-- zhTW quest_template_locale translations, consolidated (base fill + English/mixed-content fixes + Wowhead-sourced mechanical pass + Wowhead TW batch fill for previously-untranslated bracket-title rows)
DELETE FROM `quest_template_locale` WHERE `ID` = 1 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1, 'zhTW', '亞歷山大的任務', 'Welcome to the world of Alexander craft. Please try to not break the windows.  $B$BSeek out the fallen crest in the land of icy wastes. There incant the spell of a forgotten age, wallowing in the teeming mists of life. $B$B <<Do Not Localize>>', '找到被遺忘的位置，並且施放魔幻法術。', '', '去找Dragon Spawn。', '想起你的天賦', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2, 'zhTW', '沙普塔隆的爪子', '強大的角鷹獸沙普塔隆已經被你殺死了，它的爪子成為你勝利的象徵。碎木崗哨的塞娜尼·雷心一定會對你的戰利品感興趣的。', '將沙普塔隆的爪子交給梣谷碎木崗哨的塞娜尼·雷心。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5, 'zhTW', '饑腸轆轆的基特斯', '我已經困在這個鬼鎮裡好幾個星期了，除了蟲子和野草之外什麼吃的都沒有!我想吃點正常的食物，即使要多花點錢也無所謂。找點美食來給我，我會給你大筆的報酬。我聽說夜色鎮血鴉旅店的格魯奧廚師做的黑蟹蛋糕很不錯……', '和格魯奧廚師談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6, 'zhTW', '加瑞克·護足的賞金', '加瑞克·護足，幾週以來這個惡棍一直讓我們的農民和商人心驚膽顫，前幾天有人在農場附近的小屋裡看到了他的身影，就是在修道院東邊過了橋以後的那塊地方。提著他的頭回來領取賞金吧!$B$B不過你要小心一點，$N。加瑞克身邊總是有一幫暴徒，他可不是那麼容易搞定的傢伙。', '殺死加瑞克·護足，帶著他的頭到北郡修道院去找維里副隊長。', '', '去艾爾文森林找北郡山谷的維里副隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7, 'zhTW', '剿滅狗頭人', '你的第一個工作是去清除一些敗類，$n。一群狗頭人佔據了北邊的森林。去那裡解決所有你看到的狗頭人惡黨。減少他們的數量好讓我們有一天能把他們驅逐出北郡。', '殺死8隻狗頭人惡黨，然後向治安官瑪克布萊德覆命。', '', '到艾爾文森林的北郡修道院找治安官瑪克布萊德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8, 'zhTW', '盜賊的交易', '嘿，朋友!幫我一個忙如何?一大堆殭屍和蜘蛛實在讓我應接不暇。$B$B我手裡有一封要送到布瑞爾的信，是要送給一個名叫芮妮還是什麼的旅店老闆。別管她姓什麼啦!$B$B總之，那裡是一個舒適而溫暖的小地方，裡面都是些努力地想活在這個世界上的瘟疫受害者，當然那裡也是你休息的好去處。你應該自己去看看……如果你願意跑一趟，我會給你不錯的報酬。', '將一封筆跡潦草的信件送給在提里斯法林地的布瑞爾旅店老闆芮妮。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9, 'zhTW', '清理荒野', '看看這片土地上都發生了些什麼吧!這片土地曾為一群善良老實的農民們所有。但如今，一群該死的小賊把農民們全部趕走了。當然，除了老子我!但有些看守傀儡一直霸佔著我的田地。$B$B如果你覺著自己能夠勝任這份工作的話，我希望你能幫忙清除掉20台傀儡。完成了任務之後，記得回來拿酬勞。如果你把我這片田地上的傀儡清光了的話，就去清除旁邊田上的傀儡吧。', '農夫薩丁要求你破壞掉20台看守傀儡。', '', '去找西部荒野的農夫薩丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10, 'zhTW', '謝申克的救贖', '啊，這真是太糟糕了!我派我手下最得力的助手，初級勘探員謝申克去沙漠東南面那個叫做大裂口的地方進行探查。但是他現在失蹤了，而他最後一份報告中顯示，大裂口到處都充斥著奇怪的蟲子。該不會這片沙漠上兩大塊重要的地區都被蟲子佔領了吧?$B$B我需要你去大裂口找謝申克，求求你了!也許他已經……但請你把他的勘探設備找回來。恐怕那是可憐的謝申克唯一留下的東西了。', '尋找初級勘探員謝申克的下落，把他或者他的勘探設備交給加基森的高級勘探員菲茲杜瑟。', '', '去塔納利斯找加基森的高級勘探員菲茲杜瑟。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11, 'zhTW', '懸賞河爪豺狼人', '有人在艾爾文森林的邊界處看見了豺狼人，這些野蠻的動物在這兒肯定不會幹什麼好事。在瞭望塔南邊的樹林裡有一大群豺狼人到處遊蕩，憑我們自己的兵力很難應付他們。另一群則在東邊的石碑湖附近。$B$B任何幫忙清除這些豺狼人的勇士都會受到暴風城軍方的嘉獎。把他們的彩色豺狼人臂環帶給我以證明你殺了他們。', '帶8個彩色豺狼人臂環給兵營的瑞尼爾副隊長。', '', '去找艾爾文森林的瑞尼爾副隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12, 'zhTW', '西部荒野人民軍', '人民軍只有一個目標:保護西部荒野的安寧，並將和平帶回到這片土地上來。不幸的是，和平的代價總是以鮮血來換取的。$B$B我手下的一個斥候報告說，有一群迪菲亞捕獸者正在附近到處流竄並大肆破壞。最新的報告說他們出現在西北方的詹戈洛德礦坑中，摩森農場，以及法布隆的南瓜田。如果你想加入我們人民軍的話，那麼就先去殺死15名迪菲亞捕獸者和15名迪菲亞走私者，然後回來找我。', '哨兵嶺的格萊恩·斯托曼要你殺死15名迪菲亞捕獸者和15名迪菲亞走私者後回去找他。', '', '去西部荒野找哨兵嶺的格里安·斯托曼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13, 'zhTW', '西部荒野人民軍', '有人看見一群兇殘的迪菲亞掠取者洗劫了金海岸礦坑、月溪鎮及艾力克斯頓農場，我們人民軍絕不能對這樣的事袖手旁觀。馬上就出發吧，$n，讓聖光重新照耀西部荒野。$B$B金海岸礦坑就在哨塔西邊的海岸附近，作為訓練的第二部分，我希望你能殺死15名迪菲亞掠取者和15名迪菲亞強奪者。', '哨兵嶺的格里安·斯托曼要求你殺死15名迪菲亞掠取者和15名迪菲亞強奪者，然後回去向他報告。', '', '去西部荒野找哨兵嶺的格里安·斯托曼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14, 'zhTW', '西部荒野人民軍', '一些迪菲亞路霸最近一直在避開我們，到處作惡。根據我最信賴的斥候回報，這些迪菲亞路霸通常沿著從這裡到西部荒野南部的道路打家劫舍。我們相信他們現在應該就躲在南部的匕首丘陵，計畫著下一步的行動。以人民軍之名，去殺死那些傢伙吧!', '哨兵嶺的格萊恩·斯托曼要你殺死15個迪菲亞路霸、5個迪菲亞巡路者和5個迪菲亞拳匪，然後回去向他報告。', '', '去西部荒野找哨兵嶺的格里安·斯托曼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 15 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (15, 'zhTW', '迴音山調查行動', '$n，我的斥候告訴我說，狗頭人出沒的範圍遠大於我們的想像。一群狗頭人工人剛剛在北邊的回音山礦坑附近駐紮。$B$B到礦坑那裡，把他們都除掉。那裡至少有8隻狗頭人工人，殺了他們，看看他們的數量是否不止這麼多，完成之後向我回報。', '殺死8隻狗頭人工人，然後向治安官瑪克布萊德回報。', '', '到艾爾文森林的北郡修道院找治安官瑪克布萊德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 16 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (16, 'zhTW', '吉拉德的飲料', '', '', '', '去找暮色森林的葛拉德·提勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 17 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (17, 'zhTW', '奧達曼的蘑菇', '我聽說有一種新發現的植物叫做紫色蘑菇，它們成群的生長在奧達曼挖掘場，可以在較淺的通道或較少探索的區域找到。我正在研究它們在鍊金學上的潛力，這也是為什麼來找我。$B$B去找到那些紫色蘑菇然後幫我帶一打回來。你要小心點，這種蘑菇被擠壓時會噴射出有毒的孢子。$B$B幫我這個忙吧，可以讓你嘗嘗我收藏多年的藥劑!', '收集12顆紫色蘑菇，把它們交給塞爾薩瑪的加克。', '', '去洛克莫丹找灰爪山的加克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 18 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (18, 'zhTW', '盜賊兄弟會', '最近, 一夥新來的流寇停留在北郡一帶，為禍四方。他們自稱為迪菲亞兄弟會，向東過了河之後就能找到他們。$B$B我不知道他們聚在一起到底想要幹什麼，但我確信他們不是什麼好東西。給我帶回一些他們的紅色粗麻頭巾，我就送你一把武器作為獎勵。', '給北郡的維里副隊長帶回12個紅色粗麻頭巾。', '', '去艾爾文森林找北郡山谷的維里副隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 19 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (19, 'zhTW', '薩瑞爾祖恩', '黑石前鋒和黑石背教者經常在這裡和石望要塞之間伏擊我們，這群前鋒的指揮官是個名叫薩瑞爾祖恩的獸人。把他的頭給我帶來。', '將薩瑞爾祖恩的頭顱帶給湖畔鎮的治安官馬瑞斯。', '', '去找紅嶺山脈的治安官馬瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 20 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (20, 'zhTW', '黑石氏族的威脅', '黑石氏族穿越了燃燒平原，並且攻下了北方的石望要塞。他們以那座要塞為據點，劫掠湖畔鎮北邊的居民，全鎮的居民嚇得都不敢外出，只能躲在鎮裡瑟瑟發抖。$B$B幫湖畔鎮居民解決掉這個威脅吧。殺死黑石氏族的獸人，並且帶回十把他們所用的破斧作為證明。$B$B儘管黑石氏族是在北方威脅著我們，但我們也收到了他們在赤脊山脈東南部出現的報告。你可以在那裡找到他們，然後獵殺他們。', '帶回10把破斧給湖畔鎮的治安官馬瑞斯。', '', '去找紅嶺山脈的治安官馬瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 21 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (21, 'zhTW', '迴音山清剿行動', '你上次的調查證實，回音山礦坑需要一次清剿行動。回到礦坑那邊，幫我們清除那裡所有的狗頭人吧。$B$B抓緊時間，$n。狗頭人無所顧忌地盤踞在礦坑裡的時間越長，它們在北郡的據點也就越穩固。', '殺死8隻狗頭人苦力，然後向北郡修道院裡的治安官瑪克布萊德覆命。', '', '到艾爾文森林的北郡修道院找治安官瑪克布萊德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 22 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (22, 'zhTW', '豬肝餡餅', '削兩個洋蔥，剝一個大蒜，烤三片麵包，剁半兩香菜，切幾塊蘿蔔，熬一鍋肉醬。現在……我還需要8片豬肝來完成我的絕世美味餡餅!', '薩爾瑪·薩丁需要8片血牙野豬的肝來烹製豬肝餡餅。', '', '去找西部荒野的薩爾瑪·薩丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 23 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (23, 'zhTW', '烏薩苟斯的爪子', '強大的熊怪烏薩苟斯被你殺死了，它的爪子是你梣谷狩獵之行的戰利品。爪子上有一小塊新月形的印記，這個印記的意義對你來說還是一個謎。$B$B你應該把這只爪子交給碎木崗哨的塞娜尼·雷心，以此證明你已經殺死了這隻強大的猛獸。', '將烏薩苟斯的爪子交給梣谷碎木崗哨的的塞娜尼·雷心。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24, 'zhTW', '薩杜布拉的頭顱', '曾經敏捷而強大的薩杜布拉現在靜靜地躺在地上，你取得了最後的勝利。牠的頭顱對這次的梣谷狩獵來說是一件非常合適的戰利品，碎木崗哨的塞娜尼·雷心肯定會想要看看這件戰利品，然後對你在梣谷狩獵中取得的成績予以嘉獎。', '將薩杜布拉的頭顱交給梣谷碎木崗哨的塞娜尼·雷心。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25, 'zhTW', '冷靜一下', '你真該看看的，$c！$B$B精靈們認為銀風避難所牢不可破。擁有這樣的重裝防禦與水元素軍隊，他們的想法幾乎是正確的。$B$B幾乎。$B$B我們的一個法師成功召喚出一個扭曲變形的元素，作用是讓其他元素陷入混亂與暴怒之中。$B$B啊，看看他們臉上的表情！$B$B<塔坎大笑。>$B$B很不幸地，可以控制那個元素的法師死在戰場上了。現在我需要一個人去撂倒這個變形的元素。', '銀風避難所的塔坎隊長要你到密斯特拉湖，打敗泰德雷斯與12個污濁的水元素。', '在密斯特拉湖上的眺望台中偵查聯盟的前哨站。', '去梣谷找碎木崗哨的馬斯托克·維爾西斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 26 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (26, 'zhTW', '一堂必修的課程', '$N，看到你的進展十分順利，我非常高興。你正在不斷地努力成為自然界的保衛者，這是莫大的榮耀。現在是你深入學習更高級的變身技能的時候了，塞納留斯賦予我們特殊的能力，讓我們可以變身成為在水中行動自如的動物。所以，你必須到月光林地的永夜港去，跟塞納里奧議會的德迪利特·星焰談話。他將進一步指引你。', '與月光林地永夜港的德迪利特·星焰談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 27 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (27, 'zhTW', '一堂必修的課程', '$N，看到你的進展十分順利，我非常高興。你正在不斷地努力成為自然界的保衛者，這是莫大的榮耀。現在是你深入學習更高級變身技能的時候了，塞納留斯賦予我們特殊的能力，讓我們可以變身成為在水中行動自如的動物。所以，你必須到月光林地的永夜港去，跟塞納里奧議會的德迪利特·星焰談話。他將進一步指引你。', '與月光林地永夜港的德迪利特·星焰談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 28 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (28, 'zhTW', '湖中試煉', '第一個試煉是要搜尋月神湖底的神殿靈珠。它腐敗的很快，因此你要在找到它後，立即把它拿到雷姆洛斯神殿去。在神殿裡使用它，然後跟塔加里談談，她是月光林地裡最值得信賴的守衛之一。$B$B你的時間非常緊迫，而且還要與其他尋找靈珠的德魯伊競爭，靈敏和智慧是你取勝的關鍵。$B$B祝你好運，$N。', '在月神湖尋找神殿靈珠，把它帶到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿靈珠，然後與神殿中的塔加里談話來完成試煉。', '完成湖泊試煉', '去月光林地找月神湖的塔加里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 29 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (29, 'zhTW', '湖中試煉', '第一個試煉是要搜尋月神湖底的神殿靈珠。它腐敗的很快，因此你要在找到它後，立即把它拿到雷姆洛斯神殿去。在神殿裡使用它，然後跟塔加里談談，她是月光林地裡最值得信賴的守衛之一。$B$B你的時間非常緊迫，而且還要與其他尋找靈珠的德魯伊競爭，靈敏和智慧是你取勝的關鍵。$B$B祝你好運，$N。', '在月神湖尋找神殿靈珠，把它帶到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿靈珠，然後與神殿中的塔加里談話來完成試煉。', '完成湖泊試煉', '去月光林地找月神湖的塔加里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 30 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (30, 'zhTW', '海獅試煉', '第二個試煉是要尋找組成海獅墜飾的兩個部分。其中的一半蘊含著海獅的敏捷天性，另一半蘊含著海獅那令人難以置信的耐力。德魯伊汲取這兩種特性，將它們運用到自己的水棲形態中。$B$B與月光林地中的居民談話，找到這兩個部分，並將它們合併起來。最後把合併好的墜飾交給德迪利特·星焰。', '尋找水獸耐力墜飾和水獸敏捷墜飾。與月光林地的居民談話，找出這些東西可能被放在哪裡。$B$B在雷姆洛斯神殿附近將海獅墜飾的兩部分合而為一。$B$B將合併好的墜飾交給月光林地永夜港中的德迪利特·星焰。', '', '去月光林地找永夜港的德迪利特·星焰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 31 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (31, 'zhTW', '水棲形態', '你已經學完了掌握水棲形態所必須具備的所有知識，現在回到雷霆崖的圖拉克·符文圖騰那兒去吧。把墜飾拿給他看看，以此證明你已準備好接受新的知識。他會讓你掌握變化為水棲形態的訣竅，讓你在水中靈活自如。$B$B再見，年輕的德魯伊。我們會再見面的。', '回到雷霆崖，讓圖拉克·符文圖騰看看你的海獅墜飾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 32 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (32, 'zhTW', '異種蠍的威脅', '這是我要你去遞送的報告，馬上把它送到能夠對其內容有深入瞭解的那些人的手中。$B$B我知道一個名叫基爾茲賓·鼓眼的巨魔學者，他致力於研究卡林多大陸上的那些與艾澤拉斯生態格格不入的生物形態；他簡直是一本活的生物書！如果你想要知道我們面臨的是怎樣的威脅，以及如何解決這個威脅，那就把這份報告交給他吧，我們現在需要一切可以得到的説明。$B$B基爾茲賓應該住在奧格瑪暗巷區的第二層。', '把報告帶給奧格瑪的基爾茲賓·鼓眼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 33 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (33, 'zhTW', '林中的群狼', '這些狼群所感染的病毒無論怎麼也揮之不去。隨著日子一天一天過去，生病的狼群數量增加了。請人撲殺這些野生動物，對我來說是個痛苦的決定，但是我們必須在疫情擴大之前，趕快殺掉這些染病的幼狼。$B$B殺掉山谷中染病的幼狼，並且把牠們的皮帶來給我，作為你行動的證據。', '帶8片染病的狼皮交給北郡修道院外的伊根·派特斯金納。', '', '到艾爾文森林的北郡山谷找伊根·派特斯金納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 34 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (34, 'zhTW', '不速之客', '前幾天我的花園又被搞得一塌糊塗，不過我已經知道是哪個混蛋幹的了。就是被治安官馬瑞斯先生稱作「貝利格拉布」的那隻野豬。$B$B你瞧!在下一季來臨之前，我都不能種我的水仙花了。全毀了!一切都被那隻混蛋野豬給毀了!幫我除掉那個禍害!把它的獠牙帶回來給我，我會付給你酬勞的。它平常就在湖畔鎮西南的田邊閒逛，但有時候也會跑進我的花園裡來。', '湖畔鎮的瑪蒂·詹羅斯要求你殺死貝利格拉布，並帶回它的獠牙作為證明。', '', '去找紅嶺山脈的瑪蒂·詹羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 35 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (35, 'zhTW', '衛兵湯瑪斯', '如果你擔心關於魚人的傳言可能屬實的話，就去一趟艾爾文森林東部的橋邊和衛兵湯瑪斯談談吧。他最近一個星期都駐紮在那裡，應該很瞭解那個地區的情況。搞清楚事態之後，把他的報告帶給我。', '治安官杜漢要你和衛兵湯瑪斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 36 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (36, 'zhTW', '西部荒野燉肉', '我從來沒有想過有一天會被迫離開我的農莊。但是現在，那些滿是小賊和強盜的田地對我們來說已經是太過危險了。等法布隆修好他的車之後，我們就要逃離這裡了。$B$B或許你能幫我一個小忙?先讓我把我的獨家絕活西部荒野燉肉的食譜給抄下來，然後你幫我把它交給薩爾瑪·薩丁。薩丁農場就在路口的另一邊。', '弗娜·法布隆要求你將她的西部荒野燉肉食譜交給薩爾瑪·薩丁。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 37 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (37, 'zhTW', '失蹤的衛兵', '幾天前，我派了衛兵羅爾夫和馬拉凱沿著河流去偵察這一帶的情況，但我們到現在還沒回來。我得先弄清楚這二個人發生什麼事情才能完成我的報告。沿著河流往北走，找到他們……或是他們的屍體。', '衛兵湯瑪斯要你沿著河岸向北走，尋找兩個失蹤的衛兵羅爾夫和馬拉凱。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 38 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (38, 'zhTW', '西部荒野燉肉', '來幫我完成這道西部荒野燉肉!幫我找到這些材料:$B$B3塊禿鷹肉$B$B3個血牙野豬的鼻子$B$B3顆魚人的眼睛$B$B3棵秋葵', '薩爾瑪·薩丁需要3塊禿鷹肉、3個血牙野豬的鼻子、3顆魚人的眼睛和3棵秋葵。', '', '去找西部荒野的薩爾瑪·薩丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 39 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (39, 'zhTW', '傳遞湯瑪斯的報告', '把羅爾夫和馬拉凱的死訊告知治安官杜漢，向他報告說，靠我們現在的部隊根本無法遏制住這些在東部艾爾文森林的魚人。我知道我們的兵力很短缺，但是希望杜漢可以找到些人手。', '到閃金鎮去向治安官杜漢報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 40 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (40, 'zhTW', '魚人的威脅', '$N，艾爾文森林又遇到新的威脅了!魚人正陸續從東艾爾文森林的河流裡遊過來，把魚嚇跑了之外，還攻擊平民!我曾經向治安官杜漢提出警告，不過他顯然更擔心那些豺狼人和強盜，而且他不相信魚人能有多危險。請你和杜漢談談吧，$N，說服他派遣更多的部隊到東邊來!', '雷米要你去和閃金鎮的治安官杜漢談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 45 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (45, 'zhTW', '羅爾夫的下落', '進一步檢查這個地區之後，你發現有蹼狀的腳印沿著石碑湖岸向東延伸。在東邊較遠處，你隱約看見有一個魚人村落。也許羅爾夫的命運就在那裡劃下了句點……', '到魚人村去尋找羅爾夫，或是他死亡的証明。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 46 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (46, 'zhTW', '懸賞魚人', '暴風城軍隊懸賞清除那些艾爾文森林內的魚人潛伏者和魚人強奪者。殺了它們，把它們破損的魚人鱗片給我帶回來，暴風城軍隊會獎勵你的。$B$B魚人在北面的石碑湖附近建造了一座村莊，另外在南面的溪流分叉處還有一座村莊。', '給艾爾文森林東部的橋邊的衛兵湯瑪斯帶去8個破損的魚人鱗片。', '', '去找艾爾文森林的衛兵湯瑪斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 47 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (47, 'zhTW', '金砂交易', '這一帶的狗頭人有時會帶著金砂出來活動。我真的很需要這些金砂……給我找一些來，我會以鎮子裡最高的收購價格買下來─最高的價格!', '幫閃金鎮的雷米收集10袋金砂，你可以從艾爾文森林的狗頭人身上找到金砂。', '', '去找艾爾文森林的雷米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 48 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (48, 'zhTW', '琥珀酒', '高高的葡萄樹生長在南方$B$B蜿蜒的清泉流過樹根旁$B$B純淨的宛如女神的眼淚$B$B你快點去給我弄來聖泉水!', '帶聖泉之水給葛林布茲·雷酒。', '', '去找西部荒野的葛林布茲·雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 49 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (49, 'zhTW', '琥珀酒', '琥珀的顏色是我畢生之愛$B$B就像天邊夕陽下的雲彩$B$B為了它的誕生呀，勇敢的少年我召喚你$B$B我要一袋黑麥、大麥和玉米!', '葛林布茲·雷酒需要大麥、黑麥和玉米各一袋。', '', '去找西部荒野的葛林布茲·雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 50 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (50, 'zhTW', '琥珀酒', '我搗！我攪！我搗！我攪！$B少了玩意就沒法搞好$B我要一種夠硬的金屬來當罐兒$B給我弄些真銀來，我就唱完歌兒！', '葛瑞姆·雷酒需要一些真銀。', '', '去西部荒野找匕首嶺的葛瑞姆·雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 51 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (51, 'zhTW', '琥珀酒', '還沒過濾但是剛剛蒸餾$B就像是新皮甲還沒上油$B然後得燒它七八斤炭呀$B我說你趕緊動身去辦呀！', '帶給葛瑞姆·雷酒一枝楓樹枝。', '', '去西部荒野找匕首嶺的葛瑞姆·雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 52 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (52, 'zhTW', '保衛邊境', '你好，$N。離開閃金鎮越遠，在森林裡遇到的野生動物就越兇猛。東谷伐木場幾乎每天都要受到狼和熊的攻擊!$B$B我們非常需要你的幫助。', '殺掉8隻覓食的灰狼和5隻年幼的森林熊，然後回到東艾爾文森林的橋邊去找衛兵湯瑪斯。', '', '去找艾爾文森林的衛兵湯瑪斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 53 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (53, 'zhTW', '琥珀酒', '甜美的液體清澈如嬰兒淚$B百年的陳釀色深如琥珀$B但在把它放進地窖存著前$B造個橡木大桶來盛著先！', '給葛瑞姆·雷酒帶去一捆燒焦的橡木。', '', '去西部荒野找匕首嶺的葛瑞姆·雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 54 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (54, 'zhTW', '去閃金鎮報到', '$N，你已經被證實是一位非常關心北郡安全的$c了。現在我要派你去保衛艾爾文森林的周邊地區。$B$B如果你接受這個任務，就把這些文件送到閃金鎮的治安官杜漢手裡。沿著向南的大道走，穿過北郡的關卡就能看到閃金鎮了。', '將治安官瑪克布萊德的文件帶給閃金鎮的治安官杜漢。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 55 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (55, 'zhTW', '摩本特·費爾', '摩本特·費爾的老巢就在一個可以俯視烏鴉嶺墓園的山頂上。他的日子就快要到頭了……$B$B殺掉他，讓我們不被他的邪惡所侵害。為我復仇吧，也為了夜色鎮的人民!', '對摩本特·費爾使用摩本特的剋星，殺掉他，然後把摩本特的剋星交給斯溫。', '', '去找暮色森林的斯溫·猶根。', '殺死了摩本特·費爾', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 56 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (56, 'zhTW', '守夜人', '作為守夜人的指揮官，我發過誓要保衛夜色鎮人民的安全。暴風城已經把他們駐守在這裡的部隊撤了回去，現在我們只能依靠自己了。$B$B如果你覺得可以勝任這份工作，就請幫助我們吧!到夜色鎮南部的靜謐花園去，殺掉8個骷髏戰士和6個骷髏法師。我們必須儘量減輕這些不死生物所帶來的威脅!', '夜色鎮的指揮官奧瑟·埃伯洛克要你去殺掉8個骷髏戰士和6個骷髏法師。', '', '去暮色森林找夜色鎮的指揮官奧爾希雅·埃伯洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 57 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (57, 'zhTW', '守夜人', '$N，我收到報告說有不死生物在森林裡出沒!如果你能應付的話，就到烏鴉嶺的大墓地去殺15個骷髏魔和15個恐怖骷髏。另外，就在夜色鎮南部的靜謐花園墓場一帶也都發現有骷髏出沒。我們一定要把這些不死生物趕出暮色森林!', '指揮官奧瑟·埃伯洛克要你去殺死15個骷髏魔和15個恐怖骷髏。', '', '去暮色森林找夜色鎮的指揮官奧爾希雅·埃伯洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 58 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (58, 'zhTW', '守夜人', '烏鴉嶺的形勢仍然十分嚴峻，夜色鎮的安全繫在你的手上，$N。我沒有足夠的人手來保衛夜色鎮的安全。你必須再次到烏鴉嶺去除掉20個在東部的墓裡的瘟疫食屍鬼。', '夜色鎮的指揮官奧瑟·埃伯洛克要你到烏鴉嶺的東部陵墓去殺20個瘟疫食屍鬼。', '', '去暮色森林找夜色鎮的指揮官奧爾希雅·埃伯洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 59 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (59, 'zhTW', '布甲和皮甲', '為了表彰你的智慧和勇敢，我把這個標記給你，用在護甲上應該很不錯。你把它交給東谷伐木場的薩拉·迪博雷恩，她會為你做件合適的護甲。這件護甲在你為保衛艾爾文森林作戰時應該用得到。$B$B東谷伐木場就在衛兵湯瑪斯所在的哨所的東面。', '把暴風城護甲標記交給薩拉·迪博雷恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 60 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (60, 'zhTW', '狗頭人的蠟燭', '你好，$g親愛的先生:尊貴的女士;!你有時間嗎?$B$B我和我兄弟在暴風城開了間藥店，我現在正在這一帶收集些大蠟燭，以便提取其中的蠟。你能幫助我嗎?$B$B你可以在狗頭人的身上找到大蠟燭，我聽說在艾爾文森林的礦坑一帶有很多狗頭人……在南邊的法戈第礦坑和東邊的玉石礦坑裡也有不少。我建議你去這兩個礦坑裡看看。', '幫閃金鎮的威廉·匹斯特收集8支大蠟燭。', '', '去找艾爾文森林的威廉·匹斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 61 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (61, 'zhTW', '送往暴風城的貨物', '我兄弟摩根正在暴風城等我送蠟燭過去，但我實在忙得抽不開身。如果你願意把這批貨物送過去給他，他會重金酬謝你的。$B$B我已經把蠟燭裝好了，你可以在暴風城貿易區的匹斯特藥劑店找到摩根。', '把威廉的貨物送給暴風城貿易區的摩根·匹斯特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 62 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (62, 'zhTW', '法戈第礦坑', '出問題的還不止北郡的礦坑!我接到報告說艾爾文森林的法戈第礦坑已經成了狗頭人的天堂。$B$B去那裡查看一下這些報告是否屬實，然後回來告訴我。法戈第礦坑就在閃金鎮的正南方，斯通菲爾德農場和馬科倫農場之間。', '調查法戈第礦坑，然後回到閃金鎮去見治安官杜漢。', '偵察法戈第礦坑', '去找艾爾文森林的治安官杜漢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 63 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (63, 'zhTW', '水之召喚', '沿著銀松森林海岸前行，在瑟伯切爾的西邊有一處被瘟疫玷汙過的神殿。那裡的水靈不再和我們交談，你的任務就是消滅那個汙染源並淨化那個水池。$B$B將元素護腕和剩餘的泉水放置在火盆上，就可以進行召喚水靈的儀式了。$B$B把能夠證明你完成了任務的證據帶回來給我，然後我就會給你圖騰。', '擊敗墮落的水之魂，把墮落水之魂的護腕和剩餘的最純淨的水放在銀松森林的聖泉火盆上。', '', '去銀松森林找北流海岸的聖泉火盆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 64 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (64, 'zhTW', '遺失的傳家之寶', '太可怕了!弗娜一聽到田裡的騷動就把我叫醒了。田裡全都是小流氓。我們只能連夜逃出來，結果我就把我的懷錶給忘在家裡了。那隻懷錶是弗娜的爸爸在我們結婚那天送給我的，我可不想讓它落在那些盜賊手裡。我把那隻錶放在小農舍的衣櫃裡，就在西邊的那片南瓜田邊上─不可能找不到的。如果你能把它拿回來給我，我會對你感激不盡的!', '農夫法布隆希望你能幫忙找回他的懷錶。懷錶放在西邊南瓜田旁邊的農舍衣櫃裡。', '', '去找西部荒野的農夫法布隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 65 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (65, 'zhTW', '迪菲亞兄弟會', '那群自稱為迪菲亞兄弟會的流寇賊子將我們這些善良的平民趕離西部荒野，他們一定要為自己的罪行負責!我要求你去打探一下，我們必須知道到底誰是他們的頭兒，還有他們都藏在哪兒。在湖畔鎮的旅館裡有個叫威利的小賊以前欠了我一個人情，你可以找他幫忙。到艾爾文森林東邊的赤脊山去吧，湖畔鎮就那座山的腳下，到那裡去碰碰運氣。', '格里安·斯托曼要求你去和湖畔鎮的威利談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 66 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (66, 'zhTW', '斯塔文的傳說', '昨夜，一陣突如其來的不安掠過我的全身，我感到我的孫女艾莉莎正處在巨大的危機中。我用紙牌進行占卜，結果「死神」這張牌在桌上凝視著我。在長時間的沉思之後，我找到了這個可怕而神秘事件的一點線索，有一個名字浮現在我的腦中，那就是「斯塔文」。到城鎮大廳裡去找書記員達爾塔吧，看看你能否得到更多關於斯塔文的資訊……我擔心包括你我在內的所有人都有危險。', '去夜色鎮大廳找書記員達特利。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 67 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (67, 'zhTW', '斯塔文的傳說', '斯塔文?讓我查查鎮裡的記錄。$B$B斯塔文...斯塔文...讓我找找...啊，找到了!這裡有份斯塔文·密斯特曼托的檔案。記錄上最後地址是在月溪鎮的學校裡。哎呀，都是過時的東西了!$B$B朋友，你能幫我個忙嗎?如果你碰巧路過月溪鎮的話，也許能找到一些有關這個傢伙的新消息，別忘了告訴我一聲，好讓我更新檔案。', '到月溪鎮的學校尋找關於斯塔文的新資訊，給書記員官達特利。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 68 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (68, 'zhTW', '斯塔文的傳說', '你在舊手提箱裡找到了一封覆滿灰塵的信。', '把覆滿灰塵的信交給書記官達特利。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 69 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (69, 'zhTW', '斯塔文的傳說', '哎呀!我上次肯定漏掉這個了。斯塔文檔案中的第一個地址下面還有另一個地址，這個地址被擦掉了一部份。看起來他好像去閃金鎮的獅王之傲旅店了。去那裡查查看吧，$n。', '到獅王之傲旅店去問問那裡的人，看看他們是否聽說過斯塔文這個人。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 70 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (70, 'zhTW', '斯塔文的傳說', '斯塔文這個名字讓我想起點什麼…哦，我想起來了!$B$B很多年前的一個雷雨交加的夜晚，有個信差到這兒來借宿。快到午夜12點的時候，他一邊尖叫著一邊從樓上跑下來，蒼白的臉上滿是惶恐的神情，最後他穿著睡衣消失在傾盆的大雨中。$B$B由於走得太匆忙，他忘了拿走樓上箱子裡的信。他後來也沒有再回來拿走。其中一封就是那斯塔文寫給一個住在暴風城運河區的朋友的信，你自己拿去看吧。', '從箱子中拿走斯塔文未寄出的信，把它送到暴風城的運河區。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 71 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (71, 'zhTW', '回覆湯瑪斯', '把你找到的兩塊勳章交給橋邊的衛兵湯瑪斯，讓他知道兩個衛兵的死訊。', '把羅爾夫和馬拉凱的勳章交給艾爾文森林東部橋邊的衛兵湯瑪斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 72 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (72, 'zhTW', '斯塔文的傳說', '我父親從前是這幢宅子的管家，在那場大屠殺之後，他費了好大的工夫才把地上的血跡清乾淨，不過這跟我們要談的事情沒什麼關係。弗林特雷家的基金早就用光了，現在家裡最後的財產也都已經準備要拍賣掉了，那些像禿鷹一樣貪婪的徵稅官!你要是真想找些什麼資料，不妨在這堆垃圾裡找找看，天知道你能找到什麼。', '在打包的東西裡尋找線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 73 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (73, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 74 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (74, 'zhTW', '斯塔文的傳說', '你在木箱裡找到了幾樣東西:一些有霉味的、看起來像是傳家寶的東西，一副家庭肖像畫，一些打獵所得的戰利品和幾本舊書。在木箱底部的一個花瓶下面，你找到了一頁破損的日記。', '你找到的這張被撕破的日記書頁又提供了你一個線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 75 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (75, 'zhTW', '斯塔文的傳說', '我剛搬進來的時候發現樓上的箱子裡有一捆羊皮紙，我想看看那些羊皮紙上寫了什麼，但是我的視力卻讓我只能看到一團迷濛。$B$B幫我這個快瞎了的老人一個忙吧，去檢查一下樓上箱子裡的東西，看看有沒有什麼有關那個斯塔文的資訊。我記得有一頁褪色的日記，你肯定會對它感興趣的。把它拿過來，我會盡力幫助你的。', '治安官哈迦德要你從樓上的箱子裡找出一頁褪色的日記。', '', '去艾爾文森林找東谷伐木場的治安官哈迦德。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 76 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (76, 'zhTW', '玉石礦坑', '感謝你，我們現在可以知道法戈第礦坑確實被狗頭人佔據了。現在我們還需要一個人去更遠處的玉石礦坑偵察。$B$B去查看一下玉石礦坑，確定那裡是否有狗頭人。向東沿著大路走，一直走到阿祖拉之塔，然後往北走就會看到山腳下的礦坑。', '查看玉石礦坑，然後回到閃金鎮去向治安官杜漢報告。', '偵察玉石礦坑', '去找艾爾文森林的治安官杜漢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 77 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (77, 'zhTW', '收集蜜糖', '我這裡有德蘭·杜佛斯需要的包裝材料。我會幫助你為瑪爾頓那煩人的老爸包裝他要的蜜糖……不過你得給我多帶幾瓶蜜糖回來。它們就在靠近隱匿石一帶，在那座荒廢掉的部落村莊的箱子裡，可惡的泥漿怪和軟泥怪霸佔了那塊地方，有傳言說它們是由一些大型軟泥怪領導著的。但不管怎麼樣，你必須找到蜜糖並把它們帶回來讓我進行包裝。', '從隱匿石一帶被部落廢棄的基地中的箱子裡找到10瓶辛特蘭蜜糖。', '', '去辛特蘭找拉普索迪營地的基沃拉丁·獵日者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 78 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (78, 'zhTW', '斯塔文的傳說', '我知道有誰可以幫你。我以前帶領暴風城衛隊的時候，經常去夜色鎮的血鴉旅店喝酒。那兒的老闆史密茲對當地的情況瞭若指掌。把這張東西給他，看看他有什麼看法。', '把褪色的日記內頁帶給旅店老闆史密茲。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 79 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (79, 'zhTW', '斯塔文的傳說', '多年來我一直在追尋這個斯塔文的消息。幾年前那些來訪的貴族被殺之後，我曾和哈迦德一起去調查。我發現了這些沾滿淤泥的日記，但是一直沒有辦法把這上面的筆跡和樹林裡的那個瘋子聯在一起。你提供的線索證明了他的罪行。趕快把這個交給指揮官奧瑟·埃伯洛克，告訴她你所發現的一切。', '把沾滿淤泥的日記內頁交給指揮官奧瑟·埃伯洛克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 80 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (80, 'zhTW', '斯塔文的傳說', '有一段時間我一直注意著斯塔文這個討厭的傢伙。如果這些東西都是他寫的，那就足以給他定罪了。$B$B書記員達爾塔多年以來一直負責著鎮裡的檔案，他很擅長辨認筆跡。把這張紙給他，看看是否和檔案裡面斯塔文的簽名筆跡相吻合。', '把染血的日記書頁交給書記員達爾塔。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 81 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (81, 'zhTW', '送回蜜酒', '我在德蘭要的東西上花了好大的工夫，因為除了額定裝進桶裡的蜜酒之外，他還要求額外再加幾瓶！雖然我對德蘭這個傢伙的評價並不是很高，但是這世上沒有比往酒桶裡死命塞瓶子更糟的事情了……你來得正是時候。$B$B現在把這個桶送到德蘭·杜佛斯那裡去，他在奧格瑪那裡自己開了一家店。順便代我向瑪爾頓問好，我很希望能有機會再和他暢飲幾杯。', '把桶交給奧格瑪的德蘭·杜佛斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 82 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (82, 'zhTW', '腐化之巢', '好吧，你的報告中提到了蟲子……我們現在知道的是……它們正使得原本是腐化之巢所在區域的水池變得乾涸，其它方面我們一無所知。$B$B首先我們要搞清楚敵人到底是誰！你得去腐化之巢那裡，把那些蟲子的肢體帶回來給鍊金師匹斯特蘇格研究，這樣我們就可以確定到底是誰在那裡搞鬼了！', '從腐化之巢找5個森提帕爾昆蟲肢體，把它們交給加基森的鍊金師匹斯特蘇格。', '', '去塔納利斯找加基森的鍊金師匹斯特蘇格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 83 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (83, 'zhTW', '紅色亞麻布', '北郡的迪菲亞盜賊戴的是粗麻布頭巾，而艾爾文森林的迪菲亞盜賊戴的則是亞麻布做的，我可以用這些亞麻布做些不錯的東西。$B$B給我些亞麻布頭巾，我就可以做點什麼給你。$B$B迪菲亞盜賊在整個艾爾文森林地區都有營地。', '帶去6塊紅色亞麻布頭巾給東谷伐木場的薩拉·迪博雷恩。', '', '去艾爾文森林找東谷伐木場的薩拉·迪博雷恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 84 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (84, 'zhTW', '回去找比利', '這是你要的餡餅。把這東西交給那個比利的時候，別忘了告訴他我希望他吃了噎死!', '把豬肉餡餅帶給馬科倫農場的比利·馬科倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 85 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (85, 'zhTW', '遺失的項鍊', '我的項鍊不見了，一定是那個討厭鬼比利·馬科倫拿走的!他總是像隻老鼠一樣在東邊的馬科倫農場裡竄來竄去。請把我的項鍊拿回來給我，讓我這可憐的寡婦得到一些安慰吧。', '和比利·馬科倫談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 86 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (86, 'zhTW', '比利的餡餅', '給我吃點餡餅，也許我就能想起來是誰拿走項鍊了。我知道另一個農場裡的波尼斯老太太做的豬肉餡餅很好吃……$B$B我們的農場周圍有野豬，如果你能給她找幾塊野豬肉，她就應該會給你烤一塊餡餅。', '帶4塊野豬肉給斯通菲爾德農場的波尼斯·斯通菲爾德姑媽。', '', '去找艾爾文森林的波尼斯·斯通菲爾德姑媽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 87 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (87, 'zhTW', '金牙', '我在法戈第礦坑旁邊玩的時候，好像不小心弄掉了那條，呃……我是說我看見了老太太的那條項鍊。別問我它怎麼會跑到那兒去……和我沒有關係!$B$B不管怎樣，我看到一個很壯碩，鑲著金牙的狗頭人……撿起項鍊跑到礦坑裡了。你去找那個狗頭人吧，我發誓，你肯定能在他身上找到項鍊的!', '把波尼斯的項鍊帶給斯通菲爾德農場的波尼斯·斯通菲爾德。', '', '去找艾爾文森林的波尼斯·斯通菲爾德姑媽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 88 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (88, 'zhTW', '公主必須死!', '布拉克威爾一家有一頭得過獎的豬，它名叫「公主」。這頭母豬巨大無比，還經常偷偷溜到我的農場裡偷吃我的蔬菜!$B$B在它再次糟蹋了我的農場之前……必須把它給宰了!把它的項圈帶回來證明你殺了它，我會給你一些獎賞的!$B$B公主一般在布萊克威爾南瓜田出沒，那個南瓜田就在東邊，比馬科倫農場還要往東。在它肚子餓了之前殺死她，然後再回來告訴我!', '殺掉公主，把它的項圈帶給斯通菲爾德農場的斯通菲爾德媽媽。', '', '去找艾爾文森林的斯通菲爾德媽媽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 89 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (89, 'zhTW', '止水湖上的橋', '上次獸人入侵的時候，我們被迫把所有能找到的鐵都熔了來製造子彈、刀劍和盔甲。我們向暴風城請求援助，讓他們運一些材料過來。誰料一群赤脊山豺狼人劫持了這批貨物，並逃進了湖畔鎮後的山中。$B$B這樣一來，我們這座橋的重修工程馬上就要面臨缺少材料的困境了。如果你能給我帶回5根鐵矛和5個鐵鉚釘，我一定會獎勵你的。$B$B快點去吧!', '帶5根鐵矛和5個鐵鉚釘給湖畔鎮的工頭奧斯洛。', '', '去找紅嶺山脈的工頭奧斯洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 90 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (90, 'zhTW', '烤狼肉串', '烤狼肉串是道家喻戶曉的美食!我當然可以為你做一些，不過得先有材料。給我找些暴風城特製調味料和10塊狼肋排。這兒的森林裡遍地都是狼，想找點肋排肯定不是問題。至於調味料，你得到暴風城運河區的花店裡去找菲利希亞·加姆。', '收集10塊狼肋排和1份暴風城特製調味料，再回夜色鎮去找格魯奧廚師。', '', '去暮色森林找夜色鎮的廚師格魯奧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 91 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (91, 'zhTW', '所羅門的律法', '暴風城的敵人在赤脊山東側的山腳下建立了一片營地，這個無賴利用秘術不斷的對我們小鎮及人民傳播著恐懼和悲痛。莫甘斯，就是這群惡徒的首領。$B$B他控制了影皮豺狼人氏族，讓那些邪惡的野獸為他賣力。根據湖畔鎮的法律規定，救助王國的罪犯是可以被判處死刑的。$B$B這些骯髒的豺狼人一定要被處死!$B$B交10個影皮墜飾回來給我，你就可以得到獎勵。', '帶回10個影皮墜飾給湖畔鎮大廳的拜里弗·科納徹爾。', '', '去找紅嶺山脈的拜里弗·科納徹爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 92 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (92, 'zhTW', '赤脊山燉肉', '沒什麼能比烹製赤脊山燉肉更讓我高興的事了，但是現在有個小問題。自從獸人們出現之後，我就得沒日沒夜地忙著給暴風城軍隊的整整一個旅供應食物，我的食品櫃早已是空空如也了。如果你能給我找來一些材料的話，我很樂意給你做點好吃的。$B$B只要給我帶來5塊硬禿鷲肉，5個巨型血牙野豬頭和5份香脆蜘蛛肉就行了。', '湖畔鎮的廚師布雷納想要5塊硬禿鷲肉，5個巨型血牙野豬頭和5份香脆蜘蛛肉。', '', '去找紅嶺山脈的廚師布雷納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 93 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (93, 'zhTW', '黑蟹蛋糕', '我可以告訴你一個小秘密─黑「蟹」蛋糕實際上是用蜘蛛腿做的!我知道這聽起來有點噁心，不過這種蛋糕的味道絕對芳香美味而且是很好的點心!幫我找點黏糊的蜘蛛腿來，我很快就能做好給你。$B$B我聽說結網毒蜘蛛身上很容易拿到這種東西─它們的巢穴就在北邊，在山丘和小河之間。', '收集6條黏糊的蜘蛛腿，把它們交給夜色鎮的廚師格魯奧。', '', '去暮色森林找夜色鎮的廚師格魯奧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 94 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (94, 'zhTW', '法師的眼線', '我的對手莫甘斯是個強大而邪惡的法師，他就住在赤脊山的伊爾加拉之塔里。我已經找到了一種監視他的方法，只要通過阿祖拉之眼，就可以在很遠的地方看到他的一舉一動。$B$B不過要研究他的思想……我還需要進一步的幫助。$B$B如果你願意的話，就帶著這個雕紋到伊爾加拉之塔去，把它放置在塔旁邊的獅子雕像身上。$B$B完成之後，阿祖拉雕紋就會告訴我們，莫甘斯又在準備什麼邪惡的計畫。', '把阿祖拉雕紋放置到赤脊山伊爾加拉之塔旁邊的獅子雕像身上。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 95 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (95, 'zhTW', '斯溫的復仇', '我原來在東南部的一座農場裡工作……直到有一天，從逆風小徑來的黑騎兵洗劫了我的農場，趁我不在的時候殺了我的全家!我回來時發現有個模糊的人影在我家的穀倉附近埋了一件什麼東西，可惜我沒能抓住他。我也不敢在這裡繼續逗留，因為我害怕會有黑騎兵追蹤我。直到現在，我都都不知道那人到底藏了什麼。如果你能去找出真相，我一定會感激你的。那人埋東西的地方就在我的穀倉附近的一個老樹樁後面。', '到斯溫的農場去找出埋在老樹樁後面的是什麼東西。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 96 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (96, 'zhTW', '水之召喚', '拿著碎片，拿著碎片……賦予生命。$B$B賦予生命……理解生命，理解水就是生命本身……而墮落則會扼殺生命。$B$B你保護了生命，並將水的力量賦予了生命……', '把水靈碎片交給貧瘠之地的水之先知伊斯倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 97 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (97, 'zhTW', '斯塔文的傳說', '$N，趕快回報指揮官埃伯洛克，這兩個筆跡完全符合!她的懷疑是正確的!', '把這個消息告訴指揮官埃伯洛克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 98 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (98, 'zhTW', '斯塔文的傳說', '斯塔文·密斯特曼托是個惡貫滿盈的罪犯，很多無辜的人都死在他手中。毫無疑問，他犯下了無數宗的罪案，現在這個瘋子威脅到夜色鎮了。天知道這個惡棍又在策劃什麼邪惡的行動。斯塔文的家就在小鎮北邊，$C，為我一勞永逸，去把他就地處死吧。$B$B完成以後把他的家族戒指交給艾娃夫人作為證明，畢竟是她的預感才讓我們發現這個可怕的兇手，因為她夜色鎮才能更安全。', '幹掉斯塔文·密斯特曼托，把他的家族戒指交給艾娃夫人。', '', '去暮色森林找夜色鎮的艾娃夫人。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 99 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (99, 'zhTW', '阿魯高的愚行', '在我對阿魯高的魔法越來越瞭解的同時，我對這個蠢貨的鄙視與輕蔑也日益加深。我已經快要完成對他所謂的「拯救行動」研究。$B$B在我瞭解到底是什麼樣的巫術導致了焚木村的奇怪現象之後，我就算是完全瞭解透徹了。白天，那些農民們都是好端端的人。但太陽一下山，他們就變成了月怒狼人。$B$B我需要從阿魯高給他們戴上的附魔鐐銬中汲取一些能量。帶6副焚木鐐銬來給我， $N 。', '帶6副焚木鐐銬給瑟伯切爾的達拉爾·織曦者。', '', '去銀松森林找瑟伯切爾的達拉爾·織曦者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 100 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (100, 'zhTW', '水之召喚', '你吟誦完了咒語，瞬時間火盆便放出了萬丈光芒。水滴和火焰接觸時的噼啪聲越來越弱，你可以感覺到籠罩在周圍的墮落氣息已經被消滅了。', '和銀松森林的水之魂談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (101, 'zhTW', '懲罰圖騰', '有一股神秘而邪惡的勢力在森林裡蔓延，我們必須更加小心地保護自己，$N。風兒悄悄的告訴我，他們說有一個很巨大的危機正在不遠的將來耐心地等候著你。$B$B尊貴的$c，如果你想保護自己，就帶10顆食屍鬼的牙齒、10根骷髏的手指和5瓶蜘蛛毒液來給我。我會為你製作一個懲罰圖騰，讓那些企圖傷害你的敵人自食惡果。', '收集10顆食屍鬼的牙齒、10根骷髏的手指和5瓶蜘蛛毒液，把它們交給夜色鎮的艾娃夫人。', '', '去暮色森林找夜色鎮的艾娃夫人。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (102, 'zhTW', '西部荒野的巡邏', '暴風城已經把我們給遺棄了。一股腐朽與墮落的狂風正肆虐在西部荒野的平原之上。這裡是我的故鄉，我絕對不會背叛那些和我一樣堅持留在這裡的民眾們。我們這些農夫必須站出來，為自己贏得生存的空間。$B$B若你願意接受我們派給你的任務，就去巡視西部荒野的草原吧。找到那些可惡的狗頭人，把它們除掉，這些傢伙似乎與死亡礦坑裡的小賊們有些聯繫。帶八隻豺狼人的爪子回來給我，我會獎勵你的英勇行為的。', '帶8隻豺狼人的爪子給哨兵嶺的丹努文隊長。', '', '去西部荒野找哨兵嶺的丹努文隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 103 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (103, 'zhTW', '火炬的守護者', '燈塔管理員一家被殺的那一個晚上實在是太可怕啦!我只能眼睜睜地看著老瞎眼帶著那群魚人毀了他們全家，但卻幫不上任何忙。但過去的事就讓它過去吧，我現在關心的是無盡之海中那些正把船隻駛近暗礁水手們的生命。如今，維持著燈塔上火炬不熄滅的任務就落在我一個人身上了。$B$B幫我從那些收割機器人身上找來5瓶燈油吧，這樣我才能讓火炬繼續照亮下去。', '帶回5瓶燈油給西部荒野燈塔中的葛瑞森船長。', '', '去找西部荒野的葛瑞森船長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 104 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (104, 'zhTW', '海岸上的威脅', '當我的生命終結在了那片岩石上之後，我根本不知道死後的世界會是怎樣的。那天晚上的燈塔一片漆黑，因為老瞎眼嚇跑了管理員全家。他們後來又回來想要點亮燈塔，但是老瞎眼迫使一群意志薄弱的魚人突襲了燈塔。這一次，管理員全家沒那麼幸運了，他們都在我面前無助地死去。$B$B如果你在海岸邊看到老瞎眼的話，就殺死它，把它的鱗片帶一片回來給我，我會獎勵你的。', '將老瞎眼的鱗片交給西部荒野燈塔旁的葛瑞森船長。', '', '去找西部荒野的葛瑞森船長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 105 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (105, 'zhTW', '啊，安多哈爾!', '啊，進攻安多哈爾並徹底擊敗那個巫妖的時刻終於來臨了!$B$B這個城市的廢墟內就是巫妖 - 『召喚者』阿拉基統治的地方。無數的天譴軍團守護在城中心的廢墟周圍，而他的貼身隨扈守衛更是令人畏懼。你需要帶眾多的盟友前往才可能有機會成功挑戰它。$B$B消滅阿拉基，$N，從它的骨匣裡拿出一塊裂片來，作為你獲勝的證據!', '把阿拉基的骨匣裂片交給西瘟疫之地亡靈壁壘的高級執行官德靈頓。', '', '去找提裏斯法林地的高級執行官德靈頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 106 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (106, 'zhTW', '年輕的戀人', '天哪，我太痛苦了!我愛上了湯米·喬·斯通菲爾德，但我們兩家卻有著不共戴天的仇恨。所以我不能去見他，可是我無時無刻不在想念那張英俊的臉孔啊!$B$B請你把這封信交給湯米·喬，他一般會在斯通菲爾德農場西邊的河流附近，他們的農場就在這裡的正西方。', '送梅貝爾的情書給湯米·喬·斯通菲爾德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 107 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (107, 'zhTW', '給威廉·匹斯特的信', '我相信威廉·匹斯特有瓶藥水，可以撮合這兩個年輕人!$B$B把這張字條拿給威廉，他現在正住在閃金鎮的獅王之傲旅店。', '把斯通菲爾德老奶奶的字條交給威廉·匹斯特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 108 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (108, 'zhTW', '<TXT> Mystery Reward', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 109 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (109, 'zhTW', '向格里安·斯托曼報到', '看起來你參加過不少戰鬥，$c。如果你還沒有去格里安·斯托曼那裡報到的話，就趕快去吧。他是人民軍的領袖，這是個專門負責保衛西部荒野的人民軍組織，我敢說你是能幫他一些忙的。一般來說，你可以在哨兵嶺的石塔周圍找到他，那地方就在西部荒野中部的路邊上。', '去和格里安·斯托曼談一談，他一般就在哨兵嶺的石塔旁，這座石塔位於西部荒野中部地區的路邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 110 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (110, 'zhTW', '昆蟲研究', '我要去看看謝申克的勘探裝置……然後把他的東西整理一下。我預感到我們將會遇到更大的麻煩。$B$B我想讓你去見見鍊金師匹斯特蘇格，瞭解一下他的研究是否有進展。如果他有什麼新的發現，你就儘快向我回報。', '到加基森的鍊金師匹斯特蘇格那裡去了解關於昆蟲的研究有沒有新的進展。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 111 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (111, 'zhTW', '跟湯米的祖母談話', '求求你，$N，去和我的奶奶談一談吧。如果要找個能有辦法讓我和梅貝爾在一起的人的話，一定是奶奶。她就在我們家的屋子裡。', '和斯通菲爾德農場的斯通菲爾德老奶奶談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 112 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (112, 'zhTW', '收集海藻', '我可以為梅貝爾配製一種隱形液，這樣她就可以悄悄溜出馬科倫葡萄園去見湯米·喬。不過我需要一些水晶海藻來配製這種藥水。$B$B水晶海藻一般生長在海裡……不過有時候魚人也會收集它們。去看看水晶湖附近的魚人身上有沒有海藻，水晶湖就在閃金鎮的東邊。', '收集4片水晶海藻葉，給閃金鎮的威廉·匹斯特。', '', '去找艾爾文森林的威廉·匹斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 113 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (113, 'zhTW', '昆蟲研究', '高級勘探員菲茲杜瑟必須儘快看到這份報告。實際上……每個人應該知道這件事的重要性：我們正面臨著一個巨大的威脅，這個威脅不僅僅涉及到塔納利斯和加基森，如果不及時控制的話，整個卡林多大陸的南部地區都會有麻煩！甚至整個艾澤拉斯大陸都會捲入其中。而且這個威脅顯然不會就此平息。$B$B讓菲茲杜瑟把這份報告給你複製幾份，然後你去把它廣為傳播。一定要讓所有人都知道這個威脅的存在！', '把這份報告帶給加基森的高級勘探員菲茲杜瑟，讓他按照鍊金師匹斯特蘇格的要求為你複製一份報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 114 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (114, 'zhTW', '偷跑', '把隱形液交給梅貝爾·馬科倫。它的隱形效果應該可以持續到她見到湯米·喬。', '把隱形液交給梅貝爾·馬科倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 115 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (115, 'zhTW', '暗影魔法', '黑石氏族的獸人在赤脊山脈的侵略行動得到了暗影施法者的支援，他們帶著一種具有強大黑暗力量的器具—午夜寶珠。這些寶珠對赤脊山脈的防衛者們造成了巨大的傷亡，並迫使我們放棄所有在戰鬥中被這種寶珠污染了的物品。$B$B殺掉這些黑石暗影施法者，把他們身上的午夜寶珠拿回來給我。我會把他們妥善地處理掉，還這世界一片清淨!', '帶3個午夜寶珠給湖畔鎮的治安官馬瑞斯。', '', '去找紅嶺山脈的治安官馬瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 116 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (116, 'zhTW', '旱季', '我最近真是感覺有點沒勁，$N。這些酒瓶子都快空了，運酒的船也很久沒來了，這都怪那些該死的獸人。$B$B也許你幫我一個小忙?$B$B我希望你能從住在西部荒野的葛林布茲·雷酒那裡搞一桶雷霆啤酒，從暴風城搞一桶葡萄酒，從夜色鎮搞一瓶月光酒，還有還有，再從閃金鎮搞一袋蜂蜜酒來。把這些好酒都給我弄來，我會重重謝你的。', '湖畔鎮的酒吧老闆丹尼爾需要一桶雷霆啤酒，一桶葡萄酒，一瓶月光酒，還有一袋蜂蜜酒。', '', '去找紅嶺山脈的酒吧老闆丹尼爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 117 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (117, 'zhTW', '雷酒', '快點，朋友，動作要快$B釀出更多的酒來賣$B喝酒的人多吃菜的人少 $B想要釀酒就得要有蛇麻草。', '帶5束蛇麻草給葛林布茲·雷酒以完成他的特製啤酒。', '', '去找西部荒野的葛林布茲·雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 118 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (118, 'zhTW', '馬蹄鐵的價值', '我用了很多的鐵用來打造暴風城衛兵的裝備，結果沒有足夠的鐵來打馬蹄鐵了!$B$B把這封信帶給閃金鎮的鐵匠阿格斯，信上說明了我現在的情況，並向他要一批馬蹄鐵過來。', '把弗納的字條交給閃金鎮的鐵匠阿格斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 119 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (119, 'zhTW', '回覆弗納', '好，我會給他50套馬蹄鐵……$B$B就在這裡，你看，全部都打包好了，隨時可以帶走!告訴弗納，我很高興和他做生意，哦，對了，提醒他看清楚木箱上的字條!', '回去赤脊山找弗納·奧斯古，把馬蹄鐵交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 120 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (120, 'zhTW', '送往暴風城的信', '這真是段難熬的日子呀，$c。獸人的攻勢沒完沒了，如果援軍還不來的話，湖畔鎮就要保不住了!我現在委託給你的這封信是非常重要的。立刻將這份報告送給暴風城的馬庫斯·喬納森將軍。你把信送到了那邊之後，就馬上帶著那邊的消息回來，無論是好消息還是壞消息，我都要儘快知道。$B$B現在就出發吧，快去快回!', '所羅門鎮長要求你給暴風城的馬庫斯·喬納森將軍送一封信，並且在完成任務之後儘快回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (121, 'zhTW', '送往暴風城的信', '在我等待國王陛下的回應時，我希望你能把這封信交給所羅門鎮長。$B$B解散，$c!', '將馬庫斯·喬納森將軍的回信帶給湖畔鎮的所羅門鎮長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (122, 'zhTW', '幼龍的腹鱗', '我需要一些黑色幼龍腹部的鱗片來支付從阿格斯那裡買馬掌的錢。如果你能幫我搞到6塊鱗片的話，在付給阿格斯一些以後……我還能用剩下的給你做點好裝備。$B$B黑色幼龍經常在湖畔鎮南方遊蕩，獵殺它們的時候要多加小心。', '從小黑色幼龍身上收集6片幼龍的腹鱗，把它們交給赤脊山的弗納·奧斯古。', '', '去找紅嶺山脈的弗納·奧斯古。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (123, 'zhTW', '收貨人', '這是一張日程表，記錄了某個人被稱作「收貨人」的人在某天某時會收到從艾爾文森林的礦坑運來的一車黃金。$B$B根據日程表所述，這個收貨人好像就住在艾爾文森林東部的布萊克威爾南瓜田附近。$B$B這件事非常重要，你必須向閃金鎮的治安官杜漢報告。', '去閃金鎮找治安官杜漢，把收貨人的交易日程表交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (124, 'zhTW', '豺狼人的咆哮', '有一群整天攻城的獸人好像還不夠!最近又來了一群豺狼人蠻卒和秘法師，鬼鬼祟祟地在我的馬場北邊的山脊上遊蕩，而且還偷我走失的馬……$B$B如果你能把這些豺狼人都除掉的話，我和我的馬都會感謝你的。', '殺掉10名赤脊山蠻卒和8名赤脊山秘法師，然後回來找弗納·奧斯古。', '', '去找紅嶺山脈的弗納·奧斯古。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (125, 'zhTW', '遺失的工具', '我本來可以在這兒大幹一場的, $N。可是，我的工具還沒運到，由於這個小鎮被包圍了，我們很難得到外面來的補給。我本來託人從閃金鎮把工具用馬車運過來，可是橋被炸斷了，我們只好改用船運，結果那船又被獸人的投石車給打沉了。不過，我運氣不錯，我的工具箱沒壞，只是沉進了湖底。$B$B幫我把工具箱找回來吧，$N，我會付給你相當不錯的酬勞的。', '湖畔鎮的工頭奧斯洛希望你幫他找回沉入止水湖底的工具箱。', '', '去找紅嶺山脈的工頭奧斯洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (126, 'zhTW', '山中的嚎叫', '$N，那些豺狼人還在那裡!我還能聽見他們在湖畔鎮周圍的山區裡打獵時發出的嚎叫聲。其中有一個聲音喊得最響─那是猶勒，他們的頭目。$B$B幹掉猶勒，把牠的手下都給轟走!把牠的爪子給我帶回來。$B$B不過你得小心點，這傢伙能當上他們的頭目自然是有兩把刷子的。猶勒可不是個低能的混血豺狼人的……', '將猶勒的爪子帶回給湖畔鎮的弗納·奧斯古。', '', '去找紅嶺山脈的弗納·奧斯古。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (127, 'zhTW', '賣魚', '止水湖之所以出名都是因為它的班點太陽魚。它們總是供不應求……可是我這裡的存貨已經不夠了!$B$B幫我帶回10條魚來，我會好好酬謝你的。哦，如果你不會捕魚的話……可以從魚人那兒搶來!', '帶10條斑點太陽魚給湖畔鎮的碼頭管理員巴倫。', '', '去找紅嶺山脈的碼頭管理員巴倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (128, 'zhTW', '懸賞:黑石氏族', '我們一定得摧毀黑石氏族。這群強盜入侵了我們的土地，佔據了本應屬於暴風王國的群山。根據線報，在他們的氏族中，每個分隊的首領都被稱為「勇士」，你可以很容易的在北方的營地中找到他們。就在通向燃燒平原的道路西邊。$B$B所羅門鎮長希望能把這群卑鄙邪惡的傢伙通通消滅。去殺死15名黑石勇士，然後回來向我覆命。', '殺死15名黑石勇士，並向湖畔鎮的衛兵豪威覆命。', '', '去找紅嶺山脈的衛兵豪維。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (129, 'zhTW', '免費的午餐', '你能幫我一個小忙嗎?我給衛兵派克準備好了午飯，可是他出去巡邏了……他是一個又高又壯的暴風城衛兵。他在外面是能自己保護自己的，可是像我這樣的尋常市民就不行了，$B$B所以呢，如果你能幫我把他的午餐帶給他的話，我也給你一份免費的午餐!派克就在通往暮色森林的路上巡邏。', '將衛兵派克的午餐帶給他，他就在通向夜色鎮的路上巡邏。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (130, 'zhTW', '拜訪草藥師', '你回去找達希的時候，能替我帶幾朵花給她嗎?你可以在湖畔鎮西邊的草藥店裡買到花。$B$B不過，你去買花的時候……千萬別告訴瑪蒂這花是誰買的，也別說是要送給誰的……', '找到草藥師瑪蒂·詹羅斯並和她談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 131 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (131, 'zhTW', '水仙訴衷情', '這是你要的花。我為你選了水仙，這是我最喜歡的花兒!', '將水仙花送給達希。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 132 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (132, 'zhTW', '迪菲亞兄弟會', '我現在可是冒著生命危險在和你說話。迪菲亞那幫人也是聽命於某個神秘人士，我上次聽說他們與許多種族都有過合作，豺狼人，狗頭人，甚至還有哥布林。$B$B把這張字條交給斯托曼。上面寫著我所知道的關於迪菲亞兄弟會的一切。', '將威利的字條交給西部荒野的格萊恩·斯托曼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 133 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (133, 'zhTW', '食屍鬼假人', '我住得離鎮上太遠了，根本得不到保護。那些食屍鬼和疆屍沒把我吃掉簡直就是個奇跡!其實昨天還有一群噬骨者來敲擊我的牆壁!$B$B我想要做個假人，一個用來嚇唬食屍鬼的「稻草人」。我需要一些食屍鬼的肋骨來製作這個假人。你可以從食腐者、噬骨者、食腦者、腐爛者和瘟疫食屍鬼身上拿到這東西。$B$B給我帶足夠的肋骨來，我會給你一些獎賞的。', '收集7根食屍鬼的肋骨，然後把它們交給亞伯克隆比。', '', '去找暮色森林的亞伯克隆比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 134 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (134, 'zhTW', '巨魔盜賊', '幾個星期前，我離開家去遠處採草藥，有一群巨魔襲擊了我!我落荒而逃的時候丟棄了一箱珍貴的工具和草藥。$B$B這些巨魔在把我趕跑之後，就大搖大擺地回到了暮色森林南邊的巨魔丘上，我的木箱肯定就在那一帶。$B$B請幫幫我吧，$N，我很需要這個木箱，請你一定要幫我拿回來。', '把亞伯克隆比的木箱拿回來給他。', '', '去找暮色森林的亞伯克隆比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 135 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (135, 'zhTW', '迪菲亞兄弟會', '我現在很想知道威利所提到的「石匠」是什麼意思，或許這只是一個口誤?石匠公會跟迪菲亞真的有聯繫嗎?原來只有暴風城軍情七處的首領馬迪亞斯·肖爾才知道真相。把威利的字條拿給他，看看他對這個越來越大的謎團有什麼想法吧。如果你找不到他，就去舊城區的兵營看看吧。', '將威利的字條交給暴風城的馬迪亞斯·肖爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (136, 'zhTW', '桑德斯船長的寶藏', '如果你讀到這封信的話，那就意味著我，桑德斯船長，已經長眠在深深的水底了。所以，只要按照我的線索去做，我的寶藏就是你的了。首先你必須要找到我的手提箱，它應該就在西部荒野西邊海岸的某處船隻殘骸旁，如今應該八成都埋在沙裡了。海岸邊有許多處船隻的殘骸，但只有一隻沉船旁有個鏽掉的錨。找到錨你就找到箱子了!在箱子裡面，你可以找到下一條線索。', '找到桑德斯船長的手提箱，在箱子中尋找下一條線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 137 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (137, 'zhTW', '<NYI> <TXT> Stormwind Commendation', 'If you earn a commendation from one of our Marshals, then bring it to me.  It will be good for one of our Lion Emblem gloves.', 'General Marcus Jonathan in Stormwind will accept a commendation from Elwynn Forest.  Bringing him such a document will reward you with a choice of armor.', '', '去暴風城找英雄谷的馬庫斯·喬納森將軍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 138 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (138, 'zhTW', '桑德斯船長的寶藏', '字條上寫著:做得好，兄弟!現在你可以開始向東走，到懸崖邊的路旁好好找找，看看有沒有一處廢棄的煙囪，你可以在那裡找到藏著下一個線索的舊木桶。', '找到廢棄煙囪旁的舊木桶，在桶裡尋找下一條線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 139 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (139, 'zhTW', '桑德斯船長的寶藏', '仔細搜索了木桶了之後，你發現了一小片羊皮紙。上面寫著:現在，從桶這裡轉向北，像烏鴉飛翔一般絕不回頭，一直走到你看見了海邊懸崖上的風車為止。找到那風車旁的一個空水罐。仔細檢查那個水罐，你就可以找到你要找的東西了。', '在風車旁的一個空水罐裡尋找下一條線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 140 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (140, 'zhTW', '桑德斯船長的寶藏', '顯然，在這個舊罐子中藏著另一個有關桑德斯的寶藏線索。紙上有幾處墨水已經變得模糊不清，而且泛著一股威士忌的味道，不過你還是能從中辨認出這樣的字跡:看來你找到我的威士忌瓶子了，你離我的寶藏已經很近啦!只要向西走到海邊，然後一直向西游，你就可以找到藏著我的寶箱的那座島啦!', '找到桑德斯船長的箱子並打開它，取得你的獎勵。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (141, 'zhTW', '迪菲亞兄弟會', '過去的石匠公會是由一個名叫艾德溫·范克里夫的人所經營的。第一次獸人戰爭結束後，范克里夫承接下了在獸人們留下的廢墟上重建暴風城的重任。很顯然的，范克里夫對國王陛下在重建工程完成之後給予他們的待遇非常不滿意。這也許只能解釋其中一些事情。$B$B我已經寫了一份詳細的說明，要讓你拿到西部荒野交給你的老大。趕快拿去給他吧!', '將肖爾的報告交給西部荒野的格萊恩·斯托曼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (142, 'zhTW', '迪菲亞兄弟會', '我們必須找出迪菲亞兄弟會的巢穴。$N，我的斥候報告說，迪菲亞幫的信差經常出現在月溪鎮、金海岸礦坑和詹戈洛德礦坑之間的路上。我希望你能抓住他，要是他試圖反抗，就把他殺了，然後把他身上所有的東西帶回來。', '追蹤西部荒野的迪菲亞信差，並將他身上攜帶的信件交給斯托曼。', '', '去西部荒野找哨兵嶺的格里安·斯托曼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (143, 'zhTW', '送往西部荒野的信', '暴風城的軍隊似乎遇到了些麻煩事，他們早就該到這裡增援了，但直到現在還連個人影都沒有。我們沒多少時間可供浪費了!我不能再這樣坐視人民繼續無謂地犧牲而不去要求更多的增援。我聽說西部荒野組建了一支民兵部隊。$B$B把這封信帶給他們的領袖格里安·斯托曼。或許斯托曼的人在國王陛下的部隊到達之前能來幫忙抵擋上一陣。', '所羅門鎮長要求你給西部荒野的格里安·斯托曼送一封信。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (144, 'zhTW', '送往西部荒野的信', '所羅門鎮長的信讓我感到心痛。但顯然他並不知道西部荒野的戰事也很吃緊，要是他知道的話，可能就不會對民兵團的援助抱有任何期望了吧。如果暴風城不是對西部荒野的人民也不聞不問的話，我們也不會需要民兵團的。$B$B將這封回信帶給你在赤脊山的主人吧，$c。請轉告他，我的心也因為那麼多勇士的犧牲而感到十分沉重。', '將格萊恩·斯托曼的回信帶給所羅門鎮長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (145, 'zhTW', '送信到夜色鎮', '看來我又有事要麻煩你了。我寫了封信給艾羅·埃伯洛克領主，請求他派出他的精銳部隊─暮色森林守夜人─來協助湖畔鎮的防務。這封信必須馬上送去給他，你在旅途中要多加小心。埃伯洛克是夜色鎮的鎮長，那座小鎮就在暮色森林中，不要離開道路的範圍。', '所羅門鎮長要求你送一封信給夜色鎮的埃伯洛克領主。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 146 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (146, 'zhTW', '送信到夜色鎮', '如果不是和所羅門鎮長私交甚密的話，我一定會以為他是個瘋子的。因為暴風城拒絕出兵援助，就讓我把守夜人部隊派去湖畔鎮?守夜人部隊就是因為暴風城這片土地被邪惡的魔法入侵時卻遺棄我們，所以才被建立起來的。如果我把他們派離這裡的話，恐怕還沒等到他們走出這片森林，這裡就會被邪惡的勢力徹底吞沒。$B$B把這封回信帶給你在湖畔鎮的主人吧。', '將埃伯洛克領主的回信送回去給所羅門鎮長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 147 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (147, 'zhTW', '獵殺收貨人', '如果這個「收貨人」是私自從我們的礦坑裡開採黃金的話，那麼他就是在偷竊王國的金庫!把他就地正法，然後把他的交易日程表上提到的戒指帶給我。也許這枚戒指能告訴我們這個「收貨人」是在為誰工作……$B$B那張交易日程表上說「收貨人」就藏在布萊克威爾南瓜田裡，你應該到那兒去找他。', '找到「收貨人」並將他殺掉，然後帶著收貨人的戒指回來見治安官杜漢。', '', '去找艾爾文森林的治安官杜漢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 148 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (148, 'zhTW', '來自夜色鎮的補給', '哦，一個可憐的老人家還能做什麼呢?我需要從夜色鎮弄點補給品，不過路途太遙遠，我又太老了……實在是走不動啊。$B$B你能去夜色鎮幫我拿點鬼魂的髮絲回來嗎?你可以向艾娃夫人要這東西，她的家就在夜色鎮的廣場旁。', '和艾娃夫人談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 149 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (149, 'zhTW', '鬼魂的髮絲', '有個可憐的亡魂叫盲眼瑪麗，她總是在夜色鎮南部山丘上的一間農宅裡出沒。$B$B拿著這把鬼魂之梳，去讓盲眼瑪麗用它梳頭。然後再把梳子拿回來，我可以從上面收集到需要的鬼魂的頭髮。$B$B小心點，那個屋子附近潛伏著一些可怕的東西……', '把鬼靈之梳帶給盲眼瑪麗。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 150 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (150, 'zhTW', '魚人偷獵者', '魚人們開始變成了一個問題。大群的魚人漁民在止水湖沿岸下錨撒網，都快把湖裡的魚撈光了!我們得在他們把湖裡的魚都吃光之前把他們趕走!$B$B去獵殺那些魚人!帶8片魚人的鰭回來給我，我會獎勵你的。', '帶8片魚人的鰭回來給湖畔鎮的碼頭管理員巴倫。', '', '去找紅嶺山脈的碼頭管理員巴倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 151 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (151, 'zhTW', '可憐的老布蘭契', '可憐的老布蘭契呀!我們讓牠承擔的工作實在是太多了，看來牠已經要累垮了。雖然我在離開農場以前就餵過牠，可是誰會料到馬車會在半路上壞掉呢?如果你能從田裡替牠拿幾捧燕麥的話，我會對你感激不盡的。我想你可以在西部荒野所有的農場邊找到燕麥，不過你首先要將周圍那些可怕的機器人先除掉。這裡的西南邊就有幾個農場。', '西部荒野的弗娜·法布隆要你帶８捧燕麥給她。', '', '去找西部荒野的弗娜·法布隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (152, 'zhTW', '海岸的威脅', '你或許已經注意到海岸邊有許多船隻的殘骸。無盡之海確實是非常凶險，我們必須保持西部荒野海岸線的淨空，只有這樣水手們才能安全地找到靠港的路線。這些魚人實在是很麻煩，$B$B去殺死7名魚人獵潮者、7名魚人戰士、7名魚人神諭者，還有7名魚人灘行者，完成任務之後到我這裡來領取獎賞。', '殺死7名魚人獵潮者、7名魚人戰士、7名魚人神諭者，還有7名魚人灘行者，然後回去找西部荒野燈塔中的葛瑞森船長。', '', '去找西部荒野的葛瑞森船長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 153 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (153, 'zhTW', '紅色皮甲頭巾', '我們與迪菲亞兄弟會的戰局總是瞬息萬變。最近我一直在監視著他們的活動，根據長期觀察的結果，我發現他們的成員都戴著一種特殊的紅色皮頭巾。$B$B幫我帶15條這種頭巾回來吧，我會給你獎勵的。', '帶15條紅色皮甲頭巾回來給哨兵嶺的斥候加里安。', '', '去西部荒野找哨兵嶺的斥候加里安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (154, 'zhTW', '歸還梳子', '不!!!!!$B$B把它拿走，快把這個梳子拿走!$B$B我是個怪物，不會再有人說我好看了!', '把鬼魂的梳子拿回去給夜色鎮的艾娃夫人。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 155 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (155, 'zhTW', '迪菲亞兄弟會', '這麼說，斯托曼就派了你這麼一個骨瘦如柴的，$r，來保護我?看來你有得努力了，你最好再叫上幾個朋友幫忙比較保險。$B$B你知道你要做些什麼吧?我會帶你到迪菲幫的藏身之地，而你呢，就得好好保護我。當然，你最好離我近一點，越近越好。現在全迪菲亞兄弟會的人都想要我的腦袋呢。要是他們看見我和你在一起，一定會把我給宰了的。$B$B等你和你的朋友如果有準備好的話，就來跟我說一聲吧。', '護送迪菲亞叛徒前往迪菲亞兄弟會的秘密藏身處。一旦迪菲亞叛徒把你帶到范克里夫和他的手下的藏匿地點之後，儘快回去向格萊恩·斯托曼彙報相關資訊。', '護送迪菲亞叛徒找出范克里夫的藏身處', '去西部荒野找哨兵嶺的格里安·斯托曼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 156 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (156, 'zhTW', '收集腐敗之花', '如果你能幫我找些腐敗之花來，我就可以釀造很多殭屍汁。$B$B這種花全長在奇怪的地方，聽說在恐怖骷髏和骷髏魔的頭骨裡可以找到……不過至今我還沒有親眼見過!$B$B烏鴉嶺墓園裡有很多這樣的骷髏，你可以在尋找腐敗之花的時候順便把他們幹掉，夜色鎮的人民會感激你的。', '收集８個腐敗之花，然後交給夜色鎮的旅店老闆史密茲。', '', '去暮色森林找夜色鎮的旅店老闆史密茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 157 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (157, 'zhTW', '幽靈的髮絲', '這是你要的線，$N。它的用途不勝枚舉，比如用來束縛邪惡的亡魂，或者給沒有生命的東西注入生命。', '把鬼魂的髮絲交給亞伯克隆比，他住在烏鴉嶺墓園北邊的房子裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 158 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (158, 'zhTW', '殭屍汁', '我需要一瓶叫做殭屍汁的飲料。夜色鎮血鴉旅店的老闆史密茲應該有些存貨。$B$B請動作快點，最近晚上寒風刺骨，我得來點殭屍汁，好讓我的血液重新沸騰起來。', '和旅店老闆史密茲談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 159 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (159, 'zhTW', '送交殭屍汁', '這是你要的殭屍汁……$B$B小心一點，這東西強得足以把死人給弄活過來。', '把殭屍汁交給烏鴉嶺墓園北方小屋裡的亞伯克隆比。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (160, 'zhTW', '給鎮長的字條', '請把這張字條交給夜色鎮的艾羅·埃伯洛克鎮長。$B$B我和他是老朋友了……我敢說，當他讀完信，並且知道了你為我做的事情……他一定會和我一樣高興的!哈哈哈哈!', '把亞伯克隆比的信交給夜色鎮的艾羅·埃伯洛克鎮長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (161, 'zhTW', '黑暗危機逼近', '如果我的懷疑沒錯的話，這是某種火藥粉末。我們應該找個爆破專家來分析一下這到底是什麼東西，才知道我們到底面對的是什麼。阿胥蘭·暗石就在丹莫德和薩多爾大橋一帶負責那裡的警戒工作，我需要你儘快去找他，這是一段重要而危險的旅程，$N。$B$B穿過奧加茲隘口，沿著穿過潮濕之地的道路一直到丹莫德去找阿胥蘭。記住我的忠告:沿著大路走，不要停下腳步!', '首席工程師辛德維爾要你把怪味粉末交給丹莫德的爆裂物專家阿胥蘭·暗石。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 162 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (162, 'zhTW', '異種蠍的威脅', '我希望你儘快把這份報告送到對處理此類事件有經驗的人手裡。$B$B我知道有一位名叫格拉希娜·靈風的夜精靈學者，她致力於研究卡林多大陸上那些與艾澤拉斯的普通生物截然不同的生物形態，她簡直就是一本活的生物書！如果你想要知道我們面臨的是怎樣的威脅，以及如何解決這個威脅，那就把這份報告交給她吧，我們現在急需她的幫助。$B$B我聽說她住在達納蘇斯的月亮神廟裡。', '把報告帶給達納蘇斯的格拉希娜·靈風。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 163 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (163, 'zhTW', '烏鴉嶺', '烏鴉嶺出了點問題，$n。卡洛爾信誓旦旦的說在那邊的房子裡有某個人─或者某個東西─出沒。有兩個晚上，他發現有個身影在活動，第三個晚上，某扇窗戶裡還透出了燈光。$B$B你如果真的關心暮色森林的安危，就去查查看看到底是什麼樣的怪物在烏鴉嶺搞鬼。', '查出是什麼東西在烏鴉嶺搞鬼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (164, 'zhTW', '給斯溫的物資', '你認識斯溫嗎?謝天謝地，終於有人能幫我了!斯溫和他的同伴在暮色森林的西北邊有個營地。$B$B不幸的是，他們的人手太少了，少到派不出人回鎮裡來取一些必需的補給品。你能把這些物資送給斯溫嗎?', '送補給物資給斯溫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 165 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (165, 'zhTW', '隱士', '有個老人經常會到鎮裡來買東西，不過我已經有些日子沒見過他了。如果我沒記錯的話，他就住在一個可以俯瞰烏鴉嶺墓園的小屋裡。也許你該去看一看是不是出了什麼事?', '去烏鴉嶺墓園附近的小屋查看老人的情況。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (166, 'zhTW', '迪菲亞兄弟會', '你只剩下最後一個任務需要去完成。我們必須除掉艾德溫·范克里夫。雖然對一個活生生的人宣判死刑實在令我非常難過，但為了西部荒野人民的利益，我不得不讓范克里夫永遠安息。當你完成這件事之後，就把他的頭帶來給我。', '殺死艾德溫·范克里夫，把他的頭交給格里安·斯托曼。', '', '去西部荒野找哨兵嶺的格里安·斯托曼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (167, 'zhTW', '我的兄弟……', '那時我們正在西部荒野的一個大礦坑中工作，就是那個隱藏在月溪鎮的穀倉底下的礦坑……沒人知道當時那些可惡的盜賊是那從那裡出現的。總之礦道突然坍塌了，我逃了出來……可是其他人……就再也沒聽到過其他人的下落了。$B$B你看起來運氣可能會比我們好一點。如果你能幫我找到我弟弟的話，我會非常感謝你的。他總是戴著他的探險者協會徽章。如果你找不到他的話，那塊徽章至少還能給我帶來一些安慰……', '將工頭希斯耐特的探險者協會徽章帶回去給暴風城的維爾德·薊草。', '', '去找暴風城的維爾德·薊草。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (168, 'zhTW', '收集記憶', '我的許多朋友都在那次可怕的礦坑倒塌中送掉了性命。如果你的冒險正好需要到月溪鎮的那個礦坑的話，請幫忙留意一下有沒有什麼可以辨認他們身份的標誌或是物品。如果你恰巧找到他們的礦業工會會員卡的話，請一定要帶回來給我，好讓他們的家人可以明白那場恐怖的意外結果。', '找回4張礦業工會會員卡並送回給暴風城的維爾德·薊草。', '', '去找暴風城的維爾德·薊草。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 169 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (169, 'zhTW', '懸賞:加塞爾佐格', '懸賞!加塞爾佐格是黑石氏族襲擊石堡和多次劫掠湖畔鎮等行動的領導者。$B$B他是個十分危險的傢伙。根據線報，他躲藏在剛剛被他們攻陷的要塞中，謀劃著黑石氏族的下一次劫掠行動。我們必須不惜一切代價把這些在我們的國土上橫行的獸人鎮壓下去。如果有那個勇士能把加塞爾佐格的頭帶到所羅門鎮長面前的話，他將會得到重賞。', '殺死加塞爾佐格並將他的頭顱帶回來交給湖畔鎮的所羅門鎮長。', '', '去找紅嶺山脈的所羅門鎮長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (170, 'zhTW', '新的威脅', '我希望你是到這裡來助我們一臂之力的， $C 。在上一次穴居人襲擊之後，我們的人手就明顯不夠了。$B$B我聽說他們現在已經遍佈我們的國土，看來寒脊山谷也不例外。東南部的山區和湖畔已經到處都是穴居人的身影了。$B$B糟糕的事情還不只是這些，幾天前，他們襲擊並佔領了我們西邊的營地!$B$B我們這兒人手有些不足，小姑娘，我們需要強大的武力幫助我們趕走這些傢伙。', '巴爾林·霜錘要你去殺死6個石齶穴居人和6個壯實的石齶穴居人。', '', '去丹莫洛找寒脊山谷的巴爾林·霜錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 171 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (171, 'zhTW', '聯盟孤兒的看護者', '你的心腸真好啊，$N。我做夢都沒想到我在兒童週會這麼開心。謝謝你，我不想傷心因為發生在自己和他人身上的事，我的父輩告訴我忘記任何令人傷感的事。你知道嗎？當我長大了，我想成為向你一樣的英雄$B$B非常抱歉，是我回家的時候了，讓我們回去吧，我要告訴監護人。你是一個多麼偉大的人！', '去暴風城的教堂廣場見孤兒監護員奈丁加爾並帶上這個人類孤兒哨.', '', '去找暴風城的孤兒監護員奈丁加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 172 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (172, 'zhTW', '兒童週', '你願意幫助我們的孤兒院？太感謝你了，我的朋友。感謝你願意在兒童週的這段時間內為我們提供幫助。$B$B拿著這隻哨子，你只能在兒童週的這7天內使用它。當你使用它的時候，就可以和那些由你負責照看的孩子進行對話，再次使用就可以解散那個孩子。$B$B不管怎麼樣，$N——使用這個口哨，見一見你的小朋友！我相信孩子們一定很想見到你。', '使用獸人孤兒哨與你即將在兒童週期間照顧的孩子進行對話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (173, 'zhTW', '森林裡的狼人', '黑暗的勢力正在籠罩暮色森林，而卡爾文主人正在努力驅除邪惡，保護夜色鎮人民的安全是我們的職責。$B$B你覺得自己有能力加入我們嗎?$B$B我以前也跟你想的一樣，因為對哨所的安逸悠閒感到絕望，我投靠了卡爾文主人。如果你想要證明自己的實力，不是只靠嘴皮子說說就可以的。$B$B去找夜行織影狼人較量較量吧，他們經常在陽光樹林─陽光，哈!─和爛果園出沒。', '為夜色鎮的卡洛爾殺掉6個夜行織影狼人。', '', '去暮色森林找夜色鎮的卡洛爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 174 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (174, 'zhTW', '觀測星星', '我的地精朋友考格答應過要幫我製造一個可以用來觀察星星的裝置。除了魔法之外，我相信還有別的理由可以解釋發生在這片森林中的奇怪變化。$B$B根據考格的設計圖，我們的第一步得先去找根由手藝高超的工程師所做的青銅管。', '夜色鎮的維克托·安特拉斯要你給他一根青銅管。', '', '到暮色森林的夜色鎮找維克托·安特拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 175 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (175, 'zhTW', '觀測星星', '根據考格的設計圖，現在我還需要一個東西來反射光線。我記得有個叫瑪麗的女人因為總是戴著單眼透鏡而在這一帶人人皆知，你可以去找找她，向她借一個反光鏡。我記得她曾經住在暮色森林南部……', '找到瑪麗，說服她借給你一個反光鏡，用於維克托的計畫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 176 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (176, 'zhTW', '懸賞:霍格', '懸賞:霍格$B$B巨型豺狼人霍格，現正在艾爾文森林西南部的樹林裡遊蕩。他成功地對抗了目前為止所有追捕他的行動。$B$B暴風城已經為除去這只豺狼人設下了酬金，想得到酬金的獵手必須向閃金鎮的治安官杜漢提供殺死霍格的證據。', '殺死豺狼人霍格，把他那巨大的豺狼人爪帶給治安官杜漢。', '', '去找艾爾文森林的治安官杜漢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 177 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (177, 'zhTW', '觀測星星', '那隻單眼透鏡是我最珍貴的寶物，不過在發生了一件事情之後...我就把它丟在穀倉後面了。有個瘋狂的食屍鬼曾經在那一帶徘徊，可能是它把東西給撿走了。有人說那個邪惡的傢伙住在靜謐花園墓場。', '從瘋狂的食屍鬼那裡拿回盲眼瑪麗的單眼透鏡，把它交給夜色鎮的維克托。', '', '到暮色森林的夜色鎮找維克托·安特拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (178, 'zhTW', '塞歐克瑞圖斯的墜飾', '<你聽到某種飄渺的聲音>$B$B不要害怕。我是塞歐克瑞圖斯，艾爾文森林的阿祖拉之塔裡的高階法師。你手上拿著的墜子是影皮豺狼人和他們的主人莫甘斯用來聯絡的工具。$B$B根據這幾個月的研究，我相信我已經掌握了使用這些墜子進行通訊的方法。如果你能聽到我所說的話，就證明我的法術成功了。$B$B把這個墜子帶來給我，我會給你酬勞的。', '暗淡的影皮墜飾帶給法師塞歐克瑞圖斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (179, 'zhTW', '矮人服飾', '嘿，你是新來的吧?看來你需要些暖手的東西，對嗎?$B$B我想你應該想要一副保暖的手套。我是個熱心腸，很願意給你一副手套，不過我有個條件。$B$B你幫我弄些狼肉來，我保證你不會被凍掉手指頭。你覺得怎麼樣?', '斯登·粗臂想要8塊硬狼肉。', '', '去丹莫洛找寒脊山谷的斯登·粗臂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (180, 'zhTW', '懸賞:范高雷中尉', '懸賞:范高雷中尉$B$B惡行累累的豺狼人頭目范高雷在湖畔鎮及王國的敵人莫甘斯的指使下，帶著影皮豺狼人氏族到處為非作歹。鎮長所羅門下了命令，懸賞殺死這個萬惡的東西。將他的手掌割下來拿給鎮長，以此證明他的死亡。', '殺死范高雷中尉並將他的手掌割下，向湖畔鎮的所羅門鎮長覆命。', '', '去找紅嶺山脈的所羅門鎮長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (181, 'zhTW', '觀測星星', '根據考格的設計圖，我們還需要一種透鏡來完成整個裝置。我知道什麼地方有合適的透鏡，不過很難拿到。$B$B有個叫札克烏爾的巨魔住在暮色森林南部的土丘上，如果可以的話，你去把他的單片眼鏡拿來吧，我可以用它做成透鏡。', '在暮色森林南部的巨魔土丘上找到札克烏爾，把他的單片眼鏡帶回夜色鎮交給維克托。', '', '去暮色森林找夜色鎮的維克托·安特拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (182, 'zhTW', '食人妖洞穴', '我和我的兄弟森內爾被派來調查丹莫洛各個地區的食人妖活動情況。參議院正在忙著對付那些不知道從哪裡冒出來的穴居人，已經沒工夫再關心食人妖了。$B$B據我所知，在寒脊山谷南部山洞裡生活的食人妖們日子並不好過，所以我覺得派大批軍隊去圍剿它們是殺雞用牛刀，只要一兩支訓練有素的小分隊就已經綽綽有餘了。$B$B你也許能給我們提供些幫助吧?當然，我會對你的幫助給予一定的報酬。', '格瑞林·白鬚要你去殺掉10個小霜鬃食人妖。', '', '去找丹莫洛的格瑞林·白鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (183, 'zhTW', '獵殺野豬', '沒什麼能比得上用一整天的時間去打野豬更讓人愉快的了，對吧?不過，寒脊山谷裡的野豬太多了，你幾乎已經不可能在那裡再感受到狩獵的樂趣。你根本不需要去激怒它們，因為它們早就是怒氣衝天，隨時準備用獠牙把你拱上天了!事實上，這些過剩的野豬已經對我的日常狩獵形成了威脅。$B$B長話短說吧，如果你能幫我殺掉些野豬，我真的會非常感激你的。', '塔林·銳眼讓你去殺掉12隻小型峭壁野豬。', '', '去丹莫洛找寒脊山谷的塔林·銳眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 184 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (184, 'zhTW', '法布隆的地契', '這是西部荒野一片農田的地契，由希歐多爾·法布隆和他的妻子弗娜聯名簽署。地契背面有著潦草的字樣:$B$B「我們到法布隆家裡走了一趟，弄到了他的地契。我們覺得你可以很輕易地將其中一份偽造成自已的土地。$B$B法布隆家的人不會找我們的麻煩，我最後一次看到他們的時候，他們正準備離開西部荒野，不過他們的四輪貨車壞在路上了。」$B$B你認為法布隆夫妻倆可能會想要拿回這張地契……', '把法布隆的地契交給農夫法布隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (185, 'zhTW', '獵虎大師', '當我還只是個小女孩的時候，我的父親就開始訓練我捕獵老虎的技巧。$B$B你會發現虎崽子特別容易追蹤和獵殺。你在探險隊的營地附近很容易就能找到虎崽。$B$B讓我們來測試一下你的追蹤技巧，看看你是否能獵殺這些野獸。', '殺死10隻小荊棘谷猛虎。', '', '去荊棘谷找奈辛瓦里遠征隊營地的艾耶克·羅歐克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (186, 'zhTW', '獵虎大師', '年輕老虎是一回事，成年的猛虎又是不同的狀況了。獵殺成年的荊棘谷猛虎將會是更困難的挑戰。$B$B那些成年的大貓通常都在河岸東邊、庫爾森的營地南邊打發時間。', '獵殺10隻荊棘谷猛虎。', '', '去荊棘谷找奈辛瓦里遠征隊營地的艾耶克·羅歐克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (187, 'zhTW', '獵虎大師', '老年荊棘谷猛虎是虎群中最強壯的。死在牠利齒與巨爪之下的 $R  $C 亡魂可不只一個。$B$B如果艾耶克知道你打敗這些老虎的話，一定會興奮到發抖。數量最大的虎群就在南邊，荊棘谷海岸邊境的大裂層附近。', '獵殺10隻老年荊棘谷猛虎。', '', '去荊棘谷找奈辛瓦里遠征隊營地的艾耶克·羅歐克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 188 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (188, 'zhTW', '獵虎大師', '根據傳說，有一隻難以捉摸的母老虎...一隻強力的大貓，甚至讓成年的雄虎顯得矮小。奈辛瓦里探險隊的獵人們都沒能成功狩獵她。許多獵人在她耙一般的爪子下淪為獵物，他們的屍體在格羅姆高營地北邊的山丘腳下腐朽。$B$B他們將那野獸稱為辛達爾。$B$B你得下決心去做從來沒有 $R 做到過的事:狩獵、殺死辛達爾，並取得牠的爪掌。', '獵殺辛達爾並帶回牠的爪子。', '', '去荊棘谷找奈辛瓦里遠征隊營地的艾耶克·羅歐克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 189 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (189, 'zhTW', '血頂族的耳朵', '該死的食人妖!他們不斷的殺死我們派到叢林裡去的人!和他們的衝突已經讓我損失太多優秀的護衛了。我們的花費也因此節節上升!要我怎麼向大財主里維加茲解釋呢?$B$B是該做決定的時候了……想想看，科博克……你可不是被派到這裡來整日無所事事的……啊，有啦!你……你就是 $N ，是不是?你會幫我的，對不對?這份工作的獎勵可是很豐厚的哦!$B$B條件如下，幫我弄15個血頂食人妖的耳朵來，我會重重地酬謝你的。', '拿15個血頂食人妖的耳朵回來給藏寶海灣的科博克。', '', '去荊棘谷找藏寶海灣的科博克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (190, 'zhTW', '獵豹大師', '如果你想加入由小赫米特領導的頂尖狩獵隊，就必須先證明自己是一個能幹的獵豹高手。一開始不會太難的:先把目標放在小獵豹身上。等到你的狩獵經驗成長了以後，你自然就會找些更加危險的獵物。$B$B就從東邊開始，等你成為一個獵豹大師之後再回來找我。', '獵捕10隻小獵豹。', '', '去荊棘谷找奈辛瓦里遠征隊營地的艾爾加丁爵士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 191 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (191, 'zhTW', '獵豹大師', '最年輕的黑豹完全不是你對手。年齡稍長的黑豹，漸漸變得更強壯、更敏捷，也更難被擊敗。你必須拿牠們當下一個目標。$B$B那些較大的黑豹通常在西邊。', '獵殺10隻黑豹。', '', '去荊棘谷找奈辛瓦里遠征隊營地的艾爾加丁爵士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 192 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (192, 'zhTW', '獵豹大師', '接下來的部分可就比較困難了。豹長大之後，將會變得更加詭計多端，和牠們周遭的環境交融在一起，變得更難以察覺。這些狡猾的豹名為「深喉獵豹」，因為牠們喜歡突然從黑暗中現身...張著滿是利牙的血盆大口。$B$B如果你想證明自己是個真正的獵豹人，獵殺深喉獵豹是你唯一的方法。', '獵殺10隻深喉獵豹。', '', '去荊棘谷找奈辛瓦里遠征隊營地的艾爾加丁爵士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 193 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (193, 'zhTW', '獵豹大師', '你幾乎證明自己是一位優秀的獵豹高手了。但仍有一隻豹逃過了你的掌握。$B$B歌謠傳頌著一隻名叫巴爾瑟拉的豹。你該去試著用自己的技巧獵殺這頭強大的野獸，通常在巨魔洞穴上方的倒樹附近。$B$B將巴爾瑟拉的牙齒帶去給艾爾加丁應該足以證明你是大師級的獵豹獵人。', '取得巴爾瑟拉的牙齒。', '', '去荊棘谷找奈辛瓦里遠征隊營地的艾爾加丁爵士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 194 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (194, 'zhTW', '迅猛龍專精', '你覺得你的狩獵技術是最頂尖的?我馬上就能檢驗一下，看看你是不是在騙人。到叢林裡去殺十隻荊棘谷迅猛龍，這樣一來我們就知道你是不是所謂的王牌獵人了。$B$B至於在哪裡才能找到牠們，我是絕對不會告訴你的!追蹤野獸本身就是挑戰的一部分。', '獵殺10隻荊棘谷迅猛龍。', '', '去荊棘谷找奈辛瓦里遠征隊的赫米特·奈辛瓦里二世。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 195 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (195, 'zhTW', '追蹤迅猛龍', '現在讓我們看看你能不能應付更大的挑戰吧。深入叢林裡，去幹掉十隻殘暴的鞭尾迅猛龍。這些迅猛龍絕對比你之前對付過的還要強壯。$B$B鞭尾迅猛龍主要待在這裡的東南邊。靠近卡萊廢墟的位置。', '獵捕10隻鞭尾迅猛龍。', '', '去荊棘谷找奈辛瓦里遠征隊的赫米特·奈辛瓦里二世。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 196 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (196, 'zhTW', '迅猛龍專精', '過了這條河之後，在南邊的森林裡，棲息著一種非常狡猾的迅猛龍，當地人稱之為「叢林潛獵者」。牠們遠比你之前試著捕獵的目標更難追蹤和獵殺。獵殺十隻這種叢林潛獵者，那一定能成為你營火旁的好故事。', '獵殺10隻叢林潛獵者。', '', '去荊棘谷找奈辛瓦里遠征隊的赫米特·奈辛瓦里二世。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 197 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (197, 'zhTW', '迅猛龍獵手大師', '在回到奈辛瓦里探險隊營地之前，你得完成不可能的任務:狩獵從沒有其他獵人能夠捕捉的一隻迅猛龍。那野獸的名字叫泰希斯，牠統治了北荊棘谷東南隅。$B$B將泰希斯的爪子帶去給那個矮人獵手應該能證明你不是普通的 $R 。', '獵殺泰希斯。', '', '去荊棘谷找奈辛瓦里遠征隊的赫米特·奈辛瓦里二世。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 198 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (198, 'zhTW', '送補給物資給士兵托爾森', '嗯。沒錯，我這裡確實有件適合你做的事。目前佈署在荊棘谷北部的多倫中尉和他的部下需要我們的定期補給。$B$B由於食人妖的攻擊，這些補給物資一直沒有送出去，我得找人來幫我處理這件事。多倫的營地就在從暮色森林進入荊棘谷的道路西北方，你只要把補給品交給士兵托爾森就行了，如果他不在營地裡，那可能是他在營地的南邊巡邏。他會處理好這些東西的。$B$B提醒你，如果你失敗了的話，就得賠償我們的損失。', '將各式各樣的哥布林補給品交給士兵托爾森。', '', '去找荊棘谷的士兵托爾森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 199 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (199, 'zhTW', '黑暗危機逼近', '你取了些怪味粉末的樣品。', '回去見首席工程師辛德維爾七世，把你找到的線索交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (200, 'zhTW', '書呆子赫羅德', '既然連庫爾森都知道了這個秘密，那麼他們一定也在我們這邊安插了一個臥底。我們必須得搞明白這些機密內容是怎麼洩露出去的！$B$B托爾森在那邊的線人是書呆子赫羅德，他是庫爾森的後勤官，瞭解庫爾森的營地裡的一切事務。如果你能搞到他的筆記或者檔案什麼的話，或許我們能分析出托爾森到底是怎麼被發現的。$B$B當初，我們還跟庫爾森一起共事的時候，書呆子的辦公室是在營地裡唯一一座兩層房屋的二樓，他的檔案應該還在那裡。', '找到書呆子赫羅德的檔案。', '', '去找荊棘谷的書呆子赫羅德的檔案。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (201, 'zhTW', '調查營地', '我收到一條報告說，有一群獵人在風險投資公司營地所在的納菲瑞提湖上游建立營地。通常我根本不會在意這件事，但當我聽說小赫米特·奈辛瓦里也是那群獵人中的一員時，我改變了想法。他絕對是個構思周密的人，如果你瞭解我的意思的話，你永遠不會有把握的。$B$B你為什麼不去那片營地裡偵察一下呢， $N ，去看看他們到底想幹什麼?', '找到獵人營地並向藏寶海灣的克拉茲克報告這個營地的位置。', '找到獵人的營地', '去荊棘谷找藏寶海灣的克拉茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (202, 'zhTW', '庫爾森上校', '你一次又一次地證明了自己的能力，而你的足智多謀略似乎甚至能與庫爾森媲美。如果……如果你願意徹底投身到與庫爾森鬥爭的事業中去的話……也許你將成為我們反抗軍的救星!$B$B他就躲在那個名叫「儲藏室」的洞穴深處發號施令。你必須進入那個洞穴，幹掉他身邊的保鏢，最終把庫爾森和他的副官們都給除掉。$B$B出發吧， $N 。我們的生命與希望，如今都已經全部掌握在你的手中了。', '殺掉6名庫爾森精英和4名庫爾森副首領，並將庫爾森的頭顱交給反抗軍營地裡的多倫中尉。', '', '去荊棘谷找反抗軍營地的多倫中尉。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (203, 'zhTW', '以彼之道還施彼身', '我們正在與庫爾森進行一場艱難的戰鬥。他是個非常優秀的戰術大師，而且他的手下士兵的數量是我們的十倍!如果我們想要勝利的話，就必須使用他擅長的戰術來對付他。$B$B到他在東邊設立的營地裡去，殺掉他的士兵，越多越好，然後在增援趕來之前撤退。', '殺死15名庫爾森叢林戰士，然後向反抗軍營地的尤瓦中士覆命。', '', '去找荊棘谷反抗軍營地的尤瓦中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (204, 'zhTW', '庫爾森的藥物', '要想和庫爾森搏上一搏，我們就必須削弱他們的醫療隊伍。他在那裡聚集了大批醫療人員，他們能用密林藥劑治療自己的部隊，並用毒草汁液對我們的人下毒。$B$B我們要用這些藥物來治療我們自己的戰士，同時我們也需要一份毒液的樣本來研製解藥。到庫爾森的營地去把這兩樣東西找來吧，藥品應該就在那些醫療人員或密林戰士的身上，而毒草汁液大概是保存在營地中的一些物資箱裡。', '給反抗軍營地裡的尤瓦中士帶回7份密林藥劑和1份毒草汁液。', '', '去找荊棘谷反抗軍營地的尤瓦中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 205 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (205, 'zhTW', '食人妖巫術', '在我研究這些食人妖傳說的時候，我希望你能幫我收集一些食人妖們施展邪惡魔法時必備的法器。到南邊的那個劈顱食人妖部族的地盤上去，從他們的巫醫和秘法師那里弄一些劈顱食人妖的神像回來吧。', '給反抗軍營地的尼麥茲修士帶回4只劈顱食人妖的神像。', '', '去荊棘谷找反抗軍營地的尼麥茲修士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (206, 'zhTW', '麥佐斯', '庫爾森的確是該死，不過……到底是誰將他帶上了這條邪惡的道路呢?通過研究，我已經找到了真相:是一個名叫麥佐斯的巨魔法師幹的。他住在荊棘谷東部的巨魔山中，據說他擅長心靈控制魔法，我也確信正是他使得庫爾森上校墮落的。$B$B如果麥佐斯繼續活在這世上，他的邪惡法術就有可能影響到更多人，或許又會出現另一個庫爾森上校。$B$B殺死他，把他的心靈之眼帶回來，這正是他用來誘惑他人墮落的物品。', '將心靈之眼交給反抗軍營地裡的尼麥茲修士。', '', '去荊棘谷找反抗軍營地的尼麥茲修士。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 207 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (207, 'zhTW', '庫爾森的秘密', '庫爾森上校曾是個偉大而高貴的人，我必須得找到讓他墮落至此的原因!他一定是被食人妖的魔法給控制了。要想搞清楚這一點的話，我們就得先研究一下食人妖的傳說故事。$B$B據說荊棘谷中的食人妖遺跡中隱藏著四塊石板，我必須得看看這些石板上到底記述了些什麼東西!你去給我拓一份這些石板上的文字來，把拓片都交給我。$B$B第一塊石板在巴拉爾廢墟裡，第二塊石板在暗礁海的海底，第三塊和第四塊應該都在祖昆達廢墟裡。', '找到4塊石板並將上面的內容帶回去交給尼麥茲修士。', '', '去荊棘谷找反抗軍營地的尼麥茲修士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 208 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (208, 'zhTW', '王牌獵人', ' $N ，你成為了一位夠格進入我們狩獵隊的獵手。無論是羅德隆的戰場還是危機四伏的叢林，我都鮮少見到有誰能像你這樣擁有如此強大的戰鬥能力。$B$B你成功地殺死了殘忍的辛達爾，隱密的巴爾瑟拉和狡詐的泰希斯。但對於這片叢林中的獵人們來說，虎王邦加拉西的頭才代表著至高無上的榮耀。這隻白虎正是我來這裡的原因...但目前還只能眼睜睜看著牠待在南方的居處。如果你能殺死虎王邦加拉西，那麼你無疑是這裡最優秀的獵人。', '小赫米特·奈辛瓦里要你將大白虎，虎王邦加拉西的頭帶回來給他。', '', '去荊棘谷找奈辛瓦里遠征隊的赫米特·奈辛瓦里二世。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 209 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (209, 'zhTW', '劈顱食人妖的獠牙', '靠不停地獵殺老虎來保證對南海島嶼的虎牙出口實在是苦差事，不僅難度高，而且花費也高。幸虧我們找到了一種替代品，就是這些劈顱部族的食人妖的獠牙。$B$B嘿，只要你不說，買家就不會知道，對吧?給我搞一批食人妖獠牙來吧，這樣我們就能應付每月一次的供貨啦!', '給藏寶海灣的科博克帶回18根劈顱食人妖的獠牙。', '', '去荊棘谷找藏寶海灣的科博克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 210 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (210, 'zhTW', '克拉茲克的烹調鍋', '在營地裡，我是專門負責伙食的。過去的活真的很多，讓我每天都要忙到死，直到我從藏寶海灣的哥布林商人那裡買了台多功能機械烹調鍋才有所改觀。這鍋實在是太棒了!它節省了我許多的時間……我是說，在它壞掉之前!$B$B你能幫我把這鍋帶到那個哥布林商人那裡去，讓他給我修理一下嗎?他的名字叫克拉茲克。', '把克拉茲克的烹調鍋帶給藏寶海灣的哥布林克拉茲克。', '', '去荊棘谷找藏寶海灣的克拉茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 211 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (211, 'zhTW', '啊，安多哈爾!', '啊，進攻安多哈爾並徹底擊敗那個巫妖的時刻終於來臨了!$B$B你這個城市的廢墟裡就是巫妖 - 『召喚者』阿拉基統治的地方。無數的天譴軍團守護在城中心的廢墟周圍，而他的貼身隨扈守衛更是令人畏懼。你需要帶眾多的盟友前往才可能有機會成功挑戰它。$B$B消滅阿拉基，$N，從它的骨匣裡拿出一塊裂片來，作為你獲勝的證據!', '把阿拉基的骨匣裂片交給西瘟疫之地冰風營地的指揮官阿胥拉姆·瓦羅菲斯特。', '', '去西瘟疫之地找冰風崗的指揮官阿胥拉姆·瓦羅菲斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (212, 'zhTW', '冷餐會', '我的拿手菜之一就是橙味凍蜥肉，但現在的問題是……這種肉很容易變質，而且我今天晚上必須得在一位貴族的生日晚宴上做這道菜!$B$B救場如救火，如果你能馬上從剛被宰掉的冷眼蜥蜴身上割塊冷蜥蜴肉給我的話，我就給你做頓堪比國宴的美味嘗嘗!$B$B冷眼蜥蜴一般會在荊棘谷西北海岸的沙灘上曬太陽，離這裡有點遠，不是麼?所以你得趕緊行動啦!', '殺死一隻冷眼蜥蜴，取一塊冷蜥蜴肉並把它帶給藍色隱士中的安古斯·斯特恩。', '', '去找艾爾文森林的安古斯·斯特恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 213 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (213, 'zhTW', '惡性競爭', '太倡狂了!吉爾里茲把貿易親王們指定的要員們都從這裡趕了出去，這件事已經夠糟的了，現在他居然還和那些聲名狼籍的海賊們往來!$B$B里維加茲不會坐視不理的，他允許我按自己的方式來解決這些問題。$B$B我的方式是什麼?偷!最近，風險投資公司的地質學家們正在研究他們從礦裡挖出的一種奇怪的藍色水晶，從那群地質學家手裡搞些樣本回來給我，當然，我不關心你用怎樣的手段去搞。', '給藏寶海灣的科博克帶回8塊打磨過的水晶。', '', '去荊棘谷找藏寶海灣的科博克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 214 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (214, 'zhTW', '紅色絲質頭巾', '迪菲亞兄弟會的人都會戴著一種紅色的頭巾，這顯然已經是個盡人皆知的秘密了。但我們又瞭解到，這個頭巾的材料是他們的成員在幫會內部地位的象徵。$B$B既然如此，那麼我希望你出馬殺死一些兄弟會的高階成員。他們的最高階成員無疑都躲在范克里夫的秘密藏身處附近。作為證據，你要給我帶回10條紅色絲質頭巾來，這樣我才能給你獎勵。祝你好運， $N 。', '給哨兵嶺哨塔的斥候瑞爾帶回10條紅色絲質頭巾。', '', '去找西部荒野的哨兵瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 215 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (215, 'zhTW', '叢林中的秘密', '謝謝你救了我的命，$N。我知道這聽起來有點奇怪，但……請聽我解釋。$B$B多倫中尉讓我和庫爾森的手下一起重新回到軍隊裡，讓我扮演臥底的角色，為我們反抗軍搞一些有用的情報。我原本以為這裡很適合我滲透入庫爾森的營地，但我錯了。再次感謝你救了我一命。$B$B這是個機密任務，所以你千萬不能把它告訴任何人。但如果你去和多倫中尉談談的話，他會給你一個解釋的。', '與反抗軍營地裡的多倫中尉談一談。', '', '去荊棘谷找反抗軍營地的多倫中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 216 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (216, 'zhTW', '薊皮熊怪的麻煩', '薊皮熊怪在威脅我們的擴張！我們東面的薊皮村擋住了從這裡通往碎木崗哨的道路，這是一條可以包圍阿斯特蘭納的道路，沒有它，我們就會讓聯盟得到一條額外的擴張路線。$B$B$N我們決不允許有這樣的缺口存在！$B$B進入薊皮村，儘量減少那些熊怪的數量。你會為這項任務得到補償的，但更重要的是，你會為部落盡到你的職責！', '殺死8個薊皮復仇者和8個薊皮薩滿祭司。他們大部分都位於佐拉姆海岸東部的薊皮村裡。任務完成後回到梣谷佐拉姆加前哨站的卡拉恩·阿瑪卡那裡覆命。', '', '去梣谷找佐拉姆加前哨站的卡拉恩·阿瑪卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 217 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (217, 'zhTW', '保衛國王的領土', '我的計畫成功了。這幫洛克莫丹的怪物好像是由一個叫格勞姆格的酋長領導的，不過格勞姆格身邊守衛森嚴，兩個精英守衛納什爾和布勞勒爾從不離他左右。$B$B如果你想證明自己的價值的話， $N ，我希望你能接下殺掉格勞姆格和他那兩個手下的任務。去吧!等我把這裡的事情搞定再與你會合。', '殺掉穴居人首領格勞姆格及他的兩個守衛，納什爾和布勞勒爾。然後回到南部警戒塔向拉格弗斯上尉報告。', '', '去洛克莫丹找國王谷的拉格弗斯上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (218, 'zhTW', '被竊取的日記', '我的日記!那幫食人妖把它拿到洞穴裡去了。拿著日記的那個傢伙……他是一個皮膚和面頰上都塗著奇特印記的青面獠牙的傢伙，我打從娘胎裡出來後還沒見過像他那樣醜的。$B$B你應該能對付那些食人妖，幫我把我的日記拿回來怎麼樣?', '格瑞林·白鬚要你去殺掉冷酷的格瑞克尼爾，並取回他的日記。', '', '去找丹莫洛的格瑞林·白鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (219, 'zhTW', '失蹤人員', '終於…有人來了……來自聯盟的朋友!$B$B救救我…求你了…$B$B我只記得…一群邪惡的獸人讓我們團全軍覆沒……大多數人都被殺了，我的頭被狠狠地打了一下，眼前一黑就倒下去了。現在我被關在這個洞裡，奄奄一息……$B$B我必須得回到鎮上去…拜託了…你是我最後的希望了……', '保護基沙恩下士回到赤脊山。', '護送基沙恩下士返回赤脊山', '去找赤脊山的治安官馬瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 220 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (220, 'zhTW', '水之召喚', '在給你圖騰之前，伊斯倫還會有一個任務讓你去完成。我給你的那瓶水在任何情況下都會很有用。$B$B去吧，去找伊斯倫。我們會再見的。', '把最純淨的水交給貧瘠之地的伊斯倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (221, 'zhTW', '森林裡的狼人', '你可能已經注意到了，在樹林周圍有些個頭較大的狼人和那些夜行織影狼人一起遊蕩。據我們所知，大多數狼人都是這類夜行黑暗狼人。$B$B我還發現在小鎮西南的爛果園裡已經到處都是他們的身影了，這些狼人比你之前遇到的那些更難對付。$B$B小心點。', '為夜色鎮的卡洛爾殺掉12個夜行黑暗狼人。', '', '去暮色森林找夜色鎮的卡洛爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (222, 'zhTW', '森林裡的狼人', '你之前的功績使我確信，你已經可以去對付森林裡最兇猛的狼人了。$B$B在這一帶所有的狼人中，夜行邪齒狼人和夜行墮落狼人是最危險的。他們就住在南邊的洞穴和礦坑裡。$B$B你甚至能從很遠的地方看見他們的營火。', '為夜色鎮的卡洛爾殺掉8個夜行邪齒狼人和8個夜行墮落狼人。', '', '去暮色森林找夜色鎮的卡洛爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (223, 'zhTW', '森林裡的狼人', '拿著這個，$n。把這個帶給卡爾文主人。$B$B<他取出一張褪色的羊皮紙交給你>$B$B如果再多些像你這樣的力量加入，我們就能讓守夜人相形見拙!也許到那個時候，我們就能夠徹底解決這些現在令我們疲憊不堪的危機。', '把卡洛爾的便箋交給喬納森·卡爾文。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (224, 'zhTW', '保衛國王的領土', '我們要保衛洛克莫丹， $N !國王的士兵都在遙遠的戰場上英勇作戰，我們的家園卻變得危機叢生。穴居人源源不絕地從每一條裂縫裡冒出來!四處橫行的他們已經成了鐵爐堡最大的威脅，我們一定要消滅這些噁心的怪物!$B$B我們需要像你這樣的勇敢冒險家來幫忙消除穴居人的威脅。殺掉10個石裂穴居人和10個石裂斥候，然後回來向我彙報。你會在南邊山脈的隧道裡找到許多這種害蟲。', '南部警戒塔的巡山人庫伯弗林特要你殺掉10個石裂穴居人和10個石裂斥候。', '', '去丹莫洛找南部警戒塔的巡山人庫伯弗林特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 225 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (225, 'zhTW', '飽經風霜的墓碑', '這座飽經風霜的墓碑上僅僅寫著幾個字:$B$B摩根·拉迪莫爾$B$B<經過仔細的觀察，你發現墓穴的泥土最近被人動過，很多泥土好像都翻開了……>', '去和夜色鎮的希拉·沃甯迪談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 226 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (226, 'zhTW', '惡狼成群', '我和斯溫的處境越發危險了，這兒就我們倆，要吃飯就得打獵捕魚。但是每次我們帶著肉和魚回營地的時候，那些從森林跑出來的恐狼都好像要撲上來咬一口似的。別提有多危險了!$B$B如果你能替我們除掉這些狼，也許我們就能過得輕鬆些。它們經常在北邊和東邊的小河周圍出沒。', '殺掉12只饑餓的恐狼和8隻瘋狂的恐狼，然後到斯溫的營地中向拉爾斯交差。', '', '去找暮色森林的拉爾斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 227 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (227, 'zhTW', '摩根·拉迪莫爾', '<他從架子上翻出一本皮質封面的書。>$B$B如果你想知道更多，就去問奧爾希雅，她最近正在為摩根·拉迪莫爾的事情頭疼……', '去和夜色鎮的指揮官奧爾希雅·埃伯洛克談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (228, 'zhTW', '摩拉迪姆', '我的斥候說摩拉迪姆沿著一條穿過墓地的彎曲怪異的小路，在暮色森林中四處遊蕩。我們曾把他的屍體埋在山上那座小屋的後面，你知道在哪兒吧?$B$B除了祝你好運之外，我沒什麼能幫你的了。', '殺掉摩拉迪姆，把他的頭骨交給夜色鎮的指揮官奧爾希雅·埃伯洛克。', '', '去暮色森林找夜色鎮的指揮官奧爾希雅·埃伯洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (229, 'zhTW', '倖存的女兒', '我應該早點告訴你的……$B$B該怎麼說呢……$B$B摩根可能以為他的家人都死了，不過實際上他的女兒薩拉·拉迪莫爾還活著，她現在也是個守夜人。她一直在因為她父親死了以後所發生的……那些事情而苦惱。我想，你可以把關於她父親的最新消息帶給她。', '去和夜色鎮的守夜人薩拉·拉迪莫爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (230, 'zhTW', '斯溫的營地', '挖開土堆之後，你發現了一本不大的書，上面沾滿了泥土。$B$B書上沒有寫標題，不過……書裡寫著一些斯溫想要知道的東西。', '把你從斯溫的農場找到的書交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 231 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (231, 'zhTW', '女兒的愛', '拿著這個，請把這個放到他的墳墓上。也許…也許這樣他就可以知道我現在過得很好，而且我們也不會因為他所做的事責怪他。$B$B<她含著眼淚，把戴在右手上的一隻戒指摘下放在你手裡>$B$B還有……謝謝你，$n。', '把薩拉·拉迪莫爾的戒指拿到摩根·拉迪莫爾的墳墓上去。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (232, 'zhTW', '金格的貨物', '皇家藥劑師學會需要你的幫助。仔細聽好了，這個行動對你我都有好處。$B$B隔壁的藥劑師基佛看起來有些……瘋瘋癲癲的，但如果他的研究項目能早點找到一個有眼光的買家的話，早就已經得到豐厚的成果了。幸運的是，現在我已經把這個研究項目買了過來。我要你把這份訂貨單交給藍月雜貨店的店主奧雷薩多·盧卡那裡，他會給你一隻實驗工具包。當你拿到工具包之後就儘快回來向我報告，我會告訴你下一步任務的詳細情況。', '把訂貨單交給幽暗城的奧雷薩多·盧卡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (233, 'zhTW', '寒脊山谷的送信任務', '嗯，$g小子:姑娘;，我想也許你不會幫我這個忙的。今天從隧道那邊來了一大堆信，我想我沒時間把它們都給發出去了。$B$B這些信都是寄給塔林·銳眼的。沿著這條路向西走就能找到他，就在結冰的湖泊附近。$B$B你能幫我這個忙麼?', '把這一疊信件送給塔林·銳眼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 234 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (234, 'zhTW', '寒脊山谷的送信任務', '如果我沒記錯的話，格瑞林的營地就在這條路的盡頭，沿著路往東南方走就是了，他一定正在等著這封信呢。', '把這封信送給格瑞林·白鬚。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (235, 'zhTW', '梣谷狩獵', '年輕的冒險者們，注意了！梣谷的野獸正在等著你們！$B$B部落在貧瘠之地以北的區域建立了強大的基地。我們的兩個前哨站——碎木崗哨和佐拉姆海岸哨崗——正在努力地為部落的榮耀而戰！想要證明自己能力的勇士就到那兒去吧。碎木崗哨位於貧瘠之地的正北方，塞娜尼·雷心正在那裡招募願意參與梣谷狩獵中的冒險者！', '與梣谷碎木崗哨的塞娜尼·雷心談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 236 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (236, 'zhTW', '為石毀車補給燃料', '$n!你也差不多該出現了。戰鬥也許已經結束了，但我們還得準備下一場戰鬥。前往冬握湖東南的火焰熔爐，然後取回幾個永恆餘燼。$B$B我們把這些餘燼和煤炭混合，用來驅動石毀車和攻城機具。$B$B喔，如果你碰巧在那裡碰上了部落的傢伙，不要猶豫，殺了他們並奪取他們的餘燼。我們可不能讓他們在下一場戰鬥佔上優勢。', '冬握堡壘的攻城大師斯托哈德要你前往火焰熔爐，從部落玩家身上取回10個永恆餘燼。', '', '去找冬握堡壘的攻城大師斯托哈德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 237 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (237, 'zhTW', '保衛國王的領土', '巡山人庫伯弗林特總是在我面前稱讚你， $C 。因此現在我要交給你一個極其重要的任務，你必須不斷給那些入侵的穴居人施加壓力，直到我們的兄弟們從聯盟前線回來。$B$B到南部的丘陵去，殺掉10個石裂擊顱者和10個石裂先知。你的行動可以為我們贏得一點時間，完成任務後就回來向我報告。', '南部警戒塔的巡山人格拉維戈要你殺掉10個石裂擊顱者和10個石裂先知，然後回去向他彙報。', '', '去洛克莫丹找國王谷的巡山人格拉維戈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 238 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (238, 'zhTW', '金格的貨物', '東西都準備好了，$n。毫無疑問，藥劑師金格正在等著這批貨。馬上把這些東西送到她那裡去，告訴她我已經把價錢記在學會的帳上了。另外，請代我向她致以最高的敬意。$B$B好了，不要再站在這裡了，快點出發吧！', '把採樣工具包交給幽暗城的藥劑師金格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 239 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (239, 'zhTW', '西泉要塞', '我們位於西部邊界的要塞報告說，那裡的豺狼人和迪菲亞盜賊最近越來越猖獗了。他們要求我從暴風城派更多士兵過去……但是我們已經沒有多餘的人可派了!$B$B如果你願意幫忙的話，就去和西泉要塞的瑞尼爾副隊長談一談，看看他需要你做些什麼。$B$B沿著這條路往西走，過了橋之後向右轉就是要塞。', '到西泉要塞去和瑞尼爾副隊長談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 240 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (240, 'zhTW', '基特斯的美餐', '完成了─格魯奧烹製的黑「蟹」蛋糕!', '把黑蟹蛋糕拿回去交給基特斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (241, 'zhTW', '<TEST> HEY MISTER WILSON!', 'Description', 'Log', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (242, 'zhTW', '暫無內容', '你好，$c。我們沒多少時間了。龍喉氏族的獸人們已經在靠近南方的大峽谷構築了自己的工事。$B$B他們拒絕執行酋長的命令，因此我們別無選擇，只能消滅他們，讓他們永遠不再玷汙部落的名字。', '殺掉8個龍喉襲擊者、3個龍喉白骨守衛和1個龍喉軍官。', '', 'Return to [UNUSED] Truek.', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 243 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (243, 'zhTW', '進入沙漠', '你現在得去一趟塔納利斯沙漠，在那裡對當地的蜥蜴、蠍子和土狼進行一些組織測試，並蒐集一些組織樣品放進實驗工具包裡。當然，你有可能得花不少工夫才能找到合適的樣品，這一點是可以預料的。每種生物的樣本都要十份。$B$B另外，加基森的哥布林擁有這類工具包所需的能量源，去和那裡的首席工程師比格維茲談談，或許能得到一些必要的幫助。$B$B此行只許成功不許失敗，否則就不要回來見我。', '和加基森的首席工程師比格維茲談一談，請他為實驗工具包提供能量源。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 244 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (244, 'zhTW', '豺狼人的入侵', '你好，$c。我是負責這段道路巡邏任務的衛兵。雖然這條道路現在是安全的，但我曾經在這附近的東北方看見過豺狼人的宿營地。$B$B湖畔鎮必須得提防著這群豺狼人才行。請你把這條消息報告給湖畔鎮的菲爾頓副隊長,我想他一定會非常樂意給你的偵察行動付上一筆酬勞的。$B$B菲爾頓一般在湖畔鎮橋南的地區執行警戒任務。', '找到菲爾頓副隊長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 245 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (245, 'zhTW', '蜘蛛的威脅', '你好啊，$c。你有沒有看到過在西邊出沒的那些蜘蛛?這些八條腿的東西實在是太多了，多到我們沒法應付，指揮官又沒有多餘的人力可以從夜色鎮派來協助我們。$B$B我實在是不好意思向你開口，不過...看樣子你好像能對付它們。我不能承諾給你什麼貴重的寶貝，不過如果你幫助我們除掉這些骯髒的臭蟲，我肯定會獎賞你的。$B$B哦，對了，給你個忠告:盡量別碰到它們的毒液。', '殺死15隻小型結網毒蜘蛛。然後向暮色森林的守夜人道茨報告。', '', '到暮色森林找守夜人道茨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 246 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (246, 'zhTW', '審時度勢', '我們實在是沒有多餘的人手了，但我們也不能對你報告中提到的那些豺狼人不聞不問。$B$B偵察南赤脊山附近豺狼人的動向,並盡可能地殺掉足夠多的豺狼人,然後向我回報他們的數量，好讓我們對他們的威脅大小有個正確的認識。$B$B暴風城軍方需要你的幫助，$N，你會得到獎賞的。', '殺死10個混血赤脊山豺狼人和6個赤脊山偷獵者，然後向湖畔鎮的菲爾頓副隊長覆命。', '', '去找紅嶺山脈的菲爾頓副隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 247 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (247, 'zhTW', '完成狩獵', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (248, 'zhTW', '監視', '我監視伊爾加拉之塔已經很久了，並且我發現，莫甘斯與佔據了石望要塞的獸人之間起了矛盾。我不知道他們之前產生紛爭的原因是什麼，但你可以幫我揭開謎底。$B$B帶上阿祖拉雕紋，然後到那個能監視石望要塞的崗哨頂部去。$B$B找一個合適的地方，把雕紋放進去，一個箱子或者罐子之類的東西都可以，只要雕紋不會被注意到就行，那樣我的目的就達到了。', '爬上石望要塞一旁的哨塔。$B$B為阿祖拉雕紋找一個合適的容器。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (249, 'zhTW', '莫甘斯', '在長期的偵察監視之後，我終於發現了莫甘斯的計畫。$B$B他正在尋找月神鐮刀……而且，他甚至可能已經找到了。如果他有了那東西，整個赤脊山脈地區，甚至是整個暴風王國都會被他的黑暗力量所征服。$B$B我還沒有想到對付莫甘斯的辦法，但我怕如果現在不行動的話，也許以後就沒有機會了。所以我希望你能殺進伊爾加拉之塔與莫甘斯交戰。$B$B戰勝他，然後把他的暗影墜飾帶回來給我。如果你成功了的話，整個王國都將以你為傲。', '擊敗莫甘斯。$B$B將他的暗影墜飾帶給塞歐克瑞圖斯，他就在艾爾文森林內的阿祖拉之塔中。', '', '去找艾爾文森林的塞歐克瑞圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (250, 'zhTW', '黑暗危機逼近', '老天保佑，現在終於有人關心水壩的安全了。先是有人摧毀了薩多爾大橋，然後又有人搶劫丹莫德!我敢說這座大壩肯定會是黑鐵組織下一次襲擊的目標。這裡的駐軍─包括我的長官在內─大部分都開到了聯盟前線。$B$B這就是我需要你的原因，$n。我看見有幾個黑鐵工兵在水壩東邊的斜坡下轉悠。去那裡查看一下，帶回點線索給我。', '查看水壩東邊斜坡附近的區域，調查一下黑鐵矮人準備做什麼，然後把線索帶給首席工程師辛德維爾七世．', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 251 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (251, 'zhTW', '翻譯亞伯克隆比的信', '請把你給我的這封信拿給希拉·沃寧迪看看。他對語言和古代藝術很有研究─我看也只有他能翻譯這封信了。', '把寫給艾爾羅的信拿給希拉·沃寧迪。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (252, 'zhTW', '翻譯好的信件', '天哪!如果信上所寫的內容都是真的，那亞伯克隆比所做的事情……太可怕了!$B$B你最好還是把翻好的信拿回去給艾爾羅看看。$B$B快一點，我感覺到這座小鎮的末日就要到了……', '把翻好的信帶給艾爾羅·埃伯洛克領主。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (253, 'zhTW', '藏屍者的妻子', '藏屍者是個我們經常用來嚇唬孩子的故事裡的人物。他曾是個善良的鍊金師，但因為妻子伊莉莎的死而變得瘋狂。為了讓妻子復活，藏屍者用黑暗的魔法將自己的心臟放入了亡妻的胸膛裡。$B$B伊莉莎復活了……不過她也受到了詛咒，開始瘋狂地吞食人類的血肉，藏屍者不得不將他的妻子埋了起來。$B$B他的心臟就是他全部的力量，找到他妻子的墳墓，把他那顆仍在跳動著的心臟拿回來，就可以打破他的力量。', '找到伊莉莎的墳墓，從她的身上取回藏屍者的心臟，把它交給艾爾羅·埃伯洛克。', '', '去暮色森林找夜色鎮的艾爾羅·埃伯洛克領主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (254, 'zhTW', '掘墓', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (255, 'zhTW', '雇傭兵', '我等了兩個月才得到了從鐵爐堡傳來的消息，說是會有少量士兵來幫助我們防守塞爾薩瑪，不過他們還得再等兩個月才能到這兒來!我們的鎮子沒人守衛已經夠糟了，但是我們的挖掘場和水壩─這些地方都隨時面臨著被襲擊的危險。$B$B看來我已經沒有選擇了，必須臨時徵召一點士兵才行。$B$B你怎麼樣?你看起來挺合適的， $C 。有一群巨魔在洛克湖的東北方安營紮寨，你能不能幫我們把那些傢伙趕走呢?', '塞爾薩瑪的鎮長埃羅恩·鈍鼻雇你去殺掉4個莫格羅什巨魔、4個莫格羅什蠻卒和4個莫格羅什執行者。', '', '去找洛克莫丹的鎮長埃羅恩·鈍鼻。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (256, 'zhTW', '懸賞令:卓克蘇爾', '以塞爾薩瑪鎮長之令:$B$B卓克蘇爾，襲擊塞爾薩瑪鎮、巨石水壩及挖掘場的巨魔的領導者和組織者。現要求不惜採用一切手段殺死卓克蘇爾。$B$B若有人呈上殺死卓克蘇爾的證明，鎮長將給予巨額獎金。$B$B卓克蘇爾最後一次出現是在洛克莫丹東北部的巨魔營地裡。', '殺了卓克蘇爾，把他的頭顱帶給塞爾薩瑪的鎮長埃羅恩·鈍鼻。', '', '去找洛克莫丹的鎮長埃羅恩·鈍鼻。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (257, 'zhTW', '自豪的獵人', '你覺得自己可以和勇敢的達瑞爾相提並論?我可不這麼認為，當然囉，如果你不服氣的話，完全可以試試看。我會讓你去做一件非常困難的事情，困難到以你的能力恐怕根本沒法擺平，所以就算你完成不了也用不著氣餒。$B$B有群禿鷲在洛克莫丹這裡築了巢，你何不試著把牠們解決掉?告訴你吧，如果你能完成這個任務，我就把我的弓或是火槍送給你。<他輕蔑地上下打量著你。>$B$B反正你看起來也沒什麼可以輸掉的東西。', '殺死6隻山地禿鷲，然後回到遠行者小屋找年輕的達瑞爾，時限為15分鐘。', '', '去洛克莫丹找旅行者營地的年輕的達瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (258, 'zhTW', '獵人的挑戰', '你叫 $N 啊嘶，對吧?看得出來，你對自己的狩獵本領變得非常自傲，對吧?那沒什麼了不起。$B$B你應該試試去捕殺野豬。相信我，這和捕殺寒脊山谷裡那些野豬可不一樣，所以你最好當心點。$B$B失敗了也別難過。不過如果你成功了，我就把我的襯衣脫下來給你!$B$B我有沒有跟你說過我這個著名的傷疤是怎麼來的?沒有?好吧，兩年前的一天...', '殺掉5隻老山豬，然後回到遠行者小屋找年輕的達瑞爾，時限為12分鐘。', '', '去洛克莫丹找旅行者營地的年輕的達瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (259, 'zhTW', '<UNUSED>', '你好啊，$n。久仰你的大名，能見到你真是我的榮幸。我猜你大概沒聽過老凱特的故事吧？啊，老凱特——也就是凱特·湯瑪辛——曾經被公認為全境最頂尖的獵人之一。他幾乎沒有什麼是沒做過的，可是有一天，他卻迷上了一個古老的傳說……說穿了不過是個神話罷了。傳說中，湖水深處住著一隻巨大的鰭龍。要我說，這根本是胡說八道。如果你有興趣的話，不妨去找凱特聊聊。', '去找凱特·湯瑪辛談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (260, 'zhTW', '暫無內容', '現在我可以跟你說，我，就像他們說的那樣——不要否認，我知道他們是那樣說的——思維混亂，腦海中縈繞著一個不太可能的傳說。那是矮人一族的古老傳說，講的是一頭深藏在洛克湖底的巨獸。我一生中最好的一段時光都在尋找它，而且我想我離它已經很近了，可是……唉，歲月不饒人啊。如果你願意去獵捕這頭洛克湖底的怪獸，別忘了幫我帶回一些魚龍的牙齒和利爪。$B$B<他神秘地笑了笑。>', '收集5枚魚龍的牙齒和5只魚龍的爪子，然後把它們帶給科爾特·托馬森。', '', '去找洛克莫丹的科爾特·托馬森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (261, 'zhTW', '血色之路', '坦率地說，我們現在正在與天譴軍團交戰。他們是一群致力於腐化我們的人民、污染我們的土地的惡魔。我們一定要在他們將我們最後的堡壘徹底血洗、將我們的世界徹底拖入黑暗之前阻止他們。我們血色十字軍發誓要奉獻出全部身心，與天譴軍團鬥爭到底。$B$B如果你也如此宣誓了的話，鼓起你的勇氣並證明你的忠誠─去與淒涼之地的不死生物劫毀者們作戰吧，它們都聚集在那個地區南部的白骨之谷裡。$B$B只有這樣，十字軍才會接納你。', '殺掉30個不死生物劫毀者，然後向尼耶爾前哨站的安東修士覆命。', '', '去淒涼之地找尼耶爾前哨站的安東修士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (262, 'zhTW', '模糊的人影', '我一定要搞清楚那個躲在暗處目睹我全家被殺的人到底是誰!$B$B求求你了，$N，你已經表現出了你的足智多謀，請你幫我找出那個模糊的人影到底是誰，我一定要知道他到底是誰!$B$B我沒法再給你提供更多線索了，不過……拿著這本你在農場裡找到的書，也許鎮上有人能夠幫助我們找到它的主人。', '帶著你從斯溫的農場找到的書，把它拿給夜色鎮上的人看看。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (263, 'zhTW', '保衛國王的領土', '巡山人告訴我你很勇敢也很能幹， $N 。我們這兒就需要像你這樣的 $R 。穴居人的問題一點也沒有好轉，預備軍都被派到前線去了，我們在這兒孤立無援。不過現在我們有你這樣一個經驗豐富的 $C ，就看看你能做什麼吧。$B$B去殺掉10個石裂斷骨者和10個石裂薩滿，讓我們瞧瞧你是不是名副其實的穴居人殺手。', '南部警戒塔的巡山人沃爾班要你殺掉10個石裂斷骨者和10個石裂薩滿。', '', '去丹莫洛找國王谷的巡山人沃爾班。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (264, 'zhTW', '至死方休', '太過分了！他因為那該死的十字軍離開了我，說什麼“聖光是我們用來與亡靈抗爭的最重要的東西。”$B$B那麼，他的孩子呢？我呢？我日復一日地等他……一直在默默地支援著他那該死的職責！$B$B看看“公正”帶給你的一切，$N！他已經死了，而我卻成了他曾經想要消滅的東西！$B$B把這個垃圾放到他那修在瑟伯切爾的墳墓上吧。我不想再跟他有任何聯絡了！', '把克拉莉斯的墜飾放在銀松森林尤瑞夫的墳墓上。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 265 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (265, 'zhTW', '繼續搜尋模糊的人影', '拿回你的書吧，$N，祝你好運。你可以去問問鎮上的其他人，他們也許還能給你提供更多的線索。$B$B對了，我還有個線索可以提供給你─這本書的作者不是夜色鎮的人，不過書卻是在鎮裡買來的。', '看看其他的鎮民有沒有關於模糊的人影的線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 266 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (266, 'zhTW', '調查旅店', '這是你的書，祝你好運。$B$B你不妨去旅店裡查查看，如果你要找的那個人在鎮上待過的話，那麼很可能有人在旅店裡見過他。', '到旅店去查一查關於模糊人影的線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 267 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (267, 'zhTW', '穴居人的威脅', ' $C ，你可能知道也可能不知道矮人的領地正面臨穴居人的威脅。鐵爐堡的預備部隊被派到聯盟前線去了，只有很少一部分留下來負責保衛這裡的安全。我的部隊負責看守這裡的大門，提防隨時可能到來的攻擊，我們絕不能因為害怕遭到入侵而離開崗位。$B$B不過我們得向潛伏在山裡的那些穴居人施加點壓力。如果你能勝任這個工作，就去幹掉這些穴居人，然後帶8顆穴居人的石牙回來作為勝利的證明。', '給南部警戒塔的拉格弗斯上尉帶去8顆穴居人的石牙。', '', '去丹莫洛找南部警戒塔的拉格弗斯上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 268 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (268, 'zhTW', '回覆斯溫', '你找到的那本書……我還沒有寫完。我從斯溫的農場裡逃走的時候，不得不把書留在那兒……$B$B拿著這個，把這本完整的日記帶給斯溫。這一本對在他的農場上所發生的事情描述得更完整。$B$B這幾個星期以來，我一直把這本日記放在身邊，不過如果把它交出來之後我就不用面對斯溫和他的憤怒的話，我寧願把這東西交給他。', '把基特斯的日記交給斯溫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 269 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (269, 'zhTW', '尋求指引', '到暴風城去找光明大教堂的主教法席恩，把基特斯的日記給他看一看，告訴他你決心要和摩本特·費爾進行面對面的較量。$B$B雖然暴風城拋棄了夜色鎮，但是法席恩主教是個善良而又睿智的人，也許他能給你一些幫助。$B$B你的使命非常危險，不過請動作快點，$N。籠罩夜色鎮的黑暗力量無時無刻不在變得更加強大。', '把基特斯的日記交給暴風城的主教法席恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 270 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (270, 'zhTW', '被詛咒的艦隊', '幾年前，庫爾提拉斯的第三艦隊在濕地的海岸線附近全軍覆沒，對，就是丹莫洛北方的那塊濕地。其中一條船上滿載著光鑄鐵。$B$B這種金屬對我們來說相當珍貴，它們可以用來製造出附有神聖力量的武器。如果你要去與摩本特·費爾作戰的話，應該會需要這樣一把武器。$B$B去米奈希爾港找我的矮人同事戈羅林·鋼眉談談吧，如果你可以找到那些丟失了的金屬，他應該會知道該到哪裡去找。', '到濕地的米奈希爾港去，找戈羅林·鋼眉談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 271 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (271, 'zhTW', '維林的報復', '不曉得你有沒有興趣報復一下他的冒失個性?我不願意承認，但達瑞爾是有點能耐。$B$B一年前，整個遠行者小屋裡的獵人都在捕獵一隻巨熊，不過沒有一個人成功。所以，達瑞爾想去試試身手。他的努力只換來一道劃過眼睛的可怕傷疤。$B$B若你殺了那隻熊，我敢說就算是達瑞爾也會啞口無言。$B$B那隻熊名叫奧爾蘇迪，你會在北方洞穴附近找到牠的巢穴。', '殺掉奧爾蘇迪，把牠的頭顱帶給遠行者小屋裡的達瑞爾。', '', '去洛克莫丹找旅行者營地的年輕的達瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 272 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (272, 'zhTW', '海獅試煉', '第二個試煉是要尋找組成海獅墜飾的兩個部分。其中的一半蘊含著海獅的敏捷天性，另一半蘊含著海獅那令人難以置信的耐力。德魯伊汲取這兩種特性，將它們運用到自己的水棲形態中。$B$B與月光林地中的居民談一談，找到這兩個部分，並將它們合併起來。最後把合併好的墜飾交給德迪利特·星焰。', '尋找水獸耐力墜飾和水獸敏捷墜飾。與月光林地的居民談一談，找出這些東西可能被放在哪裡。$B$B在雷姆洛斯神殿附近將海獅墜飾的兩部分合而為一。$B$B將合併好的墜飾交給月光林地永夜港中的德迪利特·星焰。', '', '去月光林地找永夜港的德迪利特·星焰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 273 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (273, 'zhTW', '挖掘場的補給品', '現在還不算太晚，你還可以去找胡達爾。他不大可能走得太遠，儘管米蘭和賽恩都很壯實，但是他們帶著幾隻大桶是沒法走太快的。$B$B他們走的是補給車隊常走的路線，從鎮子出發，沿著洛克湖的邊緣往南走。$B$B只要他們還沒走到挖掘場，你就應該可以在路上找到他們。', '和胡達爾談話。', '找到胡達爾、米蘭和賽恩', '去洛克莫丹找洛克湖邊的胡達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 274 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (274, 'zhTW', '黑暗危機逼近', '這不是一般的炸藥粉末。看看這些銀色的小晶體。還有這股特別的味道!不用說這就是爆鹽粉末了!爆鹽本身沒什麼危害，不過一旦它沾上水，那威力，嘖嘖!足夠把整個鐵爐堡給炸上天!$B$B要想阻止這種東西爆炸就需要四種東西:潛伏者的毒液，莫格羅什水晶，一滴鱷魚的眼淚和一些拆彈膠質。現在你得趕緊把我的話告訴辛德維爾，否則就來不及了!', '阿胥蘭·暗石要你回去見首席工程師辛德維爾七世，把有關這種炸藥的新發現告訴他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (275, 'zhTW', '大地上的膿皰', '我不知道是怎麼回事，但是墮落正在濕地上蔓延。沼地爬行者出現了，他們就像是腐爛而危險的膿皰。要制止這些膿皰，就必須把他們驅散開，把它們趕回沼澤。$B$B這些沼地爬行者一般都在濕地的水道裡活動。', '殺死8隻沼地爬行者，然後向濕地的『綠色守衛者』雷希耶爾覆命。', '', '去濕地找綠帶草地的綠色守衛者雷希耶爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (276, 'zhTW', '踐踏之爪', '蘚皮豺狼人在濕地平靜地生活了許多年，但如今他們的數量卻膨脹了不少。他們的腳正踐踏著沼澤地中的灌木與花朵，他們污濁的斧頭也砍伐了太多的樹木。$B$B他們已經令這裡的自然失去了平衡。為了濕地的安寧，必須削減這些豺狼人的數量。$B$B去殺死15名蘚皮豺狼人和10名混血蘚皮豺狼人，他們就在南邊的奧加茲隘口附近活動。完成任務之後再回來向我覆命。', '殺死15名蘚皮豺狼人和10名混血蘚皮豺狼人，然後向濕地的『綠色守衛者』雷希耶爾覆命。', '', '去濕地找綠帶草地的綠色守衛者雷希耶爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 277 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (277, 'zhTW', '火焰管制', '蘚皮豺狼人們正在大量地砍伐濕地的樹木，用樹幹和樹枝當柴火來燒。我不能再容忍這樣的行為了!$B$B把蘚皮豺狼人生火用的打火石都給我搶過來。除了年幼的蘚皮豺狼人和混血蘚皮豺狼人以外，其他所有的蘚皮豺狼人身上都會帶著打火石。', '給『綠色守衛者』雷希耶爾帶回9塊粗製打火石。', '', '去濕地找綠帶草地的綠色守衛者雷希耶爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (278, 'zhTW', '黑暗危機逼近', '你必須立刻去收集拆彈用的原料， $N 。你可以在附近的土生蜘蛛身上找到潛伏者的毒液。鱷魚的眼淚在洛克湖裡的鱷魚身上就有。不過莫格羅什水晶很難找到。東北邊礦坑裡的巨魔開採這種水晶，不過即使在那裡，莫格羅什水晶也不常見。$B$B我們必須要作好準備才能粉碎黑鐵矮人的計畫!你找齊了這些材料之後就立刻回來找我，我會準備進行混合。', '首席工程師辛德維爾七世要你收集一份潛伏者的毒液，一塊莫格羅什水晶和一滴鱷魚的眼淚。', '', '去洛克莫丹找巨石水壩的主工程師辛德維爾七世。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 279 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (279, 'zhTW', '海中的魚人', '可惡的魚人正在從深海裡源源不斷地爬出來，它們沿著海岸線建立自己的村莊和定居點。這些傢伙給我們的漁民和商人帶來了極大的困擾，我們必須要阻止這種行為。$B$B它們當中有一個叫高布勒爾的頭目最近一直帶著一群藍鰓魚人埋伏在道路旁，搶劫過往的商旅，得手之後又馬上撤回它們的村子。現在我們的通商道路非常危險，所以我們想要通過懸賞來解決這個問題。$B$B高布勒爾和它的跟班們就躲在北邊的河口附近。找到它，把它幹掉，然後把它的頭給我帶回來。', '殺掉12個藍鰓魚人。$B$B殺死高布勒爾，取下牠的頭顱。$B$B將高布勒爾的頭顱交給米奈希爾港的卡爾·波蘭。', '', '去濕地找米奈希爾港的卡爾·波蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 280 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (280, 'zhTW', '黑暗危機逼近', '今天早些時候我發現有一些黑鐵矮人背著一隻大木桶向水壩遊去，糟糕的是那一帶沒有巡山人可以攔住他們!我懷疑他們已經把爆鹽炸藥放到了水壩下面，隨時都有可能爆炸!我馬上就把這些成分混合在一起製成拆彈劑。$B$B完成了!現在我要你把這個混合劑拿去，和木桶裡的炸藥攪拌在一起!快一點!我們沒時間了!', '首席工程師辛德維爾七世要你游到水壩底部，找到裝著炸藥的木桶，然後把拆彈劑放進去，阻止將要發生的爆炸。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (281, 'zhTW', '奪回雕像', '不久之前，有一艘名叫「盲眼公主」的商船遭到了一群魚人的襲擊。儘管這艘船完完整整地逃了出來，但船甲板上放著的貨物都被那些該死的魚人給拖下水搶走了，其中甚至包括一座十分寶貴的泰瑞納斯·米奈希爾的雕像。我們希望有人能把這座雕塑給搶回來。$B$B到海岸邊的魚人村落裡去，仔細找找看有沒有木箱、木桶，或者其他丟失貨物的蹤跡。在那裡找到米奈希爾雕像，然後回來向我覆命。', '搜索海邊魚人村落中的木箱和木桶。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (282, 'zhTW', '森內爾的觀察站', '我原本打算讓我的學徒幫我把報告送去給我的兄弟森內爾。但是如果有個更可靠的人替我送去的話就更好了。如果你不介意的話，可以去一趟嗎?$B$B嗯……你必須穿越隧道到卡拉諾斯去。$B$B在穿越隧道前，別忘了和巡山人泰洛斯聊聊，那裡的穴居人簡直氾濫成災了。$B$B順著這條路回安威瑪，然後向東走就能到隧道了，泰洛斯就駐守在附近。', '和巡山人泰洛斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (283, 'zhTW', '黑暗危機逼近', '木桶發出了輕微的嘶嘶聲。', '拆彈劑看來已經產生了效果。你可以回去向首席工程師辛德維爾七世彙報這個好消息了。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (284, 'zhTW', '繼續搜尋', '你繼續在魚人的村莊中仔細搜索著，但沒有找到任何關於米奈希爾雕像的蛛絲馬跡。$B$B也許北邊和東北邊的另兩處魚人村落那會有些什麼線索。', '搜索米奈希爾雕塑。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (285, 'zhTW', '搜尋雕像', '你仔細地搜索了這幾處魚人村落，但卻沒什麼有價值的發現。$B$B……但你有一種直覺，就是你在下次搜索中一定能找出一些很有價值的線索。$B$B北邊的最後幾處村落裡一定會有米奈希爾雕像!', '繼續在魚人村落中搜尋米奈希爾雕像的蹤跡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (286, 'zhTW', '歸還雕像', '你把這個木桶從垃圾裡拖了出來，剛一打開它，一尊精心包裹在稻草中的銀制小刻像就掉了出來。這是一個頭髮很長的年輕聖騎士高舉戰錘的樣子。$B$B這一定就是米奈希爾刻像了!你必須馬上把它交還給米奈希爾港的卡爾·波蘭。', '到濕地的米奈希爾港，將米奈希爾雕像還給卡爾·波蘭。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (287, 'zhTW', '霜鬃食人妖要塞', '我快要來不及提交報告了，你能幫我一下嗎， $N ?我只想知道這些食人妖躲在什麼地方，不過我看見這麼多的食人妖就怕得不敢進去了。$B$B你要做的是...進到山洞裡，在裡面到處走走，幹掉一些食人妖，然後再回來。$B$B順著向北的路離開卡拉諾斯，當你走到一座橋前的時候，再沿著冰凍的河流向西一直走到湧冰湖。你會發現烈酒村就在湖的西岸，而食人妖要塞就在村莊的西南邊。', '偵察霜鬃食人妖要塞，替卡拉諾斯的森內爾‧白鬚殺掉5個霜鬃獵頭者。', '對霜鬃巨魔要塞進行詳細的偵查', '去丹莫洛找閃光嶺的森內爾·白鬚。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (288, 'zhTW', '第三艦隊', '我曾經是浪花女神號上的大副─浪花女神是庫爾提拉斯第三艦隊的主力戰艦。這是一支多災多難的艦隊，說它多災多難是因為……它在最後一次出航中遇到了紅龍的襲擊。這些龍是被獸人控制的!$B$B紅龍噴出的火焰對我們的戰艦來說簡直是毀滅性的……我們的艦隊在這片海域被燒得一乾二淨，全軍覆沒。我是那次災難的唯一倖存者……$B$B……哦，我的頭疼得像鼓錘在敲!我需要一些讓我頭腦清醒的東西，好讓我繼續講述我的故事。', '為大副菲茲莫斯買一份壺裝蜜酒。', '', '去濕地找米奈希爾港的大副菲茲莫斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 289 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (289, 'zhTW', '被詛咒的船員', '<緩過氣來的菲茲莫斯繼續講述他的故事……>$B$B我是這支倒楣的庫爾提拉斯第三艦隊中唯一的倖存者，整支艦隊都在北方的海岸附近覆滅了。不過，雖然我是艦隊中唯一活著的人，卻不是唯一一個依然在這裡出現的人!因為，在一條已經沉沒的船裡，藏有巨大的、可怕的寶藏，它所擁有的可怕魔力將我的弟兄們的靈魂束縛在被海水侵蝕的船體裡。$B$B如果你能超渡我的那些被詛咒的弟兄們，也許你就能破除那個詛咒。', '殺死13個被詛咒的水手、5個被詛咒的水兵和大副斯涅利格。把斯涅利格的鼻煙盒交給米奈希爾的大副菲茲莫斯。', '', '去濕地找米奈希爾港的大副菲茲莫斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 290 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (290, 'zhTW', '解除詛咒', '為了破除詛咒，解救我所有的兄弟，就必須要把裝在我船上的那個鬼東西拿回來進行淨化!我不知道它是什麼，但我知道它被存放在船上的保險箱裡，而保險箱的鑰匙一向是由哈林多爾船長保管的。$B$B我的老船長仍時常出現我的夢裡，在我的那艘已毀滅了的無畏號的甲板上走來走去……去找到鑰匙，用它打開無畏號上的保險箱。$B$B然後，在你獲得那件被詛咒的東西以後，把它交給鎮上的牧師，戈羅林·鋼眉。', '從哈林多爾船長那裡拿到無畏號的保險箱鑰匙。$B$B用鑰匙打開無畏號的保險箱。', '', '去濕地找無畏號的保險箱。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 291 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (291, 'zhTW', '森內爾的報告', '好極了!把我的報告交給參議員巴林·紅石。他是個酸溜溜的傢伙，你可別在意。他在鐵爐堡，麥格尼陛下的宮殿裡。$B$B你不知道去鐵爐堡的路?順著這條路向北走出卡拉諾斯，穿過一座橋，然後沿著路向東走─在路邊山上應該有個很大的路標。$B$B順便說一句，你最好不要提及你是如何幫助我的，不要讓他們以為我在這裡沒有好好工作，好嗎?', '把森內爾的報告交給鐵爐堡的參議員巴林·紅石。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 292 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (292, 'zhTW', '帕雷斯之眼', '打開箱子之後，你看到了一顆發黑的寶珠，它還在閃爍著可怕的光芒。這就是菲茲莫斯所說的寶藏:一顆被詛咒的帕雷斯之眼。$B$B把被詛咒的帕雷斯之眼交給住在米奈希爾港的矮人牧師戈羅林·鋼眉，請他驅除附著在它上面的詛咒。', '到濕地的米奈希爾港，把被詛咒的帕雷斯之眼交給戈羅林·鋼眉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 293 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (293, 'zhTW', '淨化帕雷斯之眼', '我無法驅散帕雷斯之眼上的詛咒。它是由人類牧師手工製造的，所以你最好去暴風城尋找幫助。去和大主教本尼迪塔斯談談吧，他是暴風城光明大教堂的領導者，他能幫你解決問題。$B$B我希望如此。', '把被詛咒的帕雷斯之眼交給大主教本尼迪塔斯，他就在暴風城的光明大教堂裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 294 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (294, 'zhTW', '奧莫爾的復仇', '目前我們所面臨的形勢十分嚴峻，這已經是眾所周知的事了。我們剛挖出這些骨頭，它們就招來了一大群迅猛龍。這些兇殘的野獸殺光了我的弟兄們，並把我、麥琳和可憐的勘察員困在了這上面。$B$B幫我把濕地裡的這些迅猛龍都給殺光， $N 。雜斑迅猛龍和雜斑尖嘯龍就在山崖的西邊，要是你有能力對付它們的話，每種都給我殺上十隻。$B$B這只不過是我對它們的復仇計畫的開始而已!', '維爾加挖掘場的奧莫爾·鐵衣要求你殺死10隻雜斑迅猛龍和10隻雜斑尖嘯龍。', '', '去濕地找維爾加挖掘場的奧莫爾·鐵衣。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (295, 'zhTW', '奧莫爾的復仇', '現在是時候讓這些該死的迅猛龍為它們的嗜血而後悔了。在懸崖下面還有一些雜斑刺喉龍和雜斑鋸齒龍，每種都給我殺10隻，它們要為自己的所作所為付出代價!', '奧莫爾·鐵衣要求你殺死10隻雜斑刺喉龍和10隻雜斑鋸齒龍，然後回到維爾加挖掘場向他覆命。', '', '去濕地找維爾加挖掘場的奧莫爾·鐵衣。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 296 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (296, 'zhTW', '奧莫爾的復仇', '在你下到懸崖底部的時候，我碰巧發現了有一隻很特別的迅猛龍在那邊站著休息。它比一般的迅猛龍的體形要大得多，看起來也特別兇猛。我敢打賭它就是那群迅猛龍的首領，就是它帶著手下來這裡毀了整個挖掘場。$B$B我現在交給你最後一個任務， $N 。以正義的名義，審判薩爾圖斯!當然，考慮到它所犯下的重罪，它唯一能得到的判決就是死刑!把它的一隻爪子給我帶回來作為它已死的證據。', '維爾加挖掘場的奧莫爾·鐵衣要求你殺死薩爾圖斯，並在任務完成之後帶著它的一隻爪子向他覆命。', '', '去濕地找維爾加挖掘場的奧莫爾·鐵衣。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 297 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (297, 'zhTW', '收集塑像', '前一陣子，就在穴居人出現於此區之前，我們發現一大批奇特的塑像。但是我們還來不及研究它們，穴居人就把我們從廢墟裡趕了出來!這些塑像對穴居人有種奇特的影響。它可以讓那些穴居人變得更加瘋狂!$B$B給我拿8個塑像回來，我希望研究它們，也希望它們離開穴居人的手!整個挖掘場裡都是穴居人，你可以從他們身上拿到這些塑像。', '帶8個石刻塑像到鐵環挖掘場給麥格瑪爾‧落斧。', '', '去洛克莫丹找鐵環挖掘場的麥格瑪爾·落斧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 298 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (298, 'zhTW', '挖掘進度報告', '我這裡有一份報告要趕快送到塞爾薩瑪去─這是一份挖掘進度報告，還有一份再次重申我們需要更多的火藥粉的報告!你把它帶給吉恩·角盔，他是我們在塞爾薩瑪的聯繫人。$B$B這個任務沒什麼麻煩的，但你一定要完成它。', '把鐵環挖掘場的進度報告帶給塞爾薩瑪的吉恩·角盔。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 299 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (299, 'zhTW', '發現歷史', '在迅猛龍大舉入侵之前，我找到了一塊名叫戈奧茲之石的巨大石碑。我翻譯好的文字被分成了四部分，散落在挖掘場中的四個不同的地方。這些文字描述的是一個「神聖的計畫」和一個「註定的命運」。$B$B我們應該馬上把它們都收集起來，而不是繼續在這裡浪費時間。但是我已經很老了，恐怕沒辦法再殺出去跟那些兇猛的野獸作戰了。但是你不同，你年輕而強壯。$B$B到挖掘場裡去搜索這四片失落的石板:阿度斯石板、莫德爾石板、高爾姆石板和奈爾魯石板。它們應該被藏在某些古董器物裡，另外你也得留意土壤鬆動的地方。把它們拿回來給我，這樣我才能揭開這個秘密!', '勘察員維爾加要求你在挖掘場中搜索4塊石板的碎片，它們是阿度斯碎片、莫德爾碎片、高爾姆碎片和奈爾魯碎片。', '', '去濕地找維爾加挖掘場的勘察員維爾加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (301, 'zhTW', '向鐵爐堡報告', '我們必須得到上級的批准才能給鐵環挖掘場送去更多的火藥粉。把他的報告帶到鐵爐堡的探險者協會總部去，交給勘察員塔伯斯·雷矛。他可是個急性子的傢伙，如果聽說鐵環挖掘場的進展如此緩慢，他一定會暴跳如雷的。$B$B你可以在探險者大廳裡找到他。', '把鐵環挖掘場的進度報告交給勘察員塔伯斯·雷矛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (302, 'zhTW', '鐵環的火藥粉', '如果鐵環還需要火藥粉的話，以麥格尼的名義，就再給他送一批過去!我已經派了一個信差把我的許可交給塞爾薩瑪的吉恩·角盔，讓他負責準備火藥和其他物資。$B$B還有一件事情:我要你保證親自把這批火藥送達目的地。上一批沒有送到，中間也許出了什麼岔子，所以這次你得仔細提防著點。', '和塞爾薩瑪的吉恩·角盔談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (303, 'zhTW', '黑鐵戰爭', '戰火席捲了整個世界。當許多精銳的矮人士兵們為了聯盟而犧牲在前線時，我們自己的土地卻淪為了這群邪惡的黑鐵矮人覬覦的目標。他們已經攻陷了薩多爾大橋，丹莫德也岌岌可危。$B$B我們要你去聚集起一股力量，並將戰線推回去。如果你能殺死10名黑鐵矮人、5名黑鐵隧道工、5名黑鐵破壞者和5名黑鐵爆破兵的話，就能為我們組織反擊爭取到寶貴的時間。$B$B兵貴神速，快出發吧!', '丹莫德的莫特雷·加瑪森要求你殺死10名黑鐵矮人、5名黑鐵隧道工、5名黑鐵破壞者和5名黑鐵爆破兵。', '', '去濕地找丹莫德的莫特雷·加瑪森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (304, 'zhTW', '艱鉅的任務', '我手下的大部分士兵都在丹莫德的戰役中死去了，我的親兄弟也在薩多爾峽谷上的西橋被毀的時候不幸犧牲。唉，黑鐵矮人真是個像惡魔一般邪惡的族群。根據羅戈收集到的情報，這群在濕地四處肆虐的暴徒的領袖是一個名叫巴爾加拉斯的術士。他是個十分膽小謹慎的傢伙，在把手下的士兵送上戰場執行命令的時候，他往往卻躲藏在自己位於東南方惡鐵嶺的營地裡。$B$B如果你能找到這個懦夫，殺了他，把他的耳朵拿來給我，我會給你支付可觀的酬勞的， $C 。', '殺死邪惡的巴爾加拉斯，把他的耳朵帶給丹莫德外的布萊德·長鬚。', '', '去找濕地的布萊德·長鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 305 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (305, 'zhTW', '尋找挖掘隊', '啊，天呀，你一定就是長鬚派來的幫手!你真是不知道我有多擔心。$B$B我的老婆麥琳上個月的時候每禮拜都會給我寫一封信的。她是維爾加挖掘隊的成員，她最後一次寫信過來是兩週前的事了。一定是出了什麼事!$B$B長鬚說，要是我們一直都沒有收到挖掘隊那邊送來的信，那麼他就會派出一名斥候去看看情況。我猜那個斥候應該就是你吧，$n。快去東邊的挖掘場裡找到麥琳!', '塔雷爾·石紋要求你到挖掘場裡去找到麥琳·石紋。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (306, 'zhTW', '尋找挖掘隊', '這太恐怖啦!我們剛剛發現了一些十分稀有的古物，而且正在把這些巨大的骸骨挖掘出來，這個時候，可怕的事就發生了，在我們反應過來之前，多到數不清的雜斑迅猛龍沖進了挖掘場，咬死了許多人!$B$B勇敢非凡的奧莫爾救下了我和勘察員，並一直把我們護送到了一處藏身之所。現在我們被徹底困在這裡了，逃也逃不出去，我們努力工作的成果也全毀了。$B$B給，把這封信帶回去交給我親愛的塔雷爾，我已經在信裡把事情跟他解釋清楚了。', '到濕地的米奈希爾港，把麥琳的信件交給塔雷爾·石紋。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (307, 'zhTW', '骯髒的爪子', '東邊的銀泉礦坑很久以前就枯竭了。礦工聯盟把它改造成了儲藏庫，不過現在狗頭人佔據了那裡，用牠們的骯髒爪子染指我們矮人的精良工具!$B$B我們很快就能把這些害蟲趕走，但是礦工聯盟要求我們在衝進去大開殺戒之前，先把洞裡的礦工裝備拿出來。這是個艱難的任務，你也許需要幾個幫手。$B$B他們的裝備就散佈於礦坑四處，裝在礦工聯盟的木箱裡，祝你好運。', '到銀泉礦坑去收集4套礦工裝備，然後向巡山人雷矛覆命。', '', '去洛克莫丹找奧加茲崗哨的巡山人雷矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 308 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (308, 'zhTW', '加文的愛好', '', '', '', '去找丹莫洛的加文·雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 309 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (309, 'zhTW', '護送貨物', '準備出發了嗎，$n?$B$B首先，我們得把炸藥粉送到鐵環挖掘場。要我一個人運這麼多炸藥太困難了，這些東西又很危險──而且誰知道那幫黑鐵矮人打算對我做什麼?$B$B有你跟我一起走，我感覺就好多了。', '確保把米蘭和貨物送到挖掘場，然後通知勘察員基恩薩·鐵環。', '護送米蘭去挖掘場', '去洛克莫丹找鐵環挖掘場的勘察員基恩薩·鐵環。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 310 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (310, 'zhTW', '針鋒相對', '我不得不承認，雷酒家族的那幫傢伙釀酒水準還真不賴。但是他們應該知道他們的酒並不是世界上最好的!也許你能幫我讓他們瞭解這一點……$B$B拿著，帶著這桶熱麥酒，想辦法潛入卡拉諾斯的雷酒釀酒廠的酒窖，把他們的雷霆麥芽酒和我們的換一下。然後，我們就等著看好戲吧，顧客們肯定會更喜歡我的酒!$B$B如果有人看著酒桶的話，你就得想辦法轉移他的視線……', '到卡拉諾斯的雷酒釀酒廠酒窖裡去，把一桶雷霆麥芽酒換成熱麥酒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 311 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (311, 'zhTW', '向馬萊斯回報', '把一桶馬萊斯的熱酒放進了卡拉諾斯釀酒廠的地窖裡之後，你取回一桶雷霆麥芽酒作為行動成功的證明。', '把雷霆麥芽酒交給烈酒村的馬萊斯·麥酒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 312 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (312, 'zhTW', '馬克格拉恩的乾肉', '我原本儲備了一個月的乾醃肉準備過冬，為了防止野熊把肉銜走，我把它們鎖在了儲藏櫃裡。但是在我外出打獵的時候，一個叫做冰鬚的野獸偷走了我的儲藏櫃!可笑的是那個蠢貨撬不開這只用瑟銀鑄成的櫃子。$B$B但是如果拿不回這些肉，我就會餓死的。你的身手看來不錯，也許你能幫我取回儲藏櫃?你瞧我拖著這條廢腿也沒辦法把那只櫃子搶回來……', '從冰鬚的洞穴裡拿回裝有馬克格拉恩的乾肉的儲藏櫃。', '', '去丹莫洛找烈酒村的圖德拉·馬克格拉恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (313, 'zhTW', '灰色洞穴', '不是每個人都能駕駛攻城坦克的，你必須要有強壯的身體和鋼鐵般的神經……幸運的是，這兩個條件我都有!你呢?你有足夠的勇氣嗎?想不想證明給我看?$B$B啊……我想把我的「食人妖碾壓者」號坦克改造得更舒適些，你去幫我在卡拉諾斯西邊的灰色洞穴裡弄一堆雪怪的鬃毛來吧，我要用那些鬃毛做一張大毯子來裝飾我那「食人妖碾壓者」的駕駛艙。', '收集8束雪怪的鬃毛，把它們交給駕駛員迪恩·石輪。', '', '去丹莫洛找鋼架補給站的駕駛員迪恩·石輪。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 314 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (314, 'zhTW', '保護牲畜', '午夜的時候，我們聽到了吵鬧的聲音。今天早上我才發現羊圈裡少了兩隻羊，那頭名叫瓦加什的野獸襲擊了我們的牲畜。由於國王麥格尼的軍隊大都在遙遠的戰場上與聯盟其他的種族並肩作戰，所以沒有人能對付得了瓦加什。$B$B也許你有勇氣找到這隻猛獸並殺了它。把它的一顆牙齒交給我作為證明，我會獎賞你的。瓦加什就躲在這裡的農場附近，小心點，它非常兇殘。', '山羊農場的魯德拉·凍石要你殺了瓦加什，並且把它的牙齒給她帶回去。', '', '去找丹莫洛的魯德拉·凍石。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (315, 'zhTW', '完美的烈酒', '我正在尋找可以釀製完美烈酒的方法。我知道我能做到－釀酒就像我的本能一樣。我缺的只是一份正確的釀酒配方...$B$B霜鬃食人妖在西北邊的閃光嶺上種植了一種叫做微光草的植物。他們通常在奇怪的部族儀式才會用到它。我們還沒有發現這種草有太多的用途，不過它有種非常獨特的味道...我要試驗用這植物釀造我的酒!$B$B取得微光草可能會很危險，但不管你從食人妖的籃子裡「借」來多少，我都會好好付給你報酬。', '收集6束微光草，把它們交給烈酒村的雷傑德·麥酒。', '', '去丹莫洛找烈酒村的雷傑德·麥酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 316 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (316, 'zhTW', '<UNUSED>', '', '', '', 'Return to Test Squirrel.', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (317, 'zhTW', '貝爾丁的補給', '我正在準備為攻城坦克旅執行一項任務。這次任務會持續很長時間，所以我得預先收集能夠維持一個月的物資。貝爾丁正忙著修理我的坦克，你能幫我去弄一些東西來嗎?$B$B我需要一些毛皮來做床墊，還要一些野豬肉作為食品儲備。豬肉當然是從野豬身上割下來的，最好的毛皮是熊皮……在灰色洞穴南部的雪地上到處都是這兩種動物的蹤跡。', '收集4大塊野豬肉和2張厚熊皮，把它們交給鋼架補給站的駕駛員貝隆費茲。', '', '去丹莫洛找凍土嶺的駕駛員貝隆·風箱。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 318 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (318, 'zhTW', '艾沃沙酒', '雷傑德·麥酒一直以來都親口試驗他自己釀製的酒。有的好喝，有的難喝，還有的連酒量最好的矮人都能輕鬆放倒。$B$B他住在烈酒村，那地方就在卡拉諾斯的西邊。我需要一些他釀造的那種叫作艾沃沙的酒，在寒冷的旅程中，喝這種酒能幫我暖暖身子。$B$B還有……這種酒實在是太烈了，在緊要關頭還可以當燃料使，只要把它注入我那坦克車的油箱裡，整輛坦克都會爆發出無窮的力量!這個小訣竅讓我不止一次地化險為夷。', '從烈酒村的雷傑德·麥酒那里弄到一桶艾沃沙酒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (319, 'zhTW', '艾沃沙酒的要求', '我有一桶釀製好的艾沃沙酒，不過……你能幫我個忙嗎?烈酒村急需人手去對付在村子附近溜達的野獸。有時它們離我們非常近，那真是太危險了。$B$B我們並不害怕這些熊啊，豹啊，野豬啊─任何一個有自尊的矮人都不會害怕─不過，如果你能替我把它們搞定的話，我就能騰出更多的時間來釀酒了。', '殺掉6頭冰爪熊、8隻老峭壁野豬和8隻雪豹，然後回到烈酒村的雷傑德·麥酒那裡。', '', '去丹莫洛找寒風峽谷的雷傑德·麥酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 320 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (320, 'zhTW', '交給貝隆費茲', '這是你要的艾沃沙酒，$N。再次感謝你給予我們的幫助。', '把這桶艾沃沙酒交給鋼架補給站的駕駛員貝隆費茲。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (321, 'zhTW', '光鑄鐵', '這附近的海灘上的船隻殘骸大多是屬於庫爾提拉斯第三艦隊的，在上一次大戰中，那支艦隊曾與紅龍們在此激戰，不幸全軍覆沒了。$B$B那支艦隊裡的船大多是羅德隆的戰艦，但有一艘船卻不是，那是一艘名叫「飛翔魚鷹」的精靈驅逐艦。它運著滿滿一船的光鑄鐵加入了第三艦隊的船隊中，本以為這樣就足夠安全了，結果卻諷刺性地落得個被紅龍擊沉的厄運……$B$B故事就講到這兒吧，飛翔魚鷹的殘骸就在米奈希爾港的南邊。如果你能在那裡找到光鑄鐵的話，就把它給我帶回來吧。', '搜索飛翔魚鷹號的殘骸。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (322, 'zhTW', '祝福之臂', '暴風城矮人區有一個名叫格瑞曼德·艾爾默的矮人武器匠會用這種光鑄鐵來打造武器。$B$B我已經把你找到的這些鐵錠用木箱裝好了。把這個木箱交給格瑞曼德，再把你的事情告訴他。我敢打賭他一定會義憤填膺地馬上著手為你打造武器的，嘿嘿，那肯定是把就連摩本特·費爾看到了也會心驚膽顫的武器!', '將光鑄鐵錠木箱交給格瑞曼德·艾爾默。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (323, 'zhTW', '證明你的實力', '摩本特·費爾是個死靈法師，也是黑騎兵的幫兇。我希望你能去除掉摩本特·費爾，不過在瞭解你真正的實力之前，我還不能貿然拿你的生命開玩笑。$B$B你已經證明了你的勇氣，不過如果你想要面對面地和這個死靈法師作戰，首先得證明你能應付得了他的爪牙。', '殺掉15個骷髏劫掠者、3個骷髏醫者和3個骷髏守衛，然後回來見斯溫。', '', '去找暮色森林的斯溫·猶根。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (324, 'zhTW', '丟失的鐵錠', '你好不容易把那塊光鑄鐵錠從泡在水裡的箱子中拿了出來，顯然，是魚人偷走了其餘的鐵錠。獵殺飛翔魚鷹號殘骸周圍的魚人，拿到它們身上帶著的光鑄鐵錠。', '收集5塊光鑄鐵錠，把它們交給濕地的戈羅林·鋼眉。', '', '去濕地找米奈希爾港的戈羅林·鋼眉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 325 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (325, 'zhTW', '整裝待發', '你已經準備好了嗎，$N?祝你好運!我期待著你凱旋歸來!', '現在你已經得到了強大的武器，去向暮色森林的斯溫覆命吧。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (326, 'zhTW', '暫無內容', 'x', 'x', '', '去找。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (327, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (328, 'zhTW', '隱藏的鑰匙', '儘管在這些檔案檔案裡都沒有提到士兵托爾森，但你發現在赫羅德的一本帳薄後面綁著一隻小小的黃銅鑰匙。$B$B你還在研究他的其它筆記時發現了其中有一小部分提到，在一個“安全的保險箱”中裝有大量的檔案。這個保險箱應該在庫爾森營地後山的某處洞穴之中，他們管那裡叫“儲藏室”。$B$B如果你能找到這個保險箱並用這把黃銅鑰匙開啟它的話，或許裡面的檔案有助於找到導致托爾森身份暴露的內鬼。', '使用黃銅鑰匙開啟書呆子赫羅德的保險箱。', '', '去找荊棘谷書呆子赫羅德的保險箱。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 329 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (329, 'zhTW', '找出內鬼！', '在箱子裡的這些貴重物品之中，還有一張滿是灰塵且寫得十分潦草的便箋。儘管幾乎已經沒法辨認了，但你能看出來這便箋上面似乎描述了士兵托爾森所走的路線。這應該是他的巡邏路線，以及反抗軍方面與他接頭的人員與時間。簽名只有一個字母：M。$B$B毫無疑問，這應該是托爾森身邊的人寫下的便箋，而且這個人就是反抗軍營地中的臥底。', '將沾泥的便箋交給反抗軍營地裡的多倫中尉。', '', '去荊棘谷找反抗軍營地的多倫中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 330 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (330, 'zhTW', '巡邏時間表', '你給我的便箋上的簽名只有一個字母“M”……我也不知道這代表誰。$B$B但是……這便箋同時也告訴我們，這個人應該是上週與托爾森一同巡邏的同伴。所以，只要知道上週誰和托爾森一起巡邏過，那他就應該是內鬼沒錯了！$B$B去找塞斯曼下士問一問，他是負責制訂巡邏時間表的人，可以告訴你那個時候托爾森和誰在一起。', '與塞斯曼下士談一談。', '', '去荊棘谷找反抗軍營地的塞斯曼下士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 331 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (331, 'zhTW', '向多倫報告', '多倫中尉不是說要你向他回報關於巡邏時間安排的情況嗎？', '與多倫中尉談一談。', '', '去荊棘谷找反抗軍營地的多倫中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 332 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (332, 'zhTW', '酒店的廣告', '無論你跟任何人談起酒，大家都會告訴你加林納家賣的酒是全暴風城最好的。而且那裡離我們這兒並不遠，就在貿易區中，運河的邊上。$B$B給，拿著這張酒票。把這個拿到店裡去，交給我的姐姐蘇澤塔，她會送你一瓶我們釀造的最有名的黑葡萄酒。你絕對不會後悔的!', '到加林納酒店去, 將酒票交給蘇澤塔·加林納以換一瓶免費的酒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 333 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (333, 'zhTW', '哈蘭需要供貨', '我們過幾天肯定會有大單的生意。現在似乎每個人都在購買盔甲和結實的衣服，好像他們都以為明天就會變得天寒地凍一樣……$B$B但那是以後的事了。我現在最擔心的是我已經賣完了全部庫存的編織布，需要一次大批量的供貨。$B$B如果你能把我的這個要求帶給運河裁縫店的雷瑪·施涅德的話，我會非常感謝你的。', '找到運河裁縫店，並將哈蘭·巴格雷的布料訂單帶給雷瑪·施涅德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 334 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (334, 'zhTW', '薩爾曼的針線包', '我的兒子薩爾曼在法師區的拉爾森服裝店裡當學徒。他今天早上走得太著急了，忘了他的剪子和針線。我知道你這樣偉大的$C一般都會有些重要的事要做，可要是沒了工具的話，薩爾曼可沒辦法做他的工作呀!$B$B拜託了，$N。你能幫我把他的針線包拿去給他嗎?拉爾森服裝店是法師區裡的兩家裁縫店之一，在比較靠裡面的地方，也就是靠近法師塔的地方。', '到暴風城法師區的拉爾森服裝店去，將針線包帶給薩爾曼·斯涅德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 335 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (335, 'zhTW', '名釀', '維沙克領主最近正在貴族議會中造成了一股騷動。他知道我們的小小「建立」，而且還遊說其他議員進行一次全面調查。我有一個計畫能讓維沙克「忙不過來」，但我需要你的幫助。$B$B在夜色鎮郊區的斯塔文花園裡生長著一種名叫蒂羅亞之淚的白色小花。另外我還需要一些麝鼠根，那種東西只生長在濕地，就在巨石水壩下的瀑布底部。', '黑爪加爾德斯要求你從夜色鎮給他摘1朵蒂羅亞之淚，再從濕地給他采一塊麝鼠根。', '', '去找暴風城的黑爪加爾德斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 336 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (336, 'zhTW', '名釀', '維沙克領主與所有人一樣有自己的弱點，他對酒的愛好勝過一切。更可惡的是，這個蠢貨整天想著把我們這個小小的酒館給弄關門了，而他自己卻待在樓上整夜整夜地喝個不停，至於那些像滾雪球一樣越攢越多的帳單，他是肯定不會付的。好吧，讓我們看看維沙克會有多喜歡我們給他準備的這種特製佳釀:黑爪烈酒。這一定會很有意思的，$n。$B$B把這個帶給他，看看他的反應如何，我覺得這傻瓜可能會在祈願室裡當場開喝。', '將黑爪烈酒帶給祈願室裡的維沙克領主。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 337 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (337, 'zhTW', '一本破舊的歷史書', '這本書的封面已經有被刮壞的痕跡，還沾上了泥汙，但是書脊上「暴風城的歷史」的字樣仍然清晰可見。打開書的第一頁，可以看到上面蓋著暴風城圖書館的徽印。$B$B看起來似乎有人從圖書館借出了這本書卻從來沒有歸還……', '把《暴風城的歷史》這本書還給暴風城圖書館。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 338 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (338, 'zhTW', '荊棘谷的青山', '如果奈辛瓦里知道了這一切，他一定會很生氣的!$B$B出於對我的信任，他讓我來校對他的小說《荊棘谷的青山》的手稿。一開始事情進行得非常順利，但昨天一陣大風吹過了營地，結果把手稿吹得滿天都是!$B$B我已經很努力地找回了大部分的書頁，但還是有幾頁被吹進了叢林中。請你幫我把這四章裡的掉落的那幾頁書都給收集起來吧。$B$B等這四章手稿都搜集齊了以後，把它們還給我。', '收集《荊棘谷的青山》的手稿中丟失的頁面。在集齊四章書之後，將它們還給巴尼爾·石罐。', '', '去荊棘谷找奈辛瓦里遠征隊營地的巴尼爾·石罐。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 339 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (339, 'zhTW', '荊棘谷的青山 - 第一章', '第一章實在是太精彩了，令人欲罷不能!奈辛瓦里設定了小說的背景，而且在小說裡提到了他的同伴們，甚至包括我!$B$B不過，糟糕的是……有幾頁好像弄丟了。似乎第1頁，第4頁，第6頁和第8頁落在叢林中的什麼地方了!', '將奈辛瓦里的小說《荊棘谷的青山》的第1頁，第4頁，第6頁和第8頁帶給巴尼爾·石罐以湊齊第一章。', '', '去荊棘谷找奈辛瓦里遠征隊營地的巴尼爾·石罐。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 340 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (340, 'zhTW', '荊棘谷的青山 - 第二章', '第二章是整個激動人心的狩獵故事的楔子。可是裡面也有幾頁找不到了，我真想踢自己幾腳!$B$B看來我必須得找到第10頁，第11頁，第14頁和第16頁才能湊出完整的第二章。', '將奈辛瓦里的小說《荊棘谷的青山》的第10頁，第11頁，第14頁和第16頁帶給巴尼爾·石罐以湊齊第二章。', '', '去荊棘谷找奈辛瓦里遠征隊營地的巴尼爾·石罐。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (341, 'zhTW', '荊棘谷的青山 - 第三章', '第三章是我最喜愛的部分。裡面詳細講述了艾爾加丁爵士和羅歐克女士使用矮人步槍完成的第一次狩獵。而且第三章的結尾也寫得極好，為什麼?因為實在是太扣人心弦了!$B$B不過，讓我看看，似乎我們仍然要需要找回第18頁，第20頁，第21頁和第24頁來湊齊這一章。這些書頁不知被風吹到哪裡去了……', '將奈辛瓦里的小說《荊棘谷的青山》的第18頁，第20頁，第21頁和第24頁帶給巴尼爾·石罐以湊齊第三章。', '', '去荊棘谷找奈辛瓦里遠征隊營地的巴尼爾·石罐。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (342, 'zhTW', '荊棘谷的青山 - 第四章', '啊，第四章，大結局!多麼精彩的結局啊!$B$B第四章裡我們只丟了3頁，也就是第25頁，第26頁和第27頁。', '將奈辛瓦里的小說《荊棘谷的青山》的第25頁，第26頁和第27頁帶給巴尼爾·石罐以湊齊第四章。', '', '去荊棘谷找奈辛瓦里遠征隊營地的巴尼爾·石罐。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (343, 'zhTW', '關於堅韌的演講', '我正要作一次關於「堅韌的靈魂」的演講，我想引用一本關於金屬學的著作《金屬的延展性》裡的一些段落。暴風城堡裡的皇家圖書館裡應該有這本書的副本。你能把它拿來給我嗎?如果可以的話，聖光定會保佑你的!皇家圖書館很大，但首席管理員密爾頓·西弗對每一個書架上有些什麼書都瞭若指掌。告訴他我需要什麼，他就會把書找給你的。', '到暴風城堡的皇家圖書館去與密爾頓·西弗交談，他將會為你找到克里斯多夫修士所需要的關於冶金學的書。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (344, 'zhTW', '帕克斯頓修士', '《金屬的延展性》?是的，我知道這本書。那是本非常好的書，是十幾年前一位矮人礦工馬戈爾夫·布拉貢寫的。他的一生似乎都奉獻給了卡茲莫丹的群山，整日在那裡挖礦。他是個很聰明的傢伙!但這書在哪來著?哦，對了，《金屬的延展性》!這本書被我送到北郡修道院去了。那裡的管理員帕克斯頓修士想為他那裡的圖書館抄寫一份留作副本。但這是幾個月前的事了，我不知道他為什麼會花這麼長的時間……', '與北郡修道院的帕克斯頓修士談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 345 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (345, 'zhTW', '墨水補給', '我也想把《鐵的延展性》這本書儘快抄完，但是……你看看，我只用自己做的墨水抄寫書籍。這墨水是用我自己的配方製作的;它不容易暈開，也不容易弄髒紙，而且乾的很快，很不幸的，它乾得太快了!我的最後一瓶墨水在我抄完之前就乾掉了，而且我也還無法去做新的墨水!要想再配點墨水的話，我就得先弄到一些赤脊山的瑞斯班鐵礦石，一直以來，這種礦石都是由湖畔鎮的工頭奧斯洛為我提供的。', '與湖畔鎮的工頭奧斯洛交談，並向他要一些瑞斯班鐵礦石。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 346 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (346, 'zhTW', '克里斯多夫的書', '現在我已經把這本書抄完了，這裡是《金屬的延展性》的原本。感謝你的耐心，還有，如果你見到密爾頓的話，請替我向他道歉，我拖了那麼長時間真有些不好意思。', '回到教堂廣場，將《金屬的延展性》交給克里斯多夫修士。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 347 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (347, 'zhTW', '瑞斯班礦石', '瑞斯班礦石是根據第一個發現他的人─巴爾特·瑞斯班─的名字來命名的。這種礦石在冶煉之後雖然沒有鐵那麼堅硬，但它有一種純正的黑色，許多抄寫員都用它來製作墨水或染料。在北邊的瑞斯班礦坑裡就可以找到這種礦石。$B$B我們通常會有一些存貨，但最近大家都忙於抵抗獸人的進攻，沒空去採集這種礦石。此外……這段時間以來，赤脊豺狼人佔據了瑞斯班礦坑，而且他們的苦工也正在採集這些礦石。$B$B所以如果你需要的話，就得自己去那裡找了。', '收集5袋瑞斯班礦石，把它們帶給北郡圖書館的帕克斯頓修士。', '', '去艾爾文森林找北郡山谷的帕克斯頓修士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 348 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (348, 'zhTW', '荊棘谷熱疫', '我病了...病得...非常厲害...$B$B我...染上了...荊棘谷熱疫...致死的疾...疾病...$B$B...只...只有吃下...野人莫...莫...莫克...的心臟...才...才有救...那...是...一隻殘忍而...狡猾的...野獸。$B$B...巫醫安巴格瓦...是...唯一會...召喚...它...的人...$B$B找到...住在南邊...靈魂...洞穴...裡的安巴格瓦...$B$B...快點...我就要死了...就要死了...', '找到巫醫安巴格瓦並要求他召喚出野人莫克，然後將野人莫克的心臟交給芬·菲茲拉克。', '', '去荊棘谷找藏寶海灣的芬·菲茲拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 349 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (349, 'zhTW', '荊棘谷熱疫', '', '', '', '去找荊棘谷的巫醫安巴格瓦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 350 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (350, 'zhTW', '老朋友', '馬爾松曾和迪菲亞兄弟會的一個成員進行聯繫，而且萊斯科瓦似乎也脫不了干係……在范克里夫和特雷德被殺之後，萊斯科瓦依然逍遙法外，我們手上還是沒有他罪行的證據。除了證據問題之外，萊斯科瓦本身就是個神通廣大的貴族，這些優勢讓他得以淩駕於法律之上。你需要幫助。雖然我並不很情願走這一步棋，但是的確有一個可以幫助我們的人。你應該到暴風城的貿易區去找提亞斯。', '與暴風城的伊林·提亞斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 351 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (351, 'zhTW', '尋找OOX-17/TN！', '你發現了一個奇怪的蛋形金屬物體。隨便撥弄了幾下之後，它居然開啟了，變成了一個看起來像是由地精創造的那種機器裝置！一個噼裡啪啦的聲音從這個蛋形機器裝置中傳了出來。$B$B“我的名字叫奧格索普，我的母體機器人不見了！如果你能幫我找到它的話，我會獎勵你的！請把這個定向器帶到我的母體機器人那裡。我現在已經為你勘探出了它的所在地！它現在就在塔納利斯的大裂口那裡！”', '把定位器帶到奧格索普的母體機器人那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 352 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (352, 'zhTW', '<UNUSED>', '偉大的瑪莫達啊。她體型龐大，爪子和牙齒銳利如劍。當時我毫無防備，不過就算有所準備，恐怕也於事無補。她只是一揮爪——咻！眼前一片黑暗。他們都說我現在還能走路已經算走運了……$B$B唉，聽這種陳年往事想必也沒什麼樂趣可言吧？總之，$n，如果你想親自會會她——那位湖中夫人的話，', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 353 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (353, 'zhTW', '雷矛的包裹', '雷矛氏族是一個倍受尊敬的矮人氏族，他們向來以獨具慧眼著稱─所以遠在鐵爐堡的格林戈·雷矛才會托人不遠千里地讓人傳信，委託我幫他們製造一把武器，哈哈!$B$B這把武器已經完成了，但是巡山人雷矛住在洛克莫丹，離這裡實在是太遠了。如果你正好要到那邊去的話，就替我把這個包裹帶給他吧。$B$B巡山人雷矛最後一次和我聯絡的時候，他說他在洛克莫丹北部的哨塔裡。', '把給雷矛的包裹交給洛克莫丹北部哨塔里的巡山人雷矛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 354 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (354, 'zhTW', '阿加曼德家族', '阿加曼德家族曾是提里斯法林地中最富有的家族。我過去曾在他們的磨坊裡工作……當然，我是說在瘟疫降臨之前。$B$B天譴軍團入侵的時候，阿加曼德家族的人們加固了他們的莊園，並說服了在他們家做工的人留下來幫助他們抵抗天譴軍團。我們實在是太蠢了，但我們至少是愚蠢而忠誠。$B$B而阿加曼德家族用榮耀之類的幌子讓我們去送死，結果現在他們倒成了天譴軍團的走狗!$B$B為了被遺忘者，你必須去剿滅墮落於瘟疫之中的阿加曼德家族!把他們的屍體帶回來給我。', '把格里高的遺骸、妮薩的殘骸和薩爾曼的遺骸交給布瑞爾的庫勒曼·法席恩。', '', '去提里斯法林地找布瑞爾的庫勒曼·法席恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 355 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (355, 'zhTW', '與塞弗倫交談', '你把阿加曼德家族所有人的遺骸都帶來給我了，也滿足了我復仇的慾望。但阿加曼德磨坊對我，哦，不僅僅是對我，對我們全體被遺忘者來說仍是個威脅。我已經把你與阿加曼德家族戰鬥的事蹟告訴了執政官塞弗倫大人，他也希望能和你談談。', '與布瑞爾的執政官塞弗倫談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 356 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (356, 'zhTW', '巡查後方', '亡靈壁壘上的衛兵們時刻都在提防著從瘟疫之地潛入提里斯法的敵人，但仍有些天譴軍團的士兵能躲過這樣的警戒線。$B$B我們必須專注在一個戰線上才有辦法在亡靈壁壘獲得勝利!我們絕對不能腹背受敵，更不能容許補給線遭到切斷。$B$B往西邊巡邏過去，消滅你所找到任何的天譴軍團爪牙。特別注意一下巴尼爾農場，那裡已經充斥著天譴軍團的爪牙了。', '殺死8個可怕的血殭屍和8個遊蕩的幽靈，然後向亡靈衛兵林奈彙報。', '', '去找提里斯法林地的亡靈衛兵林奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 357 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (357, 'zhTW', '巫妖的身份', '北邊澈水湖中的一個小島上住著一個巫妖。雖然他是個擁有自主意志的被遺忘者，不過他認為其他所有的不死生物都是天譴軍團的奴隸，他的爪牙會襲擊任何靠近他的人。$B$B他是個無主之人，所以黑暗女王想要招降他。如果他確實精通於巫術的話，那麼他的知識會對我們很有幫助。$B$B不過我得先看過他的法術書才能瞭解他的身份和學問。潛入他的營地，把書拿回來見我。', '把巫妖的法術書帶給幽暗城的比索·埃斯沙德。', '', '去找提裏斯法林地的比索·埃斯沙德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (358, 'zhTW', '盜墓賊', '北邊的加倫鬼屋你去過嗎?那個地區的西南角是一大片亂葬崗，裡面葬著提里斯法一帶的大量因瘟疫而死的人。$B$B那邊墳墓裡的屍體大多沒能變亡靈，但最近天譴軍團派出了一群腐皮豺狼人到那裡去收集屍體，以此來壯大他們的軍隊。我們不能允許這樣的事情發生!$B$B你的任務有兩個:殺光躲在亂葬崗和加倫鬼屋裡的腐皮豺狼人，並把他們身上的防腐劑搶回來，正是這種防腐劑使他們活過來的。', '殺死腐皮盜墓賊和混血腐皮豺狼人。給布瑞爾的執政官塞弗倫帶回8瓶防腐劑。', '', '去提里斯法林地找布瑞爾的執政官塞弗倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (359, 'zhTW', '亡靈衛兵的職責', '我要這裡東邊的亡靈衛兵驛站立刻給我提交一份最新的報告。我必須知道天譴軍團是否已經迂迴繞過了防波堤並進入了提里斯法林地。我們要時刻保持警惕，封鎖住這裡與瘟疫之地的邊境，絕對不能讓天譴軍團佔據這裡的任何一寸土地!沿著路向南走，在第一個岔路口轉向東，就可以到達驛站了。到那裡去找亡靈衛兵林奈，她手裡掌握著我最需要的情報。', '與亡靈衛兵林奈談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (360, 'zhTW', '向塞弗倫回報', '現在帶著這些情報回到執政官塞弗倫那裡去吧。他急需這幾份報告，你動作最好快點。如果你回程的路上看見了任何天譴軍團的成員，就順便幹掉他們，我們可不能讓這些垃圾在我們的地盤上胡作非為。', '向布瑞爾的執政官塞弗倫報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (361, 'zhTW', '未寄出的信件', '這封信的作者是格里高·阿加曼德的長子薩爾曼。收件人則是一位名為伊維特·法席恩的女士，儘管現在看來這封信顯然是沒寄到她手上……', '找到伊維特·法席恩，將薩爾曼·阿加曼德的信交給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (362, 'zhTW', '鬧鬼的磨坊', '代弗林·阿加曼德是阿加曼德家的兩個男孩中最小的一個，但這兩個男孩子卻完全不像是兄弟。薩爾曼身材高大而且待人彬彬有禮，而他的弟弟代弗林卻身體虛弱，而且嘴巴很刻薄惡毒。$B$B當阿加曼德磨坊遭遇瘟疫的時候，他是第一個被感染的。現在，只要你靠近通向阿加曼德磨坊的道路，就仍能聽見他那喋喋不休的囈語。$B$B我正在收集阿加曼德家族所有人的遺骸，首先，我想弄到可憐的代弗林的屍骨。找到並摧毀他，然後把他的遺骨帶回來給我。', '殺死代弗林·阿加曼德，然後將代弗林的遺骸交給布瑞爾的庫勒曼·法席恩。', '', '去提里斯法林地找布瑞爾的庫勒曼·法席恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (363, 'zhTW', '突然醒來', '你醒得可真是時候。我們本來還準備把你和其他的死人一起火葬了，沒想到你居然醒來了。我是摩爾多，喪鐘鎮墓穴的看護人。現在你已不再是巫妖王的奴隸了。暗影牧師薩維斯就在山腳下的教堂裡，去和他談談吧，他會告訴你更多你必須瞭解的事情。', '和暗影牧師薩維斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (364, 'zhTW', '無腦的殭屍', '從第一個被遺忘者從墓穴中爬出那時開始，我們就在與巫妖王的天譴軍團作戰，那支大軍包含了被死靈法術喚起的不死生物部隊、生長於大陸北方的愚蠢野獸，還有永遠遭受痛苦折磨的幽靈。$B$B巫妖王已不再君臨冰封王座之上，但這個村莊的北部仍有他的奴隸們在四處橫行。消滅他們。儘管他們可能曾是我們的兄弟姐妹，也絕對不要留情。', '殺掉5個無腦的殭屍和5個悲慘的食屍鬼。', '', '去提里斯法林地找喪鐘鎮的暗影牧師薩維斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (365, 'zhTW', '悲傷之地', '看看誰來了?你看起來是個菜鳥 $C 吧。如果你想向黑暗女王陛下證明自己的實力，就得先學會我們被遺忘者行事的幾條基本原則。$B$B這裡的西邊有個農場，人類寄生其上有如腐屍身上的黴菌。更糟糕的是，血色十字軍會從他們的哨塔到附近巡邏。給這些渣滓們好好地上一課吧，把他們的寶貝南瓜給我偷10顆來。$B$B偷到10顆南瓜以後，就把它們交給布瑞爾的藥劑師喬漢。', '從位於布瑞爾西邊、喪鐘鎮北邊的農場中偷10顆南瓜來，把它們交給布瑞爾的藥劑師喬漢。', '', '去提里斯法林地找布瑞爾的藥劑師喬漢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (366, 'zhTW', '歸還書籍', '很久以前，岡瑟爾和我，還有現在隸屬於天譴軍團的圖勒·鴉爪，我們三人是很好的朋友，我們曾一起在祈倫托學習魔法。$B$B岡瑟爾和我都是大瘟疫的犧牲品，岡瑟爾後來成為了巫妖王的手下。現在我得知他脫離了巫妖王的魔爪，這真是個好消息。$B$B我們一定要找到他。我給他的書上施放了一個魔咒，當他看到這本書的時候就會知道我也已經擺脫了巫妖王的控制，希望他在知道這一點以後會加入我們。', '到岡瑟爾居住的小島去歸還他的法術書。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (367, 'zhTW', '新的瘟疫', '希瓦娜斯大人最近交給了我們皇家藥劑師學會一項很有挑戰性的命令。黑暗女王相信我們的知識與新發明的魔法將會是她擊敗阿薩斯的有力武器，她要求我們研製出一種新的瘟疫，這種瘟疫要比以前出現在艾澤拉斯大陸上的任何一種疾病都要更加猛烈，它會把阿薩斯和他的天譴軍團徹底毀滅。$B$B我的研究結果表明，野獸的血液也許是一種重要的藥引。給我帶回五瓶黑暗犬的血液來，我要驗證一下自己的理論。', '布瑞爾鎮裡的藥劑師喬漢要求你收集5瓶黑暗犬的血液。', '', '去提里斯法林地找布瑞爾的藥劑師喬漢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (368, 'zhTW', '新的瘟疫', '在你幫我收集樣本的同時，我的實驗報告也出來了。看來我還需要更多的材料來進行進一步的研究，適當加強這種新瘟疫的傳染能力。毒殺個把倒楣鬼，那是小孩子才玩的把戲，只有將瘟疫傳遍整個世界才算得上是有意義的事。$B$B我需要5片邪鰭魚人身上的鱗片，在北邊或者西邊的海灘上應該就能找到那些魚人。', '布瑞爾鎮裡的藥劑師喬漢要求你收集5片提里斯法林地的邪鰭魚人的鱗片。', '', '去提里斯法林地找布瑞爾的藥劑師喬漢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (369, 'zhTW', '新的瘟疫', '在你出去收集鱗片的時候，我已經在我的藏書中找到了一些古老而有趣的文章。這些文章裡面提到，以前曾有一種古代的瘟疫殺死過成百上千的人，而後來又有人發現在夜行蜘蛛的毒液中就能提取到這種瘟疫的致病物質。$B$B給我帶些夜行蜘蛛的毒液來，讓我完成這個實驗。我想知道毒液中的感染性元素是否能和我最新研製出來的瘟疫病原體共存。據說這種蜘蛛一般在提里斯法林地的東部出沒。', '布瑞爾鎮裡的藥劑師喬漢要你去收集4份邪惡的夜行蜘蛛的毒液樣本。', '', '去提里斯法林地找布瑞爾的藥劑師喬漢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (370, 'zhTW', '與血色十字軍的戰爭', '執行官阿倫的檔案中對如何清除這群在我們土地上肆虐的人類問題作了詳細的部署。情報表明，血色十字軍派遣了派瑞恩隊長以及足有一個整編旅的部隊進駐了布瑞爾西南方的廢塔。$B$B去殺掉派瑞恩隊長、3名血色十字軍狂熱者和3名血色十字軍傳教士，然後向我回報。', '布瑞爾的執行官塞加德要求你殺掉派瑞恩隊長、3名血色狂熱者和3名血色傳教士。', '', '去提里斯法林地找布瑞爾的執行官塞加德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (371, 'zhTW', '與血色十字軍的戰爭', '我們仍然處於戰爭狀態中，而且血色十字軍正在逐漸壯大。執行官阿倫給我的報告中提到，在瓦松隊長的指揮下，血色十字軍正以提里斯法東南部巴尼爾農場附近的那座廢塔為據點肆意劫掠。$B$B去殺掉瓦松和5名血色十字軍苦行修士，這對十字軍來說將是一次沉重的打擊!', '布瑞爾的執行官塞加德要求你殺掉瓦松隊長和5名血色苦行修士。', '', '去提里斯法林地找布瑞爾的執行官塞加德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (372, 'zhTW', '與血色十字軍的戰爭', '血色十字軍已經從提里斯法林地北部的廢塔出發，穿過了法奧之墓。根據目前我們所掌握的情報，一個名叫麥拉其的軍官指揮著這支邪惡的部隊，他是個非常殘忍的傢伙。$B$B我相信你能完成這個非常重要而又危險的任務。以黑暗女王陛下的名義，殺死麥拉其和他的兩名保鏢!', '布瑞爾的執行官塞加德要求你刺殺麥拉其隊長及他的兩名保鏢。', '', '去提里斯法林地找布瑞爾的執行官塞加德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 373 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (373, 'zhTW', '未寄出的信', '搜查艾德溫·范克里夫的屍體時，你從一堆雜亂的物品中找到了一封還未來得及發出的信。地址一欄上寫著巴洛斯·艾力克斯頓，暴風城石匠公會，城市大廳，教堂廣場。$B$B這顯然是最近剛剛寫好並封上的。', '將艾德溫·范克里夫的信交給巴洛斯·艾力克斯頓。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (374, 'zhTW', '死亡證明', '執行官塞加德告訴我說你最近和血色十字軍交戰，提里斯法林地裡現在到處都是這幫討厭的傢伙。$B$B黑暗女王麾下的瓦里瑪薩斯大人計畫將人類這種艾澤拉斯大陸上的渣滓與垃圾徹底清除掉。但目前的狀況是，人類當中最麻煩的一群傢伙─血色十字軍─已經殺入了提里斯法林地，我們必須得面對他們的挑釁。$B$B去吧，去給這群該死的血色十字軍一點顏色看看， $C 。給我帶回10枚血色十字軍徽記之戒，以此證明你對偉大的黑暗女王陛下與瓦里瑪薩斯大人的忠誠。', '給布瑞爾的亡靈衛兵伯吉斯帶回10枚血色十字軍徽記之戒。', '', '去提里斯法林地找布瑞爾的亡靈衛兵伯吉斯。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (375, 'zhTW', '死亡之寒', '好冷啊...可怕的瘟疫正如冰冷的毒蛇一般在我的血管中逡巡，也許很快我就會徹底失去意志，但這世上沒有任何東西能夠阻止我為我們偉大的黑暗女王效命。一接到命令，我就開始為希瓦娜斯大人軍隊中那些死去的戰士縫製屍袋。$B$B但現在我的手卻因為寒冷而顫慄不已。如果你能給我帶回五張夜行蝙蝠的毛皮和一些粗線的話，我就可以給自己縫條毯子了。幫幫我， $N ，這樣我就可以繼續為黑暗女王陛下的事業效力了。', '給布瑞爾的格雷森·戴德馬帶回5張夜行蝙蝠的毛皮和一些粗線。', '', '去提里斯法林地找布瑞爾的格莉絲·戴瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 376 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (376, 'zhTW', '被詛咒者', '我的任務包括照料受傷的士兵，縫製鎧甲和衣服，還有為暗影牧師薩維斯提供任何他可能需要的支援。$B$B看起來，你也即將加入到為他效力的隊伍中...我猜是要獵殺那些沒腦子的傢伙。好吧，如果你還想留著你的小命的話─我想你一定是的─也許我能幫助你。我這裡沒有足夠的狼爪子和蝙蝠翅膀了，如果你能幫我弄一些來的話，我會幫你找幾件鎧甲。在這裡的西北方可以找到大群的狼和蝙蝠。', '新兵艾爾雷斯需要6隻食腐狼的爪子和6隻夜行蝙蝠翼。', '', '去提里斯法林地找喪鐘鎮的新兵艾爾雷斯。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 377 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (377, 'zhTW', '罪與罰', '貴族議會好像嫌他們對暮色森林的漠不關心還不夠過分，現在他們居然無視夜色鎮議會的存在，決定把迪克斯特·瓦德囚禁在暴風城，而不是按照埃伯洛克大人的判決將這個惡棍斬首!$B$B迪克斯特·瓦德是在把墓地裡的屍體賣給摩本特·費爾時被抓住的，這理應是死罪。可是暴風城卻認為他們才擁有對他的處決權!$B$B去暴風城的監獄把瓦德殺掉，把他的手給我帶回來作為證明，我會獎賞你的。', '夜色鎮的米爾斯泰普議員要你殺死迪克斯特·瓦德，並把他的手帶回來作為證明。', '', '去暮色森林找夜色鎮的議員米爾斯迪普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 378 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (378, 'zhTW', '積怒已久', '你已經向我們展示出了你對麥格尼陛下的忠誠， $C 。而且我也深刻地感受到了你對那些黑鐵矮人的仇恨。$B$B我必須要堅守崗位，因此，我不得不把一個本應由我親自去完成的重要任務交給你。根據羅戈收集到的情報顯示，卡姆·深怒正是襲擊薩多爾大橋的元兇。由於他所布下的邪惡計畫，長鬚才失去了他的親人。$B$B這個劊子手由於某些政治原因被扣押在了暴風城的監獄裡。我要他死， $N 。為了長鬚!殺死卡姆·深怒，把他的腦袋給我帶回來!', '丹莫德的莫特雷·加瑪森要求你把卡姆·深怒的頭顱交給他。', '', '去濕地找丹莫德的莫特雷·加瑪森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 379 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (379, 'zhTW', '口渴的比格維茲', '你需要能量源，我可以幫你。但是你知道我要什麼嗎？我要喝的！給我弄五隻廢土水袋來，然後我就會把4711-FTZ交給你。$B$B現在……你想知道在什麼地方可以找到廢土水袋，對嗎？去這裡的東邊找廢土遊牧民吧，他們身上會帶著這種水袋。', '給加基森的首席工程師比格維茲帶去五隻廢土水袋。', '', '去塔納利斯找加基森的首席工程師比格維茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (380, 'zhTW', '夜行蜘蛛洞穴', '我們的一項最重要的任務就是獲取賴以生存的自然資源。即使在當年聯盟最鼎盛的時候，黃金資源也是非常缺乏的。$B$B這裡的西北面有一處金礦，我們需要礦坑裡的資源，但是那裡蜘蛛橫行，我們根本無法進去採掘金礦。我手上沒有人可以去完成這項任務，所以我們只有一步一步慢慢地來。去那裡看看吧，也許你能做些什麼……', '執行官阿倫要你去殺掉8隻小夜行蜘蛛和5隻夜行蜘蛛。', '', '去提里斯法林地找喪鐘鎮的執行官阿倫。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (381, 'zhTW', '血色十字軍', '得知我們在金礦的進展非常順利，你一定很開心吧?得益於你的幫助，我們終於可以把注意力放到別的事情上了。$B$B我的斥候報告說，一支血色十字軍的小分隊在東南方建立了營地。血色十字軍是一個卑鄙的組織，他們視我們為死敵，只要有一個不死生物─無論是巫妖王的爪牙還是我們被遺忘者─還活著，他們就不會停止追殺我們的行動。所以我們必須先發制人!$B$B你要多加小心，這些邪惡而狂妄的十字軍是一群非常危險的傢伙。', '從血色信徒和血色新兵身上收集12枚血色十字軍臂環，把它們交給執行官阿倫。', '', '去提里斯法林地找喪鐘鎮的執行官阿倫。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (382, 'zhTW', '十字軍信差', '布瑞爾那邊的上級發來給我的檔案顯示，有一個從血色修道院出發的血色十字軍斥候已經潛入了喪鐘鎮。有報告說這個人攜帶著非常重要的情報。至於更多的細節，我不得而知。但不管怎麼樣，我們必須得到這份情報!$B$B你是我眼前能配合調動的最適人選， $N 。找到那個信差，帶回你能取得的任何情報。', '到十字軍營地去殺掉信差邁文·考加爾，將你發現的情報交給執行官阿倫。', '', '去提里斯法林地找喪鐘鎮的執行官阿倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (383, 'zhTW', '重要情報', '我必須將這些東西交給我的上級─執行官塞加德，他就在布瑞爾。有了這份詳盡的情報，我們就能給血色十字軍以沉重的打擊。你在喪鐘鎮對我們做出了很大的貢獻，現在我要你去把這份情報及時交給塞加德，我想他能幫你找到更多能讓你大展身手的工作。$B$B沿著這條路向北走出喪鐘鎮，在進入提里斯法林地以後，你很快就會來到一個十字路口，這時向東走，然後一直向前就可以到布瑞爾了，路上有一座爐灰莊園可以幫你確認自己的方向。', '把血色十字軍檔案交給布瑞爾的執行官塞加德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (384, 'zhTW', '啤酒烤豬排', '啤酒烤豬排是我的老主顧們最喜歡的大餐!問題是，為我提供豬排的獵手被國王徵募去打仗了。$B$B也許你能幫幫我?如果你可以給我弄六塊峭壁野豬肋排，外加一杯酒店裡賣的狂想麥酒的話，我就把祖傳的啤酒烤豬排的烹飪方法教給你，而且我還可以讓你免費品嘗我做出來的美食!秘密就在麥酒裡!', '卡拉諾斯的拉格納·雷酒需要6塊峭壁野豬肋排和1杯狂想麥酒。', '', '去丹莫洛找閃光嶺的拉格納·雷酒。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (385, 'zhTW', '捕獵鱷魚', '很多獵人到洛克莫丹來都是為了捕獵這裡的鱷魚。總有一些商人專門尋找這種鱷魚皮，用它們來製作衣物或是護甲，還有些人則喜歡品嘗鱷魚肉。$B$B我們一直在進行這種貿易，但交易量並不是很大，因為鱷魚很兇猛，而且它們一般都盤踞在洛克湖中的小島上。嘿，別被我的話給嚇倒了，和鱷魚較量一番對你來說也是一種歷練。$B$B你看能不能...', '收集5塊鱷魚肉和6張鱷魚皮，把它們交給遠行者小屋裡的馬雷克‧鐵心。', '', '去找洛克莫丹的馬雷克·鐵心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (386, 'zhTW', '伸張正義', '可怕的塔高爾是加塞爾佐格手下的一個高級殺手。他殺人的手法十分殘忍，即使以獸人的標準來看也是殘暴無比。那些為了保衛國家而奮勇作戰的戰士們落在他手裡都會被他折磨致死。這個惡棍現在被關在暴風城的監獄裡，被判處了死刑。不過，這件事情好像出了點小差錯。一個官僚習氣十足的貴族延遲了處死他的日期。我敢打賭這裡面一定有鬼。$B$B處死塔高爾吧， $N 。到暴風城的監獄裡去，在他玩出什麼把戲之前把他幹掉。', '把塔高爾的頭顱帶給湖畔鎮的衛兵伯爾頓。', '', '去赤脊山找湖畔鎮的衛兵伯爾頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (387, 'zhTW', '鎮壓暴動', '我們必須把暴動給鎮壓下去!我需要你的幫助。如果外面的人知道監獄裡面已經失去了控制，我一定會丟了飯碗的!這是我所見過最無聊的鬧劇了。現在最重要的是逼迫這些囚犯投降，這樣才能保證暴風城的安全。$B$B叛亂的代價就是死亡。去殺掉一些囚犯，這樣叛亂才能得到控制!', '暴風城的典獄官塞爾沃特要求你殺死監獄中的10名迪菲亞囚犯、8名迪菲亞罪犯和8名迪菲亞叛軍。', '', '去找暴風城的典獄官塞爾沃特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (388, 'zhTW', '鮮血的顏色', '痛苦如同冰冷的河水一樣從我的血管中流過。我的孫子麥克是個多好的孩子呀，他只有14歲。當暴風城的軍隊被派往前線的時候，麥克也拿起了武器去守衛城市。他是監獄的守衛，那座監獄裡關押著許多迪菲亞兄弟會的成員。有一些囚犯們把他們的羊毛毯改織成他們組織的頭巾，麥克把這件事情上報了，結果他遭到了報復，被人從後面刺了一刀。$B$B我要報仇。給我帶回10條迪菲亞盜賊們的羊毛頭巾，像鮮血一樣殷紅的那種。', '暴風城的尼科瓦·拉斯克要你取得10條紅色毛紡頭巾。', '', '去暴風城找舊城區的尼科瓦·拉斯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (389, 'zhTW', '巴基爾·斯瑞德', '范克里夫和我過去都曾是石匠行會的成員，我們的主要工作是在戰後重新建設暴風城。當我們完成了自己的職責時，卻發現我們被徹底地欺騙了。貴族們拒絕付給我們酬勞，一些石匠行會的元老被提拔成了官員，但范克裡夫出於對所有石匠會員的忠誠拒絕了他們。他組織了一場暴動，並離開了城市，從此發誓要進行復仇。他的副官巴基爾·斯瑞德或許對范克里夫的計畫有一些瞭解，他目前正被關押在監獄裡。', '與監獄的典獄官塞爾沃特談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (390, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (391, 'zhTW', '監獄暴動', '讓我們把話挑明瞭說吧， $N :我不信任你。但是，現在的情況緊急，我也管不了那麼多了。$B$B你到下面去幹掉那個該死的斯瑞德，把他的腦袋砍下來帶給我。$B$B還有，如果你膽敢跟他合計什麼把戲，或者你不上來了的話……只要被我抓到你，就準備跟那群蛆死在一塊吧。', '殺死巴基爾·斯瑞德，把他的頭帶給監獄的典獄官塞爾沃特。', '', '去找暴風城的典獄官塞爾沃特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 392 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (392, 'zhTW', '好奇的訪客', '在斯瑞德服刑的第一年期間，從來沒有人來探視過他。我猜當時迪菲亞兄弟會認為他已經徹底沒用了，所以準備讓他自生自滅。$B$B但是幾個月前，一切都變了。有人開始定期探視他……每週一到兩次。那是個奇怪的男人，沉默寡言。我有點疑心，但他的證件是真實且合法的。$B$B他的名字叫麥里克，這是他的一些資料。我覺得他可能不會再來探視斯瑞德了。', '將神秘訪客的資料交給暴風城的巴洛斯·艾力克斯頓。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 393 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (393, 'zhTW', '往日的陰影', '我確實沒什麼線索，$N。但或許另外有人能幫上你的忙，而且他還欠了我一個人情─好了，現在不是說那個的時候。暴風城兵營中的軍情七處首領馬迪亞斯·肖爾或許能輕鬆搞定這類事。$B$B如果說有誰知道這事的話，一定就是他，他此刻就在舊城區。', '與舊城區的馬迪亞斯·肖爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (394, 'zhTW', '禽獸的首級', '到舊城區去找肖爾，告訴他萊斯科瓦的威脅已經被解決了以及你在這個人對暴風城的陰謀中涉入的情況。我敢說他一定會為暴風城出了你這樣的英雄而感到自豪的。他甚至有可能將你引薦給公主或是其他貴族。記住一點，$N，這些貴族們可能自認為他們可以完全掌制著暴風城，但總有一些事情是他們無能為力的。', '與暴風城舊城區的馬迪亞斯·肖爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (395, 'zhTW', '兄弟會的滅亡', '啊，我差點忘了。艾力克斯頓在你離開的時候來過，他有話想跟你說。顯然他是想向國王陛下報告關於迪菲亞兄弟會的事情。給你個忠告，$N。如果有人問到這個，我會把除了你殺掉萊斯科瓦以外的所有細節都告訴他。相信我，我…對這種事…已經習以為常了……另外，別跟任何人說起提亞斯的事情。', '與暴風城的巴洛斯·艾力克斯頓談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 396 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (396, 'zhTW', '覲見國王', '我準備了一份報告呈遞給國王陛下。當我聽說了你最近的事蹟之後，我認為你是遞送這份報告的最佳人選。別擔心，國王陛下一定會嘉獎你的。$B$B你的覲見已經被列入了陛下的日程表，所以你最好快點到暴風要塞裡去等待召見。', '將有關迪菲亞兄弟會的報告送給暴風要塞裡的國王瓦里安·烏瑞恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (397, 'zhTW', '幹得好', '我聽說維沙克領主很喜歡他收到的飲料。$B$B你幫了我們的大忙，$N。暴風城的術士們從此可以不再受他人干涉地自由行事了。我準備了一件特殊的小禮物給你，以表示我們的感謝。去找我的僕人茲吉，收下你的報酬吧。', '去找黑爪加爾德斯的僕人茲吉談一談，並向他索要你的酬勞。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (398, 'zhTW', '懸賞:蛆眼', '懸賞:蛆眼!$B$B這只名叫蛆眼的豺狼人臭名昭著，即使是在它的同類眼中都顯得非常邪惡而污穢，它因為對被遺忘者們犯下了不可饒恕的罪名而被判處了死刑，這只卑鄙的野獸為巫妖王的軍隊偷盜了無數的屍體。上次有人看到蛆眼作惡是在布瑞爾北邊的加倫鬼屋。$B$B布瑞爾鎮將為執行這項判決的勇敢者提供一份高額的獎金。完成任務之後，請將這只野獸的爪子交給執行官塞加德。$B$B只有弱者才會有憐憫之心。', '殺死蛆眼，並將他的爪子交給布瑞爾的執行官塞加德以換取酬勞。', '', '去提里斯法林地找布瑞爾的執行官塞加德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 399 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (399, 'zhTW', '童年的記憶', '許多年前，我是個在西部荒野的農場裡工作的小男孩，不過現在看來，這會是個永恆的回憶。俗話說時光一去永不回，這句話果然沒錯，在我身上更是獲得了雙重的印証，我家的房子已經被燒毀，又給一群盜賊給佔據了。$B$B我曾向父親詢問過我的一些物品的下落─包括我的第一個指南針，他說他沒辦法把那些東西拿回來。但是他又說它們應該還藏在農場的什麼地方。$B$B你可以在哨兵嶺的西邊找到艾力克斯頓農場。也許你能去幫我把那些東西找回來?', '到巴洛斯·艾力克斯頓在西部荒野的房子裡找尋他的指南針，並帶回暴風城教堂區給他。', '', '去找暴風城的巴洛斯·艾力克斯頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 400 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (400, 'zhTW', '貝爾丁的工具', '貝爾丁·鋼架在本地擁有一間機械店，他也是本地最好的攻城機具機械師!不過他從來不愛護他的工具。他弄壞扳手的速度遠遠大於我們的供貨速度!$B$B我們剛剛才趕出他最近訂的一批貨。如果你能把這些東西交給他，我想他一定會讓你感到不虛此行的。$B$B他開的鋼架補給站就在卡拉諾斯的東北邊。老牌的攻城機具駕駛員們經常在那裡碰頭，所以你到了那裡之後要睜大眼睛，說不定能找到一些好機會。', '把貝爾丁的工具交給貝爾丁·鋼架。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 401 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (401, 'zhTW', '等待希拉完工', '我很快就能把信件翻譯完了。請稍等一會兒再過來吧。', '稍等片刻，然後再和希拉·沃寧迪交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 402 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (402, 'zhTW', '正在忙碌的希拉', '真抱歉，不過我手頭上還有些別的事務要處理。如果我們能活下來，也許我就能完成這段翻譯。', '晚點再去見希拉，看他是否還在忙著。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 403 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (403, 'zhTW', '戒備森嚴', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 404 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (404, 'zhTW', '腐爛的爪子', '有一小撮天譴軍團的士兵已經滲入了提里斯法林地，在布瑞爾以西一帶的舊橋附近活動。$B$B到那邊去增援我們的部隊，擊退所有你見到的腐爛的死者和破碎的屍體。拆散他們的骨頭，然後把他們那腐爛的爪子給我帶回來，亡靈衛兵會獎勵你的。', '給布瑞爾的亡靈衛兵迪林格爾帶回7隻腐爛的爪子。', '', '去提里斯法林地找布瑞爾的亡靈衛兵迪林格爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 405 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (405, 'zhTW', '流浪的巫妖', '幽暗城裡的一位法力強大的高階法師比索·埃斯沙德給了我一個任務，讓我去為他找一個與天譴軍團有著豐富鬥爭經驗的勇士。你，$N，顯然就是他要找的人。$B$B現在立刻去向比索報到，他會給你指派新的任務。我也不清楚任務的細節，但大致上好像是要招安一名獨居的巫妖之類的。這份工作可能會很危險。$B$B去做好準備吧，$C。你絕對不能失敗。$B$B比索就在幽暗城的魔法區裡。', '將塞弗倫的命令交給幽暗城的比索·埃斯沙德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 406 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (406, 'zhTW', '<UNUSED>', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 407 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (407, 'zhTW', '悲傷之地', '這南瓜看起來沒什麼異樣吧？至少光看外表是無害的。如果我們想要阻止北邊來的阿薩斯軍隊，外加阻擋南方橫行的人類勢力，那麼我們必須從現在開始就意識到自己身為亡靈的優勢。$B$B只要稍微耍點小把戲，一個簡單的南瓜就能讓任何人成為黑暗女王的優秀探子。我最新培育的這種南瓜就可以做到這一點。$B$B據說現在又有個血色十字軍被俘虜了，他被關在恐懼之末旅店的某房間裡。把這個南瓜拿去給那個蠢蛋。', '將斑紋南瓜帶給被關在恐懼之末旅店地下室中的血色十字軍俘虜。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 408 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (408, 'zhTW', '家族墓穴', '如今阿加曼德磨坊已經成了天譴軍團的一處重要據點，其中防守最為堅固的地方就是阿加曼德的家族墓穴了。天譴軍團的一個兵團就駐守在那裡，他們由一個名叫達高爾隊長的骷髏領導著。他們還利用某種通靈術復活了阿加曼德家族的死者們，並打算利用它們來對付我們。$B$B我們絕對不能允許這種事情發生，你必須阻止它。到阿加曼德家族墓穴去，戰勝那些還魂的阿加曼德家族的死屍們。$B$B還有，把達高爾隊長的顱骨也給我帶回來。', '殺死8個哀嚎的鬼魂和8個腐爛的古屍。消滅達高爾隊長，並將他的顱骨交給布瑞爾的執政官塞弗倫。', '', '去提里斯法林地找布瑞爾的執政官塞弗倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (409, 'zhTW', '證明忠誠', '你說你沒有被巫妖王控制住自己的思想，這一點已經由比索在我書上灌入的魔法證實了。但是，你仍然得先證明自己是天譴軍團的敵人，這樣我才會徹底相信你。$B$B在這座島嶼的南方海邊有一個古老而血腥的祭壇，由一個強大的天譴軍團斥候莉莉絲·奈法拉所佔據著。$B$B從我身邊的木箱裡拿出一根誘靈蠟燭，在祭壇上點燃蠟燭，莉莉絲就會醒來。消滅莉莉絲，我就相信你確實是巫妖王的敵人。', '取得一根誘靈蠟燭。召喚出莉莉絲·奈法拉並殺死她。然後回去島上找岡瑟爾。', '', '去提里斯法林地找十字軍前哨的岡瑟爾·阿坎努斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 410 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (410, 'zhTW', '潛伏的陰影', '', '', '', '去找西瘟疫之地的莉莉絲的餐桌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 411 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (411, 'zhTW', '巫妖歸順', '拜託你，請將這塊虛空寶石帶給我的老朋友比索。這樣我就能和他交流了……我有好多事想和他說呢。', '將虛空寶石交給幽暗城的比索·埃斯沙德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 412 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (412, 'zhTW', '自動淨化器', '透過對諾姆瑞根現狀的進一步分析，我們發現不但那些該死的穴居人沒有被消滅，反而有更多的地精變成了喪心病狂的、邪惡的麻瘋地精。$B$B我和奧齊希望用我們的最新發明「自動淨化器」來扭轉這種局面。這台機器即將大功告成，不過我們急需一些多檔齒輪和自適應齒輪才能搞定最後的部分，請從諾姆瑞根的麻瘋地精那裡弄些過來吧。', '收集8個多檔齒輪和8個自適應齒輪，把它們交給卡拉諾斯的拉索·滑鏈。', '', '去找丹莫洛的拉茲·滑鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 413 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (413, 'zhTW', '微光酒', '我希望我兄弟維拉特能夠品嘗一下我最新釀製的微光酒。他是一個在南面的警戒塔里執勤的巡山人，就是靠近洛克莫丹邊界的那兩座哨塔里的一座。$B$B他不是釀酒師，但是他非常喜歡喝酒，而且我相信他一定喜歡這種酒的。$B$B你能替我把這桶微光酒交給他嗎?', '把這一大桶微光酒交給巡山人維拉特·麥酒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 414 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (414, 'zhTW', '給卡德雷爾的酒', '我一直都喝很多我兄弟釀造的微光酒－那真是極品啊!我想讓我的一個朋友也品嚐一下，他叫卡德雷爾，他經常在塞爾薩瑪附近的路上巡邏。$B$B要去塞爾薩瑪的話，就往東南方穿越隧道，然後在岔路口向東北方走，最後沿著大路一直走就能到塞爾薩瑪了。$B$B把這桶微光酒交給巡山人卡德雷爾，看看他是不是也讚不絕口!', '把這桶微光酒帶給巡山人卡德雷爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 415 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (415, 'zhTW', '雷傑德的新酒', '烈酒村的雷傑德·麥酒正在找你。$B$B他要和你談談他最新正在釀造的一種酒……他告訴我你幫了他很多忙。你也許應該去一次烈酒村，看看他要說什麼。$B$B也許，你可以在那裡免費享受到一頓大餐……', '和雷傑德·麥酒談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 416 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (416, 'zhTW', '逮捕狗頭人', '我們在西邊遇到了點麻煩。坑道鼠狗頭人在那裡的丘陵地帶建起了巢穴，把我們的地盤弄得烏煙瘴氣!$B$B我們必須把他們給消滅掉。去捕殺那些坑道鼠狗頭人，把他們的耳朵拿回來給我，我就給你賞金。$B$B坑道鼠狗頭人的巢穴就在塞爾薩瑪北邊的山腳下。', '收集12隻坑道鼠的耳朵，把它們帶給塞爾薩瑪的巡山人卡德雷爾。', '', '去洛克莫丹找灰爪山的巡山人卡德雷爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 417 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (417, 'zhTW', '駕駛員的復仇', '莫里‧鐵鑽在他的日記中寫著，他遭到一頭名叫癩爪的巨型冰爪熊的攻擊。他趕走了這隻野獸，不過自己也已身受重傷。$B$B從莫里屍體上的傷痕判斷，癩爪一定在之後又回來殺死了他。$B$B無論如何，莫里在他的日記中寫下了他最後的遺願:$B$B殺死癩爪，為我復仇。', '殺死癩爪。把牠的骯髒的爪子和莫里·鐵鑽的日記交給駕駛員塞克·錘足。', '', '去丹莫洛找北門哨崗的駕駛員塞克·錘足。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (418, 'zhTW', '塞爾薩瑪血腸', '塞爾薩瑪這兒饑腸轆轆的人可真不少，有跑進跑出的孩子，也有在挖掘場忙了一整天的工人。我們這兒有一道出名的菜色─血腸，你大概還沒嘗過吧?$B$B沒有?在這兒要吃飯就得幹活，別以為你是個出色的$c就可以例外。$B$B我需要熊肉、做腸衣用的豬大腸，還有做調料用的蜘蛛的毒液。把這些東西找來，剩下的就交給我維德拉好了!', '收集3塊熊肉、3根豬大腸和3份蜘蛛的毒液，把它們交給塞爾薩瑪的維德拉·壁爐。', '', '去洛克莫丹找灰爪山的維德拉·壁爐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 419 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (419, 'zhTW', '失蹤的駕駛員', '我的朋友，同時也是同一蒸汽坦克車組的同事─莫里·鐵鑽，在山上失蹤了。我們當時正在尋找一種可以用來製作高爆炸藥的稀有礦石。在我們搜尋的過程中，莫里駕駛著他的坦克攀上一處陡峭的山坡後拋錨了!他確信礦石就在這片山地裡，所以就讓我守著我們的機車，而他一個人步行繼續去搜索。莫里已經有好些天沒回來了，夜裡我時常能聽見山中的野獸發出的咆哮。莫里是個硬漢，不過我還是有點為他擔心。求求你，$N，幫我找到他。', '找到駕駛員莫里·鐵鑽。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 420 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (420, 'zhTW', '森內爾的觀察站', '隧道裡的穴居人非常具有攻擊性，它們會毫不猶豫地對隧道中的過客發動襲擊。不過你看起來挺結實的，應該不會有什麼危險。$B$B方向?如果你要找森內爾，就到卡拉諾斯去吧。$B$B一直穿過隧道，出去之後沿著大路向前走，沒幾步就到卡拉諾斯了。', '把格瑞林的報告交給卡拉諾斯的森內爾·白鬚。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (421, 'zhTW', '證明你的價值', '希瓦娜斯主人已經授命瓦里瑪薩斯大人全權負責征服南方的人類和矮人的領土。$B$B但阿魯高那個蠢貨─過去他是達拉然的大騙子，現在他是影牙城堡裡一隻中了詛咒的困獸─他那不計後果的魔法給銀松森林裡那座極具戰略意義的要塞帶來了一場大浩劫。$B$B我需要一些擁有優秀戰鬥技巧的人幫我把阿魯高留下的爛攤子給收拾掉。殺死5隻月怒白頭狼人以證明你的實力吧，這些野獸一般都在山腳下的道路兩旁遊蕩。', '瑟伯切爾的達拉爾·織曦者要求你殺死5隻月怒白頭狼人。', '', '去銀松森林找瑟伯切爾的達拉爾·織曦者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (422, 'zhTW', '阿魯高的愚行', '阿魯高這樣一個施法能力比一張紙還要淺薄的傢伙居然能夠得到祈倫托的承認，這讓我實在難以想像。$B$B現在最重要的是，搞清楚阿魯高究竟使用了什麼魔法，這樣一來我才能對付他，並為黑暗女王平定銀松森林。$B$B阿魯高曾經住在橋北的麥田旁，一名亡靈哨兵回報說，他發現了阿魯高擁有的幾本法術書，但無法偷取它們。把其中一本名叫《阿魯高的拯救》的法術書從其他書裡找出來，並帶回來給我。', '為瑟伯切爾的達拉爾·織曦者找回《阿魯高的拯救》。', '', '去銀松森林找瑟伯切爾的達拉爾·織曦者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (423, 'zhTW', '阿魯高的愚行', '在我研究過阿魯高的書以後，我最壞的設想不幸被證實了。祈倫托竟在那個連給達拉然的法師們掃屋子都不配的傢伙幹出那種愚昧行徑的時候完全不聞不問，一群蠢貨!$B$B阿魯高使用了附有魔法的物品來加強他薄弱的施法能力。我需要儘快研究一下這些物品。去殺掉一些月怒暴食者和月怒黑暗之魂狼人，收集他們身上帶著的魔法鐐銬供我研究之用。這些污穢的生物在北邊和東邊到處都是。', '給瑟伯切爾的達拉爾·織曦者帶回6副暴食者鐐銬和3副黑暗之魂鐐銬。', '', '去銀松森林找瑟伯切爾的達拉爾·織曦者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (424, 'zhTW', '阿魯高的愚行', '看來想揭開隱藏在阿魯高所用的巫術中的黑暗秘密並不簡單，這比我想像中要花掉的時間多出很多。$B$B但與此同時，我需要你來幫忙處理一下我們的亡靈哨兵發現的一個小問題。似乎阿魯高的魔法已經控制了東南方山中的深埃連礦坑。$B$B這座礦坑對瓦里瑪薩斯大人的推進有著非常重要的意義。$B$B我希望你能幹掉礦坑裡的工頭，白毛狼人格瑞姆森。只要他一死，礦坑就是我們的了。', '殺死白毛狼人格瑞姆森，把他的頭帶給瑟伯切爾的達拉爾·織曦者。', '', '去銀松森林找瑟伯切爾的達拉爾·織曦者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 425 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (425, 'zhTW', '邪惡的伊瓦', '我正在和哥哥奎恩執行偵察銀松森林的任務，並準備向高級執行官哈德瑞克復命。但我們進行得不太順利─我們穿過這座農莊的時候，被食屍鬼伊瓦襲擊了。$B$B我們從伊瓦那裡逃了出來，但他還是重創了奎恩。喝了你給他的藥水以後，哥哥正逐漸痊癒，但這段時間裡伊瓦仍可能會過來。$B$B殺死伊瓦，以保證奎恩有足夠的時間復原吧。伊瓦一般都躲在穀倉那裡，在我放鬆警戒的時候它就會開始行動。', '殺死邪惡的伊瓦，並將伊瓦的頭顱帶給伊瓦農莊的蘭妮·尤瑞克。', '', '去找銀松森林的蘭妮·尤瑞克。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 426 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (426, 'zhTW', '磨坊告急', '天譴軍團正試圖在阿加曼德磨坊那邊建立起一座前哨基地。如果他們得逞了，那麼他們在提里斯法的軍事行動將得到有利的支援。$B$B上頭已經發話下來了，必須將磨坊那邊的天譴軍團勢力全部清除乾淨。$B$B到磨坊那邊去，從斷骨士兵和碎顱士兵身上收集凹槽肋骨，再從暗眼骸骨法師身上收集焦黑的顱骨。$B$B你只需沿著道路一直向西走，過橋以後在第一個岔路口轉向北就行了。當你看到風車的時候，戰鬥隨時都會開始。', '收集5根凹槽肋骨和3個焦黑的顱骨，然後向布瑞爾的亡靈衛兵迪林格爾回報。', '', '去提里斯法林地找布瑞爾的亡靈衛兵迪林格爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (427, 'zhTW', '與血色十字軍的戰爭', '執行官亞倫大人提供給我們的資料中正是我們與那些卑劣的血色十字軍進行的戰爭中所要的突破點。我們現在知道他們在整個提里斯法林地的確切位置了。$B$B但亡靈衛兵還有其他更艱鉅的任務，巫妖王的軍隊每個夜晚都在逐漸的壯大著。我們需要一些像你這樣的志願者來把那群血色十字軍送進墳墓。$B$B順著鎮外的道路向西走，穿過索利丹農場到廢塔那裡去，殺死10名血色十字軍戰士。以此來證明你有足夠的能力為黑暗女王陛下服務。', '布瑞爾的執行官塞加德要求你去殺掉10名血色十字軍戰士。', '', '去提里斯法林地找布瑞爾的執行官塞加德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (428, 'zhTW', '失蹤的亡靈哨兵', '幾周前，亡靈哨兵蘭妮·尤瑞克和奎恩·尤瑞克被派遣到銀松森林北部去執行一次偵察任務。可我們一直沒有再得到他們的訊息。$B$B也許他們已經成了天譴軍團的犧牲品。當然，我仍然希望有人能去確認一下，你去找到這兩名亡靈哨兵。$B$B他們最初的任務是去偵察銀松森林北邊的農場，你可以從那裡開始搜尋。', '找到亡靈哨兵蘭妮·尤瑞克和奎恩·尤瑞克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (429, 'zhTW', '荒野之心', '我的哥哥奎恩被食屍鬼伊瓦打成了重傷，我不知道在沒有魔法幫助的情況下，他是否還能痊癒。儘管我不是一個藥劑師，但我知道我們的藥劑師能用變色的狼心製作治療藥水。$B$B幫我收集一些心臟並帶給南邊墳場的藥劑師倫弗利爾，然後把做好的藥水帶回來。$B$B這附近和東邊的瑪爾丁果園之間有不少座狼在到處遊蕩。', '收集6顆變色的狼心，把它們交給瑟伯切爾的藥劑師倫弗利爾。', '', '去銀松森林找瑟伯切爾的藥劑師倫弗利爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 430 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (430, 'zhTW', '回到奎恩身旁', '這就是能幫助奎恩·尤瑞克復原的藥水。$B$B現在，如果你沒什麼事的話，我就先失陪了。我還有重要的工作要繼續……', '將奎恩的藥水帶給瑟伯切爾北方伊瓦農場的奎恩·尤瑞克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (431, 'zhTW', '誘靈蠟燭', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 432 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (432, 'zhTW', '該死的石齶怪!', '那些該死的石齶怪，它們把我的工作地點變成了一片廢墟!看那裡，又一個火藥桶!$B$B啊啊啊啊啊，我真想鑽到地底下去扭斷它們那豆芽一樣的脖子!我要把它們趕盡殺絕!$B$B即使這樣也無法消除我的憤怒……它們留給了我什麼?什麼也沒有!$B$B我要親手殺了它們，不過我的胳膊已經不再那麼有力了!到採石場去，幹掉那幫該死的傢伙!我會獎賞你的!只要你去幹掉它們!', '在古博拉採掘場裡替工頭喬尼·石眉殺死6個石齶擊顱者。', '', '去找丹莫洛的工頭喬尼·石眉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 433 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (433, 'zhTW', '公僕', '作為參議院與探險者協會的一員，我決定開始瞭解這個地區石齶怪氾濫的事情。$B$B牠們把古博拉採掘場搞了個天翻地覆，而且這種行為看起來毫無理由。當我們在挖掘礦石的時候，牠們突然出現，毀壞了我們的設備，趕走了我們的礦工。我們別無選擇，只得殺光牠們，之後我們才能重建工地並繼續工作。$B$B如果你願意幫助我解決掉那些石齶怪的話，我會很樂意報答你的。', '到古博拉採掘場裡替參議員梅爾·聖石殺死10個石齶斷骨者。', '', '去找丹莫洛的參議員梅爾·聖石。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 434 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (434, 'zhTW', '伏擊!', '等我做好間諜機器人的偽裝，他會進去和萊斯科瓦談話。守衛會讓他進去的。$B$B在你幫我準備材料的同時，我會暗示馬爾松，讓他再次和萊斯科瓦會面，我甚至會給他一點假消息，好讓他對此深信不疑。$B$B接下來，萊斯科瓦就會讓他的衛兵解散，然後在花園裡等馬爾松。等你聽到他們談起迪菲亞兄弟會的時候就採取行動。你要把他們兩個都幹掉。聽懂了嗎?$B$B當你完成任務之後，儘快向提亞斯回報。', '等待葛瑞格·萊斯科瓦領主和『沉默之刃』馬爾松在花園裡的對話結束，殺死他們兩個，之後向暴風城的提亞斯回報。', '偷聽萊斯科瓦與馬爾松的對話', '去找暴風城的伊林·提亞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 435 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (435, 'zhTW', '護送埃蘭德', '外面的狼群看來是不想離開了，而且我每次走出屋子的時候，它們都惡狠狠地盯著我。這些野狼顯然是餓極了，它們把我當成了大餐!$B$B我得通知我的隊友，亡靈哨兵蘭妮·尤瑞克。也就是說，我要到她那裡去，得先找人幫我搞定這群狼。$B$B請護送我吧!不過，這邊的狼也實在是多了點，如果你還有別的朋友的話…再好不過……', '護送亡靈哨兵埃蘭德避過群狼，直到他找到蘭妮·尤瑞克。', '埃蘭德必須到達蘭妮·尤瑞克身邊', '去找銀松森林的蘭妮·尤瑞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 436 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (436, 'zhTW', '鐵環挖掘場', '勘察員基恩薩·鐵環正在負責挖掘洛克湖東邊的一座古老的廢墟。雖然我們已經給他送去了不少物資，但是他那裡最近進展非常緩慢。基恩薩·鐵環是一個頑強、誠實而精幹的矮人，沒理由會如此懈怠，所以我擔心他那兒出了什麼問題。到鐵環挖掘場去問問麥格瑪爾·落斧，他負責挖掘場的瑣事，一定知道那裡到底是怎麼了。你要可以從湖的南端繞過去，然後一直向東走，就可以到挖掘場了。', '和麥格瑪爾·落斧談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 437 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (437, 'zhTW', '亡者農場', '我們在銀松森林的斥候回報說，腐皮豺狼人在北邊一處叫做亡者農場的地方建立了一個基地。我們曾經派遣了一小隊突襲隊去對付他們，但他們每次都會得到女妖奈塔拉什的支援，我們的部隊每次都被她的魔法所擊潰。$B$B我們必須殺掉奈塔拉什。$B$B到亡者農場去突襲那裡的腐皮豺狼人。如果沒有看到奈塔拉什的話，就繼續屠殺腐皮豺狼人直到她出現為止，然後擊敗她。$B$B她的靈魂將會變成塵土。把這些塵土帶回來，作為你殺死她的證明。', '殺死亡者農場的腐皮豺狼人。', '進入亡者農場。', '去銀松森林找瑟伯切爾的高級執行官哈德瑞克。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 438 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (438, 'zhTW', '破舊渡口', '$N，我們最近發現了天譴軍團的一個新據點：破舊渡口。這處渡口就在瑟伯切爾的東方，有許多腐皮豺狼人和其他亡靈層層守衛著那裡。天譴軍團佔據了那裡，這其中一定有些什麼陰謀。到破舊渡口去調查一下，看看為什麼天譴軍團會在那裡。', '到破舊渡口去，找到天譴軍團佔據那裡的理由。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 439 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (439, 'zhTW', '腐皮線索', '在一大堆屍體中間，有一隻裸露的手。這是一隻女人的手，雖因瘟疫而導致皮膚上佈滿紅痘，但仍然十分白皙。$B$B她的手上戴著一隻戒指。你從屍體的手上取下這只戒指，看到戒指內環中有一道銘文：$B$B「贈予黛麗婭」', '將黛麗婭的戒指帶給瑟伯切爾的高級執行官哈德瑞克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 440 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (440, 'zhTW', '黛麗婭的戒指', '如果你想找到黛麗婭的丈夫或情人，也就是送給她戒指的那個人的話……去找布瑞爾的執政官塞弗倫談談吧。他或許擁有最近的死亡記錄，當然，如果你走運的話，還能發現誰是黛麗婭。$B$B但我也不抱希望。無論給她戒指的人是誰，現在恐怕也已經死了。如果他成了不死生物，也就不會再關心黛麗婭了。', '將黛麗婭的戒指帶給布瑞爾的執政官塞弗倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (441, 'zhTW', '拉林夫與幽暗城', '黛麗婭有個丈夫叫拉林夫，他現在居住在幽暗城。如果居住在布瑞爾的這位黛麗婭就是這只戒指的主人，想必他應該知道。$B$B拉林夫就在幽暗城的貿易區。', '把黛麗婭的戒指交給拉林夫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (442, 'zhTW', '突襲芬里斯島', '現在是把天譴軍團徹底趕出銀松森林的時候了。$B$B你必須再去一次那個島，殺死圖勒·鴉爪，把他的頭顱提來見我!$B$B這個任務非常危險，但是你也應該知道它的重要性， $N 。所以你只能成功，不能失敗。', '將圖勒的頭顱帶回給瑟伯切爾的高級執行官哈德瑞克。', '', '去銀松森林找瑟伯切爾的高級執行官哈德瑞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (443, 'zhTW', '腐皮豺狼人的膿液', '在我們對芬里斯島展開一次突襲行動之前，我們必須得弄清楚誰是腐皮豺狼人背後的真正主人，我們的藥劑師們相信它們的體內發生了某種神秘的變化。$B$B到破舊渡口東邊的芬里斯島去，收集一些腐皮豺狼人身上流出的膿血，然後把膿液交給瑟伯切爾外的藥劑師倫弗利爾。', '給瑟伯切爾的藥劑師倫弗利爾帶去8瓶腐皮豺狼人的膿液。', '', '去銀松森林找瑟伯切爾的藥劑師倫弗利爾。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 444 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (444, 'zhTW', '腐皮豺狼人的產生', '我還原了你帶給我的膿液，並把它們分離成了一些基本成分。我的發現還不是結論性的，但我可以肯定惡魔法術和死靈法術在這膿液的產生過程中起了極其重要的作用。$B$B在我繼續研究膿液的同時，我希望你能給幽暗城的比索·埃斯沙德帶些樣本過去。比索雖然不是一名藥劑師，但他在魔法方面的學識將會幫助我們揭開這些腐皮豺狼人的秘密。$B$B快去吧，比索就住在幽暗城的法師區。', '將膿液樣本交給幽暗城的比索·埃斯沙德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 445 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (445, 'zhTW', '給銀松森林送信', '如今，對我們這些希瓦娜斯女士的僕從來說，時間就是一切。顯然現在你也非常清楚這一點。$B$B身為皇家藥劑師學會的一員，我必須將我的研究成果與同事們分享，只有依靠所有會員的共同努力，我們才能向黑暗女王陛下提供她最期望的新瘟疫。$B$B將這些報告帶給住在銀松森林瑟伯切爾裡的藥劑師倫弗利爾，從布瑞爾向南走，到了幽暗城再轉往西南就可以了。', '將藥劑師喬漢的研究成果帶給銀松森林的藥劑師倫弗利爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 446 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (446, 'zhTW', '圖勒·鴉爪', '這種膿液是我以前的一個同僚圖勒·鴉爪製成的。在大戰之前，他是一個有著大好前途的年輕法師，但在巫妖王的勢力崛起之後，他背叛了他的朋友與兄弟，加入了天譴軍團。$B$B我沒料到他還活著，更沒有想到的是，原來是他在領導腐皮豺狼人與我們對抗。$B$B我對他的許多法術都有所瞭解，應該能幫忙調製出一種能擊敗他們的藥劑。把這個卷軸交給藥劑師倫弗利爾，卷軸上面寫著調製藥水所需要的咒語。', '把比索的卷軸交給銀松森林中的藥劑師倫弗利爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 447 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (447, 'zhTW', '致命配方', '阿薩斯的手下越來越多。不過，只要再來一次新的瘟疫，我們就可以一勞永逸地同時根除天譴軍團和人類。$B$B我的研究已經證明，將灰熊心臟中提取出的毒素和蜘蛛血混合在一起，就可以製成一種致命的毒藥。從西北方的粘絲洞中的蜘蛛身上和銀松森林中遊蕩著的熊身上採集一些樣本回來，然後把它們送給幽暗城皇家藥劑師學會裡的藥劑大師法拉尼爾。', '收集6個灰熊的心臟和6份粘稠的血液樣本，並將這些東西送給幽暗城的藥劑大師法拉尼爾。', '', '去找幽暗城鍊金房的大藥劑師法拉尼爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 448 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (448, 'zhTW', '給哈德瑞克的報告', '在你展開對芬里斯島的攻擊之前，先向高級執行官哈德瑞克覆命吧。他或許還有些額外的裝備或者情報要給你。', '向瑟伯切爾的高級執行官哈德瑞克覆命。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 449 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (449, 'zhTW', '亡靈哨兵的報告', '儘管奎恩的傷基本已經好了，但我仍想盡可能快地把報告呈送給高級執行官哈德瑞克。這裡面的情報對被遺忘者來說十分重要，它將關係到我們在整個銀松森林的統治地位。', '將亡靈哨兵的報告的報告交給瑟伯切爾的高級執行官哈德瑞克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 450 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (450, 'zhTW', '致命配方', '其實你還能為皇家藥劑師學會再做一些事情， $N 。$B$B當初阿魯高在整個森林中施展了他那可惡的魔法時，我們當中一位最有前途的成員─藥劑師博拉爾德，也被他詛咒了。現在博拉爾德已經變成了一個忠於阿魯高的傀儡，換句話說，他對我們已經徹底沒用了。但是他的研究成果可能對我們非常有用，因為他在多年以前曾經研究過一種殺死了洛丹米爾湖中所有生物的瘟疫。$B$B將伯納德的日記從他在焚木村旅店中的研究室裡偷出來，然後把日記交給藥劑師倫弗利爾。', '從焚木村的旅店中找到伯納德的日記，把它交給瑟伯切爾的藥劑師倫弗利爾。', '', '去銀松森林找瑟伯切爾的藥劑師倫弗利爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 451 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (451, 'zhTW', '致命配方', '根據博拉爾德的研究日記，採自湖岸蠕行者和潛藏者身上的苔蘚會對我們製造出這種瘟疫大有助益。這些野獸就棲息於東邊的洛丹米爾湖中的群島上。$B$B他還提到曾在一隻邪鰭魚人身上發現了一種非常稀有的硬瘤，顯然這種瘤很難得到，博拉爾德也只找到了一個。$B$B收集一些苔蘚和那種稀有的瘤，把它們帶給幽暗城的藥劑大師法拉尼爾。', '收集6份湖岸蠕行者苔蘚的樣本、6份湖岸潛藏者苔蘚的樣本和1塊硬瘤，把它們交給幽暗城的藥劑大師法拉尼爾。', '', '去找幽暗城鍊金房的大藥劑師法拉尼爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 452 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (452, 'zhTW', '焚木村中的伏擊', '你來得正好，$N！$B$B焚木村議會隨時都有可能回來，而阿魯高此時正好無暇顧及這裡。他利用議會作為傀儡控制著焚木村中無知的村民們，我相信如果沒有議會的引導，阿魯高的奴隸們一定會反戈一擊，背叛他們的主人。$B$B我無法獨自應付他們所有人。我需要你的幫助，只要齊心協力，我們一定能為希爾瓦娜斯主人消滅焚木村議會。', '幫助亡靈哨兵費雷亞消滅焚木村議會。', '幫助費雷亞消滅焚木村議會。', '去銀松森林找焚木村的亡靈哨兵費雷亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 453 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (453, 'zhTW', '搜尋烏鴉嶺', '祝你好運，$N。我希望你能找到這個傢伙，也希望他還活著。$B$B外面可沒有夜色鎮這麼安全，他可能早就成了野獸的獵物。', '找到那個模糊的人影。你的線索:$B$B他不是夜色鎮的本地人。$B$B他是個緊張而敏感的人。$B$B他離開夜色鎮往西邊去了。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 454 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (454, 'zhTW', '惡戰之後', '在這事之前，我們一直在來來回回拖著這幾個裝著火藥的桶往挖掘場運。現在我們得分工一下，米蘭負責搬這些桶，我負責搬其他的。不過讓米蘭一個人運送剩下的貨物我多少有點不放心，你能不能在他下次送貨的時候護送他一程呢?', '和米蘭談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 455 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (455, 'zhTW', '丹奧加茲告急', '龍喉氏族的獸人在濕地有了一處巢穴，現在他們的勢力已經快擴展到丹奧加斯了!我們可絕不能讓他們在這裡立足，不然，我們在濕地唯一的港口與要塞─米奈希爾港與洛克莫丹的聯繫將會被切斷。$B$B穿越丹奧加茲到濕地那邊去，向米奈希爾港的瓦斯塔格·鐵齶報到，路上順便殺它幾個獸人玩玩!$B$B米奈希爾就在丹奧加茲的另一邊，只要先順著路向北，然後在岔路口轉向西邊就是。$B$B我們寄希望於你， $N 。可別讓我們失望。', '翻越丹奧加茲。殺死8個龍喉斥候和6個龍喉蠻兵。向米奈希爾港的瓦斯塔格·鐵顎報到。', '翻越丹奧加茲', '去濕地找米奈希爾港的瓦斯塔格·鐵顎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 456 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (456, 'zhTW', '自然的平衡', '你好， $N 。我是管理員伊爾薩萊恩。我的職責是維護幽影谷一帶的自然平衡。$B$B今年的春雨似乎比往年來得都要連綿不絕，這導致了森林中某些動物的過度繁殖，而其他動物就遭了殃。$B$B其中，夜刃豹和草刺野豬的族群已經過於龐大了，幽影谷無法為它們提供更多的食物。去吧，年輕的 $C ，去減少野豬和夜刃豹的數量，以保證自然的和諧。', '殺死4隻小夜刃豹和4隻小草刺野豬，然後向管理員伊爾薩萊恩覆命。', '', '去泰達希爾找幽影谷的管理員伊爾薩萊恩。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 457 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (457, 'zhTW', '自然的平衡', '削減幽影谷中幼獸的數量是一個很好的開始， $N ，但這還遠遠不夠。$B$B如果問題不能得到根本解決的話，森林中的資源還是很快就會被耗盡的。為了所有共享這片大地的生物著想，殺死野生的獸類是一件必要之惡。進入幽影谷的東北方，為了自然的平衡，清除一些癩皮夜刃豹和一些草刺野豬。', '管理員伊爾薩萊恩要求你殺死5隻癩皮夜刃豹和5隻草刺野豬。', '', '去泰達希爾找幽影谷的管理員伊爾薩萊恩。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 458 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (458, 'zhTW', '森林保衛者', '謝天謝地你在這兒，$c。森林中的小精靈們告訴了我一些奇怪的消息。神秘的森林保衛者塔琳德拉又回到了幽影谷。這位林精的身影已經許多年都沒有在卡林多大陸上的森林中出現過了。她既然回到了這裡，就意味著這裡一定出了什麼事情。找到了塔琳德拉，並且問問她我們的森林到底怎麼了。有個哨兵向我報告過，塔林德拉曾在奧達希爾的西邊出現過。', '找到林精塔琳德拉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 459 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (459, 'zhTW', '森林保衛者', '一些邪惡的事物正在泰達希爾的森林中滋生著。看看那些原先性情溫和的熊怪們居住的地方吧。他們放棄了自己的家園，聚集在了所謂的脊骨部落的名下。$B$B一定是那些腐朽毒惡的魔苔的瘴氣造成了這種變異。小劣魔和劣魔也在幽影谷滋生開來，驚擾著這裡的居民。$B$B去和這些小劣魔和劣魔戰鬥吧，$n，觀察一下他們是否真的是受了魔苔的影響。', '收集8塊魔苔，把它們交給塔琳德拉。', '', '去泰達希爾找幽影谷的塔琳德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 460 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (460, 'zhTW', '支離破碎', '你看起來跟那幫腐皮豺狼人不一樣，這真好。我都快絕望了……$B$B我叫奧拉瑞克，過去曾是圖勒的大管家兼保鏢。他用他的魔法「保護」了我，使我免受「亡靈瘟疫」的影響，但他的魔法也讓我變成了這個半死不活的樣子。而且，自從圖勒創造了那群該死的腐皮豺狼人之後，他竟然砍了我的頭……還把我的頭給那群豺狼人當球踢!$B$B拜託，把我帶到我的身體那兒去。那群豺狼人大概是把它埋在了芬里斯城堡的馬廄旁……', '將奧拉瑞克的頭顱帶到他的墳墓旁。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (461, 'zhTW', '密室', '我知道在這城堡中有間密室，密室裡藏著一件對圖勒和他的同夥們來說很寶貴的東西，也許那裡面也有些對你很有用的東西。把我帶到那裡去！$B$B這密室就在城堡西南的塔里，在一處滿是灰塵的櫃子後面。$B$B帶上我的身子，但是不要靴子…這靴子就沒合適過……', '將奧拉瑞克帶到密室去。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 462 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (462, 'zhTW', '<UNUSED>', '除了你以外，我們還派了兩名斥候穿越阿爾加茲。可是只有一人回來了。以下是他打探到的消息：$B$B龍喉氏族派出了他們的一名副官——馬魯克·龍鱗，到阿爾加茲去集結一支獸人隊伍，企圖切斷通往米奈希爾港的陸路！$B$B我們必須馬上阻止這件事。除掉馬魯克，然後向米奈希爾港的瓦斯塔格·鐵顎回報。$B$B馬魯克的據點是阿爾加茲第二和第三條隧道之間、一座池塘對岸的小洞穴。要前往米奈希爾，穿過阿爾加茲後沿著道路向西走即可。', '殺死馬魯克·龍鱗$B$B向米奈希爾港的瓦斯塔格·鐵顎回報。', '', '去溼地找巴拉丁海灣的瓦斯塔格·鐵顎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 463 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (463, 'zhTW', '綠色守衛者', '你聽說過綠色守衛者?你應該不是在找他吧，是不是?如果是的話，我真的說你是個瘋子，不過我為什麼要阻止一個瘋子去找他送死呢?好吧，如果你真是在找那隻凶獸的話，我聽說它就在沼澤裡，在通向丹莫洛的那個岔路口的東邊。他就潛伏在那個危險的地方，在鱷魚群之間……聽說那裡還有些更可怕的東西!把你的錢留在這裡吧，要是你去找他，錢對你來說也就沒用……你該不會想在那傢伙咬你的時候用你的金幣給他鑲金牙吧?', '找到綠色守衛者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 464 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (464, 'zhTW', '龍喉旌旗', '按理說，龍喉氏族的獸人應該已經在第二次獸人戰爭中全部被消滅乾淨了呀。那時，他們失去了對紅龍的控制，而被奴役了許久的紅龍對獸人極度仇恨，所以就到處獵殺他們。只有一小部分龍喉獸人從格瑞姆巴托逃了出來，躲進了維爾加挖掘場東邊的山裡。$B$B現在他們的族群似乎又恢復了興盛，有線報說他們在米奈希爾的東北方建立了一座營地。$B$B我們要你去進攻那座營地，並帶回一些旌旗作為功勳評定的證據。', '給斯托菲隊長帶回8面龍喉旌旗。', '', '去濕地找米奈希爾港的斯托菲隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 465 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (465, 'zhTW', '納克羅什的優勢', '當你在和那些龍喉氏族的獸人作戰時，我們又獲得更多有關他們的作戰計畫情報。$B$B首先是一個壞消息，納克羅什正在大量地建造投石車，計畫一舉攻陷米奈希爾!還有一個好消息，經過在丹奧加茲一帶的艱苦奮戰，我們已經把他們的援軍徹底擋了回去!$B$B現在你所要做的就是毀掉那些投石車，它們目前仍被停放在龍喉氏族的營地裡。$B$B拿著，帶上這些火絨。你得先在營地裡殺出一條血路，找到那些投石車，然後再用這些火絨燒了它們。$B$B完成這一切之後，就去找納克羅什，把他給幹掉。我們必須徹底地將這些龍喉氏族的獸人消滅掉!', '摧毀所有的龍喉投石車。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 466 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (466, 'zhTW', '火岩礦石', '我聽說最近在濕地一帶發現了一種特別稀有的礦石，大家管它叫火岩，那礦坑就在奧加茲隘口西北方的一處洞穴裡。火岩礦石非常不穩定，它很容易爆炸，但我敢說，如果加工方法正確的話，它就可以用來製作威力強大的砲彈!$B$B給我搞一些火岩礦石的樣本來，我可以去找個夠膽的傢伙來對它進行實驗。$B$B哦，要想採集到這些礦石的話，你可得懂點採礦技術才行。如果你完全不懂的話，那麼……就找個懂行的朋友一起去吧!', '給丹莫洛的駕駛員迪恩·石輪帶回6份火岩礦石。', '', '去丹莫洛找鋼架補給站的駕駛員迪恩·石輪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 467 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (467, 'zhTW', '迪恩·石輪的夢想', '駕駛員迪恩·石輪和其他駕駛員一樣非常喜歡他的攻城坦克，他一直都想要找到加強坦克火力的方法！$B$B他聽說有一種罕見的礦石，現在正在到處拉人為他尋找這種礦石呢。如果你想找點事幹的話，就去丹莫洛的鋼架補給站找他，看看他都需要些什麼。', '和駕駛員迪恩·石輪談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 468 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (468, 'zhTW', '向巡山人羅克加報告', '巡山人羅克加正在招募一些能穿越丹奧加茲到濕地去執行任務的志願者。如果你想去北邊感受一下鞋子裡灌滿水的感覺，那就到丹奧加茲去找羅克加談談吧。沿著道路向北，走過哨塔就到丹奧加茲了。', '與巡山人羅克加談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 469 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (469, 'zhTW', '日常供貨', '你好，旅人!$B$B你是不是要去米奈希爾港?如果不是的話，我建議你就留在這裡吧，你要是想買點東西啊，喝一杯啊，或者放鬆放鬆神經什麼的話，這裡就再合適不過啦。$B$B如果你確實是要去米奈希爾的話，那麼……我想……你應該不會介意把這捆鱷魚皮捎給皮匠詹姆士·哈洛倫吧?$B$B我本來是想自己親自走一趟的，但我那個在城裡的老婆最近正發脾氣呢，我實在不想馬上就見到她，能拖多久就拖多久。', '將這捆鱷魚皮帶給米奈希爾港的皮匠詹姆士·哈洛倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 470 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (470, 'zhTW', '搜尋軟泥怪', '我每週都要去鐵鬚之墓做例行的拜訪。然而，上次過去的時候，我竟然遭到了那些可怕的軟泥怪的攻擊，我當時自然是嚇壞了。$B$B我身上也沒帶武器，只好抓起背包丟它們，不過那完全沒有用!軟泥怪很輕鬆地把我的背包給吞掉了……不過，幸運的是，這也為我爭取到了逃跑的時間。$B$B但是我現在很需要背包裡的東西!$B$B我已經忘記把包扔進哪隻軟泥怪裡了，它們看起來都是一模一樣的!所以呢，你恐怕得多殺個幾隻才能找到我的背包。鐵鬚之墓就在東北方，丹奧加斯附近。多謝你啦!', '鐵鬚之墓中的某隻軟泥怪身上有塞達的背包，奪回背包，把它送還給米奈希爾港的塞達。', '', '去濕地找米奈希爾港的塞達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 471 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (471, 'zhTW', '學徒的職責', '我把我的學徒派到了沼澤那邊去，希望他能給我搞到一些著名的巨型鱷魚的皮回來。然而他一直都沒回來，我只好親自去找他……怎麼說呢，反正我當時看到了一些比較慘的場面。$B$B醫生說他很快就會恢復健康的，但現在，我仍然急需鱷魚皮!$B$B……要是你能幫我殺幾條這種兇猛殘忍的大鱷魚，從它們身上給我剝幾張皮下來，我會非常高興的。沿著海岸北上，走過了那些魚人搭建的簡陋小屋之後就能找到鱷魚了。', '為米奈希爾港的詹姆士·哈洛倫帶回6張巨型鱷魚的皮。', '', '去濕地找米奈希爾港的詹姆斯·哈洛蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 472 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (472, 'zhTW', '丹莫德的陷落', '丹莫德已經被黑鐵矮人攻陷了!我傷得很重，$c。我們的大多數戰友都已經犧牲了!我們在薩多爾橋遭遇了伏擊，正在重整部隊的時候，那群該死的黑鐵矮人再度突襲了我們。我們的領袖布萊德·長鬚被迫吹響了撤退的號角。我們剛一離開鎮子，我就被人從背後砍了一斧頭，然後就眼前一黑昏死了過去。當我醒來的時候已經身在米奈希爾了，但是，我現在很擔心我手下的士兵們。我依然保有一絲希望，也許布萊德·長鬚還活著!看看你能不能在丹莫德附近找到他吧，$c!', '在丹莫德鎮附近尋找布萊德·長鬚的蹤跡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 473 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (473, 'zhTW', '向斯托菲隊長報告', '$N，龍喉氏族的獸人們一天天地壯大了起來，這樣下去它們遲早會攻破奧加茲的。斯托菲隊長正在誠招志士來對抗那些獸人，他就在城堡裡面的指揮室中。', '與斯托菲隊長談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 474 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (474, 'zhTW', '擊敗納克羅什', '現在所有的投石車都被燒掉了，找到納克羅什酋長，把他幹掉。', '殺掉納克羅什酋長。將納克羅什的頭顱交給斯托菲隊長。', '', '去濕地找米奈希爾港的斯托菲隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 475 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (475, 'zhTW', '煩惱之風', '一陣令人煩惱的微風吹過了森林。蓋洛拉斯·塔文斯倫一直負責為那些在班奈希爾獸穴中休眠的猛禽德魯伊們放哨。作為沉睡者們的保衛者，他的職責是確保德魯伊們的安全，從而使他們可以履行與伊瑟拉定下的契約。但是我很久都沒有收到蓋洛拉斯的消息，現在我已經越來越緊張了。到東邊的星風村去一趟，幫我把蓋洛拉斯的報告帶回來，這樣會讓我心裡輕鬆一些。', '在星風村找到蓋洛拉斯·塔文斯倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 476 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (476, 'zhTW', '瘤背熊怪的墮落', '瘤背部族的熊怪已經墮落了!曾經愛好和平的熊怪現在轉而與森林的保衛者為敵。我剛剛動身準備去班奈希爾獸穴的時候就遭到了它們的伏擊，而熊怪們現在還準備掠奪星風村!它們的首領─大槌烏薩爾─正在運用魔苔的邪惡力量使它們變得更加瘋狂。我傷得太重了，無法返回去把這個十萬火急的消息告訴阿斯瑞達斯。這個任務就交給你了，年輕的$c。我們只能希望瘋狂的瘤背熊怪還沒有對班奈希爾下手!', '返回多蘭納爾去見阿斯瑞達斯·熊皮。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 477 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (477, 'zhTW', '越境', '你也許知道，安伯米爾鎮裡還有一群人類在負隅頑抗，事實上，這主要是因為達拉然的巫師們在支援著他們。我不知道他們到底有什麼計畫，不過我想，既然他們對這樣一個偏僻的小鎮表現出如此濃厚的興趣，那麼這個地方一定有什麼還不為我們所知的重要意義。巫師們三不五時地用馬車把一些木箱從希爾斯布萊德運到安伯米爾去，他們補給線的終點就在焚木村北面的一處營地裡。幫我把木箱裡的東西拿來一些，讓我好好研究一下。', '從達拉然巫師的木箱中拿出裡面的東西。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 478 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (478, 'zhTW', '地圖與符記', '<你迅速從箱子裡中拿起了墜飾並將箱子重新蓋好。>', '將這個奇怪的墜飾交給瑟伯切爾的暗影牧師奧利斯特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (479, 'zhTW', '調查安伯米爾', '達拉爾正在嘗試著定位出達拉然巫師們施法時的能量流向。現在，我們必須要盡我們一切努力來暫緩他們的進程……$B$B那些咒術師、法師和保衛者恐怕會拼死保護墜飾。你必須清除掉這些阻礙，並把飾物搶到手。$B$B沿著大路向南走，在岔路口轉向東邊就可以到安伯米爾了。', '為瑟伯切爾的暗影牧師奧利斯特搶到8個達拉然墜飾。', '', '去銀松森林找瑟伯切爾的暗影牧師奧利斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (480, 'zhTW', '法師的頭領', '一位具有強大法力的大法師正在監管著啟動節點的行動。在目前的形勢下，我們只有殺死那個大法師才有可能阻止他們了。這將是個艱鉅的任務，無疑會有許多法師與守衛層層護衛著他。$B$B你必須出發了，儘快結果掉他。大法師死了以後，把他的法杖帶回來給我。現在就去，快!', '殺死達拉然大法師，並把他的法杖交給瑟伯切爾的暗影牧師奧利斯特。', '', '去銀松森林找瑟伯切爾的暗影牧師奧利斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (481, 'zhTW', '達拉爾的推理', '把這個飾物交給達拉爾·織曦者，或許他能從中發現一些蛛絲馬跡。', '把刻有符文的墜飾交給瑟伯切爾的達拉爾·織曦者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (482, 'zhTW', '達拉然的意圖', '啊！我想起來了！安伯米爾一直是為祈倫托所關注的地方，因為那裡隱藏著一個能量節點。那群法師們一定計劃啟動節點，並使用裡面蘊涵著的能量來為他們更深一層的目的服務。我們不能允許這樣的事情發生……啟動節點需要花費大量的魔法能量，只要我們把這些墜飾搶走，達拉然的法師們就無法繼續他們的行動了。把這件事告訴奧利斯特，他會制定出行動計畫的。', '與瑟伯切爾的暗影牧師奧利斯特談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (483, 'zhTW', '喚醒聖物', '瘤背部族的熊怪正在西邊山丘的班奈希爾獸穴肆虐。$B$B除非我們伸出援手，否則那些正在沉睡的德魯伊將永久地陷於翡翠夢境中，對即將降臨的噩運渾然不覺。只有拿到所有的喚醒聖物，我們才能將休眠儀式打斷。$B$B到獸穴裡去幫我找回鴉爪神符、黑色羽毛、天藍寶石和築巢符文。德魯伊們把這些聖物藏在神聖的箱子裡，把它們帶給我，我要準備進行喚醒儀式。', '尋回四件喚醒聖物，把它們帶給多蘭納爾的阿斯瑞達斯·熊皮。', '', '去找泰達希爾的阿斯瑞達斯·熊皮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (484, 'zhTW', '小鱷魚皮', '我是皮匠詹姆士·哈洛倫。我用鱷魚皮做東西的手藝可是艾澤拉斯第一流的，每天都有大船把我的產品一箱一箱地運到世界各地的港口去。$B$B你見過埃納爾了吧?他也是專門為我提供新鮮鱷魚皮的諸多獵人之一。$B$B最近我這裡的小鱷魚皮供應量在直線下降，鑒於目前我真的很缺貨，如果你能幫我弄些小鱷魚皮回來，我會給你開出一個非常不錯的價碼。你可以在鎮外的沼澤裡找到那種小鱷魚。', '為米奈希爾港口的詹姆士·哈洛倫帶回4張小鱷魚皮。', '', '去濕地找米奈希爾港的詹姆斯·哈洛蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 485 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (485, 'zhTW', '找到OOX-09/HL！', '你發現了一個奇怪的蛋形金屬物體。隨便撥弄了幾下之後，它居然自動開啟了，變成了一個看來是由地精製造的機器裝置！一個奇怪的聲音從這個蛋形機器裝置中傳了出來。$B$B“我的名字叫奧格索普，我的母體機器人不見了！如果你能幫我找到它，我就會獎勵你的！請把這個定向器帶到那個母體機器人那裡。別擔心，我現在已經檢測到了它的所在地！它現在就位於藏身石那一帶的河水源頭附近！”', '把定位器帶到奧格索普的母體機器人那裡去。$B$B奧格索普的母體機器人位於辛特蘭的河水源頭，就在藏身石的附近。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (486, 'zhTW', '『大槌』烏薩爾', '現在我們要去解救猛禽德魯伊了。如果我們失敗，他們將永遠迷失於夢境中。$B$B我將做好甦醒儀式的準備。為了進行這個儀式，必須殺死造成現在這種混亂局面的罪魁禍首。$B$B干擾我們同胞呼喚的就是『大槌』烏薩爾，只有讓他為此付出代價，猛禽德魯伊才能重獲自由。順著道路往西北方，找到往北方進入山崖的小徑。烏薩爾的巢穴就在那兒。', '殺掉『大槌』烏薩爾，然後回到多蘭納爾的阿斯瑞達斯·熊皮那裡。', '', '去找泰達希爾的阿斯瑞達斯·熊皮。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (487, 'zhTW', '達納蘇斯之路', '我們必須保證通往達納蘇斯的道路的安全。有報告說，路上的旅人經常受到腐化瘤背熊怪的殘忍襲擊。$B$B每天都有無數來自達納蘇斯的重要資訊在這條路上進行傳遞，因此我們絕不能容忍有這幫腐化熊怪恐嚇無辜的旅者。$B$B以神聖森林的名義拿起武器， $C 。熊怪們的巢穴就在北方道路的另一端。去殺死這些瘤背伏擊者再回來向我報告。', '殺掉6個瘤背伏擊者，然後向多蘭納爾城外的哨兵阿瑪拉·夜行者報告。', '', '去找泰達希爾的哨兵阿瑪拉·夜行者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (488, 'zhTW', '賽恩的要求', '我知道你渴望工作，對你來說今天是個幸運的日子，因為我今天只能靠你這個乳臭未乾的$c來幫忙了。$B$B你知道，$n，我可以使你非常幸福，我可以讓你擁有你從未想過的好東西。但是首先，你必須給我帶些東西來。$B$B我在森林裡的工作需要一些材料……給我拿來三顆夜刃豹的牙齒、三根巨翼梟的羽毛和三份樹林蜘蛛絲。', '給多蘭納爾外面的賽恩·腐蹄帶去3顆夜刃豹的牙齒、3根巨翼梟的羽毛和3份樹林蜘蛛絲。', '', '去找泰達希爾的賽恩·腐蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (489, 'zhTW', '尋求救贖!', '森林議會聽說你幫助了賽恩‧腐蹄，這個險惡的薩特是森林的敵人。作為一個 $R ，你應該更清楚我們不能殺害自然的生物，玷污聖潔的森林。$B$B如果你希望繼續做泰達希爾的朋友的話，你就必須在眾人的關注下挽回這個過錯。$B$B給賽恩‧腐蹄一個教訓，你就可以得到原諒。魔錐果是從樹上掉落的腐壞的種子，一般都冒著綠色的煙氣。$B$B給賽恩帶去3個魔錐果，他會以為那些只是無害的點心。', '收集3個魔錐果。', '', '去找泰達希爾的賽恩·腐蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 490 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (490, 'zhTW', '暫無內容', '根據達納蘇斯議會的法令，我對瘤背部落發出通緝令。它們已經不再是森林的朋友，而是威脅著我們的人民和這片土地的墮落的怪物。$B$B根據議會下達的命令，任何能幫助卡利達爾減輕熊怪的威脅的冒險者都可以獲得嘉獎。如果你也有志於幫助我們的話，就把它們的利牙帶給我作為證明。', '達納蘇斯外的莎依拉·夜風想要你帶給她20個瘤背熊怪的牙齒。', '', '去找泰達希爾的哨兵莎依拉·夜風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 491 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (491, 'zhTW', '給比索的魔杖', '圖勒曾經告訴過我，很久以前，他和兩名同僚利用各自手中的魔杖混合造出了一根新的魔杖。這根魔杖是友誼的象徵。不過圖勒雖然珍視他的友誼，但他卻更珍視這件物品，並且不會允許自己與別人共同擁有這樣一件寶物。所以他偷走了這支魔杖，將它藏在了芬里斯城堡。$B$B就是這個。將這個魔杖送給比索·埃斯沙德，許多年前他曾是圖勒的好朋友。我相信他會需要的。', '將狼人魔杖帶給幽暗城法師區的比索·埃斯沙德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 492 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (492, 'zhTW', '新的瘟疫', '亡靈衛兵們說，他們又抓住了一個愚蠢的矮人巡山人。在對這個俘虜做出「妥善」處理之前，衛兵們似乎打算把他先關在恐懼之末旅店的地下室裡。$B$B不如你幫我跑一趟，去看看這位可憐的俘虜喜歡不喜歡我為他特製的飲料吧。那飲料裡只摻了一丁點黑暗女王想在整個艾澤拉斯大陸上使用的那種東西……', '將喬漢的特製飲料交給被俘虜的巡山人。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 493 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (493, 'zhTW', '前往希爾斯布萊德丘陵', '為了給黑暗女士研究出一種新的瘟疫，皇家藥劑師學會最近正承受著巨大的壓力。當然，我們一直在努力工作並取得了突破性的進展。我們堅信，如果我們學會的成員彼此分享研究成果的話，進展將會更快。$B$B因此我要求你將這些我的最新發現送到塔倫米爾的藥劑師林度恩那裡去。塔倫米爾是一座位於希爾斯布萊德丘陵地帶的小鎮，這趟路程可能會很遠。$B$B順路一直向南走，記得看路標!', '將倫弗利爾的研究成果交給希爾斯布萊德丘陵塔倫米爾的藥劑師林度恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 494 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (494, 'zhTW', '進攻的時機', '噓!安靜點，仔細聽我說，$c。我被派到這個地方來監視希爾斯布萊德鎮裡的人類的動向，你必須把我的口信帶給塔倫米爾的高級執行官達薩利亞，跟她說一句:「西邊傳來烏鴉的第三聲叫聲。」沿著大路往東走，注意看路標。快點!趕快去塔倫米爾，這件事情很緊急!', '到塔倫米爾去，把亡靈哨兵萊什的口信帶給高級執行官達薩利亞。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 495 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (495, 'zhTW', '意志之冠', '希瓦娜斯殿下曾派出瑪格索爾和他的巨魔手下們前往奧特蘭克去奪取意志之冠。然而，不幸的是，他們並沒把它還回來，那個白癡竟然把它戴在了自己的頭上……我猜這群巨魔恐怕對這種亮閃閃的東西沒什麼抵抗力吧。無論如何，他這種自作主張的行為已經釀成了大錯。想必是意志之冠操控了他，令他背叛了希瓦娜斯殿下。黑暗女王陛下希望我們處理掉愚蠢的瑪格索爾，以此來警示其他不識時務的蠢貨。到希爾斯布萊德丘陵的塔倫米爾鎮去，向我的副官梅里薩拉報到。', '到希爾斯布萊德丘陵去，向塔倫米爾的梅里薩拉報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 496 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (496, 'zhTW', '受難藥劑', '唉，又在塔倫米爾度過了倒楣的一天。這裡的新鮮空氣讓我渾身都不舒服， $N 。$B$B我們最好早點給這些人類下毒。我一直在仔細研究我的藥物裡可能用到的致命藥劑。$B$B如果你想幫忙的話，就給我收集這些東西:10個灰熊的舌頭，還有非常稀少罕見的食苔蛛的毒液。塔倫米爾周圍到處都是熊和食苔蛛。', '塔倫米爾的藥劑師林度恩要你去收集10個灰熊的舌頭和一些食苔蛛的毒液。', '', '去希爾斯布萊德丘陵找塔倫米爾的藥劑師林度恩。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 497 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (497, 'zhTW', '暫無內容', '我的孩提時代一直都在敦霍爾德城堡接受角鬥士的訓練，在那段時間裡，塔蕾莎一直是我的朋友，她是我的乳母的女兒，也是那個該死的布萊克摩爾的情人。$B$B過去的事情就讓它過去吧，$n，但是對於人類在希爾斯布萊德的活動報告又讓我想起那段往事。我派遣了一支小分隊到那個地區去進行調查，並設法幫我找回一件……物品……一件塔蕾莎送給我的東西。$B$B這無疑是一項沒什麼戰略意義的任務，但是也許……$B$B他們早該回來複命了，但現在還是沒什麼訊息，我要你去塔倫米爾調查一下。', '到塔倫米爾去調查索爾派出的小分隊的狀況。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 498 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (498, 'zhTW', '拯救行動', '酋長派我和其他一些戰士從敦霍爾德拿回一件東西，並調查這個所謂的辛迪加。$B$B我們到敦霍爾德去轉了一圈，很驚訝地在那裡看到了很多人類。我們勇敢地和他們戰鬥，不過他們在人數上佔有絕對的優勢。我們當中有些同伴被俘虜了，不過我逃了出來。$B$B敦霍爾德就在這裡的東南部，過了河就是。德盧爾和托格薩還被囚禁在那裡，你得去把他們救回來。', '塔倫米爾的克魯斯克要你把德盧爾和托格薩從敦霍爾德城堡救出來。', '', '去希爾斯布萊德丘陵找塔倫米爾的克魯斯克。', '救出德盧爾', '救出托格薩', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 499 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (499, 'zhTW', '受難藥劑', '我得花一會兒時間把這些成分混合在一起，做成受難藥劑。$B$B成功了！啊，還有什麼能比給這個世界帶來點災難更讓人愉快的呢？$B$B讓我們看看這種藥劑能不能達到預期的效果。$B$B讓我的助手烏比瞧瞧黑暗女王為人類和天譴軍團準備了什麼樣的禮物。', '把受難藥劑交給烏比。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (500, 'zhTW', '破碎嶺巨魔', '破碎嶺巨魔在奧特蘭克城廢墟附近的山上挖了一座小丘。我的斥候告訴我，他們現在還佔領了那片遺跡。$B$B我們可不能讓他們在那兒享福，一旦他們覺得在那兒生活很安全，下一步就會轉移到丘陵地帶，然後就是我們南海鎮了!$B$B到北方的奧特蘭克山去獵殺幾個巨魔。把他們那骯髒的指節骨帶回來，我會給你獎賞的。', '從奧特蘭克山的破碎嶺巨魔身上收集9個骯髒的指節骨，把它們帶給南海鎮的治安官雷德帕斯。', '', '去希爾斯布萊德丘陵找南海鎮的治安官雷德帕斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (501, 'zhTW', '痛苦藥劑', '哦， $N ……希爾斯布萊德的花都開了，空氣這麼清新，讓我不得不沉湎在這種痛苦之中。我從骯髒的窗子裡望出去，渴望著那一天早點到來，讓整個世界都感染上新的瘟疫，讓他們得到應有的報應。$B$B我喜歡整天坐在這裡思考，而現在黑暗女王賦予我的使命正在召喚我，請你幫幫我吧。我的研究表明，山地獅的血液可以製作出最棒的毒酒來。給我找一點來，讓我們做點有趣的事吧。', '收集10瓶山地獅的血液，把它們交給塔倫米爾的藥劑師林度恩。', '', '去希爾斯布萊德丘陵找塔倫米爾的藥劑師林度恩。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (502, 'zhTW', '痛苦藥劑', '啊，我最喜歡的就是在這丘陵地區彌漫的鮮血的氣味！$B$B現在我們加點這個再加點那個，然後最有趣的事情就要發生了！我想把這瓶用血製成的藥劑叫做痛苦藥劑。如果我的計算正確的話，這個藥劑肯定能給希瓦娜斯殿下帶來不少好處。不過我們還需要做個實驗才能確認這一點。$B$B把這瓶藥劑拿到西南方的希爾斯布萊德農場，然後到那個地區北部的農莊裡去，讓我們看看農夫雷恩的小狗斯坦利喜不喜歡這份「禮物」。', '把痛苦藥劑餵給小狗斯坦利。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (503, 'zhTW', '高迪爾', '從你拿到的檔案來看，高迪爾被關在北邊的一個辛迪加基地裡，很有可能就在奧特蘭克山。他已經被關押太久了，你必須儘快把他救出來。', '救出高迪爾，然後回到塔倫米爾去見克魯斯克。', '找出關押高迪爾的地方', '去奧特蘭克山脈找高地的高迪爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (504, 'zhTW', '破碎嶺好戰者', '你已經和破碎嶺巨魔打過交道了，現在我要你去好好教訓教訓他們……$B$B到奧特蘭克遺跡去獵殺那些破碎嶺好戰者。我希望你多幹掉一些─只有這樣才能讓這幫畜生離聯盟的領土遠一點。', '殺死10個破碎嶺好戰者，然後回南海鎮向治安官雷德帕斯報告。', '', '去希爾斯布萊德丘陵找南海鎮的治安官雷德帕斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (505, 'zhTW', '辛迪加刺客', '我是南海鎮的新鎮長，前一任鎮長被刺殺之後，我剛剛上任。那些刺客一直都沒有找到，不過據我們調查，幾乎可以肯定他們是由辛迪加雇傭的─辛迪加是一個由邪惡的貴族掌管著的盜賊組織，而那些貴族則是已經陷落的奧特蘭克王國的遺老遺少。$B$B辛迪加在索菲亞高地及考蘭之匕各設有一個營地，就位於部落佔據的塔倫米爾的北方及西方。殺掉所有你在這些營地看到的辛迪加成員。', '殺死12個辛迪加劫匪和8個辛迪加盜賊，然後回到南海鎮向赫尼·馬雷布鎮長報到。', '', '去希爾斯布萊德丘陵找南海鎮的赫尼·馬雷布鎮長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (506, 'zhTW', '布萊克摩爾的餘孽', '一兩天前，辛迪加的首領來找過我。他叫奧裡登·匹瑞諾德，他聲稱自己是這片土地的領主。他向我吐露了他的計劃，說要把反對他的那些獸人都變成奴隸，就象他的父親和導師埃德拉斯·布萊克摩爾所計劃的那樣。$B$B更重要的是他還帶著他的小情人，一個名叫艾麗薩的嬌弱女孩。酋長想得到她脖子上帶著的項鍊。$B$B現在你可以回去報信了，等手頭上的事情忙完之後，我會自己回去的。', '把高迪爾收集的訊息帶給塔倫米爾的克魯斯克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 507 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (507, 'zhTW', '奧裡登·匹瑞諾德', '匹瑞諾德一定要被除掉，這個卑鄙的傢伙絕不能繼續在這世上逍遙了。他的領地就在北邊的洛丹米爾湖岸上。去完成這個任務，$n，別忘了把酋長想要的項鍊也拿到手，然後再回到這裡來。', '殺了奧裡登·匹瑞諾德領主，並從他的情人艾麗薩身上拿回塔蕾莎的項鍊。', '', '去奧特蘭克山脈找在高地的艾麗薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 508 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (508, 'zhTW', '塔蕾莎的禮物', '項鍊嗎？當然可以給你……拿走它吧！我不想再跟他有什麼瓜葛了……求求你，別殺我……', '把塔蕾莎的項鍊交還給塔倫米爾的克魯斯克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 509 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (509, 'zhTW', '苦楚藥劑', '又是新的一天，又有一種新的藥劑要配製。要我說，我寧願讓那些可憐的人類和天譴軍團去互相拼命，他們就喜歡互相殘殺。$B$B既然黑暗女王要加速這個過程，不如在這段恐怖的日子裡再給這片土地加點死亡和疾病怎麼樣？$B$B我有個計劃，$N，你現在到奈杉德哨崗去，那地方在塔倫米爾的南邊，南海鎮的東邊。給我找6朵泥頭花來讓我配製藥劑。', '收集6朵泥頭花，把它們交給塔倫米爾的藥劑師林度恩。', '', '去希爾斯布萊德丘陵找塔倫米爾的藥劑師林度恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (510, 'zhTW', '預備行動計畫', '這些文件當中有一份物資清單，清單裡包括各種日常物品(食物、武器、衣服)和其他工具(面具、油、毒藥)。$B$B不過其中提到最重要的就是:儘快取得清單中的物資，為文件裡所說的「針對南海鎮的重要使命」進行準備。', '把預備行動計畫帶給南海鎮的赫尼·馬雷布鎮長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (511, 'zhTW', '密文信件', '桌上有一封用密文寫成的信，你根本沒法讀懂。', '把密碼信交給南海鎮的博學者迪布斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (512, 'zhTW', '貴族之死', '我擔心辛迪加的幕後首腦想要毀滅南海鎮，因此我們必須在他們的計畫得以實現之前幹掉這些頭目。$B$B你去北邊奧特蘭克山裡的斯坦恩布萊德廢墟調查一下，我們覺得那裡是辛迪加的指揮部。$B$B我們知道這幫刺客是以前的奧特蘭克貴族指使的，貴族們可能會打扮成普通辛迪加密探的樣子，不過通過他們手上戴著的徽記之戒就能很容易地判斷他們是不是貴族了。$B$B把他們的璽戒給我拿來。', '為南海鎮的赫尼·馬雷布鎮長收集7個奧特蘭克璽戒。', '', '去希爾斯布萊德丘陵找南海鎮的赫尼·馬雷布鎮長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 513 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (513, 'zhTW', '苦楚藥劑', '就在我覺得這一天又要無趣地打發掉的時候，你給我帶來了這些泥頭花。$B$B等我把它們混合在一起。我們還需要幽暗城的大藥劑師法拉尼爾給藥劑里加上他的腐蝕膠體，然後就等著看好戲吧！$B$B把這個泥頭花葯拿去交給大藥劑師法拉尼爾，$N，現在就去。', '把泥頭花葯交給幽暗城的大藥劑師法拉尼爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 514 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (514, 'zhTW', '鐵爐堡的解碼者', '我在鐵爐堡有個同僚也許可以幫忙破譯這封信。到鐵爐堡的探險者協會去找勘察員雷矛談一談，告訴他是我讓你去的，把這封信給他看。黑石塔以北如果還有人能讀懂這封信的話，那一定就是他了。', '把密碼信帶給鐵爐堡的勘察員塔伯斯·雷矛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 515 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (515, 'zhTW', '苦楚藥劑', '泥頭花葯？太棒了！我怎麼就沒想到過這個呢？$B$B讓我給這種可怕的藥劑裡面加入我研製的腐蝕膠體。$B$B如果要啟用泥頭花水裡的汙染成分，林度恩就得先弄到強力巨魔之血藥水，還有南海岸的刺脊納迦的鱗片和碎鰭魚人的眼球。你去找到這些試劑，林度恩會知道怎麼處理它們的。天哪，我真想早點知道他的實驗進行得怎麼樣了！', '把泥頭花水、1瓶強力巨魔之血藥水、5塊刺脊納迦的鱗片和5顆碎鰭魚人的眼球交給塔倫米爾的藥劑師林度恩。', '', '去希爾斯布萊德丘陵找塔倫米爾的藥劑師林度恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 516 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (516, 'zhTW', '博倫的巢穴', '我收到報告說，一群天譴軍團的不死生物正在附近集結，準備對我們進行一次襲擊。既然得到了這樣的情報，我們就本應該先下手攻擊他們，把他們的計畫粉碎在繈褓中才對。$B$B但不幸的是，我的情報十分有限，只知道他們在一個名為博倫的巢穴的山洞裡集結。確切的位置我也不清楚，但應該在安伯米爾附近的山區中。$B$B我相信以你的能力和才智，一定可以找到他們，幹掉他們。', '找到博倫的巢穴，殺死6名鴉爪苦工和6名鴉爪守護者，然後向瑟伯切爾的暗影牧師奧利斯特彙報。', '', '去銀松森林找瑟伯切爾的暗影牧師奧利斯特。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 517 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (517, 'zhTW', '苦楚藥劑', '新藥劑終於進入了實驗階段,不過為什麼我們要把一種完美無缺、具有高度傳染性的瘟疫浪費在一隻青蛙或一條狗身上呢？讓我們以希爾瓦娜斯大人的名義好好找點樂子吧。$B$B到丹加洛克去，你知道，就是到那些骯髒的小矮人出沒的軍營裡去，給我偷一桶礦工烈酒出來，有了它，你我就可以開始狂歡了，$N。', '將一桶礦工烈酒交給塔倫米爾的藥劑師林度恩。', '', '去希爾斯布萊德丘陵找塔倫米爾的藥劑師林度恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (518, 'zhTW', '意志之冠', '瑪格索爾和他的破碎嶺食人魔在奧特蘭克廢墟已經氾濫成災了。不減少食人魔的數量的話，我們就很難去對付瑪格索爾。$B$B等他們的實力被削弱以後，我們就能繼續前進了。$B$B懂了嗎？好的。去吧。', '塔倫米爾的梅里薩拉要你去殺掉10個破碎嶺虐待者。', '', '去希爾斯布萊德丘陵找塔倫米爾的梅里薩拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 519 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (519, 'zhTW', '意志之冠', '塔爾格、瑪克拉克和戈洛姆斯都是瑪格索爾的下屬。我們不知道食人魔的忠心來源於什麼，不過他們對瑪格索爾可是死心塌地。$B$B把他們的頭給我帶回來，$n，接下來就是砍掉瑪格索爾的腦袋，徹底瓦解那些食人魔。', '幹掉塔爾格、瑪克拉克和戈洛姆斯，把他們的頭帶給塔倫米爾的梅里薩拉。', '', '去希爾斯布萊德丘陵找塔倫米爾的梅里薩拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 520 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (520, 'zhTW', '意志之冠', '瑪格索爾的下屬都死了，剩下的就是殺掉瑪格索爾，取回意志之冠。他當然不想失去那頂王冠，所以我想你最好……首先將他周圍的障礙都幹掉。$B$B找到瑪格索爾，把他的腦袋和王冠一起帶回來。破碎嶺的抵抗就到此為止了。', '殺了瑪格索爾，帶著他的腦袋和意志之冠去塔倫米爾見梅里薩拉。', '', '去希爾斯布萊德丘陵找塔倫米爾的梅里薩拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (521, 'zhTW', '意志之冠', '剩下的任務就是把意志之冠交給幽暗城的沙琳德拉。她會派人送去給希爾瓦娜斯大人。我得警告你，別想把它留著自己用，瑪格索爾的死就是最好的例子。', '把意志之冠交給幽暗城的沙琳德拉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 522 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (522, 'zhTW', '刺客的契約', '這是一份刺殺赫尼·馬雷布鎮長的契約。合約已經封好，並用一個特殊的璽戒在紅蠟上做了標記。', '把刺客的契約帶給南海鎮的赫尼·馬雷布鎮長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 523 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (523, 'zhTW', '男爵之死', '你找到的契約是瓦杜斯男爵簽署的，他是以前的奧特蘭克王國的貴族，並且一向以冷酷和殘暴而著稱。這件事的背後由瓦杜斯這樣的人主使，我對此一點也不感到奇怪。$B$B去找到他，讓他受到正義的制裁。他一定在辛迪加經常出沒的地方活動，也許在斯坦恩布萊德的廢墟，也許在廢墟北面的山谷裡。', '把瓦杜斯男爵的頭帶給南海鎮的赫尼·馬雷布鎮長。', '', '去希爾斯布萊德丘陵找南海鎮的赫尼·馬雷布鎮長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 524 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (524, 'zhTW', '苦楚藥劑', '隔壁的亡靈衛兵看守著幾個被俘的人類農夫。高級執行官達薩利亞本來懷疑有一個暴風城來的軍事顧問就藏在他們當中，不過我們昨晚發現那個可憐傢伙的屍體就躺在瘟疫之地。因此，達薩利亞決定讓我來處理這些沒什麼價值的戰俘。$B$B我看是時候給這些農夫開個宴會了。這主意聽上去真棒，就這麼幹！$B$B把這隻被汙染的酒桶放在他們房間的地毯上，給他們來一點帶著瘟疫的酒！', '把被汙染的酒桶放在被俘農夫房間的地毯上。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 525 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (525, 'zhTW', '更大的謎團', '我已經譯出了這封信，不過還是不知道它是什麼意思。你是在奧特蘭克丘陵的盜賊身上找到這封信的嗎?真奇怪……$B$B你應該把它拿去給南海鎮的鎮長看看。雖然這封信的含義不甚明瞭，但是南海鎮離奧特蘭克最近，如果有什麼威脅正在臨近的話，我想應該先告訴他。', '把被破譯的信件交給南海鎮的赫尼·馬雷布鎮長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 526 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (526, 'zhTW', '光鑄鐵錠', '你可能已經在那箱子裡找到了一塊光鑄鐵錠，但如果要打造些什麼東西的話，這麼一點鐵是絕對不夠的！$B$B你得再回去看看，沒準在船隻殘骸附近的魚人身上會有更多的光鑄鐵錠。', '收集5塊光鑄鐵錠，把它們交給溼地的戈羅林·鋼眉。', '', '去溼地找米奈希爾港的戈羅林·鋼眉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 527 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (527, 'zhTW', '希爾斯布萊德之戰', '和我說話的時候要立正，$c。$B$B我受瓦里瑪薩斯的直接領導。在我們的藥劑師研製出新型瘟疫之前，我們必須要壓制住人類的攻勢。$B$B有訊息表明，希爾斯布萊德鎮是個防守很薄弱的小鎮。你的第一個任務是擾亂敵人的食品供給和基礎設施建設。$B$B從這裡往西邊方向進發，你的目標是希爾斯布萊德平原最北邊的農場，在那裡大開殺戒的同時，別忘了把當地的農場主——農夫雷恩和農夫蓋茲也給幹掉。', '殺掉6個希爾斯布萊德僱農和6個希爾斯布萊德農夫，還有農夫雷恩和農夫蓋茲，然後返回塔倫米爾向達薩利亞報告。', '', '去希爾斯布萊德丘陵找塔倫米爾的高級執行官達薩利亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 528 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (528, 'zhTW', '希爾斯布萊德之戰', '北方農場被襲擊的訊息讓人類的村民們驚慌失措，你幹得很出色。$B$B我們的哨兵報告說有農民向希爾斯布萊德南部逃散——這些傻瓜以為他們可以藏在果園裡逃過一死。$B$B去結果他們吧，$N。回到希爾斯布萊德農場去，把這些東躲西藏的農民找出來，以黑暗女王的名義殺了他們。$B$B解散！', '殺死15個希爾斯布萊德農民，然後回到塔倫米爾向達薩利亞彙報。', '', '去希爾斯布萊德丘陵找塔倫米爾的高級執行官達薩利亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 529 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (529, 'zhTW', '希爾斯布萊德之戰', '希爾斯布萊德的人類進行了頑強的抵抗，這實在有點出乎我的意料。問題的關鍵在於，有幾個鐵匠在為那些鎮民提供武器，我們得切斷他們的所有供給線。$B$B你的任務是幹掉鐵匠維林坦，還有他的那些學徒也得殺了。還有，把他們庫存的鐵也給搶回來。等我們征服了希爾斯布萊德並開始準備進攻南海鎮的時候，這些物資就顯得非常重要了。', '殺掉鐵匠維林坦和4個希爾斯布萊德見習鐵匠，並從那裡搶回一箱鐵材，然後向塔倫米爾的達薩利亞彙報。', '', '去希爾斯布萊德丘陵找塔倫米爾的高級執行官達薩利亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 530 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (530, 'zhTW', '丈夫的復仇', '瓦德雷曾經是我的好朋友，但他也是殺害我妻子的兇手。雖然我已經不知道悲傷為何物了，但我復仇的念頭卻一直沒有改變。去幫我殺了瓦德雷，把他那雙邪惡的手帶給我，我會獎賞你的。$B$B我最後一次聽到他的消息時，他正準備從銀松森林南部的葛雷邁恩之牆逃往吉爾尼斯王國。', '殺掉瓦德雷·莫萊。', '', '去找羅德隆廢墟的拉林夫·安迪恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 531 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (531, 'zhTW', '維林的報復', '天哪!別把這種東西帶到營地裡來……它太骯髒，太可怕…太…太骯髒了!$B$B你把它拿出去行不行?沒有人想看到你這件血淋淋的戰利品!真的!', '把奧爾蘇迪的頭交給遠行者小屋的維林·疾風。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 532 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (532, 'zhTW', '希爾斯布萊德之戰', '希爾斯布萊德鎮現在一片混亂，我們相信它很快就要被攻陷了。但是，我們必須繼續堅持對敵人不斷地發動攻擊，直到把所有的人類渣滓都完全從這裡趕出去為止。$B$B雖然人類損失慘重，但他們仍然團結在領袖的周圍繼續抵抗。我們得除掉他們的首領波恩塞德鎮長，當然還有鎮議會的成員。最後別忘了毀掉他們的政治檔案《希爾斯布萊德宣言》，順便把鎮裡的文件也都偷過來。', '殺掉波恩塞德鎮長和4個希爾斯布萊德議員，摧毀《希爾斯布萊德宣言》，偷取希爾斯布萊德城鎮文件，然後回到塔倫米爾向達薩利亞彙報。', '', '去希爾斯布萊德丘陵找塔倫米爾的高級執行官達薩利亞。', '', '', '《希爾斯布萊德宣言》已經被毀', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 533 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (533, 'zhTW', '秘密潛入', '我們終於得到了關於高迪爾的線索。人類不停地到處轉移他，但是我們已經縮小了搜尋範圍，現在我們的注意力主要集中在北邊的那個辛迪加營地裡。$B$B到那兒去打探一下，然後回來向我報告。', '把關於高迪爾下落的訊息帶回來給塔倫米爾的克魯斯克。', '', '去希爾斯布萊德丘陵找塔倫米爾的克魯斯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 534 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (534, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 535 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (535, 'zhTW', '僕從瓦里克', '呃……重病、瀕死，而且還要與敵人作戰。$B$B毫無疑問，你會殺了我，但如果你可以帶給我些南海鎮烈酒的話，我會告訴你所有你想知道的——我想你們$r平時也喜歡喝點什麼吧，不是嗎？', '給辛迪加營地裡的瓦里克帶去一杯南海鎮烈酒。', '', '去奧特蘭克山找索菲亞高地的僕從瓦里克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 536 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (536, 'zhTW', '清理海岸', '我從暴風城守衛被調到這個鳥不生蛋的南海鎮來做守衛，這鎮子簡直是一無是處……整日整夜都是一股魚腥味。$B$B更別提治安官雷德帕斯了……他還想要我去對付那幫魚人，哈!$B$B我很難打起精神去跟西部海岸上的那群奇形怪狀的魚人作戰。如果你願意替我去幹掉它們，我會很感激你的。', '南海鎮的法爾林·奧里涅爾中尉要你去殺掉10個碎鰭獵潮魚人和10個碎鰭神諭者。', '', '去希爾斯布萊德丘陵找南海鎮的法爾林·奧裡涅爾中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 537 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (537, 'zhTW', '黑暗議會', '你拿來的信是一個自稱為納伽茲的人寫的，他是阿古斯覺醒的一員。我不知道這個阿古斯覺醒是個什麼樣的組織，不過如果他們和辛迪加是一夥的話，就是我們的威脅。$B$B我要你去查查這封信上提到的納伽茲和阿古斯暗影法師。找到他們，把他們幹掉。$B$B去高地看看，那裡是辛迪加的勢力範圍，就在斯坦恩布萊德的北面。$B$B如果運氣夠好的話，你就能在那兒找到這些阿古斯覺醒的特使。', '殺死4個阿古斯暗影法師。', '', '去希爾斯布萊德丘陵找南海鎮的赫尼·馬雷布鎮長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 538 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (538, 'zhTW', '南海鎮', '$N，如果你不介意多跑點路的話，我有件任務給你，好為我們的暴風城圖書館增加一些書籍。古代王國奧特蘭克在大戰之後就已經衰落了，但那裡有著大量的藏書。奧特蘭克的都城被毀實在是個悲劇，但如果他們的知識也失傳了的話，那就將是個更大的悲劇!我們必須竭盡全力地挽救我們能挽救的東西。南海鎮是最接近奧特蘭克廢墟的地方，到那裡去找博學者迪布斯吧，他會告訴你在哪裡可以找到書。', '與南海鎮的博學者迪布斯交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 539 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (539, 'zhTW', '希爾斯布萊德之戰', '希爾斯布萊德城鎮文件裡的記錄表明，碧玉礦洞已經處於聯盟的控制之下——這個礦洞是聯盟兵工廠運轉所需的鐵礦石的主要來源。$B$B雖然我們已經對希爾斯布萊德鎮進行了致命的打擊，但是聯盟還是積極地支援和保護著碧玉礦洞。$B$B這個礦洞就在希爾斯布萊德的正南方。到那裡去殺了他們的工頭，一個名叫邦德斯的人類，順便把那裡的礦工也幹掉。這樣的行動可以給聯盟傳達一個足夠清楚的訊息。', '殺死工頭邦德斯和10個希爾斯布萊德礦工，然後回到塔倫米爾向達薩利亞彙報。', '', '去希爾斯布萊德丘陵找塔倫米爾的高級執行官達薩利亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 540 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (540, 'zhTW', '保全書籍', '那些野蠻的巨魔現在就駐紮在奧特蘭克廢墟，一想起他們會把那裡的書籍怎麼樣，我就感到毛骨悚然。你一定要盡力去完成我給你的任務!$B$B進入奧特蘭克廢墟，找到巨魔奪走的書籍。把你找到的所有東西都帶給我，特別是這本書:《格里雷克之臂》。這本書裡寫著食人妖的古老學說，我一定要學。奧特蘭克是完整保存這本書的唯一地方。', '把5本失而復得的書籍和包含《格里雷克之臂》的破舊的皮書帶給南海鎮的博學大師迪布斯。', '', '到希爾斯布萊德丘陵的南海鎮找博學大師迪布斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (541, 'zhTW', '希爾斯布萊德之戰', '矮人正在協助人類？這幫骯髒的小東西。$B$B我們得看看這所謂的聯盟的實力到底如何。等這些矮子知道我們的厲害之後，看他們還願不願意繼續給人類賣命！$B$B我們知道這些矮人的據點在哪裡，他們在希爾斯布萊德東南部沿著索拉丁之牆的地方建立了一個被稱作丹加洛克的軍營。你的最終目標是攻佔丹加洛克，$c。他們的首領達倫·鐵山上尉必須得死。', '到丹加洛克去殺掉8個巡山人、4個火槍手、2個牧師，還有達倫·鐵山上尉，然後回到塔倫米爾向達薩利亞彙報。', '', '去希爾斯布萊德丘陵找塔倫米爾的高級執行官達薩利亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (542, 'zhTW', '向米爾頓回覆', '我得花點時間來研究你帶回來的《格里雷克之臂》，不過我敢說密爾頓已經等不急要把你找回來的另一些書放到暴風城的圖書館裡去了。$B$B這些就是你從奧特蘭克廢墟帶回來的書，我已經按照目錄分類整理過了。把它們帶給暴風城的密爾頓·西弗，他一定會很感激你的。', '把奧特蘭克的書籍帶給暴風城的密爾頓·西弗。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 543 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (543, 'zhTW', '匹瑞諾德冠冕', '匹瑞諾德冠冕據說是奧特蘭克王國被毀滅之前的『名門望族』匹瑞諾德家族的傳家之寶，有人說它是由鐵爐堡的珠寶大師們用最美麗的翡翠製成的。$B$B當奧特蘭克家族被毀滅的時候，冠冕也隨之遺失了。但有傳聞說有一個巨魔法師─叫什麼『守財奴』格雷爾伯格的傢伙─得到了它，那傢伙現在還在奧特蘭克遺跡附近遊蕩，想要找到更多的財寶。$B$B我們希望你能為我們取回冠冕。', '將匹瑞諾德冠冕帶給暴風城的雷明頓·瑞治維爾。', '', '去暴風城找暴風要塞的雷明頓·瑞治維爾伯爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 544 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (544, 'zhTW', '入室偷竊', '我本來是到塔倫米爾來做研究的，不過現在我手頭上有個麻煩一定要儘快解決掉。你知道，幾個月前曾有四個被遺忘者從幽暗城逃了出來。他們拋棄了自己的同伴，這沒什麼，但問題是……他們偷了黑暗女王的東西。$B$B這些小偷闖入了一間秘密的地窖，偷走了四件供藥劑師研究用的神器。黑暗女王命令我們把這四件神器找回來。$B$B小偷從幽暗城逃到了達拉然，而那些巫師則把他們收留在洛丹米爾收容所裡。', '找到被遺忘者的叛徒，取回他們偷走的神器，然後回到塔倫米爾去見大法師沃迪恩·伍德格萊爾。', '', '去希爾斯布萊德丘陵找塔倫米爾的大法師沃迪恩·伍德格萊爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 545 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (545, 'zhTW', '達拉然巡邏隊', '達拉然的巫師在他們的城市中心建起一個巨大的魔法護罩。有人認為那是為了防止城市遭到攻擊，還有人認為他們只是想有個安靜的地方供他們進行魔法研究。$B$B不管那到底是什麼原因，我關心的是在那個護罩之外的郊區廢墟裡是否藏著有用的魔法物品。$B$B不過那裡有許多巫師和他們的元素奴僕在到處巡邏。$B$B去殺了他們，殺到你手軟之後再回來吧。', '殺掉6個達拉然召喚師和12個元素奴僕，然後回到塔倫米爾去見大法師沃迪恩·伍德格萊爾。', '', '去希爾斯布萊德丘陵找塔倫米爾的大法師沃迪恩·伍德格萊爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 546 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (546, 'zhTW', '死亡的紀念品', '聽說達薩利亞讓你和希爾斯布萊德的人類作戰，我很嫉妒你……$B$B你在外面享受屠殺人類、掠奪城鎮、恐嚇無辜者的快樂，而我卻像木頭一樣待在塔倫米爾做守衛。$B$B你能可憐可憐像我這樣的老亡靈衛兵嗎？你知道我在收集人類的顱骨，正好你還要和人類戰鬥一段時間。那麼，能不能在你作戰的這段時間裡順便給我收集30個顱骨來？我會讓你的努力物有所值的。', '塔倫米爾的亡靈衛兵沙穆薩想要30個希爾斯布萊德人類顱骨。', '', '去希爾斯布萊德丘陵找塔倫米爾的亡靈衛兵沙穆薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 547 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (547, 'zhTW', '亨伯特的長劍', '高級執行官達薩利亞派我從遠處監視丹加洛克。我在一個隱蔽的角落裡紮了營，但是那天早上我在燒水的時候離開了一會兒去找柴火……$B$B等我回來時，發現放在營地裡的裝備已經不見了。$B$B一定是那些丹加洛克的矮人偵察兵從這兒經過的時候把東西拿走了。我必須得拿回我的劍！如果你能幫我拿回來的話，我會很感激你的。但是那兒的矮人真是太多了……也許你很難在他們當中找出那個小偷。', '從丹加洛克拿回亡靈衛兵亨伯特的長劍，然後回到塔倫米爾把劍還給他。', '', '去希爾斯布萊德丘陵找塔倫米爾的亡靈衛兵亨伯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (548, 'zhTW', '暫無內容', 'This will start the Bloodstone Pendant quest line...<NYI>', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 549 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (549, 'zhTW', '通緝：辛迪加成員', '經由黑暗女王希爾瓦娜斯授權，辛迪加組織的全部成員都將被處死！那些已經被羈押和俘虜的辛迪加成員必須立刻處決。殘餘的辛迪加成員目前在塔倫米爾東南部的敦霍爾德城堡廢墟聚集。$B$B任何向高級執行官達薩利亞證明自己完成了這個任務的人都會受到重賞。', '殺死10個辛迪加盜賊和10個辛迪加哨兵，然後回到塔倫米爾向高級執行官達薩利亞報告。', '', '去希爾斯布萊德丘陵找塔倫米爾的高級執行官達薩利亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 550 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (550, 'zhTW', '希爾斯布萊德之戰', '由於你在希爾斯布萊德戰役中的英勇表現，我已經向上級寫了這封褒獎狀以表揚你。$B$B把這密封的獎狀帶給幽暗城的瓦里瑪薩斯大人，你可以滿懷驕傲地去見他，$c。', '把達薩利亞的獎狀交給幽暗城的瓦里瑪薩斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 551 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (551, 'zhTW', '附有魔法的羊皮紙', '這張羊皮紙上被施加了某種咒語，使其無法被破譯。但是，卷首的一個詞卻很容易辨認：$B$B$B      納伽茲$B$B', '將這張附有魔法的羊皮紙帶給南海鎮的博學者迪布斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 552 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (552, 'zhTW', '赫爾庫拉的復仇', '正在赫爾庫拉大人即將完成他的巫妖儀式的緊要關頭，一群人類暴徒發現了他在山上進行儀式的位置，把他殘忍地殺害了。更糟的是，他們把他的遺骨埋在了南海鎮的墓地裡。$B$B這種不尊重偉大的巫師的行徑絕對是無法讓人接受的。作為他的學徒，我一定要讓復仇降臨在南海鎮。$B$B首先我們得找到赫爾庫拉的魔棒，前不久，一群雪怪侵襲了赫爾庫拉的巢穴。毫無疑問是他們當中的一個拿走了赫爾庫拉的魔棒。', '從雪怪手上拿回赫爾庫拉的魔棒，把它交給塔倫米爾的學徒塞萬德。', '', '去希爾斯布萊德丘陵找塔倫米爾的學徒塞萬德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 553 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (553, 'zhTW', '赫爾庫拉的復仇', '拿著赫爾庫拉的魔棒，你會用得著它的。$B$B赫爾庫拉用3個火葬柴堆來構築他最強大的法術：埃希爾之焰和沃拉茲之焰在丘陵地帶的洞穴裡，尤基爾之焰在丘陵洞穴上面的另一個洞穴，在山的更北邊。$B$B赫爾庫拉的魔棒必須經過這三堆火焰的洗禮才能發揮作用。在儀式完成之後，把魔棒帶到赫爾庫拉的墓地去，那座墓地就在由人類重兵把守的南海鎮。讓赫爾庫拉的復仇降臨在愚蠢的人類頭上吧！', '將埃希爾之焰、沃拉茲之焰和尤基爾之焰的力量注入赫爾庫拉的魔棒。$B$B把經過儀式洗禮之後的魔棒帶到南海鎮的赫爾庫拉墓地。', '', '去希爾斯布萊德丘陵的南海鎮墳場找赫爾庫拉的墓地。', '埃希爾之焰的力量已經注入', '沃拉茲之焰的力量已經注入', '尤基爾之焰的力量已經注入', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 554 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (554, 'zhTW', '解碼高手', '勘察員塔伯斯·雷矛是解碼和譯碼的高手。把你找到的羊皮紙交給他，運氣好的話，他說不定能弄清楚這裡面寫著什麼。塔伯斯·雷矛現在正在鐵爐堡的勘礦指揮部進修。$B$B見到他的話，就說你已經跟我談過了，好像我最近給他添了不少的麻煩……', '把附有魔法的羊皮紙帶給鐵爐堡的勘察員塔伯斯·雷矛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 555 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (555, 'zhTW', '海龜湯', '關於南海鎮，你最需要瞭解的是我們這兒有暴風城以北地區最好的美食!$B$B比如說我的秘密食譜:海龜湯。我聽說曾有人遠從夜色鎮趕來這裡，只為品嘗一碗海龜湯!不過我最近一直都沒做過這種美食。我曾經從達拉然一直走到洛丹米爾湖去捕獵鉗嘴龜，不過現在實在不是外出冒險的時候。如果你從北邊那條河里弄點鉗嘴龜身上的海龜肉來給我，我就能很快做出點海龜湯來讓你大飽口福。', '給南海鎮的廚師傑森帶去10塊海龜肉。', '', '去希爾斯布萊德丘陵找南海鎮的廚師傑森。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 556 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (556, 'zhTW', '石雕', '達拉然巫師的一項舉世聞名的能力就是他們可以操縱如元素生物這樣的從其它空間來的強大生物，他們使用魔法石雕作為控制這些元素生物的工具，現在大法師伍德格萊爾想找些石雕來研究。$B$B進入達拉然巫師的領地，去給我找些用舊的石雕回來。$B$B你可以在任何一個達拉然市民的身上找到這種石雕，不過我建議你還是去收容所一帶找找，那裡可比達拉然安全多了。', '收集10個用舊的石雕，把它們帶給塔倫米爾的看守者貝爾杜加。', '', '去希爾斯布萊德丘陵找塔倫米爾的看守者貝瓦里爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 557 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (557, 'zhTW', '地縛護腕', '大法師會對你帶回來的石雕進行研究，不過我知道他會需要一些和石雕配合的東西，也就是地縛護腕。法師們將這些護腕帶在元素生物的手腕上，以此來束縛他們。$B$B去幹掉幾個在達拉然廢墟裡遊蕩的元素生物，把它們的地縛護腕拿回來，大法師一定會很滿意的。', '為塔倫米爾的看守者貝瓦里爾收集4個地縛護腕。', '', '去希爾斯布萊德丘陵找塔倫米爾的看守者貝瓦里爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 558 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (558, 'zhTW', '珍娜的簽名', '他們說塞拉摩的珍娜?普勞德摩爾是聯盟最偉大的英雄之一。當我長大之後，我也要成為聯盟的英雄!$B$B你認識珍娜嗎，$N?你可不可以幫我個忙，幫我弄到她的簽名?我不知道怎麼向她開口，也許她很忙而無暇顧及我……但是你可以!你是和她一樣偉大的冒險者!我打賭她會給你簽名的!$B$B求求你了!', '到塞拉摩去，為你看護的孩子拿到一份珍娜?普勞德摩爾的親筆簽名。', '', '去找人類孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (559, 'zhTW', '法爾林的證據', '你相信嗎， $N ?雷德帕斯對咱們殺了那麼多魚人還是不滿意─哦，別謙虛了，你在這方面還挺有本事。現在他又要我證明我真的殺過魚人，他要我把那些冰涼的、粘糊糊的魚人的頭給砍下來讓他過目，這樣我才能得到他的肯定。', '南海鎮的法爾林·奧里涅爾中尉要你從西部海岸的魚人身上收集10顆魚人的頭顱。', '', '去希爾斯布萊德丘陵找南海鎮的法爾林·奧裡涅爾中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (560, 'zhTW', '法爾林的證據', '你知道，$n，我真的不想碰這些魚人的腦袋……既然是你解決了它們，那你能不能再幫我把它們送去給雷德帕斯?', '把一袋魚人的頭顱交給南海鎮的治安官雷德帕斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (561, 'zhTW', '法爾林的證據', '請告訴法爾林·奧里涅爾中尉，我覺得他應該把注意力重新集中在滋生於東部海灘的納迦身上。告訴他，一旦有什麼進展，就親自來向我彙報。', '和南海鎮的法爾林·奧里涅爾中尉談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (562, 'zhTW', '升官之道', '我以前在暴風城的導師發來消息告訴我聯盟的高級將領已經開始關注納迦帶來的威脅了。根據他打聽來的消息，任何人在這方面有所表現的話，都很有可能得到提拔，或者至少是調動工作崗位。$B$B不過有一個小問題……我對付不了納迦， $N 。哦，當然，我能阻止酒吧裡的醉漢互相爭吵，也能拖走好鬥的乞丐，不過納迦對我來說就太難對付了。你一定得幫我這個忙， $N 。', '南海鎮的法爾林·奧里涅爾中尉要你去殺掉10個刺脊灘行者和10個刺脊海妖。', '', '去希爾斯布萊德丘陵找南海鎮的法爾林·奧裡涅爾中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (563, 'zhTW', '人事調動', '我的這份報告看來應該是沒什麼問題了。新的守衛長官山繆森少校曾是我的導師。有了這份報告，他就完全有理由把我調回暴風城了。我需要你幫忙把報告交給他，不過……你可別讓雷德帕斯拿到它。', '把法爾林的報告交給暴風要塞裡的山繆森少校。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (564, 'zhTW', '損失慘重', '沒有什麼事比失去這些駿馬更讓我煩心了。相信我，就是那些討厭的不死生物、可惡的辛迪加惡匪和其他害人的東西在這一帶到處遊逛，殺了我們不少的馬匹。$B$B不過我可以對著我爺爺的墓碑發誓，對這些馬匹威脅最大的還是奧特蘭克上的山地獅。它們總是從山上跑下來給我搗亂!$B$B你覺得自己是個英雄?那就去做點什麼來證明吧!', '南海鎮的達倫·瑪爾維要你殺掉8隻山地獅和10隻巨型山地獅。', '', '去希爾斯布萊德丘陵找南海鎮的達倫·瑪爾維。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (565, 'zhTW', '巴圖羅的雪人毛皮披風', '我，偉大的巴圖羅，將為你做一件聞名世界、全聯盟皆知的雪人毛皮披風!$B$B不信你就到處跑跑看，能不能再找件更棒的。每個人都會說:「巴圖羅，沒有比這更好的披風了!」當然，當然沒有。$B$B巴圖羅需要一個毛布卷，一件由技藝高超的製皮師縫製的山地披風，一股細線，當然還要有雪人的毛皮!把這些東西帶給我，我就讓你看看我的本事!', '給南海鎮的巴圖羅·吉塞提找一個毛布卷、一件山地披風、一股細線和10塊雪人的毛皮。', '', '去希爾斯布萊德丘陵的南海鎮找巴圖羅·吉塞提。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (566, 'zhTW', '通緝：瓦杜斯男爵', '高級執行官達薩利亞發出命令，通緝名叫瓦杜斯男爵的人類，此人對被遺忘者犯下了重罪。瓦杜斯是辛迪加組織的高階人物。$B$B最後一次有人見到他是在塔倫米爾北部的奧特蘭克山高地上。$B$B殺死他，然後帶著他的頭去見高級執行官達薩利亞換取報酬。', '殺了瓦杜斯男爵，把他的頭帶給塔倫米爾的高級執行官達薩利亞。', '', '去希爾斯布萊德丘陵找塔倫米爾的高級執行官達薩利亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (567, 'zhTW', '危險！', '危險！$B$B以下這個希爾斯布萊德人是危險人物，已被高級執行官達薩利亞懸賞捉拿：$B$B通緝犯書記員赫拉斯·懷特斯蒂德殺害了亡靈衛兵托馬。$B$B通緝犯平民維爾克斯殺害了藥劑師埃利。$B$B通緝犯礦工哈克特殺害了亡靈衛兵弗雷。$B$B通緝犯農夫卡拉巴伏擊運往幽暗城的物資。$B$B這些敵人都躲藏起來了，很難找到，殺掉他們有重賞。', '塔倫米爾的高級執行官達薩利亞懸賞通緝書記員赫拉斯·懷特斯蒂德、平民維爾克斯、礦工哈克特和農夫卡拉巴。', '', '去希爾斯布萊德丘陵找塔倫米爾的高級執行官達薩利亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 568 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (568, 'zhTW', '格羅姆高保衛戰', '向你致敬，$c！$B$B你來得真是時候。身為酋長委派到這個叢林基地中的指揮官，我肩負著保衛所有部落成員安全的光榮使命，我們在此的任務是保證對斯通納德的供應線不被此地的怪物所侵擾。$B$B因此，我將委任你來負責減輕格羅姆高附近的迅猛龍給我們帶來的威脅。當你取得了顯著的進展後，就向我覆命吧。', '格羅姆高營地的指揮官阿格羅戈什要求你殺死15只鞭尾迅猛龍。', '', '去荊棘谷找格羅姆高營地的指揮官阿格羅戈什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 569 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (569, 'zhTW', '格羅姆高保衛戰', '在第一次進入這片叢林中的時候，我們根本就沒想和當地的土著部落發生任何衝突。我們任務中最重要的部分就是保持對斯通納德的供應線的暢通。但目前的情況很複雜，附近的一群食人魔佔領了格羅姆高東南方的米扎廢墟。他們從來就沒把我們的警告放在眼裡，頻繁地伏擊我們的補給車隊。$B$B我授命你去解決掉這群冥頑不化的食人魔。$B$B到米扎遺蹟去吧，就算不能把他們驅逐出這片地區，至少也得讓他們好好嚐嚐苦頭。', '格羅姆高營地的指揮官阿格羅戈什要求你殺死10個食人魔蠻兵和5個食人魔巫醫。', '', '去荊棘谷找格羅姆高營地的指揮官阿格羅戈什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 570 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (570, 'zhTW', '摩克薩爾丁的魔法', '部落必須意識到叢林中蘊含著的無盡的魔法力量，並儘快學會利用它來為自己服務。到目前為止，我的儀式都是很成功的，現在我已經能夠施放很強大的魔法了。勇敢的$c，我決定為你製作一件特殊的魔法物品。$B$B給我找一些深喉獵豹的爪子和一顆雌虎的牙齒來，不過你要注意，並不是任何牙都可以用的。你必須找到品質最純正的牙齒才行。$B$B這種野獸一般都潛藏在叢林中，但你在附近也能找到，只要從米扎廢墟那邊渡過河流，然後向東南方走就行了。', '格羅姆高營地的先知摩克薩爾丁要求你給他帶回8只深喉獵豹的爪子和一顆雌虎的牙齒。', '', '去荊棘谷找格羅姆高營地的先知摩克薩爾丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 571 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (571, 'zhTW', '摩克薩爾丁的魔法', '現在我要你去尋找一件非常難以得到的物品。$B$B為了將這些羽毛、爪子和牙齒中的魔法力量連線在一起，我必須要建立一個魔法陣，而這魔法陣只有用成年猩猩的肌腱才能做成。$B$B具體說來，老邁的薄霧谷猩猩身上的肌腱就很合適。他們一般棲息在藏寶海灣的東面。$B$B你必須找到足夠新鮮健康的肌腱才行，這就是說，你有可能要殺死很多大猩猩才能找出一條合我心意的肌腱來。', '給格羅姆高營地的先知摩克薩爾丁帶回1根成年大猩猩的肌腱。', '', '去荊棘谷找格羅姆高營地的先知摩克薩爾丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 572 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (572, 'zhTW', '摩克薩爾丁的魔法', '你剛才從那些野獸身上收集到的這些材料只是製造那件強力魔法物品的第一步。在我使用薩滿儀式將這些物品合成之後，你就會得到一件極為有用的工具，它可以幫你更好地為酋長和部落效力。$B$B但你先得幫我收集一些叢林捕獵者的羽毛來，據說迅猛龍將這些羽毛當作它們的臂章。在格羅姆高的南邊，離大競技場不遠的地方就有一個迅猛龍部族，你可以到那裡去看看。', '給格羅姆高營地的先知摩克薩爾丁帶回10根叢林捕獵者的羽毛。', '', '去荊棘谷找格羅姆高營地的先知摩克薩爾丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 573 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (573, 'zhTW', '摩克薩爾丁的魔法', '現在我們只差最後一種材料就可以完成這個魔法了。$B$B向南走到一處面對西側海岸的高崖之上，你會發現一處聖泉。這處聖泉是許多學者爭論的焦點，艾澤拉斯上的所有種族都認為這泉中的水乃是神為他們的子民所創造的。$B$B給我帶一瓶聖泉的水回來，這是我給你的最後一個任務啦。不過，你得小心點。有一群納迦衛兵正守在聖泉的附近，你得先對付他們才能取到泉水。', '格羅姆高營地的先知摩克薩爾丁要你去取回一瓶聖泉之水，同時還要求你殺死10名納迦探險者。', '', '去荊棘谷找格羅姆高營地的先知摩克薩爾丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 574 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (574, 'zhTW', '特種部隊', '如今我們已經在很大程度上削弱了他的正規部隊，但這就意味著你得直接去面對他手下的精銳部隊。如果那些傢伙沒有被派出去襲擊我們落單的士兵的話，他們就應該駐紮在庫爾森營地後山上一處名為「儲藏室」的洞穴裡。$B$B我私下裡認識許多庫爾森的手下，他們都是身經百戰的老兵，對庫爾森忠心耿耿，而且最要命的是，他們對敵人毫不手軟。這對你來說恐怕不是個簡單的任務， $N 。多加小心。$B$B你戰勝了他們以後，就去向我的長官多倫中尉覆命吧。', '殺掉10名庫爾森特種兵和6名庫爾森精神醫師。', '', '去荊棘谷找反抗軍營地的多倫中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 575 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (575, 'zhTW', '供與求', '「前無古人，後無來者，南海一帶最好的也是世界最好的皮匠。」他們就是這麼叫我的。我!崔斯里克!最好的皮……呃，好吧。$B$B我的皮貨以品質優質而遠近聞名，都是鑒賞家們的首選之物!$B$B我最近收到了來自技工協會雷德沃克斯主管的訂單，他需要十二雙刨花皮靴。啊，就是那種由我製作的、非常搶手的靴子。$B$B不過要想做那種靴子的話，我需要一些鱷魚皮才行。在荊棘谷北邊的河邊有很多鱷魚，你看能不能……', '收集2張淡水鱷的皮，把它們交給藏寶海灣的崔斯里克。', '', '去荊棘谷找藏寶海灣的崔斯里克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 576 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (576, 'zhTW', '海盜的眼睛', '站住!誰在那邊?$B$B啊，如果沒有那隻特製的魔法眼，我就是個廢人了。當初在一次戰鬥中，我失去了我的眼睛!但幸運的是，我們的船停靠在米奈希爾港時，一位旅行巫師送給了我一隻特製的玻璃眼，這樣我才又能看見東西了。$B$B不過昨天晚上我參加了襲擊血帆海盜的行動，在跳出船的時候玻璃眼睛不小心給弄丟了。一定是那幫血帆海盜拿走了我的眼睛!看來他們這群混蛋已經找到了到藏寶海灣來的路。$B$B你能不能幫幫我這個老海盜，把我的眼睛給找回來?', '藏寶海灣的獨眼迪茲要求你從血帆海盜那裡找回他的眼睛。', '', '去荊棘谷找藏寶海灣的獨眼迪茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 577 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (577, 'zhTW', '收集鱷魚皮', '嗯，這些靴子已經基本定型，接下來就要開始打磨表面了。但你帶來的皮似乎少了點，做不出足夠的鞋墊來。$B$B「那現在我們得幹什麼呢，崔斯里克?」你肯定會馬上問這種問題，哈哈，你跟崔斯里克說話可真不幸啊，因為我馬上就要給你派活幹啦!$B$B沒人會去觀察鞋墊的，所以我們只要找點又厚又便宜的鱷魚皮就行了。納菲瑞提湖旁邊的那種鉗嘴鱷魚就不錯。', '給藏寶海灣的崔斯里克帶回5張鉗嘴鱷魚的皮。', '', '去荊棘谷找藏寶海灣的崔斯里克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 578 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (578, 'zhTW', '海潮之石', '如果個島上確實有水元素和哥布林法師的鬼魂的話，也就是意味著在那裡可以采到海潮之石!$B$B我希望你能找到這座鬧鬼的島嶼，去看看上面到底是怎麼回事。哦，如果你想知道更多的有關海潮之石的資訊的話，可以帶著這張憑證去暴風城圖書館，他們會幫你找到我最初讀過的那本傳說的手抄本。$B$B真的是加茲班首先發現那種石頭的嗎……?', '為藏寶海灣的大財主里維加茲找到鬧鬼的島嶼。', '找到鬧鬼的島嶼', '去荊棘谷找藏寶海灣的大財主裡維加茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 579 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (579, 'zhTW', '暴風城圖書館', '', '', '', '去找艾爾文森林的丹亞·托瓦爾德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 580 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (580, 'zhTW', '威士忌·狡黠所遺失的烈酒', '我們那天喝醉了，結果從很遠的辛特蘭那邊掉下了船，活活地漂到望海崖這裡來，差點餵了魚。$B$B而且我斯利姆從小就不怕水!我們船長從一艘去暴風城的私掠船上搶來了一箱紫葡萄酒。$B$B我們在辛特蘭被風暴襲擊的時候，我東倒西歪地撞碎了那個木箱，結果那裡面的酒在大風大浪裡全都掉進海裡了。我要是不把它們給找回來的話，船長見了我非拿我餵貓不可!幫幫我吧!', '藏寶海灣的威士忌·狡黠想要你幫他找回弄丟的紫葡萄酒。', '', '去荊棘谷找藏寶海灣的威士忌斯利姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (581, 'zhTW', '耶尼庫的下落', '厄運！厄運降臨在我們酋長的小兒子耶尼庫身上……按照部族裡的習俗，他被過繼給了祖爾格拉布的食人妖，但我們暗矛部族隨後便決定跟隨獸人酋長索爾離開家鄉，可憐的耶尼庫就此與我們失去了聯絡。我是從奧格瑪回到荊棘谷來的，我回來尋找我們酋長的孩子。$B$B我相信是血頂部族抓住了他。$B$B如果你願意幫助我的話，就去幹掉血頂部族的那幫傢伙吧，他們就在北邊。把他們的獠牙給我帶來。', '給格羅姆高營地的尼姆布亞帶回9根血頂食人妖的獠牙。', '', '去荊棘谷找格羅姆高營地的尼姆布亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 582 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (582, 'zhTW', '獵頭行動', '我們必須弄清楚耶尼庫是否還活著。$B$B殺掉一些血頂部落的獵頭者，並把他們身上掛著的皺縮的頭顱給我取回來。你必須要收集儘可能多的首級回來，這樣我才能檢查一下耶尼庫的頭在不在其中。$B$B如果耶尼庫真的被血頂氏族給殺了，他們的酋長，那個名叫甘祖拉恩的傢伙，就一定會遭受長達600年的惡毒詛咒！$B$B去吧，$N。沿海岸北上，在祖丹亞廢墟和祖昆達廢墟那裡就有很多血頂獵頭者在活動。', '給格羅姆高營地的尼姆布亞帶去20個皺縮的頭顱。', '', '去荊棘谷找格羅姆高營地的尼姆布亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 583 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (583, 'zhTW', '歡迎來到叢林', '歡迎來到荊棘谷!$B$B也許你不知道，但那邊的那位矮人就是聯盟一位偉大的戰爭英雄，出名的野獸獵人赫米特‧奈辛瓦里的兒子。如同他父親一樣，他並不歡迎陌生人來他的營地，不過你看起來像是見過大世面的 $C 。$B$B作為一位久經沙場的老將，奈辛瓦里大人總是很關心你們這樣的小輩。$B$B去和他談一談吧。他和父親十分酷似，所以或許他能教你些狩獵的技巧。', '與小赫米特‧奈辛瓦里談話。', '', '去荊棘谷找奈辛瓦里遠征隊營地的赫米特·奈辛瓦里二世。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 584 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (584, 'zhTW', '血頂之顱', '感謝蛇神，耶尼庫的頭並不在這些首級當中。但我們仍不清楚他的狀況……$B$B我們必須知道真相，不過，恐怕只有血頂氏族的酋長和巫醫才知道這些事，而他們又是我們暗矛部族的敵人，所以他們是絕對不會老老實實地告訴我們真相的，恐怕他們只有在死了以後才會願意和我們談談！$B$B把甘祖拉恩和奈茲里奧克的頭給我帶回來，然後放進這個鍋裡去。$B$B他們就躲在祖昆達廢墟裡的深處。只要有他們的頭顱……我們就能和他們好好談談了。', '將甘祖拉恩的頭顱和奈茲里奧克的頭顱帶回格羅姆高營地，放入冒泡的大鍋中。', '', '去荊棘谷找格羅姆高營地的冒泡的大鍋。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 585 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (585, 'zhTW', '奈茲里奧克', '<奈茲里奧克的頭說話了>$B$B沒錯，我知道那個暗矛部落的孩子被帶到什麼地方去了。雖然你殺害了我，而且把我的靈魂也束縛了起來，但要是你們不給我點好處的話，我還是什麼都不會說的！$B$B血頂部族正在與劈顱部族交戰，要想讓我幫忙，就從劈顱部族那裡偷來3顆顱骨來，放在這裡陪著我，這樣我在扭曲虛空之中也就有三個奴隸啦。這三個頭骨必須分別從他們在巴里亞曼廢墟、贊塔加廢墟和祖瑪維廢墟的顱骨堆中拿來。', '帶回巴里亞曼戰利品、贊塔加戰利品和祖瑪維戰利品各一個，把它們放入格羅姆高營地裡中的冒泡的大鍋裡。', '', '去荊棘谷找格羅姆高營地的冒泡的大鍋。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 586 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (586, 'zhTW', '甘祖拉恩', '<甘祖拉恩的頭顱開始說話了>$B$B我要詛咒你！詛咒你的八輩子祖宗！$B$B只有鮮血和復仇才能平息我的憤怒，如果這是你的意願的話，那麼……這麼辦吧：$B$B到東邊的劈顱部族的老窩去，盡情地屠殺吧，要是你夠強的話……就幹掉他們的酋長，殘忍的安納希克。嘿嘿，把他的盔甲碎片拿來給我看，不過我很懷疑你的能力！$B$B他肯定會把你的四肢都撕下來，然後讓你爛在地裡喂烏鴉，哈哈哈！', '殺死8名劈顱獵人、6名劈顱獵頭者和4名劈顱狂戰士。$B$B將安納希克的盔甲碎片放入格羅姆高營地中的冒泡的大鍋裡。', '', '去荊棘谷找格羅姆高營地的冒泡的大鍋。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 587 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (587, 'zhTW', '鼻煙', '啊，海上的生活。我不想說這種生活有多美好，但這就是我的生活。$B$B當我每次入港的時候，我都會找個地方好好喝上一杯，再找點高品質的鼻煙抽抽。壞習慣吧，但海賊們怎麼能沒有壞習慣呢，對吧?$B$B所以你可以想像一下，當我發現鎮上的草藥師賣完了他的全部鼻煙並且已經離開了這座小鎮的時候，我會有多沮喪有多傷心了!據說給他運貨的那條船讓那些該死的血帆劫掠者給搶劫了。$B$B我相信像你這樣勇敢的 $C ，一定能說服他們交還船上的貨物，對吧?', '藏寶海灣的迪格要求你帶給他15份鼻煙。', '', '去荊棘谷找藏寶海灣的迪格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 588 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (588, 'zhTW', '耶尼庫的命運', '<奈茲里奧克開口說話了>$B$B現在，我會告訴你關於你所尋找的那個耶尼庫的事情……$B$B年輕的耶尼庫和他的氏族失散了。$B$B他被巫醫贊吉爾給帶走了。現在贊吉爾控制了他的身心，只有一種極端強大的法術才能使他恢復自由之身。$B$B而你肯定沒有這種法術，$c。$B$B或許你暗矛部落的朋友們有辦法拯救耶尼庫，不過我對此也相當懷疑。', '與肯維雷談一談。', '', '去荊棘谷找格羅姆高營地的肯維雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 589 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (589, 'zhTW', '歌唱水晶', '傳說荊棘谷的中心地帶深藏著一塊寶石，這塊寶石的名字叫心靈之眼，其中蘊涵著巨大的力量。如果你得到了這塊寶石，也許我們就能用它將失落於黑暗之中的耶尼庫拯救出來。$B$B我會與叢林之靈們商談，向他們詢問心靈之眼的位置。與此同時，你要去一趟東南方的水晶礦洞，從那裡的鐵顎蜥蜴身上收集一些藍色波光碎片。這些水晶非常稀有，但我們需要利用其中的魔法能量來控制心靈之眼。', '給格羅姆高營地的肯維雷帶回3塊藍色波光碎片。', '', '去荊棘谷找格羅姆高營地的肯維雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 590 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (590, 'zhTW', '潛行者的交易', '什麼？$B$B什麼？！$B$B你要錢？我可不欠你什麼錢。$B$B信？什麼信？哦，你是不是想打架？好吧，朋友……放馬過來啊！', '打敗喪鐘鎮的卡爾文·蒙泰古。', '擊敗卡爾文·蒙泰古', '去找喪鐘鎮的卡爾文·蒙泰古。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 591 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (591, 'zhTW', '心靈之眼', '心靈之眼目前落在了一個食人魔法師的手裡，他就住在東邊的莫什奧格巨魔山的深處，他的名字是麥佐斯。我自暗矛部落還在荊棘谷定居的時候就知道他了，他是一個邪惡的傢伙，而且法力非常強大。$B$B如果確實是他拿著心靈之眼的話，他的魔法就會具有極大的威力。$B$B你必須從這個麥佐斯的手中搶到心靈之眼。這確實是件危險的工作，但這也是我們拯救耶尼庫的唯一希望了。', '將心靈之眼交給格羅姆高營地裡的肯維雷。', '', '去荊棘谷找格羅姆高營地的肯維雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 592 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (592, 'zhTW', '拯救耶尼庫', '我已經將心靈之眼重塑為一顆靈魂寶石。你必須先用它震懾住耶尼庫，成功之後，就立刻把寶石放在他的額頭上，這樣才能抽取出他的靈魂。$B$B接下來把寶石交給尼姆布亞就可以了。$B$B耶尼庫和流亡者贊吉爾一起住在阿博拉茲廢墟，只要沿著水晶海岸走到荊棘谷的海角那邊就能找到了。', '將裝滿的靈魂寶石交給尼姆布亞。', '', '去荊棘谷找格羅姆高營地的尼姆布亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 593 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (593, 'zhTW', '靈魂寶石', '', '', '', '去找荊棘谷的耶尼庫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (594, 'zhTW', '瓶中信', '這張便箋上有極漂亮的字跡：$B$B致任何能幫助我的人$B$B拜託，我迫切地需要幫助。一隻巨大的藍鬃猩猩將我囚禁在了南海的一座島嶼上。$B$B這裡夜晚的星象我以前從未見過，島上全是茂密的叢林，但在天氣晴朗的時候，我能看見西北方的蠻荒的海岸，還有幾條大船在向西南航行。$B$B求求你，請幫幫我吧。', '找到瓶中信的作者。', '', '去荊棘谷某地方找瓶中信的作者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 595 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (595, 'zhTW', '血帆海盜', '你看起來特別像要找份活幹似的，夥計。雖然我不清楚為什麼一個喜歡在平地上過日子的$r$c會願意幫助我們這些黑水強盜，但我不會阻攔你的。我們的船就停泊在藏寶海灣，而我們的死對頭─那些該死的骯髒的血帆劫掠者─正在整個荊棘谷南部胡作非為。現在我們這裡的人不是抱著酒瓶子就是抱著姑娘!我需要一個斥候來幫我做事。去偵察一下野人海岸上有些什麼，沒錯，就是藏寶海灣北邊的那片沙灘。', '大副克拉茲要求你去偵察一下藏寶海灣北邊的海灘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 596 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (596, 'zhTW', '染血的白骨項鍊', '我是被派來格羅姆高幫助尼姆布亞完成他的任務的，但……我發現這裡還有些更有意義的事要做。$B$B血頂部族是我們的敵人。將敵人的戰利品搶過來將極大地鼓舞我們計程車氣，同時也能給對方以沉重的打擊。也許你可以幫我們部族獵殺血頂部族的成員……$B$B他們就居住在北邊，幹掉那些血頂食人妖，把染上它們鮮血的白骨項鍊給我拿回來。你拿回來越多項鍊，我們就會越尊敬你。', '給格羅姆高營地的肯維雷帶回25串染血的白骨項鍊。', '', '去荊棘谷找格羅姆高營地的肯維雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (597, 'zhTW', '血帆海盜', '這是一張藏寶海灣的地圖，上面用紅筆標叉的地方就是你現在站的位置。$B$B圖上潦草的寫著幾行字:$B$B「你們的任務就是悄悄地在此地紮營，等待南方指揮部發出信號後再開始攻擊。如果任何人試圖阻礙你們，格殺勿論。」', '將你的發現報告給藏寶海灣的大副克拉茲。', '', '去荊棘谷找藏寶海灣的大副克拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 598 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (598, 'zhTW', '裂骨項鍊', '你已經收集了足夠多的血頂氏族的戰利品，現在我要交給你一項新的任務。劈顱部族居住在東南方，以前我們一直和他們互無往來。雖然暗矛部落已經不住在荊棘谷了，但現在我們卻捲入了與他們的衝突之中。$B$B所以，我要你去獵殺他們，把他們的裂骨項鍊帶回來給我。如果你在我們這場戰爭中幫助了我們暗矛部族，就一定會贏得我們的友誼。', '給格羅姆高營地的肯維雷帶回25串裂骨項鍊。', '', '去荊棘谷找格羅姆高營地的肯維雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 599 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (599, 'zhTW', '血帆海盜', '太令我吃驚了!那麼血帆海盜正計畫著進攻藏寶海灣嗎?這群發了神經病的惡棍當真是不要命了麼，藏寶海灣永遠都是我們黑水強盜的地盤!$B$B這事比我想得還要嚴重。馬上將你所知道的一切報告給艦隊指揮官卡拉·海角!這群該死的海狗可能已經開始在鎮子外面集結了……', '把血帆海盜的計畫報告給艦隊指揮官卡拉·海角。', '', '去荊棘谷找藏寶海灣的艦隊指揮官卡拉·海角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 600 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (600, 'zhTW', '風險投資公司的採礦行為', '最近，風險投資公司在荊棘谷一帶展開了一系列的行動，這讓我們這些誠實努力的哥布林們，你看，比如我，根本沒辦法在這裡討生活了!拜託，你一定要幫幫我!$B$B風險投資公司打算在北邊的水晶礦坑那裡採礦，可是由於那邊的石化蜥蜴到處肆虐，他們根本沒辦法進入礦坑，只能在周圍的山上開採歌唱水晶。$B$B去把他們的水晶都搶來，讓他們知道他們不該在這片叢林裡如此囂張。$B$B還有……嗯嗯……把那些水晶給我帶回來當證據!', '給藏寶海灣的克蘭克·菲茲巴布帶回10塊藍色歌唱水晶。', '', '去荊棘谷找藏寶海灣的克蘭克·菲茲巴布。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (601, 'zhTW', '水元素', '這些水元素無疑是傳說中發現了海潮之石的哥布林巫師加茲班召喚的。也許你知道，海潮之石會詛咒任何挪動它的人，就是說，會讓那個倒楣的傢伙從這個世界上徹底消失。$B$B應該有什麼辦法可以破除這個該死的詛咒，我們可以請一位達拉然的法師來幫我們分析一下水元素胳膊上戴著的護腕裡的魔法。你能不能回到那島上幫我收集一些進行魔力分析所需的樣本?', '為藏寶海灣的大財主里維加茲收集6個水元素護腕。', '', '去荊棘谷找藏寶海灣的大財主裡維加茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (602, 'zhTW', '魔法分析', '我聽說達拉然的法師們已經成功地重建了他們的魔法城市，並且把它遷到了北裂境，原先所在處只留下了一個巨大的坑洞。但有些法師則留在這裡，繼續研究著這些護腕。根據我對那些法師的瞭解，他們是絕對不會拒絕任何與魔法有關的謎題的。$B$B將這包水元素的護腕拿給他們，讓他們看看能不能找到解除石頭上的詛咒的方法。建議你去那邊找大法師安斯雷姆·織符者。他曾經幫過我的忙，我想他的淵博知識可以對你有所幫助。', '將水元素護腕交給達拉然陷坑的大法師安斯雷姆·織符者。', '', '去奧特蘭克山脈找達拉然巨坑的大法師安斯雷姆·魯因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (603, 'zhTW', '安斯雷姆的鑰匙', '嗯，擁有那塊石頭的法師一定通過在某處集中力量來加強他的魔法效力……比如在某個祭壇上。按理說你應該可以用更強大的力量去瓦解它。$B$B就目前的情況而言，我知道有件物品可以派上用場:食人妖一族失落的另一件神器，一把遠古匕首。但是，還有一個……只有一個……小問題。$B$B你知道，我過去在荊棘谷進行研究的時候得到了那把匕首，但我把匕首給了我那任性的女兒，她叫凱特琳。她現在已經去了藏寶海灣，也許是真的想當個海賊吧。', '與藏寶海灣的凱特琳談話。', '', '去荊棘谷找藏寶海灣的凱特琳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (604, 'zhTW', '血帆海盜', '克拉茲高度讚揚了你為黑水強盜做出的重要貢獻。我信任你，因此我要賦予你一個對於艦隊來說至關重要的任務。$B$B我們要求你滲透進血帆海盜建立在蠻荒海岸的南方指揮部。偷襲他們的營地，將他們的海圖與計畫書都給我帶回來，我們必須要搞清楚這群渣滓到底想幹點什麼。', '藏寶海岸的艦隊指揮官卡拉·海角要求你殺死10名血帆劍客並將血帆海圖和血帆計畫書帶回去。', '', '去荊棘谷找藏寶海灣的艦隊指揮官卡拉·海角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (605, 'zhTW', '藍色歌唱水晶裂片', '歌唱水晶是荊棘谷的一種特產，它對某些人來說有著非常重要的價值。我本想運一些歌唱水晶到別的地方去賣，可那該死的風險投資公司想要獨佔它，所以，像我這樣誠實的商人看來就無法親自去收集水晶了!$B$B我決定雇傭你。$B$B荊棘谷中的蜥蜴都有吞食這種水晶的習性，這可以使它們的皮膚變得更硬。因此，我們可以從它們身上收穫到一些高品質的水晶。$B$B隨便哪隻蜥蜴身上都會有水晶，但最容易對付的是在北邊的海岸附近活動的那些蜥蜴。', '為克蘭克·菲茲巴布收集10塊歌唱水晶裂片。', '', '去荊棘谷找藏寶海灣的克蘭克·菲茲巴布。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (606, 'zhTW', '嚇唬病鬼', '你知道這裡最讓我受不了的是什麼嗎?這兒的人都有死也不還賭債的毛病!現在已經有一大群傢伙欠著我的錢了。你能幫我催一下債嗎?$B$B第一個要催的就是住在碼頭那邊的『病鬼』菲力浦。他上個禮拜欠得實在是太多了，我一定要把這筆錢給要回來!但是要想拿到它，我們就得好好嚇唬嚇唬他。$B$B到鎮子外邊去獵殺一些老邁的迷霧谷猩猩，然後從它們身上搞點內臟雜碎什麼的，把這些玩意丟給那病鬼。最好別讓他想到那是動物內臟，讓他想點更糟的。', '給藏寶海灣的『病鬼』菲力浦帶回5塊迷霧谷猩猩的內臟。', '', '去荊棘谷找藏寶海灣的“病鬼”菲利普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (607, 'zhTW', '向麥克基雷回報', '給，把這個布袋給海狼。告訴他，我是想還他錢的!我發誓!!$B$B我只是喝多了點，迷路了而已，還有……總之是一團糟了。他會理解我的─你可別亂說啊!', '將病鬼的還款交給『海狼』麥克基雷。', '', '去荊棘谷的藏寶海灣找“海狼”馬克基雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (608, 'zhTW', '血帆海盜', '菲爾拉倫一點膽量都沒有!他連划著小船穿越水晶湖都做不到，更別說獨自率領整支艦隊來和我們對抗了。$B$B血帆海盜一定會為他們的粗心大意而付出代價的。現在我們已經掌握了他們的攻擊計畫，完全可以在他們什麼還都不知道的時候搶先下手。$B$B我們並不需要派出全部的艦隊，只要一支勇敢的冒險隊伍就能輕易完成這任務。 $N ，帶著你最優秀的同伴前往菲爾拉倫的登陸點，殺掉血帆的指揮官。這樣他們的艦隊不用多久就可以去餵魚了……', '藏寶海灣的艦隊指揮官卡拉·海角要求你殺死血帆海盜的斯蒂沃特船長，尼哈魯船長和艦隊指揮官菲爾拉倫。', '', '去荊棘谷找藏寶海灣的艦隊指揮官卡拉·海角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (609, 'zhTW', '討債行動', '我這兒的欠條已經少了許多啦，但還是有許多沒信譽的傢伙欠著我的錢。$B$B接下來，我們得對付瑪雷·『木腳』·維爾金斯、『烏鴉』喬喬，還有『十指』蘇克。$B$B這幫傢伙的債欠了好久，我看他們是不想還了!後來，我聽說他們被什麼人給騙到叢林裡去了。我當然不關心他們到底會怎麼樣─我要的是我的錢!$B$B他們應該就在東北方的阿博拉茲廢墟和朱布瓦爾廢墟裡。找到他們，把我的錢拿回來。', '給藏寶海灣的『海狼』麥克基雷帶回瑪雷的木腳、喬喬的金色望遠鏡和蘇克的巨型戒指。', '', '去荊棘谷找藏寶海灣的“海狼”馬克基雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 610 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (610, 'zhTW', '『漂亮男孩』鄧肯', '我老爸派你來的?我還以為那怪老頭早就已經放棄我了呢。$B$B我之所以離家出走確實不是他的錯，他只是不應該為我安排好一條乏味的人生道路，並希望我欣然接受它。我怎麼能忍受整天讀著那些發黴的書本，整天和那幫灰頭髮加駝背的乏味老頭法師們在一起!$B$B如果你需要我的匕首，你可能得從一個叫『漂亮男孩』鄧肯的血帆海盜那裡奪回來。我想你只要教訓教訓他，他就會屈服的。', '從『漂亮男孩』鄧肯那裡奪回凱特琳的匕首。', '', '去荊棘谷找藏寶海灣的利刃凱特琳。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (611, 'zhTW', '海潮的詛咒', '這麼說你正在尋找某個祭壇嘍?好吧，雖然我不像我老爸那樣是個研究食人妖遺跡的專家，但我對你正在尋找的島嶼也略知一二，在島的附近有一座沉沒在水底的食人妖城市，我想你應該到那裡去碰碰運氣。$B$B既然是你幫我找回了我的匕首，借去用用當然沒有任何問題……但我希望你用完以後能還給我!', '用凱特琳之刃摧毀海潮祭壇，然後殺死加茲班，將海潮之石帶給大財主里維加茲。', '', '去荊棘谷找藏寶海灣的大財主裡維加茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 612 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (612, 'zhTW', '利刃', '雖然這聽起來好像不大可能，但你能試試說服凱特琳出讓她的匕首嗎？你能理解我們收藏者的心情嗎？$B$B如果你告訴她說是我需要的話，或許她能明白我的苦心，並把這匕首賣給我的。', '將凱特琳的匕首還回去。', '', '去找荊棘谷的利刃凱特琳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 613 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (613, 'zhTW', '打開瑪雷的木腳', '該死!那見鬼的瑪雷居然在他的假腳上安了一個鎖，我還死活都打不開!他的寶貝，還有他欠我的錢，都藏在那條假腿裡!$B$B我們得想辦法找到鑰匙才行。瑪雷這傢伙過去因為喜歡和住在東北邊巨魔山上的莫什奧格巨魔賭博而出名，而且他告訴過我─我是說當他還活著的時候─他每次贏了一票大的之後都會去一趟那裡，所以，或許那邊的巨魔會有他的鑰匙。$B$B要真是如此的話，你八成得大開殺戒才能搞到鑰匙……', '把瑪雷的鑰匙帶給藏寶海灣的『海狼』麥克基雷。', '', '去荊棘谷找藏寶海灣的“海狼”馬克基雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 614 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (614, 'zhTW', '船長的箱子', '我過去在一條專跑從這裡到卡林多的棘齒城的航線上幹過。我是個很優秀也很有名望的船長。$B$B直到……$B$B那些該死的海巨人毀了我的生活!他們打沉了我的船，殺光了我的水手，把我丟在一條救生艇上，讓我漂回了藏寶海灣。還有，其中一個名叫高拉什的巨人還把我的箱子給偷走了，他說要拿這東西當鼻煙盒，簡直是神經病!$B$B我聽說有人看見高拉什最近在東邊的海岸一帶閒逛。找到他，把我的箱子給搶回來!快去，你會得到一位船長的敬意的。', '將斯莫特的箱子交給藏寶海灣的海克拜瑞·斯莫特。', '', '去荊棘谷找藏寶海灣的海克拜瑞·斯莫特船長。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 615 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (615, 'zhTW', '船長的彎刀', '我的第一條船被那些海巨人們搞沉了之後，我只好買了第二艘，而且給它起名為“斯莫特的復仇”。我為它配備了新的裝備和船員，並出發去尋找那些該死的巨人。我找到了他們，但……他們又一次擊敗了我們。他們把“斯莫特的復仇”號給打成了碎片，船員也幾乎被他們殺光了，但那幫混蛋卻把我丟在了一條救生艇上，讓我一個人漂了回來。$B$B這次，那些海巨人中的另外一個偷了我的彎刀。$B$B到奈古拉什那裡去把我的佩刀給搶回來！$B$B去和斯普羅格談談吧。他本來是“斯莫特的復仇”號上的廚子，沉船的時候他也倖存了下來，我想他能幫你們找到那些巨人。', '與斯普羅格談一談。', '', '去荊棘谷的藏寶海灣找斯普羅格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 616 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (616, 'zhTW', '幽靈島', '大財主里維加茲讓我留意最近在藏寶海灣和荊棘谷附近流傳的古怪傳聞。雖然我平時是絕不會關心什麼鬼故事的，但這兩天在酒館裡聽一些水手們說在海岸附近有一座鬧鬼的小島。據他們說，那上面全是水元素和一隻整日說著瘋話的哥布林的鬼魂。$B$B如果你正好要去見里維加茲閣下的話，能替我將這件事轉告給他嗎?', '與藏寶海灣的大財主里維加茲談話。', '', '去荊棘谷找藏寶海灣的大財主裡維加茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 617 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (617, 'zhTW', '一捆海蛇草', '聽說你正在找活做， $N ?要是你夠膽的話，我這兒倒是有件不錯的活正要找人呢。$B$B你聽說過最近有許多人都在找一處泉水麼?是的，有一群納迦也在找。我有個叫格羅伊的朋友吧，他最近出了一大筆錢，想買一些納迦稱之為海蛇草的東西。我也不清楚那到底是什麼，只知道是一種很值錢的海草。他也沒說要那玩意幹什麼，不過他確實出了一個好價錢，大概需要一捆吧。$B$B你幫我搞來10根這種什麼草，那我們就可以跟他做筆交易啦。不久前有人看見這裡北邊的海灘上出現了不少納迦。', '給藏寶海灣的私掠者布勞茲帶回10捆海蛇草。', '', '去荊棘谷找藏寶海灣的海盜布勞茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 618 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (618, 'zhTW', '挑戰奈古拉什', '奈古拉什總是一副隨時準備把一切都吞下去充飢的樣子。$B$B那些巨人襲擊我們的船的時候，奈古拉什直接衝向了我的廚房，不過他可不像其他巨人那樣喜歡吃人。奈古拉什要的是酒……還有我秘製的燒烤禿鷹翅膀。嘿，這可都是我的拿手菜，我當年可是跑到荒蕪之地才弄到這食譜的！$B$B如果你想把奈古拉什給引出來，只要用點酒再加上一碟烤翅就行啦。把這些東西放進我們當初丟在東南邊海岸上的救生艇裡，然後你就等著奈古拉什聞到食物的味兒乖乖上鉤吧！', '將10塊燒烤禿鷹翅膀和5瓶密林葡萄酒帶到斯莫特船長的救生艇上去。$B$B然後殺死奈古拉什，將斯莫特的彎刀交給荊棘谷的斯莫特船長。', '', '去荊棘谷找藏寶海灣的海克拜瑞·斯莫特船長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 619 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (619, 'zhTW', '引誘奈古拉什', '', '', '', '去找荊棘谷的破損的救生艇。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 620 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (620, 'zhTW', '刺著字母的腰帶', '這條精緻的腰帶的邊上刺著兩個字母“HS”。', '將刺著字母的腰帶還給他的主人。', '', '去荊棘谷找藏寶海灣刺著字母的腰帶的主人。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (621, 'zhTW', '贊吉爾的秘密', '『流亡者』贊吉爾和他的追隨者們住在藏寶海灣東北方的朱布瓦爾廢墟和阿博拉茲廢墟裡，這個傢伙已經被他的部族放逐了。為什麼?這個……$B$B據說是因為贊吉爾掌握了可以屈服其他人的心志的方法，而他所屬部族的領袖因此非常害怕他。他讓他的追隨者們喝下了一種從叢林的植物中萃取出來的液體，用它來壓抑他們的自我意識並加強他們的力量。$B$B這種藥劑對那些試圖控制別人的傢伙來說有非常大的價值。$B$B給我弄些這種藥劑的樣本來，我要研究一下他們有什麼用處。', '收集12份贊吉爾的藥劑，把它們交給藏寶海灣的克蘭克·菲茲巴布。', '', '去荊棘谷找蠻荒海岸的克蘭克·菲茲巴布。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (622, 'zhTW', '向卡雷佈下士回報', '在你離開的這段時間裡我已經把這鍋替你修好啦。我甚至還免費加裝了一個特製的蒸汽哨，看，華麗吧！這下面還裝了一個新的自動菜刀，專門用來切蹄膀的！$B$B沒錯，克拉茲克的烹調鍋將為你帶來百分之百的烹調樂趣，我敢打賭它的主人會非常滿意的！', '將修理過的烹調鍋交給反抗軍營地的卡雷佈下士。', '', '去荊棘谷找反抗軍營地的卡雷佈下士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 623 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (623, 'zhTW', '一捆海蛇草', '$N，你不在的時候，格羅伊托人給我捎了一個信兒過來。他說他很滿意我們上次送去的貨，現在又有一位新的顧客也想要一些那種海草。$B$B我可不想花上整整一個禮拜去一趟塞拉摩，如果你願意替我去一趟的話，那就再好不過了。$B$B很有挑戰性吧?你知道那邊的塵泥沼澤吧?你可得小心點，塞拉摩可不是個普通人能去的地方。', '給塞拉摩的私掠者格羅伊帶去一束海蛇草。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (624, 'zhTW', '科泰羅的謎題', '有一座裝飾華麗，人來人往的橋$B逆風徑東，赤脊山南面之地$B在那之下，它正等待著你$B這可以叫提示，也可以叫線索$B在那裡，無盡的明天正等待著你$B在悲傷沼澤之中靜靜地等待著你', '解開這道謎題!', '', '去悲傷沼澤尋找線索。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (625, 'zhTW', '科泰羅的謎題', '卡林多上的某個遙遠之地$B危險湮滅了命運與希冀$B貧瘠之地以東的環境糟糕至極$B絕望與威脅伴著沼澤中的塵泥$B但那裡埋藏著線索供你尋覓$B在西南的一處洞穴中可解此謎題', '解開這道迷題！', '', '去塵泥沼澤尋找線索。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 626 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (626, 'zhTW', '科泰羅的謎題', '到羅德隆去！那片混亂中的土地$B在那裡，勇敢的戰士們與亡靈為敵$B在劇烈的動盪中尋找屬於你的路途$B最終你會解開這謎題$B沿著艾瑞匹克山巒，位於瀑布之底$B波光之下的寶藏正等待著你', '解開這道迷題！', '', '去辛特蘭尋找線索。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (627, 'zhTW', '克拉茲克的要求', '在阿拉希高地北部的枯鬚峽谷中有一處山洞，那裡有一種十分稀有的礦石:血石。那個山洞裡的血石雖然不是品質最佳的，但即使是低等級的血石也是很有價值的……當然這只是對那些懂得如何使用它們的人來說。$B$B我需要一些這種血石。$B$B我會在這裡修補你的鍋子，不過，當我修鍋的時候……你去給我弄些血石來吧。對，多帶點回來，我當然會給你報酬的。$B$B嗯嗯，要是你連這點事都搞不定，就去找個能搞定的人幫你!', '給藏寶海岸的克拉茲克帶去4塊次級血石礦。', '', '去荊棘谷找藏寶海灣的克拉茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 628 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (628, 'zhTW', '刨花皮靴', '裡層的東西都已經做完了，現在只剩下外面的表層部分了。表層部分我只用品質最好的老海鱷魚的皮。這種皮比帆布還要好，還要結實--如果你願意的話--，還可以為我的完美設計增加設計感和特色。$B$B但是要找到一張完美的皮很難，只有老海鱷魚的皮是唯一能配得上我的設計的材料。老海鱷只會在其他鱷魚被攻擊的時候才會出來保護族群，所以你恐怕得先殺些普通鱷魚來引牠們出來。', '帶1張老海鱷的皮給藏寶海灣的崔斯里克。', '', '去荊棘谷找藏寶海灣的崔斯里克。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (629, 'zhTW', '暗礁海', '很久以前，有一座古老的食人妖城市因為大地震沉入了西北方的野人海岸水下。現在那裡被一群魚人所佔據著，任何接近的人都會遭到他們的攻擊，我們把那處地方叫作暗礁海。$B$B在那片廢墟之中有一塊古老的石板，上面記錄著一位名叫格里雷克的食人妖英雄的傳說。那塊石板對於我們暗矛部落來說具有神聖的意義，儘管它太大，沒辦法全部運走，但我仍希望有人能從上面敲下一塊裂片，讓我們帶到奧格瑪的新家去供奉起來。', '給格羅姆高營地裡的肯維雷帶回一塊石板裂片。', '', '去荊棘谷找格羅姆高營地的肯維雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 630 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (630, 'zhTW', '瓶中信', '$N，我的一切都全靠你了！是藍鬃猩猩之王穆克拉把我抓進來的，它統治著這島上所有的野獸，它們不顧我的反抗，用這些鐵鏈把我給鎖在這兒。如果你能殺了它，從它身上找到能夠開啟這套鐐銬的鑰匙的話，我會好好報答你的。$B$B它通常在這座島的北邊活動，但你一定得小心，它絕對是一個很難對付的傢伙。', '殺死穆克拉並帶著鑰匙回去救出普巴爾公主。', '', '去荊棘谷找哈圭羅島的普巴爾公主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 631 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (631, 'zhTW', '薩多爾大橋', '當時，山裡突然傳出了一陣巨大的爆炸聲，而且在山谷中回蕩了很久。那簡直太可怕啦!士兵們為了守衛薩多爾大橋死傷慘重。長鬚說我們總有一天要向黑鐵矮人們復仇的。我們目前的情況非常窘迫，而且暫時也得不到任何援軍。長鬚派了老伊本瑟去偵察東邊的那座橋，看看我們是否有機會攻陷那裡。可這已經是好幾天以前的事了。丹莫德目前全城被圍，我們根本無法抽出人力去聯絡他。或許你能幫忙去找他……', '拉格·加瑪森要求你找到老伊本瑟。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (632, 'zhTW', '薩多爾大橋', '很顯然，可憐的老伊本瑟遭遇到了黑鐵矮人的伏擊，已經戰死了。但你突然注意到了他緊握著的拳頭中似乎有一張皺皺的羊皮紙。$B$B將這條令人沮喪的消息告訴拉格·加瑪森，並把你的發現報告給他。', '到濕地的丹莫德向拉格·加瑪森回報，並將你在伊本瑟屍體上找到的羊皮紙交給他看看。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (633, 'zhTW', '薩多爾大橋', '天呀!不!可憐的伊本瑟，這實在是一個悲劇。$B$B我們絕對不能讓他就這樣白白犧牲了。你發現的這張羊皮紙上寫道，是卡姆·深怒在背後組織了這次進攻，並且，他還在薩多爾峽谷的阿拉希高地那一側囤積了不少爆裂物。$B$B如果他們用這些爆裂物摧毀了橋樑的話，那麼我們的通向北邊的主要補給線就會被徹底切斷!必須摧毀這些爆裂物， $N !完成了這個任務後立刻回來向我覆命。$B$B你是我們最後的希望了。', '摧毀堆積的爆裂物。', '', '去濕地找丹莫德的拉格·加瑪森。', '摧毀軍火庫', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 634 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (634, 'zhTW', '向聯盟求援', '我想拜託你再幫我一個小忙，$c。我們正等待著來自鐵爐堡的援軍。但是，羅戈說阿拉希高地上的避難谷地那裡還有一處聯盟的營地。到那裡去找尼艾絲隊長。問問這位好心的隊長看看聯盟是否能派一些暫時沒有任務在身的士兵來幫我們奪回丹莫德和薩多爾大橋。', '到避難谷地找尋尼艾絲隊長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 635 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (635, 'zhTW', '山中的水晶', '你拿著這塊裂片，明顯地感覺到它在跳動著……$B$B你感到它在祈求，好像有什麼人想要與你交流，急切地需要你的幫助。$B$B你的腦中出現一幕奇特的影像─在阿拉希的北部山脈上，有一塊明亮的水晶從地面上突出來。$B$B你感覺到自己仿佛被帶到了那個地方……', '找到你在幻象中看到的那塊水晶。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 636 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (636, 'zhTW', '大地公主的傳說', '這本書敘述了元素公主密斯賴爾和她被囚禁在阿拉希高地下面的故事。$B$B它還敘述了高地裡的一處秘密的水晶岩層。這些被稱為“密斯賴爾水晶碎片”的東西是囚禁大地公主的監獄的窗戶。$B$B如果某個勇敢的人能找到密斯賴爾水晶碎片，那麼$g他:她;就有可能和她交談……', '找到密斯賴爾水晶碎塊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 637 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (637, 'zhTW', '蘇利·巴魯的信', '你手中的這封信濕淋淋的，已經面目全非了，只有幾頁像是得到了精心保護的信紙上的字跡還能辨認。$B$B這封信是寫給鐵爐堡的薩拉·巴魯女士的，開頭寫著，「親愛的薩拉……」', '把蘇利·巴魯的信交給鐵爐堡的薩拉·巴魯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 638 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (638, 'zhTW', '食人妖之敵', '隨著索拉斯·托爾貝恩的死與激流堡的毀滅，沃金大人指示我們要不惜一切代價將那把傳說中的寶劍託卡拉爾從人類的手裡搶過來，供我們在與祖爾格拉布的食人妖的戰鬥中使用。$B$B我們已經派出了一個名叫森谷的資深獵人前往阿拉希高地東北部的落錘鎮去尋找它。', '前往阿拉希高地的落錘鎮，與森谷談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 639 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (639, 'zhTW', '激流堡符印', '在古代，食人妖曾與阿拉索帝國以及我們最強大的對手——被稱為“激流堡的伊格納烏斯”的托爾貝恩作戰。托爾貝恩總是揮舞著託卡拉爾劍進行作戰。在古代語中，託卡拉爾是“食人妖殺手”的意思。$B$B然而，現在托爾貝恩子孫的勢力已大不如前了，他們的要塞也已經變成了廢墟。$B$B託卡拉爾劍是由幾塊符印保護的，這些符印現在都在激流堡的倖存者手中，我們必須獲得它們。$B$B辛迪加組織擁有第一塊——這一塊應該就在他們駐紮於激流堡的那群人中的某個人手裡。', '幫落錘村的森古拿回激流堡符印。', '', '去阿拉希高地找落錘鎮的森古。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 640 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (640, 'zhTW', '破碎的符印', '索拉斯·托爾貝恩的墓室由三塊符印護衛，這其中的第一塊你已經從辛迪加手中得到了。另外兩塊更難得到，因為它們被牢牢地控制在激流堡的民兵手裡。$B$B索拉丁符印被索拉斯的兒子加林分成了十一塊，分別由一個激流堡守衛者掌握。取回這些符印，把它們交給食人妖祭司托爾甘，他能夠將它們合成一塊完整的符印。', '從激流堡的守衛者那裡取回5塊符印碎片，把它們交給落錘村的托爾甘。', '', '去阿拉希高地的落錘鎮找托爾甘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (641, 'zhTW', '索拉丁符印', '復原得完美無缺。現在，這塊完整的符印可以被用於開啟托爾貝恩墓穴上的封印了。把它交給森古吧，他一定還有別的任務要你完成。', '把修復的索拉丁符印交給落錘村的森古。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 642 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (642, 'zhTW', '受困的公主', '我叫密斯賴爾，我是大地的公主。巨人們俘獲了我，把我拘禁在阿拉希高地的地下深處。這些水晶碎塊是我和外界交流的唯一途徑。$B$B幫幫我。這些巨人的盟友─枯鬚狗頭人─就在東邊的枯鬚峽谷裡活動，那裡有一塊類似的水晶裂片。要啟動那塊水晶，你必須從狗頭人那裡收集到密斯賴爾之塵，然後把它們放在水晶上。$B$B求求你了， $N ，幫幫我吧!', '收集密斯賴爾之塵。把它們放在枯鬚峽谷中的虹光水晶裂片上。', '', '去阿拉希高地找枯須峽谷的虹光水晶碎塊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 643 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (643, 'zhTW', '阿拉索符印', '儘管他們還沒有控制激流堡，更不要說整個阿拉希高地，但那人類王子卻率領著剩餘的騎士在鄉間疾馳。我不能理解他為什麼這麼做，誰又能理解人類的思維方式呢？$B$B且不管他到底是怎麼想的，最重要的是他把一塊符印交給了瓦羅卡爾中尉，也就是那群騎士的首領。找到這個人，把他的符印帶回來交給我。', '取回阿拉索符印，把它交給落錘村的森古。', '', '去阿拉希高地找落錘鎮的森古。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 644 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (644, 'zhTW', '托爾貝恩符印', '開啟索拉斯·托爾貝恩墓室所需的最後一塊符印掌握在他兒子手中。他深居在激流堡的一座由民兵控制的教堂裡。加林王子的保衛措施非常嚴密，他本人也是一名強大的勇士，所以這次你的任務會是非常艱鉅的。', '殺掉加林·托爾貝恩王子，把托爾貝恩符印帶給落錘村的森古。', '', '去阿拉希高地找落錘鎮的森古。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 645 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (645, 'zhTW', '託卡拉爾', '將四塊符印放在一起，它們就能互相結合形成一塊完整的符印。毫無疑問，這塊符印能夠擊破托爾貝恩地墓室裡的防護魔法。$B$B托爾貝恩的遺體就埋葬在激流堡教堂後的密室中。去取回託卡拉爾。', '從激流堡的托爾貝恩墓室中取回託卡拉爾劍。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 646 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (646, 'zhTW', '託卡拉爾', '光芒慢慢地褪去，石鞘中的託卡拉爾劍已經鬆動了。', '把託卡拉爾劍交給落錘村的森古。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 647 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (647, 'zhTW', '馬克里爾的月光酒', '昨晚我喝了很多月光酒!要是布萊德知道我在當差的時候溜出去准會要了我的命。$B$B我喝得有些太多了，就感覺到頭頂上有一整支蒸汽坦克部隊呼嘯而過，滿耳都是隆隆的響聲。$B$B哦，瞧這時間!我答應南海鎮的布魯米·比格爾要送他一些月光酒來抵債的。$B$B但是離我交貨的最後期限只有15分鐘了!請你把這些帶給他，好麼?要快!', '把馬克里爾的月光酒交給南海鎮的布魯米·比格爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 648 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (648, 'zhTW', '拯救OOX-17/TN！', '那個地精的聲音再次從那個機器人中傳了出來：$B$B“我需要你幫忙把OOX-17/TN移動到一個安全的開闊地，這樣它才可以啟動起飛程式。它自帶隱形系統，但是我需要一點時間來遠端啟動這個系統。請你把這個機器人從現在的位置護送到熱砂港去！那裡是個非常理想的起飛點，有足夠的空間作為機器人起飛的跑道！”$B$B“將它護送到那裡，然後再到藏寶海灣來找我！奧格索普·奧布諾提斯——完畢！”', '將OOX-17/TN護送到熱砂港，然後向藏寶海灣的奧格索普·奧布諾提斯報告。', '將OOX-17/TN安全護送到目的地。', '去荊棘谷找藏寶海灣的奧格索普·奧布諾提斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (649, 'zhTW', '尋找蜜酒', '我這有些事情要你來做，如果你和我一樣是蜜酒的愛好者，那我敢說你一定會接受這項任務！$B$B蜜酒當然是一種酒，你這個蠢貨！$B$B在一座被部落廢棄的村莊那裡有很多的辛特蘭蜜酒，這些蜜酒是以前那裡還有人做生意的時候留下的，那絕對是極品的蜜酒！瑪爾頓的手下知道這個村莊的具體位置，我要你去那裡一趟，給我帶一些蜜酒回來！和瑪爾頓談談吧，他會給你進一步指示的。', '和奧格瑪的瑪爾頓·杜佛斯談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 650 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (650, 'zhTW', '尋找蜜酒', '你得去跟那個名叫基沃拉丁·獵日者的精靈談談。他只需聞一下就可以辨別任何一種葡萄酒！他可以幫我們弄到蜜酒。嗯……我們需要至少六瓶包裝好的蜜酒，其中兩瓶是給爸爸的，至於他實際上需要多少瓶倒無關緊要……當你打包好了蜜酒，並且搞到了給爸爸的兩瓶蜜酒之後，就回到我這裡來！$B$B基沃拉丁的營地在辛特蘭的高等精靈大屋附近，不過那些高等精靈不太友善……相信我。', '和基沃拉丁·獵日者談一談，他的營地就在辛特蘭區域。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 651 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (651, 'zhTW', '禁錮之石', '在阿拉希高地上散佈著4塊禁錮之石，這些石頭將我牢牢地釘在地下。$B$B要想解除它們，你就必須解除最堅固的那塊:內禁錮之石。首先，你必須搜集到其他三塊石頭的鑰匙。$B$B這些石頭都有守護者在看守，但是如果你足夠聰明或者足夠幸運的話，就能找到消滅這些守衛的辦法。', '從西禁錮之石、東禁錮之石和外禁錮之石中搜集烈焰鑰匙、海浪鑰匙和雷霆鑰匙。', '', '去阿拉希高地找內禁錮法陣的內禁錮之石。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 652 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (652, 'zhTW', '打開鑰匙之石', '禁錮之石的開啟基本解開了這些束縛著我的東西，可還有一把牢不可破的鎖讓我無法動彈。你看到這圈石頭中的那塊鑰匙之石了嗎?開鎖的鑰匙在弗茲魯克手中，他是囚禁我的巨人之一，也是這石鎖的看護人。$B$B你必須從弗茲魯克那裡獲得一把名叫「秩序魔棒」的鑰匙來打開鑰匙之石。$B$B你已經為我做了這麼多， $N ，只是再幫個微不足道的小忙……我會對你更加感激不盡的!', '找到並殺死弗茲魯克，然後把秩序魔棒帶到阿拉希高地的鑰匙之石旁。', '', '去阿拉希高地找內禁錮法陣的鑰匙之石。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 653 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (653, 'zhTW', '密斯賴爾的盟友', '<密斯賴爾開始說話。>自由!我自由了!我終於自由了，我要恢復力量，不過現在我還得躲避那些追捕我的敵人。因為如果他們現在找到我的話，肯定會輕鬆將我降服並重新監禁我。總有一天我會回到那些巨人的面前，讓他們為禁錮我的行為而後悔!你是一個高尚的盟友，$N。我會再次需要你的幫助。等我準備好之後，我需要你來將我召喚到地表上。去和鐵爐堡的葛利·硬骨談談吧，他知道如何召喚我。', '和鐵爐堡的葛利·硬骨談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 654 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (654, 'zhTW', '塔納利斯的樣本', '啟動能量源之後，野外實驗工具包開始閃光和震動，看來它開始按照預定的程式工作了。$B$B根據首席工程師比格維茲所說的，你現在有兩個小時的時間在塔納利斯沙漠收集你所需的資料。如果你在兩個小時內無法收集到全部資料，那麼收集到的資料也將消失，而你則不得不重新從安全主管吉羅姆·比格維茲那裡購買另外一個能量源。$B$B當你完成任務之後就盡快回到他那裡。', '收集8份蜥蜴樣本、8份土狼樣本和8份蠍子樣本，然後在能量源耗盡之前把野外實驗工具包還給加基森的安全主管吉羅姆·比格維茲。', '', '去塔納利斯找加基森的首席工程師比格維茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 655 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (655, 'zhTW', '落錘鎮', '一切是那麼的清晰，似乎就發生在昨夜……那麼多年了，從來都看不到任何希望，卻有重重的木枷和鋼索將我們的族人束縛在這個可怕的地方。終於，終於！奧格瑞姆酋長回來解救我們了！他像座鐵塔一樣站在那裡，穿著那套如午夜一般漆黑的戰甲，將他的戰錘高高舉起。$B$B那……太恐怖了……那懦夫的一擊居然擊倒了我們最偉大的英雄。那個懦夫騎著戰馬，手持長矛向他刺去……我跪倒在地。哪裡才有希望？哪裡才有希望……', '和落錘村的托爾甘交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (656, 'zhTW', '召喚大地公主', '你必須在密斯賴爾恢復力量之前打敗她。否則，一旦等到她聚集到足夠的能量，密斯賴爾就會向追捕她的人發起挑戰！有一些人自信能控制住她，但是如果她真能被控制住，巨人們有必要先發制人把她囚禁起來嗎？$B$B這是個瘋狂的邏輯，難道不是嗎？$B$B你必須在第一次和她接觸的密斯賴爾水晶碎塊那裡將她召喚出來，然後打敗她。在打敗她之後搜出她身上的怪異鐐銬，然後與密斯賴爾水晶碎塊縛在一起。$B$B只有這樣做才能再次將密斯賴爾囚禁起來。', '到密斯賴爾水晶碎塊去召喚她，然後打敗她。$B$B搜出她身上的怪異鐐銬，將其和密斯賴爾水晶碎塊縛在一起。', '', '去找辛特蘭的密斯賴爾水晶碎塊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 657 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (657, 'zhTW', '新的瘟疫?', '<奎艾開始仔細地閱讀這份資料>這真的很有趣。看起來藥劑師喬瑞爾正在格沙克農場裡進行著一些危險的試驗，很難說這會和希爾斯布萊德有什麼牽連，不過費恩應該不會想見到我們讓這件事繼續下去。你走了以後，我們看見有一些獸人跑了進來，不過我沒有足夠的實力去幫基恩洛的忙。如果你可以的話，她需要人保護她到農場裡去偷取喬瑞爾那些還沒有送往泰倫磨坊的研究資料。', '和基恩洛談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 658 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (658, 'zhTW', '新的瘟疫?', '是費恩讓你來找我們的吧?我一點都不吃驚，那傢伙總是擔心這個擔心那個的。$B$B我們監視這個農場已經有段時間了，基恩洛說她不久前看到有一個信差從那間小房子裡走出來，往南邊去了。$B$B她平時話有些多，不過在這種危險的地方，我總是相信她的直覺。$B$B嗯……你的追蹤能力怎麼樣?我們認為那個信差可能是帶著信去塔倫米爾了。如果你能弄到那些檔案，就有可能幫助我們搞清楚在希爾斯布萊德所發生的那些怪事。', '找到被遺忘者信差，把她的密封的信件交給格沙克農場裡的奎艾。', '', '去找阿拉希高地的奎艾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 659 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (659, 'zhTW', '新的瘟疫?', '歡迎你，$N。我帶著一群探險者到這裡來調查最近發生的一些怪事。我在希爾斯布萊德有個堂兄，他最近殺掉了家養的那只名叫斯坦利的狗，因為這隻狗突然長得很巨大，而且還野蠻地攻擊所有靠近它的人。我想這一定和不死生物有些關係，我們正在尋找能證明這個猜想的更多證據。我的兩個同伴奎艾和基恩洛到阿拉希高地上的格沙克農場去了，最近這些天一直沒有她們的消息。你能幫我找到她們嗎?我越來越擔心了……', '到阿拉希高地上的格沙克農場附近找到奎艾和基恩洛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 660 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (660, 'zhTW', '新的瘟疫?', '好了， $N 。我已經準備好了。$B$B可以出發了嗎?', '保護基恩洛，直到她回到奎艾身邊。', '保護基恩洛', '去找阿拉希高地的奎艾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (661, 'zhTW', '新的瘟疫?', '就算讓基恩洛在旅店裡睡上一晚，她也不會比現在看起來更健康。你保護她保護得很好。她從農場拿回來的這些東西，至少能讓費恩瞭解到在阿拉希高地究竟發生了些什麼。為了確保你們的行動不會導致任何報復行動，我們會在這裡繼續留守一段時間。你願意返回南海鎮去和費恩談談嗎?', '到南海鎮去找費恩·奧德利克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (662, 'zhTW', '深海打撈', '奧布里領船進入海灣，我們確信能在這裡發現寶藏。先驅號安全靠岸，但是當處女號和銀松之魂號靠近港口的時候，退潮開始了。此時發生了怪事！$B$B那兩艘船撞上了什麼東西……似乎是暗礁中的什麼廟宇……它們很快就沉沒了，這真是一場災難。$B$B我們必須要在離開以前去取回他們的日誌和航海圖，這些有價值的資訊絕對不能留給任何其他人！', '大副尼茲利克斯讓你從處女號和銀松之魂號中取回航海圖和航海日誌。', '', '去阿拉希高地找法迪爾海灣的大副尼茲利克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (663, 'zhTW', '法迪爾海灣', '魯魯看見了一個小$r！魯魯總是待在哨所上！$B$B歡迎來到法迪爾海灣。奧布里船長說過，我們在這裡待不了多久。我們只要蒐集寶藏然後返回藏寶海灣就行了。$B$B但是魯魯認為我們要在這兒待很長很長的時間，我們失去了兩艘船。可憐的銀松之魂號和處女號！她們長眠在海底！$B$B魯魯說，如果你想在這逗留的話，就去和奧布里船長談談吧。', '和法迪爾海灣的奧布里船長交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (664, 'zhTW', '船長的復仇', '啊，多麼可怕的生活！我本以為我再也不能像現在這樣坐在火堆旁呼吸著新鮮的空氣了！$B$B船員們為了拯救我那美麗漂亮的處女號盡了全力。願神保佑他們，保佑他們的心靈。$B$B奧布里船長的船安全地進了港，可我們就沒那麼幸運了，大浪弄沉了我們的船。$B$B前一秒鐘我們還漂浮在海上，轉眼間就又被海浪吞沒。而那些該死的納迦還殺死了所有的倖存者！我逃到這裡來，算是勉強保住了性命。$B$B我要讓那些野獸去死！', '法迪爾海灣的斯迪加特船長要你去殺掉10個刺脊襲擊者和3個刺脊巫師。', '', '去阿拉希高地找法迪爾海灣的斯迪加特船長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (665, 'zhTW', '水下寶藏', '既然我們已經整裝待發，那麼幫助奧布里先生尋找丟失的精靈寶藏就是當務之急了！$B$B在黑暗的海底，如果沒有任何輔助手段的話，要想找到那些寶藏幾乎是不可能的。博士做的潛水鏡可以派上大用場，不過他要從山上的洞穴裡弄些魔石來，好給他的潛水鏡附上魔法。$B$B但是那座洞穴已經被詛咒了！只要我們靠近洞穴就會遭到伏擊。你得掩護我，讓我控制魔石的能量，將它注入到潛水鏡裡。', '護送菲茲索普教授到洞穴裡去並平安返回。', '保護菲茲索普教授', '去阿拉希高地找法迪爾海灣的德拉克里格博士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (666, 'zhTW', '水下寶藏', '寶藏在海床上放了那麼長時間，早已經被岩石包裹起來了。但是藉助潛水鏡中的魔法力量，你可以輕而易舉地鎖定這些寶藏。$B$B地精的創造能力實在是讓人驚歎！$B$B那麼你去把尋寶潛水鏡借來用用，$n，看你能不能幫奧布里船長找回些丟失的寶藏。$B$B我可以潛游到那兒，可是……嗯……在這片安全而乾燥的土地上，我有些重要的科學研究要做……嗯，是這樣的。', '法迪爾海灣的德拉克里格博士要你去收集10塊精靈寶石並在完成任務後歸還尋寶潛水鏡。', '', '去阿拉希高地找法迪爾海灣的德拉克里格博士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 667 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (667, 'zhTW', '水下伏兵', '太糟了，看來那些刺脊納迦正在囤積重兵準備發動攻擊。納迦在作戰時是出了名的冷酷無情，只要你還有一口氣，他們就決不會停止攻擊。$B$B我並不是說我自己的性命比弟兄們更寶貴，但你必須得保護我，因為如果沒有我對大海的瞭解，弟兄們是不可能回到藏寶海灣去的。$B$B納迦會從大海里向我們發起進攻，我要你留在這兒與我一起對抗他們，齊心協力把他們打退。$B$B你準備好了嗎，$n？', '在納迦的攻擊中保護沙克斯·奧布里。', '保護沙克斯·奧布里', '去阿拉希高地找法迪爾海灣的沙克斯·奧布里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (668, 'zhTW', '水下寶藏', '我們不要讓奧布里船長等了。他急著想看到這些寶藏呢。這不正是我們在這兒的原因嗎？$B$B和這些海盜們打了幾個星期的交道以後，我和教授都意識到，手裡拿著海盜的寶藏永遠是不安全的。$B$B拿著這些，$n，把它們交給奧布里。', '把精靈寶石交給奧布里船長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (669, 'zhTW', '水下寶藏', '艦隊指揮官卡拉·海角一定想馬上知道我們找到了什麼。$B$B你也看到了，我們還不能離開這兒。不單單是因為潮水太低的緣故，還因為那些被我們驚動的可惡傢伙正密切地注視著我們的一舉一動。$B$B假如你能把口信帶給藏寶海灣的艦隊指揮官卡拉·海角，並告訴他我們已經發現寶藏的話，你可就幫了我們黑水海盜的大忙了。把這件東西交給艦隊指揮官卡拉·海角，這樣他就會確信你說的是真的了。', '把精靈寶石樣本交給藏寶海灣的艦隊指揮官卡拉·海角。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 670 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (670, 'zhTW', '水下寶藏', '嘿，$n，看來你是個喜歡冒險的$r。在我們重新進貨之前，我的船隊會一直停泊在藏寶海灣。$B$B這裡即將發生一些大事，我得找人把相關的絕密資訊通報給在阿拉希海岸上的沙克斯·奧布里。$B$B你可以確保將口信安全而保密地送達嗎？', '把海角船長的密信送給阿拉希高地的沙克斯·奧布里。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (671, 'zhTW', '邪惡的魔法', '我感覺空氣中彌散著一種奇怪的東西……這種感覺在我的血液中不斷升騰。對此我感到很奇怪，於是便著手去尋找給我造成這種不安的原因，然後我就在西邊的諾斯弗德農場找到了一些邪惡的召喚法術留下的痕跡。當我慢慢地靠近時，我的熱血開始沸騰，胸中的怒氣不斷上升。$B$B我在地上發現了一枚血石護符，那是用在惡魔召喚儀式中的東西。可是，我找到的這枚血石護符的能量已經被耗盡了。現在我需要再弄一些來研究，可我不敢回農場去了。你能幫我找一些來嗎？', '幫落錘村的托爾甘找10枚血石護符。', '', '去阿拉希高地的落錘鎮找托爾甘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 672 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (672, 'zhTW', '振奮精神', '我們把他安頓下來，不斷地鼓舞他，向他講述我們在卡林多建立偉大的奧格瑪城的故事，但所有的這些都無法打動他。$B$B關於我們年輕的酋長的故事，擁有奧格瑞姆的戰甲和戰錘的索爾酋長……也許吧……也許吧！我們新發現的薩滿魔法或許會帶給他新的希望。這值得一試！$B$B我們可以給他一件小東西，對……給我帶些迅猛龍的眼睛，我要看看我們能做些什麼。', '從高地闊步龍和高地長尾龍身上取得10個高地迅猛龍的眼球，把它們交給落錘村的托爾甘。', '', '去阿拉希高地的落錘鎮找托爾甘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 673 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (673, 'zhTW', '邪惡的魔法', '我確信有一個強大的術士居住在激流堡城內。這個術士經常透過一種魔法物品來召喚大量的惡魔。我們必須毀掉他的能量源泉。$B$B找到這個術士，殺掉他。把所有你在他身上發現的物品都拿來給我，我會設法銷燬它的。我們絕對不能讓這片大地再被玷汙了！', '取回瑪雷茲·考爾的血石寶珠，把它交給落錘村的托爾甘。', '', '去阿拉希高地的落錘鎮找托爾甘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (674, 'zhTW', '振奮精神', '把這枚護符交給戈穆爾，看看迅猛龍的力量能否喚醒這位勇士的血管中曾經燃燒過的火焰。', '把迅猛龍利爪護符交給戈穆爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (675, 'zhTW', '振奮精神', '<戈穆爾把護身符扔到了地上>$B$B托爾甘讓你來的，是嗎？呸！我不理解他為什麼要憐憫我。在我不能和我的酋長一起戰死的時候，我就不再接受任何憐憫了。我註定要被這殘酷的命運煎熬……', '和托爾甘談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (676, 'zhTW', '落錘之戰', '軟弱的傢伙……他們全都是懦夫……你，$c，你在看什麼？你覺得自己有什麼特殊的麼？怎麼不去證明一下？$B$B阿拉希的落錘村哨所正受到攻擊。再不增派援兵的話，他們就會全軍覆滅的。$B$B不過在你去那裡之前，是不是應該先試試看自己夠不夠格？阿拉希的激流堡東北部有個食人魔的營地，石拳部族的食人魔就住在那裡。等你搞定了那裡的食人魔和執行者之後，再去向落錘村的杜拉姆法爾報告吧。', '殺掉8個石拳巨魔和10個石拳執行者，然後去阿拉希高地的落錘村哨所找杜拉姆法爾。', '', '去阿拉希高地找落錘鎮的杜拉姆法爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (677, 'zhTW', '短兵相接', '枯木食人妖和阿拉希的石拳巨魔聯合起來，要把我們趕出這片土地，但我們決不會把命運交給他們掌控！我們要除掉他們，讓他們知道誰是這兒真正的主宰。$B$B巨魔背棄了我們，食人魔想要把我們當作美味的食物——我們決不能允許這種事情發生。$B$B現在，讓我們從南邊的枯木食人妖開始吧。去殺掉他們，讓他們血流成河！', '殺死10名枯木擲斧者、10名枯木獵頭者和8個枯木巫醫，然後回到落錘村哨所的杜拉姆法爾那裡。', '', '去阿拉希高地找落錘鎮的杜拉姆法爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (678, 'zhTW', '短兵相接', '$N，你的強大已經是有目共睹的了。現在讓我們看看你如何去面對一個真正的敵人。$B$B從這裡往西南走，在通往矮人修建的那座大橋的途中，有一個石拳巨魔的老巢。如果我沒搞錯的話，那兒的虐待者和法師對你來說應該是個難度不小的挑戰——至少到現在為止對於我們來說是這樣的。$B$B儘可能多地殺死他們，無論最終是勝利還是失敗，無論回來見我的是你自己還是你的靈魂，我都會讚賞你在戰鬥表現出的堅韌精神。', '殺死10個石拳蠻兵和4個石拳法師，然後向落錘村哨所的杜拉姆法爾覆命。', '', '去阿拉希高地找落錘鎮的杜拉姆法爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 679 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (679, 'zhTW', '短兵相接', '$N，現在是時候和這些傢伙算總賬了……很明顯你完全有能力幫我們完成這最後的一擊。這些與我們為敵的蠢貨的領導者已經在激流堡廢墟裡建立了巢穴。激流堡的廢墟……那是人類軟弱無能的最好證明！$B$B找到那些石拳領主和他們的薩滿祭司，把他們全都殺掉，這些妄圖將我們趕離家園的蠢貨們活不了多久了！', '殺死7個石拳薩滿祭司和3個石拳領主，然後向落錘村哨所的杜拉姆法爾覆命。', '', '去阿拉希高地找落錘鎮的杜拉姆法爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 680 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (680, 'zhTW', '真正的威脅', '你幫我丈夫幹得不錯，$c，可他並不知道為什麼落錘村會遭受攻擊。$B$B奧卡拉爾是瑪格索爾派到激流堡去的走狗，他非常害怕我的丈夫。很多年前，我的丈夫打敗了他，他巴不得我的丈夫早點死去。$B$B我占卜到奧卡拉爾給我的丈夫設下了陷阱，並且感覺到了那些食人魔正在伺機害他……$B$B如果他知道那些食人魔在哪裡的話，一定會不顧三七二十一地殺過去。所以……請你幫我殺死奧卡拉爾吧。', '殺死奧卡拉爾，將他的頭顱帶給落錘村哨所的科林法爾。', '', '去阿拉希高地找落錘鎮的科林法爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (681, 'zhTW', '諾斯弗德農場', '我們正在為激流堡而戰，然而我們卻逐漸落入下風。我們、巨魔以及辛迪加分別控制著這座城市的一部分，現在我們這三方勢力陷入了整日互相征戰卻毫無突破的僵局。$B$B然而，當敵人們力量開始逐漸增強的時候，我們卻在慢慢地變弱。$B$B我們需要南海鎮的援助，但是辛迪加控制了我們和南海鎮之間的領地，因此那邊的補給很難運到這裡來。$B$B到辛迪加在諾斯弗德農場的基地去幹掉他們，也許這樣做能讓我們補給線上的壓力大大減輕，然後才能有更多的物資平安運抵這裡。', '殺掉6個辛迪加雇傭兵和10個辛迪加路霸，然後回到避難谷地去向尼艾絲隊長覆命。', '', '去阿拉希高地找避難谷地的尼艾絲隊長。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (682, 'zhTW', '激流堡徽章', '我們的民兵分隊正在和控制著激流堡的辛迪加成員激戰。為了刺激他們那群烏合之眾與我們作戰，辛迪加的頭目們使出了重金懸賞的手段，只要有人能殺死我們的民兵，並從他們身上繳獲激流堡徽章，辛迪加都會給予獎勵。$B$B我們必須奪回那些徽章─決不能讓劊子手們用我們的戰士的性命來換取金錢!$B$B到激流堡城內的辛迪加控制區去殺掉那些歹徒，取回我們的徽章。', '把7個激流堡徽章交給位於避難谷地的尼艾絲隊長。', '', '去阿拉希高地找避難谷地的尼艾絲隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 683 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (683, 'zhTW', '薩拉·巴魯的請求', '$n，我對你有個小小的請求。$B$B這張便箋是我寫給鐵爐堡的國王麥格尼·銅鬚的。對於你這種曾為聯盟的事業英勇作戰的$r來說，這個任務再容易不過了。$B$B以我在現在這種狀態去覲見國王陛下是很不合適的，我相信你應該可以理解。', '把薩拉·巴魯的便箋交給鐵爐堡的國王麥格尼·銅鬚。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (684, 'zhTW', '通緝:瑪雷茲·考爾', '重金懸賞瑪雷茲·考爾的項上人頭。這個獸人是辛迪加組織的高級顧問和技工，人們最後一次看見她是在激流堡內的辛迪加控制區。$B$B賞金請到尼艾絲隊長處領取。$B$B請注意:瑪雷茲是一個強大而狡猾的術士，她和惡魔有著非常密切的聯繫。追殺她時務必非常小心。', '把瑪雷茲的頭顱交給避難谷地的尼艾絲隊長。', '', '去阿拉希高地找避難谷地的尼艾絲隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 685 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (685, 'zhTW', '通緝:奧圖和法庫雷斯特', '激流堡民兵團重金懸賞法庫雷斯特領主和他的保鏢奧圖的頭顱。法庫雷斯特是辛迪加在阿拉希地區的主要領導者，他的死將使該組織在這一地區的活動陷入癱瘓。$B$B他的保鏢奧圖不是我們的戰略目標，但他生性兇殘，已經殺死了許多激流堡的士兵。$B$B賞金請到尼艾絲隊長處領取。', '把法庫雷斯特和奧圖的頭顱交給避難谷地的尼艾絲隊長。', '', '去阿拉希高地找避難谷地的尼艾絲隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 686 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (686, 'zhTW', '國王的禮物', '象巴魯夫人這樣好心的矮人可能無法理解要忍受這場可笑的戰爭其實是為了我們族人更高的利益。無論是她的丈夫還是其他在戰鬥中獻出生命的矮人，每次聽到他們的名字都讓我感到非常心痛。$B$B雖然我不能讓她的丈夫死而復生，不過我可以向他致以崇高的敬意。$B$B我會委派大石匠瑪布勒斯坦為蘇利·巴魯建造一座紀念碑。$B$B把口信帶給他，$c。你來負責傳達我的這條命令。', '國王麥格尼·銅鬚讓你去和大石匠瑪布勒斯坦談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (687, 'zhTW', '迷失者塞爾杜林', '迷失者塞爾杜林曾經是我們暮光之錘的一員。但是有一天他突然精神失常，摒棄了我們的信條，背叛了我們的信仰。在背離我們之前，他還偷走了密斯賴爾卷軸！我們沒能抓到他，但有傳言說他就躲藏在荒蕪之地中，整日胡言亂語，已經完全瘋掉了。如果你要將公主帶回來的話，就必須找到卷軸，而要找到卷軸，你就必須找到塞爾杜林。', '找到迷失者塞爾杜林。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 688 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (688, 'zhTW', '密斯賴爾的盟友', '<密斯賴爾開始說話>$B$B自由！我自由了！我終於自由了，我要恢復力量，不過現在我還得躲避那些追捕我的敵人。因為如果他們現在找到我的話，肯定會輕鬆將我降服並重新監禁我。$B$B總有一天我會回到那些巨人的面前，讓他們為禁錮我的行為而後悔！$B$B你是一個高尚的盟友，$N。我會再次需要你的幫助。等我準備好之後，我需要你來將我召喚到地表上。$B$B去和落錘村的薩魯克談談吧，他知道如何召喚我。', '和落錘村的薩魯克談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 689 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (689, 'zhTW', '國王的禮物', '我們的國王要建一座紀念碑向一個叫蘇利·巴魯的士兵致敬？你是說那個可憐的士兵是在薩多爾大橋的悲劇中死的？$B$B唉，艾澤拉斯還會有和平嗎？$B$B不管怎樣，國王下達的任務就是第一要務。我要用最好的石頭來建這座紀念碑，你到希爾斯布萊德的丘陵洞穴為我找一些奧特蘭克花崗岩來吧。', '鐵爐堡的大石匠瑪布勒斯坦要5塊奧特蘭克花崗岩。', '', '去找丹莫洛的大石匠瑪布勒斯坦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 690 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (690, 'zhTW', '馬林的要求', '你好，$N。我看出你是個渴望冒險的$c，現在我有項任務需要你的幫助。我原來的主人，大法師特雷萊恩，不久從位於阿拉希高地的激流堡裡逃了出來。他讓我到那裡去幫他取回一些臨走時落下的物品。激流堡現在已經陷入了重圍之中，他在努力保衛阿拉索之塔，但是現在看來情況越來越危險了。我的人已經到了阿拉希高地，但他們需要更多的支援。你有興趣去幫忙嗎?', '找到位於阿拉希高地上的避難谷地中的斯奎爾圖。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 691 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (691, 'zhTW', '證明實力', '大法師馬林派斯奎爾圖和我到這裡來為他收集一些試劑，對於如何收集這些物品，我感到很困惑。不過現在你來了，我想我的問題也解決了。$B$B我需要這些東西:枯木食人妖的獠牙，枯木食人妖的醫藥包和一把暗影獵手的小刀。$B$B你能幫我找到這些嗎?枯木食人妖一般都在阿拉希高地的東南一帶出沒。', '幫避難谷地中的學徒克里汀收集10個枯木食人妖的獠牙，4個枯木食人妖的醫藥包和1把暗影獵手的小刀。', '', '去阿拉希高地找避難谷地的學徒克里汀。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 692 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (692, 'zhTW', '遺失的卷軸碎片', '密……密斯賴爾卷軸？！你要那東西幹什麼？它強大的魔法力量可以把密斯賴爾召喚到地面上來，那時候我們就有大麻煩了！$B$B也許……也許已經太遲了，也許她已經自由了。密斯賴爾可能正在為報復我們而聚集力量。如果是這樣，那你就必須掌握著這至關重要的卷軸！$B$B……太糟了，它被毀掉了。憤怒的元素生物偷走了卷軸，並將它撕成了碎片。現在它們又在為這些碎片爭鬥不休。$B$B如果你能蒐集那些碎片的話，也許我們還有希望將它修復成原來的樣子……', '把破損的卷軸碎片、弄皺的卷軸碎片和燒焦的卷軸碎片帶給迷失者塞爾杜林。', '', '去找荒蕪之地的迷失者塞爾杜林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 693 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (693, 'zhTW', '特雷萊恩的符咒魔杖', '你好啊， $N ，很抱歉我以前對你那麼凶……我可以斷定特雷萊恩的第一件寶物的所在:它在石拳大廳的考格雷什手裡。順便說一句，他已經可以使用冰爆術來教訓不聽話的手下，看來離他完全掌握魔杖力量的日子也已經不遠了。$B$B石拳大廳就在這裡的南邊，薩多爾大橋的東邊。從那個巨魔手裡把那根魔杖拿回來吧。$B$B在你回來之前，我要想想我們要怎樣解決激流堡的問題。', '幫避難谷地的斯奎爾圖找到特雷萊恩的符咒魔杖，並把它帶回來。', '', '去阿拉希高地找避難谷地的斯奎爾圖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 694 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (694, 'zhTW', '特雷萊恩的防禦', '休息好了嗎?$B$B我們的下一步計畫和激流堡的阿拉索之塔周圍的巨魔有關。我們必須首先開啟這座塔的防禦系統，當然，前提是你能活著到達存放那些物品的地方。為此，首先我們需要一些石拳薩滿經常攜帶著的寶石。他們把寶石從塔裡帶了出來，但他們沒有什麼機會佔有這些寶石了。$B$B從他們那裡弄一塊寶石，把它送去給克里汀─他能夠給寶石附魔，這樣一來，寶石就可以當鑰匙用了。', '找到一塊蒼藍瑪瑙石，把它交給避難谷地處的學徒克里汀。', '', '去阿拉希高地找避難谷地的學徒克里汀。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 695 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (695, 'zhTW', '學徒的魔法', '拿著寶石吧，$N。只要將寶石放置在塔基的任何一個支撐腳上，就能啟動阿拉索之塔的防禦。當你準備進入塔中尋找特雷萊恩的其餘物品時，就使用這顆寶石。$B$B祝你好運，我將在營地裡等你凱旋而歸。哦，對了，在你離開之前別忘了去和斯奎爾圖談談，他會告訴你一些你必須瞭解的細節。', '和斯奎爾圖談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 696 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (696, 'zhTW', '進攻高塔', '以下是你要找的東西:特雷萊恩的骨匣、特雷萊恩的寶珠和特雷萊恩的黑瑪瑙。$B$B所有這三樣東西應該都在塔中的箱子裡，你打開這些箱子應該不會有什麼問題，只是要當心那些巨魔就成。$B$B阿拉索之塔的防禦不會作用於那些巨魔，因此你必須時刻準備戰鬥。如果那些巨魔發現你在偷他們的東西，你就少不了一場惡戰。$B$B多加小心，祝你好運。', '找到特雷萊恩的骨匣、特雷萊恩的寶珠和特雷萊恩的黑瑪瑙，把它們交給避難谷地的斯奎爾圖。', '', '去阿拉希高地找避難谷地的斯奎爾圖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 697 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (697, 'zhTW', '馬林的要求', '把這封信送到暴風城去，讓馬林知道我和克里汀很快就可以回家了。對於你給我們的幫助，馬林一定會好好回報你的，$N，對於這一點我深信不疑。$B$B祝你旅途順利。', '將給大法師馬林的信交給暴風城法師區裡的大法師馬林。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 698 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (698, 'zhTW', '缺乏補給', '我正努力為我們在東邊海灘那裡的哨所收集一些補給品，托克卡爾已經盡了他的全力。但他又要值勤，又要為他的士兵們做飯，一天這麼下來就沒什麼時間了。$B$B他們很喜歡吃鹽齒鱷魚的肉，但我沒時間為他們再送去一批補給了。你能幫我這個忙嗎？$B$B鹽齒鱷魚幼崽的肉不如成年鱷魚的口感好，所以你別獵殺小鱷魚，等它們長大了再吃它們也不遲。', '給悲傷沼澤的托克卡爾帶去8塊新鮮的鹽齒鱷魚肉。', '', '去悲傷沼澤找蘆葦哨崗的托克卡爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 699 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (699, 'zhTW', '缺乏補給', '我們之所以被部署在這裡，是為了警戒在這片海岸附近出沒的魚人，以防它們——或者任何其它什麼東西——威脅到斯通納德，當然，要是他們太囂張了點的話，我們也會去給它們一些顏色看看。這工作可不輕鬆，我們幾乎很少有自由的時間，所以只好拜託你來幫忙了，當然，我是說如果你願意的話。$B$B加工得當的鹽齒鉗嘴鱷的爪子可以用來製作精良的武器，給我帶些它們的爪子回來，我就會送你一件精緻的武器作為酬謝。', '給悲傷沼澤的托克卡爾帶去6只鹽齒鉗嘴鱷的爪子。', '', '去悲傷沼澤找蘆葦哨崗的托克卡爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 700 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (700, 'zhTW', '國王的禮物', '啊，羅德隆的石頭真不賴，可惜那兒已經變成一片廢墟了。$B$B紀念碑完成了！我想國王陛下一定會滿意的。$B$B如果你願意的話，請替我去告訴國王陛下，紀念碑已經完成了。', '向鐵爐堡的國王麥格尼·銅鬚彙報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 701 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (701, 'zhTW', '迅猛龍的狡詐', '只要藉助一些特別的物品，我就能創造出一件注入了迅猛龍的狡詐力量的東西！這樣就應該能讓戈穆爾瞭解到我們新的能量，並重新找回潛藏著的勇士的力量！$B$B我需要迅猛龍的心臟來完成這件物品和法書。', '從高地獵獸龍身上獲取12顆迅猛龍的心臟，把它們交給托爾甘。', '', '去阿拉希高地的落錘鎮找托爾甘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 702 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (702, 'zhTW', '迅猛龍的狡詐', '拿著這顆寶珠，用它的能量來給戈穆爾灌入迅猛龍力量的精髓。這一定會讓他的精神備受鼓舞，並給予他新的生活目標。當他恢復正常之後，我們就可以向他說明部落現在的狀況，在我們永無止境的戰鬥中，這位偉大的戰士也將幫上大忙。', '把托爾甘的寶珠交給戈穆爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 703 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (703, 'zhTW', '燒烤禿鷹翅膀', '哦，當然，燒烤禿鷹翅膀是我的最愛！醬汁濃郁，肉香撲鼻，香味能把數公里外飢餓的野獸都給吸引過來！$B$B我有能做一頓美味佳餚的一切原料，呃……還差點禿鷲翅膀！$B$B如果你想嚐嚐我的手藝，就去幫我弄些禿鷲翅膀來。儘量多弄點，沒準我一高興就把烹飪方法一併教給你！', '給里格弗茲帶去4只禿鷲的翅膀。', '', '去荒蕪之地找巨牙谷的里格弗茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 704 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (704, 'zhTW', '埃格蒙德的命運', '埃格蒙德送來的最後一份報告讓我感到十分困惑，現在他死了，我就更難受了！他提到挖掘隊在奧達曼附近的挖掘場找到了一些“遠古的石罐”。我擔心是他找到的罐子影響了石顎怪，就像這裡發現的小石像一樣。$B$B我要你去找到那些罐子，把它們拿回來以供研究。到奧達曼挖掘場去收集那些罐子吧，完成之後再回到我這裡來。', '收集4個雕紋石罐，把它們交給洛克莫丹的勘察員基恩薩·鐵環。', '', '去洛克莫丹找鐵環挖掘場的勘察員基恩薩·鐵環。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 705 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (705, 'zhTW', '潛水採珍珠', '荒蕪之地是一個無比荒涼的地方，是兇殘的捕食者和食腐動物的樂園。這裡的一切都令人感到恐慌，尤其是對於我這樣的小個子哥布林來說。為了生存，我不得不機靈些！$B$B我知道閃光彈的製作方法，也常用它來嚇走野獸。不過，作為原料之一的藍珍珠粉快要用完了。你能不能幫我找些藍珍珠回來？當然我會給你足夠的報酬。$B$B呵呵，這個東西並不是那麼好找的，恐怕你得走不少的路了。我所需要的藍珍珠可以在暗礁海的牡蠣身上找到。$B$B對，就是位於荊棘谷的那個暗礁海。', '收集9枚藍珍珠，把它們交給荒蕪之地的里格弗茲。', '', '去荒蕪之地找巨牙谷的里格弗茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 706 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (706, 'zhTW', '黑龍之火', '作為費拉諾·鋼趾的學徒，我從他那裡學會了賦予武器強力魔法的特殊技能。我最後一次聽到他的訊息時，他正和從羅德隆過來的狩獵小隊合夥工作。$B$B我不能告訴你關於這種技術的太多細節，但可以告訴你必須要用黑龍血來完成這個附魔過程， 而且一定要是從黑色幼龍那仍在跳動的心臟中湧出的血液。我現在除了等待鐵爐堡的訊息以外無事可做，所以如果你能從萊瑟羅峽谷幫我帶一顆黑色幼龍之心回來，我就向你展示一下我的技術！', '為西格魯·鐵斧拿到一顆黑色幼龍之心。', '', '去找荒蕪之地的西格魯·鐵斧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 707 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (707, 'zhTW', '鐵環挖掘場需要你!', '$N。洛克莫丹的勘察員基恩薩·鐵環從他的挖掘場給我送來報告，說是需要為我們的另一項挖掘計畫外出搜集一些情報。我就知道這麼多了，如果你願意活動一下筋骨，就去和基恩薩·鐵環談談吧。', '和洛克莫丹鐵環挖掘場的勘察員基恩薩·鐵環談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 708 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (708, 'zhTW', '黑盒子', '這個黑色金屬箱的表面已經被嚴重破壞，似乎在酸液中浸泡過——它一定在那隻巨型禿鷲的肚子裡呆了很長的時間。$B$B翻轉過箱子之後，你發現箱底印著一個標記，標記下是一行字：$B$B“19號坦克 - 鐵爐堡攻城坦克旅”', '把這個黑盒子帶到鐵爐堡的軍事大廳去。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 709 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (709, 'zhTW', '化解災難', '天哪……天哪！厄運就要降臨了。它已經朝我而來了！厄運就要降臨了！$B$B不，我不能說……不能說出他們的名字，否則會被他們聽到的！但是，如果我們……如果我們對他們有更多瞭解的話……也許我們就可以知道如何擊敗他們！$B$B也許……$B$B到奧達曼去。不！我說過！你必須找到……找到雷烏納石板……對，找到它！別讓我再提到那個名字！$B$B它深藏在那裡，就在一個古代的箱子裡……這個箱子甚至比矮人族群的年代還要久遠……', '把雷烏納石板帶給迷失者塞爾杜林。', '', '去荒蕪之地找埃格蒙德的營地的迷失者塞爾杜林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 710 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (710, 'zhTW', '研究石元素', '在荒蕪之地，我停下了所有手頭的事情來專注於我的最新專案：元素禁錮鐐銬。$B$B這些鐐銬一旦完成，就可以讓法師們在更廣的範圍內召集更加強大的元素生物。首先，我需要些小石頭碎塊，來檢驗我最新的攻擊性咒語和小發明。$B$B你可以從西面那裡的次級石元素身上收集到這些碎片，能給我弄一些來嗎？', '收集10塊小石頭碎塊，把它們交給荒蕪之地的魯特維爾·沃拉圖斯。', '', '去荒蕪之地找漫塵盆地的魯特維爾·沃拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 711 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (711, 'zhTW', '研究石元素', '$N，你的能力超過了我所有學徒的總和。$B$B我所需的下一個部分需要花些功夫。只要你稍加留心，就能在石元素身上找到一些大石片。他們的身體更加龐大，因而會有足夠大的碎片來供我試驗。你可以在西邊遠一點的地方或者東南方的山地邊緣找到它們。$B$B不用太著急，測試你帶來的小石頭碎塊還需要花些時間。', '收集3塊大石片，把它們交給荒蕪之地的魯特維爾·沃拉圖斯。', '', '去荒蕪之地找漫塵盆地的魯特維爾·沃拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (712, 'zhTW', '研究石元素', '$N，我還需要從荒蕪之地的元素生物身上弄一些東西：巨型石元素身上的護腕。據我估測，那些護腕完全可以檢驗出我的鐐銬所具有的力量。$B$B我的占卜顯示，在西南邊有一批巨型石元素。我想起來了，那附近好像還有一些食人魔。$B$B給我帶5個護腕來，我想5個就足夠了。阿布總是放錯我的試劑和實驗品，這方面它的名聲可不太好。', '收集5個石縛護腕，把它們交給荒蕪之地的魯特維爾·沃拉圖斯。', '', '去荒蕪之地找漫塵盆地的魯特維爾·沃拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (713, 'zhTW', '至關重要的冷卻劑', '讓我來告訴你些有關冰霜之油的事情吧：沒有別的什麼東西能夠像它一樣防止發動機或者齒輪過熱。$B$B它的冷卻效能和潤滑效果無與倫比。不僅如此，它還有助於儲存附著在魔法物品上的魔力。$B$B我需要一小瓶冰霜之油以加強鐐銬的魔力，好讓它們足夠強大，不然我可沒法阻止那些被召喚來的“朋友們”對我們大開殺戒。$B$B我在奧特蘭克有一個名叫布洛金的哥布林朋友，他能教你製取冰霜之油的方法。', '找到冰霜之油，把它交給荒蕪之地的魯特維爾·沃拉圖斯。', '', '去荒蕪之地找漫塵盆地的魯特維爾·沃拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 714 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (714, 'zhTW', '發條式什麼什麼儀', '$N，你所做的一切都是超一流的。$B$B<魯特維爾的注意力顯然從工作中移開了>$B$B如果我們曾在卡拉諾斯見過，你隨時都可以來申請工作。$B$B哎呦！快抓住……對，那個。謝謝。$B$B我現在還需要一件東西。雖然是件小東西，但是也非常關鍵的東西，它就是精密的發條式同步協調陀螺儀。$B$B如果你能幫我找一個的話，我就能完成工作啦。', '給荒蕪之地的魯特維爾·沃拉圖斯帶去一個發條式同步協調陀螺儀。', '', '去荒蕪之地找漫塵盆地的魯特維爾·沃拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 715 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (715, 'zhTW', '盧希恩的藥水', '我想你為魯特維爾找的那些東西會不會給我們帶來什麼麻煩，$N。另一方面，你已經在幫助魯特維爾神聖的科學研究的過程中體現了超凡的才能，那麼幫幫我如何？$B$B我需要一瓶隱形藥水和一瓶治療藥水。如果他的進展一切順利，這兩件東西都必須及時到位。$B$B作為報酬，我會給你這個配方，它是我向魯特維爾求學時，在魯特維爾長期以來在荒蕪之地的研究成果的基礎上開發出來的。', '為荒蕪之地的盧希恩·槍穗找到一瓶次級隱形藥水和一瓶治療藥水。', '', '去荒蕪之地找漫塵盆地的盧希恩·槍穗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 716 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (716, 'zhTW', '有備無患', '我知道魯特維爾瘋狂起來會有多麼危險，你最好讓我給你製作一些裝備以防萬一。也許它能保護你免受魯特維爾新發明的折磨。$B$B我一直都在研究那些你給他找來的石頭，所以我想我能造出一些不錯的護腕來供你使用。嗯，它們當然都是附有魔法的。$B$B我只需要一些鐵匠打造的青銅花紋護腕就可以幫你造出附魔的護腕了。', '給荒蕪之地的盧希恩·槍穗帶去一些青銅花紋護腕。', '', '去荒蕪之地找漫塵盆地的盧希恩·槍穗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 717 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (717, 'zhTW', '大地的震顫', '顯然，我們不能保證黑龍布萊克拉什和赫瑪圖斯仍能被囚禁在萊瑟羅峽谷裡。大批黑龍盤踞在那裡的現狀以及食人魔試圖偷走大地印章的事實說明後面將會有更可怕的事情發生。$B$B黑龍的監獄由三塊符石維持著，只有使用大地印章才能得到它們，而那些符石就是打破封印的關鍵。$B$B$n……我們要確保那些黑龍的夢想永遠無法成真。', '用大地印章啟用鑽石柱、瑪瑙石柱和紫水晶石柱並拿到三顆符石。$B$B把符石放在大地封印上，釋放黑龍布萊克拉什和赫瑪圖斯。$B$B殺了這兩條黑龍，把布萊克拉什的鎖鏈、赫瑪圖斯的鎖鏈和大地印章交給加瑞克。', '', '去荒蕪之地找鐵趾挖掘場的加瑞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 718 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (718, 'zhTW', '飢腸轆轆', '在匆忙撤出奧達曼挖掘場的途中，我們不得不丟棄了很多補給物資，那些柯什營地裡的食人魔像兀鷲看見了腐爛的屍體一樣瘋狂地掠奪我們扔掉的物資，呃，那些傢伙聞起來也和曬了好幾天的屍體沒什麼區別……$B$B不管怎麼說，他們搶走了我們裝著武器的馬車，而且現在……現在的狀況實在是隻能用窘迫兩個字來形容了——我們現在幾乎什麼吃的都找不到了。$B$B就連醃菜也要吃光了，你看……能不能幫我們弄點什麼吃的來？', '幫西格魯·鐵斧找回補給箱。', '', '去找荒蕪之地的西格魯·鐵斧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 719 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (719, 'zhTW', '矮人的工具', '你好，$c。千萬要小心四周。這裡到處都是黑鐵矮人，似乎都是屬於暗爐部族的。$B$B他們剛剛襲擊了我們的挖掘場……殺死了那裡幾乎所有的人，包括我的老闆鐵趾格雷茲，只有我僥倖逃了出來。$B$B挖掘場在這裡的北面，我想找回我們的一些物資，尤其是我的好運鋤。$B$B你能幫幫我嗎？如果找不到其它的，至少幫我找回我的鋤頭吧。', '找到雷杜爾的好運鋤，把它交給鐵趾挖掘場南邊的勘察員雷杜爾。', '', '去找荒蕪之地的勘察員雷杜爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 720 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (720, 'zhTW', '一線希望', '<在地圖上有一行用粉筆潦草寫下的文字>$B$B“雷杜爾，$B他們把我帶到了奧達曼，請速來援助。$B——鐵趾”', '找到勘察員雷杜爾，告訴他鐵趾格雷茲還活著。', '', '去找荒蕪之地的勘察員雷杜爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (721, 'zhTW', '一線希望', '$N，你能找到他嗎？你能在奧達曼找到鐵趾嗎？$B$B如果那些卑鄙的暗爐矮人將他抓為人質是為了獲得他掌握的有關泰坦的資訊的話，鐵爐堡就有大麻煩了。$B$B很久以來，黑鐵矮人一直在尋找可以製造出威力更大的作戰傀儡的魔法。鐵趾也在尋找這樣的魔法，但他的目的僅僅是為了阻止他們。$B$B估計在套出重要情報之前，他們是不會殺了鐵趾的。你要抓緊時間，儘快救出鐵趾！', '在奧達曼找到鐵趾格雷茲。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (722, 'zhTW', '鐵趾的護符', '你很勇敢……<咳嗽>……為了我來到奧達曼，$c。$B$B如果你真要幫助我……那麼……<咳嗽>……你就必須找到……幫我找到我的護符。$B$B它在……馬格雷甘·深影的手裡。他就在這附近……肯定在這片廢墟上。如果你不能阻止他的話，那枚護符將會引導他……<咳嗽>……找到卷軸。$N，就看你的了。$B$B請……拿到那枚護符。$B$B卷軸一旦落入黑鐵矮人的手裡……一切就都太晚了……', '找到鐵趾的護符，把它交給奧達曼的鐵趾。', '', '去找奧達曼的鐵趾格雷茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (723, 'zhTW', '鐵趾的遺願', '<鐵趾捂著傷口，老半天才緩過勁來，他接著說道>$B$B找到雷杜恩，$N……把護符交給他。<猛烈的咳嗽>他……<咳嗽>知道該怎麼辦。雷杜恩知道我一直在尋找我們種族的起源，他也……<咳嗽>知道阻止暗爐部族是我的使命。不能讓他們找到卷軸……<咳嗽>', '把鐵趾的護符交給荒蕪之地的勘察員雷杜恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (724, 'zhTW', '鐵趾的遺願', '好吧……誰知道下一步該做些什麼？$B$B史學家卡尼克！沒錯！$B$B他就在鐵爐堡裡。我想我們可以從他那裡尋求一些幫助。鐵趾和他曾經共同在奧達曼挖掘古代神器，估計暗爐矮人已經對他們的底細瞭如指掌了。$B$B去把鐵趾的不幸遭遇告訴卡尼克，然後把護符交給他——他會告訴你該怎麼辦。', '把鐵趾的護符交給鐵爐堡的史學家卡尼克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 725 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (725, 'zhTW', '亡者的警告', '$N，你趕快去找顧問貝爾格拉姆，把你看到的一切都告訴他，問問他我們下一步該怎麼做。這封信會讓他了解的訊息。$B$B與此同時，我會和鐵趾的亡靈交談，也許他所知道的事情能夠幫助我們解決那幫暗爐部族的傢伙帶來的麻煩。讓我們祈禱吧。', '找到顧問貝爾格拉姆，把便箋交給他。', '', '去找鐵爐堡的顧問貝爾格拉姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (726, 'zhTW', '亡者的警告', '<顧問貝爾格拉姆讀到信的結尾，他的眼睛瞪大了好一會兒。>$B$B哎喲，這真是太可怕了。$B$B$N，你回去告訴史學家卡尼克，趕快以國王的名義對這一事件採取行動。他必須制止暗爐矮人在荒蕪之地的所作所為！', '和史學家卡尼克談一談。', '', '去找鐵爐堡的史學家卡尼克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (727, 'zhTW', '遠赴鐵爐堡', '石板說明了不少問題，但這還不夠，遠遠不夠！$B$B有這麼一本書，它是雅格因在若干年前寫的筆記，上面記載著一些……我想方設法要避開的人……他們在世界各地都珍藏著這本書的複製本。而他們中最有學問的人也一直在研究它，因為它包含著極其豐富的知識……可以讓我們免遭災難的知識！$B$B到鐵爐堡去找葛利·硬骨，把徽章拿給他看看，他就會相信你是他們中的一員。向他要到雅格因的筆記……然後馬上把它交給我！', '把戰錘印章交給鐵爐堡的葛利·硬骨。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (728, 'zhTW', '遠赴幽暗城', '石板說明了不少問題，但這還不夠，遠遠不夠！$B$B有這麼一本書，它是雅格因在若干年前寫的筆記，上面記載著一些……我想方設法要避開的人……他們在世界各地都珍藏著這本書的複製本。而他們中最有學問的人也一直在研究它，因為它包含著極其豐富的知識……可以讓我們免遭災難的知識！$B$B到幽暗城去找看守者貝爾杜加，把徽章拿給他看看，他就會相信你是他們中的一員。向他要到雅格因的筆記……然後馬上把它交給我！', '把戰錘印章交給幽暗城的看守者貝爾杜加。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (729, 'zhTW', '健忘的勘察員', '首席考古學家杜瑟·灰鬚派我在偉大的勘察員雷姆塔維爾的指導下進行工作，這對我來說是無上的榮譽。在鐵爐堡學院時，每個人都知道雷姆塔維爾有許多偉大的發現。不過這位偉大的勘察員實在是……嗯……有些健忘……他常常對周圍的一切都渾然不覺。我們剛剛發現了一座大型的古代城鎮。可怕的魔像從地下蜂擁而出，佔據了那裡。不過雷姆塔維爾似乎還沒有發現這一點，我跑回奧伯丁就是為了找人去救他。請到南邊去一趟，看看偉大勘察員是否還一切安好!', '到南邊去一趟，看看勘察員雷姆塔維爾現在處境如何。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (730, 'zhTW', '黑海岸的麻煩事', '很高興見到一個對我們偉大的考古事業有如此濃厚的興趣的$c。我們的工作經常被聯盟中的其他朋友當成是矮人的休閒活動而不被理解，但是很多人都沒有意識到，最近在卡茲莫丹一帶的發現證實，一股強大的勢力正威脅著從羅德隆到卡林多的整個世界。我很擔心那些到黑海岸去考古的兄弟們，他們有好幾個星期都音信全無了。到奧伯丁去找找看有沒有關於他們的線索吧。', '到奧伯丁去尋找矮人挖掘隊的線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (731, 'zhTW', '健忘的勘察員', '好吧，那麼，霍莉...哦，不對，你不是霍莉。霍莉去哪兒啦?$B$B不說這個了，那不是我們要討論的話題。我們必須找到那把石刷...我是說神秘的化石!我們必須找到化石。達納蘇斯的探險者協會希望能看到我的工作進展情況。$B$B如果你準備好了，就和我說一聲，我們去尋找那把刷子...我是說化石!我們要找到一些能讓協會滿意的東西。$B$B你準備好了嗎?', '在勘察員雷姆塔維爾搜尋神秘化石的時候保護他，然後回到奧伯丁的考古學家霍莉那裡。', '護送勘察員雷姆塔維爾', '去黑海岸找奧伯丁的考古學家霍莉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 732 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (732, 'zhTW', '大地的震顫', '我聽西格魯說，你在過去幾天幫了他的大忙。現在我也需要你的幫助。我的主人，肯瑞託的大法師克拉蘇斯派我來結束萊瑟羅峽谷的混亂局面。$B$B我不能透露這次任務的確切性質以及我要完成的使命，但是這個任務真的非常重要。$B$B有一夥四處遊蕩的食人魔偷走了一件名叫大地印章的東西，我必須要把它拿回來。如果你能幫我找到它，我就讓你知道更多的訊息。', '幫加瑞克取回大地印章。', '', '去荒蕪之地找鐵趾挖掘場的加瑞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 733 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (733, 'zhTW', '蒐集行動', '如果不能弄到一些物資來建構防禦工事和其它的必要設施，我們在這裡的處境就會非常糟糕。我發現這個地區的食人魔居然有許多金屬碎片，也許傳說在荒蕪之地出沒攻城坦克不久之後也會出現……$B$B無論如何，勘察員對我們營地的狀況非常擔憂，所以我要儘早開工。$B$B食人魔的主營地就在火山洞穴，從這裡往西一直走就能找到。', '幫西格魯收集7塊金屬碎片。', '', '去找荒蕪之地的西格魯·鐵斧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 734 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (734, 'zhTW', '不祥的感覺', '太好啦，太好啦。$B$B<魯特維爾看了你一會兒，又去擺弄他的鐐銬了>$B$B去找盧希恩吧，$N。跟他說我需要一個5號齒輪。你能把它拿來給我嗎？', '和荒蕪之地的盧希恩·槍穗談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 735 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (735, 'zhTW', '星，手，心', '雅格因的筆記？你要它幹什麼？沒關係，我不該問這個。$B$B我會幫你的，因為我這裡還有一本。我們得互相幫助，對不對？這樣我們才能各自獲利。$B$B我需要三件寶物，把它們給我拿來，我就給你那本筆記。$B$B我不會說出它們的名字，因為可能有人正在偷聽，不過我可以把這幾個名字寫下來。', '找齊葛利·硬骨的便箋上列出的東西，然後把它們交給鐵爐堡的葛利·硬骨。', '', '去鐵爐堡的荒棄的洞穴找葛利·硬骨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 736 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (736, 'zhTW', '星，手，心', '你需要雅格因的筆記?一整本?當然……當然我會幫助你，我的$g兄弟:姐妹;。$B$B但你也得幫我。$B$B我需要三件威力強大的物品，把這些物品給我找來，筆記就是你的了。$B$B我不能把它們的名字說出來，不過我可以給你寫下來。$B$B把這個單子上的東西找來，如果你能完成這個任務，那麼你就有能力接到更重要的工作。', '把貝爾杜加的便箋上列出的東西帶給幽暗城的看守者貝爾杜加。', '', '去找奧特蘭克山脈的看守者貝爾杜加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 737 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (737, 'zhTW', '禁斷的知識', '$n，我這裡有你想要的筆記，我想不需要我再提醒你要保管好它了吧？特別是絕對不要讓它落入敵人之手。$B$B這本書裡記錄了很多真相……$B$B……可以毀滅你的真相。', '把雅格因的筆記交給塞爾杜林。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 738 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (738, 'zhTW', '尋找埃格蒙德', '勘察員埃格蒙德曾是荒蕪之地的挖掘場負責人，就是西南邊的那座挖掘場。我說「曾是」，是因為……嗯，最近幾週我都沒有得到他的任何消息。請你幫我找到埃格蒙德並拿到他的報告。我最後一次得到的消息是:埃格蒙德在荒蕪之地最南邊的挖掘場─那是苦痛堡壘附近的一個不起眼的小地方。你先去那裡找找看吧。', '找到埃格蒙德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 739 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (739, 'zhTW', '莫達洛克', '埃格蒙德留下的足跡表明他是從西邊走過來的。從沙石上的斑斑血跡不難看出，矮人埃格蒙德爬行了好一段距離。$B$B爬到這裡的時候，他終於被死神帶走了。$B$B經過仔細察看，你在旁邊的沙石中發現了幾個潦草寫下的字跡：“莫達洛克”。$B$B字跡就在埃格蒙德的手邊。', '幹掉殺害埃格蒙德的兇手：莫達洛克。$B$B順便殺掉12個石窟斷骨者。$B$B然後向洛克莫丹的勘察員基恩薩·鐵環報告。', '', '去洛克莫丹找鐵環挖掘場的勘察員基恩薩·鐵環。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 740 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (740, 'zhTW', '暫無內容', 'This quest will take players into the Searing Gorge.$B$BStay tuned...', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (741, 'zhTW', '健忘的勘察員', '勘察員雷姆塔維爾要把神秘的化石送給達納蘇斯的探險者協會?可是我不太想把他一個人留在這裡。$B$B給你，$n，把這塊神秘的化石交給達納蘇斯的首席考古學家杜瑟·灰鬚。', '把神秘的化石交給達納蘇斯的首席考古學家杜瑟·灰鬚。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 742 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (742, 'zhTW', '梣谷狩獵', '年輕的冒險者們，注意了！梣谷的野獸正在等著你們！$B$B部落在貧瘠之地以北的區域建立了強大的基地。我們的兩個前哨站——碎木崗哨和佐拉姆海岸哨崗——正在努力地為部落的榮耀而戰！想要證明自己能力的勇士就到那兒去吧。碎木崗哨位於貧瘠之地的正北方，塞娜尼·雷心正在那裡招募願意參與梣谷狩獵中的冒險者！', '與梣谷碎木崗哨的塞娜尼·雷心談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 743 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (743, 'zhTW', '風怒鷹身人', '謝謝你抽時間來和我談話， $N 。我是盧爾，既是一個 $C ，也是一個導師。$B$B如果你想在莫高雷之外經歷更多冒險的話，現在正是讓你接受更多考驗的時候了。$B$B如果你想測試自己的能力，就去東南方找風怒鷹身人作戰吧。他們駐紮在山邊遠離大路的地方。$B$B鷹身人是我們的天敵，對你來說，和他們戰鬥會是個不錯的考驗。', '給血蹄村的盧爾·鷹爪帶回8隻風怒鷹身人的爪子。', '', '去莫高雷找血蹄村的盧爾·鷹爪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 744 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (744, 'zhTW', '準備典禮', ' $N ，我的兄弟很快就要去面見血蹄酋長了，我要為他做一個頭飾，這對我來說是一種榮耀。$B$B在我處理這些皮革的時候，你能不能幫我一個忙?我沒有時間去收集足夠的羽毛，不知道你能否幫助我去收集一些呢?$B$B你應該可以在雷霆崖北面和西北面的鷹身人身上找到尺寸合適的羽毛。我需要6片蒼藍色的和6片古銅色的羽毛來完成我的頭飾。', '收集6根蒼藍色的羽毛和6根古銅色的羽毛，把它們交給雷霆崖的伊恩·鷹爪。', '', '去找雷霆崖的伊恩·鷹爪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 745 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (745, 'zhTW', '土地之爭', '這片土地上有很多紛爭， $N 。我希望你不會像我一樣經歷那麼多的戰爭，不過我還是希望你去做一件事，讓你可以瞭解到，一個看似不值一提的小小威脅如果不加制止的話，會對我們的領土帶來多大的危害。$B$B白鬃豺狼人已經在西邊的一個洞穴中和血蹄村的南邊紮了營。我們曾試圖和他們交流，卻被他們無禮地拒絕了，而且他們還大肆屠殺莫高雷的野生動物。$B$B現在語言已經不能解決問題了，我們必須有所行動。', '殺死10個白鬃製革工、8個白鬃剝皮工和5個白鬃偷獵者，然後回到血蹄村向貝恩·血蹄覆命。', '', '去莫高雷找血蹄村的貝恩·血蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 746 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (746, 'zhTW', '矮人的挖掘場', '有些矮人正準備在西北邊建立一個挖掘點。他們認為地底下埋藏著某些秘密，事實也的確如此，但挖空和破壞土地是不可能理解大地的教誨。$B$B收集矮人的挖掘工具，毀掉那些東西，然後把矮人損壞的工具帶來給我。$B$B你可以在熔爐邊破壞那些工具。你可以在雷霆崖找到熔爐，但任何一個熔爐 -- 甚至是矮人營地的熔爐 -- 都可以用來破壞工具。', '收集5個勘察員的十字鎬。在鐵匠鋪砸碎這些勘察員的十字鎬。把5件損壞的工具交給血蹄村的貝恩·血蹄。', '', '去莫高雷找血蹄村的貝恩·血蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 747 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (747, 'zhTW', '開始狩獵', '歡迎來到納拉其營地，$N 。你來到這裡的消息很快就傳遍了部族。或許很快有一天你會被迎去雷霆崖上的大城市裡，但首先，你必須先向我們證明你的能力。$B$B我們這些生活在紅雲臺地上的 $R 無疑對自己優秀的狩獵技術最為自豪，當然， $R 只為生存需要和競技而狩獵。我們庫存的肉已經不多了，另外我們還需要羽毛來做衣服。現在去獵殺附近的平原陸行鳥來給村莊提供補給吧，同時你也可以借此證明自己的能力。', '納拉其營地的格盧爾·鷹風要求你帶給他7根平原陸行鳥的羽毛和7塊平原陸行鳥肉。', '', '去莫高雷找納拉其營地的格魯爾·鷹風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 748 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (748, 'zhTW', '毒水', '那些哥布林和他們的爪牙污染了我們神聖的水井!我們必須制止他們!$B$B要想淨化所有的水井，我得先製造出相應的淨化圖騰，然後你把圖騰拿到水井那兒去完成淨化的儀式。$B$B首先，我們給冬蹄之井製作一個淨化圖騰，這需要大地的幫助。去獵捕一些草原狼和成年平原陸行鳥，把它們的爪子帶回來給我，它們就在西南方活動。', '收集6隻草原狼的爪子和4隻平原陸行鳥的爪子，把它們交給血蹄村的莫爾·雷角。', '', '去莫高雷找血蹄村的穆爾·雷角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 749 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (749, 'zhTW', '被破壞的貨車', '幾天前，我們在石牛湖北岸發現了有一個被重兵保護著的風險投資公司的馬車。我們在先前的戰鬥裡已經失去了兩個同伴，所以我們就把怒氣傾瀉在這輛馬車身上，速戰速決地把它給摧毀了。我們沒去管他們的儲物箱，滿以為一把火就可以把這些東西和馬車一起燒成灰。不過有人在那輛熊熊燃燒的貨車附近看見了風險投資公司的搶救人員，那些木箱可能沒被燒掉。也許你可以去那輛貨車旁，看看木箱裡面到底是什麼。', '摩林·雲行者要你去查看被破壞的貨車附近的補給木箱裡有什麼東西。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 750 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (750, 'zhTW', '繼續狩獵', '善於狩獵的 $R 從不僅僅將他的獵物看作戰利品，這些生活在平原上的野獸對我們的生存有著極為重要的意義。如果你能帶回一些珍貴的山獅皮的話，就會令部族裡的長老們對你刮目相看。你可以在南邊的山區找到它們。$B$B我們的孩子需要衣服，部族裡的帳篷也需要維修了。', '納拉其營地的格盧爾·鷹風要求你帶給他10張山獅皮。', '', '去莫高雷找納拉其營地的格魯爾·鷹風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 751 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (751, 'zhTW', '被破壞的貨車', '撬開蓋子之後，你發現了堆的滿滿的礦石，這又一次證明了風險投資公司確實在莫高雷地區有採礦活動。在礦石的最上面有一捆文件。$B$B你可以依稀聽見東部丘陵的頂部傳來叮叮噹噹的聲音，還可以看見從一大堆營火上升起的濃煙。', '把風險投資公司文件交給血蹄村附近的摩林·雲行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 752 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (752, 'zhTW', '一件瑣事', '我們部族的所有成員都過著完美和諧的生活，我們一起勞作，一起生活。部族中的每個成員都對其他人負有義務，並且我們總是將這些義務放在首位。現在我需要你幫我做一件麻煩的事情。我的母親今天早上去納拉其東南方的水井中取水，她已經去了很久了。你能不能替我去看看?部族裡的事務讓我實在抽不開身。', '鷹風酋長要求你去納拉其營地東南方的水井處尋找他的母親。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 753 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (753, 'zhTW', '一件瑣事', '我這一生也算是經歷了不少磨難，走了不少路，現在我這一把老骨頭也沒什麼力氣啦。我仍然在為部族盡力，但有些時候，我還真感覺有些力不從心。$B$B不過，你這 $C 似乎是正想找點什麼事情做做呀。正好，讓我來看看你的體力如何吧。把水井旁的這個水罐交給我兒子，他就在納拉其營地裡。$B$B記住，即使是最瑣碎的小事，只要你做得夠好，也能獲得長老們的首肯。', '在井邊拿一隻水罐。', '', '去莫高雷找納拉其營地的鷹風酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 754 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (754, 'zhTW', '淨化冬蹄之井', '我已經做好了可以淨化冬蹄之井的圖騰。現在你就把它拿到那兒去完成淨化儀式。冬蹄之井就在東南邊，有許多哥布林把守著那裡!$B$B這不是個簡單的任務，不過如果我們想要重新使用那裡的水，就必須得這麼做。$B$B祝你好運， $N 。', '用冬蹄之井淨化圖騰為冬蹄之井完成淨化，然後回來見莫爾·雷角。', '淨化冰蹄之井', '去莫高雷找血蹄村的穆爾·雷角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 755 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (755, 'zhTW', '大地之母祭儀', '你願意為納拉其的牛頭人做這樣瑣碎的小事，同時又渴望學習新的知識，這足以說明你有著高貴的品質，$n。我相信總有一天你會成為一位在雷霆崖赫赫有名的$c。不過在那之前，你必須首先完成大地之母祭儀，這個偉大的傳統共由三個不同的試煉組成。第一個試煉是力量之祭儀。去找灰舌先知，告訴他是鷹風酋長派你去的。翻過納拉其營地正南方的山後，你就可以找到他的居所了。', '找到居住在納拉其營地正南方山中的灰舌先知。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 756 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (756, 'zhTW', '雷角圖騰', '要製作雷角之井淨化圖騰，你必須先去收集莫高雷平原上的肉食動物的爪子。去捕獵草原捕食者和平原獅，然後把它們的爪子帶回來見我。$B$B它們就在這裡的東邊和西邊活動。', '收集6個草原捕食者的爪子和6個平原獅的爪子，把它們帶給莫爾·雷角。', '', '去莫高雷找血蹄村的穆爾·雷角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 757 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (757, 'zhTW', '力量祭儀', '大地之母祭儀對於每一個想要在雷霆崖得到尊重的年輕 $R 來說都是非常重要的。$B$B但在那之前，你必須先通過力量祭儀的試煉。在這個試煉中，你必須通過殺死部族的敵人來證明你的勇猛。$B$B生活在東邊的刺刃峽谷中的刺背野豬人侵佔了我們部族不少的土地，他們偷襲我們的狩獵小隊，還在晚上到村子裡來偷東西。$B$B殺死他們，展示出你的英勇無畏吧。拿著它們的腰帶去見納拉其營地的酋長，他將證明你通過了試煉。', '殺掉刺刃峽谷的刺背野豬人並帶回8條刺背腰帶，把它們交給納拉其營地的鷹風酋長。', '', '去莫高雷找納拉其營地的鷹風酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 758 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (758, 'zhTW', '淨化雷角之井', '圖騰已經準備好了， $N 。這一次還是由你來完成淨化儀式。$B$B到村莊北面的雷角之井去，用雷角之井淨化圖騰完成淨化儀式，然後再回來找我。$B$B願大地之靈指引你。', '在雷角之井使用雷角之井淨化圖騰，然後回來見莫爾。', '淨化雷角之井', '去莫高雷找血蹄村的穆爾·雷角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 759 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (759, 'zhTW', '蠻鬃圖騰', '還剩下一口井需要淨化，它是以蠻鬃氏族的名字命名的。要想淨化這口井，你必須從大地上尋找一種兇猛的肉食動物的牙齒，那就是草原狼前鋒的牙齒。去北邊尋找草原狼前鋒，拿到我要的東西之後再回來。$B$B這些草原狼前鋒經常在雷霆崖的山腳下遊蕩。', '收集8顆草原狼前鋒的牙齒，把它們交給血蹄村的莫爾·雷角。', '', '去莫高雷找血蹄村的穆爾·雷角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 760 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (760, 'zhTW', '淨化蠻鬃之井', '你淨化冬蹄之井和雷角之井的事蹟已在魂靈之間被廣為傳誦，年輕的 $N 。我也做好了蠻鬃之井淨化圖騰，接下來就是你最後一個任務了。$B$B蠻鬃之井在雷霆崖的北面，到那裡完成淨化儀式吧，拯救這片被哥布林污染的土地，讓這片土地上再次流動甘甜純淨的井水!', '在蠻鬃之井使用蠻鬃之井淨化圖騰，然後回來見莫爾·雷角。', '淨化蠻鬃之井', '去莫高雷找血蹄村的穆爾·雷角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (761, 'zhTW', '獵捕猛鷲', '猛鷲是一種狡猾無比、很難獵捕的鳥。收集猛鷲的羽毛可以證明一個獵手的智慧和決心。$B$B如果你想接受這個任務，就去平原上獵捕猛鷲吧。$B$B把它們的羽毛帶給我，為你的氏族贏得榮譽。$B$B猛鷲在莫高雷的任何地方都能找到，不過要發現它們，你得有銳利的眼睛;要捕捉它們，你得有靈活的手腳。', '收集8根猛鷲的羽毛，把它們帶給血蹄村的哈肯·風之圖騰。', '', '去莫高雷找血蹄村的哈肯·風之圖騰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (762, 'zhTW', '邪惡的使者', '拉格納羅斯派因弗努斯大使到苦痛堡壘去監督暗爐矮人在奧達曼挖掘神器的工作。$B$B我們的同胞已經遭受了慘重的傷亡，然而這樣的情況仍然在繼續。我不願去猜測他們會找到多少強大的神器並用它們來對付鐵爐堡。$B$B我們的目的很簡單，$c。回到荒蕪之地去，幹掉因弗努斯大使。在除掉了這個威脅之後，把你完成任務的證據交給顧問貝爾格拉姆。$B$B現在馬上出發吧。', '殺死苦痛堡壘中的因弗努斯大使，把證明他已死亡的信物交給鐵爐堡的顧問貝爾格拉姆。', '', '去找鐵爐堡的顧問貝爾格拉姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 763 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (763, 'zhTW', '大地之母祭儀', '要想繼續大地之母祭儀，你必須先通過兩個小試煉。現在也正好是你去積累積累經驗的時候了，$n。$B$B到血蹄村去找那裡的酋長，凱恩之子貝恩·血蹄吧。你可以在那兒繼續你的冒險歷程並得到雷霆崖的長老們的承認。$B$B把這個圖騰帶給貝恩。他會讀懂我刻在上面的符號，並幫助你繼續修行。$B$B順著這條從納拉其營地通向外面的路快點出發吧，千萬別迷路了。', '順著離開納拉其營地的路將鷹風圖騰帶給血蹄村的貝恩·血蹄。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 764 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (764, 'zhTW', '風險投資公司', '這就解釋了為什麼風險投資公司在不斷往莫高雷地區增派職員和設備。這些哥布林……他們的公司擴張得太快了。就像他們自己所說的那樣，只要給哥布林一點甜頭，你就能聽到他們打算盤的聲音。$B$B這些小東西實在是太貪婪了。不過我們 $R 決不會讓他們在我們的領土上為所欲為。到他們的礦坑去，給他們點顏色看看，那個礦坑就在被破壞的貨車東北方。', '血蹄村的摩林·雲巡者要你去殺死14個風險投資公司工人和6個風險投資公司主官。', '', '去找莫高雷的摩林·雲行者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 765 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (765, 'zhTW', '菲茲普羅克主管', '根據你從箱子裡拿來的文件可以看出，風險投資公司已經制定了很多把我們從這兒趕走的計畫，然後他們就能隨心所欲地掠奪我們的土地了。$B$B他們為了利潤居然可以墮落到這種程度，這簡直讓我感到厭惡和驚駭。我們要除掉這個陰謀的策劃者，他就是菲茲普羅克主管。你可以在被破壞的貨車以東的風險投資公司礦坑裡找到他，把他的筆記板帶給我，讓我們看看有沒有什麼有價值的東西。', '殺掉菲茲普羅克主管，把他的筆記板帶給血蹄村的摩林·雲巡者。', '', '去找莫高雷的摩林·雲行者。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 766 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (766, 'zhTW', '馬茲拉納其', '我祖父曾講述過他和一隻叫馬茲拉納其的陸行鳥戰鬥的故事，說起過它那邪惡的紅眼睛，剃刀般鋒利的爪子，只要被它咬一口，你就會身中劇毒。$B$B在我穿越平原的時候，正巧遭遇了它，肩膀被它咬了一口。它比我祖父所說的還可怕!我需要一些東西來幫我解毒:一顆狼心，獅子的腿骨，平原陸行鳥的鱗片和猛鷲的胃。$B$B快點，我快要不行了。', '收集草原狼的心臟、平原獅的腿骨、平原陸行鳥的鱗片和猛鷲的胃各一份，把它們交給血蹄村的茂爾·祈雨。', '', '去莫高雷找血蹄村的茂爾·祈雨。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 767 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (767, 'zhTW', '幻象祭儀', '作為大地之母儀式之一的幻象儀式可以指引你最終贏得雷霆崖長老們的尊重。我們早已認識到，土地就是我們最神聖的生命之本。如果你準備好要進行幻象儀式的話，就得去和村裡的精神領袖札爾曼·雙月談話。', '和血蹄村的札爾曼·雙月談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 768 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (768, 'zhTW', '收集皮革', '你好，年輕的 $R 。我從你的眼中看到了你重回原野捕獵的渴望。希望你能為你的氏族帶來榮耀!$B$B我擅於利用各種獸皮來為雷霆崖的居民製作護甲和衣物。$B$B如果你能幫我搞到一些獸皮的話，那我就可以用它們來為你製作一些你需要的東西。', '收集12塊輕皮，把它們交給雷霆崖的維爾倫·陸行者。', '', '去找雷霆崖的維爾倫·陸行者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 769 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (769, 'zhTW', '科多獸皮包', '莫高雷的科多獸強壯而兇猛，它們的這些特質備受我們尊敬。如果你善於皮革加工，而且希望獲得製作科多獸皮包的知識，那就給我弄點材料來吧。$B$B弄些材料來，我就會把我的手藝傳授給你。', '給雷霆崖的維爾倫·陸行者帶去4塊輕皮和4條粗線。', '', '去找雷霆崖的維爾倫·陸行者。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 770 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (770, 'zhTW', '惡魔之傷', '鬼嚎那粗糙的毛皮上還留著一個可怕的傷口，是在它與燃燒軍團的戰鬥中留下的。$B$B也許你應該把鬼嚎的死訊告訴血蹄村裡的什麼人……', '去打聽打聽誰聽說過鬼嚎。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 771 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (771, 'zhTW', '幻象祭儀', '要想通過幻象祭儀，你必須先找到製作先知之水的試劑。$B$B我需要一些水井石，你可以在莫高雷一帶的水井附近找到它們。另外，你還得在這周圍的大樹下面找到一些琥珀顆粒。$B$B這兩種東西都具有強大的元素力量，把它們結合起來，用部族之火點燃之後，你可以看到一個幻象。追隨它，它就會引領你進入這個神聖使命的下一個階段。', '收集2塊水井石和2個琥珀顆粒，把它們帶給血蹄村的札爾曼·雙月。', '', '去莫高雷找血蹄村的扎爾曼·雙月。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 772 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (772, 'zhTW', '幻象祭儀', '現在，我把神聖的先知之水交給你。$B$B準備好了之後，就去部族之火旁把水喝下，然後稍等片刻，一個幻象就會出現在你的眼前。$B$B你必須立刻決定是否要追隨這個幻象……', '在血蹄村的部族之火前將先知之水喝下，當幻象出現之後跟隨它。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 773 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (773, 'zhTW', '智慧祭儀', '要讓雷霆崖的資深長者接受你，你就必須再完成大地之母祭儀的下一個階段:智慧祭儀。你已經通過了幻象祭儀，赤色石的先祖之魂會祝福你的，只有那些喝過先知之水的人才能得到這種祝福。向雷霆崖的東面去，到赤色石尋找先祖之魂吧。', '到雷霆崖東邊的赤色石去和先祖之魂談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 774 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (774, 'zhTW', '<UNUSED>', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 775 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (775, 'zhTW', '雷霆崖之旅', '任何能夠完成大地之母祭儀的$r都可以贏得整個雷霆崖的尊重。你的最後一個任務是去見見我們的偉大首領凱恩·血蹄，他就住在雷霆崖最高的那座臺地上。', '和雷霆崖的凱恩·血蹄談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 776 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (776, 'zhTW', '大地之母祭儀', '你已經通過了大地之母祭儀，在雷霆崖贏得了你自己的一席之地。$B$B不過要維持你努力爭取到的地位，你還必須不斷證明自己的價值。$B$B我們生來就是獵手， $N 。在莫高雷城下有一隻非常強大的科多獸，我們稱它為阿蘭其亞。把它的角帶來，向我證明你追蹤和捕獵的能力。', '雷霆崖的凱恩·血蹄要你將阿蘭其亞的角帶給他。', '', '去莫高雷找雷霆崖的凱恩·血蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 777 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (777, 'zhTW', '不祥的感覺', '好吧，拿去吧。$B$B我現在要去找個掩體……$B$B你要不要一起來？', '把5號齒輪交給魯特維爾·沃拉圖斯。', '', '去找荒蕪之地的魯特維爾·沃拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 778 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (778, 'zhTW', '不祥的感覺', '哈哈！完成啦！鐐銬完成啦！$B$B記住這個時刻，盧希恩,記住這個時刻，阿布！你準備好了嗎？你將親眼看見鍊金術、工程學和魔法的完美結合。$B$B我將召集一個強大的元素生物。今天，對於我們來說，是具有里程碑意義的一天！', '擊敗法姆雷託守護者，並將魯特維爾的元素禁錮鐐銬交還給魯特維爾。', '', '去荒蕪之地找漫塵盆地的魯特維爾·沃拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 779 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (779, 'zhTW', '大地封印', '', '', '', '去找荒蕪之地的大地封印。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 780 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (780, 'zhTW', '鬥豬', '生活在東邊的刺刃峽谷中的鬥豬已經侵佔了我們部族的狩獵場。正在與我們交戰的刺背野豬人把這些野豬訓練成了兇暴而富有攻擊性的生物。$B$B去把這些可惡的傢伙殺掉，再帶些豬頭和肋排回來，我們可以燉肉給孩子們吃。', '納拉其營地的格盧爾·鷹風要求你去幹掉鬥豬，並帶給他8塊鬥豬頭和8塊鬥豬肋排。', '', '去莫高雷找納拉其營地的格魯爾·鷹風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (781, 'zhTW', '納拉其營地的危機', '在仔細檢視了地圖之後，你意識到刺背野豬人的酋長正計劃著對納拉其營地展開進一步攻擊。$B$B鷹風酋長必須馬上得知這個訊息。', '將刺背野豬人的進攻計劃交給納拉其營地的鷹風酋長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (782, 'zhTW', '破碎的聯盟', '在第二次獸人戰爭期間，部落與死亡之翼之間曾有過盟約，我們也因此得知死亡之翼的兩個副手——黑龍布萊克拉什和赫瑪圖斯——現在正被囚禁在萊瑟羅峽谷裡。$B$B如今我們要讓墮落的昔日盟友們“安靜”一點，我們要恢復部落的榮耀。我們僱傭了索格倫和他的食人魔僱傭兵團幫我們奪回大地印章，也就是那把可以開啟黑龍監獄的鑰匙。$B$B然而，索格倫背叛了我們，他打敗了我們，將大地印章佔為己有。', '殺掉索格倫，把大地印章交給卡加斯的高恩。', '', '去找荒蕪之地的高恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (783, 'zhTW', '身邊的危機', '我希望你已經整裝待發了，年輕的$c。北郡需要你的幫助!我不是說讓你去種田什麼的。暴風城的衛兵們很努力地維持著這裡的和平，但我們人手短缺，更多的危險還在不斷迫近。我們正在召募願意出力保衛家園和聯盟的人。如果你也是應召而來的話，請和我的上級長官—治安官瑪克布萊德談話。他就在我身後的這座修道院裡。', '與治安官瑪克布萊德談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (784, 'zhTW', '背信棄義的人類', '庫爾提拉斯的人類曾在普勞德摩爾上將的率領下大舉進攻杜洛塔，徹底破壞了在共同抵抗阿克蒙德和他的惡魔大軍時由大酋長和珍娜·普勞德摩爾定下的互不侵犯協議。$B$B我們擊退了人類的進攻，並攻下了提拉加德城堡。但最近，由本尼迪克上尉率領的後備軍又重新佔領了提拉加德城堡，對我們的家園構成了新的威脅，這些人類從不遵守外交協議。$B$B到南方的提拉加德城堡去消滅那些人類侵略者，證明你的勇氣和榮譽。', '殺死10個庫爾提拉斯水手和8個庫爾提拉斯水兵，再把本尼迪克上尉幹掉，然後回剃刀嶺向加索克復命。', '', '去找杜洛塔的加索克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 785 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (785, 'zhTW', '協助盟友', '索爾是一位十分睿智而高貴的首領。他在戰場上的勇猛善戰和他在外交上的高瞻遠矚一樣卓越不凡。$B$B暗矛部落的食人妖一直以來都是獸人的堅定盟友。為了表示忠誠和榮譽，我們之間簽訂了協同防衛的契約。$B$B酋長已經下達了命令，要保證我們在森金村的巨魔朋友們不會遭到任何直接的威脅。他們最值得信任的偵察兵之一拉爾·獵齒已經在密切注意他們村莊西側的狀況。$B$B去找拉爾，並根據情況協助他。', '在森金村的西側找到拉爾·獵齒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (786, 'zhTW', '科卡爾半人馬的進攻', '小聲點， $C 。科卡爾半人馬就在西邊科卡爾峭壁的山脊上。$B$B昨天晚上，我潛入了他們的村莊，發現這些骯髒的野獸準備同時向杜洛塔的食人妖和 $R 發動三波攻勢。$B$B我們決不能讓他們的入侵計畫得逞!你可以召集一些兵力，潛入科卡爾峭壁並粉碎他們的進攻計畫。$B$B他們已經把進攻計畫分別交給了三個首領，準備由他們率領三股部隊同時行動。', '在森金村外面的拉爾·獵齒要求你粉碎科卡爾峭壁內的3份進攻計畫。', '', '去杜洛塔找森金村的拉爾·獵齒。', '攻擊計畫：摧毀試煉之谷', '攻擊計畫：摧毀森金村', '攻擊計畫：摧毀奧格瑪', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (787, 'zhTW', '新的部落', '向你致意，$c。我是伊崔格，奉索爾酋長的命令在此負責招募新兵。部落已經不再是從前的那個部落了。我曾經離開過部落，在那段時間裡，我受到燃燒軍團的蠱惑而迷失了自我。在被放逐後，我被一群人類抓去當了俘虜，但最終被我們偉大的酋長救了出來。在酋長那拯救部落的遠大志向的指引下，在薩滿的教誨之下，我回來了。高內克會給你進一步的指示。', '向大獸穴裡的高內克報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (788, 'zhTW', '小試身手', '第一項任務將在力量方面對你進行考驗。我本來可以把你派去貧瘠之地獵殺科多獸，不過呢，照實說，你活著比死了對我們來說更有用。$B$B我相信你更合適和那些雜斑野豬鬥一鬥，往北邊走就可以找到它們。', '殺掉8隻雜斑野豬，然後向大獸穴裡的高內克報告。', '', '去杜洛塔找試煉谷的高內克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (789, 'zhTW', '工蠍的尾巴', '無論是強大的戰士還是笨拙的新手，都有可能會倒在蠍尾上的毒針之下。在這裡的西北方有大量蠍子在活動，給我帶8條蠍尾回來，以此來證明你的戰鬥能力吧。$B$B事實上，它們尾巴上的毒針正是製作解毒劑的重要材料，解毒劑便是從毒針中提取的。我們需要長期備有大量的解毒劑，以防止像你這樣的新手被蠍毒所害……$B$B但我肯定你是不會需要這種玩意的，對吧?', '把8根工蠍的尾巴帶給大獸穴中的高內克。', '', '去杜洛塔找試煉谷的高內克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (790, 'zhTW', '薩科斯', ' $C !我差點就神不知鬼不覺地死在這鬼地方了!我在谷裡捕獵蠍子的時候，突然看到一隻看起來特別兇惡的蠍子。當時我就決定以它為獵物，打算在它那碩大的鉗子鉗住我的腿以前，先重重地給它來上那麼一下子。$B$B但我忘記了它還有根毒刺，毒刺猛紮了下來，一下子就刺進我的胸口。拜託，你一定得替我報仇!只有這樣才能留存我的名譽!我是在南邊的高地上碰上它的。', '殺死薩科斯並將它的爪子帶回去交給哈納祖。', '', '去找杜洛塔的哈納祖。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (791, 'zhTW', '新的背包', '我太老了，已經沒法上戰場拼殺了。所以我開始用別的途徑為部落出力，實現我的價值。$B$B我在這裡監視周圍的情況，我們的力量越來越強大，我吹起號角的機會也越來越少。$B$B為了打發時間，我經常給那些保衛家園的年輕戰士們做些有用的東西。$B$B我可以給你做一個用來放置財物的包袱，但是你得先給我找些帆布腳料來，人類和半人馬經常使用這種布料。', '剃刀嶺瞭望塔中的弗恩·凝眉想要8塊帆布腳料。', '', '去杜洛塔找剃刀嶺的弗恩·凝眉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (792, 'zhTW', '邪靈劣魔', '我相信你會在試煉谷學到很多東西，年輕的 $C 。$B$B我本是被派到這處谷地裡來指引和教育你們的，但我卻在這裡發現了一些不潔之物……$B$B一群自稱為燃刃氏族的 $R 潛入了試煉谷，他們躲進了東北方的一處洞穴裡，而他們的邪靈劣魔則肆虐著周邊的一大片地區。$B$B作為你對抗燃刃氏族的第一個任務，我命令你消滅這些劣魔。盡可能地多殺一些，如果殺完了它們之後你還活著的話，就回來向我覆命。', '殺死8隻邪靈劣魔。', '', '去杜洛塔找試煉谷的祖雷薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 793 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (793, 'zhTW', '破碎的聯盟', '大地印章由三塊符石控制，它們分別被放置在萊瑟羅峽谷的鑽石柱、瑪瑙石柱和紫水晶石柱中。用大地印章就可以取下符石並開啟大地封印。$B$B當心點，$n，黑龍布萊克拉什和赫瑪圖斯是很難對付的。殺掉它們，把它們身上的鎖鏈交給我。', '用大地印章啟用鑽石柱、瑪瑙石柱和紫水晶石柱並拿到三顆符石。$B$B把符石放在大地封印上，釋放黑龍布萊克拉什和赫瑪圖斯。$B$B殺了這兩條黑龍，把黑龍布萊克拉什的鎖鏈、赫瑪圖斯的鎖鏈和大地印章交給高恩。', '', '去荒蕪之地找卡加斯的高恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (794, 'zhTW', '燃刃勳章', '我通過預言術發現在燃刃集會所的深處藏有一件蘊涵著強大力量的物品，它被一些猛獸和黑暗的魔法守衛著。$B$B那件物品叫作燃刃勳章，你的下一個任務就是找到它，把它從集會所裡偷出來。$B$B不過你可得小心，因為勳章的所有者可能是一個燃刃部落中的強者，他也許要比你以前對付過的那些傢伙要強上許多倍。$B$B現在就出發吧， $N ，那個洞穴就在這裡的西北方。', '幫大獸穴外的祖雷薩·遠凝帶回燃刃勳章。', '', '去杜洛塔找試煉谷的祖雷薩。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 795 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (795, 'zhTW', '大地封印', '', '', '', '去找荒蕪之地的大地封印。', '', '', '', '', 0);
