INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1164, 'zhTW', '科娜塔一家', '賤人!豬頭!科娜塔竟然還活著!我在這裡受苦受難，她居然全家和睦健康，人丁興旺的。我被她拋棄了!$B$B我已經沒有家了，他們都被瘟疫帶走了。我的財產也都在戰爭中被搶光燒光了。這些也就算了，然而就是她和她的那些野種們，竟然厚著臉皮趁我不在的時候偷走了我家最後一件值錢的東西。$B$B我倒是不再關心那些被偷的東西了。現在我要的是他們的人頭!$B$B到阿拉希高地去，避難谷地的東北方有一個達比雷農場，去那裡把他們都給我殺光啊!', '將科娜塔、法迪爾和馬塞爾的頭顱交給幽暗城的吉納維·卡隆。', '', '去找奧特蘭克山脈的吉納維·卡隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1165 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1165, 'zhTW', '急需精鐵礦石', '', '', '', '去找千針石林的菲茲爾·銅栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1166, 'zhTW', '莫格穆洛克主宰的任務', '向莫格穆洛克主宰鞠躬致敬吧！$B$B是雷克薩讓我做了石槌氏族的領袖！$B$B我是個好領袖，是我保衛氏族安全。$B$B大龍來了，燒了我們的家園，是我這麼個有頭腦的食人魔在這兒給氏族找了個新家。$B$B離開原來的家的時候太匆忙，我忘了點東西。小$r，去把我的東西拿來。往南走，去拿回我的烈酒、鼻菸和保險箱。你做好了我就會喜歡你。', '蕨牆村的莫格穆洛克主宰要你從石槌廢墟拿回他的烈酒、鼻菸和保險箱。', '', '去塵泥沼澤找蕨牆村的莫格穆洛克主宰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1167, 'zhTW', '奧薩拉克斯之塔', '在你正面對抗埃瑟里克斯之前，最好先向巴蘇爾請教請教。毫無疑問，他一直都在警惕地觀察著那座塔，應該會有一些新消息。', '去和奧薩拉克斯之塔附近的巴蘇爾·影擊談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1168, 'zhTW', '黑龍軍團', '雷克薩讓莫格穆洛克做大王。莫格穆洛克只知道權力，很少關心食人魔。$B$B黑龍殺了很多食人魔，還殺了薩爾格的妻子。莫格穆洛克叫我們逃跑，讓我們到這兒來。$B$B食人魔應該戰鬥。食人魔不逃跑。莫格穆洛克只關心他自己。$B$B我只把石槌村叫做家。我喜歡南邊。$B$B幫食人魔打黑龍軍團。我們要復仇。我們要回家。', '蕨牆村的薩爾格要你去殺掉10個火鬃斥候，10個火鬃灰尾龍人和5個火鬃守衛。', '', '去泥塵沼澤找蕨牆村的薩爾格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1169 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1169, 'zhTW', '群龍之首', '莫格穆洛克那個懦弱的傻瓜只知道權力，他整日和薩爾格爭奪著氏族的領導權，大概只有我才在想著要找出襲擊我們以前家園的邪惡勢力的源頭。$B$B幹嘛用這種疑惑眼神看我，$n？你以為我會像個粗俗的混蛋那樣說話嗎？就因為我是個食人魔？$B$B說正事吧，從那些大大小小的黑龍身上弄些心臟和舌頭回來給我，也許我可以找出這邪惡的源頭。', '蕨牆村的德拉茲辛比要你給他收集7條灼熱之舌和7顆灼熱之心。', '', '去塵泥沼澤找蕨牆村的德拉茲辛比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1170, 'zhTW', '奧妮克希亞的血脈', '石槌村被奧妮克希亞的種族所侵犯，不過死亡之翼的女兒怎麼會來侵犯我們的領地？$B$B這真是個大麻煩。奧妮克希亞來這裡肯定不僅僅是為了圍攻食人魔，而是還有別的什麼目的。$B$B快去通知莫格穆洛克！我們必須採取行動了。', '和蕨牆村的莫格穆洛克主宰談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1171 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1171, 'zhTW', '奧妮克希亞的血脈', '別煩我。去告訴德拉茲辛比，我們就留在這兒。這兒沒有黑龍。', '去和蕨牆村的德拉茲辛比談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1172 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1172, 'zhTW', '奧妮克希亞的血脈', '黑龍谷到處都是奧妮克希亞的子嗣，決不能讓它們繼續繁殖下去了！$B$B趕緊到塵泥沼澤西部的巨龍沼澤去，那兒肯定是奧妮克希亞的巢穴。找到那裡的龍蛋，把它們給毀了。$B$B如果他們還在不斷滋生，我們就別想奪回石槌村。$B$B至於莫格穆洛克這個傢伙……我自有辦法。', '蕨牆村的德拉茲辛比要你去毀掉5枚奧妮克希亞的蛋。', '', '去塵泥沼澤找蕨牆村的德拉茲辛比。', '摧毀奧妮克希亞的蛋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1173, 'zhTW', '挑戰莫格穆洛克主宰', '你竟敢挑戰莫格穆洛克？$B$B啊啊啊啊啊啊啊！$B$B我來踩扁你這個小$r！$B$B什麼時候準備好捱揍就告訴我。', '打敗莫格穆洛克，再把訊息帶給蕨牆村的德拉茲辛比。', '把莫格穆洛克趕出蕨牆村。', '去塵泥沼澤找蕨牆村的德拉茲辛比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1174 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1174, 'zhTW', '地精獲勝！', '', '', '', '去找千針石林的克拉茲·滑鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1175 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1175, 'zhTW', '安全隱患', '自從地精的紅雷賽車和一隻大蜥蜴撞了個滿懷之後，科魯克萊德就僱了我去看守賽道。我不知道平原上的這些動物都是吃什麼的，居然長得這麼大，但我們必須多加小心，免得它們在比賽時突然跑進賽道里。$B$B我跟你說啊，如果你想打點零工的話，那就去把這些蜥蜴趕走吧。', '為閃光平原的賽道管理員澤爾林殺死10條鹽石蜥蜴、10條鹽石水晶蜥蜴和6條鹽石凝視者。', '', '去千針石林找沙漠賽道的賽道管理員澤爾林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1176 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1176, 'zhTW', '減輕負重', '說到賽車，每一點都很重要！不論是動力輸出的調整，壓力線圈的鬆緊，或者是對於整部機車重量的控制，每一項都很關鍵，所以你必須考慮所有的東西。$B$B我們用禿鷲的骨頭對賽車進行了改造，這樣就提供了力量與重量的完美平衡，真棒。更棒的是，我們可以很容易地得到更多的禿鷲骨頭，因為這一帶到處都是禿鷲。$B$B去幫我找一些禿鷲骨頭來，我會給你個好價錢的。', '給閃光平原的普茲克找10根空心禿鷲骨。', '', '去千針石林找沙漠賽道的普茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1177 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1177, 'zhTW', '餓！', '阿泥是大巨魔。$B$B我餓了。$B$B去抓點魚來。給阿泥找吃的。$B$B你餵飽阿泥，不然阿泥就吃你。', '塵泥沼澤北部的碎泥·杜特非要你去抓8條沼鰭小魚。', '', '去找塵泥沼澤的碎泥·杜特非。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1178, 'zhTW', '哥布林贊助商', '不管在哪裡，我們的賽車隊都是哥布林的驕傲。你會對那些以各種方式為車隊貢獻自己力量的人感到吃驚的。$B$B你認識加茲魯維嗎？他為我們從全世界尋找賽車零件，有一次他甚至為我們找來了一臺完整的賽車！$B$B幾星期前，他說他要送給我們一套新的燃油調節器，但至今還沒有到貨。他一向說話算數……你能去棘齒城幫我問問嗎？我原本並不是特別心急，但是地精正在趕上我們的步伐！', '和棘齒城的加茲魯維談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1179, 'zhTW', '銅栓兄弟', '你聽說過閃光平原嗎？這是一片位於卡林多大陸上的鹽鹼地，就在千針石林大峽谷的南面。這是塊絕佳的競速場地，因為……它實在是太平坦了！$B$B有一對地精兄弟，嗯，他們是我的朋友，就在那兒試驗他們新近研製的火箭車，我聽說這玩意跑得還挺快，快到頻頻撞車的地步，把駕駛員都給撞出腦震盪來了。$B$B所以這兩個傢伙讓我幫他們弄幾頂蒸汽坦克駕駛員的頭盔。可是我這邊還有別的任務，根本抽不出身來！$B$B你能替我跑個腿嗎？', '給閃光平原上的維茲爾·銅栓捎去一箱防撞頭盔。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1180, 'zhTW', '哥布林贊助商', '回到關於你為何來這裡的話題上。我的確向普茲克保證過會幫他運一臺新的調節器，但我現在還沒有收到這臺機器。藏寶海灣的裡維加茲說他已經把東西裝船運了過來，也許是在運輸過程當中出了什麼差錯。$B$B如果是那樣的話，我們就無能為力了。現在我只知道它已經從藏寶海灣運了出來。$B$B去找碼頭管理員羅茲基爾吧，他應該能幫你查一查出貨記錄。', '和藏寶海灣的碼頭管理員羅茲基爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1181, 'zhTW', '哥布林贊助商', '恐怕我也只能幫你這些了，$n。如果你還想了解更多事情的話，就直接去找大財主裡維加茲本人吧。還有誰能比裡維加茲對他自己的生意更瞭解呢？$B$B你到港口那邊的小酒館頂樓的房間裡就能找到他了。', '與藏寶海灣的大財主裡維加茲談一談。', '', '去荊棘谷找藏寶海灣的大財主裡維加茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1182, 'zhTW', '哥布林贊助商', '瞧，納菲瑞提湖那邊的地精風險投資公司的伐木機上都裝備了最新型號的燃料調節器。我覺得，普茲克要是能拿到調節器的詳細設計圖，一定可以善加利用它。糟糕的是，那邊的工頭比我預計的要精明得多，要取得設計圖似乎並不容易。$B$B你看起來應該有能力去拿到那張設計圖。據我所知，他把那些東西都鎖在了屋子裡。', '將燃料調節器的藍圖交給藏寶海灣的大財主裡維加茲。', '', '去荊棘谷找藏寶海灣的大財主裡維加茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1183, 'zhTW', '哥布林贊助商', '你現在就趕快出發吧。替我向普茲克問好，順便告訴他，如果他需要什麼東西，就儘管跟我說。我期待著他能馬上打破記錄！', '把燃料調節器的藍圖帶給閃光平原的普茲克。', '', '去千針石林找閃光平原的普茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1184 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1184, 'zhTW', '蟲群的訊息', '返回奧格瑪的貝爾戈洛姆那裡，告訴他摩克塔正在一絲不苟地執行他的命令。把我的研究進展也告訴他，我希望他能知道這些資訊，貝爾戈洛姆一定會為此感到高興的。', '回到奧格瑪的貝爾戈洛姆·石槌那兒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1185, 'zhTW', '殼中的東西…', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1186, 'zhTW', '第十八個駕駛員', '我要開始著手將這個新的燃油調節器裝到賽車上去了，如果你想要幫助車隊的話，就去和拉澤瑞克談談吧。他是我們的駕駛員——更確切地說，是第18個駕駛員——他想為這些賽車做一個小小的修改。$B$B他經常有些奇思妙想，所以請不要太吃驚了。', '和閃光平原的拉澤瑞克談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1187, 'zhTW', '拉澤瑞克的調整', '我知道，普茲克是個偉大的機械師，但是他不敢加大油門趕超別人。但我不像他那麼膽小。$B$B在普茲克賽車的設計完成後，我花了點時間做了一些小小的修改。把控制器鬆一鬆，改造某些結構，增加更多的潤滑劑，諸如此類。$B$B我從加基森的史瑞夫那裡訂了一個爆鹽增壓器，但是那運貨的飛艇卻一頭栽進了塵泥沼澤！$n，幫我去把東西取回來吧！', '為閃光平原的拉澤瑞克取回爆鹽增壓器。', '', '去千針石林找沙漠賽道的拉澤瑞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1188 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1188, 'zhTW', '安全第一', '等等，這是怎麼回事？史瑞夫開啟了保險裝置？這樣會限制推進器的輸出功率的。我說過那個裝置要關掉！對我來說開著那東西一點好處也沒有！$B$B你必須把這個拿到塔納利斯沙漠中的加基森去，讓史瑞夫把那該死的保險裝置給我拆了。', '把爆鹽增壓器交給加基森的史瑞夫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1189 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1189, 'zhTW', '安全第一', '看，我已經按照拉澤瑞克的要求去做了。我跟他說過，在關閉安全裝置時要當心點，否則即使是最小的錯誤也會釀成大錯，輕則讓整輛賽車無法移動，重則把他直接在車裡燒成灰。$B$B如果真的那樣的話可就太丟人了，我們到哪裡去找第十九個願意入夥的賽車手呢？', '將改進型爆鹽增壓器還給閃光平原的拉澤瑞克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1190, 'zhTW', '跟上節奏', '銅栓兄弟倆發現了一種新的材料，這是唯一說得通的解釋。它們的車速比以前快了，但它們的設計，以及我們蒐集的其它一些資料都和以前的一致。$B$B我們知道的是，瑞茲爾·銅栓一直以來都致力於這項新發明的計劃之中。$B$B扎米克可以為你提供掩護，這樣你就能從他們那兒偷到這些計劃了。', '讓扎米克掩護你，然後為閃光平原的普茲克偷到瑞茲爾的計劃。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1191 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1191, 'zhTW', '扎米克的困擾', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1192 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1192, 'zhTW', '精鐵礦石', '', '', '', '去找千針石林的普茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1193 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1193, 'zhTW', '破碎的陷阱', '', '', '', '去找奧特蘭克山脈的損壞的陷阱。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1194 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1194, 'zhTW', '瑞茲爾的圖表', '瑞茲爾的圖表上介紹了精鐵礦石的精煉過程。從他的草稿中可以得知，精鐵礦石來自於荒蕪之地之中的奧達曼挖掘場。$B$B很多其它筆記的內容都與這種礦石的抗熱效能有關。$B$B整個筆記的重頭似乎是關於未精煉的精鐵礦石的。', '把精鐵礦石樣本交給閃光平原上的普茲克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1195 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1195, 'zhTW', '神聖之火', '千針石林的加拉克半人馬一直在保護著一件神器，它的歷史可以追溯到半人馬剛剛在這片土地上出現的時候。$B$B我們要得到它，但我們必須得有一瓶來自於夜精靈月井的水。$B$B要取水還必須找一個特殊的瓶子，在梣谷森林中心地帶靠近林中樹居一帶出沒的林精或許就有這種瓶子。在靠近弗倫河西岸的大路南面有一口月井，你可以在那裡裝滿水，然後把它帶回來給我。', '把裝滿水的蝕刻瓶交給雷霆崖的贊金·石蹄。', '', '去莫高雷找雷霆崖的贊金·石蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1196 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1196, 'zhTW', '神聖之火', '把這裝滿水的蝕刻瓶給亂風崗的勞恩·峭壁行者帶去吧。你可以搭乘貧瘠之地南部邊境的升降梯去千針石林。', '把裝滿水的蝕刻瓶交給亂風崗的勞恩·峭壁行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1197 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1197, 'zhTW', '神聖之火', '你找來的水可以暫時浸溼守護半人馬遺物的火焰，但是效果不會持續很久，所以你必須行動迅速。$B$B半人馬的要塞——加拉克峭壁——就在這裡的北邊，火焰就儲存在那座重兵把守的要塞中。$B$B小心點，加拉克半人馬的數量眾多，他們決不會輕易放棄如此珍貴的東西。', '拿到裂開的蹄子，把它交給亂風崗的勞恩·峭壁行者。', '', '去千針石林找亂風崗的勞恩·峭壁行者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1198 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1198, 'zhTW', '尋找塞爾瑞德', '這些天有很多關於暮光之錘與黑海岸北部黑暗深淵裡的納迦結盟的傳聞。我在這裡的任務是收集盡可能多的情報，這樣我們就知道何時何地會需要幫助了。我派去偵察黑暗深淵的斥候塞爾瑞德已經離開好幾個星期了，但直到現在他也沒有提交任何報告。糟糕的是我的其他斥候也正在處理一些緊急事務，實在抽不出人手了。幫我找到塞爾瑞德，並且幫助他完成任務吧，$n。', '到黑暗深淵去找到銀月守衛塞爾瑞德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1199 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1199, 'zhTW', '暮光之錘的末日', '受到混沌古神的古老儀式驅動，暮光之錘的成員致力於他們黑暗的守護神召回這個世界，在整個世界上散佈死亡和恐怖。$B$B我們相信暮光之錘已經和納迦達成聯盟，並且正群聚在西邊的黑暗深淵裡面。$B$B不論在那古老神殿的深淵中醞釀著怎樣邪惡的計畫，我們都必須讓它消失。$B$B向暮光之錘開戰，並且帶回你成功的證據。你的努力將獲得優渥的回報。', '收集10個暮光墜飾，把它們交給達納蘇斯的銀月守衛瑪納杜斯。', '', '去達納蘇斯找工匠區的銀月守衛瑪納杜斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1200, 'zhTW', '黑暗深淵中的惡魔', '我體內的力量已經流失。我需要你的幫助!$B$B很久以前這個地方是崇拜伊露恩的偉大神殿。但一名古神的腐化從地底滲透而上，污染了神聖的月井，導致這地方不幸地化成了廢墟。$B$B阿庫麥爾，古神的僕從，從水中崛起。$B$B暮光之錘教徒和納迦們結成同盟，好來侵佔這些土地。這些教徒，接受著克爾里斯的領導，將無辜的生命獻祭給阿庫麥爾來獲取力量。$B$B殺死克爾里斯，並將他的頭顱帶去給達納蘇斯的塞爾高姆，$N。拜託你。', '將暮光領主克爾里斯的頭顱交給達納蘇斯的塞爾高姆。', '', '去找達納蘇斯的哨兵塞爾高姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1201, 'zhTW', '塞拉摩間諜', '部落和聯盟正處於某種令人不安的休戰期。兩大陣營之間的小規模的衝突和暗殺活動時有發生，而我們的職責就是確保部落始終佔據上風！$B$B現在正是行動的時候。$B$B聯盟派了一些間諜駐紮在蕨牆村的東部，他們監視著村子，把我們的動向報給告塞拉摩，決不能讓他們繼續下去。$B$B去追蹤那些間諜，把他們幹掉。讓他們的頭兒知道我們決不會允許他們的間諜在我們面前晃來晃去！', '殺掉9個塞拉摩間諜，然後回到蕨牆村去見納澤爾·血矛。', '', '去塵泥沼澤找蕨牆村的納澤爾·血矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1202, 'zhTW', '塞拉摩碼頭', '$N，我們派了兩個間諜到一艘停泊在塞拉摩碼頭的船上偷檔案。他們找到了檔案，不過卻被人發現了行蹤，只好把檔案丟進海里。$B$B有一個間諜後來逃脫了，但是他卻兩手空空地回來，向我報告了他們失敗的行動。現在我把這個任務交給你。$B$B檔案就裝在一隻小提箱裡，而那提箱已經沉在塞拉摩碼頭下面的海水裡了。找到那些檔案，把它們交給我。', '把指揮官的檔案交給蕨牆村的納澤爾·血矛。', '', '去塵泥沼澤找蕨牆村的納澤爾·血矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1203, 'zhTW', '加爾的劍', '我要切點東西，呃……我不能告訴你我要切什麼，不過……反正我需要把劍。一種特殊的劍……$B$B有人叫它月光劍。我叫它快劍。$B$B你能幫幫我嗎？也許鎮上就有賣，或者你也可以去找個鐵匠打造一把。$B$B不過，不要等到明天再去找。我切的東西可不能放太久……', '給塵泥沼澤的加爾找一把月光劍。', '', '去塵泥沼澤找水光莊園的“沼澤之眼”加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1204, 'zhTW', '泥石龜蟹湯', '我正在研究一道叫作“泥石龜蟹湯”的菜，現在我還需要一些原料……唉，我覺得我真是不適合在塵泥沼澤裡長途跋涉！$B$B那麼，$N，你能幫我去打獵嗎？首先，我需要泥石龜的舌頭，這些海龜經常在海岸附近出沒。$B$B不過我要的還不是一般的舌頭！聽說有些泥石龜的舌頭是分叉的……$B$B他們說那樣的舌頭吃起來味道特別好，而且我也很喜歡給我的菜里加點特別的風味……', '給塞拉摩的摩根·斯特恩收集8個分叉的泥石龜舌。', '', '去塵泥沼澤找塞拉摩島的摩根·斯特恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1205 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1205, 'zhTW', '死沼巨鱷', '死沼巨鱷是一隻棲息在塵泥沼澤裡的遠古鱷魚，現在是時候讓它獲得解脫了。$B$B當它挪動著龐大的身軀遊過沼澤的時候，那衰老的骨骼飽受碾磨之苦。儘管它依舊有著可怕的力量和年輕時的速度，但老化的軀體卻折磨著它內心強大的精神——那是一種激情不減的精神。$B$B然而現在它長期生活在巨大的痛苦中，這種痛苦折磨得它幾近瘋狂。$N，現在你必須去結束它的生命，把死沼巨鱷引向安寧的天國。', '把死沼巨鱷的牙齒帶給雷霆崖的梅洛。', '', '去雷霆崖找獵人高地的梅洛·石蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1206, 'zhTW', '加爾和蜘蛛眼', '用眼睛製成飲料的味道非常好，可惜很多生物都只有兩隻眼睛。$B$B不過蜘蛛有很多眼睛，很多很多。黑霧蛛眼汁很好喝，醇美而味鹹！真是沒有比那更好的飲料了……$B$B黑霧蜘蛛就在西邊的黑霧洞穴裡活動。你說這些蜘蛛的名字是來自這個洞的名字呢，還是有別的什麼說法？', '收集20顆黑霧蜘蛛的眼球，把它們交給水光莊園的“沼澤之眼”加爾。', '', '去塵泥沼澤找水光莊園的“沼澤之眼”加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1218, 'zhTW', '沼澤青蛙腿', '我喜歡燒菜，沼澤地裡特產的美食，比如油炸綠青蛙腿之類的。$B$B不過我的青蛙腿都用完了，這一帶到處都是青蛙，像是那些巨型沼澤蛙。你可以幫我找一些青蛙腿來嗎？沒什麼難的，真的。只要往那些青蛙頭上一敲，然後把蛙腿帶給我就好。$B$B這樣我就可以燉一鍋好肉，然後大快朵頤並且分給你一些。$B$B你喜歡燉肉嗎？', '帶10條沼澤青蛙腿給塵泥沼澤的“沼澤之眼”加爾。', '', '去塵泥沼澤找女巫嶺的“沼澤之眼”加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1219, 'zhTW', '獸人的報告', '你可以在鬆土裡看到一隻緊緊握起來的獸人的手，手裡抓著一根用骨頭刻出來的管子，裡面塞著一張粘著泥土的羊皮紙。$B$B羊皮紙上的文字都是獸人的文字……這看上去很重要。', '把間諜的報告交給塞拉摩的亞汀中尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1220 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1220, 'zhTW', '維米斯上尉', '應該讓維米斯上尉看看你找到的這份報告，$N，他的獸人語不錯。我們得讓他知道塞拉摩附近有部落的間諜！$B$B隊長眼下正在塞拉摩島東北面的兵營裡。', '把間諜的報告交給蓋蘭·維米斯上尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1221, 'zhTW', '藍葉薯', '藍葉薯是美味絕頂的佳餚!但是這種東西很罕見，非常非常罕見。它們只生長在貧瘠之地，在剃刀沼澤的地下深處。$B$B不過知道這一點也沒什麼用，因為如果你不知道它們的確切位置，那麼就算近在咫尺你也不一定找得到它們。這就是我訓練這些地鼠去尋找藍葉薯的原因─它們有很靈敏的嗅覺，在五十步以外就能嗅到藍葉薯塊莖的氣味。$B$B這差事並不輕鬆，但是如果你幫我弄來一些藍葉薯的話，我會付給你一筆可觀的報酬。', '找到一個開孔的木箱。找到一根地鼠指揮棒。找到並閱讀《地鼠指揮手冊》。在剃刀沼澤裡用開孔的木箱召喚一隻地鼠，然後用指揮棒驅使它去搜尋藍葉薯。把地鼠指揮棒、開孔的木箱和6塊藍葉薯交給貧瘠之地的麥伯克·米希瑞克斯。', '', '去找貧瘠之地的麥伯克·米希瑞克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1222, 'zhTW', '伊格納茲的逃亡', '太好了，總算碰到一個不是要來吃了我的人了！$B$B我正愁沒人來幫我對付這兒的怪物哪，$g兄弟:小姐;，你看來就挺合適。$B$B那個叫摩根·斯特恩的廚子在研究一套新食譜，他讓我來這兒採集一點睡菜葉。那傢伙可能覺得睡菜葉挺好吃吧。$B$B就在我找睡菜的時候……我發現我被包圍了！你能幫我從這兒逃出去嗎？哦，對了，順便在我找睡菜的時候替我斷後。', '護送伊格納茲，然後和塞拉摩的摩根·斯特恩談一談。', '幫伊格納茲找睡菜葉', '去塵泥沼澤找塞拉摩的摩根·斯特恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1238 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1238, 'zhTW', '遺失的報告', '你可以在鬆土裡看到一隻緊緊握起來的獸人的手，手裡抓著一根用骨頭刻出來的管子，裡面塞著一張粘著泥土的羊皮紙。$B$B羊皮紙上是一個在塞拉摩偵察了好幾個星期的獸人寫的報告。$B$B瀏覽過羊皮紙之後，你決定立刻把它送給蕨牆村的獸人情報官。', '把間諜的報告交給蕨牆村的納澤爾·血矛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1239 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1239, 'zhTW', '被斬下的頭顱', '繼續挖掘了一番之後，你找到了一顆男性獸人的頭顱，脖子上有參差不齊的割痕。他的臉上還保持著發出怒吼的樣子，黑色的眼睛不屈地怒視著前方。', '把獸人的頭顱交給蕨牆村的納澤爾·血矛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1240 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1240, 'zhTW', '食人妖巫醫', '我們必須弄清楚瑪格究竟是怎麼死的！唯一的方法就是使用食人妖的巫術。把瑪格的頭拿給肯維雷，他就在荊棘谷的格羅姆高營地裡。$B$B肯維雷是暗矛食人妖裡最強的巫醫，能和瑪格·夜眼的靈魂說話的人也只有他了。', '把獸人的頭顱帶到荊棘谷的格羅姆高營地裡，交給肯維雷。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1241, 'zhTW', '失蹤的使節', '最近我們派出了一名外交使節前往塞拉摩與珍娜·普勞德摩爾女士會晤，但那位使節沒能抵達目的地。$B$B我相信迪菲亞兄弟會與這件事有關，但我並不清楚具體的細節。那個使節失蹤的消息對外仍然是嚴密封鎖的，但這件事情遲早要曝光。$B$B國王的密探已經動員。在城內尋找線索，但我打算私底下再找一些人來解決此事。$B$B我有個老朋友喬貞，他在英雄谷中。將這張字條帶給他，然後聽他的命令行事。', '在暴風城的英雄谷找到喬貞。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1242, 'zhTW', '失蹤的使節', '把這張字條交給伊林·提亞斯，不要和他說任何話。你只需要禮貌地等著他的回答就是了。不用擔心，他一定會回答你的。$B$B我必須再跟你清清楚楚地說一遍，$N:把這件事情看得認真點，在任何人面前都要閉好你的嘴。$B$B你可以在貿易區的「提亞斯乳酪店」找到提亞斯。祝你好運。', '將喬貞的密函帶給暴風城貿易區的伊林·提亞斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1243 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1243, 'zhTW', '失蹤的使節', '喬貞，你這老混……那麼，事情就是這樣了，是吧?$B$B好吧，我會處理的。我倒是希望他早點死在扭曲虛空手上呢!$B$B這麼辦吧，$N。我會開始派出我在這裡的線人，不過你得幫我跑腿，好讓我省點錢。$B$B到暮色森林的夜色鎮去找守夜人巴庫斯—他通常會在城鎮北邊的路上巡邏。告訴他，你正在為我調查迪菲亞兄弟會的活動，他會把他所知道的事情全都都告訴你的。', '將密函帶給暮色森林的守夜人巴庫斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1244 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1244, 'zhTW', '失蹤的使節', '迪菲亞兄弟會的活動?好吧，他們總是不斷在活動。就算他們按兵不動，我們也仍然視之為威脅。$B$B但現在我認為，最近事情變得有點奇怪。大概是在兩三週前吧，他們的許多密探都在腐草農場附近頻繁出沒。由此看來那裡一定是發生了什麼重要的事情。$B$B你為什麼不先去那裡調查一下，並把你調查到的結果拿給我看看?$B$B那座農場就在由西部荒野進入暮色森林的大路南邊。', '找到迪菲亞記事本，把它帶回來給暮色森林的守夜人巴庫斯。', '', '去暮色森林找夜色鎮的守夜人巴庫斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1245 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1245, 'zhTW', '失蹤的使節', '哎呀，如果這只是個用來干擾你的視線的幌子，那他們也未免搞得太複雜了，我也不太清楚這東西到底是什麼。把它交給提亞斯吧─他一定能弄明白其中的意義。千萬小心，別讓任何人把它搶走。我們都知道，這事可比我的命還重要，甚至比他的命還要重要。$B$B最後，拜託你一件事，$N，別對任何人說起我幫助過你。我的上司如果知道我對這件事有所瞭解而又沒有向他們彙報的話，沒准會絞死我的。', '將迪菲亞記事本帶給暴風城的伊林·提亞斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1246 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1246, 'zhTW', '失蹤的使節', '對了，就是他，現在我想起來了…達舍爾…達舍爾…什麼來著……他的名字是什麼來著?拳!達舍爾·石拳。圈內人都叫他拳—或許是因為他喜歡製造事端的緣故吧。你通常可以在舊城區裡見到他—在舊城區中心練拳。去和他談一談，如果有必要的話，你不妨威脅威脅他，甚至用點暴力手段，有時得那樣才能讓他說點真話出來。別猶豫!要是真像這份東西上所寫的那樣，他應該已經深陷其中，不會那麼輕易就告訴你什麼有用的資訊。', '與暴風城舊城區裡的達舍爾·石拳談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1247 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1247, 'zhTW', '失蹤的使節', '原來如此……唔……我對腐草農場那邊的會議略知一二，我記得是幾週前組織的，但我沒有去參加那個會議。我只參加了A計畫的那部分，但A計畫失敗了……那些該死的冒險者。我們的線人說，那個執行B計畫的小子來自米奈希爾，他的外號叫乾柴。對於他們的後備計畫我就知道這麼多了。', '與暴風城的伊林·提亞斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1248, 'zhTW', '失蹤的使節', '我有一個隱居在米奈希爾港的線人。他已經退休了，不過如果你告訴他你是為我工作的話，他應該會很願意幫助你的。他名叫米克哈爾，在幾年前離開暴風城的時候，他提到過自己要去旅店工作。和他談談，想辦法找到這個乾柴，再打聽一下有沒有關於使節被綁架的消息。我們現在得弄清楚他被帶到了什麼地方去，或者至少弄清楚他是誰。這份摘要裡沒有提到綁架行動完成以後的事。', '與濕地的米克哈爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1249, 'zhTW', '失蹤的使節', '你說是伊林派你來的?好吧，現在我要拿出十倍的熱情來招待你。想要什麼儘管說，我會竭盡全力來幫助你的。$B$B嗯，你說乾柴?似乎是沒聽說過的名字，但我一定會注意他的。$B$B別抬頭看，$N，出口旁邊的那傢伙正往我們這邊看呢。這傢伙似乎有點太專心地聽我們的對話了，你明白我的意思嗎?如果我是你，我就會趁他溜走之前好好教訓教訓他。', '在塔伯克·賈恩逃跑前制服他，然後回米奈希爾港旅店去找米克哈爾。', '擊敗塔波克·詹恩', '去找米奈希爾港的米克哈爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1250, 'zhTW', '失蹤的使節', '迪菲亞兄弟會出的價錢還沒高到讓我把我的命也給賠上。他們抓走了國王。對，沒錯，正是暴風城的國王，他可不是什麼簡單的外交使節。他當時正在前往塞拉摩與珍娜·普勞德摩爾會面的路上—這顯然是件大事，當然也是個大秘密。但這裡面可不是只有迪菲亞兄弟會牽扯進來，他們也是為別人效力的。我想只有他們自己知道誰是他們的雇主。我的份內事就是趁國王的船還在港口裡的時候，和他們在船上的內應碰頭，那傢伙叫亨德爾。我就知道這麼多了，我發誓!', '與濕地的米克哈爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1251 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1251, 'zhTW', '黑色盾牌', '有一面被燒燬旅店的大火燻黑了的鐵盾牌和倒塌的煙囪連在一起，這根菸囪是樹蔭旅店燒燬之後留下的幾段殘磚斷瓦中的一部分。$B$B這面鐵盾牌可以從煙囪的磚上拿下來。', '把被燻黑的鐵盾牌帶給蕨牆村的克羅格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1252, 'zhTW', '帕瓦爾·雷瑟上尉', '地上閃過的一道光芒把你的視線引到碎石的下面。你撥開了碎石，發現灰塵下有一枚白色的徽章，表面上印有金色的船錨，那是塞拉摩的標記。$B$B錨的下面刻著“帕瓦爾·雷瑟上尉”的字樣。', '把雷瑟的徽章拿給塞拉摩的蓋蘭·維米斯上尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1253, 'zhTW', '黑色盾牌', '有一面被燒燬旅店的大火燻黑了的鐵盾牌和倒塌的煙囪連在一起，這根菸囪是樹蔭旅店燒燬之後留下的幾段殘磚斷瓦中的一部分。$B$B這面鐵盾牌可以從煙囪的磚上拿下來。', '把被燻黑的鐵盾牌交給塞拉摩的蓋蘭·維米斯上尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1258, 'zhTW', '還有螃蟹！', '新菜譜裡還需要一種大螃蟹的腿，不過塵泥沼澤的汙殼螃蟹可不行！唯一合適的螃蟹在悲傷沼澤裡，離這兒很遠。$B$B螃蟹腿的殼是構成這道菜的外觀的一大要素，所以我必須要新鮮而且沒有任何疤痕的蟹腿。一隻成熟螃蟹大概只有一條或兩條這樣的腿，而我卻需要大量的螃蟹腿來試驗菜譜。$B$B那麼，$N……你願意跑一趟嗎？', '給塞拉摩的摩根·斯特恩收集12根新鮮的螃蟹腿。', '', '去塵泥沼澤找塞拉摩島的摩根·斯特恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1259, 'zhTW', '帕瓦爾·雷瑟上尉', '我不認識這個帕瓦爾·雷瑟上尉，你最好還是去問問泰索蘭副官。他負責管理塞拉摩所有守衛的檔案，包括守衛的個人資料和他們的裝備。$B$B他可以查查這些檔案，然後告訴你這個雷瑟到底是誰。', '從塞拉摩的泰索蘭副官那兒找出更多關於雷瑟的訊息。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1260, 'zhTW', '摩根·斯特恩', '我正在為餐館開發新的菜單，這份新菜單裡都是本地特產的菜色，以「海灣」為主題。我想，藍色隱士旅店的客人一定會很喜歡這個的!我讓我侄子摩根到塞拉摩去收集當地的食譜了，那地方就在塵泥沼澤的邊界地帶。我得知道他到目前為止找到了那些東西。去塞拉摩的路很長，起碼對我來說是太長了。不過我打賭像你這樣一個年輕的$c對這種長途旅行一定會欣然前往的，對吧?', '和塞拉摩的摩根·斯特恩談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1261, 'zhTW', '瑪爾格的囑託', '可惡的龍蝦人！我是不會束手待斃的！啊…但是…我已經死了，看來它的確是把我殺掉了……$B$B但是我的使命，我的使命啊！$N，你必須替我完成它。$B$B我曾在塞拉摩附近監視一隊在海灘上露營的聯盟士兵，其中一個士兵身上配戴著一件飾品，是那種鑲嵌著很多寶石，再有錢的士兵也買不起的飾品！$B$B那天晚上，我溜進他們的營地，偷走了那件飾品，但是在我返回基地的途中，一個汙殼龍蝦人殺死了我！$B$B$N，你必須找到那隻該死的龍蝦人，並奪回那件飾品。', '把寶石墜飾帶給蕨牆村的納澤爾·血矛。', '', '去塵泥沼澤找蕨牆村的納澤爾·血矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1262, 'zhTW', '向佐爾報告', '很奇怪的是，瑪爾格偷取的這件飾品居然是一個普通士兵的東西。它的主人也許掩飾了自己真正的身份，或者那個士兵本身就是個竊賊！$B$B不管事實是怎樣的，總之這是一件貴族的飾品。如果我們想要揭開這個謎團，就必須找出它真正的主人。$B$B帶著飾品去奧格瑪找佐爾·孤樹吧。他對聯盟那邊的事情頗有了解，應該會知道這件飾品是否和暴風城的貴族們有關係。', '把鑲寶石飾品帶給奧格瑪的佐爾·孤樹。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1263, 'zhTW', '燃燒的旅店', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1264, 'zhTW', '失蹤的使節', '每個月初，庫爾提拉斯的水兵們都會領取薪水，然後離開塞拉摩到別的地方去遊玩。大部分人會到這裡來找女人，喝酒，尋歡作樂一番。他們當中有一些人整天都會泡在酒館裡，我敢肯定亨德爾也是其中之一。只要那傢伙現在還留在塞拉摩的話，那麼塞拉摩的指揮官薩莫爾就能幫你找到他。雖然他只對普勞德摩爾家族效忠，但如果你說出伊林的名字，他也會幫助你的……應該會的。', '找到塵泥沼澤的指揮官薩莫爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1265 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1265, 'zhTW', '失蹤的使節', '亨德爾?是的，我知道這個人。不過你找我的士兵有什麼事呢?$B$B伊林派你來找他?嗯，好吧，我不喜歡這種感覺。如果你的事情不麻煩，伊林是不會讓你先來找我的。我理解你可能沒辦法告訴我詳情，但請明白這一點:我有責任保護好這片土地。如果你是來製造麻煩的話，最好先讓我知道你想幹嘛。$B$B我相信，亨德爾就駐守在塞拉摩外的第一座哨塔上。自己小心點!', '在警戒崗哨中搜索士兵亨德爾的消息。', '已探索哨兵峰', '去找塵泥沼澤的大法師特沃許。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1241, 'zhTW', '失蹤的使節', '最近我們派出了一名外交使節轉至塞拉摩與珍娜·普勞德摩爾女士會晤，但那位使節沒能抵達目的地。$B$B我堅信是迪菲亞兄弟會密謀了這個事件，但我並不清楚具體的過程。使節失蹤的消息對外嚴密封鎖，但這件事情遲早要被曝光。$B$B國王的密探已經行動起來，在全城範圍內尋找線索，但我打算私底下再找一些人來解決此事。$B$B我的一個老朋友喬貞現在就在英雄谷中。將這封便箋帶給他，然後聽他的命令列事。', '在暴風城的英雄谷找到喬貞。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1250, 'zhTW', '失蹤的使節', '好吧，迪菲亞兄弟會出價雖高，可還不值得把我的命也給賠上。他們抓走的是國王。對，沒錯，正是暴風城的國王，他可不是什麼簡單的外交使節。他當時正在去塞拉摩與珍娜·普勞德摩爾會面的路上——這顯然是件大事，當然也是個大秘密。但這可不是迪菲亞兄弟會的主意，實際上他們也是為別人效力的。我想只有他們自己知道誰是他們的雇主。$B$B我的份內事就是趁國王的船還在港裡的時候，和他們在船上的內應碰頭，那傢伙叫亨德爾。我就知道這麼多了，我發誓！', '與濕地的米克哈爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1264, 'zhTW', '失蹤的使節', '每個月初，庫爾提拉斯的水兵們都會領取薪水，然後離開塞拉摩到別的地方去遊玩。大部分人會到這裡來找女人，喝酒，尋歡作樂一番。他們當中有一些人整天都會泡在酒館裡，我敢肯定亨德爾也是其中之一。$B$B只要那傢伙現在還留在塞拉摩的話，那麼當地的指揮官薩莫爾就能幫你找到他。雖然他只對普勞德摩爾系列效忠，但如果你說出埃林的名字，他也會幫助你的……應該會的。', '找到塵泥沼澤的指揮官薩莫爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1266 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1266, 'zhTW', '失蹤的使節', '士兵亨德爾就在這裡的西邊，他現在正在執行保護那些輪休的塞拉摩密探們的任務。密探們正在那邊監視著部落的前哨基地—蕨牆村，當然也時刻留心著其他任何有可能威脅到我們的東西。你應該很容易就能找到他，沿著道路搜索每一個帳篷就行了。我現在還有另一件事要處理，但我應該很快就可以趕上你，如果你有任何問題，你都可以在普勞德摩爾女士所在的塔裡找到我。', '找到塵泥沼澤中的士兵亨德爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1267 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1267, 'zhTW', '失蹤的使節', '在塵泥沼澤找珍娜·普勞德摩爾談談。', '與塵泥沼澤的珍娜·普勞德摩爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1268 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1268, 'zhTW', '可疑的蹄印', '有幾排蹄印從樹蔭旅店那仍然冒著煙的廢墟中延伸出來。大部分蹄印都埋在沼澤地的鬆軟泥土裡沒法辨認，不過至少還有一些是可以看清的。', '把樹蔭旅店的可疑蹄印報告給蕨牆村的克羅格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1269 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1269, 'zhTW', '帕瓦爾·雷瑟上尉', '地上閃過的一道光芒把你的視線引到碎石的下面。你撥開了碎石，發現灰塵下有一枚白色的徽章，表面上印有金色的船錨，那是塞拉摩的標記。$B$B錨的下面刻著“帕瓦爾·雷瑟上尉”的字樣。', '把雷瑟的徽章帶給蕨牆村的克羅格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1270 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1270, 'zhTW', '伊格納茲的逃亡', '太好了，總算碰到一個不是要來吃了我的人了！$B$B我正愁沒人來幫我對付這兒的怪物哪，$g兄弟:小姐;，你看來就挺合適。$B$B棘齒城一個叫麥伯克·米希瑞克斯的地精需要弄些睡菜葉……或是別的什麼東西來做藥劑，說實話我不在乎他做什麼，反正他給的報酬不錯，而我又正巧熟悉這個沼澤，所以我就來了。$B$B倒黴的是還沒找到睡菜，我就被包圍了！你能幫我從這兒逃出去嗎？哦，對了，順便在我找睡菜的時候替我斷後。', '護送伊格納茲，然後和棘齒城的麥伯克·米希瑞克斯談一談。', '幫伊格納茲找睡菜葉', '去找貧瘠之地的麥伯克·米希瑞克斯。', '', '', '', '', 0);
