INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1273, 'zhTW', '盤問雷瑟', '我花了很長時間終於找到雷瑟了。他躲藏得很好。$B$B奧格隆擔心他在沼澤地裡待了這麼久可能已經瘋了，你跟我來，咱們一起去從他那裡套出一些我們需要的答案。', '和奧格隆一起去和雷瑟談一談，然後回到蕨牆村見克羅格。', '和奧格隆一起盤問雷瑟', '去找塵泥沼澤的克羅格。', '', '', '', '', 0);
