INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1274, 'zhTW', '失蹤的使節', '很抱歉，$g先生:夫人;。德拉維主教要我徵召一些冒險者以幫助他解決一件棘手的事情。如果你能儘快而且悄悄地去一趟暴風要塞與他談一談的話，我想他將會非常感謝你的幫助。我得再申明一次，口風請緊一些，這件事情很重要。', '找到暴風要塞的德拉維主教。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1275, 'zhTW', '研究墮落', '愚蠢的血精靈們已經徹底陷入了對魔法的狂熱之中了，難道他們沒有見到卡林多大陸上的薩特與納迦們身上發生了些什麼嗎?$B$B我總覺得血精靈們也將會踏上這樣一條不歸之路，但是艾澤拉斯已經無法再承受多一種被魔法扭曲了心智的怪物了。$B$B我希望能夠研究一下薩特和納迦的腦幹組織，這樣也許就能瞭解那些精靈們的命運將會走向何方。在梣谷海岸邊的黑暗深淵中有許多薩特和納迦，你去那裡找一找吧。$B$B這將會是一段漫長的旅程，一路小心， $N 。', '黑澗營地的芮爾溫·影星需要8塊墮落者的腦幹。', '', '去黑海岸找奧伯丁的戈沙拉·夜語。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1276, 'zhTW', '黑色盾牌', '啊，我想起來了！莫薩恩是個，嗯，他是雷霆崖的一個受人尊敬的鐵匠。我就知道以前肯定在哪兒聽過他的名字。$B$B陶土議會為了感謝我，送了我一套莫薩恩打造的護甲，他的手藝很不錯。$B$B關於莫薩恩打造的盾牌，他自己也許可以告訴你更多。$B$B這不是什麼重要線索，不過既然帕瓦爾·雷瑟還什麼都沒有說，這就是我們所瞭解的全部了。', '把被燻黑的鐵盾牌拿給雷霆崖的莫薩恩看一看。', '', '', '', '', '', '', 0);
