INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1284, 'zhTW', '可疑的蹄印', '有幾排蹄印從樹蔭旅店那仍然冒著煙的廢墟中延伸出來。大部分蹄印都埋在沼澤地的鬆軟泥土裡沒法辨認，不過至少還有一些是可以看清的。', '把樹蔭旅店的可疑蹄印報告給塞拉摩的蓋蘭·維米斯上尉。', '', '', '', '', '', '', 0);
