INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1285, 'zhTW', '戴林的下屬', '雷東……雷德帕斯……啊，找到了！帕瓦爾·雷瑟上尉。$B$B他和大部分跟隨普勞德摩爾女士橫渡大海的徵募兵一起加入了塞拉摩守衛軍。16歲時加入庫爾提拉斯海軍，戰績出色，屢獲提升……$B$B已列入失蹤名單。', '把雷瑟的資料報告給塞拉摩的蓋蘭·維米斯上尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1286, 'zhTW', '背叛者', '在沼澤地裡立足確實是非常艱難的，但是透過不懈的努力，最後我們終於在這一帶守住了幾座防守哨塔。$B$B我收到的最新訊息和偵察報告說一群背叛者佔據了我們在在旅店的西南方的一座廢棄哨塔。$B$B這群背叛者的首領叫加科因，去看看能不能從他身上找到什麼訊息。$B$B小心點，$n。他可是個難對付的傢伙。', '從巴魯斯·加科因及塵泥沼澤的背叛者那裡打探訊息。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1287, 'zhTW', '背叛者', '雷瑟？那個懦夫？$B$B我們把他趕出營地，因為他堅持要襲擊蕨牆村的食人魔，還要搶他們的物資。我們人數不夠，沒法跟那幫不長腦子的畜生鬥。$B$B他不止一次做出過分的事，所以我們就把他趕了出去。$B$B現在我幫了你的忙……那麼，別管你是不是偶然來這兒的，不如幫幫我的忙，別給我惹麻煩了吧？', '和塞拉摩的蓋蘭·維米斯上尉談一談關於雷瑟的事。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1288, 'zhTW', '維米斯的報告', '做的不錯, $N.$B$B普勞德摩爾非常驚奇我的工作,我沒有說我現在還需要一些時間.$B$B我希望把我的報告遲些給她, 但是聽起來我應該現在就和她談一談。 或許你可以更好的回答她的問題.', '把維米斯的報告帶給珍娜·普勞德摩爾，她在塞拉摩.', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1289 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1289, 'zhTW', '維米斯的報告*', '很好, 從維米斯的報告來看, 你在這次調查中幫了很多忙, 在此我感謝你.$B$B噢，我可以空出手來做其它事情了. 如果你願意，你可以回去和維米斯一起把這件事調查完。', '返回塞拉摩，與維米斯交談。', '', '', '', '', '', '', 0);
