INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1300, 'zhTW', '<nyi> <TXT> Lorn Grim Totem', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1301, 'zhTW', '詹姆士·海爾', '在藍色隱士旅店工作之前，我曾在一個頂尖的廚師兼旅店老闆手下學藝，他的名字是詹姆士·海爾。我今天能有這樣的成就都得歸功於他。不知道他現在如何，他和他的兄弟文森到米奈希爾港的一家旅店去工作了，不過最近我一直沒聽到他的消息。你要是碰巧要到米奈希爾去的話，能不能幫我問候他一下?', '和米奈希爾港的文森·海爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1302, 'zhTW', '詹姆士·海爾', '我的兄弟詹姆士跟隨珍娜女士到塞拉摩去了。我最後一次聽到他的消息是說他們在那兒打完了仗，詹姆士還在那裡的某個地方開了個旅店。不管他現在在哪兒，我想他的生意肯定很熱門，他是個很棒的廚師。啊，說起來我已經有一陣子沒聽到他的消息了─旅店的生意太忙了─不過塞拉摩的書記員應該可以幫你找到他。書記應該在市中心的要塞...塞拉摩堡壘。', '和塞拉摩要塞的書記員倫德瑞談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1317, 'zhTW', '戈多克巨魔的事務', '現在你是大王，你可以從那個精靈王子手裡拿回令戈多克驕傲的神器！你前一任的大王失敗了，自從托塞德林那個可惡的$B$B精靈從我們古代戈多克大王手中偷走它之後，沒有一個大王能想辦法把它奪回來！$B$B這個神器叫做戈多克力量護手。傳說說只有真正的戈多克大王才能把它拿回來。這個可惡的精靈還在附近——如果你找到它的話，那你就可以使用它！真的！', '找到戈多克力量護手$B$B，並將它交給厄運之槌的克羅卡斯。$B$B根據克羅卡斯所說的，“傳說”自稱是王子的精靈托塞德林從一名戈多克巨魔手中偷走了那件神器。', '', '去厄運之槌找貧民區廢墟的目擊者格林比克斯！', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1318 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1318, 'zhTW', '戈多克巨魔的事務', '現在你是大王，你可以從那個精靈王子手裡拿回令戈多克驕傲的神器！你前一任的大王失敗了，自從托塞德林那個可惡的精靈從我們古代戈多克大王手中偷走它之後，沒有一個大王能想辦法把它奪回來！$B$B這個神器叫做戈多克力量護手。傳說說只有真正的戈多克大王才能把它拿回來。這個可惡的精靈還在附近──如果你找到它的話，那你就可以使用它！真的！', '找到戈多克力量護手，並將它交給厄運之槌的克羅卡斯。$B根據克羅卡斯所說的，“傳說”自稱是王子的精靈托塞德林從一名戈多克巨魔手中偷走了那件神器。', '', '去銀松森林找芬里斯島的克羅卡斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1319, 'zhTW', '黑色盾牌', '我很抱歉幫不了忙，$n，不過可以給你介紹個能幫忙的人。卡茲·雙鏈是我們最好的鐵匠，他就在鐵匠鋪給人打鐵器。$B$B把盾牌拿給他，看看他能告訴你什麼。', '把被燻黑的鐵盾牌拿給塞拉摩的卡茲·雙鏈看一看。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1320 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1320, 'zhTW', '黑色盾牌', '啊，我差點沒注意到這個……背面的皮帶一定是被燒掉了，不過看上去這條皮帶是給某個身材高大的傢伙用的。我猜是個牛頭人。$B$B我就只能告訴你這些了，告訴維米斯上尉，很抱歉我幫不上別的什麼忙了。', '與塞拉摩的蓋蘭·維米斯上尉談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1321, 'zhTW', '黑色盾牌', '嗯……我看不出這個盾牌有什麼特別之處。我們應該把它拿給鐵匠杜高爾，看看他有什麼說法。不過我也不抱太大希望……', '把被燻黑的鐵盾牌拿給蕨牆村的杜高爾看一看。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1322, 'zhTW', '黑色盾牌', '嗯，在盾牌的邊上這兒刻著字，可惜燒過了讀不出來。$B$B要用些酸液洗乾淨，用沼澤地裡的暗牙蜘蛛的毒液就可以了。那些蜘蛛盤踞在一座舊礦洞裡，現在那裡被稱為黑霧洞穴。給我找點它們的毒囊來，我可以把盾牌清洗一下以便辨認。', '為蕨牆村的杜高爾收集5個酸性毒囊。', '', '去塵泥沼澤找蕨牆村的杜高爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1323, 'zhTW', '黑色盾牌', '呃，我想我大概倒了太多酸液在盾牌上，得擦掉點兒……$B$B嗯……有點難辨認，不過好象是一個叫“莫薩恩”的名字。從來沒聽過這個名字。克羅格認識不少人，他也許知道這個莫薩恩是誰。', '和蕨牆村的克羅格談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1324, 'zhTW', '失蹤的使節', '什麼?!你到這裡來就是為了指控我和迪菲亞兄弟會有勾結?!我無法容許你這麼侮辱我!看來我非得好好教訓教訓你才行。', '擊敗塵泥沼澤的士兵亨德爾。', '制伏二等兵亨德爾', '去找塵泥沼澤的大法師特沃許。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1338 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1338, 'zhTW', '雷矛的訂單', '有一個名叫弗倫·長鬚的矮人鑄甲匠，我很欣賞他做的東西，那手藝簡直是無人能敵。我需要一面新盾牌，而且一定要他親手做出來的盾牌!$B$B問題是……弗倫住在遙遠的南方，在暴風城的矮人區裡。他竟然住在人類的領地裡!我沒法想像他怎麼會住在離鐵爐堡這麼遠的地方，那幫人類一定出了足夠收買國王的大價錢把他給留在那兒!$B$B如果你正好要去那裡旅行一趟，又想順便掙點錢的話，能不能去弗倫那兒讓他給我做一面盾牌?', '把雷矛的訂單交給暴風城的弗倫·長鬚。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1339 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1339, 'zhTW', '巡山人雷矛的任務', '我聽說巡山人雷矛正在找一個為他跑腿的人。你看怎麼樣，要去試試看嗎？$B$B如果願意的話，你就去北邊的哨塔找他吧。', '和巡山人雷矛談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1358, 'zhTW', '給赫布瑞姆的樣本', '在卡林多大陸上我有一個叫做赫布瑞姆的藥劑師同事。他正在研究羅德隆毒素對卡林多大陸的生物所造成的影響。他應該會對倫法洛寄給我的狼心樣本很有興趣。$B$B落腳在貧瘠之地一處名為十字路口的鎮上。要找到他，你必須先搭飛艇到獸人的首都奧格瑪去，然後步行向南去杜洛塔。向西進入貧瘠之地後很快就可以到達十字路口了。', '把狼心樣本交給貧瘠之地的藥劑師赫布瑞姆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1359, 'zhTW', '給金格的貨物', '你拿來我的狼心具有與眾不同的特質。從中提煉出的特殊毒素甚至可以毒死長著這種心臟的狼！$B$B這讓我感到非常驚訝，所以我們必須對此進行深入的研究。把這幾份心臟樣本送到我的同事藥劑師金格那裡。你應該可以在幽暗城的煉金房裡找到她。', '將狼心樣本交給幽暗城的藥劑師金格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1360, 'zhTW', '尋回寶物', '我本來有個不錯的工作，就是在荒蕪之地的奧達曼挖掘場當挖掘工……直到那些該死的穴居人出現之後。我驚險地逃了出來，而且還什麼也沒來得及拿。在一片慌亂之中，我弄丟了我最重要的財產。我那箱子很難撬開是沒錯，不過你知道嗎，那裡滿地都是穴居人!$B$B你去幫我拿回箱子來，我就好好謝你!那個寫著我名字的箱子就在北部大廳的盡頭，你得一路殺進去才行。', '到奧達曼的北部大廳去找到克羅姆·粗臂的箱子，從裡面拿出他的寶貴財產，然後回到鐵爐堡把東西交給他。', '', '去找丹莫洛的克羅姆·粗臂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1361, 'zhTW', '雷戈薩·死門', '有一個名叫雷戈薩·死門的部落戰士正在招募願意前往淒涼之地執行任務的人。如果你願意的話，就去和他談談吧。雷戈薩·死門就在貧瘠之地的十字路口西邊的工事中。$B$B準備好你的武器，淒涼之地是一片危機四伏的土地。', '和雷戈薩·死門談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1362, 'zhTW', '淒涼之地的科卡爾氏族', '科卡爾半人馬居住在淒涼之地，但他們的勢力已經滲透到了貧瘠之地。這是事實，我們已經派了斥候去時刻監視著他們。$B$B只要淒涼之地的半人馬依然足夠強大，對我們而言，他們就是個威脅，我們應該主動出擊清除這個威脅。$B$B去和淒涼之地鬼旅崗哨的費古爾·雙刃談談，他也是被派去收集有關半人馬的情報的，他會知道該如何對付淒涼之地的科卡爾氏族的。', '和淒涼之地鬼旅崗哨的費古爾·雙刃談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1363, 'zhTW', '馬森的請求', '作為魔法和科學學院圖書館的管理員，我的職責是保證所有的魔法書和卷軸隨時在庫。如果這些充滿魔法能量的文字落在邪惡的人手裡，天知道會發生多可怕的事情!啊，我突然想起來……我的助手迪利斯上禮拜犯下了一個可怕的錯誤。他在圖書館裡確實是個好幫手，但他一走出暴風城就幾乎寸步難行。你能幫我把老迪利斯給找回來嗎?', '與暴風城裡的隨從迪利斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1364, 'zhTW', '馬森的請求', '馬森大人的指示再簡單不過了:將這篇重要的文章遞交給守望堡的看守者馬哈爾巴。$B$B但我從來沒有去過詛咒之地!這段路程太可怕了!$B$B我在悲傷沼澤那邊迷了路，被一大群像是植物一樣的沼澤生物給包圍了。它們在我身邊徘徊著，似乎是想要攻擊我，所以我就飛也似的逃了回來……結果我在慌亂中把文章給弄丟了。我敢肯定是有只怪物把它給撿跑了。$B$B你能幫我找回文章並把它送給馬哈爾巴嗎?', '奪回《卡德加的空間收斂研究筆記》，將它送給守望堡的看守者馬哈爾巴。', '', '去找焦土之地的看守者馬哈爾巴。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1365, 'zhTW', '戴茲帕可汗', '科卡爾並不是淒涼之地唯一的半人馬氏族。許多半人馬氏族都遊弋在這片乾燥的平原上，他們相互殘殺，紛爭不斷。他們的窩裡鬥對我們來說不是件壞事，因為半人馬強壯而且殘忍，如果這些半人馬聯合起來對付我們的話，那將是極其可怕的力量。$B$B在他們聯合起來之前，我們必須將他們各個擊破。$B$B你的第一個任務是讓科卡爾氏族出現內亂，只要幹掉他們的首領戴茲帕可汗就可以了。$B$B科卡爾村就在東北方。去吧，祝你好運。', '把戴茲帕可汗的頭顱交給淒涼之地的費古爾·雙刃。', '', '去淒涼之地找鬼旅崗哨的費古爾·雙刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1366, 'zhTW', '懸賞半人馬', '既然你已經震懾了半人馬氏族，那麼現在該讓他們出點血了。開始在淒涼之地獵殺半人馬吧，我不關心你去獵殺哪一個部族，收集半人馬耳朵就是了。$B$B減少他們的數量也就等於削弱他們的野心，打消他們不斷擴張的念頭。$B$B祝你狩獵愉快，$N。', '收集15只半人馬的耳朵，把它們交給淒涼之地的費古爾·雙刃。', '', '去淒涼之地找鬼旅崗哨的費古爾·雙刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1367, 'zhTW', '瑪格拉姆氏族', '要想打敗半人馬，我們就必須讓他們自相殘殺。首先我們要籠絡一支半人馬氏族，利用它們打敗所有的半人馬。$B$B如果你準備和瑪格拉姆氏族結盟，那麼就去殺掉他們的敵人——吉爾吉斯氏族的半人馬，這會使你在瑪格拉姆氏族中贏得尊重。當你得到足夠的尊重之後，就可以去會見瑪格拉姆氏族的首領瓦魯格，他就在淒涼之地東南部的瑪格拉姆村外。', '和瑪格拉姆氏族建立良好的關係，然後和瓦魯格談一談。', '', '去淒涼之地找瑪格拉姆村的瓦魯格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1368, 'zhTW', '吉爾吉斯氏族', '要想打敗半人馬，我們就必須以毒攻毒。我們要先籠絡一支半人馬氏族，利用他們打敗其他的半人馬。$B$B如果你準備和吉爾吉斯結盟，那麼就去攻擊他們最憎恨的對手——瑪格拉姆氏族。在你贏得了吉爾吉斯氏族足夠的尊重以後，就可以去見他們的薩滿祭司，智者烏泰克，他就住在淒涼之地西南的吉爾吉斯村外面。', '和吉爾吉斯氏族建立良好的關係，然後和智者烏泰克談一談。', '', '去淒涼之地找吉爾吉斯村的智者烏泰克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1369, 'zhTW', '破碎之淚', '吉爾吉斯以為半人馬之母瑟拉達絲在護佑著我們，他們都是蠢貨！沒有人在護佑半人馬，瑪格拉姆氏族不需要護佑！我們是最強的！$B$B讓吉爾吉斯半人馬知道他們有多蠢——到他們村莊附近的洞穴裡去一趟，他們把那種名叫瑟拉達絲之淚的水晶石藏在了洞裡。毀掉那些水晶，把碎片交給我！', '繼續和瑪格拉姆氏族保持良好的關係，把3塊破碎之淚交給瑪格拉姆村莊的瓦魯格。', '', '去淒涼之地找瑪格拉姆村的瓦魯格。', '摧毀眼淚', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1370, 'zhTW', '偷取物資', '在作戰之餘，我們為了食物而打獵。肉可以為我們補充力量，吃飽喝足之後作戰會更加勇敢。$B$B瑪格拉姆氏族的半人馬和我們一樣，他們貯藏多餘的肉食，這樣他們就能進行更持久的戰鬥。如果你能去襲擊他們在東部的村莊，並且偷走他們貯藏的肉，他們的力量就會衰竭。', '把6包粗製乾肉交給吉爾吉斯村的智者烏泰克。', '', '去淒涼之地找吉爾吉斯村的智者烏泰克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1371, 'zhTW', '瓦魯格的玩具', '很久以前，有一個小地精來到淒涼之地。他是乘著馬車來的，車上裝著奇怪而有趣、燃燒後會放出五彩繽紛的焰火的東西，還有一些沒有生命、但是居然可以自己移動的東西。我殺了這個小地精，不過在那之前……他讓我樂壞了。$B$B我從他的馬車上拿走了我最喜歡的東西，那是個木頭做的人偶，在我把它砸得粉碎之前，它總是在那裡向我招手。$B$B現在我想要一個新的，幫我弄一個來！', '繼續和瑪格拉姆氏族保持良好的關係，給瑪格拉姆村的瓦魯格找到一個高階假人。', '', '去淒涼之地找瑪格拉姆村的瓦魯格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1372, 'zhTW', '真言藥水', '瓦里瑪薩斯派遣我們這支遠征軍來對艾澤拉斯南部進行偵察。我偶然發現一個人類間諜在乞丐鬼屋附近探頭探腦。我正準備暗中跟蹤他，這個傢伙就被一些…我們的獸人朋友抓去，押進了位於悲傷沼澤裡的斯通納德要塞。獸人們還不知道我們在這裡安營紮寨，不過…我想去幫助他們，幫助我們的獸人盟友。去找法奧斯丁，讓他給我們在斯通納德的朋友製造一瓶真言藥水……', '到乞丐鬼屋去和藥劑師法奧斯丁談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1373 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1373, 'zhTW', '盎格庫', '你還需要更多的行動來證明自己，我要你去很遠的地方完成一個任務，所以從現在開始，吉爾吉斯氏族就要獨自和瑪格拉姆氏族作戰了。$B$B大地把很多的秘密告訴了聆聽它聲音的人，我聽到的秘密是關於一種紅色水晶的。這種被稱作德萊尼水晶的東西最近才出現在這片大陸上，它來自一個遙遠的地方，那裡的山脈在天空中懸浮，惡魔掌控著那裡的一切。$B$B給我帶一片德萊尼水晶碎片來，它能讓我的魔法變得強大無比！這片德萊尼水晶碎片應該就在悲傷沼澤的失落者盎格庫手裡。', '繼續和吉爾吉斯氏族保持良好的關係，並把德萊尼水晶碎片交給淒涼之地吉爾吉斯村的智者烏泰克。', '', '去淒涼之地找吉爾吉斯村的智者烏泰克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1374, 'zhTW', '傑恩可汗', '大地告訴我說，瑪格拉姆氏族變得越來越衰弱了。現在是幹掉他們的可汗的時候了！$B$B把瑪格拉姆氏族的傑恩可汗的頭給我提來！', '把傑恩可汗的頭顱交給淒涼之地吉爾吉斯村的智者烏泰克。', '', '去淒涼之地找吉爾吉斯村的智者烏泰克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1375, 'zhTW', '沙卡可汗', '你幫助了瑪格拉姆氏族，我喜歡你。現在去殺了吉爾吉斯的可汗！他叫沙卡，我要他的腦袋！我要盯著他的腦袋取笑他！', '繼續和瑪格拉姆氏族保持良好的關係，把沙卡可汗的頭顱交給淒涼之地瑪格拉姆村的瓦魯格。', '', '去淒涼之地找瑪格拉姆村的瓦魯格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1380, 'zhTW', '赫蘭薩可汗', '$N，你幫助我們戰勝了瑪格拉姆氏族。現在，請再幫助我們打敗瑪洛迪部族吧！幹掉他們的首領赫蘭薩可汗！$B$B要挑戰他，先要吹響瑪洛迪號角，這把號角就在長矛谷中的一處高聳的峭壁上。$B$B而要吹響號角，你必須得到一隻哨嘴。這種東西很少見，只有赫蘭薩可汗的心腹們才有資格攜帶。$B$B號角一響，瑪洛迪半人馬就會蜂擁而至。放手屠殺他們，直到赫蘭薩出現。$B$B赫蘭薩可汗手裡有一把……一把鑰匙。把這把鑰匙交給我，我就會告訴你有關它的秘密。', '繼續和吉爾吉斯氏族保持良好的關係，把瑪洛迪鑰匙碎片交給吉爾吉斯村的智者烏泰克。', '', '去淒涼之地找吉爾吉斯村的智者烏泰克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1381, 'zhTW', '赫蘭薩可汗', '吉爾吉斯可汗已經被幹掉，現在輪到瑪洛迪了！幹掉他們的首領赫蘭薩可汗！$B$B要挑戰他，先要吹響瑪洛迪號角，這把號角就在長矛谷中的一處高聳的峭壁上。$B$B而要吹響號角，你必須得到一隻哨嘴。這種東西很少見，只有赫蘭薩可汗的心腹們才有資格攜帶。$B$B號角一響，瑪洛迪半人馬就會蜂擁而至。放手屠殺他們，直到赫蘭薩出現。$B$B赫蘭薩可汗手裡有一把……一把鑰匙。把這把鑰匙交給我，我就會告訴你有關它的秘密。', '和瑪格拉姆保持良好的關係，把瑪洛迪鑰匙碎片交給淒涼之地瑪格拉姆村的瓦魯格。', '', '去淒涼之地找瑪格拉姆村的瓦魯格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1382, 'zhTW', '奇怪的聯盟', '我們的確很幸運，半人馬氏族之間正在同室操戈。如果他們擰成一股繩，那將會是一股無法阻擋的力量。沒錯，我們很幸運，所以我們應該緊緊抓住現在的這種優勢。$B$B眾多半人馬氏族中的一支——吉爾吉斯，正在與瑪格拉姆氏族激烈地戰鬥。我希望在我們進攻瑪格拉姆的同時，吉爾吉斯氏族也能同時發動攻擊。$B$B去和智者烏泰克談談吧，他就在淒涼之地西南的吉爾吉斯營地外面。也許我們可以透過他來和吉爾吉斯結成聯盟，同時對瑪格拉姆發起致命的攻擊！', '和吉爾吉斯氏族建立良好的關係，然後和智者烏泰克談一談。', '', '去淒涼之地找吉爾吉斯村的智者烏泰克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1383, 'zhTW', '真言藥水', '我腦中已經想到了合適的藥劑配方，可以讓口風最緊的人喝下之後也知無不言。$B$B要製成這種藥水，我需要幾顆沼澤地中的暗影黑豹的心臟，另外還需要住在那兒的泥沼之王的蘑菇。$n，像你這麼能幹的人一定可以說服他給你一個蘑菇的。$B$B最後的一種材料是綠色幼龍之血，就在伊薩里奧斯的洞穴外的綠色幼龍身上。$B$B事不宜遲，你趕快出發吧!', '乞丐鬼屋的藥劑師法奧斯丁需要5顆暗影黑豹的心臟，一顆泥沼之王的蘑菇和一些綠色幼龍之血。', '', '去找暮色森林的藥劑師法奧斯丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1384, 'zhTW', '突襲科卡爾', '科卡爾半人馬認為他們的魔法很強大，其實他們根本就不知道魔法是什麼東西！即使是把魔法扔在他們臉上，他們也不會知道的！$B$B你去讓他們知道他們的魔法有多麼脆弱吧。去殺了科卡爾氏族的蠢貨們，把他們的咒符帶回來，我要把它們丟進火坑裡，然後放聲大笑！', '和吉爾吉斯氏族保持良好的關係，把10個粗製咒符交給淒涼之地吉爾吉斯村的智者烏泰克。', '', '去淒涼之地找吉爾吉斯村的智者烏泰克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1385, 'zhTW', '野蠻外交', '淒涼之地是一片殺戮場。半人馬氏族之間互相殘殺，我們擔心最後的勝利者會不斷擴張領土，並最終威脅到我們的要塞。我們決不能允許這種情況出現。$B$B我們必須學會如何打敗半人馬氏族，為了打敗他們……我們就必須和諸多半人馬氏族中的一支結盟。瑪格拉姆氏族與吉爾吉斯氏族正在互相征伐，如果你去攻打吉爾吉斯氏族，那麼瑪格拉姆氏族就會視你為盟友。$B$B想辦法得到瑪格拉姆氏族的信任，然後去和瓦魯格談談，他就在淒涼之地東南的瑪格拉姆村裡。', '和瑪格拉姆氏族建立良好的關係，然後和瓦魯格談一談。', '', '去吉爾吉斯找瑪格拉姆村的瓦魯格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1386, 'zhTW', '突襲科卡爾氏族', '科卡爾氏族認為他們很強大，但我們對他們嗤之以鼻！我們殺這些雜碎根本不費吹灰之力！你也可以殺了他們。讓我看看你也是否也能像我們一樣殺死科卡爾半人馬。', '繼續保持和瑪格拉姆氏族的良好關係，殺掉12個科卡爾半人馬，12個科卡爾斥候和6個科卡爾虐待者，然後回到淒涼之地向瑪格拉姆氏族的瓦魯格報告。', '', '去淒涼之地找瑪格拉姆村的瓦魯格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1387, 'zhTW', '懸賞半人馬', '半人馬的社會是由多個部族組成的，每一個部族都有各自的領袖和綱領。所有的半人馬氏族只有一點是相同的：殘忍。$B$B如果我們要尋求和平，就必須先消滅這些半人馬。你的任務就是消滅他們。$B$B在淒涼之地獵殺半人馬，割下他們的耳朵。給我儘可能多帶些半人馬的耳朵回來。$B$B為了聯盟，請一定要這麼做，$N，只有這樣，和平才會降臨這片土地。', '收集15個半人馬耳朵，把它們交給尼耶爾前哨站的麥爾金斯下士。', '', '去淒涼之地找尼耶爾前哨站的麥爾金斯下士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1388, 'zhTW', '真言藥水', '一切都在按照計劃進行，$n。把真言藥水交給萊度斯，他會告訴你怎樣使用它……$B$B哈哈！', '把法奧斯丁的真言藥水交給乞丐鬼屋的亡靈哨兵萊度斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1389, 'zhTW', '德萊尼水晶', '農田避難所裡的那些失落者和我們是同族，但他們已經是瘋狂的怪物了……在我們來到艾澤拉斯的那段殘酷的征途把他們活活逼瘋了！他們現在就住在東邊的農田避難所裡，任何在附近徘徊的人都有可能被他們抓住或殺掉……$B$B他們還偷走了我們的聖物——德萊尼水晶。$B$B我們沒有足夠的力量進入農田避難所去奪回那些被他們扔在小屋和營火附近的水晶，但是失去了那些水晶……我們就會迷失自己的方向。', '給悲傷沼澤避難營地裡的瑪格圖爾帶去6塊德萊尼水晶。', '', '去找悲傷沼澤的瑪格圖爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1390, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1391, 'zhTW', '真言藥水', '要辦成這事，我們還得想點辦法。畢竟你不可能大搖大擺地走進去，然後說服那個傻瓜喝下法奧斯丁配製的藥水，對吧？$B$B不過有一樣東西是這些人類肯定不會拒絕的，那就是酒。我會把法奧斯丁的藥水和這瓶麥酒混合在一起，那個可憐的傻瓜肯定會毫不猶豫地一飲而盡。$B$B趕緊去悲傷沼澤的斯通納德要塞，$n。什麼都不要告訴別人……', '把萊度斯的酒帶給斯通納德的間諜瑪克森。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1392 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1392, 'zhTW', '木棒諾博魯', '避難營裡的的德萊尼人已經被諾博魯虐待了好幾個月了，他的棒子對於這些失落者來說是一種殘忍和暴力的象徵。', '把諾博魯的木棒交到悲傷沼澤中的避難營領導人手中。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1393 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1393, 'zhTW', '加林的逃亡', '請救救我！這些東西想要吃掉我！$B$B幫我離開這兒，我就給你一筆巨大的財富！那筆財富就在斯通納德北部沼澤的營地中，但是被鎖在了一個保險箱裡，只有我知道方法來開啟箱子。$B$B如果你幫我逃走，我就告訴你怎麼拿到那筆財富！', '護送加林逃出困境，然後開啟他放在悲傷沼澤營地裡的保險箱。', '護送加林離開農田避難所。', '去找淚水之池的加林的保險箱。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1394, 'zhTW', '透過試煉', '你做得很好，$N。你已經透過了所有的試煉，現在回到千針石林的多恩那裡去吧。他會感覺到你的變化，他會看出你的思想、身體和精神都已經足夠強大了，而你的努力理應受到嘉獎。$B$B將你在這些測試中所表現的優秀素質繼續保持下去吧，$N。如果你能做到這些的話，多恩將在以後的日子裡再次對你進行試煉。', '和千針石林的多恩·平原行者談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1395, 'zhTW', '守望堡的補給物資', '這能量石木箱要送去位於詛咒之地的守望堡。它們無法長久保持魔法的效力，因此我們恐怕不能等到下一支商隊出發時才讓他們帶去了。$B$B你必須帶著它們，去守望堡，而且動作一定要快。$B$B把它們交給城堡裡的軍需官朗格茲。想到達那裡的話，你必須向東穿越逆風小徑，再向東穿越悲傷沼澤，然後向南穿越詛咒之地。$B$B小心點，$N。你要連續穿越好幾個危險地帶，但是絕對不能失敗。', '在能量石的效力消失以前，把它們交給守望堡的軍需官朗格茲。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1396 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1396, 'zhTW', '逼近的野獸', '我的車隊本來是要去守望堡的，但我們沒能到達目的地。食人魔攻擊了我們，他們殺死了護衛，然後將所有的貨物全都給搶走了，那幫該死的傢伙逃進了逆風小徑。$B$B只有我一個人逃過了他們的襲擊。我曾發誓要保護好那些貨物，發誓要把它們安全送到守望堡！$B$B但這一帶的野獸太多了。拜託，不要讓那群野獸侵入我們的營地！', '殺死8只小鹽齒鱷魚、10只沼澤紡絲蛛和10只沼澤虎，然後向悲傷沼澤的衛兵比格斯報告。', '', '去找悲傷沼澤的衛兵比格斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1397, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1398, 'zhTW', '曬乾的流木', '我對你實在是感激不盡，$N。你有一顆充滿榮耀的心。現在，我想我仍需要謙卑地請您幫我完成另一個任務。$B$B如果我還想到守望堡去的話，就一定得修好這輛馬車。因此……我需要一些木材，我要的是結實的幹木，而不是從那些沼澤中的樹上砍下的像海綿一樣鬆軟的木頭。$B$B$N，請到東邊的海灘上去找些已經被太陽曬乾的流木，把它們給我拿來。', '給悲傷沼澤的衛兵比格斯帶回8塊曬乾的流木。', '', '去找悲傷沼澤的衛兵比格斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1418, 'zhTW', '尼卡·血痕', '可怕的荒蕪之地就在聯盟所控制的洛克莫丹地區南方，因此斯通納德與荒蕪之地中的卡加斯前哨站之間的交流經常中斷。$B$B去證明你自己的實力吧，$N。旅行到荒蕪之地去，與尼卡·血痕談一談，她是卡加斯前哨站的偵察隊長。把她的報告給我拿回來。', '和尼卡·血痕談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1419 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1419, 'zhTW', '捕獵山狗', '$c，你在荒蕪之地呆了很長時間嗎？你感覺到那裡的炎熱了嗎？你是否跟那些在塵土飛揚的平原上到處遊蕩的野獸打過交道？如果還沒有的話，現在是時候了。$B$B峭壁山狗是一種讓人頭疼的猛獸，這些強壯而兇猛的傢伙總喜歡潛入卡加斯，偷走我們的食物補給。幫我們的前哨基地解決掉這些小偷吧！$B$B捕殺這些峭壁山狗，把它們的顎骨拿來見我。帶給我足夠多的顎骨，那樣也許我才會相信你真的瞭解荒蕪之地。', '帶30塊山狗的顎骨去見卡加斯的尼卡·血痕。', '', '去荒蕪之地找卡加斯的尼卡·血痕。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1420 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1420, 'zhTW', '向迅捷的赫格拉姆報到', '我剛寫了一份要交給斯通納德的迅捷的赫格拉姆的報告，請你幫我帶去給他。$B$B千萬別在途中迷了路，也別讓這份報告落到敵人的手中。', '把尼卡的報告帶給斯通納德的迅捷的赫格拉姆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1421, 'zhTW', '丟失的貨物', '那些失落者們攻過來的時候，我一下子就被嚇呆了。等我回過神來，就看見一隻受驚的馬拖著車一路狂奔出去，竄入了北邊的失落者村莊裡。$B$B那輛車上運的是非常貴重的施法材料，都是守望堡的巫師們急需的。找到我們的材料，$N，幫我把它們帶回來。', '在農田避難所中找到商隊的貨物，並拿到巫師的材料，把它交給衛兵比格斯。', '', '去找悲傷沼澤的衛兵比格斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1422, 'zhTW', '海中的威脅', '在我給你打造武器的時侯，為什麼你不去和卡塔爾談談呢？他曾說過需要有人幫忙在海灘上巡邏，我非常樂意看到像你這樣睿智而警覺的$r去協助他，而不是我們這片營地中的某些只會騙酒喝的傢伙。', '與悲傷沼澤的卡塔爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1423, 'zhTW', '遺失的補給品', '這隻木桶不大，但非常堅固。木板的接縫處和桶蓋邊上都用一種味道刺鼻的黃色封蠟封了起來。桶底的標籤上寫著兩行大字：$B$B軍需官朗格茲$B$B守望堡', '把遺失的貨物交給軍需官朗格茲。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1424, 'zhTW', '淚水之池', '酋長大人派我們去調查阿塔哈卡神廟中發生的奇怪現象。$B$B阿塔萊食人妖是由一群使用黑暗法術的施法者組成的部族，以慣於運用禁斷的魔法而著稱。你可以想像一下，當我們到達那裡，卻發現整座廟已經沉入了水中時，我們會有多麼驚訝。$B$B現在那裡被一群自稱是艾澤拉斯保衛者的綠龍佔據著。$B$B我們得弄清楚那裡到底發生了些什麼事。去探索一下淚水之池周圍，收集一些阿塔萊神器。有了這些資訊，我就可以開始把這個謎一點一點地給解開了。', '斯通納德的費澤盧爾要求你收集5件阿塔萊神器。', '', '去找悲傷沼澤的費澤盧爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1425 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1425, 'zhTW', '運送貨物', '$N，在我修車的時候，我另外還有一件工作要交給你。$B$B我已經把從食人魔那裡搶救回來的最重要的幾件貨物都放在了包裹裡，你把它們都帶到守望堡裡去吧。這座城堡就在死亡之地北方的丘陵地帶中，時刻監視著黑暗之門裡的動靜。$B$B你只要順著這條路一直向東走，在第一個岔路口向南進入死亡之地，然後再在第二個岔路口向左轉，就可以到達守望堡了。記住，要一直順著路走，$N，多加小心。', '把貨物帶給守望堡的軍需官朗格茲。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1426 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1426, 'zhTW', '海中的威脅', '我一點都不喜歡大海，更不喜歡那些從深海里游上來的生物。他們都是些強大野蠻而又盲目的蠢貨。要是我有足夠的氣力，我就會去成百上千地屠殺魚人。不過現在我還沒那麼兇悍，所以就只好退而求其次，只要能看見這群魚人死在任何遵從著部落意願的勇士手裡，我也就滿足了。$B$B你怎麼樣呢，$c？你能殺死多少魚人？你願意和魚人當中最強的一群較量較量嗎？', '殺掉10個沼澤魚人、10個沼澤噴墨魚人和10個沼澤食腐魚人，然後向悲傷沼澤的卡塔爾回報。', '', '去找悲傷沼澤的卡塔爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1427, 'zhTW', '海中的威脅', '在你休息之前，記得再去和托克卡爾談談吧，我估計在你離開的時候他就應該把那些武器完成了。為了感謝你的幫助，他會送一把給你。一切都準備就緒以後，你就可以在對抗魚人的過程中好好試一下那把武器了……', '與悲傷沼澤的托克卡爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1428, 'zhTW', '海中的威脅', '看著你對魚人的憎惡也如同我一般地與日俱增，我非常高興。$B$B沿著海灘巡邏，你就可以找到更多的魚人，去殺吧。當你覺得自己殺得夠多了以後就回來找我，我會好好獎勵你一下的。', '殺掉10名沼澤噴墨魚人、10名沼澤食腐魚人和10名沼澤魚人智者，然後向悲傷沼澤的卡塔爾回報。', '', '去找悲傷沼澤的卡塔爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1429, 'zhTW', '阿塔萊流放者', '當你勇敢地在淚水之池周圍冒險的時候，我的斥候帶回了一張用血寫成的卷軸。那看起來像是對阿塔萊部族中的某位祭司的審判書。$B$B這位祭司被判處了阿塔萊部族中的極刑，他的命運將比死亡還要更可怕。$B$B他被放逐到了極北的辛特蘭，被迫與一群枯木食人妖住在一起。$B$我會幫你把這些物品包好的，請你帶著它們去找到這位流放者，或許你能從他那裡得知他們的部族到底使用了怎樣的魔法。任務完成之後，請立刻向我回報。', '將一捆阿塔萊神器交給辛特蘭的阿塔萊流放者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1430 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1430, 'zhTW', '新鮮的螃蟹腿', '最近我的顧客總是會來買鮮嫩多汁的螃蟹肉，特別是那些巨型淤泥蟹的肉。$B$B如果你最近要去海邊轉轉的話，最好能幫我帶一些螃蟹腿到奧格瑪去，我會付你可觀的報酬的。$B$B海岸就在這裡的東邊，那裡遍地都是螃蟹，很容易就可以弄到螃蟹腿。', '給悲傷沼澤的達爾帶去10條巨大的螃蟹腿。', '', '去悲傷沼澤找斯通納德的達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1431, 'zhTW', '聯盟關係', '請等一下，$c，讓我告訴你一些對我們的族人來說非常重要卻幾乎不為人知的東西。$B$B我們獸人是個令人驕傲的種族，而與人類之間的戰爭是如此漫長，就連索爾都有些不耐煩了。你知道的，我們的酋長睿智而謹慎，並總是以他的族人為重。總之，他是一個出色的外交家，在他與人類共同生活的那段日子裡，他也學會了許多人類的行事之道。$B$B如果我剛才說的故事引起了你的興趣，那麼就去找城市西門附近的科爾丹吧。', '與奧格瑪的科爾丹談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1432 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1432, 'zhTW', '聯盟關係', '隨著聯盟在卡林多的推進越來越深入，部落與燃燒軍團有染的錯誤結論一定會流傳開來。酋長可不會允許這樣的事情發生。受酋長所託，我正在負責這個問題的解決。$B$B我已經往淒涼之地派了密探，就在科多獸墳場北部的鬼旅崗哨附近。你的任務是跨過石爪山脈，一直走到山脈的南側，到那裡去找塔卡塔·鋼刃。', '與淒涼之地的塔卡塔·鋼刃談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1433 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1433, 'zhTW', '聯盟關係', '和火刃氏族相關的說法是多如牛毛，但你要知道，這幫傢伙實在是邪惡到家了，他們的精神已經腐朽，他們利用破壞與毀滅來維持並證明自己的存在。$B$B科爾丹派瑪烏林·碎骨者來與我同行，因為瑪烏林對火刃氏族及他們的術士之道都有著充分的瞭解。$B$B他負責策劃針對火刃氏族的行動，而我則負責對付在淒涼之地活動的惡魔。$B$B去和他談一談吧，他會告訴你如何按他的計劃行事。', '去找淒涼之地的瑪烏林·碎骨者談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1434 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1434, 'zhTW', '薩特的威脅', '惡魔是絕對不會憑空就出現的——他們需要一些空隙使邪惡得以立足。$B$B這空隙或許會產生自孱弱的精神，或許是對權力的無謂慾望，或許是對復仇的渴求，或許是要求最終審判的控訴。當我們被痛苦所困擾時，邪惡就會利用我們——例如薩特這樣的邪惡力量。$B$B火刃氏族與它們之間顯然有很緊密的聯絡，因此索爾認為他們必須被清剿乾淨。到東北方向去尋找的它們的蹤影，在將他們驅趕出這一帶後回來向我報告。', '殺死7只怨怒潛行者、7只怨怒魔僕、7只怨怒背叛者和7只怨怒喚魔者，然後向淒涼之地的塔卡塔·鋼刃覆命。', '', '去淒涼之地找鬼旅崗哨的塔卡塔·鋼刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1435 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1435, 'zhTW', '靈魂的燃燒', '對那些為了某些自私的理由而背叛了自己首領的卑劣生物們而言，死亡是他們最合適的歸宿。但對於那些將自己的全部身心奉獻給黑暗的傢伙們來說，死亡還遠遠不夠。$B$B拿著這塊寶石，當你附近有火刃氏族的爪牙死去時，就啟動寶石上面的魔法。這個法術會拯救墮落的靈魂，將它們拉出黑暗的深淵，灌注到寶石裡。$B$B在這些寶石中灌入了靈魂之後，把它們帶回來交給我，我會妥善處置它們。$B$B現在就出發吧，多加小心。', '將15塊燃燒寶石轉變為灌入靈魂的燃燒寶石，然後把它們交給淒涼之地的瑪烏林·碎骨者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1436 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1436, 'zhTW', '聯盟關係', '形勢很順利，$N。如果我們能繼續保持目前的推進勢態的話，或許酋長會允許我們在換季之前回到久別的家園。$B$B回到科爾丹那裡去，告訴他我們都幹了些什麼。我敢打賭他一定會為你在這兒的功績而獎勵你。他的事業對他來說很重要，並且如果酋長也會對他的成就表示敬意的話，他一定會非常自豪。', '與奧格瑪的科爾丹談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1437 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1437, 'zhTW', '瓦拉里爾的搜尋', '你好，$n，我是瓦拉里爾。我到這裡是來尋找達納蘇斯商業世家——瑪雷姆家族的兩個失蹤的孩子。這個家族的族長已做好了最壞的打算，不過我還是要盡一切可能找到他的孩子。我已經開始了搜尋泰拉尼斯和黛琳達的工作，但願一切順利。$B$B我最近得知的線索是，幾周前他們已經越過了石爪山。$B$B如果你發現了他們的蹤跡，就請立刻通知我。', '去淒涼之地尋找泰拉尼斯·瑪雷姆和黛琳達·瑪雷姆的馬車。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1438 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1438, 'zhTW', '瓦拉里爾的搜尋', '找到泰拉尼斯和黛琳達，然後帶著你的發現回來見我。從這座城堡開始進行搜尋吧，我會立刻和達納蘇斯的上級聯絡，讓他們知道這裡的情況。$B$B對了，$N，還有一件事情一定會讓你影響深刻。我的上級最關心的並不是泰拉尼斯以及他在這裡的活動。對他們來說，更重要的是黛琳達能否安全地回來。泰拉尼斯……在他回來之前必須要接受評估。', '去淒涼之地找到黛琳達·瑪雷姆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1439 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1439, 'zhTW', '尋找泰拉尼斯', '獸人殺掉了我們所有的護衛和僕從，然後把我們帶到了這裡。天啊，那真是太可怕了！我以為他們肯定也會殺了我們，不過顯然它們有別的計劃。$B$B泰拉尼斯試圖和他們交涉，我想他試圖用對奧術的瞭解來博得他們的好感……我不知道他為什麼要那麼做。$B$B沒有找到哥哥的下落，我就不離開這裡。找到他，然後再回來救我吧。', '去淒涼之地找到泰拉尼斯·瑪雷姆。', '', '去找淒涼之地的黛琳達·瑪雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1440 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1440, 'zhTW', '回覆瓦拉里爾', '怎麼樣，你準備好了嗎？我感謝你的幫助，如果時間不是太緊的話，請在此時此刻就接受我對你的感謝：感謝你對我和我的家族所做的一切。如果你準備好了，我們就趕快動身離開吧。', '護送黛琳達·瑪雷姆離開雷斧堡壘，然後回到淒涼之地的瓦拉里爾·屠魔者那裡。', '營救黛琳達·瑪雷姆', '去淒涼之地找尼耶爾前哨站的瓦拉里爾·屠魔者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1441, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1442, 'zhTW', '尋找科爾寶石', '你好，$N。我能為你這位追尋神聖之道的人做點什麼呢?$B$B哦，鐵匠史蒂威爾……很久以前的事了，不過我還記得他，有一段時間沒聽到他的消息了。$B$B我知道他絕不是那種卑鄙的人，他想要一塊科爾寶石一定也是為了某種高尚的目的。$B$B如果你真想要科爾寶石，就到梣谷的西北方去。你會在古老的廢墟裡看到黑暗深淵。那些仍然在使用科爾寶石的納迦就聚集在那裡。千萬不要單獨前去，$c。', '帶一塊科爾寶石給黑海岸的桑迪斯·織風。', '', '去黑海岸找奧伯丁的桑迪斯·織風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1443, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1444 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1444, 'zhTW', '向費澤盧爾覆命', '預言者迦瑪蘭宣讀了對我的放逐令，將我從阿塔哈卡神廟中趕了出來。我過去曾認為這位祭司是一位優秀的領導者。$B$B但他對自己的預言能力的過度依賴與盲目的服從一定會導致我們阿塔萊部族的毀滅，這是遲早的事情。$B$B當我說出了我所擔憂的事情時，我被判為異端，從廟裡被趕了出來。$B$B你拿來的這些東西都是無害的。但如果迦瑪蘭找到了能夠啟動召喚儀式的魔法神像，這個世界一定會落入巨大的災難之中……', '向斯通納德的費澤盧爾回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1445 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1445, 'zhTW', '阿塔哈卡神廟', '他提到了迦瑪蘭的預言？$B$B這位阿塔萊部族的精神領袖相信，只要哈卡從扭曲虛空回到艾澤拉斯，這位神祗就將賜予阿塔萊部族的每一個成員以永恆的生命。$B$B若你問我怎麼看，我會說這實在是一個只會帶來災難的愚蠢行為。$B$B你說那個流亡者提到了魔法神像？這令我十分擔心。如果這種東西確實是那個阿塔萊召喚儀式中的必需品，那我們就必須弄清楚這東西中蘊藏著怎樣的力量。$B$B到那個神廟裡去一趟，把這些神像都給我帶回來！', '收集20個哈卡神像，把它們帶給斯通納德的費澤盧爾。', '', '去找悲傷沼澤的費澤盧爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1446 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1446, 'zhTW', '『預言者』迦瑪蘭', '我的枯木同伴們通常對家裡附近的陌生人都不太友善。$B$B我?我已經沒有家了。我被我悲傷沼澤的阿塔萊族的同胞流放到這裡。$B$B我們的精神領袖迦瑪蘭曾有過一個「預言」，他聲稱召喚哈卡能帶給阿塔萊族永恆的生命。$B$B但是我覺得有些不對勁的地方，如果這個預言僅僅是為了操縱我們，那我們該怎麼辦?$B$B我要為他們流放我的舉動復仇，給我把迦瑪蘭的頭帶回來，也許這樣我的同胞就可以重獲自由。', '辛特蘭的阿塔萊流放者想要迦瑪蘭的頭。', '', '去辛特蘭找沙德拉羅的阿塔萊流放者。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1447 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1447, 'zhTW', '失蹤的使節', '是啊，你顯然不是來到暴風城中最聰明的$c，但你有可能成為那些永遠無法離開的大笨蛋之一!$B$B你見過我的」朋友」了嗎?', '擊敗暴風城的達舍爾·石拳。', '擊敗達歇爾·石拳', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1448 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1448, 'zhTW', '調查神廟', '我年輕的時候，也是像你這樣活力充沛，有一股衝勁的。$B$B但現在我老了，也不能像當初那樣在這片大陸上到處冒險了。啊，真是懷念那段日子啊!$B$B但我過去的冒險生涯中卻裡還有一個未解之迷。在我的最後一次任務中，探險者協會派我去調查阿塔哈卡神廟，據說那座廟宇就在悲傷沼澤裡。$B$B但當時我卻感到害怕，只是坐在獅鷲獸上飛過了這片地方，自然，我並沒有找到神廟。$B$B你願意滿足一個老矮人最後的願望嗎?或許你走路過去的話就可以找到神廟……', '暴風城的布羅哈恩·鐵桶要求你去找到阿塔哈卡神廟。', '搜尋阿塔哈卡神廟', '去找暴風城的布羅哈恩·鐵桶。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1449 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1449, 'zhTW', '前往辛特蘭', '正如我之前所說的，我曾經嘗試過獨自從空中尋找那座神殿。事實上，那次我並非獨自行動。我先去位於辛特蘭的鷹巢山上那座著名的獅鷲獸飼養場，在那裡我請他們當中一位最優秀的飛行員幫助我。但是在探險中，那位飛行員從他的坐騎身上掉了下去，一直掉進了沼澤之中……我老了以後，這個可憐人的名字一直出現在我的腦海裡，毫無疑問的。飼養場的管理員應該還記得這件事。到那裡去找弗斯塔德·蠻錘吧。我們得弄清楚那個飛行員到底怎麼樣了。', '到辛特蘭的鷹巢山找男爵族長弗斯塔德·蠻錘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1450 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1450, 'zhTW', '獅鷲管理員', '那麼說你這個$g毛頭小子:小姑娘;來這裡就是給探險者協會裡的某個老頭子跑腿的嗎？$B$B那你聽好了，$c。我根本不知道他說的那個曾經在艾澤拉斯到處飛的老傢伙是誰。你跑來問我這些，難道我臉上寫著“獅鷲管理員沙拉克·鷹斧”這幾個字嗎？嗯？$B$B要是你想飛那麼一次兩次的，幹嘛不去找個正兒八經的獅鷲飼養員呢？你要是還在這裡繼續閒晃的話，那我就真的要給你找點什麼活去做做了。$B$B快走快走。', '與辛特蘭的鷹巢山獅鷲飼養場裡的獅鷲管理員沙拉克·鷹斧談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1451 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1451, 'zhTW', '拉普索迪·鐵鏟', '拉普索迪那傢伙特別愛喝酒，不要誤會我的意思——我們飼養場裡所有的矮人沒事的時候都愛喝上那麼一小口麥酒。$B$B但拉普索迪不一樣，那傢伙一碰見烈酒就跟獅鷲見了天空一個模樣。而且我不得不承認的是，沒人能比拉普索迪這傢伙飛得更好了。$B$B但是自從他勉強和你那位朋友飛回來以後，他就徹底變成了另一個人，因此我們只好讓他走了。$B$B我聽說拉普索迪東邊的某個地方弄了個酒窖。', '去辛特蘭找到拉普索迪·鐵鏟。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1452 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1452, 'zhTW', '拉普索迪的卡林多雞尾酒', '嗝兒！$B$B你是那瘋子加蠢蛋布羅哈恩派來的啊？我們倒是一起經歷過一次大……大冒險……嗝兒！$B$B如果你想要知道我那時候掉進沼澤裡的時候看到了什麼，行，不過我得先喝上一杯好的。要知道那底下可不是什麼美景……嗝兒！$B$B要不這麼著吧……如果你給我弄些原料來配製卡林多雞尾酒，我就告訴你。$B$B至於原材料，先去塔納利斯搞點大鵬的砂囊……然後，然後……我看看……再去菲拉斯弄點格羅多克猩猩和鐵鬃熊的肝臟來……$B$B這便是唯一能開啟我的話匣子的東西，美味的卡林多雞尾酒呀！', '辛特蘭的拉普索迪·鐵鏟要求你帶給他3塊大鵬的砂囊、3塊格羅多克猩猩的肝臟和3塊鐵鬃熊的肝臟。', '', '去找辛特蘭的拉普索迪·鐵鏟。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1453 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1453, 'zhTW', '尋物公司的業務', '我有些工作得要你去淒涼之地一趟，$N。那裡是個非常兇險的地方，滿地都是半人馬和其他討厭的東西。不過如果你想找一份為期一星期的充實工作，就去那兒找克雷迪格·安戈爾，並告訴他是我叫你去的。你可以在尼耶爾前哨站找到他，那是淒涼之地北部山區裡的一個小營地。當你從石爪山進入淒涼之地的時候就向東轉。尼耶爾前哨站不好找，路上要多留心看看。', '和淒涼之地的克雷迪格·安戈爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1454 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1454, 'zhTW', '卡尼託的海難', '我的第一筆訂單來自於法師卡尼託，他是暴風城裡的一個貴族。他的船似乎在西北邊的海岸附近受到了海巨人的襲擊，他和僕人們想把最值錢的一個箱子帶上岸，然而，海巨人成群結隊地發起攻擊，所以他不得不放棄了這個想法，把自己和僕人傳送到了安全的地方。$B$B他希望我們能幫忙找到那隻箱子，並且把它送到暴風城。', '在淒涼之地找到卡尼託的箱子。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1455 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1455, 'zhTW', '卡尼託的海難', '你仔細考慮著到底是什麼東西撬開了箱子，同時觀察著箱子四周和頂部的又長又深的痕跡。顯然，這並不像是某個人或是某個海巨人乾的，而且這些撬痕似乎也不是匕首或者是利劍留下的。$B$B開啟箱子檢查了一番之後，你發現它是空的。$B$B找不到一點頭緒，於是你關上箱子準備離開。克雷迪格一定會很失望。', '回到淒涼之地的克雷迪格·安戈爾那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1456 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1456, 'zhTW', '卡尼託的海難', '真有趣。$B$B其實，我們也不是一點希望都沒有。$B$B在那個海岸更靠北的大海深處，有一片夜精靈的廢墟。一個納迦部落把那裡當成了他們的家，他們管那地方叫什麼來著……滑刺……不，是滑刃部族！我想我們可以去那裡碰碰運氣。$B$B如果有什麼人能夠深入到那麼遠的南部，那他們一定非常強大。如果你要去找卡尼託的東西，那麼就準備對付更加強大的納迦——滑刃潮行者或者滑刃海巫吧。', '找到卡尼託的背包，把它交給淒涼之地的克雷迪格·安戈爾。', '', '去淒涼之地找尼耶爾前哨站的克雷迪格·安戈爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1457 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1457, 'zhTW', '卡尼託的背包', '去把卡尼託的東西交給鐵爐堡的羅頓吧，他會付你報酬的。$B$B哈哈，我敢跟你打賭，他一定會盛情邀請你加入我們的。$B$B再一次感謝你，$n，你幹得很好。$B$B回去的時候要多加小心，別耽誤太多的時間——卡尼託不是那種很有耐心的人，但是毫無疑問，他是非常慷慨的。', '把卡尼託的背包交給鐵爐堡的羅頓·石錘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1458 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1458, 'zhTW', '尋物公司的委託', '我到這裡來的一個主要任務就是幫萊弗維奇收集材料，萊弗維奇是卡拉諾斯城中的一個地精法師。羅頓總覺得這件事對我們來說輕而易舉，卻對我們這裡人手短缺的現狀視而不見。$B$B他列出的清單上的前幾件物品應該很容易找到，如果你幫我找到它們的話，就可以獲得豐厚的報酬。$B$B首先你得從東邊的怨怒薩特身上弄一些角和爪子回來，然後我們再來尋找清單上列出的其它物品。', '收集10只怨怒薩特的爪子和10根怨怒薩特的角，把它們交給淒涼之地的克雷迪格·安戈爾。', '', '去淒涼之地找尼耶爾前哨站的克雷迪格·安戈爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1459 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1459, 'zhTW', '尋物公司的委託', '萊弗維奇貨單上的下一條……我看看……哦，在這裡。$B$B非常簡單，而且說明也寫得非常清楚。他需要荒土蠍的毒液和科多獸的毛皮。清單上寫得很清楚：這兩件東西分別來自兩個特定的物種：毒液來自於荒土鞭尾蠍，而毛皮則來自老邁的科多獸，注意，既不是瀕死的科多獸也不是遠古科多獸。$B$B法師……他們總是要一些稀奇古怪的東西……', '收集7瓶鞭尾蠍的毒液和3塊老邁科多獸的毛皮，把它們交給淒涼之地的克雷迪格·安戈爾。', '', '去淒涼之地找尼耶爾前哨站的克雷迪格·安戈爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1460 AND `locale` = 'zhTW';
