INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1463, 'zhTW', '大地靈契', '', '向坎納甘·地鳴要另一瓶大地靈契。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1464 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1464, 'zhTW', '火焰靈契', '', '向泰爾夫·祖拉姆再要一個 火焰靈契。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1465 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1465, 'zhTW', '瓦拉里爾的搜尋', '當你繼續搜尋馬車的殘骸時，你發現有一串足印一直向南方延伸過去。在遠方有一座巨大的城堡上空煙霧繚繞，那煙霧來自於城堡哨塔上的烽火，而不是房屋的燃燒。你的直覺告訴你：如果瑪雷姆兄妹還活著，那他們一定就在那裡。', '向淒涼之地的瓦拉里爾·屠魔者回復。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1466 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1466, 'zhTW', '尋物公司的委託', '這是物品列表上的最後一些東西了，我不會撒謊，撒謊可不是件光彩的事情。恐怕你得花更多的時間去尋找這些……$B$B我已經說了這麼多了，言歸正傳。萊弗維奇的要求是：從惡魔犬，法師獵手或者靈能獵犬那裡收集大腦；從地獄魔女、地獄巫女或地獄修女那裡收集魔女之翼；還有……從末日守衛隊長或者末日守衛領主那裡收集末日守衛之血。$B$B是不是很簡單啊？呵呵……如果你不想接這項任務的話，我也能理解。', '收集10個惡魔犬的腦子、10對魔女之翼和10瓶末日守衛之血，把它們交給淒涼之地的克雷迪格·安戈爾。', '', '去淒涼之地找尼耶爾前哨站的克雷迪格·安戈爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1467 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1467, 'zhTW', '尋物公司的委託', '要想得到報酬，你就得去一趟鐵爐堡，親自和羅頓談談。他會非常樂意收到萊弗維奇的包裹的。把這個交給他，然後你應該就能收到報酬了。$B$B別擔心，我回去以後會替你美言幾句的，從理論上講我應該不會在這個鬼地方呆太久的。', '把萊弗維奇的包裹交給鐵爐堡的羅頓·石錘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1468 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1468, 'zhTW', '兒童週', '你願意幫助我們的孤兒院?願聖光保佑你，我的朋友。你在兒童週這段時間內對我們的幫助將是無價的。$B$B拿著這個口哨，你只有在這7天內可以使用它－也就是兒童週的這七天。當你使用它的時候，你可以和那些你照顧的孩子進行對話。再次使用就可以解散那個孩子。$B$B不管怎麼樣，$N——使用這個口哨然後去見見你要保護的人!我相信孩子們一定很想見到你。', '使用人類孤兒哨來和你在兒童週期間要照顧的孩子進行對話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1469 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1469, 'zhTW', '拉普索迪的故事', '在出發前，我喝了整整一桶的烈酒。嗝兒！$B$B那是怎樣的一次飛行呀！布羅哈恩跟著我飛了幾圈，還是沒看見廟。嗝兒！$B$B我喝得有點醉了，結果沒抓穩就從坐騎上掉了下去。我一頭栽進了水裡，而且沉到了底兒，這個時候我竟然看見了那座廟。不過很快就從不知道哪裡冒出了一大群巨魔把我給圍了起來，廢話，當然得快溜了！不過我還是從那些巨魔手中搞了點紀念品回來。給，把這個帶給布羅哈恩，告訴他神廟確實就在那下面。嗝兒！', '將阿塔萊石板碎片交給暴風城的布羅哈恩·鐵桶。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1470 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1470, 'zhTW', '控制小鬼', '你好，孩子。以一個術士的標準來看，你還太年輕了些，因為你還無法掌控那些力量。我能感受到你渴望學習的熱切心情。$B$B你也一定能學會的。$B$B無知就沒有力量，知識就是我們最好的武器。運用知識，我們就能控制無序的魔法和虛空之中的生物，讓它們臣服於我們的意志。$B$B我會教你如何讓一個奴僕服從你的意志，但首先你要帶三個斷骨骷髏的顱骨給我，你可以在廢棄的鐵匠鋪附近找到它們。', '收集3個斷骨骷髏的顱骨，把它們交給溫雅·瑪山德。', '', '去提里斯法林地找喪鐘鎮的溫雅·瑪山德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1471 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1471, 'zhTW', '誓縛', '你應該見過下邊的那個召喚法陣了吧？只有站在那上面，你才能召喚出虛空行者來。$B$B用這些符文就可以進行召喚了，但在那之後，無論是用武器還是魔法，你必須擊敗它才能夠對它進行操控。$B$B等虛空行者被你征服之後，它就會與你訂下契約。契約簽定完成之後就過來找我，我會向你說明召喚法術的使用方法，以便你以後隨時召喚它。', '召喚並征服一隻虛空行者，然後將召喚符文還給詛咒神廟中的凱倫丁·哈加爾。', '', '去找提里斯法林地的凱倫丁·哈加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1472 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1472, 'zhTW', '噬魂者', '魅魔是靈魂的吞噬者，心靈的毀滅者，它們以誘惑人類為生，它們的心中只有純粹的邪惡。$B$B在沒有誘餌的情況下，我們是無法將它引入到我們的世界中來的。$B$B因此，我們要以它自身的力量來對抗它。只要有一個真正善良、純潔而博愛的人的心臟，魅魔就將因為無法抵抗這種吸引力而被引入我們的世界。之後，你就要控制它，使它對你俯首貼耳。$B$B與我的助手高德瑞克·法杉談談吧，他就在神殿裡。他會幫你找到你需要的誘餌。', '與詛咒神殿中的高德瑞克·法杉談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1473 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1473, 'zhTW', '虛空中的生物', '看來大家一致認為你已經可以學習如何召喚虛空行者了。$B$B虛空行者是一種由虛空中的混亂力量所構成的實體，如果你召喚出虛空行者但卻不能控制住它的話，你就會被它撕成碎片。$B$B世上第一個虛空行者是埃加林召喚出來的，而在他的魔典中也詳細地寫明瞭整個召喚過程。$B$B不幸的是，這本書被血色十字軍的一個成員給偷走了，他把書藏在十字軍在西邊佔據的一座塔中。把它給我拿回來，然後我就可以把召喚虛空行者的方法傳授給你了。', '奪回埃加林的魔典，把它交給詛咒神廟中的凱倫丁·哈加爾。', '', '去找提里斯法林地的凱倫丁·哈加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1474 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1474, 'zhTW', '誓縛', '在召喚法陣上，以這些心臟為材料施展一個法術，就可以為魅魔開啟一個通向這個世界的通道。儘管你現在的力量已經很強了，但你還是得竭盡全力才能戰勝魅魔。$B$B小心她的魅惑能力，$n，有很多意志堅強的人都被她誘惑，屈從了她的意志。如果你戰勝了魅魔，她將會回到虛空中去，然後我將教你如何召喚這個魅魔，讓她聽你調遣。', '召喚並征服一隻魅魔，然後將純潔的心還給詛咒神廟裡的凱倫丁·哈加爾。', '', '去找提里斯法林地的凱倫丁·哈加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1475 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1475, 'zhTW', '進入阿塔哈卡神廟', '根據傳說，阿塔哈卡神廟是供奉著古代神祗“奪魂者阿塔哈卡”的神聖祭壇，有一個名叫阿塔萊的食人妖部族世世代代守護著這座廟宇，據說從來也沒人能進到廟中去一窺究竟。$B$B潛到淚水之池底部並從廟中取出古代的神器是件很困難的事，但這卻正是我要你去做的，$n。$B$B幫我收集一些完整的阿塔萊石板，把它們帶回來給我，這樣一來我就能以英雄的身份回到探險者協會去了。我會和你一起分享這份榮耀。', '為暴風城的布羅哈恩·鐵桶收集10塊阿塔萊石板。', '', '去找暴風城的布羅哈恩·鐵桶。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1476 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1476, 'zhTW', '純潔者之心', '有榮譽感與善良的人？這種人到底存在過嗎？$B$B在進行了多年的研究並翻閱了無數的典籍與傳說之後，我終於找到了兩個符合我們標準的人。$B$B第一個叫達林·弗治維特，他將自己的全部身心都投入到了拯救那些被遺棄在格雷邁恩之牆外的羅德隆難民的事業中。$B$B另一個叫科馬·韋拉德。此人對他失蹤了的愛人忠貞不渝，一直以來都在溼地中尋找著他的愛人的下落。$B$B把他們的心臟交給凱倫丁，不過首先，讓我先告訴你到哪裡去找。', '將達林和科馬的心臟交給詛咒神殿裡的凱倫丁·哈加爾。', '', '去找提里斯法林地的凱倫丁·哈加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1477 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1477, 'zhTW', '重要的補給', '法師們正在詛咒之地的守望堡裡進行研究，這項重要的研究關係到我們對黑暗之門的瞭解。他們需要持續的補給，然而我們到守望堡的補給線非常脆弱。你必須提供幫助以保證補給物資安全抵達守望堡。到夜色鎮去找守衛隊長索里加爾，按他的指示去做。這次任務要求你進入敵方區域，準備出發吧，$N。', '和守衛隊長索里加爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1478 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1478, 'zhTW', '哈加爾的召喚', '啊，$n！我剛剛收到了凱倫丁·哈加爾託人帶來的口信，他希望你能去接受進一步的訓練。$B$B你應當為此感到自豪，$n。哈加爾先生可不是每天都會私下裡指導年輕術士的。$B$B他在幽暗城的法師區裡，應該就在詛咒神殿旁邊。', '與幽暗城的凱倫丁·哈加爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1479, 'zhTW', '永恆之樹', '我聽說過一個故事，故事裡面說夜精靈的銀行是建在一棵樹裡面的，那棵樹看起來像一頭熊!真是太酷了!夜精靈非常注重保護自然的和諧，但是熊熊聽起來就很可怕!$B$B帶我去看看那棵“熊樹”吧?求求你了!有一條船會帶我們去那裡，一點都不遠。求你了求你了求你了!', '帶著你看護的孤兒去達納蘇斯的銀行。銀行就坐落在一棵中空的樹裡，它被稱為永恆之樹。', '參觀達納蘇斯的銀行。', '去找人類孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1480, 'zhTW', '墮落者', '這片被裁下來的皮子很臭，似乎已經有點腐爛了, 值得注意的是，這塊看上去幹燥而鬆脆的東西卻異常柔軟。$B$B在攤開它之後，你可以清楚地看見其中一面上有著用某種語言寫成的紅色標記文字。在皮子的底端有一個十分清晰的符號，你認為這是個簽名。$B$B也許瑪烏林能告訴你些什麼？', '把惡魔之皮拿給淒涼之地的瑪烏林·碎骨者看看。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1481, 'zhTW', '墮落者', '我可以在擁有適當材料的情況下找到這個惡魔領主。$B$B如果他確實如我推測的一般強大，那我就得先準備一些只有從非常危險的生物身上才能收集到的物品。既然你是為酋長做事的，那麼我想你應該會接受我交付給你的任務吧。$B$B首先，我需要破壞他的反偵測結界。去給我找一塊薩特的頭皮來，不過並不是任何薩特的頭皮都可以的，只有怨怒巡影者的頭皮才能用。$B$B從淒涼之地東北部的古代遺蹟附近開始找起吧。', '給淒涼之地的瑪烏林·碎骨者帶回一張巡影者的頭皮。', '', '去淒涼之地找鬼旅崗哨的瑪烏林·碎骨者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1482, 'zhTW', '墮落者', '如果有一塊神諭水晶就好了。這種東西一般都是由納迦製造出來用於預言的。$B$B從這裡向西北方向走，一直沿著海岸線前進，你會看到一個巨大的珊瑚礁，納迦們通常在那一帶活動。你可以在那裡找到神諭水晶。滑刃納迦並非善類，而且他們也不會對你的闖入表示歡迎，所以你要小心點，動作快點。$B$B等你回來以後，我們就可以開始尋找魔王阿茲雷索克了。', '給淒涼之地的瑪烏林·碎骨者帶回一塊神諭水晶。', '', '去淒涼之地找鬼旅崗哨的瑪烏林·碎骨者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1483, 'zhTW', '菲茲克斯', '風險投資公司偷走了許多最有天分的哥布林創意，不過我們不時地會偷一些回來。不久以前，風險投資公司在石爪山的分支機搆居然雇傭了格雷蘇─一個地精!他們的另一個工程師菲茲克斯只有靠邊站了。他懇求我幫他在技工協會找份工作，我交給他一些任務，不過他或許會需要幫助。也許你能幫他一把?菲茲克斯現在就住在狂風峭壁的西部。', '和狂風峭壁的菲茲克斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1484, 'zhTW', '墮落者', '這傢伙遠比我預料的要危險得多。塔卡塔肯定會懷疑我是否能夠成功地刺殺他，而且如果不把這件事情告訴他的話，實在是對他的侮辱。$B$B去告訴塔卡塔，如果他允許的話，你將去刺殺那個惡魔，不過你也不要太堅持，如果他有別的辦法就最好了。', '與淒涼之地的塔卡塔·鋼刃談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1485 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1485, 'zhTW', '邪靈劣魔', '我們之前的術士，在這裡得到的只有部落的不信任，雖然我們現在得到了一些容忍，但是部落仍然對我們沒有絲毫敬愛。$B$B這令我們術士們更加團結在一起，當然，也有一些人選擇了隱居的生活，獨自研究著他們的魔法。我不會強迫或引導你選擇其中的任何一條道路，只會幫助你變得更加成熟。$B$B在我教會你召喚惡魔的方法之前，先給我帶六顆邪靈劣魔的腦袋回來，在東北方的山洞裡就能找到這種生物。', '給魯贊帶回6顆邪靈劣魔的頭顱。', '', '去杜洛塔找試煉谷的魯贊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1486, 'zhTW', '變異皮革', '由於納拉雷克斯徹底陷入了他的惡夢之中，有一種此前沒有見過的野獸突然侵入了哀嚎洞穴。$B$B這些邪惡的生物有著某種奇怪的、不屬於這個世界的特性。在我看來，雖然它們本性邪惡，但它們的存在對卡林多的居民也並不是完全沒有價值的。我相信它們的皮革在製皮業中可能會非常有用。$B$B如果你願意接下這個任務的話，那就到洞穴深處去，想辦法幫我找一些變異皮革吧。', '哀嚎洞穴的納爾帕克想要20張變異皮革。', '', '去找貧瘠之地的納爾帕克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1487, 'zhTW', '清除變異者', '納拉雷克斯有著一個崇高的目標。$B$B我們這位偉大的領袖一直想要進入翡翠夢境，將那片如今已經變得一片荒蕪的土地變回過去那樣茂密的森林，但似乎有一些可怕的事發生了。$B$B納拉雷克斯的夢境不知為什麼突然轉化成了一場惡夢，同時，大量的墮落生物出現在了洞穴之中。$B$B一些納拉雷克斯的信徒正在想辦法來喚醒我們的領袖，而我此時的職責就是清除洞穴中的那些邪惡生物。$B$B去吧，$n，勇敢地把那些變異的生物都清除乾淨。', '哀嚎洞穴的厄布魯要求你殺掉7只變異破壞者、7只劇毒飛蛇、7只變異蹣跚者和7只變異尖牙風蛇。', '', '去找貧瘠之地的厄布魯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1488, 'zhTW', '墮落者', '雖然我對這個魔王阿茲雷索克一無所知，但我同意瑪烏林的觀點：我們一定要儘快消滅掉這個惡魔，尤其是他正在逐漸控制火刃氏族為他的邪惡目的服務。$B$B到了你實現自己的諾言，為酋長和部落而戰的時候了，我也相信你有能力召集一隻小隊去刺殺這個惡魔領主和他的爪牙。$B$B如果你準備好了，就直接向南方出發，消滅了這個威脅之後就回來向我覆命。', '殺掉魔王阿茲雷索克和祖格卡，然後向淒涼之地的塔卡塔·鋼刃覆命。', '', '去淒涼之地找鬼旅崗哨的塔卡塔·鋼刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1489, 'zhTW', '哈繆爾·符文圖騰', '你帶來的獸皮有一種奇怪的斑點，一種我從來沒有見過的斑點。我確信綠洲裡的水是造成這些斑點的原因，我甚至能夠感受到它們給這片土地帶來的混亂，這片土地現在死氣沉沉的，就好像是長眠不醒了一樣。$B$B哀嚎洞穴一定就是這一切問題的源頭。但是，在你去那裡調查以前，先去找德魯伊長老哈繆爾·符文圖騰談談吧。我託人給他捎了信，把關於在貧瘠之地所發生的一切都轉告給他了。這位博學的長者應該能給你很多忠告。$B$B他就在雷霆崖的長者高地上。', '和哈繆爾·符文圖騰談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1490 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1490, 'zhTW', '納拉·蠻鬃', '我進入了夢境，夢見一群住在哀嚎洞穴的德魯伊。他們曾經是那麼的高貴，但如今卻已經迷失了方向，變成了一股邪惡力量的奴僕，協助他們的主子席捲貧瘠之地。$B$B我已經年老力衰，無法長時間地停留在夢境之中，也無從得知更多有關那些墮落的德魯伊的事情。不過，納拉很年輕，她的精力非常旺盛。當我離開的時候，她還在夢境裡搜尋。去找她吧，她就在那邊的帳篷裡。', '和納拉·蠻鬃談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1491 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1491, 'zhTW', '智慧飲料', '好吧，所以迅猛龍角似乎不太有用。不過沒關係，萬事起頭難嘛!而且我想我找到了另一種原料，可以讓我製造出更好的智慧飲料!$B$B有一種物質名叫哀嚎香精，我想這種東西就是造成貧瘠之地出現各種奇特動植物的原因。幫我找到這種物質，我要把它加入我的飲料裡試試看!$B$B我聽說這種物質可以在西邊的哀嚎洞穴裡的那些生物身上被找到，去獵捕那些生物，幫我收集哀嚎香精吧。', '收集6份哀嚎香精，把它們交給貧瘠之地的麥伯克·米希瑞克斯。', '', '去找貧瘠之地的麥伯克·米希瑞克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1492 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1492, 'zhTW', '碼頭管理員迪茲維格', '我需要把一隻裝有藥品、材料和其他物品的木箱送給我在卡林多的合夥人。我沒時間把它送到棘齒城的碼頭上去，況且最後一支商隊也早已經起航了。$B$B如果你方便的話，請把這只木箱交給碼頭管理員迪茲維格，他會把這只木箱放在下一班開往黑水灣的船上。', '把保險箱交給棘齒城的碼頭管理員迪茲維格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1498 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1498, 'zhTW', '防禦之道', '作為一個 $C ，我們最重要的任務之一就是……保護。我們是部落的護盾，我們要保護比我們弱小的同胞的安全。如果你要加入我們，那你就必須先向我證明你的毅力。$B$B到杜洛塔的雷霆山去，那裡有不少閃電蜥蜴和雷霆蜥蜴。去獵捕那些蜥蜴，向我證明你比牠們更加強大!在牠們的攻擊面前要毫不畏縮，帶一疊牠們燒焦的鱗片回來給我作為證明。$B$B完成這個任務之後，我就教導你。', '帶5塊燒焦的鱗片回來給貧瘠之地前沿哨所的猶塞克。', '', '去找貧瘠之地的猶塞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1499 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1499, 'zhTW', '邪靈劣魔', '祖雷薩正在找你這樣的新手，讓他們到當初你獵殺邪靈劣魔的那個地方旁邊的洞穴裡去，削減那裡的生物數量。$B$B我想你可以在幫助她的過程中學到很多東西。記得跟她說，你是去幫忙解決小鬼問題的，她肯定會準備一份獎勵給你。', '與祖雷薩談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1500, 'zhTW', '喚醒納拉雷克斯', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1501, 'zhTW', '虛空中的生物', '很少有術士能活得夠久的……我們冒著巨大的風險來研究惡魔，風險越大，回報越大。你必須儘快成熟起來，這樣才會成為對酋長和部落有用的人。$B$B現在是該讓你去學習新的召喚法術了。$B$B首先，你必須奪回維爾加石板，那個東西被火刃氏族的術士偷走了，現在石板被儲存在他們的巢穴裡，那個巢穴就在奧格瑪城東的骷髏石。有了石板之後，我會教你如何召喚虛空行者。', '為奧格瑪的甘盧爾·血眼找回維爾加石板。', '', '去找奧格瑪的甘盧爾·血眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1502, 'zhTW', '索恩格瑞姆·火眼', '一柄鑄造精良的武器對於戰士來說是很重要的。獸人這裡最好的武器鑄造師是索恩格瑞姆·火眼，他隱居在十字路口東邊的山上。如果你想要尋求一把稱手的武器，那就去找索恩格瑞姆吧。從這裡往西走，到了十字路口以後再往東進入山區，他的營地就在山頂上。', '與貧瘠之地的索恩格瑞姆·火眼談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1503, 'zhTW', '鍛造好的鋼錠', ' $N ，我會給你一柄武器，但首先我需要你的幫助。幾天前的一個晚上，西北邊的那些鋼鬃部落的傢伙摸進了我的營地，他們不敢和我正面交戰，但是他們知道我眼睛不好使，所以就想辦法用響聲把我引出來，然後派幾個同夥溜進去偷了我的東西!$B$B他們偷走了一隻鐵箱子，裡面是一些鑄造好的鋼錠。如果你能夠找到它們的話，我就會給你一件你用得到的武器。$B$B你應該可以在鋼鬃野豬人的營地裡找到那只鐵箱子，把那些鋼錠給我拿回來。', '把鍛造好的鋼錠帶給貧瘠之地的索恩格瑞姆·火眼。', '', '去貧瘠之地找荊棘嶺的索恩格瑞姆·火眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1504, 'zhTW', '誓縛', '現在，看著這塊維爾加石板，這上面雕刻著的文字會告訴你怎樣進行召喚儀式。把它拿到洞穴另一邊，放在尼爾魯·火刃帳篷裡的法陣上，然後你就可以開始召喚虛空行者了。$B$B無論用格鬥也好，用魔法也好，你必須僅憑自己的力量獨立戰勝它。在這一切都完成之後，帶著石板回來找我，我將為你和這個強大的惡魔制定永恆的盟約。', '召喚並征服一隻虛空行者，然後帶著召喚銘文向奧格瑪的甘盧爾·血眼回報。', '', '去找奧格瑪的甘盧爾·血眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1505, 'zhTW', '老兵猶塞克', '部落非常尊重戰士，因為他們具有毋庸置疑的力量。但是真正偉大的戰士同時也是一個優秀的學生。去找猶塞克吧，他經歷了很多場戰鬥，並且向很多年輕的戰士傳授過精湛的戰鬥技藝。你可以在前沿哨所的南邊找到他，那個地方位於貧瘠之地和杜洛塔的交界處，就在這裡的東邊。', '和前沿哨所的猶塞克談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1506, 'zhTW', '甘盧爾的召喚', '嘿，你！你叫$n，沒錯吧？$B$B你現在不忙吧？甘盧爾要馬上見你。他在暗影裂口和幾個高階術士待在一起。$B$B根據我以前和他打交道的經驗，他找你要麼是有什麼美差吩咐給你，要麼就是你大難臨頭了。', '去奧格瑪和甘盧爾·血眼談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1507 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1507, 'zhTW', '噬魂者', '是時候讓你學些其它的召喚魔法了。你得學習如何召喚魅魔，那是一種具有非常強大的精神力量的惡魔。她會誘惑意志薄弱者，讓他們心甘情願地成為她的奴隸！我覺得你已經有足夠的能力去面對這樣的挑戰了。$B$B魅魔只能在以一件象徵著偉大的愛與奉獻的物品作為媒質的情況下才能被召喚出來，你必須自己去尋找一件這樣的東西。$B$B建議？去和卡祖爾談談吧……這世上沒什麼東西是那個老術士不知道的。', '和暗影裂口的卡祖爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1508 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1508, 'zhTW', '盲眼卡祖爾', '嗯……根本不用問你是為什麼來找我的。$B$B既然是甘盧爾讓你來，那你一定是想要召喚魅魔了，而你現在需要一件東西作為媒質，對吧？$B$B嗯……如果你確信我這個瞎子能夠幫助你的話，那就聽著吧，$n。在奧格瑪城內的通天塔以西的一處斷崖上住著一個名叫贊卡沙的女性。$B$B去找她吧。', '和奧格瑪的贊卡沙談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1509 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1509, 'zhTW', '多格蘭的訊息', '我的丈夫多格蘭最近被派去十字路口值勤了。這對他來說是一種獎賞，令他感到十分自豪。$B$B不過我對此卻不是那麼開心，不過我當然不能讓他知道這些，更不能讓他擔心。大家都說貧瘠之地是一片比奧格瑪要危險得多的土地，在我看來那是世上最糟糕的地方。$B$B他一星期之前就該回來了，但我現在卻仍然沒有得到他的絲毫訊息……$B$B$c，你能不能去一趟十字路口，幫我打聽一下他們那邊有什麼訊息？他與一個名叫加茲羅格的戰士是搭檔，那個加茲羅格應該還在那裡值勤。', '找到十字路口的加茲羅格並和他談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1510, 'zhTW', '多格蘭的訊息', '他是在陶拉祖營地被抓住的。我們當時正在和那裡的野豬人交戰，他帶了一小隊步兵去進攻野豬人的一處營地，但他在那場戰鬥裡受了重傷。其他戰士殺出重圍，然後想要回去救他，但多格蘭的情況很糟糕，他的傷口已經潰爛了，所以他們覺得要是不能先把他治好再帶出來的話，他可能就會因為傷筋動骨而死掉。$B$B所以他們和這裡聯絡了一下，希望能從石爪山的瑪拉卡金那裡的巨魔手裡討些傷藥來。我們已經派人去找巨魔們了，但他們至今還沒有回覆我們。', '找到瑪拉卡金的肯茲格拉並和他談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1511, 'zhTW', '肯茲格拉的傷藥', '我得告訴你們，可能還會有其他人來向我討傷藥，所以我得在這裡隨時做好準備。$B$B快回去吧，$n。你得注意，一開始只能給他一半傷藥！這一半足以讓他在活動的時候不再出血，免得失血過多而死。等過了一個晚上之後再給他另一半。$B$B總之，你得把它帶給陶拉祖營地裡的勞格瑪。根據他派來的上一個信使所說的，他應該已經知道多格蘭被關在哪兒了。', '將肯茲格拉的傷藥交給陶拉祖營地的步兵勞格瑪。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1512, 'zhTW', '愛的禮物', '贊卡沙年輕而美麗，卻得跟一個殘廢過上一輩子……我可不能讓她受這種苦。$B$B別管我了，$n。謝謝你。我將會在戰鬥中光榮地結束我的生命，而不是拖著這破碎的軀殼白白度過後半輩子。$B$B拜託，別把這些告訴我的老婆……我可不想讓她在良心上受譴責。', '把沾滿泥土的墜飾帶給奧格瑪的甘盧爾·血眼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1513 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1513, 'zhTW', '誓縛', '把這個放進尼爾魯帳篷裡的召喚法陣，召喚出那邪惡的魅魔，並將她納入你的掌握。我相信你的魔法能力已經足夠強大了。不過你也要和平常一樣小心，因為驕傲和過分的自信曾經毀滅過不少前途無量的術士。$B$B在你戰勝魅魔以後，把那個墜飾拿給我，我好把訊息告訴給贊卡沙。', '召喚並征服一隻魅魔，然後將多格蘭的墜飾還給奧格瑪的甘盧爾·血眼。', '', '去找奧格瑪的甘盧爾·血眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1514 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1514, 'zhTW', '被腐化的迎風花', '', '', '', '去找費伍德森林的被腐化的迎風花。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1515 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1515, 'zhTW', '多格蘭之囚', '你為這件事兒出了很多力，所以你如果願意幫忙幫到底的話，我當然不會阻止你。但我沒辦法派給你更多的人了，所以你恐怕只能一個人去救多格蘭……$B$B多格蘭被關在北邊的一處野豬人營地裡。注意那裡的兩座小屋子，如果他還沒被殺掉或者因為傷口惡化而死掉的話，那群野豬人應該會嚴密看守他的。$B$B祝你好運。', '把肯茲格拉的傷藥帶給貧瘠之地的多格蘭。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1516 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1516, 'zhTW', '大地的召喚', '是時候了，年輕的$c。你的肉體已經足夠強壯，而你的精神也已如大地一般堅韌。你選擇了遵循薩滿之道，這代表著你擁有無可置疑的睿智。$B$B讓大地來指引你的命運，讓它成為你的一部分吧。但你必須自己去面對大地的力量，如果你已經準備妥當，你就會看見一些只有薩滿祭司才能理解的事物。$B$B去北邊去搜尋那些地獄捕獵者，給我帶一對它們的蹄子回來，然後我們再來好談談你的未來。', '給試煉谷的坎納甘·地鳴帶去2只地獄捕獵者的蹄子。', '', '去杜洛塔找試煉谷的坎納甘·地鳴。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1517 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1517, 'zhTW', '大地的召喚', '靈契是一種可以在我們的靈魂與元素之間建立起連線的特殊藥水。這種融入了魔法的藥水將使完全放開了心靈的你看到別人所不能看到的元素。你的靈魂將會永久地與靈契所對應的元素連線起來，只有我們中的少數被選中的人才知道靈契的製法。$B$B你必須知道一點……只有在神聖的地方喝下靈契才有效，其它任何地方都是不行的。$B$B到這裡西南面的靈魂石地去吧——它就隱藏在一些茂密的藤蔓植物之間。到那裡去把你的靈契喝掉，然後……嗯，到時候你就知道該怎麼做了。', '找到靈魂石地，在那裡喝下大地靈契。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1518, 'zhTW', '大地的召喚', '把這塊劣質石英交給坎納甘·地鳴，以此證實我們會過面了。他將會為你製造一根圖騰，而這塊小圓石則會是圖騰的核心。可能它看上去小了點，不過你馬上就會知道，大小並不重要，即使是最小的石子也可能比山川還要恆久。$B$B耐心一點，$N。繼續保持強健的體魄，並努力追尋智慧吧。這是大地對你的要求。最終，你也將融入大地中，尊重它，它也會尊重你。', '把劣質石英交給試煉谷的坎納甘·地鳴。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1519 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1519, 'zhTW', '大地的召喚', '是時候了，年輕的$c。你的身體已經夠強壯，你的精神如大地一般堅韌，這正是你已經成熟的標誌。$B$B大地引領並教導著我們的族人，以後你也將得到它的指引。但在那之前，你必須先透過試煉。在你完成了試煉之後，就會看到那些只有我們才能看到的東西。$B$B往東邊去，找到刺背野豬人的薩滿祭司，把他們在儀式中使用的藥膏拿回來一些。在你得到了足夠的藥膏之後再回來向我覆命。', '給納拉其營地的鴉羽先知帶回2份儀式藥膏。', '', '去莫高雷找紅雲台地的鴉羽先知。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1520 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1520, 'zhTW', '大地的召喚', '靈契是一種可以在我們的精神和自然的元素之間建立連線的藥水。這種藥水融入了魔法，它可以使開啟了心靈之門的你看到別人所不能看到的元素。你的精神將會永久地與靈契相應的元素連線起來，只有我們中的少數被選中的人才知道靈契的製作方法。$B$B靈契只能在神聖的地方生效，其它的任何地方都不行。$B$B到東邊的薩滿祭壇去，在那裡喝下靈契吧。', '找到科多石並喝下大地靈契。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1521, 'zhTW', '大地的召喚', '把這塊劣質石英交給鴉羽先知，這是我們會過面的證明。她將會為你製造一根圖騰柱，而這塊小圓石則是那根柱子的核心。它可能看上去小了點，不過你馬上就會知道，尺寸並不重要，即使是最小的石子也可能比整座山嶺還要恆久。$B$B耐心一些，$N。在保持著力量的同時追尋智慧吧，這是大地對你的要求。最終你將會成為大地的一份子，尊重它，它也會尊重你。', '將劣質石英帶給納拉其營地的鴉羽先知。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1522 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1522, 'zhTW', '火焰的召喚', '嘿，火焰可是很強大的，孩子。我看你在地系魔法方面還挺有一套，是時候讓你和卡納爾談談了。$B$B卡納爾就住在貧瘠之地，從十字路口一直向北走。他擅長元素魔法，可以教教你怎麼使用火焰……當然你得先做好準備。$B$B你可以很容易地找到他，不過別走太遠——太遠就進入精靈的領地了。', '去貧瘠之地找到卡納爾·菲斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1523 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1523, 'zhTW', '火焰的召喚', '你已經很久沒有接受試煉了，$N。到目前為止，你已經證明了自己有足夠的耐心，現在是時候讓你學習更多東西，是時候讓你瞭解毀滅…和混亂了。只要你明白自己即將為此付出的代價，火焰的元素就會與你建立連線。$B$B到貧瘠之地去找卡納爾·菲斯，他就住在十字路口北部的一間小房子裡。路上小心點，走太遠的話，你就會進入精靈的領地。', '去貧瘠之地找到卡納爾·菲斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1524 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1524, 'zhTW', '火焰的召喚', '你已經有足夠的力量來運用火焰圖騰了，不過這並不意味著你已作好了充分的準備。$B$B沿著杜洛塔的怒水河前進，在河水流入無盡之海的地方，有一條隱蔽的小路，它通向這片大陸上最高的山峰之一。沿著這條小路走到最高處，你就會看到一處由泰爾夫·祖拉姆看守的聖殿，那就是眠炎聖殿。$B$B把這個火炬交給泰爾夫·祖拉姆，它是你試圖馴服火焰力量的證明。用聖殿裡的火盆點燃火炬並把它帶回來，我就會將火焰圖騰交給你。', '把眠炎火炬帶給杜洛塔的泰爾夫·祖拉姆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1525 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1525, 'zhTW', '火焰的召喚', '你該不是到這兒來上歷史課的吧？你是要得到永恆之火和你的火焰圖騰。$B$B首先，你要製造一個靈契，並將你和它連線起來。$B$B只要你給我找來兩樣東西，我就可以為你製造火焰靈契。第一件是火焰焦油，這個相對而言比較簡單，鋼鬃野豬人的施法者通常會帶著這種東西。$B$B另一件則比較危險：從火刃氏族的祭司身上找一個試劑袋。你可以在奧格瑪東部找到他們。', '找到1個火焰焦油和1個試劑袋，把它們交給杜洛塔的泰爾夫·祖拉姆。', '', '去杜洛塔找眠炎聖殿的泰爾夫·祖拉姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1526 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1526, 'zhTW', '火焰的召喚', '火焰靈契已經做好了，現在你必須面對火焰元素的靈魂。在聖殿中使用靈契，然後去挑戰山頂上的火焰之魂。他不會在你沒有準備好的時候就攻擊你，不過他知道你能看見他。$B$B你必須迅速打倒他，$N，拖得越久他的力量就會越強大。在擊敗他之後，將他的餘燼放在火盆裡，然後點燃火炬。', '擊敗火焰之魂，將餘燼放在恆焰聖殿屋頂的火盆裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1527 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1527, 'zhTW', '火焰的召喚', '你手中緊握著火炬離開火盆，望向遠處的杜洛塔，神聖的火焰隨風狂舞，令你感到心中充滿了激動和興奮。$B$B你沿著小路回到貧瘠之地去找卡納爾·菲斯。', '將恆焰火炬交給貧瘠之地的卡納爾·菲斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1528 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1528, 'zhTW', '水之召喚', '從你上次接受測驗到現在已經有很長的時間了，兇殘十三娘。迄今為止，你展示了足夠的耐心，不過現在你應該學到更多的東西，應該去了解水的純潔。去貧瘠之地找到水之先知伊斯倫，沿著怒水河的東岸向棘齒城的南方走，你可以在一間小漁屋裡找到她。祝你好運，兇殘十三娘。', '找到貧瘠之地的水之先知伊斯倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1529 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1529, 'zhTW', '水之召喚', '從你上次接受測驗到現在已經有很長的時間了，$N。迄今為止，你展示了足夠的耐心，不過現在你應該學到更多的東西，應該去了解水的純潔。$B$B去貧瘠之地找到水之先知伊斯倫，沿著怒水河的東岸向棘齒城的南方走，你可以在一間小漁屋裡找到她。祝你好運，$N。', '找到貧瘠之地的水之先知伊斯倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1530 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1530, 'zhTW', '水之召喚', '關於水，有一點是你必須要了解的：水意味著重生。$B$B水流動著，消蝕和清洗一切事物。水的治療和恢復能力是無與倫比的，但這只有在水是完全純潔的情況下。$B$B如果水受到了汙染，那麼它將毀滅一切它接觸到的東西。理解了這一點，你就應該能明白保證水源的純潔性是多麼的重要。$B$B如果你想要得到水之靈契，就到南貧瘠之地去找布瑞恩吧，她的家園最近時常受到野豬人的騷擾。', '到南貧瘠之地去找到布瑞恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1531 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1531, 'zhTW', '風的召喚', '你正在不斷地進步，朋友。你已經證明了自己擁有可以控制風之圖騰的能力，但是首先，你要去千針石林找普拉特·雲眼。如果你給予她足夠尊重的話，她會很樂意告訴你如何得到風之圖騰。$B$B從這裡一直往南穿越貧瘠之地，在你進入千針石林之後再往東走。你會在一座山洞裡找到她和她的男朋友的——哈哈，不要告訴她我說了她那麼多的壞話——否則她可不會放過我，真的。', '到千針石林去找普拉特·雲眼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1532 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1532, 'zhTW', '風的召喚', '卡林多之風正急切地想要見你，而你應該已經成為了我們最強大的$g兄弟:姐妹;之一。我很榮幸能夠看到你的光輝未來。$B$B風元素是一種非常難以控制的元素，但是我相信以你的能力可以克服擋在你面前的一切困難。$B$B到貧瘠之地的最南端，然後從那裡走到千針石林。你可以在千針石林的東部找到普拉特·雲眼，她可以教你更多的東西。', '到千針石林去找普拉特·雲眼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1533 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1533, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1534 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1534, 'zhTW', '水之召喚', '現在，你必須帶上這個水囊，深入到那片被夜精靈稱為梣谷的茂密森林中，那地方就在貧瘠之地的北方。$B$B進入森林之後向西走，順著隔斷石爪山與梣谷的山脈前進，你會在密斯特拉湖的盡頭發現一處聖地：星辰廢墟。在那裡的湖中央有一眼小噴泉。$B$B取回一些噴泉水，那是製作靈契所需的最後一種水樣，然後我就可以把你送回伊斯倫那裡了。', '到梣谷的星辰廢墟去，將空的藍色水囊盛滿泉水，然後把它交給貧瘠之地的布瑞恩。', '', '去貧瘠之地找黑棘山的布瑞恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1535 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1535, 'zhTW', '水之召喚', '要得到我的信任並從我這裡取得靈契，你就必須找到最純潔的水。在你尋找這種水樣時，別忘了注意周圍的動靜。要小心那些依賴這種水生存並守護著它的生物，要注意這種水是如何影響森林和荒漠的。看看這種維持生命的特殊物質是如何強迫這些生物進行殺戮的。$B$B讓我們先從一個簡單的任務開始吧：在我的小屋下面有一小池這種珍貴的液體，裝滿這個水囊後再回來找我。', '到野豬人的水池去，用井中的水裝滿空的棕色水囊，然後把水囊交給貧瘠之地的布瑞恩。', '', '去貧瘠之地找黑棘山的布瑞恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1536 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1536, 'zhTW', '水之召喚', '很久以前，我和一些同伴一起去過希爾斯布萊德丘陵。我們為了保護自己而和那裡的人類作戰，後來發現自己正置身於一個由被遺忘者控制的小鎮：塔倫米爾。$B$B在那裡，我有一個特別的發現：小鎮中心有一口清泉小井。我不清楚鎮中那些被感染的居民是否清楚它的價值——那口井是那片被褻瀆的土地上唯一一塊未受褻瀆的神聖之地。$B$B用這隻水囊幫我帶回一些那口井裡的水。', '用塔倫米爾的井水裝滿空的紅色水囊，然後把它交給貧瘠之地的布瑞恩。', '', '去貧瘠之地找黑棘山的布瑞恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1537 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1537, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1538 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1538, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1558 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1558, 'zhTW', '巨石水壩', '鐵爐堡是矮人和地精的聚居地。在這附近有個地方叫做洛克莫丹，矮人在那裡建造了一座巨大的水壩。他們說那是世界上最壯觀的建築！$B$B你能不能把我帶到洛克莫丹去看看那座水壩呢？我想那座水壩叫巨磚……嗯……巨牆？巨石水壩？它很大——絕對大得讓你吃驚。我想要去看看那裡的巨大瀑布……我保證我絕對會緊緊跟著你的！', '帶著你看護的孤兒去洛克莫丹的巨石水壩。你應該帶他去水壩的中間，然後讓他俯瞰巨大的瀑布。', '參觀洛克莫丹的巨石水壩。', '去找人類孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1559, 'zhTW', '閃光彈的製法', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1560, 'zhTW', '圖加的任務', '我走丟了！$B$B我的妻子托爾塔讓我出來找晚餐，我一定是迷了路！$B$B你能行行好帶我回到托爾塔身邊嗎？她正在熱砂港南部等我。', '把圖加帶回到他的妻子托爾塔身邊。', '把圖加帶回托爾塔身邊', '去塔納利斯找熱砂港的托爾塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1578 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1578, 'zhTW', '前線的補給', '洛克莫丹的巡山人正在和穴居人戰鬥，可真是忙得不可開交呢！要對付那些穴居人，就必須給我們的部隊不斷提供盔甲和武器。$B$B這就是索瓦爾德待在那裡的原因，他在為巡山人籌集足夠的物資好讓他們保持強大的戰鬥力。如果你能打造一些銅斧和銅質鍊甲腰帶並把它們交給索瓦爾德的話，他一定會感激你的，沒準他還會跟你分享他的知識和經驗。$B$B索瓦爾德就在洛克莫丹的南部警戒塔。', '給洛克莫丹南部警戒塔的索瓦爾德帶去6把銅斧和6條銅質鍊甲腰帶。', '', '去丹莫洛找南部警戒塔的索瓦爾德·深爐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1579 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1579, 'zhTW', '小齒輪', '我到奧伯丁來僅僅是因為這裡相當的安靜。我喜歡在安靜的地方進行發明創造，因為在一夜痛飲之後，鐵爐堡的喧囂足以讓我發瘋！$B$B因此我乘船來了奧伯丁，路上喝了不少酒，結果我一不小心就把一盒小齒輪掉在了船上！$B$B我不能確定把它們掉在什麼地方了，但如果你願意到大海里釣釣看的話，也許……', '收集8個小齒輪，把它們交給奧伯丁的維茲班恩·曲針。', '', '去找奧伯丁的維茲班恩·曲針。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1580 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1580, 'zhTW', '導電器', '我們知道你是個幸運星，不過……你到底有多少幸運呢，$N？$B$B有一天晚上，我沿著黑海岸的小路散步，想要找一條河或一片湖來試驗我新發明的自行驅動火爆式誘鴨器，但那時我可能有點醉了……所以我一不留神就睡了過去，幾個小時後醒來的時候已經在奧伯丁了。我的頭髮燒焦了，導電器也都不見了！我一定是把它們丟在水裡了！$B$B也許你能在黑海岸附近的湖泊或是溪流中釣到它們……', '收集12個導電器，把它們交給奧伯丁的維茲班恩·曲針。', '', '去找奧伯丁的維茲班恩·曲針。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1581, 'zhTW', '刃葉的藥劑', '我們的藥草和鍊金原料店發展勢頭很快，但我的丈夫將太多的時間花在混合藥劑上了，我們從來都沒有時間留給彼此。$B$B如果你能弄來一些已經做好了的藥劑，我可以拿一些珍貴的藥草來和你交換，你看怎麼樣？', '給在多蘭納爾的塞拉爾·刃葉帶去6瓶獅王之力藥劑和2瓶初級防禦藥劑。', '', '去找泰達希爾的塞拉爾·刃葉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1582 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1582, 'zhTW', '月光外衣', '達納蘇斯的居民，尤其是像我這樣的手工藝者，都是相當繁忙的。年輕的冒險家們很想在曠野裡試試他們的身手，當然這就需要相應的裝備來做保障。$B$B如果你能幫我搞到足夠多的皮革製品的話，我也許會教你一些高級的製皮技術。', '把1雙雕花皮甲手套、5雙雕花皮甲長靴和5件雕花皮甲披風交給達納蘇斯的洛瑟里亞斯。', '', '去找達納蘇斯的洛瑟里亞斯。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 1598 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1598, 'zhTW', '失竊的典籍', '嘿，說你哪！你叫$n，沒錯吧？$B$B我希望你確實想要成為一名術士，如果你不能執著於自己的信念的話，那你就可能會徹底迷失自我。$B$B我會給你指引，但我首先得確定你是否夠格。$B$B不久前有一個在修道院中修行的學徒逃了出去，加入了迪菲亞兄弟會。為什麼我會對這個如此介意呢？是這樣的，他偷走了一些重要的典籍。$B$B其中有一本正好還是我很想要的，書名叫《虛無靈能》。你去把它給我偷回來，潛行者們應該把這些書藏在了他們農場中的帳篷裡。', '為杜希拉·拉薩雷找回《虛無靈能》。', '', '去艾爾文森林找北郡山谷的杜希拉·拉薩雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1599 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1599, 'zhTW', '開端', '你就是那個每個人都說起的新術士吧。他們一定很喜歡你，不然他們就不會叫我抽出做研究的時間來培訓你了。$B$B你要學的最簡單的一種召喚咒語是召喚小鬼，不過在我把這種咒語傳授給你之前，你必須要證明自己有控制小鬼所必需的魔法技能和身體素質。$B$B從西南洞穴裡的霜鬃食人妖新兵那裡給我拿三個羽毛咒符回來再說。', '給安威瑪爾的阿拉瑪爾·格里姆帶回3個羽毛咒符。', '', '去丹莫洛找寒脊山小徑的阿拉瑪爾·格里姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1618 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1618, 'zhTW', '赤脊山的補給', '並不是只有我們矮人在戰鬥，事實上，我們的人類盟友也忙得不可開交！$B$B赤脊山不斷受到黑石獸人的襲擊，裝備和物資也一直跟不上。如果你能提供一些幫助的話，他們的鐵匠弗納·奧斯古應該會教你一兩招獨家絕活。', '托姆斯·深爐要你給赤脊山的弗納·奧斯古帶去4條銅質符文腰帶和4把銅質大錘。', '', '去赤脊山找湖畔鎮的弗納·奧斯古。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1638 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1638, 'zhTW', '戰士的訓練', '你已經展示了作為一個戰士應有的天賦，$N。但是你現在還很年輕，還有很多東西需要學習。$B$B去和哈里·伯加德談談吧——他通常都在暴風城舊城區的豬和哨聲旅店裡。哈里是個老兵，也是個優秀的老師。他能教你許多一生受用的知識。', '到暴風城找哈里·伯加德談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1639 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1639, 'zhTW', '醉鬼巴托比', '當然，我可以教你。不過，我先要看看你到底有多大的本事。$B$B看見酒吧最裡面的那個醉漢了嗎？就是那個巴托比，我要你去把他的酒杯拿來。$B$B哈哈，如果你瞭解巴托比，你就會明白他是不會輕易把酒杯給你的。', '和巴托比談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1640 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1640, 'zhTW', '擊敗巴托比', '你要什麼？？你瘋了吧？$B$B你想要我的酒杯？來試試看啊！', '打敗巴托比，然後再和他談一談。', '擊敗巴托比', '去找暴風城的巴托比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1641, 'zhTW', '聖潔之書', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1642 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1642, 'zhTW', '聖潔之書', '無論在什麼時候，聖騎士都必須嚴格地遵循聖光之道，因為它是我們力量的源泉。對我們聖騎士來說，為了追求聖潔而苦修並不意味著我們是為了神格而努力—我們的目標是要在各方面都努力完善。雖然和邪惡鬥爭是眼前的當務之急，但是你必須牢記，只有無私地幫助他人才會讓你和艾澤拉斯的人民真正有所區別。同情、耐心、勇敢—這些品德對聖騎士而言，和戰鬥中所表現出來的力量一樣重要。記住這點，永遠不要忘記。', '與暴風城的達索瑞恩·拉爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1643 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1643, 'zhTW', '聖潔之書', '你接下來的任務，$N，就是要在暴風城裡找到一個需要幫助的人，一個心靈純潔動機單純的人。也許是某個樂於幫助別人的人，也許是某個需要指引的人。不管怎樣，這個人必須心地高尚，而且需要你的幫助。完成這件事之後回來這裡，那時我們再來討論關於你的修行之道，以及成為光之聖騎士的意義。', '到暴風城的貿易區找尋斯蒂芬妮·特納。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1644 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1644, 'zhTW', '聖潔之書', '願聖光護佑那些孩子，他們大多因為幾年前那次天譴軍團的襲擊而失去了家庭。$B$B我丈夫約翰為我收集給孩子們做衣服褲子的布料，不過我沒時間做，因為我得成天忙著照顧他們的飲食起居。$B$B什麼?你願意幫忙?讚美聖光，也感謝你，好心的$N。$B$B如果你能給我找點亞麻布來的話,我就能給孩子做衣服了，那可真是幫了我的大忙。', '給暴風城的斯蒂芬妮·特納收集10塊亞麻布。', '', '去找暴風城的斯蒂芬妮·特納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1645 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1645, 'zhTW', '聖潔之書', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1646 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1646, 'zhTW', '聖潔之書', '無論在什麼時候，聖騎士都必須嚴格地遵循聖光之道，因為它是我們力量的源泉。對於我們聖騎士來說，為了追求神聖而進行的幾近苛刻的修行並不意味著我們是為了神格而努力——我們的目標是要在各方面都努力完善。$B$B雖然和邪惡鬥爭是眼前的當務之急，但是你必須牢記，只有無私地幫助他人才是聖騎士區別於普通人的根本要素。同情、耐心、勇敢——這些品德對聖騎士而言，和戰鬥中所表現出來的力量一樣重要。$B$B記住這點，永遠不要忘記。', '與鐵爐堡的蒂薩·熱爐談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1647 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1647, 'zhTW', '聖潔之書', '$N，你的任務是在鐵爐堡裡找到一個需要幫助的人，一個心靈純潔動機單純的人。這也許是某個想要幫助別人的人，也許是某個需要指引的人。不管怎樣，這個人必須心地純樸，而且需要你的幫助。$B$B完成這件事之後再回到我這裡來，那時我們再來談關於你的修行之道，以及成為聖騎士的意義。', '在鐵爐堡的外環區域找到約翰·特納。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1648 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1648, 'zhTW', '聖潔之書', '我和我的妻子在暴風城管理著一家孤兒院，幫助在過去幾年裡因為天譴軍團的襲擊而失去雙親的孩子們。我差不多每個月都要來鐵爐堡收集這裡的居民捐贈的物資，而且我也會和不同的團體商談，儘可能地尋求他們的幫助。$B$B這樣的旅程往往讓人苦惱，因為它很費時間而且收效甚微。$B$B如果能找到些亞麻布來讓我妻子給那些孤兒做些衣服的話，我想我就可以寄些東西回家了。', '收集10塊亞麻布，把它們交給鐵爐堡的約翰·特納。', '', '去找丹莫洛的約翰·特納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1649, 'zhTW', '勇氣之書', '勇氣，以及伴隨著它而共同存在的一切美德，就如同那些珍貴的礦石一般:當你擁有它們的時候，要記得珍惜，因為它們非常寶貴。你也需要花費很大的精力去開採，去提煉。當你恰當地將這些礦石混合起來，一種新的堅不可摧的金屬就會產生，即使是最強大的力量也無法將其破壞。這種來自你的信仰和勇氣的力量必須經過考驗。你必須學會絕不放棄信仰，並瞭解到在聖光之力的庇護下，你可以跨越過凡人根本無法跨越的障礙。', '與暴風城的達索瑞恩·拉爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1650 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1650, 'zhTW', '勇氣之書', '很好!你對此表現出來的毫不猶豫可以清晰地佐證:你已經準備好了，並渴望著進行試煉。那麼，去吧。在西部荒野的長灘最南端的盡頭，有一處臨海而建的小屋。屋裡住著一對名叫斯迪威爾的夫婦。丈夫喬丹·斯迪威爾是一位技藝精湛的鐵匠，他暫時去鐵爐堡會見他的矮人朋友們了。於是他那無依無靠的妻子達芙妮目前一個人在家裡待著。根據線報，迪菲亞兄弟會幾乎已經完全控制了那片地區，勢單力薄的達芙妮或許需要一位元勇士的保護。去吧。', '在西部荒野找到達芙妮·斯迪威爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1651 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1651, 'zhTW', '勇氣之書', '我敢打賭，他們馬上就要再殺過來了，你最好有所準備。$B$B我在屋裡放了一把槍，我會用它來幫你的，不過可別太指望我了，最終你還是得靠自己。$B$B我不知道他們來了多少人，但我敢肯定會比先前來的要多。$B$B祈禱聖光保佑你和我吧，因為……你聽到腳步聲了嗎?他們來了!$B$B準備戰鬥!', '在迪菲亞兄弟會進攻時保護達芙妮·斯迪威爾的安全。$B$B如果你想成功的話，你和達芙妮都不能死在他們的劍下。', '保護黛芬妮·史提威爾', '去找西部荒野的達芙妮·斯迪威爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1652 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1652, 'zhTW', '勇氣之書', '拜託你，請回到達索瑞恩那裡，轉告訴他我現在已經安全了，我一定要好好感謝你和教會。他會派人給正在鐵爐堡的喬丹帶份口信，讓他不要擔心我。啊，我是多麼想念他呀……我都等不及想見他了。', '與暴風城的達索瑞恩·拉爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1653 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1653, 'zhTW', '正義試煉', '事實上，我想喬丹本人會非常感謝你的。我正準備找人給他送個信，讓他知道他的妻子目前很安全，我想你就是個合適的人選。喬丹原本可以成為一名為聖光而戰的聖騎士，不過後來為了繼承他父親的手藝走上了另一條路─他對我們的生活方式非常熟悉，也是我們最忠實的朋友。他應該還在鐵爐堡，白天的時候，喬丹喜歡在室外工作，比如在山裡呼吸新鮮的空氣。', '去和鐵爐堡的喬丹·斯迪威爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1654 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1654, 'zhTW', '正義試煉', '如果你願意接受獎賞的話，我會給你獎賞的。請不要誤會，我的慷慨取決於你能給我多少幫助，不過這樣的同盟關係對你我都有好處。$B$B我可以為你製作一把配得上你的成就的武器，一把象徵著聖騎士的精神和聖光的武器，不過首先，你要給我找到製作這把武器所需的材料。我已經列出了所需的材料，現在得有一個勇敢能幹的人去找到它們。你願意去完成這個任務嗎，$c?', '按照喬丹的武器材料單上的說明去尋找一些白石橡木、精煉礦石、喬丹的鐵錘和一塊科爾寶石，然後回到鐵爐堡去見喬丹·斯迪威爾。', '', '去找丹莫羅的喬丹·斯迪威爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1655 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1655, 'zhTW', '白洛爾的礦石', '啊!你嚇了我一跳，$g先生:小姐;!你沒看到我在思考嗎?$B$B那是什麼?喬丹的礦石…送去鐵爐堡的……啊，這樣啊，我知道你說的是什麼了。那群莫格羅什巨魔搶走了我朋友的礦石，商隊從這裡前往濕地的路上遭到了埋伏。唯一從襲擊中逃出的守衛也在前幾天死掉了─醫者沒能及時趕到。$B$B你想找到那些礦石，就往東北方向去，在洛克湖的另一邊。礦石一定就在那裡的某個地方。', '把喬丹的礦石帶給洛克莫丹的白洛爾·石手。', '', '去找洛克莫丹的白洛爾·石手。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1656, 'zhTW', '未完的任務', '拜託，$N，求求你了，幫我一個忙吧!我正在完成我的力量祭儀，但父親又要求我將這些皮毛送到血蹄村的旅店。$B$B我實在分不開身去同時完成祭儀和父親交付給我的任務。你……能不能替我跑一趟?$B$B在長途旅行之後，旅店可是個休息的好地方。我敢說你到了那裡之後也會同意的。', '將一捆毛皮帶給血蹄村的旅店老闆考烏斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1657 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1657, 'zhTW', '薰死南海鎮', '讓我們為南海鎮的敵人帶來災難，再大肆慶祝萬鬼節吧!$B$B拿一個這種特製的球型臭彈去，它裝滿了噁心至極的臭氣，臭到沒有任何人類 - 或是任何意志微弱的野獸可以忍受的地步。你要把它丟到南海鎮的中心讓它發揮效用，所以準備好一切和聯盟奮戰吧!$B$B當你完成這項任務…這項對我們的貢獻，再回來找我。', '在希爾斯布萊德的南海鎮中心投擲三顆被遺忘者臭彈，然後回去找在提里斯法林地的稻草人節的黑暗召喚者雅恩卡。', '', '去找提裏斯法林地的黑暗召喚者雅恩卡。', '在南海鎮投擲球型臭彈', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1658 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1658, 'zhTW', '破壞稻草人節', '我需要勇者前往提里斯法林地察看稻草人節。說真的 – 去那裡的確很危險。節慶上的守衛都特別兇惡。不過，我們還是要知道今年的節慶有多盛大，還有被遺忘者要在萬鬼節的尾聲帶給我們多少麻煩。$B$B如果你可以接受，前往提里斯法林地並偵查慶典。把資訊帶回來給我，我會給你豐厚的報酬。', '找出提里斯法林地的被遺忘者的稻草人節所在地。完成後回去向南海鎮的哈特曼中士覆命。', '偵察被遺忘者的柳條人節慶', '去找希爾斯布萊德丘陵的哈特曼中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1659 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1659, 'zhTW', '<UNUSED>', '', '', '', '', '', '', '', '', 0);
