INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1665, 'zhTW', '巴托比的酒杯', '好吧，這是我的酒杯。等等！讓我先把酒喝光……給你。', '把巴托比的酒杯交給伯加德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1666, 'zhTW', '治安官哈迦德', '你學會了一些招數，但你應該有一件像樣的武器。我敢打賭，只要你和治安官哈迦德先生談談的話，他一定會幫助你的。$B$哈迦德先生就住在艾爾文森林東谷伐木場的一個莊園裡。他已經退休了，不過他在工作期間曾收集了不少裝備。$B$B告訴他是我派你去的，如果你夠走運的話，他會提供給你一件武器的。', '和治安官哈迦德談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1667 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1667, 'zhTW', '蛀牙傑克', '是伯加德派你來的嗎？是的，我這裡的確有一些剩餘的武器，不過首先有一項任務交給你……$B$B不久以前，一個被稱作蛀牙傑克的迪菲亞混蛋捉弄了我。天很黑，他穿著一件暴風城衛兵的衣服，我還以為他是治安官杜漢呢。他說他要我那個舊的暴風城治安官徽章，我就把徽章給了他……然後他便大笑起來，在我反應過來之前就跑掉了！$B$B幫我取回我的勳章！蛀牙傑克應該是把徽章放在南邊的迪菲亞盜賊營地裡了。', '從蛀牙傑克的營地裡取回治安官哈迦德的徽章，把它交給治安官哈迦德。', '', '去艾爾文森林找石碑湖的治安官哈迦德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1678, 'zhTW', '維吉雷克', '如果你想提高自己在戰士中的地位，那麼你就必須變得更加堅韌一些。我可以教你一些新的技能，不過在此之前，你要向我證明你能夠對付真正的敵人。$B$B維吉雷克是這一地區最強大的食人妖，也是你即將挑戰的對手。他住在霜鬃要塞南方山腳下的棚屋裡。$B$B把維吉雷克的頭顱交給我，讓我看看你的勇氣和力量。', '將維吉雷克的頭顱交給鐵爐堡的穆倫·雷矛。', '', '去找丹莫洛的穆倫·雷矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1679 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1679, 'zhTW', '穆倫·雷矛', '你好，戰士！你有很大的潛力，不過你還要學習更多的技巧才行，穆倫·雷矛是最合適向你傳授這些技巧的矮人。$B$B你可以在鐵爐堡軍事區的軍事大廳裡找到穆倫。當你準備要成為一名真正的勇士的時候，就去和他談談吧。', '和穆倫·雷矛談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1680 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1680, 'zhTW', '托姆斯·深爐', '既然你已經學了幾招，該是為你配備一件像樣的武器的時候了。去和托姆斯·深爐談談吧，他能鑄造一件肯定讓你喜歡的武器。$B$B托姆斯就在鐵爐堡的大鍛爐。', '和托姆斯·深爐談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1681, 'zhTW', '鐵環營地', '我的導師，斯塔基·鐵環，原本在丹莫洛東部的盔枕湖南邊有一處獨家小院。他在那裡向別人傳授鐵匠的技能，他絕對是最棒的。$B$B不過，有一天，他的一個學生帶給他一塊奇特的礦石。鐵環把它叫做陰影礦石，他很希望能用它做點什麼，可是，之後不久……一夥黑鐵矮人襲擊了他的小院。他們殺死了所有的人！$B$B到鐵環的小院去，$N，為我的導師復仇，然後把那塊陰影礦石給我帶回來。', '把陰影礦石交給鐵爐堡的托姆斯·深爐。', '', '去找丹莫洛的托姆斯·深爐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1682, 'zhTW', '灰鐵武器', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1683 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1683, 'zhTW', '沃魯斯·邪蹄', '在我向你傳授知識之前，你必須顯示出決心。$B$B有一個名叫沃魯斯·邪蹄的薩特找到了我們的一口月井，就在班奈希爾獸穴的東南方。他正在井中戲耍，用他邪惡的身軀汙染純潔的井水。$B$B到月井那裡去找到沃魯斯，把他幹掉。把他的角給我帶回來，然後我就會向你傳授更高階的戰士技能。$B$B去月井的路不太好找，但是如果你細心一點的話，應該不會迷路的。', '將沃魯斯的角交給達納蘇斯的艾蘭娜瑞。', '', '去達納蘇斯找戰士區的艾蘭娜瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1684, 'zhTW', '艾蘭娜瑞', '你好啊，勇敢的戰士。你的技能越來越純熟，但戰士這個職業的要求比你想像中的要高很多。要想再進一步，你就必須要找到一個優秀的老師。$B$B艾蘭娜瑞就住在達納蘇斯的戰士區裡，她會成為你的良師。', '和艾蘭娜瑞談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1685 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1685, 'zhTW', '加科因的召喚', '難道不是每次都這樣嗎？！我找了你一整天都不見你的蹤影，等我已經不指望能找到你的時候你卻來了。$B$B你已經浪費我太多時間了，所以現在咱們就少廢話了。加科因大師要召見你進行更多訓練，我覺得你最好還是儘快找到他。$B$B他在已宰的羔羊旅店的地窖裡。順便說一句，他的藏身地點你可得保密，不要讓別人知道了。', '去暴風城的法師區向黑暗縛靈者加科因報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1686 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1686, 'zhTW', '艾魯拉的陰影', '你已經學會很多東西了，$N。現在我們將為你製作一件精良的武器，一件屬於戰士的武器。$B$B要完成這一使命，你必須去一趟黑海岸。$B$B很久以前，有一條船在奧伯丁燈塔附近觸礁，許多裝有月神礦石的箱子沉入了海底。$B$B首先，你必須打敗守護那些礦石的亡魂——艾魯拉的陰影。作為一船之長，她對自己施加了詛咒，變成了一個在海洋深處巡遊的亡魂，時時刻刻保護著船上的貨物。打敗她，摘下她的勳章，然後收集丟失的月神礦石。', '將艾魯拉的勳章和8塊月神礦石交給達納蘇斯的艾蘭娜瑞。', '', '去達納蘇斯找戰士區的艾蘭娜瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1687, 'zhTW', '幽靈燈塔', '有時候，我們孤兒院的院長會在晚上給我們講一些鬼故事。真是太恐怖了！其中有一個故事說在西部荒野的燈塔那裡有一個遊蕩的幽靈。他們說那是一個海盜船長，他的船被別的海盜給搶了。這真是太刺激了！$B$B你能不能把我帶到西部荒野的燈塔那裡去？我想要看看那個幽靈船長是不是真的在那裡！我保證會一直跟著你，而且絕對不會跑開或者惹些什麼麻煩！', '帶著你看護的孤兒去西部荒野海岸邊的燈塔。', '參觀西部荒野海岸邊的燈塔。', '去找人類孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1688 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1688, 'zhTW', '蘇倫娜·凱爾東', '我曾有一個名叫蘇倫娜·凱爾東的學生。她過去和現在的你一樣，一心渴求學習到強大的術士魔法，而且她也擁有著十分了得的天賦。更難能可貴的是，她很年輕，而且很漂亮。我最近又看見她了，那個背叛了我的女人！$B$B那時候她和迪菲亞兄弟會里的一個小賊埃爾蘭·杜德摩爾私奔了。她走掉其實倒也沒什麼，但我曾送給她一條血石頸飾，我必須把它拿回來。$B$B現在她的性命對我來說一點都不重要了。你應該可以在布萊克威爾南瓜田找到她，到那兒去把我的東西給奪回來！', '為暴風城的黑暗縛靈者加科因奪回蘇倫娜的頸飾。', '', '去找暴風城的黑暗縛靈者加科因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1689 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1689, 'zhTW', '誓縛', '你找回了我的頸環並擊敗了蘇倫娜，這證明你有著至少與她勢均力敵的力量。$B$B雖然這麼說，但我還是認為你需要進一步的訓練。你現在已經能夠控制魔法的流動了，這很好，但如果你要想要成為一位優秀的術士，這還遠遠不夠。$B$B我會教你如何控制虛無行者，不過在我教你之前，你得先在召喚法陣上召喚它出來並制服它，無論你用什麼武器都好——劍或者魔法——隨你自己樂意吧。在下面的召喚法陣上使用這個頸飾裡的魔法，然後擊敗從虛無中出現的惡魔。', '召喚並制服一個虛無行者，然後將血石頸飾還給暴風城的黑暗縛靈者加科因。', '', '去找暴風城的黑暗縛靈者加科因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1690 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1690, 'zhTW', '制裁廢土遊民', '你！是你出馬幫助加基森水業公司的時候了！$B$B那些廢土遊牧民幾乎佔據了塔納利斯沙漠上所有的水井！如果得不到這些水井的控制權，那我們的水源供應很快就會出現問題。如果你想幫助我們的話，就去解決那些該死的遊牧民吧！$B$B從這裡往東走，去幹掉10個廢土竊賊和10個廢土強盜，然後立即向我報告。你一定要為我們這些人……呃……哥布林們伸張正義啊，不管怎麼樣，快點行動吧！', '去加基森的東面殺掉10個廢土竊賊和10個廢土強盜，然後向首席工程師比格維茲覆命。', '', '去塔納利斯找加基森的首席工程師比格維茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1691 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1691, 'zhTW', '制裁更多廢土遊民', '現在我們需要你去對付那些更強大的廢土遊牧民。到現在為止你都表現得相當出色，但是如果我們想要奪回水井的話，那麼就必須要幹掉更多的遊牧民！$B$B這次，我要你去殺死他們的遊蕩者和刺客，還有暗法師。你可以在這裡的東南面找到這些傢伙。$B$B說實話，他們都很棘手。但是請你一定要幫忙，我們要取回屬於自己的東西！', '殺死10個廢土暗法師、8個廢土遊蕩者和6個廢土刺客，然後向加基森的首席工程師比格維茲報告。', '', '去塔納利斯找加基森的首席工程師比格維茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1692 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1692, 'zhTW', '鐵匠瑪希爾', '我把你收集到的月神礦石裝進了一隻箱子。把它交給鐵匠瑪希爾，他會幫你打造一件月神武器。$B$B瑪希爾住在靠南的地方，就在這座建築物的另一側。', '把這箱月神礦石交給鐵匠瑪希爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1693 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1693, 'zhTW', '月神武器', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1698 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1698, 'zhTW', '猶魯斯·麥酒', '猶魯斯·麥酒向聯盟所有強大的戰士發出了挑戰。他在赤脊山的湖畔鎮旅店等候著你們，並承諾會給所有通過試煉的戰士提供豐厚的報酬。', '與猶魯斯·麥酒談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1699 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1699, 'zhTW', '往返瑞斯班洞穴', '我把我的挑戰專案稱作“往返瑞斯班洞穴”。要想通過這次挑戰，你要做的就是進入瑞斯班洞穴，然後回到這裡——非常簡單的任務！當然，路上也許會有一些小波折……$B$B你必須在一個小時之內返回這裡，有成堆的赤脊山豺狼人擋在路上，所以你得花些時間打發它們。$B$B在出發之前，請喝下以我的家族名字命名的美酒：熱麥酒！$B$B那麼，你覺得如何？瑞斯班洞穴就在湖畔鎮北面的山腳下，你準備好了嗎？', '進入瑞斯班洞穴，然後在規定的時間內回到猶魯斯·麥酒那裡。$B$B在整個過程中你都不能死掉或者釋放靈魂，否則任務就宣告失敗。', '進入瑞斯班洞穴', '去赤脊山找湖畔鎮的猶魯斯·麥酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1700 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1700, 'zhTW', '格瑞曼德·艾爾默', '幫你鑄造鎧甲的時候，我記下了一些心得體會。我要找個人幫我把這份筆記交給格瑞曼德·艾爾默，他在矮人區的武器店裡。把筆記交給他的時候要顯得低調一點，他對自己的技術有近乎狂妄的自信，根本不願從我這裡學點什麼……', '把弗倫的筆記交給格瑞曼德·艾爾默。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1701 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1701, 'zhTW', '淬火鎖甲', '我已經給了你一面精緻的盾牌，不過我們的合作決不會就此結束。我知道如何鑄造異常堅固的鎧甲，但是鑄造起來並不容易，我需要一些稀有的材料，只要你願意跑跑腿，我保證會為你打造一件。$B$B你覺得怎麼樣，$N？如果你願意接受挑戰的話，我會給你一份列表，上面記載著我需要的材料和到可以找到這些材料的地點。', '收集必需的材料，將它們交給暴風城的弗倫·長鬚。', '', '去找艾爾文森林的弗倫·長鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1702 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1702, 'zhTW', '鑄盾師', '$N，當你完成挑戰時，我就看出你是個厲害的傢伙啦。當然，我說話算話，我會按照承諾給你獎勵……$B$B不過，這件禮物在暴風城。$B$B去跟我的朋友弗倫·長鬚談談吧，他在暴風城的矮人區裡。我敢說他是你見過的最棒的鑄盾師，他欠我一份人情。$B$B給，把這桶熱麥酒交給弗倫，讓他為你製造一副盾牌。那品質絕對讓你滿意！', '將這桶熱酒交給弗倫·長鬚。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1703 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1703, 'zhTW', '瑪希爾', '在幫你鑄造鎧甲的同時，我記下了自己的心得體會。現在我得找個人幫我把筆記交給鐵匠瑪希爾，他住在遙遠的達納蘇斯，但我相信他一定非常希望看看我記錄的這些東西。', '把弗倫的筆記交給瑪希爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1704 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1704, 'zhTW', '科羅莫特·鋼尺', '在幫你鑄造鎧甲的時候，我順手記下了我學到的技術。現在我得找個人幫我把筆記交給科羅莫特·鋼尺。他是鐵爐堡的地精鐵匠，當他知道我學到的技術以後……我敢打賭，他一定會興奮地拔掉鬍子的！', '把弗倫的筆記交給科羅莫特·鋼尺。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1705 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1705, 'zhTW', '燃燒之血', '我很不願意相信弗倫可能發現了什麼新奇的東西。不過，為了確認這一點，我要把他的技術應用到這副新的鎧甲上。如果你能幫我找來這些原料，$N，你就能擁有這樣的一件鎧甲。$B$B要製造這件鎧甲的話，我需要一些燃燒之血和一塊燃燒之石。$B$B我知道唯一能找到它們的地方是暮色森林，那些在羅蘭德末日礦洞裡出沒的夜行狼人擁有燃燒之血，而他們的首領加特斯比爾則擁有燃燒之石。$B$B願好運永遠與你同在, $N.', '把20瓶燃燒之血和1塊燃燒之石交給暴風城的格瑞曼德·艾爾默。', '', '去找艾爾文森林的格瑞曼德·艾爾默。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1706 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1706, 'zhTW', '格瑞曼德的鎧甲', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1707 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1707, 'zhTW', '收集水袋', '你好啊，$N！我叫魯格倫克，如果你想要找些事情幹，我們這裡現在就有一件重要的工作給你！$B$B沒有什麼能比幫我帶回一些廢土水袋來更能令我這個老傢伙開心的了。那可都是我們的水——就是那些混蛋把它們偷走了！你每給我帶回五個廢土水袋來，加基森水業公司就會獎勵給你一個可以用來碰運氣的小包裹。更重要的是，我們會永遠記住你所提供的幫助！', '收集5個廢土水袋，把它們交給加基森的魯格倫克。', '', '去塔納利斯找加基森的操作員魯格倫克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1708 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1708, 'zhTW', '鐵珊瑚', '我希望在我自己的鎧甲上應用弗倫·長鬚的新技術。因為你幫了弗倫的忙，而他又幫了我的忙，所以當我做好鎧甲以後，你可以第一個試用它！$B$B要打造鎧甲的話，我就得弄到一種特別的珊瑚，灼熱珊瑚。它只生長在一個地方——溼地的米奈希爾港南邊的海岸地帶。$B$B只要你給我帶來我足夠多的灼熱珊瑚，我就可以馬上開始鑄造鎧甲啦。快點，$N，我恨不得現在就開始工作！', '收集20塊灼熱珊瑚，把它們交給鐵爐堡的科羅莫特·鋼尺。', '', '去找丹莫洛的科羅莫特·鋼尺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1709 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1709, 'zhTW', '科羅莫特的成果', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1710 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1710, 'zhTW', '曬焦的蛋殼', '我很想測試一下弗倫·長鬚的最新發現，希望能將它用於我正在研究的新式鎧甲上，我認為弗倫的技術一定能產生最好的結果。$B$B你願意幫助我嗎？如果你願意幫我收集製造鎧甲所需的原料，我就會幫你也做一件。$B$B我需要曬焦的巨翼雙足飛龍蛋殼，這種飛龍大都棲息在千針石林的風巢中。在它們的巢下可以找到我要的蛋殼，當你收集了足夠數量的蛋殼之後就趕快回來找我。', '把20個曬焦的蛋殼交給達納蘇斯的瑪希爾。', '', '去達納蘇斯找戰士區的瑪希爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1711 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1711, 'zhTW', '瑪希爾的鎧甲', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1712, 'zhTW', '塞克隆尼亞', '我幾十年來都在關注著這個地方。我關注著，希望有一天能看到強大的塞克隆尼亞被人擊敗。但迄今為止，我還沒有找到一個能打敗風之王的勇士。$B$B也許你就是那個勇士。$B$B證明給我看吧，給我找來召喚塞克隆尼亞所需的東西，這樣你就能證明自己是一個偉大的勇士。也許你能打敗他並奪得他的旋風之心。$B$B這樣的話，我將把這顆心的力量注入一把武器裡，供你在今後的冒險旅程中使用。$B$B這張羊皮紙上寫著我需要的東西。', '把巴斯拉的羊皮紙上列出的東西交給奧特蘭克的『觀風者』巴斯拉。', '', '去奧特蘭克山脈找冰風崗的『觀風者』巴斯拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1713, 'zhTW', '召喚', '我已經準備好儀式要召喚塞克隆尼亞了。當他被召喚出來時，你必須打敗他，然後得到他的旋風之心。我將用它來把塞克隆尼亞的力量注入到一件武器中。$B$B$N，你準備好面對風之王了嗎？', '將旋風之心帶給捕風者巴斯拉。', '', '去奧特蘭克山脈找冰風崗的捕風者巴斯拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1714 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1714, 'zhTW', '流放精華', '', '', '', '去找奧特蘭克山脈巴斯拉的大鍋爐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1715 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1715, 'zhTW', '已宰的羔羊', '哎，以前術士們都在卡茲莫丹由諾姆瑞根的大師訓練，現在我們不得不搬到鐵爐堡這個老鼠洞裡，而且麥格尼又在一直監視我們，所以我們只能把新手都送到暴風城去訓練了。$B$B幸運的是，加科因還算是個有能力的人，你還是能在那裡學到你需要的東西的，不過現在這種樣子還是讓我很冒火！$B$B加科因就在暴風城的“已宰的羔羊”旅店的地下室裡。', '去暴風城的法師區向黑暗縛靈者加科因報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1716 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1716, 'zhTW', '噬魂者', '魅魔是靈魂的吞噬者，心靈的毀滅者，思想的控制者。她腦中永遠只有邪惡的念頭。$B$B這就是你現在要學會召喚並控制的生物，但在沒有誘餌的情況下，你是無法將她引入到我們的世界中來的。$B$B以一件象徵愛的事物作為誘餌，魅魔才會回應你的召喚。在這之後，你只有戰勝她才能將她變為你的工具。$B$B但是找到象徵著愛的東西可不容易，你最好和先知塔卡爾談談。他就住在卡林多大陸的貧瘠之地，靠近陶拉祖營地的地方。', '與貧瘠之地的先知塔卡爾交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1717 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1717, 'zhTW', '加科因的召喚', '$n！沒想到在這兒遇見你，不過我接到指示說要注意你的行蹤。$B$B你應該接受更多訓練了，下一次去暴風城的時候記得去見一下加科因，他正在等你。', '去暴風城的法師區向黑暗縛靈者加科因報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1718 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1718, 'zhTW', '島民', '作為一名戰士，你的名聲越傳越響，$N。現在是時候讓你和其它戰士比試一下，看看你真正的實力了。$B$B在貧瘠之地的海岸附近有一座名叫勇士島的小島，就在棘齒城的南部，強大的戰士們時常在那裡聚會。$B$B他們在那裡相聚，然後互相切磋。$B$B去和勇士島的首席戰士克蘭諾克·馬克雷德談談吧。如果他認為你夠格的話，就會指引你在勇士的道路上更進一步的。', '和克蘭諾克·馬克雷德談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1719 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1719, 'zhTW', '格鬥考驗', '如果你想從我這兒學到什麼，你必須首先通過格鬥考驗。對於我們勇士島上的自認為勇猛而又躍躍欲試的戰士們來說，這是他們必須通過的挑戰，如果你能通過這個考驗，那麼你就證明了自己的價值。$B$B要開始接受考驗的話，就走到那邊人群中的鬥陣中央。圖維基·弗拉海德會知道你已經準備好了，然後他就會派出挑戰者來對你進行考驗。$B$B在戰勝了所有挑戰者之後，他會叫出比格維爾。殺了比格維爾，在限定的時間內回到我這裡來覆命。', '殺掉比格維爾，然後向勇士島的克蘭諾克·馬克雷德回覆。', '走上戰陣開始格鬥考驗', '去貧瘠之地找勇士島的克蘭諾克·馬克雷德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1738 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1738, 'zhTW', '同心樹', '為了你的到來，我撥開時間的迷霧，搜尋了整個世界，終於找到了你在尋找的東西。$B$B在上古戰爭的一場戰鬥中，有一對戀人一起倒下了。在他們死去的地方，一棵同心樹茁壯地生長了起來，那是他們至死不渝的愛情的象徵。$B$B那棵樹應該足以用來引誘魅魔，你可以在梣谷森林西北的奧迪拉蘭廢墟裡找到它。', '從梣谷取回同心樹，把它交給暴風城法師區裡的黑暗縛靈者加科因。', '', '去找暴風城的黑暗縛靈者加科因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1739 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1739, 'zhTW', '誓縛', '你可以使用同心樹之核在下面墓穴裡的召喚法陣中施展一個法術，以此開啟一個供魅魔通行的傳送門。$B$B小心點，$n，即使是意志最堅定的人，也會被魅魔輕易控制。$B$B一旦你成功地擊敗了她並把她投回無盡虛無之後，就回來找我，我會告訴你如何召喚並控制她。', '召喚並制服一個魅魔，然後將同心樹之核還給已宰的羔羊旅店的黑暗縛靈者加科因。', '', '去找暴風城的黑暗縛靈者加科因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1740 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1740, 'zhTW', '索蘭魯克寶珠', '當燃燒軍團中的某個惡魔失寵以後，他們的靈魂就會被囚禁在寶珠中，供他們的法師或者術士差遣。$B$B很多寶珠被賜給了艾澤拉斯的惡魔之僕。即使是一顆破碎的寶珠，仍然可以蘊含著強大的惡魔力量。$B$B索蘭魯克寶珠碎成了兩塊，其中的一塊又被砸成碎片，分發給黑暗深淵中的暮光之錘侍僧使用。另一塊比較大的碎片在影牙城堡的一個巫師的手中。把它們找來給我，我可以用這些碎片重塑寶珠。', '找到3塊索蘭魯克寶珠的碎片和1塊索蘭魯克寶珠的大碎片，把它們交給貧瘠之地的杜安·卡漢。', '', '去貧瘠之地找南貧瘠之地的杜安·卡漢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1758 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1758, 'zhTW', '陰謀之書', '僅僅靠一個簡單的召喚法陣是無法為你召喚出惡魔獵犬來的。$B$B我和我的三個助手會幫助你製造召喚法陣，但是你必須先弄到一本陰謀之書的副本，我們很久之前就把那本書給弄丟了。陰謀之書是當初一批術士為了召喚惡魔獵犬而寫的書。$B$B克羅姆·粗臂也許能給你提供一些幫助，他原本是一個四處巡遊的術士，但是現在卻整天躲在鐵爐堡的圖書館裡苦心研究古代文獻。', '與鐵爐堡的克羅姆·粗臂談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1778 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1778, 'zhTW', '聖潔之書', '我計劃不久後就回到家鄉。幸運的是，斯蒂芬妮在暴風城把孤兒院照顧得不錯，我簡直等不及要見她了。再見，$C。', '與鐵爐堡的蒂薩·熱爐談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1779 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1779, 'zhTW', '聖潔之書', '我希望你帶上這個，$N。它的名字叫生命符記。$B$B你已經顯示了自己的仁慈與耐心，現在我需要你證明在戰鬥和魔法兩個方面的能力。$B$B最近，我的丈夫穆里頓在和黑鐵矮人的戰鬥中負傷歸來，他幾乎丟了性命——一個牧師治好了他所受的傷。$B$B帶上生命符記，和我丈夫談談。如果你能幫助他的話，我們可以再聊聊。願聖光保佑你。', '帶上生命符記，和鐵爐堡的穆里頓·熱爐談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1780 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1780, 'zhTW', '聖潔之書', '我今天就把這些拿給孩子們。你要多加小心，好心的$c。城裡已經很難看到像你這樣樂於助人的$g紳士:女士;了，不過你已經證明了聖騎士決不會拒絕幫助那些陷入困境的人。請多保重。', '與暴風城的達索瑞恩·拉爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1781, 'zhTW', '聖潔之書', '拿著這個，$N。這是生命符記。$B$B你已經證明了自己的仁慈和耐心，現在讓我們看看你是否有能力掌握光明之道的一項最偉大的能力。$B$B我的朋友傑生最近剛從艾爾文森林的英雄崗哨回來，他在那裡遭遇了迪菲亞盜賊，差點就沒命了。現在他正在聖壇邊上接受牧師的治療。$B$B把這個符記帶給他，和他談談。如果你幫得了他，我們很快就能再見面了。願你永享聖光的榮耀。', '把生命符記帶給暴風城的傑生·坦諾姆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1782, 'zhTW', '弗倫的鎧甲', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1783, 'zhTW', '聖潔之書', '我們一直在偵察一些潛伏在盔枕湖以南的黑鐵矮人。我們知道他們出現在那裡決不是什麼好事，因此我和納姆決定靠近些去看看——看看他們的頭目到底下了些什麼命令。$B$B我和納姆發起了突襲，殺掉了一些黑鐵矮人，但他們比我們想像的還要頑強，一大堆黑鐵矮人朝我們撲了過來。納姆讓我來求援，我就跑回來了。$B$B納姆需要幫助，我們一定要儘快，否則我不會安心的。$B$B你能幫助我嗎，$N？', '使用生命符記復活丹莫洛的納姆·法奧克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1784, 'zhTW', '聖潔之書', '在我陷入苦戰以前，我和穆里頓在那座小房子附近幾乎幹掉了一個黑鐵間諜。我們親眼看見他們的頭兒給他一條手令，於是我們就想把他幹掉，然後搶到那條手令。$B$B鐵爐堡議會里的一些傢伙還不相信丹莫洛有黑鐵矮人的存在。只要能得到那條手令，我們不僅能證實他們的確在這個地區活動，還能知道他們到底想要做什麼。$B$B去拿到那份手令，然後把它交給穆里頓，$N。', '從盔枕湖附近的黑鐵矮人那裡取回一份黑鐵手稿，把它交給鐵爐堡的穆里頓·熱爐。', '', '去找丹莫洛的穆里頓·熱爐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1785 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1785, 'zhTW', '聖潔之書', '我的妻子正在那裡驕傲地微笑，你最好快過去和她談談，我想她有些話要和你說。$B$B聖光會保佑你的，偉大的$c。相信有一天，我會邀請你一起來對抗天譴軍團和那些該死的黑鐵矮人。', '與鐵爐堡的蒂薩·熱爐談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1786, 'zhTW', '聖潔之書', '亨茲和我去了英雄崗哨，那地方就在艾爾文森林東北的石碑湖中央的一座小島上。我們聽說迪菲亞盜賊在邊境一帶搞間諜活動，就受命去找到證據交給國王的顧問。我們看見兩個人在鬼鬼祟祟地閱讀什麼文件，就向他們發起了突襲。這時突然出現了很多法師將我們團團包圍。亨茲為我拖住了他們，讓我先逃脫了……這個傻瓜，他為什麼要那麼做……我的兄弟亨茲，他的屍體現在還躺在那裡。你能幫助我們嗎，$N?', '把生命符記帶到艾爾文森林的英烈碑去，復活亨茲·法奧克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1787, 'zhTW', '聖潔之書', '我們以後再來談生命符記的事情吧，現在最重要的是把那份迪菲亞盜賊閱讀過的文件拿回來。如果能得手的話，我們就能證明迪菲亞盜賊混入艾爾文森林了，甚至還有可能瞭解到他們的計畫是什麼。$B$B你覺得你有能力把這些文件從這座小島上的迪菲亞盜賊手裡拿過來嗎?$B$B如果你拿到文件的話，就把它交給傑生，順便告訴他我現在沒事了。', '從石碑湖小島上的迪菲亞巫師手中拿到迪菲亞手稿，把它交給暴風城的傑生·坦諾姆。', '', '去找暴風城的傑生·坦諾姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1788, 'zhTW', '聖潔之書', '在達索瑞恩看過這份文件之後，我會把它交給國王的顧問，不過你現在應該去和達索瑞恩談談。他一定會表揚你的!再次感謝你，$N。我希望我們還能見面。有你這樣的朋友絕對是我的驕傲與榮幸。', '與暴風城的達索瑞恩·拉爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1789 AND `locale` = 'zhTW';
