INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1795, 'zhTW', '誓縛', '如果你已經做好了充足的準備，那麼我們就開始吧。首先讓我來解釋一下整個過程。$B$B第一步是創造出基本的召喚法陣，然後，我的助手將使用導能魔棒來將其強化成為更加強大的法陣。$B$B當以上這些工作都完成之後，由你來誦讀陰謀之書上的咒語，召喚惡魔獵犬。$n，你要當心。惡魔獵犬可是非常強大的生物，我希望你能保護好自己。', '召喚惡魔獵犬並打敗它，然後把陰謀之書交給棘齒城的斯坦哈德·法爾杉。', '', '去找貧瘠之地的斯坦哈德·法爾杉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1796, 'zhTW', '附魔金線血袍', '我要幫你製作的第一件裝備就是長袍，你要負責為我收集若干材料，然後我會把它們組合到一起。這樣你就將擁有有首件能使你變得更加強大的裝備。$B$B首先，你必須給我拿來一件神秘的長袍。你可以去找個裁縫幫忙製作，也可以從其他冒險者手中購買——當然如果你能自己製作的話就更好了。但是無論如何，你要先把神秘的長袍交給我，然後我們才能開始。', '將神秘的長袍交給貧瘠之地的梅納拉·虛無撕裂者。', '', '去找貧瘠之地的梅納拉·虛無撕裂者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1798, 'zhTW', '尋找斯坦哈德', '是該教你召喚惡魔獵犬的時候了，$n。但我現在手裡沒有教你這個法術所必需的材料，所以你得去找另外一個人來教你，也就是斯坦哈德·法爾杉，他是我們的另一個成員。$B$B他就住在哥布林港口城市棘齒城附近。在你到達之前，我會通知他你要過去的。', '與貧瘠之地的斯坦哈德·法爾杉談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1799 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1799, 'zhTW', '寶珠碎片', '很好，那麼我們開始吧。$B$B首先，你必須到裡面去跟我的助手們談談，然後決定自己要走哪條路——他們會給你更詳細的解釋。$B$B然後，你必須到淒涼之地的瑪諾洛克集會所去，從那裡的某個術士身上找到一顆地獄火珠。你要淨化這顆寶珠，隱居在塵泥沼澤南部的一個名叫塔貝薩的法師會幫你完成淨化。她肯定會幫助你，因為我們曾有共同的過去。$B$B我再強調一次，這些任務沒完成之前，你就別回來見我。', '在棘齒城外的塔裡與梅納拉的侍僧們談話，選擇自己修行的方式。$B$B然後給塵泥沼澤的塔貝薩帶去一顆地獄火珠。', '', '去塵泥沼澤找塔貝薩的農場的塔貝薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1800 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1800, 'zhTW', '羅德隆的王座', '在我們很聽話的時候，孤兒院院長就會給我們講述許多偉大的故事，其中的一個就是關於羅德隆的陷落，以及邪惡的阿薩斯是如何殺死自己的父親來奪取政權的。$B$B他這樣做真是太無恥了，$N！等我成長為強大的部落戰士之後，我將為榮譽而戰——而不是為了邪惡的權力！$B$B你願不願意帶我去羅德隆的王座看看呢？王座就在你進入幽暗城之前的那個大廳裡。', '帶著你看護的孤兒去幽暗城電梯外的王座大廳。', '參觀幽暗城電梯外的王座大廳。', '去找獸人孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1801, 'zhTW', '陰謀之書', '要召喚惡魔獵犬並迎接它的挑戰，一個簡單的召喚法陣是不夠的。$B$B我和三個侍僧可以幫你製造法陣，但是你需要一本《陰謀之書》。很久以前我們就把這本書給弄丟了，它是由最早的那批不借助任何外力幫助就召喚出惡魔獵犬的術士寫下的。$B$B也許約拉·安尼森能幫你的忙。這段時間裡，他作為一名製圖師受僱於幽暗城，在古籍方面他知道的比我多。', '和幽暗城的約拉·安尼森談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1802, 'zhTW', '陰謀之書', '它是丟了，不過我知道一些可以幫你找到它的線索。$B$B這本書的複製品只有一本，而且它也已經被損壞了，很大一部分的書頁全都被撕了下來，現在聽說它們落入了千針石林的半人馬手裡。$B$B其餘的部分在南海鎮的西岸丟失了，原本這些書頁是要用船送往米奈希爾港的，不過卻從來也沒能送到。$B$B你看，我告訴了你這麼多訊息，好歹你也得在找回東西以後拿來給我看看吧？', '為鐵爐堡的克羅姆·粗臂找回發黴的書籍和破損的手稿。', '', '去找丹莫洛的克羅姆·粗臂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1803, 'zhTW', '陰謀之書', '啊！你果然是個品位與我相當的術士呀。事實上，能得到陰謀之書一直是我的一大心願。你知道那本書一度曾被儲存在羅德隆城裡嗎？然而，那本書如今已經被摧毀了，大部分的書頁都不見了。到底是哪個白痴幹出這樣可憎的事？$B$B據說，失落的那一半目前在千針石林中的一群半人馬手裡。$B$B剩下的另一半本來是要被轉移到鐵爐堡去的，不過在押運過程中丟失在了南海鎮西部的海灘上。', '給幽暗城的約拉·安尼森帶回發黴的書籍和破損的手稿。', '', '去找提里斯法林地的約拉·安尼森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1804, 'zhTW', '陰謀之書', '唉……我真是恨不得一輩子都抱著這本書。不過既然這是你找到的，而且你還要用它做更重要的事，我還是把它還給你吧……不過，請你一定要告訴斯坦哈德幫我抄寫一本。$B$B對了，你去找書的時候，他託人帶了個訊息過來，讓我告訴你說他的助手要協助進行召喚，不過你必須幫他找到3根導能魔棒。$B$B斯坦哈德可能不知道要到哪裡去找導能魔棒，不過我碰巧知道！龍喉氏族的獸人法師們手上應該還有一些這種魔棒。', '將翻修過的書籍和3根導能魔棒交給棘齒城的斯坦哈德·法爾杉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1805, 'zhTW', '陰謀之書', '這書上寫的東西是我這幾年中看過的文章裡最有趣的。這邊的書很少，選擇也很少——大多數的書都是地理方面的——而且，我都把它們翻來覆去地讀了好些遍了。我真希望斯坦哈德能抽空給我也送一本這樣的書來。$B$B去和他談談吧，他在你離開的時候託人給我帶來了口信，說是要交給你一個任務，要求你找回三根召喚魔棒。$B$B當然，為了答謝你允許我繼續看這本書，我告訴你一個小秘密：你可以在溼地的獸人龍喉氏族那裡找到你要的東西。', '將翻修過的書籍和3根導能魔棒交給棘齒城的斯坦哈德·法爾杉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1806, 'zhTW', '正義試煉', '我們現在就到熔爐邊上去開始工作吧！我已經為你的到來準備很久了，現在不用再等了。$B$B在我們完成這把武器之後，你就可以更好地為聖光而戰，這一點我絕對可以保證。$B$B說實話，$N，看到你所取得的這些成績，我真有點羨慕。不過我知道我也可以用我自己的方式給你提供一些幫助，這樣就已經讓我很高興了。', '等待喬丹·斯迪威爾為你鑄造武器。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1818, 'zhTW', '迪林格爾', '亡靈衛兵迪林格爾告訴我有一份工作可以交給像你這樣的$c。如果你想要為黑暗女王效力的話，那就馬上去迪林格爾那邊報到吧。$B$B亡靈衛兵迪林格爾在布瑞爾最西邊執勤，就在墓地的旁邊。', '和布瑞爾的亡靈衛兵迪林格爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1819, 'zhTW', '『斬擊者』奧拉格', '當天譴軍團席捲提里斯法林地的時候，我們曾經抓住他們中的一員進行研究。他具有自己的意志，並自稱為『斬擊者』奧拉格。但是，雖然他的意志是自由的，但他仍然只是一個被巫妖王掌控和奴役著的傀儡。$B$B我們希望能夠讓他脫離巫妖王的控制，但是失敗了。現在，我看是時候讓他徹底地“解脫”了。$B$B讓他解脫，殺了他。$B$B啟用北部陵墓那裡的顱骨石機關，解除奧拉格身上的魔法封印。$B$B然後……做好準備，$N。', '殺死『斬擊者』奧拉格，然後和亡靈衛兵迪林格爾談一談。', '', '去提里斯法林地找布瑞爾的亡靈衛兵迪林格爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1820 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1820, 'zhTW', '庫勒曼', '你已經向黑暗女王證明了自己的價值，現在你應該有資格繼續完成她下達的其它任務了。$B$B庫勒曼·法席恩正在徵召可以幫助他對付敵人的勇士。$B$B你可以在布瑞爾東部的恐懼之末旅店找到他。', '和庫勒曼·法席恩談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1821, 'zhTW', '阿加曼德家傳武器', '在我活著的時候，阿加曼德家族是我的主人，但他們也是讓我死去的罪魁禍首！現在他們得到了應有的報復，阿加曼德家族已經成為了巫妖王手下的行屍走肉。$B$B現在我要剝奪他們最後的榮耀。到他們家族的墓地裡去，幫我搶來他們的傳家之寶：一把劍，一柄斧，一柄匕首，還有一把釘錘。將這些東西全都給我拿來！$B$B阿加曼德家族墓穴就在阿加曼德磨坊的最北端，那裡有許多天譴軍團的部隊和死去的阿加曼德族人守衛著。', '把阿加曼德家傳長劍、阿加曼德家傳戰斧、阿加曼德家傳釘錘和阿加曼德家傳匕首交給庫勒曼·法席恩。', '', '去提里斯法林地找布瑞爾的庫勒曼·法席恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1822, 'zhTW', '祖傳武器', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1823, 'zhTW', '和魯迦交談', '作為一名戰士，你已經具備了相當的素質，而且名望也日漸顯赫。也許你已經準備好要接受魯迦·狂暴圖騰的試煉了？如果是這樣的話，就去貧瘠之地的陶拉祖營地找魯迦吧。$B$B他一直以來都在那裡等待英勇的戰士響應他的召喚。', '和魯迦·狂暴圖騰談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1824 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1824, 'zhTW', '巨人曠野的試煉', '要透過試煉，你必須一直向南到巨人曠野去，在那裡有一大群叫做異種蠍的昆蟲生物。我以前從未在貧瘠之地看到過這種生物，也不知道它們的到來究竟預兆著什麼。$B$B把它們的觸角交給我，$N，要剛剛割下來、還再抽搐的那種。不要浪費時間，因為一旦你把觸角割下來，它們很快就會徹底失去活力。在規定的時間內把觸角帶給我，這樣你就透過了考驗。', '收集5根顫抖的觸角，把它們帶給貧瘠之地陶拉祖營地的魯迦。', '', '去貧瘠之地找陶拉祖營地的魯迦·狂暴圖騰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1825 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1825, 'zhTW', '和索恩格瑞姆交談', '著名的獸人鐵匠索恩格瑞姆·火眼已經聽說了你為部落作出的傑出貢獻。他願意為你製作一套護甲，馬上去找他談談吧。$B$B索恩格瑞姆的營地就在貧瘠之地十字路口的東邊。', '與貧瘠之地的索恩格瑞姆·火眼談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1838 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1838, 'zhTW', '野蠻護甲', '我聽說了關於你的英勇事蹟，所以希望能為你製作一套護甲，這能夠幫助你去為部落作出更多更偉大的貢獻。$B$B但是製作這樣一件護甲需要你的幫助，$N，如果你能幫助我，那你也就幫助了部落裡所有的鐵匠。$B$B拿著這個卷軸，這是我經過無數不眠之夜，強睜著我半瞎的眼睛寫下的，上面記載著製作護甲所需要的材料。把卷軸上所列出的材料幫我找來，我會為你製作一套護甲。', '為索恩格瑞姆收集15根菸霧鐵錠、10份藍銅粉、10塊鐵錠和1瓶燃素。', '', '去貧瘠之地找荊棘嶺的索恩格瑞姆·火眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1839 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1839, 'zhTW', '尤拉萊克和野蠻護手', '食人妖鐵匠尤拉萊克會為你鑄造一副野蠻護手，他住在杜洛塔的森金村裡，那兒是暗矛氏族的家園，他正在等著你。', '與杜洛塔的尤拉萊克談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1840 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1840, 'zhTW', '歐姆·石蹄和野蠻頭盔', '歐姆·石蹄因為他傑出的鑄造技術而被大家尊敬，他會為你鑄造野蠻頭盔。$B$B你可以在雷霆崖找到他，他就在城市中心最大的那根圖騰旁的池塘附近。', '和雷霆崖的歐姆·石蹄談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1841, 'zhTW', '維羅拉·奈特雷和野蠻腿甲', '在死亡之前，維羅拉·奈特雷曾是羅德隆最好的鑄甲師。看來死亡讓她的技藝退步了許多。去和維羅拉談談——她會幫你鑄造野蠻腿甲。$B$B維羅拉住在羅德隆的幽暗城裡，你可以在貿易區找到她。', '與幽暗城的維羅拉·奈特雷談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1842, 'zhTW', '薩特之蹄', '我可以為你鑄造一副具有很強魔法力量的野蠻手套。但是首先，你必須先替我去收集這樣的魔法力量。$B$B為了獲取這片森林的力量，許多薩特聚集在梣谷的東北面，它們在那裡貪婪地吸取和破壞著森林的力量。你可以從它們腫脹的蹄子上判斷出到底是哪些薩特在吸取梣谷的魔力。$B$B這些蹄子都有不小的魔法力量，把它們給我帶來，這樣我就可以給你鑄造野蠻手套了。', '收集7只完整的薩特之蹄，把它們交給杜洛塔森金村的尤拉萊克。', '', '去杜洛塔找森金村的尤拉萊克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1843, 'zhTW', '野蠻護手', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1844, 'zhTW', '奇美拉之角', '我會幫你鑄造頭盔，但是你必須向我證明你值得我這麼做。$B$B石爪山的西北面是一個名叫焦炭谷的山谷，那裡曾經是一片鬱鬱蔥蔥的森林，但是現在已經被完全被汙染，那裡剩下的生物也都被痛苦和絕望逼瘋了。$B$B現在我就要派你去那裡，$N。$B$B你必須去焦炭谷找到奇美拉族母，殺死她，讓她從苦痛中得到解脫，把她那光滑的奇美拉角帶給我作為你完成任務的證據，然後我就會為你鑄造頭盔。', '把光滑的奇美拉角交給雷霆崖的歐姆·石蹄。', '', '去找雷霆崖的歐姆·石蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1845, 'zhTW', '野蠻頭盔', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1846, 'zhTW', '龍喉脛骨', '要鑄造野蠻腿甲，我就需要一些結實的脛骨。溼地裡的龍喉獸人就有非常合適的脛骨，我就需要那樣的。$B$B但是你一定要確保脛骨是絕對牢固的，在你收集它們的時候記得要試一下它們是不是足夠牢固：如果你能徒手把它們弄碎，那麼它們肯定不符合我的要求。', '給幽暗城的維羅拉·奈特雷帶去8根結實的龍喉脛骨。', '', '去提里斯法林地找 幽暗城的維羅拉·奈特雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1847, 'zhTW', '野蠻腿甲', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1848, 'zhTW', '野蠻鍊衫', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1858, 'zhTW', '破碎之手氏族', '你得去想辦法把塔贊的背袋給弄開，這樣咱們才能把裡面的東西拿出來。這鎖的結構還真挺複雜的，所以你想要弄開它的話就只能靠鑰匙了。$B$B如果你沒有在塔贊的屍體上找到鑰匙，那他就一定把鑰匙放到某個安全的地方去了……啊，對了!他有一個助手叫加摩爾，是個徹頭徹尾的大酒鬼，你八成能在酒館裡找到這傢伙。我建議你「安靜地」把鑰匙從他手裡搞來。', '偷來塔贊的鑰匙，用它打開他的背袋，然後將裡面的物品交給奧格瑪暗影裂口的瑟祖克。', '', '去找奧格瑪的瑟祖克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1859, 'zhTW', '瑟祖克', '小聲點，$N。沒錯，我知道你叫什麼。有人讓我注意一個獸人，你完全符合他的描述。$B$B我們聽說你在戰鬥中頗有一套，有時也會使用一些非常的手段。$B$B我沒說錯吧？$B$B不管怎樣，你得去見見奧格瑪的瑟祖克，他有事要吩咐你。', '到奧格瑪的暗影裂口和瑟祖克談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1860, 'zhTW', '和詹妮亞交談', '我們法師有一項任務要交給你去完成，一項對於暴風城和艾爾文森林的安全至關重要的任務。$B$B詹妮亞·坎農會告訴你任務的細節。她正在暴風城的法師區裡的巫師聖地裡學習，你最好儘快找到她。', '和暴風城的詹妮亞·坎農談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1861, 'zhTW', '明鏡湖', '大規模的魔法戰爭已經使得原本穩定的魔法流開始出現異常的波動。我們正在努力調查這種波動究竟會造成怎樣的影響，而有些人已經做好了最糟糕的打算！$B$B但是現在還不能輕易下結論，我們們要派你去收集更多的資訊。$B$B拿著這個水袋，到艾爾文森林明鏡湖瀑布的底部收集那裡的水樣，然後把水樣給我帶回來，這樣我就可以用它來進行魔法汙染情況的研究了。', '把一份明鏡湖水的樣本交給暴風城的詹妮亞·坎農。', '', '去找暴風城的詹妮亞·坎農。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1878 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1878, 'zhTW', '收集水袋', '', '', '', '去找塔納利斯的操作員魯格倫克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1879 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1879, 'zhTW', '和彬克交談', '$N！我在鐵爐堡的地精同事彬克送話過來說，她有一項必須交由某個法師來完成的任務！你不正好是個法師嗎，$N？$B$B如果你願意的話，去和彬克談談吧。她就在鐵爐堡秘法區的秘法大廳裡。', '和鐵爐堡的彬克談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1880 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1880, 'zhTW', '法師文檔記憶體', '我們法師能做的事情可不僅僅是彈動一下手指變出美麗的火花那麼簡單！我們控制著魔法，控制著構建這個世界的源泉！當然，這需要極大的決心和極強的能力，還有知識……足夠多的知識！$B$B我發明的一臺裝置——法師文檔記憶體——裡面儲存著無數的知識。不過問題是，我把它弄丟了！當我們逃離諾姆瑞根的時候，我把它留在城外一座小屋的箱子裡，現在那地方麻瘋地精橫行！$B$B$N，請幫我取回我的法師文檔記憶體！', '幫彬克找回她的法師文檔記憶體。', '', '去找丹莫洛的彬克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1881, 'zhTW', '安娜斯塔西婭', '$N，安娜斯塔西婭·哈特威爾有個任務需要你這樣有才幹的$c來完成。她就在幽暗城的魔法區，去和她談談，準備為被遺忘者的法師們完成你的第一個任務吧。', '和安娜斯塔西婭·哈特威爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1882 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1882, 'zhTW', '巴尼爾農場', '東邊的瘟疫之地處於混亂的狀態。巫妖王控制下的天譴軍團將邪惡的魔法灌入土地之中，腐化並殺死那裡的一切生靈。雖然瘟疫具有強大的破壞力量，但是我們——被遺忘者的法師——相信它必定可以被清除掉。$B$B首先，我們必須判斷出它在提里斯法到底散播到了怎樣的程度。到提里斯法東部的巴尼爾農場去，在那裡的花園中收集一些金魚草，然後再回來。', '將巴尼爾金魚草交給幽暗城法師區的安娜斯塔西婭·哈特威爾。', '', '去找提里斯法林地的安娜斯塔西婭·哈特威爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1883, 'zhTW', '安蘇瓦', '森金村的部落法師安蘇瓦發現杜洛塔的魔法流出現了波動，為此他向我尋求幫助。去和安蘇瓦談談，盡你所能去幫助他。$B$B快去吧，到時一定會有更多的秘密展示在你的面前。', '和安蘇瓦談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1884 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1884, 'zhTW', '魂能骨堆', '回音群島的術士札拉贊恩擾亂了杜洛塔的魔法流。他那些邪惡的魂能骨堆就是造成這一切的罪魁禍首，他把那些骨堆放在回音群島的主島上。$B$B骨堆破壞了我們的生活，還讓在黑暗角落裡隱藏著的術士和惡魔獲得源源不斷的力量。$B$B你必須在魔法流被徹底改變之前摧毀那些魂能骨堆，$N。', '摧毀4個魂能骨堆，然後向森金村的安蘇瓦彙報。', '', '去杜洛塔找森金村的安蘇瓦。', '摧毀魂能骨堆', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1885 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1885, 'zhTW', '米奈特·卡加德', '$n?雖然現在的情況並不像我所預計的一樣，但卡加德確實對你非常感興趣。聽起來是不是有點難以置信?無論如何，你得儘快去找他談談。我想你並不想知道上一個對他的召喚置之不理的人的下場吧。', '與幽暗城盜賊區的米奈特·卡加德談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1886 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1886, 'zhTW', '亡靈哨兵', '想加入瓦里瑪薩斯大人的精英衛隊——亡靈哨兵的話，你首先必須證明自己的價值。$B$B坦城地說吧，$n，你很可能在這種證明自己價值的任務中喪命，所以我勸你最好三思而行。$B$B現在，我有一個任務要你去完成。有一位來往於銀松森林與幽暗城之間的信使，他叫阿斯托·哈德恩，由於特殊的公務需要，我必須得到他身上的一些私人物品。至於採用怎樣的策略去得到這些物品，那是你的事情，不要問我。$B$B如果你的好奇心能小一點，不那麼關心這些物品的用途的話，你會過得更自在一些。完成這個任務之後，我會再和你談的。', '得到阿斯托的介紹信，並將其交給盜賊區的米奈特·卡加德。', '', '去提里斯法林地找幽暗城的米奈特·卡加德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1898 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1898, 'zhTW', '亡靈哨兵', '這封介紹信足以使安德隆認為你就是他正在等的那位信使。我之前已經見過安德隆了，估計以他那點腦子是根本不會懷疑你的。$B$B瓦里瑪薩斯大人懷疑安德隆正在為某些其他的組織提供援助。他想知道那是個什麼組織，而且你要收集到充分的證據。$B$B我要求你在與安德隆的談話中把這些資訊都給套出來，他的店就在鍊金房旁邊。', '與幽暗城的安德隆·甘特交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1899 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1899, 'zhTW', '亡靈哨兵', '你在我背後的書架上就可以找到記有你的主子最需要的資訊的帳本。把它交給他們，記得代我問他們好。哦，還有，告訴他們，如果他們覺得與我合作確實不錯，並且還打算按日程繼續合作下去的話，他們最好還是派你來。', '將安德隆的帳本交給幽暗城盜賊區的米奈特·卡加德。', '', '去提里斯法林地找幽暗城的米奈特·卡加德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1918 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1918, 'zhTW', '被汙染的水元素', '被毀滅的水元素留下了一顆水球，它令你感到極端的厭惡，彷彿汙染密斯特拉湖的所有物質都包含在這顆水球中一樣。$B$B你不清楚誰會對這個感興趣，不過碎木崗哨的馬斯托克·維爾西斯——那個最初派你來這裡的傢伙——也許對此有所瞭解。', '將被汙染的水球交給梣谷碎木崗哨的馬斯托克·維爾西斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1919 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1919, 'zhTW', '向詹妮亞報告', '你的能力正在不斷地增強，年輕的$N。你準備好要接受真正的挑戰了嗎？你願意加入到我們正在進行的這場秘密戰爭之中嗎？$B$B如果你願意的的話，就去和詹妮亞·坎農談談吧，她在暴風城法師區的巫師聖殿裡。她有一項任務要交給你，這將幫你開啟通向那個秘密世界的第一扇窗。', '和暴風城的詹妮亞·坎農談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1920 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1920, 'zhTW', '調查藍色隱士', '有報告稱，法師區的藍色隱士旅店裡出現了異常的魔法波動。一些隱形的奇怪生物徘徊在旅店裡，我擔心那裡已經有了一道魔法裂隙。$B$B我希望你去調查一下旅店，捕獲那些生物。用旅店中的顯形卷軸讓它們現出原形，然後用封靈箱抓住它們。當你抓到足夠數量的隱形生物之後，就帶著裝滿的封靈箱、空的封靈箱和顯形卷軸回到我這裡來。', '從詹妮亞·坎農身後拿取一根顯形卷軸以及一盒封靈箱。將3個裝滿的封靈箱交給巫師聖殿裡的詹妮亞·坎農。', '', '去找暴風城的詹妮亞·坎農。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1921, 'zhTW', '收集原料', '你幫了你的法師同行們很多忙，現在是為你製作巫師長袍的時候了。威恩·拉爾森可以幫你這個忙，不過你必須把必需的原料交給她。$B$B制袍用的亞麻布很容易找到，不過你還必須得到充能裂隙寶石，唯一出產這些寶石的地方是在洛克莫丹的銀泉礦洞，它們大多被密封在矮人礦工協會的箱子裡。$B$B收集好亞麻布和寶石之後，把它們交給法師區拉爾森服裝店裡的威恩·拉爾森。', '把10匹亞麻布和6顆充能裂隙寶石交給暴風城的威恩·拉爾森。', '', '去找暴風城的威恩·拉爾森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1938 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1938, 'zhTW', '烏爾的暗影魔法研究論文', '很久以前，三個法師在暴風城裡一起學習法術，直到其中的一個開始研究黑暗魔法。他原本並不想深入其中，但是卻發現自己在不經意間越陷越深。最終，他被放逐出了暴風城。$B$B這個被放逐的法師就住在赤脊山的伊爾加拉之塔中，他手中有一本強大的魔法書——《烏爾的暗影魔法研究論文》。$B$B我們這些暴風城的法師希望能把那本書拿回來。你要做的就是溜進伊爾加拉之塔，幫我們取回那本書。', '將《烏爾的暗影魔法研究論文》交給暴風城的高階巫士安多瑪斯。', '', '去找暴風城的高階巫士安多瑪斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1939 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1939, 'zhTW', '高階巫士安多瑪斯', '高階巫士安多瑪斯希望和你談談，$N。他就在暴風城法師區的高塔頂端。$B$B能去和他會面可是非常難得的機會，因為安多瑪斯是少數幾個沒有被困在達拉然的超強的大法師之一，他找你也一定是有非常重大的事情。', '和高階巫士安多瑪斯談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1940 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (1940, 'zhTW', '新鮮的蜘蛛絲', '你一直在幫助我們，$N。我想，也許你應該換一件好點的長袍了，一件更適合資深法師地位的長袍。如果你能收集到必需的原料，我們就幫你做一件新的長袍。$B$B你必須進入暮色森林，獵捕那裡的食腐獨行蛛。抽出它們的絲，但只有最好的、最純的絲才行。你得到足夠的蛛絲後，就把它們交給威恩·拉爾森來幫你縫製長袍，她就在法師區的拉爾森服裝店裡。', '找到8束新鮮的蜘蛛絲，把它們交給暴風城的威恩·拉爾森。', '', '去找暴風城的威恩·拉爾森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 1941 AND `locale` = 'zhTW';
