INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2750, 'zhTW', '壞掉的蛋', '', '', '', '去找塔納利斯的克格爾·曲藤。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2751 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2751, 'zhTW', '野人裝甲', '這隻鐵錘在沃姆什家族中傳了二十代，$N。我們熔鑄的鐵有成千上萬噸。不幸的是，這門技藝到了奧羅克手中卻傳不下去了，這是沃姆什家族的恥辱——我既沒有親屬，又無法生育後代。$B$B決不能讓沃姆什的祖傳技藝和我一起死去！必須有人繼承它，不管他是不是沃姆什家族的後裔！$B$B向奧羅克證明你的能力吧，$N。給奧羅克找來這些東西：兩副青銅花紋護腕，兩把青銅巨劍和兩隻鋒利的爪子。把這些找來，我們再繼續。', '將2副青銅花紋護腕、2把青銅巨劍和2只鋒利的爪子交給奧格瑪的奧羅克·沃姆什。', '', '去找奧格瑪的奧羅克·沃姆什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2752 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2752, 'zhTW', '鐵肩鎧', '奧羅克可以看出你眼中的渴望，$N。你像海綿一樣渴望吸收沃姆什的智慧。$B$B我會教你三樣東西！$B$B到鐵砧那邊去，感受熔爐的熱量，為奧羅克鑄造四把青銅戰斧和四把青銅戰錘，然後你才能學習製造鐵肩鎧。', '將4把青銅戰斧和4把青銅戰錘交給奧格瑪的奧羅克·沃姆什。', '', '去找奧格瑪的奧羅克·沃姆什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2753 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2753, 'zhTW', '踩在腳下', '奧羅克還剩兩課要教給你，$N。我知道你的肌肉很疼，不過為了沃姆什家族，你還要繼續！$B$B把四頂綠鐵頭盔、四個綠鐵護腕和四個綠鐵護腿拿來給奧羅克——你可以學到知識，你的敵人也會更加痛苦！', '將4頂綠鐵頭盔、4副綠鐵護腕和4副綠鐵護腿交給奧格瑪的奧羅克·沃姆什。', '', '去找奧格瑪的奧羅克·沃姆什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2754 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2754, 'zhTW', '瘋狂之角', '這是奧羅克教你的最後一課，$N。回到神聖的鐵砧和鍛爐旁去！將兩隻結實的鐵錘、兩雙鍍銀青銅戰靴和兩副鍍銀青銅手套交給奧羅克。$B$B你會看到敵人眼中的恐懼！', '將2只結實的鐵錘、2雙鍍銀青銅戰靴和2副鍍銀青銅手套交給奧格瑪的奧羅克·沃姆什。', '', '去找奧格瑪的奧羅克·沃姆什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2755 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2755, 'zhTW', '沃姆什的喜悅', '奧羅克沒哭，$N，眼睛進了灰。$B$B<奧羅克偷偷地抹去一滴眼淚>$B$B還有一個沃姆什家族的秘密，奧羅克可以告訴你。多謝$N，奧羅克現在死而無憾了。$B$B學習沃姆什家族的喜悅之舞，然後你就掌握了鍛造鋼鐵手套的技術！', '觀察並學習沃姆什的喜悅之舞。', '學會奧羅克的喜悅之舞', '去找奧格瑪的奧羅克·沃姆什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2756 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2756, 'zhTW', '古老的技藝', '很久以前，阿圖爾克可以碾碎敵人的頭顱，將他們的骨頭磨成粉做燈絲……很久以前，$r。現在酋長號召各部族和平相處。那些往日的敵人，現在我們只能用厭煩的眼光看著他們！$B$B我知道這很難以接受，不過這就是索爾的意願。$B$B實在是讓我感到悲哀！你是來學習的，那你就學吧！給我拿四套鋼質胸甲和四頂鋼質頭盔來，你可以在鍛造它們的時候嚐到戰爭的滋味！', '將4套鋼質胸甲和4頂鋼質頭盔交給奧格瑪的鐵砧阿圖爾克。', '', '去奧格瑪找榮譽谷的鐵砧阿圖爾克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2757 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2757, 'zhTW', '藏寶海灣之旅！', '聽著，孩子，你在我這兒已經學不到什麼東西了。$B$B我認識一個鐵匠，他認識另一個優秀的鐵匠……聽起來有些混亂。你應該到藏寶海灣的鐵匠鋪去找他，只要你把這枚徽章交給他看看，他就會把有關秘銀的知識都傳授給你。$B$B怎麼樣？踏上真正的求知之旅吧，$N。$B$B如果你對此感興趣的話，就去找馬克迦文吧。別忘了給他看看這枚徽章。', '與藏寶海灣的馬克迦文談一談', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2758 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2758, 'zhTW', '鍛造的本源', '我像你這麼大的時候，在一個名叫加爾文的矮人門下學習了鑄造護甲的技術。在他離開這裡前往藏寶海灣之前，曾讓我向他許諾，要幫助訓練所有決心在鍛造這門技藝上學有所成的人——於是這麼多年來，我一直在這麼做。$B$B現在是時候讓你學點新東西了。給我打造六套金鱗護腕，你就會知道鍛造的本源是什麼了，$N。', '將6副金鱗護腕交給暴風城的巨錘漢克。', '', '去暴風城找矮人區的巨錘漢克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2759 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2759, 'zhTW', '尋找加爾文', '雖然加爾文很多年前就離開了藏寶海灣，但鎮子裡還有一個秘銀會的成員，希望能找到另一個值得加爾文親自授業的鐵匠。$B$B把這個徽章交給藏寶海灣的馬克迦文。$B$B我相信，如果你能見到加爾文的話，他一定會非常器重你的！', '與藏寶海灣的馬克迦文談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2760 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2760, 'zhTW', '秘銀會', '我們招募的人幾乎沒有能平安抵達藏寶海灣的，$N。即使是意志最堅定的鐵匠也難以抵擋這枚徽章的光芒，他們難免會產生私吞的貪念。他們都是傻瓜，因為與你即將得到的巨大財富相比，這枚徽章只是滄海一粟而已！$B$B去找到加爾文，把徽章交給他。他住在這裡的北面，就在祖爾格拉布和莫什奧格巨魔山之間的地方。', '和荊棘谷的加爾文談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2761, 'zhTW', '鐵匠必修課', '很多鐵匠都以為採礦和鍛造是兩件完全獨立的事情，不過鍛造能離得開採礦嗎？啊哈——那是不可能的！成功的鐵匠還必須得是成功的礦工。$B$B讓加爾文看看你的能力吧，$N。 給我找40塊鐵錠和40塊秘銀錠來，然後加爾文就會教你打造華麗秘銀短褲的方法！', '將40塊秘銀錠和40塊鐵錠交給荊棘谷的加爾文。', '', '去找荊棘谷的加爾文。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2762, 'zhTW', '白花花的銀子', '據說真銀比秘銀更堅固耐用，加爾文對這個說法沒有什麼異議，但是嚴格說起來，真銀並不是真的！秘銀比真銀更加高貴！哈！不管怎麼說，這一次，你要去收集一大堆銀子來，$N。$B$B給我弄四十塊秘銀錠和五塊真銀錠來，作為交換，我會向你傳授打造華麗秘銀手套的技藝，以及更為重要的，讓你知道真銀並不是真的！', '將40塊秘銀錠和5塊真銀錠交給荊棘谷的加爾文。', '', '去找荊棘谷的加爾文。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2763 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2763, 'zhTW', '灌魔工藝', '搜尋珍貴的寶石對我們來說是最重要的，$N。很少有比黃水晶更為珍貴的寶石。有了黃水晶，我們就能將注入各種裝備中的魔法特性得到大幅度提升。$B$B這一課，我們要用四塊黃水晶加強四十塊秘銀錠，這將使你更加了解神奇的寶石學，並學會如何製造華麗秘銀護肩。', '將40塊秘銀錠和4塊黃水晶交給荊棘谷的加爾文。', '', '去找荊棘谷的加爾文。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2764 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2764, 'zhTW', '加爾文的得意門生', '如果你準備要結束在加爾文這裡的訓練課程，就應該到加基森去。$B$B在那兒有我最得意的學生：特倫頓·輕錘。他可以教你很多有關華麗秘銀裝備的知識，當然你也可以留在這裡繼續學習！$B$B哦，對了，加基森在塔納利斯沙漠裡！', '和加基森的特倫頓·輕錘談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2765 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2765, 'zhTW', '鍛造專家！', '你剛來的時候，我就知道你會成為我最出色的學生之一！你毫不猶豫地把這個有魔力的飾品交給了馬克迦文，因此你才有了來見我的資格。你的全心奉獻和堅定信念應該得到回報。$B$B你已經在鍛造技藝方面取得了長足的進步，$N。拿上你的回報吧！', '到加爾文那裡拿取報酬！', '你是大贏家！', '去找荊棘谷的加爾文。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2766 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2766, 'zhTW', '尋找OOX-22/FE！', '你發現了一個奇怪的蛋形金屬物體。隨便撥弄了幾下之後，它居然自動開啟了，變成了一個看來是由地精製造的機器裝置！一個奇怪的聲音從這個蛋形機器裝置中傳了出來。$B$B“我的名字叫奧格索普，我的母體機器人不見了！如果你能幫我找到它，我就會獎勵你的！請把這個定向器帶到那個母體機器人那裡。別擔心，我現在已經檢測到了它的所在地！它現在就位於深痕谷中的一個山洞裡！”', '把定位器帶到深痕谷附近山洞中的奧格索普的導航機器人旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2767 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2767, 'zhTW', '拯救OOX-22/FE！', '那個地精的聲音再次從那個機器人中傳了出來：$B$B“我需要你幫忙把OOX-22/FE移動到一個安全的開闊地，這樣它才可以啟動起飛程式。它自帶隱形系統，但是我需要一點時間來遠端啟動這個系統。請你把這個機器人從現在的位置護送到被遺忘的海岸去！那裡是個非常理想的起飛點，有足夠的空間作為機器人起飛的跑道！”$B$B“將它護送到那裡，然後再到藏寶海灣來找我！奧格索普·奧布諾提斯——完畢！”', '將OOX-22/FE護送到被遺忘的海岸上的碼頭，然後向藏寶海灣的奧格索普·奧布諾提斯報告。', '將OOX-22/FE安全護送到目的地。', '去荊棘谷找藏寶海灣的奧格索普·奧布諾提斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2768 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2768, 'zhTW', '探水棒', '布萊中士偷了我的東西！他說只是借一下，但那混蛋卻偷了我寶貴的探水棒！沒有這根棒子，我就不知道該在哪裡打井找水！$B$B去找到布萊，把我的探水棒拿回來！我聽說他帶著一幫惡名遠揚的冒險者去了西邊的祖爾法拉克古城尋寶，你肯定可以在那裡找到他。$B$B但願那裡的食人妖已經把他幹掉了，因為如果你必須打敗他才能拿回探水棒的話，那必將是一場惡仗。', '把探水棒交給加基森的首席工程師比格維茲。', '', '去找塔納利斯的首席工程師比格維茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2769 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2769, 'zhTW', '銅栓兄弟', '你有沒有遇見銅栓兄弟?他們在卡林多的閃光平原上與哥布林賽車，而且他們通常都會獲得勝利，這並不奇怪─哥布林的賽車輪胎總是爆掉，他們幾乎從來都沒有完成過比賽!但即使是這樣，銅栓兄弟也還是在尋找新的方法使他們的車速更快，維茲爾跟我說過，他的下一個實驗需要一種很稀有的原料。或許他需要別人的幫助來獲取這種原料，你去和他談談就知道了。', '和閃光平原的維茲爾·銅栓談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2770 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2770, 'zhTW', '加茲瑞拉', '在塔納利斯沙漠的食人妖古城祖爾法拉克深處，有一個神聖的池塘。食人妖可以從那個池塘裡召喚一頭巨大的野獸─加茲瑞拉!它兇猛異常，甚至連它的鱗片都會因為巨大的能量而發出聲響。我要用它的能量來給我的賽車增加動力!$B$B把加茲瑞拉的鱗片給我弄來!$B$B不過，召喚加茲瑞拉的方法是食人妖的秘密。如果你想要面對加茲瑞拉的話，首先就要從食人妖那裡弄到召喚它的方法。', '把加茲瑞拉的鱗片交給閃光平原的維茲爾·銅栓。', '', '去千針石林找沙漠賽道的維茲爾·銅栓。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 2771 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2771, 'zhTW', '罩帽和護肩', '看來師傅一開始就計劃好了。你學會製造的東西都是我不會的，而我學會的那些你也不會。$B$B師傅很聰明，$N。這樣我們就可以互相學習了！$B$B你教我如何製造秘銀罩帽和華麗秘銀護肩，然後我再教你製造華麗秘銀頭盔，如何？', '將2頂秘銀罩帽和1副華麗秘銀護肩交給特倫頓·輕錘。', '', '去找塔納利斯的特倫頓·輕錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2772 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2772, 'zhTW', '世界在你腳下', '在去年的全谷鐵匠冠軍賽裡，我在眾目睽睽之下被一個來自風險投資公司的卑鄙傢伙用掃堂腿放倒在地。但是他們卻不知道我為什麼還能繼續站在那裡完成比賽，並取得冠軍。答案就是——沒錯，華麗秘銀戰靴！$B$B如果今年我還想取勝的話，就得學會華麗秘銀短褲的製作方法，因為這次會有一個風險投資公司的伐木工參加比賽！教我製作短褲，我就教你製作靴子，怎麼樣？', '將2雙秘銀重靴和1條華麗秘銀短褲交給特倫頓·輕錘。', '', '去找塔納利斯的特倫頓·輕錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2773 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2773, 'zhTW', '秘銀小子', '我被大家稱作秘銀小子。我給來自世界各地的冒險者們提供華麗秘銀裝備。$B$B<特倫頓悄悄地說。>$B$B但是沒幾個人知道我根本不會打造華麗秘銀手套。噓！這是你我之間的小秘密。$B$B如果你教我如何打造華麗秘銀手套的話，我就把從加爾文那裡學來的手藝傳授給你——華麗秘銀胸甲的製作方法！', '將2件重型秘銀胸甲和1副華麗秘銀手套交給特倫頓·輕錘。', '', '去找塔納利斯的特倫頓·輕錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2781, 'zhTW', '通緝：卡利夫·斯科比斯汀', '通緝：卡利夫·斯科比斯汀！$B$塔納利斯的加基森水力公司願支付高價懸賞廢墟歹徒首領卡利夫·斯科比斯汀的項上人頭。他的罪行包括：$B$B1. 殺害加基森水力公司的僱員！$B2. 偷竊加基森水力公司的資源！$B3. 搶劫加基森水力公司的財產！$B$B將卡利夫·斯科比斯汀的死亡證明交給首席工程師比格維茲，我們將立刻兌現你的獎賞！', '將卡利夫·斯科比斯汀的頭顱交給加基森的首席工程師比格維茲。', '', '去塔納利斯找加基森的首席工程師比格維茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2782, 'zhTW', '林吉的秘密', '這塊石板上佈滿了枯木食人妖的印記。林吉的秘密真是難以猜測……$B$B或許你手頭上的東西非常寶貴。當然，這東西也很有可能一文不值。悲傷中的枯木食人妖為了擺脫困境什麼事情都幹得出來……', '奧蘭·斯內克威瑟是個學者，她對枯木食人妖很有研究，也許她可以幫你看看這塊石板。奧蘭就住在幽暗城的魔法區裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2783, 'zhTW', '爭論', '我們在和錯誤的敵人進行戰鬥，$N。$B$B這片土地上真正強大的力量正在不斷增強，而我們卻還在和獸人為了這片焦土進行無謂的爭鬥。$B$B我們難道要繼續這種爭鬥，直到有一天讓燃燒軍團把我們都踏扁嗎？這實在是一種愚蠢的行為。$B$B$N，拋開你的偏見，和部落英雄的靈魂談談吧，他知道詛咒之地真正的秘密。', '與詛咒之地和悲傷沼澤交界處的部落英雄的靈魂談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2784, 'zhTW', '失落的榮耀', '請聽聽我的故事，$r。', '聆聽部落英雄的靈魂講述他的故事。', '悲傷的故事', '去悲傷沼澤斷矛路口找部落英雄的靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2801, 'zhTW', '悲傷的故事', '請你一定要先聽聽我的故事。', '聆聽部落英雄的靈魂講述他的故事。', '悲傷的故事', '去悲傷沼澤斷矛路口找部落英雄的靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2821, 'zhTW', '品質的保證', '我對於皮革製作的哲學是要做就做最好——沒有商量餘地。任何說品質不要緊的人都是想要把丹莫洛的那些水貨賣給你！$B$B在尋求高品質材料的過程中，我接觸到了厚重的雪人皮。雪人是菲拉斯土生土長的一種生物，大多在深痕谷活動。我需要一些它們的皮，如果你給我十張的話，我可以讓你在我的皮貨中選一件。如果你覺得聽起來還算公平，那我們就成交了吧。', '給羽月要塞的普拉特·馬克格魯比帶去10張厚重的雪人皮。', '', '去菲拉斯找羽月要塞的普拉特·馬克格魯比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2822, 'zhTW', '品質的保證', '我為自己製作的皮革作品感到驕傲，它們也值得我驕傲，品質是永不可能妥協的東西。任何說品質不要緊的人都是在信口亂說！$B$B在尋求高品質材料的過程中，我接觸到了厚重的雪人皮。雪人是菲拉斯土生土長的一種生物，大多在深痕谷活動。我需要一些它們的皮，如果你給我十張的話，我可以讓你在我的皮貨中選一件。如果你覺得聽起來還算公平，那我們就成交了吧。', '給莫沙徹營地的杉多爾·迅蹄帶去十張厚重的雪人皮。', '', '去菲拉斯找莫沙徹營地的杉多爾·迅蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2841, 'zhTW', '裝置之戰', '地精的技術——兩年前它最普遍的用途是被當作笑話，但是時代確實變了，現在他們建造的新型鑽探裝置比我們所有伐木機加起來都要精密。我需要它的設計圖，$N！$B$B不幸的是，這些設計圖被鎖在麥克尼爾·瑟瑪普拉格身邊的一隻保險箱裡了。更糟的是，保險箱的密碼只有麥克尼爾·瑟瑪普拉格一人知道。$B$B盡你所能得到那個密碼，$N。把設計圖給我帶回來！', '從諾姆瑞根拿到鑽探裝置藍圖和麥克尼爾的保險箱密碼，把它們交給奧格瑪的諾格。', '', '去找奧格瑪的諾格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2842, 'zhTW', '主工程師斯庫提', '斯庫提和我剛剛從克努比那裡得到關於新型地精鑽探裝置的訊息，就馬上開始動手研製捷運器6000型了，它是去諾姆瑞根最快捷可靠的方法！$B$B現在它已經完成了，$N。如果你想試試的話，就到藏寶海灣去和空運處的斯庫提談談吧。你可以從棘齒城乘船去藏寶海灣。$B$B當然，你也可以試試從滿地都是矮人的丹莫洛山脈走到諾姆瑞根去！', '和藏寶海灣的斯庫提談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2843, 'zhTW', '出發！諾姆瑞根！', '只要你有傳送器，你所要做的就只是踩上踏板，然後就會被傳送到諾姆瑞根！$B$B你可能會有一些不適感，但這些副作用應該都不是永久的……$B$B我幾乎忘了最重要的部分——如何回來。當你準備好要回來時，只要在諾姆瑞根踩上傳送器的踏板就行了！$B$B現在請把傳送器按照你的體型和體重做一些調整。', '等斯庫提調整好哥布林傳送器。', '哥布林傳送器', '去荊棘谷找藏寶海灣的斯庫提。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2844, 'zhTW', '大保姆', '都是我不好，$N。我本應細心照顧我的小朋友，沙恩。但是不知道為什麼，她離開了我。我並不十分清楚發生了什麼事，真的，但我最後一次看到她的時候，我們正在穿越這裡北面的廢墟。$B$B一切都很正常，但我轉過身一看……她就不見了。$B$B現在我不知道該怎麼辦了。你有辦法嗎，$N？我很擔心。$B$B嘿，你幫我去找沙恩怎麼樣？你看上去應該比我跑得快一些。', '尋找走丟了的精靈小姑娘。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2845, 'zhTW', '迷路的沙恩', '你能帶我回到我的朋友羅克比特身邊嗎？他本來是要照看我的……但我總是不知不覺之間就迷路了。這裡有這麼多好看的東西，我東看看西看看就不知道該怎麼走了。$B$B但是有一樣東西可以一直吸引我的注意力。$B$B在這個箱子裡有一隻對我來說最為珍貴的鈴鐺，我就喜歡聽它的聲音。我保證，如果我走失了，只要你搖響鈴鐺，我就會馬上跑回來。', '從箱子裡拿取沙恩的鈴鐺，然後護送沙恩·飄葉回到羅克比特的營地。', '帶沙恩·飄葉回到羅克比特的營地', '去菲拉斯找雙塔山的羅克比特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2846, 'zhTW', '深淵冠冕', '很久以前我曾經擁有一件美麗的珍寶，深淵冠冕。它不僅美麗——而且它對於知道怎麼使用它的人來說更是一件擁有巨大力量的寶貝。$B$B所以當水佔師維蕾薩聽說冠冕的事情之後，她就發誓要得到它。維蕾薩派人在我外出的時候到我家來偷走了冠冕，這些卑鄙的小偷！$B$B我要取回我的冠冕！到位於塔納利斯沙漠中的食人妖城市祖爾法拉克去，把冠冕從她手上搶回來。把它還給我，你會得到報酬的。', '將深淵冠冕交給塵泥沼澤的塔貝薩。', '', '去塵泥沼澤找塔貝薩的農場的塔貝薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2847, 'zhTW', '蠻皮護甲', '$n，你已經是個很熟練的製皮匠了！我知道一些裝備的製作方法，你可能會感興趣……那就是蠻皮護甲！蠻皮中包含了野葡萄的混亂而強大的力量，你可以在這片茂盛的森林中找到這種植物，也可以在森林中的某些動物身上找到。用它製作的裝備簡直是無以倫比！$B$B我會把製作蠻皮護甲的方法教給你，條件是你要為我做點事情。首先你得給我帶十塊厚皮來，等你拿來十塊厚皮之後我們再詳談。', '給羽月要塞的普拉特·馬克格魯比帶去10塊厚皮。', '', '去菲拉斯找羽月要塞的普拉特·馬克格魯比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2848, 'zhTW', '蠻皮護肩', '蠻皮護肩能夠很好地支撐穿戴者的身形，為其上臂和肩部提供了極好的保護。和所有的蠻皮護甲一樣，製作時所使用的野葡萄會使其附帶一種強大的隨機魔法效果。$B$B如果你想要這種護甲的圖樣，就給我弄六塊厚重護甲片和一株野葡萄來，這對你來說應該不算什麼過分的要求。', '給羽月要塞的普拉特·馬克格魯帶去6片厚重護甲片和1株野葡萄。', '', '去菲拉斯找羽月要塞的普拉特·馬克格魯比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2849 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2849, 'zhTW', '蠻皮外衣', '蠻皮外衣是蠻皮護甲中最主要的部分，它的結構以及編織於其中的野葡萄能使其在具有很強的保護作用的同時，還附帶著強大的魔法力量。$B$BB如果你想要這種護甲的圖樣，就給我弄兩件龜鱗胸甲、兩副龜鱗手套和一株野葡萄來。這不是件容易的活兒，但你一定可以完成它。', '給羽月要塞的普拉特·馬克格魯帶去2件龜鱗胸甲、2副龜鱗手套和1株野葡萄。', '', '去菲拉斯找羽月要塞的普拉特·馬克格魯比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2850 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2850, 'zhTW', '蠻皮頭盔', '蠻皮頭盔可以為你的頭部提供極好的保護，與此同時，它也具有相當的舒適性。和所有的蠻皮護甲一樣，製作頭盔時使用的野葡萄會使它產生一種強大的隨機魔法效果。對於穿著皮甲的人來說，這東西可是非常不錯的！$B$B想要得到這頂頭盔的圖樣的話，就給我帶兩件夜景外套、兩條夜景頭巾和一株野葡萄來。完成這個任務之後，圖樣就是你的了！', '給羽月要塞的普拉特·馬克格魯比帶去2件夜景外套、2條夜景頭巾和一株野葡萄。', '', '去菲拉斯找羽月要塞的普拉特·馬克格魯比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2851, 'zhTW', '蠻皮戰靴', '你現在已經學到了很多東西，$n，但你仍有更多的東西要學習。現在我們來談談蠻皮戰靴，它是這一套裝備的基石。$B$B這種靴子舒適合腳，可以讓你的雙腳在長途跋涉之後仍然輕鬆自如。柔軟的鞋底對於那些喜歡悄悄行動的人來說再合適不過了。$B$B如果你想要得到它的圖樣，就給我拿兩條夜景便褲和兩雙夜景長靴來。另外我還需要兩株野葡萄……只有一株的話可不夠。拿到以上這些東西之後，就把它們交給我。', '給羽月要塞的普拉特·馬克格魯帶去2條夜景便褲、2雙夜景靴和2株野葡萄。', '', '去菲拉斯找羽月要塞的普拉特·馬克格魯比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2852 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2852, 'zhTW', '蠻皮護腿', '基礎教程已經完成，你應做好準備掌握更為複雜的製作了，$n。蠻皮護脛是最堅硬和強大的皮製系列裝備中的一樣。野獸系列皮裝備讓你的胸部，大腿，小腿和其他致命的部位都被保護起來。再加上野葡萄所起的輔助作用，擁有這種裝備的冒險者一定會永遠感謝你的。$B$B如果你想要得到這個圖樣的話，帶給我兩頂龜鱗頭盔，兩付龜鱗護腕和兩株野葡萄。', '給羽月要塞的普拉特·馬克格魯比帶去2頂龜鱗頭盔、2副龜鱗護腕和2株野葡萄。', '', '去菲拉斯找羽月要塞的普拉特·馬克格魯比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2853 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (2853, 'zhTW', '蠻皮護甲大師', '好吧，$n，你就是勤奮的楷模。蠻皮護甲只剩下一種式樣你還沒有學會了。我不會要求你為最後的式樣無謂地浪費時間和精力，你可以直接得到它，還有一些……但我不能自己傳授給你。我的老師，就是帶我進入這一行的人，他會教你怎麼做。$B$B把這封信交給泰龍尼斯，他在達納蘇斯教授皮革製作的工藝。給他看這封信，讓他像我一樣認同你。', '將普拉特的信交給達納蘇斯的製皮大師泰龍尼斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 2854 AND `locale` = 'zhTW';
