INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3085, 'zhTW', '神聖石板', '啊，剛剛你不在的時候，有人送來了這塊石板，$N。$B$B如果你有時間的話，還是看看這上面說些什麼的好。如果我沒搞錯的話，這塊石板是牧師訓練師肯傑寫的，他有事找你。', '閱讀神聖石板，然後和試煉谷大獸穴外的肯傑談一談。', '', '', '', '', '', '', 0);
