INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3111, 'zhTW', '暫無內容', '很久以前，高等嚮導教授了我們和人類關於魔法的奧秘。他們告訴了我們魔法的規則和它是多麼讓人痴迷！但是決不要過於相信它。我們並不是暗夜嚮導；我們沒有他們的弱點。所以你只要保證自己走在正確的發展道路上，然後你就會發現其實魔法就好像是一把強力的武器一樣。$B$B當你準備好了，就來安威瑪爾找我。我會等著你的！$B$B——瑪瑞克·斯托納爾，法師訓練師', '和安威瑪爾的瑪瑞克·斯托納爾談談。', '', '', '', '', '', '', 0);
