INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3113, 'zhTW', '密文備忘錄', '你剛才在外面忙碌的時候，有人讓我把這個備忘錄交給你。如果你有時間的話就看一下吧，好像是盜賊訓練師索姆寫給你的，他就在安威瑪爾裡面。', '閱讀密文備忘錄，然後與寒脊山谷的索姆·哈格林談一談。', '', '', '', '', '', '', 0);
