INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3385, 'zhTW', '黑市交易', '他們把自己稱為黑市成員，他們都是些貪財如命的雜碎，只要有利可圖，他們什麼都會倒賣！$B$B現在情況變得更加糟糕了，$N。他們在灼熱峽谷建立了一個基地，貿易首領考維克在那裡策劃著所有的行動，並且和該地區的黑鐵矮人保持著密切的關係。$B$B我們必須對這種行為進行嚴厲打擊，給他們一個嚴厲的警告。去殺掉貿易首領考維克和他的同夥科朗克，把他的商人的背包給我拿回來，你的任務就算完成了。$B$B向大熔爐進發！', '殺了貿易首領考維克和他的同夥科朗克。從他的屍體上拿回商人的背包，把它交給尼莉絲。', '', '去找灼熱峽谷的尼莉絲·洛克拉夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3401 AND `locale` = 'zhTW';
