INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3402, 'zhTW', '黑市交易', '我要你把考維克被幹掉的訊息親自帶給加基森的維茲格里克，他知道考維克死亡的訊息一定會很高興的，我敢說他肯定會為此給你豐厚的獎勵。', '和加基森的維茲格里克談一談。', '', '', '', '', '', '', 0);
