DELETE FROM `quest_template_locale` WHERE `ID` = 3541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3541, 'zhTW', '傑斯雷蒙的石版', '我在奧格瑪有個主顧，他住在暗巷區。如果你不熟悉那裡，那麼你是很難找到他的，不過如果你到那個區域中最高的那座建築物裡去，就應該能找到他。$B$B不過呢，你可別讓全卡林多的人都知道他在哪裡，他在幹什麼——這對咱們倆都沒好處。$B$B為了這塊辛耶爾石板，他會付給咱們一大筆錢的。我不知道他為什麼如此在乎這塊石板，不過你真該看看他聽到這塊石板的訊息後有多激動。', '將辛耶爾石板交給奧格瑪的傑斯雷蒙。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3542, 'zhTW', '安德隆·甘特的石版', '安德隆·甘特是我的下一個主顧。他通常待在幽暗城裡……就在鍊金房附近。當我們談到石板的用途時，他就有些藏不住話。顯然幽暗城中的某些法師想要學習上層精靈所使用的秘法。他們認為這石板能對他們有所幫助。瑪科裡曾以善於召喚各種生物——特別是元素生物而聞名。$B$B把瑪科裡石板給他帶過去，然後回到我這兒來取你的報酬吧。', '將瑪科裡石板交給幽暗城的安德隆·甘特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3561, 'zhTW', '大法師克希雷姆的石版', '最後這塊石板要交給一個非常危險的傢伙，$N。聽著，比起我先前讓你接觸的那些人，我對他可以說是非常不信任的。$B$B大法師克希雷姆在一處可以俯瞰艾薩拉的山頂上建了座高塔。他是個人類，但是他的行為跟我見過的……或是殺掉的那些人類大不相同。他充滿了力量，我可不敢問他為什麼想要這塊石板。$B$B他來找過我，但是他跟我說，當我準備就緒時，他的侍衛薩納斯會帶我到塔裡去。到北邊去找薩納斯吧。', '將塞爾哈石板交給艾薩拉的大法師克希雷姆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3562, 'zhTW', '瑪加薩的報酬', '把這張便箋交給傑迪加,告訴她當她回來的時候就到這兒來領取報酬。我對她的成績很滿意。$B$B快去吧，$N。告訴你的主人，我在這兒等她。', '將瑪加薩的便箋交給艾薩拉的傑迪加。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3563, 'zhTW', '傑斯雷蒙的報酬', '把這封信交給傑迪加，告訴她，我們的交易很成功，而且我對她很滿意。$B$B讓她馬上返回奧格瑪，傑斯雷蒙會確保她的安全。$B$B也許將來我還需要你的幫助，$N。', '將傑斯雷蒙的便箋交給艾薩拉的傑迪加。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3564, 'zhTW', '安德隆的報酬', '拿著……這個……<嗝>交給傑迪加。祝你好運！', '將安德隆的便箋交給艾薩拉的傑迪加。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3565, 'zhTW', '克希雷姆的報酬', '什麼？哦，你的報酬。當然。$B$B拿好了，趕快走吧。我想傑迪加正在耐心地等你回去呢。', '將克希雷姆的便箋交給艾薩拉的傑迪加。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3566, 'zhTW', '奧比斯頓', '這……這……這是個陷阱。$B$B原諒……我。$B$B殺掉這個該死的混蛋……為我們殺掉他……為了索里奧斯。', '殺死黑衣拉索裡克和奧比斯頓，帶著黑衣拉索裡克的頭顱和奧比斯頓的心臟回到鐵爐堡的索里奧斯那兒。', '', '去找鐵爐堡的索里奧斯館長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3567, 'zhTW', '登高', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3568 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3568, 'zhTW', '墮落之水', '看見我後面的那個看起來隨時都可能病倒的牛頭人了嗎?她前段時間去過艾薩拉。她說自己在經過埃達拉斯廢墟時受到納迦的攻擊，而且負了傷。$B$B在擊退一些納迦之後，她在海灘休息了一下，並飲用了海潮之池中的水，現在她感覺有些噁心……$B$B我要找出她飲用的水。拿著這個盒子，我在裡面放了一些空瓶子，用它們到各個海潮之池中收集一些水，然後回來。', '在艾薩拉的埃達拉斯廢墟旁的海潮之池中收集4瓶水，然後回到藥劑師科雷那兒。', '', '去找藥劑師科雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3569 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3569, 'zhTW', '墮落之水', '把這個交給瑟爾薩。也許她可以痊癒……也許不能。反正要在她喝下後才能知道結果。', '將科雷的藥劑交給幽暗城的瑟爾薩·風歌。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3570 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3570, 'zhTW', '墮落之水', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3581, 'zhTW', '暫無內容', '想像你自己奔馳過平原，穿越森林，翻越高山，迎風而行……行走在未知的疆域之中，前方道路充滿驚奇，你的命運就在地平線的另一端等著你。$B$B永遠記住，靠著雙蹄奔馳，許多事', '再次與賽恩·傲跑者談話，學習平原疾走技能。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3601, 'zhTW', '我就是基姆加爾！', '我就是基姆加爾！你知道基姆加爾對血精靈意味著什麼嗎，$N？我對他們來說不過是一隻小老鼠……或者其它類似老鼠的東西，那些該死的欺凌弱小的傢伙！$B$B他們僱傭我來幫他們在這裡搜尋一些失落的寶物，當然，在他們告訴我要找什麼東西以及他們願意付給我多少錢之後，我就決定單幹了。他們馬上翻臉，還想幹掉我……幹掉我！$B$B所以，你看，永遠都不要相信血精靈。$B$B問題是，我的一些東西還在他們手裡，看樣子我自己是拿不回來了。你能幫幫我嗎？', '搜尋薩拉斯營地，找到基姆加爾的指南針、望遠鏡、燒雞和花生，然後把它們交給艾薩拉的基姆加爾。', '', '去艾薩拉找雷加什營地的基姆加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3602, 'zhTW', '艾薩拉水晶', '艾薩拉南部地區的古代峭壁巨人以吞噬這個地區的岩石和建築物為生。他們的排洩物具有高度的延展性和極其明顯的水晶特性，所以被稱作艾薩拉水晶。$B$B這種東西主要在南部地區出現，但是由於那些巨人的暴力傾向，通常你很難得到它們。$B$B你必需到艾薩拉南部去，收集足夠多的艾薩拉水晶來製作武器的主體部分。我的惡魔犬會幫助你收集水晶的。', '在艾薩拉南部收集20塊艾薩拉晶體。你可以使用惡魔犬協助尋找一些隱藏的礦脈。$B$B任務完成之後就回到洛拉姆斯那裡去。', '', '去艾薩拉找風暴海灣的洛拉姆斯·薩里比迪斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3621, 'zhTW', '武器的鑄造', '下一步就是鑄造武器了。你必須把淬火過的艾薩拉水晶交給一個有能力操縱惡魔能量的鐵匠。$B$B在荊棘谷就有這樣的一個鐵匠——他就是加爾文，秘銀會的領袖。他會按照你的要求打造武器，到祖爾格拉布和莫什奧格巨魔山之間的區域去尋找他的營地吧。$B$B願你的決心和信念引領你度過這場考驗。如果你失敗了，你的神會對你微笑。去吧，$r。', '把貨物交給荊棘谷的加爾文。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3622, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
