INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3624, 'zhTW', '暫無內容', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3625, 'zhTW', '魔化艾薩拉水晶武器', '$N，製造任何武器都需要花費一些時間。$B$B另外，你每三分鐘才可以使用一次惡魔詛咒的力量。它可以削弱汙染者和他的爪牙們的力量，但效果持續的時間可能會有差異。因此，你必須在恰當的時候使用惡魔詛咒！$B$B現在請稍等片刻，讓我來為你鍛造武器吧，$N。', '等待加爾文為你鍛造武器。', '鑄造武器', '去找荊棘谷的加爾文。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3626 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3626, 'zhTW', '返回詛咒之地', '救贖的時刻就要來臨了，$N。你必須拿著你的新武器回到詛咒之地，然後從部落英雄的靈魂那裡接受你最後的任務。', '回到部落英雄的靈魂那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3627, 'zhTW', '收集破碎的護符', '要見到汙染者的話，你就必須摧毀他手下的三個頭目的力量，然後把他們身上的護符碎片收集起來。當你拿到三塊碎片之後再回到我這裡來，我會給你進一步的指示。$B$B出發吧，$N！到詛咒之地去！把戈洛爾、瑟溫妮、奧利斯塔全部除掉！', '殺掉『毀滅者』戈洛爾、瑟溫妮女士，以及大法師奧利斯塔。從他們到屍體上拿到戈洛爾的護符、瑟溫妮的護符和奧利斯塔的護符。$B$B記住使用你的魔化艾薩拉水晶武器來削弱他們，否則他們是無法被殺死的——你必須小心謹慎地使用你的武器……', '', '去悲傷沼澤斷矛路口找部落英雄的靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3628 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3628, 'zhTW', '惡魔拉瑟萊克', '拉瑟萊克的巢穴位於詛咒之地最高的山脈的頂端，通往巢穴的唯一途徑就是使用山脈附近的傳送符文。只要你擁有護身符，就可以輕鬆到達巢穴。到了那巢穴之後，你必須召喚那個惡魔，護身符就是召喚的關鍵，$N，你要在汙染者祭壇上使用它。$B$B去打敗汙染者拉瑟萊克，把他的犄角帶回來。這將成為我們希望的象徵——在這個飽經戰火的世界上仍然有英雄存在的證據。', '消滅汙染者拉瑟萊克，將汙染者之角交給部落英雄的靈魂。另外你還要把汙染者防護結界交給他，這樣部落英雄的靈魂就可以消滅它，以避免它落入邪惡勢力之手。', '', '去悲傷沼澤斷矛路口找部落英雄的靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3629, 'zhTW', '哥布林工程學', '高階的工程學有兩個分支：地精派和哥布林派，請注意我提到哥布林工程學的唯一原因是因為我是個公正的訓練師。他們喜歡製造一些會爆炸的東西，而且絲毫不關心有什麼東西會被炸到——即使是他們自己。$B$B好吧，$N，讀一下這本手冊。如果你想要學習把自己炸上天的方法，就把這個交給加基森的尼克斯·斯普克斯賓。請記住，一旦你加入某一派，就永遠也不能再加入另一派了，所以在你完成他交給你的任務之前要三思。', '如果你想要對哥布林工程學有更多瞭解，就把工程學教材交給加基森的尼克斯·斯普克斯賓。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3630 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3630, 'zhTW', '地精工程學', '高階的工程學有兩個分支：地精派和哥布林派，雖然我認為提到地精簡直是浪費時間，但是你還是要對他們的技術保持警惕。他們製造了一大堆號稱可以改變世界的小玩意，但是那些東西很少有能用的。$B$B好吧，$N，讀一下這本手冊。如果你想要學習永遠都派不上用場的垃圾，就把這個交給鐵爐堡的技工大師歐沃斯巴克。請記住，一旦你加入某一派，就永遠也不能再加入另一派了，所以在你完成他交給你的任務之前要三思。', '如果你想要對地精工程學有更多瞭解，就把工程學教材交給鐵爐堡的技工大師歐沃斯巴克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3631 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3631, 'zhTW', '召喚地獄戰馬', '嗯，我覺得你還沒有準備好，但這件事情的決定權不在我手裡。斯坦哈德和我持不同意見，這次是他作的決定。$B$B他要你去見他，越快越好。到貧瘠之地的棘齒城去，他就和他的那些侍僧一起待在塔裡。$B$B不要再閒逛了，快點去。', '與貧瘠之地棘齒城的斯坦哈德·法爾杉談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3632, 'zhTW', '地精工程學', '高階的工程學有兩個分支：地精派和哥布林派，雖然我認為提到地精簡直是浪費時間，但是你還是要對他們的技術保持警惕。他們製造了一大堆號稱可以改變世界的小玩意，但是那些東西很少有能用的。$B$B好吧，$N，讀一下這本手冊。如果你想要學習永遠都派不上用場的垃圾，就把這個交給鐵爐堡的技工大師歐沃斯巴克。請記住，一旦你加入某一派，就永遠也不能再加入另一派了，所以在你完成他交給你的任務之前要三思。', '如果你想要對地精工程學有更多瞭解，就把工程學教材交給鐵爐堡的技工大師歐沃斯巴克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3633, 'zhTW', '哥布林工程學', '高階的工程學有兩個分支：地精派和哥布林派，顯然，哥布林工程學是所有明智的技師都會選擇的一派，用華麗的高爆炸藥和機械裝置統治世界！$B$B好吧，$N，讀一下這本手冊。如果你想要學習哥布林工程學，就把這個交給加基森的尼克斯·斯普克斯賓。請記住，一旦你加入某一派，就永遠也不能再加入另一派了，所以在你完成他交給你的任務之前要三思。', '如果你想要對哥布林工程學有更多瞭解，就把工程學教材交給加基森的尼克斯·斯普克斯賓。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3634 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3634, 'zhTW', '地精工程學', '高階的工程學有兩個分支：地精派和哥布林派，雖然我認為提到地精簡直是浪費時間，但是你還是要對他們的技術保持警惕。他們製造了一大堆號稱可以改變世界的小玩意，但是那些東西很少有能用的。$B$B好吧，$N，讀一下這本手冊。如果你想要學習永遠都派不上用場的垃圾，就把這個交給鐵爐堡的技工大師歐沃斯巴克。請記住，一旦你加入某一派，就永遠也不能再加入另一派了，所以在你完成他交給你的任務之前要三思。', '如果你想要對地精工程學有更多瞭解，就把工程學教材交給鐵爐堡的技工大師歐沃斯巴克。', '', '', '', '', '', '', 0);
