INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3635, 'zhTW', '地精工程學', '高級的工程學有兩個分支:地精派和哥布林派，雖然我認為提到地精簡直是浪費時間，但是你還是要對他們的技術保持警惕。他們製造了一大堆號稱可以改變世界的小玩意，但是那些東西很少有能用的。$B$B好吧，$N，讀一下這本手冊。如果你想要學習永遠都派不上用場的垃圾，就把這個交給藏寶海灣的奧格索普·奧布諾提斯。請記住，一旦你加入某一派，就永遠也不能再加入另一派了，所以在你完成他交給你的任務之前要三思。', '如果你想要對地精工程學有更多瞭解，就把工程學教材交給藏寶海灣的奧格索普·奧布諾提斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3636 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3636, 'zhTW', '與聖光同在', '天譴軍團對聯盟是一個長期的威脅，我想你應該明白這一點。最近，我們偶然發現了一些罕見的東西， $N 。$B$B在貧瘠之地有一片令人恐怖的灌木林稱作剃刀高地。雖然那兒曾經是野豬人的家，但是很明顯，它已經變成天譴軍團的地盤，並衍生出了更加可怕的生物……這些生物都被巫妖『寒冰使者』亞門納爾統治著。$B$B願聖光與你同在， $N ;終結那裡的邪惡吧。', '大主教本尼迪塔斯要你去殺死剃刀高地的『寒冰使者』亞門納爾。', '', '轉至暴風城，去找教堂廣場的大主教本尼迪塔斯。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 3637 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3637, 'zhTW', '地精工程學', '高階的工程學有兩個分支：地精派和哥布林派，雖然我認為提到地精簡直是浪費時間，但是你還是要對他們的技術保持警惕。他們製造了一大堆號稱可以改變世界的小玩意，但是那些東西很少有能用的。$B$B好吧，$N，讀一下這本手冊。如果你想要學習永遠都派不上用場的垃圾，就把這個交給藏寶海灣的奧格索普·奧布諾提斯。請記住，一旦你加入某一派，就永遠也不能再加入另一派了，所以在你完成他交給你的任務之前要三思。', '如果你想要對地精工程學有更多瞭解，就把工程學教材交給藏寶海灣的奧格索普·奧布諾提斯。', '', '', '', '', '', '', 0);
