INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3638, 'zhTW', '保密協議', '地精工程學追求的是高利潤，以及更高的爆破效能！我們可以製作強力的炸彈和無敵的武器，你所閱讀的手冊中就包含這些知識。$B$B這本手冊中還包含了我們古老的保密協議。一旦你成為了地精技師，你就不能轉而成為地精技師。$B$B如果你願意成為地精技師的話，請簽署這份終生保密檔案，然後再次和我說話。請謹慎考慮，$N。', '如果你同意成為一名哥布林技師，就右鍵點選保密協議，然後再次和加基森的尼克斯·斯普克斯賓談一談。', '', '去找塔納利斯的尼克斯·斯普克斯賓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3639 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3639, 'zhTW', '工作成果', '作為你的指導者，我想看看你的工作成果。你是個熟練的技師，這是毫無疑問的，$N。我要對你的工作進行分析，幫助你在地精工程學的光明大道上更快地前進。我需要以下物品：20顆重磅鐵製炸彈、20顆實心炸彈和5只自爆綿羊——注意安全第一！$B$B把這些東西交給我，我就可以發給你一張屬於你自己的地精工程師協會會員卡，如果你想要拜訪世界各地的地精工程學訓練師，這張卡是必須的！', '將20顆重磅鐵製炸彈、20顆實心炸彈和5只自爆綿羊交給加基森的尼克斯·斯普克斯賓。', '', '去找塔納利斯的尼克斯·斯普克斯賓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3640 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3640, 'zhTW', '保密協議', '地精工程學是一門可以滿足我們日常生活需要的科學！我們設計的圖紙讓我們研製出可以控制世界的裝置，你所閱讀的手冊中就包含這些知識。$B$B這本手冊中還包含了我們古老的保密協議。一旦你成為了地精技師，你就不能轉而成為地精技師。$B$B如果你願意成為地精技師的話，請簽署這份終生保密檔案，然後再次和我說話。請謹慎考慮，$N。', '如果你同意成為一名地精技師，就右鍵點選保密協議，然後再次和鐵爐堡的技工大師歐沃斯巴克談一談。', '', '去找丹莫洛的技工大師歐沃斯巴克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3641, 'zhTW', '工作成果', '作為你的指導者，我想看看你的工作成果。你是個熟練的技師，這是毫無疑問的，$N。我要對你的工作進行分析，幫助你在地精工程學的光明大道上更快地前進。我需要以下物品：6根秘銀管、1只精確瞄準鏡和2個高階假人——注意安全第一！$B$B把這些東西交給我，我就可以發給你一張屬於你自己的地精工程師協會會員卡，如果你想要拜訪世界各地的地精工程學訓練師，這張卡是必須的！', '將6根秘銀管、1只精確瞄準鏡和2個高階假人交給鐵爐堡的技工大師歐沃斯巴克。', '', '去找丹莫洛的技工大師歐沃斯巴克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3642 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3642, 'zhTW', '保密協議', '地精工程學是一門可以滿足我們日常生活需要的科學！我們設計的圖紙讓我們研製出可以控制世界的裝置，你所閱讀的手冊中就包含這些知識。$B$B這本手冊中還包含了我們古老的保密協議。一旦你成為了地精技師，你就不能轉而成為地精技師。$B$B如果你願意成為地精技師的話，請簽署這份終生保密檔案，然後再次和我說話。請謹慎考慮，$N。', '如果你同意成為一名地精技師，就右鍵點選保密協議，然後再次和藏寶海灣的奧格索普·奧布諾提斯談一談。', '', '去荊棘谷找藏寶海灣的奧格索普·奧布諾提斯。', '', '', '', '', 0);
