INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3643, 'zhTW', '工作成果', '作為你的指導者，我想看看你的工作成果。你是個熟練的技師，這是毫無疑問的，$N。我要對你的工作進行分析，幫助你在地精工程學的光明大道上更快地前進。我需要以下物品：6根秘銀管、1只精確瞄準鏡和2個高階假人——注意安全第一！$B$B把這些東西交給我，我就可以發給你一張屬於你自己的地精工程師協會會員卡，如果你想要拜訪世界各地的地精工程學訓練師，這張卡是必須的！', '將6根秘銀管、1只精確瞄準鏡和2個高階假人交給藏寶海灣的奧格索普·奧布諾提斯。', '', '去荊棘谷找藏寶海灣的奧格索普·奧布諾提斯。', '', '', '', '', 0);
