INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3661, 'zhTW', '月神之獸?', '梟獸是難以預測的生物， $N 。它們有著極端溫順的一面，如果它們重視的東西受到威脅，這些生物就會變得非常兇猛。$B$B傳說這些野獸是由伊露恩創造的，我對這種說法的真偽很感興趣。$B$B近來，我聽說辛特蘭的梟獸數量越來越多─這些兇殘、原始、野蠻的傢伙在辛特蘭的野外四處橫行。你能幫我收集一些梟獸的羽毛嗎?', '為魯瑟蘭村的艾瑞拉斯·琥珀收集15支梟獸羽毛。', '', '去泰達希爾找魯瑟蘭村的艾瑞拉斯·琥珀。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3681, 'zhTW', '聖潔之書', '你好，我的兄弟。我們這裡最有影響力的聖騎士──達索瑞恩-拉爾最近談起過你。我聽他說過你應該去找他接受試煉了……我也從他那裡聽說過你的出色表現。$B$B如果我是你，而且我有時間的話，我就會去暴風城和他聊聊的。我很肯定他會待在光明大教堂裡──他一般都待在那裡。', '與暴風城的達索瑞恩-拉爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3701 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3701, 'zhTW', '索瑞森廢墟', '到燃燒平原的索瑞森廢墟中去盡可能多地收集情報。$B$B據說那裡散佈著許多神秘的上古聖物，也許你可以在那裡搜尋一番，$N。小心在那裡保護著廢墟的索瑞森的刺客們。', '到燃燒平原的索瑞森廢墟中去，從索瑞森聖物上搜集資訊。當你收集到足夠的資訊之後，就回到皇家歷史學家阿克瑟努斯那裡。', '', '去找鐵爐堡的皇家歷史學家阿克瑟努斯。', '收集情報', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3702 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3702, 'zhTW', '索瑞森廢墟', '你願意聽聽黑鐵矮人的簡要歷史嗎?', '聽皇家歷史學家阿克瑟努斯講述索瑞森的歷史。', '索里森的故事', '去找丹莫羅的皇家歷史學家阿克瑟努斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3721 AND `locale` = 'zhTW';
