INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3790, 'zhTW', '協助大德魯伊鹿盔', '打擾一下，$c，如果可能的話，我想佔用你一點時間。達納蘇斯的塞納里奧議會希望能找到像你這樣經驗豐富的冒險家來幫助他們進行一項重要的研究項目。雖然我不知道詳細的情況，但是我可以告訴你，正是伊范達爾·鹿盔親自負責這項研究。要是你感興趣的話，請直接去達納蘇斯的塞納里奧區找他談談。', '與達納蘇斯的大德魯伊范達爾·鹿盔談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3791, 'zhTW', '晨光麥的秘密', '坦白說吧，$N。我對達納蘇斯的大德魯伊以塞納里奧議會的名義、使用 議會的資源來大量生產晨光麥的原因很感興趣——不，應該說是極度關注。我是一名研究員——研究詛咒是我的專長。我聽說晨光麥在一定的條件下可以像其它草藥那樣用於進行詛咒。$B$B我想了解更多的情況，因此我請求你的幫助。給我帶十株晨光麥回來，我會好好報答你的。', '將10株晨光麥交給羽月要塞的奎恩提斯。', '', '去菲拉斯找索爾多島的奎恩提斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3792, 'zhTW', '羽月要塞的晨光麥', '', '', '', '去找菲拉斯的奎恩提斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3801, 'zhTW', '黑鐵的遺產', '你好，$N。我是弗蘭克羅恩·鑄鐵。沒錯，正是我創造了以石頭為基礎的建築方法。在探索這個飽受戰爭創傷的世界的旅途中，你一定見過了不少由我設計建造的建築物。$B$B你也許想要知道我為什麼在這裡，以及我想要你幫我做些什麼——這些問題都很合理。$B$B我當然需要你的幫助。作為請求你幫助我的交換條件，我會給你一把鑰匙，讓你得以進入這座由我建造的……被詛咒的城市。', '如果你想要得到進入這座城市主城區的鑰匙，就去和弗蘭克羅恩·鑄鐵談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3802, 'zhTW', '黑鐵的遺產', '你可以在律法之環外的工匠大廳裡找到弗諾斯·達克維爾。殺掉那個卑鄙的傢伙，拿回我的鐵膽之錘。$B$B把鐵膽之錘拿到索瑞森神殿去，然後把它放在正確的地方——就是我的雕像的手裡。$B$B當你把鐵膽之錘放上去之後，我存放主宰鑰匙的那個小機關將會開啟。更重要的是，鐵膽之錘將會永遠掌握在我的手中。如果有人想要拿走戰錘的話，那整座雕像和戰錘都會碎裂，永遠無法修復。', '殺掉弗諾斯·達克維爾並拿回戰錘鐵膽。把鐵膽之錘拿到索瑞森神殿去，將其放在弗蘭克羅恩·鑄鐵的雕像上。', '', '轉至黑石深淵，在索瑞森神殿中找到弗蘭克羅恩·鑄鐵的雕像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3803, 'zhTW', '達納蘇斯的晨光麥', '', '', '', '去找泰達希爾的瑪斯雷·馭熊者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3804, 'zhTW', '雷霆崖的晨光麥', '', '', '', '去找淒涼之地的巴珊娜·符文圖騰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3821, 'zhTW', '巨槌石', '沙妮被派去調查過去三個星期以來燃燒平原上的那些火腹食人魔所進行的一些奇怪儀式。$B$B高圖斯告訴我說沒有聽到過任何關於那支部隊的訊息，所以他建議我最好不要再管這件事情，繼續自己手頭上的工作。你相信他居然這麼說了嗎？要知道沙妮是我的妻子啊！$B$B我不能離開我的哨所，$N，但是我必須要知道沙妮現在怎麼樣了。到燃燒平原去，找到她。', '到燃燒平原去找到沙妮·長齒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3822, 'zhTW', '克羅格魯爾', '$N，我們整支小分隊都被抓住了，除了我之外的所有同伴都被殺了。$B$B他們的頭領克羅格魯爾想要把我留下來舉行某種儀式。$B$B我被綁在這個祭壇上，被那些野獸用酷刑折磨。不到一個小時，我就被活活折磨致死。那個野獸摘下了我的結婚鼻環，把它戴在了自己的手上。我從來沒有見過如此無恥殘暴的行為！$B$B找到克羅格魯爾，殺了他！把我的戒指交給薩特拉克。$B$B另外，$N，告訴他，我們會再次見面的……來世再見……', '從克羅格魯爾手中拿回沙妮的鼻環，把它還給卡加斯的薩特拉克。搜尋巨槌石的每一處山洞和礦井。', '', '去荒蕪之地找卡加斯的薩特拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3823, 'zhTW', '消滅火腹食人魔', '我們必須先發制人！$B$B我先簡單地向你介紹一下現在的狀況，士兵。$B$B燃燒平原上的火腹食人魔是黑石獸人的盟友。它們和那些邪惡的獸人一起工作，幫助守衛蘊藏著豐富礦藏的巨槌石，並保證那條補給線一直正常運作。$B$B現在出發吧，$N。削弱他們的力量然後回來向我報告。$B$B<奧拉留斯向空中伸出手，然後作出被掐住脖子的表情。>$B$B我要殺了你，溫奇！', '殺掉15個火腹食人魔法師、7個火腹食人魔和7個火腹蠻兵，完成任務之後向奧拉留斯報告。', '', '去燃燒平原找摩根的崗哨的奧拉留斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3824 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3824, 'zhTW', '蠻王戈泰什', '我告訴你，他們現在已經被搞得暈頭轉向了！我們的下一步行動將是決定性的。$B$B幹掉那個野蠻的食人魔之王戈泰什。更重要的是，你必須把他的頭帶回來，這樣我就可以準備對火腹食人魔發動第三次攻擊了。$B$B你要留神，士兵，戈泰什並不在巨槌石上，而是在巨槌石西面的某座黑石獸人的建築物中。$B$B你的任務很簡單。找到戈泰什，然後砍掉他那肥大的腦袋。完成任務之後回到我這裡來。$B$B閉嘴，溫奇！', '找到戈泰什，他應該在巨槌石西面的某處。殺掉戈泰什並把他的頭顱交給燃燒平原的奧拉留斯。', '', '去燃燒平原找摩根的崗哨的奧拉留斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3825 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3825, 'zhTW', '梟首示眾', '士兵，你還有最後一件事要做。$B$B我已經把戈泰什的頭顱掛在了一支長矛上。現在你要做的就是把這支長矛帶到巨槌石的山頂去，把它插在地上。這樣，你就能看到那些怯懦的食人魔四散逃竄了！當你完成這個任務之後，回到我這裡來，我會為你的辛勤工作而獎勵你的。$B$B<奧拉留斯看上去有些出神。>', '把戈泰什的頭顱放在巨槌石的山頂上。找一塊軟土堆把串著頭顱的長矛插上去就可以了。', '', '去燃燒平原找摩根的崗哨的奧拉留斯。', '放置戈泰什的徽記', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3841, 'zhTW', '領養孤兒', '噢，你好，$N。很高興再次見到你。去達納蘇斯的旅途怎麼樣？$B$B你不在的這段時間裡，我們取得了相當大的進展，你會為此感到高興的。我們甚至儲存了一整巢的蛋。不幸的是，我們找到這些蛋的母親的時候，它已經死掉了。$B$B呃，你要取一隻作為寵物嗎？它們很快就要孵化了，所以它們會需要一個好$G父親:母親的。你認為呢？$B$B如果你真的感興趣的話，請帶上一顆蛋，到閃光平原的賽車場去找奎恩丁。他會告訴你更多細節的。', '與千針石林的奎恩丁談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3842, 'zhTW', '即將孵化', '辛達爾和耶爾卡？這可太有意思了。我希望那些小精龍能意識到她們的一片好心。她們倆都相當能幹。$B$B這樣看來，她們把這顆蛋作為禮物送給你了。呃，好吧，現在你應該對這顆蛋負責了。看起來它馬上就要孵化了，但是我們應該確定它是健康的。$B$B我需要兩份堅韌藥劑，然後用它們來施放一個小小的法術保護這顆蛋。至於其它的材料，我這裡就有。', '將2份堅韌藥劑交給千針林的奎恩丁。', '', '去千針石林找沙漠賽道的奎恩丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3843, 'zhTW', '新的生命', '很不錯，$N。如果它的媽媽活著生下它的話，那它將是一隻健康的寵物！$B$B要是你正巧要去辛特蘭的鷹巢山，那我建議你去找一個名叫阿格納的矮人談談，他精於訓練動物，可以就孵化的最終步驟對你進行指導。$B$B但是你一定要快，$N，這顆蛋很脆弱，要是沒有悉心的照料，它可活不了多久。', '帶著這枚脆弱的小精龍卵去辛特蘭，與阿格納談一談，但是你一定要在它還有生命力的時候趕到，在蛋裡的小生命夭折之前，你只有1小時的時間。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3844, 'zhTW', '無人知曉的秘密', '一艘被毀壞的小艇擱淺在岸邊。這裡是個小池塘，為什麼會有一艘小艇擱淺在這裡就不得而知了，不過從樹上的痕跡來看，這裡的水位並不是一直不變的。$B$B也許在附近繼續搜查一下的話有可能發現更多的線索……', '在池塘附近查詢與擱淺的小艇有關的線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3845, 'zhTW', '無人知曉的秘密', '你把那隻袋子從水中拉上了岸。如果你檢查一下袋子中的東西，那麼你應該可以知道它是誰的袋子。$B$B在馬紹爾營地那裡有一些迷路的旅行者，也許你可以在那裡發現更多的線索。', '檢視袋子裡的東西，然後將它們交給物主。', '', '去安戈洛環形山找馬紹爾營地的林克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3861, 'zhTW', '咕咕嘎！', '“咕咕嘎……咕咕嘎……咕咕！$B$B咕咕嘎……咕咕嘎……咕咕。”$B$B小雞抬頭看著你，然後伸出爪子探到地面上。你認為它是在拼寫某個單詞，但是又不確定是什麼單詞。S-A-L-D-E-A-N…C-o-o-C-e-l-y…是指薩丁農場嗎？在你發出詢問之前，小雞轉過身子，做它自己的事兒去了。', '找一些特殊的雞飼料，把它交給友好的小雞。當你找到小雞的時候，在餵食牠特殊的雞飼料之前，先對牠做出歡呼的動作。（使用/cheer命令）', '', '去找雞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3881, 'zhTW', '搶救物資', '我不知道你是怎麼到這兒來的，但是你可真是個受歡迎的$r！我是威利德·馬紹爾，這支中立探險隊的頭兒。我們的小隊近來遭受了一連串災難，其中最為嚴重的就是我們低估了安戈洛環形山的蠻荒程度！$B$B我們在逃離位於環形山西南部和東北部的營地時落下了重要的物資。你似乎是個足夠強壯的$r——能幫助我們去取回這些物資嗎？', '將食物箱和研究裝置交給安戈洛環形山的威利德·馬紹爾。', '', '去安戈洛環形山找馬紹爾營地的威利德·馬紹爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3882 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3882, 'zhTW', '挖骨頭', '你也許認為我在馬紹爾探險隊裡當挖掘工是因為我喜歡這活兒，好吧，世上可能的確有比這更糟糕的差事……但是我還真沒見過。$B$B我們本應是在恐懼小道那個鬼地方進行劍龍和雙帆龍化石的挖掘工作——順便提一句，那地名可真古怪。呃，那兒也有許多活著的恐龍！威利和霍萊堅持要研究這些東西，所以我們還是得弄些恐龍骨頭來。咱們私下裡說說，其實你只要從活著的恐龍身上給我取些骨頭回來就行了。', '將8根恐龍骨頭交給安戈洛環形山的斯巴克·尼米爾。', '', '去安戈洛環形山找馬紹爾營地的斯巴克·尼米爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3883, 'zhTW', '異型的生態', '我們僅僅遭受到了一點挫折，這並不意味著我們要停止研究！在被迫逃到這裡之前，我們曾調查過環形山南部地區的格里什昆蟲。它們與安戈洛的生態環境有些格格不入，我們想要查明原因。在它們的巢穴中必然存在幼蟲的孵化室，你可以可透過那些懸垂在天花板上的蟲卵來判斷幼蟲孵化室的所在。隨便找一個這樣的孵化室，刮取一份蟲穴內壁的樣本，把它裝到這個小瓶子裡交給我，但是你要多加小心！', '使用採集瓶從安戈洛環形山的某個格里什蟲巢的孵化室中收集一份巢穴側壁的樣本，在有懸掛著的蟲卵的房間裡收集樣本。$B$B將蟲穴內壁樣本交給安戈洛環形山的霍萊伊·馬紹爾。', '', '去安戈洛環形山找馬紹爾營地的霍萊伊·馬紹爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3884 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3884, 'zhTW', '威利德的日記', '你找到了一本被撕破的日記，其中的某些部分仍然清晰可辨，目錄中有威利德·馬紹爾的署名。如果日記上面的記載沒錯的話，那麼你可以在環形山的北部地區找到威利德。根據日記中所說的，他和他的同伴們的營地被襲擊了，所以他們不得不尋找更高處的空地紮營，以避開橫行在環形山裡的兇殘野獸。', '將日記還給安戈洛環形山中的威利德·馬紹爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3885 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3885, 'zhTW', '暫無內容', '護送我和達丹加！', '護送派提亞和達丹加！', '護送派提亞和達丹加！', '去找派提亞·格羅森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3901, 'zhTW', '斷骨骷髏', '你向被遺忘者展示了你在正常情況下的潛力， $N 。現在讓我們看看你在壓力下的表現吧。$B$B斷骨骷髏是巫妖王手下更為盲從的爪牙之一，與你先前幹掉的殭屍相比，牠們更為強韌也更為兇殘。殺掉它們，再次向被遺忘者證明你的能力吧。別耽擱時間，完成任務後立刻來找我交談。', '殺死8個斷骨骷髏。', '', '去提里斯法林地找喪鐘鎮的暗影牧師薩維斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3902 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3902, 'zhTW', '撿破爛', '嘿，說你呢!要是你想實現自己的價值，那就聽好了!$B$B我們要求那些剛剛爬出墳墓的新兵前往喪鐘鎮，搜尋任何可以為我們所用的裝備，這些裝備極有可能裝在成堆的箱子裡。我們希望能立即招募到更多的新兵，因此，除非我們想讓他們赤手空拳地上陣，否則我們就得搜尋一切可用之物!$B$B開始工作吧，你這堆可悲的骨頭!對那些不努力工作的傢伙，我可是不會給予回報的。', '在喪鐘鎮及臨近地區搜尋6件破爛裝備，把它們交給亡靈衛兵薩爾坦。', '', '去提里斯法林地找喪鐘鎮的亡靈衛兵薩爾坦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3903, 'zhTW', '米莉·奧斯沃斯', '你是個值得信賴的$c，$N。可靠，而且不畏懼戰鬥，對嗎?我有個朋友名叫米莉·奧斯沃斯，她遇到麻煩了。她就在修道院另一邊的馬廄旁，我想她可能需要你的幫助。', '與米莉·奧斯沃斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3904, 'zhTW', '米莉的葡萄', '一夥迪菲亞盜賊趁我採收的時候闖進了北郡農場!我將這件事情報告給了北郡的衛兵，他們向我保證會儘快解決，但是……我擔心我的那些葡萄!即使迪菲亞盜賊不去偷盜葡萄，恐怕那些衛兵在剿滅盜賊的過程中也會踩壞它們。$B$B你一定得幫助我!我把大部分的葡萄都裝在木箱裡了，但是我把它們留在了東南邊的農場。$B$B把那些木箱給我拿回來吧!救救我的收成!', '收集8箱米莉的葡萄，把它們交給北郡修道院的米莉·奧斯沃斯。', '', '去艾爾文森林找北郡山谷的米莉·奧斯沃斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3905 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3905, 'zhTW', '葡萄出貨單', '我的作物完好無損，請將這張葡萄出貨單交給尼爾斯修士。他在北郡經營一家銷售食品和飲料的商店，我敢說當他知道他可以得到一批新鮮葡萄時一定會很高興的。$B$B你可以在修道院的鐘塔上找到尼爾斯修士，他喜歡在那兒飲酒。', '將葡萄出貨單交給北郡修道院的尼爾斯修士。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3906 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3906, 'zhTW', '不和諧的烈焰', '部落的長老感覺到元素中的一種擾動。黑鐵矮人召喚出了一個骯髒的靈魂，這個靈魂將用沖天的大火完全毀滅這個世界。我們必須調查這種不和諧的火焰的來源。$B$B到黑石山脈去，穿過火焰裂口，進入採石場。你應該可以在那裡找到火焰之王——征服者派隆。$B$B解決這個造成擾動的源泉，然後向我回報。', '到黑石山脈的採石場去幹掉征服者派隆，然後向桑德哈特回報。', '', '去荒蕪之地找卡加斯的桑德哈特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3907 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3907, 'zhTW', '不和諧的火焰', '我可以嗅出空氣中的邪惡氣息，$N。在黑石山脈的深處依然隱藏著另一個控制著這種邪惡氣息的生物。$B$B風和大地都在哭喊著它的名字：伊森迪奧斯領主……但是有人……有什麼東西……控制這這個生物，它只是一個傀儡。$B$B找到它，找到它背後的主使者藏匿的地方。當你收集到這些資訊之後就立刻回來向我報告。', '進入黑石深淵並找到伊森迪奧斯領主。殺掉它，然後把你找到的資訊彙報給桑德哈特。', '', '去荒蕪之地找卡加斯的桑德哈特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3908 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3908, 'zhTW', '無人知曉的秘密', '你看，我已經對自己為什麼會在這裡完全沒有概念了。沒有人知道——這對所有的人來說都是個秘密！我什麼都記不起來了……$B$B不過……你帶給我的東西卻讓我想起了什麼……$B$B我的劍！我想起來了，原本我是要去將其加強的，但是我不知道我為什麼要那麼做。很抱歉我不能告訴你更多的資訊，因為我確實什麼都記不起來了！$B$B不管怎麼樣，我知道你應該把劍帶到什麼地方去——把它交給冬泉谷的多諾瓦·雪山。你可以在溫泉旁邊找到她，她會用溫泉的泉水來給劍中注入力量。', '把林克的劍交給冬泉谷的多諾瓦·雪山。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3909 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3909, 'zhTW', '視靈藥劑', '什麼，你說什麼？林克……失憶了？$B$B哦，我明白了……他失去了自己的記憶……$B$B好吧，這是他的劍。但是它並不完整。我知道有人可以把它變得完整，但是……和他說話也許會很困難。$B$B聽著，我知道有人可以幫助你，現在我沒法把一切都給你解釋清楚，總之你一定要得到視靈藥劑。我所知道的唯一一個可以幫你的人就是格雷甘·山酒了。他行蹤不定，但是我知道他眼下正在菲拉斯一帶活動。', '去菲拉斯找格雷甘·山酒。從他那裡問到獲取視靈藥劑的方法，然後向冬泉谷的多諾瓦·雪山覆命。', '', '去找冬泉谷的多諾瓦·雪山。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3910 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3910, 'zhTW', '暫無內容', '歡迎來到加基森！帶我們回家吧……', '護送派提亞和達丹加！', '護送派提亞和達丹加！', '去找派提亞·格羅森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3911 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3911, 'zhTW', '最後的元素', '只有那些進入深淵的冒險者才能迎接這個挑戰，$N。$B$B黑鐵矮人已經掌握了製造強大的作戰魔像的方法。$B$B來自間諜的報告顯示，那些矮人使用某種獨特的能量源為他們所創造的魔像提供無與倫比的殺戮能力。$B$B如果我們能得到這種元素精華的話，我們的憎惡怪就可以得到極大的加強！把那座城市翻個底朝天也在所不惜，找不到精華你就別回來！我們給予的報酬值得你去冒這個險。', '到黑石深淵去取得10份元素精華。你應該在那些作戰魔像和魔像製造者身上找找，另外，薇薇安·拉格雷也提到了一些有關元素生物的話題……', '', '去荒蕪之地找卡加斯的暗法師薇薇安·拉格雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3912 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3912, 'zhTW', '墓地相見', '這瓶藥劑可以讓你和那些普通狀態下無法看見的生物對話……$B$B把這瓶視靈藥劑和林克的劍帶到塔納利斯去，在加基森鎮外的墓地中喝下這瓶藥劑。你也許會對它所產生的效果感到奇怪，但是不要為此擔心。$B$B在你處於“另外”一種形態的時候，一直往北走到山的旁邊，你要找的人就在那裡的石壁縫裡，他的名字叫加里楊。$B$B記住，只有你在那種形態下的時候，他才會和你對話。', '在加基森鎮外的墓地中使用視靈藥劑，然後按照多諾瓦的指示找到加里楊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3913 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3913, 'zhTW', '尋找墓碑', '如果你回到墓地，$N，你會在那裡找到一塊墓碑……那不是一塊普通的墓碑，它非常顯眼。秘密就隱藏在其中。$B$B推動墓碑，然後你就可以發現那些秘密……', '復活，然後尋找加里楊讓你去找的那塊墓碑。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3914 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3914, 'zhTW', '林克的劍', '一陣強光閃過之後，你再次撿起了那把劍。它已經完全變成另一種樣子了！', '把林克的強化之劍交給安戈洛環形山的林克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3921, 'zhTW', '維妮·布特巴克', '我想我可能已經把主動式負載平衡器給弄壞了。這可不太妙，因為我已經對安德麥的一些同伴談及它了，而且他們對此非常感興趣。我們必須想辦法修好它！$B$B把這個壞掉的主動式負載平衡器交給維妮·布特巴克，她就在貧瘠之地和梣谷之間的部落前哨站裡。她非常聰明而且好奇，如果你將主動式負載平衡器給她看的話，我敢打賭她會欣然幫你修理它。', '將損壞的主動式負載平衡器交給維妮·布特巴克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3922, 'zhTW', '高強度齒輪', '我想修好這個主動式負載平衡器，但是，我需要一些材料。我用光了17.5規格的高強度齒輪，而我需要很多這樣的東西才能繼續工作。$B$B要弄到這種齒輪的話，最近的地方是東面的淤泥沼澤。風險投資公司的傢伙們通常會把齒輪放在他們的工具桶裡。到淤泥沼澤去，檢查一下你在那裡找到的工具桶，當你搜集了足夠的高強度齒輪後再回到我這裡來。', '把15個高強度齒輪交給貧瘠之地的維妮·布特巴克。', '', '去找貧瘠之地的維妮·布特巴克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3923, 'zhTW', '雷裡·格里斯高布', '好吧，我失敗了。我在主動式負載平衡器上安裝了更多的儀表來測量它的結構完整度，讀出來的資料表明現在的完整度很低。我也許需要加些轉盤或者一兩根槓桿來繼續嘗試，但是……沒準我把它會搞得更糟。$B$B你應該把主動式負載平衡器交給雷裡·格里斯高布。他過去是為風險投資公司幹活的——如果有人知道該怎麼修理這玩意的話，那一定就是雷裡了。$B$B你可以在奧格瑪榮譽谷中的諾格機械店找到他。', '把破碎的主動式負載平衡器交給奧格瑪的雷裡·格里斯高布。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3924, 'zhTW', '主動式負載平衡器說明書', '我想我可以修復主動式負載平衡器，但首先我需要一本使用者手冊。當我在風險投資公司幹活的時候，我有個名叫考博普拉格的對手……他會把主動式負載平衡器的秘密告訴那些他信任的同黨。不過我不是他的親信……$B$B考博普拉格應該在貧瘠之地東北部的石礦洞裡。從他那裡把手冊拿過來，如果他把其中的一部分給了其他人的話，你也要把它們一起拿來。', '把主動式負載平衡器說明書交給奧格瑪的雷裡·格里斯高布。', '', '去找奧格瑪的雷裡·格里斯高布。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3941 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3941, 'zhTW', '地精的援助', '讓我想想……讓我想想……我來這裡肯定是為了某個很重要的事情……$B$B我有個辦法，$N。那邊的那個洞穴裡有個叫科琳的地精，我記得我剛到這裡的時候她給我留下了很好的印象。也許在我思維混亂的時候曾向她提過一些關於我的東西。$B$B為什麼你不去問問她呢？哦，不過你要小心——她對這個地區的那些水晶表現得特別瘋狂，我不知道她究竟想幹什麼！', '到馬紹爾營地那裡的山洞中去找科琳。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3942 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3942, 'zhTW', '林克的記憶', '哦……林克？當然，他是個有趣的傢伙，他剛到這裡的時候總是對所有奇怪的事情喃喃自語。也許他的腦袋被什麼東西敲過了。$B$B他說的一些話給我留下了較深的影響——他好像要做什麼圖騰，還說要去找一個叫什麼艾瑞丹·藍風的夜精靈……如果我沒記錯的話，她好像在費伍德森林。$B$B我不知道她是否能告訴你更多的東西，如果你想要知道什麼的話，為什麼你不去問問艾瑞丹自己呢？', '到費伍德森林去找艾瑞丹·藍風。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3961, 'zhTW', '林克的冒險', '真難想像林克來這裡居然是為了幫助我們除掉火焰使者……他看上去是那麼普通的一個地精，但是我確實感覺到他和別的地精有些不同，他居然對我的實驗或者小裝置一點都不感興趣！他一定擁有一顆真正的戰士之心。$B$B把圖騰交給他，看看這是否能夠幫助喚起他的記憶。', '把亞奎門塔斯的銀圖騰交給馬紹爾營地裡的林克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3962, 'zhTW', '結伴而行', '$N，我終於想起來了……我來這裡是要和火焰使者作戰的。我經歷了一段漫長的旅途，原本最重要的目標就是它。$B$B但是我不再是英雄了……你才是。迄今為止你已經做了那麼多——應該由你來完成這個任務，而不是我。$B$B去找到火焰使者並打敗它吧。它守護著一個被稱作金色火焰的神器，這個神器的力量比我所見過的任何東西都要強大，如果它落在邪惡勢力的手中，那會是一件非常危險的事情。$B$B你應該找些同伴一起去完成這個任務——獨自行動是很危險的。', '到馬紹爾營地南邊的火羽山去。$B$B找到火焰使者，並使用圖騰除掉它的防護光環。在擊敗它之後從洞中取得金色火焰。', '', '去安戈洛環形山找馬紹爾營地的林克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3981, 'zhTW', '指揮官哥沙克', '可憐的加加爾……他甚至沒有看到那支箭射過來。咔的一聲！它就射中了他的眉心。他並不機靈，但是現在……$B$B<賈拉瑪弗露出了痛苦的表情。>$B$B當我們拔出那支箭之後，我們注意到在箭桿上包著一張便箋。那上面草草地畫著一個鐵欄後面的獸人，下面還有指揮官哥沙克的簽名。$B$B如果他還活著的話，你就要到黑石深淵去找到他。$B$B你說這是個陷阱？廢話，你這蠢貨！不然我要你去幹什麼！', '在黑石深淵裡找到指揮官哥沙克。$B$B在那幅草圖上畫著的是一個鐵欄後面的獸人，也許你應該到某個類似監獄的地方去找找看。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 3982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (3982, 'zhTW', '出了什麼事？', '我受索爾的差遣來到這裡，你真的認為這些小丑可以抓住我嗎？我是主動送上門的，這樣我才能從他們這裡收集情報。$B$B<哥沙克壓低了聲音。>$B$B黑鐵皇帝索瑞森綁架了鐵爐堡的公主，她就被關押在這座城市裡！我敢打賭，當老麥格尼聽到這個訊息時，他的心臟大概會停止跳動的。$B$B<哥沙克大笑了起來。>$B$B噓～～！你聽到了嗎？衛隊來了！準備戰鬥！', '保護哥沙克。', '擋住敵人的進攻', '去找黑石深淵的指揮官哥沙克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4001, 'zhTW', '出了什麼事？', '到目前為止，我與大廳房間中的矮人卡蘭之間的交流都很有限。但是我已經努力使他相信我——更準確地說，我們——對他沒有惡意。$B$B過去跟他談談吧，儘可能多地收集有關公主和綁架他的那些傢伙的情報，然後將這些情報反饋給酋長。$B$B索爾不想讓公主受到傷害，而是準備了某個重要的計劃，其中包括使公主安全地返回鐵爐堡。卡蘭已對此瞭如指掌……快去吧！', '與卡蘭·巨錘談一談，收集關於綁架公主鐵爐堡公主茉艾拉·銅鬚這一事件的情報。將情報反饋給奧格瑪城裡的索爾。$B$B哥沙克提到過卡蘭被關在附近的某個牢房中。', '從卡蘭那裡收集情報', '去找奧格瑪的索爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4002, 'zhTW', '東部王國', '你帶來了非常有價值的情報，$N。$B$B作為酋長，我的職責就是做一切對部落有益的事情，以確保我們的後代有一個光明的未來。$B$B一個結交新盟友的機會已經落在了我們的肩上。幫助矮人的舉動可以極大地改善我們與東部王國的關係。這就是你絕對不能失敗的原因！$B$B你準備好了嗎？', '如果你準備好要接受索爾所安排的任務，就去找他談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4003 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4003, 'zhTW', '拯救公主', '這次行動是針對黑鐵矮人的，如果我們成功了，那麼他們的整個王國都將遭到一次巨大的衝擊。$B$B茉艾拉公主正處於索瑞森大帝的控制之下。要想救她的話，你就必須殺了索瑞森。千萬小心，你的任務非常危險，因為公主可能會在索瑞森的控制下向你發起攻擊。$B$B不要傷害她！', '殺掉達格蘭·索瑞森大帝，然後將鐵爐堡公主茉艾拉·銅鬚從他的邪惡詛咒中拯救出來。', '', '轉至黑石深淵，去找王座附近的公主茉艾拉·銅鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4004 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4004, 'zhTW', '拯救公主？', '你殺了我的丈夫！我的孩子誕生之後將會沒有父親。$B$B<茉艾拉公主直指著你。>$B$B我向你保證，這個孩子會成為鐵爐堡的下一任統治者。你和你的同類將會因為今天的所做所為而付出代價。$B$B<你認為茉艾拉公主也許是受到了索瑞森的法術影響才變成這樣。>$B$B讓我獨自留在這裡，$r。你的酋長一定正在急切地想要知道他管閒事的結果。', '向索爾報告！', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4005 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4005, 'zhTW', '亞奎門塔斯', '把所有你收集的東西和這本書都帶到塔納利斯去。在落帆海灣尋找一個石頭法陣，最東邊的半島應該就是秘密所在……$B$B當你身處石陣之中的時候，誦讀阿奎爾之書，你將召喚出一個可以將你所收集的東西轉化為一支與火焰使者作戰所必需的圖騰。$B$B亞奎門塔斯被人喚醒當然不會高興，但是你要記住，在它轉換圖騰的這段時間裡，你一定要待在石陣裡面。', '把阿奎爾之書、銀爪和鐵樹之心帶到塔納利斯去。$B$B使用這本書召喚亞奎門塔斯。$B$B在圖騰完成之後，把它交給馬紹爾營地的科琳。', '', '去找安戈洛環形山的科琳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4021, 'zhTW', '人馬無雙！', '部落對你戰勝科卡爾部族的功績感到非常高興，但是科卡爾部族卻為此發了狂。有報告稱科卡爾部族的一支從淒涼之地來到了貧瘠之地，準備進行報復。到目前為止，我得到的最新訊息是：他們已經在從西面往這裡進發了！$B$B去迎戰科卡爾部族的入侵者吧，徹底結束他們對貧瘠之地的威脅！殺死那些該死的半人馬，直到他們的首領——督軍克羅姆扎出現在你面前，幹掉他，把他的旗幟撕下一片作為證據。$B$B我們都指望你了，$N。', '將克羅姆扎軍旗的碎片交給十字路口西邊的雷戈薩·死門。', '', '去找貧瘠之地的雷戈薩·死門。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4022, 'zhTW', '烈焰精華', '那些飛龍已經注意到你在灼熱峽谷中的所作所為了。$B$B向我展示你的能力，$c。我要的是龍皮，你這個蠢貨。', '向塞勒斯·薩雷芬圖斯展示你從卡拉然·溫布雷那裡得到的黑龍軍團之皮。', '展示證據', '去燃燒平原的滑石找塞勒斯·薩雷芬圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4023, 'zhTW', '烈焰精華', '你找到那些黑龍了？那就向我證明你的價值吧，$c。', '向塞勒斯·薩雷芬圖斯證明你的價值。$B$B你感覺到塞勒斯似乎對你不屑一顧。', '', '去燃燒平原找在滑石的塞勒斯·薩雷芬圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4024, 'zhTW', '烈焰精華', '我要為火焰之山中的炙熱烈焰歌唱，我要讓黑石山的熔岩瀑布貫穿我的身體。我所渴求的就是那種精華，那種炙焰的感覺。$B$B在黑石深淵住著一個純火焰鑄成的怪物：貝爾加，他是從拉格納羅斯的火焰中誕生的。殺掉貝爾加，然後從他燃燒的身體中取出他心中的烈焰。$B$B使用變化後的黑龍軍團之皮就可以安全地萃取這種烈焰。$B$B大功告成後，你會獲得獎勵的。', '到黑石深淵去殺掉貝爾加。$B$B你只知道這個巨型怪物住在黑石深淵的最深處。記住你要使用變化後的黑龍軍團之皮從貝爾加的屍體上採集烈焰精華。$B$B將你採集到的烈焰精華交給塞勒斯·薩雷芬圖斯。', '', '去燃燒平原找在滑石的塞勒斯·薩雷芬圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4041, 'zhTW', '視靈藥劑', '', '', '', '去找菲拉斯的格雷甘·山酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4061, 'zhTW', '機器的崛起', '在我們最初進攻灼熱峽谷的時候就已經見識過了那些機器。在進行了更深入的調查之後，我們發現它們是從燃燒平原運送過來的——當然也可能是從黑石深淵裡運出來的。這就是我們需要你幫忙的原因，$N。$B$B你的第一件任務是到燃燒平原去，從那裡的石頭魔像身上收集一些元素裂片。一旦你收集到足夠數量的裂片之後就回到我這裡來，我會鑑定它們的來源。', '到燃燒平原去為塞朵拉·穆瓦丹尼收集10塊斷裂的元素裂片。$B$B塞朵拉曾經說過，那裡的機械魔像和元素生物是這種裂片的主要來源。', '', '去荒蕪之地找卡加斯的塞朵拉·穆瓦丹尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4062, 'zhTW', '機器的崛起', 'G.L.A.$B$B那些裂片上刻著這樣的文字。在這些大寫字母下面有一個軍銜標誌。你在燃燒平原所摧毀的機器的等級是四，我相信這是個比較低的軍銜。$B$B把這塊裂片樣品交給東邊一處營地裡的魯特維爾·沃拉圖斯吧，他是個著名的元素學者，應該能對我們的研究有所幫助。', '將元素裂片樣本交給魯特維爾·沃拉圖斯。$B$B塞朵拉說魯特維爾就在東邊的一處營地裡。', '', '去找荒蕪之地的魯特維爾·沃拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4063 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4063, 'zhTW', '機器的崛起', '不可能是阿格曼奇！因為阿格曼奇在十年前就被殺掉了。什麼？我為什麼那麼肯定？因為我就是殺死他的人之一。$B$B他是個卑鄙的矮人，為了自己的邪惡計劃而逼我為他工作。看來壞蛋總有辦法逃脫正義的懲罰。$B$B如果這一切都是阿格曼奇幹的，那他就必須死！你去幫我弄些他最近製造的傀儡人的樣品來吧，如果有合適的樣品，我們也許就可以阻止他了。那些東西在黑石深淵裡守護著阿格曼奇。', '找到並殺掉魔像領主阿格曼奇，將他的頭交給魯特維爾。你還需要從守衛著阿格曼奇的狂怒魔像和戰鬥魔像身上收集10塊完整的元素核心。', '', '去找荒蕪之地的魯特維爾·沃拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4081 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4081, 'zhTW', '格殺勿論：黑鐵矮人', '根據卡加斯探險隊的指揮官督軍高圖斯的命令：$B$B黑石深淵中所有安格弗將軍麾下的部隊必須全部消滅。$B$B安格弗的下屬都是殺人不眨眼的暴徒，正是他們殺害了卡加斯探險隊109分隊的成員。遇到這群窮兇極惡的歹徒的時候要特別小心。$B$B任何能消滅黑石深淵安格弗將軍麾下部隊的勇士都將得到獎勵。', '到黑石深淵去消滅那些邪惡的侵略者！$B$B督軍高圖斯要你去殺死15個鐵怒衛士、10個鐵怒獄卒和5個鐵怒步兵。完成任務之後回去向他覆命。', '', '去荒蕪之地找卡加斯的督軍高圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4082 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4082, 'zhTW', '格殺勿論：高階黑鐵軍官', '根據卡加斯探險隊的指揮官督軍高圖斯的命令：$B$B偵查分隊的首領雷克斯洛特帶回了關於高階黑鐵軍官行蹤的情報。他們在戒備森嚴的城市中心地帶訓練部隊，準備對付我們。到黑石深淵去消滅他們！$B$B完成這個任務將可獲得豐厚的獎勵。', '到黑石深淵去消滅那些邪惡的侵略者！$B$B督軍高圖斯要你殺死10個鐵怒醫師,、10個鐵怒士兵和10個鐵怒軍官。完成任務之後回去向他覆命。', '', '去荒蕪之地找卡加斯的督軍高圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4083 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4083, 'zhTW', '鬼魂之杯', '', '', '', '去找奧特蘭克山脈的鬼魂之杯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4084 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4084, 'zhTW', '銀爪鐵心', '我不知道你說的那個人是誰，$N。$B$B但是請不要擔心，如果你的朋友原本打算大老遠地來找我的話，我應該可以想像到他需要什麼。$B$B在安戈洛環形山的中心地帶有一個極端邪惡的惡魔，它以一個名叫火焰使者的元素生物的形象出現……它被一層任何人都無法驅散的光環保護著……$B$B沒有人可以驅散……除非有足夠的力量。我可以教你如何獲得這樣的力量，$N。$B$B首先按我說的去做，從費伍德森林的生物身上收集11個銀爪和1個鐵樹之心，然後回來找我。', '為費伍德森林的艾瑞丹·藍風收集11只銀爪和1顆鐵樹之心。', '', '去費伍德森林找翡翠聖地的艾瑞丹·藍風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4101, 'zhTW', '淨化費伍德', '植物給與費伍德森林以生命，然而即使是它們也遭受了腐化和墮落的痛苦。我知道淨化它們的方法，但是我不會把這種方法告訴一個我不熟識或者不能信任的$r。向我證明你真的能幫助塞納里奧議會！$B$B這裡的北面有一個鐵木山洞，那裡的曲木元素已經無法挽救了。我要你幫我從它們身上取得樹汁，這些樹汁被稱作血琥珀。有了它們，我就可以研究拯救其它生命的辦法了。', '收集15顆血琥珀，把它們交給費伍德森林的阿拉珊蒂絲·銀空。', '', '去找費伍德森林的阿拉珊蒂絲·銀空。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4102, 'zhTW', '淨化費伍德', '植物給與費伍德森林以生命，然而即使是它們也遭受了腐化和墮落的痛苦。我知道淨化它們的方法，但是我不會把這種方法告訴一個我不熟識或者不能信任的$r。向我證明你真的能幫助塞納里奧議會！$B$B這裡的北面有一個鐵木山洞，那裡的曲木元素已經無法挽救了。我要你幫我從它們身上取得樹汁，這些樹汁被稱作血琥珀。有了它們，我就可以研究拯救其它生命的辦法了。', '收集15顆血琥珀，把它們交給費伍德森林的梅貝絲·河風。', '', '去找費伍德森林的梅貝絲·河風。', '', '', '', '', 0);
