INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4119, 'zhTW', '被腐化的夜龍草', '', '', '', '去找費伍德森林的被腐化的夜龍草。', '', '', '', '', 0);
