INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4361, 'zhTW', '糟糕的訊息', '你必須把這個訊息帶給麥格尼陛下，$N。他會知道接下來該怎麼做的！', '回到鐵爐堡，把這個壞訊息帶給國王麥格尼·銅鬚。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4362, 'zhTW', '王國的命運', '看起來我的老對手——達格蘭·索瑞森——已經把我和鐵爐堡都置於他的控制之下了。$B$B你可能是我的最後希望了，$N。你必須拯救我親愛的女兒，茉艾拉！$B$B只有一種方法可以破除索瑞森施放在茉艾拉身上的咒語，那就是殺死他。$B$B還有，$N，不要傷害茉艾拉！記住，她正在被索瑞森控制著！她所做所說的一切都只是索瑞森邪惡咒語的結果！', '回到黑石深淵，從達格蘭·索瑞森大帝的魔掌中救出鐵爐堡公主茉艾拉·銅鬚。', '', '轉至黑石深淵，去找王座附近的公主茉艾拉·銅鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4363, 'zhTW', '語出驚人的公主', '索瑞森是個偉大的、值得尊重的矮人。你毀了我的一生，還有我肚子裡的孩子的一生！$B$B<你認為茉艾拉公主也許是受到了索瑞森的法術影響才變成這樣的。>$B$B回鐵爐堡去告訴我父親，鐵爐堡的下一任統治者將會是個黑鐵矮人。$B$B不管他同不同意，事情都會是這樣。', '回到鐵爐堡去，與國王麥格尼·銅鬚談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4381 AND `locale` = 'zhTW';
