INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4621, 'zhTW', '敬禮，艦隊司令！', '仔細聽著，海狗……藏寶海灣是讓我們血帆海盜處處受制的根本原因。如果你殺死艦隊指揮官卡拉·海角，我們就永遠不會再遇到藏寶海灣的戰艦了。如果你殺死大財主里維加茲，我們就永遠不用被他們的法律捆住手腳了。$B$B如果你想要成為一個有榮譽感的艦隊司令——沒錯，艦隊司令，那麼就按照我說的，去殺了他們兩個。現在去吧，$g小夥子:姑娘;，當你完成了任務之後就回到我這兒來。', '殺死藏寶海灣的艦隊指揮官卡拉·海角和大財主里維加茲，然後回到荊棘谷海邊的紅霧號上去，向艦隊指揮官菲爾拉倫覆命。', '', '去找荊棘谷的艦隊指揮官菲爾拉倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4641, 'zhTW', '起點', '你終於長大啦，$N……你可以以部落的名義參加戰鬥了，為酋長的榮譽而戰吧!嗯……<卡爾圖克打量了你一番。>你會很出色的。毫無疑問，你的目標是找到一條巨龍或是一個惡魔，然後赤手空拳地打敗它，但是從比較弱的對手開始可能是個比較明智的選擇。<卡爾圖克笑了起來。>去向高內克報告吧，他可以為你這樣的年輕$c指派一項適合你的任務。你可以在西邊的大獸穴中找到高內克。', '與高內克談一談。卡爾圖克在你的地圖上標出了他的位置，並告訴你高內克居住在西邊的大獸穴中。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4642 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4642, 'zhTW', '融合軟泥怪', '這裡有一些你從費伍德森林收集的軟泥怪樣本。把它拿到安戈洛環形山去，在那裡找到一個純淨的軟泥怪……最原始的品種就可以了。當你離它夠近的時候，倒出容器裡的軟泥怪，讓我們看看這兩種軟泥怪之間會發生什麼事情。$B$B當這個試驗完成之後，把剩下來的東西交給我。我會在鍊金房這裡等你。', '把一塊融合的軟泥怪樣本交給幽暗城的化學家弗雷。', '', '去幽暗城找鍊金房的化學家弗雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4661, 'zhTW', '墮落檢測 - 費伍德森林', '', '', '', '去找測試儀器。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4681, 'zhTW', '擱淺的巨獸', '黑海岸地區到處都是這種擱淺在海灘上的生物。它們大多出現在海岸線上，有一些甚至出現在海水中。我想讓你調查另一隻最近被發現的生物，據說它的屍體躺在奧伯丁西邊的海水中，在一艘沉船附近。把你發現的任何有助於研究的資訊都回饋給我。$B$B此外，在旅途中，你可能會發現其他擱淺的生物，你一定要把這些新發現也告訴我們!', '在奧伯丁西面海水中的海龜骨骸那裡取回海龜的殘骸，然後與奧伯丁的溫尼斯‧布萊葛談話。', '', '去黑海岸找奧伯丁的溫尼斯·布萊葛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4701 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4701, 'zhTW', '座狼之源', '你一定見過黑石獸人控制的座狼。$B$B有趣的是，不管我們消滅多少座狼，它們的數量總是有增無減。我的探子報告說座狼是在黑石塔裡面繁殖並馴養的，那裡是黑石獸人的要塞。你必須去黑石塔找到座狼的源頭。找到它……然後摧毀它。$B$B祝你好運，$n。願塞納留斯保佑你……', '到黑石塔去摧毀那裡的座狼源頭。當你離開的時候，赫林迪斯喊出了一個名字：哈雷肯。這個詞就是獸人語中“座狼”的意思。', '', '去燃燒平原摩根的崗哨找赫林迪斯·河角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4721, 'zhTW', '冬泉谷的梟獸', '從冬泉谷回來的信使報告說，冬泉谷南部區域有許多洞穴，而且這些洞穴周圍似乎都有梟獸出沒。如果說它們是在守護某種重要的東西，那麼我相信這就是我們要搜查的地區。$B$B這次的任務比上一個任務更富有挑戰性，$N。如果這些生物拼盡全力守護的東西被發現的話，它們會變得非常瘋狂而暴躁。', '費伍德森林的特魯爾·法貝恩要你去冬泉谷獵殺10頭狂暴梟獸。', '', '去費伍德森林找血毒崗哨的特魯爾·法貝恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4722, 'zhTW', '擱淺的海龜', '你找到一具海龜的屍體，它顯然是不久之前擱淺在黑海岸的，而且早已被住在周圍的灰霧魚人吃得一乾二淨了。不過，剩下的殘骸也足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去了。', '把海龜的殘骸交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4723, 'zhTW', '擱淺的海洋生物', '一頭巨型蛇頸龍的屍體─它比你預想的還要大很多─躺在薄霧海的海岸上。這個生物是怎麼到這裡的，你無從得知。成群的魚人正在分食它的屍體，那些魚人看起來是如此渺小，它們完全是依靠數量才將這頭巨獸搞定的。$B$B雖然屍體已經被吃掉了大半，但是剩下的也足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去了。', '把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4724, 'zhTW', '座狼的首領', '有些人說黑石獸人控制的座狼是由超自然的力量創造的。另一些人說其實它們並不是座狼，而是一種惡魔犬，是由一個墮落的深淵領主賜予獸人的。$B$B事實上，真相並沒有這樣誇張，但是同樣很嚇人。哈雷肯是一頭巨型母座狼。她的配偶？沒有人能活著回來描述他的樣子。$B$B打擊座狼的關鍵就在於殺掉哈雷肯……另外，$N，時刻小心你的背後。', '殺死血斧座狼的領袖，哈雷肯。', '', '去荒蕪之地找卡加斯的神射手賈拉瑪弗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4725 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4725, 'zhTW', '擱淺的海龜', '還有更多海龜的殘骸躺在海岸線上。這一具屍體的龜殼上還有個廢棄的車架。也許這個生物是被某種未知的力量趕到了海岸上，而不是像別的屍體那樣自己爬上海岸。強大的灰霧魚人正聚集在屍體附近並蠶食著它。$B$B你在車架中找到了一只有著奇怪標誌的箱子，也許奧伯丁的溫尼斯·布萊葛會對它有所瞭解。', '把有奇怪標記的箱子交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4726, 'zhTW', '小龍精華', '我幾個星期來都在研究燃燒平原的龍類，而且我終於有所突破了！我製作了一個裝置——我把它叫做“龍靈採集器900型”，它可以採集小龍的精華！$B$B好吧，至少我認為它可以實現這個功能。$B$B給你，拿著這個裝置，然後到燃燒平原上去採集小龍精華。首先使用它標記小龍，然後再殺死被標記的小龍，這樣你就可以採集小龍精華了。$B$B如果一切正常的話，那就太棒了！把你採集的東西帶回來供我進行研究！', '將龍靈採集器900型和8份小龍精華交給燃燒平原烈焰峰的丁奇·斯迪波爾。', '', '去燃燒平原找烈焰峰的丁奇·斯迪波爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4727, 'zhTW', '擱淺的海龜', '一隻海龜的骸骨躺在黑海岸北部的沙灘上。也許灰霧魚人沒有發現它的屍體，或者由於某些特殊的原因而沒有去碰它。不管怎麼樣，這具屍體上有足夠的海龜肉，你可以採集一些作為樣本，並把它送到奧伯丁的溫尼斯·布萊葛那裡，供月神殿進行研究。', '把海龜的殘骸交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4728, 'zhTW', '擱淺的海洋生物', '某種海中巨獸的屍體擱淺在了海灘上，一隻帶著輪子的木桶和其他一些雜七雜八的工具散佈在這頭巨獸旁邊，看來曾經有什麼人想要研究它。雖然這具屍體被魚人吃得差不多只剩骨頭了，但是剩下的殘骸也足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去。', '把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4729, 'zhTW', '基布雷爾的特殊寵物', '你也許想要知道我在這裡幹什麼。看看這些籠子！難道這還不夠明顯嗎？$B$B我是個動物愛好者，但是首先我是個商人。我為一些富翁和名流尋找珍貴的動物，然後把它們馴化成為溫順的寵物。$B$B也許你現在想要問：“我能為你做什麼呢，基布雷爾？”回答很簡單：拿著這隻籠子，幫我找些座狼小崽子。然後，我會為你馴服一頭座狼！', '到黑石塔去找到小血斧座狼。使用籠子來捕捉這些兇猛的小野獸，然後把籠中的小血斧座狼交給基布雷爾。', '', '去燃燒平原找烈焰峰的基布雷爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4730, 'zhTW', '擱淺的海洋生物', '這具已經被吃掉一半的屍體看來是一頭海洋巨獸。屍體躺在海岸上，一群比奧伯丁那裡的同類更加強大的魚人聚在周圍大嚼大咽，不過殘留的屍體應該足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去了。', '把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4731, 'zhTW', '擱淺的海龜', '又一具海龜的殘骸躺在海岸線上，龜殼上還有個廢棄的車架。也許這個生物是被某種未知的力量趕到了海岸上，而不是像別的屍體那樣自己爬上海岸。強大的灰霧魚人正聚集在屍體附近並蠶食著它。$B$B你在車架中找到了一只有著奇怪標誌的箱子，也許奧伯丁的溫尼斯·布萊葛會對它有所瞭解。', '把有奇怪標記的箱子交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4732 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4732, 'zhTW', '擱淺的海龜', '你找到一具海龜的屍體，它顯然是不久之前擱淺在黑海岸的，而且早已被住在周圍的灰霧魚人吃得一乾二淨了。不過，剩下的殘骸也足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去了。', '把海龜的殘骸交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4733 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4733, 'zhTW', '擱淺的海洋生物', '這具巨型蛇頸龍的屍體被沖到了礁石遍佈的暮光海岸上。它比你見過的任何魚龍都要龐大蛇頸龍都要龐大，不管它是從哪裡來的，這頭巨獸原本顯然不是生活在黑海岸的。$B$B雖然這具屍體已經支離破碎了，但是殘留的屍體也足夠讓你取樣並送到奧伯丁的溫尼斯·布萊葛那裡去。', '把海洋生物的骸骨交給奧伯丁的溫尼斯·布萊葛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4734 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4734, 'zhTW', '冷凍龍蛋', '$n，我一直都在忙著準備我的新裝置，龍蛋冷凍器！這個裝置可以對黑龍蛋噴出極冷的氣流……然後就把蛋凍住了！你能不能幫我測試一下？$B$B我聽說在黑石塔的高處，黑龍有個專門的地方來孵化它們的蛋。你可以在那裡對它進行測試，然後告訴我效果如何！$B$B不要擔心。被凍住的蛋是不會對你造成危害的。你所要擔心的只是那些沒有被凍住的而已！', '在孵化間對著某顆龍蛋使用龍蛋冷凍器初號機。', '測試龍蛋冷凍器初號機', '去燃燒平原找烈焰峰的丁奇·斯迪波爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4735 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4735, 'zhTW', '收集龍蛋', '$n，我終於做好採集真正龍蛋的準備了！給你，拿著這個電動採集模組，它可以萃取龍蛋精華並使你可以很方便地運輸龍蛋。回到孵化間去，用這個東西來收集龍蛋。$B$B不要忘了把它們先冰凍起來，不然的話，在你開始收集之前龍蛋就會孵化！$B$B當你收集到足夠的龍蛋之後，就把它們交給我！', '將電動採集模組和8顆收集到的龍蛋交給燃燒平原烈焰峰的丁奇·斯迪波爾。', '', '去燃燒平原找烈焰峰的丁奇·斯迪波爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4736 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4736, 'zhTW', '尋找梅納拉·沃倫德', '啊，你好，$N。你的訓練進行得很順利，所以我想你應該因自己的辛勤努力——以及你至今仍未被魔法的力量腐蝕——而獲得獎勵。$B$B如果你感興趣的話，就到棘齒城去找梅納拉·沃倫德。她在斯坦哈德的塔裡俯瞰著整個小鎮。$B$B她並不是很友好，$N，所以你可別想從她那裡得到什麼讚許。但是如果你努力的話，那她一定會好好照顧你的。', '與貧瘠之地的梅納拉·沃倫德談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4737 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4737, 'zhTW', '尋找梅納拉·沃倫德', '嗯，你還在努力變得更強。要我說，你遲早會墮落和沉溺於魔法，遲早會被你所追尋的力量所奴役。$B$B哎！你真是笨蛋！時間會證明我是正確的——沒有別的……只需要時間。$B$B看來並不是所有人都同意澤弗洛斯特的意見。梅納拉會創造一些可以讓你變得更加強大的東西，如果你感興趣的話，就去貧瘠之地的棘齒城吧。她在城外的一座塔中。', '與貧瘠之地的梅納拉·沃倫德談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4738 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4738, 'zhTW', '尋找梅納拉·沃倫德', '讓我們來澄清一件事情，$N：我覺得你並沒有準備好肩負這樣的責任。我認為一個新手在創造某件具有強大力量的物品的過程中起不到什麼作用，特別是一個沒有經過試煉的新手。$B$B但是這不是我能決定的，因為掌握著這種力量的人決定要賦予你強大的力量。$B$B如果你想要對此有更多瞭解的話，我建議你到棘齒城去找梅納拉·沃倫德，她就住在港口上面的塔裡。', '與貧瘠之地的梅納拉·沃倫德談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4739 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4739, 'zhTW', '尋找梅納拉·沃倫德', '$c！沒錯，叫的就是你！$B$B你沒有準備好所有必須的裝備，但你已經準備就緒了，你看起來自信十足。嗯，現在我看到你的自信了。$B$B如果你準備好了，那麼梅納拉·沃倫德會教你一些東西。她主要負責向年輕的學生傳授魔法的知識，也會給那些透過測試的學生贈送特殊的禮物。$B$B如果你感興趣的話，就到貧瘠之地的棘齒城去。她就在斯坦哈德的塔裡俯瞰全城。', '與貧瘠之地的梅納拉·沃倫德談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4740 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4740, 'zhTW', '懸賞:莫克迪普!', '注意!$B$B殺死名為「莫克迪普」的魚人就可獲得一筆賞金。這只邪惡的野獸至少殺死了一名哨兵，還涉嫌使至少兩條貨船在黑海岸沉沒!$B$B莫克迪普最後一次出現是在是奧伯丁以南的一個有草棚的魚人營地中，據信它保護著那裡的草棚。殺死該魚人後請到奧伯丁的哨兵戈琳達‧納希恩處領取賞金。$B$B奧伯丁鄉村委員會', '找到並殺死名為莫克迪普的魚人。它守護著位於奧伯丁南部海岸的魚人營地。向奧伯丁的哨兵戈琳達·納希恩報告莫克迪普的死訊。', '', '去黑海岸找奧伯丁的哨兵戈琳達·納希恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4741, 'zhTW', '冬泉谷的梟獸', '冬泉谷北部區域的梟獸更加兇殘，我們必須在那兒繼續採取主動。$B$B獵殺冬泉谷中的月光梟獸，並探察他們居住的區域。$B$B那裡是非常危險的地區，但是我知道你可以面對這樣的挑戰。當你殺死十三頭梟獸之後就回到我這裡來。', '費伍德森林的特魯爾·法貝恩要你去冬泉谷獵殺13頭月光梟獸。', '', '去費伍德森林找血毒崗哨的特魯爾·法貝恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4742 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4742, 'zhTW', '晉升徽印', '正如你所見的一樣，這個簡單的徽印有三個洞。每個洞都必須用代表領導力的寶石來填滿。最終，下層要塞的維姆薩拉克主宰會使用黑龍軍團的火焰來鑄造這個徽印。$B$B你一定要明白，下層要塞的三個將軍並不總是隨身帶著命令寶石，你必須在執行任務的時候務必保持謹慎。一定要完成這個任務！', '找到三塊命令寶石：燃棘寶鑽、尖石寶鑽和血斧寶鑽。把它們和原始晉升徽印一起交給維埃蘭。$B$B可能攜帶者三塊寶石的將軍是：燃棘氏族的指揮官沃恩、尖石氏族的歐莫克大王，以及血斧氏族的維姆薩拉克主宰。', '', '去找黑石塔的維埃蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4743 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4743, 'zhTW', '晉升徽印', '上層要塞之外的黑龍軍團很少有能力用它們的烈焰鑄造徽印。維姆薩拉克是其中的一員，但是他的意志是不可動搖的。$B$B到塵泥沼澤中的巨龍沼澤去，在那裡，你可以找到一條名叫艾博斯塔夫的上古老龍。你必須擊潰他的意志，$N。把他擊垮，然後在他虛弱的軀體上使用這顆寶珠。你有很短的一段時間來控制他的意志，然後用他所噴出的烈焰鑄造徽印。', '到塵泥沼澤中的巨龍沼澤去。找到上古老龍艾博斯塔夫，對他發起無情的攻擊，直到他的意志被摧毀。$B$B此時，你必須儘快將未鑄造的晉升徽印放在這條龍面前，並使用龍力寶珠控制他的軀體，強迫他將黑龍軍團的烈焰噴向未鑄造的晉升徽印！', '', '去找黑石塔的維埃蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4761, 'zhTW', '桑迪斯·織風', '桑迪斯·織風應該已經對你在熊怪的營地那裡所進行的偵察行動有所了結了。他是奧伯丁的長者，在那裡負責處理村中的日常事務。請把你對熊怪的偵察結果彙報給他。我相信，他對熊怪墮落的原因有自己的解釋。或許你能與他一起制定出恢復自然平衡的計畫!', '與奧伯丁的桑迪斯·織風談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4762, 'zhTW', '壁泉河', '壁泉河的河水正在逐漸變得污濁，這污濁的河水流入薄霧海，我擔心奧伯丁也會很快受到影響。我懷疑居住在上游區域的黑木熊怪是造成污染的原因，但是我覺得它們並不是一切問題的真正源頭。$B$B帶上這支試管，到北面的河口去，在第一個內陸瀑布的水潭中取出一份河水的樣本來─在你抬頭就可以看到一座橋的那個地方取水就可以了。拿到樣本後就回奧伯丁來找我。', '到奧伯丁的北面去，沿著壁泉河到達第一個瀑布處，從瀑布下的水潭中取出一份水樣。', '', '去黑海岸找奧伯丁的桑迪斯·織風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4763 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4763, 'zhTW', '黑木熊怪的墮落', '我們已經知道熊怪的墮落與薩特有很大的關係，他們使用魔法護符控制熊怪。如果我們要嘗試拯救熊怪的話，就必須擊敗引誘熊怪的薩特，取回他的護符!$B$B到我們的月井裡去，在碗裡盛滿水，然後從北面的熊怪營帳中取回一些食物。把水和食物混合並放在河水邊的營火旁，只要熊怪吃下食物，它就會得到淨化，稍等片刻，那個引誘熊怪的薩特就會出現...這時你就要出手殺掉它!', '在空的淨化碗裡盛滿奧伯丁月井的井水。', '', '去黑海岸找奧伯丁的桑迪斯·織風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4764 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4764, 'zhTW', '末日扣環', '黑石塔高處有一座大廳，它曾被稱為財富大廳。黑鐵矮人將他們的遺物、戰利品以及藝術品存放在那裡。$B$B那是很久以前的事兒了。據說大廳已經塌陷，現在用於……較為普通的用途。但是我相信裡面可能仍藏有一些古代矮人的遺物。$B$B其中一件是末日扣環，那上面鑲有罕見的寶石，據說任何矮人看到它都會感動得潸然淚下。$B$B那個扣環，$N，就是你的目標。', '將末日扣環交給燃燒平原的瑪亞拉·布萊特文。', '', '去燃燒平原摩根的崗哨找瑪亞拉·布萊特文。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4765 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4765, 'zhTW', '瑞治維爾的箱子', '我已經把末日扣環放入一隻箱子，便於運送到暴風城。$N，你幫了我的大忙，不過我能請你再幫我最後一個忙嗎？$B$B把這隻箱子交給雷明頓·瑞治維爾伯爵，你可以在暴風城裡找到他。我敢說他看到這東西之後會非常高興的。', '將瑞治維爾的箱子交給暴風城的雷明頓·瑞治維爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4766 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4766, 'zhTW', '瑪亞拉·布萊特文', '我的一個手下——瑪亞拉·布萊特文被派到燃燒平原去調查索瑞森廢墟。在那座被摧毀的城市裡，黑鐵矮人也許隱藏了什麼有價值的東西……能放在我的家族博物館裡的東西。$B$B瑪亞拉說她發現了一些東西，不過一時半會還拿不到它，那東西不在索瑞森，而是在黑石塔裡。$B$B我不清楚具體的細節，不過如果你感興趣的話，那就去燃燒平原跟瑪亞拉談談吧。', '與燃燒平原的瑪亞拉·布萊特文談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4767 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4767, 'zhTW', '馭風者', '我的任務是為我們的馭風者部隊招募更多的雙足翼龍。他們的數量在不斷增加，我也希望自己有一天可以成為一名馭風者。但是，我們無法訓練出足夠的雙足翼龍來滿足需求。也許你可以幫助我，$N。$B$B我想讓你到風巢去收集一些雙足翼龍的蛋，從這裡朝西北方向走，沿著峽谷的山壁到達一處直通風巢的斜坡。你要多加小心，雙足翼龍對自己的蛋具有強烈的保護意識，它們對入侵者非常不友善。', '將10顆風巢雙足翼龍的蛋交給亂風崗的艾魯。', '', '去找千針石林的艾魯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4768 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4768, 'zhTW', '黑暗石板', '很久以前就已經去世了的矮人烏赫爾德·黑石將他的著作寫在了一塊黑暗石板上。雖然他是一個技藝高超的鍊金師，但卻被同時代的人當成精神病患者，他的研究成果也從未得到重視。$B$B不過他卻把那些寶貴的知識刻在了石板上，而且我相信這塊石板就在黑石塔中，在一個以前被稱作倖運大廳的地方。我不知道現在那裡叫什麼，因為幾乎沒人可以進入黑石塔後再活著出來。$B$B不過，如果你願意勇敢地挑戰那裡的危險並帶回黑暗石板，我保證會給你豐厚的獎賞。', '將黑暗石板交給卡加斯的暗法師薇薇安·拉格雷。', '', '去荒蕪之地找卡加斯的暗法師薇薇安·拉格雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4769 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4769, 'zhTW', '薇薇安·拉格雷和黑暗石板', '薇薇安·拉格雷從荒蕪之地的卡加斯派人捎了信過來。她認為黑石塔中的一份遠古文稿可以對我們的研究有所幫助。為了證實這一點，她需要找人幫她從塔中取出這份文稿——這任務可不容易。$B$B如果你感興趣的話，就去跟卡加斯的薇薇安談一談吧。', '與卡加斯的暗法師薇薇安·拉格雷談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4770 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4770, 'zhTW', '回家', '請幫幫我，$c！我藏在這裡已經很久了，好多天都沒有看到過一張友好的面孔。我來這裡是準備研究雙足翼龍的，但是也許我靠得太近了。我在研究一隻雙足翼龍的時候遭到了攻擊，一直被追到這裡，而且迷了路。$B$B我要回白沙崗哨去！莫特加不知道我失蹤了，如果他知道我獨自進入風巢的話，一定會暴跳如雷的。$B$B白沙崗哨就在這裡的東面……請把我帶到那裡去！', '護送波卡·捷山走出風巢，然後和白沙崗哨的莫特加·火鬃談一談。', '保護波卡離開風巢', '去千針石林找白沙崗哨的莫特加·火鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4771 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4771, 'zhTW', '黎明先鋒', '我已經將黎明先鋒放到你拿來的那個裝龍蛋的容器裡了。你的任務是把它帶到通靈學院去。$B$B亡靈法師維克圖斯在那兒向一群天譴軍團的學者傳授知識……把黎明先鋒放在名叫觀察室的房間裡,它會自動攻擊房間裡面的亡靈，如果運氣好的話，它就能一舉毀掉他們！$B$B這樣一來，殺死維克圖斯就不是問題了。你明白了嗎？', '將黎明先鋒放在通靈學院的觀察室裡。打敗維克圖斯，然後回到貝蒂娜·比格辛克那裡去。', '放置黎明先鋒', '去東瘟疫之地找聖光之願禮拜堂的貝蒂娜·比格辛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4781, 'zhTW', '魔化金線血袍', '你的下一個任務和第一個任務同樣簡單，但是你必須去尋求他人的幫助。$B$B我的披風需要一些金線作為裝飾，但是要獲得金線並不容易，很少有人知道如何製作金線。幸運地是，有個忠於我們的地精知道金線的製作工藝，並且願意幫助那些有前途的$c。$B$B把一塊金錠交給藏寶海灣的希茲克·古斯提，他是個高明的裁縫，而且他會很樂意為你紡織金線的。金錠得由經驗豐富的礦工熔鍊出來，因此你必須尋求某個礦工的幫助。', '將一塊金錠交給荊棘谷的希茲克·古斯提。', '', '去荊棘谷找藏寶海灣的希茲克·古斯提。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4782, 'zhTW', '魔化金線血袍', '回到梅納拉那兒去吧，告訴她我需要一些時間來完成這活兒，但是我向她……和你保證，我肯定會完成它。等你弄到你所需的其它物品之後，我應該已經紡好金線了。到那時你就可以到我這兒來取走金線。$B$B祝你好運，$N。哦，對了，請幫我向斯坦哈德問好。那個老瘋子……他居然在棘齒城旁邊蓋了座塔……真是瘋了。', '回到貧瘠之地的梅納拉·虛無撕裂者那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4783, 'zhTW', '魔化金線血袍', '下一件必需的材料只有在石爪山西面的淒涼之地才能找到。$B$B在大災變之後，這片區域仍處於混亂之中。你的力量和智慧都將在此得到考驗——你將面對滿懷仇恨的生物，以及可怕的燃燒軍團。$B$B到淒涼之地的東北部去尋找怨怒薩特，取回它們的血。然後從瑪諾洛克集會所的次級地獄火身上弄到一塊次級地獄火石。$B$B我們將在製作披風的過程中用到這兩種東西。', '將10瓶怨怒薩特之血和1塊次級地獄火石交給貧瘠之地的梅納拉·虛無撕裂者。', '', '去找貧瘠之地的梅納拉·虛無撕裂者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4784, 'zhTW', '魔化金線血袍', '現在我只需要三件東西就可以完成你的披風了。$B$B第一件是希茲克正在紡織的優質金線，你要回一趟藏寶海灣，把金線拿回來。$B$B第二件是阿拉希高地的火元素身上的悶燒煤，這東西我要兩塊，如果我沒記錯的話，你可以在那個地區西部的索拉丁之牆附近找到它們。$B$B最後一件是由你自己製造的一塊靈魂碎片。$B$B當你收集到所有的物品之後，就回到這座塔裡來，我將為你完成披風。', '將一些優質金線、2塊悶燒煤和一塊靈魂碎片交給貧瘠之地的梅納拉·虛無撕裂者。', '', '去找貧瘠之地的梅納拉·虛無撕裂者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4785 AND `locale` = 'zhTW';
