INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4808, 'zhTW', '菲諾克', '我還有一件事要請你幫忙。$B$B我對你收集的那些精華進行了研究，結果表明冷凍並運輸龍蛋是有可能實現的。我想測試一下這個理論，但是首先我需要一些特別設計的零件。我的同事菲諾克可以製作我需要的東西。$B$B現在，請你把這封信交給菲諾克，上面寫著我所需要的東西的技術細節。你可以在冬泉谷的永望鎮裡找到菲諾克。', '把丁奇的信交給菲諾克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4809 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4809, 'zhTW', '冰風奇美拉角', '我有丁奇所需的大部分材料，但是唯獨缺少一種很重要的零件，那就是冰風奇美拉的角。冰風奇美拉的角是寒冷的源泉，但是隻有非常純粹而完整的角才能用！我需要很多角才能完成丁奇的訂單。$B$B給我弄些完整的冰風奇美拉角來，我會為丁奇準備一個包裹。', '將8支完整的冰風奇美拉角交給菲諾克。', '', '去冬泉谷找永望鎮的菲諾克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4810, 'zhTW', '返回丁奇身邊', '好，所有的東西都已經打包準備好，只等著送貨了！祝你旅途愉快，$n，別忘了告訴丁奇說她欠我一份人情！', '把菲諾克的包裹交給燃燒平原的丁奇·斯迪波爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4811 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4811, 'zhTW', '紅色水晶', '我們東邊的區域出現了越來越多的有攻擊性的梟獸。過去它們都是很溫和的─甚至可以說是神秘的動物。儘管仍然有人對它們非常尊敬，但出於對奧伯丁安全的考慮，我不得不保持更現實一些的觀點。$B$B據說這段時間以來，月光梟獸被黑海岸東部山脈上的一塊巨大的紅色水晶吸引，聚集在它的周圍。沒有人知道那塊水晶是什麼，也沒有人知道它是否真的存在。我想讓你去找到它的位置，並把你所發現的任何東西都報告給我。', '到奧伯丁的東邊去，沿著黑海岸東部邊界的山脈尋找一顆巨大的紅色水晶，然後向奧伯丁的哨兵戈琳達‧納希恩彙報你的發現。', '在黑海岸東部邊界的山上找到巨大的紅色水晶', '去黑海岸找奧伯丁的哨兵戈琳達·納希恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4812, 'zhTW', '清洗水晶', '用這支小瓶裝一些奧伯丁月井的水。它潛在的魔法能量可以幫我們弄清這塊水晶的成分，你必須把水倒在那塊水晶上，剩下的就不用你操心了。$B$B雖然我不覺得你會有什麼不測，但我仍然希望你多加小心。我們東邊就是費伍德森林，如果這塊水晶真的與那個地方有關聯，它就可能非常危險。', '在奧伯丁月井中把空水瓶裝滿，然後調查黑海岸東部山脈的紅水晶。', '', '去找黑海岸的神秘的紅色水晶。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4813 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4813, 'zhTW', '水晶中的碎骨', '月井的水讓嵌在水晶裡的東西顯現了出來，那是一些細小的骨頭碎片，還有半塊下頜骨。這塊下頜骨似乎是人類的，但是你沒辦法打開水晶，所以還不能確定這一點─即使是最強大的魔法也幾乎不可能打碎這塊水晶。現在看來，你只能去向奧伯丁的哨兵哨兵戈琳達·納希恩彙報這個發現了。', '向奧伯丁的哨兵哨兵戈琳達·納希恩報告你的發現。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4821, 'zhTW', '異型卵', '在千針石林流傳著一個有關異型卵的傳言。那些聲稱見到它的旅行者都沒能靠近它進行詳細的觀察。毒蛇守衛著那枚卵，就彷彿是在守衛它們自己的卵一樣。$B$B我想讓你去把那枚異型卵找出來交給我，以便讓我進行觀察。據說它在某條毒蛇的窩裡，但是沿著亂風崗南面與東北面的懸崖基部有好幾處蛇窩。', '把異型卵交給亂風崗的哈加爾·雷蹄。', '', '去千針石林找亂風崗的哈加爾·雷蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4822, 'zhTW', '草莓冰激凌', '冰激凌！啊天哪，求求你可不可以給我弄點冰激凌？我最喜歡草莓味了，而世界上最美味的草莓冰激凌就是提古勒和弗羅爾的草莓冰激凌了！這是世界上我最愛吃的冰激凌了。$B$B很久以前我在閃光平原的時候吃過，但是我聽說他們可能會在城裡出售了！求你了，可不可以給我弄點提古勒和弗羅爾的草莓冰激凌？！', '給守衛找一些草莓冰激凌。這位老兄好像比較喜歡提古勒和弗羅爾的草莓冰激凌。', '', '去找人類孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4841, 'zhTW', '清除半人馬', '$N，現在我委託你去消滅那些半人馬，讓他們感受我們的怒氣。進攻亂風崗北面的半人馬營地！讓怒火指引你的武器！', '殺掉12個加拉克斥候、10個加拉克爭鬥者和6個加拉克逐風者，然後向亂風崗的峭壁衛兵圖林·長角覆命。', '', '去千針石林找亂風崗的峭壁衛兵圖林·長角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4842, 'zhTW', '奇怪的源頭', '老實說，儘管冬泉谷沒有火山，但是我相信這些溫泉更為危險……$B$B嗯，你應該是想親自去看看。橫跨冬泉谷，然後朝這個地區的最南端前進。當週圍的空氣變得汙濁而悶熱，天色也開始變暗時，你就會發現溫泉的源頭。$B$B去看看吧，我想你回來時會帶著許多疑問的。', '根據多諾瓦·雪山的指示行動，然後回到她那裡報告。', '發現暗語峽谷', '去找冬泉谷的多諾瓦·雪山。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4861, 'zhTW', '被激怒的梟獸', '小$G夥子:姑娘，過來一下！我被一群嗜血如命的梟獸追趕，從我那個在冬泉谷南部的營帳裡逃到了這兒！我覺得這可能是我離梟獸要保護的某種東西太近的緣故。$B$B我剛剛設法安全脫身，但是跟我一起的那個同伴可就沒這麼幸運了……你願意到我的營地裡去一趟嗎？我真的需要那些補給物資，另外我還想取回昨天在挖掘場發現的護符。', '在冬泉谷的南部尋找加隆·石矛的被破壞的營帳，以及他的補給物資。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4862, 'zhTW', '蜘蛛卵', '信不信由你，有人願意出錢購買最兇猛的野獸！我將派比修進入黑石塔去收集一些尖塔蜘蛛的卵，但是我已經好幾周都沒有得到她的訊息了。也許你能幫幫我的忙？$B$B我跟你說啊，$N，到黑石塔去為我收集一些尖塔蜘蛛卵，把它們帶回來，我不僅會給你一筆現金，甚至還可以幫你馴服一隻小蜘蛛！', '到黑石塔去為基布雷爾收集15枚尖塔蜘蛛卵。$B$B聽說那些蜘蛛周圍有許多這樣的卵。', '', '去燃燒平原找烈焰峰的基布雷爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4863, 'zhTW', '被激怒的梟獸', '你朝四周看了看，沒找到加隆想要的東西。但是，你注意到先前找到的箱子已被打碎，似乎是被梟獸洗劫過……$B$B你向東看去，勉強辨認出那裡有一輛支離破碎的馬車。或許你能在那裡找到加隆的東西，最好去看一看。', '找到加隆·石矛的馬車。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4864 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4864, 'zhTW', '被激怒的梟獸', '翻了翻箱子裡的東西之後，你認為裡面的工具和其它一些物品可能對加隆仍然有用，但是你沒有發現他所說的護符。$B$B梟獸似乎居住在此地北面和東面的地區，因此你認為接下來最好到它們的聚居地去找一找。', '從雪地中拾起加隆的補給物資，然後尋找盜取加隆所說的護符的梟獸。$B$B將加隆的補給物資和藍色羽毛護符交給冬泉谷的加隆·石矛。', '', '去冬泉谷找墜星村的加隆·石矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4865 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4865, 'zhTW', '狂熱之蛇', '若不是親眼所見，我絕不會相信這是真的。復仇之靈已經來到了千針石林！$B$B<哈加爾擦了擦額頭上的汗。>$B$B$N，你必須儘快採取行動！現在就去找到莫特加·火鬃，他住在亂風崗西北部的白沙崗哨，他知道該怎麼做！', '向莫特加·火鬃彙報你的發現。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4866 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4866, 'zhTW', '蛛后的乳汁', '這也許是世界上效力最強的毒藥之一，$c！$B$B在我前往黑石塔的旅途中，無意中聽到過黑石獸人談起一種致命的毒藥。他們稱其為“蛛后的乳汁”，這個名字是根據黑石塔裡面那隻煙網蛛后的名字得來的。$B$B我需要一份在你體內流淌的“蛛后的乳汁”的樣本，毒囊是遠遠不夠的！讓她在你體內注入毒汁，然後回到我這兒來！$B$B然後……我就能得到乳汁了！$B$B<他揉搓著雙手，充滿期待。>', '你可以在黑石塔的中心地帶找到煙網蛛后。與她戰鬥，讓她在你體內注入毒汁。如果你有能力的話，就殺死她吧。當你中毒之後，回到狼狽不堪的約翰那兒，他會從你的身體裡抽取這些“蛛后的乳汁”。', '擠出毒液', '去燃燒平原的烈焰峰找狼狽不堪的約翰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4867, 'zhTW', '烏洛克', '啊！說起來就麻煩了！$B$B拿上這張便箋！把我的魔精弄過來！', '閱讀瓦羅什的卷軸。將瓦羅什的魔精交給他。', '', '去燃燒平原的黑石塔找瓦羅什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4881, 'zhTW', '暗殺計劃', '牛頭人卡納提·灰雲膽敢在千針石林建立營地，簡直是膽大妄為。我們必須殺了他，剷除他的營地，消滅他的所有同伴。我們將在升降梯西南方的小崗哨中會合，然後出發。', '將暗殺計劃通知給白沙崗哨的卡納提·灰雲。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4882 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4882, 'zhTW', '守護秘密', '你不清楚這條從你剛剛殺掉的那頭梟獸身上拿到的項鍊究竟有什麼重要的價值。它閃著奇特的光芒，時亮時暗。$B$B特魯爾·法貝恩也許對此更有了解，因為他對梟獸可謂瞭如指掌。也許你應該向他諮詢一下。', '把藍羽項鍊交給血毒崗哨的特魯爾·法貝恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4883, 'zhTW', '守護秘密', '我確實比你更瞭解冬泉谷的梟獸，但是我不太瞭解它們所使用的魔法。我知道誰可以告訴你有關這條項鍊的更多資訊。$B$B雷霆崖的納拉·蠻鬃是這方面的專家，去問問她吧。祝你好運，$N。', '把藍羽項鍊交給納拉·蠻鬃。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4901, 'zhTW', '祭壇守護者', '在山脊的頂部有一座伊露恩的祭壇。根據我所瞭解到的情況，我們必須點燃那一帶每座洞穴裡的火炬，然後我們就可以直接到祭壇那邊去了。$B$B我在凱斯利爾廢墟的石頭上發現了一些用符文書寫的咒語，我想這可以開啟通往祭壇的路。我需要你來幫忙點燃那些火炬，與此同時，我將誦讀咒語。$B$B如果我們成功了，你就可以把我們的發現彙報給艾瑞拉斯了！', '在蘭莎爾拉嘗試啟用伊露恩祭壇的過程中保護她。然後將你的發現報告給魯瑟蘭村的艾瑞拉斯·琥珀。', '揭開伊露恩祭壇的秘密', '去泰達希爾找魯瑟蘭村的艾瑞拉斯·琥珀。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4902 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4902, 'zhTW', '伊露恩的梟獸', '這可真叫人著迷！$B$B我一直在思考事情的真相……呃，你也應該跟我們分享這些知識！立即到大德魯伊範達爾·鹿盔那兒去，你可以在達納蘇斯的塞納里奧區裡找到他。把這裡所發生的一切都告訴他，就像你剛才跟我說的那樣。我敢說他肯定會對此很感興趣！$B$B這可是個重要的情報，$N！', '與達納蘇斯的大德魯伊範達爾·鹿盔談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4903, 'zhTW', '高圖斯的命令', '根據督軍高圖斯的命令，黑石塔的下列主要首領必須被消滅：$B$B對我們造成巨大威脅的歐莫克大王。$B$B殘忍無情的食人妖指揮官沃恩。$B$B維姆薩拉克主宰。$B$B如果你找到何重要的檔案，也必須一併上繳。$B$B成功則受人敬仰。$B$B失敗則被人遺忘。', '殺死歐莫克大王、指揮官沃恩和維姆薩拉克主宰。找到重要的黑石檔案，然後向卡加斯的督軍高圖斯彙報。', '', '去荒蕪之地找卡加斯的督軍高圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4904, 'zhTW', '終獲自由', '阿納克要和我結婚……但是在我拒絕了他的提議之後，他當晚就回來綁架了我。我的兄弟試圖阻止他，但是阿納克太強大了，他……他殺了我的兄弟，然後把我帶到了這裡。我可憐的兄弟……$B$B$N，你能護送我離開恐怖圖騰營地嗎？求你了……我要回到薩利亞身邊去！她一定非常思念我。', '護送拉克塔·風歌離開恐怖圖騰營地，然後與亂風崗的薩利亞談一談。', '護送拉克塔·風歌離開黑雲峰。', '去千針石林找亂風崗的薩利亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4905 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4905, 'zhTW', '<UNUSED>', '保護卡納提·灰雲，抵禦半人馬刺客的攻擊。', 'Defend Kanati Greycloud', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4906 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4906, 'zhTW', '更深重的墮落', '第二個薩特營地在費伍德森林的北部，他們的頭領是薩瓦里克。這個詭計多端的惡魔在不斷吸收費伍德森林中的那些墮落生物的力量。$B$B薩瓦瑟拉斯和他的手下只不過是一個宏大計劃的一部分，他們要培養出一座墮落的月井，然後用它為薩瓦里克提供力量。$B$B現在薩瓦瑟拉斯已經成為歷史了，那麼，$n，你的任務就是到北部去，打敗薩瓦里克。', '費伍德森林的艾瑞丹·藍風要你去殺掉8個碧火喚魔者、8個碧火背叛者、8個碧火欺詐者和薩瓦里克。任務完成之後回到艾瑞丹那裡覆命。', '', '去費伍德森林找翡翠聖地的艾瑞丹·藍風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4907 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4907, 'zhTW', '丁奇·斯迪波爾', '嗨，$N。你還記得丁奇·斯迪波爾嗎？嗯，她還記得你！她讓我留意你的行蹤，因為……她需要你的幫助。我認為這可能跟她對龍類的研究工作有關。$B$B你應該到燃燒平原的烈焰峰去找她談談。', '與丁奇·斯迪波爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4921, 'zhTW', '在戰鬥中失蹤', '我們在一個小小的 $R 營地裡作戰，然後就被沖散了─她獨自與三個刺背野豬人交戰。形勢越來越不妙，我引開了一些敵人，結果她又很快被新趕到的敵人包圍了。在狂怒之下，我衝向敵人，但是他們人多勢眾，很輕鬆地就把我打倒了。$B$B我醒來的時候，一位 $R 德魯伊正在照料我的傷口，他是在黃金之路上找到我的。$B$B $C ，請你幫我尋找我妻子的音訊。', '找到曼寇里克的妻子，然後回到十字路口找他。', '', '去找貧瘠之地的曼科裡克。', '找到曼克里克的妻子', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4941 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4941, 'zhTW', '伊崔格的智慧', '雷德還活著？$B$B不可能！$B$B據說雷德在數十年前就被殺掉了。$B$B去尋求伊崔格的建議吧，$N。沒有誰能比他更瞭解黑石氏族的情況了，如果這上面所寫的都是真的，那麼你應該通知伊崔格。誰都有復仇的權利。$B$B你可以在奧格瑪找到他。$B$B在你跟伊崔格談過話之後，便去與酋長交流一下，搞清楚他想要如何處理這個問題。', '和奧格瑪的伊崔格談一談。討論完畢後，諮詢索爾的意見。$B$B你回憶起曾在索爾的大廳中見過伊崔格。', '與伊崔格會面', '去找奧格瑪的索爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4961, 'zhTW', '奧拉赫寶珠的淨化', '啊，召喚師的寶珠——這肯定是汙染的來源。如果你準備使用寶珠的話，我們就必須先驅除裡面的惡魔，這對我來說很容易。$B$B不過你的任務就困難一些了。一旦我釋放出了惡魔，你就必須殺死他。$B$B而且你的動作必須要快，如果你太慢的話，他就會回到寶珠裡面去，那樣我們可就白費力氣了！$B$B準備好你最強大的法術，把藥水放在隨手可及的地方，如果你有朋友的話，也叫幾個來幫忙，這個任務真的不可掉以輕心。', '殺死寶珠之魔，然後與塔貝薩談一談。', '', '去塵泥沼澤找塔貝薩的農場的塔貝薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4962, 'zhTW', '惡魔犬的靈魂', '這麼說，你決定去捕獲惡魔犬的靈魂，這很好。$B$B帶著這顆紅寶石——你必須帶著它才能捕獲那種惡魔的靈魂。你應該很熟悉它的使用方法：當惡魔犬快要死亡的時候，就使用這顆寶石，它會替你完成剩下的工作。$B$B我建議你到淒涼之地去，在那裡收服一頭惡魔犬。$B$B你成功之後就把捕獲到的靈魂和紅寶石都交給梅納拉。', '帶上惡魔犬紅寶石到淒涼之地去，用它捕獲一隻惡魔犬的靈魂。成功之後，將惡魔犬紅寶石和被禁錮的惡魔犬靈魂交給貧瘠之地的梅納拉·虛無撕裂者。', '', '去貧瘠之地找棘齒城的梅納拉·虛無撕裂者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4963, 'zhTW', '地獄火的靈魂', '這麼說，你決定去捕獲地獄火的靈魂，這很好。$B$B帶著這顆綠寶石——你必須帶著它才能捕獲那種惡魔的靈魂。你應該很熟悉它的使用方法：當地獄火快要死亡的時候，就使用這顆寶石，它會替你完成剩下的工作。$B$B我建議你到淒涼之地去，在那裡收服一個地獄火。$B$B你成功之後就把捕獲到的靈魂和綠寶石都交給梅納拉。', '帶上地獄火綠寶石到淒涼之地去，用它捕獲一個地獄火的靈魂。成功之後，將地獄火綠寶石和被禁錮的地獄火靈魂交給貧瘠之地的梅納拉·沃倫德。', '', '去找貧瘠之地的梅納拉·沃倫德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4964, 'zhTW', '達奧拉赫寶珠', '我馬上就開始為你製作寶珠，並將新的惡魔禁錮在裡面。等寶珠完成之後，你可以選擇是把它製成法杖還是保留這顆寶珠。我始終認為術士應該選擇自己最喜歡的武器……所以這次我也沒理由不按老規矩辦。', '等待梅納拉·虛無撕裂者完成達奧拉赫寶珠，然後再與她談一談。', '等待梅納拉·虛無撕裂者完工', '去找貧瘠之地的梅納拉·虛無撕裂者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4965, 'zhTW', '奧拉赫寶珠', '嘖嘖，很高興看到你的力量在逐漸增長，$N。我敢打賭，你是準備去貧瘠之地找梅納拉·虛無撕裂者談話吧。如果你以前沒有跟她說過話，那麼讓我來告訴你吧，到現在為止，我還沒有遇到過比她更熟練的製造師呢——尤其是是製造寶珠。那寶珠甚至可以禁錮惡魔，不費吹灰之力就能讓惡魔按我們的意願行事。$B$B如果你感興趣的話，就到貧瘠之地棘齒城旁邊的塔裡去找她吧。', '與貧瘠之地的梅納拉·虛無撕裂者談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4966, 'zhTW', '保護卡納提·灰雲', '但是，半人馬的數量可能比我想像中的要多，我請求你，$n，與我一起反擊這些可恥的暗殺者吧。', '保護卡納提·灰雲免受半人馬的襲擊。', '保護卡納提·灰雲', '去千針石林找白沙崗哨的卡納提·灰雲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4967, 'zhTW', '奧拉赫寶珠', '你這個蠢貨，仍然被那些世俗的東西捆著手腳。沒錯，我蔑視你，看見你在我前面，我就不禁要大笑。你真可悲！$B$B但是我怎麼想並不重要，關鍵是那些願意與你打交道的人怎麼想！雖然我並不看重你，但那些掌握著力量的人認為你應得到更多。$B$B如果這就是你想要的，那麼你就到棘齒城邊的塔裡去找梅納拉·虛無撕裂者談談吧。我想你以前應該見過她。', '與貧瘠之地的梅納拉·虛無撕裂者談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4968, 'zhTW', '奧拉赫寶珠', '嗯，你居然大有長進……這真令人吃驚。我曾認為你肯定已經魔法的力量拉入了墮落的深淵，那麼，讓我們來繼續增強你的力量，如何？$B$B如果你想要看看自己到底有多大的本事，就到棘齒城外的那座塔裡去找梅納拉·虛無撕裂者，她會給你指引的。', '與貧瘠之地的梅納拉·虛無撕裂者談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4969, 'zhTW', '奧拉赫寶珠', '哈哈！年輕的$r$c，你做得很好。$B$B再過一段日子，即使是地獄火和恐懼魔王都會在你面前低頭的！$B$B但是在那之前，你還得依賴凡人鑄造的武器。$B$B看起來你已經準備好了。如果你願意的話，梅納拉·虛無撕裂者想跟你談談！她住在斯坦哈德的塔裡，就在棘齒城的邊上。去吧。', '與貧瘠之地的梅納拉·虛無撕裂者談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4970, 'zhTW', '霜刃豹的食物', '如果你想要證明自己，可以先從一項簡單但很重要的任務開始。$B$B從遍佈冬泉谷的奇美拉和裂齒熊身上收集它們的肉。把肉交給我，這樣我就可以用它來餵養那些正在接受訓練的霜刃豹了。', '收集5塊裂齒熊肉和5塊冰風奇美拉肉，把它們交給冬泉谷的雷沃·霜翼。', '', '去冬泉谷找霜刀石的雷沃·霜翼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4971, 'zhTW', '時間問題', '一股邪惡的力量─很可能是天譴軍團─出現在安多哈爾，擾亂了時間的流動!我可以嘗試維持現有的時間進程，並修正它所遭到的破壞，但是我必須在一個安靜的環境中才能做這些事情，這就需要你的幫助。$B$B時光寄生蟲─以改變的時間流為能源的食腐蟲─在安多哈爾的倉庫中大量繁殖，扭曲的藍色脈搏是它們身體唯一可見的部分。它們阻撓了我的施法過程，所以，$N，請你使用時光置換器幫我除掉這些寄生蟲。', '在安多哈爾的一處倉庫附近使用時光置換器，使時光寄生蟲現身。$B$B殺掉10隻時光寄生蟲，然後將時光置換器還給西瘟疫之地安多哈爾旅店的克羅米。', '', '去西瘟疫之地找安多哈爾廢墟的克羅米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4972 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4972, 'zhTW', '找回時間', '我需要借助你的能力進入這間房間以外的世界，$N。請允許我稍後向你解釋。$B$B你發現這間房間與安多哈爾其他地方的不同了吧。我的龍族軍團成員以不同的方式在不同的時間線上工作著。要修復安多哈爾的損傷，我要從一個不同的時間線著手，避免過分污染它。要繼續進行這項工作的話，我需要一些時間飾品，其中一個是在瘟疫襲擊安多哈爾時產生的。在建築物殘骸中尋找時間飾品，這些建築都是這個曾經繁華的城市的一部分。', '在安多哈爾城中四處散落的帶鎖箱裡找到5個安多哈爾懷錶，然後把它們交給西瘟疫之地安多哈爾旅店裡的克羅米。', '', '去西瘟疫之地找安多哈爾廢墟的克羅米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4973 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4973, 'zhTW', '找回時間', '要是你願意再幫我一次，我就不客氣啦。我想要更多的懷錶，你也許能在安多哈爾的廢墟中找到它們。它們能幫助我們在與擾亂時間線的任何邪惡力量抗衡時保持平衡。$B$B對於交換，我將給你另外一件裝備，將來你會發現它的大用處的。', '在安多哈爾城的廢墟裡找到5只安多哈爾懷錶，然後把它們交給西瘟疫之地安多哈爾旅店裡的克羅米。', '', '去西瘟疫之地找安多哈爾廢墟的克羅米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4974 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4974, 'zhTW', '為部落而戰！', '雷德受到黑龍的保護，因此他才如此狂妄囂張。$B$B你，$N，必須尋找一條穿過晉升大廳的道路，找到大酋長雷德·黑手並殺死他——為部落而戰！$B$B<索爾一拳打在王座上。>$B$B高舉著他的頭顱凱旋而歸吧，將頭顱呈獻給你的酋長。去吧，你將成為部落的英雄！', '去黑石塔殺死大酋長雷德·黑手，帶著他的頭顱返回奧格瑪。', '', '去找奧格瑪的索爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4975 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4975, 'zhTW', '諾奧拉赫寶珠', '我馬上就開始為你製作寶珠，並將新的惡魔禁錮在裡面。等寶珠完成之後，你可以選擇是把它製成法杖還是保留這顆寶珠。我始終認為術士應該選擇自己最喜歡的武器……所以這次我也沒理由不按老規矩辦。', '等待梅納拉·沃倫德完成諾奧拉赫寶珠，然後再與她談一談。', '等待梅納拉·沃倫德完工', '去找貧瘠之地的梅納拉·沃倫德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4976, 'zhTW', '歸還淨化過的寶珠', '把淨化過的寶珠交給棘齒城的梅納拉，$N。代我向她問好，一路小心。我真的希望你能應付得了越來越強大的誘惑和腐蝕的力量。$B$B祝你好運。', '將淨化過的地獄火寶珠交給貧瘠之地的梅納拉·沃倫德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4981, 'zhTW', '狡猾的比修', '決不要相信地精。這是我多年來總結的經驗，$N。$B$B她的名字是比修——我們最機敏的偵察員之一。我發現她在為燃燒平原外面的一個名叫基布雷爾的可疑的寵物商工作，而且非常賣力。更糟糕的是，她在使用部落的資金來做這些事情。$B$B把她給我帶回來，要活的。$B$B她已經鑽到黑石塔裡面去了。去找到她，並把她帶回來。$B$B還有，$N，不要讓她的甜言蜜語欺騙了你。', '到黑石塔去查明比修的下落。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4982, 'zhTW', '比修的裝置', '在夜裡，當這個地方守備鬆懈的時候，我就會在城裡偷偷地四處走動，記下我所看到的可能會對K.E.F.有戰略價值的任何東西。$B$B然而昨晚事情變得非常糟糕，我被一張網絆到並觸動了一個機關，我馬上把我的偵察裝置藏起來去找藏身之所了！不幸的是，我沒法取回那套裝置。他們已經把巡邏兵的數量增加了兩三倍！所有的情報都丟失了。$B$B把我的東西拿回來，我就可以返回K.E.F.去了。', '找到比修的裝置並把它們還給她。你記得她說過她把裝置藏在城市的最底層。', '', '去找黑石塔的比修。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4983, 'zhTW', '比修的偵察報告', '把這份報告交給雷克斯洛特。它可以讓我恢復好名聲，並且肯定會讓K.E.F.在對付這些獸人時佔據戰略上的優勢。$B$B跟你一起回去？我有太多的工作要做。快走吧，他們急需這些報告！', '把比修的偵查報告交給卡加斯的雷克斯洛特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4984, 'zhTW', '大自然的苦楚', '儘管我不可能以一己之力反抗天譴軍團，但我仍然來到了這裡，盡力治癒他們對大自然造成的傷害。這片土地上的生靈遭受著瘟疫所帶來的災難，這瘟疫使大地窒息。我想請你把我在這裡未完成的工作繼續下去。$B$B對那些正在忍受折磨的動物們來說，除了仁慈地解放它們，沒有什麼其他的解決辦法了。把附近生病的狼找出來，殺死它們。我請求你，$N，結束它們的痛苦吧……這樣做也會令我得到安寧。', '消滅8隻生病的狼，然後去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。', '', '去西瘟疫之地找達隆米爾湖的穆格雷斯·深水。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4985, 'zhTW', '大自然的苦楚', '在我們所在地的東方，東瘟疫之地邊界的附近，從前驕傲而威嚴的灰熊在鄉村遊走。天譴軍團所釋放的瘟疫也已將這些動物趨散。它們在鄉村遊蕩，飽受了肌肉僵硬和皮肉腐爛之苦。$B$B我請求你也去結束它們的痛苦。治療它們苦難的唯一方法就是讓其痛快的死去，這必須由你親手來完成。', '消滅8只生病的灰熊，然後去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。', '', '去西瘟疫之地找達隆米爾湖的穆格雷斯·深水。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4986, 'zhTW', '雕紋橡木樹枝', '牛頭人德魯伊那毫無生氣的手緊緊地抓著一根看上去極為結實的橡木枝，樹皮上刻著一些德魯伊教派的文字。$B$B當你握著這根樹枝時，你發現原本應該冰冷的樹枝摸上去卻非常溫暖。巨樹泰達希爾的畫面清晰地浮現在你的腦海裡，然後是達納蘇斯。“塞納里奧議會”這幾個字也湧到了你的唇邊。你現在很清楚要把這根樹枝帶到哪兒去了。', '根據雕紋橡木樹枝上面所附加的魔法，這個牛頭人德魯伊本來準備把它交給達納蘇斯的塞納里奧議會。看來你應該到那裡去找一個德魯伊，並尋求他的幫助。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 4987 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (4987, 'zhTW', '雕紋橡木樹枝', '牛頭人德魯伊那毫無生氣的手中緊緊地抓著一根看起來極為健康的橡木樹枝，樹皮上刻著一些德魯伊的自然雕紋。$B$B當你握著這根樹枝時，你發現原本應該冰冷的樹枝摸上去卻非常溫暖。莫高雷地區的雷霆崖畫面清晰地浮現在你的腦海裡，尤其是長者高地的景象。「塞納里奧議會」這幾個字從你的嘴中同時說了出來。顯然這根樹枝早就該被安排好帶到哪裡了。', '根據這枝雕紋橡木樹枝所附加的魔法，這個牛頭人德魯伊本來準備把它交給雷霆崖的塞納里奧議會。到那裡去尋求某個德魯伊的幫助吧。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5001, 'zhTW', '比修的裝置', '通常我是不會與$r打交道的，但是現在看起來，我前有困境後有巨魔，進退兩難。你知道，我在此地的任務對部落來說有極其重要的意義。然而我得到的情報對聯盟來說也是有益的。請相信我，我不是聯盟的支持者，但黑石氏族不只有一群獸人。$B$B如果你幫我找到我的東西，我就會給你一些對你們也有用的情報。$B$B同意嗎？', '找到比修的裝置並把它們還給她。祝你好運！', '', '去找黑石塔的比修。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5002, 'zhTW', '給麥克斯韋爾的訊息', '我是個說話算話的小地精。現在仔細聽著：$B$B這些獸人的主要用途是黑龍的苦工和炮灰！$B$B他們真正的頭領不是別人，正是奈法利安，死亡之翼的兒子。我還在這一帶偵察到了一些奈法利安的下屬所在的位置。$B$B把這張地圖交給燃燒平原的麥克斯韋爾元帥，地圖上面標記著這些魔王的位置，很容易就可以辨認出來。', '到燃燒平原去，把比修的情報交給麥克斯韋爾元帥。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5021, 'zhTW', '遲到總比不到好', '「在我被困在這裡之前，這個包裹一定得送……送出去!」一個驚恐的女人哭聲在這所房子裡穿梭回蕩。你看到一個女人的亡魂瑟縮在樓上的角落裡，看起來她並不完全熟悉周圍的環境，她只是隱約地感覺到了你的存在。「你是來幫我送包裹的嗎?趁事情還沒有變得更加糟糕……求你了，幫幫我!我本來是要騎馬離開這裡的，包裹應該還在我的馬旁邊……是不是已經太遲了?」', '這個女人的鬼魂告訴你她要送出一個包裹。她說那個包裹就在她的馬旁邊。至於馬在哪裡或者包裹要送到哪裡去，她卻根本沒有說。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5022, 'zhTW', '遲到總比不到好', '你撿起這個包裹，擦掉積在上面一層薄薄的塵土和泥垢。這個包裹上面草草地寫著要寄給暴風城裡一個名叫艾瑪·費爾斯通的人，而包裹的遞送日期已經是四年之前了。$B$B儘管你不清楚艾瑪·費爾斯通是否還活著，但暴風城的市政廳裡應該還保留著城市居民的記錄，你應該去找暴風城人口普查處的皇家代理人幫忙。', '向暴風城的皇家代理人確認艾瑪·費爾斯通的下落。通常在市政廳裡都有一個人口普查官。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5023, 'zhTW', '遲到總比不到好', '你撿起那隻包裹，然後擦掉了積落在上面的一層薄薄的塵土和泥垢。這隻包裹上面草草地寫著要投寄給羅德隆的一個名叫傑雷米亞·費爾斯通的人，而包裹的遞送日期已經是四年之前了。$B$B儘管你並不清楚傑雷米亞·費爾斯通是否還活著，但幽暗城——也就是以前的羅德隆——應該還保留有城市居民的記錄，你應該去找幽暗城人口普查處的皇家監督者幫忙。', '與幽暗城的皇家監督者巴哈烏斯協商，查詢傑雷米亞·費爾斯通的下落。通常在公會註冊處附近會有一個人口普查官。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5041, 'zhTW', '十字路口的補給品', '那次被野豬人剪了徑的商隊運載著我們急需的物資。$B$B就你對鋼鬃野豬人的作戰記錄來說，你真的是勇氣十足，我希望你再接再厲，不過這一次，我想知道我是否能請你睜大眼睛，幫我們尋找一些丟失的供給物資。你可以在野豬人的營地裡四下找找，那些傢伙做了那一票之後明顯胖了許多。$B$B十字路口的居民欠你的人情。', '找到十字路口的補給箱，把它還給貧瘠之地的索克。', '', '去找貧瘠之地的索克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5042 AND `locale` = 'zhTW';
