INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5210, 'zhTW', '卡林弟兄', '借助我的魔法，《達隆郡的歷史》被增補了，現在它所記述的歷史已經包括戰爭之後的事情了。新增的章節裡有一部分講述了另一個雷德帕斯家族成員的下落，他在約瑟夫叛變後僥倖活了下來。卡林·雷德帕斯在東瘟疫之地的聖光之願禮拜堂裡。$B$B拿著這本書去找他吧。', '將《達隆鎮全史》交給東瘟疫之地的卡林·雷德帕斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5211 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5211, 'zhTW', '達隆郡的防衛者', '許多防衛者在達隆郡的戰役中倒下了。而他們之中許多人又成了天譴軍團的爪牙!找到這些可憐的靈魂並結束他們的痛苦!$B$B去獵殺吃人的食屍鬼、語無倫次的食屍鬼和生病的撕掠者。他們以前都是達隆郡的善良居民，現在毀滅他們的形體將會使他們的靈魂得到自由。$B$B你可以在病木林、考林的十字路口，還有東瘟疫之地的其他天譴軍團的據點裡找到他們。', '釋放15個達隆郡居民的靈魂，然後返回卡林·雷德帕斯身邊。', '', '去東瘟疫之地找聖光之願禮拜堂的卡林·雷德帕斯。', '解放達隆郡的靈魂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5212, 'zhTW', '血肉不會撒謊', '被遺忘者的藥劑師並不是這個世界上唯一接受過科學教育的學者。$B$B我已經研究這場瘟疫好多年了，$c。我們以前曾認為瘟疫的力量正在衰減，但是我在瘟疫之地的研究成果卻令人吃驚。瘟疫的力量似乎仍在增長！$B$B我需要進行更多的試驗！最有潛質的瘟疫源泉就是那些最近感染瘟疫的軀體。到斯坦索姆去給我帶回一些標本來，$N。', '從斯坦索姆找回10個瘟疫肉塊，並把它們交給貝蒂娜·比格辛克。你覺得斯坦索姆中的生靈都不大可能長著肉……', '', '去東瘟疫之地找聖光之願禮拜堂的貝蒂娜·比格辛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5213 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5213, 'zhTW', '活躍的探子', '你必須更加深入斯坦索姆，$N。$B$B穿過第一道門之後，你就可以看到巨大的通靈塔。我們知道天譴軍團正在源源不斷地從這些建築物中汲取力量。搜尋通靈塔，並把你找到的任何有價值的情報帶回來。', '到斯坦索姆去探索那裡的通靈塔。找到新的天譴軍團檔案，把它交給貝蒂娜·比格辛克。', '', '去東瘟疫之地找聖光之願禮拜堂的貝蒂娜·比格辛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5214 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5214, 'zhTW', '弗拉斯·希亞比', '可怕的事情……弗拉斯。你知道，城鎮被毀滅了，而弗拉斯不想離開他那珍貴的貨物。我還記得他說的最後一句話：“我要在他們該死的髒手碰到我的菸葉之前把所有東西都燒光！”$B$B我可能比較貪財，但我不是傻瓜，於是我離開了弗拉斯和他的商店。我覺得他應該是已經被燒死了，但是如果……萬一他的名牌菸草還有一部分沒有被燒燬……$B$B你怎麼說，$N？去幫煙鬼找包煙吧？', '找到弗拉斯·希亞比在斯坦索姆的菸草店，並從中找回一盒希亞比的菸草，把它交給煙鬼拉魯恩。', '', '去東瘟疫之地找聖光之願禮拜堂的煙鬼拉魯恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5215 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5215, 'zhTW', '瘟疫之鍋', '在羅德隆的土地上有八口瘟疫之鍋，其中四口在西瘟疫之地，另外四口在東瘟疫之地。這些瘟疫之鍋不斷向空中噴出毒氣，將天譴軍團的瘟疫傳播到整個大地。科爾蘇加德的力量太強大了，我們無法關掉這些瘟疫之鍋，但是我想我們可能有辦法利用它們。我的助手，高階牧師瑪多妮爾負責此項任務的執行，你去找她談談吧。', '與西瘟疫之地冰風崗的高階牧師瑪多妮爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5216 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5216, 'zhTW', '目標:費爾斯通農場', '在西瘟疫之地的四口瘟疫之鍋中，費爾斯通農場裡的那一口可能是最容易進入的了。天譴軍團在那邊駐紮的都是新兵，儘管他們也不是輕易可以擊敗的對手，但相對來說畢竟容易一些。$B$B到費爾斯通農場去，它就在這裡的正東方，安多哈爾的西北方，並與那裡的護鍋領主交戰。它身上有一把可以打開瘟疫之鍋的鑰匙。當你開啟那口鍋之後，用這個瓶子裝滿鍋裡的毒藥樣品，我們要對它進行研究以製造出一種解藥。', '到西瘟疫之地的費爾斯通農場去，找到並擊敗那裡的護鍋領主，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶費爾斯通農場的空瓶來採集瘟疫之鍋中的毒藥樣本。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5217 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5217, 'zhTW', '返回冰風營地', '你將瓶子裡裝滿了瘟疫之鍋中的毒液，製成了一份合適的樣品。$B$B現在你應該帶著毒藥回到冰風營地的高階牧師瑪多妮爾那裡去了。', '把費爾斯通農場的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5218, 'zhTW', '費爾斯通農場的瘟疫之鍋', '', '', '', '去找西瘟疫之地的天災之鍋。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5219, 'zhTW', '目標:達爾松之淚', '有一口瘟疫之鍋被放置在一座早已廢棄的農場上，現在這裡被稱為達爾松之淚。不過現在我們沒時間掉眼淚，$c。我們必須打開這口瘟疫之鍋!$B$B到安多哈爾正北方的達爾松之淚去，消滅那裡的護鍋領主。像上次一樣，護鍋領主身上應該有一把可以打開瘟疫之鍋的鑰匙。用這個瓶子從鍋裡裝一份樣品拿回來，每口鍋所使用的毒素配方都是截然不同的。', '到西瘟疫之地的達爾松之淚去，找到並擊敗那裡的護鍋領主，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶達爾松之淚的空瓶來採集瘟疫之鍋中的毒藥樣本。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5220 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5220, 'zhTW', '返回冰風營地', '你將瓶子裡裝滿了瘟疫之鍋中的毒液，製成了一份合適的樣品。$B$B現在你應該帶著毒藥回到冰風營地的高階牧師瑪多妮爾那裡去了。', '把達爾松之淚的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5221, 'zhTW', '達爾松之淚的瘟疫之鍋', '', '', '', '去找西瘟疫之地的天災之鍋。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5222, 'zhTW', '目標:嚎哭鬼屋', '已經有兩口瘟疫之鍋被成功打開了，雖然並不確定你能否繼續前進，但我們仍然想要打開剩下的兩口瘟疫之鍋。這可以讓我們的解藥發揮更大的效果!$B$B這次你的目標是嚎哭鬼屋的瘟疫之鍋。那個地方在安多哈爾正東邊，相對來說比較靠近被毀壞的城牆。和以前一樣，消滅那裡的護鍋領主，拿到它的鑰匙。用這只瓶子從鍋裡取得樣品。$B$B祝一切順利，$N!', '到西瘟疫之地的嚎哭鬼屋去，找到並擊敗那裡的護鍋領主，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶嚎哭鬼屋的空瓶來採集瘟疫之鍋中的毒藥樣本。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5223, 'zhTW', '返回冰風營地', '你將瓶子裡裝滿了瘟疫之鍋中的毒液，製成了一份合適的樣品。$B$B現在你應該帶著毒藥回到冰風營地的高階牧師瑪多妮爾那裡去了。', '把嚎哭鬼屋的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5224, 'zhTW', '嚎哭鬼屋的瘟疫之鍋', '', '', '', '去西瘟疫之地找天災之鍋。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5225 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5225, 'zhTW', '目標:蓋羅恩農場', '最後的一口瘟疫之鍋在一個被稱作蓋羅恩農場的地方，由天譴軍團中較為強大的爪牙守衛著─那裡的鬼魂和怨靈尤其危險。你可不能掉以輕心，$N。$B$B蓋羅恩農場在這裡的東北方向，靠近東瘟疫之地的邊界。和以前一樣，消滅那裡的護鍋領主以獲取他的鑰匙。拿著這個空樣品瓶，把它裝滿給我拿回來。願聖光護佑你平安完成這次危險的任務，$c。', '到西瘟疫之地的蓋羅恩農場去，找到並擊敗那裡的護鍋領主，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶蓋羅恩農場的空瓶來採集瘟疫之鍋中的毒藥樣本。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5226 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5226, 'zhTW', '返回冰風營地', '你將瓶子裡裝滿了瘟疫之鍋中的毒液，製成了一份合適的樣品。$B$B現在你應該帶著毒藥回到冰風營地的高階牧師瑪多妮爾那裡去了。', '把蓋羅恩農場的樣本瓶交給西瘟疫之地冰風營地的高階牧師瑪多妮爾。', '', '', '', '', '', '', 0);
