INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5228, 'zhTW', '瘟疫之鍋', '在羅德隆的土地上有八口瘟疫之鍋，其中四口在西瘟疫之地，另外四口在東瘟疫之地。這些瘟疫之鍋不斷向空中噴出毒氣，將天譴軍團的瘟疫傳播到整個大地。$B$B克爾蘇加德的力量太強大了，我們無法關掉這些瘟疫之鍋，但是我想我們可能有辦法利用它們。我的助手，暗影牧師範蒂絲負責此項任務的執行，你去找她談談吧。', '與西瘟疫之地亡靈壁壘的暗影牧師範蒂絲談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5229, 'zhTW', '目標：費爾斯通農場', '在西瘟疫之地的四口瘟疫之鍋中，費爾斯通農場裡的那一口可能是最容易進入的了。天譴軍團在那邊駐紮的都是新兵，儘管他們也不是輕易可以擊敗的對手，但相對來說畢竟容易一些。$B$B到費爾斯通農場去，它就在這裡的正東方，安多哈爾的西北方，並與那裡的護鍋領主交戰。它身上有一把可以開啟瘟疫之鍋的鑰匙。當你開啟那口鍋之後，用這個瓶子裝滿鍋裡的毒藥樣品，我們要對它進行研究以製造出一種解藥。', '到西瘟疫之地的費爾斯通農場去，找到並擊敗那裡的護鍋領主，用它的鑰匙開啟瘟疫之鍋。你必須隨身攜帶費爾斯通農場的空瓶來採集瘟疫之鍋中的毒藥樣本。', '', '去西瘟疫之地的費爾斯通農場解鎖天災之鍋。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5230, 'zhTW', '返回亡靈壁壘', '你往瓶子裡裝滿了瘟疫之鍋中的毒液，製成了一份合適的樣品。$B$B現在你應該帶著毒藥回到亡靈壁壘的暗影牧師範蒂絲那裡去了。', '把費爾斯通農場的樣本瓶交給西瘟疫之地亡靈壁壘的暗影牧師範蒂絲。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5231 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5231, 'zhTW', '目標：達爾松之淚', '有一口瘟疫之鍋被放置在一座早已廢棄的農場上，現在這裡被稱為達爾松之淚。不過現在我們沒時間掉眼淚，$c。我們必須開啟這口瘟疫之鍋！$B$B到安多哈爾正北方的達爾松之淚去，消滅那裡的護鍋領主。像上次一樣，護鍋領主身上應該有一把可以開啟瘟疫之鍋的鑰匙。用這個瓶子從鍋裡裝一份樣品拿回來，每口鍋所使用的毒素配方都是截然不同的。', '到西瘟疫之地的達爾松之淚去，找到並擊敗那裡的護鍋領主，用它的鑰匙開啟瘟疫之鍋。你必須隨身攜帶達爾松之淚的空瓶來採集瘟疫之鍋中的毒藥樣本。', '', '去西瘟疫之地解鎖天災之鍋。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5232, 'zhTW', '返回亡靈壁壘', '你往瓶子裡裝滿了瘟疫之鍋中的毒液，製成了一份合適的樣品。$B$B現在你應該帶著毒藥回到亡靈壁壘的暗影牧師範蒂絲那裡去了。', '把裝滿的達爾松眼淚之瓶交給西瘟疫之地亡靈壁壘的暗影牧師範蒂絲。', '', '', '', '', '', '', 0);
