INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5421, 'zhTW', '坐享其成', '', '', '', '去找淒涼之地的吉納澤林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5441, 'zhTW', '懶惰的苦工', '該死的苦工!我叫他們在山谷裡伐木，但他們總是見縫插針地打盹!我需要找個人幫我去叫醒他們。$B$B你看起來挺適合這差事的。給你，拿著這根棍子，看到偷懶睡覺的苦工就打醒他。只要狠狠地敲他們一下就能讓他們乖乖回去工作了!別忘了把棍子還給我。$B$B這些該死的懶漢……', '在懶惰的苦工睡覺時，用工頭的木棒敲他們。敲醒5個苦工，然後把工頭的木棒還給試煉谷的工頭塔茲利爾。', '', '去找杜洛塔的工頭塔茲利爾。', '喚醒苦工', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5461, 'zhTW', '萊斯·霜語', '亡靈對於生命的恐懼就像我們對於死亡的恐懼一樣，所以一個亡靈將其生前用過的東西全都毀掉是很正常的事情。$B$B不幸的是，要想建立一件能破除萊斯·霜語不死之身的神器，我們就必須找到他生前擁有的一樣東西。$B$B你必須到早已被廢棄的激流堡去，那裡是萊斯·霜語的家，到那裡去尋找這樣一件東西。祝你好運，$N。', '到阿拉希高地的激流堡遺蹟裡面尋找巫妖生前的遺物。如果你能找到這樣的東西，就把它交給馬杜克鎮長。', '', '去西瘟疫之地找達隆米爾湖的馬杜克鎮長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5462 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5462, 'zhTW', '亡靈萊斯·霜語', '你必須把這件遺物放在被玷汙的土地上。$B$B傳說弗斯特·維斯帕爾是在斯坦索姆城裡屈服於巫妖王的。在那片血跡斑斑的土地上，他心甘情願地獻出了自己的生命和靈魂，變成了亡靈的一員。$B$B你必須找到那片土地。$B$B我知道有一個天譴軍團的背叛者，他被女妖之王解救了出來，但是他現在效力於銀色黎明。去找到他，他的名字是可敬的萊尼德·巴薩羅梅。他應該對這件事情更瞭解一些，到聖光之願禮拜堂去找他吧，$N。', '到東瘟疫之地的聖光之願禮拜堂去找到可敬的萊尼德·巴薩羅梅，給他看看巫妖生前的遺物，並告訴他你收集到的情報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5463 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5463, 'zhTW', '米奈希爾的禮物', '我目睹了那個人類，萊斯·霜語，把他的靈魂獻給了巫妖王。他將匕首插入自己的喉嚨，然後微笑著橫切了下去。他的身體倒在了五芒星陣裡，巫妖王站在那個死掉的法師旁邊，只用了一個簡單的動作，巫妖萊斯·霜語就誕生了。$B$B<萊尼德看著地板，然後抬起頭來看著你。>$B$B是的，$R，我記起來了。你要找的地方有個名字——米奈希爾的禮物：那塊地方曾被巫妖王賜福，那裡是天譴軍團的聖地。', '到斯坦索姆城裡去找到米奈希爾的禮物，把巫妖生前的遺物放在那塊邪惡的土地上。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5464 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5464, 'zhTW', '米奈希爾的禮物', '巫妖的靈魂鑽入了代表它前身的物品之中，這件物品很快變成了一本禁錮著巫妖靈魂的遺物。你把它拿了起來，放入包中。', '把禁錮靈魂的遺物交給東瘟疫之地的萊尼德·巴薩羅梅。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5465 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5465, 'zhTW', '禁錮靈魂的遺物', '把這件遺物交給馬杜克吧，$N。他會告你該怎麼使用它的。', '回到凱爾達隆的馬杜克鎮長那裡，把禁錮靈魂的遺物交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5466 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5466, 'zhTW', '巫妖萊斯·霜語', '你還有最後一個任務必須去完成，$N——到巫妖萊斯·霜語的巢穴中去擊敗他。$B$B使用禁錮靈魂的遺物的力量來對付他——千萬不要心存任何憐憫，否則倒下的就會是你！不要因為痛苦而屈服！$B$B當儀式完成之後，他就不再是一個不死之身了。那時你必須儘快殺死他，把他的頭顱給我拿回來。', '在通靈學院裡找到萊斯·霜語。當你找到他之後，使用禁錮靈魂的遺物破除其亡靈的外殼。如果你成功地破除了他的不死之身，就殺掉他並拿到萊斯·霜語的頭顱。把那個頭顱交給馬杜克鎮長。', '', '去西瘟疫之地找達隆米爾湖的馬杜克鎮長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5481, 'zhTW', '葛爾多的任務', '主人需要草。我們的手太大，沒有辦法撿。你可以幫我們，我們不傷害你。我們需要陰暗草。這裡有許多這樣的草，路邊也有。$B$B拿到草之後，把它交給布瑞爾墓地的主人，霍蘭德。', '收集3根陰暗草，把它們交給布瑞爾墓地的初級藥劑師霍蘭德。', '', '去找布瑞爾的初級藥劑師霍蘭德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5482, 'zhTW', '末日草', '你看到我所處的困境了吧， $N ?那個蠢貨弄來的野草根本不是我要的!如果你能幫我弄到需要的東西，我會回報你的。幫我帶來足夠的末日草我就會給你適當的獎勵。$B$B據我所知，那些野草一般生長在大墓地附近的植物群裡，就在布瑞爾墓地北面。快去吧，小心那兒的豺狼人。', '收集10株末日草，把它們交給初級藥劑師霍蘭德。', '', '去提里斯法林地找布瑞爾的初級藥劑師霍蘭德。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 5501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5501, 'zhTW', '集骨者', '我們正坐在一座金礦上，你知道嗎，一座金礦！科多獸骨將永遠改變這個世界……我的顧客可以用它們來製作傢俱、樂器，甚至是火藥。$B$B有一個車隊經常到這兒來，收集一大堆科多獸骨，然後在葬影村把它們賣掉。如果你能去到南邊的那座科多墓地去給我弄十根科多獸骨回來，我就付你報酬。怎麼樣？', '從科多墓地收集10根科多獸骨，把它們交給獸人小屋的比布里·弗斯巴克。', '', '去找淒涼之地的比布里·弗斯巴克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5502, 'zhTW', '部落孤兒的看護者', '你對我真好，$N。我從來沒有想過會在兒童週得到如此多的樂趣，謝謝你。我不會因為我的悲慘遭遇而感到悲傷——我的爸爸媽媽總是告訴我，在面對困境的時候要保持堅強。我會成為一個英雄的……就像你一樣。$B$B不過現在，我該回家了。讓我們一起回去吧，我會告訴院長，你是一個多麼出色的$r$c！', '回到奧格瑪，把獸人孤兒哨交還給榮譽谷的孤兒監護員巴特維爾。', '', '去找奧格瑪的孤兒監護員巴特維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5503, 'zhTW', '銀色黎明委任徽章', '', '', '', '', '', '', '', '', 0);
