INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5521, 'zhTW', '炫彩黎明披肩', '$N，你為銀色黎明做出的貢獻在這裡被廣為傳頌。作為一種獎勵，你將有資格獲得我們特殊的炫彩黎明披肩，它可以幫你抵抗各種魔法效果。炫彩黎明披肩只會被授予最強大的英雄!$B$B交給我二十五枚勇氣勳章作為你對銀色黎明做出貢獻的標誌，然後我就會把我們最好的披肩給你。', '把25個銀色黎明勇氣勳章交給西瘟疫之地冰風營地的銀色黎明軍需官萊斯巴克。', '', '去西瘟疫之地找冰風崗的銀色黎明軍需官萊斯巴克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5522 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5522, 'zhTW', '萊尼德·巴薩羅梅', '我從我的主人維克圖斯那裡收到了一個訊息。好吧，其實不是從維克圖斯那裡來的……是來自於一個名叫萊尼德·巴薩羅梅的人。我不認識他，但是他認識我的主人。你要知道，除非我的主人允許，否則你是根本無從結識他的。$B$B他說維克圖斯需要龍蛋，因此它要你把它們送到東瘟疫之地的聖光之願禮拜堂去。$B$B這真讓我惱火！為什麼？難道維克圖斯不相信我嗎？哦，不要介意這些……把蛋交給萊尼德，告訴他我已經完成了主人的命令。', '把冰凍的龍蛋交給東瘟疫之地的萊尼德·巴薩羅梅。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5523 AND `locale` = 'zhTW';
