INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5673, 'zhTW', '伊露恩的賜福', '$N，不要虛度光陰，你該回一趟達納蘇斯了。女祭司阿蘭希雅派人捎信來通知你返回家園進行試煉。他們似乎認為你已準備好接受新的試煉了，就像那些信仰聖光的人也要接受試煉一樣。阿蘭希雅說她正在月神殿等你，祝你好運。', '與達納蘇斯的女祭司阿蘭希雅談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5674, 'zhTW', '伊露恩的賜福', '今天是個好日子，$N。你已經到了學習那些只有夜精靈牧師才能掌握的特有技能的年紀了，不過負責訓練你的並不是我。你應該儘快了結你在此地的事務，然後返回月神殿去跟女祭司阿蘭希雅談談。她將對你進行試煉以確保你已準備就緒，只有透過了她的試煉，你才能學到伊露恩的恩賜。', '與達納蘇斯的女祭司阿蘭希雅談一談。', '', '', '', '', '', '', 0);
