INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5675, 'zhTW', '伊露恩的賜福', '$g小夥子:小姑娘;，不要虛度光陰，你該回一趟達納蘇斯了。女祭司阿蘭希雅派人捎信來通知你返回家園進行試煉。他們似乎認為你已準備好接受新的試煉了，就像那些信仰聖光的人也要接受試煉一樣。阿蘭希雅說她正在月神殿等你，祝你好運。', '與達納蘇斯的女祭司阿蘭希雅談一談。', '', '', '', '', '', '', 0);
