INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5677, 'zhTW', '秘法回饋', '我很想向你傳授使用聖光的技能，但是這不是該由我們來做的事情。現在，你應該回到暴風城裡，去找你的同伴，$N……相信我，我沒有冒犯你的意思。當你回到光明大教堂的高階牧師勞瑞娜那兒時，你就會了解我在說什麼了——現在是你的種族為了未來而訓練你，使你在同類人中出類拔萃的時候了。', '與暴風城的高階牧師勞瑞娜談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5678, 'zhTW', '奧術回饋', '年輕人，現在你該回一趟暴風城了，你的上司召喚你回去接受更多的試煉。儘管你的離去會稍微擾亂我的計劃，但是你的種族和我的種族是同盟，而我是永遠不會背棄盟約的。$B$B我並不想在你面前扭捏作態——不管那些神秘的魔法是否是由神授予的，我對這些魔法都感到強烈地不信任。$B$B當你返回光明大教堂之後，你就會明白我所說的這些話的意義了，到那裡去跟高階牧師勞瑞娜談談吧。', '與暴風城的高階牧師勞瑞娜談一談。', '', '', '', '', '', '', 0);
