INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5683, 'zhTW', '星夜之衣', '啊，我的$g兄弟:姐妹;，我真為你感到高興！是時候讓你回到達納蘇斯去和高階女祭司阿蘭希雅談談了。我的信使很肯定地說，你所屬的教會要送新的袍子給你。$B$B你有空的時候就趕快回去一趟，待我向月神殿的姐妹們問好。$B$B願伊露恩與你同在。', '與達納蘇斯的高階女祭司阿蘭希雅談一談。', '', '', '', '', '', '', 0);
