INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5684, 'zhTW', '星夜之衣', '嗯，很高興看到你在不斷進步，牧師。也許你正在考慮什麼時候該回達納蘇斯去慶祝一番，對不對？好吧，至少今天不會……我是說不會有什麼慶祝。$B$B高階女祭司阿蘭希雅捎信來告訴我，如果我碰到你的話就讓你回去一趟。你可以在月神殿找到她。', '與達納蘇斯的高階女祭司阿蘭希雅談一談。', '', '', '', '', '', '', 0);
