INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5695, 'zhTW', '達納蘇斯的星光', '你的神殿在召喚你回到達納蘇斯去，$N。回到月神殿，然後和女祭司阿蘭希雅談談，她會在那裡等你的。$B$B如果你感覺自己已經準備好了，那就回去贏得你的新袍子吧。', '與達納蘇斯的女祭司阿蘭希雅談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5696 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5696, 'zhTW', '達納蘇斯的星光', '每當我的同胞有資格回家鄉去贏得他們的新袍子時，我總是會感到很高興。$B$B月神殿的女祭司阿蘭希雅要和你談談，當你準備好了的時候，就回到達納蘇斯去接受你的下一個考驗吧，願伊露恩與你同在，$N。', '與達納蘇斯的女祭司阿蘭希雅談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5697 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5697, 'zhTW', '達納蘇斯的星光', '如果你保持這樣驚人的成長速度，那我就會覺得我們鐵爐堡這裡怎麼沒有多一點像你這樣的牧師，$N。你讓你的同胞感覺驕傲。$B$B如果你有時間的話，就回一趟達納蘇斯，跟女祭司阿蘭希雅談一談吧，她就在月神殿裡等你。願聖光與你同在。', '與達納蘇斯的女祭司阿蘭希雅談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5698 AND `locale` = 'zhTW';
