INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5702, 'zhTW', '古代儀式', '嘿，你過來一下！我可以把所有你想要知道的東西都教給你，但是你應該知道烏爾庫——這是他的名字，對吧？——他正在找你。他有事情要讓你回到試煉谷——不，搞錯了，是奧格瑪的精神谷。對，就是那裡！$B$B嗯，是精神谷……的烏爾庫。他要和你談談。', '與奧格瑪的烏爾庫談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5703 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5703, 'zhTW', '古代儀式', '你們的精神領袖烏爾庫正在找你，$N。不要讓他等太久。$B$B你可以在部落城市奧格瑪的精神谷中找到他。', '與奧格瑪的烏爾庫談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5704 AND `locale` = 'zhTW';
