INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5711, 'zhTW', '失落的道路', '我在想，我有多少次看到過你這樣的$r從我面前走過卻從來沒有和你們說過話。我訓練過一些新手，給他們指引過方向，但是從來也沒人停下來和我談話。$B$B好吧，現在並不是聊天的時候——你應該到奧格瑪去找烏爾庫，他在精神谷等你。', '與奧格瑪的烏爾庫談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5712, 'zhTW', '失落的道路', '願好運與你同在，年輕的$r。$B$B大概一天之前有一個巨魔的信使來幽暗城找你，說是要召集年輕的牧師回精神谷去跟烏爾庫談談。我希望你自己到那裡去把事情搞清楚，你應該記得回奧格瑪的路吧？', '與奧格瑪的烏爾庫談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5713, 'zhTW', '一擊必殺', '我本來是帶著一封重要的信件往奧伯丁去，但是熊怪瑪洛什帶著它的爪牙襲擊了我。在這次攻擊事件中，我不慎中毒了，現在我幾乎無法站起來。當然，我可以製作解毒藥，但是這需要花些時間。$B$B你能在我製作解毒藥的時候保護我嗎？我會盡力協助你的。$B$B如果我們活下來的話，我就動身把那封信送到奧伯丁去，而你負責向邁斯特拉崗哨的奧奈雅報告這件事情。', '保護哨兵阿娜莎，然後向梣谷邁斯特拉崗哨的奧奈雅報告。', '保護阿娜莎', '去找梣谷的哨兵奧奈雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5721, 'zhTW', '達隆郡的戰鬥', '現在，$N，你將參加達隆郡的戰鬥，並且拯救約瑟夫·雷德帕斯。$B$B把這個聖物包裹放到達隆郡的廣場中，達隆郡居民的靈魂將因此而被喚醒。參加他們的戰鬥，並確保你完成兩件事:在霍古斯死後，達維必須存活;雷德帕斯必須存活，直到他被腐化而墮落，此時再將其擊敗。$B$B在打敗了墮落的雷德帕斯之後，他的靈魂就將得到救贖。同他交談，然後再去找他的女兒帕米拉。', '將聖物包裹放在達隆郡的廣場中。$B$B在霍古斯死亡之前，達維必須存活。$B$B在雷德帕斯隊長墮落之前保證他存活。$B$B擊敗墮落的雷德帕斯。$B$B當約瑟夫·雷德帕斯出現在廣場中時，與他的靈魂進行交談，然後回到帕米拉的家中去找帕米拉。', '', '去找東瘟疫之地的帕米拉·雷德帕斯。', '接受雷德帕斯的寬恕', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5722, 'zhTW', '尋找背包', '穴居人並不是怒焰裂谷中唯一令瑪加薩感興趣的東西。她已經得到訊息說她的僕從——瑪爾·恐怖圖騰在怒焰裂谷找到了某種奇特的東西，但是他沒能活著把它拿出來。她希望能找到瑪爾的遺體——如果他還有遺體的話——以及他在試圖與穴居人交談的過程中發現的東西。$B$B如果你能將瑪加薩感興趣的東西交給她，我敢肯定她會慷慨地獎賞你。$B那麼，到奧格瑪最黑暗的區域去找尋怒焰裂谷吧。', '在怒焰裂谷搜尋瑪爾·恐怖圖騰的屍體以及他留下的東西。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5723, 'zhTW', '試探敵人', '在奧格瑪城的地下，那些被稱為穴居人的生物正在從充滿岩漿的管道深處源源不斷地湧出來。瑪加薩心懷仁愛，試圖與這些生物和平相處，但是他們卻對她派出的外交官大開殺戒。她絕不允許牛頭人受到這樣的待遇，現在她將穴居人看作是整個部落的威脅。$B$B她希望你在穴居人毀滅部落之前消滅他們——找到怒焰裂谷，把他們全都殺掉。', '在奧格瑪找到怒焰裂谷，殺掉8個怒焰穴居人和8個怒焰薩滿祭司，然後向雷霆崖的拉哈羅覆命。', '', '去雷霆崖找長者高地的拉哈羅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5724, 'zhTW', '歸還背包', '你在牛頭人的屍體上發現了一個小包。他的手臂緊緊地夾著它，似乎在被穴居人攻擊時還試圖保護這個小包。$B$B你從他那鉗子般緊握的手臂中取出小包，裝入你自己的行囊，準備離開隧道返回雷霆崖的拉哈羅那裡去。', '將恐怖圖騰背包交給雷霆崖的拉哈羅。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5725 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5725, 'zhTW', '毀滅之力', '你知道，燃燒軍團的許多追隨者都得到過它們的主子賜予的禮物。黑暗女王認為，某些有價值的東西與其被那些鼠目寸光的渣滓拿著，倒不如為自己所用。$B$B暗影議會的一支勢力隱藏在奧格瑪地下的洞穴中，他們被稱為燃刃氏族。黑暗女王告訴我，燃刃氏族的成員擁有兩本強大的法術書——她想“借”來看一看。你去取回這些書吧。', '將《暗影法術研究》和《扭曲虛空的魔法》這兩本書交給幽暗城的瓦里瑪薩斯。', '', '去幽暗城找皇家區的瓦里瑪薩斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5726, 'zhTW', '隱藏的敵人', '如果說有什麼是我絕對不能容忍的，那就是我們當中的背叛者。但是我過早地插手這件事，真有些愚蠢─這不僅不能有效地清除那些墮落者，反而使得叛徒越來越多。$B$B但是，你，年輕的冒險者，你可以進入那些我的密探所不能到達的地方……你能發現真相……你能找出那些叛徒的幕後主使。$B$B如果你足夠勇敢的話，就去奧格瑪東邊的骷髏石，找到火刃氏族軍官的徽記，然後回到我這兒來。', '將軍官的徽記交給奧格瑪的索爾。', '', '去找奧格瑪的索爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5727, 'zhTW', '隱藏的敵人', '讓我們看看你找到的徽記是否有價值。$B$B城中有一個術士，他認為自己已經得到了我的信任，但是他並不知道我很瞭解他真正效忠的主人是誰。他實際上是火刃氏族的領袖。先別急著跟他開戰，因為他還有用處，我們可以利用他來對付我們的敵人。$B$B去奧格瑪的暗影裂口找他，把這枚徽記交給他，跟他談談，看他是否相信你是他的同夥，然後回到我這兒來。', '將軍官的徽記交給尼爾魯·火刃並與他談話，看看他是否相信你是火刃氏族中的一員，然後回到奧格瑪的索爾那裡。', '看看尼爾魯·火刃是否相信你是火刃氏族的成員', '去找奧格瑪的索爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5728, 'zhTW', '隱藏的敵人', '嗯，灼刃氏族的首領……這可是件至關重要的事。如果他們是尼爾魯的幹將，那他們就是我們的首要目標。這個薩特……巴札蘭，以及另一個尼爾魯提及的傢伙─他是幹什麼的來著，是個術士?─必須被除掉。$B$B回到怒焰裂谷去， $N 。找到灼刃氏族的兩名首領，殺死他們。但是別讓尼爾魯知道是你幹的。你必須繼續偽裝成他的忠實追隨者，不要暴露身份。', '殺死巴札蘭和『塑能師』耶戈什，然後回到奧格瑪的索爾那裡。', '', '去找奧格瑪的索爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5729, 'zhTW', '隱藏的敵人', '我想下一步應該讓你接近尼爾魯。如果他像報告中所說的那樣焦慮不安，那麼我們也許能做成兩件事。第一，你可以獲得關於議會或者至少是 火刃氏族的更多情報；第二，你也許能取得他的信任，他會讓你協助他。鑑於當前領導層的混亂狀況，他可能會將你當作填補空缺的人選。$B$B回到他那裡去，再跟他談談，但是別露出馬腳來。', '與奧格瑪的尼爾魯·火刃談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5730, 'zhTW', '隱藏的敵人', '你是我的得力助手！做好準備，$c。不久之後我就會召喚你。$B$B我花在灼刃氏族上的時間看來是白費了，但是這不意味著暗影議會的其它計劃也會受到影響。我要儘可能地消除在怒焰裂谷的損失。同時，我會讓我在貧瘠之地和梣谷的部下繼續執行新的計劃。盡快回到我這裡來。', '與奧格瑪的索爾談一談，告訴他你瞭解到的東西。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5741, 'zhTW', '聖光節杖', '據說，東邊雷斧要塞中的火刃氏族從納迦那裡得到了聖光節杖。那根節杖的力量足以讓整座城市瞬間沉入無盡之海中。這樣的力量一定不能落入火刃氏族的魔掌！$B$B你必須去拿回節杖！它在一個火刃先知手中，那個先知就待在某座雷斧哨塔的頂部。', '拿到聖光節杖，並將它交給艾瑟雷索塔裡的阿佐爾·奧達蒙特。', '', '去淒涼之地找艾瑟雷索的阿佐爾·奧達蒙特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5742 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5742, 'zhTW', '救贖', '你幹得很好，朋友。休息一下，然後聽聽我的自我介紹。', '聽聽提里奧·弗丁要說什麼。', '提里奧的故事', '去西瘟疫之地找索多里爾河的提里奧·弗丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5761, 'zhTW', '『飢餓者』塔拉加曼', '我們偉大的酋長交給我的首要任務就是搜尋那些利用惡魔的力量破壞城市的敵人。火刃氏族是個威脅，但是這裡還存在著其他的威脅，比如在怒焰裂谷安家的灼刃氏族，他們暗地裡計畫著襲擊部落的無辜民眾。$B$B要想阻止他們，就必須殺死他們的領袖─那個被稱作『飢餓者』塔拉加曼的惡魔守衛。$B$B殺死他，索爾看到他的心臟之後一定會安心很多，這點我可以確信。', '進入怒焰裂谷，殺死『飢餓者』塔拉加曼，然後把他的心臟交給奧格瑪的尼爾魯·火刃。', '', '去找奧格瑪的尼爾魯·火刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5762, 'zhTW', '小赫米特·奈辛瓦里', '我有個包裹要給我的新顧客，一個名叫小赫米特·奈辛瓦里的矮人。這個包裹花了幾個星期才到我這裡，那時候赫米特早就走了。他說他要去荊棘谷代替他父親打獵，但是他給我留了一些錢，讓我在有必要的時候把他的包裹寄給他。$B$B赫米特是個富有的矮人，所以我們最好和這號人物保持良好的關係，是不是？那麼……你願意幫我遞送包裹嗎？$B$B我聽說赫米特在荊棘谷裡紮了營，就在格羅姆高的北邊。', '將克拉維爾的箱子送到荊棘谷的小赫米特·奈辛瓦里那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5763 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5763, 'zhTW', '荊棘谷狩獵', '很久以前，有一個矮人來到這片土地上。他的名字叫做赫米特，他的目標是狩獵強大的野獸。他用起火槍來簡直是出神入化，我們在一起狩獵了很多天，甚至遺忘了不同種族之間的隔閡與憎恨。$B$B現在他離開淒涼之地去了荊棘谷，我期待有一天他可以回來，這樣我們就可以再次一起狩獵了。不過，他現在到一個未知的世界去狩獵了，所以他的兒子接替了他的位置。$B$B把這支科多獸角交給赫米特二世……我聽說他在荊棘谷裡紮了營，就在格羅姆高的北邊。', '將魯恩的科多獸角送到荊棘谷的赫米特·奈辛瓦里二世那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5781, 'zhTW', '遺忘的記憶', '為了幫泰蘭找回他失去的東西，你必須收集他過去曾經使用過的物品。$B$B第一件是一個玩具，那是他7歲的時候我送給他的。這個玩具是他最珍愛的禮物:一隻小小的戰錘，那是我的戰錘的複製品。$B$B在我因叛國罪而被驅逐出去的時候，他媽媽告訴他我已經死了。他被帶到了我的「墳墓」前，就在南邊的墓室旁邊，把那隻小戰錘和對我的記憶永遠地埋在了那裡。$B$B你必須去一趟墓室，拿回泰蘭之錘。', '到東瘟疫之地最南端的墓室去找回泰蘭之錘。完成目標之後，返回提里恩·弗丁那裡。', '', '去找東瘟疫之地的提里恩·弗丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5801, 'zhTW', '火羽山', '你需要兩塊瑟銀錠和一個強大的熱源來鍛造鑰匙的主體部分。你得自己去找瑟銀，但是我可以幫你找到熱源。$B$B我們西面的安戈洛環形山裡有一座溫度極高的火山，它被稱作火羽山。山頂的岩漿足以把瑟銀和骨頭熔在一起。你只需把買來的模具浸入熔岩湖中，然後就不用管其它的了。$B$B我的任務這就算是完成了。要完成你的鑰匙的話，你還得去跟阿爾比頓再談談。', '把骷髏鑰匙模具和2塊瑟銀錠帶到安戈洛環形山地區的火羽山頂部。在熔岩湖旁使用骷髏鑰匙模具，鑄造出一把未完工的骷髏鑰匙。$B$B把未完工的骷髏鑰匙交給西瘟疫之地冰風崗的鍊金師阿爾比頓。', '', '去西瘟疫之地找冰風崗的鍊金師阿爾比頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5802, 'zhTW', '火羽山', '你需要兩塊瑟銀錠和一個強大的熱源來鍛造鑰匙的主體部分。你得自己去找瑟銀，但是我可以幫你找到熱源。$B$B我們西面的安戈洛環形山裡有一座溫度極高的火山，它被稱作火羽山。山頂的岩漿足以把瑟銀和骨頭熔在一起。你只需把買來的模具浸入熔岩湖中，然後就不用管其它的了。$B$B我的任務這就算是完成了。要完成你的鑰匙的話，你還得去跟迪瑟斯再談談。', '把骷髏鑰匙模具和2塊瑟銀錠帶到安戈洛環形山地區的火羽山頂部。在熔岩湖旁使用骷髏鑰匙模具，鑄造出一把未完工的骷髏鑰匙。$B$B把未完工的骷髏鑰匙交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。', '', '去提里斯法林地找亡靈壁壘的藥劑師迪瑟斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5803, 'zhTW', '阿拉基的聖甲蟲', '『召喚者』阿拉基在城市廢墟的中心統治整個安多哈爾。我們知道在他占領了自己的城市之前，曾是通靈學院的領導者，為了完成鑰匙，我們就必須拿到他的那個被稱作聖甲蟲的圖章，用它來製作鑰匙的頭部。$B$B開一條路進入安多哈爾的中心，擊破他在城中空曠區域的守備。一旦將他摧毀，從他掉落的骨匣中奪取聖甲蟲!$B$B通靈學院的鑰匙在等著你，$N!', '殺掉『召喚者』阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地冰風崗的鍊金師阿爾比頓。', '', '去西瘟疫之地找冰風崗的鍊金師阿爾比頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5804, 'zhTW', '阿拉基的聖甲蟲', '『召喚者』阿拉基在城市廢墟的中心統治整個安多哈爾。我們知道在他占領了自己的城市之前，曾是通靈學院的領導者，為了完成鑰匙，我們就必須拿到他的那個被稱作聖甲蟲的圖章，用它來製作鑰匙的頭部。$B$B開一條路進入安多哈爾的中心，擊破他在城中空曠區域的守備。一旦將他摧毀，從他掉落的骨匣中奪取聖甲蟲!$B$B通靈學院的鑰匙在等著你，$N!', '殺掉『召喚者』阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。', '', '去找提裏斯法林地的藥劑師迪瑟斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5805, 'zhTW', '歡迎！', '歡迎來到魔獸世界！$B$B為了感謝您購買魔獸世界典藏版，請將這張禮券交給北郡山谷的梅里薩·斯蒂維爾。您將得到一份特別的禮物：陪伴您踏上冒險旅途的小寵物！$B$B再次感謝您的支持，請盡情享受魔獸世界的樂趣吧！', '將北郡禮品券交給梅里薩·斯蒂維爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5821, 'zhTW', '僱傭保鏢', '一般來說，裡格和我會率領我們的科多獸商隊經過科卡爾半人馬的領地。我們不時地聽到半人馬的戰鼓聲，而每當聽到那種可怕的聲音，我們就會停下。為了掙幾個錢把命送掉可不值得！$B$B你猜怎麼著，$c，如果你保護我們透過科爾卡半人馬的村莊，我們會給你相應的報酬。$B$B這段路程很短，你需要做的就是讓商隊免受損失，然後你就可以從斯米德·瑟卡布斯庫那裡領取你的獎賞了——他在就在路的那一邊。我們有些生意上的往來。', '護送基澤爾頓商隊透過科卡爾半人馬村，然後與瑟卡布斯庫的營地中的斯米德談話以領取你的獎賞。', '護送基澤爾頓車隊穿過科卡爾半人馬的村莊', '去淒涼之地找瑟卡布斯庫的營地的斯米德·瑟卡布斯庫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5841, 'zhTW', '歡迎！', '歡迎來到魔獸世界！$B$B為了感謝您購買魔獸世界典藏版，請將這張禮券交給寒脊山谷的尤里·碎盔。您將得到一份特別的禮物：陪伴您踏上冒險旅途的小寵物！$B$B再次感謝您的支持，請盡情享受魔獸世界的樂趣吧！', '將寒脊山谷禮品券交給尤里·碎盔。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5842, 'zhTW', '歡迎！', '歡迎來到魔獸世界！$B$B為了感謝您購買魔獸世界典藏版，請將這張禮券交給幽影谷的奧雷希爾·語風。您將得到一份特別的禮物：陪伴您踏上冒險旅途的小寵物！$B$B再次感謝您的支持，請盡情享受魔獸世界的樂趣吧！', '將幽影谷禮品券交給奧雷希爾·語風。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5843, 'zhTW', '歡迎！', '歡迎來到魔獸世界！$B$B為了感謝您購買魔獸世界典藏版，請將這張禮券交給試煉谷的瑪卡爾。您將得到一份特別的禮物：陪伴您踏上冒險旅途的小寵物！$B$B再次感謝您的支持，請盡情享受魔獸世界的樂趣吧！', '將試煉谷禮品券交給瑪卡爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5844, 'zhTW', '歡迎！', '歡迎來到魔獸世界！$B$B為了感謝您購買魔獸世界典藏版，請將這張禮券交給納拉其營地的沃恩·星眼。您將得到一份特別的禮物：陪伴您踏上冒險旅途的小寵物！$B$B再次感謝您的支持，請盡情享受魔獸世界的樂趣吧！', '將納拉其營地禮品券交給沃恩·星眼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5845, 'zhTW', '失落的榮耀', '當烏瑟被殺之後，白銀之手騎士團完全瓦解了。$B$B這孩子竭盡所能地堅持著。當他被逼入飽經戰亂的北谷中時，他做了最後的抵抗。$B$B騎士團是否還有別人活著，這還有什麼意義嗎?$B$B正是帶著這樣的想法，泰蘭拋棄了騎士團的戰旗，並否認了他所熟知的一切。他的榮譽被遺棄在了北谷那浸滿鮮血的土地上。$B$B你必須到北谷去，找回那面代表失落的榮耀的戰旗。', '到東瘟疫之地東北部的北谷去，找到失落榮耀的象徵。完成目標之後向提里奧·弗丁覆命。', '', '去找東瘟疫之地的提里恩·弗丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5846, 'zhTW', '愛與家庭', '當泰蘭還是孩子的時候，我們全家經常去凱爾達隆度假。我們最後一次去那裡時，一位名叫瑞弗蕾的藝術家為我們畫了一張在湖邊漫步的畫。這是最能讓我回想起與泰蘭和卡蘭德拉在一起時的美好時光的東西。那個時候我牽著我的妻子和兒子，心中充滿了無限的愛意。如果那幅畫還存在的話，你必須找到它。去凱爾達隆那座廢棄的島上看看那副畫或者那個畫家是不是還在吧。', '到凱爾達隆島去，尋找關於那副畫的線索。凱爾達隆島在瘟疫之地南部的湖中央。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5847, 'zhTW', '歡迎！', '歡迎來到魔獸世界！$B$B為了感謝您購買魔獸世界典藏版，請將這張禮券交給喪鐘鎮的克雷爾·韋洛。您將得到一份特別的禮物：陪伴您踏上冒險旅途的小寵物！$B$B再次感謝您的支持，請盡情享受魔獸世界的樂趣吧！', '將喪鐘鎮禮品券交給克雷爾·韋洛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5848, 'zhTW', '愛與家庭', '那幅畫……它懸掛在我工作室的牆上——在騎士團的兵營裡面，一直掛了許多年。$B$B在提里奧的試煉結束以後，我就知道我再也不能把那幅畫掛在公開的場合中了。我把它藏在了一個他們永遠都不會想到去看的地方。$B$B到斯坦索姆去，深入現在被血色十字軍當作基地的區域，尋找一幅繪有兩個月亮的畫。把上面的油漆剷掉，你就可以找到我的傑作“愛與家庭”。$B$B願聖光指引你的行動。', '到瘟疫之地北部的斯坦索姆去。你可以在血色十字軍堡壘中找到“愛與家庭”這幅畫，它被隱藏在另一幅描繪兩個月亮的畫之後。$B$B把這幅畫還給提里奧·弗丁。', '', '去西瘟疫之地找索多里爾河的提里奧·弗丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5861, 'zhTW', '尋找米蘭達', '$N，你完成了我交給你的所有任務，你的救贖任務只剩最後一步了。$B$B你必須把你收集到的東西交給泰蘭。不幸的是，泰蘭和他的血色十字軍一看見你就會立刻攻擊你。$B$B要傳遞我的信件只有一個辦法，那就是進行偽裝。$B$B往南走，你可以在那邊找到烏瑟之墓。我有個值得信賴的老朋友米蘭達住在那兒，找到她，把這些東西給她看看，她會幫助你的。', '到瘟疫之地南部的烏瑟之墓去，將提里恩的禮物交給巫女米蘭達。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5862, 'zhTW', '血色幻象', '我就是你們所說的……幻術師。雖然我可以創造一個幻影，讓你平安進入壁爐谷，但是你要知道，我的力量也不是無限的。$B$B如果你離開這個地區太遠的話，幻影會漸漸消失。這個法術需要花費大量的精力，即使這樣我也只能堅持很短的時間。$B$B當你準備好之後再和我說話吧。', '和巫女米蘭達交談以獲得血色幻影的效果。在血色幻影的掩護下深入壁爐谷，將提里恩的禮物交給大領主泰蘭·弗丁。$B$B壁爐谷在北方，泰蘭應該在瑪登霍爾德城堡裡面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5863, 'zhTW', '砂槌食人魔', '最近一段時間，一大群食人魔來到了塔納利斯。他們已經在南面佔領了大片沙漠，並建立了一個營地。目前，食人魔的幾個小團伙正在沙漠裡四處遊蕩，其中有些已經侵佔了古老的巨魔廢墟。$B$B你必須去消滅砂槌食人魔！我們不能讓這些傢伙的勢力壯大起來。$B$B他們的頭目名叫掠奪者格瑪洛克，我認為如果能殺掉他，食人魔的勢力就會土崩瓦解。', '加基森的安迪·利恩想要你攻入砂槌營地，殺死10個砂槌蠻兵、10個砂槌執行者，以及掠奪者格瑪洛克。', '', '去找塔納利斯的安迪·利恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5881, 'zhTW', '召回衛兵', '部落在保持軍隊戰鬥力這方面做得很好……大戰之後我們一直在卡林多大陸上繁衍生息。$B$B我想讓你幫個忙，$n。我手下有個名叫瑞什·長跑者的士兵，他駐守在南貧瘠之地的升降梯附近。把這封信交給他，信中說我將派出一名戰士去接替他的工作，這樣他就能回家看看了。先前他曾向我提出過這樣的要求，他聽到這個訊息一定會很高興的。', '馬格蘭希望你將信送到貧瘠之地升降梯的瑞什·長跑者手中。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5882 AND `locale` = 'zhTW';
