INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5892, 'zhTW', '深鐵礦洞的補給', '在戰鬥開始前，我們曾在丹巴達爾的深鐵礦洞儲存了很多補給品。那個時候石齶怪對於那裡的騷擾在我們強大的軍力面前簡直是不堪一擊，但是現在我們必須和部落作戰，所以沒有足夠的人手來控制深鐵礦洞。$B$B我們需要深鐵礦洞中的補給品，$N。進入礦洞，把它們取回來。', '把10份深鐵礦洞補給品交給丹巴達爾的聯盟軍需官。', '', '去奧特蘭克山谷找丹巴達爾的雷矛軍需官。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5893 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5893, 'zhTW', '冷齒礦洞的補給', '北邊的冷齒礦洞是一個儲存多餘補給品的好東西，但是為了抵禦雷矛部族的瘋狂攻擊，我們沒有足夠的士兵駐守在那座礦洞中。因此，現在那裡經常落入聯盟的控制，或被地下冒出來的渣滓們控制……$B$B但是我們仍然需要補給品，$N！去冷齒礦洞，幫我拿回一些補給品來。小心那裡的敵人，戰局瞬息萬變……', '把10份冷齒礦洞補給品交給霜狼要塞的部落軍需官。', '', '去奧特蘭克山谷找霜狼要塞的霜狼軍需官。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5901, 'zhTW', '瘟疫與你', '為了削弱血色十字軍，我要拿下那座對他們來說至關重要的伐木場。我相信，如果他們損失了這麼重要的一個資源，定然會在構建防禦和重建城鎮的過程中捉襟見肘。你願意幫我的忙嗎，$N?$B$B把這個瓶子拿到東瘟疫之地的病木林去，在那裡的蟻丘上抓些白蟻，放進這個瓶子裡。當你收集到了足夠多的白蟻之後就回到我這裡來。', '在東瘟疫之地的蟻丘上使用空的白蟻瓶。當你收集了100隻瘟疫白蟻之後，就回到提里斯法林地的亡靈壁壘去找米克·萊文。', '', '去找提裏斯法林地的米克·萊文。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5902 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5902, 'zhTW', '瘟疫與你', '現在我們有足夠的白蟻了，把這隻鐵桶拿到壁爐谷南邊的北山伐木場去——就在那條通往鎮子的小路的西邊。$B$B當你到了那裡之後，就在伐木場的中間找個高一點的地方，比如一隻箱子或者別的什麼東西，把桶放在上面，然後開啟桶蓋。接下來的事情就交給那些白蟻吧。完事之後回到我這裡來，我會獎勵你的。', '到西瘟疫之地的北山伐木場去找個合適的地方，在那裡放下一桶瘟疫白蟻。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5903, 'zhTW', '瘟疫與你', '我試過很多方法來清除血色十字軍，但是從來都沒有成功過。好吧，我決定更換一下行事方法，我要讓他們吃吃苦頭。$B$B如果你願意幫我的話，我準備用最恐怖的白蟻來毀滅他們的伐木場。$B$B在靠近斯坦索姆的病木林裡有一種被瘟疫扭曲的白蟻。找到它們的巢穴，在瓶子裡裝滿白蟻，然後我們就把它們放到血色十字軍的伐木場裡!', '在東瘟疫之地的蟻丘上使用空的白蟻瓶。當你收集了100隻瘟疫白蟻之後，就回到西瘟疫之地的冰風營地去找納薩尼爾·杜馬。', '', '去西瘟疫之地找冰風營地的納薩尼爾·杜馬。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5904, 'zhTW', '瘟疫與你', '現在我們有足夠的白蟻了，把這只鐵桶拿到壁爐谷南邊的北山伐木場去─就在那條通往鎮子的小路的西邊。$B$B當你到了那裡之後，就在伐木場的中間找個高一點的地方，比如一隻木箱或者別的什麼東西，把桶放在上面，然後打開桶蓋。這樣，白蟻就會開始它們的工作，然後讓那個伐木場徹底完蛋。', '到西瘟疫之地的北山伐木場去找個合適的地方，在那裡放下一桶瘟疫白蟻。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5921, 'zhTW', '月光林地', '儘管目前塞納里奧議會中的大德魯伊範達爾·鹿盔和月光林地的守護者雷姆洛斯之間氣氛很緊張，但是神聖的月光林地仍然歡迎所有德魯伊的到來。既然你正在學習利爪德魯伊之道，那麼讓我來教你傳送到那裡去的法術吧，如果你想要在月光林地尋求知識或者慰藉，就可以施放這個法術。$B$B你現在應該到月光林地去，跟永夜港的德迪利特·星焰談談關於你的前途吧。祝你好運，年輕的德魯伊。', '使用法術“傳送：月光林地”抵達月光林地，在那裡與永夜港的德迪利特·星焰談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5922, 'zhTW', '月光林地', '所有的德魯伊——無論是牛頭人還是夜精靈——都是神聖的月光林地所歡迎的客人。月光林地的守護者雷姆洛斯一直以來都在密切注意著在此沉睡的所有德魯伊。既然你正在學習利爪德魯伊之道，那麼讓我來教你傳送到那裡去的法術吧，如果你想要在月光林地尋求知識或者慰藉，就可以施放這個法術。$B$B你現在應該到月光林地去，跟永夜港的德迪利特·星焰談談關於你的前途吧。祝你好運，年輕的德魯伊。', '使用法術“傳送：月光林地”抵達月光林地，在那裡與永夜港的德迪利特·星焰談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5923, 'zhTW', '響應召喚', '朋友，打擾一下……$B$B我注意到瑪斯雷·馭熊者已經放出話來，說想要和你談談。看樣子你即將開始嶄新的生活——去接受德魯伊的訓練，他將親自訓練你。瑪斯雷是大德魯伊的助手，也是泰達希爾中最為睿智、最為威嚴的德魯伊之一。$B$B他居住在達納蘇斯的塞納里奧區，就在範達爾·鹿盔所在的那棵樹的第二層。', '與達納蘇斯塞納里奧區的瑪斯雷·馭熊者談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5924 AND `locale` = 'zhTW';
