INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5926, 'zhTW', '響應召喚', '朋友，打擾一下……$B$B我注意到圖拉克·符文圖騰已經放出話來，說想要和你談談。看樣子你即將開始嶄新的生活——去接受德魯伊的訓練，他將親自訓練你。圖拉克是大德魯伊的助手，也是最為睿智、最為威嚴的德魯伊之一。$B$B他居住在雷霆崖，就在長者高地上的塞納里奧議會大帳裡。', '與雷霆崖長者高地上的圖拉克·符文圖騰談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5927, 'zhTW', '回應召喚', '朋友，打擾一下……$B$B我注意到圖拉克·符文圖騰已經放出話來，說想要和你談談。看樣子你即將開始嶄新的生活——去接受德魯伊的訓練，他將親自訓練你。圖拉克是大德魯伊的助手，也是最為睿智、最為威嚴的德魯伊之一。$B$B他居住在雷霆崖，就在長者高地上的塞納里奧議會大帳裡。', '與雷霆崖長者高地上的圖拉克·符文圖騰談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5928, 'zhTW', '響應召喚', '朋友，打擾一下……$B$B我注意到圖拉克·符文圖騰已經放出話來，說想要和你談談。看樣子你即將開始嶄新的生活——去接受德魯伊的訓練，他將親自訓練你。圖拉克是大德魯伊的助手，也是最為睿智、最為威嚴的德魯伊之一。$B$B他居住在雷霆崖，就在長者高地上的塞納里奧議會大帳裡。', '與雷霆崖長者高地上的圖拉克·符文圖騰談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5929 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5929, 'zhTW', '巨熊之靈', '在月光林地的西北部住著一個充滿智慧而又高貴的生物，我們稱它為巨熊之靈。對所有德魯伊來說，它能夠教授他們關於熊的第一課——關於熊的最本質的東西。所有的德魯伊都要去尋找巨熊之靈，尋求它的智慧，你也不例外。$B$B現在就到巨熊之靈那裡去，學習它教給你的東西吧。當它對你的學習感到滿意之後，你就可以回到永夜港來找我了。我們會檢驗你是否真的學會了它教給你的東西。', '到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。', '到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識。', '去月光林地找永夜港的德迪利特·星焰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5930, 'zhTW', '巨熊之靈', '在月光林地的西北部住著一個充滿智慧而又高貴的生物，我們稱它為巨熊之靈。對所有德魯伊來說，它能夠教授他們關於熊的第一課——關於熊的最本質的東西。所有的德魯伊都要去尋找巨熊之靈，尋求它的智慧，你也不例外。$B$B現在就到巨熊之靈那裡去，學習它教給你的東西吧。當它對你的學習感到滿意之後，你就可以回到永夜港來找我了。我們會檢驗你是否真的學會了它教給你的東西。', '到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。', '到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識。', '去月光林地找永夜港的德迪利特·星焰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5931, 'zhTW', '返回達納蘇斯', '我們該分道揚鑣了，年輕的$r，現在你必須回到派你來這裡的導師那裡。瑪斯雷·馭熊者和自然相處得很好——即使他正居住在自然平衡陷入混亂的地方。聽從他的指導，你很快就可以完成你作為自然保護者的第一課了。$B$B現在就去吧，年輕的$r。我們會再次相見的。', '回到達納蘇斯，與塞納里奧區的瑪斯雷·馭熊者談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5932, 'zhTW', '返回雷霆崖', '我們該分道揚鑣了，年輕的$r，現在你必須回到派你來這裡的導師那裡。雖然牛頭人在領悟塞納留斯的教義這方面還是新手，但是圖拉克·符文圖騰和大自然的關係非常融洽。聽從他的指導，你很快就可以完成你作為自然保護者的第一課了。$B$B現在就去吧，年輕的$r。我們會再次相見的。', '回到雷霆崖，與長者高地的圖拉克·符文圖騰談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5941 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5941, 'zhTW', '返回克羅米身邊', '你已經收集了達隆郡之戰中留下來的許多遺物。每次你給我帶回更多的遺物，我的心就更加嚮往我的家園……更加急切地想要改變它的命運。$B$B我覺得這不可能，但是克羅米——那個安多哈爾奇怪的地精告訴我說，這是有可能的。她說你可以拯救達隆郡！$B$B她要我收集所有的遺物，然後由你去把那些東西交給她。她說她仍然在安多哈爾的廢棄旅店裡等你。', '將一包遺物交給安多哈爾的克羅米。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5942 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5942, 'zhTW', '隱藏的寶藏', '爸爸讓我給你這把鑰匙，他說你可以用它開啟房子後面的一隻箱子。$B$B他還要讓我謝謝你。你是不是幫過他？你有沒有告訴他你幫我找到了我的洋娃娃？$B$B好吧，這裡是鑰匙。謝謝你，$N。謝謝你！你是個好心的$g先生:小姐;！', '用約瑟夫的鑰匙開啟約瑟夫的箱子。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5943, 'zhTW', '基澤爾頓車隊', '你看上去是個能幹的$r，想不想賺點外快？考克和我為了賺錢而開始了這趟旅程，但是我們不知道此行的兇險！$B$B前面就是瑪諾洛克集會所……通常那裡的惡魔會忽視我們，但是這一次，有些東西把科多獸趕得四散驚逃。我願意付錢讓你保護我們透過瑪諾洛克集會所，在我們安全透過之後，你就可以到瑟卡布斯庫的營地去，從我們商業夥伴斯米德那裡獲得你的獎勵。', '護送基澤爾頓車隊透過瑪諾洛克集會所，然後與瑟卡布斯庫的營地的斯米德談一談，領取你的獎勵。', '護送基澤爾頓車隊透過瑪諾洛克集會所', '去淒涼之地找瑟卡布斯庫的營地的斯米德·瑟卡布斯庫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5944 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5944, 'zhTW', '在夢中', '那麼長時間以來，我都是大十字軍戰士的傀儡。是什麼讓血色十字軍變成了他們努力抗爭的東西？數十年來，我對於父親的記憶從未丟掉一絲一毫，這些寶貴的東西讓我繼續活在這世上。$B$B我經常做夢，在夢裡，我的父親和我在一起。他驕傲地站在我的身旁，看著我加入騎士團。我們和成群的天災士兵作戰，我們給聯盟和羅德隆帶來了榮耀。$B$B我再也不想做夢了。$B$B把我帶到他那裡去。', '護送泰蘭·弗丁走出壁爐谷。', '救贖？', '去西瘟疫之地找索多里爾河的提里奧·弗丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5961, 'zhTW', '女妖之王的勇士', '我很高興地看到強大的勇士不斷加入我們的行列。隨著時間的推移，我們的軍隊數量和戰鬥力在不斷提升。也許現在已經到了考驗你的勇氣的時候了，$c。我手下最勇猛的大將是納薩諾斯·凋零者。我們之中很少有誰能比他更具有奉獻精神和活力了。到東瘟疫之地去找他。他就住在瑪瑞斯農場，偶爾也會在附近徘徊，殺死沿途所遇到的一切天譴軍團和聯盟成員。', '與東瘟疫之地的納薩諾斯·凋零者談一談。據說他居住在瑪瑞斯農場。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5981, 'zhTW', '狂暴的巨人', '大約四千年前，泰蘭妲·語風從狂暴的巨人手中救了霜刃豹女王的命。從那個時候開始，霜刃豹就是夜精靈的盟友。$B$B那些對霜刃豹造成極大威脅的巨人依然在這附近徘徊——霜槌巨人佔據了這裡南邊的一處山谷。$B$B向霜刃豹證明你的忠誠吧；以霜刃豹女王希洛塔姆的名義殺死那些巨人！', '雷沃·霜翼要你去殺死4個霜槌巨人和4個霜槌保衛者。', '', '去冬泉谷找霜刀石的雷沃·霜翼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6001, 'zhTW', '身心之力', '在奧伯丁的正東方有很多月夜梟獸的洞穴，離奧伯丁最近的洞穴內有一塊月夜梟獸之石。月爪梟獸是這塊石頭的守護者，只有當塞納里奧月塵灑在石頭上的時候它才會出現。月爪梟獸的體內有一種力量，你必須得到這種力量，才能成為真正的利爪德魯伊。$B$B你已經獲得了使用塞納里奧月塵的權力，$N……現在向我證明你已經贏得了擁有身心之力的權力！', '使用奧伯丁的月夜梟獸之石上面的塞納里奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。$B$B任務完成之後，與達納蘇斯的瑪斯雷·馭熊者談一談。', '擊敗月爪梟獸並吸取它所擁有的身心之力。', '去達納蘇斯找塞納里奧區的瑪斯雷·馭熊者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6002, 'zhTW', '身心之力', '在貧瘠之地的陶拉祖營地西邊——就在快要進入莫高雷的地方——有一塊月夜梟獸之石。月夜梟獸是一種特殊的獸類，不是當地土生土長的動物。月爪梟獸是那塊石頭的守護者，只有當塞納里奧月塵灑在石頭上的時候它才會出現。月爪梟獸的體內有一種力量，你必須得到這種力量，才能成為真正的利爪德魯伊。$B$B你已經獲得了使用塞納里奧月塵的權力，$N……現在向我證明你已經贏得了擁有身心之力的權力！', '使用莫高雷與貧瘠之地交界處的月夜梟獸之石上面的塞納里奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。$B$B任務完成之後，與雷霆崖的圖拉克·符文圖騰談一談。', '擊敗月爪梟獸並吸取它所擁有的身心之力。', '去找雷霆崖的圖拉克·符文圖騰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6004 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6004, 'zhTW', '未完成的任務', '我以間諜的身份來此暗中搞破壞，並負責偵察壁爐谷的防禦力量。聯盟中的一些人認為這座小鎮的重要性並不局限於其歷史意義，不過這與我的工作無關。但無論如何，我要好好休息一下才有精力繼續做事。$B$B如果你願意的話，我願意出大價錢換取你的幫助。沿著堡壘附近的營帳往南查看。如果你能證明自己的實力，或許你就能幫上我的大忙呢。', '殺死2個血色醫護員、2個血色獵人、2個血色魔法師和2個血色騎士，然後回到西瘟疫之地的科爾斯塔·迪普沙東那兒。', '', '去找西瘟疫之地的科爾斯塔·迪普沙東。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6021, 'zhTW', '『流亡者』塞達爾', '在經歷了瘟疫之地的一次次禍事之後……我們還得防著盜賊。你能相信嗎?他們不是普通的盜賊，而是食人妖盜賊。$B$B不是普通的食人妖盜賊。而是亡靈食人妖盜賊!$B$B統帥這夥盜賊的是一個身體魁梧的亡靈食人妖，『流亡者』塞達爾，他們趁著夜色來到這裡，從下面的坑裡盜取屍體，然後把屍體運到他們那邪惡的藏身之所─西邊的墓室中。$B$B到那兒去，幹掉塞達爾，$N。我對他深惡痛絕!', '將塞達爾的頭顱交給聖光之願禮拜堂的護理者奧林。', '', '去東瘟疫之地找聖光之願禮拜堂的護理者奧林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6022, 'zhTW', '殺戮的理由', '我的要求就是你殺戮的理由。$B$B你的第一個任務是餵養我的獵犬。$B$B拿著這個研缽和搗杵，然後到考林路口去。你可以在那裡發現很多可供你屠殺的不死生物，從他們身上取得生命腐質，把它們放在研缽裡搗爛，然後等待它凝固。把凝固腐質給我拿回來。$B$B記住，笨蛋，那些生命腐質不會長時間保持「活力」，你必須動作快一些!', '到東邊的考林路口去屠殺鎮裡的天譴軍團。在10分鐘內收集7塊生命腐質，使用研缽和搗杵將其研磨成凝固腐質。', '', '去東瘟疫之地找瑪瑞斯農場的納薩諾斯·凋零者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6023, 'zhTW', '未完的任務', '我的真正任務是要削弱血色十字軍的外圍力量，然後潛入壁爐谷，探查他們的軍隊規模。現在我對這個行動還沒有什麼設想，因此我也許要再次請你幫助我，可以嗎，$N？根據我所收集的資料，血色十字軍在鎮外部署了兩個主要成員：獵人萊德雷和騎士杜爾根。殺了他們，這樣我們就離成功更近了一步。他們應該駐紮在壁爐谷小徑那裡，就在哨塔的附近。', '殺掉獵人萊德雷和騎士杜爾根，然後向西瘟疫之地的科爾斯塔·迪普沙東覆命。', '', '去找西瘟疫之地的科爾斯塔·迪普沙東。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6024, 'zhTW', '哈米亞的請求', '殺了我。否則就太遲了。$B$B我是哈米亞。在穿越祖爾瑪夏的時候，我和我的兄弟吃了點壞掉的肉……我們已經變了。我們已經被感染了。$B$B現在我可以感覺到巫妖的話語，他要求我去祖爾瑪夏，並感染更多我的同胞。我無法抵抗他的命令，所以在我失去一切之前，我寫下了這張卷軸。$B$B我在這座地穴的後方埋了一隻箱子，就在貨車旁的土堆中。但是只有我的鑰匙可以打開它，鑰匙在我的手裡。如果你想要得到我的財寶，就來找到我。$B$B殺了我。否則就太遲了。', '殺了滲透者哈米亞，用他的鑰匙開啟墓室後的一堆泥土。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6025 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6025, 'zhTW', '未完的任務', '什麼？真的？你想要知道更多的情報？但是你已經為我做了很多了，$N。我不能要求你為了我進入壁爐谷。$B$B你當真要去，$N？壁爐谷裡面可比那條小徑危險很多——我不能給你提供任何保護，也沒法告訴你那裡有什麼樣的危險。$B$B好吧，如果你真的想幫忙，那就到那個鎮子裡去，找一個可以俯瞰全景的高地。你可以在那裡估算一下十字軍的人數，然後回來向我報告。但是你一定要小心……', '進入壁爐谷並找一處高地，你可以在那裡觀察整個城鎮並估算血色十字軍的兵力，然後向西瘟疫之地的科爾斯塔·迪普沙東回報。', '在壁爐谷中尋找一處高地，在那裡觀察小鎮。', '去找西瘟疫之地的科爾斯塔·迪普沙東。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6026, 'zhTW', '獅子大開口', '銀色黎明的成員讓煙鬼給他們幹一些「爆炸性的」工作，煙鬼可不是小角色!只要你願意掏錢，我隨時為你效勞。這就是我的座右銘!$B$B如果你能為我做點跑腿之類的小事，那麼我也願意和你一起分享榮譽。具體來說是這樣的:我要去一趟病木林，然後給我們將要摧毀的建築物做上標記，而你就負責收集製造炸彈所需的材料。當你拿到所有東西之後就把它們交給我。你覺得怎麼樣?', '煙鬼拉魯恩要你拿來2塊瑟銀錠、1根金棒、8顆高爆爆裂物和8個不牢固的扳機。$B$B你需要找鐵匠和工程師幫忙製作這些東西。', '', '去東瘟疫之地找聖光之願禮拜堂的煙鬼拉魯恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6027 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6027, 'zhTW', '上古之書', '$n，拿著這顆毒蛇寶石。在這裡的西北面有一座小島，到那裡去把這顆寶石放在毒蛇雕像的手裡。它會召喚保護上古之書的守護者。那本書中包含了納迦的秘密，被埋藏了數百年的秘密。把這本書交給我，然後我們就會對那些長著鱗片的混蛋有更多的瞭解！', '拿到上古之書，將其交給艾瑟雷索塔中的阿佐爾·奧達蒙特。', '', '去淒涼之地找艾瑟雷索的阿佐爾·奧達蒙特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6028, 'zhTW', '永望鎮報告', '我正在找一個願意幫忙的$r，這事情雖然小，但是非常重要。我是作為銀色黎明的代表來考察永望鎮這裡的管理情況的，現在我要給冰風營地的銀色黎明軍官普爾哈特提交一份進度報告，冰風營地就在西瘟疫地的南部。$B$B如果你接下我的任務，就可以得到一個接觸我上司的好機會，也許你還可以從她那裡獲得一些工作！', '把永望鎮報告送給西瘟疫地冰風營地的銀色黎明軍官普爾哈特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6029 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6029, 'zhTW', '永望鎮報告', '我正在找一個願意幫忙的$r，這事情雖然小，但是非常重要。我是作為銀色黎明的代表來考察永望鎮這裡的管理情況的，現在我要給亡靈壁壘的銀色黎明軍官加魯什提交一份進度報告。亡靈壁壘就在西瘟疫之地的西部，提里斯法林地的東邊。$B$B如果你接下我的任務，就可以得到一個接觸我上司的好機會，也許你還可以從他那裡獲得一些工作！', '把永望鎮報告送給西瘟疫地亡靈壁壘的銀色黎明軍官加魯什。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6030 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6030, 'zhTW', '尼古拉斯·瑟倫霍夫公爵', '阿姆布蘭希發現的這本書為銀色黎明提供了豐富的文學財富……它也是迄今為止我讀過的最讓人摸不著頭腦的古書之一。$B$B我們令人尊敬的領袖尼古拉斯·瑟倫霍夫公爵是個睿智的語言學家。你能幫我把這個交給他嗎？當然會有獎勵。他現在就在聖光之願禮拜堂，東瘟疫之地的最東部。', '將《靈語研究》這本書交給東瘟疫之地聖光之願禮拜堂的尼古拉斯·瑟倫霍夫公爵。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6031 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6031, 'zhTW', '符文布', '我們木喉熊怪過著自給自足的生活，我們不喜歡陌生人。這對我們來說很好，但是這對交易不好。$B$B不久之前，一個夜精靈朋友來到了這裡，她披了一件符文布做成的披風。符文布在我們這裡很少見，但是那件袍子真的很不錯，所以夥伴們要我去找到更多的符文布。$B$B你願意給我弄些符文布來嗎？如果你能給我足夠的符文布，那我可以給你一些東西作為交換。', '把30塊符文布交給木喉要塞的梅羅什。', '', '去費伍德森林找木喉要塞的梅羅什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6032 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6032, 'zhTW', '神聖的月布', '雖然木喉熊怪很喜歡符文布，但是它對我們來說並不是神聖的。月布才是神聖的。$B$B給我帶一些這種神聖的布來，然後我就教你一種神秘的編織技巧。', '把2塊月布交給木喉要塞的梅羅什。', '', '去費伍德森林找木喉要塞的梅羅什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6041, 'zhTW', '煙鬼的炸藥', '在你收集材料的同時，我讓一些手下給那些天譴軍團的建築物做上了標記。$B$B計劃是這樣的：我將給你十根由我特製的炸藥。你要拿著它們去病木林，把它們放在那些已經被做上標記的天災建築物中。$B$B<煙鬼打了個響指。>$B$B嘭！然後世界就清靜了。', '到聖光之願禮拜堂西北方的病木林去。在那些有爆炸標記的建築物中對爆炸標記使用煙鬼的特殊混合物，以此來摧毀8座天譴軍團建築。煙鬼已經給通靈塔和屠宰房做上了標記。$B$B一旦你放置好炸彈，就離那些建築物遠一些，然後盡情欣賞你的傑作吧。$B$B順便說一句，煙鬼的特殊混合物相當不穩定……', '', '去東瘟疫之地找聖光之願禮拜堂的煙鬼拉魯恩。', '摧毀天災建築物', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6042 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6042, 'zhTW', '討厭的蝙蝠', '只要你離開農場兩步，就肯定可以撞見那些討厭的蝙蝠。我想帶著這些獵犬出去，在不驚動這些該死的傢伙的情況下剿滅天譴軍團。很明顯，與其讓我去沒日沒夜地砍殺蝙蝠，還不如做點更有意思的事情。但是你跟我不同。$B$B什麼?你的培訓?這就是培訓!出發吧，如果你不殺死一定數量的蝙蝠就別回來。不要讓我失望。', '殺掉20隻毒性瘟疫蝙蝠和10隻巨型瘟疫蝙蝠，然後回到納薩諾斯·凋零者那裡。', '', '去東瘟疫之地找瑪瑞斯農場的納薩諾斯·凋零者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6061, 'zhTW', '馴服野獸', '作為牛頭人，透過與強大的生物作戰來延續我們傳統是非常重要的。戰勝這些生物後，我們就能融合它們的靈魂，使自己與大地母親的聯絡更加緊密。$B$B同樣，馴服野獸，使它們與我們一同戰鬥，這有助於我們達到天人合一的境界。你最終要學習馴服一頭你中意的野獸，但是所有的事情都必須勤加練習才行，你要學的東西還很多。拿著這根馴獸棒開始訓練吧，你必須馴服一隻成年平原陸行鳥。', '使用馴獸棒馴服成年平原陸行鳥。練習你的技能，然後將馴獸棒還給血蹄村的雅文·刺鬃。', '馴服一隻成年平原陸行鳥', '去莫高雷找血蹄村的雅文·刺鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6062, 'zhTW', '馴服野獸', '擁有對自然的控制權是個令人羨慕的技能。作為一名獵人，你必須努力去了解並善用對自己馴服的生物身上那些與生俱來的力量。$B$B控制動物可不是件容易的事情，而是一項你必須下定決心去完成的艱鉅任務。$B$B你的第一項任務是使用這根馴獸棒去馴服一頭可怕的雜斑野豬，它們一般生活在剃刀嶺附近。在戰鬥中練習你的技能，馴服野豬，然後回到我這裡。', '使用馴獸棒馴服可怕的雜斑野豬。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。', '馴服一隻可怕的雜斑野豬', '去杜洛塔找剃刀嶺的索塔爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6063 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6063, 'zhTW', '馴服野獸', '作為一名獵人，謹記自己的職責是很重要的。自然不會屈服於我們的慾望，它就像比你更強大的某種力量一樣，應該得到你的尊敬和認可。$B$B$N，在你馴服動物使之成為你的同伴之前，你必須證明你已經理解了這一點。$B$B你的第一個任務是拿著這根馴獸棒，用它馴服一隻樹林潛伏者，以此來練習你的技能吧。', '使用馴獸棒馴服樹林潛伏者。練習你的技能，然後將馴獸棒還給多蘭納爾的達扎拉。', '馴服一隻樹林潛伏者', '去泰達希爾找多蘭納爾的達扎拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6064, 'zhTW', '馴服野獸', '嗨，這兒，$G小子:姑娘！嗯，你想知道如何獲得自己的寵物？$B$B好吧，我們這就開始吧。說到狩獵，沒有什麼比你的裝備更重要了，但我們可以另選個時候來談談我的新式火槍。現在，我們說正經的，你肯定對此感興趣：寵物！$B$B對你來說，學習的最好方法是挑選出一些生物來作為你的同伴，然後看看你喜歡哪些。那麼，去找一頭大型峭壁野豬，然後使用馴獸棒馴服它吧。', '使用馴獸棒馴服大型峭壁野豬。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。', '馴服一隻大型峭壁野豬', '去找丹莫洛的格瑞夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6065, 'zhTW', '獵人之道', '你好，年輕的獵人。看起來你已經準備好要馴服一頭野獸，並將其訓練成自己的同伴了。$B$B你必須去見一見血蹄村的雅文·刺鬃，他可以幫助你馴服自己的第一頭寵物。', '與血蹄村的雅文·刺鬃談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6066 AND `locale` = 'zhTW';
