INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6076, 'zhTW', '獵人之道', '你好，年輕的獵人。看起來你已經準備好要馴服一頭野獸，並將其訓練成自己的同伴了。$B$B你必須去見一見卡拉諾斯的格瑞夫，他可以幫助你馴服自己的第一頭寵物。', '與卡拉諾斯的格瑞夫談一談。', '', '', '', '', '', '', 0);
