INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6721, 'zhTW', '獵人之道', '你好，年輕的獵人。看起來你已經準備好要馴服一頭野獸，並將其訓練成自己的同伴了。你必須去見一見多蘭納爾的達札拉，他可以幫助你馴服自己的第一頭寵物。', '與多蘭納爾的達札拉談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6722, 'zhTW', '獵人之道', '你好，年輕的獵人。看起來你已經準備好要馴服一頭野獸，並將其訓練成自己的同伴了。$B$B你必須去見一見多蘭納爾的達扎拉，他可以幫助你馴服自己的第一頭寵物。', '與多蘭納爾的達扎拉談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6741, 'zhTW', '取之於敵', '', '', '', '去找奧特蘭克山谷的鐵匠雷格薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6761, 'zhTW', '新的邊疆', '我已經讓我的助手瑪斯雷·馭熊者來處理月光林地求援的事宜了。去跟他談談吧——不要找我。$B$B不過我要給你一些……友好的建議。是我領導著大家走出了黑暗，不是月光林地的塞納里奧議會。我們曾經陷入了一無所有的困境，但是泰達希爾給了我們新的生命！他們會努力讓你相信他們那套鬼扯，如果你真的相信了他們，那你無疑是個蠢貨。$B$B你自己來決定是不是要當一個傻瓜吧。', '與達納蘇斯的塞納里奧區的瑪斯雷·馭熊者談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6762, 'zhTW', '拉比恩·薩圖納', '這個任務的內容是這樣的，守護者雷姆洛斯在月光林地的總管——拉比恩·薩圖納——正在徵集願意去探索塔納利斯沙漠以及安戈洛環形山地區的冒險者，他就住在月光林地的永夜港裡。$B$B雖然你的工作會對我們都有好處，但是我建議你仍然要小心行事，達納蘇斯和月光林地之間的關係最近有些緊張……而且可能會越來越緊張。', '與月光林地永夜港的拉比恩·薩圖納談一談。月光林地在費伍德森林和冬泉谷之間，可以從木喉要塞中的一條通道抵達那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6781, 'zhTW', '護甲碎片', '', '', '', '去找奧特蘭克山谷的莫高特·深爐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6801, 'zhTW', '冰雪之王洛克霍拉', '', '', '', '去找奧特蘭克山谷的指揮官瑟魯加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6804, 'zhTW', '被囚禁的水元素', '一支水元素偵查部隊被派往羅德隆的東瘟疫之地，但是那裡的瘟疫把它們感染並扭曲了。我們水元素不允許這樣的事情破壞我們的純潔性！$B$B拿上這個瓶子，它裡面裝著的是海神之水。如果將它用在被感染的水元素身上，海神之水就會和它們身體中的毒素抗爭，並治癒它們！但是水元素體內發生的爭鬥也會使它們變得非常瘋狂。$B$B打敗這些瘋狂的水元素，然後把它們的縛靈護腕交給我。', '對東瘟疫之地的被感染的水元素使用海神之水。把12副不諧腕索和海神之水交給艾薩拉的海達克西斯公爵。', '', '去艾薩拉找風暴海灣的海達克西斯公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6805, 'zhTW', '雷暴和磐石', '我們水元素一直在與其它下等的元素生物交戰。如果你在這場紛爭中站在我們這一邊，就拿出點證明來！$B$B在最南端的希利蘇斯沙漠，空氣元素和地元素的僕從聚集在一處被稱作水晶谷的地方。它們保衛著某些強大的物品，不讓你們這些凡人接觸它們。儘管我不知道那些元素生物為什麼要這樣做，但我希望挫敗他們。$B$B到希利蘇斯的水晶谷去，擊敗我們的敵人，然後回到我這兒來。', '殺死15個灰塵風暴和15個沙漠奔行者，然後回到艾薩拉的海達克西斯公爵那兒。', '', '去艾薩拉找風暴海灣的海達克西斯公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6821, 'zhTW', '艾博希爾之眼', '你已經證明了自己可以擊敗我們的敵人，並能為水元素執行更為艱鉅的任務。但是到目前為止，你所面對的敵人並不算強大……如果面對強敵，你還能獲勝嗎？$B$B這就是你的新任務。$B$B獸人在黑石塔的高處捕獲了一個火焰元素的僕從——烈焰衛士艾博希爾。找到關押他的地方，殺死看守著他的獸人，然後殺死艾博希爾。把他的眼珠交給我，以此來證明你的價值。', '將艾博希爾之眼交給艾薩拉的海達克西斯公爵。', '', '去艾薩拉找風暴海灣的海達克西斯公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6822, 'zhTW', '熔火之心', '$n，也許現在已經到了派給你一項真正的考驗的時候了。你準備好了嗎？$B$B在黑石深淵的底部有一條通往熔火之心的小徑。那裡是我們死敵的要塞，由這個世上最強大的火焰奴僕把守著。$B$B到熔火之心去，$N。讓我看到你擁有足以打敗他們的力量和意志。$B$B如果你有朋友和盟軍，就召集他們。沒有一支強大的軍隊，就別想進入熔火之心並活著出來。', '殺死一個火焰之王、一個熔岩巨人、一個上古熔核犬和一個熔岩奔騰者，然後回到艾薩拉的海達克西斯公爵那裡。', '', '去艾薩拉找風暴海灣的海達克西斯公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6823, 'zhTW', '海達克西斯的使者', '如果你真的想要與我們結盟，那我邀請你對我們的敵人——空氣元素、土元素和火元素——發動戰爭。每殺死他們的一個成員，都會削弱他們在這個世界上的勢力，並進一步證明你對我們事業的忠誠。$B$B這場戰役肯定會持續很長時間，但是如果你堅持下去，那麼你就將得到至高的榮譽。', '在海達希亞水元素中達到被尊敬的聲望，然後與艾薩拉的海達克西斯公爵談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6824 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6824, 'zhTW', '敵人之手', '$N，你的貢獻對我們來說是無價的，我們不願意損失你這樣一個有用的人才，但是為了最後一個任務，也只能勉強為之了。$B$B如果你成功了，戰爭的天平將朝著對我們有利的方向發展……它值得你為之冒險。$B$B我們要將盤踞在熔火之心的幾個火元素的頭目幹掉：魯西弗隆，薩弗隆，基赫納斯和沙斯拉爾。殺了他們，把他們的手給我拿來！$B$B這項任務需要你盡全力而為之，$N，如果你能夠成功的話，火元素將遭受重大的打擊。', '將魯西弗隆之手、薩弗隆之手、基赫納斯之手和沙斯拉爾之手交給艾薩拉的海達克西斯公爵。', '', '去艾薩拉找風暴海灣的海達克西斯公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6825 AND `locale` = 'zhTW';
