INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6847, 'zhTW', '雷爾松的全視之眼', '你們在奧特萊克山脈大舉交戰對辛迪加來說沒什麼意義，$C。我們會按照慣例來做，等待時機，直到看見你們分出勝負，然後趁勢發起攻擊。但是，那並不是我們現在留在這裡的原因。我的全視之眼不見了，它被這裡的冰斧食人妖給拿走了。找到全視之眼，然後我們就會為你效力——直到分出勝負。當你拿到全視之眼後就回到我這裡來，然後我就可以好好看看你了。<指揮官雷爾松咧嘴笑著。>', '從冰斧食人妖洞穴中找到雷爾松的全視之眼，然後回到指揮官雷爾松那裡。要當心，據說雷爾松的全視之眼帶有可怕的詛咒！', '找回雷爾松的全視之眼', '去找奧特蘭克山谷的辛迪加指揮官雷爾松。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6848, 'zhTW', '雷爾松的全視之眼', '你們在奧特萊克山脈大舉交戰對辛迪加來說沒什麼意義，$C。我們會按照慣例來做，等待時機，直到看見你們分出勝負，然後趁勢發起攻擊。但是，那並不是我們現在留在這裡的原因。我的全視之眼不見了，它被這裡的冰斧食人妖給拿走了。找到全視之眼，然後我們就會為你效力——直到分出勝負。當你拿到全視之眼後就回到我這裡來，然後我就可以好好看看你了。<指揮官雷爾松咧嘴笑著。>', '從冰斧食人妖洞穴中找到雷爾松的全視之眼，然後回到指揮官雷爾松那裡。要當心，據說雷爾松的全視之眼帶有可怕的詛咒！', '找回雷爾松的全視之眼', '去找奧特蘭克山谷的辛迪加指揮官雷爾松。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6861, 'zhTW', '斯菲萊克斯的可攜式伐木機', '我和你一樣焦急地想要試一下我的可攜式伐木機，$c，但是我必須要弄到一些材料——我是說很多材料——才能製作出配套的工具！$B$B實際上，我需要像山那麼大的一堆瑟銀、秘銀和鐵，另外每一臺伐木機還需要有一個蒸汽鋸才能完工，你最好到伐木場去找找看。$B$B我在這裡遊蕩的時候（在我被抓住之前），曾在雷矛伐木場裡看到很多的蒸汽鋸。', '工程大師斯菲萊克斯要你給他拿去下列物品：$B$B30塊瑟銀錠。$B$B50塊秘銀錠。$B$B75塊鐵錠。$B$B1個蒸汽鋸。', '', '去找奧特蘭克山谷的工程大師斯菲萊克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6862, 'zhTW', '斯菲萊克斯的可攜式伐木機', '我和你一樣焦急地想要試一下我的可攜式伐木機，$c，但是我必須要弄到一些材料——我是說很多材料——才能製作出配套的工具！$B$B實際上，我需要像山那麼大的一堆瑟銀、秘銀和鐵，另外每一臺伐木機還需要有一個蒸汽鋸才能完工，你最好到伐木場去找找看。$B$B我在這裡遊蕩的時候（在我被抓住之前），曾在雷矛伐木場裡看到很多的蒸汽鋸。', '工程大師斯菲萊克斯要你給他拿去下列物品：$B$B30塊瑟銀錠。$B$B50塊秘銀錠。$B$B75塊鐵錠。$B$B1個蒸汽鋸。', '', '去找奧特蘭克山谷的工程大師斯菲萊克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6881, 'zhTW', '森林之王伊弗斯', '', '', '', '去找奧特蘭克山谷的大德魯伊雷弗拉爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6901, 'zhTW', '開始攻擊！', '', '', '', '去找奧特蘭克山谷的突擊隊長加瑞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6921, 'zhTW', '廢墟之間', '暮光之錘已經進入了黑暗深淵中的月光神殿廢墟裡去了，他們的目標肯定是要強迫元素生物來對付我們。如果我們不及早採取對策的話，這個地區就將永遠被他們控制。$B$B到黑暗深淵去找到廢墟中的深淵之石，它應該在靠近水邊的地方。深淵之石裡面是深淵之核——那裡面記載了所有元素生物的歷史。如果我擁有了它，我和陶土議會就能阻止他們了！', '把深淵之核交給梣谷佐拉姆加前哨站裡的耶努薩克雷。', '', '去梣谷找佐拉姆加前哨站的耶努薩克雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6922, 'zhTW', '阿奎尼斯男爵', '被擊敗的水元素留下了一個奇怪的水球，你猜想這東西可能是為水元素提供能量的。一股看起來就很噁心的水流在球體內翻騰噴濺，而球體本身似乎不受任何自然力的影響。$B$B如果說有人能對這個東西有所瞭解，那就只能是陶土議會的耶努薩克雷了。他就在梣谷的佐拉姆加前哨站裡。', '把奇怪的水球交給梣谷佐拉姆加前哨站的耶努薩克雷。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6941 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6941, 'zhTW', '天空的召喚 - 維波里的空軍', '', '你必須去對付守衛前線的部落精英士兵！我現在命令你去削弱那些綠皮蠻子的力量，把他們的中尉和軍團士兵的勳章給我拿來。當我拿到足夠的勳章時，我會命令開始對他們進行空中打擊的。', '', '去找奧特蘭克山谷的空軍指揮官維波里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6942 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6942, 'zhTW', '天空的召喚 - 斯里多爾的空軍', '', '我的獅鷲獸應該在前線作戰，但是在那裡的敵人被削弱之前，它們是無法發動攻擊的。部落的戰士胸前掛著代表榮譽的勳章勇猛衝鋒，而你要做的就是從他們腐爛的屍體上把勳章拿下來，並把它們交給我。只要敵人在前線的力量受到足夠的打擊，我就會發出命令進行空襲！我們將從空中給敵人造成致命的創傷！', '', '去找奧特蘭克山谷的空軍指揮官斯里多爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6943, 'zhTW', '天空的召喚 - 艾克曼的空軍', '', '它們的士氣很低，戰士。自從我們上次對部落的空中打擊失敗之後，它們就拒絕再次飛行！你必須鼓舞它們的士氣。回到戰場並攻擊部落的核心力量，殺死他們的指揮官和衛兵。盡可能帶回更多的勳章！我向你保證，當我的獅鷲獸看到這些戰利品並嗅到敵人的鮮血時，它們就會再次起飛！現在就出發吧！', '', '去找奧特蘭克山谷的空軍指揮官艾克曼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6961, 'zhTW', '冬天爺爺在這裡！', '冬幕節快樂，我的朋友！你一定要去冬天爺爺打個招呼！如果你今年表現的不錯的話，你會在冬幕節那天收到一份很棒的禮物。你一定要告訴冬天爺爺你今年想要什麼！另外，記得多買些好東西來給那些今年表現得好的人。我們這裡貨物齊全。各種貨物一應俱全——這是燻木牧場精心為您準備的貨物！', '和冬天爺爺談談；他在奧格瑪燻木牧場商人區旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6962, 'zhTW', '招待冬天爺爺', '嘿，你能幫冬天爺爺一個忙嗎，小$g男孩:女孩;？$B$B不用我說你也看得出來，冬天爺爺一天到晚都在這裡忙碌，所以他想吃些東西。一些薑餅搭配一杯冰牛奶將會非常正點 。你是冬天爺爺的朋友吧，可以帶些給我嗎？', '把5塊薑餅和一杯冰牛奶帶給奧格瑪的冬天爺爺。', '', '去找奧格瑪的冬天爺爺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6963, 'zhTW', '被偷的冬幕節', '聽著……並不是我們的神奇力量不夠，但是燻木牧場需要一些幫助——一種你們這些冒險者知道該如何給予的幫助。我們遺失了一批為了這個季節而儲存的貨物，而且現在連我們派去找這批貨物的燻木牧場特派員也不見了！拜託——最後一次出見那批貨是在奧特蘭克山脈，我們的人也是到那裡去了。請你去那裡看看人跟貨是不是都在那裡，是否一切安好！', '去奧特蘭克山脈的雪地找到失蹤的燻木牧場調查員。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6964, 'zhTW', '冬幕節的意義', '禮物，款待，獎品……我要說，呸！那些哥布林玷污了這個季節的真正意義——冬幕節。這是個萬物復甦的時刻，整個大地安靜的覆蓋在冬天爺爺所帶來的薄雪之下，冬天爺爺可不是那個穿著紅色外套的笨蛋！如果你想要瞭解更多關於冬幕節的事情，就去問問薩格尼吧。它肯定會因為有人對禮物不感興趣而是對冬幕節的歷史感興趣而感到驚奇的。', '和奧格瑪智慧谷裡的薩格尼談談關於冬幕節的事情。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6981, 'zhTW', '發光的裂片', '這塊裂片透出異樣的綠色光芒，雖然它完全是一塊固體，但是卻讓人感覺好像有一股煙從裂片中冒出來。你情不自禁地注視著這塊水晶的深處，這時你突然覺得這其中必定包含著許多曲折的故事。$B$B也許你應該去棘齒城看看那裡有沒有人知道這塊裂片的來歷。', '前往棘齒城尋找一個人，他能告訴你更多關於發光裂片的事。然後，將裂片送往被指示的地方。', '找人談談發光裂片的事情', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6982, 'zhTW', '冷齒礦坑補給品', '冷齒礦坑是部落的物資儲存點。他們的軍糧實在不是我們能吃下去的東西，但是他們的武器和護甲卻很棒！在眼下這種物資十分短缺的時候，我們要利用一切可以利用的東西！$B$B進入冷齒礦坑，幫我把他們的補給品拿回來。那些補給品可以幫助聯盟保持戰鬥力，同時也削弱了部落。$B$B祝你好運，$N。那座礦坑在南邊很遠的地方，就在部落領地的深處。', '把10份冷齒礦坑補給品交給丹巴達爾的聯盟軍需官。', '', '去奧特蘭克山谷找丹巴達爾的雷矛軍需官。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6983, 'zhTW', '天寒地凍', '一個叫做「可惡的格林奇」的生-生-生物偷走了我們的貨-貨-貨物，$N。小-小-小心！$B$B如果你要-要-要面-面-面對他的話。我看見他總是在雪-雪-雪怪出沒的地方晃-晃-晃悠；他一-一-一定在那-那-那裡！找-找-找到我們的貨物，$N，把他帶回-回-回給奧格瑪的燻木牧場，並告-告-告訴他們我需-需-需要解凍！', '找到並把被偷走的禮品帶給奧格瑪的凱瑪德·考伯賓奇。它被可惡的格林奇拿走了，去奧特蘭克雪地中去找它。', '', '去找奧格瑪的凱瑪德·考伯賓奇。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 6985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (6985, 'zhTW', '深鐵礦坑補給品', '雷矛部族的矮人把深鐵礦坑作為儲藏物資的地方。我要派你去那個礦坑裡，把裡面的補給品給我拿回來。這樣不但可以削弱雷矛部族在奧特蘭克山谷的勢力，還可以給我們提供必需的物資！$B$B小心一點，$N。深鐵礦坑在聯盟的控制下，如果我們能控制那座礦坑，那麼整個奧特蘭克山谷就會被我們牢牢掌握。', '把10份深鐵礦坑補給品交給霜狼要塞的部落軍需官。', '', '去奧特蘭克山谷找霜狼要塞的霜狼軍需官。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7001, 'zhTW', '補充坐騎', '奧特蘭克山谷中的戰爭在不斷消耗我們的軍力，因此我們必須不斷補充新的力量！$B$B如果我們可以找到更多的坐騎，狼騎兵部隊就能再一次投入戰鬥之中。$B$B拿上這根韁繩，去追蹤附近森林中的霜狼。一旦你找到了霜狼，就對它使用韁繩以馴服它。把馴服的霜狼帶回我這裡來，這樣我就可以把它編入騎兵部隊了。$B$B當我們擁有足夠的坐騎之後，狼騎兵就會再一次衝鋒陷陣！', '找到奧特蘭克山谷中的霜狼。使用霜狼口套來馴服它們。被馴服的霜狼會跟隨你回到獸欄管理員那裡，然後與獸欄管理員談話以獲得你的獎勵。', '馴服並上繳霜狼', '去找奧特蘭克山谷的霜狼獸欄管理員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7002, 'zhTW', '羊皮座具', '', '在我們的一些<class>幫助獸欄管理員捕捉巨狼的同時，其他人還需要去找一些將它們變成坐騎所必需的東西，比如韁繩和坐鞍。你必須去獵捕這個地區的山羊，也就是那些與雷矛騎兵的坐騎很相似的山羊！殺了它們，把它們的皮交給我。只要收集到足夠多的羊皮，我們就可以開始為騎手們製作坐具了。霜狼部族的狼騎兵很快就將再次馳騁在戰場上！', '', '去找奧特蘭克山谷的霜狼騎兵指揮官。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7003 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7003, 'zhTW', '被縮小的巨人', '如果我還想繼續在這裡混的話，就必須對那些巨人採取一些措施了！他們把我的生意搞得一團糟，難道不是嗎？$B$B眼下我正在實驗各種各樣的地精縮小射線，但是重點在於，我用尖端的哥布林科技強化了這種裝置！為了防止它可能對我自身造成的各種不良影響，比如死亡之類的，我希望你用它在菲拉斯的任何一種巨人身上試驗一下。在你把他們縮小之後，就可以從他們身上找到微縮殘渣——把那種東西拿來給我！', '使用索爾賓的超級壓縮器來縮小菲拉斯的任意種類的巨人，將他們縮小到更容易控制的體積。從縮小過的巨人身上收集15份微縮殘渣，把它們交給菲拉斯被遺忘的海岸碼頭的索爾賓·范達瑟。', '', '去菲拉斯的被遺忘的海岸找索爾賓·范達瑟。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7021, 'zhTW', '冬天爺爺在這裡！', '冬幕節快樂，我的朋友！你一定要去跟現在正在奧格瑪的冬天爺爺打個招呼！如果你今年表現的不錯的話，你會在冬幕節那天收到一份很棒的禮物。你一定要告訴冬天爺爺你今年想要什麼！另外，記得多買些好東西來給那些今年表現得好的人。我們這裡貨物齊全。各種貨物一應俱全——這是燻木牧場精心為您準備的貨物！', '和冬天爺爺談談；他在奧格瑪燻木牧場商人區旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7022, 'zhTW', '冬天爺爺在這裡！', '冬幕節快樂，我的朋友！你一定要去冬天爺爺打個招呼！如果你今年表現的不錯的話，你會在冬幕節那天收到一份很棒的禮物。你一定要告訴冬天爺爺你今年想要什麼！另外，記得多買些好東西來給那些今年表現得好的人。我們這裡貨物齊全。各種貨物一應俱全——這是燻木牧場精心為您準備的貨物！', '和冬天爺爺談談；他在鐵爐堡燻木牧場商人區旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7023, 'zhTW', '冬天爺爺在這裡！', '冬幕節快樂，我的朋友！你一定要去跟現在正在鐵爐堡的冬天爺爺打個招呼！如果你今年表現的不錯的話，你會在冬幕節那天收到一份很棒的禮物。你一定要告訴冬天爺爺你今年想要什麼！另外，記得多買些好東西來給那些今年表現得好的人。我們這裡貨物齊全。各種貨物一應俱全——這是燻木牧場精心為您準備的貨物！', '和冬天爺爺談談；他在鐵爐堡燻木牧場商人區旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7024, 'zhTW', '冬天爺爺在這裡！', '冬幕節快樂，我的朋友！你一定要去跟現在正在奧格瑪的冬天爺爺打個招呼！如果你今年表現的不錯的話，你會在冬幕節那天收到一份很棒的禮物。你一定要告訴冬天爺爺你今年想要什麼！另外，記得多買些好東西來給那些今年表現得好的人。我們這裡貨物齊全。各種貨物一應俱全——這是燻木牧場精心為您準備的貨物！', '和冬天爺爺談談；他在奧格瑪燻木牧場商人區旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7025 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7025, 'zhTW', '招待冬天爺爺', '嘿，你能幫冬天爺爺一個忙嗎，小$g男孩:女孩;?$B$B不用我說你也看得出來，冬天爺爺一天到晚都在這裡忙碌，所以他想吃些東西。一些薑餅搭配一杯冰牛奶將會非常正點 。你是冬天爺爺的朋友吧，可以帶些給我嗎?', '把5塊薑餅和一杯冰牛奶帶給鐵爐堡的冬天爺爺。', '', '去找丹莫羅的冬天爺爺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7026, 'zhTW', '山羊座具', '', '', '', '去找奧特蘭克山谷的雷矛山羊騎兵指揮官。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7027 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7027, 'zhTW', '補充坐騎', '看看這裡的獸欄，$N！空空如也！雷矛部族的騎兵部隊沒有坐騎——它已經名存實亡了。$B$B你必須幫助我們，士兵。拿著這根項圈，到山谷中去尋找四處徘徊的奧特蘭克山羊，並使用訓練項圈來抓住它們。當你抓住山羊之後，就把它給我帶回來，然後我就可以將它配備給騎兵部隊了。$B$B當我們有足夠的山羊之後，山羊騎兵將再次準備就緒。有了你的幫助，騎兵部隊將會獲得重生！', '找到奧特蘭克山谷中的山羊。使用雷矛訓練項圈來馴服它們。被馴服的山羊會跟隨你回到獸欄管理員那裡，然後與獸欄管理員談話以獲得你的獎勵。', '馴服並上繳山羊', '去奧特蘭克山谷找丹巴達爾的雷矛獸欄管理員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7028, 'zhTW', '扭曲的邪惡', '泰拉莫克水晶洞穴坐落在這裡的西邊，在瑪拉頓的深處……那裡是一處擁有悠久歷史的古蹟。我希望從那裡得到一些東西，$c。上古諸神的遺物就在那些巨門的後面。$B$B如果你願意挑戰潛伏在瑪拉頓裡的那些扭曲的邪惡力量，我一定會讓你為做出這個決定而感到滿意的。收集你所找到的瑟萊德絲水晶刻像，把它們交給我。$B$B一旦我拿到刻像，我就能……研究它們。刻像中蘊含的力量已經沉睡太久了……', '為淒涼之地的維洛收集15個瑟萊德絲水晶刻像。', '', '去找淒涼之地的維洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7029 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7029, 'zhTW', '維利塔恩的污染', '一個名叫維利塔恩的薩特正在玷污瑪拉頓的洞穴，使那裡的許多植物無法生長。$B$B拿著這個瓶子，$N。用洞穴裡面橘色水晶池中的水裝滿這個瓶子；瓶中所包含的物質可以中和毒藥，將它變成一種治療藥劑。$B$B你可以在橘色的洞穴中找到維利斯塔姆藤蔓，然後對它們使用淨化過的液體。這樣，附著在植物上的墮落物質就會被淨化，但是你要知道維利塔恩仍然控制著這些植物。他會利用它來對付你……', '在瑪拉頓裡用天藍水瓶在橘色水晶池中裝滿水。$B$B在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。$B$B治療8株植物並殺死那些諾克賽恩幼體，然後向葬影村的瓦克·戰痕覆命。', '', '去淒涼之地找葬影村的瓦克·戰痕。', '治療維利斯塔姆藤蔓', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7041, 'zhTW', '維利塔恩的污染', '一個名叫維利塔恩的薩特正在玷污瑪拉頓的洞穴，阻止那裡許多植物的生長。$B$B拿著這個瓶子，$N。用洞穴裡面橘色水晶池中的水裝滿這個瓶子；這瓶子裡所包含的物質能夠中和其中的毒藥，將其變成一種治療藥劑。$B$B你可以在橘色的洞穴找到維利斯塔姆藤蔓，然後對它們使用淨化過的液體。然後植物上的墮落的物質也會被淨化，但是你要知道維利塔恩仍然控制著這些植物。他會利用它來對付你……', '在瑪拉頓裡用天藍水瓶在橘色水晶池中裝滿水。$B$B在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。$B$B治療8株植物並殺死那些諾克賽恩幼體，然後向尼耶爾前哨站的塔琳德莉亞覆命。', '', '去淒涼之地找尼耶爾前哨站的塔琳德莉亞。', '治療維利斯塔姆藤蔓', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7042 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7042, 'zhTW', '被偷走的冬幕節禮物', '聽著……我不想破壞了節日的美好氣氛，但是燻木牧場需要幫助——需要你這樣的冒險家。$B$B我們弄丟了節日所需的重要禮品，現在連我們派去尋找禮品的燻木牧場密探也不見了！請幫幫忙——禮品是在奧特蘭克山脈附近丟失的，我們派出的密探也在那兒。$B$B看看禮品和密探是否都安然無恙吧！', '前往奧特蘭克山脈雪域尋找失蹤的燻木牧場密探。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7043 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7043, 'zhTW', '你是個卑鄙的人……', '一個叫做「可惡的格林奇」的生-生-生物偷走了我們的貨-貨-貨物，$N。但是要小-小-小心！就-就-就是他把我變成了一團雪-雪-雪人的！$B$B如果你要-要-要面-面-面對他的話，你可-可-可能需要一點幫助。我看見他總是在雪-雪-雪怪出沒的地方晃-晃-晃悠；他一-一-一定在那-那-那裡！找-找-找到我們的貨物，$N，把貨物帶回-回-回給鐵爐堡的燻木牧場，並告-告-告訴他們我需-需-需要解凍！', '找到並把被偷走的禮品帶給鐵爐堡的烏爾莫特。它被可惡的格林奇拿走了，去奧特蘭克山脈的雪地中去找它。', '', '去找鐵爐堡的烏爾莫特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7044 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7044, 'zhTW', '瑪拉頓的傳說', '一個名叫維利塔恩領主的黑暗薩特在這些蜿蜒曲折的洞穴中散播著他的邪惡力量。他住在有著紫色水晶的入口那邊。$B$B維利塔恩還創造了一個名叫諾克賽恩的墮落生物，讓它把守在有著橙色水晶的入口那邊。他們偷取了我兄弟的節杖。塞雷布拉斯，我的兄弟……他在洞中毫無目的地遊蕩，被墮落的力量所詛咒。$B$B你必須幫助他！找到節杖的兩個部分，然後……想辦法和我兄弟談談。', '找回塞雷布拉斯節杖的兩個部分：塞雷布拉斯魔棒和塞雷布拉斯鑽石。$B$B然後設法和塞雷布拉斯對話。', '', '去找瑪拉頓的塞雷布拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7046 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7046, 'zhTW', '塞雷布拉斯節杖', '我的權杖是我希望的源泉。它的力量可以讓我自由穿梭於這些洞穴中。我希望能夠讓我叔叔的靈魂得到安寧……這是我要交給你的任務。$B$B為了讓這兩個部分再次結合起來，我需要你的協助來完成儀式。請跟著我，聽從我的指示行動，然後我就會重新把鑽石鑲到節杖上。$B$B讓我們一起把塞雷布拉斯節杖重新組合起來！', '幫助贖罪的塞雷布拉斯製作塞雷布拉斯節杖。$B$B當儀式完成之後再和他談談。', '製造塞雷布拉斯節杖', '去找瑪拉頓的塞雷布拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7061, 'zhTW', '冬幕節', '這兒 - 若你有興趣對冬幕節了解更多的話，可以閱讀這本書。當我認為我們對於確認這個傳說的行為是適當的同時，我也受夠了學者把珍貴的資訊都搜括到一個地方的行為。$B$B當你完成了以後，把這本書拿給凱恩·血蹄。我知道他若聽到有其他人關注著我們族人的傳說之時，他會感到有興趣的。', '請自由取閱那本「冬幕節」來學習更多關於這個節日的意義。當你看完這本書後，把它送去給雷霆崖的凱恩·血蹄。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7062, 'zhTW', '季節的由來', '禮物，款待，獎品……我要說，呸！那些哥布林玷污了這個季節的真正意義——冬幕節。這是個萬物復甦的時刻，整個大地安靜的覆蓋在冬天爺爺所帶來的薄雪之下，冬天爺爺可不是那個穿著紅色外套的笨蛋！如果你想要瞭解更多關於冬幕節的事情，就去問問探險者聯盟的史學家卡尼克吧。它肯定會因為有人對禮物不感興趣而是對冬幕節的歷史感興趣而感到驚奇的。', '跟鐵爐堡的探險者聯盟的史學家卡尼克詢問關於冬幕節的事情。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7063 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7063, 'zhTW', '冬幕節', '拿著 - 若你有興趣對冬幕節多點了解的話，可以閱讀這本書。當我認為我們對於確認這個傳說的行為是適當的同時，我也受夠了學者把珍貴的資訊都搜括到一個地方的行為。$B$B當你看完以後，把這本書拿給國王麥格尼·銅鬚。我知道他若聽到有其他人關注著更老的傳說之時，他會感到興趣的。', '請自由取閱那本「冬幕節」的書來學習更多關於這個節日的意義。當你看完這本書後，把它送去給鐵爐堡的國王麥格尼·銅鬚。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7064, 'zhTW', '大地的污染', '在瑪拉頓的深處居住著一個邪惡的混亂生物——瑟萊德絲公主，她是一個和上古諸神相關的地元素。很早以前，她和塞納留斯的長子札爾塔結合，他們的後代……被稱為半人馬。那些半人馬殺掉了札爾塔，並保留了他的遺體。我的任務是徵召足夠強大的冒險者去殺死瑟萊德絲，這樣我們就可以在回到石爪山之前找到札爾塔的遺體了。', '殺死瑟萊德絲公主，然後回到淒涼之地葬影村附近的瑟琳德拉那裡覆命。', '', '去淒涼之地找薩瑟里斯海岸的瑟琳德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7065, 'zhTW', '大地的污染', '在瑪拉頓的深處居住著一個邪惡的混亂生物——瑟萊德絲公主，她是一個和上古諸神相關的地元素。很早以前，她和塞納留斯的長子札爾塔結合，他們的後代……被稱為半人馬。那些半人馬殺掉了札爾塔，並保留了他的遺體。我的任務是徵召足夠強大的冒險者去殺死瑟萊德絲，這樣我們就可以在回到石爪山之前找到札爾塔的遺體了。', '殺死瑟萊德絲公主，然後回到淒涼之地尼耶爾前哨站的守護者瑪蘭迪斯那裡覆命。', '', '去找淒涼之地的守護者瑪蘭迪斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7066, 'zhTW', '生命之種', '這些私生的半人馬——我的兒子和女兒——需要他們的父親。$B$B看看你的周圍——這個地方遍佈著希望，遍佈著我父親塞納留斯夢想中的寧靜。它們在從我的體內源源不斷地湧出來！我不能剝奪他們享受這一切的權利……即便他們對我犯下了深重的罪惡。$B$B但是我有一件事情需要請你幫助，以便讓我兄弟的心靈得到撫慰。拿著這個……這是我的遺體孕育出來的第一顆種子。告訴他，我的靈魂還在這裡，我還在繼續活著。我相信他可以理解我。', '到月光林地去找到雷姆洛斯，將生命之種交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7067 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7067, 'zhTW', '賤民的指引', '雖然我被當作異教徒流放了，但我的信仰還是一如既往——它將永遠激勵我前進。為了完成我的使命，我不得不借助外來者的力量……而不是我的半人馬同胞們。這真可悲。$B$B這個任務需要深入神聖的瑪拉頓——那座墳墓被我的同胞保護著，只有最為虔誠的半人馬才能進入。$B$B如果你願意幫助我，只需點點頭就行了。我會給你一塊羊皮紙，上面寫著具體的指示。閱讀那塊羊皮紙然後考慮一下我的話。', '閱讀賤民的指引，然後從瑪拉頓得到聯合墜飾，將其交給淒涼之地南部的半人馬賤民。', '', '去淒涼之地找瑪諾洛克集會所的半人馬賤民。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7068 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7068, 'zhTW', '裂影碎片', '在半人馬的聖地瑪拉頓中有著強大的魔法，淒涼之地的半人馬用他們的生命來保衛那個地方，但他們無法阻止我們拿走我們想要的東西。$B$B你現在要去一趟瑪拉頓，尋找那些由裂影碎片組成的石頭生物。如果你把那種紫色的水晶交給我，那麼尤塞爾奈就會為你付出的時間而獎勵你。$B$B那個地方很危險，也許你應該找一些朋友與你一同探險。', '從瑪拉頓收集10塊裂影碎片，然後把它們交給奧格瑪的尤塞爾奈。', '', '去找奧格瑪的尤塞爾奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7069 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7069, 'zhTW', '<UNUSED>', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7070 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7070, 'zhTW', '裂影碎片', '我最近開始測試不同的水晶和它們所具有的魔法特性。普勞德摩爾女士讓我徵集一些旅行者去淒涼之地尋找一處被稱作瑪拉頓的地方。在那座廢棄的廟宇中，巨大的元素生物帶有紫色的石頭，我把那種石頭稱為裂影。$B$B如果你決定去那裡的話，請幫我找些這種水晶回來，我會非常感謝你的。如果你需要的話，我甚至可以用它們製作一件飾物給你。', '從瑪拉頓收集10塊裂影碎片，然後把它們交給塵泥沼澤塞拉摩島上的大法師特沃許。', '', '去找塞拉摩島的大法師特沃許。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7081 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7081, 'zhTW', '奧特蘭克山谷的墓地', '奧特蘭克山谷中的墓地具有非常重要的戰略價值，部落和聯盟為爭奪這些神聖的土地瘋狂地廝殺，雙方都付出了慘重的代價。而你，$N，你做好加入戰鬥的準備了嗎？$B$B如果你想要知道一塊墓地是由哪一方控制的，只需觀察插在墓地上的旗幟就知道了。看到由部落佔領的墓地就把它攻打下來！一直殺到墓地中間去，拔出部落的旗幟。這樣一來，那片墓地就是我們的了！', '佔領一座墓地，然後向奧特蘭克山脈的諾雷格·雷矛中尉覆命。', '', '去奧特蘭克山脈找加文高地的杜爾根·雷矛。', '佔領墓地', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7082 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7082, 'zhTW', '奧特蘭克山谷的墓地', '奧特蘭克山谷中的戰鬥總是寸土必爭的。在殊死的拼殺中，我們和敵人所控制的區域在不斷地變化。而對墓地的爭奪則是最激烈的戰鬥，$N。$B$B為部落佔領一座墓地！找到插著聯盟戰旗的墓地，把他們的旗子拔掉。然後這座墓地就是我們的了！', '佔領一座墓地，然後向奧特蘭克山脈的提卡·血牙下士覆命。', '', '去找奧特蘭克山脈的提卡·血牙。', '佔領墓地', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7101, 'zhTW', '哨塔和碉堡', '哨塔和碉堡是非常重要的戰略設施，我們必須完全佔領它們！因此，我要求你去進攻被敵人佔領的哨塔和碉堡。$B$B想要佔領一座哨塔和碉堡，你就必須殺進去，將聯盟的旗幟拔掉，這樣部落的旗幟就會在那裡出現，然後大功告成！$B$B此時你就完成了我下達給你的任務，如果我們能夠佔據那些設施足夠長的時間，並且不被聯盟奪回去，那麼我們就可以控制那一帶了！', '佔領敵方的某座哨塔，然後向奧特蘭克山脈的提卡·血牙下士覆命。', '', '去找奧特蘭克山脈的提卡·血牙。', '佔領哨塔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7102, 'zhTW', '哨塔和碉堡', '哨塔和碉堡是非常重要的戰略設施，我們必須完全佔領它們！因此，我要求你去進攻被敵人佔領的哨塔和碉堡。$B$B想要佔領一座哨塔和碉堡，你就必須殺進去，將部落的旗幟拔掉，這樣聯盟的旗幟就會在那裡出現，然後大功告成！$B$B此時你就完成了我下達給你的任務，如果我們能夠佔據那些設施足夠長的時間，並且不被部落奪回去，那麼我們就可以控制那一帶了！', '摧毀敵方的某座哨塔或者碉堡中的旗幟，然後向奧特蘭克山脈的杜爾根·雷矛覆命。', '', '去奧特蘭克山脈找加文高地的杜爾根·雷矛。', '摧毀旗幟', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7121, 'zhTW', '軍需官', '$N，我們的軍需官讓我派新兵去他那裡報到。他需要奧特蘭克礦坑中的礦藏作為軍需之用，也許他會派你去採集它們。$B$B沿著這條路走，你可以在西邊找到軍需官。', '與雷矛軍需官談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7122, 'zhTW', '佔領礦坑', '奧特蘭克的這座礦坑蘊藏不僅僅是礦藏。部落和聯盟都在深鐵礦坑和冷齒礦坑中儲藏了大量的補給……如果我們能控制它們的話，那就太好不過了！$B$B佔領一座礦坑，然後回到我這裡來。想要佔領一個礦坑的話，你必須進入一個還未被我們控制的礦坑並殺死那裡的領袖。這樣礦坑就是我們的了，而我們也將派遣部隊來保護它！', '佔領一座還沒有被雷矛部族控制的礦坑，然後向丹巴達爾的雷矛軍需官覆命。', '', '去奧特蘭克山脈找加文高地的杜爾根·雷矛。', '佔領礦坑', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7123, 'zhTW', '霜狼軍需官', '$N，霜狼軍需官正在招募新兵，他需要派一些士兵深入奧特蘭克山谷的礦坑。去和他談談吧，他會告訴你更多的資訊。$B$B沿著西邊的路進入碉堡，然後從西邊的出口出去，你就可以找到軍需官了。', '與霜狼軍需官談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7124, 'zhTW', '佔領礦坑', '奧特蘭克山谷中戰事不斷升級，對冷齒礦坑和深鐵礦坑的爭奪也越來越激烈。豐富的礦藏和物資儲備吸引了雙方的勢力，它們的價值實在是太高了！$B$B請幫助我們的部隊，$N！為部落佔領一座礦坑！你必須進入一個仍未被我們控制的礦坑，然後幹掉其中的首領。當你完成這個目標之後，這座礦坑就是我們的了，而且我們會派遣部隊駐守其中！', '佔領一座礦坑，然後回去找奧特蘭克山脈的提卡·血牙下士。', '', '去找奧特蘭克山脈的提卡·血牙。', '佔領礦坑', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7141, 'zhTW', '奧特蘭克的戰鬥', '偵查人員報告說，在奧特蘭克山谷中隱藏著許多神器，但是霜狼氏族的獸人不會讓我們接近它們。我們不能讓部落阻止我們對於學術的追求！去幹掉他們的統帥，德雷克塔爾。只要他死了，那些獸人就會亂成一團。$B$B德雷克塔爾在奧特蘭克山谷南端的霜狼要塞中，把他除掉，然後回到我這裡來。', '進入奧特蘭克山谷，擊敗部落將軍德雷克塔爾。然後回到勘查員塔雷·石鎬那裡。', '擊敗德雷克塔爾。', '去找勘查員塔雷·石鎬。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7142, 'zhTW', '為奧特蘭克而戰', '雷矛氏族的矮人和他們的盟友正在入侵奧特蘭克山谷，我們必須和他們決一死戰！要想贏得這場戰鬥的勝利，我們就必須幹掉他們的統帥，範達爾·雷矛！$B$B你可以在北面的丹巴達爾要塞裡找到他，$B$B幹掉他，然後回來向我報告。', '進入奧特蘭克山谷，擊敗矮人將軍範達爾·雷矛。然後回到沃加·死爪那裡。', '擊敗範達爾·雷矛。', '去找奧特蘭克山脈的沃加·死爪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7161, 'zhTW', '試煉場', '你好，$c。經過如此長時間的等待，我們終於有機會響應戰鬥的召喚了。舊日的感覺正在慢慢恢復，我們又將熱血沸騰！$B$B所有新兵都必須完成氏族的試煉。$B$B在附近的蠻爪豺狼人山洞裡面有一面霜狼氏族的旗幟。去那裡拿回旗幟，然後把它還給我，我就將授予你霜狼新兵的徽記。', '到主基地東南邊的蠻爪洞穴中去找到霜狼軍旗，然後把它交給拉格隆德。', '', '去找奧特蘭克山脈的拉格隆德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7162 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7162, 'zhTW', '試煉場', '你來得真及時，$c。那些霜狼氏族的蠻子就是不願意放棄！我們要讓他們看看聯盟真正的力量，讓他們一潰千里。$B$B在你踏入戰場之前，你最好先透過雷矛部族的試煉。$B$B在丹巴達爾西南方的冰翼洞穴深處有一面雷矛部族的旗幟。到那裡去，把旗幟帶回來，然後把它交給我。這樣你就可以得到一枚雷矛部族新兵的徽記。', '到奧特蘭克山谷的丹巴達爾西南邊找到冰翼洞穴，並取得雷矛軍旗。然後把軍旗交給奧特蘭克山脈的哈格丁中尉。', '', '去希爾斯布萊德丘陵找達隆山的哈格丁中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7163 AND `locale` = 'zhTW';
