INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7172, 'zhTW', '命令之眼', '', '', '', '去找奧特蘭克山脈的哈格丁中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7181, 'zhTW', '科爾拉克的傳說', '雷矛部族並不是我們在這個地區唯一的威脅，士兵。我們在這座山谷中面對的是兩股敵人的攻擊——野蠻而原始的冰斧食人妖也在和我們進行爭鬥。$B$B它們的領袖是血怒者科爾拉克，一個殘酷而又狡猾的混蛋。$B$B如果能幹掉他，那對於整個冰斧食人妖族來說都會是一次致命的打擊。殺了科爾拉克，你就將獲得獎勵！', '據說強大的冰斧食人妖領袖會隨心所欲地出現，對奧特蘭克山谷的居民造成傷害。殺掉科爾拉克，然後向拉格隆德覆命。', '', '去找奧特蘭克山脈的拉格隆德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7201, 'zhTW', '最後的元素', '只有那些進入深淵的冒險者才能迎接這個挑戰，$N。$B$B黑鐵矮人已經掌握了製造強大的作戰魔像的方法。$B$B來自間諜的報告顯示，那些矮人使用某種獨特的能量源為他們所創造的魔像提供無與倫比的殺戮能力。$B$B如果我們能得到這種元素精華的話，我們的憎惡怪就可以得到極大的加強！把那座城市翻個底朝天也在所不惜，找不到精華你就別回來！我們給予的報酬值得你去冒這個險。', '到黑石深淵去取得10份元素精華。你應該在那些作戰魔像和魔像製造者身上找找，另外，薇薇安·拉格雷也提到了一些有關元素生物的話題……', '', '去荒蕪之地找卡加斯的暗法師薇薇安·拉格雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7202, 'zhTW', '血怒者科爾拉克', '這個地區的冰斧食人妖是個野蠻而原始的種族，他們只想把我們做成燉肉吃了。$B$B我們必須讓他們嚐嚐苦頭！$B$B從他們的洞穴找到的古書中詳細記述了他們的部族領袖權的傳承方式。那本古書中還寫到，它們現在的領袖——血怒者科爾拉克只有在需要顯身的時候才會出現。$B$B幹掉科爾拉克就能使冰斧部族滅亡！殺了他，然後回到我這裡來。', '血怒者科爾拉克躲在冰斧洞穴的深處。據說只有在第1001個冰斧食人妖被幹掉的時候，這個強大的冰斧食人妖領袖才會出現。$B$B到冰斧洞穴中去，殺掉所有擋在你面前的食人妖，直到科爾拉克出現為止。殺掉科爾拉克，然後向哈格丁中尉覆命。', '', '去希爾斯布萊德丘陵找達隆山的哈格丁中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7221, 'zhTW', '勘查員塔雷·石鎬', '啊，$N，你是來向我報到的？太好了，雷矛部族需要各方面的支援！$B$B和丹巴達爾的勘查員塔雷·石鎬談談吧，你可以在丹巴達爾兵營的最下層找到他。$B$B當你穿越丹巴達爾的時候多四處看看。對於一個勤勞的$c來說，根本不用擔心找不到事情做。', '與丹巴達爾兵營的勘查員塔雷·石鎬談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7222, 'zhTW', '沃加·死爪', '一個$c？太好了！我們很高興在奧特蘭克看到你，$N。無恥的矮人和他們的盟軍入侵了我們的山谷，我們歡迎所有部落的成員加入這場正義的戰鬥！$B$B去和沃加·死爪談談吧。他正在尋找足夠的人手來完成一項重要的任務，目標就是聯盟設立在奧特蘭克的城堡！$B$B你可以在霜狼要塞裡找到沃加。', '與霜狼要塞裡的沃加談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7223, 'zhTW', '護甲碎片', '戰爭在奧特蘭克山谷激烈地進行著，從鐵爐堡運來的物資不足以讓我們為部隊提供充足的補給。$B$B如果你能在戰場上找到護甲碎片，那麼就幫我帶一些回來吧！', '給丹巴達爾的莫高特·深爐帶去20塊護甲碎片。', '', '去奧特蘭克山谷找丹巴達爾的莫高特·深爐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7224, 'zhTW', '敵人的物資', '當你和敵人作戰的時候，收集他們護甲的碎片並把它們帶給我。我會用這些碎片來製作我們自己軍隊的護甲的！', '給霜狼村的鐵匠雷格薩帶去20塊護甲碎片。', '', '去奧特蘭克山谷找霜狼村的鐵匠雷格薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7241, 'zhTW', '保衛霜狼氏族', '戰鼓的轟鳴再次迴響在遙遠的土地上，$c。與酋長血脈相連的氏族正在被窮兇極惡的鐵爐堡雷矛氏族圍攻。$B$B我可以看出你很渴望戰鬥，並且願意幫助霜狼氏族。$B$B你必須馬上證明你的決心。$B$B你可以在希爾斯布萊德丘陵找到奧特蘭克山谷的入口。進入其中，找到拉格隆德。快點出發吧，$c，我們馬上要展開戰鬥了！', '到希爾斯布萊德丘陵地區的奧特蘭克山谷去。找到拉格隆德並和他談談，然後成為霜狼氏族的士兵。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7261, 'zhTW', '國王的命令', '我們正在奧特蘭克山谷進行一場血腥的戰鬥，矇昧的冰斧食人妖和野蠻的霜狼氏族從兩邊夾擊我們。以麥格尼·銅鬚陛下的名義，我們一定要把他們全都消滅掉！佔領那片土地，將敵人趕出去，這對於王國的穩定是非常重要的。$B$B啊，士兵可不是從樹上長出來的！向奧特蘭克的哈格丁中尉報告，在那裡加入雷矛氏族的軍隊，開始履行你光榮的職責吧。', '到希爾斯布萊德丘陵地區的奧特蘭克山谷去。到那裡之後，和哈格丁中尉談談。$B$B為了銅鬚的榮耀！', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7281, 'zhTW', '兄弟情深', '真是一個悲劇……我的兄弟居然在戰場上和我進行殊死搏殺：他是雷矛部族的指揮官。$B$B在雷矛部族的四個指揮官中，他無疑是最危險的。如果他被幹掉的話，那女妖之王就可以把他變成我這個樣子，讓他糾正自己錯誤的道路……$B$B你可以在敵方領地的深處找到我的兄弟。殺了他，然後回到我這裡來。我相信你有能力完成這個任務，士兵。$B$B還有，不要獨自行動。', '深入雷矛部族的領地，殺掉指揮官卡爾·菲力浦。任務完成之後向指揮官路易斯·菲力浦覆命。', '', '去找哨塔高地的指揮官路易斯·菲力浦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7282, 'zhTW', '兄弟情深', '他一定要擺脫他正在遭受的痛苦，士兵！他根本不知道自己在幹什麼，他已經成為了女妖之王的傀儡。$B$B現在就出發，穿過征戰平原，深入霜狼氏族的腹地。找到我的兄弟，殺掉他。這樣他的痛苦才能結束。', '深入霜狼氏族的領地，殺掉指揮官路易斯·菲力浦。任務完成之後，回到指揮官卡爾·菲力浦處覆命。', '', '去找奧特蘭克山谷的指揮官卡爾·菲力浦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7301, 'zhTW', '被捕的空軍指揮官', '我們的軍官被俘虜了，$r。我說的是那些空軍指揮官。我們在空中進行了一次激烈的交戰，但是他們不幸失敗了！更糟糕的是，我們最好的飛行員在反攻霜狼要塞過程中被射落了下來。你必須去找到他們。$B$B搜尋哨塔高地西側和霜狼要塞，那裡是他們最後出現過的地方——徹底搜尋這些地區！', '到霜狼氏族的領地中去搜尋空軍指揮官斯里多爾、空軍指揮官維波里和空軍指揮官艾克曼。任務完成之後向指揮官達菲覆命。', '', '去找奧特蘭克山谷的指揮官達菲。', '找到艾克曼', '找到維波里', '找到斯里多爾', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7302, 'zhTW', '被捕的空軍指揮官', '我們的空中支援現在處於困境之中，$N。空軍指揮官在敵人的領地中被射落，你必須找到他們，然後我們才可以開始營救行動！$B$B古斯最後一次飛行時曾出現在冰翼碉堡上空，傑斯托的雙足飛龍應該在雷矛伐木場附近。至於穆維裡克……那個笨蛋據說落在了丹巴達爾北部碉堡一帶。$B$B這是我這裡彙總的所有情報。趕快出發，徹底搜尋那些地區！', '找到空軍指揮官古斯、空軍指揮官傑斯托和空軍指揮官穆維裡克。任務完成之後向指揮官穆法特覆命。', '', '去奧特蘭克山谷找霜狼村的指揮官穆法特。', '找到古斯', '找到傑斯托', '找到穆維裡克', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7321, 'zhTW', '海龜湯', '誰說我們亡靈不懂烹飪？比如說我的秘密食譜海龜湯吧，很多部落成員千里迢迢慕名而來，只為品嚐一碗海龜湯！嘿嘿嘿……$B$B不過我最近一直都沒做過這種美食。我曾經從達拉然一直走到洛丹米爾湖去捕獵鉗嘴龜，不過眼下實在不是外出冒險的時候。如果你從東邊那條河裡弄點鉗嘴龜身上的海龜肉來給我，外加一份舒心草的話，我就能很快做出點海龜湯來讓你大飽口福。', '給塔倫米爾的克里斯托弗·傑弗寇特帶去10塊海龜肉和一些舒心草。', '', '去希爾斯布萊德丘陵找塔倫米爾的克里斯托弗·傑弗寇特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7341, 'zhTW', '公平交易', '', '', '', '去找艾薩拉的賞金獵人考拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7342, 'zhTW', '弓箭是給娘娘腔用的', '', '', '', '去找濕地的砲兵舍爾杜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7361, 'zhTW', '暗矛的青睞', '<納亞克咆哮著。>$B$B夜精靈的祖先是巨魔，有巨魔才有夜精靈。$B$B他們對於我們的攻擊是無法忍受的。鹿盔想要把我們全部幹掉——那麼就讓我們幹掉所有聽從他命令的蠢貨！他們決無可能達到他們的目的！$B$B你每殺掉一個夜精靈，納亞克都會代表暗矛部族對你表示感謝。你的事蹟將會在整個卡林多和東部王國傳播開來。現在就出發，為了暗矛部族而戰！', '你被指派去殺死奧特蘭克山谷中的夜精靈玩家。$B$B殺死一個夜精靈，然後把夜精靈的頭顱交給霜狼要塞的納亞克·海克森。', '', '去奧特蘭克山谷找霜狼村的納亞克·海克森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7362, 'zhTW', '牛頭人的盟友', '長者派我到這個戰場上來研究其他的種族。我在這裡最主要的任務就是對地精進行分析，瑪加薩對於他們的生存能力很感興趣。啊，那些地精——雖然他們看上去如此可憐而嬌小——但他們卻能迸發出今人驚訝的韌性。$B$B祝你好運，我一直以來都在找人幫我完成瑪加薩的任務。當你收集到地精的頭髮之後就把它交給我，這樣你就會被認為是牛頭人的盟友。', '你被指派去殺死奧特蘭克山谷中的地精玩家。$B$B殺死一個地精，然後把一束地精的頭髮交給霜狼要塞的拉瓦克·恐怖圖騰。', '', '去奧特蘭克山谷找霜狼村的拉瓦克·恐怖圖騰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7363, 'zhTW', '人類的病態', '人類是如此讓我感到憎惡。$B$B<指揮官菲利普咬牙切齒地說道。>$B$B雖然我是霜狼氏族的士兵，但我也是希爾瓦娜斯的僕人。$B$B我在幽暗城任職期間曾經幫助幽暗城的黑暗鍊金師進行過研究。$B$B我接到一個任務，需要收集人類的骨頭碎片，用它們來治療那些人類所殘存的人性。$B$B我被授權將這個任務下派給我的士兵。$B$B找到他們，殺死他們。把他們的骨頭交給我。', '你被指派去殺死奧特蘭克山谷中的人類玩家。$B$B殺死一個人類，然後把人類的骨頭交給指揮官劉易斯·菲利普（他一般出現在前線和霜狼要塞之間）。$B$B治療人類的藥劑唾手可得！', '', '去找哨塔高地的指揮官劉易斯·菲利普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7364, 'zhTW', '諾姆瑞根大通緝！', '大工匠親自派我來這片戰場上保衛我的地精兄弟和姐妹。我們聽說牛頭人正在磨刀霍霍地準備屠殺地精，最糟糕的是，他們居然拔掉死去地精的頭髮！這種殘暴的行為必須被阻止，我們必須以牙還牙！$B$B我要砍下他們的蹄子，$C。把他們的蹄子交給我，向我證明你是地精的盟友！', '你被指派去殺死奧特蘭克山谷中的牛頭人玩家。$B$B殺死一個牛頭人，然後把牛頭人的蹄子交給丹巴達爾的德爾克。', '', '去奧特蘭克山谷找丹巴達爾的德爾克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7365, 'zhTW', '鹿盔的輓歌', '範達爾·鹿盔已經給我下達了指令：戰場上的所有巨魔都必須被消滅。他們那關於夜精靈是他們後代的荒謬理論一定是他們嫉妒的結果，所以我們要用武力來回應他們。$B$B殺了他們，把他們的魔精給我拿來。', '你被指派去殺死奧特蘭克山谷中的巨魔玩家。$B$$殺死一個巨魔，將暗矛巨魔魔精交給丹巴達爾的亞斯拉瑪尼斯。', '', '去奧特蘭克山谷找丹巴達爾的亞斯拉瑪尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7366, 'zhTW', '大主教的仁慈', '大主教Ĥہ慈如同他的智慧一樣聞名於世。他居然對這樣一類邪惡的生物懷著同情心……$B$B<菲利浦懷疑地搖著頭。>$B$B他真是太仁慈了……太仁慈了。$B$B大主教說我們應該對亡靈保持同情心，並讓他們能夠儘快獲得真實而永恆的死亡。為了表現這樣的仁慈，我們需要他們黑色的、被疾病折磨的心臟。$B$B把被遺忘者的精華交給我，然後我們會在光明大教堂中把它們隆重地焚燒掉。快點行動，$N！', '你被指派去殺死奧特蘭克山谷中的被遺忘者玩家。$B$B殺死一個被遺忘者，然後把一枚被遺忘者的精華交給指揮官卡爾·菲利普（他一般在伐木場和礦井之間徘徊）。', '', '去找奧特蘭克山谷的指揮官卡爾·菲利普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7367, 'zhTW', '爆破專家', '霜狼部族在他們的前線和基地中都佈置了陷阱，$C。所以當你進入敵人領地的時候，必須多加小心。$B$B如果你想要放心大膽地攻擊他們的話，就得先摧毀這種針對單兵的防禦武器——我要你做的就是幹掉他們的爆破專家。如果你殺了他，就可以安全地拆除那些地雷。因為只要他被幹掉了，那些地雷也就變成了一堆廢物。$B$B你可以在冰血要塞附近的哨塔裡找到他。祝你好運！', '找到霜狼爆破專家並幹掉他。完成任務之後向雷矛爆破專家覆命。', '', '去找奧特蘭克山谷的聯盟爆破專家。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7368, 'zhTW', '爆破專家', '我對關於地雷的技術細節瞭如指掌，我負責將所有的地雷埋設在前線。$B$B如果你想要解除雷矛部族的地雷陣，你要做的就是幹掉對方的爆破專家。那個矮人懦夫無疑藏在征戰平原的第一座哨塔中。把他幹掉，聯盟就沒法再埋設地雷了。$B$B在你幹掉他之後，別忘了回到我這裡來通報一聲，你會得到獎勵的。', '找到雷矛爆破專家並幹掉他。完成任務之後向霜狼爆破專家覆命。', '', '去找奧特蘭克山谷的霜狼爆破專家。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7381, 'zhTW', '科爾拉克歸來', '雖然科爾拉克確實被幹掉了，但是還有一個問題：他是不是會一直保持死了的狀態？巨魔一向以來都以擅長妖術魔法而聲名狼藉，如果他們復活一個死去的領袖，並讓他重新執掌部族，那我絕對不會感到驚奇。$B$B你應該知道如果這種事情真的發生了的話，你該怎麼做。$B$B<拉格隆德用手指在自己的脖子上做了一個切割的動作。>$B$B這一次，我要他的腦袋。打起精神，士兵。$B$B解散！', '如果科爾拉克重新出現在奧特蘭克山谷的冰斧山洞中，就找到並幹掉他。$B$B將科爾拉克的顱骨交給霜狼要塞的拉格隆德。', '', '去找奧特蘭克山脈的拉格隆德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7382, 'zhTW', '永生的科爾拉克', '現在有一件緊急的事情……有沒有人想過要焚燒科爾拉克的屍體？那些巨魔一定會想法設法復活他們的領袖，你知道，那些藍皮膚的怪物經常會那麼做。$B$B你要小心了，$N。如果科爾拉克重新出現在你的面前，千萬不要驚慌失措。如果他真的復活了，那麼我要你把他幹掉，然後燒掉他的屍體。$B$B為了以防萬一，在焚燒屍體之前砍掉他的頭顱，然後把他的顱骨交給我。', '如果科爾拉克重新出現在奧特蘭克山谷的冰斧山洞中，就找到並幹掉他。$B$B將科爾拉克的顱骨交給丹巴達爾的哈格丁中尉。', '', '去希爾斯布萊德丘陵找達隆山的哈格丁中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7383, 'zhTW', '大地之冠', '然而泰達希爾並不是一切都盡如人意。范達爾·鹿盔對於世界之樹的計畫正如他自己所希望的那樣一步步展開了，但是還有一個小問題，這個問題或許會給泰達希爾帶來一些麻煩。$B$B不過我不打算介入此事。你得去一趟最後一口月井，就在這裡西北面的神諭林地裡，就在神諭之樹的樹幹下面，那是我們的第一口也是最強大的一口月井。在那裡灌一瓶水，然後回來向我報告。', '用月井的水裝滿紫水晶之瓶，然後把它交給多蘭納爾的科瑞薩斯·月怒。', '', '去泰達希爾找多蘭納爾的科瑞薩斯·月怒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7384, 'zhTW', '暫無內容', '給我一些鱗片。', '收集一些鱗片給在悲傷沼澤避難營的卡拉納。', '', '去悲傷沼澤找避難營的卡拉納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7385 AND `locale` = 'zhTW';
