INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7401, 'zhTW', '通緝：矮人！', '根據亞斯拉·血牙的命令，在戰場上遇到矮人的時候要格殺勿論。$B$B如果你在戰場上幹掉了矮人，就把他們的脊椎骨挖出來，留下那具血跡斑斑的屍體，警告所有膽敢冒犯霜狼氏族的蠢貨。$B$B把脊椎骨交給亞斯拉·血牙，以此來證明你的功勳。', '你被指派去殺死奧特蘭克山谷中的矮人玩家。$B$B殺掉一個矮人，然後把矮人的脊椎交給霜狼要塞的亞斯拉·血牙。', '', '去找奧特蘭克山谷的亞斯拉·血牙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7402 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7402, 'zhTW', '通緝：獸人！', '根據諾雷格·雷矛中尉的命令，所有雷矛部族的士兵都要殺掉$g他:她;在戰場上看到的每一個獸人。$B$B帶回獸人的獠牙來作為完成任務的證明。$B$B另外別忘了戴手套。', '你被指派去殺死奧特蘭克山谷中的獸人玩家。$B$B殺掉一個獸人，然後把獸人的獠牙交給丹巴達爾的諾雷格·雷矛中尉。', '', '去奧特蘭克山谷找丹巴達爾的諾雷格·雷矛中尉。', '', '', '', '', 0);
