INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7441, 'zhTW', '普希林和埃斯托爾迪', '我只是讓自己稍微鬆懈了一下，就釀成了大錯。在我匆匆逃離墮落王子的魔爪時，我被洗劫一空。一個名叫普希林的小鬼拿走了我的法術書，還有埃德薩拉斯大廳的鑰匙。$B$B我對鑰匙已經不再有興趣了，因為我已經以永生換來了自由，但是我一定要找回我的法術書。$B$B找到普希林，然後找回我的法術書。$B$B到厄運之槌的扭木廣場去找普希林吧。', '到厄運之槌去找到小鬼普希林。你可以使用任何手段從小鬼那裡得到埃斯托爾迪的咒術之書。$B$B找到咒術之書後，回到拉瑞斯小亭的埃斯托爾迪那裡。', '', '去找菲拉斯的埃斯托爾迪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7461, 'zhTW', '伊莫塔爾的瘋狂', '你難道還沒有聽夠嗎？你到底有沒有能力解決問題？$B$B這種瘋狂必須得到遏制，永生的歲月早已過去了。摧毀水晶塔周圍的守衛，削弱能量力場的保護作用，然後幹掉伊莫塔爾。此時王子的力量將被大大削弱，趁機解決他，讓這座城市中的靈魂得到安息，冒險者。', '你必須幹掉5座水晶塔周圍的守衛，那5座水晶塔維持著關押伊莫塔爾的監獄。一旦水晶塔的能量被削弱，伊莫塔爾周圍的能量力場就會消散。$B$B進入伊莫塔爾的監獄，幹掉站在中間的那個惡魔。最後，在圖書館挑戰托塞德林王子。$B$B當任務完成之後，到庭院中去找辛德拉古靈。', '', '去菲拉斯找厄運之槌的辛德拉古靈', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7462 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7462, 'zhTW', '辛德拉的寶藏', '你可以在圖書館的樓梯下方找到一隻古老的箱子，從中拿取你所需的東西吧。', '返回圖書館去找到辛德拉的寶藏。拿取你的獎勵吧！', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7463 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7463, 'zhTW', '久違的法師', '一個$r法師！這太讓我感到驚訝了。我已經有將近……現在是什麼時候？哦，已經有500年沒有看到過你這樣的法師了！$B$B我有些東西，你肯定會很感興趣，但是你必須先幫我完成一個任務。$B$B<萊德羅斯竊笑著。>$B$B在埃德薩拉斯發生了奇怪的事情，有個水元素出現在埃德薩拉斯的東側，它的出現簡直就是一場災難！$B$B到扭木廣場去，從它身上收集一瓶海多斯博恩的元素精華。把它拿回來交給我，然後我就可以教你一個非常有用的法術。', '到厄運之槌的扭木廣場去殺掉水元素海多斯博恩。把海多斯博恩精華交給圖書館的博學者萊德羅斯。', '', '去找厄運之槌的博學者萊德羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7481, 'zhTW', '精靈的傳說', '幾年前，一個名叫卡里爾·溫薩魯斯的精靈領主獨自帶著幾件上古精靈的神器逃離了他那飽經戰亂的家鄉。$B$B為了尋找這位失蹤的領主，我們離開了奎爾薩拉斯的廢墟，穿過燃燒平原以及廣闊的海洋，最終來到了菲拉斯。$B$B我們認為他就躲在埃德薩拉斯（現在被稱為厄運之槌）的大廳裡。$B$B你必須找到他，冒險者。無論他是死是活，我們必須拿回那些他所帶走的東西！', '到厄運之槌去尋找卡里爾·溫薩魯斯。向莫沙徹營地的先知科魯拉克報告你所找到的資訊。', '尋找卡里爾·溫薩魯斯', '去菲拉斯找莫沙徹營地的先知科魯拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7482, 'zhTW', '精靈的傳說', '幾年前，一個名叫卡里爾·溫薩魯斯的精靈領主獨自帶著幾件上古精靈的神器逃離了他那飽經戰亂的家鄉。$B$B為了尋找這位失蹤的領主，我們離開了奎爾薩拉斯的廢墟，穿過燃燒平原以及廣闊的海洋，最終來到了菲拉斯。$B$B我們認為他就躲在埃德薩拉斯（現在被稱為厄運之槌）的大廳裡。$B$B你必須找到他，冒險者。無論他是死是活，我們必須拿回那些他所帶走的東西！', '到厄運之槌去尋找卡里爾·溫薩魯斯。向羽月要塞的學者盧索恩·紋角報告你所找到的資訊。', '尋找卡里爾·溫薩魯斯', '去菲拉斯找羽月要塞的學者盧索恩·紋角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7483, 'zhTW', '急速聖典', '溫薩魯斯在這裡的東側遺失了急速聖典，那本聖典可以給你的裝備附加上少許的加速效果。那只是一個微不足道的小魔法，真的……$B$B不管怎麼樣，如果你感興趣的話，就去把聖典和一些基本材料給我帶來。$B$B嗯……你還需要準備一些英雄之血，一塊原始黑鑽石，外加一些大塊魔光碎片。當然我也有可能說得不完全正確！$B$B<萊德羅斯聳了聳肩膀。>', '將急速聖典、1塊原始黑鑽石、2份大塊魔光碎片和2份英雄之血交給厄運之槌的博學者萊德羅斯，以換取一份急速秘藥。', '', '去找厄運之槌的博學者萊德羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7484, 'zhTW', '專注聖典', '這本聖典幾乎令一個年輕的學者廢寢忘食。但是，幾個星期之後他就不再熱衷於此了。$B$B你們當中那些對魔法更有洞察力的$r會發現，這些東西是非常有趣的。$B$B專注聖典已經不見了，我相信是那些上層精靈的靈魂拿走了它。$B$B把聖典給我拿來，再準備一些大塊魔光碎片和暗影之皮，外加一塊原始黑鑽石，然後我就可以合成秘藥了。', '將專注聖典、1塊原始黑鑽石、4份大塊魔光碎片和2張暗影之皮交給厄運之槌的博學者萊德羅斯，以換取一份專注秘藥。', '', '去找厄運之槌的博學者萊德羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7485 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7485, 'zhTW', '防護聖典', '他因為遺失了聖典而像嬰孩一樣哭泣。告訴你吧，我自己也曾因為一些文字而哭泣——世界上沒有比知識和歷史化為烏有更大的損失了——但是為了這些幾乎無用的咒語而哭泣，這值得嗎？太荒謬了！這讓我相信王子把他殺掉對他來說反而是一種恩惠。$B$B把聖典交給我，還有一塊原始黑鑽石和一些大塊魔光碎片，外加一份磨損的憎惡縫合線，這樣我就可以幫你合成秘藥了。$B$B哦，你應該到北側去找那本聖典。', '將防護聖典、1塊原始黑鑽石、2份大塊魔光碎片和1份磨損的憎惡縫合線交給厄運之槌的博學者萊德羅斯，以換取一份防護秘藥。', '', '去找厄運之槌的博學者萊德羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7486, 'zhTW', '英雄的獎賞', '$N，你對於水元素的貢獻已經超出我們對於這個世界中的凡人所抱有的期望。$B$B我們不知道你們這些凡人如何對待這樣的貢獻，或者如何獎勵傑出的成就，但是這一次……也許我們應該給予你一些獎勵。$B$B在這座島南部的水下有一隻箱子。你可以在裡面找到你的……獎勵。$B$B去吧，$N。去拿取你的獎勵吧。', '從海達克西斯的箱子拿取你的獎勵。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7487, 'zhTW', '熔火之心的傳送門', '裂隙在翻滾，它撕裂並吞噬我們周圍所有的東西，$C。我所站立的地方旁邊的裂隙就是穿過黑石深淵直通火焰之王所在地的傳送門。$B$B你感到很驚奇嗎？真是遺憾……凡人總是無法領悟那些他們無法看到、觸控到或者感覺到的東西。$B$B我向你保證，這個傳送門可以到達熔火之心。$B$B你開始感興趣了嗎？其實這是很簡單的。進入熔火之心，獲得一塊熔核碎片，把它交給我，然後我就會將你的靈魂與傳送門進行同步。', '進入黑石深淵，在通往熔火之心的傳送門附近找到一塊熔核碎片，然後回到黑石山脈的洛索斯·天痕那裡', '', '去燃燒平原找黑石山的洛索斯·天痕。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7488, 'zhTW', '蕾瑟塔蒂絲的網', '蕾瑟塔蒂絲是一個邪惡的血精靈法師，她對魔法有著近乎變態的痴迷，而且殘忍無比，現在她逃進了厄運之槌中。蕾瑟塔蒂絲製造了一張可以收集魔法能量的網。我擔心如果不加以控制的話，她的力量將會足以摧毀整個世界！$B$B去阻止她，$N。找到她並拿回她的網。她應該在厄運之槌的扭木廣場中，就在那些薩特附近。把她的網交給我，讓我來把它的能量安全地釋放出來。', '把蕾瑟塔蒂絲的網交給菲拉斯羽月要塞的拉托尼庫斯·月矛。', '', '去菲拉斯找羽月要塞的拉托尼庫斯·月矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7489, 'zhTW', '蕾瑟塔蒂絲的網', '血精靈蕾瑟塔蒂絲已經瘋了，她極端飢渴著收集魔法的力量，這使她敢於挑戰她的同胞，並創造了一種危險的裝置，一張可以收集厄運之槌中的那些被汙染的魔法能量的網。現在她正在收集那些能量，並計劃將其用於對付她的敵人。$B$B我們必須阻止蕾瑟塔蒂絲。在厄運之槌的扭木廣場找到她，擊敗她，把她的網交給我，這樣我們也許可以把它交給那些頭腦比較冷靜的血精靈進行研究。', '把蕾瑟塔蒂絲的網交給非拉斯莫沙徹營地的塔羅·刺蹄。', '', '去菲拉斯找莫沙徹營地的塔羅·刺蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7490 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7490, 'zhTW', '部落的勝利', '你完成了一個幾乎不可能完成的任務。黑龍公主已經被你斬殺。拿下她的頭顱，把它交給你的酋長。', '將奧妮克希亞的頭顱交給奧格瑪的索爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7491 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7491, 'zhTW', '萬眾敬仰', '倫薩克霸主在力量谷等你。$B$B<索爾向你致敬。>$B$B不要讓你的民眾等得太久，英雄。', '在力量谷找到倫薩克霸主。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7492 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7492, 'zhTW', '莫沙徹營地', '菲拉斯的牛頭人長者塔羅·刺蹄派人送信請求幫助。他並沒有詳細述說詳情，但是他說他需要一個有著足夠的勇氣而且做事細緻的冒險者來幫助他。$B$B為了部落而戰，$N。到菲拉斯的莫沙徹營地去找塔羅談談吧。', '和菲拉斯莫沙徹營地的塔羅·刺蹄談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7493 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7493, 'zhTW', '一切才剛剛開始', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7494 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7494, 'zhTW', '羽月要塞', '$N！菲拉斯需要你的幫助！$B$B一個名叫蕾瑟塔蒂絲的流亡法師逃進了古代夜精靈的遺蹟——埃德薩拉斯，現在那裡被稱為厄運之槌。她手中有一件非常危險的魔法物品，我們一定要拿回它。$B$B拉托尼庫斯·月矛要求派遣強大的冒險者進入厄運之槌，從蕾瑟塔蒂絲手裡拿回那件東西。$B$B為了聯盟而戰！你可以在菲拉斯的羽月要塞中找到拉托尼庫斯。', '和菲拉斯羽月要塞的拉托尼庫斯·月矛談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7495 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7495, 'zhTW', '聯盟的勝利', '你完成了一個幾乎不可能完成的任務。黑龍公主已經被你斬殺。拿下她的頭顱，把它交給暴風城的大領主。', '將奧妮克希亞的頭顱交給暴風城的大領主伯瓦爾·弗塔根。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7496 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7496, 'zhTW', '英雄慶典', '到英雄谷去找到瑪丁雷少校，$N。他會在那裡等著你……', '在英雄谷找到瑪丁雷少校。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7497 AND `locale` = 'zhTW';
