INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7507, 'zhTW', '弗洛爾的屠龍技術綱要', '你找到了一些非常重要的東西。這本書和你看到過的其它的書不太一樣。$B$B某些人或者某些東西將圖書館的封印揭掉了，這本書中的文字十分混亂，根本無法辨識。', '將《弗洛爾的屠龍技術綱要》還回圖書館。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7508 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7508, 'zhTW', '鑄造奎爾塞拉', '如果你想要接手這個任務，那就把這把黯淡的精靈之刃交給萊德羅斯吧。', '把黯淡的精靈之刃交給博學者萊德羅斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7509 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7509, 'zhTW', '鑄造奎爾塞拉', '將未淬火的上古之刃拿到奧妮克希亞的巢穴中，並與她作戰。$B$B你需要使用一些技巧來加熱這把劍。在戰鬥中，奧妮克希亞一定會使用火焰的氣息來灼燒你。你應該將未淬火的上古之刃放在附近，並期望黑龍的火焰氣息會為這把劍加熱。如果你可以活著等到那個時候，就撿起加熱過的上古之刃，然後殺掉奧妮克希亞。$B$B將加熱過的上古之刃插入她的屍體中，這樣就可以完成它最後的鑄造儀式，並得到一把精製上古之刃。', '你必須設法讓奧妮克希亞對這把未淬火的上古之刃噴射火焰。完成之後，撿起加熱過的上古之刃。你要注意的是，加熱過的上古之刃不會一直保持被加熱的狀態，時間非常緊迫。$B$B在把它給我拿回來之前的最後一步是殺掉那條龍，並將加熱過的上古之刃插入她的屍體中。$B$B完成這些之後，奎爾塞拉就是你的了。', '', '去找厄運之槌的博學者萊德羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7521 AND `locale` = 'zhTW';
