INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7667, 'zhTW', '收集材料', '$N，這是一件我希望能得到你幫助的事情，一件重要的事情……請允許我解釋一下。$B$B在羅德隆的通靈學院中有一個被稱為屍骨儲藏所的房間。我要製造一個能夠洞穿那個房間中的邪惡力量的裝置，因此我需要兩塊鑽石：一塊艾澤拉斯鑽石和一塊原始黑鑽石。我知道這兩樣東西都不是那麼容易得到的，而且我自己沒有辦法得到。$B$B你能幫我拿來這兩樣東西嗎？', '如果你願意幫助奧格瑪智慧谷的薩格尼，就將一塊艾澤拉斯鑽石和一塊原始黑鑽石交給他。', '', '去找奧格瑪的薩格尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7668, 'zhTW', '達克雷爾的威脅', '死亡騎士達克雷爾掌管著通靈學院的屍骨儲藏所。他威脅要讓靈魂世界徹底扭曲，以達到自己的目的，我們必須阻止他！這就是你需要水晶球的原因。$B$B在屍骨儲藏所地下室的中心使用預言水晶球來召喚達克雷爾的靈魂爪牙。將那些靈魂擊敗，這時死亡騎士就會出現，$N，把他的頭顱交給我！只有他的死亡才能讓靈魂世界免受傷害！', '在通靈學院的屍骨儲藏所地下室中心使用預言水晶球，這樣將會召來一些靈魂，你必須與它們交戰。將這些靈魂擊敗，死亡騎士達克雷爾就會出現。$B$B擊敗達克雷爾，將他的頭顱交給奧格瑪智慧谷的薩格尼。', '', '去找奧格瑪的薩格尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7669 AND `locale` = 'zhTW';
