INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7670, 'zhTW', '格雷森·破影者領主', '這個偉大的時刻終於到來了，$N，接下來你就將獲得你渴望已久的東西——你的戰馬。$B$B去和暴風城教堂區的格雷森·破影者領主談談吧。他將指引你完成必需的任務，令你獲得一匹聖騎士最可信任的坐騎。$B$B我祝你在這次試煉中好運，為了聖光而戰，我的$g兄弟:姐妹;！', '與暴風城教堂區的格雷森·破影者領主談一談。', '', '', '', '', '', '', 0);
