INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7701, 'zhTW', '懸賞：監督者瑪托留斯', '監督者瑪托留斯原本是瑟銀兄弟會的潛行者密探，現在卻在熔渣之池中擔任黑鐵矮人的指揮官。根據監督者奧菲斯特的命令，殺死監督者瑪托留斯並將他的頭顱帶回來即可領取獎賞。$B$B請向偵查隊長洛洛爾領取獎勵。', '那個叫做監督者瑪托留斯的黑鐵矮人叛徒就藏在大熔爐的熔渣之池深處。$B$B殺死監督者瑪托留斯，將他的頭顱交給灼熱峽谷的偵查隊長洛洛爾以換取你的獎勵。', '', '去灼熱峽谷找瑟銀哨塔的偵查隊長洛洛爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7702 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7702, 'zhTW', '讓他們失眠！', '如果你想要破壞黑鐵矮人在熔渣之池的生產活動，就必須抓住其弱點給予致命一擊。$B$B眾所周知，矮人——特別是黑鐵矮人——需要休息！需要充足的休息！$B$B我問你，他們睡覺難道不用枕頭嗎？對，$N，他們不能沒有枕頭。你必須小心翼翼地潛入熔渣之池，偷走他們的枕頭。', '在大熔爐的熔渣之池深處，你可以發現黑鐵矮人的休息區。$B$B到休息區去偷走20只黑鐵枕頭。當你完成任務後就回到灼熱峽谷的艾沃奈斯那裡覆命。', '', '去灼熱峽谷找大熔爐的艾沃奈斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7703 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7703, 'zhTW', '戈多克巨魔的事務', '現在你是大王，你可以從那個精靈王子手裡拿回令戈多克驕傲的神器！你前一任的大王失敗了，自從托塞德林那個可惡的精靈從我們古代戈多克大王手中偷走它之後，沒有一個大王能想辦法把它奪回來！$B$B這個神器叫做戈多克力量護手。傳說說只有真正的戈多克大王才能把它拿回來。這個可惡的精靈還在附近——如果你找到它的話，那你就可以使用它！真的！', '找到戈多克力量護手，並將它交給厄運之槌的克羅卡斯。$B$B根據克羅卡斯所說的，“傳說”自稱是王子的精靈托塞德林從一名戈多克巨魔手中偷走了那件神器。', '', '去銀松森林找厄運之槌的克羅卡斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7704 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7704, 'zhTW', '看看它的個頭！', '嘖嘖……這難道不是個驚喜嗎？這實在就是個驚喜啊。比拉凱琳的巨大而精美的枕頭現在是你的囊中之物啦。艾沃奈斯肯定很想將她那髒兮兮的小手放在枕頭上。把枕頭交給她，看看她是否會獎勵你點什麼。', '將比拉凱琳的枕頭交給灼熱峽谷的艾沃奈斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7721, 'zhTW', '壓縮器的動力', '如果我想要在被遺忘的海岸這裡開一家可以正常經營的工程學商店，那我就必須先解決這些討厭的元素生物——它們簡直是無法無天！$B$B幸運的是，我發現這些元素生物身上有一種可以給我的超級壓縮器提供動力的理想材料——我希望你可以好好地教訓它們，拿到我要的東西！把它們身上的水元素核心給我拿來！', '從菲拉斯被遺忘的海岸那裡的海元素和巨型海元素身上獲取10塊水元素核心，把它們交給碼頭附近的索爾賓·範達瑟。', '', '去菲拉斯的被遺忘的海岸找索爾賓·範達瑟。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7722, 'zhTW', '絕密配方！', '當那個混賬瑪托留斯離開我們的部族時，他還帶走了比無暇的秘法水晶更加寶貴的東西——我們製作熾熱助熔劑的配方！我相信他一定在利用這個配方從黑鐵矮人那裡獲取利益。$B$B我希望你拿回我們的秘密配方，$N。我確信它們就在瑪托留斯身邊，而他正躲在熔渣之池的深處。', '在大熔爐的熔渣之池中的某個地方，你可以找到監督者瑪托留斯偷走的秘密設計圖：熾熱助熔劑。找到這些設計圖，把它們還給灼熱峽谷的大鐵匠博恩奈特。', '', '去灼熱峽谷找瑟銀哨塔的大鐵匠博恩奈特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7723, 'zhTW', '該死的胖手指！', '真糟糕，由於我近來變得越來越胖，我已經不能像以前那樣大吃大喝啦。你瞧瞧這兒的氣候，而且氣壓還很低，我的手指都腫脹起來啦，看上去就像是粗大的塞爾薩瑪血腸……$B$B你得幫我做點事情。$B$B讓我看看我的日程安排，第一件事情是……殺死峽谷中的重型作戰魔像。把它們全都幹掉。', '漢瑟爾·重拳讓你殺掉20個重型作戰魔像。$B$B重型作戰魔像就在灼熱峽谷的大熔爐附近。當你殺死足夠多的魔像後，就回去找漢瑟爾·重拳。', '', '去灼熱峽谷找瑟銀哨塔的漢瑟爾·重拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7724, 'zhTW', '熔岩蜘蛛的威脅！', '你不知道嗎，每次漢瑟爾想要放鬆放鬆，反思他的人生的時候，上面就會給他指派新的工作。$B$B我要思考！你知道我在說什麼嗎？知道嗎？$B$B巨型熔岩蜘蛛在這兒引起了一些麻煩，奧菲斯特說他跟這些畜牲勢不兩立……嗯，無論如何，這些蜘蛛讓孩子們感到不安。$B$B我想我們得殺掉它們，你正是最佳人選。', '漢瑟爾·重拳要你殺死灼熱峽谷中的20只巨型熔岩蜘蛛。你可以在灼熱峽谷的高地和熔岩池裡找到巨型熔岩蜘蛛。$B$B當你殺死足夠的巨型熔岩蜘蛛之後，回到漢瑟爾·重拳那裡覆命。', '', '去灼熱峽谷找瑟銀哨塔的漢瑟爾·重拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7725 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7725, 'zhTW', '更多被縮小的巨人！', '我知道你為我收集了一些微縮殘渣……如果你想要找一份全職工作的話，我想我一直都會需要這種殘渣的。$B$B雖然我無法付出足夠的報酬，但是我很樂意讓我的地精朋友們都瞭解你這個偉大的$r$c，地精之友！$B$B相信我，$g先生:女士;，地精們的耳朵都是很靈驗的……', '使用索爾賓的超級壓縮器來縮小菲拉斯的任意種類的巨人，將他們縮小到更容易控制的體積。從縮小過的巨人身上收集10份微縮殘渣，把它們交給菲拉斯被遺忘的海岸碼頭的索爾賓·範達瑟。', '', '去菲拉斯的被遺忘的海岸找索爾賓·範達瑟。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7726, 'zhTW', '補充動力', '你需要更多的工作，是嗎？難道我讓你去收集元素生物體內的粘液的宏偉任務還無法滿足你的冒險慾望？也許我要找到無數類似的事情讓你做才行……$B$B好吧，不說廢話了，我需要更多的水元素核心。我正想盡辦法在這裡開店，所以我給你的獎勵並不會很豐厚……但是我向你保證，我會把你的熱心和勇敢告訴所有人。你要相信我——我在熱砂集團裡認識很多人！', '從菲拉斯被遺忘的海岸那裡的海元素和巨型海元素身上獲取6塊水元素核心，把它們交給碼頭附近的索爾賓·範達瑟。', '', '去菲拉斯的被遺忘的海岸找索爾賓·範達瑟。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7727, 'zhTW', '燻火龍', '拇趾囊腫，$g小夥子:姑娘;。我的拇趾了出現囊腫。難道在這種混亂的情況下我只能砍下自己的腳來解除痛苦嗎？這就是我請求你幫助我的原因。$B$B斯克蘭格和博恩奈特讓我殺掉這些傢伙，這樣他們就能派出探險隊進入熔渣之池進行探索了，我說的就是那種叫做燻火龍還是什麼玩藝的麻煩傢伙。現在去殺了它們吧，在消滅燻火龍之前別回來找我。', '漢瑟爾·重拳讓你去殺掉20個燻火龍。$B$B燻火龍侵佔了熔渣之池中的那些岩漿池。熔渣之池就在灼熱峽谷的大熔爐中。$B$B當你殺死足夠數量的燻火龍後，就回去找漢瑟爾·重拳。', '', '去灼熱峽谷找瑟銀哨塔的漢瑟爾·重拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7728, 'zhTW', '被盜：鼓風機和望遠鏡', '下列物品已被盜走：$B$B*一臺黑鐵鼓風機。$B$B一支偵查員的望遠鏡。$B$B找到並歸還這些被盜物品者將獲得獎勵。$B$B瑟銀兄弟會相信，這些物品是被那些居住在灼熱峽谷中的該死的黑鐵矮人偷走的。$B$B那支望遠鏡是偵查員的有力工具，而鼓風機則是寶貴的冶鐵裝置。$B$B如果你找到丟失的物品，請將它們交給斯克蘭格。', '找到冶煉鼓風機和偵查員的望遠鏡，把它們還給灼熱峽谷的監工斯克蘭格。$B$B你所知道的關於這些物品的惟一資訊是：它們肯定是被黑鐵矮人偷走的。冶煉鼓風機是鐵匠用的鍛造工具，偵查員的望遠鏡是偵查員所需的偵查工具。', '', '去灼熱峽谷找瑟銀哨塔的監工斯克蘭格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7729, 'zhTW', '工作機會：肅清競爭對手', '監工斯克蘭格正在尋找一些優秀的冒險者深入灼熱峽谷。$B$B如果你對此感興趣的話，就到灼熱峽谷去，殺死你見到的所有黑鐵工頭和黑鐵奴隸販子。$B$B當你全身都沾滿那些傢伙的鮮血之後，就回到監工斯克蘭格那兒去。$B$B你自己應該知道什麼叫“全身沾滿他們的鮮血”，所以別問來問去的。', '殺死15個黑鐵工頭和15個黑鐵奴隸販子。完成任務之後就回去找監工斯克蘭格。', '', '去灼熱峽谷找瑟銀哨塔的監工斯克蘭格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7730, 'zhTW', '祖卡什的入侵', '根據有限的偵查，我們得出結論，豺狼人南面的敵人是一個類似昆蟲的物種。坦率地說，它們是否具有智慧現在已經不重要了。如果是它們將豺狼人逼得瘋狂進犯我們的領地，那麼這些蟲子就是比豺狼人還要巨大的威脅。$B$B殺入那些祖卡什蟲類的巢穴，那個地方被稱作痛苦深淵。削減它們的數量，然後把你發現的情報給我帶回來，另外別忘了拿回它們的甲殼作為你的努力的證明。', '把20塊祖卡什蟲殼交給菲拉斯莫沙徹營地的哈杜肯·迅蹄。', '', '去菲拉斯找莫沙徹營地的哈杜肯·迅蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7731, 'zhTW', '毒刺鞭笞者', '在調查痛苦深淵的時候，我們的斥候發現了一隻巨型昆蟲——它的體積比我們見過的所有昆蟲都要巨大，眼下它就在那裡遊蕩。它不僅體積很大，而且它身上似乎還有其它昆蟲所不具備的某種氣息。我們給它取了一個名字——毒刺鞭笞者。$B$B它的內臟可以幫助我們研究出對付這個新威脅的方法，把它的分泌腺割下來，然後立刻回來！', '擊敗痛苦深淵中的毒刺鞭笞者，把它的腺體交給菲拉斯莫沙徹營地的哈杜肯·迅蹄。', '', '去菲拉斯找莫沙徹營地的哈杜肯·迅蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7732 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7732, 'zhTW', '祖卡什報告', '在解決祖卡什蟲類的威脅這個問題上，你表現得非常出色。但是這個威脅遠未得到徹底的解決，我希望能再次請求你為了部落的利益而戰。$B$B這份檔案中記錄了所有與祖卡什蟲類有關的資訊。我希望把它交給奧格瑪暗巷區的基爾茲賓·鼓眼。他是個異型生物專家，希望他能從我們的發現中找到一些有價值的資訊。', '把莫沙徹營地祖卡什報告交給奧格瑪暗巷區的基爾茲賓·鼓眼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7733 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7733, 'zhTW', '更高的品質', '我找到了一個更好的雪人毛皮來源，這真令人難以置信！在菲拉斯北部的怒痕堡中有另外一批雪人，它們比你遇到過的雪人可要難對付多了，如果你想要嘗試更大的挑戰，就去那裡吧！$B$B如果你可以給我弄來一些它們的毛皮，我會給你豐厚的獎勵！', '把10塊怒痕雪人的毛皮交給菲拉斯羽月要塞的普拉特·馬克格魯比。', '', '去菲拉斯找羽月要塞的普拉特·馬克格魯比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7734 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7734, 'zhTW', '更高的品質', '我找到了一個更好的雪人毛皮來源，這真令人難以置信！在菲拉斯北部的怒痕堡中有另外一批雪人，它們比你遇到過的雪人可要難對付多了，如果你想要嘗試更大的挑戰，就去那裡吧！$B$B如果你可以給我弄來一些它們的毛皮，我會給你豐厚的獎勵！', '把10塊怒痕雪人的毛皮交給菲拉斯莫沙徹營地的杉多爾·迅蹄。', '', '去菲拉斯找莫沙徹營地的杉多爾·迅蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7735 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7735, 'zhTW', '原始雪人毛皮', '你找到了一塊原始雪人毛皮。它非常厚實——比那些怒痕雪人的毛皮要厚實許多。$B$B羽月要塞的普拉特·馬克格魯比是專門做雪人毛皮生意的，這些毛皮一定可以引起他的興趣。', '把原始雪人毛皮交給菲拉斯羽月要塞的普拉特·馬克格魯比。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7736 AND `locale` = 'zhTW';
