INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7761, 'zhTW', '黑手的命令', '愚蠢的傢伙，$B$B對於你的能力我向來不抱什麼希望，我不相信你可以阻止外來者進入主人的巢穴。如果你死亡了，那麼這顆寶珠內建的安全機制可以防止外來者直接傳送到黑翼巢穴中。$B$B只有那些手上烙有達基薩斯徽記的人才能使用這顆寶珠。值得慶幸的是，達基薩斯不像你那麼沒用，軍需官。它會守衛著那枚烙印！$B$B- 大酋長雷德·黑手$B$B備註 ：別忘了毀掉這封信，笨蛋。', '真是個愚蠢的獸人。看來你需要找到那枚烙印並獲得達基薩斯徽記才可以使用命令寶珠。$B$B你從信中獲知，達基薩斯將軍守衛著烙印。也許你應該就此進行更深入的調查。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7781, 'zhTW', '黑石之王', '以前的感覺又回來了，勝利的喜悅和傷痛的折磨流遍你的身體。在你面前的是奈法利安那顆巨大而佈滿創傷的頭顱。勇士，將這顆頭顱交給你的大領主吧。', '將奈法利安的頭顱交給暴風城的大領主伯瓦爾·弗塔根。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7782, 'zhTW', '黑石之王', '到英雄谷去，與艾法希比元帥談話。', '回到暴風城的英雄谷跟艾法希比元帥談話。', '', '', '', '', '', '', 0);
