INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7783, 'zhTW', '黑石之王', '以前的感覺又回來了，勝利的喜悅和傷痛的折磨流遍你的身體。在你面前的是奈法利安那顆巨大而佈滿創傷的頭顱。勇士，將這顆頭顱交給你的酋長吧。', '將奈法利安的頭顱交給奧格瑪的索爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7784, 'zhTW', '黑石之王', '到力量谷去找薩魯法爾霸王。', '和奧格瑪的薩魯法爾霸王談談。他在力量谷等你。', '', '', '', '', '', '', 0);
