INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7810, 'zhTW', '競技場大師', '要成為競技場大師肯定需要付出更多的代價！也許管理古拉巴什競技場的海盜知道到底要多少！', '與荊棘競技場的小個子約翰·米斯瑞爾談一談。', '', '去荊棘谷找古拉巴什競技場的小個子約翰·米斯瑞爾。', '', '', '', '', 0);
