INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7813, 'zhTW', '捐獻毛料', '', '我們現在接受毛料的捐贈。只要捐贈60塊毛料，幽暗城就會對你的慷慨行為表示感謝。我們只需要你捐贈60塊毛料就夠了，更多的毛料可以從其他志願者的捐贈獲得。$B$B如果你有60塊毛料並且願意捐贈的話，那現在就可以給我了。', '', '去找西瘟疫之地的萊斯頓·法斯雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7814 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7814, 'zhTW', '捐獻絲綢', '', '和其他紡織材料一樣，我們的絲綢庫存也已經降到了歷史最低點。如果有足夠的補給，我們就可以達成預期的目標。$B$B如果你願意將絲綢作為禮物送給我們的話，那你在這個社區中的地位無疑將大大提升！那麼，要是你有60塊絲綢並且願意把它們捐出來，那現在就可以給我了。', '', '去找西瘟疫之地的萊斯頓·法斯雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7815 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7815, 'zhTW', '鉗嘴龜！', '不要讓它們的大眼睛迷惑了你，夥計！那些海水鉗嘴龜真是個麻煩。我釣魚都不能安寧五分鐘，那些巨型魚罐頭就會把我的魚餌給偷吃掉。$B$B幫惡齒食人妖一個忙吧，幹掉它們，夥計。$B$B把它們都幹掉！', '辛特蘭惡齒村的釣魚者卡圖姆要你去殺掉10只海水鉗嘴龜。完成任務之後回到他那裡去覆命。', '', '去辛特蘭找惡齒村的釣魚者卡圖姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7816 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7816, 'zhTW', '加莫里塔！', '嘿，我說，這裡的海邊有一隻特殊的烏龜，她叫加莫里塔，是那幫卑鄙的海水鉗嘴龜的頭兒。$B$B夥計，她偷了我最好的魚餌，就在我眼皮底下！而且自從那次以後，魚兒就再也不咬我的鉤了。$B$B找到加莫里塔，把我的魚餌從她的胃裡挖出來！', '辛特蘭惡齒村的釣魚者卡圖姆要你去殺掉加莫里塔，並從它的屍體上找到卡圖姆的超級魚餌。$B$B卡圖姆說加莫里塔和其它海龜都在海岸附近活動。', '', '去辛特蘭找惡齒村的釣魚者卡圖姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7817 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7817, 'zhTW', '捐獻魔紋布', '', '我們的魔紋布儲量很低，而你可以幫助我們補充庫存！如果計算整個社區所能作出的貢獻的話，我們只需要從你那裡獲得60塊魔紋布就可以達到我們的目標了。你這樣的慷慨貢獻一定會被幽暗城的被遺忘者廣為傳頌，這一點我可以向你保證！$B$B如果你有60塊魔紋布並且願意捐獻的話，那現在就可以給我了。', '', '去找西瘟疫之地的萊斯頓·法斯雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7818 AND `locale` = 'zhTW';
