INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7839, 'zhTW', '邪枝竊賊', '邪枝食人妖入侵了我們的村子，偷走了我的工具！我有備用的工具，但是那套被偷走的工具是當年的一個救了我性命的地精送給我的。$B$B我要拿回那套工具，$N——它們對我來說意味著整個世界。$B$B馬克霍爾報告說那些工具就在亞戈瓦薩和沙爾瓦薩神廟附近。$B$B那些神廟坐落在辛特蘭的東北區域。$B$B找回我的工具！', '辛特蘭惡齒村的鐵匠斯拉提要你去找到斯拉提的工具。完成任務之後就回到他那裡去。$B$B你記得鐵匠斯拉提說過，你可以在辛特蘭東北部的某個邪枝食人妖神廟中找到它，要不然就是在隱匿石那邊。', '', '去辛特蘭找惡齒村的鐵匠斯拉提。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7840 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7840, 'zhTW', '拉爾德的午餐', '拉爾德在一個秘密的地方享用野餐，這時醜陋的邪枝食人妖一棍打翻了我。拉爾德跑回了惡齒村，但是把午餐留在了那裡。拉爾德餓了。也許你可以去那個秘密的地方找回拉爾德的午餐？拉爾德害怕。出發吧！北邊的島就是那個秘密的地方。', '辛特蘭惡齒村的拉爾德要求你去找到拉爾德的午餐。完成任務之後就回到他那裡去。$B$B拉爾德說他把午餐留在了北面的島上。當心邪枝食人妖。', '', '去辛特蘭找惡齒村的拉爾德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7841, 'zhTW', '給蠻錘部族的警告', '蠻錘部族的矮人和我們的敵人聯合起來，形成了新的聯盟。這一次，他們和高等精靈站在了一起，夥計。$B$B<奧索吐了口唾沫。>$B$B我們必須給那些蠻錘矮人傳達一條資訊，一條用我們敵人的鮮血書寫的警告。殺掉你所看到的所有高原高等精靈，把他們的屍體留在那裡作為警告。$B$B永遠不要與食人妖為敵！', '辛特蘭惡齒村的奧索·莫吉克要你去殺掉15個高原前鋒、15個高原斥候、15個高原神射手和15個高原遊俠。任務完成之後回到他那裡去覆命。$B$B你可以在辛特蘭西北部的奎爾丹尼小屋找到那些高原精靈。', '', '去辛特蘭找惡齒村的奧索·莫吉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7842, 'zhTW', '又一個給蠻錘部族的警告', '他們說蠻錘部族和獅鷲的關係就好像情侶一般。這讓我感到挺噁心的，但是我們可以利用這一點，夥計。我們可以送給他們另外一條警告。$B$B把你在辛特蘭看到的所有獅鷲都幹掉，收集它們的羽毛。然後我們就可以發出最後一條警告了。', '辛特蘭惡齒村的奧索·莫吉克要你從辛特蘭的獅鷲身上收集1根細長的獅鷲羽毛。任務完成之後回到他那裡去覆命。$B$B在辛特蘭各處都有獅鷲出沒。', '', '去辛特蘭找惡齒村的奧索·莫吉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7843, 'zhTW', '給蠻錘部族的最後警告', '<奧索遞給你一柄包在幾片獅鷲羽毛中的、浸滿血跡的長矛。>$B$B拿著這個，夥計。把它帶到鷹巢山去，就去鎮子中間的水井旁。把這根長矛插在那裡！就插在地上！讓矮人知道我們巨魔的厲害！當你完成這個壯舉之後就回來吧。希望你能活著回來。', '辛特蘭惡齒村的奧索·莫吉克要你去辛特蘭西部的鷹巢山，把給蠻錘部族的警告插在城鎮中心的水井旁邊。任務完成之後回到他那裡去覆命。$B$B當心那些憤怒的蠻錘矮人以及野蠻的聯盟成員。', '傳達給蠻錘部族的警告', '去辛特蘭找惡齒村的奧索·莫吉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7844, 'zhTW', '野蠻的親戚', '三個不同的食人妖部族居住在辛特蘭地區，$N。我們之間的共同點是：我們都是食人妖，而且我們都住在辛特蘭。$B$B邪枝食人妖——正如他們的名字一樣，是一群墮落的食人妖；他們以其他的食人妖和人型生物為食。$B$B如果祖爾金在這裡的話，他一定會手腕一抖滅掉這個部族——啊，祖爾金還沒有回來，所以我們要自己動手了。$B$B現在，你的職責就是把這幫渣滓給幹掉！', '辛特蘭惡齒村的秘法師雅爾金要你去殺掉6個邪枝割顱者和2個邪枝占卜者。任務完成之後回到他那裡去覆命。$B$B秘法師雅爾金說過，你可以在辛特蘭東北部的沙爾瓦薩和亞戈瓦薩神廟附近找到那些食人妖。', '', '去辛特蘭找惡齒村的秘法師雅爾金。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7845, 'zhTW', '被綁架的斷齒長者！', '我的愛人在邪枝食人妖發動的一次夜間突襲中被擄走。我們的探子回報說他還活著，並且被關在辛薩羅的頂部。據說邪惡祭司海克斯正準備把他當作祭品獻給邪神哈卡。$B$B你必須救救他，$N！我們的村莊不能失去他。', '辛特蘭惡齒村的斷齒族長要求你到辛薩羅去拯救她的愛人，斷齒長者。$B$B你聽說他被關在辛薩羅頂部，辛薩羅位於辛特蘭的南部地區，那裡是邪枝食人妖的主城。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7846, 'zhTW', '找回鑰匙！', '我的鐐銬的鑰匙在守護者希坦亞手裡，她就在洞穴附近。小心一點，$c，她身邊有強悍的守衛。$B$B幹掉她，然後用她的鑰匙開啟我的鐐銬。只有這樣我才能回家。', '辛薩羅的斷齒長者要求你殺掉守護者希坦亞，並用她身上的鐐銬鑰匙開啟他的鐐銬。當你找到鑰匙之後就回到他那裡去。', '', '去辛特蘭找辛薩羅的斷齒長者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7847, 'zhTW', '向斷齒族長覆命', '回到我的愛人——惡齒村的斷齒族長那裡。告訴她我馬上就回去！她一定會獎勵你的。', '辛薩羅的斷齒長者要求你將他已經被營救的訊息帶給惡齒村的斷齒族長。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7848, 'zhTW', '熔火之心的傳送門', '裂隙在翻滾，它撕裂並吞噬我們周圍所有的東西，$c。我所站立的地方旁邊的裂隙就是穿過黑石深淵直通火焰之王所在地的傳送門。$B$B你感到很驚奇嗎？真是遺憾……凡人總是無法領悟那些他們無法看到、觸控到或者感覺到的東西。$B$B我向你保證，這個傳送門可以到達熔火之心。$B$B你開始感興趣了嗎？其實這是很簡單的。進入熔火之心，獲得一塊熔火碎片，把它交給我，然後我就會將你的靈魂與傳送門進行同步。', '進入黑石深淵，在通往熔火之心的傳送門附近找到一塊熔火碎片，然後回到黑石山脈的洛索斯·天痕那裡。', '', '去燃燒平原找黑石山的洛索斯·天痕。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7849 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7849, 'zhTW', '分離的痛苦', '和許多朋友一樣，我摯愛的親人也在野外永遠逝去了。啊，我的雙胞胎兄弟莫克霍爾——他在邪枝食人妖突襲的那天晚上死了。$B$B他被殘忍地處死，他的屍體被軟泥怪和邪枝食人妖的狼分食。$B$B現在拯救他的肉體已經太晚了，但我們要拯救他的靈魂。把他的遺體帶回來，$N。', '辛特蘭惡齒村的獵戶馬克霍爾要你去找回他的雙胞胎兄弟的屍體。找到它，然後把獵戶莫克霍爾的頭顱和獵戶莫克霍爾的骨頭交給獵戶馬克霍爾。$B$B馬克霍爾說過，他兄弟的屍體被軟泥怪和邪枝食人妖的狼群分食。他還提到在辛薩羅有個大坑，裡面全都是軟泥怪，那裡還有個狼穴。這兩個地方都在靠近辛薩羅神廟頂部的區域。', '', '去辛特蘭找惡齒村的獵戶馬克霍爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7850 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7850, 'zhTW', '黑暗之瓶', '邪枝食人妖正在瘋狂地進攻我們，這是因為他們受到了邪惡祭司海克斯的墮落魔法的影響。$B$B你可以在辛薩羅找到腐化之血。那隻裝著腐化之血的瓶子散發著邪神哈卡的墮落能量，這讓邪枝食人妖們充滿了力量，並讓他們變得瘋狂。$B$B把那些腐化之血交給我，這樣我就可以去除其中的墮落能量，以此來削弱邪神的力量。', '辛特蘭惡齒村的斷齒族長要你在辛薩羅找到5瓶腐化之血。任務完成之後就回到斷齒族長那裡。', '', '去辛特蘭找惡齒村的斷齒族長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7861, 'zhTW', '通緝：邪惡祭司海克斯和她的爪牙', '根據斷齒族長的命令，邪惡祭司海克斯和她的手下必須受到制裁！$B$B如果你能除掉邪惡祭司海克斯和她的精英衛兵，那麼你就可以獲得豐富的獎勵。', '你必須殺掉邪惡祭司海克斯和5名邪枝精英守衛。任務完成之後回到辛特蘭的惡齒村，向斷齒族長報告。$B$B你可以在辛特蘭的邪枝食人妖城市辛薩羅的頂部找到他們。', '', '去辛特蘭找惡齒村的斷齒族長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7862, 'zhTW', '職位空缺：惡齒村衛兵隊長', '在衛兵隊長馬克霍爾犧牲之後，惡齒村衛兵隊長的職位再次空缺。如果你有興趣成為惡齒村的衛兵隊長，就必須完成以下任務，然後向斷齒族長提交申請表：$B$B消滅邪枝狂戰士。$B$B消滅邪枝暗影獵手。$B$B消滅邪枝飲血者。$B$B消滅邪枝噬魂者。', '你必須消滅5個邪枝狂戰士、3個邪枝暗影獵手、3個邪枝飲血者和2個邪枝噬魂者。$B$B完成任務之後向辛特蘭惡齒村的斷齒族長覆命。', '', '去辛特蘭找惡齒村的斷齒族長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7863 AND `locale` = 'zhTW';
