INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7874, 'zhTW', '鎮壓銀翼部隊', '梣谷森林將在強大的部落面前屈服，$R。無論夜精靈們說什麼做什麼，都無法阻止我們的推進。卡林多屬於部落，誰敢阻止我們拿取屬於我們的東西，誰就要死！$B$B讓你的心中充滿榮耀之光，讓那些膽敢阻止我們的敵人一個個倒下。摧毀銀翼要塞中的哨兵部隊，並拿到一枚戰歌榮譽獎章。把這樣一枚獎章給我拿來，你就可以獲得獎賞。', '進入戰歌峽谷擊敗聯盟小隊，獲得一枚戰歌榮譽獎章，然後向莫爾杉營地的沙塔爾·碎顱覆命。', '', '去貧瘠之地找莫爾杉營地的沙塔爾·碎顱。', '', '', '', '', 0);
