INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7926, 'zhTW', '暗月馬戲團', '暗月馬戲團就要來啦！盡情享受這一激動人心的盛典吧！$B$B現在趕快行動，用這張優惠券換取免費的禮品券！帶上你的贈券去狂歡節上找吉瓦斯·格里加特吧，別把它弄丟了！$B$B現在，馬戲團就在雷霆崖外，莫高雷境內。千萬別錯過了！現在就出發吧！', '到暗月馬戲團的場地裡去，將免費券交給吉瓦斯·格里加特。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7927, 'zhTW', '暗月入口套牌', '你現在已經收集到了入口套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。', '當暗月馬戲團來到鎮上的時候，把入口套牌交給他們。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 7928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7928, 'zhTW', '暗月督軍套牌', '你現在已經收集到了督軍套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。', '當暗月馬戲團來到鎮上的時候，把督軍套牌交給他們。', '', '', '', '', '', '', 0);
