INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7937, 'zhTW', '財富在等著你……', '“東谷的財寶正等著你。”$B$B你撫摸著手中的占卜，感到一絲暖意。你緊緊地握住它，眼前浮現出艾爾文森林東谷伐木場的影像。你專注地觀察著，發現馬廄附近有一堆乾草。', '到艾爾文森林的東谷伐木場去尋找你的財寶吧。', '', '', '', '', '', '', 0);
