INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7938, 'zhTW', '財富在等著你……', '“死亡礦坑中的財寶正等著你。”$B$B你撫摸著手中的占卜，感到一絲暖意。你緊緊地握住它，眼前浮現出位於西部荒野月溪鎮的死亡礦坑的影像。你專注地觀察著，發現蜿蜒的道路盡頭是一道發光的門……通往礦坑中心的門。你穿過大門，不知從哪兒冒出一個奇怪的箱子。', '到西部荒野的死亡礦坑中去尋找你的財寶吧。', '', '', '', '', '', '', 0);
