INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7944, 'zhTW', '財富在等著你……', '“哀嚎洞穴中的財寶正等著你。”$B$B你撫摸著手中的塔羅牌，感到一絲暖意。你緊緊地握住它，眼前浮現出了位於貧瘠之地十字路口西南方的一處洞穴的影像。你專注地觀察著，發現蜿蜒的道路盡頭是一道發光的門……通往洞穴中心的門。你穿過大門，不知從哪兒冒出了一個奇怪的箱子。', '到貧瘠之地的哀嚎洞穴中去尋找你的財寶吧。', '', '', '', '', '', '', 0);
