INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (7945, 'zhTW', '財富在等著你……', '「白鬃石外的財寶正等著你。」$B$B你撫摸著手中的塔羅牌，感到一絲暖意。你緊緊地握住它，眼前浮現出莫高雷白鬃石的影像。你專注地觀察著，發現洞穴入口附近有一塊樹樁。', '到莫高雷的白鬃石去尋找你的財寶吧。', '', '', '', '', '', '', 0);
