INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8105, 'zhTW', '阿拉希盆地之戰！', '$N，在阿拉希盆地的戰鬥是為了資源和領土而進行的戰鬥。這個地區作戰的關鍵是保證我們軍隊稀有物資和補給的順暢運作。我命令你去攻擊距離我們在阿拉希盆地中的基地最遠的戰略設施。$B$B當農場、礦洞、伐木場或鐵匠鋪被敵人佔據時，攻擊這些設施，找到敵人的旗幟，然後把它拔掉！$B$B當你完成了奪回這四個點的任務之後，就回到我這裡來。', '進攻礦洞、伐木場、鐵匠鋪和農場，然後向避難谷地的奧斯萊特元帥覆命。', '', '去阿拉希高地找避難谷地的奧斯萊特元帥。', '突襲礦洞', '突襲伐木場', '突襲鐵匠鋪', '突襲農場', 0);
