INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8114, 'zhTW', '控制四座基地', '$N，你贏得了在阿拉希盆地的戰爭，並在戰場上證明了自己有資格得到榮耀和尊重。你是一個有價值的$c，你讓我們的敵人知道我們絕對不會向他們的暴行屈服！$B$B現在我有一項艱鉅的任務要交給你。我需要你進入阿拉希盆地，佔領至少四座基地。如果你可以完成這個任務的話，那麼我們不僅保證了重要資源的供給，而且還向部落展示了我們的力量！$B$B出發吧，$N，祝你好運。', '進入阿拉希盆地，同時佔據並控制四座基地，當任務完成之後向避難谷地的奧斯萊特元帥報告。', '控制四座基地。', '去阿拉希高地找避難谷地的奧斯萊特元帥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8115 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8115, 'zhTW', '控制五座基地', '$N，阿拉希盆地的資源之戰是一場血腥的戰鬥。阿拉索聯軍需要你的幫助。$B$B我們還有一個任務需要交給你。$B$B聯軍想要對汙染者進行一次大規模攻擊。我們要把他們從這個戰場中的每個重要戰略點裡趕出去！$B$B這個任務不簡單，但是如果說有人可以完成它的話，那個人就是你。', '同時控制阿拉希盆地中的五座基地，然後向避難谷地的奧斯萊特元帥覆命。', '奪取五座基地。', '去阿拉希高地找避難谷地的奧斯萊特元帥。', '', '', '', '', 0);
