INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8201, 'zhTW', '祭司的頭顱', '這是真的。哈卡現在藏身在祖爾格拉布中，他正沐浴在我們的神的力量之下。被迷惑的高階祭司們正將我們最神聖的能量傳輸給奪靈者，他的力量即將超過艾澤拉斯世界上所有的生物。我們必須阻止他！$B$B拿著這根神聖之索，將它穿過負責傳輸我們神的能量的高階祭司們的頭顱。$B$B當你完成了這一步之後，就回到我這裡來。', '將神聖之索穿上5顆導魔師的頭顱，然後把這一串食人妖頭顱交給尤亞姆巴島上的伊克薩爾。', '', '去荊棘谷找尤亞姆巴島的伊克薩爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8221 AND `locale` = 'zhTW';
