INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8227, 'zhTW', '納特的捲尺', '在散落的魚餌和滾軸之中是一卷光滑的測量捲尺。捲尺上的標籤寫著：$B$B“納特·帕格，塵泥沼澤。”', '將納特的捲尺交給塵泥沼澤的納特·帕格。', '', '', '', '', '', '', 0);
