INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8231, 'zhTW', '碎浪多頭怪', '碎浪多頭怪是一種生活在艾薩拉的海陸兩棲生物。它們擁有強大的力量和頑強的生命力。$B$B碎浪多頭怪身上的堅硬光滑的鱗片是獵人實力的證明。$B$B獵殺艾薩拉沿岸的碎浪多頭怪，給我帶回它們的鱗片作為證明吧。', '將6塊碎浪多頭怪的鱗片交給艾薩拉的奧汀克。奧汀克居住在埃達拉斯廢墟東北部的懸崖頂部。', '', '去艾薩拉找破碎海岸的奧汀克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8232, 'zhTW', '神廟中的綠龍', '我要交給你一項危險的狩獵任務：殺死綠龍摩弗拉斯，把它的牙齒帶回來給我。摩弗拉斯居住在悲傷沼澤的阿塔哈卡神廟深處。$B$B如果你想要打敗它的話，就必須叫上你的夥伴同去。這條綠龍是很多人共同的敵人——去尋找那些志同道合的盟友吧。$B$B綠龍的牙齒是獵人實力的證明。將牙齒交給我，你會在狩獵中得到成長。', '將摩弗拉斯的牙齒交給艾薩拉的奧汀克。他住在埃達拉斯廢墟東北部懸崖的頂端。', '', '去艾薩拉找破碎海岸的奧汀克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8233, 'zhTW', '簡單的要求', '喬拉齊·拉文霍德領主邀請你到他那兒去。這事兒得保密，我不能再透露更多訊息了。$B$B拉文霍德莊園位於希爾斯布萊德丘陵，敦霍爾德城堡的西北方有一條道路通往那兒。', '前往拉文霍德莊園，和喬拉齊·拉文霍德領主談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8234 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8234, 'zhTW', '密封的藍袋子', '事分輕重緩急。我丟了一個藍色的小袋子，裡面的東西很私密。$B$B但是，你不用追蹤那些小偷啦，因為他們已經死了。我所知道的是，那些傻瓜費了九牛二虎之力也沒能開啟包裹，因此他們將包裹作為“神聖的器物”賣給了艾薩拉的木喉薩滿祭司。這些傢伙很聰明。$B$B我想讓你前往艾薩拉，從薩滿祭司那兒憑藉智慧取回包裹……當然你也可以憑藉武力。我認為第一種方法比較保險。一旦你成功了，就把包裹交給大法師克希雷姆。', '從艾薩拉的木喉薩滿祭司那兒取回密封的藍袋子，將它交給艾薩拉的大法師克希雷姆。', '', '去艾薩拉找在熊頭的大法師克希雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8235, 'zhTW', '密文碎片', '拉文霍德公爵想讓我們倆幫他個忙。他希望解除施加在這隻袋子上的魔法。$B$B不幸的是，我的那些關於驅散魔法的書籍被一些暴徒奪走並銷燬了，但書籍殘存的碎片對我來說仍有利用價值。如果你能給我找來至少10塊密文碎片，我就能將它們還原。你可以去殺一些森林軟泥怪試試。它們通常什麼東西都撿……你可以在艾薩拉的東北部找到森林軟泥怪。', '將10塊密文碎片交給艾薩拉的大法師克希雷姆。', '', '去艾薩拉找在熊頭的大法師克希雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8236 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8236, 'zhTW', '碧藍鑰匙', '要解讀這些碎片並移除魔化效果需要一點時間。當我完成這個工作後，我會親自將袋子交給拉文霍德領主。$B$B眼下的問題是鑰匙，據說鑰匙在綠龍摩弗拉斯手中，而摩弗拉斯則居住在阿塔哈卡神廟的深處，就是那個泡在悲傷沼澤裡的神廟。$B$B叫上你的朋友，前往綠龍的巢穴吧。拉文霍德領主在等你取回鑰匙呢。', '將碧藍鑰匙交給喬拉齊·拉文霍德領主。', '', '去希爾斯布萊德丘陵找拉文霍德莊園的喬拉齊·拉文霍德領主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8237 AND `locale` = 'zhTW';
