INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8240, 'zhTW', '贊扎的寶石', '銷燬哈卡萊寶石對我們來說至關重要，我們甚至歡迎氏族之外的人幫助我們摧毀哈卡萊寶石！$B$B將你在祖爾格拉布找到的寶石帶往贊扎祭壇進行銷燬。我會送你一枚額外的部族榮譽勳章，僅此一次，下不為例；這東西可不是輕易就能獲得的。$B$B願贊扎的祝福與你同在！', '將你在祖爾格拉布找到的哈卡萊寶石帶往尤亞姆巴島的贊扎祭壇進行銷燬，然後跟祭壇旁邊的溫卡薩談一談。', '', '去荊棘谷找尤亞姆巴島的溫卡薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8241 AND `locale` = 'zhTW';
