INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8250, 'zhTW', '法師公會', '大法師克希雷姆最近不斷在問起有沒有像你這種經歷的$r。如果你想要找他可以去艾薩拉。他的塔就在懸崖的頂端，而唯一可以上去的方法就是由他那傲慢的僕從薩納斯所施放的傳送法術。薩納斯紮營在他的主人的塔下。如果你要找他，先去艾薩拉的主要道路彎向埃達拉斯廢墟的轉角處。從那個地方再往北直走就可以到達懸崖了。', '尋找薩納斯並獲得見到大法師克希雷姆的通路。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8251 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8251, 'zhTW', '魔法粉末', '在艾薩拉的血精靈正在尋求一種研磨他們獲得的魔法物品的方法。這種方法所獲得的粉末與普通的分解法術所獲得的材料是不同的。$B$B當我派我的學徒試圖去交易這種粉末的時候，他被毫不猶豫地幹掉了。因此，他們必須為此付出代價。$B$B談話結束，$N。找到艾薩拉北部的這些血精靈，然後使用更具「說服力」的方法來獲得他們閃光的粉末。', '為大法師克希雷姆收集10份閃光粉末。', '', '去找凍霜林地的大法師克希雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8252, 'zhTW', '海妖的珊瑚', '看看你的四周吧。遺跡和海岸被惡鞭納迦所佔據了。最近，它們開始熟悉這塊土地並認識到艾薩拉所擁有的稀有材料。$B$B我說的就是魔化珊瑚─不知道為什麼，惡鞭納迦也盯上了它。海灣中的珊瑚所存無幾，這對於我的研究工作非常重要。我需要你去從惡鞭海妖那裡弄一些附魔珊瑚然後帶給我。', '收集6塊附魔珊瑚，然後把它們帶給大法師克希雷姆。', '', '去找凍霜林地的大法師克希雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8253, 'zhTW', '消滅摩弗拉斯', '在沉沒的神廟阿塔哈卡深處，有一條名叫摩弗拉斯的綠龍。$B$B數年前我受到他的襲擊，在我有能力組織防禦之前他就殺光了我所有的學徒。我知道有一名學徒已死於非命，他身上有一塊巨大的、擁有無限能量的秘法裂片。$B$B你必須跟盟友共同深入神廟。殺死摩弗拉斯，從這傢伙的胃中取出秘法裂片。', '從摩弗拉斯身上取回秘法裂片並返回大法師克希雷姆那兒。', '', '去艾薩拉找熊頭的大法師克希雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8254, 'zhTW', '幫助塞納里奧', '幫助那些需要幫助的人就是神聖之路。如何去幫助這些人不足掛齒－－重要的是為了什麼。塞納里奧議會需要你的幫助。跟奧汀克談一談並對他們的困境伸出援手。他就住在埃達拉斯廢墟的東北方的懸崖上。', '尋找艾薩拉的奧汀克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8255, 'zhTW', '打獵者', '艾薩拉的苔蹄快步者是一種曾經居住在費伍德森林的偉大生物。它們對疾病和毒藥免疫，因此沒有被那裡的墮落力量所感染。在它們遠古的智慧指引下，苔蹄快步者簡單地選擇了離開。$B$B雖然我感到非常遺憾，但是我希望你能幫助我去獵捕這些強大的野獸。收集4份健康的野鹿腺體，這是淨化藥膏的第一種成分─我們會利用淨化藥膏來治療費伍德森林的。', '收集4份健康的野鹿腺體並把它們帶給艾薩拉的奧汀克。奧汀克住在埃達拉斯廢墟東北部懸崖的頂部。', '', '去艾薩拉找破碎海岸的奧汀克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8256, 'zhTW', '亡靈腐液', '製作淨化藥膏所需的配方極其簡單:一份有毒的藥劑，兩份治療藥劑。你已經獲得了一份治療藥劑，那麼你得收集一份毒藥。$B$B埃達拉斯廢墟附近徘徊的精靈貴族充滿了邪惡，它們經常會生出一些令人作嘔的綠色粘液。這種東西被稱為不死生物腐液。$B$B這種東西邪惡力量非常強大，我只需要你帶給我一份不死生物腐液。', '為艾薩拉的奧汀克帶回1份亡靈腐液。奧汀克住在埃達拉斯廢墟東北部懸崖的頂端。', '', '去艾薩拉找破碎海岸的奧汀克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8257, 'zhTW', '摩弗拉斯之血', '藥劑的最後一種成分是第二種治療劑。$B$B據說綠龍摩弗拉斯對任何形式的毒藥和疾病免疫─無數德魯伊用生命換來了這個資訊。毫無疑問，他的血液符合我們的要求。$B$B在你收集最後一種成分時，塞納里奧議會的一名信使將帶走你已經收集到的成分。召集盟友，前往沉沒的神廟阿塔哈卡中的綠龍巢穴吧。將他的血液帶給費伍德森林中的格雷塔·苔蹄。', '前往沉沒的神廟阿塔哈卡，殺死摩弗拉斯，將他的血液交給費伍德森林中的格雷塔·苔蹄。沉沒的神廟的入口就在悲傷沼澤。', '', '去費伍德森林找翡翠聖地的格雷塔·苔蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8258, 'zhTW', '達克雷爾的威脅', '死亡騎士達克雷爾主宰了通靈學院的屍骨儲藏所。他威脅要扭曲整個靈魂國度來達到他自己的目的，我們必須阻止他！這就是水晶球可以幫助你的地方。$B$B在屍骨儲藏所地下室的中心使用預言水晶球，以此來召喚達克雷爾的爪牙。擊敗這些爪牙，接下來死亡騎士就會出現了。$N，把他的頭顱帶給我！只有他的死亡才可以將靈魂國度的局勢扭轉過來！', '在通靈學院地下室的屍骨儲藏所的中心使用預言水晶球，然後與被召喚出來的幽靈作戰。擊敗這些幽靈之後，死亡騎士達克雷爾才會出現，你的任務就是擊敗他。$B$B把死亡騎士達克雷爾的頭顱交給奧格瑪智慧穀的薩格尼。', '', '去找奧格瑪的薩格尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8259 AND `locale` = 'zhTW';
