INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8274, 'zhTW', '測試獵殺任務', '有空嗎？幫我殺幾個魚人，我會給你很棒的東西！', '殺死15只魚人然後向測試角色回報。', '', 'Return to [PH] Luis Test NPC in Designer Island.', '', '', '', '', 0);
