INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8297, 'zhTW', '阿拉希盆地的資源！', '我們必須依靠我們的士兵進行戰鬥，所有的士兵都會這麼告訴你的。他們還會告訴你，他們正在使用破爛不堪的裝備，饑腸轆轆地開向戰場！$B$B這就是阿拉希盆地顯得非常重要的原因。金屬，武器，食物，木材——所有我們所需要的東西都可以從那裡獲得。$B$B那就是我需要你發揮作用的地方，$N。進入阿拉希盆地，比敵人佔據更多的基地，以此來獲得戰鬥的勝利，然後給我帶回1箱資源來。', '獲得阿拉希盆地戰鬥的勝利，獲取一個阿拉希資源箱，然後向避難谷地的瑪克里爾中士覆命。', '', '去阿拉希高地找避難谷地的瑪克里爾中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8298 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8298, 'zhTW', '巫妖王之怒 任務', '', '', '', '去找阿拉希高地的瑪克里爾中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8299 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8299, 'zhTW', '切斷阿拉索補給線', '阿拉索聯軍正在不惜一切代價進攻阿拉希，並妄圖奪回這個區域。聯盟的各個種族正在全力進軍這塊遙遠的土地，想要將他們的勢力從避難谷地擴張到這裡。我們必須阻止他們，而最好的方式就是奪取他們的資源。$B$B你可以幫助我們，$N。進入阿拉希盆地，那裡遍地都是豐富的礦藏、肥沃的土地和技藝精湛的能工巧匠。佔據並控制你找到的所有基地，贏得戰鬥，然後把你獲得的資源給我拿回來。', '進入阿拉希盆地，獲得一箱阿拉希資源箱，然後將它交給落錘鎮的亡靈哨兵莫提斯。', '', '去阿拉希高地找東部禁錮法陣的亡靈哨兵莫提斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8300 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8300, 'zhTW', '巫妖王之怒 任務', '', '', '', '去找阿拉希高地的亡靈哨兵莫提斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8301, 'zhTW', '正義之路', '諾茲多姆的子嗣根本不信任低等種族。雖然你已經向我證明了你的確具備了英雄的潛質，但是現在你還得向我的主人證明這一點。$B$B亞什蟲巢、佐拉蟲巢、雷戈蟲巢，這些地方的蟲子們蠢蠢欲動，對我們形成了極大的威脅。殺死這些蟲巢中的異種蟲類，從它們的甲殼上取下碎片。當你獲得足夠多的碎片時，回到我這兒來。', '為流沙守望者巴里斯托爾斯收集200塊異種蠍殼碎片。', '', '去找希利蘇斯的流沙守望者巴里斯托爾斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8302, 'zhTW', '正義之手', '凡人，明智地選擇你的副手。每當你完成一次任務，你就可以選擇一個新的副手。$B$B我需要更多的異種蠍殼碎片。別浪費時間!', '為流沙守望者巴里斯托爾斯收集200塊異種蠍殼碎片。', '', '去希利蘇斯找塞納里奧要塞的流沙守望者巴里斯托爾斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8303, 'zhTW', '安納克羅斯', '是時候了，$N。$B$B我隱瞞這個秘密已經很久了，我對此深表歉意。敵人無處不在，很可能就在我們眼皮底下。請閱讀這本密典，好好運用我教給你的知識，去尋找我們的主人。', '去塔納利斯的時光之穴尋找安納克羅斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8304, 'zhTW', '親愛的娜塔莉雅', '我親愛的娜塔莉雅走失了。$B$B老實說，她失蹤之前好幾週都行為怪異。我不止一次看到她在四下無人時喃喃自語。她堅持說什麼自己是對的，堅持繼續自己的研究。$B$B我最後一次見她的時候，她正朝著南邊的銅鬚營地走去。$B$B我的兵力非常薄弱，$N。所以我想請你前往銅鬚營地，問問那些矮人。', '希利蘇斯，指揮官瑪爾利斯要你去詢問銅鬚營地的矮人居住者。你可以在塞納里奧城堡南邊找到銅鬚營地。$B$B當你收集到需要的資訊再回去找指揮官瑪爾利斯。', '', '去希利蘇斯找塞納里奧要塞的指揮官瑪爾利斯。', '詢問法蘭克爾', '詢問魯特加爾', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8305 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8305, 'zhTW', '久遠的記憶', '希利蘇斯的沙漠南方靠近一個神聖的屏障之處藏著一顆結晶之淚。這顆淚象徵著我們在流沙之戰落敗之後的苦悶。找到這顆淚並且深深地注視著它，你就可以獲得啟發。', '找到希利蘇斯的結晶之淚並注視它的深處。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8306, 'zhTW', '深入瘋狂之口', '我想讓你前往雷戈蟲巢，看看我心愛的娜塔莉雅變成什麼樣了，$N。這項任務並不容易，在你前往瘋狂之口前，請一定返回營地跟那些矮人談談。他們或許會告訴你對付居住在蟲巢中的異種蟲類的竅門。$B$B$N，如果娜塔莉雅真的如他們所說的那樣變得瘋狂……做你應該做的。$B$B<指揮官瑪爾利斯轉過身去。>', '希利蘇斯，塞納里奧城堡的指揮官瑪爾利斯要你去找尋他摯愛的娜塔莉雅。你所收集到的資訊指出，南方的雷戈蟲巢就是你可以找到娜塔莉雅·瑪爾利斯夫人的地方。$B$B別忘記在進入蟲巢之前先去拜訪銅鬚營地的矮人。他們可能有一些額外的工作和建議要給你。$B$B還有$N，記得指揮官的話:「做你該做的…」', '', '去希利蘇斯找塞納里奧要塞的指揮官瑪爾利斯。', '娜塔莉雅小姐的命運', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8307, 'zhTW', '沙漠食譜', '要適應沙漠生活並不容易。我思念奧伯丁的小鳥和綠樹，而在希利蘇斯這片乾燥的土地上，可供食用的食物少之又少。我在嘗試著研究沙漠中的草藥，但是草藥的數量並不多。我曾經看到西邊的那些暮光之錘成員獵殺沙蟲作為食物。沙蟲的味道很苦，不知道他們是怎麼吃下去的……如果你碰巧去他們營地的話，記得仔細觀察，看能不能學到點什麼。', '在塞納里奧城堡西方的暮光之錘營地尋找關於烹煮沙蟲肉的資訊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8308 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8308, 'zhTW', '布拉恩·銅鬚遺失的信件', '致此信的讀者:$B$B當你讀到這兒時，我可能已經死了，也可能很快就會死去，這很難說。總之，大部分人都已經死掉了。$B$B我已經找到了有關一位泰坦的資訊。他和一個上古之神展開了一場激戰。是的，上古之神。我還找到通往安其拉的古老隧道。$B$B將這封信帶回我的營地，保證我的猴子有充足的食物和水，記得多抱抱它。$B$B- 布萊恩·銅鬚，探險特派員$B$B附:注意那些崇拜上古之神的夜精靈。', '將布拉恩·銅鬚的信帶到希利蘇斯南邊的銅鬚營地去。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8309 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8309, 'zhTW', '追查雕紋', '在我們首次嘗試進攻蟲巢、瑪爾利斯夫人變得瘋瘋癲癲之後，那些蟲巢中就不斷湧出蟲子來!這也許跟那些奇怪的水晶上的雕紋有關。$B$B我們必須從三個蟲巢的水晶上取下拓文。如果我們能得到拓文，或許能揭開這種瘋症的謎團。$B$B帶上拓文工具，前往蟲巢去吧，$N。取下三座蟲巢中的拓文之後再回到我這兒來。', '希利蘇斯銅鬚營地的魯特加爾·雕石想要你前往亞什蟲巢、佐拉蟲巢和雷戈蟲巢，從蟲巢中的雕紋水晶上取下拓文。$B$B使用地質學家的抄錄工具包獲取古老雕紋的摹本。完成任務後回到魯特加爾·塑紋者那兒。', '', '去找希利蘇斯的魯特加爾·塑紋者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8310 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8310, 'zhTW', '破解密碼', '我得製作一種藥劑，幫助我們解讀雕紋以及其拉蟲人和異種蟲的語言!我需要什麼?很高興你能這麼問!我需要腦子!確切地說，我需要居住在蟲巢中的不同種群的異種蟲的腦子。把它們的腦子給我，或許魯特加爾的努力就不會白費。', '希利蘇斯銅鬚營地的法蘭克爾·石橋想要你取回一個亞什異種蟲腦、一個佐拉異種蟲腦和一個雷戈異種蟲腦。完成任務後回到法蘭克爾那兒。', '', '去找希利蘇斯的法蘭克爾·石橋。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8311 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8311, 'zhTW', '史波普的萬鬼節糖果！', '我想要去討萬鬼節糖果，但是我不能去，因為我生病了。如果你可以代我去的話，我會給你一些我已有的糖果！我想你會喜歡這些糖果的……它可以讓你變成又好玩又可怕的東西！$B$B每座主城的旅店老闆都有準備萬鬼節的糖果——你只要和他們交談，然後按照他們所要求的做就可以了！另外，鐵爐堡有個叫塔瓦斯德的小地精也在散發糖果。如果你得到了所有的糖果，就把它們都帶回來給我吧！', '和暴風城、鐵爐堡、達納蘇斯的旅店老闆們及鐵爐堡的塔瓦斯德·基瑟爾交談。完成要求的惡作劇來交換他們提供的糖果。$B$B帶著達納蘇斯的杏仁糖、諾姆瑞根的橡皮軟糖、暴風城的奶油杏仁花生糖，和鐵爐堡的薄荷糖去找暴風城孤兒院的賈斯伯。', '', '去找暴風城的賈斯伯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8312 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8312, 'zhTW', '賈斯伯的萬鬼節糖果！', '我想要去討萬鬼節糖果，但是我不能去，因為我生病了。如果你可以代我去的話，我會給你一些我已有的糖果！我想你會喜歡這些糖果的……它可以讓你變成又好玩又可怕的東西！$B$B每座主城的旅店老闆都有準備萬鬼節的糖果——你只要和他們交談，然後按照他們所要求的做就可以了！另外，森金村的一個名叫卡利·雷米克的食人妖也在散發糖果。如果你得到了所有的糖果，就把它們都帶回來給我吧！', '和奧格瑪、幽暗城、雷霆崖的旅店老闆們及森金村的塔卡利·雷米克交談。完成要求的惡作劇來交換他們提供的糖果。$B$B帶著雷霆崖的杏仁糖、暗矛海灘的橡皮軟糖、奧格瑪的奶油杏仁花生糖，和幽暗城的薄荷糖去找奧格瑪孤兒院的史波普。', '', '去找奧格瑪的史波普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8313, 'zhTW', '分享知識', '雖然你能讀懂沙蟲的烹飪配方，但是裏面提到的草藥和香料你都從未聽說過。卡蘭德拉斯或許對此有些瞭解。', '將破碎的食譜交給塞納里奧城堡旅店中的卡蘭德拉斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8314 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8314, 'zhTW', '解開謎題', '我們就快要取得突破了，$N!我們可以通過你取回的拓文在這塊晶華棱柱上重現雕紋。很明顯，其拉蟲人和某種未知生物利用這種文字與異種蟲交流資訊。$B$B不幸的是，我們只能從雕紋中發現這一點。我們需要設法揭開結晶中隱藏的秘密。$B$B將雕紋結晶棱柱交給塞納里奧城堡的地質學家拉克斯班。她或許能幫上忙。', '銅鬚營地的魯特加爾·塑紋者想讓你將雕紋水晶棱柱交給希利蘇斯塞納里奧城堡的地質學家拉克斯班。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8315, 'zhTW', '呼喚', '雕紋雕紋顯示，一位元其拉蟲人的使者跟三個異種蟲相約在一處龍骨旁見面。關於雕紋上方的文字，我只能假設那是某種密碼。這密碼很可能是召喚其拉蟲人使者的關鍵。$B$B我將製作一份雕紋密碼的副本，你把它放到格拉卡洛之骨的沙中。如果我沒猜錯的話，主宰會認為可以傳遞新資料了。殺死他們，然後跟其拉蟲人使者作戰。他是揭開水晶之謎的關鍵人物……', '希利蘇斯塞納里奧城堡的地質學家拉克斯班想讓你從其拉蟲人使者那裏取回水晶分解裝置。$B$B你已經奉命將召喚雕紋帶往塞納里奧城堡以南的格拉卡洛之骨處，將它們從沙中引出。一旦其拉蟲人使者露面，就殺死它，獲得水晶分解裝置。成功之後回到地質學家拉克斯班那兒去。$B$B你必須召集一支強大的軍隊來完成這項任務，$N!', '', '去希利蘇斯找塞納里奧要塞的地理學家拉克斯班。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8316 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8316, 'zhTW', '軍備之戰', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8317, 'zhTW', '廚房助手', '這個食譜一定會很簡便。我最好快點去工作才能有煙燻沙漠餃子可吃。幫我一點忙，我保證你值回票價的。', '塞納里奧城堡的卡蘭德拉斯需要製作10個沙漠肉丸子的麵團。', '', '去希利蘇斯找塞納里奧要塞的卡蘭德拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8318 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8318, 'zhTW', '秘密通訊', '有些暮光之錘祭司帶著寫滿胡言亂語的小紙片四處走動。我要你去幫我帶回一堆紙片，$c。$B$B我不能理解那些胡言亂語的意思，不過那不是重點!這些紙片就是他們不同族群秘密溝通的方式，我們從訊息傳播中拿走越多文字，他們就越無法溝通!', '帶10張暮光文本給塞納里奧城堡的鮑爾·蠻鬃。', '', '去希利蘇斯找塞納里奧要塞的鮑爾·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8319, 'zhTW', '暮光加密文件', '', '繼續帶文件給我。我們很快就能逼暮光之錘回到他們爬出來的巢穴了。', '', '去找希利蘇斯的鮑爾·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8320 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8320, 'zhTW', '暮光地領主', '暮光之錘，一個傾向毀滅的瘋狂教派，在希利蘇斯建立了據點並且日以繼夜地舉行儀式。我們還不知道他們的計畫為何，但是我們覺得應該與散落在沙漠之中的脈衝紅水晶有些關聯。$B$B雖然有一天可以解開他們的謎團，然而我們必須先處理他們帶來的立即性威脅。到他們的營地去並且找出暮光地領主。他們就是這些毒蛇的首領，也就是我們必須打擊的對象!', '殺死10個暮光地領主, 然後向塞納里奧城堡的胡姆·蠻鬃回報。', '', '去希利蘇斯找塞納里奧要塞的霍姆·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8321, 'zhTW', '卑鄙的維拉爾', '我們發現了另一個暮光之錘的運作基地。它叫暮光小徑;是個在希利蘇斯東北方角落的洞穴。當地的領導者，卑鄙的維拉爾，都在那個洞穴出沒 - 他就是你下一個一定要擊敗的人。完成之後，把他的璽戒拿來給我。$B$B祝你好運，$N。暮光小徑真的是個很可怕的地方。', '把維拉爾的璽戒帶給塞納里奧城堡的胡姆·蠻鬃。', '', '去希利蘇斯找塞納里奧要塞的霍姆·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8322, 'zhTW', '惡臭雞蛋', '南海鎮的人熱愛他們的麥酒，因此他們視南海鎮旅店裡的麥酒為寶。現在趁著萬鬼節的混亂，我們可以去毀了他們最新一批的飲品，讓他們好幾個禮拜 - 甚至是好幾個月都沒東西喝！$B$B帶著這些腐爛發臭的雞蛋，把它們放到南海鎮旅店釀酒的桶子裡。你獨自前往一定會引起衝突，所以要提高警覺！$B$B等你給南海鎮的人嘗到難以忘懷的滋味之後，回到慶典這裡找我！', '將腐爛的臭雞蛋放到南海鎮旅店主要的釀酒桶子裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8323, 'zhTW', '真實信仰者', '現在我擁有暮光詞典了，我想要請你幫我一個小忙。 $B$B我過去的組織有一份一個月循環一次的加密文件。$B$B如果他們對我的研究有任何進展或是他們終止了研究，都會在真實信仰者發表。$B$B雖然這個資訊對我來說有很明顯的價值，但是我也能分享這份文件所包含的其他有用訊息。你可以在暮光之錘的成員身上得到這份加密文件，把他帶給我。', '隱士奧泰爾希望你能帶給他10份加密的暮光文件。', '', '去找希利蘇斯的隱士奧泰爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8324, 'zhTW', '更多的讀物', '', '', '', '去找希利蘇斯的隱士奧泰爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8325 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8325, 'zhTW', '奪回逐日者之島', '你越早開始行動對我們大家越好，$N。沒有空間犯錯，所以聽仔細了。$B$B燃燒水晶 - 那個在日尖塔西方的綠色漂浮物 - 長久以來被用作增強小島的實驗。法力龍鰻是他們的守衛，但奎爾薩拉斯的天譴軍團入侵讓他們誤入歧途，因為我們無法用魔法控制他們。$B$B我們無計可施只能削減他們的數量以重拾小島。快去吧，完成後再回來找我。', '殺死8隻法力龍鰻;他們就在哨塔與瞭望台旁的燃燒水晶那裡。完成後回到逐日者之島哨塔上的博學者伊羅娜那裡。', '', '去找永歌森林的博學者伊羅娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8326, 'zhTW', '不幸的手段', '你的努力讓一些事情明朗化，老實說，我希望那不是真的。燃燒水晶未經查證的力量已經對島上的自然平衡有了更大的破壞。我們一定要採取更多不幸的措施以重拾控制。$B$B附近的山貓已經向水晶的力量屈服，而他們一定要被消滅。把他們的項圈帶回來，$N，這樣我才能實行魔法抑制以扭轉一點形勢。', '殺死泉爪山貓和幼年泉爪山貓收集8個山貓項圈。完成後去找逐日者之島的博學者伊羅娜。', '', '去找永歌森林的博學者伊羅娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8327, 'zhTW', '向蘭深·佩瑞隆回報', '你要跟我的助理蘭深·佩瑞隆報告。他會告訴你接下來要做什麼。當我們在日尖塔這裡繼續支配燃燒水晶，你則要致力於一件更緊急的事，與法薩瑞安學院有關。等你和蘭深交談的時候他會詳細地向你描述。沿著路往西邊走，你就會看到他站在那裡。祝你好運，$N - 你繼續成功是會得到獎勵的。', '和逐日者之島的蘭深·佩瑞隆談談;他就在日尖塔往西邊的路上。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8328, 'zhTW', '法師訓練', '隨著你的職業技能越來越精進，你就要從你的職業訓練師那裡多學一點東西。在逐日者之島，年輕法師的訓練師是茱莉亞·擊日者。和她談談，看看她能提供你什麼訓練。向她學東西是要花錢的，所以帶一點錢在身上。茱莉亞 - 和所有逐日者之島的訓練師一樣 - 都在日尖塔的較低層。', '和茱莉亞·擊日者 - 法師訓練師談談，她就在逐日者之島的日尖塔裡面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8329 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8329, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8330 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8330, 'zhTW', '索蘭尼亞的東西', '日尖塔那裡發生了那麼多混亂的事，我沒有時間收好留在島上的東西。我一定要在太陽之井這裡保持警戒，所以我希望你能幫我把東西找回來。$B$B我需要我的占卜寶珠，我的天譴魔法卷軸，還有我的日記。把這個包包帶去增加點空間，我的東西體積都很龐大。把它們拿來給我，我就會給你一個東西 - 你知道，因為你幫了忙;你也可以留著這個包包!', '收集看井者索蘭尼亞的占卜寶珠，他的天譴軍團的魔法卷軸和他的日記。你可以在逐日者之島的池塘邊，噴水池邊和某個燃燒水晶那裡找到這些東西。當你收集好了之後，將它們帶到逐日者之島給日尖塔上的看井者。', '', '去找陽炎島的看井者索蘭尼亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8331 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8331, 'zhTW', '奧莉爾·金葉', '$N，雖然我們以為暮光之錘在希利蘇斯的運作已停頓下來…但是，我們錯了。隨著對他們連續的襲擊，我們發現有個更黑暗的力量也就是深淵議會，利用教派基地中點綴的秘法風石在控制著暮光之錘。$N，你的下一個任務，就是去對抗深淵議會。和塞納里奧城堡東邊區域的工匠奧莉爾·金葉談談。我們需要她的手藝。', '與塞納里奧城堡的奧莉爾·金葉談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8332 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8332, 'zhTW', '議會公爵', '我們認為應該可能使用一塊風石來伏擊一名深淵議會的公爵。前提是，需要有人通過風石來進行聯繫，並讓公爵確認你是暮光之錘的一名中層人員。$B$B因此我們需要暮光信徒身份勳章的複製品。我可以製作這樣一枚勳章，但是我需要一個大塊魔光裂片，還有深淵聖殿騎士所佩戴的紋章。$B$B把這些帶給我，然後我就可以完成剩下的工作了。', '帶1大塊魔光裂片和3個深淵紋章給塞納里奧城堡的奧莉爾·金葉。', '', '去希利蘇斯找塞納里奧要塞的奧莉爾·金葉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8333 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8333, 'zhTW', '身份勳章', '', '', '', '去找希利蘇斯的奧莉爾·金葉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8334 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8334, 'zhTW', '侵略', '在把你送到學校之前，我要你先立刻解決另一個任務。曾經幫助我們管理逐日者之島園藝的那些人都失控了。儘速處理掉他們，但是記住 - 他們已變得很有侵略性。就是這樣的侵略性讓我們不得不快點消滅這些曾經溫和的僕人們。$B$B我也不願意要你接下這個任務，但是為了生存逼不得已。我會為他們哀悼的。', '殺死7個看管者和7個野生看管者，再回到逐日者之島的蘭深·佩瑞隆那裡。', '', '去找永歌森林的蘭深·佩瑞隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8335 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8335, 'zhTW', '被流放的法蘭德倫', '我們之中有個背叛者住在西南邊的法薩瑞安學院頂端。$B$B法薩瑞安是他的名字，因為不聽我們的教師與長者的話，被趕出血精靈的土地。他是我們社會的害群之馬，因為他只知道滿足自己的魔法慾望。他不學習控制;是舊時自我的軀殼 - 鄙惡者之中的一員 - 他也是日尖塔的一個威脅。$B$B殺了他和他奴役的秘法怨靈。', '殺死8個秘法怨靈、2個腐敗的秘法怨靈和被流放的法蘭德倫;他們就在法薩瑞安學院裡面。將法蘭德倫的頭顱帶給逐日者之島的蘭深·佩瑞隆。', '', '去找永歌森林的蘭深·佩瑞隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8336 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8336, 'zhTW', '一把稜片', '很遺憾我們失去了島上許多生物的掌控權。這裡曾是適合讀書研究的安寧之地。現在我們只能盡力避免被我們自己的創造物攻擊!$B$B我要提供你一個獲得魔法利益的機會，只要你完成一些收集的工作就好。幫我從逐日者之島上使用魔法的生物那裡帶回來一堆秘法稜片，我就會在你身上施法，對你以後在島上的冒險很有助益。', '從島上任何使用法力的生物身上收集6個秘法稜片，再回到逐日者之島的秘法師艾薩納斯那裡。', '', '去找永歌森林的秘法師艾薩納斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8337 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8337, 'zhTW', '暫無內容', '', '', '', '去找永歌森林的奧術師伊塔納斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8338 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8338, 'zhTW', '腐敗的秘法稜片', '你在腐敗的秘法怨靈屍體上找到一個奇怪的晶化法力稜片。這個稜片和其他你看過的很不一樣，它又黑又邪惡的樣子和你拾取的鬼魂一個樣。握著它讓你有一種不自然的不詳預感。$B$B逐日者之島上的日尖塔有個瞭望台，這個稜片可能對裡面的秘法師海利恩有所用途。', '將腐敗的秘法稜片帶到逐日者之島給日尖塔瞭望台的秘法師海利恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8339 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8339, 'zhTW', 'Royalty of the Council <NYI> <TXT> UNUSED', '', '把物品帶給塞納里奧城堡的奧莉爾·金葉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8340 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8340, 'zhTW', 'Twilight Signet Ring <NYI> <TXT>', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8341, 'zhTW', '議會領主', '深淵議會的高階領主只有通過更大的風石才能召喚出來，而只有最高等級的暮光之錘官員才可以和他們說話。不過……我找到了進一步偽裝你並欺騙深淵領主的方法!$B$B我們要偽造一枚只有他們教派中最高級別的成員才擁有的暮光貴族之戒。如果你可以帶給我大塊魔光裂片和深淵徽記的話，我就可以幫你製作一個。', '帶5塊大而豔麗的裂片和3個深淵羽飾給塞納里奧城堡的奧莉爾·金葉。', '', '去希利蘇斯找塞納里奧要塞的奧莉爾·金葉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8342, 'zhTW', '暮光徽記之戒', '', '', '', '去找希利蘇斯的奧莉爾·金葉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8343, 'zhTW', '金葉的發現', '$N，奧莉爾·金葉認為她找到了一種召喚並擊敗深淵議會成員的方法!這樣的任務是十分危險的，但是你已經贏得了塞納里奧議會極大的尊重。如果有人可以完成這項任務，那麼這個人無疑就是你。祝你好運，$N。當你準備好之後就去和奧莉爾談話。', '與塞納里奧城堡的奧莉爾·金葉談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8344, 'zhTW', '源頭的窗口', '記住我的話，年輕人 – 這座島受到汙染，而且比天譴軍團的殘留力量更有影響力。$B$B我相信這島上有一種真正的惡魔存在。$B$B西方是法薩瑞安學院的尖塔。出沒那裡的秘法怨靈是惡魔力量來源的窗口。你要幫我把腐壞及未腐壞的怨靈精華都帶來。$B$B如果你照做，我會教你如何召喚一個小鬼 – 你身為術士的第一個小鬼。', '將4份怨靈精華和1份腐壞的怨靈精華帶到逐日者之島給日尖塔的召喚者泰利拉。', '', '去找永歌森林的召喚者泰利拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8345 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8345, 'zhTW', '達斯雷瑪神殿', '我日復一日站在這觀看，等待。我曾被指責太過沉溺於過去，當我注視著地平線時。但我堅定的相信，每一個到此拜訪的人都該尊敬那些犧牲所有的人，這樣他們才會持續下去。$B$B逐日者達斯雷瑪是我們第一個王。他帶領著我們自卡林多穿越大漩渦來到這裡。$B$B往西方尋找他的神殿，並閱讀神殿中的銘文後再回來找我。', '閱讀達斯雷瑪神殿上的銘文再回到逐日者之島找日尖塔的看井者索蘭尼亞。', '', '去找永歌森林的看井者索蘭尼亞。', '閱讀達斯雷瑪神殿', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8346 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8346, 'zhTW', '止不了的渴', '如果你在逐日者之島只能學會一件事，那就學會這件事吧 - 控制你對魔法的渴望。這是止不了的渴，$N - 你一定要透過法力吸取吸收能量才能生存，而你務必要控制自己透過秘法洪流釋放魔法的情況。失敗就會成為失落者其中之一……無助地上癮發狂。$B$B尋找島上有魔法的生物並汲取他們的法力。試著控制你對能量的渴望。當你吸飽足夠的能量後再回來找我。', '對有法力的生物使用你的法力吸取種族特長6次，再回到秘法師海利恩那裡。', '', '去找永歌森林的秘法師海利恩。', '吸取生物法力', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8347 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8347, 'zhTW', '幫助先驅者', '博學者伊羅娜要你前往銀月城幫助我們開墾那裡…當然，前提是你要先成功地解決法薩瑞安學院的情況。你沒有讓我們失望，$N。在你往南邊獵鷹之翼廣場的路上，你該與先驅者艾拉瑞恩談談。她就在離橋不遠的地方。先驅者負責處理大陸和這裡的貨物往來，既然你已證明了自己的機智，他們或許需要你的幫助。', '和先驅者艾拉瑞恩談談，她就在往南方逐日者之島的橋附近。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8348 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8348, 'zhTW', '公爵的徽記', '胡姆告訴我說你知道召喚深淵公爵的方法了!真是件了不起的事兒。$B$B還有什麼能稱得上是了不起的成就呢?打扁這些傢伙。如果你明白我在說什麼，你就該知道這會對他們的屬下帶來多大的衝擊。把他們的徽記帶回來作為證據。', '把深淵徽記帶給塞納里奧城堡的鮑爾·蠻鬃。', '', '去希利蘇斯找塞納里奧要塞的鮑爾·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8349 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8349, 'zhTW', '鮑爾·蠻鬃', '現在你有了勳章，並可以召喚深淵公爵，去和鮑爾·蠻鬃談談吧。他會派你去對付深淵議會。祝你好運，$N。如果你需要更多的勳章，那麼就來找我吧。', '與在塞納里奧城堡的鮑爾·蠻鬃談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8350 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8350, 'zhTW', '完成遞送', '又一個先驅者之死真是悲劇，但當我們接受任務時也接受了風險。日尖塔的博學者伊羅娜需要將這個包裹拿到獵鷹之翼廣場的旅店，並且越快越好。$B$B我們現在人手短缺，沒有人能掩護我們。$B$B我不騙你;如果你離開了安全的黎明小路，通往獵鷹之翼廣場的路會非常危險。你覺得你可以勝任嗎，$N?', '將伊羅娜的包裹送到永歌森林給獵鷹之翼廣場的旅店主人德拉尼歐。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8351 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8351, 'zhTW', '伯爾想說話', '現在你可以偽裝成暮光議會的成員了，我想鮑爾·蠻鬃一定想跟你談談。去見他吧，準備接受一項艱鉅的任務……', '與在塞納里奧城堡的鮑爾·蠻鬃談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8352 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8352, 'zhTW', '議會權杖', '胡姆和我剛才還談起你呢。他說你已經準備好跟深淵領主作戰了!$B$B我必須告訴你，這是一項非常危險的任務。你最好叫上支援人員。我並不是讓你帶上一兩個朋友，你需要的是一支做好充分的戰鬥準備的精英團隊。如果你的朋友跟你一樣出色，你們或許能打敗他!$B$B如果你打敗了深淵領主，和往常一樣，向我出示證據，我就會給你豐厚的獎勵。', '帶一支深淵權杖給塞納里奧城堡的鮑爾·蠻鬃。', '', '去希利蘇斯找塞納里奧要塞的鮑爾·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8353 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8353, 'zhTW', '學小雞，換糖果', '啊，跟一個生病的小孩子玩要糖果的惡作劇遊戲是吧？我要說的是，對四處要糖果的遊戲來說，你的年紀似乎大了點……$B$B嗯，我的糖果是一顆鐵爐堡薄荷糖，你得……你得學小雞咯咯叫！是的，小雞們喜歡薄荷糖……好吧，或許它們不喜歡……但是除非你學小雞叫，否則我不會給你薄荷糖的！$B$B好吧，$c，你準備好了沒？！我們開始吧！', '對旅店老闆火酒模仿小雞的動作並得到一顆鐵爐堡薄荷糖！', '', '去找丹莫羅的旅店老闆洛雷·火酒。', '為旅店老闆洛雷·火酒模仿小雞的動作', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8354 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8354, 'zhTW', '學小雞，換糖果', '啊，跟一個生病的小孩子玩要糖果的惡作劇遊戲是吧？我要說的是，對四處要糖果的遊戲來說，你的年紀似乎大了點……$B$B嗯，我的糖果是一顆幽暗城薄荷糖，你得……你得學小雞咯咯叫！是的，小雞們喜歡薄荷糖……好吧，或許它們不喜歡……但是除非你學小雞叫，否則我不會給你薄荷糖的！$B$B好吧，$c，你準備好了沒？！我們開始吧！', '對旅店老闆諾曼模仿小雞的動作並得到一顆幽暗城薄荷糖！', '', '去找提裏斯法林地的旅店老闆諾曼。', '為旅店老闆諾曼模仿小雞的動作', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8355 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8355, 'zhTW', '學火車，換糖果', '要糖果的惡作劇遊戲！哈哈！$B$B即使你正在做什麼高尚的事兒，比如為生病的小孩收集糖果之類的，我也不會輕易放過你。我有一顆諾姆瑞根橡皮糖要送給那個生病的孩子……如果你願意模仿火車聲音的話！哈哈，是的，這就是惡作劇！你要拿到水果糖，就得模仿火車的聲音！$B$B哢哢－嗚嗚，$c！', '對塔瓦斯德·基瑟爾做出火車的聲音，並交換你應得的諾姆瑞根橡皮軟糖！', '', '去鐵爐堡找秘法區的塔瓦斯德·基瑟爾。', '為塔瓦斯德模仿火車的聲音', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8356 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8356, 'zhTW', '顯肌肉，換糖果', '你……你的裝束真有趣。即使你心眼好，在陪一個生病的小孩子玩要糖果的惡作劇遊戲，恐怕我還是得要求你做點什麼！$B$B讓我想想……你穿的衣服……看起來非常奇怪……你得炫耀自己的肌肉！是的，就是現在，炫耀你的肌肉吧，強壯的$g男:女;$c！$B$B你必須炫耀肌肉，這樣我才會給你美味的暴風城杏仁糖。這可是萬聖節的糖果。', '對旅店老闆奧里森作展示肌肉的動作，並交換你應得的暴風城奶油杏仁花生糖！', '', '去找暴風城的旅店老闆奧里森。', '展示肌肉給旅店老闆奧里森看', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8357 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8357, 'zhTW', '跳跳舞，換糖果', '即使你在陪一個生病的小孩子玩要糖果的惡作劇遊戲，你也要做點什麼來換取糖果！傳統習俗可不能被破壞……$B$B我想一顆糖果的代價就是你得跳支舞！是的，讓我們看看你的舞姿！跳舞吧，我會給你美味的奶糖的！', '對旅店老闆塞琳尼跳舞，並交換你應得的達納蘇斯杏仁糖！', '', '去找達納蘇斯的旅店老闆塞琳尼。', '為旅店老闆塞琳尼跳舞', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8358, 'zhTW', '學火車，換糖果', '要糖果的惡作劇遊戲！哈哈！$B$B即使你正在做什麼高尚的事兒，比如為生病的小孩收集糖果之類的，我也不會輕易放過你。我有一顆暗矛橡皮糖要送給那個生病的孩子……如果你願意模仿火車聲音的話！哈哈，是的，這就是惡作劇！你要拿到水果糖，就得模仿火車的聲音！$B$B哢哢－嗚嗚，$c！', '對卡利·雷米克做出火車的聲音，並交換你應得的暗矛橡皮軟糖！', '', '去杜洛塔找森金村的卡利·雷米克。', '為卡利·雷米克模仿火車的聲音', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8359, 'zhTW', '顯肌肉，換糖果', '你……你的裝束真有趣。即使你心眼好，在陪一個生病的小孩子玩要糖果的惡作劇遊戲，恐怕我還是得要求你做點什麼！$B$B讓我想想……你穿的衣服……看起來非常奇怪……你得炫耀自己的肌肉！是的，就是現在，炫耀你的肌肉吧，強壯的$g男:女;$c！$B$B你必須炫耀肌肉，這樣我才會給你美味的奧格瑪軟糖。這可是萬聖節的糖果。', '對旅店老闆格雷什卡作展示肌肉的動作，並交換你應得的奧格瑪奶油杏仁花生糖！', '', '去找奧格瑪的旅店老闆格雷什卡。', '向旅店老闆格雷什卡炫耀肌肉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8360, 'zhTW', '跳跳舞，換糖果', '即使你在陪一個生病的小孩子玩要糖果的惡作劇遊戲，你也要做點什麼來換取糖果！傳統習俗可不能被破壞……$B$B我想一顆糖果的代價就是你得跳支舞！是的，讓我們看看你的舞姿！跳舞吧，我會給你美味的奶糖的！', '對旅店老闆帕拉跳舞，並交換你應得的雷霆崖杏仁糖！', '', '去找雷霆崖的旅店老闆帕拉。', '跳舞給旅店老闆帕拉看', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8361, 'zhTW', '深淵聯絡', '我們見過暮光之錘的信徒舉行儀式召喚強大的元素生物。我們不知道這些生物是他們崇拜的物件還是他們準備通過這些生物來和更加強大的力量進行溝通。有一件事是可以肯定的:他們聽從這些元素生物的命令。$B$B我需要你找到一名深淵聖殿騎士，然後擊敗他!擒賊先擒王，當你完成任務之後把證明帶回來。', '在希利蘇斯塞納里奧城堡的鮑爾·蠻鬃希望你能摧毀深淵聖殿騎士並且將深淵紋章作為行動證明帶回去給他。', '', '去希利蘇斯找塞納里奧要塞的鮑爾·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8362, 'zhTW', '深淵紋章', '', '', '', '去找希利蘇斯的鮑爾·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8363 AND `locale` = 'zhTW';
