DELETE FROM `quest_template_locale` WHERE `ID` = 8364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8364, 'zhTW', '深淵節杖', '', '', '', '去找希利蘇斯的鮑爾·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8365, 'zhTW', '海賊的帽子!', '你是公司派來幫忙的?我相信你可以的。聽好了，$c。就如你所知的那樣，我是艾澤拉斯上層社會最頂極服飾的提供者。皇帝和皇后，酋長和他們部落所稱的皇后，他們所有的穿著都由我親自推薦。他們可是為此付出了大價錢，而且他們確實得到了最好的服飾。$B$B接下來就是你該做的。你應該去落帆海灣，無論你用什麼辦法，都要去弄到儘量多的海賊的帽子。你認為你可以完成這個任務嗎?', '塔納利斯熱砂港的傲慢的店主要你去幫他收集20頂南海海賊帽。', '', '去塔納利斯找熱砂港的傲慢的店主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8366, 'zhTW', '南海復仇', '啊!他們想要我完成一個不可能完成的任務!$B$B熱砂企業想要我給南海海賊一些教訓。問題是我不能同時在兩個地方;我必須待在這裏守護和平。$B$B最近，那些海賊似乎忘記了熱砂企業給他們的保護費。所以我希望你可以代表我去給他們洗洗腦子。$B$B你可以在這裏南邊不遠的落帆海灣找到他們。謝謝你，$N，我欠你的人情!', '塔納利斯熱砂港的安全主管比格維茲要你去幹掉10個南海海賊、10個南海劫掠者、10個南海碼頭工人和10個南海劍客。', '', '去塔納利斯找熱砂港的安全主管比格維茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8367, 'zhTW', '無上的榮耀', '與聯盟作戰是為部落效勞的莫大榮耀！那些在各條戰線上和聯盟作戰的士兵是我們最偉大的成員。我們要消滅我們的對手，而不是僅僅進行小規模的遭遇戰，我們要打精心準備的大戰。$B$B去每一條戰線上消滅聯盟吧！為了榮耀！為了部落！', '在每個戰場上都取得1枚榮譽獎章，並將它們交給任意部落主城或撒塔斯城中的部落戰爭使者。', '', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8368, 'zhTW', '峽谷之戰', '我們在戰歌峽谷對銀翼哨兵展開攻勢，這一戰役至關重要。聯盟以保護這片不屬於他們的森林為由，妄圖從部落手中奪取我們最大的伐木場。$B$B別讓他們的妄想成為事實，$N！為了部落，證明你的價值！成功之後再回到我這兒來。', '將3枚戰歌榮譽獎章交給戰場外的部落戰爭使者。', '', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8369, 'zhTW', '奧特蘭克的入侵者', '聽好了，$N。不管你以前聽說奧特蘭克山谷的戰鬥進行得怎麼樣，只有一件事情是真的：雷矛探險隊侵入了霜狼的領地。如果有一天我們可以讓聯盟從容地侵佔部落的領地，那麼我將會在那一天蒙羞自殺。出發吧，幹掉入侵者！', '把3枚奧特蘭克山谷榮譽獎章交給戰場外的部落戰爭使者。', '', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8370, 'zhTW', '資源競賽', '我們和聯盟的衝突已經上升為一場真正的戰爭，不久之後戰爭就將全面打響。$B$B對於阿拉希盆地的爭奪就是一個很好的開戰理由。要麼就是聯盟佔據它，並用其對付我們；或者就是我們佔據它，然後用來對付聯盟。幫助污染者保持這場資源競賽上的優勢吧，$N！', '將3枚阿拉希盆地榮譽獎章交給戰場外的部落戰爭使者。', '', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8371, 'zhTW', '共同的努力', '我們並不是在獨自與部落交戰，$g小夥子:小姑娘;。$B$B如果我們可以取得勝利，那麼我們就可以使用部落的資源來在其它的戰場上對抗他們。反之，如果我們輸掉了這場戰爭，那麼在其它的戰場上，部落將會佔有優勢。$B$B聯盟需要更多你這種身經百戰、意志堅定的老兵！$N，當你在所有戰場上都與部落交戰之後再回到我這裡。', '在每個戰場上都取得1枚榮譽獎章，並將它們交給任意聯盟主城、達拉然或撒塔斯城中的聯盟准將。', '', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8372, 'zhTW', '自然屏障', '銀翼哨兵正在和戰歌前鋒部隊爭奪這片森林。當然，銀翼哨兵保護森林的原因並非只有熱愛大自然這條理由。$B$B梣谷的森林對我們來說是一層天然的戰略屏障，可以抵抗大規模的進攻。如果沒有這片森林的話，阿斯特蘭納很快就會完全暴露在貧瘠之地的攻擊部隊面前。你願意參加對抗戰歌前鋒的戰鬥嗎？為了聯盟！', '將3枚戰歌峽谷榮譽獎章交給戰場外的聯盟准將。', '', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8373 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8373, 'zhTW', '松木的力量', '我對萬鬼節最憎恨的一點就是被遺忘者用在南海鎮的臭彈。誰知道這些節日慶祝用的東西會搞得這樣臭氣薰天……$B$B在萬鬼節期間，使用這個清潔器來把部落的雜碎們丟在村莊裏的臭彈處理掉吧。它使用了松木的力量來消除那些難聞的味道。$B$B你是否願意加入清潔南海鎮的行列？我會用萬鬼節禮物來作為回報的。', '使用臭彈清潔器來把散落在南海鎮的被遺忘者臭彈處理掉。當任務完成之後，回到南海鎮的哈特曼中士那裏。', '清理丟在南岸的臭氣彈！', '去希爾斯布萊德丘陵找南海鎮的哈特曼中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8374, 'zhTW', '戰爭的動力', '要取得戰爭的勝利，我們要做的並不僅僅是簡單地打敗敵人，勝利的關鍵往往取決於雙方的戰爭資源。$B$B阿拉希盆地蘊藏著大量物資，部落和聯盟都想搶先奪取這些資源。$B$B如果聯盟獲勝，我們的軍隊將獲得大量的劍和矛。如果部落獲勝，這些武器也一樣會被造出來，只不過是由部落的士兵拿在手裏，指著我們!去協助阿拉希盆地的聯盟吧，$N。', '將3枚阿拉希盆地榮譽獎章交給戰場外的聯盟准將。', '', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8375, 'zhTW', '銘記奧特蘭克！', '不要搞錯了，$N。部落認為奧特蘭克山谷是霜狼氏族的領地，這種看法是很正確的。$B$B你看，雷矛探險隊來這裏是為了和平地搜索礦石和遺跡，而霜狼對此的反應卻極其粗暴和不文明，這是聯盟所沒有預想到的。$B$B讓我們為那些被偷襲的勇敢的矮人默哀吧。現在出發，$c，參加奧特蘭克山谷的大戰。為了聯盟！', '把3枚奧特蘭克山谷榮譽獎章交給戰場外的聯盟准將。', '', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8376 AND `locale` = 'zhTW';
