INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8383, 'zhTW', '銘記奧特蘭克！', '', '奧特蘭克山谷的戰鬥正在激烈地進行中，$N！你有沒有完成你應盡的職責，$N？', '', '去找聯盟准將。', '', '', '', '', 0);
