INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8385, 'zhTW', '共同的努力', '', '啊，$N。我希望你在各個戰場的前線傳授你的經驗。許多剛剛來到戰場上的小夥子和小姑娘都非常尊敬你這樣的老兵。', '', '去找聯盟准將。', '', '', '', '', 0);
