INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8387, 'zhTW', '奧特蘭克的入侵者', '', '奧特蘭克山谷的戰鬥正在激烈地進行中！你必須回到奧特蘭克山谷，把入侵者趕出霜狼氏族的領地，$N！', '', '去找部落戰爭使者。', '', '', '', '', 0);
