INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8393, 'zhTW', '戰爭的動力', '要取得戰爭的勝利，我們要做的並不僅僅是簡單地打敗敵人，勝利的關鍵往往取決於雙方的戰爭資源。$B$B阿拉希盆地蘊藏著大量物資，部落和聯盟都想搶先奪取這些資源。$B$B如果聯盟獲勝，我們的軍隊將獲得大量的劍和矛。如果部落獲勝，這些武器也一樣會被造出來，只不過是由部落的士兵拿在手裡，指著我們!去協助阿拉希盆地的聯盟吧，$N。', '將3枚阿拉希盆地榮譽獎章交給戰場外的聯盟准將。', '', '去找聯盟准將。', '', '', '', '', 0);
