INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8399, 'zhTW', '自然屏障', '銀翼哨兵正在和戰歌前鋒部隊爭奪這片森林。當然，銀翼哨兵保護森林的原因並非只有熱愛大自然這條理由。$B$B梣谷的森林對我們來說是一層天然的戰略屏障，可以抵抗大規模的進攻。如果沒有這片森林的話，阿斯特蘭納很快就會完全暴露在貧瘠之地的攻擊部隊面前。你願意參加對抗戰歌前鋒的戰鬥嗎？為了聯盟！', '將3枚戰歌峽谷榮譽獎章交給戰場外的聯盟准將。', '', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8400 AND `locale` = 'zhTW';
