INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8509, 'zhTW', '聯盟需要阿薩斯之淚！', '我會簡要地告訴你重點，$c。聯盟需要大量的阿薩斯之淚來準備安其拉戰爭。不要問我它們是用來做什麼的，我並不關心這個。但是我需要你收集儘可能多地這種草藥，並把它們交給我。你願意這樣做嗎？', '把20棵阿薩斯之淚交給鐵爐堡軍事區計程車官長戈麥恩。', '', '去找丹莫洛計程車官長戈麥恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8510, 'zhTW', '聯盟需要更多阿薩斯之淚！', '我會簡要地告訴你重點，$c。聯盟需要大量的阿薩斯之淚來準備安其拉戰爭。不要問我它們是用來做什麼的，我並不關心這個。但是我需要你收集儘可能多地這種草藥，並把它們交給我。你願意這樣做嗎？', '把20棵阿薩斯之淚交給鐵爐堡軍事區計程車官長戈麥恩。', '', '去找丹莫洛計程車官長戈麥恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8511, 'zhTW', '聯盟需要輕皮！', '我們系列歷代都是著名的剝皮匠，$c。這就是聯盟要求我們為了安其拉之戰而收集輕皮的原因。我在這裡的工作是確保皮革經過正確的處理，準備投入使用。但是我們需要你的幫助。$B$B因為我不得不留在這裡，所以我需要你去幫忙收集皮革，然後把它們交給我。你覺得怎麼樣，$g小夥子:小姑娘;，你會幫我嗎？', '把10塊輕皮交給丹莫洛飛機場的波尼·碎石。', '', '去找丹莫洛的波尼·碎石。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8512, 'zhTW', '聯盟需要更多輕皮！', '很高興再見到你，$N。顯然我們需要更多輕皮來製作各種戰爭要用的東西。如果你能再幫我帶來10張輕皮就太完美了。', '帶10張輕皮給丹莫洛飛機場的波尼·碎石。', '', '去找丹莫洛的波尼·碎石。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8513 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8513, 'zhTW', '聯盟需要中皮！', '長官！我正在負責收集所有戰爭所需的中皮。如果你有足夠的精力和資金來收集中皮的話，那麼請把它們交給我。我們希望有更多像你這樣的人來幫助我們。', '把10塊中皮交給鐵爐堡軍事區的下士波特。', '', '去找丹莫洛的列兵波特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8514 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8514, 'zhTW', '聯盟需要更多中皮！', '是的$g 先生 : 女士;，看來目前我們已經收集了$2063w張中皮。我知道這個數量很龐大，但如果你願意，我可以藉由你的幫忙讓我的配額減少一點。', '帶10張中皮給丹莫洛飛機場的士兵波特。', '', '去找丹莫洛的列兵波特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8515 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8515, 'zhTW', '聯盟需要厚皮！', '這一定會很有意思！$c，安其拉之戰迫在眉睫，我正在負責收集厚皮。我們需要大量的儲備，但是首先我們必須先從第一批開始。總之這就是你來這裡的原因。$B$B那麼，你是否可以幫我帶來一些質量不錯的厚皮呢？可以嗎，可以嗎？', '把10塊厚皮交給鐵爐堡軍事區的瑪塔·鋼軸。', '', '去找鐵爐堡軍事區的瑪爾塔·鋼軸。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8516 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8516, 'zhTW', '聯盟需要更多厚皮！', '沒錯，存貨仍然不夠。$N，我們仍未達到理想的$2071w張重皮。想想我們能用重皮做的所有東西！各種護甲和武器。蒸氣坦克的零件和步槍瞄準器！工程學護目鏡，而且如果到最後我們還有剩下，可以把它們交給部落的齊柏林飛艇！$B$B你會為我帶更多的重皮回來嗎？', '帶10張厚皮給丹莫洛飛機場的瑪塔·鋼軸。', '', '去找鐵爐堡軍事區的瑪爾塔·鋼軸。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8517 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8517, 'zhTW', '聯盟需要亞麻繃帶！', '安其拉的戰爭將會持續很長時間，並且會非常殘酷。顯然聯盟尋求你們這些冒險者的幫助是很明智的選擇，我們需要收集足夠的資源來贏得這場戰爭。$B$B我在這裡收集戰爭所需要的亞麻繃帶，希望你可以幫助我們達成目標。現在一切物資都很緊缺，但是至少亞麻繃帶還是比較容易製作的。你願意幫助我們嗎，$c？', '把20卷亞麻繃帶交給鐵爐堡軍事區的哨兵塞爾瓦·銀空。', '', '去找丹莫洛的哨兵塞爾瓦·銀空。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8518, 'zhTW', '聯盟需要更多亞麻繃帶！', '我非常驚奇有那麼多無私的人將私慾拋於一旁。$c，我還需要收集更多的亞麻繃帶，直到完成我的指標。你是否可以再幫我收集一些亞麻繃帶呢？', '把20卷亞麻繃帶交給丹莫洛飛機場的哨兵塞爾瓦·銀空。', '', '去找丹莫洛的哨兵塞爾瓦·銀空。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8519 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8519, 'zhTW', '往日的回憶', '當你恢復鎮靜並重新彙集目光的時候，你發現有些東西從水晶之內往外瞪著。透過進一步的觀察，你所看到的是過去……一段記憶……很久之前就遺忘的記憶。', '瞭解所以可以的過去的事情，然後和塔納利斯時光之穴的阿納克洛斯談談。', '流沙之戰', '去塔納利斯找時光之穴的阿納克洛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8520 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8520, 'zhTW', '聯盟需要絲質繃帶！', '安其拉的戰爭陰雲正籠罩著大地，我們需要盡力讓我們的士兵做好準備。現在我正在做的就是這件事情：負責收集足夠多的絲質繃帶。$B$B你可以幫幫我嗎，$c？', '把20卷絲質繃帶交給鐵爐堡軍事區的女護士斯通菲爾德。', '', '去找丹莫洛的女護士斯通菲爾德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8521, 'zhTW', '聯盟需要更多絲質繃帶！', '你能再次幫我真是太好了，$c。看來我們已經收集了$2082w個絲質繃帶，所以我們需要更多繃帶。', '帶20個絲質繃帶給丹莫洛飛機場的護士斯通菲爾德。', '', '去找丹莫洛的女護士斯通菲爾德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8522 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8522, 'zhTW', '聯盟需要符文布繃帶！', '關於戰爭的走向，你可以隨意評說，$c，但是現在這場戰爭已經箭在弦上。看看你周圍的朋友和家人，問問你自己，如果戰爭真的爆發，你會為此做些什麼，你周圍的人會一定會盡其所能地努力生存下來。$B$B現在，我在這裡收集符文布繃帶。你願意捐贈一些嗎？', '把20卷符文布繃帶交給鐵爐堡軍事區的守護者莫沙·月影。', '', '去找鐵爐堡軍事區的守護者莫沙·月影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8523 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8523, 'zhTW', '聯盟需要更多符文布繃帶！', '又是討論緊急事件的時候了，$c。我再次感謝你之前所作的努力；不是每個人都能如此無私奉獻。但是我們仍然很多事要完成。$B$B$N，你可以再去收集符文布繃帶並拿回來這裡給我嗎？', '帶20個符文布繃帶給丹莫洛飛機場的守護者月影。', '', '去找鐵爐堡軍事區的守護者莫沙·月影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8524 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8524, 'zhTW', '聯盟需要彩鰭魚！', '你好，朋友！你不認為士兵也和別人一樣需要吃飯嗎？你當然會贊同這一點。我110%地同意你的看法！很高興我們達成了一致。現在我要你做的就是去釣很多很多新鮮的彩鰭魚，然後把它們燒好，帶到我這裡來。嗯，我彷彿已經可以嚐到它們了……', '把20條彩鰭魚交給鐵爐堡軍事區的美食家斯里克。', '', '去找丹莫洛的美食家斯里克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8525 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8525, 'zhTW', '聯盟需要更多彩鰭魚！', '你好，朋友！你不認為士兵也和別人一樣需要吃飯嗎？你當然會贊同這一點。我110%地同意你的看法！很高興我們達成了一致。現在我要你做的就是去釣很多很多新鮮的彩鰭魚，然後把它們燒好，帶到我這裡來。嗯，我彷彿已經可以嚐到它們了……', '把20條彩鰭魚交給鐵爐堡軍事區的美食家斯里克。', '', '去找丹莫洛的美食家斯里克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8526 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8526, 'zhTW', '聯盟需要烤迅猛龍肉！', '嘿，最近過得怎麼樣啊，$c？我看你好像有興趣幫即將開始的安其拉戰爭收集食品物資。我爸爸覺得我來這裡幫忙是一個學習的好方法。這可是個大錯誤，我根本不喜歡吃肉。$B$B不管怎麼樣，如果你願意的話，請帶給我大量的烤迅猛龍肉。顯然這是所有士兵都想要的美食。', '把20塊烤迅猛龍肉交給鐵爐堡軍事區的薩拉·塞維斯。', '', '去找丹莫洛的薩拉·塞維斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8527 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8527, 'zhTW', '聯盟需要更多烤迅猛龍肉！', '嘿，最近過得怎麼樣啊，$c？我看你好像有興趣幫即將開始的安其拉戰爭收集食品物資。我爸爸覺得我來這裡幫忙是一個學習的好方法。這可是個大錯誤，我根本不喜歡吃肉。不管怎麼樣，如果你願意的話，請帶給我大量的烤迅猛龍肉。顯然這是所有士兵都想要的美食。', '把20塊烤迅猛龍肉交給鐵爐堡軍事區的薩拉·塞維斯。', '', '去找鐵爐堡軍事區的薩拉·塞維斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8528 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8528, 'zhTW', '聯盟需要斑點黃尾魚！', '雖然看起來燒魚算不上什麼英雄事蹟，但是絕對不要低估戰前準備的價值，年輕的$c。士兵和其他人一樣需要吃飯，我們在這裡要準備的可是安其拉戰爭開始後所必需的東西。$B$B為此，我在這裡收集斑點黃尾魚，一種適合於儲存並且可以用於多種菜餚的物資。另外它也沒有其它鹹水魚的那種難聞的味道。你願意幫助我嗎？', '把20條斑點黃尾魚交給鐵爐堡軍事區的女獵手蕾爾·急流。', '', '去找鐵爐堡軍事區的女獵手蕾爾·急流。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8529 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8529, 'zhTW', '聯盟需要更多斑點黃尾魚！', '如果你願意我想派你再去捕一批斑點黃尾魚，$N。我想你有了第一次的經驗，這次捕魚一定會更快更容易。你願意嗎？', '帶20條斑點黃尾魚給丹莫洛飛機場的女獵手蕾爾·急流。', '', '去找鐵爐堡軍事區的女獵手蕾爾·急流。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8530 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8530, 'zhTW', '聯盟需要熔火之石！', '$c，我需要你的幫助。在熔火之心有一種被稱作熔火之石的石頭，我們需要儲備一些熔火之石來準備安其拉之戰。我瞭解到鐵匠和工程師都可以用它製作很多東西，所以我們需要你的幫助。你必須進入熔火之心,收集儘可能多的熔火之石。當然，你最好是和39名戰友一起去那裡並肩作戰。', '把50塊熔火之石交給丹莫洛飛機場的指揮官漢默·石錘。', '', '去艾薩拉找怒水河的指揮官漢默·石錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8531 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8531, 'zhTW', '聯盟需要更多熔火之石！', '感謝你把它們交給我，$N。如果你和你的朋友還能弄到這些東西的話，請繼續幫我收集它們。你說怎麼樣？', '把50塊熔火之石交給丹莫洛飛機場的指揮官漢默·石錘。', '', '去找杜洛塔的指揮官漢默·石錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8532 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8532, 'zhTW', '部落需要銅錠！', '很高興你來幫助我們。並不是所有人都能搞清楚我所需要的東西是什麼，所以我要確保你不犯錯誤。我需要的是銅錠，不是銅礦石。我們沒有時間自己進行熔鍊，希望你可以幫助我們。你可以辦到吧，$c？', '把20塊銅錠交給奧格瑪精神谷的礦工克羅威爾。', '', '去找杜洛塔的礦工克羅威爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8533 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8533, 'zhTW', '部落需要更多銅錠！', '這麼快就回來了？你很快就會成為一個真正的礦工了，$c。那麼，你已經知道怎麼鑽孔了；我需要你出去幫我挖掘一堆銅礦，熔解它們做成銅錠再帶回來給我。我知道你能辦到，問題是，你願意嗎？', '帶20個銅錠給杜洛塔的礦工克羅威爾。', '', '去找杜洛塔的礦工克羅威爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8534 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8534, 'zhTW', '佐拉蟲巢偵查報告', '我們派出了最好的斥候深入異種蟲類的巢穴收集情報。艾澤奈爾這幾天來一直在監視佐拉蟲巢，去找到她，拿回她的書面報告。我們需要這些情報來制定戰術，要儘快，$n。', '在佐拉蟲巢內找到塞納里奧斥候艾澤奈爾，然後把佐拉蟲巢偵查報告交給塞納里奧要塞的喚風者傲角。你還必須隨身帶著戰術任務簡報 VI才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的喚風者傲角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8535 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8535, 'zhTW', '蒼白聖殿騎士', '暮光之錘和深淵議會之間的聯絡看來比我們想像的還要意義重大。$B$B根據可靠情報，那個被稱為蒼白聖殿騎士的元素領主將要策動暮光之錘對塞納里奧要塞實施一次大規模的攻擊。設法把他引誘出來，然後擊殺他。', '設法召喚並擊殺蒼白聖殿騎士，然後向塞納里奧要塞的鮑爾·蠻鬃覆命。', '', '去希利蘇斯找塞納里奧要塞的鮑爾·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8536 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8536, 'zhTW', '土色聖殿騎士', '暮光之錘和他們所膜拜的元素生物對我們在希利蘇斯地區的行動是個不小的威脅。安其拉蟲牆內的敵人還在虎視眈眈，所以我們絕對不能對暮光之錘的勢力掉以輕心。$B$B想辦法召喚並摧毀一名土色聖殿騎士，然後向鮑爾·蠻鬃彙報。', '召喚並殺死一名土色聖殿騎士，然後向塞納里奧要塞的鮑爾·蠻鬃覆命。你還必須隨身帶著戰術任務簡報 III才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的鮑爾·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8537 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8537, 'zhTW', '赤紅聖殿騎士', '暮光之錘和深淵議會之間的聯絡看來比我們想像的還要意義重大。$B$B根據可靠情報，那個被稱作赤紅聖殿騎士的元素領主將要策動暮光之錘對塞納里奧要塞實施一次大規模的攻擊。設法把他引誘出來，然後擊殺他。', '設法召喚並擊殺赤紅聖殿騎士，然後向塞納里奧要塞的鮑爾·蠻鬃覆命。', '', '去希利蘇斯找塞納里奧要塞的鮑爾·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8538 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8538, 'zhTW', '四個公爵', '暮光之錘和深淵議會的連結證實比我們預期的還重要。$B$B人們相信被稱為深淵聖殿騎士的元素貴族，是支配塞納里奧要塞暮光之錘祭司大規模攻擊的主導力量之一。想辦法將他們引誘到我們的世界來並摧毀他們！$B$B你往日的貢獻和成功使我們決定派你來執行這項任務。相信你可以輕鬆完成。', '設法召喚並擊殺辛德爾公爵、深淵公爵、微風公爵和裂石公爵，然後向塞納里奧要塞的指揮官瑪爾利斯覆命。', '', '去希利蘇斯找塞納里奧要塞的指揮官瑪爾利斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8539 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8539, 'zhTW', '目標：佐拉雌蠍', '我們需要援軍進攻佐拉蟲巢。你的主要目標是那些佐拉雌蠍，當你的任務完成之後就去向指揮官瑪爾利斯報告。', '擊殺30只佐拉雌蠍，然後向塞納里奧要塞的指揮官瑪爾利斯覆命。你還必須帶著作戰任務簡報 V才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的指揮官瑪爾利斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8540 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8540, 'zhTW', '衛兵的靴子', '塞納里奧城堡守衛的坐騎軍師缺少精製秘銀戰靴。取得一批戰靴並立即送給塞納里奧城堡的維斯·庫魯茲隊長。', '將3雙精製秘銀戰靴帶到希利蘇斯給塞納里奧城堡的守衛隊長維斯·庫魯茲。你還必須將後勤任務簡報 II帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的維斯·庫魯茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8541, 'zhTW', '衛兵的砂輪', '塞納里奧城堡守衛的守衛面臨砂輪短缺。取得一批砂輪並立即送給塞納里奧城堡的維斯·庫魯茲隊長。', '將10個緻密砂輪，10個堅固的砂輪和10個重砂輪帶到希利蘇斯給塞納里奧城堡的守衛隊長維斯·庫魯茲。你還必須將後勤任務簡報 III帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的維斯·庫魯茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8542, 'zhTW', '部落需要錫錠！', '為了部落，$r，我沒有時間解釋一遍給你聽。我們即將在安其拉開戰，但是首先長官要我們做一件叫做「準備」的事。這表示我需要你去收集錫錠。我想我需要的數字很龐大。B$B你還在這裡幹嘛?', '帶20個錫錠給奧格瑪精神谷的蠻兵瑪烏格。', '', '去找奧格瑪精神谷的步兵瑪烏格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8543 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8543, 'zhTW', '部落需要更多錫錠！', '很好，我看的出你對這場戰爭很用心。我有點期盼戰爭可以趕快開始，我想你應該也是一樣，$c。當戰爭開始時一定會是很光榮的。部落這在希利蘇斯沙漠的塵土上奔馳著，手上拿著武器，衝鋒陷陣在無數的蟲群之中。總有一天將會取得極大的榮耀!$B$B哈!但是首先我們需要錫錠。真有趣，這樣的小東西卻可以帶來巨大的不同，你說不是嗎?', '帶20個錫錠給杜洛塔的蠻兵瑪烏格。', '', '去找奧格瑪精神谷的步兵瑪烏格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8544 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8544, 'zhTW', '征服者的肩甲', '據說我們之中那個被人類種族穿戴的華麗肩鎧已成為與龍翼競爭的工具了。$B$B幫我把最高等其拉領導者穿戴的護甲弄來，然後我就能將它們做成一套比奈法利安翅膀更可怕的肩鎧了!', '將其拉命令束腕、2個夜晚塑像、5隻石甲蟲和5隻泥土甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到中立的聲望值才能完成這個任務。', '', '去找安其拉的安多葛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8545 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8545, 'zhTW', '部落需要秘銀錠！', '$c，戰爭就要來臨而我們唯一能做的事就是做好準備。這就是我們要互相幫忙的時候了。告訴你，他們叫我負責收集所有製作必備品需要的秘銀錠。而我還需要更多!$B$B，所以，我希望你可以離開這裡幫我們挖一些秘銀來，然後將它們熔製成錠。你可以幫我們這個忙嗎?', '帶20個秘銀錠給奧格瑪精神谷的資深士官克拉恩。', '', '去杜洛塔找軍士長克拉恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8546 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8546, 'zhTW', '部落需要更多秘銀錠！', '', '', '', '去杜洛塔找軍士長克拉恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8547 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8547, 'zhTW', '歡迎！', '歡迎來到魔獸世界!$B$B為了感謝您購買魔獸世界典藏版，請將這張禮券交給獵鷹之翼廣場的瑪希拉·晨星。您將得到一份特別的禮物:陪伴您踏上冒險旅途的小寵物!$B$B再次感謝您的支持，請盡情享受魔獸世界的樂趣吧!', '將獵鷹之翼廣場禮品券帶到獵鷹之翼廣場的日尖塔給瑪希拉·晨星。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8548, 'zhTW', '志願兵的裝備', '$n，你已展現與我們結盟對抗敵人的偉大決心。$B$B作為更進一步的鼓勵，我要給你一項塞納里奧議會給我們親密盟友的獎勵。$B$B我會希望你在這之前先完成一些任務，但對你這種人而言應該不是問題。', '將5個塞納里奧作戰徽章，3個塞納里奧後勤徽章，和7個塞納里奧戰術徽章帶到希利蘇斯給塞納里奧城堡的瓦古斯。你還必須在塞納里奧議會達到友好聲望值才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的瓦古斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8549 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8549, 'zhTW', '部落需要寧神花！', '據說每個世代都必須面臨一個決定性的試驗。我擔心安其拉之戰對我們的毅力而言是個嚴酷的考驗。所以我們要充分準備，並藉此了解我們的實力。$B$B我已經自願幫忙部落收集寧神花，然後它們就能被拿來製作戰爭用的藥劑。我希望你能給我一些支援，我需要你去帶回大量的草藥給我。你能幫我嗎，$c?', '帶20個寧神花給奧格瑪精神谷的草藥學家波德·飛羽。', '', '去找奧格瑪精神谷的草藥學家波德·飛羽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8550 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8550, 'zhTW', '部落需要更多寧神花！', '', '', '', '去找奧格瑪精神谷的草藥學家波德·飛羽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8551 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8551, 'zhTW', '船長的箱子', '我過去在一條專跑從這裡到卡林多的棘齒城的航線上幹過。我是個很優秀也很有名望的船長。$B$B直到……$B$B那些該死的海巨人毀了我的生活!他們打沉了我的船，殺光了我的水手，把我丟在一條救生艇上，讓我漂回了藏寶海灣。還有，其中一個名叫高拉什的巨人還把我的箱子給偷走了，他說要拿這東西當鼻煙盒，簡直是神經病!$B$B我聽說有人看見高拉什最近在東邊的海岸一帶閒逛。找到他，把我的箱子給搶回來!快去，你會得到一位船長的敬意的。', '將斯莫特的箱子交給藏寶海灣的海克拜瑞·斯莫特。', '', '去荊棘谷找藏寶海灣的海克拜瑞·斯莫特船長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8552 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8552, 'zhTW', '刺著字母的束帶', '這條精緻的束帶的邊上刺著兩個字母「HS」。', '將刺著字母的束帶還給他的主人。', '', '去荊棘谷找藏寶海灣刺著字母的腰帶的主人。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8553 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8553, 'zhTW', '船長的彎刀', '我的第一條船被那些海巨人們搞沉了之後，我只好買了第二艘，而且給它起名為“斯莫特的復仇”。我為它配備了新的裝備和船員，並出發去尋找那些該死的巨人。我找到了他們，但……他們又一次擊敗了我們。他們把“斯莫特的復仇”號給打成了碎片，船員也幾乎被他們殺光了，但那幫混蛋卻把我丟在了一條救生艇上，讓我一個人漂了回來。$B$B這次，那些海巨人中的另外一個偷了我的彎刀。$B$B到奈古拉什那裡去把我的佩刀給搶回來！$B$B去和斯普羅格談談吧。他本來是“斯莫特的復仇”號上的廚子，沉船的時候他也倖存了下來，我想他能幫你們找到那些巨人。', '與斯普羅格談話。', '', '去荊棘谷的藏寶海灣找斯普羅格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8554 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8554, 'zhTW', '挑戰奈古拉什', '奈古拉什總是一副隨時準備把一切都吞下去充饑的樣子。$B$B那些巨人襲擊我們的船的時候，奈古拉什直接衝向了我的廚房，不過他可不像其他巨人那樣喜歡吃人。奈古拉什要的是酒……還有我秘制的燒烤禿鷲翅膀。嘿，這可都是我的拿手菜，我當年可是跑到荒蕪之地才弄到這食譜的!$B$B如果你想把奈古拉什給引出來，只要用點酒再加上一碟烤翅就行啦。把這些東西放進我們當初丟在東南邊海岸上的救生艇裡，然後你就等著奈古拉什聞到食物的味兒乖乖上鉤吧!', '將10塊燒烤禿鷲翅膀和5瓶密林葡萄酒帶到斯莫特船長的救生艇上去。然後殺死奈古拉什，將斯莫特的彎刀交給荊棘谷的斯莫特船長。', '', '去荊棘谷找藏寶海灣的海克拜瑞·斯莫特船長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8555 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8555, 'zhTW', '守護之龍', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8556 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8556, 'zhTW', '不屈力量之戒', '謠傳其拉將領所帶的徽戒具有強大可怕的力量，上面裝飾用的墮落寶石，理論上應該要替換成更純淨的材質，才可以讓戒指呈現出一種不腐敗的形象。$B$B這些寶石能完美搭配著其拉塑像，因為他們的品質最頂級了。$B$B帶給我徽戒跟塑像，我就幫你製作一個強大力量的戒指，$c。', '帶1枚其拉將領戒指、2個柔光塑像、5隻青銅甲蟲和5隻象牙甲蟲給希利蘇斯的喚風者耶薩德拉。你還需要在塞納里奧議會達到尊敬聲望才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的喚風者耶薩德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8557 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8557, 'zhTW', '不屈力量披氅', '我很高興聽到你正在協助我們準備攻擊安其拉，$n。我要給你一個保護物品協助你對抗我們的敵人，$c。$B$B我需要一塊其拉披氅，我一定會為你量身訂做。我還需要塑像和甲蟲來做一個合適的鉤子。$B$B我保證你不會失望的。', '帶1件其拉軍用披氅、2個瑪瑙塑像、5隻銀色甲蟲和5隻白骨甲蟲給希利蘇斯的凱伊·迅爪。你還需要在塞納里奧議會達到崇敬聲望才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的凱伊·迅爪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8558 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8558, 'zhTW', '不屈力量之鐮', '其拉和它們的奴僕使用的物品都是用最稀有和最精緻頂級的材料做成:巨大的古老生物骨頭，地底深處的寶石，純淨堅硬的金屬。$B$B光看一眼其拉神器，就讓我有股衝動想把它們粉碎溶解的碎片，拿來精進我的手藝。證明你對議會的忠誠吧，$n，然後我就會幫你用最好的其拉材料做一個強大的武器。', '帶1把其拉尖刺刀柄、2個雪白塑像、5隻水晶甲蟲和5隻石甲蟲給希利蘇斯的守望者哈爾洛。你還必須在塞納里奧議會達到崇拜聲望值才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的守望者哈爾洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8559, 'zhTW', '征服者的護脛', '其拉蟲人魔法既強大又古老。最強大的其拉蟲人物品甚至可以與龍抗衡。$B$B幫我把其拉統御束腕和其他次要材料帶來，我就能為你製作一雙強大的靴子。$B$B你會在對抗敵人時發現它們很有用的。', '將其拉命令束腕、2個戰爭塑像、5隻象牙甲蟲和5隻金色甲蟲帶給安其拉的坎多斯特拉茲。此任務還需要在諾茲多姆的子嗣達到中立的聲望。', '', '去找安其拉的坎多斯特拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8560, 'zhTW', '征服者的腿甲', '你想要向我的族人證明你的價值嗎，凡人?很好，或許我們可以互相幫助。$B$B古老的沙蟲，奧羅，是個有傳奇力量的生物。相傳他是由上古之神自己創造的生命仿冒品。$B$B他的皮膚很奇怪……很厚，幾乎是穿透不過的，但是他卻很柔軟，可以像小型生物優雅的高速移動。$B$B幫我帶一份他的皮膚樣本和其他次要材料來給我，我就能為你製作一個有強大能量的護腿。', '將奧羅的外皮、2個死亡塑像、5隻青銅甲蟲和5隻象牙甲蟲帶給安其拉裡面的坎多斯特拉茲。你還必須在諾茲多姆的子嗣達到友好聲望值才能完成這個任務。', '', '去找安其拉的坎多斯特拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8561, 'zhTW', '征服者之冠', '雙子帝王…他們不斷的耳語正慢慢地對我的精神造成傷害。他們嘲笑我，知道我不能更進一步進入他們的領地拯救我的哥哥亞雷戈斯。$B$B我的視線裡看到了他們怪獸般的臉孔，戴著強大的王冠。但是我會報復的…我會將這些其拉的飾品轉變為適合我們需求的東西。$B$B幫我把我要的材料帶來，$n。我會給你一頂有著無與倫比能量的首盔。', '將維克尼拉斯的頭環、2個太陽塑像、5隻石甲蟲和5隻水晶甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到友好聲望值才能完成此任務。', '', '去找安其拉的安多葛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8562, 'zhTW', '征服者的胸甲', '最令人恐懼的上古之神正在從安其拉的休眠之中慢慢醒來。艾澤拉斯世界不久之後即將面對這股恐怖的力量，時間對於如此強大的存在來說毫無意義。$B$B當星辰的位置合適的時候，他將讓恐怖的力量席捲所有的一切。你必須在此之前找到他，消滅他。$B$B完成這個任務，把他的外殼交給我。我會獎勵你一件凡人從未見到過的護甲……一件只有弒神者才有資格獲得的護甲!', '將上古之神的甲殼、2個戰爭塑像、5隻銀色甲蟲和5隻白骨甲蟲帶給安其拉的溫瑟拉。你還必須在諾茲多姆的子嗣達到尊敬聲望值才能完成這個任務。', '', '去找安其拉的溫瑟拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8563, 'zhTW', '術士訓練', '隨著你的職業技能越來越精進，你就要從你的職業訓練師那裡多學一點東西。在逐日者之島，年輕術士的訓練師是召喚者泰利拉。和他談談，看看他能提供你什麼訓練。向他學東西是要花錢的，所以帶一點錢在身上。$B$B召喚者泰利拉 - 和所有逐日者之島的訓練師一樣 - 都在日尖塔的較低層。', '和術士訓練師 - 召喚者泰利拉談談 - 他就在逐日者之島的日尖塔裡面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8564, 'zhTW', '牧師訓練', '隨著你的職業技能越來越精進，你就要從你的職業訓練師那裡多學一點東西。在逐日者之島，年輕牧師的訓練師是梅特倫·艾瑞那。和她談談，看看她能提供你什麼訓練。向她學東西是要花錢的，所以帶一點錢在身上。梅特倫·艾瑞那 - 和所有逐日者之島的訓練師一樣 - 都在日尖塔的較低層。', '和牧師訓練師 - 梅特倫·艾瑞那談談 - 她就在逐日者之島的日尖塔裡面。', '', '', '', '', '', '', 0);
