INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8572, 'zhTW', '精兵的裝備', '$n，你已展現了與我們結盟對抗敵人的偉大決心。$B$B作為更進一步的鼓勵，我要給你一項塞納里奧議會給我們親密盟友的獎勵。$B$B我希望你在這之前先完成一些任務，但對你這種人而言應該不是問題。', '將7個塞納里奧作戰徽章，4個塞納里奧後勤徽章，和4個塞納里奧戰術徽章帶到希利蘇斯給塞納里奧城堡的瓦古斯。你還必須在塞納里奧議會達到尊敬聲望值才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的瓦古斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8573 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8573, 'zhTW', '勇士的裝備', '$n，你已展現了與我們結盟對抗敵人的偉大決心。$B$B作為更進一步的鼓勵，我要給你一項塞納里奧議會給我們親密盟友的獎勵。$B$B我希望你在這之前先完成一些任務，但對你這種人而言應該不是問題。', '將15個塞納里奧作戰徽章，20個塞納里奧後勤徽章，20個塞納里奧戰術徽章和1枚塞納留斯印記帶到希利蘇斯給塞納里奧城堡的瓦古斯。你還必須在塞納里奧議會達到崇拜聲望值才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的瓦古斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8574 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8574, 'zhTW', '忠誠者的裝備', '$n，你已展現了與我們結盟對抗敵人的偉大決心。$B$B作為更進一步的鼓勵，我要給你一項塞納里奧議會給我們親密盟友的獎勵。$B$B我希望你在這之前先完成一些任務，但對你這種人而言應該不是問題。', '將15個塞納里奧作戰徽章，20個塞納里奧後勤徽章，17個塞納里奧戰術徽章和1枚雷姆洛斯印記帶到希利蘇斯給塞納里奧城堡的瓦古斯。你還必須在塞納里奧議會達到崇敬聲望值才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的瓦古斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8575 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8575, 'zhTW', '艾索雷葛斯的魔法賬本', '<你看不懂這塊石板上的任何一個字。你連它是用什麼語言寫的都不知道!>', '將艾索雷葛斯的魔法石板帶給塔納利斯的納里安·柔想。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8576 AND `locale` = 'zhTW';
