INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8577, 'zhTW', '斯圖沃爾，曾經最好的朋友', '如果要我翻譯什麼，我就需要我的水晶球護目鏡。不幸的是，它們很久以前就被我曾經最要好的朋友斯圖沃爾給偷走了。他把我的心弄傷了五處然後就把我丟在這裡等著腐爛。$B$B藉著我信任的水晶球幫忙，我讓他不論是走到銀松森林的格雷邁恩之牆還是正被燃燒軍團控制的外域的任何一個角落都會被孤立。你要找到他並拿回我的護目鏡，$n!', '納里安·柔想要你去找到他曾經最好的朋友，斯圖沃爾，並拿回他被偷走的水晶球護目鏡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8578 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8578, 'zhTW', '水晶球護目鏡?沒問題!', '<你聽到木箱裡傳來鬆了一口氣的嘆息聲。>$B$B你只是想要他的水晶球護目鏡?很好!沒有問題……給我一分鐘來……嘿!怎麼……搞的!$B$B嗯，現在有壞消息和更壞的消息。壞消息是我把護目鏡弄丟了。更壞的消息是我是在上個月去熔火之心附近探索的時候弄丟的。沒錯，熔火之心……我想我們的生意結束了!再見!', '去熔火之心探險並找回那些護目鏡!當你取回護目鏡後再回到塔納利斯的納里安·柔想那裡。', '', '去找塔納利斯的納瑞安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8579 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8579, 'zhTW', '凡人中的勇士', '', '', '', '去找坎多斯特拉茲。', '', '', '', '', 0);
