INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8580, 'zhTW', '部落需要火焰花！', '嘿，$c。是你啊!部落認為這次的安其拉之戰需要很多的火焰花。或許他們會將它拿來做些好東西。或許他們會拿來當蒸汽坦克的燃料再送給聯盟?誰知道?比雷凱基也不知道!$B$B不過比雷凱基知道這件事就是了……他知道你會幫他的忙並帶回很多火焰花，對嗎?', '帶20朵火焰花給奧格瑪精神谷的蝙蝠騎士比雷凱基。', '', '去找奧格瑪精神谷的蝙蝠騎士比雷凱基。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8581, 'zhTW', '部落需要更多火焰花！', '', '', '', '去找奧格瑪精神谷的蝙蝠騎士比雷凱基。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8582 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8582, 'zhTW', '部落需要紫蓮花！', '$c，紫蓮花是一種試劑，可以拿來做很多藥水、藥劑和油，有些對我們安其拉戰役很有幫助。我們需要為戰役製作數量龐大的藥水。而且我也要做些實驗找出紫蓮花更多的功用。但是我需要大量的花才能做這些事。$B$B那是你進來的地方。走出去，採集越多紫蓮花越好。這是你能辦到的事嗎?', '帶20朵紫蓮花給奧格瑪精神谷的藥劑師耶澤爾。', '', '去找奧格瑪精神谷的藥劑師耶澤爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8583 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8583, 'zhTW', '部落需要更多紫蓮花！', '', '', '', '去找奧格瑪精神谷的藥劑師耶澤爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8584 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8584, 'zhTW', '不要過問我的工作', '如果你還想知道我的事，那就是:永遠不要過問我的工作!我做的事情你是不會懂的。舉例來說:你知道什麼是治療精神異常的口罩嗎?你當然不知道!這就是為什麼我負責策劃而你負責採集。$B$B如我先前所說的，如果有用的話，我們需要一隻500磅的雞。$B$B前往加基森和戴格·迅斬談談 - 他會要你尋找一種合適的樣本。', '塔納利斯的納里安·柔想要你去和加基森的戴格·奎克里弗談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8585 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8585, 'zhTW', '恐怖之島！', '傳說菲拉斯恐怖之島上的奇美洛克有世界上最柔軟多汁的食物!現在這些奇美洛克也有父親，如果準備的夠好，就有可能看起來像隻500磅的雞。$B$B前往恐怖之島殺死拉克麥拉並把他新鮮的屍體帶來給我。這應該會讓地精很滿意。要讓我滿意的話，你就要弄些奇美洛克的嫩腰肉來給我。$B$B這麼做，你就會得到500磅的雞和一些其他的東西。', '找到拉克麥拉的屍體並帶20塊奇美洛克的嫩腰肉去給塔納利斯的戴格·迅斬。', '', '去找塔納利斯的迪爾格·奎克里弗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8586 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8586, 'zhTW', '戴格的超美味奇美拉肉片', '我的食譜完成了!現在我需要你帶給我的是一些火箭燃料和石中鹽。我會處理香料的部份，而你帶給我的肉將會是其他的重點。$B$B等你把我要的東西拿來，就能把雞帶回去給納里安了。', '加基森的戴格·迅斬要你幫他帶回20個哥布林火箭燃料和20個石中鹽。', '', '去找塔納利斯的迪爾格·奎克里弗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8587 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8587, 'zhTW', '返回納里安', '我是個哥布林，孩子。這是你要的500磅的雞。$B$B一個地精幹嘛要500磅的雞，我實在搞不懂……$B$B<戴格咕噥了一些難以理解的話。>$B$B大概是要睡在裡面吧……骯髒的地精……', '將500磅的雞送給塔納利斯的納里安·柔想。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8588 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8588, 'zhTW', '部落需要重皮！', '既然我們在準備作戰，那麼最好事先收集所有需要的東西，你不覺得嗎?我們現在製作的主要戰爭材料之一是重皮。我們會在任何東西上使用到它，從增強材料到護甲，還有好的老舊防水布。$B$B但是首先我們需要弄到多一點重皮。那是你的工作，$c。磨銳你的刀，幫我帶回一大堆來。然後我們再談。', '帶10張重皮給奧格瑪精神谷的剝皮師亞曼尼。', '', '去找奧格瑪的剝皮師亞曼尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8589 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8589, 'zhTW', '部落需要更多重皮！', '', '', '', '去找奧格瑪的剝皮師亞曼尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8590 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8590, 'zhTW', '部落需要厚皮！', '我很高興你決定來和我談這件事，$c。看來部落為即將來臨的安其拉之戰準備的差不多了。但是你和我仍要盡自己的責任。$B$B我被要求收集大量的厚皮做為戰爭材料，而我需要你去幫我收集。如果你決定幫忙，那就代表了部落的榮耀和感激。你會幫忙嗎?', '帶10張厚皮給奧格瑪精神谷的烏瑪拉中士。', '', '去找奧格瑪的烏瑪拉中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8591 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8591, 'zhTW', '部落需要更多厚皮！', '', '', '', '去找奧格瑪的烏瑪拉中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8592 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8592, 'zhTW', '神諭者的冠冕', '雙子帝王…他們不斷的耳語正慢慢地對我的精神造成傷害。他們嘲笑我，知道我不能更進一步進入他們的領地拯救我的哥哥亞雷戈斯。$B$B我的視線裡看到了他們怪獸般的臉孔，戴著強大的王冠。但是我會報復的…我會將這些其拉的飾品轉變為適合我們需求的東西。$B$B幫我把我要的材料帶來，$n。我會給你一頂有著無與倫比能量的首盔。', '將維克尼拉斯的頭環、2個先知塑像、5隻銀色甲蟲和5隻白骨甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到友好聲望值才能完成此任務。', '', '去找安其拉的安多葛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8593 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8593, 'zhTW', '神諭者的長褲', '你想要向我的族人證明你的價值嗎，凡人?很好，或許我們可以互相幫助。$B$B古老的沙蟲，奧羅，是個有傳奇力量的生物。相傳他是由上古之神自己創造的生命仿冒品。$B$B他的皮膚很奇怪……很厚，幾乎是穿透不過的，但是他卻很柔軟，可以像小型生物優雅的高速移動。$B$B幫我帶一份他的皮膚樣本和其他次要材料來給我，我就能為你製作一個有強大能量的護腿。', '將奧羅的外皮、2個生命塑像、5隻金色甲蟲和5隻泥土甲蟲帶給安其拉的坎多斯特拉茲。同時，你一定要在諾茲多姆的子嗣達到友好聲望值才能完成這個任務。', '', '去找安其拉的坎多斯特拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8594, 'zhTW', '神諭者的披肩', '據說我們之中那個被人類種族穿戴的華麗肩鎧已成為與龍翼競爭的工具了。$B$B幫我把最高等其拉領導者穿戴的護甲弄來，然後我就能將它們做成一套比奈法利安翅膀更可怕的肩鎧了!', '帶回其拉命令束腕、2座重生塑像、5隻銀色甲蟲和5隻象牙甲蟲給在安其拉的安多葛斯。同時你必須在諾茲多姆的子嗣達到中立的聲望值才能完成此項任務。', '', '去找安其拉的安多葛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8595 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8595, 'zhTW', '凡人中的勇士', '', '殺死其拉主使者對人類而言是個顯著的成就，$n。無論如何，他們擁有強大的能量與數量。繼續對抗他們以證明自已成為我們勇士的價值。', '', '去找坎多斯特拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8596 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8596, 'zhTW', '神諭者的裹足', '其拉蟲人魔法既強大又古老。最強大的其拉蟲人物品甚至可以與龍抗衡。$B$B幫我把其拉命令束腕和其他次要材料帶來，我就能為你製作一雙強大的靴子。$B$B你會在對抗敵人時發現它們很有用的。', '將其拉命令束腕、2個死亡塑像、5個青銅甲蟲和5個金色甲蟲帶給安其拉的坎多斯特拉茲。此任務還需要在諾茲多姆的子嗣為中立的陣營。', '', '去找安其拉的坎多斯特拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8597, 'zhTW', '龍語傻瓜教程', '我就知道有一天那本書會變的很好用!幸好，我有那個智慧和遠見將它放在安全的地方。$B$B別擔心，它被藏在一個沒有人會發現的地方!第一次去的時候我需要一架旋翼機到達那裡。不幸的是，我在回程的海邊把它撞壞了。經過那次意外我才獲得了這些超地精的超自然能量!$B$B去天涯海灘找回我撞壞的旋翼機並往南方游去!你就會看到那個地點了!', '找到埋在南海中一個島上的納里安·柔想的書。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8598 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8598, 'zhTW', '贖金', '<紙條上的文字是以不同的字體黏貼上羊皮紙的表面。>$B$B我們找到你珍貴的書了，地精。如果你還想看到它，就照著我們的話去做。$B$B<列著詳細的指示，共有3頁。>$B$B帶著錢獨自前來!', '將勒贖信件帶給塔納利斯的納里安·柔想。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8599 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8599, 'zhTW', '給納里安的情歌', '我不常有訪客。事實上，我上一次有訪客是當我從一艘破爛、撞毀的飛行器上救了一個可愛的地精的時候。$B$B<米莉蒂絲注視著前方，掉入回憶的漩渦。>$B$B你認識他嗎?納里安?納里安·柔想?喔，如果有人能幫我傳個訊息給他會非常好。我一定要告訴他我的感覺!我知道這是愛!$B$B你可以傳個口訊給納里安嗎?我永遠都欠你一份人情!', '把米莉蒂絲的情書帶給塔納利斯的納里安·柔想。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8600 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8600, 'zhTW', '部落需要硬甲皮！', '我發現刀子握在掌心的適合度遠比刀口的鋒利重要。即使是最鈍的刀劍也能在危急時發揮作用。但是你和我沒有這種問題，畢竟我們總會讓刀鋒維持在最利的狀態。$B$B對吧?嗯，不重要。我有個任務要給你，$c。為了部落，還有你對安其拉之戰該盡的職責，我要你去收集很多硬甲皮給我。你能做到嗎?', '帶10張硬甲皮給奧格瑪精神谷的塞拉圖斯。', '', '去找奧格瑪的塞拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8601, 'zhTW', '部落需要更多硬甲皮！', '', '', '', '去找奧格瑪的塞拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8602, 'zhTW', '風暴召喚者的肩鎧', '據說我們之中那個被人類種族穿戴的華麗肩鎧已成為與龍翼競爭的工具了。$B$B幫我把最高等其拉領導者穿戴的護甲弄來，然後我就能將它們做成一套比奈法利安翅膀更可怕的肩鎧了!', '將其拉統御束腕、2個生命塑像、5隻金色甲蟲和5隻水晶甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到中立的聲望值才能完成這個任務。', '', '去找安其拉的安多葛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8603, 'zhTW', '神諭者的法衣', '最令人恐懼的上古之神正在從安其拉的休眠之中慢慢醒來。艾澤拉斯世界不久之後即將面對這股恐怖的力量，時間對於如此強大的存在來說毫無意義。$B$B當星辰的位置合適的時候，他將讓恐怖的力量席捲所有的一切。你必須在此之前找到他，消滅他。$B$B完成這個任務，把他的外殼交給我。我會獎勵你一件凡人從未見到過的護甲……一件只有弒神者才有資格獲得的護甲!', '將上古之神的外殼、2個死亡塑像、5隻石甲蟲和5隻水晶甲蟲帶給安其拉的溫瑟拉。你還必須在諾茲多姆的子嗣達到尊敬聲望值才能完成這個任務。', '', '去找安其拉的溫瑟拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8604, 'zhTW', '部落需要絨線繃帶！', '你好，$c。為了安其拉戰役的準備，我在這裡協調部落收集絨線繃帶的事。戰場上，我們的士兵們無法仰賴醫者得以生存。因此，我們要將這些急救工具收集好給他們。$B$B如果你有時間，我需要很多的絨線繃帶。把它們拿來給我，我就會好好地獎勵你。', '帶20個絨線繃帶給奧格瑪精神谷的醫者朗蘭納。', '', '去找奧格瑪的醫師朗蘭納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8605, 'zhTW', '部落需要更多絨線繃帶！', '', '', '', '去找奧格瑪的醫師朗蘭納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8606, 'zhTW', '螳螂捕蟬！', '我知道了!我們就這麼辦。我要去收集一袋石頭而你要負責空投。我知道我應該要去運送而我已經準備要去了 –… 應該算是吧。$B$B<納里安上下打量你。>$B$B嗯，你會做的很好。帶著這個頭巾，還有一袋石頭前往冬泉谷的空投點。$B$B我把你所有會需要的東西都放在這個特別的工具箱裡。等他們出現拿取貨物時，一舉消滅他們!讓他們知道惹毛納里安的下場!', '塔納利斯的納里安·柔想要你前往冬泉谷並將一袋金子放在綁架書的人所紀錄的空投點。', '', '去找塔納利斯的納瑞安。', '是誰控制著人造猿二號？', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8607, 'zhTW', '部落需要魔紋布繃帶！', '我相信你跟我說話是因為你要幫忙我收集東西吧?很好!不管用什麼方法，我是說真的喔，我希望你去收集很多魔紋布繃帶。越新鮮的越好，但不一定要新鮮。把它們帶來給我，$c，我就會親自酬謝你的。', '帶20個魔紋布繃帶給奧格瑪精神谷的卡隆女士。', '', '去找奧格瑪的卡隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8608, 'zhTW', '部落需要更多魔紋布繃帶！', '', '', '', '去找奧格瑪的卡隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8609, 'zhTW', '部落需要符文布繃帶！', '看來安其拉戰役會造成部落和聯盟間不可避免的衝突。但令人驚訝的是，這不是場雙方間的戰爭，而是對抗異種蠍和控制他們的力量。雙方都在收集打一場勝仗所需的資源。$B$B我在收集要分配給士兵們的符文布繃帶。但是我沒有協助是不會成功的。你能幫我這個忙嗎，$c?', '帶20個符文布繃帶給奧格瑪精神谷的尼根·陶蹄。', '', '去找奧格瑪的尼根·陶蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8610 AND `locale` = 'zhTW';
