INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8611, 'zhTW', '部落需要瘦狼排！', '我站在這裡不是為了曬成好看的小麥色，$c。是為了戰爭作準備。如果我們要消滅安其拉那些蟲子，那麼我們就要準備好，包括食物!$B$B他們要我為即將來臨的戰爭收集並醃製瘦狼排。但是我必須留在這裡處理事情，所以我需要你去殺一些狼，並將它們的肉烹煮成瘦狼排再帶來給我。你聽懂了嗎?', '帶20塊瘦狼排給奧格瑪精神谷的血衛士拉爾塔。', '', '去找杜洛塔的血衛士拉爾塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8612 AND `locale` = 'zhTW';
