INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8613, 'zhTW', '部落需要斑點黃尾魚！', '今天是個釣魚的好日子，你不覺得嗎?這樣很好，因為我正需要很多的魚。部落要我負責收集一噸有斑點的黃尾魚。他們說是安其拉戰役需要的。我說我會盡力而為。所以我需要一些幫忙。你會幫我吧，$c?', '帶20條有斑點的黃尾魚給奧格瑪精神谷的漁夫林度。', '', '去杜洛塔找奧格瑪的漁夫林度。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8614 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8614, 'zhTW', '部落需要更多斑點黃尾魚！', '', '', '', '去找杜洛塔的漁夫林度。', '', '', '', '', 0);
