INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8615, 'zhTW', '部落需要烤鮭魚！', '安其拉之戰是一項浩大的工程，$c。這裡收集的所有材料，不管是武器要用的金屬，還是要吃的食物，所有的東西都一樣重要。如果你好幾天沒吃東西就會沒有力氣在必要時舉起你的斧頭。$B$B因此，我們盡量收集食物。我正在收集烤鮭魚，好保存又營養。你可以幫我這個忙嗎，$c?', '帶20條烤鮭魚給奧格瑪精神谷的圖拉·利爪。', '', '去找杜洛塔的圖拉·利爪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8616 AND `locale` = 'zhTW';
