INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8617, 'zhTW', '部落需要燒焦的核心石！', '是你為安其拉之戰貢獻的時候了，$c。你消磨時間的悠閒日子已經結束了。現在是為我和部落效勞的時候，我告訴你，我可不像戰爭首領那樣心胸寬大。$B$B你要聚集你的軍力，最好是一個公會，然後進軍熔火之心。你會發現裡面的居民都有燒焦的核心石。帶大量的石頭回來給我。', '帶50個燒焦的核心石給杜洛塔的佐格將軍。', '', '去找丹莫洛的佐格將軍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8618 AND `locale` = 'zhTW';
