INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8620, 'zhTW', '獨一無二的秘笈', '我早該知道。我的頭號敵人，維維爾博士，他的老把戲!現在，由於你在冬泉谷的失敗，所以我的書才會被維維爾博士給毀了!請問你這位大英雄現在要如何拯救世界?$B$B我拿到的紙條上說目前所知道的複製品「龍語傻瓜教程:第二卷」已經被撕成八塊散亂在風中!如果你先幫我找回遺失的部分，再用這條魔蔓將書捆好帶回來給我。', '接著復原龍語傻瓜教程書中遺漏的八章，並將它們與魔法書裝訂在一起以完成龍語傻瓜教程:第二卷，將它交給塔納利斯的納里安·柔想即可。', '', '去找塔納利斯的納瑞安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8621, 'zhTW', '風暴召喚者的護足', '其拉蟲人魔法既強大又古老。最強大的其拉蟲人物品甚至可以與龍抗衡。$B$B幫我把其拉統御束腕和其他次要材料帶來，我就為你製作一雙強大的靴子。$B$B你會在對抗敵人時發現它們的威力。', '將其拉統御束腕、2個先知塑像、5隻青銅甲蟲和5隻泥土甲蟲帶給安其拉的坎多斯特拉茲。你一定要在諾茲多姆的子嗣達到中立的聲望值才能完成這個任務。', '', '去找安其拉的坎多斯特拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8622, 'zhTW', '風暴召喚者鍊衫', '最令人恐懼的上古之神正在從安其拉的休眠之中慢慢醒來。艾澤拉斯世界在不久之後即將面對這股恐怖的力量，時間對於如此強大的存在來說毫無意義。$B$B當星辰的位置合適的時候，他將讓恐怖的力量席捲所有的一切。你必須在此之前找到他，消滅他。$B$B完成這個任務，把他的外殼交給我。我會獎勵你一件凡人從未見到過的護甲……一件只有弒神者才有資格獲得的護甲!', '帶回上古之神的甲殼、2個先知塑像、5隻銀色甲蟲和5隻白骨甲蟲給安其拉的溫瑟拉。你還必須在諾茲多姆的子嗣達到尊敬聲望值才能完成這個任務。', '', '去找安其拉的溫瑟拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8623 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8623, 'zhTW', '風暴召喚者的王冠', '雙子帝王…他們不斷的耳語正慢慢地對我的精神造成傷害。他們嘲笑我，知道我不能更進一步進入他們的領地拯救我的哥哥亞雷戈斯。$B$B我的視線裡看到了他們怪獸般的臉孔，戴著強大的王冠。但是我會報復的…我會將這些其拉的飾品轉變為適合我們需求的東西。$B$B幫我把我要的材料帶來，$n。我會給你一頂有著無與倫比能量的首盔。', '將維克洛爾的王冠、2個重生塑像、5隻石甲蟲和5隻水晶甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到友好的聲望值才能完成此項任務。', '', '去找安其拉的安多葛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8624, 'zhTW', '風暴召喚者的護腿', '你想要向我的族人證明你的價值嗎，凡人?很好，或許我們可以互相幫助。$B$B古老的沙蟲，奧羅，是個有傳奇力量的生物。相傳他是由上古之神自己創造的生命仿冒品。$B$B他的皮膚很奇怪……很厚，幾乎是穿透不過的，但是他卻很柔軟，可以像小型生物優雅的高速移動。$B$B幫我帶一份他的皮膚樣本和其他次要材料來給我，我就能為你製作一個有強大能量的護腿。', '將巨型沙蟲的皮、2個征戰塑像、5隻青銅甲蟲和5隻象牙甲蟲給安其拉的坎多斯特拉茲。你還必須在諾茲多姆的子嗣達到友好的聲望值才能完成此任務。', '', '去找安其拉的坎多斯特拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8625, 'zhTW', '神秘肩墊', '據說我們之中那個被人類種族穿戴的華麗肩鎧已成為與龍翼競爭的工具了。$B$B幫我把最高等其拉領導者穿戴的護甲弄來，然後我就能將它們做成一套比奈法利安翅膀更可怕的肩鎧了!', '帶回其拉統御束腕、2個死亡塑像、5隻石甲蟲和5隻青銅甲蟲給安其拉的安多葛斯。同時你必須在諾茲多姆的子嗣達到中立的聲望值才能完成此項任務。', '', '去找安其拉的安多葛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8626 AND `locale` = 'zhTW';
