INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8639, 'zhTW', '死亡執行者的頭盔', '雙子帝王…他們不斷的耳語正慢慢地對我的精神造成傷害。他們嘲笑我，知道我不能更進一步進入他們的領地拯救我的哥哥亞雷戈斯。$B$B我的視線裡看到了他們怪獸般的臉孔，戴著強大的王冠。但是我會報復的…我會將這些其拉的飾品轉變為適合我們需求的東西。$B$B幫我把我要的材料帶來，$n。我會給你一頂有著無與倫比能量的首盔。', '將維克洛爾的王冠、2個戰爭塑像、5隻金色甲蟲和5隻泥土甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到友好聲望值才能完成此任務。', '', '去找安其拉的安多葛斯。', '', '', '', '', 0);
