INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8640, 'zhTW', '死亡執行者的護腿', '你想要向我的族人證明你的價值嗎，凡人?很好，或許我們可以互相幫助。$B$B古老的沙蟲，奧羅，是個有傳奇力量的生物。相傳他是由上古之神自己創造的生命仿冒品。$B$B他的皮膚很奇怪……很厚，幾乎是穿透不過的，但是他卻很柔軟，可以像小型生物優雅的高速移動。$B$B幫我帶一份他的皮膚樣本和其他次要材料來給我，我就能為你製作一個有強大能量的護腿。', '帶回奧羅的外皮、2個夜晚塑像、5隻石甲蟲和5隻水晶甲蟲給在安其拉的坎多斯特拉茲。你還必須在諾茲多姆的子嗣達到友好的聲望值才能完成此任務。', '', '去找安其拉的坎多斯特拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8641, 'zhTW', '死亡執行者的肩甲', '據說我們之中那個被人類種族穿戴的華麗肩鎧已成為與龍翼競爭的工具了。$B$B幫我把最高等其拉領導者穿戴的護甲弄來，然後我就能將它們做成一套比奈法利安雙翼更可怕的肩鎧了!', '將其拉命令束腕、2個太陽塑像、5隻銀色甲蟲和5隻泥土甲蟲帶給安其拉的安多葛斯。你一定要諾茲多姆的子嗣達到中立的聲望值才能完成這個任務。', '', '去找安其拉的安多葛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8642 AND `locale` = 'zhTW';
