INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8655, 'zhTW', '復仇者的護脛', '其拉蟲人魔法既強大又古老。最強大的其拉蟲人物品甚至可以與龍抗衡。$B$B幫我把其拉統御束腕和其他次要材料帶來，我就能為你製作一雙強大的靴子。$B$B你會在對抗敵人時發現它們很有用的。', '將其拉統御束腕、2個先知塑像、5隻青銅甲蟲和5隻泥土甲蟲帶給安其拉的坎多斯特拉茲。你一定要在諾茲多姆的子嗣達到中立的聲望值才能完成這個任務。', '', '去找安其拉的坎多斯特拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8656, 'zhTW', '打擊者鍊衫', '最令人恐懼的上古之神正在從安其拉的休眠之中慢慢醒來。艾澤拉斯世界不久之後即將面對這股恐怖的力量，時間對於如此強大的存在來說毫無意義。$B$B當星辰的位置合適的時候，他將讓恐怖的力量席捲所有的一切。你必須在此之前找到他，消滅他。$B$B完成這個任務，把他的外殼交給我。我會獎勵你一件凡人從未見到過的護甲……一件只有弒神者才有資格獲得的護甲!', '將上古之神的甲殼、2個生命塑像、5隻金色甲蟲和5隻泥土甲蟲帶給安其拉的溫瑟拉。你還必須在諾茲多姆的子嗣達到尊敬聲望值才能完成這個任務。', '', '去找安其拉的溫瑟拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8657 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8657, 'zhTW', '打擊者的王冠', '雙子帝王……他們正向我輕聲密語，這折磨著我的神志。他們嘲笑我，他們知道我無法進入神殿的深處去拯救我的兄弟亞雷戈斯。$B$B我可以看見他們猙獰的臉龐，他們頭上戴著具有無窮力量的皇冠。但是我必須要報仇……我會把這種代表其拉蟲人力量的飾品轉化成對我們有利的東西。$B$B把我需要的材料交給我，$n。我會為你製作一頂具有超凡力量的首盔。', '將維克洛爾的王冠、2個征戰塑像、5隻青銅甲蟲和5隻象牙甲蟲帶給安其拉的安多葛斯。你必需在諾茲多姆的子嗣達到友好聲望值才能完成此項任務。', '', '去找安其拉的安多葛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8658 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8658, 'zhTW', '打擊者的護腿', '你想要向我的族人證明你的價值嗎，凡人?很好，或許我們可以互相幫助。$B$B古老的沙蟲，奧羅，是個有傳奇力量的生物。相傳他是由上古之神自己創造的生命仿冒品。$B$B他的皮膚很奇怪……很厚，幾乎是穿透不過的，但是他卻很柔軟，可以像小型生物優雅的高速移動。$B$B幫我帶一份他的皮膚樣本和其他次要材料來給我，我就能為你製作一個有強大能量的護腿。', '將巨型沙蟲的皮、2個太陽塑像、5隻銀色甲蟲和5隻白骨甲蟲帶給安其拉裡面的坎多斯特拉茲。你還必須在諾茲多姆的子嗣達到友好聲望值才能完成此項任務。', '', '去找安其拉的坎多斯特拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8659 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8659, 'zhTW', '打擊者的肩鎧', '據說我們之中那個被人類種族穿戴的華麗肩鎧已成為與龍翼競爭的工具了。$B$B幫我把最高等其拉領導者穿戴的護甲弄來，然後我就能將它們做成一套比奈法利安翅膀更可怕的肩鎧了!', '將其拉命令束腕、2個戰爭塑像、5隻水晶甲蟲和5隻象牙甲蟲帶給安其拉的安多葛斯。你還必須在諾茲多姆的子嗣達到中立聲望才能完成此項任務。', '', '去找安其拉的安多葛斯。', '', '', '', '', 0);
