INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8660, 'zhTW', '厄運召喚者的裹足', '其拉蟲人魔法既強大又古老。最強大的其拉蟲人物品甚至可以與龍抗衡。$B$B幫我把其拉統御束腕和其他次要材料帶來，我就能為你製作一雙強大的靴子。$B$B你會在對抗敵人時發現它們很有用的。', '將其拉統御束腕、2個夜晚塑像、5隻泥土甲蟲和5隻象牙甲蟲帶給安其拉的坎多斯特拉茲。這個任務需要在諾茲多姆的子嗣達到中立聲望值。', '', '去找安其拉的坎多斯特拉茲。', '', '', '', '', 0);
