INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8687, 'zhTW', '目標：佐拉坑道蠍', '援軍已被徵召加入佐拉蟲巢的攻擊了。你被選為監看佐拉坑道蠍。完成你的任務之後再回報給指揮官瑪爾利斯。', '殺死30隻佐拉坑道蠍並回希利蘇斯向塞納里奧城堡的指揮官瑪爾利斯回報。你還必須將作戰任務簡報 VII帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的指揮官瑪爾利斯。', '', '', '', '', 0);
