DELETE FROM `quest_template_locale` WHERE `ID` = 8697 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8697, 'zhTW', '無盡智慧之戒', '謠傳其拉中尉戴的戒指讓他們有可怕的能力。這顆讓他們如虎添翼的腐敗寶石，理論上可以用較純淨的材料來替換為一個不腐敗的戒指。$B$B其拉塑像配戴的寶石就能有此功效，因為它們的質地非常好。$B$B幫我把戒指和塑像帶來我就能為你做一枚強大的戒指，$c。', '帶1枚其拉典禮戒指、2個黑曜石塑像、5隻銀色甲蟲和5隻白骨甲蟲給希利蘇斯的喚風者耶薩德拉。同時你必須在塞納里奧議會達到尊敬聲望值才能完成這項任務。', '', '去希利蘇斯找塞納里奧要塞的喚風者耶薩德拉。', '', '', '', '', 0);
