INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8728, 'zhTW', '好消息與壞消息', '好吧，這比預期中花了更長的時間。現在讓我看看帳目上記載著什麼。$B$B<納里安在他規律地呼吸之下仔細地看著帳目。>$B$B好消息是我有百分之九十九的把握，我有能力讓奧金浮標對你造成很大的效用。這，當然，完全關係著壞消息。$B$B壞消息就是我需要很多的奧金、源質礦石以及罕見的寶石。$B$B把我需要的東西帶來，我就可以製作浮標了。', '塔納利斯的納里安·柔想要你帶20個奧金錠、10個源質礦石、10個艾澤拉斯鑽石和10個藍寶石給他。', '', '去找塔納利斯的納瑞安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8729, 'zhTW', '奈普圖隆的憤怒', '我和你說過壞消息了嗎?它的名字叫巨齒鯊:100尺長，死亡和毀滅的化身。我想我忘記和你說這個了。$B$B根據我的超級精準千里眼提供的訊息，你會在艾薩拉的海岸找到最合適使用這個浮標的地方，就在風暴海灣。$B$B你要尋找一個大漩渦，就是附近都是沉船的地方。$B$B另外，我希望你帶上你的朋友。$B$B如果你成功的話，那麼把權杖裂片帶給安納克羅斯。', '在艾薩拉風暴海灣一帶的大漩渦使用奧金浮標。', '', '去塔納利斯找時光之穴的阿納克洛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8730, 'zhTW', '奈法利斯的腐敗', '勇士，是你嗎?我受命保管這塊裂片已經有一千年了，現在我的生命處於最黑暗的時期，我相信會有一位勇士替我把它拿回來……任重而道遠。$B$B<瓦拉斯塔茲虛弱地咳嗽著。>$B$B奈……奈法利斯現在掌握著那塊權杖裂片。$B$B時間緊迫，勇士。奈法利斯想要摧毀這塊裂片，你必須趕快行動!', '殺死奈法利安，並拿到紅色權杖裂片。把裂片交給塔納利斯時光之穴入口處的安納克羅斯。你必須在5小時之內完成這個任務。', '', '去塔納利斯找時光之穴的阿納克洛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8731, 'zhTW', '戰地任務', '你好，$n。在我給你更重要的戰地任務之前，你必須完成你的戰地任務，$B$B你會在雷戈蟲巢外面找到劈顱隊長的奧格瑪軍團。$B$B向他報告後帶著證明回到我這裡。我會給你一個更高階的任務。$B$B喔，請盡量遠離鐵爐堡軍旅。聯盟與部落志願兵之間的緊張情勢正高漲。', '前往雷戈蟲巢，到那裡的奧格瑪軍團哨站向克魯格·碎顱報告。準備好未簽字的戰地任務報告，取得簽過字的戰地任務報告並帶給塞納里奧城堡的喚風者卡爾東。注意:給奧格瑞瑪軍團的士兵治療或者施放增益法術會打開你的PvP標誌。', '', '去希利蘇斯找塞納里奧要塞的喚風者卡爾東。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8732 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8732, 'zhTW', '戰地任務報告', '', '', '', '去希利蘇斯找克魯格·碎顱', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8733 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8733, 'zhTW', '伊蘭尼庫斯，夢境暴君', '這是一場救贖之旅，英雄。也許今日我會被殺害，但我是因為公平與正義而死。你一定要取得綠色權杖裂片，也一定要淨化被上古諸神所污染的伊蘭尼庫斯。$B$B到達納蘇斯，在城牆外你就可以看到我的代理人之一。在不通知鹿盔的情形下，這位代理人會著手進行一些事，並將我們的計畫告訴泰蘭妲。$B$B<瑪法里恩嘆息。>$B$B一次的墮落要一千年來彌補......', '到泰達希爾去找瑪法里恩的代理人，大約在達納蘇斯牆外某處。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8734 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8734, 'zhTW', '泰蘭妲與雷姆洛斯', '我們會通知泰蘭妲的，凡人。瑪法里恩·怒風已經讓我準備好這次突發事件。$B$B現在你必須去月光林地然後和雷姆洛斯談談。他會進一步指引你去召喚伊蘭尼庫斯。$B$B我們會祝你好運的。', '去月光林地和守護者雷姆洛斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8735 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8735, 'zhTW', '腐蝕夢魘', '你必須到艾澤拉斯的四個翡翠夢境入口。然後從各個門分別取得腐蝕夢魘的碎片，住在那區的刃鱗龍人握有那些碎片，收集好碎片之後帶回給我。', '到艾澤拉斯的4個翡翠夢境入口。從各個門分別取得腐蝕夢魘的碎片，完成任務後交給月光林地的守護者雷姆洛斯。', '', '去月光林地找雷姆洛斯神殿的守護者雷姆洛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8736 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8736, 'zhTW', '噩夢顯現', '我們必須盡量控制伊蘭尼庫斯，我們要讓他獲得救贖，而不是摧毀他。$B$B泰蘭妲已經在趕來幫助我們的路上了。我們必須守住巨龍的攻擊，保護永夜港免遭傷害。$B$B做好準備！你和你的盟友是我們唯一的希望。', '保護永夜港免受伊蘭尼庫斯的傷害。不要讓守護者雷姆洛斯死亡。不要殺掉伊蘭尼庫斯。保護好你們自己。等待泰蘭妲。', '伊蘭尼庫斯的救贖', '去月光林地找月神湖的守護者雷姆洛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8737 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8737, 'zhTW', '碧藍聖殿騎士', '暮光之錘和他們所膜拜的元素生物對我們在希利蘇斯地區的行動是個不小的威脅。安其拉高牆內的敵人還在虎視眈眈，所以我們絕對不能對暮光之錘的勢力掉以輕心。$B$B想辦法召喚並摧毀一名碧藍聖殿騎士，然後向鮑爾·蠻鬃回報。', '召喚並殺死一名碧藍聖殿騎士，然後向塞納里奧城堡的鮑爾·蠻鬃覆命。你還必須將戰術任務簡報 I帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的鮑爾·蠻鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8738 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8738, 'zhTW', '雷戈蟲巢偵察報告', '我們派出了最好的斥候深入異種蟲類的巢穴收集情報。蘭迪奧這幾天來一直在監視佐拉蟲巢，去找到他，拿回他的書面報告。我們需要這些情報來制定戰術，要盡快，$n。', '在雷戈蟲巢內找到塞納里奧斥候蘭迪奧，然後把雷戈蟲巢偵察報告交給塞納里奧城堡的喚風者傲角。你還必須隨身帶著戰術任務簡報 VII才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的喚風者傲角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8739 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8739, 'zhTW', '亞什蟲巢偵察報告', '我們派出了最好的斥候深入異種蟲類的巢穴收集情報。佳莉亞這幾天來一直在監視亞什蟲巢，去找到她，拿回她的書面報告。我們需要這些情報來制定戰術，要盡快，$n。', '在亞什蟲巢內找到塞納里奧斥候佳莉亞，然後把亞什蟲巢偵察報告交給塞納里奧城堡的喚風者傲角。你還必須隨身帶著戰術任務簡報 VIII才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的喚風者傲角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8740 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8740, 'zhTW', '暮光掠奪者', '許多暮光之錘的騎兵經常在我們塞納里奧城堡守衛範圍之外的區域遊蕩，並伺機襲擊我們巡邏兵和商旅小隊。$B$B找到並擊敗暮光掠奪者和他們的領袖，一個名叫莫娜的可怕戰士。當任務完成之後，去向喚風者傲角報告。', '殺死暮光掠奪者莫娜和2個暮光掠奪者。任務完成之後就回去向喚風者傲角報告。你還必須隨身帶著戰術任務簡報 IX才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的喚風者傲角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8741, 'zhTW', '冠軍的回報', '守護者在等待著你，$N。把綠色節杖碎片交給時光之穴前的阿納克洛斯吧。', '把綠色節杖碎片交給塔納利斯時光之穴的阿納克洛斯。', '', '', '', '', '', '', 0);
