INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8762, 'zhTW', '麋鹿梅特森', '出大事了！麋鹿梅特森被綁架了！$B$B梅特森是冬天爺爺的八頭麋鹿之一－－也是燻木牧場的財產。我們已經收到不只一封，而是兩封聲稱他們擁有梅特森的集團勒索信。因為節日即將來臨！拜託－－找到梅特森並把牠帶回來給我們！$B$B你可以從這些勒索信上找尋線索，並且把這個麋鹿粉末灑在牠的身上－－這會讓牠擺脫任何拘束他的東西！$B$B拜託了，事不宜遲！', '找到馴鹿梅特森。在你手上的筆記中查尋有關梅特森下落的線索。$B$B當你找到它之後，往它身上灑一些糜鹿粉末，這樣就可以讓它擺脫任何束縛。$B$B解救梅特森之後，把糜鹿粉末還給鐵爐堡的烏爾莫特。', '', '去找鐵爐堡的烏爾莫特。', '尋找麋鹿梅特森並且解救牠', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8763 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8763, 'zhTW', '節日英雄', '聽著……我實在不應該告訴你這些的，但是既然你是今天的英雄……$B$B今年到處都有新鮮的冬青，但它從未長久保存下來。我們已經找到一台機器可以用來保存冬青－－它再也不會壞掉了！我們要把它用來點綴這個節日……並且在夏天的時候賺點蠅頭小利！$B$B我可以讓你使用這台機器，但是你必須要是大師級廚師才行。你會需要一些石中鹽跟兩、三個，嗯，五個金幣吧。這可以讓你做出一些很不錯的東西了。', '攜帶1份石中鹽及5個金幣到冬青保存機去，你可以獲得五份保存的冬青。', '', '去找冬青樹儲藏器。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8764 AND `locale` = 'zhTW';
