INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8770, 'zhTW', '目標:亞什防衛者', '這一地區猖獗的異種蟲群對我們來說是個巨大的威脅。你被指派負責對亞什蟲巢發動攻擊，主要目標是亞什防衛者。$B$B在你的任務完成之後，向指揮官瑪爾利斯回報。', '殺死30隻亞什防衛者再到希利蘇斯的塞納里奧城堡向指揮官瑪爾利斯回報。你還必須將作戰任務簡報  I帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的指揮官瑪爾利斯。', '', '', '', '', 0);
