INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8772, 'zhTW', '目標：佐拉守衛', '我們需要援軍進攻佐拉蟲巢。你的主要目標是那些佐拉守衛，當你的任務完成之後就去向指揮官瑪爾利斯報告。', '殺死30隻佐拉守衛再到希利蘇斯的塞納里奧城堡向指揮官瑪爾利斯回報。你還必須將作戰任務簡報  VI帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的指揮官瑪爾利斯。', '', '', '', '', 0);
