INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8778, 'zhTW', '鐵爐堡軍旅需要爆裂物!', '鐵爐堡軍旅需要極大量…爆炸性…的零件。幫他們收集並帶給鐵爐堡軍旅的諾斯賓先生。', '把6瓶獻祭之油、5瓶哥布林火箭燃油和10份緻密火藥粉交給希利蘇斯地區的佐拉蟲巢附近的秘術師諾斯賓。你還必須帶著後勤任務簡報 IV才能完成這個任務。', '', '去希利蘇斯找佐拉蟲巢附近的奧術師諾斯賓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8779 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8779, 'zhTW', '研究材料', '地理學家拉克斯班的研究對我們在希利蘇斯的運作有著極大的價值。她最近的研究需要研究材料。$B$B請收集這些材料並直接送給她讓她繼續做研究。', '將一個大塊魔光裂片，一個大塊強光裂片和一個巨型綠寶石帶到希利蘇斯給塞納里奧城堡的地理學家拉克斯班。你還必須將後勤任務簡報 V帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的地質學家拉克斯班。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8780 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8780, 'zhTW', '戰場上的護甲片', '鐵爐堡軍團的護甲片儲備量偏低，這很危險。去收集一些護甲片，把它們交給佐拉蟲巢附近的珍妮拉·鋼錘。', '將8塊毛皮護甲片和8塊重型護甲片交給佐拉蟲巢附近的珍妮拉·鋼錘。你還必須將後勤任務簡報 VII帶去才能完成這個任務。', '', '去希利蘇斯的佐拉蟲巢附近找珍妮拉·鋼錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8781, 'zhTW', '戰場上的武器', '鐵爐堡軍旅對我們在希利蘇斯的戰鬥很有價值。不幸地，他們很多補給都在來這裡的路上弄丟了。取得一批武器並送給佐拉蟲巢附近的珍妮拉·鋼錘。', '將2把月鋼寬劍帶到佐拉蟲巢外的鐵爐堡軍旅前哨給珍妮拉·鋼錘。你還必須將後勤任務簡報 VI帶去才能完成這個任務。', '', '去希利蘇斯的佐拉蟲巢附近找珍妮拉·鋼錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8782, 'zhTW', '制服供應', '最近不斷加入的志願者導致我們制服短缺。去搜集一些制服的材料，然後把它們交給喚風者傲角。', '把1塊月布、2卷符文布卷和1份鐵網蛛絲交給喚風者傲角。你還必須將後勤任務簡報 VIII帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的喚風者傲角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8783, 'zhTW', '特殊的材料', '塞納里奧城堡的鐵匠，瓦古斯，需要附魔材料為我們的軍隊製作強大的武器。取得這些東西並直接帶給瓦古斯，塞納里奧城堡的軍隊才能裝備齊全。', '帶2個附魔瑟銀錠和2塊附魔皮革到希利蘇斯給塞納里奧城堡的瓦古斯。你還必須將後勤任務簡報 IX帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的瓦古斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8784, 'zhTW', '其拉軍的秘密', '你發現了一個上古其拉神器!或許神廟入口附近的巨龍之一需要這個聖物。', '將這個上古其拉神器帶給藏在神廟入口附近的巨龍。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8785 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8785, 'zhTW', '奧格瑪軍團需要魔精油!', '奧格瑪軍團需要幾種特別的材料。依他們在希利蘇斯的現況，我們希望能越快完成他們的要求越好。收集這些材料並帶給一個叫沙艾的食人妖。', '帶6瓶強力魔精油，6瓶大魔精和8瓶獻祭之油到希利蘇斯給雷戈蟲巢附近的暗影牧師珊雅。你還必須將後勤任務簡報 IV帶去才能完成這個任務。', '', '去希利蘇斯找雷戈蟲巢的暗影祭司沙艾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8786, 'zhTW', '戰場上的武器', '奧格瑪軍團需要額外的武器，而我們現階段無法提供。取得他們要的武器並帶給雷戈蟲巢外面的梅洛克·遠途。', '帶3把巨型鐵斧到雷戈蟲巢外面的奧格瑪軍團營地，交給梅洛克·遠途。你還必須將後勤任務簡報 VI帶去才能完成這個任務。', '', '去希利蘇斯找雷戈蟲巢的梅洛克·遠途。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8787, 'zhTW', '戰場上的護甲片', '奧格瑪軍團英勇的志願者已來到希利蘇斯幫助我們作戰。但是他們的護甲片補給在旅途中弄丟了。取得一批護甲片並送到奧格瑪軍團營地給梅洛克·遠途。', '帶8塊毛皮護甲片和8塊重型護甲片給雷戈蟲巢附近的梅洛克·遠途。你還必須將後勤任務簡報 VII帶去才能完成這個任務。', '', '去希利蘇斯找雷戈蟲巢的梅洛克·遠途。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8788, 'zhTW', '輕輕搖晃過的禮物', '', '這個禮物看起來好像已經被稍微搖晃過了幾次。上面的標籤寫著：給最特別的$r$c。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8789, 'zhTW', '其拉帝王武器', '一千年以來，我們並沒有無所事事地留在這裡，$N。$B$B我們在這裡看著這些野獸耗盡資源時自相殘殺，我們傾聽了它們密謀毀滅我們世界的談話，我們還知道了它們內部的爭權奪利。$B$B它們確實有弱點，而且我們知道如何利用這些弱點。$B$B找到它們在葬禮儀祭上陪葬用的武器，把它和他們自己的神所創造的最強的元素融合在一起，我們就可以創造出終結一切的武器。', '把其拉帝王武器和3塊源質礦石交給安其拉神廟的亞雷戈斯，他會幫你製作使用源質灌注的武器。', '', '去找亞雷戈斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8790, 'zhTW', '其拉帝王標誌', '亞雷戈斯認為，在一定情況下，因上古諸神和他們的僕從之間的衝突而產生的元素也會對他們本身造成致命的威脅。凡人，我指的是源質。$B$B將其拉帝王徽記和這種元素交給我，我就能為武器注入巨大的力量。', '如果你能將其拉帝王徽記和3個源質礦石帶給安其拉神廟『夢境之龍』麥琳瑟拉，她就能為你製作源質灌注的武器。', '', '去找夢境之龍麥琳瑟拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8791, 'zhTW', '奧斯里安的墮落', '來自其拉蟲群的威脅已經被平息。可怕的奧斯里安已被擊敗。$B$B卡林多的居民知道這樣的勝利都會如釋重負。將奧斯里安的頭顱帶給塞納里奧城堡的指揮官瑪爾利斯。', '將『無疤者』奧斯里安的頭顱帶到希利蘇斯給塞納里奧城堡的指揮官瑪爾利斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8792, 'zhTW', '部落需要你的幫助！', '嗨，我很高興你決定聽我說完。部落需要所有的幫助來準備安其拉之戰，這表示我們需要你!連我們現在講話的時候，都有官方的收集者在收集戰爭需要的材料，但是我們沒有你的幫助仍然無法達到目標，$n!$B$B你應該去和負責的督軍格爾庫克談談。你看怎麼樣，$c?你會幫我們做這重要的準備嗎?', '和奧格瑪精神谷的督軍格爾庫克交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8793 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8793, 'zhTW', '部落需要你的幫助！', '嗨，我很高興你決定聽我說完。部落需要所有的幫助來準備安其拉之戰，這表示我們需要你!連我們現在講話的時候，都有官方的收集者在收集戰爭需要的材料，但是我們沒有你的幫助仍然無法達到目標，$n!$B$B你應該去和負責的督軍格爾庫克談談。你看怎麼樣，$c?你會幫我們做這重要的準備嗎?', '和奧格瑪精神谷的督軍格爾庫克交談。', '', '', '', '', '', '', 0);
