INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8794, 'zhTW', '部落需要你的幫助！', '嗨，我很高興你決定聽我說完。部落需要所有的幫助來準備安其拉之戰，這表示我們需要你!連我們現在講話的時候，都有官方的收集者在收集戰爭需要的材料，但是我們沒有你的幫助仍然無法達到目標，$n!$B$B你應該去和負責的督軍格爾庫克談談。你看怎麼樣，$c?你會幫我們做這重要的準備嗎?', '和奧格瑪精神谷的督軍格爾庫克交談。', '', '', '', '', '', '', 0);
