INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8799, 'zhTW', '大英雄！', '聽好…我可以不告訴你的，但是既然你是今日的英雄…$B$B每年的這個時候到處都有新鮮的冬青，但是它們都不能保久。我們有一個保存冬青的機器 – 它會永遠保鮮！我們用它來點綴節日…在夏天的時候還可以賺取利潤！$B$B我會讓你使用保存機，但你一定要是個大師級的廚師才行。你需要一些石中鹽和兩個，三個，喔五個好了，五個金幣。我會幫你弄到一批好貨的。', '攜帶1份石中鹽及5個金幣到冬青保存機去，你可以獲得5份保存的冬青。', '', '去找冬青樹儲藏器。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8800 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8800, 'zhTW', '塞納里奧戰鬥工具', '完成你在戰爭中被指派的任務後，你要和鐵匠瓦古斯交談。給他看看你這一路上獲得的徽章。他會給你適合等級的工具來幫助我們的事業。', '到希利蘇斯和塞納里奧城堡的瓦古斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8801, 'zhTW', '克蘇恩的遺產', '安其拉的高牆搖晃起來。超越這世界的邪惡力量已經被摧毀了。$B$B當你注視著巨像憎惡的遺跡時，心跳幾乎被凍結。在死一般的寂靜中，你還是能感覺克蘇恩的邪惡力量。$B$B你完成了別人認為不可能的任務。$B$B你取下惡魔的眼梗小心放進你的包包裡。$B$B把克蘇恩之眼帶到下一個房間裡的巨龍那兒。', '將克蘇恩之眼帶給安其拉神廟的卡拉史塔斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8802, 'zhTW', '卡林多的救星', '前往時光之穴，<大人/女士>$n。安納克羅斯等著你回來。把克蘇恩之眼交給他，他絕對會將它放在主人的收集品裡。', '把克蘇恩之眼帶給時光之穴的安納克羅斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8803, 'zhTW', '節慶禮物', '', '這個禮物上的便條紙寫著：給$n，希望這個禮物可以幫助你將溫暖及節日的喜悅散播到整個艾澤拉斯大陸。冬天爺爺敬贈', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8804, 'zhTW', '沙漠生存包', '隨著新兵增援塞納里奧城堡，如何讓他們在沙漠中生存成了一個問題。缺水是基本的問題，沙漠中無數具毒的生物對沒有經驗的自願兵而言是很大的威脅。收集沙漠生存工具包需要的物資並帶給塞納里奧城堡的卡蘭德拉斯。', '帶4個純水之球，4個特強抗毒藥劑和4個沙漠肉丸子帶到希利蘇斯給塞納里奧城堡旅店的卡蘭德拉斯。你還必須將後勤任務簡報 I帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的卡蘭德拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8805, 'zhTW', '衛兵的靴子', '塞納里奧城堡守衛的坐騎軍師缺少華麗秘銀戰靴。取得一批戰靴並立即送給塞納里奧城堡的維斯·庫魯茲隊長。', '將3雙華麗秘銀戰靴帶到希利蘇斯給塞納里奧城堡的守衛隊長維斯·庫魯茲。你還必須將後勤任務簡報 II帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的維斯·庫魯茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8806, 'zhTW', '衛兵的砂輪', '塞納里奧城堡守衛的守衛面臨砂輪短缺。取得一批砂輪並立即送給塞納里奧城堡的維斯·庫魯茲隊長。', '將10個緻密砂輪，10個堅固的砂輪和10個重砂輪帶到希利蘇斯給塞納里奧城堡的守衛隊長維斯·庫魯茲。你還必須將後勤任務簡報 III帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的維斯·庫魯茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8807 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8807, 'zhTW', '研究材料', '地理學家拉克斯班的研究對我們在希利蘇斯的運作有著極大的價值。她最近的研究需要研究材料。$B$B請收集這些材料並直接送給她讓她繼續做研究。', '將1個大塊魔光裂片，1個大塊強光裂片和1個巨型綠寶石帶到希利蘇斯給塞納里奧城堡的地理學家拉克斯班。你還必須將後勤任務簡報 V 帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的地質學家拉克斯班。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8808 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8808, 'zhTW', '制服供應', '最近加入的一批自願兵造成制服的短缺。取得一批制服材料並帶給喚風者傲角。', '將1塊月布，2個符文布卷和1個鐵網蛛絲帶到希利蘇斯給塞納里奧城堡的喚風者傲角。你還必須將後勤任務簡報 VIII帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的喚風者傲角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8809 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8809, 'zhTW', '特殊的材料', '塞納里奧城堡的鐵匠，瓦古斯，需要附魔材料為我們的軍隊製作強大的武器。取得這些東西並直接帶給瓦古斯，塞納里奧城堡的軍隊才能裝備齊全。', '將2個附魔瑟銀錠和2塊附魔皮到希利蘇斯給塞納里奧城堡的瓦古斯。你還必須將後勤任務簡報 IX帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的瓦古斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8810, 'zhTW', '戰場上的繃帶', '我們在戰場的繃帶補給正因最近的死傷嚴重而短缺。取得一批急救補給並送給塞納里奧城堡的喚風者傲角。', '將30個厚符文布繃帶，30個厚絲質繃帶和30個厚魔紋繃帶到希利蘇斯給塞納里奧城堡的喚風者傲角。你還必須將後勤任務簡報 X帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的喚風者傲角。', '', '', '', '', 0);
