INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8827, 'zhTW', '冬天的禮物', '我聽說冬天爺爺－在燻木牧場的慷慨支持下－已經把要給所有人的禮物放在鐵爐堡的樹下。真希望我也能去，但是我必須看管這台PX-238冬幕歡樂製造器。不過你一定得去看看。我相信冬天爺爺已經準備好印著你名字的禮物了。', '和冬天爺爺談談；他在鐵爐堡燻木牧場商人區旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8828 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8828, 'zhTW', '冬天的禮物', '我聽說冬天爺爺－在燻木牧場的慷慨支持下－已經把要給所有人的禮物放在奧格瑪的樹下。真希望我也能去，但是我必須看管這台PX-238冬幕歡樂製造器。不過你一定得去看看。我相信冬天爺爺已經準備好印有你名字的禮物了。', '和冬天爺爺談談。他在奧格瑪燻木牧場商人區旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8829 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8829, 'zhTW', '最後的詭計', '暮光之錘的運作機制有著數不清的保密措施。雖然他們的一舉一動影響著我們的世界，但他們策劃陰謀的大本營卻是在一個我們不知道的地方。$B$B我們開始相信暮光之錘用來召喚他們領導者的石頭可以雙向傳輸。因此我們要嘗試使用它，我們必須精雕細琢地仿製一件暮光大使的長袍。$B$B收集需要的材料並交給奧莉爾·金葉，$n。', '將1塊暗影之皮，3條磨損的憎惡縫合線和1件暮光信徒長袍帶到希利蘇斯給塞納里奧城堡的奧莉爾·金葉。你還必須將後勤任務簡報XI帶去才能完成這個任務。', '', '去希利蘇斯找塞納里奧要塞的奧蕾爾·金葉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8830 AND `locale` = 'zhTW';
