INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8867, 'zhTW', '新年煙火', '月光林地的德魯伊每年都會舉辦一次慶典，慶祝我們城市對抗遠古惡魔的偉大勝利。$B$B我們讚美長者的智慧，共享美食盛宴，當然還有…煙火秀！$B$B，這些可不是普通的煙火。它們受過伊露恩的祝福，經月火賜予力量，發射它們能提高人民的精神，振奮他們的力量。$B$B你只要捐獻一點東西就能跟我們的商人購買色彩繽紛的煙火。試試這附近的一些發射器吧，$N。', '點燃8枚新年煙花和2組新年煙花束，然後回到任何一座主城的新年預告者身邊。', '', '去找新年預告者。', '點燃新年煙火。', '點燃新年煙火束。', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8868 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8868, 'zhTW', '伊露恩的祝福', '年獸曾是這個世界的英雄。一隻有著極大力量和運氣的狼，在年獸屈服於惡魔魔法前，他都在先祖之戰的英雄身邊一起作戰。和他的盟友反目成仇後，他的怒火席捲了整個艾澤拉斯，所到之處充滿死亡和恐懼。$B$B最後終於在月光林地這裡被擊敗了，年獸現在沉睡在月神湖水中。但是每年新年，在慶典之中，他就會開始蠢蠢欲動…$B$B找些朋友，$N，召喚年獸並擊敗他。贏得伊露恩的祝福!', '召喚年獸，擊敗他並獲得伊露恩的祝福。再回到永夜港找瓦拉達爾·星歌。', '獲得伊露恩的祝福', '去月光林地找永夜港的瓦拉達爾·星歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8869, 'zhTW', '甜美的平靜', '平靜之劍位於血色堡壘內，紅衣鑄錘師以生命守護著它。打敗他，並將他的圍裙交給我。作為報答，我將訓練你成為鍛造戰錘的鐵匠。$B$B不過你要知道，一旦你選擇成為鑄錘師，就不能再學習打造刀劍和戰斧的技藝了。', '到斯坦索姆去殺死紅衣鑄錘師。將紅衣鑄錘師的圍裙交給莉莉絲。', '', '去冬泉谷找永望鎮的輕盈的莉莉絲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8870, 'zhTW', '新年慶典', '新年將至，$N！塞納里奧議會邀請艾澤拉斯大陸的居民，一同參加新年的慶祝活動。在這特有的城市有一個標示著神聖月光之環的地方，你可以在那兒找到新年預告者。她會告訴你更多關於節慶的訊息。', '與鐵爐堡秘法區的新年預告者談話，你也可以在其他主要城市跟新年預告者談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8871, 'zhTW', '新年慶典', '新年將至，$N！塞納里奧議會邀請艾澤拉斯大陸的居民，一同參加新年的慶祝活動。在這特有的城市有一個標示著神聖月光之環的地方，你可以在那兒找到新年預告者。她會告訴你更多關於節慶的訊息。', '與暴風城花園區的新年預告者談話，你也可以在其他主要城市跟新年預告者說話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8872, 'zhTW', '新年慶典', '新年將至，$N！塞納里奧議會邀請艾澤拉斯大陸的居民，一同參加新年的慶祝活動。在這特有的城市有一個標示著神聖月光之環的地方，你可以在那兒找到新年預告者。她會告訴你更多關於節慶的訊息。', '到達納蘇斯，與在塞納里奧區的新年預告者談話，你也可以在其他主要城市跟新年預告者談話。', '', '', '', '', '', '', 0);
