INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8883, 'zhTW', '瓦拉達爾·星歌', '既然你有新年邀請卡，你就能前往月光林地！你會在那裡看到許多狂歡者，瓦拉達爾·星歌和他的姊姊法莉爾·星歌在永夜港裡等著所有想積極參與慶祝活動的人。通過較強的月光前往月光林地並和瓦拉達爾·星歌談談；看看你能在新年裡得到什麼禮物！', '在月光中使用你的新年邀請卡前往月光林地。到達後和永夜港的瓦拉達爾·星歌交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8884 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8884, 'zhTW', '魚頭，魚頭……', '你好，$c。看看海岸邊;你看到了什麼?沒錯，我們的海灘…….我們的寧靜海岸，充斥著可惡的魚人。$B$B我們不容許他們這樣的毀壞!$B$B我有個任務要給你。只要你覺得可以接受的話，我要他們的頭!看看我們能不能大量削減他們的數量，讓他們知難而退，回到原本黑暗的深淵!', '收集8個厲鱗魚人頭顱。將它們帶到永歌森林裡俯瞰著寧靜海岸的懸崖給海斯維利·桑凱。', '', '去找永歌森林的海斯維利·桑凱。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8885 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8885, 'zhTW', '魔鉤的戒指', '厲鱗魚人並沒有被你的努力給嚇跑。但是，我想我知道什麼才會讓他們知難而退，還會給我帶來一些個人的報酬。$B$B他們有一個自稱魔鉤的魚人首領。他會在金色湖岸南邊的海岸閒晃。這隻野獸曾經殺過我一個伙伴，現在竟公然戴著他的戒指，簡直就是一種藐視與嘲笑。$B$B殺了魔鉤，把我朋友的戒指帶回來給我。然後我們就會看到這些怪物受驚嚇的樣子!', '從厲鱗首領麻木的爪子中取回魔鉤的戒指，交給在永歌森林裡俯瞰寧靜海岸的懸崖上的海斯維利·桑凱。', '', '去找永歌森林的海斯維利·桑凱。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8886 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8886, 'zhTW', '厲鱗劫掠者!', '喔，還好有你，$c!那些黏乎乎的厲鱗魚人搶走了我的貨物!鄙惡者把我那一丁點的魔法物品偷走已經夠糟了，這些魚人竟然還偷走剩下的!這個地方怎麼搞的?$B$B你可以幫我奪回我的貨物嗎?我不奢望你把它們全追回來，但如果你能幫我，我會非常感激。那群厲鱗魚人的小茅屋就在金色湖岸的泊地西方和南方，我確定!', '追回6個凱利山德拉船長的貨物帶到永歌森林，交給日帆泊地東邊防禦營地的凱利山德拉船長。', '', '去找永歌森林的凱利山德拉船長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8887 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8887, 'zhTW', '凱利山德拉船長遺失的航海方針', '真有趣.....你發現的是一個防水的皮管，裡面裝著好幾張紙。看上面的記號，這些紙是航海方針，每張上面都有一樣的簽名，凱利山德拉船長。$B$B你聽說日帆泊地東邊附近有一個小小的防禦營地。或許船長就在那裡?', '將凱利山德拉船長丟失的航海方針帶到永歌森林的日帆泊地，凱利山德拉船長就在東邊的防禦營地。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8888 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8888, 'zhTW', '博學者的學徒', '$C，聽好了。因為某些原因我現在不能進去，我決定關閉我附近的尖塔。幾天前，我派了一個學生，學徒羅勒塞拉斯，去那裡進行這個任務。從此就再也沒有聽到她的消息了。你可以進入暮萎尖塔看看她的狀況如何，確定她安然無恙嗎?你可以沿著遠行者居所外的小徑往北走，就能找到那座塔，然後在岔路右轉。謝謝你。', '和在永歌森林暮萎尖塔附近的學徒羅勒塞拉斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8889 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8889, 'zhTW', '關閉尖塔能源', '如你所知，博學者暮萎派我來這裡關閉供應尖塔的能源。有三個開關，分別在塔裡不同的地方。$B$B不幸的是，我來的太晚了，暮萎尖塔已經爬滿了奇怪的魔法生物。在我沒有專業技術可以完成這個任務時，像你這樣的$c，一定可以輕易的辦到吧?', '關閉暮萎尖塔內3個暮萎尖塔能量源。再將關閉能源珠寶帶回永歌森林交給學徒羅勒塞拉斯。', '', '去找永歌森林的學徒羅勒塞拉斯。', '第一個能源關閉', '第二個能源關閉', '第三個能源關閉', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8890 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8890, 'zhTW', '塔內的消息', '$N，我想請你幫我最後一個忙。你可以將這裡發現的東西轉達給遠行者居所的博學者暮萎嗎?讓他知道我很好，但確定他知道有些學徒已經成為鄙惡者的一員。謝謝你的幫忙!', '回到永歌森林的遠行者居所找博學者暮萎。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8891 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8891, 'zhTW', '放棄的調查', '你發現了一本應該是博學者暮萎留下的調查日誌。簡略的瀏覽後發現一些關於過濾墮落魔法流的驚人嘗試，可能可以解釋在暮萎尖塔這裡發生了什麼事。博學者肯定想要回這本日誌。', '將博學者的日誌帶到永歌森林給遠行者居所的博學者暮萎。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8892 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8892, 'zhTW', '日帆泊地的狀況', '日帆泊地已經快被鄙惡者那些敗類給淹沒了。只要我們一有援軍就要殺它們個片甲不留，$N。$B$B同時你可以幫我們給他們一點顏色瞧瞧。前往那裡讓他們知道我們不是好欺負的。', '殺死5名鄙惡者暴徒和5名鄙惡者流氓並向永歌森林的遊俠迪哥里恩回報。', '', '去找永歌森林的遊俠迪哥里恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8893 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8893, 'zhTW', '超級測蛋器', '', '超級測蛋器是克格爾·曲藤的最新成果，看起來真是令人印象深刻。你剛剛接觸到超級測蛋器的控制面板，它就劈啪作響了起來。', '', '去找塔納利斯的測蛋器。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8894 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8894, 'zhTW', '清理地面', '真是可怕，我告訴你!塔裡有奇怪的事發生，博學者和他的學徒紛紛逃跑，然後就是像你知道的那樣，整個地上充斥著這些魔法怪物!而誰告訴了威利坦?沒有人，你知道嗎!$B$B$C，你一定要幫我清理這些鬼東西…….有他們四處亂跑我無法維護土地整潔!', '殺死6隻法力毒蛇和6隻艾德惡魔再回到永歌森林向暗木營地的地面守衛者威利坦回報。', '', '去找永歌森林的地面守衛者威利坦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8895 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8895, 'zhTW', '北部聖所的貨物', '很高興知道你至少有點能力，$N。既然你如此想證明自己，我會給你另一個任務。$B$B這是給牧地看守者凱丹尼斯的信，他是負責維修北部聖所的秘法師。往獵鷹之翼廣場的西南方走你就會找到他。他是個很重要的人物，所以我希望你不要跟他講些無關緊要的瑣事。', '將無記號的信件帶到永歌森林交給北部聖所的牧地看守者凱丹尼斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8897 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8897, 'zhTW', '親愛的科蘭拉', '我得在城門駐守巡邏，但是我心裡一直想著我的戀人科蘭拉。如果幸運的話，我還能注視她一會兒；但是，你瞧瞧我，我不過是個薪水微薄的小軍官，隨時都可能奉命趕赴前線。$B$B她會忘記我嗎？城裡有那麼多男人，其中不乏有錢的傢伙。$B$B不管怎樣，我寫了一些東西給她……如果你能幫我交給她的話，我會很感謝你的。', '將亨德瑞克中尉精心書寫的信件交給暴風城銀行外面的科蘭拉·迪恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8898 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8898, 'zhTW', '親愛的科蘭拉', '我上次去暴風城銀行辦事時遇到一位少女。她偷走了我的心。現在，我想她想得快發瘋了！我想把這封信給她——我反反覆覆寫了12次呢！$B$B這封信裝滿了我的心意，我一定要讓她看看。$B$B如果你順路的話，能幫我這個忙嗎？', '將皺褶的信件交給暴風城銀行外面的科蘭拉·迪恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8899 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8899, 'zhTW', '最親愛的克萊拉', '要如何形容她的美麗？我想千言萬語也道不盡。$B$B這些人類混淆視聽，任由我們成了胡言亂語的傻瓜。$B$B我早就看那些文字不順眼了。而且我不想再擠出其他華麗的辭藻。對，她早就擁有了一切，否則其他的求婚者將佔據她視線，偷走她的眼眸。', '將完美無暇的信件遞給克萊拉·迪恩，她在暴風城的銀行外面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8900 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8900, 'zhTW', '最親愛的艾妮亞', '我看得出來她很傷心，看她過去的處境，我是說她似乎蠻難過的，你不覺得嗎?$B$B可是和她談過之後，我發現有個關聯。沒人懂我，但我覺得只有她能懂我。$B$B像我跟別人聊的時候，他們就只會笑我，而我也沒再跟她談天了。可是，我好想念她。你能幫我把這封信交給她嗎?我希望她能親自收到這封。', '將微皺的筆記送給幽暗城銀行旁的艾妮亞· 海頓。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8901, 'zhTW', '親愛的艾琳娜', '年輕的$c，你知道什麼是愛情嗎？我一直以為自己跟愛情扯不上什麼關係，直到最近在幽暗城邂逅了一位名叫艾琳娜的少女。我和我的族人們都不常外出，更不要說被遺忘者了。$B$B但是，我日日夜夜都在想她。$B$B你能幫我把這封信帶給她嗎？我想請她來莫高雷。希望她能接受我的邀請。', '將精心書寫的信件交給幽暗城銀行附近的艾琳娜·海東。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8902 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8902, 'zhTW', '最親愛的艾妮亞', '很久以前，我就和我的青梅竹馬艾妮亞訂下婚約。我已經很多年都不再想她了，但是最近，她又會不時的佔據我的腦海。$B$B或許，即使一切都過去了，每個人的生命中都還有點空間可以容納愛。$B$B我相信她也一定變了。你可以幫我把這封信送給她嗎？我太緊張了，不敢親自拿給她。', '將深情書寫的信送給幽暗城銀行附近的艾妮亞·海頓。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8903, 'zhTW', '危險的愛', '這種像傳染病的愛有些不對勁。這樣不太好，是個眼中釘，而且最糟的是，這對所有聯盟的人來說都是個威脅。$B$B你想想：要是守衛也感染了這種奇怪的病怎麼辦？我們一定要想個辦法。$B$B找到暴風城裡的一名守衛，看看他們是否已經得到了這愚蠢的病。', '取得一張暴風城守衛的卡片並帶給暴風城的艾里斯坦·莫塔。', '', '去找暴風城的艾里斯坦·莫塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8904, 'zhTW', '危險的愛', '這種像傳染病的愛有些不對勁。這情形很噁心，而且當它降低了我們的警戒心，對所有人來說都是個威脅。$B$B我們有這麼多人民都已經陷入如此荒繆的行為已經夠糟了。但我想這甚至還散播到我們的守衛那裡了，他們是應該對這種事免疫的人。$B$B找一名我們的守衛，看看他們是否已經得到了這愚蠢的病。', '取得一張守衛者的發霉卡片並帶給幽暗城的芬斯塔德·阿吉歐。', '', '去找奧特蘭克山脈的芬斯塔德·阿吉歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8905 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8905, 'zhTW', '誠摯的建議', '你好，$c。我有一些你可能會感興趣的東西。$B$B它很像你們那個職業的人會穿戴的典型護甲，但是等級高很多。只要你幫我一個小忙，我願意和你交換一件普通裝備。$B$B冬泉谷的霜刃豹和熊的鮮血裡有我目前需要的成分。幫我帶來足夠的樣本還有護腕裝備，以及一點金子。你會發現你的付出是值得的。', '取得15滴冬泉血滴樣本，20金和1套野性之心護腕給鐵爐堡的德莉娜。', '', '去鐵爐堡找王座廳的德莉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8906 AND `locale` = 'zhTW';
