INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8920, 'zhTW', '誠摯的建議', '嗨，$c!我從你舉止可以看出，你已經見識過這世界許多事了。但是我敢打賭你一定沒有看過像這樣的護甲。$B$B幫我個小忙，我就和你交換一套普通的護腕。$B$B我現在需要足夠的希利蘇斯蜘蛛與蠍的毒液樣本。把物品帶給我再加上幾枚金幣，我就履行這項交易。', '取得15份希利蘇斯血液樣本，20金和1套勇氣護腕，帶給奧格瑪的莫克瓦。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8921, 'zhTW', '外膜蒸餾器', '啊，你需要我最新的工程研究……超空間鬼魂顯像機!不幸的是我沒有資金和人力了。$B$B你願意幫忙?太好了!我們的第一項任務是建構一個可以取得死者組織的儀器!製作一個外膜蒸餾器不是件簡單的事，$n。$B$B我需要你幫我帶來一個奧金轉換器，一些強效不滅精華和石鱗魚油。我還需要燃燒平原熔岩池裡的火山灰來製作一個過濾器。', '將1個精密奧金轉換器、4份強效不滅精華、10瓶石鱗魚油，25份火山灰和40金交給在加基森的莫克斯·法力爭奪者。', '', '去找塔納利斯的穆克斯·瑪納斯卡波。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8922, 'zhTW', '超自然儀器', '我一定要找到和安希恩·哈莫談話的方法……或者正確的說，是他的鬼魂!$B$B我知道有個工程師對超自然有奇怪的癖好。他聲稱能夠製造一種和亡靈說話的機器!$B$B你收集的血液正是他要的，拿到加基森給他，就當作是他工作的酬勞!', '將密封的鮮血採樣瓶帶到塔納利斯的加基森，交給莫克斯·法力爭奪者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8923, 'zhTW', '超自然儀器', '在那之後你還敢留在附近真是勇敢。應該是因為我給你的護甲讓你激起了興趣吧。還有更多護甲，只要你還有興趣幫我。$B$B你收集的毒液樣本是要給我一個朋友的，他叫莫克斯·法力爭奪者，是個對超自然很有興趣的工程師。他最近的研究就是製作了一個和亡者溝通的儀器!我最後的希望是聯絡安希恩，了解更多我的狀況。', '將密封的毒液交給在加基森的莫克斯·法力爭奪者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8924, 'zhTW', '尋找外膜', '真是件好工程，我是這麼告訴自己的!恐怕你會為了尋找無形的不死族，而走上好一段路。$B$B你要了解，不同的天氣就會有不同的不死鬼靈結構。在希利蘇斯受盡折磨的夜精靈、冬泉谷的精靈貴族靈魂和東瘟疫之地的鬼魂和女妖會有我們需要的不同外膜。在你取得他們之前記得將蒸餾器放在附近!', '前往東瘟疫之地，在無形的不死族附近使用外膜蒸餾器收集12個希利蘇斯燒焦的外膜、12個冬泉谷冰凍的外膜和12個東瘟疫之地穩定的外膜。將它們和外膜蒸餾器一起交給在加基森的莫克斯·法力爭奪者。', '', '去塔納利斯找加基森的穆克斯·瑪納斯卡波。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8925 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8925, 'zhTW', '攜帶式能量泉源', '現在我們需要找到穩定、可攜帶式的能量泉源以供外膜存活。我聽說一個叫做熔岩領主博克的強大元素，他的心臟是一個強大的岩漿之核 - 可以無盡的供給熱能!$B$B據說在燃燒平原可找到他。將岩漿之核帶來給我，我們就能獲得足夠的能量啟動超空間鬼魂顯像機!', '去燃燒平原找到熔岩領主博克，取得他的岩漿之核帶給在加基森的莫克斯·法力爭奪者。', '', '去塔納利斯找加基森的穆克斯·瑪納斯卡波。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8926, 'zhTW', '公平的補償', '你信守承諾將莫克斯建構的儀器帶來了。我相信如果我給你獎賞，你會感興趣的。若你想升級的話，就把腰帶和一整套手套拿來給我。我承諾我交還給你的一定是更為精良的物品。', '將野性之心腰帶，一套野性之心手套帶給鐵爐堡的德莉娜。', '', '去鐵爐堡找王座廳的德莉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8927, 'zhTW', '公平的補償', '你證明了自己是個非常可靠的人，$N。我相信你會幫我度過這次的困境，我會依照你的表現來給予獎勵。$B$B現在我要把你的腰帶和手套換掉。如果我們一起度過了這個難關，我就會把剩下的裝備都做給你。', '將野性之心腰帶和1套野性之心手套帶給奧格瑪的莫克瓦。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8928, 'zhTW', '狡猾的商人', '精華讓我們有足夠的能量發動我們的儀器，現在我們只需要製作一個可以導入能量，不會融化成灰燼的魔棒。$B$B我在冬泉谷遇到一個小鬼專門賣各式各樣的異國物品。他帶著一個很棒的元素魔棒。我現在真的很懊惱當初沒有買下它。$B$B他就住在暗語峽谷入口的一個洞穴裡。潛入那裡看看你能否找到他。$B$B確定一下他是不是跟你酌收40金，那是他跟我說好的價錢!', '前往冬泉谷南方的暗語峽谷入口，向住在洞穴裡的小鬼買下一把惡魔元素魔棒，再回到加基森的莫克斯·法力爭奪者那裡。', '', '去找塔納利斯的穆克斯·瑪納斯卡波。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8929 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8929, 'zhTW', '尋找安希恩', '嗯，我們現在沒什麼事做了，但還是試試哥布林的發明吧。聽說安希恩在進入斯坦索姆大門的時候被不死軍團給殲滅了。$B$B試著到那裡使用這個儀器，了解安希恩知道的所有事。', '在斯坦索姆的入口使用超空間鬼魂顯像機並和安希恩·哈莫的鬼魂談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8930, 'zhTW', '尋找安希恩', '非常好，$n。現存要測試的部份都放在哥布林的發明裡了。有人說安希恩準備進大門時，就已經被斯坦索姆的不死生物軍團所殺害。$B$B試用那裡的裝置，看看可不可以和不死生物對談!', '在斯坦索姆的入口使用超空間鬼魂顯像機並和安希恩·哈莫的鬼魂談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8931, 'zhTW', '公平的補償', '你做到了你所承諾的事，把穆克斯製造的裝備給我帶了回來，那麼我也按承諾給予你一件不錯的獎勵。把你原先使用的腰帶和手套拿來吧，我會幫你升級它們。', '將一條馭獸者腰帶和一副馭獸者手套交給鐵爐堡的德莉娜。', '', '去鐵爐堡找王座廳的德莉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8932, 'zhTW', '公平的補償', '你信守承諾將莫克斯建構的儀器帶來了。我相信如果我給你獎賞，你會感興趣的。若你想升級的話，就把普通腰帶和整套手套拿來給我。', '將博學者腰帶和1套博學者手套帶給鐵爐堡的德莉娜。', '', '去鐵爐堡找王座廳的德莉娜。', '', '', '', '', 0);
