INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8942, 'zhTW', '公平的補償', '你證明了自己是個非常可靠的人，$N。我相信你會幫我度過這次的困境，我會依照你的表現來給予獎勵。$B$B現在就交換你的腰帶和護手。如果我們一起度過了這個難關，我就會把剩下的裝備都做給你。', '將元素之索和1套元素護手帶給奧格瑪的莫克瓦。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
