INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8943, 'zhTW', '公平的補償', '你證明了自己是個非常可靠的人，$N。我相信你會幫我度過這次的困境，我會依照你的表現來給予獎勵。$B$B現在我要把你的腰帶和手套換掉。如果我們一起度過了這個難關，我就會把剩下的裝備都做給你。', '將鬼霧腰帶和1套鬼霧手套帶給奧格瑪的莫克瓦。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8944 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8944, 'zhTW', '公平的補償', '你證明了自己是個非常可靠的人，$N。我相信你會幫我度過這次的困境，我會依照你的表現來給予獎勵。$B$B現在就交換你的腰帶和護手。如果我們一起度過了這個難關，我就會把剩下的裝備都做給你。', '將勇氣腰帶和1套勇氣護手帶給奧格瑪的莫克瓦。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8945 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8945, 'zhTW', '逝者的請求', '我會為你解答，$n。但是目前我手上有更多緊要的事。$B$B我摯愛的妻子被瑞文戴爾的不死敗類給囚禁了。$B$B我本來就很不贊成她加入銀色黎明的愚蠢軍隊，但是那也不重要了。你一定要完成我要你做的事，一定要從瑞文戴爾男爵手中救出亞希達!', '前往斯坦索姆從瑞文戴爾男爵那裡救出亞希達·哈莫。', '', '去找斯坦索姆的伊思達·哈爾蒙。', '解救伊思達', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8946 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8946, 'zhTW', '生命的證據', '我的愛人在救我的時候死去，這實在是命運最殘忍的事了。但是你聲稱擁有和他交談的能力。$B$B把這個小盒子拿給他，讓他知道我還好好的。他絕對不要在這個世界遊盪了，我的心無法承受。$B$B再會了，$n。我永遠欠你一份人情。', '將亞希達的小墜子帶給東溫疫之地的安希恩·哈莫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8947, 'zhTW', '安希恩奇怪的要求', '我們並不了解瓦薩拉克勳章的重要性，所以它才會跟其他戰利品一起被瓜分。第一塊被一個叫瑟爾倫的矮人拿走。我試著從他那裡把它取回來，結果他把我教訓了一頓。你要使用武力把那個碎片拿回來。$B$B我聽說瑟爾倫成為黑鐵矮人的戰士。要和他進行一場打鬥是不小的挑戰。$B$B幫我收集下列的材料。你會需要它們的。', '將3塊黑鐵錠，20塊附魔皮，3塊月布和4塊熟化毛皮帶給東溫疫之地的安希恩·哈莫。', '', '去東瘟疫之地找斯坦索姆的安泰恩·哈爾蒙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8948 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8948, 'zhTW', '安希恩的老朋友', '瑟爾倫不是個願意參戰的人。我製作了這面旗幟以顯現他的家族色彩。$B$B只要加上一點巫術，這面旗幟就會誘導他使他無法抵抗。$B$B我有一個老同事叫法琳，他知道詳細的製作過程。他是個很特別的……惱怒的人。你可以在厄運之槌的圖書館找到他。', '將不完整的挑釁旗幟帶到厄運之槌的圖書館給法琳·樹形者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8949 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8949, 'zhTW', '法琳的仇恨', '是的，我的確熟悉你所需要的附魔，$c。但是我不是免費幫忙的人，就算你是我的老友派來的也一樣。$B$B我對我們粗野的巨魔鄰居只有仇恨和鄙視。不只他們，我對歐莫克的追隨者和戈多克大王的追隨者都一樣痛恨。$B$B我要你去殺了他們。殺越多越好!幫我把他們脖子上戴的串珠拿來作為你努力的證據。照著做，我們就能談談你的要求。', '從厄運之槌或黑石塔的巨魔身上收集25個巨魔戰爭串珠再回到厄運之槌圖書館找法琳·樹形者。', '', '去奧特蘭克山脈找達拉然巨坑的法爾林·樹影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8950 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8950, 'zhTW', '教唆者的附魔', '我可以將你需要的附魔輕鬆地施放在旗幟上，$n。不幸的是，我沒有需要的材料，因為它非常稀有，以致於想附魔的人都會惹上麻煩。$B$B我需要在這些大廳陰魂不散的艾德雷斯鬼魂精華，一把通靈學院黑暗符文和一些大塊魔光裂片。把這些材料帶給我，我就會幫你完成任務。', '將以下的物品帶給厄運之槌的法琳·樹形者:1份嘲弄幽靈精華，4個黑暗符文和8個大塊魔光裂片。', '', '去菲拉斯找厄運之槌圖書館的法爾林·樹影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8951, 'zhTW', '安希恩的離別感言', '瓦薩拉克的靈魂被存封在這個護符裡。因為我們的貪婪，愚蠢地把護符分成三塊，不知道有可怕的詛咒在等著我們。$B$B阻止瓦薩拉克魔法的唯一方法就是將勳章重新組合回去。回到德莉娜那裡，告訴她布德利是找到剩下護符的唯一希望。和她談談為你安排的獎勵。$B$B我，這一次，終於可以安息了。祝你好運;你需要這份好運的!', '帶著野性之心長靴，野性之心褶裙和野性之心肩甲回到鐵爐堡的德莉娜那裡。', '', '去鐵爐堡找王座廳的德莉亞娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8952 AND `locale` = 'zhTW';
