INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8958, 'zhTW', '安希恩的離別感言', '瓦薩拉克的靈魂被存封在這個護符裡。因為我們的貪婪，愚蠢地把護符分成三塊，不知道有可怕的詛咒在等著我們。$B$B阻止瓦薩拉克魔法的唯一方法就是將勳章重新組合回去。回到德莉娜那裡，告訴她布德利是找到剩下護符的唯一希望。和她談談為你安排的獎勵。$B$B我，這一次，終於可以安息了。祝你好運;你需要這份好運的!', '帶著鬼霧便鞋，鬼霧護腿和鬼霧披肩回到鐵爐堡的德莉娜那裡。', '', '去鐵爐堡找王座廳的德莉亞娜。', '', '', '', '', 0);
