INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8959, 'zhTW', '安希恩的離別感言', '瓦薩拉克的靈魂被存封在這個護符裡。因為我們的貪婪，愚蠢地把護符分成三塊，不知道有可怕的詛咒在等著我們。$B$B阻止瓦薩拉克魔法的唯一方法就是將護符重新組合回去。回到德莉娜那裡，告訴她布德利是找到剩下護符的唯一希望。和她談談為你安排的獎勵。$B$B我，這一次，終於可以安息了。祝你好運；你需要這份好運的！', '帶著勇氣戰靴，勇氣腿鎧和勇氣肩甲回到鐵爐堡的德莉娜那裡。', '', '去鐵爐堡找王座廳的德莉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8960, 'zhTW', '布德利不幸的命運', '所以我們要找到剩下的勳章?要找到布德利是件頭痛的事。他回到了黑石山想再次進入黑石塔，但他從此就沒有再回來過了。$B$B我建議你帶著哥布林的鬼魂顯像機，因為我怕我最擔心的事情可能會發生。', '到黑石山並使用超空間鬼魂顯像機，去黑石塔附近尋找布德利。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8961, 'zhTW', '烈焰三巨頭', '為了要召喚瓦薩拉克領主，我們首先要收集另外三分之二的護符。為此，我們需要火盆和一些特別的煤燃燒。$B$B我們需要三種火元素貴族手上的東西，黑石深淵的伊森迪奧斯，黑石塔的烈焰衛士艾博希爾，和希利蘇斯的辛德爾公爵。收集他們那裡的殘餘，然後和神聖火盆一起交給我，若銀色黎明尊敬你的話，你就可以從他們那裡獲得。', '收集伊森迪奧斯的煤渣，艾博希爾的煤炭和辛德爾的煤渣，並帶著神聖火盆回到黑石山找布德利。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8962, 'zhTW', '重要的材料', '$C，仔細聽好了。既然我們有了火盆和點燃它的方法，我們還需要另一個材料來注入火盆；一種強大的集中力來誘使我已故亡友的靈魂出現。$B$B莫爾·灰蹄，我們最重要的德魯伊，在塞納里奧議會有很多親密的朋友，其中有些人已被異種消滅。我要你去希利蘇斯從雷戈蟲巢的異種身上取得德魯伊遺骨。', '取得德魯伊的遺體，再回到黑石山找布德利。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8963, 'zhTW', '重要的材料', '$C，仔細聽好了。既然我們有了火盆和點燃它的方法，我們還需要另一個材料來注入火盆；一種強大的集中力來誘使我已故亡友的靈魂出現。$B$B伊薩利恩，我們的女祭司，在星風村的冬泉谷長大。我要你去冬泉谷南邊的霜語峽谷，從那裡的霜槌巨人身上取得星風村聖物，他們有時候會襲擊北方。', '取得星風村聖物，再回到黑石山找布德利。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8964, 'zhTW', '重要的材料', '$C，仔細聽好了。既然我們有了火盆和點燃它的方法，我們還需要另一個材料來注入火盆；一種強大的集中力來誘使我已故亡友的靈魂出現。$B$B賈林和索索斯這對兄弟是血色十字軍的信徒。他們渴望在那個邪惡的組織裡成為騎士。前往東瘟疫之地的提爾之手，從血色禁衛隊那裡取得光亮的狂熱之劍。', '取得光亮的狂熱之劍，再回到黑石山找布德利。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8965, 'zhTW', '重要的材料', '$c，仔細聽好了。既然我們有了火盆和點燃它的方法，我們還需要另一個材料來注入火盆;一種強大的集中力來誘使我已故亡友的靈魂出現。$B$B有個跟我們同行的死靈法師，科爾莫克，喜愛召喚贖罪島上被流放的亡者靈魂，那個地方就在希爾斯布萊德丘陵南邊海岸。去那裡的遺跡取得一些被流放的靈魂灰燼。', '取得流放者的靈魂灰燼，再回到黑石山找布德利。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8966, 'zhTW', '瓦薩拉克護符的左半塊', '我的朋友，莫爾·灰蹄，是第一個因為擁有瓦薩拉克的護符碎片和其中包含的腐敗靈魂碎片而受害的人。在偷了瓦薩拉克的法術書和護符之後，我們就立刻從黑石塔上層逃走。途中，莫爾跌進了塔底。$B$B之後，我們發現他並沒有摔死，只是被指揮官沃恩俘虜起來且受盡折磨。幾個鬼魂刺客溜進去在沃恩面前把他給殺了。', '使用召喚火盆來召喚莫爾·灰蹄的靈魂並殺了他。帶著瓦薩拉克護符的左半塊和召喚火盆回到黑石山的布德利那裡。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8967, 'zhTW', '瓦薩拉克護符的左半塊', '後來的日子裡我們發現，就在我們努力生存時，我們公司那個叫依薩利恩的夜精靈女祭司已回到她古老城市的家園，現在稱為厄運之錘。據我們所知，她是為了私人因素回去的，同時也為了解開她擁有護符的秘密。$B$B不過，她沒有很成功。聽說她在艾德雷斯神殿被奧茲恩和他的手下給伏擊了。', '使用召喚火盆來召喚依薩利恩的靈魂並殺了她。帶著瓦薩拉克護符的左半塊和召喚火盆回到黑石山的布德利那裡。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8968, 'zhTW', '瓦薩拉克領主護符的左半塊', '賈林和索索斯這對兄弟，決定要加入血色十字軍因為我們的傭兵公司要解散了。他們帶著瓦薩拉克領主的左半塊護符。我說這真是一個很好的解脫，但我們需要拿回那個東西。$B$B據消息指出，他們是因為在血色十字軍堡壘的創始祭儀失敗，被大十字軍戰士達索漢在他的房間裡殺死。$B$B無論如何，我們……也就是你，還是要把那塊護符討回來。', '使用召喚火盆來召喚賈林和索索斯並殺了他們。帶著瓦薩拉克領主護符的左半塊和召喚火盆回到黑石山的布德利那裡。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8969, 'zhTW', '瓦薩拉克領主護符的左半塊', '現在我們有了需要的東西，該是討論你下一個要召喚的人的時候了。$B$B科爾莫克在巨魔中算是好的，讓他恢復正常直到他求助於巫術為止。在那之後，事情因每個人的裝備而變的棘手。當他拿著他的護符回到新家，通靈學院時，一點也不令人驚訝。$B$B但是就連在那裡，或是尤其在那裡，他仍無法免於鬼靈刺客的威脅。他們就在他的主人萊斯·霜語面前殺了他。', '使用召喚火盆召喚科爾莫克的靈魂並殺了他。帶著瓦薩拉克領主護符的左半塊和召喚火盆回到黑石山的布德利那裡。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8970, 'zhTW', '我看見你的未來有奧卡茲島……', '我說，$c，在我有生之年，我曾一時興起想成為一個預言師。但是，這工作賺的錢並沒有你想像的多，因為這是個危險的工作，試劑既稀有又昂貴。然而，我有足夠的能力可以精確地指出最後一塊護符的位置，還有和它在一起的老友靈魂。$B$B你從那裡走進來，$n。我要你再走出去，到離塵泥沼澤海岸不遠的奧卡茲島，從斯塔沙茲納迦身上收集血巨藻。', '在斯塔沙茲納迦身上收集20份血巨藻再回到黑石山的布德利那裡。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8971 AND `locale` = 'zhTW';
