INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8977, 'zhTW', '回到德莉娜那裡', '和你一起工作很愉快，$n。這是完成的產品。$B$B希望它能對你目前的努力有所幫助。還有，如果你不介意，幫我宣傳一下。我不介意有更多的顧客!', '將超空間鬼魂顯像機帶給鐵爐堡的德莉娜。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8978 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8978, 'zhTW', '回到莫克瓦那裡', '和你一起工作很愉快，$N。這是完成的產品。$B$B希望它能對你目前的努力有所幫助。還有，如果你不介意，幫我宣傳一下。我不介意有更多的顧客！', '帶著超空間靈體顯像機回到奧格瑪的莫克瓦那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8979 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8979, 'zhTW', '芬斯塔德的直覺', '我想我知道造成最近這種情況的原因。你有沒有在運河上聞過新的香水味？新上市的古龍水和香水？$B$B我們的思想已經被一些邪惡的煉金術給混亂了。$B$B只有一個方法可以確定 - 帶一瓶古龍水和香水給我的朋友，藥劑師金格。皇家藥劑學會會找出真相的。$B$B你回來後我會補償你購買香水的錢。', '帶1個古龍水瓶和1個香水瓶給幽暗城煉金區的藥劑師金格。', '', '去找奧特蘭克山脈的藥劑師金格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8980 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8980, 'zhTW', '金格的估計', '真是出乎意料。看來芬斯塔德一定對某些東西很熟悉。我發現了控制心智的藥劑本質遺跡。$B$B裡面有些成分香水裡的確會有，但是我發現少數一些成分...這是很高深的煉金術，屬於皇家藥劑師學會成員的技能。', '回到幽暗城的銀行外找芬斯塔德·阿吉歐。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8981, 'zhTW', '送禮物', '', '', '', '去找丘比特·傳播者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8982, 'zhTW', '追溯來源', '我們一定要找出誰是供應商。我注意到藥劑師卡崔娜把一瓶香水藏在她的背包裡。她說她是跟旅店老闆諾曼買的。', '和幽暗城的旅店老闆諾曼談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8983, 'zhTW', '追溯來源', '我的產品有什麼問題嗎？嗯，我從沒看過這麼多人都如此想得到一個東西。我是跟一個叫瑪拉·瑞尼克的商人購買我的補給。她是鎮上新來的。她提到有一些東西要送到法師區的裁縫師那裡。', '前往幽暗城的法師區，到裁縫師的店裡和瑪拉·瑞尼克談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8984, 'zhTW', '揭露來源', '聽好，盜賊藥劑師的行為並不是我所擔心的。如果他正暗中破壞我們的努力，就讓我第一個指引你正確的方向。如果他是無辜的，那他也沒什麼好怕的，對嗎？我這些東西是跟藥劑師史塔弗隆·雷倫買的。他正在希爾斯布萊德丘陵越過拉文霍德莊園的隱密區域工作。老實跟你說，我覺得他有點怪怪的。', '越過拉文霍德莊園，找到希爾斯布萊德丘陵上的藥劑師史塔弗隆·雷倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8985, 'zhTW', '更多重要的材料', '$c，仔細聽好了。既然我們知道了最後一塊護符的位置，我們還需要另一個材料來注入火盆;一種強大的集中力來誘使我已故亡友的靈魂出現。$B$B依薩利恩，我們的女祭司，在星風村的冬泉谷長大。我要你去冬泉谷南邊的霜語峽谷，從那裡的霜槌巨人身上取得星風村聖物，他們有時候會襲擊北方。', '取得星風村聖物，再回到黑石山找布德利。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8986, 'zhTW', '更多重要的材料', '$C，仔細聽好了。既然我們知道了最後一塊護符的位置，我們還需要另一個材料來注入火盆；一種強大的集中力來誘使我已故亡友的靈魂出現。$B$B莫爾·灰蹄，我們最重要的德魯伊，在塞納里奧議會有很多親密的朋友，其中有些人已被異種消滅。我要你去希利蘇斯從雷戈蟲巢的異種身上取得德魯伊遺骨。', '取得德魯伊的遺體，再回到黑石山找布德利。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8987 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8987, 'zhTW', '更多重要的材料', '$C，仔細聽好了。既然我們知道了最後一塊護符的位置，我們還需要另一個材料來注入火盆；一種強大的集中力來誘使我已故亡友的靈魂出現。$B$B賈林和索索斯這對兄弟是血色十字軍的信徒。他們渴望在那個邪惡的組織裡成為騎士。前往東瘟疫之地的提爾之手，從血色禁衛隊那裡取得光亮的狂熱之劍。', '取得光亮的狂熱之劍，再回到黑石山找布德利。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8988 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8988, 'zhTW', '更多重要的材料', '$c，仔細聽好了。既然我們知道了最後一塊護符的位置，我們還需要另一個材料來注入火盆；一種強大的集中力來誘使我已故亡友的靈魂出現。$B$B有個跟我們同行的巨魔巫師，科爾莫克，喜愛召喚贖罪島上被流放的亡者靈魂，那個地方就在希爾斯布萊德丘陵南邊海岸。去那裡的遺跡取得一些被流放的靈魂灰燼。', '取得流放者的靈魂灰燼，再回到黑石山找布德利。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8989 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8989, 'zhTW', '瓦薩拉克領主護符的右半塊', '我的朋友，莫爾·灰蹄，是第一個因為擁有瓦薩拉克領主的護符碎片和其中包含的腐敗靈魂碎片而受害的人。在偷了瓦薩拉克的法術書和護符之後，我們就立刻從黑石塔上層逃走。途中，莫爾跌進了塔底。$B$B之後，我們發現他並沒有摔死，只是被指揮官沃恩俘虜起來且受盡折磨。幾個鬼靈刺客溜進去在沃恩面前把他給殺了。', '使用召喚火盆召喚莫爾·灰蹄的靈魂並殺了他。帶著重新組合的瓦薩拉克領主的護符和召喚火盆回到黑石山的布德利那裡。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8990 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8990, 'zhTW', '瓦薩拉克領主護符的右半塊', '後來的日子裡我們發現，就在我們努力生存時，我們公司那個叫依薩利恩的夜精靈女祭司已回到她古老城市的家園，現在稱為厄運之槌。據我們所知，她是為了私人因素回去的，同時也為了解開她擁有護符的秘密。$B$B不過，她並沒有成功。聽說她在艾德雷斯神殿被奧茲恩和他的手下給伏擊了。', '使用召喚火盆召喚依薩利恩的靈魂並殺了她。帶著重新組合的瓦薩拉克領主護符和召喚火盆回到黑石山的布德利那裡。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8991 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8991, 'zhTW', '瓦薩拉克護符的右半塊', '賈林和索索斯這對兄弟，決定要加入血色十字軍因為我們的傭兵公司要解散了。他們帶著瓦薩拉克護符的右半塊。我說這真是一個很好的解脫，但我們需要拿回那個東西。$B$B據消息指出，他們是因為在血色十字軍堡壘的創始儀式失敗，被大十字軍戰士達索漢在他的房間裡殺死。$B$B無論如何，我們…也就是你，還是要把那塊護符討回來。', '使用召喚火盆召喚賈林和索索斯並殺了他們。帶著重新組合的瓦薩拉克護符和召喚火盆回到黑石山的布德利那裡。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8992 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8992, 'zhTW', '瓦薩拉克護符的右半塊', '現在我們有了需要的東西，該是討論你下一個要召喚的人的時候了。$B$B科爾莫克在巨魔中算是好的，讓他恢復正常直到他求助於巫術為止。在那之後，事情因每個人的裝備而變的棘手。當他拿著他的護符回到新家，通靈學院時，一點也不令人驚訝。$B$B但是就連在那裡，或是尤其在那裡，他仍無法倖免於鬼魂刺客的威脅。他們就在他的主人萊斯·霜語面前殺了他。', '使用召喚火盆召喚科爾莫克的靈魂並殺了他。帶著重新組合的瓦薩拉克護符和召喚火盆回到黑石山的布德利那裡。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8993 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8993, 'zhTW', '送禮物', '', '', '', '去找匹德菲特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8994 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8994, 'zhTW', '最後的準備', '我們就快準備好了，$c。剩下要做的就是再取得一些材料讓火盆調合，才能召喚瓦薩拉克領主。$B$B首先，我要請你前往黑石塔並殺死那裡的獸人。他們戴著含有追蹤金屬的護腕，我需要那個，所以我需要你去殺多一點人，我才能獲得足夠的護腕。然後，要完成注入的工作，你需要幫我帶來回１瓶超級能量精煉藥劑。$B$B祝你好運!$n!', '收集40個黑石護腕和1份超級能量精煉藥劑。把它們帶給黑石山上的布德利。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8995 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8995, 'zhTW', '認錯，瓦薩拉克領主', '現在一切都就緒了，$n。$B$B瓦薩拉克領主還活著的時候都住在野獸的房間。去那裡挑戰野獸，使用召喚火盆召喚出瓦薩拉克。它會再次與他結合，所以要再次殺死他。我會先解決野獸，記得多帶點朋友去黑石塔上層。$B$B一旦你解決了瓦薩拉克，在他的屍體上使用他的護符。當他的靈魂重新結合後，他也可能會想要回他的護符。$B$B祝你好運!', '用召喚火盆召喚出瓦薩拉克領主。殺了他，在他的屍體上使用瓦薩拉克的護符。然後，將瓦薩拉克領主護符還給瓦薩拉克領主之靈。', '', '去找黑石塔的瓦塔拉克公爵之魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8996 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8996, 'zhTW', '回到布德利那裡', '我會原讓你這次的無禮，因為你今天做了一件高尚的事，$c，那就是帶回我被偷走的靈魂。儘管你的本性明顯地處於弱勢，$r，你仍然展現了比別人更多的勇氣，就連從我這裡偷走東西的人也沒有你強，或許永遠也不會有人比得上你。$B$B趁我還沒改變心意殺了你之前，回到他們那裡去。回去告訴他們，他們很安全…至少現在是。', '回到黑石山的布德利那裡並將召喚火盆交給他。', '', '去找燃燒平原的伯德雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8997, 'zhTW', '回到原點', '我想是說再見的時候了，我的朋友。但是，如果你偶爾想回來和我談談，我都在這裡。或許就在你等待朋友加入黑石塔的突擊時。$B$B去吧，在我開始落淚之前離開。回到鐵爐堡的德莉娜那裡，告訴她發生了什麼事。', '回到鐵爐堡的王座廳和德莉娜談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8998, 'zhTW', '回到原點', '我想是說再見的時候了，我的朋友。但是，如果你偶爾想回來和我談談，我都在這裡。或許就在你等待朋友加入黑石塔的突擊時。$B$B去吧，在我開始落淚之前離開。回到奧格瑪的莫克瓦那裡，告訴他發生了什麼事。', '回到奧格瑪智慧谷在索爾的堡壘中找莫克瓦談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 8999 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (8999, 'zhTW', '最後的獎賞', '這真是個不可思議的故事，$N！謝謝你，我保證，所有相關的人都衷心的感激你。現在我或許可以安心的入眠了。$B$B至於你的獎勵，我確信這幾樣東西你會很喜歡。', '將你的野性之心風帽和野性之心外衣交給德莉娜。', '', '去鐵爐堡找王座廳的德莉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9000 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9000, 'zhTW', '最後的獎賞', '這真是個不可思議的故事，$N！謝謝你，我保證，所有相關的人都衷心的感激你。現在我或許可以安心的入眠了。$B$B至於你的獎勵，我確信這幾樣東西你會很喜歡。', '將你的馭獸者之帽和馭獸者外套交給德莉娜。', '', '去鐵爐堡找王座廳的德莉娜。', '', '', '', '', 0);
