INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9007, 'zhTW', '最後的獎賞', '真是個不可思議的故事，$N！謝謝你，我保證，所有相關的人都衷心的感激你。因為你的努力，我們走出了從前犯的錯誤。$B$B至於你的獎勵，我確信這幾樣東西你會很喜歡。', '將你的野性之心兜帽和野性之心外衣交給莫克瓦。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9008 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9008, 'zhTW', '最後的獎賞', '確實是個令人驚異的故事，$n！我實在是太感謝你了，其他一些與此有關的人也會對你表示真心誠意的感激，這一點我向你保證。你的努力使我們終於認識到了自己過去所犯的錯誤。這兒還有些你絕對會很喜歡的東西，送你算作獎勵吧。', '將你的馭獸者之帽與馭獸者外套交給莫克瓦爾。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9009 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9009, 'zhTW', '最後的獎賞', '真是個不可思議的故事，$N！謝謝你，我保證，所有相關的人都衷心的感激你。因為你的努力，我們走出了從前犯的錯誤。$B$B至於你的獎勵，我確信這幾樣東西你會很喜歡。', '將你的虔誠之冠和虔誠長袍交給莫克瓦。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
