INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9015, 'zhTW', '挑戰', '仔細聽好，$n。想讓旗幟照著計劃運作，你就必須進入黑石深淵競技場。讓裁決者格里斯通對你宣判並將旗幟穩穩地放在地上作為藐視他的動作。$B$B你的受害者將無法控制他自己，變的狂怒而向你挑戰。一旦你得到尋找的東西，就去找安希恩。', '前往黑石深淵競技場並在你被裁決者格里斯通宣判時將挑釁旗幟放在它的中央。殺死瑟爾倫和他的戰士們，再帶著第一塊瓦薩拉克領主護符回到東瘟疫之地的安希恩·哈莫那裡。', '', '去東瘟疫之地找斯坦索姆的安泰恩·哈爾蒙。', '打敗塞爾德林的小隊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9016 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9016, 'zhTW', '安希恩的離別感言', '瓦薩拉克的靈魂被存在這個護符裡。因為我們的貪婪，愚蠢地把護符分成三塊，不知道有可怕的詛咒在等著我們。$B$B阻止瓦薩拉克的魔法的唯一方法就是將護符重新組合回去。回到莫克瓦那裡，告訴他布德利是找到剩下護符的唯一希望。和他談談為你安排的獎勵。$B$B我，這一次，終於可以安息了。祝你好運；你需要這份好運的！', '帶著野性之心長靴，野性之心褶裙和野性之心肩甲回到奧格瑪的莫克瓦那裡。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9017 AND `locale` = 'zhTW';
