INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9022, 'zhTW', '安希恩的離別感言', '瓦薩拉克的靈魂被存在這個護符裡。因為我們的貪婪，愚蠢地把護符分成三塊，不知道有可怕的詛咒在等著我們。$B$B阻止瓦薩拉克的魔法的唯一方法就是將護符重新組合回去。回到莫克瓦那裡，告訴他布德利是找到剩下護符的唯一希望。和他談談為你安排的獎勵。$B$B我，這一次，終於可以安息了。祝你好運；你需要這份好運的！', '帶著勇氣戰靴，勇氣腿鎧和勇氣肩甲回到奧格瑪的莫克瓦那裡。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
