INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9023, 'zhTW', '完美的毒藥', '我哥哥和我在拉文霍德莊園外進行毒藥的製作。$B$B拉文霍德領主要我做出一種又新又強的毒藥混合物，從祖爾格拉布和安其拉廢墟的生物身上取下毒囊製作。$B$B$c，有兩種特別的劇毒野獸居住在那些受詛咒的廢墟，它們身上的毒素就是我們要找的。幫我從野獸庫林納克斯和溫諾希斯身上取下毒囊，我們會永遠感激你的。', '塞納里奧城堡的德爾克·雷木要你去幫他取回溫諾希斯的毒囊和庫林納克斯的毒囊。', '', '去希利蘇斯找塞納里奧要塞的德爾克·雷木。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9024, 'zhTW', '艾里斯坦的直覺', '我知道了！你有沒有聞過新的香水味？新上市的古龍水和香水？我們的守衛不會輕易怠慢職責的。$B$B除非他們的思想已經被一些邪惡的煉金術給混亂了。$B$B只有一個方法可以確定 - 帶一瓶古龍水和香水給摩根·匹斯特，告訴他我的懷疑。你回來後我會補償你花錢購買香水的。', '帶1個古龍水瓶和1個香水瓶給暴風城貿易區的摩根·匹斯特。', '', '去找暴風城的摩根·匹斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9025 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9025, 'zhTW', '摩根的發現', '嗯，我會的。看來艾里斯坦一定對某些東西很熟悉。我發現了愛情藥水和狡猾的失心藥膏本質遺跡。$B$B裡面有些成分香水裡的確會有，但是我發現少數一些成分……聞起來很有意思。', '回到暴風城貿易區的銀行外面找艾里斯坦·莫塔。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9026, 'zhTW', '追溯來源', '我們一定要找到來源。我看過比平常更多的人 - 包括守衛 - 在鑲金玫瑰進進出出。和奧里森談談。如果她有賣，她就能告訴你是從哪買來的。', '到暴風城貿易區和鑲金玫瑰旅店老闆奧里森談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9027 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9027, 'zhTW', '追溯來源', '古龍水發生什麼事了嗎？有可能。我從沒見過有這麼多人都爭相搶購一項商品。聽著，如果它有什麼問題，我也想知道。我跟一個叫艾佛特·索里山姆的商人買了補給品。他是鎮上新來的。他提到有一些物品要送到「最好的線團」那家店。', '到暴風城運河邊和「最好的線團」那家店的艾佛特·索里山姆談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9028, 'zhTW', '揭露來源', '什麼？叛國罪？不，不，我向你保證，我完全沒有惡意。難道我想幫助那些人減輕痛苦的求愛儀式也有錯嗎？拜託，那不是犯罪。為了證明我沒有惡意，我甚至可以告訴你我的貨源是誰。是一個叫史塔弗隆·雷倫的人運給我的，他是個藥劑師。我從沒跟他講過話。我們的哥布林經紀人說他在希爾斯布萊德丘陵越過神秘的拉文霍德莊園工作。希望你有那個運氣能找到他。', '找到在希爾斯布萊德丘陵，拉文霍德莊園後方的藥劑師史塔弗隆·雷倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9029 AND `locale` = 'zhTW';
