DELETE FROM `quest_template_locale` WHERE `ID` = 9030 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9030, 'zhTW', '安希恩的離別感言', '瓦薩拉克的靈魂被存在這個護符裡。因為我們的貪婪，愚蠢地把護符分成三塊，不知道有可怕的詛咒在等著我們。$B$B阻止瓦薩拉克的魔法的唯一方法就是將勳章重新組合回去。回到德莉娜那裡，告訴她布德利是找到剩下護符的唯一希望。$B$B我，這一次，終於可以安息了。祝你好運，你需要這份好運的!', '與鐵爐堡的德莉娜談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9031 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9031, 'zhTW', '告別安泰恩', '瓦塔拉克的靈魂就封印在這枚護符裡。因為貪婪，我們愚蠢地將它分成了好幾部分，絲毫不瞭解這會為我們帶來怎樣殘酷的詛咒。$B$B唯一解除瓦塔拉克的法術的辦法，就是將這枚勳章重新組合在一起。回到德莉娜那裡去，告訴她說，伯德雷已經是她找齊剩餘部分的最後希望了。$B$B我只希望能從此安息。祝你好運……你會非常需要運氣的！', '與奧格瑪的莫克瓦爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9032 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9032, 'zhTW', '布德利不幸之命運', '這枚徽章裡有瓦薩拉克的靈魂嗎？被這強大的詛咒所守護其實也沒什麼好驚訝的。$B$B布德利的所在位置顯現出一些問題。上次我聽到的是他準備重返黑石塔的消息，然後就再也沒音訊了。$B$B到黑石山去找他，不過我很擔心他可能早已身亡。所以我建議你隨身攜帶哥布林的裝置，朋友。', '到黑石山並使用超空間靈體顯像機，去黑石塔附近尋找布德利。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9033 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9033, 'zhTW', '戰爭的回響', '離最後一場仗也有五年了……$B$B失去了數以萬計的戰友為的是什麼?威脅永遠也沒有被完全消滅。$B$B而且巫妖王再次興風作浪……他的應聲蟲，科爾蘇加德，又對我們的土地計畫了另一次攻擊。$B$B我們不能再容許了!證明你的奉獻。證明你願意冒著生命和截肢的危險去阻止這場風暴，銀色黎明和血色十字軍的聯合力量會隨侍在後聽你差遣。$B$B進入納克薩瑪斯並殺死裡面的天譴軍團……', '東瘟疫之地聖光之願禮拜堂的指揮官艾利格·攜晨者要你去殺死5名活巨怪，5名石膚石像鬼，8名死亡騎士隊長與3隻毒液捕獵者。', '', '去找東瘟疫之地的指揮官埃裡戈爾·黎明使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9034 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9034, 'zhTW', '無畏胸甲', '在你與納克薩瑪斯裡的天譴軍團戰鬥時，你會發現被褻瀆的城垛和受戰爭破壞的鎧甲碎塊，把它們帶來給我，我就會為你製作一件英雄穿的護甲。', '東瘟疫之地聖光之願禮拜堂的柯菲斯將為你製作無畏胸甲，只要你將下列物品帶給他:1件被褻瀆的胸甲，25個受戰爭破壞的鎧甲碎塊，4個奧金錠和2個聯結水晶。', '', '去找東瘟疫之地的科爾法克斯，聖光之勇士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9035 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9035, 'zhTW', '路邊的伏擊', '嘿，就是你!你一定要幫我，拜託!我的同伴學徒和我遭到鄙惡者的攻擊!由於他們對魔法瘋狂的渴望，拿走了所有可以得手的東西:法力水晶，魔杖，魔法書……所有的東西!美勒杜跑去追他們了，我得留在這裡看守他們沒拿走的東西。沿著路往下走，看看你能不能幫他一把。', '沿著銀月城的路往南走，和永歌森林的學徒美勒杜談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9036 AND `locale` = 'zhTW';
