INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9049, 'zhTW', '救贖束腰', '你會在納克薩瑪斯主人屍體身上找到我們死去英雄的遺物。把那些被褻瀆的紀念品和受戰爭破壞的鎧甲碎塊帶來給我，還有能讓被詛咒的護甲恢復生氣的製作材料，我就會為你製作一件傑出的護甲。', '東瘟疫之地聖光之願禮拜堂的指揮官艾利格·攜晨者將為你製作救贖束腰，只要你將下列物品帶給他:1條被褻瀆的束腰，8個受戰爭破壞的鎧甲碎塊，1個奧金錠和3個聯結水晶。', '', '去找東瘟疫之地的指揮官埃裡戈爾·黎明使者。', '', '', '', '', 0);
