INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9050, 'zhTW', '救贖腕甲', '你會在納克薩瑪斯主人屍體身上找到我們死去英雄的遺物。把那些被褻瀆的紀念品和受戰爭破壞的鎧甲碎塊帶來給我，還有能讓被詛咒的護甲恢復生氣的製作材料，我就會為你製作一件傑出的護甲。', '東瘟疫之地聖光之願禮拜堂的指揮官艾利格·攜晨者將為你製作救贖腕甲，只要你將下列物品帶給他:1對被褻瀆的束腕，6個受戰爭破壞的鎧甲碎塊，1個奧金錠和2塊熟化毛皮。', '', '去找東瘟疫之地的指揮官埃裡戈爾·黎明使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9051 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9051, 'zhTW', '毒性測試', '這些你幫我製造的毒素有著特殊的用途。環形山裡的魔暴龍使得那裡的狩獵和生存環境對我來說都變得十分惡劣。即使我足夠強壯，殺死一隻魔暴龍也只會讓另一隻遊蕩入那塊帶領地而已。$B$B帶上這根毒針並將其刺入一隻活著的魔暴龍體內。毒素會使它很快就安靜下來，不過……我不知道很快有多快……', '將魔暴龍之刺扎入一隻魔暴龍的體內。', '把毒刺扎入魔暴龍體內', '去安戈洛環形山找沼澤地的托爾瓦·尋路者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9052 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9052, 'zhTW', '血瓣花之毒', '我想要請你幫忙調製一種毒素，以平定鎮靜環形山盆地中的大怪物。這不會致命的，只有$c銳利的雙眼能收集這份材料。$B$B你可以在環形山盆地週遭看到血帽蘑菇，它們就生長在血瓣花苗裡頭。另外，在巨痕谷中有飛行的巨型黃蜂可收集格里什毒刺，地點就在環形山盆地的南方。', '收集8個血帽和8個格里什毒刺，交給安戈洛環形山的托爾瓦·尋路者。', '', '去安戈洛環形山找沼澤地的托爾瓦·尋路者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9053 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9053, 'zhTW', '更好的材料', '這正是我害怕的 - 這毒素的效果仍無法對付這大怪物。$B$B如果我們想要製造強力毒性的劑量，你必須到阿塔哈卡神廟底下，揭發神廟的秘密，然後取回守衛腐爛的藤蔓。神廟非常危險，理所當然要帶個朋友一同前往。$B$B任務完成後記得回來找我。', '前往沉沒的神廟底部，從守衛那取回腐爛的藤蔓並交給托爾瓦·尋路者。', '', '去安戈洛環形山找沼澤地的托爾瓦·尋路者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9054 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9054, 'zhTW', '地穴行者外套', '我發現地穴惡魔的甲殼有一種功用。我可以發明一種極輕巧又致命的護甲套裝，只要組合一些納克薩瑪斯裡被褻瀆的魔法護甲碎片。$B$B幫我把需要的物品帶來，我就會為你製作一套世界前所未有的護甲!', '東瘟疫之地聖光之願禮拜堂的獵人里歐波將為你製作地穴行者外套，只要你將下列物品帶給他:1件被褻瀆的外套，25個受戰爭破壞的鍊甲碎塊，4個奧金錠和3塊熟化毛皮。', '', '去東瘟疫之地找聖光之願禮拜堂的獵手雷奧普德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9055 AND `locale` = 'zhTW';
