INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9061, 'zhTW', '地穴行者腕甲', '我發現地穴惡魔的甲殼有一種功用。我可以發明一種極輕巧又致命的護甲套裝，只要組合一些納克薩瑪斯裡被褻瀆的魔法護甲碎片。$B$B幫我把需要的物品帶來，我就會為你製作一套世界前所未有的護甲!', '東瘟疫之地聖光之願禮拜堂的獵人里歐波將為你製作地穴行者腕甲，只要你將下列物品帶給他:1對被褻瀆的束腕，6個受戰爭破壞的鍊甲碎塊，1個奧金錠和2塊熟化毛皮。', '', '去東瘟疫之地找聖光之願禮拜堂的獵手雷奧普德。', '', '', '', '', 0);
