INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9062, 'zhTW', '浸溼的書頁', '那些可惡的鄙惡者有人撐腰當然比較囂張。但我們先不要擔心那個。我要先找到我講師的元素魔典。$B$B我非常確定我看到他們其中一個懦夫把它扔進河裡，但我也無法指出正確的位置。如果你找到它的話我會給你一點獎勵的。', '永歌森林的學徒美勒杜要你去附近的橋邊搜尋水裡，把安西歐的元素魔典帶給他。', '', '去找永歌森林的學徒美勒杜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9063 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9063, 'zhTW', '托爾瓦·尋路者', '獵人托爾瓦·尋路者已向德魯伊尋求幫忙。他說只有我們能幫他，因為我們具備足夠的技能和對大自然的尊敬。$B$B有一條連接安戈洛環形山和塔納利斯沙漠的路。由那條路進入環形山盆地，你很快就能找到托爾瓦了。', '與安戈洛環形山的托爾瓦·尋路者談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9064, 'zhTW', '說謊', '安西歐如果知道他的書被毀了一定會大發雷霆。我有一個小建議;別擔心，我會讓你很值得的。$B$B把這本書帶給他，不要告訴他這件意外。如果他問起，就跟他說你不小心把書掉進池塘了。他沒有管你的權利，所以他也不能把你怎樣。$B$B安西歐都在靜語池講課，就在銀月城的東南方。你會為了我們這麼做吧?我會好好獎勵你的!', '把安西歐的元素魔典帶到永歌森林的靜語池給講師安西歐。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9065, 'zhTW', '派迪麥克斯任務', '嘿你，踢倒那座塔！', '確定你摧毀了那座塔！', '', '去找Kanrethad。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9066, 'zhTW', '即時的懲罰', '我希望你今天學了有價值的一課，$N。永遠別相信別人會為你說謊。$B$B現在我要你回到我那兩個愚蠢的學生那裡，用這個魔杖教訓他們。我的魔法告訴我只要沿著這條路往西，你就會在死亡之痕的另一邊找到他們了。$B$B完成後再回到我這裡。我會給你一點小獎勵。', '在安西歐的兩個學生身上使用安西歐的懲戒魔棒:學徒瑞倫和學徒美勒杜。再帶著魔棒回到永歌森林的靜語池找安西歐。', '', '去找永歌森林的導師安西歐。', '學徒美勒杜受到了懲罰', '學徒瑞倫受到了懲罰', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9067 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9067, 'zhTW', '夜夜狂歡', '我喜歡辦派對……只是稍微慶祝一下奎爾薩拉斯的壯麗!$B$B不過我現在缺少人力……我需要你去收集更多的派對物資。$B$B去銀月城的植物大師·日觸那裡幫我帶回來一瓶陽光下的特殊美酒，到遠行者居所和莎嵐尼·初光拿一些美味的泉爪開胃菜。然後你可以在晴風村的海利斯·晨行者那裡拿回我的煙火。$B$B動作快一點!', '取得陽光下的特殊美酒，泉爪開胃菜和一卷煙火，再回到永歌森林的薩瑟里的避風港交給薩瑟里領主。', '', '去找永歌森林的薩瑟里領主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9068 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9068, 'zhTW', '粉碎大地外套', '你可以將為了防守這片土地而倒下的勇士護甲帶來給我嗎?$B$B護甲已被褻瀆，無疑是正被惡魔使用;不過，只要有被戰爭破壞的護甲碎塊，被褻瀆的護甲就可以復原並再次被批上戰場。$B$B將死者的遺物和淨化材料帶來給我，粉碎大地護甲就會是你的。$B$B尋找納克薩瑪斯。', '東瘟疫之地聖光之願禮拜堂的林布拉特·大地粉碎者將為你製作粉碎大地外套，只要你將下列物品帶給他:1件被褻瀆的外套，25個受戰爭破壞的鍊甲碎塊，4個奧金錠和3塊熟化毛皮。', '', '去東瘟疫之地找聖光之願禮拜堂的雷布拉特·碎地者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9069 AND `locale` = 'zhTW';
