INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9076, 'zhTW', '鄙惡者頭目', '鄙惡者在狼吞虎嚥邪惡魔法的時候非常懈怠，他們根本不知道我們已取回我們的軍備。但是我們也不能總是期望他們保持懈怠。現在就是採取果斷攻擊的時候。讓我們先以他們的首領阿德倫為先例。有人看見他在船廠旁那棟建築物的頂樓。幫我把他的頭帶來，我會好好地獎勵你。', '把阿德倫的頭顱帶給永歌森林日帆船廠附近的微蘭德絲·白晨。', '', '去找永歌森林的微蘭德絲·白晨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9077 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9077, 'zhTW', '骨鐮胸甲', '如果你想要骨鐮護甲，你就要提供材料。$B$B進入納克薩瑪斯，在空中的巨大漂浮死城，找到被褻瀆的護甲和受戰爭破壞的護甲碎塊。把它們和其他材料帶回來給我讓我重組，你就會得到你的骨鐮護甲。喔，而且你還要付我錢因為你麻煩我……我會提供骨頭。', '東瘟疫之地聖光之願禮拜堂的『刺客』羅漢將為你製作骨鐮胸甲，只要你將下列物品帶給他:1件被褻瀆的胸甲，25個受戰爭破壞的皮甲碎塊，2個奧金錠和6塊熟化毛皮。', '', '去東瘟疫之地找聖光之願禮拜堂的殺手洛汗。', '', '', '', '', 0);
