INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9085, 'zhTW', '死亡暗影', '等你瓦解了遭到攻擊區域的天譴軍團召喚法陣，你就能挑戰保護它們的侍僧。$B$B說實在的，他們不是人。他們是暗影，是巫妖王最可怕的生物之一。使用他們身上的墓地符文可以讓他們顯現出來並用魔法或武器將他們摧毀。', '前往召喚法陣殺死一個末日之影，再回到東瘟疫之地的聖光之願禮拜堂找指揮官湯瑪士·海勒瑞。', '', '去東瘟疫之地找聖光之願禮拜堂的指揮官托馬斯·海勒拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9086 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9086, 'zhTW', '夢行者外套', '許多英雄在最後一場戰役倒下，至今也有許多人在對抗天譴軍團時陸續陣亡。那些屍體身上的護甲都被納克薩瑪斯剝去做未知的用途。$B$B取回被褻瀆的護甲和受戰爭破壞的護甲碎塊，再給我其他需要的材料，我就會製作夢行者護甲。', '東瘟疫之地聖光之願禮拜堂的瑞恩將為你製作夢行者外套，只要你將下列物品帶給他:1件被褻瀆的外套，25個受戰爭破壞的皮甲碎塊，6塊熟化毛皮和2個聯結水晶。', '', '去東瘟疫之地找聖光之願禮拜堂的萊茵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9087 AND `locale` = 'zhTW';
