INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9095, 'zhTW', '霜火長袍', '身為一個看守者，我可以容易地接觸許多麥迪文的個人財產。在那些物品之中，我發現秘典是最有意思的。大部分的書都充滿了 - 坦白地說 - 廢話，但也有一些書是珍寶。其中一本秘典記載著一套大法師裝備的製作方法:霜火。$B$B<安琪拉指向她的頭。>$B$B全都在這裡而且我很願意與你分享知識的果實，只要你能提供我必要的材料。', '東瘟疫之地聖光之願禮拜堂的大法師安琪拉·多桑杜將為你製作霜火長袍，只要你將下列物品帶給他:1件被褻瀆的長袍 ，25個受戰爭破壞的布甲碎塊，4塊月布和2個聯結水晶。', '', '去東瘟疫之地找聖光之願禮拜堂的大法師安吉拉·杜薩圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9096 AND `locale` = 'zhTW';
