INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9102, 'zhTW', '霜火束腕', '身為一個看守者，我可以容易地接觸許多麥迪文的個人財產。在那些物品之中，我發現秘典是最有意思的。大部分的書都充滿了 - 坦白地說 - 廢話，但也有一些書是珍寶。其中一本秘典記載著一套大法師裝備的製作方法:霜火。$B$B<安琪拉指向她的頭。>$B$B全都在這裡而且我很願意與你分享知識的果實，只要你能提供我必要的材料。', '東瘟疫之地聖光之願禮拜堂的大法師安琪拉·多桑杜將為你製作霜火束腕，只要你將下列物品帶給他:1對被褻瀆的束腕，6個受戰爭破壞的布甲碎塊，1個秘法水晶和1個聯結水晶。', '', '去東瘟疫之地找聖光之願禮拜堂的大法師安吉拉·杜薩圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9103 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9103, 'zhTW', '瘟疫之心長袍', '我不會裝模作樣，蛆蟲。瘟疫之心物品所擁有的黑暗可以把我們兩個都摧毀。這就是為什麼價格如此高昂的原因。如果我就要死了，也會是個富翁。$B$B你死了我也不會對你吐一口豺狼人的口水，照我的話做就對了。把我要的東西帶來，我們就能雙方受惠 - 或是死亡;但我已經解釋過了…….', '東瘟疫之地聖光之願禮拜堂的『施怒者』麥特斯將為你製作瘟疫之心長袍，只要你將下列物品帶給他:1件被褻瀆的長袍，25個受戰爭破壞的布甲碎塊，4塊月布和2個聯結水晶。', '', '去東瘟疫之地找聖光之願禮拜堂的憤怒者瑪塔烏斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9104 AND `locale` = 'zhTW';
