INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9111, 'zhTW', '信仰長袍', '<蒙托神父在你面前在空中做了一些奇怪的動作。>$B$B祝福你<男孩/女孩>，你找到亡者的裝備了嗎?那些在戰場上嚥下最後一口氣的可憐靈魂 - 一切都被奪去包括他們的尊嚴。$B$B幫我把死者被褻瀆的遺物和淨化試劑帶來，你就會了解信念了。', '東瘟疫之地聖光之願禮拜堂的神父伊尼哥·蒙托將為你製作信仰長袍，只要你幫他把下列的東西帶去:1件被褻瀆的長袍，25個受戰爭破壞的布甲碎塊，4塊月布和2個聯結水晶。', '', '去東瘟疫之地找聖光之願禮拜堂的英尼戈·蒙托爾神父。', '', '', '', '', 0);
