INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9189, 'zhTW', '送貨到瑟伯切爾', '你已經傷了這位小姐的心，雖然它早已不再跳動了。$B$B既然這樣，我有一封信要送到銀松森林的瑟伯切爾。諫言者索利安是我們在被遺忘者那邊的代表。$B$B最近的路線，除非你要坐他們的蝙蝠去，不然你就是從幽暗城的門口順著往南方的路走。跟著路標走。要到達目的地應該不困難。儘管放開你的心胸吧;瑟伯切爾可是一個殘破不堪的地窖呢。$B$B這些被遺忘者還真是奇怪的生物呢。', '將密封的辛多雷命令送到銀松森林的瑟伯切爾給諫言者索利安。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9190 AND `locale` = 'zhTW';
