INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9199, 'zhTW', '食人妖護符', '$c，埋在阿曼尼地下墓穴的食人妖屍體已經死而復生了!我要你前往那裡把他們死亡的證據帶來給我。其中有些食人妖身上會攜帶護符;那是個具有未知力量源的灼熱物品。我們不確定它們是否與食人妖復活有關...那就要靠博學者來了解了。$B$B地下墓穴在日傷山峰裡面，就在東邊。我聽說最容易進入的地方就在山的北面。', '收集8個食人妖護符交給亡靈守衛瑪塔堤斯，他在鬼魂之地的安寧地。', '', '去找幽魂之地的亡靈哨兵瑪塔堤斯。', '', '', '', '', 0);
