DELETE FROM `quest_template_locale` WHERE `ID` = 9218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9218, 'zhTW', '脊骨之塵', '復活的骷髏體內流著的黑暗力量主要會累積在他們的脊椎裡。我發現了一個方法可以將這股能量注入藥水裡，增強我們的魔法能力對抗不死族。$B$B幫我帶來一些脊骨之塵我就會樂意提供你一個樣本。你會在西邊的死亡之痕找到一堆遊走的骷髏。', '把10份脊骨之塵交給安寧地的博學者艾米諾。', '', '去找幽魂之地的博學者艾米諾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9219 AND `locale` = 'zhTW';
