INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9220, 'zhTW', '死亡之域戰爭', '如果你想要幫忙的話，此時此地就是最佳良機。$B$B重建太陽聖所，我們早已在敵方權力中心:死亡之域，高舉反抗的消息。$B$B去與這群居住在這個邪惡天譴軍堡壘的不死生物們對戰。', '在死亡之域殺掉5名死亡之域通靈師，6名奈幽碧斯百夫長和6名哀嚎者，並回到鬼魂之地向太陽聖所的博學者艾度尼斯回報。', '', '去找幽魂之地的博學者艾度尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9221, 'zhTW', '精良級軍備之戰-銀色黎明聲望友善', '你好，朋友。你想要用點黎明徽記或是十字軍徽記來換取一些強大的物品嗎?$B$B不過我必須要警告你，雖然你是銀色黎明所友好的朋友，但是想要購買這些物品可是還須付出一筆龐大的額外費用，我建議你去提升更高的聲望後再來考慮這些物品吧。', '付出30個黎明徽記和30個十字軍徽記就能換取銀色黎明藏寶庫裡的一樣強大的物品。', '', '去東瘟疫之地找聖光之願禮拜堂的軍需官米蘭達·布利洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9222, 'zhTW', '史詩級軍備之戰-銀色黎明聲望友善', '你好，朋友。你想要用點黎明徽記或是十字軍徽記來換取一些史詩級的物品嗎?$B$B不過我必須要警告你，雖然你是銀色黎明所友好的朋友，但是想要購買這些物品可是還須付出一筆非常龐大的額外費用，我建議你去提升更高的聲望後再來考慮這些物品吧。', '付出110個黎明徽記和110個十字軍徽記就能換取銀色黎明藏寶庫裡的一樣史詩級的物品。', '', '去東瘟疫之地找聖光之願禮拜堂的軍需官米蘭達·布利洛克。', '', '', '', '', 0);
