INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9225, 'zhTW', '史詩級軍備之戰-銀色黎明聲望崇敬', '你好，朋友。你想要用點黎明徽記或是十字軍徽記來換取一些史詩級的物品嗎?$B$B不過我必須要警告你，雖然你是的銀色黎明所崇敬的朋友，但是想要購買這些物品應該還不划算，我建議你在多提升一下聲望再來考慮這些物品吧。', '付出45個黎明徽記和45個十字軍徽記就能換取銀色黎明藏寶庫裡的一樣史詩級的物品。', '', '去東瘟疫之地找聖光之願禮拜堂的軍需官米蘭達·布利洛克。', '', '', '', '', 0);
