INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9228, 'zhTW', '史詩級軍備之戰-銀色黎明聲望崇拜', '你好，朋友。你想要用點黎明徽記或是十字軍徽記來換取一些史詩級的物品嗎?$B$B只要是銀色黎明所崇拜的朋友我一定會給予最高的折扣!看看吧，一定讓你物超所值!', '付出27個黎明徽記和27個十字軍徽記就能換取銀色黎明藏寶庫裡的一樣史詩級的物品。', '', '去東瘟疫之地找聖光之願禮拜堂的軍需官米蘭達·布利洛克。', '', '', '', '', 0);
