INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9229, 'zhTW', '羅馬拉丁尼的命運', '在銀色黎明成立以前，羅馬拉丁尼原本是兄弟會的戰士 - 大領主莫格萊尼的愛徒!可是當羅馬拉丁尼得知莫格萊尼的死訊之後，憤怒和仇恨開始慢慢的侵蝕他的心靈。$B$B你要記住，$n，當怒氣以及仇恨過大時，一個人就不再是人了。他會迷失自己的方向並失去行為控制的能力。羅馬拉丁尼就這樣帶著仇恨的精神進入納克薩瑪斯去復仇……從此音訊全無。$B$B進入納克薩瑪斯去找尋羅馬拉丁尼的消息。', '進入納克薩瑪斯並找尋羅馬拉丁尼的命運。', '', '去找東瘟疫之地的科爾法克斯，聖光之勇士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9230, 'zhTW', '羅馬拉丁尼的冰握', '想要修理這個戒指不是那麼容易的，$n。這個戒指是由類似納克薩瑪斯的天譴軍團架構的獨特印記，還有一些其他的材料所提煉而成的。只要能夠取得那獨特的冰凍符文我就能讓這枚戒指重現它原有的光芒。', '東瘟疫之地聖光之願禮拜堂的柯菲斯需要你帶給他1個冰凍符文，1顆藍寶石，還有1個奧金錠。', '', '去找東瘟疫之地的科爾法克斯，聖光之勇士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9231 AND `locale` = 'zhTW';
