DELETE FROM `quest_template_locale` WHERE `ID` = 9232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9232, 'zhTW', '竭盡所能……', '你真的想要成為銀色黎明的英雄?你可不要小看科爾蘇加德的爪牙，我可是見過他們無情的踐踏偉大的銀色黎明士兵的屍體!像你這種不了解狀況的人在納克薩瑪斯裡又要如何生存呢?$B$B<維爾海姆深深的嘆了一口氣。>$B$B但是現在這種狀況，我也只能將我的希望寄託在你身上和盡我所能的來幫助你。$B$B工匠大師歐瑪利安之前留下了一些便褲的配方，只要你能提供所需的材料我就能夠幫你做件適合的便褲。', '東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他2個冰凍符文，2個水之精華 ，2顆藍寶石，還有30金。', '', '去東瘟疫之地找聖光之願禮拜堂的工匠威爾海姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9233, 'zhTW', '歐瑪利安之手冊', '維爾海姆，$B$B如果你正在閱讀本冊，我應該早就死了。希望你知道我臨死前還念念不忘你和你那個有欠磨練的生意頭腦。還真遺憾，這手冊持有人的工匠技術比你還差。$B$B關於此手冊:這是我所其餘的配方紀錄。盡量滿足持有人的製作需求。我知道你這個混蛋服務費索價不貲。$B$B鄙視，$B$B歐瑪利安', '把歐瑪利安之手冊交給工匠維爾海姆，他就在東瘟疫之地聖光之願禮拜堂。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9234 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9234, 'zhTW', '冰剋護手', '謝謝你與歐瑪利安，願他安息。我現在能製作冰剋護手了，你只需要替我找來製作材料，以及支付一些工匠費就可以了。', '東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他5個冰凍符文，12個瑟銀錠，2個奧金錠，2個水之精華，還有200金。', '', '去東瘟疫之地找聖光之願禮拜堂的工匠威爾海姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9235, 'zhTW', '冰剋護腕', '謝謝你與歐瑪利安，願他安息。我現在能製作冰剋護腕了，你只需要替我找來製作材料，以及支付一些工匠費就可以了。', '東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他4個冰凍符文，12個瑟銀錠，2個奧金錠，2個水之精華，還有200金。', '', '去東瘟疫之地找聖光之願禮拜堂的工匠威爾海姆。', '', '', '', '', 0);
