INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9236, 'zhTW', '冰剋胸甲', '謝謝你與歐瑪利安，願他安息。我現在能製作冰剋胸甲了，你只需要替我找來製作材料，以及支付一些工匠費就可以了。', '東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他8個冰凍符文，16個瑟銀錠，2個奧金錠，4個水之精華，還有300金。同時你必須在銀色黎明達到崇拜聲望值，才能完成這項任務。', '', '去東瘟疫之地找聖光之願禮拜堂的工匠威爾海姆。', '', '', '', '', 0);
