INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9246, 'zhTW', '冰鱗胸甲', '謝謝你與歐瑪利安，願他安息。我現在能製作冰鱗胸甲了，你只需要替我找來製作材料，以及支付一些工匠費就可以了。', '東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他8個冰凍符文，24個厚蠍鱗，7個水之精華 ，5塊熟化毛皮，還有300金。同時你必須在銀色黎明達到崇拜聲望值，才能完成這項任務。', '', '去東瘟疫之地找聖光之願禮拜堂的工匠威爾海姆。', '', '', '', '', 0);
