INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9247, 'zhTW', '保管者的徵召', '$n，$B$B長久以來你為了銀色黎明的利益服務，永遠表現你最有能力的一面。現在，我們又耳聞一項極需支援的號召。$B$B$n，若你願意協助的話，請向東瘟疫之地的聖光之願禮拜堂，跟名冊保管者報到。', '將名冊保管者的信交給在東瘟疫之地聖光之願禮拜堂的他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9248, 'zhTW', '謙卑的提議', '(達納蘇斯語)祝你好運，$r。如果你可以向我證明深淵議會的領主已死亡，我就獎勵你一件可以幫你對付其拉的物品。', '希利蘇斯塞納里奧城堡裡的奧莉爾·金葉要你帶給她1個深淵節杖。同時你必須在塞納里奧議會達到尊敬聲望值，才能完成這項任務。', '', '去希利蘇斯找塞納里奧要塞的奧蕾爾·金葉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9249, 'zhTW', '40張獎券 - 高階獎品', '', '', '', '去找吉瓦斯·格里加特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9250, 'zhTW', '阿泰絲之杖的骨架', '等阿泰絲之杖的骨架組好後，阿泰絲就幾近完美了。只有杖頭跟杖尾還找不到。還有一件法杖的小問題，就是它能接觸到薩格拉斯的邪惡力量。$B$B去找人幫你尋找遺失的部份，並且還要能驅除法杖裡的邪惡力量。', '找人一起幫你尋找法杖的最後2塊部位，並和你一同淨化杖中的魔鬼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9251 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9251, 'zhTW', '阿泰絲，被污損的守護者之杖', '你身上擁有一項具有強大邪惡力量的物品，或許連你也懷疑為什麼自已還能活著。不清楚這個問題的答案，$n。我只做我必須做的事而已。$B$B科爾蘇加德高踞在納克薩瑪斯的王座上，正在策劃著什麼……他手上有你要找的東西，也正在追尋你所擁有的物品。$B$B提到法杖的杖柄;一個叫做布萊恩·銅鬚的矮人帶著它進入了安其拉，但當他離開時卻把阿泰絲之杖杖柄留在裡面了。$B$B如果你可以把這些碎片找回來，請帶回來給我。', '在塔納利斯的時光之穴裡，安納克羅斯要阿泰絲之杖的杖頭跟阿泰絲之杖的杖柄。', '', '去塔納利斯找時光之穴的阿納克洛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9252, 'zhTW', '保衛晴風村', '我們已感覺到天譴軍團明顯提高攻擊行動，$N。我們快抵抗不住了，而且銀月城好像也沒有增援的跡象。協助我們削弱死亡之痕不死生物的數目，一起來保護這村莊。', '殺掉4個腐肢掠奪者、4個黑暗怨靈。然後回到遊俠塞瑞覆命，他在永歌森林的晴風村。', '', '去找永歌森林的遊俠塞瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9253, 'zhTW', '符文守護者德蘭', '天譴軍團有增無減的攻擊行動讓我相信，鬼魂之地邊界那裡的某個防禦符文石一定發生故障。我們用這些古老的石頭來保護我們不受不死族傷害。它們大部分都在太陽之井的攻擊後被摧毀或不見了。朝著鬼魂之地的方向沿著路往南走，往西邊看就會發現一條小徑。你會在附近的一個符文石看到符文守護者德蘭;他會知道發生了什麼問題。', '與永歌森林的符文守護者德蘭談話，他在鬼魂之地邊界附近。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9254, 'zhTW', '遊蕩者學徒', '感謝你的幫忙，$N。當我整頓好這裡的事情時，我想請你幫個忙。我之前的一個學徒捲入了危險的研究調查。她前往了東部聖所，就在死亡之痕中間。我擔心她的安危。你能不能幫我把她找回來，並說服她找回自己。', '與東部聖所的學徒莫維達談話，位置在永歌森林。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9255, 'zhTW', '研究報告', '雖然我的研究結果令人沮喪，這份資料還是有可取之處。我要在這份報告被正視之前，先讓博學者檢視一下我的成果。拜託你，把這些報告拿給西邊晴風村的博學者蘭德拉·晨行者。', '把研究報告帶到永歌森林交給晴風村的博學者蘭德拉·晨行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9256, 'zhTW', '晴風村', '我有另一個任務要給你，$N。遊俠迪哥里恩被派去晴風村找尋更多有關鄙惡者攻擊附近船廠的線索。他正尋求增援，可是我們還不能幫忙。去找到他，然後盡你全力去幫助他吧。沿著內精靈之門這條路一直往南走就能找到晴風村了。祝你好運，$N。', '到永歌森林與晴風村的遊俠迪哥里恩談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9257, 'zhTW', '阿泰絲,守護者之杖', '最後一個任務會是最困難的，$n。你要去迎頭攻擊巫妖王的將軍跟上古之神，但是，你現在要面對的是薩格拉斯之手。$B$B帶著這個法杖到斯坦索姆。你會看到聖化之地:而羅德隆最偉大的騎士就是在這裡被謀殺的。把這污損的法杖放在聖化之地上，準備巨大力量由內破壞……毀滅這個支配法杖的邪惡東西，然後回到我這。', '塔納利斯時光之穴的安納克羅斯要你帶著阿泰絲,守護者之杖前往斯坦索姆，在聖化之地上使用它。擊敗從法杖內被驅除的生物再回去找他。', '', '去塔納利斯找時光之穴的阿納克洛斯。', '淨化埃提耶什', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9258, 'zhTW', '烈焰邊境', '天譴軍團的污土持續進攻新的區域。為此，我們在鬼魂之地邊界建造了防護符石，以防止污染繼續蔓延。某次天譴軍團的攻擊行動中，他們摧毀了西邊的符石，迫使我們必須燒掉四周的土地來遏止污穢擴散。我的姐妹，拉瑞安娜·河風，看管著烈焰邊境。去找她，她可能有工作要給你。', '去烈焰邊境附近找拉瑞安娜·河風，位置就在永歌森林的西南方。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9259, 'zhTW', '血帆的叛徒', '', '', '', '去找荊棘谷的血帆叛徒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9260, 'zhTW', '調查暴風城的天譴軍團', '天譴軍團就在我們的門邊紮營；我能不能坐視不管！你一定會站出來保衛暴風城不受可惡的入侵者騷擾吧？$B $B外面有些奇怪的符文法陣，燃燒著和不死族周圍及大墓地上一樣的能量。它們有一定的重要性，我肯定，而且我要你去調查出來。削減那些異常物的數量；把它們死亡的證據和調查結果帶來給我，我就會獎勵你。去吧！', '從暴風城外的天譴軍團身上收集3個黯淡的墓地之石並調查它們營地附近發光的符文法陣。', '調查法陣', '去暴風城找英雄谷的奧林中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9261 AND `locale` = 'zhTW';
