INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9271, 'zhTW', '阿泰絲,守護者之杖', '這個最終的任務會是最艱難的一個，$n。你已經挑戰並擊敗了一名遠古之神和巫妖王的將軍，但現在你必須挑戰薩格拉斯之手。$B$B帶著這個法杖到斯坦索姆。你在那裡會找到一片聖化之地:羅德隆最強大的騎士都在那裡被殺害。將這個污損的法杖放在神聖的大地上，準備等著一股巨大的力量破繭而出……擊敗那個控制法杖的邪惡生物再回來找我。', '塔納利斯時光之穴的安納克羅斯要你帶著阿泰絲,守護者之杖前往斯坦索姆，在聖化之地上使用它。擊敗從法杖內被驅除的生物再回去找他。', '', '去塔納利斯找時光之穴的阿納克洛斯。', '淨化埃提耶什', '', '', '', 0);
