INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9274, 'zhTW', '溺死者的靈魂', '就我有印象以來北邊的湖就充斥著我祖先的靈魂，$N。那些可憐的鬼魂都是在一場悲慘的意外中溺死在湖底的受害者。$B$B事情的來龍去脈我已忘得差不多了，但是他們揮之不去的哭喊聲一直提醒著我他們的詛咒。$B$B如果你能勝任這個任務，我要你去湖那裡結束他們的苦難，$N。我和他們都會感謝你的……我保證。', '鬼魂之地，遠行者營地的遊俠克羅南，要你去附近的湖裡殺死8個復仇的亡魂和8個貪婪的亡魂。', '', '去找幽魂之地的遊俠克羅南。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9275, 'zhTW', '一點小佐料', '讓我先自我介紹。我是皇家藥劑師學會的藥劑師范衲斯特。我是來幫助遠行者解決他們的食人妖麻煩。我想我有辦法解決這個問題。$B$B我手上有一堆強而有力的毒藥。食人妖也是活的生物，他們也要吃。如果我們把他們的食物加入我的毒藥……那麼，我相信結果會非常有趣。$B$B你願意幫助我們擺脫南邊札布諾瓦的影松食人妖嗎?', '到札布諾瓦營地在食人妖的食物裡下毒，再回到鬼魂之地的遠行者營地，將剩下的藥劑師之毒交給藥劑師范衲斯特。', '', '去找幽魂之地的藥劑師范衲斯特。', '對鮮肉架下毒', '對燻肉架子下毒', '對鮮魚架子下毒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9276, 'zhTW', '攻擊札布泰拉', '我很高興你來這裡幫忙，$c。我們的資源已經減少許多，所以你的幫忙對我們而言是相當珍貴的。隊長已派我追查當地影松食人妖營地的騷擾事件。我們的策略就是讓他們失去平衡直到有天能一舉殲滅他們。$B$B到那時候，我們就需要所有能找到的志願者，這樣那些影松食人妖的數量才不會增加。$B$B你覺得你能前往東方的札布泰拉給他們點顏色瞧瞧嗎?', '殺死8名影松暗影施法者和8名影松獵頭者，再回到鬼魂之地找遠行者營地的遠行者索安娜。', '', '去找幽魂之地的遠行者索安娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9277 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9277, 'zhTW', '攻擊札布諾瓦', '是來點比較有挑戰性任務的時候了。南邊的札布諾瓦是較強大的影松食人妖的家。為了持續將食人妖的數量削減至最小，我要派你去那裡攻擊他們，不論你用什麼手段。$B$B你覺得這方法如何，$N?準備好對付更多的食人妖了嗎?', '殺死10名影松馭貓者和10名影松妖術師，再回到鬼魂之地找遠行者營地的遠行者索安娜。', '', '去找幽魂之地的遠行者索安娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9278, 'zhTW', '歡迎！', '歡迎來到魔獸世界!$B$B為了感謝您購買魔獸世界典藏版，請將這張禮券交給藍色守望的喬萊爾。您將得到一份特別的禮物:陪伴您踏上冒險旅途的小寵物!$B$B再次感謝您的支持，請盡情享受魔獸世界的樂趣吧!', '將藍色守望禮物兌獎券交給藍色守望的喬萊爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9279 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9279, 'zhTW', '你活下來了！', '別擔心我的傷，<兄弟/姊妹>。我們有人能活下來就是奇蹟!$B$B你看起來還沒恢復健康;你被拘禁了好幾個禮拜。$B$B發生了一些事，艾克索達便失事了。很多人都死了。$B$B但你還活著讓我鬆了一口氣，$n。有你帶領我們，我相信很快我們就能平安離開這個地方!波尼特斯要我叫你醒來後去找他。他在山丘腳下等你。沿著路往西南方走。', '和安曼谷失事地點的波尼特斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9280 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9280, 'zhTW', '補充治療水晶', '現在最緊要的就是我們消耗的治療水晶。我們必須盡快補充水晶!$B$B不幸的是，現在唯一的方法就是從當地的安曼谷飛蛾身上直接抽取血液。他們的血液是很合適的替代品。$B$B你可以在溪谷附近的區域找到他們，不過他們大多集中在西北方。', '從附近的安曼谷飛蛾身上取得8瓶飛蛾血清，再回到安曼谷失事地點的波尼特斯那裡。', '', '去埃門谷找墜毀點的普羅尼圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9281, 'zhTW', '清除道路', '博學者坎德立斯派我來這清除任何有敵意的野生生物。等這個區域安全了，博學者打算把這裡變成對抗天譴軍團的前哨。$B$B如果要我說當學生時學到的一件事就是負起責任 - 尤其是悠關性命的事!$B$B如果你有興趣，我要你去殺死西邊和南邊的巨型細網蜘蛛和鬼爪劫毀者，我會給你豐厚的報酬。', '鬼魂之地安狄里安莊園的學徒瓦瑞爾要你去殺10隻巨型細網蜘蛛和10個鬼爪劫毀者。', '', '去找幽魂之地的學徒瓦瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9282, 'zhTW', '遠行者營地', '博學者和遠行者永遠都不會有意見一致的時候，$N。不過，說到達克汗，我們全都同意一定要想出個辦法來擊敗他和他的軍團。東北邊的遠行者營地有個叫薇娜的遊俠，她對我們的敵人有了一些重要的發現。和她談談看是否你能幫得上忙。', '太陽聖所的博學者坎德立斯要你去鬼魂之地和遠行者營地的遊俠薇娜談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9283, 'zhTW', '德萊尼生還者', '治療水晶的庫存已重新補足，但那不是我們能幫助傷者的唯一方法。所有的德萊尼都能使用那魯的祝福來治療他人。你一定要使用這個能力來治療一個失事後的生還者。$B$B你可以在西邊和西北邊的區域找到大部份的生還者，但那場失事讓我們分佈散落在整個溪谷裡。$B$B生還者暴露在能量水晶的照射下，所以你應該可以順著環繞生還者散發的紅光而找到他們。$B$B你一定要救救他們，$n。', '對散落在安曼谷各處的其中一名德萊尼生還者使用那魯的祝福技能。之後再回到安曼谷失事地點找薩度恩。', '', '去埃門谷找墜毀點的扎爾杜。', '拯救德萊尼倖存者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9284 AND `locale` = 'zhTW';
