INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9292, 'zhTW', '破碎的墓地水晶', '在陷入憎恨的屍體身上，你發現破碎的水晶，以微弱的能量緩慢地跳動著。', '將破碎的墓地水晶帶給暴風城城門外的歐令中尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9293 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9293, 'zhTW', '必要手段……', '附近的湖已受到其中一塊船用能量水晶的污染。許多安曼谷的植物和動物也都因此產生突變。$B$B我有個方法可以治療湖泊，但我需要突變的鞭笞者樣本來做分析。他們就在西邊的安曼牧場裡。$B$B你能幫我嗎， $C ?', '收集10個鞭笞者樣本再回到安曼谷的失事地點找植物學家泰瑞茲。', '', '去找埃門谷墜毀點的植物學家塔蕾克絲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9294 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9294, 'zhTW', '拯救湖泊', '感謝老天爺，我想它產生作用了!我會給你一個藥劑讓你散播在南邊的銀線湖裡。它會中和掉散落在這附近的放射性船用能量水晶所產生的影響。$B$B游到那裡並散播我的中和劑。別擔心，你不會因為待太久而被幅射影響的。', '對放射性能量水晶散播中和劑。然後，再回到安曼谷的失事地點找植物學家泰瑞茲。', '', '去找埃門谷墜毀點的植物學家塔蕾克絲。', '施放中和劑', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9295, 'zhTW', '來自前線的信件', '你在殺掉的眾多天譴軍團爪牙其中一人身上找到這封信。從它的樣子和氣味判斷，它已經和不死族在一起一些日子了。或許聖光之願禮拜堂的某人會對它有興趣進而好好的研究它……', '將撕破的信件帶到東瘟疫之地的聖光之願禮拜堂交給名冊保管者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9296 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9296, 'zhTW', 'reuse', '這塊石頭散發著一股黑暗的力量。你應該把它交給某人。', '將黯淡的死靈之石交給某人。', '', '', '', '', '', '', 0);
