INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9300, 'zhTW', '前線的書頁', '你在殺掉的眾多天譴軍團爪牙其中一人身上找到這封信。從它的樣子和氣味判斷，它已經和不死族在一起一些日子了。或許聖光之願禮拜堂的某人會對它有興趣進而好好的研究它……', '將破爛的書頁帶到東瘟疫之地的聖光之願禮拜堂交給名冊保管者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9301, 'zhTW', '前線的信封', '你在殺掉的眾多天譴軍團爪牙其中一人身上找到這封信。從它的樣子和氣味判斷，它已經和不死族在一起一些日子了。或許聖光之願禮拜堂的某人會對它有興趣進而好好的研究它……', '將染血的信封帶到東瘟疫之地的聖光之願禮拜堂交給名冊保管者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9302, 'zhTW', '前線的公文', '你在殺掉的眾多天譴軍團爪牙其中一人身上找到這封信。從它的樣子和氣味判斷，它已經和不死族在一起一些日子了。或許聖光之願禮拜堂的某人會對它有興趣進而好好的研究它……', '將弄皺的公文帶到東瘟疫之地的聖光之願禮拜堂交給名冊保管者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9303, 'zhTW', '注射疫苗', '薩那需要我們的幫忙來搶救艾克索達的部份區域。泰瑞茲準備了一份疫苗可以用在奈斯特灌木林梟獸身上，大部分需要搶救的地區都有他們的蹤跡。$B$B只要靠近未注射的梟獸再使用水晶就可以了。不幸的是，你必須殺了其他的生物。你可以在東南邊的奈斯特灌木林和奈斯特山丘找到他們。', '在6個奈斯特灌木林梟獸身上使用注射用水晶。再回到安曼谷的失事地點找復仇者艾德。', '', '去埃門谷找墜毀點的守備官奧達爾。', '奈斯特灌木林梟獸已注射疫苗', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9304, 'zhTW', '前線的文件', '你在殺掉的眾多天譴軍團爪牙其中一人身上找到這封信。從它的樣子和氣味判斷，它已經和不死族在一起一些日子了。或許聖光之願禮拜堂的某人會對它有興趣進而好好的研究它……', '將弄髒的文件帶到東瘟疫之地的聖光禮拜堂交給名冊保管者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9305 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9305, 'zhTW', '備用零件', '我們已設法找到在失事中損壞的全像攝影發射器。如果我們能修好它，那麼我們就有機會找到安曼谷外的其他生還者。$B$B我們知道鄰近區域有些船上的儀器可以拿來做為備用零件，不過當地的梟獸早已搶先我們一步偷走它們。$B$B $N ，我們要你前往南邊的奈斯特灌木林和山丘，找到那些備用零件!', '收集4個發射器的備用零件。然後再回到安曼谷的失事地點找技師·薩那。', '', '去埃門谷找墜毀點的技師沙娜安。', '', '', '', '', 18019);
DELETE FROM `quest_template_locale` WHERE `ID` = 9306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9306, 'zhTW', '和復仇者艾德談談', '$N，復仇者艾德在找人處理奈斯特灌木林的突變梟獸問題。我們一定要處理這個因為意外降落此處所帶來之負面影響。$B$B你會在失事地點的南邊找到他。拜託，儘快去和他談談。', '和埃門谷失事地點的復仇者艾德談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9307, 'zhTW', '憐憫之心', '附近的銀線湖因為掉入了一片船的殘骸而受到汙染。這對附近許多生物都造成突變，有些變的極有敵意。情況最糟糕的是突變的梟獸。$B$B我要你往南邊進入奈斯特灌木林，儘可能制服那些可憐的怪物。這是安樂死呀，$C。請儘量快刀斬亂麻減少它們的痛苦。', '殺死14個突變的梟獸，再回到埃門谷的失事地點找復仇者艾德。', '', '去藍謎島找元素聖谷的守備官奧達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9308 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9308, 'zhTW', '血精靈遺體？', '你認為躺在地上的殘骸是屬於一個辛多雷 -- 血精靈 -- 的屍體。看他的樣子是在灌木叢裡遭到幾個野蠻的突變梟獸攻擊了。$B$B搜尋屍體，你發現他脖子上戴了一條護符。或許復仇者艾德會對這個有點興趣？', '將血精靈護符帶到埃門谷交給失事地點的復仇者艾德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9309 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9309, 'zhTW', '調查暗影山脊', '我們手上有幾個不同來源的證據指出暗影山脊有不尋常的活動正在進行中。這很麻煩;我們以為先前進行的偵察任務已經做得很徹底了。有一個斥候尚未跟我回報。$C，我要你前往西南方到銀線湖的另一邊，找到托蘭，看他為什麼被耽擱了。', '到安曼谷的暗影山脊找到托蘭並和他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9310 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9310, 'zhTW', '黯淡的墓地水晶', '在死去的人類屍體身上，你找到了一個散發著微弱能量的水晶。', '將黯淡的墓地水晶帶給幽暗城庭院的盧卡中尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9311 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9311, 'zhTW', '血精靈間諜', '我有一個計劃。我們一定要殺了他們的領導者。他們沒有了主人，或許會撤退重建勢力。我們只要爭取時間直到修復完成。$B$B然後復仇者艾德一定會知道這件事。殺了勘測員，再回去告訴他我們發現了什麼。', '殺死勘測員坎翠斯，然後把這裡發生的事告訴安曼谷失事地點的復仇者艾德。', '', '去埃門谷找墜毀點的守備官奧達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9312 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9312, 'zhTW', '發射器', '$N，你去外面調查暗影山脊時，薩那已經在這裡展開關於全像攝影發射器的研究。你應該會想和她談談。', '和安曼谷失事地點的技師·薩那談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9313, 'zhTW', '前往藍色守望', '謝天謝地，$N，你一定要立刻到藍色守望和戴伏恩談談!有一條路通往這小島的西邊。沿著它走並穿過水晶河川到達島的較大區域。再沿著路走你就會來到藍色守望。看看你能否說服他們給我們一些補給和援助。我們會盡量跟上你。謝謝你，沒有你我們辦不到這些的!', '到藍謎島和藍色守望的技師戴伏恩談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9314 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9314, 'zhTW', '藍色守望的字條', '$C!有一群突變的野獸撲向我，害我的腿受了傷。我們收到薩那的命令後就從藍色守望出發派去進行偵察任務。拜託你，代替我去和照顧者查倫談談好嗎?她需要知道會有多少人前去藍色守望。越過水晶河川再沿著路走，你就可以到達藍色守望。記得請她給你一個地方休息。', '去藍謎島和藍色守望的照顧者查倫談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9315, 'zhTW', '安羅科舒頓', '靠近一點，我快……死了。$B$B我被派來這裡……殺這些奈幽蟲族，但是范德隆不……知道他們有個領導者。$B$B<垂死的血精靈咳出了大量的鮮血。>$B$B你一定要找到……並殺死安羅科舒頓。找人幫忙。她在日冠村……附近遊蕩。', '殺死安羅科舒頓再回到鬼魂之地的安寧地找秘法師范德隆。', '', '去找幽魂之地的秘法師范德隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9316 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9316, 'zhTW', '[TXT]哥布林掠奪者', '<布理安娜用搜尋的目光看了你一眼。>$B$B$B$B那麼，你想殺一些哥布林，是嗎？嗯，如果你下定決心，可以從附近的掠奪者開始。幫我帶來他們的牙齒做為證據。', '設計者之島的布理安娜·史奈德要10顆哥布林牙齒。', '', 'Return to Bri s Test Character in Designer Island.', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9317 AND `locale` = 'zhTW';
