INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9339, 'zhTW', '小偷的獎勵', '這道從暴風城心臟中偷來的火焰讓你感到溫暖。這股原始的力量對你來說很陌生，但(NAME)或許知道更多……', '把暴風城之焰歸還給(NAME)。', '', '', '', '', '', '', 0);
