INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9340, 'zhTW', '大裂縫', '我們差點就被聯盟軍隊給圍堵了。辛多雷朝聖者不斷從艾澤拉斯湧入，我們一定要建立一條不受敵人窺探的安全路徑。$B$B我已經想過並得到一個解決方法。我們要在大裂縫闢出一條秘密通道。$B$B沒錯即使那裡爬滿了野蠻的岩石鐮奪怪，他們不過是野獸，我們可以教教他們什麼是恐懼。我要你去殺死一堆野獸。他們應該學著害怕。', '在獵鷹哨站的遊俠隊長范瑞要你去獵鷹哨站東邊的大裂縫殺死8個小石鐮掠奪者和3個石鐮突擊隊員。', '', '去地獄火半島找獵鷹崗哨的遊俠隊長維恩雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9341, 'zhTW', '銀色黎明外衣', '', '', '', '去找銀色軍需官。', '', '', '', '', 0);
