INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9342, 'zhTW', '潛行的地殼穿刺者', '看上去侵佔礦井的gan\'arg還不是最令人頭疼的，最近有一些巨型蟲子從另外一個方向向我們入侵！$B$B索爾瑪的駐軍正忙於防範燃燒軍團和照顧他們的傷員，只能由我和礦工們來解決這件事情。$B$B〈工頭指了指睡著的苦工們。〉$B$B你能指望他們幫上什麼忙嗎……$B$B如果你能幫我消滅掉那些蟲子，我很樂意把他們的酬勞都給你。', '索爾瑪附近礦井中的Foreman Razelcraz想你殺掉15個Marauding Crust Bursters。這些蟲子有可能從地面下的隧道突然發起進攻。', '', '去地獄火半島找索爾瑪的工頭拉澤克拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9343, 'zhTW', '銀色黎明外衣', '', '', '', '去找銀色物資官。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9344, 'zhTW', '倉促的離開', '你好，$N。外域到處都充滿了危險，這是許多遠征軍很快就意識到的問題。我想年輕的Grelag也應該親自去感受一下。$B$BGrelag是一個非常有前途的學生，但是他缺乏耐心！他渴望研究他們人民的歷史，但他常常會忘記如今是危機四伏。$B$B他正前往斷脊氏族崗哨，完全忘記了虎視耽耽的燃燒軍團和邪獸人。我擔心他會發生什麼不測。', '先知瑞卡酷要你找到她的學生格萊克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9345 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9345, 'zhTW', '準備藥膏', '就在薩斯葛爾映入眼簾的同時，一個軍團的巡邏兵看到了我。我拔腿就跑，想要躲入遠處的其中一個塔，但是一隻惡魔犬抓到我而且差點咬斷我的腳!$B$B我設法逃走，但是我的腳無法配合。石衛士安比藍找到我並將我帶到這裡。$B現在，我得找個法子治療我的腿。骨葉生長在北方的白骨之谷附近。使用這種葉子做成的藥膏能夠減輕疼痛讓我繼續前進。', '收集12份地獄火骨葉植物然後交給斷脊氏族崗哨的格萊克以完成他的藥膏。', '', '去地獄火半島找斷脊氏族崗哨的葛雷拉格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9346 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9346, 'zhTW', '地獄野豬飛起來', '你看過地獄野豬飛嗎？他們還不需要翅膀就能飛喔！$B$B<警備隊長克朗克笑著。>$B$B對抗北邊的燃燒軍團營地消耗了我們的存貨，包括髮射的彈藥。這是個嘗試新事物的大好時機。$B$B除了使用大卵石，我想試試點燃東邊廢墟附近餓死的地獄野豬屍體並用來發射到燃燒軍團的營地。$B$B你是要自願幫忙，還是要我來命令你呢？', '索爾瑪的警備隊長克朗克要你幫他從飢餓的地獄野豬那裡弄到10個鼓起的地獄野豬屍體。', '', '去地獄火半島找索爾瑪的前線指揮官卡倫克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9347 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9347, 'zhTW', '野放的虛無行者', '檢查精華髮現容器內有不知明物質的強烈能量漩渦。你一邊思考，一邊感覺到你的心智開始被牽引，要你更靠近看的更深。$B$B你發覺你快抓不住你的意志，便立刻將你的視線移開。在你決定要如何處置它時，它的樣子還停留在你的意識邊緣。', '將悸動的虛無行者精華帶給索爾瑪的馬琥藍·胖蹄。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9348 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9348, 'zhTW', '圍捕劫毀者', '外域充斥著令人著迷的生物，$N。迷人但也極度危險。$B$B那裡充滿了劫毀者，以那樣貧瘠的土地看來有點奇怪，但仔細研究卻發現階級的奧妙。$B$B石頭劫毀者似乎馴化了另一種劫毀者，也就是劫毀者，並將它們育為打獵的同伴和守衛動物。我需要了解他們如何訓練劫毀者。我們一定要中斷並檢視他們在西南邊的繁殖地點，就在泰洛卡森林附近。', '替索爾瑪的馬琥藍·胖蹄殺死10個被困的小劫毀者並取得12顆劫毀者蛋。', '', '去地獄火半島找沙納爾荒地的瑪霍拉姆·硬蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9349 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9349, 'zhTW', '收集劫毀者蛋', '我快餓死了!$B$B想起來真是諷刺呀，你說是嗎?一個餓扁的廚師?$B$B<雷噶西邊笑邊拿從口袋裡拿出一張羊皮紙來。>$B$B在我們被粗暴地擊落之前，這張旅行指南指出在西南方靠近泰洛卡森林的地方有一個地區叫做刺棘蔓，那裡滿地都是美味的劫毀者蛋!$B$B假如有人有勇氣去那邊取回一些蛋的話，我可以煮出一頓豐盛的佳餚!', '替地獄火半島，飛艇失事地的雷噶西取得12顆劫毀者蛋。', '', '去地獄火半島找飛艇墜毀點的雷加希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9350 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9350, 'zhTW', '永不休息的苦工', '燃燒軍團每日不停地進犯這裡，這給我們的防守造成了非常沉重的壓力。你看，如果城牆倒塌，索爾瑪一定會失守。我已經安排了一些苦工去維修城牆，但材料似乎快要用完了。$B$B好在，先知大人的一位學生對過去的許多獸人傳統瞭解十分深刻，他推薦我們採用一種過去常用的材料修補城牆。很久很久以前，獸人經常獵殺裂蹄牛，它的肉、皮，還有骨頭，都可以派上很大的用場。現在，你去東南邊再次獵殺一些裂蹄牛，收集它們身上所有有用的東西，順便也可以透過這種方式來紀念我們的祖先。', '殺死暴怒的裂蹄牛，收集8張裂蹄牛的皮和8根裂蹄牛的骨頭，將它們交給索爾瑪的前線指揮官卡倫克。', '', '去地獄火半島找索爾瑪的前線指揮官卡倫克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9351 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9351, 'zhTW', '野放的虛無行者', '就算我能修復飛艇的骨架，我還是需要一些東西來使引擎獲得能源。我的燃料都用完了，而且這附近沒有地方能添加燃料!$B$B再我們南邊有一塊破碎的區域叫做扭曲原野，那裡充滿了狂野的虛無行者與無法控制的虛無行者。不過我更喜歡把他們當成移動的電池。$B$B如果你能帶給我足夠數量的虛無行者精華，我就能把引擎改造成以這些精華為燃料。我也可以因此飛得更遠!', '將10個濃縮的虛無行者精華帶給飛艇失事地的『驚嘆』史哥利德·幸運心。', '', '去地獄火半島找飛艇墜毀點的“尖嗓子”斯克裡·拉克希德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9352 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9352, 'zhTW', '達納蘇斯的入侵', '除了鄙惡者不斷帶來的威脅外，我還要處理各種謊報目睹夜精靈的狀況。$B$B雖然大部份的報導都是沒有根據的，但是，最近有個事件需要進一步的調查。我們的主要能量來源之一，西部聖所，而且關於達納蘇斯破壞的傳言一直很猖獗。$B$B前往那裡對付任何可疑的人。再向看守聖所的牧地看守者維蘭妮雅回報。', '前往西部聖所，就在獵鷹之翼廣場的西南邊，擊敗那裡所有的入侵者。將你的發現向牧地看守者維蘭妮雅報告。', '', '去找永歌森林的牧地看守者維蘭妮雅。', '擊敗入侵者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9353 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9353, 'zhTW', 'Redeem iCoke Gift Box Voucher', '', '', '', '去找艾拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9354 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9354, 'zhTW', '尋找新材料', '<正忙著做事的矮人見到你過來，立刻滿是期待地抬起頭。>$B$B你如果也想委託我製造裝備的話，就排隊等著吧，$c。我現在正忙著維修洛薩之子的盔甲呢，畢竟，沒幾天之後我們就得再次與敵人戰鬥了。$B$B自從那些該死的硬殼穿地蟲侵佔了礦井之後，我們的金屬庫存量就一直在下降，如今可是沒剩多少了。我正在用從榮耀堡東北邊那些暴怒的裂蹄牛身上收集到的材料做一些試驗。雖然這些材料不能完全取代鋼鐵，但眼下我們也只能將就著用了。', '殺死一些暴怒的裂蹄牛，收集8張裂蹄牛的皮和8根裂蹄牛的肌腱，將它們交給榮耀堡的哈姆菲。', '', '去找地獄火半島的哈姆菲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9355 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9355, 'zhTW', '聰明人的工作', '幸會，$c。現在援軍總算到達了，我們可以俘虜一些正常的生物了。$B$B我們首要的目標之一就是恢復西南邊路上人與貨物的流通，但得先從遍布在那裡的地殼穿刺者手中奪回來。$B$B如果你願意幫助我們對抗這個威脅，洛薩之子會很感激你。小心他們準備突襲之前在地上留下的洞。', '殺死15名捕食中的地殼穿刺者再回到榮譽堡的工頭比干莫斯那裡。', '', '去地獄火半島找榮耀堡礦洞的工頭比格姆斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9356 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9356, 'zhTW', '技術高超', '希德老愛說自己飛行「技術高超」，我想「笨手笨腳」比較符合吧!$B$B看看那邊那堆殘骸，他稱那叫「隨便」降落。$B$B當然，那是因為我們遭到射擊，不過我比較想把他大卸八塊，誰叫他一直誇讚自己的飛行技術有多好!$B$B我得為他製作一組機翼好回家。往東邊去，在白骨之谷那可以找到剃骨紅頭禿鷲  。他們的翅膀多汁豐滿，完全符合我的需要。', '將12個豐滿的禿鷲翅膀交給飛艇失事地的雷噶西。', '', '去地獄火半島找飛艇墜毀點的雷加希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9358, 'zhTW', '遊俠塞瑞', '別以為這個村子的安全是與生俱來的。我們被東邊的天譴軍團和西邊的鄙惡者包圍。遊俠塞瑞保護我們的邊界，不讓死亡之痕湧入的不死族侵擾我們。沿著出城後往東邊的路走，看看你能否幫她一把。', '向永歌森林晴風村外的遊俠塞瑞報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9359, 'zhTW', '遠行者居所', '你對壓制鄙惡者的幫助是無價的。遠行者在對抗阿曼尼食人妖時如果能有像你這樣的人一定會很有用。去東北方的遠行者營地和晨奔中尉談談，看看他需要怎樣的幫助。', '向永歌森林遠行者營地的晨奔中尉報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9360, 'zhTW', '阿曼尼入侵', '雖然你不了解這些作戰計劃的語言，你還是能清楚地辨別出一個標記著遠行者居所和晴風村的地圖。$B$B你最好讓遠行者居所的晨奔中尉知道這點。', '將阿曼尼攻擊計畫送給遠行者居所的晨奔中尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9361, 'zhTW', '地獄野豬，另一種白肉', '這些蛋很棒吧，但你說什麼?我們得更上一層樓?$B$B一片培根可讓餐點更加完美，我知道哪裡可以取得$B$B這地方到處都是地獄野豬，當然這邊沒有人負責檢查及處理這些肉，但我們很幸運!$B$B<雷噶西在身後翻找並製造出一個瓶子。>$B$B這原本不是用在豬肉上的，但烹飪本身就是一種即興創作，這已經夠用了!', '飛艇失事地的雷噶西要你去收集8個乾淨的地獄野豬肉。使用淨化藥劑來淨化你從瘋狂地獄野豬身上取的腐敗地獄野豬肉。', '', '去地獄火半島找飛艇墜毀點的雷加希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9362, 'zhTW', '督軍克雷利安', '時間不多了，$n!我的占卜法術揭露了一種強大的魔法來源。我不能離開哨塔，所以要請你去殺死擁有那個手工藝品的邪惡生物。$B$B那個可悲的小矮子，督軍克雷利安，他就躲在辛瑪洛神殿的守衛群後面。把他化成灰燼並拿走他最珍愛的稜彩貝殼。', '為大法師克希雷姆取得稜彩貝殼。大法師就住在艾薩拉懸崖邊上的一座哨塔裡。', '', '去艾薩拉找在熊頭的大法師克希雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9363, 'zhTW', '警告晴風村', '前往晴風村警告遊俠迪哥里恩關於阿曼尼的計劃。即使祖瑪羅什已死，晴風村還是要準備好對抗食人妖的攻擊。告訴迪哥里恩我們會盡快派遣援軍給他。', '前往永歌森林的晴風村和遊俠迪哥里恩談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9364, 'zhTW', '破碎的魔法', '我的研究揭露了稜彩貝殼的一個獨特用途。$B$B帶著貝殼並對艾薩拉的惡鞭者施放你的變形法術。如果你等待一下，貝殼混亂的光環會讓它們變成幾個更小的複製物一陣子。用最快的速度把這些複製物殺死，貝殼就能收集它們的精華。$B$B等貝殼滿了，再回來交給我。', '對艾薩拉的惡鞭者施放變形術並殺死幾秒後出現的複製物。等你殺夠了，再回去找艾薩拉的大法師克希雷姆。', '', '去艾薩拉找在熊頭的大法師克希雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9365, 'zhTW', '小偷的獎勵', '這道從暴風城心臟中偷來的火焰讓你感到溫暖。這股原始的力量對你來說很陌生，但(NAME)或許知道更多……', '把暴風城之焰歸還給(NAME)。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9366, 'zhTW', '需要魔化之血', '這裡的東北邊是阿葛納爾之池。它曾是德萊尼人的聖地，但在惡魔阿葛納爾的鮮血濺到水裡後他們的水源就被汙染了。$B$B那鮮血雖然老邁且被稀釋，它仍具有極大的力量。恐懼惡魔現在到處都是，他們有著魔化之血所蘊含的純淨惡魔能量。殺死他們取得你能弄到的所有魔化之血。我會好好獎勵你。', '地獄火半島獵鷹哨站的『憂鬱者』瑞安登要你從住在阿葛納爾之池的恐懼惡魔身上取回6份魔化之血樣本。', '', '去找地獄火半島獵鷹崗哨的陰沉的利亞森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9367, 'zhTW', '火焰節慶', '仲夏又來了!$B$B每一年，按照傳統，雀屏中選的營火管理者要負責看管我們城市裡的營火。當整個艾澤拉斯都是燃燒的火焰時，我們的火苗一定要是最熱烈、最明亮的，才能恰當地表現出對季節的尊敬。$B$B事實上，我有個任務要給你，如果你不介意的話。我還沒聽說所有主城裡的火焰都燃燒的恰如其分。前往那裡讓火焰為你取取暖 -- 確定它們是燙的!', '觸摸暴風城，鐵爐堡和達納蘇斯裡的營火，再和任何一個節慶傳說大師談談。', '', '去找節慶傳說大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9368, 'zhTW', '火焰節慶', '仲夏又來了!$B$B每一年，按照傳統，雀屏中選的營火管理者要負責看管我們城市裡的營火。當整個艾澤拉斯都是燃燒的火焰時，我們的火苗一定要是最熱烈、最明亮的，才能恰當地表現出對季節的尊敬。$B$B事實上，我有個任務要給你，如果你不介意的話。我還沒聽說所有主城裡的火焰都燃燒的恰如其分。前往那裡讓火焰為你取取暖 -- 確定它們是燙的!', '觸摸奧格瑪，雷霆崖和幽暗城裡的營火，再和任何一個節慶故事使者談談。', '', '去找節慶故事使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9369, 'zhTW', '補充治療水晶', '我們是德萊尼。我們的船失事了，而且由於我們有許多傷者，我們現在最擔心的就是治療水晶的耗用情形。我們一定要盡快補足水晶!$B$B不幸的是，我們此時唯一的選擇就是從當地的山谷飛蛾身上直接抽取血液。他們的血液是很合適的替代品。$B$B你可以在溪谷附近的區域找到他們，不過他們大多集中在西北方。', '從附近的安曼谷飛蛾身上取得8瓶飛蛾血清，再回到安曼谷失事地點的波尼特斯那裡。', '', '去埃門谷找墜毀點的普羅尼圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9370, 'zhTW', '阻止淨化', '我們的斥候最近在阿葛納爾之池附近抓到了一名德萊尼聖騎士。他要去參加淨化池子的祭儀。我們一定要阻止那個德萊尼，否則我們將會失去魔化之血的供給!$B$B他帶著這個信號寶石，想找到一個讓牧師 - 或他們自稱的「隱士」- 可以安全進行祭儀的地方。將寶石放在阿葛納爾祭壇附近並準備好攻擊任何接近的德萊尼人。$B$B我建議你帶一兩個盟友一起去。', '前往阿葛納爾之池，將德萊尼信號寶石放在阿葛納爾祭壇附近，擊敗任何回應你召喚的德萊尼隱士。完成後帶著信號寶石回到獵鷹哨站的『憂鬱者』瑞安登那裡。', '', '去找地獄火半島獵鷹崗哨的陰沉的利亞森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9371, 'zhTW', '植物學家泰瑞茲', '$N，植物學家泰瑞茲需要你的幫助。你可以在西邊找到她和她的學徒，就在船外面。', '和安曼谷失事地點的植物學家泰瑞茲談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9372, 'zhTW', '惡魔污染', '歡迎來到塞納里奧前哨，$c。我們這裡很少有人來，但你的到來讓我很感激。我的工作因為要研究這些荒蕪土地的生物，所以我必須獨自前往偏遠地區。$B$B塞納里奧遠征隊派我去研究外域中最危險的一些野生動物，而我也有了驚人的發現。雖然這裡的許多生物已經歷了徹底的改變，但他們仍持續產生突變。我在收集鮮血樣本來證明這些改變，歡迎任何人的意幫忙。', '地獄火半島上塞納里奧前哨的塞伊亞·紅髮要你從笨重的地獄野豬身上收集6份地獄野豬血的樣本。', '', '去地獄火半島找塞納里奧哨站的塞安·紅鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9373 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9373, 'zhTW', '丟失的公文', '在檢查被打扁的皮箱時，很明顯的看出箱子的損壞一定是蠕蟲的腐蝕性消化液體造成的。皮革看來被工具雜亂地加工過，但裝飾品的細節已無法辨別。$B$B唯一可辨識的箱子特徵就是一個老舊的塞納里奧議會標誌。在完全不了解箱子裡裝了什麼的情況下，你決定最好的辦法就是將它送給議員成員。', '將磨損的皮箱交給塞伊亞·紅髮，他紮營在靠近西地獄火半島的夏納廢墟。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9374, 'zhTW', '阿利恩的日記', '我的丈夫，阿利恩，自從我們到了外域後就對阿葛納爾之池非常迷戀。他花了很多時間研究所有關於軟泥怪的事!$B$B他幾天前消失在阿葛納爾之池。他們說他死了而我也束手無策。$B$B我能做的一件事就是確保他的研究不會跟他一起死去。往東北方前往那個池子尋找他的日記，他通常都放在一個棕色的背包裡。', '地獄火半島，獵鷹哨站的博學者卡莉達要你去阿葛納爾之池取得阿利恩的日記。', '', '去地獄火半島找獵鷹崗哨的魔導師卡爾琳達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9375, 'zhTW', '通往獵鷹哨站的路', '<憔悴的血精靈看到你的出現露出了一絲寬慰。>$B$B拜託，$c，把我從這個籠子裡弄出去!我不顧馬提克·托塞德利的警告，魯莽地拋下我們那群人從索爾瑪出發。$B$B我被馬提克提到的生物設下陷阱，一定就是劫毀者。我設法把他們趕走，但那就是麻煩的開端。$B$B因為我的傷，那些鳥人找到了我，把我拖回這籠子裡，並把我鎖在這!我一定要回到獵鷹哨站!', '保護受傷的血精靈朝聖者前往獵鷹哨站，然後與達勒利斯·凝明交談。', '護送受傷的血精靈朝聖者回到獵鷹崗哨', '去地獄火半島找獵鷹崗哨的塔雷里斯·晨光。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9376 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9376, 'zhTW', '朝聖者的困境', '那個受傷的朝聖者看來像在喊著跟背包有關的事。$B$B你遇到她的時候，在附近有看到一個背包嗎?嗯……$B$B她一定是在逃離攻擊的時候掉了背包的。這些惡毒的劫毀者，在南方的峽谷中的這些惡毒的劫毀者，以愛攻擊落單的旅人而出名。$B$B如果她不冷靜下來，我就無法治療她的傷。她的固執只可能會賠上她的性命。$B$B到塵羽峽谷去看看是否可以找到她紮營的地方。我打賭她把背包掉在那了。', '那個受傷的血精靈朝聖者在塵羽峽谷紮營時遭到惡毒的劫毀者攻擊。找到她的營地並尋找朝聖者丟失的背包。', '', '去地獄火半島找獵鷹崗哨塔的雷里斯·晨光。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9377 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9377, 'zhTW', '渴望力量', '一般來說，獵鷹崗哨是朝聖者們來到外域之後的第一個停留點。儘管這裡已經是那些朝聖者所能找到的最近的血嚮導定居點，但許多朝聖者到達這裡時，已經深深陷入了對魔法能量的極度飢渴之中。$B$B在這樣一個全新的世界中，許\\r\\n多血嚮導都會發現他們有必要重新學習如何獲得魔法能量。$c，他們需要食物和水，不過他們最需要的仍然是魔法能量。外域中的虛空行者體內蘊藏著十分強大力量，但是虛空行者數量非常稀少，你只能在西南邊的遷躍平原找到他們。', '從虛空行者身上收集1份強大的虛空行者精華，將其交給獵鷹崗哨的塔雷里斯·晨光。', '', '去地獄火半島找獵鷹崗哨塔的雷里斯·晨光。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9378 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9378, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9379 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9379, 'zhTW', '惡魔獵犬的補品', '你好，$c。跟基爾西也打個招呼吧。別怕別怕，除非有我的命令，否則它是不會咬人的。$B$B<安吉拉對著這隻地獄犬發出咕咕的叫聲。>$B$B跟居住在外域的遷躍犬相比，它的體型未免也太過嬌小了。不過我們很快就能改變這一點，對吧，基爾西？$B$B我想我已經有辦法了。我希望你能幫我搞來一些遷躍犬的血液，你可以去東南邊捕捉它們，然後放血，我需要這些東西來進行試驗……嗯，算是“治療”吧。', '將6份遷躍獵犬之血交給索爾瑪的“利爪”安吉拉·凱斯提爾。', '', '去找地獄火半島的“利爪”安吉拉·凱斯提爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9380, 'zhTW', '群居的獵犬', '我發誓，如果我再收到來自鐵爐堡的信件……$B$B你有沒有過向那些根本聽不進你說話的人解釋過什麼事的經歷呢，$c？我把鐵爐堡裡那些人要的遷躍獵犬標本送了過去，可他們居然厚顏無恥地回信說，他們要的不是一隻而是“一群”！一群遷躍獵犬！$B$B我只好再寫信向他們解釋說遷躍獵犬是獨居生物，但是沒有一個人相信。我真是懶得再跟他們多說了，你願意到榮耀堡的東邊去幫我再搞六隻標本回來嗎？', '將6只完整的遷躍獵犬屍體交給榮耀堡的勘探員穆拉圖斯。', '', '去找地獄火半島的勘探員穆拉圖斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9381, 'zhTW', '真禽之箭', '由於大量的朝聖者湧入，獵鷹哨站最近變的相當忙碌。我最近沒什麼時間四處探險，所以我沒辦法完成這批箭，除非我能收集到更多的羽毛。$B$B一個有自尊心的遊俠是不能沒有箭的，但我該怎麼做?如果你願意去獵鷹哨站北邊幫我收集剃骨禿鷹的尾部羽毛我會很樂意獎勵你。它們通常是在獵鷹哨站北邊的巨大獸骨那盤旋。', '從剃骨禿鷹身上收集8根剃骨尾羽，交給獵鷹哨站的獵鷹者崔娜·河風。', '', '去地獄火半島找獵鷹崗哨的馴鷹者德蕾娜·河風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9382, 'zhTW', '裂蹄的命運', '你好，$c。$B$B我相信你在外域的旅行中一定已經見到了這個世界中某些墮落的力量。這些力量讓居住在這裡正常的生物變得扭曲\\r\\n - 確切地說是那些活著的生物。$B$B南邊和西邊的clefthoof曾經是非常溫順的食草動物，但世界的墮落給他們造成了無止境的災難。儘管我們會很傷心，但只有死亡才能將他們從痛苦的折磨中解救出來。你願意幫幫我，解除bristlehide clefthoof的痛苦嗎？', '殺掉15個Bristlehide Clefthoof，向塔哈瑪特神殿的Wise Amaan覆命。', '', '去找地獄火半島的智者阿曼恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9383, 'zhTW', '野心勃勃的計劃', '血精靈象徵著不負責任的魔法使用，$c。他們不控制魔法能量，不，他們根本是魔法的奴隸，最後他們在自己和沉溺之間會什麼也得不到。他們利用外域虛無行者的能量來壯大自己的惡魔魔法。$B$B我準備了一個法術加持過的水晶讓我們中和一個虛無行者，摧毀之後可以切斷它與這個世界的連結。虛無行者大多數出現在地獄火堡壘東南邊的扭曲原野。', '對已受傷且無法控制的虛無行者使用神化水晶再回到特爾哈曼神廟找伊莎安娜。', '', '去地獄火半島找塔哈瑪特神殿的艾爾薩娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9384, 'zhTW', '<待完成任務>', '現在是時候殺死這個怪物了。$N，你一定要小心，畢竟你對外域的虛空行者還不夠熟悉。$B$B將這個容器交給負責毀滅虛空行者的魯瑪圖。仔細地觀察整個過程，然後回來向我報告。', '將閃光的淨化水晶交給沙納爾神殿的魯瑪圖，他會利用聖光的力量來摧毀水晶中的虛空行者。', '', '去找地獄火半島的艾爾薩娜。', '協助摧毀虛空行者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9385, 'zhTW', '消滅劫毀者', '榮譽堡派我們與阿拉卡談判，而我們在此紮營並想著「嘿，這裡真是一個很棒的據點」。我們不知道和惡毒的劫毀者有多接近。$B$B他們是無情的劫毀者，讓我們所有的工作都無法進行。如果你能替我們解決他們，我們將可以提供一點獎金給你。你覺得呢?', '殺死10個惡毒的劫毀者後回到地獄火半島找葛明尼·長鬚。', '', '去找地獄火半島的格雷尼·長鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9387, 'zhTW', '腐敗根源', '如這個不幸的傢伙一般，未受腐敗的德萊尼，是善良的聖光勇士。是什麼樣的腐敗讓他們偉大的種族變成破碎者和失落者呢?$B$B聽說有個理論顯示低落的能量是影響變化的主因，我想要證實這個理論的真實性。$B$B你會在西北方的夏納廢墟找到受伊利達瑞監工控制的卑微的失落者。從監工身上得到惡魔精華後拿來給我，這樣就可以在這位德萊尼身上試驗看看。', '前往地獄火半島的夏納廢墟從伊利達瑞監工身上取得5個惡魔精華。完成任務後回到獵鷹哨站找藥劑師艾斯隆。', '', '去地獄火半島找獵鷹崗哨的藥劑師艾瑟森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9388, 'zhTW', '卡林多的閃爍火焰', '世界各地都有許多的火焰在燃燒著，$n。最難處理的火焰就是那些發著綠光的;沒有管理的話它們不會長久燃燒。為我們的火焰管理者確認那些翠綠色的火焰仍在卡林多燃燒著，聽到了嗎?$B$B你可以在貧瘠之地的棘齒城，黑海岸的主宰之劍附近找到它們，還有從銀翼哨站旁的橋邊進入梣谷的森林裡，和沿著石爪山脈的幹道走到通往狂風峭壁的路上都能找到。', '探勘梣谷，貧瘠之地，黑海岸，和石爪山脈的營火，再和節慶火焰管理者談談。', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9389, 'zhTW', '東部王國的閃爍火焰', '仲夏火焰節慶傳統上會在整個土地上點燃無數的火焰。有些人說綠色的火焰是最美的，因為它們是最難維持的而且又有獨特的色澤。為我們的火焰管理者確認它們仍在東部王國燃燒著。它們座落在濕地的丹莫德附近，銀松森林內的焚木村那裡也有，眺望濕地燈塔的峭壁上，和希爾斯布萊德丘陵廢棄的哨塔旁。', '探勘希爾斯布萊德丘陵，銀松森林，西部荒野，和濕地的營火，再和節慶火焰管理者談談。', '', '去找節慶營火管理者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9390, 'zhTW', '尋找希戴', '聽聽我的困境，$c。我的兄弟，希戴，很久以前就出發去聯絡瑪格哈崗哨的獸人。他總是個理想主義者，認為是展現我們的不同並和他們和平協議的時候了。$B$B他已失蹤了好幾天了，我擔心他遭遇不測。$B$B你能讓我的心靈稍作休息去找他嗎?希戴一定就在東邊附近的某個地方。', '隱士歐拜德要你去尋找他的兄弟，希戴，就在地獄火半島的東邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9391, 'zhTW', '記下路徑', '岩石鐮奪怪的數量愈來愈少，所有遺留下來的是為了指引朝聖者前往安全的路徑。帶著火炬回到大裂縫並從東邊搜索三個標示路徑的烽火臺。$B$B點燃三個烽火臺然後回來找我。請小心，當你點燃第一個烽火臺之後，將會吸引附近任何一個岩石鐮奪怪。', '獵鷹哨站的遊俠隊長范瑞要你前往地獄火半島的大裂縫點燃南方烽火臺、西方烽火臺和中央烽火臺。完成任務後帶著點燃的火炬回去找他。', '', '去地獄火半島找獵鷹崗哨的遊俠隊長維恩雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9392 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9392, 'zhTW', '盜賊訓練', '隨著你的職業技能越來越精進，你就要從你的職業訓練師那裡多學一點東西。在逐日者之島，年輕盜賊的訓練師是巡路者凱瑞爾。和凱瑞爾談談，看看他能提供你什麼訓練。向他學東西是要花錢的，所以帶一點錢在身上。$B$B凱瑞爾 - 和所有逐日者之島的訓練師一樣 - 都在日尖塔的較低層。', '和巡路者凱瑞爾 - 盜賊訓練師談談，他就在逐日者之島的日尖塔裡面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9393 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9393, 'zhTW', '獵人訓練', '隨著你的職業技能越來越精進，你就要從你的職業訓練師那裡多學一點東西。在逐日者之島，年輕獵人的訓練師是遊俠薩琳娜。和薩琳娜談談，看看她能提供你什麼訓練。向她學東西是要花錢的，所以帶一點錢在身上。$B$B薩琳娜 - 和所有逐日者之島的訓練師一樣 - 都在日尖塔的較低層。', '和遊俠薩琳娜 - 獵人訓練師談談，她就在逐日者之島的日尖塔裡面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9394, 'zhTW', '威利坦在哪裡?', '暗木的地面守衛者不見了!一定是博學者和大家離開時忘了叫他一起走了。我知道他還在營地附近，但我不敢自己去找他，有太多魔法生物在那裡閒晃了。你能幫我去找他嗎，$c，確定他還安然無恙?', '到永歌森林的暗木營地尋找地面守衛者威利坦。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9395, 'zhTW', '薩瑟里的避風港', '我發誓如果再讓我收到跟薩瑟里領主的舞會物資相關的請求我就要用火球殺了某人!我看起來像舞會策劃人嗎?!再偷偷告訴你，那個白痴和他的食客們根本就不相信我們這裡正遭受攻擊!我們有些人正忙著，呃，我不知道，防守奎爾薩拉斯剩下的土地!$C，可以請你前往薩瑟里的避風港看看能不能讓他閉上嘴嗎?那地方就在往西邊的路上。', '到永歌森林和薩瑟里的避風港的薩瑟里領主談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9396 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9396, 'zhTW', '阿拉卡的魔法', '外域裡有許多秘密，$n。我們遲早都會發現它們的。$B$B半人半鳥的阿拉卡擁有古老的秘法知識，能大大地幫助我們探索這個世界。前往南邊的海艾斯洞穴。取得任何海艾斯可能帶在身上的魔法卷軸並帶回來給我。', '帶回4個海艾斯卷軸到地獄火半島給獵鷹哨站的秘法師卡拉崔斯·晨星。', '', '去地獄火半島找獵鷹崗哨的奧術師卡雷希斯·晨星。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9397, 'zhTW', '稀有的鳥類', '海艾斯阿拉卡馴養了一種叫做卡里瑞的美麗鳥類。$B$B我之前抓到了一隻年輕的公鳥而他們似乎是可訓練的。如果我有一隻母鳥那麼我就能試著孵化牠們。不過她一定要很年輕……要是幼鳥才行。一隻年老的野生鳥無法在籠中生存。$B$B拿著這個籠子前往南方，到海艾斯洞穴去。在那些蛋中尋找快孵化的。如果你幫我帶回來一隻母幼鳥，我就會重重的答謝你。', '前往地獄火半島的海艾斯洞穴捕捉一隻母卡里瑞幼鳥。用這個空的鳥籠捉住她，完成這個任務後再回去找獵鷹者崔娜·河風。', '', '去地獄火半島找獵鷹崗哨的馴鷹者德蕾娜·河風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9398, 'zhTW', '痛恨的掠奪者', '住在外域的破碎者忍受著永無止盡的暴力。因此當黑暗之門敞開時，他們帶著逃離這片土地的無限希望蜂擁而上並不令人驚訝。$B$B但不幸的，住在大裂縫的岩石鐮奪怪視我們從南方來的兄弟姊妹為獵物。到那去削弱岩石鐮奪怪的數量，這樣我們的族人才有機會。', '地獄火半島特爾哈曼神廟的斥候范路娜要你去殺死8個小石鐮掠奪者和4個石鐮突擊隊員。', '', '去找地獄火半島塔哈瑪特神殿的斥候瓦努拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9399 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9399, 'zhTW', '殘酷的監工', '你或許覺得大部份的破碎者都是邪惡的，對嗎?其實他們只是缺乏指引。$B$B在我遇見歐曼奈之前，我也曾失落。$B$B我們的心靈因為獸人的惡魔魔法受盡痛苦的折磨。我們很容易迷惑和被佔便宜。$B$B與伊利丹同盟的惡魔們，鎮日襲擊地獄火並俘虜我們的族人當做奴隸。因為歐曼奈我們現在有了希望。前往西南方的夏納廢墟，殺掉伊利達瑞監工，我們就可以重獲自由了!', '到夏納廢墟殺死4名伊利達瑞監工，再回到地獄火半島的特爾哈曼神廟找依坎。', '', '去地獄火半島找塔哈瑪特神殿的伊坎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9400 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9400, 'zhTW', '刺客', '$n，我們最近發現了一個秘密計畫，內容是要暗殺我們前往獵鷹哨站的使者。地獄火堡壘知道了我們的計畫，所以今早派遠征隊前往設下埋伏。$B$B我們的斥候告訴我一個叫做克魯恩·斷脊氏族的刺客在堡壘北邊的路上等待著。去那裡殺了這個刺客。讓魔獄獸人知道我們不是好惹的!', '納茲格雷爾要你前往地獄火堡壘北邊的道路尋找一個叫克魯恩·斷脊氏族的刺客。', '找到克倫·斷脊者', '去地獄火半島調查邪獸人的屍體。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9401 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9401, 'zhTW', '奇怪的武器', '你將石斧從屍體裡抽出來更仔細地檢視它。這個武器的製作技巧有些不尋常。$B$B它的來源像是獸人的東西，雖然它的材質是你從未見過的。納茲格雷爾或許有興趣看看這個武器。', '將沉重的石斧帶到地獄火半島的索爾瑪交給納茲格雷爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9402 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9402, 'zhTW', '去吧!', '那麼……$n是嗎?別因為我知道你的名字就受寵若驚，我有個學生就一直不停下的奉承你。$B$B嗯……如果你想給<她/他>一個好印象，何不為我做點什麼呢?在我身後的池塘底部有一個碧藍之瓶。潛入水底把它帶來這裡。', '潛入靜語池底為導師安西歐取得碧藍之瓶。', '', '去永歌森林找縈語水池的指導者安瑟隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9403 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9403, 'zhTW', '純淨之水', '既然你已經學到一些東西了，那我就在教你更實際的東西吧。在近戰狀態下能夠保護自己，跟你的能力有關。當然，在大部分緊迫的情況下你該求助於近戰，但那不是你不做準備的藉口。$B$B我可以協助你製作一個適合你的法師訓練的法杖。把你為我取得的小玻璃瓶拿去裝滿艾蘭達瀑布底部的水。沿著東南方的河流走就可以了。', '導師安西歐要你去艾蘭達瀑布裝滿碧藍之瓶。', '', '去永歌森林找縈語水池的指導者安瑟隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9404 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9404, 'zhTW', '適者生存', '你或許注意到艾蘭達瀑布附近走動的樹木。身為大自然的保護者，他們被注入了原始的魔法，利用你帶來給我的水，我們可以依照我們自己的目的來重新改變他們。$B$B不幸的是，森林守衛者是瘋狂的生物，所以你需要殺死幾個才能找到可用的樹枝。', '殺死永歌森林守衛者直到找到完美的樹枝給導師安西歐。', '', '去永歌森林找縈語水池的指導者安瑟隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9405 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9405, 'zhTW', '大酋長的命令', '你知道的，大酋長會把他的權力放在這次遠征之後只有一個原因。我們來自這個世界。這是我們生根的地方。$B$B這個旅程對獸人和血精靈而言具有不同的意義。他們視旅程為尋找樂土。但是，對我們而言那就像回到家園。$B$B無論是誰把這把斧頭製作的和傳統斧頭極為相似，我們一定要聯絡他。這件事情對我們太重要了，所以不能使用一般的追查方式。把武器拿給先知瑞卡酷，她會知道該怎麼做。', '把沉重的石斧帶給在地獄火半島索爾瑪的先知瑞卡酷。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9406 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9406, 'zhTW', '瑪格哈', '你從黑暗之門那一邊帶來的這個消息……你要我們相信杜洛坦之子現在統治著它後方的土地……沒有任何惡魔的污點?還有現在他的人民已重回這個世界?$B$B為了你好，我希望這不是什麼玩笑話，$c。這對我族人的意義……是無法言喻的。我一定要立刻捎個口信到納葛蘭!地獄吼一定要聽聽這個消息。$B$B帶著這封信回去索爾瑪給你的領導者。告訴他瑪格哈歡迎他們!', '將來自瑪格哈的信送回地獄火半島給索爾瑪的納茲格雷爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9407 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9407, 'zhTW', '通過黑暗之門', '多年來黑暗之門呈現靜默……被遺忘的狀態。但它不再沉默了。$B$B在停止這裡猛烈的攻擊後，我們的軍隊衝破這道大門與這些惡魔們在他們的地盤見面了!$B$B現在，我們被困在這場凶惡的戰爭中，而有一些人認為我們可能會輸。然而這是我們的責任，我們堅定的信念，擊倒這些外域的惡魔並確保我們的勝利，$n。$B$B如果你能幫忙我們，就立刻去跟歐萊恩中將報告。他在外域等著你……', '傳過黑暗之門找到歐萊恩中將。他在另外一邊等著你的到達，就在外域裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9408 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9408, 'zhTW', '被遺忘的英雄', '在為那些當初在關閉黑暗之門的戰役中犧牲的士兵們感到痛苦的同時，我的內心也為得知仍有許多當初的遠征軍戰士活了下來而感到自豪與驕傲。$B$B我真不敢相信，但他們確實矗立在那裡——宛如一座座鐫刻著所有聯盟將士決心的豐碑。$B$B就在那座要塞中，有一位我們所有人都萬分景仰的英雄——達納斯·托爾貝恩！立刻找到他，$c。他已經見過許多我們派過去的士兵了，當然也會非常樂意見到你。', '與榮耀堡的遠征軍指揮官達納斯·托爾貝恩談一談。', '', '去地獄火半島的榮耀堡找遠征軍指揮官達納斯·托爾貝恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9409, 'zhTW', '緊急送件!', '既然你已收集了所有我們需要的東西來補充我們的治療水晶，我要你送些瓶子給我們的牧師，薩度恩。他就在船中央的房間裡照料我們的傷者。', '將一捆瓶子送到安曼谷給失事地點的薩度恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9410 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9410, 'zhTW', '精神指引', '就算是我們優秀的追蹤狼都比不過他們，$n。靈魂自有一套不同於我們看待這個世界的方式。你現在的作為將會帶領你前往所尋找的人面前，他們顯現出來的不只是他們蹤跡，還有他們的精髓。$B$B現在就去，$c，帶著這個圖騰，在發現石斧的地方使用它。', '在你到找克魯恩·斷脊氏族屍體的地點使用狼圖騰，然後跟著先祖之狼圖騰的靈魂。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9411 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9411, 'zhTW', '<UNUSED>Infused Bandages', '', '', '', '去找東瘟疫之地的白鬚大使。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9412 AND `locale` = 'zhTW';
