DELETE FROM `quest_template_locale` WHERE `ID` = 9413 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9413, 'zhTW', '<UNUSED>Crystal Flake Throat Lozenge', '', '', '', '去找希利蘇斯的藥劑師奎因納德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9414 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9414, 'zhTW', '<UNUSED>Infused Bandages', '', '', '', '去找希利蘇斯的藥劑師奎因納德。', '', '', '', '', 0);
