INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9415, 'zhTW', '向治安官藍牆報告', '你是治安官藍牆的新兵嗎?你當然是啊。$B$B你還在等什麼?優秀的士兵都死在沙漠裡了。你不想快點加入他們嗎?$B$B現在，快去吧，別在路上變成人乾啊。', '到佐拉蟲巢旁的聯盟營地和治安官藍牆談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9416 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9416, 'zhTW', '向奇立卡將軍報告', '你一定是奇立卡將軍的新兵。你也該是時候出現了。在沙漠裡體力很快就會負荷不了。$B$B矮人每天都在增加援軍，而我們不能在短缺資源的希利蘇斯損失土地。$B$B向將軍取得你的指令。我的工作不是訓練你，而是找到你。', '到雷戈蟲巢旁的部落營地和奇立卡將軍談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9417 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9417, 'zhTW', '阿拉卡的威脅', '阿拉卡是種很聰明的生物……就和你見過的所有地精一樣聰明。不過，他們就是有這樣的魔法和暴躁的脾氣。$B$B最近他們攻擊了榮譽堡的巡邏者，這就是我們被派來這裡的原因。你聽，麥倫和我都是舉世聞名的神射手，我們實至名歸!但是我們的專長是獵鳥和其他獵物……而不是……召喚閃電的鳥人。$B$B對於這次的任務你說能給予我們什麼樣的協助?你會在西南邊找到海艾斯洞穴。', '地獄火半島的葛明尼·長鬚要你殺死4個海艾斯風行者和6個海艾斯猛爪護衛。', '', '去找地獄火半島的格雷尼·長鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9418, 'zhTW', '艾芙魯的寶珠', '<你將寶珠拿近，聽到一股聲音對你說話。>$B$B我感覺到你不是阿拉卡人，所以我試著交換自由。我叫艾羅那斯。我曾經統治東部的風。海艾斯的法師，艾芙魯，將我禁錮在寶珠中。$B$B找到阿拉卡人用來奴役我的祭壇。它就藏在阿拉卡巢穴的東南方。帶著寶珠靠近並在我自由後交還給我。我將會給你強大的寶藏來交換我的自由!', '把艾芙魯的寶珠帶回地獄火半島，到海艾斯洞穴東南方的海艾斯祭壇，一旦艾羅那斯重獲自由就把寶珠交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9419 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9419, 'zhTW', '穿過沙漠', '我們最近發現部落一直在希利蘇斯沙漠中搜尋有用的資源，但是不用太擔心他們。我們認為這悶熱的沙漠不太值得部署大批軍力。$B$B不過，那些資源的重要性已被發現，現在我們正努力在趕進度。$B$B如果我能獲得你的協助，你一定要進入沙漠取得希利塞斯紅塵並將它帶回來這裡。', '找到並將希利塞斯紅塵送到希利塞斯提取器那裡，再到佐拉蟲巢附近的聯盟營地和治安官藍牆談談。', '', '去找希利蘇斯的布魯沃爾元帥。', '運回水晶塵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9420 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9420, 'zhTW', '完美的羽毛', '在這裡南邊的海艾斯洞穴的阿拉卡飼養了一種特殊品種的鳥類，叫做卡里瑞。牠們的羽毛在艾澤拉斯的交易所可以賣得一大筆錢。想想看到時候我能買多少麥芽酒!$B$B告訴你，只要你幫我帶回一堆卡里瑞羽毛，我就會送你一頂我私有的帽子。你認為如何?你永遠都找不到一樣的帽子啊!就這麼說定?', '地獄火半島的麥倫·長鬚要你從海艾斯洞穴不同種類的卡里瑞身上弄到8根卡里瑞羽毛。', '', '去找地獄火半島的米倫·長鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9421, 'zhTW', '薩滿訓練', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9422, 'zhTW', '穿過沙漠', '我們已經汲取希利蘇斯沙漠的水晶資源好一陣子了。我們面對的唯一危險就是那些把這個地方當做他們家園的生物，令人受不了的沙子灰塵和高溫。$B$B但是現在聯盟似乎知道我們在這裡發現了什麼。我們之間展開了搶奪天然資源大賽還要防止它們被其他人奪走。$B$B我需要所有可獲得的幫助。我希望你能伸出援手。', '找到並將希利塞斯紅塵送到希利塞斯提取器那裡，再到雷戈蟲巢附近的部落營地和奇立卡將軍談談。', '', '去希利蘇斯找雷戈蟲巢的吉里卡將軍。', '運回水晶塵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9423, 'zhTW', '回去找歐拜德', '希戴的死被證實了，你帶著這個殘酷的消息回去找歐拜德。', '回到地獄火半島的特爾哈曼神廟找隱士歐拜德，告知他希戴的死訊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9424, 'zhTW', '瑪酷魯的復仇', '希戴就像瑪酷魯的兄弟一般，而我們還能夠活著都是因為他!他們說瑪酷魯瘋了，但如果歐曼奈一直都不採取行動的話，那他們才是瘋了!$B$B瑪酷魯雖然沒有多大力量，但如果你要幫希戴報仇，他必定傾出所有來幫助你。$B$B我之前曾在東北方的山丘上看過那個棕色獸人瑪格哈自言自語，他們憎恨我們!不值得我們的同情!去吧，為希戴報仇!帶著他們的先祖珠串來證明你完成了!', '地獄火半島上特爾哈曼神廟的瑪酷魯要你帶給他10個瑪格哈先祖珠串。', '', '去地獄火半島找塔哈瑪特神殿的瑪庫魯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9425 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9425, 'zhTW', '向塔倫米爾報告', '啊，很高興再次見到你，$c!我有一個相當適合你的任務。$B$B加入成為部落的一員，我們要確定支持他們的努力，並協助他們解決問題。這樣更有助於他們幫助我們。$B$B前往希爾斯布萊德丘陵東南方被遺忘者之城的塔倫米爾。當你到達時，請去找諫言者幽曦。', '前往希爾斯布萊德丘陵的塔倫米爾和諫言者幽曦談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9426 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9426, 'zhTW', '阿葛納爾之池', '自從我們稱這塊土地為德拉諾就發生了很多事。這塊土地的其中一部分被惡魔污染永久改變了。$B$B有一個大家都知道的地方，阿葛納爾之池。這曾經是個人們的神聖泉源所在地。如果我們要收回這個池塘，血之惡魔阿葛納爾所造成的污染一定要淨化。沿著這裡往東走，殺了在池塘邊徘徊的恐懼惡魔和軟泥怪。', '『智者』阿曼要你前往阿葛納爾之池，並殺掉6隻恐懼惡魔和6隻憤怒的腐泥怪。', '', '去地獄火半島找塔哈瑪特神殿的智者阿曼恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9427, 'zhTW', '淨化水源', '我必須要求你完成我們指派給你的任務。既然惡魔勢力已經削弱，你一定要帶著這瓶淨化水瓶去淨化被污染的源頭 - 阿葛納爾自己的屍體。$B$B你將在阿葛納爾之池北方盡頭找到惡魔的骨頭。小心，我感覺阿葛納爾的本質並沒有放過這個世界。', '『智者』阿曼要你前往阿葛納爾之池並對阿葛納爾的屍體使用淨化的瓶子。當阿葛納爾的本質藉由瓶子裡的水得到淨化就回去找他。', '', '去地獄火半島找塔哈瑪特神殿的智者阿曼恩。', '淨化阿苟納的氣息', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9428, 'zhTW', '向碎木崗哨回報', '<當她靠近的時候，大使要她降低音量。>$B$B你享譽盛名，$n。我要你前往在梣谷的碎木崗哨。步行前往最方便的道路是往西走穿過杜洛塔和貧瘠之地，然後再分叉路往北轉。$B$B當你到達時，和諫言者·日誓談談。路上小心;梣谷是個很危險的地方!', '前往梣谷的碎木崗哨，和諫言者·日誓談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9429, 'zhTW', '前往夜色鎮', '我被告知暴風城有大麻煩了。著名的暮色森林，一個充滿不死生物邪惡及污穢臭味的地方。$B$B就在我們努力幫忙的同時，我要你前往東南方的夜色鎮，那是人類主要居住的城鎮。隱士·迪藍會等待你的到達。', '到暮色森林的夜色鎮去找隱士·迪藍談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9430 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9430, 'zhTW', '夏納聖物', '如同我之前所說，我不渴求能夠看到別人所無法看到的。我不會批評你對瑪酷魯的代表所做的事，但我認為你需要去了解所看到的表象背後的意義。$B$B到夏納廢墟的西南方去搶救你所發現的任何聖物。如果命中註定的話，你就會找到我們需要的東西。$B$B我的要求所蘊含的本意也許不會馬上顯現。但要有信心，$n。真理永遠顯現於有耐心的人面前。', '在地獄火半島，特爾哈曼神廟的『智者』阿曼要你去夏納廢墟取得10個夏納聖物。', '', '去地獄火半島找塔哈瑪特神殿的智者阿曼恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9431, 'zhTW', '不同的方式', '辛多雷不在銀月城的大廳，反而建立在千針石林一座迎風的孤峰頂上幹嘛?$B$B很簡單。我的同胞將不再擁有我了。我之前寫過一本關於魔法癮之天然療法的論文，但是所有的書都被燒掉了。$B$B我可以在這裡安全地追求我的研究，但我的試劑用完了。如果你願意去石林西部盡頭附近的雷鳴岩石元素身上弄到淨化泥土，並送到白沙崗哨給我的同事，我會很感激。', '從雷鳴岩石元素身上收集2把淨化泥土並將它們帶給白沙崗哨的維茲羅·擦軸人。', '', '去千針石林找白沙崗哨的維茲羅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9432 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9432, 'zhTW', '前往阿斯特蘭納', '我很高興你來這裡幫忙。事實上，有件事你可以做。$B$B身為聯盟的一份子，我希望你可以前往夜精靈之城，阿斯特蘭納。它就在梣谷裡，卡林多大陸上，黑海岸南方的一座大森林。$B$B到達後請和復仇者帕賴斯談談，看看你能做什麼來幫助居民。', '前往梣谷的阿斯特蘭納並和復仇者帕賴斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9433 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9433, 'zhTW', '月井之水', '別再那樣看著我!我沒有說要派你帶著汲器和瓶子去薩蘭納爾空地裡的月井那裡!$B$B我一直，呃……在修補一個要送給客戶的產品。事實上，我已在薩蘭納爾附近設立好一個攜帶式的機器人控制臺。你要帶著這個控制裝置並在我隱藏的控制臺附近使用它。$B$B如果我的客戶聽到我把機器人從它的包裝裡移出來，他會夾住我的耳朵把我吊起來!', '到千針石林接近薩蘭納爾的邊境找到藏在小灌木叢裡的隱藏指揮控制臺，站在它附近使用機器人控制來操作機器人3000號。引導機器人到千針石林的西部邊緣，薩蘭納爾的聯盟前哨所在地。使用機器人來收集一個月井的水樣本再帶給白沙崗哨的維茲羅·擦軸人。', '', '去千針石林找白沙崗哨的維茲羅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9434 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9434, 'zhTW', '測試藥水', '<維茲羅從機器人那裡取回水樣本，將它和岩石元素泥土及其他幾個物品放在一個木箱裡。>$B$B好了，這就是博學者伊羅賽清單上所有的東西。告訴她和她合作很愉快，我祝她的研究順利。', '將試劑木箱送給亂風崗的博學者伊羅賽。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9435 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9435, 'zhTW', '遺失的水晶', '如果希爾斯布萊德有什麼很棒的事實，那就是那裡註定要活在戰爭的陰影之下。就連像一車的石頭這樣無害的東西都是目標。$B$B通常損失建築材料不是什麼了不起的挫敗，但最近從碧玉礦坑運來的貨物裡包含了一箱我急著要研究的稀有水晶。被遺忘者劫掠者攔截了那輛貨車，並把它開到東北方他們想重建的哨塔那裡。我們一定要立刻奪回那些水晶， $C !', '從被遺忘者那裡取回一箱稀有水晶並交給南海鎮的胡嵐。', '', '去希爾斯布萊德丘陵找南海鎮的忽爾蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9436 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9436, 'zhTW', '洞悉血頂習性', '你好，$c。我習慣在旅途中研究不同的食人妖部族的作戰技巧，而我發現了一個趨勢。北邊的伽什廢墟和巴拉爾廢墟的血頂食人妖和北邊森林的阿曼尼使用相同的策略。$B$B他們的魔法看來往一個有趣的方向分岐，而他們利用它成為區域裡最強大的部族。它可能形成一個對抗阿曼尼的強大武器核心，但首先我必須先多了解它。', '格羅姆高營地的奈米斯·鷹眼要你幫他從血頂薩滿身上帶來一個血頂圖騰。', '', '去荊棘谷找格羅姆高營地的納密斯·鷹眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9437 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9437, 'zhTW', '黎明行者的微光', '這裡的巨魔不只代表了粗野的笑話，酸澀的麥芽酒，和一次又一次的衝撞遊戲。當我的船，黎明行者擱淺時，那些從塞拉摩來的壞蛋偷走了我的貨物和最後生還的船員。我設法來到這裡尋找幫助，但那些無用的巨魔只是茫然的看著我說完我的故事。$B$B我需要一個可靠的$r之幫忙，去北點哨塔取回我剩下的貨物並釋放伊薩妮亞，他們就被扣留在東北邊。', '蕨牆村的巴藍達·亮星要你前往北點哨塔的塞拉摩軍隊中去取回黎明行者得貨物並救出他第一個同伴伊薩妮亞。', '', '去塵泥沼澤找蕨牆村的巴爾蘭達·新星。', '', '從北點哨塔營救伊薩妮亞', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9438 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9438, 'zhTW', '給索爾的消息', '自從我們來到外域後大酋長就一直在等這個消息。現在你有這個殊榮能親自告訴他瑪格哈的消息。$B$B快去吧，$n。帶著這封信;上面印有我個人的封印。沒有什麼消息比你帶去的更讓索爾想聽了。', '前往奧格瑪將來自納茲格雷爾的信交給索爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9439 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9439, 'zhTW', '無人的行李', '這裡是卡加斯?喔，天啊。我還以為是個，一個……呃，某種聚居地，在這個荒野裡某種文明的象徵。$B$B一定出了什麼錯;這個充滿粗野，骯髒，竊笑野蠻人的小屋不會是遠征軍的總部。當我告訴這些笨拙的野蠻人那些黑鐵矮人是如何搶劫我又消失在苦痛堡壘時，他們竟然厚顏無恥的笑我。我可以靠你幫我取回我的財產和尊嚴吧，可以嗎?', '從黑鐵矮人在苦痛堡壘的地盤取回諫言者的包裹和諫言者的細劍再還給卡加斯的諫言者·薩羅法斯。', '', '去荒蕪之地找卡加斯的顧問薩洛法斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9440 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9440, 'zhTW', '一點食物', '我在製作一個用來對付德萊尼的武器，我需要你的協助!$B$B失落者是德萊尼進化的前身，我一直在對他們做實驗。我要你去拿被邪惡汙染的食物去餵給他們所捕捉的家畜。然後當他們宰殺並吃了這些動物的同時，他們也會被詛咒!那會給避難營自負的隱士·艾弗恩一點顏色瞧瞧!$B$B現在就去吧，快!你可以在農田避難所東北方找到失落者和他們被關著的動物。', '將邪惡污染的食物餵給被失落者捕捉的動物。再帶著殘羹剩菜回到悲傷沼澤的斯通納德找瑟賽·幽歌者。', '', '去找悲傷沼澤的瑟爾希·暗歌。', '餵食被捕獲的鱷魚', '餵食被捕獲的沼澤虎', '餵食被捕獲的狼蛛', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9441, 'zhTW', '瑪格哈使者', '聽完你帶來的消息我這一刻真的很想起身前往外域。不過在杜洛塔這裡的重要事情仍需要我來處理。$B$B我會立刻安排一份適合的禮品送去給麥哈。我也會派我最信任的外交官前往。這全都需要時間……我需要某人到那裡代表我們。$B$B我一定要將我的信任託付給你，$n。前往地獄火的瑪格哈崗哨對我的族人提供所有你能做的協助。別讓我失望，$n。一切就靠這了。', '索爾要你回到地獄火半島的瑪格哈崗哨找葛坎·血拳並協助他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9442, 'zhTW', '削弱力量的疾病', '你願意幫助我們實在是太好了，$n。我們的蠻兵因為喝了污染的水而生病了，而我又找不著解毒劑的原料。我需要一種名叫乾頂的稀有磨菇。$B$B我們首先要做的是保持位置的隱密，且在尋找磨菇時別冒著被發現的危險，不然我寧可親自上陣。地獄火半島上唯一有乾頂磨菇的地方是在大裂縫的洞穴中，就在這邊的南方。$B$B如果你選擇去尋找，就得非常的小心。', '地獄火半島上瑪格哈崗哨的大地呼喚者瑞卡要你從大裂縫裡的洞穴帶1個乾頂磨菇給她。', '', '去地獄火半島找瑪格漢崗哨的喚地者利迦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9443, 'zhTW', '所謂的光明使者的印記', '我曾是烏瑟·光明使者的一個學生，他是白銀之手騎士團的創立者。我看過他如何粗暴地對待阿薩斯王子的訓練。那導致了我的家園，奎爾薩拉斯的毀滅，我把一切都歸因於烏瑟和他的無能!而現在他竟然還有自己光榮的墓碑 - 真是美好。$B$B我的資訊告訴我那些血色笨蛋把他的一個\'神聖\'的聖物放在他們壁爐谷附近的守衛哨塔頂端。$B$B去西瘟疫之地把它拿回來給我。', '取得光明使者記號再帶回西瘟疫之地的亡靈壁壘給瑪拉·曦刃。', '', '去找提裏斯法林地的瑪拉·曦刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9444 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9444, 'zhTW', '褻瀆烏瑟之墓', '這樣好多了。我加了一點邪惡魔法在裡面。$B$B現在，你一定要把它帶到他在西瘟疫之地的安息之處。在烏瑟的雕像前使用腐敗的神聖象徵來褻瀆他的墓碑!你要靠近一點才能讓它產生作用。$B$B要找到墓碑就到安多哈爾廢墟的東南方去。完成後再回來找我。$B$B動作快，$c!', '褻瀆烏瑟之墓再回到西瘟疫之地的亡靈壁壘找瑪拉·曦刃。', '', '去提里斯法林地找亡靈壁壘的麥拉·黎明之刃。', '褻瀆烏瑟爾之墓', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9445 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9445, 'zhTW', '佔地者:值得的禮物', '', '從壁爐谷入口附近的守衛哨塔頂端取得烏瑟的祝福，再帶給冰風崗的。', '', '去找。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9446 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9446, 'zhTW', '光明使者之墓', '既然你已取回光明使者的印記，剩下要做的就是把它帶回烏瑟之墓。$B$B你願意陪我一起去嗎?那裡不遠，我也喜歡你的陪伴。之後你可以回來這裡將經驗告訴高階牧師瑪多妮爾。$B$B你說怎麼樣，$n?', '護送隱士·楚恩到西瘟疫之地的烏瑟之墓。之後，再到西瘟疫之地的冰風營地和高階牧師瑪多妮爾談談。', '護送學者特盧恩轉至烏瑟爾之墓', '去西瘟疫之地找冰風崗的高階牧師瑪多妮爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9447 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9447, 'zhTW', '使用藥膏', '我用你帶給我的草藥準備了一種簡單的藥膏可以恢復我們蠻兵的力量。帶著它並將它使用在你看見的疲憊不堪的蠻兵身上。完成後回來找我。', '大地呼喚者瑞卡要你到地獄火半島的瑪格哈崗哨，對10個疲憊不堪的瑪格哈蠻兵使用治療藥膏。', '', '去地獄火半島找瑪格漢崗哨的喚地者利迦。', '治癒疲憊的瑪格漢步兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9448 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9448, 'zhTW', '憐憫被詛咒者', '我就知道!那個血精靈女巫，瑟賽·幽歌者，一直在詛咒失落者。我不知道原因也不知道方法為何，但結果就是悲慘。幾個失落者因為被更邪惡的力量所詛咒，所以現在已經更加嚴重的腐敗了!$B$B$c，你不覺得這些悲慘的生物很可憐嗎?他們不該在這樣可怕的狀態下過完一生。$B$B你可以在農田避難所找到這些被詛咒的失落者，在路的東邊。', '殺死3個被詛咒的失落者再回到悲傷沼澤的避難營找隱士·艾弗恩。', '', '去找悲傷沼澤的學者阿弗恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9449 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9449, 'zhTW', '召喚大地', '時候到了，$n。你已經成長到準備直接與這世界的元素之靈交流的階段了。$B$B但是先警告你。我可以感應到，我們進入這世界的方法和它不幸的副作用已激怒了大地之靈並造成元素的不平衡。$B$B如果你要製造你的大地圖騰，就必須先和安曼谷之靈談談。你可以在神聖樹林裡找到它，就在山丘的西北邊。', '到安曼谷的神聖樹林和安曼谷之靈談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9450 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9450, 'zhTW', '召喚大地', '元素的平衡已被山谷裡德萊尼的狂暴入侵給瓦解了。你們的失事讓大地的靈魂被激怒，還轉向其他來壓制他們的元素。你知道，了解元素只可能發生在和諧的狀態下。$B$B因此，尋求平衡就是你的責任了。在我身後的樹林裡有著不安的大地靈魂和其他三種元素鬥爭著。幫忙恢復平衡。', '殺死4個不安的大地元素再回到安曼谷的神聖樹林找安曼谷之靈。', '', '去藍謎島找元素聖谷的峽谷之靈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9451 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9451, 'zhTW', '召喚大地', '我現在要給你一塊我的實體讓你製造你的大地圖騰。把它交給送你來這裡的那個人。$B$B我和你就會永遠被綁在一起。你的一生都將可以支配大地的力量。等你的骨頭在生命結束後回到我們這裡它就會達到平衡。$B$B聰明地使用我們的力量。', '將大地水晶送到安曼谷給失事地點的法曼瓦。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9452 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9452, 'zhTW', '紅鯛魚 - 非常美味!', '我發現這些水裡充滿了活躍的紅鯛魚，一種非常美味的魚。只要有個捕魚網，我就能抓到足夠的魚來餵飽許多的德萊尼!不幸的是，我最近在河裡捕魚時被一種叫做魚人的生物攻擊，受了點傷無法進行我的工作。我需要幫忙!$B$B到東邊的水晶河川捕捉這種魚，記得在成群的紅鯛魚旁使用這個捕魚網。$B$B你說怎麼樣?完成後記得把魚網帶回來。', '使用德萊尼捕魚網捕捉10隻紅鯛魚。完成任務後將魚和網子帶回藍謎島給狄克泰納。', '', '去找蔚藍海岸島的狄克泰納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9453 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9453, 'zhTW', '找到艾克緹昂!', '你完成了一件很棒的工作，$N。我們的人民會很感激這次的餽贈。說到這，你可否將這些紅鯛魚送給藍色守望的艾克緹昂呢?$B$B他應該不難找因為他正在等著這批貨。', '送紅鯛魚木箱給藍色守望的艾克緹昂。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9454 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9454, 'zhTW', '牧月大獵殺', '你將讓自己成名了，$N。要不要試試打獵呢?$B$B從前在德拉諾，我們最厲害的獵人能獵捕一種稱為塔巴克的野獸，類似這裡的牧月成鹿。$B$B如果你認為自己夠德萊尼，就回去野外殺死夠多的成鹿，把你的背包裝滿肉塊。$B$B你可以在藍色守望南邊找到在吃草的他們。小心他們的角!', '帶6塊牧月成鹿嫩腰肉給藍色守望的艾克緹昂。', '', '去找蔚藍海岸島的艾克緹昂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9455 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9455, 'zhTW', '奇怪的發現', '你在小型夜間潛伏者身上發現的水晶看來是來自艾克索達的。這或許能解釋這區域某些動物不尋常的外表和行為。$B$B帶著水晶回到藍色守望。主教一定會想知道這個發現的。', '將微光水晶送給藍色守望的主教米奈奧斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9456 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9456, 'zhTW', '下一步……清除夜間潛伏者', '我不會為你的發現找任何的理由。這明顯的是我們的錯。我們獲報在東邊的河川裡有粉碎的水晶碎片但卻選擇忽視它的牽連。現在我們不是要坐著哭喊這座島上降臨的悲劇，就是要做點什麼來阻止它擴散。$B$B如果你有興趣的話，我要你回到野外殺死越多被感染的小型夜間潛伏者越好。', '藍色守望的主教米奈奧斯要你殺死8隻被感染的小型夜間潛伏者。', '', '去找蔚藍海岸島的主教米奈奧斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9457 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9457, 'zhTW', '稀有的庇護人', '所以這個奈亞斯就是這些血頂部族及他們奇特魔法的幕後主導?我必須承認，這是我的調查中最想不到的地方，但無論如何，我們的發現還是有用的。$B$B西北方的海岸有一座有著少數水元素的島。那裡有個可能是用來做為這類食人妖祭壇的原始石片。拿著你找到的這個圖騰到那個祭壇去。看看我們是不是能召喚出這個奈亞斯並淨化他的力量，讓它較為協調。', '在奈亞斯祭壇附近使用奈亞斯的禮物來召喚水元素奈亞斯。擊敗他再帶著奈亞斯的心回到格羅姆高營地的奈米斯·鷹眼那裡。', '', '去荊棘谷找格羅姆高營地的納密斯·鷹眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9458 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9458, 'zhTW', '<UNUSED>強化感官藥水', '', '', '', '去找希利蘇斯的遠征軍首席排程官恩克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9459 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9459, 'zhTW', '<UNUSED>Anti-crit Potion', '', '', '', '去找東瘟疫之地的高莫克大使。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9460 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9460, 'zhTW', '結合力量', '卡特斯·暗葉報告!$B$B喔……你是誰?如果你是為了我的報告而來，我堅持你要先幫我。$B$B我計畫要攻擊哨兵間諜，但我打算先派我忠誠的私語進入做為第一波攻擊。但她需要一點氣味才能找到他們。$B$B像你這樣的人一定可以溜進去偷走哨兵隊長身上的東西吧?', '卡特斯·暗葉要你從哨兵隊長身上扒走花邊手帕帶來給他。', '', '去找永歌森林的克爾圖斯·暗葉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9461, 'zhTW', '火焰的召喚', '你應該知道預言者在聽說你成功的通過試鍊後曾提起過你吧。不過你得先和他談過才能得到火焰圖騰。$B$B這可是珍貴的殊榮喔;你得馬上到艾克索達去見他!', '到艾克索達的聖光地窖尋找預言者費倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9462 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9462, 'zhTW', '火焰的召喚', '$n!是時候讓你接受靈魂更深入的訓練了。你要去找塔奴藍，一個藍色守望的薩滿。他可以引導你了解並駕馭火焰的力量。', '到藍謎島和藍色守望的塔奴藍談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9463 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9463, 'zhTW', '醫療用途', '我發現島上亂竄的鞭笞者藤蔓裡有一種復原的藥效特性。透過適宜的處理，藤蔓可以做成一種強大的治療藥膏。不幸的是，有那麼多受傷的德萊尼路過藍色守望，我們總是物資不足。$B$B我們嬌弱的客人昨天在水晶河川旁被發現，受了傷又意識不清。如果你可以幫我把藤蔓帶來，我們就能救她。$B$B你可以在藍色守望的南方和東方找到根鬚捕獸者。', '藍色守望的隱士·法禔瑪要你幫她帶來8個根鬚捕獸者藤蔓。', '', '去找蔚藍海岸島的隱士‧法禔瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9464 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9464, 'zhTW', '火焰的召喚', '你再一次地要被試煉，而你如果想創造一個圖騰來駕馭火焰元素的能量，就一定要理解這次的混亂。$B$B東北邊海岸有一個神聖的火焰之地叫餘燼林地。暴躁者就在它被燃燒的樹中，他是一個有著強大力量的火焰元素，你一定要和他談談。$B$B現在就去找他，願艾澤拉斯的元素之靈跟隨著你。', '到藍謎島和餘燼林地的暴躁者談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9465 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9465, 'zhTW', '火焰的召喚', '我有一個叫郝特的同胞發瘋了，無疑是因為你的船失事的緣故。他開始要求當地的梟獸崇拜他。$B$B這不能繼續下去!我們不能有人假扮成神祇!恢復平衡是你的責任。$B$B首先，你一定要取得他們的儀式火炬，它被瘋狂的梟獸帶到西邊的靜松要塞裡了。$B$B把火炬帶回來給我。', '取回儀式火炬並帶回藍謎島給餘燼林地的暴躁者。', '', '去藍謎島找灰燼林地的坦普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9466 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9466, 'zhTW', '懸賞:『野蠻者』黑爪', '遊俠隊長下令，懸賞邪惡的岩石鐮奪怪女王『野蠻者』黑爪。$B$B最近一次有人看到『野蠻者』黑爪是在大裂縫的洞穴裡。想得到獎賞就把她的爪子帶來以證明你做到了。', '為地獄火半島獵鷹哨站的遊俠隊長范瑞帶來黑爪之爪。', '', '去地獄火半島找獵鷹崗哨的遊俠隊長維恩雷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9467 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9467, 'zhTW', '火焰的召喚', '遠在西南邊的銀謎小島裡，月翼獸窟的梟獸受到迷惑，錯把郝特當成他們的神祇來崇拜。而事實上他是一個需要從自身的悲慘中解脫的墮落元素。那個火炬就是他覆滅的關鍵。$B$B郝特通常命令這些梟獸以燃燒肖像來榮耀他。因此，當你將它點燃，他就會出現了。殺了他並將他的骨骸帶來給我。然後使用我給你的背包中的寶珠回來我這。', '取得郝特的骨骸並將它們和儀式火炬一起帶回藍謎島給餘燼林地的暴躁者。記得你拿到骨骸後就可以使用歸返寶珠傳送回暴躁者那裡。', '', '去藍謎島找灰燼林地的坦普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9468 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9468, 'zhTW', '火焰的召喚', '在探究你自己與火焰的關係這件事上，你今天做得非常好。記得永遠要用最大的尊敬來對待它以免被燒傷。$B$B我幫你留了一些郝特的骨骸。在製造你的火焰圖騰時使用它們並記住所有你所學到的。$B$B現在回去找塔奴藍吧。', '將郝特的骨骸送到藍謎島給藍色守望的塔奴藍。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9469 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9469, 'zhTW', '羽鬚的背書', '在我最後決定謁見弗斯塔德·蠻錘時，我希望有我們在蠻錘矮人中最有力的擁護者在我身邊，$n。$B$B羽鬚受到他的人民的愛戴，是因為他那傳奇的獅鷲獸訓練技巧及他的聰明才智。如果有任何人可以影響弗斯塔德·蠻錘的話，那一定是他。$B$B我很想親自去見他，但是我在等候覲見蠻鬚時無法離開鷹巢山區域。去南方羽鬚的住處拜訪他並詢問他是否願意與我談談。', '前往羽鬚小屋，如果矮人在家的話就拜訪他。如果他不在，就看看有沒有他的線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9470 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9470, 'zhTW', '展示好意', '辛特蘭高低不平的地形不僅是蠻錘矮人和他們獅鷲獸的家園，也是許多森林食人妖部族的家園。$B$B食人妖將蠻錘視為他們先祖之地上的不速之客，把握每個機會攻擊獅鷲獸的巢穴來挑戰矮人。想向蠻錘證明我們自己的價值，就要幫忙平息這些攻擊，殺掉枯木領導者，巫醫·梅金，他住在伯根的棚屋的一個洞穴裡，就在沙德拉洛西邊。', '鷹巢山的洛勒斯大使要你去殺掉巫醫·梅金以及他的蜘蛛寵物恰克斯。', '', '去辛特蘭找鷹巢山的魯雷斯大使。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9471 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9471, 'zhTW', '捕食掠奪者', '蠻錘矮人是獅鷲獸的同伴、照顧者、也是訓練師。獅鷲獸向來不缺敵人，尤其是在森林食人妖的部族中。$B$B不過，有時候，威脅也會來自大自然的掠奪者，像是狼群。一隻動物不是一隻獅鷲獸的對手，但他們通常會一群群的鎖定獅鷲獸，因為普通的獵物很稀少。刪減狼群的數量可以降低他們對獅鷲獸的衝擊，也能讓我們贏得蠻錘的歡心。', '鷹巢山的洛勒斯大使要你殺死10隻癩皮銀鬃狼和5隻銀鬃狼。', '', '去辛特蘭找鷹巢山的魯雷斯大使。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9472 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9472, 'zhTW', '阿利恩的情婦', '阿利恩手邊有那麼多重要的事但他還是擠出時間來見情婦!$B$B這一切都很明朗了。薇艾拉·陽語，那個骯髒的蕩婦……我們要讓她知道永遠不要再招惹博學者。$B$B帶著這個卷軸去找薇艾拉。想辦法引誘她到城外再對她使用卷軸。$B$B阿利恩提過她無法抗拒塞納里奧德魯伊的一種酒。你可以在西邊的塞納里奧避難所找到一些，在贊格沼澤裡面。', '獵鷹哨站的博學者卡莉達要你引誘薇艾拉·陽語離開居住地再對她使用卡莉達的懲罰卷軸。', '', '去地獄火半島找獵鷹崗哨的魔導師卡爾琳達。', '使用卡爾琳達的懲戒卷軸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9473 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9473, 'zhTW', '替代的選擇', '這女孩為了讓藥膏發揮效用已做了太多努力。或許有別的辦法……$B$B藍謎島森林有許多秘密，其中一個就是一種叫藍色金魚藻的稀有植物，有些人說它是萬靈丹 - 治療所有疾病的解藥。$B$B你可以從它和藍謎島其他植物明顯的對比以及它需要藍色松樹為基底來生長的特性辨視它。動作快!$B$B還有$N，小心那裡的盤根痛擊者因為它們以食用金魚藻維生。', '藍色守望的爹達歐要你幫他帶來5個藍色金魚藻球莖。', '', '去找蔚藍海岸島的狄戴爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9474 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9474, 'zhTW', '光明使者的印記', '我在艾澤拉斯短暫的時間裡已經認識了許多它的英雄。其中的烏瑟·光明使者是最出色的。烏瑟是幾世代的英雄，最後被他最有前途的學徒，阿薩斯背叛。$B$B為向他致敬，我想要回一些他遺留在附近墓碑的物品。據說他有一個神聖的聖物在血色十字軍那裡，放在他們的守衛哨塔頂端，靠近壁爐谷的入口。$B$B拜託你，$c，去把它拿回來。', '取得光明使者的印記帶回西瘟疫之地交給冰風營地的隱士·楚恩。', '', '去西瘟疫之地找冰風崗的學者特盧恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9475 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9475, 'zhTW', '取回那些蛋', '仔細檢查遺體，你猜測這具破碎憔悴的骷髏一定是羽鬚僅剩的全部。其中一隻骷髏的手裡握著一捆撕裂，有髒污的紙。你小心地拿走並將它打開，看到了一個手繪的地圖和一些倉促寫下的筆記。$B$B地圖看來是在描繪沙德拉洛和它標示了「x」記號的三座神廟，可能是被偷走的蛋的位置。你將地圖放進你的背包到安全一點的地方檢視。', '收集5顆獅鷲獸的蛋帶回去給鷹巢山的洛勒斯大使。', '', '去辛特蘭找鷹巢山的魯雷斯大使。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9476 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9476, 'zhTW', '追蹤羽鬚', '最近幾篇日記都詳細寫著枯木食人妖對蠻錘獅鷲住所不斷遭到突襲和一連串的偷蛋事件讓羽鬚感到憂心。一次搜尋小型枯木聚集地的行動似乎也沒有成果。$B$B最後一篇描述了羽鬚懷疑一個叫梅金的枯木巫醫是策劃突襲的人。最後，倉促的寫下了一個句子表示這個矮人想前往沙德拉洛尋找蛋的意圖。', '前往沙德拉洛尋找羽鬚的蹤跡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9477 AND `locale` = 'zhTW';
