INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9483, 'zhTW', '生命中更棒的樂趣', '', '', '', '去地獄火半島找獵鷹崗哨的薇拉·火語。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9484, 'zhTW', '馴服野獸', '為了防禦和生計，你可以毫無疑問地獵捕並殺死野獸，但是要和他們做朋友並駕馭他們的力量就要看你怎麼掌握了。這是我能教你的。$B$B拿著這個魔法的馴獸棒讓一隻野生動物暫時和你結為朋友並一起作戰。從瘋狂的龍鷹開始，一隻容易駕馭的鳥類，就在遠行者居所外。完成後回到我這裡。', '用馴獸棒來馴服瘋狂的龍鷹，然後再回到晨奔中尉那裡。', '馴服一隻瘋狂的龍鷹', '去永歌森林找遠行者居所的達恩·晨行者中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9485 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9485, 'zhTW', '馴服野獸', '你做的很好，$n。你對野外的了解迅速增長。$B$B迷霧蝙蝠是聰明的獵人，結合了龍鷹的敏捷和泉爪山貓的兇殘。他們就在南方越過艾蘭達之河的地方，捕食從路上閒晃過去的不幸旅人。$B$B使用這個最後的馴獸棒來和迷霧蝙蝠做朋友，完成後再來找我。', '用馴獸棒來馴服迷霧蝙蝠，然後再回到晨奔中尉那裡。', '馴服一隻迷霧蝠', '去永歌森林找遠行者居所的達恩·晨行者中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9486, 'zhTW', '馴服野獸', '年長的泉爪山貓是有效率又敏捷的獵人。若想和它做朋友，它會先將你視為獵物。別被逼退了。$B$B用馴獸棒讓那隻大獵豹和你站在同一陣線並和它一起打獵。他們就在永歌森林裡，有些會和小屋非常靠近。等你學了夠多再回來找我。', '用馴獸棒來馴服年長的泉爪山貓，然後再回到晨奔中尉那裡。', '馴服一隻老魔泉豹', '去永歌森林找遠行者居所的達恩·晨行者中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9487, 'zhTW', '秘法搶奪者', '秘法搶奪者是有著野蠻力量的魔法生物。他們有著厚重的護甲並且可以使用暈眩打擊。但是，你，卻可以繞過他們的防衛避開他們的攻擊。你的法術技能有許多優勢，$n。$B$B前往晨星尖塔擊潰那些秘法搶奪者。從他們的遺體中收集有魔法能量的晶化碎片給我。晨星尖塔就在東邊越過湖的地方。', '秘法師范德隆要你收集10個秘法碎片給他。', '', '去鬼魂之地找塔奎林的奧術師範迪瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9488, 'zhTW', '一件簡單的長袍', '你收集的秘法碎片非常適合。$B$B適合什麼，你問適合什麼嗎?適合製作極好的長袍給像你一樣的$c!$B$B我們現在所需要的是一些亞麻布和細網絲囊。你可以在任何細網蜘蛛身上找到絲囊，最好是在殺了他們之後。', '秘法師范德隆要你幫他帶來15塊亞麻布和一個細網絲囊。', '', '去鬼魂之地找塔奎林的奧術師範迪瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9489, 'zhTW', '淨化斷崖', '$n，你在這裡真好。天譴軍團帶著無盡的恨意攻擊我們的城市，我擔心我們守衛的士氣就要被擊破了。$B$B快點前往南方的死亡之痕，潔拉和她的遊俠已經在那裡準備好了。用你的祝福讓他們充滿聖光的力量。', '對死亡之痕的6個永歌森林遊俠施放真言術:韌。', '', '去永歌森林找鷹翼廣場的珀納瑞斯。', '祝福永歌遊俠', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9490 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9490, 'zhTW', '岩石鐮奪怪女王', '岩石鐮奪怪是壞心，卑鄙，又暴力的生物。不過和他們的女王，『野蠻者』黑爪比起來，一般的鐮奪怪就是溫馴的野獸了。$B$B她吃掉了我的表弟，那場景很可怕。我發誓有一天黑爪會為此付出代價。你帶回那個怪物死亡的證據我就會把一生的積蓄都給你。就這麼說定了?$B$B你將需要一些朋友幫忙才能殺掉黑爪。有銳利長劍的朋友。你可以在大裂縫的洞穴裡找到她。祝好運!', '從大裂縫的『野蠻者』黑爪身上取得黑爪之爪，將它帶回地獄火半島給特爾哈曼神廟的依坎。', '', '去地獄火半島找塔哈瑪特神殿的伊坎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9491 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9491, 'zhTW', '貪婪', '一個富有的商人，我指的是骯髒的富有，昨天來這裡說一個有著「極大考古重要性」的戒指被鎖在阿曼尼地下墓穴無數的埋葬箱之一裡。當他不談戒指的事時，他就在說他會為那個戒指付多少錢。$B$B告訴你，我來幫你掩飾盜賊的工具，如果你能幫我帶回戒指，我會付你買十個戒指的錢!', '安寧地的依蘭兒要你從阿曼尼地下墓穴取回缺口金指環。', '', '去鬼魂之地找塔奎林的艾拉蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9492 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9492, 'zhTW', '扭轉情勢', '獸人永久的威脅是外域的傷心事實之一。我們洛薩之子曾經相信我們會用自己的血換得榮譽堡的安全，但那會沒有和平。$B$B洛薩之子不會對任何獸人妥協 - 不管他們是綠色，咖啡色，還是現在的紅色 - 我們會征服他們或拼死抵抗。如果我們要期望勝利，就要去地獄火堡壘與他們殊死一戰。幫我把他們自稱「大酋長」卡加斯·刃拳的武器帶來你就能獲得獎勵。', '把大酋長卡加斯之手帶給榮譽堡的軍隊指揮者達納斯·托爾貝恩。', '', '轉至地獄火半島，去找榮耀堡的遠征軍指揮官達納斯·托爾貝恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9493 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9493, 'zhTW', '魔獄部落的驕傲', '我們對地獄火堡壘的魔獄部落了解很少，而我們也犧牲掉很多性命才得來這些資訊。$B$B卡加斯·刃拳指揮的魔獄部落軍隊受邪惡魔法加持，野蠻又身經百戰。這支軍隊的精英---破碎之手軍團士兵、勇士和百夫長都以軍官身份效命，並且令魔獄部落的正規兵畏懼。$B$B找到並消滅他們是成功突襲魔獄部落領導者必要的第一步。', '榮譽堡的戰場元帥洛摩斯要你殺死8個破碎之手軍團士兵，4個破碎之手百夫長，和4個破碎之手勇士。', '', '轉至地獄火半島，去找榮耀堡的戰地指揮官洛姆斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9494 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9494, 'zhTW', '魔化餘燼', '艾澤拉斯古板的學術已經蜷縮在他們的哨塔裡太久了，現在我該讓他們見識一下最前線的研究!他們不敢玩火而那正是我要做的，一旦我把手放到火上，那就是了。$B$B在地獄火堡壘的破碎大廳裡，大術士·奈德克斯掌控著無與倫比的魔法技藝，那是由一對奇異的火盆所累積的力量。使用他用的容器來盛裝這些魔化餘燼，抓住一個帶回來給我，$n。', '榮譽堡的魔導師薩柏瑞希斯要你幫她帶來一份魔化餘燼。', '', '轉至地獄火半島，去找榮耀堡的大法師薩布蘭希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9495 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9495, 'zhTW', '酋長的希望', '要釋放那些受汙染的獸人並不容易，$n。大酋長索爾見過太多獸人英雄被命運的手給擺平。現在，看來卡加斯·刃拳也算是他們的一員。$B$B在地獄火堡壘的破碎大廳裡，卡加斯以魔獄部落的「大酋長」稱號自居。有一批瘋狂嗜血的魔獄獸人為他撐腰，除非索爾瑪被摧毀否則他不會善罷干休。大酋長索爾命令我們不惜一切代價擊敗卡加斯和他的軍隊。', '把大酋長卡加斯之手帶給索爾瑪的納茲格雷爾。', '', '轉至地獄火半島，去找索爾瑪的納茲格雷爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9496 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9496, 'zhTW', '魔獄部落的驕傲', '把殘拳霸主的羞辱先放一旁，$n，這個魔獄部落不是省油的燈。$B$B據我們所知，卡加斯·刃拳指揮的魔獄部落軍隊受邪惡魔法加持，野蠻又身經百戰。這支軍隊的精英---碎手軍團士兵、勇士和百夫長都以軍官身份效命，並且令魔獄部落的正規兵畏懼。$B$B找到並消滅他們是成功突襲魔獄部落領導者必要的第一步。', '索爾瑪的影子獵人泰巾要你殺死8個破碎之手軍團士兵，4個破碎之手百夫長，和4個破碎之手勇士。', '', '轉至地獄火半島，去找索爾瑪的暗影獵手塔金。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9497 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9497, 'zhTW', '邪部落的象徵', '自所謂的“邪部落”這個詞傳入酋長的耳中開始，他就徹底陷入了巨大的憤怒與悲愴之中。正如當初雷德·黑手所率領的那個偽部落一樣，這個本不應存在的部落也必定滅亡。他們的旗幟將被掛在在格羅瑪什要塞的城牆上示眾，以昭示酋長的力量。$B$B執行酋長意志這一光榮的任務，就落在你的肩膀上了，$N。這不是一個簡單的任務，那面旗幟被一個邪部落的勇士保護著，聽說他名叫戰爭使者沃姆羅格。顯然，你需要殺死他才能搶到旗幟。', '殺死戰爭使者沃姆羅格，並奪得邪部落軍旗，然後把它交給索爾瑪的大督軍霍恩·重拳。', '', '去地獄火半島找機甲殘骸的大督軍霍恩·重拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9498 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9498, 'zhTW', '獵鷹哨站', '我的族人最近完成了建築獵鷹哨站的工作，那是在地獄火半島西南方，地獄火堡壘後方的一個運作基地。歡迎你到那裡做我們的盟友，$n。$B$B如果你在找工作，就去那裡告訴遊俠隊長范瑞是我派你來的。他會給你一些適合你程度的任務。', '到地獄火半島向獵鷹哨站的遊俠隊長范瑞報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9499 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9499, 'zhTW', '獵鷹哨站', '你還在這幹嘛，$n?你沒聽說我們在地獄火半島建了一個很棒的辛多雷前哨站嗎?$B$B你當然寧願和血精靈同伴在一起，遠離這一切的……氣味。你可以在西南方找到獵鷹哨站，就在地獄火堡壘後方。向遊俠隊長范瑞回報;他會照顧你的。$B$B前方的路很危險，還有聯盟斥候重重戒備。我建議你找一些同伴一起前往。最好是血精靈。', '前往地獄火半島西南方的獵鷹哨站並向遊俠隊長范瑞報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9500, 'zhTW', '水之召喚', '距離上次你接受測試已經有好一陣子的時間了。先知諾柏多一直問起你。你一定增長了很多智慧才會被徵召來學習水元素的秘密。$B$B你記得在艾克索達內水晶大廳的何處能找到他吧?', '與藍謎島中艾克索達裡水晶大廳的先知諾柏多談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9501, 'zhTW', '水之召喚', '一個叫阿基歐斯的強大水元素要求見你一面。看來血謎島的水元素出現了極大的不平衡。因為有血精靈這樣不尋常的嗜好我並不驚訝。$B$B血謎島北方海岸的海浪下有一個隱秘的沙洲，你可以在那裡找到阿基歐斯。$B$B帶著這瓶藥水;等你進到水裡，靠近沙洲時，它可以幫你找到她。', '到血謎島的隱秘沙洲和阿基歐斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9502, 'zhTW', '水之召喚', '距離上次你接受測試已經有好一陣子的時間了。先知諾柏多一直問起你。你一定增長了很多智慧才會被徵召來學習水元素的秘密。$B$B你記得在艾克索達內水晶大廳的何處能找到他吧?', '與藍謎島中艾克索達裡水晶大廳的先知諾柏多談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9503, 'zhTW', '水之召喚', '和其他的元素平衡，水是所有生物的根源和支柱。它賦予並滋養生命，所有的生命都仰賴它才能存在。但是，當它被汙染了，它同時也讓生命結束。$B$B我們一定要終止傷害繼續造成。西南邊就有這樣受汙染的水源叫做邪惡池塘。前往那裡，從住在池塘的水之靈身上抽取邪惡精華。', '收集6份腐敗精華再帶回血謎島給隱秘沙洲的阿基歐斯。', '', '去秘血島找藏帆暗礁的阿奎歐斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9504, 'zhTW', '水之召喚', '這比我擔心的還要糟。汙染非常嚴重，如果未經管束它就會散播到洋流裡然後帶到整個艾澤拉斯!$B$B我們需要一個最純淨的水樣本來對照惡性的。附近的卡林多大陸上有座森林叫做梣谷。靠近它的西南方邊界有一個叫星塵廢墟的地方。$B$B帶著這個皮製水袋到那個廢墟中心的小月臺上，裝滿噴水池的水。快，$n!', '裝滿空皮製水袋再回到血謎島的隱秘沙洲找阿基歐斯。', '', '去秘血島找藏帆暗礁的阿奎歐斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9505, 'zhTW', '費倫的預言', '預言提到了今天:在這座島上，在這個新世界裡，我們的盟友會找到我們。「我們會被測試。他們會要求我們為我們的父親贖罪……」那時候，我並不了解他字句背後的意思，但看到這個生物和她對我們的反應，現在一切都逐漸明朗了。我們族人的腐敗被認為是對等的。前往南方。我們是在那裡找到這個生物的。找到它的族人並告訴他們關於我們族人的事。', '爹達歐要你前往南方找到受傷的生物提到的人們。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9506, 'zhTW', '一個小開始', '我是聯盟海軍指揮的艦隊司令·奧迪席斯。我們的船被迫停靠在你們島旁是因為碰到了某種族對我們的侵擾。要開口談這件事真尷尬，但哥布林不知怎地躲藏在我的兩艘船上偷渡來此。$B$B昨天夜裡，當大部分船員都在船艙裡睡覺時，我們就遭到突擊了!$B$B更奇怪的是，他們拿走了我們的航海工具就跳船了!$B$B他們消失在東邊的樹叢中。你可以去幫我們找回工具嗎?這對我們而言很重要。', '奧迪席斯平臺的艦隊司令·奧迪席斯要你取回被風險投資公司偷走的航海指南針和航海地圖。', '', '去找蔚藍海岸島的艦隊司令‧奧迪席斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9507 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9507, 'zhTW', '從摩戈·瑞茲當克的桌上拿的', '根據這些計劃書，哥布林是為了艾克索達的水晶殘骸而來的。看來哥布林想挖光島上的水晶並在完成任務後劫走兩架停靠在海岸上的聯盟船隻。$B$B你該把這些計劃書帶給艦隊司令·奧迪席斯。', '將最高機密風險投資公司計劃帶給奧迪席斯平臺的艦隊司令·奧迪席斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9508 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9508, 'zhTW', '水之召喚', '我已經確定汙染的來源了。那是一些瘋狂研究的副產品，而你將要去結束它!$B$B西南方的邪惡池塘是一個小營地。你會在那裡找到『不淨者』泰拉希恩的「研究」。他在那裡製造污物並滲入了島上的水源。$B$B使用你從梣谷取得的純水來摧毀他好幾桶的儲藏物。那一定會把他引出來。$B$B我們會結束這一切!', '把泰阿希恩的頭顱帶到血謎島給隱秘沙洲的阿基歐斯。', '', '去秘血島找藏帆暗礁的阿奎歐斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9509 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9509, 'zhTW', '水之召喚', '我保留了一點梣谷的水，不是因為我質疑你處理情況的能力。而是，我知道你會成功，所以我想確保你可以帶點特別的東西回去給諾柏多。$B$B來，$n，拿著這瓶純水。它會確保你得到一個非常強大的水圖騰。$B$B先知諾柏多等著你回去艾克索達。', '把純淨水瓶帶回藍謎島給艾克索達的先知諾柏多。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9510, 'zhTW', '刺毛裂蹄獸皮', '那你是想知道能幫上什麼忙了？現在我們的clefthoof hides供貨緊缺，$N。$B$B如果你去西南邊，會發現獵鷹崗哨附近有許多bristlehide clefthoof。他們的皮是皮革製作最佳的材料。幫我找一堆clefthoof hides回來，我會給你應得的獎賞。', '地獄火半島瑪格漢崗哨的Provisioner Braknar讓你給他帶回5張Bristlehide Clefthoof Hides。', '', '去地獄火半島找瑪格漢臺地的供給官布拉克納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9511, 'zhTW', '卡加斯的戰鬥計劃書', '你在卡加斯身上找到的檔案看來是對榮耀堡大型入侵的細節計劃書。', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9512, 'zhTW', '廚師的特大燴肉', '艦長是對的，你是個聰明的傢伙。也許你可以幫廚師的忙?$B$B要是我再讓船員吃雞肉，我一定會被送到禁閉室的。$B$B我注意到沿著海岸線一路都有爬行者 - 多著呢!幫我帶點爬行者的肉來，我會永遠感激不盡的。$B$B幫改過自新的海賊一個忙吧?', '奧迪席斯平臺的『小廚』麥克威醬要你幫他帶來6塊滑膩的爬行者肉。', '', '去找蔚藍海岸島的『小廚』麥克威醬。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9513 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9513, 'zhTW', '奪回廢墟', '雖然有些人認為我們現在的處境是不幸的事，但我感覺我們來到這裡是有原因的。命運無形的手把我們推向這個方向。原因會隨著時間而明朗。$B$B西邊是古老的夜精靈城市，現在是個佈滿納迦的廢墟。如果納迦汙染了我的先祖之地，而我只是閒坐在一旁，那就是我的疏失了。 $B$B你已證明你是個能幹的$c了。讓我的族人感到光榮，清除掉廢墟裡他們不歡迎的居民。', '藍謎島，奧迪席斯平臺的女牧師凱玲·伊丹奈爾要你殺死5個怒鱗侍從、5個怒鱗納迦和5個怒鱗海妖。', '', '去找蔚藍海岸島的女牧師凱玲‧伊丹奈爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9514 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9514, 'zhTW', '符文雕飾石板', '你辨別不出這石板上的任何符號。或許女祭司可以解讀這些神秘的符文。', '把符文雕飾石板帶到藍謎島給奧迪席斯平臺的女牧師凱玲·伊丹奈爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9515 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9515, 'zhTW', '督軍司瑞史提斯', '納迦入侵會是一場災難，$N。我見過納迦的本事，我不想見到這樣的大災難降臨在任何生物身上。如果要我猜，這個督軍司瑞史提斯會躲在洞穴裡 - 或許是在西邊的海岸上。$B$B找到督軍司瑞史提斯並結束他的統治。', '藍謎島，奧迪席斯平臺的女牧師凱玲·伊丹奈爾要你殺了督軍司瑞史提斯。', '', '去找蔚藍海岸島的女牧師凱玲‧伊丹奈爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9516 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9516, 'zhTW', '摧毀軍團', '我不能容忍他們活在這世界上!燃燒軍團摧毀了我們的種族，迫使我們到新世界建立新家園。然後他們又一次一次的出現，我們只能一再撤退。$B$B夠了!$B$B在冥火嶺，屠魔峽谷，和屠魔山南方的區域有一群燃燒軍團的餘孽。他們是過去燃燒軍團入侵這世界時所遺留下來的。$B$B趁還來的及的時候把他們盡量殺光!', '殺死6個瑪諾洛克鞭笞者，6個惡魔守衛，和6個灼熱的地獄火，再回到梣谷的林歌神殿找復仇者維達。', '', '去梣谷找林歌神殿的守備官維達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9517 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9517, 'zhTW', '可恥的浪費', '歡迎來到林歌神殿，$c。你現在看到的帳篷，就是將來會蓋建築物的地方，但這樣的目標需要穩定的建築材料來源。我不能讓我的工人砍伐樹林裡的任何老樹，但我們在南方和西方的鄰居對森林就沒有這樣的敬畏了。$B$B我們將盜取戰歌伐木工砍伐的木材，從西邊的薩特要塞取回一些受汙染的木材。把木頭帶給格納，他會淨化它們以做使用。', '帶15塊戰歌林材和5塊薩提納爾地獄木頭給林歌神殿的格納。', '', '去梣谷找戰歌伐木營地的納亞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9518, 'zhTW', '毀滅間諜', '戰歌伐木營地是使這片土地陷入備戰狀態的禍端。每當我們阻止他們的運作有所進展時，監督者高薩克就會命令他的伐木工加倍努力!$B$B現在，獸人砍的木材比他們會用到的還多，當他們的刀身砍進新的樹時，那些木頭就留在那裡腐爛!這對我們而言是公然的侮辱， $N ，我們要讓他們知道我們不會讓土地受到更多的毀滅!$B$B去吧，監督者高薩克和他的爪牙死掉之前都不要歇息!', '林歌神殿的哨兵露西歐·星語要你摧毀監督者高薩克，2個戰歌伐木機，5個部落伐木工，和10個部落斥候。', '', '去梣谷找林歌神殿的哨兵盧希爾·星語。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9519 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9519, 'zhTW', '丟失的酒杯', '我們西邊的地方現在叫做薩提納爾，它曾是我的族人建立的重要神殿。那裡面有一個無價的聖物，伊露恩酒杯，是伊露恩的祭司委託神殿守衛保管的。朝聖者曾前往神殿體驗酒杯傳說中的治療能量。$B$B這些故事或許只是無稽之談，但如果它們有任何一點真實性，那個聖物就可能讓受傷的森林恢復過來。我一定要知道真相， $N 。', '把伊露恩酒杯帶給林歌神殿的凱尼斯·靜風。', '', '去梣谷找林歌神殿的凱尼斯·靜風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9520 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9520, 'zhTW', '殘忍計畫', '惡魔掉了這張羊皮紙，驚人的是它竟然是用普通語寫的!裡面提到的人，迪亞索魯斯和戈甘諾恩，是兩個聲名狼籍的恐懼領主，控制著附近的惡魔。$B$B羊皮紙上詳細描述了惡魔要攻擊北方林歌神殿的準備細節;那裡正在建立新的德萊尼聚集地。$B$B或許林歌神殿的復仇者維達會對這些很有興趣?', '將殘忍計畫送到梣谷給林歌神殿的復仇者維達。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9521, 'zhTW', '北方前線的報告', '對抗戰歌伐木營地的戰役不單是從林歌神殿展開，$N。西南邊的銀翼樹林還有更多的銀翼哨兵，靠近貧瘠之地的邊界。在樹林那，哨兵輕歌指揮我們抵抗那些想摧毀我們土地的人。$B$B我現在把最新的報告送過去給哨兵輕歌已經有點太晚了，而且也猶豫是否要獨自離開林歌神殿。如果你的旅程會經過銀翼樹林附近，你願意幫我遞送報告嗎?', '將哨兵露西歐·星語的報告送給銀翼樹林的哨兵輕歌。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9522 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9522, 'zhTW', '永遠沒有下一次!', '$n，你要讓燃燒軍團的攻擊永遠都不會成真。你一定要去殺了他們的領導者。沒有他們，剩下的惡魔也只是無腦的蠢蛋而已。$B$B你要去冥火嶺更遠的南方，靠近曼諾洛斯的飄浮斷矛附近找到屠魔峽谷裡的戈甘諾恩。$B$B『追尋者』迪亞索魯斯就住在屠魔山上的獸穴裡。要找到那座山，就到部落的葛羅·地獄吼紀念碑旁，在屠魔峽谷上找一個斜坡。', '殺了戈甘諾恩和『追尋者』迪亞索魯斯，再回到梣谷的林歌神殿找復仇者維達。', '', '去梣谷找林歌神殿的守備官維達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9523 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9523, 'zhTW', '小心輕放', '女祭司告訴我西邊的廢墟是夜精靈文明唯一遺留下來的產物。那讓我想起我爸爸總是這樣說夜精靈廢墟，「兒子，當你看見夜精靈廢墟時，夜精靈的聖物肯定就在附近。」$B$B如果我不僱用我第一個看到的人去挖出夜精靈聖物給我，那我還算是什麼矮人?現在快去吧!', '藍謎島，奧迪席斯平臺的考古學家阿達曼·鐵心要你幫他帶來8個古代聖物。', '', '去找蔚藍海岸島的考古學家阿達曼‧鐵心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9524 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9524, 'zhTW', '監禁堡壘', '聯盟，這裡?聽清楚了，$c。$B$B卡加斯抓走了我的幾個士兵。一個重要的官員，隊長阿蓮娜也在裡面。你一定要試著在她被處決前搶救她。$B$B別擔心我，等我喘口氣就會想辦法出去的。', '在地獄火堡壘的隊長阿蓮娜被處決前拯救她。這個任務只能在英雄難度副本中完成。', '', '去地獄火半島找地獄火堡壘的奧琳娜上尉。', '營救奧琳娜上尉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9525 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9525, 'zhTW', '堡壘中的囚徒', '我剛剛從卡加斯的監獄中活著逃了出來，$N。還有幾個其它俘虜今天就要被處決了，一位重要的軍官也在其中。$B$B如果這位沙塔·碎骨上尉被殺的話，將給我們帶來很大的損失。你一定要想盡一切辦法把他救出來。我……我恐怕難以繼續前進了……', '在地獄火堡壘內的沙塔·碎骨上尉被處決前救出他。$B$B該任務必須在英雄等級難度的地下城中完成。', '', '去地獄火半島找地獄火堡壘的沙塔·碎骨上尉。', '營救沙塔·碎骨上尉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9526 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9526, 'zhTW', '奪回冥火嶺', '小傢伙，南方的夜歌森林有一個區域，最近被稱為冥火嶺。糟糕的是，那邊已經被惡魔佔據著，並腐蝕著那塊土地。$B$B你能做些什麼來幫忙奪回這片地嗎?$B$B我有一堆種子就是特別為這樣的目的保留下來的。帶著它們去冥火嶺，將它們種在肥沃的土堆中。', '將8顆樹苗種在肥沃的土堆裡，再回到梣谷的林歌神殿找格納。', '', '去梣谷找林歌神殿的納亞爾。', '種下樹苗', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9527 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9527, 'zhTW', '剩下的一切', '我們和島上的野獸和平共處了許多年。你可以想像當他們襲取海濱攻擊我們時我有多驚訝。$B$B我拼了命的奮戰但還是輕易地被擊敗。當我因為受到劇烈的一擊而昏了過去時，我祈禱我的家人不會遭殃。$B$B當我醒來時，一切是如此平靜。沙子被血浸濕 - 那是他們的血。他們全都被毀滅了。$B$B我不想報仇，$N。我只想要回我家人的遺體好好埋葬。', '藍謎島的科倫要你找到科倫家族遺骨。', '', '去找蔚藍海岸島的科倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9528 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9528, 'zhTW', '求救', '我們家幾個禮拜前遭到島上的魚人和梟獸攻擊。我設法逃了出來但我想我的父母已慘遭毒手了。我不知道現在該怎麼辦，但我一定要試著回到我的家 - 或是說它還沒被摧毀的部份……你會幫我通過森林嗎?', '護送麥格文穿過島嶼回到她的家。', '瑪格溫已護送至安全處', '去找蔚藍海岸島的科倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9529 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9529, 'zhTW', '虛無石', '雖然我知道你的小鬼是個有用，有時又有趣的僕人，但現在是時候讓你駕馭一個更強大的惡魔了:虛無行者。$B$B由死亡之痕往下走直到遇見艾蘭達之河。在河的南方找到閃著光的藍色石頭並取走它，你的道路就會顯現。', '從死亡之痕取得虛無石。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9530 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9530, 'zhTW', '我要一棵樹', '我已經懷疑這件事好一陣子了，但這證明了它是真的。$B$B我們之中有個叛徒。$B$B哥布林留下的計畫裡證明了陰謀的存在。既然我不知道他是誰，我就要你幫助找到叛徒。我的手下沒有一個可信。$B$B如果這要起作用，我就需要一顆挖空的樹和樹葉。搜尋我們北邊樵木工附近的樹。你要自己找到樹葉。看看森林裡有沒有。', '藍謎島，奧迪席斯平臺的艦隊司令·奧迪席斯要你幫他帶回中空樹和5堆樹葉。', '', '去找蔚藍海岸島的艦隊司令‧奧迪席斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9531 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9531, 'zhTW', '樹的偽裝', '根據計畫，背叛者和哥布林的領導者，吉索，將要在西部半島上的一個海灣相見。我要你出現在那場會面，$N。$B$B記得那些樹和葉子嗎?你要穿戴上它們!那是完美的偽裝。$B$B去海灣那裡尋找一面納迦旗幟。如果旗子在那，就表示安排了一場會面。當你看到旗幟後就使用偽裝工具，然後等待。最後背叛者會現身。讓密會結束再回來告訴我那背叛者的是誰。帶著那個壞蛋的身份回來找我。', '藍謎島，奧迪席斯平臺的艦隊司令·奧迪席斯要你去觀察吉索和背叛者的會議。$B$B等你知道了背叛者的身份就回去找他。', '', '去找蔚藍海岸島的艦隊司令‧奧迪席斯。', '背叛者揭露', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9532 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9532, 'zhTW', '找到卡特斯·暗葉', '$n，我們的一個斥候對他的職責太專注了。他無情地調查我們的敵人但卻沒寄回他的發現報告。$B$B你一定要找到這個間諜，卡特斯·暗葉，說服他交出他的報告再盡快帶回來給我。他就在西南方，艾蘭達之河分叉並流到金霧村的地方。安都拉斯的夜精靈是他的目標，他不會離他們太遠。', '找到卡特斯·暗葉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9533 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9533, 'zhTW', '伸出援手', '有卡多雷的支持和合作，我的族人在梣谷東邊了付出了重要的努力。$B$B在建築師尼莫斯和復仇者維達的監督下，他們正在復興一個老舊的夜精靈前哨。建築的工作不簡單，$n，因為他們面對的挑戰和敵人很多。 我知道建築師尼莫斯和他在林歌神殿的同伴會感激任何能獲得的幫忙，而他也請我派任何有興趣的<男人/女人>去他那裡。', '前往林歌神殿和建築師尼莫斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9534 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9534, 'zhTW', '摧毀軍團', '惡魔般的燃燒軍團剩餘成員一直對我們的戰歌伐木營地發動突襲!$B$B不要再來了!$B$B惡魔正從東邊的冥火嶺，屠魔峽谷和屠魔山區域開始攻擊。$B$B盡量去殺死他們，為你自己和部落帶來榮耀!', '殺死6個瑪諾洛克鞭笞者，6個惡魔守衛和6個灼熱的煉獄火，再回到梣谷的碎木崗哨找瓦露薩。', '', '去梣谷找碎木崗哨的瓦魯莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9535 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9535, 'zhTW', '殘忍計畫', '惡魔掉了這張羊皮紙，驚人的是它竟然是用獸人語寫的!裡面提到的人，迪亞索魯斯和戈甘諾恩，是兩個聲名狼籍的驚懼領主，控制著附近的惡魔。$B$B計畫詳述對西北邊碎木崗哨的惡魔攻擊準備細節。$B$B你相信碎木崗哨的瓦露薩會對這些很有興趣。', '將殘忍計畫送到梣谷給碎木崗哨的瓦露薩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9536 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9536, 'zhTW', '永遠沒有下一次!', '$n，你要讓燃燒軍團的攻擊永遠都不會成真!去殺了這些驚懼領主!沒有他們，剩下的惡魔也只是無腦的蠢蛋而已。$B$B你要去冥火嶺更遠的南方，靠近曼諾洛斯的飄浮斷矛附近找到屠魔峽谷裡的戈甘諾恩。$B$B『追尋者』迪亞索魯斯就住在屠魔山上的獸穴裡。要找到那座山，就到葛羅·地獄吼的紀念碑旁，在屠魔峽谷上找一個斜坡。', '殺了戈甘諾恩和『追尋者』迪亞索魯斯。', '', '去梣谷找碎木崗哨的瓦魯莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9537 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9537, 'zhTW', '別對地精仁慈', '一定要讓火花·歐爾滾知道什麼叫正義!$B$B我要你去海邊那找到這個騙人的地精。一旦你找到他，就要他抖出所有的事情!$B$B如果連一個聯盟的高階官員都有不忠的行為，誰知道還有多少其他人也墮落了?$B$B還有$N，必要時你可以使用武力……', '奧迪席斯平臺的艦隊司令·奧迪席斯要你從工程師火花·歐爾滾那裡取回背叛者的信件。', '', '去找蔚藍海岸島的艦隊司令‧奧迪席斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9538 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9538, 'zhTW', '學習語言', '我想我破解了它，$N!$B$B<奧蘭指向圖騰。>$B$B我們所需要知道的靜松熊怪語言都銘刻在他們的圖騰上了。只要知道他們文字符號的基本意義，我們就能研究圖騰並試著和熊怪溝通。$B$B我在羊皮紙上寫下了他們基本的文字符號。研究它並檢驗圖騰。它會引導你至下一個語言圖騰。$B$B等你學會他們的語言之後再回來和阿魯古談談!$r!', '閱讀奧蘭給你的靜松熊怪語言入門書並和藍色守望的阿契達的圖騰互動。', '已閱讀寧松熊怪語言入門', '去找蔚藍海岸島的阿契達的圖騰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9539 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9539, 'zhTW', '庫的圖騰', '你開始閱讀圖騰，僅能唸出一些奇怪的字和片語。慢慢地，文字開始在你腦袋裡形成。你認為圖騰告訴你要去附近東北邊的山丘上。', '使用提供給你的線索找到庫的圖騰。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9540 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9540, 'zhTW', '堤克悌的圖騰', '你開始閱讀圖騰，較能發出字和片語的音。文字開始在你的腦袋裡形成。你認為圖騰告訴你要走到東邊的水晶河川對面。或許你的目的地就在河的另一邊。', '使用提供給你的線索找到堤克悌的圖騰。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9541, 'zhTW', '優兒的圖騰', '這圖騰的象徵似乎翻譯的更快一些。這些圖形和畫像都交融成熟悉的字。你相當確定這圖騰要你去南方，河流之下。在河底有個東西。', '使用提供給你的線索找到優兒的圖騰。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9542, 'zhTW', '瓦克的圖騰', '圖騰裡不再有你無法辨視的象徵了。優兒的圖騰讀起來就像在看你自己的語言一樣。印記辨識出另一個熊怪巢穴，就在西邊。你可以熟練地解讀圖騰上的語言知道你的目的地是鬚肢村。優兒會引導你，但如果你迷路了，你知道你可以走森林裡往西的古老精靈之路來到達你的目的地。', '使用提供給你的線索找到瓦克的圖騰。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9543 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9543, 'zhTW', '贖罪', '我們和獸人的歷史是不斷的鬥爭，$n。因為他們的嗜血我們曾經快被趕盡殺絕，因此現在就算不受惡魔影響了我們也躲著他們。$B$B但是，這個關係……不會是希戴所想要的。和我們的長者，『智者』阿曼談談。他會對這些事件做些解釋。', '到地獄火半島和特爾哈曼神廟的『智者』阿曼談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9544 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9544, 'zhTW', '阿契達的預言', '圖騰上的圖像是描述靜松熊怪及鬚肢熊怪兩族的戰爭。上面的蝕刻顯示鬚肢熊怪對靜松熊怪做了不合理的事。$B$B在這場混亂中，一則預言開始實現:將會出現一位英雄 - 非熊怪族群 -拯救了靜松熊怪。$B$B殺了鬚肢村裡的鬚肢熊怪，取得鑰匙，用這把鑰匙釋放被俘虜的靜松熊怪。完成後回到靜松要塞找阿魯古!', '釋放8個在鬚肢村裡發現的靜松俘虜。完成後回到藍色守望找靜松要塞的阿魯古。', '', '去找藍色守望的靜松要塞的阿魯古。', '釋放靜松俘虜', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9545 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9545, 'zhTW', '先知的聖物', '固執的人封閉他們的心並說服自己一個真理。聰明的人則開放他們的心胸接受各種不同的可能性，導致現在和現在所造成的種種。$B$B帶著這個聖物去找希戴。不要用你的眼睛看，$n，要用你的心。', '地獄火半島的特爾哈曼神廟的『智者』阿曼要你回到特爾哈曼神廟東北方希戴的屍體那邊使用先知的聖物。任務完成後回去找他。', '', '去地獄火半島找塔哈瑪特神殿的智者阿曼恩。', '看到幻像', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9546 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9546, 'zhTW', '預言中的英雄', '預言說，會有一位英雄站出來，並將我們從刺臂部族的魔爪之下拯救出來……終於，願古靈們能為這位英雄的到來而歡呼。$B$B現在，您終於來了。$B$B卑微的我向您致敬，偉大的英雄。我請求您，一定要拯救我們的孩子們。我們的衛兵被殺之後，他們被刺臂部族帶走了。你應該可以在西南方的刺臂村的牢籠裡找到他們。刺臂熊怪身上帶有鑰匙，殺死他們就可以得到鑰匙了。救救我的族人吧。', '止松部族的阿魯古要求你釋放8名被囚禁在刺臂牢籠中的止松俘虜。', '', '去藍謎島的碧藍崗哨找止松部族的找阿魯古。', '釋放止松俘虜', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9547 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9547, 'zhTW', '風的召喚', '$n，先知諾柏多一直在問你的事。一定是時候讓你學習風的秘密了，最後的元素!$B$B我要你知道我對你目前所達到的一切都很驕傲。我知道你的前方有很棒的事在等著你。', '與藍謎島中艾克索達裡水晶大廳的先知諾柏多談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9548, 'zhTW', '被偷走的裝備', '噓!小聲一點別讓我被發現。$B$B如果魚人察覺我的存在，實驗就毀了!危機已經逼近到足以毀掉我的研究數據。$B$B我昨天在搜索糧食的時候，他們其中一個一定是晃的太近發現了我的營地。我回來的時候剛好看見兩個魚人拿走一個木箱裝滿了我大部分的裝備!它一定在他們附近的營地之一裡，但我不能冒險現身。你願意幫忙嗎?', '把克羅波的裝備帶回來給克羅波·維茲班，他藏在海邊的一個龜殼裡面。', '', '去找鮮血島的克羅波‧維茲班恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9549 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9549, 'zhTW', '黑沙的手工藝品', '我對黑沙魚人的觀察和描寫是相當輝煌的，$N，但它們只是開始。我打算帶著黑沙的早期製作技術產物回到鐵爐堡。$B$B問題是黑沙總是帶著這些物品在身上，我不能背著良心去殺他們。如果你願意幫我收集黑沙先知帶著的塑像，和黑沙戰士及巡岸者帶著的粗糙小刀，我不會問你是怎麼弄到它們的。', '帶3個粗糙的魚人塑像和6把粗糙的魚人小刀給克羅波·維茲班，他藏在海邊的一個龜殼裡面。', '', '去找鮮血島的克羅波‧維茲班恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9550 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9550, 'zhTW', '模糊的地圖?', '這個繪畫粗糙的地圖並未透露出任何關於繪圖者的線索，但看來是隻很不穩的手畫的。顫抖的線條和符號描繪出一個有著破損圓柱的小亭子，在一個部分淹沒在水中的哨塔附近。$B$B如果這地圖可信的話，這些廢墟似乎位在島的東邊海岸。你不知道你可以在那邊找到什麼，但這一定夠重要繪圖者才會記錄下來。', '找到地圖中描繪的亭子並尋找製圖者想記錄下來的東西。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9551 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9551, 'zhTW', '風的召喚', '$n，先知諾柏多一直在問你的事。一定是時候讓你學習風的秘密了，最後的元素!$B$B我要你知道我對你目前所達到的一切都很驕傲。我知道你的前方有很棒的事在等著你。', '與藍謎島中艾克索達裡水晶大廳的先知諾柏多談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9552 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9552, 'zhTW', '風的召喚', '風的偉大靈魂在呼喚著你，$n，是時候讓你留心了。$B$B我要你前往北方的狂風山尖，它面對著艾克索達失事的山脈。在它的山頂你會找到一個洞穴，我最出色的學徒之一，維拉達就在裡面。$B$B請你聆聽她的智慧並照著她的吩咐做。當你回來時你會對風元素有更深的認識。', '到藍謎島的狂風山尖和維拉達談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9553 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9553, 'zhTW', '風的召喚', '雖然風看起來虛無飄渺，它卻是一個普遍的力量，覆蓋並彌漫在我們身邊所有的事物。$B$B雖然你看不見它，但這個洞穴的岩石大部分都是由風組成的，海洋的水裡也充滿了它，沒有它，火就不能持續燃燒。別讓那些元素聽到你在重覆這些話!$B$B有這樣智慧的人就在附近，你會想和他談談。蘇瑟拉斯在斷崖的北方邊緣等著你。你會從他那裡獲得了解。', '到藍謎島的狂風山尖和蘇瑟拉斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9554 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9554, 'zhTW', '風的召喚', '雖然我其他元素的兄弟姊妹要你進行不同的任務，但我不會對你有更多的要求。你的船從我的天空掉落在這個地方，我想你已對這個意外做了許多「彌補」。我可以看見你已擁有所有的智慧來聰明地利用風元素。$B$B帶著我本質的這個部分回到先知諾柏多那裡，這樣他就能幫你製作你的圖騰。等你準備好，我就會讓你飛回艾克索達。', '帶著空氣漩渦回到藍謎島找艾克索達的先知諾柏多。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9555 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9555, 'zhTW', '火焰的召喚', '我很感謝你選擇了薩滿的艱難之路。很少人會這麼做，但我預見向破碎者學習薩滿之道對我們的未來是不可或缺的。$B$B他們雖然被這樣稱呼，但他們都曾是德萊尼。地獄魔法改變了他們，那就是為什麼他們不能召喚聖光的力量。有些人否決他們和他們教授的薩滿之道，但他們並不邪惡。$B$B我希望你去和先知諾柏多談談。他是我所知道最有智慧的薩滿，你會從他的指引中學到很多。', '到艾克索達和水晶大廳的先知諾柏多談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9556 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9556, 'zhTW', '給勝利者……', '你一定在哨塔間浴血奮戰了很久，$r。為感謝你對這片土地防禦付出的努力，我們要給你一些東西做為回饋，但是首先，你一定要先向我們證明你知道這裡發生的悲劇有多大的影響。$B$B踏上斯坦索姆的道路並找到一瓶聖水。一旦你拿到了它，就前往暴風城或幽暗城的法師區……在那裡，如果你在這些土地間是勝利的，你就會找到我的同事。', '從斯坦索姆城裡取得一瓶斯坦索姆聖水，當你的陣營在東瘟疫之地獲得勝利，就把它交給暴風城或幽暗城法師區裡的羅德隆法師。', '', '去找羅德隆法師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9557 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9557, 'zhTW', '解讀這本書', '沒有辦法閱讀這本書的內容，你思考著誰能幫你從製圖師的潦草字跡中辨別出原著的字句。$B$B想起無數文化中隱士裴薩斯的手工藝品收藏，你懷疑他老練的雙眼是否能幫你解讀這本書的內容。', '把古老的日記帶給血色守望的隱士裴薩斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9558 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9558, 'zhTW', '長鬚兄弟', '我們有個阿拉卡土匪的麻煩，他們掠劫我們許多的補給商隊，所以我僱了一些矮人來解決他們。$B$B他們是兄弟;葛明尼·長鬚是哥哥。$B$B我有點擔心他們。那些瘋狂的矮人帶的麥芽酒比食物和彈藥更多!或許你可以去看看他們的情況?$B$B阿拉卡的藏身處，海艾斯洞穴，在很遠的西邊 - 大裂縫後面。他們在那裡的西北方建立營地，就在塵羽峽谷的南邊。', '前往海艾斯洞穴的西北邊找葛明尼·長鬚，在地獄火半島的榮譽堡西邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9559, 'zhTW', '靜松要塞', '允諾者，你一定要去北方我族人的家園 - 靜松要塞。你會在那裡遇上最令人怯步的挑戰。去吧，大酋長靜松在等著你。', '和靜松要塞的大酋長靜松談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9560, 'zhTW', '天啟的野獸!', '我和我哥哥在東邊的樹林裡打獵時遭到奇怪的，像昆蟲一樣的野獸突擊。我們從沒在藍謎島見過這樣的畸型生物!他們會是即將來臨的天啟徵象嗎?你命中注定要阻止的天啟?$B$B如果你真的是允諾者，你就要擊敗那些天啟的生物……把他們的皮革帶來給我。利用它們的皮革，我可以製作強大力量的護甲!$B$B去東邊找到它們，就在路的那一邊。', '藍謎島，靜松要塞的墨爾多要你幫他帶來8塊劫毀者皮。', '', '去找蔚藍海岸島的墨爾多。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9561, 'zhTW', '諾凱的話', '翻譯已經準備好了，$n。$B$B<隱士裴薩斯指著他翻譯尾段的一塊文字。>$B$B\'敵人離我們不遠了。我們聚集了所有的生還者撤退到東方的神廟。這是我們在島上真正掌握的最後一塊土地，生還者也都有默契的認為這裡是我們最後的一站。我已將我最後的一些財產埋在神廟的土裡，希望有人會找到它們並知道這裡發生了什麼事。', '找到諾凱的日記中描述的地點及那裡埋藏已久的財產。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9562, 'zhTW', '魚人……為何此時?為何此地?', '這些日子很黑暗，允諾者。就連魚人都對我們窮追不捨 - 一點也不誇張。不幸地，不只我的自尊受挫。$B$B雖然我們和沙鰭魚人的關係一直都很不好，但我們怎麼也沒想到他們會有膽攻擊我們還偷取我們的食物存貨!到西邊的淤塞海岸取回我們被偷的糧食!$B$B還有如果你看見一隻黑皮膚的魚人蹼指間卡著一塊白色的毛皮……', '藍謎島，靜松要塞的克夫要你取回5袋靜松穀物。', '', '去找蔚藍海岸島的克夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9563, 'zhTW', '贏得麥倫的信任', '你想要獲得我們的信任?我最近不太相信任何人。$B$B不久前我們才在阿拉卡手下損失了其中一員。這件事讓我接近崩潰。$B$B跟你說，如果你可以證明你對榮譽堡的忠誠...帶一杯守望苦味啤酒給我...沒錯，這聽起來真不錯...之後我會和你做個交易。$B$B在守望堡的波尼那有啤酒現貨。', '麥倫·長鬚要你幫他帶來1杯守望苦味啤酒。同時你必須在榮譽堡達到友好聲望值才能完成這個任務。', '', '去找地獄火半島的米倫·長鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9564, 'zhTW', '克夫的尊嚴', '你取回克夫跟魚人奮鬥時「丟失」的毛皮。將毛皮還給克夫並讓他知道可怕的莫爾古爾古拉已經被殺了。', '將克夫的尊嚴帶到藍謎島的靜松要塞還給克夫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9565, 'zhTW', '搜索靜松要塞', '身為大酋長，我最擔心的就是靜松要塞的腐敗根源。為什麼梟獸 - 曾經是我們的盟友 - 會攻擊我們?他們為什麼會居住在靜松要塞?或許裡面的某個東西會有答案。搜索靜松要塞尋找腐敗源頭的線索。', '搜索靜松要塞找到線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9566, 'zhTW', '血水晶', '表面上看來，水晶似乎只是艾克索達的一部分。但這水晶出了些可怕的錯誤，它是血紅色的而且迅速地溶解在洞穴的給水系統中。這或許解釋了藍謎島生物不尋常的侵略性行為。帶著這個消息去找大酋長靜松。', '和靜松要塞的大酋長靜松談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9567, 'zhTW', '了解敵人', '在血色守望見到新面孔真好，$c。雖然血精靈是最緊迫的威脅，但還有其他以血謎島為家的邪惡生物。$B$B納茲維斯薩特是特別令人擔心的。他們是骯髒，惡魔的生物，掌握黑暗魔法，以艾克索達失事產生的汙染物為食物。$B$B我們一定要阻擋他們，但首先要先了解他們。去西南邊的納茲維恩，從他們奇形怪狀的紀念碑來認識他們。', '找到納茲維恩的納茲維斯紀念碑並取得納茲維斯紀念碑雕紋。拿到一個雕紋後回到血色守望的復仇者艾樂希雅那裡。', '', '去找鮮血島的復仇者艾樂希雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9568 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9568, 'zhTW', '進攻勢態', '這比我想像的還糟，$N。我們德萊尼很清楚知道將自己的靈魂出賣給燃燒軍團換取力量和不朽的承諾會有怎麼樣的下場。$B$B島上的薩特，納茲維斯，就是第一批這樣的後裔，與軍團結盟的瘋狂生物。我擔心他們會想辦法利用艾克索達的水晶力量來對付我們.$B$B你見過他們對大地做的事。想像薩特會對他們做什麼。去西南方的納茲維恩，開始我們的攻勢！\\r\\n\\r\\n', '血色守望的復仇者艾蕾希亞要你殺死10個納茲維斯薩特，5個納茲維斯盜賊，和5個納茲維斯魔語。', '', '去秘血島找秘血崗哨的守備官艾蕾希亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9569 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9569, 'zhTW', '遏制威脅', '既然已讓薩特知道了我們的存在，我們就一定要放出消息讓他們知道我們不會容忍燃燒軍團的爛人出現在這些土地。$B$B德萊尼已經躲避燃燒軍團和它的爪牙太久了，$N。他們不管在哪裡找到我們都毫不留情。$B$B我們一定不能讓薩特利用艾克索達的失事，把腐敗的水晶當做武器。去北邊，他們領導者居住的艾克薩瑞安，殺了他，取回他一直在收集的被汙染的水晶!', '殺死5個艾克薩瑞安巡影者，5個艾克薩瑞安地獄呼喚者，和澤伏瑞斯，再收集5個被汙染的水晶交給血色守望的復仇者艾樂希雅。', '', '去找鮮血島的復仇者艾樂希雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9570 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9570, 'zhTW', '潛伏的克爾肯', '在水晶風暴平息後，一隻神秘的野獸出現在我們村子裡。這隻野獸，克爾肯，是被入侵的梟獸帶來這裡的，他對我們的村子造成許多毀壞。許多靜松的人都為了防禦我們的土地而被殺，還有許多人嘗試制服這隻野獸，從此失去了他們的性命。$B$B在我的幻境中我看見一個人擊敗了克爾肯。那個人一定就是你，$N。你是我們唯一的希望。進入靜松要塞殺死克爾肯。把他的皮革帶回來給我做為證據。', '藍謎島，靜松要塞的『啟示者』克茲要你殺死克爾肯再帶回克爾肯的皮。', '', '去找蔚藍海岸島的『啟示者』克茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9571 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9571, 'zhTW', '克爾肯的皮', '把克爾肯的皮帶給墨爾多，在村子的另一邊。他會把皮革做成你要的物品。', '將克爾肯的皮送給靜松要塞的墨爾多。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9572 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9572, 'zhTW', '削弱防禦', '快，時間不多了。索爾瑪的存在與否就靠刀刃來決定了!$B$B我們被西邊的地獄火堡壘和東邊的燃燒軍團夾攻。現在燃燒軍團的注意力轉向黑暗之門，我們一定要利用這個機會突擊地獄火堡壘的魔化獸人。關鍵就是先突破他們的防禦!$B$B去那裡殺死他們的領導者，再將證據帶回交給房間那一頭的卡沙瑞斯!', '殺死看護者卡爾古瑪、無疤者歐瑪爾和納桑。將卡爾古瑪之手、歐瑪爾的蹄子和納桑之顱帶到地獄火半島的索爾瑪交給卡沙瑞斯。', '', '轉至地獄火半島，去找索爾瑪的卡薩雷茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9573 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9573, 'zhTW', '歐沐魯酋長', '我是靜松年少者，靜松遺產的繼承人。如你所見，我的防衛者對靜松要塞裡攻擊我們的瘋狂梟獸設了一個死亡陷阱。我們雖然能阻止他們進到這裡，但我的防衛者卻沒有一人能滲入要塞。如果你可以進到裡面並殺了他們的領導者，那就能給我們機會襲擊!$B$B找到歐沐魯酋長並殺了他。也殺死任何你在裡面遇到的瘋狂梟獸。', '藍謎島，靜松要塞的靜松年少者要你殺死歐沐魯酋長和9個瘋狂的梟獸。', '', '去找蔚藍海岸島的靜松之子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9574 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9574, 'zhTW', '腐敗的受害者', '血謎島在我們到達之後已經被徹底的改變了。艾克索達的失事讓殘骸散落在整座島上，我想它開始對野生生物產生了負面的影響。$B$B在我確定我的推論之前，我需要更仔細的檢視一番。水晶似乎對樹木的影響最快，所以樹人應該是最容易出現症狀的。如果你幫我從墮落的樹人身上帶回樹皮的樣本，我就能開始我的深入研究。', '帶6塊晶化樹皮給血色守望的莫瑞伊。', '', '去找鮮血島的莫瑞伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9575 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9575, 'zhTW', '削弱防禦', '快，$c，時間不多了。榮譽堡的存在與否就靠刀刃來決定了!$B$B我們被西邊的地獄火堡壘和東邊的燃燒軍團夾攻。現在燃燒軍團的注意力轉向黑暗之門，我們一定要利用這個機會突擊地獄火堡壘的魔獄獸人。關鍵就是先突破他們的防禦!$B$B去那裡殺死他們的領導者，再帶回證據給大廳那一頭的甘尼!', '殺死看護者卡爾古瑪、無疤者歐瑪爾和納桑。將卡爾古瑪之手、歐瑪爾的蹄子和納桑之顱帶到地獄火半島的榮譽堡給甘尼。', '', '轉至地獄火半島，去找榮耀堡的岡尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9576 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9576, 'zhTW', '酷鰭的項鍊', '檢視這個製作粗糙的墜飾，你發現水晶正輕柔地搏動著。雖然它的光線很微弱，但你幾乎可以感覺水晶散發出一種錯誤的訊息。$B$B你不太確定是什麼支配著酷鰭製作出這樣的墜飾，但這發現實在是太重要無法忽略。你或許該把它拿給血色守望的人看看。', '將紅色水晶綴飾帶給血色守望的莫瑞伊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9577 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9577, 'zhTW', 'DAILY TEST QUEST (PVP)', '<NYI>Seek <QUESTGIVER> in <LOCATION>.  S/he wishes for you to aid them in a difficult task.', 'Speak with <QUESTGIVER> in the <AREA>.', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9578 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9578, 'zhTW', '尋找高拉恩', '你常想到你的家人嗎，$N?有許多家庭都坐上了艾克索達，但我很少聽到有人能團圓的。我自己也在尋找我丈夫高拉恩的消息，他是冬眠核心的技師。那個殘骸在西邊，那裡充滿了血精靈!我一定要知道高拉恩的下落!就算是他的死訊也比永遠都不知道來的好。我的丈夫會戴著一個和我一樣的墜飾;它們是我姐姐送的禮物。', '尋找莫瑞伊的丈夫高拉恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9579 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9579, 'zhTW', '高拉恩的命運', '你無法利用莫瑞伊給你的資訊來鑑別高拉恩的屍體，但他的衣服看來被人搜括過而撕裂。$B$B這區域的血精靈會拿走殘骸身上所有有價值的東西，包括高拉恩的寶石護符。$B$B雖然她的丈夫未從失事中生還，你相信莫瑞伊會很感激你從血精靈那裡取回她丈夫的護符。', '將高拉恩的護符帶給血色守望的莫瑞伊。', '', '去找鮮血島的莫瑞伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9580 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9580, 'zhTW', '熊的必需品', '我相信你在血謎島的這段時間也看到了，很少遺物未因我們的到來而改變。我的訓練和經驗讓我知道就算是像這樣的環境產物也可以拿來利用。$B$B資源這麼少，我們一定要依賴我們的足智多謀。我用閒晃在島上的熊肉補充我們的存貨。有適當的處理，我們就能安全的吃熊肉。如果你要去外面晃晃，何不幫忙補充一些存貨呢?', '帶8塊老棕熊腰肉給血色守望的追蹤者萊希安。', '', '去找鮮血島的追蹤者萊希安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9581, 'zhTW', '水晶的學問', '歡迎來到血色守望，$c。監督前哨的防禦是我首要關心的事，但我也被艾克索達的領導者指派了很多其他的職務。$B$B問題是在島嶼這樣危險的時候派出大量的研究員是很危險的。我需要某人去島上不同地點收集一連串的水晶樣本。$B$B我需要的第一個樣本一定要來自鎮南方過了橋的地方，劫毀者寄生的船隻殘骸。', '對衝擊遺址水晶使用水晶採礦鎬以取得衝擊遺址水晶樣本然後交給血色守望的通報者米可拉斯。', '', '去找鮮血島的通報者米可拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9582 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9582, 'zhTW', '一人的力量', '當船失事的時候，我們的獸欄散落在島的東北方海邊。我有一把鑰匙可以打開關著一種致命生物，死亡劫毀者的籠子。那個生物沒什麼防禦能力，但卻能抵抗大部份的魔法，一定要用單純的劍刃把它殺死。$B$B拿著這把鑰匙將那個生物從監禁和痛苦中釋放。我們不能讓它逃跑，否則會對生態造成比現在更嚴重的傷害。', '打開劫毀者牢籠殺死死亡劫毀者，再回藍謎島的藍色守望找羅達。', '', '去藍謎島找碧藍崗哨的魯安達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9583 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9583, 'zhTW', '歐瑪的測試任務', '高尚的人給我衣服', '幫歐瑪拿衣服', '', ' 到程式設計師之島的測試龍附近找歐瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9584 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9584, 'zhTW', '第二個樣本', '既然我們有了基線水晶，我們就需要更多危險區域的樣本來完成這套送到艾克索達的水晶。$B$B下一個樣本一定要來自劍木林的血精靈控制的水晶，就在血色守望的西北邊。我獲悉他們改變並取得水晶用在一些魔法儀器上。看看你能否找到一個未被合併在他們儀器裡的水晶並採下一個樣本。', '對變質的血謎水晶使用水晶採礦鎬以取得變質的水晶樣本然後交給血色守望的通報者米可拉斯。', '', '去找鮮血島的通報者米可拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9585 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9585, 'zhTW', '最後的樣本', '在我把這些水晶送到艾克索達前還有一個樣本要收集，$n。最後的樣本一定要來自西北邊艾克薩瑞安的薩特要塞。$B$B我不確定這個水晶樣本能說明什麼，但我肯定一定會有一些汙染的徵象。記得從水晶上開採下你的裂片，就是看起來像你取得之前樣本的那種水晶，否則我們的研究員就無法做出有根據的對照。', '對艾克薩瑞安水晶使用水晶採礦鎬以取得艾克薩瑞安水晶樣本然後交給血色守望的通報者米可拉斯。', '', '去找鮮血島的通報者米可拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9586 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9586, 'zhTW', '幫助塔瓦拉', '我們的一個草藥師，塔瓦拉去尋找草藥太久了。我擔心她受了傷需要忙，但我不能自己去找她。$B$B請找到她並提供你的治療，$c同伴。她離開藍色守望的時候是往東邊的溫泉走去。', '藍色守望的古樊要你找到塔瓦拉並治療她的傷口。', '', '去藍謎島找碧藍崗哨的古安。', '治癒塔瓦拉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9587 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9587, 'zhTW', '黑暗的消息', '大概查看了一下已沒有氣息的『信使』維斯路登，你發現了一封捲起來的信件，上面的封膠尚未拆開。一個精緻的「伊」字以血紅色的墨水壓印在上面。打開這張便條，你看到的內容令你不安。$B$B軍隊指揮者達納斯·托爾貝恩回到榮譽堡後一定會想要看看這封信!', '將不祥的信件帶到地獄火半島交給榮譽堡的軍隊指揮者達納斯·托爾貝恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9588 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9588, 'zhTW', '黑暗的消息', '大概查看了一下已沒有氣息的『信使』維斯路登，你發現了一封捲起來的信件，上面的封膠尚未拆開。一個精緻的「伊」字以血紅色的墨水壓印在上面。打開這張便條，你看到的內容令你不安。$B$B納茲格雷爾回到索爾瑪後一定會想要看看這封信!', '將不祥的信件帶到地獄火半島交給索爾瑪的納茲格雷爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9589 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9589, 'zhTW', '血液就是生命', '那封信會讓人們心浮氣躁的。他們會認為如果我們知道他們是如何創造出這些新的魔獄獸人，我們就會想些辦法來對付他們。要對抗東邊的燃燒軍團就已經夠慘了。$B$B所以，這是你的幸運之日，小甜甜!你得去地獄火堡壘裡的血熔爐晃晃。聽起來很熱!$B$B進去那裡，殺死一些魔獄獸人再將他們的血液樣本帶回來。$B$B你覺得你辦的到嗎?', '收集10個魔獄獸人血瓶後回到地獄火半島的榮譽堡找甘尼。', '', '轉至地獄火半島，去找榮耀堡的岡尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9590 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9590, 'zhTW', '血液就是生命', '那封信讓人心煩，不只是因為它是從背叛者那來的。如果我們要打敗他們，就得知道他們是如何創造出這些新的魔獄獸人!要對抗東邊的燃燒軍團就已經夠慘了，現在連西邊也出現了一批新的魔獄獸人軍隊!$B$B你得滲透進地獄火堡壘的血熔爐裡，將你在那發現的魔獄獸人血液樣本帶回來。', '收集10個魔獄獸人血瓶帶回地獄火半島的索爾瑪給百夫長卡沙瑞斯。', '', '轉至地獄火半島，去找索爾瑪的卡薩雷茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9591 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9591, 'zhTW', '馴服野獸', '當$c初次踏上<他的/她的>路，。<他/她>只學會殺戮。現在看來你已準備好學習更多。$B$B靜松熊怪提供了一個方法來精通馴服的技巧而不需要數個月的學習。他們可以將圖騰刻成某種動物的樣子，你就能暫時用來和那種生物做朋友。$B$B你的第一堂課就是帶著這個圖騰，到島的西海岸找到尖刺的爬行者來使用它。', '使用馴服圖騰和尖刺的爬行者做朋友再回到女獵人凱拉·夜弓那裡。', '馴化一隻帶刺的螃蟹', '去找藍謎島的女獵手凱拉·夜弓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9592 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9592, 'zhTW', '馴服野獸', '爬行動物是無疑地脾氣暴躁，但林地陸行鳥會考驗你的決心。更多強大的盟友需要獵人更不屈不撓。$B$B帶著這個馴服圖騰去和林地陸行鳥做朋友。他們就在藍謎島的北方區域。', '使用馴服圖騰和大林地陸行鳥做朋友再回到女獵人凱拉·夜弓那裡。', '馴化一隻巨型林地陸行鳥', '去找藍謎島的女獵手凱拉·夜弓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9593 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9593, 'zhTW', '馴服野獸', '你在馴服林地陸行鳥的時候或許有注意到那種叫夜間潛伏者的大型貓科動物。他們是有效率又致命的獵人……也是盟友。$B$B使用這個馴服圖騰和夜間潛伏者做朋友。和這個兇惡的獵豹一起打獵並保護他不受傷害。完成後再來找我。', '使用馴服圖騰和夜間潛伏者做朋友再回到女獵人凱拉·夜弓那裡。', '馴化一隻夜行豹', '去找藍謎島的女獵手凱拉·夜弓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9594, 'zhTW', '燃燒軍團的徵象', '護甲碎塊是由一種好像會吸收光線的深黑色金屬鑄造而成。雖然它不像被附魔的樣子，但它絕對有不對勁的地方。$B$B這種護甲只有一種軍隊會使用 - 燃燒軍團。軍團出現在這裡就是因為他們要動員島上的薩特對抗德萊尼。$B$B對當地薩特採取行動，再回到血色守望把這個護甲碎塊拿給復仇者艾樂希雅看。', '殺死8個納茲維斯薩特和8個納茲維斯魔語，然後帶著泰斯拉克的鎧甲到血色守望找復仇者艾樂希雅。', '', '去找鮮血島的復仇者艾樂希雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9595 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9595, 'zhTW', '控制魔法', '你已經選擇了$c之路，所以你一定要學會控制魔法。魔法，當它不受控制的時候，會腐化靈魂並摧毀世界。$B$B你想對魔法有全面性的了解的話，你必須去找一個對魔法十分著迷的人。前往藍謎島西北方的海岸邊，使用你的法術來消滅魚人。你展現出來的法力會引起潛伏在那邊的邪惡力量的注意，奎爾德尼·法怨。擊敗它。$B$B等你完成後就去找巴提，他在艾克索達的聖光地窖裡。', '殺死淤塞海岸的魚人來召喚奎爾德尼·法怨，然後擊敗它。完成之後，到艾克索達的聖光地窖和巴提談談。', '', '去找艾克索達的聖光穹頂的巴蒂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9596 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9596, 'zhTW', '<DEPRECATED>Control', '<NYI>Do something else,$c！', '<NYI>Log description.', '', '去找Designer Island的Jonathan LeCraft。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9597, 'zhTW', '<UNUSED>', '<NYI>Hey little man, do something worthy and talk to Jonathan LeCraft.', '<NYI>Log description.', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9598 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9598, 'zhTW', '救贖', '我負責指引獻身於聖光的聖騎士走向聖潔之路，使其保護我們的人民免於敵人的威脅。$B$B朝聖潔之路踏出第一步的時刻已經來臨了。只要你下定決心，我會給你一本聖潔之書。書中的內容將有助於你對聖光的了解，以及身為一名聖騎士必須負擔的職責。假如你的能力足夠並且可以貫徹書中的精神，那麼我將賦予你更強大的力量。', '研讀聖潔之書並且跟喬歐談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9599 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9599, 'zhTW', '<UNUSED>', '在所有事物中，聖騎士一定要反映聖光，它補充我們的力量。努力成為我們族人之中出色的一個不代表我們要得到神性 - 我們是要在各個方面都表現的好。$B$B就算在這些惡劣的時代被召喚來懲罰邪惡，你也一定要記住那是在幫助真正會將你和其他人分開看待的人。憐憫，耐心，勇敢 - 這些事對聖騎士而言和戰鬥中的力量一樣重要。$B$B你要清楚的知道，而且永遠不能忘記。', '和艾克索達的喬歐談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9600 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9600, 'zhTW', '救贖', '那麼，$n，你的任務就是協助我們的新盟友，靜松熊怪。$B$B幾個年輕的靜松薩滿偶然發現了一個鬚肢營地然後就被趕盡殺絕。帶著這個生命符記去復活其中一個薩滿。$B$B越過橫跨藍謎和血謎島的橋，鬚肢營地就在路的東邊。完成後再來和我談談。', '喬歐要你用生命符記復活一個年輕的熊怪薩滿再回去找她。', '', '去艾克索達找聖光穹頂的約爾。', '復活年輕的熊怪薩滿祭司', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9601, 'zhTW', '前進亡靈壁壘', '血騎士瑪拉·曦刃要求你當他的聽眾，$n。你可以在亡靈壁壘找到瑪拉，保衛提里斯法林地和西瘟疫之地之間的通道。$B$B他不是以他的耐心聞名。聰明的話就不要讓他等。', '和在亡靈壁壘的瑪拉·曦刃談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9602, 'zhTW', '傳遞不幸的消息……', '你一定要將這個消息告訴你的族人，$N。雖然你英勇的行為的確有讓凱爾薩斯和他黑暗主人的計畫慢下來，但攻擊絕對會持續下去。$B$B把背叛者的信件帶給你的領導者。他們一定要親自看看。或許他們能更清楚了解裡面寫的東西。', '將背叛者的信件帶給藍色守望的主教米奈奧斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9603, 'zhTW', '床，繃帶，和很多很多', '歡迎來到血色守望，$c。請不要介意四周的凌亂。把簡單的事情視為理所當然是很容易的，就像建造一間有著完整裝潢和存貨的旅店，直到你被迫無中生有才知道它的困難。$B$B我們已利用這個分離艙做為建築物，但沒有適當的家具和急救補給品，這旅店也不過是個美麗的帳篷而已。艾克索達的魯古尼已表示會給我們一個包裹來解決我們最迫切的需要，但我還需要某人幫我把這個單子送給他。', '把塔伏爾的單子交給血色守望的角鷹獸管理員勒藍度。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9604, 'zhTW', '飛快的角鷹獸', '只要一點錢，你就能租一隻角鷹獸載你到艾克索達。$B$B搭乘角鷹獸是既快又安全的方式，提供給攜帶重要訊息的人選擇。如果你要乘坐，再跟我說，我會安排的。', '向勒藍度那租借一隻角鷹獸飛往艾克索達，抵達後，將塔伏爾的單子交給那魯之座的魯古尼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9605, 'zhTW', '角鷹獸管理員史丹樊那斯', '箱子在這，$N。這應該夠塔伏爾經營旅店了。讓他知道有需要的話他可以繼續訂貨。血色守望急切地需要一個地方來照料傷者及供給旅人住宿。$B$B等你準備好前往血色守望，就去找艾克索達入口旁的史丹樊那斯。', '到艾克索達外去找史丹樊那斯，並乘坐角鷹獸回到血色守望。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9606, 'zhTW', '回到塔伏爾·羅歐那裡', '如果我沒記錯，血色守望的角鷹獸管理員是勒藍度。要是你之前已經跟他說過話了，就能從我這租一隻角鷹獸到他那去。$B$B這是個很好的學習:角鷹獸一直接受訓練飛往他們的主要城市，但它們只能送你前往所在地之外的角鷹獸管理員那。$B$B因為你已經去過勒藍度的其中一處鳥點，就能使用這條路線帶著補充品回到血色守望去。', '與史丹樊那斯租借一隻角鷹獸回到血色守望。一旦抵達後，運送魯古尼的補給品給照顧者塔伏爾·羅歐', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9607, 'zhTW', '狂怒之心', '$c，立刻聚集一支軍隊去調查地獄火堡壘的血熔爐!意思就是今天，小公主!$B$B我們的魔法指出那裡出現了某個不尋常的東西。但裡面有一個強大的力量阻擋了任何精細的秘法調查。這有道理!$B$B你要帶著眾多人手 - 我們派去那裡的人沒有一個回來過!$B$B徹底的偵察那裡再向軍隊的指揮官報告你所見到的一切。', '徹底調查血熔爐再到地獄火半島的榮譽堡向軍隊指揮者達納斯·托爾貝恩回報。', '全面調查鮮血熔爐', '轉至地獄火半島，去找榮耀堡的遠征軍指揮官達納斯·托爾貝恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9608, 'zhTW', '狂怒之心', '$c，你一定要立刻聚集一群人去調查地獄火堡壘的血熔爐!$B$B我們的魔法占卜指出那裡出現了某個不尋常的東西。但裡面有一個強大的力量阻擋了任何精細的秘法調查，所以它一定是非常重要的。$B$B你要帶著眾多人手 - 我們派去那裡的人沒有一個回來過!$B$B徹底的偵察那裡再向索爾的顧問，納茲格雷爾報告你所見到的一切。', '徹底調查血熔爐再到地獄火半島的索爾瑪向納茲格雷爾回報。', '全面調查鮮血熔爐', '轉至地獄火半島，去找索爾瑪的納茲格雷爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9609, 'zhTW', '幫助看守者比格斯', '瑪格圖爾告訴我附近有個無依無靠的看守者。很明顯的他從黑海岸護送來的商隊遭到了失落者的攻擊。聽起來他似乎是唯一的生還者。$B$B他就在南邊的某個地方。拜託，$c，給予他你的協助。', '在悲傷沼澤裡找到看守者比格斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9610 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9610, 'zhTW', '淚水之池', '我很有興趣研究艾澤拉斯的過去，不知道你是否願意幫忙?$B$B我想請你去附近沼澤裡一個具有重要歷史意義的地方。淚水之池就在東南方。據說在它的岸邊和池子深處都埋藏著阿塔萊食人妖文化的手工藝品。$B$B但是要小心，一隻古老的綠色之龍，索姆努斯，和他的龍族守護著池子，池裡還有食人魚!', '取得5個阿塔萊神器再回到悲傷沼澤的避難營找何拉魯。', '', '去找悲傷沼澤的霍拉魯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9611, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9612 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9612, 'zhTW', '衷心的感謝!', '你救了我一命，$n!真是太感謝你了!要不是你那個野獸早就把我碎屍萬段了。$B$B如果你在藍色守望看見主教，告訴他你做的事。我相信他會很高興聽到這樣的消息!', '和藍色守望的主教米奈奧斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9613 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9613, 'zhTW', '琪安娜的遺囑', '<當你觸碰這把劍時，你聽到一個女性的聲音在對你說話。>$B$B喔！不要這樣！你沒看到我都變成碎片了嗎？這樣真的很痛。$B$B看來卡拉讚的人沒有把你捉起來。那麼你一定要知道卡德加和紫羅蘭之眼的事。$B$B你要找到一個人可以把我重組回去。卡爾侖……他曾是我們的密探……他就在附近。我希望你站在我們善良的這一邊。如果是的話，他就可以幫忙！', '你在卡拉贊找到的Shattered Blade要你請卡爾侖將它修復。你還需要在紫羅蘭之眼達到尊敬聲望值才能完成這個任務。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9614 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9614, 'zhTW', '重鑄短劍', '這武器斷成好多截……要把它重組不是件容易的事。$B$B我需要克銀。很多的克銀。我還需要虛無水晶和一些原始之火。', '帶40個克銀錠，1個虛無水晶和8個原始之火給卡拉讚的卡爾侖。', '', '去找卡拉讚的庫雷恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9615 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9615, 'zhTW', '重鑄長劍', '這武器斷成好多截……要把它重組不是件容易的事。$B$B我需要克銀。很多的克銀。我還需要虛無水晶和一些原始之火。', '帶40個克銀錠，1個虛無水晶和8個原始之火給卡拉讚的卡爾侖。', '', '去找卡拉讚的庫雷恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9616 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9616, 'zhTW', '土匪!', '這看起來是一個賞金帳本。你不了解血精靈的語言，但你注意到有一個圖片描繪一個死去的德萊尼，一個微笑的血精靈站在屍體旁，和一個你認為是某種血精靈貨幣的符號。$B$B他們已經對德萊尼發動攻擊了!你一定要通知主教。', '將血精靈情報帶給藍色守望的主教米奈奧斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9617 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9617, 'zhTW', '尋找遠行者', '遠行者居所的晨奔中尉要覲見所有能幹的獵人。去找她對你有很大的助益，$n。她是我們天職的智慧燈塔。$B$B遠行者居所就在銀月城的南方。', '和遠行者居所的晨奔中尉談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9618 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9618, 'zhTW', '交回報告', '你的花招真令人印象深刻。我可以放心地讓你將這些報告帶給賽藍尼斯。', '將卡特斯·暗葉的報告帶給銀月城的賽藍尼斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9619 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9619, 'zhTW', '召喚符文', '虛無石顯現出一個多層建築物被鬼影纏繞的幻象。畫面時而清晰時而模糊，隨著其他的建築物也出現在畫面裡，你相信那是金霧村。$B$B屋頂和樹頂突然間閃現，顯露出沿著西邊的艾蘭達之河去金霧村的路。$B$B到了那裡，在中央建築物的頂端，靠近召喚符文處使用虛無石並擊敗召喚出來的虛無行者。只有這樣你才能回到老師身邊。', '在金霧村使用虛無石召喚出一個虛無行者，擊敗它，再回到銀月城的塔萊妮亞那裡。', '', '去銀月城找密室的塔萊尼婭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9620 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9620, 'zhTW', '失蹤的調查小組', '隨著我們在血色守望安置下來，我也派出了調查小組去製作更多可靠的島嶼地圖。大部分的情況來說，他們都會帶著我們需要的資料毫髮未傷的回來，但我派去東邊廢墟的小組卻未向我們回報。我擔心他們會發生什麼事，但我沒有人手可以接下另一個任務去找他們。找到他們，$N，給予他們任何需要的協助帶回他們的調查資料。', '通報者米可拉斯要你找到他派去羅薩倫廢墟的調查小組並盡力幫助他們。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9621, 'zhTW', '部落的使者', '我們潛在的新盟友對我們的能力有些懷疑。被認為連自己家的問題都無法解決那我們對他們而言還有什麼用?$B$B這會改變一切。我們的能力不再會被質疑。我們會以同等的姿態加入部落。$B$B把這封信交給希瓦娜斯，被遺忘者的統治者。她已經和我們站在同一陣線了，但達克汗的死訊對她而言沒有影響力。準備好長途跋涉吧，$N。如果一切進行順利她會送你到奧格瑪的。', '將來自洛索瑪·塞隆的信帶到幽暗城，提里斯法林地的被遺忘者首都給希瓦娜斯·風行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9622, 'zhTW', '警告你的族人', '要塞保住了，很快的我的族人會回到先祖的家。預言成真了，一個新的繁榮時代就要在靜松展開了。但我擔心黑暗就在你自己的族人前方逼近。還有問題未被解答 - 預言的幻象未被目睹。回到你的領導者那裡告訴他們你在這看見了什麼。還有允諾者，如果你需要靜松的幫助，請隨時開口。', '和藍色守望的主教米奈奧斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9623 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9623, 'zhTW', '是時候了', '你在我們新家的荒野裡活了下來，並展現你的過人之處。我相信你可以協助那些血謎島前線的戰役了。阿古斯之手會需要像你這樣的$r。$B$B向『獸群管理者』托拉利斯回報。他在艾克索達外面照顧著伊萊克。把這些命令交給他，這樣他就會指示你在血謎島上的新任務。', '藍色守望的主教米奈奧斯要你將主教的命令送給『獸群管理者』托拉利斯，他就在艾克索達外面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9624, 'zhTW', '最愛的一道菜', '我發現了一件很棒的事，$c。在未受汙染的島上生長著一種超棒的水果叫沙梨。它們長在樹底下。$B$B我準備用它們來做派，但如果我一不小心，伊萊克就會開始四處遊蕩偷取我的水果。我已採集夠多水果和這些動物分享，但我的儲存量已不夠而我對派的渴望又不斷上揚。你願意幫我收集這些水果讓我做另一批派嗎?我保證會分你的!', '凱索十字路的艾昂爾要你幫他帶來10顆沙梨。', '', '去找鮮血島的艾昂爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9625, 'zhTW', '伊萊克是嚴肅的職責', '他瘋了嗎?委託這樣的事情給一個不知名的年輕$r!記住這點孩子:你永遠也無法成為一個阿古斯之手的!你沒那個本事!我想我這次得遷就他了。到血謎島和凱索十字路的渥卡恩談談。沿著往北方的路走，到了岔路時繼續往北走就對了。', '和血謎島的『伊萊克牧者』渥卡恩談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9626 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9626, 'zhTW', '會見大酋長', '你知道，我對我的家園或人民的愛從未變過。我為銀月城拼了命的打鬥才有機會和幽暗城及奧格瑪坐上同一張談判桌。$B$B這應該讓任何的對立平息下來。帶著這封信去找奧格瑪的索爾。身為部落首領的他會對接受你們種族的保證做最後的決定。$B$B我已在信上加上我自己的封印做為個人的背書。去西北方哨塔上搭乘往杜洛塔去的飛艇。', '希瓦娜斯·風行者要你將希瓦娜斯蓋章的信帶給杜洛塔首都，奧格瑪的索爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9627, 'zhTW', '效忠部落', '你的人民被聯盟狠狠的背叛。你已成功抵擋達納蘇斯和鐵爐堡間諜的攻擊。現在你又在家門前擊敗了一個強大的天譴軍團領導者。你的實力已不再值得懷疑。現在很明顯的你需要我們而我們也需要你。回到洛索瑪那裡。告訴他我清楚的收到了他的訊息。<大酋長將信在手中揉爛。>歡迎來到部落，精靈。', '回到銀月城向洛索瑪·塞隆回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9628 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9628, 'zhTW', '搶回資料', '現在幫製圖師完成他們的任務已經太遲了，但看來他們收集了通報者米可拉斯想要的資料。儲存他們調查資料的水晶不在他們的背包裡，所以它一定是在怒鱗納迦的手中。$B$B你知道通報者米可拉斯若失去了調查小組會很難過，但他還是會搶救調查資料吧。', '從死亡的製圖師附近的怒鱗身上取得勘察資料水晶，再帶回血色守望給通報者米可拉斯。', '', '去找鮮血島的通報者米可拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9629, 'zhTW', '標記魚人', '西南方海岸上的黑沙魚人是很好奇的生物。在某些方面來說，他們只是敏銳的哨兵，但其他時候，他們又展現了非凡的組織程度。$B$B我對此有一些理論，但直接最近才有真正試探他們的方法。我想出了一個辦法讓我可以追蹤我有興趣的魚人，而不會對他們造成一點傷害或干擾他們自然的行為。如果你願意幫我做標記，我會很樂意酬謝你的協助。', '血色守望的莫瑞伊要你使用魚人標示器「標記」6個黑沙斥候。', '', '去找鮮血島的莫瑞伊。', '標記黑沙斥候', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9630 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9630, 'zhTW', '麥迪文的日記', '我們已經聽說了你的名字，$n。你已成功進出卡拉贊 - 比大部分人能達到的次數還多。$B$B我要請你幫我一個特別的忙。紫羅蘭之眼一直試著尋找麥迪文的私人日記，這是我們研究的一部分。$B$B不幸的是，我們派去的密探沒有一個人回來過。瑞依恩是最後一個被派去的人，看看你能否找到他並注意任何關於日記的線索。', '逆風小徑的大法師艾特羅斯要你進入卡拉贊並和瑞依恩談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9631 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9631, 'zhTW', '朋友的協助', '我忘了考慮到一個小細節。這個骨頭碎片裡的麥迪文精華殘渣完全沒有生氣 - 就像阿坎洛格斯一樣。$B$B不過有個辦法。而且我知道誰可以幫我們。$B$B前往虛空風暴的52區，把骨頭碎片拿給凱娜·拉斯蕊德看。她會知道該怎麼做。', '將燒焦的白骨碎片帶給虛空風暴的凱娜·拉斯蕊德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9632, 'zhTW', '新找到的盟友', '通報者米可拉斯保衛血色守望的工作做的相當不錯，$c，但我們的敵人有許多，而我們的資源卻很少。$B$B敵人很清楚我們的弱點，但你和聯盟軍隊的聯繫卻是他們料想不到的。我準備了一封介紹信給奧伯丁的人民，最近的聯盟殖民地，提出合作對抗我們敵人的建議。帶著它去找艾克索達西邊碼頭附近的女獵人凱拉·夜弓。', '將介紹信交給女獵人凱拉·夜弓。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9633, 'zhTW', '去奧伯丁的路', '如果你在碼頭外等著，你就會看到從黑海岸的奧伯丁來的船抵達。等到它的乘客都下船後，你就能上船。$B$B在一小段旅程之後，船就會在奧伯丁停下，你就能遞送你的訊息了。$B$B你最好將這個交給桑迪斯·織風，我的一個老朋友也是那個鎮上很受尊敬的市民。', '從靠近女獵人凱拉·夜弓的碼頭上搭船前往奧伯丁。等你到了奧伯丁，將介紹信拿給桑迪斯·織風。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9634 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9634, 'zhTW', '外來掠奪者', '我們在旅途中學到的一件事就是當你將一個世界的野生動物帶到另一個世界時一定要格外小心。當艾克索達失事時，它裝載著各種外域的物種樣本，包括一個叫劫毀者的昆蟲掠食者。$B$B有些樣本不見了，但許多其他的還活著並開始喜歡荒地。如果我們不持續觀察它們，它們會擾亂島上的自然平衡。$B$B你可以在凱索十字路西邊找到這些劫毀者，靠近海岸的地方。', '殺死10隻血謎幼蟲後回到血謎島的凱索十字路找『伊萊克牧者』渥卡恩。', '', '去找鮮血島的『伊萊克牧者』渥卡恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9635 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9635, 'zhTW', '快速節流微粒吸取器!', '沼氣真是驚人，也非常有用，老兄!但首先，你得能夠將它吸收，這樣的話，朋友，你就需要一台快速節流微粒吸取器。$B$B我現在就能給你設計圖，不過我得先要點回報。一些備用零件如何?上次我檢查的時候，發現死亡污泥損壞的蒸汽幫浦附近有很多零件，就在東北方。$B$B我聽說枯萎的巨人在那邊的乾枯河床上四處散佈著零件。', '帶15個蒸汽幫浦零件到贊格沼澤給薩布拉金的馬克·戴沃。', '', '去贊加沼澤找薩布拉金的馬克·迪沃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9636 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9636, 'zhTW', '快速節流微粒吸取器!', '你看過沼氣嗎?是不是很閃亮?$B$B雖然這得用快速節流微粒吸取器來吸乾。我可以給你設計圖去製作，但我確切需要一些備用零件來修理這邊的器材。$B$B上次我檢查時，發現死亡污泥的蒸汽幫浦附近有許多零件散落，就在東北邊。我想是枯萎的巨人破壞幫浦所致。$B$B我們是不是該互惠一下呢?', '帶15個蒸汽幫浦零件到贊格沼澤給泰倫多爾的李小炸。', '', '去贊加沼澤找泰雷多爾的凱莉·弗萊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9637 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9637, 'zhTW', '凱娜的要求', '我離開肯瑞托是為了追求那些被我們組織所禁止的知識;諷刺的是現在我被要求用那個知識來協助他們。$B$B如果要我幫你這個忙，你就要先幫我做些事。我要你取得我一直在找的兩本秘典。$B$B第一本叫黑暗之書，是由一個叫奈德克斯的獸人術士所擁有的。第二本叫遺忘之名魔典，屬於一個阿拉卡叫做暗法師希斯。', '凱娜·拉斯蕊德要你到地獄火堡壘的破碎大廳，從大術士奈德克斯那裡取得黑暗之書，再到奧齊頓的塞司克大廳，從暗法師希斯那裡取得遺忘之名魔典。這個任務必須在英雄難度下完成。', '', '去找虛空風暴的卡琳娜·拉瑟德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9638 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9638, 'zhTW', '妥善保管', '我是要尋找日記嗎?不可能……我記不太清楚……$B$B我知道了!你想的是葛瑞戴。我到這裡的時候是他在找那本書。他現在應該已經找到了，你為何不直接去問他呢?$B$B我會助你一臂之力……但這些書真是太……有趣了!', '到卡拉贊和守護者圖書館的葛瑞戴談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9639 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9639, 'zhTW', '康席斯', '日記，什麼日記?你一定是在想康席斯。$B$B去問問她。我不能離開我的工程否則所有的努力都會白費!', '到卡拉贊和守護者圖書館的康席斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9640 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9640, 'zhTW', '埃蘭之影', '讓我想一下。紫羅蘭之眼……麥迪文的日記……對了，我現在都想起來了。$B$B在我開始讀這些卷軸前我相信我有你們要找的日記……$B$B埃蘭……對，埃蘭跟我要這本書。也正好。我必須交給他。畢竟他是麥迪文的父親，你知道嗎?', '取得麥迪文的日記並帶到卡拉贊的守護者圖書館交給康席斯。', '', '去找卡拉讚的卡姆希絲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9641, 'zhTW', '受到輻射的水晶裂片', '艾克索達失事的邪惡水晶裂片散落在整個血謎島，汙染了水源和景色。$B$B我們甚至開始在動物的肉體裡找到水晶裂片。我已找到一個方法可以淨化裂片，將它們轉變為有用的水晶，所以如果你幫我帶來足夠的裂片，我就會用一個完整的水晶和你交換。目前為止我已在熊，劫毀者，翼蛾，和樹人的身體裡找到裂片，他們都住在島上受汙染的地方。', '血色守望的復仇者波羅斯要你幫他帶來10個受到輻射的水晶裂片。', '', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9642 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9642, 'zhTW', '更多受到輻射的水晶裂片', '', '如果你有更多受到輻射的水晶裂片，我很樂意和你交換。', '', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9643 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9643, 'zhTW', '蟒藤', '一個好木匠會善用所有可利用的資源，$c。就連最奇怪的生物所擁有的特性我們都能利用。$B$B血色守望不斷遭受太陽之鷹的攻擊，我們要尋求各種天然的防禦包括陷阱。鞭笞者多刺的藤蔓很適合建造我想的陷阱。銳利的刺和致命的毒素結合會讓粗心的攻擊者落入陷阱。幫我把突變的蟒藤帶來這樣我就能開始動工。', '血色守望的追蹤者萊希安要你幫他帶來6個多刺的蟒藤。', '', '去找鮮血島的追蹤者萊希安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9644 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9644, 'zhTW', '夜禍', '我們的準備完全。我已將你收集的材料放入這個罈裡。把它帶到大師的露臺，就是打鬥的地方，放火把它給燒了。$B$B釋放出來的能量會讓阿坎洛格斯燒黑的遺體死而復生。擊敗那個生物並立刻取得它的精華!你要把它帶給艾特羅斯。$B$B如果你失敗了，星星預測你會讓天空出現一個巨大的恐懼。$B$B一個叫做夜禍的恐怖生物!', '前往卡拉贊的大師的露臺使用凱娜的骨灰罈來召喚夜禍。從夜禍的屍體取得微弱的秘法精華並帶給大法師艾特羅斯。', '', '去找逆風小徑的大法師奧圖魯斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9645 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9645, 'zhTW', '大師的露臺', '日記?什麼日記?$B$B喔，對了。那本日記!紫羅蘭之眼為此派我來這裡。現在我想起來了。$B$B<康席斯指向日記裡的一頁。>$B$B這是艾特羅斯有興趣的那頁。其他人的日記是他們回憶的記錄，你知道麥迪文的更是如此嗎?$B$B試試看。前往大師的露臺閱讀這頁，你就會知道我的意思了。也順便向艾特羅斯報告一下。我想我會在這裡再待一會兒。', '前往卡拉贊的大師的露臺並閱讀麥迪文的日記。完成任務後帶著麥迪文的日記回到大法師艾特羅斯那裡。', '閱讀日記', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9646 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9646, 'zhTW', '懸賞:死亡之爪', '通報者米可拉斯的命令:以18銀懸賞帶著死亡之爪，一隻潛行捕食的熊已死的證據回來的勇敢靈魂。$B$B死亡之爪是極為危險的生物，在血色守望西北方的海岸殺死了一批調查小組。旅人最好都避開那個區域。', '將死亡之爪的爪子帶給血色守望的通報者米可拉斯。', '', '去找鮮血島的通報者米可拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9647 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9647, 'zhTW', '撲殺翼蛾', '當我們第一次碰到翼蛾時，他們沒有什麼突變的跡象。隨著汙染日益嚴重，飛蛾和其他物種便開始出現受汙染的跡象。$B$B現在已經進展到和他們接觸的所有生物幾乎都遭到損害了。他們正在擴大艾克索達失事後散落的水晶裂片所造成的傷害。我們別無選擇只能開始削減他們在血色守望北邊的數量。', '血色守望的追蹤者萊希安要你殺死10隻皇家藍翼蛾。', '', '去找鮮血島的追蹤者萊希安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9648 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9648, 'zhTW', '麥克艾瑞野生蘑菇', '你知道採集蘑菇比消耗蘑菇更危險嗎?蘑菇採收者置身於許多未知 - 不包括潛在 - 的野生生物危機中。$B$B如果沒有危險會是什麼樣子?我需要收集蘑菇。你會在這些未探勘的荒野中找到四個不同的品種:水生惡菌菇，血色蘑菇，有害的孢子群，和魔錐果真菌。它們都是血謎島上獨特的品種。把它們帶來給我。', '血色守望的潔希拉·麥克艾瑞要1個水生惡菌菇，1個血色蘑菇，1個有害的孢子群，和1個魔錐果真菌。', '', '去找鮮血島的潔希拉·麥克艾瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9649, 'zhTW', '伊瑟拉之淚', '再見到你真好，$N!你在完成我給你的最後一個任務時真是異常地有效率。或許你對另一個任務有興趣?$B$B東北方有個龍痕島，一種名罕見蘑菇生長在那邊，伊瑟拉之淚 - 以住在那座島上的綠龍軍團為名。我只需要一個蘑菇小樣本，但我一定要警告你島上的居民不歡迎訪客。步步為營。', '血色守望的潔希拉·麥克艾瑞要2個伊瑟拉之淚。', '', '去找鮮血島的潔希拉·麥克艾瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9650 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9650, 'zhTW', '擴大魔法', '很好，讓我們提升我的魔法屬性吧。這有道理。畢竟我是個巫師。$B$B因為一個人的身體器皿是武器並不表示那個人就是畜生。$B$B我要你去收集一些材料。', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9651 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9651, 'zhTW', '擴大魔法', '很好，讓我們提升我的魔法屬性吧。這有道理。畢竟我是個巫師。$B$B因為一個人的身體器皿是武器並不表示那個人就是畜生。$B$B我要你去收集一些材料。', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9652 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9652, 'zhTW', '體力提升', '我不介意。我們也要充份利用我們的情況……以我來說，就是武器。或許也可能成為我最好的武器。$B$B沒錯，就這麼辦。一個銳利的刀口，一個堅固的刀柄……我喜歡它的音調。$B$B我要你去幫我收集一些東西。', '', '', '去找金娜之影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9653 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9653, 'zhTW', '體力提升', '我不介意。我們也要充份利用我們的情況……以我來說，就是武器。或許也可能成為我最好的武器。$B$B沒錯，就這麼辦。一個銳利的刀口，一個堅固的刀柄……我喜歡它的音調。$B$B我要你去幫我收集一些東西。', '', '', '去找金娜之影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9654 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9654, 'zhTW', '面面俱到的防禦', '進攻性魔法是我的專長……這我還記得。我會盡力將我的秘法引導力量加到你那裡。$B$B不過我需要更多的純粹原始力量。閒晃在守護者圖書館較高層的秘法反常者會是很好的目標。收集他們的秘法殘餘，我們需要很多的量。', '琪安娜的遺囑裡的琪安娜的斷面要你從卡拉讚的秘法反常者身上收集20個秘法殘渣。', '', '去找金娜之影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9655 AND `locale` = 'zhTW';
