INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9661, 'zhTW', '面面俱到的防禦', '進攻性魔法是我的專長……這我還記得。我會盡力將我的秘法引導力量加到你那裡。$B$B不過我需要更多的純粹原始力量。閒晃在守護者圖書館較高層的秘法反常者會是很好的目標。收集他們的秘法殘餘，我們需要很多的量。', '琪安娜的遺囑裡的琪安娜的斷面要你從卡拉讚的秘法反常者身上收集20個秘法殘渣。', '', '去找金娜之影。', '', '', '', '', 0);
