INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9662, 'zhTW', '琪安娜的自由', '我的記憶……我現在全部都記起來了！我的腦袋像拼圖忽然間拼湊在一起。$B$B我是卡拉贊改變後第一批被派去調查那裡的人。惡魔莫克札發現了我的侵入。$B$B我很快就知道我不是他的對手。我開始感覺我的靈魂被他的魔法抑制。$B$B在最後一刻我將自己的一部分藏起來……將一部分的記憶藏在我唯一能想到的地方:我的武器裡。莫克札掌握了我的靈魂。你一定要幫我取回它！', '打敗卡拉贊裝備著琪安娜意志的莫克札。琪安娜的斷面一定要活下來。', '', '去找金娜之影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9663, 'zhTW', '幫凱索的忙', '你來的正好，$N。這區域的血精靈活動在過去一個禮拜已經加倍了。我們的密探告訴我們自稱為太陽之鷹的血精靈計畫要對藍謎島發動攻擊。我要你去警告一下我們的盟友和同伴。$B$B警告靜松要塞的大酋長靜松，藍色守望的主教米奈奧斯，和奧迪席斯平臺的艦隊司令·奧迪席斯。$B$B時間緊迫所以我借你我的伊萊克。記得不能讓它碰到水。', '凱索十字路的凱索要你去警告靜松要塞的大酋長靜松，藍色守望的主教米奈奧斯，和奧迪席斯平臺的艦隊司令·奧迪席斯關於血精靈即將發動的攻擊。完成任務後回到凱索那裡。你只有15分鐘。', '', '去找鮮血島的凱索。', '已警告大酋長靜松', '已警告主教米奈奧斯', '警告艦隊司令·奧迪席斯', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9664, 'zhTW', '建立新前哨', '歡迎來到瘟疫之地，$n。如你所知，被遺忘者和他們的盟友佔據著西邊的土地。聯盟指揮官已決定要在東邊建立新的防禦工事來強化我們敵人周圍的陷阱。$B$B早自羅德隆被奪取並因此目的重建時哨塔就被廢棄了。這些土地很危險，我們需要你的幫忙。', '佔領東瘟疫之地的皇冠哨塔，東牆之塔，北地哨塔和病木林哨塔，再回到聖光之願禮拜堂的密使·白鬚那裡。', '', '去東瘟疫之地找聖光之願禮拜堂的白鬚大使。', '佔領皇冠哨塔', '佔領東牆哨塔', '佔領北地哨塔', '佔領病木林哨塔', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9665, 'zhTW', '增強防禦', '被遺忘者密探揭發了聯盟的秘密計畫，他們要在東瘟疫之地被廢棄的哨塔上建立新基地。$B$B現在要緊的是我們不能讓他們在東部邊界建立重要的據點，所以我們一定要趕走這批聯盟入侵者。我們目前的計畫是把他們可能已攻佔的所有哨塔中趕走，並佔據控制那些哨塔不受進一步的攻擊。', '佔領東瘟疫之地的皇冠哨塔，東牆之塔，北地哨塔和病木林哨塔，再回到聖光之願禮拜堂的密使·戈馬克那裡。', '', '去東瘟疫之地找聖光之願禮拜堂的密使·戈馬克。', '已奪得皇冠哨塔', '已奪得東牆之塔', '奪得北地哨塔', '奪得病木林哨塔', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9666, 'zhTW', '宣示力量', '你有看過毒蛇人嗎?就是自稱納迦的那些人?$B$B<凱索吐了一口口水。>$B$B他們竟敢在三天前趁著夜色的掩護向這營地進軍。你相信那些原始野獸的膽大妄為嗎?$B$B我要你送一個訊息給他們的領導者，$N。東北方的怒鱗巢穴是希司領主的家。找到他，殺了他，把這支旗幟插在他的屍體上。$B$B讓他們知道每當看見我們的軍旗，就是該害怕的時候!', '血謎島，凱索十字路的凱索要你殺了怒鱗巢穴的希司領主，並將德萊尼旗幟插入他的屍體。', '力量的宣言', '去找鮮血島的凱索。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9667 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9667, 'zhTW', '拯救靜松公主', '救救我，$N!鬚肢熊怪把我抓來並且打算將我獻祭給他們骯髒的神祇!$B$B大酋長鬚肢握有開啟籠子的鑰匙。要逼他現身，你必須殺死邪惡的鬚肢熊怪，位置就在這座營地西邊的兩座鬚肢熊怪營地。如果你殺了夠多熊怪，他就會出來報仇!當他出現的時候，殺了他並拿到鑰匙!$B$B如果你救了我，我的父親會重重答謝你的!', '釋放囚禁在籠子裡的靜松公主後與血色守望的靜松大使歐洛格談談。$B$B你得殺掉大酋長鬚肢才能得到籠子的鑰匙。', '', '去找鮮血島的靜松大使法薩布。', '已拯救靜松公主', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9668, 'zhTW', '向主教阿德密特斯回報', '一個阿古斯之手的士兵代表了很多意義:服從，勇敢，智慧，和最重要的，高尚。你或許還沒展現出這些特質，$c。如果你還對加入阿古斯之手有興趣，就向血色守望的主教阿德密特斯回報吧。他和他的部屬會進一步的以德萊尼士兵的方式訓練你。還有記住，$N:高尚的人不會永遠都做高尚的事，有時候他們身不由己。沿著這條路往北走你就可以找到血色守望。', '和血色守望的主教阿德密特斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9669, 'zhTW', '失蹤的遠征隊', '大概一個禮拜前，當我和我的研究小組在血謎島西邊的荒野探勘時，遭到嗜血的蜘蛛攻擊。水晶汙染的效果非常明顯，因為這些蜘蛛體型變得既龐大又極具攻擊性。$B$B我設法逃了出來，但我的組員就沒這麼幸運。我們不能讓同樣的命運降臨在其他人身上。去西邊的琥珀網小徑殺死蜘蛛和他們的女王，沙拉克。', '殺死8隻謎霧紡紗者，8隻謎霧吸血者和他們的領導者，沙拉克。任務完成後回到血色守望找阿奇拉斯。', '', '去找鮮血島的阿奇拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9670 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9670, 'zhTW', '他們還活著!或許吧……', '那真是一場血戰啊，$N。我們被一大群蜘蛛給突襲。他們的祖先用不可思議的速度向我們蜂擁而上並把我們包在繭裡。$B$B在我們被纏住後，她開始在我們附近產卵。我們就要成為她幼蟲的食物了!是食物!$B$B我設法逃了出來，但我沒辦法丟下其他人不管。目前為止我都無法成功接近那裡。你可以伸出援手嗎?$B$B摧毀那些繭!希望我們的隊員還有人活著!', '研究員卡尼勒斯要你救出5個遠征隊研究員。', '', '去找鮮血島的研究員卡尼勒斯。', '已釋放遠征隊研究員', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9671, 'zhTW', '緊急送件', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9672 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9672, 'zhTW', '血咒遺產', '親愛的朋友，我顫抖著手寫下這封信。我希望它能及時送到你手中。昨天夜裡，「失望」號的船長，艾德華·漢尼斯出現在我帳篷前面。和20年前因壞血病而死的艾德華·漢尼斯一模一樣。這個亡魂告訴我一個讓我的心不停顫抖的故事。一個我要你聽的故事和一個我要你完成的任務。你願意接受嗎?你願意去基地東北方的龍痕島找艾德華嗎?艦隊司令·奧迪席斯，敬上', '艦隊司令·奧迪席斯要你找到隊長艾德華·漢尼斯並和他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9673 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9673, 'zhTW', '野獸訓練', '除了和你選擇的寵物合作之外，你還必須學會一套照顧和訓練它的學問。為此，銀月城的野獸訓練師海德尼斯可以指引你的道路。$B$B只要我的學生對他展現最大的敬意，他也會尊敬他們。別讓我失望。', '和銀月城的海德尼斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9674, 'zhTW', '血咒納迦', '他們說當世界分裂的時候，這座島是最悲情的。數千條夜精靈性命在這裡犧牲而被世人遺忘，原本屬於夜精靈的土地如今興起了為仇恨而生的可怕生物 - 納迦。$B$B他們效忠於他們瘋狂的女王艾薩拉，誓要殺光任何膽敢穿越他們海洋的人。這種情形將會持續數千年，但是現在將要改變。$B$B任務的第一個命令就是解決掉沙洲的血咒納迦。', '龍痕島的隊長艾德華·漢尼斯要你殺死10個血咒納迦。', '', '去找鮮血島的隊長艾德華·漢尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9675, 'zhTW', '野獸訓練', '喔，還有一件事!你要和艾克索達的加納談談。他能教你最後一點必要的知識來照料和訓練你的寵物。$B$B你可以在貿易區西南方的角落找到他。', '到艾克索達的貿易區和加納談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9676, 'zhTW', '聖騎士訓練', '當你在職業中不斷進步，你會想從職業訓練師所能提供你的訓練中獲得助益。對逐日者之島這裡的年輕聖騎士而言，你們的訓練師是傑斯賽尼斯·擊日者。和傑斯賽尼斯談談，看他能提供什麼訓練給你。他的訓練需要收費，所以帶一些錢在身上。你的訓練師 - 和逐日者之島上所有的訓練師一樣 - 都在日尖塔的較低層。', '和傑斯賽尼斯·擊日者 - 聖騎士職業訓練師 - 談談，他就在逐日者之島的日尖塔裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9677, 'zhTW', '騎士領主伯洛德瓦勒的召喚', '$n，你在先前訓練中的表現相當出色並在那些可能成為血騎士的人中脫穎而出。你已經準備好接受下一個階段的訓練了，為達此目的，騎士領主伯洛德瓦勒本人已表示要和你談談。$B$B我相信騎士領主伯洛德瓦勒要給你一個試煉來考驗你的能力和訓練。你可以到銀月城的遠行者廣場，在血騎士總部找到他。祝你好運，$n。', '到銀月城的遠行者廣場和騎士領主伯洛德瓦勒談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9678, 'zhTW', '第一個試煉', '你已經學到很多關於戰鬥和殺人的事了，初學者，但我們的軍隊中還有很多事要學。$B$B聖光的專精需要專注的心志和極大的意志力。沒有這些，你不過只是個街頭暴徒。$B$B鬼魂之地東北方區域有一座島，叫做磨難之島，那是我們用來磨練這些技能的地方。你會在那裡一個淺淺的洞穴裡找到一個火盆。在火盆前跪下，點燃它，並專注於你眼前看到的東西。', '前往騎士領主伯洛德瓦勒所描述的島，找到洞穴，並點燃火盆。當第一個試煉結束，回到銀月城的騎士領主·伯洛德瓦勒那裡。', '', '去找永歌森林的騎士領主布拉德瓦羅。', '完成第一個試煉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9679 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9679, 'zhTW', '回到騎士領主伯洛德瓦勒身邊', '你的襲擊者已死，但他的話聽起來好像他出現在這裡不是個意外。這隻能代表騎士領主伯洛德瓦勒所說的試驗的一部分。$B$B你在苦難中活了下來並完成了騎士領主要你做的事，你應該回到銀月城向他報告。', '向銀月城的騎士領主伯洛德瓦勒報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9680 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9680, 'zhTW', '發掘過去', '康席斯是對的!這個消息真的極為重要。$B$B如果麥迪文將他自己的精華融入他使用的魔法來擊敗巨龍，那我們很有可能從龍的殘骸中取得同樣的微量精華殘餘。如此一來它很有可能埋在逆風小徑的灰燼之下，等待被人發掘。$B$B前往卡拉贊南方的山脈，幫我把一個似龍的起源的骨頭碎片帶來。', '大法師艾特羅斯要你去卡拉贊南方山脈的逆風小徑取回一個燒焦的白骨碎片。', '', '去找逆風小徑的大法師奧圖魯斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9681, 'zhTW', '學習力量', '別認為我過於嚴厲，$n。靜刃清楚的知道他的任務目的。他了解並接受他的職責，他是所有胸懷抱負的血騎士的表率。$B$B我不是在致哀悼詞，$n。靜刃效命我們的時間還沒那麼快結束，而你就是要讓他復活的那個人。$B$B你在騎士團中的訓練才剛開始。凱爾薩斯的背叛還有失去我們力量的來源，你得學習新的方法來使用聖光。去找博學者阿斯塔樂·血誓吧。', '到血騎士總部底下隱藏的房間裡和博學者阿斯塔樂·血誓談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9682, 'zhTW', '絕望者……', '在沙洲的突出處，比你發現血咒納迦再深入一點的地方，可以找到絕望者:血咒航海者，那些被血咒抓去的鬼魂。$B$B我現在要你做的事，讓人感到不忍心……但他們一定要被消滅並把他們被詛咒的軀殼帶回來給我。$B$B他們的靈魂一定要得到安息。等你完成了我要求的事情再回來找我，我就會給你最後的一個任務。', '龍痕島的隊長艾德華·漢尼斯要你帶回4個血咒靈魂。', '', '去找鮮血島的隊長艾德華·漢尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9683 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9683, 'zhTW', '終止血咒', '你會在南方找到血咒島。在島的頂端你會找到一座獻給摯愛的納迦女王，艾薩拉的神殿。摧毀那個雕像 - 把它燒毀!這一定會引起阿托夫，血咒領導者的憤怒。$B$B殺了阿托夫再回來找我!', '龍痕島的隊長艾德華·漢尼斯要你摧毀艾薩拉女王雕像並殺了血咒的阿托夫。', '', '去找鮮血島的隊長艾德華·漢尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9684, 'zhTW', '掌握聖光', '拿著這個容器，$n。容器上的魔法可以讓你吸取那些博學者身上殘存的聖光。他們曾經負責禁錮那魯，它的能量依舊存留在他們身上。$B$B這樣正好足夠你來復活你的同伴。$B$B別擔心這些博學者，$n。我會照料他們，索拉納爾領主向我保證，莉雅德倫女士至今仍在尋找新的力量來源。', '在血精靈博學者身上使用幻光容器來裝滿它，再回到銀月城的騎士領主伯洛德瓦勒那裡。', '', '去找永歌森林的騎士領主布拉德瓦羅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9685 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9685, 'zhTW', '解救亡者', '在你準備容器的時候，我派了一組新人去挽救桑古瑞斯·靜刃。他和一個侍者在銀月城旅店的頂樓。用你最快的速度到那裡並釋放容器的魔法讓他復活。$B$B時間緊迫，$n。一旦他死去太久，就連聖光也無法將他救回來了。等你讓靜刃復活了再來找我。', '帶著裝滿的幻光容器到銀月城旅店並使用它的魔法來復活桑古瑞斯·靜刃。', '', '去找永歌森林的騎士領主布拉德瓦羅。', '復活桑利亞斯·靜刃', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9686 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9686, 'zhTW', '第二個試煉', '你站在騎士團中高手的邊緣，$n。首先，你必須接受另一個試煉來證明自己的價值。$B$B第二個試煉和第一個不同，因為這次將不會有驚喜。你眼前的挑戰是簡單的;你一定要在戰鬥中挑戰並打敗四個血騎士勇士。$B$B等你接受挑戰，亭子中央就會出現一個水晶。觸摸它來開始你的試煉，並且不要離這棟建築物太遠。$B$B你準備好了嗎?', '完成第二次的試煉，在大師克萊倫‧布勞德摩爾附近的亭子裡擊敗血怒勇士，勇士萊特蘭德，迅刃勇士，及勇士桑司瑞克。', '完成第二項試煉', '去永歌森林找銀月城廢墟的克雷倫·血傷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9687, 'zhTW', '恢復聖潔', '不久以前，區域裡曾經平靜的梟獸出現在島的海岸。他們會一個接一個來偷取陣亡的龍骨。我不知道是什麼讓這些生物這樣苦惱，或是他們為什麼會想要死者的骨頭，但那些後裔的靈魂因為這樣悖理逆天的行為無法安息。$B$B到西邊去，穿過赤紅地帶，你會找到怒羽山脊。進入梟獸營地取回被偷走的龍骨。', '龍痕島的托瑞斯王子要你取回8根龍骨。', '', '去找鮮血島的托瑞斯王子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9688 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9688, 'zhTW', '進入夢境', '你在這島上看到的幼龍都是綠龍軍團被激怒的靈魂。就像我一樣，他們都被束縛在這塊土地上，無法回到他們在夢境之國的最後安息之地。$B$B取得亡者的骨頭會暫時讓他們平息下來，但你一定要採取進一步的行動。$B$B解放他們永恆的束縛。在完成之前我不能離開這裡。他們一定要被釋放!', '龍痕島的托瑞斯王子要你殺死5隻翠綠色幼龍和5隻翠綠色小龍。', '', '去找鮮血島的托瑞斯王子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9689 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9689, 'zhTW', '瑞索默', '許多黑龍軍團的成員都在攻擊中被殺了。這些亡魂中有一名死亡之翼的副官，他的靈魂現在還出沒在這個地方。如果你望著天空，你會看見他的鬼靈面容在空中環繞。他的仇恨心太重以致於連死後都還心懷憤恨。$B$B帶著你先前為我收集的骨頭到這座島的山頂上，將它們放在永不熄滅的柴堆裡。此舉會發出一種訊息使瑞索默降下來查看究竟。到時候就殺死他的不死身驅。', '龍痕島的托瑞斯王子要你殺了瑞索默。', '', '去找鮮血島的托瑞斯王子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9690 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9690, 'zhTW', '第二個試煉', '新加入的$n，你很努力的精進我們博學者傳授給你的聖光力量。你學到了我們能力的來源和身為血騎士的職責。$B$B是時候讓你接受第二個試煉和獲得血騎士高手身份的競賽了。這個試煉會由大師克萊倫·布勞德摩爾在城的北方所主持。穿過銀月廢墟前往北方，在快要到達通往逐日者之島的橋之前往東邊的路走。', '向大師克萊倫·布勞德摩爾回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9691 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9691, 'zhTW', '回到銀月城', '立刻回到銀月城向騎士領主伯洛德瓦勒報告。你的出現會讓他知道你已經通過試煉了。$B$B他會告訴你成為一個高手之路上還剩下什麼考驗。抬起你的頭，$n。許多人接受過這個試煉，但很少人能凱旋歸來。', '回到銀月城的騎士領主伯洛德瓦勒那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9692 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9692, 'zhTW', '高手之路', '在一個新的高手正式成為血騎士軍官前，<他/她>一定要取得製作我們騎士團特有武器，血淬三叉矛的材料才行。$B$B你也一定要贏得穿戴上我們騎士團徽記的權利。當騎士團成立時，固定的編號就已分配給每一個人了，所以每個新的高手就會從一個老手接過<他的/她的>號碼。你的徽記來自一個在死亡之域勇敢率領突襲部隊的陣亡騎士。$B$B我準備好了一份筆記要指引你。', '將一顆被污染的科爾寶石，血鑄錠木箱，大量憤怒之血，和一個血騎士徽記帶給銀月城的騎士領主伯洛德瓦勒。', '', '去找永歌森林的騎士領主布拉德瓦羅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9693 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9693, 'zhTW', '阿古斯對我的意義', '阿古斯對你而言有什麼意義，$N?你大概和許多德萊尼一樣不知道或不記得我們的家園。我們在那裡和曼那瑞分開:那是薩格拉斯『賦予』我們一族的扭曲惡魔形態，或是如他們所自稱的，埃雷達爾。埃雷達爾……這個字曾經有它的意義。<阿德密特斯好像在品嚐這個字一樣。>真噁心。不要再浪費時間了。找到復仇者波羅斯展開你的訓練。', '血色守望的主教阿德密特斯要你去和復仇者波羅斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9694 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9694, 'zhTW', '血色守望', '你知道，血色守望是阿古斯之手運作的兩個前鋒基地之一。你已經去過另一個基地藍色守望了;血謎島的情形是完全不同的。當我們第一次到這裡，這片土地是和藍謎島一樣美麗的。我們甚至還稱它為銀色歡地，但是現在疾病散播大地，而更糟的是，我們在艾克索達對抗的血精靈從失事中生還了。這讓我想到你的第一個任務:前往西北方的劍木林除掉所有你見到的血精靈。', '血色守望的復仇者波羅斯要你殺死10個太陽之鷹間諜。', '', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9695 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9695, 'zhTW', '太陽之王的命令', '這份公文非常重要。不幸的是它所使用的語言是你不能理解的嚮導語。$B$B或許Vindicator Boros能看懂。', '將太陽之王的命令帶給血色守望的復仇者波羅斯。\\r\\n\\r\\n', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9696 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9696, 'zhTW', '翻譯……', '我們的首席審問者伊萊希雅會說流利的薩拉斯語。把文件帶給她，看看她怎麼說。', '將太陽之鷹書信帶給血色守望的審問者伊萊希雅。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9697 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9697, 'zhTW', '看守者里薩歐', '當地生物的生態中有一項重要的研究要進行。尤其是泥沼裡的孢子生物跟泥沼領主。相信我，一旦你進入那個區域，你將會發現那裡的工作極具挑戰性。$B$B到南方的泥沼西區找到塞納里奧看守站，和看守者里薩歐談談。沿著路往西走你就會找到她了。她有點 - 心無旁鶩 - 但別因此而影響你找她的目的。$B$B噢，當心她的貓。', '到贊格沼澤的塞納里奧看守站和看守者里薩歐談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9698 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9698, 'zhTW', '覲見預言者', '我要你把翻譯的文件親自交給費倫，$N。我不信任那個笨手笨腳的信差。$B$B向預言者解釋血精靈正在從外域接收援軍，他們在艾克索達的德萊尼之中有個間諜。費倫住在艾克索達的聖光地窖。$B$B動作快!', '將翻譯太陽之鷹的書信帶給艾克索達的預言者費倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9699 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9699, 'zhTW', '是真是假', '謝謝你及時的送達，$N。你將要成為阿格斯之手優秀的密探之一了。$B$B要是我們能知道他們在血謎島向誰報告那就好了，還有更重要的，太陽之門在什麼地方……他們似乎有重重戒備 - 不管它是在什麼地方。$B$B你有興趣接一些勘察的工作嗎?$B$B如果可以，請帶著這些命令回到復仇者波羅斯那裡。他會給你下一個任務。', '將費倫的命令帶給血色守望的復仇者波羅斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9700 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9700, 'zhTW', '向黑暗中發射魔法', '費倫表示如果血精靈已在這座島和外域間開啟了裂縫，傳送門開啟的地方就會有召喚儀式的殘餘物或異常者出現。你一定要搜索島上有顯現出這些異象的地方。$B$B小心，$N;有些異象是從虛無本身來的生物。如果你發現虛無反常者，就殺了他們!帶著你找到的新資訊回來向我報告。從北邊開始你的搜索，靠近星移活塞的地方。', '血色守望的復仇者波羅斯要你找到太陽之門地點並殺死5個虛無反常者。', '已確認太陽傳送門地點', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9701 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9701, 'zhTW', '觀察孢子人', '我們要盡可能了解斯博格爾的孢子人和他們與其他生物的關係。方法就是我現在正在進行的;被動觀察記錄下他們的互動關係。$B$B我要你沿著往西方的路前往重生峽谷。調查整個區域再回來告訴我你所看到的。', '調查贊格沼澤的重生峽谷，再將你的發現帶回贊格沼澤向塞納里奧看守站的看守者里薩歐回報。', '調查孢殖林', '去贊加沼澤找塞納里奧崗哨的觀察者莉薩奧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9702 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9702, 'zhTW', '暴食的問題', '我不懂為什麼泥沼領主會穿過道路到重生峽谷 - 他們這麼餓一定是有原因的。這樣是不對的!$B$B我是說，通常我不會捲入其中，但如果他們持續吃光所有的孢子囊是會把他們滅絕的!$B$B我們就這麼辦:我留在這裡，你前往東邊的跨格山脊尋找他們突襲孢子人並且把他們當成食物的線索。', '收集10份被丟棄的營養品再回到贊格沼澤的塞納里奧看守站找看守者里薩歐。', '', '去贊加沼澤找塞納里奧崗哨的觀察者莉薩奧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9703 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9703, 'zhTW', '冬眠核心', '我們還有其他人在尋找太陽之門的線索，$N。我要你先專注於手上的工作。$B$B波羅斯收到一則新報告指出有另一個失事地點。我們發現那個失事地點就是艾克索達的冬眠核心。這是覆蓋船艙的支撐區域，就和我們德萊尼從安曼谷爬出來的那個船艙一樣。$B$B這個區域也有醫療補給。前往冬眠核心，就在血色守望正西邊。尋找物資及生還者。', '血色守望的復仇者庫羅斯要你取得12箱醫療補給。', '', '去找鮮血島的復仇者庫羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9704 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9704, 'zhTW', '鄙惡者兇手', '做為往返逐日者之島和內獵鷹之翼廣場的先驅者不是一件簡單的工作。時間緊迫，工時冗長，更糟的是...還有鄙惡者!$B$B南方穿過銀月廢墟的路...那地方到處都是為了區區幾塊法力水晶而準備殺死你的鄙惡者。不幸的是，我想我們上次派去送伊羅娜包裹的先驅者已經慘遭毒手。$B$B我看到你積極的想證明自己。進入黎明小路看你是否能找到我們先驅者的蛛絲馬跡。', '往南進入銀月廢墟的黎明小路尋找被殺的先驅者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9705 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9705, 'zhTW', '重獲包裹', '你接過並確認這個包裹真的是從博學者伊羅娜那裡來的。艾拉瑞恩或許會要你把它帶給她。', '將伊羅娜的包裹帶給先驅者艾拉瑞恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9706 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9706, 'zhTW', '高拉恩的日誌 - 復仇者薩魯安的命運', '你的手顫抖著撿起書。庫羅斯一定知道這個悲劇了。將書還給他。', '將高拉恩的日誌帶給血色守望的復仇者庫羅斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9707 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9707, 'zhTW', '鑄造武器', '你再一次地在部隊還有同儕面前證明了自己的價值。我很高興賜予你高手的階級，$n。凱爾薩斯王子本身都會為你感到驕傲。$B$B我們任何人都會因為在你身旁作戰而感到光榮。持續為那些想加入我們的人做榜樣。不要顯露仁慈或軟弱，不辭辛勞地保衛你的族人和兄弟，磨練你的聖光專精技巧。$B$B現在，拿走符合你新階位的武器吧。', '把原料木箱帶給銀月城的貝瑪倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9708 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9708, 'zhTW', '熟悉的蘑菇', '沒錯，就是它，我就知道我在泥沼的其他地方有看過這種特別的蘑菇!$B$B北方有個叫開闢泥沼的地方。如果你問我的話我會說這地方的名字真怪，不過我沒去過那裡。我需要那些蘑菇的樣本來證實我的假設。$B$B小心點，$c。我聽說巨魔搬到那一帶了，所以你要從他們那裡拿到樣本。這會不會是泥沼領主不再到那邊覓食的原因呢?', '收集15個蘑菇樣本再回到贊格沼澤的塞納里奧看守站交給看守者里薩歐。', '', '去贊加沼澤找塞納里奧崗哨的觀察者莉薩奧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9709 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9709, 'zhTW', '偷回蘑菇', '$c，我有個想法。我要你再次前往北方，這次要到巨魔領土的中心!$B$B開闢泥沼西北方有個叫安格拉斯要塞的地方，就在一座大型蘑菇橋對面的漂浮島嶼上。$B$B巨魔一定把收割的蘑菇儲存在那裡。我保證一定到處都看的到，或許有些巨魔身上也有!$B$B幫我帶來足夠數量的蘑菇我就能試著提供泥沼領主一些新的營養來源。', '收集10箱蘑菇再回到贊格沼澤的塞納里奧看守站交給看守者里薩歐。', '', '去贊加沼澤找塞納里奧崗哨的觀察者莉薩奧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9710 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9710, 'zhTW', '血淬三叉矛', '我已準備好一切了，$n。你很快就會有和新身份相稱的武器了。', '等待貝瑪倫幫你鑄造武器。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9711 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9711, 'zhTW', '殘忍的馬帝斯', '馬帝斯會得到正義的，$N;我要你找到他並把他帶回三頭政治。$B$B搜索島嶼找到這個混蛋。如果你找到他，就使用這把信號槍。我的追蹤者看到閃光就會前去協助逮捕馬帝斯。抓到他後再來找我。', '血色守望的復仇者庫羅斯要你抓到殘忍的馬帝斯。', '殘酷的馬提斯已捕獲', '去找鮮血島的復仇者庫羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9712, 'zhTW', '薩拉斯戰馬', '你在騎士團中的服務非常優異而出色，$N。你對聖光之力的運用技巧證實了魔導師阿斯塔洛與他的同伴教授你這些知識的努力沒有白費，他們的工作是值得的。$B$B既然你已經掌握了聖光的力量，那麼你完全可以召喚出一匹健壯的戰馬，作為你忠實的坐騎。$B$B繼續為騎士團帶來貢獻與榮耀吧，$N，更加美好的前臺在等待著你。', '與騎士領主布拉德瓦羅交談，學習如何召喚你的薩拉斯戰馬。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9713, 'zhTW', '白閃菇可採集標誌', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9714 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9714, 'zhTW', '再給我木槿花!', '', '', '', '去贊加沼澤找孢子村的舒特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9715 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9715, 'zhTW', '給我木槿花!', '我們一定要補充多用途的血紅木槿庫存量。它們以前都長的和灌木一樣肥厚，但泥沼水位下降後就只能在盤牙蓄湖的深幽泥沼找到它們，在毒蛇之湖底下。$B$B據說那裡的搖晃者，泥沼巨人，和深幽泥沼蝙蝠都認為它們是美味佳餚。所以，如果你要幫我們，就一定要從他們那裡取回花朵。', '收集5朵血紅木槿再回到贊格沼澤的斯博格爾交給卡思汗特。', '', '去贊加沼澤找孢子村的舒特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9716 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9716, 'zhTW', '昂布拉凡湖的憂慮', '我們期望在外域找到一小塊有生氣的地方。在贊格沼澤發現的是有著蓬勃生態的蒼翠環境。$B$B然而，我們對這個區域最初的評估是錯誤的。從我們開始測量以來，湖泊和沼澤的水位已不斷地下降。$B$B這樣的衝擊對當地的動植物而言是個災難。前往西南方的昂布拉凡湖，尋找這個水量銳減的線索。', '調查昂布拉凡湖水量銳減的原因。再回到贊格沼澤的塞納里奧避難所找伊斯歐·風歌。', '調查暗澤湖', '去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9717 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9717, 'zhTW', '喔，開始吧!', '雖然我們是個崇尚和平的民族，但我們仍要與孢子巨人作戰，不論我們願不願意。我們之間有著一句格言，人人都有蘑菇人人都要作戰!$B$B有個孢子巨人領導者，飢餓泥沼，種植了一種非常特別的植物叫地孢，它可以保存完美好幾千年。如果那個植物發生了什麼事，他絕對會心痛不已。$B$B去盤牙蓄湖的深幽泥沼，幫我們偷來一片葉體。相信我，他一定會發現的。', '收集一片地孢之葉交給贊格沼澤的斯博格爾的塔蘇。', '', '去贊加沼澤找孢子村的塔蘇。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9718 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9718, 'zhTW', '烏鴉高飛時', '我們一定要確定納迦的活動範圍有多大再對症下藥。$B$B勘察贊格沼澤所有的水域是一個很冗長的工作。如果你允許的話，我會使用我的魔法將你的形體鑄造成一個更適合偵察沼澤的模樣。$B$B等你準備好開始就將這個護符高舉至我附近的陽台上。完成後我會引導你安全的回來。', '伊斯歐·風歌要你使用暴風烏鴉護符來探勘贊格沼澤的主要湖泊。', '調查贊加沼澤的湖泊', '去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9719 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9719, 'zhTW', '追蹤獵捕者', '從歷史上來看我們族人最大的危險就是來自泥沼行者。我們正在面對孢子巨人所帶來的麻煩，無法再承受古老敵人的攻擊。$B$B你已證明自己是有能力的，$c。你覺得你能前往盤牙蓄湖的深幽泥沼消滅巨大的泥沼行者之母，黑色捕獵者嗎?$B$B把她的腦袋帶來給我做為證據。', '把黑色捕獵者的大腦帶給贊格沼澤的斯博格爾的奇尼克斯。', '', '去贊加沼澤找孢子村的肯尼克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9720 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9720, 'zhTW', '一定要保持平衡', '我不能了解為什麼納迦會把水從他們自己的棲息地抽走。但我所了解的是需要阻止他們的運作。$B$B這些種子帶著大地的憤怒。把它們帶到納迦操作的蒸汽幫浦那裡並在他們的控制中使用它們。$B$B種子生長出來的藤蔓會和你的臂膀一樣粗，和鋼鐵一樣堅固。去吧，$n。恢復納迦打亂的平衡吧。', '伊斯歐·風歌要你在毒蛇之湖、昂布拉凡湖、沼澤光之湖和瀉湖的蒸汽泵使用鐵藤之種。再帶著未使用的種子回到贊格沼澤的塞納里奧避難所找她。', '', '去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。', '破壞暗澤湖控制檯', '破壞沼光湖控制檯', '破壞毒蛇湖控制檯', '破壞環礁湖控制檯', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9721, 'zhTW', '索拉納爾領主的召喚', '你對我們騎士團的奉獻和在階級的晉升都獲得了注意。事實上，索拉納爾·血怒領主，莉雅德倫女士的左右手，一位真正的英雄，已要求要和你談談。$B$B這是份殊榮，$n。通常索拉納爾領主將一般成員的管理都交給我，但他現在有興趣和你親自見見。別耽擱了，$n。', '和銀月城的索拉納爾·血怒領主談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9722, 'zhTW', '大師之路', '在騎士團的各階級之中，存在著一個僅由精英騎士組成的內環議會。議會的成員都是由領導層親自挑選出的最具奉獻精神、最值得信賴，以及技巧最為優秀的血騎士。這些大師們最顯著的標誌就是他們所擁有的薩拉斯戰馬坐騎。$B$B每名議會的預備成員都必須擁有一個議會內的推薦人，並需要表現出他們對騎士團核心原則的奉獻與尊崇。$B$B鑑於你的優秀表現，我已被選為你的推薦人，將以血騎士大師的身份推薦你加入議會，不知道你是否願意加入。', '再次與索拉納·血怒交談，接受他對你的推薦。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9723, 'zhTW', '承諾的手勢', '血騎士的忠誠在<他的/她的>劍末也不會停止，$n。騎士團不只是要求它的成員操練和戰鬥。一個真正的騎士對所有騎士團的活動全心奉獻，即使有些活動表面上看來不那麼光榮。$B$B這第一次的任務既不是密集的戰鬥，也不是光榮的活動，但沒有這樣的貢獻，騎士團就會分崩離析。我會給你一個博學者阿斯塔樂·血誓的人需要的物品清單，這樣才能讓我們的魔法保有聖光能量。', '帶40塊符文布，6個奧金錠，10根太陽草，5個黑暗符文和150金幣給銀月城的索拉納爾·血怒領主。', '', '去找銀月城的索拉納·血怒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9724, 'zhTW', '警告塞納里奧議會', '塞納里奧遠征隊已成為一個有良好自主權的組織。這些事件已經嚴重到我們該警告塞納里奧議會的地步了。$B$B不要擔心，我不會要你回去月光林地;我們有間諜在地獄火半島附近。', '到地獄火半島和塞納里奧前哨的艾咪希·迷霧長者談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9725 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9725, 'zhTW', '展現忠誠', '我們血騎士一定要保衛奎爾薩拉斯，$n。這是你的訓練重點。我們的敵人既殘忍又無情。銀月城和它的人民在我們和盟友的努力下才能維持自由。$B$B我收到一些令人心神不寧的報告，我們在東南方和東瘟疫之地交界處出現了新的天譴軍團。一群天譴攻城技師和他們的裝備看來是在準備對鬼魂之地展開攻擊。他們絕對不能成功。', '銀月城的索拉納爾·血怒領主要你摧毀3台天譴軍團肉類貨車並殺死15個天譴攻城技師。', '', '去找銀月城的索拉納·血怒。', '', '摧毀天災絞肉車', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9726, 'zhTW', '既然我們是朋友……', '東北方血鱗營地的納迦開始殺害我們的族人。我們不能讓這樣的事繼續下去，$c!$B$B我們建議你給他們一點顏色瞧瞧以示我們的友誼。', '殺死12個血鱗奴隸驅使者和6個血鱗女巫師，再回到贊格沼澤找斯博格爾的卡思汗特。', '', '去贊加沼澤找孢子村的舒特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9727, 'zhTW', '既然我們還是朋友……', '報告指出東北方血鱗營地的納迦持續在殺害我們的族人。我們以為你已經解決這個問題了，$c!$B$B我建議你給他們一點顏色瞧瞧才能讓我們的友誼維繫下去。', '殺死12個血鱗奴隸驅使者和6個血鱗女巫師，再回到贊格沼澤找斯博格爾的卡思汗特。', '', '去贊加沼澤找孢子村的舒特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9728, 'zhTW', '溫馨款待', '當遠征隊的德魯伊忙於研究植物和湖泊時，我就負責對付這裡的敵人。$B$B自從我們來到贊格沼澤，納迦就毫無預警的對我們發動致命攻擊。我們已盡力把他們阻擋在海灣，但我們的資源有限。$B$B我要你去贊格沼澤各個納迦要塞並讓他們知道我們不是好欺負的。幫我把他們的爪子帶來做為你勝利的證據。', '塞納里奧避難所的守望者漢姆特要你幫他帶來30個納迦之爪。', '', '去贊加沼澤找塞納里奧庇護所的監護者哈穆特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9729, 'zhTW', '擊潰費斯伍爾!', '小納迦讓費斯伍爾很生氣!孢子人是費斯伍爾的好朋友，所以費斯伍爾給納迦方舟。$B$B我們要進入附近的納迦村子。你要幫忙嗎?帶朋友一起來!', '護送費斯伍爾進入沼澤光蒸汽幫浦區域取得斯利斯方舟。將費斯伍爾和方舟安全地帶回來再去贊格沼澤和斯博葛爾的卡思汗特回報。', '將薩斯里斯聖櫃送回孢子村', '去贊加沼澤找孢子村的舒特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9730, 'zhTW', '暗羽領導者', '塞納里奧遠征隊在此發佈賞金懸賞洛迦海卡斯特，暗羽納迦的首領。海卡斯特上次被塞納里奧斥候看到是在瀉湖，贊格沼澤的中南方區域。$B$B暗羽和許多攻擊塞納里奧遠征隊的事情都有關聯，他們的領導者更是特別危險。$B$B想獲得賞金的人就要向守望者漢姆特回報。', '殺了瀉湖的洛迦海卡斯特並回到贊格沼澤的塞納里奧遠征隊向守望者漢姆特回報。', '', '去贊加沼澤找塞納里奧庇護所的監護者哈穆特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9731, 'zhTW', '排水結構圖', '你取得的結構圖顯示一個地下排水和幫浦系統，連接毒蛇之湖區域的湖泊。$B$B如果結構圖正確無誤，在毒蛇之湖中心有一個巨大的排水管。去確認這件事並將消息帶到塞納里奧避難所。', '搜尋毒蛇之湖尋找排水管的徵兆。帶著你的發現回到塞納里奧避難所找伊斯歐·風歌。', '發現抽水泵', '去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9732 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9732, 'zhTW', '回到沼澤', '回到伊斯歐那裡讓她知道我會盡快對她伸出援手。$B$B月光林地和希利蘇斯的事讓我們的成員無暇分心，但我們會盡力運送必要的資源到塞納里奧避難所。', '回到贊格沼澤塞納里奧避難所的伊斯歐·風歌那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9733 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9733, 'zhTW', '警告塞納里奧議會', '塞納里奧遠征隊已成為一個有良好自主權的組織。這些事件已經嚴重到我們該警告塞納里奧議會的地步了。$B$B不要擔心，我不會要你回去月光林地;我們有間諜在地獄火半島附近。', '到地獄火半島的索爾瑪和馬琥藍·胖蹄談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9734 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9734, 'zhTW', '回到沼澤', '回到伊斯歐那裡讓她知道我會盡快對她伸出援手。$B$B月光林地和希利蘇斯的事讓我們的成員無暇分心，但我們會盡力運送必要的資源到塞納里奧避難所。', '回到贊格沼澤塞納里奧避難所的伊斯歐·風歌那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9735 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9735, 'zhTW', '聖光真正的主人', '一個血騎士能以其他被稱為「聖騎士」的傢伙所完全無法理解的技巧來行使聖光的力量。但儘管我們發揮了聖光的潛力，他們依舊鄙視我們。$B$B我們一定要給他們一個訊息讓他們知道我們不是好對付的。我腦袋裡想的既不簡短也不簡單，但如果你值得託付的話，第一步就是滲入提爾之手修道院的藏書房取得一瓶提爾之手聖水。', '銀月城的索拉納爾·血怒領主要你幫他帶來提爾之手聖水。', '', '去找銀月城的索拉納·血怒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9736 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9736, 'zhTW', '聖光的主人', '現在我們擁有聖水了，但還需要一些其它的材料。$N，這其中有些物質十分稀有，而且價格昂貴，但我已經找到了可靠的貨源。$B$B你應該可以從一個名叫索爾雷的材料商那裡買到一些奧術觸媒，他的商店開在死亡之痕附近的一處曠野上。城內謀殺小徑的盜賊訓練師一旁的毒藥商達爾莉亞那裡有一些黃昏之塵的存貨。$B$B此外，要完成這種混合藥劑，我還需要一顆艾澤拉斯鑽石和一顆原始黑鑽石。', '銀月城的索拉納·血怒要求你給他帶回一份奧術觸媒、一份黃昏之塵、一顆艾澤拉斯鑽石和一顆原始黑鑽石。', '', '去找銀月城的索拉納·血怒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9737 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9737, 'zhTW', '聖光真正的主人', '我們的路是一條真正利用聖光的路，$n。向那些自稱為「聖騎士」的人證明他們的愚蠢，我要發出一個清楚的訊息。$B$B阿隆索斯教堂，也就是白銀之手騎士團的成立之處，似乎對斯坦索姆的摧毀免疫。教堂的永恆火焰提供聖光保護，但當你使用混合物來熄滅火焰時，那個防護就不在了。它會燃燒，而世界也會知道我們對聖光的統治。', '在阿隆索斯教堂的永恆火焰旁使用混合物撲滅劑來移除聖光的防護。準備和任何要保衛教堂的人作戰。', '', '去找銀月城的索拉納·血怒。', '解除阿隆索斯禮拜堂的保護', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9738 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9738, 'zhTW', '無法行動', '你一定要幫我!我們被伊斯歐派來這裡調查蒸汽幫浦的秘密，還有為什麼它們會被用來排出泥沼的水份。但我的朋友們斷絕關係把我丟在這裡。$B$B那四個人有時候真的很混蛋，但我還是愛他們。$B$B這就是為什麼我需要你去調查他們的下落，雖然我擔心他們遭遇不測。到奴隸監獄和深幽泥沼去找他們。$B$B謝謝你，$c。', '調查大地束縛者瑞吉，自然學家拜特，威德·綠指和喚風者卡勞發生了什麼事。然後再回到贊格沼澤的盤牙蓄湖找看守者詹汗格。', '', '去贊加沼澤找盤牙水庫的觀察者傑哈恩。', '找到縛地者雷葛', '找到博學者拜特', '找到除草者格林薩姆', '找到喚風者克勞恩', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9739 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9739, 'zhTW', '孢子人的困境', '嘿!你一定要救救我們!$B$B真菌巨人正毀滅我們所有的孢子囊!你一定要想想辦法，否則我們就會失去幼苗!$B$B孢子囊一開始很大，後來會隨著裡面的空氣消耗而變小。尋找小的，成熟的孢子囊並盡量拯救他們!', '重生峽谷的法斯恩要你收集10個成熟的孢子囊。', '', '去贊加沼澤找孢殖林的法恩森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9740 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9740, 'zhTW', '太陽之門', '多虧了你和你做的努力，我的斥候才能找到太陽之門。精靈讓傳送門的位置保持活動，這樣他們才能瞬間移動它。這是為什麼你調查到的地點是空的。$B$B這個系統的優點也是它最大的缺點。太陽之門由傳送門控制器來穩定。如果我們可以擊敗控制器，我們就能摧毀傳送門。目前太陽之門的位置在西邊，旋繞導航器的南方。找到並摧毀它!', '血色守望的復仇者艾伊森要你摧毀太陽之門。', '', '去找鮮血島的復仇者艾伊森。', '摧毀太陽之門', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9741, 'zhTW', '虛無異常者', '幾天前艾伊森派我的小組去進行一個勘察任務，搜索太陽之門。不用說，我們發現了……$B$B<羅莉指著喬爾力。>$B$B不管那些蠢精靈透過傳送門在傳送什麼，這讓虛無能量不斷被釋放。那個區域到處都是虛無異常者。$B$B我們一定要在他們有機會變成虛無反常者前毀了他們。你可以在西南方靠近太陽之門的地方找到這些生物的發源地。殺了他們，完成後向艾伊森報告。', '殺死12個虛無異常者再向血色守望的復仇者艾伊森回報。', '', '去找鮮血島的復仇者艾伊森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9742 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9742, 'zhTW', '更多孢子囊', '', '', '', '去贊加沼澤找孢殖林的法恩森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9743 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9743, 'zhTW', '自然天敵', '我們孢子人和泥沼領主向來都處的不好。過去我們設法用矛和石頭把他們留在海灣。最近他們似乎變的比較有侵略性……或是說比較激進。他們不怕我們或我們的武器。$B$B你比我們更可怕又有更好的裝備。如果你可以幫我們挑戰泥沼領主，我們永遠都會欠你一份人情!幫我把他們的藤鬚帶來這樣我就會知道你殺了多少個。', '贊格沼澤，重生峽谷的法斯恩要你幫他帶來6個泥沼領主藤鬚。', '', '去贊加沼澤找孢殖林的法恩森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9744 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9744, 'zhTW', '更多藤鬚!', '', '你殺了許多巨人，但還有更多隨侍在後。他們仍在攻擊我們的孢子囊!。', '', '去贊加沼澤找孢殖林的法恩森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9745 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9745, 'zhTW', '熄滅火焰', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9746 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9746, 'zhTW', '體能極限', '勝利就只差臨門一腳，$N。發現了太陽之門，他們的補給線不久後就會被完全封鎖了。現在是襲擊他們部隊的時候。$B$B你可以在西邊找到許多的太陽之鷹營地。太陽之鷹控火者和太陽之鷹防衛者佔據了大部分的區域。找到他們，殺了他們，再回來找我。', '血色守望的復仇者艾伊森要你殺死10個太陽之鷹控火者和10個太陽之鷹防衛者。', '', '去找鮮血島的復仇者艾伊森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9747 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9747, 'zhTW', '昂布拉凡部族', '納迦是很恐怖的生物，沒錯。但更恐怖的是幫助他們的破碎者和失落者叛徒部族!$B$B最糟糕的是昂布拉凡部族的失落者;他們使用黑暗魔法對他人設陷阱並奴役他們。他們對逃跑的奴隸特別殘酷，如果我離開避難所一天他們就會劃破我的喉嚨。$B$B前往南方的昂布拉凡村，殺了他們和他們的領導者，卡塔魯。在那之前我每一天都會過的心驚膽跳。', '塞納里奧避難所的伊奇言要你前往昂布拉凡村殺死卡塔魯，8個昂布拉凡先知，6個昂布拉凡巫醫和6個昂布拉凡神諭者。', '', '去贊加沼澤找塞納里奧庇護所的伊卡因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9748 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9748, 'zhTW', '別喝那裡的水', '我們的薩滿聲稱水元素因為水源的污染受到很大的影響。我們知道艾克索達的能量核心位在西邊的山裡。它一定是正滲漏出揮發性的液體到水供給裡!我要你去幫我收集更多資訊。$B$B<艾伊森指向一個瓶子並點點頭。>$B$B你要帶著這個瓶子沿著海邊北方走，直到你到達血謎島的河流匯入海洋的區域。採集那裡的樣本並帶回來給我。', '血色守望的復仇者艾伊森要你使用水樣本瓶取得血謎水樣本。', '', '去找鮮血島的復仇者艾伊森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9749 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9749, 'zhTW', '他們還活著！或許吧……', '真是倒黴透了，$N。我們遭到了一大群蜘蛛的突襲。他們的先驅以驚人的速度突然襲擊我們，將我們困在蜘蛛網裡。$B$B我們被網纏住後，她開始在我們附近產卵。我們將成為她後代的食物！食物！$B$B我費盡力氣逃了出來，但我不能丟下其它人不管。直到現在我也沒能將他們解救出來。你能幫幫我嗎？$B$B毀掉那些蜘蛛網！希望我們隊的人還活著！', '研究員卡尼勒斯要你救出5個遠征隊研究員。', '', '去秘血島找琥珀蛛網小徑的研究員考內留斯。', 'Expedition Researcher Freed', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9750 AND `locale` = 'zhTW';
DELETE FROM `quest_template_locale` WHERE `ID` = 9751 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9751, 'zhTW', '血咒遺產', '昨天夜裡，「失望」號的船長，艾德華·漢尼斯出現在我帳篷前面。和20年前因壞血病而死的艾德華·漢尼斯一模一樣。這個亡魂告訴我了一個讓我的心顫抖的故事。一個我要你聽的故事和一個我要你完成的任務。你會去做嗎?你會去找血色守望東北方的龍痕島找艾德華嗎?', '艦隊司令·奧迪席斯要你去找隊長艾德華·漢尼斯並和他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9752 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9752, 'zhTW', '逃離昂布拉凡', '你一定要幫我離開這裡!$B$B我在附近採集草藥然後這些小野人就把我綁架來這裡。我試著擊退他們，可是他們人多勢眾。$B$B幫助我回到塞納里奧避難所，遠離這些殘酷的卑鄙小人和他們邪惡的魔法!', '護送凱拉·長鬃回到贊格沼澤的塞納里奧避難所。完成任務後向伊斯歐·風歌回報。', '護送凱拉·長鬃回到塞納里奧庇護所', '去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9753 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9753, 'zhTW', '我們所知道的事……', '我們最近幾天了解了很多敵人的事。血精靈由一個叫賽羅娜斯的人領導並密謀要摧毀我們。最後，他們要征服歐蘿絲並重拾對艾克索達的控制。$B$B讚美聖光，我們摧毀了太陽之門，阻止了他們的補給線。不幸的是，他們持續使用旋繞導航器的污染物來毒害大地，使用幅射性落塵的突變物質來利己。$B$B有了這樣的認識，阿德密特斯便想出個計畫。快去找他。', '和血色守望的主教阿德密特斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9755 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9755, 'zhTW', '', '我們對敵人的審訊毫無進展，朋友。無論怎樣刑訊逼供也無法取得任何成果。現在我們需要派遣勇士打入敵人內部。\\r\\n\\r\\n我可以在你身上施展一個法術，讓你從外表和說話風格上都變成一個血精靈。這樣，也許你能幫我們從俘虜那裡套取出一些情報。\\r\\n\\r\\n你要和那些囚犯仔細攀談，儘量讓他們透露更多的資訊。\\r\\n\\r\\n同時還要記住，朋友，在偽裝期間不要離開秘血崗哨，否則偽裝就會失效。', '同秘血崗哨中被俘的炎鷹偵察兵交談。取得炎鷹情報。完成任務以後回去見主教埃德門圖斯。', '取得炎鷹情報', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9756 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9756, 'zhTW', '我們不知道的事……', '我們嘗試審問的企圖已悲慘地失敗了，$N。折磨 - 當然 - 是絕對會有的。我們需要的是一個在裡面的德萊尼。$B$B我可以對你施放一個法術讓你變成血精靈並調整你的語言。透過一些藉口，我們或許可以獲得被俘虜的密探的消息。$B$B在這樣的偽裝下，我要你盡可能的從囚犯那裡取得資訊。$B$B還有$N，偽裝的時候不可以離開血色守望否則法術就會失效。', '和血色守望被俘虜的太陽之鷹密探談談並取得太陽之鷹情報。完成任務後回報主教阿德密特斯。', '', '去找鮮血島的主教阿德密特斯。', '取得太陽之鷹情報', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9757 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9757, 'zhTW', '尋找女獵人凱拉·夜弓', '女獵人凱拉·夜弓謁見所有合格的獵人。她可以教你馴服野生野獸的技巧，這是你現在的訓練中應該先學的課題。$B$B凱拉就在瓦拉船台附近，艾克索達的西邊碼頭。', '和瓦拉船台附近的女獵人凱拉·夜弓談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9758 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9758, 'zhTW', '回到秘法師范德隆那裡', '我的朋友，希望你可以好心的回到秘法師范德隆那裡，我知道他非常渴望派你來鬼魂之地這裡進行你的第一個任務。我們都靠你了，$N。別讓我們失望。', '回到鬼魂之地的安寧地找秘法師范德隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9759 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9759, 'zhTW', '結束他們的世界', '如果你珍惜你的生命就不要接下這個任務。你看到遠處那個從山邊突起的巨大能量核心嗎?任何接下這個重擔的人都需要一路戰鬥到那座山上，在保護我的同時要和太陽之鷹軍隊作戰，而我要切斷那個核心以破壞它。賽羅娜斯也在那裡某處。$B$B如果你就此離去我也不會輕視你的，$N。$B$B但或許你就是那個能摧毀旋繞導航器和擊敗賽羅娜斯的人。那麼，你是嗎?', '在破壞者勒茍索嘗試摧毀旋繞導航器並殺死賽羅娜斯時跟著他並保護他。完成任務後回到血色守望的主教阿德密特斯那裡。', '向量線圈已摧毀，希羅娜絲已擊殺', '去找鮮血島的主教阿德密特斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9760 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9760, 'zhTW', '復仇者之陵', '我不會要你獨自一人背負著摧毀旋繞導航器和殺死賽羅娜斯的重擔，$N;不過，我想你可以幫忙為其他可能接下這樣危險任務的人清理道路。$B$B踏上血色守望外往北邊的路並沿著它一直走到岔路。到了那裡，選擇左邊的路並一直走到你看見復仇者之陵 - 它會在路的偏西邊一點。科林會在那邊等你。', '到血謎島和復仇者之陵的復仇者科林談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9761, 'zhTW', '清除道路', '只有最身經百戰，高尚，又毫無畏懼的德萊尼才會接下於勒茍索的任務。主教不會命令任何一個阿格斯之手的密探接下摧毀旋繞導航器和殺死賽羅娜斯的任務。他拒絕讓任何一個德萊尼去送死 - 像是那些自殺般的任務……$B$B<科林嘆氣。>$B$B我的工作是削弱太陽之鷹的防禦。你要殺死旋繞導航器附近的太陽之鷹並為我們的勇士將道路清空 - 不論我們的勇士是誰。', '復仇者之陵的復仇者科林要你殺死8個太陽之鷹破壞者和8個太陽之鷹密探。', '', '去找鮮血島的復仇者科林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9762, 'zhTW', '未寫下的預言', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9763 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9763, 'zhTW', '督軍的藏身之處', '非常、非常安靜地躲在你敵人的藏身處入口是有好處的。$B$B幾個小時前我看到一群納迦通過左邊第二個隧道的石拱門。我不太懂他們的語言，不過我清楚的聽懂一個字:卡利斯瑞。$B$B那一定是進入蒸汽洞窟的入口，就是督軍卡利斯瑞指揮軍隊的地方。你一定要找到他並阻止他。我太虛弱了無法提供任何協助。', '看守者詹汗格要你找到並殺死盤牙蓄湖裡的督軍卡利斯瑞。', '', '去贊加沼澤找盤牙水庫的觀察者傑哈恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9764 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9764, 'zhTW', '瓦許女士的命令', '這封信裡寫著對運作蒸汽洞窟的盤牙納迦詳細的命令。信中警告塞納里奧德魯伊進入該區域並命令他們見到就殺。更改其他湖泊水流進入盤牙蓄湖的費用要加倍。命令上印有聲名狼藉的瓦許女士封印。$B$B塞納里奧遠征隊應該會對這封信很有興趣。把它帶給他們的領導者，伊斯歐·風歌。', '將瓦許女士的命令帶到贊格沼澤給塞納里奧避難所的伊斯歐·風歌。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9765 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9765, 'zhTW', '準備作戰', '塞納里奧遠征隊始於一場和平的冒險，但我們現在面對的卻是和納迦的戰爭。$B$B我們之中有許多人願意作戰，但都裝備不足。幫我把納迦自己的武器帶來，這樣我們就能重新鑄造成大刀和利箭。$B$B只有最好的裝備對我們才是有用的，$n。你要去盤牙蓄湖尋找納迦。', '從盤牙蓄湖的納迦身上取得盤牙裝備並將它們帶回贊格沼澤給塞納里奧避難所的伊斯歐·風歌。', '', '去贊加沼澤找塞納里奧庇護所的伊謝爾·風歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9766 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9766, 'zhTW', '盤牙裝備', '', '我們會將納迦自己的鋼鐵拿來鑄造成武器對付他們。幫我把你在盤牙蓄湖找到的裝備帶來給我。', '', '去找伊謝爾·風歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9768 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9768, 'zhTW', '盤牙法術書', '', '', '', '去找贊加沼澤的埃西恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9769 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9769, 'zhTW', '流行沒有理由', '<瑪卡莎輕輕地咯咯而笑。>$B$B我打賭如果他們知道自己穿著蟲子在身上的話，這股流行風很快就會結束了。$B$B我們開始殺這裡的蟲子是因為他們一直阻撓我們的建造工程。有些事業心重的商人會在這裡停留，過夜，然後你也知道，他們就會把我們所有的蟲子翅膀給買光!$B$B他說是用來做衣服的。我還是寧願穿我的護甲，謝謝。但如果你收集到螢光蛾的翅膀，我很樂意買下它們。', '從螢光蛾身上弄到8個透明之翼給斯溫派特崗哨的瑪卡莎。', '', '去贊加沼澤找沼澤鼠崗哨的瑪加沙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9770 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9770, 'zhTW', '險惡的沼牙', '有時候我真希望丹傑派一個薩滿來給我們，或至少給我們一個圖騰讓沼牙撕裂者留在海灣邊。$B$B這整個地方都爬滿了害蟲!這樣是不對的。難道不該有個什麼東西把這些卑鄙的生物給吃掉嗎?$B$B我們一直都輪流扮演消滅者的角色。你出現的正是時候，$n。恭喜!現在離開這裡清除掉一些沼牙生物!', '斯溫派特崗哨的瑞伏基要你殺死10個沼牙撕裂者。', '', '去贊加沼澤找沼澤鼠崗哨的裡維伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9771 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9771, 'zhTW', '尋找斥候傑巴', '既然你對地形很熟，我想請你幫忙一些別的事。死亡污泥，我們這樣稱西北邊的區域，那是個令人毛骨悚然的地方。沒有任何人回報在那裡看過任何活著的東西，但他們也都沒有久留。$B$B斥候傑巴自願去那裡調查並回報他的發現。他三天前離開崗哨就再也沒有回來了。他去這麼久也沒有寄送什麼報告回來。你可以去找他嗎，$n?', '尋找斥候傑巴。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9772 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9772, 'zhTW', '傑巴的報告', '一點一點枯萎的真菌點綴在斥候傑巴的身上。不管殺他的人是誰，他一定是由和死亡污泥枯萎的巨大蘑菇一樣的真菌組成的。或許某個枯萎的巨人意外地在他坐著寫報告時抓到他。$B$B沒有報告的文字，要知道斥候發現了什麼幾乎是不可能的。如果可以找到報告，就要把它交給祖瑞伊。', '從枯萎的巨人那裡取得斥候傑巴的報告並將它交給斯溫派特崗哨的祖瑞伊。', '', '去贊加沼澤找沼澤鼠崗哨的祖萊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9773 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9773, 'zhTW', '不要再給我蘑菇了!', '蘑菇湯，燉蘑菇，蘑菇醬!$B$B蘑菇，蘑菇，蘑菇!這裡只有這個東西可以吃。如果你說你肚子餓，廚師就會給你一把斧頭叫你自己去砍下你的晚餐!$B$B嗯，我已經受夠蘑菇了。我在湖裡有看到魚。當然，他們看起來是個棘手的工作，但他們一定比蘑菇好多了!$B$B我要花多少錢請你去幫我弄來這幾個禮拜裡第一份像樣的晚餐?', '從昂布拉凡鰻魚身上收集8份鰻魚片並帶給斯溫派特崗哨的瑪卡莎。', '', '去贊加沼澤找沼澤鼠崗哨的瑪加沙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9774 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9774, 'zhTW', '厚多頭蛇鱗片', '瑞伏基帶來皮革護甲是很聰明的。這個沼澤不久就會讓我的鎧甲都沒有用了。$B$B我已經趁我還有能力的時候用鱗片一點一點的把它換掉了。沼澤裡的多頭蛇有著厚實而具保護力的鱗片，可以經得起他們家園的潮濕。$B$B不過找到適合的鱗片是個麻煩冗長的過程。一般來說，最好的鱗片都撕裂或磨損的太薄不能使用在護甲上。幫我從大湖泊的多頭蛇身上取來優良的鱗片。', '斯溫派特崗哨的祖瑞伊要你幫他帶來12片厚多頭蛇鱗片。', '', '去贊加沼澤找沼澤鼠崗哨的祖萊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9775 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9775, 'zhTW', '向暗影獵人丹傑回報', '暗影獵人丹傑絕對在等待我的報告，告訴他建造前哨的進展。我準備了一個簡短的摘要說明我們已完成了什麼，但失去了斥候傑巴，我無法再撥出一個信差將報告帶到西邊的薩布拉金給丹傑。$B$B如果你要往那邊去，可以把這個帶給他嗎?暗影獵人丹傑剛開始可能有點嚇人，但等你習慣了，他其實也沒那麼壞。', '將祖瑞伊的報告帶給薩布拉金的暗影獵人丹傑。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9776 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9776, 'zhTW', '奧雷伯爾港', '你知道，泰倫多爾的許多居民都是德萊尼大屠殺戰爭下的難民。在這樣的掙扎中為所有的盟友保衛泰倫多爾，讓它成為安全的避風港是我的目標。有些人想加入我們，但我覺得他們還沒準備好。$B$B我們要提供他們所有的幫助，$n。一群由伊庫堤領導的破碎者已在西北方的毒蛇之湖那裡找到一個舊神廟廢墟做為避難所。找到他們並對他們伸出友誼之手。', '和奧雷伯爾港的伊庫堤談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9777 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9777, 'zhTW', '明亮孢子', '沼澤這裡沒有什麼東西是會燃燒的，$r，所以我們一定要求助於其他方法來點亮泰倫多爾。濕地裡有許多生物和植物都會發出柔和的光芒。$B$B限制發光的生物是困難又殘忍的事，所以我們決定使用一種蘑菇做為光線的來源。$B$B我們在這裡採集並培育明亮蘑菇，但我們需要不時地收集新作物。那個小小的，綠色的蘑菇通常生長在泰倫多爾附近的大基地之一。', '帶6個明亮孢子給泰倫多爾的洛安瑪。', '', '去贊加沼澤找泰雷多爾的魯埃姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9778 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9778, 'zhTW', '守望者漢姆特', '在你離開塞納里奧避難所之前，確定你有和守望者漢姆特談談。他負責遠征隊的安全。$B$B如果我沒有派一個像你一樣老練的冒險者給他，他永遠都不會原諒我的。', '到贊格沼澤的塞納里奧避難所向守望者漢姆特報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9779 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9779, 'zhTW', '攔截訊息', '再見到你真好，$N。我有個困難你或許可以解決。$B$B我們在太陽之鷹陣線後方的密探回報，看見太陽之鷹士兵傳送一份不尋常的文件。$B$B不幸的是，我們未成功取得一份文件的副本。我要你去那裡嘗試弄到那個文件。我確定如果你施加足夠的壓力，太陽之鷹密探就會供出我們要的資訊。必要時你可以使用武力。', '殺死太陽之鷹的血精靈們直到你取得太陽之鷹書信，然後交給血色守望的復仇者波羅斯。', '', '去找鮮血島的復仇者波羅斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9780 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9780, 'zhTW', '昂布拉凡鰻魚片', '在這裡看到新面孔是一件好事。我和哈爾隆恩第一次來到泰倫多爾的時候是唯一的外來者，但那似乎是上輩子的事了。$B$B我們還是試著歡迎新來者，確保永遠都有足夠的食物和補給。我們永遠也償還不了泰倫多爾隱士對我們的好，但我們可以以他們為榜樣並延伸到其他人身上。$B$B如果你願意幫忙，附近的湖泊充滿了一種叫昂布拉凡鰻魚的魚，它的肉是我們的主食。', '泰倫多爾的諾納尼要你幫她帶來8份鰻魚片。', '', '去贊加沼澤找泰雷多爾的諾蘭妮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9781, 'zhTW', '僧多粥少', '在我最後一次的打獵旅行中，我看見一群食人妖在建造一個新前哨。毫無疑問的他們也開始在這些土地獵食。$B$B如果他們永遠都待在這裡，食物的競爭就會很激烈。我們不能毫無預警的直接攻擊他們，但我們可以除掉一些自然的食物競爭。$B$B你們每殺一個污泥多頭蛇，就有三個人少了食物。', '殺死10個污泥多頭蛇再回到泰倫多爾的哈爾隆恩那裡。', '', '去贊加沼澤找泰雷多爾的海爾倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9782, 'zhTW', '死亡污泥', '我和泰倫多爾的隱士住在一起有好一段時間了，$n，在那段時間裡我對沼澤有了不少認識。最近，我開始注意到東北方有個干擾的改變。$B$B那裡差不多所有的生命都開始枯萎和死亡，似乎是毫無理由的。我有一些想法大概知道發生了什麼事，但它們只是小小的推測而已。如果你可以幫我帶來那區域的泥土樣本，我或許能將這個秘密查個水落石出。', '將死亡污泥泥土樣本帶給泰倫多爾的復仇者伊達爾。', '', '去贊加沼澤找泰雷多爾的守備官伊達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9783, 'zhTW', '不尋常的乾旱', '你帶給我的泥土樣本幾乎沒有水分，$n。如果泥土本身失去水分，那麼住在死亡污泥的生物一定遭受了可怕的磨難。$B$B我見過當區域的真菌巨人開始枯萎和死亡的情景。這樣的痛苦讓他們快瘋了，使他們攻擊任何進入他們道路的生物。$B$B這些生物不知道自己發生了什麼事。我們也無法拯救他們，所以我們能做的就是結束他們的苦難。', '泰倫多爾的復仇者伊達爾要你去殺死12個枯萎的巨人。', '', '去贊加沼澤找泰雷多爾的守備官伊達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9784, 'zhTW', '辨別植物組織', '', '我還需要更多的植物組織。隨著湖泊的水分流失，我有預感入侵當地生態的品種數量正不斷的攀升。不過，我需要更多的數據來支持我的理論。', '', '去贊加沼澤找塞納里奧庇護所的勞蘭娜·薩維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9785 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9785, 'zhTW', '先祖的祝福', '你贏得了塞納里奧遠征隊的信任，$n。是時候讓你和我們結盟的先祖，艾斯炎和奇里斯談談並要求他們的祝福了。$B$B帶著先祖的面具會讓你帶有強大的力量。這些增益會隨著你在我們之中的聲望提高而增大。$B$B去吧，$n，並要求先祖給你他們的祝福。', '喚風者黑蹄要你去和塞納里奧避難所的先祖艾斯炎及奇里斯談談並取得他們的祝福。', '', '去贊加沼澤找塞納里奧庇護所的喚風者塔魯·黑蹄。', '知識印記', '戰爭印記', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9786, 'zhTW', '波哈姆廢墟', '在我的族人被獸人屠殺之前，泰倫多爾是德萊尼隱士和女巫的靜修場所。有一小群隱士和復仇者保衛這區域的多個神殿。$B$B在戰爭時期，我們和派到神殿的隱士失去聯繫，尤其是西南邊波哈姆廢墟的人。我聽說一支失落者部族在該區域安頓下來，甚至還在使用廢墟。前往波哈姆廢墟並告訴我你在那裡發現了什麼。', '泰倫多爾的隱士阿浩恩要你去波哈姆廢墟探勘。', '偵察博哈姆廢墟', '去贊加沼澤找泰雷多爾的學者安霍爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9787, 'zhTW', '菲拉芬塑像', '就你給我的波哈姆廢墟觀察資料看來，這個失落者部族好像恢復崇拜動物靈魂了。在我們接近他們之前，我們一定要更了解他們的信仰。$B$B回到菲拉芬村並謹慎地收集一些他們的塑像，這樣我就能研究它們。試著不要激怒他們，$n，因為那有可能破壞我們與他們來往的機會。', '收集6個菲拉芬塑像並帶回泰倫多爾給隱士阿浩恩。', '', '去贊加沼澤找泰雷多爾的學者安霍爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9788, 'zhTW', '黑暗潮濕的地方', '在我從昂布拉凡部族那逃出來後，我就躲在他們村子南方的一個洞穴裡。但我並不知道沼澤野獸和孢子人正在爭奪那個洞穴!$B$B我倉皇離開並留下了一個箱子，裝滿我塵世間僅剩的財產。$B$B在帶著我的東西溜出昂布拉凡之後，馬上又失去它們真是一個可怕的諷刺。如果你願意把它們帶回來給我，我就給你一個我私人的物品。你說怎麼樣，$n?', '在昂布拉凡南方的洞穴裡尋找伊奇言的物品。把它們帶回贊格沼澤還給塞納里奧避難所的伊奇言。', '', '去贊加沼澤找塞納里奧庇護所的伊卡因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9789, 'zhTW', '裂蹄專精', '想在這隻旅隊中取得一席之地嗎?你得證明你自己。$B$B我不在乎你曾經獵殺過什麼，在你獵過我們在這獵過的東西之前，你都不算狩獵過。從狩獵裂蹄開始來證明你的<男子氣概/狩獵技巧>。$B$B我見過它們出現在緊接著旅隊的區域附近以及靠近南邊的地方。', '殺死12頭裂蹄牛，然後向納格蘭奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里覆命。', '', '去納格蘭找奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9790, 'zhTW', '透明之翼', '生活在這樣偏遠的地區讓我們懂得利用所有的事物。當然，你必須先停止思考這些材料是哪裡來的。$B$B我發現螢光蛾的翅膀非常防水。它們既堅固又輕薄，而且還很有彈性。$B$B<哈爾隆恩咯咯地笑。>$B$B我看到你臉上的表情了。就像我說的，要花點時間才能適應偏遠地區的物資獲取方式。如果你要去外面闖一闖，可以幫我帶一些翅膀回來嗎?', '泰倫多爾的哈爾隆恩要你幫他從贊格沼澤的任何螢火蟲身上帶回8個透明之翼。', '', '去贊加沼澤找泰雷多爾的海爾倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9791, 'zhTW', '險惡的沼牙', '在獸人對抗我們人民的時期，採集者幾乎很少離開泰倫多爾，因為他們害怕被攻擊或俘虜。現在，我們比較常出外冒險，不過沼澤也沒有比較安全。$B$B虛空鰭刺近幾個月似乎變的比較大膽。我不知道這和他們平常的獵物變少有沒有關係，但他們一直經常攻擊我們的採集小組。如果我們可以削減他們在泰倫多爾的數量，或許他們就會學著不來打擾我們。', '殺死10個沼牙撕裂者再回到泰倫多爾的諾納尼那裡。', '', '去贊加沼澤找泰雷多爾的諾蘭妮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9792, 'zhTW', '給泰拉的消息', '你已在我們的交易中證明你是值得信任的，$n，在這個難取得我們人民信任的時候。$B$B我有一大群同胞已在南邊的納葛蘭，一個老德萊尼城市，泰拉建立了他們的家園。要前往泰拉，往南進入納葛蘭，再持續往東南方走直到你到達歐夏剛東邊的峭壁。$B$B任何像你一樣協助我們的人都會受到泰拉的人民歡迎。$B$B找到納霍德並告訴他你已贏得了我的信任。', '到納葛蘭和泰拉的納霍德談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9793 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9793, 'zhTW', '杜瑞的命運', '預言者費倫想尋找盟友的事讓那些德萊尼有勇氣留在外域開始尋找他們的盟友。對抗燃燒軍團的戰爭把我們從城市和神廟裡趕走，但他們還沒摧毀我們文明的遺跡。$B$B杜瑞，是我以前在泰洛卡森林的家，它曾是最早由獸人統治的城市之一。我已經很久沒聽過那裡的消息了。把這封信帶到泰洛卡裡的艾蘭里堡壘給安達爾歐，看你能發現什麼。', '將復仇者伊達爾的信帶到泰洛卡森林給艾蘭里堡壘的安達爾歐。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9794, 'zhTW', '沒時間好奇了', '$N，我有件事想請你幫忙。通常我會自己做這件事，但我現在真的太忙了。$B$B我有個叫齊亞隆的朋友在北邊劍刃山脈的希爾瓦納。他在等我的消息，雖然我想他聽到後不會太高興。$B$B如果你可以幫我傳話給他，我會很感謝你。另外我一定要堅持，這很重要，那就是你不能偷讀這封信。這只能讓齊亞隆知道。', '把提莫斯的信帶給位在劍刃山脈希爾瓦納的齊亞隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9795 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9795, 'zhTW', '巨魔威脅', '好像納迦和他們的盟友還不夠多似的，巨魔將他們的觸角延伸到了沼澤區。他們已征服了西北邊大部分區域，那裡已經沒有什麼緩衝之地了。我們每殺一個人，就會有好幾個人代替他的位子。我不確定如果他們決定發動攻擊，我們還能保住薩布拉金多久。前往北方進入山裡，到的獸人雷霆王村堡壘讓奈克薩爾知道我們的困境。我們歡迎他可提供的任何幫助。', '前往劍刃山脈的雷霆王村和奈克薩爾談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9796, 'zhTW', '贊格沼澤的消息', '暗影獵人丹傑不是唯一在等我報告的人。泰洛卡森林碎石堡的莫卡薩急著想知道我們的進展，尤其因為她的信差都會經過這裡。$B$B她要我在斯溫派特崗哨完成後通知她。如果你不介意幫我傳送消息，我會非常感激。我們也常常四處奔走，但實在還有太多事要做了。你如果想去碎石堡的話，就順著贊格沼澤的路往南走，進入泰洛卡森林然後就在杜瑞的遠處。', '到泰洛卡森林和碎石堡的莫卡薩談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9797 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9797, 'zhTW', '卡拉達爾的援軍', '<信差還喘著氣，示意你坐下。>$B$B他們可能活不了了，$r!用最快的速度到卡拉達爾。$B$B<看你還很茫然，信差便開始詳細解釋。>$B$B瑪格哈的家園在納葛蘭的南方。踏上沼澤外往南方的路，然後在第一個岔路往東走，在湖邊尋找一個大型聚集地。$B$B找到我們的指揮官，隊長卡洛克汗，提供你的協助。卡拉達爾不能倒下!', '到納葛蘭和卡拉達爾的隊長卡洛克汗談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9798, 'zhTW', '血精靈計畫書', '這些計畫書看起來很重要。你應該帶著它們去找失事地點的復仇者艾德。', '帶著血精靈計畫書到安曼谷的失事地點找復仇者艾德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9799 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9799, 'zhTW', '植物學家的跑腿任務', '西邊的安曼牧場是當地主要的鞭笞者繁殖地。因為附近湖泊的地下水污染，植物學家泰瑞茲擔心一旦我們淨化湖泊，鞭笞者將無法再自己重新繁殖。$B$B前往安曼牧場摘一些受污染的花給我，或許我可以看看它們並想個辦法。你可以不尋常的紅色花瓣來辨別它們。', '收集3朵被污染的花朵再回到安曼谷的失事地點找學徒米虛歐。', '', '去埃門谷找墜毀點的學徒維莎爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9800 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9800, 'zhTW', '稀有的豆子', '你的裝備不良無法挑戰納葛蘭不安的元素。在你幫助陶土議會之前，你一定要先幫你自己。$B$B你會在西邊找到納葛蘭野生動物留下的糞堆。你要在糞便裡尋找消化的納葛蘭豆子殘餘。我就可以用這個豆子做一個藥片，幫你在戰鬥中對付自然不安的力量。$B$B等你收集到比兩個拳頭還多的消化過的豆子再來找我……巨魔的拳頭。', '將8顆挖出來的卡拉果交給納格蘭元素王座的元素師魯艾普。', '', '去納格蘭找元素王座的元素師魯艾普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9801, 'zhTW', '尋找材料', '我感覺這些失落者對德萊尼沒什麼好感，但卻會歡迎阿拉卡。我可以製造一個藥水讓你的外表短暫地變成阿拉卡。它需要一些不能儲藏的材料而且一定要在收集到的幾個小時裡被使用掉。$B$B你要幫我帶來一些孢子蝙蝠眼睛和沼地行者觸鬚。這兩種生物就住在泰倫多爾附近的荒野。', '泰倫多爾的隱士阿浩恩要你幫他帶來4個孢子蝙蝠眼睛和4個沼地行者觸鬚。', '', '去贊加沼澤找泰雷多爾的學者安霍爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9802, 'zhTW', '贊格沼澤的植物', '贊格沼澤的湖泊正慢慢地乾涸中。我們不太知道是什麼原因，但我們知道很多植物正濱臨絕種的危機。$B$B身為遠征隊的編目者，追蹤並鑑定這些植物是我的工作，這樣我們才能更了解它們發生了什麼事。$B$B如果你願意幫忙，就幫我帶來未經辨認的植物組織。如果你是個草藥學家就可以直接從地上把它摘起來，而沼澤當地的生物也可能攜帶植物組織在身上。', '帶10個未經辨認的植物組織到贊格沼澤給塞納里奧避難所的羅安娜·薩威爾。', '', '去贊加沼澤找塞納里奧庇護所的勞蘭娜·薩維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9803, 'zhTW', '菲拉芬的信差', '是時候讓我們擁抱菲拉芬並教導他們聖光並未遺棄他們。帶著我準備的藥水去波哈姆廢墟。$B$B等你到了廢墟，喝下藥水假裝成他們的一種鳥精靈形態。和年長的克魯提談談，讓他知道德萊尼準備好歡迎他的人民，我們長久失聯的兄弟。', '到達波哈姆廢墟後喝下阿浩恩藥劑。在阿拉卡形態下和年長的克魯提談談。', '', '去贊加沼澤找泰雷多爾的學者安霍爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9804, 'zhTW', '天歌的焦慮精靈', '納葛蘭水源的干擾讓天歌湖的水之靈變的非常焦慮。他們已開始輪番在整個水道散佈毀滅。$B$B水之瓦吐森在幻象中來找過我們並允許我們除去這個問題 - 順便連干擾源都一起解決掉……$B$B我們會去源頭，但首先你一定要立刻解決掉王座的問題。摧毀焦慮的湖中水之靈再來找我。', '消滅8個湖水之魂，然後向納格蘭元素王座的元素師魯艾普覆命。', '', '去納格蘭找元素王座的元素師魯艾普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9805, 'zhTW', '辛納瑞塔斯的祝福', '可惡的失落者，至此之前他們都被放逐在贊格沼澤的沼澤，現在竟想將他們的骯髒散播到世界的其他角落。$B$B我找到了狂怒的智慧並獲得了他們的祝福。要阻止來源，我們一定要釋放它們的元素!$B$B我給你生命之火，那是從辛納瑞塔斯本身的火焰精華取下的。前往東南方的風蘆村在他們的營房上釋放生命之火!讓他們見識元素的狂怒!', '納葛蘭，元素王座的元素師羅艾柏要你摧毀風蘆村的大營房，西營房，南營房，和東營房。完成任務後將生命之火還給元素師羅艾柏。', '', '去納格蘭找元素王座的元素師魯艾普。', '燒燬大棚屋', '燒燬西部棚屋', '燒燬南部棚屋', '燒燬東部棚屋', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9806, 'zhTW', '豐饒孢子', '孢子蝙蝠和沼澤行者徘徊在沼澤的長梗蘑菇旁，於他們的附屬器官上累積豐饒孢子。$B$B如你所見，我們是個矮小的種族，所以我們在收集這些孢子時是很受限制的。找到孢子蝙蝠和沼澤行者並收集豐饒孢子。斯博格爾所有人都會欠你一份人情。', '吉薩夫要你從贊格沼澤不同的孢子蝙蝠和沼澤行者身上收集6份豐饒孢子。完成任務後回到斯博格爾找吉薩夫。', '', '去贊加沼澤找孢子村的格沙弗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9807 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9807, 'zhTW', '更多豐饒孢子', '', '', '', '去贊加沼澤找孢子村的格沙弗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9808 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9808, 'zhTW', '白閃菇', '我看過你們族人使用閃亮的圓形金屬來交易需要的東西。我們和你們沒什麼不同。我們使用閃亮的圓形蘑菇當做貨幣。$B$B白閃菇在沼澤裡到處都是，你只要學會如何把它從地上拔起來又不把它弄壞。我會教你怎麼做，如果你保證幫我們帶來一些當做存貨。你說如何，$n?', '帶10個白閃菇到贊格沼澤給斯博格爾的米斯恩。', '', '去贊加沼澤找孢子村的姆希菲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9809 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9809, 'zhTW', '更多白閃菇', '', '', '', '去贊加沼澤找孢子村的姆希菲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9810, 'zhTW', '被污染的靈魂', '瓦吐森可以去除汙染的惡臭;但這樣做的話，就會製造出扭曲的靈魂精華。一個由元素間最骯髒的腐敗源組成的靈魂精華。$B$B你可以在西南方的沼澤找到這個被污染的靈魂，藏在日春湖深處。$B$B找到並摧毀這個被污染的瓦吐森精華和所有它可能製造出的腐敗產物。', '殺死瓦圖蘇的汙染精華和8個湖水湧動者，然後向納格蘭元素王座的元素師魯艾普覆命。', '', '去納格蘭找元素王座的元素師魯艾普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9811 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9811, 'zhTW', '辛多雷的朋友', '這是我們血精靈歷史中嶄新的一章，$N。你的幫助加強了我們雙方種族的關係，$r。$B$B把背叛者的頭顱帶給銀月城的地區統治者，洛索瑪·塞隆。他等不及想聽到這個消息。', '把達克汗的頭顱交給銀月城的洛索瑪·塞隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9812, 'zhTW', '部落的使者', '我們潛在的新盟友對我們的能力有些懷疑。被認為連自己家的問題都無法解決那我們對他們而言還有什麼用?$B$B這會改變一切。我們的能力不再會被質疑。我們會以同等的姿態加入部落。$B$B把這封信交給希瓦娜斯，被遺忘者的統治者。她已經和我們站在同一陣線了，但達克汗的死訊對她而言沒有影響力。準備好長途跋涉吧，$N。如果一切進行順利她會送你到奧格瑪的。', '將來自洛索瑪·塞隆的信帶到幽暗城，提里斯法林地的被遺忘者首都給希瓦娜斯·風行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9813 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9813, 'zhTW', '會見大酋長', '你知道，我對我的家園或人民的愛從未變過。我為銀月城拼了命的打鬥才有機會和幽暗城及奧格瑪坐上同一張談判桌。$B$B這應該讓任何的對立平息下來。帶著這封信去找奧格瑪的索爾。身為部落首領的他會對接受辛多雷的保證做最後的決定。$B$B我已在信上加上我自己的封印做為個人的背書。去西北方哨塔上搭乘往杜洛塔去的飛艇。', '希瓦娜斯·風行者要你將希瓦娜斯蓋章的信帶到杜洛塔首都，奧格瑪給索爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9814 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9814, 'zhTW', '破頂蘑菇，老兄!', '你喜歡蘑菇嗎，老兄?贊格沼澤這裡有一個強大的蘑菇，離薩布拉金非常近。$B$B不過你一定要小心，老兄。他們會叫它破頂是有原因的。如果你沒有做好適當的防護措施就和它靠的太近，它會朝你爆開來!噗!一個毒性孢子雲就會跑到你頭上。$B$B我拿它們來研究過，但現在都用的差不多了。', '幫巫醫·托卡斯帶6個破頂蘑菇來。', '', '去贊加沼澤找薩布拉金的巫醫托爾加什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9815 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9815, 'zhTW', '摧毀菌體', '感染最嚴重的水元素在西南方的哈剌尼盆地，被遺棄的哈剌城之下。有些不幸的元素不需要任何環境的衝擊就會被摧毀，而低劣菌體一旦被摧毀後就要從世界上徹底移除。$B$B你想想，低劣菌體留下了被汙染的殘骸小球，如果它未被處理掉就會散播並進一步污染環境。$B$B摧毀這些低劣菌體，把他們浮泥核心帶回來給我。', '納葛蘭，元素王座的元素師羅艾柏要你取得5個浮泥核心。', '', '去納格蘭找元素王座的元素師魯艾普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9816 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9816, 'zhTW', '你看過他們嗎?', '這個沼澤少了一個東西，老兄!這裡沒有魚人。$B$B別擔心，老兄，我有個辦法可以解決這個問題。看到那邊的嘎鉤和哥鉤了嗎?我打算把魚人的禮物送給失落者!$B$B帶著這個籠子到匕首沼地村再把他們釋放在東北邊的小屋那裡。你知道我不能讓嘎鉤和哥鉤跟你一起冒險，但我會給你一籠子的彩色小魚人。你會在那裡看到一塊平坦的石頭，就把它放在那裡然後打開籠子就好!', '帶著魚人鐵籠並將它放在匕首沼地村附近的平坦岩石上。', '', '去贊加沼澤找薩布拉金的巫醫托爾加什。', '在匕潭村放生小魚人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9817 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9817, 'zhTW', '血鱗領導者', '塞納里奧遠征隊在此發佈賞金懸賞納吉斯·法亞司，血鱗納迦的首領。納迦巫女上次被看到是在毒蛇之湖，贊格沼澤的北邊區域。$B$B血鱗是相當危險的生物，接近他們的領導者更要格外小心。$B$B想獲得賞金的人就要和塞納里奧避難所的守望者漢姆特回報。', '殺了毒蛇之湖的納吉斯·法亞司再回到贊格沼澤的塞納里奧避難所找守望者漢姆特領取獎勵。', '', '去贊加沼澤找塞納里奧庇護所的監護者哈穆特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9818, 'zhTW', '地底之下', '某個東西在責罵著地底。它擊打地面好像要懲罰它一樣。$B$B*砰*$B$B<安崔哥用拳頭捶打著自己的胸口。>$B$B它發出這個聲音十萬次了。不停地擊打。大地暈眩。它現在正向我們呼叫。$B$B葛爾道格和我說話。葛爾道格知道有個力量正逼迫元素出來。某個地底下的力量。$B$B去和葛爾道格談談。不，聽葛爾道格的，不要說話。聽葛爾道格說……', '和葛爾道格溝通。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9819, 'zhTW', '痛苦的大地', '把篡位者帶來。你會找到他。跟著大地之路走。你先讓痛苦的大地之靈安息。一定要再次沉睡。$B$B<葛爾道格猛力將拳頭打入地面，傳出臭氣薰天的泥土味。>$B$B一定要沉睡!$B$B<葛爾道格指向東南邊。>$B$B找到山脈附近的靈魂。靠近山丘。靠近岩石。靠近大地。$B$B讓他們安息。$B$B泰拉蕊盆地……東南方。', '納格蘭元素王座的戈達烏要你消滅10個被折磨的地靈。', '', '去納格蘭找元素王座的戈達烏。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9820 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9820, 'zhTW', '懸賞:葛洛卡老大', '懸賞-無論死活:葛洛卡老大，安格拉斯砍蘑菇活動的監督者。$B$B這個野人和他那些揮舞著斧頭的同伴們在鎮的北方砍了許多蘑菇。如果他不停下來，他和他的人會砍出一條通到薩布拉金的路來。$B$B任何將葛洛卡老大的頭顱帶來給暗影獵人丹傑的人會重重有賞。', '將葛洛卡老大的頭顱帶給薩布拉金的暗影獵人丹傑。', '', '去贊加沼澤找薩布拉金的暗影獵手德恩加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9821, 'zhTW', '吃掉精髓', '<葛爾道格撿起一塊石頭開始咀嚼它。>$B$B葛爾道格嘗了嘗味道。葛爾道格知道這塊石頭到過哪裡。$B$B<葛爾道格舉起他一隻粗壯的腿重踏到地上。>$B$B看。看看納葛蘭。$B$B<葛爾道格指引你看他的腳印。在那腳印裡你看見一個完美的納葛蘭地圖，標記著葛爾道格要你去摧毀元素的地方。>$B$B摧毀他們!幫葛爾道格把可以吃的部分帶來。$B$B帶著地圖。', '將10塊被激怒的碾壓者的核心交給納格蘭元素王座的戈達烏。', '', '去納格蘭找元素王座的戈達烏。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9822, 'zhTW', '逼近的攻擊', '巨魔砍蘑菇的活動選在這個地點絕對不是意外。我一直懷疑他們是要準備對薩布拉金進行攻擊。$B$B我一定要確切地知道，$n。巨魔在西北方有另一個前哨，安格拉斯營地。如果他們在準備攻擊，那裡便會有他們計畫的證據。去那裡，$n，搜索營地尋找他們真正意圖的蛛絲馬跡。帶著所有可疑的東西回來找我。', '將安格拉斯攻擊計畫帶回薩布拉金給暗影獵人丹傑。', '', '去贊加沼澤找薩布拉金的暗影獵手德恩加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9823, 'zhTW', '不是你死就是我活', '為了停止安格拉斯的威脅，我們一定要殺了他們的領導者，血拳主宰。不過我們會做的更好。我們會藉由懲戒他和他的跟隨者來警告其他人。$B$B去安格拉斯要塞解決我們的敵人。要塞就在薩布拉金西北邊小島上的洞穴裡。你會在安格拉斯營地後方看到一座由倒塌的磨菇做成的橋。$B$B趕盡殺絕，$n。他們不會放過我們的。', '殺了血拳主宰，10個安格拉斯蠻槌兵，和10個安格拉斯噬魂者再向薩布拉金的暗影獵人丹傑回報。', '', '去贊加沼澤找薩布拉金的暗影獵手德恩加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9824 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9824, 'zhTW', '秘法干擾', '我試著要取得一種卡拉贊能量的印記……當然，是為了個人的計畫。不幸的是，我這裡沒人可幫我。如果我可以接近一個地下水源，我的水晶就能接收更清楚的訊號。$B$B我聽說一個地下水池塘在我們底下的地窖裡。不過這整個地方爬滿了鬼魂，而冒險到那裡對我這年紀的人來說是很危險的。你看怎麼樣;你會幫助一個老人去使用水晶嗎?', '到大師的地窖，在靠近地下水源的地方使用紫羅蘭占卜水晶再回到卡拉贊外面的大法師艾特羅斯那裡。', '', '去找逆風小徑的大法師奧圖魯斯。', '收集地下水井的訊號', '收集地下水池的訊號', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9825 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9825, 'zhTW', '不安的活動', '你應該有注意到，卡拉贊外面爬滿了鬼魂生物。它們存在的原因未知，而這讓我很惱怒!$B$B幫我把他們的鬼魂精華帶來，這樣我就可以研究他們的天性。卡拉贊有很多秘密，$n。我決心要把它們一一解開。', '帶10個鬼魅精華給卡拉贊外面的大法師艾特羅斯。', '', '去找逆風小徑的大法師奧圖魯斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9826 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9826, 'zhTW', '達拉然的聯繫', '這些跡象是對我們不好的預兆，$n。我一直都不太會保守秘密，所以我要告訴你一點關於我的組織的事，紫羅蘭之眼。$B$B我們是肯瑞托的密探，達拉然的參議元老。我們被指派看守卡拉贊和麥迪文，以確保事情不會失控。$B$B而他們做的……非常快速，就在麥迪文消失後。$B$B這份報告詳細列出我的發現。把它交給給大法師賽卓克，另外也是紫羅蘭的消息;你會在達拉然的郊區找到他。', '將艾特羅斯的報告帶給達拉然郊區的大法師賽卓克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9827 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9827, 'zhTW', '枯萎的孢子臺', '仔細研究孢子臺發現很多缺口，好像原本連接著什麼。大量不同的菌類成了一個謎題。它不健康，但你很難知道它正常運作時的功能為何。$B$B或許某個和贊格沼澤動植物熟悉的人能告訴你更多關於這個孢子臺的事。', '將枯萎的孢子臺帶到泰倫多爾給洛安瑪。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9828 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9828, 'zhTW', '枯萎的孢子臺', '仔細研究孢子臺發現很多缺口，好像原本連接著什麼。大量不同的菌類成了一個謎題。它不健康，但你很難知道它正常運作時的功能為何。$B$B或許某個和贊格沼澤動植物熟悉的人能告訴你更多關於這個孢子臺的事。', '將枯萎的孢子臺帶到斯溫派特崗哨給瑞伏基。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9829 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9829, 'zhTW', '卡德加', '艾特羅斯的報告讓人很不安。我們認為卡拉贊將自己閉關不與外界往來是很不妙的。我們原本有內應在裡面，但是從此之後我們再也沒他們的消息了。現在又出現了這個……惡魔放射物。我們一定要調查清楚。$B$B唯一能重新開啟卡拉贊的人應該已死了:卡德加和麥迪文。$B$B我們希望後者是真的死了，但我們最近發現他的學徒，卡德加還好好的活在撒塔斯城。找到他並將艾特羅斯的報告交給他。', '將艾特羅斯的報告送到泰洛卡森林給撒塔斯城的卡德加。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9830 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9830, 'zhTW', '刺針毒素', '當我和德萊尼交談時，我常感覺他們認為自己和他們的環境遠離。很多人好像同情我的同胞，破碎者，他們口中失去什麼的人。$B$B我們破碎者或許是失去了我們對聖光的傾向，但我們的經驗讓我們和這塊土地更親近。$B$B我的人民看的見少數德萊尼才看的到的機會。舉例來說，住在南邊和西邊的沼光流血者的毒囊。它有從打獵到治療的各種用途。', '帶6份沼光流血者毒囊給奧雷伯爾港的保魯。', '', '去贊加沼澤找奧雷柏爾營地的普爾魯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9831 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9831, 'zhTW', '卡拉贊的入口', '這份報告的消息讓我十分困擾，$n。不過，要進入卡拉贊的入口相當困難。$B$B你知道，當我清楚我被孤立在這裡的時候我就把鑰匙分成了三半。$B$B我將鑰匙放在附魔的容器裡，再把它們放在當時安全的地方。$B$B但隨著外域承受的黑暗轉變，一切今非昔比。第一個碎片在暗影議會接管的奧齊頓區域。把那個碎片拿來給我。', '卡德加要你進入奧齊頓的暗影迷宮並從藏在那裡的秘法容器取得第一塊鑰匙碎片。', '', '去找撒塔斯城的卡德加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9832 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9832, 'zhTW', '第二和第三個碎片', '我把第二個碎片藏在毒蛇之湖的底部，早在這名字還沒出現以前。納迦接手後在那裡安裝的巨大排水管好像把容器裡的東西都吸入盤牙蓄湖深處了。$B$B第三個碎片會是最難到手的，因為我在那魯還控制風暴要塞的時候就把它留在裡面了。現在的統治者是凱爾薩斯，而我留下碎片的房間已經變成監獄了。$B$B幫我把這些剩下的碎片拿來，$n。希望你會成功。', '在盤牙蓄湖的秘法容器裡取得第二塊鑰匙碎片，風暴要塞的秘法容器裡取得第三塊鑰匙碎片。完成任務後回到撒塔斯城的卡德加那裡。', '', '去找撒塔斯城的卡德加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9833 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9833, 'zhTW', '溝通管道', '伊庫堤帶領我們到贊格沼澤的原因之一是為了幫助開啟德萊尼和卡爾奈在納葛蘭家園，泰拉的溝通管道。為了讓信差快速地往返泰拉和泰倫多爾，我們一定要保護道路。$B$B在我們來這裡的路上，我們遭到沼牙分割者多次的攻擊。我們可以反擊他們，但他們會對隻身的信差造成可怕的威脅。減少他們的數量可以幫助穩固我們信差的安全。', '奧雷伯爾港的保魯要你去殺死12個沼牙分割者。', '', '去贊加沼澤找奧雷柏爾營地的普爾魯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9834 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9834, 'zhTW', '自然護甲', '瑪克吐一直都可以看見一哩外的一個德萊尼穿著閃亮護甲逼近，就連在這黑暗的沼澤都一樣!$B$B瑪克吐想嘲笑他們，但他想起他們對卡爾奈很好，所以他想教他們卡爾奈是如何製作護甲的。$B$B沼爪痛擊者黑暗，多鱗的皮革可以做出瑪克吐穿過最好的一些護甲。如果$n可以幫瑪克吐帶來這些深藏在毒蛇之湖的沼爪痛擊者的皮革，他會樂於分享他的護甲。', '帶8塊沼爪皮給奧雷伯爾港的瑪克吐。', '', '去贊加沼澤找奧雷柏爾營地的瑪克圖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9835 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9835, 'zhTW', '安格拉斯入侵', '你在這裡看到的小群破碎者是從納葛蘭一個較大的聚集地來的外交使團。卡爾奈，如我們自稱，是想和我們德萊尼兄弟重新團結的破碎者。$B$B我的團隊來這裡加強卡爾奈與泰倫多爾的德萊尼關係。$B$B如果安格拉斯巨魔有他們的方法，這座神廟就保存不了多久了。他們清光了開闢泥沼高聳的蘑菇，更逼近到我們的避難所。如果你自認是我們的朋友，就幫助我們打敗這個敵人。', '殺死10個安格拉斯巨魔和5個安格拉斯薩滿再回到奧雷伯爾港的伊庫堤那裡。', '', '去贊加沼澤找奧雷柏爾營地的伊庫提。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9836 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9836, 'zhTW', '大師之觸', '我把我還是學徒時的鑰匙組合好了。它看起來完全保有鑰匙的功能。不過，說到要開啟卡拉贊，這可能也只是一小塊金屬而已。$B$B沒有麥迪文的同意，這把鑰匙就沒有用。是的，我當然知道麥迪文已死。這只是讓事情變的困難，但不是不可能。$B$B在艾澤拉斯有個地方叫時光之穴，由銅龍軍團守護著。想辦法進到裡面，穿過時光讓麥迪文賦予鑰匙能力。', '進入時光之穴說服麥迪文讓復原的初生之鑰恢復能力。', '麥迪文的觸控', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9837 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9837, 'zhTW', '回到卡德加那裡', '我在記憶片段中曾見過一些圍繞在你跟這把鑰匙之間，將會發生的事情。$B$B<麥迪文好像剛見到鬼一樣看著你。>$B$B你的前方有艱難的日子在等著你，$n。希望你的力量不會讓你失望。$B$B關於那把鑰匙，等卡德加被派來我這裡後我會交給他。沒有比他更好的學徒了。$B$B我想你會需要一把自己的鑰匙。$B$B<麥迪文把手伸進他的長袍並交給你他自己的鑰匙。>$B$B去吧。祝你好運，$c。', '回到撒塔斯城的卡德加那裡並給他大師之鑰。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9838 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9838, 'zhTW', '紫羅蘭之眼', '一個重大的責任落到你肩上，$n。如果紫羅蘭之眼觀察到的現象是可信任的，那你一定要幫他們。$B$B因為所有我和賽卓克的意見不合中，像這樣的人做的事仍是重要的。不過，要確定他們不會利用你。記住你才是鑰匙的關鍵，不是他們。但如果卡拉贊的危險是真的，那麼他們最好準備引導你去解決它。回去找艾特羅斯並盡全力幫助他。', '和卡拉贊外的大法師艾特羅斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9839 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9839, 'zhTW', '血拳主宰', '任何巨魔部族的中心都是它的領導者。沒有領袖，安格拉斯的組織就會消失，然後他們就會藉由打鬥來決定誰是下一個領導者。$B$B雖然我們看過這區域的巨魔，他們的真正力量還是聚集在西北方的安格拉斯要塞。墮落蘑菇旁有個沼澤，連接沼澤的小島上有個洞穴，就在那裡。$B$B去那擊敗血拳主宰。那會讓我們可以暫時休息一下。', '伊庫堤要你去殺了血拳主宰和10個安格拉斯蠻槌兵。完成任務後回到奧雷伯爾港。', '', '去贊加沼澤找奧雷柏爾營地的伊庫提。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9840 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9840, 'zhTW', '評估狀況', '既然我們找到回麥迪文哨塔的路 - 或是說你們找到 - 我們第一件要做的事就是先了解裡面的情況。$B$B我們有一個滲入卡拉贊的密探已設法將她的觀察記錄下來。不幸的是，卡拉贊被毀後不久就傳來了她的死訊。卡拉贊的鐵匠，卡爾侖也是我們的人。雖然他不是紫羅蘭之眼的一員，但他應該能幫助我們找到琪安娜的日誌。去裡面找他。', '找到卡拉贊裡的卡爾侖。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9841, 'zhTW', '以牙還牙', '有這個來自地獄的可恨嗡嗡聲根本沒辦法工作!你聽到了嗎?$B$B我沒辦法把它趕出我腦袋裡!我也知道究竟是什麼在發出這聲音。是那些該死的沼光流血者!這些噪音總是從村子的南方還有西方傳來。$B$B它們太大隻了以致於無法用蒼蠅拍打死，也無法用腳踩死或者揮手趕走它們。停下那可惡的嗡嗡聲唯一的方法就是殺了它們。我不管你是怎麼做的，$n，讓他們安靜下來!', '殺死8個沼光流血者再回薩布拉金的坎巴利卡那裡。', '', '去找贊加沼澤的加巴林卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9842, 'zhTW', '最鋒利的劍', '沼澤潮濕的空氣讓我的金屬工具都生鏽了。它讓木工很難進行，所以我放棄了金屬劍刃。$B$B後來我發現住在鎮南邊和西邊的沼牙分割者長著我從未擁有過的銳利鋒刃。它們能夠抵抗鏽蝕和磨損。只是把它們接在柄上有點不易處理，不過我已找出解決之道了。我會很感激你為我帶來的尖刃。', '帶10把沼牙分割者之刃給薩布拉金的坎巴利卡。', '', '去找贊加沼澤的加巴林卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9843, 'zhTW', '琪安娜的日誌', '你說你在找什麼?琪安娜?$B$B我好像有認識一個叫這名字的人。她住在客房。我應該把它當成秘密的，對吧?$B$B你說你和紫羅蘭之眼一起的嗎?不，我從沒聽過他們。$B$B如果你不介意，我要回去工作了。$B$B<卡爾侖好像已經忘了你的存在一樣。>', '搜索卡拉贊的客房尋找琪安娜的日誌並帶給卡拉贊外的大法師艾特羅斯。', '', '去找逆風小徑的大法師奧圖魯斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9844, 'zhTW', '惡魔存在', '琪安娜的最後幾個入口證實了我們認為惡魔出現在卡拉贊裡的懷疑。$B$B她察覺燃燒軍團密探的到來，依她描述是從哨塔頂端來的。$B$B她的入口停在這裡。$B$B卡拉贊是個非常重要的地方，$c。它是虛空的傳送門，照亮其他世界的燈塔。它若落入錯誤的人手裡其後果是可以想見的。一定要阻止這個惡魔入侵。而你，$n，是唯一有著鑰匙的人。', '大法師艾特羅斯要你去摧毀卡拉贊頂端的惡魔存在。', '', '去找逆風小徑的大法師奧圖魯斯。', '摧毀惡魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9845, 'zhTW', '擊敗釣魚者的對手', '在地獄火半島的荒地跋涉後能到一個有水的地方真是令人感到慰藉。我本來擔心外域沒有好的釣魚場所。$B$B現在我很慶幸我有把釣魚配備使勁的搬來。大部分的時候，釣魚是很好的，除了那些在毒蛇之湖不好的沼爪痛擊者。$B$B他們不但把魚都嚇跑，還大膽的把我鉤子上的餌給咬走。我花在重新裝餌的時間比我釣到魚的時間還要多!', '殺死10個沼爪痛擊者再回到薩布拉金的祖賈亞那裡。', '', '去贊加沼澤找薩布拉金的蘇爾加亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9846, 'zhTW', '菲拉芬靈魂', '據說沼澤中最強大的失落者部族，菲拉芬，擁有強大的醫術。或許這樣的傳言沒有證實，但任何能幫助我引導這世界靈魂的方法都不能被忽略。$B$B找到菲拉芬秘法師、菲拉芬獵人還有菲拉芬德魯伊，$n，奪得他們的圖騰。所有我想知道的一切應該都刻在那個圖騰的表面上。', '帶10個菲拉芬防護圖騰給薩布拉金的先知賈尼迪。', '', '去贊加沼澤找薩布拉金的先知亞尼迪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9847, 'zhTW', '靈魂助手?', '我們一定要了解這個蛇靈魂究竟擁有多大的力量，還有它是否可以屈服於我們的意志。想像我掌控一個外域靈魂的力量時可以做些什麼事!$B$B帶著這個圖騰走向通往波哈姆廢墟的樓梯底部吧。將圖騰放在地上它就會自己進行剩下的運作。除非靈魂表明否則它無法顯現誰使用了那個圖騰。', '帶著菲拉芬圖騰到波哈姆廢墟的樓梯底部並將它插在地上。將你的發現回報給薩布拉金的先知賈尼迪。', '', '去贊加沼澤找薩布拉金的先知亞尼迪。', '召喚毒蛇之魂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9848, 'zhTW', '匕首沼地的秘密', '蟲，蟲，蟲!沼澤充滿了蟲而我的同伴似乎對它們很著迷。$B$B嗯，我受夠蟲了!有種新東西更能引起我的興趣。西邊有個失落者的村子，他們自稱為匕首沼地。$B$B整個部族都是由高度專業的刺客所組成。我注意到他們會調製並使用一種特別強效的毒藥。我超想知道更多關於那毒藥的事，但那將需要一個配方副本和一個樣本瓶。', '將匕首沼地毒藥手冊和匕首沼地毒藥瓶帶給奧雷伯爾港的提莫斯·丹尼爾。', '', '去贊加沼澤找奧雷柏爾營地的迪莫斯·丹尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9849 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9849, 'zhTW', '粉碎外表', '<葛爾道格從背上折斷一塊黑檀岩石。>$B$B你獲得一塊大地之怒。帶著葛爾道格的巨礫並將它投向毒藥岩石。粉碎它們的甲殼來發掘真相。摧毀僭取者的爪牙再帶著他們的名字回去找葛爾道格。$B$B你可以在世界的邊緣找到粉碎的元素。西南邊。', '納葛蘭，元素王座的葛爾道格要你殺死30個古羅克的爪牙。', '', '去納格蘭找元素王座的戈達烏。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9850 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9850, 'zhTW', '裂蹄專精', '你已向我證明你可以找到並擊敗一個普通的裂蹄，但更危險的是公裂蹄。$B$B獵殺三十隻。然後你就可以來和我談談你的打獵技能。$B$B到納葛蘭中央區域的西邊的南邊找他們。', '殺死12頭裂蹄公牛，然後向納格蘭奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里覆命。', '', '去納格蘭找奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9851, 'zhTW', '裂蹄專精', '班薩爾是外域所有裂蹄中最兇猛、最難對付的一個。她也是最粗野的一個。$B$B據說她都在歐夏剛附近的靈魂牧場和她的裂蹄群閒晃。$B$B你想真正證明你的打獵專精嗎?幫我把她的角帶來!', '取得班薩爾之角再回到納葛蘭找奈辛瓦里狩獵隊的赫米特·奈辛瓦里。', '', '去納格蘭找奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9852 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9852, 'zhTW', '最後的浴血之戰', '住在納葛蘭的生物有一隻叫做長牙的皇后。她是個你在其他地方都看不到的巨大伊萊克!$B$B你會對這個名字害怕是正常的。巴奇洛爾、卡特瑞普以及班薩爾都無法跟她比擬。聽說可以在眺望歐夏剛的西南方巨大峭壁上找到她。如果你有膽的話幫我把她厚實的心臟帶來。$B$B因為你很有可能不會再回來，要在我這裡留一封信給你的下一個同胞嗎?', '將長牙之心帶到納葛蘭交給奈辛瓦里狩獵的赫米特·奈辛瓦里。', '', '去納格蘭找奈辛瓦里狩獵隊營地的赫米特·奈辛瓦里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9853 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9853, 'zhTW', '『篡位者』古羅克', '我們一定要召喚古羅克。你要召喚古羅克然後摧毀他。$B$B你一定要去西北方的戰槌山丘並找到巨魔崇拜的古羅克。你將戰槌巨魔的巨魔頭顱放在古羅克的土靈烙痕上。只有那樣古羅克才會出現。七個頭顱。$B$B如果你還活著，就把古羅克的大地頭盔帶回來給葛爾道格。葛爾道格會把頭盔粉碎。$B$B<葛爾道格狠狠地對空咬了一口，動搖著你腳下的大地。>', '納葛蘭，元素王座的葛爾道格要你殺了『篡位者』古羅克並將古羅克的大地頭盔帶回來。', '', '去納格蘭找元素王座的戈達烏。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9854 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9854, 'zhTW', '風翼專精', '你像我一樣為打獵而活嗎，$c?你想尋求在你追蹤獵物時伴隨的平靜嗎?你知道什麼才能向你死去的獵物最後的心跳致敬嗎?我會幫助你達成這個目標。$B$B納葛蘭是一塊蒼翠繁茂的土地，是這破碎世界中充滿了生命的地方。殺死一些風翼貓頭鷹再來和我談談。$B$B你可以在很多地方找到他們，但從西邊開始會是最好的方向。', '殺死12只風鵬，然後向納格蘭奈辛瓦里狩獵隊營地的“好兒子”沙度·遠行者覆命。', '', '去納格蘭找奈辛瓦里狩獵隊營地的“好兒子”沙度·遠行者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9855 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9855, 'zhTW', '風翼專精', '如果你想要有一天可以追蹤最強大的獵物，那你一定要永遠督促自己!當你尚未準備好的時候，我會指引你走向正確的方向。$B$B還有另一種風翼貓頭鷹是更致命的。尋求這個貪婪的風翼貓頭鷹來測試你的勇氣。你可以在納葛蘭中心的西邊和西南邊找到他們。', '殺死12只飢餓的風鵬，然後向納格蘭奈辛瓦里狩獵隊營地的“好兒子”沙度·遠行者覆命。', '', '去納格蘭找奈辛瓦里狩獵隊營地的“好兒子”沙度·遠行者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9856 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9856, 'zhTW', '風翼專精', '你準備好了，$c。準備好挑戰所有風翼貓頭鷹的母親，卡特瑞普。在獵捕那麼多她的孩子之後，你給她一個擊敗你的機會!去西邊較大的風翼貓頭鷹那裡找她。$B$B如果你活了下來，把她的眼睛帶給我。', '將卡特瑞普之眼帶到納葛蘭給奈辛瓦里狩獵隊薩杜費茲。', '', '去納格蘭找奈辛瓦里狩獵隊營地的“好兒子”沙度·遠行者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9857 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9857, 'zhTW', '塔巴克專精', '我想我今天不會去打獵。你要代替我去嗎?$B$B我告訴赫米特我要去獵捕一些塔巴克，看起來到處都是他們的蹤影。雄鹿特別好獵捕。他們都聚集在樹旁邊。$B$B你覺得你可以幫我搞定這件事嗎?', '殺死12頭塔布雄羊，然後向納格蘭奈辛瓦里狩獵隊營地的哈羅德·蘭恩覆命。', '', '去納格蘭找奈辛瓦里狩獵隊營地的哈羅德·蘭恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9858, 'zhTW', '塔巴克專精', '這該死的擦傷已經讓我痛苦不堪。所以，你準備好再次……<咳嗽>……代替我嗎?$B$B這次你要獵捕一些食棘者。他們更難搞定而且比其他雄鹿更狡猾，所以你要放聰明點。去找他們……<咳嗽>……他們就躲在納葛蘭中部靠西邊和靠南邊的樹下。$B$B快點，去那裡……<咳嗽>……讓赫米特看看你的本事。我沒事的。', '殺死12頭塔布羊食棘者，然後向納格蘭奈辛瓦里狩獵隊營地的哈羅德·蘭恩覆命。', '', '去納格蘭找奈辛瓦里狩獵隊營地的哈羅德·蘭恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9859, 'zhTW', '塔巴克專精', '<痛苦的咳嗽。>$B$B別擔心……<咳嗽>……我。我沒事的。只是……<咳嗽>……擦傷。$B$B還是一樣，我想你要……<咳嗽>……再代替我……<咳嗽>……一次。$B$B你一定要找到偉大的巴奇洛爾，雄鹿的……<咳嗽>……王。如果你要……<咳嗽>……帶朋友一起去也可以。$B$B把他的一個蹄帶給我……<咳嗽>，<咳嗽>……做為確證。$B$B去找他……<咳嗽>……就在納葛蘭很遠的西邊領導著他的牧群。', '取得巴奇洛爾之蹄並帶回納葛蘭交給奈辛瓦里狩獵隊的哈洛德·蘭恩。', '', '去納格蘭找奈辛瓦里狩獵隊營地的哈羅德·蘭恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9860, 'zhTW', '新的指令', '立刻回到賽卓克那裡，$n。你對紫羅蘭之眼提供的協助會得到獎勵的。$B$B想想你要我們和我們的組織做些什麼，$c，但獲得達拉然大法師的好感也不會讓你後悔的。', '和達拉然郊區的大法師賽卓克談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9861, 'zhTW', '哀嚎之風', '這個緊密的元素空氣團用一種你無法理解的語言和你說話。你認為那是元素的語言:卡林多語。或許元素王座的某個人會對這個不尋常的發現有些解釋。', '在元素王座找到會講卡林多語的人再讓他看看哀嚎之風。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9862, 'zhTW', '黑暗之血腐敗者', '黑暗之血在俘虜和折磨大氣的靈魂!黑暗之血是我的同胞:一支服從於邪惡莫斯萊克，盤牙的野獸之王的破碎者部族。$B$B風之靈表示黑暗之血腐化者俘虜了其他的風之靈，並利用他們製造元素階級裡的混亂。看來黑暗之血最近劫掠了西南方一個叫日春的獸人村子，並使用強大的元素魔法干擾湖泊。找到黑暗之血腐化者並摧毀他們。', '納格蘭元素王座的元素師莫格要你殺死5個暗血淨化者。', '', '去納格蘭找元素王座的元素師魯艾普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9863, 'zhTW', '邪惡的塑像', '我們的領導者已死，我們只剩下四面八方襲來的攻擊了。邪惡的黑暗之血部族現在攻擊我們是大好時機!$B$B最近幾天，我們遭到破碎者不下5次的襲擊。他們甚至奪去了我們唯一的領土:日春崗哨。$B$B我們一定要還擊讓他們見識我們的力量!擊敗邪惡的崇拜者，把他們扭曲的崇拜塑像帶來，這樣他們才能改邪歸正。', '將10個暗血神像交給納格蘭加拉達爾的先知古庫斯。', '', '去納格蘭找加拉達爾的先知古庫斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9864 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9864, 'zhTW', '失蹤的戰友', '在最後一次黑暗之血襲擊後，一群年輕人決定採取行動。我們試著阻止他們但憤怒已經讓他們失去控制。距離上次看見我們親愛的年輕人已經有一個星期了。$B$B拜託，$r，你一定要找到他們!他們才剛進入青春期。他們怎麼可能打的過這樣的野蠻人呢?$B$B他們往鎮外西邊的路上走。沿著那條路尋找我們年輕人的蛛絲馬跡。$B$B還有$n，如果你還愛惜你的生命，避開哈剌。那是戰區。', '試著找到失蹤的卡拉達爾戰友。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9865 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9865, 'zhTW', '一朝為戰士', '我並不認識你，陌生人，但是我請求你的幫助。我羞於要求你的幫忙，但我只是一個小小的獸人而已。$B$B我的心中湧起了一股前所未有的感受。我……我要報仇。我要他們以牙還牙。你的同胞們曾經也有這種感受嗎?我希望撿起我的戰斧然後把敵人劈成兩半。不停的揮舞武器直到我的兩隻手臂無力的垂在我的兩旁，精力用盡為止。你在那邊可以找到我們的敵人……殺死他們……殺光他們……', '消滅20個暗血清道夫和10個暗血掠奪者。', '', '去納格蘭找瑪格漢車隊的小薩魯法爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9866 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9866, 'zhTW', '他將走遍大地……', '你可以幫我最後一個忙嗎，$n?我不想回到卡拉達爾。我相信我的命運在別的地方 - 我會在那裡有一個更大的使命。$B$B拜託你，去找先知科霍克，告訴他我不會回去了。我不能回去。我一定要走遍大地……他會懂的。', '將消息送給卡拉達爾的先知科霍克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9867, 'zhTW', '黑暗之血領導者……', '我們最近幾週失去了很多朋友。$B$B我們幾十年來對抗納葛蘭的巨魔，但現在一個新的威脅又興起了。黑暗之血的破碎者部族攻擊我們在西南方的日春崗哨漁村，還將所有住在那個鎮上的居民都殺了或驅逐。$B$B雖然其他人都認為最好的做法就是趕盡殺絕，但我知道我們一定要摧毀他們的領導者。我不知道他們的領導者是誰，但我想當你找到他的時候你就知道了。', '納葛蘭，卡拉達爾的先知馬卡戴斯要你幫他把黑暗之血奧拓爾的頭顱帶來。', '', '去納格蘭找加拉達爾的先知瑪加迪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9868 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9868, 'zhTW', '卡達許圖騰', '謝謝你，陌生人。要不是你他們早就把我殺了。$B$B三天前我在卡拉達爾的夜間戰鬥中被這些黑暗之血綁架。我到目前發現的事會嚴重動搖外域的根基:這些野蠻人想取回卡達許圖騰!我們不能讓圖騰落入黑暗之血的手中!$B$B你一定要幫我逃出去。還有陌生人，如果我沒有平安回到卡拉達爾，你一定要告訴卡爾洛斯這裡發生的事……', '護送瑪格哈俘虜離開日春崗哨。如果你成功的話就和卡拉達爾的卡爾洛斯談談。', '營救瑪格漢俘虜', '去納格蘭找加拉達爾的加爾魯什。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9869, 'zhTW', '元素王座', '你好，$r。我是洛奇，陶土議會的元素使者。我是來泰拉通知卡爾奈元素的狀況。$B$B我可以請你幫個忙嗎?你可以前往納葛蘭北邊山丘的元素王座，在天歌湖後方，然後告訴元素師莎爾瓦克我已平安到達泰拉了嗎?她會為這小小的動作而獎勵你的。', '元素師洛奇要你前往元素王座和元素師莎爾瓦克談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9870, 'zhTW', '元素王座', '你好，$r。我是亞哈，陶土議會的元素使者。我是來卡拉達爾通知瑪格哈元素的狀況。$B$B我可以請你幫個忙嗎?你可以前往納葛蘭北邊山丘的元素王座，在天歌湖後方，然後告訴元素師莎爾瓦克我已平安到達卡拉達爾了嗎?她會為這小小的動作而獎勵你的。', '元素師亞哈要你前往元素王座和元素師莎爾瓦克談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9871, 'zhTW', '黑暗之血入侵者', '羊皮紙上畫著一個粗糙的納葛蘭地圖。在泰拉的位置上有一個大大的紅色「X」。看來這些野蠻人正計畫攻擊這個城市。把黑暗之血入侵計畫帶到泰拉給阿爾克隆。', '將黑暗之血攻擊計畫帶給阿爾克隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9872, 'zhTW', '黑暗之血入侵者', '羊皮紙上畫著一個粗糙的納葛蘭地圖。在卡拉達爾的位置上有一個大大的紅色「X」。看來這些野蠻人正計畫攻擊這個城市。把黑暗之血入侵計畫帶到卡拉達爾給卡爾洛斯。', '將黑暗之血攻擊計畫帶給卡爾洛斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9873 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9873, 'zhTW', '我的老友奧拓爾……', '這些入侵計畫是某個我曾經認識的人寫的。黑暗之血奧拓爾，他曾是一個高尚的破碎者，對元素相當精通，現在是泥沼領主莫斯萊克身邊一個昏庸的應聲蟲。$B$B這些計畫說明他們奪下了西北方一個叫日春的獸人村莊。$B$B前往日春崗哨毀掉黑暗之血奧拓爾的世界。你所做的事是為了我們大家好……', '納葛蘭，泰拉的阿爾克隆要你去殺了黑暗之血奧拓爾。', '', '去納格蘭找塔拉盆地的阿雷克隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9874 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9874, 'zhTW', '阻止蔓延', '我剛得知一個史詩級大災難的消息，$n。邪惡的黑暗之血劫掠了西北方的日春崗哨獸人村莊，還殺了那裡的居民。更糟的是，他們開始把屍體丟進日春湖裡。如果那些屍體腐爛，我們在該區域的水資源也會被危害。$B$B我接下來要給你的任務很可怕，但它一定要完成。拿著這個附魔的火炬回到日春。把所有腐爛的獸人屍體都燒毀。', '納葛蘭，泰拉的『賢者』歐塔布要你使用液態火炬摧毀10個日春崗哨居民屍體。完成任務後將液態火炬交回。', '', '去納格蘭找塔拉的先知歐圖布。', '燒掉日泉村民的遺體', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9875 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9875, 'zhTW', '未編目的品種', '羅安娜一定是漏掉了這個品種的植物。你確定你發現了一個新的品種尚未被羅安娜所記載。你最好拿去給羅安娜，看她會怎麼處理。', '將未編目的品種帶到贊格沼澤給塞納里奧避難所的羅安娜·薩威爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9876 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9876, 'zhTW', '入侵失敗', '我派了一小批德魯伊去調查你在毒蛇之湖發現的排水現象。他們本來應該很快就回來了。不用說，他們沒有。$B$B你是我們最有能力的盟友之一;我要你去找到他們並了解發生了什麼事。', '伊斯歐·風歌要你去盤牙蓄湖入口附近尋找塞納里奧遠征隊德魯伊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9877 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9877, 'zhTW', '恢復藥劑', '對抗天譴軍團的戰役讓我們死傷慘重。每天都有很多人被殺，還有更多人的命運更悲慘。天譴軍團俘虜人質也是常見的事。和在死亡之域等待他們的比起來死亡會是更好的選擇。他們在可怕的毒藥效果下喪失意志被嚴刑拷打。安寧地的藥劑師倫澤紳發明了一種解藥;去找他並取得這個恢復藥劑。', '和安寧地的藥劑師倫澤紳談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9878 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9878, 'zhTW', '解決問題', '納葛蘭的黑暗之血對我們的環境有著深遠的負面影響。元素變遷對野生生物有著極大的干擾。更糟的是，日春崗哨的夷平再次點燃了獸人對我們人民的仇恨。$B$B雖然卡爾奈和黑暗之血是不同的部族，但在獸人眼裡他們都是破碎者。$B$B我們一定要想辦法解決這個難題。前往西北邊的日春崗哨，解決黑暗之血的麻煩。', '消滅10個暗血清道夫和5個暗血掠奪者，然後向納格蘭塔拉的智者普里魯魯克覆命。', '', '去納格蘭找塔拉的智者普里\\r\\n魯魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9879 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9879, 'zhTW', '卡達許圖騰', '要是你沒來我早就被殺了，陌生人。他們在尋找遺失的聖物中已經殺了那麼多卡爾奈。$B$B他們要找的是卡達許圖騰。他們怎麼會認為我們知道這個圖騰的事，我真的不懂。圖騰不是獸人天生的工具嗎?$B$B這個消息一定要讓阿爾克隆知道。或許他知道為什麼黑暗之血會綁走卡爾奈還為了獸人工具的下落折磨他們。$B$B趁更多人來之前我們快走吧。', '護送卡爾奈俘虜離開日春崗哨。成功後再和泰拉的阿爾克隆談談。', '營救庫雷尼俘虜', '去納格蘭找塔拉的阿雷克隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9880 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9880, 'zhTW', 'Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin Cap', '', '', '', '去找地獄火半島的委任官翠希·普羅維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9881, 'zhTW', 'Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin Cap', '', '', '', '去找地獄火半島的傳令官布萊肯·黑眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9882 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9882, 'zhTW', '偷小偷的東西', '奈薩斯王子哈拉瑪德命令我們不要開始歐夏剛內部的工作，因為可能會激怒一支強大的那魯。那就像砸我們自己的腳一樣。$B$B不過，我想我可能找到了一個漏洞。$B$B你想想，我們不是唯一被這個巨像鑽石所吸引的伊斯利。一個叫卡沃希的小偷率領一群盜賊伊斯利進入歐夏剛，而他們已經開始從裡面運出大量的碎片了。$B$B$r，而你的工作就是要去那裡取回原本屬於我們的東西。', '取得10個歐夏剛水晶碎片並帶到納葛蘭交給艾瑞斯平臺的吉札。', '', '去納格蘭找埃瑞斯碼頭的傑赫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9883, 'zhTW', '更多水晶碎片', '', '', '', '去找納格蘭的傑赫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9884 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9884, 'zhTW', '會員福利', '', '聯合團照顧它的朋友是出了名的好。每個月初我都會為你準備好一些寶石做為你服務的酬勞。你獲得的寶石品質將視你對我們的忠誠度來決定。希望你會做出聰明的選擇和我們在一起。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9885 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9885, 'zhTW', '會員福利', '', '再見到你真好，$n。我已經準備好你這個月的寶石了。我多放了一點進去，藉此表達我們有多喜歡你。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9886 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9886, 'zhTW', '會員福利', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9887 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9887, 'zhTW', '會員福利', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9888 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9888, 'zhTW', '無能的領導者', '我逃過一劫，在石拳巨魔對我村子的夜間攻擊中活了下來。$B$B但我問你，陌生人:為了什麼?$B$B<喬林指著卡爾洛斯。>$B$B他拒絕給予我們協助。巨魔劫掠我的城鎮，而他坐在那裡對著一團火哭泣。我們成了什麼樣子?我們會變成什麼樣子?$B$B我派了一個斥候，科伊瑞斯去村子那裡，現在的血之谷廢墟。你可以去找他並給他協助嗎?他躲在泰洛卡和納葛蘭的邊界。', '喬林·亡眼要你找到科伊瑞斯並和他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9889 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9889, 'zhTW', '別殺那個胖子', '我看著這些野獸好多天了。胖的那個說他在等待。不過，他在等什麼，仍是個謎。$B$B我有個計畫，不過要靠你使用一些武力。你要殺死他的幾個部屬然後把他打個半死。這樣做我相信他就會告訴我們所有要知道的事了。', '泰洛卡森林的科伊瑞斯要你殺死10個石拳侵略者並鞭打無情的昂庫爾直到他說話為止。', '安克爾招供', '去泰羅卡森林找血環廢墟的無情的安克爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9890 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9890, 'zhTW', '成功!', '多年來，石拳統治著外域所有的巨魔。巨魔在克羅的領導下非常團結，對他們所給予的土地也很滿意。過去幾個月來，我們因為一支叫戰槌的新氏族失去了許多巨魔。戰槌奪去了我們在納葛蘭大部分的土地還殺了許多我們的人。$B$B我們別無選擇只能佔領這個城鎮。我們被滅絕了……$B$B克羅失蹤，石拳陷入混亂。『劍刃』蘭崔索在他不在時代理統治。', '帶著你從昂庫爾那裡得知的消息去找泰洛卡森林的科伊瑞斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9891 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9891, 'zhTW', '科伊瑞斯是懦夫', '帶著你所知道的事去找卡拉達爾的喬林。他如果聽到巨魔因為需要更多空間，就把我們的村子毀了還殺了許多人民，我保證他會很不高興。$B$B願先祖守護你……如果你需要我，我會躲在樹叢裡。', '帶著你從昂庫爾那裡得知的消息去納葛蘭找卡拉達爾的喬林·亡眼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9892 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9892, 'zhTW', '更多黑曜石戰爭串珠', '', '你取得更多戰爭串珠了嗎?你可以在遠北找到很多巨魔，就在贊格沼澤的邊界附近。', '', '去找納格蘭的傑赫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9893 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9893, 'zhTW', '黑曜石戰爭串珠', '空等歐夏剛準備開始挖掘讓我們的利潤不斷消耗，$n。$B$B幸運的是，我想出了一種替換的收入來源。納葛蘭的巨魔佩戴黑曜石做的戰爭串珠，那在任何世界都是要價不低的礦物。$B$B澤瑞德為了安全考量已解決掉一些野獸了。把戰爭串珠視為額外的獲利。或是乾脆別想那麼多，把它們帶給我就對了。', '帶10個黑曜石戰爭串珠到納葛蘭交給艾瑞斯平臺的吉札。', '', '去納格蘭找埃瑞斯碼頭的傑赫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9894 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9894, 'zhTW', '保護守夜人', '在你的旅途中，你可能會遇到一些遠征隊的守夜人。他們處理大部分的野外工事:記錄沼澤裡獨特的動物，收集樣本，和有感知力的物種聯繫。$B$B守夜人的安全是最重要的事，$c。因為沼澤野獸的攻擊，我們必須召回派去南方探勘方格洞穴的守夜人。守望者漢姆特相信殺了他們的領導者卡拉奎領主，將快速結束攻擊。', '殺了卡拉奎領主再回到塞納里奧避難所向喚風者黑蹄回報。', '', '去贊加沼澤找塞納里奧庇護所的喚風者塔魯·黑蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9895 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9895, 'zhTW', '垂死的平衡', '你有仔細地看看你的四周嗎，$n?這是個生病的大地，拼命地想讓自己保持平衡卻一直失敗。$B$B如果你知道要審視哪裡，你可以看看它的症狀。某些品種迅速地過度生長，變的更有侵略性。$B$B這種無法控制的生長例子就像泥沼行者伯克拉斯。如果你想親自看看它，就去避難所的南方水路。$B$B準備好保護自己。那個生物不知道什麼叫仁慈。', '找到並解決掉伯克拉斯，再回到塞納里奧避難所向萊司恩·月火回報。', '', '去贊加沼澤找塞納里奧庇護所的萊森·月火。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9896 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9896, 'zhTW', '黑刺的螫針的毀滅', '在卡茲格羅斯的燃燒中心旁，這裡真熱!我不怪第一批隊伍離開，但大家都知道並不是高溫把他們趕走的。不，是黑刺，雖然他們不願承認。$B$B當巨大的黃蜂不知道從哪冒出來並攻擊的時候，他們紮營在閃耀德萊尼哨塔的南方，哨塔在西邊，就在菲拉芬村的北方!我等不及想看看我把這生物的刺針帶回鐵爐堡時他們臉上的表情!', '將黑刺的螫針交給泰倫多爾的勘察員康歐。', '', '去贊加沼澤找泰雷多爾的勘探員柯納爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9897 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9897, 'zhTW', '我得救了！', '我不介意分享。我很高興從那個小人那裡被救出來，甘克利!而且我從贊格沼澤收集了好多皮革，所以一點問題都沒有!', '將大批皮革帶到納葛蘭交給奈辛瓦里狩獵隊的哈爾歐德·蘭恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9898 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9898, 'zhTW', '讓大刺針示愛', '她會是我的。喔沒錯 - 她會是我的。$B$B瑪卡莎是你見過最美麗的食人妖吧?我要想個辦法贏得她的芳心。我知道，她喜歡祖瑞伊，但那就要改變了。我會用一個安全無比的計畫。$B$B我所需要的就是想辦法展現我高超的打獵技巧，那是你進來的地方我的朋友。有一隻叫黑刺的巨大泥沼黃蜂，他就在閃耀德萊尼哨塔的南方區域，德萊尼哨塔則在西邊。幫我把他的刺針帶來，我就能使用我的魔法。', '將黑刺的螫針交給斯溫派特崗哨的瑞伏基。', '', '去贊加沼澤找沼澤鼠崗哨的裡維伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9899 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9899, 'zhTW', '未完成的工作', '誰快想個辦法讓瑞伏基清醒過來!他忽視他的職責而且還反將所有的能量致力於引起我的注意。我試著忽略他並要他停止。但根本沒有用。$B$B在他恢復過來之前，我都要跟在他後面善後。他本來應該要解決斯柏溫的，但我保證那個怪物現在還活的好好的。如果你有空的話，可以去死亡污泥的西部殺了那隻蝙蝠嗎?我會同時對付瑞伏基。', '斯溫派特崗哨的瑪卡莎要你去殺了斯柏溫。', '', '去贊加沼澤找沼澤鼠崗哨的瑪加沙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9900 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9900, 'zhTW', '卡沃希', '這個地方出現伊斯利盜賊一定會讓吉札很高興，不管我們走到哪他都只看的見機會，但那對我們的運作安全是個真正的威脅。$B$B他們的領導者卡沃希，是個危險的罪犯，我首要的目標就是消滅他。$B$B如果你想證明自己的用處，就去解決掉卡沃希。我會給你適當的獎勵。', '殺了歐夏剛附近的卡沃希再回到納葛蘭找艾瑞斯平臺的澤瑞德。', '', '去納格蘭找埃瑞斯碼頭的瑟利德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9901, 'zhTW', '未完成的任務', '聯盟派出的第一支遠征隊回報遇到一隻巨大的孢子蝙蝠，他們叫他斯柏溫。他們當時必須快點離開所以來不及殺了他，我想我得幫他們完成這個工作。$B$B他們的報告暗示那個生物就在死亡污泥的西部。我想復仇者伊達爾說過那在泰倫多爾的東北方。', '泰倫多爾的勘察員康歐要你去殺死斯柏溫。', '', '去贊加沼澤找泰雷多爾的勘探員柯納爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9902 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9902, 'zhTW', '恐怖的沼澤光之湖', '走在充滿納迦的土地上讓我知道了殘忍的真相，我那些不那麼幸運的同胞是如何被對待的。在西南方的沼澤光之湖，我看到一個非常壞心的監工玩著一個致命遊戲。就在一隻巨大的瘋狂野獸，恐懼之爪準備好要進食時，他命令他的奴隸進到水裡。$B$B我不用描述結果了。我們人數太少無法直接抵抗納迦，但我們可以殺死他們的寵物來剝奪他們的樂趣。', '殺了恐懼之爪再回到奧雷伯爾港向保魯回報。', '', '去贊加沼澤找奧雷柏爾營地的普爾魯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9903, 'zhTW', '最大的挑戰', '你已經對付過大部分的小多頭蛇，但我懷疑莫拉吉斯是否對你的表現印象深刻。他是隻狡猾兇猛的野獸，逃過許多釣魚者的追捕。$B$B我想成為他所挑戰的最後一個人。他一定藏在東北方的毒蛇之湖深處。他是個過時的傢伙;只是他還不知道而已。', '殺死莫拉吉斯再回到薩布拉金向祖賈亞回報。', '', '去贊加沼澤找薩布拉金的蘇爾加亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9904, 'zhTW', '抓到恐懼之爪', '我抓過沼澤裡所有種類的魚，唯獨一隻就是可以巧妙地躲開我。我當然抓過鰻魚和泥鰭狂怒者。但上次我去沼澤光之湖的時候，釣到一隻魚把我的線給扯斷然後逃跑。$B$B他叫恐懼之爪，他不死我是不會善罷干休的。他太大了所有的漁夫都不可能釣到他，所以我想我們只能依循舊法殺了他。', '殺了恐懼之爪再回到薩布拉金向祖賈亞回報。', '', '去贊加沼澤找薩布拉金的蘇爾加亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9905 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9905, 'zhTW', '瑪克吐的復仇', '瑪克吐上次去毒蛇之湖獵捕多頭蛇皮時，遭到他見過最大的多頭蛇攻擊。瑪克吐正要拿起他的魚叉，卻為時已晚。他只有足夠的時間逃跑免得成為多頭蛇的食物。$B$B誰知道?說不定下一次，瑪克吐就不會那麼幸運了。瑪克吐還想去那裡，他希望不會再有下次。你願意幫瑪克吐向莫拉吉斯復仇嗎?', '找到並殺死莫拉吉斯，再回到奧雷伯爾港向瑪克吐回報。', '', '去贊加沼澤找奧雷柏爾營地的瑪克圖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9906 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9906, 'zhTW', '戰鬥的訊息', '只有一種東西能推動巨魔:力量。如果讓他們覺得我們很脆弱，他們會利用這個弱點來消滅我們。$B$B卡爾洛斯或許準備放手讓巨魔雜種奪取我們的土地，但我可不同意!我要你送個訊息給石拳，$n。他們唯一能理解的訊息:野蠻。$B$B前往東南方的燃燒之劍廢墟，讓他們見識瑪格哈的力量。$B$B還有$n，在離開前先和其他人談談。', '納格蘭加拉達爾的約林·死眼要你殺死8個石拳打擊者和8個石拳秘術師。', '', '去納格蘭找加拉達爾的約林·死眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9907 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9907, 'zhTW', '大膽前進', '往正西邊去你就會發現哈剌尼盆地。盆地裡可以看見納葛蘭的雙子斷崖:北風和南風。石拳的突擊隊利用斷崖隱藏他們的巨魔土丘。$B$B我要你去找到這些突擊隊並以瑪格哈之名殺光他們。', '納格蘭加拉達爾的約林·死眼要你殺死10個石拳戰士和10個石拳法師。', '', '去納格蘭找加拉達爾的約林·死眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9908 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9908, 'zhTW', 'Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin', '', '', '', '去找地獄火半島的委任官翠希·普羅維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9909 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9909, 'zhTW', 'Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin', '', '', '', '去找地獄火半島的傳令官布萊肯·黑眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9910 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9910, 'zhTW', '軍旗與實行', '如果你要前往燃燒之劍廢墟，我有個任務要給你。帶著這些瑪格哈戰鬥戰旗，將它們插在巨魔廢墟裡三個不同的地方。最好是插在明顯易見之處，尋找巨大的燃燒柴堆。將戰旗放置於第一、第二和第三個燃燒之劍柴堆上。$B$B戰旗會為戰鬥失敗的巨魔留下持續性的影響。', '納葛蘭，卡拉達爾的『秘法師』伊萊克根要你在第一個燃燒之劍柴堆、第二個燃燒之劍柴堆以及第三個燃燒之劍柴堆上使用瑪格哈戰鬥戰旗。完成後將瑪格哈戰鬥戰旗還給他。', '', '去納格蘭找加拉達爾的秘法師埃爾卡甘。', '放置第一面軍旗', '放置第二面軍旗', '放置第三面軍旗', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9911 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9911, 'zhTW', '沼澤的伯爵', '這個血淋淋的上顎是來自一個大的不可思議的昆蟲。它的蟲體一定是贊格沼澤有史以來最大的生物。從這個上顎的狀態來判斷，它一定是捨棄了吃腐肉的飲食習慣。$B$B塞納里奧遠征隊一定會對這個樣本很有興趣。看守者里薩歐在跨格山脊西邊有個小營地。', '將『伯爵』安古拉的上顎帶給看守者里薩歐。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9912 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9912, 'zhTW', '塞納里奧遠征隊', '塞納里奧議會在外域的主要遠征部隊叫做塞納里奧遠征隊。雖然它一開始只是一個直接聽命於塞納里奧議會的小團隊，但它後來就變成一個龐大而自主的組織。$B$B塞納里奧遠征隊的領導者伊斯歐·風歌，要我們指引自願者去她的前哨站。到東贊格沼澤的塞納里奧避難所向她報告。你往西邊的主要道路走就會直接通到那裡。', '到贊格沼澤的塞納里奧避難所和伊斯歐·風歌談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9913 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9913, 'zhTW', '聯合團需要你!', '我的組織，聯合團，正在尋找一些像你一樣機智的人。你不會再找到比我們更誠實，更努力，或更好相處的伊斯利了。$B$B我們要求的只有忠誠，奉獻和合理的道德彈性。如果你有興趣可以和我們的地面運作領導者，吉札談談。你可以在歐夏剛北方的艾瑞斯平臺找到他。', '到納葛蘭向艾瑞斯平臺的吉札報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9914 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9914, 'zhTW', '象長牙', '象牙是大家爭相搶奪的東西。我有一大堆的客人排隊等著購買。$B$B你可以說服我讓你分一杯羹。$B$B漫步在納葛蘭的野生伊萊克有著我想要的高品質象牙。避開公伊萊克;他們的象牙不符合我想要的條件。$B$B喔還有別擔心，這不是偷獵;我和獸人還有德萊尼都有共識了。$B$B你和我也有共識嗎?', '收集3對象長牙帶回納葛蘭交給艾瑞斯平臺的薩德瑞克。', '', '去納格蘭找埃瑞斯碼頭的沙德雷克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9915 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9915, 'zhTW', '更多象長牙', '', '我還需要更多對野生伊萊克的象長牙。不幸的是，我的經費短缺無法支付你的利潤。不過，如果你持續提供我需要的東西，你就會得到聯合團的歡心。', '', '去找納格蘭的沙德雷克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9916 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9916, 'zhTW', '血之谷補給木箱', '石拳已把從我們村子裡偷走的補給移到納葛蘭的雙子斷崖了，就在哈剌尼盆地的西邊。$B$B你在區域裡的時候，要把眼睛張大注意那些補給木箱。如果我們可以把那些東西拿回來，就會減輕卡拉達爾監護員身上的重擔。', '納格蘭加拉達爾的秘法師埃爾卡甘要你找回10個血環補給箱。', '', '去納格蘭找加拉達爾的秘法師埃爾卡甘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9917 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9917, 'zhTW', '我眼花了嗎', '是我眼花了還是那邊真的有一支巨魔獵捕隊伍?巨魔離他們土堆那麼遠要做什麼?我一點也不喜歡這樣，陌生人。一開始是黑暗之血現在又有巨魔。我們沒有人力處理這些威脅。$B$B你可以幫我們調查東邊的巨魔活動嗎?他們的前鋒營地在距離這裡200步的東邊。你看到石拳獵人的話就表示你沒走錯。殺了他們找到計畫書!', '納葛蘭，泰拉的女獵人班吐克要你取得石拳計畫。', '', '去納格蘭找塔拉的女獵手彬圖克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9918 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9918, 'zhTW', '在我的看守下門都沒有!', '戰鬥計畫是一個巨魔副官寫的。他的名字不是叫當普就是浪普。$B$B<班吐克把羊皮紙放到一邊，仰起她的頭。>$B$B也可能是比利。$B$B不論如何，我想你該回去那裡和比利或浪普或當普，隨便啦，和他談談!試著圓滑地接近他。如果沒有用，就用武力解決。', '納葛蘭，泰拉的女獵人班吐克要你去和浪普談談。等你收集到女獵人班吐克要的資訊再回去找她。', '', '去納格蘭找塔拉的女獵手彬圖克。', '審問拉普', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9919 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9919, 'zhTW', '斯博格爾', '你是個好心的$r，$n。不像我遇過的其他人一樣。$B$B你應該見見我其他的同胞們;他們會對你的幫助很感激。把這些孢子囊帶給我的領導者，米斯恩。你會在北邊的斯博格爾找到他。', '前往重生峽谷北邊的斯博格爾，將獲救的孢子囊送給米斯恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9920 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9920, 'zhTW', '『破壞者』哞哞爾', '你一定要立刻找到哞哞爾!你可以在泰拉中央，噴水池旁找到他。確實的告訴他巨魔跟你說的話。', '納葛蘭，泰拉的女獵人班吐克要你去和『破壞者』哞哞爾談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9921, 'zhTW', '燃燒之劍廢墟', '這些巨魔獵捕集會就是入侵的前兆。我們一定要在他們召集足以拿下我們城鎮的龐大軍隊前先襲擊他們。$B$B你要開始幹活了，$r。$B$B這個區域最大的石拳集散地就在燃燒之劍廢墟，幾乎是泰拉的正東方，靠近泰洛卡邊界。去那裡讓石拳知道泰拉不會讓他們稱心如意的!', '殺死8個石拳打擊者和8個石拳秘術師，然後向納格蘭塔拉的擊碎者姆摩爾覆命。', '', '去納格蘭找塔拉的擊碎者姆摩爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9922, 'zhTW', '納葛蘭的雙子斷崖', '你表現的非常出色，$n。你準備好接受更多挑戰了嗎?$B$B我獲報得知有一大群石拳巨魔躲在納葛蘭的雙子斷崖，就在哈剌尼盆地的西北方。$B$B前往斷崖解決掉剩下的石拳巨魔吧。', '殺死10個石拳戰士和10個石拳法師，然後向納格蘭塔拉的擊碎者姆摩爾覆命。', '', '去納格蘭找塔拉的擊碎者姆摩爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9923, 'zhTW', '救命!', '救命!他們要吃了我!我剛剛才知道!$B$B找到鑰匙，我知道它一定在某個巨魔身上。$B$B如果你可以讓我離開這裡，我父親會重重的酬謝你!他是泰拉的領導者，阿爾克隆。', '找到石拳鑰匙並釋放柯爾奇。成功後和泰拉的阿爾克隆談談。', '', '去納格蘭找塔拉的阿雷克隆。', '營救考爾奇', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9924, 'zhTW', '柯爾奇又不見了!', '<阿爾克隆嘆氣。>$B$B這真是尷尬。你記得我的孩子，柯爾奇嗎?你不久前將他從燃燒之劍氏族廢墟救出來。嗯，他的好奇心又讓他再次陷入困境了。他告訴我他要去幫哞哞爾「叔叔」調查石拳威脅，就跑去北邊哈剌尼盆地的巨魔土丘了。$B$B你覺得你能找到他嗎?我會永遠感激的。', '泰拉的阿爾克隆要你找到並且釋放柯爾奇。', '', '去納格蘭找塔拉的阿雷克隆。', '再次營救考爾奇', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9925 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9925, 'zhTW', '防禦之事', '吉札選擇將我們的運作基地建在離歐夏剛最近的地方，完全不在意我們組員的安全。為什麼?因為他要在這裡設立商店，而不是在南方的山上，這樣才能提升百分之十的生產力。$B$B不要擔心離我們十英尺遠的瘋狂虛無再生者。那是安全人員的問題，不是吉札的。$B$B幫我殺一些虛無再生者，我就付你我們防禦經費的十分之一。別太開心，經費不多。', '納格蘭埃瑞斯碼頭的瑟利德要求你殺死沃舒古附近的8個空靈爪牙。', '', '去納格蘭找埃瑞斯碼頭的瑟利德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9926, 'zhTW', '標誌暗影議會/戰槌任務支線', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9927, 'zhTW', '殘忍的狡猾', '<傳授者給你一堆旗幟。>$B$B這些是我最近取得的戰槌巨魔旗幟。$B$B我要你前往南方的吉爾索洛堡壘，殺死所有你能找到的吉爾索洛垃圾。將戰槌巨魔旗幟插在每個陣亡的吉爾索洛士兵心臟上。等你完成這個任務和與這個計劃相關的其他任務之後再來找我。', '轉至基爾索羅堡壘，將10面戰槌食人魔軍旗插在基爾索羅成員的屍體上，然後返回納格蘭火刃廢墟向蘭特瑞索·火刃覆命。$B$B將沒有用完的戰槌食人魔軍旗還給蘭特瑞索。', '', '去納格蘭找火刃廢墟的蘭特瑞索·火刃。', '放置戰槌食人魔軍旗', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9928, 'zhTW', '欺騙的軍備', '如果我的計畫可行，你就得去從吉爾索洛堡壘裡偷取吉爾索洛裝備。$B$B搜索堡壘內的吉爾索洛裝備箱。把所有你找到的東西都帶來給我。$B$B吉爾索洛堡壘就在南方，稍偏燃燒之劍氏族廢墟的西邊。', '納格蘭火刃廢墟的蘭特瑞索·火刃要你收集10份基爾索羅軍備。', '', '去納格蘭找火刃廢墟的蘭特瑞索·火刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9929 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9929, 'zhTW', '失蹤的商人', '你剛剛來到這裡不久，我想你還不認識Dugar吧，認識嗎？他是一個能與撒塔斯城中各派都有聯絡的商人。$B$B別問他是怎麼做到的，總之他確實能夠賣給他們一些連我們的軍需官都無法提供的東西。$B$B他三天前離開沙塔斯，可到現在也沒有回來。他通常全程往返也用不了三天的。要是你也打算進入森林的話，可以幫我們找找他嗎？', '沿著通往沙塔斯的道路向西北方前進，尋找有關Dugar的一切線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9930, 'zhTW', '失蹤的商人', '你剛剛來到這裡不久，我想你還不認識Deirom吧，認識嗎？他是一個能與撒塔斯城中各派都有聯絡的商人。$B$B別問他是怎麼做到的，總之他確實能夠賣給他們一些連我們的軍需官都無法提供的東西。$B$B他三天前離開沙塔斯，可到現在也沒有回來。他通常全程往返也用不了三天的。要是你也打算進入森林的話，可以幫我們找找他嗎，有任何訊息就和僱傭兵團長Thander說吧。', '沿著通往沙塔斯的道路向西北方前進，尋找有關Deirom的一切線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9931, 'zhTW', '回報', '現在你一定要將戰爭的種子種在戰槌那個肥胖，無用的腦袋裡。到西北邊的山脈附近，你會找到獰笑骷髏氏族廢墟。$B$B<傳授者指向你帶給他的那箱裝備。>$B$B你認得這些旗幟嗎?它們是吉爾索洛旗幟。我要你帶一堆吉爾索洛旗幟去插在戰槌巨魔的屍體上。記住，你可以在西北邊找到那些巨魔。', '納格蘭火刃廢墟的蘭特瑞索·火刃要你殺入嘲顱廢墟，將10面基爾索羅軍旗插在戰槌食人魔的屍體上。$B$B將沒有用完的基爾索羅軍旗還給蘭特瑞索。', '', '去納格蘭找火刃廢墟的蘭特瑞索·火刃。', '放置基爾索羅軍旗', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9932, 'zhTW', '證據的屍體', '你在吉爾索洛堡壘的橫衝直撞讓我們有了特別的機會。我們有足夠的屍體讓它看起來像是大戰過後的模樣。$B$B前往獰笑骷髏氏族廢墟尋找獰笑骷髏庭院。庭園中應該會有一座燃燒中的火堆。確定該區域安全後再使用這個毯子發送煙霧訊號。當我的巨魔看見煙霧，他們會溜進去將吉爾索洛被殺死的屍體佈置好。$B$B那應該會是最後一戰了!', '納葛蘭，燃燒之劍氏族廢墟的『劍刃』蘭崔索要你去獰笑骷髏庭院，在燃燒的戰槌柴堆使用潮濕的羊毛毯來通知他的巨魔。', '', '去納格蘭找火刃廢墟的蘭特瑞索·火刃。', '放置基爾索羅屍體', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9933 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9933, 'zhTW', '給泰拉的訊息', '<傳授者指向一個沒有標記的木箱。>$B$B拿著。這是我給你人民的一點心意。你獨自拯救了我的氏族不被滅絕。$B$B你可以告訴你的領導者，火刃的傳授者和他的石拳巨魔接受這個和平的禮物。$B$B<傳授者鞠躬。>', '將火刃和平禮物帶給泰拉的阿爾克隆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9934 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9934, 'zhTW', '給卡拉達爾的訊息', '<傳授者指向一個沒有標記的木箱。>$B$B拿著。這是我給你人民的一點心意。你獨自拯救了我的氏族不被滅絕。$B$B你可以告訴你的領導者，火刃的傳授者和他的石拳巨魔接受這個和平的禮物。$B$B<傳授者鞠躬。>', '將火刃和平禮物帶給卡拉達爾的卡爾洛斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9935 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9935, 'zhTW', '懸賞:『老巫婆』吉絲達', '懸賞:死活不拘$B$B吉爾索洛的『老巫婆』吉絲達和她的僕人犯下謀殺、禁忌儀式、與燃燒軍團為伍、綁架和搶劫。$B$B據說他們聚集在納葛蘭東南方的吉爾索洛堡壘，靠近泰洛卡的邊界。$B$B讓吉絲達受到制裁的人就可以獲得卡拉達爾的守望者波洛克發放的大批黃金獎勵。', '殺死巫婆吉塞爾達以及任意10名基爾索羅成員，完成任務後向加拉達爾的監護者布羅克復命。', '', '去納格蘭找加拉達爾的監護者布羅克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9936 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9936, 'zhTW', '懸賞:『老巫婆』吉絲達', '懸賞:死活不拘$B$B吉爾索洛的『老巫婆』吉絲達和她的僕人犯下謀殺、禁忌儀式、與燃燒軍團為伍、綁架和搶劫。$B$B據說他們聚集在納葛蘭東南方的吉爾索洛堡壘，靠近泰洛卡的邊界。$B$B讓吉絲達受到制裁的人就可以獲得泰拉的守望者莫布夫·吉爾發放的大批黃金獎勵。', '殺死巫婆吉塞爾達以及任意10名基爾索羅成員，完成任務後返回塔拉向監護者莫布吉爾覆命。', '', '去納格蘭找塔拉的監護者莫布吉爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9937 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9937, 'zhTW', '懸賞:『飢餓者』唐恩', '你解決掉納葛蘭兩個最大的威脅，$n。你準備好拿下靈魂原野的天譴軍團了嗎?$B$B『飢餓者』唐恩在歐夏剛區域作威作福，大量毀滅擋他路的人。到現在為止，還沒有人能除掉納葛蘭這個兇猛的古羅。召集你的盟友前往西邊的靈魂原野，就在靠近歐夏剛的地方，找到唐恩。殺了他，我會給你和這任務同樣困難度的獎勵。', '殺死『飢餓者』唐恩。完成任務後回去找守望者波洛克。', '', '去納格蘭找加拉達爾的監護者布羅克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9938 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9938, 'zhTW', '懸賞:『飢餓者』唐恩', '你解決掉納葛蘭兩個最大的威脅，$n。你準備好拿下靈魂原野的天譴軍團了嗎?$B$B『飢餓者』唐恩在歐夏剛區域作威作福，大量毀滅擋他路的人。到現在為止，還沒有人能除掉納葛蘭這個兇猛的古羅。召集你的盟友前往西邊的靈魂原野，找到唐恩。殺了他，我會給你和這任務同樣困難度的獎勵。', '殺死『飢餓者』唐恩。完成任務後回去找守望者莫布夫·吉爾。', '', '去納格蘭找塔拉的監護者莫布吉爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9939 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9939, 'zhTW', '懸賞:『諫言者』索爾波', '懸賞:死活不拘$B$B『諫言者』索爾波，因為許多次對卡拉達爾計畫性的攻擊。索爾波和他的搶奪者與薩滿殺了無數的破碎者。如果索爾波有武裝的話，那是相當危險又殘忍的。$B$B索爾波住在納葛蘭北邊山脈的獰笑骷髏氏族廢墟。$B$B殺死或俘虜『諫言者』索爾波的獎勵將由卡拉達爾的守望者波洛克分發。', '殺死顧問佐爾布、5個戰槌薩滿祭司和5個戰槌劫掠者，完成任務後向監護者布羅克復命。', '', '去納格蘭找加拉達爾的監護者布羅克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9940 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9940, 'zhTW', '懸賞:『諫言者』索爾波', '懸賞:死活不拘$B$B『諫言者』索爾波，因為多次對泰拉計畫性的攻擊而被通緝。索爾波和他的搶奪者與薩滿殺了無數的破碎者。索爾波被認為是有武裝、危險又殘忍的。$B$B索爾波住在納葛蘭北邊山脈的獰笑骷髏廢墟。$B$B殺死或俘虜『諫言者』索爾波的獎勵將由泰拉的守望者莫布夫·吉爾分發。', '殺死顧問佐爾布、5個戰槌薩滿祭司和5個戰槌劫掠者，完成任務後向塔拉的監護者莫布吉爾覆命。', '', '去納格蘭找塔拉的監護者莫布吉爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9941 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9941, 'zhTW', '追蹤罪犯', '阿拉卡的足跡，伴隨著一對淺淺的車轍，走向路的北邊。看來阿拉卡從作戰地點拖走了什麼，或許朝著附近的安身之處去。$B$B雖然壞掉的馬車顯示了打鬥的痕跡，但還是沒有提供什麼迪羅姆的下落。跟隨阿拉卡足跡往北，繼續尋找商人。如果他被活捉，那或許還有機會拯救他。', '到壞掉的馬車北方，持續在阿拉卡聚集地搜尋迪羅姆的下落。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9942 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9942, 'zhTW', '追蹤罪犯', '阿拉卡的足跡，伴隨著一對淺淺的車轍，走向路的北邊。看來阿拉卡從作戰地點拖走了什麼，或許朝著附近的安身之處去。$B$B雖然壞掉的馬車顯示了打鬥的痕跡，但還是沒有提供什麼杜葛爾的下落。跟隨阿拉卡足跡往北，繼續尋找商人。如果他被活捉，那或許還有機會拯救他。', '到壞掉的馬車北方，繼續在阿拉卡聚集地搜尋杜葛爾的下落。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9943, 'zhTW', '回到薩德爾那裡', '迪羅姆的貨物不像是被損壞甚至是被開過。他們明顯地對貨物有興趣，但看來他們的犯人更重要一點。阿拉卡攻擊和綁架迪羅姆的意圖仍不清楚，但商人絕對沒有被囚禁在這裡。$B$B沒有未來的線索讓你繼續搜尋，你決定是時候向薩德爾報告你的發現了。', '將你的發現回報給奧蕾莉亞要塞的薩德爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9944 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9944, 'zhTW', '失蹤的瑪格哈利隊伍', '祖母說我們一定要堅持下去為我們的人民效勞。她說我們一定要做卡爾洛斯的典範 - 讓他們知道生命會繼續下去。$B$B我這裡有這麼多事要做，尤其是祖母又生病了。你願意幫助瑪格哈的一個監護員嗎?$B$B幾天前我們派了一群葬禮隊伍到先祖之地而他們尚未返回。你願意去找他們嗎?他們走上卡拉達爾外西邊的路。沿著走，避開哈剌。', '尋找失蹤的瑪格哈利隊伍。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9945 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9945, 'zhTW', '戰槌之戰', '我們被戰槌突襲的時候正在往先祖之地的路上。他們從四面八方逼近，殺死了好幾排守衛和很多其他的人。他們甚至褻瀆貨車裡長者的遺物。$B$B為了什麼?他們要這樣羞辱我們並宣示他們的力量。就連石拳都不會這樣做。$B$B我是個崇高的獸人，$n，但就連我也有底限的。找到西北邊戰槌山丘的攻擊者並殺光他們!', '納格蘭瑪格漢車隊的長者尤爾雷要求你殺死8個戰槌蠻兵和8個戰槌術士。', '', '去納格蘭找瑪格漢車隊的長者安格雷茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9946 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9946, 'zhTW', '『掠取者』喬沃', '你有看過巨魔國王嗎，$r?很少人看過還能活著訴說這個故事的。不幸的是，這就是我們目前所面臨的問題。$B$B這些野蠻人的領導者就是一個叫做喬沃的巨魔。傳說喬沃就是那個逼迫古羅離開洞穴的巨魔。喬沃便自己稱王，消滅效命於古羅的巨魔氏族。因此，戰槌產生了。$B$B到戰槌洞穴深處找到喬沃。殺了他並把他的頭顱帶來給我。', '納葛蘭，瑪格哈利隊伍的長老優兒利要你去殺死『掠取者』喬沃並取得喬沃的頭顱。', '', '去納格蘭找瑪格漢車隊的長者安格雷茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9947, 'zhTW', '回到瑞克格那裡拉', '杜葛爾的貨物不像是被損壞甚至是被開過。他們明顯地對貨物有興趣，但看來他們的犯人更重要一點。阿拉卡攻擊和綁架杜葛爾的意圖仍不清楚，但商人絕對沒有被囚禁在這裡。$B$B沒有未來的線索讓你繼續搜尋，你決定是時候向瑞克格報告你的發現了。', '將你的發現回報給碎石堡的瑞克格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9948 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9948, 'zhTW', '找到生還者', '如果我知道任何巨魔的事情，那就是他們喜歡新鮮的食物。這代表被他們捉去的瑪格哈在成為食物之前都會是活著的。我知道這是個噁心的想法，但也是對我們有利的想法。$B$B前往戰槌山丘尋找瑪格哈囚犯。如果你找到犯人，那麼你就會在戰槌巨魔附近找到他們籠子的鑰匙。$B$B殺了巨魔得到鑰匙並釋放犯人。', '納格蘭瑪格漢車隊的長者安格雷茲要求你去釋放5個瑪格漢俘虜。', '', '去納格蘭找瑪格漢車隊的長者安格雷茲。', '營救瑪格漢俘虜', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9949 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9949, 'zhTW', '鳥眼視線', '沒有未來的資訊，我們現在處於一個艱難的狀況。我不會放棄尋找並拯救迪羅姆。他被綁架不是意外，$N。$B$B阿拉卡在動鬼腦筋，但他們究竟在計劃什麼呢？$B$B法師哨塔裡的安達爾歐知道他們一些特殊的魔法。如果有正確的工具，他可以湊出一些新資訊給我們。他需要白骨荒野北邊各個阿拉卡城鎮的“眼睛”水晶 - 就在迷霧斯奇司，迷霧瑞斯克，和迷霧辛諾那裡。', '將迷霧斯奇司之眼，迷霧辛諾之眼，和迷霧瑞斯克之眼交給奧蕾莉亞要塞的安達爾歐。', '', '去找泰羅卡森林的安達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9950 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9950, 'zhTW', '鳥眼視線', '沒有未來的資訊，我們現在處於一個艱難的狀況。我不會放棄尋找並拯救杜葛爾。他被綁架不是意外，$N。$B$B阿拉卡在動鬼腦筋，但他們究竟在計劃什麼呢？$B$B庫爾卡拓克術士知道他們一些特殊的魔法。如果有正確的工具，他可以湊出一些新資訊給我們。他需要白骨荒野北邊各個阿拉卡城鎮的“眼睛”水晶 - 就在迷霧斯奇司，迷霧瑞斯克，和迷霧辛諾那裡。', '將迷霧斯奇司之眼，迷霧辛諾之眼，和迷霧瑞斯克之眼交給碎石堡的庫爾卡拓克。', '', '去找泰羅卡森林的庫加托克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9951, 'zhTW', '它在看著你!', '快，躲起來!奈伏薩拉爾的眼睛正注視著你……注視著我們所有人!$B$B我不敢去哨塔頂端和它交談，但你……你看起來像是知道該說什麼話的樣子。小心點，它不是個笑話也不會讓蠢蛋好過的。$B$B如果你可以的話，說服它下來喝杯茶。但是，不管你用什麼方法，叫它不要再盯著我看!', '殺了奈伏薩拉爾再回到泰洛卡森林找塞納里奧灌木林的守望者崔洛斯。', '', '去泰羅卡森林找塞納里奧樹林的監護者忒洛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9952 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9952, 'zhTW', '勘察員波莫羅', '所以安達爾歐確定迪羅姆被囚禁在迷霧撒拉斯？那裡是我們所知道最大的阿拉卡聚集地。$B$B迷霧撒拉斯在森林的南方遠處，和白骨荒野的東部邊界很近。不幸的是，我沒有太多的瞭解，不過我們有個探險者協會成員駐紮在那裡，他或許能幫你。勘察員波莫羅的營地就在迷霧撒拉斯西南方土地的邊緣。和他談談再來對付阿拉卡。', '找到並和勘察員波莫羅談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9953 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9953, 'zhTW', '監視者諾達克', '所以庫爾卡拓克確定杜葛爾被囚禁在迷霧撒拉斯？那裡是我們所知道最大的阿拉卡聚集地。$B$B迷霧撒拉斯在森林的南方遠處，和白骨荒野的東部邊界很近。不幸的是，我對那裡並不太瞭解，不過我們有個斥候駐紮在那裡，他或許能幫你。監視者諾達克的營地就在迷霧撒拉斯西南方土地的邊緣。和他談談再來對付阿拉卡。', '找到並和監視者諾達克談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9954 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9954, 'zhTW', '柯爾奇的贖金', '<阿爾克隆給你一封佈滿塵垢的信。>$B$B我剛收到這封信。是一個叫做戰槌的巨魔氏族寄來的，他們統治納葛蘭西北方的土地。上面說他們抓走了柯爾奇，如果我們不合作，他們就會把他給吃了。不可否認的，柯爾奇是個智障，但他還是我的同胞。你會救他嗎，$n?$B$B我猜他被鎖在戰槌山丘上的一個籠子裡。那就是你要去的第一站。', '阿爾克隆要你去戰槌山丘找柯爾奇。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9955 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9955, 'zhTW', '『掠取者』喬沃', '他們叫他『掠取者』喬沃，$n。就是這個巨魔強行攻佔以前統治他們的古羅。你最好相信他是很強大的!$B$B大廚說喬沃住在一個大籠子裡 - 不管那是在什麼地方……拿到鑰匙把我救出去!如果我們可以度過這個難關我的父親絕對會給你一份厚禮!只要我自由了，就去找他。', '柯爾奇要你拿到喬沃的鑰匙，這樣你就可以將他從牢籠中釋放。等你完成了這個任務就回到泰拉找阿爾克隆。', '', '去納格蘭找塔拉的阿雷克隆。', '營救考爾奇', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9956 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9956, 'zhTW', '被破壞的貨車', '我是運送補給到贊格沼澤奧雷伯爾港的車隊一員。當我們靠近沼澤邊界時，一群邪惡的戰槌巨魔撲上來。他們殺死了其他人，把我和所有的補給當成囚犯。$B$B幸好他們忘了在我的籠子上放置栓子。我趁他們睡著的時候逃了出來。$B$B雖然對我的同伴們而言已經太遲了，但我們真的可以利用他們偷走的補給。戰槌山丘就在納葛蘭西北邊的山間。', '收集10個塔拉補給箱，把它們交給塔拉的女獵手琪瑪。', '', '去納格蘭找塔拉的女獵手琪瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9957, 'zhTW', '塞納里奧灌木林發生了什麼事?', '我們好一陣子沒聽到泰洛卡森林裡塞納里奧灌木林的德魯伊消息了。$B$B$n，我要你去那裡看看發生什麼事了。有幾個方法可以到那裡，但最快的方法是沿著路往南走，當你進入森林後就選擇從撒塔斯城的岔路往東走。', '到泰洛卡森林去和塞納里奧灌木林的一個德魯伊談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9958 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9958, 'zhTW', '偵察防禦', '我在這裡的時候和阿拉卡有一些互動，他們沒有一個人是友善的。他們看起來非常具領域性，但我想我們也是一樣，對嗎？就連先祖們都沒有任何和鳥人來往的紀錄。$B$B阿拉卡擁有一種原始的魔法，那是艾澤拉斯上的我們所未知的力量，被用來編織迷霧撒拉斯的防禦網。在和他們對抗前，我們最好先偵察他們的防禦才知道對手的斤兩。', '前進迷霧撒拉斯觀察城鎮的防禦。', '', '去找泰羅卡森林的勘測員巴莫拉爾。', 'Investigate Veil Shalas Defenses', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9959, 'zhTW', '偵察防禦', '我在這裡的時候和阿拉卡有一些互動，他們沒有一個人是友善的。他們看起來非常具領域性，但我想我們也是一樣，對嗎？就連先祖們都沒有任何和鳥人來往的紀錄。$B$B阿拉卡擁有一種原始的魔法，那是我們的先知所未知的力量，被用來編織迷霧撒拉斯的防禦網。在和他們對抗前，我們最好先偵察他們的防禦才知道對手的斤兩。', '前進迷霧撒拉斯瞭解防禦營地的魔法。', '', '去泰羅卡森林找鴉羽山的斥候努達克。', 'Investigate Veil Shalas Defenses', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9960, 'zhTW', '塞納里奧灌木林發生了什麼事?', '嘿，$c。我們很久沒聽到來自塞納里奧灌木林的德魯伊的消息了。$B$B我要你去那裡看看發生了什麼事。通過森林往西北方走就會找到了。', '到泰洛卡森林去和塞納里奧灌木林的一個德魯伊談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9961, 'zhTW', '塞納里奧灌木林發生了什麼事?', '$c，我有個緊急任務要交給你。我們好一陣子沒聽到塞納里奧灌木林的德魯伊消息了。這和我們平常至少每幾天就會聽到他們的消息比起來很不尋常。$B$B我要你去那裡確定他們沒事。通過森林往西北方走就會找到灌木林了。', '到泰洛卡森林去和塞納里奧灌木林的一個德魯伊談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9962, 'zhTW', '血色競技場:斷趾', '你準備好進行第一場戰鬥了嗎?如果是的話就讓我知道比賽可以開始了。你要做的就是去血色競技場等待對手到來。$B$B這是場對抗斷趾的比賽，他是個兇猛的裂蹄。$B$B祝你好運!我希望你會帶著朋友一起。$B$B還有記住，當你或你的對手陣亡倒地時比賽就結束了。', '擊敗斷趾。擊敗他們之後跟『食人妖僕從』烏丁領取獎賞。', '擊敗斷蹄', '去找納格蘭的巨魔僕從伍迪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9963, 'zhTW', '向源頭尋找幫助', '你遇到的結界的確是強大的魔法。阿拉卡使用的技巧是遠遠超出我們所能理解的，我們只能希望藉他們的幫忙找到一個抗衡物。$B$B我知道你在想什麼。敵人怎麼會幫我們征服他們的防禦？答案是他們當然不會。你有聽過瘋狂老阿拉卡聖人，可可瑞克的故事嗎？他們說他就躲在白骨荒野西邊的迷霧里斯克裡，等待失落的世代重返。', '找到迷霧里斯克裡的可可瑞克並和他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9964, 'zhTW', '向源頭尋找幫助', '你遇到的結界的確是強大的魔法。阿拉卡使用的技巧是遠遠超出我們所能理解的，我們只能希望藉他們的幫忙找到一個抗衡物。$B$B我知道你在想什麼。敵人怎麼會幫我們征服他們的防禦？答案是他們當然不會。你有聽過瘋狂老阿拉卡聖人，可可瑞克的故事嗎？他們說他就躲在白骨荒野西邊的迷霧里斯克裡，等待失落的世代重返。', '找到迷霧里斯克裡的可可瑞克並和他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9965, 'zhTW', '良心的約定', '現在，我很有誠意地建議你與我做一筆小小的交易：只要你願意展示出為我解決一個小小問題的好意來，我就願意幫助你營救你的同志。$B$B巨魔是我們一族長久以來不共戴天的仇敵，最近，他們又從納格蘭的大草原遷徙回了森林中。$B$B遷徙回來的巨魔中有一個很特別，他叫穆格苟克，很有冒險精神，可惜不怎麼聰明。他和他的朋友一直血環廢墟那邊，給我們製造著麻煩，想要激怒我們。', '把穆格苟克的頭顱交給迷霧里斯克的可可瑞克。', '', '去泰羅卡森林找雷希鴉巢的庫庫雷克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9966, 'zhTW', '良心的約定', '現在，我很有誠意地建議你與我做一筆小小的交易：只要你願意展示出為我解決一個小小問題的好意來，我就願意幫助你營救你的同志。$B$B巨魔是我們一族長久以來不共戴天的仇敵，最近，他們又從納格蘭的大草原遷徙回了森林中。$B$B遷徙回來的巨魔中有一個很特別，他叫穆格苟克，很有冒險精神，可惜不怎麼聰明。他和他的朋友一直血環廢墟那邊，給我們製造著麻煩，想要激怒我們。', '把穆格苟克的頭顱交給迷霧里斯克的可可瑞克。', '', '去泰羅卡森林找雷希鴉巢的庫庫雷克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9967, 'zhTW', '血色競技場:憂鬱兄弟黨', '下一場賽事是對付雙人組 - 正確的說是兩個兄弟。他們自稱為「憂鬱兄弟」。$B$B現在退縮還不算太晚，$n。我能夠理解。$B$B但如果你準備要行動了，就踏進血色競技場裡等待黑暗之血雙子到來。$B$B最後站著的人就是贏家!', '擊敗自稱憂鬱兄弟的黑暗之血雙子。擊敗他們之後跟食人妖僕人伍德林領取獎賞。', '擊敗藍色兄弟', '去找納格蘭的巨魔僕從伍迪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9968, 'zhTW', '奇怪的能量', '某種奇怪的力量改變了灌木林裡的泰洛飛蛾。$B$B曾經這裡有各種的生命，現在只剩下泰洛飛蛾。以前這些飛蛾生性溫馴，現在的牠們處於一種被激怒的狀態，會毫不猶豫的在你接近時攻擊你。$B$B我需要比對兇惡和正常的飛蛾。幫我各收集一些這兩種樣本。你可以在南方和北方找到未受影響的飛蛾。$B$B我確定這和所有德魯伊被殺死的事情有關。', '收集4個泰洛飛蛾樣本和4個兇惡的泰洛飛蛾樣本。再回到泰洛卡森林找塞納里奧灌木林外的大地束縛者塔伏格蘭。', '', '去泰羅卡森林找塞納里奧樹林的縛地者塔弗格倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9969, 'zhTW', '最後的試劑', '我能製造出一種可以抑制住沙拉斯鴉巢那裡結界法術的物品。但我得提醒你，$N，這個法術僅僅是為了讓你救出被關押在那裡的朋友而用的。我絕對不會允許你任意傷害我的同胞。$B$B用於製造這個護身符的材料我這裡基本都有了，但仍有一些其它材料我需要你幫我收集回來。我需要一些扭曲獵人精華，還有一把泰羅卡灌木，這些都可以在鴉巢附近的地方找到。', '將5份扭曲獵者精華和30顆泰羅卡灌木交給迷霧里斯克的可可瑞克。', '', '去泰羅卡森林找雷希鴉巢的庫庫雷克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9970, 'zhTW', '血色競技場:『碎裂領主』洛克達', '這場仗會很痛苦，$n。你有什麼朋友夠勇敢可以幫你嗎?巨魔設法從劍刃山脈弄到一個叫做洛克達的巨人!相信我，你需要朋友，他看起來堅不可摧!他就像石頭一樣堅硬 - 一點也不誇張!$B$B如果你還想和他挑戰，踏進血色競技場他就會來了。', '擊敗『碎裂領主』洛克達。獲勝之後跟食人妖僕人伍德林領取獎賞。', '擊敗裂石之王洛卡達爾', '去找納格蘭的巨魔僕從伍迪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9971, 'zhTW', '樹叢裡的線索', '我不知道是什麼殺了這裡所有的德魯伊。我去南方的白骨荒野做了幾天的調查。$B$B拜託你，一定要幫我解開這恐怖悲劇後的秘密。進入灌木林裡尋找可能揭發真相的線索。我之前曾短暫地到過那裏，我可以發誓我看到了一個破碎者屍體及緊鄰著屍體旁的一個怪異物體$B$B不用擔心崔洛斯 - 他應該已經被發生的事搞瘋了，我想他應該不會造成傷害。', '調查破碎的屍體旁邊的奇怪的物品來判定塞納里奧灌木林發生過什麼事。再回到泰洛卡森林外找大地束縛者塔伏格蘭。', '', '去泰羅卡森林找塞納里奧樹林的縛地者塔弗格倫。', '檢查奇怪的物體', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9972 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9972, 'zhTW', '血色競技場:史卡拉克斯', '你要在那裡把他們都殺光，孩子!他們下場比賽有個槍手。他們說他是虛無領主還是什麼的……他們不會想讓你對抗他們的勇士。你有聽到那個蹩腳選手莫古對你狂吠嗎?賭金已經累積到最高限度了!$B$B進到那個圈圈裡把這個人迅速解決掉!', '擊敗史卡拉克斯。獲勝之後跟食人妖僕人伍德林領取獎賞。', '擊敗瑟克拉加斯', '去找納格蘭的巨魔僕從伍迪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9973 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9973, 'zhTW', '血色競技場:戰槌勇士', '他們必須將勇士從劍刃戰士地窖運送進來。他訓練山嶺巨人 - 一次三個。$B$B如果你贏了，你就成為新的勇士。你覺得你的勝算有多少，小鬼?你敢試一試嗎?只要一句話我就賭你贏。$B$B現在就進去贏吧!', '擊敗戰槌勇士。獲勝之後跟食人妖僕人伍德林領取獎賞。', '擊敗戰槌勇士', '去找納格蘭的巨魔僕從伍迪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9974 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9974, 'zhTW', '最後的試劑', '我能製造出一種可以抑制住沙拉斯鴉巢那裡結界法術的物品。但我得提醒你，$N，這個法術僅僅是為了讓你救出被關押在那裡的朋友而用的。我絕對不會允許你任意傷害我的同胞。$B$B用於製造這個護身符的材料我這裡基本都有了，但仍有一些其它材料我需要你幫我收集回來。我需要一些扭曲獵人精華，還有一把泰羅卡灌木，這些都可以在鴉巢附近的地方找到。', '將5份扭曲獵者精華和30顆泰羅卡灌木交給迷霧里斯克的可可瑞克。', '', '去泰羅卡森林找雷希鴉巢的庫庫雷克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9975 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9975, 'zhTW', '原始魔法', '我已經將法術灌注到了這個護符中。而你所要做的，就是找到沙拉斯鴉巢邊界上的守護圖騰，然後釋放其中的力量。這樣一來，結界就會被撕裂。$B$B<你發現這個護符上所雕刻著的人物形象並不是非常像一個鴉人。>$B$B啊，我們的族人並非在最初就是這個樣子的。我們曾經也曾是擁有華麗外表的生物，但我們……我們一再聽信讒言，做出了錯誤的抉擇。最終，我們未能完成那個神聖的使命，也使我們失去了美麗的外表，強大的力量，甚至是……我們的生命。不要重複我們所犯過的錯誤，$N。', '在通向沙拉斯鴉巢的道路周圍的圖騰附近使用庫庫雷克的護符，然後與勘測員巴莫拉爾談一談。', '', '去找泰羅卡森林的勘測員巴莫拉爾。', '使用庫庫雷克的護符', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9976, 'zhTW', '原始魔法', '我已經將法術灌注到了這個護符中。而你所要做的，就是找到沙拉斯鴉巢邊界上的守護圖騰，然後釋放其中的力量。這樣一來，結界就會被撕裂。$B$B<你發現這個護符上所雕刻著的人物形象並不是非常像一個鴉人。>$B$B啊，我們的族人並非在最初就是這個樣子的。我們曾經也曾是擁有華麗外表的生物，但我們……我們一再聽信讒言，做出了錯誤的抉擇。最終，我們未能完成那個神聖的使命，也使我們失去了美麗的外表，強大的力量，甚至是……我們的生命。不要重複我們所犯過的錯誤，$N。', '在通向沙拉斯鴉巢的道路周圍的圖騰附近使用庫庫雷克的護符，然後與斥候努達克談一談。', '', '去泰羅卡森林找鴉羽山的斥候努達克。', '使用庫庫雷克的護符', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9977 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9977, 'zhTW', '血色競技場:最後的挑戰', '<葛爾薩克正數著他堆積如山的金幣。>$B$B你為我賺了很多錢，小鬼。如果你可以擊敗莫古，我保證會讓你值回票價。你在血色競技場所受的苦全都會有代價的。$B$B現在快前往那裡讓這些巨魔看看你的厲害!', '擊敗戰槌的英雄，莫古。獲勝之後跟食人妖僕人伍德林領取獎賞。', '擊敗戰槌英雄穆戈爾', '去找納格蘭的巨魔僕從伍迪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9978 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9978, 'zhTW', '用盡所有必須的手段', '我不知道是什麼造成如此，不過我清楚要如何找出更多的線索。$B$B安普爾是一位破碎者商人，專門運送各種商品及資訊。要是你可以說服他開口，我確信你可以聽到些有趣的事。$B$B他都在杜瑞跟撤塔斯城之間來回。不過，當心點 - 他可是帶了個保鑣隨行。', '找到並說服安普爾，使他告訴你所知道的事。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9979 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9979, 'zhTW', '風之貿易者拉斯蕊', '我奉命到撒塔斯城向一個伊斯利取貨並運送幾箱貨物。$B$B我上次看到他的時候，他在陰鬱城的世界的盡頭小酒館外站著。他叫拉斯蕊，我只知道這樣而已!$B$B想知道更多訊息，請去和他談話!', '到撒塔斯的陰鬱城和世界的盡頭小酒館的拉斯蕊談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9980 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9980, 'zhTW', '拯救迪羅姆！', '立刻進入沙拉斯鴉巢，$N！現在時間非常寶貴。如果阿拉卡發現你已經破除了他們的防禦體系，他們一定會換個地方關押迪羅姆的，甚至把他殺掉。$B$B如果可能的話，帶上一兩個朋友幫助你，闖入那裡面看起來確實很困難。那些鳥人對他們的囚犯看守得十分嚴密，絕不會允許他們輕易逃脫。如果你找到了迪羅姆，立刻消滅他身邊的守衛，帶他回到奧蕾莉亞要塞，並通知薩德爾。', '前往迷霧撒拉斯，殺了盧安卡，再釋放迪羅姆。完成任務後再向奧蕾莉亞要塞的戴娜·甘乃迪女士回報。', '', '去泰羅卡森林找奧蕾莉亞要塞的德娜·肯尼迪。', '', 'Free Deirom', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9981, 'zhTW', '拯救杜葛爾！', '立刻進入沙拉斯鴉巢，$N！現在時間非常寶貴。如果阿拉卡發現你已經破除了他們的防禦體系，他們一定會換個地方關押迪羅姆的，甚至把他殺掉。$B$B如果可能的話，帶上一兩個朋友幫助你，闖入那裡面看起來確實很困難。那些鳥人對他們的囚犯看守得十分嚴密，絕不會允許他們輕易逃脫。如果你找到了迪羅姆，立刻消滅他身邊的守衛，帶他回到碎石堡，並通知羅卡格。', '前往迷霧撒拉斯，殺了盧安卡，再釋放杜葛爾。完成任務後再向碎石堡的羅卡格回報。', '', '去找泰羅卡森林的羅卡格。', '', 'Free Dugar', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9982, 'zhTW', '他自稱奧翠司……', '上個禮拜有個人騎著一隻虛空龍來到城裡。他說自己叫奧翠司然後詢問我們幾個關於納葛蘭的問題。$B$B他聲稱他在追捕燃燒軍團。那種瘋狂的事竟然是他的工作。你能想像嗎?居然有人會自願獵捕惡魔?$B$B在他離開之前，他要我們讓鎮上想成為英雄的人知道他會待在西納葛蘭一陣子，如果他們想展現決心，就去找他。', '如果你想與燃燒軍團挑戰就到西納葛蘭去找『受難者』奧翠司。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9983, 'zhTW', '他自稱奧翠司……', '上個禮拜有個人騎著一隻虛空龍來到城裡。他說自己叫奧翠司然後詢問我們幾個關於納葛蘭的問題。$B$B他聲稱他在追捕燃燒軍團。那種瘋狂的事竟然是他的工作。你能想像嗎?居然有人會自願獵捕惡魔?$B$B在他離開之前，他要我們讓鎮上想成為英雄的人知道他會待在西納葛蘭一陣子，如果他們想展現決心，就去找他。', '如果你想與燃燒軍團挑戰就到西納葛蘭去找『受難者』奧翠司。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9984, 'zhTW', '隱秘之城', '儘管你無法辨認出卷軸上的奇怪筆跡，但還是可以從公文最後華麗的印章中看出，這份卷軸出自一位頗有地位的鴉人之手。盧埃加或許就是那個抓捕和監禁迪魯姆的鴉人，還負責審問他。不過，他看上去也是接到了另一個地位更高的鴉人之命令才負責這件事的。$B$B你突然想起山德曾說過，安達爾對鴉人研究頗多，或許他能讀懂卷軸中的內容。', '將盧埃加的命令交給泰羅卡森林中奧蕾莉亞要塞的安達爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9985, 'zhTW', '隱秘之城', '儘管你無法辨認出卷軸上的奇怪筆跡，但還是可以從公文最後華麗的印章中看出，這份卷軸出自一位頗有地位的鴉人之手。盧埃加或許就是那個抓捕和監禁杜加爾的鴉人，還負責審問他。不過，他看上去也是接到了另一個地位更高的鴉人之命令才負責這件事的。$B$B你突然想起羅卡格曾說過，庫加托克對鴉人研究頗多，或許他能讀懂卷軸中的內容。', '將盧埃加的命令交給泰羅卡森林中碎石堡的庫加托克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9986, 'zhTW', '阻礙阿拉卡', '我們要讓阿拉卡知道我們的人民不會白白讓他們攻擊。如果我們不阻止他們，路途對我們的商人、信差或士兵而言就不再安全。$B$B我的斥候已認出了各個主要阿拉卡營地的領導者。到迷霧瑞斯克，迷霧辛諾，和迷霧斯奇司找到阿斯卡斯、阿翼特和烏達克並殺了他們。', '殺死迷霧瑞斯克的阿斯卡斯、迷霧辛諾的阿翼特和迷霧斯奇司的烏達克再回到艾蘭里堡壘找薩德爾。', '', '去泰羅卡森林找奧蕾莉亞要塞的山德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9987 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9987, 'zhTW', '阻礙阿拉卡', '我們要讓阿拉卡知道我們的人民不會白白讓他們攻擊。如果我們不阻止他們，路途對我們的商人、信差或士兵而言就不再安全。$B$B我的斥候已認出了各個主要阿拉卡營地的領導者。到迷霧瑞斯克，迷霧辛諾，和迷霧斯奇司找到阿斯卡斯、阿翼特和烏達克並殺了他們。', '殺死迷霧瑞斯克的阿斯卡斯，迷霧辛諾的阿翼特，和迷霧斯奇司的烏達克再回到碎石堡找瑞克格。', '', '去泰羅卡森林找碎石堡的羅卡格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9988 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9988, 'zhTW', '公子哥的好朋友', '千萬不要被山德和他那些同夥給騙了。雖然這群傢伙看起來像是一群令人生畏的優秀士兵，其實在那華麗的外表下，他們只不過是一堆徹頭徹尾的廢物，一群公子哥兒而已！$B$B當然，這一點他們是絕對不會讓別人知道的。他們特別喜歡奢侈的氈製品和毛皮，還有各類最華美的羽毛。$B$B當然，當然，最令人嚮往的羽毛要數鴉人身上的那些，但是我的存貨越來越少了。如果你能幫我去找些羽毛回來，我會很樂意付一筆可觀的工\\r\\n錢給你。', '給奧蕾莉亞要塞的洛瑟蕾絲帶回30片鴉人的羽毛。', '', '去泰羅卡森林找奧蕾莉亞要塞的洛瑟蕾絲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9989 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9989, 'zhTW', '異類的靈魂', '記得當我第一次來到外域並傾聽這裡各種靈魂的聲音時，我對自己聽到的東西感到非常詫異。同時，我也留意到有些靈魂的聲音我竟然無法聆聽清楚。$B$B我嘗試過各種辦法，仍然接觸不到這些鴉人的靈魂。他們的魔法與我們的完全不同，但我還不能確定接觸他們的靈魂是否超出了我的能力範圍。$B$B總之，幫我找一些鴉人的羽毛回來吧，或許依靠這些他們身上的東西，我就能接觸到他們的靈魂。', '將30片鴉人的羽毛交給碎石堡的瑪魯卡茲。', '', '去泰羅卡森林找碎石堡的瑪魯卡茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9990 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9990, 'zhTW', '調查杜瑞', '你知道嗎，說到這，我還真的想起大概一個月前賣過幾箱奇怪又特殊的工程零件給安普爾。我不確定那是幹嘛用的，但我知道它們是要送到杜瑞去的。$B$B或許那裡還有一兩箱?', '找到密封的箱子再將它送到泰洛卡森林交給塞納里奧灌木林外的大地束縛者塔伏格蘭。', '', '去泰羅卡森林找塞納里奧樹林的縛地者塔弗格倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9991 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9991, 'zhTW', '調查土地', '要當我的眼線需要一點勤奮。尼斯蘭德瑪斯會帶你通過燃燒軍團營地，但你一定要將看見的所有東西記載下來。就算是你覺得最微小不重要的細節都可能對我們的目的很有助益。$B$B首先，我要你注意營地裡有什麼樣的建築物，構成營地的防禦是什麼。$B$B尼斯蘭德瑪斯會等你準備好，$n。不要害怕，他會保護你不受傷害的。', '坐好享受旅程。等調查完成後和奧翠司談談。', '偵查鑄魔營地', '去納格蘭找受難者奧圖裡斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9992 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9992, 'zhTW', '奧萊姆貝種子', '森林裡的樹真美對吧?我常常在想他們會不會生長在艾澤拉斯上。$B$B不過我很猶豫要不要運送幼苗回去。這是個顛簸的路途而且他們比一袋種子那樣的東西還要難傳送許多。種子都儲藏在堅硬的松果裡，那些松果在成熟後會從樹枝上掉落下來。$B$B如果你在旅途中看到這種松果，可以麻煩你帶一些種子回來給我嗎?', '收集30顆奧萊姆貝種子交給艾蘭里堡壘的羅斯勒斯。', '', '去泰羅卡森林找奧蕾莉亞要塞的洛瑟蕾絲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9993 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9993, 'zhTW', '奧萊姆貝種子油', '森林奧萊姆貝樹的油種子非常有價值。我想收集很多種子，粹取它們的油，再看看拿來做些什麼。$B$B想想看，那裡有整森林的樹，製造出一大堆被浪費掉的種子。不管它最後變成烹飪油，燈油，或武器用油，我就是不能讓它白白浪費!$B$B將你從奧萊姆貝松果收集到的種子帶來給我。它們散落各處。', '將30顆奧萊貝種子交給碎石堡的瑞克利亞。', '', '去泰羅卡森林找碎石堡的拉克妮亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9994 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9994, 'zhTW', '這些是什麼東西?', '我是不知道你覺得怎麼樣，不過我不知道那些東西是什麼。但我知道一件事 - 它們看起來很危險!$B$B$n，我覺得你該帶一盒零件回東南方的艾蘭里堡壘交給珍奈·星語。她或許會知道這些是什麼。', '將一箱零件運回泰洛卡森林交給艾蘭里堡壘的珍奈·星語。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9995 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9995, 'zhTW', '這些是什麼東西?', '我是不知道你覺得怎麼樣，不過我不知道那些東西是什麼。但我知道一件事 - 它們看起來很危險!$B$B$n，我覺得你該帶一盒零件回東南方的碎石堡交給吐奇。他或許會知道這些是什麼。', '將一箱零件運回泰洛卡森林交給碎石堡的吐奇。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9996 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9996, 'zhTW', '攻擊火翼崗哨', '我們知道火翼崗哨的血精靈為凱爾薩斯及伊利丹工作。而根據你的消息，很明顯的他們利用杜瑞的破碎者做為中間的走私者偷運一些可怕的武器。$B$B無論他們在那幹嘛，我們現在可以做得最有效的事就是減少他們的人數。$B$B必須解決掉這些火翼血精靈們!出發前往北方的火翼崗哨去解決他們。', '殺死10個火翼防衛者，10個火翼血守衛，10個火翼術士。再回到泰洛卡森林向艾蘭里哨站的莫瑞狄恩中尉回報。', '', '去泰羅卡森林找奧蕾莉亞崗哨的米利迪安中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9997, 'zhTW', '攻擊火翼崗哨', '我們知道火翼崗哨的血精靈為凱爾薩斯及伊利丹工作。而根據你的消息，很明顯的他們利用杜瑞的破碎者做為中間的走私者偷運一些可怕的武器。$B$B無論他們在那幹嘛，我們現在可以做得最有效的事就是減少他們的人數。$B$B必須解決掉這些火翼血精靈們!出發前往東北方的火翼崗哨去解決他們。', '殺死10個火翼防衛者，10個火翼血守衛，10個火翼術士。再回到泰洛卡森林向碎石營地的丘尼士官回報。', '', '去找泰羅卡森林碎石營地的卡烏尼中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9998, 'zhTW', '難搞的鄰居', '最近到達東邊廢墟的魔獄獸人不僅讓薩德爾很為難也很困擾。他們立刻開始建造防禦工事並修補建築物。$B$B他們沒日沒夜的趕工，$n。我派了最信賴的密探之一去盯著他們，但我們絕不能動作太慢。先對付他們的工人再到噬骨者廢墟北邊的艾蘭里哨站找瑟蘿莉雅·影篷。她會給你進一步的指示。', '殺死12個乖戾的苦工再向艾蘭里哨站的瑟蘿莉雅·影篷回報。', '', '去泰羅卡森林找奧蕾莉亞崗哨的塞洛莉婭·影衣。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 9999 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (9999, 'zhTW', '爭取時間', '只要傳送門還在，我們對煉冶場做的一切都不能長久。我們一定要想出一個辦法摧毀燃燒軍團建築。$B$B我需要時間設計一個攻擊計畫。如果你可以讓他們的工程師和技工無暇分心，那就會大大地減緩他們的進展，幫我爭取一點需要的時間。$B$B離監督者越遠越好，$n。他們是非常危險的生物。', '西納葛蘭的『受難者』奧翠司要你去殺死2個惡魔守衛領導者，3個莫阿格工程師和8個甘納格技工。', '', '去找納格蘭的受難者奧圖裡斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10000 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10000, 'zhTW', '不受歡迎的存在', '我們在索爾瑪的軍隊認為他們將魔獄獸人控制在地獄火堡壘區域裡，但最近剛到達東邊廢墟的人卻有不同的說法。$B$B我們不能讓他們在這裡立足。瑞克格派了巡影者凱德到廢墟去監視他們，但我們仍要做點什麼來阻止他們進入。$B$B前往廢墟，殺死他們的苦工，再到北邊的樹林裡找凱德。他會告訴你下一步該往哪裡走。', '殺死12個乖戾的苦工再向巡影者凱德回報。', '', '去找泰羅卡森林碎石營地的追蹤者凱德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10001, 'zhTW', '規劃大師', '所有的煉冶場都有一個規劃大師。規劃大師決定了一個煉冶場的構造以及每種構造如何建築。此外，這個資訊會保存在規劃師隨身攜帶的一套藍圖裡面。有了如此重要的資訊，我們可以說服我的一個朋友提供一些協助。$B$B找到莫阿格規劃大師並拿走他的藍圖。他就駐紮在煉冶場的後方。', '西納葛蘭的『受難者』奧翠司要你取得規劃大師的藍圖。', '', '去找納格蘭的受難者奧圖裡斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10002, 'zhTW', '火翼聯繫', '過去這幾天來，我觀察到一個血精靈女人來往魔獄獸人要塞並和魔獄獸人領導者交談。從她的肢體語言看起來，她很明顯的是在發布命令。但是為什麼?她是在傳達誰的命令?$B$B我的好奇心蓋過了我的判斷力，於是我在她離開魔獄獸人營地時尾隨她。她往北方走，回到火翼崗哨。我在到達血精靈的前哨周圍前停了下來。$B$B在她再次離開魔獄獸人營地前殺了她。', '找到並殺死麗莎艾歐·織火者，再回去找瑟蘿莉雅·影篷。', '', '去泰羅卡森林找奧蕾莉亞崗哨的塞洛莉婭·影衣。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10003 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10003, 'zhTW', '火翼聯繫', '過去這幾天來，我觀察到一個血精靈女人來往魔獄獸人要塞並和魔獄獸人領導者交談。從她的肢體語言看起來，她很明顯的是在發布命令。但是為什麼?她是在傳達誰的命令?$B$B我的好奇心蓋過了我的判斷力，於是我在她離開魔獄獸人營地時尾隨她。她往北方走，回到火翼崗哨。我在到達血精靈的前哨周圍前停了下來。$B$B在她再次離開魔獄獸人營地前殺了她。', '找到並殺死麗莎艾歐·織火者，再回去找巡影者凱德。', '', '去找泰羅卡森林碎石營地的追蹤者凱德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10004 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10004, 'zhTW', '耐心與諒解', '帶著藍圖前往泰洛卡森林的撒塔斯城。到了那裡就立刻去陰鬱城找一個叫沙薩拉畢恩的莫阿格。他大概會在酒吧裡，借酒澆愁。$B$B對了，你要說服他協助你。試著以耐心和諒解接近他。如果沒有用，就用你的拳頭來解決。', '西納葛蘭的『受難者』奧翠司要你帶著規劃大師的藍圖去找撒塔斯城的沙薩拉畢恩並說服他幫助你。', '說服薩薩拉比姆', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10005 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10005, 'zhTW', '讓大地束縛者塔伏格蘭知道', '$n，你在這邊慶祝完之後，我想你該回去塞納里奧灌木林和大地束縛者塔伏格蘭談談。$B$B我相信他會想知道那裡真正發生什麼事。', '到泰洛卡森林去和塞納里奧灌木林外的大地束縛者塔伏格蘭談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10006 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10006, 'zhTW', '讓大地束縛者塔伏格蘭知道', '$n，我想在這邊慶祝完之後，你該回去塞納里奧灌木林和大地束縛者塔伏格蘭談談。$B$B我相信他會想知道那裡真正發生什麼事。', '到泰洛卡森林去和塞納里奧灌木林外的大地束縛者塔伏格蘭談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10007 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10007, 'zhTW', '削弱軍隊', '薩德爾和伯特泰歐不會容忍這樣龐大的敵方軍隊出現在我們的門前。要他們派遣駐軍成員來參與攻擊營地也不可能。這只會讓我們變的很脆弱很好攻擊。$B$B我們的責任是盡力削弱魔獄獸人對我們的威脅。你盡力削減他們的兵力而我負責想辦法來拖延他們的援軍。', '殺死10個噬骨破壞者和6個噬骨斷背者再回去找瑟蘿莉雅·影篷。', '', '去泰羅卡森林找奧蕾莉亞崗哨的塞洛莉婭·影衣。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10008 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10008, 'zhTW', '把泰洛卡的事留在泰洛卡', '如果消息傳到索爾瑪讓他們知道控制魔獄獸人的事失敗了，我們就要有一大堆同伴了。老實說，我不想成為大家的焦點，所以我們不要讓這個小問題浮上檯面，懂嗎?$B$B如果我們可以讓魔獄獸人造成足夠的傷亡，他們的出現就不會再引起碎石堡外任何人的注意了。所以，讓我們現在就結束它吧。$B$B打起精神來吧，擺動你的武器，揮舞你的雙手，不管怎麼做都可以 - 只要殺死魔獄獸人。', '巡影者凱德要你去殺死10個噬骨破壞者和6個噬骨斷背者。', '', '去找泰羅卡森林碎石營地的追蹤者凱德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10009 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10009, 'zhTW', '解決一些傢伙', '<沙薩拉畢恩大笑。>$B$B這是沙薩拉畢恩設計的。$B$B<沙薩拉畢恩指著藍圖上的建築物和結構。>$B$B看看這些哨塔。惡魔獵手看不見，對嗎?淒慘，可憐的奧翠司。如果他有眼睛他會哭吧?$B$B沒錯，沙薩拉畢恩會幫忙但你要先幫忙沙薩拉畢恩。$B$B<沙薩拉畢恩給你一個帳本。>$B$B這些生物欠沙薩拉畢恩金子。很多金子。去幫沙薩拉畢恩討債再回來。他們不會輕易把沙薩拉畢恩的金子給你。你要和他們打上一架，不過你很強壯。你可以擊敗沙薩拉畢恩!', '撒塔斯城的沙薩拉畢恩要你取回拉利克的欠款，庫庫許的債款和服倫之債。', '', '去泰羅卡森林找撒塔斯城的薩薩拉比姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10010 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10010, 'zhTW', '就這麼簡單嗎?', '<沙薩拉畢恩指著藍圖。>$B$B你看到惡魔火砲在哪了嗎?$B$B<沙薩拉畢恩畫下一個箭頭表示改變方向。>$B$B你把惡魔火砲轉過來用在建築物上。$B$B等等!別太瘋狂!有一件你不知道的事。監督者有啟動火砲的鑰匙。你要先弄到鑰匙!每個監督者身上各有一把!$B$B不是這麼簡單，對吧?$B$B把消息帶回去給奧翠司。', '撒塔斯城的沙薩拉畢恩要你回到西納葛蘭找『受難者』奧翠司。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10011 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10011, 'zhTW', '煉冶場:徹底擊潰', '召集你的盟友，$n。如果你要挑戰監督者就需要他們。$B$B一旦你有了適合的團隊，就到各個煉冶場找到並殺死監督者。拿走他們的鑰匙並用它們開啟惡魔火砲對煉冶場發射。等煉冶場都被摧毀後再回到我這裡。', '納葛蘭西邊的『受難者』奧翠司要你去摧毀煉冶場:仇恨和煉冶場:恐懼。', '', '去找納格蘭的受難者奧圖裡斯。', '摧毀鑄魔營地：仇恨', '摧毀鑄魔營地：畏懼', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10012 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10012, 'zhTW', '魔獄獸人計畫', '計畫書上的字體太精細準確，不像是魔獄獸人寫出來的。你無法理解文字在表達什麼，但它的含意十分明顯:魔獄獸人正接受火翼崗哨的血精靈命令。$B$B為什麼這兩個力量會結合在一起?伯特泰歐或許對這奇怪的聯盟組合有些見解。你決定回到艾蘭里堡壘給他看看這個圖像。', '將魔獄獸人計畫交給艾蘭里堡壘的伯特泰歐。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10013 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10013, 'zhTW', '看不見的手', '計畫書上的字體太精細準確，不像是魔獄獸人寫出來的。你無法理解文字在表達什麼，但它的含意十分明顯:魔獄獸人正接受火翼崗哨的血精靈命令。$B$B為什麼這兩個力量會結合在一起?瑞克格或許對這奇怪的聯盟組合有些見解。你決定回到碎石堡給他看看這個圖像。', '將魔獄獸人計畫交給碎石堡的瑞克格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10014 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10014, 'zhTW', '火翼崗哨的專案', '正如我說的那樣，我們已經收到了新的情報，並且面臨著更棘手的問題。$B$B血精靈正在火翼崗哨拼命地製造第二枚炸彈。用不著我再多說，你也知道一旦他們建成這個裝置並投入使用的話，對奧蕾莉亞要塞來說該意味著什麼了！$B$B我的偵察員告訴我他們在環繞中心庭院的四座較小的建築物裡看守著該裝置的密碼。趁現在還來得及，到那裡去幫我把密碼偷回來！', '偷取四張魔法炸彈密碼錶，把它們交給泰羅卡森林中奧蕾莉亞崗哨的米利迪安中尉。', '', '去泰羅卡森林找奧蕾莉亞崗哨的米利迪安中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10015 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10015, 'zhTW', '火翼崗哨的專案', '正如我說的那樣，我們已經收到了新的情報，並且面臨著更棘手的問題。$B$B血精靈正在火翼崗哨拼命地製造第二枚炸彈。用不著我再多說，你也知道一旦他們建成這個裝置並投入使用的話，對碎石堡來說該意味著什麼了！$B$B我的偵察員告訴我他們在環繞中心庭院的四座較小的建築物裡看守著該裝置的密碼。趁現在還來得及，到那裡去幫我把密碼偷回來！', '偷取四張魔法炸彈密碼錶，把它們交給泰羅卡森林中碎石營地的卡烏尼中士。', '', '去找泰羅卡森林的卡烏尼中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10016 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10016, 'zhTW', '灰座狼尾巴', '你的旅途中有遇到灰座狼嗎?我在勘測森林北邊區域的時候剛好有機會觀察他們。我不建議你靠近他們，除非你準備好來場戰鬥。$B$B他們不怕我們，也不會猶豫保衛他們的領土。$B$B像這樣的生物是很適合有著美麗的尾巴。我一直試著收集它們來修剪一件新披風，但那些座狼總是逃過我的陷阱。你能幫我嗎?', '艾蘭里堡壘的伯特泰歐要你去幫他帶回來12個灰座狼尾巴。可以從灰座狼或灰座狼首領身上取得。', '', '去泰羅卡森林找奧蕾莉亞要塞的波爾泰姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10017 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10017, 'zhTW', '物資短缺', '每天都有越來越多難民通過撒塔斯城的大門。有些人承受了巨大的傷口，他們還能到的了這裡真是奇蹟。$B$B我可以應付大部分的普通傷口;我做為奧多爾醫者的訓練讓我有這樣的能力。毒藥傷害則比較麻煩，因為我的抗毒補給已經開始短缺了。$B$B幫我從當地的懼牙蜘蛛身上取下毒囊帶來給我，這樣我就可以製造更多解毒劑。你會在泰洛卡東南方找到一塊蜘蛛區。', '將8個懼牙毒囊交給撒塔斯城的薩尼爾。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去找泰羅卡森林的莎妮爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10018 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10018, 'zhTW', '狼魂法衣', '幾個世代前，當獸人氏族仍將泰洛卡森林視為家園時，狼魂在他們生活中是一個重要的角色。當獸人離開，他們不再需要狼魂於是就將它留下了。$B$B時間過去，狼魂變的很孤單便也離開了森林。$B$B我相信我可以將狼魂帶回他的祖傳家園，就像我們獸人回來一樣。儀式需要用森林的狼皮來製作法衣，才能引導靈魂回到它的家。', '將12塊灰座狼皮交給碎石堡的瑪魯卡茲。', '', '去泰羅卡森林找碎石堡的瑪魯卡茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10019 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10019, 'zhTW', '更多毒囊', '', '', '', '去找地獄火半島的莎妮爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10020 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10020, 'zhTW', '給札麗亞的解藥', '我右邊這位女士的頭部有嚴重的創傷。她活了下來，但卻失去了她的視力。$B$B我的人民使用的一種傳統解藥需要非常老的蜥蝪血液。$B$B不幸的是，由於許多團體私下偷偷獵捕，泰洛卡蜥蝪都活不久。$B$B有一隻蜥蝪是我從年輕時就知道的。他叫做「岩石凝視者」傳說他住在東邊，靠近這個地區的邊緣。$B$B幫我把他的血帶回來，這樣札麗亞才能重見光明。', '將岩石凝視者之血帶給撒塔斯城的薩尼爾。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去找泰羅卡森林的莎妮爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10021, 'zhTW', '恢復聖光', '很久前大都是德萊尼住在這個區域。我們奧多爾奉命保護我們神聖的舊址和聖壇。它們很多都被我們的敵人給摧毀或奪去。$B$B這裡的東邊有一個阿拉卡前哨站。它是有目的地建在我們三個神聖的聖壇地點上。阿拉卡使用他們邪惡的魔法來扭曲及汙染我們神殿的內在力量。$B$B帶著這個瓶子前往阿拉卡前哨站並用它來淨化那三個聖壇。', '伊莎納要你去撒塔斯城東邊的阿拉卡前哨站使用神聖之瓶淨化東祭壇，西祭壇以及北祭壇。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去撒塔斯城找奧爾多高地的伊沙娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10022, 'zhTW', '難捉摸的鐵顎', '既然我有了修剪需要的毛皮，我想有一隻狼的毛皮會很適合做我披風的兜帽。想像看見你的敵人穿著森林裡最奸詐的掠奪者的毛皮!$B$B我試過對老鐵顎設陷阱，但沒有成功。我試過圍捕他，用計謀打敗他，引誘他。沒有一次成功過。$B$B他都在森林的東北區閒晃，如果你能成就我所不能，我會很樂意獎勵你。', '將鐵顎的生皮交給艾蘭里堡壘的伯特泰歐。', '', '去泰羅卡森林找奧蕾莉亞要塞的波爾泰姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10023, 'zhTW', '鐵顎族王', '你收集第一堆毛皮表現的很好。$B$B法衣的最後一個部份需要一種獨一無二的毛皮。有一隻特別的狼，又老又奸詐，靠它的力量當上了森林狼的族王。森林狼們稱他為鐵顎，萬能的獵人。$B$B在我的幻境中，我看過他在森林的東北區徘徊。在法衣裡加入他的毛皮一定會點亮狼的精神之路。$B$B不要為鐵顎哀悼。他會很光榮的。', '將鐵顎的生皮交給碎石堡的瑪魯卡茲。', '', '去泰羅卡森林找碎石堡的瑪魯卡茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10024, 'zhTW', '沃藍索的預言', '我們的領導者，『先知』沃藍索，曾是凱爾薩斯親近的顧問。他預見的幻象警告他凱爾的行徑會導致我們族人的毀滅。$B$B幻象通常是模糊不清的，但我們的鍊金師發明了一種精華能幫他集中他的洞察力。不幸地，這種精華需要一種稀有的材料:蜥蜴眼。我通常的來源，這個可悲的伊斯利，讓我很失望。$B$B到泰洛卡的岩石區尋找濕鱗蜥蜴並把他們的眼睛帶回來。', '將8個濕鱗蜥蜴眼交給撒塔斯城的秘法師艾德蕊雅。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去找撒塔斯城的奧術師艾蒂莉亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10025 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10025, 'zhTW', '更多蜥蜴眼', '', '', '', '去找地獄火半島的奧術師艾蒂莉亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10026, 'zhTW', '魔法干擾', '承認這點很令人難為情，但我在泰洛卡森林這裡發生了一些事，是我當學徒開始從未發生過的。$B$B偶爾，我的法術會失敗，而我知道我沒有做錯任何一個步驟。第一次發生的時候我幾乎快瘋了。$B$B我想我找到了原因。森林裡充滿了叫做扭曲行者的生物，他們是喜好魔法的惡魔，習慣干擾魔法波動。對付他們最好的方法就是殺了他們。', '艾蘭里堡壘的安達爾歐要你殺死10個扭曲行者。', '', '去泰羅卡森林找奧蕾莉亞要塞的安達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10027 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10027, 'zhTW', '魔法干擾', '沒有什麼比準備施放法術還討人厭的，除了被某種看不見的力量給中斷。第四次發生之後我知道這可能是某種巧合，所以我派奇柏伊斯歐去調查。$B$B我保證你永遠不會遇到一個比奇柏伊斯歐還會回嘴的小鬼。$B$B總而言之，他設法找到了一個問題的來源，一個叫做扭曲行者的討厭生物。他們習慣干擾所有看的到的魔法能量。我受夠他們的干擾。', '殺死10個扭曲行者並回到碎石堡向庫爾卡拓克回報。', '', '去泰羅卡森林找碎石堡的庫加托克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10028, 'zhTW', '能量容器', '杜瑞廢墟裡有很多帶著新鮮魔法能量的容器。我們很幸運統治這城市的破碎者竟忽略了他們的資源，但我們不能以為他們永遠都會如此。$B$B有了那些容器和它們的能量，我們人民中散落的生還者就能抵抗惡魔魔法的誘惑。我們從王子的愚行下每救一個奎爾多雷就多一個人幫我們重建失落的光輝。幫我把這些容器帶來，$c。', '將8個德萊尼容器交給艾蘭里堡壘的羅斯勒斯。', '', '去泰羅卡森林找奧蕾莉亞要塞的洛瑟蕾絲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10029 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10029, 'zhTW', '亡靈在召喚', '白骨荒野的亡者靈魂一直在召喚著我！其中一個叫索拉伏恩在懇求我的幫助。$B$B$C，你一定要前往南方的白骨荒野幫助這個靈魂。他就在奧齊頓的北邊入口附近。為了跟他溝通，你必須跨越時空到來生一下。我會給你一份精華讓你在荒野裡使用。$B$B如果你覺得需要更多的精華，就回來找我。\\r\\n\\r\\n', '隱士麗蒂娜要你去泰洛卡森林的白骨荒野，在難民商隊找到她的助理，索拉伏恩。$B$B完成奧爾多所有的任務會降低你的占星者聲望。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10030 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10030, 'zhTW', '取回白骨', '因為奧齊頓的爆炸而亡的德萊尼白骨散落在白骨荒野上。他們的靈魂無法得到安息，也不能向來生前進。$B$B$c，你必須幫我取回他們的骨頭然後將他們帶到最終的安息地!只有這樣他們才能安息;只有這樣他們才能安心。$B$B小心的收集那些無法安息的骨頭然後交給白骨荒野中心地帶的奧齊頓的瘋狂的藍姆多。儘管他的名字如此，他會知道如何照顧他們的。', '收集10根無法安息的白骨。交給奧齊頓儀式競技場西邊的瘋狂的藍姆多，位在泰洛卡森林的白骨荒野中間。', '', '去泰羅卡森林奧金頓的儀式廣場找瘋狂的拉姆杜爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10031 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10031, 'zhTW', '幫迷失者找到方向', '許多德萊尼的靈魂受到奧齊頓的爆炸而腐化了。現在他們痛苦的遊蕩在荒野中。$B$B$n，我懇求你讓他們安息吧。殺死那些遠在奧齊頓牆邊的白骨荒野中遊蕩的迷失的靈魂和德萊尼骷髏。$B$B什麼?你認為讓他們盲目的在痛苦中遊蕩會比較好嗎?$B$B完成之後，回去找難民商隊的索拉伏恩然後告訴他你完成的事情。', '殺死10個迷失的靈魂和10個德萊尼骷髏，然後跟難民商隊的索拉伏恩談話，位在泰洛卡森林的白骨荒野。', '', '去白骨荒野找難民車隊的蘇拉文。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10032 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10032, 'zhTW', '圖雷姆的神器', '你留意過圖雷姆的那些失落者嗎？他們一直在廢墟中四處徘徊，尋找德萊尼人留下來的碎片。$B$B這些失落者的智慧水平完全不能與他們的破碎者主人相比，他們已經忘掉了以前的生活和身份，變成了完全不同的物種。$B$B我認為我們可以利用失落者的這些無意識舉動來收集到一些古老的德萊尼聖物。既然妥善地選擇目標能夠為我們謀得利益，還為什麼要去冒險與這些破碎者開戰呢？', '從圖雷姆清道夫和圖雷姆獵人身上收集6個圖雷姆神器，把它們交給碎石堡的拉克妮亞。', '', '去泰羅卡森林找碎石堡的拉克妮亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10033 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10033, 'zhTW', '懸賞:鞭骨者的死亡!', '重金懸賞白骨荒野的鞭骨者。身為眾所皆知的瘟疫帶原者，得盡速消滅他們!雖然它們遍佈整個荒原，但大部分的鞭骨者聚集在北邊的腐蝕嶺。$B$B完成後向泰伊拉·艾薇斯崔德回報並領取你的獎賞。', '殺了20隻鞭骨者後回報給泰洛卡森林裡艾蘭里堡壘的泰伊拉·艾薇斯崔德。', '', '去泰羅卡森林找奧蕾莉亞要塞的泰拉·遠途。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10034 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10034, 'zhTW', '懸賞:鞭骨者的死亡!', '白骨荒野的鞭骨者襲擊矛克使他病了。現在他要他們全部消失!$B$B雖然鞭骨者遍佈整個荒原，但是大部分的鞭骨者聚集在北邊的腐蝕嶺。$B$B完成任務後回報矛克·邪擊，他會給你一筆重賞的。', '殺了20隻鞭骨者後回報給泰洛卡森林裡碎石堡的矛克·邪擊。', '', '去泰羅卡森林找碎石堡的瑪烏格·銳箭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10035 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10035, 'zhTW', '托茍斯!', '白骨荒野裡有個非常可怕的生物，只有那些無畏的勇士才敢追蹤他。$B$B我說的就是托苟斯，它是鞭骨者裡頭的王者，它徘徊在白骨荒野西部邊疆地帶的迷霧瑞漢茲。$B$B可惜那邊有一個阿拉卡稻草人，人們都稱它為托苟斯剋星，它使得托苟斯只敢待在海灣一帶。我打賭假如你把托苟斯的配偶崔奇拉的屍體放在稻草人的腳下，托苟斯還是會趕來。你可以在白骨荒野北邊的腐蝕嶺找到她。$B$B幫我帶回來一根托苟斯尾巴上的羽毛。', '利用崔奇拉的屍體引誘托苟斯出現。取得一根托茍斯的尾羽然後交給泰洛卡森林的艾蘭里堡壘的泰伊拉·艾薇斯崔德。', '', '去泰羅卡森林找奧蕾莉亞要塞的泰拉·遠途。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10036 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10036, 'zhTW', '托茍斯!', '托苟斯這些鞭骨者的王，我要他的命!$B$B不久前，當我出外在迷霧瑞漢茲西方的角落狩獵時，這支畜牲向我撲了過來。$B$B<矛克敲了敲他的眼罩。>$B$B它奪走了我的眼睛，而現在我要他的命!把他的一隻尾羽帶給我當證明，我會給你豐厚的獎賞。$B$B你將需要他的配偶崔奇拉的屍體才能喚它下來，因為他非常害怕那邊一個被人稱為托苟斯剋星的阿拉卡稻草人。$B$B你可以在腐蝕嶺的北邊荒原地區找到她。', '利用崔奇拉的屍體引誘托苟斯出現。取得一根托苟斯的尾羽然後回到泰洛卡森林的碎石堡找矛克·邪擊。', '', '去泰羅卡森林找碎石堡的瑪烏格·銳箭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10037 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10037, 'zhTW', '當然是釣魚', '說起湖來，東北方上面那有個很適合釣魚的湖。我都跟朋友一起過去，但是我的母親不再讓我去那裡了。$B$B她說那裡太危險了，但我根本不曾在那看過任何東西，除了幾隻蜘蛛。好像蜘蛛會對你怎麼一樣……$B$B我最愛的就是那邊的鰻魚。如果你正要往湖那邊過去，能不能幫我帶點鰻魚回來?他們很會亂跳，不過一旦你制服他們，就能安穩的帶回來了。', '將8隻新鮮閃鱗鰻交給撒塔斯的塞斯。', '', '去找撒塔斯城貧民窟的塞瑟。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10038 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10038, 'zhTW', '與士兵維克斯談話', '葛蘭戈瓦村附近一位斥候的報告才剛送進來。他提到一個幽暗團隊進入了那裡的廢墟。$B$B$n，我要你跟士兵維克斯談談，看看你能如何協助他找出那個不明團隊的目的。往西邊去，越過碎石堡。他上一份報告提到他的位置在接近村子的北方入口處。', '在泰洛卡森林的葛蘭戈瓦村北方入口處找到士兵維克斯並與他談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10039 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10039, 'zhTW', '與斥候奈夫提斯談話', '我已經通知那位目前在葛蘭戈瓦村附近監視幽暗團隊的斥候近日遷移到那裡。$B$B$n，我要你與斥候奈夫提斯談談並看你要如何協助她找出這個不明團隊的目的。$B$B朝著這裡的南方前進，然後轉向正西方，繞過白骨荒野的北方。她最後一次的報告指出她的位置位於村子的南邊入口附近。', '在泰洛卡森林的葛蘭戈瓦村南方入口處找到斥候奈夫提斯並與她談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10040 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10040, 'zhTW', '他們是誰？', '我不清楚他們是誰，但我知道他們不懷好意!$B$B我會給你一個偽裝，要你去跟他們這三個我覺得很「多話」的人說話。與新兵、工人、以及諫言者對話。$B$B但是要小心;那裡有幾位兇猛的獵人有可能會看穿你的偽裝!無論你要做什麼，都別離開村莊 - 偽裝是很容易破除的。要是你失去了你的偽裝，回到我這裡來，我會再給你另一個。', '於偽裝中與幽暗的新兵，幽暗的工人及幽暗的諫言者說話。完成後回到泰洛卡森林的葛蘭戈瓦村中找士兵維克斯回報。', '', '去泰羅卡森林找格蘭戈瓦村的列兵維克斯。', '與陰暗新兵交談', '與陰暗勞工交談', '與陰暗顧問交談', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10041, 'zhTW', '他們是誰？', '我不清楚他們是誰，但我知道他們不懷好意!$B$B我會給你一個偽裝，要你去跟他們這三個我覺得很「多話」的人說話。與新兵、工人、以及諫言者對話。$B$B但是要小心;那裡有幾位兇猛的獵人有可能會看穿你的偽裝!無論你要做什麼，都別離開村莊 - 偽裝是很容易破除的。要是你失去了你的偽裝，回到我這裡來，我會再給你另一個。', '於偽裝中與幽暗的新兵，幽暗的工人及幽暗的諫言者說話。完成後回到泰洛卡森林的葛蘭戈瓦村中找斥候奈夫提斯回報。', '', '去泰羅卡森林找格蘭戈瓦村的斥候奈弗蒂絲。', '與陰暗新兵交談', '與陰暗勞工交談', '與陰暗顧問交談', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10042 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10042, 'zhTW', '殺光暗影議會!', '什麼!這些傢伙都是暗影議會的?!$B$B$n，你必須回到那裡並殺光他們!我要你殺掉他們的領導者及所有的劊子手和召喚者。$B$B在你完成後，向艾蘭里堡壘的葛拉伏汗中尉回報。$B$B祝你好運，$c!', '殺掉10個幽暗的劊子手，10個幽暗的召喚者及暗影大師葛瑞弗，然後回到泰洛卡森林的艾蘭里堡壘與葛拉伏汗中尉回報。', '', '去泰羅卡森林找奧蕾莉亞要塞的加維·砂錘中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10043 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10043, 'zhTW', '殺光暗影議會!', '什麼!這些傢伙都是暗影議會的?!$B$B$n，你必須回到那裡並殺光他們!我要你殺掉他們的領導者以及所有的劊子手和召喚者。$B$B在你完成後，回報給碎石堡的諫言者菲拉。$B$B祝你好運，$c!', '殺掉10個幽暗的劊子手，10個幽暗的召喚者及暗影大師葛瑞弗，然後回到泰洛卡森林的碎石堡回報諫言者菲拉。', '', '去泰羅卡森林找碎石堡的顧問菲埃拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10044 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10044, 'zhTW', '與祖母的會面', '祖母要我前來找你並傳達一個訊息。她希望和你談談。$B$B我的毅力已經降低了但還不會出錯，$n，如果你使祖母生氣，我將會盡我最後所能擊敗你。她在主廳中。$B$B<卡爾洛斯指著北方的大建築物。>$B$B聆聽並照她的話去實行。', '與祖母吉雅談談，並聆聽她跟你說的內容。', '聆聽蓋亞安祖母的話', '去納格蘭找加拉達爾的蓋亞安祖母。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10045 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10045, 'zhTW', '材料成分', '卡修爾母親想與你談談，$n。在此成真前，你得先收集所需的藥草來製作可擴展你的心靈，進而得以與神靈溝通的藥劑。$B$B你得取得泰洛卡的奧萊姆貝根莖，贊格沼澤的沼澤梅，納葛蘭的泰拉蕊藻葉以及劍刃山脈的龍脊。我已經把這些藥草種植地的指引寫在這個羊皮紙上。等你收集好這些材料後回來找我。', '納葛蘭的卡拉達爾的祖母吉雅要你收集1個奧萊姆貝根莖，1個沼澤梅，1個泰拉蕊藻葉及1個龍脊。', '', '去納格蘭找加拉達爾的蓋亞安祖母。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10046 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10046, 'zhTW', '跨越黑暗之門', '兩週前，我們接到哨兵的報告，稱戰地指揮官洛姆斯帶領著一支浩浩蕩蕩的聯盟大軍離開了守望堡。這支軍隊兵力雄厚，供給充足，並且有著一位屢建戰功的指揮官，他們的目標必定只有一個：揮師外域。$B$B酋長已經派出先遣部隊轉至黑暗之門，如果聯盟真的認為有必要派那麼多人去，那我們也得讓他們見識一下部落的增援部隊。$B$B跨越黑暗之門，向索爾瑪的納茲格雷爾報到。', '跨越黑暗之門，跟索爾瑪的納茲格雷爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10047 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10047, 'zhTW', '光榮之路', '光榮之路，他們這樣稱呼它。一條從他們灰暗的堡壘中心到黑暗之門的路，以我的人民的骨骸所鋪成的。$B$B把我們當成動物一般來狩獵，摧毀我們的城市，折磨那些活著的人對他們來說是不夠的了。沒錯，他們拿我們的骨駭當成鋪路石，不讓我的兄弟們在聖光下有一處適當的墳地。$B$B那些受折磨的靈魂仍在這些地方徘徊，我請求你，$n，幫助我。', '在光榮之路上使用德萊尼聖水清洗8個被踐踏的骨骸，完成後回到榮譽堡找星移占卜師克里。', '', '去地獄火半島找榮耀堡的位面占卜者克雷夫。', '淨化被踐踏的骷髏', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10048 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10048, 'zhTW', '魔法粉塵', '我需要一些粉塵，但不是普通的粉塵。$B$B附近森林中的華麗的巨蛾翅膀上覆蓋著一種魔法粉塵，可以讓試圖捕獲它們的生物平靜下來。我可以利用這種粉塵來破除鴉人之眼的魔法結界。這樣，我們就可以用它們來追蹤迪魯姆的下落。$B$B我不需要太多，幾小撮粉塵就行。', '收集7撮安撫粉塵，將它們交給奧蕾莉亞要塞的安達爾。', '', '去泰羅卡森林找奧蕾莉亞要塞的安達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10049 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10049, 'zhTW', '魔法粉塵', '我需要一些粉塵，但不是普通的粉塵。$B$B附近森林中的華麗的巨蛾翅膀上覆蓋著一種魔法粉塵，可以讓試圖捕獲它們的生物平靜下來。我可以利用這種粉塵來破除鴉人之眼的魔法結界。這樣，我們就可以用它們來追蹤杜加爾的下落。$B$B我不需要太多，幾小撮粉塵就行。', '收集7撮安撫粉塵，將它們交給碎石堡的庫加托克。', '', '去泰羅卡森林找碎石堡的庫加托克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10050 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10050, 'zhTW', '不屈的靈魂', '入侵的接近尾聲的時候，南方的軍械庫被部落狡詐的死亡騎士攻陷。那些卑劣的幽靈詛咒軍械庫的防衛者 - 將他們困在在生與死的中間界。$B$B必須釋放那些高貴的靈魂自由!我請求你，$n，結束我的同志們的折磨，因為我無法親自動手。', '榮譽守衛衛斯羅要你去南方的遠征隊軍械庫打敗12個不屈的步兵，10個不屈的魔巫士，和5個不屈的騎士。', '', '去地獄火半島找榮耀堡的榮耀堡衛兵維斯洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10051 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10051, 'zhTW', '逃出火翼崗哨!', '感謝老天!$B$B$c，我需要你幫我逃離。我這有對艾蘭里堡壘的防禦以及可能有關整個外域的重要訊息!$B$B我從塞納里奧遠征隊那過來，擔負著外交任務，不過就像你看到的，他們不是很友善。如果你能夠保護我平安，我擔保你可以得到相當可觀的獎賞!$B$B我們可能沒辦法只靠自己 - 你有隊伍吧，有嗎?', '護送伊斯拉·星鬃到安全的地方後回報泰洛卡森林裡艾蘭里堡壘的阿瑞克·追日者上尉。', '護送伊斯拉·星鬃', '去泰羅卡森林找奧蕾莉亞要塞的烏瑞克·獵日者上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10052 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10052, 'zhTW', '逃出火翼崗哨!', '感謝老天!$B$B$c，我需要你幫我逃離。我這有對碎石堡的防禦以及可能有關整個外域的重要訊息!$B$B我從塞納里奧遠征隊那過來，擔負著外交任務，不過就像你看到的，他們不是很友善。如果你能夠保護我平安，我擔保你可以得到相當可觀的獎賞!$B$B我們可能沒辦法只靠自己 - 你有隊伍吧，有嗎?', '護送伊斯拉星鬃到安全的地方後回報泰洛卡森林裡碎石堡的諫言者菲拉。', '護送伊斯拉·星鬃', '去泰羅卡森林找碎石堡的顧問菲埃拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10053 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10053, 'zhTW', '進攻塞斯高', '我們必須妥善利用你殺死指揮官奈克羅格這一輝煌戰果，要乘勝追擊，$N。如果我們運氣夠好，塞斯高的首領——“暗眼”格里洛克現在應該還沒有收到任何關於奈克羅格的訊息。$B$B這個“暗眼”格里洛克領導著東南邊塞斯高的噬骨氏族邪獸人發動過許多次戰爭。立刻轉至他的巢穴，到那處邪獸人營地內的某個山洞裡找到並幹掉他。然後，你要在洞中找到邪獸人的作戰計劃書，我們一定要避免遭到對方的突襲。', '擊敗“暗眼”格里洛克，在他的巢穴中搜尋血環攻擊計劃書。', '', '去地獄火半島找塞斯高的血環攻擊計劃書。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10054 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10054, 'zhTW', '迫近的厄運', '快速地瀏覽完整個計劃之後，你發現這次的襲擊應該是由塞斯高的首領督軍摩爾肯直接策劃，由白骨法師沃爾洛率隊執行的。此外，地圖上標識出的東西遠不止摩爾肯的部隊而已。$B$B計劃書中還提到，已經完成集結的噬骨氏族軍隊將配合來自地獄火堡壘的其它邪獸人軍隊向榮耀堡發起全面的進攻。$B$B沒有時間去通知阿曼蒂中尉了。你必須在噬骨氏族的軍隊發起進攻前阻止他們！', '殺死15名血環步兵、10名血環通靈師、5名血環苦工和督軍摩爾肯，然後向榮耀堡西部哨塔的阿曼蒂中尉報到。', '', '去地獄火半島找榮耀堡西部哨塔的阿曼蒂中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10055 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10055, 'zhTW', '不浪費，就不缺乏', '有援軍太好了，不過我沒看到他們有任何馬車搬運錠塊及木材過來。$B$B看看周圍，朋友。樹木短缺，礦也已經超過軍隊鐵渣的需求。$B$B補給品缺乏，我儘所能地使用替代品，但已經面臨開始得重覆使用的狀況了。$B$B光榮之路的南方邊緣有許多佈滿機械圍繞的廢墟。其中仍有一些可以使用。你覺得可以用來廢物利用嗎?', '將8塊可利用的鐵及8塊可利用的木頭交給榮譽堡的戴夫利。', '', '去地獄火半島找榮耀堡的達姆菲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10056 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10056, 'zhTW', '血環補給品', '東南邊的獸人城鎮廢墟塞斯高現在成了那些地獄火堡壘中源源不斷湧出的邪獸人的基地。$B$B洛薩之子一直和他們有著小規模的對抗和衝突。那些邪獸人真的十分可怕，若是我沒有親眼見過他們，恐怕真得很難相信洛薩之子對他們的評價。$B$B總之，某種神秘的東西令那些邪獸人發生了變化，變得更加強大了。我們必須想辦法阻止他們繼續壯大自己的力量。現在你立刻轉至塞斯高，破壞掉那裡所有的補給品。', '摧毀6堆血環補給箱，然後向榮耀堡的阿曼蒂中尉覆命。', '', '去地獄火半島找榮耀堡的阿曼蒂中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10057 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10057, 'zhTW', '與領導者同在', '遠征隊軍械庫的煩惱一直都在，就算有了你的大力幫忙。沒人真的相信這裡發生的事，也不相信有被困在廢墟裡的那些墮落士兵的靈魂。$B$B也許我們用錯法法處理這件事了。我一直都認為每個鬼魂都是跟廢墟連繫在一起，但如果他們是跟隨著他們的領導者的話呢?$B$B大法師辛特和少校薩沃斯是最接近他們的人，也許擊敗他們的鬼魂將可平息剩下的其他人。', '擊敗大法師辛特和少校薩沃斯的鬼魂後回到榮譽堡西北邊的塔中找榮譽守衛衛斯羅。', '', '去地獄火半島找榮耀堡的榮耀堡衛兵維斯洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10058 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10058, 'zhTW', '一份多年的禮物', '<牧師的目光緩緩的從他的杯子轉向你。>$B$B你難道不知道最好不要打擾手持杯子的人嗎?$B$B喔，這是要幹嘛的?我猜有新訪客是好事。圖拉揚在想什麼?$B$B我猶記得我們離開的前夕，我將光明的奧秘交給他。在戰爭及接下來這幾年，他從未忘記每日對士兵們朗讀其中一節。$B$B當他再度離開我們，他將書還給了我。也許很傻，但我相信書就安全地放在軍械庫的南方的我的營地裡。', '取得光明的奧秘後回到榮譽堡交給神父摩葛·戴維迪克斯。', '', '去地獄火半島找榮耀堡的瑪格爾·戴維迪庫斯神父。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10059 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10059, 'zhTW', '塞斯高的首領', '我們必須妥善利用你殺死指揮官奈克羅格這一輝煌戰果。要乘勝追擊，$N！如果我們運氣夠好，塞斯高的首領——“暗眼”格里洛克現在應該還沒有收到任何關於奈克羅格的訊息。$B$B這個“暗眼”格里洛克領導著東南邊塞斯高的噬骨氏族邪獸人發動過許多次戰爭。立刻轉至他的巢穴，到那處邪獸人營地內的某個山洞裡找到並幹掉他。然後，你要在洞中找到邪獸人的作戰計劃書，我們一定要避免遭到對方的突襲。', '殺死“暗眼”格里洛克，在他的巢穴中搜尋血環攻擊計劃書。', '', '去地獄火半島找塞斯高的血環攻擊計劃書。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10060 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10060, 'zhTW', '迫近的末日', '快速地瀏覽完整個計劃之後，你發現這次的襲擊應該是由塞斯高的首領督軍摩爾肯直接策劃，並由白骨法師沃爾洛率隊執行的。此外，地圖上標識出的東西遠不止摩爾肯的部隊而已。$B$B計劃書中還提到，已經完成集結的噬骨氏族軍隊將配合來自地獄火堡壘的其它邪獸人軍隊向榮耀堡發起全面的進攻。$B$B沒有時間去通知阿曼蒂中尉了\\r\\n。你必須在噬骨氏族的軍隊發起進攻前阻止他們！', '消滅15名血環步兵、10名血環通靈師、5名血環苦工和督軍摩爾肯，然後向斷脊氏族山脈的石頭守衛安比蘭彙報情況。', '', '去地獄火半島找斷脊氏族崗哨的石頭守衛安比蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10061, 'zhTW', '陰魂不散', '當初，噬骨氏族的邪獸人對遠征軍物資庫發動了一次突襲，幾乎將那裡的駐軍屠戮殆盡。那場戰役充滿了血腥和暴力，生還者寥寥無幾。$B$B後來，儘管我們派人埋葬了所有的死難者，可是他們的靈魂仍舊徘徊在那些廢墟之間。最近，我在預言的夢境常常看到，這些靈魂成為了索爾瑪最大的威脅之一。$B$B因此，現在我們能做的事情只有一件——必須讓這些靈魂得到安息。去吧，孩子，你必須擊敗他們。', '葛雷拉格要你轉至榮耀堡以南的遠征軍物資庫，殺死12個步兵的陰魂、10個巫師的陰魂和5個騎士的陰魂。', '', '去地獄火半島找斷脊氏族崗哨的葛雷拉格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10062, 'zhTW', '尋找領袖', '儘管你作了很大的努力，遠征軍物資庫的騷動仍在繼續。沒有人知道那裡到底發生了什麼事情，也不知道到底是什麼令那些死去的士兵靈魂依舊徘徊在廢墟。$B$B或許我們完全錯了。我看到的幻象顯示出每一個靈魂都被廢墟束縛，但也許束縛他們的其實是他們的首領呢？$B$B大法師辛托爾和塔沃斯少校在那些士兵周圍，擊敗他們的靈魂或許會讓其它的人安息下來。', '擊敗大法師辛托爾和塔沃斯少校的鬼魂，然後向斷脊氏族山脈的葛雷拉格覆命。', '', '去地獄火半島找斷脊氏族崗哨的葛雷拉格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10063 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10063, 'zhTW', '探險者協會，那是給地精的東西嗎?', '帶小孩!你相信嗎?他們把我從前途光明的考古發掘裡叫出來要我去奧迪席斯隊長的遠征隊去照顧一個小地精!我從未聽說有地精要當勘察員，所以我問了。看來好像我們現在接受地精了，而這個特別的傢伙受到魚人們的愛戴!哎，他已經下班了，在島的北方海岸那一個破舊的龜殼處紮營。如果你不相信我就去看看吧!', '在血色守望的北邊海岸上的破舊龜殼處尋找克羅波·維茲班。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10064, 'zhTW', '與阿格斯之手談談', '阿古斯之手在復仇者之陵建立了一個前方據點，但被血精靈及突變的野生生物在數量上遠遠的超過了。沒有後備的話，他們的前哨將有陷落的危險，而我們則無法監視旋繞導航器週遭的狀況。到復仇者之陵西北方找斥候喬爾力報到，並提供你的協助，$N。', '向復仇者之陵的斥候喬爾力報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10065, 'zhTW', '清出一條路來', '在我們偵察太陽之鷹及他們的門戶這段期間，我受了許多的傷。斥候羅莉設法幫我止血，並試著想出一個方法將我疏送到血色守望。$B$B問題就在於我們得放棄現在這個位置以確保日後能夠安全的回來。$B$B只要我們一離開這個神聖的地區，我們就會被劫毀者捉住。如果你能幫我們清理掉一些暴怒的劫毀者，也許就能讓我們回程安全些。', '殺了10個暴怒的劫毀者後回到復仇者之陵找斥候喬爾力。', '', '去找鮮血島的斥候喬爾力。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10066, 'zhTW', '噢，他們所編織的糾纏的圈套', '我們不敢放棄我們的哨站，或離開復仇者之陵太遠，$r。接近旋繞導航器的突變生物藉由水晶洩漏的能量而產生了極大的改變。$B$B突變的糾纏者好像獲得了某些程度的知覺。他們已經懂得創造，佈置，及隱藏惡毒的陷阱，能夠捕捉住即使是最細心的戰士。$B$B假如我們繼續否認事實，我們將無法與這些太陽之鷹對抗。去攻擊問題的源頭，$N。', '殺掉8個突變的糾纏者後向復仇者之陵的復仇者科林回報。', '', '去找鮮血島的復仇者科林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10067 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10067, 'zhTW', '污濁的水精靈', '大部分的生物接觸過水晶的能量後都以同樣的方式墮落:肌肉上有奇怪的記號，強烈地侵略性，以及身體有小片的水晶裂片。然而，位於這裡北方的污濁的水之靈似乎整個都晶化了。$B$B我之前從未看過任何生物會這樣晶化的，不過當我們偶然發現他們後，發現他們特別的危險。我們必須在太陽之鷹將他們當成新的力量來源前除掉他們。', '殺掉6個污濁的水之靈後回到復仇者之陵找復仇者科林。', '', '去找鮮血島的復仇者科林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10068 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10068, 'zhTW', '看井者索蘭尼亞', '現在，我需要你去做一些事。$B$B看井者索蘭尼亞需要你的貢獻。你很會討他的歡心。$B$B他就在這房間樓梯往上走的戶外觀景平臺上等你。', '與逐日者之島上日尖塔的看井者索蘭尼亞談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10069 AND `locale` = 'zhTW';
