INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10073, 'zhTW', '看井者索蘭尼亞', '現在，我需要你去做一些事。$B$B看井者索蘭尼亞需要你的貢獻。你很會討他的歡心。$B$B他就在這房間樓梯往上走的戶外觀景平臺上等你。', '與逐日者之島上日尖塔的看井者索蘭尼亞談談。', '', '', '', '', '', '', 0);
