INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10074, 'zhTW', '歐夏剛水晶粉末', '這地方就是德萊尼研究那魯水晶的主要研究場所。$B$B我們所發現的是與來自「 鑽石」山，歐夏剛的水晶有關的研究手札中真正的金礦山。看來好像這地區的所有東西都附著一些歐夏剛水晶殘留的粉末。如果你在這個區域冒險時有發現任何的粉末，把它帶回來給我，我會獎勵你一枚可以用來與軍需官購買物品並代表我感謝之意的標記。', '將10份沃舒古水晶塵樣本交給哈蘭的主研究員阿米蒂恩。', '', '去納格蘭找哈蘭的主研究員阿米蒂恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10075 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10075, 'zhTW', '歐夏剛水晶粉末', '', '', '', '去納格蘭找哈蘭的主研究員阿米蒂恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10076 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10076, 'zhTW', '歐夏剛水晶粉末', '這地方就是德萊尼研究那魯水晶的主要研究場所。$B$B我們所發現的是與來自「 鑽石」山，歐夏剛的水晶有關的研究手札中真正的金礦山。看來好像這地區的所有東西都附著一些歐夏剛水晶殘留的粉末。如果你在這個區域冒險時有發現任何的粉末，把它帶回來給我，我會獎勵你一枚可以用來與軍需官購買物品並代表我感謝之意的標記。', '將10份沃舒古水晶塵樣本交給哈蘭的主研究員卡託斯。', '', '去納格蘭找哈蘭的主研究員卡託斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10077 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10077, 'zhTW', '歐夏剛水晶粉末', '', '', '', '去納格蘭找哈蘭的主研究員卡託斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10078 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10078, 'zhTW', '將剩餘的變不需要的', '現在我們已經將我們的回收活動發展出地面之外，該是時候開始計畫的第二步了。$B$B穿過光榮之路，仍有部落老舊的刀刃發射器瞄準著我們。別讓他們的老舊騙了你，$n，他們還是非常危險。當我們正忙著盡力拓荒時，我們不能假裝以為部落正要拆除他們的軍備。$B$B拿著這個火炬，去燒掉還在的攻城設備。我不會給部落任何安全的機會。', '使用燃燒的火炬燒死光榮之路上監視的部落刀刃發射器。然後，將燃燒的火炬帶給榮譽堡的戴夫利。', '', '去地獄火半島找榮耀堡的達姆菲。', '燒燬東部的擲刀車', '燒燬中部偏東的擲刀車', '燒燬中部偏西的擲刀車', '燒燬西部的擲刀車', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10079 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10079, 'zhTW', '礦場的騷動', '甘納格的不適應者像瘟疫一樣流竄在礦坑中!$B$B他們不只將工人趕出隧道，還日夜的在那敲打!更糟的是，現在還有達納斯在盯我!他說要將我的麥芽酒配給量取消要是我不盡快改善的話!$B$B沒有礦工願意進去那裏，而守衛則忙著把自己喝到傻。$B$B我求求你，$n，幫幫我。達納斯可以奪走我的尊嚴，但是他不能奪走我的麥芽酒!', '殺掉12個甘納格工人後回去找工頭比干莫斯。', '', '去地獄火半島找榮耀堡礦洞的工頭比格姆斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10080 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10080, 'zhTW', '軍團的煉冶場', '如果你與休夫利談過話，他一定會告訴你他發現礦井遭到了侵襲，但這個煩惱是次要的，我知道這預示著將出現一個更大的惡魔。$B$B東北邊索爾瑪的部落前哨，燃燒軍團的爪牙們日以繼夜地忙碌著，他們到底在忙什麼呢？$B$B我派去的偵察員沒有一個回來。時間不知不覺地過去了，$N。想辦法混進鑄魔營地：狂亂，看看燃燒軍團到底在幹什麼。', '殺掉10個甘納格僕人，5個煉冶場軍團士兵，和5個悲痛之女，然後搜尋煉冶場:狂怒找出軍團意圖的證據。', '', '去找魔火峽谷的雕文方尖塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10081 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10081, 'zhTW', '與卡修爾母親會面', '一旦作用生效了可別被你可能見到的東西嚇到!這些靈魂都在我們身邊 - 一直都是。這瓶藥劑能讓你的心靈理解並最後見到這些靈魂。如果你要和卡修爾母親談談就得在這種狀態下才行。$B$B你會在西南方的一條大路上找到她，就在先祖之地那。', '祖母吉雅要你與卡修爾母親談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10082 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10082, 'zhTW', '焦慮的先祖們', '你有看到他們在我們身邊走動嗎?先祖之地正常來說都是平靜且不受打擾的。$B$B直到最近，先祖之靈紛紛覺醒且極度焦慮。某種事物嚴重打擾了這些靈魂。我們必須找出到底是什麼事，但首先，我們得先把這立即的威脅擺一邊。$B$B這些你看到正在走動的鬼魂不是真的先祖們而是他們狀態的呈現。你必須摧毀那些激動的獸人靈魂。去完成後回來找我。', '卡舒爾宗母要求你讓8個激動的獸人靈魂再次安息。', '', '去納格蘭找先祖之地的卡舒爾宗母。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10083 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10083, 'zhTW', '軍團的計劃', '$N.你複製了一份蝕刻在地板上的明顯雕紋的複本，但沒有第二個部份，這份圖表就完全沒有意義。$B$B戰場元帥洛哈瑪斯曾提及另一個位於西邊的營地，煉冶場:怨恨。有可能軍團將另外一半的計劃書放在那裡的某處嗎？$B$B如果軍團是在進行一個大規模的生產行動，那麼聚集在許多不同的地點是合理的。', '取得煉冶場:洩憤計劃再回到遠征隊哨塔找戰場元帥洛哈瑪斯。', '', '去地獄火半島找軍團前線的巴洛克元帥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10084 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10084, 'zhTW', '襲擊黑色祭壇', '擁有莫阿格工程師的技術及無止盡供應的甘納格部屬，他們會在我們將信送到守望堡前就開始大量生產惡魔劫奪者。$B$B我們別無選擇只能儘快的與他們對抗。我們在這次的進攻中無法將榮耀堡的軍力分撥去幫助你，這樣做無疑是自殺的行為。邪獸人和部落會緊抓住這一個弱點來攻擊我們。$B$B榮耀堡已經堅守了20年歲月了，我們不想要現在失去它。', '殺掉煉冶場:黑色祭壇的黑夜領主瑪法斯，完成後回報榮耀堡的軍隊指揮者達納斯·托爾貝恩。', '', '去地獄火半島找軍團前線的巴洛克元帥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10085 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10085, 'zhTW', '拜訪先祖們', '我需要你到先祖們的村落去，$n。到每一處仔細的尋找並看看先祖們是否還在。$B$B拜訪北邊的日春崗哨，山另一側遙遠北方的獰笑骷髏廢墟，東北的卡拉達爾，還有最後一個，納葛蘭和泰洛卡森林邊界的血之谷廢墟，就在東方。$B$B一旦你在他們的家中見到先祖們後回到我這裡來。', '納葛蘭上先祖之地的卡修爾母親要你去拜訪日春崗哨，獰笑骷髏廢墟，卡拉達爾以及血之谷廢墟。', '', '去納格蘭找先祖之地的卡舒爾宗母。', '拜訪日泉崗哨', '拜訪嘲顱廢墟', '拜訪加拉達爾', '拜訪血環廢墟', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10086 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10086, 'zhTW', '我替……部落工作!', '你相信嗎?這些獸人僱用我幫他們修補防禦工事以及製造爆裂物。這可是一般人夢寐以求的工作呢!可惜我們材料短缺，但是對於像我一個這麼聰明的哥布林來說當然不成問題!$B$B你願意幫助我嗎?我需要光榮之路上可利用的木頭還有廢棄的城垛上的可利用的金屬。去那邊幫我回收物資吧，但是要小心那些紅皮膚的獸人!$B$B任務完成後回來找領取大獎!', '將8片可利用的金屬及8塊可利用的木頭交給索爾瑪的奴克巴斯。', '', '去地獄火半島找索爾瑪的澤格·納克布斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10087 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10087, 'zhTW', '為了部落……燒了它!', '我是一個幸運的哥布林。我可以有機會製造爆裂物還有殺人機器，而且知道它們馬上就會用在重要的任務上!$B$B講到任務，我剛接獲一個索爾瑪的命令:燒毀那些光榮之路對面兩側的聯盟火砲...就是那些異常靠近又將砲口危險地指向部落防禦工事的火砲。拿著這個火炬去火砲那邊。點燃火炬然後看那些火砲燒成火花吧!', '使用燃燒的火炬燒毀東邊的聯盟火砲還有西邊的聯盟火砲，然後回報索爾瑪的米希克·奴克巴斯。', '', '去地獄火半島找索爾瑪的澤格·納克布斯。', '燒燬東部火炮', '燒燬西部火炮', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10088 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10088, 'zhTW', '礦場的騷動', '礦井遭遇了甘納格之災，而苦工們卻認為這是一個小憩的好時機！我不明白為什麼在礦井被擾亂時他們居然還睡得著，但這不是關鍵問題。如果我們不能儘快地幹掉那些該死的甘納格，索爾瑪將會面臨礦石和其它礦物供應不足的危機。我已經向警備隊長克朗克請求幫助了，但是他說城鎮遭到了持續不斷地攻擊，他沒有辦法派出多餘的人手來幫助我。你願意幫幫我嗎？', '殺掉12個甘納格工人後回報工頭拉澤克拉茲。', '', '去地獄火半島找索爾瑪的工頭拉澤克拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10089 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10089, 'zhTW', '軍團的煉冶場', '自索爾瑪建立後，遭到了燃燒軍團炮擊。我們一直在努力抵抗，但形勢變得越來越糟糕。$B$B影子獵人泰巾曾多次嘗試瞭解更多敵人的情況，但他派出的偵察員沒有一個能回來。$B$B時間不知不覺地過去了，$N。想辦法混進鑄魔營地：狂亂，看看燃燒軍團到底在幹什麼。', '殺掉10個甘納格僕人，5個煉冶場軍團士兵，和5個悲痛之女，然後搜尋煉冶場:狂怒找出軍團意圖的證據。', '', '去找魔火峽谷的雕文方尖塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10090 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10090, 'zhTW', '軍團的計劃', '你雖然複製了蝕刻在地面上閃光的符號，但缺少另外一半這個圖表沒有任何意義。$B$B這些符號顯示西邊的 煉冶場:怨恨 也參與到了這個計劃。燃燒軍團會不會把圖表的剩餘部分藏在那裡？$B$B如果燃燒軍團想要製造某種醜陋的巨型怪物，那他們所有的營地都會參與進去的。', '取得煉冶場:洩憤計劃再將它們交給劫奪者荒野的霸主殘拳。', '', '去地獄火半島找機甲殘骸的大督軍霍恩·重拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10091 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10091, 'zhTW', '靈魂儀器', '啊!他們折磨我，試圖從我口中得知撒塔斯的防禦措施。$B$B我失敗了 - 他們將其他人拿去餵海爾瑪，而我就是下一個了。但我沒有告訴他任何事情!$B$B他們根本是瘋了!他們拼命的召喚連他們都無法控制的惡魔力量!$B$B他們使用特別的裝置使靈魂碎裂，讓他們的召喚，更具威力。你必須去偷這些裝置!$B$B我很想加入你，但是我得先回撒塔斯城去回報陰鬱城間諜首領。', '偷取5個靈魂儀器並把它們運送給撒塔斯城裡露臺的間諜首領麥莉莎·陽冠。', '', '去撒塔斯城找聖光廣場的間諜女王梅麗薩·海克隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10092 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10092, 'zhTW', '襲擊黑色祭壇', '有了莫阿格工程師的技術和數也數不清的甘納格爪牙，在我們將訊息通知奧格瑪之前他們就能大量地製造出惡魔劫奪者。$B$B除了儘快地剷除他們我們別無選擇。我不能調派索爾瑪駐軍去幫助你，那樣的話我們易失於防守而遭到攻擊的。$B$B還有許多在等待機會的敵人，聯盟仍在盼望著向我們疏於防範的前哨發起猛攻。千萬不要失敗，$N。一切都靠你了。', '殺掉煉冶場:黑暗祭壇的黑夜領主瑪法斯，然後回到劫奪者荒野找霸主殘拳。', '', '去地獄火半島找機甲殘骸的大督軍霍恩·重拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10093 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10093, 'zhTW', '特爾哈曼神廟', '很幸運地，光榮之路不是我的人民進入這些島嶼的唯一路途。往西方去，少數幾個我們的聖所倖存著，雖然其他一些已經被侵犯了。$B$B當費倫在準備前往艾澤拉斯的旅途時，我們其中一些人可以在我們的聖地繼續尋找重建的地方。$B$B在地獄火半島的西方，你可以在特爾哈曼神廟找到一小群德萊尼，由『智者』阿曼領導。我相信他會有興趣與你見面的。', '與地獄火半島西邊特爾哈曼神廟的『智者』阿曼談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10094 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10094, 'zhTW', '血之聖典', '自從暗影議會的召喚導致這個曾經繁華的城市爆炸，並形成現今的白骨荒野已經兩年了，$B$B如今他們以一股無法置信的強大力量在內戰著。$B$B$n，你必須進入暗影迷宮找出他們在對抗的是什麼，分辨是否會對我們造成威脅。我們的間諜提到他們使用一本邪惡的召喚禁書，只知道叫血之聖典。$B$B從這本書的內容中找出你要得答案來。', '閱讀奧齊頓的暗影迷宮裡的血之聖典。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10095 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10095, 'zhTW', '進入迷宮的中心', '暗影議會對兩年前召喚的強大生物失去控制了!這就是導致奧齊頓爆炸，而日後白骨荒野形成的原因。$B$B只知道叫做莫爾墨，他威脅打敗暗影議會並獲得自由來到外面的世界!$B$B隨著大師之後，其他的領導者紛紛死亡，你是目前外域裡對抗這怪物的最後希望了!$B$B$n，你知道你及你的同伴們內心是不怕失敗的!', '殺掉莫爾墨後回到撒塔斯城的聖光露臺並且向間諜首領麥莉莎·陽冠回報暗影迷宮裡頭發生的事件。', '', '去撒塔斯城找聖光廣場的間諜女王梅麗薩·海克隆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10096 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10096, 'zhTW', '拯救斯柏路克', '伊奇言告訴過我他在那些洞穴中發生的事而我覺得這真是太糟糕了!$B$B你知道的，也許我們的做點什麼幫助那些可憐的斯柏路克。伊奇言說他們住在方格洞穴，但最近被那些沼澤怪物們入侵了。$B$B你怎麼不去那邊看看是否你可以將一些沼澤怪物趕走呢?就在西南邊那邊。', '殺掉10隻沼澤挖掘者及10隻沼澤潛伏者，完成後回到贊格沼澤找塞納里奧避難所的羅安娜·薩威爾。', '', '去贊加沼澤找塞納里奧庇護所的勞蘭娜·薩維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10097 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10097, 'zhTW', '兄弟鬩牆', '塞司克在奧齊頓爆炸時以極大的聲響離開了司凱堤斯。當然這一定是我們大師到來的預兆。$B$B我的兄弟，希斯，是領導者的其中一員並告訴我們有義務進入神廟廢墟去晉見我們的神。$B$B在我們開始居住在廢墟中，那個稱作塞司克大廳的地方後，我開始懷疑我兄弟及他的同伴，伊奇斯。$B$B慢慢地，希斯將我逐出大廳，但他拒絕讓我帶走我的姐妹拉卡。你能幫我救出她來嗎?', '殺掉塞司克大廳的暗法師希斯，之後釋放拉卡自由。完成拯救後回到塞司克大廳外找伊斯法。', '', '去泰羅卡森林找白骨荒野的伊斯法爾。', '', '解救拉卡', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10098 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10098, 'zhTW', '泰洛克的遺產', '我的人民以一位名叫泰洛克的先祖英雄為榮。幼年阿拉卡以聽他的功績及他漂亮穿著的描述為樂。$B$B他在我的人民之中已經存在了幾百年，但有天卻神秘地消失，只留下他的面具，矛，和著作。$B$B這些遺物被阿拉卡珍藏著，但他們很難過塞司克在與司凱堤斯分裂時把這些物品帶走了。$B$B我現在知道塞司克所做的事是錯的了而且必須把這些遺物交還回去。', '將泰洛克面罩，泰洛克羽毛，及泰洛克的傳說交給塞司克大廳外的伊斯法。', '', '去泰羅卡森林找白骨荒野的伊斯法爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10099 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10099, 'zhTW', '幕後的黑手', '那些邪惡的甘納格持續的跑進去礦坑!你每殺掉一個，就會有兩個或三個更多的跑出來取代!$B$B一定有人在那最接近礦脈的地方指示著這些入侵行動。上次看來你似乎很成功的抵擋了他們，而聖光知道你是唯一勇敢到能夠再回到礦坑裡冒險的人。找出是誰負責這些騷動並且要他付出代價!', '找出及殺掉榮譽堡底下礦坑裡的希卡洛，完成後回報給工頭比干莫斯。', '', '去地獄火半島找榮耀堡礦洞的工頭比格姆斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10100 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10100, 'zhTW', '幕後的黑手', '不要誤會我的意思，$N，我當然會很高興有你來幫助我們解決礦井的問題，但是你每殺掉一個隧道礦工，馬上會有成雙成倍的出現在你面前。$B$B我已經向警備隊長克朗克說過了，但是他仍然拒絕向我提供任何幫助。他一直在暗自抱怨地獄野豬。如果我能肯定他不會打我的話，我一定會告訴他已經沒有時間再去想這個微不足道的事了！$B$B不管怎樣，看上去已經有人進駐到礦井中去指揮所有的事情了。把他找出來，殺掉他！', '找到索爾瑪礦井中的烏爾卡斯，殺掉他。然後返回向工頭拉澤克拉茲覆命。', '', '去地獄火半島找索爾瑪的工頭拉澤克拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10101, 'zhTW', '當靈魂們說話時', '歐夏剛 - 鑽石山 - 對我們來說曾經那麼神聖。那裡曾是我們氏族每年收集慶祝春天節慶的地方。那裡曾是我們薩滿與光榮的先祖之靈交談的地方。那裡曾是我們文化的中心 - 直到那些暗影打敗我們。當氏族轉化成部落，這些歐夏剛的靈魂沉默了。先祖們背過身不再看顧我們。$B$B現在有某種事物將他們從平靜中喚醒了。到歐夏剛去探險並找出是什麼在打擾這些靈魂們。', '納葛蘭的先祖之地的卡修爾母親要你去找出擁有的幻象。去找歐夏剛的庫爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10102, 'zhTW', '秘密的揭露', '我的能量在過去幾個世紀中不斷的流失，在這段期間我所在的地方有一個虛無緩慢的成長-吞噬附近的靈魂。無可奈何的，我眼睜睜看著歷代獸人的靈魂被吸入這場漩渦中。最近，我的敵人控制了這個漩渦並用來吸引無數的虛無爪牙加入燃燒軍團。$B$B現在，終結這場循環及釋放這些獸人靈魂的關鍵就是另一個那魯 - 阿達歐。我感應到她的本體就在泰洛卡森林裡撒塔斯的先祖之城裡。', '和撒塔斯城裡的阿達歐談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10103 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10103, 'zhTW', '報告祖瑞伊', '隨著戰場元帥洛摩斯和他的軍隊到來，聯盟及他們的德萊尼朋友們日漸茁壯。他們將這到撒塔斯的每一個古老的德萊尼廢墟都進入備戰狀況。$B$B為了響應，食人妖在贊格沼澤的東部建立了一個新的崗哨，就在死亡污泥的南方。斯溫派特崗哨，他們這樣稱呼。我很開心他們在這樣的地方生活還擁有這種幽默感，因為我可一點都不欣賞。$B$B這個崗哨的指揮官要求我派一些多餘的人手過去。', '回報贊格沼澤的伊斯溫派特崗哨裡的祖瑞伊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10104 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10104, 'zhTW', '與杜瑞有關', '這些杜瑞的謠言都未經證實。有些人說這個城鎮的廢墟是被瘋狂的破碎者及失落者所侵略的，而投機的手工藝品獵人則是偷取德萊尼的聖物。$B$B很難去分別哪個是真哪個是假，但是我們有責任盡我們所能去保衛廢墟。到泰洛卡森林的艾蘭里堡壘找安達爾歐。他是魔法聖物的學生之類的。比起其他人來說，他比較有可能知道那裡發生了什麼事。', '與泰洛卡森林裡艾蘭里堡壘的安達爾歐談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10105 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10105, 'zhTW', '給瑞克利亞的消息', '如今斯溫派特崗哨已經完工了，我們對於道路的進出控管比較有辦法了。而我們在泰洛卡森林的存在比較不安全了。即使如此，在碎石堡，瑞克利亞等著我們的進度報告。$B$B她機警又能幹，$n，但小心她的周圍。她沿路上有很多容易搬動的貨品，但別認為她衷心的對我們有興趣。瑞克利亞只去她認為有利可圖的地方。', '與泰洛卡森林裡碎石堡的瑞克利亞談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10106 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10106, 'zhTW', '地獄火防禦堡壘', '地獄火堡壘與我們持續交戰著。我們堅守到現在，卻還是無法對他們發動一場真正的攻擊。為了這樣，我們需要將集結待命區域往前移。$B$B我們的斥候發現在地獄火堡壘附近有三道防禦點。我們需要你去幫忙保衛這些堡壘。每占領一座堡壘，就來跟我回報。$B$B願好運在戰鬥時照耀著你，$n，祝福你能確實快速的擊敗部落軍隊以贏得這些同樣的防禦堡壘。', '占領望海崖，競技場和破碎之丘，完成後回到地獄火半島的榮譽堡找士官長崔西·波特威歐。', '', '去地獄火半島找榮耀堡的委任官翠希·普羅維爾。', '佔領瞭望臺', '佔領競賽場', '佔領碎石嶺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10107 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10107, 'zhTW', '外交的衡量', '科伊瑞斯傳來有關石拳領導者的消息:他是個獸人!一個在我們父親那年代通過黑暗之門的古老獸人並且在那之後就回到他的家鄉了。我希望你去擊敗這個獸人並試著說服他撤回這些石拳巨魔。他就住在東南方接近泰洛卡森林邊緣的燃燒之劍廢墟上面的平臺。祝你好運，$n!$B$B小心點，他可是個劍刃高手……', '納葛蘭裡卡拉達爾的喬林·亡眼要你去燃燒之劍廢墟尋找『劍刃』蘭崔索並與他談談。', '聆聽劍聖的故事', '去納格蘭找火刃廢墟的蘭特瑞索·火刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10108 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10108, 'zhTW', '外交的衡量', '這個女獵人的密探送了一則石拳領導者的消息來:他是個獸人!一個在我們父親那年代通過黑暗之門的古老獸人並且在那之後就回到他的家鄉了。我希望你能去擊敗這個獸人並試著說服他撤回這些石拳巨魔。他就住在東邊的燃燒之劍廢墟上面的平臺上。祝你好運，$n!$B$B小心點，他可是個劍刃高手……', '納葛蘭裡泰拉的『破壞者』哞哞爾要你去燃燒之劍廢墟尋找『劍刃』蘭崔索並與他談談。', '聆聽劍聖的故事', '去納格蘭找火刃廢墟的蘭特瑞索·火刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10109 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10109, 'zhTW', '我一定要擁有它們!', '你看到它們了嗎??我向加茲魯維嚇死人的口臭發誓，我將擁有那些蛋!嗯，你看起來像是能給我一些幫忙。$B$B我告訴你怎麼來著，$r;如果你幫我收集一些東西讓我的彈跳裝置4000能夠起作用，我就會給你一把鑰匙讓你能好好運作這個裝置!你說你能用彈跳裝置4000來幹嘛?你所不能做的就是變成它……$B$B我需要從納葛蘭的空氣元素身上的空氣元素氣體。他們到處都是所以不要問我到哪可以找他們!', '南納葛蘭上從氏族守望來的瓦薩特要你帶給它3個空氣元素氣體。', '', '去找納格蘭的瓦薩特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10110 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10110, 'zhTW', '地獄火防禦堡壘', '必須將地獄火堡壘的魔獄獸人趕出我們的土地!去攻擊他們，我們得先守住堡壘附近的前方防線。$B$B我們的前鋒發現有三個防禦堡壘符合這個需求，但聯盟也有同樣的想法而且已經派遣軍隊前去佔領它們了!$B$B我們要你去阻止聯盟並且佔領這些堡壘。支援佔領每一個堡壘並於完成後回來找我。$B$B為了部落!', '佔領望海崖，競技場和破碎之丘，完成後回到索爾瑪找戰場咆嘯者黑眼。', '', '去地獄火半島找索爾瑪的傳令官布萊肯·黑眼。', '佔領瞭望臺', '佔領競賽場', '佔領碎石嶺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10111 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10111, 'zhTW', '我要蛋!', '既然有人介紹你來找我，我要你幫我把蛋拿來!試著用彈跳裝置4000降落在鳥巢的正中心。但是要小心!跳的不好的話可是會造成身體傷害或者永久的傷殘喔。', '納葛蘭的瓦薩特要你用彈跳裝置4000偷取鄰近樹上的鳥巢並且取得未孵化的蛋。', '', '去找納格蘭的瓦薩特。', '嘗試偷取鳥蛋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10112 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10112, 'zhTW', '個人的喜好', '嗯?你提到一個箱子嗎?還是好幾個?你知道箱子的材質是什麼做成的嗎?$B$B還有這個商人的名字叫什麼?安普爾?你確定他是破碎者的一員嗎?我沒有與他們那一族有過幾次交易。$B$B也許你幫我個忙我就會喚起我的回憶?$B$B空行者阿拉卡 - 古老的投擲者 - 最近偷了我大量的進口貨物。我要全部都拿回來!$B$B你可以在撒塔斯城的南方找到迷霧斯奇司。', '取得5個拉斯蕊被偷的貨物。將它們送回撒塔斯城的陰鬱城，交給接近世界的盡頭小酒館的風之貿易者拉斯蕊。', '', '去撒塔斯城找貧民窟的星界商人拉斯萊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10113 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10113, 'zhTW', '奈辛瓦里狩獵隊', '「出去替我們找一些補給品，」他這樣說。在我找到這地方前我差點死了快15次!這些破碎者也許不是最好客的傢伙但至少他們沒試著要把我皮肉分離掉。$B$B不管怎樣，我不準備回去了。我大獵殺的歲月已經結束了。如果你往東北方朝贊格沼澤去並且到了奈辛瓦里狩獵隊，跟他們說『獵槍』退出了，$B$B嘿，也許你可以取代我喔!祝你好運，陌生人。', '『獵槍』瓊斯要你到納葛蘭東北方的郊區與奈辛瓦里狩獵隊的赫米特·奈辛瓦里談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10114 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10114, 'zhTW', '奈辛瓦里狩獵隊', '這些獸人之前從來沒有看過一隻牛頭人 - 要是你肯相信像這種事的話。如果不是為了隊長卡洛克汗，他們可能現在已經把我當他們下一頓的餐點給吃了。$B$B喔我的禮貌到哪了呢?我是歐洛恩·遠行者，不凡的獵人!我是從艾澤拉斯到這找尋大獵物的奈辛瓦里遠征隊營地的一員。要是你對狩獵有興趣，也許你應該來參觀我們在奈辛瓦里狩獵隊的營地，在這裡的正東方接近贊格沼澤的邊界。', '歐洛恩·遠行者要你到納葛蘭的奈辛瓦里狩獵隊跟薩杜費茲遠行者談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10115 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10115, 'zhTW', '匕首沼地的異常', '卡爾奈及德萊尼不是一直都看對方很順眼，特別是在對失落者的相關議題上。我很樂意幫忙來找我們的失落者，但我們不會追捕他們。一些德萊尼則堅持要\'救贖\'他們。$B$B不過，有段時間有些失落者發展過頭了，就像匕首沼地失落者。在西邊他們的村落，他們涉獵了毒藥及騙術，在我們看來這是違反自然的行為。$B$B我們必須在這些邪惡的匕首沼地失落者擴大他們的影響力前解決掉這些狀況。', '殺掉3個匕首沼地刺客及15個匕首沼地污泥居者。', '', '去贊加沼澤找奧雷柏爾營地的伊庫提。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10116 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10116, 'zhTW', '懸賞:姆瑪奇酋長', '懸賞:姆瑪奇酋長 - 匕首沼地這個邪惡及墮落失落者部族的領導者，因為他對奧雷伯爾港的殘暴攻擊。$B$B這個酋長及他一整隊的刺客要為許多卡爾奈及德萊尼的死負責並且只有由經驗豐富的戰士才有辦法對付他。$B$B建議旅客全部避開匕首沼地村週遭區域到奧雷伯爾港的西邊。$B$B如要換取獎賞，將酋長死亡的證據交給伊庫堤。', '將姆瑪奇酋長圖騰交給奧雷伯爾港的伊庫堤。', '', '去贊加沼澤找奧雷柏爾營地的伊庫提。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10117 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10117, 'zhTW', '懸賞:姆瑪奇酋長', '懸賞:姆瑪奇酋長 - 匕首沼地這個邪惡及墮落失落者部族的領導者，因為他對薩布拉金所發動的殘暴攻擊。$B$B這個酋長及他一整隊的刺客要為許多斥候及傳令員的死負責並且只有由經驗豐富的戰士才有辦法對付他。$B$B建議旅客全部避開匕首沼地村週遭區域到薩布拉金的西北方。$B$B如要領取獎賞，將酋長死亡的證據交給暗影獵人丹傑。', '將姆瑪奇酋長圖騰交給暗影獵人丹傑。', '', '去贊加沼澤找薩布拉金的暗影獵手德恩加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10118 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10118, 'zhTW', '給匕首沼地的訊息', '在所有贊格沼澤裡的失落者部族中，匕首沼地是最奸詐及激進的部族。他們有著完善的組織且不隱瞞他們想要控制其他沼澤中的失落者的欲望。$B$B他們的攻擊已經造成我的斥候及傳令員大量的傷亡。我不能承受再失去任何一員了。$B$B如果我們不盡快展開行動，他們將會徹底的控制所有的道路而薩布拉金將被包圍。', '殺掉3個匕首沼地刺客及15個匕首沼地污泥居者並於完成後回到薩布拉金找暗影獵人丹傑。', '', '去贊加沼澤找薩布拉金的暗影獵手德恩加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10119 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10119, 'zhTW', '通過黑暗之門', '20年來黑暗之門一直都是個沉靜的遺跡 - 讚頌著一段被遺忘的時光。$B$B<勒松看了看週遭。>$B$B我從沒想過還會今日，在這裡調查這個深淵。$B$B這道門的另一邊我們正陷入苦戰 - 一場沒有援助就無法勝利的戰爭。你必須穿過黑暗之門去幫助我們的軍隊，$c。$B$B馬上去向指揮官杜朗報到。他在外域等著你……', '通過黑暗之門找到指揮官杜朗。他在另一邊等你 - 就在外域裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10120 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10120, 'zhTW', '抵達外域', '藉由聯盟的幫忙，我的獸人們得以守住這裡的防線，但我需要你幫我把報告送回去給索爾瑪的克洛克爾克將軍。有他的幫忙，我們就能夠把這些惡魔趕回那個孕育他們的深淵去!與後面平臺上的法拉格·伏瑞菲德談談。她會幫助你的。', '地獄火半島上黑暗之門的歐萊恩中將要你將歐萊恩的報告交給法拉格·伏瑞菲德。', '', '去地獄火半島找命運階梯的維拉加·亂羽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10121, 'zhTW', '徹底消滅燃燒軍團', '雖然這個地方充滿著陌生的新敵人，燃燒軍團依舊還是我們遠征軍的最大威脅。一位我們最信任的士兵，碎顱中士，研究過軍團的戰略 - 試著去了解這些惡魔真正的目的。到南邊的城牆外的補給營地找到他。$B$B還有 $n - 小心軍團。不要低估他們的邪惡。', '到索爾瑪城外東邊的補給營地找碎顱中士談談。', '', '去地獄火半島找補給車隊的斯古爾·碎顱者中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10122, 'zhTW', '堡壘的外圍', '每天，地獄火堡壘都會開啟它的大門，無數的邪獸人會在此時湧出那個巨大的堡壘，如洪流一般分佈到沿著要塞的南側城牆周圍所設立的各個營地去。$B$B我已經派了一名最優秀的偵察人員列兵伊瑪裡恩去偵察這些邪獸人的活動狀況、裝備情況和數量分佈等等情報。但是，他至今還沒有向我發回任何報告或是其它什麼資訊。$B$B伊瑪裡恩應該主要是在南部城牆最北側營地一帶，也就是靠近地獄火堡壘的地方進行偵察。找到他，$N。若是沒有他帶回來的訊息，我們就只能坐以待斃。', '轉至南部城牆外最北側的營地尋找列兵伊瑪裡恩的下落。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10123, 'zhTW', '魔焰深谷', '毀滅領主卡札克統馭著外域裡的燃燒軍團。既然我們捉不到卡札克 - 總有一天會的 - 我們就得抓到指揮陸地上軍團軍隊的副官。$B$B他們已經在魔焰深谷部署了恐懼領主，就在這裡的東邊。他們負責製造這些狂暴的暴風雨下在我們身上。把他們及他們的爪牙趕出去會是對燃燒軍團一個很大的打擊。', '地獄火半島索爾瑪東邊補給商隊的碎顱中士要你殺掉4個烈焰行者小鬼，6個地獄火戰爭使者及1個恐懼呼喚者。', '', '去地獄火半島找補給車隊的斯古爾·碎顱者中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10124, 'zhTW', '前方據點:搶奪者荒野', '你英勇的戰鬥受到極度的肯定，$c。他們派你到前線去與殘拳的部下會面。他們是激進份子，全心為了徹底消滅燃燒軍團而奉獻，因此你們可能會很合得來……$B$B朝東方大概200步的距離在群起突出的陸地處轉向南方。你會看到搶奪者荒野這個用來停留的老農地。一到那裡，就找前線指揮官吐阿奇報到。$B$B現在馬上啟身!', '向搶奪者荒野的前線指揮官吐阿奇報到。', '', '去地獄火半島找機甲殘骸的前線指揮官托爾克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10125, 'zhTW', '任務:中斷聯絡', '這裡東邊不遠的地方就是軍團前線。軍團前線可以說是燃燒軍團在這裡設立的一個移動司令中心。只要走近，你就能看見那裡四處嶙立著的軍團天線。燃燒軍團的士兵就是使用這些東西與外域的其它營地聯絡的。它們同時也是遮蔽一切外來魔法干擾和監聽的屏障，使軍團的通訊安全得到了保障。$B$B我要求你立刻帶上這些爆炸物去摧毀那些天線。一定要全部清除，$N。軍團前線南部和北部的邊界上都安裝了這種裝置。', '地獄火半島上劫奪者荒野的前線指揮官吐阿奇要你使用吐阿奇的爆裂物摧毀軍團天線:洩憤、軍團天線:狂怒、軍團天線:仇恨以及軍團天線:恐懼。', '', '去地獄火半島找機甲殘骸的前線指揮官托爾克。', '摧毀軍團感應器：敵意', '摧毀軍團感應器：狂亂', '摧毀軍團感應器：仇恨', '摧毀軍團感應器：畏懼', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10126, 'zhTW', '指揮官奈克羅格的命令', '這些命令是由指揮官奈克羅格下達的，他命令營地中的邪獸人巡邏兵將這個人類囚犯帶到南邊去進行審訊。$B$B阿曼蒂中尉曾說過，南部城牆附近到處都有邪獸人的營地，因此他們將列兵伊瑪裡恩帶到南部城牆附近的任何一個營地之中都是有可能的。$B$B此外，從信中提到的審訊來看，捕捉到他的邪獸人一定認為暫時留著他的性命會有什麼好處。因此，你最好趁這他們還沒有改變主意之前，趕緊找到列兵伊瑪裡恩的下落。', '沿著南部城牆的西側往南搜尋，在下一個營地中尋找列兵伊瑪裡恩的下落。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10127, 'zhTW', '任務:切斷聯絡', '要是我沒有讓你去清除掉東邊軍團前線裡的那些惡魔的話，那我可就真該被判成翫忽職守罪了。$B$B燃燒軍團在兩側的前線都佈置了同樣的防禦體系：惡魔劫奪者輪班守備各軍團駐營地，而憤怒守衛則在各營地之間巡邏，而一名希樊征服者則負責監視整個防禦體系。去把他們都殺光，讓卡扎克好好頭疼一番去吧。$B$B噢，對了，小心外圍的惡魔劫奪者。我知道你很厲害，但碰上這些東西會耽誤上你不少的時間。', '地獄火半島上劫奪者荒野的前線指揮官吐阿奇要你殺掉4個惡魔處理者，8個憤怒守衛，以及征服者薛艾希。', '', '去地獄火半島找機甲殘骸的前線指揮官托爾克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10128, 'zhTW', '拯救大兵伊瑪裡恩', '伊瑪裡恩散落著的裝備和物品略略向南方擴展了幾十碼，這大致上顯示出他似乎是被帶去了南部城牆正南方的某處。而從地面上淺而凌亂的車輪印跡看得出，押解伊瑪裡恩的那些邪獸人都沒來得及帶走什麼東西，走得十分匆忙。這是為什麼呢？$B$B難道是有人在那邊等著審訊他？難道就是指揮官奈克羅格，你在信中瞭解到的那個應該駐紮在最北邊的邪獸人首領？$B$B總之，這面盾牌，以及這些車輪印跡給你帶來了更多的疑問，但無論如何，你已經大致知道列兵伊瑪裡恩在什麼地方了，說不定你還可以在那裡找到指揮官奈克羅格。', '沿著南部城牆繼續往南前進，找到指揮官奈克羅格囚禁列兵伊瑪裡恩的地方。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10129, 'zhTW', '任務:墨奇斯以及夏德拉茲入口', '我們已經找出燃燒軍團用來傳送增援部隊的兩個主要傳送器:墨奇斯入口和夏德拉茲入口。$B$B假如你往東方的光榮之路看上去，你將看見它們設置在道路的兩旁。我想要你把這兩個傳送器炸成歷史!$B$B這裡是你將使用的炸彈，由一個52區的地精特別設計的。現在你可以去跟空軍指揮布拉克談話 - 他將讓你騎乘雙足翼龍。', '與空軍指揮布拉克談談，炸掉墨奇斯入口以及夏德拉茲入口，完成後回到搶奪者荒野找前線指揮官吐阿奇。', '', '去地獄火半島找機甲殘骸的前線指揮官托爾克。', '摧毀穆爾凱斯之門', '摧毀沙德拉茲之門', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10130, 'zhTW', '西側的威脅', '除了其它指示之外，命令書中還提到要讓邪獸人們準備好武器和裝備，隨時準備發動下一次進攻。$B$B依照這份計劃，指揮官奈克羅格的軍隊將從西邊進攻榮耀堡，與東邊的軍隊形成一個鉗形攻擊戰略。$B$B而當榮耀堡的主要軍力都集中在東部城牆的時候，來自西邊的襲擊將是極具殺傷力的。只有讓西邊的軍隊無法發起襲擊，榮耀堡才有希望逃脫危險。', '殺死10名碎手衛兵、10名碎手狂戰士和5名碎手侍僧，然後向榮耀堡西部哨塔的阿曼蒂中尉報到。', '', '去地獄火半島找榮耀堡西部哨塔的阿曼蒂中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10131 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10131, 'zhTW', '逃脫計劃', '就像我說的那樣，要想從這裡逃出去不是件容易的事情。指揮官奈克羅格雖然看上去像是個只有一身蠻力的傢伙，但實際上他一點也不笨。$B$B事實上，牢房的鑰匙一直都在他身上，從沒有離開過他的視線之外。而且，他根本不會輕易從塔頂上下來，除非準備審訊我或者另外一個獸人俘虜。$B$B總之，想讓他從塔頂上下來得花費點工夫，不過，我已經有個辦法了。找個在南部城牆邊巡邏的士兵，把他身上的炸藥給我帶回來。', '殺死一名碎手擲彈兵，將他攜帶的劣質炸彈交給高加茲前哨的列兵伊瑪裡恩。', '', '去地獄火半島找高加茲前哨的列兵伊瑪裡恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10132 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10132, 'zhTW', '巨大威脅', '你看的見北方那顆巨大的紅色水晶嗎?它不久前從天空上掉下來，引起一場巨大的地震。$B$B當我們前去調查這場騷動時，我們發現該處多了許多原本不存在的戈羅西四處徘徊。$B$B對於那水晶和它散發的能量，很明顯的有些怪事正在發生，但是我沒有時間關心那件事。那些山巨人才是我的當務之急。$B$B我要你招募幾名隊友一同前往墜天山脈解決他們。', '殺掉5個狂怒的巨像，完成後回到地獄火半島的塞納里奧前哨找塔拉希恩。', '', '去地獄火半島找塞納里奧哨站的圖拉希恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10133 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10133, 'zhTW', '任務:殺死信差', '你的行動已經開始令軍團感到不安了，$N。我的斥候剛剛通知我說，軍團被迫重新開始利用信使來傳遞信件，完成通訊。這下我們就有了將他們徹底剷除出這片大陸的機會！$B$B接下來我要你做的事，要求你擁有遠遠超出一般的士兵的機敏和戰力。$B$B軍團的信使當前往返於北方的阿苟納之池與鑄魔營地：暴虐之間。你必須在鑄魔營地：暴虐外截住並幹掉他，並帶著他身上的Legion missive回來見我。', '地獄火半島劫奪者荒野的前線指揮官吐阿奇要你殺死阿瑞克斯瑪裡達許並且取回軍團公文。', '', '去地獄火半島找機甲殘骸的前線指揮官托爾克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10134 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10134, 'zhTW', '赤紅水晶線索', '當戈羅西在你的攻擊之下倒下，你第一次注意到它的手中握著一個深紅水晶碎片。$B$B儘管深紅水晶碎片相形之下在山岳巨人手中是如此的渺小而且不引人注意，對你來說，卻是一塊相當重的碎片。它看起來疑似是在山脊中間的一塊巨大水晶。$B$B這塊碎片明顯的可以為這裡正在進行的怪事提供一條線索，並且你確信在南方塞納里奧前哨的德魯伊想要看看它。', '將赤紅水晶裂片送到地獄火半島的塞納里奧前哨給塔拉希恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10135 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10135, 'zhTW', '任務:充當信差', '我僅僅是一名前線的戰地指揮官，$c。對於這樣重要的情報，我們該採取什麼樣的行動……，決定許可權只能屬於我們的領袖納茲格雷爾大人。你必須馬上把這些信件帶到索爾瑪呈現給他。士兵，搭乘雙足飛龍吧，願你一路上不會受到任何阻礙！', '將軍團公文帶給地獄火半島上索爾瑪的納茲格雷爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10136, 'zhTW', '殘忍的目的', '博學者血鷹終於解讀了之前你找到的公文密函。密函的內容原來是卡札克領主的其中一名手下-殘忍的阿拉薩爾斯所寫的。很顯然的，阿拉薩爾斯是燃燒軍團在地獄火半島的陸軍總指揮。現在他們要撤銷他的指揮權，$n。因為其他人對他的極端偏見而解除他的指揮權。$B$B到西邊的阿葛納爾之池然後解決這個所謂的『燃燒軍團指揮官』。今天，就是我們部落奪回地獄火半島的時候了。叫那些燃燒軍團去死吧。', '殺死殘忍的阿拉薩爾斯，再回索爾瑪找納茲格雷爾。', '', '去地獄火半島找索爾瑪的納茲格雷爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10137 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10137, 'zhTW', '挑釁指揮官', '計劃是成功還是失敗，就全靠這些炸彈了……$B$B儘管我非常討厭使用獸人制造的東西，但現在這可能是我活著逃出去的唯一機會。帶上這個，將它扔向塔上懸掛著的旗幟。$B$B聽到爆炸的聲音之後，指揮官奈克羅格一定會從塔頂上走下來調查原因，尋找是誰在搗亂。你就要趁這個機會殺掉他，並且拿到鑰匙，然後回來幫我把牢房的門開啟。祝你好運，$N。', '引爆劣質炸彈製造混亂，誘使指揮官奈克羅格離開哨塔。從他手中奪得奈克羅格的鑰匙，開啟囚禁列兵伊瑪裡恩的牢籠。救出列兵伊瑪裡恩之後向阿曼蒂中尉覆命。', '', '去地獄火半島找榮耀堡的阿曼蒂中尉。', '', '', '營救大兵伊瑪裡恩', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10138 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10138, 'zhTW', '誰的命令？', '現在，$N，至少有一件事已經明確了，那就是：我們不能讓狀況繼續惡化下去。邪獸人數量增長的速度與我們消滅他們的速度幾乎一樣快，現在幾乎已經將我們包圍了。如果只是這樣躲在榮耀堡的城牆之後，整天算著日子，等待邪獸人或是燃燒軍團過來把我們完全殺光的話，我們是無法贏得這場戰爭的。$B$B你最近表現得非常出色，已經使我們避免了多次邪獸人兇殘的進犯，但是，這還不夠，你現在必須想辦法攻進榮耀之路，並找出在幕後策劃了這幾次襲擊的那個幕後黑手。', '殺死20名碎手步兵和10名碎手術士，並奪得教官祖羅克的命令，然後向榮耀堡西部哨塔的阿曼蒂中尉覆命。', '', '去地獄火半島找榮耀堡西部哨塔的阿曼蒂中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10139 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10139, 'zhTW', '刺殺指揮官', '根據我當前所掌握的情報，教官祖羅克應該是為地獄火半島上所有邪獸人首領指揮官戈拉克斯效力的，是他的心腹，他的左右臂膀。$B$B這個戈拉克斯明顯不是個典型的邪獸人蠻夷，儘管他是我們的敵人，我仍不得不佩服他，是他讓我們在如此長的時間內都被迫陷入被動的境地。$B$B祖羅克的命令書中顯示出戈拉克斯的指揮部位於榮耀之路末端，靠近要塞城牆與北部城牆相接的地方，你要立刻去刺殺他。不過，面對這樣一個強大的邪獸人，說不準會發生什麼事情，$N，你最好能帶些同伴一起去。', '殺死指揮官戈拉克斯，然後向榮耀堡西部哨塔的阿曼蒂中尉覆命。', '', '去地獄火半島找榮耀堡西部哨塔的阿曼蒂中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10140 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10140, 'zhTW', '榮譽堡之行', '當你準備好時，我將安排你直接飛到榮譽堡。$B$B到達之後，與治安官伊斯歐朵爾談話並且交給他杜朗的報告。他將很高興看見另一位從祖國來報到的新成員，同時我確信那報告中有重要的軍情!', '飛到榮譽堡把杜朗的報告送給治安官伊斯歐朵爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10141, 'zhTW', '燃燒軍團捲土重來', '當燃燒軍團侵略艾澤拉斯的同時，他們也在進行著他們的恐怖活動，就在外域。多年來我們一直持續追蹤他們的活動，但是他們最近的這個行動，$c-我該怎麼說呢，是我們前所未見的。$B$B去東方補給商隊的附近尋找阿圖瑪斯中士。她一直在監控那些入侵者而且可能知道他們的意圖所在。$B$B你的動作要快-保重了，$n-燃燒軍團的危險性可是不容忽視的。', '到東方去與榮譽堡外東部補給營地的阿圖瑪斯中士談談。', '', '去地獄火半島找東補給車隊的沃圖姆斯中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10142, 'zhTW', '苦痛之路', '毀滅領主卡札克指揮外域的燃燒軍團。我們無法接近卡札克-現在還不行-我們可以也必須接近負責指揮燃燒軍團地面部隊的副官。$B$B他們在東邊的苦痛之路部署了一些恐懼領主。就是他們製造地獄火風暴將火雨落在我們頭上的元兇。消滅它們還有它們的手下對燃燒軍團來說會是一大挫折。', '在地獄火半島榮譽堡東方的東部補給營地的阿圖瑪斯中士要你殺死4個烈焰行者小鬼，6個地獄火戰爭使者和1個恐懼呼喚者。', '', '去地獄火半島找東補給車隊的沃圖姆斯中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10143, 'zhTW', '遠征隊哨塔', '指揮高層已經注意到你的英勇戰績，$c。他們想要派你到前線去與洛哈瑪斯的部隊會合。他們是主張徹底消滅燃燒軍團的激進派，因此你正適合那裡……$B$B往東方走大約400步，穿過白骨之谷，直到你碰到一部毀壞的惡魔搶奪者。你將看見遠征隊哨塔，那裡曾經是燃燒軍團的基地。到達之後，向前線指揮官金斯頓報到。$B$B馬上出發!', '向遠征隊哨塔的前線指揮官金斯頓回報。', '', '去地獄火半島找遠征軍崗哨的前線指揮官金斯頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10144, 'zhTW', '阻斷他們的援軍', '你會在東北方找到軍團前線，而附近的空間就是用來集結遍佈在外域的援軍傳送門。$n，我們將要去摧毀那些傳送門!$B$B拿著這個雷管。它是由52區所設計的，使用惡魔本身的力量成為一種爆炸裝置!殺死格瑞之門和卡雷茲之門附近的軍團部隊以收集惡魔符文石，在傳送門內使用雷管引爆符文石……然後觀賞煙火大會吧!!$B$B去吧，$n，任務完成時向我回報。', '殺掉格瑞之門和卡雷茲之門附近的敵人取得惡魔符文石。在格瑞之門和卡雷茲之門內使用金斯頓的書冊。帶著剩下的爆裂物回去找前線指揮官金斯頓。', '', '去地獄火半島找遠征軍崗哨的前線指揮官金斯頓。', '破壞格雷姆傳送門', '破壞凱勒茲傳送門', '摧毀軍團感應器：湮滅', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10145, 'zhTW', '任務:切斷聯絡', '假如我沒命令你殺死駐紮於基地東方軍團前線的惡魔們，這將是疏忽職守。$B$B軍團前線兩邊以相同的方式駐防:惡魔處理者在軍團兵營之間巡邏，憤怒守衛輪班保衛著兵營。一個希樊征服者監督整個營地的運作。殺死他們並且讓卡札克整治他們。$B$B留意巡邏的惡魔劫奪者。我知道你很強壯，但是那些東西會迅速解決你。', '地獄火半島上遠征隊哨塔的前線指揮官金斯頓要你殺死4個惡魔處理者，8個憤怒守衛，和征服者亞奎斯。', '', '去地獄火半島找遠征隊哨塔的前線指揮官金斯頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10146 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10146, 'zhTW', '任務:墨奇斯和夏德拉茲入口', '黑暗之門的西邊有兩個巨大的傳送器:墨奇斯入口和夏德拉茲入口。$B$B假如你從東邊的光榮之路看上去，你將看見他們在道路的兩旁。我要你把它們炸成碎片!$B$B這裡是你將使用的炸彈，它們是由一個52區的哥布林所特別設計的。現在，與空軍指揮戴畢瑞談話 - 他會派遣一隻獅鷲獸送你上路。', '與空軍指揮戴畢瑞交談，炸掉墨奇斯入口和夏德拉茲入口，然後回到遠征隊哨塔向前線指揮官金斯頓回報。', '', '去地獄火半島找遠征軍崗哨的前線指揮官金斯頓。', '摧毀穆爾凱斯之門', '摧毀沙德拉茲之門', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10147 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10147, 'zhTW', '任務:殺死信差', '你的行動已經開始令軍團感到不安了，$N。我的斥候剛剛通知我說，軍團被迫重新開始利用信使來傳遞信件，完成通訊。這下我們就有了將他們徹底剷除出這片大陸的機會！$B$B接下來我要你做的事，要求你擁有遠遠超出一般的士兵的機敏和戰力。$B$B軍團的信使當前往返於最北方的阿苟納之池與鑄魔營地：暴虐之間。你必須在鑄魔營地：暴虐外截住並幹掉他，並帶著他身上的軍團公文回來見我。', '地獄火半島上遠征軍崗哨的前線指揮官金斯頓要求你找到並殺死阿瑞克斯瑪裡達許，奪回軍團公文。', '', '去地獄火半島找遠征隊哨塔的前線指揮官金斯頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10148 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10148, 'zhTW', '任務:充當信差', '我僅僅是一名前線的戰地指揮官，$c。對於這樣重要的情報，我們該採取什麼樣的行動……，決定許可權只能屬於我們的領袖軍隊指揮官達納斯·托爾貝恩閣下。你必須馬上把這些信件帶到榮耀堡去呈現給他。士兵，去後面搭乘獅鷲吧，願你一路上不會受到任何阻礙！', '將軍團公文帶給地獄火半島上榮耀堡內的軍隊指揮官達納斯·托爾貝恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10149 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10149, 'zhTW', '任務:終結所有，戰勝所有', '假如你沒有截獲這些信件，你知道會發生什麼事情嗎，$N？<達納斯點了點頭。>$B$B是的，全地獄火半島的燃燒軍團部隊都會來敲我們榮耀堡的大門。若是真有那樣一場突襲，恐怕沒有人可以活下來。$B$B要想不讓這些命令抵達軍團前線，那只有一個辦法。你必須立刻轉至西北方的阿苟納之池，並殺死這隻阿拉薩爾斯。$B$B去吧，若是能夠成功，我會大力嘉獎你的。', '地獄火半島上榮耀堡的軍隊指揮官達納斯·托爾貝恩要你去殺掉殘忍的阿拉薩爾斯.', '', '去找地獄火半島的遠征軍指揮官達納斯·托爾貝恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10150 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10150, 'zhTW', '堡壘的外圍', '每天，地獄火堡壘都會開啟它的大門，無數的邪獸人會在此時湧出那個巨大的堡壘，如洪流一般分佈到沿著要塞的南側城牆周圍所設立的各個營地去。$B$B我已經派了一名最優秀的斥候瑪克哈去偵察這些邪獸人的活動狀況、裝備情況和數量分佈等等情報。但是，她至今還沒有向我發回任何報告或是其它什麼資訊。$B$B斥候瑪克哈應該主要是在北部城牆最北側營地一帶，也就是靠近岩石堆的地方進行偵察。找到她，$N。若是沒有她帶回來的訊息，我們就只能坐以待斃。', '轉至北部城牆最北端的營地尋找斥候瑪克哈的下落。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10151 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10151, 'zhTW', '指揮官奈克羅格的命令', '這些命令是由指揮官奈克羅格下達的，他命令營地中的邪獸人巡邏兵將這個獸人囚犯帶到南邊去進行審訊。$B$B暗影獵手塔金曾說過，北部城牆附近到處都有邪獸人的營地，因此他們將斥候瑪克哈帶到北部城牆附近的任何一個營地之中都是有可能的。$B$B此外，從信中提到的審訊來看，捕捉到她的邪獸人一定認為暫時留著她的性命會有什麼好處。因此，你最好趁這他們還沒有改變主意之前，趕緊找到斥候瑪克哈的下落。', '沿著北部城牆的西側往南搜尋，在下一個營地處尋找斥候瑪克哈的下落。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10152, 'zhTW', '西側的威脅', '除了其它指示之外，命令書中還提到要讓邪獸人們準備好武器和裝備，隨時準備發動下一次進攻。$B$B依照這份計劃，指揮官奈克羅格的軍隊將從西邊進攻索爾瑪，與東邊的軍隊形成一個鉗形攻擊戰略。$B$B而當索爾瑪的守備部隊把注意力都集中在東側的城牆時，來自西邊的襲擊將是極具殺傷力的。只有讓西邊的軍隊無法發起襲擊，索爾瑪才有希望逃脫危險。', '殺死10名碎手衛兵、10名碎手狂戰士和5名碎手侍僧，然後向塞斯高附近斷脊氏族崗哨的石頭守衛安比蘭報到。', '', '去地獄火半島找斷脊氏族崗哨的石頭守衛安比蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10153 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10153, 'zhTW', '拯救斥候瑪克哈', '瑪克哈散落著的裝備和物品略略向南方擴展了幾十碼，穿過了榮耀之路。而從地面上淺而凌亂的車輪印跡看得出，押解瑪克哈的那些邪獸人都沒來得及帶走什麼東西，走得十分匆忙。這是為什麼呢？$B$B難道是有人在那邊等著審訊她？難道就是指揮官奈克羅格，你在信中瞭解到的那個應該駐紮在最北邊的邪獸人首領？$B$B總之，這面盾牌，以及這些車輪印跡給你帶來了更多的疑問，但無論如何，你已經大致知道斥候瑪克哈在什麼地方了，說不定你還可以在那裡找到指揮官奈克羅格。', '往南穿越榮耀之路，轉至南部城牆尋找指揮官奈克羅格囚禁斥候瑪克哈的地方。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10154, 'zhTW', '逃脫計劃', '就像我說的那樣，要想從這裡逃出去不是件容易的事情。指揮官奈克羅格雖然看上去像是個只有一身蠻力的傢伙，但實際上他一點也不笨。$B$B事實上，牢房的鑰匙一直都在他身上，從沒有離開過他的視線之外。而且，他根本不會輕易從塔頂上下來，除非是要審訊我或者另外一個人類俘虜。$B$B總之，想讓他從塔頂上下來得花費點工夫，不過，我已經有個辦法了。找個在南部城牆邊巡邏的士兵，把他身上的炸藥給我帶回來。', '殺死一名碎手擲彈兵，將他攜帶的劣質炸彈交給高加茲前哨的斥候瑪克哈。', '', '去地獄火半島找高加茲前哨的斥候瑪克哈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10155 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10155, 'zhTW', '挑釁指揮官', '計劃是成功還是失敗，可就全靠這些炸彈了……$B$B儘管我非常討厭使用邪獸人制造的東西，但現在這可能是我活著逃出去的唯一機會。帶上這個，將它扔向塔上懸掛著的旗幟。$B$B聽到爆炸聲之後，指揮官奈克羅格一定會從塔頂上走下來檢視，要把搗亂的人給揪出來。你就要趁這個機會殺掉他，拿到鑰匙後馬上回來幫我把牢房的門開啟。祝你好運，$N。', '引爆劣質炸彈製造混亂，誘使指揮官奈克羅格離開哨塔。從他手中奪得奈克羅格的鑰匙，開啟囚禁斥候瑪克哈的牢籠。救出斥候瑪克哈之後向塞斯高附近斷脊氏族崗哨的石頭守衛安比蘭覆命。', '', '去地獄火半島找斷脊氏族崗哨的石頭守衛安比蘭。', '', '', '營救斥候瑪克哈', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10156 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10156, 'zhTW', '誰的命令？', '現在，$N，至少有一件事已經明確了，那就是：我們不能讓狀況繼續惡化下去。邪獸人數量增長的速度與我們消滅他們的速度幾乎一樣快，現在幾乎已經將我們包圍了。如果只是這樣躲在工事後面，整天算著日子，等待邪獸人或是燃燒軍團過來把我們完全殺光的話，我們是無法贏得這場戰爭的。$B$B你最近表現得非常出色，已經使我們避免了多次邪獸人兇殘的進犯，但是，這還不夠，你現在必須想辦法攻進榮耀之路，並找出在幕後策劃了這幾次襲擊的那個幕後黑手。', '殺死20個碎手步兵和10個碎手術士，並奪得教官祖羅克的命令，然後向斷脊氏族崗哨的石頭守衛安比蘭覆命。', '', '去地獄火半島找斷脊氏族崗哨的石頭守衛安比蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10157 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10157, 'zhTW', '刺殺指揮官', '根據我當前所掌握的情報，教官祖羅克應該是為地獄火半島上所有邪獸人首領指揮官戈拉克斯效力的，是他的心腹，他的左右臂膀。$B$B這個戈拉克斯明顯不是個典型的邪獸人蠻夷，儘管他是我們的敵人，我仍不得不佩服他，是他讓我們在如此長的時間內都被迫陷入被動的境地。$B$B祖羅克的命令書中顯示出戈拉克斯的指揮部位於榮耀之路末端，靠近要塞城牆與北部城牆相接的地方，你要立刻去刺殺他。不過，面對這樣一個強大的邪獸人，說不準會發生什麼事情，$N，你最好能帶些同伴一起去。', '殺死指揮官戈拉克斯，然後向索爾瑪的暗影獵手塔金覆命。', '', '去地獄火半島找索爾瑪的暗影獵手塔金。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10158 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10158, 'zhTW', '血環補給品', '東南邊的獸人城鎮廢墟塞斯高現在成了那些地獄火堡壘中源源不斷湧出的邪獸人的基地。$B$B因此，暗影獵手塔金把我派到這裡來，監視這處據點，以及裡面那些奇特的居民。$B$B總之，某種神秘的東西令那些邪獸人發生了變化，變得更加強大了。我們必須想辦法阻止他們繼續壯大自己的力量。現在你立刻轉至塞斯高，破壞掉那裡所有的補給品。', '摧毀6堆血環補給箱，然後向斷脊氏族崗哨的石頭守衛安比蘭覆命。', '', '去地獄火半島找斷脊氏族崗哨的石頭守衛安比蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10159 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10159, 'zhTW', '清光棘牙丘陵!', '我們一直都在清理棘牙丘陵通往西邊道路上的劫毀者以保持通道暢通。要是我們與贊格沼澤的避難所完全斷絕會變得很糟糕。$B$B我們並不想去逼迫這些生物，但似乎沒有其他的選擇尤其在他們變本加厲攻擊那些通過的旅人。$B$B要是可以的話，去解決掉那裡的一些劫毀者。', '殺死8隻棘牙劫毀者還有8隻棘牙吐毒者然後回到地獄火半島的塞納里奧前哨找馬琥藍·胖蹄。', '', '去地獄火半島找塞納里奧哨站的瑪霍拉姆·硬蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10160, 'zhTW', '了解你的敵人', '謠言指出有一支新品種的獸人正在興起。他們體型更大，更兇殘-比我們所知的獸人還要更加奸詐狡猾。假如這個謠言屬實，那麼我們在外的勢力將會面臨超過他們可負擔的壓力。$B$B我已經委託我的中尉，阿瑪迪，去調查這個謠言。假如你願意在我們遭遇困難的時刻幫助我們，就去找她吧。她駐守在要塞西邊的破塔上。$B$B還有$n-你要小心。你正步入一個危險的世界。', '到榮譽堡西方的老舊守衛塔去與阿瑪迪中尉談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10161, 'zhTW', '如果情況緊急……', '在一個緊急的事件當中，保持準頭的永遠都是主駕駛，特別是當你唯一的副駕駛吐的稀哩嘩啦的時候。$B$B好消息是我們不需要花很多天等待替換的零件進口。壞消息是〝備用〞零件四散在這裡到東方的白骨之谷之間。$B$B其他壞消息呢?備用零件不是那麼的備用。它們，呃，在我們迫降途中掉落了。你能幫助我去收集足夠的備用零件好讓我們能夠再次離開地面嗎?', '收集30個飛艇殘骸，並帶回給飛艇失事地的『驚嘆』史哥利德·幸運心。', '', '去地獄火半島找飛艇墜毀點的“尖嗓子”斯克裡·拉克希德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10162 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10162, 'zhTW', '任務:深淵沙洲', '現在你已經得到你的翼龍了，也許你想參加另一個轟炸任務?$B$B這一次我們已經孤立了燃燒軍團的主要生產地區，就在北邊煉冶場的後方。我要你騎上翼龍然後摧毀該區所有該死的傢伙!$B$B這裡是給你使用的炸彈-現在，準備好的話就去跟空軍指揮布拉克談話吧。', '地獄火半島上搶奪者荒野的前線指揮官吐阿奇已經要求你消滅20個甘納格苦工，5個莫阿格監督者和5座惡魔火砲。', '', '去地獄火半島找機甲殘骸的前線指揮官托爾克。', '', '', '摧毀邪能火炮', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10163 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10163, 'zhTW', '任務:深淵沙洲', '現在你已經得到你的飛龍了，也許你想參加另一個轟炸任務?$B$B這一次我們已經孤立了燃燒軍團的主要生產地區，就在北邊煉冶場的後方。我要你騎上飛龍然後摧毀該區所有該死的傢伙!$B$B這是你的炸彈 - 現在，準備好的話就去跟獅鷲專家風怒談談吧。', '地獄火半島上破碎崗哨的空軍指揮葛萊弗卡爾要你去殺掉20個甘納格苦工，5個莫阿格監督者和5座惡魔火砲。', '', '去地獄火半島找破碎崗哨的空軍指揮官格萊芬加爾。', '', '', '摧毀邪能火炮', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10164, 'zhTW', '一切都會很好', '你相當具有冒險精神，$n。之前你甚至已經到過奧奇奈地穴內了。$B$B我是幸運靈魂當中的一個。我跟勒威薩斯沒有關係，也不是主教瑪拉達爾邪惡巫術實驗的一部份。在你殺掉勒威薩斯後，瑪拉達爾還活著，繼續在地穴裡面折磨靈魂。$B$B我的要求很簡單的。進入奧奇奈地穴，殺掉主教瑪拉達爾，以便那些困在裡面的靈魂最後能夠安息。', '站在奧齊頓的奧奇奈地穴外的大祖父阿爾崔瑪斯要你進入奧奇奈地穴並殺掉主教瑪拉達爾。', '', '去泰羅卡森林找奧金頓的奧德里姆斯宗父。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10165 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10165, 'zhTW', '暗殺競爭對手', '薩法爾是個精明的傢伙 - 我將會這樣追封他的……在他安穩的搶走這個地下室所有的寶藏同時，他企圖阻止聯合團的進入。我沒辦法相信這些蠢蛋們可以打敗薩法爾的防禦，因此我想要跟你談個交易，$r。$B$B進入法力墓地殺掉奈薩斯王子薩法爾。將他的屍體帶回給我當作證明，我將會大大的獎賞你。', '法力墓地外的奈薩斯王子哈拉瑪德要你去殺掉奈薩斯王子薩法爾並將薩法爾裹帶帶回來給他。', '', '去泰羅卡森林找白骨荒野的節點親王哈拉邁德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10166, 'zhTW', '白吼的記憶', '這個墜飾喚起了不同時期的回憶。一段比較好的時光。$B$B不幸地是，回憶是我現在最不需要的東西。$B$B我要你把這東西埋葬在烈焰邊境的符文石旁邊。那裡就是我第一次遇見樹人長者的地方。讓我老朋友的回憶休息吧。', '拉瑞安娜·河風要你在烈焰邊境將老白樹墜飾放置在符文石旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10167, 'zhTW', '奧齊頓……', '奧奇奈地穴的深處是一座墳墓:一座與現存在這片粉碎領土內任何一座墓都不同的墳墓。奧齊頓的浩瀚陵墓就是來自於這座墳墓，第一座的墳墓。$B$B你必須冒險到奧齊頓的奧奇奈地穴找到這座墳墓。殺掉地穴守護者並釋放被俘獲在內的靈魂。這個靈魂擁有那把鑰匙……', '前往泰洛卡森林的白骨荒野的奧奇奈地穴，並殺掉主教瑪拉達爾以釋放迪歐瑞的靈魂。', '', '去希爾斯布萊德丘陵找達隆山的德歐里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10168, 'zhTW', '靈魂看見的', '幾個世紀以來，奧齊頓的靈魂聚結成為我黯淡的本質。大多數降臨於這地穴的大災難都是直接使我狀態變弱的原因。$B$B遺憾地是，沒有什麼東西可以制止這個循環。這就是身為那魯的一個問題 - 沒有了虛無，聖光就無法存在。$B$B你的唯一的解決辦法就是在他們轉化成虛無生物之前先去消滅納葛蘭的古老靈魂。使用這些靈魂之鏡尋遍整個地穴以釋放他們……', '在奧奇奈地穴裡的某處找到一面靈魂之鏡，並且用它召喚來自納葛蘭的古老的獸人元祖的黯淡的靈魂前來。消滅15個黯淡的靈魂好讓那些先祖能夠安息。當任務完成後，回到先祖之地的卡修爾母親那裡。', '', '去納格蘭找先祖之地的卡舒爾宗母。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10169 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10169, 'zhTW', '鎮靜劑', '奧爾多如今看來是得到沙塔爾的恩寵了。怎麼說好呢，這真是意料之外，情理之中。$B$B看吧，他們竟然在離阿達爾那麼近的地方炫耀著他們的佇列操演。除了拍納魯的馬屁，他們還能幹點別的正經事嗎？$B$B先驅者哈隆奈姆的火槍手中隊未免也太認真了點，居然因為擔心午飯時間過長耽擱了操練，把自己的鍋都給帶來了。我們可不能放過這個機會，得給他們點顏色看看，$N。$B$B我要你把這個瓶子裡的東西倒進他們的飯菜裡。這樣一來，結果可就……有趣了。', '撒塔斯城內的魔導師法爾里斯要求你將一瓶鎮靜劑帶去聖光廣場，倒入射手隊的烹飪鍋內。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10170, 'zhTW', '回到祖母身邊', '帶著你勝利的消息返回卡拉達爾找祖母吉雅，$n。這將使瑪格哈士氣大振。或許甚至連年輕的地獄吼都會自他的抑鬱中振奮起來。', '回到卡拉達爾找祖母吉雅談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10171 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10171, 'zhTW', '極為傷心的酋長', '你已經為瑪格哈做了許多事，$n。你的成就廣為大家所知，包括卡爾洛斯。現在到他那裡那並且告訴他你最近的勝績。告訴他你為他及他的族人所做的事。他肯定會因為你的話而感到振奮。', '卡拉達爾的祖母吉雅要你去與卡爾洛斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10172 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10172, 'zhTW', '沒有希望了', '你是一位值得尊敬的$r，$n。你已經為了瑪格哈做了許多事。沒有人能否認你對我族人所做的事。哎呀，瑪格哈的時代結束了。你已經讓我知道，遠超過一切事物，我不適合領導這些人。我受詛咒的血流得太深。我無法……我不能成為第二個地獄吼去毀掉獸人。$B$B$n，請回到祖母那並且告訴她我跟你說過的話。我沒有臉回去見她……去直視她的雙眼。', '去與祖母吉雅談談並告訴她卡爾洛斯跟你說了什麼。', '與蓋亞安祖母談話', '去納格蘭找加拉達爾的蓋亞安祖母。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10173, 'zhTW', '大法師之杖', '請允許我自我介紹，$c。$B$B我是羅樊德威，大法師瓦戈斯的學徒。$B$B我的師傅是……應該這麼說，不受歡迎的。我到這來是有一件至關重要的事情。$B$B這城市東南方的阿克隆廢墟是燃燒軍團行動的溫床。他們在廢墟的意圖既不關我的事，也不關我師傅的事，但是他們的領導人，艾克爾拉斯，擁有大法師之仗。$B$B這喚魔粉末會讓你將惡魔從隱形中顯示出來。把它撒在廢墟的中心的火盆上。', '從『審判官』艾克爾拉斯那裡取回大法師瓦戈斯之杖，並且將它帶去給52區的羅樊德威。為了讓艾克爾拉斯現身，把喚魔粉末撒在在廢墟中心的火盆上。', '', '去找虛空風暴52區的拉文德維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10174 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10174, 'zhTW', '紫羅蘭之塔的詛咒', '現在，你可以使用大法師之杖與他聯繫。$B$B他住在紫羅蘭之塔，在東南方的一座〝島嶼〞上。這座塔是他的居所也是他的監獄，如同被詛咒了一樣。肯瑞托既不能進去也不能離開，把我與我的主人分開。$B$B這權杖的魔力能穿透塔的防禦，但只有在有人在肯瑞托外面禱告才行。$B$B拿著這大法師之杖並使用它召喚出他的影像。告訴他已經發生的事，我並沒有完全讓他失望。', '使用大法師瓦戈斯之杖與大法師瓦戈斯連絡。如果你遺失了大法師瓦戈斯之杖，可以跟52區的羅樊德威談談取得一個替代品。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10175 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10175, 'zhTW', '索爾，杜洛坦之子', '回到你的世界去，$n。到我的孫子那裡並且告訴他，他的血緣在這裡 - 在這粉碎的世界。$B$B告訴他他父親的遺風永在。$B$B告訴他所有的事……', '到奧格瑪去將吉雅的訊息傳達給索爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10176 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10176, 'zhTW', '守護者阿其羅斯', '現在你已經收集好所有用來打破凱爾薩斯的詛咒所需的物品，還有一件事要完成。當凱爾薩斯封印這座塔時，他放了一個秘法魔像，阿其羅斯，在這座塔的底部。$B$B你必須打敗阿其羅斯以讓我再度在塔中運用法術。$B$B當你進入紫蘿蘭之塔時，詛咒就會開始對你發生作用。$B$B一旦你打敗阿其羅斯，登上塔的高處協助我進行儀式的準備行動。', '進入肯瑞瓦村莊中心的紫蘿蘭之塔打敗阿其羅斯，完成後與大法師瓦戈斯談談。', '', '去虛空風暴的紫羅蘭之塔找大法師瓦格斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10177 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10177, 'zhTW', '奧齊頓的麻煩', '我在奧齊頓的間諜已經送來了干擾報告。那個地方從幾年前炸毀後就除了麻煩以外什麼都沒有。$B$B那邊有某些事徹底的不對勁 - 再一次地 - 暗影議會目前正在戰備中。雖然這些報告缺乏細節，不過他們的準備活動看起來似乎是指向內部。$B$B$n，你必須想辦法到暗影迷宮的入口。戰場元帥瑪赫范將會在完成每一項任務後將你填寫入報告中。', '向泰洛卡森林裡奧齊頓的暗影迷宮入口處的戰場元帥瑪赫范報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10178, 'zhTW', '找尋間諜·吐剛', '吐剛，這個傻瓜!我們在這裡勉強擋住攻擊，而他回去取得更多情報並且試著解救其它的間諜!$B$B我不知道是要愛他還是殺了他!$B$B暗影議會一定已經使用魔法在搜尋我們了，因為我們所有的間諜必須趕緊離開那裡。我們大多數都無法做到這樣。$B$B拜託，如果你勇敢到足以進入暗影迷宮，你可以留意一下吐剛嗎?已經有一會兒了，不過我擔心情況更糟。', '在奧齊頓的暗影迷宮裡找到間諜·吐剛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10179, 'zhTW', '肯瑞瓦村的管理器', '當我們明確得知遠征軍已經被困外域，無法返回艾澤拉斯世界的時候，肯瑞託先遣隊進駐了法蘭倫平原，並修築了一座名為肯瑞瓦的村落。我將村子交給管理器戴沃斯負責，但是當凱爾薩斯和他的軍隊將我封印在紫羅蘭之塔中後，我便徹底失去了與他的聯絡。$B$B$N，去肯瑞瓦村尋找他的下落，盡你所能地幫助他。我敢肯定，那次攻擊後，他肯定非常忙碌。', '與虛空風暴肯瑞瓦村的管理器戴沃斯談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10180, 'zhTW', '無法置身事外', '我試著說服伊斯法留在這裡，在撒塔斯的安全中，但是他不肯。相反的，他決定獨自再次冒險前往奧齊頓。$B$B他很幸運能夠逃離塞司克大廳一次，但是如果他們發現他，將不會有第二次。$B$B我欣賞他想解救妹妹的渴望，但是他無法在沒有幫助的情況下完成它。$B$B找到伊斯法並和他談談，$n。如果你不能說服他回來，或許你能幫助他營救拉卡?', '與伊斯法談談，你可以在奧齊頓的塞斯克大廳入口附近找到他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10181, 'zhTW', 'Collector\'s Edition: -pn - E - FLAG', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10182, 'zhTW', '戰場法師達斯立克', '這把劍簡直就是極品，鍛造精美而且非常適合給戰場法師所使用。上頭有肯瑞托的圖樣還有一個「達斯立克」的名字深深的刻在劍柄上。$B$B當這把劍交到你手上的時候，你感到劍的金屬部位散發出一種不協調的感覺，就好像這把劍分處於兩個不同的世界一樣。這把劍就是把戰場法師達斯立克的靈魂困在這個世界上的元兇嗎?$B$B也許把它放回原本屬於的地方就可以打破這個枷鎖，讓達斯立克的靈魂可以安息。', '找到戰場法師達斯立克的駐紮處將劍放回他的武器架。完成之後，與肯瑞瓦村莊的管理者戴沃斯談談。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '', '讓達斯利克的靈魂安息', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10183, 'zhTW', '前往52區', '我離開這裡研究虛空 - 伊斯利現存以及所有的。這是個遠離城鎮的光源及吵雜的理想地點。這個橋很棒吧?只要我能讓這個垃圾繼續工作。$B$B嘿，你知道嗎，要是你在找工作，52區那邊有一堆呢!就在這條路往上走然後在交叉口右轉。$B$B你為不幫我送我最新的調查筆記給火箭主管夫斯拉吉呢?我相信他會有很多事給你去做，什麼和X-52火箭船，以及所有!', '遞送虛空學家的手記給虛空風暴52區的火箭主管夫斯拉吉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10184 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10184, 'zhTW', '惡意的倖存者', '這個村裡大多數的靈魂幾乎都是肯瑞托法師的蒼白倖存者。他們失去了原先的意識，盲目憤怒的排徊在廢墟間。$B$B不過，不是一直都是這樣的。在這次攻擊餘波中，這些靈魂變的焦躁不安，但沒有惡意。隨著時間過去他們只變的更加的激進。我不敢冒險進去村子的南邊，他們可不會因為是我而手下留情。去平息他們，希望能夠淨化他們的憤怒。', '肯瑞瓦村莊的管理者戴沃斯要你去肯瑞瓦的小鎮廣場殺掉20個分離的靈魂。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10185, 'zhTW', '比死還糟的命運', '在血精靈毀掉肯瑞瓦村莊後，他們開始在西北方建造一座大型建築物。沒有大法師的專業鑑定，我們無法確切的說明那裡發生了什麼事。$B$B不過，有件事是可以確定的。血精靈的舉動已經在村中解放了一批的飢渴的法力元素。他們似乎被巫師街的廢墟吸引，進行更多的毀壞。我們不允許這樣繼續下去。', '殺掉10個法師殺手及10個法力尋找者後回到肯瑞瓦村莊找管理者戴沃斯。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10186, 'zhTW', '你被雇用了!', '讓我成為第一個歡迎你上任的人，資淺技師第三級的$n!$B$B我們正在那裡建造我的傑作 - X-52虛空火箭!$B$B但首先我們需要先拿到全部的零件跟燃料。就是你來的地方。$B$B一開始，我需要水晶 - 很多的水晶 - 供給火箭的伊斯利引擎母體。而德萊尼的耳朵裡有水晶!$B$B往北方到安卡特廢墟去將他們帶來給我!別在意那些德萊尼的鬼魂。', '收集10個伊斯利母體水晶，然後帶回虛空風暴的52區交給火箭主管夫斯拉吉。', '', '去找虛空風暴52區的火箭主管弗斯拉格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10187, 'zhTW', '給大法師的訊息', '儘管局勢舉步維艱，但你的到來還是令我們振奮不已，這意味著大法師並沒有忘記村子的困境。$B$B<管理器抬頭望了望遠處的高塔。>$B$B這聽起來很荒謬，對吧？有的時候，一面石牆就能將我們隔絕。魔法壁障實在是太容易被忽視了。$B$B如果你願意的話，請進入塔內告知大法師瓦格斯，我們正在努力恢復肯瑞瓦村的原貌，很快就能制定出計劃，將這些法力生物逐出村落。', '與虛空風暴紫羅蘭之塔塔頂的大法師瓦格斯談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10188 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10188, 'zhTW', '卡薩斯符印', '在我們多年前離開艾澤拉斯前，肯瑞托委託我們的遠征隊管理一個強大的神器，卡薩斯符印。這在我們對抗獸人的戰鬥中提供了很大的幫助，並且扮演了幫助破解囚禁我的魔法的主要角色。$B$B然而，在凱爾薩斯奪走我的所有物後，他將這個符印給了縛法者瑪莉安娜，一直都支持駐軍的人。要是他真的了解他擁有的是什麼，就不會那麼容易的把它送人了。', '從法力熔爐寇魯的縛法者瑪莉安娜那取得卡薩斯符印，就在紫羅蘭之塔的西北方。在你拿到這個符印後，使用大法師瓦戈斯之杖投射出大法師瓦戈斯的影像，告訴他你的進度。如果你遺失了大法師瓦戈斯之杖，可以和52區的羅樊德威談談取得一個替代品。', '', '使用大法師瓦格斯的法杖投射一個大法師的影像並告知你的進度。$B$B如果你不小心遺失了大法師瓦格斯的法杖，可以向52區的拉文德維爾再要一根。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10189 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10189, 'zhTW', '法力熔爐巴納爾', '你應該注意到在來這裡的途中有一座凱拉的法力熔爐。你知道嗎，這座大型紫色建築物是從天上吸收能量?$B$B我們是由薩塔派到這裡來調查他們的。你可以藉由取得一份人事名單來幫助我們收集資料。讓我們知道誰在那裡以及他們的所作所為對我們來說都是珍貴的資訊。$B$B我們相信阿拉斯恩上尉，他就在法力熔爐巴納爾外領導一隊投石隊，身上擁有一份相似的名單。將它帶來給我。', '52區的間諜大師薩洛迪恩要你去法力熔爐巴納爾的外圍從阿拉斯恩上尉身上取得巴納爾員工名冊。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去虛空風暴找52區的間諜大師薩羅迪恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10190, 'zhTW', '補充電源', '我有一個非常重要的任務要到這些廢墟內去收集機械裝置，但問題是我沒辦法讓我的機器人都維持充滿電的狀態。$B$B相位捕獵者-看起來像龍人的傢伙-擁有很多的能量!你可以在這個島的邊緣找到從虛空中飄流而來的他們。$B$B幫這個充電火槍裝上電池然後使用在呈現虛弱的相位捕獵者身上，殺死它以吸收殘存的能量。', '將充電火槍使用在足夠的相位捕獵者身上直到電池蓄電量達到10。之後將它帶回虛空風暴的安卡特廢墟交給機器人專家艾里。', '', '去虛空風暴找恩卡特廢墟的機器人專家艾蕾。', '電池充能等級', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10191 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10191, 'zhTW', '充滿動力的馬克斯五號', '你好，$r。我已經充電完畢而且可以準備出發了。$B$B在這些廢墟中有一些我想獲得的脆弱德萊尼機械。我已經在我的手腕起動處安裝了精密的伺服電動器，還有最先進的燃燒氣動力撞擊排流器。小心的應付他們就不會有問題了。$B$B然而，這些廢墟中的鬼魂很有可能攻擊你，所以我將會需要你跟隊友的保護。', '護送馬克斯A型機器人五號通過安卡特廢墟並安全的回來。完成後與在虛空風暴的安卡特廢墟外的機器人專家艾里談談。', '護送麥克斯米林V型穿越恩卡特廢墟', '去虛空風暴找恩卡特廢墟的機器人專家艾蕾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10192 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10192, 'zhTW', '卡薩斯的手冊', '肯瑞托和我們的遠征隊一起派送另一個卡薩斯的所有物。是他的一本法術書，書名是卡薩斯的手冊。內容包括所有他精通的法術，在這場戰爭中替我們提供了多方的優勢。$B$B在凱爾薩斯和他的軍隊包圍肯瑞瓦前，這本手冊曾被一個叛逆的學徒從我這偷走企圖想研究裡面的法術。這個學徒及他同夥將他們自己關在城鎮南方的小屋中，私下個別研讀不同的內容，。', '從肯瑞瓦村莊的小鎮廣場取回卡薩斯的手冊 - 第一章，卡薩斯的手冊 - 第二章，和卡薩斯的手冊 - 第三章。拿到所有章節後使用大法師瓦戈斯之杖與大法師連絡。', '', '使用大法師瓦格斯的法杖與大法師取得聯絡。$B$B如果你不小心遺失了大法師瓦格斯的法杖，可以向52區的拉文德維爾再要一根。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10193 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10193, 'zhTW', '高重要性的目標', '「根據名冊的資料，我們知道法力熔爐運作的首腦是星移管理者及星移工程師。就是他們在監督法力熔爐取得一個叫「扭曲能量」的東西並經由一個地下輸送管系統送到一個遙遠的地點。$B$B那裡僅存的專家就剩地質學家。剩下的不是軍隊裡的士兵就是博學者的好友;兩者都很容易被取代。$B$B進入那裡並殺掉凱爾薩斯的專家群;那將會大大的打擊他。」', '52區的間諜大師薩洛迪恩要你去法力熔爐巴納爾殺掉2個日怒星移管理者，6個日怒星移工程師以及8個日怒地理學家。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去虛空風暴找52區的間諜大師薩羅迪恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10194 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10194, 'zhTW', '隱形飛行', '在你離開後，我的手下發現了另一座法力熔爐。就在這裡的東邊，叫做法力熔爐寇魯。$B$B我兩位優秀的間諜已經在法力熔爐外設下了一個秘密的降落點。你要去幫助他們滲入凱爾薩斯的軍隊裡，並盡全力去取得任何的消息。$B$B去與城牆外的維納妮雅談談;她會安排一隻雙足飛龍載你到法力熔爐寇魯去。到了那裡，與卡利迪斯·曙光談談;他會簡短解說你的任務內容。', '與52區外的維納妮雅交談並飛往法力熔爐寇魯。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10195 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10195, 'zhTW', '流行時尚', '自從我用你帶回來的羽毛為波爾泰姆製作了一頂帽子之後，包括山德在內的其它所有僱傭兵都嚷嚷著說也想要一頂。於是我只好告訴他們說馬上就為他們製作帽子，不過，我需要有人為我穩定地供應鴉人羽毛。$B$B如果你能將在森林冒險中收集到的羽毛都給我，我會非常感激你的。', '給奧蕾莉亞要塞的洛瑟蕾絲帶回30片鴉人的羽毛。', '', '去泰羅卡森林找奧蕾莉亞要塞的洛瑟蕾絲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10196 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10196, 'zhTW', '更多鴉人羽毛', '儘管我成功地將鴉人的靈魂吸引到了我的身邊，但它們太容易受到驚嚇了，一接觸就逃跑了。或許我偽裝得更好點，它們就會被迷惑得更深，可以長時間靠近我。$B$B你再去搞羽毛吧，我需要更多你先前給我搞來的那些羽毛。如果你能再給我帶回來一些，我會很感激你的。', '將30片鴉人的羽毛交給碎石堡的瑪魯卡茲。', '', '去泰羅卡森林找碎石堡的瑪魯卡茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10197 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10197, 'zhTW', '具說服力的偽裝', '滲透進凱爾薩斯的軍隊中不是一件簡單的任務。以我對於幻術有限的了解，我只能將你變成凱爾薩斯的一位部下的樣子，但對於他們的制服我還有一些細節無法複製。$B$B帶給我一套他們的長袍，一雙他們的手套以及一個日怒守衛勳章。這可以使我的法術效果更加有說服力。', '取得1套日怒秘法師長袍，1雙日怒調查員手套和1個日怒守衛勳章，完成後將這些帶回虛空風暴的法力熔爐寇魯給卡利迪斯·曙光。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去虛空風暴找法力熔爐：庫魯恩的卡勒迪斯·晨光。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10198 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10198, 'zhTW', '收集資訊', '我已經根據你拿來的物品準備了一套制服。經由魔法加持過以完成偽裝。$B$B我們發覺指揮官黎鑄在幾分鐘前去見了秘法師艾登尼斯。他帶了全部的守衛在身邊，因此無論他們談論的是什麼一定是很重要的事，去看看你是否可以聽到些什麼。$B$B喔，我都忘了。你要離巡邏法力熔爐的秘法魔像遠一點。他們會看破偽裝的。', '使用日怒偽裝，進入法力熔爐寇魯聽取指揮官黎鑄與秘法師艾登尼斯的對話。完成任務後回報給卡利迪斯·曙光。為占卜者完成任務會讓你的奧多爾聲望降低。', '收集情報', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10199 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10199, 'zhTW', '一點額外的刺激', '阿，我剛忘了一種用來使我的混合物產生一點必需的額外刺激的原料。$B$B這種虛空鰭刺的刺，漫生在岩膚鐮奪怪附近，形成了一個孔。幫我帶一些他們的刺來，我會從中萃取毒液出來!$B$B我相信成效一定會很驚人的!', '替虛空風暴裡52區的布茲帶來5個虛空鰭刺。', '', '去虛空風暴找52區的布茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10200, 'zhTW', '回去找薩洛迪恩', '最好這個消息能夠盡快的送回去給薩洛迪恩。我會待在這掩護我們的行蹤。$B$B讓凱爾薩斯發現我們在附近窺探對我們來說不是件好事。機密情報永遠是好的，要是你的敵人根本不知道你知道的話。', '回到虛空風暴的52區找間諜大師薩洛迪恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10201, 'zhTW', '現在，真相的時刻', '這個油已經準備好接受第一次測試了。他看起來濃烈到足以作為高品質的武器油了。$B$B查明的唯一方法就是進行專業的試驗。看到在懸賞告示旁的葛利克嗎?當然，他不出名，但是獸人知道他對武器有他的看法!$B$B拿著這個油的樣本給他並要他使用在他的武器上。在他有機會測試後，讓我知道他對這個東西的看法。', '找到葛利克並要他將東西試用在他的武器上。一旦他測試過這個油後，回去向瑞克利亞報告結果。', '', '去泰羅卡森林找碎石堡的拉克妮亞。', '讓葛雷克測試奧雷巴油', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10202, 'zhTW', '背叛者', '我們最近接觸了一位想要加入我們隊伍的日怒博學者，發誓他手中握有我們需要的情報。我們已經詢問過我們的情報員以確保他不是一個雙面間諜，而他通過測試了。$B$B他就部署在不好連絡的法力熔爐艾拉。去跟他談談並了解他所知道的消息。如果他有他聲稱的一半有用，我們就能好好的運用他。', '到法力熔爐艾拉去與博學者瑟勒朵恩談談。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10203, 'zhTW', '傳送無價的資產', '看到52區的那道縫隙了嗎?我們做到了!<張嘴大笑>$B$B這為了X-52虛空火箭生產了各種吸引人的物品，但我們的設備日漸減少了。$B$B我們在燃燒軍團進入前曾在東南方的阿克隆廢墟營運過。我需要你帶著這個超強化傳送搖控器到廢墟去。用它來將我們的引擎發送回裂隙下的工兵領班布拉斯特費索。$B$B資淺技師第三級$n，這是你升遷的機會。好好珍惜!', '使用超強化傳送搖控器將多旋轉挖掘機、伺服氣動挖泥器、多光譜地形分析器以及裝滿爆裂物的大型貨車傳送回52區。完成後向位於虛空風暴內的52區中裂縫東邊盡頭的工兵領班布拉斯特費索回報。', '', '去虛空風暴找52區的首席工兵布拉斯特菲茲。', '回收高轉速挖掘器', '回收機械氣壓挖掘爪', '回收多光譜地形掃描器', '回收一大車炸藥', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10204, 'zhTW', '血寶石水晶', '凱爾薩斯的博學者們提高了他們法力水晶的用途使他們可以在幾秒內虹吸大量的能量。$B$B他們將小型血寶石水晶的裂片融合成更大，更完整的一顆水晶。$B$B到法力熔爐巴納爾去從日怒博學者那取得一個這種裂片並使用它從一顆大型水晶中虹吸能量出來。$B$B完成後回到找我，我可以研究這個光環的作用。別擔心;任何副作用都是暫時的。', '博學者萊莉娜要你去法力熔爐巴納爾從日怒博學者那取得一個血寶石裂片。在一個更大的血寶石水晶附近使用這個裂片，並帶回52區給她。為占卜者完成任務會讓你的奧多爾聲望降低。', '吸取血寶石的能量', '去虛空風暴找52區的魔導師拉恩娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10205 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10205, 'zhTW', '星移劫掠者尼薩德', '一定得解決掉星移劫掠者尼薩德!我不知道他是如何從我的攻擊中存活下來得，但絕不允許他繼續在那進行他的行動。$B$B回到那裏去殺掉尼薩德。他在接近聚集之地西南方的轉角那有一座小型的伊斯利營地。$B$B別像我之前一樣失敗了，$c。', '殺掉星移劫掠者尼薩德，完成後回到虛空風暴的52區找虛空行者凱澤。', '', '去虛空風暴找52區的虛空獵手卡爾伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10206, 'zhTW', '挑選你的職責', '那些伊斯利蠢蛋們和我們一樣投機取巧，我會這樣形容他們的。但沒有人，我的意思是沒有人喔，敢侵入我們的領地!$B$B南邊的聚集之地是我們的!$B$B如果我們要完成X-52虛空火箭，我們就需要涉獵所有新的技術。既然這些伊斯利偷取我們的東西，我想以牙還牙是公平的。$B$B你何不往那去看看是否能偷偷學到一些他們的技術回來!', '收集10片伊斯利技術後回到虛空風暴的52區找威勒老爹。', '', '去虛空風暴找52區的維勒老爹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10207 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10207, 'zhTW', '前線基地:劫奪者荒野 重新啟用', '你在戰爭中的英勇表現已經被高層注意到了，$C.他們想要派你去前線與殘拳的軍隊會合。他們激進，全心奉獻於殲滅全數的燃燒軍團，因此你應該可以處的很好……$B$B朝東方大概200步後在大型土地凸出處轉向南方。一旦到達那裡，就找前線指揮官吐阿奇報到。$B$B現在快行動！', '到劫奪者荒野找前線指揮官吐阿奇報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10208 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10208, 'zhTW', '阻斷他們的援軍', '這裡的正東方就是軍團前線。這個前線的對面就是地獄火通道及傳送門，用來將燃燒軍團的援軍帶進地獄火半島及整個外域。我們得去摧毀那些傳送門!$B$B帶著這些雷管。這是來自於52區的設計，它是一個使用惡魔本身力量來引爆的一個裝置!打敗燃燒軍團在塞勒斯還有卡魯歐傳送門附近的軍隊來收集惡魔符文石，使用雷管來觸發傳送門內的4顆石頭，然後看場好戲!完成任務後回來找我。', '打倒塞勒斯傳送門和卡魯歐傳送門附近的敵人以便收集惡魔符文石。在塞勒斯傳送門還有卡魯歐傳送門內使用吐阿奇的雷管。完成後帶著吐阿奇的雷管回到地獄火半島的搶奪者荒野找吐阿奇。', '', '去地獄火半島找機甲殘骸的前線指揮官托爾克。', '破壞希魯斯傳送門', '破壞科盧爾傳送門', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10209 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10209, 'zhTW', '召喚者卡辛恩的禮物', '下一件我們要做的事就是從監禁他的血精靈召喚者手中取回我的珍寶，葛拉希厄斯。召喚者卡辛恩是凱爾薩斯派來毀掉肯瑞瓦的軍隊中最資深的博學者其中一位。很自然的他會將我的珍寶當成戰利品的一種。$B$B我相信卡辛恩，以他的愚蠢來說，他會試著強迫葛拉希厄斯來服侍他。我的水晶球顯示卡辛恩現在座落在\'法力熔爐杜羅，如果這個術語對你來說有任何意義的話。', '到日怒要塞的北方小島上，打倒法力熔爐杜羅的召喚者卡辛恩，並從他手中將葛拉希厄斯之石拿回來。當你拿到石頭後，使用大法師瓦戈斯之杖與大法師連絡。如果你遺失了大法師瓦戈斯之杖，可以找52區的羅樊德威拿取替代品。', '', '使用大法師瓦格斯的法杖與大法師取得聯絡。$B$B如果你不小心遺失了大法師瓦格斯的法杖，可以向52區的拉文德維爾再要一根。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10210 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10210, 'zhTW', '阿達歐', '歡迎來到撒塔斯城，$c。這是所有外域中唯一你可以到處都安全的地方。$B$B一群被稱為薩塔的那魯將惡魔從這裡趕出去了。$B$B如果你從來沒有碰過那魯，那你應該去看看在聖光露臺的阿達歐。這位薩塔的領導者是一位令人敬畏的人，如果我有看過的話。穩定是來自這個荒島上其他生物的流暢變化。', '與聖光露臺中央的薩塔領導者，阿達歐談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10211 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10211, 'zhTW', '聖光之城', '不要有太多的詢問以免打擾阿達歐，$c。那可能是你曾經面對過最具力量的生物了。$B$B你看起來很不面熟。我猜你是想認識這個城市吧?$B$B你得原諒我要是我無法親自為你導覽，因為我有點忙著與阿達歐討論戰略。也許你可以找個可配合的召喚僕人代替我嗎?太好了!', '跟著卡德加的僕人並聽他說故事。完成任務後回去找卡德加。', '聖光之城', '去找撒塔斯城的卡德加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10212, 'zhTW', '瑪格哈的英雄', '我必須在離開前將一切就緒。回去向祖母通知她的孫子就要來了。', '回到納葛蘭的卡拉達爾找祖母吉雅。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10213 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10213, 'zhTW', '調查這場空難', '當我在荒原中受傷時，我看到了一艘哥布林飛艇墜毀。它墜落在西北方，就在遠征隊軍械庫那一邊。$B$B那艘飛艇著火了。尖叫，著火的哥布林像炸彈一樣的從天空落下。當然我很痛而且失了很多血。我可以想像這整件事情。$B$B如果你可以找到任何倖存者的話，我們可以提供他在斷脊氏族崗哨這裡避難。', '搜尋空難倖存者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10214 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10214, 'zhTW', '亂糟糟的礦洞', '礦井被一群甘爾葛混蛋給侵佔了，而那些苦工們卻決定好好小憩一下！我不知道在礦井發生騷動的時候他們怎麼還睡得著，不過這不是我最擔心的事情。$B$B如果我們不能儘快除掉那些甘爾葛，索爾瑪的礦石和其它礦物供給都會被切斷。我已經向前線指揮官卡倫克尋求幫助了，但是他說現在城鎮不斷遭到襲擊，他沒有多餘的人手可以派來支援我。你願意幫幫我嗎？', '殺死15個甘爾葛工兵，然後向工頭拉澤克拉茲覆命。', '', '去地獄火半島找索爾瑪礦洞的工頭拉澤克拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10216 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10216, 'zhTW', '安全至上', '薩法爾的伊斯利徹底的將我們趕出法力墓地。感謝老天，我有個計畫。雖然我們不能從前門進去，一定有許多的傳送器在裡面。$B$B我要你先去為我的成員開出一條路，然後我要你去啟動其中一台傳送器將我們傳送進去。$B$B在清完路後啟動房間裡的啟動器，就在薩法爾的房間的前一間。別擔心，我會讓你的付出有價值的……', '工匠莫法利厄司要你去殺掉10個伊斯利盜墓者，5個伊斯利巫士，5個奈薩斯捕獵者及5個伊斯利縛法者。一旦完成後，找到在薩法爾之前一個房間的伊斯利傳送器並啟動它。', '', '去找希爾斯布萊德農場的虛靈傳送器控制檯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10217 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10217, 'zhTW', '化石燃料', '我的伐木機器人燃料用光了！', '測試', '', '去地獄火半島找索爾瑪的工頭拉澤克拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10218, 'zhTW', '解決別人的難事', '你在期待誰!?那個白痴莫法利厄司已經「優先離開」了。現在我在收拾他的殘局。我需要你做的就是看著我經過薩法爾的乙醚收集器然後榨乾它們收集的所有東西。如果我成功的完成了我的任務，哈拉瑪德將會親自獎賞你!$B$B你說什麼?護送我通過法力墓地然後揀一些驚人的寶藏?你已經完成了大部分的工作了!已經沒有東西還有辦法在我們走過之後還活著，對吧?', '護送工程師薩希恩安全的穿越法力墓地讓他可以拾取那些薩法爾的精華收集器內的精華。完成後回到法力墓地外的聯合團紮營地找奈薩斯王子哈拉瑪德回報。', '護送低溫工程師沙赫恩', '去泰羅卡森林找白骨荒野的節點親王哈拉邁德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10219, 'zhTW', '遛狗', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10220 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10220, 'zhTW', '讓他們聽話', '我被派到這裡與不屈者的靈魂連繫。這些曾經很自豪的聯盟士兵們在很久以前被擊敗，現在他們受到詛咒的靈魂在西方的廢墟間徘迴。$B$B要是他們可以加入，我們將會得到一個有力的同盟。想想看，利用一團不死戰士來對抗我們的敵人。但這些不死族因仇恨而失控，根本不會聽進我的話。$B$B也許我們可以脅迫他們加入。', '莫爾迪巴要你去斷脊氏族崗哨西方的遠征隊軍械庫殺掉12個不屈的士兵，8個不屈的騎士，以及6個不屈的魔巫士。', '', '去地獄火半島找斷脊氏族崗哨的莫迪巴大使。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10221, 'zhTW', '布姆博士!', '$n，我之前的門徒，史巴克·伍伯羅斯，在下來這裡的時候沒有帶他的安全盔帽，結果有天他就轉化成了惡名昭彰的布姆博士!$B$B而且他還偷了我們大部分的挖掘設備到東北方去!他和他的布恩機器人們對52區來說變成了一個威脅。$B$B我需要你到他在城外的布姆營地去把他解決掉!使用這些布姆的厄運炸彈去除掉他。$B$B記得不要靠近他及他的那些布恩機器人!', '殺掉布姆博士並將這個好消息帶給虛空風暴的52區給工兵領班布拉斯特費索。', '', '去虛空風暴找52區的首席工兵布拉斯特菲茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10222, 'zhTW', '日怒部隊', '在凱爾薩斯王子的部隊摧毀了村莊並且將大法師監禁在紫色之塔後，他們撤回到東北方的日怒要塞。這個毀了我們村莊又殺了我們同伴的男人在為了他們的\'光榮勝利\'乾杯的同時，我們卻無力為我們的淪陷報仇。$B$B我們一定要為他們所犯下的罪行展開行動!為我們的復仇吹響號角吧，$n。去日怒要塞向那些罪人們討回公道吧。', '肯瑞瓦村莊的管理者戴沃斯要你去殺了10個日怒弓箭手。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10223, 'zhTW', '擊倒戴利斯', '我永遠都忘不了當初帶領發動攻擊的那個血精靈。在他的赤紅色護甲之上，他穿了一件外袍上面有一個圖案我從來沒見過。$B$B既勇猛又無憐憫之心，他身先士卒的帶隊方式是其他血精靈軍官們前所未見的。他必須為那天許多肯瑞托法師的死亡負起責任，但是他並沒有在日怒要塞逗留太久。凱爾薩斯命令他去法力熔爐杜羅協助佔領該地區。找到他，$n，並且讓他的弓永遠失去主人吧。', '肯瑞瓦村莊的管理者戴沃斯要你去殺掉大師戴利斯·黎擊。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10224, 'zhTW', '引擎的精華', '身為 X-52的首席工程師，我必須得將虛空火箭的主引擎維持在極好的狀態。$B$B不幸的是，我還沒將它們建造出來。$B$B$c，我現在身陷緊迫的困境中!我幾乎擁有全部的零件。所缺少的就是引擎的核心。$B$B幸好，我想我們可以好好運用這些從當地法力怨靈取得的精華來協助啟動這些引擎。$B$B可以在島的北邊大部分的灼熱壕溝附近找到他們。當然，除了52區這以外。', '收集7個法力怨靈精華將它們帶回到虛空風暴的52區給首席工程師崔普。', '', '去虛空風暴找52區的主工程師特雷普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10225 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10225, 'zhTW', '回報工程師', '$n!我需要你帶著這些伊斯利水晶給首席工程師崔普，我的，啊，首席工程師。$B$B他應該知道要怎麼處理它們。如果他不知道，你得看護這些水晶到他找出為止。', '將這些伊斯利母體水晶送到虛空風暴的52區給首席工程師崔普。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10226 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10226, 'zhTW', '元素力量粹取', '真該死，竟然沒有成功!$B$B好吧，我有另一個點子!我要辛洛歐趕工製造出一個元素力量提取器。我不確定這個能量有什麼用途，但是我知道我會用的上它。$B$B在南邊的破碎荒地岩石區的破碎的奔行者還有扭曲法力元素正好都有我所需要的東西!$B$B提取器可以讓你在殺死了它們之後把它們身上的能量轉換成固體型態好讓你收集。', '取得5個元素力量並將它們帶給虛空風暴的52區給首席工程師崔普。', '', '去虛空風暴找52區的主工程師特雷普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10227 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10227, 'zhTW', '我看到了德萊尼的鬼魂', '我看到德萊尼的鬼魂。它就在我們身邊。$B$B啊，沒人相信我因為我是個小孩。甚至連我的媽咪都不相信我。$B$B<哈勒指著藍姆多。>$B$B他相信我，因為……他也看得到他們。他對小孩做的事感到生氣。$B$B真的很好笑。我看到鬼，人們只是笑一笑並拍拍我的頭，試著安撫我。藍姆多看到鬼卻被人們說他瘋了。我真希望我永遠不要長大!$B$B你進去前應該要先跟藍姆多談談。他曾是個亡靈牧師。', '與奧奇奈地穴外白骨堆的瘋狂的藍姆多談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10228, 'zhTW', '伊斯奇歐', '我相信這些我們已經關心了至少500年以上的鬼魂應該要被遺忘。 瑪拉達爾有其他的想法。他撤到紀念土窖開始他的實驗……巫術。$B$B我希望你別想要去那裡……至少先幫助我出去之後再去，以便這些該死的鬼魂可以離開我身邊。我知道他們將寶物藏在哪，$r。想聽了嗎，啊?$B$B從撒塔斯的艾多爾，伊斯奇歐那把亡者之書帶給我。', '尋找並與撒塔斯城裡撒塔斯的伊斯奇歐談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10229, 'zhTW', '解譯書籍', '這本書看來好像是以一種神秘的聯盟密碼寫成的某種歷史。亞登，斷脊氏族崗哨的歷史學家，已經研究不屈者一段時間了;他也許可以破解這些聯盟密碼並解釋這本書的內容。', '拿著這本神秘的秘典給斷脊氏族崗哨的歷史家亞登。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10230, 'zhTW', '戰鬥號角', '也許我們用錯方式來接近不屈者了?$B$B這本書告訴我遠征軍械庫是在很久前被獸人及死亡騎士團摧毀。不屈者持續以復仇的鬼魂之姿在這永遠的對抗魔獄獸人氏族。$B$B他們只想到復仇。我們必需安排他們打敗他們最憎恨的敵人。再一次進入遠征隊軍械庫找到少校薩沃斯。他身上有一把戰鬥號角能夠招集不屈者。把它帶來給我。', '從少校薩沃斯那把不屈戰爭號角帶給斷脊氏族崗哨的歷史家亞登。', '', '去找斷脊氏族崗哨的史學家奧爾森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10231 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10231, 'zhTW', '什麼書?我沒看到有什麼書啊。', '藍姆多?呃，讓我想想……藍姆多……喔，有，那個亡靈牧師。他要這本書幹嘛?喔沒關係。沒錯我騙了你，我沒這本書。反正，再也沒用啦。書被偷了。一定是被那些邪惡的難民其中一個拿走了。除此之外，奧齊頓現在已經廢掉了。這本書對我們來說已經失去用途了。如果你找得到它，你就留著吧。$B$B就像我說的，我上星期見過幾個惡棍在這裡偷偷摸摸。去找他們吧。他們一定是在貧民窟那玩骰子。', '艾澤基爾提到書已經被偷了。你最好的辦法就是去找那些惡棍並看看他們是否有什麼消息。', '教訓“髒鬼”拉瑞，獲取資訊', '去找撒塔斯城的“髒鬼”拉瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10232, 'zhTW', '與軍團一戰', '燃燒軍團已經進入了我們的領地廢棄農場，就在這條路下去過了橋後的東邊。$B$B這對我們說可能會是個大問題!隨著軍團在阿克隆廢墟，到目前那裡，情況開始不利於在52區這的我們 - 和這個火箭計劃。$B$B$n，我要你去那解決那些惡魔!我想這麼做，但是我是個愛好者，不是個好鬥者。$B$B沒錯，事情將變得很麻煩，我可以感覺得到!', '殺掉5個莫阿格設計師及15個甘納格工程師。完成後回到虛空風暴的52區找威勒老爹。', '', '去虛空風暴找52區的維勒老爹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10233, 'zhTW', '燒毀日怒要塞', '除掉日怒要塞的駐兵不足以阻止血精靈們重新佔領它。凱爾薩斯的部下們積極又頑強。留下任何日怒的物品無疑是在邀請他們回來。$B$B不能讓這種事發生，所有的東西都必須摧毀。$n，記得要將他們的帳棚及火砲都燒成灰燼!$B$B<這個鬼魂的拳頭緊握。>$B$B從日怒火焰管理者那偷取火炬來完成你的任務，$n。', '使用燃燒的火炬，摧毀4個日怒投石器和4個日怒帳篷後回到肯瑞瓦村莊找莫爾蘭巫士中尉。', '', '去虛空風暴找肯瑞瓦村的巫師上尉莫爾蘭。', '燒燬日怒弩車', '燒燬日怒帳篷', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10234 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10234, 'zhTW', '惡魔的垃圾……', '你看起來像是個有能力的年輕<男子/女子>!我在想你是否能幫我個忙呢?$B$B往東邊去是廢棄農場，燃燒軍團進駐的地方。那裡到處都是大型的惡魔搶奪者零件。那裡也有一大堆看起來他們似乎一點都不在意的小型零件。$B$B我要你進入那裡並將許多小型的惡魔搶奪者零件帶來給我!', '取得10個惡魔搶奪者零件後帶回虛空風暴秘境領地內的領地崗哨交給威勒媽媽。', '', '去虛空風暴找中央生態圓頂的維勒老媽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10235, 'zhTW', '殺死末日裂爪', '你知道什麼可以阻擋他們嗎?就是殺掉他們的領導者!$B$B在我聽說過的所有例子當中，這都是最有效的方法。而且當他們看到像你這樣<勇猛的/強悍的>$c打倒他們的領導者……當然，我賭他們會夾著尾巴往山上逃竄!$B$B回到那裡去殺掉那個叫做末日裂爪的大個頭。我聽說他住在廢棄農場的東邊，就在輸送管的下面。$B$B也把他的爪子帶來給我!也許我們可以好好利用它。', '取得末日裂爪之手然後將它送回虛空風暴裡秘境領地內的領地崗哨給威勒媽媽。', '', '去虛空風暴找中央生態圓頂的維勒老媽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10236 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10236, 'zhTW', '令人討厭的外域!', '我不敢相信我為了來外域而離開了藏寶海灣。我的堂弟史哥利德·幸運心保證我在外域可以賺大錢，但是他卻坐著他的飛艇離開把我一個人丟在這靠著這個礦坑勉強過日子。$B$B我要怎麼在動不動就被魔獄野豬和惡魔還有魔獄獸人攻擊的這裡生活下去呢?昨天我的伐木機壞掉了，而我要拿來修理的零件被魔獄獸人給偷走了。他們把零件帶到西南邊的裂縫去，而且可能將它們給丟在那了。', '找到六個伐木機零件然後交給索爾瑪西北方的礦坑的工頭瑞絲坎茲。', '', '去地獄火半島找索爾瑪的工頭拉澤克拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10237 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10237, 'zhTW', '警告52區!', '$n，你必須馬上傳話回去52區!快點!$B$B告訴火箭主管燃燒軍團正朝我們前進了!', '傳遞這個壞消息給虛空風暴內52區的火箭主管夫斯拉吉知道。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10238 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10238, 'zhTW', '如何服務哥布林', '為什麼魔獄獸人要偷走我的伐木機零件呢?我恨死他們了。他們常常潛入我的營地偷走我的東西。幾天前他們搶走了我的三個苦工!現在我剩下的苦工們也跑光了因為他們害怕被魔獄獸人給吃掉。假如你可以救回我的苦工也許其他的人會回來。你沿著牆往西南方走就可以看到魔獄獸人的營地。', '從魔獄獸人營地救回曼尼、莫歐還有杰克然後回到索爾瑪西北方的礦坑找工頭瑞絲坎茲。', '', '去地獄火半島找索爾瑪礦洞的工頭拉澤克拉茲。', '營救曼尼', '營救莫恩', '營救雅克', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10239 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10239, 'zhTW', '潛在的能量來源', '我們並不是唯一與那些聚集在一起的魔法生物戰鬥的人。血精靈們也跟我們一樣遭遇同樣的困擾，但是我並不知道為什麼。$B$B不論他們在那邊進行什麼樣的行動，血精靈們似乎不願意停下來。事實上，我看過他們嘗試各種方法殺死那些生物。其中最有效的方法牽涉到由某種濃縮的能量物質所提供能源的魔法防禦。$B$B去奪回一些這種能量物資並且帶回來給我。當機會來臨的時候，不要猶豫你的行動會阻擾到那些血精靈。', '肯瑞瓦村莊的莫爾蘭巫士中尉要你去從法力熔爐寇魯的血精靈行動中奪取10個能量隔離體回來。', '', '去虛空風暴找肯瑞瓦村的巫師上尉莫爾蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10240 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10240, 'zhTW', '建立結界', '我們正準備試著利用從血精靈那取得的能量來源在村子的週圍建立一個結界。我不能保證這將會可行，但我們得試試看。$B$B否則，這些法力生物必定會繼續吞食這些淪陷的肯瑞托鬼魂。$B$B在城鎮週邊使用這個小符文裝置釋放能量。如果我可以無誤的進入農田，那我們就得開始注意那幾個你使用過這個裝置的地點的差異性。', '在東邊符文，東北邊符文，以及西邊符文附近使用符文啟動裝置。這些符文能夠在肯瑞瓦村莊的巫士街及小鎮廣場區週邊找到。完成任務後回去找莫爾蘭巫士中尉。', '', '去虛空風暴找肯瑞瓦村的巫師上尉莫爾蘭。', '啟用東部符文', '啟用東北部符文', '啟用西部符文', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10241, 'zhTW', '法力熔爐巴納爾的擾亂行動', '我們是薩塔派來這裡調察凱爾薩斯軍隊營運的法力熔爐。不幸的是，占卜者威脅要違反他們資訊收集的職責除非我們派軍支援他們。$B$B我們於政治方面無法妥協於這項使命，所以我們決議削弱法力熔爐的防禦以便讓占卜者進行他們的工作。$B$B去證明你對奧多爾的忠誠，殺掉日怒博學者及守護法力熔爐巴納爾的血守衛。', '殺掉8個日怒博學者及8個日怒血守衛，完成後回到52區找主教歐瑞利斯。為奧多爾完成任務會使你的占卜者聲望降低。', '', '去虛空風暴找52區的大主教歐雷里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10242, 'zhTW', '斷脊氏族崗哨', '$n，我在這裡的裝備，很不幸的，不足以應付我想進行的所有測試。然而，我在斷脊氏族崗哨的同事，藥劑師艾柏瑞克擁有需要的工具。$B$B我已取得了血之谷鮮血的樣本 - 從過去一個索爾瑪密探的任務中獲得的。把樣本帶去給艾柏瑞克讓他研究。$B$B要去斷脊氏族崗哨，就和空軍指揮布拉克談談，他在南邊的雙足翼龍那裡。', '搶奪者荒野的藥劑師席蓮娜要你和空軍指揮布拉克談談以搭乘雙足翼龍到斷脊氏族崗哨，把血之谷鮮血樣本帶給斷脊氏族崗哨的藥劑師艾柏瑞克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10243 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10243, 'zhTW', '那魯的技術', '占卜者拿到了一本法力熔爐巴納爾的人事名冊，目前正在愉快的挑選刺殺對象。$B$B他們遺露了一小點資訊，潦草的書寫在這本名冊的邊緣。看起像是用來進入那魯製的系統密碼或是代碼就像在艾克索達還有風暴要塞的一樣。$B$B到法力熔爐尋找一個控制臺。把控制台裡頭的內容複製在這個捲軸上。我們必須證實我們對這項技術來源的懷疑。', '進入法力熔爐巴納爾找到巴納爾控制臺。為奧多爾完成任務會使你的占卜者聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10244 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10244, 'zhTW', '惡魔搶奪者製造手冊R.T.F.R.C.M.', '撕開這本厚重書卷上的封印之後，你發現你基本上無法理解上面所書文字的內容。它們似乎是用某種惡魔語所撰寫的。$B$B不過，你卻能看明白上面的圖片，並理解了這些圖片所表達的涵義。$B$B很明顯，這是一本惡魔劫奪者的建造手冊，而且，你知道，威勒媽媽一定非常想看看這本手冊！', '將惡魔劫奪者製造手冊帶到虛空風暴的秘境領地裡的領地崗哨給威勒媽媽。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10245 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10245, 'zhTW', '巴納爾控制臺謄本', '你試著將閃過眼前的景象描繪下來。結果雖不甚準確，但應該足以當成證據來證實或反駁奧多爾的懷疑。', '將巴納爾控制臺謄本傳送到虛空風暴的52區給隱士卡爾加。為奧多爾完成任務會使你的占卜者聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10246 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10246, 'zhTW', '攻擊法力熔爐寇魯', '你在法力熔爐巴納爾的成功十分的引人注意。我確信隱士卡爾加將會要你再一次到法力熔爐寇魯重操舊業。$B$B我們已經知道那裡部署了特別重要的一群日怒秘法師及調查員，我要你去攻擊他們。成功的話將是你對敵軍一個決定性的打擊。', '到法力熔爐寇魯去殺掉8個日怒大法師及5個日怒調查員。完成後回報給主教歐瑞利斯。為奧多爾完成任務會使你的占卜者聲望降低。', '', '去虛空風暴找52區的大主教歐雷里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10247 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10247, 'zhTW', '莫米沙博士', '在城鎮東邊的郊區就是試驗場。我們最頂尖的實驗家，莫米沙博士，一直以來都在那邊實驗把惡魔搶奪者、伊斯利人、當然還有我們的哥布林科技結合在一起。$B$B這並不表示我們不感激你在收集上所做的努力，你這個小學三年級程度的技師，$n!$B$B去找他吧;我知道他會有辦法拯救52區的。$B$B既然知道他很可能把你當成實驗的對象，假如我是你，我會帶一些同伴去以免危險。', '去虛空風暴的試煉場裡和莫米沙博士交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10248, 'zhTW', '你，機器人', '我是莫米沙博士，很高興替你服務。來，拿著這個控制器。我要你啟動我的新發明-廢料搶奪者X6000然後讓它活動活動。$B$B但是你不可以離他太遠!遙控器綁在我的控制臺這裡，假如你離太遠，這個機器人就會停止運作。$B$B幫我試試每種功能……在你這次的性能試驗中我會看著你同時測試它的伺服機制。', '啟動廢料搶奪者X6000搖控器然後測試它的功能。然後將你的測試結果回報給虛空風暴的試煉場的莫米沙博士。應付所有發生的問題。', '', '去虛空風暴找實驗場的工程學博士沃米薩。', '完成再造機甲X6000型的測試', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10249, 'zhTW', '回去找主管!', '我確定火箭主管想要跟你說一兩句話!$B$B如果我是你，我會毫不猶豫地回到52區與他談談!', '馬上回報給在虛空風暴裡52區的火箭主管夫斯拉吉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10250, 'zhTW', '血腥的復仇', '東邊有座聯盟的廢棄圍攻哨塔。現在拾荒者在那邊收集戰時遺留下來的舊鐵釘還有一些廢物。好久以前，許多聯盟的士兵們在這座塔失去了他們的生命而他們的軍旗被烏崔克搶走了，他是一個可惡的獸人指揮官。$B$B去聯盟軍旗附近吹響不屈戰爭號角。這將會吸引烏崔克的注意。你同時會召喚出多年前戰死的亡魂。', '在聯盟軍旗附近吹響不屈戰爭號角。殺掉烏崔克後回到斷脊氏族崗哨找歷史家亞登。', '', '去找斷脊氏族崗哨的史學家奧爾森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10251 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10251, 'zhTW', '大師的偉大設計?', '兩位德萊尼昨晚來拜訪我們。他們不知為何知道我們擁有這本書並開出天價想「從我們手中取走這本書」。$B$B我們沒問他們想要用這本書做什麼，但是年輕的那一個一直說著「主人偉大的設計」，無論那表示什麼。$B$B看著，當有錢來時，我什麼問題都沒有。他們給我們許多金子，而我們給了他們這本書。$B$B他說他們住在納葛蘭 - 在泰拉北方，舊的被遺棄的軍械庫那裡。', '找到在納葛蘭被遺棄的軍械庫的博學者奈崔恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10252, 'zhTW', '死者的視界', '事情早就開始了。勒威薩斯站在奧齊頓的廢墟頂端唸誦著亡者之書。他藉由死者的名字喚醒他們，然後透過惡魔的儀式來約束那些可憐的靈魂聽從他的命令。假如有機會的話他將會喚醒整個奧齊頓的亡者!$B$B但是……你必須做好事前的準備。你不能跟你看不見的敵人戰鬥。$B$B<奈崔恩給你一張羊皮紙。>$B$B將我要製作藥劑的物品交給我。它將會打開你的眼界並且讓你看見靈界。', '納葛蘭裡被遺棄的軍械庫的奈崔恩要你為他帶來1個山地古羅眼珠，1個無瑕的巨型風翼貓頭鷹之啄和1份老邁的裂蹄油。', '', '去找納格蘭的博學者尼特林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10253, 'zhTW', '靈魂呼喚者勒威薩斯', '現在就去，$n。你可以在奧齊頓最高的廢墟發現勒威薩斯。從白骨荒野南方的區域進去那裡。他就站在一場靈魂的暴風當中……$B$B殺掉他並取回亡者之書。一旦你取得這本詛咒之書，毀掉它!毀掉它好讓這樣的暴行永遠不會再出現。', '殺掉勒威薩斯並且取走他的亡者之書。將亡者之書交付給在奧齊頓的奧奇奈地穴入口外的瘋狂的藍姆多。你有一個交易，記得嗎?', '', '去泰羅卡森林的奧金頓找瘋狂的拉姆杜爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10254, 'zhTW', '軍隊指揮官達納斯·托爾貝恩', '<治安官伊斯歐朵爾拍了拍身上的塵土。>$B$B嗯，該是你工作賺取薪資的時候了。馬上去跟要塞的軍隊指揮者托爾貝恩回報。他跟他的顧問團毫無疑問的會很高興迎接你。$B$B<治安官伊斯歐朵爾立正跟你敬禮。>$B$B為了聯盟!', '治安官伊斯歐朵爾要你向榮譽堡的軍隊指揮官達納斯·托爾貝恩回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10255, 'zhTW', '測試解毒劑', '我想血液裡有某種東西可以拿來作為解毒劑的基礎原料。不要用那種好像我瘋了的眼神看我!$B$B這在大自然中是基本準則。常常，解藥就來自於自身的毒素。那就是我準備要做的事。$B$B解除這些野豬身上的惡魔作用可能可以消除他們的侵略性並且讓我們了解如何能夠有效的幫忙其他種類的生物。', '將恐牙的鮮血樣本使用在地獄野豬身上並觀察結果。一旦你知道實驗的結果後，回到地獄火半島的塞納里奧前哨找塞伊亞·紅髮。', '', '去地獄火半島找塞納里奧哨站的塞安·紅鬃。', '測試解毒劑', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10256, 'zhTW', '找到鑰匙持有者', '回想起來，我以為我本該預料到凱爾薩斯的魔法會如此的堅固。他一直是一位有才華的法師，但是我從未見過他在攻擊高塔時所運用的力量。$B$B守衛讓我無法用水晶球占卜出適當持有的那股力量的事物，但是卻無法阻止你的占卜。$B$B不過，你會需要一個集中。有一個背負水晶的巨人，名為艾派斯巨人，它遊蕩在法力熔爐杜羅西邊的平原上。一顆它的水晶將會是極好的占卜集中。', '找到艾派斯巨人並且從他那裡取得艾派斯巨人的水晶集中。回到紫蘿蘭之塔並且在大法師 瓦戈斯的寶珠附近使用艾派斯巨人的水晶集中，以找出誰握有打斷那些塔之詛咒的關鍵。', '', '去虛空風暴找紫羅蘭之塔的大法師瓦格斯。', '查明鑰匙在誰手中', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10257, 'zhTW', '取得拱心石', '我不訝異凱爾薩斯將鑰匙交給像是指揮官薩瑞尼斯那樣的守衛持有。凱爾薩斯王子是個日理萬機的人，但是他不是傻子。$B$B為了永遠消滅這個禍害，你必須進入風暴要塞並且得到拱心石。$B$B只有毀掉拱心石，我才能恢復自由。', '冒險進入風暴要塞的波塔尼卡從指揮官薩瑞尼斯身上取回拱心石。將它帶給紫蘿蘭之塔的大法師瓦戈斯。', '', '去虛空風暴找紫羅蘭之塔的大法師瓦格斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10258, 'zhTW', '榮耀失落者', '軍械庫的指揮官霍卡爾斯，位在東邊的塔內。你必須向他回報打敗烏崔克的消息。他會友善的對待你嗎?當然他也有可能會試著摧毀你的靈魂。你永遠都不知道像他們這種亡魂的想法。$B$B不屈者仍然對我們懷有敵意而且假如他們可以的話他們會毫不猶豫的殺死你。請小心$n。', '向遠征隊軍械庫的指揮官霍卡爾斯回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10259, 'zhTW', '進入裂縫中', '入口的戰鬥一直都在激烈進行著!銀色黎明正在進行一場絕望的戰爭 -- 而且如果我們失敗，惡魔之火將永無止盡。$B$B幫助我們，$n。進入這條裂縫去協助我們的兄弟姐妹。幫忙抵擋這股黑暗的浪潮!銀色黎明 -- 和這個世界 -- 需要你!', '殺掉6個入侵的惡魔守衛，然後回去找銀色特使波特威歐。', '', '去詛咒之地找黑暗之門的銀色使者普羅維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10260, 'zhTW', '虛空學家卡伯尼寇斯', '你一定是穿過了那座由刀鋒山連線虛空風暴的橋才來到這裡的。你也一定看見Netherologist Coppernickels和他那些瘋狂的研究裝備了吧？$B$B奇怪……我還在等著他的報告呢，已經遲到太久太久了。他一定是把這事給忘記了。你知道那些“科學家”的，忙起來什麼都忘了。$B$B立刻回到橋邊幫我逮住他，馬上要來他的報告，無論他說什麼藉口都不行。$B$B謝謝你了！', '轉至刀鋒山與虛空風暴相連線的橋邊尋找Netherologist Coppernickels，並與他交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10261, 'zhTW', '懸賞:殲滅者伺服電動機!', '懸賞:1部殲滅者伺服電動機以替換我的長頸光譜分析器裡故障的那一部。$B$B你和你朋友可能想要與西邊法力熔爐巴納爾裡的血精靈詢問看看是否他們有任何備用品。他們好像有一些秘法殲滅者四處散置著。$B$B請把原始的伺服電動機交給52區的威勒老爹。', '取得一部殲滅者伺服電動機，並且將它帶回虛空風暴的52區交給威勒老爹。', '', '去虛空風暴找52區的維勒老爹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10262, 'zhTW', '一堆伊斯利', '有另外一件事需要你來幫忙。$B$B有一群叫做薩希斯的伊斯利，已經與聯合團斷絕關係並開始自食其力。他們也與日怒血精靈斷絕往來了。這是不被容許的!$B$B我滲透進入他們在聚集之地南邊的團體。但在我解決掉他們的領導者後，我就得逃離這到52區去。$B$B$c，到那裡去帶回他們的徽記。當然，因為他們是懦夫所以不是每個人都有將徽記配戴起來。', '收集10枚薩希斯徽記，並且將它們帶回虛空風暴的52區交給虛空行者凱澤。', '', '去虛空風暴找52區的虛空獵手卡爾伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10263, 'zhTW', '協助聯合團', '撒塔斯城的那魯已經試圖找出一個方法引領聯合團協助他們尋找的進度。$B$B幸運的是伊斯利和虛空風暴的血精靈之間的生意關係最近變糟了。$B$B城裡有一名聯合團的代表名叫虛空行者凱澤，最近陷入一幫伊斯利叛徒的麻煩中。作為一名占卜者的代表，我要你盡你所能的去幫助他。', '到虛空風暴的52區找虛空行者凱澤談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10264, 'zhTW', '協助聯合團', '撒塔斯城的那魯已經試圖找出一個方法引領聯合團協助他們尋找的進度。$B$B幸運的是伊斯利和虛空風暴的血精靈之間的生意關係最近變糟了。$B$B城裡有一名聯合團的代表名叫虛空行者凱澤，最近陷入一幫伊斯利叛徒的麻煩中。作為一名占卜者的代表，我要你盡你所能的去幫助他。', '到虛空風暴的52區找虛空行者凱澤談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10265 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10265, 'zhTW', '聯合團水晶收集', '我們領導人，奈薩斯王子哈拉瑪德，派我帶著一顆取自阿克隆廢墟的水晶手工品到東南方去。$B$B那些都是老舊的德萊尼廢墟。對在這裡的我和這個哥布林來說不幸的是，燃燒軍團已經決定進駐好進行他們自己的挖掘工作。$B$B如果你願意幫助我，到廢墟去並向名為潘塔斯阿諾的恐懼領主那取回那個水晶手工品。', '取得阿克隆水晶手工品，並且將它帶回虛空風暴的52區交給虛空行者凱澤。', '', '去虛空風暴找52區的虛空獵手卡爾伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10266 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10266, 'zhTW', '要求幫助', '在你在阿克隆廢墟的時候，我收到一個來自我們領土外的代表之一尋求協助的要求。好像是聯合團在設法從拒絕支付的血精靈那收回資產的過程中有一些「困難」。$B$B請往52區外的東邊前進然後越過橋到下一座島嶼。你就會找到我在領地崗哨的同事，加魯，就在秘境領地內。', '尋找並提供加魯你的幫助。他就在虛空風暴的秘境領地裡的領地崗哨。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10267 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10267, 'zhTW', '合法的回收', '我們與血精靈的貿易關係看來好像到了尾聲。幾個星期前就把一大批勘察設備的貨品送到法力熔爐杜羅交給他們了。他們拒絕付款。$B$B$n，我要你到東邊的法力熔爐杜羅去拜訪那裡的血精靈。他們那裡似乎有一些法力生物侵擾的麻煩，佔據了他們所有的心思。$B$B我不關心他們發生了什麼事，不過我非常想見到我們的財產歸還。', '收集10箱勘探設備帶回虛空風暴秘境領地的領地崗哨給加魯。', '', '去虛空風暴找中央生態圓頂的加魯斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10268 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10268, 'zhTW', '晉見王子', '奈薩斯王子哈拉瑪德已經傳達要我知道他對於馬上要親自送回給他的這個物品很感興趣。 如果你可以代替我將它送回去的話我會很感激你的。$B$B獲得奈薩斯王子的接見是一種莫大的榮譽，而我相信他會對你在虛空風暴這裡冒險的故事非常感興趣。$B$B到風暴之尖北方山頂上找出他的居所。他經常以全身影像現身，就是你可能會對話的對象。', '將勘探設備送到虛空風暴的風暴之尖交給奈薩斯王子哈拉瑪德的影像。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10269 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10269, 'zhTW', '三角測量點之一', '有另一個需要取回測量設備的原因。這裡有一顆來自於對我至關重要的德萊尼傳說的水晶。$B$B傳說這顆水晶會給予持有者如神一般的力量!不過現在有著被其他人發現的危險 - 就是燃燒軍團。$B$B$n，帶著這個設備並用它來找到第一個三角測量點。我們知道它在東邊靠近法力熔爐奧崔斯的某處。$B$B完成後，去找我的密探報告，商人海辛，就在法力熔爐奧崔斯的那座島上。', '使用三角裝置指引你前往第一個三角測量點的方向。一旦你找到它，把位置報告給虛空風暴法力熔爐奧崔斯島上護國者哨站的商人海辛。', '找到一號三角測量點', '去虛空風暴找維序派哨站的商人哈斯辛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10270 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10270, 'zhTW', '一個不太謙虛的提議', '從你臉上的表情看來，我可以判斷你是一個$r知恩圖報的人。$B$B身為一位新奇商品的商人我已經建立起一個良好的聲譽，而且我差不多要開發一個新商機了。$B$B我需要一個靠得住的承包商去取得來自天國山脈的貨品。$B$B首先，你會需要重新補充一個傳送平台的電源。在礦井之路通道那有多餘的力量背包，就在法力熔爐奧崔斯的南方。護國者在那生活，因此你可以跟隨著他們的足跡到達你的目的地。', '取得傳送力量背包並將它帶到法力熔爐奧崔斯東方的天國山脈的伊斯利傳送器去。啟動這個平臺並將傳送力量背包交給風之貿易者瑪利德的影像以便他能夠安裝它。', '', '去虛空風暴的蒼穹之脊並使用虛靈傳送器找星界商人瑪裡德的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10271 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10271, 'zhTW', '動手幹活', '就你真實所見，這地區充滿各個成長階段的虛空龍族。所有的虛空龍族，年輕的和老的，都含有一種 K -- 呃，我的一位客戶，非常想要的精華。$B$B大部分的人不願意冒著生命危險去收集，因此這地方就屬於我們的。你可以從藉由收集這裡任何生物的精華開始，不過重要的是我們馬上要著手發展出一個供給出來。一旦你收集到第一批了就回到我這裡來。', '收集8個虛空龍精華然後回到伊斯利傳送器地區。你可以從虛空龍或者虛空龍身上取得虛空龍精華 。', '', '去虛空風暴的蒼穹之脊虛靈傳送器區域。找到隱蔽的身影並與其對話。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10272 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10272, 'zhTW', '一個有希望的開始', '我們到這來是調查一個有關新奇品種的龍的謠言，或許可以說是死亡之翼本身的後裔。雖然，這些很明顯的不是普通的黑龍。$B$B一旦我們有機會檢驗他們的蛋，我們就會知道的更多。他們對我的飛行敵意愈來愈深，因此我無法過度深入去收集這些蛋。你會願意幫助我嗎?', '收集15個虛空龍族的蛋，完成後返回天國山脈的泰利和喬洛德那裡。', '', '去虛空風暴找蒼穹之脊的泰莉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10273 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10273, 'zhTW', '討人厭的傢伙', '你的前雇主，風之貿易者瑪利德，一定是收到了你正在幫助我們的風聲。根據我的推測，我曾經看過他的虛空行者來到這裡，希望找出我們的下落。$B$B目前為止我們都可以逃過他們的追蹤，但是在問題變的更嚴重之前瑪利德必須處理掉。$B$B假如你對瑪利德的印象是正確的話，他將會為了保住產品的供應而不擇手段。回去找他然後告訴他你準備提出一項交易。將他引誘出來然後殺死他。', '跟風之貿易者瑪利德交談並且引誘他離開交易站。殺死他然後回去天國山脈找泰利還有喬洛德。', '', '去虛空風暴找蒼穹之脊的泰莉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10274 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10274, 'zhTW', '保衛天國山脈', '虛空龍與他們黑龍祖先有著完全相同的兇猛性格，不過他們還是有完全相異之處。他們迅速的孵化及成長，駕馭德拉諾內加速他們種類的奇異能量。$B$B關於他們我還有非常多的事情需要了解，不過我相信這些力量可能對我自己的飛行有用途。如果我們能取代這些龍的領導者維拉庫，向他們展現我們的力量，我們就能屈服剩下的虛空龍。', '使用藍龍軍團的挑戰在天國山脈的南方邊緣上激怒維拉庫。打敗他並且回到天國山脈的泰利和喬洛德那裡。', '', '去虛空風暴找蒼穹之脊的泰莉。', '消滅維拉庫', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10275, 'zhTW', '三角測量點之二', '我參考了你所提供源自第一點的資料重新校正了三角裝置。你能夠以相同的方式精準的找到第二個測量點。$B$B我能告訴你的全部資訊就是第二個測量點在遙遠的西方某處。$B$B一旦你找到它，去與風之貿易者吐魯曼，另一個奈薩斯王子的密探談談。他在通往法力熔爐艾拉所處島嶼的橋邊一個小型貿易站冒充武器商人。', '使用三角裝置指引你前往第二個三角測量點的方向。一旦你找到它，將位置報告給在虛空風暴的吐魯曼平臺的風之貿易者吐魯曼，他就在從法力熔爐艾拉島出來的橋的另一邊。', '找到二號三角測量點', '去虛空風暴找圖魯曼的營地的星界商人圖魯曼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10276, 'zhTW', '完整三角形', '有了第1個和第2個據點的資料，我現在確定水晶就在東北方的法拉隆廢墟最上方。$B$B不幸的是，資料顯示水晶正在移動，這代表它已經被發現了，可能是被燃燒軍團發現了!$B$B為了以防萬一，我建議你帶著一些朋友一起去。$B$B殺了持有水晶的惡魔，並且把它送回給奈薩斯王子哈拉瑪德。', '取回阿塔莫水晶並且將它帶到虛空風暴的風暴之尖交給奈薩斯王子哈拉瑪德的影像。', '', '去虛空風暴的風暴尖塔找節點親王哈拉邁德的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10277 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10277, 'zhTW', '時光之穴', '你好，$n。請跟著管理人。她將把事情弄得……更清楚一點。', '在時光之穴的安杜姆要你跟隨洞穴附近的時間管理人。', '遊覽時光之穴', '去塔納利斯找時光之穴的安多爾姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10278, 'zhTW', '扭曲裂縫', '長久以來我都在外域遊蕩，探索虛無的本質。現在我又老又虛弱。也許你會幫助我?$B$B我一定要知道虛無行者的秘密。你必須先到西邊的扭曲原野尋找。就在遠征隊軍械庫的西邊有一個陰暗的角落座落在坑道的深處，在那邊時間跟空間都很虛弱。在扭曲原野使用我的不穩定的扭曲裂縫生成器製造一個扭曲裂縫。你一定要從扭曲裂縫出現的那些生物身上蒐集扭曲虛空。', '在扭曲原野使用不穩定的扭曲裂縫生成器。從不穩定的虛無行者身上收集3個扭曲虛空，帶回斷脊氏族崗哨交給瘋狂的歐卡司。', '', '去地獄火半島找斷脊氏族崗哨的瘋狂的歐加斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10279 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10279, 'zhTW', '前往主人的巢穴', '啊，$n。我們一直期待著你的到來。請允許我的兄弟之一載你飛到主人那裡。他在下面等你……', '與時光之穴的安杜姆談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10280 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10280, 'zhTW', '給撒塔斯城的特件', '我是個信守承諾的伊斯利，$n。你的確鼓舞了我。$B$B我現在要將阿塔莫水晶交給你送去給那魯。而就是你的英勇行為將這變得可行，我希望你能將這東西送過去。$B$B你可以使用我私人傳送器直接到達撒塔斯城。直接踏進去就會將你傳送到那了。$B$B將這個水晶交給一個在聖光露臺叫做阿達歐的那魯。祝你一路順風。', '將阿塔莫水晶送交到撒塔斯城的聖光露臺交給阿達歐。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10281, 'zhTW', '正式自我介紹', '你好，$n。不要被我嚇到。這只是我現今形態的投影罷了。這是讓我跟我的同伴可以不用現身而能繼續觀察的唯一方法。$B$B之前接近你的那個伊斯利，瑪利德，只比偽裝合法商人的騙子好一點點而已。我想要你考慮一下轉而跟我合作。我來這的目的就是想在這個山脊發現更多不尋常龍種的資料。到北邊山脊的盡頭找我然後我們進行近一步的深談吧。', '在天國山脈的北端找到泰利並與她談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10282, 'zhTW', '舊時的希爾斯布萊德', '向西走是希爾斯布萊德的時間之道 - 準確地來說就是7年前。$B$B敵軍正在對付部落酋長，索爾，試圖阻止他逃出敦霍爾德城堡。$B$B假如索爾從未逃出來，這個世界 - 如你現在認識的 - 將不復存在。$B$B召集一群冒險者經由時間通道到舊時的希爾斯布萊德。我們的兩位密探在裡面等著你們。$B$B去與另一邊的伊洛森談談。', '時光之穴的安杜姆要你到希爾斯布萊德丘陵去跟伊洛森談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10283, 'zhTW', '塔蕾莎的聲東擊西', '塔蕾莎在索爾的生存、教養以及塑造索爾的人生上面是不可或缺的一個人。$B$B塔蕾莎也是最初在敦霍爾德城堡幫索爾分散敵人的注意力，讓索爾可以逃出去的人。$B$B現在永恆之龍捉住了塔蕾莎並且把她關在塔倫米爾。少了我們的幫忙，拯救索爾的機會就不會出現。你必須使用我給你的縱火裝置燒毀敦霍爾德城堡的拘留所。完成之後，去跟敦霍爾德城堡的年輕的索爾談話，他是被關在地下室的囚犯。', '前往敦霍爾德城堡，使用伊洛森交給你的燃燒炸彈包裹在每一個拘留守衛室裡的桶中放置5個燃燒炸藥。當你引爆拘留守衛室後，與敦霍爾德城堡地牢裡的索爾談談。', '', '去找索爾。', '點燃收容所', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10284, 'zhTW', '逃離敦霍爾德', '你現在看著我只看得見一個男孩的型體，但是在我的心靈以及靈魂裡隱藏著我的夢想。 我對我的族人有所計畫，陌生人。有一天，他們會推翻他們的迫害者，並且起而為一。他們會從禁錮他們束縛中解放出來並起義形成獸人部落。$B$B我承諾你，陌生人，萬一我們可以活著離開這裡，當我有方法酬謝你這樣無私的行為時，我會去找到你……我會去找你。$B$B<索爾點頭。>$B$B當你準備好我們就出發。', '當你準備開始時，讓索爾知道。跟著索爾離開敦霍爾德城堡，並協助他釋放塔蕾莎以及完成他的天命。任務完成後到希爾斯布萊德找伊洛森談談。', '', '去找舊希爾斯布萊德丘陵的伊洛希恩。', '完成索爾的命運', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10285, 'zhTW', '回去安杜姆身邊', '時間線已經恢復正常而恆龍軍團在希爾斯布萊德之上的戰役已經平息了。$B$B馬上回去找安杜姆。他在主人的巢穴等著你。', '回去塔納利斯沙漠的時光之穴找小孩安杜姆 。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10286, 'zhTW', '阿利恩的秘密', '阿利恩的日記並沒有論及任何學者的研究。裡面詳述了他跟一個年輕的女血精靈所做出的越軌行為!我怎麼會那麼笨呢?$B$B很可惜，那個放蕩女人的身份並沒有出現在這本日記中。阿勒迪斯是阿利恩的同事兼好友跟知己。去問他並且找出阿利恩的外遇對象。$B$B我當初看到阿勒迪斯離開獵鷹哨站前往贊格沼澤。順著城鎮的馬路往北走，最後會往西通往贊格沼澤。', '博學者卡莉達要你詢問博學者阿勒迪斯，據說有人看到他從獵鷹哨站前往贊格沼澤。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10287, 'zhTW', '情婦曝光', '我是阿利恩的朋友，但是我不會為了他而被毒打一頓。他的情婦是薇艾拉·陽語。$B$B去告訴他那個凶暴殘忍的妻子。她又能怎麼辦呢?', '回去找獵鷹哨站的博學者卡莉達。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10288, 'zhTW', '抵達外域', '我要你與艾米思·蠻錘談談，你往南邊走大約30步的地方，並且搭上第一班飛往榮譽堡的航班。當你到達榮譽堡時，治安官伊斯歐朵爾將迎接你。我已經準備好一份報告詳述我們在這裡的情況。給他這份報告，並且告訴他你已準備好要出任務了。$B$B你已經接到命令了，士兵，現在出發吧!並且雖然你體內的滿腔熱血一定很幫助我們對抗下面的惡魔，但是不要在這裡浪費時間。榮譽堡更需要你的幫助。', '地獄火半島的黑暗之門的指揮官杜朗要你將杜朗的報告送到艾米思·蠻錘的手中。', '', '去地獄火半島找命運階梯的阿米什·蠻錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10289 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10289, 'zhTW', '前往索爾瑪', '當你準備好時，我將召喚雙足翼龍空運你到索爾瑪。到達之後，將歐萊恩的報告交給克洛克爾克將軍。$B$B為了部落，$n - 祝你好運。', '搭乘法拉格·伏瑞菲德的雙足飛龍到索爾瑪。將歐萊恩的報告交給克洛克爾克將軍。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10290 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10290, 'zhTW', '尋找法拉萊特', '東北方有一個叫做虛空石的地方，過去那邊是一片綠意盎然的土地，人們還看不見被現在的人們稱為虛空石的著名地標。最近暴露的水晶地層蘊含一種礦物，我們稱之為法拉萊特，以紀念這塊土地的前身。$B$B我們已經開採小量的法拉萊特，並且事實證明很受顧客的青睞。最高等級的礦物並非來自大地的靜電蘊含量，而是來自虛空石周遭的那些巨人。如果你能提供高等級的法拉萊特，我就能分給你一部份的利潤。', '收集四個天然法拉萊特然後交給風暴之尖的祖班·艾貞努比。', '', '去虛空風暴找風暴尖塔的伊格努比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10291 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10291, 'zhTW', '回報納茲格雷爾', '雖然我們的戰士們曠世無雙，但是我們在這塊荒地的控制權仍然薄弱。到軍營裡面向納茲格雷爾報告 - 他需要可以執行特殊任務的人員……就像你一樣。如果我們不能保護我們在這裡的領地，我們將對任何人都無用處。現在去吧!', '索爾瑪的克洛克爾克將軍要你去跟納茲格雷爾談話。', '', '去地獄火半島找索爾瑪的納茲格雷爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10292 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10292, 'zhTW', '更多能量！', '小規模地採集珍貴物資帶有一種原始而低等的作坊經濟的感覺，這種方式在如今的市場經濟時代已經了失去競爭力。$B$B我們迫切需要找出大量開採和生產法蘭石的方法！這樣的話，流入市場的法蘭石量將完全掌握在我們手中。$B$B我有個法子，不過這需要一個強大而集中的能量源。唯一可能找到這種強大的能量源的地方就是燃燒軍團的營地。轉至此地以北的軍營，偷幾尊火炮回來。', '伊格努比要你將8尊軍團火炮帶回風暴尖塔。', '', '去虛空風暴找碎裂廢土的伊格努比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10293 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10293, 'zhTW', '摘下母礦', '現在我們有了一個好的基本產品，就會需要一些更高品質的東西。當然目前為止我們取得的法拉萊特很好，不過我知道還有更好的。$B$B我們得直接從法拉隆巨人的族主，奎克史卡爾身上取得一份樣本!你可以在虛空石地區的其他巨人群中找到它。它背後延伸出的一大片法拉萊特正好就是我們要的東西。擊倒這個巨人並將法拉萊特核心帶回來。', '風暴之尖的祖班·艾貞努比要你取得一個法拉萊特核心。', '', '去虛空風暴找風暴尖塔的伊格努比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10294 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10294, 'zhTW', '虛無之脊', '我們必須改良我的扭曲裂縫生成器。你必須把它帶到虛無山脈。由這裡向東走。你必須避開薩斯葛爾這污穢的堡壘。往東在薩斯葛爾之外有一個小通道穿過群山。穿過這條通道你將發現虛無山脈，在深淵邊緣上的一個可怕的地方。$B$B你必須殺死你在那裡發現的怪物，並且為我帶來他們靈魂的裂片。有了裂片的力量我們就能改良扭曲裂縫生成器，並且打開通往更遠處的入口，而使入口不被關閉。', '去虛無山脈並且殺死你找到的生物。收集40個虛無山脈靈魂裂片，並且交給斷脊氏族崗哨的瘋狂的歐卡司。', '', '去地獄火半島找斷脊氏族崗哨的瘋狂的歐加斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10295, 'zhTW', '來自深淵', '我的扭曲裂縫生成器完成了。你現在能使用它召喚虛無裡真正的王子，他的靈魂裂片將告訴我們許多虛無世界裡的事物。$B$B往南到虛無山脈，並在虛無石附近使用我的扭曲裂縫生成器。你要在在深淵的邊緣附近尋找一叢水晶。一道巨大的扭曲裂縫將形成，而虛無男爵·加倫希斯肯定將出現。$B$B消滅這生物並將他的靈魂裂片帶來給我。', '殺掉虛無男爵加倫希斯並收集他的靈魂裂片，將這個裂片帶給斷脊氏族崗哨的瘋狂的歐卡司。', '', '去地獄火半島找斷脊氏族崗哨的瘋狂的歐加斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10296 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10296, 'zhTW', '黑色沼澤', '恆龍軍團已經放棄了一些無謂的小動作。他們計畫要殺死守護者麥迪文並且阻止黑暗之門讓它永遠無法開啟。雖然表面上來說，這對聯盟來說是個好消息，但事實上他們的行動將帶來災難並且毀滅整個世界。$B$B你必須穿過時間之道到達黑色沼澤。先往西邊再往南邊，經過未來的我，直到你到達充滿沼澤樣本的通道。穿過去然後跟塞特交談。', '在黑暗之門開啟的期間經由穿越時光之穴到達黑色沼澤，並與塞特交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10297 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10297, 'zhTW', '黑暗之門的開啟', '在時間之道的前方，黑色沼澤的中央地帶，守護者麥迪文正在開啟黑暗之門，宣佈著艾澤拉斯的獸人時代即將來臨。$B$B恆龍軍團派出了他們的裂縫領主去阻止這件事的發生。$B$B散佈在沼澤四周的裂縫領主將會現形。恆龍軍團的裂縫領主將會傾巢而出試著摧毀麥迪文的防禦網，最後是麥迪文本人。$B$B殺死他們的裂縫領主還有領導者!持續你的保護行動直到麥迪文成功開啟黑暗之門。當你需要協助的時候就使用這個時間信號燈。', '在時光之穴的黑色沼澤裡的塞特已給予你保護麥迪文直到他成功打開黑暗之門的任務。任務完成後，回到塞特那裡。', '開啟黑暗之門', '去找黑色沼澤的薩艾特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10298 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10298, 'zhTW', '世代的拯救者', '返回到安杜姆這個孩子的身邊，$n。他在這時間之袋外邊等待著你，就在主穴裡。$B$B我聽到許多關於讚美你的話語。流沙之鱗已經對你的能力表示興趣。或許他們也想與你談話。', '回去塔納利斯沙漠的時光之穴找安杜姆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10299 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10299, 'zhTW', '關閉法力熔爐巴納爾', '我們不能憑藉武力關閉法力熔爐，因為我們將冒著造成大爆炸的危險，後果可能會將外域移成平地。$B$B依據你的謄本，有一種永久癱瘓法力熔爐科技的緊急關機方法 - 一個在那魯架構中常見的安全機制。$B$B要進行此程序，你必須先取得開啟控制台的一顆水晶。根據我們的情報，這顆開啟水晶被一個叫做瑞爾迪斯的監督者所持有。', '回到法力熔爐巴納爾從監督者瑞爾迪斯身上取得巴納爾控制水晶。使用它來關閉法力熔爐巴納爾控制臺然後回報隱士卡爾加。為奧多爾完成任務會使你的占卜者聲望降低。', '', '去虛空風暴找52區的學者卡爾亞。', '', '關閉法力熔爐：布納爾', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10300 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10300, 'zhTW', '重鑄法杖', '<羅樊德威檢查了法杖，發現法杖的頭部缺了一小塊。>$B$B真粗魯啊!艾克爾拉斯一定是把法杖頭部的結晶給拔下來當做裝飾品掛在別的地方，他一點都不了解 法杖的頭部結晶要跟法杖其他的部位一起作用才會生效。$B$B只要法杖一天不完整，它的魔力就會大幅度的縮減。只要有大小合適的德萊尼結晶，我應該就可以修好它。我曾經聽哥布林談到北邊的安卡特廢墟的鬼魂就有這種結晶。', '從安卡特廢墟的鬼魂身上取回四個無瑕水晶裂片並且交給52區的羅樊德威。', '', '去找虛空風暴52區的拉文德維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10301, 'zhTW', '開啟手冊', '我很高興大多數卡薩斯的手冊取回了，但是沒有紫羅蘭眼睛的話，也是沒用的。你要明白，卡薩斯完全知道記錄在書中之咒語的全然力量，並且採取措施保護他們免於他人窺探。$B$B只有知識淵博的魔法師能使用紫羅蘭眼睛解開手冊的秘密。$B$B在凱爾薩斯攻擊期間，他的其中一名軍官，法術剝奪者瑪拉希歐，將它掠奪到塔東北方的日怒要塞。無疑地，她認為它是一個漂亮的小玩意。', '從日怒要塞的法術搶奪者瑪拉希歐身上取得紫羅蘭眼睛。完成之後使用大法師瓦戈斯之杖與大法師連絡。如果你遺失了大法師瓦戈斯之杖，與52區的羅樊德威交談以取得一個替代品。', '', '使用大法師瓦格斯的法杖與大法師取得聯絡。$B$B如果你不小心遺失了大法師瓦格斯的法杖，可以向52區的拉文德維爾再要一根。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10302, 'zhTW', '暴躁突變者', '來自艾克索達散發輻射的能量核心一直對這裡的環境造成浩劫。最明顯的效應是，它們附近開始出現一些奇怪的生物。$B$B也許我們能做些事情去幫助他們，但是現在，他們十足的數量已非我們的能力所能處理了。$B$B我要你去削減他們的數量，或許給我一點時間思考，我將有別的辦法對付它們。', '殺死8個暴躁突變者，然後返回安曼谷的失事地點的植物學家泰瑞茲那裡。', '', '去找埃門谷墜毀點的植物學家塔蕾克絲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10303, 'zhTW', '血精靈', '你必須消滅……血精靈……威脅。查明……他們目的……是甚麼!$B$B他們在我後面的山脊上。', '殺死10個血精靈斥候，然後返回安曼谷裡暗影山脊的托蘭那裡。', '', '去埃門谷找暗影山的圖蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10304, 'zhTW', '復仇者艾德', '有了你的幫忙，我們已經可以比想像中還快的找到解決的方法。我沒有別的工作要交給你。我和我的學徒們可以完成剩下的事情。你應該去船的另一邊跟復仇者艾德談話。', '與安曼谷裡失事地點的復仇者艾德談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10305 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10305, 'zhTW', '貝馬拉', '這本陳舊，堅固的書籍不是咒語書，而你可能認為一個肯瑞托法師會攜帶它。書中的內容佈滿了手寫的故事，伴隨豐富多彩的插圖。$B$B這本書籍好像比它之前的擁有者還要古老許多，甚至可能是一件傳家之寶。書中蘊含了一個強烈的羈絆，很可能就是把貝馬拉的靈魂榜定在肯瑞瓦廢墟的緣由。把書放回她住所書架上適當的地方或許可以幫助安撫她焦躁不安的靈魂。', '找到貝馬拉在巫師街的所在處然後把書放回他的書櫃。完成後，與肯瑞瓦村莊的管理者戴沃斯談談。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '讓貝爾瑪拉的靈魂安息', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10306, 'zhTW', '咒術師盧瑞斯', '這件披風，肯定是以高等精靈技術，還有肯瑞托的規格華麗地裁製而成。這些繡在布料上的符號及特徵對你沒有任何意義，但明顯地這件衣服處處充滿著魔法屬性。$B$B或許這個物品將前一個擁有者的靈魂與這個平面的實體物綁束在一起。如果是如此，將它送回咒術師盧瑞斯住處的衣櫃那也許可以打破靈魂與這個世界的連結，讓它安息。', '找到咒術師盧瑞斯在巫師街的所在處並且把披肩放回他的衣櫃。然後，跟肯瑞瓦村莊的管理者戴沃斯談話。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '讓魯米拉斯的靈魂安息', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10307, 'zhTW', '考林·織霜者', '看看這頂帽子，你不禁想知道是否有任何肯瑞托法師擁有這樣的一頂帽子。從帽子的磨損研判，看來這個地精沒有它就沒辦法出門了。$B$B你馬上試戴了這頂帽子，發現一股魔法屬性讓人有想跳舞的微弱衝動。$B$B這個珍貴物品也許是這個死掉的法師與這個村子間的關聯來源。將這頂帽子放回考林住處的小提箱裡也許可以解放這個靈魂。', '找到考林·織霜者在巫師街的所在處並且把帽子放到它的小提箱裡。然後，跟肯瑞瓦村莊的管理者戴沃斯談話。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '讓考利恩的靈魂安息', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10308 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10308, 'zhTW', '另一支伊斯利勢力', '', '', '', '去虛空風暴找52區的虛空獵手卡爾伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10309 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10309, 'zhTW', '有心臟的惡魔搶奪者', '你看見南方那邊廢棄的惡魔搶奪者了嗎?它真美，對嗎?$B$B我想要它的心!$B$B什麼?是的，當然它有一顆心……誰沒有呢?$B$B<閔坎普憤怒了一會兒。>$B$B去到那裡，把它撬開，帶回我想要的，而我將給你一份優渥的費用作為報答。$B$B喔，如果我是你，我會帶一兩位朋友去。這些薩希斯可是相當暴躁的一群伊斯利!$B$B帶著這個惡魔電擊器，當你準備好要開始時，啟動惡魔搶奪者的心。', '取回惡魔搶奪者之心，並且把它交付給虛空風暴的聚集之地的閔坎普。', '', '去虛空風暴找機甲廢場的米西·米恩卡普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10310 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10310, 'zhTW', '破壞星移門!', '因為惡魔搶奪者廢棄場附近的燃燒軍團，我們得盡我們所能阻止惡魔進入這一區。$B$B他們在南方一處他們稱之為侵略點:摧毀者的地方有一座星移門。$B$B我需要你和我一起前往這個地區並在我破壞門的時候保護我的安全。$B$B之後，到北邊的秘境領地裡的領地崗哨通知加魯我們成功了。$B$B我們得需要一到兩個你的朋友一同隨行。', '護送迪耶亞到位於侵略點:摧毀者的星移門，並注意在他破壞門的時候保護他的安全。完成後到虛空風暴上秘境領地裡的領地崗哨找加魯談談。', '破壞燃燒軍團遷躍門', '去虛空風暴找中央生態圓頂的加魯斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10311 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10311, 'zhTW', '迪耶亞需要你的幫助', '$c，真高興你可以幫上我的忙。$B$B燃燒軍團在附近的惡魔搶奪者們越來越肆無忌憚了，讓我開始擔心我們的安危。那些惡魔時常從南邊的侵略點:摧毀者得到增援部隊。$B$B我的同伴，迪耶亞跑去那邊偵察狀況並且看看他能夠做些什麼來破壞燃燒軍團的星移門。$B$B請你找到他並且盡你所能的幫助他。', '與虛空風暴的侵略點:摧毀者附近的迪耶亞交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10312 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10312, 'zhTW', '肯瑞瓦的記錄', '安息那些幽靈不會如我們所希望的一樣減緩他們的侵略行為。你制服的惡靈已在鎮上的街道再度出現。$B$B我們必須揭露背後的起因。肯瑞瓦的災難才正開始，要不然幽靈現在已經安息了。$B$B在肯瑞瓦南區的市政廳保留有這裡全部居民的記錄。據我所知，這份記錄過去被戰場法師達斯立克所持有。或許他的幽靈仍然擁有它。', '自肯瑞瓦村莊的市政廳取回肯瑞瓦的記錄，並把它歸還給監護者戴沃斯。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10313, 'zhTW', '測量扭曲能量', '如果我們的直覺是對的，這些法力熔爐是建造來運用風暴要塞的技術的話，那麼之後整個外域都將陷入死亡的危險中。$B$B風暴要塞的能源補充裝置不該在離大陸如此接近的地方使用。這些扭曲的能量會把這個大陸給毀了，即使是被控制在凱爾的導線裡。$B$B帶著這個寶珠到法力熔爐巴納爾去;它已被調整成可測量扭曲的能量。到導線的尾端去使用它，就是他們進入陸地的那個地方。', '52區的主教歐瑞利斯要你帶著不協調寶珠到法力熔爐巴納爾去並將它使用在四條導線的尾端。為奧多爾完成任務會使你的占卜者聲望降低。', '', '去虛空風暴找52區的大主教歐雷里斯。', '測量北部管道', '測量東部管道', '測量南部管道', '測量西部管道', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10314 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10314, 'zhTW', '長久的懷疑', '這個奇怪的魔法裝置不像你以前所看見的。它當然不是血精靈製造的。$B$B當你感覺到幽靈移動靠近建築物時，寶珠發出了最大強度的光芒，而當幽靈離開時，就變暗了。毫無疑問它也是鬼魂的腐敗過程中的一個要素。$B$B這背後的原理仍然是一個未知的。如果你能連同你的報告一起提供一些鬼魂的殘餘物也許監護者戴沃斯會對這有一些深入見解。', '從肯瑞瓦村莊的教堂庭院的扭曲的鬼魂身上收集10個憎惡殘餘並且交給管理者戴沃斯。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10315, 'zhTW', '消滅虛空術師', '血精靈是傻瓜!我很高興我們與他們之間的貿易關係已經破裂。在我遍及宇宙的所有旅行中，我從未遇到過如此自私的生物。$B$B他們繼續用他們的法力熔爐破壞我們周遭的土地，因此讓我們看看是否我們能越過那座橋並且削弱法力熔爐艾拉的運作。$B$B他們的虛空術師將能源傳導進出血寶石以穩定法力的流量。去那裡，並且消滅他們!', '殺死15個日怒虛空術師，並返回虛空風暴之吐魯曼平臺的虛空行者歐祖爾那裡。', '', '去虛空風暴找圖魯曼的營地的虛空獵手奧爾蘇。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10316 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10316, 'zhTW', '尋找證據', '無論是誰在背後支持鬼魂的轉化都非常深思熟慮的行動，優先注意鎖定最有力量的法師，但是為何呢?這種需要去影響死去的肯瑞托法師亡靈的魔法一定非常具有力量。$B$B為什麼一個強大的法師會惹上這些麻煩?我說這是另一個凱爾薩斯的陰謀，設計來引起這裡更多的苦難。如果有血精靈在這，他們可能會躲在篷橋的對面屋子裡。', '在肯瑞瓦村莊教堂庭院搜索關於操縱那些靈魂的幕後主使者的線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10317, 'zhTW', '解決工頭', '血精靈稱那座處於法力熔爐艾拉下方的礦坑叫崔爾曼礦坑。自從他們失去法力熔爐艾拉奧崔斯下面的那個礦坑後，這裡就是他們現今提供熔爐運作原料的主要供給來源。$B$B不用說，癱瘓他們礦坑運作對我們來說會是有益的。或許我們甚至可以佔領並自行接管這裡?$B$B無論如何，我要你到那裡去解決工頭日落。礦坑就位於這座島的左後方附近。', '在崔爾曼礦坑裡面解決工頭日落，崔爾曼礦坑在虛空風暴的法力熔爐艾拉下面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10318 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10318, 'zhTW', '解決征服者', '我曾經是這裡的工頭。但是現在我被降級了，我意識到我們從奎爾薩拉斯到外域的神聖之行全都是謊言。$B$B一句凱爾薩斯編織的謊言，目的是強化他在虛空風暴這裡的力量。$B$B我已經努力說服我的弟兄們離開，特別是這裡的燃燒軍團不懷好意，但是他們太頑固了。$B$B願意幫我個忙嗎?殺死征服者古林德卡爾。然後返回伊斯利那邊，並且告訴他我不再是他的敵人。', '殺死征服者古林德卡爾。然後返回虛空風暴的吐魯曼平臺的風之貿易者吐魯曼那裡。', '', '去虛空風暴找圖魯曼的營地的星界商人圖魯曼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10319, 'zhTW', '取得骨匣', '我想我應該跟你解釋清楚。你已經遇見了大法師的學徒之一，羅樊德威，但是還有另一位名叫納伯瑞厄斯的學徒。$B$B他原本是一名熱衷學習的學生，但是受到死靈法術的誘惑。當凱爾薩斯大軍出現時，納伯瑞厄斯利用這個機會背叛大法師，交出塔的防禦機制背後的秘密。$B$B現在，看來好像他已經成為一名巫妖。如果我們要制止他，我們必須取得他的骨匣。以我對他的了解，骨匣應該埋在他的住所附近一個看不見的地方。', '在肯瑞瓦村莊教堂後院區取回納伯瑞厄斯骨匣然後帶去給管理者戴沃斯。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10320 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10320, 'zhTW', '消滅納伯瑞厄斯!', '大法師瓦戈斯看到了納伯瑞厄斯尋求巫術的危險，但我不認為他曾要他的徒弟破壞肯瑞托大多數的建築。$B$B你一定要打倒他，$n，否則他將會持續奴役我們死去弟兄的鬼魂，奪走他們應得的安息並摧毀肯瑞瓦所剩不多的殘骸。$B$B有他手中的那個骨匣，他可以同時面對兩到三個戰士，但誰知道他的魔法能對更多的敵人做什麼呢?', '肯瑞瓦村莊的管理者戴沃斯要你擊敗教堂庭院的納伯瑞厄斯。', '', '去虛空風暴找肯瑞瓦村的管理器戴沃斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10321, 'zhTW', '關閉法力熔爐寇魯', '你在巴納爾的成功帶給我們很大的希望，$n。$B$B我們將我們的發現分享給占卜者而他們也提供我們更多有關其他法力熔爐的消息做為回報。$B$B還有其他三座法力熔爐存在，由日怒軍隊全權控制著。$B$B你可以在東邊找到法力熔爐寇魯。監督者塞琳娜那有控制水晶。去拿到它並使用在法力熔爐的控制台執行警急關閉。$B$B我們全都指望你了，$n。', '到法力熔爐寇魯去，就在52區的東方，並從監督者塞琳娜那拿到寇魯控制水晶。使用它關閉法力熔爐寇魯控制臺，完成後回去找隱士卡爾加。為奧多爾完成任務會使你的占卜者聲望降低。', '', '去虛空風暴找52區的學者卡爾亞。', '', '關閉法力熔爐：庫魯恩', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10322, 'zhTW', '關閉法力熔爐杜羅', '我們已經從仍舊在運作的兩座法力熔爐之一得到消息。日怒軍團正失去對法力熔爐杜羅的控制。$B$B日漸增加的能源產量吸引了附近遊蕩的法力生物 - 法力熔爐正處於混亂之中。$B$B若是在杜羅發生爆炸的話有可能會引起連鎖反應，那會危及整個外域。監督者阿森尼爾握有你需要用來安全關閉法力熔爐的控制水晶。', '隱士卡爾加要你前往法力熔爐杜羅並從監督者阿森尼爾身上取得杜羅控制水晶。使用它來關閉法力熔爐杜羅控制臺。為奧多爾完成任務會使你的占卜者聲望降低。', '', '去虛空風暴找52區的學者卡爾亞。', '', '關閉法力熔爐：杜隆', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10323, 'zhTW', '關閉法力熔爐：艾拉', '一座法力熔爐就可以讓風暴要塞維持運作。在我們關閉法力熔爐艾拉之後，凱爾薩斯會藉著節源來儲存能源。$B$B到西北方的法力熔爐艾拉去，給他們最後一擊使他們停止運作。$B$B監督者阿薩納德持有最後一個爆發水晶。警告你我們預測這個最後一個還在運作的凱爾薩斯的法力熔爐艾拉會有強烈的反抗。你可能需要幾個可靠的朋友來協助你。', '到法力熔爐艾拉從監督者阿薩納德那拿到艾拉控制水晶。使用它關閉法力熔爐艾拉控制臺。為奧多爾完成任務會使你的占卜者聲望降低。', '', '去虛空風暴找52區的學者卡爾亞。', '', '關閉法力熔爐：艾拉', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10324, 'zhTW', '牧月大獵殺', '做得好，$n!做得好!$B$B既然你已經見識過牧月成鹿了，那麼現在是你晉級去狩獵更可怕的獵物的時候了。不要讓牧月雄鹿平時對週遭事物漠不關心的個性愚弄了你:當它被激怒時，就是一個可怕的敵人。$B$B你可以在這裡北邊發現那些雄鹿。好好狩獵吧。', '將6個牧月雄鹿皮革帶去給藍色守望的艾克緹昂。', '', '去找蔚藍海岸島的艾克緹昂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10325 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10325, 'zhTW', '基爾加丹印記', '你大概也知道，$n，奧多爾是聖光的守護者還有那魯的僕人。$B$B相對的跟我們立場相反的是燃燒軍團的部隊-惡魔們下定決心要摧毀世界還有腐化無辜的靈魂。$B$B假如你想向奧多爾證明你自己，幫我帶回來燃燒軍團的低階屬下還有暗影議會追隨者的徽記。我們知道暗影議會在白骨荒野的一個藏身處還有燃燒軍團在納葛蘭以及劍刃山脈擁有許多的哨站。', '將10個基爾加丹印記交給撒塔斯城的『護光者』艾德伊恩。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去撒塔斯城找奧爾多高地的聖光護衛者阿德因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10326, 'zhTW', '更多的基爾加丹印記', '', '你帶回了更多敵人的印記了嗎，$c?燃燒軍團仍是一個威脅，不論天涯海角我們都將繼續對抗他們。', '', '去找聖光護衛者阿德因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10327, 'zhTW', '單一基爾加丹印記', '', '我將拿走你剩下的所有印記。別擔心;你的行為將被正式的表揚。', '', '去找聖光護衛者阿德因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10328, 'zhTW', '日怒簡報', '有件關於這些法力熔爐的事情一直困擾著我，$n。那魯科技的先進程度令人驚嘆;凱爾薩斯本來應該要花費多年的時間才能慢慢了解。$B$B想收集相關的情報一直都很困難，因為凱爾薩斯的軍隊很注重紀律並且毀掉所有書面通訊的證據。$B$B我們得知法力熔爐杜羅遭受法力生物的攻擊。有可能那些防禦者尚未毀去他們的作戰指示。取得它們並且把它們帶來給我。', '前往法力熔爐杜羅並且從駐紮的日怒守軍中取得日怒軍情簡報和日怒機密簡報。當你完成這項任務時，返回主教歐瑞利斯那裡。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去虛空風暴找52區的大主教歐雷里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10329 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10329, 'zhTW', '關閉法力熔爐巴納爾', '你離開之後，我與奧多爾討論過了。法力熔爐看起來像是一座源於風暴要塞並經過修改的那魯科技建築。顯然地，大多數的那魯建造物都有一些保險機制，以至於發生緊急事件時，允許它們被永久停用。$B$B通常經由一顆控制水晶在控制台開啟此機制。你瞧，根據你獲得的名冊，控制水晶被一名叫做監督者瑞爾迪斯的傢伙所持有。取得控制水晶，並且看看你能做什麼。', '回去法力熔爐巴納爾並從監督者瑞爾迪斯身上取得巴納爾控制水晶。將它用來關閉巴納爾控制臺，完成後回報給間諜大師薩洛迪恩。為占卜者完成任務會使你的奧多爾聲望降低。', '', '去虛空風暴找52區的間諜大師薩羅迪恩。', '', '關閉法力熔爐：布納爾', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10330 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10330, 'zhTW', '關閉法力熔爐寇魯', '薩洛迪恩告訴我們你成功地關閉法力熔爐巴納爾。他希望你能再一次關閉這裡的法力熔爐並要我們注意任何使用控制水晶操作控制台的傢伙。我們確信監督者塞琳娜握有這個控制水晶。$B$B回到那裡完成任務。你不再需要鬼鬼祟祟;拿到水晶，啟動關閉程序，殺死那些試圖制止你的技師然後出來。$B$B快一點，凱爾薩斯的那些蠢蛋很快就會發現我們的。', '從監督者塞琳娜那裡取得寇魯控制水晶。在寇魯控制臺使用它關閉法力熔爐，完成後回報卡利迪斯·光明。為占卜者完成任務會使你的奧多爾聲望降低。', '', '去虛空風暴找法力熔爐：庫魯恩的卡勒迪斯·晨光。', '', '關閉法力熔爐：庫魯恩', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10331 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10331, 'zhTW', '必需的工具', '你並沒有在這附近的地上看見一支鍛造之錘，有嗎?我把它帶出來是為了要幫一個老人阿默林的馬匹們修理馬蹄鐵，但是我找不到我的錘子了。$B$B我已經找過這個穀倉不下六次了但我就是沒辦法找到它。也許其他的學徒把它拿回去鐵匠舖了嗎?你願意去那邊幫我看看嗎?舖子就在小鎮廣場的哨塔東南方。', '跟肯瑞瓦學徒取回冶煉大錘然後交給肯瑞瓦村莊的學徒安崔森。', '', '去虛空風暴找肯瑞瓦村的學徒安德雷薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10332 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10332, 'zhTW', '鐵匠大師朗瑟士', '終於，我的短工計畫完成了!我等不及要正式表現給朗瑟士大師看看。$B$B<當你在描述尋回鐵錘的過程時學徒專注的看著你。>$B$B他們攻擊你嗎?他們所有人嗎?以聖光之名，他們已經瘋了!$B$B我們該怎麼辦呢，$n?這樣說會讓我感到悲痛，但是我們可能必須殺死朗瑟士大師。這樣我就是肯瑞瓦唯一的鐵匠了，但是我相信我的訓練足以服務整個城鎮的需要。', '在肯瑞瓦村莊的學徒安崔森要你殺了小鎮的鐵匠大師，朗瑟士的鬼魂。', '', '去虛空風暴找肯瑞瓦村的學徒安德雷薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10333 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10333, 'zhTW', '協助威勒媽媽', '對了，$n，我在想你是否能幫我另外一個忙?$B$B我在外面的一個同伴需要幫忙。我在想你可以去查看她一下嗎?$B$B我相信威勒大媽會感謝你的幫忙。希望你別在意她說話刻薄。$B$B她在東邊設法開發我們的利益。你會在秘境領地的領地崗哨找到她。', '到虛空風暴內秘境領地的領地崗哨找威勒媽媽談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10334 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10334, 'zhTW', '需要更多的鈴鐺', '在哪，噢，我的貝絲跑去哪兒呢?在攻擊之後，我在原野和教堂庭院四處搜尋她，但是她始終無影無蹤!$B$B唯一她留下的東西是這舊的牛鈴。通常當她聽到搖鈴的聲音時就會跑過來，但是我這老弱的身軀恐怕已經不能用力地搖響它。$B$B如果你願意到原野去使勁地搖響這鈴鐺，我會借你貝絲的鈴鐺。或許貝絲就是在等這鈴鐺聲。', '在肯瑞瓦村莊的禮拜堂山丘附近找到貝絲。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10335 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10335, 'zhTW', '調察這些廢墟', '我必須到法拉隆廢墟開始我的挖掘!問題是那裡被大批惡魔侵入!$B$B也許你能為我做一些初步性的工作?$B$B廢墟內的東北方有三個地點，我要你去放置勘察標誌的地方。每一個標誌地點都在一面德萊尼旗幟的附近。$B$B當你放好這三個標誌後，回到我這裡。', '放置3面勘察標誌，然後回到虛空風暴的風暴之尖找塞菲爾恩。', '', '去虛空風暴找風暴尖塔的塞菲裡恩。', '放置一號測量標記', '放置二號測量標記', '放置三號測量標記', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10336 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10336, 'zhTW', '卡露薩斯的爪牙', '幾個星期前，燃燒軍團進入了法拉隆廢墟，阻撓我們挖掘當地神器的計劃。$B$B今日稍早，我得知他們一位恐懼領主，卡露薩斯，不知為何殺光了所有其他的燃燒軍團。從那之後他就召喚惡魔來為他做事。$B$B$c，我要你到東北方的那些廢墟去除去他們這些惡魔的騷擾。', '殺死10隻卡露薩斯之犬和5隻卡露薩斯之眼。完成後返回虛空風暴的風暴之尖找虛空行者那魯利斯。', '', '去虛空風暴找風暴尖塔的虛空獵手納烏希思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10337 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10337, 'zhTW', '母牛返家', '意識到貝絲仍然注視你，你指向薩戴爾的位置。你知道你自己許諾要保護這隻母牛回到她家去。在你說完後，你了解這隻母牛不可能了解你所說的任何事情。$B$B你聳了聳肩，準備護衛這隻牛回到薩戴爾跟前。', '護送貝絲安全地回到她的主人，薩戴爾身邊。', '護送貝希回家。', '去虛空風暴找肯瑞瓦村的薩德爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10338 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10338, 'zhTW', '關閉法力熔爐杜羅', '你說法力熔爐杜羅遭受攻擊而日怒部隊已經失去控制了嗎?真是進退兩難!如果杜羅淪陷，那麼風暴要塞也會跟著淪陷。唯一的缺點是……如果風暴要塞被毀了，爆炸將可能將這塊被遺棄的土地毀滅殆盡。$B$B凱爾薩斯因此而死是好事。其他人跟著死掉的話就……沒那麼好，我覺得啦。這樣要求你讓我很為難，但是請你前往法力熔爐杜羅，並且在它產生爆炸之前關閉它。監督者阿森尼爾擁有控制水晶。', '回到法力熔爐杜羅從監督者阿森尼爾手中取得杜羅控制水晶。在杜洛控制臺使用控制水晶關閉該裝置然後向間諜大師薩洛迪恩回報。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去虛空風暴找52區的間諜大師薩羅迪恩。', '', '關閉法力熔爐：杜隆', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10339 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10339, 'zhTW', '伊斯利恩', '這裡的正南方你將可找到伊斯利恩軍事要塞。伊斯利恩就在那裡，為某些事情作準備……或許是一次對奧崔斯的攻擊。$B$B不過，我們不能這個冒險，$c。突破他們的周邊防禦，並且毀掉他們的訓練設施。$B$B一旦你已經消滅他們的士兵和索瓦斯上尉，找到伊斯利恩傳送器VI，並用它建立與我的聯繫以獲得你的下一個命令。', '指揮官阿密爾要你殺死5個伊斯利恩刺客、5個伊斯利恩突擊兵、2個伊斯利恩調查者還有索瓦斯上尉然後啟動伊斯利恩傳送器Ⅵ。', '', '去虛空風暴的復仇軍前沿基地用復仇軍發射器塞塔找到指揮官阿米爾的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10340 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10340, 'zhTW', '破碎崗哨', '$n，你已經在前線完成了一項很棒的任務，而且你與那隻裝甲獅鷲獸展現了許多才能……我想我心裡有另一項任務給你。$B$B這個新任務要從破碎崗哨開始 -- 一個蠻錘在接近黑暗之門的一塊漂浮之島上建立的攻擊據點。那裡稍微讓人不安了點，但是你有堅韌的勇氣。你將會沒問題的。$B$B與空軍指揮戴畢瑞談談，讓他送你到破碎崗哨。到達之後跟那裡的獅鷲獸管理員大師符文衣·蠻錘報告。', '前線指揮官金斯頓要你去找空軍指揮戴畢瑞談談，騎乘獅鷲獸到破碎崗哨，然後找符文衣·蠻錘報到。', '', '去地獄火半島找破碎崗哨的魯恩託格·蠻錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10341, 'zhTW', '趁他人之危', '你發現的這個消息對我們來說還真幸運，$n。現在你不僅可以自由自在的跳著華爾滋進入法力熔爐杜羅，同時也製造了一個給予凱爾薩斯大軍迎頭痛擊的好機會。$B$B利用這個法力生物襲擊的好機會並且解決所有你遇到落單的日怒士兵。$B$B我對於薩洛迪恩這種冷血屠殺自己人的方式並不會感到特別的開心，但是以戰略上的優勢來說實在很難放棄這個行動。', '殺掉8個日怒咒術師，6個日怒射手以及4個日怒百夫長。完成任務後回到52區找博學者萊莉娜。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去虛空風暴找52區的魔導師拉恩娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10342, 'zhTW', '獲得岩層泥岩', '我靠著賣飲品給這附近的酒鬼來維持一個不錯的生活。但是這無法滿足我了!$B$B火箭主管總是告訴我他如何無法使X-52升空所需的火箭燃料盡善盡美。$B$B我們能為他解決那個小問題。$B$B一開始我需要從本地的岩膚鐮奪怪的頁岩中萃取油出來!它將形成一種濃縮的基質，假設帶有爆炸性，成為我想要的那種混合物。$B$B找到鐮奪怪，和他們的頁岩，遍布在紫色的岩石附近到處都找得到。', '收集5個岩層泥岩並將這些交給虛空風暴上52區的布茲。', '', '去虛空風暴找52區的布茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10343, 'zhTW', '無止盡的侵略', '凱爾薩斯對肯瑞瓦的攻擊從打雷般的聲響還有陽光般的刺眼光芒開始，擊中了西北邊的軍官營地。那邊的摧毀程度最為慘重而當血精靈撤退之後，一件奇怪的事情發生了。$B$B一些由法力構成的生物從整個區域開始湧入那個村莊。我們暫時盡量對他們採取容忍的態度，但是隨著對凱爾薩斯使用的武器的了解越多，我希望能切斷這些法力生物的來源。', '搜尋肯瑞瓦村莊大批法力生物出沒的地方找到法力炸彈碎片，並且把它交給莫爾蘭巫士中尉。', '', '去虛空風暴找肯瑞瓦村的巫師上尉莫爾蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10344, 'zhTW', '空軍指揮葛萊弗卡爾', '空軍指揮葛萊弗卡爾負責蠻錘部族的這個部隊。如果這是你第一次去破碎崗哨，那你應該找他報到。$B$B你可以在遠處的那座塔左邊的某個地方裡找到他。', '與破碎崗哨的空軍指揮葛萊弗卡爾談談。', '', '去地獄火半島找破碎崗哨的空軍指揮官格萊芬加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10345 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10345, 'zhTW', '地上的屍體……', '你看見這些屍體了嗎，$r?阿肯納斯要為這次屠殺負責。他吸乾他們的身體，除了肉軀以外沒有留下任何東西。但是不要讓這些屍體欺騙你!在那些屍體裡面躺著噬屍獸，等待著撲向那些接近的不知情傻瓜。$B$B我已經接到我的命令了。我必須待在這裡直到支援到達。那並不表示你就不能帶著我的點火器去燒毀那些搞亂礦場的枯萎屍體。無論如何，任務必須被完成。', '對12具腐敗的屍體使用護國者的點火器。在你的任務完成之後，將護國者的點火器還給在礦井之路通道外面的密探阿雷克斯。', '', '去找虛空風暴瑟安豎井外的代理人阿拉克塞。', '焚燒乾枯的屍體', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10346 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10346, 'zhTW', '回到深淵沙洲', '$n，你已經證明你是一名有能力的獅鷲騎士，我們能派你參與更多次突擊深淵沙洲的行動。你說什麼，$c?你想要更多的飛行次數嗎?', '在地獄火半島破碎崗哨的獅鷲專家風怒要你殺死20個甘納格苦工、5個莫阿格監督者還有5座惡魔火砲。', '', '去地獄火半島找破碎崗哨的獅鷲騎士維比洛。', '', '', '摧毀邪能火炮', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10347 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10347, 'zhTW', '回到深淵沙洲', '$n，你準備好對深淵沙洲進行另一次攻擊了嗎?我擔心如果我們不繼續對那裡的軍團部隊施壓並允許他們鞏固堡壘防禦的話，我們可能會受到北方一股大規模的惡魔攻擊。$B$B你說怎麼樣，$c?你想要乘坐另一隻雙足飛龍去再次重擊深淵沙洲嗎?', '地獄火半島上搶奪者荒野的空軍指揮布拉克要你消滅20個甘納格苦工，5個莫阿格監督者和5座惡魔火砲。', '', '去地獄火半島的機甲殘骸找空軍指揮官布拉克。', '', '', '摧毀邪能火炮', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10348 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10348, 'zhTW', '新的機會', '我聽說一群從艾澤拉斯來的「德魯伊」對於我們秘境技術的效果相當感興趣。$B$B塞納里奧遠征隊的代表迫切地想取得那些在秘境中生長的植物，特別是一種以治療效能而出名，名為象牙鈴的植物。它們以矮樹叢的樣式生長在秘境領地裡大型植物的周邊。$B$B要是你願意幫我去收集這些藥草當我的首批貨物，我會讓你分一杯羹的。', '採集15朵象牙鈴，完成後回到領地崗哨找瑪戴德。', '', '去虛空風暴找中央生態圓頂的瑪爾達德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10349 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10349, 'zhTW', '大地束縛者', '你應該把水晶塊帶到大地束縛者。她跟你一樣……總是需要弄清一個秘密的真相，滿腦子都在思考。$B$B如果你問我的看法，我覺得她想得太多了。$B$B就把它交給她，我確信她將讓丟給你一堆麻煩去找出山脊那裡正在發生些什麼事。', '將赤紅水晶裂片拿去地獄火半島的塞納里奧前哨交給大地束縛者卡拉崔亞·夜風。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10350 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10350, 'zhTW', '畢和瑪特', '在我們在一起的期間，你已經從我這裡學習到很多高深的知識了，該是我將你交給更睿智的專家的時候了。$B$B畢和瑪特，就是在我年幼無知時訓練我的人，他將是你的新導師。我已經告訴他你將去找他，而他正等待著你。$B$B你可以戰士區的中心找到他，就在艾克索達的貿易區的最高點。', '與艾克索達貿易區的畢和瑪特談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10351 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10351, 'zhTW', '自然治療法', '一定是那個巨大水晶所散發出來的邪惡召喚了山岳巨人並使他們變得瘋狂。$B$B它太大了無法移動，並且以我們的能力無法破壞它，但是我知道有一種方法可以壓制它的力量。$B$B我已經在山脊上水晶的西北角落召喚一個環界。將這個種子拿到那個環界去，並將它的力量導引出來，透過雨、生物、和昆蟲再生的自然力量來治療大地。$B$B當心點，$n，我感應到這裡有一股外在的力量……非自然的力量!', '在大地束縛者之環使用新生之種去治癒水晶周遭的土地。然後，帶著任何你所獲得的情報返回地獄火半島的塞納里奧前哨找大地束縛者卡拉崔亞·夜風。', '', '去地獄火半島找塞納里奧哨站的縛地者加蘭蒂婭·夜風。', '治癒墜星山', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10352 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10352, 'zhTW', '捐獻毛料', '', '', '', '去找泰達希爾的萊頓·暗影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10353 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10353, 'zhTW', '貪求無厭的阿肯納斯', '阿雷克斯和我2天前被派遣到奧崔斯。我們的任務:找到並且終結虛無領主阿肯納斯。我們跟蹤他到這礦場，並且發現他一直捕食該地區生物的能量。$B$B一場火拼導致阿雷克斯和我失散了。現在我被困在這裡，受了重傷。任務變得一團亂!$B$B假如你能解決掉阿肯納斯，高階領導層將感激你。如果你接受這項任務，我將藉由提供我自己的倒影作為守護人幫助你。', '位於虛空風暴上礦井之路通道的密探亞希克斯要你殺掉貪求無厭的阿肯納斯，完成後回到虛空風暴的護國者哨站找指揮官阿密爾。', '', '去虛空風暴找維序派哨站的指揮官阿米爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10354 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10354, 'zhTW', '捐獻絲綢', '', '', '', '去找泰達希爾的萊頓·暗影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10355 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10355, 'zhTW', '枯萎的肉體', '我們必須確定這場損害傳播多遠了。你帶來給我的孢子臺來自一個泥沼巨人。 他們更大，更強壯的親戚，泥沼領主，應該更能抵抗那些使巨人墮落的變化。$B$B最好也能知道死亡污泥裡發生的變化如何影響附近的其它生物。$B$B回到死亡污泥去，看看你能否取回該區域裡泥沼領主和海妖的樣本。', '收集5個乾乾枯的多頭蛇樣本和5個枯萎的泥沼領主樣本，並且將它們帶回泰倫多爾交給洛安瑪。', '', '去贊加沼澤找泰雷多爾的魯埃姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10356 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10356, 'zhTW', '捐獻魔紋布', '', '', '', '去找蔚藍海岸島的達葛魯。', '', '', '', '', 0);
