INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10363, 'zhTW', '更多的符文布', '', '', '', '去找永歌森林的索瑞姆·輕歌。', '', '', '', '', 0);
