INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10364, 'zhTW', '希德摩斯', '你在短時間內就有如此的成長，$n。比我原先預期或希望的還快，$n。該是你在希德摩斯的指導下繼續訓練的時候了。$B$B我已經傳話給在艾克索達的他等著你。你可以在靠近聖光地窖入口處的隱士聖所裡找到他。', '到艾克索達的聖光地窖與希德摩斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10365, 'zhTW', '關閉法力熔爐：艾拉', '你做得比我們任何一個參予過的都還要好。法力熔爐艾拉是凱爾薩斯最後一個還在運作的法力熔爐。它就在西北方，但是恐怕你要繞一圈才能找到它。我們要你去將它停止運作。$B$B最後一個的控制水晶在監督者阿薩納德身上。這是我們所知道凱爾薩斯最後的一個能量來源，準備好迎接激烈的攻防戰吧。假如我是你我會多帶幾個戰友一同前去。$B$B嗯……阿薩納德。對於一個辛多雷來說是多麼的奇怪阿。', '到法力熔爐艾拉去從監督者阿薩納德身上取得艾拉控制水晶。將它使用來關閉星座控制臺。為占卜者完成任務會使你的奧多爾聲望降低。', '', '去虛空風暴找52區的間諜大師薩羅迪恩。', '', '關閉法力熔爐：艾拉', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10366, 'zhTW', '喬歐', '聖光和純潔之路並不條容易行進的道路，$n。即使是我，有時候也會在這條路上掙扎。$B$B你應該去找我的師傅，喬歐，她在艾克索達。她在我開始我的聖光之路時訓練過我，我相信她將發現你是一位有潛力的新人。$B$B你將可在位於艾克索達的復仇者聖所裡的聖光地窖裡找到喬歐，就在一間被閃耀明亮的光輝所包圍的房間裡。', '在艾克索達的復仇者聖所與喬歐談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10367, 'zhTW', '眾人的背叛者', '任何一個你所看到的被奴役的破碎者部族，你都會找到一個叛徒。一個可鄙的生命為了力量的承諾出賣他的弟兄。$B$B在廢墟中央的樓梯頂上有一間小屋。那是背叛者的小屋。$B$B他現在不在那裡，因此如果你有耐心，你可以溜進去那裡。在裡面你將發現一個保險箱，裡面有一把鑰匙。那把鑰匙可打開鎖住崔互德長者囚犯的鍊子。把它帶給我。$B$B注意，無情的阿爾塞斯就在附近徘徊。', '在夏納廢墟的納拉杜要你從附近一所小屋裡取回夏納鑰匙。', '', '去地獄火半島找沙納爾廢墟的納拉杜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10368, 'zhTW', '崔互德長者', '崔互德的靈魂受到打擾因為我們的長者被囚禁了。拿著這把鑰匙然後走下樓梯去釋放他們。$B$B他們分別是『鼓風者』莫洛德、『召火者』阿庫羅還有『喚水者』阿亞藍。一旦他們自由了，崔互德的靈魂就會回到崔互德部族了。', '釋放夏納廢墟的『鼓風者』莫洛德，『召火者』阿庫羅及『喚水者』阿亞藍。完成後向納拉杜回報。', '', '去地獄火半島找沙納爾廢墟的納拉杜。', '釋放撫風者莫洛德', '釋放召火者阿庫魯', '釋放喚水者埃伊蘭', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10369, 'zhTW', '阿爾塞斯的死亡', '是的，元素之靈已經回歸我們了!我們不像以往那麼的強壯，但是就算只有一點點的魔法給予正確的人使用還是很有用的。$B$B阿爾塞斯的黑暗之王授予他強大的力量。帶著這個權杖。這曾經是我們部族偉大的象徵。對著阿爾塞斯使用它，他的力量將暫時被剝奪。然後打敗他，這樣我的人民終獲自由!', '對無情的阿爾塞斯使用崔互德長者法杖，並且在他失去力量之後殺死他。完成這項任務之後，返回夏納廢墟找納拉杜。', '', '去地獄火半島找沙納爾廢墟的納拉杜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10370 AND `locale` = 'zhTW';
