INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10379, 'zhTW', '虛弱之觸', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10380, 'zhTW', '黑暗契約', '$n，我們曾如此盲目的完全沒有發覺我們最危險的兩個敵人已經結盟。$B$B我不訝異占卜者刻意不將這個訊息透露給我們，不過現在我們必須面對事實。燃燒軍團及凱爾薩斯的日怒軍隊屬於同一股勢力。$B$B這些惡魔就是凱爾薩斯至今能夠利用風暴要塞的技術的唯一原因。在歐瑞利斯指令下我必須命令你去殺掉他們。', '虛空風暴的吐魯曼平臺的凱嵐要你殺死6個甘納格星移技工，3個命運之女還有3個莫阿格轉換大師。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去虛空風暴圖魯曼的營地找凱蘭恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10381, 'zhTW', '奧多爾不再', '我在這裡的任務已經結束了。我完成了歐瑞利斯要我做的事 - 我從未失敗過。$B$B如今再也不是了。隨著凱爾薩斯與燃燒軍團結盟的訊息後，我預見一場大屠殺 - 他們稱之為燃燒的遠征。$B$B他們先是把我們最神聖的城市送給我們的敵人，而後他們又要求我們與他們的敵人死戰。回去歐瑞利斯那;跟他說那魯們從現在開始主導他們自己的戰鬥。', '回報52區的主教歐瑞利斯。為奧多爾完成任務會使你的占卜者聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10382, 'zhTW', '到前線去', '那個，$n，我希望你已經準備好迎接我們下一階段的行動。軍團永遠都不會停止 - 我們也是!乘著一隻獅鷲獸飛到榮譽崗哨 - 一個接近軍團前線的小型哨站。$B$B去與戰場元帥布洛克談談。在你抵達後他會給你指示。喔，順便告訴那個臉色蒼白的盾牌親吻者我說「哈囉」。', '乘著一隻獅鷲獸去榮譽崗哨並與戰場元帥布洛克談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10383, 'zhTW', '線索在這！', '哈囉。你應該查明那些兔子。', '與強納森·樂卡夫特談論關於兔子的事。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10384, 'zhTW', '伊斯利恩資料', '看看四周吧，凡人。這台傳送器的附近應該就有一個伊斯利恩數據機體。找到數據機體，打開它，並且擷取裡面的內容。$B$B馬上將它帶回傳送器這邊!', '伊斯利恩軍事要塞的指揮官阿密爾的影像 - 伊斯利恩傳送器VI - 要你取得伊斯利恩數據機體。', '', '去虛空風暴的復仇軍前沿基地用復仇軍發射器塞塔找到指揮官阿米爾的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10385, 'zhTW', '大腦損傷的可能性＝高', '他們在軍事要塞周遭使用傳達者傳送情報。$B$B你只有一種方法可以見到這些傳達者，並且竊取他們所握有的情報。不幸的是，這樣做有可能會使你受到無法復原的大腦損傷。$B$B假如你仍然感興趣，你將必須在監視陣地這裡殺死伊斯利恩，並且取走他們的精華。一旦你取得精華，喝光它。它將讓你暫時能看到伊斯利恩傳達者 - 讓你有足夠的時間殺死傳達者，並且竊取它的情報。', '伊斯利恩軍事要塞的指揮官阿密爾的影像 - 伊斯利恩傳送VI - 要你取回15件伊斯利恩傳達資料。', '', '去虛空風暴的復仇軍前沿基地用復仇軍發射器塞塔找到指揮官阿米爾的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10386, 'zhTW', '魔能機甲的摧毀者', '大督軍霍恩·重拳一直在尋找願意採用自殺式攻擊方法對付燃燒軍團的人。你一定有勇氣去接受其中一個任務。$B$B當你準備好流血犧牲的時候去跟他談一談。他正在那邊慶祝幹掉了一臺魔能機甲。他和他的護衛隊幾個小時前摧毀了那臺魔能機甲，要不是他的兇猛和戰鬥技巧，我們可能都死在這裡了。', '與大督軍霍恩·重拳談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10387, 'zhTW', '魔能機甲的摧毀者', '大督軍霍恩·重拳一直在尋找願意採用自殺式攻擊方法對付燃燒軍團的人。你一定有勇氣去接受其中一個任務。$B$B當你準備好流血犧牲的時候去跟他談一談。他正在那邊慶祝幹掉了一臺魔能機甲。他和他的護衛隊幾個小時前摧毀了那臺魔能機甲，要不是他的兇猛和戰鬥技巧，我們可能都死在這裡了。', '與大督軍霍恩·重拳談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10388, 'zhTW', '返回索爾瑪', '希望你旅途還愉快，夥伴。一個信差在你離開時抵達 - 看來好像納茲格雷爾有新的任務要給你。你最好回頭到索爾瑪去跟他報到。我有預感軍團正要開始行動。', '回到索爾瑪與納茲格雷爾談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10389, 'zhTW', '苦痛的黑暗', '你好啊，$n.我解開了燃燒軍團公函上的密語並且發現了惡魔們對這個半島的戰略計畫。很顯然的，有一大群地獄恐懼惡魔聚集在西邊的阿葛納爾之池。我們不能容許這股勢力輕易坐大。你必須去降低那群可恨的數量。', '博學者血鷹要你去阿葛納爾之池殺10個恐懼惡魔。', '', '去地獄火半島找索爾瑪的魔導師文森特·血鷹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10390, 'zhTW', '煉冶場:黑色祭壇', '$n，我們有理由相信位在最東邊的煉冶場還沒有建造完畢。燃燒軍團的甘納格僕人正在夜以繼日的趕工完成煉冶場。我們不能允許這種事情發生。$B$B到東邊的煉冶場:黑色祭壇殺死10個甘納格。把他們首領 - 鍛造王鋒鋸 - 的人頭帶給我，然後燃燒軍團的惡魔搶奪者生產作業就會中斷了!', '索爾瑪的納茲格雷爾要你攻擊煉冶場:黑色祭壇，殺死10個甘納格僕人並將鍛造王鋒鋸的頭帶回來。', '', '去地獄火半島找索爾瑪的納茲格雷爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10391, 'zhTW', '狂怒的火砲', '燃燒軍團又有了第二個製造場所，煉冶場:狂怒，緊接在索爾瑪的東北方。他們在山坡上佈置了大量的惡魔火砲-而且那些砲口是直接對著我們的!你必須去煉冶場引爆那些火砲彈藥堆。$B$B拿著這些炸藥並將他們設置在每個彈藥堆裡。$n，你必須確定你已經破壞了所有的彈藥堆-不然誰都沒有辦法阻止燃燒軍團對著我們的頭上發射火雨般的砲彈!', '在煉冶場:狂怒摧毀3門MKI型惡魔火砲然後回報給索爾瑪的納茲格雷爾。', '', '去地獄火半島找索爾瑪的納茲格雷爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10392 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10392, 'zhTW', '通往深淵的門戶', '你是我們的驕傲，$n。但現在我們必須搶在燃燒軍團恢復前出擊!出發到索爾瑪北方的侵略點:殲滅者去。內有一座傳送門以便軍團將援助傳送進來。$B$B你得去讓傳送門超載 - 並將它炸回所屬的深淵去。門的啟動鑰匙由這裡的指揮官 - 戰爭使者阿瑞克斯阿摩持有。殺了他。拿到鑰匙。將它使用在那道門上，做該做的事。願酋長的祝福與你同在。', '殺掉阿瑞克斯阿摩拿到燃燒軍團入口鑰匙。對惡意符文使用燃燒軍團入口鑰匙，完成之後回到索爾瑪向納茲格雷爾回報。', '', '去地獄火半島找索爾瑪的納茲格雷爾。', '', '關閉燃燒軍團傳送門', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10393 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10393, 'zhTW', '邪惡的計畫', '字條上遍佈了昏暗，而難以辨識的潦草筆跡。你看得越仔細，這些文字符號越呈現出模糊扭曲的景象讓你看的眼花撩亂。只有一個人在索爾瑪可以解讀出如此邪惡的文字-血精靈博學者血鷹。', '將燃燒軍團公文帶到索爾瑪交給博學者血鷹。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10394, 'zhTW', '瓦解 - 煉冶場:黑色祭壇', '注意聽我說，$n。我們一直都在監視燃燒軍團在前方山坡的軍營。我們相信這些所謂的「煉冶場」是那些惡魔們拿來生產那些該死的惡魔搶奪者的地方。$B$B你可以去西邊看看其中一個最近的營地，煉冶場:黑色祭壇。我們的情報顯示那裡還在建造中。假如你可以殺死甘納格僕人還有他們的主人-鋒鋸-我們就可以讓燃燒軍團的惡魔搶奪者生產線崩潰!', '殺掉10個甘納格僕人及在黑色祭壇煉冶場的鋒鋸，完成後回到榮譽崗哨找戰場元帥布洛克。', '', '去找軍團前線的巴洛克元帥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10395, 'zhTW', '黑暗書信', '字條上遍佈了昏暗，而難以辨識的潦草筆跡。你看的越仔細，這些文字符號越呈現出模糊扭曲的景象讓你看的眼花撩亂。這麼古老的筆跡只有榮譽堡的一個人才看的懂-德萊尼秘法師-克里。$B$B把燃燒軍團公文交給星移占卜師克里，他住在榮譽堡的指揮室。', '帶著這封公文給在榮譽堡主要塞中的星移占卜師克里。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10396 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10396, 'zhTW', '敵人的敵人……', '現在我們的重點放在第二個目標-煉冶場:狂怒。它的地點在煉冶場:黑色祭壇的西邊。麻煩的是那些惡魔部署了大量的惡魔火砲直接對著部落的索爾瑪的前哨站!雖然我幾乎不敢相信，但是我們真的需要部落幫我們拖住在黑暗之門的戰線。我們不能讓索爾瑪淪陷。$B$B拿著這些破壞炸藥然後將它們放置在惡魔火砲的彈藥堆裡。你必須在燃燒軍團粉碎我們的盟友之前摧毀所有的火砲!', '摧毀煉冶場:狂怒的3座MKI型惡魔火砲，然後向榮譽崗哨的戰場元帥布洛克回報。', '', '去找軍團前線的巴洛克元帥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10397, 'zhTW', '侵略點:殲滅者', '沒錯，我們在山脊上找到了燃燒軍團最後的基地-侵略點:殲滅者。它的位置在煉冶場:狂怒的西北方-內藏有一道傳送門可以讓燃燒軍團傳送援軍進來!$B$B你必須關閉那個傳送門以阻止更多的惡魔被傳送過來。侵略點:殲滅者的霸主，戰爭使者阿瑞克斯阿摩，擁有那個傳送門的啟動鑰匙。從他身上取得鑰匙然後關閉那個該死的門!', '殺掉阿瑞克斯阿摩拿到燃燒軍團入口鑰匙。 對惡意符文使用燃燒軍團入口鑰匙。', '', '去找軍團前線的巴洛克元帥。', '', '關閉燃燒軍團傳送門', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10398, 'zhTW', '返回榮耀堡', 'PH:出發到榮耀堡。', 'PH: 出發到榮耀堡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10399 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10399, 'zhTW', '黑暗之心', '這正是我所擔心的。阿瑞克斯阿摩 - 你之前所殺的惡魔，是軍團領主 - 殘忍的阿拉薩爾斯的手下。看來這個新的壞蛋已經在阿葛納爾之池聚集了一批凶惡的恐懼惡魔部隊。$B$B你必須到那裡去 - 在他們對我們發動攻擊前殺死那些恐懼惡魔。你要小心，我的朋友 - 阿葛納爾之池圍繞在充滿毒煙瘴氣又崎嶇不平的山谷之中。你可以在西北邊找到那些被詛咒的池子，往地獄火堡壘的方向找就對了。$B$B願聖光與你同在，$n。', '殺掉10個阿葛納爾之池的恐懼惡魔，完成後回到榮譽堡的主堡壘裡回報星移占卜師克里。', '', '去地獄火半島找榮耀堡的位面占卜者克雷夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10400 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10400, 'zhTW', '霸主', '高貴的星移占卜師已經告訴我有關你的冒險事蹟，$n - 包含你所發現的新的敵人。如果克里可信的話，這個「殘忍的阿拉薩爾斯」就跟洛薩之子之前對付過的敵人一樣強大與邪惡。$B$B這次你會為我們挺身而出嗎，$n?你會去對付這個軍團領主並且以聖光的名義制裁他嗎?如果是如此，你可以在阿葛納爾之池找到他。如果不是的話，他所犯下的罪行總有一天會找上你。', '殺掉阿葛納爾之池的殘忍的阿拉薩爾斯，完成後回到榮譽堡要塞找軍隊指揮者達納斯·托爾貝恩。', '', '去地獄火半島找榮耀堡的遠征軍指揮官達納斯·托爾貝恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10401 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10401, 'zhTW', '任務:終結所有，戰勝所有', '假如你沒有截獲這些信件，你知道會發生什麼事情嗎，$N？<納茲格雷爾點了點頭。>$B$B是的，全地獄火半島的燃燒軍團部隊都會來敲我們索爾瑪的大門。若是真有那樣一場突襲，沒有人可以活下來。$B$B要想不讓這些命令抵達軍團前線，那只有一個辦法。你必須立刻轉至西北方的阿苟納之池，並殺死這隻阿拉薩爾斯。$B$B去吧，若是能夠成功，我會推薦酋長大力嘉獎你的。', '地獄火半島上索爾瑪的納茲格雷爾要求你殺掉殘忍的阿拉薩爾斯。', '', '去地獄火半島找索爾瑪的納茲格雷爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10402 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10402, 'zhTW', '<TXT>', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10403 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10403, 'zhTW', '納拉杜', '也許崔互德還有希望。在我們被伊利達瑞奴役之前，我是領導這個部族的四位長老之一。我以為其他的長老都死了，但我逐漸發現至少還有兩位長老還活著-跟我一樣被既無力又被鎖鍊住了。$B$B我還沒辦法找到納拉杜，我怕他會遭遇到不測。從廢墟的階梯往上走你會看到更多小屋;也許你可以找到他。假如所有的長老都還活著的話，對我們部族來說真是天大的好消息呀。', '在夏納廢墟尋找納拉杜的下落。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10404 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10404, 'zhTW', '對抗軍團', '我們當前已經獲悉，燃燒軍團向凱爾薩斯提供了大量的技術援助，這已經使凱爾薩斯的威脅等級提高了數倍。$B$B然而，由於燃燒軍團在這一地區部署的軍隊實在太多了，我們所能對敵人造成的最大打擊，恐怕也只有直接正面進攻地域內正北方的兩處鑄魔營地了。立刻轉至鑄魔基地：煉獄和鑄魔基地：湮滅，消滅那裡所有的敵人。願聖光指引著劍的方向，$N。', '在52區的主教歐瑞利斯要你去熔爐基地:遺忘和熔爐基地:苦難，並殺掉12個甘納格鍛造黑手，6個莫阿格鍛造王和6個憤怒使者。$B$B為奧多爾完成任務會使你的占星者聲望降低。', '', '去找大主教歐雷里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10405 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10405, 'zhTW', '破壞行動', '我們想辦法必須破壞這些造成奈薩斯捕獵者行為異常的機器。攻擊他們的原始加速器是無用的，因為它是伊斯利的創造物。我們必須改為破壞他們作為導管的法力熔爐能量輸送管。$B$B我需要建造一個裝置使得導管的保險裝置超載。為了校準此裝置，我需要一個執政官或霸主準備好要傳輸的伊斯利恩裹帶。', '伊斯利恩軍事要塞的指揮官阿密爾的影像 - 伊斯利恩傳送器VI - 要你取回1個準備好的伊斯利恩裹帶。', '', '去虛空風暴的復仇軍前沿基地用復仇軍發射器塞塔找到指揮官阿米爾的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10406 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10406, 'zhTW', '傳遞訊息', '我正派我的一名爆破專家去安置破壞裝置。請確保他在安置破壞裝置時的安全。$B$B保護他!他無法反擊敵人的攻擊，因為他只是一名投射的影像而已，但是影像還是會被摧毀的!$B$B一旦工作完成，回到我這裡。', '伊斯利恩軍事要塞的指揮官阿密爾的影像 - 伊斯利恩傳送器VI - 要你護送護國者破壞者到法力熔爐奧崔斯導管，並且在他破壞導管時保護他。', '破壞復仇軍管道', '去虛空風暴的復仇軍前沿基地用復仇軍發射器塞塔找到指揮官阿米爾的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10407 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10407, 'zhTW', '索奎薩爾的影子', '這個惡名昭彰的埃雷達爾，索奎薩爾，領導虛空風暴當地的燃燒軍團。光是提到他的名字就足以讓大多數德萊尼發抖。他從西北方的一座島嶼下達命令，只有少數受他極度信任的副官才能通行此地。$B$B想要到那裡的話你需要一顆傳送石，要拿到它可不是個簡單的任務。石頭的第一半由熔爐基地:遺忘的鍛造大師莫爾洛克持有。第二半則是由熔爐基地:苦難的希洛斯持有。', '52區的隱士卡爾加要你從熔爐基地:遺忘的鍛造大師莫爾洛克身上取得第一部分的索奎薩爾的傳送石，從熔爐基地:苦難的希洛斯身上取得第二部份的索奎薩爾的傳送石。為奧多爾完成任務會使你的占卜者聲望降低。', '', '去虛空風暴找52區的學者卡爾亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10408 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10408, 'zhTW', '奈薩斯王薩哈達爾', '我擁有另外一個干擾器，這個干擾器可以摧毀圍繞著薩哈達爾的三條導管。一但那些導管被摧毀，薩哈達爾的保護力場將會關閉。這麼做，他將會讓你看見前所未有的凶猛攻擊，$n。$B$B如果你想清除薩哈達爾的世界，我就給你干擾器。', '伊斯利恩軍事要塞的指揮官阿密爾的影像 - 伊斯利恩傳送器VI - 要你使用護國者干擾器去打敗薩哈達爾的軍隊，然後消滅奈薩斯王薩哈達爾。', '', '去虛空風暴的復仇軍前沿基地用復仇軍發射器塞塔找到指揮官阿米爾的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10409, 'zhTW', '對軍團致命一擊', '在埃雷達爾強大的力量前，即使是數量龐大的部隊也無用武之地。他們腐化凡人靈魂的力量是如此的強大，以至於只有那些擁有最堅強意志的人才有可能面對面的對抗他們。$B$B將這塊石頭拿去主宰者侵佔崗哨，位置在熔爐基地:遺忘還有熔爐基地:苦難之間，然後帶著你的好朋友以及實力堅強的朋友與你同行。歐瑞利斯還有卡爾加在索奎薩爾的領地等著你;我會派艾德伊恩加入他們。$B$B願聖光今日得以彰顯，$n。願索奎薩爾遇見他的末日。', '高階女祭司伊莎納想要你去虛空風暴西北角的軍團傳送門，並使用它傳送到索奎薩爾的領地。一旦到達那裡，打敗索奎薩爾。為奧多爾完成任務會使你的占卜者聲望降低。', '重創燃燒軍團', '去撒塔斯城找奧爾多高地的伊沙娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10410 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10410, 'zhTW', '伊莎納的幫助', '是時候面對索奎薩爾了，$n。挑戰一個埃雷達爾領導者對我們而言不是件簡單的事。如果準備不足，一丁點錯誤就可能讓我們賠上性命。$B$B把索奎薩爾的傳送石帶到撒塔斯城的永恆聖光神殿給高階女祭司伊莎納。她會決定我們該如何處理這個情況。', '帶著索奎薩爾的傳送石到撒塔斯城奧多爾高地的永恆聖光神殿交給高階女祭司伊莎納。為奧多爾完成任務會使你的占卜者聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10411 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10411, 'zhTW', '電擊的啊呀!', '在被毀壞的法力熔爐周遭你將找到迪曼修斯手工藝品的溢流。滲出的爛泥充滿了圍繞著奧崔斯的水池。就在那些水池下面，伊斯利恩軍事要塞目前的所在地，你將會發現更多虛無荒廢者形態的溢流。$B$B最好的處理方法是使用電擊將軟泥們分解成水珠般的球體。使用這種藥劑讓你的攻擊產生電流。結果會將軟泥們分解成它們的原始形態。摧毀這些球體!', '在虛空風暴上護國者哨站裡的研究員納巫德要求你破壞30個虛無荒廢者球體和30個爛泥軟泥怪球體。', '', '去虛空風暴找維序派哨站的研究員納烏德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10412 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10412, 'zhTW', '火翼徽章', '凱爾薩斯·逐日者視我們為一大威脅已經不是什麼秘密。面對現實吧-很少有辛多雷，銀月的年輕人，願意加入凱爾薩斯哪一方。$B$B大家也都知道這可不光是口舌之爭。占卜者跟凱爾薩斯的軍隊只要見面就會攻擊彼此。唯一可以證明你是站在我們這一邊的方法，$n，就是跟我們一起戰鬥。$B$B凱爾薩斯的低階士兵都穿著火翼徽章來顯示他們的階級。幫我帶回一些這種東西。', '撒塔斯城的博學者菲雅蘭要你帶給她10個火翼徽章。為占卜者完成任務會使你的奧多爾聲望降低。', '', '去找泰羅卡森林的魔導師菲亞琳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10413 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10413, 'zhTW', '恐獸的污染', '你小心地用將虛無恐獸所掉落的污泥填滿一個藥水瓶。$B$B在護國者哨站的研究員納巫德將對這樣的發現十分感興趣!立刻把它帶到他那裡!', '將一瓶虛無恐獸的污泥拿給在虛空風暴上護國者哨站裡的研究員納巫德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10414 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10414, 'zhTW', '單一的火翼徽章', '', '即使是最小的貢獻也會被注意到，$n。我們的敵人很多，但是我們將戰勝他們!。', '', '去找泰羅卡森林的魔導師菲亞琳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10415 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10415, 'zhTW', '更多的火翼徽章', '', '你最近為我們做了什麼，$n?對凱爾薩斯的戰爭是不會自己開始的，你知道嗎?。', '', '去找泰羅卡森林的魔導師菲亞琳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10416 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10416, 'zhTW', '力量的綜合', '秘法寶典不是一本處理秘法事情的普通書。在它們裡面藏有強大的力量 - 一個我已經學會將它合成為一個秘法符文的力量。$B$B如果你在冒險中發現一本秘法寶典，我將給你一個秘法符文。只有最強大的魔法佩帶者會帶著我需要的那些書。在外域這通常代表凱爾薩斯的血精靈們 - 但是你這寶典經常會出現的地方一定會使你感到驚訝。', '在撒塔斯城的『先知』沃藍索想要你取得一本秘法寶典。為占卜者完成任務會使你的奧多爾聲望降低。', '', '去找泰羅卡森林的先知沃雷塔爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10417 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10417, 'zhTW', '進行一次診斷!', '不論聯合團決定在那邊出席，我們都帶著我們的秘境技術。因為我們經常發現我們居於危險的環境中，此磁場讓我們可以在控制和維持生命的氣氛裡工作。$B$B虛空風暴不穩定的狀況和生物已經開始破壞支撐我們秘境的裝備，特別是這裡東邊的生成器。我已經開始診斷那裡了，希望能瞭解到要採取怎樣的行動來抗衡所產生的損害。你願意幫我收集結果並且把他們帶回來給我嗎?', '取得診斷結果並帶回到領地崗哨給瑪戴德。', '', '去虛空風暴找中央生態圓頂的瑪爾達德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10418, 'zhTW', '處理活動破壞者', '搜尋這個區域來找尋造成我們裝備損害的線索，我曾看見在東方的小湖底部有護盾生成器的碎片。我不能確定為什麼鱷魚們會對裝備感到興趣，但是我們必須制止這個問題。$B$B聯合團對此事情的處理方式十分清楚。如果必需在裝備和鱷魚們之間選擇，當然是裝備留下。我將會付出一筆可觀的酬勞給那些對付它們的人。', '領地崗哨的瑪戴德要你去殺掉8隻刺鱗鱷魚。', '', '去虛空風暴找中央生態圓頂的瑪爾達德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10419 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10419, 'zhTW', '秘法寶典', '', '你拿到更多的秘法寶典了嗎，$n?。', '', '去找泰羅卡森林的先知沃雷塔爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10420 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10420, 'zhTW', '淨化的聖光', '這座神殿是整個外域裡最神聖的地方之一。在這裡的聖光能力如此強大，甚至是被最強大的惡魔所污染的東西都可以被淨化成一般世俗的東西。$B$B在你與惡魔敵人對抗過程中如果有遇到任何魔化武器的話，將把他們帶到我這裡，我將證明聖光的淨化能力。', '將魔化武器帶去給撒塔斯城的伊莎納。為奧多爾完成任務會使你的占卜者聲望降低。', '', '去撒塔斯城找奧爾多高地的伊沙娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10421, 'zhTW', '魔化武器', '', '你今天有拿到任何魔化武器嗎?讓聖光消滅他們，$n。別讓哪些污穢的生物殘存在這世界上。', '', '去找伊沙娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10422, 'zhTW', '泰拉里斯上尉', '10天前泰拉里斯上尉帶領一群士兵往南向伊斯利恩軍事要塞走去。從那以後，我們就沒收到他或者他隊員的消息。$B$B他們被伏擊並且殺死的可能性很高，但是我收到來自我的儀器的一個奇特讀值。$B$B我認為它是一個痛苦信號，但是這些事情以前曾出錯。如果泰拉里斯仍然活著，他們正把他關在他們的一座監獄裡。你必須找到監獄並且用鑰匙打開它，或許在典獄長身上可找到。', '在虛空風暴裡的護國者哨站的血肉處理者維迪厄斯已經要求你找到並釋放泰拉里斯上尉。', '', '去虛空風暴找維序派哨站的馴獸者維裡迪斯。', '營救泰拉留斯上尉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10423, 'zhTW', '到風暴之尖', '工程大師加巴想要了解診斷的結果。如果有差異的話，他們會警告我們要多注意我們的秘境生成器。隨著地方變得更加的不穩定，他們的效用會變得更難控制。它將為我們的遠征隊及其他生活在這秘境下的事物招來災難。$B$B你在風暴之尖那可以找到秘境。只要從這個秘境原野順著路往北方，通過那座橋。它將會引領你到尖塔底部的電梯處。', '與風暴之尖的加巴交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10424, 'zhTW', '診斷:關鍵', '如果瑪戴德的結論是正確的-我沒理由去相信這是錯誤的結論-那麼其他剩下的秘境就有麻煩了。$B$B我真的認為瑪戴德沒去確認造成損壞的真正原因。有時候，動物會破壞生成器，但從未如此嚴重過。$B$B為了安全起見，我要你到風暴之尖的主要秘境生成器進行診斷，就在秘境最東部邊緣的桑什倫秘境那裡。', '在桑什倫秘境生成器附近使用診斷儀器，並將診斷結果帶回風暴之尖給加巴。', '', '去虛空風暴找風暴尖塔的賈巴爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10425 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10425, 'zhTW', '逃離軍事要塞', '感謝凱瑞西!他可能把我四分五裂!$B$B我是一名護國者士兵，新兵。大約10天前我的排被派遣執行一項偵察任務。當我們正移動穿過這座島上方岩架時，一群伊斯利恩突然襲擊我們。至少我認為它是伊斯利恩。他們有相同的能量顏色，但是他們外表看起來虛無。$B$B只有泰拉里斯逃過一劫。我認為他們把他關在一座監禁室裡。$B$B我必須回到護國者哨站!你能護送我嗎?', '護送被囚禁的護國者先鋒回到虛空風暴的護國者哨站。', '護送被俘虜的維序派前鋒', '去虛空風暴找維序派哨站的指揮官阿米爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10426 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10426, 'zhTW', '秘境植物群', '看看你的週遭，$c!是不是很驚人?當然，這些難以置信的生命復甦是伊斯利秘境的副產品，但是想像它能為探險隊帶來甚麼。$B$B我正準備與伊斯利談判以取得他們的技術，但是我想更進一步的了解它對植物類型的生命的影響。$B$B我已經建造了一個設備將秘境的能量集中在這個地區的鞭擊者上。可以請你為我測試它並且與我分享結果嗎?', '在法拉隆鞭笞者上使用能量磁場調幅器。當你已經進行10次試驗後，觀察結果並且回報給風暴之尖的阿魯尼·月火。', '', '去虛空風暴找風暴尖塔的歐瑞恩·月焰。', '測試能量調節器', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10427, 'zhTW', '秘境的生物', '你對鞭擊者的研究結果出現一些令人震驚的情報，但是我想知道它是否對生物也有效。$B$B我怕收集關於住在這個秘境下面的塔巴克們的情報要比研究鞭笞者還要困難。$B$B使用這加標籤設備，你能使一隻虛弱的塔巴克睡著，並為其且加上標籤，當生物長大時我將用它來跟蹤生物。加標籤設備將不會有效，除非塔巴克已經消耗掉它大多數的能量。', '幫阿魯尼·月火為風暴之尖的12隻塔巴克貼上標籤。你可以使用塔巴克標示器在塔巴克種鹿或者塔巴克的身上。', '', '去虛空風暴找風暴尖塔的歐瑞恩·月焰。', '', '標記塔布羊', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10428, 'zhTW', '失蹤的漁夫', '在我們受傷發燒的客人夢裡，她提到一個漁夫，科倫，在藍謎島西南方海岸外的銀謎小島上身陷苦痛。對於一切所發生的事情，沒有人有機會調查它，但是我確實感到有一點擔心。或許有些你能做的事，$n?', '到藍謎島海岸外的銀謎小島東南方碼頭找到科倫。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10429, 'zhTW', '自然過頭時', '秘境技術擁有這樣的力量!當然，有一些我們不敢超越的界線，$n。$B$B允許生物生長太大或者太快可能就像一個荒蕪的風景一樣有害。$B$B我已經聽到謠言說東方的水池中有這樣的一種生物。我聽說伊斯瑞爾商人密謀為了娛樂去抓那長得太快的海蛇，但是我對這巨大生物有另一目的。為我帶來這生物的心臟，好讓我可以研究它。', '風暴之尖的阿魯尼·月火要你為她帶來一個笨重的海蛇心。', '', '去虛空風暴找風暴尖塔的歐瑞恩·月焰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10430 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10430, 'zhTW', '測試原型', '我在做一台攜帶式的生成器修理工具以供聯合團在一些更嚴厲的氣候使用。就算這樣，它並不是為虛空風暴所設計，但是用在那裡我們應該不會有任何問題的。$B$B我已經計畫與我最好的技師上去秘境原野，在虛空石東北方更遠處。帶這件原型到塔斯爾。他將知道要利用它做什麼。如果它成功的話，我們就能利用它在更大的秘境加強護罩生成器。', '將修理儀器帶去秘境原野交給塔斯爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10431, 'zhTW', '外來的協助', '日怒的簡報支援了這個理論，凱爾薩斯已取得外界的幫助來建造及運作這些法力熔爐。對象是誰還不知道，雖然我們可能可以在法力熔爐艾拉中發現答案。$B$B我已經派了一組我的人馬前往查察周邊的區域。到北邊的吐魯曼平臺去和與凱嵐談談。看看他在法力熔爐艾拉那發現了什麼。找出是誰在幫助及關照這些日怒軍隊。', '到52區北邊的吐魯曼平臺與凱嵐談談。為奧多爾完成任務會使你的占卜者聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10432 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10432, 'zhTW', '毀滅的證據', '你應該也注意到了，法力熔爐艾拉到處充滿了燃燒軍團的僕人。凱爾薩斯與燃燒軍團結成了同盟。他一定是察覺到伊利丹的墮落行為已經陷入了瘋狂於是就加入了他們。$B$B假如占卜者獲得確切的證據，這將會使他們在政治上獲得相當大的好處。我知道事實上燃燒軍團在東邊基地的軍隊已經接獲了凱爾薩斯的命令。$B$B取得這些命令然後交給薩洛迪恩。', '從法力熔爐艾拉的惡魔身上取得8個凱爾薩斯的命令，並且將它們帶到52區然後交給間諜大師薩洛迪恩。為占卜者完成任務會使你的奧多爾聲望降低。', '', '去虛空風暴找52區的間諜大師薩羅迪恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10433 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10433, 'zhTW', '持續觀察', '這些伊斯利聰明又非常細心，所以我會在這成為一個簡單的毛皮商人一點都不奇怪。事實上，我是從52區派來評估伊斯利用來產生秘境技術的。$B$B我需要你的幫忙，$c。我們已被要求無論何時都使用非哥布林的媒介。$B$B我要你去做得就是帶給我一些裂牙山貓毛皮以偽裝成一個獵人。你可以到秘境領地那的各處找到山貓。', '帶10個裂牙山貓毛皮給領地崗哨的休利·波爾。', '', '去虛空風暴找中央生態圓頂的舒利·波爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10434 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10434, 'zhTW', '最佳拍檔', '做得好。$B$B<休利向你眨眼。>$B$B我想他們應該相信了。現在，當我派你去風暴之尖與我的合夥人們談話時，他們對你將不會有任何猜疑。$B$B你要尋找傑克森和歐杜毒針。他們將告訴你所有你需要知道的。告訴他們是休利派你來的。', '與風暴之尖的歐杜毒針交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10435 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10435, 'zhTW', '回收物資', '<歐杜四處看看然後降低她的聲音。>$B$B我確信休利有告訴你一點關於我們在這裡的工作。當雅克森和我外出在原野「狩獵」的時候，我們一直在收集伊斯利秘境生成器的碎片，並且把它們藏在我們獵殺的生物，秘境原野猛禽的巢穴裡。$B$B那是一個風暴之尖東北方很遙遠的地區，靠近虛空石。我不期望你會在那裡碰到許多伊斯利，但是你願意幫助我們收集秘境生成器的碎片嗎?', '風暴之尖的歐杜毒針要你為她帶回10個秘境生成器碎片。', '', '去虛空風暴找風暴尖塔的針眼奧蒂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10436 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10436, 'zhTW', '全部清除!', '在我們能開始試驗之前，我們必須先確定這地區已清除掉會干擾的任何東西。在我們的情況中，那表示是這些長得太快的蜥蜴。$B$B<塔斯爾指向那些鐮齒迅猛龍。>$B$B假如那些傢伙之一決定在生成器啟動時咬一口，那將無法預料會發生什麼事。在我身為一位技師的所有歲月中，我已經看見過許多奇怪的東西，包括開始裝的很謙遜而令人厭惡的縫合怪。', '駐紮在秘境原野的塔斯爾要你殺死12隻鐮牙迅猛龍。', '', '去虛空風暴找邊緣生態圓頂的塔沙爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10437 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10437, 'zhTW', '破壞的訣竅', '在法力熔爐奧崔斯的上方有一個虛空裂洞，就是那些虛無領主，迪曼修斯通過的地方。那個裂洞提供迪曼修斯和虛無的聯結，使他免於身體的傷害。要是我們能夠將迪曼修斯用來保持他自己形體逐漸消失的管道阻斷，我們就能摧毀它並隨後將迪曼修斯銷毀。$B$B要這樣做，我們首先要你從他派去做骯髒工作的虛無生物身上收集那些迪曼修斯的碎片。', '虛空風暴上護國者哨站的戴比瑞教授要你去找回8片迪曼修斯碎片。', '', '去虛空風暴找維序派哨站的達比雷教授。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10438 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10438, 'zhTW', '乘著虛空之翼', '來，$n。帶著這個相位干擾器上陣吧!受保護的虛空龍將會帶你飛到夠接近奧崔斯的地方讓你可以將干擾器丟在虛無導線上方。$B$B盡量多丟幾個干擾器以確定消滅完全!$B$B你準備好後，就跟虛無龍談談，他會帶你上去。$B$B要是你錯過了目標，你可以在上去前跟我拿更多的炸彈。', '虛空風暴的護國者哨站的戴比瑞教授要你在進入奧崔斯之上的虛無導線範圍內使用你的相位干擾器。多丟幾個相位干擾器以確認全數目標都消滅了。在你跟虛無導線距離夠近的時候使用相位干擾器它就會自動導向虛無導線。在你成功後回去找戴比瑞教授!', '', '去虛空風暴找維序派哨站的達比雷教授。', '摧毀空靈管道', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10439 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10439, 'zhTW', '『吞盡者』迪曼修斯', '你勇敢的行動已經迫使阿密爾反擊了!他已經部署了瑟翼德上尉以及復仇者!$B$B現在剩下的就是摧毀迪曼修斯了。$B$B當你準備好後，我會需要瑟翼德。如果他目前沒有在進行另一場戰鬥，那麼他會在這裡的正東方等候你下的命令。$B$B當你準備好要應戰時讓他知道一下，他會讓他的軍隊投入戰鬥中!$B$B祝你好運，凡人!我們已經追捕迪曼修斯一千年了!', '護國者哨站的戴比瑞教授要你跟瑟翼德上尉談談，然後跟著他的軍隊到法力熔爐奧崔斯殺掉『吞盡者』迪曼修斯!', '', '去虛空風暴找維序派哨站的達比雷教授。', '', '與薩義德上尉交談', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10440 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10440, 'zhTW', '成功!', '這個測試徹底的成功了!我們可以使用這個裝置來開始修復秘境。$B$B將測試結果的消息帶到風暴之尖並讓加巴知道我也找到護罩生成器破壞的原因了。好幾個地方的生成器組件內主要的零件遺失了。這不是意外，$n，也不是技術上的失誤。我們遭小偷了。', '回到風暴之尖與加巴談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10441, 'zhTW', '推銷貨物', '<奧蒂再次壓低了嗓門。>$B$B我打算將手頭上的貨偷偷送回52區。這些零件可以組裝出不止一臺的掩碼生成器，為我們帶來難以估量的商業利益。$B$B我看見塞納里奧遠征隊的代表在與虛靈協商，希望能獲得生態圓頂科技的資料。你不妨告訴她，她想要的貨我們也有，而且價碼非常合理。這樣她就不用和那些狡詐的虛靈繼續交涉了。', '與虛空風暴中風暴尖塔底部的歐瑞恩·月焰談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10442, 'zhTW', '協助塞納里奧前哨', '$c，有個叫做塞伊亞·紅髮的牛頭人為了要我們提出協助而一直糾纏我們。她屬於塞納里奧遠征隊，而且他們已經在從這裡通往贊格沼澤西邊道路的南面設立了一個小哨站。$B$B假如你走到了棘牙丘陵，表示你走過頭了。$B$B你可以去那邊看看她需要什麼幫助嗎?我可不想為了這種小事情而驚動到遊俠隊長范瑞。', '獵鷹者崔娜·河風要你去向地獄火半島上塞納里奧前哨的塞伊亞·紅髮提供你的幫忙。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10443, 'zhTW', '協助塞納里奧前哨', '塞納里奧議會已經派出了一支遠征隊到外域，就我的了解，他們是來這裡研究發生了什麼事情並且盡他們的能力挽回已經造成的傷害。$B$B他們已經在西邊設立了一個小型哨站，就在通往贊格沼澤道路的南邊。$B$B你願意去那邊看看有什麼你可以幫的上忙嗎?去跟塞伊亞·紅髮談談吧，當初就是她向我們要求協助的。', '『智者』阿曼希望你在塞納里奧前哨的地獄火半島向塞伊亞·紅髮貢獻你的力量。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10444 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10444, 'zhTW', '到艾蘭里哨站報到', '立即行動!$B$B我們在出了這裡接近火翼崗哨的地方有個我要你去跟他談談的人。他對你下一步要做得事有更好的想法。$B$B到艾蘭里哨站外找莫瑞狄恩中尉報告並告知他狀況。你可以在火翼崗哨正南方的南方河岸堤往東北方找到這個崗哨。$B$B一路平安啊，$n。', '珍奈·星語要你去泰洛卡森林的艾蘭里哨站回報莫瑞狄恩中尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10445 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10445, 'zhTW', '永恆之瓶', '伊利丹從永恒之井裝了七瓶帶走。他將其中三瓶倒入了海加爾山頂的湖中，於是第二個永恒之井就這麼產生了。多年來一般人認為其他的瓶子已經失蹤了。$B$B隨著黑暗之門的開啟，我們發現伊利丹給了他的副官凱爾薩斯還有瓦許一人一瓶。取回他們的持有的部份;我們需要把它們當作媒介來開啟通往海加爾山的傳送門，不論是通往現在還是遠古以前。海加爾山戰役的結果必須要保存下來。', '時光之穴的索芮朵蜜要你去從盤牙蓄湖的瓦許女士身上取得瓦許的殘存之瓶，從風暴要塞的凱爾薩斯·逐日者身上取得凱爾薩斯的殘存之瓶。', '', '去找塔納利斯的索莉多米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10446 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10446, 'zhTW', '最終的密碼', '他們正在庭院中製造第二個法力炸彈。我的情報顯示這顆炸彈的最終的密碼在火翼崗哨，由這個計畫的監督者薩爾斯·烏德恩所持有。$B$B$n，你必須回到那裏去從他身上取得最終的密碼。他通常都在最高的那座塔的頂端。$B$B拿到這個最終的密碼到中庭找到炸彈並將它引爆。$B$B只有這樣我們才能確保艾蘭里堡壘的安全。', '莫瑞狄恩中尉要你使用最終的密碼去引爆法力炸彈。完成後回報給泰洛卡森林內艾蘭里堡壘的珍奈·星語。', '', '去泰羅卡森林找奧蕾莉亞要塞的傑奈·星語。', '', '引爆魔法炸彈', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10447 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10447, 'zhTW', '最終的密碼', '他們正在庭院中興建第二個法力炸彈。我的情報顯示這顆炸彈的最終的密碼是由火翼崗哨這個工程的監督者，薩爾斯·烏德恩所持有。$B$B$n，你必須回到那裏去從他身上取得最終的密碼。他通常都在最高的那座塔的頂端。$B$B取得這個最終的密碼到中庭找到炸彈並將它引爆。$B$B只有這樣我們才能確保碎石堡的安全。', '丘尼士官要你使用最終密碼清單去引爆法力炸彈。完成後回報泰洛卡森林裡碎石堡的吐奇。', '', '去泰羅卡森林找碎石堡的圖基。', '', '引爆魔法炸彈', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10448 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10448, 'zhTW', '到碎石營地報到', '立即行動!$B$B我們在出了這裡接近火翼崗哨的地方有個我要你去談談的人。她對你下一步要做的事有更好的想法。$B$B到碎石營地外找丘尼士官報告並告知她狀況。$B$B出了崗哨外順著路往北方出發。從杜瑞的中部，順著路到東邊去。你就會在火翼崗哨正西南方的河岸邊找到這個營地。$B$B祝你好運，$n。', '吐奇要你去向泰洛卡森林裡碎石營地的丘尼士官報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10449 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10449, 'zhTW', '藥劑師席蓮娜', '藥劑師席蓮娜一直在研究地獄火半島的野獸。她想要你收集的一個血液樣本;幸運的話，她或許會發現是什麼把那些噬骨者混蛋的皮膚變成紅色的!$B$B席蓮娜在搶奪者荒野，索爾瑪的東南方。沿著往東的路走，等你看到一塊被摧毀，發著綠光的金屬，你就到了。她在雙足翼龍後面有一個營地。', '索爾瑪的弗爾托克·破斧者要你把噬骨者鮮血樣本帶給搶奪者荒野的藥劑師席蓮娜。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10450 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10450, 'zhTW', '噬骨者鮮血', '噬骨者!他們全都該死!看到他們紅色的皮膚和墮落讓我的血液沸騰!$B$B我有個任務要給你，$n。殺死噬骨者獸人並收集他們邪惡的鮮血。有一個藥劑師需要血液來做她的實驗，這樣我們就能知道這些獸人是如何被惡魔給污染的，一種我們最近才剛讓自己解放出來的污染。$B$B到南方的光榮之路，噬骨者在旁邊毀壞的城垛搜尋有用的物品。當你完成任務後回來找我。', '帶12個噬骨者血瓶給索爾瑪的弗爾托克·破斧者。', '', '去地獄火半島找索爾瑪的烏托克·斷斧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10451 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10451, 'zhTW', '從考斯卡水池逃脫', '感謝大地之母!我跟其他人在幾天前分開了。我立志要查出引起水之靈騷動的來源。我的調查引領我到了考斯卡，納迦污染影月谷水源頭的地方。$B$B不幸的是，我被發現並囚禁了起來。我無法形容他們對我做了什麼恐怖的事。$B$B我們必須離開這個地方!幫我逃離並找到在詛咒祭壇的托爾洛克。', '護送大地治癒者威爾達逃出考斯卡水池並於完成後找到在詛咒祭壇的大地治癒者托爾洛克，你可以在古爾丹火山的西邊郊區找到他。', '護送大地治癒者維爾達到達安全地點', '去影月谷找詛咒祭壇的大地治癒者託洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10452 AND `locale` = 'zhTW';
DELETE FROM `quest_template_locale` WHERE `ID` = 10453 AND `locale` = 'zhTW';
