INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10464, 'zhTW', '先知的誓約', '$c，你既然做出了承諾，就要實現自己的諾言。$B$B為流沙之鱗效力，你就會獲得應得的獎勵。如果你失敗的話，歷史的程序將被破壞！', '當你在流沙之鱗中的聲望達到尊敬後，將永恆之戒交給時空之穴的索莉多米。', '', '', '', '', '', '', 0);
