INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10468, 'zhTW', '先知的誓言', '$N，你實現了自己的諾言。為此，你獲得了青銅龍的賞識。$B$B只要你繼續維護髮生在海加爾山的歷史事件的正常程序，那麼我將不斷在永恆之戒中注入力量，直至達到它所能容納的能量的顛峰。這一天不會太遠的。', '當你在流沙之鱗中的聲望達到崇敬後，將永恆之戒交給時空之穴的索莉多米。', '', '', '', '', '', '', 0);
