INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10472, 'zhTW', '先知的盟約', '$N，你取得的成就已經超越了我的想像。$B$B與青銅龍一樣，你能自由地穿行在時空中。你註定會成為一名強者，而我非常樂意幫你達成這一目標。$B$B繼續為流沙之鱗效力吧，我將繼續在永恆之戒中注入力量，直至達到它所能容納的能量的顛峰。', '當你在流沙之鱗中的聲望達到崇拜後，將永恆之戒交給時空之穴的索莉多米。', '', '', '', '', '', '', 0);
