INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10476, 'zhTW', '殘暴的敵人', '如果你要想證明你對我們的忠誠，除了對抗我們的敵人外沒有更好的方式了。$B$B在這些當中，沒有其他人可以與這些巨魔在力量及殘暴上相比。把他們脖子配戴的戰爭串珠帶來給我作為他們死亡的証明，我會讓其他人知道你英勇的表現。', '泰拉的守望者莫布夫·吉爾要你去從納葛蘭上各種不同的巨魔身上取得10個黑曜石戰爭串珠。', '', '去納格蘭找塔拉的監護者莫布吉爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10477 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10477, 'zhTW', '更多的戰爭串珠', '', '你還有其他的黑曜石戰爭串珠嗎，$n?。', '', '去納格蘭找塔拉的監護者莫布吉爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10478 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10478, 'zhTW', '更多的戰爭串珠!', '', '', '', '去納格蘭找加拉達爾的監護者布羅克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10479, 'zhTW', '證明你的力量', '雖然我們在找尋平靜的生活，但我們的敵人太多了。這些當中，沒有人可以跟巨魔完全殘暴的力量相比。$B$B如果你是試圖想對我們證實你的力量，就將他們戴在脖子上的戰爭串珠帶來給我。我會告訴其他人你的成就的。', '卡拉達爾的守望者波洛克要你去從納葛蘭上各種不同的巨魔身上收集10個黑曜石戰爭串珠。', '', '去納格蘭找加拉達爾的監護者布羅克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10480, 'zhTW', '暴怒的水之靈', '本區的伊利達瑞納迦已控制了影月谷唯一純淨的水源頭。$B$B你可以在這裡的正北方找到納迦的巢穴:考斯卡。考斯卡週遭是好幾塊波濤洶湧的水流區對著島嶼痛苦的怒吼著。那些就是暴怒的水之魂在其中徘徊。$B$B到考斯卡去使用這個靈魂圖騰捕捉水之魂。你在考斯卡水池附近可以找到這些靈魂的最廣大集散地。', '影月谷的詛咒祭壇的大地治癒者托爾洛克要你使用靈魂圖騰去捕獲5個水之魂。', '', '去影月谷找詛咒祭壇的大地治癒者託洛克。', '捕獲水之魂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10481, 'zhTW', '暴怒的風之靈', '去東南方冒險吧，英雄。當你看到一片巨大的藍色水晶從陸地上突出時，你就已經到達你的目的地了。就是那裡，在虛空之翼農場，你可以找到暴怒的風之靈。他們漫遊在陸地的懸崖及山邊。$B$B摧毀它們受折磨的形體並用這個靈魂圖騰捕捉它們的靈魂。完成後回來找我。', '影月谷的詛咒祭壇的大地治癒者托爾洛克要你使用靈魂圖騰去捕獲10個大氣之魂。', '', '去影月谷找詛咒祭壇的大地治癒者託洛克。', '捕獲氣之魂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10482, 'zhTW', '魔獄獸人拾荒者', '噬骨者氏族的獸人，拾荒者潛伏在廢棄的城垛俯瞰著光榮之路。我們必須假設這些魔獄獸人在為他們的主人收集地獄火堡壘裡的戰爭機械零件 - 一定要阻止他們!$B$B去北方找噬骨者獸人，$n。找到他們並殺了他們!但要謹慎行事，因為雖然這些獸人是次要的魔獄獸人氏族，他們的力量仍可匹敵我們到目前為止挑戰過任何的綠皮膚獸人……', '殺掉20個噬骨獸人，完成後回到榮譽堡回報阿瑪迪。', '', '去地獄火半島找榮耀堡的阿曼蒂中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10483, 'zhTW', '邪惡的預兆', '$n，在我們對抗魔獄獸人的血之谷氏族時，我們在他們身上發現不祥的飾品。這些獸人從榮譽堡陣亡的士兵身上收集徽記再製造成被詛咒的符咒。我們擔心血之谷獸人的黑暗魔法已將我們的徽記轉變成對抗我們的邪惡符咒!$B$B從薩斯葛爾的血之谷獸人身上找到這樣的符咒，在東邊，再把它帶到薩斯葛爾的東北方，給遠征隊哨塔的剛脊下士。', '榮譽堡的阿瑪迪中尉要你帶來1個被詛咒的護符給遠征隊哨塔的剛脊下士。', '', '去地獄火半島找遠征軍崗哨的埃隆雷下士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10484, 'zhTW', '被詛咒的護符', '$n，我們不能允許血之谷獸人擁有他們被詛咒的護符!你一定要為我們取回它們才能把它們處理掉，這樣原本擁有它們的士兵們才能為自己的犧牲感到光榮。$B$B前往薩斯葛爾，血之谷被詛咒的住所，進行你可怕的任務……拿到護符後再回來找我。', '帶著12個被詛咒的護符回去給遠征隊哨塔的剛脊下士。', '', '去地獄火半島找遠征軍崗哨的埃隆雷下士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10485 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10485, 'zhTW', '血之谷的督軍', '你展現了強大的力量和時運，因為你探究了薩斯葛爾並活著回來!現在，讓我們期望你的好運能繼續保持，因為我有個緊迫的任務要請你去做......$B$B督軍莫克坐在薩斯葛爾的兵營裡，指揮著他的邪惡軍隊來對抗我們。他的策略既狡詐又殘酷，我必須承認他極有可能成功擊倒我們。因此，$n，我要你將莫克從他的位子上除掉。把他的護甲帶來給我這樣我們就能把它展示給士兵們看，鼓舞他們的士氣。', '把督軍莫克的破碎胸甲帶給遠征隊哨塔的剛脊下士。', '', '去地獄火半島找遠征軍崗哨的埃隆雷下士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10486, 'zhTW', '失控的侵略', '在雷霆王被曼諾洛斯之血轉化成魔獄獸人前他們曾是一個驕傲的獸人氏族。$B$B最近我們從污染下游河谷的巨魔手中重新發現了這個獸人村落。他們在雷霆王氏族遺棄這裡後進駐。$B$B我們要保住這個地方，而我需要你來幫忙。$B$B在鋸齒山脊的南方及西方，那裡有一群放血者已經變成我們的災難。他們不停地繁殖。$B$B殺掉他們並於完成後回來找我。', '葛德雷克要你去殺掉12個刃翼血信。完成後回到劍刃山脈的雷霆王村找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10487, 'zhTW', '龍的粉末', '聯盟最近進駐西邊，使用他們精靈法術在短期內建立一個城鎮及果園。我們得將她們的防禦削弱以防她們不會也生出勇氣來。$B$B我有個方法可以達成目的甚至更好。我要你越過橋到西南方去，經過血槌深谷進去生命之林。$B$B攻擊她們在生命之林的精靈龍防禦並將在它們翅膀中找到的魔法粉塵帶回來給我。', '葛德雷克要你去取得4份精靈龍粉末。完成後，回到劍刃山脈的雷霆王村找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10488, 'zhTW', '保護我們自己', '有了你帶回的魔法粉塵，我製作了一個魔法藥膏可助於我們本身的防護。$B$B我們的恐狼完美的將坐騎，守衛及朋友集結於一身，但是那些聯盟的人渣在鋸齒山脊那獵殺它們。$B$B$N，我要你將這個藥膏使用在我們那些恐狼朋友身上。下一次聯盟再派他們的獵殺團隊來時就會得到一個野蠻的驚喜。$B$B要小心還是有一些狼可能不喜歡這個藥膏，將會反咬你。', '在5隻雷霆王恐狼身上使用葛德雷克的藥膏來強化它們及鋸齒山脊的防禦。完成後回到劍刃山脈的雷霆王村找葛德雷克。', '', '', '強化雷霆王恐狼', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10489, 'zhTW', '砍伐古老之樹', '懸賞!$B$B斯卓霖普·深根，戰爭古樹及希爾瓦納南方的生命之林防衛者領袖。$B$B往西邊過了橋後越過血槌深谷就可以找到他。$B$B將他的大箱帶回給雷霆王村旅館內的吐查克·雙爪。', '取得斯卓霖普·深根的樹幹並送到劍刃山脈的雷霆王村給吐查克·雙爪。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10490 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10490, 'zhTW', '水之召喚', '我感覺到距離你上一次測試已經有一段時日了。這是因為先知諾柏多對你有所要求。$B$B你被派去學習了水元素的奧義因此你的智慧一定大有長進。$B$B我相信你記得如何從卡林多上黑海岸的奧伯丁搭船到艾克索達吧?你也記得哪裡可以找到艾克索達裡水晶大廳的先知，對吧?]', '與藍謎島中艾克索達裡水晶大廳的先知諾柏多談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10491 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10491, 'zhTW', '風的召喚', '$n，先知諾柏多再一次的對你有所要求。該是時候要你去學習風的秘密，元素當中的最後一個!$B$B我要你知道我對你到目前所完成的所有事感到驕傲。我知道你前途光明。$B$B到卡林多上黑海岸的奧伯丁搭船。穿越迷霧之海到藍謎島上艾克索達的水晶大廳內找先知。', '與藍謎島中艾克索達裡水晶大廳的先知諾柏多談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10492 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10492, 'zhTW', '誠摯的建議', '你好，$c。我有一些你可能會感興趣的東西。$B$B它很像你們那個職業的人會穿戴的典型護甲，但是等級高很多。只要你幫我一個小忙，我願意和你交換一件普通裝備。$B$B冬泉谷的霜刃豹和熊的鮮血裡有我目前需要的成分。幫我帶來足夠的樣本還有護腕裝備，以及一點金子。你會發現你的付出是值得的。', '取得15滴冬泉血滴樣本，20金和1套野性之心束腕給鐵爐堡的德莉娜。', '', '去鐵爐堡找王座廳的德莉亞娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10493 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10493, 'zhTW', '誠摯的建議', '嗨，$c!我從你舉止可以看出，你已經見識過這世界許多事了。但是我敢打賭你一定沒有看過像這樣的護甲。$B$B幫我個小忙，我就和你交換一套普通的護腕。$B$B我現在需要足夠的大型希利蘇斯蜘蛛與蠍的毒液樣本。把物品帶給我再加上幾枚金幣，我就履行這項交易。', '取得15滴希利蘇斯毒液樣本，20金和1套光鑄護腕，帶給奧格瑪的莫克瓦。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10494 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10494, 'zhTW', '公平的補償', '你信守承諾將莫克斯建構的儀器帶來了。我相信如果我給你獎賞，你會感興趣的。若你想升級的話，就把腰帶和一整套手套拿來給我。我承諾我給你的一定是超過精良的物品。', '將元素之索以及一雙元素護手帶給鐵爐堡的德莉娜。', '', '去鐵爐堡找王座廳的德莉亞娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10495 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10495, 'zhTW', '小小的補償', '你已經證明了自己是個非常守信譽的$r，$N。我堅信你能夠幫我走出當前的困境，當然我也會根據你的表現給予你一些獎勵。$B$B現在我可以幫你更換腰帶和手套，如果事情進展順利，我會繼續幫你升級其它的部件。', '將一條光鑄腰帶和一副光鑄護手交給奧格瑪的莫克瓦爾。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10496 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10496, 'zhTW', '告別安希恩', '瓦薩拉克的靈魂就封印在這枚護符裡。因為貪婪，我們愚蠢地將它分成了好幾部分，絲毫不瞭解這會為我們帶來怎樣殘酷的詛咒。$B$B唯一解除瓦薩拉克的法術的辦法，就是將這枚勳章重新組合在一起。回到德莉娜那裡去，告訴她說，布德利已經是她找齊剩餘部分的最後希望了。順便跟她提一下你應得的報酬。$B$B我只希望能從此安息。祝你好運……你會非常需要運氣的！', '帶上一雙元素長靴、一條元素護腿和一副元素護肩，回去向鐵爐堡的德莉娜覆命。', '', '去鐵爐堡找王座廳的德莉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10497 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10497, 'zhTW', '告別安希恩', '瓦薩拉克的靈魂就封印在這枚護符裡。因為貪婪，我們愚蠢地將它分成了好幾部分，絲毫不瞭解這會為我們帶來怎樣殘酷的詛咒。$B$B唯一解除瓦薩拉克的法術的辦法，就是將這枚勳章重新組合在一起。回到莫克瓦爾那裡去，告訴他說，布德利已經是他找齊剩餘部分的最後希望了。順便跟他提一下你應得的報酬。$B$B我只希望能從此安息。祝你好運……你會非常需要運氣的！', '帶上一雙光鑄戰靴、一條光鑄腿鎧和一副光鑄肩鎧，回去向奧格瑪的莫克瓦爾覆命。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10498 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10498, 'zhTW', '最後的獎賞', '這真是個令人驚異的故事，$N！我實在是太感謝你了，其它一些與此有關的人也會對你表示真心誠意的感激。或許今天晚上我就能睡個安穩覺了。$B$B這兒還有些你絕對會很喜歡的東西，送你算作獎勵吧。', '將你的元素罩帽與元素外衣交給德莉娜。', '', '去鐵爐堡找王座廳的德莉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10499 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10499, 'zhTW', '最後的獎賞', '確實是個令人驚異的故事，$N！我實在是太感謝你了，其它一些與此有關的人也會對你表示真心誠意的感激，這一點我向你保證。你的努力使我們終於認識到了自己過去所犯的錯誤。$B$B這兒還有些你絕對會很喜歡的東西，送你算作獎勵吧。', '將你的光鑄頭盔與光鑄胸甲交給莫克瓦爾。', '', '去找奧格瑪的莫克瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10500, 'zhTW', '部落需要你的幫助！', '嗨，我很高興你決定聽我說完。部落需要所有的幫助來準備安其拉之戰，這表示我們需要你!連我們現在講話的時候，都有官方的收集者在收集戰爭需要的材料，但是我們沒有你的幫助仍然無法達到目標，$n!$B$B你應該去和負責的督軍格爾庫克談談。你看怎麼樣，$c?你會幫我們做這重要的準備嗎?', '和奧格瑪精神谷的督軍格爾庫克交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10501 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10501, 'zhTW', '聯盟需要你的幫助！', '嗨，我很高興你決定聽我說完。聯盟需要所有的幫助來準備安其拉之戰，這表示我們需要你!連我們現在講話的時候，都有官方的收集者在收集戰爭需要的材料，但是我們沒有你的幫助仍然無法達到目標，$n!$B$B你應該去和負責的戰場元帥斯諾·落雪談談。你看怎麼樣，$c?你會幫我們做這重要的準備嗎?', '和鐵爐堡軍事區的戰場元帥斯諾·落雪交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10502, 'zhTW', '血槌巨魔', '希爾瓦納有一個比雷霆王村的部落還要致命的威脅。$B$B我說的是居住在這些山區中的巨魔。這裡的南邊還有東邊，深谷的底部住著血槌氏族。雖然他們並不是唯一威脅我們的巨魔氏族，他們卻是最靠近我們的一族。$B$B我要你往南穿過生命之林，然後轉向東邊的道路前往他們的前哨站。在血槌前哨站盡可能的殺光那些血槌巨魔。', '指揮官天影要你去血槌前哨站殺死30個血槌巨魔。當你完成這個可怕的任務後，回到劍刃山脈的希爾瓦納向他回報。', '', '', '殺死血槌巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10503, 'zhTW', '劍刃的威脅', '雷霆王村有一個比希爾瓦納的聯盟還要可怕的威脅。$B$B我說的是居住在這些山區中的巨魔。這裡的西邊，深谷的底部住著劍刃氏族。雖然他們並不是唯一威脅我們的巨魔氏族，他們卻是最靠近我們的一族，當初我們就是打敗他們才佔領這個地方。$B$B往北越過鋸齒山脊，然後順著路往下走，你就會到達他們的要塞。在劍刃要塞還有劍刃庭園盡可能的殺光那些劍刃巨魔還有劍刃迅猛龍。', '吐查克·雙爪要求你在劍刃要塞還有劍刃庭園殺死30個劍刃巨魔還有10隻劍刃迅猛龍。任務完成時回到劍刃山脈的雷霆王村向他回報。', '', '', '殺死劍刃巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10504, 'zhTW', '劍刃巨魔', '血槌氏族的北邊有一個更嚴重的威脅:劍刃要塞。$B$B這些劍刃巨魔是山區之中最強的氏族，受到被稱為弒龍者戈魯爾的古羅還有他的七個兒子所支持。$B$B現在我們已經解決了血槌氏族，是時候該轉移目標到他們的競爭對手了。$B$B從血槌要塞往北穿過深谷直到你到達劍刃要塞還有劍刃庭園。盡可能殺光裡頭的劍刃巨魔。', '指揮官天影要你在劍刃要塞還有劍刃庭園殺死30個劍刃巨魔。任務完成時回到劍刃山脈的希爾瓦納向他回報。', '', '', '殺死劍刃巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10505, 'zhTW', '血槌巨魔', '在劍刃氏族的南方還有另外一個威脅:血槌前哨站。$B$B雖然血槌巨魔不是這些山區中最強的氏族，不受名為弒龍者戈魯爾的古羅厚愛，不過他們緊接在第二名。$B$B現在我們已經解決掉劍刃氏族，是時候轉移焦點對付他們的對手了。$B$B從劍刃要塞往南經過深谷一直走直到你到達血槌前哨站為止。盡你所能的殺光附近的血槌巨魔。', '吐查克·雙爪要你在血槌前哨站殺死30個血槌巨魔。任務完成時回到劍刃山脈的雷霆王村向他回報。', '', '', '殺死血槌巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10506, 'zhTW', '情況緊迫', '因為狼群的減少，部落正在尋找代替品。不幸的是附近剛好有可替代的狼。$B$B在東邊深谷下方的血槌巨魔養了一大群強壯的狼作為他們自己的守衛。我不想派你去殺掉那些恐狼，那麼為何這次我們不做點不同的呢?$B$B我已經由精靈龍的翅膀所自然落下的粉塵中提煉出一種魔法粉末。將它灑在那些恐灰狼的身上使部落對他們失去興趣。', '琳娜·月泉要你帶著她的縮小粉末並使用在5隻血槌恐狼身上，你可以在血槌前哨站及血槌深谷找到這些狼群。完成後，回到劍刃山脈的希爾瓦納找她。', '', '', '削弱血槌恐狼', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10507 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10507, 'zhTW', '轉捩點', '這是我們一直在等待的機會，$n。我們將向我們的人民宣佈我們不但發現了凱爾薩斯真正的主人是誰，我們還可以擊敗他的新主人們以證明我們的實力。$B$B我虛弱的身軀讓我不能夠親自在行動中協助你，但是我會給你一個物品使得我的力量可以傳送在大陸之間協助你。', '在熔爐基地:遺忘的北邊的侵略點:主宰者使用索奎薩爾的傳送石，傳送你的隊伍到索奎薩爾的平臺。到達之後，使用沃藍索的禮物擊敗索奎薩爾。為占卜者完成任務會使你的奧多爾聲望降低。', '', '去泰羅卡森林找占星者之臺的先知沃雷塔爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10508 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10508, 'zhTW', '給沃藍索的禮物', '我不想派你兩手空空的去沃藍索那裡。不給對方留下深刻的印象不是我的行事風格。$B$B想要進入位於北方的索奎薩爾的領地的話，我們會需要用到他專用的傳送器 - 由索奎薩爾的傳送石上鎖的。第一部分的石頭在熔爐基地:遺忘的鍛造大師莫爾洛克手中。第二部份則由熔爐基地:苦難的惡魔希洛斯持有。$B$B去取得這兩個部份，沃藍索會感動到說不出話來的。', '52區的間諜大師薩洛迪恩要你從熔爐基地:遺忘的鍛造大師莫爾洛克身上取得上部索奎薩爾之石，從熔爐基地:苦難的希洛斯身上取得下部索奎薩爾之石。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去虛空風暴找52區的間諜大師薩羅迪恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10509 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10509, 'zhTW', '前往光榮', '現在我可以理所當然的派你回去撒塔斯城。你發現了凱爾薩斯與燃燒軍團結盟的證據，也拿到了這個霸主後門的鑰匙。$B$B確認沃藍索不會因為這個消息的刺激而倒下 - 這老頭變得有點虛弱，如果你明白我的意思的話。你可以在占卜者階梯的先知書庫內找到他。', '帶著索奎薩爾的傳送石到撒塔斯城的占卜者階梯給『先知』沃藍索。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10510, 'zhTW', '進入德萊尼礦坑', '看到有人願意幫助這裡真的是太好了!$B$B波爾葛利姆和我是探險者協會的一員，我們到這是要知道我們能從這些山中得到什麼。我們聽過各種不同的傳說，我等不及要紮營開始探險。$B$B有一個東西特別吸引了我的注意力。夜精靈提到東邊深谷下面有個地方叫做德萊尼礦坑。就在血槌前哨站的南方盡頭。我想要那邊土生土長的一些水晶。', '波爾葛利姆·頑錘要你去收集5個德萊尼礦坑水晶然後回到劍刃山脈的希爾瓦納找她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10511, 'zhTW', '怪酒', '如果我要現在就開始這個假期，那麼我就需要更多的酒。不幸的是，這些精靈們根本不懂發酵的藝術。$B$B我偶然聽到深谷那邊的血槌巨魔有很多的酒。我想要試看看。$B$B幫我個忙吧?往南方出發經過生命之林，接著下了斜坡往東進入血槌前哨站帶幾瓶酒給我?我聽說他們有幾大桶的酒就放在附近而釀酒大師會帶著酒到處提供給所有的巨魔。', '波爾葛利姆·頑槌要你拿到11瓶血槌蠻禁烈酒給他。一旦你完成後，將這個帶到劍刃山脈的希爾瓦納給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10512, 'zhTW', '灌醉劍刃巨魔', '我不會再嚐一口那個難聞的穢物!不過這倒是給了我一個點子。$B$B<波爾葛利姆眼中閃了一下。>$B$B計畫是這樣的。我們知道那些血槌氏族實際上每天都要牛飲這些東西。但我好奇他們的敵人，劍刃巨魔，是怎樣想的?$B$B$N，我要你帶著這些剩下的廢物去看看是否能夠讓這些劍刃巨魔喝醉。你可以從血槌前哨站往北通過深谷的地方找到他們。', '帶著這個血槌蠻禁烈酒並試著用來讓5個劍刃巨魔喝醉。如果你成功了，回到劍刃山脈的希爾瓦納找波爾葛利姆。', '', '', '喝醉的劍刃巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10513 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10513, 'zhTW', '歐朗諾克·碎心', '我不知道我們要如何取得那些靈魂所提及的法術，$n。老實說，我甚至不知道要從哪裡開始找起。$B$B<托爾洛克茫然的看著遠方。>$B$B嗯……雖然很久遠了但是這可能是我們唯一的機會。之前我曾經見過一位獸人到過這個地區。我曾與他短暫交談過。他是一位隱士並且提到他就住在考斯卡水池上面的東北方。找到這位獸人，歐朗諾克·碎心。$B$B就像我說過，那是很久之前的事了。', '到破碎暗礁去找歐朗諾克·碎心 - 就在考斯卡水池的北方。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10514 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10514, 'zhTW', '我經歷過很多事……', '我曾經歷過很多的事情，陌生人，不過我之前是個怎樣的人不重要。現在的我才是重點，而我現在是個農夫。$B$B我用訓練過的惡魔野豬來從破碎平原的硬土中挖出肉條來。不過，最近從東北巢穴出現的撕掠者攻擊我的動物，妨礙我取得肉條。$B$B你可以到北邊的區域去幫我收集肉條嗎?當你站在肉條土堆上時使用這個哨子就會出現一隻野豬把它挖出來!', '影月谷內歐朗諾克的農場的歐朗諾克·碎心要你去破碎平原取回10個影月塊莖。他也要你在完成任務後將歐朗諾克的野豬哨帶回來。', '', '去影月谷找歐魯諾克農場的歐魯諾克·裂心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10515 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10515, 'zhTW', '學到一課', '我們需要讓那些鐮奪怪知道壞了歐朗諾克的好事下場會如何!$B$B我要你回去破碎平原把你看到的每一個鐮奪怪的蛋都破壞掉。他們就在撕掠者地盤的深處，因此要提高你的警覺性。', '影月谷內歐朗諾克的農場的歐朗諾克·碎心要你去破碎平原破壞10個掠食鐮奪怪的蛋。', '', '去影月谷找歐魯諾克農場的歐魯諾克·裂心。', '摧毀貪婪剝石者的卵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10516 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10516, 'zhTW', '復仇者的服飾', '我知道這很怪，但我真的想要待在這個籠子裡。這讓我有絕佳的機會去進行我來這要做的事;收集劍刃氏族的資訊。$B$B我隨時都可以離開，不過我想要取回我的劍跟盾。$B$B他們的兩位領導者擁有我的裝備。卓克嘎姆擁有我的劍而瑪格多克擁有我的盾。$B$B要是你有需要的話，拿著並使用這個來自血槌前哨站的啤酒到南邊去降低他們的防衛並引誘他們兩個，不過要小心他們那些沒喝酒還清醒著的守衛!', '帶回復仇者瓦黎恩之刃及復仇者瓦黎恩之盾。然後將這兩項物品帶回劍刃山脈的劍刃要塞給復仇者瓦黎恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10517 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10517, 'zhTW', '哥爾迪姆，你的死期到了...', '劍刃要塞的領導者叫哥爾迪姆。相信我……這個名字很適合他。$B$B雖然如此，我不會低估他的。他詭計多端的使他的氏族成為弒龍者戈魯爾的親信，如今他們支配著這些山脈。而且無時無刻都有一位隨扈跟隨在哥爾迪姆身邊，包括發誓不沾血槌酒的防衛者。$B$B為了希爾瓦納的安全，我要你回去那裡解決掉他。', '復仇者瓦黎恩要你去殺掉哥爾迪姆，劍刃要塞巨魔的首領。一旦完成後，回到劍刃山脈的尖石要塞找她。', '', '去劍刃山脈找刀塔要塞的守備官烏里恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10518, 'zhTW', '插上戰旗', '我要你去從他們的一位勇士身上將劍刃旗幟偷來，帶到南方的血槌前哨站去。將旗插在他們的北槌哨塔上。$B$B這樣會激怒血槌氏族，他們會毫不留情的攻擊你。不過這樣也會將他們的敵意集中在劍刃要塞上，進而遠離希爾瓦納。$B$B在你打倒葛恩·葛羅巴諾斯拿到他的頭盔時就表示你完成任務了。將頭盔帶回希爾瓦納去。$B$B$N，這並不容易。帶一兩個朋友跟你一起去吧。', '在北槌哨塔頂端使用劍刃旗幟來誘引葛恩·葛羅巴諾斯。將旗幟跟葛恩·葛羅巴諾斯的頭盔送到劍刃山脈的希爾瓦納給指揮官天影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10519 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10519, 'zhTW', '毀滅密碼 - 歷史與真相', '<歐朗諾克調整他的姿勢站得直挺挺的。>$B$B我得要確認，$n。為了確認，我得考驗你。請原諒這個小小的偽裝。我天生是個農夫就像你是<女性/男性>一樣。要說的話，也不完全是。$B$B如果你發現了毀滅密碼，你會需要聽聽我要跟你說的事。你準備好後讓我知道，我會告訴你故事內容。', '影月谷裡歐朗諾克的農場的歐朗諾克·碎心要你聆聽他的故事。', '詛咒密碼 - 真相和歷史', '去找影月谷歐魯諾克農場的歐魯諾克·裂心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10520 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10520, 'zhTW', '協助大德魯伊鹿盔', '打擾一下，$c，如果可能的話，我想佔用你一點時間。達納蘇斯的塞納里奧議會希望能找到像你這樣經驗豐富的冒險家來幫助他們進行一項重要的研究項目。雖然我不知道詳細的情況，但是我可以告訴你，正是伊范達爾·鹿盔親自負責這項研究。要是你感興趣的話，請直接去達納蘇斯的塞納里奧區找他談談。', '與達納蘇斯的大德魯伊范達爾·鹿盔談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10521, 'zhTW', '葛洛姆特,歐朗諾克之子', '我的長子，葛洛姆特，留下來搜查考斯卡崗哨 - 就在這裡的西南方。$B$B他是家族裡的戰士 - 脾氣暴躁且嗜血成性……遺傳自他的母親。沿著考斯卡崗哨外圍找找。要是你看到納迦的屍體，葛洛姆特就一定是在附近了。$B$B找到他後，告訴他:「我們只為了理想而戰。」這會讓他知道你是碎心的朋友以避免你枉死。', '在影月谷的考斯卡崗哨找到葛洛姆特,歐朗諾克之子。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10522 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10522, 'zhTW', '毀滅密碼 - 葛洛姆特的命令', '這個納迦垃圾是我今天審問的第六個。他穿著精緻的盔甲所以我想他會知道些什麼，那些其他的傢伙都沒有用。$B$B<葛洛姆特指著周圍的這些納迦屍體。>$B$B我只打他一次就告訴我所有的事了。$B$B第一部的密碼藏在考斯卡崗哨還是考斯卡水池的一個納迦寶箱裡，就在這裡的東邊。他說納迦身上都有鑰匙。殺了他們，拿走他們的鑰匙並打開考斯卡寶箱。在你找到密碼後回來找我。', '在影月谷考斯卡崗哨的葛洛姆特,　歐朗諾克之子要你奪回毀滅密碼第一部。', '', '去影月谷找庫斯卡崗哨的格洛姆託，歐魯諾克之子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10523 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10523, 'zhTW', '毀滅密碼 - 取回第一部', '<葛洛姆特將文件捲好放進一個鎖匣裡。>$B$B把這個帶鎖箱交給父親。他在農場等你回去，就在這的東北方。$B$B告訴他我很快就會回家。一旦我真的得到樂趣後……', '帶著葛洛姆特的帶鎖箱到影月谷的歐朗諾克的農場給歐朗諾克·碎心。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10524 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10524, 'zhTW', '雷霆王氏族手工藝品', '神器上的標記指出它原來是由雷霆王氏族獸人製造的。這些獸人在變成魔獄獸人之前曾住在雷霆王村這。$B$B血錘巨魔曾暫時居住在這個村落直到最近被部落趕走了。你曾經聽說過人們試著尋找其他遺失的神器。你的腦海中浮現關於這些神器的記憶，那是一個鼓、一支箭及一片石板。$B$B到劍刃要塞去找到它們並帶回給洛克嘎·血握。', '取回雷霆王氏族大鼓，雷霆王氏族之箭以及雷霆王氏族石板。將它們隨同雷霆王氏族手工藝品一起帶回，交給劍刃山脈雷霆王村的洛克嘎·血握。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10525 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10525, 'zhTW', '幻象導覽', '$r笨蛋。你差點毀掉這個鼓!$B$B我費盡千辛萬苦來到這裡，直到現在才有所收獲。至少你能夠在別人都失敗，或是更慘的地方成功。$B$B是時候喚出幻象來引領你找到最後一個我一直在找尋的神器。$B$B拿著這個代表我的靈魂的熾熱之魂碎片。用它來將你的身體轉化為火，將你的靈魂變為幻象指引你前往最後發現雷霆王神器的位置。', '使用熾熱之魂碎片將你的靈魂轉化成幻象導覽模式。在你的幻象導覽帶領你找到最後一個雷霆王神器的所在地後，與雷霆王村的洛克嘎·血握談談。', '已發現最後的雷霆氏族神器', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10526 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10526, 'zhTW', '雷霆之矛', '如果那個我讓你看見的幻象屬實，那麼你就得往下到河谷以及血槌深谷的南方盡頭。在那你會找到德萊尼礦坑。$B$B到礦坑的後方去，取得雷霆之矛。不用管其他東西!我對於礦坑內的水晶沒有興趣，還有巨魔也是一樣。$B$B一但你拿到這個矛就馬上帶回來這裡給我!$B$B還有，$N，你要非常小心……我可不願去想要是它有任何損傷的話你會發生什麼事。', '洛克嘎·血握派你去取回雷霆之矛。將它帶回劍刃山脈的雷霆王村給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10527 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10527, 'zhTW', '阿爾托,歐朗諾克之子', '我的小兒子，阿爾托，留下來搜查伊利達瑞崗哨 - 就在遙遠的西南方，處於軍團要塞及蠻錘要塞之間。$B$B因為阿爾托是個技巧高超的獵人身兼一個職業級的追蹤手，我擔心他這次可能會過頭。伊利達瑞崗哨是伊利丹惡魔的試煉場。那些都是離開燃燒軍團投靠背叛者的惡魔!$B$B到伊利達瑞崗哨去並找到阿爾托，$n。', '在影月谷的伊利達瑞崗哨找到阿爾托,歐朗諾克之子。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10528 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10528, 'zhTW', '惡魔水晶監牢', '從這個景象來判斷，你注意到阿爾托是由徘徊廢墟中的水晶發出的能量光束來固定。你使力去試，阿爾托動都沒動。$B$B你注意到水晶的底部有一個空的縫孔 - 也許是個鑰匙孔。看來似乎好像定期就會有魅魔執行某種儀式。$B$B調查伊利達瑞崗哨的領導者。也許她手中擁有釋放阿爾托的鑰匙。', '在伊利達瑞崗哨找到並殺掉痛苦魔女卡布利莎，拿著結晶鑰匙回到阿爾托,歐朗諾克之子的屍體那。', '', '去影月谷找伊利達雷崗哨的阿托爾，歐魯諾克之子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10529 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10529, 'zhTW', '獵人之道', '遠行者居所的曦奔中尉需要一個觀眾隨同所有的獵人。這大大助於你去找出她來，$n。她是我們職業的智慧指引者。$B$B遠行者居所在銀月城的南方。', '到永歌森林的遠行者居所找曦奔中尉交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10530 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10530, 'zhTW', '獵人之道', '遠行者居所的晨奔中尉要求一位聽眾與所有的獵人同行。這會有助於你去找出她來，$n。她是我們職業的智慧引導。$B$B遠行者居所就在銀月城的南方。', '與遠行者居所的晨奔中尉談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10531 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10531, 'zhTW', '阿拉希盆地之戰！', '$n，在阿拉希盆地的戰鬥是為了資源和領土而進行的戰鬥。這個地區作戰的關鍵是確保我們軍隊稀有物資和補給的順暢運作。我命令你去攻擊距離我們在阿拉希盆地中的基地最遠的戰略設施。$B$B當農場、礦坑、伐木場或鐵匠舖被敵人佔據時，攻擊這些設施，找到敵人的旗幟然後把它拔掉!$B$B當你奪回這四個點之後再回到我這裡。', '進攻礦坑、伐木場、鐵匠鋪和農場，然後向避難谷地的奧斯萊特元帥覆命。', '', '去阿拉希高地找避難谷地的奧斯萊特元帥。', '突襲礦洞', '突襲伐木場', '突襲鐵匠鋪', '突襲農場', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10532 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10532, 'zhTW', '切斷阿拉索補給線', '阿拉索聯軍正在不惜一切代價進攻阿拉希，並妄圖奪回這個區域。聯盟的各個種族正在全力進軍這塊遙遠的土地，想要將他們的勢力從避難谷地擴張到這裡。我們必須阻止他們，而最好的方式就是奪取他們的資源。$B$B你可以幫助我們，$N。進入阿拉希盆地，那裡遍地都是豐富的礦藏、肥沃的土地和技藝精湛的能工巧匠。佔據並控制你找到的所有基地，贏得戰鬥，然後把你獲得的資源給我拿回來。', '進入阿拉希盆地，獲得一箱阿拉希資源木箱，然後將它交給落錘鎮的亡靈哨兵莫提斯。', '', '去阿拉希高地找東部禁錮法陣的亡靈哨兵莫提斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10533 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10533, 'zhTW', '更多的資源', '', '', '', '去找阿拉希高地的亡靈哨兵莫提斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10534 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10534, 'zhTW', '回家', '一個$r$c……$B$B是的，最近有一個你的軍隊裡的牧師來過這裡，$n。他告訴我該是你回到艾克索達與希德摩斯見面的時候了。他的要求聽起來有急迫的感覺，所以我沒有跟他見面太久。', '艾克索達的希德摩斯要你去見他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10535 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10535, 'zhTW', '阿拉希盆地的資源！', '我們必須依靠我們的士兵進行戰鬥，所有的士兵都會這麼告訴你的。他們還會告訴你，他們正在使用破爛不堪的裝備，饑腸轆轆地開向戰場!$B$B這就是阿拉希盆地顯得非常重要的原因。金屬，武器，食物，木材─所有我們所需要的東西都可以從那裡獲得。$B$B那就是我需要你發揮作用的地方，$n。進入阿拉希盆地，比敵人佔據更多的基地，以此來獲得戰鬥的勝利，然後給我帶回1箱資源來。', '獲得阿拉希盆地戰鬥的勝利，獲取一個阿拉希資源木箱，然後向避難谷地的瑪克里爾中士覆命。', '', '去阿拉希高地找避難谷地的瑪克里爾中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10536 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10536, 'zhTW', '更多的資源', '', '', '', '去找阿拉希高地的瑪克里爾中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10537 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10537, 'zhTW', '羅恩格隆，碎心之弓', '這是一個徵兆，$n。就算死亡，我也無法停止。取回毀滅密碼的一部份是我的命運。有了你的幫忙，我的命運得以完成。$B$B在我們開始這趟旅行前，我必須拿到我的長弓，羅恩格隆。這是碎心家族代代相傳的傳家寶。$B$B我的直覺告訴我有個惡魔從我屍體邊將它偷走了。殺了這裡的惡魔直到找到我的弓。', '影月谷內伊利達瑞崗哨的阿爾托之靈要你去從本地的惡魔手中取回羅恩格隆，碎心之弓。', '', '去影月谷的伊利達雷崗哨找阿托爾的靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10538 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10538, 'zhTW', '沸騰的血', '最後的實驗並非完全沒有用 - 我有保存一點你帶給我的鮮血。現在煮沸後，它應該已擺脫了血之谷巫者加諸於其人民血液中的詛咒。$B$B我需要更多來研究。去薩斯葛爾的獸人身上收集血之谷鮮血。等你收集好血液，把它帶到他們受詛咒的鍋爐去煮沸它。將沸騰的血帶回來給我。', '在詛咒熔爐使用血之谷鮮血來製造沸騰的血。帶12份沸騰的血給斷脊氏族崗哨的藥劑師艾柏瑞克。', '', '去地獄火半島找斷脊氏族崗哨的藥劑師阿爾布雷克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10539 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10539, 'zhTW', '回家', '一個$r$c……$B$B是的，最近有一個你的軍隊裡的牧師來過這裡，$n。他告訴我該是你回到艾克索達與希德摩斯見面的時候了。他的要求聽起來有急迫的感覺，所以我沒有跟他見面太久。', '艾克索達的希德摩斯要你去見他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10540 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10540, 'zhTW', '毀滅密碼 - 阿爾托的命令', '終於，我們準備好了。我將把我的一部份靈魂贈與你，英雄。它將會守護你並幫助你對抗邪惡。$B$B你接著必須往這裡的南方朝著伊利達瑞崗哨的後方前進。藏在之後的是一個邪惡的生物叫做多數的威納拉圖斯。我的幽魂獵手會在他靠近時將他引出來。$B$B殺掉維納迪並從他的屍體取得毀滅密碼第二部。', '影月谷中伊利達瑞崗哨的阿爾托之靈要你從多數的威納拉圖斯邊取回毀滅密碼第二部。遭受幽魂獵手攻擊或傷害的生物將無法掉落戰利品或經驗值。', '', '去找蠻錘要塞的阿托爾的靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10541, 'zhTW', '毀滅密碼 - 取回第二部', '感謝你，英雄。假如沒有你，我的靈魂會永遠的困在這個可恨的地方。$B$B<阿爾托交給你一個鬼靈之箱。>$B$B把它拿給我父親，他在東北方遠處的田裡，考斯卡水池的上方……帶鎖箱裡裝的是羅恩格隆還有密碼的第二部。$B$B他要是聽到了我的死訊一定會很傷心。答應我你一定要讓我的父親知道我的靈魂已經安息了無牽掛。請告訴他我看到的打獵場非常的壯觀。告訴他我會在那邊等他……', '將阿爾托的上鎖帶鎖箱交給影月谷裡歐朗諾克的農場的歐朗諾克·碎心。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10542 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10542, 'zhTW', '他們偷走我的水煙筒和酒!', '提洽里曾經是一個非常友善的食人妖。我來這裡是為了?血槌氏族如何釀造酒。但是如果我這樣做，血槌氏族會埋了提洽里然後讓他的屍體放在這裡腐爛!$B$B最不好的事情是他們偷走了我的水煙筒!$B$B那麼，你想要幫助提洽里嗎?你幫我找回我的水煙筒。提洽里認為偷走它的巨魔往西南方礦坑的礦坑方向去了。$B$B還有當你到那邊的時候，順便撿一些酒!', '取得提洽里的水煙筒還有10份血槌蠻禁烈酒。帶到劍刃山脈交給血槌深谷的巫醫提洽里。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10543 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10543, 'zhTW', '葛瑞諾克和柯爾卡赫，我為你們而來!', '提洽里一直在等待著他復仇的時刻!$B$B他們活埋提洽里讓他自生自滅的那天，就是由葛瑞諾克·巴拓伯恩領導。隔天劍刃氏族的柯爾卡赫到南方發動攻擊的時候踢到提洽里的頭。$B$B我要他們死光光!$B$B你可以在血槌前哨站的南槌哨塔頂端找到葛瑞諾克。柯爾卡赫則在劍刃要塞最北邊的一棟建築物的頂端。柯爾卡赫的身邊有清醒的防衛者，所以你要使用這瓶酒來引誘他離開他們。', '巫醫提洽里要你殺死最令他痛苦的人，葛瑞諾克·巴拓伯恩還有柯爾卡赫。完成後回到劍刃山脈的血槌深谷找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10544 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10544, 'zhTW', '詛咒你們的氏族!', '提洽里要向所有的巨魔復仇!$B$B提洽里在世的時候曾經是一個法力強大的巫醫。假如你去我的墳墓就可以找到邪惡重型神像。$B$B將神像的魔力灌注在劍刃要塞還有血槌前哨站的建築物以及塔的門口。你對他們下的巫毒將會召喚出一個邪惡的靈魂而你必須擊敗它。如此你就可以詛咒他們的建築物。$B$B但是要注意，假如你嘗試去詛咒一個已經被詛咒的建築物，你將會喚出另一個詛咒的靈魂!', '使用邪惡重型神像詛咒5個在劍刃要塞的建築物或者高塔以及血槌前哨站的2個建築物或者高塔。任務完成時回到劍刃山脈的血槌深谷找巫醫提洽里。', '', '', '已詛咒劍刃要塞建築物', '已詛咒血槌前哨站建築物', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10545 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10545, 'zhTW', '劍刃氏族的喝酒大會', '正如提洽里所說，他幫他的血槌朋友釀造酒。但是他卻沒說背後的原因。$B$B血槌氏族正在面對可怕的困境。劍刃氏族快打垮他們了，而他們需要新的武器來幫助戰鬥。$B$B這個時候提洽里想出了一個很棒的方法。為什麼不釀造一種完美的酒，使這種酒可以提高你們的力量同時又削弱敵人的戰鬥力呢?只不過，提洽里不知道這個方法是否能成功。$B$B所以，你必須把這種酒帶到劍刃要塞看它是否有效用!', '提洽里要你使用血槌蠻禁烈酒讓5個劍刃巨魔喝醉。任務完成後回到劍刃山脈的血槌深谷找巫醫提洽里。', '', '', '劍刃巨魔已喝醉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10546 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10546, 'zhTW', '柏爾拉克, 歐朗諾克之子', '當阿爾托去狩獵而葛洛姆特去打仗的時候，柏爾拉克則在研究他的魔法。後來他到德拉諾的戶外展開了他學者研究勘查的生涯。幾年前他變成一個全新的半獸人回家了。$B$B他增強的感知力還有敏銳的心智已經策劃了一件不為人知的秘密行動。$B$B已經成為一個自信又強大的半獸人的他，計畫奪回保衛最森嚴的一部密碼。$B$B找到柏爾拉克在日蝕崗哨的藏身處，就在南方的遠處。他躲在橋下的暗處監視著血精靈的行動。', '到影月谷的日蝕崗哨附近尋找柏爾拉克, 歐朗諾克之子。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10547 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10547, 'zhTW', '血薊與蛋', '要不是當初我發現他是一個……對血薊上癮的人，我就會放棄了。我ㄧ開始沒有想到但是種種跡象都顯示……$B$B假如現在我們可以找到一些血薊，我們就可以開工了。$B$B我曾經在旅途中遇到一個在撒塔斯城作見不得人生意的破碎者圖比亞斯。$B$B圖比亞斯的生意模式是賣血薊給血精靈以換取腐爛的阿拉卡蛋。$B$B這裡的正西邊有幾座阿拉卡廢墟。在廢墟中找到腐爛的阿拉卡蛋然後到撒塔斯城的陰鬱城。你可以在那邊找到圖比亞斯。', '在日蝕崗哨北邊橋上的柏爾拉克, 歐朗諾克之子要你找到腐爛的阿拉卡蛋然後交給泰洛卡森林西北邊撒塔斯城的『骯髒暴食者』圖比亞斯。', '', '去泰羅卡森林找撒塔斯城的暴食者托比亞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10548, 'zhTW', '悲傷的事實', '還記得我跟你說過那個在尋找戒指的胖商人嗎?結果是，他派他的考古學家兒子去尋找戒指但是進行的不太順利。我說的不太順利是指他們殺了他兒子然後縮小了他兒子的頭顱。$B$B我這麼說可能會讓你覺得我沒人性、心機重而且非常的冷酷無情，但是他願意付大筆的金錢取回他兒子的頭顱。聽起來你是最適合的人選!$B$B往東邊前進直到你遇到食人妖廢墟札布泰拉還有札布諾瓦。你一定會在其中的一個箱子找到你要的頭顱。', '安寧地的依蘭兒要你從札布泰拉還有札布諾瓦其中的一個箱子取得考古學家的皺縮頭顱。', '', '去鬼魂之地找塔奎林的艾拉蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10549 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10549, 'zhTW', 'REUSE', '還記得我跟你提過的那個尋找指環的胖商人嗎？這位商人派他那醉心於考古學的兒子外出尋找古物，可惜此行不順。我的意思是，他掛了，被巨魔砍下了腦袋。$B$B雖然這樣說顯得冷酷無情，不過這位父親願意出重金取回他兒子的腦袋。這項任務派你去再適合不過了！$B$B轉至東邊的巨魔廢墟塞布提拉和塞布努瓦，頭顱應該就在某個營地的某個箱子裡。', '塔奎林的依蘭兒要你從札布泰拉還有札布諾瓦其中的一個箱子取得考古學家的皺縮頭顱。', '', '去鬼魂之地找安達洛斯的艾拉蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10550 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10550, 'zhTW', '一捆血薊', '我沒有說謊。那個蛋真是太棒了。你從哪邊拿來的?嗯，假如你需要更多的血薊，你知道我在哪裡以及我需要什麼。$B$B這是一捆血薊。把它拿去給你的指使人吧。', '將一捆血薊交給影月谷的日蝕崗哨附近橋上的柏爾拉克, 歐朗諾克之子。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10551 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10551, 'zhTW', '向奧多爾效忠', '', '你確定已經做好決定了嗎，$n?奧多爾將會歡迎你加入同盟，但是占卜者將不會原諒你的這個決定。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10552 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10552, 'zhTW', '向占卜者效忠', '', '你確定已經做好決定了嗎，$n?占卜者將會歡迎你加入同盟，但是奧多爾將不會原諒你的這個決定。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10553 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10553, 'zhTW', '『先知』沃藍索', '既然你已經選擇了占卜者，$n，你應該去見占卜者的領導者。$B$B你可以在占卜者階梯的『先知』書庫找到『先知』沃藍索。$B$B看你是否可以幫上他的忙。他會很高興的知道你決定幫助占卜者。', '去跟撒塔斯城占卜者區的『先知』書庫裡頭的『先知』沃藍索談話。為占卜者完成任務會使你的奧多爾聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10554 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10554, 'zhTW', '伊莎納', '既然你已經選擇了奧多爾，你最好還是去跟他們的領導者打聲招呼。你可以在永恆聖光神殿找到高階女祭司伊莎納。', '跟永恆聖光神殿裡面的伊莎納談話，位在奧多爾高地的撒塔斯城。為奧多爾完成任務會使你的占卜者聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10555 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10555, 'zhTW', '莫名的不安', '拉斯汗阿拉卡所研究的法術是很邪惡的。他們一手抓滿-還是應該說一爪?-自己身上的羽毛當做施法材料!$B$B我並不覺得那是一種善良的法術。我來這邊是為了研究他們的法術，可惜我無法接近他們。$B$B你可以這樣做:將他們的法術施放在你自己身上，然後回來找我。你必須找到他們的其中一本法術書，位置就在迷霧拉斯的樹林高處。$B$B除非你自己可以長出羽毛，我看是長不出來啦，你就必須取回他們的一些羽毛。', '收集18根掉落的拉斯汗羽毛，然後在迷霧拉斯的樹梢上閱讀拉斯汗書卷。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10556 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10556, 'zhTW', '達成要求', '書中的圖案文字告訴我們要去迷霧拉斯的魔力法陣使用阿拉卡的羽毛才能施展該法術。$B$B令人困惑的圖案看起來像是一個阿拉卡正在為自己注入卡里瑞的精神力量。', '在拉斯汗的法陣使用一把羽毛，然後在卡里瑞的精神退去之前回去找希爾瓦納的達藍艾歐。', '', '', '讓達藍艾歐分析卡里瑞光環', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10557 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10557, 'zhTW', '測試飛行:ZC號', '我製造了一個很棒的裝置，ZC號，我確定他的功能沒有問題，但是……你願意幫我測試它嗎?$B$B傷殘補助金可是很高的喔!$B$B跟我旁邊的雙胞胎兄弟，瑞利談話。祝你好運，$N。測試完畢後回來找我。或者……假如你因為重大傷殘無法回來找我，你的戰友可以來向我回報取得你的報酬。', '跟瑞利·薩普納伯談話然後使用ZC號。回去托斯利基地找塔利·薩普納伯。', '測試塔莉的實驗', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10558 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10558, 'zhTW', '榮耀堡的崇敬', '你向我們證明了你的能力，$N。像你這樣的人總有一天會成為偉大的領袖。$B$B繼續去攻擊破碎大廳的敵人，為你自己在我們的士兵中贏得榮譽。如果你沒有讓我失望，那我就會交給你更重要的任務。', '地獄火半島榮耀堡的遠征軍指揮官達納斯·托爾貝恩要求你進入地獄火堡壘的破碎大廳對抗邪獸人，直到你在榮耀堡的聲望達到崇敬。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10559, 'zhTW', '索爾瑪的崇敬', '你又再一次的證明了你自己，$c。然而更多的考驗在等著你。$B$B繼續跟那些地獄火堡壘的破碎大廳裡面的魔獄部落戰鬥，你的大名就會流傳在這片大地的索爾瑪追隨者之間。', '在地獄火半島索爾瑪的納茲格雷爾要你跟地獄火堡壘的破碎大廳裡面的魔獄獸人戰鬥以獲得索爾瑪的崇敬。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10560, 'zhTW', '沙塔爾的崇敬', '<阿達爾所發出的平和而寧靜的音律略略轉向低沉與憂鬱。>$B$<你的眼前浮現了一座帶有明顯納魯風格的巨大建築，你知道那是風暴要塞，它現在已經被凱爾薩斯的軍隊佔領了。他們還把那裡的強大力量用於某些極端邪惡的目的。阿達爾承諾，在你為奪回風暴要塞做出應有的貢獻之後，將賦予你更重要的使命。>', '撒塔斯城的阿達爾希望你通過擊敗風暴要塞內的凱爾薩斯的軍隊，在沙塔爾陣營中達到崇敬聲望。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10561, 'zhTW', '時光守望者的崇敬', '你已經向我們證明了你自己，$r。然而，時光線還不安全。$B$B我們在尋找真正的勇者而你已經證明了你的實力。$B$B繼續對付那些時光的侵略者以保衛過去發生的重大事件而你就會得到你應得的崇敬。', '時光之穴的安杜姆要你繼續在時光之穴內守護希爾斯布萊德還有黑色沼澤的重大事件以獲得時光守望者的崇敬。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10562, 'zhTW', '圍困!', '不要鬆懈下來，$r。我們正遭受燃燒軍團不斷的攻擊。$B$B從他們在西南方的基地軍團要塞，那些惡魔們不停的降下一波波的地獄火。我們盡我們所能地殺死他們，但是新的地獄火像隕石般撞擊地面，又是一波新的攻擊。$B$B我的手下已經灰頭土臉還有精疲力盡了。我不知道他們還能撐多久。拜託，$n，幫助我們防禦吧。在戰線上找個位置一起來阻止那些地獄火吧!', '蠻錘要塞外面的空軍指揮官奴艾恩要你殺死10個地獄火攻擊者。', '', '去影月谷找蠻錘要塞的空軍指揮官努埃恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10563, 'zhTW', '前往軍團要塞', '軍團要塞的城堡堅固到幾乎無法攻陷，而且我坦白跟你說，我不能為了一次突擊而分散我的部隊。我們只能指望你了，$n。$B$B從我們收集到的有限資料顯示燃燒軍團在軍團要塞囤積了大量的戰備物資，同時也預備了一些地獄火。你必須帶著我給你的偽裝潛入軍團要塞打聽他們的計畫。你最大的期望是可以攔截或者偷聽他們指揮者之間的軍情交流。祝你好運，$n。', '前進到軍團要塞然後找到軍團傳輸設備。當你靠近傳輸設備的時候，使用你的偽裝然後打聽燃燒軍團的計畫。任務完成時向蠻錘要塞的空軍指揮官奴艾恩回報。', '', '去影月谷找蠻錘要塞的空軍指揮官努埃恩。', '', '', '偷聽燃燒軍團的計劃', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10564, 'zhTW', '引爆地獄火!', '你的裝置並不會讓你贏得什麼選美大賽，但是它應該足以摧毀囤積在軍團要塞的地獄火。從惡魔搶奪者能量核心的能量在惡臭水池所造成的結果來看，它的爆炸將會造成可觀的傷害。$B$B你覺得如果你在要塞的綠紋圈中間引爆裝置，它的範圍應該可以波及到所有的地獄火。', '當你站在軍團要塞的綠紋圈中的時候引爆魔化炸彈。任務完成時，回報給蠻錘要塞的空軍指揮官奴艾恩。', '', '去影月谷找蠻錘要塞的空軍指揮官努埃恩。', '', '摧毀軍團要塞的地獄火', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10565, 'zhTW', '維克尼爾之石', '多年來維克尼爾的阿拉卡一直是我們的眼中釘。他們奉行的是一種奇怪的信仰，指使他們做出瘋狂的行為。他們現在把這種水晶隨身攜帶，使用在不好的地方。$B$B我對他們的儀式有一點了解。他們把水晶拿到他們的法陣將能量注入其中。村裡的人都想了解多一些。伏擊幾個阿拉卡直到你得到水晶為止，將水晶灌滿能量，然後交還給我。', '收集一個維克尼爾水晶並且在維克尼爾的法力之環使用它，然後把充能維克尼爾水晶交給摩克納薩爾村的德托克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10566, 'zhTW', '錯誤的試驗', '我已經打造了四根魔杖，我相信可以加強阿拉卡的水晶力量。將這些魔杖帶到索格瑪領土，然後使用在巨魔奴隸身上。$B$B你必須從該區的阿拉卡身上取得注入能量的水晶。$B$B當你測試出來哪一根魔杖是最好的，回來找我。', '對一個阿拉卡巨魔奴隸測試每一根德托克的魔杖。每一根魔杖都需要消耗一個灌能維克尼爾水晶。', '', '', '測試第一根魔杖', '測試第二根魔杖', '測試第三根魔杖', '測試第四根魔杖', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10567, 'zhTW', '製造墜飾', '魯安曠野的阿拉卡依靠著烏鴉神諭使，他們神祇的信使讓他們聚集在一起。$B$B他們相信那些神諭使從天上看著他們，而他們的神則在天上將教義宣揚給信使們，最後信使們從天上下來傳達神的旨意。$B$B神諭使對阿拉卡的靈魂有著非常強的支配能力。他們使用一種魔法的墜飾正好是我們所需要的。$B$B殺死一些阿拉卡並奪取他們的爪子以引起神諭使的注意。把爪子放在他們的祭壇就可以得到信使的注意。', '在魯安歐克神諭者法陣找到6個魯安歐克之爪來召喚1個烏鴉神諭使。殺死它然後將神諭使墜飾交給魯安曠野的泰姆昂。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10568 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10568, 'zhTW', '巴瑞碑文', '許多年前，可怕的獸人術士古爾丹在影月谷的中央地帶引發了火山爆發。西南方的德萊尼村莊巴瑞還有當地的居民以及一些重要的宗教藝品因此而被熔岩給掩埋了。$B$B那個被人稱為灰舌的奸詐破碎者部族已經接獲伊利丹的命令去挖掘該區了。我們必須利用這個機會奪回巴瑞碑文，據說上面記載著卡拉伯爾神廟的秘密，也就是現在的黑暗神廟。', '薩塔祭壇的隱士希拉要你去巴瑞廢墟從地上或者灰舌勞工的身上收集12個巴瑞碑文。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去影月谷找沙塔爾祭壇的學者希拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10569 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10569, 'zhTW', '史凱瑟隆殘骸', '我們的斥候從阿拉卡的廢棄營地帶回來了令人困擾的報告。$B$B那些法力強大的阿拉卡法師的鬼魂使用著我們從來不知道他們擁有的法術力量。他們似乎正在組織化，好像為了什麼而在作準備，但是我們卻無法得知。我們不能維持如此的無知!$B$B到北邊的史凱瑟隆殘骸，死亡熔爐的西北邊然後尋找他們的動機。', '自史凱瑟隆殘骸的黑暗議會阿拉卡身上取回史凱瑟隆指揮官日誌 - 第一頁，史凱瑟隆指揮官日誌 - 第二頁，和史凱瑟隆指揮官日誌 - 第三頁交給獅鷲騎士凱蘭。', '', '去影月谷找蠻錘要塞的獅鷲騎士基爾蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10570 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10570, 'zhTW', '血薊花的陷阱', '<柏爾拉克從你的身上拿走了一束血薊並且放在鼻子前面嗅了一下。>$B$B有點刺鼻……$B$B現在你拿著這束血薊然後把它放在這座橋的另一端。當那個使者經過他每天例行的路線的時候，他會無法克制的想把那束血薊撿起來-他會支開他的保鏢的。我告訴你，血精靈看不起那些沉溺於血薊而上癮的人。如果他被他的同袍們發現……$B$B所以你所需要做的就是等他支開他的保鏢。當他落單的時候，突擊他!殺了他然後取回信件。', '影月谷的日蝕崗哨附近橋上的柏爾拉克, 歐朗諾克之子要你取回怒風信件。', '', '去找影月谷的伯拉克，歐魯諾克之子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10571 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10571, 'zhTW', '長者奧朗奴', '根據石板上的記載，有一個被稱為卡拉伯爾勳章的神器被收藏在巴瑞。只有德萊尼的最高階祭司會被贈與此物，因為它可以讓使用者自由的進入卡拉伯爾神廟。$B$B我們必須想辦法得知灰舌奪回勳章了沒。它的力量會對我們跟伊利丹的戰鬥提供很大的幫助。$B$B阿卡瑪每天都會傳遞手寫的命令給在巴瑞的副官，長者奧朗奴。把那些信件取回來並且交給我。', '薩塔祭壇的隱士希拉要你取回位在巴瑞廢墟的長者奧朗奴身上的阿卡瑪的命令。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去影月谷找沙塔爾祭壇的學者希拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10572 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10572, 'zhTW', '製作炸彈', '我們不能允許燃燒軍團進行他們進軍黑暗神廟摧毀蠻錘要塞的計畫。$B$B只有一個辦法可以阻止他們，$n。你必須製造一場爆炸，大到足以摧毀燃燒軍團在軍團要塞所囤積的所有地獄火。$B$B在靠近軍團要塞的惡臭水池那邊你可以使用老舊的惡魔搶奪者能量核心來當作你製作爆裂物的材料。在惡魔搶奪者附近搜索其他殘骸尋找我們可能用來製作外罩的鎧甲。', '取得一個惡魔搶奪者能量核心，一個惡魔搶奪者能量母體，還有一個惡魔搶奪者鎧甲並將這些東西帶給蠻錘要塞的空軍指揮官奴艾恩。', '', '去影月谷找蠻錘要塞的空軍指揮官努埃恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10573 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10573, 'zhTW', '死亡熔爐', '從你在軍團要塞得到的消息，我們知道燃燒軍團的暗影議會的盟友們正在提供地獄火給死亡熔爐。我已經派出了一支小型的偵察部隊監視該區域，但是他們無法提供我們需要知道的消息。$B$B假如死亡熔爐可以獨力運作，他們將可以重建你在軍團要塞摧毀的地獄火堆。$B$B我要你去見天鳴者艾文·野翼，你可以在死亡熔爐哨塔找到他，地點就在死亡熔爐的南邊。', '向死亡熔爐哨塔的天鳴者艾文·野翼回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10574 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10574, 'zhTW', '灰舌墮落者', '阿卡瑪的信中指出，大勳章的四個碎片被挖掘出來的時候送給了灰舌墮落者。這些可怕的破碎者曾經是一個強大的薩滿如今褻瀆了薩滿們所尊敬的元素力量。$B$B風之墮落者，哈盧姆可以在虛空之翼小徑找到。伊肯尼恩還有烏拉魯，大地和火之墮落者最後被人發現的地方是在靠近古爾丹火山的惡魔深淵。拉卡恩，水之墮落者謠傳是在靠近考斯卡崗哨的地方。$B$B找到他們並且取回勳章碎片。', '從哈盧姆，伊肯尼恩，拉卡恩和烏拉魯那邊取回四個勳章碎片然後回到影月谷的薩塔祭壇找隱士希拉。為奧多爾完成任務會使你的占卜者聲望降低。', '', '去影月谷找沙塔爾祭壇的學者希拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10575 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10575, 'zhTW', '典獄官監牢', '你獲得的碎片只是勳章的一半而已。灰舌的領導者阿卡瑪一定擁有另一半。$B$B我不敢這麼要求你，因為阿卡瑪既邪惡又狡猾。$B$B據說他跟灰舌部族裡頭最邪惡最慘忍的傢伙死亡誓言者，在典獄官監牢的某處設置了一間刑房密室。$B$B我要你找出那間可怕的監獄，並且打聽阿卡瑪的下落。破碎者杉諾魯是他們當地的第二指揮官，必要的時候可以拷問他。', '隱士希拉要你去典獄官監牢，它的位置在巴瑞廢墟的南邊並且逼問杉諾魯關於阿卡瑪的下落。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10576 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10576, 'zhTW', '影月谷的潛行', '<柏爾拉克上下打量你。>$B$B這件事有點困難，但是我想我有辦法。$B$B我可以幫你偽裝成這些伊利達瑞血精靈的其中一員，$n。不過，首先我需要幾件他們的護甲。重要的是護甲必須是乾淨的。上面不可以沾有血跡!我們要避免被懷疑。$B$B把護甲拿給我然後我會負責其他部分的偽裝。$B$B一旦穿上偽裝，你將傳遞訊息給大指揮官 - 親自的。', '位在影月谷靠近日蝕崗哨一座橋上的柏爾拉克, 歐朗諾克之子要你找回6件日蝕護甲。', '', '去找影月谷的伯拉克，歐魯諾克之子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10577 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10577, 'zhTW', '予取予求的伊利丹……', '帶著這個偽裝潛入日蝕崗哨。一旦你成功潛入以後，用這個偽裝來隱藏你自己。這些日蝕血精靈沒有辦法看穿你的偽裝，你可以藉此安全的找到大指揮官魯斯克。$B$B一旦你找到魯斯克，告訴他密件的處理去向。這個行動會嚇破你的膽子，$n。你就假裝你是他的上司，傳遞上頭的訊息給他。你應該辦的到。$B$B喔-小心龍鷹可是會看穿你的偽裝呢。', '位在影月谷靠近日蝕崗哨的一座橋上的柏爾拉克, 歐朗諾克之子要你傳遞伊利丹的一段訊息給日蝕崗哨的大指揮官魯斯克。', '傳達伊利丹的口信', '去找影月谷的伯拉克，歐魯諾克之子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10578 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10578, 'zhTW', '毀滅密碼 - 柏爾拉克的命令', '那個密碼碎片永遠不會到達祖魯希德的手上。你必須在『晦暗者』魯歐運送的時候偷襲他，你不能給他任何機會完成他的運送。$B$B龍喉堡壘就在正東方，當你穿過虛空之翼農場就會看到。你會在龍喉堡壘和星光聖所之間的某處找到魯歐。用你最快最大的力量去偷襲他。但是，$n，我有聽說過，這個魯歐可是很強悍的。保持你的警戒心。$B$B當你成功之後把密碼交還給我。', '影月谷的日蝕崗哨附近橋上的柏爾拉克, 歐朗諾克之子要你從『晦暗者』魯歐身上奪回毀滅密碼第三部。這個任務將會需要組隊來完成。', '', '去找影月谷的伯拉克，歐魯諾克之子。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10579 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10579, 'zhTW', '毀滅密碼 - 取回第三部', '將這個箱子交給我父親。他仍然居住在歐朗諾克的農場，在遙遠的北邊，考斯卡水池的上方。當三個碎片重新結合以後，古老的文字就會再次浮現。$B$B祝你好運，$n。轉告我父親再過不久我就會回家了。', '帶著柏爾拉克的帶鎖箱到影月谷的歐朗諾克的農場交給歐朗諾克·碎心。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10580 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10580, 'zhTW', '這些該死的地精跑去哪裡了?', '儘管我們在這裡的工作已完成，但是有件事讓我覺得很抱歉:我們迫使托斯利還有他的地精朋友們離開了。我們沒有選擇;他們的工程技術還有科學實驗在小樹林裡把我們過去所做的努力弄的一團糟。假如你願意幫我去看看他們後來的情況我會很感激。他們最後的消息是往東方過橋而行。我確定他們後來一定是轉往南方了，遠離雷霆王村。到南方的鋸齒山脊尋找他們移動的線索。', '指揮官天影要求你去劍刃山脈南邊的鋸齒山脊尋找托斯利還有其他地精去向的線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10581, 'zhTW', '跟著痕跡走', '很好，我是來警告你在山脊上不會找到任何東西。千萬不要跟著散落地上的備用零件痕跡走，那會通到托斯利基地的!你不會在那邊找到托斯利還有其他地精的。', '講了一圈，原來R-3D0型機器人已經告訴你跟著散落地面的零件痕跡上斜坡到剃刀山脊，你就會發現地精們在一個叫做托斯利基地的地方。假如你找的到托斯利的話，跟他談談吧。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10582 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10582, 'zhTW', '暗影議會的爪牙', '<艾文聆聽你描述軍團要塞的事件，一面聽一面點著他的頭。>$B$B這使我們對未來的評估可以更透徹。我們已經偵察到他們朝要塞的方向運送地獄火，但是除此之外一無所獲。$B$B暗影議會把死亡熔爐守的比一桶未開罐的雷酒桶還緊。你現在首先要做的事情就是多殺幾個敵人才能混進去然後四處刺探看看。開始清除暗影議會把守通往死亡熔爐的通路!', '死亡熔爐哨塔的天鳴者艾文·野翼要你去殺10個死亡熔爐守護者還有5個靈魂行者。', '', '去影月谷找死亡熔爐哨塔的伊萬·蠻翼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10583 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10583, 'zhTW', '弗藍尼斯的命運', '空軍指揮官奴艾恩原先派我們到這裡來是為了監視死亡熔爐並且刺探軍情。弗藍尼斯·迅翼自願嘗試滲透進去死亡熔爐，但是我們已經好多天都失去了他的消息。$B$B我怕最壞的事情會發生在他身上，$n。弗藍尼斯雖然是一個技巧熟練的斥候，但是假如他遇上無法應付的局面時，我們卻不可能知情。在死亡熔爐搜索他或者他可能蒐集到的資訊或物品。', '死亡熔爐哨塔的天鳴者艾文·野翼要你去死亡熔爐搜索弗藍尼斯·迅翼並且找回弗藍尼斯的包包。', '', '去影月谷找死亡熔爐哨塔的伊萬·蠻翼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10584 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10584, 'zhTW', '收集能量轉換器', '北邊劍刃崗哨那些愚笨的巨魔一直在襲擊我們的能量轉換器!你要為我把它們追回來，可以這麼說。$B$B毫無疑問的，巨魔巨大、笨拙的手毀壞了轉換器。所以，我要你做的就是從他們那裡釋放能量並在組合的電流體上使用這個原始電磁集電器來裝住它。$B$B你可能會感覺有點疼痛，所以在它被裝在磁力發電機球體裡時你需要「殺掉」它。', '托斯利要你帶著原始電磁集電器去收集5個電流體。任務完成時回去劍刃山脈的托斯利基地找托斯利。', '', '', '收集電流體', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10585 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10585, 'zhTW', '召喚密室', '暗影議會為了要快速生產地獄火以彌補它的使用量，他們必定有一個地區專門用來召喚墮落的元素，這些元素是用來當作地獄火的靈魂。$B$B他們用來召喚的密室很可能在地底下，靠近污濁的水池或者熔岩池。找到位在死亡熔爐的召喚密室，並且找到方法終止他們的召喚儀式。參與製作地獄火的莫阿格有可能攜帶可以中斷召喚者施法的工具。', '從死亡熔爐鐵匠或者死亡熔爐技工身上獲得一個元素替換器並且使用它來中斷召喚密室中的儀式。任務完成後回報給死亡熔爐哨塔的天鳴者艾文·野翼。', '', '去影月谷找死亡熔爐哨塔的伊萬·蠻翼。', '終止地獄火召喚儀式', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10586 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10586, 'zhTW', '擊敗戰爭使者！', '我們在死亡熔爐對抗暗影議會的行動已經有了很大的進展，但是假如我們想要真正的勝利，我們必須打敗燃燒軍團在那邊的監督者。$B$B我在弗藍尼斯的包包裡頭的物品中找到了一個鑰匙。我相信它將可以幫助你追蹤到你在軍團要塞偵察到的戰爭使者瑞術恩。$B$B在你追蹤並且解決掉戰爭使者瑞術恩之後，直接去跟空軍指揮官奴艾恩回報吧。他可是急著想聽到這個消息呢!', '擊敗戰爭使者瑞術恩，取回瑞術恩的指令，然後回報給蠻錘要塞的空軍指揮官奴艾恩。', '', '去影月谷找蠻錘要塞的空軍指揮官努埃恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10587 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10587, 'zhTW', '卡拉伯爾訓練場', '我們的斥候回報發現了一大群日怒血精靈軍隊正朝卡拉伯爾廢墟行進中。通常這種情形只會代表著一種軍事威脅，不過我們仍然覺得事情有點不對勁。$B$B根據斥候回報的描述，他們的穿著還有作戰方式都很像伊利丹本人。我不希望為了不正確的揣測而提高警戒，所以我希望你去幫我取回一些他們的武器。然後我們就可以知道我的揣測是否正確了。', '薩塔祭壇的主教歐納拉要你從薩塔祭壇東南方卡拉伯爾廢墟裡，從惡魔獵人懇求者和惡魔獵人見習生的身上奪回8把日怒大刀。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去影月谷找沙塔爾祭壇的大主教歐納拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10588 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10588, 'zhTW', '毀滅密碼', '在我們的世界歷史中，這個法術被使用過了幾次呢?毫無疑問的，它的破壞威力是無與倫比的。$B$B你現在必須拿著這個密碼(現在已經完成了)並且在詛咒祭壇 - 就是在古爾丹的回憶佇立的地方，唸出上面的文字。$B$B一旦你開始讀密碼的時候，你就會看見這段銘記於大地的回憶。留在原地等著迎接賽洛庫的到來。$B$B你一定要獲得勝利，$n。我們的大地已經無法再承受額外的打擊了。', '在詛咒祭壇使用毀滅密碼，召喚『火焰之王』賽洛庫。殺死火焰之王賽洛庫然後去跟大地治癒者托爾洛克談話，你同樣可以在詛咒祭壇找到他。', '', '去影月谷找詛咒祭壇的大地治癒者託洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10589 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10589, 'zhTW', '進入的方法', '根據瑞術恩的指令，地獄火大量聚集的地點叫做侵略點:災難，而且這個地點隱蔽在北邊的山區裡。想到達那邊的唯一方法是使用軍團要塞裡頭的一個傳送器。$B$B燃燒軍團的軍隊之中有特定的人員會攜帶可以啟動傳送器的儀器。你必須搶回一些這種儀器才能啟動傳送器。假如有需要你就殺光那邊的惡魔也沒關係，但是你不准給我空手回來。', '將軍團傳送門控制器交給蠻錘要塞的空軍指揮官奴艾恩。軍團要塞的莫阿格武器鐵匠都會攜帶這種儀器。', '', '去影月谷找蠻錘要塞的空軍指揮官努埃恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10590 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10590, 'zhTW', '復仇的證明', '是時候讓你記得不該被遺忘的歷史了……屠殺我們族人的阿薩斯和他的天譴軍團。$B$B向天譴軍團復仇是減輕你痛苦的唯一辦法。很不幸他們對恐懼和痛苦沒太大的感覺。只有他們徹底的毀滅才能為你帶來一點快樂。$B$B和銀色黎明軍官加魯什談談，了解天譴石和如何取得它們的知識 - 在我們再次交談前我要看到很多以做為你承諾的證據。', '瑪拉·曦刃要你幫他帶回20個爪牙的天譴石。', '', '去找提里斯法林地的麥拉·黎明之刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10591 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10591, 'zhTW', 'DESTROY THIS QUEST！', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10592 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10592, 'zhTW', '女妖之王的智慧', '天譴石離開擁有它們的骷髏之握時就會變的很脆弱。單單把它們握在我的手裡就讓它們碎裂了。$B$B<瑪拉把天譴石捏成一堆小碎石。>$B$B帶著這些碎片去找女妖之王，希瓦娜斯·風行者，她在幽暗城的王座裡。她知道如何將這些殘餘物變成對抗天譴軍團的武器。', '將天譴石碎片交給幽暗城的希瓦娜斯·風行者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10593 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10593, 'zhTW', '古老的禍害', '這些石頭提醒著我不想記住的汙點，但卻也是我無法忘記的。當你把這些石頭帶來給我的時候就是在考驗我的耐性。$B$B不過，很明顯的你的內心渴望和我同樣的復仇，所以我會幫你完成這個目標。$B$B去探索位在悲傷沼澤的阿塔萊神廟深處吧。你必須解開它的秘密釋放古老的禍害，摧毀它並把它身體的一部份帶回來給瑪拉·曦刃。我的守衛會將天譴石碎片交給瑪拉。', '解開阿塔萊神廟的秘密釋放阿塔拉利恩，並且從他的肉體取回腐爛的藤蔓。當你已經完成時，返回亡靈壁壘的米哈爾那裡。', '', '去找提里斯法林地的麥拉·黎明之刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10594, 'zhTW', '測量共振的頻率', '帶著這些掃描器到美聲山脊。當你依照地上的位置裝設它們，你會創造出彼此相疊的掃描區域來讀取水晶的振幅。但是你必須站在五個震動區域的交錯點，這樣一來我才能獲的我所需要的資料。$B$B你的掃描器同時也會與其他人放置的掃描器產生共鳴。$B$B喔對了，在過程中將會產生一個裂縫!我完全不知道會跑出什麼東西來。', '地鐵地精尼克偉恩寇要你以下列的方式來安裝震盪頻率掃瞄器。你必須在安裝完畢時同時處在五個震盪區域之中。$B$B完成之後，回到劍刃山脈的托斯利基地向地鐵地精尼克偉恩回報。', '已測量鳴唱水晶的共振頻率', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10595 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10595, 'zhTW', '圍困!', '<高莫克望著天空。>$B$B我們的斥候部隊已經展開了一場激戰，但是地獄火還是一直不斷的轟過來!$B$B來自他們位於西南方的軍團要塞基地，那些惡魔們根本是毫髮無傷的一直轟炸我們!就連柯爾克隆精英守衛也無法永久的阻擋他們。$B$B我正在佈置戰局讓所有的$r都可以盡他們的責任共同防禦影月村。這可不是一場遊戲，$c。影月村的生死存亡正在危急關頭。盡你身為部落一份子的責任，投入我們戰力薄弱的地方共同作戰吧!', '影月村外面的血衛士高莫克要你去殺10個地獄火攻擊者。', '', '去影月谷找影月村的血衛士古爾穆克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10596 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10596, 'zhTW', '前往軍團要塞', '軍團要塞的城堡是你的目標。沒有人會去支援你，所以正面交鋒你想都不用想。$B$B從我們蒐集到的少數情報顯示，燃燒軍團在要塞裡頭囤積準備了大量的地獄火。我將給你一個偽裝，你就可以潛入軍團要塞並且發現他們的計畫。$B$B你的最大期望是可以攔截或者偷聽他們指揮者之間的軍情交流。', '去軍團要塞，找到軍團傳輸設備，然後在偽裝的狀態下打聽燃燒軍團的計畫。任務完成後向影月村的血衛士高莫克回報。', '', '去影月谷找影月村的血衛士古爾穆克。', '', '', '偷聽燃燒軍團的計劃', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10597, 'zhTW', '製作炸彈', '我們可不能讓燃燒軍團進軍黑暗神廟的腳步給踩傷了。$B$B想辦法摧毀那些燃燒軍團準備用來對付我們的地獄火。這可不是請求，$n;這是命令。$B$B靠近軍團要塞的惡臭水池保存了舊的惡魔搶奪者能量核心，你可以把它當作某種魔化炸彈的基礎材料。在要塞附近搜索另一個殘骸，尋找一個能量母體還有一個鎧甲。你應該可以利用這些東西組成一個炸彈，威力足以摧毀所有的地獄火，同時還可以讓軍團要塞好好的感受一下地動山搖的滋味!', '取得惡魔搶奪者能量核心，惡魔搶奪者能量母體還有惡魔搶奪者鎧甲，把它們帶給影月村的血衛士高莫克。', '', '去影月谷找影月村的血衛士古爾穆克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10598 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10598, 'zhTW', '引爆地獄火!', '你的裝置並不會讓你贏得什麼選美大賽，但是它應該足以摧毀囤積在軍團要塞的地獄火。從惡魔搶奪者能量核心的能量在惡臭水池所造成的結果來看，它的爆炸將會造成可觀的傷害。$B$B你覺得如果你在要塞的綠紋圈中間引爆裝置，它的範圍應該可以波及到所有的地獄火。', '當你站在軍團要塞的綠紋圈上面的時候引爆魔化炸彈。當你完成任務，回報給影月村的血衛士高莫克。', '', '去影月谷找影月村的血衛士古爾穆克。', '', '摧毀軍團要塞的地獄火', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10599 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10599, 'zhTW', '死亡熔爐', '當你在軍團要塞解決那些地獄火的時候，我在重新思考你作的報告。我們沒有理由相信燃燒軍團會對死亡熔爐的情況撒謊。他們真的在那邊加速地獄火的生產速度，所以我已經派出一支偵察隊去監視死亡熔爐。$B$B假如我們無法讓死亡熔爐停工的話，他們會重建你在軍團要塞所摧毀的地獄火堆。$B$B你去跟一個叫做爐熔守望的塔裡跟斥候薩葛蘭回報，它的位置就在死亡熔爐的北方。', '向爐熔守望的斥候薩葛蘭回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10600 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10600, 'zhTW', '暗影議會的爪牙', '<薩葛蘭一邊點頭一邊聽你訴說在軍團要塞發生的事件。>$B$B你的描述彌補了我們資訊不足之處。我們曾經偷偷見到他們往要塞的方向運送地獄火，但是再也打聽不到其他的消息。$B$B暗影議會幾乎把整個死亡熔爐給層層封鎖住了。看來你必須要殺出一條血路才進的去。開始清除由暗影議會所把守通往死亡熔爐的通道吧!', '爐熔守望的斥候薩葛蘭要你去殺10個死亡熔爐守護者還有5個靈魂行者。', '', '去影月谷找熔渣哨塔的斥候薩格蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10601 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10601, 'zhTW', '凱格羅西的命運', '他們的偵察隊通常有三個成員。可惜，凱格羅西想要逞英雄。$B$B他潛入了死亡熔爐而從此之後我們就沒再聽過他的消息了。$B$B很可能，那個笨蛋已經去送死了。暗影議會的成員可不是白痴，凱格羅西的實力敏銳度不算很強，你了解我說的話吧。試著去死亡熔爐尋找他或者找回他可能蒐集到的軍情或者物品。', '爐熔守望的斥候薩葛蘭要你去死亡熔爐尋找凱格羅西還有凱格羅西的背包。', '', '去影月谷找熔渣哨塔的斥候薩格蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10602, 'zhTW', '召喚密室', '看起來死亡熔爐為了想快速的大量生產地獄火，他們必定有一個專門召喚元素的地區，這些元素是用來當作地獄火的核心。$B$B他們用來召喚的密室應該在地底下，靠近一個污濁的水池或者熔岩池。找到在死亡熔爐裡頭的召喚密室，並且找到ㄧ個方式終止他們的召喚儀式。參與製作地獄火的莫阿格都有可能攜帶可以幫助你中斷召喚者施法的工具。', '從死亡熔爐鐵匠或者死亡熔爐技工身上取得一個元素替換器，並且使用它來中斷召喚密室中的儀式。任務完成時，回報爐熔守望的斥候薩葛蘭。', '', '去影月谷找熔渣哨塔的斥候薩格蘭。', '終止地獄火召喚儀式', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10603, 'zhTW', '擊敗戰爭使者！', '我們在死亡熔爐對抗暗影議會的行動進展良好，但是現在該是我們解決他們的時候了。$B$B我在凱格羅西的背包裡頭的物品裡找到一把鑰匙。至少在他們殺了凱格羅西之前他完成了某項使命。$B$B這把鑰匙可以幫助你追蹤你在軍團要塞偵察到的戰爭使者瑞術恩。$B$B在你找到並且解決了戰爭使者瑞術恩之後，直接去向血衛士高莫克回報吧。我們不能讓他等太久。', '擊敗戰爭使者瑞術恩，奪回瑞術恩的指令，然後向影月村的血衛士高莫克回報。', '', '去影月谷找影月村的血衛士古爾穆克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10604, 'zhTW', '進入的方法', '根據瑞術恩的指令，地獄火大量聚集的地點叫做侵略點:災難，而且這個地點就在我們村子的後方山區裡!想到達那邊的唯一方法是使用軍團要塞裡頭的一個傳送器。$B$B燃燒軍團的軍隊之中有特定的人員會攜帶可以啟動傳送器的儀器。你必須搶回一些這種儀器才能啟動傳送器。假如有需要你就殺光那邊的惡魔也沒關係，但是你不准給我空手回來。不要耽擱時間;敵人已經非常靠近我們了。', '將軍團傳送門控制器交給影月村的血衛士高莫克。在軍團要塞的莫阿格武器鐵匠都會攜帶這種儀器。', '', '去影月谷找影月村的血衛士古爾穆克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10605, 'zhTW', '凱倫丁的召喚', '你的臉上有種渴望學習的表情，$n。也許是時候可以加強你的訓練了。$B$B去跟幽暗城的凱倫丁·哈加爾談一談吧，這個老傢伙倒還懂得一兩手絕活你將來可能會派上用場。', '跟幽暗城的凱倫丁·哈加爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10606, 'zhTW', '惡魔搶奪者保養技術', '要消滅燃燒軍團剩餘庫存的最好的方法是利用他們的武器來打擊他們。我已經在著手研究一個裝置，讓你可以控制一個下面的惡魔搶奪者哨兵。$B$B但是目前我還剩下幾個難題。為了克服它們，我需要博士嘎崔克鎖在斜坡底部保險箱裡的技術手冊。他大概不會平白無故的把保險箱的鑰匙送給你，所以你必須把它搶回來。只要把惡魔搶奪者的技術手冊交給我，我會搞定剩下的事情。', '殺死博士嘎崔克然後取得博士的鑰匙。使用該鑰匙打開博士的保險箱取得惡魔搶奪者保養技術然後把它交給侵略點:災難的普萊克希。', '', '去影月谷找登陸場：災難的普雷西。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10607, 'zhTW', '烏鴉神的秘密預言', '在葛瑞許納什，烏鴉智者留下的圖騰使得阿拉卡人可以聽見烏鴉的話語。不幸的是，阿拉卡的語言對我們來說太難以解讀。$B$B使用神諭使墜飾就可以讓我們了解他們的語言。你將可以捕捉阿拉卡的靈魂以了解他們的語言。當你身體內充滿著阿拉卡的靈魂時，你可以接近圖騰了解它們想傳達的訊息。$B$B幫助我們了解它們的訊息吧，$n。', '殺死葛瑞納阿拉卡取得理解烏鴉語的效果2分鐘。在法術的效果之下，你可以從四個聖物之中得知四段預言。當你得知四段預言之後就回來找我。', '', '', '獲得第一段預言', '獲得第二段預言', '獲得第三段預言', '獲得第四段預言', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10608, 'zhTW', '清除水晶的障礙', '那些該死的岩石鐮奪怪阻礙了我在美聲山脊所做的研究!當我在挖掘那些歌唱水晶的時候，它們總是跑來破壞我研究那些水晶的美妙旋律。$B$B你看起來像是可以幫我解決這個問題的人。幫我去南邊殺死那些水晶鐮奪怪。', '地鐵地精尼克偉恩寇要你殺死10個水晶鐮奪怪然後回到劍刃山脈的托斯利基地向他回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10609, 'zhTW', '龍生蛋，蛋生龍?', '我在我的醫生領域裡頭研究龍之精華的用途。對於一個生病的人來說，我想它們可能是一種萬靈藥!我需要有人去南邊的美聲山脊幫我取回一些。$B$B你願意帶著我的時光相位轉換器使用在剛從虛空龍蛋孵出來的虛空幼龍嗎?不管它們會變化成什麼，幫我取回精華。$B$B關於這件事，我想補充一下，我並不確定它們變化的結果因為我們所使用的是非常不穩定、改變時間與空間的科技產品。', '收集3個原始虛空龍之精華、3個年輕的虛空龍之精華還有3個成熟的虛空龍之精華。交給劍刃山脈托斯利基地的費茲特「醫生」克羅克塔可。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10610 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10610, 'zhTW', '基本的勘察', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10611, 'zhTW', '惡魔搶奪者保養技術', '要消滅燃燒軍團剩餘庫存的最好的方法是利用他們的武器來打擊他們。我已經在著手研究一個裝置，讓你可以控制一個下面的惡魔搶奪者哨兵。$B$B但是目前我還剩下幾個難題。為了克服它們，我需要博士嘎崔克鎖在斜坡底部保險箱裡的技術手冊。他大概不會平白無故的把保險箱的鑰匙送給你，所以你必須把它搶回來。只要把惡魔搶奪者的技術手冊交給我，我會搞定剩下的事情。', '殺死博士莫歐費卡斯取得博士的鑰匙 。使用鑰匙打開博士的保險箱取得惡魔搶奪者保養技術，然後將這本書交給災難侵佔崗哨的那卡西。', '', '去影月谷找登陸場：災難的納坎斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10612 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10612, 'zhTW', '惡魔與狂熱', '<普萊克希翻閱這本手冊。>$B$B嗯，我們需要的東西都在這裡，但是還有一個問題。惡魔搶奪者原本就不是被設計成可接受遠端遙控。$B$B我們可以修改一台讓你暫時使用，但是你的動作要快，不然後果難測!假如你用惡魔搶奪者做出來的特技表演驚動到燃燒軍團的手下我一點也不驚訝。保持警戒，不管你要怎麼做，別忘了造成的傷害越大越好!', '使用惡魔搶奪者控制平台控制一個惡魔搶奪者哨兵。在你的惡魔搶奪者失效之前摧毀60個死鑄地獄火。任務完成後，向侵略點:災難的普萊克希回報。', '', '去影月谷找登陸場：災難的普雷西。', '摧毀死亡熔爐的地獄火', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10613 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10613, 'zhTW', '惡魔與狂熱', '<那卡西翻閱這本手冊。>$B$B我們需要的資訊都在這裡，但有一件事要注意。這些東西原本就設計成不受遠端控制。$B$B我們可以修改一台讓你暫時使用，但是你的動作要快，不然後果難測!假如你用惡魔搶奪者使出的手段驚動到燃燒軍團的手下我一點也不驚訝。保持警戒，但要記住，首要任務是維護影月村的安全!', '使用惡魔搶奪者控制平台控制一個惡魔搶奪者哨兵。在你的惡魔搶奪者失效之前摧毀60個死鑄地獄火。任務完成後，向侵略點:災難的那卡西回報。', '', '去影月谷找登陸場：災難的納坎斯。', '摧毀死亡熔爐的地獄火', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10614 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10614, 'zhTW', '風中低語', '我已經尋遍外域有關摩克納薩爾的謠言，但沒有任何關於它的蹤跡。最後，我們可能找到他們的家。但是既然現在就在這裡，我心裡卻充滿著不安。在我搜尋的期間，心神不安使我到深夜都無法入睡。他們會接受我嗎?我……知道他們領導人的名字:李歐羅克斯。將他找出來。這次你必須當我的眼睛。', '到劍刃山脈的摩克納薩爾村找到李歐羅克斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10615 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10615, 'zhTW', '魯安曠野', '你幫助我揭示關於這裡阿拉卡本質的情報，將有很多其他人有很大的興趣知道。我們已經被塞納里奧遠征隊的成員拜訪過，那些人也已經變得掛慮阿拉卡在劍刃山脈這裡的意圖。你應該出外尋找他。他的名字是泰姆昂，而你將在魯安曠野的永恆樹林裡找到他。沿著這裡西方的道路走，然後在剃刀山脊分岔處向北走。最後，當路在刀刃峽谷分開時，沿著西邊的道路走。', '與永恆樹林的泰姆昂交談，永恆樹林在劍刃山脈的魯安曠野。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10616 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10616, 'zhTW', '<nyi>Breadcrumb', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10617 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10617, 'zhTW', '絲翼之繭', '絲翼之繭的絲在我們村子有非常多種的用途。我們永遠都不夠用，絲越多越好。$B$B要從幼蟲身上採集繭是很困難的，因為一旦它們開始成長變化繭就被破壞了。$B$B我們的士兵們都忙於應付對村莊的攻擊行動。假如你可以幫我們收集一些它們的繭來，那就太好了。', '摩克納薩爾村的塔爾瑞克要你從絲翼幼蟲身上收集8個絲翼之繭。$B$B在幼蟲成長成絲翼之前殺掉它，不然繭就會被破壞。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10618 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10618, 'zhTW', '最柔軟的翅膀', '捕獵絲翼幼蟲對我們的年輕士兵來說是一項困難的挑戰，但幸運的是，即使他們從幼蟲身上採集繭失敗了，我們仍然可以使用已孵化的絲翼翅膀。$B$B事實上，我們對翅膀的使用量大於繭，而且希望越多越好。$B$B假如你願意幫助我們去外面收集一些翅膀就太好了。', '摩克納薩爾村的希歐瑪納要你收集12個彩虹之翼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10619 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10619, 'zhTW', '灰舌部族', '破碎者們一直都畏懼著灰舌部族。他們其中不乏凶惡又殘忍的成員，全都是由阿卡瑪親手挑選的。他們好鬥殘忍的程度不下於任何一個納迦、惡魔或者伊利丹的血精靈部隊，而他們現在聚集了大批的成員在巴瑞廢墟，就在這裡的西南邊。在他們對我們發動攻擊前去那邊削減他們的成員數目吧。', '復仇者阿魯曼要你去巴瑞廢墟殺死3個灰舌駕馭者、4個灰舌戰士還有6個灰舌薩滿。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去影月谷找沙塔爾祭壇的守備官奧魯門。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10620 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10620, 'zhTW', '山脊的威脅', '當托斯利決定搬到外域去後我們就開始幫忙，自此之後就一直幫下去。$B$B現在看來我們終於斬除了一些根源。所有瘋狂的科學家們繼續進行著他們的計畫，而我們非正式騎兵是來保護他們的。$B$B我們現在需要你去北方的剃刀山脊，或是東邊的鱗翼沙洲，殺死行者來保持淨空。他們是住在岩石礦脈間的鬼祟蜘蛛，會對沒有戒心的過路者一撲而上。', '迪希·迪娜要你殺死10隻山脊行者。任務完成後，回到劍刃山脈的托斯利基地向她回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10621, 'zhTW', '伊利達瑞毀滅裂片', '這個金屬裂片看起來像是屬於一柄更大型武器的裂片。刻在金屬上的尖型圖樣發出駭人的光芒。$B$B你並不知道這把武器的用途，但是卻很難不理會它。大部分在軍團要塞的莫阿格在工作上使用到的金屬碎片看起來都跟你手上的一樣。也許蠻錘要塞的其中一位鐵匠能告訴你更多的訊息。', '將伊利達瑞毀滅裂片交給蠻錘要塞的歐爾汀·雷拳。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10622, 'zhTW', '表明立場', '阿卡瑪一直在附近觀察你的進展，$n。$B$B你在巴瑞廢墟殺死的灰舌是我們所知道最邪惡的破碎者……他是由阿卡瑪本身精心挑選出來以維持我們必須向伊利丹報告的事情表面。然而死亡誓言者知道阿卡瑪的真正意圖。$B$B事情總有先後順序。我們必須先確定你不是伊利丹的人。一個叫做薩卓瑞斯的薩特代表伊利丹監視著我們。殺死他就能證明你的立場。', '殺死影月谷的典獄官監牢的薩卓瑞斯然後向杉諾魯回報。', '', '去影月谷找守望者牢籠的薩諾魯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10623 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10623, 'zhTW', '伊利達瑞毀滅裂片', '這個金屬裂片看起來像是屬於一柄更大型武器的裂片。刻在金屬上的尖型圖樣發出駭人的光芒。$B$B你並不知道這把武器的用途，但是卻很難不理會它。大部分在軍團要塞的莫阿格在工作上使用到的金屬碎片看起來都跟你手上的一樣。也許影月村的其中一位鐵匠能告訴你更多的訊息。', '將伊利達瑞毀滅裂片交給影月村的葛羅空·亡眼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10624, 'zhTW', '鬧鬼的過去', '你有沒有感覺到一股陰風吹過?或許你會想是有人把手放在你的肩膀上?那並不是你的憑空想像，$r。這片土地一直以來都有鬼的存在。所有的地方都充滿著鬼魂，他們永遠都被困在這裡。$B$B你想看它們嗎?你確定?這種東西想改變一個人-往壞的方向。$B$B好吧，我要你去幫我去影月谷西邊的地獄熔岩池的附近收集永燃灰燼。只要是靠近綠色的熔岩……', '影月谷裡影月村的總藥劑師希爾達嘉要你帶給她15個永燃灰燼樣本。', '', '去影月谷找影月村的主藥劑師希爾達迦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10625, 'zhTW', '顯靈鏡', '我稱它為「顯靈鏡」。我真聰明，是嗎?當你戴上這個護目鏡，你將可以看到影月谷的鬼魂。$B$B然而在我給你之前，你必須答應我你會幫我們清除這些在村子的鬼魂。$B$B戴上這個護目鏡然後消滅你看到所有在影月村遊蕩的鬼魂。我們希望，消滅這些鬼魂會逼迫剩下的鬼魂移居別處。', '影月谷的影月村的總藥劑師希爾達嘉要你殺死12個影月狂熱者。', '', '去影月谷找影月村的主藥劑師希爾達迦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10626 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10626, 'zhTW', '奪取武器', '只要加強供應這種材料，我們就可以幫你打造一把可用的武器。$B$B軍團要塞的兩個深淵領主馬卡瑞登還有莫爾葛洛朗，已經裝備上這些對抗惡魔的武器。我們沒有辦法得知燃燒軍團預計要生產多少支這種武器，但是假如我們可以奪取它的原始樣本，那就可以推測出來了。$B$B<歐爾汀露出了笑容。>$B$B使用燃燒軍團的「秘密武器」來對抗他們很有成就感，你不覺得嗎?', '蠻錘要塞的歐爾汀·雷拳要你幫他取得馬卡瑞登的大刀還有莫爾葛洛朗的大刀。', '', '去影月谷找蠻錘要塞的奧丁·雷拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10627, 'zhTW', '奪取武器', '只要加強供應這種材料，我就可以打造一把適合你的武器。$B$B軍團要塞的兩個深淵領主馬卡瑞登還有莫爾葛洛朗，已經裝備上這些對抗惡魔的武器。奪取這他們的這兩把武器就可以提供足夠的材料製造你的武器，還有其他的武器。$B$B我等不及在戰場上對敵人使用這種武器。這樣就可以教訓燃燒軍團不該玩弄對抗惡魔的法術。', '影月村的葛羅空·亡眼要你帶給他馬卡瑞登的大刀還有莫爾葛洛朗的大刀。', '', '去影月谷找影月村的格羅克姆·死眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10628 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10628, 'zhTW', '阿卡瑪', '你已經表明了立場。我將告訴你我們首領的藏身處。$B$B順著那邊的牆走;有一個地下通道隱藏在你右手邊的水池裡。$B$B我必須警告你，$n。你不可以跟那邊你所看到的每一個人講話。', '跟典獄官監牢的密室裡的阿卡瑪談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10629, 'zhTW', '噁心的工作', '「我終於把我的伐木機修好了但是我好像把它的鑰匙搞丟了。我養了一批惡魔犬來保護我的營地。他們份內的工作做的不太好而且常常咬我。他們也喜歡亮晶晶的東西。我猜其中一支惡魔犬把我的伐木機鑰匙吃下去了。假如你願意帶我的惡魔犬去散個步的話我會獎賞你的。殺死一些地獄野豬然後讓它吃。它會做它該做的事情，等它吃完以後，在它的「排出物」中找找看有沒有我的鑰匙。」', '使用惡魔犬之哨召喚一隻惡魔犬。帶惡魔犬去散步然後殺死一些地獄野豬。在惡魔犬的「排出物」中尋找伐木機鑰匙。把伐木機鑰匙交給索爾瑪西北方礦坑裡的工頭瑞絲坎茲。', '', '去地獄火半島找索爾瑪礦洞的工頭拉澤克拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10630 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10630, 'zhTW', '索爾瑪的地下礦坑', '我已經快要恢復營運了。問題就出在我的礦坑中的甘納格。我無法派遣我的苦工進入工作而且一旦我修好了這個伐木機我也不想冒險派它去戰鬥。那些甘納格有一個首領就在礦坑的深處。假如你殺死他的話也許剩下的甘納格會離開。然後我就可以開始賺錢支付我離開這裡的旅費。', '殺死烏爾卡斯然後回報給索爾瑪西北方礦坑裡的工頭瑞絲坎茲。', '', '去地獄火半島找索爾瑪礦洞的工頭拉澤克拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10631 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10631, 'zhTW', '恢復營運', '開著我的伐木機器人，到礦裡去挖一些礦石回來。', '取一些礦石。', '', '去找。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10632, 'zhTW', '割下你的牙齒', '托斯利還有他的科學家們能夠得到你的幫助真是太好了。可惜我並沒有時間可以沉迷在「個人」嗜好上面。$B$B假如你想要幫這裡的忙，你只要聽從我的要求去做，而且是馬上，我需要一些武器。$B$B我們的槍在射程內很有殺傷力，但是當敵人靠近，我們則需要擁有一些強大的近戰武器做預備。$B$B北邊剃刀山脊的匕爪尾龍的牙齒可以做出精良的武器鋸齒劍身，連我都感到畏懼。', '洛薩克·鐵面要你取回5個特級銳利匕爪牙齒。完成後回到劍刃山脈的托斯利基地交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10633, 'zhTW', '泰朗·血魔-傳說與傳奇', '關於泰朗·血魔生平的故事實在太多了，但是大部分只是-故事而已。我們並不知道在他返回德拉諾之後發生了什麼事。$B$B我們唯一可以確定的是他曾經死過一次。$B$B我聽斥候回報說有一個古老的獸人靈魂居住在暗影祭壇，就在東南方的遠處，穿過虛空之翼農場還有虛空之翼小徑。帶著顯靈鏡然後找到這個獸人。他會有更多關於血魔的消息。', '影月谷影月村的總藥劑師希爾達嘉要你尋找古老的影月靈魂。假如你的顯靈鏡遺失的話，總藥劑師希爾達嘉可以幫你製作一副新的。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10634 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10634, 'zhTW', '預言:血魔的護甲', '血魔在世的時候是一個壞蛋，但是死後，他所製造的恐懼並沒有因而減少。$B$B你可以在東南方找到虛空之翼礦脈。有一塊曾經屬於影月谷的土地現在變成了浮在半空中的小島。$B$B身為死亡之翼後代的弗歐克爾曾經以這個小島為家，但是現在成了他的墓地。他在小島上不停的繞圈子飛行，為了他打敗血魔而激動著。$B$B假如你想取得血魔的護甲，你就必須打敗弗歐克爾。', '影月谷東南方暗影祭壇的古老的影月靈魂要你取得血魔的護甲。', '', '去影月谷找暗影祭壇的上古影月之魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10635 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10635, 'zhTW', '預言:血魔的披風', '他曾經犯下了許多殘忍暴行，但是沒有一個比的上屠殺那些卡拉伯爾教士。$B$B在古爾丹的部落軍隊擊敗了卡拉伯爾的德萊尼之後，卡拉伯爾教士的殘存者變成了戰俘，被迫集體以行軍的方式帶到地獄火堡壘。$B$B血魔，當時還未成為死亡騎士的血魔，冷血地殺死了每一個戰俘。那些戰俘的靈魂現在懷著復仇之心漫遊在黑暗神廟的前方。$B$B血魔的披風就是在那些卡拉伯爾教士的身上。', '影月谷東南方暗影祭壇的古老的影月靈魂要你取得血魔的披風。', '', '去影月谷找暗影祭壇的上古影月之魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10636 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10636, 'zhTW', '預言:血魔之杖', '他們一個個的在他面前跪下，為了表示忠誠而奉獻他們的生命。血魔舉起他的鐮刀然後把他們的頭砍下。在這場屠殺之後不久，血魔自殺了。$B$B但是他可不是為了懺悔才這麼做!不，血魔追求的是永恆不朽!卡拉伯爾鬼騎士從那些墮落的死亡騎士屍體上爬了起來。$B$B它們現在徘徊在古爾丹之手的道路上，等待它們主人回來的那一天。血魔之杖就在它們的手上。取回它……', '影月谷東南方暗影祭壇的古老的影月靈魂要你取回血魔之杖。', '', '去影月谷找暗影祭壇的上古影月之魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10637 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10637, 'zhTW', '製造混亂', '這些武器已經被證實，就跟我們所擔心的一樣。伊利丹正在卡拉伯爾廢墟訓練惡魔獵人，而我們必須阻止他。$B$B不要被他們的名字給騙了，$n，他們的力量將會用來對付我們就像我們對付惡魔一樣。$B$B他們的術士會召喚惡魔並且奴役它們來當作惡魔獵人的初級訓練。有一個深淵領主名做阿薩羅斯，被證實因其力量過於強大不能用在初級訓練上而被束縛在放逐的狀態。想辦法讓他脫離束縛。這樣就可以幫我們爭取所需的時間了。', '主教歐納拉要你返回卡拉伯爾廢墟，想辦法釋放阿薩羅斯。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去影月谷找沙塔爾祭壇的大主教歐納拉。', '釋放阿薩洛斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10638 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10638, 'zhTW', '影月城的訓練', '在影月城找到你的訓練師。', 'Seek &lt;NAME&gt; in the &lt;DISTRICT&gt; of Silvermoon City.。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10639 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10639, 'zhTW', '其實我是……泰朗·血魔', '現在血魔的物品已經被找回，整個謎團只剩下最後一塊拼圖就可以完成:故事的主人。$B$B<古老的影月靈魂嘴角上揚，露出邪惡的笑容。>$B$B當然你不會相信我告訴你的真實故事。暗影祭壇是我的牢籠。少了你的幫助，我將會永遠的被困在這裡。現在，我將佔據你的身體而你將會殺死我的俘虜解開我的束縛。假如你拒絕的話我們兩個都會永遠的被困在這裡。$B$B泰朗·血魔即將自由了!', '古老的影月靈魂利用你把你當成了工具!現在你已經幫他收集到他所需要的物品，他就露出了他的真面目-泰朗·血魔。想破解他的附身，你必須照他的命令去殺死『遠古看守者』卡西亞斯。完成之後，去找影月村的總藥劑師希爾達嘉。', '', '去影月谷找影月村的主藥劑師希爾達迦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10640 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10640, 'zhTW', '奧翠司', '在這種日子跟年代很難得會聽到有人願意成為惡魔獵人。更難得的是竟然還有人成為惡魔獵人之後卻不效忠於伊利丹。$B$B據說外域就有這樣子的一個人。這個人的名字據說在燃燒軍團納葛蘭一帶的領土比任何一個復仇者奧多爾的軍隊還要可怕。他的名字就是奧翠司。$B$B去納葛蘭的西邊找他。他或許會在這些新的惡魔獵人訓練場散播一些希望。', '去納葛蘭的西部找『受難者』奧翠司。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10641, 'zhTW', '對抗軍團', '燃燒軍團再次的腐化凡人的靈魂證明了他們的能耐。假如要我信任你所追尋的知識，我需要你證明你對我的忠誠心。$B$B一個叫做薩撒爾的惡魔長久以來都在利用她天生的虛無形態躲避我。$B$B她守護著憤怒女牧師而她們則在熔爐基地:苦難替她效命。殺死她的一名手下然後把鮮血灑在地上。這種公開的挑釁會讓薩撒爾暫時現形。在她消失前殺了她。', '『受難者』奧翠司要你從虛空風暴的熔爐基地:苦難的憤怒女牧師身上取得一個新鮮滴落的血液。將它灑在地上然後殺死薩撒爾的化身。任務完成後回去找奧翠司。', '', '去找納格蘭的受難者奧圖裡斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10642 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10642, 'zhTW', '機械中的鬼魂', '我擔心這些矮人們不知道他們把城堡蓋在了什麼樣的地方之上。這個地區曾經屬於影月獸人的祖先，我說的是他們靈魂沉睡的地方，$r。$B$B近二十年來他們都在蠻錘要塞的地底沉睡著，但最近某種原因驚醒了他們。$B$B穿過蠻錘之門尋找這片大地之下的地獄熔岩池還有地獄熔岩流。靠近熔岩的地方就有永燃灰燼。把這個灰燼帶給我，我才可以用它製造對我們有幫助的東西。', '影月谷的蠻錘要塞的『執法官』索羅斯要你交給他15個永燃灰燼樣本。', '', '去影月谷找蠻錘要塞的仲裁者索魯斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10643 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10643, 'zhTW', '影月先驅者', '以後大家就知道索羅斯的確有幽默感。$B$B閒話休提。這個顯靈鏡可以讓你看見在這個要塞徘徊的影月獸人靈魂。當你知道其實我們才是這裡的侵略者的時候不要害怕。唉，時間已經過了那麼久，他們一定是被滅絕了。消滅出現在蠻錘要塞的影月先驅然後向我回報。', '影月谷的蠻錘要塞的『執法官』索羅斯要你殺死12個影月先驅。', '', '去影月谷找蠻錘要塞的仲裁者索魯斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10644 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10644, 'zhTW', '泰朗·血魔-傳說與傳奇', '關於泰朗·血魔生平的故事實在太多了，但是大部分只是-故事而已。我們並不知道在他返回德拉諾之後發生了什麼事。$B$B我們唯一可以確定的是他曾經死過一次。$B$B我聽斥候回報說有一個古老的獸人靈魂居住在暗影祭壇，就在東方的遠處，穿過虛空之翼農場還有虛空之翼小徑。帶著顯靈鏡然後找到這個獸人。他會有更多關於血魔的消息。', '影月谷的蠻錘要塞的『執法官』索羅斯要你找到古老的影月靈魂。假如你弄丟了你的顯靈鏡，『執法官』索羅斯可以幫你做一副新的。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10645 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10645, 'zhTW', '其實我是……泰朗·血魔', '現在血魔的物品已經被找回，整個謎團只剩下最後一塊拼圖就可以完成:故事的主人。$B$B<古老的影月靈魂嘴角上揚，露出邪惡的笑容。>$B$B當然你不會相信我告訴你的真實故事。暗影祭壇是我的牢籠。少了你的幫助，我將會永遠的被困在這裡。現在，我將佔據你的身體而你將會殺死我的俘虜解開我的束縛。假如你拒絕的話我們兩個都會永遠的被困在這裡。$B$B泰朗·血魔即將自由了!', '古老的影月靈魂利用你把你當成了工具!現在你已經幫他收集到他所需要的物品，他就露出了他的真面目-泰朗·血魔。想破解他的附身，你必須照他的命令去殺死『遠古看守者』卡西亞斯。完成之後，回去找蠻錘要塞的『執法官』索羅斯。', '', '去影月谷找蠻錘要塞的仲裁者索魯斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10646 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10646, 'zhTW', '伊利丹的弟子', '你已經證明了你的忠誠心，$n。你必須原諒我的小心翼翼，因為世界上的東西並不是都像表面所呈現的一樣。$B$B等你準備好的時候我就會告訴你有關瓦瑞迪斯的事情。', '聆聽奧翠司的故事。', '伊利丹的學生', '去納格蘭找鑄魔營地：仇恨的受難者奧圖裡斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10647 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10647, 'zhTW', '懸賞:烏伏洛斯，影月谷的天譴軍團', '死亡懸賞令:$B$B烏伏洛斯，影月谷的天譴軍團。$B$B根據歐巴洛卡赫霸主的命令，那隻魔獸，烏伏洛斯應該要被立即處死而殺死它的人必須從屍體上剝下它的鬃毛以資證明。假如你成功的話就把它的火鬃交給公告員薩爾登·崔賴斯。$B$B烏伏洛斯最後出現的地方在古爾丹火山，就在影月谷的中心地帶-影月村的東邊。', '殺死烏伏洛斯然後取回烏伏洛斯的火鬃。交給影月谷的影月村裡頭的公告員薩爾登·崔賴斯。', '', '去影月谷找影月村的戰爭召喚者薩爾東·圖斯萊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10648 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10648, 'zhTW', '懸賞:烏伏洛斯，影月谷的天譴軍團', '死亡懸賞令:$B$B烏伏洛斯，影月谷的天譴軍團。$B$B根據賽恩尼·憂瑞卡爾的命令，那隻魔獸，烏伏洛斯應該要被立即處死而殺死它的人必須從屍體上剝下它的鬃毛以資證明。假如你成功的話就把它的火鬃交給公告員畢爾斯納特。$B$B烏伏洛斯最後出現的地方在古爾丹火山，就在影月谷的中心地帶-蠻錘要塞的東北邊。', '殺死烏伏洛斯然後取回烏伏洛斯的火鬃。交給影月谷的蠻錘要塞裡頭的公告員畢爾斯納特。', '', '去影月谷找蠻錘要塞的戰爭召喚者比爾斯諾特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10649, 'zhTW', '惡魔之名寶典', '關於你們想阻止瓦瑞迪斯還有他的追隨者我感到同情，你們不會成功的。想打敗他的話，除非你們找到給予他力量的神器。$B$B據說奧齊頓的暗影迷宮裡面的煽動者黑心擁有惡魔之名寶典。這本書是你打敗瓦瑞迪斯的唯一希望。', '去奧齊頓的暗影迷宮從煽動者黑心身上取得惡魔之名寶典。完成任務後向納葛蘭的奧翠司回報。', '', '去納格蘭找鑄魔營地：仇恨的受難者奧圖裡斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10650 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10650, 'zhTW', '回報奧多爾', '這本書……我能用它來增加我的力量十倍……不!它最終將腐化我的靈魂，我確信這。回去將你派來這裡的那些人那裡，$n。$B$B你現在有方法制止瓦瑞迪斯了。等待，直到他經由變形而顯露出他惡魔的形式，在那時，你將需要當他的面燒掉這本書。那將是你能剝奪他力量的唯一方法。', '跟影月谷薩塔祭壇的主教歐納拉談話。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10651 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10651, 'zhTW', '阻止瓦瑞迪斯', '我們必須處理掉這本腐敗的書，但是在那之前我們必須使用它來剝奪瓦瑞迪斯的力量。$B$B我們必須關閉卡拉伯爾廢墟的訓練場，意思是我們除了要殺死瓦瑞迪斯之外還要殺死三個協助他的夜精靈精銳:艾倫狄恩、賽拉斯還有奈斯瑞歐。遵照奧翠司的指示擊敗瓦瑞迪斯。為了我們大家，我希望你會成功。', '主教歐納拉要你去卡拉伯爾廢墟殺死艾倫狄恩、賽拉斯、奈斯瑞歐還有瓦瑞迪斯。當瓦瑞迪斯改變形態時使用惡魔之名寶典來削弱他的力量。任務完成後帶著惡魔之名寶典向主教歐納拉回報。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去影月谷找沙塔爾祭壇的大主教歐納拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10652 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10652, 'zhTW', '敵人身後', '我們已經安排好帶你去我們密探的藏身之處。當你準備好的時候就來找我，我們會安排你上路。', '當你準備好前往法力熔爐寇魯的時候跟維納妮雅交談。到達之後跟卡利迪斯·曙光談話。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10653 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10653, 'zhTW', '薩格拉斯印記', '現在你應該明白為什麼我們要對抗燃燒軍團還有他們的部下了。$B$B假如你想向奧多爾證明你自己，幫我帶來燃燒軍團還有他們的暗影議會追隨者的高階徽記。高階的燃燒軍團成員可以在虛空風暴還有影月谷找到。', '將10個薩格拉斯印記交給撒塔斯城的『護光者』艾德伊恩。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去撒塔斯城找奧爾多高地的聖光護衛者阿德因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10654 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10654, 'zhTW', '更多的薩格拉斯印記', '', '你佩帶了更多我們敵人的徽記了嗎，$c?燃燒軍團仍是一個威脅，我們將繼續在任何我們找到他們的地方追捕他們。', '', '去找聖光護衛者阿德因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10655 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10655, 'zhTW', '一個薩格拉斯印記', '', '我願意收下你身上任何多的印記。別擔心;你的行為將受到適當的表揚。', '', '去找聖光護衛者阿德因。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10656, 'zhTW', '日怒徽章', '就如你所知，占卜者跟凱爾薩斯的軍隊正在作戰。凱爾薩斯視我們為妨礙他影響血精靈的眼中釘，並且一再的攻擊我們。$B$B假如你想幫助我們對抗凱爾薩斯，你有很多目標可以進行。凱爾薩斯的高階士兵都穿著日怒徽章以標明階級。你可以在虛空風暴還有影月谷的全區域找到他們。', '撒塔斯城的博學者菲雅蘭要你帶給她10個日怒徽章。為占卜者完成任務會使你的奧多爾聲望降低。', '', '去找泰羅卡森林的魔導師菲亞琳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10657 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10657, 'zhTW', '操控閃電', '我們並沒有將ZC號的使用量維持在預算之內。但是，我發現剃刀山脊的鱗翼風蛇擁有閃電般的氣息還有腺體可以供我們利用。$B$B我已經重新磨光了電磁收集器好讓它可以吸收雷擊。總而言之，當它遭受雷擊的時候它的保護殼上有一個反應圈可以讓加強雷擊的能量，直到雷擊被吸收為止。喔，而且它會減慢你的速度。$B$B去吧，把收集器打開，然後幫我們帶回來一些便宜的燃料吧。', '托斯利要你使用再極化的磁力發電機球體從鱗翼風蛇身上吸收25個閃電之擊。同時，收集5個鱗翼閃電腺。然後回到劍刃山脈的托斯利基地交給他。', '', '', '吸收閃電之擊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10658 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10658, 'zhTW', '更多的日怒徽章', '', '你最近為我們做了什麼，$n?對凱爾薩斯的戰爭是不會自己開始的，你知道嗎?。', '', '去找泰羅卡森林的魔導師菲亞琳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10659 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10659, 'zhTW', '一個日怒徽章', '', '即使是最小的貢獻也會被注意到，$n。我們的敵人很多，但是我們將戰勝他們!。', '', '去找泰羅卡森林的魔導師菲亞琳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10660 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10660, 'zhTW', '奇怪的生物……', '我對研究那些在影月谷流動熔岩附近徘徊的奇怪爬蟲類很有興趣。我從來沒有看過可以忍受熔岩漿如此高溫的野獸!$B$B在影月村外面一個地面破碎又有熔岩流在地面的裂縫中穿梭的地方你可以找到惡魔烈焰雙帆龍。殺死他們並且把他們的脾臟拿給我。我可以對他們的脾臟進行初步的分析以了解他們對熱的抗性為何如此的高。$B$B從東南方開始搜尋吧。', '影月谷的影月村的研究員提歐魯斯要你取得8個惡魔烈焰脾臟。', '', '去影月谷找影月村的研究員提歐魯斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10661, 'zhTW', '美味的脾臟！', '你有沒有聽說過有食物會自己煮自己然後永遠都能維持熱度?我會說你在作夢!$B$B但是也許這個夢會是真的!就在要塞的外面靠近熔岩池還有熔岩流的地方你可以找到一些野獸活躍在高溫之中。他們叫做惡魔烈焰雙帆龍。$B$B在這裡的矮人告訴我那些雙帆龍擁有最美味的脾臟而且他們的脾臟不用煮就熟了!幫我帶回來一些脾臟我就會給你一些錢。$B$B你可以從東邊開始搜尋。', '影月谷的蠻錘要塞的葛諾瑪斯要你取得8個惡魔烈焰脾臟。', '', '去影月谷找蠻錘要塞的諾姆斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10662, 'zhTW', '隱居的鐵匠', '<歐爾汀正在檢驗他試著鎔鑄這個金屬的結果然後搖了搖頭。>$B$B這已經超出了我的能力範圍之外，但那並不表示這武器不能重新製造供你使用。$B$B有一個技術高強的鐵匠大衛·偉恩，他曾經陪伴洛薩之子到德拉諾。他是一位了不起的鐵匠，可惜選擇離開了遠征隊。這些日子以來，他住在泰洛卡森林的火翼崗哨東方，那是在一個半島上的小營地 。把這些金屬錠帶給他然後看他是否可以幫你製造武器。', '將一箱鑄塊帶到泰洛卡森林的韋恩的避難所給大衛·偉恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10663, 'zhTW', '隱居的鐵匠', '<獸人失敗地搖了搖頭。>$B$B這已經超出了我的能力範圍之外，但那並不表示這武器不能重新製造供你使用。$B$B有一個技術高強的鐵匠大衛·偉恩，他曾經陪伴洛薩之子到德拉諾。他是一位了不起的鐵匠，可惜選擇離開了遠征隊。這些日子以來，他住在泰洛卡森林的火翼崗哨東方，那是在一個半島上的小營地 。把這些金屬錠帶給他然後看他是否可以幫你製造武器。', '將一箱鑄塊帶到泰洛卡森林的韋恩的避難所給大衛·偉恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10664, 'zhTW', '額外的材料', '你帶來的金屬錠包含了大部分我鑄造這把劍身所需要的金屬，但是我還需要其他的一些材料才能製造這武器的其他部分。$B$B我需要卻又不在這裡的東西有一個堅鋼骨架、一些厚重境外皮革還有一個惡魔守護圖騰。技巧熟練的鑄造家應該會製造前兩樣東西，但是第三樣東西只能跟撒塔斯的陰鬱城裡頭的施法材料商范提購買。他就站在販售商人之中。', '韋恩的避難所的大衛·偉恩要你帶給她一個堅鋼骨架、4張厚重境外皮革還有一個惡魔守護圖騰。', '', '去泰羅卡森林找韋恩的避難所的戴維·韋恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10665, 'zhTW', '麥克納爾的容器', '要熔鑄你帶來的這些金屬錠將需要很大的熱能-這不是一般的熔爐可以供應的。$B$B我將需要額外的熱能來源提供給我的熔爐而且在外域只有非常少數的東西可以提供那麼大的能量。$B$B風暴要塞的麥克納爾區那邊的法力容器含有非常大的能量。從機械王卡帕希特斯附近的法力容器堆尋找一個滿溢的法力容器然後帶回來給我。', '韋恩的避難所的大衛·偉恩要你交給他一個滿溢的法力容器。', '', '去泰羅卡森林找韋恩的避難所的戴維·韋恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10666, 'zhTW', '惡魔詞典', '重新在劍上附魔需要幾個用惡魔語唸出的法術。$B$B這在我接受學徒訓練的時候並沒有傳授給我，反正也沒有地方可以學這種東西。有一本書，叫做惡魔詞典，裡面包含了大部分我需要的惡魔語，但是它被一個暗影議會術士所持有。$B$B它的持有者領導者瓦皮歐，位在奧齊頓的暗影迷宮的大廳深處。不管你用什麼手段都要把那本書取回來給我。', '從領導者瓦皮歐身上取得惡魔詞典然後交給韋恩的避難所的大衛·偉恩。', '', '去泰羅卡森林找韋恩的避難所的戴維·韋恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10667 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10667, 'zhTW', '地獄土壤', '你之前帶給我的骨架在還沒強化之前是不足以支撐那些鎔化的金屬。有一種稀有的土壤可以用來冷卻並且強化骨架，使骨架的硬度增加異常的強度。$B$B這種土壤被稱為地獄土壤，給予了納迦很大的利用價值。只有極少數的納迦才能持有它，而在外域我只知道一個使用它的納迦-海法師希斯比亞，他居住在盤牙蓄湖的蒸汽洞窟。', '從海法師希斯比亞的身上取得一個瓶裝地獄土壤交給韋恩的避難所的大衛·偉恩。', '', '去泰羅卡森林找韋恩的避難所的戴維·韋恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10668, 'zhTW', '對抗伊利達瑞', '我仍然尊敬伊利丹。要不是他我不會找到我的方向。$B$B然而，他已經不是原來的他了。他的靈魂已經為了追求力量而腐敗了，他的心智已經被權力給扭曲了。他已經變成我當初發誓要消滅的罪惡，而伊利丹的手下們也變成像燃燒軍團一樣的憎恨著這世界。$B$B他在外域的領土已經逐漸縮小但是他的勢力範圍仍然廣闊。為了證明你跟他不是一夥的，殺了他在影月谷的伊利達瑞崗哨的副官洛斯羅司。', '『受難者』奧翠司要你去殺影月谷的伊利達瑞崗哨的洛斯羅司。', '', '去找納格蘭的受難者奧圖裡斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10669, 'zhTW', '挑戰不可能', '有些惡魔只忠於自己。真正的惡魔會尋找並且殺死他的獵物，不管它的獵物是屬於哪個勢力。$B$B惡魔希樂斯-一個燃燒軍團背叛者-曾經被一群在贊格沼澤的沼澤生物當作神來祭拜。當德拉諾快要被摧毀的時候，他撤退到沼澤光之湖的底部進入冗長的睡眠之中。在沼澤光之湖找到傳送門然後將這柄矛插入地面中。$B$B希樂斯將會醒來-做好你的準備殺了他，證明你是所有惡魔的敵人。', '『受難者』奧翠司要你在贊格沼澤的沼澤光之湖的傳送門使用灌魔銀矛以喚醒希樂斯。殺死他之後回去找奧翠司。', '', '去找納格蘭的受難者奧圖裡斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10670 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10670, 'zhTW', '大地之母的眼淚', '這把劍的附魔一定是需要某種強大的施法材料，例如一個寶石。我知道一種寶石可以達成我們的目的，因為要承受如此強大附魔法術而不會碎裂的施法材料實在太少了。我們所需要的寶石叫做大地之母的眼淚。這個寶石在當初創造它的巨魔手中就具有強大的法力，而現在的持有人戰爭使者歐姆拉格在地獄火堡壘的破碎大廳有許多強而有力的盟友。取回寶石前你要保重你自己，$n。', '從戰爭使者歐姆拉格身上取回大地之母的眼淚然後交給韋恩的避難所的大衛·偉恩。', '', '去泰羅卡森林找韋恩的避難所的戴維·韋恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10671, 'zhTW', '一磅多的肉', '$N，我有別的事情要你去做。那些知識份子之中的一個人想要研究在雷森平台那出現像惡魔般的血肉野獸，就在剃刀山脊的北邊。$B$B更重要的是，他們想研究那邊的血肉野獸的肉。$B$B<迪希做出了一個作嘔的表情。>$B$B不過當然，他們不想把自己的手弄髒，而且他們只想要蒼穹能量肉體，這可不是所有的血肉野獸都有的。$B$B我說，拿人的手短，但是你又能怎麼辦呢?', '迪希·迪娜要你取得5個蒼穹能量肉體然後回到劍刃山脈的托斯利基地交給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10672 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10672, 'zhTW', '老實說，這樣不合理', '我們必須對這種生物做進一步的研究。$B$B在東邊遠處的巴瑞廢墟下方，大型熔岩流的附近你可以找到秘法控制裝置。這些控制器是由一個叫做葛諾瑪斯的天才所製造，唯一的目的是透過機械操控的蠍子來探測熔岩漿。$B$B他已經有很長的一段時間失去了理智而現在只對一種地精們所熟知最熱的食物有興趣。$B$B<提歐魯斯做出好笑的表情。>$B$B我要你使用控制器然後標示那些在熔岩流的雙帆龍以進行進一步的研究。', '影月谷的影月村的研究員提歐魯斯要你去巴瑞廢墟的熔岩流附近然後使用秘法控制裝置控制一隻秘法蠍子，操控它潛入熔岩流中標示8隻大型惡魔烈焰雙帆龍。', '', '去影月谷找影月村的研究員提歐魯斯。', '標記大型魔火雙帆龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10673 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10673, 'zhTW', '偉大的魔脊', '葛諾瑪斯已經知道了雙帆龍聚集的所在處並且計畫要把他們吃光光!他一定是透過他的秘法蠍子的眼睛看到我所看到的景象。聽我說，我沒有時間跟你解釋。他已經瘋了而且他的瘋狂行徑將會使得我們喪失製作防火跳傘裝最後的一樣材料。$B$B回到巴瑞附近的熔岩流然後尋找偉大的魔脊。一旦你找到它，殺了它然後將他的毛皮帶回來給我。$B$B不要跟我討價還價，$n。我不吃那一套。', '影月谷的影月村的研究員提歐魯斯要你殺死偉大的魔脊並且取回魔脊之皮。', '', '去影月谷找影月村的研究員提歐魯斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10674, 'zhTW', '捕捉神奇的光球', '北邊雷森平台的雷森伊斯利開發了一些有趣的科技產品。$B$B我相信他們不會介意你使用這個陷阱捕捉幾個他們浮在空中的粉紅色光球吧?反正那些光球八成只是裝飾品而已。$B$B這個陷阱有一個特殊的功能，當陷阱開啟時會吸引一個飄浮的光球飛向它。當然，它同時也會驚動到那些雷森關於你的到來。', '托斯利要你使用聖光陷阱捕捉15個雷森光球。任務完成後回到劍刃山脈的托斯利基地向他回報。', '', '', '已捕捉雷森光球', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10675, 'zhTW', '給他們地精式的解脫!', '<血從托斯利的臉上流了下來。>$B$B這些球體是由虛空的能量還有靈魂所組成的，部分的靈魂竟然是地精的靈魂!$B$B他們真大膽!我們那些往北旅行的同伴們，就是他們殺死的嗎?!$B$B$N，你必須阻止這件事，而唯一的解決方法就是殺死他們的首領，奈薩斯王子洛薩恩。$B$B但是你必須將他從隱匿中引誘出來。我猜你只要殺死大量的雷森伊斯利就會引誘他現身。$B$B將他身上的靈魂收集品交給我，那東西一定在他身上。', '托斯利要你取得靈魂收集品然後回到劍刃山脈的托斯利基地交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10676, 'zhTW', '伊利達瑞的剋星', '<大衛聚集了他的鑄造工具。>$B$B在取回我們重鑄那把克制惡魔的劍刃材料上你做的很好。你的艱苦努力以及奉獻都將值回票價。$B$B是重鑄這把劍的時候了。', '等待大衛·偉恩完成為你鑄造的劍。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10677, 'zhTW', '第二道菜……', '我記得古爾丹火山的東邊看過更大型的雙帆龍，就在靠近巴瑞廢墟的熔岩地帶附近。幫我去那邊附近的雙帆龍身上取回一個過大的惡魔烈焰內臟。你可能需要殺掉許多隻才能找到一個像我形容的胃囊。去吧!其中一支倒楣的雙帆龍注定要成為我的下一餐。', '影月谷蠻錘要塞的葛諾瑪斯要你取回一個過大的惡魔烈焰內臟。', '', '去影月谷找蠻錘要塞的諾姆斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10678, 'zhTW', '主菜上場!', '長話短說，我曾經跟一個叫做提歐魯斯的血精靈共事過。當我可以進入美食之家的時候我們的關係就破裂了。他決定自行繼續用我的發明來進行我們的研究。總而言之，他雇用了一些部落惡徒在巴瑞廢墟的熔岩地帶使用我發明的秘法蠍子找到了所有雙帆龍之母!$B$B我要你去那邊在他之前殺死那隻雙帆龍之母，魔脊，然後帶回它的毛皮給我。$B$B動作快!', '影月谷蠻錘要塞的葛諾瑪斯要你帶回魔脊之皮。', '', '去影月谷找蠻錘要塞的諾姆斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10679 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10679, 'zhTW', '冷卻刀刃', '這把刀接近完成了!$B$B你幾乎可以感受到魔法開始在鋼鐵裡結合，但是還有一件事要去完成。$B$B你必須帶著這把煉冶過的刀到影月谷裡接近古爾丹火山頂部的沸水池將這把刀丟入熔岩池裡將它冷卻。在你將這把刀冷卻後，回來這裡。', '前往靠近古爾丹火山頂部的沸水池將鍛造伊利達瑞毀滅之刃放入熔岩池中冷卻。一旦你弄到冷卻的伊利達瑞毀滅之刃，就回到韋恩的避難所找大衛·偉恩。', '', '去泰羅卡森林找韋恩的避難所的戴維·韋恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10680 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10680, 'zhTW', '古爾丹火山', '元素之靈需要你的幫忙，$r!影月谷已經受到一股無法形容的邪惡勢力給支配著。生靈們一直被折磨著直到今天。許多人顯得憤怒並且不願意加入陶土議會。$B$B朋友，請幫忙治癒這片大地。$B$B往蠻錘要塞的東北方前進你會發現一個地區稱為詛咒祭壇。去那邊跟大地治癒者托爾洛克交談吧。', '跟影月谷詛咒祭壇的大地治癒者托爾洛克交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10681, 'zhTW', '古爾丹火山', '元素之靈需要你的幫忙，$r!影月谷已經受到一股無法形容的邪惡勢力給支配著。生靈們一直被折磨著直到今天。許多人顯得憤怒並且不願意加入陶土議會。$B$B朋友，請幫忙治癒這片大地。$B$B在影月村的東南方-影月谷的中央地帶-你會發現一個地區稱為詛咒祭壇。去那邊跟大地治癒者托爾洛克交談吧。', '跟影月谷詛咒祭壇的大地治癒者托爾洛克交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10682, 'zhTW', '協商時間……', '當我們抵達魯安曠野，巨龍教徒們正集中在黑翼集會所，經由這個隧道通往西方。不過現在，它們正接近我們這裡，$B$B我需要你去找到巨龍教徒的監督者。他在魯安曠野的各個營地之間定時巡邏。$B$B與他商量一下。讓他知道有協商的空間，不過我們不會寬恕或允許大規模屠殺野生生物，包括樹林的砍伐也是一樣。', '林木守衛蕭恩要你去與監督者奴阿爾協商。完成後回到劍刃山脈的永恆樹林找林木守衛。', '與監工努阿爾的談判已完成', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10683 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10683, 'zhTW', '巴瑞碑文', '灰舌破碎者收到伊利丹的命令去遙遠的北方挖掘巴瑞廢墟。毫無疑問地，他們在搜尋德萊尼的神器 - 在古爾丹將這個城鎮埋於一場火山爆發前巴瑞是許多巴瑞古物的起源地。我們得利用這次的機會去發現巴瑞石板，一個先祖原文，據說藏有卡拉伯爾神廟的秘密……一個你或許知道的地方，黑暗神廟。', '星光聖所的秘法師賽利斯要你去巴瑞廢墟從地上及灰舌勞工身上收集12個巴瑞碑文。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去影月谷找群星聖殿的奧術師塞里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10684, 'zhTW', '長者奧朗奴', '根據石板上的記載，有一個被稱為卡拉伯爾勳章的神器被收藏在巴瑞。只有德萊尼的最高階祭司會被贈與此物，因為它可以讓使用者自由的進入卡拉伯爾神廟。$B$B我們必須想辦法得知灰舌奪回勳章了沒。它的力量會對我們跟伊利丹的戰鬥提供很大的幫助。$B$B阿卡瑪每天都會傳遞手寫的命令給在巴瑞的副官，長者奧朗奴。把那些信件取回來並且交給我。', '星光聖所的秘法師賽利斯要你去巴瑞廢墟取回長者奧朗奴身上的阿卡瑪的命令。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去影月谷找群星聖殿的奧術師塞里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10685 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10685, 'zhTW', '灰舌墮落者', '阿卡瑪的信中指出，大勳章的四個碎片被挖掘出來的時候送給了灰舌墮落者。這些可怕的破碎者曾經是一個強大的薩滿如今褻瀆了薩滿們所尊敬的元素力量。$B$B風之墮落者，哈盧姆可以在虛空之翼小徑找到。伊肯尼恩還有烏拉魯，大地和火之墮落者最後被人發現的地方是在靠近古爾丹火山的惡魔深淵。拉卡恩，水之墮落者謠傳是在靠近考斯卡崗哨的地方。$B$B找到他們並且取回勳章碎片。', '從哈盧姆，伊肯尼恩，拉卡恩和烏拉魯那邊取回四個勳章碎片然後回到影月谷的星光聖所找秘法師賽利斯。為占卜者完成任務會使你的奧多爾聲望降低。', '', '去影月谷找群星聖殿的奧術師塞里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10686 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10686, 'zhTW', '典獄官監牢', '你獲得的碎片只是勳章的一半而已。灰舌的領導者阿卡瑪一定擁有另一半。$B$B我不敢這麼要求你，因為阿卡瑪既邪惡又狡猾。$B$B據說他跟灰舌部族裡頭最邪惡最慘忍的傢伙死亡誓言者，在典獄官監牢的某處設置了一間刑房密室。$B$B我要你找出那間可怕的監獄，並且打聽阿卡瑪的下落。破碎者杉諾魯是他們當地的第二指揮官，必要的時候可以拷問他。', '秘法師賽利斯要你前往位在巴瑞廢墟南邊的典獄官監牢。拷問杉諾魯關於阿卡瑪的下落。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10687, 'zhTW', '卡拉伯爾訓練場', '我們的斥候回報發現了一大群日怒血精靈軍隊正朝卡拉伯爾廢墟行進中。通常這種情形只會代表著一種軍事威脅，不過我們仍然覺得事情有點不對勁。$B$B根據斥候回報的描述，他們的穿著還有作戰方式都很像伊利丹本人。我不希望為了未經證實的揣測而提高警戒，所以我希望你去幫我取回一些他們的武器。然後我們就可以知道我的揣測是否正確了。', '星光聖所的拉瑞莎·擊日者要你從星光聖所東北方，卡拉伯爾廢墟的惡魔獵人懇求者還有惡魔獵人見習生身上奪回8個日怒大刀。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去影月谷找群星聖殿的拉瑞薩·射日者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10688 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10688, 'zhTW', '製造混亂', '這些武器已經被證實，就跟我們所擔心的一樣。伊利丹正在卡拉伯爾廢墟訓練惡魔獵人，而我們必須阻止他。$B$B不要被他們的名字給騙了，$n，他們的力量將會用來對付我們就像我們對付惡魔一樣。$B$B他們的術士會召喚惡魔並且奴役它們來當作惡魔獵人的初級訓練。有一個深淵領主名做阿薩羅斯，被證實因其力量過於強大不能用在初級訓練上而被束縛在放逐的狀態。想辦法讓他脫離束縛。這樣就可以幫我們爭取所需的時間了。', '拉瑞莎·擊日者要你回到卡拉伯爾廢墟，並且找出方法釋放阿薩羅斯。B為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去影月谷找群星聖殿的拉瑞薩·射日者。', '釋放阿薩洛斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10689 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10689, 'zhTW', '奧翠司', '你沒看見當今的許多惡魔獵人。他們被他們自己的族人以懷疑的眼光觀看，而要找到沒有對伊利丹多少有點忠誠的是非常稀少的。$B$B有謠傳說在納葛蘭外面有一個這樣的惡魔獵人。他的名字是奧翠司。他出於憤怒地憎惡全部的惡魔，如果你能使他相信你有與他共同的目標，那他將幫助我們。$B$B到西方的納葛蘭去並找到他。他可能願意散發一些光芒在這些新惡魔獵人訓練場地上。', '前往西方的納葛蘭並且找到『受難者』奧翠司。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10690 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10690, 'zhTW', '獸穴之后', '懸賞!$B$B瑞瑪，雷霆王村南邊鋸齒山脊的獸穴之后及主要的防衛者。$B$B出到鎮外向東走，越過橫跨血槌深谷的橋找到她。她隱居在橋南邊的隧道內。$B$B帶著她死亡的消息回到希爾瓦納的指揮官天影那裡。', '殺死瑞瑪然後通知在劍刃山脈之希爾瓦納的指揮官天影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10691 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10691, 'zhTW', '回到先知者身邊', '這本書……我能用它來增加我的力量十倍……不!它最終將腐化我的靈魂，我很確定。回去派你來這裡的那些人身邊，$n。$B$B你現在有方法制止瓦瑞迪斯了。等待，直到他經由變形而顯露出他的惡魔型態，在那時，你將會需要當他的面燒掉這本書。那將是你能剝奪他力量的唯一方法。', '與影月谷裡星光聖所的拉瑞莎·擊日者談談。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10692 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10692, 'zhTW', '阻止瓦瑞迪斯', '當然我們必須摧毀這本書，但不是在我們用它來毀滅瓦瑞迪斯之前。$B$B假如我們要關閉伊利丹模仿者的這所學院，我們必須不只對付瓦瑞迪斯，也必須對付這三個幫助他的夜精靈大師:艾倫狄恩，賽拉斯和奈斯瑞歐。$B$B聚集一種合適力量並返回卡拉伯爾廢墟。 遵循奧翠司的指示以戰勝瓦瑞迪斯。很希望他的計畫將有效 - 否則……與你合作將會是一種快樂。', '拉瑞莎·擊日者要你到卡拉伯爾廢墟殺掉艾倫狄恩、賽拉斯、奈斯瑞歐以及瓦瑞迪斯。在瓦瑞迪斯使用變形符文時用惡魔之名寶典來削弱他的力量。任務完成後帶著惡魔之名寶典回報拉瑞莎·擊日者為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去影月谷找群星聖殿的拉瑞薩·射日者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10693 AND `locale` = 'zhTW';
