INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10701, 'zhTW', '擊倒虛空石', '致關心X-52虛空火箭建造進度的人 - $B$B本地的山巨人之王，虛空石，已對破碎荒地造成了威脅。他已經干擾了整個島嶼南方岸邊的運作!$B$B帶你的朋友一起去解決掉他!完成後，回到52區這來找我。$B$B火箭主管夫斯拉吉', '殺掉虛空石後回到虛空風暴的52區向火箭主管夫斯拉吉回報。', '', '去找虛空風暴52區的火箭主管弗斯拉格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10702 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10702, 'zhTW', '蠻兵的工作……', '所有本地的部落軍隊都被派去處理燃燒軍團的攻擊。這表示我們蠻兵人手不足。$B$B我們的補充品商隊一直受到本地野獸的攻擊。我們無法繞道15步遠而不撞見一隻奇美拉，惡魔野豬，或變種的大蠍子。$B$B到那裡去清理影月谷那些天性殘暴的野獸!殺光它們!', '影月谷裡影月村的歐巴洛卡赫霸主要你去殺掉20隻影月村野生動物。這些動物內包括惡魔野豬，邪惡之翼奇美拉，以及熱殼螯蝎。任何一種組合都可以。', '', '去影月谷找影月村的奧巴洛恩大王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10703 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10703, 'zhTW', '套上你的護膝……', '該是在泥中打滾搞得全身髒兮兮的時候了。你本來期望什麼呢?你得在會爬之前學走，對吧?阿，講反了……$B$B不管如何，我們都得全心全力撲殺那些被燃燒軍團丟給我們的垃圾。那會為你帶來為影月谷清理瘋狂的野獸的美名。$B$B抓把劍吧，棍棒，不管是什麼你高興就好，把你看得到的野獸都殺掉，愈多愈好。這樣一定會為我們的補給商隊清出一條路!', '影月谷裡蠻錘要塞的賽恩尼·憂瑞卡爾要你去殺掉20隻影月谷野生動物。這些生物包括惡魔野豬，邪惡之翼奇美拉，以及熱殼螯蝎。任何一種組合都可以。', '', '去影月谷找蠻錘要塞的大領主尤雷加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10704 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10704, 'zhTW', '闖入亞克崔茲的方法', '你發現的阿塔莫水晶中鑲有一則訊息。奈薩斯王子哈拉瑪德已經提供我們關於對抗風暴要塞非常重要的資訊。$B$B他告訴我們他們將一把鑰匙分為兩片裂片，兩者合一時可開啟要塞的亞克崔茲衛星。$B$B一半由波塔尼卡的一位古老生物叫扭曲分裂者所持有。另一半由麥克納爾裡的操縱者帕薩里歐擁有。$B$B將兩個裂片帶來給我，我會將他們合成亞克崔茲鑰匙。', '阿達歐派你去取得亞克崔茲鑰匙的頂部和底部裂片。將它們帶回去給他，他會將他們合成亞克崔茲鑰匙後交給你。', '', '去找沙塔斯城的阿達歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10705 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10705, 'zhTW', '先知烏達羅', '我希望你在我告訴你那些從我的爪牙手上取來的好幾片卡拉伯爾勳章都只是複製品時不要太震驚。<阿卡瑪打開他的手掌給你看一個完全相同的勳章。>我的死亡誓言者跟我盡可能的守住這個秘密不讓伊利丹知道。不過我們還是會懷念那最後的一片。烏達羅到我的夢裡宣稱他已找到了那最後的一片勳章。糟糕的是他正被凱爾薩斯監禁在風暴要塞的亞克崔茲裡。去找到他並看看他到底知道些什麼。', '到風暴要塞的亞克崔茲找到先知烏達羅。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10706 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10706, 'zhTW', '神秘的前兆', '在他死之前，烏達羅好像在他下面的地板上寫了一個單字。字體很難辨認不過你看出了這個字阿塔莫。$B$B或許阿卡瑪會知道他同胞所要傳達的訊息內容是什麼。', '回到影月谷的典獄官監牢找阿卡瑪。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10707 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10707, 'zhTW', '阿塔莫露臺', '我們已經知道那些受伊利丹控制的魔獄獸人在阿塔莫露臺守護著一顆名為狂怒之心的阿塔莫水晶。他們以黑暗魔法掩蓋它的光芒以防落入薩塔的手中。$B$B以你的方式打入黑暗神廟外的阿塔莫露臺並往天空方向看。暗影領主戴斯衛歐會在你無法到達的工匠區盤旋。你必須殺掉他跟他的術士群們才能拿取水晶。$B$B一點都不容易啊，$n。祝你好運了。', '到影月谷內阿塔莫工匠區的頂端取得狂怒之心。完成任務後回到影月谷的典獄官監牢找阿卡瑪。', '', '去影月谷找守望者牢籠的阿卡瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10708 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10708, 'zhTW', '阿卡瑪的承諾', '<阿卡瑪將這顆水晶插入手中的勳章中。>$B$B我的身體已大不如前，$n。經過這麼多年如此接近邪惡的本體 - 我不知道是否還能夠相信自己可以持有力量如此強大的神器而無動於衷。$B$B把這個當成我對你的承諾，當時機來臨你得面對伊利丹的時候，我會支持你。把它帶給那個我們都認識且能夠相信它的力量的人。將這個勳章交給撒塔斯城的阿達歐。', '將卡拉伯爾勳章交給撒塔斯城的阿達歐。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10709 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10709, 'zhTW', '團聚', '所以你來自傳送門外的世界嗎?並且你知道雷克薩。噢是的，我跟他很熟。其實，他是我的兒子。但他在很久以前，做出了他的選擇。他不屬於我們之中的一員，而他在這裡也不受歡迎。有這些血槌巨魔，我們的麻煩已經夠多了。要知道:身為一個混血兒並不代表你就是摩克納薩爾。', '回到劍刃山脈的雷霆王村找雷克薩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10710 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10710, 'zhTW', '飛行測試:美聲山脊', '我一直都在搬弄著ZC號，因此我準備好進行另一個測試了!你想要幫忙嗎?$B$B下一次的飛行會很短，但是很快!$B$B嗯……雖然我確定不會有危險……不過我有準備這個，呃，同意書要你簽署。這只是形式上啦，我跟你保證!$B$B祝你好運囉!要升空時跟瑞利談談，實驗結束後回來找我!', '簽署塔利的切結書，接著與瑞利·薩普納伯談談以使用ZC號。完成後回到托斯利基地找塔利·薩普納伯。', '拋開謹慎，放手一搏', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10711 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10711, 'zhTW', '飛行測試:雷森平台', '$n，我將ZC號的效能提高了百分之三十。那將會一個等同你的體重的測試物品和風阻比率發射達到新的高度!想要驗證我的理論嗎?這個實驗應該會將你發送到接近雷森平台的地方。$B$B與瑞利談談……他會幫你準備好升空。', '與瑞利·薩普納伯談談以使用ZC號。完成後回到托斯利基地找塔利·薩普納伯。', '抵達天空的極限', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10712, 'zhTW', '飛行測試:魯安曠野', '你好阿，$n。很高興又遇到你了!我有一個非常重要的任務!$B$B這是一個旋轉的虛空天氣風向儀。我需要你在飛行時帶幾個幫我閱讀上面的數據後再將它們交給我在魯安曠野的親戚。$B$B與瑞利談談後搭乘一架ZC號飛往魯安曠野去。在你飛行時，轉動這個風向儀!$B$B登陸後，帶著這個旋轉風向儀給歐瑪利·贊普奈。$B$B祝你好運，$n。別遲到了!', '與瑞利·薩普納伯談談以使用ZC號。飛到魯安曠野的途中，轉動虛空天氣風向儀。將旋轉的虛空天氣風向儀送到魯安曠野給歐瑪利·贊普奈。', '發射到盧安荒野。', '去劍刃山脈找常青林的歐瑪利·薩普納波。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10713, 'zhTW', '……行動的時間到了', '我們不能袖手旁觀任由他們在我們身邊屠殺魯安曠野。我們首要的考慮一定是那些樹。$B$B$C，我要你回到曠野去幫我們傳達一個非常特別的訊息。我要你殺掉每一個你接觸到的砍伐者!$B$B如果他們不講道理，或許他們會聽從這種更武斷的勸導!', '到魯安曠野去殺掉10個巨龍教團砍伐者，完成後回到劍刃山脈的永恆樹林找林木守衛蕭恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10714 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10714, 'zhTW', '精靈的翅膀上', '如果巨魔們騷擾摩克納薩爾，那麼我將制止他們及他們的跟隨者。巨魔們是一種頭腦簡單的生物，而且摩克納薩爾煩惱對他們而言也幾乎沒有好處。$B$B一定有其他原因。$n，帶著精靈，我的老鷹，並刺探血槌領導人間的談話。他可以進入而不會被發現，但我們不能。', '找到忙著聊天的一對血槌監工及血槌預言者，接著使用雷克薩的哨子召喚出精靈來暗中監視他們。完成後，回到劍刃山脈的雷霆王村找雷克薩。', '', '', '竊聽血槌巨魔的計畫', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10715 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10715, 'zhTW', '進入翻騰峽谷', '那麼，你的雷克薩想要我為他製作一種毒藥嗎?我將給他所想要的，但是是有價格的。即使對朋友，一定也有一個價格。免費的東西破壞友誼。$B$B首先，你必須冒險一小段路程，往西南方到翻騰峽谷。$B$B在那裡的磨坊裡，有一些在整個外域，或任何地方，最毒的生物。我說的是地殼穿刺者，而做這毒劑，將需要收集它們的腺體來給我。', '沙伯邁恩男爵已經告訴你為了要做出雷克薩需要的毒藥，你必須取得7個地殼穿刺者的毒腺。一旦你完成任務，返回到劍刃山脈位於血之環的沙伯邁恩男爵處。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10716 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10716, 'zhTW', '飛行測試:烏鴉林<需要報酬>', 'ZC號已經準備好做最長遠的升空了！你覺得呢，$N？你想要再飛行一次嗎？$B$B我已經改良了推進系統但是，直到我算出所有變數前，卡皮悉拓鋰得需要新增燃料以提供必要的後衝力！在飛行前去和瑞利談談 - 他知道細節。$B$B祝你好運，$N。這趟飛行將會帶你到遠方的烏鴉林去。如果你在這場飛行後還活著 - 還有林中的巨魔及阿拉卡 - 就回到這來慶祝吧！', '與拉雷·薩普納波談一談，並使用風動電容器。然後返回託什雷的基地，向塔利·薩普納波覆命。', '深入危險區域。', '去刀鋒山找託什雷的基地的塔利·薩普納波。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10717 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10717, 'zhTW', '行竊侵入者', '原諒我，但我無法不去偷聽你跟蕭恩的對話。我想要幫忙你。$B$B我正在研究黑翼集會所的事，並幫忙德魯伊們與他們交易。$B$B我很想要幾隻他們的幼龍;這會有助於我們藉由了解他們所尊敬事物來判斷我們真正對抗的是什麼。$B$B不過首先，我們得需要一些網子。我注意到魯安曠野外圍的巨龍教團盜獵者身上有一大堆網子。', '沙彌亞·暗示者要你去取得5個巨龍教團織網並帶回劍刃山脈的永恆樹林交給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10718 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10718, 'zhTW', '靈魂會說話', '$N，既然你能看見我，有樣東西你必須告訴雷克薩。我知道他在尋找他的族人，並且我也知道他們在那裡。摩克納薩爾，正如他們被人所知道的，在剃刀山脊東方有一個村莊。去那裡，帶給雷克薩這則消息。他的人處境危險，而且我知道他將想要來幫助他們。', '嘎姆·狼伴已經告訴你摩克納薩爾，雷克薩的族人，住在那裡。對劍刃山脈之雷霆王村的雷克薩說這件事。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10719 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10719, 'zhTW', '你拿到筆記了嗎?', '祭司完成了這份筆記，很明顯的是要交給監督者奴阿爾。上面由某個叫克菲斯·暗鱗的人簽了名。$B$B林木守衛蕭恩可能會對這本筆記很感興趣。', '將會見紙條交給劍刃山脈裡永恆樹林的林木守衛蕭恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10720 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10720, 'zhTW', '最小的動物', '那些巨魔們，儘管頭腦簡單的可以，還是會注意到你散播此毒劑於他們整個營地。因此，我將教你怎樣徵募自然界一種最小的生物來幫助你完成這項任務。$B$B藉由在這個鼓上奏出簡單的節奏，你能哄騙一隻土撥鼠遵循你的命令。$B$B往北邊走，進入匕爪峽谷穿過血之環，在血槌營地附近有一個土撥鼠的巢穴。一旦你獲得土撥鼠的幫助，利用它把毒散播到血槌的小桶子內。', '在土撥鼠的巢穴使用科多獸皮鼓。在控制土撥鼠後，在血槌營地的3只小桶裡下毒。當那完成時，返回劍刃山脈之雷霆王村的雷克薩那裡。', '', '', '對綠點烈酒桶下毒', '對成熟的月光酒桶下毒', '對發酵種子啤酒桶下毒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10721, 'zhTW', '葛魯洛克的豬時光', '$N，我有一頭寵物野豬名字叫胡佛。他想要幫助你去整整附近戈魯爾的兒子之一。$B$B葛魯洛克居住在一個稱為詛咒之谷的地方。當你到達那裡時，放開胡佛。那個古羅將有一段時間會在附近追趕胡佛，而你就取回他看守的一只袋子，並且把它交給沙伯邁恩男爵。$B$B想去詛咒之谷就由北邊的斜坡道向下走，並向東穿過飛龍之末。詛咒之谷在東方的邊界上。', '取得葛魯洛克的袋子，並且將它帶到劍刃山脈的血之環交給沙伯邁恩男爵。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10722, 'zhTW', '黑翼集會所的集會', '我知道該怎麼做!$N，你必須假扮成監督者奴阿爾參加這場會議!$B$B集會所裡的巨龍教徒都有一套標準的全套穿著，因此去收集他們不要的碎塊，在你湊足後，將它們拼成一個偽裝。$B$B假扮成監督者奴阿爾與克菲斯·暗鱗談話看看他有怎麼反應，然後回去找林木守衛蕭恩。$B$B你朝著龍骨隧道的方向順著路經過烏鴉林及葛瑞許納什到盡頭就會找到這個集會所了。', '從各個巨龍教徒身上收集足夠的戲服碎塊來做出一套監督者偽裝。使用這個偽裝來參加和克菲斯·暗鱗的會議，並將你的發現回報給劍刃山脈裡永恆樹林的林木守衛蕭恩。', '已出席與科菲斯·暗鱗的會面', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10723, 'zhTW', '食龍者柯爾葛羅姆', '我們尋找的古羅是柯爾葛羅姆，食龍者。由於沙伯邁恩的陷阱，你將可迅速解決掉古羅。你將發現他接受圓面之地巨魔們的獻祭。$B$B沿著來自血之環北方的道路，然後再向魯安曠野的西方。穿過隧道往西北去。$B$B首先，殺死巨魔們取下他們的頭。我們將送出一個訊息。在他的祭壇上設置陷阱。當他死掉時，在他身邊插入這可怕的圖騰 - 沒有一個人會誤解那訊息。$B$B做掉這魯莽的人。$B$B<米莎咆哮著。>', '去圓面之地並且從圓面巨魔那裡收集3個可怕圖騰。於柯爾葛羅姆的祭壇使用沙伯邁恩的陷阱，並召喚及殺死食龍者，柯爾葛羅姆。$B$B當柯爾葛羅姆死掉後，把3個可怕圖騰放置在他屍體附近，然後返回劍刃山脈之雷霆王村的雷克薩那裡。', '', '', '放置可怕圖騰', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10724, 'zhTW', '劍刃囚犯', '在我到達這些山之後不久，我受到一隊劍刃巨魔的攻擊。$B$B雖然我在與他們戰鬥中順利逃脫，並且殺死很多巨魔，但他們帶走了我的翼龍，里奧克，還把他關了起來。精靈們已經找到他，被關在戈魯爾之巢外劍刃營地中央的一只籠裡。$B$B其中的一個巨魔必定帶著鎖他的鑰匙。找到它，那精靈就能用它打開關里奧克籠子的鎖。$B$B你可以在下方匕爪峽谷的最北邊找到那些巨魔的營地。', '殺死劍刃巨魔取得雙足翼龍的牢籠鑰匙。取得鑰匙後，找到雙足翼龍的牢籠並且使用精靈之哨召喚打開籠子的精靈。在里奧克自由後，返回劍刃山脈的雷霆王村向雷克薩回報。', '', '', '', '', '拯救里奧克', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10725 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10725, 'zhTW', '紫羅蘭之眼中的地位', '你的服務已在對你的期望之上，$n。你離達成非達拉然居民所能獲得的最高榮譽只差一步。$B$B持續證明你對我們的忠誠，而我將賦予你的徽章它全部的能力。', '當你與紫羅蘭之眼的聲望到達崇拜後，將你的紫羅蘭印記交給逆風小徑的大法師利瑞達。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10726, 'zhTW', '紫羅蘭之眼中的地位', '你的服務已在對你的期望之上，$n。你離達成非達拉然居民所能獲得的最高榮譽只差一步。$B$B持續證明你對我們的忠誠，而我將賦予你的徽章它全部的能力。', '當你與紫羅蘭之眼的聲望到達崇拜後，將你的紫羅蘭印記交給逆風小徑的大法師利瑞達。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10727, 'zhTW', '紫羅蘭之眼中的地位', '你的服務已在對你的期望之上，$n。你離達成非達拉然居民所能獲得的最高榮譽只差一步。$B$B持續證明你對我們的忠誠，而我將賦予你的徽章它全部的能力。', '當你與紫羅蘭之眼的聲望到達崇拜後，將你的紫羅蘭印記交給逆風小徑的大法師利瑞達。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10728 AND `locale` = 'zhTW';
