INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10731, 'zhTW', '紫羅蘭刺客之路', '', '你對你的決定有把握嗎，$n?這可不是你可以隨便決定的事喔。紫羅蘭徽記會隨著力量而成長，只要你繼續對紫羅蘭之眼證明你自己。', '', '', '', '', '', '', 0);
