INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10733, 'zhTW', '遵循紫羅蘭之路', '你已經決定你要走的路了，$c。現在就由你去走這條不管目的為何處的路。$B$B你會發現有朋友在達拉然法師團裡有它的好處。好好跟我們相處你的功績就不會白費。', '當你與紫羅蘭之眼的聲望到達尊敬後，將你的紫羅蘭印記交給逆風小徑的大法師利瑞達。', '', '', '', '', '', '', 0);
