INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10737, 'zhTW', '大師之觸', '我把我還是學徒時的鑰匙組合好了。它看起來完全保有鑰匙的功能。不過，說到要開啟卡拉贊，這可能也只是一小塊金屬而已。$B$B沒有麥迪文的同意，這把鑰匙就沒有價值。是的，我當然知道麥迪文已死。這只是讓事情變的困難，但不是不可能。$B$B在艾澤拉斯有個地方叫時光之穴，由銅龍軍團守護著。想辦法進到裡面，穿過時光讓麥迪文賦予鑰匙能力。', '進入時光之穴說服麥迪文讓復原的初生之鑰恢復能力。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10738 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10738, 'zhTW', '傑出的表現', '你沒有讓我們失望，$n。不過，我們還是對你寄以高度的厚望。$B$B繼續效忠紫羅蘭之眼，你會得到應得的獎勵。', '當你與紫羅蘭之眼的聲望到達崇敬後，將你的紫羅蘭印記交給逆風小徑的大法師利瑞達。', '', '', '', '', '', '', 0);
