INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10742, 'zhTW', '攤牌', '終於到了。我們會把苟克從他的巢穴引出來，然後我們就會殺了他。隨著苟克一死，這些血錘巨魔就再也無法威脅摩克納薩爾了。到位於戈魯爾之巢外苟克的祭壇去，接著吹響我的號角。我會出現，跟你一起面對這個戈魯爾之子。', '在苟克祭壇上使用雷克薩的戰爭號角，接著殺掉苟克。完成任務後回到劍刃山脈的雷霆王村找雷克薩。', '', '去找劍刃山脈的雷克薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10743 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10743, 'zhTW', '[DEPRECATED]<txt>莫克納薩的英雄', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10744 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10744, 'zhTW', '勝利的消息', '你得馬上將我們成功的消息帶給庫德蘭·蠻錘!他的人民在空軍指揮官奴艾恩領導下不斷的戰鬥保衛蠻錘要塞的安全，你的歸來無疑會提高他們的士氣。隨著軍團的威脅不同以往，庫德蘭終於可將注意力轉移來解決伊利丹的軍隊。我們這裡的位置不好防守，不過我們今日贏得了一場大勝利。', '回到蠻錘要塞與庫德蘭·蠻錘談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10745 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10745, 'zhTW', '勝利的消息', '你必須馬上將我們成功的消息傳給歐巴洛卡赫霸主知道!如今我們已經擊潰了軍團並使他們在影月谷消聲匿跡，統治者就可以將注意力轉往我們其他的敵人身上。$B$B雖然柯爾克隆守衛不會承認，不過他們會很高興我們不用再到兩個前線上戰鬥了。', '回到影月村與歐巴洛卡赫霸主談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10746 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10746, 'zhTW', 'DEPRECATED Karazhan: LAB - E - Exalted Ring - Caster', '你的成就已經大大的超過我的預期，$N.$B$B你如同所有青銅龍般可以輕鬆的進出時空。你註定擁有巨大的力量，而我也非常榮幸能夠一路協助你得到它。$B$B繼續侍奉流沙之鱗，而我將釋放你天賦的充分潛能。', '當你的流沙之鱗聲望值到達崇拜之後帶著你的永恒指環給在時光之穴的索芮朵蜜。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10747 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10747, 'zhTW', '巨龍教團的幼龍', '我需要檢查生長在黑翼集會所的那些幼龍。$B$B那裡有一大群幼龍在洞穴裡外飛來飛去，同樣的也有為數不少的蛋，可能你一靠近就會孵化。$B$B$N，麻煩你拿著這個網子去活抓一堆幼龍給我。$B$B朝西前進越過龍骨橋或經過龍骨隧道可以找到它們。順著路一路經過葛瑞許納什及烏鴉林到盡頭去。', '沙彌亞·暗示者要你使用黑色幼龍網補抓10隻巨龍教團黑色幼龍。將這些幼龍帶到劍刃山脈的永恆樹林給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10748 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10748, 'zhTW', '麥克斯納爾必須要死!', '他們讓我們別無選擇，$N。是時候把黑翼集會所帶來的威脅做個了結了，殺掉他們的領導者，灰喉麥克斯納爾。$B$B我不知道你在那裡的時候有沒有瞥見他，但他是龍族的一員，半人半龍。而且他很強壯，所以不要低估了他!$B$B快點把它了結，幸運的話你就能保衛永恆樹林和魯安曠野的安全。', '代表永恆樹林的塞納里奧遠征隊的德魯伊，以及魯安曠野當地的生命，林木守衛蕭恩要你去殺掉灰喉麥克斯納爾。完成後回到劍刃山脈的永恆樹林找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10749 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10749, 'zhTW', '沙伯曼男爵的毒藥', '來，把這個拿給你的主人。我確定無論理由為何，雷克薩都會好好使用它。$B$B喔，記得提醒他，他欠我一次。$B$B他知道我要什麼，因此我相信不管如何他都會把東西交給我，我們會比你想像的還要更快再次見到面。$B$B現在，當個聽話的小<男孩/女孩>把這個送去給雷克薩吧。', '將沙伯曼男爵的毒藥送到劍刃山脈的雷霆王村給雷克薩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10750 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10750, 'zhTW', '征服之路', '我的雙足飛龍已經將消息傳送回來了，$n。伊克利普森血精靈們正在策畫大幹一場。他們已經開始在征服之路組織他們的軍隊，就在東北方遠處 - 緊連著日蝕崗哨。$B$B我要你到征服之路去了解狀況。一旦你完成後，使用這個信號槍向雙足飛龍發出信號。會有一隻雙足飛龍自天空俯衝而下與你會合。把你的發現告訴他們，他們會給你下一個指令。', '前往影月谷的征服之路。一旦你完成這一區的初步偵察後，使用柯爾克隆信號槍對柯爾克隆飛龍騎士發送信號。萬一你遺失了你的柯爾克隆信號槍就跟歐巴洛卡赫霸主談談，他會給你一個替代品。', '偵查征服之路', '使用庫卡隆訊號槍召喚一名庫卡隆馭風者。$B$B如果你不慎丟失了庫卡隆訊號槍，可以問奧巴洛恩大王另要一支。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10751 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10751, 'zhTW', '突破道路', '我們需要多一點的時間，$r。我會讓其他的雙足飛龍飛到更前面一點的地方去。但願我們能夠收集到更多的資訊。現在我需要你去做得就是清出一條路來還有更重要的是，引開他們對我們的注意力!$B$B一旦你削減了他們的人數後就使用這個柯爾克隆信號槍呼叫一隻雙足飛龍。', '殺掉20個伊克利普森士兵，10個伊克利普森騎士，以及10個伊克利普森縛法者，接著使用柯爾克隆信號槍發送信號給柯爾克隆飛龍騎士回去回報任務完成。萬一你遺失了你的柯爾克隆信號槍的話可以找影月谷裡影月村的歐巴洛卡赫霸主談談，他會給你一個替代品。', '', '使用庫卡隆訊號槍召喚一名庫卡隆馭風者。$B$B如果你不慎丟失了庫卡隆訊號槍，可以問影月谷內影月村的奧巴洛恩大王另要一支。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10752 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10752, 'zhTW', '前進梣谷', '最近萊恩·狼行者從達納蘇斯經過奧伯丁而來，朝著梣谷前進;他提到跟熊怪有關的事情。我沒有機會去問她的情況如何但是也許你可以去找她並且提供協助$C。順著奧伯丁的南部道路走。一旦你到達梣谷邊界繼續順著路走。你會在那邊找到阿斯特蘭納還有萊恩·狼行者。', '在阿斯特蘭納跟萊恩·狼行者談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10753 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10753, 'zhTW', '搶救自然', '燃燒軍團所犯下的暴行不記其數。即使在我們對話的同時，他們也派出燃燒軍團部隊對付外域的生物們。無力抵抗燃燒軍團的力量，外域的生物們一個接一個的倒下。$N，幫助我停止他們這些破壞自然的罪行。$B$B越過山丘往東邊去，你會看到燃燒軍團的破壞已經遍及整個刀刃峽谷了。殺死犯下這些罪行的元兇，惡魔墮落者，還有盡可能殺死越多的魔誓越好。', '殺死4隻魔誓鱗翼，4隻魔誓匕爪還有2隻惡魔墮落者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10754 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10754, 'zhTW', '進入堡壘', '這新開鑄模是用來鑄造某種鑰匙的。從這幅雕在它背面的圖像來看，它看起來與地獄火有關。$B$B也許這能引起榮譽堡部隊指揮官，達納斯的興趣。', '將原始鑰匙模子帶去給地獄火半島上榮譽堡的軍隊指揮官達納斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10755 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10755, 'zhTW', '進入堡壘', '這新開鑄模是用來鑄造某種鑰匙的。從這幅雕在它背面的圖像來看，它看起來與地獄火堡壘有關。$B$B也許這能引起部落在索爾瑪的領導人，納茲格雷爾的興趣。', '將原始鑰匙模子帶去給地獄火半島上索爾瑪的納茲格雷爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10756 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10756, 'zhTW', '大師洛赫克', '這鑰匙柄的符號……很難在鑄模裡做出來，但是我認出它為破碎之手所有。$B$B這是個好機會，這把鑰匙能讓你進入破碎大廳。$B$B與我們當地的鐵匠，洛赫克談談。如果有任何人能鍛造出這把鑰匙，那一定是他。', '將原始鑰匙模子帶去給索爾瑪的洛赫克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10757 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10757, 'zhTW', '洛赫克的請求', '魔獄獸人鐵匠可能不是世界上最熟練的鐵匠，但是他們的工藝技術卻也算不錯。如果我們想要以一把有用的鑰匙的話，只有魔鐵能被用於這個鑄模 - 其它任何東西或許最後終將毀壞它。$B$B帶一些魔鐵錠，一點魔塵和火焰微粒來給我。我會試著把它做出來，但是我不保證能成功。', '帶4個魔鐵錠，2個魔塵和4個火焰微粒回到地獄火半島的索爾瑪交給洛赫克。', '', '去地獄火半島找索爾瑪的羅霍克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10758 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10758, 'zhTW', '比地獄還熱', '沒有用，$n!不管我放多少煤炭到火裡，它就是不夠熱。$B$B只有一樣東西我能想到有足夠的熱度可以加溫這把鑰匙，而它是在軍團的惡魔搶奪者裡面。$B$B我曾經看見過有一個被擊倒，就那麼一次。我記得當它落下時，有看見它裡面在冒煙、射出火焰和蒸汽。帶著這個鑄模，並將它進入倒下的惡魔搶奪者。如果你計畫打倒一個，我建議你一起帶些朋友去。', '在地獄火半島破壞一部惡魔搶奪者，並且將未淬火的鑰匙模插入它的殘骸裡。將燒焦的鑰匙模型帶到洛赫克給索爾瑪。', '', '去地獄火半島找索爾瑪的羅霍克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10759 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10759, 'zhTW', '找出背棄者', '我覺得全部的碎片都在這裡，但是我就是不能有效的將它們都拼湊在一起。$B$B我認為我們的最好的方向是去努力找出日記中所提到的背棄者。如果他將他的同志遺棄在營地的話，我想你會有機會去說服他幫助我們了解黑暗議會阿拉卡正在計畫些什麼。$B$B在西北方的熔岩平原道路上開始找尋他吧。', '在熔岩平原上找到帕莎並與他交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10760 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10760, 'zhTW', '史凱瑟隆殘骸', '史凱瑟隆殘骸，就在東方，是一個令人恐懼的地方。那些勞役確信它被詛咒了。$B$B這裡的樹很少，所以勞役們別無他法只有冒險進入阿拉卡廢墟伐木。阿拉卡精靈折磨工作團，吸取他們的生命，並且用它去增強他們的邪惡魔力。$B$B我們必須查明什麼正驅策著黑暗議會，並在他們的影響擴大之前制止他們。為他們計畫的證據搜尋史凱瑟隆殘骸吧。', '自史凱瑟隆殘骸的黑暗議會阿拉卡身上取回史凱瑟隆指揮官日誌 - 第一頁，史凱瑟隆指揮官日誌 - 第二頁，和史凱瑟隆指揮官日誌 - 第三頁交給影月村的卡古爾中士。', '', '去影月谷找影月村的卡格魯爾中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10761, 'zhTW', '找出背棄者', '這裡沒有什麼可以解釋為什麼阿拉卡的精靈依然存在在這世界中，或是他們為什麼那麼渴望獸人的血。$B$B我認為我們的最好的方向是去努力找出日記中所提到的背棄者。如果他將他的同志遺棄在營地的話，我想你會有機會去說服他幫助我們了解黑暗議會阿拉卡正在計畫些什麼。$B$B在東南方的熔岩平原道路上開始找尋他吧。', '在熔岩平原上找到帕莎並與他交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10762, 'zhTW', '戴夫利大師', '這鑰匙柄的符號……很難在鑄模裡做出來，但是我認得它為破碎之手所有。$B$B很有可能，這把鑰匙將讓你進入破碎大廳。$B$B與戴夫利談談。他精通他的工藝。如果他不能為你製作這把鑰匙，那將沒有人能。', '將原始鑰匙模子帶去給榮譽堡的戴夫利。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10763 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10763, 'zhTW', '戴夫利的請求', '魔獄獸人們雖然可以說是完全的野蠻人，但是他們的鍛造技術沒有你想像的那麼原始。如果我們想要以一把有用的鑰匙的話，只有魔鐵能被用於這個鑄模 - 其它任何東西或許最後終將毀壞它。$B$B帶一些魔鐵錠，一點魔塵和火焰微粒來給我。我會試著把它做出來，但是我不保證能成功。', '帶4個魔鐵錠，2個魔塵和4個火焰微粒回到地獄火半島的榮譽堡給戴夫利。', '', '去地獄火半島找榮耀堡的達姆菲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10764 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10764, 'zhTW', '比地獄還熱', '沒有用，<少年/少女>。我不能給它足夠的熱氣……材料無法被正確地加溫。$B$B你知道的，燃燒軍團使用的惡魔搶奪者們是以滾燙之魔化火焰的核心提供動力的 - 它燃燒所產生的溫度比一般的火焰熱得多。$B$B假如你能找到足夠的人取得一個，你就能在倒下的搶奪者裡面加熱鑄模。注意，$c，那些惡魔搶奪者們幾乎都是成群結隊的。', '在地獄火半島破壞一部惡魔搶奪者，並且將未淬火的鑰匙模插入它的殘骸裡。將燒焦的鑰匙模型帶到榮譽堡給戴夫利。', '', '去地獄火半島找榮耀堡的達姆菲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10765 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10765, 'zhTW', '當世界衝突時……', '在征服之路的南端，一支定居商隊附近，我發現了一個看起來像是一個巨人和一位血精靈大法官間的會議。巨人在這裡做什麼?這感覺有點不對勁，蠻兵。$B$B我要你排除任何的困難前往會議地點，並且結束它。取得會議中任何可能發現的東西，然後以信號槍通知我們。', '殺掉大法官血葉和偉大的科羅克，並取回伊利丹的命令。一旦你已經完成這項任務，使用柯爾克隆信號槍發出信號通知柯爾克隆飛龍騎士。萬一你失去你的柯爾克隆信號槍，與影月谷之影月村的歐巴洛卡赫霸主交談，並要求代替品。', '', '使用庫卡隆訊號槍召喚一名庫卡隆馭風者。$B$B如果你不慎丟失了庫卡隆訊號槍，可以問影月谷內影月村的奧巴洛恩大王另要一支。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10766 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10766, 'zhTW', '侵略點:災難', '目前我們已經進入軍團在侵略點:災難的基地，我們需要想出一種方式去停止它們在這的運作。蠻錘要塞將不會是安全的，除非軍團被趕出山谷。$B$B我已經送一隊先遣隊到侵略點幫助你擬定一個計畫去破壞軍團的補給。回去軍團要塞並踏進上方有綠色水晶的傳送器。普萊克希將在你的目的地與你見面。', '在侵略點:災難向普萊克希報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10767 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10767, 'zhTW', '侵略點:災難', '目前我們已經進入軍團在侵略點:災難的基地，我們需要想出一種方式去停止它們在這的運作。影月村將不會是安全的，除非軍團被趕出山谷。$B$B我已經送一隊先遣隊到侵略點幫助你擬定一個計畫去破壞軍團的補給。回去軍團要塞並踏進上方有綠色水晶的傳送器。那卡西將在你的目的地與你見面。', '在侵略點:災難向那卡西報告。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10768 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10768, 'zhTW', '伊利達瑞的外袍', '飛龍騎士必須返回影月村為我們突擊的下一個階段作準備。我現在需要你的是這些血精靈所穿的外袍。$B$B當你收集了足夠的外袍時，使用柯爾克隆信號槍召喚飛龍騎士。準備好做點間諜行動吧，$r!', '收集10件伊利達瑞外袍，然後使用柯爾克隆信號槍發出信號給另一名飛龍騎士。萬一你失去你的柯爾克隆信號槍的話，與影月谷裡影月村的歐巴洛卡赫霸主交談，並要求代替品。', '', '使用庫卡隆訊號槍召喚一名庫卡隆馭風者。$B$B如果你不慎丟失了庫卡隆訊號槍，可以問影月谷內影月村的奧巴洛恩大王另要一支。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10769 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10769, 'zhTW', '行列中的歧見……', '研究員提歐魯斯體貼的為了最後的攻擊把這混合物放在一起。我只是在這件你給我的外袍上傾注它，而這件外袍被注滿了伊利達瑞骯贓的精華。$B$B拿著這件施過法的外袍，並且旅行到伊克利普森農場，在日蝕崗哨的西南邊。一旦到了那裡，使用這件外袍轉變成一位伊利丹的代理人。在裝扮期間，殺了在原野徘徊之發狂的戈羅西。他們將認為那是伊克利普森所做的攻擊，而切斷全部關係!', '在偽裝為伊利丹的代理人時，殺掉5個瘋狂的巨像，並且返回影月谷的影月村向歐巴洛卡赫霸主回報。同時將他的柯爾克隆信號槍交還給他。', '', '去影月谷找影月村的奧巴洛恩大王。', '在偽裝狀態下殺死瘋狂的巨人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10770 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10770, 'zhTW', '一些餘燼', '這裡東北方在我們上方的高原上躺著我老家之被燒盡的灰。在燃燒軍團派他們的灼熱小鬼去燒盡我們之前，有一大片森林在那些繁盛。在過了如此多個死寂的世紀後，我疲倦而老去的心甚至仍然渴望復仇。有太多敵人了以致於不能收復土地，但是你能使他們害怕。$B$B確定你願意幫助我?', '苔木長老想要你殺死8個灼熱小鬼，然後返回魯安曠野找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10771 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10771, 'zhTW', '來自灰燼', '如果你沿著東方的道路並上到山的側面，然後轉向北方，那你將會來到我長期失去的家。曾經在那裡有一棵樹。我早已忘記它的名字了。很久以前燃燒軍團召喚灼熱小鬼和其他火焰生物。我的家就被毀滅了，而我的族人逃離了。現在只有我留下來。$B$B我已經保存了一些可以在肥沃的火山土壤種植的鐵樹根種子。他們的魔力是強大的。為我做這件事，而我將與你同享一批被遺忘已久的財寶。', '苔木長老想要你旅行至斯卡德，並將鐵根種子種植在三座不同的肥沃的熔岩泥土內，然後返回魯安曠野到他那裡。', '', '', '南方火山泥土', '中央火山泥土', '北方火山泥土', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10772 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10772, 'zhTW', '征服之路', '我的獅鷲騎士已經帶了一點消息回來了!伊克利普森血精靈們正在進行大計畫。他們已經開始在征服之路集結他們的軍隊，位於這裡的東邊 - 鄰接日碩崗哨。$B$B我想要你旅行到征服之路並且評估情勢。完成之後使用這隻信號槍發送信號通知獅鷲騎士。獅鷲騎士將從天空俯衝下來與你會面。告訴他們你發現了什麼，他們將給你下一步命令。', '旅行到影月谷的征服之路。一旦你完成這地區的初步評估，使用蠻錘信號槍發出信號通知另一位蠻錘獅鷲騎士。萬一你失去你的蠻錘信號槍，與影月谷之蠻錘要塞的賽恩尼·憂瑞卡爾交談，並要求代替品。', '偵查征服之路', '使用蠻錘訊號槍召喚一名蠻錘獅鷲騎士。$B$B如果你不慎丟失了蠻錘訊號槍，可以問影月谷內蠻錘要塞的大領主尤雷加爾另要一支。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10773 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10773, 'zhTW', '突破道路', '我們需要更多的時間，$r。我將要與一些其他的獅鷲騎士飛越前方。希望，我們能收集更多的情報。我現在需要你清出一條通道，而更重要的，使他們的箭遠離我們!$B$B一旦你削弱他們的人數，使用蠻錘信號槍召喚一名獅鷲騎士。', '殺死20名伊克利普森士兵，10名伊克利普森騎士，和科難lJ的5個兒子，然後使用蠻錘信號槍發出信號通知另一名蠻錘獅鷲騎士報告你任務完成。萬一你失去你的蠻錘信號槍，與影月谷之蠻錘要塞的賽恩尼·憂瑞卡爾交談，並要求代替品。', '', '使用蠻錘訊號槍召喚一名蠻錘獅鷲騎士。$B$B如果你不慎丟失了蠻錘訊號槍，可以問影月谷內蠻錘要塞的大領主尤雷加爾另要一支。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10774 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10774, 'zhTW', '血精靈 + 巨人 = ？？', '在征服之路的南端，一支定居商隊附近，我發現了一個看起來像是一個巨人和一位血精靈大法官間的會議。巨人在這裡做什麼?這感覺有點不對勁，蠻兵。$B$B我要你排除任何的困難然後去到該會議，並且結束它。從會議中取得任何你能找到的東西，然後以信號槍召喚我們其中一個。', '殺掉大法官血葉和偉大的科羅克，並取回伊利丹的命令。一旦你完成這項任務，使用蠻錘信號槍發出信號通知另一個蠻錘獅鷲騎士。萬一你失去你的蠻錘信號槍，與影月谷之蠻錘要塞的賽恩尼·憂瑞卡爾交談，並要求代替品。', '', '使用蠻錘訊號槍召喚一名蠻錘獅鷲騎士。$B$B如果你不慎丟失了蠻錘訊號槍，可以問影月谷內蠻錘要塞的大領主尤雷加爾另要一支。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10775 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10775, 'zhTW', '伊利達瑞的外袍', '獅鷲騎士必須返回蠻錘堡壘為我們突擊的下一個階段作準備。我現在需要你的是這些血精靈所穿的外袍。$B$B當你收集了足夠的外袍時，使用蠻錘信號槍召喚獅鷲騎士。準備好做點間諜行動吧，$r!', '收集10件伊利達瑞外袍，然後使用蠻錘信號槍發出信號給另一名蠻錘獅鷲騎士。萬一你失去你的蠻錘信號槍的話，與影月谷之蠻錘要塞的賽恩尼·憂瑞卡爾交談，並要求代替品。', '', '使用蠻錘訊號槍召喚一名蠻錘獅鷲騎士。$B$B如果你不慎丟失了蠻錘訊號槍，可以問影月谷內蠻錘要塞的大領主尤雷加爾另要一支。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10776 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10776, 'zhTW', '行列中的歧見……', '葛諾瑪斯體貼的為了最後的攻擊把這混合物放在一起。我只是在這件你給我的外袍上傾注它，而這件外袍被注滿了伊利達瑞骯贓的精華。$B$B拿著這件施過法的外袍，並且旅行到伊克利普森農場，在日蝕崗哨的西南邊。一旦到了那裡，使用這件外袍轉變成一位伊利丹的代理人。在裝扮期間，殺了在原野徘徊之發狂的戈羅西。他們將認為那是伊克利普森所做的攻擊，而切斷全部關係!', '在偽裝為伊利丹的代理人時，殺掉5個瘋狂的巨像，並且返回影月谷之蠻錘要塞的賽恩尼·憂瑞卡爾那裡。同時將他的蠻錘信號槍交還給他。', '', '去影月谷找蠻錘要塞的大領主尤雷加爾。', '在偽裝狀態下殺死瘋狂的巨人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10777 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10777, 'zhTW', '阿斯格的圖騰', '你在指揮官日誌裡讀到的是真實的。當獸人部落 在古爾丹下方聚集時，我的族人想辦法對抗他以保衛我們免受威脅。古爾丹獲悉他們的意圖，並且施下毀滅我們陣營和扭曲我兄弟靈魂的一種強大咒語。在他們釋放出更大的惡魔之前，$B$B他們必須被制止。在北方的史凱瑟隆殘骸裡，找尋阿斯格並且將他所攜帶的圖騰帶來給我。有了它，我們就能開始阻礙黑暗議會的計畫。', '將史凱瑟隆戰爭圖騰帶給熔岩平原的帕莎。', '', '去影月谷找熔岩平原的帕沙恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10778 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10778, 'zhTW', '利安瑟魔棒', '單單圖騰不夠強大得足以抵消黑暗議會的邪惡魔力。$B$B我們將它與其他物體的力量結合起來，做成一個權杖以集中能量。我們無法從他們墮落的最深處中拯救出我的諸兄弟，但是我們能制止他們。$B$B為此權杖，我需要的項目之一是利安瑟魔棒，它被東南方日蝕崗哨的血精靈所持有。它被放在廢墟最高層上的一座亭子裡，並且被重重保衛。小心，$n。', '從任何在日蝕崗哨的血精靈身上取得利安瑟的鑰匙，並用它打開利安瑟的保險箱並且取去利安瑟魔棒。返回熔岩平原將魔棒交給帕莎。', '', '去影月谷找熔岩平原的帕沙恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10779 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10779, 'zhTW', '獵人之道', '你好，年輕的獵人。我看你好像熟練得足以對付一隻野獸，並且訓練它成為你的同伴。$B$B你應該到LOCATION見見女獵人凱拉·夜弓。她能教你如何獲得自己的寵物。', '與LOCATION的女獵人凱拉·夜弓談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10780 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10780, 'zhTW', '史凱瑟隆羽毛', '這權杖還欠缺最後一種元素。我們必須把權杖的能力導引向黑暗議會幽靈。$B$B我們能透過收集散佈在史凱瑟隆營地地上的羽毛並且在權杖裡使用他們去完成那件事。營地位於南方，在蠻錘要塞的東方。$B$B古爾丹的魔法完全毀滅了我的諸兄弟，只留下他們的靈魂，但是不只這樣。魔法以阿拉卡所準備的咒語為食，創造出一種吞沒靈魂的邪惡力量。', '收集8根史凱瑟隆羽毛，並且把他們帶到在熔岩平原給帕莎。', '', '去影月谷找熔岩平原的帕沙恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10781, 'zhTW', '赤紅守望的戰鬥', '當我們在對話時，他們或許正在征服之路尋找你。你必須逃跑，$r!$B$B留下我，我已經準備好了……他們……我想我聽到他們來了。機不可失，時不再來!走吧!如果你選擇留下，你必須戰鬥!$B$B如果你戰鬥，並且設法存活的話，帶著你在這裡學會的，並且把那知識告知給撒塔斯城的阿達歐。', '在赤紅守望的戰鬥與伊利丹的軍隊戰鬥，並且存活下來!一旦你勝利，回到在撒塔斯城的阿達歐那裡。', '消滅火色魔印的軍隊', '去泰羅卡森林找撒塔斯城的阿達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10782, 'zhTW', '浸注權杖頭', '權杖差不多要完成了!$B$B剩下的是讓權杖頭充滿流自這個被詛咒地方之古爾丹回聲的力量。向東走，靠近惡魔深淵和在死亡熔爐的南方附近，是詛咒祭壇。$B$B在那裡，古爾丹昔日的碎片被困住。當你攜帶這權杖之未完成的頭部進入祭壇周遭地區時，假如有一些事物回應它時不要驚嚇到。你正攜帶一個與災變有強大連結關係而又非常危險的物體。', '裝備未完工的權杖頭，旅行到詛咒祭壇，並在靠近古爾丹時使用它。當權杖頭被灌注能量之後，返回在熔岩平原的帕莎那裡。', '', '去影月谷找熔岩平原的帕沙恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10783, 'zhTW', '沙伯邁恩男爵', '我的計畫是。我們毒害巨魔們，然後消滅他們的古羅主人。在我於這些山中旅行期間，我遇見一個名為沙伯邁恩男爵的人。他精通鍊金術，且可確信會幫助我們。你可以在這裡北邊峽谷下方的血之環那裡找到他。無論他需要什麼代價，都由你來判斷是否接受。', '與在劍刃山脈之血之環的沙伯邁恩男爵談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10784 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10784, 'zhTW', '粉碎血槌營地', '<吐查克傾身接近低聲地說。>$B$B$N，你到目前為止對我們所做的比與巨魔戰鬥還要自豪。而當我對雷克薩所計畫的有信心時，我將依舊要求你在返回之前，粉碎血槌營地的巨魔們。$B$B那樣我們將加倍確信結果。$B$B要到那裡，向北走，走下雷霆王村外面的斜坡道。然後，在斜坡道底部，向西走越過飛龍之末，並向北穿過翻騰峽谷和匕爪峽谷。', '吐查克·雙爪要求你殺死10個血槌槌兵和5個血槌術士。之後，返回到劍刃山脈之雷霆王村的他那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10785 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10785, 'zhTW', '它是一個陷阱!', '在這個世界沒有其他原因能比戈魯爾和他兒子們更能令我憎惡!他們屠殺我的族人-我的孩子-現在我將嚐到報仇的滋味!$B$B我已經利用龍火做成一個陷阱，如果你夠聰明的話，你甚至可以使用它來殺死古羅。$B$B快一點就對了，把陷阱拿給雷克薩。$B$B我渴求報仇的火焰必須要被撲滅!', '將龍火陷阱交付給劍刃山脈之雷霆王村的雷克薩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10786, 'zhTW', '圓面之地大屠殺', '我知道雷克薩有計畫要你向圓面之地前進。當你到那裡時，我有一些想要你去做的事情。$B$B我們必須把握任何能打倒這些山上的巨魔的機會，否則他們將佔領我們，這樣我們就會流血並且無意義的死去!$B$B圓面之地位於西北方遠處。向北走到魯安曠野，然後從那裡走向西邊，穿過隧道並通過烏鴉林。$B$B$N，我想要你殺掉圓面之地的劍刃巨魔們。徹底消滅他們!', '屠殺5個劍刃蠻卒和3個劍刃薩滿，然後返回劍刃山脈之雷霆王村的吐查克·雙爪那裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10787, 'zhTW', '飛龍之末的龍', '如果我們要面對他，我們必須做些會激怒苟克的事情。\\r\\n\\r\\n現在你釋放了&&&，我想我知道要做什麼了!\\r\\n\\r\\n當你準備好時，讓我知道，而我將要求&&&載你飛到其中一個被刺穿在飛龍之末岩石上的龍的屍體處。\\r\\n\\r\\n取回屍體，並把它帶回來這裡給我，這樣我們就能創造一些必定可將苟克從隱藏中帶來出來的東西!', '雷克薩已經要求你跟他講關於騎乘&&&出去到飛龍之末去收回一具黑龍屍體的事。當你收回屍體時，返回到劍刃山脈之雷神要塞的他那裡。', '', '到劍刃山脈的劍刃庭園找雷克薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10788, 'zhTW', '返回塔萊妮亞那裡', '你的主人之一，塔萊妮亞，在銀月城裡等待著你了，$n。我想是時候你學習召喚和控制更強大的惡魔了，因此我建議你立刻去見她。我知道可沿著兇殺路找到一個舒適的邪惡小窩，密室，並在那裡找到塔萊妮亞。', '與銀月城的塔萊妮亞交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10789, 'zhTW', '返回凱倫丁·哈加爾那裡', '啊，原來你在這，$n。$B$B凱倫丁·哈加爾已放話要你去幽暗城的魔法區見他。他的耐性可是不太好，因此你最好不要讓他久等。', '與幽暗城的凱倫丁·哈加爾交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10790, 'zhTW', '返回甘盧爾·血眼那裡', '你離家很遠了，$r。或許是你回去向你的主人甘盧爾·血眼學習的時候了。他知道我們所有工藝的知識，即使是這裡我們所熟知那些。$B$B甘盧爾居住在奧格瑪的暗影之穴。', '與奧格瑪的甘盧爾·血眼交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10791, 'zhTW', '歡迎狼魂', '我已經差不多完成我將在儀式期間穿的法衣了。當我加上最後的裝飾時，我要你將薰香設置在我左邊符文石附近的蠟燭旁。$B$B我相信它將幫助我們吸引狼魂的注意，畢竟它是過去獸人氏族所做的。我幾乎能想像我的祖先在一次成功的打獵之後，用它在儀式中向狼魂獻上崇敬。$B$B一旦你已經安置好薰香，我就開始儀式。', '在瑪魯卡茲的小屋裡蠟燭附近使用典禮薰香並且觀察儀式。當儀式完成的時候，再次與瑪魯卡茲交談。', '', '去泰羅卡森林找碎石堡的瑪魯卡茲。', '', '幫助瑪魯卡茲召喚狼之魂', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10792, 'zhTW', '薩斯葛爾必須被燒毀!', '血之谷氏族已經背叛了他們的高貴傳統!我們獸人奮戰並誓死保護自己免於瑪諾洛斯的惡魔感染，望向我們卑鄙的親戚只看見軟弱和卑賤……因此，他們必須被燒死!$B$B進入他們在東方的堡壘，薩斯葛爾並燒毀他們的建築。殺死苦工取有他們的火炬，在他們的熔爐點燃火炬，並且向他們的茅舍、他們的馬棚和他們的兵營投擲燃燒的火炬。燒光他們，然後返回我這裡!$B$B為部落而戰!', '殺死血之谷苦工奪走他們的火炬，在薩斯葛爾熔爐點燃他們，然後把燃燒的火炬丟到薩斯葛爾建築物裡。', '', '去地獄火半島找斷脊氏族崗哨的達克霍爾上尉。', '燒燬兵營', '燒燬東部小屋', '燒燬西部小屋', '燒燬獸欄', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10793 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10793, 'zhTW', '弗札克的日記:戰爭警告', '這本日記記錄了伊利丹軍隊最近的活動。它也解釋了為什麼弗札克正在征服之路到處遊行。他親自負責捕捉一位薩塔的高階將軍。$B$B這位將軍目前被拘禁在一處名為赤紅守望的兵營，位於征服之路的南端。有一個自稱為赤紅法印的神秘團體負責監禁他。如果你選擇進行調查，帶些盟友是聰明的。', '在赤紅守望找到馬克斯·阿瑞利恩，薩塔的高階將軍。他位在一個水晶的監牢裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10794, 'zhTW', '破碎之手盜賊', '$n，在這世界上還有我們不知道的秘密。奧格瑪的破碎之手能讓你了解這些秘密的其中之一:釀造致命毒藥的方法。按他們要求的去做，你將獲得他們的信任。$B$B要到奧格瑪，就走銀月城通往幽暗城的大門。然後到城市外找到哥布林飛船在附近接載乘客的哨塔。從那裡飛往奧格瑪，你就能發現暗影裂口裡的申蘇爾。', '到奧格瑪與申蘇爾交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10795 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10795, 'zhTW', '與多爾哥克的約會', '非常好，我已經看見你在附近，我一直有一些重要的事情想對你講。$B$B有報告說由於某些原因，血槌巨魔計畫對希爾瓦納和魯安曠野發動攻擊。我們不知道是誰或者什麼東西在催促他們做這事，但是我打算趁早摧毀他們的計畫!$B$B攻擊將從血槌營地開始。沿著魯安曠野外面斜坡道向西北走下去，你就會找到它。我要你殺死他們的領導人，多爾哥克!', '指揮官海法斯·石牆要你殺死血槌營地的多爾哥克。在你完成之後，返回劍刃山脈的永恆樹林找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10796, 'zhTW', '粉碎血槌營地!', '我聽說你到目前為止對我們所做的比與巨魔戰鬥還要自豪。現在，我將要求你再次面對他們。我要你摧毀血槌營地的巨魔!$B$B要去那裡，就從魯安曠野外的斜坡往西北方走下去。你將在斜坡道的底部找到他們。$B$B祝你好運，$c!', '中尉費爾威德要你殺死10個血槌槌兵和5個血槌術士。之後，返回劍刃山脈的永恆樹林找她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10797 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10797, 'zhTW', '古羅的支持', '一個小雕像標誌從多爾哥克死亡的爪子上掉下來。它與某個古羅有明顯的相似處。$B$B想必斜坡上往東，魯安曠野的永恆樹林有個指揮官海法斯·石牆會對這東西感興趣!', '將柯爾葛羅姆的徽章帶到劍刃山脈的永恆樹林交給指揮官海法斯·石牆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10798, 'zhTW', '拜訪男爵', '這是個壞消息。食龍者柯爾葛羅姆是最近對抗希爾瓦納血槌計畫的幕後主使者!為什麼他在操縱他們，而不只是利用劍刃，我不知道。但如果我們要對付古羅，我們就需要幫助。我認識一個精通各種奇特魔法的人。他的名字叫沙伯邁恩男爵，你可以在血之環找到他，回到西北邊的斜坡下，再往西南方通過峽谷。請他幫我們製作一個給古羅的陷阱。', '和沙伯邁恩男爵談談關於製作陷阱的事。他就在劍刃山脈的血之環。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10799 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10799, 'zhTW', '進入翻騰峽谷', '非常好，我會製作這個陷阱，但我要先得到一些東西。$B$B附近有個古羅剛好有我要的物品，但你不能挑戰他，還不能。$B$B所以，我們要用附近的地殼穿刺者毒藥製造出一種睡眠粉末。$B$B你可以在西南邊的翻騰峽谷找到他們。幫我帶一堆他們的腺體來，而且動作要快!', '沙伯邁恩男爵要你幫他帶來7份地殼穿刺者毒腺。等你取得它們後回到劍刃山脈的血之環找他 。', '', '去刀鋒山找鮮血之環的薩博邁恩男爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10800 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10800, 'zhTW', '晚安，古羅', '我已經再次勝過自己。我已經為你製作了熟睡粉末，去用在葛魯洛克身上，那個我談到正守衛著我想要之東西的古羅。$B$B葛魯洛克一直在詛咒之谷，一個在血之環另一邊，飛龍之末東方邊緣的地區。$B$B如果我是你，一旦得到他的大袋子，我將不會再耽擱。灰塵的效果不會持續多久。', '沙伯邁恩男爵要你去偷葛魯洛克的袋子，然後將它帶回劍刃山脈的血之環給他。', '', '去刀鋒山找鮮血之環的薩博邁恩男爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10801, 'zhTW', '它是一個陷阱!', '與戈魯爾的兒子和他們的父親相比較，在這個世界上沒有事物能令我更加憎恨!他們屠殺我的族人和我的孩子，現在我將嚐到報仇的滋味!$B$B我已經由一些龍火作成一個陷阱，如果你足夠聰明的話，你正好可以使用它來殺死古羅。$B$B我確信你有屬意的古羅;而我不在意你殺死哪一個。就是快一點，將陷阱拿給你的石牆指揮官。$B$B我渴求報仇的火焰必須用水熄滅!', '把龍火陷阱帶到劍刃山脈的永恆樹林交給指揮官海法斯·石牆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10802, 'zhTW', '食龍者柯爾葛羅姆', '我們必須讓巨魔看看我們不是好欺負的。我們必須送出一個訊息。$B$B到圓面之地殺死那裡的巨魔。把他們的頭帶回來。$B$B然後去柯爾葛羅姆的祭壇，並且為他在那裡佈下陷阱。柯爾葛羅姆將會出現，而你必須誘騙他進入陷阱。當他死掉時，在他的屍體附近裝好你的可怕圖騰，以便巨魔能見他們倒下的主人和兄弟，並且知道想毀滅我們所需付出的代價。', '去圓面之地從圓面巨魔那裡收集3種可怕圖騰。在柯爾葛羅姆的祭壇使用沙伯邁恩的陷阱來召喚並殺死食龍者柯爾葛羅姆。$B$B當柯爾葛羅姆死掉時，把3種可怕圖騰放置在他的屍體附近，然後返回劍刃山脈的永恆樹林找指揮官海法斯·石牆。', '', '', '設置可怕圖騰', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10803 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10803, 'zhTW', '圓面之地大屠殺', '我知道我們有讓你向圓面之地前進的計畫。你去那裡的時候，我有些事情想要你去做。$B$B我們必須掌握任何能打倒這些山裡的巨魔的機會，否則他們將征服我們，這樣我們就會流盡鮮血無意義的死去!$B$B圓面之地位於西邊。走到西南方，越過橋並穿過隧道。在烏鴉林的西邊可以找到他們。$B$B$N，我想要你清除圓面之地的劍刃巨魔。', '屠殺5個圓面蠻卒和3個圓面薩滿，然後返回劍刃山脈的永恆樹林找中尉費爾威德。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10804, 'zhTW', '好心', '有東西控制住他們了，$r。$B$B<摩德奈指著頭頂飛翔的虛空龍。>$B$B他們連飛下來吃飯都不肯。我看過幾隻掉到地上，在他們的身體撞擊到地面前就因為過度疲勞而死亡了。$B$B我們一定要救救他們!在水晶附近可以找到的石釘鐮奪怪是他們天生的獵物。殺死鐮奪怪並帶走他們的屍體。把一個屍體放在農場上，然後站著動也不動。只要你不做出任何攻擊性的動作，他們就不會攻擊你。', '影月谷，虛空之翼農場的摩德奈要你餵食8隻成熟的虛空之翼龍。', '', '去影月谷找靈翼平原的莫德奈。', '餵養成熟的靈翼幼龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10805, 'zhTW', '戈魯爾之巢大屠殺', '你已經證明你是足智多謀的，現在我想要請你加入我與戈魯爾和他的兒子間的戰鬥。$B$B劍刃家族擁護古羅，當你在別處消減他們的數量時，你還沒有對付到他們最強大的力量。$B$B戈魯爾只用最強壯的巨魔保護他的巢穴外部，而那些就是你必須殺死的人。往北走穿過匕爪峽谷，然後你就會在盡頭發現戈魯爾之巢。', '沙伯邁恩男爵要你和你的朋友殺死10個劍刃執行者，5個劍刃戰鬥法師，5個劍刃劫毀者和他們領導人，費葛羅姆的任務。當你已經設法完成這項偉績時，返回劍刃山脈的血之環找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10806 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10806, 'zhTW', '攤牌', '我們面對劍刃巨魔的主人，苟克，的時刻已經來到。那也是著手處理事情的時刻，去告別古羅的生命。$B$B拿著我的璽戒。當你到了苟克祭壇時，使用它，而我到來加入你。$B$B我們將一同毀滅苟克。', '在茍克祭壇使用沙伯邁恩的徽章，然後殺死茍克。當完成時，返回劍刃山脈的血之環找沙伯邁恩男爵。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10807 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10807, 'zhTW', '灰舌破碎者', '破碎者們一直都畏懼著灰舌部族。他們其中不乏凶惡又殘忍的成員，全都是由阿卡瑪親手挑選的。他們好鬥殘忍的程度不下於任何一個納迦、惡魔或者伊利丹的血精靈部隊，而他們現在聚集了大批的成員在巴瑞廢墟，就在這裡的北邊。在他們對我們發動攻擊前去那邊削減他們的成員數目吧。', '『感化者』瓦倫恩要你去巴瑞廢墟殺死3個灰舌駕馭者、4個灰舌戰士還有6個灰舌薩滿。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去影月谷找群星聖殿的勸誡者瓦倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10808 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10808, 'zhTW', '阻礙黑暗議會', '黑暗議會的幽靈想透過一種在史凱瑟隆營地南邊的熔岩地窖裡進行的儀式，召喚古老而強大的邪惡力量。$B$B古爾丹的魔法與他們自己的混在一起，使他們能夠幫助這種生物顯現在我們的世界!我們不能允許這種事情發生，$n。它所帶來的死亡和毀滅是無法想像的!$B$B帶著這個權杖到召喚的場地去，並使用其魔力，一勞永逸地阻止黑暗議會!', '殺掉黑暗議會儀式者，並且使用帕莎之杖去結束黑暗議會的召喚儀式，然後返回熔岩平原的帕莎那裡。', '', '去影月谷找熔岩平原的帕沙恩。', '終結黑暗教團的召喚儀式', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10809 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10809, 'zhTW', '懸賞告示:座狼大師科洛斯', '海報寫著:$B$B「座狼大師科洛斯領導血之谷氏族的座狼騎士。懸賞他的人頭，因為他的騎士們向開往斷脊氏族崗哨的補給列車勒索高額的過路費。」$B$B「斥候到薩斯葛爾裡向他報告，能帶來這個壞人頭顱的英雄將贏得部落的感謝，以及一大筆的賞金。」$B$B「-達克豪中尉」', '殺死座狼大師科洛斯，並且將他的頭帶到斷脊氏族崗哨交給達克豪中尉。', '', '去地獄火半島找斷脊氏族崗哨的達克霍爾上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10810, 'zhTW', '破損的面具', '當你檢視破損的面具的時候，你聽見面具發出奇怪的聲音。假如面具沒有破損的話你可以聽見更清楚的聲音。$B$B魯安曠野的歐瑪利·贊普奈可能可以修理這個面具。', '將破損的面具帶給魯安曠野的歐瑪利·贊普奈。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10811 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10811, 'zhTW', '尋找奈爾斯阿拉古', '他們的庇護者翱翔在高空中，$n。或許你對他孩子的仁慈已感動了他的心。尋找奈爾斯阿拉古並且得到他的幫助。同時，你或許能解決虛空之翼龍的困境。$B$B<摩德奈指向天空。>$B$B飛的很高，朋友……', '尋找奈爾斯阿拉古，虛空之翼軍團的庇護者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10812, 'zhTW', '神秘面罩', '沒問題，修好了。你問我這是什麼?哦，這是一個通訊裝置-它可以讓那些笨蛋跟彼此通訊。你知道的呀，燃燒軍團!我建議你把這個面具交給野蠻領主安德烈利安。他就在那邊走來走去。他總是不停的移動。$B$B那就快點去吧，他一直很想得到這個東西。', '將神秘面罩帶給魯安曠野的野蠻領主安德烈利安。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10813 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10813, 'zhTW', '葛銳洛克之眼', '$n，你已經勇敢面對了血之谷獸人的巢穴，可怕的薩斯葛爾，並且存活下來!或許你有幫助我的力量，因為我的目的是注視進最黑暗的巫者，葛銳洛克的心智!$B$B拿著這塊裂片。用它迷惑一顆葛銳洛克之眼，並且將它與自己結合。回到這裡並且靠近我的大鍋……它將從你身上拉出眼睛。$B$B去吧，$n。小心使用 -- 只要它打開了一條小縫，葛銳洛克之眼就會把你出賣給我們的敵人!', '使用雷札克的裂片去俘虜一顆葛銳洛克之眼，然後靠近雷札克的大鍋去提煉它。在它被移除之後，把雷札克的裂片還給他。', '', '去地獄火半島找斷脊氏族崗哨的塞薩克。', '交回格里洛克之眼', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10814 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10814, 'zhTW', '奈爾斯阿拉古的傳說', '我有你可能有用的訊息。請聽聽我必須告訴你的，$r。', '與奈爾斯阿拉古交談並且聽他的故事。', '奈爾薩拉庫的故事', '去影月谷找靈翼平原的奈爾薩拉庫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10815 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10815, 'zhTW', '瓦薩雷克的日記：戰爭的前奏', '日誌中記載了伊利丹軍隊近期的動向，還提到了瓦薩雷克率兵駐守征服之路的原因。原來這傢伙親手俘虜了一名沙塔爾高階將領。$B$B當前，這位將軍被關押在位於征服之路南端的火紅崗哨。一個名叫火色魔印的神秘組織負責看守囚犯。你若是想要調查此事，最好叫上你的朋友一同轉至。', '轉至火紅崗哨尋找瑪庫斯·奧拉林，他是沙塔爾的高階將領。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10816 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10816, 'zhTW', '開拓神聖之地', '你對抗巴瑞的破碎者做得很好，$n。讓我們看看你對伊利丹最可怕的軍隊可以做的如何。$B$B影月氏族的魔獄獸人佔領了阿塔莫露臺，那兒曾經是非常神聖的地方，在那裡的阿塔莫水晶被用於神聖的典禮上。$B$B我們有理由相信，他們把一顆真的阿塔莫水晶藏在附近，但是我們的水晶球占卜什麼也沒顯示。雖然如此，那些魔獄獸人是在德萊尼的神聖地上，他們的存在必須被解決。', '復仇者阿魯曼要你殺死8個影月殺戮者，8個影月挑選者和4個影月黑暗編織者。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去影月谷找沙塔爾祭壇的守備官奧魯門。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10817 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10817, 'zhTW', '巨大的懲罰', '你對抗灰舌破碎者做得很好，$n。如果你可以的話，我還有另一項挑戰給你。$B$B沒多久以前，星光聖所遭受到伊利丹的魔獄獸人一次驚人的攻擊。$B$B我們確定那是佔據阿塔莫露臺的影月獸人所犯下的罪行。$B$B給他們知道占卜者不是好欺負的。', '『感化者』瓦倫恩要你殺死8個影月殺戮者，8個影月挑選者和4個影月黑暗編織者。為占卜者完成任務會讓你的奧多爾聲望降低。', '', '去影月谷找群星聖殿的勸誡者瓦倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10818, 'zhTW', '沙伯邁恩男爵請求你的出現', '$n，當你出去對付$c的時候，沙伯邁恩男爵派他的寵物龍帶來一個訊息。$B$B他在找你本人。據我了解，他想要你率領他自己對古羅的戰鬥。$B$B我猜測你是在整個外域裡最有資格幫助他的人，但是如果我是你，我會先與兩位朋友聯繫，並且要他們在血之環加入你的行列。', '你收到邀請再次與沙伯邁恩男爵談一些關於進口的事務。去劍刃山脈的血之環找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10819, 'zhTW', '邪誓防毒面具', '我有一個非常特殊的任務要交給你，$N。我要你滲透進入東邊的煉冶場:怒氣。當你到達煉冶場你將需要戴上邪誓防毒面具然後找到軍團通報器。一旦你找到通報裝置就跟裝置另一邊的人談話，不管他是誰。$B$B假如一切順利你就可以誆騙這些惡魔做出一些不光明正大的事情!試著告訴那個惡魔，煉冶場:怒氣已經造反了。$B$B祝你好運$C。', '戴著邪誓防毒面具使用煉冶場:怒氣的軍團通報器。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10820 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10820, 'zhTW', '矇騙敵人', '有話快說!要是讓我聽到你在浪費我的時間，你就死定了!$B$B什麼?煉冶場造反了?這不可能是真的!我的手下不敢挑戰我的權威。$B$B既然這樣，他們每一個人都將為他們的叛變付出代價，非常大的代價。把他們都殺光事情就結束了!執行完我的命令之後向我回報，不然我就把你一起解決掉。', '殺死4個末日之爐侍者和4個末日之爐工程師。', '', '去刀鋒山找鑄魔營地：怒火的軍團聯絡器。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10821, 'zhTW', '你被開除了!', '末日哀嚎者沒有想辦法阻止那場叛變嗎?她真大膽!她一直以來都在質疑我的權威。不論如何，這會是她的最後一次了。你必須召喚她然後親自解決她。$B$B她的煉冶場守衛擁有可以召喚她到煉冶場:怒氣的鑰匙。取得五把鑰匙然後啟動五座軍團尖塔。那些方尖塔的啟動時間很短，所以確認要全部同時啟動。記住，煉冶場守衛擁有比較多的鑰匙。', '殺死末日哀嚎者然後回到永恆樹林向野蠻領主安德烈利安回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10822, 'zhTW', '一個日怒徽章', '', '', '', '去找影月谷的戰鬥法師弗亞拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10823, 'zhTW', '更多的日怒徽章', '', '', '', '去找影月谷的戰鬥法師弗亞拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10824 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10824, 'zhTW', '日怒徽章', '占卜者的生存視超額徵募的凱爾薩斯而定。每一個來自奎爾薩拉斯並加入他的朝聖者都讓他更接近勝利。我們的對手是真實的。$B$B然而，我們很快將沒有新兵，到時候就要看哪一方能較快殺死對方。把和凱爾薩斯及伊利丹結盟的高階血精靈所配戴的日怒徽章帶來給我，證明你對占卜者的價值。你可以在西邊的日蝕崗哨和東北邊的卡拉伯爾廢墟找到他們。', '星光聖所的戰鬥法師維爾阿拉要你為她帶來10個日怒徽章。為占卜者完成任務會使你的奧多爾聲望降低。', '', '去影月谷找群星聖殿的戰鬥法師弗亞拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10825 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10825, 'zhTW', '未知的真相', '這個奇怪，魔法的寶珠從阿拉卡的廓羽下方落下。$B$B充滿著怪異，紫色的光輝，寶珠跟著一個聽不到的節拍跳動著。拿著它使你略感不舒服，因此你迅速地把它放到你的背包裡。$B$B或許穿過隧道越過龍骨橋，在魯安曠野西邊的林木守衛蕭恩會有興趣看看它?', '將葛瑞納寶珠送到劍刃山脈的魯安曠野給林木守衛蕭恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10826 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10826, 'zhTW', '薩格拉斯印記', '現在你應該明白為什麼我們要對抗燃燒軍團還有他們的部下了。$B$B假如你想向奧多爾證明你自己，幫我帶來燃燒軍團還有他們的暗影議會成員的高階徽記。在影月谷這邊你可以找到強大的燃燒軍團成員，位在西邊遠方的軍團要塞還有死亡熔爐。', '取得10個薩格拉斯印記交給影月谷的先驅者沙洛尼恩。為奧多爾完成任務會讓你的占卜者聲望降低。', '', '去影月谷找沙塔爾祭壇的先驅者薩隆尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10827 AND `locale` = 'zhTW';
