DELETE FROM `quest_template_locale` WHERE `ID` = 10828 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10828, 'zhTW', '一個薩格拉斯印記', '', '', '', '去找影月谷的先驅者薩隆尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10829 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10829, 'zhTW', '樹老長者必須知道', '這真麻煩!阿拉卡害長者和保衛者被邪惡靈魂附身!但是有一位長者無論如何不能被影響。他的名字是樹老長者，如果我們要拯救烏鴉林的樹木，那你必須立刻去找他!回到烏鴉林。你可在過了葛瑞許納什的道路分岔處找到他。', '林木守衛蕭恩要你尋找並且與樹老長者交談，一位傳說住在劍刃山脈的烏鴉林裡的長者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10830 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10830, 'zhTW', '淨化樹林', '葛瑞納已經讓葉鬚樹人和石化樹人被邪惡的可伊靈魂佔據。$B$B我們必須拯救這些樹，否則整個烏鴉林很快將永遠消失!$B$B結合在葛瑞許納什找到的葛瑞許納什寶珠魔法，和兇暴烏鴉身上的一根可怕幼羽。$B$B使用結合成的驅邪羽毛引出可伊靈魂並盡快殺了它。石化樹人對這儀式來說太強大了，但如果我們拯救了足夠的葉鬚樹人，他們也將獲得自由。', '收集5個葛瑞許納什寶珠和5根可怕幼羽，然後將它們合併成驅邪羽毛。使用這些羽毛驅除並殺掉5個佔據烏鴉林葉鬚樹人的可伊靈魂。等你完成，返回劍刃山脈的烏鴉林找樹老長者。', '', '', '葉鬚樹人已驅魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10831 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10831, 'zhTW', '成為一名月布裁縫師', '如果你感興趣，我能教你月布裁縫技術的方法。專精於月布縫製技術後，製作出來的原始月布將比一般產量高出兩倍，且你將能接觸幾種獨有的圖樣。只要你通過一次簡單的試驗。$B$B關於這個試驗，你的任務是去塞納里奧避難所的月井製作一個原始月布的小樣本。我將提供你所需的材料。等你製作出樣本，把它帶回來讓我檢查。', '站在塞納里奧避難所的月井中使用魔染幽紋曲尺來製作一個原始月布樣本。將完成的樣本帶回撒塔斯的陰鬱城給那斯馬拉·月歌。*警告!*你只能選擇一種裁縫專業。', '', '去找撒塔斯城的納絲瑪拉·月歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10832 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10832, 'zhTW', '成為一名魔焰裁縫師', '如果你想要的話我能教你魔焰裁縫技術的方法，但是先警告你，它是一項危險的工作。$B$B在虛空風暴創造的魔法布吸引了強大的虛空鬼魂。我正在尋找一種降低反衝的方法，但是我的研究需要更多虛空怨靈的精華。$B$B帶著這個信號燈到虛空風暴，並且用它召喚一個虛空怨靈。帶回它的精華我就同意教你。身為一名魔焰裁縫，你將得到雙倍的布並且能接觸到獨有的圖樣。', '帶一個虛空怨靈精華的樣品到撒塔斯的陰鬱城給蓋吉·術法編織者。*警告!* 你只能選擇一種裁縫專業。', '', '去找撒塔斯城的金吉·斯比維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10833 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10833, 'zhTW', '成為一名影紋裁縫師', '如果你變成一位影紋裁縫專家，你將可比一般裁縫師縫製多出兩倍的暗影布，且可以用到數種獨有的圖樣。$B$B當然，任何一位裁縫師都可以使用暗影祭壇，但是暗影裁縫師能更深入的融入祭壇，解開只有少數人可以探查的力量。$B$B將這顆水晶拿到東方的影月谷，然後在虛空之翼農場南方找到虛空之翼小徑。在靠近世界的邊緣，你將會發現暗影祭壇。在那裡使用水晶。', '在暗影祭壇附近使用暗影深淵水晶，以加深你與祭壇的協調，然後回到撒塔斯陰鬱城中的安德利恩·暗紋紡織者那裡。*警告!*當完成此任務，你將成為一位暗影專家。你只能選擇一種專業技能。', '', '去找撒塔斯城的安迪恩·達克斯賓。', '增強與暗影祭壇的共鳴', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10834 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10834, 'zhTW', '葛銳洛克『暗眼』', '葛銳洛克『暗眼』已經將一部份的自己抵押給黑暗力量，並且因而獲得極強的魔法。他失去的眼睛在某個地獄坑洞深處燃燒著，現在一個惡魔的小飾物……和掩蓋他背叛的眼罩掌握著它自己的黑暗秘密。$B$B把葛銳洛克的眼罩帶來給我，$n，而我將為你的效勞大大地酬謝你……', '殺死葛銳洛克『黑眼』並且將葛銳洛克的眼罩帶去給斷脊氏族崗哨的雷札克。', '', '去地獄火半島找斷脊氏族崗哨的塞薩克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10835 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10835, 'zhTW', '藥劑師安拓維奇', '$n，我已經準備好關於血之谷獸人發現的初步報告。我在索爾瑪的同事，藥劑師安拓維奇會很高興收到它們。他也研究魔獄獸人的現象……希望能防止這樣的悲劇再次降臨在我們的獸人盟友身上。$B$B把這份報告拿給他，我將繼續研究你帶來給我的血液。如果幸運的話，我們將找出魔獄獸人痛苦的根因。', '將艾柏瑞克的發現帶去索爾瑪給藥劑師安拓維奇。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10836 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10836, 'zhTW', '滲入龍喉堡壘', '我需要時間才能想出一個辦法去救我的孩子和伙伴。你這次要相信我，凡人。$B$B到龍喉堡壘冒險去吧，它位於虛空之翼農場的東方邊緣，並且將你發現的所有龍喉獸人消滅。接著發生的混亂和騷動應該對他們的計畫有相當的影響。$B$B先警告你，我的一些族人太厲害了 - 龍喉腐化了他們的心。對他們來說，唯一的解決就是死。我允許你去結束他們的生命。', '影月谷，虛空之翼農場上方飛得很高的奈爾斯阿拉古要你殺死15個龍喉獸人。龍喉堡壘裡所有的龍喉獸人都可以。', '', '去影月谷找靈翼平原的奈爾薩拉庫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10837 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10837, 'zhTW', '前往虛空之翼岩架!', '我相信我能以本身的力量給予幽藤水晶附魔的效能。灌輸在這些水晶內的力量足以將那些龍從奴役他們的主人手中解救出來。$B$B前往虛空之翼岩架，一座在影月谷破碎沙洲外的小島，向東南方去。你將在虛空之翼岩架發現幽藤水晶。當你已經收集足以裝滿你背包的水晶時，回到我這裡。$B$B$n，小心現在居住在島上的龍喉者。', '影月谷，虛空之翼農場上方飛得很高的奈爾斯阿拉古要你從虛空之翼岩架收集12顆幽藤水晶。', '', '去影月谷找靈翼平原的奈爾薩拉庫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10838 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10838, 'zhTW', '惡魔占卜器', '惡魔占卜器準備好了。把它帶到地獄火堡壘後面，朝向地獄火盆地，在地上召喚它。 它就會開始調整自己至與地獄火堡壘調和。在它調和後，對占卜器說話並抄下它告訴你的東西。把那個抄本帶來給我……$B$B去吧，$n，準備好再去。地獄火堡壘一定會偵測到占卜器並派看守人去破壞它!', '在地獄火盆地裡使用惡魔占卜器，等它調和，然後帶走讀數。將惡魔占卜器和惡魔占卜器讀數帶回索爾瑪給藥劑師安拓維奇。', '', '去地獄火半島找索爾瑪的藥劑師安東尼維奇。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10839 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10839, 'zhTW', '迷霧斯奇司:泰洛克黑石', '迷霧斯奇司在商隊的西北方，撒塔斯南邊森林的一片獨立的小樹林裡。謠傳司凱堤斯的殖民隊已經建造了一個崇拜的邪惡祭壇。如果斯奇司的阿拉卡要被救贖，這個泰洛克黑石就必須被淨化。$B$B帶著這個淨化魔棒並把它用在黑石上。透過阿達歐祝福，魔棒的純潔應足以帶給黑石清澈。現在去吧，願聖光照耀在你身上。', '在迷霧斯奇司的泰洛克黑石上使用淨化魔棒，並返回白骨荒野的難民商隊找奇瑞克。', '嘗試淨化泰羅克黑石', '去找白骨荒野難民車隊的覺醒者基爾利克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10840 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10840, 'zhTW', '聖光之墓', '向東走，埋在被燒焦的沙子下的即是聖光之墓，一個死者失落的安息之處方。在我們的商隊被伏擊之前，我正要去墓地淨化它邪惡的靈魂。$B$B我卻不知道它已經被另一種邪惡所侵擾。甚至現在，伊斯利為了死者幾世紀以前獲得的小飾物和紀念品而劫掠死者的身體。$B$B當我們的商隊努力求生存時，我能做的卻很有限。', '高階祭司歐格蘭要你去進入聖光之墓，殺死10個伊斯利虛空術師和10個伊斯利掠奪者，然後回到難民商隊找他。', '', '去白骨荒野找難民車隊的高階祭司奧戈魯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10841, 'zhTW', '復仇先驅', '[PH]  進入光明之墓，啟動那玩意兒。', '[PH]  啟動那玩意兒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10842, 'zhTW', '復仇的靈魂', '聖光之墓現在已經被暗影議會所腐蝕了，裡面那些死去的德萊尼人的靈魂受到了深入骨髓的詛咒，成為了內心中充滿憤怒、困惑，以及對生者之怨念的邪靈。$B$B進入那座墓穴，找到那些悲慘的犧牲品。讓他們得到最後的安息。', '高階祭司奧戈魯要你去聖光之墓，擊敗5名復仇的德萊尼。', '', '轉至白骨荒野的難民車隊，同那裡的高階祭司奧戈魯交談。', '已殺死復仇的德萊尼', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10843, 'zhTW', '不知道從什麼時候開始……', '不知道從什麼時候開始，我們就已經在和劍刃巨魔作戰了。$B$B我們已經設法把他們擊退，因此現在他們只微弱的掌握住劍刃崗哨。按你來的路回去，在剃刀山脊的西南邊緣。$B$B藉由殺死他們的領導人，葛諾斯·布羅格納，向我證明你的價值。$B$B讓我們看看當你與巨魔作戰時，你是塊什麼料。', '為了向摩克納薩爾證明自己，李歐羅克斯已經命令你殺死葛諾斯·布羅格納，劍刃崗哨的巨魔領導人。完成後返回劍刃山脈的摩克納薩爾村找李歐羅克斯，不然就不要回來。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10844, 'zhTW', '煉冶場:怒氣', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10845, 'zhTW', '殺死幼龍之母', '我的獵人剛完成美聲山脊的偵察任務回來。看來寄生於那些水晶的虛空龍已經大幅增加並威脅到我們。$B$B既然你已證明你是一個有能力的殺手，讓我們看看你的$c技能是否敵的過一隻成年的龍。$B$B向南方穿過鱗翼沙洲並找到美聲山脊。進入那裡並殺死他們的母親，魔翼。', '李歐羅克斯要你殺死魔翼 。等你殺死她再返回摩克納薩爾村找他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10846, 'zhTW', '了解摩克納薩爾', '<李歐羅克斯用一種讓你的靈魂凝結的眼神注視著你的眼睛。>$B$B你來到摩克納薩爾，但是你不了解我們。你不了解我們鬥爭以求生存。$B$B假如你要了解我們，那麼你必須忍受一次那種鬥爭的滋味。$B$B南方是維克尼爾阿拉卡。他們在一個叫做索格瑪領土的洞穴裡奴役一群巨魔，而他們的領導人，維克也在那裡。$B$B殺了他!', '要開始你對摩克納薩爾的了解，就要殺掉維克，維克尼爾阿拉卡的領導者。然後，返回劍刃山脈的摩克納薩爾村找李歐羅克斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10847, 'zhTW', '司凱堤斯之眼', '厄運從司凱堤斯的懸崖傾聽著。$B$B我的族人，阿拉卡，面臨被無法形容的邪惡掩蔽的命運。我們太常濫用黑暗魔法去做壞事了。透過阿達歐我已經學習了聖光和救贖。$B$B泰洛克透過被黑暗術施法的眼球從司凱堤斯窺看他的殖民地。從泰洛卡北邊的迷霧瑞斯克和迷霧辛諾偷取這些眼珠。讓我看見泰洛克所看見的。讓我透過司凱堤斯的眼睛窺探。', '將瑞斯克之眼還有辛諾之眼交給撒塔斯城內陰鬱城的『贖罪者』里拉克。', '', '去找撒塔斯城貧民窟的救贖者瑞拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10848, 'zhTW', '迷霧瑞漢茲:邪惡靈魂', '迷霧瑞漢茲是一塊特別邪惡的司凱堤斯殖民地。$B$B儘管村莊被奧齊頓災難所毀滅，泰洛卡的影響力依舊存在那裡的邪惡靈魂中。向西前往迷霧瑞漢茲，殺死那些殘忍卑鄙的人。你將在暗影之墓西邊發現他們，在白骨荒野和泰洛卡森林的邊境上。$B$B這將是我們對抗泰洛卡和司凱堤斯的守護者的第一擊。', '殺死4個死亡之爪靈魂、4個尖嘯靈魂還有2個烏鴉之魂然後回報給難民商隊的奇瑞克。', '', '去找白骨荒野難民車隊的覺醒者基爾利克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10849 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10849, 'zhTW', '尋找奇瑞克', '其他阿拉卡參加了泰洛克的背叛。$B$B奇瑞克認出泰洛克是一個騙徒，並非一位先知。泰洛卡所預測唯一的預言是出自於他自己召喚的毀滅。$B$B是奇瑞克從司凱堤斯英勇地領導我們。在我們朝聖到撒塔斯之後，奇瑞克便到殖民地尋找其他人。$B$B這份公文訴說眼球看過的一切。一定要告訴奇瑞克!沿著撒塔斯外南方的道路到白骨荒野，並且尋找商隊。', '將里拉的書信交給白骨荒野的難民商隊的奇瑞克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10850 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10850, 'zhTW', '虛空火焰引擎裡的虛空氣體', '', '你打開惡魔搶奪者倒入燃料的蓋子。', '', '去虛空風暴找未啟用的魔能機甲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10851, 'zhTW', '敵人的圖騰', '尊敬一個人的祖先有正確的方式，也有錯誤的方式。$B$B劍刃巨魔帶著圖騰，但是他們並非用它們來表現他們的尊敬。相反的，他們想使用它們去操作並且控制。$B$B我們應該偷取他們的圖騰，因為他們不值得擁有!我們會把它們拿來做更好的利用。$B$B去西方的劍刃崗哨，就在剃刀山脊的西南邊。殺死劍刃秘法師和粉碎者，並從他們那裡拿走圖騰!', '收集5個劍刃氏族圖騰交給劍刃山脈的摩克納薩爾村的招魂師多赫加。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10852 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10852, 'zhTW', '失蹤的朋友', '我們停留在這邊的原因是因為有一些人在半夜的時候闖入並且發出了很大的噪音。那個感覺是很可怕的。我不知道我們什麼時候可以再度上路。$B$B我的一些朋友已經失蹤了。我不知道他們在哪裡。我想那些可怕的鳥人把他們帶到了西北邊。他們八成是被鎖在籠子之類的東西裡面。假如你找到他們的話那就太好了。我有點擔心他們。', '伊森要你在迷霧斯奇司找到他的12個失蹤的朋友然後回到難民商隊找他。', '', '去白骨荒野找難民車隊的伊森。', '營救兒童', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10853 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10853, 'zhTW', '呼喚靈魂', '美聲山脊的虛空龍靈魂需要解放。$B$B虛空龍不永遠都是虛空龍。他們過去是黑龍。$B$B但是，由於這個世界的毀滅，一股虛空能量改變了一切，並且產生了改變幼龍蛋的副作用。$B$B現在他們全都是以前自身的扭曲版本。我們必須幫助他們找到平靜。$B$B要這樣做就要去殺死一隻靠近召靈圖騰的龍，然後自它身上取走它的靈魂。', '招魂師多赫加要你使用召靈圖騰收集8個次級虛空龍靈魂然後回到劍刃山脈的摩克納薩爾村交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10854 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10854, 'zhTW', '奈爾斯阿拉古的力量', '帶著這顆附魔虛空藤水晶走上你回到龍喉堡壘的路。到了那裡，尋找那些被奴役的龍並召喚附魔幽藤水晶的魔法。我會傾洩自己的能量，讓龍掙脫俘虜著他們的束縛。當你看見龍已經掙脫束縛時，幫助它戰勝它的俘虜者!因為監禁的關係它一定是虛弱的。$B$B解救所有你能找到的龍，並且返回我這裡，$n。', '飛翔在影月谷的虛空之翼農場上方的奈爾斯阿拉古要你釋放5隻被奴役的虛空之翼龍。', '', '去影月谷找靈翼平原的奈爾薩拉庫。', '解救被奴役的靈翼幼龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10855 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10855, 'zhTW', '惡魔搶奪者，不用了謝謝!', '啊，是的 - 惡魔搶奪者!軍團無疑是最可怕的機械創造物。這些可惡的東西中至少有三座瞄準了風暴之尖。$B$B很幸運的，它們還未啟動。這給予我們透過破壞取代殘暴武力去對付他們的可能性。$B$B由熔爐基地:遺忘的甘納格手中取得凝結的地下瓦斯:用它淹沒並灌滿一只惡魔搶奪者附近的油箱。我有一種感覺，它的引擎會出問題。', '從熔爐基地:遺忘的甘納格鍛造手身上取得5份濃縮的虛空氣體，就在風暴之尖的西北方，並把它們裝填進附近閒置的惡魔搶奪者。在你完成這項任務之後，返回虛空行者那魯利斯那裡。', '', '去虛空風暴找風暴尖塔的虛空獵手納烏希思。', '', '摧毀未啟用的魔能機甲', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10856 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10856, 'zhTW', '最佳的防禦', '工業破壞的勇敢行動只能讓我們走到現在這一步，$n。熔爐基地:遺忘是惡魔搶奪者的一個集中地，熔爐基地:苦難則是他們軍隊的臨時基地，因為它是大部分軍團的傳送設備所在地。$B$B我要你進入那裡削減他們的數量。 他們現在必定有充分的憤怒使者軍團，而我們就是不能允許它發生。', '虛空行者那魯利斯要你在熔爐基地:苦難殺死12個憤怒使者，在風暴之尖的北方。', '', '去虛空風暴找風暴尖塔的虛空獵手納烏希思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10857 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10857, 'zhTW', '傳送這個!', '儘管殺死惡魔很有趣，但是當軍團持續用它的傳送器輸送任何被我們殺死的替補成員時，對我們完全沒好處。$B$B不幸地，我手邊沒有任何威力強大的爆裂物……不過負責維持傳送器運作的莫阿格那有。$B$B帶著這根魔棒……我已經調整它的功率去干擾莫阿格的大腦頻率。回到熔爐基地:苦難並在你能看到的任何莫阿格身上使用它。你不會有太長的時間，但你將能使用他們的破壞爆裂物摧毀鄰近的傳送器。', '虛空行者那魯利斯要你對熔爐基地:苦難的莫阿格使用精神干擾魔棒並且對煉冶場的三個傳送器使用他們的引爆傳送器能力。', '', '去虛空風暴找風暴尖塔的虛空獵手納烏希思。', '摧毀西部傳送器', '摧毀中部傳送器', '摧毀東部傳送器', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10858, 'zhTW', '凱瑞納古', '我羞愧地再次開口請求你的幫助，$n，但是你是我們一族的唯一希望。沒有我的伴侶，虛空之翼的龍們可能會全部死去。$B$B想辦法抵達龍喉堡壘的頂端，並找到凱瑞納古。$B$B我們會在上空盤旋。萬一在他們的防禦過程中出現中斷，虛空之翼的力量將向底下展開攻擊來幫助你。', '到龍喉堡壘尋找凱瑞納古。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10859, 'zhTW', '收集寶珠', '雷森伊斯利有一種奇怪的儀器會發出微小、粉紅色光芒的飄浮光球。它們讓我想起靈魂。$B$B它們不會與伊斯利死亡時所釋放的大黃球相混淆，這些完全是別種東西。$B$B我要你到北方的雷森平台設置一些圖騰，這些圖騰將會攻擊粉紅光球。$B$B把它們帶回來給我這樣我才能確切地判斷它們是什麼。', '招魂師多赫加要你使用寶珠召集圖騰收集15個雷森光球。任務完成後回到劍刃山脈的摩克納薩爾村向他回報。', '', '', '收集雷森光球', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10860, 'zhTW', '摩克納薩爾的款待', '餓嗎，$r?偉大的靈魂會幫助那些自助者。如果你想要掙一頓飯，我建議你注意聽著，因為布拉格爾那裡不會給你任何免費的東西，而且也不可口!$B$B剃刀山脊和鱗翼沙洲的迅猛龍及鱗翼具有你從未嚐過之最美味的兩種佳餚中所需要的東西。把他們的迅猛龍肋骨和毒蛇肉帶來給我，我將為你做出這兩道菜。$B$B我甚至可以教你如何自己烹煮它們，如果你動作快的話。', '女總管瓦拉給你一份可以製作兩道他最喜歡的菜餚的材料名單，包含了3個迅猛龍肋骨還有3份毒蛇肉。回到劍刃山脈的摩克納薩爾村的把材料交給她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10861, 'zhTW', '迷霧里斯克:先發制人的攻擊', '西南方不幸的殖民地叫做迷霧里斯克，泰洛卡的爪牙試圖在他們的鳥類同胞孵化之前玷污他們。里斯克的黑暗男巫士將蛋用暗影詛咒封在容器裡。當幼鳥孵出時，他們不用腦子地為泰洛克效命。$B$B前往迷霧里斯克，並在咒語有時間滲入前，提前破開這些蛋。即使你太遲了，你也能殺死已被污染的鳥類。$B$B記住，聖光的光芒在黑暗中是最明亮的。', '打破在迷霧里斯克受詛咒的蛋。在返回難民商隊找奇瑞克之前，救回3隻幼鳥並殺掉3隻有害的幼鳥。', '', '去找白骨荒野難民車隊的覺醒者基爾利克。', '救贖雛鳥', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10862, 'zhTW', '向部落投降', '那些懦弱的阿拉卡每天都攻擊我們。他們偷襲我們的獵人而且有時候還突襲到城內來。我們盡可能的殺死他們，但是他們的魔法很強大而且他們時常都可以逃出我們的毒手。$B$B我聽說有些阿拉卡要求跟部落維持友好關係。他們住在撒塔斯城的西北邊。他們的首領是『贖罪者』里拉克。去陰鬱城找他，當你找到他的時候要求他投降。', '瑞克格要你在撒塔斯城尋找『贖罪者』里拉克並且要求他跟他的人民歸順部落。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10863, 'zhTW', '阿拉卡的秘密', '在邊境這裡我們必須每天對付阿拉卡。他們高興就襲擊我們，突襲我們的補給線，並且殺死我們的斥候。$B$B然而，我們對這些謎一般的生物幾乎不瞭解。我已經得到消息，西北方撒塔斯城的阿拉卡和我們不是敵對的。他們或許願意分享他們種族的秘密。$B$B『贖罪者』里拉克是他們的領導人。他住在陰鬱城的北方區域。', '戴娜·甘迺迪女士要你在撒塔斯城找到『贖罪者』里拉克向他探聽他願意分享的阿拉卡秘密。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10864 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10864, 'zhTW', '靈魂的負擔', '我有一個儀器，惡魔占卜器，它能分析邪惡魔法。我將讓你使用占卜器，但是首先……你必須安撫它。占卜器，你明白的，在裡面困著一隻有浩瀚智慧的生物，而它的需要，我們可以說，十分古怪。$B$B要安撫占卜者，你必須殺死獸人。具體的說，他們必須是破碎之手獸人 -- 占卜者需要他們的靈魂。$B$B等你獲得靈魂的時候回來找我。你將可在地獄火堡壘北方，以及南方及周圍發現獸人。', '殺死20個破碎之手獸人，然後回到索爾瑪找藥劑師安拓維奇。', '', '去地獄火半島找索爾瑪的藥劑師安東尼維奇。', '收割碎手之魂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10865 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10865, 'zhTW', '通知李歐羅克斯!', '快一點，你必須通知李歐羅克斯在雷森平台發生了什麼事!$B$B那些寶珠是由靈魂所組成，他們之中的一些人是摩克納薩爾!', '招魂師多赫加要你去通知李歐羅克斯關於雷森伊斯利的企圖。他的位置在劍刃山脈的摩克納薩爾村。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10866 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10866, 'zhTW', '『疲憊者』祖魯希德', '他隱藏在我的思想裡，凡人。他等我放棄……讓我順從他的意志。$B$B而這將是他毀滅的原因。我將召喚他。我將告訴他我會按他要求的去做。當他出現時，殺死他並且拿到這把鑰匙!$B$B要知道:祖魯希德是具有未知力量的一個古老獸人。伊利丹肯定已經更進一步授權他。你在為我的要求冒生命危險。你確定你希望做這樣的犧牲嗎?', '殺死『疲憊者』祖魯希德然後取得祖魯希德的鑰匙。使用祖魯希德的鑰匙打開祖魯希德的鎖鍊釋放凱瑞納古。', '', '去影月谷找龍喉要塞的卡瑞納庫。', '解救卡瑞納庫', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10867, 'zhTW', '唯一的回應', '我們對於這種……這種，對我們祖先靈魂的污辱只能有一種回應!$B$B$n，假如你可以幫助我們歸還那些受尊崇的往生者靈魂到他們適當的安息地，就回去雷森平台。$B$B回去那邊殺死雷森直到他們的領導者奈薩斯王子洛薩恩露出他膽小的面容。殺死他然後取回那些靈魂，交給招魂師多赫加!', '李歐羅克斯請你取回靈魂收集品然後帶回劍刃山脈的摩克納薩爾村交給招魂師多赫加。', '', '去刀鋒山找莫克納薩村的喚靈者多戈加爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10868 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10868, 'zhTW', '阿拉卡作戰方式', '阿拉卡再度攻擊我們了，這一次他們趁半夜的時候襲擊我們然後在我們可以衝出去跟他們正面交鋒之前就使用他們的黑暗魔法逃脫。他們使用他們的召喚法陣來復活他們某些死亡的戰士但是假如我們攻擊他們的家園他們就不能逃跑了。迷霧瑞斯克還有迷霧辛諾就在這裡的北邊和東北邊。$B$B找到這些阿拉卡的巢穴然後盡可能的殺光他們。', '諫言者菲拉要你殺死14個辛諾鷹爪還有6個辛諾巫士然後回到碎石堡找她。', '', '去泰羅卡森林找碎石堡的顧問菲埃拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10869, 'zhTW', '抑制阿拉卡', '阿拉卡再度攻擊我們，這一次他們趁半夜的時候襲擊然後在我們整理隊伍攻擊之前就使用他們的黑暗魔法逃脫了。迷霧瑞斯克還有迷霧辛諾就在這裡的北邊和西北邊。$B$B找到這些阿拉卡的巢穴然後盡可能得殺光他們。他們也許不怕我們，但至少我們可以削減他們的戰力。', '葛拉伏汗中尉要你殺死14個辛諾爪牙還有6個辛諾巫士然後回到艾蘭里堡壘找他。', '', '去泰羅卡森林找奧蕾莉亞要塞的加維·砂錘中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10870, 'zhTW', '虛空之翼的盟友', '請讓我送你回去見摩德奈。我相信他想要再次見你。', '讓凱瑞納古送你去虛空之翼農場見摩德奈。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10871, 'zhTW', '靈翼之盟', '讓我送你回到莫德奈那裡吧。他一定想要再見你一面。', '讓卡瑞納庫把你送回靈翼平原的莫德奈身邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10872, 'zhTW', '『疲憊者』祖魯希德', '他隱藏在我的思想裡，凡人。他等我放棄……讓我順從他的意志。$B$B而這將是他毀滅的原因。我將召喚他。我將告訴他我會按他要求的去做。當他出現時，殺死他並且拿到這把鑰匙!$B$B要知道:祖魯希德是具有未知力量的一個古老獸人。伊利丹肯定已經更進一步授權給他。你在為我的要求冒生命危險。你確定你希望做這樣的犧牲嗎?', '殺死『疲憊者』祖魯希德然後取得祖魯希德的鑰匙。使用祖魯希德的鑰匙打開祖魯希德的鎖鍊釋放凱瑞納古。', '', '去影月谷找龍喉要塞的卡瑞納庫。', '解救卡瑞納庫', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10873 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10873, 'zhTW', '夜裡被劫走的人', '我們的小哨站遭受不斷的攻擊。數天前我們在白骨荒野東南方的邊界遭受幽網山脊的蜘蛛們襲擊。它們的攻擊使得我們許多人中毒並且被蜘蛛網住拖走了。我們的一些士兵在匆忙之中拿起了身邊的武器裝備，在夜色中追補那些蜘蛛。$B$B我們已經好幾天沒看到我們被抓走的俘虜或者外出追捕那些蜘蛛的士兵了。我們希望有些人還活著，也許只是被蜘蛛囚禁起來而已。我們的人數太少了。你可以幫忙搜救我們的人嗎?', '斥候納夫靈要你去幽網山脊釋放6名被網住的薩塔戰士然後回到薩塔前哨找他。', '', '去白骨荒野找沙塔爾營地的斥候納弗林。', '解救沙塔爾戰士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10874 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10874, 'zhTW', '迷霧撒拉斯:火源信號', '泰洛克的棲息地，司凱堤斯，隱現在東邊白骨荒野的上方。迷霧撒拉斯在司凱堤斯的底部，那是泰洛克最受人畏懼的領地。透過在迷霧撒拉斯的要塞，泰洛克的前鋒賢者發動對聖光的戰爭。$B$B撒拉斯的壞蛋們跟他們的主人透過一種複雜的魔法火源信號來溝通。往東邊去，$r，消滅那些火源。一旦迷霧撒拉斯被消滅，我們就可以策劃攻陷司凱堤斯。$B$B但是我想得太遠了。', '難民商隊的奇瑞克要你熄滅迷霧撒拉斯的四個火源信號。', '', '去找白骨荒野難民車隊的覺醒者基爾利克。', '熄滅藍玉訊號火焰', '熄滅翡翠訊號火焰', '熄滅紫羅蘭訊號火焰', '熄滅血石訊號火焰', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10875 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10875, 'zhTW', '回報納茲格雷爾', '$n，在你突襲惡魔占卜器的時候，我向上級回報了你對抗魔獄獸人的英勇事蹟。我們在索爾瑪的傑出領袖，納茲格雷爾想跟你談話。我相信他心裡有一個困難的任務……', '跟索爾瑪的納茲格雷爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10876 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10876, 'zhTW', '堡壘之根', '軍隊指揮官葛洛克斯正在訓練地獄火堡壘的破碎之手隊長，逼他們磨練戰技。你必須殺死他，$n，因為他的死亡將帶給魔獄獸人沉重的打擊。$B$B然而，這不全然是你要做的事情。$B$B拿著這個旗幟。插在葛洛克斯的屍體上面。如果葛洛克斯的指揮官，卡加斯之手身上流著任何一滴正統的獸人血液的話就會回應你的挑戰!$B$B他的頭顱，卡加斯之手的頭顱，就是我要的東西。', '殺死軍隊指揮官葛洛克斯，將部落的挑戰安置在他的屍體上，殺死卡加斯之手，然後將卡加斯之手的頭顱交給索爾瑪的納茲格雷爾。', '', '去地獄火半島找索爾瑪的納茲格雷爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10877 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10877, 'zhTW', '恐怖聖物', '很久以前有一個商隊帶著任務前往奧齊頓的大墓穴中一個古老墳墓中取得恐怖聖物。他們都逃跑了，原因就是那個遺物。那個遺物是一個邪惡的東西，當有人碰觸它時就會召喚出魔物。那個商隊在東邊的某處被消滅了。$B$B這個邪惡的神器是擊敗受詛咒的泰利巴斯的關鍵，這個飛行在白骨荒野的生物的可怕計畫。假如你願意的話就請幫助我，但是你的生命甚至是你的靈魂都會很危險。', '歐肯要你去東邊被遺棄的商隊取回恐怖聖物。任務完成後回去找歐肯。', '', '去白骨荒野找沙塔爾營地的沃爾昆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10878 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10878, 'zhTW', '暗夜來臨前', '自從我們的商隊被暗影議會卡巴異教徒攻擊以後，斥候就被派到撒塔斯城求救。守衛們認為我們現在暫時安全了，但是他們低估了那些瘋狂的人。$B$B就像我，並不想在半夜被某個卡巴新教徒劃破我的喉嚨。幫我們一個忙，在他們來攻擊我們之前把戰鬥帶到我們的敵人那邊。$B$B你會在南邊找到攻擊我們的人，就在奧齊頓北方的入口。', '泰洛卡森林，難民商隊的麥克達要你殺死8個卡巴爭鬥者，4個卡巴織法者還有2個卡巴新教徒。', '', '去白骨荒野找難民車隊的米克達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10879 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10879, 'zhTW', '司凱堤斯的攻擊', '司凱堤斯已經對我們發動了戰爭!你已經聚集足夠的力量幫助撒塔斯的防禦了嗎?$B$B阻止那些攻擊者!', '阻止那些進攻者然後跟里拉談話。', '抵擋進攻', '去找撒塔斯城貧民窟的救贖者瑞拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10880 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10880, 'zhTW', '卡巴的命令', '這段訊息上有一個深色的徽印而且上面的語言看起來有點熟悉，看起來像是以密碼編寫的。$B$B也許難民商隊那邊有人會了解。', '將卡巴的命令帶到泰洛卡森林的難民商隊給麥克達。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10881, 'zhTW', '暗影之墓', '許多人相信引起大爆炸使得奧齊頓分裂的就是暗影議會。據說他們喚醒了裡面一個巨大的魔物。$B$B假如謠言屬實，那麼那個魔物一定是轉頭對付他們了。根據這些命令，暗影議會部分的成員正在逃離奧齊頓。他們在暗影之墓收藏了奧齊頓的強大神器。$B$B其中的三個神器是神聖而不可侵犯的，因為它們屬於三個法力強大的族王阿魯南、卡倫還有阿塔勒。我必須要求你去取得它們。', '去難民商隊西邊的暗影之墓，並且取得阿魯南的披氅、卡倫的裁決槌還有阿塔勒卷軸。任務完成後回去找難民商隊的麥克達。', '', '去白骨荒野找難民車隊的米克達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10882 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10882, 'zhTW', '厄運通報者', '<阿達歐的「聲音」裡有一種刺耳的音調。>$B$B凱爾薩斯王子真不會選他的典獄官，現在我們在亞克崔茲被關住的實體已經獲得自由了。$B$B其中有一個，被稱為先驅者史蓋力司的上古諸神的僕人，試著將他主人妄想攻佔宇宙所有世界的夢想帶到這個世界來。$B$B$n，你不能讓他逃走。回去風暴要塞的亞克崔茲，然後趁還來得及時殺死先驅者史蓋力司!', '你的任務是去風暴要塞的亞克崔茲衛星殺死先驅者史蓋力司。任務完成後回去撒塔斯城的聖光露臺找阿達歐。', '', '去撒塔斯城找貧民窟的阿達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10883, 'zhTW', '風暴之鑰', '你已證明你自己完成重大任務的能力，$n。你發現毀滅密碼和凱爾薩斯的關連對我們的目標非常重要。萬一凱爾使用那些密碼，這個世界所剩不多的事物都可能會被瓦解。$B$B阿達歐確信凱爾必須被阻止，並且正在尋找願意經歷試煉的冒險者。證明他們的能力者將被授予那魯的眷顧。$B$B<卡德加點頭。>$B$B阿達歐正在等你……', '與撒塔斯城的阿達歐談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10884 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10884, 'zhTW', '那魯的試煉:寬容', '在你被那魯認可之前，你必須通過四次考驗。$B$B在地獄火堡壘的破碎大廳裡有三個你的族人。他們被殘酷的人，卡加斯·刃拳抓住。他企圖處決他們以作為他男子氣概和力量的標誌。在這樣的一個暴行發生之前，你必須救出這些囚犯。作為行動的證據，為我帶來劊子手未使用的斧。它的斧刃上不能有一滴血!', '撒塔斯城的阿達歐要你自地獄火堡壘的破碎大廳取回劊子手的廢棄之斧。此任務必須在英雄難度副本裡完成。', '', '去撒塔斯城找貧民窟的阿達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10885 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10885, 'zhTW', '那魯的試煉:力量', '在你被那魯認可之前，你必須通過四次考驗。$B$B力量的試驗分成兩部分。你必須消滅盤牙蒸汽洞窟的領導人，督軍卡利斯瑞，並為我帶來他的三叉戟。殺死被稱為莫爾墨的異界生物，他在奧齊頓的暗影迷宮裡，並為我帶來他的精華。$B$B完成這事，你就通過了力量的試驗。', '撒塔斯城的阿達歐要你去取回卡利斯瑞的三叉戟和莫爾墨的精華。此任務必須在英雄難度副本裡完成。', '', '去撒塔斯城找貧民窟的阿達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10886 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10886, 'zhTW', '那魯的試煉:堅毅', '在你被那魯認可之前，你必須通過四次考驗。$B$B在我們的旅行中，我們遇到了很多危險的生物。我們將其中某些生物監禁並且安置在現在稱為風暴要塞的亞克崔茲。$B$B但是，有一名囚犯，那是一名環境的受害者。一個在錯誤的時間，出現在錯誤的那魯船裡的偷渡者。$B$B去亞克崔茲冒險吧，救出這個地精，米歐浩斯·曼納斯頓。確保他的生存。', '撒塔斯城的阿達歐要你去援救來自風暴要塞，亞克崔茲的米歐浩斯·曼納斯頓。此任務必須在英雄難度副本裡完成。', '營救米爾豪斯·法力風暴', '去撒塔斯城找貧民窟的阿達爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10887 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10887, 'zhTW', '逃出墓穴', '感謝你的幫忙，$n。我本來以為我死定了。$B$B我們快點離開吧。不用多久那些教徒就會追上來了。', '幫助阿庫諾回到泰洛卡森林的難民商隊。任務完成後跟麥克達交談。', '護送阿酷諾', '去白骨荒野找難民車隊的米克達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10888 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10888, 'zhTW', '那魯的試煉:瑪瑟里頓', '在你被那魯認可之前，你必須通過四次考驗。$B$B只剩一個障礙了，凡人。召集一支軍隊並且前往地獄火堡壘深處的瑪瑟里頓巢穴。一路殺進密室的中心，並毀滅那邪惡的腐敗者!', '撒塔斯城的阿達歐要你殺死瑪瑟里頓。', '', '去找沙塔斯城的阿達歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10889 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10889, 'zhTW', '回到撒塔斯城', '你的行為雖然勇敢，但肯定會引起泰洛克的報復行為$B$B趕快去撒塔斯城。傳話給里拉!', '去撒塔斯城跟里拉談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10890 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10890, 'zhTW', '[UNUSED] <NYI> ', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10891 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10891, 'zhTW', '帝國的金屬盔甲', '在加基森有一個矮人，名字叫德羅泰恩，他將教你怎樣製造帝國的金屬。而你必須做的只是到塔納利斯沙漠並且找到他。感興趣嗎?', '與加基森的德羅泰恩交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10892 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10892, 'zhTW', '帝國的金屬盔甲', '在加基森有一個矮人，名字叫德羅泰恩，他將教你怎樣製造帝國的金屬。而你必須做的只是到塔納利斯沙漠並且找到他。感興趣嗎?', '與加基森的德羅泰恩交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10893 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10893, 'zhTW', '長尾是關鍵', '黑翼巨龍教徒集中在隧道裡，我們難以應付此情勢。十分坦白的，他們為數眾多。$B$B當我們有辦法注意到他們中的任何人太過接近，事實就是如果他們認真攻擊，我們就會被佔領。$B$B目前的狀況需要有人穿過隧道到另一端那兒，並且殺掉他們的領導人，德拉卡·長尾。打算找點樂子嗎?', '殺死德拉卡·長尾，龍骨隧道裡的巨龍教徒領導者。一旦你完成，回到劍刃山脈的龍骨隧道看守者月影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10894 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10894, 'zhTW', '龍骨看守者', '嗯，我不確定我們應該怎麼做。我不適合當軍事行動的策劃人。$B$B看守者月影會知道怎麼做。他目前正前往我們在西邊的龍骨隧道的防禦工事，就在龍骨橋的尾端。我們有部隊在那邊以防那些教徒們想搞鬼。$B$B拜託你，請以最快的速度將信件送到他手中。', '將會見紙條交給劍刃山脈的龍骨隧道入口的看守者月影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10895 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10895, 'zhTW', '薩斯葛爾必須被燒毀!', '是時候從空中攻擊薩斯葛爾了!我們的獅鷲騎士已準備好突擊，$n。但是他們需要某個人在地面引導他們開火。你準備好進行一項秘密任務了嗎?$B$B將這些煙霧烽火拿進去薩斯葛爾，血之谷堡壘的西方。他們有四座警衛塔:一座在他們北方的牆附近，一座在他們南方的牆附近，一座在他們的煉冶場，而另一座靠著他們的山麓。把信號標放置在每座塔下面，而我們將飛到那裡轟炸他們!', '在每座薩斯葛爾的哨塔使用煙霧烽火，然後回到遠征隊哨塔找空軍指揮戴畢瑞。', '', '去地獄火半島找遠征軍崗哨的空軍指揮官達比利。', '標記北部哨塔', '標記南部哨塔', '標記熔爐哨塔', '標記丘陵哨塔', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10896 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10896, 'zhTW', '被寄生的保衛者', '這塊土地的樹木被奧齊頓釋放出來的能量給毀壞了。釋放出來的腐敗魔法能量將這塊土地摧殘成你目前四處都可以看到的荒野。倖存的樹木現在被討厭的蝕木蟲侵擾，這些蟲在他們的樹皮下爬行並且啃食他們的樹身。$B$B腐爛的森林盛怒者以及群聚的根鬚行者是這些蝕木蟲的宿主。你可以在森林東邊的邊緣地帶找到他們。消滅這些生物，然後殺死自它們樹身逃出的蝕木蟲。', '拉庫提要你殺死25隻蝕木蟲，然後回到難民商隊那裡找他。蝕木蟲寄宿在腐爛的森林狂怒者和群聚的根鬚行者的軀體裡。', '', '去白骨荒野找難民車隊的拉庫泰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10897 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10897, 'zhTW', '大師級藥水', '正如你所知，植物具有特性，而允許鍊金師透過藥水重新能量化並且使其它人恢復生氣。$B$B我對外域植物的熟悉允許我教鍊金師怎樣從它們當中做出最大效用。如果你有興趣擴增你藥水的知識，我有一項任務要你去完成。$B$B有謠傳說在風暴要塞的大植物學家費瑞衛恩寫了一本綜合植物學指南。將它與你工作的樣品一起帶到我這裡，我將教你所尋找的知識。', '羅安娜·薩威爾要你去風暴要塞的波塔尼卡，並且從大植物學家費瑞衛恩那裡取回植物學家的野地指南。另外她也想要你為她帶回來5瓶超強效治療藥水，5瓶超強效法力藥水和5瓶昏睡藥水。*警告!*你只能選擇一種鍊金術專業化。', '', '去贊加沼澤找塞納里奧庇護所的勞蘭娜·薩維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10898 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10898, 'zhTW', '天翼', '天翼在你身邊飛來飛去。$B$B你感覺他要你跟著他。', '護送天翼然後回報給撒塔斯城的『贖罪者』里拉克。', '護送天空之翼', '去找撒塔斯城貧民窟的救贖者瑞拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10899 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10899, 'zhTW', '大師級轉化', '任何鍊金師都會告訴你物質是有延展性的，任何物質都可以轉化成另一個形態 - 但不是真的憑空創造物品或者在轉化的過程中破壞它。$B$B一位真正的轉化大師能學會克服這限制 - 而且我能教你怎樣習得這項專精!$B$B身為未來的轉化師你無疑擅長原始的力量 - 所有原始力量之物質代表的結合。讓我看看的轉化能力，我將與你分享我的知識。', '虛空風暴，風暴之尖的薩爾菲要你帶給他4個原始力量。*警告!*你只能選擇一種鍊金術專精。', '', '去虛空風暴找風暴尖塔的薩雷維。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10900 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10900, 'zhTW', '瓦許的印記', '', '把它燒掉，$r。全部燒掉!他們什麼都不該擁有!聽到了沒!不留一物!他們必須為他們過去以及將來所犯下的罪行付出代價。如果我能掙脫這些可惡的枷鎖，我將親自殺死瓦許。或是你想做奈普圖隆的工作?她的死亡對我們都有利，軟皮膚的。你願意幫我組成這隻神聖的鬥棍。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10901, 'zhTW', '卡德許的鬥棍', '為我帶來這根鬥棍需要的元素徽記!$B$B土靈徽記為弒龍者戈魯爾所持有。戈魯爾可在劍刃山脈中的巢穴裡面找到。$B$B第二個徽記是一個叫做夜禍的生物的燃燒之心。這隻神話般的野獸據說住在先知麥迪文的神聖大廳裡。$B$B動作快!', '盤牙蓄湖中奴隸監獄的『異端』司卡利斯要你帶給他土靈徽記和熾烈徽記。', '', '去盤牙水庫找奴隸圍欄的異教徒斯卡希斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10902 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10902, 'zhTW', '大師級藥劑', '我終生致力於藥劑製作的完善技術。盡管我目前很成功，我還是無法製造長生不老的藥劑。$B$B我想我知道我所缺少的試劑。我聽說艾澤拉斯有個地方叫做時光之穴，時空的侵入者裂縫領主還有裂縫看守者都在那邊逐步入侵還有離開時間線。$B$B這種侵入性的時空轉移在時間線上製造了裂縫，最後扭曲形成晶化的精華。將這些精華還有你做出來的樣本帶給我然後我就會教你我所知道的東西。', '去時光之穴的黑色沼澤從裂縫領主還有裂縫看守者身上取得10個無限精華。同時帶著5個極效防禦藥劑、5個專精藥劑還有5個極效敏捷藥劑交給撒塔斯的陰鬱城的羅洛其恩。*警告!*你只能選擇一種鍊金術專精。', '', '去找撒塔斯城的羅羅基姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10903, 'zhTW', '返回榮譽堡', '$n，當你在執行薩斯葛爾的任務時，我接獲我的指揮官，喬渥上校的消息。他在戈卡茲崗哨附近戰鬥時被惡魔的腐敗侵襲，而他的情況已經變得非常糟。$B$B你已經在對抗魔獄獸人上為我們贏得這樣大的斬獲。你在戰鬥中的力量毫無疑問……而你的精神是否一樣堅強?$B$B請返回榮譽堡與克拉圖談話，他在榮譽堡旅店的上層房間內。', '與助手克拉圖談話，他在榮譽堡的旅店裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10904, 'zhTW', '獲得魔化彈藥', '我們必須關閉燃燒軍團進入死亡之門的通道，但是首先你必須破壞他們的兩扇星移門!$B$B問題是，我們現在根本無法對那些東西造成損傷，所以你必須使用他們自己的武器對抗他們。$B$B死亡的力量，死亡看守，死亡熔爐鐵匠和死亡熔爐技師攜帶著惡魔火砲的彈藥。$B$B一般來說，它不會影響他們任何人，但是如果你把彈藥帶來給我，我將為它們注入自然放縱的憤怒!', '永恆樹林德魯伊要你收集5個惡魔砲彈。等你完成，就到劍刃山脈使用德魯伊信號召喚死亡之門內的永恆樹林德魯伊。', '', '去刀鋒山的死亡之門內用德魯伊訊號彈召喚常青林德魯伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10905 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10905, 'zhTW', '大師級藥水', '我的鍊金術知識很廣泛。不過，它的本質是很普通的。如果你希望專攻其中的一門領域，你必須找到專精該門研究的人。$B$B如果你希望專精於藥水，我建議你尋求塞納里奧遠征隊的羅安娜·薩威爾幫助。$B$B她對植物的知識將讓你可發揮原料的最大作用。到贊格沼澤找她，並告訴她是我叫你到她那裡的。', '跟贊格沼澤的塞納里奧避難所的羅安娜·薩威爾交談。*警告!*你只能選擇一種鍊金術專精。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10906 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10906, 'zhTW', '大師級藥劑', '我的鍊金術知識很廣泛。不過，它的本質是很普通的。如果你希望專攻其中的一門領域，你必須找到專精該門研究的人。$B$B如果你希望專精於藥劑方面，我建議你去找一個叫羅洛其恩的阿拉卡尋求幫助。$B$B他在藥劑上的知識是無人能比的，但他卻把技巧浪費在追尋永生的藥劑上。找到他看看他能教你什麼。', '跟撒塔斯城的陰鬱城的羅洛其恩交談。*警告!*你只能選擇一種鍊金術專精。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10907 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10907, 'zhTW', '大師級轉化', '我的鍊金術知識很廣泛。不過，它的本質是很普通的。如果你希望專攻其中的一門領域，你必須找到專精該門研究的人。$B$B如果你希望專精於轉化，我建議你尋求一個叫薩爾菲的伊斯利幫助。他居住於虛空風暴的風暴之尖。$B$B他對轉化的精通是……嗯，很古怪的!看看你能向他學些什麼，但是注意 - 伊斯利很會討價還價。', '跟虛空風暴的風暴之尖的薩爾菲談話。*警告!*你只能選擇一種鍊金術專精。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10908 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10908, 'zhTW', '跟『贖罪者』里拉克談談', '跟我談話的你看起來很驚訝。我不怪你。我的族人，阿拉卡本來就該被人所畏懼。$B$B假如你想知道更多的事情，你應該去跟撒塔斯城的『贖罪者』里拉克談話。他在陰鬱城的北部，跟司凱堤斯其他的流亡者在一起。$B$B最後，$n，我們會再交談的。', '『覺醒者』奇瑞克要你跟撒塔斯的陰鬱城區內的『贖罪者』里拉克談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10909 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10909, 'zhTW', '惡魔靈魂', '喬渥上校在葛卡茲哨站附近的一次戰鬥中被詛咒了，那是一個破碎之手魔獄獸人常出沒的地方。我的主人，巴瑞達心急如焚地工作以治癒不幸的人，但是他需要幫助。上校的痛苦靈魂在尋找平靜，而他通向平靜的道路，我擔心是一條復仇的道路。$B$B把這個隱士聖物拿到葛卡茲哨站。把它放置在靠近破碎之手獸人的地上並且擊敗他們。這將釋放他們的邪惡靈魂 -- 你必須為喬渥靈魂的恢復殺死那些邪惡靈魂。', '榮譽堡的克拉圖要你在榮譽堡西南方的葛卡茲哨站使用隱士聖物，殺死聖物附近的破碎之手狂戰士，再殺死10個被釋放的惡魔靈魂來為喬渥上校復仇。', '', '去地獄火半島找榮耀堡的助手克拉圖。', '為尤勒斯復仇', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10910 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10910, 'zhTW', '死亡之門', '現在燃燒軍團有一個更大的威脅。南邊有一個被人稱為死亡之門的傳送門，它開啟另一個可怕的世界，燃燒軍團在那邊養殖他們致命的地獄獵犬。$B$B要去那裡，就離開永恆樹林往東邊斜坡上去。沿著往南的路走，通過刀刃峽谷，雷森平台，剃刀山脊和鱗翼沙洲。然後，走下斜坡進入維克哈爾看臺，再通過摩克納薩爾南邊的隧道進入死亡之門。$B$B當你到達的時候，使用這個德魯伊信號。', '野蠻領主安德烈利安請你到死亡之門。到達之後，使用德魯伊信號召喚一個永恆樹林德魯伊好讓你可以跟他們談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10911 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10911, 'zhTW', '自由開火!', '既然那些彈藥可以影響燃燒軍團，是時候讓你使用它了。$B$B他們有兩個星移門用來傳送還有加強他們的虛無恐獸。一個在北邊一個在南邊，但是兩個都在惡魔火砲的射程範圍內。$B$B使用同化彈藥以取得各個惡魔火砲的控制權並摧毀星移門。$B$B讓砲隊先展開攻擊，必要的話準備殺死它的防衛者讓火砲保留下來。', '使用同化彈藥以取得死亡之門的惡魔火砲控制權。使用它們來摧毀南方星移門還有北方星移門。然後，使用德魯伊信號召喚一個永恆樹林德魯伊來回報你的勝利。', '', '去刀鋒山的死亡之門使用德魯伊訊號彈召喚常青林德魯伊。', '摧毀南部遷躍門', '摧毀北部遷躍門', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10912 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10912, 'zhTW', '魔犬之主', '『魔犬之主』貝爾蒙必須死!就是他主持的儀式使得死亡之門維持運作。$B$B死亡之門位在山谷的北方盡頭。你到了那邊就可以找到埃雷達爾。$B$B你將會需要幫忙，帶著這把魔杖。當你跟貝爾蒙戰鬥的時候使用它，然後我的幾位朋友就會出來協助你。$B$B擊敗了埃雷達爾之後回去找野蠻領主安德烈利安。$B$B另外，$n，感謝你為了我們所做的努力。', '永恆樹林德魯伊告訴你最後的一件事是殺死『魔犬之主』貝爾蒙。任務完成後，回到劍刃山脈的永恆樹林向野蠻領主安德烈利安回報。', '', '去刀鋒山找常青林的荒野之王安塔裡恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10913 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10913, 'zhTW', '不適當的葬禮', '沒有任何事情可以阻止腐敗的蔓延嗎?我的士兵已經與奧奇奈持續戰鬥數天，而且不知道什麼時候才能終止這場戰爭。每起傷亡，無論是奧奇奈還是薩塔的陣亡者魂魄，均從戰場上被抓走 - 他們的靈魂升起並且被帶到未知的地方。$B$B我不允許這種事情發生!在戰場上一個適當的葬禮是不可能的，但是那些惡魔不能奪走他們的靈魂!帶著這支火炬前往戰場，從這裡直接向東走。燒掉你看見的每具屍體!我們不能獻給惡魔儀式更多無辜的靈魂。', '泰洛卡森林白骨荒野，薩塔前哨的指揮官洛沃要你燒毀8個陣亡的奧奇奈戰士還有8個陣亡的薩塔復仇者。', '', '去泰羅卡森林找白骨荒野的指揮官拉瓦伊。', '焚燒被殺死的沙塔爾守備官的屍體', '焚燒被殺死的奧金尼戰士的屍體', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10914 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10914, 'zhTW', '需要一位英雄', '這樣是不夠的。我們需要一位英雄。我們的部隊被奧奇奈日漸增加的數目給擊敗了。$B$B<指揮官洛沃看著你。>$B$B你願意當我們的英雄嗎?回到戰場上殺死他們的士兵。讓他們無暇分神好讓我的斥候潛入他們的後方，然後看他們在製作什麼東西。', '泰洛卡森林白骨荒野，薩塔前哨的指揮官洛沃要你殺死12個奧奇奈新教徒還有5個奧奇奈末日預言者。', '', '去泰羅卡森林找白骨荒野的指揮官拉瓦伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10915 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10915, 'zhTW', '墮落的主教', '他們將偷來的靈魂奉獻給他們從奧奇奈地穴拖出來的一個棺材。我的斥候相信棺材的裡面包含了地穴的首位主教。他們想要復活這位古老的主教!$B$B你必須一路打進奧齊頓的西邊然後在他們奉獻足夠的靈魂之前阻止棺材裡面的東西。萬一你迷路，就跟隨其他的靈魂走。$B$B摧毀那個棺材裡面的東西!', '泰洛卡森林白骨荒野，薩塔前哨的指揮官洛沃要你摧毀奧奇奈棺材的內容物。', '', '去泰羅卡森林找白骨荒野的指揮官拉瓦伊。', '摧毀奧金尼棺材中的生物', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10916 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10916, 'zhTW', '挖掘祈禱珠串', '隱士巴瑞達計畫驅除喬渥上校體內的腐敗根源，因此他需要一個助手。我需要的助手一定要做好準備......$B$B我很羞愧地承認我的祈禱珠串遺失在榮譽堡的庭院裡了。我覺得是菲菲這隻狗偷了珠串並且埋了起來，但是我不知道在那裡。如果你與菲菲的主人，士官長崔西·波特威歐談話，或許她會知道菲菲將它偷來的財寶藏在那裡。', '尋回德萊尼祈禱珠串然後交給榮譽堡的助手克拉圖。', '', '去地獄火半島找榮耀堡的助手克拉圖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10917 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10917, 'zhTW', '流亡者的困境', '身為一個流亡者，我身上被效忠於司凱堤斯城的阿拉卡標上了死亡的記號。為了生存我不能離開這些城牆，但那並不表示我不能給他們復仇的一擊。$B$B我有一小堆寶物願意分享，只要你幫我對付那些我想要成為的刺客。把泰洛卡迷霧裡不同居民的羽毛帶來給我做為他們死亡的證據。', '帶30根阿拉卡羽毛到撒塔斯的陰鬱城給威卡斯。', '', '去撒塔斯城找貧民窟的維卡克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10918 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10918, 'zhTW', '更多的羽毛', '', '司凱堤斯的手下仍然在不遠的距離監視著我們這些流亡者。現在所有我們在撒塔斯城外的人都離死不遠。幫我帶回來更多的羽毛當作你戰勝他們的證明。', '', '去撒塔斯城找貧民窟的維卡克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10919 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10919, 'zhTW', '菲菲的狗餅乾', '', '', '', '去找地獄火半島的菲菲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10920 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10920, 'zhTW', '為了垂死的同伴', '當那些懼牙寡婦攻擊我們的前哨站時，我們聽到那魯的聲音呼喚我們去戰鬥。我們在夜色中追捕那些生物。在黑暗中我們發現有些人死了，我們還可以聽到其他的人因為反抗那些捉住他們的人而發出的掙扎聲。$B$B到了早上我們來到這裡，發生了一場激烈的戰鬥，不過我們被打敗了。懼牙的毒液很快就會奪走我同伴的生命而我也撐不了多久。我希望在我死以前可以知道那些懼牙寡婦已經被打敗了。', '復仇者赫藍要你殺死20隻懼牙寡婦然後回到幽網山脊的西邊找他。', '', '去白骨荒野的靈網山脊邊緣找守備官海雷恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10921, 'zhTW', '泰洛卡狼蛛', '你已經殺死許多懼牙寡婦但是他們還是會不斷的繁殖並且不久之後就會再度攻擊我們。幽網山脊是泰洛卡狼蛛的巢穴，她是這些可怕生物的母親。假如我們想要安全的話，她就必須死亡。', '復仇者赫藍要你殺死泰洛卡狼蛛然後回到幽網山脊的西邊找他。', '', '去白骨荒野的靈網山脊外面找守備官海雷恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10922, 'zhTW', '挖掘骨頭', '喂!你看起來像是可以照顧自己的人，$r。我跟我的工作人員正在尋找一個可以保護我們到北邊挖掘場的保鏢。這份工作的薪水很好而且你只要確保沒有噁心的生物會殺死我或者我的工作人員就可以了。$B$B假如你成功的保護我們的人員無傷亡的回來，在那邊的德拉弗懷玆會付錢給你。', '護送里同還有他的工作人員然後在他們挖掘的時候保護他們。任務完成後回到薩塔前哨找德拉弗懷玆。', '保護探險家們', '去泰羅卡森林找白骨荒野的杜瓦弗維茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10923, 'zhTW', '邪惡逼近', '如果你希望挑戰受詛咒的泰利巴斯，現在你必須在一個邪惡的死靈儀式裡使用恐怖聖物。到東北方去，在越過奧齊頓的苦痛山丘，一個死靈法師聚集的地方。$B$B那裡的奧奇奈亡語者和末日預言者帶著具有強大死靈魔力的厄運頭顱。如果你收集了足夠的頭顱，你就能使用它們的魔力配合恐怖聖物的力量強迫泰利巴斯面對你的挑戰。', '歐肯要你把恐怖聖物帶到苦痛山丘。一旦到了那裡，殺死奧奇奈亡語者和奧奇奈末日預言者，並收集20顆厄運頭顱。然後找到苦痛山丘召喚法陣並且使用恐怖聖物召喚並消滅受詛咒的泰利巴斯。任務完成時，回到歐肯那裡。', '', '去白骨荒野找沙塔爾營地的沃爾昆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10924, 'zhTW', '血任務!', '這區域的扭曲追趕者鮮血是一種強大又稀有的施法材料。它是我店裡銷售最好的物品。$B$B平常我都帶著我的小鬼，塞皮跟我一起去收集。扭曲追趕者的血對你我來說都具有腐蝕性且很難安全的收集，但是卻難不倒塞皮。$B$B店裡的生意越來越忙，所以假如我派塞皮跟你去，你願意幫忙我收集鮮血嗎?塞皮的注意力不集中，所以你必須在殺死扭曲追趕者的時候靠近一點好讓塞皮完成他的工作。', '帶8罐扭曲追趕者之血給扭曲太空的沙布奧斯。', '', '去虛空風暴找扳鉗鎮的薩布奧斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10925 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10925, 'zhTW', '邪惡將至', '', '', '', '去找。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10926, 'zhTW', '回到薩塔營地', '我們沒力氣回去了。那些懼牙的毒液效果太強了。你必須幫我們回報薩塔營地。斥候納夫靈會派一支救援隊來尋找我們。', '復仇者赫藍要你回到薩塔營地跟斥候納夫靈談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10927, 'zhTW', '殺光爬行者', '指揮官天影要清空這條通道以促進我們跟避難營的貿易。我不能離開我的哨站所以我只好把任務交到你的手裡。清空通道然後馬上回報指揮官天影!', '連接贊格沼澤和劍刃山脈隧道的哨兵月語要你殺死6隻洞穴爬行者然後回報希爾瓦納的指揮官天影。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10928, 'zhTW', '殺光爬行者', '吐查克·雙爪要清空這條通道以促進我們跟沼澤叛徒的交易。我不能離開我的哨站所以我把任務交到你的手上。清空這個通道然後馬上回報吐查克·雙爪!', '連接贊格沼澤和劍刃山脈隧道的蠻兵葛拉赫要你殺死6隻洞穴爬行者然後回報雷霆王村的吐查克·雙爪。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10929 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10929, 'zhTW', '太鼓之音', '你願意怎樣為探險者協會做更多工作?這些白骨蟲完全激起我們的興趣。$B$B這裡有一面我的鼓，你可以在白骨荒野使用它。只要在這討厭的東西上敲擊，看看你會得到什麼回應。如果它是一條白骨蟲，殺死它並把屍體帶回給我們研究。我們將需要一批完好的屍體以得到一個有效的測試樣品。', '白骨荒野的薩塔前哨的德拉弗懷玆要你帶給他8個成熟骨質分解屍體。', '', '去泰羅卡森林找白骨荒野的杜瓦弗維茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10930, 'zhTW', '巨大白骨蟲', '我是對的!你帶給我的這些屍體屬於白骨蟲幼蟲。你知道那表示什麼嗎?它表示在外面的某處有一隻大的!我認為如果我們能提供正確的食物，就能引誘它出來。讓我們看看……需要大型的屍體誘餌!是的!$B$B我記得在這東邊白骨荒野的另一邊看見過裂蹄。到那去並殺掉一隻裂蹄。一旦它死了，就敲響鼓。希望會那隻大蟲會出來吃它。如果有，你就設法殺死它，並把它的器官帶來給我!', '白骨荒野的薩塔前哨的德拉弗懷玆要你取得巨大的白骨蟲器官。他同時也想要回他的太鼓。', '', '去泰羅卡森林找白骨荒野的杜瓦弗維茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10931, 'zhTW', '回到艾克索達', '你在艾克索達的主人希德摩斯想見你。他關切你的訓練進度，除此之外的事情我不太清楚。', '跟艾克索達的希德摩斯談話。', '', '', '', '', '', '', 0);
