INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10935, 'zhTW', '喬渥上校的驅邪儀式', '$n，現在該拯救喬渥上校了。他的情況惡化了，而且巴瑞達擔心假如我們不淨化他的腐化，那麼我們將會失去他。$B$B帶著你找到的珠串去跟隱士巴瑞達談話並且開始淨化的祭儀。別讓任何事情打擾了祭儀...假如一切順利，喬渥上校就會得救。當喬渥得救了以後跟他談話，然後跟我回報。', '跟隱士巴瑞達談話。使用祈禱珠串幫助祭儀進行，然後等上校得救以後跟他談話。最後，回報助手克拉圖。', '', '去地獄火半島找榮耀堡的助手克拉圖。', '拯救尤勒斯上校', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10936 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10936, 'zhTW', '托爾貝恩正在找你', '我們在交談的時候，有一位信差在大廳等著。我想他等的累了或者他趁喬渥沒注意的時候跑走了。$B$B總而言之，軍隊指揮者達納斯正在找你。我建議你馬上去兵營裡頭見他!', '助手克拉圖告知你軍隊指揮者達納斯·托爾貝恩正在找你。到地獄火半島，榮譽堡裡的兵營跟他談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10937 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10937, 'zhTW', '殺死訓練員蘇洛克', '我收到消息指出地獄火堡壘前外的破碎之手魔獄獸人正在組織一個全面的攻擊行動。毫無疑問的，他們對於你打敗他們一些氏族的這件事感到不太高興。$B$B前往地獄火堡壘，就在光榮之路的盡頭。你會發現那些魔獄獸人正忙著做戰前的準備，而你的出現將使他們大吃一驚。$B$B殺死那邊的指揮者。殺死訓練員蘇洛克!', '軍隊指揮者達納斯·托爾貝恩命令你盡快殺死訓練員蘇洛克。一旦殺了訓練員後就回到地獄火半島的榮譽堡向軍隊指揮者回報。', '', '去地獄火半島找榮耀堡的遠征軍指揮官達納斯·托爾貝恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10938 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10938, 'zhTW', '暗月祝福套牌', '你現在已經收集到了祝福套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。', '當暗月馬戲團來到鎮上的時候，把祝福套牌交給他們。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10939 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10939, 'zhTW', '暗月風暴套牌', '你現在已經收集到了風暴套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。', '當暗月馬戲團來到鎮上的時候，把風暴套牌交給他們。', '', '', '', '', '', '', 0);
