INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10941, 'zhTW', '暗月愚人套牌', '你現在已經收集到了愚人套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。', '當暗月馬戲團來到鎮上的時候，把愚人套牌交給他們。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10942 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10942, 'zhTW', '兒童週', '有你做伴，哪怕只有很短的幾天，我們的這位小姑娘也一定會非常開心。$B$B收下這隻孤兒哨吧。只要吹響它，就可以召喚出你要照看的小孩子。你只需要負責照顧她一段時間就可以了——實際上就是兒童週期間。$B$B$N，召喚出這個孩子吧。她肯定迫不及待地想要跟你見面，隨你探索城外的美麗世界！', '使用血精靈孤兒哨召喚出你將在兒童週期間照看的小孩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10943, 'zhTW', '兒童週', '有你做伴，哪怕只有很短的幾天，我們的這位小姑娘也一定會非常開心。$B$B收下這隻孤兒哨吧。只要吹響它，就可以召喚出你要照看的小孩子。你只需要負責照顧她一段時間就可以了——實際上就是兒童週期間。$B$B$N，召喚出這個孩子吧。她肯定迫不及待地想要跟你見面，隨你探索城外的美麗世界！', '使用德萊尼孤兒哨召喚出你將在兒童週期間照看的小孩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10944 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10944, 'zhTW', '保守的秘密', '再次感謝你，$n。我認得你。阿卡瑪將他轉而對付伊利丹的計畫託付給你因此我也信任你。$B$B納迦發現我反抗伊利丹的事實而且對我嚴刑拷問。我並沒有告訴他們任何事情 - 阿卡瑪教我如何透過冥想克服痛楚。$B$B伊利丹命令那些納迦把我送到他的手上，因為伊利丹本人可以看穿我的這副身軀並且直接窺視我心中最深處的秘密。$B$B我們必須警告阿卡瑪。我們的計畫處於危險之中!', '前往影月谷的典獄官監牢並且跟阿卡瑪交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10945 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10945, 'zhTW', '哈克烏和蘑菇人', '我有個朋友叫哈克烏。她說她曾經被邪惡的真菌巨人追趕，慌亂之中迷了路，所幸被孤兒院收留。$B$B我們在這兒快樂地生活著，直到去年她的家人得知她的下落，接她離開了孤兒院。我記得她住在一個名叫孢子村的地方。$B$B我想去看看她和她生活的蘑菇村莊。孤兒院監護員說孢子村就在孢子湖和沼光湖之間，就在贊加沼澤西部。$B$B帶我去好嗎？帶我去好嗎？求你了？！', '帶上孤兒薩蘭蒂亞，轉至位於贊加沼澤的孢子村。如果你抵達時發現她不在身邊，記得要先召喚她。然後，跟哈克烏談一談。', '帶薩蘭蒂亞轉至孢子村', '去找贊加沼澤的哈克烏。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10946 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10946, 'zhTW', '灰舌偽裝', '歐蘭的犧牲對我們的打擊很大。我真不該叫他犧牲自己的生命。但是該發生的已經發生了。$B$B如果我們想欺騙伊利丹，給他局勢安定的錯覺，我們必須聽從他的命令 - 至少現在必須這麼做。$B$B我有一支龐大的灰舌部族軍隊，但是 - 不屬於死亡誓言者 - 沒有人可以相信。$B$B你必須要完成伊利丹的命令。帶著這頂風帽;它蘊含著魔法的力量。任何看到你殺死凱爾的鳳凰---歐爾的人都會認為你是我的一名手下。', '前往風暴要塞並且戴上灰舌風帽殺死歐爾。完成任務後回到影月谷找阿卡瑪。', '灰舌氏族的詭計', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10947, 'zhTW', '古老的神器', '伊利丹的焦點已經轉向凱爾薩斯，這都要感謝你。是時候該我們行動了。$B$B預兆告訴我一個神器將會在我們的最後一戰中幫忙我們 - 一個被人稱為凜冬的巫妖所佩帶的骨匣。可惜的是自從他在海加爾山戰役被擊敗之後，骨匣的力量就消失了。$B$B然而，應該有方法可以取得這個神器。傳說中艾澤拉斯有一處由青銅龍守衛的地方...一處過去與現在的交會處。你將會在那裡找到我們要尋找的東西。', '前往塔納利斯的時光之穴並且進入海加爾山戰役。進入之後，擊敗瑞齊‧凜冬並且將時間定相骨匣交給影月谷的阿卡瑪。', '', '去影月谷找守望者牢籠的阿卡瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10950 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10950, 'zhTW', '奧金頓的儀式廣場', '有位路經孤兒院的牧師跟我們講過奧金頓的故事，據說那地方對德萊尼一族至關重要，就在這附近哦。$B$B他說奧金頓曾經是德萊尼人的埋骨地，但是不久前發生了爆炸事件。$B$B我想去奧金頓的儀式廣場看看。孤兒院監護員說那地方就在白骨荒野的中間，泰羅卡森林的南部。$B$B親愛的$N$G先生:小姐，拜託你，帶我去好嗎？', '帶上孤兒多爾南，轉至位於奧金頓中心儀式廣場的集合石。奧金頓就在泰羅卡森林內的白骨荒野的中心地帶。如果你抵達時發現她不在身邊，記得要先召喚她。', '帶多爾南轉至儀式廣場', '使用你的孤兒哨召喚德萊尼孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10951, 'zhTW', '參觀黑暗之門', '我們遊覽了這麼多有趣的地方，怎麼能錯過黑暗之門呢？！$B$B大人們總是跟我們講那些關於黑暗之門的恐怖故事，他們說那兒有很多惡魔和其它詭異生物，總之是個非常危險的地方。$B$B<薩蘭蒂亞轉動著眼珠。>$B$B但是有你保護我，情況應該不會太糟，是嗎？$B$B我想去親眼看看。黑暗之門應該在地獄火半島東部邊緣吧，你還記得確切的方位嗎？', '帶上孤兒薩蘭蒂亞，登上命運階梯，站在地獄火半島的黑暗之門前。如果你抵達時發現她不在身邊，記得要先召喚她。', '帶薩蘭蒂亞轉至黑暗之門', '使用你的孤兒哨召喚血精靈孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10952 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10952, 'zhTW', '參觀黑暗之門', '要是我們沒別的地方可去，那就去黑暗之門吧！$B$B孤兒監護員們總是說那兒很危險，居住著很多惡魔什麼的，還說只有象你這樣的英雄才能跨越黑暗之門。$B$B<多爾南轉動著眼珠。>$B$B但是有你保護我，情況應該不會太糟，是嗎？$B$B我真得很想去親眼看看。黑暗之門就在地獄火半島東部邊緣吧，你還記得確切的方位嗎？', '帶上孤兒多爾南，登上命運階梯，站在地獄火半島的黑暗之門前。如果你抵達時發現她不在身邊，記得要先召喚她。', '帶多爾南轉至黑暗之門', '使用你的孤兒哨召喚德萊尼孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10953 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10953, 'zhTW', '參觀元素王座', '你知不知道元素王座這個地方？據說啊，它就在納格蘭大草原上，那兒有許多許多強大的元素生物。$B$B很快，我就要變成為一個厲害的法師了，或者術士也行！我得掌握駕馭元素力量的能力。$B$B要不咱倆一起去元素王座？$B$B<薩蘭蒂亞狡猾地看著你。>$B$B你肯定會獲益良多的！那地方就在加拉達爾北邊，天歌湖的對岸。', '帶上孤兒薩蘭蒂亞，轉至位於納格蘭的元素王座。如果你抵達時發現她不在身邊，記得要先召喚她。然後，與元素師沙爾瓦克談一談。', '帶薩蘭蒂亞轉至元素王座', '去找納格蘭的元素師沙爾瓦克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10954 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10954, 'zhTW', '埃瑞斯碼頭的希爾！', '我有點想念我的哥哥希爾了。他比我大幾歲，所以監護員們讓他去納格蘭給虛靈們當學徒了。$B$B要是能去看看他就好了。他一直很喜歡地質學一類的東西，想必他在那兒過得挺開心的。$B$B孤兒監護員跟我說他在納格蘭一處名叫埃瑞斯碼頭的地方受訓。埃瑞斯碼頭就位於沃舒古山脈的西北方，沿著塔拉西邊的道路一直走就能到。', '帶上孤兒多爾南，轉至位於納格蘭的埃瑞斯碼頭。如果你抵達時發現她不在身邊，記得要先召喚她。然後與希爾談一談。', '帶多爾南轉至埃瑞斯碼頭', '去找納格蘭的希爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10955 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10955, 'zhTW', '莫希斯·輕翼', '早在塞納里奧議會統一所有的德魯伊教派之前，猛禽德魯伊就負責將飛行的訣竅傳授給那些年輕有為的德魯伊。猛禽德魯伊教派解散後，原先的成員在傳授飛行訣竅時就更為小心謹慎了。$B$B莫希斯·輕翼仍然在挑選合適的學徒，只有為數很少的德魯伊能掌握各種形態，不過你似乎可以滿足莫希斯對學生的要求。去贊加沼澤的塞納里奧庇護所找他吧。', '與贊加沼澤塞納里奧庇護所的莫希斯·輕翼談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10956 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10956, 'zhTW', '納魯之座', '你知道納魯的故事嗎？這些天使般的神靈一直以來都在無私地幫助德萊尼人。我曾在撒塔斯城附近見過他們。$B$B他們說有一位名叫沃洛斯的納魯去了你們的世界，就在艾克索達城中。我想親眼看看他。$B$B你能帶我去嗎？我敢打賭，要是我們利用撒塔斯城聖光廣場的傳送門，一定很快就能到達那兒！要是你在艾克索達中迷了路，可以隨時檢視你的地圖。', '帶上孤兒多爾南轉至藍謎島的艾克索達，將她帶到納魯之座底部的沃洛斯面前。如果你到達時她不在你身邊，記得召喚她。$B$B進入主城後你可以檢視地圖確定沃洛斯的位置。', '帶多爾南轉至納魯之座', '去藍謎島找艾克索達的沃洛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10957, 'zhTW', '灰舌的救贖', '當伊利丹獲得破碎者的擁戴時，阿卡瑪是我們之中最有智慧的一個人。他知道公開對抗背叛者會讓我們的種族滅絕。$B$B因此他在最高機密的情況下密謀策劃了這重要的一刻。失敗會造成大災難...不只是對阿卡瑪，不只是對破碎者，而是對整個外域。和伊利丹這麼親近的人沒有一個能對他造成這樣可怕的打擊。$B$B幫助阿卡瑪釋放他的靈魂，他就能讓你進入伊利丹的聖所。', '擊敗黑暗神廟中阿卡瑪的陰影來幫助阿卡瑪奪回他的靈魂。完成後回到先知卡奈那裡。', '', '去找黑暗神廟的先知卡奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10959, 'zhTW', '背叛者之死', '等伊利丹的副官被擊敗，阿卡瑪就能衝破伊利丹的聖所之門。只要阿卡瑪這麼做你就準備好帶著軍隊進入。$B$B我們仍然不清楚瑪翼夫發生什麼事，但是就算沒有她我們也要繼續前進。$B$B希望你的軍隊足以應付這個任務。伊利丹不會樂於見到阿卡瑪。', '先知卡奈要你擊敗黑暗神廟裡的伊利丹。', '', '去找黑暗神廟的先知卡奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10960, 'zhTW', '等我長大了……', '你在我這個年紀時，能確定自己長大後要成為一名$c嗎？$B$B反正現在我還不太確定呢。法師？術士？或是聖騎士？血騎士？啊，我要成為一名血騎士！$B$B他們說真正的血騎士在銀月城傳授聖光的教義，那是你們的世界吧。你能帶我去那兒嗎？我聽說聖騎士訓練師在銀月城的遠行者廣場。$B$B帶我去吧。求你了！', '將孤兒薩蘭蒂亞帶到銀月城遠行者廣場的聖騎士訓練師面前。如果你到達時她不在你身邊，記得召喚她。然後跟血騎士的領袖女伯爵莉亞德琳談談。$B$B進入主城後你可以檢視地圖並詢問衛兵，確定聖騎士訓練師的位置。', '帶薩蘭蒂亞轉至銀月城拜訪聖騎士訓練師', '去找銀月城的女伯爵莉亞德琳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10961, 'zhTW', '喚醒戒衛', '很久之前，用於傳授風暴烏鴉形態知識的聖物被託付給克林塔爾·夢行者保管。$B$B克林塔爾的軀體在月光林地的獸穴中休眠，他的靈魂則在翡翠夢境中徜徉。$B$B我得準備一劑可以令他的靈魂復甦的藥膏。製造這種混合劑需要一些普通的草藥，還有生長在贊加沼澤高大的蘑菇頂端的沼澤花。採集沼澤花的時候要小心，它們非常脆弱，而且可能會爆發出致命的毒氣。', '將10株沼澤花、10簇遠古苔和10株夢露花交給塞納里奧庇護所的莫希斯·輕翼。', '', '去找贊加沼澤的莫希斯·輕翼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10962, 'zhTW', '參觀時光之穴', '曾經有位年老的牧師路經孤兒院，給我們講過時空之穴的故事。他說位於時間中心的時空之穴起著維護歷史程序的重要作用。$B$B我不知道那是什麼意思，但是他說那兒駐守著守護世界的龍族！我想看看龍長什麼樣！$B$B我們可以去時空之穴嗎？那位牧師說入口就在那片名叫塔納利斯的沙漠東部邊緣。$B$B我們去了那裡之後，你能給我買件紀念品嗎？', '將孤兒多爾南帶到時光之穴中央平臺上的扎拉多姆面前。如果你到達時她不在你身邊，記得召喚她。$B$B然後在時間守護者的軍需官艾魯爾米那兒為她購買一個玩具龍，艾魯爾米就在入口通道底部附近。', '帶多爾南轉至時光之穴', '使用你的孤兒哨召喚德萊尼孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10963, 'zhTW', '參觀時光之穴', '曾經有位年老的牧師路經孤兒院，跟我們講起時光之穴的故事。他說位於時間中心的時光之穴起著維護歷史程序的重要作用。$B$B我不知道那是什麼意思，但是他說那兒駐守著守護世界的龍族！我真想看看龍是長什麼樣的啊！$B$B我們可以去時光之穴嗎？那位牧師說入口就在那片名叫塔納利斯的沙漠東部邊緣。$B$B還有還有，我們去了之後，你可以給我買件紀念品嗎？', '將孤兒薩蘭蒂亞帶到時空之穴中央平臺上的扎拉多姆面前。如果你到達時她不在你身邊，記得召喚她。$B$B然後在時光守護者的軍需官艾魯爾米那兒為她購買一個玩具龍，艾魯爾米就在入口通道底部附近。', '帶薩蘭蒂亞轉至時光之穴', '使用你的孤兒哨召喚血精靈孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10964, 'zhTW', '喚醒沉睡者', '帶上喚醒戒衛轉至月光林地的怒風獸穴。克林塔爾·夢行者就在最南端的那個駐有夢境守衛者的洞穴中。$B$B喂他服下藥膏，等待他慢慢甦醒。在克林塔爾·夢行者的靈魂與身體重新結合的過程中，他會處於異常脆弱的狀態；當然，他是不可能認出你的。$N，一旦他恢復神志，請立即通報你的身份。他需要你的幫助才能收集到儀式所需的聖物。', '使用喚醒戒衛幫助克林塔爾·夢行者從翡翠夢境中甦醒。當他恢復意識後跟他談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10965, 'zhTW', '夢境危機', '<克林塔爾聽你傳達莫希斯的指示，他點著頭，臉上卻流露出憂慮的神情。>$B$B我無法完全從翡翠夢境中脫身，但是這塊取自我的靈魂的碎片可以幫助你尋找聖物。$r，好好保護它，這東西相當脆弱。$B$B翡翠夢境已經成為了危機重重的是非之地。它緊緊地抓住我，只有等這兒恢復正常，我才可能全身而退。你所看到的不過是夢境中折射出的影像！', '在克林塔爾·夢行者的靈魂收集艾維娜聖物時保護他，然後與夢境衛士魯羅薩談一談。', '', '去月光林地找月神湖的夢境衛士魯羅薩。', '協助克林塔爾收集聖物', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10966, 'zhTW', '返回孤兒院', '糟糕！我該返回撒塔斯城的孤兒院了。$B$B跟你在一起的日子非常愉快。$N，你是世界上最好的人！就像我的大$g哥哥:姐姐;一樣！$B$B<多爾南的眼中泛起淚花。>$B$B我會想你的！長大之後，我要做一個像你一樣的人！！！', '將德萊尼孤兒哨歸還給撒塔斯城貧民窟的孤兒院長莫希。', '', '去找撒塔斯城的孤兒院長莫希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10967, 'zhTW', '返回孤兒院', '糟糕！我該返回撒塔斯城的孤兒院了。$B$B跟你在一起的日子非常愉快。$N，你是世界上最好的人！就像我的親$g哥哥:姐姐;一樣！$B$B<薩蘭蒂亞的眼中泛起淚花。>$B$B我會想你的！長大之後，我要做一個像你一樣的人！！！', '將血精靈孤兒哨歸還給撒塔斯城貧民窟的孤兒院長莫希。', '', '去找撒塔斯城的孤兒院長莫希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10968, 'zhTW', '拜訪預言者', '我感覺得出，這孩子頗有與眾不同之處。$B$B你應該帶她去見艾克索達的預言者努波頓。我想他一定盼著你們倆呢。$B$B努波頓大人就在水晶大廳的最頂層。', '帶上孤兒多爾南，轉至藍謎島艾克索達的水晶大廳拜訪預言者努波頓。如果你到那兒時她不在你身邊，記得召喚出她來。$B$B記住，你在城裡可以檢視地圖。', '帶多爾南拜訪預言者努波頓', '去藍謎島找艾克索達的預言者努波頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10969, 'zhTW', '尋找阿密爾', '看起來有一股外來的勢力對聯合團的商業活動虎視眈眈。在過去兩天內已經有5名聯合團商人失蹤了。我們有理由相信伊斯利恩罪嫌重大。假如你想協助我們的話就去護國者哨站尋找指揮官阿密爾吧。$B$B護國者哨站就在正東方的下一座島上。', '去護國者哨站尋找指揮官阿密爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10970, 'zhTW', '慈悲的任務', '我們在上一次進入伊斯利恩領地的偵察任務時搶救了這個監禁寶珠。要不是它發出暗淡的悲傷信號，我們原本可能不會發現它。$B$B我們認為我們其中一員可能被關在裡面不過我們沒有辦法打開這個寶珠而不去傷害到裡面的東西。$B$B我們對於伊斯利恩的所知就是他們其中任何一員 - 在任何時候 - 都持有能夠打開寶珠的鑰匙。取得一把鑰匙並帶回這裡好讓我們能夠揭開這個寶珠的秘密。', '為虛空風暴內護國者哨站的指揮官阿密爾取得被搶救的伊斯利恩監獄鑰匙。', '', '去虛空風暴找維序派哨站的指揮官阿米爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10971, 'zhTW', '伊斯利恩的秘密', '<阿密爾拿出了一個標籤。>$B$B我在死去的先鋒遺體身上找到這個囚犯的身分標籤。我猜想他們以同樣的方式替所有的囚犯製作標籤。$B$B我想要收集這些標籤然後編列成冊以幫助我了解他們的司法體系。假如你日後找到更多的伊斯利恩監獄鑰匙，就可以前往南方的伊斯利恩軍事要塞打開伊斯利恩監獄，將所有你找到的身分標籤都交給我。', '虛空風暴護國者哨站的指揮官阿密爾要你帶給他1個伊斯利恩囚犯身分標籤。', '', '去虛空風暴找維序派哨站的指揮官阿米爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10972 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10972, 'zhTW', '伊斯利恩囚犯身分編錄', '我需要更多的身分標籤，$n。目前為止我發現這些標籤不只是拿來辨識囚犯的身分而已，它同時也記載著囚禁的場所!$B$B一旦我破解上面的編碼，就可以明確的知道所有盟友被囚禁的位置，並且以最小的衝突救出他們。', '我需要更多的身分標籤，$n。目前為止我發現這些標籤不只是拿來辨識囚犯的身分而已，它同時也記載著位置!一旦我破解上面的編碼，就可以明確的知道所有盟友被囚禁的位置，並且以最小的衝突救出他們。', '', '去虛空風暴找維序派哨站的指揮官阿米爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10973 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10973, 'zhTW', '千個世界', '我已經破解他們的密碼了!每個標籤的密碼被分成好幾個部份。標籤的正面永遠寫著同一句話:「千個世界……」。我不確定這幾個字的涵義但是感覺上有誘人受騙的意思。$B$B標籤的背後才是重要的資料所在。第一段的記號記錄著地點，而第二段記號記錄著囚犯的種類。此外，看起來那些鑰匙可以組合成一種更特殊的鑰匙，上面記載著另一種囚犯的種類。現在我只需要更多的鑰匙……', '虛空風暴護國者哨站的指揮官阿密爾要你帶給他5把伊斯利恩監獄鑰匙。', '', '去虛空風暴找維序派哨站的指揮官阿米爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10974 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10974, 'zhTW', '貝許爾的靜止密室', '伊斯利恩在劍刃山脈最北邊人稱貝許爾平臺的沙洲上有一塊領地。根據鑰匙碎片上的記載，他們在貝許爾有更大規模的監獄。我應該跟你提一下，伊斯利恩稱呼那些監獄為靜止密室。$B$B這個鑰匙碎片可以讓你進入其中一個特殊的靜止秘室叫做靜止密室A。帶著這個鑰匙碎片前去調查吧。$B$B調查完成以後我的幻影將會在貝許爾平臺等你，跟我交談。', '使用伊斯利恩鑰匙片 - A打開在劍刃山脈貝許爾平臺的靜止密室A。$B$B將調查密室得到的證據交給貝許爾平臺的指揮官阿密爾的影像。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10975 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10975, 'zhTW', '淨化貝許爾的密室', '', '', '', '去刀鋒山找巴什伊爾碼頭的指揮官阿米爾的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10976, 'zhTW', '奈薩斯王印記', '我必須知道伊斯利恩在奧齊頓的法力墓地裡關著什麼樣的東西。$B$B在你與貝許爾的靜止密室野獸戰鬥的時候，你可能會看到一樣叫做奈薩斯王印記的東西。如果你找到這樣東西，馬上交給我!這是要製作通往法力墓地裡頭的靜止密室鑰匙所欠缺的最後一樣材料。', '劍刃山脈貝許爾平臺的指揮官阿密爾的影像要你交給他1個奈薩斯王印記。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10977 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10977, 'zhTW', '法力墓地的靜止密室', '你所找到的奈薩斯王印記使我可以打造一把通往法力墓地靜止密室的鑰匙。$B$B根據雕紋上面的紋路記載其中關著2名囚犯:一名位於前方的區域，另一名位於靠近奈薩斯王子薩法爾的地方。我即將給你的這把鑰匙可以打開位於前方的密室。$B$B我要你前往奧齊頓的法力墓地並且打開法力墓地的靜止密室。', '劍刃山脈貝許爾平臺的指揮官阿密爾的影像要你使用法力墓地靜止密室鑰匙打開奧齊頓的法力墓地靜止密室。這個任務只能在英雄難度下完成。', '調查法力陵墓靜止間', '去刀鋒山找巴什伊爾碼頭的指揮官阿米爾的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10978 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10978, 'zhTW', '返回莫希斯·輕翼身邊', '聖物已經取回，你必須立刻離開這裡，$N。克林塔爾置自己和夢境守衛者的安全於不顧，幫助你找回聖物；現在，他必須專心對抗那些滋擾翡翠夢境的入侵者了。$B$B將聖物交給莫希斯·輕翼，並將你看到的情形告訴他。或許他可以幫助我們判斷入侵翡翠夢境的人究竟是誰。', '將艾維娜聖物交給贊加沼澤塞納里奧庇護所的莫希斯·輕翼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10979 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10979, 'zhTW', '轉至常青林', '你確定自己在獸穴中看到了一隻烏鴉？$B$B事情越來越令人困惑了。看來我們沒法直接幫助克林塔爾和夢境守護者，但是如果我們能查明究竟是什麼在滋擾翡翠夢境，或許就有辦法阻止這些神秘的入侵者。$B$B有報告稱刀鋒山上一支遠古的鴉人部族已經復甦，而他們所崇拜的神正是一隻烏鴉。去常青林找阿爾索恩·風歌，或許這支鴉人部族與翡翠夢境有著千絲萬縷的關係！', '與刀鋒山常青林的阿爾索恩·風歌談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10980 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10980, 'zhTW', '烏鴉之書', '莫希斯的猜測是對的，這支鴉人部族很可能跟翡翠夢境的躁動有關，但是在沒搞清楚情況之前，我們不能貿然行動。$B$B坦莫在研究中發現，鴉人部族很可能保有一本古老而神聖的“烏鴉之書”。$B$B鴉人的靈魂不會自己顯現在你的眼前，所以你需要帶著這塊石頭，到刀鋒山的西部高峰去，在烏鴉林的南邊弄到一顆以太鰩之眼。把它們組合起來，你就可以看到鴉人的靈魂了。你要尋找的目標，是一個名叫長者塞克卡爾的靈魂。', '使用一顆以太鰩之眼和你的先知之石找到烏鴉教派的幽靈。在漩渦峰尋找長者塞克卡爾的靈魂，向他詢問有關烏鴉之書的問題，然後向常青林的阿爾索恩·風歌覆命。', '', '去刀鋒山找常青林的阿爾索恩·風歌。', '瞭解有關烏鴉之書的知識', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10981, 'zhTW', '奈薩斯王子薩法爾的私人密室', '', '', '', '去刀鋒山找巴什伊爾碼頭的指揮官阿米爾的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10982, 'zhTW', '哈拉瑪德之眼', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10983, 'zhTW', '乾癟的莫格多克', '莫格多克真聰明!他派葛羅克來城市，找幫助。血槌氏族需要幫助。莫格多克說找幾個強壯的小伙子來劍刃山脈找他。他站在血之環的塔頂。莫格多克真聰明!', '到劍刃山脈血之環外面的高塔頂端找乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10984, 'zhTW', '與巨魔談話', '<范魯如結晶般清晰的音調傳入你的腦海中。>$B$B陰鬱城有一個巨魔懇求來往旅客的協助。大家對他的困難視而不見。$B$B你覺得你可以幫上他的忙嗎?$B$B他的名字是葛羅克，他就坐在東南方的商人附近。$B$B感謝你，$n。', '到撒塔斯城和陰鬱城區的巨魔，葛羅克談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10985, 'zhTW', '幫助阿卡瑪', '<克希利身上發出陣陣淡泊的光芒，而他身邊的奧爾多和占星者軍隊也回應著他的命令。克希利的軍團已經完全準備好了，隨時可以將伊利丹的軍隊壓制住，並為阿卡瑪吸引敵人的注意力。現在，這位納魯正等待著你給出進攻開始的訊號。>', '在克希利的軍隊發動佯攻之後，保護阿卡瑪和瑪維進入影月谷內的黑暗神殿。', '幫助阿卡瑪和瑪維進入黑暗神殿。', '去影月谷找巴爾裡廢墟的克希利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10986, 'zhTW', '天空之眼', '就算烏鴉之書的殘片都在，要找到它們也很困難。我們最好是利用比你的視線更為敏銳的眼睛。$B$B觀察者艾萊亞在納格蘭暮光嶺的東部邊緣研究當地的各種鳥類。去那兒找她吧，在她的幫助下，你或許可以藉助鳥類敏銳的視線找到烏鴉之書的殘片。', '與納格蘭暮光嶺的觀察者艾萊亞談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10987 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10987, 'zhTW', '捕獲麻鷹', '納格蘭的野生麻鷹是視覺最為敏銳的食肉鳥類。但是由於體型較小，因此受到風鵬的排擠，納格蘭大部分割槽域已經難尋它們的蹤跡。$B$B大多數的麻鷹棲息在暮光嶺。如果你能捕獲一隻麻鷹，我可以訓練它去尋找被掩埋的書典殘片。$B$B但是捕捉麻鷹並不是件容易的事，它們極易受到驚嚇，一旦有陌生人靠近就會立即飛走。我建議你悄悄接近這些敏感的生物，伺機投擲羅網。', '用麻鷹網捕捉一隻野生麻鷹，把它交給暮光嶺的觀察者艾萊亞。', '', '去納格蘭找暮光嶺的觀察者艾萊亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10988 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10988, 'zhTW', '烏鴉石', '經過訓練，這隻麻鷹已經能對鳥哨聲做出反應了。吹響鳥哨，它就會飛到你身邊，指引你尋找書典殘片。阿爾索恩捎話過來說，你要找的殘片應該都在斯克提斯及其周圍的峽谷中，去那裡找麻鷹吧。$B$B當你集齊殘片後，將鳥哨還給阿爾索恩，她會將這隻麻鷹放歸大自然的。$B$B代我向阿爾索恩問好。', '在斯克提斯收集8塊烏鴉石，把它們交給刀鋒山常青林的阿爾索恩·風歌。', '', '去刀鋒山找常青林的阿爾索恩·風歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10989 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10989, 'zhTW', '乾癟的莫格多克', '乾癟的莫格多克在塔頂等你。他叫我找一個$r$c就像你這樣。你去找他說重要的事情。去吧，但是不要告訴別人。這是秘密!', '前往劍刃山脈的血之環找乾癟的莫格多克。他就站在劍刃山脈，血之環外的塔頂，丘特的旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10990 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10990, 'zhTW', '雄鷹精華', '根據烏鴉之書的記載，在遠古時代，崇拜鴉神的鴉人捕捉三種與鴉神為敵的猛禽，將它們的精華封印在石頭神殿中。每座神殿都由專門的守護者看守，防止鴉神的敵人釋放這些被禁錮的精華。$B$B如果我們能拿到這些精華，就應該能引出鴉神並擊敗它。$B$B書中提到，第一座神殿中禁錮著雄鷹精華，這座神殿位於泰羅卡森林尤魯恩湖以南的山丘中。$B$B烏鴉之書中還說，雄鷹勇敢地戰鬥，但最終被潮水般湧來的敵人淹沒。你的熊形態所具備的堅韌與強壯應該可以在這場戰鬥中發揮巨大的作用。', '擊敗雄鷹守護者，取得雄鷹精華。使用阿爾索恩的麻鷹哨以召喚麻鷹傳遞你獲勝的訊息。$B$B如果你弄丟了阿爾索恩的麻鷹哨，可以回到常青林找阿爾索恩·風歌再拿一個。', '', '去找阿爾索恩的麻鷹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10991 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10991, 'zhTW', '獵鷹精華', '<麻鷹口中傳出阿爾索恩的聲音。>$B$B崇拜烏鴉之神的鴉人們還封印了獵鷹精華。$B$B它被禁錮在斯克提斯附近的神殿中，昭示著烏鴉祭司那叱詫風雲的輝煌歲月。$B$B那座神殿就在斯克提斯西北方的艾雷諾湖岸邊。$B$B要戰勝獵鷹守護者，你必須藉助獵鷹的力量。在獵豹形態下，利用你的速度和敏捷，趁守護者恢復能力之前擊敗他！', '擊敗獵鷹守護者，取得獵鷹精華。使用阿爾索恩的麻鷹哨以召喚麻鷹傳遞你獲勝的訊息。$B$B如果你弄丟了阿爾索恩的麻鷹哨，可以回到常青林找阿爾索恩·風歌再拿一個。', '', '去找阿爾索恩的麻鷹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10992 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10992, 'zhTW', '山鷹精華', '<麻鷹口中傳出阿爾索恩的聲音。>根據烏鴉之書記載，被封印的最後一塊也是最強大的一塊精華是山鷹精華。它被禁錮在遠離斯克提斯的神殿中，就在奧金頓東南方某座偏僻的小島上。$B$B從書中的描述來看，應該就是被稱為悲翼之地的島嶼。$B$B山鷹守護者幾乎對鳥類利爪的攻擊完全免疫。放棄物理攻擊吧，呼喚群星之怒擊敗他。不要重蹈山鷹的覆轍。', '擊敗山鷹守護者，將山鷹精華交給常青林的阿爾索恩·風歌。', '', '去刀鋒山找常青林的阿爾索恩·風歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10993 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10993, 'zhTW', '返回塞納里奧庇護所', '將這些精華交給莫希斯·輕翼，並告訴他我們收集到的關於鴉神的新情報。$B$B莫希斯懂得如何利用這些精華引出鴉神安蘇。快去找他吧，不知道克林塔爾和夢境守衛者還能在鴉神的攻擊下堅持多久！$B$B<在你準備轉身離開的時候，阿爾索恩抓住了你的手臂。>$B$B$N，拜託你告訴莫希斯，我幫你了多大的忙。我擔心他不知道我為此做出的貢獻！', '將阿爾索恩的包裹交給塞納里奧庇護所的莫希斯·輕翼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10995 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10995, 'zhTW', '葛魯洛克的兩個龍頭骨', '詛咒之谷位在東邊飛龍之末的邊界處。戈魯爾之子，葛魯洛克就在那邊策劃他的愚蠢計劃。$B$B我聽說他的一樣物品被人用巧妙的手法給偷走了。是你做的嗎?可惜他沒有在過程中喪失性命。$B$B如果我們想重獲自由，我要你搶走他最重要的資產，那就是他父親屠殺黑龍軍團的龍頭骨。你要取得龍頭骨的唯一方法就是殺死他。', '取得葛魯洛克的龍頭骨，帶到劍刃山脈的血之環外，交給塔頂乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10996 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10996, 'zhTW', '瑪格歐克的寶箱', '瑪格歐克在剃刀山脊的山坡上以及東南邊巡邏。他的父親指派他為東邊山區的看守者，而他則享受著殘虐當地任何看不順眼的生物。$B$B為了我的部族生存權，身為戈魯爾之子的他必須被消滅。這就要靠你幫忙了。$B$B瑪格歐克總是隨身攜帶一個寶箱。將他的寶箱帶來給我，證明你已經殺死他。你可以拿走寶箱裡頭的任何東西。', '取得瑪格歐克的寶箱，帶到劍刃山脈的血之環，交給塔頂乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10997, 'zhTW', '就連古羅也有軍旗', '你聽說過撒塔斯城嗎，$c?它的西北邊上方有個地方叫做阻礙之丘，一個你只能藉由飛行坐騎才能到達的地方。$B$B其中一位戈魯爾之子 - 史拉格，離鄉背井到那邊並且控制當地的戈杜尼巨魔。即使距離如此遙遠，我們也不能讓他坐大，免得當他的兄弟們都被殺死之後會回來復仇。$B$B$N，你必須到那邊並且取得他的軍旗，證明他已經被擊潰了。', '取得史拉格的軍旗，帶到劍刃山脈的血之環，交給塔頂乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10998, 'zhTW', '搶奪魔典', '還有一個古羅要殺:史庫洛克·靈魂研磨者。他的藏身處非常隱密，但是有一個辦法可以引誘他現身。$B$B他曾經受過一個叫做邪惡的梵戈的巨魔術士訓練，你必須取得他的魔典!$B$B梵戈必須由你加上其他四名人員才能召喚，每個人站在一個火焰之環內。到東北邊的山區，靠近破碎荒野的附近尋找梵戈之環。$B$B還有一點，$N，假如你聽見梵戈說什麼變大之類的話，快回到你的火焰之環裡面!', '你必須取得梵戈的邪惡魔典。把它交給劍刃山脈血之環外塔頂的乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 10999 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (10999, 'zhTW', '一擊必殺', '帶給我8顆穴居人的石牙。', '帶給我8顆穴居人的石牙。', '', '去找喬‧蘭姆西。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11000 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11000, 'zhTW', '深入靈魂研磨者獸穴', '這本魔典是殺死史庫洛克的關鍵。$B$B在靈魂研磨者獸穴大聲的閱讀這本魔典以啟動儀式。接著一個叫做靈魂研磨者的東西會伴隨著許多史庫洛克的靈魂受害者出現，這些靈魂會試著破壞靈魂研磨者。你必須阻止這些靈魂這麼做，直到史庫洛克被迫在這個世界上現身為止。$B$B往北穿過匕爪峽谷，到達血之環的另一邊。$B$B獸穴的位置就在你到達戈魯爾之巢之前的右手邊。$B$B將史庫洛克的靈魂帶回來。', '取得史庫洛克的靈魂並且交給劍刃山脈血之環外塔頂的乾癟的莫格多克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11001, 'zhTW', '擊敗烏鴉神', '在對付烏鴉神一事上，我們已經沒有時間浪費了。你必須將精華灌注的月亮石帶到一個具有強大魔力的地方，引誘烏鴉神離開對他而言是安全的翡翠夢境。$B$B前往塞司克大廳將月亮石鑲在烏鴉之爪上。這個地點位於鷹王的大廳之前的一個密室裡。$B$B我們必須讓安祖相信他的信徒已經聚集起來準備迎接他降臨這個世界。等他現身的時候，別放過他!', '殺死烏鴉神並且回到塞納里奧避難所的莫西斯·語翼那裡。此任務只能在英雄難度的地城內完成。', '', '去找贊加沼澤的莫西斯·語翼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11002, 'zhTW', '瑪瑟里頓陣亡', '伊利丹·怒風的魔獄獸人軍隊來源已經消失了。生產殘忍戰爭工具的工廠也停止運作了，至少現在是如此。一切只剩下幾個小飾品以及這個割下來的頭顱 - 一個適合聯盟英雄的戰利品。$B$B將瑪瑟里頓之首交給榮譽堡的達納斯·托爾貝恩。', '將瑪瑟里頓之首交給地獄火半島榮譽堡的軍隊指揮官達納斯·托爾貝恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11003 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11003, 'zhTW', '瑪瑟里頓陣亡', '伊利丹·怒風的魔獄獸人軍隊來源已經消失了。生產殘忍戰爭工具的工廠也停止運作了，至少現在是如此。一切只剩下幾個小飾品以及這個割下來的頭顱 - 一個適合部落英雄的戰利品。$B$B將瑪瑟里頓之首交給索爾瑪的納茲格雷爾。', '將瑪瑟里頓之首交給地獄火半島索爾瑪的納茲格雷爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11004 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11004, 'zhTW', '暗影世界', '天空指揮官艾德瑞斯在一次對司凱堤斯的侵略行動中受到重傷。從此之後他的意識一直徘徊在清醒與昏迷之間。$B$B我擔心他已經精神錯亂。他在短暫清醒時要求我準備一種由阿拉卡身上攜帶的暗影之塵所製作的藥劑。他似乎相信這種藥劑能使他看見阿拉卡真正的領導者們所居住的「暗影世界」。$B$B我一點也不相信這種胡言亂語，但是我怕不做出這罐藥劑的話他不會善罷干休。你可以幫我的忙嗎?', '瑟弗林要你前往司凱堤斯從當地的阿拉卡身上取回6個暗影之塵。', '', '去找泰羅卡森林的瑟弗林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11005 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11005, 'zhTW', '魔爪祭司的秘密', '感謝你還聽我瘋狂的豪言壯語。一直以來我們都想要摧毀司凱提斯的指揮系統;我們已經探聽到他們有三個叫魔爪祭司的聖職人員，但是我們從未親眼見過。現在我們知道其中的原因。$B$B去跟瑟弗林交談以取得更多他發現的藥劑。使用藥劑找到並殺死那三個魔爪祭司:艾夏歐、史奇吉克以及札列克。據說他們住在迷霧亞拉芮克，靠近黑風湖的東邊海岸。', '從瑟弗林那裡取得暗影藥劑，用它找到並殺死司凱堤斯的魔爪祭司艾夏歐，魔爪祭司史奇吉克和魔爪祭司札列克。完成這個任務後回去找天空指揮官艾德瑞斯。', '', '去找泰羅卡森林的天空指揮官艾德瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11006 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11006, 'zhTW', '更多暗影之塵', '', '看來指揮官並不是胡言亂語。交給我更多的暗影之塵，我就給你另一份藥劑。', '', '去找泰羅卡森林的瑟弗林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11007 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11007, 'zhTW', '凱爾薩斯和綠焰光球', '你身邊的空氣發出了嗡嗡聲 - 一種溫和的嗡嗡聲。那魯已經知道你的勝利。也許它們就是你被迫從凱爾薩斯‧逐日者還在抽動的遺體上撿起這個球體的原因。它到底隱藏了什麼秘密？$B$B也許撒塔斯城的阿達歐會知道。', '將綠焰光球交給撒塔斯城的阿達歐。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11008 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11008, 'zhTW', '向司凱堤斯開火', '你認為你夠資格成為禦天者的一員嗎?讓我們看看你在空中的能耐吧。阿拉卡正在培植一批數量龐大的變種攻擊寵物，用來攻擊我們的斥候。我要你拿著這些爆破彈炸毀阿拉卡住所屋頂的孵卵所。盡量避開守衛那些卵的巨大的卡里瑞，要不然在你還沒發現是什麼東西攻擊你之前，你已經從坐騎上被擊落了。', '在司凱堤斯住所的屋頂尋找巨大的卡里瑞蛋，並且對其使用禦天者爆破彈藥。完成之後回報天空士官多林。', '', '去找泰羅卡森林的天空士官多林。', '已摧毀巨大的卡里瑞蛋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11009 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11009, 'zhTW', '巨魔的天堂', '既然你已經解放了我們的奴役生涯，我們可以開始重新統合整個部族。這可能要花點時間;部族之間的舊仇很難化解。但是現在有一件更迫切的事情，你必須前往位於西方上空的歐格利拉。你必須保護歐格利拉還有我們不受上方的軍隊威脅，就像之前古羅為了保護我們而對抗伊斯利、惡魔還有最可怕的黑龍軍團一樣。當你到達巨魔的天堂時，請教裘阿洛該如何做最好。', '乾癟的莫格多克要你去劍刃山脈的歐格利拉與裘阿洛交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11010 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11010, 'zhTW', '轟炸任務', '你有飛行坐騎...那又怎樣!你以為你有足夠的能力駕馭它嗎?$B$B北邊的煉冶場:憤怒，還有南邊的煉冶場:驚駭都是我的眼中釘，也對歐格利拉的和平造成威脅。對禦天者發射的滿天惡魔火砲使得我們無法前往他們的煉冶場進行破壞行動。$B$B你想證明你的能力嗎?拿著這些炸彈然後去炸毀他們的砲彈堆吧。小心別被他們把你從坐騎上給射下來了!', '使用禦天者炸彈摧毀15個惡魔砲彈堆。', '', '', '邪能砲彈堆已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11011 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11011, 'zhTW', '永恆的警惕', '你擊敗了鴉神安蘇，這真是了不起的成就。不過，我認為他肯定不肯善罷甘休，並且會再找機會返回外域。$B$B只要鴉神的追隨者還在，他就可能死灰復燃。收下這顆灌注精華的月亮石以防萬一吧。', '與莫希斯·輕翼談談，獲得一顆灌注精華的月亮石。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11012 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11012, 'zhTW', '靈翼血誓', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11013 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11013, 'zhTW', '為伊利達雷效力', '靈翼浮島……那本是靈翼龍族的避難所，如今卻淪為龍喉氏族橫行之地。雖然獸人們侵佔了我們的領地，可是他們無法削弱龍族強大的魔法力量。憑藉這種力量，我們可以掩蓋你的真實身份，幫助你安全混入龍喉氏族。$B$B我已經備好一封書信，我要你飛往龍喉營地，將它交給莫格霍爾大王。屆時，你將以伊利丹·怒風麾下一名邪獸人的身份開始新的生活。', '轉至靈翼浮島，將伊利達雷服役文書交給龍喉營地的莫格霍爾大王。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11014 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11014, 'zhTW', '會見工頭', '<莫格霍爾將服役文書揉成一團，隨手扔到一旁。>$B$B好吧，重要的事先說。想加入我統率的龍喉軍團，你就得幹活——誰也不能例外。去找點事做吧，別搞砸了。我會根據你的表現決定要不要再派你做些別的事。$B$B與龍喉營地中心的工頭瓦爾庫勒·龍息談一談。他會根據你的技能，為你安排適當的差事。$B$B好了，滾吧！', '與龍喉營地的工頭瓦爾庫勒·龍息談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11015 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11015, 'zhTW', '靈翼水晶', '你什麼都不擅長嗎？好吧。你雖說有些愚鈍，不過還是可以替我們做些事的。獵殺靈翼浮島上的生物，你或許可以從它們身上找到靈翼水晶。替我收集一些靈翼水晶，今天的任務就算完成了。', '將30塊靈翼水晶交給影月谷龍喉營地的工頭瓦爾庫勒·龍息。', '', '去影月谷找靈翼浮島的工頭瓦爾庫勒·龍息。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11016 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11016, 'zhTW', '虛空礦洞剝石者的外皮', '嗯，剝皮師？這兒可是剝皮師的天堂啊！獵殺水晶蔟附近的剝石者，替我收集一些虛空礦洞剝石者的外皮。', '將35張虛空礦洞剝石者的外皮交給影月谷龍喉營地的工頭瓦爾庫勒·龍息。', '', '去影月谷找靈翼浮島的工頭瓦爾庫勒·龍息。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11017 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11017, 'zhTW', '靈塵花粉', '採藥者？！很有趣的營生啊……我們的法師和薩滿祭司正好需要你的幫助。靈翼浮島上的靈塵灌木擁有奇異的花粉，對他們研究魔法很有幫助。替我收集一些靈塵花粉，今天的任務就算完成了。', '將40份靈塵花粉交給影月谷龍喉營地的工頭瓦爾庫勒·龍息。', '', '去影月谷找靈翼浮島的工頭瓦爾庫勒·龍息。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11018 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11018, 'zhTW', '虛空礦石', '礦工！$B$B<瓦爾庫勒向你敬禮。>$B$B咱們真是志趣相投！瓦爾庫勒也是一名礦工！沒有什麼比蓬頭垢面地挖掘礦脈更有趣的事了，對吧？$B$B尋找虛空礦脈，替我收集一些虛空礦石。', '將40塊虛空礦石交給影月谷龍喉營地的工頭瓦爾庫勒·龍息。', '', '去影月谷找靈翼浮島的工頭瓦爾庫勒·龍息。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11019 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11019, 'zhTW', '你的夥伴', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11020 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11020, 'zhTW', '緩慢的死亡', '龍喉獸人幾乎在每叢水晶簇都設立了苦工營地。直接殺掉獸人必定會惹來不必要的麻煩，但是我們可以略施妙計，既能削減他們的數量，又不會引起莫格霍爾的懷疑。$B$B在影月谷中獵殺那些被感染的野生動物，取出它們的邪能腺體。將邪能腺體和這團羊肉混合起來，放在苦工營地附近。他們只要吃上一口就會倒地身亡！', '影月谷龍喉營地的僱傭兵亞茲爾要你將邪能腺體和亞茲爾的羊肉的混合物投放在12座龍喉苦工營地附近，毒殺龍喉苦工。', '', '去影月谷找靈翼浮島的僱傭兵亞茲爾。', '在龍喉苦工營地投毒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11021 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11021, 'zhTW', '艾夏歐的年鑑', '這本神秘的書籍是在魔爪祭司艾夏歐的屍體上找到的。書中包含了神秘的文字以及一些神聖生物的圖樣，遠超出你的理解能力。$B$B裡頭的文字是一種你不了解的語言;很像一種古老的阿拉卡書寫體。也許你應該將這本書交給天空指揮官艾德瑞斯。', '將艾夏歐的年鑑交給司凱堤斯北邊的天空指揮官艾德瑞斯。', '', '去找泰羅卡森林的天空指揮官艾德瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11022, 'zhTW', '與莫格多克談話', '<國王/皇后>$n!在你離開這裡前往歐格利拉之前跟乾癟的莫格多克談談!', '跟乾癟的莫格多克談話。他站在劍刃山脈的血之環東面塔頂。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11023, 'zhTW', '再度轟炸!', '那些高射火砲仍然對我們造成威脅，$N。$B$B你可別誤會我的意思，我認為你上次執行任務的表現非常出色。但事實上，那些該死的惡魔們補充砲彈的速度似乎比我們摧毀他們砲彈的速度還快。這同時表示我們的士兵很難通過該區域，更別提那些惡魔們對歐格利拉所造成的風險。$B$B你意下如何?想再次轟炸他們嗎?', '天空士官樊德麗要你炸毀15個惡魔砲彈堆。任務完成後回到劍刃山脈的禦天者崗哨向她回報。', '', '', '已摧毀惡魔砲彈堆', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11024, 'zhTW', '陰鬱城的盟友', '陰鬱城有一個阿拉卡叫做里拉克...他是值得信賴的人。把這本書...交給他。$B$B<艾德瑞斯把書交給你的時候失去了意識。>', '將艾夏歐的年鑑帶到撒塔斯城內交給陰鬱城的『贖罪者』里拉克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11025 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11025, 'zhTW', '頂尖水晶', '經過適當的事前準備，那些山區中的水晶就能展現出它的奇異能量，就好像我們在歐格利拉發現它有使人思緒清晰的能力。$B$B山上的生物都垂涎著那些水晶裂片，並且將其裂片使用於他們私人的用途之上。那些水晶的價值甚至還引起了一些商機。$B$B想協助我們的話，你必須先學習了解頂尖裂片。幫我找一些裂片回來。除了這裡的生物會攜帶頂尖裂片之外，有時候你也可以在鐮奪怪挖掘水晶的地方發現裂片。', '裘阿洛要你收集5塊頂尖裂片，然後回到劍刃山脈上方的歐格利拉交給他。', '', '去劍刃山脈找奧格瑞拉的庫洛爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11026, 'zhTW', '驅逐惡魔', '朋友，你到達的時間真是太完美了!我們真的需要幫助。你會得到一個非常稀有的物品作為回報，這樣你我兩方都能得到好處。$B$B我們已經不再是兇暴的巨魔了，不過附近的惡魔們威脅要侵擾我們和禦天者。對抗惡魔的問題是，他們一旦被殺死，就會以一個新的軀體重新回來! $B$B不過，如果你使用這個水晶來召喚一個驅逐傳送門，當他們在傳送門附近死亡時，他們的精華就會被抽走，並且放逐回他們的老家!', '克朗克要求你使用驅逐水晶來放逐劍刃山脈上煉冶場:憤怒與煉冶場:驚駭中的15隻惡魔。當你完成任務後回去找他。', '', '', '已驅逐惡魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11027 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11027, 'zhTW', '你有黑暗符印嗎？', '那個營地的惡魔時常修理他們的傳送門。賈克說$N這一次給那些惡魔好看！$B$B但是，賈克要另一個暗色符文來製作晶鑄暗色符文給你。', '假如小$r沒有暗色符文，你就去跟克朗克說話。他試著每天做一個暗色符文！也許你可以去他的袋子裡拿一個？！', '', '去找刀鋒山的甘克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11029 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11029, 'zhTW', '殘破的偽裝', '打開包裹，$N。這是一個偽裝。看起來沒什麼說服力對吧?$B$B我為伊斯利走私者製作它們以搜尋稀有的書本。有一個阿拉卡作家住在司凱堤斯的中心島嶼，泰洛克之墓;他的名字叫撒哈克。他既老又幾近全盲。$B$B利用這個偽裝來和他交談並取得那本叫敵人之血的書。小心點，$N。這個偽裝騙不了其他的阿拉卡。', '使用殘破的阿拉卡偽裝從撒哈克那裡取得敵人之血再回到海茲克那裡。', '', '去找泰羅卡森林的海茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11030 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11030, 'zhTW', '我們的兒子想當禦天者巡邏員', '$c，我們有個問題 - 我們有很多兒子。自從禦天者搬到附近，所有的兒子都在討論要加入他們的軍隊。$B$B身為一個驕傲的父親，我們要他們在申請的時候擁有所有的優勢。所以，可以請你到北邊或南邊的煉冶場，在惡魔水晶熔爐取得魔法藥水給我們的兒子嗎?你絕對會看到它們的綠色煙霧。$B$B我們認為它們價值十個頂尖裂片。我們會給你裂片，但我們現在手上沒有。', '取得野獸的不穩定精煉藥劑。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11031 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11031, 'zhTW', '不再是大法師', '', '', '', '去找逆風小徑的大法師蕾爾達。', '', '', '', '', 0);
