INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11033, 'zhTW', '不再是刺客', '', '', '', '去找逆風小徑的大法師蕾爾達。', '', '', '', '', 0);
