INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11107, 'zhTW', '莫格霍爾大王', '我知道我身份低微，根本沒有資格直接帶口信給您。請您原諒我的無禮。莫格霍爾大王要您立刻轉至他的房間接受覲見。', '與影月谷龍喉營地的莫格霍爾大王談一談。', '', '', '', '', '', '', 0);
