INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11108, 'zhTW', '伊利丹·怒風大人', '來吧，大領主$N。伊利丹大人正等著你呢！', '與伊利丹·怒風會面。如果你有幸活下來，就轉至撒塔斯城的貧民窟尋找巴薩姆斯。', '與伊利丹·怒風會面', '去泰羅卡森林的撒塔斯城找巴薩姆斯。', '', '', '', '', 0);
