INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11116, 'zhTW', '納魯的試煉：瑪瑟裡頓', '想要證明你自己擁有獲得風暴鑰匙的資格，你必須首先完成四個試煉。$B$B現在，你只需要跨越最後一個障礙了，凡人。聚集一支軍隊，轉至地獄火堡壘深處，在瑪瑟裡頓的巢穴中殺出一條血路，進入中央的密室，殺死那個邪惡的腐蝕者！$B$B完成了這個任務，你就將獲得風暴鑰匙。', '撒塔斯城的阿達爾要求你殺死瑪瑟裡頓。', '', '到地獄火半島找阿達歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11117 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11117, 'zhTW', '抓住野生鹿角兔!', '就是現在。你聽到了嗎?從那邊的丘陵傳過來的。那是鹿角兔!被啤酒節氣味吸引過來的野生動物。我一直想抓一些，可惜我撞傷了小腿，跑不過那些兔崽子。但是你可以幫我!$B$B帶著這個網子然後用它抓住那些小傢伙。帶五隻回來給我，我會給你很不錯的報酬!還有一件事 - 你得喝到醉眼惺忪才能看到牠們!大杯乾下去或者跟我要一副模擬醉眼護目鏡!', '茍達克·狙獵者要你用鹿角兔捕網幫他抓5隻昏迷的鹿角兔。他提到你必須要喝醉或戴上模擬醉眼護目鏡才看得到那些鹿角兔。', '', '去找丹莫羅的苟達克‧狙獵者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11118 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11118, 'zhTW', '粉紅伊萊克遊行', '在啤酒節時喝醉是個長久以來的優良傳統 -- 是天殺的必要!問題是，我接到從艾澤拉斯各地的報告都指出，我們的慶典被幻像所騷擾!我們可不能容許這種事!$B$B這些伊萊克不能被一般武器所傷害 -- 武器會直接穿過牠們 -- 所以帶著這個驚人的地精裝置前往其他的啤酒廣場，讓牠們灰飛湮滅。要記得，你一定要喝醉或戴上模擬醉眼護目鏡才能看到牠們!如果你需要一副的話跟我說一聲。', '前往暴風城、達納蘇斯還有艾克索達外頭的啤酒廣場，在那些地方宰掉三頭伊萊克，然後回去找茍達克·狙獵者。你一定要喝醉或戴上模擬醉眼護目鏡才看得見那些粉紅伊萊克。', '', '去找丹莫羅的苟達克‧狙獵者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11120 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11120, 'zhTW', '粉紅伊萊克遊行', '聽著，我們正在此地做點生意。人們都喝醉啦?這是筆好生意，但我得告訴你有件事情在限制我們的利潤 - 那些幻覺。你不知道那個嗎?那些孩子向我報告說，我忠實的老主顧們正在四處尋找粉紅伊萊克。$B$B我可不希望我的老主顧心神不寧。聽好，帶著這隻鰭刺去其他的啤酒廣場，並且替我好好照顧牠，行嗎?記得一定要喝醉啊!', '造訪銀月城、雷霆崖還有幽暗城外的啤酒廣場，在每個地方各宰掉三隻伊萊克，然後回去找葛羅卓克·獵狙者。你一定要喝醉才看得見那些粉紅伊萊克。', '', '去找杜洛塔的葛羅卓克‧獵狙者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11121, 'zhTW', 'DAILY TEST QUEST (RAID)[日常]', '<NYI>Seek <QUESTGIVER> in <LOCATION>.  S/he wishes for you to aid them in a difficult task.', 'Speak with <QUESTGIVER> in the <AREA>.', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11122, 'zhTW', '來回跑', '你想在啤酒節中幫忙是吧？我有個絕佳的任務可以託付給你。我讓你坐上我的競速山羊，然後你就直奔卡拉諾斯。我有些酒桶要從那裡拿過來。$B$B弗萊恩‧火酒就在酒桶堆附近的小丘上。在你靠近時他會把酒桶丟給你，然後你要迅速地把酒桶拿回來這邊丟給保爾‧凍石。一次只能帶一桶。$B$B準備好了嗎？', '從卡拉諾斯的弗萊恩‧火酒那裡拿一個酒桶，並帶回來給保爾‧凍石。如果你的山羊跑掉了，就叫奈爾‧拉姆斯登再給你一頭。', '', '去找丹莫羅的奈爾‧拉姆斯登。', '酒桶已運送', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11123, 'zhTW', '調查廢墟', '可憐的詹姆士一直沒有辦法從樹蔭旅店的被毀和他家人被殺害中復原過來。我和小伙子們盡力地想把犯案的混蛋給揪出來。$B$B我派出了我們最好的調查員，巡察員塔倫，前往廢墟調查，不過他孤身一人，任務又實在太龐大。要是你願意幫塔倫一把，我們都會很感激的。聖光知道，我們全都想去幫忙。$B$B主大道會引領你前去旅店，但小心點。你會超過我們士兵保護的範圍。', '和樹蔭旅店的巡察員塔倫談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11124, 'zhTW', '調查廢墟', '如果你從村子出去沿著路往南，然後轉西朝貧瘠之地去，你就會經過樹蔭旅店的廢墟。$B$B塞拉摩派出了一個調查員想找出旅店到底發生了什麼事。一般來說我會建議你別淌這渾水，但我們有來自奧格瑪的命令要我們『協助』調查。$B$B你可以接受塞拉摩調查員的任何協助，你高興的話甚至可以給他一兩條消息，但記得把你真正的發現向我報告。', '和樹蔭旅店的巡察員塔倫談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11125, 'zhTW', '[PH] New Hinterlands Quest', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11126, 'zhTW', '叛徒就在我們之中', '很高興認識你，$c。我來到塞拉摩是為了要解決叛逃者的問題。這些人不只是拋下他們的守區，有的人甚至潛回了城裏。$B$B那些叛逃者間諜正在廣布謊言，希望能夠說服其他人加入他們。$B$B他們幾乎存在於城鎮與碼頭的每個守衛點。找到他們，揭發他們，讓他們身敗名裂。在這個時候，任何的行動都有可能激起旁人對他們的同情。', '找出5個叛逃者煽動家，然後向塞拉摩碼頭的卡莉雅·哈斯丁回報。', '', '去塵泥沼澤找塞拉摩島的加莉亞·哈斯汀。', '揭露叛逃煽動者的面目', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11128, 'zhTW', '宣傳戰', '那些叛逃者的間諜不只是和我們的守衛攀談。我們還發現為數眾多的傳單，由叛逃者設法從碼頭上的一艘船隻走私上岸。$B$B那艘用來載運傳單的船還停在塞拉摩，在最遠的碼頭那邊。如果你能夠偷偷登上船，並且拿到剩下的宣傳文件，那些間諜就會失去他們最有力的工具。要小心!那艘船是由老練的私掠者所駕駛，而且那些貨物可能被藏在船長室裡。', '把叛逃者宣傳計畫帶給塞拉摩碼頭的卡莉雅·哈斯丁。', '', '去塵泥沼澤找塞拉摩島的加莉亞·哈斯汀。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11129, 'zhTW', '凱爾失蹤了!', '幫幫我，$N! 我最寶貝的寵物，凱爾跑不見了!我只知道牠平常會在血蹄村附近亂跑，牠現在一定是迷了路又餓著肚子。$B$B你願意幫我找到牠並且餵牠嗎?只要牠吃飽了，牠就會安靜下來並且回家來。$B$B你需要去找食物來餵牠。牠最喜歡的就是嫩陸行鳥肉了，你只需要獵一隻並且拿那些多汁的肉給凱爾。你要是看見凱爾在村子裡，牠一定會過來找你的。', '莫高雷-血蹄村的亞哈伯·麥蹄希望你幫忙找他珍貴的寵物，狂怒的凱爾。$B$B餵凱爾吃嫩陸行鳥肉，然後回去找亞哈伯·麥蹄。', '', '去找莫高雷的亞哈伯·麥蹄。', '', '凱爾被餵飽了', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11130, 'zhTW', '閃亮閃亮的東西！', '過來過來，$G夥計:寶貝兒;！讓我老格裡伏塔看看那些閃亮閃亮的東西……$B$B嗯嗯，嘿，不錯不錯，但應該還有更好的。對，對，好上許多的。$B$B<格裡伏塔向你斜過身來，低聲耳語道。>$B$B很多地方呢，有許多許多寶貴的閃亮閃亮的小玩意，但你得知道哪裡有才行！不過今天呢，可就是你的幸運日了。我認識一個能幫你忙的傢伙，可以讓你找到無數亮閃閃的東西，多得你都拿不動。$B$B去吧，去找我的老朋友巴德，他就在祖阿曼附近。你呢，就跟他說是老格裡伏塔派你去的，他就會讓你參加他的新計畫啦。', '格裡伏塔要求你將他的便箋交給鬼魂之地的巴德，他就在祖阿曼外。', '', '到鬼魂之地找霸德·奈德瑞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11131 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11131, 'zhTW', '阻止火勢!', '你一定要幫助我們!無頭騎士正在攻擊村莊。到處都是火焰!孩子們會有危險!$B$B拜託，$n，加入滅火的行列。拿起水桶灑向火源，或是交給靠近火勢的朋友。熄滅那些火焰，我們或許還有救!', '變裝的孤兒監護員希望你幫助撲滅村莊中的火勢。等火完全撲滅之後，再和變裝的孤兒監護員交談。', '撲滅火勢', '去找變裝的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11132 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11132, 'zhTW', '誘人的保證', '我的理論證實了祖阿曼中存在著大量財寶的傳聞，當然了，我的理論不是你們這些凡人可以理解的。$B$B很快每個人都將獲得享不盡的榮華富貴了！$B$B不過，你得先去完成一些重要的事情, 你必須通過努力來掙得你的那一份, 畢竟……$B$B我們的初期行動並沒有像我希望的那樣順利進行。事實上，我的地圖，和那個借走我地圖的新手，在深入納洛拉克的平臺調查後就失蹤了。要替換一個人很簡單，但我需要那份地圖！$B$B只要成功了，人們就會永遠的記住你，是你幫助巴德·奈德雷克解開了祖阿曼的秘密！', '戰斧嶺的巴德·奈德雷克要你前往祖阿曼的高階祭司納洛拉克所在的平臺，找回他的地圖。', '', '去找幽魂之地的霸德·奈德瑞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11133 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11133, 'zhTW', '敗壞叛逃者的名聲', '我已經竄改了你從叛逃者傭兵手上拿到的傳單。現在，任何人只要讀了它們一定會對叛逃者還有他們的目標有截然不同的看法。$B$B要是我們能把這些散佈給夠多的守衛，那些叛逃者大概會羞愧地根本不敢靠近我們的城牆。$B$B<卡莉雅交給你一疊竄改過的傳單。>$B$B在我計畫我們下一步的行動前，你何不先開始呢?', '卡莉雅·哈斯丁要你把這些竄改過的傳單散發給6個塞拉摩守衛，然後回到塞拉摩的碼頭向她回報。', '', '去塵泥沼澤找塞拉摩島的加莉亞·哈斯汀。', '發放傳單', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11134 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11134, 'zhTW', '叛逃者的末日', '現在我們已經把叛逃者趕出了塞拉摩，現在是時候來把整個任務完成了。我本地的線民回報我，叛逃者的基地是一艘停泊在碼頭東南方小島旁的船。$B$B逮捕他們的領袖，蓋維司·灰盾，應該可以讓他們喪失反抗的意志。找到他並且說服他投降。我不懷疑他會炫耀性地試圖戰鬥，不過當他瞭解他贏不了的時候，他就會投降。', '抓住蓋維司·灰盾，然後向塞拉摩碼頭的卡莉雅·哈斯丁回報。', '', '去塵泥沼澤找塞拉摩島的加莉亞·哈斯汀。', '抓獲賈維斯·格雷希德', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11136, 'zhTW', '令人困擾的發展', '根據我們斥候最近巡邏的回報，有了一個令人困擾的轉變。他們發現有人帶著迪菲亞頭巾在塞拉摩城牆北邊的恐懼海岸活動。$B$B根據這個區域的災難顯示他們很有可能是一次船難的倖存者，但我們的情報非常有限。城北警戒崗哨的衛摩爾上尉正在尋找幫手做進一步的調查。', '向警戒崗哨的衛摩爾上尉回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11137 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11137, 'zhTW', '迪菲亞在塵泥沼澤?', '我的斥候向我回報了一場東北方海岸的船難。船難在這一帶並不是什麼罕見之事，但報告的內容卻提到了所有的倖存者都帶著紅色的頭巾!$B$B迪菲亞是工匠與商會成員，並不是水手。他們在船難現場做什麼?尤其是在一個他們向來沒有興趣的大陸上。$B$B謠傳他們的領袖暫居在哨塔東北方的島嶼上。殺了他然後把他身上所有的文件都帶來。', '從加爾恩·邁瑟斯身上取得迪菲亞指令，然後交給警戒崗哨的衛摩爾上尉。', '', '去塵泥沼澤找警戒哨崗的維摩爾上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11138 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11138, 'zhTW', '瑞恩·麥格吉爾', '根據你發現指令的文字，迪菲亞的首要目標就是找到並且取回他們的貨物。$B$B軍情七處有一個叫做瑞恩·麥格吉爾的打撈潛水員已經在塞拉摩外圍活動了一陣子。當聽到船難的時候，瑞恩前往現在被迪菲亞佔據的島嶼潛水。$B$B如果我們想要搶先取得迪菲亞的貨物，我們就需要他的幫助。往東北邊去，在你先前造訪過的島嶼更北邊的小島應該可以找到他。', '把迪菲亞指令交給恐懼海岸的瑞恩·麥格吉爾。', '', '去塵泥沼澤找恐懼海岸的瑞恩·米克基爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11139 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11139, 'zhTW', '二手的潛水裝備', '從這兒到奧卡茲的海底散落著一大堆的船難殘骸，迪菲亞早就已經開始在這一帶潛水搜尋。透過他們的裝備，我們就可以讓你整裝出發，加入尋寶的行列。但你得先有技巧的『借用』。$B$B搜索這座島上，尋找裝著潛水裝備的木箱還有用來修理的工具。等你找到這些就立刻帶來給我，我會讓你的裝備馬上就能使用!', '把工具組和受損的潛水裝備帶給塵泥沼澤的瑞恩·麥格吉爾。', '', '去塵泥沼澤找恐懼海岸的瑞恩·米克基爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11140 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11140, 'zhTW', '找回貨物！', '嗯，我已經盡力把這套裝備修復得可以潛水一段時間，不過，我並不認為這能支撐太長的時間。$B$B船難的殘骸一路從這座島的東側海岸延伸到奧卡茲島。在頭盔還維持運作時，在奧卡茲和這座島嶼的海底間尋找船難的殘骸。使用打撈用具來尋找船隻的貨物。但要小心別太靠近奧卡茲島，那些多頭蛇很凶猛的。', '把6個打撈起來的保險箱交給塵泥沼澤的瑞恩·麥格吉爾。', '', '去塵泥沼澤找恐懼海岸的瑞恩·米克基爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11141, 'zhTW', '珍娜一定得知道', '你一定要立刻把我們的發現告訴珍娜女士，絕對不能延誤!如果迪菲亞正在運送囚犯，我們不知道囚犯是誰或者犯人是不是還活著!$B$B但可以確定一件事，$n。就是迪菲亞不會大費周章地運送一個無名小卒。他們的囚犯必定大有來頭。珍娜女士一定比任何人還明白這些線索代表了什麼。你可以在塞拉摩中心的法師塔找到她。', '和塞拉摩的珍娜·普勞德摩爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11142, 'zhTW', '偵察奧卡茲島', '看來瑞恩對奧卡茲島的直覺是對的。我們需要調查那個島嶼，但這得動用一整個旅的部隊才能打到那個島上。$B$B塞拉摩的防衛武力無法承擔這樣的攻擊，我和卡莎·紅翼商量過了，她是塞拉摩獅鷲獸管理員的學徒，讓你能夠使用她的一隻騎獸從空中偵察奧卡茲島。$B$B奧卡茲島掌握著迪菲亞計畫中有關他們的囚犯，甚至是囚犯身份的關鍵。', '和卡莎·紅翼談談，並用她的獅鷲獸偵察奧卡茲島。當你的偵察結束之後，和塞拉摩的珍娜女士談談。', '偵察奧卡茲島', '去塵泥沼澤找塞拉摩島的珍娜·普勞德摩爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11143, 'zhTW', '一個恐懼的關聯', '我和巡察員塔倫談過你從樹蔭旅店收集到的證據。他似乎認為那些蹄印與盾牌是屬於牛頭人的恐怖圖騰氏族。$B$B配合恐怖圖騰在沼澤開始活動的報告，我想這並不是個巧合。我要派你去和達利爾上尉談談，他是恐怖圖騰的專家。出城後沿著路往北走一直到北點哨塔，那是道路上的第二個哨站。', '向北點哨塔的達利爾上尉回報。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11144, 'zhTW', '確認嫌疑', '恐怖圖騰或許是最好戰的牛頭人氏族，但這並不表示他們毫無組織。要是他們真的燒毀了樹蔭旅店，這一定是他們氏族長者的命令。$B$B在西北邊有一個恐怖圖騰的大型聚落叫做黑蹄村。他們一直利用那裡當作基地來攻擊哨塔。不過，我打賭你一定可以在那裡找到那些命令。去調查村子中的長者，看看能不能找到你要的命令。', '把恐怖圖騰作戰計畫帶給北點哨塔的達利爾上尉。', '', '去塵泥沼澤找北點哨塔的達利爾上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11145, 'zhTW', '恐怖圖騰的囚犯', '我們盡了一切努力來阻擋恐怖圖騰的劫掠者，但他們持續對哨塔發動攻擊。更糟的是，他們把隊長派出去收集情報的巡邏隊和守護道路的守衛給抓了起來。$B$B我猜想那些俘虜都被關在黑蹄村，就在西北方。我想恐怖圖騰的防衛者說不定會帶著鑰匙，我不管你要怎麼做，$c，總之把我的人活著帶回來。', '北點哨塔的盧卡斯中士要你釋放5個塞拉摩囚犯。', '', '去找塵泥沼澤北點哨塔的盧卡斯中士。', '解救塞拉摩囚犯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11146 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11146, 'zhTW', '捕捉迅猛龍', '東北方的一片沼澤中住著一窩特別討厭的迅猛龍。已經有不只一名缺乏警覺的士兵死在牠們手上了，但我想我們可以利用牠們來對付我們的恐怖圖騰鄰居。$B$B帶著這根繩索並用它來捕捉那些你制服的血沼迅猛龍或血沼尖嘯龍。除非你已經在戰鬥中使那些野獸虛弱，否則我是不會嘗試去捕捉牠們的。這恐怕得費上一番功夫。', '北點哨塔的盧卡斯中士要你去捕捉6隻迅猛龍。你可以捕捉血沼迅猛龍或血沼尖嘯龍。', '', '去找塵泥沼澤北點哨塔的盧卡斯中士。', '捕獲迅猛龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11147 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11147, 'zhTW', '放出迅猛龍', '「現在我們有了自己的迅猛龍，我們的下一步就是『鼓勵』牠們去攻擊西北邊黑蹄村的恐怖圖騰。$B$B我手上有一些剩下的......後腿，別在意它是什麼肉。這就是你的誘餌。在黑蹄村中心的風車前放下這些腿肉。如果牠們的訓練無誤，牠們應該會解決剩下的事情。」', '北點哨塔的盧卡斯中士要你去把迅猛龍誘餌放在黑蹄村的風車前面。', '', '去找塵泥沼澤北點哨塔的盧卡斯中士。', '放生迅猛龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11148 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11148, 'zhTW', '恐怖圖騰的武裝', '如果你在旅店廢墟發現的裝備是屬於恐怖圖騰的攻擊隊伍，那他們西北邊的營地裡一定會有更多類似的武器。$B$B我們對黑蹄村的瞭解並不多，但根據劫掠隊伍的人數來判斷，他們在這裡一定有著一批相當大的武力。$B$B不管用什麼方法，去弄到一些他們的裝備，好讓我們可以比對你在旅店找到的那些。', '北點哨塔的達利爾上尉帶給他7件黑蹄武裝。', '', '去塵泥沼澤找北點哨塔的達利爾上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11149 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11149, 'zhTW', '塔貝薩的協助', '我沒有辦法撥出任何人手來搜索第二個恐怖圖騰哨站，但我知道有個人也許能幫你。$B$B在泥潭沼澤的深處，靠近南邊的地方，有個由塔貝薩所擁有的小農場。她或許看起來只像是個鄉下老巫婆，但事實上她是個法師而且還在占卜上頗富盛名。沿著路往南到她的農場去，請她協助你調查樹蔭旅店大屠殺的真凶。', '和塔貝薩在她的農場談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11150 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11150, 'zhTW', '夷平恐角崗哨!', '不需要占卜就可以知道我那些討人厭的新『鄰居』會幹出什麼好事。要是如你所說，他們燒毀了樹蔭旅店，那也沒什麼理由要再繼續容忍這群惡棍。$B$B帶著這根火炬，把他們的營地夷為平地!你會在我農場的北邊找到恐角崗哨。你不會錯過的，那些恐怖圖騰大張旗鼓地以他們最愛的圖騰宣示他們的存在。', '把恐角崗哨的北方帳棚，東方帳棚和東北方帳棚燒毀，然後回塔貝薩的農場向她回報。', '', '去塵泥沼澤找塔貝薩的農場的塔貝薩。', '燒燬北部帳篷', '燒燬東北部帳篷', '燒燬東部帳篷', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11151 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11151, 'zhTW', '為海爾家族討回公道', '雖然恐怖圖騰對我來說不過是一群討厭鬼，但維米斯上尉會希望知道你的努力。把你發現的消息告訴他，說你已經找到了要為燒毀樹蔭旅店負責的人。$B$B現在已經救不回吉姆·海爾一家人了，但也許恐怖圖騰之後會在攻擊任何與塞拉摩有關的人時考慮再三。', '和塞拉摩堡壘的蓋蘭·維米斯上尉談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11152, 'zhTW', '終獲平靜', '我多希望我們能讓詹姆士·海爾的妻子與兒子能知道我們已經讓兇手伏法了。$B$B<維米斯上尉遞出一個小花圈。>$B$B有人說他們的靈魂會知道的，既使我們觸碰不到他們。雖然能做的並不多，但我希望你能在海爾家族的紀念碑上獻上花圈。那是塞拉摩的城門北邊，墓園中較大的石頭之一。', '塞拉摩堡壘的蓋蘭·維米斯上尉希望你向海爾家族的紀念碑獻上花圈。', '', '去塵泥沼澤找塞拉摩堡壘的蓋蘭·維米斯上尉。', '在海厄爾家族墓碑前放置花圈', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11153 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11153, 'zhTW', '突破封鎖線', '我們的船隻全沉了!我們需要你的幫助來突破設在破碎海峽的海賊封鎖線!$B$B帶著這些榴散彈，然後從哈洛梅瑟『借給』我們的飛艇搭個便車。他會帶你飛過那些海賊流氓的船隻，你可以給他們一點好看!$B$B如果你沒辦法把他們炸成碎片，我怕我們就永遠也無法突破封鎖線了。', '帶著派特洛夫的榴散彈然後把它們往海賊多的地方丟，殺死或摧毀25個封鎖線海賊以及10個封鎖線火砲。一旦你完成行動，向鎮西要塞的投彈手派特洛夫回報。', '', '去找凜風峽灣的投彈手派特洛夫。', '', '封鎖砲台已摧毀', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11154, 'zhTW', '嚇到他們挫屎!', '你，對，就是你…我需要你來幫幫我！$B$B派特洛夫為了要在要塞裡面製造榴散彈，派我上來這撿一些蝙蝠糞便。他派我來送死嘛！$B$B暗爪蝙蝠就倒掛在北邊的裂木森林裡面，但是除非要我回家，否則我一步也不要離開這座平台！$B$B但…但是你，可以幫我對吧？拜託拜託？！！！$B$B喏，這些是鞭炮。我想啊，如果你在蝙蝠底下放這些鞭炮，他們一定會馬上嚇到拉屎的！', '收集10塊暗爪糞便，送去給鋼鐵之門的工程師費克努。', '', '去找凜風峽灣的工程師費克努。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11155 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11155, 'zhTW', '又是鍬牙湯？', '現在我們牲畜都離奇失蹤了，我們最好盡快重新補給，否則在我們對付這周圍的野獸之前就要先餓死了！$B$B由於我負責要餵飽這群人，所以我需要你前往東方幫我找一些肉回來。除此之外，我還想找人幫我們煮些柔軟的鍬牙肉。$B$B要小心那些雄鹿…牠們的脾氣不太好！', '主廚黑壺要你帶6塊鍬牙肉，回到鎮西要塞交給她。', '', '去找凜風峽灣的主廚黑壺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11156 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11156, 'zhTW', '恐角劫掠者', '那些恐怖圖騰就躲在北邊的恐角崗哨，一天比一天大膽囂張。晚上的時候，你還可以聽見他們討論自己在戰鬥中的行為，如何對付那些想在此定居的人們。$B$B他們想把我們從塔貝薩的農場趕走，她已經在這裡訓練學徒好幾代了。我們盡全力地保護農場，但學徒加利昂在上一次攻擊中受了傷。$B$B去恐角崗哨，殺死每一個你看得見的恐怖圖騰!攻擊必須被阻止。', '殺死12個恐角的恐怖圖騰，然後向塔貝薩農場的學徒莫蘭恩回報。', '', '去塵泥沼澤找塔貝薩的農場的學徒莫蘭恩。', '殺死恐角崗哨的恐怖圖騰成員', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11157 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11157, 'zhTW', '邪惡窩巢', '$n，除了你之外我信不過別人來處理這件事。我要消滅東南方燃燒森林中的元龍蛋和元龍幼龍!$B$B自從我們抵達此地，餘燼窩巢就一直在起火，一定有某種邪惡的魔法在作用。而且最近居然還有擴散的現象。我的手下告訴我，如果我們不盡快處理這件事，幾週之後我們就要被火焰四面包圍了!$B$B去那裡掃除那些元龍蛋和元龍幼龍以解除我們的威脅。', '消滅15個元龍蛋和15隻元龍幼龍，然後向亞當斯隊長回報，他就在凜風峽灣的鎮西要塞。', '', '去找凜風峽灣的亞當斯隊長。', '元龍幼龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11158 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11158, 'zhTW', '血沼羽毛', '你是不是害怕布洛葛在這裡，小$r?別擔心。泥鏈營地的哥布林都是布洛葛的朋友，你也可以唷。$B$B黑龍毀了我們的老家還殺死很多布洛葛的老朋友，可是新的主宰卻不願意報仇，於是布洛葛就離開了蕨牆村。布洛葛來這裡讓朋友的靈魂安息並且替他們復仇，但布洛葛需要幫忙。為了要準備儀式，布洛葛需要有強大魔法的羽毛，像是城鎮西邊血沼墓穴的那些迅猛龍的羽毛。', '帶5根血沼羽毛給泥鏈營地的布洛葛。', '', '去塵泥沼澤找泥鏈鎮的布洛格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11159 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11159, 'zhTW', '吸引石槌之靈', '布洛葛已經做好了讓他朋友安息的圖騰。當龍來的時候，他們殺死了所有不願逃走的石槌巨魔。布洛葛跟著莫格穆洛克主宰逃走，希望能和其他的石槌倖存者組織一次反攻。$B$B反攻從來也沒有展開，石槌死者的靈魂仍糾纏著布洛葛與其他人。帶著這根圖騰往北去石槌廢墟，然後在巨魔遺體旁邊使用它，吸引那些靈魂。擊敗那些靈魂然後讓他們與遺體一起安息。', '泥鏈營地的布洛葛，希望你讓10個石槌之靈安息。', '', '去塵泥沼澤找泥鏈鎮的布洛格。', '讓石槌之魂安息', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11160, 'zhTW', '石槌軍旗', '當很多龍出現並佔領了布洛葛的老家的時候，石槌巨魔逃走了，而且把所有的東西都丟下，包括了氏族的軍旗。$B$B布洛葛知道軍旗就藏在石槌巨魔山丘的深處，但現在那裡叫做火焰洞穴。布洛葛一定要拿到氏族軍旗才能向殺死他朋友的龍來報仇。$B$B布洛葛的氏族山丘，火焰洞穴，就在泥鏈營地的西北邊，充斥著許多的龍類生物。軍旗在洞穴的深處。小心點，$n。', '找到石槌軍旗並且把它帶給泥鏈營地的布洛葛。', '', '去塵泥沼澤找泥鏈鎮的布洛格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11161, 'zhTW', '敵意的精華', '要製作布洛葛儀式所需的圖騰，他需要那些殺死他朋友的生物的精華。布洛葛敵人的仇恨與憤怒將會讓他復仇的魔法更加茁壯。$B$B殺死火鬃灰尾龍裔，火鬃斥候，火鬃逆鱗守衛，然後在他們的屍體旁使用布洛葛的圖騰。只有那些龍人死去時才會釋放出他們的精華。$B$B你要找的那些生物散佈在火焰洞穴，以及石槌廢墟的北邊。', '帶10個黑龍精華給泥鏈營地的布洛葛。', '', '去塵泥沼澤找泥鏈鎮的布洛格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11162 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11162, 'zhTW', '挑戰黑龍軍團', '布洛葛很喜歡對沼澤的黑龍復仇的主意。$n，你已經為了這一刻的準備幫了很多忙。你願意繼續幫忙嗎?$B$B帶著布洛葛的氏族軍旗往東方去，直到你看到一個像是龍嘴的洞穴。將石槌軍旗插在洞穴的入口，然後發出布洛葛對奧妮克希亞的挑戰。$B$B布洛葛和石槌要把他們的土地討回來!', '把石槌軍旗插在奧妮克希亞的巢穴的入口，等待奧妮克希亞的回應，然後向泥鏈營地的布洛葛回報。', '', '去塵泥沼澤找泥鏈鎮的布洛格。', '為石槌氏族復仇', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11163 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11163, 'zhTW', '對不起，我是臥底', '<多娜環顧了一下週圍，然後對你悄悄地說。>$B$B$n，我接下來告訴你的事情一定要嚴格保密，你明白嗎？$B$B其實我是沙塔斯衛隊派到巴德身邊的臥底。說實話，你剛來的時候我一度認為你是他們組織中的關鍵人物。$B$B但是你的行動打消了我的疑慮，洗清了你的嫌疑。實際上，既然你幹掉了瘋狂的祖爾金，我一定要好好獎勵一下你！', '向多娜·布拉斯庫報告你的英雄事蹟，並領取你的獎勵。多娜現在駐紮在祖阿曼外面的鬼魂之地。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11164, 'zhTW', '奪牙奇兵', '嗨，朋友！你是新來的吧？ 我託你辦件事吧....$B$B巴德一直想讓他的森林巨魔偽裝變得更逼真。他說他就快完成了——只是需要最後一點加工，只是需要點獠牙而已……$B$B我的剝皮才能在這裡毫無用處，拔那些巨魔的獠牙讓我感到噁心。$B$B帶10根巨魔獠牙回來給我，怎麼樣，朋友？', '普雷蒙要你從祖阿曼的巨魔身上收集10根森林巨魔獠牙，把它們帶回巴德的營地交給他。', '', '去找幽魂之地的皮格蒙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11166, 'zhTW', 'X標記……你的末日！', '那群蠢貨究竟是如何失敗的？$B$B我一再囑咐他們要小心，要小心——為了幫助他們潛入祖阿曼，我甚至把我的地圖和偽裝都給了他們。$B$B啊，不過任何事總有好的一面，他們的失敗對你和你的朋友們來說是個機會。只要成功了，你們就可以名正言順地加入我的隊伍，和我一起分享即將到手的那些無盡的榮譽。並不是\\r\\n我貪心，只是讓你意識到這點而已。$B$B在我將最終的挖掘計劃準備妥當之前，我的地圖上還有幾塊區域需要更詳盡的探索……', '進入祖阿曼並調查哈爾拉茲的大廳、加亞萊的平臺和埃基爾松的平臺。將這些地方的細節報告給巴德，他的營地就在鬼魂之地。', '', '去找鬼魂之地的巴德·奈德雷克。', '調查哈爾拉茲的大廳', '調查加亞萊的平臺', '調查埃基爾松的平臺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11167, 'zhTW', '新種瘟疫', '就在阿薩斯將我們扭曲成這種可悲的存在之後不久，皇家藥劑師學會致力於創造出我們自己的瘟疫。一種能吞噬所有血肉的瘟疫:活人、死人或是不死生物。$B$B我們已經成功研發出這種瘟疫，而我們就是來到此地要將它傳播給天譴軍團。$B$B聯盟攔截了船隻，上面有我們從幽暗城實驗室送來的最新菌種。前往東南方的沉船地點，搶救你看到所有的容器。', '復仇臺地的藥劑師黎珊達，要你從東南方的沉船中回收10個完好的瘟疫容器。', '', '去找凜風峽灣的藥劑師黎珊達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11168, 'zhTW', '摻入混合物', '我有種感覺我們的瘟疫感染力，多少被漫長的船期所影響了。現在需要一種強力的毒素來強化這株菌種的效力。$B$B海灘上的螃蟹是棕色外殼的潮行蟹的遠親。那種較小的熱帶種產出一種足以讓巨魔昏倒的麻痺毒。$B$B而我們都知道東西越大就越好!本地種的腺體越大，產出的毒素按理說也就越強。幫我帶一些回來!', '從巨型潮行蟹的身上收集3具巨型毒素腺體，交給藥劑師黎珊達，她就在凜風峽灣的復仇臺地上。', '', '去找凜風峽灣的藥劑師黎珊達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11169 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11169, 'zhTW', '恐怖圖騰武器', '在上一次恐怖圖騰攻擊的時候，我受了傷，但我卻拿到了一根敵人用來對付我們的奇怪圖騰。$B$B它似乎在戰鬥中發射出一種原始的能量箭，但就我個人的經驗卻無法說出這個東西是如何運作的。如果你願意幫我試驗這個東西，我就把圖騰借給你。$B$B農場四周的有水區域有著一些討厭、有斑點的塵泥鱷魚和塵泥利齒鱷魚。試著在圖騰附近和那些鱷魚戰鬥。', '塔貝薩農場的學徒加利昂希望你對10隻塵泥雜斑鱷魚或塵泥利齒鱷魚測試俘虜圖騰。', '', '去塵泥沼澤找塔貝薩的農場的學徒加里奧。', '測試圖騰', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11170, 'zhTW', '海上測試', '我們剛剛才聽說聯盟部隊將要派出援軍。沒有比現在更好的時機了!$B$B我們正好需要測試的目標，而這些北方艦隊的後備軍人將會非常適合!$B$B帶著這些瘟疫瓶，然後和蝙蝠管理員卡蜜兒談談。告訴她你需要徵召一隻騎乘蝙蝠來協助我們。$B$B一旦你抵達海上，將這些瓶子丟向增援艦隊。我等不及要看結果了!', '和蝙蝠管理員卡蜜兒交談，然後騎上一隻蝙蝠去攔截聯盟的援軍。一旦抵達艦隊上空，使用瘟疫之瓶去感染16個北方艦隊預備兵。', '', '去找凜風峽灣的藥劑師黎珊達。', '北方艦隊後備兵已感染', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11171 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11171, 'zhTW', '妖術領主？哈！', '太棒啦！看來我很快就能進入祖阿曼了。$B$B$N，你表現得非常出色。我和同伴們談過了，他們對你的印象頗好喲。你馬上就能成為我們中的一份子啦。眼下，你還得完成一項任務——除掉妖術領主。$B$B這對你來說簡直是小菜一碟。只要你毫不畏懼地向他發動攻擊，這傢伙就會膽怯地轉身逃走。那些年老體衰的巨魔通常會給自己冠上可怕的頭銜，以此掩飾他們脆弱的本性，你明白嗎？', '戰斧嶺的巴德·奈德雷克要你轉至祖阿曼，殺死妖術領主瑪拉卡斯。', '', '去找鬼魂之地的巴德·奈德雷克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11172 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11172, 'zhTW', '飛艇失事', '不久之前，有一艘哥布林飛艇墜毀在東邊。幾天前有一位熱砂企業的代表經過了這裡。$B$B她正在尋找關於飛艇貨物還有駕駛員比吉爾的消息，但是我們沒有人去失事地點仔細的察看。我懷疑她是否有能力獨自處理那些殘骸，並且找回飛艇原本運載的那些貨物。$B$B假如你有空的話，你可以去比吉爾的飛艇殘骸那邊找她，就在這裡東邊靠近山區的地方。', '跟比吉爾的飛艇殘骸的莫克希·鋼格談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11173, 'zhTW', '試劑小偷', '如果你想叫學徒莫蘭恩做一件事而不搞砸的話，那就是聽他抱怨那些試劑。$B$B平常的時候我都不理他，但是這招從來沒有用。這次，我要換個方法對付他。$B$B也許我可以在他發現之前把遺失的試劑給掉包的話，或許他就不會來吵我了。我們兩個都使用的試劑之中最常見的是沼澤毒液，它來自於農場北方沼澤中的暗牙爬行者和毒性切割者。假如你將毒液交給我，我就可以在莫蘭恩發現之前把它掉包了。', '將6瓶沼澤毒液交給塔貝薩的農場的學徒加利昂。', '', '去塵泥沼澤找塔貝薩的農場的學徒加里奧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11174 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11174, 'zhTW', '預防腐蝕', '看看這個地方!到處都是軟泥怪。假如我找不到方法使牠們處於控制之下，牠們將會侵蝕機體的殘骸還有飛艇的貨物!$B$B我不能空手回去，$c!在牠們腐蝕所有的東西之前幫我熔解這些軟泥吧!$B$B這個裝置充滿能源之後會將能量集中在軟泥怪身上，使牠們爆炸。飛艇的能量核心碎片應該可以提供這個裝置所需的能量。靠近失事地中心的能量核心隨時都可以提供能量，但是其他的就時有時無了。', '莫克希·鋼格要你熔解10個軟泥怪然後回到比吉爾的飛艇殘骸向她回報。', '', '去塵泥沼澤找比吉爾的飛艇殘骸的莫希·斯蒂格里。', '溶解軟泥怪', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11177 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11177, 'zhTW', '水光莊園的隱士', '沼澤裡住著一位當地人稱為『沼澤之眼』加爾的傢伙。水光莊園之前的主人在一種神秘的情況下消失無蹤時，他就「接管」了那個地方。$B$B每隔一段時間我都會派人去看看他。他會讓我想起我的祖父，你知道嗎?有些人說他的腦筋不太正常。$B$B假如你從塞拉摩門口的道路往西北邊走，在路轉向西邊之前你會發現水光莊園就在女巫嶺一帶。', '跟水光莊園的『沼澤之眼』加爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11178, 'zhTW', '督軍之血', '當你觀察這隻瓶子時，你突然想起了祖阿曼外面那個狂妄的傢伙。$B$B你迫不及待地想要看到巴德的表情！', '把祖爾金之血交給祖阿曼外面鬼魂之地的巴德。', '', '去找鬼魂之地的巴德·奈德雷克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11179, 'zhTW', '芬雷沒膽', '是誰負責維修弩手們的武器？是我，Finlay Fletcher！$B$B我們的部隊計劃轉移到Fort Wildervaar，指揮官指派我協助處理所有準備事宜，搞得我沒時間外出收集製作弓弦所需的腸線了！$B$B好心的$C，幫我個忙好嗎？獵殺凜風峽灣的霧刃豹，從它們身上弄到完整的腸線！那些弄斷的腸子就算啦。', '收集7個新鮮的霧刃豹腸線，然後回到西部衛戍要塞向芬雷·伏萊齊回報。', '', '去凜風峽灣找西部衛戍要塞的芬雷·箭羽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11180, 'zhTW', '是什麼在女巫嶺作祟?', '我旅行經過此地，想要拜訪加爾還有他的新居。但卻感受一種從所未見的無盡恐懼!那裡一定出了什麼問題，我不可能是唯一看見的人...$B$B你看到那些鬼魂還有散落在女巫嶺的屍體嗎?我有一種感覺，要是有人知道這裡發生了什麼事，那一定是他們。探訪這附近甦醒的鬼魂與屍體，透過戰鬥讓他們安息，然後看看你能在加爾被邪惡吞噬之前能找到些什麼!', '水光莊園的莫丹特·格林思比希望你從10個復活之軀或復活之靈身上獲得情報。', '', '去塵泥沼澤找水光莊園的摩丹特·格雷斯比。', '收集資訊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11181, 'zhTW', '女巫剋星', '在我做為草藥師的這些年中，我時常觀察到自然能為最困難的問題提供精妙的解決方法。我讀到那些流浪法師或巫醫時常使用一種名為女巫剋星的草藥，利用草藥燃燒的燻煙來將邪惡的東西從隱蔽處吸引出來。$B$B若這是真的，那表示女巫剋星就生長在女巫嶺靠近淺水的地方。你可以從它們寬大的葉子和中心紅色的花莖辨認出來。把你所能找到的草藥都帶給我，$n，這可能是我們唯一的希望。', '帶9株女巫剋星給水光莊園的莫丹特·格林思比。', '', '去塵泥沼澤找水光莊園的摩丹特·格雷斯比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11182, 'zhTW', '根本原因', '世界萬物處於一種自然的平衡，唯有當受到與自然和諧不同調的干擾時，平衡才會被打亂。$B$B你殺死那些幼龍和飛龍的努力都是白費功夫。讓魔法燃燒樹林不停擴張的元兇是那些最近才甦醒的維酷人和他們的主人，史克德‧龍裔。$B$B如果你想要在手上沾染鮮血，我建議你從他們開始。你可以在餘燼窩巢的南邊找到他們的巢穴。', '殺死5名掠龍管理員和史克德‧龍裔。等你完成之後，向餘燼窩巢的餘燼窩巢古樹回報。', '', '去找凜風峽灣的餘燼窩巢古樹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11183, 'zhTW', '淨化女巫嶺', '火炬已經準備好了。把它放在碼頭的盡頭，然後做好準備面對出現的東西。$B$B我不知道火炬的煙會把什麼東西給召來...要是真的出現了什麼。我得說，我信不過那些鄉野法術，但我們沒時間想別的法子了。為了你和加爾，我祝你好運。', '水光莊園的莫丹特·格林思比希望你把火炬放在碼頭的盡頭，並且擊敗任何出現的東西。', '', '去塵泥沼澤找水光莊園的摩丹特·格雷斯比。', '淨化女巫嶺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11184 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11184, 'zhTW', '懸賞：貪婪的血爪', '旅人與在這一帶工作的熱砂員工都被告知要避開城鎮西邊的血沼墓穴。$B$B那個區域四處都是迅猛龍，由冷酷又狡猾的貪婪的血爪所率領，牠起碼已經殺死了兩名熱砂工程師。$B$B德拉席特·滴栓已經宣布了豐厚的獎金來獎勵任何可以清除泥鏈營地威脅的人。', '殺死貪婪的血爪並且向泥鏈營地的德拉席特·滴栓回報。', '', '去塵泥沼澤找泥鏈鎮的德拉茲特·迪普瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11185, 'zhTW', '藥劑師的信件', '從一名被遺忘者藥劑師身上取得的信中藏著驚人的跡象，內容指出恐怖圖騰和羅德隆的新主人有著密切的聯繫。$B$B「為了表示我們的誠意以及當作我們合作關係的象徵，我們已經派遣藥劑師西拉協助你對付我們在卡林多大陸的共同敵人。沒有人可以阻擋我們聯合起來的力量和決心。」$B$B你應該將這封信交給軍情七處在塔貝薩的農場的探員─安德羅·波特。', '將蠟封的信件交給塔貝薩的農場的安德羅·波特。', '', '去塵泥沼澤找泥潭沼澤的安德羅·波特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11186, 'zhTW', '背叛的跡象?', '從一名被遺忘者藥劑師身上取得的信中暗示幽暗城與恐怖圖騰的高層之中有人私下勾結。$B$B「為了表示我們的誠意以及當作我們合作關係的象徵，我們已經派遣藥劑師西拉協助你對付我們在卡林多大陸的共同敵人。沒有人可以阻擋我們聯合起來的力量和決心。」$B$B也許蕨牆村的納澤爾·血矛會知道如何處理這份情報。', '將蠟封的信件交給蕨牆村的納澤爾·血矛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11188 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11188, 'zhTW', '兩個錯誤...', '現在我們已經激怒了那些餘燼窩巢的元龍，他們很有可能加強對要塞的攻勢，這樣可不太好。我最討厭一個錯誤還牽扯到另一個，但顯然我們現在沒得選擇，非得毀滅這些生物不可。一個令人懊悔的行動，但人生不如意事，十有八九。$B$B帶著我的魔杖。我已經增長了它的射程，雖然它的傷害可能還比不上給他們一拳。但終究，它只是要引起元龍的注意。', '鎮西要塞的法師中尉瑪歷斯特交代你摧毀3隻元龍。', '', '去找凜風峽灣的法師中尉瑪歷斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11189 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11189, 'zhTW', '最後一次', '你好啊，我死了嗎？我想我應該是死了，因為我飄在我身體上！$B$B喔，這真是倒楣的一件事。我原本正打算向艾琳娜求婚的時候，天譴軍團卻來突襲。$B$B我知道她還活著…我可以在心中感應到她。$B$B你有辦法把我帶到她身邊嗎？那些天災軍依舊看得到我的鬼魂，恐怕會對我做一些很可怕的事情。$B$B我想要最後再看一次她漂亮的臉龐。你可以轉告她我愛她。', '護送探險者賈倫的鬼魂安全地送到探險者艾琳娜·石衣身邊，她就在凜風峽灣的鋼鐵之門。', '安全護送探險者賈倫的鬼魂到探險者艾琳娜·石衣', '去凜風峽灣找鋼鐵之門的工頭伊蕾娜·石衣。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11190, 'zhTW', '一個尺寸可不是全部適用', '$g小夥子:小姑娘;，哪個天才把我們的火砲做成非標準的尺寸？現在我們得特製砲彈才能發射這些勞什子的鬼東西！$B$B我想拜託你去外頭把我們發射過的砲彈找回來。我相信這些愚蠢的傢伙應該會把砲彈射得到處都是，南方和東方應該很多。$B$B<砲手張開手比畫了一下砲彈大概的大小。>$B$B這絕對比我們重做新的快上不少。', '砲手伊利要你收集10顆鎮西砲彈，然後回到鎮西要塞交給他。', '', '去找凜風峽灣的砲手伊利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11191 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11191, 'zhTW', '廢棄的燈塔', '東邊的舊燈塔已經廢棄多年，但是鮑伯斯·嘶鍊一直想要再度啟動那座燈塔。$B$B我不知道她計畫怎麼做，但是她認為這樣可以使船隻和貨物駛入碼頭的時候更加的流暢，所以我並不會反對她這麼做。規劃碼頭的工作其實還不錯，尤其是他們原本想派你去前線作戰的時候，你知道嗎?', '跟塞拉摩東邊島上燈塔的鮑伯斯·嘶鍊談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11192 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11192, 'zhTW', '蛇頸龍油', '燈塔的舊日誌指出照射燈所使用的燃油是從沿海附近的蛇頸龍身上提煉出來的油。$B$B<鮑伯斯對這種過時科技的產物皺了皺鼻子。>$B$B我想這是一種粗糙但實用的設計吧。舊日誌上記載著最年幼的黑色蛇頸龍油效果最好，牠們就生活在塞拉摩碼頭的正底下。$B$B假如你願意的話，可以幫燈塔的燈添加燃油嗎?', '將4罐蛇頸龍油交給塞拉摩附近燈塔內的鮑伯斯·嘶鍊。', '', '去塵泥沼澤塞拉摩島找巴布·菲茲托克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11193 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11193, 'zhTW', '深海的卑鄙居民', '你知道嗎，那座舊燈塔裡可以找到的東西真是太不可思議了。在我把燈點亮了之後，我在上面的舊大箱裡找到這本書。$B$B<鮑伯斯舉起這本書並且大聲地唸出它的書名。>$B$B「《深海的卑鄙居民》!」$B$B天啊，假如我看見這種生物應該會昏倒吧!我相信這本書可以博人一笑，但我現在就是沒時間讀書。$B$B你知道誰會喜歡這本書嗎……碼頭上的魚販─『骯髒』米凱爾·克羅威。他專門收集舊書。', '將《深海的卑鄙居民》交給塞拉摩碼頭的『骯髒』米凱爾·克羅威。', '', '去塵泥沼澤找塞拉摩島的“髒鬼”邁克爾·克羅維。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11194 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11194, 'zhTW', '這會是真的嗎?', '喔，我相信你跟鮑伯斯一定覺得書中古怪的描述和草圖很好笑，但是你們有沒有想過傳說也許是真的呢?$B$B假如你留心地打聽，我相信你仍然可以聽見水手們談到泰瑟爾，也就是書中提到住在這裡的海洋生物!當然啦，假如你想確定的話，你可以去問問看老納特·帕格。$B$B他在狂潮灣的小島上有一個小的釣魚營地，位在塵泥海灣的西南方。', '到狂潮灣，納特的平臺，與納特·帕格談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11195 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11195, 'zhTW', '破爛的巫毒人偶', '我太感動了，$n，居然是真的。我都不記得上一次有$r幫助蘇加姆走出困境是什麼時候了。$B$B這個是我從一個忙著鎖住我的野蠻人身上弄來的，看上去並不值多少錢，但是如果說有人可以確定它的價值，我想就只有我的好朋友格里伏塔了！$B$B如果你能成功活著離開這裡，不如把這個交給他看看。', '將破爛的巫毒人偶交給撒塔斯城的格里伏塔。', '', '去找撒塔斯城的格里伏塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11196 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11196, 'zhTW', '失蹤的巨魔', '聽著，朋友，普雷蒙還有件事需要你幫忙，我那個沒用的表兄被困在了祖阿曼裡。不過他還活著——就在昨晚，我還看到了他的訊號彈！$B$B他給我帶來了這麼多麻煩，我真應該就這麼讓他在裡面爛掉。不過話說回來，他還欠我一大筆錢。$B$B儘量幫他一把，把他欠我的錢給我拿回來！', '普雷蒙希望你深入祖阿曼，找到並幫助他的表兄蘇加姆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11197 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11197, 'zhTW', '雷酒的秘密ZZOLD Upper Deck Promo - Ghost Wolf Mount OLD', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11198 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11198, 'zhTW', '打倒泰瑟爾!', '不管是不是海怪，我們都不會拿船隻的安危去冒險。我已經命令我們最好的神射手來對付這個泰瑟爾。砲兵也已經以三門迫擊砲來強化碼頭的防禦。$B$B我也下令點亮燈塔。如果泰瑟爾真的來攻擊，你的職責就是在牠殺光神射手之前，操作迫擊砲打倒泰瑟爾。我不會待在同一個地點太久，使用迫擊砲很有可能會引起牠的注意。', '泰拉摩碼頭的米爾斯少校要你打敗泰瑟爾。', '保衛塞拉摩港口不受泰瑟爾破壞', '去塵泥沼澤找塞拉摩島的米爾斯少校。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11200, 'zhTW', '過於巧合', '我們已經從旅店的廢墟中盡可能的搜集線索。我很關心調查結果將如何的指引我們，但我們必須知道實情。$B$B從地上的蹄印和盾牌上莫薩恩的標誌，都使我相信恐怖圖騰可能與這件事有關。他們最近在沼澤建立了營地，也就是東北方的黑蹄村。前往黑蹄村並且尋找更多印著莫薩恩標誌的武器裝備。', '蕨牆村的克羅格要你交給他7件黑蹄武裝。', '', '去塵泥沼澤找蕨牆村的克羅格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11201, 'zhTW', '恐怖圖騰的陰謀', '自從恐怖圖騰在千針石林的活動曝光以後，許多牛頭人都對他們抱著猜忌的心態。我們曾經看過恐怖圖騰的高階成員犯下謀殺和綁架的罪行以達成他們的目的，而我擔心我們將會是他們的下一個目標。$B$B恐怖圖騰在這裡的東北方，藍色沼地附近建立了一座新的營地─黑蹄村。他們的領導人，也就是長者們將會從雷霆崖接獲命令。看看你是否能搶奪這些命令，並且把他們整合起來以洞悉恐怖圖騰的計畫。', '將恐怖圖騰的作戰計畫交給蕨牆村的克羅格。', '', '去找塵泥沼澤的克羅格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11202, 'zhTW', '任務:永燃之焰', '自從有記憶以來那些被遺忘者就一直在圖謀不軌，那些裝滿爛泥的瘟疫槽就是其中一部份。$B$B請容我說一句，$g先生:女士;，我們應該要在他們能使用這些之前把它給全毀了。我自己從餘燼窩巢準備了一大捆火炬。這些東西可以燒上幾天幾夜!$B$B拿去，我想你一定比我更擅長摧毀那些東西。', '餘燼矛塔的斥候諾雷斯，要你使用永燃火炬摧毀霍葛萊周圍的四個瘟疫槽。', '', '去找凜風峽灣的斥候諾雷斯。', '西南方瘟疫戰車已摧毀', '西北方瘟疫戰車已摧毀', '東北方瘟疫戰車已摧毀', '東南方瘟疫戰車已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11203, 'zhTW', '尋找塔貝薩', '你在黑蹄村奪回的武器裝備上除了訓練時的刮痕，並沒有明顯的打鬥痕跡，這表示燒毀樹蔭旅店的恐怖圖騰仍然逍遙法外。$B$B這裡的南邊，也就是泥潭沼澤的中心處住著一位女巫塔貝薩。雖然她是一個人類，但是她跟我們的關係良好並且還幫助我們訓練一些法師。$B$B去找她協助我們追蹤這些燒毀旅店的恐怖圖騰。不能讓聯盟認為我們跟這起攻擊事件有關連。', '跟泥潭沼澤的塔貝薩談話，她位在她的農場裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11204, 'zhTW', '回報克羅格', '我希望我能幫上你的忙，而且很抱歉我無法提供更多的訊息。我的學徒和我製作過太多的武器和護甲，我們沒辦法對每一件裝備提供太詳細的資訊。$B$B我們不但提供守衛這片牛頭人大地的勇士們裝備，那些恐怖圖騰們也特別鍾愛我們的作品。一個經驗豐富的武士總是會欣賞手工精良的裝備。', '跟蕨牆村的克羅格談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11205 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11205, 'zhTW', '夷平恐角崗哨!', '不需要占卜就可以知道我那些討人厭的新『鄰居』會幹出什麼好事。要是如你所說，他們燒毀了樹蔭旅店，那也沒什麼理由要再繼續容忍這群惡棍。$B$B帶著這根火炬，把他們的營地夷為平地!你會在我農場的北邊找到恐角崗哨。你不會錯過的，那些恐怖圖騰大張旗鼓地以他們最愛的圖騰宣示他們的存在。', '把恐角崗哨的北方帳棚、東方帳棚和東北方帳棚燒毀，然後回到塔貝薩的農場向她回報。', '', '去塵泥沼澤找塔貝薩的農場的塔貝薩。', '燒燬北部帳篷', '燒燬東北部帳篷', '燒燬東部帳篷', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11206, 'zhTW', '正義得伸', '我懷疑恐怖圖騰會放棄他們想將人類趕出這片沼澤的計畫。至少我們已經解決了在樹蔭旅店犯案的兇手。$B$B我相信派你前來的調查員並不需要知道這件事，但是部落不能再放任恐怖圖騰了，否則有一天他們的行動將使部落後悔莫及。$B$B珍娜女士和索爾酋長都不希望再度燃起戰火，但是他們是否願意為了避免戰爭而採取必要的手段呢?', '回到蕨牆村找克羅格。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11207 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11207, 'zhTW', '收回貨物!', '這架飛艇原本要運送可使用六個月的補給品給泥鏈營地的我們!當然，他們可以用以物易物的方式換取所需，但是他們總不能永遠這樣下去。$B$B我被派來這裡盡可能的回收那些貨物，但是飛艇的殘骸散落在這個地區的沼澤一帶。我相信許多貨物在失事的時候都報銷了，但是你願意幫我盡可能的找回剩餘的貨物嗎?', '比吉爾的飛艇殘骸的莫克希·鋼格要你取得8個飛艇貨物。', '', '去塵泥沼澤找比吉爾的飛艇殘骸的莫希·斯蒂格里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11208 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11208, 'zhTW', '替德拉席特送貨', '德拉席特會很期待聽到我的消息，但我不認為此地已經安全到我可以離開的程度。如果你有空的話，你願意替我把一些搶救起來的貨物送給泥鏈營地的德拉席特嗎?$B$B要是你還沒去過那裡的話，那是個小營地就在此處的西南邊，靠近石槌廢墟。你也可以走塔貝薩農場的那條路。等你到了泥鏈營地，你要找的人叫做德拉席特·滴栓。', '把飛艇貨物交給泥鏈營地的德拉席特·滴栓。', '', '去塵泥沼澤找泥鏈鎮的德拉茲特·迪普瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11209 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11209, 'zhTW', '納特的討價還價', '所以你找到了《深海的卑鄙居民》的抄本，對嗎?根據我的經驗我可以告訴你，這全是真的。我曾經親眼看過好幾隻那種東西。$B$B不過如果你想知道泰瑟爾的事情。我們得要有個交易，有點事情我希望你去做。我正在試做一系列的新魚餌，不過我還沒有試過這個。$B$B拿著這沱魚漿 -- 對啦，聞起來是有點爛爛的臭味 -- 把它塗在你身上，然後游到西南邊的沉船那邊。如果你僥倖活下來了，再告訴我它效果如何!', '納特平台的納特·帕格要你去測試他的新魚餌。', '', '去塵泥沼澤找納特的碼頭的納特·帕格。', '測試魚肉醬', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11210 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11210, 'zhTW', '噢，這是真的', '是，泰瑟爾是真有其物，牠就住在塞拉摩海域。$B$B牠對亮光特別有興趣，這也是為什麼他們最先就把燈塔關閉，你知道...$B$B要是你重新點亮燈塔，牠一定立刻就會回來。不過任何有正常心智的人都不會這麼做。$B$B這一定很適合你的計畫!能跟你喝一杯真不錯，不過如果泰瑟爾真的把你變成魚餌，那可別怪老納特。如果你真的打算這麼幹，那最好先去和塞拉摩碼頭的米爾斯少校商量一下。', '和塞拉摩碼頭的米爾斯少校談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11211 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11211, 'zhTW', '幫助泥鏈營地', '當那個哥布林……她的名字叫什麼……波克希，弗克希……對了，莫克希!總而言之，當她前往飛艇殘骸而經過這裡的時候，她說泥鏈營地的城鎮有一些麻煩。$B$B那艘失事的飛艇原本要運送給他們最新的補給品。假如你順著路往南走，經過石槌廢墟之後就可以看到泥鏈營地。$B$B你何不去那邊找德拉席特·滴栓然後看看你能幫上什麼忙呢?', '跟泥鏈營地的德拉席特·滴栓談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11212, 'zhTW', '塔貝薩的農場', '沼澤的中心處住著一位老婦人叫做塔貝薩。我們對她的了解並不多，只知道她比外表上看起來還要老的多。她不時的幫助我們並且維持我們和部落在這裡的和平。$B$B以前她會定時與我們聯繫，但是最近失去了她的消息。$B$B等你有空的時候可以去探訪她嗎?只要順著往北點哨塔的路直到轉向南方進入泥潭沼澤。她的農場就在路旁。', '跟泥潭沼澤的塔貝薩談話，她位在她的農場裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11213 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11213, 'zhTW', '探訪塔貝薩', '有一個人類的女子叫做塔貝薩住在沼澤中央的小農場裡。平常我不會跟人類打交道，但是她有時會提供我們很大的幫助。$B$B可惜的是，她已經很久沒跟我們聯絡了，而我正想找人去她的農場裡看看她的情況。$B$B假如你從村子的道路往南行深入沼澤，你會在泥潭沼澤的中央找到她的農場。', '跟泥潭沼澤的塔貝薩談話，她位在她的農場裡。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11214 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11214, 'zhTW', '前往泥鏈營地的任務', '熱砂企業最近在塵泥沼澤南方建立了一個新的哨站。假如我記的沒錯的話，它叫做泥鏈營地，只要順著路南下過了塔貝薩的農場還有石槌廢墟就可以看到了。$B$B這對我們來說是一個很棒的商機，珍娜女士要我派一位代表前去跟他們建立新的交易門路。你願意當我的代表嗎?', '跟泥鏈營地的德拉席特·滴栓談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11215 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11215, 'zhTW', '幫助泥鏈營地', '熱砂企業在沼澤南方的新哨站並不遠。運送補給品到泥鏈營地的飛艇失事了，使他們缺乏重要的工具、食物和醫療用品。$B$B順著路南下並且進入沼澤的內部。在這條路帶你到達泥鏈營地之前，你會經過塔貝薩的農場還有石槌廢墟。盡可能的幫助那邊的領導人吧。', '跟泥鏈營地的德拉席特·滴栓談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11216 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11216, 'zhTW', '大法師艾特羅斯', '我的導師叫我來這裡尋找協助，但可惜他們不允許我離開陰鬱城，而且會來這裡的人通常都無法幫上什麼忙。$B$B你的確看起來不一樣，像是一位冒險家。假如你有興趣協助我們的話就去麥迪文的舊住所，卡拉贊的外頭跟大法師艾特羅斯談談。$B$B同時，我將試著徵求前往這座城市其他地方的通行權。據說我們有一位舊夥伴就在這裡。', '到逆風小徑跟卡拉贊外的大法師艾特羅斯談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11217 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11217, 'zhTW', '抓住龍的尾巴', '由於飛艇失事延緩了補給品的供給，我們的醫療用品和繃帶已經用光了。$B$B我們已經盡可能的物盡其用了，但是平日所要應付的昆蟲、傷亡和敵人已經幾乎耗光我們的醫療資源了!我已經找到一種植物似乎可以療傷和止痛，但它同樣地也面臨短缺的情況。$B$B它叫做龍尾草，並且大量的生長在城鎮東邊的黑龍谷和巨龍泥沼一帶。這種草帶有環狀的莖鬚，並且當你注視著它的時候會產生脈動。', '泥鏈營地的吉希克斯·污流要你交給他8根龍尾草的莖。', '', '去塵泥沼澤找泥鏈鎮的吉茲克斯·格里古格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11218, 'zhTW', '危險!炸彈!', '$n，隊長指派我一個任務，而我需要你的幫忙。$B$B一些我的探險者協會朋友，在北邊低語峽谷挖掘東西的時候發瘋了，他們攻擊任何想要進去的人。$B$B隊長只擔心供應要塞的礦石。幸運的是，我有能夠搞定這件事情的東西。$B$B進去那兒，炸掉礦石，把所有你找到的寶石帶回來。你知道嗎，經營這個地方可不便宜!$B$B但我得警告你，那種礦石很怪!', '利用鋼環防呆火藥來收集6枚低語峽谷礦石碎片以及18顆低語峽谷寶石，然後交給鎮西要塞的賽波‧鋼環。', '', '去找凜風峽灣的賽波‧鋼環。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11219, 'zhTW', '阻止火勢!', '部落的孩子需要你，$n。無頭騎士曾是個人類聖騎士，如今他只是個瘋狂的魔鬼，他正在我們的村莊裡四處放火!你一定要撲滅那些火焰!$B$B拿起水桶灑向火焰吧，或是把水桶交給靠近火源的夥伴。撲滅所有的火焰並且阻止無頭騎士!', '戴面具的孤兒監護員要你幫忙撲滅村莊中的火勢。等火完全撲滅之後，再和鎮上的戴面具的孤兒監護員交談。', '撲滅火勢', '去找戴面具的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11221, 'zhTW', '來自戰場的報告', '我們在北裂境的任務就是摧毀阿薩斯。聯盟只不過是個妨礙，只要找到他們的蹤影我們就應該擊垮他們。$B$B我們摧毀了他們最東部的艦隊，但生還者卻在遺棄水岸架設起防禦的木柵，就在南方不遠處。我們的部隊早該擊敗他們，但是我們卻低估了他們的求生意志。去找到戰場上的軍官，黑暗遊俠利雅娜以及亡靈哨兵拉薩爾，讓他們兩個人報告情況。', '和戰場上的黑暗遊俠利雅娜以及亡靈哨兵拉薩爾交談，他們就在復仇臺地南方的浴血谷。等你完成之後，向高階執行官安賽姆回報。', '', '去找凜風峽灣的高階執行官安賽姆。', '聆聽拉薩爾的回報', '聆聽萊亞娜的回報', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11222, 'zhTW', '警告伯瓦爾!', '也許我們沒有所有的答案，但把我們的發現交給大領主伯瓦爾·弗塔根至關緊要，而且要盡快!$B$B他必須要知道迪菲亞在暴風城中有著有力的支持者，而且這和瓦里安王的失蹤有關!$B$B我可以利用我的魔法縮短你前往暴風城的旅途。你準備好出發的時候就告訴我吧，$n。', '和暴風城的大領主伯瓦爾·弗塔根談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11223, 'zhTW', '返回珍娜身邊', '我得制定一個剿滅迪菲亞盜賊餘孽的計劃。請你回到塞拉摩，轉達我對珍娜女士的謝意。一直以來，她都是我們忠誠的夥伴和堅定的盟友。$B$B你可以去城西法師區的法師塔下尋找大法師馬林，他可以用法術迅速將你送回塞拉摩。', '與塞拉摩的珍娜·普勞德摩爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11224 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11224, 'zhTW', '趕回騾群', '我聽說北方的低語峽谷發生了一些不好的事情。探險者協會的不少人都去了那個地方，有人說他們因為他們的發現而發了瘋。$B$B但這都改變不了他們帶走了我們大多數騾子和裝備的事實。我不要失去這些騾子!$B$B如果你到那附近，剛好有遇上我的騾子的話，就走過去舉起手來威嚇牠們。牠們肯定就會乖乖回來。', '探險者艾比蓋兒要你對10隻被遺棄的運貨馱騾使用/舉手，然後回到鎮西要塞向她回報。', '', '去找凜風峽灣的探險者艾比蓋兒。', '遺棄的騾子已被趕走', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11225 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11225, 'zhTW', '女巫嶺的隱士', '沼澤似乎對人類有種奇怪的影響力。有些人光只是住在這裡就發瘋了。$B$B任何曾經居住在水光莊園的人都以某種驚人的方式陷入瘋癲。最後一任的所有者『沼澤之眼』加爾，就已經開始出現一些徵兆了。$B$B我並不完全瞭解那裡到底發生了什麼事，如果你願意深入調查的話，我將會非常感謝。$B$B莊園就在沼澤的東部邊緣。往東邊去，穿過藍色沼地和北點哨塔。莊園就在一塊幽魂出沒，叫做女巫嶺的地方。', '和水光莊園的『沼澤之眼』加爾談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11226 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11226, 'zhTW', '幽靈虎坐騎', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11227 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11227, 'zhTW', '讓牠們吃烏鴉', '高階執行官要我利用我的狗來找出敵人的斥候，但我得告訴你，這些瘟疫獵犬如果沒被餵飽是那裡都不會去的。$B$B如果軍方無法瞭解這些野獸很挑嘴，那他們也不能期待這些獵犬在戰場上會有什麼用，牠們根本不碰部隊給我的那些垃圾。$B$B你看來好像還挺閒的，你何不帶一隻狗去西邊獵烏鴉?那些烏鴉肉對我們來說是不怎麼樣，但我的狗狗都很喜歡!', '龐提烏斯，復仇臺地的狗籠管理者要你使用瘟疫獵犬鐵籠來召喚一隻飢餓的瘟疫獵犬，用峽灣烏鴉的烏鴉肉來餵飽牠們。那些烏鴉就在復仇臺地的西邊。', '', '去找凜風峽灣的龐提烏斯。', '已餵食瘟疫獵犬', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11230, 'zhTW', '埋伏!', '按理說這應該跟郊遊差不多。他們的部隊又飢又累，帶著傷而且裝備破爛。但不知道怎麼，我們居然一頭撞進他們的陷阱。$B$B我們靠近南方的暗礁以尋求掩護，卻被那些聯盟狗立刻包夾。$B$B我很抱歉的說，如果你想要用我們的火砲對任何東西發射的話，你恐怕得先幫我們把船給搶回來。', '風行者號上的哈克船長要你殺死15個北方艦隊海員。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11231 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11231, 'zhTW', '鑰匙與牢籠', '隊長或許不在意，但這事我們可多少知道一些，維酷人正在北方的夏勒布隆進行一種叫做「喚醒」的可惡儀式。$B$B他們用活人獻祭以補充他們不潔儀式的能量!$B$B$c，你一定要阻止這件事情!不管什麼人或什麼東西被關在籠子，你都要去把他們給放出來。我想那些維酷人會有鑰匙。$B$B聖光知道我們最不需要的，就是有越來越多那些奇怪的維酷人出現，更糟糕的是，他們有可能會喚醒一些更邪惡的東西!', '雷瓦瑞爾神父要你收集足夠的夏勒布隆鐵籠鑰匙，去釋放10個夏勒布隆囚犯。等你完成之後回到鎮西要塞向神父報告。', '', '去找凜風峽灣的雷瓦瑞爾神父。', '傑拉布倫的囚犯已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11232, 'zhTW', '指引方向', '我們應該有辦法殺出一條路回到我們的槍砲邊。不幸的是，能見度太差強人意了，所以你得從地面替我們將目標標示出來。$B$B帶著這些煙霧照明彈，到西邊被聯盟佔領的遺棄水岸去，沿著北邊的牆壁使用它們來標示火砲的位置。$B$B等清出一條通道給地面部隊後，就盡快去通知利雅娜。我們可以照顧好自己的。', '在遺棄水岸北邊牆壁的聯盟火砲處使用煙霧照明彈。完成任務後回到浴血谷回報黑暗遊俠利雅娜。', '', '去找凜風峽灣的黑暗遊俠利雅娜。', '東方火砲已標記', '西方火砲已標記', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11233, 'zhTW', '痛下殺手', '你已經在戰場上證明你的能力，$n。你非常有可能將局勢扭轉成對我們有利了。$B$B我現在有個非常重要的任務要指派給你。我不確定我們暴露的弱點能堅持多久，所以我們一定得利用出其不意這項優勢。$B$B我要你利用我們攻擊時所造成的混亂，混進去敵方刺殺他們的首領。依照階級來看，他們分別是:上尉歐斯特、中尉西里尼和士官羅利克。祝你好運，$c。', '復仇臺地南邊的黑暗遊俠利雅娜要你去遺棄水岸殺了上尉歐斯特、中尉西里尼和士官羅利克。', '', '去找凜風峽灣的黑暗遊俠利雅娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11235, 'zhTW', '對付夏勒布隆', '現在我們有另一個問題。活著回來的斥候告訴我維酷人正在他們北方的要塞中幹些見不得人的勾當。$B$B他們把那個地方叫做夏勒布隆，真是奇怪的名字。$B$B但這不重要，重要的是你要去那個地方把那些該死的東西給清理一番，然後看看你能不能查出他們在搞什麼鬼。$B$B我知道我能仰賴你，$n。', '亞當斯隊長要你去殺死15個夏勒布隆戰士、8個夏勒布隆符文使和8個夏勒布隆守眠者。完成之後，再回到鎮西要塞向他報告。', '', '去找凜風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11236 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11236, 'zhTW', '死靈主宰梅贊', '天譴軍團就在夏勒布隆，他們還有一堆死靈法師!他們一定是要把維酷人拉入阿薩斯的陣營。$B$B我要消滅那些死靈領主的領袖!$B$B不管要什麼代價，$n，我都要死靈主宰梅贊和他所計畫的一切都被消滅。$B$B我絕對不能讓維酷人與天譴軍團結盟!$B$B梅贊就在夏勒布隆的右後方平台。', '殺死死靈主宰梅贊。然後向鎮西要塞的亞當斯隊長回報。', '', '去找凜風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11237 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11237, 'zhTW', '夏勒布隆攻擊計畫', '這些計畫記錄了即將對鎮西要塞展開的攻擊。它顯示了時常在上空盤旋的冰霜巨龍加拉希恩也會參與進攻。$B$B法師中尉瑪歷斯特肯定會對這件事情有所建議。把計畫交給在要塞南方的他。', '把夏勒布隆攻擊計畫交給鎮西要塞的法師中尉瑪歷斯特。', '', '去找凜風峽灣的法師中尉瑪歷斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11238 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11238, 'zhTW', '冰霜巨龍與它的主人', '你把這個東西拿來給我是對的，$n。你得排除萬難前往夏勒布隆，並殺了那隻飛龍和牠的主人，喚龍者惡邪!$B$B即使是現在，就在我們進行談話的當下，冰霜巨龍可能已經在路途中了。$B$B不過，如果我從這些計畫中理解得沒錯的話，在夏勒布隆外左後方喚龍者的平臺上吹響這個喚龍者號角，就可以將加拉希恩召喚回去。當這隻生物降落後，就殺了牠!$B$B還有，$n，請把號角帶回來給我。我們可不想讓它落入不適當的人手中。', '殺了喚龍者惡邪並使用喚龍者號角將加拉希恩召喚回來，殺了牠。接著，帶著號角回到鎮西要塞交給法師中尉瑪歷斯特。', '', '去找凜風峽灣的法師中尉瑪歷斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11239 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11239, 'zhTW', '侍奉聖光', '你的作為已經成為了典範，$n，不過還有某件事一直困擾著我:天譴軍團。$B$B聖光無法接受他們的存在，我們也沒辦法接受。我希望這個要求對你來說不會太過份，不過我要你往北回到夏勒布隆，並摧毀那個邪惡巢穴中不潔的天譴軍團!記得也要查探夏勒布隆底下的喚醒之廳。$B$B淨化即是救贖的關鍵，孩子。為我們帶來榮耀吧!', '殺死10隻不滅的看守者、4頭駭人的恐獸以及2隻腐爛的活屍。結束以後，將成功的消息告訴鎮西要塞的雷瓦瑞爾神父。', '', '去找凜風峽灣的雷瓦瑞爾神父。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11240 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11240, 'zhTW', '發狂者的首領', '喔，夥伴，我真的不想這麼說，但是當你不在的時候，上尉對那個地方熱切的關心起來。$B$B看來他想要讓我那個年老的探險者協會首領死掉。我猜我們得集合成一隻防衛隊前往肅清他們的餘黨，上尉想要他們的人頭落地，如同過去一樣。$B$B幫我個忙好嗎？回到低語峽谷並解決掉史盔吉‧獵像者。在我的記憶中，我推測他應該在洞穴裡的西北角落。', '殺掉史盔吉‧獵像者，然後回到鎮西要塞回報賽波‧鋼環。', '', '去找凜風峽灣的賽波‧鋼環。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11241, 'zhTW', '火的蹤跡', '謝謝你幫我脫離這場混亂，$n。我一點也不想知道那些聯盟的卑鄙小人打算對我做什麼。$B$B讓我們離開這裡，看看我們有沒有辦法向他們討回公道。那是營火嗎？', '護送藥劑師漢尼斯逃出遺棄水岸。完成這個任務後，回報給藥劑師黎珊達。她就在凜風峽灣的復仇臺地。', '營救藥劑師哈尼斯', '去找凜風峽灣的藥劑師黎珊達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11242 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11242, 'zhTW', '終獲自由!', '憤怒是我的囚牢，$n，而你釋放了我。儘管我自詡正義，但我帶給艾澤拉斯良善百姓的死亡與恐懼，讓我的靈魂悔恨垂淚。$B$B感謝你領我重回聖光。希望我永遠也不會再次迷失。$B$B帶著這本破碎的祈禱書給孤兒監護員，那些孩子將會知道我再也不會去騷擾他們了。', '帶著湯瑪斯‧托姆森的聖典交給變裝的孤兒監護員，她在閃金鎮、卡拉諾斯或藍色守望。', '', '去找變裝的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11243 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11243, 'zhTW', '如果瓦爾加德陷落...', '如果瓦爾加德陷落了，我們深入北裂境的主要補給線將會不再存在。這樣的話，我們全都成為巫妖王的僕從就只是時間問題了。我對你瞭解不多，但我在艾爾文還有妻子和三個小孩。而且要是我連一場戰鬥都沒打就倒下，那我可真該死了。$B$B此地的情勢危急，我們用得上所有你召集來的幫手。到前門去打敗那些入侵的怪物，協助守衛保護這座城市!', '海軍中將凱勒要你殺死12個掠龍入侵者或掠龍座狼。他就在凜風峽灣的瓦爾加德港口。', '', '去找凜風峽灣的海軍中將凱勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11244 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11244, 'zhTW', '拯救那些救援者', '我們到這裡已經一個月了，而那些畸形的巨人毫無預警地出現。我們對這樣的攻擊幾乎毫無防備，為了我們的自滿付出了沉重的代價。我們損失了整個考古隊，還有一些鎮民被綁架帶去遺跡。之後我們就一直處於守勢。$B$B更糟糕的是，我們派去救援的斥候被維酷人用魚叉攻擊，就在瓦爾加德北方的森林中等死。清除那些魚叉，救出我們的斥候!', '海軍中將凱勒要你拯救8個被刺穿等死的瓦爾加德斥候。他就在凜風峽灣的瓦爾加德港口。', '', '去找凜風峽灣的海軍中將凱勒。', '已救出瓦爾加德偵察兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11245 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11245, 'zhTW', '危險的塔樓', '$G先生:女士，如果我們想要透過斯克恩，就必須清除那些塔樓！$B$B如果您注意過那些塔樓，就會發現樓頂上站滿了施法者。太靠近它們的話，我們都會完蛋的！$B$B但我們已經從西部衛戍要塞請求了火力支援。為了準確地摧毀那些塔樓，我們要儘量靠近它們，然後放出定位的煙幕彈。$B$B別靠得太近就行了！', '西部衛戍軍士要你轉至斯克恩，利用軍士的煙幕彈標記四座塔樓的位置，供炮擊定位用。', '', '去找西部衛戍軍士。如果西部衛戍軍士不在附近那麼請使用你的西部衛戍令牌。', '標記西北塔樓', '標記東部塔樓', '標記西南塔樓', '標記東南塔樓', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11246 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11246, 'zhTW', '可怕而必要的手段', '我們得到報告說，這些維庫人會死而復生。他們和天譴軍團不一樣，是另一種形式的不死生物。$B$B我們不能冒這個險。$B$B來，拿著我的刀。當我們穿過這個地區的時候，你要用它確保那些被我們打倒的維庫人不會再突然跳起來。這本該是我的工作，可惜我的胃比較脆弱。$B$B<中士幸災樂禍地笑了笑。>$B$B這把刀我已經磨了一上午了，肯定非常好用。', '西部衛戍軍士要你轉至斯克恩，利用軍士的彎刀確保20個斯克恩部族的維庫人無法復活。', '', '去找西部衛戍軍士。如果西部衛戍軍士不在附近那麼請使用你的西部衛戍令牌。', '確保斯克恩的維庫人不再復活', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11247 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11247, 'zhTW', '燃燒吧，斯克恩，燃燒吧！', '亞當斯上尉曾經嚴令我必須重點打擊此地的基礎設施。$B$B但既然現在這裡由您負責，那您可以酌情處理。$B$B我建議我們是否可以去燒燬斯克恩窪地裡的那兩座長屋和兵營？我們只需要進入這些建築內部，然後把這根火炬扔進去就行了。', '西部衛戍軍士要你轉至斯克恩，利用軍士的火炬燒燬東北方的長屋、西北方的長屋以及兵營。', '', '去找西部衛戍軍士。如果西部衛戍軍士不在附近那麼請使用你的西部衛戍令牌。', '點燃西北方的長屋', '點燃東北方的長屋', '點燃兵營', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11248, 'zhTW', '行動:斯考恩之怒', '$n，我現在一定要請求你接下一個非常冒險，非常危險，只有你才有辦法完成的工作。$B$B維酷的堡壘，斯考恩，就在東邊的邊境。我的斥候通知我那些「巨人」準備好要攻擊我們，而我的軍力四散在峽灣各地，所以我手邊沒有足夠的人手可以憑武力拿下該處。$B$B反之，你得使用你的小聰明。我已經派了一位瞭解細節的士官到前線去。在斯考恩將這個指揮徽記亮出來，他就會現身並聽從你的指揮。', '亞當斯隊長要你在斯考恩使用鎮西指揮徽記，然後與鎮西士官談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11249, 'zhTW', '阻止昇華！', '這張巨大的卷軸是用龍皮製作的。展開這張長達十尺的卷軸之後，你看到覆蓋著鱗片的卷軸上畫著一副維庫人的神秘儀式的場景。$B$B一個維庫領主，在一群天使形象的生物的環繞中，正緩緩升入天堂。而這副圖的後臺，則是一個神秘而巨大的黑影。$B$B你突然意識到，這就是斯克恩的領主正要去做的事。你必須阻止他！在斯克恩的頂層，領主的房間外已經堆好了一大捆木柴。', '在領主的火堆附近展開維庫昇華卷軸，召喚出維庫領主並殺死他。完成以後，鑑於這種儀式的性質，你確信西部衛戍要塞裡的萊瓦里安神父會對這張卷軸感興趣。', '', '去凜風峽灣找西部衛戍要塞的萊瓦里安神父。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11250 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11250, 'zhTW', '斯考恩征服者萬歲!', '呃...您...已經完成了被派來此地的每一件任務，$g先生:女士;。我必須要說我很榮幸能聽從這樣一位優秀而年輕$r的指揮。$B$B隊長一定會很樂於知道你的成功，但如果你因為任何理由要繼續待在這裡，我將聽任你的指揮。', '將鎮西指揮徽記還給鎮西要塞的亞當斯隊長。', '', '去找凜風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11252, 'zhTW', '進入俄特加德!', '聽著，小鬼。我已經幹掉了我份內數量的敵人 - 甚至連你的份都解決了。你要知道...$B$B那些維酷人在戰鬥中毫不畏懼。他們甚至渴望能犧牲戰死。靠著他們的數量和這樣的兇殘，我們死定了 - 無庸置疑。$B$B他們只在意一件事，就是因格瓦的名號。我不瞭解他們為什麼這麼努力想要獲得因格瓦的讚揚，但如果能扳倒他，肯定會對他們的士氣造成嚴重的打擊。$B$B那麼，我們或許還有一絲機會...', '防衛者摩丹要你去殺死住在俄特加德深處的『盜掠者』因格瓦。然後把他的頭交給海軍中將凱勒。', '', '去找凜風峽灣的海軍中將凱勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11253 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11253, 'zhTW', '嗅出敵人', '現在這個無賴的肚子已經餵飽了，或許會比較願意合作。這是牠的鍊子，等你準備好了就把牠從籠子裡面放出來吧。$B$B我不知道安賽姆期待你會找到什麼，但是別放過這條狗帶給你的任何線索。', '在復仇臺地的瘟疫獵犬鐵籠附近使用瘟疫獵犬之鍊，然後在瘟疫追蹤獵犬所帶你去的地點尋找線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11254, 'zhTW', '龍皮地圖', '看得仔細一點，卷軸顯然是一張非常詳細的峽灣地圖。許多村莊的地點還描繪了一些像是部族徽記的圖案。$B$B復仇臺地的地點則標上了一個不成比例的大骷髏。$B$B這張地圖想必對高階執行官安賽姆來說很有軍事價值。', '把龍皮地圖交給復仇臺地的高階執行官安賽姆。', '', '去找凜風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11255 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11255, 'zhTW', '龍顱囚犯', '這場戰鬥尚未結束，$n。如果那座村子中依舊有我們的同胞存活，就得有人去把他們給救出來。$B$B<海軍中將凱勒對你點點頭。>$B$B前往北方，並且進入龍顱村。進入之後尋找我們的同胞。如果他們被囚禁的話，你需要想個辦法把他們給救出來。$B$B或許他們會有進一步的消息，能說明我們到底在和什麼戰鬥。', '海軍中將凱勒要你去解救3個被俘虜的瓦爾加德囚犯。他就在凜風峽灣的瓦爾加德港口。', '', '去找凜風峽灣的海軍中將凱勒。', '已救出瓦爾加德的俘虜', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11256, 'zhTW', '拿下斯考恩!', '$n，維酷族的堡壘，斯考恩，就在南邊。那兒的奇特巨人最近甦醒過來，並且開始向外擴張，無所不用其極的攻打我們。$B$B探子來報，他們將在這裡對我們發動攻勢，但我軍的力量不足與對抗他們。因此，我們將準備前往北方，到較為安全的地方去。$B$B我請求你運用你的機智為我們爭取一些時間。我派了一名勇士，他將告訴你詳情。在斯考恩亮出這枚紋章，他就會現身，並且盡一切力量幫助你。', '灰燼圖騰酋長要求你在斯考恩使用冬蹄紋章，與冬蹄勇者交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11257, 'zhTW', '駭人聽聞的必要工作', '長老告訴我們，維酷族人可能會死而復生;不是你們說的天譴軍那種活死人喔，而是一種不同的不死生物。$B$B但千萬不能冒險。$B$B喏，把我的砍刀帶著。當我們通過這個地方以後，把我們殺掉的維酷人屍骨剁碎。$B$B我花了一整個早上把刀子磨利，就算是他們的骨頭也應該砍得斷。', '冬蹄勇者要你使用勇者砍刀支解20名斯考恩的溫特斯考恩部族維酷人。', '', '', '寒冬扭曲維库人已肢解', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11258, 'zhTW', '燒啊，斯考恩，燒啊!', '灰燼圖騰酋長命令我燒毀這裡的許多房子。$B$B不過，既然你是老大，這個責任就落到你肩上了，$n。$B$B我建議燒掉那兩間長屋，還有兵營，都在斯考恩低窪的地區。我們要做的，就是潛進裡面，用火炬點燃建築物。', '冬蹄勇者建議你使用勇者火炬，在斯考恩東北與西北邊的長屋以及兵營縱火。', '', '', '西北方長屋已點燃', '東北方長屋已點燃', '軍營已點燃', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11259, 'zhTW', '厄運的哨塔', '當我們經過斯考恩，我們一定要摧毀這些哨塔。$B$B只要你看過這些塔，你會看到塔頂安排了許多施法者。太靠近這些哨塔你的厄運就會降臨。$B$B然而，我們可以請求冬蹄營地的蠍尾獅進行空襲。要這麼做，我們得夠靠近，好讓你在塔頂施放煙霧信號彈。$B$B不過別太靠近就是了。', '冬蹄勇者告訴你使用勇者信號彈標記出所有的四座斯考恩哨塔，以利空襲成功。', '', '', '西北方塔樓已標記', '東方塔樓已標記', '西南方塔樓已標記', '東南方塔樓已標記', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11260, 'zhTW', '阻止飛升!', '這份巨大的卷軸是由龍皮做成。翻開它超過10呎長的內容，你可以看到塗抹在鱗狀表面的圖像描述著一道神秘的維酷儀式。$B$B一位維酷的族長，被某種外表像天使一般的東西環繞著，飛升上天。一個神秘，黑暗的人影隱約出現在圖像的背景中。$B$B你體內一陣刺痛告訴你斯考恩的族長正在附近著手準備進行這個儀式。你必須阻止這件事!斯考恩的頂端有一大堆的柴堆，就在族長的會所前。', '在族長的柴堆附近使用維酷飛升卷軸將他召喚出來並殺掉他。之後，由於儀式的類型，你確定冬蹄營地的主母安卡會對這份卷軸相當感興趣。', '', '去找凜風峽灣的主母安卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11261, 'zhTW', '斯考恩征服者!', '你已經將派我們來要做的工作都完成了，$c。我得承認你是個戰鬥好手，你的族人並不如我一開始所想的那麼奇特。$B$B灰燼圖騰酋長一定很想聽到你成功的消息，不過，假使你決定在這多待一會，不論理由是什麼，我會繼續和你並肩作戰的。', '將冬蹄紋章交給冬蹄營地的灰燼圖騰酋長。', '', '去找凜風峽灣的灰燼圖騰酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11262, 'zhTW', '因格瓦非死不可!', '我們整個隊伍就只剩我還活著。$B$B這些維酷人是無情的戰士。他們的人數佔有優勢，戰略兇狠無比，我們唯一的希望就是打倒他們的領袖，然後祈禱這會造成他們的指揮系統大亂。$B$B對方的領袖叫做因格瓦，把他的頭顱給我帶來!', '黑暗遊俠瑪拉請求你殺死俄特加德要塞的『盜掠者』因格瓦。', '', '去找凜風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11263, 'zhTW', '對付夏勒布隆', '活著回來的遠偵斥候通報我，維酷人在西邊他們的主堡中被喚醒了。$B$B那是個叫做夏勒布隆的禁區，遠偵斥候告訴我，維酷人正在舉行一場奇怪的儀式。$B$B我們不能讓儀式繼續下去。$B$B你願意繼續幫助我們嗎？你能夠在他們完成任何儀式，向我們攻擊之前，幫我們殺掉夏勒布隆的維酷人嗎？', '灰燼圖騰酋長要求你殺掉15名夏勒布隆戰士、8名夏勒布隆符文使和8名夏勒布隆守眠者。事成之後，回到冬蹄營地向他回報。', '', '去找凜風峽灣的灰燼圖騰酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11264, 'zhTW', '死靈主宰梅贊', '這些死人都在夏勒布隆，和死靈法師一夥？$B$B我們必須把死靈領主的領導者消滅才行。$B$B$n，不計一切代價去完成，小心死靈主宰梅贊，不管他嘗試要完成什麼，制止這件事。$B$B不管他們利用這些不死生物從事什麼，我們都無法承擔維酷族人成功的後果！$B$B找到梅贊，他就在夏勒布隆右後方區域的平台上。', '殺掉死靈主宰梅贊以後，向冬蹄營地的灰燼圖騰酋長回報。', '', '去找凜風峽灣的灰燼圖騰酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11265 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11265, 'zhTW', '鑰匙與牢籠', '在我們僅有的瞭解中，維酷人正進行一個非自然的儀式，一個「喚醒」儀式，在西邊的夏勒布隆。$B$B$n，你一定要阻止這件事。不管是誰或什麼東西被關在那些籠子裡，都一定要救他們出來。我猜，維酷人擁有鑰匙。$B$B我們最不願意見到的是那些奇怪的維酷人對我們造成威脅，或著更糟，他們把更邪惡的生物喚醒...', '主母安卡要求你收集足夠的夏勒布隆鐵籠鑰匙，將10名夏勒布隆囚犯救出來。當你完成以後，回到冬蹄營地向她回報。', '', '去找凜風峽灣的主母安卡。', '傑拉布倫的囚犯已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11266 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11266, 'zhTW', '夏勒布隆攻擊計畫', '這些計畫書詳述著即將對冬蹄營地發起的攻擊。在上空盤旋的冰霜巨龍，加拉希恩，看來似乎是將會參與攻擊。$B$B毫無疑問，賽利亞‧冰鬃在這件事當中會提供她的協助。將計畫帶到東邊的營地交給她。', '將夏勒布隆攻擊計畫送到冬蹄營地交給賽利亞‧冰鬃。', '', '去找凜風峽灣的賽利亞‧冰鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11267 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11267, 'zhTW', '冰霜巨龍與它的主人', '你將這個東西拿來給我的直覺是對的，不過我的蠍尾獅無法與龍相抗衡。你得往西探索並前往夏勒布隆，殺掉那隻冰霜巨龍和它的主人，喚龍者惡邪!$B$B現在它可能就在途中了!$B$B如果我從這些計畫中理解沒錯的話，在夏勒布隆左後方外的平臺上吹響喚龍者號角，加拉希恩就會回去。當這隻生物降落之後，就殺了它!$B$B還有，$n，把號角帶來給我。我們不想讓號角落入壞人的手裡!', '殺了喚龍者惡邪並使用喚龍者號角將加拉希恩召喚下來然後殺掉它。完成後，帶著號角回到冬蹄營地找賽利亞‧冰鬃。', '', '去找凜風峽灣的賽利亞‧冰鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11268 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11268, 'zhTW', '活屍橫行', '你給予我們的協助遠超過我們所冀求，$n，但有件事情依舊令我困擾:那些叫做天譴軍團的東西。$B$B在這個世界底下的大地、空氣、水與火焰的精靈無法容忍他們的存在，卻似乎不打算對他們出手。我們要讓天譴軍團知道，他們在和誰作對!$B$B也許這個要求太過份了，但我希望你能回到西方，前往夏勒布隆，毀滅那些邪惡巢穴中違反自然的天譴軍團。記得也要查探夏勒布隆底下的喚醒之廳!', '殺死10個不滅的看守者、4隻駭人的恐獸和2隻腐爛的活屍。然後，通知主母安卡你的成功，她就在冬蹄營地。', '', '去找凜風峽灣的主母安卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11269 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11269, 'zhTW', '羽絨之於絲線', '聯盟的先鋒將於幾天內抵達。這些士兵等著要用禦冬裝備，但是我還有幾件披風要完成。$B$B一直以來我都使用斑點角鷹獸的羽絨作為披風的內裡，但是我的存貨用完了!$B$B你一定要幫幫我，$n。要是這些披風沒有即時完成，亞當斯隊長一定會剝了我的皮!把所有你找得到的羽絨帶來給我。換毛期的角鷹獸在飛越堡壘附近的荒野時，身上的毛都會掉落地面。', '吉爾‧葛瑞斯特要你帶10團斑點角鷹獸羽絨給他。', '', '去找凜風峽灣的吉爾‧葛瑞斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11270 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11270, 'zhTW', '戰爭就是地獄', '我們已經慢慢毀掉暴風城位於這座海岸的北方艦隊餘黨。位於西邊的屍體就是這場對抗的殘暴證明。$B$B這並不會影響我高雅的審美觀，不過這倒是對我們的生命造成了危險。$B$B在這片巫妖王的土地上，死者隨時都會甦醒過來化為對付我們的武器。拿著這把火炬 - 你得要去確認這種事不會發生。', '復仇臺地的高階執行官安賽姆要你拿著點燃的火炬，使用它燒掉10具被丟棄在城鎮西邊的屍體。', '', '去找凜風峽灣的高階執行官安賽姆。', '陣亡戰士已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11271 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11271, 'zhTW', '加緊準備', '我的族人很重視斑點角鷹獸的羽絨，從單純裝飾到製作儀式服裝都用的上。我們正在進行離開崗哨的準備，所以這是本季最後一次收集的機會了。$B$B要是你肯幫忙，我就能弄到足夠的存量，以確保大家都能擁有長途跋涉所需要的裝備。山裡的情況變化很快，風暴可能毫無預警的就出現了。$B$B你可以在崗哨周圍的地面找到這些羽絨。', '冬蹄營地的阿喉塔‧白霜要你帶10團斑點角鷹獸羽絨給他。', '', '去找凜風峽灣的阿喉塔‧白霜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11272 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11272, 'zhTW', '有待解決的宿怨', '這個精靈王子還以為自己可以任意進出我的國土，侮辱皇后，屠殺百姓，拍拍屁股然後走人?他以為我們會在俄特加德的部落增員發動攻擊時袖手旁觀?$B$B門都沒有。$B$B你得進入俄特加德然後殺掉他。我要阿薩斯知道我們已經來了，而且我們不是鬧著玩的。$B$B事情完成後向俄特加德要塞的黑暗遊俠瑪拉回報，她會了結剩餘零星的事務。', '高階執行官安賽姆要你進入俄特加德要塞並殺掉凱雷希斯親王。', '', '去找凜風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11275, 'zhTW', '製作號角', '我的族人世世代代都在獵殺這些山丘上的巨型雪人，而我今年要初次加入打獵。這很可能是我們永遠離開這個崗哨以前的最後一次狩獵了。$B$B為了替這次的狩獵做準備，我必須用山羊角做出一個響亮的號角，牠們就漫步在營地附近的雪地中。長者告訴我說那聲音很像女性雪人的發情聲，不過我很懷疑。$B$B將你找到最好的山羊角帶來給我，$n，我會從裡面挑一個出來。', '冬蹄營地的諾可瑪‧雪先知要你帶6個未受損傷的山羊角給她。', '', '去找凜風峽灣的諾可瑪‧雪先知。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11277 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11277, 'zhTW', '邪惡深淵', '他們將迪剛恩關在附近一個大型競鬥場的籠子裡。在我收集到的消息指出，掠龍者讓他們的囚犯與他們最強大的鬥士對打。他們會將輸家丟到地下室讓天譴軍團的死靈法師將他們變成食屍鬼!太恐怖了!$B$B不過事有先後順序!石板就散落在整個地城中。我們先來找到這些石板，你再去嘗試當個英雄吧。', '俄特加德墓窖的葛羅倫費德要你去收集10個龍顱石板。', '', '去找凜風峽灣的葛羅倫費德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11278, 'zhTW', '回到瓦爾加德', '為了發現這樣聖物，我們羞愧地損失了兩名最優秀的矮人。他們犧牲生命保住了這些資訊。$B$B<葛羅倫費德用一件破衣服把密碼與石板裹了起來。>$B$B帶著這個回到瓦爾加德。麥克索夫會知道該怎麼處理這些東西。$B$B至於我?我自己一個人沒問題的。我都已經撐了這麼久!', '把葛羅倫費德的包裹交給瓦爾加德港口的貝爾川‧麥克索夫。', '', '去找凜風峽灣的貝爾川·麥克索夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11279 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11279, 'zhTW', '綠色的龍蛋和幼龍', '我們正在研究的新瘟疫非常驚人，我想繼續研究。$B$B要不要拿些元龍寶寶來試試看？！$B$B想想它的可能性，不只能感染人形生物，這種瘟疫可以感染任何物種！$B$B來，我多準備了一瓶瘟疫，就是為了這一刻，就是為了你。$B$B將它灑在西北方餘燼窩巢的蛋上，然後從孵化的染疫元龍身上採集樣本。', '瘟疫使者提林加斯特要你去收集10個染疫元龍幼龍採樣，並送到新阿加曼德給他。', '', '去找凜風峽灣的瘟疫使者提林加斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11280 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11280, 'zhTW', '龍胃炎', '等等，那讓我想到一個點子！假定瘟疫是因為散佈在蛋殼外面所以才殺不死這些雛龍呢？$B$B$n，我們一定得將瘟疫殖入牠們體內！$B$B我知道了！我這裡有一些染疫肉塊。將肉塊拿到餘燼窩巢，讓牠們吃掉！$B$B不，我們想得太狹隘了。我們來讓一隻在天空中飛翔的元龍降落下來吃掉肉塊。$B$B沒錯！$B$B站在肉塊附近並觀察接下來發生的事。沒錯，牠可能會攻擊你，不過這就是進步的代價。', '新阿加曼德的瘟疫使者提林加斯特要你使用提林加斯特的染疫肉塊去吸引一隻元龍降落，並觀察牠吃肉塊的反應。', '', '去找凜風峽灣的瘟疫使者提林加斯特。', '已觀察始祖幼龍瘟疫的結果', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11281, 'zhTW', '模仿自然的呼喚', '號角已經粗略製作完成了，不過在我進行傳統的雕刻前，我想要先確認一下號角是否有用。阿喉塔告訴我說他在崗哨東北邊凍結的瀑布底下測試他的號角。阿喉塔還告訴我說我們的獵人世代都這樣利用凍水的音響效果。我等不及想要知道更多了！$B$B你可以幫我去測試這個號角嗎？如果我沒弄錯，你說不定還會引來一頭雪人，所以請做好準備！一旦你測試完號角，就把它帶回來給我！', '測試雕紋號角，然後將結果帶回冬蹄營地交給諾可瑪‧雪先知。', '', '去找凜風峽灣的諾可瑪‧雪先知。', '測試諾科瑪之角', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11282, 'zhTW', '恐懼的一課', '等你像葛司一樣經歷過許多次的戰鬥之後，你會知道，打擊敵人最好的方法就是讓他們怕死怕得要命!$B$B但這些維酷人一點都不害怕。你殺死一個，另一個又衝上來...比起前一個吼得更大聲，武器也更大一把。$B$B唯一讓維酷人害怕的方法就是殺死維酷人中最壯最壞的傢伙。$B$B越過封鎖去和那些溫特斯考恩作戰吧，直到維酷英雄出現!然後殺死他們，把女王的旗幟插在他們的屍體上。讓他們學會什麼叫做恐懼!', '葛司要你去殺死『放血者』兀夫、『災害』歐立克和古拿‧索瓦德森然後把被遺忘者旌旗插在他們的屍體上。在被遺忘者封鎖線附近殺死那些維酷人直到他們出現。', '', '去找凜風峽灣的葛司中士。', '邪惡者歐里克的屍體已被刺穿', '放血者烏爾夫的屍體已被刺穿', '岡納·索爾瓦森的屍體已被刺穿', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11283, 'zhTW', '貝爾海姆死亡人數統計', '他們維酷人不斷不斷的從西邊的城鎮中湧來，看都看不到邊!$B$B葛司有個主意，你到城鎮「裡面」殺掉溫特斯考恩人。「馬上」他們就不會再來了!', '葛司中士需要你去貝爾海姆殺掉16名溫特斯考恩維酷族人。', '', '', '巴雷海姆的死亡人數', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11284, 'zhTW', '隔壁的雪人', '如果哨兵不願意幫我，你願意嗎？我是橋那邊礦坑的工頭。我的手下正在為了提供探險隊用來挖通灰白之丘通道的武器而進行採礦。$B$B但有隻巨大的雪人入侵了礦坑，擋住了我們要開通的隧道！我們試著對牠大喊或是拿煙燻牠，但全都沒用。$B$B也許你可以用城鎮附近雪地中的霜角山羊肉做成一餐，把牠從睡眠中喚醒？拜託？我們束手無策了！', '威德瓦堡壘的工頭寇畢要你去打倒碎角。', '', '去找凜風峽灣的工頭寇畢。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11285, 'zhTW', '燒盡貝爾海姆!', '殺死溫特斯考恩的人可能還不夠，也許多燒一些他們的房子吧!呃...還有他們的橋。我們應該把整個市鎮燒光才能確保安全!$B$B拿著這把火炬到貝爾海姆，前往西方，然後把舉目所見「全部」燒光!這就能好好教訓他們一頓。', '葛司中士要你前去貝爾海姆，並使用葛司的火炬燒毀1間溫特斯考恩居所、1間溫特斯考恩瞭望塔、1座溫特斯考恩橋樑以及1間溫特斯考恩兵營。', '', '', '寒冬扭曲住所已焚燒', '寒冬扭曲瞭望塔已焚燒', '寒冬扭曲橋樑已焚燒', '寒冬扭曲軍營已焚燒', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11286, 'zhTW', '鋼鐵之門的神器', '我來到這裡是為了一個不同的理由;我的一位老朋友在夢中呼喚我。但是，如今我看到這些小傢伙用他們的機械在地上打出了一個大窟窿，讓我怒火中燒。$B$B舉目所及，這些矮人們，正如他們為人所知的，正在挖掘神器;一些對瞭解我們過去可能相當重要的神器。$B$B我要你到底下把那些東西拿給我。不要讓任何矮人阻擋了你的去路。', '賢者霧行要求你收集10樣鋼鐵之門神器。收集完成以後，回到鋼鐵之門向他回報。', '', '去找凜風峽灣的賢者霧行。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11288, 'zhTW', '閃耀的聖光', '<愛力士一面喘息，一面試著開口說話。>$B$B我是銀白十字軍的特使，身負著神聖的職責。$B$B我們的部隊在瘟疫之地傷亡慘重，藉由黎明曙光淨化了這個神器，使之再次恢復純淨。為了喚醒神器我們死了許多的同伴。$B$B還有機會...還有時間。$B$B神器被丟入逝者之穴，就在我們下方深處，由殘酷的亡者所守護。$B$B<愛力士的身體流閃著令人目眩的光芒。>$B$B聖光。將會。保護。你。', '俄特加德墓窖的『誓縛』愛力士要你去取回神聖法器。這是個有時間限制的任務。', '', '去找凜風峽灣的『誓縛』愛力士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11289 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11289, 'zhTW', '受榮耀的指引', '<愛力士微笑著。>$B$B榮耀歸諸聖光。你辦到了!$B$B<愛力士咳嗽。>$B$B拿著神器回到瓦爾加德。埃盧隆‧真刃領主等著它的回歸。$B$B朋友，帶著榮耀而戰。永遠。榮耀。$B$B<愛力士斷了氣。>', '將神聖法器交還給瓦爾加德的埃盧隆‧真刃領主。', '', '去找凜風峽灣的埃盧隆·真刃領主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11290 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11290, 'zhTW', '掠龍戰鬥計畫', '雖然我們沒找到多少關於因格瓦下落的資訊，但我們得知了雅尼思居住在龍顱村的洞穴裡，位在狼穴的旁邊。$B$B從獲救士兵身上匯集的情報指出，雅尼思保護著掠龍戰鬥計畫。$B$B我需要你回到龍顱村，將這些計畫找出來。把擋在你面前的維酷族人殺光 - 包括雅尼思!', '海軍中將凱勒要你把掠龍戰鬥計畫帶給他。他就在凜風峽灣的瓦爾加德港口。', '', '去找凜風峽灣的海軍中將凱勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11291 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11291, 'zhTW', '前往鎮西要塞!', '<海軍中將凱勒捲起了戰鬥計畫。>$B$B我們已經取得所有保住瓦爾加德需要的資訊。你一定得把這些戰鬥計畫送去西側峽灣峭壁邊的鎮西要塞。去找飛行管理員助理，艾米廬‧冬風談談。她可以讓你搭上一隻獅鷲獸前往鎮西。$B$B一旦你抵達那裡，去找亞當斯隊長。他是那裡的負責人。亞當斯會知道怎麼處理這些計畫。', '帶著掠龍戰鬥計畫前往凜風峽灣的鎮西要塞交給亞當斯隊長。', '', '去找凜風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11292 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11292, 'zhTW', '掠奪弱者', '很高興見到你。我來自灰白之丘，前來與你的同伴進行交易。我的族人在灰白之丘有一個很大的前哨站，你往北邊去時最好去拜訪一下。$B$B我已經在這附近的林地和雪地設置好陷阱了。有了這些陷阱抓到的動物肉及毛皮，我將擁有大量的貨物可以與鎮民進行交易。$B$B如果你願意幫忙從陷阱收回獵物的話，我可以讓你分紅。不過要當心，你不會是當地唯一的掠奪者。', '威德瓦堡壘的陷捕者傑桑要你帶8個受困的獵物給他。', '', '去找凜風峽灣的陷捕者傑桑。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11293 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11293, 'zhTW', '叫賣麥酒!', '我們需要讓大家知道有關麥酒家族在啤酒節的事。你得到銀行外、軍事區、探險者大廳以及秘法區外的旗幟下大聲叫喊。不過我會讓事情簡單點，我會借你競速山羊韁繩和一隻競速山羊4分鐘。用馬鞭驅趕山羊奔跑，不過試著別讓牠累過頭。', '在銀行外、軍事區、探險者大廳及秘法區外散佈有關啤酒節的訊息。', '', '去找丹莫羅的畢肯‧麥酒。', '在銀行外叫賣', '在軍事區叫賣', '在探險者大廳叫賣', '在秘法區叫賣', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11294 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11294, 'zhTW', '叫賣雷酒!', '是時候讓人們知道雷酒聽見了他們對於好啤酒的渴求。你得到銀行外、軍事區、探險者大廳以及秘法區外的旗幟下大聲叫喊。$B$B不過我會讓事情簡單點，我會借一隻山羊和一些馬鞭給你4分鐘。$B$B跑太快的時候要小心，你在鐵爐堡可找不到蘋果......我們可不想幫到麥酒的使者。', '在銀行外、軍事區、探險者大廳及秘法區外散佈有關啤酒節的訊息。', '', '去找丹莫羅的達然‧雷酒。', '在銀行外叫賣', '在軍事區叫賣', '在探險者大廳叫賣', '在秘法區叫賣', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11296 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11296, 'zhTW', '裂木森林的俘虜', '有某種東西激怒了附近的生物，可能就是那些被稱為天譴軍的活死人。$B$B在護送賢者來此的路上，我們大部分的獵人都折損在裂木寡婦的手上，她們是一種致命的巨大蜘蛛，就住在裂木森林的北部。$B$B我必須留在此地保護我們剩餘的力量，但是你…你可以幫我看看我的遠偵斥候是否還活著，也許被困在裂木寡婦的繭中。$B$B你願意嗎，陌生人？', '遠偵斥候穹雲要你釋放7名冬蹄遠偵斥候。完成之後，回到鋼鐵之門找他。', '', '去找凜風峽灣的遠偵斥候穹雲。', '已釋放冬蹄長跑者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11298 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11298, 'zhTW', '那瓶酒是啥？', '東南方是一個名為低語峽谷的地方。發了瘋的探險者協會成員在裡頭到處橫行!我們的商隊在穿越本區時遭到他們攻擊，他們還不停地襲擊我們的糧秣搜尋隊。$B$B我一定得知道到底是什麼造成了這次錯亂!我懷疑是他們喝的東西導致他們失去理智，就是那些散佈在峽谷中的桶子。我要你趁他們忙著採礦時，從那些矮人中偷出這些桶子。', '藥劑師營地的藥劑師馬爾薩斯要你帶5個矮人酒桶給他。', '', '去找凜風峽灣的藥劑師馬爾薩斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11300 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11300, 'zhTW', '審判競技場中的慘敗', '如果你擊敗了其他的鬥士，歐路夫就會出現。這大概是我們取回密碼的唯一方法。穿上一雙好靴子，我們得要在審判競技場忙上一會兒了。如果你真的取回密碼，把它拿給墓窖入口的葛羅倫費德。$B$B我?別擔心我!我們只差一點就能找到人類血緣中失落的環節了!', '擊敗審判競技場的鬥士們，然後面對『暴力』歐路夫。擊敗歐路夫然後取回上古密碼。將上古密碼交給俄特加德墓窖入口的葛羅倫費德。', '', '去找凜風峽灣的葛羅倫費德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11301, 'zhTW', '腦!腦!腦!', '馬爾薩斯有沒有抓著你嘮嘮叨叨地講那些啤酒桶還有瘋矮人的事情？$B$B我一點都不懷疑那些矮人瘋了，但我一點也不覺得偷那些矮人的啤酒會有任何幫助。$B$B我們需要的是大腦。大量的腦。我們將要立刻開始徹底研究這些謎團，說不定能替瘟疫找到新的材料。$B$B帶著這個鋸子，前往東南方的低語峽谷，殺死一些矮人。用這個鋸子從他們身上取出腦子，然後帶來給我。', '藥劑師營地的藥劑師格里克要你帶給他12個發狂的探險者大腦。', '', '去找凜風峽灣的藥劑師格里克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11302, 'zhTW', '神秘的冰雪樹妖', '我們第一次到達這附近為要塞選址的時候，曾經在北邊的兩處林地附近遇到了一些懷有敵意的生物。再後來，我們穿越鎮子南邊的那塊被冰雪覆蓋的林地時，又遇到了幾隻饒有興趣地觀察著我們的樹妖。不過，跟北邊那些林地裡的不同，她們沒有攻擊我們。$B$B當時，我們被這裡的鬼天氣折磨得暈頭轉向，而且又餓又累，她們完全可以不費吹灰之力就把我們殺個精光，可她們沒有那麼做。$B$B或許我們應該主動和她們接觸一下，去爭取所有能夠爭取到的盟友？你願意轉至冰雪林地，向她們表達我們的友善之意嗎？', '與冰雪林地的魯莉爾蕾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11304, 'zhTW', '新阿加曼德', '我擔心我們在復仇臺地的設備並不是最好的。畢竟這裡是個軍事哨站。$B$B我要你把這瓶菌種帶給新阿加曼德的首席瘟疫使者哈里斯，沿著路經過貝爾海姆往南，然後再往西。他們那邊的設備比較好 - 他會知道該怎麼做。$B$B動作要快，$n。我們的敵人越來越多也越來越強。我們需要發展出實際能用的武器來對抗他們!', '把黎珊達的菌種帶給首席瘟疫使者哈里斯，他在凜風峽灣西部的新阿加曼德。', '', '去找凜風峽灣的首席瘟疫使者哈里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11305 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11305, 'zhTW', '特製的配方', '我們持續噴灑維酷人的村莊已經一個禮拜了，可是那些混蛋就是不會死。$B$B面對現實吧，$n，到目前為止，我們的瘟疫已經作用在人類、矮人、狗、牲畜...你想得到的都有了。隨著菌種適應越來越多宿主，雜質也就隨之增加。我們所需要的，是專為維酷人生理所製的菌種。$B$B霍葛萊的酋長在我們接管該處之後就逃之夭夭了;你可以在西邊找到他。身為一位掠龍部族的族長，他的血液很理想。', '從索瓦爾德的身上得到掠龍族王之血，他就在索瓦爾德營地中，並將血液交給新阿加曼德的首席瘟疫使者哈里斯。', '', '去找凜風峽灣的首席瘟疫使者哈里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11306, 'zhTW', '進行高溫攪拌', '到目前為止，你做得很好，$n。我願意教你一些進階的技術，使你能對這場瘟疫有更深的認識。$B$B拿著這個空瓶子，裝滿我左手邊大鍋中的鮮血。並且把它調進我右手邊瘟疫樣本裡面，直到你獲得了安定的混合物為止。', '用維酷血液之鍋的血裝滿空的藥劑師燒瓶，接著將維酷血液瓶混進哈瑞斯的瘟疫樣本中，直到你獲得了安定的化合物為止。任務完成以後，向首席瘟疫使者哈里斯回報。', '', '去找凜風峽灣的首席瘟疫使者哈里斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11307, 'zhTW', '實地測試', '既然我們有了專為維酷人特製的新瘟疫菌種，就該在霍葛萊測試樣本。如果一切都照計畫進行，他們應該會立刻灰飛煙滅，因為他們的體內全都會被瘟疫吞噬殆盡!$B$B霍葛萊就在此地的北方。我們的瘟疫使者也已經把先前的瘟疫菌種準備好在那邊了 - 應該不難辨認。', '前往霍葛萊，對10個染疫掠龍維酷人使用瘟疫噴霧劑。然後向首席瘟疫使者哈里斯回報。', '', '去找凜風峽灣的首席瘟疫使者哈里斯。', '已對染疫維库人噴灑', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11309 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11309, 'zhTW', '工作所需', '哈里斯想要進行爆破，嗯？沒錯，我幫的上忙。$B$B不過，你得替我弄來一些材料。我不能把我的精選零件用在會爆炸的玩意上面。$B$B首先，我需要鍬牙韌帶…比人類的好用多了。$B$B我還需要一磅的肉。那個叫安東的傢伙有批肉好便宜，他在西邊的道路來回走動。', '新阿加曼德的『鋼鋸』潔妮要你收集6條鍬牙韌帶和1磅新鮮的肉塊。', '', '去找凜風峽灣的『鋼鋸』潔妮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11310 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11310, 'zhTW', '警告:待組裝', '嗯，拿去吧!我們的朋友將會有點...不安定。所以我建議你到霍葛萊以前，不要把他組合起來。$B$B等你到那兒以後，盡可能在自爆前集中多一點維酷人吧。$B$B成功以後，不管剩下什麼都帶來給我吧，屍塊我總是用得到!', '在霍葛萊中使用憎惡體配件工具，利用無腦的憎惡體組圍捕染疫維酷人。殺死至少20個維酷人後，向新阿加曼德的『鋼鋸』潔妮回報。', '', '去找凜風峽灣的『鋼鋸』潔妮。', '染疫維库人已消滅', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11311 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11311, 'zhTW', '壓制元素', '如果你要像我們一樣，在此地生存，你一定要學會如何面對環境的挑戰。隨著北方山丘上的元素逐漸增生，如果你警覺性不夠，元素將會取走你的性命。$B$B在我們離開此地之前，必須要最後一次削減那些元素。你願意在我們繼續準備的時候協助我們嗎？$B$B你必須要殺死你在前哨附近雪丘遇到的冰裂片元素或咆哮颶風。', '冬蹄營地的馴風者卡剛要你殺死8個山地的元素。你可以殺死冰裂片元素或咆哮颶風。', '', '去找凜風峽灣的馴風者卡剛。', '山脈元素生物已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11313, 'zhTW', '冰的靈魂', '在林地附近的冰元素曾經是我們的同伴，但是一股迅速且具破壞性的力量橫掃了這片土地，讓它們轉而攻擊我們!$B$B這就是我和我的姊妹們所承受的恐懼。我們向你現身就是希望你能幫助我們擊退這股蔓延進我們林地、毒害我的姊妹的腐化力量!$B$B我們一直在收集這些冰元素的核心，並妥善保管，直到某天，我們能將冰元素復原。你願意幫忙嗎?', '冰凍林地的露麗兒要你帶給他15顆冰結之核。', '', '去找凜風峽灣的露麗兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11314 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11314, 'zhTW', '墮落的姊妹', '西南邊的那座林地，過去跟這座林地並無二致。神秘的力量和異種魔法重塑了那片大地。林地的雪融了，居住在那兒的姊妹們被這突如其來的改變而陷入瘋狂。$B$B我們以為能夠和她們接觸，但是卻被攻擊，我害怕許多的姊妹們已經無可救藥，但是我不能放棄希望。$B$B帶著我的墜飾，前往西南方的鮮亮林地，使用它試著拯救我的姊妹們。', '冰凍林地的露麗兒要你在7名冰寒水精身上使用她的墜飾。', '', '去找凜風峽灣的露麗兒。', '已釋放寒冰水靈', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11315, 'zhTW', '狂亂的藤蔓', '居住在西南方，鮮亮林地的水精們，從前照料著嬌豔的血色常春藤花壇，但是，那股使水精們瘋狂的力量，同樣也轉變了她們所最愛的常春藤。$B$B這些藤蔓如今會抓住那些粗心動物的腳，或者鞭笞靠近林地裡的生物。在我們收復這座林地之前，我們需要馴服這些藤蔓並且拔除它們。$B$B盡你所能的清除這些常春藤，它們的生長已經無法控制了。', '冰凍林地的露麗兒要你去殺死8棵血色常春藤。', '', '去找凜風峽灣的露麗兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11316 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11316, 'zhTW', '扭曲林地之子', '西邊的林地被轉化成一個可怕的地方，稱之為扭曲林地。駭人的野獸居住在樹林、石堆以及林地水池間。$B$B我不知道這些生物是從哪來的，或者是什麼可怕的力量給予他們生命，不過他們一定得被解決掉!$B$B我擔心要是他們掌控了林地，他們將會毫不留情的進行污染。去收拾掉這些殺害我們姐妹的生物。', '冰凍林地的露麗兒要你去殺掉10個刺藤蠕行者。', '', '去找凜風峽灣的露麗兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11317, 'zhTW', '淨化', '我們勇敢地進入裂木森林是因為我糾纏的夢境，夢境與我生死之交的座狼朋友，巫牙有關。他正在向外求援，而你一定要去幫他。$B$B但你無法和他溝通，或在其他座狼之中活動。我知道一個方法。$B$B首先，你需要透過冥想來淨化你的內在騷動。$B$B在霜刃峰的頂端有著一座聖壇，就在冬蹄營地的東北邊。山脈的西邊有一條小路通往山頂。$B$B在那裡冥想好淨化你自己，完成之後再回來找我。', '鋼鐵之門的賢者霧行建議你去霜刃聖壇冥想，好淨化你的內在騷動。', '', '去找凜風峽灣的賢者霧行。', '已淨化內心的紛亂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11318 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11318, 'zhTW', '現在就是山羊競速…差不多。', '所以你想瞧瞧競速山羊?希望你已經準備好面對極速挑戰了。『但是』在我讓你出發之前，你得向我證明你知道該如何操控這些良好的生物。$B$B條件如下:我會借給你一些競速韁繩還有一頭山羊。你得向我證明你會操縱這些山羊。$B$B讓山羊在疾馳、快步和慢跑的狀態下各維持8秒。假如你想知道如何駕馭這些山羊，去找我的學徒保爾·安伯斯堤爾吧。', '你有4分鐘的時間可以鞭打山羊，然後在3種不同速度下各維持8秒。', '', '去找丹莫羅的奈爾‧拉姆斯登。', '維持快步8秒', '維持慢跑8秒', '維持疾馳8秒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11319, 'zhTW', '黑魂看守者種子', '西北邊的林地如今是扭曲林地，那裡曾經是一些林地看守者的家園。他們和姐妹們一起負責林地的維護。$B$B當林地產生變化時，那些姐妹們都死了，不過有些看守者設法活了下來。現在，他們在這塊土地上種植會使健康植物枯死的有毒植物。$B$B我會給你一個冰元素的冰結之核。當你摧毀一個孢子，便以冰晶冰凍它，使它不會再生。', '冰凍林地的露麗兒要你摧毀8個孢子。', '', '去找凜風峽灣的露麗兒。', '孢子已冰凍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11320 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11320, 'zhTW', '[[NYI] Now this is Ram Racing... Almost.]', '[Quest Description]', '[Log Descritpion ]', '', '去找丹莫羅的達然‧雷酒。', '維持綠色速度6秒', '維持黃色速度6秒', '維持紅色速度6秒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11321, 'zhTW', '有人說「紀念品」嗎?', '啤酒節除了競速山羊外，還要痛快暢飲!有空的時候，拿這個兌換券去找貝爾碧·迅移。她就在啤酒節營地後方附近。如果你沒看見她，別擔心，她一定會看見你的。$B$B總之，拿這個兌換券給她以換來你的免費啤酒節酒杯。她很樂意處理各種啤酒節的交易。', '把啤酒節酒杯兌換券交給啤酒節營地的貝爾碧·迅移。', '', '去找丹莫洛的貝爾碧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11322, 'zhTW', '淨化', '最近我常做惡夢，都是關於一隻叫做巫牙的座狼。牠在向外求援，你一定得幫幫他。$B$B然而，你無法和牠說話，或是讓其他的座狼接受你。我知道方法。$B$B但首先，你需要透過冥想來淨化你的內在騷動。$B$B在霜刃峰的頂端有著一座聖壇，就在東北方。山脈的西邊有一條小路通往山頂。$B$B在那裡冥想好淨化你自己，完成之後再回來找我。', '鋼鐵之門的看守者月葉建議你去霜刃聖壇冥想，好淨化你的內在騷動。', '', '去找凜風峽灣的看守者月葉。', '已淨化內心的紛亂', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11323, 'zhTW', '披著座狼皮', '我從夢中得知巫牙在裂木森林西北邊緣，一個大雪紛飛的洞穴中。$B$B他身處巨大的危險之中!$B$B我想出了一種魔法偽裝，可以讓你在裂木森林時看起來像是一隻座狼。這種偽裝很脆弱，完全倚賴鬧鬼森林的奇異魔法在運作。這只能騙過那些座狼，讓你可以靠近巫牙。$B$B拜託，$c，找到他並且幫助他。', '賢者霧行要你到裂木森林找出巫牙並且幫助牠。如果你失去了座狼偽裝，回去找賢者霧行再要一個。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11324, 'zhTW', '座狼首領', '當你吃下了猛禽之鷹的雙眼之後，你應該就能看見賈爾沃並且撕裂他的喉嚨!$B$B$r朋友，去裂木森林的西邊找出賈爾沃並且殺掉他。事成之後，告訴霧行，我又是座狼首領了!', '巫牙要求你殺掉賈爾沃。接著將座狼偽裝交還給鋼鐵之門的賢者霧行。', '', '去找凜風峽灣的賢者霧行。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11325 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11325, 'zhTW', '披著座狼皮', '我從夢中得知巫牙在裂木森林西北邊緣，一個大雪紛飛的洞穴中。$B$B他身處巨大的危險之中!$B$B我想出了一種魔法偽裝，可以讓你在裂木森林時看起來像是一隻座狼。這種偽裝很脆弱，完全倚賴鬧鬼森林的奇異魔法在運作。這只能騙過那些座狼，讓你可以靠近巫牙。$B$B拜託，$c，找到他並且幫助他。', '看守者月葉要你到裂木森林找出巫牙並且幫助牠。如果你失去了座狼偽裝，回去找看守者月葉再要一個。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11326, 'zhTW', '座狼首領', '當你吃下了猛禽之鷹的雙眼之後，你應該就能看見賈爾沃並且撕裂他的喉嚨!$B$B$r朋友，去裂木森林的西邊找出賈爾沃並且殺掉他。事成之後，告訴月葉，我又是座狼首領了!', '巫牙要求你殺掉賈爾沃。接著將座狼偽裝交還給鋼鐵之門的看守者月葉。', '', '去找凜風峽灣的看守者月葉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11327, 'zhTW', '任務:取回包裹', '幹得好，我們需要一些瘟疫材料。$B$B我知道！$B$B在你摧毀那些大缸的時候，我剛好去偵察了一個從新阿加曼德被維酷人抓到霍葛萊的藥劑師。可憐的傢伙。$B$B$n，我敢賭任何東西，他身上一定有會些材料。你覺得你能進入霍葛萊把他的包裹拿回來嗎？', '斥候諾雷斯要去霍葛萊取回藥劑師的包裹。一旦你完成任務，回到餘燼矛塔向他報告。', '', '去找凜風峽灣的斥候諾雷斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11328, 'zhTW', '任務:被遺忘者的情報', '沒錯，所以我想你應該回去要塞，把這東西拿給派比‧錯鼻。她差不多算是個業餘鍊金師，但我們也只有她了。$B$B有一件關於派比的事情要提醒你;她酷愛喝她的酒。因此，你大概得在旅店中找到她「沉醉喝酒的氣氛裡」。$B$B我相信她知道該怎麼做的。', '斥候諾雷斯要求你將藥劑師的包裹送給鎮西要塞的派比‧錯鼻。', '', '去找凜風峽灣的派比·錯鼻。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11329 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11329, 'zhTW', '我什麼都願意嘗試!', '只要我活著的一天，我就再也不想看到另外一桶醃魚了！沒日沒夜就是把桶子裝滿，但總是有空的桶子要我裝！$B$B我好希望我沒有把所有納特‧帕格的魚餌用光。真的，就跟魔術一樣有效呢。可是，現在如果我一個小時釣到一條魚就算幸運了！$B$B我聽說北地刺鬚魚可以當很棒的魚餌，但是誰會瘋到潛進冰冷的湖底、砍掉水裡的植物一根一根的找呢？不是我就對了…但是，也許，我是說也許啦，我可以說服你去…', '威德瓦堡壘的克里斯多夫‧斯洛安要你帶5條北地刺鬚魚給他。', '', '去找凜風峽灣的克里斯多夫·斯洛安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11330 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11330, 'zhTW', '當然...有用!', '瞧，即刻瘟疫機器！$B$B不過我見鬼的不想把這東西試在自己身上。而且我也知道你不想成為我的實驗目標！$B$B喔，我有…我有個點子！$B$B我們抓到了一個維酷囚犯，就關在要塞底下的囚牢裡。你何不拿著這瓶我裝好了的混合物去給那個巨人喝哩…嗝？！', '鎮西要塞的派比‧錯鼻建議你把她的派比的特殊混合物給掠龍維酷囚犯服下，並且觀察服用後的結果。', '', '去找凜風峽灣的派比·錯鼻。', '已對維库人囚犯施用佩皮的調製藥劑', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11332 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11332, 'zhTW', '任務:毀掉瘟疫!', '皇家藥劑師學會企圖改進一種新的瘟疫，要讓我們融化成一團？！$B$B我絕對不能讓它發生！$B$B快去中庭和格銳爾‧礦錘談談。他會準備一隻獅鷲獸和炸彈給你。我要你把新阿加曼德的瘟疫槽全炸成碎片！', '亞當斯隊長命令你丟5顆炸彈擊中新阿加曼德的瘟疫槽。完成任務之前不要回到鎮西要塞找他。', '', '去找凜風峽灣的亞當斯隊長。', '瘟疫戰車命中次數', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11333 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11333, 'zhTW', '進入靈體世界', '探險者協會也許可以透過他們的考古發現挖掘歷史的片段，中將或許能藉由武力得知一些此時的資訊，然而真相只有精靈知道。$B$B透過適當的藥劑我可以看見靈體世界。那裡存在著北裂境的過去、現在與未來。$B$B如果你還想知道更多，我會需要我的試劑袋。它掉在匕鞘海灣底部的沉船中，就在東邊不遠。', '瓦爾加德的『智者』索拉利亞思要你去尋找試劑袋。', '', '去找凜風峽灣的『智者』索拉利亞思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11334 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11334, 'zhTW', '打中，得分！', '[PH] 射擊已標記的目標。', '[PH]瑞林要你射擊標靶，然後把標靶來福槍還給他。', '', '去找瑞林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11335 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11335, 'zhTW', '戰鬥的號角: 阿拉希盆地', '事實上，我們在多線作戰，$g小子:小姑娘;，而且我們不能把軍隊部署得太過分佈，否則我們可能會全盤皆輸！$B$B我們需要以天為單位來部署最關鍵的部隊，今天，阿拉希盆地的戰鬥最需要勇敢的士兵！$B$B帶著勝利的訊息回來吧，$n。我們不允許部落狗來威脅屬於我們的資源！', '在阿拉希盆地的戰場中獲勝，然後向任何一座首都或撒塔斯的聯盟准將回報。', '在阿拉希盆地獲勝', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11336 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11336, 'zhTW', '戰鬥的號角:奧特蘭克山谷', '事實上，我們在多線作戰，$g小子:小姑娘;，而且我們不能把軍隊部署得太過分佈，否則我們可能會全盤皆輸！$B$B我們需要以天為單位來部署最關鍵的部隊，今天，奧特蘭克山谷的戰鬥最需要勇敢的士兵們！$B$B現在就出發吧，$N，去幫助雷矛遠征軍。我們不能就這麼看著霜狼氏族逃脫他們應受的懲罰。', '在奧特蘭克山谷的戰場中獲勝，然後向任何一座首都或撒塔斯的聯盟准將回報。', '在奧特蘭克山谷獲勝', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11337 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11337, 'zhTW', '戰鬥的號角:暴風之眼', '和部落的鬥爭沒有邊界，$N。既使在外域，領土的糾紛與古老的仇恨依舊可以挑起戰爭的烽火。$B$B前往暴風之眼吧，確保聯盟將會像在艾澤拉斯一樣地獲勝。', '在暴風之眼的戰場中獲勝，然後向任何一座首都或撒塔斯的聯盟准將回報。', '風暴之眼的勝利', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11338 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11338, 'zhTW', '戰鬥的號角:戰歌峽谷', '銀翼哨兵一直以來都為了保護戰歌峽谷的森林而戰。我們保護這座森林並不是因為我們喜愛這些樹，而是因為這座森林在聯盟領土的邊界樹立了一座天然的屏障。$B$B它在今日的戰略地位上比起過去任何時候都還要重要。我們急需補充兵源，否則梣谷將變成貧瘠之地的附屬領地!', '在戰歌峽谷的戰場中獲勝，然後向任何一座首都或撒塔斯的聯盟准將回報。', '在戰歌峽谷獲勝', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11339 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11339, 'zhTW', '戰鬥的號角: 阿拉希盆地', '阿拉希盆地快要淪落在聯盟的手中了。我們一定要在這種非常時刻派出援軍，否則我們的努力將會付之一炬。$B$B一刻都別拖延，$c，前往阿拉希盆地打敗敵軍。勝利屬於部落!', '在阿拉希盆地的戰場中獲勝，然後向任何一座首都或撒塔斯的部落戰爭使者回報。', '在阿拉希盆地獲勝', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11340 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11340, 'zhTW', '戰鬥的號角:奧特蘭克山谷', '最近我們快要將雷矛入侵者趕出奧特蘭克山谷了。因此我們重新指派所有我們的援軍去支援霜狼部族。$B$B那裡一場決定性的勝利會釋出我們需要的資源，好用來擊敗其它所有戰線的聯盟雜碎。$B$B去吧，$n。聽從勇敢霜狼戰士的呼喚，贏得無上的榮耀。', '在奧特蘭克山谷的戰場中獲勝，然後向任何一座首都或撒塔斯的部落戰爭使者回報。', '在奧特蘭克山谷獲勝', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11341, 'zhTW', '戰鬥的號角:暴風之眼', '我們將會戰鬥並擊敗我們在各處發現的敵人。艾澤拉斯，外域，各地都一樣。$B$B我們不允許聯盟在暴風之眼中佔有優勢。今天就去對他們開戰...明天可能就太遲了!', '在暴風之眼的戰場中獲勝，然後向任何一座首都或撒塔斯的部落戰爭使者回報。', '風暴之眼的勝利', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11342, 'zhTW', '戰鬥的號角:戰歌峽谷', '聯盟是陰險的敵人，$n。他們藉口想保護梣谷的森林只是為了掩飾他們想侵略我們在貧瘠之地的領土。$B$B今天我們可以將敵人一勞永逸地趕出我們領土的機會來臨了。前往戰歌峽谷並且奪回屬於我們的東西!', '在戰歌峽谷的戰場中獲勝，然後向任何一座部落主城或撒塔斯的部落戰爭使者回報。', '在戰歌峽谷獲勝', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11343, 'zhTW', '依米倫的回響', '靈魂世界已經落入巫妖王的統治中。由純粹的惡夢所創造出來的可怕生物如今看管著元素的國度。我感應到這些華爾琪在守護著一個駭人的秘密。$B$B我已經太老也太虛弱了，無法承受另一趟旅行。你一定要代我前去，$n。$B$B帶著這個薰香爐到龍顱村，使用它來進入靈魂世界。找出東北方的大型房舍!無論如何，避開華爾琪，免得被永遠困在他們的世界中。', '『智者』索拉利亞思要你在處於靈魂世界時去搜查龍顱村，找到有關龍顱的秘密相關資訊。', '巨龍顱骨的秘密已揭露', '去找凜風峽灣的『智者』索拉利亞思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11344, 'zhTW', '尼弗瓦的苦痛', '我們只知道維酷人最近才出現在北裂境。那為什麼，我們卻在15,000年前的幻象中看見維酷人?如果維酷人之前就出現在北裂境，我們就早該要知道了。$B$B你必須要進入尼弗瓦，要進入那邊你需要前往東北方，穿過龍顱村，走那條穿過水壩的道路。尼弗瓦在峽灣的高崖之上。$B$B等你抵達尼弗瓦之後使用薰香爐，然後看你能找到什麼線索。', '『智者』索拉利亞思要你在靈體世界時搜索尼弗瓦，收集關於尼弗瓦秘密的情報。', '尼弗雷瓦爾的秘密已揭露', '去找凜風峽灣的『智者』索拉利亞思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11345 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11345, 'zhTW', '打靶獎勵', '[PH] 射擊已標記的目標。', '[PH]瑞林要你射擊標靶，然後把標靶來福槍還給他。', '', '去找瑞林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11346 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11346, 'zhTW', '符文之書', '巨人小徑，位於東南邊廣大的岩石區，裡頭到處都是鐵矮人。斥候回報中提到他們看到矮人哄騙地面上的石巨人，然後在他們身上雕刻符文。$B$B我無法推論他們的動機，不過我懷疑他們想要將這些巨人轉化成武器。這些鐵符文喚石者和束縛者隨身帶了大量的書本，當中一定包括了他們雕刻在巨人身上的符文。$B$B去取得這些書本的書頁，$n，收集它們，然後帶回來給我。', '威德瓦堡壘的勘察員貝爾瓦要你將符文之書帶去給他。', '', '去找凜風峽灣的勘察員貝爾瓦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11347 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11347, 'zhTW', '清理某些房間', '我們有著堆積如山的包裹要送到卡拉諾斯的旅店去。這些包裹得儘快送到，所以我讓你借用我的競速山羊。就算你只送1個包裹我也會很感激。但你只有5分鐘，能送多少送多少吧，我會依數量獎勵你的。', '把包裹送到卡拉諾斯，最少一次。送得越多次獎勵越好。', '', '去找。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11348 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11348, 'zhTW', '指揮符文', '你可以感受到我刻在石板上符文所散發出來的力量嗎？這些是鐵矮人所使用符文的縮小版。我們可以使用這些來停止它們的運作。$B$B帶著這個去巨人小徑，然後對一個尚未受到鐵矮人轉化的石巨人使用。$B$B巨人應該會服從你，但我將符文設計為一段時間之後就會恢復呈原本的狀態。巨人應該能在你對抗束縛者穆迪斯時成為有力的盟友，穆迪斯是巨人小徑的鐵矮人部隊領袖。', '威德瓦堡壘的勘察員貝爾瓦要你測試指揮符文，並且擊敗束縛者穆迪斯。', '', '去找凜風峽灣的勘察員貝爾瓦。', '測試指揮符文', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11349 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11349, 'zhTW', '掌控符文', '我這倒是有鋤頭、鐵錘和鑿子什麼的，可惜它們不能雕刻符文。鐵矮人使用的雕琢工具就不一樣啦，他們在鑄造工具時向裡面灌注了魔法力量。$B$B使用這樣的工具進行雕刻，符文就不僅僅是簡單的字元了，它們具備了束縛、支配與扭曲的力量。$B$B這些我都瞭然於心，眼下就缺少雕琢工具進行實踐了。轉至巨人平原的鐵矮人營帳附近尋找工具箱，把它們帶回來給我。', '將一套鐵符文雕刻工具交給維德瓦堡壘的勘測員貝瓦爾。', '', '去凜風峽灣找維德瓦堡壘的勘測員貝瓦爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11350 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11350, 'zhTW', '符文之書', '灰燼圖騰酋長派我前往巨人小徑進行一次偵察任務，那是在東南方，越過了冰凍林地的一片遼闊的岩石高原。$B$B這個區域被鐵矮人所佔領，他們重新出現在地表似乎改變了巨人。$B$B鐵符文喚石者和束縛者帶著大本的書籍，書中一定紀錄著他們刻在巨人身上的符文。$B$B找到這本書的紙頁，收集它們，然後把它帶給我。這是我們唯一了解他們計畫的方法。', '冬蹄營地的遠偵斥候潘比要你把符文之書帶給他。', '', '去找凜風峽灣的遠偵斥候潘比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11351 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11351, 'zhTW', '精通符文', '我想我大概知道鐵矮人在做什麼了。他們所使用的工具是在鑄造的時候就已經灌注了魔法。$B$B然後他們用此來雕刻符文，這些圖案不只是文字。這些符文有力量能夠束縛、強迫與扭曲。$B$B要是我能有那樣一組工具，我就可以仿製書中的符文。我曾經在巨人小徑那邊的帳篷中找到一個工具盒，不過那個盒子是空的。幫我找找看類似的盒子，從他們那邊取得一組工具。', '把鐵符文雕刻工具帶給冬蹄營地的遠偵斥候潘比。', '', '去找凜風峽灣的遠偵斥候潘比。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11352 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11352, 'zhTW', '指揮符文', '你可以感受到我刻在石板上符文所散發出來的力量？這些是鐵矮人所使用符文的縮小版。我們可以使用這些來停止它們的運作。$B$B帶著這個去巨人小徑，然後對一個尚未受到鐵矮人轉化的石巨人使用。$B$B巨人應該會服從你，但我將符文設計為一段時間之後就會恢復呈原本的狀態。巨人應該能在你對抗束縛者穆迪斯時成為有力的盟友，穆迪斯是巨人小徑的鐵矮人部隊領袖。', '冬蹄營地的遠偵斥候潘比要你測試指揮符文，並且打倒束縛者穆迪斯。', '', '去找凜風峽灣的遠偵斥候潘比。', '測試指揮符文', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11353 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11353, 'zhTW', 'FLAG: Got the work shirt[日常]', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11354 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11354, 'zhTW', '懸賞:納桑的騎乘馬鞭', '今天有位買家看上了伊利丹信使的坐騎所擁有的幾樣東西。當然，我說的是『信使』維斯路登和他的龍坐騎，納桑。$B$B假如你對我付出的賞金有興趣的話，你可以在地獄火壁壘找到他們，並且從他們身上取得騎乘馬鞭。$B$B消息指出那條馬鞭是由那隻龍所持有，據說是因為納桑不讓維斯路登使用它。', '風之貿易者札令姆要你取得納桑的騎乘馬鞭。將這樣物品帶回撒塔斯陰鬱城交給他以領取賞金。這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的商人扎雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11355 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11355, 'zhTW', '巨人的遷徙', '東邊的巨人平原起了騷動，刻有符文的石巨人開始往北邊的霜刃峰遷徙。我不知道他們的目的地是哪兒。$B$B刻在他們身上的符文散發著詭異的光芒，驅使他們前進。如果你能擊倒巨人，從他們體表剝下一些符文，符文的效力就會消散，便於我們展開研究。$B$B利用這把鋤從巨人身上剝下一些符文石板，然後把它們給我帶回來。', '維德瓦堡壘的研究員艾德蘭要你在4個符文石巨人的屍體上使用符文搜尋之鋤。', '', '去凜風峽灣找維德瓦堡壘的研究員艾德蘭。', '分析符文石巨人的屍體', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11358, 'zhTW', '誘因', '如果我們能找出什麼東西吸引巨人在西北邊出沒，我們或許能在他們達成目的之前阻止他們。$B$B雖然我能解讀不少你帶來樣本上的符文，但我所不瞭解的符文，才讓我最憂心。當我前往巨人小徑時，我注意到有一個巨大破損的石板從地面突起，就在這個區域的東北方白雪堆積處，霜刃峰的山腳附近。帶著這個樣本，比對石板上的符文，看你能不能查出些什麼。', '威德瓦堡壘的研究員艾德蘭要你去比較符文樣本與破損的石板。', '', '去找凜風峽灣的研究員艾德蘭。', '將符文與破碎石板比對', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11359, 'zhTW', '破壞麥加力斯', '束縛者穆迪斯創造出了最強大的符文巨人，麥加力斯，並且帶領他們完成任務。擊敗麥加力斯會令他們群龍無首。等到遠征軍力抵達以後，我們的士兵們便能孤立並且打敗殘存的巨人，同時把鐵矮人大師從他們的營地趕出去。$B$B在巨人小徑之北，霜刃峰的丘陵一帶找出麥加力斯，並且打敗他！', '擊敗麥加力斯，並且向威德瓦堡壘的研究員艾德蘭回報。', '', '去找凜風峽灣的研究員艾德蘭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11360 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11360, 'zhTW', '救火隊演練', '現在無頭騎士還逍遙法外，閃金鎮的英雄總是準備隨時組成救火隊。你也想要幫忙嗎?$B$B在此地以北，守衛們設立了一個區域來練習救火。去那邊然後練習把水潑向火焰。你可以在大水桶那裡把水裝滿。$B$B再見，$n。等你完成救火隊的訓練，再來找我們!', '把水桶丟向5個火源，然後跟變裝的孤兒監護員談話。', '', '去找艾爾文森林的變裝的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11361, 'zhTW', '消防演練', '蠻兵們在村子外頭設立了消防演練區。這段時間剃刀嶺的建築常常失火，你應該要伸出援手，受訓成為一個消防員！$B$B往剃刀嶺的西邊走，穿過村牆時向右轉。找到演練區，然後抓住水桶把它們扔向那些練習用的火堆。', '把水桶扔向5個火源，然後再和剃刀嶺的戴面具的孤兒監護員談談。', '', '去杜洛塔找剃刀嶺的戴面具的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11362 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11362, 'zhTW', '懸賞:凱利丹的羽飾手杖', '世人的品味真是無奇不有。舉一個我最近遇上的買家來說好了。$B$B地獄火堡壘有一個魔血獸人叫做『破壞者』凱利丹。他帶著一根非常平凡的手杖，平常人根本連看都不想看它。但是呢，這正是我的客戶想要的東西。$B$B我為什麼要拒絕這筆生意呢?$B$B假如你想要賞金的話，幫我前往血熔爐找到他跟他的手杖。', '風之貿易者札令姆要你取得凱利丹的羽飾手杖。將手杖帶回撒塔斯陰鬱城交給他以領取賞金。這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的商人扎雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11363 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11363, 'zhTW', '懸賞:刃拳的徽印', '今天有一名非常有錢的收藏家需要一樣非常特殊的物品。$B$B那就是大酋長卡加斯·刃拳隨身攜帶的一個命令徽印，他平常都用這個徽印簽署所有正式的文件。我要你幫我取得這個徽印。$B$B你可以在破碎大廳的深處找到他。毫無疑問地你一定要費力的戰勝一支訓練有素的部隊才能見到他。我相信你一定辦得到。', '風之貿易者札令姆要你取得刃拳的徽印。將徽印帶回撒塔斯陰鬱城交給他以領取賞金。這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的商人扎雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11364, 'zhTW', '懸賞:破碎之手百夫長', '你敢質疑你的主人嗎?瑪頓恩也不敢。$B$B我要見到的是破碎之手氏族的百夫長身上所流的鮮血。你可以在地獄火堡壘的破碎大廳找到他們。$B$B假如你想要這筆賞金的話，你就要待在那裡直到殺光他們為止。', '虛空行者瑪頓恩要你殺死4名破碎之手百夫長。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空獵手瑪哈杜恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11365, 'zhTW', '巨人的行進', '東邊的巨人小徑，刻著符文的石巨人開始往北方遷移，靠近霜刃峰。他們的最後目的地是哪裡，我並不知道。$B$B石巨人身上刻著的發光符文引導著他們的旅程。打倒一些巨人。$B$B對巨人的屍體使用這個十字鎬，這樣可以敲下那些符文。等你收集了足夠多的樣本，就帶著你的發現回來。', '冬蹄營地的賢者伊丹要你對4個符文石巨人的屍體使用符文追尋之鎬。', '', '去找凜風峽灣的賢者伊丹。', '符文石巨人屍體已分析', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11366, 'zhTW', '誘因', '我們一定要找出什麼東西吸引巨人往西北方而去，這樣我們才能在他們抵達目的地前阻止他們。$B$B符文樣本給了我們一些線索，但那些未知的符文讓我有些憂慮。$B$B當我前往巨人小徑時，我注意到一個巨大破損的石板從地面突起，就在這個區域東北方的積雪之處，霜刃峰的山腳附近。帶著這個樣本，比對石板上的符文，看你能不能查出些什麼。', '冬蹄營地的賢者伊丹希望你去比較符文樣本與破損的石板。', '', '去找凜風峽灣的賢者伊丹。', '將符文與破碎石板比對', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11367, 'zhTW', '破壞麥加力斯', '束縛者穆迪斯製造了麥加力斯，做為符文巨人的核心，領導他們進行任務。打倒麥加力斯可以讓他們群龍無首。我會請灰燼圖騰酋長在我們往北邊前進時，挪出一些人手來消滅那些剩下的符文巨人。沒有了那些巨人，鐵矮人就無法對抗我們了。$B$B在巨人小徑之北，霜刃峰的丘陵一帶找出麥加力斯，並且打敗他！', '擊敗麥加力斯，並且向冬蹄營地的賢者伊丹回報。', '', '去找凜風峽灣的賢者伊丹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11368, 'zhTW', '懸賞:奎克米瑞之心', '我有個不尋常的任務。我接觸到一個來自異世界的有錢人，對於恐怖的東西特別有興趣。$B$B她尤其想要奎克米瑞之心。$B$B我聽說那個怪物有三顆心臟，不過一顆就足夠滿足我們的需求。據我所知，你可以在奴隸監獄的深水池中找到奎克米瑞。', '風之貿易者札令姆要你取得奎克米瑞之心。將這顆心帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11369, 'zhTW', '懸賞:黑色捕獵者的蛋', '贊格沼澤的那些沼澤行者中有一隻巨大的母獸。她總是被稱為黑色捕獵者，而每當母獸死去前她就會產下一顆蛋。$B$B我有個買家對這種蛋很有興趣。他提到關於什麼增加動物園收藏之類的。$B$B如果你對我提供的報酬有興趣，那就前往深幽泥沼，然後殺死黑色捕獵者並且取得她的蛋。', '風之貿易者札令姆要你取得黑色捕獵者的蛋。將蛋帶回撒塔斯陰鬱城交給他以領取賞金。這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的商人扎雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11370, 'zhTW', '懸賞:督軍的論述', '很多人都知道納迦族中的督軍卡利斯瑞是個強大的戰士，卻很少人知道他把他的知識全都記錄下來。$B$B我有位顧客得知了此事，有很高的興趣想把論述拿到手。$B$B我想拜託你去盤牙蓄湖的蒸汽洞窟把那本書拿來給我。', '風之貿易者札令姆要你取得督軍的論述。將東西帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11371, 'zhTW', '懸賞:盤牙侍從', '瑪頓恩聆聽並且遵從，我現在希望你協助我。$B$B現在這是我的職責了，盤牙部族的侍從必須被毀滅。去那些陰暗潮濕的角落尋找他們，就在盤牙蓄湖的蒸汽洞窟中。$B$B我只接受他們終極的滅絕。', '虛空行者瑪頓恩要你殺死14名盤牙侍從。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11372, 'zhTW', '懸賞:伊奇斯的冠羽', '最近有個牛頭人向我接頭，她的丈夫最近獲選成為酋長。她想替他的頭飾增添一點花樣。$B$B她尤其想拿到卑鄙的鷹王伊奇斯的冠羽。$B$B你要是對我的賞金有興趣的話，可以前去奧齊頓的賽司克大廳。', '風之貿易者札令姆要你取得伊奇斯的冠羽。將東西帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11373 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11373, 'zhTW', '懸賞:薩法爾的奇妙護符', '今天我有個私人的任務要拜託你，當然酬勞與它的危險度相等。$B$B我的家族和奈薩斯王子薩法爾還有他的手下，很有點『淵源』。要是他配戴的護符落入我的手中，那就表示他已經被解決了。$B$B如果你對我提供的賞金有興趣的話，你可以前往他在奧齊頓，法力墓穴的老巢。', '風之貿易者札令姆要你取得薩法爾的奇妙護符。將東西帶回撒塔斯陰鬱城交給他以領取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11374, 'zhTW', '懸賞:主教的靈魂寶石', '在奧齊頓的奧奇奈地穴正在進行許多令人討厭的實驗，想要對死靈術做更進一步的研究。許多的儀式都和那些在那裡面受盡折磨或遭到毀滅的靈魂有關。$B$B我有個顧客想要釋放其中的一個靈魂。那個靈魂就被禁錮在主教瑪拉達爾手上的靈魂寶石中。$B$B去地穴找到他，然後盡快把寶石拿回來給我。', '風之貿易者札令姆要你取得主教的靈魂寶石。將東西帶回撒塔斯陰鬱城交給他以領取賞金。這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的商人扎雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11375, 'zhTW', '懸賞:莫爾墨的低語', '等我說完，也許你就不會接下這個任務了。$B$B我有個古怪的客人專門在研究死去的存在。謠傳說現在被稱為莫爾墨的東西摧毀了那個他原先存在的世界。教授對他的「低語」很感興趣，想知道莫爾墨是如何完成這項任務。$B$B你願意前往奧齊頓的暗影迷宮，把那個東西帶來給我嗎?', '風之貿易者札令姆要你取得莫爾墨的低語。把東西帶到撒塔斯陰鬱城交給他好換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11376 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11376, 'zhTW', '懸賞:惡毒導師', '瑪頓恩聽說沒有人比暗影迷宮中的六臂女惡魔更殘酷了。$B$B前往奧齊頓吧，那這些惡魔給揪出來，全部殺光。$B$B如果這麼簡單的任務你都無法達成，那我們彼此也沒什麼話好說了。', '虛空行者瑪頓恩要你殺死3名惡毒導師。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11377 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11377, 'zhTW', '美味的復仇', '我今晚得替一些不尋常的客人舉辦酒席。其中有一位曾經在司凱堤斯的上空飛行時，被那個怪物卡里瑞給踢下鳥來--他的腿斷得很嚴重。$B$B他們要準備一些特別的東西來慶祝他的康復宴會:卡里瑞燉肉。$B$B我可以借給你我的煮菜鍋，讓你可以幫我準備一些燉肉。食譜很簡單，不過你需要一根巨大的卡里瑞肉翅還有一些扭曲漢堡。', '陰鬱城的洛克要你用他的煮菜鍋幫他料理一些卡里瑞燉肉。做好之後回去找他。', '', '去找泰羅卡森林的巨石洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11378 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11378, 'zhTW', '懸賞:紀元狩獵者的頭顱', '我的顧客的品味從世俗到獨特，無奇不有。有些時候他們想要非常世俗的事物但伴隨他們所尋求的獨特異國物品。$B$B就像是最近的這個任務，我的客戶，恕我無法說出他的名字，想要拿紀元狩獵者的頭顱來妝點他的牆壁。$B$B$c，你願意找出方法回到過去，前往舊希爾斯布萊德，替我那喜好獵奇的贊助人拿到那顆頭顱嗎?', '風之貿易者札令姆要你取得紀元狩獵者的頭顱。帶到撒塔斯的陰鬱城交給他以換取賞金。這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的商人扎雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11379 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11379, 'zhTW', '超燙的燉肉', '我正想用我對烹飪的抱負來發明新的食譜。但是老實跟你說，這些日子以來我一直都是一個只說不做的哥布林。我已經喪失了我的冒險精神。$B$B但是你……讓我想起年輕的時候;那時的我以為可以一手拿著劍，另一手拿著煮菜鍋挑戰全世界。$B$B我要你帶著我心愛的煮菜鍋到劍刃山脈去。在鍋子裡放入已經烹飪過的小肋排和香脆巨蛇肉，然後在世界上唯一溫度夠高的冥淵火屍體上烤出它特殊的風味。', '陰鬱城的洛克要你用他的煮菜鍋烹製一些驚奇惡魔燉煮，需要兩份摩克納薩爾小肋排，還有一份的香脆巨蛇肉。完成時回去找他。', '', '去找泰羅卡森林的巨石洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11380, 'zhTW', '美味法力', '你大概不知道，我以為我的食品種類已經是最新奇的了，但還是有人跑來想找更不尋常的:法力莓果特餐。$B$B糟糕的是，法力莓果只長在虛空風暴的秘境中。更別說那些伊斯利人也很喜歡那些莓果，所以風暴之尖那一帶早就被採個精光了。$B$B我只相信那些受過最好烹飪訓練的人才能採到最好的莓果，別讓我失望!', '陰鬱城的洛克要你去虛空風暴的秘境收集15個法力莓果。', '', '去找泰羅卡森林的巨石洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11381, 'zhTW', '靈魂之湯', '空氣中飄著死亡的味道。我從來沒有接過這麼多訂單來訂購我著名的湯品 -- 它可以抒解你的心靈，撫慰你的靈魂。$B$B我可是慧眼識廚師呢!你要不要來幫我一些忙，我可以給你一些酬勞?$B$B拿著我的煮菜鍋，去收集一些裂蹄肉，我就和你分享我的小秘密。你知道為什麼我的湯對靈魂有益?不是因為雞肉─我在納葛蘭的先祖之地烹調，吸收當地的靈氣。', '陰鬱城的洛克要你用他的煮菜鍋煮一些心靈雞湯。完成之後回去找他。', '', '去找泰羅卡森林的巨石洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11382 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11382, 'zhTW', '懸賞:艾奧那斯的沙漏', '我發誓我有些顧客真的瘋了。有些執著你還值得去追求，有些你根本不應該想到這種事!$B$B我最近的這個客人已經超過瘋狂的極限了。他想要艾奧那斯的沙漏。$B$B對，你沒聽錯，恆龍軍團的艾奧那斯!$B$B但拿出了一個國王才付得出的賞金，我又能向誰抱怨?那，你準備好前往時光之穴，回到黑色沼澤替我拿到沙漏嗎?', '風之貿易者札令姆要你取得艾奧那斯的沙漏。帶到撒塔斯的陰鬱城交給他以換取賞金。這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的商人扎雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11383 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11383, 'zhTW', '懸賞:裂縫領主', '瑪頓恩知道你得去哪裡。瑪頓恩知道你得殺死裂縫領主。但瑪頓恩不確定在什麼時候。$B$B我知道這樣不合邏輯，但風中的聲音卻沒有說得更明確。$B$B通過時光之穴前往黑色沼澤，到了那裡事情也許就會更清楚。', '虛空行者瑪頓恩要你殺死4名裂縫領主。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空獵手瑪哈杜恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11384, 'zhTW', '懸賞:扭曲分裂者的剪枝', '不久之前，一個卡多雷的女德魯伊交給我一項任務。當然，還有不少的金幣!$B$B顯然達納蘇斯方面希望能夠讓一個名為扭曲分裂者的秘法古樹復原。那棵巨樹現在陷入了恍惚或是腐化中，我不是很確定，但你可以在風暴要塞的波塔尼卡深處找到它。$B$B她說他們只需要一小段剪枝來讓它重新生長。', '風之貿易者札令姆要你取得扭曲分裂者的剪枝。帶到撒塔斯的陰鬱城交給他以換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11385, 'zhTW', '懸賞:尋日導魔師', '風又再對瑪頓恩低語，隸屬於尋日者的導魔師今天就得被殺死。$B$B你可以在風暴要塞的波塔尼卡中找到他們。$B$B你想要賞金的話，就殺死那些導魔師。', '虛空行者瑪頓恩要你殺死6名尋日導魔師。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11386 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11386, 'zhTW', '懸賞:帕薩里歐的投映器', '我一直以為操縱者帕薩里歐使用魔法將他的影像在外域各處投射。很顯然我錯了。$B$B我最近的一個客人告訴我，血精靈使用一種特殊的機械裝置來和凱爾薩斯王子的投影溝通。就我所知，他們是從虛空風暴的薩希斯反叛者那邊取得的。$B$B我的客戶想要那個投映器。你何不去拜訪一下帕薩里歐?他就在風暴要塞的麥克納爾。', '風之貿易者札令姆要你取得帕薩里歐的投映器。帶到撒塔斯的陰鬱城交給他以換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11387, 'zhTW', '懸賞:風暴要塞-熔爐毀滅者', '有些機械構裝生物在麥克納爾之中，瑪頓恩被告知它們必須被毀掉。$B$B前往風暴要塞，把那些風暴要塞-熔爐毀滅者給毀掉。$B$B然後你可以回來領取你的賞金。', '虛空行者瑪頓恩要你殺死5名風暴要塞-熔爐毀滅者。完成之後回到撒塔斯陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11388, 'zhTW', '懸賞:史蓋力司卷軸', '今天的客人想找樣真的很罕見的東西。$B$B傳說先驅者史蓋力司是上古諸神的僕人。還說他有著一個巨大的卷軸記載著他們要如何支配宇宙生命的指示。$B$B目前的這位買家希望$g他:她;能親自摸摸那個卷軸，當然$g他:她;是讀不了上頭的文字的。$B$B到風暴要塞的亞克崔茲，把東西拿來給我，好嗎，$c?', '風之貿易者札令姆要你取得史蓋力司卷軸。帶到撒塔斯的陰鬱城交給他以換取賞金。$B$B這個任務只能在英雄難度下完成。', '', '去找泰羅卡森林的風之貿易者札令姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11389, 'zhTW', '懸賞:亞克崔茲哨兵', '亞克崔茲的哨兵們陷入瘋狂了。裡面的囚犯們行為全都失控了而其他的守衛會攻擊想幫忙的人。$B$B瑪頓恩聽見了虛空之風中的細語。它說消滅那些哨兵們。$B$B完成這項任務的話，今天的賞金就屬於你的了。', '虛空行者瑪頓恩要你解決5個亞克崔茲哨兵。完成之後回到撒塔斯的陰鬱城找他領取賞金。', '', '去找泰羅卡森林的虛空行者瑪頓恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11390, 'zhTW', '我有飛行器了!', '哎呀，你在等什麼，還有工作等著完成呢!$B$B這是我們飛行器的鑰匙。去抓三袋聖物，並運回鋼鐵之門北側和南側的起吊平臺。我會替你標示出平臺位置。$B$B手腳快點!我們時間不多了!', '鋼鐵之門首席考古學家要你去挖掘地點的底部運回3袋聖物，並將東西帶到鋼鐵之門北側或南側的平臺。使用飛行器上的繩鉤來進行此任務。完成後回去找鋼鐵之門首席考古學家。', '', '去找凜風峽灣的鋼鐵之門首席考古學家。', '遺物袋已送達', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11391, 'zhTW', '巡邏鋼鐵之門', '啊？你回來詢問另一個工作？$B$B嗯，好吧，鑰匙在這。我們今天不需要拖運，所以只要留心有沒有任何可疑的地方就好了，行嗎？$B$B我已經在她身上裝備了火箭和機關槍 - 只是以防不備之需。', '你現在是鋼鐵之門的一流駕駛，所以鋼鐵之門首席考古學家要你去巡邏挖掘地點，並擊退任何想要進行攻擊的生物。待你完成你的巡邏後，回報給他。', '', '去找凜風峽灣的鋼鐵之門首席考古學家。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11392 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11392, 'zhTW', '召喚無頭騎士', '許多悲傷蠟燭裝飾著這座南瓜祭壇。', '將一根悲傷蠟燭插入翻過的泥土。', '', '去找血色修道院的翻過的泥土。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11394, 'zhTW', '比魚人更惡臭……', '有傳言說切米爾海岸埋藏著珍貴的古器，於是我跟隨探險隊來這裡調查實情。我原本以為海灘是魚人的地盤，但是當我看見這一切時，簡直不敢相信自己的眼睛！$B$B<探險者伸出頭來瞧了瞧四周。>$B$B天譴軍團佔領了切米爾海岸，他們將魚人和其它生物變成了一具具的行屍走肉！$B$B$C，我們應該做點什麼。你能解決掉那些天譴軍團的成員嗎？', '探險者亞倫要你轉至切米爾海岸，在那裡殺死15名任意種類的天譴軍團成員，完成任務後向他覆命。', '', '去凜風峽灣找切米爾海岸的探險者亞倫。', '殺死切米爾海岸的天譴軍團成員', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11395, 'zhTW', '這是個天譴裝置', '你剛剛摧毀的天譴生物手上抓著這個裝置。這個裝置上鑲著一顆珠寶，很像是天譴水晶頂端的那個。$B$B當然，探險家賈倫會很樂意看一看這個。', '將天譴裝置交給寒凜海岸的探險者賈倫。', '', '去找凜風峽灣的探險者賈倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11396 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11396, 'zhTW', '關閉護盾', '瞧，控制器側面有個按鈕。我敢打賭，如果你離天災水晶夠近的話，就可以用控制器關閉它的護盾。接下來嘛，在護盾恢復之前摧毀水晶就行啦。$B$B$N，怎麼樣？你願意接受這項任務嗎？只要你順利地關閉護盾並摧毀水晶，就能得到一份很棒的獎勵。$B$B天譴軍團瘋狂地將其它生物轉換成他們的同類，這是我們唯一能阻止他們的方法。', '切米爾海岸的探險者亞倫要你摧毀3顆天災水晶。', '', '去凜風峽灣找切米爾海岸的探險者亞倫。', '摧毀天災水晶', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11397, 'zhTW', '你還以為魚人已經夠臭了!', '我最近到這裡是為了調查一些關於天譴軍的謠言。我以為這一帶的海岸只有魚人，可是我完全沒想到會看到這種場面!$B$B天譴軍團就在那邊，他們在改變那些魚人，還把任何他們派得上用場的東西全變成不死生物!$B$B$c，我們不能任由他們繼續製造更多同類，尤其是不能對魚人下手!在營地的西北邊有斜坡可以到海邊。在還沒有太遲之前對付那些天譴軍!', '藥劑師安娜塔西亞要你殺死寒凜海岸上任何種類的天譴軍共15名。一旦你完成去凜風峽灣的藥劑師營地向她回報。', '', '去找凜風峽灣的藥劑師安娜塔西亞。', '寒湖海岸的天災已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11398, 'zhTW', '這是個天譴裝置', '你剛剛摧毀的天譴生物手上抓著這個裝置。這個裝置上鑲著一顆珠寶，很像是天譴水晶頂端的那個。$B$B當然，藥劑師安娜塔西亞會很樂意看一看這個。', '將天譴裝置交給藥劑師營地的藥劑師安娜塔西亞。', '', '去找凜風峽灣的藥劑師安娜塔西亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11399 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11399, 'zhTW', '關閉那些護盾', '注意看控制器的底部這邊。我猜你如果靠那些天譴水晶夠近，你應該可以使用控制器關閉他們的護盾。如果他們的護盾失去作用，那應該可以輕而易舉地摧毀這些東西。$B$B你有足夠的勇氣進行這件事嗎，$n？如果你能關閉那些護盾並且摧毀水晶，我可以保證會有可觀的報酬。$B$B你應該不會拒絕減少天譴軍的數量吧，尤其用魚人做成的那些？', '藥劑師營地的藥劑師安娜塔西亞要你摧毀3個天譴水晶。', '', '去找凜風峽灣的藥劑師安娜塔西亞。', '鞭笞水晶已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11400 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11400, 'zhTW', '啤酒節騎乘用山羊', '如果你把這個手印亮給保爾·安伯斯堤爾看，那個山羊競速學徒就會讓你借用啤酒節騎乘用山羊。', '將「榮譽釀酒者」手印交給保爾·安伯斯堤爾，他就在丹莫洛的啤酒營地入口附近。', '', '去找丹莫洛的波爾·凍石。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11401 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11401, 'zhTW', '召喚無頭騎士', '許多悲傷蠟燭裝飾著這座南瓜祭壇，搖曳的火光似乎是在竊笑與嘲諷著你……', '將一根悲傷蠟燭插入翻過的泥土。', '', '去找血色修道院的翻過的泥土。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11402 AND `locale` = 'zhTW';
DELETE FROM `quest_template_locale` WHERE `ID` = 11403 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11403, 'zhTW', '終獲自由!', '憤怒是我的囚牢，$n，而你釋放了我。儘管我自詡正義，但我帶給艾澤拉斯良善百姓的死亡與恐懼，讓我的靈魂悔恨垂淚。$B$B感謝你領我重回聖光。希望我永遠也不會再次迷失。$B$B帶著這本破碎的祈禱書給孤兒監護員，那些孩子將會知道我再也不會去騷擾他們了。', '帶著湯瑪斯‧托姆森的聖典交給戴面具的孤兒監護員，她在杜洛塔、布瑞爾和獵鷹之翼廣場。', '', '去找戴面具的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11404 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11404, 'zhTW', '召喚無頭騎士', '許多悲傷蠟燭裝飾著這座南瓜祭壇，搖曳的火光似乎是在竊笑與嘲諷著你……', '將一根悲傷蠟燭插入翻過的泥土。', '', '去找血色修道院的翻過的泥土。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11405 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11405, 'zhTW', '召喚無頭騎士', '許多陰鬱的蠟燭點綴在南瓜祭壇旁邊，嘲諷般地笑著...', '帶著一根陰鬱蠟燭去零散翻覆的泥土那邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11407 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11407, 'zhTW', '為德羅恩的釀酒廠而吶喊!', '你想幫忙把力量與榮譽帶給啤酒節嗎?我們需要你在力量谷、榮譽谷、智慧谷和精神谷拍賣場外的旗杆下大聲叫喊。$B$B我們可以把競速山羊借給你4分鐘。$B$B不過要小心，那些小氣的哥布林可沒有在沿路上放著蘋果。', '在力量谷的拍賣場外的旗杆下，榮譽谷、智慧谷與精神谷散佈有關啤酒節的訊息。', '', '去找杜洛塔的寇特‧高斯坦。', '在拍賣行外叫賣', '在榮譽谷叫賣', '在智慧谷叫賣', '在靈魂谷叫賣', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11408 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11408, 'zhTW', '為提洽里的巫毒釀酒廠而吶喊!', '我們需要讓大家知道有關食人妖參加了啤酒節的事情。你得到力量谷的拍賣場外，還有榮譽谷、智慧谷以及精神谷的旗幟下大聲叫喊。不過我會讓事情簡單點，我會借你一頭競速山羊，為時4分鐘。$B$B不過小心點，哥布林可沒有在沿路上放蘋果，他們就是這麼小氣。', '在力量谷的拍賣場外的旗杆下，榮譽谷、智慧谷與精神谷散佈有關啤酒節的訊息。', '', '去找杜洛塔的亞隆。', '在拍賣場外叫賣', '在榮譽穀叫賣', '在智慧穀叫賣', '在精神穀大喊', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11409, 'zhTW', '現在就是山羊競速...差不多。', '所以你想瞧瞧競速山羊?那些矮人覺得自己會駕馭山羊，但說實話，他們大部分的時候都醉得一塌糊塗，你想這能有多難?$B$B在我讓你出發之前，你得向我證明你能控制這些善良又合法的動物。$B$B條件如下:我會借給你一些競速韁繩還有一頭競速山羊。你得向我證明你會操縱這些山羊。$B$B讓山羊在快步、慢跑和疾馳的狀態下各維持8秒。', '你有4分鐘的時間可以鞭打山羊，然後在3種不同速度下各維持8秒。', '', '去找杜洛塔的山羊管理員雷。', '維持快步8秒', '維持慢跑8秒', '維持疾馳8秒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11410 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11410, 'zhTW', '逃走的大魚', '你帶來的鯰魚很不錯，做成的魚餌對大多數的魚都有效果，不過……我擔心它會引來那隻水怪！$B$B剛到這裡的時，我在魚鉤上用過一些納特·帕格的魚餌，當時想也沒想就拋杆入水。結果……一隻大水怪咬住了魚鉤，並且在掙扎的時候把線纏在了它體表那嶙峋的冰柱上！$B$B那時候要不是我眼疾手快切斷了線，早就被拖進水裡吃掉了！在幹掉這隻名叫霜鱗的怪物之前，我是絕對不敢用新魚餌的。這個工作就交給你了，到湖中央沉船那邊去使用這種新魚餌，把那隻水怪誘出來幹掉。它一定會上鉤的！一定！', '維德瓦堡壘的克里斯托弗·斯洛安要你擊敗霜鱗。', '', '去凜風峽灣找維德瓦堡壘的克里斯托弗·斯洛安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11411 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11411, 'zhTW', '冬蹄營地', '我以前跑腿當信使的時候，曾在峽灣的兩岸遠遠看見過許多本地的原住民。其中有一種最為神秘，從遠距離上看，這類原住民跟牛頭人很像，但如果靠近仔細觀察的話，兩者之間又有所不同——這些原住民顯然要比普通牛頭人更強壯，體格更高大，毛髮也更粗糙一些。$B$B我在哈爾格林德和斯克恩的北邊找到了一處他們的定居點，就在那邊的森林中。那個定居點據說叫冬蹄營地，在亞勒霍恩丘陵地的腳下，也就是蒼松嶺的邊界旁。你去與他們接觸一下吧，看看他們是否能對我們有所幫助。', '與冬蹄營地的灰燼圖騰酋長談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11412 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11412, 'zhTW', '來回跑', '真高興你來了，我們有大麻煩了！酒在從刃拳海灣送過來的路上出了一點意外，現在那些酒卡在半路動彈不得。你得幫我們把那些酒帶回來！$B$B騎我的競速山羊去，只要順著路走就可以到達刃拳海灣了。$B$B你一靠近他，他就會丟給你一桶酒，然後你把酒桶帶回來，丟給我那更靠得住的助手。目前我們只需要3桶酒。這件事若辦得好，也許我們還會有其他的工作交代給你。', '從倒在通往刃拳海灣路上的哥布林手中得到酒桶，然後交給山羊管理員雷的助手。如果你的山羊不見了，找山羊管理員雷再要一頭。', '', '去找杜洛塔的山羊管理員雷。', '酒桶已運送', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11413 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11413, 'zhTW', '有人說「紀念品」嗎?', '我們不但供應民眾啤酒，同時我們還贈送酒杯!只要用正式的票卷就可以換取漂亮的紀念杯!這張兌換卷給你。$B$B跟啤酒節營地前方的布力克斯談話。他個性古怪，甚至現在他老是戴著那副護目鏡。他會幫你兌換那張兌換券，並且啤酒節的其他交易都可以找他。', '把啤酒節酒杯兌換券交給啤酒節營地的布力克斯·修械。', '', '去找杜洛塔的布利克斯·菲克維特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11414 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11414, 'zhTW', '兄弟的背叛', '我夢見過觀察者莉莎·月葉！如果你是她的朋友，那麼你也是我的朋友。$B$B直到上一次月圓之夜前，我一直都是族群裡的頭狼。後來，那頭奇怪的白狼，迦瓦爾，從北方來到了這裡。在我曾經的兄弟們的幫助下，他很快成了新的頭狼。他非常奇怪，很不正常。$B$B如果你想幫我，就先去殺掉那些背叛我的傢伙。$B$B比奧莫弗到鋼鐵之門的西北方去捕獵了，瓦爾戈則在東南方的西部長矛塔樓附近。$B$B他們能輕易識破你的偽裝。', '烏爾芬要你去殺死背叛他的座狼，比奧莫弗和瓦爾戈。完成任務後，穿著斗篷回到裂木森林向他覆命。$B$B如果你弄丟了座狼偽裝，可以去找觀察者莉莎·月葉再要一件。', '', '去凜風峽灣找裂木森林的烏爾芬。你需要使用座狼偽裝。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11415 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11415, 'zhTW', '兄弟的背叛', '霧行在我夢裡出現過!如果你是他的朋友，你就是我的朋友。$B$B直到上一次月圓之前，我一直是狼王。直到那頭詭異的白座狼，賈爾沃，從北方來到此地以後，挾著那些曾是我兄弟的狼群幫助，很快的當上了座狼首領。牠的行為令人感覺不太自然。$B$B如果你要幫忙，首先你一定要殺掉背叛我的傢伙。$B$B畢歐莫夫在一個兩腳的叫做鋼鐵之門的西北邊狩獵。另外去東南邊尋找瓦爾格，西矛哨塔附近。$B$B他們不會被你的模樣給愚弄的。', '巫牙要求你殺掉背叛他的座狼，畢歐莫夫和瓦爾格。成功以後，在偽裝的情況下向巫牙回報，他就在裂木森林裡。如果你遺失了你的座狼偽裝，向賢者霧行要一個替代品。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11416 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11416, 'zhTW', '巨鷹之眼', '迦瓦爾用一種奇怪的魔法隱藏了自己的蹤跡。除非他自己願意，沒有人能看見或聞到他。但我們也許能有辦法。$B$B我的敵人，那頭名叫塔隆斯里克的鷹，據說有一雙能看穿一切的眼睛。如果你能拿到她的眼珠，就一定能看見迦瓦爾。$B$B塔隆斯里克的巢穴在維庫人的據點斯克恩西南方的一條瀑布底下。只要你去翻動鷹巢裡的卵，她就會從天空衝下來攻擊你。$B$B把她的眼珠給我帶回來。', '烏爾芬要你去拿到巨鷹之眼。完成任務後，穿著斗篷回到裂木森林向他覆命。$B$B如果你弄丟了座狼偽裝，可以去找觀察者莉莎·月葉再要一件。', '', '去凜風峽灣找裂木森林的烏爾芬。你需要使用座狼偽裝。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11417 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11417, 'zhTW', '雌鷹之眼', '賈爾沃將他自己隱藏在一道邪惡的魔法之後。沒有人可以看到他，除非他想要讓你看到。不過，也許有個機會可能可以讓我們看到他。$B$B我的敵人，那隻大鷹，猛禽之鷹，傳說擁有可看到所有東西的雙眼。如果你去奪得她的雙眼，那麼你就一定能夠看到賈爾沃。$B$B猛禽之鷹將她的巢築在一座瀑布下，就在人稱為斯考恩的維酷領地西南方。只要你碰觸她巢裡的蛋，她就會從天而降來殺你。$B$B去取得她的眼睛。', '巫牙要你去取得雌鷹之眼。完成後穿上偽裝，回到裂木森林去找牠。如果你不知為何失去了座狼偽裝，就回去找賢者霧行再要一個。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11418, 'zhTW', '我們叫他鋼羽', '一隻勇敢的角鷹獸在堡壘上空盤旋，時不時俯衝下來捕捉獵物。傑森朝他射了好幾箭，可是都沒有命中目標！$B$B我們給這隻出色的角鷹獸取了個名字叫鋼羽，不過就是搞不懂他為什麼就喜歡在維德瓦堡壘附近出沒。大多數角鷹獸都不喜歡人類。$B$B研究員艾德蘭用角鷹獸的羽毛製作了一枚護符，據說這枚護符能讓使用者透過鋼羽的眼睛觀察世界。', '找到盤旋在維德瓦堡壘上空的鋼羽，利用飾羽符咒揭開他的秘密。然後向基爾·克利瑟報告情況。', '', '去凜風峽灣找維德瓦堡壘的基爾·克利瑟。', '發現鋼羽的秘密', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11419 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11419, 'zhTW', '啤酒節騎乘用山羊', '假如你給山羊競速學徒，德瑞茲·迅跌看這個手印的話，他就會讓你購買啤酒節騎乘用山羊。', '將『榮譽釀酒者』手印交給德瑞茲·迅跌，他就在杜洛塔的啤酒營地入口附近。', '', '去找杜洛塔的德瑞茲·迅跌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11420 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11420, 'zhTW', '償還之途', '兩週前我們的首席工程師弄來了一台維酷魚叉獵槍 - 就是他們用來把我們船隻擊沉的玩意兒。在研究那台獵槍之後，他打算做一本魚叉操作手冊。$B$B但不幸的是，他被綁架到北邊的龍顱村。我們最後終於找到了他，但重傷垂危而且手冊也不見了。他死前的遺言說手冊遺落在俄特加德墓窖中，在龍顱村的西北邊。幫我把手冊拿回來!', '守衛隊長索芮克希望你去找回魚叉操作手冊，他就在凜風峽灣的瓦爾加德。', '', '去找凜風峽灣的守衛隊長索芮克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11421, 'zhTW', '火力全開...', '我們要趁著維酷部隊混亂的時候給予他們更多打擊!帶著魚叉控制裝置前往尼弗瓦，並且鎖定最北邊的魚叉砲塔，就在村子的懸崖邊。$B$B到了那邊之後，指揮一個蓋在建築平臺上的維酷魚叉獵槍。用魚叉獵槍對龍顱村降下一場災難!摧毀長屋、船塢、貯藏設施以及任何維酷人派來阻擋你的防禦者!$B$B如此一來，匕鞘海灣將會成為一個更安全的港口!', '凜風峽灣的冰錘中尉希望你摧毀掠龍長屋、掠龍船塢、掠龍貯藏設施和8個掠龍防衛者。等到任務完成，將魚叉控制裝置還給他。', '', '去找凜風峽灣的冰錘中尉。', '', '屠龍者長屋已摧毀', '屠龍者碼頭小屋已摧毀', '屠龍者儲藏設施已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11422, 'zhTW', '兒子的三叉戟', '<從他在石頭上製造出的抓痕看來，你辨認出幾個符號:一個三叉戟，一個屍化魚人，太陽，一條沈船，還有一個代表你的粗略形狀。>$B$B<苦思這個魚人想要傳達的意思。顯然他要你去寒凜海岸取得一隻三叉戟，不過太陽圖樣很難懂。直到你了解他指得是他的兒子。>$B$B<他的兒子被轉變為屍化魚人了!他要你去沉船的附近找到他的兒子，並將他的三叉戟帶回來。>', '老冰鰭要你去取得腐鰓的三叉戟。將東西帶回他那位於寒凜海岸的小島上給他。', '', '去找凜風峽灣的老冰鰭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11423, 'zhTW', '敵人的遺產', '隨著我們的部隊向北裂境進軍，我們的敵人將不單單被擊敗。他們的房舍將被燒毀，他們的屍體將被我們的瘟疫所吞噬，所有他們存在過的痕跡都會被抹去。$B$B但身為一個知識的追尋者，我很擔心。東方的城鎮尼弗瓦很快將會被我們復仇臺地的部隊所夷平。曾在此生活的維酷詩人海古斯曾經寫過三首英雄史詩:雙子的英雄史詩、寒冬詛咒的英雄史詩和華爾琪英雄史詩。在尼弗瓦被摧毀之前取得它們。', '前往鬼刃崗哨北邊的尼弗瓦，尋找寒冬詛咒的英雄史詩、華爾琪英雄史詩和雙子的英雄史詩。', '', '去找凜風峽灣的抄寫員賽昆恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11424, 'zhTW', '盾丘', '我的工作在戰爭時應該是非常簡單的事。到處都有可利用的屍塊。$B$B然而，事情沒那麼簡單。這些知識分子製造了所有類型的殺人瘟疫，並且把它們送往敵鎮，然後污染了大部分的資源。$B$B不過，還有一個地方，那裡還有可利用的樣本。南邊的盾丘，是一處古老的維酷埋葬地，裡頭的活屍尚未受到任何的瘟疫感染 - 不管是被我們還是被巫妖王污染。去幫我取得一些骨頭，我會好好答謝你的。', '『鋼鋸』潔妮需要你帶給她5個上古維酷骸骨，可以在新阿加曼德的南方的盾丘中，從再活化的維酷族身上找到。', '', '去找凜風峽灣的『鋼鋸』潔妮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11425 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11425, 'zhTW', 'Test Quest - Craig', '去執行一項任務吧！', '害蟲，開始憎恨他們。', '', 'Return to Test Squirrel.', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11426 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11426, 'zhTW', '找出裝置', '別擔心，$n;我們將會循線得到十分重要!十分驚人的結果!你只需要相信我，然後照我的話去做。$B$B為了計畫的第二步，我們需要拿到手冊上提到的裝置。我確信那些龍顱村負責操作魚叉獵槍的維酷人身上可能會有那個東西。你可以在村子東邊找到他們，就在長屋的碼頭那邊。', '守衛隊長索芮克要你把魚叉控制裝置帶來給他，他就在凜風峽灣的瓦爾加德。', '', '去找凜風峽灣的守衛隊長索芮克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11427, 'zhTW', '會見冰錘中尉...', '你看到那些位於東北峭壁的維酷建築嗎?維酷叫那個地方為尼弗瓦。用來攻擊我們護衛艦的魚叉，大部分都是來自那裡。$B$B嘿，你知道嗎?該是以牙還牙的時候了，$n。我要你帶著這個魚叉控制裝置去見冰錘中尉，他就躲藏在尼弗瓦西北邊的一棟維酷建築中。$B$B等你準備好，我會讓你坐上一隻獅鷲獸，迅速前往冰錘所在的地點!', '守衛隊長索芮克要你去將魚叉控制裝置交給駐守在尼弗瓦外的冰錘中尉。', '', '去找凜風峽灣的冰錘中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11428, 'zhTW', '守護者凋葉', '你一直都是我們最好的朋友和盟友，$n。還有一件事我一定得請你幫忙。$B$B你已經看過扭曲林地和住在那裡的野獸腐化的情況。這些黑心的守護者將會一直從林地的水及土中繁衍出這些憎惡體，除非我們起身反抗。$B$B這些黑心守護者中最強大的那位叫做守護者凋葉。去殺了他，$n，並開啟恢復林地的方法，就像你曾經挽救了我的姐妹一樣。', '冰凍林地的露麗兒要你去殺了守護者凋葉。', '', '去找凜風峽灣的露麗兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11429, 'zhTW', '放下，揮舞!', '我不打算將此任務交給某些未經考驗的廢物手中。$B$B現在，如果你想要對我證明你已經擁有完成此任務的能力，你得去完成以下我所說的事情。$B$B帶著這面戰鬥軍旗，接著前往北邊的貝爾海姆。一抵達貝爾海姆，就去找城鎮的中心，並將旗子放下。擊退所有想要弄倒我們珍貴旗幟的維酷混蛋，一旦你建立了聯盟的威勢後，就回來找我!', '凜風峽灣的冰錘中尉要你將聯盟旌旗放置在貝爾海姆，然後保護旌旗免於攻擊者攻擊。萬一你沒死，就將聯盟旌旗帶回去給冰錘中尉。', '已防禦聯盟旗幟', '去找凜風峽灣的冰錘中尉。', '聯盟旗幟已放置', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11430 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11430, 'zhTW', '魚叉大師亞瓦思', '你在貝爾海姆的表現頗為優秀，$n。在你出發前，稍做休息一下，在尼弗瓦那還有工作得完成。$B$B我們已經找到負責用魚叉攻擊我們護衛艦的維酷了 - 名為亞瓦思。你可以在東南邊的尼弗瓦懸崖上，那棟主魚叉建築中找到他。$B$B找到他，為了他對聯盟所犯下的罪行處死他!$B$B讓我感到驕傲，$n!', '凜風峽灣的冰錘中尉要你去殺了尼弗瓦的魚叉大師亞瓦思。', '', '去找凜風峽灣的冰錘中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11431, 'zhTW', '抓住野生鹿角兔!', '你好啊!我是個瘋矮人!我們矮人相信只要你喝夠多啤酒，隱形的生物就會出現。事實上它們可能現在就在啤酒營地附近閒晃!但除非你喝醉不然你是看不見它們的。$B$B我們矮人想得出任何可以喝得爛醉的理由。$B$B我打賭你也想要一個喝酒的理由...所以幫我帶五隻鹿角兔回來，就用這個我從一個爛醉如泥的矮人身上弄來的網子。$B$B要是你看不見它們，那就表示你還不夠醉。', '『矮鬼』葛羅卓克·獵狙者要你用鹿角兔補網幫他抓5隻昏迷的鹿角兔。他提到你必須在喝醉的情況下才看得到那些鹿角兔。', '', '去找杜洛塔的葛羅卓克‧獵狙者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11432 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11432, 'zhTW', '沉睡的巨人', '我無意間聽到你和雷瓦瑞爾神父的談話。請容我指出他讓你做的還不夠多。$B$B你必須要處理那些在夏勒布隆底下的喚醒之廳中沉睡的維酷人!$B$B我毫不懷疑那些喚醒他們的儀式是他們沒落的原因。我猜想那些死靈領主應該會有些裝置你可以讓那些維酷人提早脫離沉睡的狀態。$B$B而這樣的分離對那些維酷人而言將會十分致命。', '法師中尉瑪歷斯特要你殺死5個冬眠的維酷人。等你完成之後回到鎮西要塞向他回報。', '', '去找凜風峽灣的法師中尉瑪歷斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11433 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11433, 'zhTW', '沉睡的巨人', '我無意間聽到你和主母安卡的談話。無意冒犯，但她讓你做的還不夠多。$B$B你必須要處理那些在夏勒布隆底下的喚醒之廳中沉睡的維酷人!$B$B我毫不懷疑那些喚醒他們的儀式是他們沒落的原因。我猜想那些死靈領主應該會有些裝置你可以讓那些維酷人提早脫離沉睡的狀態。$B$B而這樣的分離對那些維酷人而言將會十分致命。', '阿喉塔‧白霜要你殺死5個冬眠的維酷人。等你完成之後回到冬蹄營地向他回報。', '', '去找凜風峽灣的阿喉塔‧白霜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11434 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11434, 'zhTW', '被遺忘的寶藏', '我透過專精那些海賊不在意的財寶而致富，像是藝術品、古董或是收藏家的寶貝。$B$B許多年前黑色康拉德的艦隊在南方沉沒。所有的黃金和珠寶都被潛水伕撈走了，但兩件古老的聖物還在藏在海底。一件是博物館級的阿曼尼花瓶，另一個則是雄鷹雕像。$B$B幫我把這兩個東西拿回來，我可以拿別的海賊寶藏回報你。我還可以給你一點東西讓你的水底冒險容易一些。', '無賴角的帥哥泰瑞要你從南方的沉船中帶給他1個阿曼尼飾瓶和1個雄鷹刻像。', '', '去找凜風峽灣的帥哥泰瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11435 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11435, 'zhTW', '收集南瓜燈', '你好，$n！謝謝你趕走了無頭騎士！他跑掉以後，我們就可以自由自在地在村裡玩啦！$B$B哦哦，對啦對啦，我還找到幾個無頭騎士丟在這裡的南瓜，真可怕……你能把它們帶給院長嗎？', '將一堆南瓜燈交給穿戲服的孤兒院長。', '', '去找變裝的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11436 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11436, 'zhTW', '衝浪時刻', '掌舵渡過凜風峽灣的峭壁真的叫人神經衰弱!我利用維酷族技術和矮人的精巧裝置找出了一種解決方法。只需要小小的修改和良好的調整，我發明了冰錘的魚叉控制器!當然它還沒有測試過，但這不就是你的存在價值嘛!$B$B帶著這個控制器去尼弗瓦的大槍那邊，用這個把你自己射進瓦爾加德。向索芮克回報你的勝利吧。噢，對了，你可以保留那個控制器。', '使用尼弗瓦的大型維酷魚叉獵槍把你自己射進瓦爾加德。向守衛隊長索芮克回報你對維酷人的勝利。', '進行魚叉衝浪', '去找凜風峽灣的守衛隊長索芮克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11437 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11437, 'zhTW', '[PH] 啤酒花園 A', '[PH] 到達納蘇斯、艾克索達、沙塔斯城或暴風城以外的任何啤酒花園，找啤酒節叫賣員談話，即可獲得一份免費椒鹽卷餅。', '[PH] 到任何啤酒花園找啤酒節叫賣員談話，即可獲得一份免費椒鹽卷餅。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11438 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11438, 'zhTW', '[PH] Beer Garden B', '[PH] 到達納蘇斯、艾克索達、沙塔斯城或暴風城以外的任何啤酒花園，找啤酒節叫賣員談話，即可獲得一份免費椒鹽卷餅。', '[PH] 到任何啤酒花園找啤酒節叫賣員談話，即可獲得一份免費椒鹽卷餅。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11439 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11439, 'zhTW', '救火隊演練', '卡拉諾斯的勇敢矮人可以立刻組成一支救火隊，現在無頭騎士還逍遙法外。你想要幫忙嗎?$B$B南邊那裡，巡山人設立了一個區域來練習救火。去那邊然後練習把水潑向火焰。你可以在大水桶那裡把水裝滿。$B$B再見，$n。等你完成救火隊的訓練，再來找我們!', '把水桶丟向5個火源，然後跟變裝的孤兒監護員談話。', '', '去找丹莫羅的變裝的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11440 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11440, 'zhTW', '救火隊演練', '現在無頭騎士還逍遙法外，保安官們總是辛勤地準備隨時組成救火隊。你也想要幫忙嗎?$B$B在此地的西邊往艾克索達的方向，保安官們設立了一個區域來練習救火。去那邊然後練習把水潑向火焰。你可以在大水桶那裡把水裝滿。$B$B再見，$n。等你完成救火隊的訓練，再來找我們!', '把水桶丟向5個火源，然後跟變裝的孤兒監護員談話。', '', '去找蔚藍海岸島的變裝的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11441, 'zhTW', '啤酒節!', '前往在鐵爐堡外的啤酒節營地，找啤酒節管理人談談並取得一杯免費啤酒。', '和啤酒節管理人交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11442, 'zhTW', '歡迎來到啤酒節!', '在鐵爐堡外的美酒節會場找到美酒節組織者，領取免費的啤酒。', '與美酒節組織者交談，以領取免費的啤酒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11443, 'zhTW', '匕鞘灣潛水', '嗨...嗯...有事嗎?你在這裡這裡做什麼?$B$B我?...喔...呃，你知道...我在...嗯...我在整理這個地方!是凱勒親自下的命令!他跟我說，「哈利，我要你穿上潛水裝，去搜尋匕鞘海灣沉船中『我們』的東西...」$B$B話說，也許你可以幫我個忙，在這個海灣中有各式各樣的好東西，呃，我是說補給品。去那邊幫我把所有你找到的東西帶來。你可以用這個潛水頭盔，免得你缺氧而死。', '匕鞘海灣底部的哈洛德‧拉格銳思要你收集10個沃爾加德補給木箱。', '', '去找凜風峽灣的哈洛德‧拉格銳思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11444 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11444, 'zhTW', '[PH]啤酒廣場A', '[PH]找一個啤酒節宣傳員交談，他會在達納蘇斯、艾克索達、撒塔斯城或暴風城外的啤酒廣場。取得一個免費的鹹脆餅。', '[PH]在任何一個啤酒廣場和啤酒節宣傳員交談，並取得免費的鹹脆餅。', '', '', '', '', '', '', 0);
