INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11447, 'zhTW', '歡迎來到啤酒節!', '[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.', '[PH] Speak to the Brewfest Organizer and receive a free beer.', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11448 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11448, 'zhTW', '探險者協會前哨', '這根本就是一連串的密碼胡扯!就算有這份密碼我也沒有辦法搞清楚那些石板內容是頭還是尾。大家都知道，密碼學不是我的強項。$B$B你要把密碼和石板帶給我們的密碼學家，史坦華。不幸的是，我已經兩週沒有聽到史坦華的消息了。他帶了二十個科學家前往峽灣東南部的挖掘現場之後，我就再也沒聽過他的消息。我能做的就是請那邊的馬概先用他的飛行器載你一程。', '到凜風峽灣的探險者協會前哨，將麥克索夫的包裹交給史坦華。', '', '去找凜風峽灣的史坦華。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11449 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11449, 'zhTW', '消防演練', '亡靈哨兵在城鎮外頭設立了消防演練區。我們不能讓布瑞爾的建築物再受到傷害了 - 你應該要盡你的本分，受訓成為一個消防員。$B$B順著路朝西邊經過墓園。你就會看到演練區了。', '把水桶扔向5個火源，然後再和布瑞爾的戴面具的孤兒監護員談談。', '', '去找提裏斯法林地的戴面具的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11450 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11450, 'zhTW', '消防演練', '衛兵們在城鎮外頭設立了消防演練區。我們不能讓無頭騎士破壞辛苦重建的城鎮--你應該要盡你的本分，受訓成為一個消防員。$B$B朝南方穿越大門到十字路口交界處。你就會看到演練區了。', '把水桶扔向5個火源，然後再和獵鷹之翼廣場的戴面具的孤兒監護員談談。', '', '去找永歌森林的戴面具的孤兒監護員。', '撲滅火勢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11451 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11451, 'zhTW', '艾利西亞之詩', '嗨，我替我的朋友凱莉寫了一首詩。她喜歡和撒塔斯城的奧多爾混在一起。你知道?就在外域。$B$B你可以把我的詩帶給她嗎?我媽咪說我還太小不能去撒塔斯城!', '你被要求把艾利西亞之詩帶給外域撒塔斯城的凱莉·達克。', '', '去找撒塔斯城的凱莉·達克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11452 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11452, 'zhTW', '沉睡的國王', '從霸主手中掉落的一束羊皮紙中，你可以分辨出上面寫著在墓窖下舉行的儀式。$B$B然而，上頭顯示維酷之后，安格博妲在喚醒依米倫王上遇到了困難。這個儀式在被稱為冬之殿堂的巨大房間中舉行，就在夏勒布隆的北方盡頭。$B$B如果你動作夠快，你或許還來得及阻止她。', '擊敗安格博妲王后並且阻止喚醒依米倫王的儀式。如果你成功的話，回到鎮西要塞向亞當斯隊長回報。', '', '去找凜風峽灣的亞當斯隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11453 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11453, 'zhTW', '沉睡的國王', '從霸主手中掉落的一束羊皮紙中，你可以分辨出上面寫著在墓窖下舉行的儀式。$B$B然而，上頭顯示維酷之后，安格博妲在喚醒依米倫王上遇到了困難。這個儀式在被稱為冬之殿堂的巨大房間中舉行，就在夏勒布隆的北方盡頭。$B$B如果你動作夠快，你或許還來得及阻止她。', '擊敗安格博妲王后並且阻止喚醒依米倫王的儀式。如果你成功的話，回到冬蹄營地向灰燼圖騰酋長回報。', '', '去找凜風峽灣的灰燼圖騰酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11454 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11454, 'zhTW', '尋找破壞者', '這一堆破爛的廢紙像是被那些黑鐵入侵者所意外留下來的。$B$B那些計畫很複雜，而且是用一種矮人語密碼所寫成，末尾的簽名『寇仁‧恐酒』倒是很清楚，還提到提到黑石深淵的黑鐵酒吧。你應該要找到這個教唆者，終止這些掠奪。', '在黑石深淵的黑鐵酒吧中找到寇仁‧恐酒。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11455 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11455, 'zhTW', '錢的氣味', '使我們海賊出名的事情有很多，但是衛生可不在其中。許多海賊船上的老鼠比人還要多上個五六倍。$B$B也難怪我們入島不久後，所有的熊都得了狂犬病。長話短說，頭目要牠們全死光。$B$B事情就是這樣，我從暴風城中得知了一種野熊麝香的香味配方。我們殺了熊，再賣掉麝香。我給咱們找到了一個大好的生意機會。你覺得如何?', '凜風峽灣，無賴角的帥哥泰瑞要你在附近從狂暴棕熊身上取得4個野熊麝香。', '', '去找凜風峽灣的帥哥泰瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11456 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11456, 'zhTW', '餵飽倖存者', '我們巨牙海民大多以漁獲作為糧食。當需求提高的時候，我們偶爾也會狩獵陸地動物。$B$B附近的伊斯考村最近被海賊所攻擊，倖存者持續地湧入。$B$B我們的漁獲最多只能支撐這一週，島上有許多鍬牙，而他們身上的肉十分豐富。$B$B請幫助我的同胞，狩獵那些大型野獸，並且把牠們的肉帶回來。', '卡瑪廓的長者阿推克要你從群矛之島的海島鍬牙身上取得6個海島鍬牙肉。', '', '去找凜風峽灣的長者阿推克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11457 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11457, 'zhTW', '卡瑪廓備戰', '依斯里魯克，戰爭之靈，族人們描述他是一頭銀色的雄鷹。故事中訴說著依斯里魯克如何和一百隻座狼對抗，拯救他的幼禽。$B$B如今，輪到我們了，同樣要對抗我們的敵人，救出我們的同胞。我們需要製造新的武器。霜翼奇美拉的角既鋒利又能方便地做成矛的尖端，而牠們就棲息在島上積雪的地方。把你所能找到最優質的角帶給我吧。', '長者阿推克需要你取得3根奇美拉角。', '', '去找凜風峽灣的長者阿推克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11458 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11458, 'zhTW', '為伊斯考復仇', '斯里魯克的圖騰已經準備好了，$n，為此我該好好答謝你。我們必須暫時拋開和平手段，對那些攻擊我們的土地與族人的敵人進行反擊。$B$B那些掠奪伊斯考的海賊奴隸販子，發狂似的將所有的俘虜全部屠殺。前往伊斯考的東部執行這場復仇。拿著這把號角，當你需要協助的時候，用它呼喚我的同胞。', '長者阿推克需要你去伊斯考殺掉8名北海奴隸販子，當你需要協助的時候吹響卡瑪廓號角。', '', '去找凜風峽灣的長者阿推克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11460 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11460, 'zhTW', '贏得信賴', '馴鷹活動的第一步也是最重要的一步就是馴鷹者與$g他:她;的鳥兒之間的聯繫。主人必須要贏得鳥兒的信賴!$B$B<海達戈指著他腳邊籠子中的獵鷹。>$B$B想要贏得牠們的信賴，首先要滿足牠們的胃。$B$B這些被稱為峽灣石隼的鳥兒，主要是吃小蟲。峽灣上那些鬆動的岩石是小蟲最佳的生活地點。找一隻小蟲來餵飽籠子中的獵鷹。', '海達戈要你找一隻峽灣幼蛆來餵飽他腳邊籠子中的獵鷹，他就在凜風峽灣的探險者協會前哨。', '已餵食峽灣岩隼', '去找凜風峽灣的『馴鷹者大師』海達戈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11461, 'zhTW', 'DEPRECATED', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11463 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11463, 'zhTW', '北海海賊', '過去的幾周中海賊對補給船隻的攻擊持續增加。我們僱用了一個哥布林間諜來協助我們的探員滲透進入可疑的海賊中。$B$B這一群北海掠劫者在加爾文暗礁的無賴角一帶活動。我們對他們了解有限，但我們知道希爾瓦娜斯想要他們領袖的人頭。$B$B你擁有很高的評價，$N.如果你接下這個任務，我們就可以讓軍隊的注意維持再對抗阿薩斯的部隊上。你願意幫忙嗎?', '找到格瑞希克斯·斷紡，他在凜風峽灣的西南邊海岸，加爾文暗礁的最北端。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11464 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11464, 'zhTW', '賭債', '我聽說你替泰瑞做了一些事情。我是希望能有一些可信賴的人出現。$B$B是這樣，海賊都喜歡賭博。但是呢，往往都不愛付賭債。$B$B如果你對幫我收集一些銅板有興趣的話，我倒是很樂意分你一份。$B$B我們可以從簡單一點的開始。『銀月』哈利是個有點古怪的傢伙，收集了一大堆昂貴的血精靈小飾品在他的帳篷裡 - 不過每次見到我的時候，都老愛裝出一副破產的模樣。去拿回我的黃金吧。', '無賴角的塔廬克要你去拿回『銀月』哈利的欠款。', '', '去找凜風峽灣的塔廬克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11465 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11465, 'zhTW', '被洗劫的商隊', '我率領了一支商隊從瓦爾加德出發，但遭到掠龍氏族的攻擊。我是突襲中唯一的倖存者。不幸的是，我沒辦法取回那些運來的峽灣火雞。這是你嘗試第一次石隼狩獵的好機會。$B$B<海達戈遞給你一個籠子。>$B$B帶著獵鷹籠前往西方，順著營地的路走下去。用獵鷹抓到那些跑掉的火雞。等你完成任務之後，再回來找我。$B$B記得要餵那些獵鷹!', '海達戈要你使用訓練過的石隼來抓回5隻峽灣火雞，他就在凜風峽灣的探險者協會前哨。一旦你完成任務請帶著籠子回報。', '', '去找凜風峽灣的『馴鷹者大師』海達戈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11466 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11466, 'zhTW', '傑克喜歡他的飲料', '我們下一個顧客，傑克‧亞當斯，可不像哈利那麼好打發。他通常一整天都和朋友在喝酒，全都是強悍的海賊。這次不要使用武力，免得弄得太難看。$B$B看你有沒有辦法利用他的飲酒習慣。一個人在喝醉前能喝的酒也就這麼多。$B$B說不定某個酒吧女侍能幫上忙。等他醉倒的時候，看你有沒有辦法伸手摸進他的口袋，拿走屬於我的東西。', '塔廬克要你去拿回傑克‧亞當斯的欠款，他就在凜風峽灣的無賴角。', '', '去找凜風峽灣的塔廬克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11467 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11467, 'zhTW', '死人的賭債', '你或許聽過黑色康拉德，他是這一帶最有名的海賊。$B$B嗯，他和我賭過一把，而且他也沒付錢。$B$B我很想把帳收回來，但問題是...這傢伙死了。$B$B我原本是打算將這筆帳給刪掉，但當我看到這個...$B$B<塔廬克攤開了群矛之島的地圖，東北邊的高原上有著一個X。>$B$B他把財寶藏在巨牙海民的島上。我要你去拿到它。如果讓那個爛貨沒付錢就逃過了，我一定會遭天譴的。', '無賴角的塔廬克要你尋找黑色康拉德的寶藏，在群矛之島東北角的高原上，就在伊斯考的北方。', '', '去找凜風峽灣的塔廬克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11468 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11468, 'zhTW', '獵鷹對隼鷹', '你感受到你們的親密關係了嗎，$n?我想你確實感受到了你和獵鷹之間逐漸成形的聯繫了。如果我告訴你，時候到了你就能夠透過獵鷹的眼睛視物，你會相信嗎?哎呀，這就是馴鷹的最高境界。$B$B不過首先你得打更多獵!這隻猛禽得要更加磨練牠的反射能力。派牠去對付一個更強悍的對手!這個區域的峽灣隼鷹在我們四周的樹頂築了巢。牠們就是你的下一個目標!', '凜風峽灣，探險者協會前哨的海達戈要你使用訓練過的石隼去捕抓10隻峽灣隼鷹。完成任務後，帶著籠子回去找海達戈。', '', '去找凜風峽灣的『馴鷹者大師』海達戈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11469 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11469, 'zhTW', '清潔肥皂', '是呀，我得在瘋子喬納回來前，把甲板打掃得一塵不染。但我沒辦法靠著我的手和膝蓋辦到!$B$B問題是，我們的肥皂用完了。雖然這比較算是你的問題而不是我的，夥伴。既然你是菜鳥，我有特別任務要交給你。$B$B這個島上的西北海岸，那邊有一大堆海獅。在那些浮冰你會找到它們的老大，大羅伊。把他的油脂帶回來，我就可以把它變成你從所未見的超棒肥皂!', '史加斗‧霜首要你去拿大羅伊的油脂作為他魔法清潔肥皂的主要材料。等你拿到之後，回到無賴角東邊的海賊船找她。', '', '去找凜風峽灣的史加斗‧霜首。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11470 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11470, 'zhTW', '鳥群間沒有榮譽存在', '你顯然已經準備好鷹獵活動的下一步了，$n。$B$B帶著你那隻訓練過的石隼到東邊，前往維酷位於石牆升降梯附近的鷹巢。你可以派出你的石隼去從巢中偷出隼鷹蛋。牠的窩就在巢穴周遭峭壁的偏僻地區。找出那些鷹巢並使用你的石隼搜尋所有的蛋!$B$B留意那些峽灣隼鷹族母，$n。如果你被攻擊了，使用你的石隼脫逃和滑翔技能逃走!', '海達戈要你使用訓練過的石隼來抓回8個峽灣隼鷹蛋，他就在凜風峽灣的探險者協會前哨。等你完成任務後，帶著籠子回去找海達戈。', '', '去找凜風峽灣的『馴鷹者大師』海達戈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11471 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11471, 'zhTW', '魚兒上勾', '我知道你為什麼在這，$n。你是被派來殺掉我們的首領，喬納‧斯德林。$B$B我想要提供我的協助。喬納的領導地位威脅著我們的行動。$B$B同時攻擊部落和聯盟的艦隊?簡直是自殺。巨牙海民只要一離開這種氣候環境就會迅速死去，還想把他們賣作奴隸?真是場災難。$B$B喬納的藏身處就在西邊的一處洞穴裡。把他的望遠鏡帶來給我當作證明，在我接手領導後第一個行動就會是停止攻擊你們的盟友。', '無賴角的安妮‧波恩要你將喬納‧斯德林的望遠鏡帶給她。', '', '去找凜風峽灣的安妮‧波恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11472 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11472, 'zhTW', '傳遞心意...', '北海海賊將群島間的公海獅首領，大羅伊給殺死了。他們這麼做只是為了用牠來製作肥皂清理船隻!$B$B<安努尼亞克嘆氣。>$B$B現在海獅們都不交配了。去幫我協助牠們重新繁殖。$B$B你可以在東南方的雙水之濱找到公海獅。他們很愛吃海島東方和西方的美味暗礁魚。$B$B帶上這張網子，收集至少一打的魚 -- 可能還要更多，然後把公海獅引過海峽到母海獅身邊。', '對暗礁公海獅丟擲美味的暗礁魚好將牠引往一隻暗礁母海獅。一旦你幫助牠們找到真愛，就回到卡瑪廓找安努尼亞克。', '已將珊瑚公牛引導至珊瑚母牛處', '去找凜風峽灣的安努尼亞克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11475 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11475, 'zhTW', '完成工作的工具', '我已經研究這個停止運作的傀儡好一陣子了，$n。我想我可以製造一個可供一人乘坐的複製品。這個點子應該可以騙過那些鐵矮人，讓我們得以進入巴爾古恩。$B$B現在我沒辦法使用一把錘子跟火鉗就做出東西來。我需要我的工具!很不幸的是在鐵矮人第一次攻擊時，我將那些工具留在伊瓦德遺跡後方了。去替我取得我的工具!$B$B伊瓦德遺跡就在遙遠的東北方。', '凜風峽灣，探險者協會前哨的渥特要你去取回他的建造工具。', '', '去找凜風峽灣的渥特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11476 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11476, 'zhTW', '切切和呱呱', '這裡的海賊...我們有一些獨特的講話方式。賽吉恩有...許多不同的特殊講話方式...全都混在一起。$B$B我只知道他想要一隻青蛙和一把小刀。$B$B你或許可以從『銀月』哈利那邊弄到便宜的小刀。至於青蛙，鎮上到處都是，隨便抓一隻，然後把刀子一起拿給他。$B$B我痛恨處在那隻小動物的情況下，如果你知道我在講什麼的話。', '從『銀月』哈利那邊拿到一把閃亮小刀，然後抓一隻無賴蛙。把這些交給無賴角的賽吉恩。', '', '去找凜風峽灣的賽吉恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11477 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11477, 'zhTW', '非我族群?', '小聲點，$r。這些鐵矮人反應很快的。別讓挖掘的行動愚弄了你。那些鋼皮的怪物才沒有在挖東西哩!先生，沒錯，正好相反，他們在掩埋這個地方!不管是為了什麼理由，他們都不想要讓人發現這個地方。$B$B是什麼樣的矮人會掩埋古代聖物還有挖掘場地?我來告訴你是那一種:就是你可以不顧後果隨意屠殺的那種!進去裡面把他們全殺光!', '凜風峽灣，伊瓦德遺跡的多尼要你去殺了10個鐵符文摧毀者，5個鐵符文苦力以及2個鐵符文賢者。', '', '去找凜風峽灣的多尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11478 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11478, 'zhTW', '遠方的前哨...', '我知道你還沒去過南邊的探險者協會前哨拜訪我的兄弟們。你為何不幫幫多尼的忙，將這則訊息傳送給史坦華。他會很有興趣聽到有關鐵矮人活動的消息。$B$B就像我說的，坐上坐騎，往南方前進。你會在抵達巴爾古恩前先看到前哨。', '將多尼的信傳送給探險者協會前哨的史坦華。', '', '去找凜風峽灣的史坦華。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11479, 'zhTW', '『鴉腿』丹', '呱呱在講話，碰友。『鴉腿』丹就那邊那條遠遠的船上。$B$B最好跟緊那個爛咖，老兄。告訴他咱不是給他搞好玩的。你把他浸龍骨之後就去跟泰瑞講。', '去挑戰『鴉腿』丹，他就在無賴角的其中一條船上。完成之後和帥哥泰瑞談談。', '', '去找凜風峽灣的帥哥泰瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11481, 'zhTW', '太陽之井的危機', '我代表納魯感謝你所做出的一切貢獻，$r。$B$B儘管我們在外域的事業還遠遠未盡，但我還是希望你能承擔一件至關重要的任務，這件任務無比重要。$B$B當前，我們的部隊分兵四處，很多地方已經無\\r\\n暇顧及，但是為了緩和這裡的形勢，我們仍然派出了一支部隊轉至艾澤拉斯，調查太陽之井高地的狀況。$B$B那裡需要你，$n，去向拉雷索爾報到吧。告訴他，我還會派更多的人過去。', '撒塔斯城奧爾多高地的聖光護衛者阿德因要求你轉至太陽之井高地，與主教拉雷索爾談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11483, 'zhTW', '我們可以重建它', '工具?有了。材料?沒有。$B$B如果我們要建造這個東西，你得給我材料。$B$B優先中的優先，$n。我需要從尼弗瓦拿到一個大桶，好來做成骨骼結構，然後從瓦爾加德那邊拿一些黑鐵鑄塊，還要從貝爾海姆那邊取得工業力量之繩。$B$B尼弗瓦和貝爾海姆是西北邊的維酷村鎮。瓦爾加德在匕鞘海灣，也在西北邊。和馬概先談談好取得鑄塊。等你全都搞定，他會把你送回這裡。', '凜風峽灣的探險者協會前哨的渥特要你帶給一個大桶、工業力量之繩和黑鐵鑄塊。', '', '去找凜風峽灣的渥特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11484, 'zhTW', '我們擁有技術', '儘管一件機械的基本結構是很重要，但我們也不應該低估一樣傀儡的外觀。如果我們要欺騙那些鐵矮人，那麼複製體就一定要很精確!$B$B這一點我是辦得到。$B$B帶給我從這個區域的鍬牙身上取來的新鮮的鍬牙毛皮，還有從西北方的尼弗瓦或貝爾海姆的維酷人身上取來的鋼質肋材。', '凜風峽灣、探險者協會前哨的渥特要你帶給他一張新鮮的鍬牙毛皮和鋼質肋材。', '', '去找凜風峽灣的渥特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11485 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11485, 'zhTW', '鐵符文傀儡與你:火箭跳躍', '好吧，$n;到了該你爬進去這個東西內部並學著操作它的基本功能了。當你準備好，上工作臺，我會讓你進入傀儡內坐定。$B$B你的首要課程就是學會使用傀儡的傳送系統。你會注意到鐵矮人在挖掘地點附近設置了特別的符文雕像。他們的傀儡就是使用那些符文雕像充電並進行點對點飛行。去試試我立在這裡的符文雕像看看。', '凜風峽灣，探險者協會前哨的渥特要你對鐵符文雕刻使用鐵符文傀儡的火箭跳躍能力。一旦完成任務後，你可以點選寵物視窗選擇解散來取消傀儡。', '已掌握火箭跳躍', '去找凜風峽灣的渥特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11486, 'zhTW', '美酒中的美酒', '我知道像你這樣的$G小子:姑娘;最喜歡阻止衝突了，對吧？你想要讓你們的啤酒節平平安安地辦完，不要出亂子。那麼我有一個提議……$B$B在這只酒杯中裝滿我們最棒的烈酒，然後把它交給鐵爐堡外的啤酒節組織者，這樣我們黑鐵矮人也算是參加了這個節日！全艾澤拉斯最棒的烈酒來自這裡！黑石山的深處！不要忘了這一點！', '將黑鐵啤酒杯交給丹莫洛的埃菲庫格·鐵桶。', '', '到丹莫洛找埃菲庫格·鐵桶。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11487 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11487, 'zhTW', '美酒中的美酒', '我知道像你這樣的$G小子:姑娘;最喜歡阻止衝突了，對吧？你想要讓你們的啤酒節平平安安地辦完，不要出亂子。那麼我有一個提議……$B$B在這只酒杯中裝滿我們最棒的烈酒，然後把它交給奧格瑪外的啤酒節組織者，這樣我們黑鐵矮人也算是參加了這個節日！全艾澤拉斯最棒的烈酒來自這裡！黑石山的深處！不要忘了這一點！', '將黑鐵啤酒杯交給杜洛塔的塔波爾·斯威雷格。', '', '到杜洛塔找塔波爾·斯威雷格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11489 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11489, 'zhTW', '鐵符文傀儡和你:收集資料', '你在操作傀儡的工作當中最重要的部分就是收集資料。我已經放置了一個鐵矮人聖物在遠處的貨車上。那是一顆懸浮，閃著電光的灌能水晶。$B$B上工作臺去，我會將你置入傀儡。一旦你回到駕駛座，使用傀儡的資料收集技能取得測試資料。', '凜風峽灣的探險者協會前哨的渥特要你在接近鐵矮人聖物時使用鐵符文傀儡收集資料的技能。一旦完成任務後，你可以點選寵物視窗選擇解散來取消傀儡。', '', '去找凜風峽灣的渥特。', '已收集測試資料', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11490 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11490, 'zhTW', '占卜者的占卜', '到殿堂去...使用寶珠。$B$B<提里斯喘息著。>$B$B快一點...一定要...阻止他們...在他們能夠...$B$B<提里斯在你面前死去。>', '提里斯要你在博學者殿堂的陽臺使用寶珠。', '', '去找魔導師平台的卡雷苟斯。', '占卜法球已啟動', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11491 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11491, 'zhTW', '鐵符文傀儡和你:虛張聲勢', '你隨時要有預備計畫，以免你的主要計畫發生意外!那就是為何我會將反智慧系統內建於傀儡中的原因。$B$B當你駕駛著閃亮新坐騎在巴爾古恩挖掘場時，可能會招致一些懷疑。這就是你的虛張聲勢技能存在的理由!你只要在被質問時，使用這個技能就可保你安然無恙。$B$B踩在雷布隆斯基的毯子上試試這個能力，一旦他開始咆哮生氣時，就使用虛張聲勢!$B$B等你準備好了，就爬上工作臺吧。', '凜風峽灣，探險者協會前哨的渥特要你在踏上雷布隆斯基的地毯後，對他使用鐵符文傀儡的虛張聲勢技能。一旦完成任務後，你可以點選寵物視窗選擇解散來取消傀儡。', '已唬弄勒布朗斯基', '去找凜風峽灣的渥特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11492 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11492, 'zhTW', '大難不死', '歡迎來到太陽之井，凡人。你來的正是時候。$B$B你應當也已經看到了，現在燃燒軍團正夜以繼日地將太陽之井內的強大能量運用於他們那些邪惡而卑賤的目的。$B$B凱爾薩斯也重新站了起來，並繼續領導和統籌著他的部隊配合燃燒軍團。我們必須再一次阻止他。$B$B但是，現在有一件更加緊急和複雜的事情等著我去處理，凱爾薩斯的命運恐怕必須交給你來完結了。千萬不要讓我失望。$B$B祝你好運，我們很快還會再見面的。', '卡雷苟斯要求你擊敗魔導師平臺內的凱爾薩斯。取下凱爾薩斯的徽記之後，立刻向破碎殘陽基地的主教拉雷索爾覆命。', '', '去找奎爾丹納斯島的主教拉雷索爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11493 AND `locale` = 'zhTW';
DELETE FROM `quest_template_locale` WHERE `ID` = 11494 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11494, 'zhTW', '閃電聖物', '好了，構造體各項機能測試完畢，你可以準備出發了。除了之前你測試過的所有系統以外，我還給這臺機器加上了泰坦語的聽說翻譯功能。$B$B把它帶到南邊的巴爾古挖掘場去，然後開始從那些充斥著閃電能量的聖物裡收集資料。萬一有任何鐵矮人懷疑到你，馬上對他們使用唬騙系統。哦，對了，別忘記利用火箭助推系統在那些符文之間跳躍！$B$B那麼，準備好了的話，就坐上駕駛座吧！', '凜風峽灣探險者協會哨站的沃爾特要你使用鐵符文構造體的收集資料技能收集15份鐵符文資料。$B$B完成任務後，你可以在寵物選項選單中點選解散寵物來解散構造體。', '', '去凜風峽灣找探險者協會哨站的沃爾特。', '收集鐵符文資料', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11495 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11495, 'zhTW', '轟鳴的雷霆', '我們在巴爾古挖掘場挖開的那個洞穴……許多人見了都是繞著走的……我倒也不怪他們膽小。那個洞穴裡一直髮出雷鳴一般的聲音，$N！轟鳴的雷聲！$B$B而且你要知道，所有進去探索過的人都遭遇了不幸！好多人甚至再也沒回來過。於是到最後，就沒有任何人敢進去那裡了。$B$B不過，既然你要去巴爾古挖掘場，不如幫我們去檢視一下那個洞穴吧。仔細研究一下那裡面的泰坦雕塑，然後把你瞭解到的東西告訴我。', '凜風峽灣探險者協會哨站的沃爾特要你使用鐵符文構造體仔細探索巴爾古挖掘場內的雷霆洞穴。$B$B完成任務，你可以在寵物選項選單中點選解散寵物來解散構造體。', '調查雷霆洞穴', '去凜風峽灣找探險者協會哨站的沃爾特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11496 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11496, 'zhTW', '聖殿的結界', '我們的首要任務是佔領陽灣聖殿。只要控制了它，我們就能利用它的能量，開啟一道從撒塔斯城到這裡來的傳送門。$B$B聖殿周圍現在到處都是失心者——退化成腦殘形態的血精靈。通常來說，它的防禦設施應該能夠阻止敵人的入侵，但失心者把防護結界的能量源給偷走了。$B$B消滅那些失心者，從他們手上的奪回法力餘燼，用它們重新啟用聖殿的防護結界。', '破碎殘陽基地的瑟里斯·黎明之心希望你能從失心魔癮者和失心吞噬者那裡獲取4份法力餘燼，用它們啟用東邊的陽灣聖殿周圍的水晶結界。', '啟用水晶結界', '去奎爾丹納斯島的破碎殘陽基地找瑟里斯·黎明之心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11497 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11497, 'zhTW', '學習飛行', '雖然這或許最後會危及我長遠的生意，但以$g他:她;自己的坐騎馳騁天際的夢想，總是比一個地方接著一個地方的接駁飛行要更好。$B$B我完全明白這種感覺。$B$B你，我的朋友，要走一趟影月谷西南邊的蠻錘要塞。等你到了那裡，和伊爾莎·咆釀談談關於飛行指導的事情。提醒你，她的訓練可不便宜。但你會發覺這是值得的。', '伊爾莎·咆釀談談，她在影月谷的蠻錘要塞。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11498 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11498, 'zhTW', '學習飛行', '雖然這或許最後會危及我長遠的生意，但以$g他:她;自己的坐騎馳騁天際的夢想，總是比一個地方接著一個地方的接駁飛行要更好。$B$B我完全明白這種感覺。$B$B你，我的朋友，要走一趟影月谷西北邊的影月村。等你到了那裡，和歐洛克談談關於飛行指導的事情。提醒你，他的訓練可不便宜。但你會發覺這是值得的。', '和歐洛克談談，他在影月谷的影月村。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11499 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11499, 'zhTW', '懸賞:凱爾薩斯王子的璽戒', '$c，今天我的要求幾乎是不可能的任務。今天，你得取來血精靈之主，凱爾薩斯·逐日者的璽戒!$B$B事實上，謠傳說他在風暴要塞的死去只是詐死。他已經再次出現了，這次是在奎爾達納斯之島上的博學者殿堂。他在那裡做什麼得要別人來告訴你。我只知道我認識許多收藏家都對他的王戒非常有興趣，而我打算替他們弄到這個東西。$B$B或者該說，我希望你替我做到。', '風之貿易者札令姆要你取得凱爾薩斯王子的璽戒。帶到撒塔斯的陰鬱城交給他以換取賞金。這個任務只能在英雄難度下的博學者殿堂完成。', '', '去找泰羅卡森林的商人扎雷姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11500, 'zhTW', '懸賞:折磨之女', '風又再對瑪頓恩低語，折磨之女得被送回他們出現的地獄。$B$B瑪頓恩知道這些惡魔可以在奎爾達納斯之島的博學者殿堂找到。$B$B也許你會完成這件事以換取賞金，又或許你不會。', '虛空行者瑪頓恩要你解決4名折磨之女。完成之後回到撒塔斯的陰鬱城找他以換取賞金。', '', '去找泰羅卡森林的虛空獵手瑪哈杜恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11502 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11502, 'zhTW', '防衛哈剌', '我們不是個好戰的民族，$r。但要是戰爭侵犯到我們的土地，我們也絕不逃跑。$B$B聯盟與部落在哈剌掀起戰爭，一直延燒到西北。我們不知道血精靈在耍什麼詭計，但部落的任何勝利都是災難。我們同胞與獸人間的歷史充滿了血腥與背叛。$B$B前往哈剌並且殺死我們的敵人。我們將會回報你金錢、榮譽與名聲。', '在哈剌擊敗10名敵對玩家，然後回去找泰拉的拉寇爾。', '', '去納格蘭找塔拉的拉庫爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11503, 'zhTW', '新敵與宿怨', '我們古老的宿敵，德萊尼，帶著強大的盟友回來了。他們在西南的哈剌掀起戰爭。$B$B我們必須阻止他們在哈剌獲得勝利，不然卡拉達爾將陷入危機。$B$B去殺死那些協助我們宿敵的傢伙。', '在哈剌擊敗10名敵對玩家，然後回去找卡拉達爾的可托克。', '', '去納格蘭找加拉達爾的卡爾託格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11504 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11504, 'zhTW', '亡者重生!', '東邊的道路是巨牙海民主要的狩獵小徑。至少曾經是...$B$B近來，回到卡瑪廓的獵人們宣稱死者已經復活，並出外尋找鮮血!那就是我和我兒子前來這裡的原因。長者阿推克要我們在懸崖這找出解決方法。$B$B你會願意在我們需要時幫助我們嗎?我在尋找願意前往盾丘冒險犯難的英雄，就在此地的東南邊。在被褻瀆的墳地中尋找線索，並將你的發現帶回來給我。', '凜風峽灣內卡瑪廓的歐弗斯中，位於遠古升降梯的歐弗斯要你去找出芬吉爾的線索，洛丁的線索，還有伊蘇鐸夫的線索。', '', '去找凜風峽灣的卡瑪廓的歐弗斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11505 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11505, 'zhTW', '奧齊頓之靈', '奧齊頓的靈魂並沒有在爭鬥中支持聯盟或部落，但獲取它們的眷顧能提供我們在這個區域一些優勢。$B$B在古老的習俗中活著的人們曾向白骨荒原的靈魂尖塔獻上敬意 - 但通常只在每日特定的時刻。如果你能在特定的時刻裡佔領這些哨塔，你就會將靈魂引領至我們這一方。$B$B若我們獲得靈魂的眷顧，它們就會協助我們。', '幫助聯盟佔領白骨荒原的尖塔。', '佔據一座靈魂之塔', '去泰羅卡森林找奧蕾莉亞要塞的驅魔師蘇利文。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11506 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11506, 'zhTW', '奧齊頓之靈', '德萊尼或許是我們的敵人，但他們在奧齊頓的祖靈卻是躁動而沒有陣營。$B$B德萊尼的傳統是在每天特定的時候對靈魂尖塔獻上敬意。如果你能幫我們在那時佔領哨塔，你就可以幫助那些奧齊頓的靈魂回歸平靜。$B$B聯盟會試圖想要佔領哨塔好獲得死者的眷顧。我們一定要確保勝利是屬於我們的。', '幫助部落佔領白骨荒原的靈魂尖塔。', '佔據一座靈魂之塔', '去泰羅卡森林找碎石堡的驅魔師瓦沙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11507 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11507, 'zhTW', '長者阿推克和卡瑪廓', '<歐弗斯捆起了你帶給他的線索。>$B$B我的人民在與北海掠劫者的戰爭中遭到了殘酷的侵略。如果有任何巨牙海民能夠幫助我們完成導正海賊的錯誤，這人一定會是卡瑪廓的長者阿推克。你必須馬上將這些線索交給他。$B$B要前往卡瑪廓你一定得使用我前面的遠古升降梯。搭乘升降梯直通卡瑪廓找到長者阿推克。', '凜風峽灣的卡瑪廓的歐弗斯要你將歐弗斯的包裹送到卡瑪廓給長者阿推克。', '', '去找凜風峽灣的長者阿推克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11510 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11510, 'zhTW', '『史酷朵斯』', '喬納‧斯德林在發瘋之後的第一件事就是拿走我珍貴的辛多雷占卜水晶，然後拿去餵給了我的剋星，虎鯨『史酷朵斯』。$B$B那個該死東西的名字可不是我取的。我只知道她在無賴角東南方的船隻邊徘徊。殺死那隻發育過度的金魚，割開她的胃把我漂亮的辛多雷水晶給找回來。$B$B完成了這件事，我們就可以來談談生意。', '無賴角的『銀月』哈利要你從虎鯨『史酷朵斯』的身上取回辛多雷占卜水晶。', '', '去找凜風峽灣的『銀月』哈利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11511, 'zhTW', '風暴之怒法杖', '這些神器受到了詛咒，$r，你一定是瘋了才會想要尋找它們。我知道每一個和這些東西接觸的人，不是瘋了就是被殺死。$B$B就舉法杖為例，最後一次我聽見它，就是載著這根法杖的船隻被遺棄，留在群矛之島的海岸上腐爛，就在北方不遠。$B$B如果你真的想要那玩意兒，就去檢查船上的貨物吧。$B$B不管你做什麼，都絕對不要把法杖帶回來這裡!還有，離阿巴督爾遠一點!他會把你的心臟給挖出來。', '找到風暴之怒法杖，然後把它交給凜風峽灣的卡瑪廓的歐弗斯。', '', '去找凜風峽灣的卡瑪廓的歐弗斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11512 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11512, 'zhTW', '伊蘇鐸夫的冰凍心臟', '有人說喬納原本就腦筋不太正常，但我知道真相。是因為那個心臟。那個該死的冰凍心臟!從他把那個東西從墳墓中拿出來時就看出他的改變。我看到血液在他的血管中結冰...是那個時候他才真正瘋了。$B$B他離開我們，在小島的北方挖了一個自己的洞穴。我聽說他把心臟丟在他的熊穴之中。太微小，太遲了...$B$B要是你敢把心臟帶回這裡來，我一定親手把你給殺了!', '找到伊蘇鐸夫的冰凍心臟，然後把它交給凜風峽灣的卡瑪廓的歐弗斯。', '', '去找凜風峽灣的卡瑪廓的歐弗斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11514 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11514, 'zhTW', '維持太陽之井傳送門', '我們必須要維持傳送門的能量，否則它就會崩解。貝許爾平臺的以太族所藏匿的法力電池正好符合我們的需求。平臺就在劍刃山脈的西北角，就在北邊。$B$B記得，你需要從那些以太族身上取得一個相位裝置，使用它來確定走私貨物的位置。$B$B當心那些負責守衛法力電池的相位龍鰻。', '找到10個走私的法力電池，然後把他們交給撒塔斯城，聖光露臺的主教納蘇安。', '', '去找沙塔斯城的主教納蘇安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11515 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11515, 'zhTW', '血債血償', '當凱爾薩斯的部隊透過那道傳送門撤退時，他最忠誠的侍從們得到了可怕的獎勵。他們留了下來，啜飲著惡魔的血液。$B$B這些血液改變了他們，賜予了他們新的力量，也證明了他們的墮落。$B$B從惡魔身上取得血液樣本，用血液啟用魔能虹吸寶石的能量，然後奪走這些傲慢蠢貨的新力量。在他們變得虛弱之後殺死他們，然後回來向我覆命。', '基爾加丹王座的魔導師瑟伊拉希望你使用魔能虹吸寶石殺死4個憔悴的魔血精靈。你需要用附近的天怒先鋒身上的惡魔血液來啟動魔能虹吸寶石。', '', '去地獄火半島找基爾加丹王座的魔導師瑟伊拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11516 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11516, 'zhTW', '轟炸傳送門', '我們必須得關閉這道傳送門，阻斷燃燒軍團向太陽之井增援。$B$B拿上這些灰燼，裡面有我創造的活焰。只要有足夠的能量支援，它就能產生強大的破壞力。$B$B在活焰周圍殺死那些遊蕩的魔能火花，這樣活焰就可以逐漸得到能量，變得越來越活躍。$B$B等你完成後，把活焰帶到傳送門那裡去，它知道下一步該怎麼做。', '基爾加丹王座的魔導師瑟伊拉希望你使用熾熱的灰燼召喚一個活焰，在它周圍消滅大型魔能火花，它就會逐漸變成一個不穩定的活焰。帶著不穩定的活焰去摧毀軍團傳送門。', '摧毀軍團傳送門', '去地獄火半島找基爾加丹王座的魔導師瑟伊拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11518 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11518, 'zhTW', '太陽之井每日傳送門旗幟', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11520 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11520, 'zhTW', '尋根', '歡迎，$r。$B$B我怕這裡沒什麼能提供的，我得等我的試劑到貨。$B$B在我要求的補給中，其中有一種特別的試劑，刺棘根莖，特別難以取得。$B$B所幸，我知道一個秘密…$B$B使用刺棘撕掠者的腺體，可以控制劫毀者來挖掘那些根莖。$B$B要找到那些根莖，你要旅行到外域，從撒塔斯往東北飛，直到刺棘高地。', '日境港的瑪納要你去外域的刺棘高地收集5個刺棘根莖，然後再回來找她。', '', '去找奎爾丹納斯島的瑪納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11521 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11521, 'zhTW', '繼續尋根', '我的存貨當前很充足，但仍然需要大量的荊刺根鬚來保證日常所需。$B$B採集這些根鬚的確很困難，但我知道有一種特別的方式可以獲得它們。$B$B利用荊刺剝石者的腺體，就可以控制一頭掠食者來幫你挖出這些根鬚。$B$B想要找到這些根鬚的話，從外域的撒塔斯城一直往東北飛，就能到達荊刺高地了。$B$B$n，等你採集到了5份根鬚後就回到我這裡來吧。', '陽灣港口的瑪爾娜希望你轉至外域的荊刺高地，收集5根荊刺根鬚給她。', '', '去奎爾丹納斯島找陽灣港口的瑪爾娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11522 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11522, 'zhTW', '', '[PH]基於某種原因，(TBD)，\\n\\n\\r\\n你必須收集5條銳刺根。$B$B這種植物只能在沙塔斯東北方的一處偏僻地點找到，就在你翻過山脊、即將進入地獄火半島的地方。', '', '', '返回覆命。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11523 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11523, 'zhTW', '啟用結界！', '我們已經成功地讓聖殿周圍的水晶結界恢復正常，但為什麼就這麼罷手呢？我們的其它建築都需要建立防禦措施，不過失心者仍然在頑固地偷取著結界的能量。$B$B消滅那些失心者，奪回他們手上的法力餘燼，用以啟用聖殿的結界。我們的安全就全都靠它了。', '破碎殘陽基地的瑟里斯·黎明之心希望你能從失心魔癮者和失心吞噬者那裡獲取4份法力餘燼，用它們啟用陽灣港建築物外圍的水晶結界。', '啟用水晶結界', '去奎爾丹納斯島的破碎殘陽基地找瑟里斯·黎明之心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11525 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11525, 'zhTW', '轉化更多奧術守衛', '我的計劃成功了。依靠這些奧術守衛的幫助，我們已經成功得拿下了陽灣聖殿。$B$B我製造了一批新的水晶，可以讓更多的奧術守衛接受我們的指令。把它們放入那些被打敗的奧術守衛的外殼裡。成功控制它們之後，我會把它們部署到別的地方去。', '破碎殘陽基地的守備官夏安希望你將調和過的水晶核心放入5臺被打敗的奧術守衛體內，將它們轉換成友軍。', '', '去奎爾丹納斯島找破碎殘陽基地的守備官夏安。', '轉化奧術守衛', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11526 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11526, 'zhTW', '失蹤的魔導師', '我們已經派出一名精英人員前去調查南邊黎明廣場中央的惡魔傳送門的狀況，但她一直沒有回來。$B$B帶上這張卷軸，這是我們從一名敵人的屍體上搜出來的。我們相信它能讓你使用那座傳送門，一旦穿越了那道傳送門以後，立刻找到魔導師瑟伊拉，並儘可能協助她。', '在黎明廣場的傳送門附近使用軍團傳送卷軸。穿越傳送門之後，立刻找到魔導師瑟伊拉。', '', '去地獄火半島找基爾加丹王座的魔導師瑟伊拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11527 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11527, 'zhTW', '慈悲號上的叛變', '哎，我們出了點問題，兄弟。我的砲手叛變了!我的船員得一面在甲板上給索洛夫一點顏色瞧瞧，一面還得應付底下叛亂的砲手。$B$B你得下去對付那些老水手，並且把船尾大砲要用的火藥粉拿來。$B$B等你填充好大砲，索洛夫就死定了，而戰利品也手到擒來!', '船長艾爾利斯要你從船艙中拿回5個桶裝火藥粉。他就在凜風峽灣的慈悲姐妹號之上。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11528 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11528, 'zhTW', '冬幕節禮物', '', '禮物上有一個小牌子寫著:冬幕節快樂，$n!。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11529 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11529, 'zhTW', '索洛夫的戰利品', '我的船員已經把大砲裝填妥當，就等著你啦，兄弟。它就躺在船尾甲板，就在船的另一頭。快就位，等到索洛夫進入視線的時候就開火!$B$B等我們把那個旱鴨子給打下來，你就要去替我們收取戰利品，你也知道我們沒辦法離開這艘該死的船!把戰利品帶給我，你也可以分到一份 - 盾牌...', '使用大砲殺死索洛夫，取得索洛夫的戰利品。把索洛夫的戰利品還給慈悲姐妹號的船長艾爾利斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11530 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11530, 'zhTW', '阿薩瑞特之盾', '這是你的盾牌。我希望它不會詛咒你，像它詛咒我和我的船員一樣。你不必急著回家，不過你也不能待在這裡...我很確定有人對於拿回這個東西很感興趣。$B$B好啦，現在帶著這個東西滾下我的船吧!', '將阿薩瑞特之盾還給卡瑪廓的歐弗斯，他在凜風峽灣的遠古升降梯。', '', '去找凜風峽灣的卡瑪廓的歐弗斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11531 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11531, 'zhTW', '奇怪的引擎零件', '這個奇怪的引擎零件看起來並不適用於蒸汽幫浦，也不像是你看過的任何機器。或許李小炸會知道些什麼。', '把奇怪的引擎零件帶去給泰倫多爾的李小炸。', '', '去贊加沼澤找泰雷多爾的凱莉·弗萊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11533 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11533, 'zhTW', '繼續空襲', '由於我們對死亡之痕的燃燒軍團保持空襲，我們成功地拿下了軍械庫。$B$B事實上，如果我們能持續對他們進行空襲的話，一切都會變得非常順利。拿上這些奧術炸彈，去對付那些惡魔。$B$B如果你做好了飛行準備，就去和陽灣港口的艾雷·碎雲談談。', '戰鬥法師艾爾娜希望你去和艾雷·碎雲談一談，飛往死亡之痕。用奧術炸彈殺死2個深淵霸主、3個艾瑞達巫師和12個天怒執行者。', '', '去奎爾丹納斯島找陽灣聖殿的戰鬥法師艾爾娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11534 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11534, 'zhTW', '向納蘇恩報到', '我真高興能看到你在這裡，$c！現在我們已經從失心者手裡搶回了這處聖殿，當務之急就是在這裡建立起一座通向外域撒塔斯城的傳送門。$B$B我尊貴的上司——主教納蘇恩當前正領導著別動隊中的許多法師處理傳送門的能量維持事宜。他要求我派一些有前途的後備兵去幫助他。$B$B拜託你了，立刻轉至撒塔斯城，到聖光廣場的阿達爾身旁去找他。', '商人波塔努斯要求你轉至撒塔斯城，與聖光廣場上的主教納蘇恩談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11535 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11535, 'zhTW', '做好準備', '物資正在運來，起碼我是這麼被告知的。$B$B但無論如何，我們無法繼續等待支援會在攻勢陷入困境前到來。我們必須要盡量利用手邊的資源。$B$B就我來說，我需要礦石來製造鐵砧，好讓我可以著手升級我們的鎧甲和武器。$B$B在東邊的海岸有一群納迦，他們在收集礦石並且裝箱要運送給燃燒軍團。$B$B偷走他們的礦石會對我們有很大的幫助...。', '日境軍械庫的鐵匠荷莎要你殺死東部的暗脊部屬，用他們身上的鑰匙，然後從箱子中偷取三塊礦石。', '', '去找奎爾丹納斯島的鐵匠荷莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11536 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11536, 'zhTW', '不要停下……', '既然我們已經有了鐵砧，那麼我就可以真正地開始工作了。$B$B不管我們能得到多少幫助，都要好好利用這些暗脊鐵礦石。如果我們想在這裡取得勝利，就需要持續地補充武器和裝備。$B$B這裡東面的海岸上有一群納迦正在採集礦石，他們把礦石打包運送給燃燒軍團。$B$B如果能從他們手上奪取礦石的話，可真稱得上是一石二鳥……', '陽灣軍械庫的鐵匠霍爾薩希望你去殺死東面的暗脊侍從，奪取他們的鑰匙，然後從他們的箱子裡偷取3塊礦石。', '', '去奎爾丹納斯島找陽灣軍械庫的鐵匠霍爾薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11537 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11537, 'zhTW', '繼續作戰', '我們必須持續不斷地消滅燃燒軍團的部隊，挫敗他們的銳氣。$B$B仇恨使者是燃燒軍團的特種部隊，專門負責增援重要的戰略地點。燃燒軍團的士兵會因為他們的到來而更加奮勇作戰，因為他們對仇恨使者的恐懼遠大於對我們的恐懼。$B$B今天我們會改變這一切。拿上這面戰旗，去黎明廣場掃蕩惡魔。等到他們派出仇恨使者後，幹掉他，把戰旗插在他的屍體上。', '先驅者伊努羅希望你轉至黎明廣場，殺死仇恨使者和6名燃燒軍團惡魔，然後將破碎殘陽戰旗插在仇恨使者的屍體上。', '', '去奎爾丹納斯島找陽灣聖殿的先驅者伊努羅。', '將戰旗插在仇恨使者的屍體上', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11538 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11538, 'zhTW', '日境軍械庫的戰鬥', '燃燒軍團控制著日境軍械庫，它在我們的行動中具有重要的戰略價值。只要他們的士氣高昂，我們就很難奪取建築物的控制權。$B$B憎恨密使是軍團的打擊部隊派來鞏固他們的戰術據點。敵人靠著他們的抵達正在重整。比起我們，他們更懼怕這些憎恨密使。$B$B今天，我們要改變這件事。拿起這個旌旗並且殺死那些軍團惡魔。等到憎恨密使出現，殺死他並且刺穿他。', '先驅者因努羅要你殺在曙光廣場或日境軍械庫的6隻燃燒軍團惡魔以及憎恨密使。用破碎之日旌旗刺穿憎恨密使的屍體。', '', '去找奎爾丹納斯島的先驅者因努羅。', '憎恨使者已被刺穿', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11539 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11539, 'zhTW', '奪下港口', '凱爾最精英的部隊之一，曦刃軍團目前駐紮日境港和晨星村。$B$B港口在我們的計畫中佔有關鍵的位置，所以你對曦刃造成的每一分損傷都對我們來說是莫大的助力。凱爾薩斯會悔恨他為什麼要背棄他的人民，與燃燒軍團同流合污。', '日境軍械庫的博學者伊拉斯塔要你去殺死6名曦刃召喚師、6名曦刃血騎士和3名曦刃神射手。', '', '去找奎爾丹納斯島的博學者伊拉斯塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11540 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11540, 'zhTW', '擊潰晨鋒部隊', '晨鋒軍隊已經被我們趕出了陽灣港口，這一帶已經完全在我們的控制之下了。但不知道為什麼……我並不滿意。$B$B我希望你能轉至西面的晨星村，消滅任何殘餘的晨鋒部隊。他們追隨凱爾薩斯來到這裡時，命運就已經註定了。', '陽灣軍械庫的魔導師伊拉斯塔希望你去消滅6個晨鋒召喚者、6個晨鋒血騎士和3個晨鋒射手。', '', '去奎爾丹納斯島找陽灣軍械庫的魔導師伊拉斯塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11541, 'zhTW', '解救綠鰓奴隸', '納迦佔領了東南面的綠鰓海岸。那些被稱為暗脊海妖的女性納迦用魔法奴役了當地的魚人。$B$B我有責任破壞納迦在那裡所進行的一切活動，這也就是你來這裡的原因。$B$B$C，我希望你能從那些女性納迦身上奪取控制寶珠，將它們扔在綠鰓奴隸周圍，打碎寶珠就能讓魚人恢復自由。$B$B我想這樣魚人就會被激怒，反抗他們的主人。', '瓦琳德拉上尉希望你能解救10個綠鰓奴隸。完成任務之後，去陽灣港口的銀月之傲號上向她覆命。', '', '去奎爾丹納斯島找陽灣港口的瓦琳德拉上尉。', '解救綠鰓奴隸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11543 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11543, 'zhTW', '拒敵港外', '我們剛剛攻佔了陽灣港口，然而不幸的是，有一支滿載著晨鋒預備兵的艦隊正在路上，凱爾薩斯的軍隊很快就將得到增援。$B$B帶上這瓶油，向艾雷·碎雲要一隻龍鷹。你可以騎著龍鷹飛經艦隊上空，一旦達到攻擊距離，就用油在他們的船帆上放火。$B$B之後，你要降落在船上，攻擊那些預備兵。他們的船帆著火以後，肯定會忙作一團，從而無心防禦你的攻擊。', '陽灣軍械庫的守備官凱蘭要求你去跟艾雷·碎雲談一談，並飛越晨鋒部隊的增援艦隊。將火油投擲到對方的船帆上，使之引燃。落地後，再殺死6名晨鋒預備兵。', '', '去奎爾丹納斯島找陽灣軍械庫的守備官凱蘭。', '燒燬辛洛雷號', '燒燬血誓號', '燒燬曙光追尋者號', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11544 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11544, 'zhTW', '阿塔瑪軍備', '影月谷東面的阿塔瑪平臺對於德萊尼人來說是個神聖的地方，但現在那裡滿地都是邪獸人。他們用從那裡挖掘出的特殊礦石製造著邪惡的武器和裝備。$B$B我需要這些裝備，用它們和納迦那裡搶來的礦石製造合金。我們的學者已經讓鐵砧具備了淨化金屬的能力。$B$B從影月天選者、影月斬殺者和影月暗法師身上找到這些裝備。把它們拿到這裡來，在我的鐵砧上打碎並淨化它們，然後把淨化過的阿塔瑪金屬交給我。', '鐵匠霍爾薩要求你在奎爾丹納斯島陽灣軍械庫的鐵砧上打碎阿塔瑪軍備，以此製造5塊淨化過的阿塔瑪金屬。', '', '去奎爾丹納斯島找綠鰓海岸的鐵匠霍爾薩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11545 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11545, 'zhTW', '慷慨的捐贈', '我們已經從敵人的手中奪下了日境，最後的勝利近在咫尺。但我們也付出了高昂的代價，許多勇敢的戰士也為了這個成就獻出了他們的生命。$B$B我的目標就是希望那些在戰場上捐軀的勇士不會被遺忘。我想請你考慮一下給紀念碑基金一些捐贈。多餘的款項則會用來幫助陣亡將士的寡婦與孤兒。', '太陽之井島上日境的隱士艾悠里，希望你能夠捐助10枚金幣。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11546 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11546, 'zhTW', '開始營業', '歡迎你，$n。$B$B我有多種方式可以幫助你進行作戰準備。$B$B比如說，我最近領悟了一種獨特的藥劑配方。$B$B艾澤拉斯很多野外地區都生長著血莓，長久以來人們只把它們當成是一種公害而已。不過我瞭解到，在這種植物受到太陽之井能量的影響後，就會產生一種特殊成分——提取這種成分可以提升使用者的能力。$B$B從附近的灌木叢中找一株樣本給我，我會讓你知道我所指的是什麼。', '陽灣港口的瑪爾娜希望你從奎爾丹納斯島上的灌木叢中收集5顆血莓。', '', '去奎爾丹納斯島找陽灣港口的瑪爾娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11547 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11547, 'zhTW', '魔網能量線的讀數', '一群不勞而獲的傢伙！$B$B你們都只想取得便利，卻從沒想過要去製造一道最簡單的傳送門。$B$B也許給你們一點小小的教訓會讓你們對我在這裡所做的一切有所感激。$B$B拿上這顆水晶，在這裡西面的血水晶、南面的黎明廣場傳送門和東南方的綠鰓海岸一帶的納迦神殿那裡調節水晶。$B$B也許這樣你就會認識到傳送魔法的珍貴……', '陽灣聖殿的星術師達納裡安希望你在血水晶、黎明廣場傳送門和綠鰓海岸的納迦神殿上使用星術師的水晶。', '', '去奎爾丹納斯島找陽灣聖殿的星術師達納裡安。', '接收傳送門讀數', '接收神殿讀數', '接收血水晶讀數', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11548, 'zhTW', '鼎力支援', '我們已經為那些在本次戰爭中犧牲的人們建起了一座紀念碑。對犧牲者的家人與愛人，對那些永遠失去了摯愛的人們來說，這隻能給他們一些微薄的安慰。$B$B我還在募集一筆捐款，以供養那些已經犧牲的英雄們留下的遺族。如果你願意的話，請幫助他們吧。', '奎爾丹納斯島陽灣港的學者艾尤莉希望你捐贈10枚金幣。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11549 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11549, 'zhTW', '慷慨的捐贈者', '你已經為我們做了許多事情，$N。我們非常感謝你的協助。$B$B不過，不知道你是否注意到屋外正在募捐的學者艾尤莉？她是一位非常有魅力的善良人，但儘管如此，捐獻的數額卻還不太夠。$B$B如果你願意捐一筆錢給她，協助她的事業，我想你一定會聲名遠揚的。你覺得怎麼樣？', '學者卡伊索斯希望你捐獻1000枚金幣以協助學者艾尤莉的事業。若完成這個任務，你將會獲得“破碎殘陽的$N”的稱號。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11550 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11550, 'zhTW', '欺詐者降臨', '儘管我們已經付出了巨大的犧牲，但仍然沒能阻止凱爾薩斯執行他那罪惡的計劃。現在太陽之井已經被重新啟用，準備迎接欺詐者的入侵。$B$B在我和阿達爾前面的這個指示器代表著太陽之井當前的防禦狀況。他們升起了數道極其強大的魔法屏障，將我們的攻擊部隊完全隔離在了內部各處核心密室的外面。現在，就是現在，毫無疑問就是我們最需要世界各地之援助的時刻了。$B$B立刻轉至奎爾薩拉斯的正北方，向奎爾丹納斯島上的大法師奈蘇爾報到。', '轉至奎爾薩拉斯正北方的奎爾丹納斯島，向大法師奈蘇爾報到。$B$B鐵爐堡和銀月城的飛行管理員可以將你送到目的地。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11552 AND `locale` = 'zhTW';
