INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11558, 'zhTW', '危險的愛', '這種像傳染病的愛有些不對勁。這情形很噁心，而且當它降低了我們的警戒心，對所有人來說都是個威脅。$B$B我們有這麼多人民都已經陷入如此荒繆的行為已經夠糟了。但我想這甚至還散播到我們的守衛那裡了，他們是應該對這種事免疫的人。$B$B找一名我們的守衛，看看他們是否已經得到了這愚蠢的病。', '取得一張守衛發霉的卡片並帶給幽暗城的芬斯塔德·阿吉歐。', '', '去找奧特蘭克山脈的芬斯塔德·阿吉歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11559, 'zhTW', '冬鰭交易', '既然你可以和冬鰭魚人交談了，這是個好機會讓他們認識你。最好的方法就是和他們談生意。$B$B在魚人眼中最珍貴的就是蚌類，而他們唯一倖存的商人就是阿魯咕嚕咕爾。如果我是你，我會收集一些冬鰭蚌送給他當成禮物。$B$B蚌殼可以在海溝一帶找到，當然也包括冬鰭村和他們的洞窟。', '收集5個冬鰭蚌，然後把它們交給冬鰭避居地的阿魯咕嚕咕爾。', '', '去找北風凍原的阿魯咕嚕咕爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11560, 'zhTW', '喔不，蝌蚪!', '喔太好了，你回來了!$B$B當村子的山崩越過河後出現了洞穴，一個被稱為克拉希穆司的壞心龍蝦人，從洞穴裡冒了出來把冬鰭蝌蚪偷走。$B$B追隨他的所有魚人們身上都產生了變化，當他們再度現身時，他們已經被他控制了。$B$B$c，你一定得游過河並解救村落和洞穴中的冬鰭蝌蚪。$B$B冬鰭部族的未來就靠你了!', '莫戈莫戈大王要你去解救20個冬鰭蝌蚪。完成任務後回到冬鰭避居地找他。', '', '去找北風凍原的莫戈莫戈大王。', '已救出冬鰭蝌蚪', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11561, 'zhTW', '他們!', '我們在水中的兄弟姊妹現在全成了我們的敵人。他們綁架了我們的蝌蚪，把我們趕出了自己的村莊，被他們殺死的，多到我都不會數了。$B$B證明你自己，$r!遊過裂隙去殺死他們!$B$B不管新的王給你什麼樣的禮遇，只有殺死他們我們才會接受你。如果辦不到，你最好快滾，然後永遠也別回來!', '冬鰭避居地的布爾格墨葛要你殺死15個冬鰭魚人。任何戰士、神諭者、巡岸者的組合都可以。', '', '去找北風凍原的布爾格墨葛。', '冬鰭魚人已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11563, 'zhTW', '戈墨爾吉珥 墨勒吉爾 吉爾戈!!!', '要是你那雙可憐的小眼睛有用的話，你就應該看得出來，我們正在被那些海灣北部的虎鯨屠殺!$B$B假如你那個寶貝的夜精靈王想把他的備用服裝要回去，我想你最好認真的幫助我，把虎鯨王吉爾戈的頭顱帶來給我，牠踏著命運的浪潮而來 -- 所有聽見波濤中海妖輓歌的生命，終將希望破滅!$B$B動作要快，$r，就算我們浪費時間在講話的時候，冬鰭魚人都在失去他們的生命!', '姆姆戈莫要你帶著吉爾戈的頭顱回到冬鰭避居地給他。', '', '去找北風凍原的姆姆戈莫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11564, 'zhTW', '多汁的虎鯨燉肉', '情況是，陌生的$r，或許你在追殺虎鯨王吉爾戈。$B$B這樣很好，但如果你想要品嚐絕世珍品的燉肉的話，那你就應該把在微光海灣活動的虎鯨的多汁油脂帶回來給我。$B$B如果你想獲得與你努力相得的回報，那麼動作就要要快...我得花不少功夫來處理那個傢伙的魚身。', '斬擊者布墨格伯姆要你收集7個多汁虎鯨脂。回到北風凍原的冬鰭避居地向他回報。', '', '去找北風凍原的斬擊者布墨格伯姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11565 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11565, 'zhTW', '備用服裝', '很好，只要你們的國王繼續協助我們對抗敵人，他的秘密就不會有洩漏的危險。$B$B嗯，把這個交給他。我仔細清理過了，雖然我不知道他為什麼需要第二件偽裝。$B$B或許他心裡有什麼事想告訴你?', '把莫戈莫戈大王的備用服裝帶到冬鰭避居地給他。', '', '去找北風凍原的莫戈莫戈大王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11566 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11566, 'zhTW', '永不...屈服!', '該是結束這種違反自然情況的時候了，$n。為了讓冬鰭魚人能夠有個未來，克拉希穆司必須死!$B$B我要你帶著我的備用魚人服裝，以投降當藉口混入冬鰭洞窟。拿著白旗，魚人就不會攻擊你。$B$B你可以在洞窟的西南邊最角落處找到他。一旦你靠得夠近，解決掉克拉希穆司。將他的爪子帶來給我，證明你已完成這個污點行動。', '冬鰭避居地的莫戈莫戈大王要你帶一個克拉希穆司之爪給他。', '', '去找北風凍原的莫戈莫戈大王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11567 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11567, 'zhTW', '科瓦迪爾的上古盔甲', '我當時就在運送盔甲的船上。我們才登上船要返航的時候就受到被遺忘者驅逐艦的攻擊。$B$B他們強登上船，把所有東西掠奪一空，然後就鑿沉了船隻。$B$B這是我最後一次看見那套盔甲。如果你要的話，你可以搭乘我的轟炸機從無賴角前往那些驅逐艦停泊的可怕小島。跟我的女人艾朗雅談談，她就在外頭。她會帶你們上轟炸機。$B$B如果你找到了那個東西，你最好別把它帶回來!', '找到科瓦迪爾的上古盔甲，然後把它交給凜風峽灣的卡瑪廓的歐弗斯。', '', '去找凜風峽灣的卡瑪廓的歐弗斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11568 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11568, 'zhTW', '歸於平靜', '<歐弗斯遞給你一個背袋。>$B$B包包中是你發現的那些神器。找出這些物品當初被偷走的盾丘墓塚，位置就在東南邊，並且將神器放回去。希望這樣能使那些在我們狩獵地作祟的靈魂平靜下來。$B$B堅強點，$n...', '在盾丘被洗劫的墓塚使用一包維酷神器，歸還伊蘇鐸夫的冰凍心臟、阿薩瑞特之盾、風暴之怒法杖和科瓦迪爾的上古盔甲。完成後回到遠古升降梯找卡瑪廓的歐弗斯。', '', '去找凜風峽灣的卡瑪廓的歐弗斯。', '艾瑟萊特之盾已歸還', '風暴之怒法杖已歸還', '已歸還伊蘇多夫的冰封之心', '已歸還卡瓦迪爾的遠古護甲', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11569 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11569, 'zhTW', '鑰匙大師俄姆戈苟', '我們一定要逃出這些個洞穴!有些魔法物質從上頭的凜懼島漏了進來，影響了每個人的心智。$B$B鑰匙大師俄姆戈苟在南邊的洞穴裡面。他握有打開我的牢籠鑰匙，從他身上奪過來給我，我才能打開這個牢籠逃出去。$B$B快一點!', '冬鰭洞窟的葛勒格勒格勒要你拿到俄姆戈苟之鑰。', '', '去找北風凍原的葛勒格勒格勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11570 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11570, 'zhTW', '逃離冬鰭洞窟', '我籠子的鎖看起來並不牢固，但我還沒傻到在沒有幫助的情況下試圖逃離這裡。$B$B你願意幫我安全地逃離這個洞窟嗎?沒時間可以浪費了，$r。$B$B等我們回到避居地，讓大王知道我平安無事。他一定會好好獎勵你的。', '平安地將魯格伯護送回去，然後向冬鰭避居地的莫戈莫戈大王回報這個好消息。', '護送魯格布爾至安全處', '去找北風凍原的莫戈莫戈大王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11571 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11571, 'zhTW', '學習溝通', '要幫忙，你必須要學會說冬鰭語。我們要靠著自然與魔法的力量來達成。$B$B拿著這個海螺貝。史卡德就住在海溝的底部，他是個空氣與水的狂怒元素。$B$B一旦打敗了她，就對她的屍體使用海螺去捕捉她的魔法蒸汽。帶著裝滿的海螺回來找我，我將會把我對冬鰭語的知識灌注給你。$B$B幸運的是，一個朋友教過我等下要對你施展的水中呼吸術。', '莫戈莫戈大王給你一個海螺要你對史卡德的屍體使用。之後回到冬鰭避居地把國王的盛滿海螺交給他。', '', '去找北風凍原的莫戈莫戈大王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11576 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11576, 'zhTW', '監控裂口:異常裂壁', '你好，$r，我是達拉然的加倫。$B$B不久以前，從地熱噴發的角度來看來，裂口還算是個平靜的地方。$B$B但是到了最近，地震頻繁到令人提高警覺，地面也出現了裂隙，顯示出一股強大力量的獨特能源正在散發。$B$B我在此地的任務是要紀錄下這些異像。我的儀器顯示出西南方的懸崖還有一個震源。$B$B請帶著這個裝置，然後在你找到新的災害的時候使用它。', '琥珀岩臺的加倫要你在異常裂壁使用奧能檢測儀。', '', '去找北風凍原的圖書管理員加倫。', '已取得裂岩崖異常讀數', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11577 AND `locale` = 'zhTW';
