INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11587, 'zhTW', '劫獄', '你好，$c。我是唐納森，達拉然的忠心代表。$B$B請原諒我的魯莽，但是我們發現我們身處於危機當中。遍佈於艾澤拉斯的法師皆被綁架了，我奉命徵召任何有辦法協助揭開此謎團的人。$B$B位於南邊的營地就是我們調查的起點。我想請你去解救被困在那裡的一位法師囚犯。你會需要從周遭的狩法獵人身上取得他們秘法監牢的鑰匙。', '琥珀岩臺的圖書管理員唐納森要你前往碧晶哨點，從碧晶狩法獵人身上取得碧晶監牢鑰匙，並使用鑰匙從秘法監牢釋放一位被抓住的法師。', '', '去找北風凍原的圖書管理員唐納森。', '已救出奧術囚犯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11588 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11588, 'zhTW', '重複利用', '阻止艾胡恩前來艾澤拉斯並引起一場元素大戰！', '摧毀位於黑暗深淵內的元素艾胡恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11589 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11589, 'zhTW', '重複利用', '阻止艾胡恩前來艾澤拉斯並引起一場元素大戰！', '摧毀位於黑暗深淵內的元素艾胡恩。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11590 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11590, 'zhTW', '綁架', '$n，我們有了麻煩。$B$B我剛剛才得知我們的一位大法師在返回達拉然的途中失蹤了。想當然爾，我們懷疑狩法獵人是他失蹤的幕後主使。$B$B時間非常緊迫。如果我們還打算拯救她的話，我們一定要盡快知道伊娃諾女士發生了什麼事。$B$B帶著這個裝置，回到碧晶哨點，在碧晶巫士垂死之際對他使用裝置。這樣可以束縛他一段時間，讓你可以把他帶回來接受審問。', '唐納森要你在碧晶哨點對一個受傷的碧晶巫士使用秘法捆縛器。然後回到琥珀岩臺向他回報。', '', '去找北風凍原的圖書管理員唐納森。', '被俘的碧藍術士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11592 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11592, 'zhTW', '我們進攻!', '你們獸人當中一位名為鋼顎的獸人試著抄捷徑穿越我們的墳地以節省時間。這最好不是你們部落常有的行為，$r，否則你會發現坦卡族就是你們的終點！$B$B不過，你看起來好像想要協助處理這件事。很好！$B$B鋼顎被詛咒的靈魂現在還徘徊在此地，騷擾著我們的先祖們。我們必須終結他！$B$B如果我們可以活著完成這件事，就去通知你們在北方前哨的霸主博格洛克。$B$B你有在聽我講話嗎？', '幫助遠偵斥候傲蹄以及他的戰歌劫掠者在對鋼顎商隊的攻擊中存活下來，並解決掉軍隊指揮官鋼顎的靈魂。如果成功了，就回報給博格洛克前哨的霸主博格洛克。', '已成功協助長跑者傲蹄的攻勢', '去找北風凍原的霸主博格洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11593 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11593, 'zhTW', '可敬的死者', '我們死者應該要有個英雄般的葬禮，但我們沒辦法在坦卡族的聖地埋葬他們。$B$B我不會要你把他們的屍體拖回來這裡，但帶著這個然後深入陵墓。當你經過那些死去的商隊守衛和工人時，用火炬點燃他們。$B$B向我們的死者致敬，$c!', '鋼顎商隊的蠻兵怒拳要你使用她的火炬燒掉10具死亡的商隊守衛或死亡的商隊工人的屍體。', '', '去找北風凍原的蠻兵怒拳。', '已焚燒陣亡的商隊護衛與工人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11594, 'zhTW', '讓他們安息', '軍隊指揮官鋼顎的白癡行為造成了這一場混亂。他在想些什麼？帶著一隊商隊穿越坦卡族的墓塚？$B$B儘管如此，做了還是做了。現在該是我們忙著處理後果了。$B$B霸主博格洛克要求我盡全力去協助遠偵斥候傲蹄。這位遠偵斥候要我們去讓他的祖先之靈們安息。$B$B你意下如何，$c？你是夠$g勇猛:強壯; 到足以處理如此簡單任務的人嗎？', '讓20個坦卡靈魂安息，不論是鬼魅賢者或者復活的遠偵斥候都行，完成後回報鋼顎商隊的蠻兵怒拳。', '', '去找北風凍原的蠻兵怒拳。', '陶爾金之靈已安息', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11597, 'zhTW', '戰歌要塞的防禦', '我們似乎總是在最糟糕的情形下相遇呢，甲蟲之王。自從我們上一次見面以後，你還一直在拯救世界嗎？$B$B<薩魯法爾輕聲笑了起來。>$B$B不管我們年輕的指揮官怎麼說，北裂境非常需要你的説明。$B$B如果能有一打像你這麼強大的士兵，我們現在已經在奧格瑪舒服地烤火了。$B$B去向戰歌要塞南門外的拉茲格爾大王報導吧。', '向戰歌要塞南方小屋裡的拉茲格爾大王報到。', '', '向霸王瑞茲葛回報，他就在戰歌堡外的南方主要通道。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11598 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11598, 'zhTW', '奪回力石礦場', '當戰歌堡由10呎厚的鋼鐵與岩石所保護，這個礦場卻脆弱無助地受到奈幽蟲族的攻擊。$B$B<瑞茲葛指向西方。>$B$B就在這個礦場後面有著幾千名名天譴軍，等待著攻擊命令。只要奈幽蟲族攻破我們的內部防線，我們就會被阿薩斯的不死軍團所淹沒。$B$B我們絕不能讓它發生 - 所以我們要反攻那些礦場內的奈幽蟲族。$B$B鮮血與雷霆將與你同在，士兵!', '戰歌堡的霸王瑞茲葛要你殺死15隻奈幽巴奈幽蟲族。', '', '去找北風凍原的霸主瑞茲葛。', '納魯巴已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11600 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11600, 'zhTW', '已故的威廉‧愛勒頓', '威廉的脖子被利刃劃過。$B$B進一步的調查只顯示了一個線索可以告訴蕾瑞莎 - 一張寫著威廉‧愛勒頓名字的招募卡。', '到北風凍原的驍勇要塞，把招募卡帶給蕾瑞莎。', '', '去找北風凍原的蕾瑞莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11602 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11602, 'zhTW', '切斷來源', '礦場的空中偵察回報說，奈幽蟲族把他們的蟲卵收藏在靠近基地的鷹架上。這些聰明的野獸...他們讓蟲卵放在高處保持乾燥，遠離戰鬥中心。$B$B你要回去那邊破壞他們的蟲卵。找到它們，打爛它們，毀掉它們。$B$B每毀掉一顆蟲卵就表示少了一打的奈幽蟲族來啃食我們的屍體。', '戰歌堡的霸王瑞茲葛要你摧毀10個奈幽巴卵囊。', '', '去找北風凍原的霸主瑞茲葛。', '', '', '', '納魯巴卵囊已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11603, 'zhTW', '酒後吐真言', '軍隊曾經是老人寇爾本的一切。他退休後，還是堅持將軍隊當成他的生命。$B$B他知道所有將軍，單位，軍旅，派遣隊的名稱...只要你說的出他都知道。他就是你需要的人。$B$B問題在於，他的心靈已經傷痕累累。除非他拿到庫爾提拉斯葡萄酒，不然他不會跟任何人說話。帶他回到身為海軍的時光。$B$B我已經好幾個月沒收到貨物了。最近一艘載滿庫爾提拉斯葡萄酒的商船沉沒在東北邊。去看看你有沒有辦法打撈到一瓶庫爾提拉斯葡萄酒給寇爾本。', '去驍勇要塞東北邊的船難殘骸打撈一瓶庫爾提拉斯葡萄酒，然後將它帶給驍勇要塞旅店裡的老人寇爾本。', '', '去找北風凍原的老人寇爾本。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11605, 'zhTW', '尊榮的先祖', '<當你凝視這尊石雕的同時，從遙遠的方傳來聲音，在你的腦海中回盪著。>$B$B別害怕，陌生人，我是阿特那克長老，這些巨牙海民的先祖，手藝獨步一時的工匠，同時，數百年來，也是這片石礦場的守護者。$B$B這片石礦場飽經蹂躪，這也使得當先祖的靈魂降臨世間的時候，許多石雕仍未完成。你願意幫助我矯正這些錯誤嗎?$B$B首先，我得瞭解這些行於世間的先祖之名。在這些石雕附近，找出它們的標示。', '冷岩礦場外的阿特那克長老需要你分辨出長者凱蘇克、長者撒加尼、還有長者塔克瑞特的石雕在何處。', '', '', '已辨識長老凱蘇克', '已辨識長老薩加尼', '已辨識長老塔克瑞特', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11606, 'zhTW', '耐心正是我們不需要的美德', '我們可以殺掉所有看得到的奈幽蟲族並摧毀所有找得到的卵囊，不過那些東西會一直不停的出現，直到我們炸掉他們的管道和通道為止。當然，我們無法在沒有強大軍火的情況下完成這項工作。不幸的是，我們大多數的儲備物資都被哥布林和鐵匠用在攻城坦克和軍備上。$B$B我們在力石礦場外有一堆品質頗優良的補給品 - 就在所有奈幽蟲族垃圾下面。你只要到那裡去並將東西帶來給我。', '戰歌堡的軍需官侯加斯要你去取回15箱戰歌軍火。', '', '去找北風凍原的軍需官侯加斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11607, 'zhTW', '迷失的靈魂', '在礦場的攻擊中，在這裡工作的薩滿和工匠都陣亡了。這種暴力行為使靈魂世界陷入完全的混亂，我們無法將先祖們引導回家鄉，除非我們有方式安撫這些被殺的靈魂。$B$B這些侵略者本身沒留意到靈魂，不過他們的同伴，碧晶獵犬，感應到這些靈魂並奴役他們。$B$B去殺了這些碧晶獵犬，並使用其所留下的原始能量，將限制這些無辜靈魂的禁錮打破。', '冷岩礦場外區的阿特那克長老要你去釋放3個卡斯卡拉工匠和3個卡斯卡拉薩滿的靈魂。', '', '', '卡斯卡拉工匠之靈已釋放', '卡斯卡拉薩滿之靈已釋放', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11608 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11608, 'zhTW', '把那些蟑螂埋起來!', '東、南、西、北，這些方位是你應該要留心的。在這力石礦場中圍繞著這座堡壘的，是四個地點完美的奈幽巴坑道口。$B$B<侯加斯遞給一個包裹。>$B$B小心謹慎地處理這個包裹，$n。一個失手，你可能就會變成碎肉。$B$B包裹裡面是一些爆鹽深水炸彈。前往每個奈幽巴坑道口，然後在中心點安置深水炸彈。如果一切順利的話，隧道就會坍塌。$B$B快去吧!', '戰歌堡的軍需官侯加斯要你使用爆鹽深水炸彈包裹來摧毀南方、東方、西方和北方的奈幽巴坑道口。', '', '去找北風凍原的軍需官侯加斯。', '南方納魯巴坑洞已摧毀', '東方納魯巴坑洞已摧毀', '西方納魯巴坑洞已摧毀', '北方納魯巴坑洞已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11609, 'zhTW', '撿起碎片', '隨著那些被謀殺的工匠與薩滿獲得安息，我們也可以重新完成那個被攻擊打斷的儀式。你必須要扮演傳統巨牙海民薩滿的角色，你也得戴上所有需要的儀式物品。$B$B現在沒空去打造新的物品了，所以你必須要去搜索採石場，從那些受害者身上取回物品。小心處理這些物品，$n，很多東西都已經有數個世紀的歷史了。你也有可能得從入侵者的手上取回那些東西。', '帶6個巨牙海民儀式物品交給阿特那克長老，他就站在冷岩礦場的外面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11610 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11610, 'zhTW', '引領先祖返家', '藉由你的幫助，先祖的靈魂才能夠回到家，也就是卡斯卡拉的工匠和薩滿滿懷敬愛製成的雕像裡。為先祖們所準備的儀式在礦場遭受攻擊的過程中斷了，你必須完成祭儀。帶著你從礦場中回收的物品，站在有名牌的雕像前，然後吟誦這段頌歌。$B$B<一段陌生的語言浮現在你腦海中，而你可以毫無滯礙的覆誦它。>', '阿特那克長老要你引領長者凱蘇克、長者撒加尼、還有長者塔克瑞特的靈魂到他們的石雕紀念像中。', '', '', '長老凱蘇克的儀式已完成', '長老薩加尼的儀式已完成', '長老塔克瑞特的儀式已完成', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11611, 'zhTW', '被天譴軍抓走', '<莫吐斯長嘆一口氣。>$B$B苦工啊...我們可以張貼一份告示讓奈幽巴免費取用大餐了嘛。$B$B懂嗎，苦工的問題是:（一）他們比泥還扶不上牆;而且（二）他們比痲瘋地精還要不堪一擊。想當然爾，他們第一個被天譴軍抓走!$B$B懂吧，這讓我陷入了窘境，沒有苦工，勞力工作就停頓了。沒有苦工就沒有建設。$B$B找出我的苦工，救出他們，$r。如果他們還活著，你可以在織起的網子裡找到他們，就在力石礦場裡面。', '戰歌堡的工頭莫吐斯要你將5名戰歌苦工救出來。', '', '去找北風凍原的工頭莫吐斯。', '戰歌苦工已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11612 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11612, 'zhTW', '收復礦場', '很高興見到你，$c。我叫伊塔魯克，本來是冷岩礦場的工匠。$B$B當那些神秘的藍色平台從高地上方飛來的時候，我和我的同伴正在為一組新的雕像進行最後的加工儀式。$B$B他們降落的時候，上面的法師一湧而上，屠殺我的同伴，掠奪了礦場。如果不加以阻止的話，他們會毀了我們的雕像然後帶走工藝品。你願意幫助我擊敗這些入侵者嗎?', '冷岩礦場入口附近的依塔魯克要你殺死12個碧晶寶藏獵人。', '', '去找北風凍原的伊塔魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11613 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11613, 'zhTW', '卡魯克的誓約', '他們自稱為科瓦迪爾。我們的族人有著關於他們的傳說;我們把他們叫做圖克哈瑞克 - 霧行者。$B$B我的村子就是被那些巨大的霧人所毀。我認識的每個人都被殺死了，包括我的父親，阿尤特。$B$B根據巨牙海民的律法，我應該要報復那些殺死我親族的人。$B$B但我只是個漁夫，甚至還沒有通過成年的試煉...我沒辦法對付邪惡的科瓦迪爾。$B$B如果你願意替我報了血仇，我會欠你許多。', '卡魯克要你殺死6個斯卡迪爾劫掠者和5個斯卡迪爾長船水手。', '', '去找北風凍原的卡魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11615 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11615, 'zhTW', '奈幽巴秘密', '你瀏覽著書頁，尋找任何重要的訊息。在最後一頁中你發現一些看起來像是發狂似的草寫:$B$B死靈領主。我計算至少有一打。$B$B西邊的農場被用來作為某種恐怖的天譴軍團生產地。$B$B一堆堆的犧牲品。$B$B我想他們就在我的上方。急沖沖的跑向堡壘。我不會被活抓的。$B$B懼毒血毒素。如果他們決定要咬我的話，他們將會得到一個驚喜。$B$B將這個訊息帶回去給巴素司。', '帶著盧瑟的日記給戰歌堡的巡影者巴素司。', '', '去找北風凍原的巡影者巴素司。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11616 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11616, 'zhTW', '傳信給地獄吼', '<巴素司撕掉最後一頁並把它捲起來。>$B$B馬上把這個拿給地獄吼！在這段時間內，我會派出一隻小隊去偵察農場。$B$B記得告訴地獄吼我們需要支援。', '帶著巴素司的便箋給戰歌堡的卡爾洛斯‧地獄吼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11617 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11617, 'zhTW', '阻礙他們的逃脫', '我相信你一定看過那些在礦場上空盤旋的藍白平臺。那些是狩法獵人用來輸送他們部隊的運輸裝置，現在他們用這些來裝載我們的神器與我們雕像的碎片。$B$B我們一定要在他們離開礦場之前阻止他們。$B$B在礦場挖掘的小東西身上會帶著爆裂物。拿到爆裂物然後用來摧毀他們的平臺。他們的領導者在一個著陸的平臺上監視著，但我們之後再來對付他。', '冷岩礦場外的伊塔魯克要你摧毀北部平臺、東部平臺和西部平臺。', '', '去找北風凍原的伊塔魯克。', '東方平台已摧毀', '北方平台已摧毀', '西方平台已摧毀', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11619 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11619, 'zhTW', '『殘酷』加邁爾', '我的父親就是被這掠奪隊的首領，『殘酷』加邁爾所殺。他在海灘上的一個洞穴中建立了居所。$B$B你已經和他的手下打過照面了。結束你挑起的這場戰鬥吧，$n。替我的父親報仇，我會把我僅剩的東西和你分享。', '卡魯克要你擊敗裂鞭水岸的『殘酷』加邁爾。', '', '去找北風凍原的卡魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11621, 'zhTW', '萊維羅希的石板', '你清理了石板上的刻痕，找尋任何你看得懂的內容。你終於找到了以下的片段：「迷霧之子將要收集一千個靈魂，以獻給居於晦暗深海中的，喚醒他的特使。」卡魯克或許會對這個消息感興趣。', '把你在石板上找到的訊息告訴卡魯克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11622, 'zhTW', '裂鞭的秘密', '或許有人能夠解開這個謎團，$r。謠傳科瓦迪爾人讓一些納迦女祭司苟活下來，關在神殿中。高階女祭司薇迦一定很樂意把那些科瓦迪爾不速之客給趕走。或許她能告訴你更多石板文字的意義。', '在北風凍原的裂鞭遺跡找到薇迦。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11623 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11623, 'zhTW', '拜訪監管者', '狩法獵人部隊的領袖是一個名叫監管者殷希維俄的可怕生物。我的族人無數個世代以來狩獵土地和海洋中的野獸，但我卻從來沒有見過像監管者那樣的東西。$B$B他就在礦場邊緣上空的其中一個飛行圓盤，監管他們所有的活動。$n，我只能相信是先祖們送你來解救我們，我也希望你能幫我永遠地把那些狩法獵人給逐出礦場。', '冷岩礦場郊區的伊塔魯克要你殺死監管者殷希維俄。', '', '去找北風凍原的伊塔魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11625, 'zhTW', '納茲贊恩的三叉戟', '五百年前，艾薩拉將一個名為萊維羅希的生物囚禁在海底。現在那些野蠻人居然想要破壞我們女王的努力!$B$B他們佔領了我們的城市，然後犧牲我的同胞來喚醒他!當他們把納迦都殺光了，他們就開始去抓巨牙海民。他們的靈魂將無法安息!$B$B我會幫你，因為平息我的復仇是一條漫長的道路。他們的隊長，拉格納就在裂鞭東北部的深處。他帶著一根黃金三叉戟。把它帶來給我!', '裂鞭的薇迦要你前往裂鞭遺跡的東北部。殺死拉格納‧德拉卡路德之後，把納茲贊恩的三叉戟交給她。', '', '去找北風凍原的薇迦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11626 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11626, 'zhTW', '特使', '在萊維羅希被囚禁的時候，拉吉‧納茲贊恩是裂鞭的皇帝。艾薩拉本人親自祝福過他的三叉戟，如果那隻野獸真的逃脫的話，三叉戟也應該能殺死它。$B$B現在你持有它了，$r。儘管它令我作嘔，但我終將向那些野蠻的巨人復仇。$B$B把三叉戟帶到裂鞭之下的深處。你會發現萊維羅希在海底休眠。將三叉戟深深地插入他的血肉中!然後向派你來的人回報，我不想再看見你了。', '在裂鞭遺跡北方邊緣的水底，到漂浮冰山之下尋找萊維羅希。使用納茲贊恩的三叉戟殺死他。然後回到裂鞭水岸的北邊找卡魯克。', '', '去找北風凍原的卡魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11627, 'zhTW', '沸點', '喔，這正是想要的情報:你們『先知』的下落與狀況。他也不是什麼都知道嘛，無法避開降臨在自己頭上的麻煩。$B$B總之，我會告訴你取得那些情報的方法。但首先，你得先替我做些事情。$B$B我相信你應該在南方見識過了水與火之間的戰爭。『沸滾』持續地讓『翻湧』的水池沸騰，他們兩個已經戰鬥了許多年。$B$B前往焦炭高崗和極熱之池，讓他們兩個停止爭吵。', '英波里安要你把『沸滾』和『翻湧』打倒屈服。等他們屈服之後再回到艾卓納斯遺跡找她。', '', '去找北風凍原的英波里安。', '希默爾已臣服', '邱恩已臣服', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11628 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11628, 'zhTW', '天譴裹布', '在東北方隱約可以看見恩吉拉聖城，天譴軍團在北風凍原上的基地。就在它的高牆之後，天譴軍指揮官派出他的奈幽蟲族包圍了我們。$B$B一直防守下去只會害死我的同胞，但我的顧問們卻意見紛歧。德姆只會盲目的衝鋒，賢者艾睿則偏好隱匿的行動。$B$B聖城污染了附近的土地與當地的生物。艾睿相信天譴長毛象的毛皮可以作為掩蔽，用以隱藏一個滲透者。', '坦卡雷村的冬風酋長要你帶回5個天譴長毛象皮。', '', '去找北風凍原的冬風酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11629, 'zhTW', '回去找靈語者', '你已經做到我請求你的事情，我這就把你想要的拿給你。$B$B將元神交還給博格洛克前哨的靈語者。如果她夠睿智，她就會知道一個儀式，能讓你獲得你所尋覓的消息。', '將英波里安的元神帶給博格洛克前哨的靈語者嗥牙。', '', '去找北風凍原的靈語者嗥牙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11630 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11630, 'zhTW', '惡土', '透過治癒聖城外圍的荒蕪土地，賢者艾睿認為她可以製造一種披風，讓大多數的天譴軍爪牙忽略你的存在。她說，你應該可以混入其中。$B$B她最好是正確的。這是我們唯一的收集情報與策劃反擊的機會。$B$B你應該可以在要塞的南邊和西邊挖到她要的土壤。等你收集完成之後再來找我。', '將8塊天譴污染土壤帶給坦卡雷村的冬風酋長。', '', '去找北風凍原的冬風酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11631 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11631, 'zhTW', '風之幻象', '拿去，$n，我將元神和你調整一致了。$B$B當我的風圖騰出現以後，放開你的靈魂迎向元神，並且全神貫注在先知厲行者的天命。$B$B風之靈無所不至;有幸你將能獲得預見的能力。', '在博格洛克前哨中嗥牙的圖騰，使用英波里安的元神施展儀式，以獲得有關於先知厲行者的消息。結束以後，再向靈語者嗥牙交談。', '', '去找北風凍原的靈語者嗥牙。', '已占卜先知格林渥克的命運', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11632, 'zhTW', '冷風帶來的...', '你拿到了依司瑞克斯的外殼碎片，並且瞭解到這不過是個開端。既使是現在你都感覺勝利非常的短暫?巫妖王肯定上千個像依司瑞克斯這樣的怪物，等著要被釋放來攻擊部落。$B$B帶著你的戰利品並且把它交給戰歌堡中的霸王薩魯法爾。他應該要知道你戰勝了一名強大的天譴軍成員。', '將依司瑞克斯的硬化殼交給戰歌堡的霸王薩魯法爾。', '', '去找北風凍原的薩魯法爾霸王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11633, 'zhTW', '混入其中', '賢者艾睿已經織好裹布了。帶著它前往恩吉拉聖城。在城裡披上它，就可以躲開天譴軍。這是我們刺探對方防禦工事和領導者的最佳機會。$B$B穿著披風去偵察聖城裡的三座尖塔。雖然這裹布可以讓你躲過大多數的天譴軍，如果你太靠近恩吉拉憎惡體，它們就會發現你。', '坦卡雷村的冬風酋長要你到恩吉拉聖城裡穿上灌魔天譴裹布，然後偵察鮮血尖塔、苦痛尖塔、以及凋零尖塔。', '', '去找北風凍原的冬風酋長。', '已偵察腐朽尖塔', '已偵察血之尖塔', '已偵察痛苦尖塔', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11637 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11637, 'zhTW', '卡甘尼蘇', '在我那為數不多的蠻兵軍力被殺之後，我被拖行至此並獻祭般的被處死。犯下此舉的狗頭人稱作卡甘尼蘇。$B$B你雖然擊敗了他的薩滿助手，但是我的靈魂仍然被拴縛在這裡。他殺了我之後，用我的屍身製造了一尊神像，用以禁錮我在這。卡甘尼蘇藉此習得我所全部所知的薩滿之道。$B$B你必須從他身上將這尊神像奪回來，並且在我的靈魂上使用。卡甘尼蘇就在附近的洞穴裡。$B$B唯有如此方能真正解放我。', '找回卡甘尼蘇的神像並且在先知厲行者的殘骸上使用。你必須將神像交給瑪格默斯中的先知厲行者之靈。', '', '', '已釋放先知格林渥克', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11638 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11638, 'zhTW', '交回我的殘骸', '$n，既然我的靈魂已然被釋放，你願意幫助我將我的殘骸帶給靈語者嗥牙呢？殘骸被放置在我身下的地面上。$B$B我感應到靈語者還在西方博格洛克前哨中，那是我最後看到她的所在。', '將安息在先知厲行者之靈底下的先知厲行者的殘骸遞交給博格洛克前哨的靈語者嗥牙。', '', '去找北風凍原的靈語者嗥牙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11639 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11639, 'zhTW', '向瑪格默斯報仇', '霸主下令不准薩滿治療我的傷，他說要我從中學得教訓，並且為我的失敗好好反省。$B$B你可以替我，以及在瑪格默斯送命的弟兄報仇!$B$B我清楚靈語者要你去把先知救出來。$B$B去吧，$c，就在東方...殺掉猛瑪象人和他們的狗頭人走狗。奪回崗哨的榮耀!', '殺了10個瑪格默斯薩滿，5個瑪格默斯採獵者，3個瑪格默斯粉碎者，以及3個瑪格默斯瑞卡的配偶。完成後，回到博格洛克前哨找甌爾卓希。', '', '去找北風凍原的甌爾卓希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11640 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11640, 'zhTW', '真言', '在你描述的尖塔中居住著天譴軍團領導主要的部將，高階祭師。他們不只指揮著天譴軍團，還擁有鑰匙可通往上方的亡域和他們的主人。$B$B如果我們無法找到並擊敗他們的頭目，我們將被源源不絕的天譴爪牙攻陷。不管德姆有多想要與敵人開戰，我沒辦法讓我的人民失去防衛。這任務就交給你了，$n，去殺了這些高階祭師並取得他們手上的卷軸。', '帶著高階祭司納菲賽特的卷軸，高階祭司塔烈卡的卷軸，和高階祭司安杜拉斯的卷軸給坦卡雷村的冬風酋長。', '', '去找北風凍原的冬風酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11641, 'zhTW', '英勇一擊', '從一開始的時候，我就勸告過冬風酋長應該要集結我們最強大的戰士，然後對敵人的基地展開攻擊。他不願意聽從我的建議，而寧願照著賢者艾睿的計畫，在周圍鬼鬼祟祟地活動。$B$B我不要再等了。如果冬風酋長膽小得不敢派出我們的戰士應戰，或許你願意向他證明直接的攻擊也可能會成功。衝進恩吉拉聖城，所把所有阻礙你的傢伙全殺光，$n。', '殺死15個恩吉拉食屍鬼和5個恩吉拉死靈法師，然後向坦卡雷村的德姆‧冰隱回報。', '', '去找北風凍原的德姆‧冰隱。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11643 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11643, 'zhTW', '莫布的氣動式坦克外鑽模夾具', '這些板手根本沒用，兄弟。我需要我的氣動式坦克外鑽模夾具好讓那些東西動起來!不幸的是，我把我的舊工具掉在臺地的另一邊了。就在獸欄旁邊的低矮小屋裡。你得幫我去拿來，因為我天殺的很清楚實在不應該靠近那些迷霧。$B$B喔對了，兄弟，要小心那些迷霧。就是那些迷霧把海岸給扯碎了。', '莫布要你找回他的氣動式坦克外鑽模夾具，他就在北風凍原的回聲海岸。', '', '去找北風凍原的莫布。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11644 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11644, 'zhTW', '超強力金屬板!', '我需要金屬來強化這些坦克!超強力金屬板散落在卡爾洛斯臺地以及海灣底部的各處。$B$B只不過在你去尋找金屬板的時候要小心。迷霧是...嗯...有侵略性的!這些迷霧佔據了臺地和鄰近的巨牙海民村莊。可憐的巨牙海民...', '莫布要你收集10個超強力金屬板，他就在北風凍原的回聲海岸。', '', '去找北風凍原的莫布。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11645 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11645, 'zhTW', '骯髒、發臭的極地狗頭人!', '那些骯髒、發臭的極地狗頭人…他們偷走了我所有的補給品！$B$B你問什麼是極地狗頭人？就跟一般狗頭人差不多，不過他們服侍猛瑪象人，照料他們的生活。我知道，這很奇怪！$B$B有人要幫幫我嗎？我知道那些卑鄙的東西偷走了我所有的東西。是我太傻，以為在簡易機場北邊整理貨物很好很安全。$B$B幫幫我，去北邊那個愚蠢的瑪格默斯。如果你能快點把我的東西給拿回來，我可以給你現金報酬！', '收集10個卡芙緹的貨物，帶回去給嘶軸簡易機場的卡芙緹‧顛鏈。', '', '去找北風凍原的卡芙緹‧顛鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11647 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11647, 'zhTW', '中和大鍋', '恩吉拉聖城中的瘟疫大鍋讓我十分擔憂，$n。顯然冬風酋長信任你的判斷以及你對我們敵人的瞭解。你願意在執行酋長計畫的同時，協助我處理聖城中的大鍋嗎？$B$B我準備了一根圖騰，它會攻擊並且中和大鍋中的東西。你只需要找出大鍋的位置，然後把圖騰插在附近就行了。我們每摧毀一樣天譴軍的武器，我們就離勝利更近一步。', '坦卡雷村的賢者艾睿要你使用她的圖騰去中和恩吉拉聖城中的東部大鍋，中央大鍋和西部大鍋。', '', '去找北風凍原的賢者艾睿。', '東方坩堝已淨化', '中央坩堝已淨化', '西方坩堝已淨化', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11648 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11648, 'zhTW', '說服的藝術', '慶幸你在這裡，$r。$B$B瞧，即使在這種非常時期 - 祈倫托的行誼準則對我們採取「極端」的手段十分不滿。$B$B但是，你是個局外人，不受此限制，你可以因應傳回的消息做出任何必要的手段。$B$B做你該做的，我們得馬上知道伊娃諾女士被關在何處!$B$B我會忙著整理這些書架，喔，對了，也許你會覺得這個老東西很有用處...', '琥珀岩臺的圖書管理員諾曼提司需要你對被囚禁的碧晶巫士使用神經刺針，直到他吐露伊娃諾女士的所在地。', '', '去找北風凍原的圖書管理員諾曼提司。', '已審問囚犯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11649, 'zhTW', '狂怒微粒', '雖然，他們的小爭執我們已經解決了，仍然還要幫助你和你的靈語者。$B$B如你所見，我的僕從們被火水元素的戰爭所激怒，而短時間內不會有任何的改變，但是，你可以從中取得利益。$B$B為了要幫助你，我們需要他們身上的微粒。深入廢墟裡面，從這些暴風身上取回微粒吧。', '收集5個暴風雨微粒，然後把它們交給艾卓納斯遺跡的英波里安。', '', '去找北風凍原的英波里安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11650 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11650, 'zhTW', '只要再幾樣東西...', '你可能已經注意到了，我們將簡易機場建造在一處猛瑪象人洞穴的南方邊境!$B$B<卡芙緹偷偷的說了幾句挖苦嘶軸的話。>$B$B老頭子要我負責對以下的情況找出一個...呃...有創意性的解決方式:如果我們不盡快解決他們的話，他們將會來到這裡，將我們撕成一塊塊!$B$B這就是你要做的事情。我要幫我弄來這張購物清單上所有的東西。拜託了。', '收集卡芙緹的工具，一個過載電容器，以及一把洛克那爾的砂粒。將這些東西送去給嘶軸簡易機場的卡芙緹‧顛鏈。', '', '去找北風凍原的卡芙緹‧顛鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11652 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11652, 'zhTW', '納森平原', '一旦你準備好了，就跳上一台坦克，開到東南方的納森平原去。$B$B使用坦克的武裝消滅天譴軍團。如果你被擋住了，「肉鋸」可以把他們撕碎，然後就用地雷解決他們!如果你找到我們的士兵，直接載走!最後一點，油箱散佈在平原各處。$B$B試著接近中央的建築物，然後觀察那裡到底發生了什麼事。$B$B如果你把這些全部做完並且還活下來，就直接去找地獄吼!', '駕駛部落攻城坦克到納森平原摧毀100個天譴士兵，並救援3個受傷的戰歌士兵。你同時必須查出天譴軍團攻擊領導人的身分。成功之後，向戰歌堡的卡爾洛斯‧地獄吼報告。', '已辨識天災首領', '去找北風凍原的卡爾洛斯‧地獄吼。', '天災單位已殲滅', '已救出受傷的戰歌士兵', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11653 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11653, 'zhTW', '哈...你現在可沒那麼大囉!', '這樣就可以應付她了，老大!接下來，我要你這麼做...$B$B帶著我的光束槍，朝著北邊前往瑪格默斯。如果我們想要有機會對抗那些怪物，我們必須減小他們的體型...就這麼辦。$B$B為了評估光束槍的效能，我要你在猛瑪象人身上的光束槍效果結束之前殺掉牠們。任何粉碎者或是配偶都可以，不過放過那些後代吧...他們還很小，不用擔心。', '在5隻瑪格默斯粉碎者或瑪格默斯瑞卡的配偶身上檢測卡芙緹的超進階初體版微縮光束槍。在完成後，回到嘶軸簡易機場找她。', '', '去北風凍原找菲茲蘭克機場的機靈鬼沃比斯波基。', '測試卡芙緹的光束槍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11654 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11654, 'zhTW', '鮮血尖塔', '在你調查血瓶時，你發覺到裡面的東西似乎依舊溫熱。受害者一定才剛剛被放血，說不定還活著。$B$B天譴軍為什麼要這些鮮血？他們過去從不在意活著的囚犯。或許等你找到這些血液的來源，你就能發現天譴軍團的計畫。', '調查鮮血尖塔尋找更多關於新鮮的血瓶的情報。', '', '去找北風凍原的雪地追蹤者古魯姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11655 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11655, 'zhTW', '進入迷霧', '穿過迷霧前往北方，你會找到卡爾洛斯臺地。往南則是我家鄉的遺址，帕雷亞。這兩個地方都遭到一個被稱為科瓦迪爾的古老勢力所掠奪。$B$B這些可怕的野蠻人毫不留情地殺死了我所有的族人，然後把你的同胞往內陸逼。$B$B所有帕雷亞剩下的東西都是我們巨牙海民的財產，但卻被科瓦迪爾人給帶走了。儘管我們並不是好復仇的種族，但正義一定得伸張。巨牙海民的遺物一定回到我手上。進入迷霧幫我找到它們。', '帕雷亞的華特要你殺死科瓦迪爾人，收集8個巨牙海民遺物。他就在北風凍原的回聲海岸。', '', '去找北風凍原的帕雷亞的華特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11656, 'zhTW', '焚火示眾', '巨牙海民的魔法跟你同胞的薩滿法術很類似。但我們侍奉元素的方法不同，但我們能夠呼喚的力量是一樣強大的。$B$B<華特在你面前揮舞著一根火炬般的短杖。>$B$B我希望你帶著這根巨牙海民火炬回到迷霧中並且攻擊科瓦迪爾船艦。你會發現他們有三艘船在迷霧之中，停靠卡爾洛斯臺地的碼頭，就在北方不遠，還有一艘停在帕雷亞的海岸，就在南方。放把大火把他們的船全給燒了!讓所有人都看見!', '回聲海岸的帕雷亞的華特要你使用巨牙海民火炬燒毀在帕雷亞與卡爾洛斯臺地的科瓦迪爾船艦。你得摧毀以下的船隻:巨蛇之喉、科‧德拉卡、伯爾之錘和伯爾之砧。', '', '去找北風凍原的帕雷亞的華特。', '巨蛇之顎已摧毀', '庫爾達卡爾已摧毀', '波爾的鐵鎚已摧毀', '波爾的鐵砧已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11657 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11657, 'zhTW', '接住火炬', '既然你已經學會投擲火炬了，讓我們看看你接不接得住它!$B$B拿著這堆未點燃的火炬。去營火那邊然後把火炬高高地丟向空中!然後在火炬落地之前接住它...然後再把它丟回去!連續接住四個後，就回來找我。$B$B小心點!如果它們掉到地上可是很危險的!所以千萬別失誤!要是你真得失誤了，那你就得回到營火那再重新開始一次。祝你好運!', '連續接住4根火炬，然後跟吞火者大師談話。', '連續接住4支火把', '去找吞火者大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11658 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11658, 'zhTW', 'B計畫', '好啦，別驚慌!光束槍雖然沒有成功，但是我們有其他配套措施。$B$B<卡芙緹揉擰著她的手指。>$B$B我們要分散簡易機場的注意!為了要能成功，我們得先做一些準備。$B$B<顛鏈朝你上上下下打量一番。>$B$B就在西邊，鋼顎商隊，他們很愚蠢的從坦卡族的墓園抄捷徑，想當然爾被喚醒的靈魂宰了。$B$B前往那裡，從那些死掉的獸人身上弄一些外裝來，啊對，還有他們的旌旗也一併帶回來。', '收集10件戰歌外裝和1根戰歌旌旗。將它們帶回去給嘶軸簡易機場的卡芙緹‧顛鏈。', '', '去找北風凍原的卡芙緹‧顛鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11659 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11659, 'zhTW', '粉碎寶珠!', '他們...抽囚犯的血...放在...那些球中。$B$B<古魯姆短暫的閉上了眼，將頭靠回來。>$B$B血...被帶上了亡域...當成血親王的食物...$B$B<古魯姆倒抽了一口氣。>$B$B答-答應我...你會...摧毀集血...之球...傳話給...朱奈克。$B$B<雪地追蹤者失去了意識。>', '摧毀5個集血之球並回報坦卡雷村的雪地追蹤者朱奈克。', '', '去找北風凍原的雪地追蹤者朱奈克。', '血球已擊碎', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11660 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11660, 'zhTW', '上古海員號角', '一個名為歐拉布斯的科瓦迪爾上尉指揮著最初對帕雷亞人民的侵略。他監看著兩個村落的毀滅，然後消失不見。$B$B早前有個傳聞提到歐拉布斯贈送了科瓦迪爾織霧者一個號角。這個號角可在有需要時用來召喚他。$B$B我們需要從科瓦迪爾織霧者身上取得這個號角，並召喚歐拉布斯。如果把他給摧毀，這些野蠻人或許就會撤退。$B$B找出帕雷亞的織霧者，就在南邊。', '帕雷亞的華特要你將上古海員號角帶給他。他就在北風凍原的回聲海岸。', '', '去找北風凍原的帕雷亞的華特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11661, 'zhTW', '『舵手』歐拉布斯', '帶著號角前往西方的戰歌碼頭。走到碼頭的底端，然後吹響號角。那個聲音將會喚醒歐拉布斯。$B$B殺死那個污穢的野獸，然後回來找我!', '回聲海岸的帕雷亞的華特要你使用上古海員號角召喚『舵手』歐拉布斯，並且殺死歐拉布斯。', '', '去找北風凍原的帕雷亞的華特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11664, 'zhTW', '逃出迷霧', '我可以聽到外面的迷霧生物。他們的鬼叫聲快把我逼瘋了，不過我可不敢試著逃離這裡。況且，我還能逃去哪呢？即使我逃得了一時，也難保不會跟其他人一樣被他們追上並且落得被處死的下場。$B$B我想知道，這場迷霧涵蓋的範圍有多廣呢，陌生人？它已經籠罩這整個大陸了嗎？$B$B你願意幫助我試著逃離這陣迷霧嗎？我想我可以引領我們回到我父親身邊。我仍感覺得到他的生命特質。他就在附近。', '跟隨著小穆圖走出迷霧。成功拯救小穆圖後，與穆圖長者談談。', '穆圖已救出', '去找北風凍原的穆圖長者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11665, 'zhTW', '城裡的鱷魚', '你好，$g小夥子:姑娘;。我很高興你願意停下來和這個老人聊天 -- 家裡最近出了一些狀況。$B$B一個旅行商人把一窩鱷魚寶寶賣給了容易受騙的孩子。鱷魚是狂野的獸類，許多已經逃走，潛伏在城裡的下水道中。$B$B拿出你最堅固的釣魚竿吧，在暴風城或是奧格瑪垂下魚標，把一隻小惡魔帶回來給我。我急著想看看這些鱷魚寶寶。', '把一隻鱷魚寶寶帶給老人巴洛。你可以在撒塔斯城東北邊的泥濘湖畔找到他在那釣魚。', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11666, 'zhTW', '魚餌強盜', '你一定知道有關金色淡水小魚的事--牠們遍佈於所有泰洛卡森林的河中，對牧師來說是一道美味佳餚。不過這裡有個你從來都沒聽說過的:黑鰭小魚。$B$B這種魚是出名的狡詐且難以捕捉。你得在最佳的緊要關頭才能拉動你的釣線，因為牠們在咬住餌之前都很小心翼翼。$B$B將你的魚線丟入泰洛卡森林的河中，並將一尾黑鰭小魚帶來給我。別在湖中垂釣，黑鰭小魚只生長在流動的水中。', '帶一尾黑鰭小魚給老人巴洛。你可以在撒塔斯城東北邊的泥濘湖畔找到他在那釣魚。', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11667 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11667, 'zhTW', '逃脫的那個', '微光泥鰍是一種在納葛蘭水域中非常靈活的底棲魚。他們一生都在不斷成長，並以戰士的別稱聞名。$B$B許多年前，我抓到一隻我認為是世界上最大的泥鰍……直到牠咬斷我的魚線並且掙脫。$B$B像你這種程度的漁夫是不需要什麼指點 -- 你的命運正等在納葛蘭的湖畔。', '抓到世界最大的泥鰍，然後帶給老人巴洛。你可以在撒塔斯城東北邊的泥濘湖畔找到他在那釣魚。', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11668, 'zhTW', '抓蝦子一點都不簡單', '贊格沼澤的湖中擁有豐富的魚產。懷疑過他們以什麼為食嗎?$B$B就是蝦子。巨型清水蝦。洛克跟我說你可以用蝦子煮出無數的菜色。$B$B但是蝦子實在太小了，沒辦法用釣線來釣。所以這有個點子:把浮腫的倒刺鰓鱒魚剖開，夠幸運的話你會在當中找到一兩隻蝦子。', '帶10隻巨型清水蝦給老人巴洛。你可以在撒塔斯城東北方找到他在泥濘湖畔垂釣。', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11669, 'zhTW', '魔化之血肉片', '這個老人就快要去打獵了。我要去打敗艾薩拉海岸外的一隻巨大鯊魚。$B$B事情就是，我需要一種在水中也不會溶解的毒藥。想要製作出那樣的東西，我會需要一種腺體，來自於一種毒魚:魔化之血鯛魚。$B$B像這種邪惡的魚種只存活在地獄火半島和影月谷的惡水中。帶條大魚給我，我就會是個快樂的老人了。', '帶一尾可怕的魔化之血鯛魚給老人巴洛。你可以在撒塔斯城東北邊的泥濘湖畔找到他在那釣魚。', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11670 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11670, 'zhTW', '是獸人乾的！真的！', '我費了好大勁才將這些衣料拼湊成一件戰歌獸人偽裝。別擔心，我在衣料中新增了去年萬聖節剩下的好東西，它應該非常結實。啊，我真是個天才！$B$B喏，袋子裡裝著獸人偽裝和你取回的那面旗幟。帶上它轉至獁格莫斯，殺死猛獁人的酋長獁格莫斯雷加。$B$B你必須在偽裝狀態下將旗幟插在獁格莫斯雷加的屍體上，令猛獁人的注意力轉移到戰歌獸人身上。', '偽裝成戰歌獸人，將戰歌旗幟插在獁格莫斯雷加的屍體上。完成任務後返回菲茲蘭克機場，將偽裝還給機靈鬼沃比斯波基。', '', '去北風凍原找菲茲蘭克機場的機靈鬼沃比斯波基。', '將戰歌旗幟插在獁格莫斯雷加的屍體上', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11671, 'zhTW', '和時間賽跑', '所以這是真的。她在他們手中。$B$B事情該怎麼解決看來是很清楚了，$r。她「會」被救出來。$B$B我必須在這裡支援拯救的準備行動。我會再找你來;這次先去取得監獄的鑰匙。我們目前所了解的就是，這個沙爾倫因其完美無缺的護盾保護而不會受到傷害。$B$B為此我們已經定做了一個特別的炸藥，可以解除她的這層保護，讓你有辦法執行你的職責。等你取得鑰匙後，回來找我。$B$B快點，$n。伊娃諾女士正在受苦!', '琥珀岩臺的唐納森派你使用碧晶護盾炸彈關閉碧晶哨點的護盾。接著打敗沙爾倫並取得她持有的鑰匙。', '', '去找北風凍原的圖書管理員唐納森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11673 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11673, 'zhTW', '快把我弄出去！', '我知道他們遲早會送人來…結果卻遲了這麼久。$B$B我本來是想利用一下這些極地狗頭人的，但是他們的薩滿卡甘尼蘇卻決定不如把我做成瑪格默斯瑞卡的點心。$B$B等等…你說什麼？！你不是他們派來的？！$B$B你…你你…是說他們把我給忘了？！$B$B好吧，你在這才是要緊的事情。$B$B只要你打破這條鐵鍊，我們就一起回去機場，然後你可以告訴嘶軸我安全回去了。$B$B那當然，如果他還記得我的話。', '將邦克‧電環護送到安全地點，並且向嘶軸簡易機場的嘶軸‧滿閥回報。', '邦克·托格佛特已護送至安全處', '去找北風凍原的嘶軸‧滿閥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11675, 'zhTW', '合宜的死', '垂死獸穴的猛瑪象人被捲入了一場瘟疫。我們一定要找出原因，但首先我們得結束他們的苦難。$B$B$r，你必須要前往北方攀上我們前面的坡地，然後盡可能地消滅那些可憐的生物。', '消滅10隻染疫猛瑪象人，然後向垂死獸穴的賢者高臺回報。', '', '去找北風凍原的賢者高臺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11676, 'zhTW', '慈悲的自由', '他們沒殺死的士兵就被關在散佈於農地上的籠子裡。經過幾次偷竊行動，我們已經設法找到了幾隻鑰匙，不過我們無法順利的靠近任何囚犯。$B$B我們需要你的『天賦』來保護那些鑰匙並釋放囚犯。痛擊這些死靈領主和畸形者，拿走他們的鑰匙。使用那些鑰匙來釋放天譴囚犯。', '戰歌農場前哨的巡影者卡納利亞斯要你去釋放5個天譴囚犯。', '', '去找北風凍原的巡影者卡納利亞斯。', '天災囚犯已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11677, 'zhTW', '阻止瘟疫', '我相信瘟疫是由上方洞穴中的某個東西所引起的。$B$B$c，我要你拿著這些種子。通常我都用它們來抵禦天譴軍團，但它們也能用來消解這些獸穴中所進行的骯髒勾當。$B$B找到瘟疫的來源，然後把種子丟進去。', '賢者高臺就站在垂死獸穴的南方，要求你使用高臺的淨化種子將垂死獸穴的瘟疫大鍋中和。', '', '去找北風凍原的賢者高臺。', '瘟疫坩堝已中和', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11679 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11679, 'zhTW', '重鑄鑰匙', '', '唐納森希望你去和琥珀岩臺的瑟利斯塔茲談談。', '', '去找北風凍原的瑟利斯塔茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11680 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11680, 'zhTW', '起飛', '鑰匙重新鑄造了。$B$B現在，注意聽我的忠告，$r。努力完成或是至死方休，如果我的飛龍身上掉落任何一片鱗片的話，我會算在你個人的帳上。$B$B現在，閃吧。', '等你準備好釋放伊娃諾時，將沙爾倫的鑰匙交給戰爭法師安辛。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11683 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11683, 'zhTW', '墜毀的亡域', '我們只能夠推測西邊那個墜毀的亡域裡面還滿是天譴軍。$B$B當你到塔爾拉瑪斯去的時候，$c，我要你殺死你在亡域和周邊的池子找到的巫妖王僕從。', '到塔爾拉瑪斯和膿瘡之池去摧毀任意20個天譴軍，然後，向垂死獸穴南方的賢者高臺回報。', '', '去找北風凍原的賢者高臺。', '塔拉瑪斯的天災已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11684, 'zhTW', '偵察坑道口', '你可以感覺到土地的震動嗎？$B$B天譴軍團的奈幽蟲族正在地面深處下活動著。他們已經出現在水泉原野的西南邊，騷擾著冬風酋長派出的巡邏隊。$B$B<這位坦卡族長者遞給你一份磨舊的地圖。>$B$B或許單獨一人可以成功到達巡邏隊無法前往的地方。帶著這份地圖前往水泉原野，並標記下奈幽蟲族坑道口的位置。', '坦卡雷村的主父瑪哈要你使用水泉原野地圖去紀錄南部坑道口，西北部坑道口，以及東北部坑道口的位置。', '', '去找北風凍原的主父瑪哈。', '標記南方坑洞位置', '標記東北方坑洞位置', '標記西北方坑洞位置', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11685 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11685, 'zhTW', '元素之心', '現在我們知道奈幽蟲族坑道口的確切地點了，我們可以破壞它們，停止天譴軍團進攻，並嚴重削弱他們的軍力。馴風者巴拉知道有個方法可以控制元素，進而摧毀奈幽蟲族目前使用的通道，不過她會需要你的幫忙。$B$B村子的東南方，接近冰凍之境另一邊的海岸，你可以找到一個由冰凍土元素控制的區域。這些元素的心臟正是馴風者巴拉需要的東西。', '帶5個元素之心給坦卡雷村的馴風者巴拉。', '', '去找北風凍原的馴風者巴拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11686 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11686, 'zhTW', '戰歌農場', '根據盧瑟的紀錄，天譴軍團目前使用這個地方做為那些怪物的培訓地，就是你在原野上看到笨重行走的那些東西。$B$B<艾寇里斯顫抖著。>$B$B那些怪物曾經是獸人...牛頭人...$B$B在想出一個計畫前，我們需要更多資訊。我要你去調查三個天譴軍團頻繁行動的地點:這裡西南邊的戰歌穀倉，正西邊的托普的農場，及北邊的舊戰歌屠宰場。$B$B一旦你完成了偵察，就回來找我。', '戰歌農場前哨的巡影者艾寇里斯要你去偵察戰歌穀倉，托普的農場，及戰歌屠宰場。', '', '去找北風凍原的巡影者艾寇里斯。', '偵察戰歌穀倉', '偵察托爾普的農場', '偵察戰歌屠宰場', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11687, 'zhTW', '博士與巫妖領主', '有兩個人...一定...得死。$B$B就是上面的...博士還有...巫妖領主。去找到他們...殺掉他們...在...$B$B...一切都...太遲...以前...', '殺死剃刀獰笑博士和巫妖領主冽冬。接著回到北風凍原的死亡獸穴南邊找高臺賢者。', '', '去找北風凍原的賢者高臺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11688 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11688, 'zhTW', '該死的不潔豬隻', '看看牠們!我這些漂亮的科多獸無力去保護自己遠離那些不潔的豬隻!我需要你替我爭取些時間，$r。我想我可以治癒生病的科多獸，不過你得避免讓那些骸豬靠近牠們，否則將沒有治癒的餘地了!$B$B到外面去，送那些豬入土為安 - 永遠!', '戰歌農場前哨的農夫托普要你去殺了10隻骸豬。', '', '去找北風凍原的農夫托普。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11690 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11690, 'zhTW', '帶牠們活著回來', '帶著這個坐騎銜鐵，$n。你會注意到我在護套上放了一個微型機器藥劑師。那東西將會馬上在科多獸咬下時將感染治癒。一旦你治癒牠們，你會需要將牠們騎回家。牠們會很虛弱，所以你需要慢慢的引導他們回到這裡。$B$B將我的寶貝們帶回來給我，$n!$B$B最後一件事，你只有10分鐘!那就是銜鐵裡解藥的持續效果。', '戰歌農場前哨的農夫托普要你去營救8隻受感染的科多獸。', '', '去找北風凍原的農夫托普。', '已救出科多獸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11691 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11691, 'zhTW', '召喚艾胡恩', '我和手下的薩滿已經聚集我們的力量，為了接下來和冰霜領主的戰鬥做好準備。$N，你將會是大地之母的拳頭。$B$B帶著這根熔岩圖騰。對東北方的冰石使用它。艾胡恩正在透過那個石塊引導他的力量;我們希望圖騰能夠打斷他並且切斷他和元素位面的連結。$B$B如果我們夠幸運的話，那或許我們就能打敗他。$B$B做好準備，$n。如果艾胡恩和我們正面衝突，他將會非常瘋狂與憤怒。', '將陶土議會熔岩圖騰帶到冰石旁邊。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11693 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11693, 'zhTW', '喔太好了...染疫猛瑪象人!', '汀基和我來到這裡追蹤一些老猛瑪象人。很明顯的，那些洞穴裡就是他們赴死之地。$B$B當然，我們並不知道他們是在裡頭是怎麼染上瘟疫的。我們不能讓染疫的生物四處遊蕩;太不健康了。$B$B唉呀，為什麼你不趁我想出我下一步該怎做前先去解決一些染疫的生物呢？', '殺死10個染疫猛瑪象人，接著回到垂死獸穴的南方找碧西‧扭柄。', '', '去找北風凍原的碧西‧扭柄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11694 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11694, 'zhTW', '洞穴裡的古怪', '所以呢，雖然你已經處理了那些染疫野獸，但是我還是偷看了一下洞穴的內部。$B$B裡頭的教徒們正在進行瘟疫化!$B$B他們將某種有毒的混合物放在大鍋中釀煮著。我有一種平常用來解毒的粉末，我將它混合了其它的東西。我想這將可中和他們的釀煮物!$B$B帶著這個粉末前往其中一個洞穴試試看有沒有效。', '潛伏在垂死獸穴南方的碧西‧扭柄要你對垂死獸穴瘟疫大鍋使用碧西的抑制粉末來中和它。', '', '去找北風凍原的比希·鉗柄。', '中和瘟疫大鍋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11695 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11695, 'zhTW', '元素之怒號角', '我可以用這堆無生命力的石頭製作出一個元素的模樣，但是讓它活起來則是完全不同的一件事。因此，我們需要幫助，還需要一點運氣。$B$B傳說中提到一件名為元素之怒號角的古老神器，由一位偉大的坦卡族英雄所發現的。我會借你這個傳說的複製卷軸。我不知道這個傳說是不是真的，但這是我們最好的選擇。如果傳說是對的，這個號角有一部份就位於環繞著村子西南邊和北邊的氾濫平原上。', '從波嚥酋長和汨驚酋長身上取回號角的下半部和號角的上半部，並將這兩樣東西帶給坦卡雷村的馴風者巴拉。', '', '去找北風凍原的馴風者巴拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11696 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11696, 'zhTW', '艾胡恩就在這裡!', '$n，你的出現真是個恩賜。艾胡恩就在那些洞穴之中，為他的攻擊積蓄力量。陶土議會已經派人出發了，但單靠他們是無法擊敗艾胡恩的。探索吧，$n。找到我們陶土議會的薩滿，和他們的領袖魯瑪·天空之母談談。或許加上你的力量，我們能在一切太遲之前打倒艾胡恩。', '在奴隸監獄中找到魯瑪·天空之母。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11698 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11698, 'zhTW', '不如徹底消滅天譴軍團', '如果那些洞穴上方的教徒們可以在這場破壞中存活下來，那麼只能假定西邊那個倒坍的亡域當中仍充滿著天譴軍團。前方的池子也一定滿滿的都是天譴軍！$B$B雖然你人在塔爾拉瑪斯，$c，你覺得你可以殺光所有在那發現的巫妖王奴僕嗎？', '摧毀20個位於塔爾拉瑪斯和膿瘡之池的天譴軍，不限種類。接著，回到北風凍原的垂死獸穴正南方找碧西‧扭柄。', '', '去找北風凍原的比希·鉗柄。', '摧毀塔爾拉瑪斯的天譴軍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11699 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11699, 'zhTW', '我被困在這個該死的籠子...不過關不了太久了!', '教徒們使用魔法將我關進這個籠子裡，而且這籠子還沒有門。他們一點都沒想到我可是簡易機場的首席傳輸工程師耶！$B$B有了你的協助，以及一點點費力的工作，我不會在這裡待太久的。$B$B我需要從食屍鬼身上取得一個引擎核心水晶，從他們的醫生身上取得一個魔法迴轉儀，從位於頂端的巫妖領主身上取得一個導引天譴石。$B$B有了那些東西，我應該能夠做出一個傳送裝置回到嘶軸那，以地精的方式逃走！', '收集一個引擎核心水晶，一個魔法迴轉儀，以及一個導引天譴石。將這些帶到塔爾拉瑪斯交給汀基‧芯哨。', '', '去找北風凍原的汀基‧芯哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11705 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11705, 'zhTW', '愚蠢的努力', '真是瘋狂。他們如何能夠要求我們對付一個天譴死靈領主及一隊不知數目的爪牙呢?$B$B<蓋特利嘆了一口氣。>$B$B如果艾寇里斯派你過來，那他一定是認為你身懷眾多本領。或許你會祈求今天能發生奇蹟，嗯?$B$B當你準備好，我們就進行襲擊，並對付瓦瑞達斯。$B$B如果我們能夠不損一兵一卒的解決這一團混亂，就將情況回報給戰歌堡的地獄吼。', '協助蓋特利擊敗戰歌農場的『剝皮者』瓦瑞達斯。完成後回報給卡爾洛斯‧地獄吼。', '已擊敗剝皮者瓦里杜斯', '去找北風凍原的卡爾洛斯‧地獄吼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11706 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11706, 'zhTW', '崩壞', '我已經使用這個元素之怒號角建立並約束住艾魯威斯。當你站在接近水泉原野最南邊的坑道口時，他將會回應號角的召喚。$B$B艾魯威斯釋放的震動應該會崩壞奈幽蟲族的通道並終結他們左右兩翼的攻擊。要是奈幽蟲族的指揮官在震動後現身我也不會感到訝異。如果通道的崩壞無法逼退他們的攻擊，那麼擊敗他們的頭目則一定會讓他們撤退。', '坦卡雷村的馴風者巴拉要你使用元素之怒號角崩潰奈幽巴坑道口，並擊敗克萊克希斯克領主。', '', '去找北風凍原的馴風者巴拉。', '', '納魯比坑道已崩塌', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11708 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11708, 'zhTW', '機械地精', '既然你都在這了，該是我告訴你事情由來的時候了。$B$B在你聽完我的故事後，到外面去找我的副手，金基‧翼果。她將會處理從開始到結束這段期間所有的事情。', '聽取嘶軸‧滿閥的故事，然後去嘶軸簡易機場找金基‧翼果。', '已聆聽嘶嘶剎車的故事', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11710 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11710, 'zhTW', '這個運輸是怎麼回事？', '東邊到處散落著備用零件，沸水池、水泉原野...到處都是，真見鬼了，說不定連幫浦站都是。幫我帶一些回來。也許我有辦法讓外向的傳送正常運作，當然最好事能讓內向的傳送穩定。$B$B我痛恨看到另一場意外...', '收集15個嘶軸的備用零件，然後送交給嘶軸簡易機場的莫爾斗‧旋輪。', '', '去找北風凍原的莫爾斗‧旋輪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11711 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11711, 'zhTW', '膽小鬼貨運...30分鐘內送達否則免費', '每過去一天，我們都會在大門邊看到更多的逃兵。我們連關住那些蛆蟲的牢房都不夠了。尤其是我們還得讓那些豬高興。$B$B<諾克一邊笑，一邊發出豬叫。>$B$B我要你押解其中一個膽小鬼到東邊的十字路口去，然後發射信號彈。他們看到信號之後會派出一位隊長，來接管那個懦夫。$B$B等你完成押送之後，向東邊道路的斥候敦苟克回報。', '護送聯盟叛逃者到戰歌堡東邊的十字路口，然後發射你的戰歌信號槍通知聯盟。等你將聯盟叛逃者送到目的地之後，向斥候敦苟克回報。', '聯盟逃兵已送達', '去找北風凍原的斥候敦苟克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11712, 'zhTW', '再詛咒', '如果你有聽老頭子講，你就知道我們外頭有不少被轉化的地精。他們被齒輪大師梅卡佐德注射了一種東西把『血肉詛咒』給逆轉，他們現在全變成機器人了！$B$B我們認為我們有辦法可以再次詛咒好讓他們恢復正常。我們要你帶著這個再詛咒物質轉變注射劑，然後對你看見的每個機械地精屍體使用。$B$B我們希望這能治好他們，然後讓我們把他們關起來別靠近那個地方。$B$B你覺得如何，$n？', '嘶軸簡易機場的金基‧翼果要你對6個嘶軸機械地精使用再詛咒物質轉變注射劑。', '', '去找北風凍原的金基‧翼果。', '嘶嘶剎車地精已被詛咒並傳送', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11713, 'zhTW', '偵察坑道口', '嘶軸派出了一隊空中偵察隊前去勘測位於水泉原野南部的奈幽蟲族坑道口，不過他們還沒回來。我沒辦法再繼續呆等著他們的訊息，所以我需要有人前去查看這些坑道口。$B$B我了解當中所牽涉的危險，所以相對地我會好好酬謝你。帶著這個地圖，並記錄下所有你在坑道口所發現的重要訊息。', '嘶軸簡易機場的艾伯奈‧嘶鍊要你使用水泉原野地圖去紀錄南部坑道口，西北部坑道口，以及東北部坑道口的位置。', '', '去找北風凍原的艾伯奈‧嘶鍊。', '標記南方坑洞位置', '標記東北方坑洞位置', '標記西北方坑洞位置', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11714 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11714, 'zhTW', '殲滅害蟲', '或許你會有興趣幫我清理這些地方?到處都充滿著骯髒的小鼠輩!科多獸，狗頭人，不管你要怎麼稱呼他們都行，這個該死的地方到處都是他們。伴同的這股惡臭讓我的生活變成地獄!$B$B去替我解決這些惡黨，我會讓你的付出得到同等的回報，$n。', '北風凍原，血孢平原的斥候敦苟克要你去殺死8個血孢收割者，5個血孢起火者和2個血孢炙烤者。', '', '去找北風凍原的斥候敦苟克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11715 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11715, 'zhTW', '供給工程的燃料', '我計畫建造一部機器瓦解天譴軍團用來部署奈幽蟲族的管道，不過由於主抽取鑽井架發生故障，我們得用別的方法來替裝置收集燃料。$B$B在東南方往水泉原野的方向走，在主鑽井架外有許多沸騰的小油池。如果你可以從這些油池中收集到足夠的油，我能製造出天然的燃料供給機器動力。$B$B只要將收集器安置在油井附近，機器就會自行吸取並將油儲存於本體的油槽中。', '嘶軸簡易機場的艾伯奈‧嘶鍊要你使用可攜式原油收集器收集8個油桶。', '', '去找北風凍原的艾伯奈‧嘶鍊。', '已收集油桶', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11716 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11716, 'zhTW', '不可思議的血孢', '我們正在見證這裡某種令人驚奇的東西，$r。一整個從未被發現過的生態圈就在離我們不遠的地方生長!我推測血孢植物就是讓這個生態環境如此活躍的主因。$B$B我已經從附近的雄種血孢植物身上收集了一些花粉，但還缺少授粉需要的雌種受體。你可以在我們周遭的偌大植物群附近找到它們。$B$B當心它們的守護者!那些狗頭人可不會輕易的放棄這些血孢植物!', '北風凍原，血孢平原的血法師羅瑞斯要你去取回10個血孢心皮。', '', '去找北風凍原的血法師羅瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11717 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11717, 'zhTW', '花粉來源', '很明顯!血孢飛蛾就是該對這些植物體授粉負責的對象。一定是這些飛蛾的內部系統中發生了什麼引發它們進行授粉行為。現在一切都合理了，$n。那就是為什麼狗頭人沒殺了這些飛蛾，反而不遺餘力地保護它們的原因!那些愚蠢的小鼠輩們全都知情!$B$B好吧，我們只需要取得我們份內的飛蛾授粉就好!你意下如何呢?以科學為名義幫我去取一些回來?', '北風凍原，血孢平原的血法師羅瑞斯要你去取回5個血孢蛾花粉。', '', '去找北風凍原的血法師羅瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11718 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11718, 'zhTW', '長毛象外皮機器人', '我調整了一台老舊機器人的骨架，讓它能夠產生夠強的地震好塌陷那些隧道，但這些機械經不起北裂境嚴寒的摧折。$B$B我想到的解決方法是使用本地長毛象的厚毛皮來隔絕低溫。它們就在簡易機場南方的平原活動，靠近水泉原野附近。幫我帶足夠數量的毛皮回來，好讓我可以完成機械。接下來我們就可以用它來對付奈幽蟲族了!', '嘶軸簡易機場的艾伯奈‧嘶鍊要你帶給他6張厚長毛象皮。', '', '去找北風凍原的艾伯奈‧嘶鍊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11719 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11719, 'zhTW', '一個適合測試的對象', '<羅瑞斯仔細觀察你，就像是在估算什麼一樣。>$B$B我們已經有了這個授粉的血孢花，卻沒人測試過它的效果。哎呀，或許你會有興趣將它擦在你的皮膚上讓我觀察一下嗎？反正，能發生什麼糟糕的事呢？$B$B你別擔心，$n！拿著這個樣本，並將它全部擦在你的臉上。', '北風凍原，血孢平原的血法師羅瑞斯要你使用受粉的血孢花並讓她觀察結果。', '已使用血孢花', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11721, 'zhTW', '『折磨者』甘默斯拉', '猛瑪象人生性驕傲，與獅子極為相似:一個或兩個雄性領導可以與許多個雌性擁有子嗣。以西邊猛瑪象人獸穴，甘默斯的例子來說，甘默斯拉就是頭目。甘默斯拉操控著猛瑪象人的數量，因此一定得殺掉甘默斯拉以避免猛瑪象人的暴動。$B$B帶著這一袋壓碎的血孢花進入甘默斯。使用袋中的粉末削弱甘默斯拉，然後殺了他!帶著他的頭顱來給我作為證明。', '殺了甘默斯拉，將甘默斯拉的頭顱帶回北風凍原的血孢平原交給力角始祖。', '', '去找北風凍原的力角始祖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11722, 'zhTW', '甘默斯戰利品', '我們無法將這場部落的勝利佔為己有，$n。因為冒險不顧生命進行血孢試驗的是你，而最後終結甘默斯拉的也是你。$B$B回到戰歌堡替我們增光，並將甘默斯拉的頭顱交給地獄吼大人。', '將甘默斯拉的頭顱交給戰歌堡的卡爾洛斯‧地獄吼。', '', '去找北風凍原的卡爾洛斯‧地獄吼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11723 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11723, 'zhTW', '部署搖震器', '看吧，這台機械將會拯救我們免於奈幽蟲族的威脅!$B$B<艾伯奈一邊介紹完成的機器人一邊流露出驕傲的光彩。>$B$B拿著這個遙控器，前往水泉原野的奈幽蟲族坑道口最南邊。使用遙控器啟動搖震器5000型。剩下的它自己會動手。$B$B要是它製造的震動引來了奈幽蟲族頭目的注意也不足為奇。事實上，這會是個消滅奈幽蟲族防衛的大好機會。', '嘶軸簡易機場的艾伯奈‧嘶鍊要你使用搖震器5000型去破壞奈幽蟲族的通道並擊敗克萊克希斯克領主。', '', '去找北風凍原的艾伯奈‧嘶鍊。', '', '部署震撼者5000型', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11724, 'zhTW', '巨大蛾蛋捲?', '這顆蛋顯然對某人很重要，附近的屍體可以證明。你注意看這顆蛋的話會發現它已經被貼上送往血孢平原的貨物，由血法師羅瑞斯照料的標籤。就在東邊!$B$B取得蛋並將它帶給等待的血法師。', '帶著這顆發光的巨蛋到北風凍原的血孢平原交給血法師羅瑞斯。', '', '去找北風凍原的血法師羅瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11726, 'zhTW', '有點辣', '自從飛機失事之後，狼群就在四處翻找殘骸，我很怕他們會吃掉任務的膠捲。$B$B我有個計畫來回收那些膠捲，但我需要你的幫助才能成功。$B$B南方與東方的氾濫平原有一種叫做戈洛克的生物。他們使用有毒的香料來保存食物，那會讓所有其他生物感到不適。如果你能從蒸汽噴射者或戈洛克蹣跚者身上收集到足夠的香料包，我就能做個狼餌。', '沸水之池的『尾旋』艾基‧榫栓要你收集4個戈洛克香料包。', '', '去找北風凍原的『尾旋』艾基‧榫栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11728, 'zhTW', '狼便便', '不管你要做什麼，千萬不要自己吃了餌食。只要把餌食放在那些沾染油污的狼附近。如果他們真的餓到吃下膠捲，他們只要一聞到餌食就會立刻跑過來。$B$B接來你只需要靜靜的等待時間處理，然後你就可以搜索那些，呃...膠捲的副產品。$B$B我應該要提供你特殊的工作用狼便便夾，但是我把它忘在簡易機場了。我怕你得...呃...用傳統一點的手法處理。', '沸水之池的『尾旋』艾基‧榫栓要你收集8個微縮膠捲。', '', '去找北風凍原的『尾旋』艾基‧榫栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11729, 'zhTW', '超音波式螺絲起子', '你剛卸下的部分有個東西在它的機械內部。$B$B這看起蠻複雜的…簡易機場的人應該會有興趣看一看這玩意兒。譬如說卡芙緹‧顛鏈？', '將超音波螺絲起子交給嘶軸簡易機場的卡芙緹‧顛鏈。', '', '去找北風凍原的卡芙緹‧顛鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11730, 'zhTW', '主人與僕從', '終極工具就是這把超音波式螺絲起子。它能夠對機械產品為所欲為!$B$B回到池子中拆解掉梅卡佐德的機器人。接著你就可以對它們的殘體使用螺絲起子，我打賭他們將會轉向我們這邊，至少短時間內會是這樣。$B$B我很確定這對機械地精一點用都沒有，所以就放過他們吧。$B$B喔，如果你想要從機器人身上拿點什麼的話，你會想要在使用螺絲起子前先下手!', '使用超音波式螺絲起子重新設定15個機器人，接著回去嘶軸簡易機場找卡芙緹‧顛鏈。記得要先拾取再進行重設。', '', '去找北風凍原的卡芙緹‧顛鏈。', '機器人已重新編程', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11731 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11731, 'zhTW', '投擲火炬', '你想當一名火焰雜耍師?你已經具備這個資格了嗎?你夠靈敏嗎?反應夠快嗎?你有勇氣嗎?假如你認為你已經具備以上的條件，那麼我們來做個小小的練習吧!$B$B拿著這些火炬，然後跑到營火的旁邊。你會看到火盆上閃爍著標誌。對標示的火盆投擲一根火炬。動作要快!你得在標誌消失以前擲出火炬才算數!$B$B在時間結束之前擊中足夠數量的火盆，然後回到這裡……我們再來進行下一個課程。', '在火炬投擲遊戲中獲勝，然後與吞火者大師談話。', '擊中8個火盆', '去找吞火者大師。', '火盆已擊中', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11732 AND `locale` = 'zhTW';
