INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11787, 'zhTW', '褻瀆這些火焰!', '', '褻瀆部落的贊格沼澤營火!。', '', '', '', '', '', '', 0);
