INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11788, 'zhTW', '左轉鬆，右轉緊', '好吧，我想我們準備好進行倒數第二次的進攻了...在你撂倒梅卡佐德以前，你得先把他的手下打爆才行!$B$B你可以分別在西點、北點、中點和南點抽水站找到噹機、ED-210、極限爆衝和研磨者等四個他的手下。$B$B只要轉動抽水站的節流閥，弄亂它們原本在做的事情，它們就會現身了。你不會錯過那些地方的，那裡有燈光在旋轉。', '拆除噹機、ED-210、極限爆衝和研磨者，然後向嘶軸簡易機場的金基‧翼果回報。', '', '去找北風凍原的金基‧翼果。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11789, 'zhTW', '需要幫助的士兵', '那邊那位!拜託，我需要你的幫忙。這個士兵中了地穴惡魔的毒，我們得立刻救他。$B$B我已經試圖減緩毒素蔓延，但如果沒有解毒劑的補給，我無法中和它。$B$B他們承諾說從南方上來的風暴破碎者會有一批抗毒劑。幫我去那邊的箱子裡找急救補給。$B$B快一點，$c!我們無法承擔更多不必要的人手損失了。', '驍勇要塞外的醫護兵赫索恩要你進入風暴破碎者的停靠處，從一箱急救補給中找到赫索恩的抗毒劑。', '', '去找北風凍原的醫護兵赫索恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11792 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11792, 'zhTW', '聖光的敵人', '先別急著走。我不知道你怎麼想，$c，但我不太相信將軍剛剛說的話。聽起來不太可靠...好像不是他自己想講的感覺。$B$B這裡有些事不太對勁。所有我們試著合作的提案都被阻止或延後了。該是我們採取更加自主態度的時候了。$B$B如果我們想要更加了解要塞內教徒的事...或許我們應該先調查外面的教徒。$B$B情報人員回報說有一小組教徒正在協助北邊的天譴軍團。去看看他們身上是否藏有任何線索。', '先驅者瓦銳恩要你去挑戰驍勇要塞的北邊，遠郡附近的教徒通靈師，並從他們身上取得教徒公報。', '', '去找北風凍原的先驅者瓦銳恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11793 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11793, 'zhTW', '進一步的調查', '我擔心這就是我必須委任間諜的原因...一個可以進行秘密工作的人。將證據帶在身上，並將它交給旅館裡的復仇者亞拉。$B$B告訴他是我派你前去，並請她保守秘密。我們並不知道誰會是替教派工作的人。', '帶著教徒公報給驍勇要塞旅館裡的復仇者亞拉。', '', '去找北風凍原的復仇者亞拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11794, 'zhTW', '獵殺開始', '我已經盡可能的去了解這個邪惡的死亡教派，包括他們的神秘語言。$B$B瓦銳恩是對的。教徒們提到喬裝的間諜在驍勇要塞幾個地點:底下的碼頭，堡內的監獄，以及旅館中的廚房。$B$B拿著這個驅魔師之目。在那三個地方使用它 - 任何最近使用過教派死靈法術者都會被一圈黑暗光環覆蓋。趕在惡毒的事發生前，解決掉這些教徒們。', '復仇者亞拉要你在驍勇要塞的三個地點使用驅魔師之目找到詛咒神教的成員並擊敗他們。', '', '去找北風凍原的復仇者亞拉。', '碼頭的異教徒已擊敗', '監獄的異教徒已擊敗', '廚房的異教徒已擊敗', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11795 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11795, 'zhTW', '緊急狀況協定:章節8.2，段落C', '不管有沒有受傷，身為一個空軍指揮官，我負責找出並交回所有麾下陣亡駕駛員的徽記。一直以來我都和嘶軸一起飛行，我們從未忘記交回駕駛員的徽記。$B$B我的傷讓我無法離開失事殘骸的安全區域太遠，不過或許你願意幫我去取回徽記？在這段時間內，我將準備執行我身為空軍指揮官的最後職責。', '從嘶軸偵察駕駛員的屍體上取得6個嘶軸駕駛員徽記，將徽記帶回沸水之池交給『尾旋』艾基‧榫栓。', '', '去找北風凍原的『尾旋』艾基‧榫栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11796, 'zhTW', '緊急狀況協定:章節8.2，段落D', '在我返回簡易機場報告前只剩最後一件事情要做。緊急狀況協定的章節8.2，段落D提到為了不讓我們的技術落入敵方手中，要求我盡可能地破壞所有的殘骸。$B$B如果你願意幫助我完成這個最後的職責，我會將我的火把交給你。我不敢想像要是這些機器落入部落的哥布林同行手中他們將會怎麼做。', '『尾旋』艾基‧榫栓要你去破壞東邊的殘骸，南邊的殘骸，以及西北邊的殘骸。', '', '去找北風凍原的『尾旋』艾基‧榫栓。', '鑿沉東方殘骸', '鑿沉南方殘骸', '鑿沉西北方殘骸', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11797 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11797, 'zhTW', '圍攻', '哎呀，哎呀，哎呀。看到阿爾洛斯拿出他的大槍來真是好啊。$B$B別誤會我的意思 - 我們大家都盡力了，不過你們當中的重要人物與他們並肩作戰更能將情勢轉而有利於我們。我不知道我們還能抵擋這些不死的奈幽蟲族多久。$B$B出去幫我殺死一些蠕行者如何?讓這些小子見識一下怎麼做才是正確的。', '錘丘中士要你去驍勇要塞外的納森沙地殺了6個地穴爬行者。', '', '去找北風凍原的錘丘中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11798, 'zhTW', '齒輪大師', '齒輪大師梅卡佐德根本就瘋了!他說要給予我們永生，移除所謂「血肉的詛咒」，但他根本只是把我們做成他的機器奴隸!$B$B$n，我們十分確定他人還在東方水池中間的幫浦站。$B$B我們最後一次看見他，他就在建築頂上的指揮小屋中。上去那邊並且調查他的東西。$B$B如果地精想要存活下來，你就必須要面對梅卡佐德!', '研究齒輪大師的手冊，並且帶著梅卡佐德的頭回去向嘶軸‧滿閥報告。', '', '去找北風凍原的嘶軸‧滿閥。', '已研究齒輪大師的手冊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11799 AND `locale` = 'zhTW';
