INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11864, 'zhTW', '任務聲明', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11865 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11865, 'zhTW', '不宜死亡', '在正南方，通常馴鹿都自由，和平地漫步著。接著，奈辛瓦里出現，什麼都變了。現在，馴鹿身處於一個無盡的狂亂狀態，永遠都處於驚慌中。躲藏在原野裡的獵人及陷捕者追蹤著牠們。$B$B死亡並不適合奈辛瓦里的劊子手。他們一定得親身感受他們施加在馴鹿身上的折磨!$B$B帶著這一堆假毛皮並將它放在他們置於南方的馴鹿陷阱上。看著這些獵人栽在自己設置的死亡陷阱中吧!', '北風凍原，D.E.H.T.A.駐營的札扎要你使用一堆假毛皮使8個奈辛瓦里陷捕者落入陷阱。', '', '去找北風凍原的札扎。', '奈辛瓦里的陷阱師已被困', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11866 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11866, 'zhTW', '吾敵之耳', '無論他們是荒原的寶藏搜尋者或是嗜血獵人，任何援助奈辛瓦里且膽敢破壞我們珍愛的野生動物者都會被當作是D.E.H.T.A.的敵人。$B$B如果你殺了這些骯髒的奈辛瓦里支持者，就將他們的死亡證明帶給我，你將會獲得來自D.E.H.T.A.德魯伊的祝福獎勵。', '北風凍原，D.E.H.T.A.駐營的大德魯伊拉索利厄思說，如果你可以帶15個奈辛瓦里僕人之耳給他，他將會獎勵你。', '', '去找北風凍原的大德魯伊拉索利厄思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11867, 'zhTW', '耳朵，永遠都不夠...', '無論他們是荒原上的尋寶者或是嗜血的獵人，任何膽敢援助奈辛瓦里襲擊我們所珍愛野生動物的人，都將被當作是D.E.H.T.A.的敵人。如果你殺了這些骯髒的奈辛瓦里支持者，將他們的死亡證明帶給我，你將會獲得來自D.E.H.T.A.德魯伊的祝福獎勵。', '北風凍原D.E.H.T.A.前哨的大德魯伊拉索利厄思提到如果你可以帶15個奈辛瓦里僕人之耳給他，他將會獎勵你。', '', '去找北風凍原的大德魯伊拉索利厄思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11868 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11868, 'zhTW', '挑選者來了', '在接近這座懸崖的南邊盡頭處，你將會發現馴鹿陷捕者的奸詐頭目。她是一個前所未有的野蠻人，挖出被屠殺的動物內臟棄之不用:飲用牠們的血並對月嗥叫!$B$B找到這個兇手，凱倫，並終結她那無價值的存在。$B$B做好準備，$n。『挑選者』凱倫沉迷於奈辛瓦里濫施給她的財富中!', '北風凍原，D.E.H.T.A.駐營的札扎要你去殺了『挑選者』凱倫。', '', '去找北風凍原的札扎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11869, 'zhTW', '跟蚌殼一樣開心', '往西邊走你會發現庫姆亞湖。目前就我們所知，這是世上僅存的淡水巨型蚌殼棲息地。$B$B當然奈辛瓦里的僕人們現在將這個湖當作巨型珍珠飼養場。一定得阻止他們!得教訓一下那些想要危害整個物種的人。$B$B到庫姆亞湖去，並找出掠寶狂潛水者。殺光他們，把湖水染紅為止!等目標完成後回來找我!', '北風凍原，D.E.H.T.A.駐營的祭師賽紐斯要你去殺掉10個掠寶狂潛水者。', '', '去找北風凍原的祭師賽紐斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11871, 'zhTW', '在我們的看守下，想都別想', '散佈在整個海灘上，處於船隻的殘骸與投棄的貨物之中的，就是木箱和一袋袋的動物肢體。看來似乎那個奈辛瓦里和北海掠劫者是一夥的。那些骯髒的海賊正在運送由奈辛瓦里的兇惡僕人堆積在離岸的貨物。無疑地他們最後將會回到家鄉，坐擁財富，成為遍及艾澤拉斯的無恥之徒。$B$B這不會發生的。在我們的看守下，想都別想。將你在這片海灘上發現的所有東西帶來給我。他們將永遠都無法擁有這些東西!', '北風凍原，被遺棄之境的祭師利安卓要你去取得12箱的動物肢體。', '', '去找北風凍原的祭師利安卓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11872, 'zhTW', '惡劣的蚌殼大師', '一個人把自己神化為「蚌殼大師」真的是很下流，好像他們支配著整個海洋裡的生物一樣。沒有人可以這樣自稱!$B$B一定得找到這個「蚌殼大師」並殺了他。最後一次看到他是在被遺棄之境的海岸外失事的殘骸那。$B$B一旦完成此任務，回到北邊的D.E.H.T.A.駐營找祭師賽紐斯，並告知她任務已成功完成。', '殺了蚌殼大師凱並回到D.E.H.T.A.駐營找祭師賽紐斯。', '', '去找北風凍原的祭師賽紐斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11874 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11874, 'zhTW', 'Upper Deck Promo - Rocket Mount', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11875 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11875, 'zhTW', '取得優勢', '破碎之日進攻部隊將會需要所有能夠用來擊退基爾加丹聯軍的有利條件。我在暴風城的同袍製造了一種油，可用來強化我們使用的刀具及盔甲。$B$B主要的成份，虛空殘渣，遍佈於外域中 -- 只要你知道上哪找就行。任何一位草藥學大師、剝皮大師、或是採礦大師都懂得如何利用$g他的:她的;專業來收集此種物品。那些專屬於外域的藥草、礦脈以及生物身上都可能帶有這種殘渣。', '將8個虛空殘渣交給撒塔斯城中的大使莫爾丁。', '', '去找泰羅卡森林的摩爾丁特使。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11876 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11876, 'zhTW', '幫助那些無力自救者', '牠們是雄偉的野獸，對吧?$B$B<拉索利厄思指著北風凍原的長毛象。>$B$B他們的數量正在日漸銳減。那些自稱為獵人的惡魔，為了消遣和財富屠殺這些野獸。$B$B<拉索利厄思的臉因憤怒而扭曲。>$B$B就是這些嗚咽讓我發怒，$n。你可以聽到這些聲音伴隨著風聲傳來。這些小長毛象，被困在獵人邪惡的陷阱裡，對我們求救著。$B$B帶著這個錘子去粉碎那些陷阱。讓這些小象自由!', '大德魯伊拉索利厄思要你使用D.E.H.T.A.陷阱粉碎者去釋放8隻小長毛象。拉索利厄思就在北風凍原的D.E.H.T.A.駐營。', '', '去找北風凍原的大德魯伊拉索利厄思。', '已釋放長毛象幼獸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11877 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11877, 'zhTW', '日怒攻擊計畫', '在我們部署奎爾達納斯的攻擊部隊時，我們發現凱爾薩斯的爪牙正在策劃反攻。他命令位於虛空風暴的日怒血精靈前來攻擊我們位於外域的行動，想要把軍隊及注意力從太陽之井這裡引開。$B$B我們不能讓這種事發生，$n。每一兵一卒都得部署在前線。$B$B前往虛空風暴並取得他們的攻擊計畫。那裡的任何一個血精靈身上都可能擁有計畫。祝你好運，$n。', '撒塔斯的托沃斯領主要你前去取得日怒攻擊計畫。', '', '去找撒塔斯城的託沃斯男爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11878 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11878, 'zhTW', '庫諾克知道', '雖然你英勇地拯救了許多小象，但它們大多數依舊會死去。你要知道，沒有一個照顧的人，這些小象得在荒野之中自己求生。$B$B但現在有個方法!能幫助那些倖存的!$B$B此地北方的長毛象原野上，靠近沸水之池的邊界，你可以找到『巨獸』庫諾克:一隻古老而睿智的長毛象。帶著長毛象孤兒去找庫諾克，他會知道該怎麼辦。', '帶失怙的小長毛象去找北風凍原的『巨獸』庫諾克。', '孤兒長毛象幼獸已送交庫諾克', '去找北風凍原的『巨獸』庫諾克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11879 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11879, 'zhTW', '『長毛象摧毀者』卡烏', '你無法單獨擊敗那隻該為屠殺我族負起責任的生物。凍原的長毛象將會幫助你!$B$B前往平原冒險並找到一隻公長毛象。牠將會讓你騎乘並控制牠的行徑。騎上牠並在北邊卡烏的棲息地找到卡烏。同心協力，你們將會是促成卡烏死亡的那隻手。$B$B摧毀卡烏的軍隊並從卡烏手中奪走他那把心愛的戰戟。成功後回到D.E.H.T.A.駐地找拉索利厄思。', '殺掉『長毛象摧毀者』卡烏並取得卡烏的戰戟。將卡烏的戰戟送到北風凍原的D.E.H.T.A.駐營交給大德魯伊拉索利厄思。', '', '去找北風凍原的大德魯伊拉索利厄思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11880 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11880, 'zhTW', '多相測量', '我確定那個『地精發明家』是個瘋子。他不停地在說有黑色的扭曲空間出現在納葛蘭，歐夏岡的靈魂原野上。$B$B據他說，這個…呃…多重…多相…耶…測什麼鬼的護目鏡可以讓配戴者看得見那些扭曲空間，並且取得讀數。他很堅持說這些數據對我們在太陽之井的戰役非常重要。我想他是個神經病，但我受命要調查一切可能有幫助的事情。你願意去幫忙蒐集讀數嗎?', '撒塔斯城的先驅者哈洛尼恩希望你使用多相光譜護目鏡來取得6個多相讀數。', '', '去撒塔斯城找聖光廣場的先驅者哈隆奈姆。', '獲取多相讀數', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11881 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11881, 'zhTW', '帶回來!', '你有看到到處低飛掠過的飛行器嗎？那就是地精的傑出創造物。$B$B我一直在想要親手把玩他們的科技產品，而適當的機會自己送上門了。一架偵察機就墜毀在水泉原野。$B$B前往一架墜毀的機器旁吹響這個哨子，接著我那可靠的騾子，潔妮會回應你。她將會跟隨著你並馱運可利用的殘骸，不過你一定得保護她的安全。她只要一遭到攻擊就會開始丟棄貨物。', '協助潔妮帶著她所有的貨物從失事地點抵達坦卡雷村的菲奇司‧絞輪處。', '', '去找北風凍原的菲奇司‧絞輪。', '在不遺失貨物的情況下護送珍妮安全返回', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11882 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11882, 'zhTW', '玩火', '你想學點熱騰騰的新技巧嗎?我不知道你有沒有辦法學會我這種技藝，不過如果你是個夠專心的學生的話，或許能學會一兩招。去跟任何一個聯盟主城的吞火者大師談談。他們應該可以協助你。', '跟任何一個聯盟主城的吞火者大師談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11883, 'zhTW', '火舞?', '你想要學習火舞的藝術?很好，那去跟任何一個部落主城的火舞者大師談談。他們應該可以協助你。', '跟任一個何部落主城的火舞者大師談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11884 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11884, 'zhTW', '犀牛王尼德…', '在此地之西，庫姆亞湖之上的高崖，有一隻名叫尼達爾的卑鄙生物在晃蕩著。他自稱為『犀牛王』，在荒野上狩獵那些受傷或太年幼而無法自保並抵抗尼達爾的犀牛。更糟糕的是，尼德還復活了一隻犀牛作為他的坐騎和保鏢。$B$BD.E.H.T.A絕少會要一隻動物死亡，但尼德那被污染的犀牛必須要被處理掉…殺死他們兩個，然後再回來找我。', '『獸穴看守者』基林格爾要你去殺死『犀牛王』尼達爾和他的同伴『午餐盒』，完成之後再回到北風凍原的D.E.H.T.A.駐營向他回報。', '', '去找北風凍原的『獸穴看守者』基林格爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11885 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11885, 'zhTW', '敵人之血', '被司凱堤斯魔爪祭司扣留為囚犯的子嗣都列在這本書裡:女獵人吉札拉，水晶巨人葛洛克，以及異端黑暗尖叫者阿卡萊和『風怒者』瓦奇茲。殺了他們才能讓泰洛卡回到這個世界。$B$B你需要時光流逝阿拉卡身上帶的卷軸，才能在司凱堤斯的召喚法陣召喚他們。你挑戰的是強大的生物;帶朋友一起去會比較好。', '在司凱堤斯的召喚法陣中央找到顱骨堆。在顱骨堆用10個時光流逝卷軸召喚並擊敗每個子嗣。回到黑風平臺找海茲克。', '', '去找泰羅卡森林的海茲克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11886 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11886, 'zhTW', '不尋常的活動', '當慶典舉行時，$c，我們當中的某些人就需要留意那些較嚴重的問題。$B$B在節慶開始時，我們收到了來自佐拉姆海岸的報告，有關於暮光教派的活動明顯增加。這個節日的起源就是緬懷那些瘋子所崇敬的強大力量;這不可能是巧合。前往黑暗深淵入口南邊的營地去，看看那些暮光教徒在搞什麼鬼 - 必要的時候使用武力也沒關係。等你找到的時候，使用這個信號來召喚一個嚮導。', '前往位於梣谷，佐拉姆海岸的黑暗深淵入口南邊新成立的暮光營地。為陶土議會找出答案，然後使用圖騰信號召喚陶土議會嚮導。', '', '去找陶土議會嚮導。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11887 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11887, 'zhTW', '緊急補給', '搜出了這位死掉地精的財物之後，你發現了一個小包裹，裡面滿是乾糧、工具和一個稱手的地精導管帶。這些包裹中的小工具對菲奇司‧絞輪來說，對於修理起破損的地精飛行器應該滿有用的。$B$B把這些工具交給菲奇司應該可以獲得一筆不錯的報償。', '從墜毀的嘶軸偵察駕駛員的屍體上收集7個地精緊急工具箱。然後帶給坦卡雷村的菲奇司‧絞輪。', '', '去找北風凍原的菲奇司‧絞輪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11889 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11889, 'zhTW', '死從天降', '我們固守抵禦蟲子進犯的戰線。但是，有些無恥的混蛋可以飛過前線，嚴重打擊了我們內部的防禦武力。$B$B我從民間船隻上徵用了一些強化魚網。如果你丟東西的技術不錯，就可以用網子把那些傢伙從天上給打下來。減少它們的數量，好讓我們的部隊可以守住要塞。', '錘丘中士希望你使用強化織網來殺死6隻驍勇要塞外的天譴噴火者。', '', '去找北風凍原的錘丘中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11890 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11890, 'zhTW', '他們在搞什麼鬼？', '地精在西邊的水池附近捲入了一些麻煩。這根本就是他們用那些自稱是發明的東西污染土地的報應。$B$B我要你前往他們的幫浦站，看看他們到底怎麼了。然後向我回報。', '調查嘶軸幫浦站四周的區域。然後向坦卡雷村的賢者地空回報。', '已檢查嘶嘶剎車抽水站周邊環境', '去找北風凍原的賢者地空。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11891 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11891, 'zhTW', '無辜的偽裝', '根據這個看來，在佐拉姆海岸的大集會西北邊有另一個教徒營地，而且他們正在與...客人說話?$B$B親耳聽聽會知道的更多，$r。拿著這個寶珠;它可讓你以本地海灘爬行物的模樣出現。去刺探那些教徒在西北邊營地中的「客人」談話，成功後回報給我。', '使用爬行者寶珠去刺探位於梣谷，佐拉姆海岸的黑暗深淵西邊新成立的暮光營地。然後使用圖騰信號召喚陶土議會嚮導。', '聆聽暮光異教徒的計畫', '去找陶土議會嚮導。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11892 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11892, 'zhTW', '刺殺哈洛德‧蘭恩', '你為北風凍原上的動物們貢獻很大，$n。那些奈辛瓦里的狗腿已經被擊退，至少教訓他們短時間內不會忘記。$B$B哈洛德‧蘭恩，納葛蘭大屠殺的主要元兇，已經被確定正是凍原上負責奈辛瓦里運作的人。他正駐紮於西方的庫姆亞湖。$B$B<伊拉索利厄思交給你一把雕工複雜的橡木號角。>$B$B找到蘭恩，殺掉他。如果你需要我們的幫忙，就吹響這把號角吧。', '大德魯伊拉索利厄思要你殺掉哈洛德‧蘭恩，拉索利厄思就在北風凍原的D.E.H.T.A.駐營。', '', '去找北風凍原的大德魯伊拉索利厄思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11893 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11893, 'zhTW', '元素的力量', '我一直努力想告訴那些傻傻的哥布林，他們的機器是不可靠的。$B$B元素的力量才是深層而不變的。當我完成了學徒訓練，我將可以使用它們完整的力量。而我目前所知道的，就足以幫助我們的朋友菲奇司。$B$B帶著這個風魂圖騰，放置在村子西邊的那些蒸汽狂怒者附近。圖騰會吸取那些被殺死元素的能量。把充能完畢的圖騰還給我，我來處理剩下的事情。', '坦卡雷村的杜然‧霜蹄希望你使用風魂圖用收集10個蒸汽狂怒者的能量。', '', '去找北風凍原的杜然‧霜蹄。', '已收集能量', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11894 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11894, 'zhTW', '拼湊貼補', '記得你帶給我的那些地精導管帶？$B$B嗯，我找到了一個地方可以派上用場。這台飛行器的結構拼湊得有點勉強，如果我還希望這玩意兒能飛的話，我就得強化它。$B$B那邊的杜然告訴我坦卡族使用蒸汽燻製馴鹿皮革來製作防水容器。沼澤馴鹿在村子附近生活，還有南方的氾濫平原。弄來你能找到最好的皮革，然後在水泉原野的蒸汽孔將皮革燻製好。', '坦卡雷村的菲奇司‧絞輪要你帶給他5張蒸汽燻製皮。', '', '去找北風凍原的菲奇司‧絞輪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11895 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11895, 'zhTW', '駕馭風暴', '聽你的敘述，那些金屬生物似乎很好應付。但首先，你必須要駕馭風暴。$B$B我身後的小屋有一根圖騰。等你準備好，將你的意志專注在圖騰上，風暴將會到來。你必須要擊敗風暴，然後將他的精華吸收到你的體內。$B$B如果還有別人在那邊，你們可以一起合作擊敗它。等你完成之後，回來找我，$c。', '擊敗狂亂風暴，然後回到坦卡雷村找賢者地空。', '', '去找北風凍原的賢者地空。', '已掌控風暴', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11896 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11896, 'zhTW', '電擊弱點', '你的體內現在有了風暴的力量。我將會提供你可用來集中那股力量的媒介，並弱化池子中的機器人。$B$B拿著這個閃電魔棒。使用它來對付你在西邊大池區所發現的機械地精機械產物。不必使用魔棒對付機械地精;主母泰嘉對它們別有想法。$B$B一旦機器人被風暴之力弱化了，就徹底的拆除它們!', '當機器單位處於被風暴之力弱化的狀況時，摧毀嘶軸幫浦站週遭大池區中，除了機械地精以外的任意15個機器單位。完成後，向坦卡雷村的賢者地空回報。', '', '去找北風凍原的賢者地空。', '機器人已削弱並摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11897 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11897, 'zhTW', '塞住坑道口', '天譴軍團毫無預警的出現，$n。就是那些該死的坑道口;就我們所知，地底隧道一路通往寒冰皇冠。巨大的不死蟲類潛伏在地面下挖掘隧道。$B$B幾年的採礦經驗讓我知道，沒有支撐的橫樑，管道在爆炸後會變得容易塌落。$B$B拿著這些爆炸物，將它們放在坑道口的入口處，地點就在西邊海邊後面的山脊之上。等你炸垮了它們之後再回來。', '錘丘中士要你使用燃燒爆裂物去破壞驍勇要塞西北邊和西南邊的坑道口。', '', '去找北風凍原的錘丘中士。', '南方坑洞已安置炸藥', '北方坑洞已安置炸藥', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11898 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11898, 'zhTW', '突破', '在聖城的最下層，有一座籠罩著光的灰色祭壇。進入祭壇，進入恐懼亡域納克薩爾。$B$B當心點，$n。瓦拉納爾親王身邊肯定有他的貼身僕役保衛著，他們會以生命阻止你前進亡域的頂層區域。$B$B你一定要穿越亡域通往王子所在地。如果你無法擊敗他的話，$n，我擔心我的人民將永遠無法得知冰霧所提供的安全。', '擊敗瓦拉納爾親王及他的部下，『殘酷』范希林和『邪惡』路西翁，接著回報給坦卡雷村的冬風酋長。', '', '去找北風凍原的冬風酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11899 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11899, 'zhTW', '除咒的靈魂', '西方水池的機械地精對我們來說是個謎團。他們在地精們從幫浦站及其周邊失蹤沒多久之後出現。$B$B他們是非自然的危害，必須要處理掉。$B$B帶著這個攝魂器並且對機械地精的屍體使用來捕捉他們的靈魂。然後回來找我，我們可以將他們釋放出來，看他們到底發生了什麼事。', '使用主母的攝魂器來捕捉10個嘶軸機械地精的靈魂。然後回坦卡雷村向主母泰嘉回報。', '', '去找北風凍原的主母泰嘉。', '地精之魂已捕獲', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11900 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11900, 'zhTW', '檢查讀數', '我本來希望奧核之心的衝擊能夠被侷限在這個區域，但根據最近的報告，顯然波動已經影響了整個艾澤拉斯，地質不穩定的情況幾乎是指數性飆升!$B$B我需要有人在我研究解決之道時，隨時監控奧核之心。$B$B我在凜懼島周圍安置了檢測儀器，偽裝成瑪里苟斯的占卜寶珠。一個就在奧核之心的裂溝附近，另外三個則藏在山谷四周的裂縫中。去察看每一個然後向我回報讀數。', '隘境之盾的大法師貝瑞那德希望你去收集他設在凜懼島的儀器的數據。', '', '去找北風凍原的大法師貝瑞那德。', '讀取奧核之心地質數據', '讀取南部凜懼島數據', '讀取北部凜懼島數據', '讀取西部凜懼島數據', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11903, 'zhTW', '是行動的時候了', '那麼，$n，在遠郡的我軍戰至最後一兵一卒以後，我們只剩下一件事情可以做:那就是親自和天譴軍團戰鬥。$B$B我們已經將遠郡剩下的居民訓練成民兵。但沒有你幫助，他們幾乎沒有獲勝的希望。去幫助他們。我和小夥子們會監視這條路。我們絕不會讓天譴軍越雷池一步!', '遠郡的吉羅德‧葛林要你去殺死14個染疫食腐者。', '', '去找北風凍原的吉羅德‧葛林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11904, 'zhTW', '勞動的果實', '天譴軍團一直持續出現...不過我們不能放棄!聽著，$n。那個礦坑內有一部貨車，裝載著最後一批聯盟長久以來在這片大陸尋找的礦石。$B$B問題在於，貨車的啟動手把被鎖住了。當軍隊進入裡面時，傑考伯司上尉強行沒收了所有重要的裝備，包括貨車啟動手把鑰匙。$B$B那股感染了礦坑裡士兵的瘟疫必定也感染了傑考伯司。去從他身上取得鑰匙並回收礦石。', '前往遠郡的礦坑，從傑考伯司上尉身上取得貨車啟動手把鑰匙，並用它來鬆開運礦車。完成任務後回到遠郡找吉羅德‧葛林。', '', '去找北風凍原的吉羅德‧葛林。', '礦車已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11905 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11905, 'zhTW', '拖延不可避免的毀滅', '艾澤拉斯的地脈被修改導向了奧核之心。$B$B秘法能量的匯流已經開始在不同空間之間扯開一條裂隙。$B$B我阻止不了這一切，但我已經找到了一個方法可以減緩它。$B$B帶著這個進入奧核之心，然後在形成中的裂隙旁啟動它。', '奧核之心內戰爭法師凱特林的影像要你在形成中的裂隙旁啟動間次元重製器。', '', '去找北風凍原的大法師貝瑞那德。', '次元裂隙已延緩', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11906 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11906, 'zhTW', '淨化水池', '<一滴眼淚從鐵眼的臉上落下。>$B$B我聽說你要往西方的水池去。我希望你在那邊的時候能幫我做點事情，$r。$B$B那些絲毫不在意這片土地的地精，還在用他們的機器繼續污染著大地。我要你收集你看到的任何零件。$B$B把那些東西交給我。在我們離開此地以前，我要看到他們被妥善地處理。', '收集15個嘶軸的備用零件，然後交給坦卡雷村的鐵眼。', '', '去找北風凍原的鐵眼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11907 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11907, 'zhTW', '副手', '一般都知道齒輪大師梅卡佐德有四個副手在管理水池的機器人。$B$B我們得要終止這些傢伙!$B$B我們的遠偵斥候和雪地追蹤者說，如果你能把西點抽水站、北點抽水站、中點抽水站和南點抽水站的活門給關掉，那四個副手就會立刻出現阻止你破壞他們的運作。$B$B抽水站就在水池旋光的中央，圍繞著幫助站。$B$B快去吧，$n!', '打倒噹機、ED-210、極限爆衝和研磨者，然後向坦卡雷村的賢者地空回報。', '', '去找北風凍原的賢者地空。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11908 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11908, 'zhTW', '相關用具', '我負責管理收割魔像 - 在天譴軍團摧毀我們大部分的農場之前，這是個很重要的工作。但我有個主意能讓這些魔像被重新利用。$B$B我想我可以改寫收割機器人讓它們可以協助我們和天譴軍戰鬥。$B$B不過，我並不是這方面的專家，所以我需要我的手冊。但問題是，我把手冊掉在工坊了...就是礦坑旁邊那棟燃燒的建築。你願意幫我去搶救出手冊嗎?', '杰瑞米亞‧豪寧要你從遠郡礦坑旁燃燒的建築中找回一本書《農地、工廠和工坊》。', '', '去找北風凍原的杰瑞米亞‧豪寧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11909 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11909, 'zhTW', '打敗齒輪大師', '顯然這個齒輪大師梅卡佐德並不是什麼心智正常的生物。他所提出的治療和永生只不過要把我們全都變成他的機械奴隸，他一定要被阻止!$B$B引導我的風向我傾訴，告訴我他就在東方水池中間的幫浦站頂端。$B$B他八成就在建築頂上的指揮小屋中。進入指揮小屋並研究他的東西。$B$B$n，如果我們想要存活你就必須要對抗梅卡佐德!', '研究齒輪大師的手冊，並且帶著梅卡佐德的頭回到坦卡雷村向主母泰嘉報告。', '', '去找北風凍原的主母泰嘉。', '已研究齒輪大師的手冊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11910 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11910, 'zhTW', '古樹的秘密', '很顯然這個區域的不穩定已經對本地的生物造成影響。$B$B我對冰川古樹以及他們最近的適應性變化有特殊的興趣。我懷疑他們轉變成為『咒縛』古樹的情況，可能會有著我們目前困境的線索。$B$B為了我的研究，我需要這兩者的樣本。行動要快……', '隘境之盾的大法師貝瑞那德希望你從凜懼島的古樹身上收集3個冰川裂塊和3個咒縛裂塊。', '', '去找北風凍原的大法師貝瑞那德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11911 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11911, 'zhTW', '激長', '我在這裡短短時間學到的東西，遠遠超過我幾十年的研究。$B$B這些古樹暴露在難以形容的巨大秘法能量下。它明顯地將他們轉變為...別的東西。$B$B我十分確信他們的蛻變有最後一個階段。幫我找來一些關於他們最後階段的證據。', '奧核之心內戰爭法師凱特林的影像要你從結晶保衛者身上收集5個秘法裂塊。', '', '去找北風凍原的大法師貝瑞那德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11912 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11912, 'zhTW', '為莓發狂', '噢!能看到一個新面孔真叫人鬆了一口氣。我都開始以為我們已經被遺忘了。$B$B我們的補給線好幾天前就被切斷了，而事情看起來 - 嗯，很絕望。老實說，我從一開始就認為這是個自殺任務。$B$B我本來就不適合這樣的戰亂生活，更別提這刺骨之寒!我寧可回到達拉然去研究那些古文獻。$B$B總而言之，我們的食物補給幾乎用盡了。拜託，不管你收集到什麼都請交給我。', '隘境之盾的圖書管理員瑟菈要你從凜懼島的霜莓叢收集10個霜莓。', '', '去找北風凍原的圖書管理員瑟菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11913 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11913, 'zhTW', '不要冒險', '我聽了你向吉羅德回報的內容，但我可不同意。如果教徒要利用他們邪惡的瘟疫在礦坑裡的穀物中下毒，那麼他們大可在礦坑外做這件事，同時也比較容易。$B$B我們沒時間把中毒與否的穀物挑撿開，只能趕緊全燒掉。$B$B拿著火炬，把外頭所有袋子裡的穀物燒掉。如果我們熬過這波攻擊卻死於瘟疫，那就真的是件悲劇了。', '溫蒂‧達倫需要你使用溫蒂的火炬，將8袋遠郡穀物燒毀。', '', '去找北風凍原的溫蒂‧達倫。', '遠陽郡的穀物已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11914 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11914, 'zhTW', '守護秘密', '我們能存在此地全是靠著保持隱匿。要是護盾失效，哪怕只有一會兒，瑪里苟斯的手下都會逮到我們。$B$B我在此地的職責之一就是恢復那些戰法師的法力以免他們集中力渙散。但隨著我們失掉了補給線，我被迫勉強湊合行事。$B$B我用得上你的協助，$n。$B$B就在奧核之心附近，秘法巨蛇以大量的魔法能量為食。只要打敗它們，它們會留下一種我用得上的法力精華。', '隘境之盾的圖書管理員瑟菈要你殺死奧核之心附近的秘法巨蛇，並且收集5個奧核法力精華。', '', '去找北風凍原的圖書管理員瑟菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11915 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11915, 'zhTW', '玩火', '你想學點熱騰騰的新技巧嗎?我不知道你有沒有辦法學會我這種技藝，不過如果你是個夠專心的學生的話，或許能學會一兩招。去跟任何一個部落主城的吞火者大師談談。他們應該可以協助你。', '跟任一個何部落主城的吞火者大師談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11917 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11917, 'zhTW', '反擊', '我們必須以行動來維持平衡!時間對我們相當不利。$B$B帶著大型的冰石回到佐拉姆海岸的營地。他們可以利用這些東西來和元素溝通，就像是希利蘇斯那樣。雖然我不喜歡這樣，那些精靈會瞭解的 - 你必須要召喚艾胡恩手下的一個副官，並且摧毀它。或許這樣先發制人的行動會有效……', '把冰石召喚出來的霜浪副官殺死，冰石就在梣谷的佐拉姆海岸。然後向主城中的陶土議會長老回報。', '', '去找陶土議會長者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11918 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11918, 'zhTW', '基本訓練', '這是一場戰爭，凡人，而我們就是長矛的尖端。$B$B你對這塊土地或當前局勢的看法與我們眼前的戰爭相比根本是微不足道。我們面對的是守護巨龍瑪里苟斯和他整個藍龍軍團。你只需要知道，如果他獲勝了，那麼這個世界將不復存在。$B$B我們在此地的數量稀少，而我們所對抗的敵人卻數量龐大。我們的死亡是必然的結果，我們最終的成功也只是拖延我們的敵人。$B$B去吧。在我想到要如何運用你之前，替自己找點事情做。', '隘境之盾的瑞洛拉茲要你去殺死10隻凜懼島織法者。', '', '去找北風凍原的瑞洛拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11919 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11919, 'zhTW', '獵龍', '藍龍開始在他們的飛龍身上劃上神秘的符文。我一定要知道它們的意義。$B$B<瑞洛拉茲拿長矛劃開自己的手，在矛尖沾上他的血。>$B$B帶著這個，然後對他們使用長矛。等待他們被制服，然後效果解除之前把他們帶回來找我。$B$B他們的雛龍在西北方邊緣的山谷活動。', '瑞洛拉茲要你使用瑞洛拉茲之矛來制服一隻奧核雛龍，然後帶回隘境之盾給他。', '', '去找北風凍原的瑞洛拉茲。', '已捕獲奧術龍獸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11921 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11921, 'zhTW', '投擲更多的火炬', '哈囉，火焰雜耍師!你玩得開心或是燒掉了什麼嗎?那就是我想聽到的事!現在，你覺得自己是個火炬投擲的專家嗎?既然這樣的話我有個測試給你…$B$B你知道規則:將火炬投擲到標記的火盆裡。不過，這一次你擁有的時間變少，你得投中的火盆更多了。$B$B準備好了嗎?', '在火炬投擲遊戲中獲勝，然後與吞火者大師談話。', '擊中20個火盆', '去找吞火者大師。', '火盆已擊中', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11922, 'zhTW', '投擲火炬', '你想當一名火焰雜耍師?你已經具備這個資格了嗎?你夠靈敏嗎?反應夠快嗎?你有勇氣嗎?假如你認為你已經具備以上的條件，那麼我們來做個小小的練習吧!$B$B拿著這些火炬，然後跑到營火的旁邊。你會看到火盆上閃爍著標誌。對標示的火盆投擲一根火炬。動作要快!你得在標誌消失以前擲出火炬才算數!$B$B在時間結束之前擊中足夠數量的火盆，然後回到這裡……我們再來進行下一個課程。', '在火炬投擲遊戲中獲勝，然後跟吞火者大師談話。', '擊中8個火盆', '去找吞火者大師。', '火盆已擊中', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11923 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11923, 'zhTW', '接住火炬', '現在你會投擲火炬了，來看看你是否接得住吧!$B$B拿著這堆未點燃的火炬。到營火前去並將火炬高高丟入空中。在火炬掉落至地面前接住...然後再將它丟高!連續接住4根火炬，就回來找我。$B$B當心點!要是火炬掉到地上可是很危險的!別漏接了!如果你真得漏接了，你就得回到營火前重新再來一次。祝你好運啦!', '連續接住4根火炬，然後跟吞火者大師談話。', '連續接住4支火把', '去找吞火者大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11924, 'zhTW', '接住更多的火炬', '接火炬當然可以讓你保持清醒。你以為你可以持續很久嗎?$B$B走著瞧吧…', '連續接住10根火炬，然後跟吞火者大師談話。', '連續接住10支火把', '去找吞火者大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11925 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11925, 'zhTW', '接住更多的火炬', '接火炬當然可以讓你保持清醒。你以為你可以持續很久嗎?$B$B走著瞧吧...', '連續接住10根火炬，然後跟吞火者大師談話。', '連續接住10支火把', '去找吞火者大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11926, 'zhTW', '投擲更多的火炬', '哈囉，火焰雜耍師!你燒得開心嗎?那就是我想聽到的事!現在，你覺得自己是個火炬投擲的專家嗎?既然這樣的話我有個測試給你...$B$B你知道規則:將火炬投擲到標記的火盆裡。不過，這一次你擁有的時間變少，你得投中的火盆更多了。$B$B準備好了嗎?', '在火炬投擲遊戲中獲勝，然後跟吞火者大師談話。', '擊中20個火盆', '去找吞火者大師。', '火盆已擊中', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11930, 'zhTW', '穿過越風之地', '穿過越風之地的道路就在東方，這是唯一通往龍骨荒野的途徑。在你穿越凍原的途中有許多兇險在等著你。小心天譴軍團，還有他們對於這片土地野獸的影響。最近有謠傳說，我們死去的坦卡族同胞復活，攻擊往來於龍骨荒野的馬車商隊!保護你的車隊，守護那些疏散的難民!$B$B瓦圖克‧冰誕在等著你過橋，引導你進入龍骨荒野。', '護送坦卡雷疏散者通過越風之地，瓦圖克‧冰誕在龍骨荒野的邊界等著你。', '確保通往龍骨荒野的通道', '去找龍骨荒野的瓦圖克‧冰誕。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11931, 'zhTW', '破解密碼', '我感覺到這裡的飛龍身上有一個明顯的特質，但是覆蓋在他們身上的符文含意依舊困擾著我。$B$B沒有聖典，我將需要更多時間來解譯這些符文。$B$B離這裡不遠處有一個祈倫托背叛者，卡列拉斯，他手中可能有我想要的書冊複印版。他的手下握有我進行翻譯時所需要的符文。$B$B動作快點，凡人。瑪里苟斯的力量隨著時間流逝而更加強大。', '隘境之盾的瑞洛拉茲要你去從審判官卡列拉斯身上取得蒼藍聖典，並從他的凜懼島縛法者身上取得3個幻光符文。', '', '去找北風凍原的瑞洛拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11933 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11933, 'zhTW', '盜取艾克索達之焰', '這個從艾克索達核心偷出來的火焰，讓你感到很溫暖。這股新的力量對你而言很陌生，但故事使者或許知道更多……', '將艾克索達之焰帶回去給節慶故事使者。', '', '去找節慶故事使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11934 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11934, 'zhTW', '發掘你的潛力', '今天你將解開你的法術書中的一頁，你甚至根本不瞭解它就在那兒。帶給我一點東西，然後我就會幫你把那個婊子開啟。', '拿點屎給這傢伙。', '', '去找Designer Island的Jonathan LeCraft。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11935 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11935, 'zhTW', '偷取銀月之焰', '這個從銀月城偷出來的火焰，讓你感到很溫暖。這股新的力量對你而言很陌生，但博學大師或許知道更多……', '將銀月之焰交給節慶博學大師。', '', '去找節慶傳說大師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11936 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11936, 'zhTW', '醞釀策劃', '我們的目標十分簡單。繼續隱藏避免被瑪里苟斯發現，觀察他的龍群，並且盡可能地阻撓他的行動。為此，我有事情要託付給你。$B$B藍龍將他們的龍蛋產在奧核之心的底部。暴露在如此巨大的秘法能量之下，一定會加快孵化的速度，也沒有人知道這會對他們的子嗣產生什麼影響。$B$B不過我並不算查清楚那究竟會產生什麼樣的影響。殺死那邊的龍人，然後用他們的冰凍的斧頭打破龍蛋。', '隘境之盾的瑞洛拉茲要你殺死凜懼島龍人，然後使用他們的冰凍的斧頭去打破5顆藍龍蛋。', '', '去找北風凍原的瑞洛拉茲。', '龍蛋已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11937 AND `locale` = 'zhTW';
DELETE FROM `quest_template_locale` WHERE `ID` = 11938 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11938, 'zhTW', '爭取一點時間', '現在我們有了骨匣，要得到我需要的資訊應該沒有問題。在聖城裡的天譴軍很快就會注意到異狀，然而。$B$B我無法在這裡抵擋他們的全面攻擊。也許我可以...但我寧可不要被發現。$B$B我要你前往那裡並且製造一些損傷。但願這能讓他們分神夠久，足以使這兩個傢伙吐出腸子來...當然，只是打個比方。帶著路瑞德，他可以提供一些幫助。', '北風凍原上悲嘯通靈塔中的薩沙理安要你對恩吉拉聖城中的天譴軍團造成20人的傷亡。你可以使用路瑞德的骨頭來協助你。', '', '去找北風凍原的薩沙理安。', '恩基拉的傷亡者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11939 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11939, 'zhTW', '？？？？？', '[PH]用來結束此任務鏈的任務——召喚並擊殺一隻成年幼龍(菁英？)——在地城中與幼龍戰鬥？', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11940 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11940, 'zhTW', '獵龍', '我需要更多的雛龍來繼續研究符文對他們身體的改變。$B$B它們能在西北方山谷的邊緣找到...$B$B<瑞洛拉茲拿長矛劃開自己的手，在矛尖沾上他的血。>$B$B帶著這個，然後對他們使用長矛。等待他們被制服，然後效果解除之前把他們帶回來找我。', '瑞洛拉茲要你使用染血的長矛來制服一隻奧核雛龍，然後帶回隘境之盾交給他。', '', '去找北風凍原的瑞洛拉茲。', '已捕獲奧術龍獸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11941 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11941, 'zhTW', '謎題...', '這個金屬碎片有某種力量阻礙了你施法。$B$B或許瑞洛拉茲可以壓抑一些它的效果。', '將閃爍碎片交給隘境之盾的瑞洛拉茲。', '', '去找北風凍原的瑞洛拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11942 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11942, 'zhTW', '真言', '巫妖已經招了，$n。恩吉拉的高階祭司握有進入納克薩爾的秘密。$B$B前往鮮血尖塔、苦痛尖塔與凋零尖塔，並殺死每個祭司。$B$B當你拿到三個卷軸之後再回來。', '悲嘯通靈塔的薩沙理安要你前往恩吉拉聖城，並且從苦痛尖塔回收高階祭司塔烈卡的卷軸;從凋零尖塔回收高階祭司納菲賽特的卷軸，以及從鮮血尖塔回收高階祭司安杜拉斯的卷軸。', '', '去找北風凍原的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11943, 'zhTW', '囚籠', '你發現了一個特殊監牢的碎片，$n。$B$B瑪里苟斯的手下使用類似的監牢囚禁被抓到的法師以及其他秘法實體，但這個監牢是製造來囚禁某種...更強大的...$B$B希望我們敵人的敵人能夠成為一個朋友，你要去找到這個監牢的其他碎片。$B$B它們可能由瑪里苟斯最信賴的部下所保管。', '隘境之盾的瑞洛拉茲要你從天藍將軍身上取得監禁外殼，以及從戰爭使者寇瑞卓克身上取得能量之核。', '', '去找北風凍原的瑞洛拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11944 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11944, 'zhTW', '受到包圍!', '我們的情況幾近絕望。我們受命帶領少數的人去拿下悲嘯通靈塔。$B$B如果我們能夠守住這個位置對抗天譴軍團，我們就很幸運了。我們人數不多，受傷且無逃生路徑。$B$B如果你能替我們減輕一下壓力，我們或許就能守住我們的位置。殺掉一些圍住建築物的不死族 - 我們將會拖延他們前進。', '死亡看臺的下士維恩要你去殺掉7個通靈塔防衛者。', '', '去找北風凍原的下士維恩。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11945 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11945, 'zhTW', '作最壞的打算', '黑暗的時代降臨。卡庫特之靈行走於大地，收集巨牙海民的亡魂。$B$B迷霧之子奪走了諸多同胞，不久，摯愛的卡斯卡拉也會化為灰燼。$B$B然而，希望仍未破滅。或許不光是為了我們，但我們已經把家人送到昂紐沛。我們在此抵抗，是為了他們的將來。$B$B他們需要補給，否則就要挨餓了。昂紐沛的存糧不足，在事情太遲以前替我們的家人保住所有的補給吧!', '戊塔克需要你在卡斯卡拉收集8個卡斯卡拉補給品。', '', '去找北風凍原的戊塔克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11947 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11947, 'zhTW', '反擊', '我們必須以行動來維持平衡!時間對我們相當不利。$B$B淒涼之地西北邊的艾瑟雷索，有個營地藏在它的陰影之下。他們使用冰石和元素溝通，就像是希利蘇斯那樣。雖然我不喜歡這樣，那些精靈會瞭解的 - 你必須要召喚艾胡恩手下的一個副官，並且摧毀它。或許這樣先發制人的行動會有效……', '把冰石召喚出來的冰雹副官殺死，冰石就在淒涼之地的艾瑟雷索。然後向主城中的陶土議會長老回報。', '', '去找陶土議會長者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11948 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11948, 'zhTW', '反擊', '我們必須以行動來維持平衡!時間對我們相當不利。$B$B奈普圖隆一直以來都在荊棘谷西岸小島上有個基地。暮光教派在此設立了冰石，來和獵潮者的國度溝通，就像是希利蘇斯那樣。雖然我不喜歡這樣，那些精靈會瞭解的 - 你必須要召喚艾胡恩手下的一個副官，並且摧毀它。或許這樣先發制人的行動會有效……', '把冰石召喚出來的冰風副官殺死，冰石就在荊棘谷西邊的水元素小島。然後向主城中的陶土議會長老回報。', '', '去找陶土議會長者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11949 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11949, 'zhTW', '決心一戰!', '卡斯卡拉對我們而言是個聖地，$r。我們的祖先在塔尤卡之靈的指引下來到此地。$B$B但迷霧中那些污穢的生物就這樣毫無理由的攻擊我們。$B$B我們要讓他們瞧瞧我們手中的長矛不是只會用來獵鯨。和我們並肩作戰，朋友。或許我的同胞有一天會報答你。', '阿泰卡要你在卡斯卡拉殺死12個科瓦迪爾劫掠者。', '', '去找北風凍原的阿泰卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11951, 'zhTW', '誘餌與攻擊', '在我被俘虜的時候，我學到了很多關於瑪里苟斯的事情。命運讓我們現在可以利用這些知識來對付他。$B$B這裡有一隻強大的藍龍，薩拉苟莎，在奧核之心的高處盤旋。她是守護巨龍的護衛也同時是他的伴侶。如果任何嚴重的威脅產生，她就會警告他的主人。$B$B被俘虜的時候我在薩拉苟莎手上吃了很多苦頭，現在該是她死去的時候了。但首先，我們得設下一個完美的誘餌...', '凱瑞史卓莎要你從凜懼島四周收集10個晶化法力裂片。如果你弄丟了增強的秘法監牢，和隘境之盾的瑞洛拉茲談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11952 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11952, 'zhTW', '反擊', '我們必須以行動來維持平衡!時間對我們相當不利。$B$B灼熱峽谷的觀火嶺是暮光教派在此地的活動基地。最近他們透過冰石來和獵潮者的國度溝通，就像是希利蘇斯那樣。雖然我不喜歡這樣，那些精靈會瞭解的 - 你必須要召喚艾胡恩手下的一個副官，並且摧毀它。或許這樣先發制人的行動會有效……', '把冰石召喚出來的嚴寒副官殺死，冰石就在灼熱峽谷的西北部，觀火嶺底下的洞穴。然後向主城中的陶土議會長老回報。', '', '去找陶土議會長者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11953 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11953, 'zhTW', '反擊', '我們必須以行動來維持平衡!時間對我們相當不利。$B$B希利蘇斯是暮光教派的艾澤拉斯基地。他們在北部透過新的冰石來和獵潮者的國度溝通。雖然我不喜歡這樣，那些精靈會瞭解的 - 你必須要召喚艾胡恩手下的一個副官，並且摧毀它。或許這樣先發制人的行動會有效……', '把冰石召喚出來的冰川副官殺死，冰石就在希利蘇斯北部的暮光小徑。然後向主城中的陶土議會長老回報。', '', '去找陶土議會長者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11954 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11954, 'zhTW', '反擊', '我們必須以行動來維持平衡!時間對我們相當不利。$B$B為了確保艾胡恩能夠成功，暮光教派在德拉諾靠近黑暗之門的地方建立了一個基地。他們透過冰石來協助冰霜領主的抵達。雖然我不喜歡這樣，那些精靈會瞭解的 - 你必須要召喚艾胡恩手下的一個副官，並且摧毀它。或許這樣先發制人的行動會有效……', '把冰石召喚出來的冰川聖殿騎士殺死，冰石就在地獄火半島靠近黑暗之門的地方。然後向主城中的陶土議會長老回報。', '', '去找陶土議會長者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11955 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11955, 'zhTW', '艾胡恩，冰霜領主', '我相信你有足夠的力量能承擔我們眼前的責任。我們不能容許暮光教派和奈普圖隆的納迦異端實現他們的計畫。為了艾澤拉斯以及這塊土地上所有的生命，我們一定要行動。我們的目標十分明確，你必須前往盤牙蓄湖中的奴隸監獄，去找我們在那邊的薩滿。去吧，要快!', '前往贊格沼澤的盤牙蓄湖，進入其中的奴隸監獄，並且和紐瑪·雲女交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11956 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11956, 'zhTW', '尋找骨匣', '沒有時間閒聊了，$n。我被派來進行這個本應是自殺的任務:佔領這座通靈塔。但我已經完成了身為士兵的職責，現在是時候找出些答案來了。$B$B這個巫妖有我在尋找的情報，但我沒辦法傷害他的肉體來逼供。$B$B巫妖將他的靈魂藏在骨匣中;找不到骨匣，我就無法從它口中刺探出情報。$B$B回到營地去找我的愛馬幽暮，她會帶領你找到骨匣。把它帶來給我。', '前往死亡看臺騎上幽暮，找到塔那薩爾骨匣的位置。然後把它帶回來交給悲嘯通靈塔的薩沙理安。', '', '去找北風凍原的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11957, 'zhTW', '薩拉苟莎的下場', '使用你找來的法力水晶，我做了這個能量聚合體。$B$B薩拉苟莎是個貪吃的傢伙。她不可能抵抗這樣的誘惑。其中蘊含著大幅削弱她的魔法。接下來就只能期待她沒有識破我們的陷阱...$B$B做好準備，$n，等你準備好面對薩拉苟莎再告訴我。', '凱瑞史卓莎要你使用能量聚合體來引誘薩拉苟莎，然後擊敗她。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11958 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11958, 'zhTW', '不可浪費', '獾狼怪一直以來是我們的天敵，但你們對大龍骨荒野的入侵，卻因為生存空間減少而迫使他們往北遷移。$B$B再加上今晨大地所發生的劇變，他們比起以往顯得更加具攻擊性。他們掠奪了我們的貨物數次...那些貨物可是我們所仰賴遠離家園的物資。$B$B作為善念與友誼的象徵，請將我們的貨物從落雪林地的獾狼怪身上奪回來。', '從獾狼怪身上奪回6個被偷取的默亞基貨物。將貨物交還給默亞基港的長者科納尼。', '', '去找龍骨荒野的長者科納尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11959, 'zhTW', '殺掉洛根', '情勢每況愈下，而我們只能採取唯一的手段...很遺憾，洛根非死不可!$B$B他是落雪林地部族中的首領，也是一頭兇猛的獾狼怪。但也唯有如此，才能在他們不斷的進攻與掠奪糧食中獲得短暫的喘息。$B$B你可以在「血肉撕裂者」的小屋前找到他，就在林地北方的高崗上。他比他的族人大得多，你不會錯過他的。殺掉他，將他的血塗滿你全身，如此才能展現你的支配權並令他們尊敬。', '將洛根之血塗抹在你身上之後，向默亞基港的長者科納尼回報。', '', '去找龍骨荒野的長者科納尼。', '洛古恩的血已塗抹', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11960, 'zhTW', '計畫未來', '如果我們有機會存活下來，我們應該要當機立斷地對付獾狼怪。但我擔心我們過度的狂熱可能會造成他們大量的死亡。$B$B落雪林地獾狼怪也和我們一樣同樣有生存的權力。你和我要看看他們是否能把握這個機會。$B$B如果長者科納尼還沒問過你，他大概會請你出面跟他們交涉。當你前往北方的林地時，我希望你收集一些他們的小熊怪。', '收集12個落雪林地小獾狼。把他們交給默亞基港的陷捕者茂伊。', '', '去找龍骨荒野的陷捕者茂伊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11961, 'zhTW', '精靈在看照著我們', '強大的精靈在看照我的部落 -- 卡斯卡拉將不會失敗。$B$B依斯里魯克將會賜予我們勇氣，塔尤卡將會確保我們能找到食物與棲身之所，而卡庫特將會看照我們的逝者，讓他們不致迷失。$B$B依斯里魯克的引導是我們目前最需要的。我請我的姪子埃魯克把依斯里魯克的圖騰給帶回來，但科瓦迪爾的長矛殺死了他，他的屍體落入了北方的水中。把圖騰帶回來給我，$n。別讓我姪子死得毫無價值。', '尼約德之息海灣的長者穆亞希要你進入水中去尋找埃魯克的屍體，並且拿回依斯里魯克的圖騰。', '', '去找北風凍原的長者穆亞希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11962, 'zhTW', '最後一次遞送', '就是這個。加上你最後搶救出來的礦石，我們現在有足夠的量可以送給驍勇要塞了。$B$B如果遠郡會被從艾澤拉斯的表面上抹去，那起碼讓我們可以記得是誰第一個守護我們土地，而是誰最後一個放棄。$B$B帶著這塊礦石給希爾妲‧石鑄 - 她是我的一位好友。告訴她用這塊礦石做出一點好武器來。接下來的日子我們會需要很多。', '把遠郡礦石箱送交給驍勇要塞的希爾妲‧石鑄。', '', '去找北風凍原的希爾妲‧石鑄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11964, 'zhTW', '夏日小焦焰的薰香', '你知道節慶火焰在每個聯盟營地都有嗎?火焰看守者在每個城鎮之外照顧它們，確保營火明亮和慶典的維持。$B$B每位火焰看守者都有一個夏日小焦焰陪伴 -- 火焰精靈的使者。$B$B你想要向小焦焰獻上敬意嗎，$N?帶著這個夏日薰香，把它交給任何一個夏日小焦焰。取悅那些火焰小精靈，它或許會回報你。', '節慶博學大師要你把夏日薰香帶給任何一座聯盟據點外的夏日小焦焰。', '', '去找夏日小焦焰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11965, 'zhTW', '集結!', '遠郡現在還有一絲機會，$n。這是我們全力換來的，也是靠著你的幫助。$B$B我們現在只需要一個集結點。我已經讓手下把武器運送到市鎮廳。去敲響市鎮廳的警鐘，好讓倖存者可以在那邊集結。$B$B該是時候讓天譴軍團瞧瞧我們的骨氣。', '前往遠郡的市鎮廳，敲響裡面的警鐘。', '', '去找北風凍原的吉羅德‧葛林。', '遠陽郡的鐘已敲響', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11966, 'zhTW', '節慶小焦焰薰香', '你知道節慶火焰在每個部落營地都有嗎?火焰守護者在每個城鎮之外照顧它們，確保營火明亮和慶典的維持。$B$B每位火焰看守者都有一個節慶小焦焰陪伴 -- 火焰精靈的使者。$B$B你想要向小焦焰獻上敬意嗎，$N?帶著這個夏日薰香，把它交給任何一個節慶小焦焰。取悅那些火焰小精靈，它或許會回報你。', '節慶故事使者要你把夏日薰香帶給任何一座部落據點外的節慶小焦焰。', '', '去找節慶小焦焰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11967, 'zhTW', '召集紅龍', '瑪里苟斯一定注意到有些事情不對勁。$B$B我瞭解他，他的注意力很片段。我相信等他知道他最珍愛的薩拉苟莎發生了什麼事，我一定可以把他從他安全的領域中引誘出來。$B$B盡快帶我去找瑞洛拉茲，$n。他必須要召集所有他指揮的龍群來面對瑪里苟斯。', '凱瑞史卓莎請你帶她去隘境之盾找瑞洛拉茲。', '', '去找北風凍原的瑞洛拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11968, 'zhTW', '局勢轉變', '靈魂聽見我們求援的哭喊，$n。這或許表示還有機會拯救卡斯卡拉。$B$B趁著天候造成的混亂，去殺死科瓦迪爾領袖。我相信你的行動一定能扭轉戰局。', '長者穆亞希要你去尼約德之息海灣殺死可怕的海嘉爾。', '', '去找北風凍原的長者穆亞希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11969, 'zhTW', '發動陷阱', '我們能贏得這個機會大半都靠著你的努力，$n。$B$B只有你最適合去展開對瑪里苟斯的攻擊行動。$B$B帶著這個燃信，然後在奧核之心的西北部使用它來點燃火源信號。凱瑞史卓莎會在那裡指示你下一步的行動。', '瑞洛拉茲要你在凜懼島的火源信號使用瑞洛拉茲的燃信。', '', '去找北風凍原的瑞洛拉茲。', '已引誘馬利高斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11970, 'zhTW', '夏日傳說大師', '節慶固然是個歡樂與笑語的時刻，然而讓你知道這個節日的由來也很重要。教育是一種需要追求並且細細品味的東西。聯盟主城的節慶博學大師能夠引領你。去好好學習吧。', '和聯盟主城的任何一位節慶博學大師談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11971, 'zhTW', '夏日故事使者', '節慶固然是個歡樂與笑語的時刻，然而讓你知道這個節日的由來也很重要。教育是一種需要追求並且細細品味的東西。部落主城的節慶故事使者能夠引領你。去好好學習吧。', '和部落主城的任何一位節慶故事使者談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11972 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11972, 'zhTW', '艾胡恩裂片', '這些裂片不祥地震動著。它們蘊含著冰霜領主的最後精華嗎?', '將寒冰裂片交給魯瑪·天空之母。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11973 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11973, 'zhTW', '戰俘', '瑪里苟斯讓凱瑞史卓莎成為他的伴侶!$B$B我們不能讓這種事發生。$B$B$r，你必須盡全力使她免於遭受此種命運。', '戰爭法師凱特林要你釋放凱瑞史卓莎。', '', '去找北風凍原的瑞洛拉茲。', '克里斯塔莎已安息', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11974 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11974, 'zhTW', '[ph] Now, When I Grow Up...', '', '', '薩蘭德莉亞造訪銀月城的L70ETC樂團', '去找血精靈孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11976, 'zhTW', '寒冰裂片', '這些裂片不祥地震動著。它們蘊含著冰霜領主的最後精華嗎?', '將寒冰裂片交給魯瑪·天空之母。', '', '去希爾斯布萊德丘陵找達隆山的魯瑪·天空之母。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11978 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11978, 'zhTW', '進入窪地', '在我們能正式讓這些坦卡族加入部落之前，我們必須要從附近樹林出沒的阿努巴奈幽蟲族手中取回我們的武裝。前幾天夜裡由阿格瑪之錘出發的車隊被天譴軍突襲，武裝也丟失了。$B$B進入西風難民營東方的樹林，去取回那些武裝，$r。', '龍骨荒野，西風難民營的特使亮蹄要你去找回10個部落武裝。', '', '去找龍骨荒野的特使亮蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11980 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11980, 'zhTW', '部落的驕傲', '我是獲選護送武器裝備運輸車隊的守衛之一。攻擊來得迅速而且毫無前兆。我們奮力抵抗並且殺死了幾十隻野獸，但它們實在太多了。$B$B托辛和我勉強活了下來...$B$B如果不是因為我們的傷勢，我們早就親自進入森林獵殺那些魔鬼。你願意幫助我們挽回我們的尊嚴嗎?在森林中搜索那些阿努巴奈幽蟲族並且殺光它們!為了部落!', '血衛士羅奇爾要去殺死15隻阿努巴伏擊者，他就在龍骨荒野的西風難民營。', '', '去找龍骨荒野的血衛士羅奇爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11982, 'zhTW', '巨石橫飛', '我們下方就是鐵矮人自古以來的領地——索爾莫丹。幾千年前，石巨人踏裂了大地，將那座地底城市的一部分永遠掩埋在了坍塌的山石之下，另一部分則暴露出了地表，幾近毀滅。$B$B然而，直到今天，那些鐵矮人仍在試圖奪回他們過去的王城，但我們絕不會允許。我手下的巨人們每天都在用巨巖與碎石填補著他們挖出來的溝壑，希望能阻止他們的進犯，讓他們永遠放棄這裡。你也帶上一些巨石到東北方的溝壑邊去，幫助我們徹底毀滅敵人的頑抗吧。', '在丘陵上俯瞰索爾莫丹的庫倫要求你向索爾莫丹的露天區域投擲石塊，以此騷擾鐵矮人的挖掘工作。', '', '去灰白之丘找巨石丘陵的庫倫。', '騷擾鐵矮人的工作', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11983, 'zhTW', '部落的血誓', '他們都準備好了，$n。這些坦卡族都願意加入部落，寧願犧牲一切也要將天譴軍團逐出這個世界。$B$B<亮蹄交給你一個印有部落徽印的卷軸。>$B$B這個卷軸中寫著部落的血誓。傳統上我們要讓我們新加入的坦卡兄弟姊妹複述其中神聖的字句。$B$B帶著這個卷軸讓坦卡族宣誓加入部落，指揮官。等你完成任務，拿著卷軸回來找我。', '和西風難民營中的坦卡族交談，讓他們其中5個人宣誓加入部落。完成之後帶著部落的血誓回去找特使亮蹄。', '', '去找龍骨荒野的特使亮蹄。', '陶爾金已加入部落', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11984, 'zhTW', '把籠子裝滿', '老霸德也有過輝煌的日子。$B$B但自從我們在鬼魂之地以來，他就對我們一點用也沒有了。我們得自己想辦法謀生，以現在來說就是把食人妖賣給出價最高的買家。$B$B幸運的是，我們最近找到了霸德的用處。他的身分讓他可以跟本地的食人妖打交道，所以我們教了他一些把戲，以便讓我們獲利。$B$B你自己去看。跟霸德聊聊，帶他去德拉克辛遺跡西南邊，當他逮到食人妖的時候馬上使用這個籠子。', '花崗岩之泉的山米爾要你對著被霸德擊昏的寒冰食人妖使用賞金獵人的籠子。', '', '去找灰熊丘陵的山米爾。', '已活捉冰霜巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11985, 'zhTW', '進入缺口', '如果我們無法打倒鐸爾莫丹內部的防衛者，鐵矮人就可以堅守下去。土靈只能勉強控制那些由鐵之子所建造的傀儡，但他們無法攻入城市。$B$B隧道縮窄得太快，我的巨人們根本無法使用，所以我們沒有多少選擇。你願意進入城市中，殺死他們的指揮者嗎?', '在可以俯瞰鐸爾莫丹的山丘上的庫倫要你殺死鐵族長阿爾古姆。', '', '去找灰熊丘陵的庫倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11986, 'zhTW', '破損的日誌', '這本破損、沾滿污泥的日誌經歷過了不少日子。匆匆翻過書頁，你發現許多筆記、圖示與地圖。$B$B作者的手寫字跡有種模糊的熟悉感，但你直到發現了布萊恩‧銅鬚你才認出來。$B$B這本冊子的後半部，包含了最近的才寫的內容，已經被扯掉了。書頁落在戰場上，除非找到完整的書頁，否則誰也不知道布萊恩最後到底發現了什麼。', '找回8頁失蹤日誌紙頁，將它們和不完整的日誌黏合起來，然後將完整的日誌交給西部荒野民兵團駐營的多杉‧深掘。', '', '去找灰熊丘陵的多杉·深掘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11988 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11988, 'zhTW', '符刻拱心石', '布萊恩的日誌中提到，他使用一種符刻拱心石來啟動他所發現的金屬板中的重要符文。沒有那個拱心石，金屬板只比廢鐵好一些。$B$B在布萊恩最後一次進入時，他寫到鐵矮人防衛者搶走了他的拱心石，並且打破了它，然後分別保管。在我們能解讀符文金屬板之前，我們必須要找到碎片。任何鐸爾莫丹或附近建築中的矮人都有可能帶著碎片。', '西部荒野民兵團駐營的多杉‧深掘要你帶給他5個符刻拱心石碎片。', '', '去找灰熊丘陵的多杉·深掘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11989 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11989, 'zhTW', '休戰?', '注意一點，老兄。$B$B德拉庫魯縮皺過的$r人頭多到我都記不清了 - 就算我記得，我也數不了那麼多。多虧我被關在這個籠子裡，否則名單上的倒楣鬼恐怕又要多一個了。$B$B不過事情就是這樣，也許我們應該把彼此的歧見先放到一邊，嗯?$B$B德拉庫魯知道很多事情，老兄。一些可以幫助你在此地的事情。$B$B<德拉庫魯用獠牙在掌心劃了一道，然後把手伸出籠子外。>$B$B你覺得怎麼樣，老兄...休戰?', '花崗岩之泉的德拉庫魯要你在他籠子附近使用粗鈍的雕刻刀，然後再和他交談。', '', '去找灰熊丘陵的德拉庫魯。', '與達庫魯的血之契約', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11990 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11990, 'zhTW', '幻象之瓶', '一步一步來，老兄，有些準備工作要做。$B$B沒人告訴我他們要把我關多久，你需要一罐強猛的藥劑我們才能保持聯繫。$B$B你走狗運啦，我剛好知道那東西!材料又剛好都在附近。$B$B我要那邊那個食人妖小子身上的瓶子，北邊湖裡的水蘊草，還要一些海茲伍灌木葉。$B$B快去快去，老兄，他們就要把我拖走啦!', '花崗岩之泉的德拉庫魯要你帶給他1個水晶瓶、1片水蘊草藻葉和3片海茲伍灌木葉。', '', '去找灰熊丘陵的德拉庫魯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11991 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11991, 'zhTW', '呈交翻譯', '有一套傳說中的神器，為了保衛德拉克薩隆要塞而被創造出來，失傳了千年之久。$B$B大多數的人認為這些神器只是傳說，但是德拉庫魯很清楚，老兄!$B$B我差一點就能發現神器在哪，卻在解讀象形文字的時候被逮了。你得把我的靈魂召喚回去那裡，我才能夠把它讀完!$B$B去德拉克辛遺跡的火盆使用我的藥劑，遺跡就在西南方而已。你得摻入我弟兄的冰凍魔精，我雖然不忍看到我的弟兄被殺害，但是這可是為了更偉大的未來而做的犧牲。', '德拉庫魯需要你從德拉克辛遺跡的德拉克瑞食人妖身上獲得5個冰凍魔精，然後在德拉庫魯的火盆上使用藥劑。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11992 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11992, 'zhTW', '海圖', '你在龍皮上發現了海圖的一部分。如果能拼湊出完整的海圖，或許可以瞭解克瓦迪爾未來的攻擊計劃。$B$B裂鞭海岸的水手身上說不定就攜帶著海圖的缺失部分。卡魯克應該會對上面的內容感興趣吧。', '將斯卡迪爾海圖的缺失部分交給裂鞭海岸的卡魯克。', '', '去找北風凍原的卡魯克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11993 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11993, 'zhTW', '符文預言', '我們沒有時間可以浪費了!現在我們結合了符刻拱心石 -- 嗯，大部分的 -- 就可以解讀布萊恩在逃跑前所研讀的文獻。$B$B我們不知道他是否研讀過三個金屬板，但我們可以假設他已經取得足夠的資訊，讓他前往下一個目的地。$B$B在每一塊金屬板之前，使用拱心石解讀文獻。布萊恩也許就靠我們了!', '西荒兵團駐營的多杉·深掘要你解讀三塊符文板。', '', '去找灰熊丘陵的多杉·深掘。', '解讀第一段預言', '解讀第二段預言', '解讀第三段預言', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11994 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11994, 'zhTW', 'Juno/s Flag Tester[日常]', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11997, 'zhTW', '再次向格裡安·斯托曼報到', '月溪旅奉命轉至灰白之丘東北部，確保那裡的通行安全。他們在灰喉堡東北方、索爾莫丹西南方創建了一處營地。$B$B你應該認識月溪旅的領袖格裡安·斯托曼上尉吧？在對抗羅德隆天譴軍團的戰役中，格裡安立下了赫赫戰功。但他卻毅然決定離開戰場，返回西部荒野對抗迪菲亞兄弟會。', '與月溪旅營地的格裡安·斯托曼上尉談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11998, 'zhTW', '動之以情', '讓我們的部隊能最快前往寒冰皇冠的方法，就是透過上古鐵矮人城市鐸爾莫丹之下的隧道網。$B$B布魯嘉‧石聽和他的探險者協會成員大概會不太爽，不過命令就是命令。$B$B要是你能帶給他一桶紅木貿易站的陷捕者，休‧格雷斯所賣的私釀酒，事情會好談一些，貿易站就在東南方靠近林線的地方。$B$B那個傢伙腦袋有點不太正常，不過在這裡你找不到比他更好的私釀酒了。', '帶給布魯嘉‧石聽一桶嚎爽私釀酒，他就在西部荒野民兵團駐營。', '', '去找灰熊丘陵的布魯嘉·石聽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11999 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11999, 'zhTW', '搜索屍體', '西南邊的月眠花園是一群精靈貴族的最後安息地。同時也是一個地脈核心。$B$B藍龍軍團在使用一種叫做極濤磁針的魔法裝置要摧毀核心，將能量釋出好讓他們可以隨意重新導向。$B$B我需要更多的訊息，而你要幫我取那些訊息!$B$B在那個地方被摧毀成遺跡之後，精靈貴族的鬼魂重新甦醒，殺死了那邊大半的狩法獵人。去搜索他們的屍體尋找線索。', '找出月眠花園計畫書，並交到阿格瑪之錘給大法師埃薩‧奪日者的影像。', '', '去找龍骨荒野的大法師埃薩‧奪日者的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12000 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12000, 'zhTW', '搜索屍體', '西南邊的月眠花園是一群精靈貴族的最後安息地。同時也是一個強大的地脈核心。$B$B藍龍軍團在使用一種叫做極濤磁針的魔法裝置要摧毀核心，將能量釋出好讓他們可以隨意重新導向。$B$B我需要更多的訊息，而我希望你能幫我取得那些訊息。$B$B在那個地方發生劇變而變成遺跡之後，精靈貴族的鬼魂重新甦醒，殺死了那邊大半的狩法獵人。去搜索他們的屍體尋找線索。', '找出月眠花園計畫書，並帶去繁星之眠給大法師莫德菈的影像。', '', '去找龍骨荒野的大法師莫德菈的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12001, 'zhTW', 'zzOLDHunting Tarot: Lesser Beasts[日常]', '仔細看著這些牌，影像開始有些模糊，直到你看見自己披著許多野狼與棕熊的毛皮站在那邊。你只能假設你註定要喚醒塔羅牌的力量。', '收集12張破損的皮革，然後使用狩獵塔羅牌召喚獵人。破碎的皮革只能從5級或以上的野獸身上取得。', '', '去找Designer Island的Jonathan LeCraft。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12002 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12002, 'zhTW', '戰鬥中的弟兄', '我希望格里安知道我在戰鬥開始的時候就把我的手下撤離了鐸爾莫丹。在這裡穩定下來之前，我們不可能挖掘任何東西。$B$B你看起來像是個勇敢的人，而且你也有斯托曼的信任。$B$B鐸爾莫丹就在我們的東北邊，而在我們的土靈弟兄和鐵矮人造物之間的戰鬥依舊激烈。盡量幫助我們的弟兄，我會開始想辦法找出我們該如何完成鐸爾莫丹的測量。', '殺死10個符刻戰鬥魔像然後向西部荒野民兵團駐營的布魯嘉‧石聽回報。', '', '去找灰熊丘陵的布魯嘉·石聽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12003 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12003, 'zhTW', '發掘隧道', '我搜尋鐸爾莫丹隧道系統入口的第一個地點就是偏遠的建築群。$B$B當我帶著我的手下離開時，那些鐵矮人防衛者似乎正在建築中安置難民。在你探索的時候請務必小心。$B$B任何隧道入口都有可能會通往那些建築。我不確定斯曼托希望我們找些什麼，但我很懷疑鐵矮人會任由我們這樣調查。', '西部荒野民兵團駐營的多杉‧深掘希望你去探索鐸爾莫丹的北部建築、東部建築和南部建築。', '', '去找灰熊丘陵的布魯嘉·石聽。', '調查北方建築', '調查東方建築', '調查南方建築', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12004 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12004, 'zhTW', '阻礙協議', '我們需要來個一石二鳥，$c。而你就是那顆石頭。$B$B我們的兩隻鳥就是風之貿易者穆法和戈拉莫什。他們應該就在月眠花園西半邊的某處，最可能的地方就是能夠俯瞰深淵的大型兩層建築中。$B$B我希望能驗證他們的亡故，如果你願意效勞的話。', '將風之貿易者穆法的殘骸和戈拉莫什的鱗片帶去繁星之眠給大法師莫德菈的影像。', '', '去找龍骨荒野的大法師莫德菈的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12005 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12005, 'zhTW', '阻礙協議', '我們需要來個一石二鳥，$c。而你就是那顆石頭。$B$B我們的兩隻鳥就是風之貿易者穆法和戈拉莫什。他們應該就在月眠花園西半邊的某處，最可能的地方就是能夠俯瞰深淵的大型兩層建築中。$B$B我希望能驗證他們的亡故，如果你願意效勞的話。', '將風之貿易者穆法的殘骸和戈拉莫什的鱗片交給大法師埃薩‧奪日者的影像，位在阿格瑪之錘。', '', '去找龍骨荒野的大法師埃薩‧奪日者的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12006 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12006, 'zhTW', '為暴行復仇!', '這些被稱為狩法獵人的生物闖入並毀掉了我們的居地。$B$B為我們復仇，否則我會確保你的軍事基地被亡靈大軍給輾過!', '殺死總計15名的龍骨荒野狩法獵人、月眠巡者、極濤磁針巫士或節點巫師。完成之後向月眠花園的伊希尼歐‧月影回報。', '', '去找龍骨荒野的伊希尼歐‧月影。', '月棲花園的藍龍軍團已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12007 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12007, 'zhTW', '犧牲是必要的', '我知道了，老兄!$B$B就在北邊，札布哈拉克的通靈塔之上，有個石像頭鑲著紅寶石眼睛。其中一顆紅寶石就是那個預言者之眼!把它帶到火盆來，然後喝下我的藥劑。$B$B當然，要讓我的藥劑作用，又會需要一些魔精 - 這次得從督軍辛波身上取來。他就躲在札布哈拉克的小屋裡。$B$B殺死辛波是件可恥的事，老兄，但他立下血誓要守護德拉克薩隆，而他卻失敗了。如今他的魔精至少可以讓我們重新奪回德拉克薩隆。', '德拉庫魯要你將預言者之眼帶給他，就在札布哈拉克的德拉庫魯的火盆處。你必須收集辛波的魔精，以便在火盆上使用德拉庫魯的藥劑。', '', '去找灰熊丘陵的德拉庫魯的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12008 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12008, 'zhTW', '阿格瑪之錘', '阿格瑪之錘就矗立在這座營地的正東方，那裡是部落的軍事力量在龍骨荒野上的最後堡壘。$B$B毫無疑問，你引導犛牛人加入部落的行為有著巨大的價值，這一點包括我在內的所有部落兄弟姐妹都看在了眼裡。我也希望你能將這個好訊息告訴阿格瑪大王。$B$B現在就出發吧，$N！與風賽跑！轉至東邊的阿格瑪之錘！', '轉至龍骨平原的阿格瑪之錘，與阿格瑪大王談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12009 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12009, 'zhTW', '突凱亞的螃蟹陷阱', '因為這些麻煩事，我失去了助手。如果可以的話你能不能幫幫我?$B$B我在港口的海面下設置了許多補蟹陷阱。你能幫我拿回來嗎?我太老了，動不了了，大海對我來說又太危險。$B$B求求你，拿著這顆氣囊，你在水面下的時候它會幫助你呼吸。', '收集8個突凱亞的螃蟹陷阱，交還給默亞基港的突凱亞。', '', '去找龍骨荒野的突凱亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12012 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12012, 'zhTW', '通知長老', '這個消息必須要通知整個陶土議會。我不確定該如何進行，但把任務交付給你的長老或許知道。拜託，回去向長老報告，並且採取下一步行動 - 我們一定得做點什麼!', '回到任何一座主城，把圖騰信號還給陶土議會長老。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12013 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12013, 'zhTW', '終結阿肯尼瑪斯', '我還有最後一件事情要你去做，$r的$n。我希望你去摧毀阿肯尼瑪斯!$B$B西邊的巫士使用那個巨大的空中裝置，在我們的安息地鑽出了巨大的深穴。他們的行徑釋放了一隻畸形的怪物!$B$B我不在意這是否與活人有關，但阿肯尼瑪斯以死者的靈體為食。$B$B你必須盡快阻止這一切!', '消滅阿肯尼瑪斯，然後回去找月眠花園的伊希尼歐‧月影。', '', '去找龍骨荒野的伊希尼歐‧月影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12014 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12014, 'zhTW', '穩若泰山？', '歐隆德的筆記指出，他攜帶了一台名叫可攜式地震儀的裝備，可是現在哪兒都找不到。$B$B調查紀錄顯示，他在鐸爾莫丹的坑道中完成了所有的讀數記載，除了一條標有「外露東部坑道底」的坑道以外。$B$B最後一條紀錄記載歐隆德躲在水底下的時候遭到地下蛇頸龍的攻擊。這些生物可能把他的裝備搶走了。在你讀取最後的讀數以前，你必須把它找到。', '拿回可攜式地震儀，並使用它讀取鐸爾莫丹的數據。最後向西部荒野民兵團駐營的布魯嘉‧石聽回報。', '', '去找灰熊丘陵的布魯嘉·石聽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12015 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12015, 'zhTW', 'Test Quest for Craig', 'klajsdklajlsd', 'Craig Amai at wherever wants you to bring him 5 whatevers.', '', 'Return to [Demo] Craig Amai.', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12016 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12016, 'zhTW', '誘餌', '我很肯定...我們遠古的水中宿敵，『獵物玩弄者』吐烏格瓦已經回來了。我們必須設下陷阱對付他，就你跟我。$B$B吐烏格瓦有一個弱點，就是他的胃。有一種肉是他絕對無法抗拒的。$B$B『雙巨螯』，蟹族之母，齊里厄雅。就在西南邊的環礁一帶的海域遊蕩。你必須去拜訪她，並且帶回她的肉來。', '取得『雙巨螯』之肉，並且把它交給默亞基港的突凱亞。', '', '去找龍骨荒野的突凱亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12017 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12017, 'zhTW', '鉤上的肉', '我的朋友，時候到了:讓我們來對付吐烏格瓦!$B$B我把肉準備好了，只要你把我的鉤子當作誘餌丟進水裡，那頭野獸一定會來的。順著釣魚線下去找牠。$B$B做什麼都行，就是別被吐烏格瓦給吞了，$n!', '殺掉吐烏格瓦，向默亞基港的突凱亞回報。', '', '去找龍骨荒野的突凱亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12019 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12019, 'zhTW', '最後的儀式', '我以死亡之軀服侍阿薩斯，是因為我沒有選擇。他宰制了我的意志與我的身體。詛咒神教以血肉之軀服侍阿薩斯…是出於自願。$B$B現在我們知道如何使用這些真言來進入納克薩爾，我們可以終結這場邪教瘟疫。前往恩吉拉，並且在浮空要塞下方尋找傳送寶珠。$B$B往上爬並且在頂端與我會合。以你所有的勇氣武裝自己，我們也許無法成功逃出生天。', '前往恩吉拉聖城並且找出浮空要塞納克薩爾下方的傳送寶珠。使用寶珠抵達塔頂，然後幫助薩沙理安。', '', '', '最後的儀式', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12020 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12020, 'zhTW', '就這麼一次，在我酒醉的時候…', '黑鐵矮人被痛扁了一頓!就在他們夾著尾巴逃回黑鐵酒吧的時候，他們還掉了一些貨物下來。最重要的是，你保住了營地…至少今天保住了。去找博克西，然後向他說明你擊敗黑鐵矮人的英勇事蹟。', '與啤酒節營地的博克西·栓旋者交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12022 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12022, 'zhTW', '乾了再砸!', '喂!看起來啤酒難不倒你。但你能好好使用啤酒杯嗎?$B$B黑鐵矮人要回來報復，毀掉我們的節慶。拿酒杯丟他們是最好的阻止方法，但首先，讓我們瞧瞧你能不能在老S.T.O.U.T.這裡丟中一個。$B$B這很簡單，拿起一杯免費招待的啤酒節樣品，然後乾了它。接下來要確定你面對著S.T.O.U.T.。等你丟中他5次之後再告訴我。', '使用免費招待的啤酒節樣品並丟中S.T.O.U.T.5次，然後和博克西·栓旋者談談。', '', '去找丹莫羅的博克西‧栓旋者。', '命中S.T.O.U.T.', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12023, 'zhTW', '甜蜜的復仇', '令人舒爽的碾壓。現在…你…$R傢伙…有個憎惡體在南方的山坡亂晃。去殺了它。好好地把它宰了。', '殺死東部腐屍農地山坡上的憎惡體。一旦殺戮完成就回去找貝維思領主。', '', '去找。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12024, 'zhTW', '記錄陣亡者', '感謝你的到來，$n。儘管我們一直沒有收到暮冬要塞那邊傳來的訊息，但我堅信，他們仍然在與天災軍團激烈地抗爭著。不過，恐怕他們也無力再支援我們，我們將在這裡獨自抵抗那座屠宰房的威脅了。$B$B首先，我們得確認那些戰死者的身份，好將他們英勇犧牲的訊息通知他們的家人。聯盟軍部將我們派駐到這裡時，所有人都填寫了身份證明文書，以清點這裡的駐軍狀況。$B$B到那些戰士們的遺體身上去找這些文書吧，有了這些文書，我就可以開始羅列陣亡將士的名單了。', '在腐臭平原的骸骨中尋找聯盟居民名單。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12026 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12026, 'zhTW', '破損的日誌', '這本破損、沾滿污泥的日誌飽經風霜。匆匆翻過書頁，你發現許多用矮人語寫成的筆記、圖示與地圖。$B$B你唯一能辨識出來的文字，是字句結尾處，布萊恩‧銅鬚潦草的簽名。$B$B這本冊子的後半部，包含了最近的才寫的內容，已經被扯掉了。某個人覺得這本筆記很重要，所以才摧毀了它。也許從戰場中收集這些遺失的書頁，可以讓你找到一些線索。', '找回8頁失蹤日誌紙頁，將它們和不完整的日誌黏合起來，然後將完整的日誌交給歐尼克瓦營地的賢者帕努納。', '', '去找灰熊丘陵的賢者帕努納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12027 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12027, 'zhTW', '軟綿綿先生的冒險之旅', '抱歉打擾你，$g先生:女士;，你知道回去軍營的路嗎？我和軟綿綿先生本來決定在樹林裡走走，而我的兄弟沃特也要跟來的，可是他有侍從工作要做只得作罷。$B$B我和軟綿綿先生自個兒來，但是迷路了，森林裡到處都是飢餓的狼群，不過，我們找到了這座塔。$B$B狼走了，可是我們還是走不出去。$B$B我問過軟綿綿先生，他也不清楚回去的路，可以幫幫我們嗎？行行好？', '幫助愛蜜莉和軟綿綿先生回到西部荒野民兵團駐營，然後再向侍從沃特交談。', '幫助艾蜜莉與軟軟先生返回營地', '去找灰熊丘陵的侍從沃特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12028, 'zhTW', '靈魂洞察', '$r，自從地震分隔之後，我再也沒有聽過因度雷村族人的消息了。$B$B你有經歷過幻象任務嗎?你打敗過洛根，你一定能夠勝任的。$B$B我會給你一些特製的薰香灑在我的火盆中。把它的煙霧用力吸進去，你的靈魂就會飄升到空中，可以看見因度雷的情況。$B$B隨著你的靈魂升起，我就可以透過你的眼睛觀察。', '完成靈魂洞察之後和默亞基港的『秘法師』托阿魯交談。', '已獲得關於因杜勒村的靈性洞見', '去找龍骨荒野的『秘法師』托阿魯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12029 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12029, 'zhTW', '燒灼的天災', '嗝！……得趕快把這些屍體燒了，免得牠們又爬起來到處亂晃。$B$B老爹以前常說，唯一比殺一次巨魔更糟的事，就是得殺牠們兩次。$B$B對了，嗝……說到天災，要是不先削減北邊那些巨魔的數量，我們就沒法打進那座巨魔要塞。$B$B你要不要拿些我的烈酒去，把那些混蛋做個了斷？', '花崗岩之泉的麥客‧菲爾森要你用他的烈酒去燒死德拉克薩隆的20隻飢餓天災巨魔。', '', '去找灰熊丘陵的麥客‧菲爾森。', '天災巨魔已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12031 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12031, 'zhTW', '解放徘徊者', '精靈在西方的聖地被蹂躪得支離破碎。如今，魔法在土地間流竄，所經之處飽受摧殘。$B$B當藍龍試著要控制這股法力的同時，卡魯耶克的靈魂陷入了危機。$B$B這股力量自湖泊竄出，瞬間就殺死了絕大多數的村民，而倖存者都陷入了瘋狂。$B$B$n，你一定要馬上釋放這些靈魂，他們才能超生。放過那些瘋狂的生物;他們還有機會能獲得理智。', '讓總計15名的因度雷漁夫、因度雷秘法師或因度雷戰士獲得安息，並向因度雷村的長者馬納洛亞回報。', '', '', '因杜勒之靈已安息', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12032 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12032, 'zhTW', '深海晤談', '我們一定要諮詢水神歐巧諾亞的意見;只有她曉得卡魯耶克的天命將歸於何處，也唯有深淵珍珠可以將她從混沌的虛空中呼喚她現身。$B$B海岸的西南方海面上是海水之巔，上面有著一座祭壇，而珍珠就在其中。$B$B在祭壇中和海神溝通，歐巧諾亞一定能聽見你的呼喚。順著她的意思去做，免得觸怒她，並讓巨牙海民招致毀滅。$B$B如果你能活著回來，向我的秘法師回報。', '透過深淵珍珠溝通，照著海神歐巧諾亞指示的去做。只要你通過了考驗，就向默亞基港的『秘法師』托阿魯回報。', '', '去找龍骨荒野的『秘法師』托阿魯。', '已遵從歐查諾亞的驅使', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12033 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12033, 'zhTW', '從西方來的消息', '<托伏斯搖了搖手，遞給你一封信。>$B$B<托伏斯壓低了聲音說。>$B$B耐心點，$n。$B$B很高興在這裡看到你，士兵!地獄吼大人果然派出了他最強的戰士來協助阿格瑪領主!$B$B<托伏斯壓低了聲音說。>$B$B讀完之後就用旁邊的火把信燒掉。', '閱讀來自薩爾法魯的信，然後把它給毀了。等你完成之後再和信差托伏斯交談。', '索爾法的信已閱讀並銷毀', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12035 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12035, 'zhTW', '改寫技術', '好吧，我懂了!重新改寫雖然有點複雜，但對於像你這樣聰明的$c應該不是問題。$B$B帶著我的工具去讓一些收割機器人『退役』。他們一倒下，你就使用工具把他們所有的紅線塞進藍色的插槽中。這會讓他們進入自我防衛模式。快一點，$n。再過不了多久，就沒東西可以搶救了。', '遠郡的杰瑞米亞‧豪寧要你摧毀5台收割機器人，然後使用杰瑞米亞的工具重新改寫它們。', '', '去找北風凍原的杰瑞米亞‧豪寧。', '豐收採集者已重新配線', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12036 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12036, 'zhTW', '從阿茲歐-奈幽的深處', '攻擊冰霧村的不死奈幽蟲族是從一個名為那金之淵的巨大深坑中出現。如果置之不理，那些怪物一定會在憤怒之門夾擊我們的部隊，而我們勝利的希望也就毀了。$B$B我需要有人監視那邊，$n。你要前往西方去調查那金之淵。我們要找出他們主要的出口並且封死它!幫我找出那個地點。', '探索那金之淵然後將你發現向阿格瑪之錘的資深士官丘科多克回報。', '已探索納爾君之坑', '去找龍骨荒野的資深士官丘科多克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12037 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12037, 'zhTW', '搜救行動', '獸人…他們就是不聽 - 嗝。你知道我在說什麼嗎，$r？庫賽爾已經跟我們在一起好幾年了。還以為她已經知道我們怎麼做事的。吸引蠢蛋進行危險的工作，然後等一切安全之後再收穫成果。有這麼難明白嗎？她就是不懂...她完全沒耐心，擅自離開，把事情全攬進自己的手上。說不定現在已經死了，但我覺得不跟著她事情很不妙，我又不敢自己一個人做 - 嗝。你怎麼說，老兄？', '花崗岩之泉的麥客要你進入德拉克薩隆，找出庫賽爾發生了什麼事。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12038 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12038, 'zhTW', '燒灼的天災', '還在等什麼，$c？那些天災巨魔可不會自己送死！$B$B你知道規矩的。到北邊的德拉克薩隆去……拿些這裡的烈酒，從遠處扔到牠們身上……嗝。然後坐下來看牠們燒個痛快就行了。', '花崗岩之泉的麥客‧菲爾森要你用他的烈酒去燒死30隻飢餓天災巨魔。', '', '去找灰熊丘陵的麥客‧菲爾森。', '天災巨魔已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12039 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12039, 'zhTW', '尤格薩倫的黑血', '『憤怒之門』安格拉薩...我看過大門的金屬發出波狀的震動，彷彿它有生命一樣!我活了50年還沒有看過金屬會「呼吸」的。$B$B只有巨牙海民對它有所瞭解。他們稱它為「尤格薩倫的黑血」還要我遠離那個東西。$B$B在西邊的冰霧村外有個深坑，叫做那金之淵。我聽說這個深坑有很多這種奇怪的礦物。如果你會去那附近，你願意幫我帶點樣本回來嗎?', '阿格瑪之錘的伯魯斯‧折鐵者要你收集10個尤格薩倫的黑血樣本給他。', '', '去找龍骨荒野的伯魯斯‧折鐵者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12040 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12040, 'zhTW', '在阿薩斯體內的敵人', '我們正處在一場內戰之中。我們族類最後的倖存者在世界的深處對抗滅族的威脅。巫妖王不惜一切代價想要支配整個阿茲歐-奈幽王國。不從者都被烙上天譴軍之敵的印記，並且被追殺至死。$B$B在阿薩斯體內有著我們共同的敵人...$B$B加入我們這方，並且消滅此處被玷污的阿努巴!讓阿努巴拉克親自聽聽牠們臨死痛苦的哀嚎!', '『排除者』齊力克斯要求你殺死6隻阿努巴地下領主。他就在龍骨荒野的那金之淵。', '', '去找龍骨荒野的『排除者』齊力克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12041, 'zhTW', '失落的帝國', '你已經證明了你願意在危急時刻協助阿茲歐帝國，而阿茲歐帝國也將會協助部落。$B$B帶著這個卷軸回去找你的領袖。裡面記錄著攻擊冰霧村的奈幽蟲族的力量與弱點。請把這個當成一種良好信念的表現 - 對你們同胞的協助。利用這些知識來擊敗阿努巴，你也是幫了我們一個大忙。$B$B再會，$r。', '將齊力克斯的作戰計畫交給霸主阿格瑪，他就在東邊的阿格瑪之錘。', '', '去找龍骨荒野的霸主阿格瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12043 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12043, 'zhTW', '鏽鼻防禦', '你，$c!我們南方的不死生物持續地干擾我們的工作。去把他們清理掉，行嗎?', '在葛拉克朗安息地周邊的挖掘場殺死12個荒原掘地工和1個荒原監工。任務完成之後向鏽鼻崗哨的納孚回報。', '', '去找龍骨荒野的納孚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12044 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12044, 'zhTW', '進貨', '嘿你好啊!南邊的天譴軍團正在挖一些上古龍之類的。我原本不想管他們為什麼要這麼做，但是他們挖出了一車車的混合礦石。$B$B幫我去帶一些那種礦物回來。部落在製造這麼多武器，這玩意一定可以賣個好價錢。', '從葛拉克朗安息地周邊的挖掘場收集8堆混合礦物，然後交給鏽鼻崗哨的辛克。', '', '去找龍骨荒野的辛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12045 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12045, 'zhTW', '銼冰', '我從沒見過你...初來乍到水晶之鉗嗎?很高興有你的幫忙。多一雙手就多一份力量。$B$B你拿到了原料，我就能完成我的機械，然後我們可以把它賣給那些當官的，賺大錢回老家?$B$B事實上，大部分的零件我都有了，我只需要一些武器本身的原料。納孚說，北邊的元素上的鋸齒狀寒冰裂片，最適合製作我炸彈中的破片了 - 快去弄一些來，好嗎?', '從北邊的冰元素身上收集4個寒冰爆裂碎片，帶回來交給鏽鼻崗哨的希伏利克司。', '', '去找龍骨荒野的希伏利克司。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12046 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12046, 'zhTW', '柔軟的彈殼', '我需要為這些榴砲彈換些新的彈殼。我本來有的材料都太硬了，導致爆炸的時候，破片沒辦法飛散開來。$B$B我需要的是夠薄的動物皮革。那些西邊的蟄猛巨蟲隧掘者可以派上用場...或者是逗留在龍骨上的兀鷹。反正把你能找到的都帶給我。', '從蟄猛巨蟲隧掘者、或龍骨兀鷹身上收集12張薄獸皮，牠們出沒在鏽鼻崗哨附近。當你拿到了獸皮，把它們給希伏利克司。', '', '去找龍骨荒野的希伏利克司。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12047 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12047, 'zhTW', '不會融化的東西', '不不不!寒冰裂片統統不能用了!它們還沒造成傷害就都融化了。我再也不會相信納孚關於原料的話了。這表示我們需要其他東西當作破片。$B$B我知道了!我真聰明，用骨頭裂塊嘛。$B$B這附近到處都是蟄猛巨蟲嚼碎過的骨頭裂塊。去找找，幫我帶一些可以用的裂塊過來。', '在鏽鼻崗哨東邊的龍骨中搜尋12根斷裂的大骨。', '', '去找龍骨荒野的希伏利克司。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12048 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12048, 'zhTW', '天譴武裝', '我根本沒辦法用這些礦石做出任何該死的東西。它們根本沒辦法連接在一起!不管我怎麼努力，這些天譴金屬就是彎不過來!$B$B如果我有一些天譴武裝的樣本，或許我能夠反推出那些物品是如何製造的。$B$B冰霧村充斥著許多重裝天譴奈幽蟲族。前去那邊幫我拿些天譴武裝回來!有了你的幫助，我或許能成功地用這些礦物做出點什麼。$B$B冰霧村就在西方。', '伯魯斯‧折鐵者要你收集8個天譴武裝，他就在龍骨荒野的阿格瑪之錘。', '', '去找龍骨荒野的伯魯斯‧折鐵者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12049 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12049, 'zhTW', '難以下嚥', '那些部隊鐵定需要一大堆食物來填飽肚子。$B$B我來告訴你這種謹慎的$r永遠不會知道的小秘密...那些蟄猛巨蟲吃起來的口感就跟雞沒兩樣。$B$B去東邊招惹一條如山的笨重蟄猛巨蟲，你大概沒法子直接殺掉一條蟲，所以你得趁牠嘴巴大開時，把這東西丟進牠的喉嚨。盡你所能地把肉片給我拖回來。', '到鏽鼻崗哨的東邊，和一頭笨重的蟄猛巨蟲戰鬥，直到牠張嘴之際，將高效爆破炸藥丟進他的喉嚨裡。當蟲爆炸以後，從地面上收集6片燒焦的蟄猛巨蟲肉帶回去給辛克。', '', '去找龍骨荒野的辛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12050 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12050, 'zhTW', '伐木', '接下來，我們需要一些木材準備給所有聯盟正在建造的哨塔。南方有一些纖細的樹木，但是北方那些鷹身人築巢的樹木更加適合建築用。$B$B帶著這個。等你抵達鷹身人築巢的地區，使用控制器，我的一台伐木機會過去找你。盡量多收集一些木材。那些鷹身人絕對不會容許你砍伐牠們的老家 - 必要的話就解決牠們吧。$B$B快去吧!', '在你抵達北方的鷹身人築巢地之後，使用辛克的伐木機控制裝置召來一台伐木機。從那個地區收集50捆的木材，然後回到鏽鼻崗哨去找辛克。如果你弄丟了辛克的伐木機控制裝置，去跟鏽鼻崗哨的辛克談話，再要一個新的。', '', '去找龍骨荒野的辛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12051 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12051, 'zhTW', '偷一些羽毛', '這些鷹身人一直在拖慢我們賺錢的速度!把她們殺光。', '替鏽鼻崗哨的納孚殺死20名鷹身人，她們就出沒在鏽鼻崗哨的西北邊。', '', '去找龍骨荒野的納孚。', '寒風鷹身人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12052 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12052, 'zhTW', '有夠囉唆!', '$c，看到沒?那就是領導攻擊的鷹身人，他們襲擊了我們要送去大門的貨物!我在冷風陵地的後方看過她。$B$B這些鷹身人一直在拖慢我們賺錢的速度!把他們殺光。', '殺死冷風之女及15名冷風鷹身人，他們出沒在鏽鼻崗哨西北邊的山區中。完成之後，向納孚回報。如果你需要辛克的伐木機控制裝置，與鏽鼻崗哨的辛克談談。', '', '去找龍骨荒野的納孚。', '', '寒風鷹身人', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12053 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12053, 'zhTW', '部落的力量', '如今，坦卡族成為了我們的戰友，我們要展現團結奪回冰霧村。$B$B阿格瑪之錘的西方你就能看見冰霧村了，坐落於山腳下。前去村子挑戰阿努巴奈幽蟲族吧!將我們熱愛的部落旌旗插在冰霧村中，然後把所有膽敢靠近撕毀旌旗的蟲族消滅!$B$B讓阿努巴感受部落的真正力量!讓他們死前最後一眼所見的東西，就是我們的旌旗!', '龍骨荒野上，阿格瑪之錘的資深士官丘科多克需要你在冰霧村中使用戰歌戰旗，護衛它免於攻擊。事成以後，將戰歌戰旗一併帶回來。', '已防禦戰歌戰旗', '去找龍骨荒野的資深士官丘科多克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12054 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12054, 'zhTW', '日誌解讀', '沃塔克是對的 -- 我們不能放過這個機會。$B$B幸好，我知道一個辦法可以翻譯這個布萊恩的日誌。$B$B紅牙熊怪的薩滿就聚集在營地南邊的心之血聖壇，他們會種植一種叫做精靈之息的草藥。他們使用以秘方製作的薰香來尋求先祖靈魂的智慧。$B$B去找一個『獨眼』格朗姆巴德的薩滿。他應該會帶著草藥去向厄索克做出奉獻。', '帶一小截精靈之息給歐尼克瓦營地的賢者帕努納。', '', '去找灰熊丘陵的賢者帕努納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12055 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12055, 'zhTW', '奇怪的裝置', '拿起這個奇怪的裝置之後，你才確定它本質充滿魔力。很可惜，這裝置看不出來有什麼用途。$B$B也許，拿給月眠花園以東、繁星之眠的大法師，可以告訴你它的用途也說不定？', '把戈拉莫什的奇怪裝置交給繁星之眠的大法師莫德菈的影像。', '', '去找龍骨荒野的大法師莫德菈的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12056 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12056, 'zhTW', '死亡標記:高階教徒贊古司', '我親眼目擊了他的背叛!那個叛徒帶領了阿努巴進攻這座堡壘，殺掉了我手下幾個優秀的士兵。$B$B<茍爾特搖了搖頭。>$B$B他一直以來為天譴軍賣命，而我們卻什麼都不知道!還有多少像贊古司的人?我要把他們全部揪出來，揪出來以後...$B$B<苟爾特做了一個割喉的動作。>$B$B名單上的第一位就是贊古司。斥候回報他躲在西邊的那金之淵。找到他，宰掉他，把他的頭帶給我。', '殺掉高階教徒贊古司，並將他的頭交給苟爾特隊長。他就在龍骨荒野上的阿格瑪之錘裡。', '', '去找龍骨荒野的苟爾特隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12057 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12057, 'zhTW', '鑲肉骨書', '這本典籍由肉塊所拼湊而成，看起來正在流著血。檢查之後，你發現每頁內容滿是以血所寫成的奇怪符號。$B$B不管書頁中蘊藏的知識為何，這本書一定很重要。將它帶給阿格瑪之錘的苟爾特隊長，就在冰霧村的東方。', '將鑲肉骨書交到阿格瑪之錘的苟爾特隊長手上。', '', '去找龍骨荒野的苟爾特隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12058 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12058, 'zhTW', '符文預言', '布萊恩的日誌內容還包括了鐵矮人符號文字的簡介。我把這些簡介刻在一顆拱心石上，這可以幫助你瞭解雕在符文板上的文字。$B$B日誌的字裡行間顯示，布萊恩正在追查他的族人起源的線索。不要漏掉在他的最後抵達地點的任何線索。$B$B回到此地東北的鐸爾莫丹，站在每一塊石板的前面，使用拱心石辨認出上面的內容。我們不能讓聯盟先找到他。', '歐尼克瓦營地的賢者帕努納需要你解讀這三塊符文板。', '', '去找灰熊丘陵的賢者帕努納。', '第一則預言已解讀', '第二則預言已解讀', '第三則預言已解讀', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12059 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12059, 'zhTW', '奇怪的裝置', '拿起這個奇怪的裝置之後，你才確定它本質充滿魔力。很可惜，這裝置看不出來有什麼用途。$B$B也許，拿到月眠花園東北的阿格瑪之錘交給大法師，他可以告訴你它的用途也說不定？', '把戈拉莫什的奇怪裝置交給阿格瑪之錘的大法師埃薩‧奪日者的影像。', '', '去找龍骨荒野的大法師埃薩‧奪日者的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12060 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12060, 'zhTW', '投影與計畫', '這是傳送裝置。如果要我猜，應該會通到西邊月眠花園空中的極濤磁針平台上面。$B$B我需要你利用這裝置去看看上面有什麼。看起來它應該雙向都能作用，你應該不用從上面跳下來才對。$B$B我想，當你傳送至極濤磁針上面以後，應該有某種儀器你可以調查一下。$B$B只要你在花園裡面，你應該在哪裡都能使用傳送器才對。', '靠近並觀察月眠花園上空極濤磁針裡的投影。帶著情報，回到繁星之眠的大法師莫德菈的影像身邊。', '', '去找龍骨荒野的大法師莫德菈的影像。', '已觀察激湧針上的物體', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12061, 'zhTW', '投影與計畫', '這是傳送裝置。如果要我猜，應該會通到西南邊月眠花園空中的極濤磁針平台上面。$B$B$n，我需要你利用這裝置去看看上面有什麼。看起來它應該雙向來回，你應該不需要從上面跳下來才對。$B$B我認為當你傳送至極濤磁針上面以後，應該有某種儀器你可以調查一下。$B$B只要你在花園裡面，你應該在哪裡都能使用傳送器才對。', '靠近並觀察月眠花園上空極濤磁針裡的投影。帶著情報，向阿格瑪之錘的大法師埃薩‧奪日者的影像回報。', '', '去找龍骨荒野的大法師埃薩‧奪日者的影像。', '已觀察激湧針上的物體', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12062, 'zhTW', '羞辱寇仁·恐酒', '寇仁·恐酒就在隔壁房間裡，激怒黑鐵矮人，再發動一次攻擊。擊敗他!$B$B去找寇仁，挑起一場戰鬥。告訴他，他的啤酒連豬都不喝。$B$B你說了之後，就準備好打架吧。上一個侮辱他釀的酒的傢伙…變成了兇暴野豬的晚餐。', '與寇仁·恐酒交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12064, 'zhTW', '阿努巴之鏈', '他們將我的父親用魔法鎖鍊捆綁在冰霧村的正中央。根據我所收集到的情報來看，監獄被三名阿努巴的魔導師給控制住了 - 每一位魔導師各擁有一把鑰匙。$B$B搜遍冰霧村，把他們找出來。殺掉他們，拿走他們的鑰匙碎片。擁有三片碎片以後，我們就能把我父親救出來了。只要他自由...$B$B懲罰很快就會來臨的。', '班索克‧冰霧要求你把阿諾克拉之鑰碎片、提法科斯之鑰碎片和席諾克之鑰碎片帶給他。他就在龍骨荒野上的冰霧村中。', '', '去找龍骨荒野的班索克‧冰霧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12065, 'zhTW', '海灘上的節點', '狩法獵人的部隊最近開始在閃耀水岸活動，就在月眠花園的南邊。我猜你可能會在海灘上發現一個守衛嚴密的節點和一個負責那個地方的指揮官。$B$B我毫不懷疑他們的隊長會在那邊安排某些人控制裝置。取得控制裝置並且對節點使用。$B$B運氣好的話，我們應該可以獲得更多訊息，知道他們到底在那邊想幹什麼。', '取得地脈節點控制戒指並且對閃耀水岸的地脈節點使用，以獲得更多的訊息。然後回去找大法師莫德菈的影像，他就在繁星之眠中。', '', '去找龍骨荒野的大法師莫德菈的影像。', '已取得魔網匯聚點資訊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12066, 'zhTW', '海灘上的節點', '狩法獵人的部隊最近開始在閃耀水岸活動，就在月眠花園的南邊。我猜你可能會在海灘上發現一個守衛嚴密的節點和一個負責那個地方的指揮官。$B$B我毫不懷疑他們的隊長會在那邊有一些個人控制裝置。取得控制裝置並且對節點使用。$B$B透過你的協助，我們應該可以獲得更多訊息，知道他們到底在那邊想幹什麼。', '取得地脈節點控制戒指並且對閃耀水岸的地脈節點使用，以獲得更多的訊息。然後回去阿格瑪之錘找大法師埃薩‧奪日者的影像。', '', '去找龍骨荒野的大法師埃薩‧奪日者的影像。', '已取得魔網匯聚點資訊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12067 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12067, 'zhTW', '一封家書', '你找到一封藏在她長袍襯裡中的信。上面寫著:「父親，$B$B對於我的不告而別，我很抱歉。如果你正在讀這封信，那麼我已經不在世上了。$B$B我被迫替瑪里苟斯的軍團工作，他們威脅我如敢不從，我們的家人將會遭到殺身之禍。我覺得好羞愧。$B$B如果你找到任何可以對抗他們的方法，就不要擔心我了。我欺騙了他們並且從內部破壞他們的行動。$B$B我愛你，爸爸!$B$B艾米」$B$B指揮官賽雅‧蒼鋼一定會想看看這封信!', '把馬林隊長的信帶給繁星之眠的指揮官賽雅‧蒼鋼。', '', '去找龍骨荒野的指揮官賽雅‧蒼鋼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12068 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12068, 'zhTW', '自塵土而來的聲音', '<德拉庫魯將預言者之眼放在他的眉心，先祖之心擱在他的胸口。>$B$B我們很接近了，老兄，非常接近了...$B$B德拉克瑞銘碑是唯一殘存下來的東西，沒有人知道銘碑有多古老，也沒有人知道銘碑上寫的是什麼，但只要德拉庫魯有了心和眼，我就看得懂了。你可以在東邊德拉齊金的地穴深處找到銘碑，等你找到了銘碑，從神諭者和保衛者的身上拿走神聖魔精，你就可以在地穴裡面召喚我了。他們會很自豪能為此喪命的。', '德拉庫魯要你從德拉齊金遺跡中，找到德拉克瑞銘碑，並且從德拉克瑞神諭者和保衛者身上取得5個神聖魔精。然後在遺跡的德拉庫魯的火盆使用德拉庫魯藥劑召喚他的影像。', '', '去找灰熊丘陵的德拉庫魯的影像。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12069 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12069, 'zhTW', '向坦卡大酋長回報', '<班索克把牢房鑰匙交給你。>$B$B你得快一點，$n。拿這把鑰匙從阿努巴牢房裡把我父親從阿努巴監獄救出來。他自由之後，請協助他殺死阿努巴領導者，幽暗蟲王阿努貝坎。當幽暗蟲王被擊敗以後，把牠的殼敲下一塊來當作戰利品，呈給阿格瑪之錘的部落大軍。讓阿格瑪瞧瞧坦卡大酋長的力量!', '用阿努巴監獄鑰匙釋放坦卡大酋長冰霧，並且幫助他擊敗幽暗蟲王阿努貝坎。拾起一塊阿努貝坎之殼的碎片，交給阿格瑪霸主。他就在龍骨荒野上的阿格瑪之錘裡。', '', '去找龍骨荒野的霸主阿格瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12070 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12070, 'zhTW', '重整部隊', '鐵之子使用他們的符文奴役了我許多的兄弟，用他們來突破鐸爾莫丹的圍城。我希望我們不必與他們作戰，但我們沒有選擇。$B$B我的巨人無法支撐太久這樣的攻擊。$B$B我對這片土靈裂片灌注了祝福的力量，以協助我們的盟友。帶著這個參與北方巨礫之丘的戰鬥，並且用這來穩定並且強化我們的同伴。$B$B殺死所有阻礙你的鐵矮人。', '在巨礫之丘的戰鬥中使用大地裂片來重整灰白之丘巨人，殺死阻礙你的鐵矮人，然後向庫倫回報，他就在可以俯瞰鐸爾莫丹的山丘上。', '', '到灰白之丘的巨礫之丘找庫倫。', '鼓舞灰白之丘巨人', '殺死鐵符文復仇者', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12072 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12072, 'zhTW', '荒獸死定了!', '我想你一定看到冰霧村裡面，被製造出來的阿努巴荒獸大軍了。阿努巴正在策劃將這些怪物送到憤怒之門來對付我們。不能讓這件事發生!$B$B帶著這把信號槍前去西方的冰霧村，開槍召喚戰鬥坐騎飛下來。駕馭戰鬥坐騎毀掉那些從地面攻擊不到的荒獸!$B$B一旦你把他們的空中武力解決，回來向我領賞!', '在冰霧村中使用沃爾諾克的信號槍以呼喚柯爾克隆戰鬥坐騎。騎乘柯爾克隆戰鬥坐騎殺死25頭阿努巴荒獸!任務完成後回去阿格瑪之錘找沃爾諾克‧風怒者。', '', '去找龍骨荒野的沃爾諾克‧風怒者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12073 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12073, 'zhTW', '重擊鐵矮人', '聯盟並不是唯一在灰白之丘的對抗我們的勢力，除了東北方的鐸爾莫丹被一群石巨人圍攻，鐵矮人牢牢地掌握著東部海岸。$B$B身經百戰的戰士會對敵人的痛處攻擊，如果我們忽略了鐵矮人在鐸爾莫丹的弱點，那我們就是呆子。不要對鐵矮人手下留情，把擋在你前面的統統殺光。$B$B這些「鐵之子」將會知道部落的恐怖。', '殺死任意10位防衛鐸爾莫丹的鐵矮人，並且向歐尼克瓦營地的斥候沃塔克回報。', '', '去找灰熊丘陵的斥候沃塔克。', '鐵矮人守衛已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12075 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12075, 'zhTW', '精挑細選', '外頭很冷，對吧，$r?寇恰不願意和我見面。看來他還有更迫切的事情 - 那就是從底下洞穴不斷攻擊他們的蟄猛巨蟲。說不定你可以幫我說服寇恰我其實是個好人。$B$B在北邊的洞口，我看到了一名巨人被那種蟲給吃了...我還是不懂為什麼這些蟲這麼輕易就把巨人宰了。從他的傷口採一些樣本給我吧。', '從冰巨人的屍體上收集1份岩肉樣本，位置在水晶之鉗的山洞口，佐特的北邊。任務完成以後，向峽谷中央附近的佐特回報。', '', '去找龍骨荒野的佐特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12076 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12076, 'zhTW', '骯髒的事情', '你帶給我的樣本只要看一眼，就可以發現某種腐蝕性唾液的明顯痕跡。很自然的假設，這種唾液跟蟲子用來掘地的成份是一樣的，這也使得這些唾液成了對付冰巨人恐怖的武器。$B$B把我的刮鏟帶著，找一隻蟲打架，當他吐口水在你身上的時候，用刮鏟把唾液刮掉帶回來給我。給我多一點 - 我要拿他來做藥劑的主要成份。', '對你自己使用刮鏟，收集2瓶蟄猛巨蟲吐出來的腐蝕唾液。任務完成以後，把瓶子帶給水晶之鉗的佐特。', '', '去找龍骨荒野的佐特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12077 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12077, 'zhTW', '一天兩次外敷', '這份藥劑應該可以抵擋他們的口水。替我拿給寇恰，好嗎?告訴他如果他願意報答這個人情，我還有很多藥源。', '把佐特準備的藥劑交給『無敵』寇恰。', '', '去找龍骨荒野的『無敵』寇恰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12078 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12078, 'zhTW', '牧蟲人', '那就這樣吧。如果巨人們不會前來幫助我們，也許我們可以利用這些蟲子。下面的洞窟裡，在母蟲附近一定有些幼蟲。帶著這個箱子，並且捕捉3隻幼蟲，把它們帶來給我。$B$B在交涉失敗的時候，奴役是個完美的變通手段。', '進入水晶之鉗底下的洞窟，使用結實的木箱捕捉3隻蟄猛巨蟲幼蟲。在抓到幼蟲之後記得要把箱子撿起來!把被捕獲的蟄猛巨蟲幼蟲交給水晶之鉗的佐特。', '', '去找龍骨荒野的佐特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12079 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12079, 'zhTW', '重踏地面', '你好，小傢伙。我不知道什麼樣的瘋狂理由帶你來到水晶之鉗，但我歡迎你的到來。$B$B這些冰蟲...這些蟄猛巨蟲養成了吃我兄弟的胃口。我想在作戰時期你不會覺得我們同族很友善，但如果你是來幫忙處理蟲子問題的話，我會聽你說的。$B$B如果我們想要拿回洞窟的話，就得先清理這些峽谷中的蟄猛巨蟲餵食者。加入我們的戰鬥，$r!', '潛入水晶之鉗北端的洞穴，替『無敵』寇恰殺死8隻冰心蟄猛餵食者。', '', '去找龍骨荒野的『無敵』寇恰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12080 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12080, 'zhTW', '超級大蟲', '蟄猛巨蟲在底下的洞窟中有隻母蟲在繁殖牠們。我們叫她響鑽，這是一個從瘟疫之地來的冒險家命名的。我在牠們最初的突襲中見過她一次 - 她的身形大到足以吞噬我的年輕族人。不除掉她，這洞穴就不會落入我們手中。', '進入冰心洞窟殺死響鑽。如果你還帶著的話，記得要用佐特的保護藥劑來保護你自己不受蟄猛巨蟲的噴酸傷害。當你完成任務之後向水晶之鉗的『無敵』寇恰回覆。', '', '去找龍骨荒野的『無敵』寇恰。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12081 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12081, 'zhTW', '葛夫洛克', '沒有你的幫助，我們無法扭轉鐸爾莫丹的情勢。這座古老的城市長久以來一直都是這些土與石族勢力的戰場。我唯一的祈求就是最後能將戰事弭平。鐵矮人仍舊能利用他們的魔法捕捉並奴役我們的弟兄，葛夫洛克正在尋找出拯救符文巨人的方法，你可以在一處被稱為「瑟希斯遺跡」的群島上找到他，位置就在離東風水濱中央到南方的海面上。', '和瑟希斯遺跡的葛夫洛克交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12082 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12082, 'zhTW', '嘟 - 答 - 嘟 - 噠!', '聽著，孩子。這不是你該來玩耍的地方。$B$B我正要闖出這裡，跟緊我，我來帶你出去。', '護送哈里遜從德拉齊金遺跡逃脫，接著和哈克爾營地的哈克爾交談。', '哈里森已護送你至安全處', '去找灰熊丘陵的哈克爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12083 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12083, 'zhTW', '林地之上', '我確信還有更多這種水晶體，而每一個水晶體依次引導到地脈能量。只是，我們仍舊無法確實知道他們想利用那些能量做什麼。$B$B我猜測，你可以在東南邊洛薩羅林地上方找到另外一處。如法炮製，把負責的人揪出來，把他們所有的控制裝備拿走，我相信每個節點都有同樣的控制方式。$B$B小心點，$n，林地非常的危險。', '取得地脈節點控制護符並且對繁星之眠的地脈節點使用，以獲得更多的訊息。接著，向繁星之眠的大法師莫德菈的影像回報。', '', '去找龍骨荒野的大法師莫德菈的影像。', '已取得魔網匯聚點資訊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12084 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12084, 'zhTW', '林地之上', '我確信還有更多這種水晶體，而每一個水晶體依次引導到地脈能量。只是，我們仍舊無法確實知道他們想利用那些能量做什麼。$B$B我猜測，你可以在南邊洛薩羅林地上方找到另外一處。如法炮製，把負責的人揪出來，把他們所有的控制裝備拿走，我相信每個節點都有同樣的控制方式。$B$B動作要快，$c，我感覺時間不夠了。', '取得地脈節點控制護符並且對洛薩羅林地的地脈節點使用，以獲得更多的訊息。接著，向阿格瑪之錘的大法師埃薩‧奪日者的影像回報。', '', '去找龍骨荒野的大法師埃薩‧奪日者的影像。', '已取得魔網匯聚點資訊', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12085 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12085, 'zhTW', '一封家書', '你在他的袍子中的內襯中發現了秘藏的信件，信上寫道:$B$B「迪諾:$B$B塔辛尼讓妳失望了。如果你讀到這封信，那我已不在人世。$B$B瑪里苟斯逼我替他的軍隊做事，不然就以家人的生命作威脅。塔辛尼不會讓這件事情發生的!$B$B別擔心我，好好保護你的孩子。我耍了那些人，並且從中搗亂。$B$B我愛妳，妹妹!$B$B塔辛尼」霸主阿格瑪一定會想要看到這封信的!', '將塔辛尼中尉的信件送給阿格瑪之錘的霸主阿格瑪。', '', '去找龍骨荒野的霸主阿格瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12089 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12089, 'zhTW', '懸賞：博學者克爾多努斯', '奉霸主阿格瑪之命:$B$B犯人:博學者克爾多努斯$B$B罪名:通敵$B$B該員狀況:存活$B$B博學者克爾多努斯，阿格瑪之錘的法師指揮官，以部落為名格殺勿論。$B$B克爾多努斯最後被人發現朝西南方前往月眠花園，意圖加入藍龍軍團陣營與其抗魔之役。$B$B小心接觸克爾多努斯，該員是為一強大之魔導師。$B$B一切賞金將由阿格瑪之錘之苟爾特隊長支付。', '殺死博學者克爾多努斯，並向苟爾特隊長回報，他在龍骨荒野的阿格瑪之錘中。', '', '去找龍骨荒野的苟爾特隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12090 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12090, 'zhTW', '懸賞：吉甘陶', '奉霸主阿格瑪之命:$B$B犯人:吉甘陶$B$B罪名:襲擊部落;「長太醜」$B$B該員狀況:存活$B$B猛瑪象人領主，吉甘陶，因涉嫌多起襲擊部落士兵與龍骨荒野軍事設施事件遭到通緝。$B$B吉甘陶最後一次被人發現於阿格瑪之錘東南方林間小路中遊蕩。$B$B相信吉甘陶持有大量軍火並且極端危險。$B$B一切賞金將由阿格瑪之錘之苟爾特隊長支付。', '殺死吉甘陶，並向苟爾特隊長回報，他在龍骨荒野的阿格瑪之錘中。', '', '去找龍骨荒野的苟爾特隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12091 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12091, 'zhTW', '懸賞：懼爪', '奉霸主阿格瑪之命:$B$B犯人:懼爪$B$B罪名:襲擊部落$B$B該員狀況:存活$B$B懼爪因多次攻擊往來毒怨之地的部落車隊而遭懸賞。$B$B懼爪盤據晶紅龍殿上方的懸崖，位在阿格瑪之錘東方。接近懼爪需極度小心。$B$B一切賞金將由阿格瑪之錘之苟爾特隊長支付。', '殺死懼爪，並向苟爾特隊長回報，他在龍骨荒野的阿格瑪之錘中。', '', '去找龍骨荒野的苟爾特隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12092 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12092, 'zhTW', '強化古樹', '藍龍軍團的所作所為，不是只有$r受到了衝擊，東南邊洛薩羅林地的古樹們也同樣有所影響。$B$B有些古樹被污染 - 盡一切所能避開他們 - 但是大部份還有得救。然而，林子裡的樹人看來不僅免疫大地上滲出的魔法，以及，隨著魔力出現而出沒的秘法龍鰻的影響。$B$B向樹人要他們的樹皮，餵給古樹。希望這樣足夠拯救他們。', '對3個洛薩羅古樹使用行者樹皮以強化他們，然後向繁星之眠的薩瑞翠亞納回報。', '', '去找龍骨荒野的薩瑞翠亞納。', '洛薩洛遠古樹人已強化', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12093 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12093, 'zhTW', '強制符文', '即使庫倫攻打鐸爾莫丹的同時，鐵矮人仍將他們的魔法作用在我們的同胞身上。從地上召喚出我們的同胞，使用符文束縛他們，這些鐵之子強迫他們向石之子作戰。$B$B他們使用強制符文沿著東風水濱，把受奴役的巨人送到北方的戰場上。$B$B找出四個強制符文，破壞它們迫使他們的監督者現身 - 這些監督者正是控制每顆符文的編織者。只要沒了這些監督者，符文一點用也沒有。', '瑟希斯遺跡的葛夫洛克要你去打敗監督者德沃、監督者寇爾甘、監督者羅克利和監督者布魯農，好讓四個強制符文失去效力。', '', '去找灰熊丘陵的葛夫洛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12094 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12094, 'zhTW', '潛在的力量', '雖然支配符文具有強制性，我們還是有個機會能解放這些符文巨人。$B$B我會給你一片石頭，自從我被創造以來它就一直是我的一部份。如果適當地注入能量，它就能用來解放那些被束縛的巨人。$B$B在鐵之途和森林邊緣之間的能量之地上，也就是你們稱為地脈交叉點的地方，有兩個遠古石頭地標。另外一個在遺跡南方盡頭的島嶼上。到各個石頭處把碎片充能，然後回來找我。', '到第一塊遠古之石、第二塊遠古之石、以及第三塊遠古之石替葛夫洛克裂片充能，然後返回瑟希斯遺跡找葛夫洛克。', '', '去找灰熊丘陵的葛夫洛克。', '已從第一塊遠古之石汲取力量', '已從第二塊遠古之石汲取力量', '已從第三塊遠古之石汲取力量', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12095 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12095, 'zhTW', '前往龍殞營地', '此地東方，在龍骨荒野的中心處，是個除了龍類遺骸和冰雪以外一無所有的平原。天譴軍團在中央凍原建立起數個營地，不斷的把復活的冰霜巨龍送去攻擊我們在憤怒之門的部隊。雖然大多數的冰龍都被洛克漢與他的巨龍獵人輕鬆解決，但其中一頭龍卻相當的麻煩。$B$B前往東北方並到龍殞營地找洛克漢，協助他和他的部下擊敗薩拉絲婥，我會大大的獎賞你!', '與龍骨荒野上龍殞營地的洛克漢交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12096 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12096, 'zhTW', '強化古樹', '南方洛薩羅林地的古樹被秘法龍鰻給污染了...龍鰻從土中被喚起!$B$B那些已經被污染的古樹很危險，對我們也沒有用處，但是大部分還是有得救。很幸運，林子裡的樹人似乎對那裡發生的一切都不為所動。$B$B向樹人要一些樹皮，拿到以後餵給那些古樹。這應該有辦法強化他們。$B$B別再打擾我做事了!我得好好監視這些藥劑師才行。', '對3個洛薩羅古樹使用行者樹皮以強化他們，然後向阿格瑪之錘的大地守望者格里夫回報。', '', '去找龍骨荒野的大地守望者格里夫。', '洛薩洛遠古樹人已強化', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12097 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12097, 'zhTW', '薩拉絲婥，北方災厄', '我的獵人不是死了就是被凍成冰塊了，$n。你還是要幹嗎?只要跟我說一聲，我就把那條龍再叫過來。$B$B如果你宰掉它，帶那怪獸的冰凍心臟回去阿格瑪之錘給苟爾特。他一定會好好酬謝你，老兄。', '與洛克漢交談，呼喚冰霜巨龍薩拉絲婥。殺死薩拉絲婥並且把薩拉絲婥的冰凍心臟送去給阿格瑪之錘的苟爾特隊長。', '', '去找龍骨荒野的苟爾特隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12099 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12099, 'zhTW', '終獲自由', '你所灌滿的碎片應該足以用來打破束縛我兄弟的符文魔法。$B$B帶著它，沿著東風水濱前往北邊找到符文巨人。釋放石頭中儲藏的能量並觀察結果。$B$B如果有效的話，符文巨人應該會回復神智不再服從鐵矮人。要是石頭失效的話，巨人會在被削弱的狀態下攻擊。但是，我們有什麼選擇呢?如果我們不去嘗試的話，他們永遠會毫無希望的被奴役著。', '使用葛夫洛克的符文破壞者釋放四個符文巨人，然後向瑟希斯遺跡的葛夫洛克回報。', '', '去找灰熊丘陵的葛夫洛克。', '符文巨人已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12100 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12100, 'zhTW', '遏止腐敗', '死亡和疫病隨著天譴軍團而來。我們經常眺望天譴軍入侵的區域，野生動物慘遭蹂躪，最終被腐敗和傳染病毀滅。$B$B對龍骨荒野大多數的原生物種來說，一切都已經太遲了。天譴軍帶來的潰疾已經感染了這些野獸，使他們潰爛發狂。$B$B你必須冒險前往西方，到那金之淵消滅被感染的野生生物。檢查他們的屍體，找出一副製造疫苗所需的抗腐化臟器。', '龍骨荒野上，阿格瑪之錘的梭爾‧鷹怒要你殺死15個被感染的野生生物，並取得抗腐內臟。', '', '去找龍骨荒野的梭爾‧鷹怒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12101, 'zhTW', '好醫生...', '我們的被遺忘者盟友把他們的藥劑師核心成員送來這裡，幫助我們摧毀憤怒之門的天譴軍團。其中一位辛塔爾‧瑪雷菲爾斯醫生，精通天譴軍團的疫病，而且知道如何抑制它的擴散。我先前和他達成了協議替野生動物製作一劑疫苗。從那時候起他就在等待這個臟器。$B$B把這個抗腐內臟送去給瑪雷菲爾斯醫生，告訴他是我要給他的。他會派你去做下一項工作。', '將抗腐內臟送去給阿格瑪之錘的辛塔爾‧瑪雷菲爾斯醫生。', '', '去找龍骨荒野的辛塔爾·瑪雷菲爾斯醫生。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12102, 'zhTW', '尋找晶紅紫丁香', '晶紅龍殿就在此地東方是很幸運的一件事。你可以在那兒找到被稱做晶紅紫丁香的花。只要有這種促進生命的植物我就可以替這個區域未受污染的動物調出一劑疫苗。$B$B前往東方的晶紅龍殿尋找紫丁香。$B$B記住:這座龍殿，就像這被詛咒的荒原中所有的龍殿一樣，都被天譴軍團給包圍了。小心一點，我們可不希望你被餘燼龍給吞了。$B$B<辛塔爾大笑。>', '龍骨荒野，阿格瑪之錘的辛塔爾‧瑪雷菲爾斯醫生要你收集1個晶紅紫丁香。', '', '去找龍骨荒野的辛塔爾·瑪雷菲爾斯醫生。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12103 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12103, 'zhTW', '不推薦', '我聽夠了，$N。我們必須確保發生在銀溪的一切不會散佈到整個大陸上。$B$B我不在乎是水質、高度、或是古老的巨魔詛咒把這些村民變的兇殘瘋狂…返回銀溪，然後結束他們的性命。', '琥珀松小屋的德瑞克上尉要你殺死8個銀溪村民和8個銀溪陷捕者。', '', '去灰白之丘找琥珀松木營地的杜蒙特中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12104 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12104, 'zhTW', '向梭爾回報', '<瑪雷菲爾斯醫生交給你個裝滿黑色液體的瓶子。>$B$B拿去吧，$r。把這個拿回去給那頭牛，告訴他所有的債都償清了。我們正式「扯平」。$B$B現在，在我放傑寧斯咬你之前快滾吧。', '把辛塔爾的疫苗送去給阿格瑪之錘的梭爾‧鷹怒。', '', '去找龍骨荒野的梭爾‧鷹怒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12105 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12105, 'zhTW', '深入黑暗', '這本日誌是由一個銀溪鎮的居民米克哈爾所寫的。內容詳細紀錄了一個組織的到來，被稱作『魔狼教』的暗影信徒。$B$B村民起初並不情願信奉這個教派，但是它的支持者逐漸遍佈村民之中。$B$B出於不安，米克哈爾把他的女兒莎夏從銀溪鎮送走，並且嘗試勸導其他的村民。$B$B米克哈爾在最後一行字提到，一場與鎮長召開的會議，討論穴石礦坑中不明的現象。', '將米克哈爾的日誌帶給琥珀松小屋的都蒙特中尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12107 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12107, 'zhTW', '地脈的盡頭', '在他袍子裡，你發現了兩樣讓你感興趣的東西。$B$B其一是條護身符，顯然就是節點的控制裝置;另外是一連串的任務指令，由一個名叫席卓葛斯的人所發佈的，最終將矛頭指回了他就是月眠花園的領導者。$B$B這張被水濡濕的牛皮紙指明，戈拉莫什將所有的狩法獵人軍力調往東邊的蒼藍龍殿。$B$B也許你應該蒐集所有的節點資訊，並且沿著龍殿西邊的岩架前去東方，進行調查。', '使用地脈節點控制咒符，從因度雷湖底下的地脈節點中取得你所需的資訊。接下來往東前去蒼藍龍殿，就在龍骨荒野中央偏南的地方，從西邊的岩架調查發生了什麼事情。最後，返回繁星之眠大法師莫德菈的影像之處。', '', '去找龍骨荒野的大法師莫德菈的影像。', '已取得魔網匯聚點資訊', '已觀察蔚藍龍神殿', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12108 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12108, 'zhTW', 'DEPRECATED', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12110 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12110, 'zhTW', '地脈的盡頭', '在他袍子裡，你發現了兩樣讓你感興趣的東西。$B$B其一是條護身符，顯然就是節點的控制裝置;另外是一連串的任務指令，由一個名叫席卓葛斯的人所發佈的，最終將矛頭指回了他就是月眠花園的領導者。$B$B這張既破爛又被水濡濕的牛皮紙指明，戈拉莫什將所有的狩法獵人軍力調往東邊的蒼藍龍殿。$B$B也許你應該蒐集所有的節點資訊，並且沿著龍殿西邊的岩架前去東方，進行調查。', '使用地脈節點控制咒符，從因度雷湖底下的地脈節點中取得你所需的資訊。接下來往東前去蒼藍龍殿，就在龍骨荒野中央偏南的地方，從西側的岩架觀察發生了什麼事情。最後，返回阿格瑪之錘的大法師埃薩‧奪日者的影像之處。', '', '去找龍骨荒野的大法師埃薩‧奪日者的影像。', '已取得魔網匯聚點資訊', '已觀察蔚藍龍神殿', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12111 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12111, 'zhTW', '野生物遊蕩之地', '這個包裹裡面有幾瓶裝有辛塔爾製造的疫苗。我要你現在去附近的林子裡調查落雪麋鹿和寒地灰熊的蹤跡。等你遇到這些生物之後，找一個安全的距離，朝牠們的方向丟去。瓶子破掉會釋放出一股無嗅的氣體，並使牠們吸入觸媒。這些野獸幾乎不用直接踏進氣體的範圍內，就會被接種疫苗 - 最後就會得救。$B$B盡量夠替這些野獸們接種疫苗，再向我回報。', '阿格瑪之錘的梭爾‧鷹怒需要你對5頭落雪麋鹿和5頭寒地灰熊使用疫苗包裹。', '', '去找龍骨荒野的梭爾‧鷹怒。', '已為雪落麋鹿接種', '已為北極灰熊接種', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12113 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12113, 'zhTW', '很高興認識你...的肉!', '$c，你好哇!在火堆邊挨著我坐下吧，嗄?$B$B我樂意分你一點好吃的溫暖大餐，可惜我啥都沒有。我在這裡等一個朋友前來，不然我就會自己去找點吃的了。$B$B這樣吧，你看來什麼都沒有，就是時間多，這附近又有很多的肉，你要不要幫我個忙，弄些肉過來?', '哈克爾營地的哈克爾需要你從暮嚎徘徊者身上收集10塊多筋座狼肉，以及長蹄牧者身上收集10塊鍬角排。', '', '去找灰熊丘陵的哈克爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12114 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12114, 'zhTW', '復仇療法', '食人妖...我恨透他們啦!<哈克爾啐了一口口水。>$B$B我有一次被一群那該死的混帳給捉了...就差那麼一點點我的頭就被他們給縮了!$B$B我的朋友告訴我把這件事放到腦後，人要大步向前，但是我就是覺得不對勁。$B$B你想知道要怎麼讓我開心一點嗎，$r?只要看到成堆的食人妖屍體多到擋住陽光我就開心了!如果你能讓這件事成真，我有很多金子等著花呢。', '哈克爾營地的哈克爾要你去德拉齊金遺跡外，殺10名德拉克瑞保衛者和10名德拉克瑞神諭者。', '', '去找灰熊丘陵的哈克爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12115 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12115, 'zhTW', '寇爾提拉與死亡的語言', '有一位最近加入我們的人也許可以解讀這本書。一個名叫寇爾提拉‧亡織者的自由死亡騎士暫時駐紮在阿格瑪之錘。他曾經是阿薩斯的死亡騎士，天譴軍團的一員，也許能夠翻譯死者的語言。$B$B把這本把鑲肉骨書拿去給寇爾提拉，請他翻譯內容。', '將鑲肉骨書交給寇爾提拉‧亡織者。', '', '去找龍骨荒野的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12116 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12116, 'zhTW', '膽子要大...', '你好，$c。你真是個好人，願意留下來聽卡拉茲講古。$B$B多年來，卡拉茲一直聽命於這些靈魂，完成他們的請求，而心力交瘁。$B$B近來，許多哭喊聲從這些廢墟中傳出來，尋求他們無法得到的平靜。$B$B如果你願意幫助這些古老的靈魂，進入地穴，收集屬於這些受折磨的靈魂生前的物品。', '哈克爾營地的卡拉茲要你進入德拉齊金遺跡，並收集5罐德拉克瑞臟器罈。', '', '去找灰熊丘陵的卡拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12119 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12119, 'zhTW', '等候謁見', '$n，你必須儘快趕去龍眠神殿，並將這封信呈給管理者，泰瑞歐斯塔茲。$B$B神殿坐落在龍骨荒野的中心，順著東邊的道路直走到底，通過龍墳荒原就能抵達了。$B$B我相信管理者讀過你的介紹信之後，他會讓你晉見龍后雅立史卓莎。我們只能期盼我們還來得及。$B$B感謝你為我們做了這麼多事情。旅途平安!', '將介紹信送交到龍眠神殿的泰瑞歐斯塔茲手上。', '', '去找龍骨荒野的泰瑞歐斯塔茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12120 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12120, 'zhTW', '德拉克古歐的木槌', '腐化...$B$B在你把這些瓶子拿來之前，克拉茲就已經感覺到了。腐化讓上古德拉克瑞之靈充滿了痛苦，讓他們得不到安息。$B$B克拉茲不會騙你，$c。要淨化這個區域需要很重大的犧牲，但我們晚點再談。$B$B這裡的活人之中有人握有淨化的關鍵。找出德拉克古歐，然後把他的木槌帶回來給克拉茲。', '哈克爾營地的克拉茲要你殺死德拉齊金遺跡外頭的德拉克古歐，然後帶著德拉其金木槌回來。', '', '去找灰熊丘陵的卡拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12121, 'zhTW', '另一頭見', '這些德拉克瑞食人妖只懂得用野蠻的敵意跟你相處。你不欠他們什麼。確實很少人能夠完成卡拉茲今天要求你做的事。$B$B要淨化這個地方，並且讓這些靈魂獲得永恆的安息，你就得投身死亡之中。$B$B墓穴中有人在等著你 - 在另一個世界裡。他有我們想知道的情報，$n。$B$B用木槌敲響銅鑼。腐化此地的靈魂必定會將你送到靈魂世界去。$B$B卡拉茲等著你回來。', '哈克爾營地的卡拉茲要你用德拉齊金木槌敲響德拉齊金遺跡外面的銅鑼。等到你被殺死後，就能夠進入遺跡並且與剛裘的靈魂交談。', '', '', '死於督軍金納拉克之手', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12122, 'zhTW', '等候謁見', '$n，你必須儘快趕去龍眠神殿，並將這封信呈給管理者，泰瑞歐斯塔茲。$B$B神殿坐落在龍骨荒野的中心，順著東邊的道路直走到底，通過龍墳荒原就能抵達了。$B$B我相信管理者讀過你的介紹信之後，他會讓你晉見龍后雅立史卓莎。我們只能期盼我們還來得及。$B$B感謝你為我們做了這麼多事情。旅途平安!', '將介紹信送交到龍眠神殿的泰瑞歐斯塔茲手上。', '', '去找龍骨荒野的泰瑞歐斯塔茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12123, 'zhTW', '警告龍后', '<巨龍管理者將介紹信從你手中取走。>$B$B是...是呀，我想你已經準備好覲見女王。$B$B準備好就告訴我吧，我會命這些飛龍安全地引領你到神殿的頂端。你得親自將這封信呈給雅立史卓莎女王。', '將介紹信送交到龍眠神殿的『生命守縛者』龍后雅立史卓莎手上。', '', '去找龍骨荒野的『生命守縛者』雅立史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12124, 'zhTW', '警告龍后', '<巨龍管理者將介紹信從你手中取走。>$B$B是...是的，我想你已經準備好覲見女王。$B$B準備好就告訴我吧，我會命這些飛龍安全地引領你到神殿的頂端。你得親自將這封信呈給雅立史卓莎女王。', '將介紹信送交到龍眠神殿的『生命守縛者』龍后雅立史卓莎手上。', '', '去找龍骨荒野的『生命守縛者』雅立史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12125, 'zhTW', '為血魄效力', '吾輩過去曾用無辜者之血來餵飽符文刃的飢渴。啊，我已經無法再選擇這種作法。$B$B<寇爾提拉停下來想了一想。>$B$B我們得湊合將就一下。此地南方，在高崖上，有個巨牙海民的村落，因度雷。由於前陣子遭到藍龍軍團的混沌魔法蹂躪，因度雷的居民已經發狂了。$B$B帶著這個血魄寶石，對瘋狂的村民使用它，如果我不能取得無辜者之血，我該當得到羔羊之血!', '阿格瑪之錘的寇爾提拉‧亡織者要你對發狂的因度雷村民使用血魄寶石，然後帶著充盈的血魄寶石向他回報。', '', '去找龍骨荒野的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12126, 'zhTW', '為穢邪效力', '吾輩渴望穢邪之力。它是我們存在的本質，將死亡賜予那些膽敢嘲弄它的人!幸好有著這樣的泉源，能在我需要之時，供我汲取力量。$B$B帶著這穢邪寶石前往東方的晶紅龍殿。你會在那裡找到阿薩斯的死亡騎士，瓦倫赫公爵。在戰鬥中削弱他的決心，然後對他釋放寶石的力量。這會將他殺死，並竊走他的穢邪能量!', '阿格瑪之錘的寇爾提拉‧亡織者要你對瓦倫赫公爵使用穢邪寶石，然後將充盈的穢邪寶石交還給他。', '', '去找龍骨荒野的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12127, 'zhTW', '為冰霜效力', '這刺骨的凍寒會在死亡騎士迎戰敵人的時候保護他們。掌控冰霜之力的人將可帶來混亂與毀滅!$B$B帶著這個冰霜寶石，然後穿越龍骨荒野的開闊凍原，直到你抵達龍眠神殿東方的黎明之鏡。在彼處，你要與盤據湖泊的冰冷亡魄軍團作戰，並且奪取它們的冰霜精華。在它們虛弱的時刻使用寶石的力量，$n!', '阿格瑪之錘的寇爾提拉‧亡織者要你對冰冷亡魄使用冰霜寶石，然後帶著充盈的冰霜寶石回去給他。', '', '去找龍骨荒野的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12128, 'zhTW', '與瑞加爾聯繫', '在軍隊試圖穿越鐸爾莫丹的興奮之中我差點就忘了瑞加爾和他的小組還在勘察員崗哨。我派了瑞加爾和他的助理，以及一個登山家的朋友去丹亞戈附近建立了一個小哨站，就在東風水濱的南端。他們是去調查南方丘陵區鐵矮人的蹤跡的，但我至今都沒有收到任何報告。如果你要去那一帶的話，能夠找找他們嗎?', '與勘察員崗哨的瑞加爾·斷眉交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12129, 'zhTW', '完美的設計圖', '鐵矮人毫不隱瞞他們正在準備打仗的事實。有這些巨人、魔像、以及閃電元素，他們等於擁有高於西部荒野民兵團的科技優勢。如果兵團在北邊沒有快點找到通道的話，鐵矮人就會突襲他們。$B$B我們得把矮人擋在這裡，我剛好找到了方法。丹亞戈充滿了不停製造出戰爭魔像的符文鐵匠。他們各自帶著不同零件的設計圖，所以你得尋找拼湊出所有部分。', '把完整的戰爭魔像藍圖交給勘察員崗哨的瑞加爾‧斷眉。', '', '去找灰熊丘陵的瑞加爾‧斷眉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12130, 'zhTW', '可以盜用的時候為什麼要動手製造？', '我們有藍圖了，可是沒有零件的話什麼都不能做！我們沒有鑄造廠，更沒有原料，但是在丹亞戈有一大堆的零件。$B$B你的工作？幫這些零件找新家。$B$B它們應該散佈在符文鐵匠工作的建築物裡，我想，當你偷拿他們的手工成品的時候他們會有些暴躁，這也是無可厚非的。你能帶來越多零件，我們就能把魔像做的越好。', '把8個戰爭魔像零件交給勘察員崗哨的瑞加爾‧斷眉。', '', '去找灰熊丘陵的瑞加爾‧斷眉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12131 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12131, 'zhTW', '我們有能源', '就快大功告成啦，不過作戰魔像需要能量晶格做動力源。在被丹厄古爾的鐵矮人發現之前，我們已經收集到了很多頗有價值的情報。符文鑄造師杜拉爾和符文鑄造師卡索恩身上就有能量晶格。$B$B我們得設法搞來這兩塊能量晶格。$B$B他們應該在丹厄古爾中層的兩座車間裡。', '將杜拉爾的能量晶格和卡索恩的能量晶格交給勘探員哨站的萊加爾·斷眉。', '', '去灰白之丘找勘探員哨站的萊加爾·斷眉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12132 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12132, 'zhTW', '毀滅之力', '雖然你為我做了很多，但還有一件任務要麻煩你。$B$B你曉得這個世界之外還有另外一個世界，暗影世界。從那個世界，痛苦侵襲著我。在自身的惡魔之前，我毫無招架之力，而你可以終結他們的恐怖統治。你有力量，我曾經用我的雙眼見識過。$B$B進入暗影世界，勇敢面對折磨我的惡魔!$B$B只要做得到，我保證，我就會翻譯這本骨書。', '龍骨荒野上，阿格瑪之錘的寇爾提拉‧亡織者需要你進入暗影世界，擊敗6隻幽暗折磨者。如果你需要再次進入暗影世界，和寇爾提拉‧亡織者交談。', '', '去找龍骨荒野的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12133 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12133, 'zhTW', '砸碎南瓜', '這個大型南瓜燈籠放在村莊的中央。那些看著它眼睛的人，都會受到當中黑暗威脅的引誘而誤入歧途。$B$B砸碎南瓜之後露出一個老舊、燒焦的聖徽。', '將燒焦的聖徽交給變裝的孤兒監護員。', '', '去找變裝的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12134 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12134, 'zhTW', '莎夏的狩獵', '這東西...這詛咒...侵襲了銀溪鎮和季至村...從人們之中製造出野獸來。$B$B我父親試著要警告他們，但他們全聽信了魔狼教。$B$B他們現在已經完全迷失了，該是時候殺了他們...這也是為了他們好。', '莎夏要你去季至村殺死12個季至獵人。', '', '去找灰熊丘陵的莎夏。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12135 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12135, 'zhTW', '「讓火焰來吧!」', '你一定得幫幫我們!無頭騎士可能會在任何時候攻擊這個村子!火焰將會到處都是!孩子們並不安全!$B$B拜託，$n，你願意面對無頭騎士的火焰嗎?等他來的時候，你一定要加入滅火的行列。拿起水桶灑向火源，或是交給靠近火勢的朋友。如果你能熄滅那些火焰，我們或許還有救!', '變裝的孤兒監護員希望你在無頭騎士縱火之後，幫助撲滅村莊中的火勢。等火完全撲滅之後，再和變裝的孤兒監護員交談。', '撲滅火勢', '去找變裝的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12136, 'zhTW', '譯妥的骨書', '$n，就是它了。我已經把書上每一頁印在上頭的內容翻譯妥當。在其中，你可以發現一列名單，全部都是橫跨整座大陸的詛咒神教成員。$B$B但是退一步說，詛咒神教的間諜網絡與運作令人訝異。$B$B再會，朋友，願這本書能為你和你的人民有所幫助。', '將翻譯過的鑲肉骨書帶給阿格瑪之錘的苟爾特隊長。', '', '去找龍骨荒野的苟爾特隊長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12137 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12137, 'zhTW', '老兄，冷靜點', '老兄，就像預言說的，有個$r$c會使我們的靈魂安眠。我們等得可久了!$B$B德拉克瑞人成了失落的一族，好勇鬥狠，他們忘記了曾經擁有過神聖情操，所以他們現在得付出代價。$B$B可是，我們沒做錯事還是遭受苦難，老兄。這片地方必須要有人淨化，而只有活人能辦得到。$B$B以你之身再次加入，並糾正過往的污點吧。從我附近的箱子裡面拿走雪花，讓我的弟兄們睡著。把他們的殘留物拿給你的靈魂嚮導，他知道接下來要怎麼做。', '剛裘需要你到德拉齊金遺跡裡，從他的箱子中收集永眠之雪。對上古德拉克瑞之靈上使用雪花，將德拉克瑞靈魂粒子帶給哈克爾營地的卡拉茲。', '', '去找灰熊丘陵的卡拉茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12138 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12138, 'zhTW', '……我們沒有能源', '你以為這幫傢伙會很厚道地給能量晶格充滿電？事實上，他們留了一手防著我們呢。$B$B好吧，我們總是能想出辦法的，雖然麻煩了點。這兩塊能量晶格的電力僅夠維持作戰魔像很短時間內的動力，要它作戰是不可能的。$B$B你瞧，鐵矮人將閃電斥候部署在丹厄古爾周圍。殺死這些閃電斥候，就可以用作戰魔像從它們的屍體上吸取能量了。', '利用10個閃電斥候為你的作戰魔像充能，然後將充能完畢的作戰魔像交給勘探員哨站的萊加爾·斷眉。', '', '去灰白之丘找勘探員哨站的萊加爾·斷眉。', '充電等級', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12139 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12139, 'zhTW', '「讓火焰來吧!」', '無頭騎士可能會在任何時候攻擊這個村子!火焰將會到處都是!$B$B$n，你願意面對無頭騎士的火焰嗎?等他來的時候，你一定要加入滅火的行列。拿起水桶灑向火源，或是交給靠近火勢的朋友。如果你能熄滅那些火焰，我們或許還有救!', '戴面具的孤兒監護員要你幫忙撲滅村莊中的火勢。等火完全撲滅之後，再和鎮上的戴面具的孤兒監護員交談。', '撲滅火勢', '去找戴面具的孤兒監護員。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12140 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12140, 'zhTW', '全體向隆諾克致敬!', '就像牛頭人、被遺忘者、食人妖、還有血精靈一樣，坦卡族也需要出身己族的領導人。你救出來的那個人，隆諾克，將會成為他們的領導者。$B$B<霸主阿格瑪交給你一張羊皮紙。>$B$B我給你一份熟悉的東西 - 部落的血誓。$B$B將這份血誓交給隆諾克‧冰霧，讓他以坦卡族的領袖身分加入部落。$B$B不要讓他等太久$B$B<阿格瑪點頭。>', '在阿格瑪之錘找到隆諾克‧冰霧，並讓他以坦卡牛頭人領袖的身分加入部落。當你完成任務之後，帶著部落的血誓回去找霸主阿格瑪。', '', '去找龍骨荒野的霸主阿格瑪。', '羅納克·冰霧已啟蒙', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12142, 'zhTW', '害蟲控管', '啊!有隻小畜生狗頭人趁著我們忙著對付上一波龍的攻擊時跑來我們的營地搗蛋。只要咱們一沒注意，他們就會騷擾我們，我已經受夠了!$B$B你會在南邊猛瑪象人營地外圍找到那些狗頭人的藏身之處。去屠殺他們。如果猛瑪象人替他們的奴隸出頭，就把他們也給殺掉。', '第七軍團前線的杜安要求你，到龍眠神殿周圍的猛瑪象人營地殺死10隻雪原極地狗頭人和3隻龍骨荒野猛瑪象人。', '', '去找龍骨荒野的杜安。', '雪原地精怪', '龍骨荒野的巨型獸', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12143, 'zhTW', '峽谷追擊戰', '我真不敢相信!又一團該死的害蟲企圖從我們這裡偷走更多補給品。他們正沿著北邊的峽谷逃逸，追上他們，不管他們是要去找誰，都給我把他解決掉!', '第七軍團前線的杜安要求你，沿著第七軍團前線東北方的峽谷追擊極地狗頭人，並且處理掉他們的領導者。', '', '去找龍骨荒野的杜安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12144, 'zhTW', '害蟲控管', '喂，老兄!在上一波龍的攻擊中，其中一隻小畜生狗頭人跑來我們的營地搗蛋。只要咱們一沒注意他們就跑來煩，我已經受夠了。$B$B你在東邊的猛瑪象人營地外圍可以找到那些狗頭人的藏身之處。去把他們宰掉。如果猛瑪象人替他們的奴才出頭，就把他們也給宰了。', '龍殞營地的剛朵卡尼斯要求你，到龍眠神殿週遭的猛瑪象人營地殺死10隻雪原極地狗頭人和3隻龍骨荒野猛瑪象人。', '', '去找龍骨荒野的剛朵卡尼斯。', '雪原地精怪', '龍骨荒野的巨型獸', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12145, 'zhTW', '峽谷追擊戰', '我真不敢相信!另一群該死的害蟲剛剛又想要拿走我們的補給品。他們現在正沿著峽谷逃逸，追上他們，不管他們是要去找誰，都把他給我殺掉!', '剛朵卡尼斯要求你沿著龍殞營地南方的峽谷追擊極地狗頭人，並且殺掉他們的領袖。', '', '去找龍骨荒野的剛朵卡尼斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12146 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12146, 'zhTW', '擾人的暗示', '號角的底部誇張的紋飾著一柄錘子和一道閃電。這號角上的某些部分看起來極端與猛瑪象人不匹配。$B$B帶著號角往南穿過泰坦之途到龍眠神殿，找出對這個隱含威脅的物品有興趣之人。', '帶著紋飾戰鬥號角前往龍眠神殿，找出能評估這個潛在威脅的人。', '', '去找龍骨荒野的歐拉史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12147 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12147, 'zhTW', '擾人的暗示', '號角的底部誇張的紋飾著一柄錘子和一道閃電。這號角上的某些部分看起來極端與猛瑪象人不匹配。$B$B帶著號角往東穿過泰坦之途到龍眠神殿，找出對這個隱含威脅的物品有興趣之人。', '帶著紋飾戰鬥號角前往龍眠神殿，找出願意評估這個潛在威脅的人。', '', '去找龍骨荒野的歐拉史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12148 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12148, 'zhTW', '獨一無二', '在猛瑪象人之中看到這樣的徽印可真奇怪...這代表有著一定的組織，真不尋常。$B$B猛瑪象人很少撇開他們天生的攻擊性彼此合作。我推測他們可能打算要掠劫一個大型營地。$B$B我很懷疑這號角就只有這麼一支，我希望你證明我是錯的。你會在蒼藍龍殿西北方的峽谷找到骨裂。去挑戰他，然後把我想知道的線索通通帶回來給我。', '在蒼藍龍殿西北方的峽谷中，或峽谷附近找出骨裂，並且殺了牠。把你找到的任何證據帶回來給龍眠神殿的歐拉史卓莎。', '', '去找龍骨荒野的歐拉史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12149 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12149, 'zhTW', '強悍的猛瑪象人', '猛瑪象人是種討人厭的殘暴生物…這就是為什麼我們很少看到他們集結成龐大的數量還不會彼此互相殘殺。他們之中出現了一個強大的領導者，如果我們要終止猛瑪象人的威脅就得把他解決掉。$B$B我正要開始調查。在這段時間我要你盡可能的去擾亂他們。$B$B此地東方豎立了三根火炬。在火炬附近，有三隻猛瑪象人的統治者 - 殺掉他們，爭取一些時間讓我們找出他們的領袖。', '獵殺在龍眠神殿東方的血饗，冰碎，和龍牴。$B$B血饗位於龍墳荒原的東南角，就在翡翠龍殿的北邊。冰碎在黎明之鏡的北緣巡邏。龍牴在青銅龍殿西方的懸崖底下遊蕩。$B$B殺死這些猛瑪象人之後向龍眠神殿的歐拉史卓莎報告。', '', '去找龍骨荒野的歐拉史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12150 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12150, 'zhTW', '隱居的符文大師', '德瑞格瑪·符標是一位猛瑪象人符文大師…稀有的品種。他通常都是獨來獨往，但也和龍骨荒野上一些強大、有影響力的猛瑪象人來往。他一定知道這個新領袖是誰。$B$B隨著天譴軍團和藍龍的問題日益嚴重，我想我們無法獲得任何額外的支援，所以我需要你從德瑞格瑪那裡用必要的手段挖出情報來。$B$B你可以在黎明之鏡上方的懸崖上找到他。', '找出德瑞格瑪·符標;在通往能俯瞰黎明之鏡懸崖的途中，有個道路旁邊的洞穴，他就在裡面。向他挑戰，使用一切手段問出猛瑪象人領袖的名字。獲得情報後向龍眠神殿的歐拉史卓莎回報。', '巨型獸督軍之名', '去找龍骨荒野的歐拉史卓莎。', '巨型獸督軍之名', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12151 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12151, 'zhTW', '跋扈的督軍', '我們沒有理由懷疑德瑞格瑪說的不是真話。不論是葛羅姆薩爾擊敗了你，或是你擊敗了牠，都與他無關。$B$B照著他的指引…帶著你先前交給我的號角，到蒼藍龍殿南方的火炬圈去，然後吹響號角公開宣佈你的挑戰。$B$B當『雷霆使者』葛羅姆薩爾現身的時候，殺了他，然後帶他的頭來見我。', '前往蒼藍龍殿南方的火炬圈，然後吹響紋飾戰鬥號角。擊敗『雷霆使者』葛羅姆薩爾，然後把他的頭帶回去給龍眠神殿的歐拉史卓莎。', '', '去找龍骨荒野的歐拉史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12152, 'zhTW', '吉納拉克的末路', '很高興見到你是活著回來的一員，許多經過死者之徑的人無法回來和我們聊聊旅程。$B$B當你不在這兒的時候，卡拉茲見到了一個影像，揭露了接下來要做的事情。$B$B地穴中的某處藏著一個神聖的祭品。用你先前蒐集的遺物所塑造的靈魂之塵，對著這個祭品使用。$B$B注入能量的祭品將會給墮落的督軍帶來死亡，並解放苦難中的靈魂。$B$B願靈魂指引你的行動，$n。', '哈克爾營地的卡拉茲要你在德拉齊金遺跡裡面收集神聖德拉克瑞祭品，並且對其使用德拉克瑞靈魂之塵。你必須在哈克爾營地外的鑼使用注入能量的德拉克瑞祭品。', '', '去找灰熊丘陵的卡拉茲。', '督軍金納拉克已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12172 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12172, 'zhTW', '達拉然的能量調和', '歡迎你，法師。$B$B你現在肯定在想，達拉然在哪裡？怎樣才能去那裡呢？讓我來幫你吧。$B$B不過在我教你如何傳送到我們偉大的城市去之前，你必須得對你自己和北裂境的魔網能量線進行調和。否則，你可能會在傳送過程中傷害到自己。$B$B帶上這塊魔網調和水晶，轉至這裡西面的眠月花園，在那裡的湍流之針下面的深坑中使用它。這樣你就完成了學習法術的準備。', '群星之墓的大法師茉德拉的影像要你與北裂境的魔網能量線進行調和。', '', '去龍骨荒野的群星之墓找大法師茉德拉的影像。', '與北裂境的魔網能量線調和', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12173, 'zhTW', '達拉然的能量調和', '歡迎你，法師。$B$B你現在肯定在想，達拉然在哪裡？怎樣才能去那裡呢？讓我來幫你吧。$B$B不過在我教你如何傳送到我們偉大的城市去之前，你必須得對你自己和北裂境的魔網能量線進行調和。否則，你可能會在傳送過程中傷害到自己。$B$B帶上這塊魔網調和水晶，轉至這裡西南面的眠月花園，在那裡的湍流之針下面的深坑中使用它。這樣你就完成了學習法術的準備。', '阿格瑪之錘的大法師艾薩斯·奪日者的影像要你與北裂境的魔網能量線進行調和。', '', '去龍骨荒野的阿格瑪之錘找大法師艾薩斯·奪日者的影像。', '與北裂境的魔網能量線調和', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12179, 'zhTW', '特別任務1[PH]', 'DESCRIPTION: Complete this quest for Specialization 1.', 'LOG: Complete this quest for Specialization 1.', '', '去找Jonathan LeCraft。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12180, 'zhTW', '被俘的勘察員', '為了探查神器和當地歷史的資訊，瑞加爾派了一隊的勘察員進丹亞戈。瑞加爾的小隊卻從未料想到丹亞戈是如此的人口眾多。當鐵矮人備戰的同時，他們被俘，但是我們不夠人手救出他們，而瑞加爾又忙著幻想著如何打敗鐵矮人而分身乏術。任務落在你肩上了，$N，任何鐵矮人和他們僕役的身上，都有可能帶著關有勘查員牢房的鑰匙。', '救出勘察員加恩、勘察員拓剛和勘察員韋拉那，再向勘察員崗哨的巡山人基立安回報。', '', '去找灰熊丘陵的巡山人基立安。', '救出勘察員加恩', '救出勘察員拓剛', '救出勘察員韋拉那', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12186, 'zhTW', '旗幟:贏家', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12187, 'zhTW', '旗幟:參賽者', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12190, 'zhTW', '跟我的小朋友問好', '哈克爾看到這些上選的材料以後，一定會自願掏出金塊的。剩下就是把東西帶給他了。$B$B他就在東方邊境處紮營，靠近鬧鬼的德拉齊金遺跡。$B$B在我搞定這些屍體之前，你應該可以到得了那裡...除非，你對屍體防腐比較感興趣?', '皮格蒙要你將哈克爾的原料，帶給哈克爾營地的哈克爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12191 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12191, 'zhTW', '乾了再砸!', '那些討厭的黑鐵矮人又回來了!我們要確定你有保護自己的能力。更重要的是，我們要知道你能保護我們的財產!S.T.O.U.T.已經準備好了，對吧?把免費招待的啤酒節樣品給喝光，然後拿酒杯來丟擲S.T.O.U.T.!擊中目標5次之後再來找我。', '使用免費招待的啤酒節樣品並丟中S.T.O.U.T.5次，然後和比索·迅提談談。', '', '去找杜洛塔的比索‧迅提。', '命中S.T.O.U.T.', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12193 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12193, 'zhTW', '今年有沒有紀念品？', '啤酒節除了競速山羊外，還要痛快暢飲!有空的時候，拿這個兌換券去找貝爾碧·迅移。她就在啤酒節營地後方附近。如果你沒看見她，別擔心，她一定會看見你的。$B$B總之，拿這個兌換券給她以換來你的免費啤酒節酒杯。她很樂意處理各種啤酒節的交易。', '把啤酒節酒杯兌換券交給啤酒節營地的貝爾碧·迅移。', '', '去找丹莫洛的貝爾碧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12194 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12194, 'zhTW', '喂，聽說今年沒有紀念品，是不是真的啊?', '我們不但供應民眾啤酒，同時我們還贈送酒杯!只要用正式的票卷就可以換取漂亮的紀念杯!這張兌換卷給你。跟啤酒節營地前方的布力克斯談話。他個性古怪，甚至現在他老是戴著那副護目鏡。他會幫你兌換那張兌換券，並且啤酒節的其他交易都可以找他。', '把啤酒節酒杯兌換券交給啤酒節營地的布力克斯·修械。', '', '去找杜洛塔的布力克斯·修械。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12195 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12195, 'zhTW', '意外的訪客', '最近一次出發的狩獵隊，不只帶回了獵物。$B$B他們碰上一名負傷的矮人，從鐵矮人的要塞丹亞戈逃出來，他可能知道一些能夠用來對付咱們宿敵的資訊，但是在這之前，我們得先讓他退燒才行。$B$B在附近森林中出沒的覆銀成鹿，牠們的角一直以來都用來做成治療的膏藥。如果你能多帶些角回來，我能便能試試這些膏藥能不能讓我們的「訪客」醒過來。', '把5根成年鹿角帶給歐尼克瓦營地的『刀疤』托邁克。', '', '去找灰熊丘陵的『刀疤』托邁克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12196 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12196, 'zhTW', '從頭開始', '我沒那麼多閒工夫自己鑄造零件，可是位於東南方丹亞戈的鑄造場正日以繼夜的量產魔像零件。$B$B我想，你應該回去那裡，根據這張藍圖，把零件收集好給我。$B$B這些零件遍佈在鐵矮人符文鐵匠工作的建築物理面。$B$B$n，請快一點，托邁克看起來就要藉故發火了!', '把8個戰爭魔像零件交給歐尼克瓦營地的勘察員洛卡。', '', '去找灰熊丘陵的勘察員洛卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12197 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12197, 'zhTW', '我們要能量', '嗯，我們有了魔像的外殼，但是對托邁克來說，這還不夠好。他根本不瞭解這些東西不會自己兜在一塊兒，然後奇蹟似地自己動起來!我們需要電池來啟動它。$B$B當我還在丹亞戈的時候，我注意到符文鐵匠杜拉爾和符文鐵匠卡索恩是製作電池的人。我需要從他們身上各拿一個電池，來替我們的魔像充能。$B$B你可以在丹亞戈中央樓層的工坊中找到這兩位符文鐵匠。', '把杜拉爾的能量電池和卡索恩的能量電池交給歐尼克瓦營地的勘察員洛卡。', '', '去找灰熊丘陵的勘察員洛卡。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12198 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12198, 'zhTW', '...也許還沒好', '魔像的電池已經充能，足以讓它以最低效率運作，但是啟動作戰系統，還需要更多的能量。$B$B好消息是，丹亞戈的外緣有許多的閃電哨兵巡邏，我們可以借助它們的能量替魔像的武器系統充能。$B$B把魔像帶在身邊，靠近這些哨兵，當哨兵死掉之後，它就會吸收這些能量。', '從10個閃電哨兵上替你的戰爭魔像充能，然後向歐尼克瓦營地的勘察員洛卡回報。', '', '去找灰熊丘陵的勘察員洛卡。', '衝鋒等級', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12199 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12199, 'zhTW', '打倒鐵族長', '既然魔像已經完全充滿能量了，咱們就可以用它來對付丹亞戈的首領。$B$B根據我對丹亞戈的首領「鐵族長怒錘」的觀察，他總是被一個魔像用護盾貼身保護著，讓他免受傷害。$B$B我們可以擾亂那具名叫鐵砧的魔像，讓它降下這面護盾。利用你那具魔像的電磁脈衝能力就能完成這項工作。$B$B族長就待在丹亞戈頂端的主要工廠裡面，監督著下層產品進度。', '利用戰爭魔像的能力，擊敗鐵族長怒錘，接著向歐尼克瓦營地的『刀疤』托邁克回報。', '', '去找灰熊丘陵的『刀疤』托邁克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12200, 'zhTW', '翡翠龍之淚', '隨著荒疫化合物的惰性樣本完成，與活化觸媒的到手，我們只剩下一個合適的空殼容納這兩樣成分，就大功告成了。$B$B此處西南，龍骨荒野的海岸邊，你可以發現翡翠龍殿。殿內你可以找到一顆硬化的綠龍淚珠殘留，我不清楚來由是什麼，但，他們在死前哭得可兇了。去查查。$B$B去翡翠龍殿收集淚珠。', '首席瘟疫使者米道頓需要你收集8顆翡翠龍之淚。他就在龍骨荒野上的毒怨之地裡。', '', '去找龍骨荒野的首席瘟疫使者米道頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12201, 'zhTW', '監督者的分身', '聽起來洛肯才是鐵矮人迅速整軍的幕後主使。$B$B只有最高位階的鐵矮人才能接近他的身邊，所以，我們要把你喬裝成一個監督者，好讓你知道那裡究竟發生了什麼事情。$B$B我有個計畫，不過需要一些物資補給。$B$B在丹亞戈找到一名鐵符文監督者，殺掉他，把他的制服帶回來。', '將一件監督者制服帶給歐尼克瓦營地的斥候沃塔克。', '', '去找灰熊丘陵的斥候沃塔克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12202, 'zhTW', '留下倩影', '我們要把工作完成，把你跟那些討人厭的鐵矮人弄成同一個德性。$B$B最好的方法就是根據真的鐵矮人大頭照來製作偽裝。$B$B當托邁克的狩獵小隊發現了那個倔強的勘察員，他們把他手上的攝像機奪走了。我想現在我們有機會使用到了。$B$B把攝像機帶去丹亞戈，殺幾個鐵矮人，把他們的樣子用這個機器記錄下來。樣本照夠了，你再把攝像機帶回來。', '使用洛卡的攝像機紀錄8位丹亞戈鐵矮人的影像，然後向歐尼克瓦營地的斥候沃塔克回報。', '', '去找灰熊丘陵的斥候沃塔克。', '已捕捉鐵矮人的影像', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12203, 'zhTW', '洛肯的命令', '我把你的監督者偽裝所需的所有零件都準備好了。穿上去的時候別吐出來，為了要逼真，我花了不少工夫在上面。$B$B把偽裝工具帶去東南方的丹亞戈，偽裝你自己，前往城市寬廣的中央區最東邊的建築物。$B$B在那裡，你應該可以看見一個族長和監督者聽取洛肯命令的平臺。在偽裝的情況下啟動它，盡你所能的蒐集情報。', '把你自己偽裝成鐵符文監督者，攔截洛肯的訊息，然後回報給歐尼克瓦營地的斥候沃塔克。', '', '去找灰熊丘陵的斥候沃塔克。', '已收到洛肯的訊息', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12204, 'zhTW', '以洛肯之名', '鐵矮人是北裂境最兇猛也最主要的敵人之一，不論我們到哪，他們嘴上總掛著洛肯的名字和我們奮戰。$B$B我們必須知道這個洛肯是誰，他的目的何在。當地人也許會幫忙。$B$B前往東北方的紅木貿易站，有個人名叫休‧格雷斯，兜售著他的貨物。更向東去，瑟希斯遺跡裡面，你可以找到一個名叫葛夫洛克的石巨人。從他們口中打聽洛肯的消息。他們一定知道一些有用的消息。', '和休‧格雷斯及葛夫洛克聊聊關於洛肯的消息，並向歐尼克瓦營地的斥候沃塔克回報。', '', '去找灰熊丘陵的斥候沃塔克。', '已審問休·格拉斯', '已審問加夫洛克', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12205 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12205, 'zhTW', '懸賞：血色突襲軍', '奉高階執行官羅思之命，所有血色突襲軍的非法組織成員都將即刻處死。$B$B絕不寬恕，同時執行本命令而遭受人類俘虜的成員都應該知曉，他們將被刺死，抑或受到更嚴重的懲罰!$B$B引述高階執行官之言:「讓雪地用他們的血染成紅色!」', '殺死20名血色突襲軍成員，並將成果回報給毒怨之地的高階執行官羅思。', '', '去找龍骨荒野的高階執行官羅思。', '血色十字軍成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12206, 'zhTW', '荒疫告別式', '你看過徵人海報了嗎？高階執行官究竟在想什麼？！$B$B<維琪朝四周張望，壓低聲量繼續說著。>血色突襲軍被他們的牧師復活了，這對我們來說一點也不好，更糟糕的是，復活成為天譴軍，對吧？$B$B是的，我完全同意你的看法，關於屍體我們得想想辦法。$B$B我有些東西。拿著這些我剛創造出來的荒疫，然後對著牢籠中的囚犯們試試看。$B$B不髒、不亂、也不會有敵人反擊。', '毒怨之地的藥劑師維琪‧萊文要求你對血色突襲軍囚犯測試荒疫之瓶。', '', '去找龍骨荒野的藥劑師維琪‧萊文。', '已測試枯萎藥劑', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12207 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12207, 'zhTW', '沃達希爾的傾圮', '久遠之前，強大的德魯伊在此處的東北栽植了一株巨木。$B$B該株巨木被稱為沃達希爾，也就是承繼了諾達希爾的...世界之樹。沒有人知道原因，但就在樹木完全長成以後，德魯伊們決定必須毀掉它。$B$B自從我們抵達這裡以來，$n，大地就不斷對我傾訴。她苦楚的哭號從沃達希爾殘株倒下的地方傳來。$B$B腐化的軟泥怪在該處遊蕩，帶給我一些軟泥怪的樣本，好讓我們開始治療這片土地。', '征服堡的風先知灰角需要你前往沃達希爾之枝、沃達希爾之心與沃達希爾之淚三處，從混亂軟泥怪身上獲得6件黏液樣本。', '', '去找灰熊丘陵的風先知灰角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12209 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12209, 'zhTW', '掠奪軍品', '啊，很好，新面孔。你想要證明你的實力嗎，新面孔？$B$B血色十字軍中，最狂熱也最偏執的血色突襲軍，阻擋了南方的後路。如果我們要對抗他們，在短時間之內，必須要準備比我能鍛造出還要多的鎧甲與武器。$B$B我們為何不搶他們的來用呢？$B$B講白一點，「你」為何不搶他們的來用呢？', '毒怨之地中的軍需官巴特勒要求你偷取8件血色突襲軍護甲與8把血色突襲軍武器。', '', '去找龍骨荒野的軍需官巴特勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12211 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12211, 'zhTW', '阻止他們復活!', '我就是不懂，荒疫不是早該生效了!$B$B算了，別費神了。$B$B<藥劑師基於某種原因似乎鬆了一口氣。>$B$B雖然荒疫沒辦法在血色突襲軍身上發生效果的原因不明，但我們仍然得阻止牧師復活他們。$B$B我想到了別的點子，他們的屍體絕對防止不了這招。$B$B$n，帶著我的鼠籠，對你在新壁爐谷所遇到的血色突襲軍員屍體上放出這些老鼠。我把這些鼠輩們餓了好幾頓，牠們肯定見到什麼吃什麼!', '毒怨之地的藥劑師維琪‧萊文要求你使用她的老鼠容器到新壁爐谷清理15具血色突襲軍成員的屍體。', '', '去找龍骨荒野的藥劑師維琪‧萊文。', '血色十字軍屍體已被清空', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12212, 'zhTW', '倉庫補貨', '早啊，$c。$B$B中尉大人提過，倉庫被部落洗劫，使得我們的糧食補給嚴重不足。$B$B不用說，我們要讓這些惡棍付出代價，但是首要我們得專注在補足倉庫。我的手下盡力在做了，但是為了要扭轉劣勢，我們需要每個成員貢獻出力量。$B$B你可以在本地的成鹿身上取得鹿肉。祝你狩獵愉快!', '琥珀松小屋的護林者大師安德豪爾需要你殺死高角成鹿，並收集8塊多汁鹿肉。', '', '去找灰熊丘陵的護林者大師安德豪爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12213 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12213, 'zhTW', '竄出的黑暗', '有些東西...黑暗的東西...侵襲了沃達希爾。就在德魯伊們決定摧毀世界之樹之後，它中空的殘枝依然生長著盤根，直入地底。$B$B我需要你前去東北邊殘破樹幹的三處地方，盡你所能的深入地底。$B$B一旦你下到裡面，使用這顆寶珠，讓該區域環繞的能量對它留下痕跡。這會散發出些許光亮，看清沃達希爾發生了何事，並且瞭解為什麼它無法成為一株世界之樹。', '征服堡的風先知灰角需要你前往沃達希爾之枝、沃達希爾之心與沃達希爾之淚三處，在其地表之下深處使用地卜者寶珠。', '', '去找灰熊丘陵的風先知灰角。', '已於沃德拉希爾之心下方使用法球', '已於沃德拉希爾之肢下方使用法球', '已於沃德拉希爾之淚下方使用法球', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12214 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12214, 'zhTW', '新的坐騎', '你好，我是漢瑟爾。很高興認識你，$g先生:女士;。$B$B執行官找上我，說：『漢瑟爾，我要你幫我們弄些新的坐騎來。』$B$B他以為亡靈馬是從地裡長出來的嗎？$B$B（悄悄話）其實……如果你能找到馬的墳場，牠們還真的是從地裡長出來的。$B$B不過我們這裡沒有那種地方，所以我要你做的是，往南到新爐火谷去，殺掉那些騎士，拿走他們的馬鞭，偷走他們的戰馬。$B$B把馬騎回來給我，然後把韁繩交給我，拜託了。', '汙毒村的漢瑟爾‧包爾要你偷走3匹十字軍戰馬並交給他，同時交出韁繩。', '', '去找龍骨荒野的漢瑟爾‧包爾。', '血色十字軍戰馬韁繩已交出', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12222, 'zhTW', '縛火者的秘密', '就當我們要擊退部落的時候，靠近南邊海岸，掠龍族人在他們沃德盧恩的村內進行徵兵。$B$B村子裡最強的戰士被授予火焰灌注咒符，使他們有控制強大、野蠻的元龍之力。如果我們能控制其中一隻元龍，也許我們能利用牠解決沃德盧恩所構成的威脅。$B$B掠龍縛火者製造出咒符，同時灌注力量進去。殺掉他們，拿走咒符。', '帶3條火焰灌注咒符給琥珀松小屋的護林者崔克。', '', '去找灰熊丘陵的護林者崔克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12223, 'zhTW', '削弱敵軍', '南方沃德盧恩村發生了一連串的騷動。族長特沃德‧艾利克森以及他的侍衛正在準備出征。這片荒野上，我們大多數的人都在對抗部落的詭計，琥珀松將會非常脆弱。$B$B旅行至沃德盧恩，很靠近南方的海岸，讓掠龍族人曉得我們不是好欺負的。$B$B殺掉那些侍衛，多多益善。讓他們想想，在這個與部落衝突的時刻，進犯我們是不智的。', '殺死12名掠龍侍衛，返回琥珀松小屋的護林者崔克那裡。', '', '去找灰熊丘陵的護林者崔克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12226 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12226, 'zhTW', '一路暢通到底', '$r，我們得快點!我可不能冒險讓這些珍貴的種子被消化掉。「馬上」把它們給弄出來。$B$B到西邊河岸採收一些黑根草，我會為你調配一些瀉藥，這樣應該會有所作用。$B$B快點去!別忘了，這是你自找的...', '琥珀松小屋的安德豪爾需要你帶給他5株黑根莖。', '', '去找灰熊丘陵的護林者大師安德豪爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12227 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12227, 'zhTW', '我可幫不了你', '好了，$r。這是黑根草的汁。$B$B一喝見效，所以麻煩你到廁所之後再喝下去。$B$B把種子還給我!', '琥珀松小屋的安德豪爾需要你飲用安德豪爾的黑根沙，並且利用附近的廁所將消化一半的琥珀種子取回來。', '', '去找灰熊丘陵的護林者大師安德豪爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12228, 'zhTW', 'Reacquiring the Magic [PH]', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12229, 'zhTW', '可能的關聯性', '不久以前，我們派遣了一支遠征隊前往被瘋狂熊怪攻擊的東方。生還者描述殺死其中一隻熊怪時，他的身軀流淌出一種黑色黏稠的物質。$B$B千年以來，這個區域的熊怪都很溫和，也許熊怪的異常行為與我們調查出的黑暗能量有關聯。$B$B帶給我熊怪血液的樣本，你可以在東邊怒牙聖壇和心之血聖壇找到他們。', '征服堡的風先知灰角需要你從怒牙聖壇和心之血聖壇的熊怪身上獲取8瓶瘋狂熊怪之血。', '', '去找灰熊丘陵的風先知灰角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12230, 'zhTW', '向攻城鐵匠行竊', '我被賦予摧毀血色突襲軍弩砲的任務，但很不幸的，我和諸位藥劑師們對於如何使用我們的資源意見不一致，因而我沒有任何東西可以用來摧毀弩砲!$B$B東北邊就是腐屍農地。熔爐和血屍戰車旁的天譴攻城鐵匠們是破壞的專家。$B$B我們的運氣很好，他們也將炸彈放置於附近。$B$B我需要你替我拿回這些炸彈，我不管你是從地面上，或者是攻城鐵匠身上找到都可以。', '毒怨之地的亡靈衛兵莫爾德要求你拿回6個攻城鐵匠炸彈。', '', '去找龍骨荒野的亡靈衛兵莫爾德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12231 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12231, 'zhTW', '熊神的後裔', '灰白之丘的熊怪，可能受到與沃達希爾的疫病相同的肆虐。他們被牽連進最近一場血腥的部族戰爭，就在數年的和平共處之後。$B$B他們所護衛的東方聖壇，正是厄索克後裔的老家。$B$B如果這股墮落之力已經影響了熊怪，可能的理由是他們之間的血脈，寇荻安與歐爾嵩仍然沒有受到傷害。$B$B如果原因是如此，找出他們，聆聽他們說什麼。', '征服堡的風先知灰角要求你和怒牙聖壇的歐爾嵩，以及心之血聖壇的寇荻安交談。', '', '去找灰熊丘陵的風先知灰角。', '歐爾森的故事', '科迪安的故事', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12232, 'zhTW', '炸毀弩砲', '終於，輪到我們對他們的攻城機具進攻了!別搞砸了。$B$B我說笑的。$B$B一點點啦。$B$B$c，用這些炸彈轟炸新壁爐谷的弩砲。$B$B我們會向皇家藥劑師學會展現我們的老方法:根本不需要策劃!', '毒怨之地的亡靈衛兵莫爾德要你使用攻城鐵匠炸彈轟炸5臺新壁爐谷弩砲。', '', '去找龍骨荒野的亡靈衛兵莫爾德。', '已轟炸新爐火谷投石車', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12233, 'zhTW', '處理種子', '不，不……還是你拿著吧。$B$B你不會真的想讓我拿著它們吧？$B$B接下來你該這麼做……', '不，不……這些東西你留著。$B$B在經歷了那些事之後，你該不會真的以為要由我來處理這些吧？$B$B你接下來要做的是……', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12238 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12238, 'zhTW', '淨化德拉克薩隆', '好朋友，時候終於到了。德拉克薩隆很快就會從邪惡的不死生物中淨化，回復到原本高貴的樣子。我的靈魂將會安息，同時報答你的幫助，要塞裡面最珍貴的寶藏就是你的了，老兄!要塞的頂端有一座神聖的通靈塔，只要你爬到塔頂，你必須最後一次召喚我過去，而我將完成儀式。哎呀，召喚我照例需要一些材料。從要塞的倖存者身上收集一些魔精吧。', '德拉庫魯需要你在德拉克薩隆的火盆上使用德拉庫魯的藥劑。你需要五個耐久魔精才能使用德拉庫魯的藥劑。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12249, 'zhTW', '熊神厄索克', '是時候了，$N。帶著這些灰燼，尋找寇荻安跟你提過的熊怪。如果他動身尋找厄索克，他一定在厄索克的巢穴附近，灰喉鎮的北邊。你會需要他的協助，你是無法獨力擊敗厄索克的。當你打敗厄索克之後，使用這些灰燼來淨化他的靈魂，屆時才知道我們的努力是否會付諸流水。', '琥珀松小屋的祭師賽苓要你找到厄索克之穴附近的圖爾·怒掌，在他的協助之下擊潰厄索克。達成任務之後，在厄索克的屍身上使用淨化過的沃達希爾灰燼。', '', '去找灰熊丘陵的祭師賽苓。', '淨化厄索克', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12256 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12256, 'zhTW', '縛火者之秘', '即使聯盟的懦夫攻擊我們的據點，但東南方沃德盧恩的掠龍維酷哨站仍在繼續準備戰爭。維酷人和我們所面對過最強的敵人相比，還差得遠呢，但是我們得在他們真正給我們造成威脅之前，徹底消滅他們。$B$B他們之中最強的鬥士才能駕駛元龍作戰，縛火者製造出了威力強大的咒符，來控制這些野獸。你需要殺掉他們，奪走咒符，使我們的計畫成功。', '帶3個火焰灌注咒符給征服堡的士官納茲格寧姆。', '', '去找灰熊丘陵的士官納茲格寧姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12257, 'zhTW', '展現實力', '東南方沃德盧恩的維酷村落正在為戰爭作準備。沃德盧恩的族長沒辦法湊出一支龐大的軍隊，但是在我們的軍力這麼分散的狀況下還是很有風險。$B$B我們不能讓族長跟他的部下有機會攻擊，所以我們必須主動迎敵。如果你真的是個部落的$c，你會很高興有這個機會能展現我們的實力。$B$B殺掉那些侍衛，告訴那些掠龍者不該看輕部落!', '殺死12個掠龍侍衛，然後回去找征服堡的士官納茲格寧姆。', '', '去找灰熊丘陵的士官納茲格寧姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12258 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12258, 'zhTW', '亡者的宿命', '順著這條路下去，城鎮中心滿是橫行著的溫特加德不死居民!我們的墓穴似乎成了天譴軍永無止境的士兵增援處、朝我們襲來。然而，別對他們手下留情，$n，當他們曾經是血肉之軀，還具備良知與思想，如今他們成為了肆虐的不死生物，僅有一個目標，那就是我們的毀滅。$B$B朝城鎮中心的方向殺出一條血路，送這些復仇魂屍回去製造他們的地方，讓他們安息吧。', '龍骨荒野上溫特加德要塞中的指揮官萊諾爾‧風矛需要你殺死15隻復仇魂屍。', '', '去找龍骨荒野的指揮官萊諾爾·風矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12259, 'zhTW', '沃德盧恩的族長', '有了這些灌注了火焰的符咒，我們終於可以挑戰族長了。$B$B他最喜愛的坐騎是一隻叫做烈焰使者的凶暴元龍。牠被鐵鍊綁在沃德盧恩的西部，但你應該可以利用符咒的力量操控牠來對付族長。$B$B一旦你控制了烈焰使者，就去沃德盧恩的塔頂找出族長並利用烈焰使者來消滅他。', '利用烈焰使者擊敗族長特沃德‧艾利克森，然後向征服堡的士官納茲格寧姆回報。', '', '去找灰熊丘陵的士官納茲格寧姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12260 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12260, 'zhTW', '完美的假象', '你可能會懷疑我是如何維持這身偽裝的;我用了女間諜借給我的魔鏡。$B$B它的能力有限，但我想應該夠我們兩個用。拿著，我要你用鏡子假扮成一個突襲軍血鴉牧師。$B$B動作要快...我不知道你拿走鏡子之後我這個美麗外貌能夠維持多久。$B$B你要明白，這不會立刻將你完美的偽裝起來，所以直到我能抽空幫你以前，都不要以為這是萬無一失的偽裝。', '新壁爐谷的史考莉探員要你偷取突襲軍血鴉牧師的影像。完成之後將女妖的魔鏡還給史考莉探員。', '', '去找龍骨荒野的史考莉探員。', '十字軍烏鴉祭司的影像已竊取', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12261, 'zhTW', '無處可逃', '他們正從我死去的兄弟們的骸骨上汲取能量...$B$B我並不喜歡詛咒神教，但他們厚顏無恥的行為已經惹怒了我。我不會手下留情...反正我也沒有所謂的慈悲心。$B$B我要你去確保當屠殺開始的時候他們沒路可逃。把這個毀滅禦符放在龍殿的出口盡頭。守護它，直到它完全充能完成為止。', '將毀滅禦符放在黑曜龍殿的出路盡頭，就在開始積雪的地方。保護禦符，直到它完全充能好為止，然後向賽瑞納爾回報。', '', '去找龍骨荒野的賽瑞納爾。', '破壞守衛已充能完畢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12262 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12262, 'zhTW', '求救無門', '我們一個都不會放過。$B$B就在外面，下流的通靈師與他們的骷髏僕役使我的領地蒙羞。把他們屠殺殆盡。', '在黑曜龍殿外面殺死6個燃燒深淵通靈師與10個悶燒的骷髏。一旦你完成了這項工作，向賽瑞納爾回報。', '', '去找龍骨荒野的賽瑞納爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12263 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12263, 'zhTW', '不懷好意', '詛咒神教並非只是為了汲取死去龍族的力量而來。我想我知道他們的目的，但我需要你幫我證明我是對的。$B$B我會幫你覆上這個通靈師的偽裝。回到洞穴裡確認他們待在這個神聖之地究竟有何企圖。我會透過你的雙眼來觀察。$B$B小心一點，$n，如果你受到任何的傷害，這脆弱的幻象很可能就會消失。', '等待賽瑞納爾幫你偽裝成燃燒深淵通靈師，然後回到奈薩里奧之喉刺探詛咒神教的動向。完成後向賽瑞納爾回報他們的意圖與細節。', '發現熔岩龍復活密室', '去找龍骨荒野的賽瑞納爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12272 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12272, 'zhTW', '流血的礦石', '在納克薩瑪斯進攻的幾小時之前，我們有個礦工碰巧發現了一種暗色礦石，會不斷的流出黏濁的液體。在疏散礦坑的混亂之中，我們失去了那個陌生礦脈的樣本。現在天譴軍團正在為了製造他們的死亡機械探礦。$B$B你必須回去在此處東北方的腐屍農地裡的溫特加德礦坑，並回收這種奇怪的礦石。對我們的任務來說，這是至關緊要的一件事!', '龍骨荒野上溫特加德要塞的攻城工程師刻閃要你從溫特加德礦坑回收10個奇怪的礦石的樣本。', '', '去找龍骨荒野的攻城工程師刻閃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12273 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12273, 'zhTW', '辱罵', '是時候徹底打擊突襲軍的士氣了!$B$B我要你拿著權杖並且用在他們的四個領導者身上:軍營樓上的指揮官喬丹，東南方面海斜坡上的砲手指揮吉爾哈特，鐵匠舖的鐵匠古德曼，以及在獸欄的獸欄管理員梅瑟。$B$B用權杖支配他們，集中意志迫使他們辱罵突襲軍，然後把他們全部殺光!', '高階執行官羅思指派你對指揮官喬丹、砲手指揮吉爾哈特、鐵匠古德曼，以及獸欄管理員梅瑟使用強制權杖。使用之後殺了他們，迫使他們在臨終前辱罵血色突襲軍。', '', '去找龍骨荒野的高階執行官羅思。', '喬丹指揮官的指控與死亡', '首席砲手齊爾胡特的指控與死亡', '鐵匠古德曼的指控與死亡', '馬廄主人默瑟的指控與死亡', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12274 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12274, 'zhTW', '失寵', '我們需要從高階修士那裡弄來更多情報，現在我們有血鴉牧師的幻象，我想我可以讓你與他近距離談話。$B$B不幸的是，我們必須把他和他的護衛分開，否則你永遠無法從他身上得到任何的情報。$B$B<探員靠在她的鏟子上想了一會兒。>$B$B我想我知道怎麼做了!保持著偽裝，爬上修道院的頂端然後把鐘敲響。那樣應該會讓修士的護衛跑開，然後你就可以下去和他說話了。', '新壁爐谷的史考莉探員要你敲響修道院的鐘，然後與高階修士談話獲取情報。', '', '去找龍骨荒野的史考莉探員。', '修道院的鐘已敲響', '已與大修道院長交談', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12276, 'zhTW', '尋找史霖金', '雖然我並沒有史霖金的消息，也不知道他遭逢了什麼樣的命運，但也許我可以幫助你尋找他。$B$B<刻閃掏出了一個迷你機械玩具。>$B$B這並不是一個玩具，新夥伴。事實上，這是我最新的發明的機器。這個機器的唯一功能，就是用來尋找失蹤者。雖然這個狀況很不幸，但這台機器是你尋找史霖金的最佳選擇。$B$B你準備好要開始搜索的話，就把這個機器人放在我身旁的地上。', '在溫特加德礦坑中找到『爆破地精』史霖金。如果你需要引導，可以利用刻閃的追蹤機器人。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12278, 'zhTW', '每月啤酒俱樂部', '會員享有優惠。成為「每月啤酒俱樂部」的會員，表示你有管道獲得到最新、最青的啤酒。$B$B帶著你的「每月啤酒」俱樂部會員表格給拉金‧雷酒，他就在鐵爐堡的石火旅店中。', '把「每月啤酒」俱樂部會員表格帶給拉金‧雷酒，他就在鐵爐堡的石火旅店中。', '', '到鐵爐堡的石火旅店找丹莫洛的拉金‧雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12286, 'zhTW', '糖果桶', '', '這種糖果桶在各地的旅店都有。來吧…拿點糖果！。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12287, 'zhTW', '歐利克·真心與遺民之濱', '我凝視著寶珠、看見了你必經的道路，$N。多年以前，龍骨荒野海岸邊發生了一件慘劇。事件的本身依舊晦暗難明，但是我相信你的宿命就在南方，在遺民之濱的諸多廢墟之中。沿著東南方的路走下去，經過被蹂躪的城鎮廣場，順著路走，直到黎明之境。你會遇到我的一個老朋友，名叫歐利克·真心。他在那兒等著你。', '在龍骨荒野的黎明之境上，尋求歐利克·真心的協助。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12300 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12300, 'zhTW', '堅毅試煉', '好吧，朋友。你幫了我們一兩個小忙，但這並沒有測試出一個人真正的勇氣。$B$B在這一帶，如果你沒有披上自己獵物的皮，都不能算是一個真正的獵人。$B$B<瑟傑拔出他自己的剝皮刀遞給你。>$B$B這些攻擊我們城鎮的獸人混蛋，他們的領袖叫做斷骨;你可以在西北邊的營地找到他。$B$B沒錯，你要去剝那個混帳的皮。', '在銀溪鎮的西北邊找出斷骨中士，並且通過堅毅試煉。', '', '去找灰熊丘陵的被俘虜的陷捕者。', '膽識試煉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12301, 'zhTW', '真相會解放我們', '齊利格多年前將這顆水晶球交給我，並且囑咐我詳細的使用說明。近五年，每當我對此所發生的事情感到憤怒、憂心或哀傷的時候，我就會專注我的意念到這顆水晶球上。 直至現在我才瞭解齊利格送我這顆寶珠的原因。 將我的水晶寶珠帶到遺民之濱，在海灘的上層找到我的舊基地廢墟，並且把寶珠放置於城鎮的中央。令這些被遺民們透過我的心靈看看這個世界。', '在遺民之濱的廢墟中使用歐利克水晶寶珠，救贖這些被遺民。', '被遺忘者已救贖', '去找龍骨荒野的歐利克·真心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12303, 'zhTW', '提供軍資金', '<軍需官壓低聲音對你耳語。>$B$B$c，我需要你的幫助;我們的金庫全空了，憤怒之門的柯爾克隆先鋒駐地為了那邊的作戰把我們的錢全部拿走了。$B$B不過，我聽說東南方遺民之濱那些沉船上藏有財寶。$B$B我們非得快點做些什麼才行，否則我們很快就無法繼續對抗血色突襲軍了。你知道，戰爭很花錢的!', '毒怨之地的軍需官巴特勒要你回收6個遺民寶藏。', '', '去找龍骨荒野的軍需官巴特勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12304, 'zhTW', '海濱地產', '是時候擴張毒怨之地了!$B$B我們會在時機適當的時候對付突襲軍，但我要你帶頭前往遺民之濱。那裡的房屋很有潛力，而且景觀很好!$B$B不幸地，那兒有一大群人類鬼魂，遇難的船員，和其他沒發現自己已經死亡的傢伙。$B$B清空海濱和淺灘，然後你我兩人就可以來討論怎麼在那裡蓋一座新的愜意小陵墓。', '遺民之濱北邊的勘測員漢森要你殺死20個遺民鬼魂。', '', '去找龍骨荒野的勘測員漢森。', '被遺忘的幽魂已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12306, 'zhTW', '每月啤酒俱樂部', '$n，團結就是力量。成為「每月啤酒」俱樂部的一員，意味著你和你的同好隨時享用最青的啤酒。$B$B帶著你的「每月啤酒」俱樂部會員表格交給雷瑪，他就在奧格瑪精神谷的暗木小屋裡。', '帶著「每月啤酒」俱樂部會員表格交給雷瑪，他就在奧格瑪精神谷的暗木小屋裡。', '', '去找奧格瑪的雷瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12307, 'zhTW', '禍狼根', '你聽過禍狼草嗎?那是種恐怖的植物...會摧毀我們的即將收成的作物。$B$B我們花了整整一個星期把它們砍掉，但這些草根又開始發芽了。$B$B這看起來雖然不像是一件緊急的事情，但這種植物再長出來可真的會是...一場災難。如果你在村子附近找到的話，你能夠幫忙拔除它們嗎?', '銀溪鎮的卡特加要你拔除8個禍狼根。', '', '去找灰熊丘陵的卡特加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12308 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12308, 'zhTW', '逃離銀溪鎮', '你...你不是他們的一份子?快點!放我出去!$B$B我們必須立刻前往琥珀松小屋!一旦都蒙特中尉發現這些傢伙究竟是什麼人，這個城鎮會被徹底摧毀!', '打開木籠，然後幫助獲釋的聯盟斥候逃離銀溪鎮。當你抵達琥珀松小屋之後，向都蒙特中尉報告。', '', '去找灰熊丘陵的都蒙特中尉。', '從銀溪村逃脫', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12313, 'zhTW', 'UNUSED Save Brewfest!', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12315, 'zhTW', '粉碎澈水艦長!', '每次推進，我們的人就會遭遇新的聯盟援軍。簡直就像是他們的指揮官算準了我的每一步似的!$B$B現在偉大的澈水艦長該去死了。他在海灣遠處的聯盟驅逐艦上指揮他的部隊。$B$B這會是場硬仗，$n。帶幾個值得信賴的朋友，或者你有鑰匙開動那些修復的伐木機，用它把澈水開腸剖肚!不管你用哪種方法，他都非死不可!', '殺死澈水艦長，然後向風險海灣的卡茲嘉將軍報告。', '', '去找灰熊丘陵的卡茲嘉將軍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12316 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12316, 'zhTW', '死守海灣!', '我們不能讓部落控制風險海灣。這個港口對於我們在灰白之丘以及其他地方的行動來說是不可或缺的。$B$B斯托曼上尉已經帶領剩餘的西部荒野民兵團往東搜尋穿越山脈的道路，所以我們沒有後援軍力了。$B$B去戰場上，$n，然後殺死部落派來的征服堡狂戰士。殺到他們一個不剩。聯盟必須得到這個港口!', '擊敗10個部落成員或玩家，然後向風險海灣的斯圖亞特中尉回報。', '', '去找灰熊丘陵的斯圖亞特中尉。', '探險灣的部落成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12317, 'zhTW', '死守海灣', '這該死的西部荒野民兵團是個比我們預期中更強悍的對手。雖然他們人數很少，卻驍勇善戰，但我們沒有時間慢慢耗了。$B$B征服者克蓮娜的命令是盡快佔領港口。你必須打破這僵局，$n。找出敵人的海軍士兵然後殺到他們停止抵抗為止。這樣我們才能夠握有港口的控制權。$B$B動作快點，我不想讓征服者克蓮娜等太久。', '擊敗10個聯盟成員或玩家，然後向風險海灣的百夫長卡格朗姆回報。', '', '去找灰熊丘陵的百夫長卡格朗姆。', '探險灣的聯盟成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12319, 'zhTW', '書中的秘密', '這會是什麼，$n?那巫妖施展在你身上的想必不是一般的詛咒!$B$B<德肯翻過書上可怕的書頁。>$B$B我甚至搞不清楚我是不是把書拿反了。我們得找出這書裡隱藏的情報!$B$B<德肯把書交還給你。>$B$B高階指揮官應該會知道要怎麼做。帶著這鑲肉骨書去找他然後告訴他這裡發生的事情。', '把鑲肉骨書帶去給高階指揮官海弗德‧龍禍，他就在龍骨荒野的溫特加德要塞中。', '', '去找龍骨荒野的高階指揮官海弗德·龍禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12320 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12320, 'zhTW', '了解死者的語言', '帶著書，然後沿著往軍營的路前進。進了軍營之後下樓梯進入地牢。你會在監獄中找到審判官哈拉德和我們的鎮長，高佛雷。我相信高佛雷也許就是拼圖的最後一塊，而哈拉德能夠幫我們拼湊出真相。$B$B去吧!', '把鑲肉骨書帶給溫特加德要塞地牢的審判官哈拉德。', '', '去找龍骨荒野的審判官哈拉德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12321, 'zhTW', '諄諄善誘', '高佛雷‧古達，曾經是正直的溫特加德鎮長，如今成為了天譴軍的密探。他慢慢的、一點一點的從人類變成了不死的食屍鬼。如今，他只聽從巫妖王的命令，並且只為了侍奉他的主人而活。$B$B但是和所有的天譴軍一樣，高佛雷通曉死者的語言，並且只要適當的刺激他，他會告訴我們關於這本書所需要的資訊。$B$B一旦你聽見你想聽的，回報給前線的高階指揮官。有需要的話，我會把這裡清乾淨的。', '等待審判官哈拉德的大義凜然的宣教結束，將你揭露的消息回報給高階指揮官海弗德‧龍禍，他就在溫特加德要塞中。', '已聆聽正義佈道', '去找龍骨荒野的高階指揮官海弗德·龍禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12323, 'zhTW', '把他們燻出來', '還有許多膽小的風險投資公司員工躲在風險海灣中央的建築物裡。我必須把手頭上每個人都派去跟部落作戰，但我們也不能允許那些風險投資公司的離群者繼續在那些建築物裡紮營。$B$B也許我們能「說服」他們向他們的船隻移動。帶上這個煙霧彈，然後用它來把那些離群者從他們的農舍、鋸木廠或獸欄裡面燻出來。記得不要太靠近，他們可能會咬人的。', '使用煙霧彈來把20個風險投資公司離群者從建築物驅逐出去，然後向士官當尼報告。', '', '去找灰熊丘陵的士官當尼。', '探險公司的落隊者已被煙燻逼出', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12324, 'zhTW', '把他們燻出來', '這個港不止有大批流著鼻涕的聯盟懦夫出沒，更糟糕的是，還有許多風險投資公司的員工躲在那些建築裡面。他們不值得我們浪費時間去殺，而且反正我手邊也沒有多餘的戰士可用。$B$B也許我們可以「說服」他們向他們的船隻移動。帶著這個煙霧彈，然後用它把那些離群者從農舍、鋸木場或獸欄裡燻出來。記得不要太靠近;天知道他們身上染有什麼疾病。', '用煙霧彈把20個風險投資公司離群者從建築物驅逐出去，然後向石衛士狂暴圖騰報告。', '', '去找灰熊丘陵的石衛士狂暴圖騰。', '探險公司的落隊者已被煙燻逼出', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12326, 'zhTW', '蒸氣坦克突襲', '這是個偵搜摧毀任務。你要負責駕駛一輛坦克到腐屍農地上消滅天譴軍團的瘟疫戰車。車上配有3個第七軍團士兵。如果想要讓任務成功，一個人都不能少!$B$B你必須要靠近一輛瘟疫戰車來放下工程師。讓他們做好工作，然後再向下一台移動。當農場上的瘟疫戰車都清除了之後，朝要塞廢墟前方的墓塚移動，然後把剩下的組員放下車。和安柏‧凱許在裡頭碰面。', '駕駛聯盟蒸汽坦克去摧毀6架瘟疫戰車，然後把第七軍團精英送到溫特加德墓塚。成功了之後，就與安柏‧凱許交談，他就在龍骨荒野的溫特加德墓塚。', '', '', '瘟疫馬車已破壞', '第七軍團精英安全送達', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12327, 'zhTW', '出竅體驗', '啊，你尋求的是過去的景象。你是個睿智的$r。$B$B每次有人來算命的時候，他們總是問我關於未來的問題。當你到了我這年紀，你就會發現探知過去通常更有用。$B$B窺看我的水晶球吧。讓我們看看我們能得知些什麼。', '在魯巫娜的水晶球旁飲用輕靈藥水，觀看過去的幻象。', '來自過去的異象', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12328, 'zhTW', '魯巫娜的要求', '我不會要你付錢來換取我的服務，因為我可以預見你的行動是必要的，而且今天你獲知的事情將會成為一切的關鍵。$B$B然而，我要你為我收集一種藥劑。從東北方的食蕨巨蛾身上收集輕靈粉末。替我做完這件事之後我就會替你準備一種藥水，帶你去你想目睹的事件所在的時空。', '『瞎子』魯巫娜要你取得4把輕靈粉末。', '', '去找灰熊丘陵的『瞎子』魯巫娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12330 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12330, 'zhTW', '逼安那托利開口', '我妹妹就在這裡某處，但是這混帳死也不肯說。$B$B他看起來不太在意自己的死活，但是我有主意。我認識安那托利的老婆，塔迦納，打從魔狼教來這之前就認識她了 - 她是個養馬的。$B$B拿著這枝鎮定飛鏢，活逮住她，我們需要她當作對付安那托利的籌碼。$B$B一旦救出我妹妹，我會幫你把躲在這一切之後的黑手揪出來。', '白松貿易站的莎夏需要你拿著鎮定飛鏢，對著季至村的塔迦納使用。把塔迦納帶回白松貿易站。', '塔佳娜已送達', '去找灰熊丘陵的莎夏。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12331 AND `locale` = 'zhTW';
