INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12372, 'zhTW', '死守龍眠神殿', '藍龍軍團竟敢靠著過量流入蒼藍龍殿的法力壯膽，進而攻打龍眠神殿!$B$B我請求你騎上我們的防衛者加入戰局，並且殺死他們的巨龍與飛龍大軍，同時攻擊龍殿中湧出的地脈法力能量，破壞它的穩定。$B$B出門東西兩邊的區域有許多龍眠防衛者，和其中一頭衛士交談，騎上牠加入戰局。$B$B沒有你的幫助，$n，我們必敗無疑。', '龍眠神殿的戴伏斯塔茲要求你騎乘龍眠防衛者，殺死3隻蒼藍巨龍、5隻蒼藍飛龍，並且擾亂蒼藍龍殿。', '', '去找龍骨荒野的戴伏斯塔茲領主。', '', '', '使蔚藍龍神殿失去穩定', '', 0);
