INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12412, 'zhTW', '敵人之友', '我猜你跟我想的都是同一件事:聯盟將會在灰白之丘被擊潰。$B$B這裡有太多木材、礦石、獵物以及戰略要衝，我們不可能放棄這裡的戰線。$B$B到目前為止，我們的計畫都很成功...但是，有件事，會給敵軍關鍵性的幫助。$B$B遙遠的東邊，林邊崗哨中，當地的陷捕者尋求加入聯盟的陣營。在他們有任何機會加入之前，殺光他們。', '征服堡的征服者克蓮娜需要你去殺死8名銀溪獵人，以及他們的首領，弗拉戴克。他們就在林邊崗哨中。', '', '去找灰熊丘陵的征服者克蓮娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12413 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12413, 'zhTW', '銀溪之戰', '數小時之前，那些陷捕者充其量不過就是些農夫，被逼著加入聯盟的部隊。$B$B現在他們變成了別的東西...一個不確定因素。我討厭不確定。前去灰白之丘的北方，他們村子銀溪鎮外頭的丘陵，協助我們的人手擊潰這些陷捕者。', '征服堡的征服者克蓮娜需要你殺死8名銀溪防衛者，你可以在銀溪丘上找到他們。', '', '去找灰熊丘陵的征服者克蓮娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12414 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12414, 'zhTW', '準備馬匹', '上尉斯托曼把我們的騎四…七士…，阿反正就是騎馬的，統統派去風險海灣打仗了。$B$B會在這裡紮營的原因呢，就是為了東北邊巨礫之丘到這附近滿滿都是跑來跑去的高地野馬。上尉叫我負責把他們抓起來。$B$B你肯幫忙嗎？我有棍子，我有線，營地附近還長滿了野生胡蘿蔔。拔幾根胡蘿蔔，拿棍子一起使用，引誘這些野馬，然後把他們騎回這。', '將5匹高地野馬騎回侍從派西身邊，他就在西部荒野民兵團駐營中。', '', '去找灰熊丘陵的侍從派西。', '高地野馬已歸還', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12415 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12415, 'zhTW', '嚇唬馬匹', '聯盟的「西部荒野民兵團」就駐紮在遙遠的北邊，鐸爾莫丹的附近。他們愚蠢到分散兵力挑戰我們對風險海灣的控制權，而且他們缺乏騎兵的情形下出發。$B$B他們目前正試著捕捉並馴服那些在西部荒野民兵團駐營以及巨礫之丘附近閒晃的高地野馬。我們一定要在他們補充他們的坐騎以前阻止他們。拿著這個東西，然後丟在馬匹的附近好讓牠們跑走。', '驚嚇15匹高地野馬，並回報給索羅克‧風暴之怒，他就在歐尼克瓦營地。', '', '去找灰熊丘陵的索羅克‧風暴之怒。', '高地野馬已被驚嚇', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12416 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12416, 'zhTW', '戰火升溫', '龍殿被天譴軍破壞殆盡，而龍殿的守護者，妲莉雅‧日觸，下落不明。在神殿中殞命的紅龍，如今成了扭曲的骸骨餘燼龍，將我們團團圍住，情勢危急，$r。$B$B伊斯肯達隊長帶領了一群汝等族類的小隊，在龍殿之外截斷天譴軍團的攻勢。$B$B前去幫助他...但請待在他的小隊後方。天譴軍團的攻勢源源不絕，我可不希望在那些滿是創痕的山谷中失去你。', '幫助伊斯肯達隊長守護山谷，擊敗12隻嚴寒食屍鬼攻擊者、8隻嚴寒魂屍攻擊者，以及1隻嚴寒憎惡體攻擊者。事成以後，向賽利斯塔茲回報。', '', '去找龍骨荒野的賽利斯塔茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12417 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12417, 'zhTW', '回歸大地', '我還有另外一項需要注意的任務。我的兄弟不時在戰鬥中殞歿，如果我們不快點行動，他們只會助長餘燼龍的事例。$B$B從北方或南方的通道進入龍殿...這兩處的天譴軍應該比較薄弱。$B$B尋找從樹上掉落的晶紅橡實，並且將之種在我殞落的兄弟身旁。藉此，他們能夠帶來新生...這是吾族皆為之驕傲的命運。', '從北方或南方的通道進入晶紅龍殿，尋找晶紅橡實。對戰死的紅龍使用晶紅橡實，使他們的軀體回歸大地。任務完成以後，向賽利斯塔茲回報。', '', '去找龍骨荒野的賽利斯塔茲。', '紅寶石守護者已回歸大地', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12418, 'zhTW', '走過燃燒之境', '我還有最後一個任務要交給你，$r...一個應該能夠扭轉戰況的任務。$B$B回到神殿去，殺掉那些供給突襲軍能量的死靈法師群。只要他們死了，我們應該就可以擊退這些軍隊，並重新奪回神殿。$B$B我還需要你去找到神殿底下的腐化來源並摧毀它。$B$B我知道我的要求很多，不過如果你願意為我去做這件事的話，我們就可以贏得這場戰鬥。', '從南方或北方的通道進入晶紅龍殿，並殺死6名嚴寒死靈法師，同時消滅神殿下方腐化的源頭。任務完成以後，向賽利斯塔茲回報。', '', '去找龍骨荒野的賽利斯塔茲。', '', '紅寶石腐化已淨化', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12419 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12419, 'zhTW', '晶紅龍殿的命運', '當你拾起胸針的時候，它的微弱光芒稍微變亮了點。$B$B卡薩斯一定會想知道妲莉雅的死亡。把胸針帶去龍眠神殿給他。', '將妲莉雅‧日觸的紅寶石胸針交給卡薩斯，並且通知他妲莉雅之死。卡薩斯就在龍眠神殿的統治會議室中。', '', '去找龍骨荒野的卡薩斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12420 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12420, 'zhTW', '每月啤酒俱樂部', '會員享有優惠。成為「每月啤酒俱樂部」的會員，表示你有管道獲得到最新、最青的啤酒。$B$B帶著你的「每月啤酒」俱樂部會員表格給拉金·雷酒，他就在鐵爐堡的石火旅店中。', '把「每月啤酒」俱樂部會員表格帶給拉金·雷酒，他就在鐵爐堡的石火旅店中。', '', '去找丹莫羅的拉金‧雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12421, 'zhTW', '每月啤酒俱樂部', '', '帶著「每月啤酒」俱樂部會員表格交給奧格瑪裡的雷瑪。', '', '去找奧格瑪的雷瑪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12422, 'zhTW', '戰術性赦免', '聽著，$n。我要你謹慎而迅速的行動。$B$B克蓮娜的一個高階士官在銀溪鎮外面抓到了一位被流放的陷捕者。如果按照他們一貫的行事作風，在今天傍晚以前囚犯就會被處決掉。$B$B我們不能讓這件事發生。你知道的，這囚犯的特徵與米克哈爾在日誌中描述的大女兒符合。$B$B如果我們放走她，然後跟蹤她，她將會帶領我們找到控制著陷捕者的人。把這封信帶去給她。', '把赦免信交給銀溪丘上被俘虜的陷捕者。', '', '去找灰熊丘陵的被俘虜的陷捕者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12423, 'zhTW', '米克哈爾的日誌', '從你收集到的資訊看來，這本日誌是由一名叫做米克哈爾的銀溪鎮居民所寫的。$B$B這是由某種變體的人類通用語所寫成的。也許你該把它帶回去給征服者克蓮娜。', '把米克哈爾的日誌帶去給征服堡的征服者克蓮娜。', '', '去找灰熊丘陵的征服者克蓮娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12424, 'zhTW', '高耿娜', '這本書是用人類的豬言狗語寫的。這得立刻燒掉$B$B把它交給我的姊妹高耿娜，別浪費我的時間。', '把米克哈爾的日誌交給征服堡的高耿娜。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12426 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12426, 'zhTW', 'DEPRECATED', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12427, 'zhTW', '征服之淵:熊摔角!', '所以說你對戰鬥有興趣，啊?好吧，克蓮娜已經禁止了所有入伍的士兵參加鬥技場戰。不過你呢，我的朋友，技術上來說是一個自由的戰鬥員，所以不算在禁令裡面。$B$B很棒的漏洞，嗯?$B$B總而言之，如果你有興趣的話，我可以先讓你從某隻沒價值的爛熊開始出道。我甚至可以讓你帶朋友下場!', '在征服者之淵中擊敗鐵皮，然後找布齊‧維爾占談話取得你的獎賞。', '已擊敗鐵皮', '去找灰熊丘陵的布齊‧維爾占。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12428, 'zhTW', '征服之淵:瘋熊怪之戰', '你還不賴。真的不賴。$B$B你覺得你可以打得過熊怪嗎?那來隻特大號北裂境熊怪怎麼樣?$B$B很好很好。帶上你的隊友，去場子裡吧。讓我們給這些傢伙一場精采表演...也許我們這趟可以賺更多的銅板。', '在征服之淵中擊敗托格‧雷電圖騰，然後找布齊‧維爾占談話取得你的獎賞。', '已擊敗托爾格·雷霆圖騰', '去找灰熊丘陵的布齊‧維爾占。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12429, 'zhTW', '征服之淵:鐵與血', '在這種地方能找到個真正的鬥士真好...我們過去幾週來都只有一些囚犯和關在籠子裡的野獸。人們都覺得無聊了，你懂吧?$B$B總之，你的下一個挑戰是從鐸爾莫丹偷出來的一座純正鐵魔像...你覺得你能擊倒它嗎?', '在征服者之淵中擊敗鏽血，然後找布齊‧維爾占談話取得你的獎賞。', '已擊敗鏽血', '去找灰熊丘陵的布齊‧維爾占。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12430 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12430, 'zhTW', '征服之淵:致死方休', '我就跟你直說了，小子。下個參賽者是個謀殺犯。$B$B真的就是謀殺犯。$B$B他本來上週就要被處刑了，但他只用左手就絞死了劊子手，所以克蓮娜的守衛把他轉交給我。$B$B你可以跳過這個傢伙，我不會怪你的。', '在征服之淵中擊敗霍葛倫‧地獄斬，然後找布齊‧維爾占談話取得你的獎賞。', '已擊敗霍格倫·地獄裂', '去找灰熊丘陵的布齊‧維爾占。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12431, 'zhTW', '征服之淵:攤牌時刻', '你一定讓克蓮娜覺得很煩心。她和高耿娜互罵了一陣，現在她要你立刻到征服之淵裡報到。$B$B有謠言說那是場致死方休的戰鬥!這對你來說是個壞消息，不過對我們的生意來說是個天大的好消息!$B$B不管怎麼說，你都不可能逃過命運...最好快點進去了結這件事。', '在征服之淵中擊敗克蓮娜。', '', '去找灰熊丘陵的高耿娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12432 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12432, 'zhTW', '乘著紅色火箭', '嘿，$r!給我把你那身懶骨頭滾來這裡!$B$B聯盟有艘運木船就在東北方。既然我們得不到他們的木材，那我們只有一件事好做 - 毀掉木材!$B$B港口尾端的哥布林有幾枚魚雷已經蓄勢待發，他也有燃料，全都在北邊那艘停著的哥布林船隻上面。$B$B取得一些燃料，控制一枚魚雷，駕駛它攻擊船艦。$B$B稍息後解散，稍息!', '風險海灣燈塔中的戈洛科將軍要你摧毀聯盟的運木船隻。戈洛科將軍只有當部落勢力拿下燈塔之後才會出現在該處。', '', '去找灰熊丘陵的戈洛科將軍。', '聯盟木材貨運已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12433 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12433, 'zhTW', '尋找溶劑', '呃啊!又來了，又一塊墊圈報銷了...$B$B每次只要這種事發生，潤滑劑就會在所有的零件上流淌得到處都是。要是沒有溶劑，光是清理就要花上好幾個小時。$B$B你知道嗎，$r，在碼頭上風險投資公司的接駁船中，有種很棒的火箭燃油 - 他們好像叫它元素115吧。那種油可以作成絕佳的溶劑。$B$B拿一罐來，我可以提供麻煩你的獎勵。', '風險海灣中，部落基地的葛特需要你帶一罐元素115給他。', '', '去找灰熊丘陵的葛特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12434 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12434, 'zhTW', '繼續尋找溶解劑', '', '', '', '去找灰白之丘的古圖爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12436 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12436, 'zhTW', '額外收入', '你好，$c。你會發現在這征服堡，我們買賣克蓮娜要我們買賣的東西...而且是以克蓮娜要我們買賣的價格。$B$B這都是些令人發悶的生意。我想賺一點錢，同時餵飽咱們的蠻兵。你何不去獵捕一些雄鹿，然後拿些鹿肉來給我?$B$B這附近有無數的鹿，所以我只要你拿最好的肉來。', '征服堡的補給官羅克芮要你從附近的高角成鹿身上取來5塊多汁鹿肉。', '', '去找灰熊丘陵的補給官羅克芮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12437 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12437, 'zhTW', '乘著紅色火箭', '$n，聽好了。這場戰爭不僅爭奪戰略上的優勢，同時還有資源上的領先。$B$B我有一個任務可以扭轉目前面對此處部落的劣勢。$B$B港口尾端有幾枚魚雷，我們可以利用它擊沉西北邊部落的運木船。$B$B你必須從北邊哥布林停泊的船上取得一些燃料，再將魚雷射向他們的運輸艦!', '風險海灣燈塔的指揮官豪瑟需要你摧毀部落的運木船隻。指揮官豪瑟只有當聯盟勢力拿下燈塔之後才會出現。', '', '去找灰熊丘陵的指揮官豪瑟。', '部落運木船已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12438 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12438, 'zhTW', '懸賞:克羅格·毀誓者', '公告者:伊魯希亞·盧恩$B$B克羅格·毀誓者，天譴軍的血肉巨人，必須為我的丈夫、小孩、與我的摯友語幕一家的死負責。具有足夠勇氣獵取這份獎金的人可以在東南方腐屍農地邊緣的懸崖找到克羅格。$B$B我要正義!殺死克羅格·毀誓者!$B$B假使有人殺掉了克羅格·毀誓者，我已經預先將金錢與物品交給了大領主李奧瑞克·馮·澤爾迪格，請他代發。$B$B請為我們復仇!', '殺死克羅格·毀誓者，然後向大領主李奧瑞克·馮·澤爾迪格領取賞金，他就在龍骨荒野的溫特加德要塞。', '', '去找龍骨荒野的李奧瑞克·馮·澤爾迪格公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12441, 'zhTW', '懸賞:高階薩滿血掌', '公佈者:德羅菲$B$B就在異法陵地之上，我的表親史克羅堤和布羅特，遭到一幫邪惡的血掌獾狼怪襲擊。我們雖然企圖脫逃，但史克羅堤和布羅特恐怕已遭不測。$B$B我要懲罰這些傢伙!是否有勇者願意冒險前往東南方，也就是龍骨荒野的邊境，異法陵地上格殺高階薩滿血掌以及他的親信?$B$B本人將提供豐渥的賞銀交付給大領主李奧瑞克·馮·澤爾迪格，由他發放給任何完成此任務者!', '殺掉高階薩滿血掌，並回報給大領主李奧瑞克·馮·澤爾迪格以獲取你的獎賞;他就在龍骨荒野上的溫特加德要塞裡。', '', '去找龍骨荒野的李奧瑞克·馮·澤爾迪格公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12442, 'zhTW', '懸賞:突襲軍指揮官艾尤圖斯', '公告者:大領主李奧瑞克·馮·澤爾迪格$B$B第七軍團的部隊在溫特加德東北方的小徑上遭到突襲軍指揮官艾尤圖斯與一群沒大腦的血色突襲軍狂徒襲擊。面對此等冷血狡詐的行為必須以以暴制暴!$B$B溫特加德要求正義!到東北方的突襲營地找出突襲軍指揮官艾尤圖斯，終結他可悲的生命。$B$B我會獎賞任何接受這任務的勇者!', '殺掉突襲軍指揮官艾尤圖斯，並回報給大領主李奧瑞克·馮·澤爾迪格以獲取你的獎賞;他就在龍骨荒野上的溫特加德要塞裡。', '', '去找龍骨荒野的李奧瑞克·馮·澤爾迪格公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12443, 'zhTW', '尋找溶劑', '呃啊!又來了，又一塊墊圈報銷了...$B$B每次只要這種事發生，潤滑劑就會在所有的零件上流淌得到處都是。要是沒有溶劑，光是清理就要花上好幾個小時。$B$B你知道嗎，$r，在碼頭上風險投資公司的接駁船中，有種很棒的火箭燃油 - 他們好像叫它元素115吧。那種油可以作成絕佳的溶劑。$B$B拿一罐來，我可以提供麻煩你的獎勵。', '風險海灣中，聯盟基地的巴爾玻芬克需要你帶一罐元素115給他。', '', '去找灰熊丘陵的巴爾玻芬克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12444 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12444, 'zhTW', '黑河前哨戰', '風險投資公司正在離開灰白之丘的路上。他們以前把這裡當作是轉運木材的地點，但是狀況對他們來說變得過於危險。$B$B他們棄置的營地如今炙手可熱，而且我們非常清楚不能讓部落染指這個地方。$B$B黑河伐木營地是本區三個伐木地中最小的，但是我們仍然需要它。完成你分內的工作，防衛部落大軍，任何他們奪走的木材都將會被製成武器，在別處用來對付我們。', '斥候隊長卡特需要你去黑河伐木營地殺死10名部落成員或玩家。', '', '去找灰熊丘陵的斥候隊長卡特。', '黑河的部落成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12446 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12446, 'zhTW', '繼續尋找溶解劑', '', '', '', '去灰白之丘找風險灣的巴布芬克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12448 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12448, 'zhTW', '戰火升溫', '龍殿被天譴軍破壞殆盡，而龍殿的守護者，妲莉雅‧日觸，下落不明。在神殿中殞命的紅龍，如今成了扭曲的骸骨餘燼龍，將我們團團圍住，情勢危急，$r。$B$B德拉森隊長帶領了一群汝等族類的小隊，在龍殿截斷天譴軍的攻勢。$B$B幫助他...但請待在他的小隊後方。天譴軍的攻勢源源不絕，我可不希望在那些滿是創痕的山谷中失去你。', '幫助德拉森隊長守護山谷，擊敗12隻嚴寒食屍鬼攻擊者、8隻嚴寒魂屍攻擊者，以及1隻嚴寒憎惡體攻擊者。事成以後，向凡加斯塔茲回報。', '', '去找龍骨荒野的凡加斯塔茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12449 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12449, 'zhTW', '回歸大地', '我還有另外一項需要注意的任務。我的兄弟們在戰鬥中殞歿，如果我們不快點行動，他們將會助長餘燼龍的數量。$B$B從南方的通道進入龍殿...這處的天譴軍應該比較薄弱。$B$B尋找從樹上掉落的晶紅橡實，並且將之種在我殞落的兄弟身旁。藉此，他們能夠帶來新生...這是吾族皆為之驕傲的命運。', '從南方的通道進入晶紅龍殿，尋找晶紅橡實。對戰死的紅龍使用晶紅橡實，使他們的軀體回歸大地。任務完成以後，向凡加斯塔茲回報。', '', '去找龍骨荒野的凡加斯塔茲。', '紅寶石守護者已回歸大地', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12450 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12450, 'zhTW', '走過燃燒之境', '我有最後一項任務要交付給你，$r...一個可以扭轉戰局的任務。$B$B返回龍殿，殺掉發起這場突襲的死靈法師。只要他們一死，我們就能擊退這些軍隊，最後奪回龍殿。$B$B我同時需要你從龍殿底下找出腐化的源頭，並且消滅它。$B$B我曉得已經請求你替我們做了很多，但是只要你替我們完成這件事，我們將會獲得這場戰爭的勝利。', '從南方的通道進入晶紅龍殿，並殺死6名嚴寒死靈法師，同時消滅神殿下方腐化的源頭。任務完成以後，向凡加斯塔茲回報。', '', '去找龍骨荒野的凡加斯塔茲。', '', '紅寶石腐化已淨化', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12452 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12452, 'zhTW', '晶紅龍殿的命運', '把達莉亞的紅寶石胸針帶給賽里斯特拉茲，並告知他她的命運。', '將妲莉雅的紅寶石墜飾交給賽利斯塔茲，並將妲莉雅之死告訴他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12453 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12453, 'zhTW', '上空的窺伺', '他們要我提供協助對抗聯盟大軍。目前的情況，我軍與對方勢均力敵，而我們極力找尋優勢。$B$B在這附近翱翔於山巔林間的帝王雄鷹將會是我們極佳的斥候選擇。帶著這根銀色的羽毛，將我的目光與牠們連結在一起。$B$B只要能看到敵人的一舉一動，便能獲得我們所需的戰略優勢。你將會發現大量的雄鷹出沒在東方的山地中。', '風先知灰角要你在6隻灰白之丘的帝王雄鷹身上使用銀羽。', '', '去找灰熊丘陵的風先知灰角。', '帝王鷹之眼已被束縛', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12454 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12454, 'zhTW', '生命的循環', '伊瑟拉在翡翠夢境中沉睡著，同時監視著夢境與艾澤拉斯。然而，一場駭人的夢魘佔據了夢境，我擔心伊瑟拉現今已被這場夢魘所影響。$B$B近來，我請求她援助對抗天譴軍團的戰爭;天譴軍正在其他的龍殿中喚醒冰霜巨龍。但是她曲解了我的意思。$B$B取而代之的是，她告訴龍殿中的防衛者，將所有不是綠龍軍團的成員視為敵人。$B$B我需要你殺掉一些天爪，龍殿必須回歸它的平衡。', '翡翠龍殿的『花園看守者』尼夏拉請求你殺死5頭翡翠天爪。', '', '去找龍骨荒野的『花園看守者』尼夏拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12455 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12455, 'zhTW', '隨風而逝', '軍火空投失控了，朋友。鎮西要塞運來的彈藥被空中盤旋的冰霜巨龍給攔截了，飛行機具數秒內被撕成碎片，而貨物則隨風四散。大部分的貨物仍然在機艙上 - 只是遍佈腐屍農地裡。$B$B我要你回去那裡，將四散在那該死農地裡的軍品木箱子拿回來。$B$B快去!我們不可能在沒有槍枝和彈藥的情況下展開攻擊，$g老兄:大姐;!', '龍骨荒野，溫特加德墓塚中的安柏‧凱許需要你拿回8件溫特加德軍火。', '', '去找龍骨荒野的安柏·凱許。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12456 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12456, 'zhTW', '艾里史卓斯的長羽', '我能感覺到神殿尚未完全回歸平衡。青綠看守者已經被我們的舉動所觸怒，我感覺他聽不進我們任何理由。$B$B艾里史卓斯是一頭巨大的天爪，棲息在翡翠龍殿的南方，他同時控有整個龍殿的空中防禦，而恐怕我們得應付他的攻擊。$B$B拿著這些天爪蛻皮，並把蛻皮放在他視力所及的地面上，他會飛下來的。把他的長羽帶給我。', '翡翠龍殿的『花園看守者』尼夏拉要求你取得艾里史卓斯的長羽。', '', '去找龍骨荒野的『花園看守者』尼夏拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12457 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12457, 'zhTW', '鏈砲與你', '我們朝著東西兩向架起了鏈砲和路障，我方受傷的士兵們藏身在兩處房間內 - 盡所能的不去驚動無腦的食屍鬼。$B$B既然我們有了彈藥，我要你操縱其中一台鏈砲，並使用它為我們的士兵炸出一條路!只要你就位，從藏身處呼叫一名士兵，然後猛烈開火擊退靠近他的天譴軍!$B$B快出發吧!', '龍骨荒野，溫特加德墓塚中的安柏‧凱許要你援救8名受傷的第七軍團士兵。', '', '去找龍骨荒野的安柏·凱許。', '已救出受傷的第七軍團士兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12458 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12458, 'zhTW', '鞭笞者之種', '我們需要更多的武器來對抗天譴軍。東南方翡翠龍殿的自然產物也許就是這個問題的解答。$B$B任何的不死生物，除了受到希瓦娜斯救贖的被遺忘者外，只要踏進龍殿一步，立刻化為灰燼。$B$B我想要測試個理論，而我需要你作為我達成這項工作的手段，年輕的$r。前去翡翠龍殿，從殿內翡翠鞭笞者的身上拿走種子。', '龍眠神殿頂端的伊薩里奧斯領主要求你拿回3顆鞭笞者種子。', '', '去找龍骨荒野的伊薩里奧斯領主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12459 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12459, 'zhTW', '水能載舟亦能覆舟', '既然只有三顆種子，我們必須將它們用在最佳的可能用途上。$B$B你的目標就是盤旋在葛拉克朗安息地空中的再活化冰霜巨龍，腐屍農地東邊兵營廢墟中的『邪惡』特基德、以及在遙遠東北方的辛薩卡拉中的監督者死凝。$B$B如果這些種子能徹底毀滅低等的天譴軍，那麼同樣能將大幅的削弱他們三個。事實上，這樣就足夠你自己料理他們了。', '龍眠神殿頂端的伊薩里奧斯領主要求你摧毀弱化的再活化冰霜巨龍、弱化的『邪惡』特基德、以及弱化的監督者死凝。', '', '去找龍骨荒野的伊薩里奧斯領主。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12460 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12460, 'zhTW', '到晶紅龍殿報到', '我們在晶紅龍殿需要你。龍群已經被藍龍和天譴軍團四面包圍了…他們一點也不比我們好過。情況似乎非常危急，但這也給了我們一個結交珍貴盟友的好機會。我派出了一個兵團來幫助紅龍對抗晶紅龍殿的天譴軍團，如果你願意作戰的話，請前往龍殿東方的山脊上找賽利斯塔茲，然後盡你所能的提供協助。', '向晶紅龍殿東邊山脊上的賽利斯塔茲報到，就在龍眠神殿的西方。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12462 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12462, 'zhTW', '搞定這件事', '通往地獄的大門就在台階下面:視線可及之處充滿了天譴軍，而且每分每秒都在增加。我們所能收集到的微薄情報指出兩個天譴軍的死靈領主正在瘋狂的清空下面的兩個墓穴。在我們侵入賽爾贊的內室之前，我們得處理掉這兩個小丑，和他們從納克薩瑪斯帶來的好朋友。$B$B進入墓塚中，解決死靈領主、納克薩瑪斯恐怖衛士和納克薩瑪斯之影。', '龍骨荒野，溫特加德墓塚的『災禍』約德‧冰鬚要你殺死死靈領主薩維斯，死靈領主赫魯斯，和15個納克薩瑪斯天譴部隊。', '', '去找龍骨荒野的『災禍』約德·冰鬚。', '', '', '納克薩瑪斯的天災已擊殺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12464 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12464, 'zhTW', '我的宿敵', '我的宿敵，大將軍阿比迪斯，也來到了北裂境。$B$B不知她怎麼辦到的，撐過了對提爾之手的攻擊，帶了一支小部隊來到北方。他們在南邊建立了新壁爐谷。$B$B雖然他們在對抗天譴軍團方面可能會很有用，但阿比迪斯本人卻是個太過精明的對手，不能放著她不管。相信我，如果我們放過他們，她會在塵埃落定之前拿劍抵著我們的喉嚨。$B$B因此，我們要除掉他們的領袖，再做我們自己的工作。提著她的頭來見我。', '把大將軍的頭顱帶去給溫特加德要塞的指揮官艾利格‧黎明使者。', '', '去找龍骨荒野的指揮官艾利格·攜晨者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12465 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12465, 'zhTW', '掠鬚的日誌', '不管掠鬚的日記剩下的頁面寫了些什麼，都得把它找回來。到地道另一端的房間裡找出襲擊掠鬚的人。一定是他們把掠鬚的日誌撕碎了!$B$B當你找到遺失的頁份之後，回去找溫特加德墓塚入口處的安柏‧凱許。', '回收掠鬚日誌的第四頁、掠鬚日誌的第五頁、掠鬚日誌的第六頁、以及掠鬚日誌的第七頁;然後向安柏‧凱許回報，他就在龍骨荒野的溫特加德墓塚。', '', '去找龍骨荒野的安柏·凱許。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12467 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12467, 'zhTW', '追擊冰颶:賽爾贊的骨匣', '你的冰霜巨龍就在那裡。$B$B<泰拉里恩指向西方。>$B$B她可真是個大傢伙!$B$B如果你做好了戰鬥準備，就和『巨龍引誘者』說。他會『接她過來』。一旦冰颶夠靠近了，我們會把她鍊在地上然後解決她!希望有了你的協助，我們可以幹掉她，並且替你取得那個骨匣。$B$B一旦你拿到了骨匣，返回溫特加德要塞向高階指揮官海弗德‧龍禍報告。他正在籌劃與賽爾贊的最後決戰。', '從冰颶身上取得賽爾贊的骨匣，然後將它交給溫特加德要塞的高階指揮官海弗德‧龍禍。', '', '去找龍骨荒野的高階指揮官海弗德·龍禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12469 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12469, 'zhTW', '返還派遣者', '仔細檢查之後，你發現這個哥布林似乎是被派出來運送一個裝滿炸藥的包包通過荒野。附近半埋在雪中的鷹身人羽毛說明了他是怎麼遇害的。$B$B看起來，哥布林似乎是要將炸藥從東邊某處送往憤怒之門。看來沿著山脊向東走回去通知派遣者是最謹慎的作法。', '沿著山脊往東走，把炸藥包送回去給鏽鼻崗哨的辛克，在龍骨荒野的北方。', '', '去找龍骨荒野的辛克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12470 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12470, 'zhTW', '恆龍的秘密', '東北方青銅龍殿中的時空風暴阻止了不朽生物的進入。$B$B恆龍軍團與龍殿中的守護者進行著控制權爭奪，我們一定要趁機獲取情報。$B$B你只是個凡人，你可以進入龍殿中使用永恆沙漏。保護沙漏，直到恆龍軍團的領導人現身。$B$B提醒你，恆龍軍團會盡可能阻止你的!', '龍眠神殿頂端的克羅米拜託你前往青銅龍殿。一旦進入殿中，將永恆沙漏放置地上。持續保護沙漏，並將你所收集到的情報回覆給她。', '永恆沙漏已受保護', '去找龍骨荒野的克羅米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12472 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12472, 'zhTW', '結局', '歸功於你的英勇行徑，弗塔根領主下令全面進攻賽爾贊。第七軍團攻入了地穴中的召喚大廳，發現了一個看起來像是通往地獄的大門。萬事具備就只差你了。$B$B帶著骨匣，向溫特加德墓塚內的軍團指揮官約立克回報。$B$B天譴軍在要塞外頭挖了一條地道，你可以利用它迅速地找到約立克。快去吧，$n!帶領我們迎向勝利!', '將賽爾贊的骨匣帶給軍團指揮官約立克，他就在龍骨荒野上的溫特加德墓塚中。', '', '去找龍骨荒野的軍團指揮官約立克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12473 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12473, 'zhTW', '開頭與尾聲', '每一則好的故事都有開頭跟尾聲，$n。雖然你的故事離結局還有段距離，但我敢打賭，如果它還沒成為一個傳說的話，我就受天打雷劈!當這一切都結束，不論我們發生了什麼事情，你在溫特加德的所作所為，將會成為家喻戶曉的故事流傳多年。$B$B現在，盟友，當你準備好以後，我會使用骨匣把賽爾贊騙出來。$B$B要是我們成功了，向溫特加德要塞的高階指揮官海弗德‧龍禍回報我們勝利的消息。', '擊敗『幽暮使者』賽爾贊並向高階指揮官海弗德‧龍禍回報，他就在龍骨荒野的溫特加德要塞中。', '已擊敗黃昏使者瑟爾贊', '去找龍骨荒野的高階指揮官海弗德·龍禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12475 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12475, 'zhTW', '人們藏匿的秘密', '當背叛發生在遺民之濱，阿薩斯王子 - 同行的還有穆拉丁 - 開始了他追尋霜之哀傷的任務。發現霜之哀傷的洞窟有可能就在附近嗎?這之中還有什麼秘密呢?雖然法球沒有回答這個問題，但是它向我顯現了其他事情。$B$B溫特加德要塞的東北方，是一座血色突襲軍的哨站。哨站中的某處有一張地圖。法球告訴我這張地圖能為我們提供很大的忙。$B$B把它帶來!', '『遠識』齊利格要你將突襲軍地圖帶回來給他，他就在龍骨荒野中溫特加德要塞裡面。', '', '去找龍骨荒野的『遠識』齊利格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12476 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12476, 'zhTW', '十字軍回歸?', '溫特加德要塞的東北方有一座剛蓋好的營地，由血色十字軍 - 或者說 - 他們如今稱呼自己血色突襲軍所建造的。雖然我們還沒辦法確認為什麼他們要來北裂境，他們肯定和以前一樣危險。就在昨晚，血色突襲軍殺害了我們12名的士兵，$n，我們一定要給他們一個教訓。$B$B前去突襲營地削弱他們。', '龍骨荒野，溫特加德要塞裡的最高指揮官萊諾爾‧風矛要你去突襲營地殺死20名血色突襲軍員。', '', '去找龍骨荒野的指揮官萊諾爾·風矛。', '血色十字軍已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12477 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12477, 'zhTW', '救贖之途', '「救贖之途」，你有聽說過嗎?傳說中那是一本寫有血色突襲軍大將軍阿比迪斯的預言書。你在書中可以找到血色狂熱分子的動機與目標 - 更別提一大堆的瘋言瘋語。$B$B前去溫特加德要塞東北方的突襲營地，從突襲軍員身上帶回來一份「救贖之途」。', '將「救贖之途」交給高階指揮官海弗德‧龍禍，他就在龍骨荒野的溫特加德要塞裡面。', '', '去找龍骨荒野的高階指揮官海弗德·龍禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12478 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12478, 'zhTW', '霜之哀傷洞窟', '他們已經標記出霜之哀傷洞窟的位置，我們不清楚為什麼血色突襲軍會對這裡感興趣，但光看就知道，洞窟附近的區域已經被重兵固守著。不過，我們還是要前進！ 帶著這顆占卜寶珠，往北離開小鎮，接著往西北前去血色哨點。一路往洞窟的底層殺去。到底之後，使用寶珠，將你發現的消息帶回來。', '在霜之哀傷洞窟底部使用齊利格的占卜寶珠，揭開過去的秘密！。', '', '去找龍骨荒野的『遠識』齊利格。', '過去的秘密已揭露', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12479, 'zhTW', '前往北裂境！', '歡迎來到巫妖王之怒朋友家庭測試版。利用我身旁的傳送門開始你前往北裂境的旅程。$B$B你可以選擇要傳送至北風凍原的驍勇要塞或是凜風峽灣的瓦爾加德。', '與北風凍原、驍勇要塞的聯盟招募員或是凜風峽灣、復仇臺地的聯盟招募員交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12480, 'zhTW', '前往北裂境！', ' 描述 歡迎來到巫妖王之怒朋友家庭測試版。利用我身旁的傳送門開始你前往北裂境的旅程。$B$B你可以選擇要傳送至北風凍原的戰歌堡或是凜風峽灣的復仇臺地。\\r\\n\\r\\n \\r\\n\\r\\n', '與北風凍原、戰歌堡的部落招募員或是凜風峽灣、復仇臺地的部落招募員交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12481, 'zhTW', '罵上加傷', '維酷人在這件事情上很精明，幸好我已經準備好了更多的花樣。$B$B他們的領袖，畢雍，是個暴躁的傢伙。我們已經把他們的語言拼湊成一段侮辱語，推測應該相當下流。內容大約是關於他母親跟一頭畜生...我們也不太確定。$B$B帶著這張紙，然後對他唸出來。等他開始追著你跑，就把他引回這裡。我們保證他無法活著走出去。', '對貝爾海姆的畢雍‧海格德森唸出維酷人的侮辱語，然後將他引回黎戴爾的埋伏處，幫忙殺了他。', '', '去找凜風峽灣的黎戴爾。', '已羞辱比約恩·哈爾古森', '已擊敗比約恩·哈爾古森', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12482, 'zhTW', '對付尼弗瓦', '我們在等候復仇臺地的援軍來對尼弗瓦發動攻擊。然而，如果我們能早一點佔領它，就能讓我們取得對聯盟的優勢。$B$B進入城鎮中，看你能否確認他們的數量。', '遊俠隊長艾瑞依爾要你去尼弗瓦殺死5個掠龍戰士、4個掠龍符文先知以及4隻掠龍巡狩獵犬。', '', '去找凜風峽灣的遊俠隊長艾瑞依爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12483, 'zhTW', '燉幻光菇', '嘿，你有空的時候，何不幫老皮格蒙做點事?我有個朋友會做一種超棒的燉菜 - 你絕對沒吃過這麼好吃的東西!$B$B他想要這附近出產的幾種食材。在西南邊的遺跡和北邊的營地就找的到了。$B$B怎麼樣，老兄?', '花崗岩之泉的皮格蒙要你去德拉克辛遺跡收集5個幻光雪菇和5個冰蛇之眼，以及從札布哈拉克收集5個甜根。', '', '去找灰熊丘陵的皮格蒙。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12484 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12484, 'zhTW', '天譴烤肉', '呃。$B$B綑綁那些不幸的食人妖讓我的心好痛，可是我的背更痛!$B$B幫老皮格蒙一把，把屍體拖到麥客那裡去。$B$B如果不把他們燒掉，要不了多久他們又會爬起來亂晃。', '花崗岩之泉的皮格蒙要你把一具乾縮食人妖屍體帶去給麥客‧菲爾森，然後放進火裡。', '', '去找灰熊丘陵的麥客‧菲爾森。', '木乃伊屍骸已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12485 AND `locale` = 'zhTW';
