INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12491, 'zhTW', '恐酒的恐酒', '寇仁·恐酒的屍體緊抓住這個小小的酒桶。這一定是他最惡名昭彰的恐酒!', '將恐酒的恐酒帶到鐵爐堡附近的啤酒節營地交給易菲克佛·鐵桶。', '', '去找丹莫羅的易菲克佛‧鐵桶。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12492 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12492, 'zhTW', '恐酒的恐酒', '寇仁·恐酒的屍體緊抓住這個小小的酒桶。這一定是他最惡名昭彰的恐酒!', '將恐酒的恐酒帶到奧格瑪附近的啤酒節營地交給泰伯·詐桶。', '', '去找杜洛塔的泰伯‧詐桶。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12494 AND `locale` = 'zhTW';
