INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12600, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12603, 'zhTW', '磨利你的爪子', '原始飛龍已經佔據了北方和東方大部分的區域，我甚至在這裡就可以感覺到他們吐息的熱度。在我們能挑戰最強的飛龍之前，我們最好先對付那些較弱的傢伙來測試我們的技巧。$B$B但別鬆懈你的警戒，那些野獸可以活生生地吞下一個人。等你更熟悉那些飛龍的戰術之後，再回來找我，我會告訴你下一步。', '殺死6隻原始飛龍然後和多里安前哨的多里安‧龍巡者交談。', '', '去找索拉查盆地的多里安‧龍巡者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12604, 'zhTW', '恭喜!', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12605 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12605, 'zhTW', '確保誘餌', '我們可不打算像個白癡一樣地揮舞著手臂來引起育母斯莉薇娜的注意，但如果我們夠聰明的話，就應該可以引誘她來和我們戰鬥。我們也能夠弄到更多，呃，我小小計畫的飼料。<多里安瞥了狹嘶一眼。>$B$B但現在還不需要擔心那些。只要去營地的東邊還有東北邊找一些原始飛龍蛋就好。去把那些蛋打破，挖出那些雛龍。等育母知道我們做了什麼之後，她就毫無選擇只能對付我們。', '把6隻原始雛龍帶給多里安前哨的多里安‧龍巡者。', '', '去找索拉查盆地的多里安‧龍巡者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12606, 'zhTW', '繭縛!', '現在隧道被封閉了，我們下一個該關心的就是落在敵人手中的夥伴。$B$B如果運氣好的話，我們有些士兵應該還在奈幽蟲繭裡活的好好的。$B$B趁還來得及的時候把他們放出來!', '魯伯特上尉要你打開德拉克索璀的奈幽之繭，解救3個俘虜步卒之後回去和他交談。', '', '去祖爾德拉克找達克索塔的魯伯特上尉。', '已釋放被俘的步兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12607, 'zhTW', '一個長毛象任務', '在你前去挑戰育母斯莉薇娜之前，多里安想到一個妙計推薦給你和赫米特，你們可以騎在長毛象的背上來協同作戰。$B$B營地的四周都是長毛象。只要把這個轡頭套在一隻碎牙長毛象的頭上就行。只要小心那些公象就是了。牠們可能完全無法忍受這些拘束。等你找到一隻適合的長毛象之後，把牠帶回這裡來。', '帶一隻碎牙長毛象給多里安前哨的狹嘶。', '', '去找索拉查盆地的狹嘶。', '碎牙長毛象已送達', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12609, 'zhTW', '補充貨架', '聽著，$c。我瞭解這樣可能有點要求太多了...$B$B新鮮的蜘蛛毒液很難找到，就算是蜘蛛在這裡大批出沒也一樣。但芬克斯坦說他至少需要一大缸，而且很快就要用到。$B$B我會叫我在外頭的部下收集這些藥材，但如果我們要及時完成鍊金師的命令，他們就需要援手。$B$B當你漫步在祖爾德拉克的原野上的時候，留意地門爬行者，然後把你找到的毒液全都拿來給我。', '希伯伐洛克的阿爾納斯上尉，要你從祖爾德拉克的地門爬行者身上，收集7份新鮮的蜘蛛毒液。', '', '去找祖爾德拉克的阿爾納斯上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12610 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12610, 'zhTW', '剪掉他們的翅膀', '自從芬克斯坦來了以後，我就被迫替他的實驗和製藥收集各種不同的材料。$B$B我會遵守誓言執行我的命令，但我是個經驗豐富的老兵。我曾經參與過數十場戰鬥。我寧可待在前線，對十字軍做出更直接的貢獻。$B$B幫幫我，$r。替我收集一些蝙蝠翅膀，好讓我能夠更快回去參與一些真正的行動。', '希伯伐洛克的阿爾納斯上尉，要你從祖爾德拉克蝙蝠身上，收集7個無瑕疵的蝙蝠翼。', '', '去找祖爾德拉克的阿爾納斯上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12611, 'zhTW', '七倍奉還', '巫妖王的部下愚蠢地踏入了至高無上的生命之力所統御的大地。他們所造成的傷害將會七倍奉還在他們身上。$B$B名叫薩爾葛倫‧荒疫使者的怪物必須直接為腐化這片土地負責;你可以在正北方找到他。帶著這個禦符，用它來把死亡的力量反射回他身上。讓天譴軍團見識生命的力量能夠戰勝一切。', '芙蕾雅的化身要你使用芙蕾雅之禦將薩爾葛倫‧荒疫使者的死亡箭七倍反彈回去以擊敗他。', '', '去找索拉查盆地的芙蕾雅的化身。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12613 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12613, 'zhTW', '甬道之門充能 - 造物者瞰臺', '我們不能在這時候停止，$r。你已經觸動了第一個開關，但還有一個。$B$B泰坦建造了第二個制高點來觀察他們的造物。你會在東邊找到它，在山脈的高處。$B$B拉下監控所內的啟動開關θ，甬道之門就會打開。', '芙蕾雅的化身要你前往休拉薩盆地東方的造物者瞰臺，然後使用啟動開關θ。', '', '去找索拉查盆地的芙蕾雅的化身。', '西塔啟動開關', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12614 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12614, 'zhTW', '產後憂鬱', '育母斯莉薇娜現在應該像是一整團咆哮的牙齒、尖刺和爪子。你偷走了她的孩子，沒有任何母親會和藹地面對這種事。$B$B雖然牠們是從蛋裡面孵出來的，但她對於那些幼獸的愛想必不遜於你母親對你的愛。$B$B她現在應該又絕望又狂暴，兩者都是赫米特喜歡獵物所處的狀態。你和他，還有那隻長毛象，應該能夠打的過她。$B$B她正在蠻荒灌木林北緣的棲所，渴望著復仇。', '殺死育母斯莉薇娜，然後向多里安前哨的多里安‧龍巡者回報。', '', '去找索拉查盆地的多里安‧龍巡者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12615 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12615, 'zhTW', '辛托加之祝福', '妖術師烏邦茍或許跟你提過向祖爾德拉克的諸神奉獻的事情。辛阿布瓦並不是唯一被德拉克瑞所遺忘的神祇。$B$B我們庇護於辛托加，繁榮之母的保護之下。就像辛阿布瓦一樣，如果你將德拉克瑞的祭品獻給她，她一定會將祝福賜予你。', '巫醫庫弗要你在辛托加的雕像前獻上10份德拉克瑞祭品。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12617 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12617, 'zhTW', '滅絕入侵者', '我是泰坦之女，芙蕾雅的具現存在之一。我就是生命守護者 -- 我留在這裡以保護這塊土地免受天譴軍團的威脅。$B$B但我從沒預料到巫妖王居然派出自願的活人僕從來執行他的計畫。$B$B我大可輕易地親手粉碎那些教徒，但我必須要全力對付那些不死大軍並且保護我盆地的剩餘部分。$B$B去吧，$n。將我的憤怒傳達給那些傲慢無禮的入侵者。', '雨頌者急湍的芙蕾雅化身要你前往西北邊的死亡之手駐營，並殺死8個教徒滲透者。', '', '去找索拉查盆地的芙蕾雅的化身。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12618 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12618, 'zhTW', '辛托加的祝福', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12619 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12619, 'zhTW', '紋飾符文刃', '對死亡騎士來說，最為重要的一件裝備就是符文刃。死亡騎士正是透過符文刃來支配冰霜、血魄與穢邪之力。符文刃同時也是死亡騎士用來蓄積符能的容器。$B$B現在，你該為自己打造第一柄符文刃了。搜索這層樓的武器架，然後找出一柄戰損之劍。一旦找到了，就把那柄劍拿去附近的符文熔爐，用它來製造一柄符文刃。', '搜索黯黑堡的武器架，找出一把戰損之劍，然後在符文熔爐使用它來鍛造一把符文刃劍。將符文刃劍交給黯黑堡的講師拉祖維斯。', '', '去找黑鴉堡壘的講師拉祖維斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12620 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12620, 'zhTW', '生命守護者之怒', '我們動作不夠快，$n。那些雜碎教徒已經抵達了微光之柱而且著手準備摧毀它，我可以感覺得到。$B$B我們沒多少時間了。在微光之柱頂端吹響這個號角，藉由水晶來引導我的力量。$B$B我們會讓那些雜碎知道少對泰坦的創造物胡搞。', '雨頌者急湍的芙蕾雅化身要你在微光之柱的頂端使用芙蕾雅的號角。', '', '去找索拉查盆地的芙蕾雅的化身。', '生命守衛者之怒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12621 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12621, 'zhTW', '芙蕾雅的契約', '教徒的問題已經處理了，但天譴軍的入侵卻沒有減緩。情況越來越危機了，$n。$B$B現在還剩下最後一個手段。但在我揭露更多之前，我必須要確認我能完全地相信你。', '聽芙蕾雅的化身要說什麼。', '', '去找索拉查盆地的芙蕾雅的化身。', '菲雅的契約', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12622, 'zhTW', '金阿萊的領袖', '你跟艾胡奈想到的是同一件事嗎，老兄?$B$B有一些德拉克瑞食人妖聚集在西南方的金阿萊之池。我們得引出他們的領袖，而艾胡奈剛好知道你該怎麼做!$B$B去那邊殺死那些食人妖。等你殺得夠多了，他們的領袖就會出現。$B$B等他們出現在圖騰旁邊的時候，老兄，你一定得要把庫吐貝沙，加瓦尼爾還有『瘋子』丘洛的寶藏都給弄到手。', '辛托加的割顱者艾胡奈要你拿到庫吐貝沙的寶藏，加瓦尼爾的寶藏以及『瘋子』丘洛的寶藏。', '', '去找祖爾德拉克的割顱者艾胡奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12624 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12624, 'zhTW', '它可能在任何地方!', '當我發現寶莉安小姐要和奈辛瓦里遠征隊一起進行這趟旅行時，我立刻就簽約成為一名甲板員。你知道，我已經計畫要娶她好幾個月了!$B$B原本一切都準備好了。我本來要在船難那天晚上向她求婚...但現在戒指不見了。我找遍了每個地方!$B$B我知道這聽來很瘋狂，但我確信訂婚戒指就在盆地的某個地方。如果不是某個風險投資公司的人偷了它，可能就是被野生動物給吃了。但它就在盆地的某處...我就是知道!', '從休拉薩盆地的各種生物身上尋找黃金訂婚戒。', '', '去找索拉查盆地的查德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12625, 'zhTW', '支配阿徹魯斯', '向偉大的死亡之城阿徹魯斯行注目禮吧！它是舉世無雙的超級堡壘！即使是納克薩瑪斯，也不能承受一次來自黑鋒要塞的突然襲擊！$B$B或許你的意識仍然有些模糊，但事實是，我們的時間確實不多了。你必須在短時間內充分了解阿徹魯斯，把這裡所有的細節都記在腦子裡。戰爭的號角已經吹響了！$B$B立刻到本層的樓梯間去，東北，西邊，南邊，北邊，四個邊樓梯間隨便你選。從樓梯走到上面一層的守備層，在那裡找到攻城鍛造大師科弗斯，向他索要報告書。報告書是要送給薩拉諾爾的。', '向黑鋒要塞守備層的攻城鍛造大師科弗斯報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12627, 'zhTW', '突破金阿萊', '我一直試圖與諸神溝通。然而，金阿萊之池的咒醫在舉行的儀式一直干擾我的嘗試。$B$B打破他們的阻礙是必要的。如果你要往西南方進入池子的區域，我很確定你一定會碰上他們的魔法大鍋。$B$B擾亂每一個大鍋，破壞他們阻擋我的儀式。', '辛托加的巫醫庫弗要你擾亂藍色大鍋，綠色大鍋，紫色大鍋和紅色大鍋。', '', '去找祖爾德拉克的巫醫庫弗。', '已擾動藍色坩堝', '已擾動綠色坩堝', '已擾動紫色坩堝', '已擾動紅色坩堝', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12629, 'zhTW', '你可以逃，但你躲不了', '一旦天譴軍團有了目標，就沒有東西可以阻止他們獲得它。$B$B你注定要變成一個沒有心智的存在，變成一具行屍走肉...$B$B<史戴芬的臉扭曲成一個殘忍的笑容。>$B$B...除非，我們可以利用他們的慾望來對付他們。$B$B我晚點再解釋。我得準備一個複雜的魔法，而且需要一些材料。$B$B到東邊的苦楚聖匣去。殺掉憎惡體，並且收集那裡的食屍鬼口水，然後帶著他們的殘骸回來給我。', '黯黑守望的史戴芬要你前往苦楚聖匣，從惡臭的憎惡體身上收集5個惡臭的憎惡體內臟，以及收集5份黏稠的食屍鬼唾液。', '', '去找祖爾德拉克的史戴芬·瓦度。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12630 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12630, 'zhTW', '踢納斯、拿毛髮', '在你跟納斯見面之前，有件事情得先告訴你。$B$B納斯那天感染了一劑有毒的瘟疫，現在他既盲又聾，幾乎是麻木不仁了。$B$B不過這並不全是壞事。他差不多完全對事物免疫了，因此很適合做某些工作-比方說我現在要給你的工作。$B$B這附近有些初生的天譴食人妖，我們需要研究荒疫在他們身上的效果。帶上納斯和這雙靴子。當你殺了一隻食人妖，就猛踹他一腳，然後他就知道要採集毛髮樣本了。', '黯黑守望的史戴芬要你用納斯從乾癟的食人妖身上收集10份毛髮樣本。如果你失去了納斯，就回去找史戴芬。', '', '去找祖爾德拉克的史戴芬·瓦度。', '已收集毛髮樣本', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12631 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12631, 'zhTW', '某種邀請...', '這個頸飾以骸骨製作，仍然淌著血，充滿著精細繁複的設計。$B$B看著它，使你被一種不祥的感覺所吞噬 - 它在逼迫你戴上頸子。你奮力抵抗這種衝動，決定要把它帶回黯黑守望。$B$B如果有人能夠解釋這一切，一定是死亡騎士...', '把無息頸飾交給黯黑守望的史戴芬。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12632, 'zhTW', '但首先是我的後裔', '我是最後一個還沒被鎮壓的神，所以我們必須設法解救其他神。由於被鎮壓者的魔法所束縛，我沒辦法看出祂們的命運。$B$B但首先，我要請你幫我一個忙。德拉克瑞食人妖用我的魔法來對付我。他們將我的後裔轉變成了畸形的怪物。$B$B帶著我的鬍鬚，殺死我受折磨的子嗣，然後用它的魔法將他們從惡夢中釋放，重新復活。', '哈寇亞要你在她子嗣的屍體上使用她的鬍鬚來釋放他們，並且將他們復活。當你完成之後回到哈寇亞祭壇找她。', '', '去找祖爾德拉克的哈寇亞。', '哈爾科亞的被詛咒後裔已復活', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12633, 'zhTW', '黑暗呼喚', '這個頸飾以骸骨製作還滴著血，充滿著精細繁複的設計。$B$B看著它，使你被一種不祥的感覺所吞噬-它在逼迫你戴上它。你奮力抵抗這種衝動，決定要把它帶回黯黑守望。$B$B如果有人能夠解釋這一切，一定是死亡騎士...', '把苦痛糾結頸飾交給黯黑守望的史戴芬。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12634 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12634, 'zhTW', '有些人會打成檸檬汁，有些人會釀成酒', '老天在這時候丟給我一車的檸檬！當船墜地的時候，我最棒的酒桶都爆開了！我們現在只剩幾瓶蘭姆酒，根本不夠整個口渴的遠征隊喝啊！$B$B我們需要弄些酒精飲料，而且要快！$B$B叢生沼林東邊的樹上好像有很多水果，但是太高了我碰不到。你去找出粗壯的爬藤，然後看看你能不能把水果從樹上搖下來。把你找到的水果都帶來給我。', '把1個柳橙，2串香蕉，還有1個木瓜拿給奈辛瓦里營地的葛林布茲‧雷酒。', '', '去找索拉查盆地的葛林布茲·雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12635 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12635, 'zhTW', '雪豹女神的聖物', '我聽說你要去探視哈寇亞的狀況。祝你好運。$B$B我在想如果你到了祭壇周邊，願不願意幫我回收他們的聖物?我不需要太多個，而且那就在東南方不遠處而已。$B$B你怎麼說?', '辛托加的撰史者托基尼要你回收10個哈寇亞聖物。', '', '去找祖爾德拉克的撰史者托基尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12637 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12637, 'zhTW', '擦身而過', '也許是睿智、也許是幸運，二者其一阻止了你把這個頸飾戴上。$B$B不論如何，你得到這個東西絕非偶然。你被某人給盯上了。或者是某個東西...。$B$B把你的頸飾拿去給血玫，讓她把險些落在你身上的命運展示給你看。', '黯黑守望的史戴芬要你把無息頸飾交給血玫‧達圖拉。', '', '去找祖爾德拉克的史戴芬·瓦度。', '扼喉者的目的已揭露', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12638 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12638, 'zhTW', '迫近的呼喚', '也許是睿智、也許是幸運，二者其一阻止了你把這個頸飾戴上，$r。$B$B不論如何，你得到這個東西絕非偶然。你被某人給盯上了。或者是某個東西...。$B$B把你的頸飾拿去給血玫，讓她把險些落在你身上的命運展示給你看。', '黯黑守望的史戴芬要你把苦痛糾結頸飾交給血玫‧達圖拉。', '', '去找祖爾德拉克的史戴芬·瓦度。', '扼喉者的目的已揭露', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12639 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12639, 'zhTW', '冰凍土元素', '我們從附近抓到了這些元素，所以我現在有很多的防衛者了。但是，要讓它們強到可以抵擋我們的敵人需要很多能量。$B$B西北方德拉克瑪布瓦的冰凍土元素身上有我可以用來維持我們防線的東西。', '辛托加的元素馴伏者達茍答要你收集7個冰凍土元素精華。', '', '去找祖爾德拉克的元素馴伏者達苟答。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12640 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12640, 'zhTW', '封閉裂隙', '如果達茍答還沒講的話，我想她要派你去西北方的德拉克瑪布瓦幫她的防衛者找更多東西。$B$B當你在那邊的時候，艾胡奈想要你摧毀那些源源不絕冒出元素的裂隙。我們才不想要被他們攻擊!$B$B但要小心，在你嘗試封閉裂隙的時候會有更多冰凍土元素出現。', '辛托加的割顱者艾胡奈要你封閉7個元素裂隙。', '', '去找祖爾德拉克的割顱者艾胡奈。', '元素裂隙已封印', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12641, 'zhTW', '死亡從天而降', '在這個平台的上方，矗立著亞榭洛之眼。你可以從該處召喚出一個探測之眼，用它來分析血色十字軍在新亞法隆的駐防。亞榭洛之眼所擁有的力量應該可以令你輕易的獲取所需的資訊。$B$B使用亞榭洛之眼的虹吸能力來分析熔爐、市政廳、堡壘和禮拜堂。控制亞榭洛之眼的裝置就在平台的兩端。不要浪費時間，$n。$B$B此地天譴軍團勢在必得。這是巫妖王之令!', '巫妖王命令你利用亞榭洛之眼分析血色堡、新亞法隆熔爐、新亞法隆市政廳，以及赤紅之焰禮拜堂。使用亞榭洛之眼控制裝置來控制亞榭洛之眼。', '', '去找黑鴉堡壘的巫妖王。', '新阿瓦隆熔爐已分析', '新阿瓦隆市政廳已分析', '血色要塞已分析', '已分析緋紅烈焰禮拜堂', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12643 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12643, 'zhTW', '銀內襯', '一旦天譴軍團的眼中發現了目標，在得到它以前休想阻止他們。$B$B你注定要變成一個沒有心智的生物，像是一具會走路的屍體一樣...$B$B<史戴芬的臉扭曲成一個邪惡的笑容。>$B$B...除非，我們可以利用他們的慾望來對付他們。$B$B我晚點再解釋。我有一個複雜的魔法要準備，而且需要一些材料。$B$B到東邊去，苦楚聖匣下方的那塊地。殺掉那裡的食屍鬼和憎惡體，然後帶著他們的屍塊回來。', '黯黑守望的史戴芬要你前往苦楚聖匣，從惡臭的憎惡體身上收集5個惡臭的憎惡體內臟，以及收集5份黏稠的食屍鬼唾液。', '', '去找祖爾德拉克的史戴芬·瓦度。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12644 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12644, 'zhTW', '靜置', '現在我們有了原料，我也已經叫我的助手準備好蒸餾器了。他會監控整個過程，但我需要你幫忙控制場面。你搞不好會覺得我們就只是把東西通通扔進蒸餾器裡面擺著，但你錯了。$B$B材料和加熱都要在特定的時間加入，其餘的時候又要維持壓力不變。每個狀況都只有10秒不到的時間讓你反應而已。當你準備好開始蒸餾的時候，告訴『醺醉』麥克曼努斯。', '成功完成蒸餾流程，然後把做好的雷酒的叢林調酒交給奈辛瓦里營地的葛林布茲‧雷酒。', '', '去找索拉查盆地的葛林布茲·雷酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12645 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12645, 'zhTW', '試喝', '現在是找出真相的時候了!$B$B<葛林布茲咯咯笑著。>$B$B我一直都想說說看這一句。一般來說，我通常都會在宴會上公開新酒，但在這叢林的正中央可沒辦法這麼做。$B$B所以呢，咱們就把樣本拿給幾個好朋友試試，然後問問他們的評語吧。讓我看看，我們當然想聽赫米特‧奈辛瓦里的意見，然後還有海德里厄斯‧哈羅威也要。他們就在營地裡。還有，你也要搭飛行器飛到湖畔起降場去，就在盆地的中央附近，然後也讓塔瑪拉‧顛鏈嚐嚐看。', '把雷酒的叢林調酒樣品交給赫米特‧奈辛瓦里，海德里厄斯‧哈羅威，以及塔瑪拉‧顛鏈，然後回到奈辛瓦里營地向葛林布茲‧雷酒回報。', '', '去找索拉查盆地的葛林布茲·雷酒。', '海梅特的試味', '哈德里烏斯的試味', '塔瑪拉的試味', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12646 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12646, 'zhTW', '我的預言者，我的敵人', '我的預言者太快吸收了我太多力量，也因此害死了他自己。你可以在南邊德拉克瑪布瓦的水坑看出這件事的後果。$B$B我的前牧師已經將他給復活起來，以期完成這項工作。他們正在將我的力量重新引導回他身上，不久之後他就會重新甦醒。$B$B你必須在事情太遲之前解決他，然後帶著我的魔精回來。', '魯諾克祭壇的魯諾克之靈要你取得他的寒地熊神魔精。', '', '去找祖爾德拉克的魯諾克之靈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12647 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12647, 'zhTW', '苦難的盡頭', '我的身體已經死去多時了，$n。他們選出新的預言者來結束這一切只是時間上的問題。$B$B我要把我最後的力量灌注在你身上。在祭壇建築裡，那個折磨者的身上有一種薰香，可以喚醒我的身體，讓你能夠傷害它。$B$B使用薰香，為我結束我的苦難吧。$B$B如果我反抗的話，我先向你道歉。即使是我，求生的意志也是很強烈的。', '魯諾克之靈要你用折磨者薰香喚醒他的身體。然後你要用他的靈魂灌注給你的力量殺死魯諾克。如果你失去了魯諾克的魔精光環，你可以回去找魯諾克之靈重新獲取它。', '', '去找祖爾德拉克的魯諾克之靈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12648 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12648, 'zhTW', '裝扮', '拿著...我替你製造了一套偽裝，應該可以讓你看起來跟天譴軍團一模一樣。$B$B只要保持住偽裝，你應該可以自由的在他們之間走動。只有荒疫守衛可以看穿我的幻象。小心他們!$B$B還有一件事是你該知道的，就是這偽裝不太穩定，因此可能會無預警地消失，所以請保持警戒。$B$B讓我們來測試看看。使用頸飾並且拜訪東邊的天譴商人。帶一瓶苦澀血漿回來找我。', '黯黑守望的史戴芬要你使用蠱惑頸飾披上天譴偽裝。當你變成天譴軍的外貌以後，從軟魄那裡買一瓶苦澀血漿。如果你失去了蠱惑頸飾，回去黯黑守望找史戴芬再要一個。', '', '去找祖爾德拉克的史戴芬·瓦度。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12649, 'zhTW', '著裝!', '拿著...我替你製造了一套偽裝，應該可以讓你看起來跟天譴軍團一模一樣。$B$B只要保持住偽裝，你應該可以自由的在他們之間走動。只有荒疫守衛可以看穿我的幻象。小心他們!$B$B還有一件事是你該知道的，就是這偽裝不太穩定，因此可能會無預警地消失，所以請保持警戒。$B$B讓我們來測試看看。使用頸飾並且拜訪東邊的天譴商人。帶一瓶苦澀血漿回來找我。', '黯黑守望的史戴芬，要你使用蠱惑頸飾以披上天譴偽裝。當你變成天譴軍的外貌以後，從軟魄那裡買一瓶苦澀血漿。如果你失去了蠱惑頸飾，回去黯黑守望找史戴芬再要一個。', '', '去找祖爾德拉克的史戴芬·瓦度。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12650 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12650, 'zhTW', '掠奪他們自己的神器', '附近還有一個儲藏神器的祭壇。$B$B聽說在西北方，越過德拉克瑪布瓦的破碎凍原後方，魯諾克祭壇的德拉克瑞食人妖已經掠奪了他們自己的聖地。$B$B$c，如果你能夠從他們不知感激的手中搶救那些神器的話我會很感激你的。', '辛托加的撰史者托基尼要你回收7個魯諾克神器。', '', '去找祖爾德拉克的撰史者托基尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12652 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12652, 'zhTW', '餵食食屍鬼', '過來，食屍鬼!對啊，我在跟你說話。$B$B吃飯時間到啦!得把伙食都發給食屍鬼才行!$B$B今天的特餐!腸腦煲...好吃好吃好吃。$B$B只要在食屍鬼旁邊丟下碗公就好了。這是交朋友的好方法啊。$B$B你有食屍鬼朋友嗎?哈，哈，哈哈!', '苦楚聖匣的軟魄，要你在10個凋零的食屍鬼旁邊使用腸腦煲。', '', '去找祖爾德拉克的軟魄。', '已餵食腐爛食屍鬼', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12654 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12654, 'zhTW', '兼差獵人', '當赫米特要我陪馬文來這裡的時候，我暗自期望我有機會在修理飛行器和建立營地的空檔磨練我的狩獵技巧。$B$B我想要狩獵一頭叫做匹奇的獅子。聽說他出沒在南方，靠近叢生沼林與擎天之柱北面交界之處。如果你找到那頭野獸的話，可以幫我把屍體帶回來嗎?如果謠言是真的，那麼牠會是個連赫米特都會肅然起敬的戰利品!', '把匹奇的殘骸帶去給湖畔起降場的塔瑪拉‧顛鏈。', '', '去找索拉查盆地的塔瑪拉·顛鏈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12655 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12655, 'zhTW', '辛茹克的祝福', '祖爾德拉克還有一位被忽視的神明。$B$B辛茹克的雕像就在正北方。被稱做「睿智者」的辛茹克也很珍惜祂的領域。祂讓守衛嚴厲的處罰那些不夠聰明，沒繞過守衛的人。$B$B避開守衛，然後把祭品獻給辛茹克，以獲取祂的祝福。', '巫醫庫弗要你對辛茹克的雕像獻上10份德拉克瑞祭品。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12656, 'zhTW', '辛茹克的祝福', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12658 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12658, 'zhTW', '我的大鵬寵物', '多里安要我訓練餵食他抓到的這些幼龍，這讓我想到，我也想要自己的寵物!$B$B不，不要這些幼小的龍。我不想要一頭能夠把我手咬斷的寵物!$B$B不過，在營地東北的白骨原野，越過龍類盤據的區域，有一大群的血爪大鵬。成鳥是不可能馴服的了，但如果你從巢裡幫我拿蛋來，我可以從孵化就開始養起。', '把7個大鵬蛋帶去給多里安前哨的狹嘶。', '', '去找索拉查盆地的狹嘶。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12659 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12659, 'zhTW', '割頭皮!', '我想差不多是割點頭皮的時間了，老兄!$B$B東北邊希伯德拉卡的食人妖應該很不賴。誰叫他們要養了那些花俏的蝙蝠，又攻擊我們呢!$B$B艾胡奈甚至還借給你他的刀子讓你好好完成這項工作呢。', '辛托加的割顱者艾胡奈要你使用艾胡奈小刀去割10個希伯德拉卡食人妖的頭皮。割顱者提醒你記得要先拾取他們身上的物品。', '', '去找祖爾德拉克的割顱者艾胡奈。', '赫布達卡萊巨魔已被剝頭皮', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12660 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12660, 'zhTW', '毀滅武器', '巫妖王的走狗竟敢帶毀滅性的武器進入我的領地。我無法忍受這種事。$B$B去北邊，到他們的前哨銷毀他們用來破壞這塊大地的武器。我們不能讓天譴軍團再污染這聖地的一分一毫了。', '芙蕾雅的化身要你前往西北方的死亡之手駐營摧毀4個不穩定爆裂物。', '', '去找索拉查盆地的芙蕾雅的化身。', '不穩定炸藥已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12661 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12661, 'zhTW', '滲透沃塔魯斯', '你現在也許已經猜到我的計畫了。$B$B我們要利用天譴軍團對你的興趣來對付他們。你要去進行臥底工作。我知道這等於是叫你去送死，但反正我們不採取行動的話你也是死定了。$B$B前往東北方的痛苦聖匣，然後披著你的偽裝站上那個平臺。進入沃塔魯斯之後你得去贏取天譴指揮官的信任。$B$B完成了你的任務之後，就吹響這個號角，我會飛去你的位置接收報告。', '史戴芬要你使用蠱惑頸飾進入沃塔魯斯然後完成天譴指揮官的任何要求。如果你失去了蠱惑頸飾，回去黯黑守望找史戴芬再要一個。', '', '去找祖爾德拉克的史戴芬·瓦度。', '上將達庫魯的任務已完成', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12662, 'zhTW', '宰掉希伯金', '<達茍答看著艾胡奈，然後嘆了口氣。>$B$B你真的想要對付希伯德拉卡?光是收集頭皮是沒用的。你得解決掉他們的首領，希伯金。$B$B問題是，他待在他們的蝙蝠養殖場上面指揮他的部隊。$B$B去敲響他的鼓，我保證他會飛下來。那就是你動手殺他的好時機。$B$B你可以帶著我們從他的獵頭者那裡得到的網子。當他降落的時候用網子困住他的蝙蝠。這樣你就不用同時面對兩個敵人。', '辛托加的元素馴伏者達茍答要你殺死希伯金。', '', '去找祖爾德拉克的元素馴伏者達苟答。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12663, 'zhTW', '聚首', '', '沃塔魯斯的德拉庫魯要你跟血袋交談，然後參觀祖爾德拉克。', '', '去找祖爾德拉克的德拉庫魯霸主。', '祖爾德拉克的巡禮已完成', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12664, 'zhTW', '黑暗地平線', '', '沃塔魯斯的德拉庫魯要你跟血袋交談，然後參觀祖爾德拉克。', '', '去找祖爾德拉克的德拉庫魯霸主。', '祖爾德拉克的巡禮已完成', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12665, 'zhTW', '我感應到不安', '風蛇女神奎茲倫出了點問題。我沒辦法感應出確切的狀況，但我知道她的祭壇被強大的生物給蹂躪了。$B$B我要派你搭乘我其中一個被你拯救的孩子過去那裡。你們兩個將會迅速而隱匿的移動，查出奎茲倫的狀況。$B$B我的孩子將會確保你平安回到我這裡來。睜大眼睛注意狀況吧。$B$B當你準備好的時候就提出要求，我會為你召喚我的小貓。', '哈寇亞要你查清楚奎茲倫身上發生了什麼事。和她交談以騎上她的孩子，潛入奎茲倫的祭壇。當你完成任務之後回到哈寇亞祭壇找她。', '奎茲倫的命運已揭露', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12666, 'zhTW', '進入幽界的準備', '奎茲倫可能已經死了，但我可以感覺到他的靈魂還在幽界的祭壇處徘徊。我們得想個辦法把你送過去她那裡。$B$B幸運的是， 我手邊剛好有一批不再被主人需要的神聖飾物。我的鎮壓者和爪牙應該都還戴著它們。$B$B把那些飾物帶來給我，我會抽取它們的能量讓你跨入奎茲倫的幽界夢魘中。', '哈寇亞要你收集8個神聖飾物。收集完成之後送去哈寇亞祭壇給她。', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12668 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12668, 'zhTW', '復仇的基礎', '我為我最愛的高階祭司準備了特別的計畫。不過，首先你得透過為我的復仇奠基來證明你自己。$B$B你還想活，對吧?$B$B就像你看到的一樣，我的信徒在這裡過得很愜意，但是該送他們回去最終的歸宿了。$B$B如果你願意的話就幫我這個小忙，$n。引誘他們靠近我的靈魂之泉，然後了結他們的性命。$B$B他們嚐起來如此美味，他們的獻祭再也不會落空了。我向你保證。', '奎茲倫之靈要你在她的靈魂之泉附近毀滅12個食人妖，不管是奎茲倫崇拜者或蛇觸狂戰士都可以。你只能在完成這任務之後才回去她的祭壇找她。', '', '去找祖爾德拉克的奎茲倫的靈魂。', '已在靈魂噴泉附近擊殺巨魔', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12669, 'zhTW', '目前為止一切都很糟', '你所報告的一切都與我們所知的相符。觀察德拉庫魯以及贏得他的信任將會為你未來的任務打好基礎。$B$B回去找他，然後照他說的話做。用一切手段使你自己看起來很真心，$n。有太多事都要靠你的表現了。$B$B這次我還要指派你一項額外的工作:當你在原野上的時候，將這個添加物加進他們的荒疫大鍋裡面。這應該能夠中和天譴的散佈，讓這一批鍋子失效。', '黯黑守望的史戴芬要你回去找德拉庫魯，然後完成他交代你的工作。當你到痛苦聖匣的時候，你要對5個荒疫大鍋使用稀釋添加物。如果你失去了蠱惑頸飾，回去黯黑守望找史戴芬再要一個。', '', '去找祖爾德拉克的史戴芬·瓦度。', '達庫魯的任務已完成', '枯萎坩堝已稀釋', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12671, 'zhTW', '空中偵察', '咱們差不多是時候把飛機準備好然後讓這個地方運作起來了。教授一直要我查探從東北方來的氣候異象。$B$B問題是，如果我們要飛進未探索區的話，我需要一位副駕駛。我才不要一個人飛去那個鬼地方。$B$B怎麼樣，$g猛男:辣妹;?也許你可以學到點什麼啊。只要你學會處理北風...要飛去哪裡都不是問題。', '協助駕駛員維克完成偵察飛行。', '偵察飛行', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12672 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12672, 'zhTW', '準備舞台', '我給你個繼續存活的機會。$B$B有許多驅動詛咒的能量碎片散落在祭壇附近的地面。我想要你去替我收集那些碎片。沒有多到足夠撼動詛咒的程度，但夠我用來對我的預言者復仇了。$B$B去吧，小蟲。在我改變讓你活著的決定之前快完成我的要求。', '奎茲倫的靈魂要你收集10個幽界力量碎片。當你完成之後回到奎茲倫祭壇找她，。', '', '去找祖爾德拉克的奎茲倫的靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12673 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12673, 'zhTW', '滾下山坡', '如果你要讓自己值得巫妖王賞識，你就得當一個好的領袖-要能夠控制尊敬!$B$B我有個能夠讓你磨練指揮技巧的工作，老兄...$B$B我有些手下被訓練去底下的土地收集荒疫水晶，但他們又懶又慢的。你要負責指揮他們，老兄。$B$B帶著這根權杖去教他們怎樣做好工作。當他們被你控制住了，就叫他們去收集水晶!', '沃塔魯斯的德拉庫魯指揮官，要你對荒疫魂屍使用建言權杖，然後命令他們收集7個荒疫水晶。', '', '去找祖爾德拉克的德拉庫魯霸主。', '已收集枯萎水晶', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12674, 'zhTW', '地獄也會憤怒', '現在你該懲罰我的三個高階祭司了:姆弗努、托托、還有哈文尼。你可以在祭壇周邊找到他們。$B$B帶著這根妖術手杖。我用我的憤怒強化了手杖。我確定它的效果一定夠強。$B$B只要使用它，然後接著毀掉他們就行了。手杖上的妖術會處理好其他事情。$B$B<奎茲倫露齒而笑。>$B$B成功了我就放你走。失敗了就死。', '奎茲倫祭壇的奎茲倫之靈要你對高階祭司姆弗努、高階祭司托托、還有高階祭司哈文尼使用奎茲倫的妖術手杖。一旦使用完手杖，就殺了他們。', '', '去找祖爾德拉克的奎茲倫的靈魂。', '大祭司穆夫努死前已被施咒', '大女祭司圖阿圖阿死前已被施咒', '大祭司哈溫尼死前已被施咒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12675, 'zhTW', '最後一件事', '在我們實行對預言者的終極復仇之前只剩下最後一件事情要做。你所收集的力量碎片必須灌注一個活神的部分靈魂。你必須向哈寇亞求取她的靈魂。$B$B一旦你成功了，你不要回到幽世來，返回我物質世界的祭壇。我的子嗣與守護者將不會再攻擊你，你可以輕鬆地接近我的預言者。', '將幽界力量碎片堆送去給哈寇亞，請求她給你部分的靈魂。你仍會在哈寇亞祭壇找到她。', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12676, 'zhTW', '破壞工作', '在我們想辦法研究水晶的用途的時候，我們要你回到沃塔魯斯去達成德拉庫魯的要求。$B$B你每成功完成一個任務，你就越接近他，帶領我們更加接近他的心思。$B$B你到兒的時候，我還有個任務要給你。德拉庫魯的天譴血屍車隊我們造成了顯著的威脅。我們得那些車子毀掉。$B$B去血屍車那裡啟動這些炸藥。一旦裝好了，就快離開!如果你太靠近的話，炸彈也會波及到你。', '黯黑守望的史戴芬要你再替德拉庫魯完成一項任務。此外，你還要在痛苦聖匣用爆破炸藥炸毀5台血屍車。如果你失去了蠱惑頸飾，回去黯黑守望找史戴芬再要一個。', '', '去找祖爾德拉克的史戴芬·瓦度。', '天災戰車已摧毀', '達庫魯的任務已完成', '得知達庫魯的秘密', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12677, 'zhTW', '危險物質', '荒疫水晶?!這該死的德拉庫魯究竟想要做什麼?$B$B顯然，他在做的事很重要。繼續完成他的要求，也許當他跟你更熟了以後，就會讓你知道他的計畫。$B$B在此期間，我們得調查這些水晶。$B$B當你進入沃塔魯斯的時候，試著趁沒人注意的時候弄來一些採收的水晶。$B$B小心點!處理那些水晶的時候你的偽裝有可能會消失。', '黯黑守望的史戴芬要你去沃塔魯斯完成任何德拉庫魯要你做的任務。當你到那裡的時候，要去偷取5個採收的荒疫水晶。$B$B如果你失去了蠱惑頸飾，回去黯黑守望找史戴芬再要一個。', '', '去祖爾德拉克找黑鋒哨站的斯特凡·瓦杜。', '完成德拉庫魯的任務', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12678, 'zhTW', '混沌所驅，讓苦難控制你的情感', '他們現在在死亡止境外頭站穩了陣腳，徒勞地試著想要逼退我們以保住他們的馬匹、礦坑、木材、以及人民。$B$B這是你在天譴戰爭中所要學習的第一課:恐懼!$B$B去南邊的前線，消滅血色十字軍。保留屍體，以利我們製造死亡大軍。$B$B但最重要的是，要殺死逃跑的村民。他們可以接受士兵犧牲喪命，但村民呢?村民的死將會把恐懼深植在人們心中。', '死亡止境的瓦拉納爾親王命令你殺死10個血色十字軍或血色農民，以及10個避風郡市民。', '', '去找瘟疫之地：血色禁地的瓦拉納爾親王。', '血色十字軍已擊殺', '避難郡的居民已擊殺', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12679 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12679, 'zhTW', '今晚我們在避風郡用餐', '晦天者是毫無心智的傀儡，只有一個存在目的:殺!他們專門鎖定任何從避風郡逃向新亞法隆尋求安全的人們。我們當然不能讓那些懦夫逃向安全的地方，然後武裝起來對抗我們!$B$B但我們有個小小的問題。它們為了最大的射程和傷害而使用了薩鋼箭。然而，薩鋼是一種只有北裂境出產的金屬，因此我們資源有限!替我回收那些箭，那麼我就會賜給你可觀的獎賞。', '死亡止境的『晦天者』歐里索斯要你回收15枝薩鋼箭。', '', '去找瘟疫之地：血色禁地的『晦天者』歐里索斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12680 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12680, 'zhTW', '俠盜獵馬手', '十字軍在距離我們一步之遙的地方有個滿是馬匹的獸欄真是太幸運了。雖然他們持續防守它，一個積極進取的新生死亡騎士應該能夠突破他們的防守，並且取得屬於$g他:她;的東西!$B$B一旦你從避風郡獸欄取得了馬匹，就把牠帶回來給我，我會設法把牠變成一匹優秀的死亡戰騎。$B$B記住，$n，只有被抓到才算是偷。小心那個混蛋獸欄管理員，基崔克!', '『騎士』撒拉納要你從避風郡獸欄偷來一匹馬，然後回到死亡止境交給他。', '', '去找瘟疫之地：血色禁地的『騎士』撒拉納。', '已成功偷取馬匹', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12681, 'zhTW', '試劑專員', '在達拉然的大法師潘塔魯斯期待我們帶著各種試劑和法器回去。本地居民似乎偏好動物的肢體。血爪大鵬的扭曲爪子是他們的最愛。$B$B我並沒有資格判斷謠言的真實性，不過我想這其中確實有些古怪。$B$B有很多大鵬棲息在東北方的白骨原野，以老長毛象的屍體為食。你願意幫我收集給大法師研究的爪子嗎?', '將5個扭曲的大鵬爪帶給多里安前哨的寇爾文‧諾靈頓。', '', '去找索拉查盆地的寇爾文‧諾靈頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12682, 'zhTW', '人跡未竟之地(DEPRECATED)', '並非所有的遠征隊成員都是來狩獵取樂的，我們中的一部分人還肩負著重要的研究工作。$B$B冰封的北裂境中心竟然存在這樣一片熱帶天堂——休拉薩盆地真是不可思議的存在。如果我不能搞清楚這片土地的奧秘，就不配做個學者。$B$B這張地圖給你吧。', '這次遠征隊裡並不是所有人都是來獵殺最大、最稀有的獵物的。我們之中有些人其實有正經事要做。$B$B這個地方的存在本身就令人費解——在北裂境的中央居然有一片熱帶樂園。如果我不花點心思試著了解這個地方，那我這個學者的頭銜可就名不副實了。$B$B拿著這些', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12683 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12683, 'zhTW', '十萬火急', '這個盆地中沒有比惡潮多頭蛇唾液更具有腐蝕性的東西了。我有個特製的容器，用來替大法師潘塔魯斯收集這樣的東西。現在我只需要一位勇敢的，呃...收集者。$B$B你看起來像是個強壯又愛冒險的$c。你想不想一面賺點錢，一面替達拉然辦點事呢?$B$B你只要拿著這個容器到惡潮湖去，就在西南邊。去攻擊多頭蛇，然後用容器採集他們噴灑在你身上的唾液即可。', '多里安前哨的寇爾文‧諾靈頓要你採集5份多頭蛇唾液樣本並殺死5隻惡潮多頭蛇。', '', '去找索拉查盆地的寇爾文‧諾靈頓。', '已收集痰液樣本', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12684 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12684, 'zhTW', '逝神之血', '長毛象之神瑪姆托司選擇自我毀滅，同時也將神殿毀了大半，不讓祂的食人妖取得祂的力量。$B$B如果我要犧牲我部分的靈魂，我就需要一些用來支撐自己的東西。$B$B瑪姆托司在東北方留下了一個大坑洞，就在奎茲倫祭壇的北邊。在坑洞裡，他的血液仍舊活著。$B$B把它帶來給我。', '哈寇亞要你去收集7個瑪姆托司之血。將它們帶回去哈寇亞祭壇給她。', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12685 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12685, 'zhTW', '自作自受', '這就是事情的結果...復仇。$B$B<哈寇亞嘆了一口氣。>$B$B帶著這個儀式工具包，然後在祭壇上奎茲倫的屍體附近啟動它。如果一切順利，她的靈魂會被拉進物質界，讓她能夠從預言者身上取回力量。$B$B剩下的就靠你了，$n。你必須在預言者枯竭的狀態下殺死他。', '殺死枯竭的奎茲倫預言者然後通知辛托加的巫醫庫弗。', '', '去找祖爾德拉克的巫醫庫弗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12686 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12686, 'zhTW', '忍無可忍', '愚蠢!這實在是忍無可忍，老兄!我整批的荒疫都沒用了!$B$B那個雜種，達穆克!他應該負責看守那些荒疫的。他令我失望了，老兄!$B$B好好學著，$n。失敗是會像疾病一樣蔓延的。你得抓住它，在你被殺掉之前搶先除掉它!$B$B帶上這支權杖。他會讓我的天譴食人妖變的更強壯。用他們殺掉達穆克。他就躲在下頭南邊的地方$B$B讓他成為所有人的警惕吧，老兄。不要讓德拉庫魯失望!', '沃塔魯斯的德拉庫魯要你前往痛苦聖匣，並且對德拉庫魯的僕從使用活效權杖。接著用它的能力來擊敗達穆克。', '', '去找祖爾德拉克的德拉庫魯霸主。', '已擊殺達爾穆克', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12687 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12687, 'zhTW', '進入陰影之境', '你所偷來的馬匹已經被帶往陰影之境了。我的黑騎兵就是在那裡殺死這頭野獸，然後將它復活成一匹死亡戰騎的。你覺得你有勇氣進入陰影之境求取死亡戰騎嗎?$B$B如果你接受的話，我將會把你傳送至陰影世界。一旦你到了那裡，到我們南方的曠野去找黑騎兵。如果要凱旋而歸，你就得殺死他，奪取他的死亡戰騎，然後返回死亡止境。一旦你成功了，就發出騎士之喚吧。', '死亡止境的『騎士』撒拉納要你去挑戰並殺死亞榭洛黑騎兵，然後奪走他的亞榭洛死亡戰騎。如果你成功了，把亞榭洛死亡戰騎帶回死亡止境，然後用騎士之喚召喚撒拉納。', '騎士的挑戰', '去找瘟疫之地：血色禁地的『騎士』撒拉納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12688 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12688, 'zhTW', '設計工程災難', '這些哥布林流氓和他們的手下自稱擁有這個柱子和水晶。我是來這裡探勘這些水晶和採取樣本的，但他們制服了我，不讓我回去營地。$B$B如果你幫我殺出一條路離開這裡，我們就可以給這些惡棍上一堂永難忘懷的課!', '幫助工程師海里斯從詐咧挖掘場逃脫，然後到奈辛瓦里營地找赫米特‧奈辛瓦里談話。', '護送工程師海莉絲離開斯溫格林的挖掘場', '去找索拉查盆地的赫米特·奈辛瓦里。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12689 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12689, 'zhTW', '神諭者之手', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12690 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12690, 'zhTW', '火上加油', '該開始對剛德拉克進軍了，老兄。也是時候把你放出去對付那些食人妖了!$B$B他們突破了我們的牆壁，把整個軍隊送到咱們北邊。$B$B哈哈哈!$B$B他們只是替咱們補充燃料罷了，老兄!我們把酋長抓過來，然後其餘的都殺光!這是主人計畫中的一部份...$B$B你帶著這根權杖去控制我的憎惡體。帶他們到德拉克瑞的軍隊那裡去，然後把他們全都殺掉!當酋長出現的時候，我的寵物泥岩之翼將會把他們抓來我這裡。', '沃塔魯斯的德拉庫魯要你用指揮權杖控制浮腫的憎惡體，然後在嚴寒止境用他們的能力殺死60個德拉克瑞碎顱者，並引出3個德拉克瑞酋長。當你殺死夠多碎顱者之後酋長就會出現。', '', '去找祖爾德拉克的德拉庫魯霸主。', '達卡萊碎顱者已擊殺', '已引誘達卡萊酋長', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12691 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12691, 'zhTW', '古舊的石箱', '這個石箱似乎被鎖住了。看起來似乎有個巨大的石頭鑰匙孔。$B$B也許附近的守衛身上會有鑰匙。', '從附近的休拉薩守護者身上取得巨型石頭鑰匙然後帶到造物者瞰臺的古舊石箱處。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12693 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12693, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12694 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12694, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12698 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12698, 'zhTW', '好禮送不完', '我從納克薩瑪斯的冰凍核心來此享用靈魂，並且給予我們的宿敵迎頭痛擊 - 我全力以赴。$B$B我要給你的這個裝置，是個攜帶式的瘟疫散播器。把它帶去東邊的避風郡礦坑，然後在作業中的血色礦工附近釋放它。用它來把礦工轉變成食屍鬼;當你擁有一小隻軍隊的時候再回來找我。我在靈魂真空清潔器裡面給他們預留了位置!', '死亡止境的『收割者』高希交給你收割者的禮物，要你用在血色礦工身上。用這個裝置製造5個血色食屍鬼，然後把食屍鬼帶去給高希。', '', '去找瘟疫之地：血色禁地的『收割者』高希。', '血色食屍鬼已歸還', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12699 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12699, 'zhTW', '難堪的插曲', '在我們出發之前得先解決一個小問題。懂嗎，我好像找不到飛行器的鑰匙。$B$B我幾乎把每個地方都找遍了…也許你可以幫我一把。我還沒找過的地方就只剩下湖裡而已了。$B$B我甚至可以把我自己的氣瓶給你。雖然氣瓶裡面的空氣不多了，但是還能讓你呼吸個幾口。', '在大河之心的湖水中尋找維克的鑰匙串。', '', '去找索拉查盆地的駕駛員維克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12701 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12701, 'zhTW', '聖光之尖大屠殺', '在匆忙的撤離中十字軍將會犯下一個致命的錯誤:忘記要檢查他們的礦車。$B$B你要回到東邊的避風郡礦坑，找出我的手下放在庫房外的礦車。爬進礦車裡面，然後讓不知情的血色礦工幫你滲透進敵人的後方。$B$B一旦你登上了他們的船艦，就用船上的大砲來對付他們!把他們屠殺殆盡!$B$B要離開的時候，就從大砲那裡召喚天譴獅鷲獸。', '死亡止境的瓦拉納爾親王命令你殺死100個血色防衛者。', '', '去找瘟疫之地：血色禁地的瓦拉納爾親王。', '血色守衛已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12702 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12702, 'zhTW', '雞派對!', '我賭你猜不到發生什麼事了。$B$B不，當然不是茍瑞格克或是雞。$B$B好吧，我騙人的，苟瑞格克又讓雞跑出來了。笨苟瑞格克和鬼叫的肚子。$B$B如果你需要任何獵人的協助，儘管跟我說...他們就在附近某處。', '給狂心之丘的長者哈爾凱克逮住12隻逃跑雞。', '', '去找索拉查盆地的長者哈爾凱克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12703 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12703, 'zhTW', '卡爾塔克的衝撞', '你就是偉大的巫妖獵人，吭?有個這麼強的狂心盟友加入戰鬥真好。也許你甚至強到可以召喚卡爾塔克。$B$B西南邊的卡爾塔克堡正在進行大戰。去殺死附近的大舌頭，直到你拿到一份好的神諭者血。把血帶回祭壇召喚卡爾塔克來吃好吃的大舌頭大餐。$B$B如果你值得尊敬，卡爾塔克就會進入你的身體...有了卡爾塔克的力量，你可以殺死很多火觸大舌頭。$B$B去大開殺戒吧，獵人!', '將純淨的神諭者之血樣本帶到卡爾塔克的祭壇，召喚出卡爾塔克。只要有卡爾塔克分享力量的幫助，替卡爾塔克堡的薩滿賈克杰克殺死附近50個炫觸戈洛克。', '', '去找索拉查盆地的薩滿賈克杰克。', '電光魚人已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12704 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12704, 'zhTW', '取悅偉大雨石', '自從苔行者被攻擊以來，我就擔心是我們對偉大雨石不夠好...也許我們太貪心。我們需要貢獻更多財寶!$B$B你上次很擅長找亮晶晶...也許你可以多找一點?你也許需要好雨頌者的幫忙。告訴我們需要誰就好。', '雨頌者之篷的高階神諭者蘇-楔要你帶著一個同伴挖掘收集6個閃亮的財寶。記得向雨頌者之蓬的高階神諭者蘇-楔要你先前的同伴。', '', '去找索拉查盆地的高階神諭者蘇-楔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12705 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12705, 'zhTW', '泰坦的意志', '小狗人持續攻擊炫觸...我們得對抗他們，否則他們就會攻擊別的神諭者。$B$B你是我們的好朋友，所以我們給你特別的榮耀。偉大的諸神很久以前留下了保護者守衛祭壇...它現在還在，但聖壇沒被侵擾它就不知道大事不妙。$B$B小狗人有對祭壇不好的水晶...去殺小狗人，然後找到壞水晶，帶去祭壇:這樣蘇-侯魯就知道要幫忙了。$B$B如果蘇-侯魯帶你進入他的身體，你不要害怕。他很強，所以會保證你安全。', '從炫觸避風港附近的獾狼怪身上取得一塊受污染的水晶，並帶往偉大閃電石召喚蘇-侯魯。在蘇-侯魯所分享的力量幫助下，殺死50個附近的狂心獾狼怪，然後向偉大閃電石附近的喚雷者蘇-邁特回報。', '', '', '狂心攻擊者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12706 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12706, 'zhTW', '死亡止境的勝利!', '<瓦拉納爾親王交給你一個封好的卷軸。>$B$B這是我們在死亡止境勝利的完整報告。你要把它交給大領主莫格萊尼 - 在亞榭洛裡。我有特地將你的英勇行徑寫進報告裡。莫格萊尼將會為了這場勝利給予你豐厚的獎勵，$n。$B$B去吧!', '把瓦拉納爾親王的報告交給亞榭洛:黯黑堡中的大領主達瑞安‧莫格萊尼。', '', '去找黑鴉堡壘的大領主達瑞安‧莫格萊尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12707 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12707, 'zhTW', '毛茸茸的正義', '艾胡奈聽說你要去瑪姆托司爆坑啊，老兄。瑪姆托司之子被激怒了，並且高聲要求正義!$B$B沿著東北的小路走上階梯，前往祖爾德拉克的下一層。你在右手邊可以找到瑪姆托司祭壇的殘留部分。$B$B當你到了那裡以後，把這個瑪姆托司勳章亮給一頭暴怒的長毛象看。牠會冷靜下來，讓你跳上牠的背。$B$B騎上牠，把所有你找得到的瑪姆托司信徒都給踩爛!', '辛托加的割顱者艾胡奈要你使用瑪姆托司勳章安撫一頭暴怒的長毛象，然後騎上牠將12個瑪姆托司信徒踐踏至死。', '', '去找祖爾德拉克的割顱者艾胡奈。', '瑪姆托斯的信徒已被踐踏致死', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12708 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12708, 'zhTW', '附魔提基戰士', '我知道你要去東北邊的佐爾馬茲堡砦，$c。當你到那裡的時候，我需要你對付督軍的特別護衛。$B$B他們叫做附魔提基戰士，是非常嚴重的威脅。如果德拉克瑞食人妖大量生產他們，我們很快就會被擊垮了。$B$B讓咱們告訴他們這種東西不值得生產，怎麼樣?', '辛托加的元素馴伏者達茍答要你消滅12個附魔提基戰士。', '', '去找祖爾德拉克的元素馴伏者達苟答。', '附魔提基戰士已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12709 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12709, 'zhTW', '中了妖術的儲藏箱', '請見諒，$n。我聽說你可能要前往東北方的佐爾馬茲堡砦。這樣的旅程對我們來說，是替收集德拉克瑞貨物做個收尾的好機會。$B$B我透過管道得知德拉克瑞督軍的異常偏執。他對堡砦裡所有的儲藏箱都施展了強大的妖術。謠傳他的提基戰士身上有解藥，但誰知道呢?$B$B如果你有空收集這些貨品的話，我會非常感激你的。', '辛托加的撰史者托基尼要你收集12個佐爾馬茲堡砦貯藏箱。', '', '去找祖爾德拉克的撰史者托基尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12710 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12710, 'zhTW', '揭露真相', '你做得很好，$n。$B$B你證明了我有看人的眼光!現在你知道為什麼巫妖王給了我這個天賦...$B$B現在是時候把主人的計畫透露給你了，老兄。$B$B現在你會知道我們要怎麼掃蕩蜂擁的德拉克瑞食人妖，然後在偉大的剛德拉克取得我們應得的位置。$B$B拿著這枝權杖，老兄。這是對你信任的象徵。有了它，你就可以進入我的上層房間，親眼見識一下我們的秘密武器。', '沃塔魯斯的德拉庫魯要你傳送至他的上層房間。', '', '去找祖爾德拉克的德拉庫魯霸主。', '已探索達庫魯的上層密室', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12711 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12711, 'zhTW', '被遺棄的信件', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12712, 'zhTW', '督軍佐爾馬茲的鑰匙', '$n，我們需要一把鑰匙來解開犀牛神阿卡利的縛鎖。他們正準備要殺死祂。$B$B德拉克瑞督軍，佐爾馬茲持有那把鑰匙。聽說了你的事蹟之後，他把自己和家人關在東北方階梯上的要塞裡。$B$B督軍很強，而你將會需要幫助。如果你能夠結合提基，也就是他家族成員的劍與符咒，你就能夠召喚你所需要的助力，到他的家門前去挑戰他。', '辛托加的哈寇亞要你去取得督軍佐爾馬茲的鑰匙。', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12713 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12713, 'zhTW', '背叛', '是時候結束這場猜謎遊戲了，$n。$B$B雖然你帶來的情報很有價值，我們還是必須解決德拉庫魯，在他把他的怪物放出來之前終止他的計畫。$B$B我們替你改造了這柄權杖。當時機來臨的時候，你可以對德拉庫魯的荒疫之血食人妖使用它，然後讓他們背叛德拉庫魯。這是你唯一可以擊敗他的機會。$B$B好好奮戰吧。', '黯黑守望的史戴芬要你擊敗德拉庫魯。如果你把蠱惑頸飾搞丟了，返回黯黑守望的史戴芬處再拿一個。', '', '去找祖爾德拉克的史戴芬·瓦度。', '已擊敗上將達庫魯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12716 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12716, 'zhTW', '瘟疫使者的要求', '看看這個南瓜拼湊成的東西!有注意到少了什麼嗎?你當然沒注意到，因為你是個蠢貨!你大概是從腦袋開始死掉的吧。$B$B<諾斯嘆了口氣。>$B$B我收到命令要我製作一個瘟疫大鍋。你要協助我。$B$B在新亞法隆的大門裡面就是旅館。進入旅館，偷個空鍋給我。然後去熔爐，它也很靠近大門，然後偷一些鐵鍊來。也幫我拿10個十字軍的頭顱來。需要我跟你講頭顱上哪兒找嗎?', '『瘟疫使者』諾斯要求你替他拿1個空的大鍋，1條鐵鍊，還有10個十字軍顱骨來。', '', '去找瘟疫之地：血色禁地的瘟疫者諾斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12717 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12717, 'zhTW', '諾斯特調', '大鍋已經準備好對整片大地噴灑它惡臭的腐化了!$B$B現在，替你上一堂關於瘟疫大鍋的課程，死亡騎士。大鍋所釋放的氣體對活物來說是非常致命的，但卻能夠強化天譴軍團。對所有的天譴生物來說，它能夠餵養死亡，時間越久就越強大。$B$B拿著這些十字軍顱骨，把它們扔進大鍋裡。你會對結果感到很高興的。', '把十字軍顱骨堆放進瘟疫大鍋中。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12718 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12718, 'zhTW', '用更多的顱骨來釀製', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12719 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12719, 'zhTW', '無處可逃，無處可躲', '除了全面殲滅以外，沒有什麼能滿足我們，$n。要達成這個目標，只靠幾百隻無腦的食屍鬼去突擊新亞法隆的正門是不夠的。我們必須滲透他們的聖所並且處理掉他們的官員。要讓他們知道在天譴軍團的掌心是無路可逃的!$B$B潛入西南方的新亞法隆市政廳，然後刺殺鎮長。從那棟建築裡找出新亞法隆名冊，然後帶來給我。', '緬懷墓穴的凱雷希斯親王命令你殺死鎮長昆比，並取得新亞法隆名冊。', '', '去找瘟疫之地：血色禁地的凱雷希斯親王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12720 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12720, 'zhTW', '如何影響敵人，獲得朋友', '我在世界各地漫遊的時候發現了幾個有趣的東西。舉例來說，你知道要多少鼓勵才能讓一個人把隱藏的秘密全部說出來嗎?很幸運的，我剛好手上有些能夠鼓勵人的東西。$B$B<凱雷希斯從一個華麗的珠寶盒裡拿出某樣東西。>$B$B這是我的「說客」。裝上它們，然後前往原野，死亡騎士。把尖端對準新亞法隆的士兵使用。查出這個「赤紅黎明」的真相。', '緬懷墓穴的凱雷希斯親王命令你去找出關於「赤紅黎明」的真相。把凱雷希斯說服者從華麗珠寶盒拿出來，然後用它們來「說服」血色十字軍吐實。', '「緋紅曙光」已揭露', '去找瘟疫之地：血色禁地的凱雷希斯親王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12721 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12721, 'zhTW', '暴怒', '$n，沒有時間了。你一定得拿這把鑰匙去解開阿卡利的縛鎖。$B$B他被固定在祖爾德拉克的首都，剛德拉克前方的庭院裡。阿卡利的鎖鍊被四個錨點所固定。你必須將他們一一解開，釋放犀牛神。$B$B剛德拉克裡面滿是寒冰食人妖。然而，我相信如果你夠小心的話，應該能夠偷溜進去，不會遇到太多危險。$B$B一旦你成功了，請通知巫醫。', '辛托加的哈寇亞要你釋放阿卡利，然後到辛托加通知巫醫庫弗。', '阿卡利已擺脫枷鎖', '去找祖爾德拉克的巫醫庫弗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12722 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12722, 'zhTW', '待宰羔羊', '當天譴軍的亡域佔據了天空的時候大部分的人類都會望風而逃。但血色十字軍卻不會!$B$B我必須坦承 - 我比較享受和十字軍的交流。雖然這些年來天譴軍隊他們的攻擊製造了人類史上最慘的數起悲劇，但我們又 - 再次 - 陷入戰鬥!$B$B我們該讓他們享受永遠服侍巫妖王的喜悅!進入新亞法隆，並且滿足他們的赴死之願吧。不要留下任何活口。', '緬懷墓穴的瑞文戴爾男爵命令你殺死10個血色十字軍士兵和15個新亞法隆市民。', '', '去找瘟疫之地：血色禁地的瑞文戴爾男爵。', '血色十字軍士兵已擊殺', '新阿瓦隆的居民已擊殺', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12724, 'zhTW', '正義十字軍之道', '關於這個信差會在哪裡出現，我們一點該死的頭緒也沒有。這些人類也沒有人能夠給我個答案。$B$B<歐貝茲指著橫屍地面的五個血色十字軍。>$B$B不過我確實有從最後一個傢伙身上搾出些有用的情報來。他們在血色堡裡有張日程表，記錄了所有巡邏的路線。我要你潛入堡壘把那張日程表偷出來。$B$B血色堡就是新亞法隆最大的那棟建築，就在東北方。', '新亞法隆，血色旅店的歐貝茲‧血禍命令你去血色堡偷取新亞法隆巡邏日程表。', '', '去找瘟疫之地：血色禁地的歐貝茲‧血禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12726 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12726, 'zhTW', '風與水之歌', '聆聽了風暴，是嗎?風暴工匠沙洲迴響著古老的歌...風與水之歌。$B$B吞噬掉颱風與風暴之子的偉大暴風雨。拿這個鼓去演奏他的歌...演奏駭風的歌。$B$B幫忙用風與水餵養他，讓暴風雨繼續下去。', '蘇-睨要你到風暴工匠沙洲用暴風雨之鼓幫助駭風吞噬3個風暴亡魄和3個水漾之靈。', '', '去找索拉查盆地的神諭者蘇-睨。', '已吞噬水靈', '風暴亡魂已吞噬', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12727 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12727, 'zhTW', '血腥突圍', '警報已經響了。高階審判官和他的侍僧很快就會趕來。我傷得太重了，幫不上什麼忙，但我會盡我所能。$B$B殺死高階審判官和他的好朋友。把他的頭扯下來，帶去找薩沙理安。復仇會安撫他憤怒的靈魂。$B$B還有一件事，$n。如果你成功活下來，而且回到薩沙理安身邊，告訴他，他們在禮拜堂那邊處決囚犯。也許他會再派你去那裡扮演英雄。', '殺死高階審判官瓦羅斯，把瓦羅斯的頭顱帶去給血色旅店的薩沙理安。血色旅店位於新亞法隆。', '', '去找瘟疫之地：血色禁地的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12728 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12728, 'zhTW', '監控裂口:冬鰭洞窟', '我必須要整匯我的筆記，並且準備一份回達拉然給我同事的報告。$B$B當我在進行這些事的時候，我必須要求你去北邊的冬鰭洞窟。你必須站在洞口裡面使用奧能檢測儀。$B$B一旦取得資料之後立刻回來找我。沒有它，我的資料就不夠齊全。', '琥珀岩臺的圖書管理員加倫要你在冬鰭洞窟使用奧能檢測儀。', '', '去找北風凍原的圖書管理員加倫。', '已取得冬鰭洞窟讀數', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12729 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12729, 'zhTW', '諸神已然開口', '諸神已然開口，而我們必須回應祂們的睿智。$B$B把你的朋友召集起來吧，$N。帶著他們到北邊的辛茹克去殺死那裡的守護者，直到得到一顆無瑕疵的心臟。帶著他們到東南邊的奎茲倫祭壇去瓦解祭壇守望者，直到取得他們的陣風精華。$B$B把兩者都送去給哈寇亞，她將會把它們結合成一樣物品，能夠強迫死去阿卡利的預言者現身。', '將無瑕疵的守護者之心和守望者的陣風精華送去給辛托加的哈寇亞。', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12730 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12730, 'zhTW', '佐爾希伯的召集', '你和你的夥伴必須把這個召集裝置，或者說召喚裝置，拿去剛德拉克南方的佐爾希伯。$B$B你會在裡面找到一個法陣。使用召集裝置強迫阿卡利得預言者現身。$B$B我心與你同在，$N。我們共同經歷了這麼多事，你不但盡力拯救了我的性命，還幫助了其他被德拉克瑞食人妖毀滅的神。$B$B但這次，我擔心我們也許要在彼世才能再會了。', '辛托加的哈寇亞要你殺死阿卡利預言者。', '', '去找祖爾德拉克的哈寇亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12732 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12732, 'zhTW', '心臟血液的力量', '總有一天，瑞傑克會成為偉大的戰士。血液和天火將會使瑞傑克變強。你很快就會見識到。瑞傑克給你瓶子，你拿去西邊遠方日觸之柱的頂端，然後把水裝進瓶子裡。$B$B然後去盆地的北端，白骨原野北邊的岩臺。你去找血爪族母然後殺掉牠。拿走牠的心臟之血。$B$B你把心臟之血和水混合在一起，拿給瑞傑克。瑞傑克喝下它，就會變強。', '將一份日觸心臟血液交給狂心之丘的瑞傑克。', '', '去找索拉查盆地的瑞傑克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12733 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12733, 'zhTW', '死亡挑戰', '源自於巫妖王在冰凍荒原深處擊敗伊利丹‧怒風所獲得的勝利，死亡挑戰是所有死亡騎士都必須進行的一項晉升儀式。$B$B找出另一個亞榭洛死亡騎士並且向他要求決鬥。他們一定得接受，並且戰到勝利降臨為止!$B$B現在就動身，$n!為天譴軍團贏得勝利!向巫妖王獻上榮耀!', '『戰鬥召喚者』歐魯命令你與5個死亡騎士決鬥並獲得勝利。你可以選擇與死亡騎士新兵或玩家作戰。', '', '去找瘟疫之地：血色禁地的『戰鬥召喚者』歐魯。', '已在決鬥中擊敗死亡騎士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12734 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12734, 'zhTW', '瑞傑克:第一滴血', '瑞傑克剛剛成為狂心部族最年輕的戰士。爸爸給了瑞傑克一把強大的劍，要用來打敗狂心部族的敵人，但是傳統習慣說要先把劍沾血。老戰士通常都這麼做。你替瑞傑克做這件光榮的事好嗎?$B$B拿這把劍，插進所有狂心敵人的屍體中:西南邊的黃蜂和硬拳，還有大舌頭。也許還要沾霧語者的血，在西北方遠處，靠近惡潮湖的地方。', '用狂心之丘黃蜂、硬拳衝鋒者、3個霧語族的成員的屍體讓瑞傑克之刃飲血。不論是霧語神諭者或霧語戰士都可以。當你完成了任務之後，回去狂心之丘找瑞傑克。', '', '去找索拉查盆地的瑞傑克。', '已在藍寶石蜂巢黃蜂身上見血', '已在鐵拳衝鋒者身上見血', '已在迷霧低語成員身上見血', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12735 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12735, 'zhTW', '淨化之歌', '休拉薩的土地是純淨的。巨柱群保護了這片大地幾百年。$B$B水，則不夠純淨，因為它是從休拉薩外面來的...從海洋、湖泊、以及河流而來。水有的時候會帶來不好的靈魂-必須淨化的靈魂。$B$B你把這個排鐘拿到惡潮湖、冬握河、還有大河之心去彈奏。它會讓壞靈魂生起氣來...然後你得殺了它們。', '雨頌者之蓬的蘇-睨要你在惡潮湖、冬握河、還有大河之心彈奏淨化排鐘，然後殺死污染水源的邪惡靈魂。', '', '去找索拉查盆地的神諭者蘇-睨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12736 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12736, 'zhTW', '冥思之歌', '你當然沒有戈洛克聰明!你只是頭腦簡單的$r。$B$B但你也不是毫無希望!你表現出你的學習能力了。也許水晶可以把你變聰明，就像水晶把我們變聰明了一樣!$B$B我教你能夠清靜心靈的歌。你到水晶旁邊演奏歌曲，然後水晶就會讓你的腦袋更好...沒辦法跟戈洛克一樣好，但是會比你現在好。活血之柱已經斷了，但其他的柱子還是好的!', '雨頌者之蓬的蘇-睨要你在微光之柱、日觸之柱、苔光之柱和擎天之柱的頂端使用冥想長管笛。', '', '去找索拉查盆地的神諭者蘇-睨。', '在微光之柱沉思', '在苔光之柱沉思', '在觸天之柱沉思', '在陽光之柱沉思', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12737 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12737, 'zhTW', '豐饒之歌', '風暴是一種毀滅性的力量。風暴會燒掉樹。風暴會淹掉房子。$B$B但如果你知道正確的曲子，風暴也可以是一種生命的力量。在造物者棲所上面的風暴工匠沙洲，你可以找到一些小土堆。這些土堆很肥沃--裡面有種強力的種子。他們一直在等待一首正確的歌曲。$B$B你帶著這個號角，然後為它們演奏這首歌。', '雨頌者之蓬的蘇-睨要你前往造物者棲所西北邊的風暴工匠沙洲，並在8堆濕潤的肥沃土堆附近演奏豐饒號角。', '', '去找索拉查盆地的神諭者蘇-睨。', '已演奏豐饒之歌', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12739 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12739, 'zhTW', '特別驚喜', '我們來到這裡，夷平了整個地方，然後前往牢房。我們倒是沒想到會看到那種景象，$n。看來十字軍真的很忙。整間牢房都塞滿了銀色黎明的囚犯。大多數在我們抵達的時候都已經死了，但還有一些人還有呼吸。$B$B我本來要進去把他們通通處決掉，但我認為這個榮耀應該歸於你手中。尤其是有個很吵鬧的牛頭人，我想你一定會很樂於親手行刑的。', '赤紅之焰禮拜堂的騎士指揮官瘟疫之拳命令你處決附近牢房裡關押的銀色黎明囚犯，瑪拉‧勇角。', '', '去找瘟疫之地：血色禁地的騎士指揮官瘟疫之拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12740 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12740, 'zhTW', '給銀白十字軍的降落傘', '那些天空之懼一直在屠殺我的手下!摔死是一種恐怖的死法。$B$B$c，你得把這些降落傘發給他們!這樣至少他們有機會可以奮力求生。', '銀白看臺的指揮官法爾斯戴夫要你替10個庭院裡的銀白十字軍或銀白盾侍裝備降落傘。', '', '去找祖爾德拉克的指揮官法爾斯戴夫。', '已為銀色部隊裝備降落傘', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12741 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12741, 'zhTW', '暴風的力量', '笨大舌頭以為對雲唱歌就可以給他們帶來力量。瑞傑克來告訴這些大舌頭怎麼取得力量，去搶!$B$B西北邊遠方，有個很大、很平坦的地方，大舌頭管它叫「風暴工匠沙洲」。瑞傑克確定你只能像鳥一樣用飛的才能到達那裡。$B$B瑞傑克聽說在這個沙洲有強大的風和水之力。為了他們做的壞事殺死他們，然後把它帶去大舌頭的「暴風雨聖壇」，在沙洲西邊。瑞傑克會等你帶著終極的力量回來。', '收集3個季風精華和3個風暴精華，然後帶去暴風雨聖壇。帶著暴風雨的真實力量回去狂心之丘找瑞傑克。', '', '去找索拉查盆地的瑞傑克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12742 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12742, 'zhTW', '特別驚喜', '我們來到這裡，夷平了整個地方，然後前往牢房。我們倒是沒想到會看到那種景象，$n。看來十字軍真的很忙。整間牢房都塞滿了銀色黎明的囚犯。大多數在我們抵達的時候都已經死了，但還有一些人還有呼吸。$B$B我本來要進去把他們通通處決掉，但我認為這個榮耀應該歸於你手中。尤其是有個很吵鬧的人類，我想你一定會很樂於親手行刑的。', '赤紅之焰禮拜堂的騎士指揮官瘟疫之拳命令你處決附近牢房裡關押的銀色黎明囚犯，艾倫‧史坦布利吉。', '', '去找瘟疫之地：血色禁地的騎士指揮官瘟疫之拳。', '', '', '', '', 0);
