INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12744, 'zhTW', '特殊的憐憫', '我們來到這裡，將這個地方夷為平地，然後向牢房走去。在那裡看到的一切完全出乎我們的意料，$N。看來血色十字軍真是很忙碌。那裡塞滿了銀色黎明的俘虜，當我們到達的時候，其中的大部分人都已經感染瘟疫死去了，但少數人還有呼吸。$B$B裡面有一個矮人，他感染了瘟疫，已經活不長了。去結束他的痛苦吧。', '赤色烈焰禮拜堂的騎士團指揮官普雷菲斯特希望你去探視牢房裡的銀色黎明俘虜，多諾凡·普弗斯特，並結束他的痛苦。', '', '去找東瘟疫之地：血色領地的騎士團指揮官普雷菲斯特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12745 AND `locale` = 'zhTW';
