INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12750, 'zhTW', '特別驚喜', '我們來到這裡，夷平了整個地方，然後前往牢房。我們倒是沒想到會看到那種景象，$n。看來十字軍真的很忙。整間牢房都塞滿了銀色黎明的囚犯。大多數在我們抵達的時候都已經死了，但還有一些人還有呼吸。$B$B我本來要進去把他們通通處決掉，但我認為這個榮耀應該歸於你手中。尤其是有個很吵鬧的被遺忘者，我想你一定會很樂於親手行刑的。', '赤紅之焰禮拜堂的騎士指揮官瘟疫之拳命令你處決附近牢房裡關押的銀色黎明囚犯，安東尼‧布瑞克。', '', '去找瘟疫之地：血色禁地的騎士指揮官瘟疫之拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12754 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12754, 'zhTW', '瞰臺伏擊', '當你在外面火燒禮拜堂和屠殺害蟲的時候，我忙著制訂一個計畫。$B$B血色信差預計會在這小時內通過血色瞰臺。瞰臺旁邊的道路非常空曠，而且擠滿了十字軍。穿上這個臨時用偽裝，然後躲在瞰臺等待血色信差通過。等他夠接近你的時候，就以滿心的狂怒襲擊他!砍倒他，然後把他的所有物通通拿走 - 包括他的衣服!$B$B那個瞰臺就在此地東方兩百步之處。', '位於新亞法隆中，血色旅店內的歐貝茲‧血禍命令你殺死血色信差並取回血色信差的所有物，以及血色信差的信息。', '', '去找瘟疫之地：血色禁地的歐貝茲‧血禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12755 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12755, 'zhTW', '與命運相見', '這封信一定得送到阿比迪斯手上。我不想引起他們的懷疑。得讓他們繼續認為事情都和他們計畫的一樣。$B$B你要披上血色信差的衣服，然後藉由黑暗魔法的幫助，化成信差的外型。$B$B阿比迪斯就在國王港，位於血色瞰臺的東南方。把信息送過去，然後盡可能的從她身上挖出情報來。她得告訴我們關於「赤紅黎明」的事情。', '歐貝茲‧血禍命令你把血色信差的信息送去國王港給大將軍阿比迪斯。', '', '去找瘟疫之地：血色禁地的大將軍阿比迪斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12756 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12756, 'zhTW', '血色突襲軍出線', '聽好了，信差。血色大地已經陷落了。新亞法隆和避風郡被天譴軍團佔領。死亡的鬼靈在頭頂上逼近，威脅隨時侵襲我們。$B$B帶著這個信息回去給嘉爾瓦:$B$B「帶著你的軍團轉向，備船前往冰凍荒原。下次我們見面的地方將會是在北裂境。」$B$B把這個交給嘉爾瓦。$B$B<阿比迪斯交給你一本日誌。>$B$B這會解釋一切。$B$B血色十字軍已經消失了。血色突襲軍萬歲!', '將「救贖之途」帶到新亞法隆的血色旅店交給歐貝茲‧血禍。', '', '去找瘟疫之地：血色禁地的歐貝茲‧血禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12757 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12757, 'zhTW', '血色軍隊迫近...', '我們一定要對入侵的軍隊做好準備，$n。你要將你的發現立刻告訴大領主莫格萊尼!我會開啟一個傳送門直接通往亞榭洛。走進去，它就會立刻傳送你。$B$B把阿比迪斯的日記交給大領主莫格萊尼。他或許能找到它的用處。', '將救贖之途交給在亞榭洛:黯黑堡的大領主達利安‧莫格萊尼。', '', '去找黑鴉堡壘的大領主達瑞安‧莫格萊尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12758 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12758, 'zhTW', '英雄的頭盔', '瑞傑克在遙遠的風暴工匠沙洲聽到有關巨合金人的傳說。你可以在西北方，就在盆地邊緣外找到它。$B$B想像一下瑞傑克把巨合金人的頭當作頭盔。讓瑞傑克勢如破竹!讓瑞傑克力量強大!$B$B你去幫瑞傑克拿，不過合金頭可能不是那麼容易就可以跟合金身體分開。或許可以在日觸之柱附近的詐咧挖掘場裡從小綠人和他們朋友那拿到鐵炸彈?用炸彈把合金身體跟頭分開，然後帶來給瑞傑克。', '從詐咧挖掘場的風險投資公司裝置上取得風險投資公司爆裂物，使用它們來取得風暴看守者的頭顱。將風暴看守者的頭顱帶到狂心之丘交給瑞傑克。', '', '去找索拉查盆地的瑞傑克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12759 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12759, 'zhTW', '戰爭工具', '賽匹克說你或許是他見過最棒的戈洛克獵人了...除了賽匹克之外。西南邊的大戰還在持續中 - 你去幫忙。$B$B賽匹克保留了一些最大型，最厲害的陷阱在卡爾塔克堡的藏匿處...告訴費克嘎，叫他在戰爭中使用這些陷阱，那你也就可以使用它們了。去挑選你想要的陷阱，然後殺掉許多的大舌頭。$B$B非常非常多!', '從賽匹克在卡爾塔克堡的藏匿處中，取回一些陷阱。使用這些陷阱，屠殺附近50個炫觸戈洛克，然後回到卡爾塔克堡找薩滿賈克杰克。', '', '去找索拉查盆地的薩滿賈克杰克。', '電光魚人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12760 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12760, 'zhTW', '狂心的秘密力量', '卡爾塔克堡的戰鬥還在持續...我想也是時候讓你知道狂心的大秘密了。$B$B我們有從家鄉帶來的莓子...它們本身沒什麼特別的，但是跟醉醉飲料混在一起喝就會讓狂心變超級強，你現在是個狂心族了...輪到你變強了。$B$B我給你一些酒，然後你就會變得超級強，然後去把所有的炫觸大舌頭打扁。', '喝下狂心秘密飲料，在卡爾塔克堡附近殺死30隻炫觸戈洛克。', '', '去找索拉查盆地的薩滿賈克杰克。', '電光魚人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12761 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12761, 'zhTW', '水晶精通', '炫觸依舊被小狗人攻擊...我們想，如果我們不阻止他們，他們大概就不會停手了。雖然我們有個秘密武器...我們把它送給了蘇-邁特，好讓他用來保護所有的神諭者。$B$B秘密武器是來自於大神...神聖的大神聖壇裡找到的超閃亮水晶。要小心...不要打破了。$B$B水晶就在西南方遠處，靠近炫觸避風港的地方有個聖壇，就在箱子裡。你要使用水晶幫助蘇-邁特打敗小狗人。', '前往炫觸避風港並且取得水晶防護。使用水晶防護殺死附近的50隻狂心獾狼怪。等這些工作都完成，回去找炫觸避風港的喚雷者蘇-邁特。', '', '', '狂心攻擊者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12762 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12762, 'zhTW', '偉大諸神的力量', '我們得做些事來阻止小狗人繼續攻擊炫觸炫觸避風港。賈露特把他在大河之心某處找到的一種超級特別的水晶拿來給我...我們以前看過這種水晶，我們認為它應該可以解決我們的煩惱。$B$B這個水晶現在還沒有力量，但是如果夠靠近的話，那個露天的活血之柱應該能夠幫它重新充飽能量。一旦水晶充能完成，就去西南邊遠方的炫觸避風港利用水晶的能量讓你變的又大又強。$B$B接著是踹小狗人屁股的時間了。', '利用暴露出來的活血之柱替休眠拋光水晶充能。前往炫觸避風港，用水晶給你的能量殺死30個附近的狂心獾狼怪，然後把你的成果告訴炫觸避風港的喚雷者蘇-邁特。', '', '', '狂心攻擊者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12764 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12764, 'zhTW', 'The Secret to Kungaloosh (DEPRECATED)', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12765 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12765, 'zhTW', 'Kungaloosh (DEPRECATED)', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12771 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12771, 'zhTW', '鐵爐堡', '聖光響應了我們的祈禱！依靠撒塔斯城的納魯所賜予的聖光精華，以及虔誠信徒的祈福，我們終於創造出了神聖而強大的聖物，這些聖物將成為我們對抗巫妖王的利器。$B$B帶上這個，$n。你要仔細保護它，把它安全地送到鐵爐堡。麥格尼·銅鬚急於轉至北裂境參戰，這件聖物可以説明他達成目標。', '拉莎莉爾主教要你將光明聖物交給鐵爐堡的國王麥格尼·銅鬚。', '', '到鐵爐堡找國王麥格尼·銅鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12773 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12773, 'zhTW', '達納蘇斯', '我們的祈禱得到了回應!我們利用來自撒塔斯那魯的聚合聖光，以及虔誠信徒所獻上的祈禱，創造了擁有深奧力量的神聖法器。這些法器將會成為我們對抗巫妖王陰謀的武器。$B$B帶著這個，$n。看緊它，將之確實送抵達納蘇斯。把它送去給泰蘭妲‧語風 -- 她的牧師們將會發現這是她們與來自北方的邪惡勢力交戰的關鍵力量來源。', '主教拉札利爾要你把聖光灌注神器送去給達納蘇斯的泰蘭妲‧語風。', '', '去達納蘇斯找神殿花園的泰蘭妲·語風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12774 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12774, 'zhTW', '暴風城', '我們的祈禱得到了回應!我們利用來自撒塔斯那魯的聚合聖光，以及虔誠信徒所獻上的祈禱，創造了擁有深奧力量的神聖法器。這些法器將會成為我們對抗巫妖王陰謀的武器。$B$B帶著這個，$n。看緊它，並安全地將它送達暴風城。暴風城之王已經回來了。我相信他會很樂於見到這個。', '主教拉札利爾要你把聖光灌注神器送去給暴風城的安杜因‧烏瑞恩國王。', '', '去找艾爾文森林的瓦里安·烏瑞恩國王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12776 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12776, 'zhTW', '艾克索達', '聖光響應了我們的祈禱！依靠撒塔斯城的納魯所賜予的聖光精華，以及虔誠信徒的祈福，我們終於創造出了神聖而強大的聖物，這些聖物將成為我們對抗巫妖王的利器。$B$B帶上這個，$n。你要仔細保護它，把它安全地送到艾克索達，交給聖光穹頂的先知維倫。他可以借用聖物的力量對抗阿薩斯的邪惡部隊。', '拉莎莉爾主教要你將光明聖物交給艾克索達的維倫。', '', '到艾克索達找先知維倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12777 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12777, 'zhTW', '絕望的聯軍', '親愛的$n，巫妖王在用疾病和侵略折磨著我們——部落和聯盟都深受其害。只有艾澤拉斯的這兩個偉大文明聯手，才有可能擊敗他。$B$B我們在撒塔斯城的聖光廣場結成了聯軍。$B$B為了幫助我們對抗巫妖王，請你到聖光廣場的新聯盟營地去，和拉莎莉爾主教談一談。$B$B願聖光保佑你，$n。', '到撒塔斯城的聖光廣場去，與新聯盟營地中的拉莎莉爾主教談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12779 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12779, 'zhTW', '萬事萬物的終結...', '你已經屠殺了無數的部隊，但你黑暗的心靈卻渴望著更多。你的飢渴永遠也沒有滿足的一天，$n。<巫妖王停頓了一下。>$B$B所有事物都需要終結，死亡騎士。血色十字軍對我們發動了最後的攻勢。對他們而言，已經沒有退路...沒有選擇。也因此他們會以你從未見識過兇殘來戰鬥。$B$B用這個號角來召喚我麾下的一頭巨龍。爬上它的背並指揮它進入戰鬥。靠著它你將會終結血色十字軍。', '巫妖王命令你徹底滅絕血色十字軍。使用霜育號角召喚一隻霜育鎮壓者，殺死150名血色士兵和摧毀10台血色弩砲。避開他們的彈道以閃躲來襲的砲火!', '', '去找瘟疫之地：血色禁地的巫妖王。', '血色士兵已擊殺', '血色投石車已摧毀', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12781, 'zhTW', '歡迎!', '歡迎來到魔獸世界!$B$B為了感謝您購買《魔獸世界》典藏版，請將這張禮券交給黯黑堡的『女妖』席厄克希。您將得到一份特別的禮物:陪伴您踏上冒險旅途的小夥伴!$B$B再次感謝您的支持，請盡情享受魔獸世界的樂趣吧!', '將黯黑堡禮品券交給黯黑堡的『女妖』席厄克希。', '', '去找『女妖』席厄克希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12785 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12785, 'zhTW', '奧格瑪', '我們有了突破性的發現!我們的殭屍樣本讓我們對天譴瘟疫的本質有了新的認識。他們結出了腐爛，甜美的果實...$B$B把這個盒子帶往奧格瑪，盒子裡面是一顆被殭屍瘟疫感染的頭顱，當然還有一些其他我們發明出的東西 -- 一種反式瘟疫。這兩種瘟疫在殭屍的腦袋中不斷對抗，而這顆頭顱正是解藥的關鍵，這我很確定。$B$B把這個盒子帶給我的助手，藥劑師卡洛孚，他在奧格瑪替大酋長索爾服務。', '大藥劑師普崔司要你把這顆雙重染疫的大腦交給奧格瑪的藥劑師卡洛孚。', '', '去找奧格瑪的藥劑師卡洛孚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12786 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12786, 'zhTW', '雷霆崖', '我們有了突破性的發現!我們的殭屍樣本讓我們對天譴瘟疫的本質有了新的認識。他們結出了腐爛，甜美的果實...$B$B把這個盒子帶往雷霆崖，盒子裡面是一顆被殭屍瘟疫感染的頭顱，當然還有一些其他我們發明出的東西 -- 一種反式瘟疫。這兩種瘟疫在殭屍的腦袋中不斷對抗，而這顆頭顱正是解藥的關鍵，這我很確定。$B$B把這個盒子帶給我的助手，鍊金師夏睨，他在雷霆崖上替瑪加薩‧恐怖圖騰服務。', '大藥劑師普崔司要你把這顆雙重染疫的大腦交給雷霆崖的鍊金師夏睨。', '', '去莫高雷找雷霆崖的藥劑師夏睨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12787 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12787, 'zhTW', '幽暗城', '殭屍瘟疫實際上是個隱藏的祝福。在我們尋找解藥的研究中，我們學習到許多與天譴軍與他們的傳染病相關的知識。我們的研究賦予了我們對付他們的武器。武器，還有工具...$B$B拿著這個 -- 這是一顆殭屍的腦袋，我們從近來的發現中取得的化合物裡面，注射進這顆頭顱中，使得它有一部分被治癒了。將這顆頭顱送給藥劑大師法拉尼爾;我有一整列張表的實驗等著他拿這個頭來做。', '大藥劑師普崔司要你把這顆雙重染疫的大腦交給幽暗城的藥劑大師法拉尼爾。', '', '去找奧特蘭克山脈的藥劑大師法拉尼爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12788, 'zhTW', '銀月城', '我們有了突破性的發現!我們的殭屍樣本讓我們對天譴瘟疫的本質有了新的認識。他們結出了腐爛，甜美的果實...$B$B把這個盒子帶往銀月城，盒子裡面是一顆被殭屍瘟疫感染的頭顱，當然還有一種我們發明出的東西 -- 一種反式瘟疫。這兩種瘟疫在殭屍的腦袋中不斷對抗，而這顆頭顱正是解藥的關鍵，這我很確定。$B$B把這個盒子帶給我的助手，藥劑師提琵希。她在銀月城替洛索瑪‧塞隆服務。', '大藥劑師普崔司要你把這顆雙重染疫的大腦交給銀月城的藥劑師提琵希。', '', '去找銀月城的藥劑師提琵希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12790, 'zhTW', '學習來去之法:魔法通道', '怕你還不知道，你可以使用我身後平臺的水晶傳送至達拉然下方，水晶之歌森林中的紫羅蘭看臺。$B$B同樣地，你也可以使用遺跡的水晶回到我上頭的房間。$B$B我希望你可以現在試試看。', '位於達拉然裡紫羅蘭之門的大法師瑟琳卓，希望你使用傳送至紫羅蘭看臺的水晶以及傳送至達拉然的水晶。', '', '去找達拉然的大法師瑟琳卓。', '已使用紫羅蘭崗哨傳送水晶', '已使用達拉然傳送水晶', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12791, 'zhTW', '魔法王國達拉然', '嗨，$n。你可能有注意到，也可能沒注意到，我們祈倫托把我們的城邦移到了北裂境這裡來。$B$B達拉然再也不會待在洛丹米爾湖畔的保護罩裡面了。現在這個城市靠著魔法漂浮在水晶之歌森林的上方。$B$B我們相信你已經準備好要前往城市了。再和我談一次話，我就會施展傳送法術把你送去那裡。$B$B當你抵達的時候，去找大法師瑟琳卓並且把我的徽記交給她，證明你和我談過。', '將祈倫托徽記交給位於達拉然裡紫羅蘭之門的大法師瑟琳卓。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12794 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12794, 'zhTW', '魔法王國達拉然', '嗨，$n。你可能有注意到，也可能沒注意到，我們祈倫托把我們的城邦移到了北裂境這裡來。$B$B達拉然再也不會待在洛丹米爾湖畔的保護罩裡面了。現在這個城市靠著魔法漂浮在水晶之歌森林的上方。$B$B我們相信你已經準備好要前往城市了。再和我談一次話，我就會施展傳送法術把你送去那裡。$B$B當你抵達的時候，去找大法師瑟琳卓並且把我的徽記交給她，證明你和我談過。', '將祈倫托徽記交給位於達拉然裡紫羅蘭之門的大法師瑟琳卓。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12796, 'zhTW', '魔法王國達拉然', '嗨，$n。你可能有注意到，也可能沒注意到，我們祈倫托把我們的城邦移到了北裂境這裡來。$B$B達拉然再也不會待在洛丹米爾湖畔的保護罩裡面了。現在這個城市靠著魔法漂浮在水晶之歌森林的上方。$B$B我們相信你已經準備好要前往城市了。再和我談一次話，我就會施展傳送法術把你送去那裡。$B$B當你抵達的時候，去找大法師瑟琳卓並且把我的徽記交給她，證明你和我談過。', '將祈倫托徽記交給位於達拉然裡紫羅蘭之門的大法師瑟琳卓。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12797 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12797, 'zhTW', '由甬道之門返回', '你說的是事實，$r。就連我們談話的這一刻我都能夠感覺到休拉薩盆地的本質正因不死荒疫而逐漸衰弱。$B$B我已經將我的存在跟這個符文連結在一起了，$r。把它交給派你來這裡的那個人手中 -- 因為只有她的力量才能夠打開進入她領地的通道。', '將終末符文帶回去休拉薩盆地交給雨頌者急湍的芙蕾雅化身。', '', '去找索拉查盆地的芙蕾雅的化身。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12798 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12798, 'zhTW', '眾劍套卡', '你現在集齊了整套的眾劍套卡，另一張卡片出現在套卡的上面。上頭描繪著一個占卜師，似乎無論你用什麼角度拿著套卡，他都一直盯著你看。$B$B你覺得這張卡片似乎可以用來跟什麼人溝通。', '使用眾劍套卡召喚一位暗月占卜師，然後把套卡交給他。', '', '去找暗月算命師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12799 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12799, 'zhTW', '吸取靈魂', '他們說，你應該對他的到來感到開心。他們說，你應該享受有他陪伴的時光...$B$B在這件事情上來說，我沒多大選擇餘地。芬克斯坦是十字軍陣中最優秀的鍊金師，我其實應該感到很光榮，因為他選擇我的崗哨建立商店。但是自從他來這裡以後，我就被抓去收集一大堆的材料。$B$B那麼，$r，幫個忙如何?就在南邊，有些池子被古老的食人妖靈魂給佔據了。幫我收集他們的魂能吧。', '希伯伐洛克的阿爾納斯上尉要你去薩金之池從迷失的德拉克瑞靈魂身上收集5個上古魂能。', '', '去找祖爾德拉克的阿爾納斯上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12801, 'zhTW', '黎明曙光', '銀色黎明大膽地在聖光之願禮拜堂與我們對抗。他們竟敢對抗天譴軍團，就為了這個理由，他們非被毀滅不可!$B$B巫妖王的大軍已經準備好面對瘟疫之地的最後一戰了。就在今天，我們將登上天譴英雄的不朽殿堂!$B$B當你準備好作戰的時候，向大領主達瑞安‧莫格萊尼報到。大領主將會發佈最終行軍的號令，並且在聖光之願禮拜堂率領我們的軍隊。', '擊敗銀色黎明的部隊，並且發現黎明曙光。要是你成功活了下來，就向大領主達瑞安‧莫格萊尼報告。', '', '', '拂曉之光已發現', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12804 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12804, 'zhTW', '適合獵人的肉排', '有些時候，一個塞滿了獵人的營地是再糟不過的地方了。他們全都忙著捕殺獵物，結果我只弄得到又硬又多筋的肉。這不會是你狩獵累了一天回家想吃到的東西。$B$B不過，幸運的是，附近有地方可以取得柔軟，多汁的肉。在營地和河川的南邊有些長頸食草者。他們就是咱們飢餓獵人的最佳食物來源。幫我帶些最棒的肉塊回來，然後我們就能夠好好款待我們的同志們。', '把5塊長頸食草者肉排帶回去奈辛瓦里營地給『斬擊者』寇爾格。', '', '去找索拉查盆地的『斬擊者』寇爾格。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12805 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12805, 'zhTW', '搶救生命之力', '活血之柱被巨力所擊倒，把那塊土地都翻了起來。$B$B在那破碎的裂片四周遊蕩的元素都蘊含著給予巨柱力量的生命精華。我不能眼看著這些能量被浪費掉，因為只剩下四個柱子了。$B$B前往東南方的破碎裂片，尋找活血元素。$B$B在它們殘留物上使用這個寶石來回收他們身上猛烈的能量。當這一切結束的時候，我們會需要這些能量來復原這片大地。', '芙蕾雅要你去東南方的破碎裂片，在8個被摧毀的活血元素身上使用生命之力寶石。', '', '去找索拉查盆地的芙蕾雅的化身。', '已回收生命之血能量', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12807 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12807, 'zhTW', '至今的故事...', '我們有很多事情得做，但首先，我想我們得先來個短暫的講習。$B$B我們死亡騎士和我們的血色老友有段精采的過去，而他們現在像白癡一樣地在西北方的港口裡舒適的休息著。$B$B當你準備好要聽故事的時候，就再次和我談話。我會為你啟蒙。', '在死亡高崗聽取指揮統領艾睿特的故事。', '已聆聽將軍阿雷特的故事', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12809 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12809, 'zhTW', '鐵爐堡', '聖光響應了我們的祈禱！依靠撒塔斯城的納魯所賜予的聖光精華，以及虔誠信徒的祈福，我們終於創造出了神聖而強大的聖物，這些聖物將成為我們對抗巫妖王的利器。$B$B帶上這個，$n。你要仔細保護它，把它安全地送到鐵爐堡。地精區的高等技工梅卡托克正在期待著借助聖物的力量為聯盟效力。', '拉莎莉爾主教要你將光明聖物交給鐵爐堡的高等技工梅卡托克。', '', '到鐵爐堡找高等技工梅卡托克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12810 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12810, 'zhTW', '水中之血', '在突襲軍港口的部隊因為獅鷲騎士的增援而實力大增。你需要一隻坐騎才能對付他們。但首先，我們需要一些材料來準備儀式。$B$B要著手進行儀式我們會需要大量的血液。$B$B<指揮統領把手指向西北方。>$B$B在港口底下有個相當豐富的來源...鯊魚。在沒有把囊袋裝滿血液之前別回來找我。', '死亡高崗的指揮統領艾睿特要你用血囊裝滿10隻極餓的大白鯊的鮮血。', '', '去找寒冰皇冠的指揮統領艾睿特。', '已從貪婪之顎收集血液', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12812, 'zhTW', '奧格瑪', '終於有重大突破了！我們的僵屍樣本在天災的影響下產生了新的特性，並結出了豐碩的果實……$B$B把這只盒子帶到奧格瑪去。裡面是一枚帶有僵屍疫病的徽記，上面還有我們添加的其它東西——一種反藥劑。這兩種將在徽記上相互作用，而我敢肯定，這枚徽記就是治癒疫病的關鍵。$B$B把這只盒子交給我的助手，藥劑師卡爾洛夫。他就在奧格瑪的索爾酋長身邊。', '大藥劑師普特雷斯要求你將雙天災腦質交給奧格瑪的藥劑師卡爾洛夫。', '', '到奧格瑪找藥劑師卡爾洛夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12813 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12813, 'zhTW', '從他們的屍體上復甦!', '多麼仁慈...我們的指揮統領多麼的大方啊。他身處花朵與陽光之中，而我的心中卻只充滿著仇恨。$B$B光是結束他們可悲的性命還不夠...我要他們受到羞辱...受到貶低。$B$B還有什麼比被轉變成自己最痛恨的東西更令人啞口無言的呢?把全副身心都奉獻出來，只為了消滅一樣東西，然後，最後卻變成了它?$B$B多哀傷啊。$B$B把這份酊劑帶去西北邊的突襲軍港口。用在那些僵直的屍體上，然後看著接下來發生的一切;但記得避開教堂。', '死亡高崗的瑟塔爾‧暗癒者給了你暗癒者的酊劑。把它用在10具突襲軍港口的血色突襲軍屍體上。', '', '去找寒冰皇冠的瑟塔爾‧暗癒者。', '血色十字軍屍體已轉化', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12814 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12814, 'zhTW', '你會需要一頭獅鷲獸', '有什麼比用他們自己的獅鷲獸來對付他們更適合的呢?前往突襲軍港口，從獅鷲騎士死僵的手中奪取韁繩。$B$B把牠帶回來這裡，送去給烏佐‧喚死者。他會讓牠們進行適當的轉變，然後給你進一步的指示。', '將一頭突襲軍獅鷲獸送到死亡高崗的烏佐‧喚死者手中。', '', '去找寒冰皇冠的烏佐‧喚死者。', '十字軍獅鷲已交給烏索·喚死者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12815 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12815, 'zhTW', '禁航區', '既然你有了骸骨獅鷲獸，我要你每天把它帶到底下，在突襲軍港口上空製造一個禁航區。$B$B我得承認，老兄，我一點也不介意你是否用骸骨獅鷲獸殺死他們的獅鷲騎士，但是我猜如果你真的要這麼做，你會發現這樣比較輕鬆就能接近他們。$B$B還有，骸骨獅鷲獸可以讓你使用許多方便的把戲。', '死亡高崗的烏佐‧喚死者要你殺死10個突襲軍獅鷲騎士。', '', '去找寒冰皇冠的烏佐‧喚死者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12816 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12816, 'zhTW', '調查銀月城的天譴軍團', '巫妖王把他的不死生物派到我們的門口，我們不能坐視不管！你一定會站出來保衛銀月城不受可惡的入侵者騷擾吧？$B $B外面有些奇怪的符文法陣，散發著和周圍不死生物與亡域上同樣的能量。它們有一定的重要性，我肯定，而且我要你去調查出來。削減那些該死生物的數量，把它們死亡的證據和調查結果帶來給我，我就會獎勵你。去吧！', '從銀月城外的天譴軍團身上，收集三個暗淡的亡域之石，並調查它們營地附近發光的符文法陣。', '調查一個法陣', '去找永歌森林的朱雷克中尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12817 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12817, 'zhTW', '調查艾克索達的天譴軍團', '巫妖王把他的不死生物派到我們的門口，我們不能坐視不管！你一定會站出來保衛艾克索達不受可惡的入侵者騷擾吧？$B $B外面有些奇怪的符文法陣，散發著和周圍不死生物與亡域上同樣的能量。它們有一定的重要性，我肯定，而且我要你去調查出來。削減那些該死生物的數量，把它們死亡的證據和調查結果帶來給我，我就會獎勵你。去吧！', '從艾克索達外的天譴軍團身上，收集三個暗淡的亡域之石，並調查它們營地附近發光的符文法陣。然後回去找克瑞格中尉。', '調查法陣', '到艾克索達找克雷格爾上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12818, 'zhTW', '清理', '直接講重點…瑞基特要我組裝一些更強力的地雷，但是我的零件快不夠用了。$B$B在城鎮的西邊，你可以找到上一艘火箭雪橇的殘骸…瑞基特在替它加油的時候可能有點太興奮了，但是也許我早該想到不能把噴嘴放的太靠近排氣孔。活到老，學到老啊，嗯?$B$B在雪橇的殘骸附近應該有很多多餘的零件…你何不去那裡趕跑那些拾荒者，然後替我搶點殘骸來呢?', 'K3的吉爾·炫臼想要10塊燒焦的殘骸。', '', '去找風暴峭壁的吉爾·炫臼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12819, 'zhTW', '危機四伏', '該死!我的工具在哪裡?我不久前才看到它們在這的啊。$B$B噢!也許我在西邊佈雷的時候把它們忘在那裡了。這可真有點不方便。如果你能去幫我把它們拿來的話我會很感激的。但你得小心你的腳步...你應該能走我走出來的那條路進去吧。$B$B喔，不要想用飛的進去...我機靈地架設了會把所有飛行物打下來防空塔台，它們可不會分辨目標的。', 'K3的吉爾‧炫臼希望能從他的地雷區取回炫臼的工具。', '', '去找風暴峭壁的吉爾·炫臼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12820 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12820, 'zhTW', '精巧的手法', '我等這些地雷等了一輩子!好吧，至少也等了好幾天。為什麼他花了那麼多時間?$B$B我們現在的困境是這樣，朋友...那裡有一大票的猛瑪象人 -- 你知道的，又黑又毛，而且長的奇醜 --牠們熱切地想要奪下K3。$B$B這可不會成真。$B$B我們在東北邊的路徑上設立了一些防禦。但很遺憾的是，我們的雷射塔能量有限...這就是地雷派上用場的時候了!去那兒把牠們給炸上天吧!', 'K3的瑞基特要求你，在迦姆之禍用強化地雷抵擋12個來自迦姆的攻擊者。迦姆入侵者與雪盲跟隨者，都算在目標之內。', '', '去找風暴峭壁的瑞基特。', '加姆攻擊者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12821, 'zhTW', '能量爆發', '工兵小隊準備好啦！$B$B意思是說，享樂的時刻到啦！$B$B只剩一件事情阻擋著我們全面進攻迦姆而已！我派了一個信差到他的後方建立傳送器…而且成功了…但他卻回來拿傳送器運作所需的能量電池。傳送器還是沒運作…也就是說能量電池沒能抵達目的地。$B$B我要你去迦姆之禍的另一頭把能量電池找出來。找到以後，把電池帶去更東邊的迦姆高崗，然後啟動傳送器。', 'K3的瑞基特要你找出傳送器能量電池並用它來啟動迦姆高崗的傳送平臺。', '加姆傳送裝置已啟動', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12822, 'zhTW', '不知恐懼為何物', '現在我們打開了傳送器，我的計畫有點複雜...包含了許多面向，而且配合得天衣無縫。還得做好後勤準備!還要招募部隊!大概也得花上好幾個禮拜的時間!$B$B哈哈，我派你去那裡待了一陣，對吧?你獲派這個任務啦，小鬼。跳過傳送器，然後跟他們幹上一架!我們的工兵會支援你...他們將無路可逃。', 'K3的瑞基特要你殺死6個迦姆看守者與8個雪盲誓徒。', '', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12823, 'zhTW', '天衣無縫的計畫', '嘿你好!你是來加入突擊的對吧?$B$B我有項特別任務要給你...我們要把整個洞穴炸垮在牠們頭頂上!在牠們的洞穴後方，你可以找到霜膽的祭壇。偷溜進去把這個硬盒裝爆裂物裝在祭壇附近。$B$B一旦炸藥裝置好了，你得在附近待上一陣子，確定霜膽上鉤，然後快點逃出來!天知道要是爆炸了洞穴可以撐的了多久!', '迦姆高崗的基諾，要你把硬盒裝爆裂物裝置在霜膽的祭壇附近，然後殺死托爾瑪‧霜膽，在洞穴坍塌壓垮你之前逃出去。', '', '', '放置炸藥包', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12825 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12825, 'zhTW', '表達謝意', '[佔位文字] 使用迷你飛機對豺狼人首領實施自殺式衝撞。', '用迷你飛機神風特攻豺狼人領袖。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12826 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12826, 'zhTW', '輕微不穩定', '看起來不錯!$B$B不，不是說你 - 是說我的新地雷。你有點太自滿了，不是嗎?另一方面，我，絕對是才華洋溢的!我的智力可沒有人能比得上。$B$B我們在談什麼?哦對，我的新地雷!全新，而且更加進化...不管瑞基特想用來做什麼用途都可以。$B$B做個好$g孩子:女孩;，把它交給瑞基特，好嗎?她就在那兒...這應該是段史詩般的旅程，我很確定。不過小心點，她有些瘋瘋癲顛的。', '把吉爾的強化地雷送去給K3的瑞基特。', '', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12827 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12827, 'zhTW', '回收乾糧再利用', '嘿，嘿!你是新面孔!要不要幫瑞基特一個忙啊?$B$B我們有個預料外的問題…存糧不足。我知道，我知道…我們早該預料到有這麼一天，但你不懂。我們原本只是想要帶著工兵分隊迅速的在這邊繞一圈，就這樣，所以通常咱們不擔心長期食糧問題。但老K3似乎越來越熱鬧了。$B$B簡單的解決方案?西邊有個豺狼人營地，附近有些豺狼人在亂晃，有些到處在拾荒。能不能幫忙弄點他們的乾糧來?', 'K3的瑞基特，要你從附近的野生山丘豺狼人身上，回收16份風乾的豺狼人口糧。', '', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12828 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12828, 'zhTW', '豐沛的靈感', '哇!那東西可真是噁心。不是要替豺狼人的品味說話，只是不管他們吃的是什麼，至少是...可以吃的東西吧?$B$B讓我們更進一步地活用創意...$B$B托爾在城鎮北邊有個炸藥配給器...就在那個大洞穴的入口處附近，你不會看漏的。我相信她應該是要用那些炸藥來採礦什麼的，但我有個更好的點子。$B$B去拿一個炸藥來，然後扔向附近的長毛象...牠們大多分佈在西邊。收集那些肉，然後把肉帶回來。', 'K3的瑞基特要你拿一個U.D.E.D，然後用它把一頭長毛象炸碎，接著帶回8個營養的長毛象肉塊。', '', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12829 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12829, 'zhTW', '上前線', '嗨呀!我叫托爾。我要前往K3礦工作業的地點...我馬上就要去了!$B$B這個洞窟裡有好多毛骨悚然的東西。我想我們進去之前可以把蜘蛛的數量減少一點 - 你覺得怎麼樣?', '晶網洞窟外面的托爾‧滾鉗要你殺死12隻晶網蜘蛛。', '', '去找風暴峭壁的托爾‧滾鉗。', '水晶蛛網蜘蛛已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12830 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12830, 'zhTW', '重新獲得礦石', '我們要進去了!$B$B我們抵達的時候，裡頭有些極地狗頭人...然而他們的採礦行動似乎碰上了某種不幸的阻礙。這不打緊 - 反正我們很快就要接手礦坑了。$B$B我派了幾個礦工進去採取礦石樣本，好讓我用來校正器材，但是他們卻沒有回來。$B$B你不介意代替他們進去幫我弄點樣本出來吧?極地狗頭人可能抓了幾個礦工，不過我猜他們現在多半是死了。', '晶網洞窟外面的托爾‧滾鉗，要你取回5個不純淨的薩鋼礦石樣本。', '', '去找風暴峭壁的托爾‧滾鉗。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12831 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12831, 'zhTW', '只忘一半', '喂…我胃裡好像有個螺旋槳一樣。$B$B我想我走得動，但是從我在洞穴後方被某個生物咬了一下之後我就覺得身體裡面有個很糟糕的東西。那玩意比其他蜘蛛都來的大…而且色彩鮮豔。$B$B瑞基特可能可以替我做出解毒劑，但是她會需要咬我的那玩意身上的毒囊。你願意幫我找到它嗎?我不覺得托爾會來幫忙。$B$B我會躺在這裝死，希望他們不會來煩我。', '晶網洞窟中受傷的哥布林礦工要你從冰尖爬行者身上取得冰尖毒囊。', '', '去找風暴峭壁的受傷的哥布林礦工。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12832 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12832, 'zhTW', '苦澀的啟程', '喂 - 謝謝你!我以為我就要變成蜘蛛的點心了。也許我說的有點太早了 - 讓我們逃出這裡吧!$B$B當你準備好要出發了就跟我說一聲...但是請快點。', '護送受傷的哥布林礦工離開晶網洞窟，然後與K3的瑞基特交談。', '護送受傷的地精礦工前往K3', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12833 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12833, 'zhTW', '存貨過多', '又見面啦!你沒有像其他的冒險者一樣落跑啊?好吧，你真是個惹人愛的傢伙，不是嗎?我才正懷疑是不是我聞起來怪怪的還是怎樣?$B$B我們需要一點幫助，你的經驗正好可以派上用場。記得那些猛瑪象人嗎?顯然那個洞窟沒有完全倒塌...還有一小撮苟活著。基諾還說什麼有他就搞定了。$B$B幸虧，吉爾做的地雷數量遠超過所需。這個給你!', 'K3的瑞基特要求你，在迦姆之禍用強化地雷抵擋來自迦姆的攻擊者。迦姆入侵者與雪盲跟隨者，都算在任務目標的攻擊者內。', '', '去找風暴峭壁的瑞基特。', '加姆入侵者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12834 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12834, 'zhTW', '不是雨，也不是雪，也不是爆炸的飛機', '[佔位文字] 在巨人身上測試耐寒轟炸機。', '對巨人測試冷天氣炸彈。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12835 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12835, 'zhTW', '全部長大', '[佔位文字] 在巨人身上測試成年約爾孟加特。', '對巨人測試長大的蟄猛巨蟲', '', '去找。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12836 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12836, 'zhTW', '表達謝意', '我正好知道一項工作，很適合急著表現的菜鳥!我們有個豺狼人的麻煩…你甚至可以說是個豺狼人流行病!討厭的生物。他們不斷地湧出，現在已經跑到了我們的門口，偷我們的東西!真是難以相信。$B$B事情全都是因為他們的領袖，瘤皮而起，也會因為他結束。我要你去處理「結束」的部分…一路前往西邊雪盲丘的營地，去拜訪他。$B$B當我說「拜訪他」的時候，其實就是婉轉地在說「將他凌遲至死」。瞭嗎?瞭吧!', 'K3的瑞基特要你殺死瘤皮。', '', '去找風暴峭壁的瑞基特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12837 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12837, 'zhTW', '貨在托爾那', '[佔位文字] 向托爾回報。', '向托爾回報', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12838 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12838, 'zhTW', '情報收集', '我得要知道血色突襲軍今天在策劃些什麼。你要替我執行這項任務。$B$B飛往突襲軍港口，然後從他們的軍備箱裡面偷出文件來。箱子一定有上鎖，所以你得要用你想的到的辦法從血色突襲軍成員身上把鑰匙弄來。', '死亡高崗的野牛‧厲禍要你收集5份突襲軍情報文件。', '', '去找寒冰皇冠的野牛‧厲禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12839 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12839, 'zhTW', '上將的偉大計畫', '起初這些筆記看起來就像是你在找的其他資料一樣。但，迅速讀過內容之後你發現不是這麼回事。$B$B這封信上寫著韋斯溫上將就在島上的某處，但他目前仍然隱藏著自己的行蹤。他談到一個就快降臨的光榮之日，到時候血色突襲軍將會先解決巫妖王，然後再洗淨整個世界，為艾澤拉斯帶來秩序。$B$B統領指揮會想看看這封信的!', '將上將的信箋交給死亡高崗的指揮統領艾睿特。', '', '去找寒冰皇冠的指揮統領艾睿特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12840 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12840, 'zhTW', '絕對機密', '如果真的有人知道上將在哪裡，一定就是他在突襲軍港口的船長們了。$B$B<統領指揮摩擦著他的雙手。>$B$B威辛頓和哈特弗德，如果我沒記錯的話。去把情報逼問出來，然後了結他們的小命。$B$B我要知道上將到底藏在哪裡!', '死亡高崗的指揮統領艾睿特要你從威辛頓船長和哈特弗德船長口中逼問出情報來。', '', '去找寒冰皇冠的指揮統領艾睿特。', '已拷問並殺死威靈頓隊長', '已拷問並殺死哈特福隊長', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12841 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12841, 'zhTW', '巫婆的交易', '你一定是來找那個綠色的小囚犯…我們也許可以互相幫忙。$B$B你沒辦法靠蠻力把那隻哥布林弄出去的，至少沒辦法活著弄出去，嗯。$B$B在我的族人之中，他們叫我依爾克凡，幻術士。如你所見，海迪尼爾把我囚禁在這裡。$B$B如果我能夠拿到我的符文，我就可以讓你不被發現地潛入他們之中。礦坑更深處有個來回巡邏的監督者，名叫塞拉。我的符文在她手上。幫我把符文拿回來，然後我們再來談談。', '凋落礦坑的『巫婆』洛莉拉要你從監督者塞拉手上把依爾克凡符文拿回來。', '', '去找風暴峭壁的『巫婆』洛莉拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12842 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12842, 'zhTW', '符文鑄造:準備作戰', '戰爭在你的靈魂上刻下了無法磨滅的印記，死亡騎士。你已經學會了符文鑄造的黑暗秘藝，靠著它，你將可以在你的武器上刻下強大的符文。$B$B一定要做好作戰的準備。回到亞榭洛之心的符文熔爐旁，用符文鑄造的力量替你的武器紋上一個強大的符文!$B$B當你的刀刃上閃耀著黑暗能量之後，再回來找我!', '黯黑堡的講師拉祖維斯命令你用你的符文鑄造技能來為你的符文魂刃刻上符文。只要有符文熔爐，你就可以隨時自由地替換刻在武器上的符文。', '武器已鑲飾', '去找黑鴉堡壘的講師拉祖維斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12843 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12843, 'zhTW', '他們把男人抓走了!', '你得幫幫我們！當我們遠征到山裡架設發射塔的時候被襲擊了。$B$B他們看起來很像維酷人，但皮膚是藍色的，而且表面還覆著霜…而且全是女性！他們把遠征隊的男人全都抓走了，放過我們女性。求求你，$N！我想他們應該被關在希弗爾達村，就是那個能俯瞰K3的村子。', '格雷徹·嘶炫要你前往希弗爾達村並拯救5個哥布林囚犯。', '', '去找風暴峭壁的格雷森·嘶炫。', '釋放哥布林囚犯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12844 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12844, 'zhTW', '裝備回收', '拜託你，$N。當海迪尼爾帶走我們的男人的時候，他們也把我們的裝備全都給拿走了。當然，把人救回來是比較重要的，但假如你找到了我們的裝備，能帶回來給我們的話，我們也會非常感激你的。$B$B你可以在我們的上方找到他們的村子，就在北方。', '格雷徹·嘶炫要你到K3北邊的希弗爾達村收集8份K3裝備。', '', '去找風暴峭壁的格雷森·嘶炫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12845, 'zhTW', '達拉然傳送水晶旗幟', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12847, 'zhTW', '第二次機會', '我聽說過他們的大教堂裡有個大主教，但是我完全沒想到他們是把蘭格瑞給復活起來，又讓他晉升了!赤紅大教堂有重兵駐防，而且只有一個出入口，所以你得找些幫手。$B$B我們還是得弄清楚上將在哪裡，但這次我們絕不依賴運氣!$B$B帶著這個裝置。一旦你殺死了大主教，就可以用它來開啟一道傳送門讓我通過。$B$B我要直接從他的靈魂上把答案逼出來!我們一定會把海軍上將韋斯溫找出來的!', '殺死大主教蘭格瑞，然後在他的屍體旁召喚艾睿特之門。等指揮統領艾睿特訊問完大主教的靈魂之後，在赤紅大教堂與他交談。', '', '去找寒冰皇冠的指揮統領艾睿特。', '', '召喚艾睿特之門', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12848 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12848, 'zhTW', '無邊飢渴', '無盡的飢渴很快就會找上你了，$c。而當它來臨的時候，你會承受無法言喻的苦痛。這種折磨只有一道解藥:那就是滿足你的飢渴。$B$B我會告訴你通往救贖的關鍵。$B$B那些被黑暗兄弟會裁定沒用的傢伙被鎖在亞榭洛之心裡。用這把鑰匙來釋放那些拙劣的新兵。讓他們穿上裝備與你作戰，來換取他們的自由。殺了他們，你的苦痛就會止息。失敗了，你就得承受永恆的磨難。$B$B是生是死- 由你作主。', '黯黑堡的講師拉祖維斯命令你釋放一個拙劣的新兵，然後冷血地殺死他!不是你死就是他們亡!。', '', '去找黑鴉堡壘的講師拉祖維斯。', '不配的新成員已被壓制', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12849 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12849, 'zhTW', '血魄、冰霜與穢邪之力', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12851, 'zhTW', '騎上熊背', '考驗正等著你，女人!$B$B你擁有英后之心嗎?還是只會整天哭哭啼啼?$B$B上了戰場，你就會知道答案。$B$B你可以對你的母親，姊妹，甚至對你自己撒謊，但戰場會揭露出一個人最真實的一面。$B$B當你準備好了以後，騎上冰牙，然後投入戰場。你必須從她的背上，對我們的敵人降下死亡之雨。', '布倫希爾達村的布瑞嘉娜，要你騎上冰牙到遠古寒冬山射擊7隻冰霜座狼以及15個冰霜巨人。', '', '去找風暴峭壁的布瑞嘉娜。', '寒冰座狼已焚燒', '寒冰巨人已焚燒', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12852 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12852, 'zhTW', '揭露上將', '在新壁爐谷與大將軍阿比迪斯作戰的時候，上將以堅固無比的魔法球保護自己逃逸。$B$B我十分擅長消除魔法。$B$B帶著這個，然後到隱匿谷，當他張開防護球的時候對他使用。我真希望我能當場看看他的表情。$B$B把他解決掉吧。', '指揮統領艾睿特要你解決韋斯溫上將。完成之後回到死亡高崗找指揮統領。', '', '去找寒冰皇冠的指揮統領艾睿特。', '已處理大提督維斯特文', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12854 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12854, 'zhTW', '跟隨布萊恩的足跡', '自從在灰白之丘找到了布萊恩的日誌以來，我們只有發現過另外一個布萊恩的線索。有一封神秘的信寄到了鐵爐堡的探險者協會，沒有任何關於寄出地點的訊息。上頭只寫著我們應該要與布萊恩在他的營地碰面，然後協助他進行搜索。$B$B我只知道那個營地應該位於此地的東北方，越過伯爾之息河谷，座落於泰坦之途的某些遺跡處。', '從布萊恩的營地取得粗麻包裹的信箋，然後交還給霜堡的考古學家安多林。', '', '去找風暴峭壁的考古學家安多林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12855 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12855, 'zhTW', '嗅出犯人', '布萊恩便箋上的口吻暗指他想要把某個東西與便箋埋在一起，也許是某種包裹。你確定你只找到這個？$B$B好吧，我讓你帶上一條冰霜獵犬。牠們被霜誕族用來進行追蹤。把牠帶去毀壞的營地，然後讓牠嗅出布萊恩的味道。$B$B牠至少會帶你找到下落不明的那些東西，如果我們運氣夠好，甚至還可以找到布萊恩本人。', '在廢棄營地使用冰霜獵犬項圈，追蹤拿走布萊恩所有物的傢伙。當你回收了物品，就使用通訊裝置聯絡你聯絡的到的人。', '', '', '追蹤小偷', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12856 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12856, 'zhTW', '冰冷之心', '在戰場上光榮赴死會為我們全體帶來榮耀。然而，被凍結在冰塊裡承受無盡的嘲諷則否…$B$B你要飛往冰霜巨人的城市，丹尼弗蘭，就在遠古寒冬山谷的東邊，然後解救幾條我方被俘虜的元龍。有了他們的幫助，你就可以將我們的姊妹從冰凍的束縛中解放出來，帶領三位姊妹平安返家。$B$B小心那些巨人的木棒，否則你也會落入俘虜的行列中。', '救出3條被俘虜的元龍和9位布倫希爾達囚犯。', '', '', '已救出布倫希爾達的囚犯', '已釋放始祖幼龍', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12857 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12857, 'zhTW', '懸賞： 怒鬃的蹼', '公告者:怒爪酋長$B$B怒爪酋長所信賴的海獅，怒鬃，反咬了他主人一口。怒爪說怒鬃不乖因為那些德拉庫魯食人妖。怒爪酋長很傷心的要求殺死怒鬃並把怒鬃的蹼帶來給酋長當作證明。$B$B你會在東南邊找到怒鬃，在怒爪湖。$B$B怒爪酋長寫得不好很抱歉。第一次用這種東西;對了，怒爪酋長是獾狼怪，不是人。', '取回怒鬃的蹼，然後交給祖爾德拉克中，聖光止境的怒爪酋長。', '', '去找祖爾德拉克的怒爪酋長。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12858 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12858, 'zhTW', '謎團的拼圖', '感謝聖光，有人終於收到我的訊息。現在我終於脫離鐵矮人的掌握了，我想要請你們幫忙。我有獲得諾甘農拱心石的線索。諾甘農拱心石是守護奧杜亞檔案庫的鑰匙，但是泰坦將它分成兩半，藏起來。$B$B其中一塊，拱心石的殼，藏在北海岸的發明者圖書館，就在奧杜亞南方。所以你要做的第一件事情就是從圖書館守衛者身上拿回通行圓盤的碎片。', '收集六片發明者圓盤的碎片，將它們組成發明者圓盤。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12859 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12859, 'zhTW', '這個讚:火還很燙!', '食人妖攻擊怒爪巢穴，把怒爪趕出去!現在更壞。食人妖現在在燒村莊!這很糟。酋長讓最厲害的怒爪巫醫，摩基，研究火焰。結果驚人!火還是很燙，而且會燒東西。$B$B你可以幫怒爪滅火嗎?摩基會給你特殊的怒爪滅火器。用特殊的滅火器把把東南方的怒爪巢穴的火滅掉。有時候要噴很多次才能滅火，但滅火器一定有水!怒爪魔法超厲害!', '祖爾德拉克聖光止境的巫醫長老摩基要你用怒爪滅火器撲滅15個怒爪巢穴裡的著火小屋。', '', '去找祖爾德拉克的薩滿長老摩基。', '小屋的火已撲滅', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12860 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12860, 'zhTW', '資料探勘', '你組成的那個圓盤…是空的！那個奸詐的彌米爾一定把東西藏在別的地方了。找找看發明者的圖書館;你在那裡有看到資料庫嗎？$B$B也許那就是你拿圓盤要做的事情。嘗試用它靠近那些資料庫。或許它會檢索，然後重新存取資料。等你嘗試之後，再聯絡我，讓我知道你找到了什麼。在此同時，我會去找另一半的鑰匙。', '用發明者圓盤檢索7份在資料庫裡的隱藏資料。', '', '使用布萊恩的通訊器聯絡布萊恩·銅鬚。$B$B如果你弄丟了聯絡器，你可以與冰霜堡的考古學家安多林重新要個新的。', '取得隱藏資料', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12861 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12861, 'zhTW', '食人妖發瘋啦!', '德拉庫魯...你知道這食人妖是誰嗎?我覺得壞食人妖都是被德拉庫魯食人妖控制。他們叫自己德拉庫魯食人妖-我聽說的。你知道我為什麼是怒爪酋長了。我是獾狼怪裡最聰明的!$B$B但是這不是我跟你說話的原因。壞食人妖來把怒爪趕出巢穴。沒逃走的怒爪都被抓走了。你要去怒爪巢穴，東南方，然後救出被抓走的怒爪。鑰匙在食人妖身上，殺了他們!很多個鎖需要很多把鑰匙!', '祖爾德拉克聖光止境的怒爪酋長要你用從不同食人妖身上拿到的德拉庫魯『開鎖器』解救八個怒爪囚犯。', '', '去找祖爾德拉克的怒爪酋長。', '已釋放被俘的怒爪', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12863, 'zhTW', '致謝', '啊!謝謝你到這裡來$G小子:小女孩;。$B$B從你圓睜的雙眼和顫抖的雙手看來，我敢大膽地推測你是新來的。聽起來讓你見見我們親切的地主會是個好主意。$B$B我們有些多餘的醫療補給品...老實說，我們沒料到能夠擁有這麼舒適的據點。去把這個箱子拿給那邊的格洛梭，如果你願意的話，再幫他一把。我們實在受到很多照顧接待，因此不希望他們認為我們不知感激。', '把醫療補給箱交給霜堡的格洛梭·硬鬚。', '', '去風暴峭壁找霜堡的格洛梭·硬鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12864 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12864, 'zhTW', '消失的斥候', '既然你來幫忙，我有件事情要麻煩你。$B$B我們的幾個斥候拖延了很久還沒有回來。這山地環境很嚴苛...但這幾個小子應該早有準備才對。$B$B前往東方...搜索伯爾之息河谷沿途以及伯爾瀑布...他們應該是在那個方向。如果你找到任何跡象，立刻把消息帶回來給我。我們在此地有一些敵人 - 如果他們之中有人升高了敵意，咱們最好早點收到警告。', '霜堡的格洛梭要求你，搜索伯爾之息河谷與伯爾瀑布，尋找失蹤霜誕斥候的蹤跡。', '找出失蹤的偵察兵', '去找風暴峭壁的格洛梭·硬鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12865 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12865, 'zhTW', '忠誠的夥伴', '新人!你好啊!你有時間的話，我有些工作要交代你。$B$B此地東去就是足跡冷原...是個鳥不生蛋的地方，但是，那裡聚集著一群犀牛。我們的小鳥對犀牛肉情有獨鍾，但是獵捕犀牛其實滿危險的，因為那一帶還有不少元龍的巢穴。$B$B如果你夠機靈的話，去獵些犀牛肉，帶到這附近的群山裡，填飽棲息在那裡的老鷹吧。', '在霜堡的弗尤林‧霜眉要求你，獵取8片新鮮寒冰犀牛肉，並用來餵飽鎮上的風暴頂雄鷹。', '', '去找風暴峭壁的弗尤林·霜眉。', '已餵食風脊鷹', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12866 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12866, 'zhTW', '擊退來犯者', '該死的鷹身人。我們把他們打到投降好幾次了，多到我都記不清…然後每打一次他們就會安分一陣子。這次我還以為他們會安分久一點。$B$B顯然沒有。$B$B他們的記憶力雖然不會存留太久，但如果能夠削減他們的數量，他們就會退回去。前往北方跟東方的山谷替我清掉一票鷹身人，怎麼樣？', '霜堡的格洛梭‧硬鬚要你殺死8個霜羽尖嘯者以及8個霜羽女巫。', '', '去找風暴峭壁的格洛梭·硬鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12867 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12867, 'zhTW', '偷嬰賊', '數週之前，如果你抬頭往上看，你會看到幾十隻漂亮的雄鷹在空中盤旋。現在，就算有也寥寥無幾。牠們現在幾乎整天都待在巢裡，因為那些鷹身人一直在偷取牠們的蛋。$B$B這些鷹身人似乎養成了愛吃老鷹肉的習慣...這些病態的妖婦把蛋帶在身邊，等到孵化出來才吃掉雛鳥。前往山谷的北邊或東邊那找出那些蛋並且蛋給拿回來，我會把帶它們回鷹巢。', '霜堡的弗尤林‧霜眉要你帶回15顆風暴頂鷹蛋。', '', '去找風暴峭壁的弗尤林·霜眉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12868 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12868, 'zhTW', '西拉納‧冰嘯', '這個西拉納‧冰嘯聽起來像是那個在背後煽動鷹身人攻擊的傢伙。如果我們把她解決掉，我想他們的攻擊就持續不了多久了。$B$B我們的一名風暴騎兵宣稱看見她在西北邊的山上徘徊，把這個妖婦找出來並宰了她。讓我們解決這一切吧。', '霜堡的格洛梭‧硬鬚要你殺死西拉納‧冰嘯。', '', '去找風暴峭壁的格洛梭·硬鬚。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12869, 'zhTW', '逼人太甚', '你當時跟洛肯一起在場，不是嗎？鐵矮人抓走了元龍的育母，維拉努斯。那些龍對此感到非常不開心…變得非常具有攻擊性。$B$B他們入侵了風暴頂雄鷹的領土，導致全面開戰，現在是時候回報牠們的恩情了。我們現在就出發，去足跡冷原把那些龍殺得片甲不留。$B$B風暴之心國王把這柄戰錘交給我 - 好好使用它，然後記得交還給我。', '霜堡的弗尤林‧霜眉要求你，騎乘一頭風暴頂雄鷹，並前往足跡冷原殺死16隻風暴巔巨龍。', '', '去找風暴峭壁的弗尤林·霜眉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12870 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12870, 'zhTW', '遠古聖物', '哎呀你好哇!$B$B在你出發去進行你偉大的任務與冒險之前，我可以拜託你幫個小忙嗎，$g小子:小女孩;?$B$B這山脈中藏著滿滿的聖物和漂亮的小東西…對探險者協會來說簡直就是美夢成真啊。如果你碰巧找到這些寶藏，然後帶來給我，我會萬分感激的。我甚至可以跟你分享我的麥芽酒!相信我，$g小子:小女孩;，這是筆划算的交易!', '把10個奧杜亞聖物帶去給霜堡的洛克·銳頦。', '', '去找風暴峭壁的洛克·銳頦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12871 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12871, 'zhTW', '來自探險者協會的援助', '真有趣。我在外殼上並沒有看到任何鎖定的結構。這代表我們要做的不僅僅是找到另外一部份，然後組合成拱心石就好。$B$B把外殼拿去霜堡，給遠征隊的領導者拉格努斯看。等他佩服完了，應該就能夠靠著外殼推敲出核心的樣子，也許還能讓冰霜矮人幫忙找它。$B$B我去查查看能否找出結合兩個部分的方法。當我們都有了進展再碰頭。', '帶著諾甘農之殼去霜堡找拉格努斯。', '', '去找風暴峭壁的拉格努斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12872, 'zhTW', '諾甘農之殼', '發明者圓盤資料傳輸中。$B$B圓盤資料傳輸完畢。$B$B緊急伽瑪射線措施準備中。$B$B緊急伽瑪射線措施準備完成。請以充能圓盤啟動諾甘農之殼管理員梅查頓。一旦您的身分確認完成，管理員會立刻給您諾甘農之殼。$B$B祝您擁有愉快的千年。', '從管理員梅查頓那取回諾甘農之殼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12874 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12874, 'zhTW', '霜誕的熱情', '我很樂意提供我的居所與家園給需要幫助的旅行者，但是我不願強迫我的人民加入你們的行動。$B$B這樣吧…我的子民都是貨真價實的戰士。在霜誕矮人成年的時候，他必須在戰鬥中證明自己的本事。他必須向我們證明他不會被體型的差距給打敗。$B$B向我證明你跟我的子民一樣強悍勇猛，我就會讓他們聽你說話或是為你作戰。跟南邊懸崖的弗尤林談談，他會讓你進行測驗。', '霜堡的約格·風暴之心要求你與弗尤林·霜眉交談，取得坐騎，並進行你的挑戰。', '', '去找風暴峭壁的約格·風暴之心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12883 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12883, 'zhTW', '德拉庫魯的命令', '奴僕們聽令!巫妖王將讓德拉庫魯指揮在祖爾德拉克的天譴軍部隊。我們的命令是殺掉所有東西。$B$B所有東西都得死!$B$B我們將走在亡者原野的屍體上。為了天譴軍，將他們送到在賽拉瑪斯的納法勒斯王子部隊!在德拉庫魯的管理下，所有東西都不會浪費!很快，我們就會喝著先知的血，變得比以往都要強大!祖爾德拉克跟剛德拉克都將死於天譴軍手上!', '把德拉庫魯的命令拿給祖爾德拉克聖光止境的十字軍領主蘭迪加。', '', '去找祖爾德拉克的十字軍領主蘭迪加。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12884 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12884, 'zhTW', '黯黑守望', '此處以西，越過了毀壞的路面跟建築，就是死亡騎士的紮營地，黯黑守望。$B$B<十字軍領主蘭迪加將德拉庫魯的命令捲起。>$B$B把這些命令拿給一個叫史戴芬‧瓦度的。讓他知道銀白十字軍會對付納法勒斯王子。他們要處理德拉庫魯。$B$B小心點，$n。去黯黑守望的路上有許多天譴軍。', '將德拉庫魯的命令送到祖爾德拉克黯黑守望的史戴芬‧瓦度手上。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12885 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12885, 'zhTW', '奧杜亞的流亡者', '風暴群山是個複雜的地方，可只是泰坦遺跡而已。住在那裡的人面對的是洛肯跟他的爪牙們。他將他最喜愛的僕人們，鐵矮人，放在那裡對抗所有岩石生物。他將土靈逐出奧杜亞，強迫他們遷居石崖避難所，就在發明者圖書館的西邊山面上。石崖跟他的兄弟被鐵矮人圍困在那裡。找到他們，幫助他們，$N。', '跟石崖避難所的『塑岩者』石崖談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12886 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12886, 'zhTW', '德拉坎舍試煉', '這就是了。你通過了所有海茲競技的考驗...幾乎所有。你是我們姊妹中最好也最勇猛的。最後的試煉近在眼前。德拉坎舍試煉，一個考驗著海迪尼爾戰士的價值跟靈魂的真正試煉。你要以你自己，你的飛龍坐騎，再加上一根帶鍊魚叉來和二十個姊妹競爭。$B$B不要手下留情。沒有人期待你這麼做。', '用海迪尼爾魚叉打敗10個風暴神殿的海茲競技飛龍騎兵。', '', '去找風暴峭壁的索林姆。', '已擊敗希爾茲彌特龍騎士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12887 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12887, 'zhTW', '這是有趣的遊戲', '黯刃騎士團要拿下西北邊的暗影穹殿。我在他們的隊伍中有一個線民，他需要幫忙。$B$B首先第一步就是遮斷巫妖王的視覺。他用一個名叫窺探之眼的裝置監視整個區域，那眼睛就飄浮在穹殿的頂端。$B$B我們的矮人準備了一些對付他的東西。破壞「眼睛」了以後，去找穹殿中的史力弗男爵。他偽裝成仍受巫妖王的控制的樣子。', '破壞窺探之眼，然後向暗影穹殿的史力弗男爵回報。', '', '去找寒冰皇冠的史力弗男爵。', '毀滅窺探之眼', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12888 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12888, 'zhTW', '廢料E號', '這張卡片讓使用者能操控廢料機器人E號上的操控面板，讓機器人能夠重新開始它維修的任務。$B$B廢料E號看起來應該是在發明者圖書館的內部。這張卡片上寫了機器人上壞掉的元件和系統。如果有適當的元件，它就能重新上工。', '將廢料E號操作卡、4把鈷藍螺栓、5個過載電容器帶到發明者圖書館裡的廢料E號。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12891 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12891, 'zhTW', '我有個點子，但首先...', '當我還在，嗯哼，巫妖王的底下服務時，我們常常用一種叫做最高統治節杖的東西讓比較聰明的天譴軍聽話。$B$B我需要你幫我製作新的一枝。$B$B不過幸運的是，所有需要的材料都隨手可及:教徒節杖、憎惡體之鉤、魂屍之繩、還有一把天譴精華。$B$B這應該不難，$c。', '暗影穹殿的史力弗男爵要你收集一把教徒節杖、一個憎惡體之鉤、一條魂屍之繩、還有五個天譴精華。', '', '去找寒冰皇冠的史力弗男爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12892 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12892, 'zhTW', '這是有趣的遊戲', '黯刃騎士團要拿下西北邊的暗影穹殿。我在他們的隊伍中有一個線民，他需要幫忙。$B$B首先第一步就是遮斷巫妖王的視覺。他用一個名叫窺探之眼的裝置監視整個區域，那眼睛就飄浮在穹殿的頂端。$B$B我們的哥布林準備了一些對付他的東西。破壞「眼睛」了以後，去找穹殿中的史力弗男爵。他偽裝成仍受巫妖王的控制的樣子。', '破壞窺探之眼，然後向暗影穹殿的史力弗男爵回報。', '', '去找寒冰皇冠的史力弗男爵。', '眼球體已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12893 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12893, 'zhTW', '解放你的心靈', '暗邪，夜林女士跟跳躍者會對巫妖王的戰爭很有幫助，要是他們能掙脫他所施加的意志束縛。這就是最高統治節杖的用處。$B$B你可以在往東邊跟西邊的墓穴前的岩架上找到他們，還有在上頭墓穴附近的岩架。節杖是用在他們的屍體上的。$B$B起飛吧。馬上就可以讓他們加入我們!', '暗影穹殿的史力弗男爵要求你，在暗邪、夜林女士與跳躍者的屍體上使用最高統治節杖。', '', '去找寒冰皇冠的史力弗男爵。', '維爾已被策反', '夜林夫人已被策反', '跳躍者已被策反', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12895 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12895, 'zhTW', '失蹤的銅鬚', '我們離開之前，我收到斥候沃塔克收集的資料，關於這個布萊恩‧銅鬚。毫無疑問，從他的資料上可以發現這個布萊恩已經從灰白之丘往風暴群山出發了。在我們失事之前，我看到南邊有個營地，就在過了足跡冷原，可以看到伯爾之息河谷的地方。$B$B要是布萊恩不在那裡，就去搜搜營地和周圍，看看有沒有那個該死的矮人去了哪裡的線索。把你找到的東西帶回來。', '在布萊恩的營地裡搜尋粗麻包裹的信箋，將它交給葛羅姆亞什失事地的博克塔‧血怒。', '', '去找風暴峭壁的博克塔‧血怒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12896 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12896, 'zhTW', '如果無法感化他', '像光禍將軍這樣的死亡騎士，與巫妖王的意志聯繫太過緊密，除非在極端特殊的狀況下，是無法被解開的。$B$B將軍本人待在穹殿裡監督著新武器的製作。只要你去擾亂他在北邊熔爐的武器架，我保證他會親自前來。我會派暗邪，夜林女士跟跳躍者進去幫你。$B$B如果我們要攻陷暗影穹殿的話，光禍將軍一定得死!', '擊敗光禍將軍，然後回到砲艇，破天者號向薩沙理安回報你的成功。', '', '去找寒冰皇冠的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12897 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12897, 'zhTW', '如果無法感化他', '像光禍將軍這樣的死亡騎士，與巫妖王的意志聯繫太過緊密，除非在極端特殊的狀況下，是無法被解開的。$B$B將軍本人待在穹殿裡監督著新武器的製作。只要你去擾亂他在北邊熔爐的武器架，我保證他會親自前來。我會派暗邪，夜林女士跟跳躍者進去幫你。$B$B如果我們要攻陷暗影穹殿的話，光禍將軍一定得死!', '擊敗光禍將軍，然後回到砲艇，奧格林之錘向寇爾提拉‧亡織者回報你的成功。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12900 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12900, 'zhTW', '製作鞍具', '所以說你想要騎熊?嗯，如果你能奮鬥到這一步，一定有人覺得你有資格參加海茲競技。$B$B總之一步一步來，我們首先得替你做個鞍座。$B$B你可以在南邊的懸崖處找到散居的雪人。他們的毛皮很堅韌，厚度又正好適合。帶一些毛皮給我，我就會讓你開始學習如何做個熊騎士。', '布倫希爾達村的艾絲翠德‧畢優利塔要你取得3塊冰鬃雪人毛皮。', '', '去找風暴峭壁的艾絲翠德‧畢優利塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12901 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12901, 'zhTW', '無中生有', '一定要阻止納法勒斯王子。我們不能讓天譴軍繼續把這個地區當作殭屍工廠。如果我們能夠讓坦克運作，也許就還有一點機會。現在我需要的是備用零件。$B$B此地西北方被稱為瑟瑞姆之歿。天譴軍隊把這個地方當作某種基地。殘骸自從他們抵達以來就散佈在基地的四周。那裡地表四處遍布天譴金屬碎塊。把那些東西拿給我，我會試著好好加以利用。', '十字軍前線營地的工程師瑞德要你回收10個天譴金屬碎塊。', '', '去找祖爾德拉克的工程師瑞德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12903, 'zhTW', '這就是朋友的意義...', '我們當時被納法勒斯王子與至少十幾個天譴軍襲擊。我叫達加希和雙胞胎待在坦克裡面，但是他們不聽我的話。達加希盯著我的眼睛，然後說，「如果沒有人出去的話，我們全都會被殺光。」然後他就叫瑞德關掉引擎，接著他就衝鋒出去了。這是我看過最英勇的行為。$B$B我聽見王子對那些怪獸喊了幾句命令。聽起來他似乎要把他們帶去瑟瑞姆之歿，就在此地西北方。我們一定得救出我們的朋友。你願意去尋找他們嗎?', '十字軍前線營地的十字軍麥克凱拉要你找到十字軍達加希、介爾克、與孛爾。', '', '去找祖爾德拉克的十字軍麥克凱拉。', '已找到十字軍達加斯', '已找到格爾克', '已找到伯爾', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12904, 'zhTW', '聖光不會賜予我復仇', '他們...他們殺了我兄弟。$B$B<介爾克努力忍住淚水。>$B$B他們像是宰殺牲口一樣屠殺了他。現在他們把他放在營地另一頭的一張桌子上，準備用他來進行穢暗的實驗。達加希也死了。聖騎士在東北方的遺跡英勇地頑抗，但是瓦苟的領袖，奧嘉爾，實在太強了。$B$B我是唯一的倖存者，而我也快死了。我...我正在轉變。$B$B如果聖光不會賜予我復仇，也許你會，$c。把他們全部殺光。', '瑟瑞姆之歿的介爾克要你殺死15個瓦苟。', '', '去找祖爾德拉克的介爾克。', '瓦格爾已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12906 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12906, 'zhTW', '紀律', '讓你從單純的事情開始做起吧。在礦坑裡替我們工作的男性維酷人並不是自願的...單純只是出於對刀刃的恐懼。$B$B每隔一小段時間他們之中總會有人喪失動機。找出不合作的維酷人，然後叫他們去工作。$B$B帶著這把紀律節杖。你去造成他們痛苦，而不是造成死亡。嗯，至少大多數時候是這樣啦。', '凋落礦坑的殘酷的米歐瑞德要你對6個精疲力竭的維酷人使用紀律節杖。', '', '去找風暴峭壁的殘酷的米歐瑞德。', '已管教精疲力盡的維库人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12907 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12907, 'zhTW', '殺一儆百', '每個作用力都會產生相對的反作用力，姊妹。當我們對男性施加壓力的時候，產生的反作用力就是最近謠傳的叛亂。$B$B這些鬍子豬儸賤民背後的煽動者叫做賈爾赫。宰掉他...確定其他的男性都有目睹他的末日。他們得搞清楚，我們是不會容忍反抗的。', '凋落礦坑的殘酷的米歐瑞德要你殺死賈爾赫。', '', '去找風暴峭壁的殘酷的米歐瑞德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12908 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12908, 'zhTW', '某個囚犯', '你毫不手軟。你在這一帶會混的很好。$B$B我有另外一個任務要給你。有個維酷女囚犯變的比我預期中的還要令人困擾。$B$B她竟然有膽宣稱自己有權參加海茲競技 -- 我們比試力量與戰鬥本領的神聖競賽。$B$B這是解開她鐐銬的鑰匙。盡可能做得乾淨俐落點。再怎麼說她雖然不是我們族人，也是個女性。', '拿著米歐瑞德的鑰匙去凋落礦坑找『巫婆』洛莉拉。', '', '去找風暴峭壁的『巫婆』洛莉拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12910 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12910, 'zhTW', '嗅出犯人', '這次就照博克塔的意思作，但我希望他將來會補償我。不要這樣看我。雖然博克塔負責指揮沒錯，但沒有人可以命令獵人。$B$B「把那頭野獸弄走，」他總是說，「叫牠別再吼了。」$B$B然後當他需要的時候又突然改變態度。下次他再抱怨，我就叫霜齧咬他一下。別擔心，她追蹤獵物的表現會很出色的。當她找出目標之後，你就得自己對付鐵矮人，布萊恩，或者你找到的任何東西。', '騎上霜齧，然後騎向布萊恩的便箋上殘留氣味的源頭。然後回收布萊恩的通訊器，用它跟布萊恩‧銅鬚聯絡。', '', '', '循著氣味追蹤源頭', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12914 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12914, 'zhTW', '拯救基默', '所以你是說他被關在一個百呎高的籠子裡，嗯?$B$B如果我的計算正確，我們至少可以脆化籠子的絞鍊，給巨人足夠的餘裕掙脫出來。$B$B要做到這件事，我需要一些塑化劑和穩定劑。$B$B女妖精華應該很適合當作塑化劑。你可以從東北邊亡者原野的女妖身上取得。穩定劑可以從西南邊黯黑守望附近的地怒者身上取得。$B$B動作快吧!', '十字軍前線營地的工程師瑞德要你把6個女妖精華與6個矽藻土壤交給他。', '', '去找祖爾德拉克的工程師瑞德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12915 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12915, 'zhTW', '修補圍籬', '如果我想從我兄弟的手中奪過造物者神殿，我就得跟老盟友重修舊好。$B$B也許藉著消滅一個共通的敵人，能夠使我稍微修補我和霜巨人的友誼。$B$B斐雍帶著鐵巨人包圍了丹尼弗蘭。你必須在斐雍之砧擊敗他，就在此處東方遠處。削弱他的軍力，讓霍迪爾之子邁向勝利。$B$B帶著這個符咒，$n。用它來召喚我的土靈幫助你。', '風暴神殿的索林姆要求你到丹尼弗蘭東邊的斐雍之砧，殺死斐雍與5個鐵巨人。使用索林姆的大地符咒，可以召喚他的土靈與你一同作戰。要發動符咒，必須準備斐雍之砧附近所產的花崗岩巨石。', '', '去找風暴峭壁的索林姆。', '已擊殺弗約恩', '風暴鍛造鐵巨人已擊殺', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12916 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12916, 'zhTW', '我們唯一的希望', '我要給你的東西叫做爆鹽。這是一種極端易爆的炸藥，還具有獨特的性質。由於具有高延展性，你可以很輕易的把它塞進鉸鏈與籠子的縫隙裡製造最大的傷害。$B$B回去找你的朋友用超超超大爆鹽炸藥釋放他吧。$B$B讓我們期待他能遵守約定。他是我們唯一的希望了。', '一旦你使用超超超大爆鹽炸藥打開天譴圍欄之後，就與與瑟瑞姆之歿的基默交談。', '', '去找祖爾德拉克的基默。', '天災圍欄已炸毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12917 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12917, 'zhTW', '以風之聲交談', '我想我們應該無法期待能夠很輕易的找到布萊恩，我們運氣沒那麼好。如果我們能弄懂布萊恩在說什麼，也許你就可以說服他告訴你他的位置。$B$B風的力量在群山中很強，也許可以提供我們很大的幫助。一個學識淵博的薩滿可以透過風聽懂世界上的各種語言。$B$B在西北邊的雪迅平原上，你可以找到由風所構成的存在，風暴馭乘者。捕捉他們的聲音，然後把聲音帶來給我。', '把5個風之聲帶去給葛羅姆亞什失事地的摩特哈‧風誕。', '', '去找風暴峭壁的摩特哈‧風誕。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12918 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12918, 'zhTW', '完美寶石', '看來刺骨的寒風已經吹到這裡來了？現在不僅僅是缺少欣賞我手藝的顧客，而且我也沒有庫存的寶石可以出售了！如果你能弄些未切割的寶石來補充我的庫存，我可以教你切割完美寶石的技術。切割完美寶石能讓你在切割諾森德地區出產的優秀品質寶石時，有機會切割出一顆具有更高屬性的完美寶石。', '將茶晶石、黑玉和暗影水晶各兩顆交給瓦加德的恩霍羅。', '', '去找凜風峽灣的安胡洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12919 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12919, 'zhTW', '風暴之王的復仇', '我的子民被巫妖王大舉屠殺。天譴軍團現在用風暴巨人的屍體製造毫無心智的血肉巨人，或者縫補出像瑟瑞姆這種更糟的畸形怪物。$B$B沒有任何東西可以阻止我把他們逐出這個世界。我們會攜手毀滅威脅祖爾德拉克的天譴軍。$B$B我們將會把他們全部殺死:納法勒斯王子、奧嘉爾以及瑟瑞姆!$B$B當你準備好了，就告訴我，讓我們開始我們的毀滅之旅。', '與基默交談出發。$B$B騎著基默摧毀100個天譴軍，並殺死『天選』奧嘉爾、瑟瑞姆以及納法勒斯王子。一旦你成功了，就向十字軍前進營地的十字軍麥克凱拉報告。', '', '去找祖爾德拉克的十字軍麥克凱拉。', '殺死天譴軍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12920 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12920, 'zhTW', '追上布萊恩', '你在等什麼？感謝摩特哈，語言的藩籬已經被打破了。與布萊恩‧銅鬚聯絡，然後找出他躲在哪裡，還有他到底在追蹤什麼。$B$B也許我們還能從這場災難中搶救點什麼。', '使用布萊恩的通訊器與布萊恩‧銅鬚通訊，與他交談，然後和葛羅姆亞什失事地的博克塔‧血怒交談。如果你弄丟了布萊恩的通訊器，去找葛羅姆亞什失事地的摩特哈‧風誕談談。', '', '去找風暴峭壁的博克塔‧血怒。', '與布蘭恩交談', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12922 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12922, 'zhTW', '精鍊之火', '在它滲著水氣的外層之下，這塊金屬閃動著奇異的光芒。$B$B不過首先，你認為先把上頭的熔渣在斐雍的鐵鉆燒掉才是謹慎的作法。$B$B正當你思索著在這冰凍的荒原裡要上哪找火源的時候，一個火焰亡魄走過了你面前…', '你必須從霜域湖的沸騰亡魄身上收集10個狂烈火花，然後在斐雍之砧使用它們。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12924 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12924, 'zhTW', '鑄成同盟', '<自從你見到索林姆以來，他首度微笑。>$B$B一切都開始有種命中注定的味道了，$r。$B$B你找到的東西，是我盔甲殘餘的殘片，在哀戚中我拋下它，丟給了元素。只有霍迪爾之子能夠重鑄它，因為原先盔甲就是他們製造出來的。$B$B也許你已經為他們做的夠多了，多到足以軟化他們對我的痛恨。去找他們的國王，裘庫姆，假使他還活著的話。$B$B設法晉見他，請求他的協助。', '你要去丹尼弗蘭，請求裘庫姆王允許重鑄索林姆之甲。完成他的任務之後，你要去找丹尼弗蘭的尼約梅爾德談話。', '', '去找風暴峭壁的尼約梅爾德。', '', '弗約恩的鐵砧已帶往杜恩尼弗倫', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12925 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12925, 'zhTW', '畸形', '巫妖王曾三次派使者前來，三次都立即被我們肢解分屍了。$B$B我們在華爾基倫的姊妹並不像我們一樣堅定的信奉傳統教條，所以接受了天譴軍。現在她們不再從野外捕捉飛龍，而是在天譴軍帶來的瘟疫與疾病中培育牠們。$B$B取走華爾基倫海迪尼爾所攜帶的冰霜之油，然後用在你找到的任何染疫龍蛋上。謠傳那些龍蛋都被保存在一座惡臭的荒疫之池中。', '布倫希爾達村的賽拉‧克微蕭要求你，前往華爾基倫並從華爾基倫野心家身上取得冰霜之油瓶。使用冰霜之油摧毀30個染疫元龍蛋。', '', '去找風暴峭壁的賽拉‧克微蕭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12926, 'zhTW', '拼圖的碎片', '我們看過鐵矮人帶著他們的傀儡與布萊恩稱做土靈的那種石頭生物作戰，鐵矮人一方還有他們的巨人盟友。想辦法聯絡布萊恩，然後盡你所能地協助他。記住任何能夠幫助我們對付鐵矮人與背後主人的訊息。', '使用布萊恩的通訊器聯絡布萊恩‧銅鬚，了解下一步該做的事。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12927, 'zhTW', '資料探勘', '你組裝好的圓盤…是空白的！守護者彌米爾，建造這座圖書館的工匠，一定把資訊藏到別的地方去了。到發明者圖書館找找;你有沒有看到資料庫？$B$B也許這就是圓盤的用途。試著靠近資料庫使用圓盤，也許它是被設計成能夠從資料庫下載儲存資料的東西。當你嘗試過了以後，就再次聯絡我，讓我知道你發現了什麼。在此同時，我會試著追蹤另一半的檔案庫鑰匙。', '使用發明者圓盤從資料庫取得7份隱藏資料。', '', '', '已收集隱藏資料', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12928 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12928, 'zhTW', '諾甘農之殼', '發明者圓盤資料傳輸中。$B$B圓盤資料傳輸完畢。$B$B緊急伽瑪射線措施準備中。$B$B緊急伽瑪射線措施準備完成。請以充能圓盤啟動諾甘農之殼管理員梅查頓。一旦您的身分確認完成，管理員會立刻給您諾甘農之殼。$B$B祝您擁有愉快的千年。', '從管理員梅查頓那取回諾甘農之殼。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12930, 'zhTW', '稀有的土壤', '這些鐵鎚用來敲鑿岩石，而不是鐵矮人的日子，現在看來似乎很遙遠。我們從奧杜亞被驅逐出來，使得我們之中的弱者死去，而最強的工匠都成了戰士。$B$B隨著鐵矮人步步進逼，就連最強的戰士都會死去。$B$B我們沒辦法幫助傷者，除非我們能夠補充附上法術的土壤。我們過去曾在西北邊的峭壁開採這種土壤，但是僵持的戰火使我們抽不出身補充存貨。你願意幫忙嗎?', '使用土靈採礦鎬採取7堆附魔土壤。將附魔土壤與5張霜紋布帶去給石崖避難所的『塑岩者』石崖。', '', '去找風暴峭壁的『塑岩者』石崖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12931, 'zhTW', '反擊', '避難所的防衛者盡其所能地削弱了鐵矮人的攻勢，但是我們還是一點一點的被逼退。我的手下很堅強，但他們還是會疲勞。要是沒有援軍的話，被徹底擊敗只不過是時間上的問題而已。$B$B你願意借出你的能力來幫助避難所嗎?這樣將會大大提高防衛者的士氣，並且為他們 -- 還有我 -- 帶來反擊的希望。$B$B殺死你在避難所外遇見的任何風鑄矮人，或是他們的創作物。', '『塑岩者』石崖要你殺死10個風鑄進攻者，然後回到石崖避難所向他回報。殺死風鑄劫掠者或風鑄劫奪者都可以。', '', '去找風暴峭壁的『塑岩者』石崖。', '風暴鍛造攻擊者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12932, 'zhTW', '苦痛露天競技場:伊格卓斯!', '我跟你說，老兄，這個地方是納葛蘭平原的翻版。這些食人妖比巨魔還要下流，但是我跟你講，哪裡有錢賺，我就往哪裡跑!所以啦，歡迎來到祖爾德拉克，夥伴。$B$B你新來乍到，就讓我直接幫你講解。我是比賽發起人，我身旁的是我的保鏢烏丁。你則是場上的娛樂。當你想要作戰的時候就告訴我，我就會準備進行比賽。$B$B如果你準備好了，而且帶了一隊朋友，我們就可以開始了!怎麼樣?', '進入苦痛露天競技場並且擊敗伊格卓斯!然後去找『食人妖僕從』烏丁領賞。', '已擊敗尤格德拉斯', '去找祖爾德拉克的食人妖僕人伍德林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12933 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12933, 'zhTW', '苦痛露天競技場:猛瑪象人!', '下一場比賽可好玩了，夥伴!顯然有些從龍骨荒野來的猛瑪象人也想參一腳。你以前有跟這些傢伙打過嗎?我只能建議你瞄高一點啊!$B$B告訴我一聲，咱們就開始搞派對吧!', '進入苦痛露天競技場並且擊敗臭鬚!然後去找『食人妖僕從』烏丁領賞。', '已擊敗臭鬍子', '去找祖爾德拉克的食人妖僕人伍德林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12934 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12934, 'zhTW', '苦痛露天競技場:超越次元!', '我不想對你說謊，朋友。這次也許你贏不了。下一個對手是從元素界來的!我根本不知道競技場上到底會出現什麼咧!$B$B如果你覺得準備好了，就進去送他們下地獄吧!', '進入苦痛露天競技場並且擊敗一位元素領主!然後去找『食人妖僕從』烏丁領賞。', '已擊敗元素領主', '去找祖爾德拉克的食人妖僕人伍德林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12935 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12935, 'zhTW', '苦痛露天競技場:巨牙世界末日!', '下一場的戰士是從一個黑暗的地方來的，小子。只有在另一邊才看的到的那種黑暗。他非常的飢餓，而且願意不擇手段取勝。你可要小心點!我聽說他把跟雪人摔角當作運動在做!$B$B你準備好了我們就開始。', '進入苦痛露天競技場並且擊敗歐令諾寇·碎牙者!然後去找『食人妖僕從』烏丁領賞。', '已擊敗奧里諾科·碎牙者', '去找祖爾德拉克的食人妖僕人伍德林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12936 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12936, 'zhTW', '苦痛露天競技場:『血怒者』科爾拉克!', '你不會相信的，夥伴。你的下一場戰鬥是對上『血怒者』科爾拉克!看來德拉克瑞食人妖決定放手一搏了!讓我告訴你，夥伴，他可是有喝過那些動物神的汁液。他很強，而且完全準備好要把你給抬去種了。$B$B你準備好了嗎?', '進入苦痛露天競技場並且擊敗『血怒者』科爾拉克!然後去找『食人妖僕從』烏丁領賞。', '已擊敗嗜血怒者科拉克', '去找祖爾德拉克的食人妖僕人伍德林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12937 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12937, 'zhTW', '解救倒下者', '避難所的防衛者相當英勇，但是他們沒法在鐵矮人的猛攻下支持太久。$B$B多虧了你收集來的泥土，我可以製造繃帶，以治癒傷兵及陣亡的戰士。我們治好越多防衛者，我們就能支持越久。$B$B帶著這些膏藥，到避難所外面，治療負傷和倒下的土靈防衛者。盡你所能地讓他們重回戰場，$n。對我們來說，每增加一個傷兵都是不能承受的損失。', '使用脈流糊藥治療8個倒下的土靈防衛者，然後回到石崖避難所找『塑岩者』石崖。', '', '去找風暴峭壁的『塑岩者』石崖。', '已治療陣亡的土靈守衛', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12939 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12939, 'zhTW', '榮耀挑戰', '首先，第一步得要在卓頓海姆裡面一個叫做蠻荒岩臺的地方進行。就在西邊的山上。$B$B岩臺上的維酷戰士們總是在進行拳鬥，由他們族長指派的人選教導他們戰鬥的技藝。$B$B我要你帶著這面旗幟去挑戰他們。讓我們以「僅僅一個$r」的技藝打擊他們的士氣，如何?$B$B<公爵咧嘴微笑，腐爛的牙齒在穹殿的微光中閃爍。>', '暗影穹殿的蘭克洛公爵要你用挑戰旗幟挑戰並擊敗6個默約丁戰鬥員。', '', '去找寒冰皇冠的蘭克洛公爵。', '已挑戰並擊敗約丁戰士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12940 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12940, 'zhTW', '糖果桶', '', '這種糖果桶在各地的旅店都有。來吧…拿點糖果！。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12941 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12941, 'zhTW', '糖果桶', '', '這種糖果桶在各地的旅店都有。來吧…拿點糖果！。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12942 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12942, 'zhTW', '斬下她們的黑翼', '叛徒。我們海迪尼爾討厭她們。$B$B華爾基倫的居民該受的懲罰已經拖了太久了。在我們對索林姆保持忠誠的時候，她們卻成了巫妖王的走狗!$B$B她們把受到他恩賜的人稱為華爾琪。他們用長滿羽翼的雙翅飛行，就像鷹身人一樣。$B$B你可以在西北邊遠方找到華爾基倫，在風暴神殿的後方。殺死那些長翅膀的母狼，姊妹。殺死她們，我就會用我珍藏的物品來獎勵你。', '布倫希爾達村的『復仇』伊娃要你去華爾基倫殺死12個初生的華爾琪。', '', '去找風暴峭壁的『復仇』伊娃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12943 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12943, 'zhTW', '暗影穹殿敕令', '『強者』烏弗蘭族長坐在他的大廳裡控制著整個蠻荒岩臺。我研究過他，這位族長是個有耐性的維酷人，滿腦子都是策略與征戰。他也偏好待在後方，不想過度涉入戰鬥之中。$B$B我要他死!$B$B我已經寫下一道敕令。站在族長面前，把它大聲唸出來。$B$B<公爵富饒興味地抬起眉毛。>$B$B這應該...至少會讓他焦躁起來。', '暗影穹殿的蘭克洛公爵命令你在『強者』烏弗蘭族長面前朗讀暗影穹殿敕令，然後殺了他。', '', '去找寒冰皇冠的蘭克洛公爵。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12944 AND `locale` = 'zhTW';
