INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12953, 'zhTW', '燒吧，華爾基倫，燒吧', '這個箱子裝滿了燃燒魚叉。你想起在外頭有看到魚叉獵槍與乾草堆。$B$B伊娃也許會感激你的額外努力並給予你適當的獎勵。', '使用華爾基倫魚叉獵槍燒毀6個乾草堆。', '', '去找風暴峭壁的『復仇』伊娃。', '已縱火', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12954 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12954, 'zhTW', '苦痛露天競技場:伊格卓斯!', '我還在想你什麼時候才會出現呢，$N!過去的血色競技場勇士會吸引超多人來看比賽!我們會賺大錢的，老兄!好多好多錢!$B$B總而言之，這個垃圾場就是祖爾德拉克。這些冰霜食人妖好像都把它當廁所在用。我不知道，不過你問我的話我會說這整個地方都過時啦!但是誰管它呢，對吧?我們是來賺錢的!$B$B你知道規矩，$N。你準備好了就跟我說一聲，咱們就開始表演啦!', '進入苦痛露天競技場並且擊敗伊格卓斯!然後去找『食人妖僕從』烏丁領賞。', '已擊敗尤格德拉斯', '去找祖爾德拉克的食人妖僕人伍德林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12955 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12955, 'zhTW', '消滅競爭者', '呣呣咈呣咈咈咈...$B$B<跳躍者清了清喉嚨。>$B$B抱歉噢。有的時候很難聽懂我在講什麼。你知道的。$B$B我得再提一下，如果你哪天經過蠻荒岩臺，就是西邊山脈再過去那兒時，你記得消滅那兒的競爭者。$B$B具體地說呢，我要你去找席格芮‧冰誕、忠誠的埃弗睿、奧努祖與汀基‧芯哨單挑並且讓他們在維酷面前出醜。', '暗影穹殿的跳躍者要你去單挑並擊敗席格芮‧冰誕，忠誠的埃弗睿，奧努祖，以及汀基‧芯哨。', '', '去找寒冰皇冠的跳躍者。', '已擊敗希格麗德·冰生者', '已擊敗忠誠者艾弗倫', '已擊敗歐努宗', '已擊敗汀奇·威克惠斯', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12956 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12956, 'zhTW', '希望的火花', '很顯然，這不只是一塊普通的金屬而已。$B$B它不像任何你所熟悉的礦石，質地既堅硬又不容易斷裂，而且遠比看起來輕的多，而且就算冷卻了也還發著光。$B$B靠近一點看，你發現在金屬的表面下閃耀著索林姆的符文...', '你要把精煉微光礦石帶去給風暴神殿的索林姆。', '', '去找風暴峭壁的索林姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12957, 'zhTW', '風鑄奴隸', '鐵矮人在西南方，雪迅平原的西側的山丘上挖了一個礦坑。他們利用被俘虜的機械地精，也就是守護者彌米爾的僕從們來替他們採礦。$B$B我不知道這些機械地精是從哪裡來的，也不知道他們自由了以後會做什麼，但也許我們能夠得到他們的幫助。$B$B前往冰凍礦坑，$n，然後將他們從奴役中解放出來。問問他們願不願意與我們一同對抗鐵矮人的暴行。', '石崖避難所的『塑岩者』石崖要你釋放6個被俘虜的機械地精，並殺死3個風鑄監工。', '', '去找風暴峭壁的『塑岩者』石崖。', '嘗試釋放被俘的機械地精', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12958 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12958, 'zhTW', '貨品：血玉護符', '一間有錢的貨運公司訂購了整套的血玉護符要賣到幽坑城去。如果你能夠給我一個護符，我可以給你一個達拉然珠寶匠徽章作為回報。', '將一個維酷護符、一個暗玉以及一個血石合併，以製成一個血玉護符，將其交給達拉然的提摩西‧瓊斯。你可以從北裂境的任何一個維酷人身上找到維酷護符。', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12959, 'zhTW', '貨品：發光象牙刻像', '一間有錢的貨運公司訂購了整套的發光象牙刻像要賣到幽坑城去。如果你能夠替我帶來一個刻像，我可以給你一個達拉然珠寶匠徽章作為回報。', '將一個北地象牙、一個玉髓以及一個暗影水晶組合成發光象牙刻像，然後交給達拉然的提摩西‧瓊斯。你可以從北裂境的任何一個鍬牙或長毛象身上找到北地象牙。', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12960, 'zhTW', '貨品：邪惡烈日胸針', '一間有錢的貨運公司訂購了整套的邪惡烈日胸針要賣到幽坑城去。如果你能為我找來一個，我可以給你個達拉然珠寶匠徽章作為回報。', '把一個鐵矮人胸針、一個巨黃晶以及一個烈日水晶組合成邪惡烈日胸針，交給達拉然的提摩西‧瓊斯。你可以從北裂境的任何一個鐵矮人身上找到鐵矮人胸針。', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12961 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12961, 'zhTW', '貨品：錯綜龍骨刻像', '一間有錢的貨運公司訂購了整套的錯綜龍骨刻像要賣到幽坑城去。如果你能夠給我一個，我可以給你個達拉然珠寶匠徽章作為回報。', '把一個元龍骨、一個烈日水晶以及一個暗玉組合成錯綜龍骨刻像，並交給達拉然的提摩西‧瓊斯。你可以從北裂境的任何一頭元龍身上取得元龍骨。', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12962 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12962, 'zhTW', '貨品：光亮護甲聖物', '一間有錢的貨運公司訂購了整套的光亮護甲聖物要賣到幽坑城去。如果你能夠給我一套，我可以給你一個達拉然珠寶匠徽章作為回報。', '把一個元素護甲碎塊、一個血石以及一個巨黃晶組合成光亮護甲聖物，並交給達拉然的提摩西‧瓊斯。你可以從北裂境的任何一個亡魄身上取得元素護甲碎塊。', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12963 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12963, 'zhTW', '貨品：移形烈日珍品', '一間有錢的貨運公司訂購了整套的移形烈日珍品要賣到幽坑城去。如果你能夠給我一份，我可以給你一個達拉然珠寶匠徽章作為回報。', '把一個天譴珍品、一個烈日水晶以及一個暗影水晶組合成移形烈日珍品，並交給達拉然的提摩西‧瓊斯。你可以從北裂境的任何一個天譴軍身上取得天譴珍品。', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12964 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12964, 'zhTW', '黑暗礦石', '雪迅平原西方的冰凍礦坑，那裡的風鑄鐵矮人建了一座以奴隸運作的礦坑。$B$B它在戰線後方遠處，所以我們一直無法察探那裡的狀況，但我的斥候回報，說他們看過那裡運出一車又一車黑色，病態的礦石。', '把5個黑暗礦石樣本帶去給石崖避難所的『塑岩者』石崖。', '', '去找風暴峭壁的『塑岩者』石崖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12965 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12965, 'zhTW', '洛肯的賜禮', '負責指揮風鑄鐵矮人的傢伙叫做符文先知瓦杜然。雖然我從來沒有看過他們，但相傳他的主人，也就是奪取了奧杜亞的守護者洛肯，據說把強大的泰坦神器賜給了瓦杜然。$B$B這就能夠解釋我的手下從風鑄戰士身上所見到的力量與殘暴是從何而來了。$B$B瓦杜然的基地，尼達維里爾就坐落在西南邊，過了雪迅平原的地方。前往該處，$n，消除他的力量。毀掉洛肯給他的賜禮，幫我們削弱洛肯追隨者的力量。', '破壞洛肯之怒、洛肯之力與洛肯之恩賜，然後返回石崖避難所向『塑岩者』石崖回報。', '', '去找風暴峭壁的『塑岩者』石崖。', '洛肯的憤怒已摧毀', '洛肯的力量已摧毀', '洛肯的恩惠已摧毀', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12967 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12967, 'zhTW', '與元素作戰', '思諾利曾是我國的驕傲。一位強大的戰士，用他的棍棒擊敗了許許多多的敵人。$B$B我們尊敬他，但他已經不再是那個思諾利了。年紀大了，使他的感覺變得遲鈍，力量也衰退了。但他仍舊和從前一樣驕傲，絕不肯錯過任何一場戰鬥。$B$B說到戰鬥，我們正在冷卻斐雍之砧，好把它帶回去。殘存的火焰亡魄還在持續抵抗。請幫思諾利重現他往日的榮耀吧，$r。引導他對付他的敵人。', '尼約梅爾德要你陪伴思諾利到斐雍之砧去，並幫助他殺死10個沸騰亡魄。', '', '去找風暴峭壁的尼約梅爾德。', '沸騰亡魂已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12968 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12968, 'zhTW', '優爾達的愚行', '一切都是那個女巫起的頭，『颶語者』優爾達來到了我們的村子。她竟敢污衊我們高貴的傳統，滔滔不絕地講出巫妖王那些劇毒的承諾。$B$B她離開的時候身上理應插了一把劍的，不過她的魔法很強悍，所以她逃掉了。$B$B去華爾基倫最大的建築物找她，然後讓她知道不該戲弄我們。', '布倫希爾達村的『復仇』伊娃要你去華爾基倫殺死『颶語者』優爾達。', '', '去找風暴峭壁的『復仇』伊娃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12969 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12969, 'zhTW', '那是你的哥布林嗎?', '我相信那就是你在找的那個綠色小傢伙。如果我是你，我會在海迪尼爾人把他劈成兩半之前插手阻止。$B$B你在海茲競技的時候到來，所以所有的參加者必定得要接受你的挑戰。沒有什麼能夠阻止你把你綠色的朋友給帶走。', '挑戰艾格奈塔‧泰斯多達以拯救奇夫‧嘶炫。成功之後回去找布倫希爾達村的『巫婆』洛莉拉。', '', '去找風暴峭壁的『巫婆』洛莉拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12970 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12970, 'zhTW', '海茲競技', '不知道你注意到沒有?在第一場格鬥中，擊敗你的海迪尼爾對手，你就獲准參加了海茲競技 - 海迪尼爾間的盛大格鬥賽事，優勝者可以獲得侍於索林姆身側的榮耀。$B$B海茲競技令我感到猶如身陷囹圄般的痛苦，我希望參加賽事，但是我的年華已逝，身體也羸弱得無法成為海迪尼爾的鬥士。$B$B如果你願意傾聽，我倒是為你量身訂做了一套計畫。', '聆聽『巫婆』洛莉拉的計畫。', '', '去找風暴峭壁的『巫婆』洛莉拉。', '聆聽洛克莉拉的提議', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12971 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12971, 'zhTW', '接受所有挑戰', '我就直說吧。好消息是，因為你擊敗了艾格奈塔，在下一輪比賽中，你將是場上的焦點。$B$B壞消息是，你的對手也都是第一輪中的優勝者。別奢望輕易過關。', '布倫希爾達村的『巫婆』洛莉拉，要求你擊敗6個挑戰者。', '', '去找風暴峭壁的『巫婆』洛莉拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12973 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12973, 'zhTW', '銅鬚兄弟', '成功了!我們終於拿到拱心石了...它好美啊!我曾經多次環遊世界，但這東西又再次喚起了我的不安與興奮。不過，我想現在不是呆呆的站著看的時候了，我們得快點逃出去。$B$B跳上我的飛行器，在出去的路上幫忙掩護我!', '陪同布萊恩‧銅鬚，搭乘其飛行器前往霜堡。', '陪同布蘭·青銅鬍前往霜寒堡', '去找風暴峭壁的維洛格‧冰吼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12974 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12974, 'zhTW', '勇士的呼喚!', '呼，下面那根本不叫打鬥。只不過是幾個傢伙圍著旗子在跳舞罷了。$B$B你想要來點真正的打鬥嗎?因為我手上可是有最熱門的票。$B$B聽過葛爾薩克和烏丁嗎?在外域經營血之環競技場的那個哥布林與食人妖?他們現在來到了北裂境，而且他們在祖爾德拉克開了全新的鬥技俱樂部。如果你有興趣的話，就去水晶之歌東邊的祖爾德拉克吧。他們在中央的大競技場裡面。告訴他們是維克斯派你去的!', '到祖爾德拉克的苦痛露天競技場找葛爾薩克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12975 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12975, 'zhTW', '紀念', '索林姆一定告訴過你，使我們分道揚鑣的那場悲劇。$B$B這是在雷殞之地發生的，就在東北方。那裡有座冰凍的化石，還有許多靈魂徘徊，都不斷的使人想起那黑暗的一天。$B$B如果要我的子民原諒索林姆，就一定得把那些形象給換掉。我們一定得建造一座紀念碑，為我們的人民帶來心靈的平靜。$B$B前往該處，$r。收集在那一天粉碎的霍迪爾號角碎片。', '丹尼弗蘭的裘庫姆王要求你，去雷殞之地收集8個號角碎片。', '', '去找風暴峭壁的裘庫姆王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12976 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12976, 'zhTW', '給逝者的紀念碑', '把這些碎片帶去找尼約梅爾德。他會用這個聖物的殘片建造一個偉大的紀念碑。$B$B願它能夠撫平我的子民這些年來所背負的傷痛，治癒傷痕。$B$B願它的存在能夠帶領我們邁向新的時代，再次站在索林姆身側奮戰。$B$B去吧，$c，尼約梅爾德在等著你。', '裘庫姆王要你把霍迪爾號角碎片送去給丹尼弗蘭的尼約梅爾德。', '', '去找風暴峭壁的尼約梅爾德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12977 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12977, 'zhTW', '霍迪爾的呼喚', '你為丹尼弗蘭的巨人做了一件無與倫比的事。沒有你的幫助，這座紀念碑就不會存在。$B$B你靜靜的想著它的宏偉，心中充滿了某種感覺。這些感覺使你心中浮現想法與影像...以及一種急迫感。$B$B感覺消逝了以後，你已經明白要怎麼做了。雷殞之地無法安息的靈魂一定要得到解脫。$B$B在你出發的時候，你發現手中握著一把靈體號角。', '在雷殞之地對5個尼弗蘭祖先與5個不安的霜誕鬼魂的屍體吹響霍迪爾號角。', '', '去找風暴峭壁的裘庫姆王。', '尼弗倫始祖已釋放', '不安的寒冰誕生者已釋放', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12978 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12978, 'zhTW', '面對風暴', '我曾像石崖一樣，在奧杜亞擔任守護者的工匠。但隨著洛肯叛變，我將鐵錘轉向了新的敵人。$B$B當我們有多餘人手的時候，我會帶領小隊襲擊尼達維里爾，好減輕防衛者的負擔，但是現在我們的戰線已經瀕臨崩潰了。$B$B你已經證明了自己是個有能力的戰鬥員，也是個可靠的盟友。也許你願意帶著我們的旌旗，然後對西南方雪迅平原後面的鐵矮人要塞，尼達維里爾發動攻擊。', '石崖避難所的布魯爾‧鐵禍要你殺死10個尼達維里爾的風鑄者。你可以殺死風鑄勇士、風鑄魔導師或是風鑄戰爭魔像。', '', '去找風暴峭壁的布魯爾‧鐵禍。', '尼達維里的風暴鍛爐者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12979 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12979, 'zhTW', '黑暗護甲', '與其他魔像的防禦裝備比起來，這塊護甲片既厚又大。檢驗了魔像的屍體之後，你發現這個厚甲片，似乎是事後加工裝上的。$B$B為什麼鐵矮人要在他們的魔像上，加裝這種多餘又大小不合的護甲?$B$B也許布魯爾·鐵禍能夠檢驗一些從戰爭魔像上取下的護甲片，他就能夠得到答案。', '把4塊黑暗護甲樣本帶去給石崖避難所的布魯爾·鐵禍。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12980 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12980, 'zhTW', '護甲的秘密', '這塊護甲片的外觀令人困惑，但我們得盡可能地從中查出資訊來。這可能是瓦杜然的陰謀。$B$B他下了很大的功夫採掘、精鍊、鍛造與測試這塊金屬。$B$B在東方，山地的北面，有座建築物名叫彌米爾工坊。它已經荒廢了一段時間，但如果我們運氣夠好，應該還有些侍者能夠運作。把護甲片帶去那裡，盡可能地查出資訊來。', '將黑暗護甲片帶去彌米爾工坊，要求侍者托克檢驗它。當你完成了以後，回到石崖避難所找布魯爾‧鐵禍。', '', '去找風暴峭壁的布魯爾‧鐵禍。', '已調查護甲板', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12981 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12981, 'zhTW', '熱與冷', '當你凝視著鐵砧的時候，你回想起最近所做的事情，尤其是將這個神器帶來此處的那件事。$B$B你突然想到你能做些什麼了。在東邊，悶燒的廢金屬散落在地面上…都是此地戰鬥的殘留物。$B$B如果能夠將之冷卻收集起來，霜巨人就能夠得到足夠的金屬，而且也能夠清理掉戰爭留下的垃圾。', '你要前往霜域湖，殺死易怒的亡魄，然後在斐雍之砧對著悶燒的廢金屬使用寒冰精華。接著，你必須收集6個冰凍鐵碎塊並回到丹尼弗蘭的斐雍之砧處。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12982 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12982, 'zhTW', '黯刃囚犯', '現在我回來了，我確信男爵會想要我救回我的手下。我看得出來他們只是勉強守住這裡而已。巫妖王的軍隊差不多要突破防線了，若沒有被俘虜的那群死亡騎士，我們不可能守得住。$B$B你能再幫助我一回嗎，$n?$B$B回到卓頓海姆，並且把他們放出籠子外。$B$B不管你要怎麼做，給我弄開那些該死的鎖。那些維酷人身上應該有鑰匙。$B$B不管怎樣，把我的手下給救出來!', '暗影穹殿裡被搶劫的維倫，要你釋放8名黯刃囚犯。你可以在整個卓頓海姆區域找到關著囚犯的籠子。', '', '去找寒冰皇冠的被搶劫的維倫。', '黑鴉之刃的囚犯已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12983 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12983, 'zhTW', '最後一頭', '從我有記憶以來，我們最好的熊就都是來自東邊的凜冬洞窟。$B$B也許這樣的時光終於到了盡頭。凜冬洞窟被一群貪婪的蟄猛巨蟲攻陷了，野生的熊也全部絕跡。$B$B但如果你能夠找到倖存的熊族母，我向你保證，她絕對比任何眷養長大的熊還要驍勇善戰。$B$B帶著這個鞍座去凜冬洞窟，並拯救一頭倖存的族母。祝你好運。', '布倫希爾達村的艾絲翠德‧畢優利塔，要你拯救一頭凜冬洞窟的冰喉族母。', '', '去找風暴峭壁的艾絲翠德‧畢優利塔。', '已救出冰顎女王', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12984 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12984, 'zhTW', '『風暴降生』瓦杜然', '我們別無選擇，$n。你在彌米爾工坊所得知的訊息意味著我們必須在瓦杜然完成他的新武器並使用它之前趕緊行動。$B$B即使是此刻，避難所的防衛者也在努力奮戰，替我們爭取時間對付『風暴降生』瓦杜然。$B$B你必須越過西南方的雪迅平原前往尼達維里爾，然後找出瓦杜然，與他作戰。但你不必孤軍奮戰。帶著這支戰爭號角，當你準備好要面對他的時候就吹響這號角。布魯爾跟我會加入戰鬥幫助你。', '找到『風暴降生』瓦杜然後，使用石崖的戰爭號角。擊敗『風暴降生』瓦杜然，然後返回石崖避難所向『塑岩者』石崖報告。', '', '去找風暴峭壁的『塑岩者』石崖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12985 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12985, 'zhTW', '鑄造頭部', '你好，$r。$B$B既然你仍舊想要取得我們人民的信任，裘庫姆王覺得有項工作很適合你。$B$B我設計了另外一樣神器，能夠讓我們的堡壘獲得霍迪爾的祝福。我幾乎已經收集到所有需要的原料了。唯一缺少的就是我們死去敵人的眼睛。$B$B帶著這個工具，然後從散落在原野的鐵巨人屍體上面收集眼睛。', '丹尼弗蘭的尼約梅爾德要你去霜域湖，在死亡的鐵巨人身上使用鑽石尖端之鎬，收集8個風鑄之眼之後帶回去給他。', '', '去找風暴峭壁的尼約梅爾德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12986, 'zhTW', '泰坦的命運', '諾甘農之核不在這裡。我不確定你為何尋找它，$r，我也不確定你真的瞭解，你所追求的物品有什麼用途。$B$B在我進一步協助你之前，我希望你能夠先幫助我。我最近吸收了一些關於看守者索林姆的知識。他的地位遭到挑戰，而命運尚未明朗。這使我感到很困惑，因為我並不認識其他的看守者。用這個資料庫來檢查他們位於東北方的神殿，然後把資訊帶回來給我。', '足跡冷原的克里圖斯要你前往發明神殿、凜冬神殿、生命神殿以及秩序神殿，使用資料庫來檢驗每個區域。', '', '去找風暴峭壁的克里圖思。', '已調查發明神殿', '已調查寒冬神殿', '已調查生命神殿', '已調查秩序神殿', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12987 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12987, 'zhTW', '放置霍迪爾之盔', '頭盔已經鑄造好了。$B$B你的付出絕不會被忽視，小傢伙。雖然還有很多事得辦，但我們霍迪爾之子很感激你所做的一切。$B$B為了回報你，我把將頭盔獻給國王和兄弟的機會讓給你。$B$B飛到我面前的冰柱頂端，並且把這個石板上的字念給我們的人民聽。$B$B享受這份殊榮吧，$c。在你之前從未有外來者得到過同樣的榮耀!', '尼約梅爾德要你飛到丹尼弗蘭北邊冰柱的頂端，並使用宣言石板。', '', '去找風暴峭壁的尼約梅爾德。', '霍迪爾之盔已安裝', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12988 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12988, 'zhTW', '摧毀熔爐!', '我先前愚蠢的認為瓦杜然在那維爾搖籃的計畫，就是南邊那個巨大的工地，只不過是為了紀念「守護者」洛肯的殘忍而建造的怪紀念碑。$B$B現在我們知道真相了，那是用來對付我們以及我們盟友的武器。我們不能讓這個鐵巨像完成，$n，否則那就會是避難所的末日。$B$B前往那維爾搖籃，找出風鑄工匠所使用的電光熔爐，然後把它們破壞掉。', '用石崖的炸彈摧毀北方電光熔爐、中央電光熔爐以及南方電光熔爐，然後回到石崖避難所向『塑岩者』石崖回報。', '', '去找風暴峭壁的『塑岩者』石崖。', '北方雷霆熔爐已破壞', '中央雷霆熔爐已破壞', '南方雷霆熔爐已破壞', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12989 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12989, 'zhTW', '滑溜的黑暗', '這些邪惡的蟄猛巨蟲已經佔領了凜冬洞窟的大半部分。牠們是卑劣的生物...洛肯的孩子，專門吸吮索林姆殘渣的兄弟。$B$B身為索林姆的僕人，那些渣滓我們見一個殺一個。你會在村外東邊找到那個洞窟。', '艾絲翠德‧畢優利塔要你到布倫希爾達村東邊的凜冬洞窟殺死8隻極餓的蟄猛巨蟲。', '', '去找風暴峭壁的艾絲翠德‧畢優利塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12990 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12990, 'zhTW', '蟲洞', '給我弄些材料來，我就教你怎樣使用你的蟲洞製造器。', '為Jon LeCraft帶一些材料來，防止他迅速死亡，然後學會一個很棒的新法術。', '', '去找Designer Island的Jonathan LeCraft。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12991 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12991, 'zhTW', '打擊他們的弱點', '石崖妨礙那維爾搖籃那些鐵矮人的計畫很不錯，我也有我自己的點子。只要沒有工匠，建造鐵巨像的進度就會停擺。$B$B那維爾搖籃就在屏護著避難所的這座山丘的南邊。去那裡殺掉所有擋路的風鑄工藝師。他們也許跟從前的我們相去不遠，但他們建造的武器卻會威脅到我們全部的人。', '殺死10個風鑄工藝師，然後返回石崖避難所找布魯爾‧鐵禍。', '', '去找風暴峭壁的布魯爾‧鐵禍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12992 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12992, 'zhTW', '打死那些該死的維酷人!', '卓頓海姆的那些臭維酷人欠打!$B$B$n打死他們!', '暗影穹殿的暗邪要你在卓頓海姆區域殺死15個維酷人。', '', '去找寒冰皇冠的暗邪。', '尤頓海姆的維库人已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12993 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12993, 'zhTW', '巨大的威脅', '你延緩了鐵巨像的進度，做的很好，但我擔心我們不過是讓鐵矮人更加堅定完成這項武器的意志罷了。$B$B即使是現在，他們也不斷的把新的勞力送進來，然後交由監督者壓榨他們。也許我們終究無法阻止他們完成巨像。如果事情往這個方向發展的話，我們就得弄清楚我們到底要對抗什麼東西。回去那維爾搖籃，到南邊找出詳述巨像攻防能力的文件。應該在底層的帳篷與熔爐附近。', '取得巨像攻擊設計說明書與巨像防禦設計說明書，然後帶去給石崖避難所的『塑岩者』石崖。', '', '去找風暴峭壁的『塑岩者』石崖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12994 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12994, 'zhTW', '間諜獵人', '你與丹尼弗蘭居民的密切往來帶來了意想不到的發現。$B$B舉例來說，你發現你似乎聽的懂獸母的喉音吼聲和尖銳的叫聲…至少你是這麼想的。$B$B她似乎感覺到要塞外頭有危險，要你去處理。$B$B她用前掌將繞在脖子上的鐵鍊解下，丟在你腳前。當你撿起鍊子的時候，你注意到上頭還連著一根飽經風霜的利牙…', '你必須到遠古寒冬山谷擊敗3個風鑄間諜。在死去座狼的屍體旁使用以太座狼之牙可以召喚一頭以太霜座狼使隱藏的敵人暴露行蹤。當你除去了山谷中的間諜以後，回到丹尼弗蘭找冰霜座狼獸母。', '', '去找風暴峭壁的冰霜座狼獸母。', '風暴鍛造滲透者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12995 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12995, 'zhTW', '留下我們的記號', '我們得從許多不同方面來攻擊卓頓海姆的維酷人。蠻力當然是一種好方法，但我偏好更有智慧的手法。$B$B我要你去削弱他們的士氣。$B$B我的手下替你打造了幾支旌旗。我要你把這些旌旗拿去插在倒下的維酷人屍體上。$B$B讓這些旌旗不斷提醒他們，他們要面對的威脅可遠比巫妖王的怒氣來的直接。', '暗影穹殿的史力弗男爵，要你將15枝黯刃旌旗插在卓頓海姆區域找到的維酷人屍體身上。', '', '去找寒冰皇冠的史力弗男爵。', '已在維库人屍體旁插上黑鴉之刃旗幟', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12996 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12996, 'zhTW', '熱身', '你很幸運，姊妹。像這樣的熊族母已經絕跡好些年了。$B$B如果你缺乏騎乘的技巧，一頭好熊也不會為你帶來太多好處。$B$B我要讓你在齊爾加瑞克身上練習一些技巧。他是我們抓過最大隻的雪人，所以你得小心點。如果被他痛扁了一頓，只要走開就好了...我們把他綁起來可是有理由的。', '布倫希爾達村的艾絲翠德‧畢優利塔要你用戰熊族母韁繩來擊敗齊爾加瑞克。', '', '去找風暴峭壁的艾絲翠德‧畢優利塔。', '已擊敗基爾加拉克', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12997, 'zhTW', '進入深淵', '打敗拴住的對手是一回事。和不被束縛的熊騎兵戰鬥，又是完全不同的另外一回事。$B$B去尖牙之淵，運用一切你所學過的技能，擊敗你的對手。祝你好運，我的姐妹。$B$B榮耀與你同在，你會成功的。', '布倫希爾達村的艾絲翠德‧畢優利塔要求你，在尖牙之淵裡使用戰熊族母韁繩，擊敗6頭海茲競技戰熊。', '', '去找風暴峭壁的艾絲翠德‧畢優利塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12998 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12998, 'zhTW', '風暴之芯', '根據你從那維爾搖籃取回的文件看來，這座鐵巨像只剩下一個關鍵部分沒有完成 -- 那就是風暴之芯。$B$B沒有了它，鐵巨像的武器就遠比設計中來的弱。如果我們可以避免監督者那維爾取得核心，我們就有機會擊敗那座巨像!$B$B你所找到的文件指出核心位於奧迪斯，位於南邊遠方的一座泰坦設施。它的入口位於一座俯視伯爾之息河谷的高峰南方。', '石崖避難所的『塑岩者』石崖要你前往奧迪斯，阻止監督者那維爾取得風暴之芯。', '', '去找風暴峭壁的『塑岩者』石崖。', '嘗試取得風暴之心', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13000 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13000, 'zhTW', '緊急措施', '群山中的寒氣非常的嚴酷。不過一兩天，我們就把墜毀殘餘的木頭通通給燒光了。$B$B我們在東方的洞穴裡看見了一些座狼。我要你找到這個洞穴，並且把毛皮弄來。聽起來也許沒差多少，但這可是凍死和活著看到明天太陽的差別。$B$B座狼並不會單獨狩獵，所以我要給你一顆閃光彈。當你被數量壓倒的時候，這應該能幫你爭取一點時間。', '血衛士洛嘉要你去東邊的吉摩拉克獸穴，並取得6張座狼毛皮。', '', '去找風暴峭壁的血衛士洛嘉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13001 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13001, 'zhTW', '打造霍迪爾之矛', '時候到了，小$c。群星早已預言了這天的到來。$B$B偉大的霍迪爾親自賜給我預示，向我顯現了製造一柄至高神器的秘密，那就是霍迪爾之矛。$B$B我們一定得聽令!如果我們未能收到這項賜禮，末日一定接踵而來。$B$B我召喚你來協助我進行這項神聖的任務。$B$B越過峽谷，進入凜冬洞窟，從冰坑中收集永霜裂片，然後從洞窟外的長毛象身上收集毛皮。', '丹尼弗蘭的博學者蘭德維爾要你從凜冬洞窟的深處收集3個永霜裂片，以及從遠古寒冬山谷的堅忍的長毛象身上取得3個堅忍的長毛象皮革。', '', '去找風暴峭壁的博學者蘭德維爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13003 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13003, 'zhTW', '屠龍高手', '霍迪爾之矛所代表的是戰鬥中的英勇。$B$B他的存在本身就為所有進入丹尼弗蘭的人注入了對榮耀的深切渴求。事實上，光是待在它附近，就讓你非常想要測試一下自己的實力。$B$B看了看地平線，你的視線在一頭野生巨龍飛過的時候牢牢盯緊了牠。$B$B決定了。在你跟牠之間，註定只有一個能夠看見明天的太陽...', '你要用霍迪爾之矛在遠古寒冬山谷挑戰一頭野生巨龍。一旦與牠接觸，你就得與之奮戰，至死方休。', '', '', '野生巨龍已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13004 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13004, 'zhTW', '完美寶石', '戰爭一觸即發，我們都要竭盡所能！我的長處在於切割寶石，而且不是普通的寶石，是完美的寶石！如果你能弄些未切割的寶石來給我，我也可以教你學會這種技術。切割完美寶石能讓你在切割諾森德地區出產的優秀品質寶石時，有機會切割出一顆具有更高屬性的完美寶石。', '將茶晶石、黑玉和暗影水晶各兩顆交給無畏要塞的奧雷斯托斯。', '', '去找北風凍原的艾雷斯托思。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13005 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13005, 'zhTW', '土靈誓約', '許多年來我忽視了我的職責，沉溺於失敗與自憐之中。$B$B但勇敢的土靈卻不然。他們以生命守護造物者殿堂的誓言依舊維持不輟。$B$B即使在此刻，他們也勇敢無私地與腐敗的鐵矮人奮戰，等待扭轉局面的時機到來。$B$B而時機，已經到來了。我們要集合殘存的土靈防衛者，率領他們取得光榮的勝利。吹響群山號角，將他們召來你的身邊，奪回造物者殿堂吧。', '造物者殿堂的索林姆要你用群山號角召來土靈，擊敗20個鐵矮人與7個鐵哨兵。', '', '去找風暴峭壁的索林姆。', '鐵哨兵已擊殺', '鐵矮人攻擊者已擊殺', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13006 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13006, 'zhTW', '油光煥發', '當你靠近頭盔的時候，你注意到嚴寒的環境已經在神器的表面產生了影響。現在看起來只是薄薄的一層冰，但顯然將會把頭盔整個吞噬掉。$B$B為了不讓你辛勤努力的成果白費，你決定找出解決的方法。$B$B就在你打算出發的時候，頭盔的眼睛閃爍了一下，凜冬洞窟的影像進入了你心中。', '你要進入丹尼弗蘭西方的凜冬洞窟，並收集5份黏性油。然後回到丹尼弗蘭將油使用在霍迪爾之盔上。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13007 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13007, 'zhTW', '鐵巨像', '我們沒能阻止鐵巨像竣工，$n，這代表我們沒有別的選擇，只能與它作戰了。$B$B布魯爾已經策劃了一個能夠攻擊巨像唯一弱點的計畫。$B$B不管巨像的護甲有多厚，遇上酸液時仍舊十分脆弱。使用雪迅平原北端的寶珠控制一隻蟄猛巨蟲，然後利用它來對付鐵巨像。如果你對於駕馭這些生物有需要幫忙，請找旁邊的馭蟲者談談。', '用被馴服的蟄猛巨蟲擊敗鐵巨像，然後返回石崖避難所向『塑岩者』石崖回報。', '', '去找風暴峭壁的『塑岩者』石崖。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13008 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13008, 'zhTW', '天譴戰術', '我們碰上了意想不到的事情!我們在山側炸出了一個洞穴，然後衝進了天譴岸地。天譴軍的反擊非常強烈，我們撐沒多久就潰敗了。我們撤退到谷地，以彈雨伺候追上來的天譴軍。這抵擋了他們一陣子，直到...那些混蛋開始用十字軍當做活盾牌。我們因為擔心殺死自己的士兵而不得不停火。$B$B解救那些困在基地外面原野上的士兵吧，$c!', '銀白先鋒駐地的十字軍指揮官恩塔利要你解救8位被網住的十字軍。', '', '去找寒冰皇冠的十字軍指揮官恩塔利。', '被蛛網纏繞的十字軍已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13009 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13009, 'zhTW', '新的開始', '我們的人民是否能夠再次愛戴索林姆仍舊是件不確定的事。$B$B如果別的東西都不行的話，也許這套盔甲能夠讓他想起那些日子，當時我們還榮耀地並肩而立，所向無敵。', '尼約梅爾德要你把重鑄護甲帶去風暴神殿給索林姆。', '', '去找風暴峭壁的索林姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13010 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13010, 'zhTW', '克洛米爾，風暴之錘', '在我奪回造物者神殿的家園之前，還剩下一樣工作。$B$B一定得找到克洛米爾。$B$B在那命運之日，我以全部的力量與憤怒將它擲向大地。隨即產生了一場巨大的爆炸。$B$B許多年來我一直以為失去了它，但是我一定得確認才行。$B$B回到裘庫姆王那兒，問問他是否知悉任何有關戰錘的下落。', '索林姆要你與丹尼弗蘭的裘庫姆王談話，並瞭解他對克洛米爾知道多少。', '', '', '克羅米爾的命運已發現', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13011 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13011, 'zhTW', '解決喬克塔', '蟄猛巨蟲是需要盡快處理的棘手生物。要是讓牠們有生存空間，牠們就會像野兔一樣繁殖，像野火一樣蔓延。$B$B西南方的凜冬洞窟出現了牠們的蹤跡。不趕緊殺死母蟲的話，牠們就會在我們的地盤上落地生根。$B$B她抗拒不了食物的誘惑。帶著這把小刀，從牠們洞穴裡的熊屍上切一塊腹肉，然後把肉放在靠近她的坑洞附近。趁她進食的時候殺了她。', '丹尼弗蘭的裘庫姆王要你去凜冬洞窟殺死喬克塔。', '', '去找風暴峭壁的裘庫姆王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13012 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13012, 'zhTW', '沙迪斯長者', '', '很慶幸這片大地的居民仍然會對古老的種族表達敬意。我祝你平安，$n，並且送你這個硬幣...。', '', '', '', '', '', '', 0);
