INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13036, 'zhTW', '榮譽至上', '通往救贖之道漫長無盡啊，年輕的$c。我們打遍了各大陸，甚至穿越了世界，來到了此處。現在，我們要面臨最大的挑戰:毀滅巫妖王與他的天譴軍團。哎，我們卻是各自為政地在進行這場戰鬥。部落與聯盟彼此作戰，無法援助我們。我們一定得為了自己奮戰不懈!我們又有什麼別的選擇呢?你願意加入嗎?把你的力量借給我們，$c!我的指揮官，恩塔利，正在等待著你。', '向銀白先鋒駐地的十字軍指揮官恩塔利報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13052 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13052, 'zhTW', '空中偵察', '謝謝你幫維斯雷修好了那架飛行器。你願意再幫我們一個忙嗎？西北方有一股不尋常的氣流襲來。我已經指派了飛行員維克去偵察情況，不過他恐怕還需要一名副駕駛員。如果你覺得自己能勝任的話，就飛往湖濱降落場去找他吧。喔，記得告訴他，是我派你去的。', '卡爾維特教授要你飛往湖濱降落場，與飛行員維克談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13055 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13055, 'zhTW', '洞穴中的解藥', '見到友善的面孔真好。搞不好是最後一次了吧。$B$B我還來不及逃走，就一頭蟄猛巨蟲用毒刺螫了我一下。老兄，我可以感覺到我的身體漸漸麻木。$B$B我需要一個毒腺來製作解毒劑，還有一些山洞裡的洞穴蘑菇…它們能延緩毒性。$B$B請快點，我沒有多少時間了。', '在吉摩拉克獸穴裡的追蹤者瓦爾吉，要求你替他採得1個蟄猛巨蟲的毒素腺體和8個洞穴蘑菇。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13057 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13057, 'zhTW', '造物者殿堂', '是時候了，$N。我準備要面對洛肯了。讓我們前往造物者殿堂，挑戰我兄弟的部隊。那個傻瓜會後悔他惹火了我。', '到造物者殿堂的東南邊緣找索林姆，造物者殿堂就在丹尼弗蘭的西北方。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13065, 'zhTW', '歐漢茲長者', '', '很慶幸這片大地的居民仍然會對古老的種族表達敬意。我祝你平安，$n，並且送你這個硬幣...。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13066 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13066, 'zhTW', '由羅克長者', '', '很慶幸這片大地的居民仍然會對古老的種族表達敬意。我祝你平安，$n，並且送你這個硬幣...。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13067 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13067, 'zhTW', '修干加達長者', '', '很慶幸這片大地的居民仍然會對古老的種族表達敬意。我祝你平安，$n，並且送你這個硬幣...。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13069 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13069, 'zhTW', '把他們射成刺蝟', '卓頓海姆擁有空中防禦，包括元龍騎兵和魚叉獵槍。他們將其集中部署在北面和西面 - 防線上最脆弱的地方。$B$B我們就是要以子之矛，攻子之盾!$B$B<跳躍者以單眼緊盯著你，並且瘋癲地格格笑著。>$B$B前往西南方的英靈殿，奪下峭壁上的魚叉獵槍，哪一邊都行。解決掉那些元龍和上面的騎兵。把他們都射成刺蝟!', '暗影穹殿的跳躍者要求你，使用卓頓海姆速射魚叉，射下15頭卓頓海姆元龍和騎乘其上的騎兵。', '', '去找寒冰皇冠的跳躍者。', '尤頓海姆始祖幼龍與其騎士已擊落', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13071 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13071, 'zhTW', '暗邪愛看煙火秀!', '暗邪喜歡火!暗邪也愛元龍!$B$B<憎惡體興奮地拍著手。>$B$B小$n，去卓頓海姆的尼約達村偷一頭元龍。讓牠在卓頓海姆製造美麗的煙火秀吧!', '暗影穹殿的暗邪要求你，偷走一頭尼約達元龍，並利用牠在卓頓海姆區域內焚燬8棟維酷建築。不過，巴拉加德堡壘因為材質的緣故無法焚燬。', '', '去找寒冰皇冠的暗邪。', '維库人建築已點燃', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13074 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13074, 'zhTW', '翡翠夢魘中的一絲希望', '我們所需要的材料只存在於翡翠夢境中...被灌注了強大復生魔法的橡實。這塊神聖區域中的許多地方，都與翡翠夢境緊密聯繫著，而我的神殿就在其中。$B$B我將送你進入夢境中，為我找來一些橡實。盡快準備好，$c，以這種方法進入夢境相當危險，而你也很可能被夢魘所包圍。$B$B盡快找到一些橡實，然後離開我的神殿，或是擰你自己，以回到真實世界來。', '月光林地的守護者雷姆洛斯指示你，進入翡翠夢境並找到3枚翡翠橡實。然後離開雷姆洛斯神殿一帶，以回到艾澤拉斯。', '', '去月光林地找月神湖的守護者雷姆洛斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13075 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13075, 'zhTW', '雷姆洛斯之恩', '我會開啟一個傳送門，好送你回到帶你來的德魯伊那兒。你和你的十字軍已擁有我的祝禱與祈福。我希望這枚橡實可以淨化你的十字軍同伴，並將他從悲慘的宿命中給救回來。$B$B再見了，$r。', '攜帶翡翠橡實，回寒冰皇冠的靜默警戒找十字軍布理登布萊特。', '', '去找寒冰皇冠的十字軍布理登布萊特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13078 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13078, 'zhTW', '妲莉雅之淚', '在這樣的黑暗時刻，我不能遺棄一盞將滅的聖光。$B$B我們需要一樣神聖之物，或許是拯救布理登布萊特的一線希望...一個受到同種瘟疫所害的聖潔生物所遺留的東西。$B$B動身吧，就在晶紅龍殿外正進行著戰鬥的神聖道路上。當你見到晶紅管理者低飛，並在不死軍團腳下燃起烈焰，你將會見證新生命滋長。在滋長的生命間，找到妲莉雅之淚 - 將它帶來給我。', '龍眠神殿裡的生命守縛者雅立史卓莎要求你，在晶紅管理者施放烈焰、淨化生命後，從地上收集妲莉雅之淚。', '', '去找龍骨荒野的『生命守縛者』雅立史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13079 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13079, 'zhTW', '雅立史卓莎之恩', '你要了解，年輕的$r，要淨化這具肉體並培育新的生命，確實是易如反掌...然而，在不傷害身體的情況下移除瘟疫，就不是我所能完全掌握的力量了。$B$B若布理登布萊特真是你們所仰望的燈塔，或許他能撐過淨化的痛苦過程並獲得新生，但我不敢保證，這就是你所尋求的救贖。去吧，帶著它與我最真誠的祝禱。', '寒冰皇冠的靜默警戒，將雅立史卓莎之息交給十字軍布理登布萊特。', '', '去找寒冰皇冠的十字軍布理登布萊特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13083 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13083, 'zhTW', '黑暗中的一絲微光', '<十字軍布理登布萊特的外袍，靜靜地安躺在箱子的底部，咆哮的北風從箱子的縫隙灌入，一方衣角輕擺著。>$B$B提里奧會想看到這個的，偉大戰士的最後遺物。', '將十字軍布理登布萊特的外袍帶給十字軍之巔的大領主提里奧‧弗丁。', '', '去找寒冰皇冠的大領主提里奧‧弗丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13084 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13084, 'zhTW', '燃燒吧，卓頓海姆!', '我們來看看，是不是可以進一步削弱維酷人的士氣，$n。$B$B我希望你到卓頓海姆去，並將他們的旌旗丟進火中。這聽來似乎沒什麼，但是看到祖傳的家園，日復一日地被破壞，帶給他們的打擊，將比肉體上的痛苦更令人感到折磨。$B$B至少...這不會痛。', '暗影穹殿的蘭克洛公爵要你焚燬10支維酷旌旗。', '', '去找寒冰皇冠的蘭克洛公爵。', '維库人旗幟已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13086 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13086, 'zhTW', '最後防線', '我已經部署好基地的防禦措施了，$c!在先鋒駐地的四座高塔上，各有一門易於操作的銀白十字軍火砲，經過賈斯塔夫神父的親自加持。你得飛上其中一座高塔並操控火砲。用它擊潰巫妖王親自策劃的天譴軍攻勢。$B$B不過話說在前頭，天譴軍團一定會派冰霜巨龍襲擊高塔。把牠們都打下來!如果高塔淪陷，他們也破牆而入的話，我們就玩完了!', '以銀白火砲殺死100個天譴進攻者。同時殺死3隻霜育摧毀者。成功之後，向攻城大師費茲克回報。', '', '去找寒冰皇冠的攻城大師費茲克。', '天災攻擊者已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13087 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13087, 'zhTW', '北方廚藝', '所以說你既然沒有我要的燉肉，你在這裡幹嘛。我肚子餓的要死!至少給我弄來一些冷肉，讓我自己煮燉肉吧!如果你幫我弄來肉的話，我就給你食譜讓你可以自己煮。現在快點去給我弄點肉來!', '把四塊冷肉塊交給瓦爾加德的布隆·塗酒。北裂境的任何野獸身上都能找到冷肉塊。', '', '去找凜風峽灣的布隆·塗酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13088 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13088, 'zhTW', '北方廚藝', '這兒有好多的新兵，而且這些小子都餓壞啦!如果你能夠去外頭幫我弄點燉肉用的冷肉塊來，我可以教你怎麼做這道菜。', '把四塊冷肉塊交給驍勇要塞的羅利克·麥克里爾。北裂境的任何野獸身上都能取得冷肉塊。', '', '去找北風凍原的羅利克‧麥克里爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13089 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13089, 'zhTW', '北方廚藝', '沒有什麼比一道新鮮燉肉更能夠讓你暖暖身子的了。替我從這地方的野獸身上弄點冷肉塊來，我就教你做一道熱騰騰的燉肉。', '把四塊冷肉塊交給復仇臺地的湯瑪士‧寇里奇歐。北裂境的任何野獸身上都能找到冷肉塊。', '', '去找凜風峽灣的湯瑪士‧寇里奇歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13090 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13090, 'zhTW', '北方廚藝', '戰歌進攻部隊的戰士們需要填飽肚子維持力量。如果你能夠從犀牛或其他野獸身上弄點冷肉塊來，我就能為他們做點燉肉。如果你想的話，我也很樂意教你食譜。', '把四塊冷肉塊交給戰歌堡的翁恩‧柔蹄。北裂境的任何野獸身上都能取得冷肉塊。', '', '去找北風凍原的翁恩‧柔蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13091 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13091, 'zhTW', '身為水駭體的藝術', '我洞穴外的水閘，運用了許多維酷魔法中仍然未解的基本原理。我要教你一點小把戲，讓你好好地玩弄這些單細胞生物一會兒，然後利用他們在卓頓海姆引起一場浩劫!<被女妖寄生的維酷人在空中演練了魔法，並以巨大的手指，觸碰你的額頭。>$B$B去吧，打開門進入水閘去。你將會看到一個水駭體，好好地運用它，摧毀我們的敵人!', '尼約達村的骸骨女巫要你操控一隻水駭體，在卓頓海姆一帶，以其殺害10個維酷人。定義上合格的維酷人指卓頓海姆沉睡看守者、卓頓海姆戰士、默約丁水魔導師、尼約達女矛侍、和英靈殿瓦苟。', '', '去找寒冰皇冠的骸骨女巫。', '已附身水中恐懼並擊殺尤頓海姆維库人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13092 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13092, 'zhTW', '解讀骸骨', '操控這種生物的一個好處是，我可以使用她所有的能力。作為一個骸骨女巫及符文解讀者，她擁有占卜並決定他人命運的能力。$B$B<骸骨女巫不懷好意地笑著。>$B$B幸虧我就擁有影響解讀結果的能力。$B$B將你在卓頓海姆殺害的維酷人骸骨帶來給我，我將用來占卜你的命運，並允許你自己決定它。', '尼約達村的骸骨女巫指示你，收集15份維酷骸骨。', '', '去找寒冰皇冠的骸骨女巫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13093 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13093, 'zhTW', '解讀骸骨', '', '選擇你的命運吧，$n。', '', '去找寒冰皇冠的骸骨女巫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13094 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13094, 'zhTW', '他們不知羞恥嗎?', '大法師貝瑞把關於奧輿全覽圖的研究借給了我。那是一份瑪里苟斯亟欲拼湊起來的地圖。$B$B我犯了一個錯誤，那就是與來此補充物資的部落冒險者小隊談起這件事...現在那本研究不見了!$B$B一定是被他們給偷走了。拜託，幫我把書找回來。', '戰爭法師凱特林的影像要你取回貝瑞那德的研究。', '', '去找北風凍原的圖書管理員瑟菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13095 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13095, 'zhTW', '他們不知羞恥嗎?', '大法師貝瑞把關於奧輿全覽圖的研究借給了我。那是一份瑪里苟斯亟欲拼湊起來的地圖。$B$B我犯了一個錯誤，那就是與來此補充物資的聯盟冒險者小隊談起這件事...現在那本研究不見了!$B$B一定是被他們給偷走了。拜託，幫我把書找回來。', '戰爭法師凱特林的影像要你取回貝瑞那德的研究。', '', '去找北風凍原的圖書管理員瑟菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13096 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13096, 'zhTW', '迦爾達拉之死', '你見過那場面嗎，夥計？$B$B這是我見過的最可怕的事情了。偉大的阿卡里……在我面前被殺死了。真是太恐怖了……$B$B我曾發誓永遠不會參與實際的行動，只是負責觀察而已。但我實在是無法忍受了！迦爾達拉必須得到懲罰！$B$B請你進入古達克，把他找出來。當你為阿卡里復仇之後再回來見我。', '杜布拉金的託瑪爾要你殺死古達克的迦爾達拉。', '', '去找祖爾德拉克的托爾瑪。', '已擊殺加爾達拉', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13098 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13098, 'zhTW', '為了後代子孫', '剛德拉克已經完了，老兄。$B$B歷史就在咱們眼前重演啦。當食人妖背叛了自己的神明時，就注定要面臨末日了。這只是時間的問題而已。$B$B如果我們能夠清楚的紀錄這些事件，也許就能避免後世子孫重蹈覆轍。$B$B如果你夠勇敢，就進入剛德拉克，找找有什麼線索可以告訴我們德拉克瑞帝國怎麼會走到今天這一步。', '杜布拉金的撰史者巴琪妮要你進入剛德拉克收集6個德拉克瑞歷史石板。', '', '去找祖爾德拉克的撰史者巴琪妮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13099 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13099, 'zhTW', '探班', '有些可怕的聲音從剛德拉克裡頭傳出來，老兄。而且還越來越大聲，越來越頻繁。我的老學生待在剛德拉克西邊的哨站記錄事情。也許你能夠幫我去探個班?', '托基尼要你與杜布拉金的撰史者巴琪妮談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13100 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13100, 'zhTW', '灌能蘑菇肉糕', '我們有張訂單得馬上出貨!『不只是配件』的歐爾頓‧班尼特需要一份蘑菇肉糕。$B$B弄來一些長在達拉然下水道的灌能蘑菇，還有冷肉塊，在任何一個火堆處放進鍋子裡燉煮，煮好後送到歐爾頓那兒去。', '使用你的肉糕鍋，用4朵長在達拉然下水道的灌能蘑菇和2份冷肉塊煮出灌能蘑菇肉糕，然後送去給『不只是配件』的歐爾頓‧班尼特，就在達拉然的織符者廣場。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13101, 'zhTW', '戲法旅舍的會議', '戲法旅舍的艾立爾‧蒼凝要舉辦一場會議，而且他得盡快籌備盛宴!$B$B你要提供他一些北地燉肉，還有一壺葡萄酒。你可以在達拉然中央一帶的『勸君更進一杯酒』起司店弄到酒。起司店的老闆欠我酒，你應該可以在店附近找到一壺。$B$B把酒和燉肉帶給艾立爾。', '以你的烹飪技能作出4份北地燉肉，並從達拉然的起司店取走一壺葡萄酒，將其帶給戲法旅舍的艾立爾‧蒼凝，就在達拉然的織符者廣場。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13102, 'zhTW', '下水道燉菜', '雅杰‧格林，地下道的旅店老闆，現在需要為在他那落腳的顧客張羅一份燉菜。$B$B在水晶之歌森林裡，摘取4根水晶之歌胡蘿蔔，和4份冷肉塊一起烹調。$B$B要去水晶之歌森林的話，可以透過織符者廣場東角的傳送門大廳。$B$B燉菜準備好後，送去給雅杰。', '在烹調鍋中，將產自水晶之歌森林的4支水晶之歌胡蘿蔔，與4份冷肉塊一起烹調。燉菜備齊以後，送去給達拉然下水道的旅店老闆，雅杰‧格林。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13103 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13103, 'zhTW', '給怒金的起司', '達拉然獸皮工店的拉尼德‧怒金現在急需葡萄酒和起司。$B$B從達拉然中心的『勸君更進一杯酒』貨架上取得起司，並在全市各處的桌上，收集半杯滿的葡萄酒。把收集來的酒倒在同一個瓶子中，和起司一起送去給拉尼德。$B$B我不覺得他分得出其中的差別。', '在空的起司盤上，放上『勸君更進一杯酒』取來的陳年達拉然濃起司，並從達拉然市中各處的桌上，收集6杯半滿的達拉然葡萄酒杯。將起司和葡萄酒帶給達拉然獸皮工店的拉尼德‧怒金，店的位置在魔導師貿易區。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13107 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13107, 'zhTW', '芥末熱狗!', '大法師潘塔魯斯偶爾喜歡看鬥球比賽，而他現在就要出發去看一場，但他需要帶些食物。$B$B你必須在他的野餐籃中，放入4份你做的犀牛熱狗，還有4份自市中綠地採來的野生芥末。$B$B把野餐籃送去給他，使他準備齊全地出發。', '以烹飪技能調理4份犀牛熱狗，並自達拉然市內的綠地採來4份野生芥末，都放進空的野餐籃。然後將野餐籃送去給達拉然市內，卡薩斯平臺的大法師潘塔魯斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13108 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13108, 'zhTW', '不惜代價！', '無論如何，洛肯一定要死。$B$B如果我不得不親手撕碎他，那麼他很快就會為自己的惡行付出代價。$B$B若是你碰巧趕在我前面遇到他，擊敗他的榮耀就全歸你了。$B$B把他的信物帶給我，我會祝福並感謝你的。', '丹尼芬雷的約庫姆國王要你進入閃電大廳並擊敗洛肯，然後將洛肯的信物帶回去給他。', '', '去找風暴峭壁的裘庫姆王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13109 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13109, 'zhTW', '勢不兩立', '我要坦白告訴你，小$r。自從我們與托里姆的盟約破裂後，我的族人已經變了。$B$B作為他們的首領，我最希望他們心靈的創傷能夠癒合，我們與風暴之王的友誼能夠恢復。在你擊敗弗約恩之後，我們已經向這個目標邁進了一大步。我要請你幫助我們更進一步……$B$B有一個比弗約恩更強大的敵人住在閃電大廳裡，他威脅到了我們的生存。沃爾坎和我們之間，只有一個能活下來。', '丹尼芬雷的約庫姆國王要你進入閃電大廳，擊敗沃爾坎。', '', '去找風暴峭壁的裘庫姆王。', '已擊敗沃爾坎', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13110 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13110, 'zhTW', '死不瞑目', '並非所有我們的士兵都能自天譴岸地平安歸來。許多人被殺害後，被轉化成醜惡而扭曲的另一種人格。這就是成為天譴軍團之途。對這些枉死的靈魂而言，並不能得到永恆的寧靜。我們應該要讓他們安息。$B$B越過止境到天譴岸地去吧，殺掉那些被轉化為骷髏的再活化十字軍。將聖水灑在他們的骸骨上，解救他們的靈魂。', '在回聲山谷的賈斯塔夫神父要求你，在再活化的十字軍屍體上使用聖水，以解救10個不能安息的靈魂。', '', '去找寒冰皇冠的賈斯塔夫神父。', '不安的靈魂已釋放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13111 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13111, 'zhTW', '獨一無二', '聽著，老兄。$B$B就第一眼而言，這看來不過就是另一個古老的故事－食人妖藉由毀滅他們原應敬仰的種族，獲得了禁忌的力量。$B$B如果這個傳說是真的，應該還有某些和德拉克瑞有關的有趣玩意殘留下來。如果我聽到的是真的，剛德拉克內應該有尊特別的魔像－一尊獨一無二的魔像!$B$B你想要一趟刺激的冒險嗎，老兄?幫我從剛德拉克帶回那魔像的一部分，好讓我研究研究。', '杜布拉金的撰史者巴琪妮要求你，進入剛德拉克，並撿回一塊德拉克瑞巨像的碎片。', '', '去找祖爾德拉克的撰史者巴琪妮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13112 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13112, 'zhTW', '灌能蘑菇肉糕', '『不只是配件』的歐爾頓‧班尼特需要一份蘑菇肉糕。$B$B弄來一些長在達拉然下水道的灌能蘑菇，還有份冷肉塊，在任何一個火堆處放進鍋子裡燉煮，烹調好後送到歐爾頓那兒去。$B$B只要他們願意嚐嚐地精的美味，我會讓他們一試成主顧的!', '使用你的肉糕鍋，用4朵長在達拉然下水道的灌能蘑菇和2份冷肉塊煮出灌能蘑菇肉糕，然後送去給『不只是配件』的歐爾頓‧班尼特，就在達拉然的織符者廣場。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13113 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13113, 'zhTW', '戲法旅舍的會議', '你相信嗎？部落竟然禁止了吃人的行為…我告訴你這是不對的！我還是專心完成我的訂單好了。$B$B戲法旅舍的艾立爾‧蒼凝有許多訪客，你得提供他一些北地燉肉，還有一壺葡萄酒，酒可以從達拉然市中心的起司店弄來。$B$B去吧，把酒和燉肉送去給艾立爾。', '將4份北地燉肉與從達拉然的起司店取走的一壺葡萄酒，帶給戲法旅舍的艾立爾‧蒼凝，就在達拉然的織符者廣場。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13114 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13114, 'zhTW', '下水道燉菜', '我們又有活得幹了。地下道旅店的老闆，現在要為他那餓死鬼般的顧客張羅一份燉菜。$B$B不過看來他不怎麼欣賞，我上回在燉菜裡放地精的廚藝。在水晶之歌森林裡，摘取4根水晶之歌胡蘿蔔，和4份冷肉塊一起烹調。然後送去給雅杰。$B$B要去水晶之歌森林的話，可以透過織符者廣場東角的傳送門大廳。', '在烹調鍋中，將產自水晶之歌森林的4根水晶之歌胡蘿蔔，與4份冷肉塊一起烹調。燉菜煮好以後，送去給達拉然下水道的旅店老闆，雅杰‧格林。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13115 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13115, 'zhTW', '給怒金的起司', '獸皮工店的拉尼德‧怒金，現在需要葡萄酒和起司。為什麼他不想嚐嚐我美味的地精呢？$B$B從達拉然中心的起司店弄點起司，然後從城市各處的桌子上，收集幾杯半滿的葡萄酒。把酒和起司一起送去給拉尼德。$B$B也許我們可以將其命名為雜燴美酒，是吧。', '在空的起司盤上，放上『勸君更進一杯酒』取來的陳年達拉然濃起司，並從達拉然市中各處的桌上，收集6杯半滿的達拉然葡萄酒杯。將起司和葡萄酒帶給達拉然獸皮工店的拉尼德‧怒金，店的位置在魔導師貿易區。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13116 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13116, 'zhTW', '芥末熱狗!', '大法師潘塔魯斯喜歡看激烈的鬥球比賽，但他需要帶些食物。$B$B你必須在他的野餐籃中，放入4份你做的犀牛熱狗，還有4份自市中綠地採來的野生芥末。$B$B用芥末熱狗塞滿他的野餐籃吧，小子。', '以烹飪技能調理4份犀牛熱狗，並自達拉然市內的綠地採來4份野生芥末，都放進空的野餐籃。然後將野餐籃送去給達拉然市內，卡薩斯平臺的大法師潘塔魯斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13117 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13117, 'zhTW', '他們打哪來的?', '巫妖王的部屬，在血肉作坊中日以繼夜地生產憎惡體和血肉巨人。$B$B不僅如此，越來越多的骷髏建造者，也如潮水般湧出，他們工作的進度不斷加快。$B$B如果我們不能儘早察覺他們打哪來的，還有他們如何能工作得如此迅速，我們就會被敵人的大軍給淹沒。往東南方搜尋看看，試圖找出這些骷髏的來源。', '調查血肉作坊東南方的召喚祭壇，然後向黑色守望的黑騎兵亞爾利回報。', '', '去找寒冰皇冠的黑騎兵亞爾利。', '已調查召喚祭壇', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13118 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13118, 'zhTW', '對天譴岸地的淨化', '天譴軍團派遣大軍進犯銀白十字軍，但是被擊退。現在他們到處燒殺擄掠。他們在天譴岸地的所有俘虜，都被巫妖王操控，成了他的奴隸。$B$B無疑地，銀白十字軍一定會請你幫忙，讓他們的士兵能有尊嚴地死去。我對你的要求不多，為了成功，我們必須對天譴軍團進行無差別掃蕩。$B$B去天譴岸地吧，朝西北方穿過止境，讓所有阻擋你路途的人都倒下。', '在寒冰皇冠，回聲山谷的黯黑看守者要求你，殺掉3名遺忘深淵高階祭師、3名遺忘深淵地底王、還有8名再活化的十字軍。', '', '去找寒冰皇冠的黯黑看守者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13119 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13119, 'zhTW', '摧毀祭壇', '所以他們正在祭壇上召喚工人與戰士嗎?$B$B他們就是我們的首要目標。召喚大師應該會有根法杖，好讓他啟動傳送門。如果你能殺死召喚大師，並奪下法杖，你就能使傳送門超載，然後摧毀祭壇。$B$B就這麼對付那四個祭壇，一旦它們都被摧毀，回來向我回報。', '殺掉召喚大師札洛德，並使用他的召喚法杖摧毀四座召喚祭壇。完成之後，回到黑色守望，向黑騎兵亞爾利回報。', '', '去找寒冰皇冠的黑騎兵亞爾利。', '第一座召喚祭壇已摧毀', '第二座召喚祭壇已摧毀', '第三座召喚祭壇已摧毀', '第四座召喚祭壇已摧毀', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13120 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13120, 'zhTW', '死亡凝視', '血肉作坊是個龐大的設施，我們很難面面俱到地了解裡面發生的所有事。幸好，我有個計畫。$B$B<雅爾利從披風的口袋裡取出一顆寶珠，並遞給你。>$B$B這是顆死亡凝視寶珠。透過它，我們可以觀察到天譴軍團的一舉一動，然後決定最好的進攻方案。$B$B將這些寶珠安置在三個重點區域的臺座上 - 西南邊的憎惡體實驗室與血肉巨人實驗室，還有西邊遠處，綠色熔爐的周圍區域。', '將死亡凝視寶珠安置於憎惡體實驗室寶珠座、血肉巨人實驗室寶珠座和熔爐區寶珠座，然後回黑色守望向黑騎兵亞爾利回報。', '', '去找寒冰皇冠的黑騎兵亞爾利。', '法球已放置於憎惡實驗室', '法球已放置於血肉巨人實驗室', '法球已放置於坩堝區域', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13121 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13121, 'zhTW', '透過另一隻眼', '如果我們打算要進行下一步，我們一定要利用巫妖王的工具來反制他。$B$B越過山脈往西南方去，就是庫爾加拉要塞。卓頓海姆的神諭者就躲在其中，接收主人的命令並且透過巫妖王之眼來窺探偵察。$B$B你要對付的就是那顆眼睛。雖然無法用它來穿透冰冠城塞的帷幕，但你還是可以用它來觀察其他地方，讓我們知道哪裡才是最好的進攻路線。', '尼約達村的骸骨女巫賦予你新的任務，要利用巫妖王之眼收集情報。', '', '去找寒冰皇冠的骸骨女巫。', '已為骸骨女巫取得情報', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13122 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13122, 'zhTW', '天譴石', '天譴石，是每個天譴軍在誕生或被創造時，伴隨產生的一項物品。它對擁有者而言，有某些益處，然而更重要的，它能讓天譴軍團的領導者，隨時掌握每個單位的位置與動向。$B$B只要有足夠的天譴石，我就能追蹤其他天譴軍團成員，在寒冰皇冠上的行動。$B$B當你在天譴岸地上，對天譴軍團大開殺戒時，收集所有你能找到的天譴石。當你的背包再也裝不下，把它們帶回來給我。', '在寒冰皇冠，回聲山谷裡的黯黑看守者要你帶回15個天譴石給他。', '', '去找寒冰皇冠的黯黑看守者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13123 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13123, 'zhTW', '巫妖王之怒典藏版: -DEM -E -FLAG', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13124 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13124, 'zhTW', '負隅頑抗', '戰鬥一直在持續進行，$n。我們設法避過了瑪里苟斯的偵測，繼續設法破壞他的陰謀。但好消息就到此為止了。我們的努力幾乎沒有產生任何效果。瑪里苟斯與他的手下日益壯大。現在連我們最後一支突襲隊都被俘虜關在奧核之眼中。我們一定得設法救援他們!貝加瑞斯塔茲與他的夥伴對我們來說非常重要。我們能夠倚重你嗎，$n?', '瑞洛拉茲要你進入奧核之眼並解救貝加瑞斯塔茲與他的同伴。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13125 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13125, 'zhTW', '空氣也為之凍結', '你必須擊敗天譴岸地的領主們，若要讓此地自天譴軍團的魔掌中解放出來。$B$B『血肉撕裂者』索拉納斯掌控了天譴岸地第一階的神殿。在索拉納斯附近，你可以找到高階祭師亞薩蒙，他在第二階的靈魂尖塔上宣道。再往上走，地底王塔婁諾斯則據有魔鬼之淵的庭院。$B$B他們都是可怕而不容小覷的敵手。需要幫助時，使用這把戰爭號角。亞榭洛的死亡騎士將會出現。', '在寒冰皇冠，回聲山谷的黯黑看守者要求你，殺掉『血肉撕裂者』索拉納斯、高階祭師亞薩蒙、和地底王塔婁諾斯。', '', '去找寒冰皇冠的黯黑看守者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13126 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13126, 'zhTW', '共同戰線', '從這裡開始，要靠我們合作無間才能夠前進。$B$B在我們的上方，瓦羅斯躲進了一道無法穿透的護盾之中。要找到他的話，你就一定得消滅構築護盾的離心傀儡。$B$B我們每個人都能夠提供我們所屬軍團的飛龍給你們騎乘。你必須靠著這些飛龍的幫助才能夠對付瓦羅斯。', '貝加瑞斯塔茲要你摧毀10具離心傀儡，除去瓦羅斯的護盾。然後你必須擊敗瓦羅斯‧雲行者。', '', '', '離心構造體已摧毀', '已擊敗瓦羅斯·逐雲者', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13127 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13127, 'zhTW', '法師領主厄隆', '我們與我們的目標之間，只剩下一個阻礙了。他的名字叫厄隆。$B$B他在上方守衛著第三環。小心他的強力咒法，朋友。$B$B擊敗他。讓他為背叛付出代價!', '貝加瑞斯塔茲要你擊敗奧核之眼中的法師領主厄隆。', '', '', '已擊敗法師領主烏羅姆', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13128 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13128, 'zhTW', '飛翼與祈禱', '面對伊瑞茍斯的時候到了。$B$B他能夠直接啜飲瑪里苟斯的魔力泉源 - 從他負責保護的地方抽取能量。$B$B然而，擊敗了法師領主，也解放了飛龍的完整力量。只要巧妙的運用，一定能夠擊敗伊瑞苟斯。', '貝加瑞斯塔茲要你殺死奧核之眼的伊瑞苟斯。', '', '去找北風凍原的瑞洛拉茲。', '已擊敗魔網守護者埃雷格斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13129 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13129, 'zhTW', '鬥智遊戲', '<庫賽爾從短衫上割下了長長一條布料交給你。>$B$B來，$r，拿著。把它浸在『召喚者』諾沃司所留下的殘骸中。$B$B我們得找出到底是什麼讓那些天譴軍如此激動。', '庫賽爾要你對『召喚者』諾沃司的屍體使用庫賽爾的短衫碎片，然後將腐液玷污的布料帶回去德拉克薩隆要塞給她。', '', '去找灰熊丘陵的麥客‧菲爾森。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13130 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13130, 'zhTW', '革命的基石', '你可以看見天譴岸地，有個令人作嘔的腐朽坑洞，然而有天它將成為尊貴與榮耀之地。大領主弗丁將之稱為「正義要塞」。$B$B嗯，固若金湯如冰冠城塞，也是從一顆石頭開始建造的。所以，現在開始尋找革命的第一顆石頭吧。$B$B往南方的水晶之歌去，找到在其東邊的無縛灌木林。在灌木叢的底層收集結晶心材，並從珊達拉遺跡取得精靈石藝。', '回聲山谷的十字軍建築師席拉斯要求你，採集10株結晶心材的樹幹，以及10份上古精靈石藝。', '', '去找寒冰皇冠的十字軍建築師席拉斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13131 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13131, 'zhTW', '我箱子裡的垃圾', '看看這個!我的箱子從未如此空虛。它應該裝著比現在多十倍的寶物!$B$B我的同伴妄想獨吞所有的戰利品，現在瞧他們怎麼了!一堆白骨，就是這樣的下場!$B$B就像我老媽告訴我的 - 唯一比沒有財寶還糟糕的事，就是受詛咒的財寶。$B$B聽著，遠方有一大票財寶，而且我敢打包票，不是受詛咒的那種。那些小王八蛋根本不需要它 - 對他們而言不過是垃圾罷了。$B$B幫我弄回來，我會分你一些油水的，小子。', '俄特加德之巔的布瑞格要求你，找到5個失去光澤的銀錠、3顆閃光的小珠、2只黃金高腳杯以及1尊碧玉雕像。', '', '去找烏特加德之巔的布瑞格·細柄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13132 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13132, 'zhTW', '我將復仇!', '呃!不能責怪他們，$g小夥子:小姑娘;。誰不是這樣呢?$B$B他們將自己丟進了成堆的黃金當中 - 以為他們挖到了主礦脈，他們的確是。唉...但現在看看他們。喪失心智的奴隸，連一枚金幣都無法拾起。$B$B唯有幸運的我，免去了相同的命運。逃跑的途中，我被擊倒了 － 實在是不怎麼好的起步。一抬頭，看到他們其中一人率先轉身...$B$B做個好$g孩子:女孩;，找到負責這裡的傢伙，教訓教訓他，教他別再欺壓我的夥伴。', '俄特加德之巔的布瑞格要求你，殺掉依米倫王。', '', '去找烏特加德之巔的布瑞格·細柄。', '殺死依米倫王', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13133 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13133, 'zhTW', '尋找遠古英雄', '快點，$n，去西南方的先祖大廳!$B$B裡面你會找到休眠的默約丁。喚醒他們，直到你找到伊斯卡德。找到他之後，對他使用這個護符，並將他帶回來見我。$B$B現在馬上出發。我可沒時間讓你浪費!', '尼約達村的骸骨女巫要求你，帶回伊斯卡德。', '', '去找寒冰皇冠的骸骨女巫。', '伊斯卡德已交給骸骨女巫', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13134 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13134, 'zhTW', '讓他們血濺五步', '沒有保持肢體機能用的血液，和用以保存肉體的防腐液，天譴軍團就無法製造他們的血肉怪物。如果我們能切斷這兩者的補給，他們的軍隊就會崩解，而我們也就可以輕易地摧毀這些玩意。$B$B在他們組裝血肉巨人和憎惡體的實驗室中，你可以找到裝著防腐液的大缸與盛裝鮮血的大型寶珠。摧毀它們，並讓任何膽敢阻擋你的人都倒下!', '黑色守望的黑騎兵亞爾利要求你，摧毀5個盛裝防腐液的缸子，以及5個血魄寶珠。', '', '去找寒冰皇冠的黑騎兵亞爾利。', '血珠已擊碎', '防腐液桶已摧毀', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13135 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13135, 'zhTW', '它會殺了我們', '此處的東南方，在水晶之歌森林的東界，有個被稱為無縛灌木林的地方。在那裡，存在各種生命的形式。灌木林中的生物有種共通的特點，就是他們對魔法能量起的共鳴。他們都擁有純淨的晶化能量。當其不穩定時，足以殺死我們每個人!$B$B前往無縛灌木林，殺掉其中的生物，奪取他們的晶化能量。我們需要補充燃料，而他們需要永遠的安息。我們稱之為「雙贏」。', '在寒冰皇冠，回聲山谷的十字軍工程師史匹派崔要求你，收集並帶回8份晶化能量。', '', '去找寒冰皇冠的十字軍工程師史匹派崔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13136, 'zhTW', '鋸齒裂片', '你從一名食屍鬼的屍體中，拔出了這塊鋸齒狀的尖利裂片。金屬的刃口並不平整，表示它要不就是由生手煉鑄而成，要不就是由一塊更大的部份碎裂出來。$B$B你想起，在血肉作坊與食屍鬼對陣時，曾看過類似的碎片嵌在他們的屍體上，這讓你不禁想知道，碎片的製造者，究竟為何如此大費周章。若你收集一些類似的碎片，並帶給十字軍歐拉金‧山瑞斯，或許他會有些想法。', '將10片鋸齒裂片，帶給黑色守望的十字軍歐拉金‧山瑞斯。', '', '去找寒冰皇冠的十字軍歐拉金·山瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13137 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13137, 'zhTW', '不名譽戰鬥', '在西南方最高的山頂上，戰傷尖塔俯視著卓頓海姆。這裡是維酷人的聖地，就進行光榮戰鬥的地點偏好而言，其重要性僅次於英靈殿。$B$B我們應該在那上面觀賞不名譽戰鬥。$B$B召集你的夥伴飛往尖塔。當你準備好了，點燃你的火源信號，我將以伊斯卡德的面目出現。$B$B我們將進行戰鬥，你將會嬴，而瓦德瑪卓必定會前來觀看這場戰鬥!', '尼約達村的骸骨女巫要求你，在戰傷尖塔上擊敗伊斯卡德。', '', '去找寒冰皇冠的骸骨女巫。', '已在戰鬥中擊敗伊斯卡德', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13138 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13138, 'zhTW', '我熔...熔化了!', '<歐拉金以著盔甲的一手，握住一片裂片。>$B$B施加足夠力量的話，它足以刺穿盔甲。我們必須查明它的原料，和巫妖王使用它的意圖。$B$B去東邊，緊鄰冰冠城塞的瑪里庫立斯。根據我們僅有的一點情報，那裡充斥著鎔鍊與鍛造用的器具。帶這些裂片過去，在瑪里庫立斯底部的開放熔爐中鎔鍊它。一旦它被鎔鍊並重鑄，我們就能辨明它的成分。', '使用瑪里庫立斯熔爐下層附近的鋸齒裂片袋。將熔化的金屬錠帶回給黑色守望的十字軍歐拉金‧山瑞斯。', '', '去找寒冰皇冠的十字軍歐拉金·山瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13139 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13139, 'zhTW', '深入北裂境的冰凍心臟', '席拉斯和史匹派崔點收了建造正義要塞所需的建材與燃料。多虧你和黯刃騎士團，天譴岸地裡的天譴軍團已潰不成軍，他們的軍官也都被擊敗。$B$B我將會挑選動工的地點，但是，在此之前，你得先將我的報告上呈給大領主提里奧‧弗丁。在他的領導下，大軍將開入寒冰皇冠。', '將賈斯塔夫神父的報告呈給大領主提里奧‧弗丁，他在寒冰皇冠的銀白先鋒駐地。', '', '去找寒冰皇冠的大領主提里奧‧弗丁。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13140 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13140, 'zhTW', '瑪里庫立斯的符文鐵匠', '關於你取得的那些裂片，唯一可能的產地就是瑪里庫立斯。它是巫妖王金屬工業的所在地，就在寇普雷薩的東邊。$B$B令人困惑的是，無論是組合憎惡體和血肉巨人，或者召喚骷髏僕役，都不需要這些金屬。找到在瑪里庫立斯底層工作的骷髏符文鐵匠，並弄來他們正在加工的板子。我們必須知道，為什麼會在血肉作坊裡發現這些金屬。', '帶回5塊符文薩鋼板給黑色守望的十字軍歐拉金‧山瑞斯。', '', '去找寒冰皇冠的十字軍歐拉金·山瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13141, 'zhTW', '十字軍之巔保衛戰', '<大領主弗丁握著一支銀白十字軍的旌旗。>$B$B這支旌旗是獨一無二的，$n。它帶著強力的祝福，可以使大片荒蕪的土地變得聖潔不可侵犯。$B$B你必須帶著它前往西北方，穿過止境，到天譴軍團嘲弄地稱為十字軍之巔的地方。將旌旗豎立在死去弟兄的顱骨堆頂端，然後防禦任何攻擊。聖滌的過程結束後，去找賈斯塔夫神父。$B$B現在去吧，$n。願你心中無畏無懼。', '前往十字軍之巔，在十字軍顱骨堆上使用十字軍祝福旌旗。防禦天譴軍團發動的攻擊，直到十字軍之巔頂端一帶的土地被聖滌。最後回到寒冰皇冠的回聲山谷，找到賈斯塔夫神父。', '十字軍之巔的戰役', '去找寒冰皇冠的賈斯塔夫神父。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13142, 'zhTW', '女妖的復仇', '這一刻終於到來了，$n。你和你的朋友必須挑戰巴拉加德堡壘的領主，卓頓海姆的主宰者，共主巴拉加德。$B$B在卓頓海姆西南邊，登上堡壘的頂端，你會看到一支號角。吹響它。讓你的挑戰之聲在一片平靜中迴響。$B$B巴拉加德將不得不面對你。而我...容我自稱，瓦德瑪卓將在當場判定挑戰的勝敗。$B$B<被女妖附身的維酷人發出了怒吼。>', '尼約達村的骸骨女巫要求你，挑戰並擊敗共主巴拉加德，以作為她的復仇。', '', '去找寒冰皇冠的骸骨女巫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13143, 'zhTW', '生力軍', '首先，我在東方的壁壘看見一些輕盈潛獵者。在我們和阿薩斯決裂前，牠們曾為我們所役，牠們是你可以找到最好的斥候...只需要支配之眼的一點刺激。$B$B飛上去，找到一個潛獵者，先打倒牠，然後用這個黯刃符印收服牠。牠會認得符印，我保證。將牠帶至此處東北方的岩石頂端，牠會知道怎麼來找我的。', '苦難高崗上奸詐的維瑞希要求你，將一個已收服的輕盈潛獵者，帶回至苦難高崗東北方的岩石堆頂端。', '', '去找寒冰皇冠的奸詐的維瑞希。', '已制伏並歸還敏捷潛行者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13144, 'zhTW', '一石二鳥', '血肉作坊憎惡體實驗室裡的工人，已經完成了一些他們的作品。目前，那些生物仍被拴在實驗室週遭的柱子上，但如果我們沒有任何作為，他們就會加入巫妖王的軍隊。$B$B骸骨堆中伸出的緊握之手散佈於血肉作坊週遭。這些骸骨的手都已被火焰之力附魔。找到這些骷髏，解放它們，將它們帶往憎惡體的成品附近，然後就有好戲可看了!', '黑色守望的黑騎兵阿爾利要求你，以燃燒的骷髏摧毀3個被禁錮的憎惡體。', '', '去找寒冰皇冠的黑騎兵亞爾利。', '鎖鏈憎惡已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13145, 'zhTW', '邪鄙堡', '我們必須了解敵人。$B$B使用支配之眼來控制輕盈潛獵者，並偵察整個區域。我之前飛行時注意到幾個地方，希望你特別靠近去偵察的:東北方的俯瞰處、東南方的工作區域、中心附近的大熔爐、西南方的祭壇區域。$B$B潛獵者跳躍的距離很長，而且從高處落下時不會受傷 - 利用這項優勢，在壁壘之間高低穿梭。', '苦難高崗上奸詐的維瑞希要你利用一隻輕盈潛獵者來偵察瑪里庫利斯。', '', '去找寒冰皇冠的奸詐的維瑞希。', '已探索獻祭祭壇', '已探索熔血鍛爐', '已探索冰封瞭望台', '已探索符文工坊', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13146 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13146, 'zhTW', '慷慨大放送', '我們必須引起某些混亂...任何可以使死亡騎士離開領導者身邊的混亂。如果我們殺掉他們的爪牙，我猜他們會對日常運作提高警戒。$B$B憎惡體是簡單的獵物，行動遲緩、容易預測、還有最重要的，愚蠢。利用他們對潛獵者的信任，把他們拖到散佈在建築區域裡的天譴炸彈附近。你將可以在他們搞清楚發生什麼事情之前就把炸彈給點燃。', '苦難高崗上奸詐的維瑞希要求你，利用輕盈潛獵者的鐵鍊，拖曳天譴炸彈到4個瑪里庫利斯的笨拙殘暴者身邊。', '', '去找寒冰皇冠的奸詐的維瑞希。', '天災炸彈禮物已送達', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13147 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13147, 'zhTW', '速配達人', '瓦苟和較次等的不死爪牙間最主要的不同之處在於，瓦苟仍然保留了足夠的心智，使他們對被奴役一事感到不齒。沒有任何瓦苟樂意和骷髏或食屍鬼一同工作。$B$B我們就是要利用這一點，利用這必然的仇恨，使這些有心理障礙的瑪里庫立斯陰影蠻卒與其他不死生物內鬥。這應該會減緩他們的生產，並使死亡騎士不得不介入處理。$B$B這其實滿簡單的 - 在這些蠻卒接近次等不死生物時，對他們丟石頭。', '苦難高崗上奸詐的維瑞希要求你，在瑪里庫立斯利用輕盈潛獵者，當陰影蠻卒接近較低等的不死生物時，對其丟擲石頭。引起5場打鬥後返回。', '', '去找寒冰皇冠的奸詐的維瑞希。', '工人打鬥已開始', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13148 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13148, 'zhTW', '修理項鍊', '這條損壞的項鍊附著一張發票，上面寫著「提摩西‧瓊斯財產 - 卡地亞珠寶公司 - 魔導師貿易區 - 達拉然」。$B$B也許你該修復它並物歸原主。', '以一枚玉髓修復這條項鍊，並送至提摩西‧瓊斯的珠寶工藝店，店在達拉然的魔導師貿易區。', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13149 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13149, 'zhTW', '驅散幻影', '總是來搗亂…$B$B恆龍軍團似乎藉由欺騙阿薩斯王子來擾亂歷史。$B$B如果他們說服他相信所有的穀物都沒有受到瘟疫感染，那麼他將不會做出肅清斯坦索姆的關鍵決定。$B$B這絕對不能發生。$B$B對任何可疑的箱裝穀物使用秘法干擾器，揭露它們的真面目。工作完成以後，和我在斯坦索姆的入口會合，在此處北方。', '克羅米要求你，在斯坦索姆的往日，對可疑的箱子使用秘法干擾器，然後在其入口附近和她交談。', '', '去找斯坦索姆的清剿的克羅米。', '驅散染疫的穀箱', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13150 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13150, 'zhTW', 'ZZOLD失落:小飾物', '“在飾物的底部有張發票，標示著在達拉然的‘提摩西·瓊斯 - 珠寶店名，區名’。或許，若你能修好它並物歸原主，他會給你一些回報。”', '修好這個玩意，並歸還給達拉然珠寶工藝店的提摩西·瓊斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13151 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13151, 'zhTW', '護送皇室', '阿薩斯馬上就要面臨是否要孤注一擲的難題，並且做出重大的決定。$B$B我必須徵召你，在王子的斯坦索姆抉擇行動中隨侍在側。$B$B你必須確保阿薩斯安全穿過斯坦索姆，並且擊敗瑪爾加尼斯!', '克羅米要求你，在斯坦索姆的抉擇中，隨侍於阿薩斯身側。瑪爾加尼斯被擊敗以後，回頭找她交談。', '', '去找斯坦索姆的清剿的克羅米。', '已擊敗瑪爾加尼斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13152, 'zhTW', '探訪博士', '所以，他們一直都在再活化聖所中，將薩鋼裂片嵌入食屍鬼體內?我們應該在這些食屍鬼被部署出來對付我們的部隊前阻止這件事。$B$B在血肉作坊的血肉巨人實驗室一帶，找到再活化聖所的入口。在那裡，食屍鬼的幕後黑手，賽伯諾克博士保留了他作品中最可怕的一件，補釘。解開他的鎖鍊，幫助他完成對博士的復仇。讓他的傑作成為毀滅他的原因。', '黑色守望的黑騎兵阿爾利，要你在再活化聖所中，摧毀束縛補釘的金屬樁，並協助他完成對賽伯諾克博士的復仇。', '', '去找寒冰皇冠的黑騎兵亞爾利。', '帕奇已釋放', '幫助帕奇殺死薩布諾克博士', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13153 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13153, 'zhTW', '保衛勇士', '$n，見到你真好。戰鬥暫時沉靜了下來，我們應該加緊腳步以備齊物資。我的研究指出，近來在冰川瀑布被殺害的士兵，他們所穿的護甲被灌注了一股巨大的能量。部落正在那一帶蒐集護甲。$B$B馬上前往冰川瀑布，殺掉任何你遇到的部落成員。將他們灌能的護甲帶回來給我。$B$B如果你不能找到任何部落成員，你大概會找到一副被元素殺害的冒險者護甲。', '冬握堡壘的巫女凱拉娜要你前往冰川瀑布，從部落玩家身上收集10件灌魔部落護甲。', '', '去找冬握堡壘的巫女凱拉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13154 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13154, 'zhTW', '龍骨與箭頭', '元龍實在是妙不可言!好吧，至少他們的骨頭是!我曾經以龍骨製的箭頭裝備我們的弓箭手。不幸地，在安格拉薩的大屠殺後，在龍骨荒野上幾乎不可能找到龍骨。$B$B然而，冬握湖西緣的暗影森林中，仍有著多得足以淹沒我們的龍骨。$B$B前往暗影森林，帶回任何你所找到的龍骨碎片!$B$B部落也在那一帶收集龍骨碎片。殺光他們!', '冬握堡壘的弓箭商藍道夫要你前往暗影森林，從部落玩家身上取得10個龍骨箭袋。', '', '去找冬握堡壘的弓箭商藍道夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13158 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13158, 'zhTW', '謹慎是關鍵', '聽我說，$r。不久前，紫羅蘭堡的一件意外引起了我的注意。看來藍龍即將對達拉然發動全面的入侵!我要你馬上前往監獄，並與守望者艾圖拉斯交談。他會告訴你詳情。不只這樣，我需要做到滴水不漏的地步。我們應該儘可能地不要驚動達拉然市民。我的指示夠清楚嗎?很好，現在去吧!', '羅甯要你前往達拉然的紫羅蘭堡，並與守望者艾圖拉斯交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13159 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13159, 'zhTW', '牽制', '這是監獄的鑰匙。$B$B我和我的人馬會待在這裡，萬一你無法壓制攻勢，我們將是最後一道防線。$B$B記得和辛克拉麗中尉交談。她會讓你進入監獄的防線。$B$B快點，$r。沒有時間了。若沒有你的協助，我留在裡面的人馬撐不了多久的。記得向我回報，一旦入侵的勢力成功地被壓制。', '守望者艾圖拉斯要你進入紫羅蘭堡，並擊退藍龍的攻勢。一旦霞妮苟莎被殺害，向艾圖拉斯回報。', '', '去找達拉然的守望者艾圖拉斯。', '殺害霞妮苟莎', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13160, 'zhTW', '慘不忍睹', '石像鬼是偵察的理想人選，從空中發動攻擊時也相當致命，但是他們有個顯著的弱點。大部分的石像鬼，必須以石化的狀態休息很長的時間，好維持能使笨重身軀飛行的能量。$B$B當我透過你操控的斥候之眼凝視，我注意到東邊和南邊的牆裡，有一大群冰膚哨兵正處在休眠的狀態。讓潛獵者跳上他們的岩架，趁他們睡眠時一網打盡。', '苦難高崗上奸詐的維瑞希要你使用輕盈潛獵者的投擲技能，摧毀12個睡眠中的冰膚哨兵。', '', '去找寒冰皇冠的奸詐的維瑞希。', '冰膚哨兵已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13161 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13161, 'zhTW', '穢邪騎士', '是時候斬除他們的首腦了。$B$B我曾經在洛基爾身邊待過好一陣子。他的穢邪技巧比我認識的每一個死亡騎士都好，他也同樣地殘忍無情。$B$B當洛基爾在自己的地盤上戰鬥時，他的力量最為強大。很不幸地，我們別無選擇也無法顧慮那麼多，你只能靠自己了，盡量避免和他的不死爪牙交鋒，然後竭盡全力取得勝利。$B$B敏捷靈活是關鍵，$c，還有切莫低估他。', '苦難高崗上奸詐的維瑞希要你殺死穢邪騎士洛基爾。', '', '去找寒冰皇冠的奸詐的維瑞希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13162 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13162, 'zhTW', '冰霜騎士', '莎菲…莎菲是個不太一樣的死亡騎士。她會讓你沉浸於甜言蜜語之中，你在她身上嗅不出一絲邪惡的氣息。趁你鬆懈之時，她就會出奇不意地作掉你，臉上甚至還帶著笑容。$B$B我相信你能擊敗莎菲，但別過分自信。她的長處，就是令她的敵人錯估形勢，處於致命的懈怠中，然後以漫天蓋地的冰霜攻擊粉碎對手。$B$B別放鬆你的戒心，也別小看她。', '苦難高崗上奸詐的維瑞希要你殺死冰霜騎士莎菲。', '', '去找寒冰皇冠的奸詐的維瑞希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13163 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13163, 'zhTW', '血魄騎士', '貝洛克是我所見過中極少數可以成為死亡騎士的維酷人之一，這多半要歸功於他的殘忍嗜血。若你能夠擊敗他，就算是替我們除去了一個心腹大患。$B$B和他戰鬥時，盡量和你的同伴保持距離。他會抽取你的生命能量為其所用，所以你必須儘可能地阻撓他使用這項技能。$B$B我對你有信心。你要確定他的死亡。', '苦難高崗上奸詐的維瑞希要你殺死血魄騎士貝洛克。', '', '去找寒冰皇冠的奸詐的維瑞希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13164, 'zhTW', '血禍的命運', '隨著苦難大軍的騎士不斷死去，現在正是除去其領袖 - 歐貝茲·血禍的大好時刻。$B$B莫格萊尼在你出任務時來找過我，他告訴我歐貝茲的藏匿處。就在冰冠城塞正下方有個很大的深穴 - 你可以在其門外找到歐貝茲。$B$B我們已派遣一些黯刃騎士的菁英前往 - 集結夥伴並投入戰鬥吧。血禍的死期到了。', '苦難高崗上奸詐的維瑞希派遣你去殺死歐貝茲·血禍。', '', '去找寒冰皇冠的奸詐的維瑞希。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13166, 'zhTW', '黯黑堡爭奪戰', '指揮大廳的局勢已經安定下來了，但是巫妖王在亞榭洛之心留給了我們一份小禮物。七拼八湊的恐怖人物，縫補者，另外還有一幫憎惡體佔據著二樓。$B$B使用這個傳送門，到二樓去清除天譴軍團的餘孽。別單獨面對縫補者!你得和亞榭洛的死亡騎士一起對付那個怪物!$B$B去吧，$n。我會罩你的!', '殺掉10個天譴軍團，並協助殺掉縫補者。事成之後，向大領主達瑞安‧莫格萊尼回報。', '', '去找黑鴉堡壘的大領主達瑞安‧莫格萊尼。', '', '縫補者', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13167, 'zhTW', '狙殺逆王', '逆王阿努巴拉克，以阿茲歐-奈幽，這個一度光榮輝煌的地底王國作為根據地。$B$B自他叛變以來，他已使我們的家鄉墮落成卑鄙污穢之地。他統率著一支不死奈幽蟲族的軍隊，如同其領導者，也都出賣了靈魂來服侍巫妖王。$B$B為逆王的統治畫下一個句點吧，$c。這對我們雙方的子民都好。$B$B若你能夠達成過往眾人所辦不到的事，就將阿努巴拉克的軀殼帶來見我。', '那金之淵裡的『排除者』齊力克斯交付給你一個任務，要你擊敗阿茲歐-奈幽的阿努巴拉克。然後將阿努巴拉克的裂殼帶回給齊力克斯。', '', '去找龍骨荒野的『排除者』齊力克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13168, 'zhTW', '臨別禮物', '看看我們找到了什麼...支配之眼。神教通常會盡其所能地確保這些東西的安全，但我猜，當我們在他們的家中大開殺戒時，他們並沒有退路。$B$B支配之眼，能賦予使用不同力量的任何種族能力，精準地控制一隻不死爪牙。如同你能想像的，用在笨拙的食屍鬼和骷髏身上，將非常有效。$B$B介意嘗試一下嗎?用支配之眼，控制一隻被俘的幽影吧。', '暗影穹殿的凱力多斯‧血刃要求你，使用支配之眼以控制一個被俘虜的幻象看守者。', '奪取幻影守衛的控制權', '去找寒冰皇冠的凱力多斯·血刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13169 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13169, 'zhTW', '不死生物的忠實朋友', '如同往常，西南方薩鋼礦場裡的不死生物老是讓他們的瘟疫獵犬挨餓，好讓牠們更具攻擊性。利用幽影靠近牠們並餵飽其中幾隻，我保證牠們在酒足飯飽之後，只要他們的主人不在附近，就完全不會甩你。$B$B餵飽牠們以前千萬不要靠近。你的幽影匿蹤可騙不過牠們的鼻子。', '暗影穹殿的凱力多斯‧血刃要求你，利用幻象看守者餵飽18隻飢餓的瘟疫獵犬。', '', '去找寒冰皇冠的凱力多斯·血刃。', '已餵食飢餓瘟疫獵犬', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13170, 'zhTW', '弱者才需要榮耀', '一般來說，食屍鬼是很脆弱的東西，西南方薩鋼礦場裡的哨兵更是無一例外。利用一隻幽影，我相信你可以偷偷地溜進去，並無聲無息地放倒他們的監視者。$B$B在合理的時間內，儘可能地除掉你所遇到的所有監視者...不久我們將發動進攻，我希望敵人能盡量地被削弱。', '暗影穹殿的凱力多斯‧血刃希望你去暗殺20個不安的監視者。', '', '去找寒冰皇冠的凱力多斯·血刃。', '不安的哨兵已暗殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13171 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13171, 'zhTW', '從何而來', '我比較關心的是沿這條路走往西南方的薩鋼礦場。他們正開採出數量龐大的礦石，而我希望了解，他們究竟用來建造什麼。要達到這個目的，我們將先從削弱對方的防禦下手。$B$B我注意到，有一系列水晶散佈在那據點的週遭，我假定它們是某種防禦的設施，類似通靈塔之類的。利用幻象看守者摧毀你找到的任何水晶。', '暗影穹殿的凱力多斯‧血刃，派遣你去排除10個天譴牽制水晶。', '', '去找寒冰皇冠的凱力多斯·血刃。', '被放逐的天災水晶', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13172 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13172, 'zhTW', '混亂之源', '好用的工具，不是嗎?削弱他們的防禦這件事幹得真好，$c。現在我們可以推動主要的攻勢了。$B$B計畫很簡單 - 我們將摧毀一切會動的玩意，混到裡頭去，然後在一團混亂中偷取情報。$B$B準備好了就告訴我，我會讓一頭骷髏獅鷲獸與你同行。', '暗影穹殿的凱力多斯‧血刃，派遣你去哀泣礦場並屠殺80個不死生物。和他對話，以取得一頭骷髏獅鷲獸協助你進行突襲。', '', '去找寒冰皇冠的凱力多斯·血刃。', '哭泣採石場的亡靈已屠殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13173 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13173, 'zhTW', '騷動之中', '我們已經弄到了不少工人。他們會很有用的。$B$B我要你用眼睛控制其中一個工人返回挖掘場。現在整個營地都陷入了混亂，他們肯定會把當成你在襲擊中走散的工人，你不會露餡的。$B$B你要找出工廠的負責人並動手幹活。如果夠幸運的話，我們很快就能發現那些邪鐵的去向。我會通過眼睛關注你的。', '我們抓到了不少工人，他們應該能派上用場。$B$B我要你用眼睛把其中一名工人帶回採石場。既然整座營地已經亂成一團，他們絕對沒辦法把你跟其他被攻擊打散的工人分辨出來。$B$B找到負責這次行動的人，然後開始工作。運氣好的話，我們很快就能查出那些薩隆邪鐵被運去哪裡了。我會透過眼睛在旁看著你。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13174 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13174, 'zhTW', '騷動之中', '打斷他們的運作只是計畫的一部分。另一個重要的目的是找出薩鋼究竟送去了哪裡。我們知道其中一些目的地，但是薩鋼的產量讓我覺得這背後有個更大的計畫。$B$B當你在礦場時，留意任何可以找到的文件。若你騎乘獅鷲獸去的話，你可以在幹完壞事後隨時跳下來。', '暗影穹殿的凱力多斯‧血刃要你取回一份哀泣礦場文件、一份哀泣礦場帳本、一份哀泣礦場地圖和一份哀泣礦場日程表。', '', '去找寒冰皇冠的凱力多斯·血刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13177 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13177, 'zhTW', '以其人之道，還治其人之身', '歡迎來到冬握堡壘，$n。你的任務很簡單。擊敗十個部落菁英。現在，去吧!為聯盟帶回勝利!', '冬握堡壘的指揮官桑奈希要求你殺掉10個部落成員。', '', '去找冬握堡壘的指揮官桑奈希。', '部落成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13178 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13178, 'zhTW', '趕盡殺絕!', '歡迎來到冬握堡壘，$n!督軍卡爾洛斯下了一道命令:趕盡殺絕!$B$B讓十個最強悍的聯盟成員倒下後，回來找我。', '冬握堡壘的指揮官達多許要求你殺掉10個聯盟成員。', '', '去找冬握堡壘的指揮官達多許。', '聯盟成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13179 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13179, 'zhTW', '以其人之道，還治其人之身', '歡迎來到冬握湖，$n。你的任務很簡單，擊敗十個部落的精英。去吧!為聯盟帶來勝利!', '冬握湖的指揮官桑奈希要求你殺掉10個部落成員。', '', '去找冬握堡壘的指揮官桑奈希。', '部落成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13180, 'zhTW', '趕盡殺絕!', '歡迎來到冬握湖，$n!督軍卡爾洛斯下了一道命令:趕盡殺絕!$B$B讓十個最強悍的聯盟成員倒下後，回來找我。', '冬握堡壘的指揮官達多許要求你殺掉10個聯盟成員。', '', '去找冬握堡壘的指揮官達多許。', '聯盟成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13181, 'zhTW', '冬握之捷', '指揮官桑奈希的腳下堆了這麼多的部落屍體，他一定很滿意，但是對驍勇遠征軍而言，控制冬握才是最重要的目標。你得確保我們能徹底控制冬握湖。$B$B不過，你別想只靠你的盟友做這些骯髒的事情來不勞而獲。如果你在戰鬥結束後還沒有到達徵召的第二級官階就別回來。', '在冬握戰場中獲勝，並向冬握湖的戰術軍官阿布拉米斯回報。你必須參與戰鬥才能擁有勝利的榮耀。', '在冬握湖取得勝利', '到冬握湖找戰術軍官阿布拉米斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13182 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13182, 'zhTW', '別忘了那些蛋!', '遍佈於阿茲歐-奈幽，天譴奈幽蟲族總是小心翼翼地孵育將孵化的蛋，這是牠們數量迅速滋長的原因。$B$B若能清除掉不死生物玷汙過，用以鳩佔鵲巢的敗壞蟲蛋，對牠們的洞穴而言是件好事。$B$B當你探索那一度是阿茲歐-奈幽的廣袤地帶，一定要清理我們古老家園中，任何你看到的天譴蛋。', '那金之淵裡的『排除者』齊力克斯，要你進入阿茲歐-奈幽並摧毀6個奈幽天譴蛋。', '', '去找龍骨荒野的『排除者』齊力克斯。', '摧毀奈幽天譴蛋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13183 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13183, 'zhTW', '冬握之捷', '雖然達多許必定會為我們痛宰敵人感到滿意，但掌控冬握堡壘才是我們的最終目的。不擇手段也要確保冬握湖是我們的。$B$B然而，你別想只靠你的盟友做這些骯髒的事情來不勞而獲。如果你在戰鬥結束後還沒有到達徵召的第二級官階就別回來。', '在冬握戰場中獲勝，並向冬握湖的戰術軍官科伊瑞斯回報。你必須要參與戰鬥才能擁有勝利的榮耀。', '在冬握湖取得勝利', '到冬握湖找戰術軍官科伊瑞斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13185 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13185, 'zhTW', '突破重圍', '我聽到他們了!聯盟就要來了。摧毀三部聯盟攻城器，然後回來找莫普。', '冬握堡壘的莫普中尉要你摧毀3台聯盟攻城器械。', '', '去找冬握堡壘的莫普中尉。', '聯盟攻城裝置已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13186 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13186, 'zhTW', '突破重圍', '這城堡被部落軍隊包圍，只是時間上的問題了。摧毀3台他們的攻城裝置，然後向我回報。', '冬握堡壘的資深爆破兵勒茍索要你摧毀3台部落攻城器械。', '', '去找冬握堡壘的資深爆破兵勒茍索。', '部落攻城裝置已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13187 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13187, 'zhTW', '無面者', '在對抗不死生物的戰爭中，隨著家園一寸一寸地淪陷，我的子民也愈發絕望。$B$B那些被稱為無面者的生物，我們只知道他們曾不慎觸怒了古老神衹的意旨。$B$B總而言之，我們無法同時與這些強大的敵人兩面作戰。$B$B也許借助你的幫助，我們終於可以打敗無面者。', '先知伊須特要你殺死信使沃菈齊及其身邊的三個忘卻者。', '', '去找龍骨荒野的『排除者』齊力克斯。', '被遺忘者已摧毀', '已擊敗傳令官沃拉茲', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13188 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13188, 'zhTW', '諸王之道', '你從今而後，永遠都是一名黯刃騎士，$n，但你要知道：你曾是聯盟的英雄。$B$B<達瑞安凝視著你。>$B$B我們的騎士團若要存活下去，必定得要建立盟友。你必須代表黯刃騎士團前往聯盟。$B$B在我東南方的平臺上，有個通往暴風城的傳送門。帶著這封由弗丁為你所寫的信，送到安杜因‧烏瑞恩國王手中。通過傳送門吧。', '把信件送給聯盟的國王，暴風城的暴風要塞中的安杜因‧烏瑞恩。', '', '去找艾爾文森林的瓦里安·烏瑞恩國王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13189 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13189, 'zhTW', '薩魯法爾的祝福', '你從今而後，永遠都是一名黯刃騎士，$n，但你要知道：你曾是部落的英雄。$B$B<達瑞安凝視著你。>$B$B我們的騎士團若要存活下去，必定得要建立盟友。你必須代表黯刃騎士團前往部落。$B$B在我東南方的平臺上，有個通往奧格瑪的傳送門。帶著這封由弗丁為你所寫的信，送到薩魯法爾霸王手中。通過傳送門吧。', '把信件送到奧格瑪交給薩魯法爾霸王。', '', '去找奧格瑪的索爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13190 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13190, 'zhTW', '好時光的一切', '安卡罕特，我們的故鄉...$B$B我夢想著，終有一天，我們會逐退佔據古老家園的死亡與黑暗。為了使夢想成真，我有個削弱敵人士氣的計畫。$B$B他們珍貴的看守者必須被燒死!$B$B帶回他們的屍體，放在城市深處的火盆上。軀體焚燒過的氣味會存留於空氣中，提醒我們的敵人，他們的弱點。$B$B要當心，$c!他們的不死軀體非常脆弱，而且會迅速地毀壞。', '那金之淵裡的『排除者』齊力克斯要求你，帶回一具安卡哈看守者的屍體，安放在安卡罕特的安卡罕特火盆上。此任務只能於英雄模式下完成。', '', '去找龍骨荒野的『排除者』齊力克斯。', '安卡哈守望者的屍體已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13191 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13191, 'zhTW', '為石毀車補給燃料', '為了部落，$n!雖然戰鬥就要結束，我們還是得為聯盟的下一波攻勢做好準備!去冬握東南邊的火焰熔爐取回十個永恆餘燼。$B$B這些餘燼混合煤塊後可以作為石毀車和攻城機具的燃料。$B$B我聽到報告，聯盟豬玀沒日沒夜地採集餘燼。殺光他們，奪走他們的餘燼!如果他們已經遺棄了那區域，做好準備，和那一帶的火元素戰鬥，直到你找到餘燼為止!', '冬握堡壘的攻城鐵匠重蹄要你前往火焰熔爐，從聯盟玩家身上取得10個永恆餘燼。', '', '去找冬握堡壘的攻城鐵匠猛蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13192 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13192, 'zhTW', '護衛城牆', '嘿，老兄。這地方搞得我皮皮挫的啦，你不暸的嗎?$B$B路上好多孤魂野鬼。我想弄個咒毒防護結界，但是我需要一些靈魂，老兄。別的我不要，只有強悍勇士的靈魂能用。$B$B冬握東邊有個冰川瀑布，那裡的特別性質能夠淬鍊出我要的靈魂。在那裡幹掉聯盟，搞不好他們就有我要的東西。$B$B帶回那些傢伙的護甲。如果沒有聯盟在那，可能就是被元素先下手了，老兄。', '冬握堡壘的咒毒大師符金要求你，從冰川瀑布取回10套灌能的護甲。', '', '去找冬握堡壘的咒毒大師符金。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13193 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13193, 'zhTW', '龍骨與箭頭', '為什麼給我裝備弓箭手的工作?我是個詩人，不是遊俠!好吧，抱怨也沒用。$n，我需要龍骨以製造箭頭。$B$B前往冬握西邊的暗影森林。從最近的一次戰鬥後開始，聯盟也在那個區域採集龍骨。殺掉他們並拿走龍骨。$B$B如果失敗的話，你也可能很幸運地從那一帶的靈魂弄到龍骨。我聽說他們喜歡將活的獵物弄死，然後串在龍骨上。', '冬握堡壘的維耶隆‧炎羽中尉要你前往暗影森林，從聯盟玩家身上取得10個龍骨箭袋。', '', '去找冬握堡壘的維耶隆‧炎羽。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13194 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13194, 'zhTW', '以玫瑰治療', '在戰火稍事歇息之際，或許有人會相信和平的曙光就要降臨於斯。然而令人沮喪，這並非吾輩命運之歸宿。$B$B前往冬握湖西南部的生命冷原。我需要生於當地的玫瑰，用以製造治療創傷的藥膏。$B$B不幸地由於聯盟的濫採，玫瑰已變得駭人地稀少。殺掉生命冷原上的聯盟成員，從他們身上取走草藥袋。$B$B如果此舉不成，或許鞭笞者身上也會有。', '原獵者穆法特要你前往生命冷原，從聯盟玩家身上取得10個聯盟草藥袋。', '', '去找冬握堡壘的原獵者穆法特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13195 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13195, 'zhTW', '罕見的草藥', '我的媽，這裡有夠冷!讓我想起阿古斯星上風暴圍繞的卡里諾斯山脈。無論如何，這裡的冰霜風雪會讓我們的士兵著涼的。$B$B前往冬握堡壘西南方的生命冷原，把10個部落草藥袋帶回來給我。我會將它們磨成抵禦寒冷用的草藥。$B$B曾有人目擊部落也在那一帶採集草藥。別猶豫，不要留下任何活口，然後取走他們的草藥袋!$B$B你或許也能在那個地區的鞭笞者身上找到草藥袋。', '冬握湖的隱士泰莎要你前往生命冷原，從部落玩家身上取得10個部落草藥袋。', '', '去找冬握堡壘的隱士泰莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13196 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13196, 'zhTW', '龍骨與箭頭', '元龍實在是妙不可言!好吧，至少他們的骨頭是!我曾經以龍骨製的箭頭裝備我們的弓箭手。不幸地，在安格拉薩的大屠殺後，在龍骨荒野上幾乎不可能找到龍骨。$B$B然而，冬握湖西緣的暗影森林中，仍有著多得足以淹沒我們的龍骨。$B$B前往暗影森林，帶回任何你所找到的龍骨碎片!$B$B部落也在那一帶收集龍骨碎片。殺光他們!', '冬握湖的弓箭商藍道夫要你前往暗影森林，從部落玩家身上取得10個龍骨箭袋。', '', '去找冬握堡壘的弓箭商藍道夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13197 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13197, 'zhTW', '為石毀車補給燃料', '$n!是你該現身的時候了。我們很可能會在這場戰鬥中吃鱉，所以最好儘早開始為下回準備!去冬握湖東南部的火焰熔爐取回一些永恆餘燼。$B$B這些餘燼混合煤塊後可以作為石毀車和攻城機具的燃料。$B$B噢，還有，如果你在那裡遇到部落，別猶豫，殺光他們，奪走他們的餘燼。我們一定要阻止他們繼續佔據要塞!', '冬握湖的攻城大師斯托哈德要你前往火焰熔爐，從部落玩家身上取得10個永恆餘燼。', '', '去找冬握堡壘的攻城大師斯托哈德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13198 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13198, 'zhTW', '保衛勇士', '$n，見到你真好。我們應該加緊腳步以準備下一波對要塞的攻勢。我的研究指出，近來在冰川瀑布被殺害的士兵，他們所穿的護甲被灌注了一股巨大的能量。部落正在那一帶蒐集護甲。$B$B馬上前往冰川瀑布，殺掉任何你遇到的部落成員。將他們灌能的護甲帶回來給我。$B$B如果你找不到任何部落成員，也許可以在那裡找到被元素生物殺害的冒險者所遺留下來的護甲。', '冬握湖的巫女凱拉娜要你前往冰川瀑布，從部落玩家身上取得10件灌魔部落護甲。', '', '去找冬握堡壘的巫女凱拉娜。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13200, 'zhTW', '為石毀車補給燃料', '為了部落，$n!雖然戰鬥就要平息，我們還是得為奪回要塞做好準備!去冬握東南邊的火焰熔爐取回十個永恆餘燼。$B$B這些餘燼混合煤塊後可以作為石毀車和攻城機具的燃料。$B$B我聽到報告，聯盟豬玀沒日沒夜地採集餘燼。殺光他們，奪走他們的餘燼!如果他們已經遺棄了那區域，做好準備，和那一帶的火元素戰鬥，直到你找到餘燼為止!', '冬握湖的攻城鐵匠重蹄要你前往火焰熔爐，從聯盟玩家身上取得10個永恆餘燼。', '', '去找冬握堡壘的攻城鐵匠猛蹄。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13201 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13201, 'zhTW', '以玫瑰治療', '許多勇士在戰鬥中倒下，但若缺乏妥善的照料，會有更多人死於負傷。$B$B前往冬握西南方的生命冷原。我需要生於當地的玫瑰，用以製造治療創傷的藥膏。$B$B不幸地，由於聯盟的濫採，玫瑰已變得駭人地稀少。殺掉生命冷原上的聯盟成員，從他們身上取走他們的草藥袋。$B$B若此舉不成，或許一兩個鞭笞者身上會有。', '冬握湖的原獵者穆法特要你前往生命冷原，從聯盟玩家身上取得10個聯盟藥草袋。', '', '去找冬握堡壘的原獵者穆法特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13202 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13202, 'zhTW', '大禍臨頭', '嘿老兄。看到聯盟那些傢伙了嗎?他們躲在自己的堡壘裡，看來倒挺安逸的。$B$B看來他們過得太爽了點，對吧?我想惡搞一下那地方，但是我需要一些靈魂，老兄。不過我可不是巫毒符不挑，我只要可以勝任工作的強悍勇士靈魂。$B$B冬握東邊的冰川瀑布有某種特質，可以淬鍊出我要的靈魂。作掉那裡的聯盟成員，也許他們有我們需要的東西。$B$B帶回那些小傢伙的護甲。如果那裡沒有聯盟成員，或許是被元素先下手為強了，老兄。', '冬握湖的咒毒大師符金要你前往冰川瀑布，從聯盟玩家身上取得10件灌能聯盟護甲。', '', '去找冬握堡壘的咒毒大師符金。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13203, 'zhTW', '冬幕節禮物', '', '禮物上有一個小牌子寫著:冬幕節快樂，$n!。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13204 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13204, 'zhTW', '惡臭磨菇', '一朵畸形的磨菇-似乎是剛從蠻穴野獸惡臭又滿佈分泌物的屍塊上掉下來的磨菇。檢視它時，你被中人欲嘔的惡臭薰得差點昏過去。$B$B你想知道，是否這是奈幽蟲族的盤中美味。將這黏涕涕的噁心玩意放進你的背包，你決定要找出真相……', '你必須在安卡罕特的蠻穴野獸身上，採集6朵怪誕菌菇，並送去給那金之淵裡的『排除者』齊力克斯。', '', '去找龍骨荒野的『排除者』齊力克斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13205 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13205, 'zhTW', '撤除武裝', '從我身邊拿走它，$g小夥子:小女孩;，這些維酷武器真是齷齪!$B$B我親自觸碰了它們的邊緣，其中有某種古怪。令人迷惑地勻稱、邪惡的鋒利刃口，全然是種致命武器。$B$B潛進他們的堡壘，若沒有意外的話，弄來些他們的武器。$B$B底限是:越少維酷人在附近揮舞斧頭越好。', '防衛者摩丹要你進入俄特加德要塞，並偷走5件維酷武器。', '', '去找凜風峽灣的防衛者摩丹。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13206 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13206, 'zhTW', '撤除武裝', '我們應該好好研究這些野蠻人武器中的奧妙!$B$B如果你曾目睹，他們是如何輕易地把我的同袍大卸八塊，你就會了解我的急迫感。$B$B搜索那地方，帶回他們的武器，能拿多少就拿多少。', '黑暗遊俠瑪拉要求你，從俄特加德要塞偷走5件維酷武器，然後送回她手中，她會在俄特加德要塞中等候。', '', '去找凜風峽灣的高階執行官安賽姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13207 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13207, 'zhTW', '石之大廳', '嗯哼，在這裡看到其他冒險者是蠻令我驚訝的。$B$B如果我的研究正確，這裡一定有值得探尋的巨大發現!$B$B如果你可以讓我無後顧之憂，我倒是很歡迎有你與我作伴。', '布萊恩‧銅鬚要求你和他一道尋找石之大廳裡的秘密。', '', '去找岩石大廳的布萊恩·銅鬚。', '布蘭恩的探索已完成', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13210 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13210, 'zhTW', 'Blizzard Account: - DEM - E - FLAG', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13211 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13211, 'zhTW', '以火淨化', '天譴軍團將我們倒下的弟兄轉化成食屍鬼或骷髏，或肢解他們的軀體以製造憎惡體，回過頭來對付我們。這一切必須被阻止!$B$B為了保衛家園和同胞而倒下的弟兄都是英雄，他們不該落得如此可悲的命運。再者，我們實在無法承受在戰場上與他們干戈相向的痛苦。帶著這把火炬前往血肉作坊，燒掉任何你在再活化聖所與憎惡體實驗室裡找到的屍體。', '黑色守望的十字軍歐拉金‧山瑞斯要求你，以歐拉金的火炬焚毀7具膿瘡屍體。', '', '去找寒冰皇冠的十字軍歐拉金·山瑞斯。', '腐爛屍體已焚燒', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13212, 'zhTW', '他被大卸八塊了', '因為十字軍歐拉金被綁架，在對血肉作坊的最終攻擊即將來到之際，銀白十字軍卻是群龍無首。雖然對我而言，他和其他十字軍並無二致，但是十字軍們可不是這麼想。$B$B我實在不喜歡在這件事上浪費時間，但我別無選擇。我們英勇的十字軍勇士大概已經被肢解，要用來製造憎惡體了。下去血肉作坊，宰掉和我方戰鬥的肥胖恐獸，找回歐拉金的軀體。', '找回歐拉金的軀幹、歐拉金的雙腳、歐拉金的左手、和歐拉金的右手，帶回給黑色守望的黑騎兵阿爾利。', '', '去找寒冰皇冠的黑騎兵亞爾利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13214 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13214, 'zhTW', '英靈殿之戰:已逝的英雄', '若你認為你準備好了，我剛好有場可以讓你一展身手的比賽。$B$B另一組外來者認為，他們已準備好要接受英靈殿的嚴苛挑戰。他們恃傲而來，但最終和其他人亦無二致。$B$B若你自視不凡--自恃擁有可與傳奇戰士匹敵的技巧與經驗--那麼，請接受挑戰。', '英靈殿的蓋爾維孚向你挑戰，在一場戰鬥中擊敗六名死去的英雄:艾德雷斯、『半魂』蓋內斯、賈卓斯、瑪蘇德、里希和塔拉。若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。', '已擊敗陣亡英雄', '去找寒冰皇冠的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13215 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13215, 'zhTW', '英靈殿之戰:『黑暗大師』齊特瑞司', '許多種族不遠千里而來，只為了在英靈殿裡證明他們自己的實力。有些甚至是從地底下的世界來的。$B$B『黑暗大師』齊特瑞司就是其中一人。$B$B來自地底深處，瘋狂支配之處，齊特瑞司要求和奇人異士在環中決鬥。而你就是不二人選。$B$B你敢面對這個奈幽夢魘嗎，$r?', '英靈殿的蓋爾維孚向你挑戰，要你擊敗『黑暗大師』齊特瑞司。若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。', '已擊敗黑暗宗師基特里克斯', '去找寒冰皇冠的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13216 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13216, 'zhTW', '英靈殿之戰:席格芮‧冰誕回來了', '你的一個老仇家回來了:席格芮‧冰誕。也許你還記得在蠻荒岩臺上擊敗她的往事?$B$B沒關係，她一定記得你。她堅持要給她個再次證明自己的機會。$B$B就我個人而言，這是另一個復仇的機會，但對這裡同樣也有好處。$B$B我就將場子留給你了，$n。你願意再次面對席格芮‧冰誕嗎?', '英靈殿的蓋爾維孚向你挑戰，要你擊敗席格芮‧冰誕。若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。', '已擊敗希格麗德·冰生者', '去找寒冰皇冠的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13217 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13217, 'zhTW', '英靈殿之戰:卡納基!', '你能走到這一步，真的相當了不起，$n，但是接下來你在英靈殿中得面對的，是遠遠超出你想像的巨大恐懼。$B$B我該警告你馬上回頭。卡納基是巫妖王邪惡心腹打造而成的龐然血肉怪物。$B$B我不覺得你和你的朋友有所勝算。不過，你有權決定。', '英靈殿的蓋爾維孚向你挑戰，要你擊敗卡納基。若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。', '已擊敗卡奈奇', '去找寒冰皇冠的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13218 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13218, 'zhTW', '英靈殿之戰:死擊族長', '你的技術已引起卓頓海姆維酷人的注意，$n。巴納霍格族長對你有很大的興趣，而且堅持要當你的下一個對手。$B$B如果你認為卡納基很可怕，那你大可以回家去了。巴納霍格族長的外號是「死擊」。我想你應該猜得到這名號從何而來的。$B$B你願意接受族長的挑戰嗎?', '英靈殿的蓋爾維孚向你挑戰，要你擊敗『死擊』巴納霍格族長。若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。', '已擊敗酋長巴納霍格', '去找寒冰皇冠的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13219 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13219, 'zhTW', '英靈殿之戰:最後的挑戰', '我擔心你的勝利終將導致你的毀滅，$n。$B$B<要是華爾琪的臉色能更白的話，你會覺得她一臉慘白。>$B$B關於你在英靈殿中的勝利，聲名已遠播至冰冠城塞，擾動了一個你絕對不想面對的敵手。$B$B值此非常時刻，薩杜瓦爾親王已在趕往此處的路上。吉雍納警告你該逃離此地，我實在不能不認同。$B$B你怎麼想?他已在途中。你要在最後一場戰鬥中，面對這個血腥親王嗎?', '英靈殿的蓋爾維孚向你挑戰，要你擊敗薩杜瓦爾親王。若你成功，跟在英靈殿南緣俯瞰的『殘酷』吉雍納交談。', '已擊敗桑多瓦爾王子', '去找寒冰皇冠的『殘酷』吉雍納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13220 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13220, 'zhTW', '將歐拉金拼湊回來', '我們實在沒時間將歐拉金的軀體拼在一起。幸好，天譴軍團提供你一個作縫補活的好地方。$B$B在血肉作坊的血肉巨人實驗室附近，有個再活化聖所。在那一帶找個絲線捲、一把醫生的切割刀。將歐拉金的軀體帶去聖所裡的大實驗室，然後幹活吧。', '取得一個絲線捲、以及醫生的切割刀，帶往再活化肉塊聖所，試著利用歐拉金的殘骸將其再活化。一旦工作完成，向黑色守望的黑騎兵阿爾利回報。', '', '去找寒冰皇冠的黑騎兵亞爾利。', '已復活十字軍奧拉金·聖萊斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13221 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13221, 'zhTW', '我還沒死!', '聖光對我微笑。我還沒死於這活生生的夢魘中，但若我不能逃脫，天譴軍團將殺了我，並肢解我的軀體以作為他們『工作』的原料。$B$B我無法獨力做到這件事，我的孩子，唯有藉助你的幫忙，我才能活下來再次對抗天譴軍團。$B$B在天譴軍團的劊子手了結我以前，你能幫助我幫逃出去嗎？', '護送卡瑪洛斯神父至安全之處，並向破天者號上的虔誠的亞柏薩倫回報。', '護送卡馬羅斯神父至安全處', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13222 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13222, 'zhTW', '護衛攻城行動', '向前向中看齊，$n!我們就要展開對冬握堡壘的攻擊。那些部落畜生以為可以懦弱地躲在城牆之後?嗯哼，我不認為!我們將讓他們見識到地精科技的威力，並且粉碎他們的城牆!$B$B然而，最具威力的攻城器具也需要人手操作。操作或護衛一台攻城載具，直到它摧毀三座部落建築。', '冬握湖的資深爆破兵勒茍索要你駕駛或保護一個攻城器，讓其順利摧毀三個建築物。士兵階級以上的玩家可於哥布林工坊建造攻城器。', '', '去找冬握堡壘的資深爆破兵勒茍索。', '已防禦攻城載具', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13223 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13223, 'zhTW', '護衛攻城行動', '討厭的聯盟不會佔領要塞太久的。莫普將粉碎他們的城牆，但是莫普得待在營地裡。莫普希望他可以粉碎想破壞部落石毀車的聯盟成員。$B$B你，$n!你來做莫普的工作。保護3台進攻聯盟建築的攻城載具。聯盟不會想到你會保護石毀車。讓聯盟知道莫普有多聰明!', '冬握湖的莫普中尉要你保衛或駕駛一台攻城載具，讓其順利摧毀三座聯盟建築物。有階級的部落玩家可於哥布林工坊建造攻城器。', '', '去找冬握堡壘的莫普中尉。', '已防禦部落攻城載具', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13226 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13226, 'zhTW', '審判日將臨!', '我們無法獨力擊敗巫妖王。分裂的我們唯有敗亡一途!$B$B我懇求你回應我們的呼喚，$g兄弟:姐妹;。銀白十字軍接受所有願意為戰爭奉獻心力的志士。大領主提里奧·弗丁在銀白先鋒駐地親自等著你!坐上你的坐騎，飛往寒冰皇冠的東南邊境。你可以在那裡找到大領主弗丁以及銀白十字軍的士兵。去吧，$c，為了審判日將臨!', '在寒冰皇冠的銀白先鋒駐地，向大領主提里奧·弗丁報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13228, 'zhTW', '破碎前線', '什麼戰鬥?!那支部隊進行的是偵察任務!$B$B還有聯盟的消息是怎麼一回事 - 你確定他說的是聯盟嗎?$B$B聽我說，$n!我得知道發生了什麼事，現在!$B$B馬上前往該地，找到解答!搜遍戰場並尋找生還者 - 線索 - 什麼都好!', '搭乘著奧格林之錘的寇姆‧黑疤要求你，前往破碎前線並詢問垂死的狂戰士，以了解發生的事。', '', '去寒冰皇冠找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '已審問垂死的狂戰士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13229, 'zhTW', '我還沒死!', '聖光對我微笑。我還沒死於這活生生的夢魘中，但若我不能逃脫，天譴軍團將殺了我，並肢解我的軀體以作為他們『工作』的原料。$B$B我無法獨力做到這件事，$c，除非借助你的幫助，我才能活下來再次對抗天譴軍團。$B$B在天譴軍團的劊子手了結我以前，你能幫助我幫逃出去嗎？', '護送卡瑪洛斯神父至安全之處，並向奧格林之錘上的凱爾坦修士回報。', '護送卡馬羅斯神父至安全處', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13230 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13230, 'zhTW', '替我復仇!', '我聽到他們的聲音，$g兄弟:姐妹;...$B$B聯盟傷兵的哀鳴呻吟...那令我實在不舒服...$B$B完成我們未竟的事業，$c。不要手下留情...不要留下任何一個活口。$B$B為...為了部落...', '垂死的狂戰士要求你在破碎前線上殺死5個垂死的士兵。完成後，向奧格林之錘上的空奪者寇姆‧黑疤回報。', '', '去寒冰皇冠找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '垂死的聯盟士兵已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13231 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13231, 'zhTW', '破碎前線', '什麼?!不…!我們承受了多少的痛苦，只為了維持這回攻擊的低調。部落怎麼可能知道的?裝備…人力…全軍覆沒了嗎?不可能的!$B$B我們在寒冰皇冠的戰略，其關鍵在於比部落先奪下那道門。我們必須盡快重新整備，然後發動另一波攻勢。$B$B查看戰場，搜尋所有的生還者。檢討從這場悲劇中得到什麼教訓。$B$B還有，為了將臨的戰鬥，你得打點妥當，$n，我們必須兩面作戰…', '破天者號上的提督賈斯汀·巴特勒要求你，去破碎前線訊問一個垂死的士兵，並回報給他。', '', '去找寒冰皇冠的提督賈斯汀·巴特勒。', '訊問垂死的士兵', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13232 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13232, 'zhTW', '給我個痛快!', '他們嘲弄我們 - 就算是躺在這裡等死，也還在嘲弄我們...$B$B拜託，$g兄弟:女士;...別讓他們的哀鳴成為我最後聽見的聲音...$B$B給我個痛快吧...讓我從痛苦中解脫...進...入聖光。$B$B找到我的夥伴...給他們同樣的了結。$B$B別留給天譴軍團...任何喚醒我們的機會!$B$B我求你...', '破碎前線上一個垂死的士兵要求你，殺死5個垂死的士兵，並向提督賈斯汀‧巴特勒回報。', '', '去找寒冰皇冠的提督賈斯汀·巴特勒。', '垂死的士兵已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13233 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13233, 'zhTW', '絕不留情!', '如同我告訴過你的。他們不過是在虛張聲勢。$B$B如同往常地，部落再次蔑視我們視為珍愛及神聖的一切事物。他們該以生命償付違逆聖光的罪過。$B$B無一例外。$B$B想想一個不被他們玷污的世界，$n。想像我們孩子所能享受的歡愉。想想我們後代對你回憶的敬仰，當他們知道是你帶給他們安穩的幸福。$B$B現在去吧，讓夢想成真!', '破天者號上的提督賈斯汀‧巴特勒要你在寒冰皇冠殺掉15個部落玩家。', '', '去找寒冰皇冠的提督賈斯汀·巴特勒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13234 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13234, 'zhTW', '叫他們付出代價!', '時機來臨了!$B$B我們已經忍受了自以為是的聯盟太久!我們袖手旁邊這世界的軟弱與絕望也太久了。$B$B現在，我們將終止這份恥辱!現在，我們讓他們嚐嚐什麼叫恐懼!現在，我們將榮耀帶給部落!$B$B在寒冰皇冠這裡，我們要碾碎聯盟!$B$B去吧，$c，追捕他們!碾碎他們。讓他們生不如死!', '空奪者寇姆‧黑疤要你在寒冰皇冠殺掉15個聯盟玩家。', '', '去寒冰皇冠找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13235 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13235, 'zhTW', '血肉巨人鬥士', '你在破壞血肉作坊與清除巫妖王的爪牙這件事上做得很好。現在，所有殘餘的部隊，必須一起對付血肉作坊最龐大的成品 -- 名為莫比達斯的血肉巨人。$B$B這可不會是場輕鬆的遊戲，不過，暗影穹殿派了瑪葛瑞弗‧達卡和一些援軍。和他在血肉作坊西邊的最高點碰頭。一旦你準備好進行攻擊，告訴他，他會讓他的部隊加入戰鬥。', '在血肉作坊的西端，與瑪葛瑞弗‧達卡交談與莫比達斯接戰的事宜。擊敗莫比達斯以後，向黑色守望的黑騎兵阿爾利回報。', '', '去找寒冰皇冠的黑騎兵亞爾利。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13236 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13236, 'zhTW', '詛咒軍團', '你大概覺得自己很厲害 -- 打敗這些不死生物，用你的戰爭機器壓碎他們的骸骨。$B$B但這跟創造他們的力量比起來微不足道。$B$B我曾經看過王子殿下親自表演。我可以示範給你看...如果你想的話。', '第一軍團前線營地的米希阿斯‧薩爾奈要求你，喚起100名食屍爪牙，以讓它們加入軍隊。', '', '去找寒冰皇冠的米希阿斯·薩爾奈。', '已喚起食屍鬼爪牙', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13237 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13237, 'zhTW', '刺探', '當你的指揮官由於他對聯盟敵人的嫌惡因而分散注意力時，你可以投靠我，並協助我堅定地面對真正的敵人 - 巫妖王及他的爪牙。$B$B為了把握任何能在城塞中擊敗他的希望，你的人馬必須把守住每道大門。$B$B現在，專注在你的第一要務上。回到前線，並刺探他們的防禦狀態。尋找任何可讓我們趁隙而入的弱點。$B$B我會等你的回報，$c。', '奧格林之錘上的寇爾提拉‧亡織者要你前往破碎前線並擊敗5隻笨重的憎惡體，5位毒惡的死靈法師，與5位暗影菁英。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '巨大憎惡已擊殺', '邪惡死靈法師已擊殺', '暗影行者已擊殺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13239 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13239, 'zhTW', '烈不烈', '從哪開始呢...嗯哼，你一定知道我是這艘船的首席工程師，我也經手過所有的情報 - 對，對，這是真的，我最近注意到你在南方目擊冰霜巨龍的報告，而我也相信，我已經發展出一套對付他們很有效的方案...現在你得走幾步路，不過基本上，你要打造一個沒穿護甲的假人，在上面用這溶劑塗上一大塊，然後趕快找個掩蔽!$B$B...你還在聽嗎，$r?', '首席工程師銅爪要求你，在破碎前線上使用銅爪的烈性油，以吸引3頭霜育天爪。為了使用烈性油，你必須在戰場上收集一個白骨堆、一頂被遺棄的頭盔、和一副被遺棄的盔甲。', '', '去寒冰皇冠找奧格瑞姆之錘的首席工程師銅爪。', '已進行實地測試', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13240 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13240, 'zhTW', '泰彌亞在你的未來預見了離心傀儡!', '汝應前往漂浮於凜懼島上的奧核之眼，$n。$B$B據余所見，汝應當於該地毀去離心傀儡。余斷言，若汝不能當機立斷地摧毀這些怪力亂神之物，則汝輩必致敗亡。$B$B吾既視之，汝遂應行之。', '達拉然的大法師泰彌亞預見你必須摧毀10個離心傀儡。', '', '去找水晶歌森林的大法師泰彌亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13241 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13241, 'zhTW', '泰彌亞在你的未來預見了依米亞狂戰士!', '依米倫王的戰士就擋在汝與指日可待的勝利之間。$B$B汝將前往凜風峽灣深處，名為俄特加德之巔的要塞。余無法更加強調，汝輩能了結依米亞狂戰士，是如何地重要。$B$B若未能達成，將致汝輩之毀滅。$N!', '達拉然的大法師泰彌亞要求你，殺掉7個依米亞狂戰士。', '', '去找水晶歌森林的大法師泰彌亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13243 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13243, 'zhTW', '泰彌亞在你的未來預見了恆龍密探!', '由於恆龍軍團之危害，時間線岌岌可危。若無汝的干預，時間將四分五裂!$B$B汝必須穿越時空，前往時光之穴內的斯坦索姆的抉擇。$B$B洞察所有可能往事之意圖，令余頭痛欲裂，但余可預見，殺死這些恆龍密探為汝之第一要務。$B$B唯有除去所有恆龍，真實歷史方能存留，現在與未來亦不為之擾動。', '達拉然的大法師泰彌亞預見你必須殺死4頭恆龍密探。', '', '去找水晶歌森林的大法師泰彌亞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13246 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13246, 'zhTW', '死亡證明:凱瑞史卓莎', '你對凱瑞史卓莎的故事熟悉嗎?$B$B她是如何地在殺死薩拉苟莎，瑪里苟斯的配偶中扮演著關鍵角色?接著，又如何被瑪里苟斯冰封在一塊冰塊之中，以與他相伴?$B$B我們注意到了，瑪里苟斯正利用他的魔法破壞她的心智。這已使凱瑞史卓莎幾近瘋狂。$B$B$n，你必須進入凜懼島的奧核之心，在她完全喪失心智之前了結她。$B$B雖然這令我十分難過，但我還是堅持你必須帶回她的心臟，以作為證明。', '達拉然的大法師朗達拉克要求你，帶回凱瑞史卓莎的碎心。這個任務只能在英雄難度中完成。', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13248 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13248, 'zhTW', '死亡證明:依米倫王', '俄特加德之巔的依米倫王是最受巫妖王器重的維酷人。光是這個理由就值得殺死他。$B$B再者，倘若他響起戰角號召所有的依米亞與默約丁的領袖，維酷人可能會是天譴軍團裡最難纏的角色!$B$B看你的了$n，千萬別讓它發生。將他頸上上的墜盒帶回來給我，這樣我就會知道依米倫不再對我們構成威脅。', '達拉然的大法師朗達拉克要求你，帶回一個逝去王后的墜盒。這個任務只能在英雄難度中完成。', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13249 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13249, 'zhTW', '死亡證明:預言者薩隆杰', '德拉克薩隆要塞曾經是德拉克瑞王國的驕傲。如今卻淪為巫妖王的墊腳石，來毀滅祖爾德拉克，以便偷取食人妖眾神之力的力量。$B$B但假使我們能夠擊敗他們的領袖，預言者薩隆杰，或許便能遏止源源不竭的天譴食人妖妖援軍。至少，這能讓祖爾德拉克的銀白十字軍少點負擔。$B$B擊敗預言者後將他的附魔提基像帶回來給我。', '達拉然的大法師朗達拉克要求你，帶回一個預言者的附魔提基像。$B$B這個任務只能在英雄難度下完成。', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13252 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13252, 'zhTW', '死亡證明：塑鐵者斯約尼爾', '我們對於所謂“血肉詛咒”的情況知之甚少，不過岩石大廳裡儲存著與之相關的資訊。$B$B塑鐵者斯約尼爾似乎相當瞭解這種詛咒。我們有充分的證據表明，他身上有著一塊泰坦製造的資訊圓盤，上面的資訊足以解答我們的所有疑問。$B$B幫我把圓盤拿來，$n，這樣我們就能對血肉詛咒進行研究了。', '達拉然的大法師蘭達洛克要你將血肉詛咒圓盤交給他。該任務必須在英雄難度下完成。', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13257 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13257, 'zhTW', '戰爭的使者', '酋長需要你，勇士。奧格瑪進入了全城戒嚴狀態，一場不可避免的衝突迫在眉睫。酋長已經下令關閉所有的商店和服務設施，全面備戰。$B$B我不能透露更多的消息了——至少現在不能。在這樣的場合跟你談論局勢也不合適。$B$B酋長傳下令來，部落最強大的勇士必須立即趕往王座廳向他報到。去吧，$N！穿過傳送門返回奧格瑪，向索爾報到。', '轉至奧格瑪的格羅瑪什堡壘，向索爾報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13259 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13259, 'zhTW', '確立優勢', '我們必須把握唯一的機會，對城堡造成破壞——千萬不能搞砸了。$B$B我們已經弄到了天譴軍團製造的強力薩隆邪鐵炸彈。但是在引爆炸彈之前，必須確保萬無一失。$B$B我們得在天譴軍團的援軍趕來之前，迅速壓制他們的防禦部隊。$B$B幫助我的人消滅天災士兵吧，然後你就可以準備引爆炸彈了。', '冰冠堡壘的克蕾迦中士要你去殺死10只笨重的恐屍。', '', '去寒冰皇冠找冰冠堡壘的克蕾迦中士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13261 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13261, 'zhTW', '烈不烈', '哇呼!成功啦!當然我怎麼可能懷疑自己超乎自然的天才，只是我不太確定應該期待多大的爆炸 - 這麼說吧，我很高興你的眉毛沒有燒焦。我現在只要讓老寇看看你砸那些龍。他只得升我當...當...比首席工程師還高的官兒!你再拿一批那玩意兒然後回去前線，我去叫老寇來...$B$B等什麼?出動啊!', '首席工程師銅爪，要你在破碎前線使用銅爪的烈性油，以吸引3隻霜育天爪。為了使用烈性油，你必須先從戰場上取得被遺棄的頭盔、被遺棄的盔甲與骨堆。', '', '去寒冰皇冠找奧格瑞姆之錘的首席工程師銅爪。', '已進行實地測試', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13264 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13264, 'zhTW', '有夠討厭!', '憎惡體...$B$B可以是很難纏的敵人。我曾經不只一次看過他們逆轉整個戰局。很少人能理解，他們也可以是很可靠的戰友。$B$B他們不太思考。如果你知道他們製造的秘密，你就能夠賦予他們一些基本的指令而他們完全不會質疑你。$B$B算你好運，我知道這些秘密。$B$B這個裝置可以重新活化那些被你擊敗的憎惡體殘骸。拿著它，並學著用他們反擊那些死亡之門的天譴軍團。', '奧格林之錘上的寇爾提拉‧亡織者要你使用憎惡體再活化工具包創造再活化的憎惡體，並用來殺掉15隻冰結食屍鬼、15隻邪惡的魂屍、15個復活的聯盟士兵。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '冰霜食屍鬼已引爆', '凶殘幽魂已引爆', '復生的聯盟士兵已引爆', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13265 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13265, 'zhTW', '布料搜掠', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13266 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13266, 'zhTW', '毫無遺憾的一生', '當我的生命走到盡頭時，我希望自己能夠毫無遺憾地離開這個世界。那些因此悲傷的人會明白，作為部落的酋長，我做出的決定都是有利於我的子民的。$B$B但是瓦里瑪薩斯和普特雷斯的叛變……令我們過去的努力全都付之東流。$B$B<索爾沉重地嘆了口氣。>$B$B正義必須得到伸張。$B$B轉至幽暗城的傳送門馬上就會開啟，沃金正在等你，我稍後也會過去和你們碰面。我們要一起挽回殘局，$N。', '穿過格羅瑪什堡壘內的傳送門，轉至幽暗城，向沃金報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13267 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13267, 'zhTW', '幽暗城之戰', '瓦里瑪薩斯已經控制了整座幽暗城。我們的士兵整裝待發，只等酋長髮出進攻的指令。$B$B只要幫助我們奪回幽暗城，你就可以躋身部落最偉大的勇士之列！如果你能從戰場上活著回來，就去向索爾覆命吧。$B$B準備就緒後和酋長談一談。', '幫助索爾和希爾瓦娜斯為部落奪回幽暗城。$B$B完成任務後向索爾覆命。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13268 AND `locale` = 'zhTW';
