INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13273, 'zhTW', '追尋核心', '有了諾甘農之殼在手，只剩下鑰匙的另一半部需要去找了，幸運地，我已讓探險者協會努力追尋諾甘農之核的下落。$B$B發明者圖書館的東南方遠處、在一個往北丹尼弗蘭的斜坡上有一個背負吾名的營地。許多搜尋第二半部鑰匙的協會成員們正駐紮在那兒。將他們編制的地圖與筆記都帶回來給我，我們應該可以用那些資料來找出另外一半鑰匙的下落。', '在布萊恩營地找出勘察員克羅娜的筆記與勘察員索林的地圖。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13274 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13274, 'zhTW', '核心的守護者', '勘察員索林的筆記指出諾甘農之核目前正被一個名叫艾桑的哨兵看守著，彌米爾的創造物之一。$B$B索林提到艾桑守護的穹殿在這些日子被叫做「洛肯的交易地」。$B$B洛肯，嗯？土靈曾經提過他。$B$B穹殿據說位於被摧毀的探險者協會營地西南方，圓形入口坐落在山邊眺望著遠古寒冬山谷。$B$B找到這個艾桑並從他手上取得核心，當然如果你們打起來的話我不會太意外。', '取得諾甘農之核。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13275 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13275, 'zhTW', '快躲起來', '你真的不該碰它。但現在你碰了，他一定會出來找你。$B$B而且他一定會找到你，除非你躲起來。$B$B如果你還想活命，快幫我把無面者的血帶來。', '米希阿斯‧薩爾奈要你取得3個無面者之血。', '', '去找寒冰皇冠的米希阿斯·薩爾奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13276 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13276, 'zhTW', '有夠討厭!', '你知道怎麼做的，$c。$B$B拿著這個工具包，並使用從憎惡體身上取得的內臟來製作你專屬的憎惡體，然後命令他們去攻擊門口的那些敵軍。$B$B當我們在突襲入口時，你的作為將會大大地強化這項策略。', '奧格林之錘上的寇爾提拉‧亡織者要你使用憎惡體再活化工具包創造再活化的憎惡體，並用來殺掉15隻冰結食屍鬼、15隻邪惡的魂屍、15個復活的聯盟士兵。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '冰霜食屍鬼已引爆', '凶殘幽魂已引爆', '復生的聯盟士兵已引爆', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13277 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13277, 'zhTW', '抵抗巨人族', '當對抗天譴軍隊的地面作戰開始白熱化，我們更不能忽略入口本身。$B$B城牆附近的血肉巨人能夠投擲巨石與大冰塊，對他們的敵軍步兵造成毀滅性的傷害，集結你的兵力並消滅這些巨人族。知己知彼、百戰百勝。$B$B還有，給我帶回點他們的背脊，如果我的記憶還正確，我應該還有點小秘訣可以傳授給你。', '奧格林之錘上的寇爾提拉‧亡織者要你從默德雷薩的膿創恐獸身上取得5份膿汁之脊。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13278, 'zhTW', '汙染者科普洛斯', '有報告指出死亡之門有一隻非常強大的殭屍，$c。$B$B我們必須設法解除它帶來的潛在威脅。如果你能親自與它交手，應該可以瞭解到更多的有價值的情報。$B$B轉至死亡之門西面的大廳，向這隻怪物發起挑戰，找出它的弱點。', '奧格瑞姆之錘的庫爾迪拉·織亡者要你轉至默德雷薩，殺死汙染者科普洛斯。', '', '去寒冰皇冠找奧格瑞姆之錘的庫爾迪拉·織亡者。', '殺死汙染者科普洛斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13279 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13279, 'zhTW', '化學常識', '<庫爾迪拉取過脊骨，把裡面的膿液倒進瓶子裡。>$B$B我們對血肉巨人的特性有一點點了解……$B$B它們的脊骨膿液可以以一種非常有趣的方式與瘟疫病菌溶合，將瘟疫轉換成一種腐蝕劑。$B$B雖然說從高高的城牆上潑下腐蝕劑會讓下面的士兵非常鬱悶，但至少受害者不會變成天譴軍團的爪牙。$B$B把這隻瓶子裡的東西倒進死亡之門西面大廳內的瘟疫之鍋裡去。', '奧格瑞姆之錘的庫爾迪拉·織亡者希望你轉至默德雷薩，將脊骨膿液倒進那裡的瘟疫之鍋。', '', '去寒冰皇冠找奧格瑞姆之錘的庫爾迪拉·織亡者。', '中和瘟疫之鍋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13280 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13280, 'zhTW', '佔山為王', '瞧見依米海姆西北方那座陡峭的山峰了麼，你只要駕駛我的跳躍機器人儘快爬上山頂就行啦，$N！$B$B布拉斯·炸雷是個懦弱的壞蛋，他正在擺弄自己的破爛機器人呢，大概馬上就要完工了吧。我們正在比賽，看誰能搶先佔領那座山頭！$B$B等你跳上去之後，將我們的軍旗插到徽記堆裡。讓大家知道，聯盟才是最棒的！我的工程學技術才是最棒的！', '依米海姆的弗拉索·磨輪要你使用弗拉索的跳躍機器人，將聯盟軍旗插到山頂的徽記堆上。', '', '去寒冰皇冠找依米海姆的弗拉索·磨輪。', '插下聯盟軍旗', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13281 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13281, 'zhTW', '中和瘟疫', '沒有我的幫助，你也可以中和敵人的瘟疫之鍋了，$r。$B$B去消滅死亡之門一帶的血肉巨人，用它們脊骨中的膿液中和瘟疫。$B$B你所打擊的是敵軍最重要的核心部分。這是一個重要的任務——對我們的事業而言生死攸關的任務。只要時間允許，就應該盡力去完成。$B$B記住，你可以在默德雷薩找到血肉巨人和瘟疫之鍋。', '奧格瑞姆之錘的庫爾迪拉·織亡者希望你轉至默德雷薩，將脊骨膿液倒進那裡的瘟疫之鍋。$B$B你可以使用從起膿的血肉巨人身上收集而來的脊骨製造膿液。', '', '去寒冰皇冠找奧格瑞姆之錘的庫爾迪拉·織亡者。', '中和瘟疫之鍋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13282, 'zhTW', '返回地面', '現在你該走了。我身後有一道傳送門，它可以把你送到地面上去。$B$B我們還會見面的。他會來找你。$B$B他遲早會找到你。', '返回奧格瑞姆之錘，向庫爾迪拉·織亡者覆命。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13283, 'zhTW', '佔山為王', '嘿，你好啊，$N。跟昨天一樣，我要你駕駛跳躍機器人儘快爬上依米海姆東南方那座山峰的頂部！$B$B弗拉索·磨輪這個自以為是的傢伙，她老是說她的跳躍機器人比我的好！呸！我們正在比賽，看誰能搶先佔領那座山頭！$B$B等你跳上去之後，將我們的軍旗插到徽記堆裡。讓大家知道，部落才是最棒的！我的工程學技術才是最棒的！', '依米海姆的布拉斯·炸雷要你使用布拉斯的跳躍機器人，將部落軍旗插到山頂的徽記堆上。', '', '去寒冰皇冠找依米海姆的布拉斯·炸雷。', '插下部落軍旗', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13284 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13284, 'zhTW', '地面突襲', '你好，$c。$B$B最近我們一直在對依米海姆發動猛攻，但是這些維庫人比我們之前遇到過的要兇殘得多。每次部隊試圖向依米海姆推進時都會遭到伏擊，我們的人員損失非常慘重。$B$B如果你願意參戰，幫助我的小分隊安全抵達依米海姆的大門，我們會好好獎勵你的。抵達大門之後，我們就會挖掘壕溝，等待後援部隊。', '護送破天者號部隊抵達依米海姆的門口。完成任務後返回依米海姆東面的冰川邊緣，向地面指揮官庫普覆命。', '', '去寒冰皇冠找失落希望之谷的地面指揮官庫普。', '護送聯盟部隊前往依米海姆', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13285, 'zhTW', '打造鑰匙', '啊哈!就是它:發明神殿，守護者彌米爾自己的寶座!當然，那兒就是結合兩個半部鑰匙的地點。$B$B根據勘查員們的筆記，發明神殿位於造物者殿堂西側的最高點之一。這意味著它大致位於葛羅姆亞什失事地東邊。$B$B我會在神殿與你會合然後我們再將兩個部份合而唯一。', '布萊恩‧銅鬚要你在發明神殿與他會合並且結合諾甘農之殼與諾甘農之核。一旦你協助布萊恩‧銅鬚之後便回報給葛羅姆亞什失事地的博克塔‧血怒。', '', '去找風暴峭壁的博克塔‧血怒。', '幫助布蘭恩製作鑰石', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13286, 'zhTW', '……所有可能的幫助', '時局令人絕望，$c……$B$B我感到異常焦慮，打算接受一切可能的幫助——包括這裡的死亡騎士駐軍。$B$B和薩沙理安談一談吧。看看他能否幫助我們改良對抗天譴軍團的戰術，確保我們一旦組織起足夠的人手，就能夠一擊而勝。$B$B我們已經走到了這一步……絕對不能功敗垂成！', '破天者號的高階指揮官加斯汀·巴雷特要你與薩沙理安談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13287, 'zhTW', '知己知彼', '像你這樣擁有豐富作戰經驗的英雄必定了解這一點：沒有什麼途徑比親自與敵人交手更能摸清對方底細了。$B$B雖然你渴望獲得攻佔冰冠堡壘的榮耀，但是我們必須首先突破巫妖王的每一扇大門。所謂知己知彼，百戰百勝……$B$B我要你返回破碎前線，與敵人交戰。尋找他們的弱點，然後向我彙報詳細的情況。', '破天者號上的薩沙理安要你轉至破碎前線，殺死5名笨重的憎惡、5名邪惡通靈師和5名暗影專家。', '', '去寒冰皇冠找破天者號的薩沙理安。', '殺死笨重的憎惡', '殺死邪惡通靈師', '殺死暗影專家', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13288, 'zhTW', '你的憎惡夥伴', '憎惡……$B$B可怕的敵人。我不止一次目睹它們迅速地扭轉了戰局。事實上，它們也可以成為有用的夥伴，這一點倒是鮮為人知。$B$B憎惡並不聰明。只要你瞭解製造憎惡的秘密，就可以對它們發出簡單的指令。相信我，它們會毫不猶豫地執行你的命令。$B$B你很幸運，我恰好知曉其中的奧秘。$B$B對憎惡的殘骸使用這個工具包，將其復活。接下來你就可以利用它對付駐守在死亡之門的天譴軍團了。', '破天者號上的薩沙理安要你使用憎惡復活工具包製造一名復活的憎惡，然後利用它殺死15只冰寒食屍鬼、15只殘忍的惡鬼和15名復活的聯盟士兵。', '', '去寒冰皇冠找破天者號的薩沙理安。', '引爆冰寒食屍鬼', '引爆殘忍的惡鬼', '引爆復活的聯盟士兵', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13289 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13289, 'zhTW', '你的憎惡夥伴', '你知道該怎麼做吧，$c。$B$B對憎惡的殘骸使用這個工具包，製造一隻聽命於你的憎惡，然後命令它去攻擊駐守在死亡之門的敵人。$B$B在我們對死亡之門再次發動攻擊之前，你可以好好地熟悉一下這種戰術。', '破天者號上的薩沙理安要你使用憎惡復活工具包製造一名復活的憎惡，然後利用它殺死15只冰寒食屍鬼、15只殘忍的惡鬼和15名復活的聯盟士兵。', '', '去寒冰皇冠找破天者號的薩沙理安。', '引爆冰寒食屍鬼', '引爆殘忍的惡鬼', '引爆復活的聯盟士兵', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13290 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13290, 'zhTW', '請留意一下……', '在斬雷號任職期間，首席技師波爾維克憑藉卓越的表現贏得了大家的喝彩。如今，他也是破天者號不可或缺的關鍵人物。若不是他，我們的戰艦早就被轟成碎片，散落在這片冰原上了。$B$B不過這傢伙有個毛病，他喜歡與大家分享所有細微的發明或是發現——而其中大部分都超出了我的理解範圍。$B$B我必須集中注意力對抗敵軍，不能為這種事分心。$B$B請代我去跟他談一談，$n。如果可以的話，最好幫幫他。他就在船艙裡。', '高階指揮官加斯汀·巴雷特要你與破天者號的首席技師波爾維克談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13291 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13291, 'zhTW', '“借來”的技術', '好吧，我明白了。指揮官沒時間關注我的小發現。這是他的損失！$B$B瞧，我設法從敵人那裡“得到”了一批液體。儘管我討厭改造下等的地精科技製品，不過這次就算破例啦。$B$B喏，拿著這份樣本。我要你實地測試它的功效，便於讓我透過逆向工程來重現它的製作流程。$B$B轉至破碎前線，收集製造假人的材料，然後使用液體。', '破天者號上的首席技師波爾維克要你在破碎前線使用偷來的液體。$B$B你需要收集被丟棄的頭盔、被丟棄的護甲和一堆白骨才能召喚假人，這些材料都可以在破碎前線找到。', '', '去寒冰皇冠找破天者號的首席技師波爾維克。', '完成實驗', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13292 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13292, 'zhTW', '偷來的解決方案', '嗯，嗯，再來一次怎麼樣？訓練總是不嫌多的。$B$B我們已經找到了對付冰霜巨龍的法子。$B$B$r，繼續削減它們的數量吧。你幹掉的冰霜巨龍越多，我們在進攻冰冠堡壘時遇到的阻擾就越少。$B$B祝你好運。記得將沒用完的液體帶回來給我。', '破天者號上的首席技師波爾維克要你在破碎前線使用偷來的液體。$B$B你需要收集被丟棄的頭盔、被丟棄的護甲和一堆白骨才能召喚假人，這些材料都可以在破碎前線找到。', '', '去寒冰皇冠找破天者號的首席技師波爾維克。', '殺死霜巢天爪龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13293 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13293, 'zhTW', '轉至依米海姆！', '依米海姆坐落在寒冰皇冠的中心地帶，我要你潛入這座冰霜維庫人的大型城市。$B$B布拉斯·炸雷已經抵達城市西側，代表戰歌遠征軍與聯盟展開了競賽。他要使用跳躍機器人與對方進行搶佔山頭的比賽！$B$B別讓我們失望，$N。地精工程學的尊嚴就靠你來維護了！此外，這裡的士兵都指望著你呢。$B$B我們都下了注，賭你一定能勝過那些蠢貨！', '與依米海姆的布拉斯·炸雷談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13294 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13294, 'zhTW', '抵抗巨人族', '當對抗天譴軍隊的地面作戰開始白熱化，我們更不能忽略入口本身。$B$B城牆附近的血肉巨人能夠投擲巨石與大冰塊，對他們的敵軍步兵造成毀滅性的傷害，集結你的兵力並消滅這些巨人族。知己知彼、百戰百勝。$B$B還有，給我帶回點他們的背脊，如果我的記憶還正確，我應該還有點小秘訣可以傳授給你。', '破天者號上的薩沙理安要你從默德雷薩的膿創恐獸身上取得5份膿汁之脊。', '', '去寒冰皇冠找破天者號的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13295, 'zhTW', '基礎化學', '<薩沙理安拿起膿汁之脊並將膿汁抽入一個瓶子裡。>$B$B血肉巨人鮮為人知的一種特性…$B$B就是他們的髓液與瘟疫的互動非常奇妙，竟然會轉變為一種腐蝕性的強酸。$B$B從高牆上倒下的酸液可能不會太好看，但至少受害者不會復生成敵軍的戰力。$B$B把這些瓶內液體倒入死亡之門西側的其中一個瘟疫大鍋內。', '破天者號上的薩沙理安要你在默德雷薩的瘟疫大鍋使用膿汁脊髓液。', '', '去寒冰皇冠找破天者號的薩沙理安。', '中和瘟疫之鍋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13296 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13296, 'zhTW', '前進依米海姆!', '我需要你盡快前往依米海姆，那個寒冰皇冠中央的大冰雪維酷的村子。$B$B芙芮索·齒研就在下面那兒的南側代表驍勇遠征軍與部落惡徒們競爭著。以她的彈跳機器人對抗部落的彈跳機爭奪山脈之王的頭銜!$B$B可別讓我們失望了$n。你背負著不只是地精工程學的榮耀!還有我們這群地精全部的希望。$B$B最最重點的是，我們的注全押在你身上，賭你可以狠狠教訓那群白痴!', '與依米海姆的芙芮索·齒研交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13297 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13297, 'zhTW', '中和瘟疫', '你不再需要我的協助來中和敵人的瘟疫大鍋了，$r。$B$B獵殺死亡之門的那些血肉巨人並用他們的脊髓液消滅那些瘟疫病體。$B$B同時你是在打擊敵軍的戰略重心。這是個重要的任務－對我們極為必要，並且應該即刻執行。$B$B切記，巨人與大鍋都位於默德雷薩。', '破天者號上的薩沙理安要你在默德雷薩的瘟疫大鍋上使用膿汁脊髓液。你可以使用從膿創恐獸身上取得的巨人之脊來蒐集膿汁脊髓液。', '', '去寒冰皇冠找破天者號的薩沙理安。', '中和瘟疫之鍋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13298 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13298, 'zhTW', '污敗的寇普羅斯', '據報死亡之門附近出現了強力殭屍，$c。$B$B我們不能放任這樣潛在的威脅不理。任何你能透過戰鬥獲取有關這些東西的資訊都比我們目前的一無所知要好的多。$B$B前往門的西廂找到這個生物。戰鬥，並找出任何我們可加以利用的弱點。', '破天者號上的薩沙理安要你在默德雷薩殺掉污敗的寇普羅斯。', '', '去寒冰皇冠找破天者號的薩沙理安。', '殺死汙染者科普洛斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13299 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13299, 'zhTW', 'ZZOLD幽光披風', '', '', '', '去晶歌森林找衰弱之河的查理·沃爾斯。', 'Complete Achievement: Northrend Loremaster', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13300 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13300, 'zhTW', '搶救薩鋼礦奴', '我的人民都被綁到依米海姆的薩鋼礦坑當作礦奴，維酷要塞就在寒冰皇冠的中央。巫妖王逼他們日以繼夜的開挖那些邪惡的礦石。$B$B我答應大領主弗丁會把那些可憐鬼活著救出來，這正是我們目前的要務。$B$B不幸地，我被命令待在攻擊艦上擔任英勇遠征軍的大使，你能幫我把他們救出來嗎，$n?', '破天者號上的虔誠的亞柏薩倫請你去援救10名薩鋼礦坑奴隸。', '', '去找寒冰皇冠破天者號上的虔誠的亞柏薩倫。', '營救薩隆邪鐵礦洞奴隸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13301 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13301, 'zhTW', '地面突襲', '你好，$c。$B$B最近我們一直在對依米海姆發動猛攻，但是這些維庫人比我們之前遇到過的要兇殘得多。每次部隊試圖向依米海姆推進時都會遭到伏擊，我們的人員損失非常慘重。$B$B如果你願意參戰，幫助我的小分隊安全抵達依米海姆的大門，我們會好好獎勵你的。抵達大門之後，我們就會挖掘壕溝，等待後援部隊。', '護送庫卡隆部隊抵達依米海姆的大門。完成任務後返回依米海姆北面的冰川邊緣，向地面指揮官科特亞覆命。', '', '去寒冰皇冠找轟炸場的地面指揮官庫普。', '護送部落部隊前往依米海姆', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13302 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13302, 'zhTW', '薩隆邪鐵的奴隸', '維庫人將他們的俘虜送去位於寒冰皇冠中心的依米海姆，迫使他們進入那座城市的薩隆邪鐵礦洞做苦工。巫妖王命令他們日夜不停地挖掘這種邪惡的礦石。$B$B我答應過弗丁大人，一定要將他們活著救出來。這就是我們眼下的任務。$B$B但是作為戰歌遠征軍的使者，我不得不奉命待在這艘飛艇上。你能替我去救他們嗎，$N？', '奧格瑞姆之錘的凱爾坦修士要你去營救10名薩隆邪鐵礦洞奴隸。', '', '去寒冰皇冠找奧格瑞姆之錘的凱爾坦修士。', '營救薩隆邪鐵礦洞奴隸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13303 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13303, 'zhTW', '測試任務', '', '', '', '去找Jonathan LeCraft。', 'Complete Achievement: Northrend Loremaster', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13304 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13304, 'zhTW', '戰地維修', '天譴軍團還沒有從我們的這次攻勢中緩過氣來，$N。你順利地完成了引爆任務，極大地鼓舞了大家計程車氣，我們要一鼓作氣，繼續戰鬥。$B$B位於我們下方的開闊山谷是一處戰略要地。我們在失落希望之谷的東南角發現了一輛癱瘓的攻城車，似乎還可以使用。$B$B如果你能從食腐的惡鬼手裡搶回丟失的零件，或許能讓它重新運轉起來。一輛攻城車就足以對敵人的地面單位造成重創了。', '奧格瑞姆之錘的庫爾迪拉·織亡者從食腐的惡鬼身上收集5塊攻城車零件，然後將它們帶去失落希望之谷的損毀的攻城車旁。', '', '去寒冰皇冠的失落希望之谷找損毀的攻城車。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13305 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13305, 'zhTW', '竭盡全力', '你要用這臺機器去對付天譴軍團？你這樣是無法勝過他們的。$B$B你或許可以消滅幾百個敵人……甚至幾千個，但你無法取得勝利。這樣不行。$B$B等你擺弄夠了這臺機器，可以到北邊來找我。那裡有一座舊軍營。我會讓你認識到，你要面對的是怎樣的敵人。', '使用整修過的攻城車，在失落希望之谷裡消滅150只腐朽的食屍鬼、20個霜顱大法師和2個白骨巨人。完成任務之後轉至第一軍團前線營地，與米斯希爾薩·阿奈爾談一談。', '', '去寒冰皇冠找失落希望之谷的米斯希爾薩·阿奈爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13306, 'zhTW', '構建路障', '一旦我們的部隊開始動身穿越奧爾杜薩，他們就很容易遭到來自鐵牆壁壘和廣袤的冰川平原地區的攻擊。$B$B我們沒有時間和資源去建造防禦工事，但可以搭建一些臨時性的路障，抵禦天譴軍團的遠端火力和突擊，以保護我們的士兵。$B$B帶著這隻工具箱到奧爾杜薩西面的隕落英雄之谷去。按照我在那裡做好的記號，用這隻工具箱製造一些路障。', '奧格瑞姆之錘的庫爾迪拉·織亡者要你使用路障搭設工具建造8處路障。', '', '去寒冰皇冠找奧格瑞姆之錘的庫爾迪拉·織亡者。', '建造路障', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13307 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13307, 'zhTW', '濺血的旗幟', '天譴軍團正在奧爾杜薩西面的隕落英雄之谷和寒冰皇冠裡搜尋死者，想要用他們來對付我們。天譴軍團的軍官已經復活了山谷中的一些死者，並賦予了他們可怕的力量和狂熱的忠誠。天譴軍團首領所攜帶的旗幟是這種力量的源泉，去殺死那些旗手，以此減少他們所控制的被轉化英雄的數量。$B$B你必須幫我們除去這個障礙，並且在大部隊開拔之前幫助我們削弱天譴軍團的抵抗力度。', '奧格瑞姆之錘的庫爾迪拉·織亡者要你去殺死5個天災旗手、5個天災轉化者和20個被轉化的英雄。', '', '去寒冰皇冠找奧格瑞姆之錘的庫爾迪拉·織亡者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13308 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13308, 'zhTW', '思維詭計', '<你的腦海中響起了這個怪物的聲音，它似乎在痛苦中掙扎，顯得格外詭異。>$B$B$R，我需要你的幫助。和你那些被俘虜的朋友一樣，我也被巫妖王手下的巨人給抓起來的。我從地下世界一路往上，想要調查從這座洞穴中傳來的噪音，結果就被他們抓住並囚禁了起來。$B$B你願意幫我嗎？鐐銬的鑰匙就在礦洞中的工頭身上。殺死他！$B$B<你感到一股壓力衝擊著你的思維，似乎這個怪物正在迫使你執行它的命令。>', '薩隆邪鐵礦洞的黑暗低語者阿克希姆要你去找到工頭的鑰匙，幫它開啟鐐銬。', '', '去寒冰皇冠找薩隆邪鐵礦洞的黑暗低語者阿克希姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13309 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13309, 'zhTW', '空中突襲', '我們許多弟兄已經整裝待前往依米海姆進行空降。我需要你幫助他們安全抵達。$B$B維酷在他們的圍牆內架設了許多自動矛槍，已經多次阻礙我們的空投。我們的工程師已經裝設了一台鎮壓砲塔來摧毀那些矛槍－往矛槍附近開火，產生的煙霧應該能顧阻礙它們發射。$B$B坐上砲塔然後掩護我們的弟兄安全抵達他們的降落區。', '依米海姆東面冰冠邊緣的地面指揮官庫普命令你操作破天者號鎮壓砲塔來保護破天者號軍隊運輸機直到部隊完成空降。', '', '去寒冰皇冠找失落希望之谷的地面指揮官庫普。', '破天者號潛入者安全著陸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13310 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13310, 'zhTW', '空中突襲', '正好有事情可以交給你這個廢物去做，省得你整天遊手好閒的。$B$B我們正準備將一隊訓練有素的士兵空投到依米海姆去。但是維庫人在圍牆內設定了自動魚叉炮，用於摧毀我們的運兵機。於是，我們請奧格瑞姆之錘的工程師建造了一座壓制炮臺。$B$B你要充當炮手，對維庫人的魚叉炮進行掃射，遮擋它們的視線，並摧毀它們的傳動裝置。你必須在確保運兵機完整的情況下讓所有士兵都安全降落。', '依米海姆北面冰川邊緣的地面指揮官科特亞命令你使用庫卡隆壓制炮臺，保證庫卡隆運兵機安全降落並卸下所有部隊。', '', '去寒冰皇冠找轟炸場的地面指揮官庫普。', '庫卡隆潛入者安全著陸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13311 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13311, 'zhTW', '群魔套卡', '你現在收集齊了整套的群魔套卡，另一張卡片出現在套卡的上面。上頭描繪著一個占卜師，似乎無論你用什麼角度拿著套卡，他都一直盯著你看。$B$B你覺得這張卡片似乎可以用來跟什麼人溝通。', '使用群魔套卡召喚一位暗月占卜師，然後把套卡交給他。', '', '去找暗月算命師。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13312 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13312, 'zhTW', '鐵牆壁壘', '鐵牆壁壘眺望著逝往英雄山谷，在奧多薩的西側、稱霸著四面八方的週遭。只要壁壘還未攻下我們根本無法越雷池一步。駐防者是邪惡的葛林克爾與他詛咒神教的爪牙們。$B$B只要你能削弱葛林克爾的力量，至少我們的軍隊就多少能在進軍時與之抗衡。拿著這個歪曲符文，在壁壘盡頭葛林克爾的寶珠旁釋放符文之力，應該多少能夠引起這個召喚師的注意。', '擊敗邪惡的葛林克爾然後回報奧格林之錘上的寇爾提拉‧亡織者。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13313 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13313, 'zhTW', '阻礙空中偵察', '聯盟不知道怎麼地在逝往英雄山谷與寒冰皇冠上空弄來了一隊偵察機，就在奧多薩的西側的開闊區域。$B$B我們不允許就這樣被佔了上風，首席工程師銅爪已經供應了我們絕佳的武器來對付這項威脅 - 他把他的新飛彈命名為SGM-3。他向我保證絕對彈無虛發，快去利用這新武器讓我們扳回一城!', '使用SGM-3飛彈擊落6艘破天者號偵察戰鬥機，然後向奧格林之錘上的空奪者寇姆‧黑疤回報。', '', '去寒冰皇冠找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '破天者號偵察戰機已擊落', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13314 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13314, 'zhTW', '獲取情報', '部落最近表現得很活躍，我討厭這樣。自從破碎前線的那次行動以後，他們已經開始變得越來越猖狂了。聯盟必須阻止他們。$B$B他們在寒冰皇冠的上空、奧爾杜薩和鐵牆壁壘的西面有頻繁的活動，斥候和傳令兵騎著龍鷹進進出出，不斷傳遞情報和命令。帶上這把鏢槍，用它去幹掉那些奧格瑞姆之錘斥候。如果你也騎著飛行坐騎的話，這個任務應該更容易完成。', '從奧格瑞姆之錘斥候身上截獲6份奧格瑞姆之錘急件，把它們交給破天者號上的高階指揮官加斯汀·巴雷特。', '', '去寒冰皇冠找破天者號的高階指揮官加斯汀·巴雷特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13315 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13315, 'zhTW', '暗中偵察', '一切都在計畫之中。我們策劃了一連串完美的計畫來奪下死亡之門。傷亡雖是必然， 但最終的勝利將屬於我們－咬緊牙關對付那些愛管閒事的部落...$B$B不論如何，我們的下一個需要關切的目標是荒寂之門。飛往那兒並試著熟悉敵人的據點。$B$B當你回來我會再給你進一步指示。', '破天者號上的薩沙理安要你飛往荒寂之門，偵察門的南、中、北、西北區域。', '', '去寒冰皇冠找破天者號的薩沙理安。', '前往奧多薩南部', '前往奧多薩中部', '前往奧多薩北部', '前往奧多薩西北部', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13316 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13316, 'zhTW', '寇普雷薩的守衛者', '寇普雷薩，又稱驚怖之門。將是阻止我們進攻冰冠城塞最後一道防線。就在鐵牆壁壘的南方，焚焰地與冰川的後方。但當我們的軍隊行軍至此必定早已筋疲力竭。$B$B我們必須事先削弱它的防禦，否則軍隊很有可能就在此瓦解。$B$B這個要塞駐守著巫妖王最可怕與最狂熱的手下。盡你的全力毀掉這些守衛，那麼或許我們還有一線希望。', '奧格林之錘上的寇爾提拉‧亡織者要你殺掉5個恐慌先驅者與 5個寇普雷薩守護者。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13317 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13317, 'zhTW', '----', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13318 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13318, 'zhTW', '舉手之勞', '詛咒神教掌控著荒寂之門，是嗎? 這並不意外。$B$B找點樂子的時候到了。你提到在門的南端有些新教徒加入。他們幾乎都會攜帶著一個特別的道具 - 一種幻術寶珠。$B$B這東西通常被教徒用來偽裝，讓他們潛入、滲透或混進他們的敵人。$B$B殺了這群傻瓜直到你取得寶珠， $c，然後用在征服者身上。', '破天者號上的薩沙理安要你從奧多薩的惡劣新兵身上取得幻術寶珠，然後在3個黑暗征服者身上使用它。', '', '去找寒冰皇冠的薩沙理安。', '已拖拽並丟棄黑暗征服者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13319 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13319, 'zhTW', '切斷指揮鍊', '根據你的報告以及我對神教的印象，他們在每個駐紮點都派駐了一名監督者來調度各個行動。$B$B我相信也許解決掉這些指揮者的效果非常有限，但至少能拖延他們的行動並讓他們調度失衡，這對我們目前的處境已經非常值回票價。$B$B解決掉那些監督者以後再回來找我。', '破天者號上的薩沙理安要你前往奧多薩擊敗監督者菲德里斯、監督者薩夫林、監督者維拉傑與監督者杰昆。', '', '去找寒冰皇冠的薩沙理安。', '監工菲德里斯已擊殺', '監工賈昆已擊殺', '監工維拉吉已擊殺', '監工薩弗林已擊殺', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13320 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13320, 'zhTW', '無法複製', '我在這裡都聞到了他們的大鍋散發出的氣味，不過鍋裡煮的並不是瘟疫病菌。$B$B所有宣誓為詛咒教派效力的人都必須飲下一種可以奪走他們的意願、使他們永遠效忠巫妖王的藥劑。$B$B有人說，這種藥劑中封存著那些受到殘酷折磨、並被無情屠殺的生物的扭曲之魂，不過我從來就沒能成功地複製過這種藥水……$B$B從荒涼之門西北區域的三處大鍋裡各採集一些樣本，裝進這隻瓶子裡，然後把它交給首席技師波爾維克。', '破天者號上的薩沙理安希望你轉至荒涼之門奧爾杜薩，在那裡的3處詛咒教徒的大鍋中使用分離的藥瓶，然後將其交給首席技師波爾維克。', '', '去寒冰皇冠找破天者號的首席技師波爾維克。', '收集藍色樣本', '收集綠色樣本', '收集黑色樣本', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13321 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13321, 'zhTW', '重新測試', '這樣應該就行了！$B$B那些邪惡的教徒還想把更多靈魂放進他們的噁心果汁？ 我說我們就幫他們一把！$B$B來把這乾了 - 別擔心，我已經稀釋過了…我幾乎敢保證這唯一的效果是當你殺掉一個教徒以後，這能幫你找出他的靈魂精華。$B$B等你蒐集到一定的量，就把那坨扭曲惡靈的苦痛糾結凝塊扔進任何一個鍋子$B$B讓他們嚐嚐自食惡果的滋味！', '破天者號上的首席工程師栓鉗要你將苦痛糾結凝塊丟進奧多薩的一個大鍋中。', '', '去找寒冰皇冠的首席工程師栓鉗。', '蠕動之團已放逐', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13322 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13322, 'zhTW', '重新考驗', '那些扭曲的詛咒教徒想要把別人的靈魂放進他們的飲料裡？那麼讓我們來幫他們一把吧！$B$B把這東西喝下去——不用擔心，我已經對它進行了稀釋……現在它唯一的作用只是讓在你幹掉詛咒教徒時可以發現他們的精華。$B$B等你收集到一些精華之後，把那些充滿扭曲靈魂怨念的沸騰魔質扔進他們的瘟疫之鍋裡。$B$B看看他們嚐到自己的藥劑之後會怎樣！', '破天者號上的首席技師波爾維克希望你喝下稀釋過的詛咒教徒滋補劑，殺死奧爾杜薩一帶的任意詛咒教徒，從他們身上收集被汙染的精華。然後將10份被汙染的精華組合成沸騰的魔質，把它扔進奧爾杜薩的瘟疫之鍋裡。', '', '去寒冰皇冠找破天者號的首席技師波爾維克。', '投放沸騰的魔質', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13323 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13323, 'zhTW', '從天而“降”', '看來那些新教徒的數量又增加了。你知道該怎麼做吧……$B$B新來的教徒在荒涼之門的南端接受訓練。他們之中的絕大部分人應該都持有一件特殊的物品——幻象寶珠。$B$B這種寶珠可以用來偽裝詛咒教徒，使他們能夠安全地自由行動，滲透或是完全偽裝成敵人的模樣。$B$B去幹掉那些蠢貨，從他們身上收集幻象寶珠，然後對黑暗壓制者使用它。', '破天者號上的薩沙理安希望你從奧爾杜薩的苦痛新兵身上奪取幻象寶珠，然後對那裡的3名黑暗壓制者使用。', '', '去寒冰皇冠找破天者號的薩沙理安。', '扔下黑暗壓制者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13324 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13324, 'zhTW', '暗月稜鏡套牌', '你現在已經收集到了稜鏡套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。', '當暗月馬戲團來到鎮上的時候，把稜鏡套牌交給他們。', '', '去找薩杜斯·帕雷教授。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13325 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13325, 'zhTW', '暗月混亂套牌', '你現在已經收集到了混亂套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。', '當暗月馬戲團來到鎮上的時候，把混亂套牌交給他們。', '', '去找薩杜斯·帕雷教授。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13326 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13326, 'zhTW', '暗月高尚套牌', '你現在已經收集到了高尚套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。', '當暗月馬戲團來到鎮上的時候，把高尚套牌交給他們。', '', '去找薩杜斯·帕雷教授。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13327 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13327, 'zhTW', '暗月死靈套牌', '你現在已經收集到了死靈套牌的所有卡片，與前8張的背面圖案完全一樣的第9張卡片神秘地出現在你手中。在這張卡片上寫著，“將這些卡片拿到暗月馬戲團去，你就將獲得獎勵。”你聽說暗月馬戲團每過幾個月就會路過一次莫高雷和閃金鎮，因此你也許需要等待一段時間才能看到他們。', '當暗月馬戲團來到鎮上的時候，把死靈套牌交給他們。', '', '去找薩杜斯·帕雷教授。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13328 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13328, 'zhTW', '擊破碎片', '在寇普雷薩之頂，巫妖王的爪牙豎立了3座水晶，驚怖、絕望與苦難裂片。他打算等我們的人馬一接近寇普雷薩的城牆，就要將水晶的力量釋放來毀滅我們。$B$B若這些能量完全釋放，水晶將會癱瘓每個人的心靈並注入極大的痛苦與恐懼。到時候天譴軍團便能如入無人之境般地進行屠殺。$B$B找出這些水晶然後摧毀它們，將殘餘的裂片帶回來給我，我們絕對不能讓巫妖王重塑這些武器!', '將破損的驚怖裂片、破損的絕望裂片、破損的苦難裂片，帶回來給奧格林之錘上的寇爾提拉‧亡織者。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13329 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13329, 'zhTW', '驚怖之門', '焚焰地，是前往寇普雷薩必經之路，坐落在鐵牆壁壘之南，巫妖王的精銳組織了堅固的防線來鎮守堡壘。$B$B由一群死亡騎士領頭的骷髏劫奪者軍團擋住了去路。我擔心縱使擊敗了劫奪者，天譴軍團恐怕會輕易地讓他們復生，再次進攻。$B$B我想了個法子來阻止這情況，但我不能保證會奏效。拿著這些溶劑淋在劫奪者的遺骸上把它們融掉。', '奧格林之錘上的寇爾提拉‧亡織者希望你用烈性酸液來溶解6個骷髏劫奪者的屍體。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '骷髏掠奪者的骨頭已溶解', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13330 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13330, 'zhTW', '受選者的血', '那些維酷族相當受到巫妖王的重用，自稱依米亞，他們在寒冰皇冠中央地帶建立了一個屬於他們的城市。在我們進攻冰冠城塞之前尚需許多準備，而我們目前正面對的其中一項，就是進攻這些自稱「受選」於巫妖王的維酷。$B$B前往他們的城市依米海姆，在他們的地盤上擊敗他們。讓他們明白誰才是這兒無庸置疑的強者。', '奧格林之錘上的戰爭使者戴沃斯‧里歐特要求你，到依米海姆殺掉20個維酷族。', '', '去寒冰皇冠找奧格瑞姆之錘的戰爭使者戴沃斯‧里歐特。', '尤彌爾海姆的維库人已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13331 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13331, 'zhTW', '別讓聯盟重見天日', '這些聯盟還真是有夠難纏，我承認，但這改變不了什麼。帶著這些SGM-3然後再次擊落任何你看到的破天者號偵察戰鬥機。$B$B雖然我懷疑那些蠢蛋什麼時候才能理解，總之我們的飛彈還很多，就打到他們清醒為止。去逝往英雄山谷上空擊落那些戰鬥機，就在奧多薩的西側。沒將它們全部都打成殘骸不要回來見我。', '使用SGM-3飛彈擊落6艘破天者號偵察戰鬥機，然後向奧格林之錘上的空奪者寇姆‧黑疤回報。', '', '去寒冰皇冠找奧格瑞姆之錘的空奪者寇姆‧黑疤。', '破天者號偵察戰機已擊落', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13332 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13332, 'zhTW', '架起路障', '當我們的兵力進推超過奧多薩後，他們將較容易遭到從鐵牆壁壘與來自開闊冰川下的敵軍攻擊。$B$B我們既沒有時間也沒有多餘的物資來建造防禦工事，但我們可以放置一些路障來協助我們的弟兄遮蔽火焰與分散天譴軍的攻勢$B$B拿著這個路障裝置前往逝往英雄山谷，在奧多薩的西側。尋找我設置的標記並用這個裝置在那建構你的路障。', '破天者號上的薩沙理安要你使用柵欄構築工具包建造八座路障。', '', '去找寒冰皇冠的薩沙理安。', '已建造路障', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13333 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13333, 'zhTW', '搶奪急件', '不僅我們在努力，部落也在不斷向鐵牆壁壘和奧爾杜薩西面的寒冰皇冠派出斥候。$B$B不能讓部落透過這種方法領先我們。再帶上這把鏢槍，不要對那些奧格瑞姆之錘斥候手軟！把你截獲的急件都給我帶回來。$B$B部落的損失就是我們的成果。', '從奧格瑞姆之錘斥候身上截獲6份奧格瑞姆之錘急件，把它們交給破天者號上的高階指揮官加斯汀·巴雷特。', '', '去寒冰皇冠找破天者號的高階指揮官加斯汀·巴雷特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13334 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13334, 'zhTW', '染血的旌旗', '在寒冰皇冠的逝往英雄山谷區域，往奧多薩的西側，天譴軍尋求了已逝的亡靈來對抗我們。天譴將領們喚醒了山谷的亡者並將其注入了可怕的力量與憤恨。冰冠區域裡由天譴將領們攜帶的旌旗就是這股力量的來源。殺掉執旗者，你便能衰弱他們率領的那些邪化戰士們。$B$B只有你，能幫我們解決這個困境，並在我們的主力能夠進軍前測試抵抗勢力。', '破天者號上的薩沙理安要你殺掉5個天譴執旗者、5個天譴轉化者、20個轉化的英雄。', '', '去找寒冰皇冠的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13335 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13335, 'zhTW', '驚怖之門', '焚焰地，是前往寇普雷薩必經之路，座落在鐵牆壁壘之南，巫妖王的精銳組織了堅固的防線來鎮守堡壘。$B$B由一群死亡騎士領頭的骷髏劫奪者軍團擋住了去路。我擔心縱使擊敗了劫奪者，天譴軍團恐怕會輕易地讓他們復生，再次進攻。$B$B我想了個法子來阻止這情況，但我不能保證會奏效。拿著這些溶劑淋在劫奪者的遺骸上把它們融掉。', '破天者號上的薩沙理安希望你用烈性酸液來溶解6個骷髏劫奪者的屍體。', '', '去寒冰皇冠找破天者號的薩沙理安。', '溶解冰冠劫掠者的殘骸', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13336 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13336, 'zhTW', '受選者的血', '那些自稱依米亞的維酷人相當受到巫妖王的重用，他們在寒冰皇冠中央地帶建立了一個屬於他們的城市。在我們進攻冰冠城塞之前尚需許多準備，而我們目前正面對的一樣就是進攻這些自稱「受選」於巫妖王的維酷人。$B$B前往他們的城市依米海姆，在他們的地盤上擊敗他們。讓他們明白誰才是這裡無庸置疑的強者。', '破天者號上的騎士長德羅許要你到依米海姆殺掉20個維酷族。', '', '去找寒冰皇冠的騎士長德羅許。', '殺死依米海姆維酷人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13337 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13337, 'zhTW', '鐵牆壁壘', '鐵牆壁壘眺望著逝往英雄山谷，在奧多薩的西側、稱霸著四面八方的週遭。只要壁壘還未攻下我們根本無法越雷池一步。駐防者是邪惡的葛林克爾與他詛咒神教的爪牙們。$B$B只要你能削弱葛林克爾的力量，至少我們的軍隊就多少能在進軍時與之抗衡。拿著這個歪曲符文，在壁壘盡頭葛林克爾的寶珠旁釋放符文之力，應該多少能夠引起這個召喚師的注意。', '擊敗邪惡的葛林克爾然後回報破天者號上的薩沙理安。', '', '去找寒冰皇冠的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13338 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13338, 'zhTW', '寇普雷薩的守衛者', '寇普雷薩，又稱驚怖之門。將是阻止我們進攻冰冠城塞的最後一道防線。座落在焚焰地與冰冠後方、鐵牆壁壘的南側。但當我們的軍隊行軍至此必定早已筋疲力竭。$B$B我們必須事先削弱它的防禦，否則軍隊很有可能就在此瓦解。$B$B這個要塞駐守著巫妖王最可怕與最狂熱的手下。盡你的全力毀掉這些守衛，那麼或許我們還有一線希望。', '破天者號上的薩沙理安要你殺掉5個恐慌先驅者與 5個寇普雷薩守護者。', '', '去找寒冰皇冠的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13339 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13339, 'zhTW', '擊破碎片', '在寇普雷薩之頂，巫妖王的爪牙豎立了3座水晶，驚怖、絕望與苦難裂片。他打算等我們的人馬一接近寇普雷薩的城牆，就要將水晶的力量釋放來毀滅我們。$B$B若這些能量完全釋放，水晶將會癱瘓每個人的心靈並注入極大的痛苦與恐懼。到時候天譴軍團便能如入無人之境般地進行屠殺。$B$B找出這些水晶然後摧毀它們， 將殘餘的裂片帶回來給我，我們絕對不能讓巫妖王重塑這些武器!', '將破損的驚怖裂片、破損的絕望裂片、破損的苦難裂片，帶回來給破天者號上的薩沙理安。', '', '去寒冰皇冠找破天者號的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13341 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13341, 'zhTW', '協助突襲', '我們需要更多人手來參加對依米海姆的進攻。$B$B凡是有點腦子的戰士，都會告訴你維庫人是兇猛的戰士，不可輕侮。伊米亞戰士更是如此。他們總是不遺餘力地向我們證明，為什麼巫妖王更看重他們。$B$B這場戰鬥由地面指揮官庫普指揮。依米海姆位於寒冰皇冠的中心，庫普的部隊就駐紮在城市東面，靠近冰川的邊緣的地方。', '向依米海姆東面冰川上的地面指揮官庫普報道。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13342 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13342, 'zhTW', '不只是蟲子', '好啦，$g朋友:小姐;，是時候安置點蟲子了。$B$B別緊張，我不是說真的蟲子，但同樣可以達到目的。$B$B在奧多薩的北部，詛咒神教的虛無召喚者奴役了一些惡魔爪牙。使用節杖來從被奴役的爪牙的屍體上吸取一些黑暗物質，然後用在他們的召喚水晶來讓我們的小間諜現身。$B$B直到它被發現之前，黑暗信差都會作為我們的眼睛，暗中地偵察敵人的一舉一動。', '破天者號上的薩沙理安要你在奧多薩蒐集5個黑暗物質來召喚黑暗信差。', '', '去找寒冰皇冠的薩沙理安。', '已召喚黑暗信使', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13343, 'zhTW', '恆龍之謎，復甦', '來的正好!或者...我們是不是才剛講過話?$B$B<克羅米覺得時間的連續性很有趣。>$B$B總之，恆龍正在追你!嗯好吧，不是現在的你。應該說，他們正在追著過去的你，過去正在守護永恆沙漏的你，你還記得對吧?$B$B那時候的你，不過已經變成現在的你了。等等，好，不管了。重點是你得回去青銅龍殿保護你自己跟沙漏以免歷史被改寫，然後你就消失了!', '龍眠神殿的克羅米要求你再次回到青銅龍殿。一旦進入龍殿，將永恆沙漏放在地上並幫助過去的自己抵抗恆龍軍團。', '永恆沙漏已受保護，免受無盡龍族侵害', '去找龍骨荒野的克羅米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13344 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13344, 'zhTW', '活動竊聽器', '教徒們已經發現了你上次召喚出來的信使，$r。$B$B雖然我們已經得到了大量的情報，但是能夠監控詛咒教派的每一步行動對我們非常重要。$B$B轉至奧爾杜薩，用這根魔棒從那些被奴役的爪牙的屍體上吸取一些黑暗物質，然後使用詛咒教派的召喚水晶，再幫我們召喚出一個黑暗信使。$B$B在黑暗信使被發現之前，它將一直作為我們的耳目，小心地觀察敵人的行動。', '破天者號上的薩沙理安希望你去收集5份黑暗物質，然後在奧爾杜薩召喚出一名黑暗信使。', '', '去寒冰皇冠找破天者號的薩沙理安。', '召喚黑暗信使', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13345 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13345, 'zhTW', '需要更多資訊', '詛咒神教雖是出了名的成事不足、敗事有餘，但這次似乎不太一樣...$B$B或許是事關巫妖王讓他們熱血沸騰。但無論如何，他們看似前所未有地自信。我們得抽絲剝繭地找出到底這股自信的來源是什麼。$B$B我想關鍵應該在那些神教研究員身上。找出他們所為何來，然後向我回報。', '破天者號上的薩沙理安要你在奧多薩的神教研究員身上蒐集3頁詛咒神教研究，然後編成詛咒神教論文。', '', '去找寒冰皇冠的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13346 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13346, 'zhTW', '別讓邪惡伺機喘息', '這些傻瓜這次還真的歪打正著了，而且極有可能阻礙我們的計畫!$B$B這一區的領袖，雅路麥斯，在儀式中犧牲自己讓他的僕從引導能量注入他的靈魂。$B$B如果讓他持續修練，很快他們就能將他們主子的靈魂轉化成一股強大的對手。$B$B蒐集雅路麥斯的心臟、顱骨、權杖與長袍然後在雅路麥斯的殘骸結合。$B$B快點，$r! 在他尚未變得太過強大之前摧毀他!', '破天者號上的薩沙理安要你在奧多薩擊敗飛升的雅路麥斯。', '', '去找寒冰皇冠的薩沙理安。', '擊敗飛升的雅路麥斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13347 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13347, 'zhTW', '浴火重生', '我們的命運在出生時就已註定。伯瓦爾之死雖然是一場悲劇，但這也是不可避免的。$B$B現在你所能做的，就是向英雄致敬，$N。從戰場上把伯瓦爾的盾牌拿回來，將其交給你的國王。在你將盾牌交給瓦里安的時候，告訴他：“我們並沒有失去一切。死去的英雄將會使我們變得更加團結，齊心協力將邪惡從這個世界中驅趕出去。”$B$B他一定不能失去信仰。去吧，$N。你的人民需要一個英雄，他們需要你。', '從天災之門安加薩的戰場上取回弗塔根之盾，把它交給暴風城要塞中的瓦里安·烏瑞恩國王。', '', '去暴風城找暴風要塞的瓦里安·烏瑞恩國王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13349 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13349, 'zhTW', '霜育之源', '我們必須加緊攻勢。別讓天譴軍團有機會喘息。$B$B辛德拉苟莎之殞就在逝望山谷之東。詛咒神教就在那一帶活動，受巫妖王的不死維酷僕從們嚴密監督，伺機而動。$B$B那是個含有強大能量的地區，也算是藍龍軍團墳場。可怕的霜育冰龍就是自這些藍龍遺骸中長成。$B$B攻擊此地應該能對敵人的冰霜巨龍兵源造成重創。你願意試試嗎，$n？', '奧格林之錘上的寇爾提拉‧亡織者要你在辛德拉苟莎之殞殺掉5個巨龍復生者、8個教徒墮落者以及3個維酷死靈領主。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13350 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13350, 'zhTW', '別讓邪惡伺機喘息', '是雅路麥斯...我能夠感應到，他的力量又增強了。顯然他的爪牙又重新開始對他灌注能量。如果他得到足夠的休養，很快地他就會變成一個可怕的威脅。$B$B回到他在奧多薩北部的處所。蒐集雅路麥斯的心臟、顱骨、權杖與長袍然後在雅路麥斯的殘骸結合。$B$B快點，$r! 在他尚未變得太過強大之前摧毀他!', '破天者號上的薩沙理安要你在奧多薩擊敗飛升的雅路麥斯。', '', '去找寒冰皇冠的薩沙理安。', '已擊殺昇華者阿魯梅斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13351 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13351, 'zhTW', '暗中偵察', '一切都在計畫之中。我們策劃了一連串完美的計畫來奪下死亡之門。傷亡雖是必然， 但最終的勝利將屬於我們 - 咬緊牙關對付那些愛管閒事的聯盟...$B$B不論如何，我們的下一個目標是奧多薩:荒寂之門。飛往那兒並試著熟悉敵人的據點。$B$B當你回來我會再給你進一步指示。', '奧格林之錘上的寇爾提拉‧亡織者要你飛往荒寂之門，偵察門的南、中、北、西北區域。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已造訪奧督薩爾南方', '已造訪奧督薩爾中央', '已造訪奧督薩爾北方', '已造訪奧督薩爾西北方', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13352 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13352, 'zhTW', '舉手之勞', '詛咒神教掌控著荒寂之門，是嗎? 這並不意外。$B$B找點樂子的時候到了。你提到在門的南端有些新教徒加入。他們幾乎都會攜帶著一個特別的道具 - 一種幻術寶珠。$B$B這東西通常被教徒用來偽裝，讓他們潛入、滲透或混進他們的敵人。$B$B殺了這群傻瓜直到你取得寶珠， $c，然後用在征服者身上。', '奧格林之錘上的寇爾提拉‧亡織者要你從奧多薩的惡劣新兵身上取得幻術寶珠，然後在3個黑暗征服者身上使用它。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已拖拽並丟棄黑暗征服者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13353 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13353, 'zhTW', '舉手之勞', '看樣子又有許多新血加入了詛咒神教。你知道該怎麼做...$B$B在門的南部區域，新加入的教徒正被訓練著，他們幾乎都會攜帶著一個特別的道具 - 一種幻術寶珠。$B$B這東西通常被教徒用來偽裝，讓他們潛入、滲透或混進他們的敵人。$B$B殺了這群傻瓜直到你取得寶珠，然後用在征服者身上。', '奧格林之錘上的寇爾提拉‧亡織者要你從奧多薩的惡劣新兵身上取得幻術寶珠然後用在3個黑暗征服者身上。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已拖拽並丟棄黑暗征服者', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13354 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13354, 'zhTW', '切斷指揮鍊', '從你的報告與我對神教的印象裡，他們在每個駐紮點都派駐了一個監督者來協調各個行動。$B$B我相信也許解決掉這些帶頭的效果非常短暫，但至少能拖延他們的戰術並破壞一點平衡，這對我們目前的處境已經非常值回票價。$B$B解決掉那些監督者以後再回來找我。', '奧格林之錘上的寇爾提拉要你前往奧多薩擊敗監督者菲德里斯、監督者薩夫林、監督者維拉傑與監督者杰昆。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '監工菲德里斯已擊殺', '監工賈昆已擊殺', '監工維拉吉已擊殺', '監工薩弗林已擊殺', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13355 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13355, 'zhTW', '重製失敗', '我從這兒都能嗅到鍋子的臭味，但這不是瘟疫之鍋。$B$B想加入神教的信徒都會被強迫喝下一種遺忘劑，將他們的意志奪去並變成巫妖王永遠的奴隸。$B$B有人說這藥劑裡面包含著被殘忍地折磨後屠殺的受害者靈魂，但我從未成功的重製這樣的藥劑...$B$B將這個瓶子裝滿分別從門的西北區域的三個大鍋取出的樣本，然後拿給首席工程師銅爪。', '奧格林之錘上的寇爾提拉‧亡織者要你利用隔離之瓶從3個教徒的大鍋帶回樣本給首席工程師栓鉗。', '', '去寒冰皇冠找奧格瑞姆之錘的首席工程師銅爪。', '已收集藍色樣本', '已收集綠色樣本', '已收集黑暗樣本', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13356 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13356, 'zhTW', '重新測試', '這樣應該就行了！$B$B那些邪惡的神棍還想把更多靈魂放進他們的噁心果汁？ 我說我們就幫他們一把！$B$B來把這乾了 - 別擔心，我複製了很多…我幾乎敢保證這唯一的效果是當你殺掉一個教徒以後幫你找出他的靈魂菁華。$B$B等你蒐集到一定的量，就把那坨扭曲惡靈的苦痛糾結凝塊扔進任何一個鍋子$B$B讓他們嚐嚐自食惡果的滋味！', '奧格林之錘上的首席工程師銅爪要你將苦痛糾結凝塊丟進奧多薩的一個大鍋中。', '', '去寒冰皇冠找奧格瑞姆之錘的首席工程師銅爪。', '蠕動之團已放逐', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13357 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13357, 'zhTW', '重新測試', '那些邪惡的教徒還想把更多靈魂放進他們的噁心果汁裡? 我說我們就幫他們一把!$B$B來把這乾了 - 別擔心，我複製了很多...我幾乎敢保證這唯一的效果就是當你殺掉一個教徒以後，這會幫你找出他的靈魂菁華。$B$B等你蒐集到一定的量，就把那坨扭曲惡靈的苦痛糾結凝塊扔進任何一個鍋子$B$B讓他們嚐嚐自食惡果的滋味!', '奧格林之錘上的首席工程師銅爪要你將苦痛糾結凝塊丟進奧多薩的一個大鍋中。', '', '去寒冰皇冠找奧格瑞姆之錘的首席工程師銅爪。', '蠕動之團已放逐', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13358 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13358, 'zhTW', '不只是蟲子', '好啦，$g朋友:小姐;，是時候安置點蟲子了。$B$B別緊張，我不是說真的蟲子，但同樣可以達到目的。$B$B在奧多薩的北部，詛咒神教的虛無召喚者奴役了一些惡魔爪牙。使用節杖來從被奴役的爪牙的屍體上吸取一些黑暗物質，然後用在天譴召喚水晶來讓我們的小間諜現身。$B$B直到它被發現之前，黑暗信差都會作為我們的眼睛，暗中地偵察敵人的一舉一動。', '奧格林之錘上的寇爾提菈要你在奧多薩蒐集5個黑暗物質來召喚黑暗信差。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已召喚黑暗信使', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13359 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13359, 'zhTW', '龍殞之地', '藍龍一族全數都在此隕落。但現在，一個接著一個，他們被「他」的僕從召回。$B$B他親手將最年長的一些復生。帶回一些幼龍的骨塵給我。我將告訴你他是如何辦到的。', '辛德拉苟莎之殞的米希阿斯‧薩爾奈，請你取得6個幼龍骨塵。', '', '去找寒冰皇冠的米希阿斯·薩爾奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13361 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13361, 'zhTW', '王子與獵手', '在王子變成國王以前。他打了好多好多仗...但唯一的一次，他差點送了命。$B$B那場戰鬥就在這裡。在你讓我展示事情的經過以後，你就全部都了解了。$B$B找一塊染血之石然後把它撿起來。然後你就會看到一切的經過...', '白骨之廷的米希阿斯‧薩爾奈要你尋找一個染血之石然後完成王子的宿命。', '', '去找寒冰皇冠的米希阿斯·薩爾奈。', '王子的命運', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13364 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13364, 'zhTW', '提里奧的決斷', '就在今晨，我的斥候才告訴我詛咒神教的一行人，正由冰冠城塞帶著一件聖物前往黑暗大教堂。$B$B現在我知道那應該就是阿薩斯的心臟...保存著他最後剩下的一丁點人性。$B$B這是聖光給我們的預兆。只要這聖物尚存在，就表示阿薩斯‧米奈希爾有朝一日還能找回他的人性!$B$B到教堂入口見我。記得帶上教徒侍僧兜帽 - 我們要喬裝進去。', '十字軍之巔的提里奧‧弗丁要你取得，並帶著教徒侍僧兜帽到黑暗大教堂入口見他，就在冰冠城塞的西北邊。', '', '去找寒冰皇冠的大領主提里奧‧弗丁。', '', '提里奧的謀略', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13365 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13365, 'zhTW', '不只是蟲子', '詛咒教徒已經發現了你的上個信差，$r。$B$B但在消息尚未證實前，持續監視他們的每一步格外重要。$B$B在奧多薩使用節杖來從被奴役的爪牙的屍體上吸取一些黑暗物質，然後用在天譴召喚水晶來讓我們的小間諜現身。$B$B直到它被發現之前，黑暗信差都會作為我們的眼睛，暗中地偵察敵人的一舉一動。', '奧格林之錘上的寇爾提菈要你在奧多薩蒐集5個黑暗物質來召喚黑暗信差。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已召喚黑暗信使', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13366 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13366, 'zhTW', '需要更多資訊', '詛咒神教雖是出了名的成事不足、敗事有餘，但這次似乎不太一樣。$B$B或許是事關巫妖王讓他們熱血沸騰。但無論如何，他們看似前所未有地自信。我們得抽絲剝繭地找出到底這股自信的來源是什麼。$B$B我想關鍵應該在那些神教研究員身上。找出他們所為何來，然後向我回報。', '奧格林之錘上的寇爾提拉要你在奧多薩的神教研究員身上蒐集3頁詛咒神教研究，然後編成詛咒神教論文。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13367 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13367, 'zhTW', '別讓邪惡伺機喘息', '這些傻瓜這次還真的歪打正著了，而且極有可能阻礙我們的計畫!$B$B這一區的領袖，雅路麥斯，在儀式中犧牲自己讓他的僕從引導能量注入他的靈魂。$B$B如果讓他持續修練，很快他們就能將他們主子的靈魂轉化成一股強大的對手。$B$B蒐集雅路麥斯的心臟、顱骨、權杖與長袍然後在雅路麥斯的殘骸結合。$B$B快點，$r! 在他尚未變得太過強大之前摧毀他!', '奧格林之錘上的寇爾提拉，要你在奧多薩擊敗飛升的雅路麥斯。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已擊敗昇華者阿魯梅斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13368 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13368, 'zhTW', '別讓邪惡伺機喘息', '是雅路麥斯...我能夠感應到，他的力量又增強了。顯然他的爪牙又重新開始對他灌注能量。如果他得到足夠的休養，很快地他就會變成一個可怕的威脅。$B$B回到他在奧多薩北部的處所。蒐集雅路麥斯的心臟、顱骨、權杖與長袍然後在雅路麥斯的殘骸結合。$B$B快點，$r! 現在還來得及摧毀他!', '奧格林之錘上的寇爾提拉，要你在奧多薩擊敗飛升的雅路麥斯。', '', '去寒冰皇冠找奧格瑞姆之錘的寇爾提拉‧亡織者。', '已擊敗昇華者阿魯梅斯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13369 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13369, 'zhTW', '造化弄人', '根據普勞德摩爾女士的要求，我允許她作為外交使節轉至奧格瑪，質問部落的索爾酋長。我會派你協助她，保證她的安全。把奧格瑪的訊息帶回來告訴我。$B$B等你做好出發的準備之後，就去跟珍娜談談吧。', '陪同珍娜·普勞德摩爾轉至卡林多大陸的奧格瑪，與部落的索爾酋長交談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13370 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13370, 'zhTW', '政變', '你們的勇士伯瓦爾為保衛我們這個世界而犧牲了。我們部落同樣為了失去這樣一位偉大的英雄而感到悲傷，但部落並不應該為普特雷斯在天災之門發動的偷襲而負責。我們也因為這次背叛失去了一位偉大的英雄。$B$B告訴你的國王，我們會盡一切努力將這次事件的主謀繩之以法。我們也會盡全力避免與聯盟發生衝突，不過如果我們受到挑釁，部落也會毫不猶豫地進行自衛。', '使用格羅瑪什堡壘中的傳送門返回暴風要塞，把索爾的訊息轉達給瓦里安·烏瑞恩國王。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13371 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13371, 'zhTW', '殺戮時刻', '在你從奧格瑪回來之前，我就派了布羅爾和瓦莉拉轉至幽暗城。事實上，他們現在已經駐紮在通往廢墟的下水道入口外面，等待著我的命令。$B$B普勞德摩爾女士會開啟一道傳送門，穿過它就可以直達幽暗城外，與我們的部隊匯合。去向布羅爾和瓦莉拉報到吧，我稍後就到。', '使用暴風要塞內的通往幽暗城的傳送門轉至幽暗城。到達目的地之後，向布羅爾·熊皮報到。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13372 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13372, 'zhTW', '聚源虹膜之鑰', '一股強烈的魔力不斷以聲音與能量的形式，自這塊從薩菲隆爪上落下的眼狀珠寶中發散出來。對於凡人而言光是待在這塊石頭附近就感到幾近刺耳。$B$B很明顯地這樣強大的物品必須帶給巨龍之后，『生命守縛者』雅立史卓莎。前往龍眠神殿諮詢她的建議，就在龍骨荒野區域。', '轉交聚源虹膜之鑰給『生命守縛者』雅立史卓莎，她就在龍骨荒野的龍眠神殿頂端。', '', '去找龍骨荒野的『生命守縛者』雅立史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13374 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13374, 'zhTW', '大反擊!', '聽好，$n，只有最好的飛行員才能接受這個任務，只有綠外線科技與你同在之下，來個又深又遠的長途飛行深入敵境!$B$B讓利基再給你一架轟炸機，這次前往逝望山谷。由於這次任務目標同時會位於空中與地面，眼睛睜大點兒，看好你的護盾!$B$B祝你好運!', '偏激工程師泰茲菈要你殺掉轟炸地步兵、石像鬼伏擊者、霜育哨兵與天譴戰爭機器。', '', '去找寒冰皇冠的偏激工程師泰茲菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13375 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13375, 'zhTW', '聚源虹膜英雄之鑰', '一股強烈的魔力不斷以聲音與能量的形式，自這塊從薩菲隆爪上落下的眼狀珠寶中發散出來。對於凡人而言光是待在這塊石頭附近就感到幾近刺耳。$B$B很明顯地這樣強大的物品必須帶給巨龍之后，『生命守縛者』雅立史卓莎。前往龍眠神殿諮詢她的建議，就在龍骨荒野區域。', '轉交聚源虹膜英雄之鑰給『生命守縛者』雅立史卓莎，她就在龍骨荒野的龍眠神殿頂端。', '', '去找龍骨荒野的『生命守縛者』雅立史卓莎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13377 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13377, 'zhTW', '幽暗城之戰', '在天譴之門殺害伯瓦爾和勇敢的聯盟士兵的罪魁禍首，眼下就躲藏在幽暗城的深處。$B$B瓦里安已經帶著聯盟最強大的部隊前來支援這次行動了。加入他和普勞德摩爾女士的隊伍，與這些最偉大的聯盟勇士們並肩戰鬥！$B$B等你準備好了之後，就去告訴瓦里安·烏瑞恩國王。', '協助瓦里安·烏瑞恩國王和珍娜·普勞德摩爾，剿滅大藥劑師普特雷斯！成功之後，向瓦里安·烏瑞恩國王報告。', '協助瓦里安·烏瑞恩國王', '去暴風城找暴風要塞的瓦里安·烏瑞恩國王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13378 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13378, 'zhTW', '首席工程師考伯克拉', '與首席工程師考伯克拉談談。', '與首席工程師考伯克拉談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13380, 'zhTW', '委以重任', '綠外線技術可以讓我們在天災軍團的鼻子底下大搖大擺地行動！而且，我們把這種技術應用到了專門製造的轟炸機上……但不是為了隱藏它們，完全不是那麼回事！我們用綠外線技術來保護它們！$B$B去向卡倫·諾爾要一架轟炸機，然後飛到轟炸場上空……用它的護盾和炮臺保護自己，並使用投彈器攻擊天災軍團。好好練習一下，然後再回來找我。我還有很多更重要的任務要交給你呢！', '吉普利·基羅赫斯要你去殺死40個轟炸場步兵、8個轟炸場軍官和15只石像鬼伏擊者。', '', '去找寒冰皇冠的碁伯里‧基羅赫茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13381 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13381, 'zhTW', '下個目標', '帶好你的幸運符，$n，選篇你最喜歡的禱告辭。下個任務就要測試你的反應跟耐性，好像你丈母娘要來一樣!$B$B找凱倫‧諾談話再索取一架轟炸機。駕著它飛越轟炸地深入逝望山谷。這次的目標更多，天上飛的跟地上爬的都有。看好你的護盾，子彈通通上膛，$n!結束以後回來找我。', '碁伯里‧基羅赫茲要你殺掉轟炸地步兵、石像鬼伏擊者、霜育哨兵與天譴戰爭機器。', '', '去找寒冰皇冠的碁伯里‧基羅赫茲。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13384 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13384, 'zhTW', '永恆之眼的審判', '現你既已能夠進入聚源虹膜，也該是時候將鑰匙發揮真正的作用了。$B$B儘管我也希望生擒瑪里苟斯，但情勢似乎不容許我們這麼做。事情到了這個關頭，其餘的守護巨龍者認為『織法者』必須...被制裁。$B$B<卡薩斯的最後一句話帶著些許的不安。>$B$B$n，前往永恆之眼，迎戰瑪里苟斯並將魔法之心帶回來。', '卡薩斯，位於龍骨荒野的龍眠神殿頂端，要你帶著魔法之心回去。這個任務適用普通難度、10人的永恆之眼副本。', '', '去找龍骨荒野的卡薩斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13385 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13385, 'zhTW', '永恆之眼的英雄審判', '現你既已能夠進入聚源虹膜，也該是時候將鑰匙發揮真正的作用了。$B$B儘管我也希望生擒瑪里苟斯，但情勢似乎不容許我們這麼做。事情到了這個關頭，其餘的守護巨龍者認為『織法者』必須...被制裁。$B$B<卡薩斯的最後一句話帶著些許的不安。>$B$B$n，前往永恆之眼，迎戰瑪里苟斯並將魔法之心帶回來。', '卡薩斯，位於龍骨荒野的龍眠神殿頂端，要你帶著魔法之心回去。這個任務適用英雄難度、25人的永恆之眼副本。', '', '去找龍骨荒野的卡薩斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13387 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13387, 'zhTW', '保護現場', '薩隆邪鐵炸彈已經安裝完畢，$N。但是我們只有一次機會，千萬別搞砸了。$B$B為了確保安全爆破，我們必須奪得這片本地的臨時控制權。先去削減天災士兵的數量吧。', '冰冠堡壘的肯達爾上尉要你去殺死10只笨重的恐屍。', '', '去寒冰皇冠找冰冠堡壘的肯達爾上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13388 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13388, 'zhTW', '引爆！', '事情進展得非常順利，準備引爆炸彈吧。$B$B它們就堆在深坑附近。我這就開始疏散人員。', '冰冠堡壘下面的肯達爾上尉要你轉至附近的薩隆邪鐵炸彈堆旁邊，點燃引線。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13389 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13389, 'zhTW', '引線太短', '在你點燃引線的時候，你發現它的燃燒速度比你想像中的要快了許多。$B$B炸彈就要爆炸了，只有馬上跳進深坑，並且不被炸下來的雜物砸到，你才有可能活下來。', '在你被雜物砸中的地方尋找線索。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13390 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13390, 'zhTW', '黑暗中的聲音', '這東西根本不是水晶，而是某種被寒冰包裹的器官。$B$B當你碰到它的時候，你的手上傳來一陣劇痛。你覺得自己的手彷彿被砍掉了一樣，但卻看到不任何傷口。$B$B當你再次集中精神時，你聽見附近有一個小男孩的聲音在飄蕩。$B$B“你真的不該那麼做的。”', '在納扎納克：遺忘深淵裡調查這個聲音的來源。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13391 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13391, 'zhTW', '藏匿行蹤', '你不該碰它的。但你已經碰過了，他很快就會來找你。$B$B他一定會找到你，除非你能躲藏起來，不讓他發現。$B$B如果你還想活下去，就去弄一些無面者的鮮血回來！', '米斯希爾薩·阿奈爾要你收集3份無面者之血。', '', '去寒冰皇冠找納扎納克：遺忘深淵的米斯希爾薩·阿奈爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13393 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13393, 'zhTW', '戰地維修', '好吧，現在還不到慶功的時候。你順利地完成了引爆任務，極大地鼓舞了部隊計程車氣，我們要一鼓作氣，繼續戰鬥。$B$B士兵們在下面的曠野中發現了一架部落的大型攻城車，似乎還可以使用。惡鬼們好像正在拆卸它的零件。$B$B如果能將它重新組裝起來，我們一定能重創山谷裡的天譴軍團。$B$B當然，你可以要面對為數眾多的敵人，但是我對你有信心！', '破天者號上的薩沙理安要你從食腐的惡鬼身上收集5塊攻城車零件，然後將它們帶去失落希望之谷的毀壞的攻城車旁。', '', '去寒冰皇冠的失落希望之谷找毀壞的攻城車。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13394 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13394, 'zhTW', '別太認真', '你要用這玩意對付天譴軍團？我想你大概贏不了。$B$B我相信你能摧毀大概上百…甚至上千個天譴軍，但還是沒用的。至少在這個情況沒有用。$B$B等你玩夠了再來北邊找我，那兒有個老舊的駐軍營地。我會讓你了解你真正要面對的敵人。', '利用翻新的石毀車在逝望山谷摧毀150隻被分解的食屍鬼、20名霜顱法師、2名骸骨巨人。完成後與第一軍團前線營地的米希阿斯‧薩爾奈對話。', '', '去找寒冰皇冠的米希阿斯·薩爾奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13395 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13395, 'zhTW', '詛咒軍團', '你大概以為你很厲害--打敗這些不死生物，用你的戰爭機器壓碎他們的骸骨。$B$B但這跟創造他們的力量比起來微不足道。$B$B我曾經看過王子殿下親自表演。我可以示範給你看...如果你想的話。', '第一軍團前線營地的米希阿斯‧薩爾奈要求你，喚起100名食屍爪牙，以讓它們加入軍隊。', '', '去找寒冰皇冠的米希阿斯·薩爾奈。', '已喚起食屍鬼爪牙', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13396 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13396, 'zhTW', '徒勞', '現在你明白了嗎？派你們的人去對付王子的部隊，只會讓他們獲得更多的士兵。$B$B我也不指望你能明白……你的下場或許會和其它人一樣。你還是回到派你來的人身邊去吧，他們可能在擔心你了。', '返回破天者號，向薩沙理安覆命。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13397 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13397, 'zhTW', '辛德拉苟莎之殞', '你真的天生適合這行，$n。你瞧，通常當我指派任務給其他士兵。他們完成的機率大概一半一半，至於回來的機率...呃，大概要再少一點。$B$B但是你，永遠是使命必達。就像地精鐘錶一樣精準!$B$B總之呢，我還有任務給你。辛德拉苟莎之殞，就在山谷東邊。那邊有許多的教徒正蠢蠢欲動，更別提冰霜巨龍的紛擾。我要你去給我教訓那些傢伙。$B$B我討厭那些教徒。', '破天者號上的薩沙理安要你在辛德拉苟莎之殞殺掉5個巨龍復生者、8個教徒墮落者以及3個維酷死靈領主。', '', '去寒冰皇冠找破天者號的薩沙理安。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13398 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13398, 'zhTW', '龍殞之地', '藍龍一族全數都在此隕落。但現在，一個接著一個，他們被「他」的僕從召回。$B$B他親手將最年長的一些復生。帶回一些幼龍的骨塵給我。我將告訴你他是如何辦到的。', '辛德拉苟莎之殞的米希阿斯‧薩爾奈，請你取得6個幼龍骨塵。', '', '去找寒冰皇冠的米希阿斯·薩爾奈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13400 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13400, 'zhTW', '王子與獵手', '在王子變成國王以前。他打了好多好多仗...但唯一的一次，他差點送了命。$B$B那場戰鬥就在這裡。在你讓我展示事情的經過以後，你就全部都了解了。$B$B找一塊染血之石然後把它撿起來。然後你就會看到一切的經過...', '白骨之廷的米希阿斯‧薩爾奈要你尋找一個染血之石然後完成王子的宿命。', '', '去找寒冰皇冠的米希阿斯·薩爾奈。', '王子的命運', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13403 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13403, 'zhTW', '提里奧的決斷', '就在今晨，我的斥候才告訴我詛咒神教的一行人，正由冰冠城塞帶著一件聖物前往黑暗大教堂。$B$B現在我知道那應該就是阿薩斯的心臟...保存著他最後剩下的一丁點人性。$B$B這是聖光給我們的預兆。只要這聖物尚存在，就表示阿薩斯‧米奈希爾有朝一日還能找回他的人性!$B$B到教堂入口見我。記得帶上教徒侍僧兜帽 - 我們要喬裝進去。', '十字軍之巔的提里奧‧弗丁要你取得，並帶著教徒侍僧兜帽到黑暗大教堂入口見他，就在冰冠城塞的西北邊。', '', '去找寒冰皇冠的大領主提里奧‧弗丁。', '', '提里奧的謀略', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13405 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13405, 'zhTW', '戰鬥的召喚：遠古海灘', '北裂境的戰鬥並不僅僅是對抗巫妖王的部隊，我們還要與那些部落交鋒。$B$B最近我們在遠古海灘發現了一件強大的泰坦神器。你應該知道，我們矮人向來都是這類神器的保管者，因此我們也同樣有資格獲得這件新發現的神器。$B$B眼下，部落對這件神器表現出了極大的興趣，他們很顯然想要盜取神器，並用它來對付我們。聯盟必須不惜一切代價阻止他們！', '在遠古海灘戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟准將覆命。', '在遠古海灘獲勝', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13407 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13407, 'zhTW', '戰鬥的召喚：遠古海灘', '雖然說我們開進北裂境是為了掃平天譴軍團，但這並不代表我們應該對聯盟不聞不問。$B$B探險者協會的矮人已經發現了一件強大的泰坦聖物的所在地，如果讓聯盟拿到它的話，我們就沒好日子過了。$B$B去吧，$N，消滅我們的敵人。讓他們明白，無論在哪裡相遇，他們永遠都是我們不共戴天的死敵。', '在遠古海灘戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。', '在遠古海灘獲勝', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13408 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13408, 'zhTW', '地獄火半島的工事', '地獄火堡壘與我們的軍隊一直有著小規模的衝突與交戰。當前，我們自己的領地大多守備穩固，但一直沒能對他們發動真正的進攻。為了籌備進攻，我們要首先佔領地獄火堡壘外圍的戰略要地。$B$B我們的斥候當前確定了三處互成犄角之勢的工事，希望你能協助這三處的防守。佔領所有工事之後回來向我報告。$B$B願你能在接下來的戰鬥中有好運氣，$N，毫無疑問，你得面對部落的威脅，他們也同樣想佔領這三處重要的工事。', '佔領瞭望臺、競賽場和碎石嶺，然後向地獄火半島上榮耀堡內的委任官翠希·普羅維爾覆命。', '', '去地獄火半島找榮耀堡的委任官翠希·普羅維爾。', '佔領瞭望臺', '佔領競賽場', '佔領碎石嶺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13409, 'zhTW', '地獄火半島的工事', '在我們的故鄉肆虐的所有地獄火堡壘邪獸人都必須要消滅乾淨！但要想攻擊地獄火堡壘，我們必須首先佔領堡壘外圍的幾處戰略要地。$B$B巡邏隊發現有三處工事正好適合我們的目的。但聯盟竟與我們不謀而合，現在已經派出部隊佔領了那裡！$B$B我要求你立刻阻止聯盟的行動，並佔領這些工事。協助我軍佔領工事之後，立刻回來向我報告。$B$B為了部落！', '佔領瞭望臺、競賽場和碎石嶺，然後向地獄火半島上索爾瑪的傳令官布萊肯·黑眼覆命。', '', '去地獄火半島找索爾瑪的傳令官布萊肯·黑眼。', '佔領瞭望臺', '佔領競賽場', '佔領碎石嶺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13410 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13410, 'zhTW', '地獄火半島的工事', '地獄火堡壘與我們的軍隊一直有著小規模的衝突與交戰。當前，我們自己的領地大多守備穩固，但一直沒能對他們發動真正的進攻。為了籌備進攻，我們要首先佔領地獄火堡壘外圍的戰略要地。$B$B我們的斥候當前確定了三處互成犄角之勢的工事，希望你能協助這三處的防守。佔領所有工事之後回來向我報告。$B$B願你能在接下來的戰鬥中有好運氣，$N，毫無疑問，你得面對部落的威脅，他們也同樣想佔領這三處重要的工事。', '佔領瞭望臺、競賽場和碎石嶺，然後向地獄火半島上榮耀堡內的委任官翠希·普羅維爾覆命。', '', '去地獄火半島找榮耀堡的委任官翠希·普羅維爾。', '佔領瞭望臺', '佔領競賽場', '佔領碎石嶺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13411 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13411, 'zhTW', '地獄火半島的工事', '在我們的故鄉肆虐的所有地獄火堡壘邪獸人都必須要消滅乾淨！但要想攻擊地獄火堡壘，我們必須首先佔領堡壘外圍的幾處戰略要地。$B$B巡邏隊發現有三處工事正好適合我們的目的。但聯盟竟與我們不謀而合，現在已經派出部隊佔領了那裡！$B$B我要求你立刻阻止聯盟的行動，並佔領這些工事。協助我軍佔領工事之後，立刻回來向我報告。$B$B為了部落！', '佔領瞭望臺、競賽場和碎石嶺，然後向地獄火半島上索爾瑪的傳令官布萊肯·黑眼覆命。', '', '去地獄火半島找索爾瑪的傳令官布萊肯·黑眼。', '佔領瞭望臺', '佔領競賽場', '佔領碎石嶺', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13412 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13412, 'zhTW', '科拉絲塔薩', '你好，$c。能請你幫個忙嗎？$B$B紅龍萊洛拉斯負責駐守這座崗哨，他有個妹妹叫作科拉絲塔薩。科拉絲塔薩不顧萊洛拉斯的反對，到魔樞上層偵察藍龍的活動去了。$B$B他雖然嘴上不說，但是心裡還是很牽掛自己的妹妹。如果能得到科拉絲塔薩的訊息，他肯定會很高興的。$B$B請你去找到她，叫她放下自尊，給她的兄弟捎個訊息回來。', '圖書館員塞爾拉要你去跟考達拉的科拉斯塔薩談一談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13413 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13413, 'zhTW', '展翅高飛！', '凡人，你居然有勇氣靠近瑪裡苟斯的巢穴？還是說你只是因為無知才闖進這裡的？答案很快就可以揭曉了……$B$B我是一名經驗豐富的訓練師，專門為紅龍軍團訓練優雅的幼龍。我來這裡研究敵人的作戰手段，並向我珍愛的寵物們傳授有效的禦敵手段，以便將來能對付藍龍軍團的主子。$B$B為了讓你有機會證明自己的勇氣和實力，我可以讓你騎著我的幼龍去對付敵人的爪牙。$B$B只要你開口，就可以得到這個寶貴的機會……', '考達拉魔樞上層的科拉絲塔薩要你騎著她的幼龍殺死5名鱗誓精英。', '', '去北風凍原找魔樞的科拉絲塔薩。', '殺死鱗誓精英', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13414 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13414, 'zhTW', '展翅高飛！', '我們又見面了，$r。我要承認，我對你越來越感興趣了。$B$B如果我沒猜錯的話，你是來練習空戰技巧的吧？$B$B像平時一樣，我的寵物已經做好準備，隨時可以去消滅敵人。$B$B只要你開口，就可以隨意調遣它們。', '考達拉魔樞上層的科拉絲塔薩要你騎著她的幼龍殺死5名鱗誓精英。', '', '去北風凍原找魔樞的科拉絲塔薩。', '殺死鱗誓精英', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13415 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13415, 'zhTW', '圖書館裡的控制臺', '諾甘農之殼已唾手可得，$n。帶著發明者圓盤進入圖書館。裡面應該有個控制臺，你可以用發明者圓盤啟動它。我猜想除了諾甘農之殼，彌米爾在那裡應該藏了更多東西。那裡儲藏的結構圖，應該可以讓鐵爐堡的工程師忙上個好幾年!$B$B無論如何，使用圓盤以取回諾甘農之殼。但願彌米爾沒有在我們的路途上放上更多障礙。', '將發明者圓盤，帶至發明者圖書館裡的發明者圖書館控制臺。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13416 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13416, 'zhTW', '圖書館裡的控制臺', '諾甘農之殼已唾手可得，$n。帶著發明者圓盤進入圖書館。裡面應該有個控制臺，你可以用發明者圓盤啟動它。我猜想除了諾甘農之殼，彌米爾在那裡應該藏了更多東西。那裡儲藏的結構圖，應該可以讓鐵爐堡的工程師忙上個好幾年!$B$B無論如何，將圓盤帶去控制臺。但願彌米爾沒有在我們的路途上放上更多障礙。', '將發明者圓盤，帶至發明者圖書館裡的發明者圖書館控制臺。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13417 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13417, 'zhTW', '銅鬚兄弟', '成功了！我們終於拿到拱心石了…它好美啊！我曾經多次環遊世界，但這東西又再次喚起了我的不安與興奮。不過，我想現在不是呆呆的站著看的時候了，我們得看點逃出去。$B$B跳上我的飛行器，在出去的路上幫忙掩護我！', '陪同布萊恩·銅鬚，搭乘其飛行器前往霜堡。', '陪同布萊恩·銅鬚前往霜堡', '去風暴峭壁找冰霜堡的維羅格·冰嘯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13420 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13420, 'zhTW', '永霜', '這塊冰曾歷經巨大的壓力、長期深埋地底，經過大自然的魔法所催化。以上種種所造成的影響，竟然使得這塊冰不再融化。$B$B由於對這樣的現象所知甚少，你決定把一塊樣品帶回丹尼弗蘭，確信那兒一定有人會具備更深入的見解。', '你即將返回丹尼弗蘭詢問考德爾有關這塊永霜的訊息。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13421 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13421, 'zhTW', '牢記永霜!', '', '', '', '去找祖爾德拉克的考德爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13422 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13422, 'zhTW', '維護紀律', '你完成了別人做不到的事。但你萬不能就此停歇。$B$B你必須讓其他人看看何謂真正的力量與奉獻。$B$B凋落礦坑中許多維酷男工非常的不合群，必須讓他們再次學習什麼叫做紀律。讓他們看看，姐妹...讓他們看看不服從的下場是什麼。', '布倫希爾達村的『仲裁者』格瑞塔要你對6個疲憊的維酷人使用紀律權杖。', '', '去找風暴峭壁的『仲裁者』格瑞塔。', '已管教精疲力盡的維库人', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13423 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13423, 'zhTW', '衛冕', '每個人都對你的表現印象深刻，姊妹。但是不要放鬆了戒心!每個迷於聲名的挑戰者都將會上前挑戰你的海茲戰后頭銜。$B$B給這些傲慢自大的傢伙一點教訓，讓她們見識一下你的戰后本色。', '布倫希爾達村的『仲裁者』格瑞塔要求你擊敗六個挑戰者。', '', '去風暴峭壁找布倫希爾達村的仲裁者格蕾塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13424 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13424, 'zhTW', '重返深淵', '要保持最好的騎術，你就得每天與其他海迪尼爾切磋。$B$B返回尖牙之淵，把你的技術展現給她們看。她們會很感激像你這樣高超的人將她們擊敗的。', '布倫希爾達村的『仲裁者』格瑞塔要你到尖牙之淵使用冰喉族母韁繩，然後擊敗6頭海茲競技戰熊。', '', '去風暴峭壁找布倫希爾達村的仲裁者格蕾塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13425 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13425, 'zhTW', '那些畸形非死不可', '只對你的同伴展現你的本領是不夠的。你也必須對抗我們的敵人，親愛的姊妹。$B$B華爾基倫的那些叛徒還在養殖染疫的元龍，不停嘲弄我們的龍騎傳統。$B$B搶走他們持有的冰霜油，然後凍毀那些可恨的染疫龍蛋。', '布倫希爾達村的『仲裁者』格瑞塔要你前往華爾基倫，從華爾基倫野心家身上取得冰霜之油瓶。使用冰霜之油瓶摧毀30個染疫元龍蛋。', '', '去找風暴峭壁的『仲裁者』格瑞塔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13427, 'zhTW', '戰鬥的召喚：奧特蘭克山谷', '事實上，我們在多線作戰，$g小子:小姑娘;，而且我們不能把軍隊部署得太過分佈，否則我們可能會全盤皆輸！$B$B我們需要以天為單位來部署最關鍵的部隊，今天，奧特蘭克山谷的戰鬥最需要勇敢的士兵們！$B$B現在就出發吧，$N，去幫助雷矛遠征軍。我們不能就這麼看著霜狼氏族逃脫他們應受的懲罰。', '在奧特蘭克山谷戰場中獲得一場勝利，然後向任意聯盟主城、達拉然、冬握湖或撒塔斯城中的聯盟准將覆命。', '在奧特蘭克山谷獲勝', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13428, 'zhTW', '戰鬥的召喚：奧特蘭克山谷', '我們就快要把雷矛入侵者從奧特蘭克山谷趕走了，因此我們必須調動一切可能的增援力量來幫助霜狼氏族。$B$B一場決定性的勝利可以讓我們騰出足夠的資源在其它戰場上消滅聯盟的那些混蛋。$B$B出發吧，$N。聽從霜狼氏族的號令，去贏得無上的榮耀吧！', '在奧特蘭克山谷戰場中獲得一場勝利，然後向任意部落主城、達拉然、冬握湖或撒塔斯城中的部落戰爭使者覆命。', '在奧特蘭克山谷獲勝', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13429, 'zhTW', '替阿卡瑪製造混亂', '<希瑞的身上閃爍著光芒，身邊的奧多爾與占卜者部隊等待希瑞下達命令。希瑞的部隊準備逼退伊利丹的部隊，替阿卡瑪製造一場騷動。那魯等待著你提出開戰的請求。>', '在希瑞的手下製造混亂的時候護送阿卡瑪和瑪翼夫進入影月谷的黑暗神廟。', '幫助阿卡瑪與麥維進入黑暗神廟', '去找影月谷的希瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13430 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13430, 'zhTW', '那魯的試煉:瑪瑟里頓', '在你被那魯認可之前，你必須通過四次考驗。$B$B只剩一個障礙了，凡人。召集一支軍隊並且前往地獄火堡壘深處的瑪瑟里頓巢穴。一路殺進密室的中心，並毀滅那邪惡的腐敗者!', '撒塔斯城的阿達歐要你殺死瑪瑟里頓。', '', '去找沙塔斯城的阿達歐。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13431, 'zhTW', '卡達什聖杖', '將製作聖杖所需的元素徽記給我帶回來！$B$B土靈徽記在屠龍者格魯爾手中，他就躲在刀鋒山的巢穴裡。$B$B另一枚徽記是夜之魘的心臟，據說這隻神秘的野獸居住在先知麥迪文的高塔內。$B$B迅速行動吧！', '將土靈徽記和燦爛徽記交給盤牙水庫奴隸圍欄的異教徒斯卡希斯。', '', '去找奴隸圍欄的異教徒斯卡希斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13432 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13432, 'zhTW', '永恆水瓶', '伊利丹從永恆之井中取出了七瓶水。他將其中三瓶倒入海加爾山顛的湖泊中，由此形成了第二口永恆之井。歲月流逝，剩下的四瓶水已不知去向。$B$B黑暗之門開啟後，我們得知伊利丹將兩瓶水交給了他的副官凱爾薩斯和瓦絲琪。取回殘餘的永恆之水，我們可以利用它開啟通往近代或是遠古時期的海加爾山的時光通道。我們必須維持海加爾聖戰的事件不被改變。', '時光之穴的索莉多米要你從盤牙水庫的瓦絲琪那裡取回瓦絲琪的水瓶殘餘，並從風暴要塞的凱爾薩斯·逐日者那裡取回凱爾薩斯的水瓶殘餘。', '', '去找塔納利斯的索莉多米。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13433 AND `locale` = 'zhTW';
