DELETE FROM `quest_template_locale` WHERE `ID` = 13476 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13476, 'zhTW', '無上的榮耀', '與聯盟作戰是為部落效勞的莫大榮耀！那些在各條戰聯機和聯盟作戰的士兵是我們最偉大的成員。我們要消滅我們的對手，而不是僅僅進行小規模的遭遇戰，我們要打精心準備的大戰。$B$B去每一條戰聯機消滅聯盟吧！為了榮耀！為了部落！', '在每個戰場上都取得1枚榮譽獎章，並將它們交給任意部落主城、沙塔斯、達拉然或冬握湖的部落戰爭使者。', '', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13477 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13477, 'zhTW', '共同的努力', '', '', '', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13478 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13478, 'zhTW', '共同的努力', '我們並不是在獨自與部落交戰，$g小夥子:小姑娘;。$B$B如果我們可以取得勝利，那麼我們就可以使用部落的資源來在其它的戰場上對抗他們。反之，如果我們輸掉了這場戰爭，那麼在其它的戰場上，部落將會佔有優勢。$B$B聯盟需要更多你這種身經百戰、意志堅定的老兵！$N，當你在所有戰場上都與部落交戰之後再回到我這裡。', '在每個戰場上都取得1枚榮譽獎章，並將它們交給任意聯盟主城、沙塔斯、達拉然或冬握湖的聯盟准將。', '', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13479 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13479, 'zhTW', '彩蛋大狩獵', '貴族花園，生命與春天的慶典！希望你們喜歡彩蛋狩獵，朋友，說不定我用得上像你這樣卓越人士的協助。 我不知道是什麼樣的魔法製造出這些彩蛋，德魯伊也不願意向我解釋。說不定你能在收集彩蛋的時候也替我找一些蛋殼碎片。你可以保留彩蛋裡面的東西，我只是想要一些蛋殼碎片的樣本。', '取得20個蛋殼碎片。', '', '去找春日蒐集者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13480, 'zhTW', '彩蛋大狩獵', '貴族花園，生命與春天的慶典！希望你們喜歡彩蛋狩獵，朋友，說不定我用得上像你這樣卓越人士的協助。 我不知道是什麼樣的魔法製造出這些彩蛋，德魯伊也不願意向我解釋。說不定你能在收集彩蛋的時候也替我找一些蛋殼碎片。你可以保留彩蛋裡面的東西，我只是想要一些蛋殼碎片的樣本。', '取得20個蛋殼碎片。', '', '去找春日收集者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13481 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13481, 'zhTW', '讓我們離開這裡!', '聖光對我微笑。我還沒有死在這場活生生的夢魘中，不過如果我不逃出去，天譴軍團會因為我在「使用」它們在這邊的成果而把我撕成碎片。$B$B但我一個人逃不了，$c，我需要你的幫助，如果我能逃出去就能再次對抗天譴軍團。$B$B你願意幫我逃出去，從天譴軍的屠夫手上救我一命？', '護送卡瑪洛斯神父至安全之處，並向奧格林之錘上的凱爾坦修士回報。', '護送卡馬羅斯神父至安全處', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13482, 'zhTW', '讓我們離開這裡', '聖光對我微笑。我還沒有死在這場活生生的夢魘中，不過如果我不逃出去，天譴軍團會因為我在「使用」它們在這邊的成果而把我撕成碎片。$B$B但我一個人逃不了，我的孩子，我需要你的幫助，如果我能逃出去就能再次對抗天譴軍團。$B$B你願意幫我逃出去，從天譴軍的屠夫手上救我一命？', '護送卡瑪洛斯神父至安全之處，並向破天者號上的虔誠的亞柏薩倫回報。', '護送卡馬羅斯神父至安全處', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13485 AND `locale` = 'zhTW';
