INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13502, 'zhTW', '滴搭滴，貴族花園籃', '來…帶著這個蛋籃，去收集明亮的彩蛋吧。對了，找到10塊貴族花園巧克力後，就帶蛋籃回來找我。', '收集10個貴族花園巧克力，然後與借來的蛋籃一起歸還。', '', '去找貴族花園商販。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13503 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13503, 'zhTW', '滴搭滴，貴族花園籃', '來，帶著這個蛋籃，去收集明亮的彩蛋吧。找到10塊貴族花園巧克力後，就帶蛋籃回來找我。', '收集10個貴族花園巧克力，然後與借來的蛋籃一起歸還。', '', '去找貴族花園商人。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13524 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13524, 'zhTW', '逃離銀溪鎮', '你……你不是他們的人？快！快把我放出來！$B$B我們必須馬上逃往琥珀松木營地！一旦杜蒙特中尉發現這些傢伙的真面目，就會夷平這個鎮子！', '開啟木籠，幫助聯盟斥候逃出銀溪鎮。抵達琥珀松木營地後向杜蒙特中尉彙報情況。', '', '去灰白之丘找琥珀松木營地的杜蒙特中尉。', '逃出銀溪鎮', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13538 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13538, 'zhTW', '南方破壞工作', '冬握河的南邊有三座哨塔正在吸取堡壘的能量!$B$B摧毀影景哨塔、焰望哨塔或冬際哨塔，然後回來找我。記得，只有攻城載具才能破壞哨塔，所以要確保他們不受部落的攻擊!', '摧毀影景哨塔、焰望哨塔或冬際哨塔，然後向冬握湖的戰術軍官阿布拉米斯回報。', '', '去找冬握堡壘的戰術軍官阿布拉米斯。', '摧毀三座南方塔樓中的其中一座', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13539 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13539, 'zhTW', '推倒哨塔', '或許聯盟已經打到家門口了，但一個真正的戰術家眼光看得更遠。$B$B「攻其不備，出其不意。」$B$B$n，我需要你越過冬握河，去摧毀南方三座哨塔中的一座。我們的術士回報說那些哨塔正在吸收能量，我們可以使用那些能量來強化部隊。$B$B一旦你摧毀了其中一座哨塔，就回來找我。', '摧毀影景哨塔、焰望哨塔或冬際哨塔，然後向冬握湖的戰術軍官科伊瑞斯回報。', '', '去找冬握堡壘的戰術軍官科伊瑞斯。', '摧毀冬握堡壘南方的一座塔樓', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13548, 'zhTW', '糖果桶', '', '這種糖果桶在各地的旅店都有。來吧…拿點糖果！。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13549 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13549, 'zhTW', '驗明正身', '除了德拉克瑞神器之外，我也打算要帶一些祖爾德拉克的野生生物回去贊達拉島。我這裡有公的霜豹和冰掌熊，但是我還需要雌豹跟雌熊!$B$B可惜我的陷捕者在一場意外中喪生了。也許你願意替補他的位置?$B$B不知道你能不能好心地用這個吹箭把那些豹和熊弄睡著，然後拉起牠們的尾巴檢查，替我帶回來一些雌獸。你可以在魯諾克祭壇、奎茲倫祭壇和哈寇亞祭壇的附近找到這些動物。', '辛托加的撰史者托基尼要你對霜豹和冰掌熊使用托基尼的吹箭。把兩種雌獸各3隻帶回來給他。', '', '去找祖爾德拉克的撰史者托基尼。', '已尋回母寒冰豹', '已尋回母冰爪熊', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13556 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13556, 'zhTW', '杜布拉金的蛋', '你好嗎，老兄?能不能幫我個忙啊?巴琪妮需要用一堆迅猛龍蛋為杜布拉金進行獻祭儀式。$B$B你以為我們為什麼沒有被德拉克瑞食人妖宰掉啊?!那是因為杜布拉金在幫助我們!$B$B我們需要你從外頭剛德拉克的樹邊收集那些迅猛龍蛋。有時候迅猛龍也會把蛋帶在身上孵。', '杜布拉金的哈瓦那要你收集12個剛德拉克迅猛龍蛋。', '', '去找祖爾德拉克的哈瓦那。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13559, 'zhTW', '霍迪爾的祭禮', '', '當偉大的霍迪爾還與霜巨人同在時，任何普通的祭禮都配不上祂。也許祂已經不在了，但是我們還是保留了為祂的力量與智慧獻上祭禮的傳統。如果你能夠為這項傳統出一份力，將會大大的提升你的名聲，小$c。', '', '去找祖爾德拉克的立勒賀夫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13571 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13571, 'zhTW', '失而復得', '我本來有個不錯的工作，就是在荒蕪之地的奧達曼挖掘場幹活……直到那些該死的穴居人出現之後。我險些就沒能活著跑出來，而且還什麼也沒來得及拿。在一片慌亂之中，我弄丟了我最重要的財產。我那箱子很難撬開是沒錯，不過你知道麼，那裡滿地都是穴居人！$B$B你去幫我拿回箱子來，我就好好謝你！那個寫著我名字的箱子就在北部大廳的盡頭，你得一路殺進去才行。', '到奧達曼的北部大廳去找到克羅姆·粗臂的箱子，從裡面拿出他的寶貴財產，然後回到鐵爐堡把東西交給他。', '', '回到鐵爐堡把東西交給克羅姆·粗臂', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13592 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13592, 'zhTW', '驍士的實地訓練', '聯賽是一個和你的同伴彼此磨練戰技的機會，但我們不能忘記真正的敵人，天譴軍團，是不會停歇的。當你們光榮地互相切磋技藝時，你也應該要維持你的戰鬥技巧。$B$B前往逝往英雄山谷的西南邊，寇普雷薩北邊的區域。天譴軍團在該地復活陣亡的英雄，並利用他們來對付我方。擊敗這些天譴軍團的爪牙，並且讓你自己隨時準備好應付戰鬥。', '銀白聯賽場地的馬庫斯‧巴羅威爵士要你殺死10名轉化的英雄。', '', '去找寒冰皇冠的馬庫斯‧巴羅威爵士。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13600 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13600, 'zhTW', '足以匹配的武器', '偏偏在這個時候走霉運!$B$B我的聯賽之刃不見了。我聽吟遊詩人說以前旅人會拿凜冬風信子獻給一位孤獨的少女來換取贈禮。這些風信子只長在鐵牆水壩的流冰之上，水壩則在水晶之歌森林的西北邊，與寒冰皇冠交接之處。收集那些花朵然後帶去龍骨荒野東北邊的德拉克瑪湖，靠近祖爾德拉克與灰白之丘的邊界。請和那位孤獨的少女換取一柄合適的利刃。', '把德拉克瑪之刃帶給銀白聯賽場地的傑科布‧亞雷瑞斯元帥。', '', '去找寒冰皇冠的傑科布‧亞雷瑞斯元帥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13603 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13603, 'zhTW', '名劍配勇士', '精心淬鍊磨利的鋼劍如今已經不流行了。其他的戰士都在使用附魔的刀刃，我在這方面可是輸了他們一大截，但還是有機會的。$B$B有個關於灰白之丘少女的古老傳說，傳說她守護著一柄強大的兵刃。據說她受到詛咒被變成了一隻青蛙，所以再也沒有人使用過那柄劍。她就混雜在灰木湖畔那些青蛙之中，在灰木崗哨的東邊。傳說只有一種方法可以破除詛咒，就是一個真心的吻。在親任何東西前先擦上這個護唇膏，$n。否則，你可能會長疣。', '取得灰木古劍，並帶給銀白聯賽場地的傑科布‧亞雷瑞斯元帥。', '', '去找寒冰皇冠的傑科布‧亞雷瑞斯元帥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13604 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13604, 'zhTW', '大資料庫資料圓盤', '這片白金圓盤有著令人驚嘆的對稱性，沒有一點刮痕或瑕疵。清晰的符文銘刻在它的邊緣之上，寫著「大資料庫」。$B$B奧杜亞之中一定有裝置能夠讀取這片圓盤。', '將大資料庫資料圓盤帶到奧杜亞的大資料庫控制臺。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13606 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13606, 'zhTW', '芙蕾雅的符印', '如果我猜得沒錯，芙蕾雅的符印恐怕更麻煩。$B$B根據大資料庫的記錄，符印的精華與她的三個古老僕從相連，亮葉、鐵枒和石木。若是這三個長者受到傷害，就會危急符印的完整性。$B$B但放過這些長者，就表示你們在面對芙蕾雅時，她會更加強大。$B$B我能說什麼呢，$n，這是個兩難的抉擇。', '奧杜亞大資料庫的勘察員多倫要你取得芙蕾雅的符印。想知道更多關於如何取得芙蕾雅的符印，請詢問大資料庫控制臺。', '', '去找奧杜爾的勘察員多倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13607 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13607, 'zhTW', '星穹渾天儀', '聽著，$g小夥子:小姑娘;!艾澤拉斯的命運就取決於此。$B$B我們唯一的機會就是即時趕到星穹渾天儀，找到這個艾爾加隆，並且阻止他把任何訊息傳回去給他的泰坦主人。$B$B找到星穹渾天儀，然後把你找到的所有資料都帶回來。我們或許還有點時間應付艾爾加隆的到來。', '奧杜亞大資料庫的勘察員多倫要你找到通往星穹渾天儀的入口。', '已找到天體天文館的入口', '去找奧杜爾的勘察員多倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13609 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13609, 'zhTW', '霍迪爾的符印', '霍迪爾的符印可不容易取得。你不光是得擊敗霍迪爾本人，你還得在他毀掉存放符印的箱子之前打敗他!$B$B如果需要更多資料可以去大資料庫控制臺查詢。那個東西擁有的資料比全世界所有圖書館加起來都還多!', '奧杜亞大資料庫的勘察員多倫要你取得霍迪爾的符印。想知道更多關於如何取得霍迪爾的符印，請詢問大資料庫控制臺。', '', '去找奧杜爾的勘察員多倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13610 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13610, 'zhTW', '索林姆的符印', '索林姆已經不再是原本那個人了，$n。他受到了一種黑暗的影響。$B$B有一種邪惡的東西偽裝成他死去的妻子，希芙。$B$B你不能讓那個冒充者的法術控制他。要是這樣的話，他符印的位置可能就永遠沒人知道了!$B$B你得要讓他回復理智，而且動作要快。$B$B跟先前一樣，大資料庫控制臺會告訴你所有殘酷的細節...你不會喜歡的。', '奧杜亞大資料庫的勘察員多倫要你取得索林姆的符印。想知道更多關於如何取得索林姆的符印，請詢問大資料庫控制臺。', '', '去找奧杜爾的勘察員多倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13611 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13611, 'zhTW', '彌米倫的符印', '彌米倫真是個聰明的傢伙。他的整個住處都連結在某種自毀裝置上。$B$B要是你想拿到他的符印，你們就得很不幸地與自毀裝置比賽誰的動作快。如果有需要的話，可以向大資料庫控制臺查詢更多資料。', '奧杜亞大資料庫的勘察員多倫要你取得彌米倫的符印。想知道更多關於如何取得彌米倫的符印，請詢問大資料庫控制臺。', '', '去找奧杜爾的勘察員多倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13614 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13614, 'zhTW', '艾爾加隆', '你真的辦到了，$n。把符印帶去給大資料庫控制臺，看你有沒有辦法獲得進入星穹渾天儀的許可。$B$B你最好動作快一點，$g小夥子:小姑娘;。時間緊迫。', '將看守者符印帶給奧杜亞的大資料庫控制臺。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13616 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13616, 'zhTW', '凜冬之鋒', '詛咒那個打斷我配劍的死亡騎士!$B$B在水晶之歌森林南部，俯瞰通往水晶之鉗的出口，你可以找到恆燃領主。殺死它並從屍體上取走永燃餘燼。$B$B然後把餘燼帶到凜風峽灣北部的冬息湖中央，用它來釋放一位冰中少女。她是一柄遠古兵刃的守護者，等待著新的配劍者來釋放她。$B$B證明你足以贏得她長久守護的武器，$n。', '銀白聯賽場地的傑科布‧亞雷瑞斯元帥要你把凜冬之鋒帶給他。', '', '去找寒冰皇冠的傑科布‧亞雷瑞斯元帥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13622 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13622, 'zhTW', '上古史', '這些碎片合在一起能夠拼出一把線條典雅的戰錘。它的構造必然含有某種泰坦特性。$B$B或許能在大資料庫中查詢到相關的資料。', '將破裂的瓦蘭尼珥碎片帶給奧杜亞大資料庫的大資料庫控制臺。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13625 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13625, 'zhTW', '學習駕馭', '聯賽中大部分的比賽都需要比賽者在戰鬥中妥善地駕馭坐騎。為了讓你熟習騎乘作戰，我們在聯賽場地北區的各處都放置了練習用的假人。$B$B到亭閣外的獸欄去，就在主競技場旁邊。從長槍架上拿把長槍，然後騎上奎爾多雷戰駒。讓你自己熟習它們的作戰方式並且擊敗三種不同的訓練假人。', '以戳刺擊中近戰標靶5次，對2個脆弱的遠程標靶使用破盾，對2個脆弱的衝鋒標靶使用衝鋒。然後回到銀白聯賽場地找斥候夏琳卓雅。如果你弄丟了長槍，你可以從任何一個靠近白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的斥候夏琳卓雅。', '對近戰目標使用突刺', '對虛弱的遠程目標使用碎盾', '對虛弱的衝鋒目標使用衝鋒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13627 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13627, 'zhTW', '幫我盜伐一些木材', '過來點。不，別太近。我們不想引起過多的注意，對吧?$B$B大競技場所需要的木材超過了我們的儲備物資，我可不要付錢去買那些從灰白之丘運來的木材。在水晶之歌森林的西部邊緣，靠近巨偉之樹的附近，長了一些年輕的水晶之歌橡木。$B$B正好可以提供我們建築與搭架用的板材。帶上這把斧頭，用它砍倒那些樹再把它們劈成木板，但別讓人看見!', '把12個亂劈的木板帶給銀白聯賽場地的貝索‧爆栓。', '', '去找寒冰皇冠的貝索‧爆栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13629 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13629, 'zhTW', '瓦蘭尼珥，遠古諸王之錘', '大資料庫發現了一種重鑄瓦蘭尼珥碎片的可行辦法:你必須將碎片放入一個名為尤格薩倫生物的實質形體內。$B$B聽來有些艱難，但對於有著如此力量的神器而言，你所冒的風險是值得的。', '當尤格薩倫在施放震耳咆哮時，將破裂的瓦蘭尼珥碎片丟入尤格薩倫的嘴中，然後擊敗尤格薩倫並取回重鑄的遠古諸王之錘。只能在英雄模式下完成，並且至少有一名奧杜亞看守者未提供協助。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13631 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13631, 'zhTW', '情況良好，完美收場', '我們最好得動作快點，$n。我們得從達拉然傳出回覆代碼。$B$B把這個交給羅甯，我在那裡跟你碰頭。', '將回覆代碼Α帶給達拉然的羅甯。', '', '去找水晶歌森林的羅甯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13633 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13633, 'zhTW', '西部荒野的黑騎士？', '我想你應該聽過那個叫做黑騎士參賽者的惱人謠言。據說任何預定要和他比賽戰鬥的人全都遭遇不測。$B$B當然，我們沒有確切的證據，但調查一下這位騎士也無傷大雅。$B$B他自稱來自西部荒野的庫珀家族。你能去一趟西部荒野拜訪他在月溪鎮西邊的住所嗎？看看你能不能找到什麼東西證明他的說詞。', '調查黑騎士的說詞，然後帶著你的發現回到銀白聯賽場地去找十字軍萊達菈。', '', '去找寒冰皇冠的十字軍萊達菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13634 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13634, 'zhTW', '銀松的黑騎士？', '我想你應該聽過那個叫做黑騎士參賽者的惱人謠言。據說任何預定要和他比賽戰鬥的人全都遭遇不測。$B$B當然，我們沒有任何證據，但調查一下這位騎士也無傷大雅。$B$B他自稱來自銀松森林的瓦爾甘牧場。那是一個在洛丹米爾湖西岸的小牧場。你能去拜訪那個牧場讓我們知道他故事的真相嗎？', '調查黑騎士的說詞，然後帶著你的發現回到銀白聯賽場地去找十字軍萊達菈。', '', '去找寒冰皇冠的十字軍萊達菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13641 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13641, 'zhTW', '先知水晶', '既然我們知道黑騎士的故事都不是真的，我們得找出他和那些被謀殺騎士的關連。$B$B我知道一個方法能找出他們是怎麼死的，但需要一些稀有的材料。我們要一顆先知水晶，只有在聚集於夜精靈遺跡的無縛的先知身上才找到，就在水晶之歌森林中部的凋落樹林。找到那些先知，$n，把他們身上的水晶帶給我。', '把先知水晶帶給銀白聯賽場地的十字軍萊達菈。', '', '去找寒冰皇冠的十字軍萊達菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13643 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13643, 'zhTW', '死者的故事', '這顆水晶將會揭露三名聯賽參賽者的死亡真相。帶著它前往聯賽場地東邊的墓地，在溫德爾‧貝爾弗爵士、洛瑞安‧日炎和康歐‧鐵握的墳墓前使用它。$B$B如果這些人真的遭到謀殺，並且與黑騎士有關，那我們一定得要阻止他再次行動。仔細留意水晶的訊息，$n，我們一定要確認這些死亡是不是意外。', '在溫德爾‧貝爾弗爵士、洛瑞安‧日炎和康歐‧鐵握的墳墓前使用先知水晶，找出他們的死因，然後向十字軍萊達菈回報。', '', '去找寒冰皇冠的十字軍萊達菈。', '已調查溫德爾·巴爾弗爵士之死', '已調查洛里安·日光烈焰之死', '已調查科納爾·鐵拳之死', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13649, 'zhTW', '賈斯汀的趣味測試', '喂！看起來啤酒難不倒你。但你能好好使用啤酒杯嗎？$B$B黑鐵矮人要回來報復，毀掉我們的節慶。拿酒杯丟他們是最好的阻止方法，但首先，讓我們瞧瞧你能不能在老S.T.O.U.T.這裡丟中一個。$B$B這很簡單，拿起一杯免費招待的啤酒節樣品，然後幹了它。接下來要確定你面對著S.T.O.U.T.。等你丟中他5次之後再告訴我。', '使用免費招待的啤酒節樣品並丟中S.T.O.U.T.5次，然後和博克西·栓旋者談談。', '', 'Return to [PH] Justin\'s Test NPC.', 'S.T.O.U.T. Hit', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13654 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13654, 'zhTW', '怪異的侍從', '每天，黑騎士的侍從瑪洛裡克都會扛著斧子，大搖大擺地離開營地，轉至晶歌森林。他必然是想讓我們相信他是出去砍柴了，但每次他都只帶回幾根小樹枝。$B$B他經常到暮色之鏡西南方的廢墟去。也許他的騎士領主的確是讓他去辦什麼事情，但即使如此，他在那裡待的時間也太長了些。$B$B想點什麼辦法吸引他的注意力，或者把他打昏，然後搜搜他身上的東西。如果他真的在打什麼鬼主意，我們可不能矇在鼓裡。', '從一個骷髏伐木工身上取下一根大腿骨，用它打昏瑪洛裡克。在瑪洛裡克身上搜查一番，找到證據後向銀色比武場的十字軍戰士萊達拉報告。', '', '去寒冰皇冠找黑色觀察站的十字軍戰士歐爾拉金·薩利斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13662, 'zhTW', '獲得信任', '', '', '', '去找灼熱峽谷的大鐵匠博恩奈特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13663, 'zhTW', '黑騎士的命令', '我們一定要查出誰派黑騎士來參加聯賽，他的主人又能從殺死參賽者中獲得什麼好處。$B$B祈倫托表示願意在這件事情上提供協助。$B$B帶著這個附魔韁轡到黑騎士在聯賽場地東側的營地，用它來控制黑騎士的獅鷲獸。韁轡的魔法會強迫獅鷲獸帶你到他主人的所在。仔細搜索然後把你發現的東西給帶回來。', '使用附魔韁轡控制黑騎士的獅鷲獸，並騎著牠前往目的地。一旦你抵達後，找到失竊的聯賽邀請函和黑騎士的命令，然後把這些東西帶給銀白聯賽場地的十字軍萊達菈。', '', '去找寒冰皇冠的十字軍萊達菈。', '已取得黑騎士的獅鷲', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13664, 'zhTW', '黑騎士之死', '我們必須讓黑騎士的陰謀畫上句點，並且讓那些反對我們的人明白，我們不會坐視並允許我們的勇士被謀殺。現在，他將察覺有人擋住了他的路。在光天化日之下挑戰他，他就不能拒絕或在黑暗中進行暗殺，$n。$B$B用我的銀白戰騎出賽。牠就拴在獸欄。$B$B和勇士競技場的侍從凱文談談。侍從會召喚黑騎士前來戰鬥，但你要讓為他的罪行付出代價。', '擊敗黑騎士然後與銀白聯賽場地的十字軍萊達菈談話。', '', '去找寒冰皇冠的十字軍萊達菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13665, 'zhTW', '技擊大賽', '技擊大賽是聯賽項目中最重要的一項比賽。暴風城的百姓崇拜他們的騎士，並且希望我們能在技擊賽中獲勝。因此，所以每個人都磨練戰技等著對抗其他聯盟城市的驍士。$B$B我也建議你這麼做。$B$B到亭閣外的獸欄去，從長槍架上拿把長槍，然後騎上圈養的艾爾文戰駒，然後挑戰其他的驍士。他們就在我們帳篷外的聯盟驍士競技場。', '帶3個驍士印記交給銀白聯賽場地的約瑟夫‧霍雷上尉。如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的約瑟夫‧霍雷上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13666, 'zhTW', '名劍配勇士', '有些勇士相信一把來自北裂境的上古武器可以在聯賽中帶來好運。而我已經同意要幫他們找到這些武器。$B$B有個關於灰白之丘少女的古老傳說，傳說她守護著一柄強大的兵刃。據說她受到詛咒被變成了一隻青蛙，所以再也沒有人使用過那柄劍。她就混雜在灰木湖畔那些青蛙之中，在灰木崗哨的東邊。傳說只有一種方法可以破除詛咒，就是一個真心的吻。在親任何東西前先擦上這個護唇膏，$n。否則，你可能會長疣。', '取得灰木古劍，並帶給銀白聯賽場地的秘法師泰利斯。', '', '去找寒冰皇冠的秘法師泰利斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13669 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13669, 'zhTW', '足以匹配的武器', '我們的勇者偏好北裂境這裡所生產的上古武器。$B$B我曾聽聞吟遊詩人講述旅行者將凜冬風信子獻給孤獨的少女，以換取回報之禮的故事，那些風信子只長在鐵牆水壩的流冰之上，就在水晶之歌森林的西北邊，與寒冰皇冠交接之處。收集那些花朵然後帶去德拉克瑪湖的燈之環，位於龍骨荒野東北邊，靠近祖爾德拉克與灰白之丘。向孤獨的少女要一把足以匹配的劍刃。', '將德拉克瑪之刃帶給銀白聯賽場地的秘法師泰利斯。', '', '去找寒冰皇冠的秘法師泰利斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13670 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13670, 'zhTW', '凜冬之鋒', '鐵爐堡大勇士的侍從告訴我一個有趣的故事。$B$B在水晶之歌森林南部，俯瞰通往水晶之鉗的出口，你可以找到恆燃領主。殺死它並從屍體上取走永燃餘燼。$B$B然後把餘燼帶到凜風峽灣北部的冬息湖中央，用它來釋放一位冰中少女。她是一柄遠古兵刃的守護者，等待著新的配劍者來釋放她。$B$B證明你足以贏得她長久守護的武器，$n。', '銀白聯賽場地的秘法師泰利斯要你把凜冬之鋒帶給他。', '', '去找寒冰皇冠的秘法師泰利斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13671 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13671, 'zhTW', '實地訓練', '聯賽是一個和你的同伴彼此磨練戰技的機會，但我們不能忘記真正的敵人，天譴軍團，是不會停歇的。當你們光榮地互相切磋技藝時，你也應該要維持你的戰鬥技巧。向我們證明你能光榮和勇敢地面對天譴軍團，並且贏得參加聯賽的資格。$B$B前往寒冰皇冠，殺死任何目光所及的天譴軍。但要避開轟炸地，他們在那裡的數量太多了。', '銀白聯賽場地的阿凡瑞斯‧迅擊要你殺死8個寒冰皇冠天譴軍。你可以殺死在轟炸地以外的任何天譴軍。', '', '去找寒冰皇冠的阿凡瑞斯‧迅擊。', '寒冰皇冠的天災已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13672 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13672, 'zhTW', '準備挑戰', '當你一邊磨練志士的技巧，你也可以接受志士的挑戰。挑戰將會考驗你騎乘戰鬥的技巧，並且判別你是否準備好成為一名驍士。如果你通過挑戰，你就可以加入你主城的代表隊，成為一名驍士。$B$B等你準備好開始挑戰，可以回來找我。', '帶15個志士徽印給銀白聯賽的秘法師泰利斯，表示你準備好接受志士的挑戰。', '', '去找寒冰皇冠的秘法師泰利斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13673 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13673, 'zhTW', '名劍配勇士', '有些勇士相信一把來自北裂境的上古武器可以在聯賽中帶來好運。而我已經同意要幫他們找到這些武器。$B$B有個關於灰白之丘少女的古老傳說，傳說她守護著一柄強大的兵刃。據說她受到詛咒被變成了一隻青蛙，所以再也沒有人使用過那柄劍。她就混雜在灰木湖畔那些青蛙之中，在灰木崗哨的東邊。傳說只有一種方法可以破除詛咒，就是一個真心的吻。在親任何東西前先擦上這個護唇膏，$n。否則，你可能會長疣。', '取得灰木古劍，並帶給銀白聯賽場地的博學者艾狄恩‧日谷。', '', '去找寒冰皇冠的博學者艾狄恩‧日谷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13674 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13674, 'zhTW', '足以匹配的武器', '我們的勇者偏好北裂境這裡所生產的上古武器。$B$B我曾聽聞吟遊詩人講述旅行者將凜冬風信子獻給孤獨的少女，以換取回報之禮的故事，那些風信子只長在鐵牆水壩的流冰之上，就在水晶之歌森林的西北邊，與寒冰皇冠交接之處。收集那些花朵然後帶去德拉克瑪湖的燈之環，位於龍骨荒野東北邊，靠近祖爾德拉克與灰白之丘。向孤獨的少女要一把足以匹配的劍刃。', '將德拉克瑪之刃帶給銀白聯賽場地的博學者艾狄恩‧日谷。', '', '去找寒冰皇冠的博學者艾狄恩‧日谷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13675 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13675, 'zhTW', '凜冬之鋒', '有位奧格瑪驍士告訴我一個有趣的故事。$B$B在水晶之歌森林南部，俯瞰通往水晶之鉗的出口，你可以找到恆燃領主。殺死他並從屍體上取走永燃餘燼。$B$B然後把餘燼帶到凜風峽灣北部的冬息湖中央，用它來釋放一位冰中少女。她是一柄遠古兵刃的守護者，等待著新的配劍者來釋放她。$B$B證明你足以贏得她長久守護的武器，$n。', '銀白聯賽場地的博學者艾狄恩‧日谷要你把凜冬之鋒帶給他。', '', '去找寒冰皇冠的博學者艾狄恩‧日谷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13676 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13676, 'zhTW', '實地訓練', '聯賽是一個和你的同伴彼此磨練戰技的機會，但我們不能忘記真正的敵人，天譴軍團，是不會停歇的。當你們光榮地互相切磋技藝時，你也應該要維持你的戰鬥技巧。向我們證明你能光榮和勇敢地面對天譴軍團，並且贏得參加聯賽的資格。$B$B前往寒冰皇冠，殺死任何目光所及的天譴軍。但要避開轟炸地，他們在那裡的數量太多了。', '銀白聯賽場地的艾瑪瑞爾‧日誓要你殺死8個寒冰皇冠天譴軍。你可以殺死寒冰皇冠中除了轟炸地以外，任何地方的天譴軍。', '', '去找寒冰皇冠的艾瑪瑞爾‧日誓。', '寒冰皇冠的天災已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13677 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13677, 'zhTW', '學習駕馭', '聯賽中大部分的比賽都需要比賽者在戰鬥中妥善地駕馭坐騎。為了讓你熟習騎乘作戰，我們在聯賽場地北區的各處都放置了練習用的假人。$B$B到亭閣外的獸欄去，就在主競技場旁邊。從長槍架上拿把長槍，然後騎上奪日者陸行鷹。讓你自己熟習它的作戰方式並且用它擊敗三種不同的訓練假人。', '以戳刺擊中近戰標靶5次，對2個脆弱的遠程標靶使用破盾，對2個脆弱的衝鋒標靶使用衝鋒。然後回到銀白聯賽場地找加拉西雅‧明曦。如果你弄丟了長槍，你可以從任何一個靠近獸欄或奪日者亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的加拉西雅‧明曦。', '對近戰目標使用突刺', '對虛弱的遠程目標使用碎盾', '對虛弱的衝鋒目標使用衝鋒', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13678 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13678, 'zhTW', '準備挑戰', '當你一邊磨練志士的技巧，你也可以接受志士的挑戰。挑戰將會考驗你騎乘戰鬥的技巧，並且判別你是否準備好成為一名驍士。如果你通過挑戰，你就可以加入你主城的代表隊，成為一名驍士。$B$B等你準備好開始挑戰，可以回來找我。', '帶15個志士徽印給銀白聯賽場地的博學者艾狄恩‧日谷，表示你準備好接受志士的挑戰。', '', '去找寒冰皇冠的博學者艾狄恩‧日谷。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13679 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13679, 'zhTW', '志士的挑戰', '你是一位認真鍛鍊的志士，$n，該是時候找個經驗老到的對手來測試你的騎乘作戰技巧了。$B$B裝備你的長槍，到亭閣外的獸欄去騎上奎爾多雷戰駒。$B$B你可以在聯賽場地北部的志士競技場中找到侍從大衛。他會確認你已經準備好戰鬥，並且召喚你的對手。$B$B祝好運，$n。願你的馬匹穩健而你的攻勢凌厲。', '和侍從大衛交談以召喚你的對手。一旦你擊敗銀白驍士，回去銀白聯賽場地找秘法師泰利斯。如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的秘法師泰利斯。', '已擊敗銀色勇士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13680 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13680, 'zhTW', '志士的挑戰', '你是一位認真鍛鍊的志士，$n，該是時候找個經驗老到的對手來測試你的騎乘作戰技巧了。$B$B裝備你的長槍，到亭閣外的獸欄去騎上奪日者陸行鷹。$B$B在聯賽場地北部的志士競技場，有個人類小孩叫做侍從大衛。他會確認你已經準備好戰鬥，並且召喚你的對手。$B$B祝好運，$n。願你的坐騎穩健而你的攻勢凌厲。', '和侍從大衛交談以召喚你的對手。一旦你擊敗銀白驍士，回去銀白聯賽場地找博學者艾狄恩‧日谷。', '', '去找寒冰皇冠的博學者艾狄恩‧日谷。', '已擊敗銀色勇士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13681 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13681, 'zhTW', '奧杜亞石塊的碎片', '別說你不知道，要替這項工程準備石材真是場惡夢!許多安全的遺跡裡有成噸成噸的石頭，那些神聖到腦子有問題的聖騎士卻不肯用。說什麼那是『無價的瑰寶』。$B$B總之，唉唉叫也無濟於事。在風暴群山的足跡冷原或發明者圖書館的泰坦遺跡中，有著成山成噸的石頭。帶上我的，呃，『鑿子』，你可以把那些大石塊打碎成可用的碎片。', '帶15個小型石塊堆給銀白聯賽場地的波索‧爆栓。', '', '去找寒冰皇冠的波索‧爆栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13682 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13682, 'zhTW', '來自上空的威脅', '自從你揭發了詛咒神教的潛伏者之後，大領主提里奧‧弗丁就加倍了守衛的人數。他認為他們不可能只因為黑騎士被擊敗就停止行動。$B$B根據我們的天爪斥候回報，有一隻叫做寒冽之喉的冰霜巨龍率領了一批神教突襲隊。如果我們沒有攔截他們，聯賽就會受到他們的攻擊。斥候回報看見寒冽之喉就在西南方，在鐵牆壁壘和奧多薩之間的地區飛行。', '銀白聯賽的『純淨者』埃卓克要你擊敗寒冽之喉和3個教徒投彈手。', '', '去找寒冰皇冠的『純淨者』埃卓克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13686 AND `locale` = 'zhTW';
