INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13692, 'zhTW', '劍與海', '我的劍掉進海裡了。幫我找回來!', '水晶之歌森林的老人巴洛要你幫他找回騎士位階之劍。', '', '去找泰羅卡森林的老人巴洛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13697 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13697, 'zhTW', '驍士的任務', '在你的驍士訓練中，你有機會與其他城市代表隊的驍士互相切磋。儘管驍士的戰鬥不算是標準賽事的一部份，你還是可以從中學到關於對手的戰鬥方式與弱點等珍貴的經驗。$B$B驍士是十分活躍的一群，帶著榮譽戰鬥吧。$B$B持續地以驍士的身分進行訓練，直到你的能力足以擊敗你最強的對手，然後帶著你所贏得的徽印來找我。', '帶25個驍士徽印給銀白聯賽場地的『碎顱者』莫克拉。', '', '去找寒冰皇冠的『碎顱者』莫克拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13699 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13699, 'zhTW', '驍士的挑戰', '你幾乎已具備代表暴風城參加技擊大賽的資格了。為了要證明你足以加入城市代表隊名單中，你必須要擊敗一位銀白十字軍的勇士。$B$B前往亭閣外的獸欄，裝備你的長槍並乘上坐騎。到聯賽場地西側的銀白驍士競技場找侍從丹尼。等你準備好之後，侍從會叫出你的對手。$B$B等戰鬥結束之後，我們再來談一談結果。', '和侍從丹尼談談以召喚你的對手。一旦你擊敗銀白勇士，回到銀白聯賽場地去找傑科布‧亞雷瑞斯元帥。如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的傑科布‧亞雷瑞斯元帥。', '已擊敗銀色冠軍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13700 AND `locale` = 'zhTW';
