INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13713, 'zhTW', '驍士的挑戰', '你幾乎已具備代表鐵爐堡參加技擊大賽的資格了。為了要證明你足以加入城市代表隊名單中，你必須要擊敗一位銀白十字軍的勇士。$B$B前往亭閣外的獸欄，裝備你的長槍並乘上坐騎。到聯賽場地西側的銀白驍士競技場找侍從丹尼。等你準備好之後，侍從會叫出你的對手。$B$B等戰鬥結束之後，我們再來談一談結果。', '和侍從丹尼談談以召喚你的對手。一旦你擊敗銀白勇士，回到銀白聯賽場地去找菈娜‧頑錘。$B$B如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的拉娜·硬錘。', '擊敗銀白勇士', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13714 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13714, 'zhTW', '驍士的任務', '在你的驍士訓練中，你有機會與其他城市代表隊的驍士互相切磋。儘管驍士的戰鬥不算是標準賽事的一部份，你還是可以從中學到關於對手的戰鬥方式與弱點等珍貴的經驗。$B$B驍士十分活躍，他們彼此會為了榮譽而爭鬥。$B$B持續地以驍士的身分進行訓練，直到你的能力足以擊敗你最強的對手，然後帶著你所贏得的徽印來找我。', '帶25個驍士徽印給銀白聯賽場地的菈娜‧頑錘。', '', '去找寒冰皇冠的菈娜‧頑錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13715 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13715, 'zhTW', '驍士的任務', '在你的驍士訓練中，你有機會與其他城市代表隊的驍士互相切磋。儘管驍士的戰鬥不算是標準賽事的一部份，你還是可以從中學到關於對手的戰鬥方式與弱點等珍貴的經驗。$B$B驍士十分活躍，他們彼此會為了榮譽而爭鬥。$B$B持續地以驍士的身分進行訓練，直到你的能力足以擊敗你最強的對手，然後帶著你所贏得的徽印來找我。', '帶25個驍士徽印給銀白聯賽場地的安布羅斯‧拴炫。', '', '去找寒冰皇冠的安布羅斯‧拴炫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13716 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13716, 'zhTW', '驍士的任務', '在你的驍士訓練中，你有機會與其他城市代表隊的驍士互相切磋。儘管驍士的戰鬥不算是標準賽事的一部份，你還是可以從中學到關於對手的戰鬥方式與弱點等珍貴的經驗。$B$B驍士十分活躍，他們彼此會為了榮譽而爭鬥。$B$B持續地以驍士的身分進行訓練，直到你的能力足以擊敗你最強的對手，然後帶著你所贏得的徽印來找我。', '帶25個驍士徽印給銀白聯賽場地的克羅索斯。', '', '去找寒冰皇冠的克羅索斯。', '', '', '', '', 0);
