INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13723, 'zhTW', '驍士的挑戰', '你幾乎已具備代表諾姆瑞根參加技擊大賽的資格了。為了要證明你足以加入城市代表隊名單中，你必須要擊敗一位銀白十字軍的勇士。$B$B前往亭閣外的獸欄，裝備你的長槍並乘上坐騎。到場地西側的銀白驍士競技場找侍從丹尼交談。等你準備好之後，侍從會叫出你的對手。$B$B等戰鬥結束之後，我們再來談一談結果。', '和侍從丹尼談談以召喚你的對手。一旦你擊敗銀白勇士，回到銀白聯賽場地去找安布羅斯‧拴炫。如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的安布羅斯‧拴炫。', '已擊敗銀色冠軍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13724 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13724, 'zhTW', '驍士的挑戰', '你幾乎已具備代表艾克索達參加技擊大賽的資格了。為了要證明你足以加入城市代表隊名單中，你必須要擊敗一位銀白十字軍的勇士。$B$B前往亭閣外的獸欄，裝備你的長槍並乘上坐騎。到場地西側的銀白驍士競技場找侍從丹尼交談。等你準備好之後，侍從會叫出你的對手。$B$B等戰鬥結束之後，我們再來談一談結果。', '和侍從丹尼談談以召喚你的對手。一旦你擊敗銀白勇士，回到銀白聯賽場地去找克羅索斯。如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的克羅索斯。', '已擊敗銀色冠軍', '', '', '', 0);
