INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13741, 'zhTW', '名劍配勇士', '精心淬鍊磨利的鋼劍如今已經不流行了。其他的戰士都在使用附魔的刀刃，我在這方面可是輸了他們一大截，但還是有機會的。$B$B有個關於灰白之丘少女的古老傳說，傳說她守護著一柄強大的兵刃。據說她受到詛咒被變成了一隻青蛙，所以再也沒有人使用過那柄劍。她就混雜在灰木湖畔那些青蛙之中，在灰木崗哨的東邊。傳說只有一種方法可以破除詛咒，就是一個真心的吻。在親任何東西前先擦上這個護唇膏，$n。否則，你可能會長疣。', '取得灰木古劍，並帶給銀白聯賽場地的菈娜‧頑錘。', '', '去找寒冰皇冠的菈娜‧頑錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13742 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13742, 'zhTW', '足以匹配的武器', '偏偏在這個時候走霉運!$B$B我的聯賽之刃不見了。我聽吟遊詩人說以前旅人會拿凜冬風信子獻給一位孤獨的少女來換取贈禮。這些風信子只長在鐵牆水壩的流冰之上，水壩則在水晶之歌森林的西北邊，與寒冰皇冠交接之處。收集那些花朵然後帶去龍骨荒野東北邊的德拉克瑪湖，靠近祖爾德拉克與灰白之丘的邊界。請和那位孤獨的少女換取一柄合適的利刃。', '將德拉克瑪之刃帶給銀白聯賽場地的菈娜‧頑錘。', '', '去找寒冰皇冠的菈娜‧頑錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13743 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13743, 'zhTW', '凜冬之鋒', '詛咒那個打斷我配劍的死亡騎士!$B$B在水晶之歌森林南部，俯瞰通往水晶之鉗的出口，你可以找到恆燃領主。殺死它並從屍體上取走永燃餘燼。$B$B然後把餘燼帶到凜風峽灣北部的冬息湖中央，用它來釋放一位冰中少女。她是一柄遠古兵刃的守護者，等待著新的配劍者來釋放她。$B$B證明你足以贏得她長久守護的武器，$n。', '銀白聯賽場地的菈娜‧頑錘要你把凜冬之鋒帶給她。', '', '去找寒冰皇冠的菈娜‧頑錘。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13744 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13744, 'zhTW', '驍士的實地訓練', '聯賽是一個和你的同伴彼此磨練戰技的機會，但我們不能忘記真正的敵人，天譴軍團，是不會停歇的。當你們光榮地互相切磋技藝時，你也應該要維持你的戰鬥技巧。$B$B前往逝往英雄山谷的西南邊，寇普雷薩北邊的區域。天譴軍團在該地復活陣亡的英雄，並利用他們來對付我方。擊敗這些天譴軍團的爪牙，並且讓你自己隨時準備好應付戰鬥。', '銀白聯賽場地的羅洛‧穩擊要你殺死10名轉化的英雄。', '', '去找寒冰皇冠的羅洛‧穩擊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13745 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13745, 'zhTW', '技擊大賽', '技擊大賽是聯賽項目中最重要的一項比賽。鐵爐堡的百姓都渴望著我們獲勝的消息。因此，每個人都磨練戰技等著對抗其他聯盟主城的驍士。$B$B我也建議你這麼做。在競技場練習的驍士就在我們的帳篷外。裝備你的長槍，到亭閣外的獸欄去，騎上圈養的鐵爐堡山羊，然後挑戰其他的聯盟驍士。', '帶3個驍士印記交給銀白聯賽場地的卡拉菈‧跌酒。如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的卡拉菈‧跌酒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13746 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13746, 'zhTW', '名劍配勇士', '精心淬鍊磨利的鋼劍如今已經不流行了。其他的戰士都在使用附魔的刀刃，我在這方面可是輸了他們一大截，但還是有機會的。$B$B有個關於灰白之丘少女的古老傳說，傳說她守護著一柄強大的兵刃。據說她受到詛咒被變成了一隻青蛙，所以再也沒有人使用過那柄劍。她就混雜在灰木湖畔那些青蛙之中，在灰木崗哨的東邊。傳說只有一種方法可以破除詛咒，就是一個真心的吻。在親任何東西前先擦上這個護唇膏，$n。否則，你可能會長疣。', '取得灰木古劍，並帶給銀白聯賽場地的安布羅斯‧拴炫。', '', '去找寒冰皇冠的安布羅斯‧拴炫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13747 AND `locale` = 'zhTW';
