INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13749, 'zhTW', '驍士的實地訓練', '聯賽是一個和你的同伴彼此磨練戰技的機會，但我們不能忘記真正的敵人，天譴軍團，是不會停歇的。當你們光榮地互相切磋技藝時，你也應該要維持你的戰鬥技巧。$B$B前往逝往英雄山谷的西南邊，寇普雷薩北邊的區域。天譴軍團在該地復活陣亡的英雄，並利用他們來對付我方。擊敗這些天譴軍團的爪牙，並且讓你自己隨時準備好應付戰鬥。', '銀白聯賽場地的提金‧輪扳要你殺死10名轉化的英雄。', '', '去找寒冰皇冠的提金‧輪扳。', '', '', '', '', 0);
