INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13750, 'zhTW', '技擊大賽', '技擊大賽是聯賽項目中最重要的一項比賽。我們知道每個人都期待著我們在比賽中勝出，而我也不希望讓他們失望。因此，每個人都磨練戰技等著對抗其他聯盟主城的驍士。$B$B我也建議你這麼做。$B$B裝備你的長槍，到亭閣外的獸欄去，然後騎上圈養的渦輪陸行鳥，然後挑戰其他的驍士。他們就在我們帳篷外的聯盟驍士競技場。', '帶3個驍士印記交給銀白聯賽場地的佛立金‧輪扳。如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的佛立金‧輪扳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13752 AND `locale` = 'zhTW';
