INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13778, 'zhTW', '名劍配勇士', '我聽說聯盟的勇士正在替他們的戰士尋找一把遠古兵刃。我們可不能讓他們佔有這樣的優勢$B$B有個關於灰白之丘少女的古老傳說，傳說她守護著一柄強大的兵刃。據說她受到詛咒被變成了一隻青蛙，所以再也沒有人使用過那柄劍。她就在灰木湖畔混在那些青蛙之中，在灰木崗哨的東邊。傳說只有一種方法可以破除詛咒，就是一個真心的吻。在親任何東西前先擦上這個護唇膏，$n。否則，你可能會感染疣症。', '取得灰木古劍，並帶給銀白聯賽場地的亡靈哨兵威瑟瑞。', '', '去找寒冰皇冠的亡靈哨兵威瑟瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13779 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13779, 'zhTW', '足以匹配的武器', '偏偏在這個時候走霉運!$B$B我的聯賽之刃不見了。我聽吟遊詩人說以前旅人會拿凜冬風信子獻給一位孤獨的少女來換取贈禮。這些風信子只長在鐵牆水壩的流冰之上，水壩則在水晶之歌森林的西北邊，與寒冰皇冠交接之處。收集那些花朵然後帶去龍骨荒野東北邊的德拉克瑪湖，靠近祖爾德拉克與灰白之丘的邊界。請和那位孤獨的少女換取一柄合適的利刃。', '將德拉克瑪之刃帶給銀白聯賽場地的亡靈哨兵威瑟瑞。', '', '去找寒冰皇冠的亡靈哨兵威瑟瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13780 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13780, 'zhTW', '凜冬之鋒', '詛咒那個打斷我配劍的死亡騎士!$B$B在水晶之歌森林南部，俯瞰通往水晶之鉗的出口，你可以找到恆燃領主。殺死他並從屍體上取走永燃餘燼。$B$B然後把餘燼帶到凜風峽灣北部的冬息湖中央，用它來釋放一位冰中少女。她是一柄遠古兵刃的守護者，等待著新的配劍者來釋放她。$B$B證明你足以贏得她長久守護的武器，$n。', '銀白聯賽場地的亡靈哨兵威瑟瑞要你把凜冬之鋒帶給他。', '', '去找寒冰皇冠的亡靈哨兵威瑟瑞。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13781 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13781, 'zhTW', '驍士的實地訓練', '聯賽是一個和你的同伴彼此磨練戰技的機會，但我們不能忘記真正的敵人，天譴軍團，是不會停歇的。當你們光榮地互相切磋技藝時，你也應該要維持你的戰鬥技巧。$B$B前往逝往英雄山谷的西南邊，寇普雷薩北邊的區域。天譴軍團在該地復活陣亡的英雄，並利用它們來對付我方。擊敗這些天譴軍團的爪牙，並且讓你自己隨時準備好應付戰鬥。', '銀白聯賽場地的薩拉‧喬克要你殺死10名轉化的英雄。', '', '去找寒冰皇冠的薩拉‧喬克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13782 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13782, 'zhTW', '技擊大賽', '技擊大賽是聯賽項目中最重要的一項比賽。獲勝並不容易，但我有信心我們終將得勝。你必須要持續和你的坐騎一起練習，直到你們合作無間。$B$B這樣有助於你應付聯賽戰鬥的嚴苛情況。$B$BB裝備你的長槍，到亭閣外的獸欄去，然後騎上圈養的被遺忘者戰馬，挑戰其他的驍士。他們就在我們帳篷外的部落驍士競技場。', '帶3個驍士印記交給銀白聯賽場地的管理者德瑞齊。如果你弄丟了長槍，你可以從任何一個靠近獸欄或奪日者亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的管理者德瑞齊。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13783 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13783, 'zhTW', '名劍配勇士', '我聽說聯盟的勇士正在替他們的戰士尋找一把遠古兵刃。我們可不能讓他們佔有這樣的優勢$B$B有個關於灰白之丘少女的古老傳說，傳說她守護著一柄強大的兵刃。據說她受到詛咒被變成了一隻青蛙，所以再也沒有人使用過那柄劍。她就在灰木湖畔混在那些青蛙之中，在灰木崗哨的東邊。傳說只有一種方法可以破除詛咒，就是一個真心的吻。在親任何東西前先擦上這個護唇膏，$n。否則，你可能會感染疣症。', '取得灰木古劍，並帶給銀白聯賽場地的艾瑞西雅‧曦詠。', '', '去找寒冰皇冠的艾瑞西雅‧曦詠。', '', '', '', '', 0);
