INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13787, 'zhTW', '技擊大賽', '技擊大賽是聯賽項目中最重要的一項比賽。獲勝並不容易，但我有信心我們終將得勝。你必須要持續和你的坐騎一起練習，直到你們合作無間。$B$B這樣有助於你應付聯賽戰鬥的嚴苛情況。$B$B裝備你的長槍，到亭閣外的獸欄去，然後騎上圈養的銀月城陸行鷹，挑戰其他的驍士。他們就在我們帳篷外的部落驍士競技場。', '帶3個驍士印記交給銀白聯賽場地的安妮拉‧修倫。如果你弄丟了長槍，你可以從任何一個靠近白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的安妮拉‧修倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13788 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13788, 'zhTW', '來自上空的威脅', '自從你揭發了詛咒神教的潛伏者之後，銀白十字軍就加倍了守衛的人數。他們認為詛咒神教不可能只因為黑騎士被擊敗就停止行動。$B$B根據銀白十字軍的斥候回報，有一隻叫做寒冽之喉的冰霜巨龍率領了一批神教突襲隊。如果我們沒有攔截他們，聯賽就會受到他們的攻擊。斥候回報看見寒冽之喉就在西南方，在鐵牆壁壘和奧多薩之間的地區飛行。', '銀白聯賽的克羅科·天譴剋星要你擊敗寒冽之喉和3個教徒投彈手。', '', '去找寒冰皇冠的克羅科‧天譴剋星。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13789 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13789, 'zhTW', '和敵人一戰', '大競技場位在這個世界最危險的地方，$n。這片土地是我們用鮮血和苦痛從天譴軍手中換來的，但敵人持續反擊，他們部隊的數量彷彿無窮無盡。但更糟糕的是，這批不死大軍還有著凡人支持者的協助，詛咒神教。$B$B深入寒冰皇冠，殺死你所遇到的任何一個教徒。', '銀白聯賽場地的瑟利安‧破曉要你殺死15名詛咒神教的成員。你可以在寒冰皇冠任何一個地方殺死神教成員。', '', '去找寒冰皇冠的瑟利安‧破曉。', '詛咒教派成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13790 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13790, 'zhTW', '勇士們', '身為一名勇士，你精通騎乘作戰的技巧，擊敗了各種層級的挑戰者。當聯賽開始時，那些被你擊敗的人將會加倍努力，想要一雪前恥。$B$B繼續和勇士競技場的戰士練習將會是個明智之舉。裝備你的長槍，到聯賽場地南邊的獸欄去。然後跨上你的坐騎，面對其他的勇士吧。', '帶4個勇士印記交給銀白聯賽場地的露莉。如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的露莉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13791 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13791, 'zhTW', '和敵人一戰', '當我們把注意力放在這些模擬戰中，要知道我們真正的敵人依舊環伺在四周。銀白十字軍想要透過競賽找出最優秀的戰士，但我們也能知道誰從戰場上回來。讓那些聖騎士知道，就算是在聯賽準備期間，我們也願意對抗詛咒神教。$B$B前往寒冰皇冠，殺死你所遇到的任何一個教徒。他們在奧多薩和亡頌者之望人數眾多。', '銀白聯賽場地的『放血者』佐爾必要你殺死15名詛咒神教的成員。你可以在寒冰皇冠任何一個地方殺死神教成員。', '', '去找寒冰皇冠的『放血者』佐爾必。', '詛咒教派成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13793 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13793, 'zhTW', '勇士們', '身為一名勇士，你精通騎乘作戰的技巧，擊敗了各種層級的挑戰者。你確信你會對上你先前所擊敗的人。$B$B你應該持續鍛鍊自己的技巧並且學習敵方的弱點。代表各大城市的勇士們就在獸欄附近的勇士競技場。到獸欄去，裝備你的長槍，然後跨上你的坐騎，面對其他的勇士吧。', '帶4個勇士印記交給銀白聯賽場地的伊黎芮‧夜暮。如果你弄丟了長槍，你可以從任何一個靠近獸欄或白銀誓盟亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的伊黎芮‧夜暮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13807 AND `locale` = 'zhTW';
