INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13811, 'zhTW', '勇士們', '身為一名勇士，你精通騎乘作戰的技巧，擊敗了各種層級的挑戰者。當聯賽開始時，那些被你擊敗的人將會加倍努力，想要一雪前恥。$B$B你應該持續鍛鍊自己的技巧並且學習敵方的弱點。代表各大城市的勇士們就在獸欄附近的勇士競技場。裝備你的長槍，然後跨上你的坐騎，面對其他的勇士吧。', '帶4個勇士印記交給銀白聯賽場地的露莉。如果你弄丟了長槍，你可以從任何一個靠近獸欄或奪日者亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的露莉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13812 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13812, 'zhTW', '來自上空的威脅', '自從你揭發了詛咒神教的潛伏者之後，銀白十字軍就加倍了守衛的人數。他們認為詛咒神教不可能只因為黑騎士被擊敗就停止行動。$B$B根據銀白十字軍的斥候回報，有一隻叫做寒冽之喉的冰霜巨龍率領了一批神教突襲隊。如果我們沒有攔截他們，聯賽就會受到他們的攻擊。斥候回報看見寒冽之喉就在西南方，在鐵牆壁壘和奧多薩之間的地區飛行。', '銀白聯賽的克羅科‧天譴剋星要你擊敗寒冽之喉和3個教徒投彈手。', '', '去找寒冰皇冠的克羅科‧天譴剋星。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13813 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13813, 'zhTW', '和敵人一戰', '當我們把注意力放在這些模擬戰中，要知道我們真正的敵人依舊環伺在四周。銀白十字軍想要透過競賽找出最優秀的戰士，但我們也能知道誰從戰場上回來。讓那些聖騎士知道，就算是在聯賽準備期間，我們也願意對抗詛咒神教。$B$B前往寒冰皇冠，殺死你所遇到的任何一個教徒。他們在奧多薩和亡頌者之望人數眾多。', '銀白聯賽場地的『放血者』佐爾必要你殺死15名詛咒神教的成員。你可以在寒冰皇冠任何一個地方殺死神教成員。', '', '去找寒冰皇冠的『放血者』佐爾必。', '詛咒教派成員已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13814 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13814, 'zhTW', '勇士們', '身為一名勇士，你精通騎乘作戰的技巧，擊敗了各種層級的挑戰者。你確信你會對上你先前所擊敗的人。$B$B你應該持續鍛鍊自己的技巧並且學習敵方的弱點。代表各大城市的勇士們就在獸欄附近的勇士競技場。到獸欄去，裝備你的長槍，然後跨上你的坐騎，面對其他的勇士吧。', '帶4個勇士印記交給銀白聯賽場地的伊黎芮‧夜暮。如果你弄丟了長槍，你可以從任何一個靠近獸欄或奪日者亭閣的長槍架再拿一把。', '', '去找寒冰皇冠的伊黎芮‧夜暮。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13816 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13816, 'zhTW', '英雄:星穹渾天儀', '聽著，$g小夥子:小姑娘;!艾澤拉斯的命運就取決於此。$B$B我們唯一的機會就是即時趕到星穹渾天儀，找到這個艾爾加隆，並且阻止他把任何訊息傳回去給他的泰坦主人。$B$B找到星穹渾天儀，然後把你找到的所有資料都帶回來。我們或許還有點時間應付艾爾加隆的到來。', '奧杜亞大資料庫的勘察員洛倫要你找到通往星穹渾天儀的入口。', '已找到天體天文館的入口', '去找奧杜爾的勘察員洛倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13817 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13817, 'zhTW', '英雄:大資料庫資料圓盤', '這片白金圓盤有著令人驚嘆的對稱性，沒有一點刮痕或瑕疵。清晰的符文銘刻在它的邊緣之上，寫著「大資料庫」。$B$B奧杜亞之中一個有個裝置能夠讀取這片圓盤。', '將大資料庫資料圓盤帶到奧杜亞的大資料庫控制臺。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13818 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13818, 'zhTW', '英雄:艾爾加隆', '你真的辦到了，$n。把符印帶去給大資料庫控制臺，看你有沒有辦法獲得進入星穹渾天儀的許可。$B$B你最好動作快一點，$g小夥子:小姑娘;。時間緊迫。', '將看守者符印帶給奧杜亞的大資料庫控制臺。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13819 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13819, 'zhTW', '英雄:情況良好，完美收場', '我們最好得動作快點，$n。我們得從達拉然傳出回覆代碼。$B$B把這個交給羅甯，我在那裡跟你碰頭。', '將回覆代碼Α帶給達拉然的羅甯。', '', '去找水晶歌森林的羅甯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13821 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13821, 'zhTW', '英雄:芙蕾雅的符印', '如果我猜得沒錯，芙蕾雅的符印恐怕更麻煩。$B$B根據大資料庫的記錄，符印的精華與她的三個古老僕從相連，亮葉、鐵枒和石木。若是這三個長者受到傷害，就會危急符印的完整性。$B$B但放過這些長者，就表示你們在面對芙蕾雅時，她會更加強大。$B$B我能說什麼呢，$n，這是個兩難的抉擇。', '奧杜亞大資料庫的勘察員洛倫要你取得芙蕾雅的符印。想知道更多關於如何取得芙蕾雅的符印，請詢問大資料庫控制臺。', '', '去找奧杜爾的勘察員洛倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13822 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13822, 'zhTW', '英雄:霍迪爾的符印', '霍迪爾的符印可不容易取得。你不光是得擊敗霍迪爾本人，你還得在他毀掉存放符印的箱子之前打敗他!$B$B如果需要更多資料可以去大資料庫控制臺查詢。那個東西擁有的資料比全世界所有圖書館加起來都還多!', '奧杜亞大資料庫的勘察員洛倫要你取得霍迪爾的符印。想知道更多關於如何取得霍迪爾的符印，請詢問大資料庫控制臺。', '', '去找奧杜爾的勘察員洛倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13823 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13823, 'zhTW', '英雄:索林姆的符印', '索林姆已經不再是原本那個人了，$n。他受到了一種黑暗的影響。$B$B有一種邪惡的東西偽裝成他死去的妻子，希芙。$B$B你不能讓那個冒充者的法術控制他。要是這樣的話，他符印的位置可能就永遠沒人知道了!$B$B你得要讓他回復理智，而且動作要快。$B$B跟先前一樣，大資料庫控制臺會告訴你所有殘酷的細節...你不會喜歡的。', '奧杜亞大資料庫的勘察員洛倫要你取得索林姆的符印。想知道更多關於如何取得索林姆的符印，請詢問大資料庫控制臺。', '', '去找奧杜爾的勘察員洛倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13824 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13824, 'zhTW', '英雄:彌米倫的符印', '彌米倫真是個聰明的傢伙。他的整個住處都連結在某種自毀裝置上。$B$B要是你想拿到他的符印，你們就得很不幸地與自毀裝置比賽誰的動作快。如果有需要的話，可以向大資料庫控制臺查詢更多資料。', '奧杜亞大資料庫的勘察員洛倫要你取得彌米倫的符印。想知道更多關於如何取得彌米倫的符印，請詢問大資料庫控制臺。', '', '去找奧杜爾的勘察員洛倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13827 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13827, 'zhTW', '寶藏!', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13828 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13828, 'zhTW', '精通近戰', '聯賽競技的核心就是騎乘近戰。拿起這把長槍，然後騎上亭閣外圈養的奎爾多雷戰駒。$B$B一旦你騎上坐騎，就去找傑倫‧鎖木。他就在聯賽場地的北部邊緣，志士競技場的東邊。傑倫會教你該怎麼樣使用防禦，確保你在近距作戰時的安全。', '裝備你的長槍，騎上亭閣外的奎爾多雷戰駒。跟傑倫‧鎖木談談並以戳刺擊中近戰標靶5次，然後回去找銀白聯賽場地的秘法師泰利斯那。', '', '去找寒冰皇冠的秘法師泰利斯。', '傑蘭·洛克伍德的建議', '對近戰目標使用突刺', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13829 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13829, 'zhTW', '精通近戰', '聯賽競技的核心就是騎乘近戰。拿起這把長槍，然後騎上亭閣外圈養的奪日者陸行鷹。$B$B一旦你騎上坐騎，就去找傑倫‧鎖木。他就在聯賽場地的北部邊緣，志士競技場的東邊。傑倫會教你該怎麼樣使用防禦，確保你在近距作戰時的安全。', '裝備你的長槍，騎上亭閣外的奪日者陸行鷹。跟傑倫‧鎖木談談並以戳刺擊中近戰標靶5次，然後回去找銀白聯賽場地的博學者艾狄恩‧日谷那。', '', '去找寒冰皇冠的博學者艾狄恩‧日谷。', '傑蘭·洛克伍德的建議', '對近戰目標使用突刺', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13830 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13830, 'zhTW', '魅影鬼魚', '任何一個北裂境有點水準的釣客都知道什麼是小巧的長印魚。牠不適合食用，但有時對鍊金師很有用。$B$B然而，在休拉薩盆地的大河之心，有一種隱匿的魚躲藏在長印魚中。魅影鬼魚。一離開水中，牠們會漸漸變得透明直到完全消失。有些人猜想他們回到了休拉薩，而其他人則更為...迷信。$B$B我要你去抓這種魚並用任何方法解開牠的謎團!', '達拉然的瑪西亞‧切斯要你揭開魅影鬼魚的秘密。', '發現幽靈魚的謎團', '去找達拉然的瑪西亞·切斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13832 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13832, 'zhTW', '下水道的珠寶', '真的很難以置信，大多數的人在達拉然下水道垂釣只為了想釣大老鼠與變異魚。特別是當這些水裡充滿了無價的珠寶:被那些心碎的傻瓜、小偷和粗心大意的醉鬼丟棄的。$B$B要訣就是讓你的釣鉤沉到底部，然後釣到東西時別拉太用力。試試看，$n。我願意拿我自己的小飾品來交換你釣到的東西。', '達拉然的瑪西亞‧切斯要你帶給她一塊被腐蝕的首飾。', '', '去找水晶歌森林的瑪西亞·切斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13833 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13833, 'zhTW', '血濃於水', '血牙這種躁動的魚是治療感染傷口的藥方之一。如果你想要的話，我們可以做一些。$B$B一如其名，牠們相當嗜血。我只知道捕捉這些小惡魔的方法就是製造一灘血池後來釣牠。$B$B把你自己搞得全身都是血吧!在北風凍原殺掉一隻野獸，然後跳進水裡。這樣會立刻沖掉血跡，然後造出一個完美的釣魚點。', '達拉然的瑪西亞‧切斯要你帶給她5尾血牙狂魚。', '', '去找水晶歌森林的瑪西亞·切斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13834 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13834, 'zhTW', '危險的美味', '最棒的釣魚往往也是最危險的。那些無恥的傢伙總是在吹噓冬握湖有著最多也最豐富的漁獲量。$B$B事實上，那是唯一一個能釣到傳說中駭魚的地方:一種超致命也超美味的魚。幫我帶點來吧，我們可談點生意。', '達拉然的瑪西亞‧切斯要你帶給她10尾駭魚。', '', '去找水晶歌森林的瑪西亞·切斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13835 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13835, 'zhTW', '精通破盾', '你需要學會如何打破一個對手的防禦，才能在騎乘作戰中獲勝。拿起這把長槍，騎上亭閣外圈養的奎爾多雷戰駒。$B$B一旦你騎上坐騎，就去找瓦利斯‧逐風者。他就在聯賽場地的北部邊緣，志士競技場的東邊。瓦利斯會教你該怎麼樣使用遠距破盾攻擊，讓遠距標靶變得脆弱。', '裝備你的長槍，騎上亭閣外的奎爾多雷戰駒。跟瓦利斯‧逐風者談談並且對2個脆弱的遠程標靶使用破盾，然後回去找銀白聯賽場地的斥候夏琳卓雅。', '', '去找寒冰皇冠的斥候夏琳卓雅。', '瓦利斯·逐風者的建議', '對虛弱的遠程目標使用碎盾', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13836 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13836, 'zhTW', '少了隻胳膊!', '我最近收到消息，在達拉然監獄中發生了件不幸的意外事故，監獄中有個狠毒的罪犯切斷守衛的手臂並丟進水中。$B$B急救診所說，只要我們能把斷掉的手臂帶回去，他們就有辦法接回去。$B$B你在監獄外面的水邊釣魚也很長一段時間了，我敢用我最心愛的釣魚竿打賭，手臂一定會浮出水面。找到那條手臂，然後把它帶給達拉然的歐莉珊拉。她知道該怎麼處理。', '達拉然的仁慈的歐莉珊拉要你把斷裂的手臂帶給她。', '', '去找達拉然的仁慈的歐莉珊拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13837 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13837, 'zhTW', '精通衝鋒', '你在坐騎戰鬥時最強力的攻擊就是衝鋒。拿起這把長槍，騎上亭閣外圈養的奎爾多雷戰駒。$B$B一旦你騎上坐騎，就去找魯根‧鋼腹。他就在聯賽場地的北部邊緣，志士競技場的東邊。魯根會教你該怎麼樣使用衝鋒，並且教你一些基本戰略。', '裝備你的長槍，然後在亭閣外的獸欄騎上圈養的奎爾多雷戰駒。去和魯根‧鋼腹談談，並且衝撞2個脆弱的衝鋒標靶，然後回來找銀白聯賽場地的阿凡瑞斯‧迅擊報告。', '', '去找寒冰皇冠的阿凡瑞斯‧迅擊。', '魯根·鋼腹的建議', '衝鋒虛弱的衝鋒目標', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13838 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13838, 'zhTW', '精通破盾', '你需要學會如何打破一個對手的防禦，才能在騎乘作戰中獲勝。拿起這把長槍，騎上亭閣外圈養的奪日者陸行鷹。$B$B一旦你騎上坐騎，就去找瓦利斯‧逐風者。他就在聯賽場地的北部邊緣，志士競技場的東邊。瓦利斯會教你該怎麼樣使用遠距破盾攻擊，讓遠距標靶變得脆弱。', '裝備你的長槍，然後在亭閣外的獸欄騎上圈養的奪日者陸行鷹。去和瓦利斯‧逐風者談談，並且衝撞2個脆弱的衝鋒標靶，然後回後找銀白聯賽場地的加拉西雅‧明曦報告。', '', '去找寒冰皇冠的加拉西雅‧明曦。', '瓦利斯·逐風者的建議', '對虛弱的遠程目標使用碎盾', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13839 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13839, 'zhTW', '精通衝鋒', '你在坐騎戰鬥時最強力的攻擊就是衝鋒。拿起這把長槍，騎上亭閣外的圈養奪日者陸行鷹。$B$B一旦你騎上坐騎，就去找魯根‧鋼腹。他就在聯賽場地的北部邊緣，志士競技場的東邊。魯根會教你該怎麼樣使用衝鋒，並且教你一些基本戰略。', '裝備你的長槍，然後在亭閣外的獸欄騎上圈養的奪日者陸行鷹。去和魯根‧鋼腹談談，並且衝撞2個脆弱的衝鋒標靶，然後回後找銀白聯賽場地的艾瑪瑞爾‧日誓報告。', '', '去找寒冰皇冠的艾瑪瑞爾‧日誓。', '魯根·鋼腹的建議', '衝鋒虛弱的衝鋒目標', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13845 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13845, 'zhTW', '密封的毒藥瓶', '這個毒藥瓶看起來特別危險。也許達拉然的某個人會對它有興趣。', '把這個密封的毒藥瓶交給達拉然下水道的鍊金師席尼斯拉。', '', '去找達拉然的鍊金師席尼斯拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13846 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13846, 'zhTW', '為理念捐款', '最好最佳的勇士每天都會來禮拜堂聆聽銀白告解者的教誨。$B$B你應該看看她是如何鼓舞他們的，$n。他們不僅僅是為銀白十字軍奮戰，更是為理念捐了很多錢。$B$B也許你也想捐獻一點?', '和侍從亞緹談談並為銀白十字軍的理念捐贈10金。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13847 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13847, 'zhTW', '在敵人的大門前', '在我們準備好參加聯賽的同時，銀白十字軍軍團也在進行突襲敵人在冰冠城塞中堡壘的準備。$B$B在寒冰皇冠西南的白骨之廷，有一些勇敢的十字軍已經在寇普雷薩南方設立了前線營地。裝上你的長槍並騎上在營地裡圈養的競賽戰騎，再去毀滅巫妖王的爪牙。$B$B不用畏懼成群的骨衛步卒，$n，戰騎的馬蹄能輕易的踐踏他們。', '銀白聯賽場地的約瑟夫‧霍雷上尉要你去殺掉15個骨衛步卒、10個骨衛斥候以及3個骨衛中尉。', '', '去找寒冰皇冠的約瑟夫‧霍雷上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13850 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13850, 'zhTW', '毒藥的免疫力', '你想騎毒皮暴掠龍嗎？恐怕我有些壞訊息要告訴你。$B$B毒皮暴掠龍全身都是毒，從血液到唾沫，連皮膚表面都有毒素。你要是爬上去，不出幾個小時就會中毒而死。$B$B在我賣給你毒皮龍之前，你必須先獲得抵抗毒素的能力，這要花很長的時間，非常長……你需要去在戰鬥中沐浴毒血，要洗許多次。如果你真的對此感興趣，那麼你要知道，毒皮暴掠龍經常會出現在沼澤地的北部本地，你一直向西北方走，就能找到那裡了。', '安戈洛環形山的莫維克說，如果你能被毒皮暴掠龍的血染上20次毒，就可以安全地騎它了。攻擊毒皮魔暴龍，有一定機率會中毒。', '', '去安戈洛環形山找沼澤地的莫維克。', '灑上毒皮暴掠龍的血', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13851, 'zhTW', '在敵人的大門前', '在我們準備好參加聯賽的同時，銀白十字軍軍團也在準備突襲敵人在冰冠城塞中的堡壘。$B$B在寒冰皇冠西南的白骨之廷，有一些勇敢的十字軍已經在寇普雷薩南方設立了前線營地。裝上你的長槍並騎上在營地裡圈養的競賽戰騎，再去毀滅巫妖王的爪牙。$B$B不用畏懼成群的骨衛步卒，$n，戰騎的馬蹄能輕易的踐踏他們。', '銀白聯賽場地的卡拉菈‧跌酒要你去殺掉15個骨衛步卒、10個骨衛斥候以及3個骨衛中尉。', '', '去找寒冰皇冠的卡拉菈‧跌酒。', '', '', '', '', 0);
