INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13859, 'zhTW', '在敵人的大門前', '在我們準備好參加聯賽的同時，銀白十字軍軍團也在準備突襲敵人在冰冠城塞中的堡壘。$B$B在寒冰皇冠西南的白骨之廷，有一些勇敢的十字軍已經在寇普雷薩南方設立了前線營地。裝上你的長槍並騎上在營地裡圈養的競賽戰騎，再去毀滅巫妖王的爪牙。$B$B不用畏懼成群的骨衛步卒，$n，戰騎的馬蹄能輕易的踐踏他們。', '銀白聯賽場地的安妮拉‧修倫要你去殺掉15個骨衛步卒、10個骨衛斥候以及3個骨衛中尉。', '', '去找寒冰皇冠的安妮拉‧修倫。', '', '', '', '', 0);
