INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13861, 'zhTW', '冰冠城塞前的戰鬥', '在我們一些人為了聯賽而忙碌的同時，我們的兄弟也在準備突襲敵人在冰冠城塞中的堡壘。$B$B在寒冰皇冠西南的白骨之廷，有一些勇敢的十字軍已經在寇普雷薩南方設立了前鋒營地。裝上你的長槍並騎上在營地裡圈養的競賽戰騎，再去毀滅巫妖王手下的指揮官。$B$B不用畏懼成群的骨衛步卒，$N，戰騎的馬蹄能輕易的踐踏他們。', '銀白聯賽場地的『純淨者』埃卓克要你去殺掉3個骨衛指揮官。', '', '去找寒冰皇冠的『純淨者』埃卓克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13862 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13862, 'zhTW', '冰冠城塞前的戰鬥', '在我們一些人為了聯賽而忙碌的同時，我們的兄弟也在準備突襲敵人在冰冠城塞中的堡壘。$B$B在寒冰皇冠西南的白骨之廷，有一些勇敢的十字軍已經在寇普雷薩南方設立了前線營地。裝上你的長槍並騎上在營地裡圈養的銀白戰騎，再去毀滅巫妖王手下的指揮官。$B$B不用畏懼成群的骨衛步卒，$n，戰騎的馬蹄能輕易的踐踏他們。', '銀白聯賽場地的『純淨者』埃卓克要你去殺掉3個骨衛指揮官。', '', '去找寒冰皇冠的『純淨者』埃卓克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13863 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13863, 'zhTW', '冰冠城塞前的戰鬥', '在某些十字軍準備聯賽的同時，他們也派出了其他人去突襲敵人在冰冠城塞中的堡壘。$B$B在寒冰皇冠西南的白骨之廷，有一些勇敢的十字軍已經在寇普雷薩南方設立了前線營地。裝上你的長槍並騎上在營地裡圈養的競賽戰騎，再去毀滅巫妖王手下的指揮官。$B$B不用畏懼成群的骨衛步卒，$n，戰騎的馬蹄能輕易的踐踏他們。', '銀白聯賽場地的克羅科‧天譴剋星要你去殺掉3個骨衛指揮官。', '', '去找寒冰皇冠的克羅科‧天譴剋星。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13864 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13864, 'zhTW', '冰冠城塞前的戰鬥', '在某些十字軍準備聯賽的同時，他們也派出了其他人去突襲敵人在冰冠城塞中的堡壘。$B$B在寒冰皇冠西南的白骨之廷，有一些勇敢的十字軍已經在寇普雷薩南方設立了前線營地。裝上你的長槍並騎上在營地裡圈養的競賽戰騎，再去毀滅巫妖王手下的指揮官。$B$B不用畏懼成群的骨衛步卒，$n，戰騎的馬蹄能輕易的踐踏他們。', '銀白聯賽場地的克羅科‧天譴剋星要你去殺掉3個骨衛指揮官。', '', '去找寒冰皇冠的克羅科‧天譴剋星。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13887 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13887, 'zhTW', '毒皮暴掠龍蛋', '你對毒皮暴掠龍的毒已經免疫而可以安全的駕馭毒皮暴掠龍並觸碰牠們的蛋。毒皮暴掠龍非常兇殘，所以必須從雛龍就開始訓練。$B$B如果你想要一隻毒皮暴掠龍坐騎，必須先要有一顆未孵化的蛋。沼澤地裡散佈著許多暴掠龍巢。去找一些蛋殼顏色較淡的龍蛋--那些蛋即將孵化出雛龍。$B$B如果你帶幾個來給我，我可以讓你保留一個，並指導你如何養大小暴掠龍。', '帶4個毒皮暴掠龍蛋給沼澤地東南邊的莫維克。', '', '去安戈洛環形山找沼澤地的莫維克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13889 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13889, 'zhTW', '嗷嗷待哺', '毒皮小暴掠龍殷切地看著你，並在沙土上畫了幾個圖形。$B$B圖很潦草，但能分辨出那是雙帆龍、劍龍和翼手龍。畫完後，牠抬頭看著你，露出牙齒做出咬食的動作。$B$B你的毒皮小暴掠龍一定很想嚐嚐這些動物的鮮肉。殺死安戈洛環形山中任何種類的雙帆龍、劍龍或翼手龍，並以牠們的肉餵食你飢餓的小暴掠龍。', '你的毒皮小暴掠龍要你餵牠15片新鮮的恐龍肉。', '', '', '已餵食新鮮恐龍肉給劇毒雛龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13903 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13903, 'zhTW', '格里什幼蟲', '毒皮小暴掠龍殷切地看著你，並在沙土上畫了幾個圖形。$B$B那些畫看起來像是數種巨大的昆蟲，可能是格里什異種蟲。畫完後，牠用短小的前臂指著圖然後做出咬食的動作並舔了舔嘴唇。$B$B牠必定是要你去安戈洛環形山南部中央的巨痕谷收集異種蟲肉。當你收集到肉時，餵食你飢餓的毒皮小暴掠龍。', '你的毒皮小暴掠龍要你餵牠10片異種蟲肉。', '', '', '已餵食希利蘇斯蟲肉給劇毒雛龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13904 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13904, 'zhTW', '煮熟？熱炒？還是生吃？', '毒皮小暴掠龍指指餓得咕嚕咕嚕叫的胃引起了你的注意。牠在沙土上畫出了異種蟲，並在旁邊多畫了幾個小圓圈。牠指著小圓圈並殷切地看著你。$B$B這些圓圈一定是指異種蟲蛋。在塔納利斯西邊與安戈洛環形山交界的腐化之巢應該是個能找到小暴掠龍所要的蛋的好地方。', '你的毒皮小暴掠龍要你餵牠12個異種蟲蛋。', '', '', '已餵食希利蘇斯蟲卵給劇毒雛龍', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13905 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13905, 'zhTW', '炎鵬羽毛', '小暴掠龍看了你一會兒，彷彿在思考你是否會瞭解。牠在沙地上畫了一對羽毛，然後用爪子指著要黏在牠的肘部和膝蓋。$B$B牠看起來不太餓，那羽毛是要做什麼？$B$B牠一定是想要用它來裝飾自己，就像你看過的其他迅猛龍一樣。炎鵬有著最大最華麗的羽毛，它們大多盤據在塔納利斯西部，灌木谷的東北邊，那些大型生物的骨骸附近。', '你的毒皮小暴掠龍要你帶給牠5片炎鵬全羽。', '', '去找毒皮小暴掠龍。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13906 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13906, 'zhTW', '一暝大一吋', '在你的專業照養之下，毒皮小暴掠龍長得非常快。當他們不斷成長，乳牙會被恆齒替換。如果你保留牠們脫落的乳牙，會比較容易知道牠們何時大到可以訓練為坐騎。$B$B你的毒皮暴掠龍會讓你知道他想要什麼，所以要多關心牠。當牠的所有乳牙都脫落之後，帶著牠以及鞍座所需的材料來找我，剩下的部份就交給我吧。', '帶著20顆毒皮乳牙、毒皮小暴掠龍、20塊符文布、20張硬甲皮以及80玫金幣去找安戈洛環形山沼澤地東南邊的莫維克。', '', '去安戈洛環形山找沼澤地的莫維克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13926 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13926, 'zhTW', '神諭者孤兒魯魯', '孤兒們一直都很期待能有像你這樣的朋友，$N。我非常高興你能答應照顧他們其中的一個。$B$B帶上這隻哨子。有了它，你隨時都能召喚受你照顧的孤兒。你不需要照顧他太久——大概也就是兒童週這段時間。$B$B好了，$N，請召喚你的孤兒吧。他一定會非常喜歡你的。你們一定會在北裂境各處渡過不少愉快的旅程。', '同孤兒監護員艾蕊婭交談，然後使用神諭者孤兒哨召喚你要在兒童週照顧的孤兒。', '', '去找神諭者孤兒。如果你的孤兒不在附近那麼請使用你的神諭者孤兒哨。', '同孤兒監護員艾蕊婭交談', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13927 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13927, 'zhTW', '狼獾人孤兒科科', '孤兒們一直都很期待能有像你這樣的朋友，$N。我非常高興你能答應照顧他們其中的一個。$B$B帶上這隻哨子。有了它，你隨時都能召喚受你照顧的孤兒。你不需要照顧他太久——大概也就是兒童週這段時間。$B$B好了，$N，請召喚你的孤兒吧。他一定會非常喜歡你的。你們一定會在北裂境各處渡過不少愉快的旅程。', '同孤兒監護員艾蕊婭交談，然後使用狼獾人孤兒哨召喚你要在兒童週照顧的孤兒。', '', '去找狼獾人孤兒。如果你的孤兒不在附近那麼請使用你的狼獾人孤兒哨。', '同孤兒監護員艾蕊婭交談', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13929 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13929, 'zhTW', '史上最巨大的樹！', '在大戰爆發，我們離開自己的村莊之前，索烏塞和我們講過歷史上最巨大的樹！$B$B索烏塞管那棵樹叫灰喉堡。索烏塞告訴我們，它就在灰白之丘的中央。不，等等，這不是索烏塞說的。索烏塞說的是灰白之丘。肯定沒錯！那棵好大的樹就在灰白之丘的中央。絕對沒有錯！$B$B你帶我們去那裡好不好？我們要好好看看那棵大樹。索烏塞告訴我們，有許多大熊怪就住在那棵樹裡。也許我們還能看見他們呢。', '帶著你的孤兒魯魯轉至灰喉堡。當你進入到那棵大樹的樹幹裡時，如果他不在你身邊，一定要召喚他過來。', '帶魯魯轉至灰喉堡', '去找神諭者孤兒。如果你的孤兒不在附近那麼請使用你的神諭者孤兒哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13930 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13930, 'zhTW', '熊怪的家園', '高階薩滿祭司拉克亞克總是向我們講強大武士的故事。其中有些故事發生在很遠的地方。有時候，他會講巨大的熊怪為了保衛樹城而英勇戰鬥的故事。$B$B也許你能帶科科到那裡去，去看看那些大樹，還有那裡的戰場！高階薩滿祭司拉克亞克告訴科科，那座巨大的樹城灰喉堡就矗立在灰白之丘的正中心。$B$B科科在遇到監護員之前從沒有見過一座城市。但這座城市裡沒有戰士，只有穿著紫袍子的人。科科想去看看真正的戰士為了真正的城市作戰的樣子！', '帶著你的孤兒科科轉至灰喉堡。當你進入那棵巨樹的樹幹時，如果他不在你身邊，一定要召喚他過來。', '帶科科去看灰喉堡', '去找狼獾人孤兒。如果你的孤兒不在附近那麼請使用你的狼獾人孤兒哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13931 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13931, 'zhTW', '又過了一年，又一個紀念品。', '我們不但供應每個人啤酒，同時還贈送酒杯!只要用合法的方式就可以換取漂亮的紀念杯!這張兌換卷給你。$B$B跟啤酒節營地後方的布力克斯談話。他是個怪傢伙，甚至現在也還戴著那副護目鏡。他會幫你處理那張兌換券，而所有啤酒節的交易也都可以找他。', '把啤酒節酒杯兌換券交給啤酒節營地後方的布力克斯‧修械。', '', '去找杜洛塔的布利克斯·菲克維特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13932, 'zhTW', '又過了一年，又一個紀念品。', '啤酒節除了競速山羊外，還要痛快暢飲!有空的時候，拿這個兌換券去找貝爾碧·迅移。她就在啤酒節營地後方附近。如果你找不到她，別擔心，她一定會看見你的。$B$B總之，把這張兌換券交給她來換取你的免費啤酒節酒杯。她也會樂意的為你處理各種啤酒節的交易。', '把啤酒節酒杯兌換券交給啤酒節營地的貝爾碧·迅移。', '', '去找丹莫洛的貝爾碧。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13933 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13933, 'zhTW', '青銅巨龍聖地', '有時候，高階神諭者索烏塞會講一些關於一座巨龍祭壇的故事。那和雨水巨石可不一樣。索烏塞告訴我們，也許我們能在那裡看到我們自己，只不過不會像我們現在這樣閃光光。索烏塞的意思是說，我們能在那裡看到自己許多年以後的樣子。$B$B你要帶我們去那裡？我們記得青銅巨龍聖地是在一個叫龍骨荒野的地方。索烏塞說，雨水巨石讓他知道，那個聖地就在龍眠神殿的東北方，或者是暮冬要塞的西北方。我們現在出發嗎？', '帶上你的孤兒魯魯轉至青銅巨龍聖地。如果當你到達那裡的時候，他不在你身邊，一定要召喚他過來。', '帶著魯魯轉至青銅巨龍聖地', '去找神諭者孤兒。如果你的孤兒不在附近那麼請使用你的神諭者孤兒哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13934 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13934, 'zhTW', '青銅巨龍聖地', '當科科還是小孩子的時候，他經常會聽長者們說起一個遙遠的聖地。有時候，長者們會說，在青銅巨龍聖地能知道關於未來的一切事情。$B$B科科要告訴你，他要成為強大的戰士。所以我們現在就要到那裡去看看。青銅巨龍聖地就在龍骨荒野，在一個被稱作龍眠神殿的東北方，一座被稱為暮冬要塞的人類城鎮的西北方。$B$B我們要到那裡去，看看未來。我要讓監護員知道，她是錯的。科科是戰士，不是傻瓜。', '帶上你的孤兒科科轉至青銅巨龍聖地。如果當你到達那裡的時候，他不在你身邊，一定要召喚他過來。', '帶著科科轉至青銅巨龍聖地', '去找狼獾人孤兒。如果你的孤兒不在附近那麼請使用你的狼獾人孤兒哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13937 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13937, 'zhTW', '轉至奇妙玩具店的旅行', '我們還有時間去下一站？我們聽說達拉然有一間玩具店，但我們從來沒有去過那裡。監護員說，如果大家都要去那裡的話，那裡就會被擠爆了。也許我們可以去那裡？只有我們？我們可以在那裡得到一隻規模紙飛艇嗎？他們就會把那種小飛艇送到達拉然的奇妙玩具店去。我們一直都想要一隻那樣的小飛艇。也許你能給我們一隻？', '在奇妙玩具店購買一隻規模紙飛艇，然後把它擲給你的孤兒魯魯。', '', '去找神諭者孤兒。如果你的孤兒不在附近那麼請使用你的神諭者孤兒哨。', '將小型紙飛艇擲給魯魯', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13938 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13938, 'zhTW', '轉至奇妙玩具店的旅行', '你還要帶科科去另一個地方？監護員說達拉然有一個奇妙玩具店。但科科從沒有去過那裡。保姆說，如果有一個孤兒去了，她就必須帶所有孤兒都去那裡了。你能帶科科去那裡嗎？$B$B科科看到過其它孩子玩摺紙飛艇。科科聽說那些飛艇都是從奇妙玩具店裡飛出來的。也許你能在那裡弄到一隻摺紙飛艇，然後和科科一起玩？', '在奇妙玩具店購買一隻規模紙飛艇，再將小飛艇丟給你的孤兒科科。', '', '去找狼獾人孤兒。如果你的孤兒不在附近那麼請使用你的狼獾人孤兒哨。', '將小型紙飛艇擲給科科', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13950 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13950, 'zhTW', '夥伴！', '你要知道，孤兒們都是很孤獨的。有時候，我們很想去別的地方看看，結交一些新的朋友。$B$B也許你能帶我們去闖一闖？我們聽說有一個叫冬鱗避難所的地方。那就在北風凍原裡面。要去那裡，我們應該向西北方前進，走到靠近考達拉島邊緣的地方。$B$B監護員說有一個勇敢的人也在那裡養育著一群孤兒。他們一定也很孤單，一定也需要朋友。你願意帶我們去那裡嗎？', '帶領你的孤兒魯魯前去拜訪冬鱗避難所。當你到達那裡的時候，如果他不在你身邊，一定要召喚他過來。', '帶領魯魯參觀冬鱗避難所。', '去找神諭者孤兒。如果你的孤兒不在附近那麼請使用你的神諭者孤兒哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13951 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13951, 'zhTW', '夥伴！', '除了監護員照顧的小孩子，科科還想有別的朋友。也許我們能去一些別的地方？$B$B科科知道有一個部落居住在龍骨荒野。他們住的地方叫做飄雪林地。你知道嗎？飄雪林地在莫亞基港口的北邊和紅玉巨龍聖地的南邊。$B$B<提到海象人的時候，科科的臉上現出一副生氣的表情。>$B$B你帶科科去那裡。去拜訪那裡的村子。也許我們能遇到新的狼獾人，讓他們知道，狂心氏族有多厲害！', '帶著你的孤兒科科轉至飄雪林地。當你到達那裡的時候，如果他不在你身邊，一定要召喚他過來。', '帶領科科參觀飄雪林地。', '去找狼獾人孤兒。如果你的孤兒不在附近那麼請使用你的狼獾人孤兒哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13952 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13952, 'zhTW', '感激的亡者', '能再次看看朋友和家人的感覺真好，雖然我或許有點太超過了...我已經把他們今天給我準備的東西全吃光了!$B$B我能麻煩你幫我找些美味的亡者麵包嗎?我會非常感激...$B$B我想，那邊的小販有在賣食譜。', '拿一些亡者麵包給暴風城墓地中興奮的人類靈魂。使用橘色金盞花可以看見這些隱形的靈魂。', '', '去找艾爾文森林的興奮的人類靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13954 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13954, 'zhTW', '紅龍女王', '高階神諭者索烏塞有一個故事，說的是造物主造出了所有的龍和一位統馭所有巨龍的女王。我們想看一看那位女王！你能帶我們去龍眠神殿的最高處嗎？索烏塞告訴我過我們，那個神廟就在龍骨荒野的中心。$B$B我們真的很想見到紅龍女王。她一定又大又美麗。也許她能幫助我們找到新的爸爸媽媽。$B$B你會帶我們去嗎？', '帶上你的孤兒魯魯去拜訪雅立史卓莎，生命的縛誓者，她就在龍眠神殿的頂端。如果當你到達那裡的時候，他不在你身邊，一定要召喚他過來。', '帶著魯魯去見雅立史卓莎，生命的縛誓者', '去找神諭者孤兒。如果你的孤兒不在附近那麼請使用你的神諭者孤兒哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13955 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13955, 'zhTW', '紅龍女王', '科科一直都很喜歡巨龍。科科一直都想有一條龍。但監護員不讓科科這樣做。不過她說了，你可以帶科科去看看紅龍女王。$B$B科科終於聽監護員說了一句也有道理的話。你願意帶科科去龍骨荒野中心的龍眠神殿嗎？我們一同飛到那座神廟頂上，去看看紅龍女王。她一定非常非常巨大。這樣她才能成為所有巨龍的女王。科科已經等不及想要見她了！', '帶上你的孤兒科科去拜訪雅立史卓莎，生命的縛誓者，她就在龍眠神殿的頂端。如果當你到達那裡的時候，他不在你身邊，一定要召喚他過來。', '帶著科科去見雅立史卓莎，生命的縛誓者', '去找狼獾人孤兒。如果你的孤兒不在附近那麼請使用你的狼獾人孤兒哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13956 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13956, 'zhTW', '拜訪一位造物主', '高階神諭者索烏塞總是告訴我們，造物主如何建起聖地，而我們則讓它們發光。但他從沒有見過一位造物主。沒有人見過造物主。不過，也許你能找到一位造物主？$B$B索烏塞告訴我們，造物主建造了一座界門，並把它安放在索拉查南部的正中心。索烏塞沒有說它會通向哪裡。但也許我們能借助它走到一位造物主的面前！帶我們走進那道界門，讓我們看看門的另一邊到底有些什麼吧，$N。', '帶著你的孤兒魯魯轉至塑造者之臺的源生石像那裡。當你到達那裡的時候，如果他不在你身邊，一定要召喚他過來。', '帶魯魯去拜訪源生石像', '去找神諭者孤兒。如果你的孤兒不在附近那麼請使用你的神諭者孤兒哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13957 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13957, 'zhTW', '強大的赫米特·奈辛瓦里', '你知道科科一直想要見到的人是誰嗎？赫米特·奈辛瓦里。$B$B也許你能帶科科去見他？長者哈爾卡克把他的所有事情都告訴我們了。他來到索拉查就是為了獵捕當地最大的怪物！就連狂心氏族的長老們也尊敬赫米特·奈辛瓦里，稱他為偉大的獵人。$B$B長者哈爾卡克告訴科科，奈辛瓦里營地就在索拉查西側的中部，碎浪河附近。我們去那裡拜訪他，學習如何像赫米特那樣狩獵好不好？', '帶著你的孤兒科科去拜訪赫米特·奈辛瓦里。他就在奈辛瓦里營地。如果當你到達那裡的時候，他不在你身邊，一定要召喚他過來。', '帶科科去拜訪赫米特·奈辛瓦里', '去找狼獾人孤兒。如果你的孤兒不在附近那麼請使用你的狼獾人孤兒哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13959 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13959, 'zhTW', '返回孤兒院', '我們和你一起度過了最棒的時光，$n。我們好希望你現在可以當我們的$g爸爸:媽媽;，但你必須帶我們回去找達拉然孤兒監護員阿瑞雅了。$B$B也許你改天能再來找我們?我們喜歡去看看冬鰭的小朋友們和龍后。沒有人會相信我們會見了一位偉大之神的!$B$B我們會想念你的，$n。我們保證改天會寫信給你，好嗎?', '帶著你的被監護人回到達拉然孤兒院並把神諭者孤兒哨交回給達拉然的孤兒監護員阿瑞雅。', '', '去找達拉然的孤兒監護員阿瑞雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13960 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13960, 'zhTW', '返回孤兒院', '你知道嗎?其實你沒有那麼壞，$n。你帶恰嘎去很多有趣的地方。恰嘎遇到了很多新朋友而且經歷了其他小獾狼怪沒經歷過的。$B$B你，還有赫米特‧奈辛瓦里，以及落雪林地的小獾狼怪都是最好的新朋友。也許改天你會帶一本荊棘谷的青山給恰嘎?恰嘎保證有空時也會寫信告訴你近況。也許有時候會對大舌頭小孩友善一點。$B$B恰嘎要回去照顧孤兒的女士阿瑞雅那裡了，回到紫色的人類城市。', '帶著你的被監護人回到達拉然孤兒院並把獾狼怪孤兒哨交回給達拉然的孤兒監護員阿瑞雅。', '', '去找達拉然的孤兒監護員阿瑞雅。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13966 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13966, 'zhTW', '冬幕節禮物', '', '禮物上有一個小牌子寫著:冬幕節快樂，$n!。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13986 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13986, 'zhTW', '受傷的同伴', '$c，相信你已經知道，這裡的戰鬥相當艱苦。我們還能守住戰線，但我們的戰士已死傷慘重。$B$B我們的一個名叫奧伯妮·亮鬃的戰士手臂上的傷口感染了。她被送回到雷霆崖進行急救。不過，她在混亂中把盾牌遺失在了這裡。你能把這面盾牌連同我們的祝福一起給她帶過去麼？我們非常想念她的微笑。$B$B你可以在雷霆崖的長者高地那裡找到她。', '將破舊的部族護盾交給奧伯妮·亮鬃。她就在雷霆崖裡的長者高地。', '', '去找莫高雷的阿波尼·亮鬃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13990 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13990, 'zhTW', '魔法公雞', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13997 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13997, 'zhTW', '如果在我戰鬥的時候，你讀到了這個……', 'Dan是全世界最可怕的程式設計師……我說的是魔獸世界！$B$B當我戰鬥的時候，你卻沒辦法和我說話，難道這不是很奇怪的事情嗎？而現在這種怪事已經不會再發生了，我的朋友。Dan對我的一個生物特性做了大規模改進！$B$B和我一起慶祝吧，消滅這些可怕的怪物。正是它們讓我陷入了永遠無法停息的戰鬥之中。', 'ELM Daze Target想要你為Dan和Great Justice消滅5個ELM Attacker。', '', 'Return to ELM Daze Target in Designer Island.', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14016 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14016, 'zhTW', '黑騎士的詛咒', '在你打贏黑騎士後我想要把他的遺體丟出聯賽場地，但告解者帕爾璀絲堅持他應該被正式的埋葬。從此之後，一股黑暗的氣息在墓地徘徊不去，使得人們不敢去探視死者。$B$B你能去聯賽場地東邊盡頭的墓地一趟，看看到底發生什麼事嗎?', '銀白聯賽場地的十字軍萊達菈要求你去調查黑騎士之墓。', '調查黑騎士之墓', '去找寒冰皇冠的十字軍萊達菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14017 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14017, 'zhTW', '黑騎士的命運', '你說屍體被神教教徒偷走了?他們會去的地方我想只有一個，亡頌者之望，聯賽場地西邊高崗的營地。$B$B不管那些教徒想幹什麼，我們都得阻止他們。看來我聽到的傳言是真的，那個惡名昭彰的寇勒醫生一定是神教成員並以在此磨練他的技藝。在神教營地尋找高台或祭壇，殺了醫生，尋找他進行計畫的證物，並且用任何方法來阻礙他的工作。', '在亡頌者之望攔截寇勒醫生的指示，然後回去找銀白聯賽場地的十字軍萊達菈。', '', '去找寒冰皇冠的十字軍萊達菈。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14023 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14023, 'zhTW', '香料麵包餡料', '我們的香料麵包餡料是旅人豐年祭餐桌上的必備食物。它不只在暴風城受歡迎，現在更在旅人豐年祭的食譜上佔有一席之地。$B$B如果你已經是位廚師，去找旅人豐年祭的商人領取一本烹飪書吧，他也提供所有佳節大餐所需的當地食材。如果你還不是位廚師，這是你開始學習的最好時機!$B$B當你做好餡料，就交給餐桌旁的賈斯伯‧摩爾吧。', '製作5份香料麵包餡料，然後帶給暴風城大門外邊餐會區的賈斯伯‧摩爾。', '', '去找艾爾文森林的賈斯伯‧摩爾。', '準備香料麵包填料', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14024 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14024, 'zhTW', '南瓜派', '你做的香料麵包餡料聞起來很香，但少了南瓜派就不配稱作旅人豐年祭餐會了。那是我們喜歡的另一道暴風城名餚，而它只使用這裡生長的成熟的艾爾文南瓜來製作。$B$B如果你還不知道怎麼做南瓜派，在你的豐年祭烹飪書中有這道菜的做法。$B$B你願意做幾片南瓜派並帶給鐵爐堡外邊的愛德華‧溫斯洛嗎？他正為南瓜派的量不夠而急得跳腳呢。', '製作5片南瓜派，然後帶給鐵爐堡外邊餐會區的愛德華‧溫斯洛。', '', '去找丹莫羅的愛德華‧溫斯洛。', '準備南瓜派', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14028 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14028, 'zhTW', '蔓越莓甜酸醬', '如果你從未吃過蔓越莓甜酸醬，嘗過後你會愛上它的。它是用最新鮮又氣味強烈的濕地蔓越莓所製成的。如果你想試試手藝來製作甜酸醬，從旅人豐年祭的商人那就可以買到。$B$B食譜應該就在你的豐年祭烹飪書中。$B$B如果有時間的話，你願意做一些甜酸醬並帶給暴風城外的賈斯伯‧摩爾嗎？我答應用一些甜酸醬跟他交換你帶來的南瓜派。', '製作5份蔓越莓甜酸醬，然後帶給暴風城外邊餐會區的賈斯伯‧摩爾。', '', '去找艾爾文森林的賈斯伯‧摩爾。', '準備蔓越莓酸辣醬', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14030 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14030, 'zhTW', '達納蘇斯的貪吃鬼', '謝謝你帶來的蔓越莓甜酸醬。這裡有太多東西要烹製了，我幾乎沒時間去想別的事。而我現在的第一要務是，達納蘇斯的艾薩克‧愛勒頓那裡幾乎吃完了所有食物。你應該可以快馬加鞭的幫忙趕製更多的香料麵包餡料和南瓜派吧？商人那有你所需要的一切食材。$B$B你可以在戰士區的那一邊，達納蘇斯入口附近的餐桌旁找到他。', '帶5份香料麵包餡料和5份南瓜派給達納蘇斯入口附近的艾薩克‧愛勒頓。', '', '去達納蘇斯找戰士區的艾薩克‧愛勒頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14032 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14032, 'zhTW', '清理狗頭人營地', '你的第一個任務是清剿一群惡徒，$n。一群狗頭人正在北方的那片森林中為非作歹。到那裡去，消滅你找到的狗頭人歹徒，削減他們的數量，讓我們最終能將他們徹底趕出北郡。', '消滅10個狗頭人歹徒，然後回去見治安官瑪克布萊德。', '', '去找治安官瑪克布萊德。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14033 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14033, 'zhTW', '蜜煮甘薯', '既然你都來了，那就應該帶幾個泰達希爾甘薯才對。它們被用來製作世界上最美味的蜜煮甘薯。$B$B如果你不相信我，去查查你豐年祭烹飪書中的食譜然後試試吧。如果還有剩，你應該分一些給暴風城外邊餐會區的葛列格里‧塔波。這是他最愛的美食之一，不過對他來說，其實每樣食物都是他的最愛！', '製作5份蜜煮甘薯，然後帶給暴風城大門外邊的葛列格里‧塔波。', '', '去找艾爾文森林的葛列格里‧塔波。', '準備蜜汁地瓜', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14035 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14035, 'zhTW', '慢烤火雞', '每個旅人豐年祭的餐會都需要一個華麗的主題物，當然我不是指裝飾用的豐饒角，而是說華美的烤火雞這道主菜。$B$B在你的豐年祭烹飪書中有這道好菜。何不去宰了幾隻野生火雞然後準備個幾份呢？而整個艾爾文森林都有火雞在亂逛，找到牠們並不是件難事。$B$B在你烤好之後，你願意帶幾份給達納蘇斯大門附近的艾薩克‧愛勒頓嗎？', '製作5隻慢烤火雞然後帶給達納蘇斯大門附近的艾薩克‧愛勒頓。', '', '去達納蘇斯找戰士區的艾薩克‧愛勒頓。', '準備慢烤火雞', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14037 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14037, 'zhTW', '香料麵包餡料', '我們的香料麵包餡料是旅人豐年祭餐桌上的必備食物。這道菜從羅德隆美好的年代就一直記載著，現在更在傳統菜餚上佔有一席之地。$B$B如果你已經是位廚師，去找旅人豐年祭的商人領取一本烹飪書吧，他也提供所有佳節大餐所需的當地食材。如果你還不是位廚師，這是你開始學習的最好時機!$B$B當你做好餡料，就交給餐桌旁的威廉‧慕林吧。', '製作5份香料麵包餡料，然後帶給幽暗城中庭餐會區的威廉‧慕林。', '', '去找提裏斯法林地的威廉‧慕林。', '準備香料麵包填料', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14040 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14040, 'zhTW', '南瓜派', '你做的香料麵包餡料很受歡迎，但少了南瓜派就不配稱作旅人豐年祭餐會了。那是另一道傳統的當地名餚，而它只使用這裡生長的成熟提里斯法南瓜來製作。$B$B如果你還不知道怎麼做南瓜派，在你的豐年祭烹飪書中有這道菜的做法。$B$B你願意做幾片南瓜派並帶給奧格瑪外邊的法蘭西斯‧埃頓嗎？他正為南瓜派的量不夠而急得跳腳呢。', '製作5片南瓜派，然後帶給奧格瑪外邊餐會區的法蘭西斯‧埃頓。', '', '去找杜洛塔的法蘭西斯‧埃頓。', '準備南瓜派', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14041 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14041, 'zhTW', '蔓越莓甜酸醬', '你嚐過蔓越莓甜酸醬沒？它是用新鮮又氣味強烈的怒水蔓越莓所製成的。如果你想試試手藝來製作甜酸醬，從旅人豐年祭的商人那就可以買到。$B$B食譜應該就在你的豐年祭烹飪書中。$B$B如果有時間的話，你願意做一些甜酸醬並帶給雷霆崖升降梯底部西邊的杜金‧遠野嗎？', '製作5份蔓越莓甜酸醬，然後帶給雷霆崖升降梯底部西邊的杜金‧遠野。', '', '去找雷霆崖的杜金‧遠野。', '準備蔓越莓酸辣醬', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14043 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14043, 'zhTW', '蜜煮甘薯', '既然你都來了，那就應該帶著幾個莫高雷甘薯才對。它們被用來製作美味的蜜煮甘薯，所有旅人豐年祭名餚中我最愛的一道菜。$B$B如果你不相信我，去查查你豐年祭烹飪書中的食譜然後試試吧。如果你正要回去奧格瑪，把它們帶給城外邊餐會區的法蘭西斯‧埃頓。我是一直在補給他的食物存量沒錯，可是那邊的消耗量實在太大了。', '製作5份蜜煮甘薯，然後帶給奧格瑪外邊餐會區的法蘭西斯‧埃頓。', '', '去找杜洛塔的法蘭西斯‧埃頓。', '準備蜜汁地瓜', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14044 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14044, 'zhTW', '食物短缺的幽暗城', '謝謝你帶來的蜜煮甘薯。這裡有太多東西要烹製了，我很難補滿所有食物。然後，邁爾斯捎給我一封短信說他那裡的餡料及蔓越莓甜酸醬快要消耗殆盡了。你應該可以快馬加鞭的幫忙趕製更多的這兩樣食物吧？商人那應該有你所需要的一切食材。$B$B你可以在幽暗城廢墟中庭附近的餐桌旁找到邁爾斯‧墨壺。', '帶5份香料麵包餡料和5份蔓越莓甜酸醬給幽暗城入口附近的邁爾斯‧墨壺。', '', '去找提裏斯法林地的邁爾斯‧墨壺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14047 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14047, 'zhTW', '慢烤火雞', '旅人豐年祭的餐會都需要一個主菜，以我們來說就是慢烤火雞了。沒有任何一道菜可以與它相提並論。$B$B在你的豐年祭烹飪書中有這道好菜。何不去宰了幾隻野生火雞然後準備個幾份呢？整個提里斯法林地都有火雞在亂逛，找到牠們並不是件難事。$B$B在你烤好之後，你可以帶幾份給奧格瑪外邊的法蘭西斯‧埃頓嗎？', '製作5隻慢烤火雞然後帶給奧格瑪大門附近的法蘭西斯‧埃頓。', '', '去找杜洛塔的法蘭西斯‧埃頓。', '準備慢烤火雞', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14048 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14048, 'zhTW', '火雞不足', '我從節日開始就不停的烹製食物，但依然是供不應求。可以請你幫我處理一道菜嗎？$B$B這裡很難抓到火雞，如果你能提供一些慢烤火雞，那可是幫了一個大忙。若你想要自己準備這道菜，艾爾文森林的任何地方都可以獵捕到野生火雞。旅人豐年祭商人也提供你所需要的其他物品。', '帶20隻慢烤火雞給鐵爐堡外的凱特倫‧鐵壺。', '', '去找丹莫羅的凱特倫‧鐵壺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14051 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14051, 'zhTW', '別忘了餡料!', '快要可以把桌子擺滿食物了！我在盯著甘薯時順道做好了蔓越莓甜酸醬，也確定派沒有烤焦。$B$B我想所有東西應該都準備好了。不，等等，我忘了某個東西。餡料！噢，不。在其他東西做好之前我沒有時間把餡料放進製作排程了。你可以幫幫我嗎？買或做一些餡料應該不會花太多時間，而且你可以在這裡買到食材。', '帶20份香料麵包餡料給鐵爐堡外邊餐會區的凱特倫‧鐵壺。', '', '去找丹莫羅的凱特倫‧鐵壺。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14053 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14053, 'zhTW', '蔓越莓甜酸醬又吃完了？', '我丈夫，賈斯伯，要去做更多的蔓越莓甜酸醬，但看來他正忙於確認蜜煮甘薯是否足以供應給所有的客人。你可以幫忙嗎？如果你是個廚師，你可以在鐵爐堡外邊的旅人豐年祭商人那取得氣味強烈的濕地蔓越莓。$B$B如果你不會烹調，請其他人做甜酸醬也是可以。', '帶20份蔓越莓甜酸醬給暴風城外邊餐會區的愛蓮‧摩爾。', '', '去找艾爾文森林的愛蓮‧摩爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14054 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14054, 'zhTW', '一「派」輕鬆', '艾薩克忙著教慶祝者製作旅人豐年祭的傳統菜宴並如何分配每年此時所收成的食材。我已經儘可能的把桌子堆滿菜盤，但艾薩克的最愛快要吃完了，就是南瓜派。$B$B你能拿一些來給我們嗎?如果你想自己做，你需要去暴風城外邊跟旅人豐年祭商人購買成熟的艾爾文南瓜。', '帶20片南瓜派給達納蘇斯大門附近餐會區的瑪麗‧愛勒頓。', '', '去達納蘇斯找戰士區的瑪麗‧愛勒頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14055 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14055, 'zhTW', '她要甘薯', '我妻子愛蓮把我抓來幫忙把桌子堆滿，但她卻三心二意。一開始要我做南瓜派，但現在她卻改要蜜煮甘薯。$B$B不過，我已經開始做派了，所以也許你能幫我趕製那些甘薯。若我們能完成她要求的每樣東西，她一定會很驚喜的。$B$B如果你要自己做蜜煮甘薯，你必須從達納蘇斯的旅人豐年祭商人那邊買一些甘薯。謝了，$n。', '帶20份蜜煮甘薯給暴風城外邊餐會區的賈斯伯‧摩爾。', '', '去找艾爾文森林的賈斯伯‧摩爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14058 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14058, 'zhTW', '她要甘薯', '蘿貝塔‧卡特找我來幫忙準備其中一道菜，蜜煮甘薯。正常說來，我是很樂意幫忙的，但我已經答應女侍幫她看好桌子。$B$B若你願意幫我處理那些蜜煮甘薯，我會很感激你的。要是我讓蘿貝塔失望，她是不會原諒我的。$B$B如果你要自己烹製蜜煮甘薯，你必須跟雷霆崖的旅人豐年祭商人買些甘薯。謝了，$n。', '帶20份蜜煮甘薯給幽暗城餐會區的威廉‧慕林。', '', '去找提裏斯法林地的威廉‧慕林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14059 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14059, 'zhTW', '蔓越莓甜酸醬又吃完了？', '我真希望能搞清楚為何蔓越莓甜酸醬消耗得那麼快。有時候，我猜他們趁我不注意時偷偷拿去餵那些憎惡體。你可以幫我做一批新的嗎？如果你是個廚師，你可以在奧格瑪外邊的旅人豐年祭商人那買到氣味強烈的怒水河蔓越莓。$B$B如果你不會烹調，請其他人做甜酸醬也是可以。', '帶20份蔓越莓甜酸醬給幽暗城中庭餐會區的蘿貝塔‧卡特。', '', '去找提裏斯法林地的蘿貝塔‧卡特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14060 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14060, 'zhTW', '一「派」輕鬆', '杜金和拉荷忙著教慶祝者製作旅人豐年祭的傳統菜宴並如何分配每年此時所收成的食材。我已經儘可能的把桌子堆滿菜盤，可是南瓜派快吃完了。$B$B你能拿一些來給我們嗎?如果你想自己做，你需要去幽暗城外邊跟旅人豐年祭商人購買成熟的提里斯法南瓜。', '帶20片南瓜派給雷霆崖外邊餐會區的瑪哈拉‧金麥。', '', '去找莫高雷的瑪哈拉‧金麥。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14061 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14061, 'zhTW', '火雞不足', '我從節日開始就不停的烹製食物，但依然是供不應求。可以請你幫我處理一道菜嗎？$B$B這裡很難抓到火雞，如果你能提供一些慢烤火雞，那可是幫了一個大忙。若你想要自己準備這道菜，提里斯法林地的任何地方都可以獵捕到野生火雞。旅人豐年祭商人也提供你所需要的其他物品。', '帶20隻慢烤火雞給奧格瑪外邊的昂達尼‧巨磨。', '', '去找杜洛塔的昂達尼‧巨磨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14062 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14062, 'zhTW', '別忘了餡料!', '快要可以把桌子擺滿食物了！我在盯著甘薯時順道做好了蔓越莓甜酸醬，也確定派沒有烤焦。$B$B我想所有東西應該都準備好了。不，等等，我忘了某個東西。餡料！噢，不。在其他東西做好之前我沒有時間把餡料放進製作排程了。你可以幫幫我嗎？買或做一些餡料應該不會花太多時間，而且你可以在這裡買到食材。', '帶20份香料麵包餡料給奧格瑪外邊的昂達尼‧巨磨。', '', '去找杜洛塔的昂達尼‧巨磨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14064 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14064, 'zhTW', '分享豐年祭盛宴', '直到你在豐年祭餐席上吃的飽飽才算是徹底的慶祝了旅人豐年祭。$B$B來唷，坐好囉，開動吧，吃吃看每樣食物！你可以自己換位置，或是請其他人傳一些他們的食物給你。$B$B當你每種菜餚都吃足了，你將滿懷著有福同享的愉悅。', '在豐年祭餐席上每種食物享用五份，直至你獲得有福同享效果。豐年祭餐席會出現在大多數的主城和城鎮。', '', '去找豐年祭餐席女侍。', '分享之靈', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14065 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14065, 'zhTW', '分享豐年祭盛宴', '直到你在豐年祭餐席上吃的飽飽才算是徹底的慶祝了旅人豐年祭。$B$B來唷，坐好囉，開動吧，吃吃看每樣食物!你可以自己換位置，或是請其他人傳一些他們的食物給你。$B$B當你每種菜餚都吃足了，你將滿懷著有福同享的愉悅。', '在豐年祭餐席上每種食物享用五份，直至你獲得有福同享效果。豐年祭餐席會出現在大多數的主城和城鎮。', '', '去找豐年祭盛宴女侍。', '分享之靈', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14074 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14074, 'zhTW', '被劫的腿肉補給', '銀白十字軍派遣了一艘載著陸行鳥肉及其他補給品的快艇來給聯賽場地的我們，但它一直沒有抵達。斥候回報說看見快艇被科瓦迪爾所攻擊，那些可怕的海上維酷劫掠者。$B$B他們屠殺了船員並把貨物帶去一座叫做赫魯斯加臺地的島上。如果你往北方看去，可以看見它籠罩在迷霧之中。你能幫我們取回那些被偷的貨物嗎?沒有那些陸行鳥腿，我們很快就會食物短缺。', '取回10份被偷的陸行鳥腿給銀白聯賽場地的娜拉希·雪曦。', '', '去找寒冰皇冠的娜拉希‧雪曦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14076 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14076, 'zhTW', '勇士的早餐', '現在大競技場完成了，銀白十字軍要我們幫忙尋找能與勇士對戰的生物。$B$B巨型蟄猛巨蟲有著最奇怪的進食特性;牠們吃自己同類的蛋會長得特別強壯，而深地蟄猛巨蟲的蛋是最好的。$B$B帶著這個鼓到風暴群山中央的足跡冷原，然後在那邊的雪堆附近敲鼓。引出深地蟄猛巨蟲，殺了牠們，然後收集牠們的卵囊。', '取得4份蟄猛巨蟲卵囊並帶給銀白聯賽場地的莎薇娜·識歌。', '', '去找寒冰皇冠的莎薇娜‧識歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14077 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14077, 'zhTW', '聖光的憐憫', '我聽從告解者帕爾璀絲的教誨，我必須告訴你，她說的話讓我省思許多。與十字軍並肩作戰是不夠的;我們必須接手他們的任務。$B$B北海岸外就是赫魯斯加臺地，來自海上的科瓦迪爾侵襲了這個古老的巨牙海民聚落，並屠殺了村民。拿著這本書並在村民屍體旁為死者頌禱儀式。這可以讓他們的靈魂脫離迷霧的束縛並獲得安息。', '使用告解者的祈禱書對8個被殺的托利克村民執行最後的儀式，然後回去找銀白聯賽場地的娜拉希·雪曦。', '', '去找寒冰皇冠的娜拉希‧雪曦。', '執行最後的儀式', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14079 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14079, 'zhTW', '在艾爾文森林學習騎術', '這本介紹著騎術訓練與購買坐騎的小手冊是蘭達爾‧亨特送來的。$B$B蘭達爾就在艾爾文森林的東谷伐木場，只要沿著暴風城外的路向東走即可抵達。', '到艾爾文森林的東谷伐木場，把這本小手冊繳回給蘭達爾‧亨特。', '', '去艾爾文森林找石碑湖的蘭達爾·亨特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14080 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14080, 'zhTW', '阻止侵略者', '科瓦迪爾，可怕的維酷劫掠者，攔截了我們的船隻並屠戮了北方一座島上的巨牙海民，把島更名為赫魯斯加臺地。如果他們在那邊打穩基礎，毫無疑問我們將會是他們下一個目標。$B$B十字軍的軍力全都用在對付天譴軍了，所以我們必須保護聯賽場地。從這裡向北飛抵島上並在科瓦迪爾毀滅任何東西之前處理掉他們。', '銀白聯賽場地的娜拉希·雪曦要你去殺掉10個科瓦迪爾。', '', '去找寒冰皇冠的娜拉希‧雪曦。', '殺死科瓦迪爾', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14081 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14081, 'zhTW', '在永歌森林學習騎術', '這本介紹著騎術訓練與購買坐騎的小手冊是珀拉斯坎送來的。$B$B珀拉斯坎就在薩爾倫的出租商行，銀月城牧羊人之門外的東南方。', '到銀月城，把這本小手冊繳回給珀拉斯坎。', '', '去找永歌森林的珀拉斯坎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14082 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14082, 'zhTW', '在艾克索達學習騎術', '這本介紹著騎術訓練與購買坐騎的小手冊是阿露恩送來的。$B$B阿露恩就在藍謎島的艾克索達入口處。', '到藍謎島的艾克索達外頭，把這本小手冊繳回給阿露恩。', '', '去找藍謎島的埃亞倫。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14083 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14083, 'zhTW', '在丹莫洛學習騎術', '這本介紹著騎術訓練與購買坐騎的小手冊是奧薩姆‧鐵角送來的。$B$B奧薩姆就在丹莫洛的凍石農場，沿著鐵爐堡外的路向東走即可抵達。', '到丹莫洛的凍石農場，把這本小手冊繳回給奧薩姆‧鐵角。', '', '去丹莫洛找凍石農場的奧薩姆·鐵角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14084 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14084, 'zhTW', '在丹莫洛學習騎術', '這本介紹著騎術訓練與購買坐騎的小手冊是賓吉‧羽哨送來的。$B$B賓吉就在鋼架補給站，丹莫洛卡拉諾斯的東北方。', '到丹莫洛的鋼架補給站，把這本小手冊繳回給賓吉‧羽哨。', '', '去丹莫洛找鋼架補給站的賓吉·羽哨。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14085 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14085, 'zhTW', '在達納蘇斯學習騎術', '這本介紹著騎術訓練與購買坐騎的小手冊是賈薩姆送來的。$B$B賈薩姆就在達納蘇斯的塞納里奧區。', '到達納蘇斯的塞納里奧區，把這本小手冊繳回給賈薩姆。', '', '去達納蘇斯找貿易區的賈薩姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14086 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14086, 'zhTW', '馳騁在奧格瑪', '這本關於騎乘訓練和坐騎購買的廣告小冊子是由基爾達派發出來的。$B$B你可以在奧格瑪的榮譽谷找到基爾達。', '將這本小冊子交給奧格瑪榮耀谷的基爾達。', '', '到艾薩拉找基爾達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14087 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14087, 'zhTW', '在莫高雷學習騎術', '這本介紹著騎術訓練與購買坐騎的小手冊是卡爾‧雷詠送來的。$B$B卡爾就在莫高雷的血蹄村。', '到莫高雷的血蹄村，把這本小手冊繳回給卡爾‧雷詠。', '', '去莫高雷找血蹄村的卡爾·雷歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14088 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14088, 'zhTW', '馳騁在杜洛塔', '這本關於騎乘訓練和坐騎購買的廣告小冊子是由克薩爾迪派發出來的。$B$B你可以在南杜洛塔的森金村找到克薩爾迪。', '將這本小冊子交還給杜洛塔南面森金村的克薩爾迪。', '', '去杜洛塔\\r\\n找暗矛海灘的克薩爾迪。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14089 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14089, 'zhTW', '在提里斯法林地學習騎術', '這本介紹著騎術訓練與購買坐騎的小手冊是維爾瑪‧瓦納姆送來的。$B$B維爾瑪就在提里斯法林地的布瑞爾。', '到提里斯法林地的布瑞爾，把這本小手冊繳回給維爾瑪‧瓦納姆。', '', '去提里斯法林地找布瑞爾的維爾瑪·瓦納姆。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14090 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14090, 'zhTW', '戈莫克要他的極地狗頭人', '我的兩名部下在試著囚禁猛瑪象人『穿刺者』戈莫克時被殺了，而那隻生物仍舊怒氣沖沖。牠因為最愛的極地狗頭人不在身邊而嚎叫了好幾個小時。$B$B如果銀白十字軍不希望在大競技場使用這隻怪物，我會親手殺掉牠。也許是該帶給這隻野獸一些玩具的時候了。帶著這個網子去風暴群山東南邊的迦姆之禍。就在K3的東北。捕捉一些極地狗頭人並向聖光祈禱你抓到正確的那隻。', '使用加重的網子捕捉8隻雪盲跟隨者，並帶給銀白聯賽場地的莎薇娜·識歌。', '', '去找寒冰皇冠的莎薇娜‧識歌。', '', '捕捉雪盲跟隨者', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14092 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14092, 'zhTW', '勇士的早餐', '現在大競技場完成了，銀白十字軍要我們幫忙尋找能與勇士對戰的生物。$B$B巨型蟄猛巨蟲有著最奇怪的進食特性;牠們吃自己同類的蛋會長得特別強壯，而深地蟄猛巨蟲的蛋是最好的。$B$B帶著這個鼓到風暴群山中央的足跡冷原，然後在那邊的雪堆附近敲鼓。鼓聲會引出深地蟄猛巨蟲。殺了牠們，收集牠們的卵囊並帶回聯賽場地。', '取得4份蟄猛巨蟲卵囊並帶給銀白聯賽場地的提洛斯‧曦奔。', '', '去找寒冰皇冠的提洛斯‧曦奔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14095 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14095, 'zhTW', '鑑定屍體', '一顆從死亡的海怪身上找到的完整牙齒相當罕見。十字軍銀曦一定會想看看的。', '把海怪牙交給十字軍銀曦來作為勝利的證明。', '', '去找寒冰皇冠的十字軍銀曦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14096 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14096, 'zhTW', '庫爾，看看你這次幹的好事', '十字軍庫爾又讓自己陷入麻煩了，不過這次可不只他一個人。當他發現有些教徒在聯賽場地西邊的亡頌者之望紮營時，庫爾召集了一些志士發動一次突襲。$B$B在沒有增援的情況下，庫爾和他的跟隨者輕易的被俘虜了。除非我們進行救援，不然神教一定會將囚犯當作祭品。任何一個教徒都有可能帶著黑色牢籠的鑰匙。找到鑰匙並釋放庫爾及被俘虜的志士們。', '從亡頌者之望救出『魯莽』庫爾和4位被俘虜的志士，然後回去找銀白聯賽場地的娜拉希·雪曦。', '', '去找寒冰皇冠的娜拉希‧雪曦。', '拯救『魯莽』庫爾', '拯救被俘虜的志士', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14100 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14100, 'zhTW', '陶土議會的遺跡', '$N，你已經掌握了許多技能，能夠自如地控制四大元素了。而你要努力去做的就是維持四大元素的平衡。只要經過不懈的聯繫，你就能只攜帶一枚聖物，而不必再攜帶全部四件圖騰了。$B$B同奧格瑪智慧谷的戈圖拉·林風談談，在那裡繼續磨礪你控制元素的技藝吧。', '將你的四大元素圖騰交給奧格瑪的戈圖拉·林風。', '', '到奧格瑪找戈圖拉·林風。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14101 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14101, 'zhTW', '多廷·赫魯斯加', '科瓦迪爾，海上的維酷們劫掠了船隻和岸邊的居民，屠戮了北方海峽那端一座巨牙海民的島。他們的首領，多廷·赫魯斯加，打算控制這整片海域。$B$B若他的勢力壯大，我們的船隻和軍艦就永無安寧之日了。我們將被孤立在此而對巫妖王束手就擒。$B$B拿著這個奪來的科瓦迪爾戰爭號角到赫魯斯加臺地東北邊的巨牙海民雕像之環，使用它來挑戰科瓦迪爾的首領。', '銀白聯賽場地的高階十字軍艾德拉要你去擊敗多廷·赫魯斯加。', '', '去找寒冰皇冠的高階十字軍艾德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14102 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14102, 'zhTW', '喚霧者伊格瓦', '科瓦迪爾回到了北裂境的海岸，若不加以制止，他們將會截斷我們的援軍以及後勤補給。他們的其中一員，喚霧者伊格瓦，居住在赫魯斯加臺地西邊的洞穴中。他在那裡操縱著霧來隱蔽科瓦迪爾及他們操控的海中怪獸。$B$B拿著這個符咒，前往聯賽場地北邊海峽彼端的赫魯斯加臺地。找到喚霧者的洞穴並使用符咒讓他現形。', '銀白聯賽場地的高階十字軍艾德拉要你去殺掉喚霧者伊格瓦。', '', '去找寒冰皇冠的高階十字軍艾德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14103 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14103, 'zhTW', '泰坦鋼粉末', '', '', '', '去找水晶歌森林的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14104 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14104, 'zhTW', '『刀疤』歐諾夫', '『刀疤』歐諾夫在科瓦迪爾中是以劫掠和俘虜船隻聞名的可怕劫掠者。他和船員駕駛博爾之怒攻擊我們的船隻並竊奪我們的貨物。$B$B歐諾夫和他的部下也是屠戮巨牙海民並把島改名為赫魯斯加臺地的傢伙。他的船停泊在島上港口的東端。將這面旌旗插在船上，宣告你擄獲了他的船，進而挑釁他出來和你一戰。', '銀白聯賽場地的高階十字軍艾德拉要你去殺掉『刀疤』歐諾夫。', '', '去找寒冰皇冠的高階十字軍艾德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14105 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14105, 'zhTW', '亡頌者凱洛斯', '詛咒神教為了目睹我們的毀滅而又增強了他們的勢力。他們在聯賽場地西邊山脊的亡頌者之望據點越來越堅強茁壯。$B$B殘忍的亡頌者凱洛斯和他的部下鞏固了他們的所在地並準備釋放所有神教的武器。$B$B我的部下已經準備好與驍士們一同保衛聯賽場地，但我需要一個像你，$N，一樣的勇士來引領我們的行動以減緩攻勢。找到亡頌者凱洛斯並殺了他。', '銀白聯賽場地的高階十字軍艾德拉要你去殺掉亡頌者凱洛斯。', '', '去找寒冰皇冠的高階十字軍艾德拉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14106 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14106, 'zhTW', '納·卡達的任務測試', '', '', '', '去找真正的羅納卡達。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14107 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14107, 'zhTW', '逝往者的命運', '銀白十字軍並不是第一個在寒冰皇冠對抗巫妖王的勢力。我們的敵人正在讓那些逝去的靈魂來對抗我們。$B$B他們遊蕩在逝往英雄山谷，聯賽場地的西南方，奧多薩與鐵牆壁壘之間。那個區域散亂著毀棄的靈魂水晶，被天譴軍團用來控制那些靈魂。收集那些靈魂水晶並和這個聖光祝福聖物一起使用來給予那些靈魂安息的祝福。這些英雄們理當早日獲得安息。', '十字軍銀曦要你讓6位陣亡英雄之靈獲得安息。', '', '去找寒冰皇冠的十字軍銀曦。', '祝福陣亡英雄之靈', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14108 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14108, 'zhTW', '逮住海怪!', '奪日者和白銀誓盟派遣船隻前往北邊的赫魯斯加臺地和科瓦迪爾人交戰，但他們被科瓦迪爾的劫掠艦隊中途攔截，且自顧不暇。更糟糕的是，科瓦迪爾人找出了召喚潛伏在北海深海中恐怖海怪的方法。如果我們想保住船上的人，就必須要驅離海怪，並且中斷科瓦迪爾的召喚儀式。$B$B十字軍，拿著這些長矛，銀白角鷹獸將會帶你前往戰場。', '十字軍銀曦要你騎上銀白角鷹獸，對北海海怪投擲6支烈焰之矛並解決3個維酷深海呼喚者。$B$B你可以在聯賽場地的銀白十字軍帳棚外面找到銀白角鷹獸。', '', '去找寒冰皇冠的十字軍銀曦。', '對北海海怪投擲矛', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14112 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14112, 'zhTW', '雪人到底該吃什麼？', '十字軍抓住了一隻叫作冰嚎的雪人。他將會成為大競技場對戰的成員之一，而我們被要求幫忙訓練及看護他。$B$B十字軍應該不會喜歡用奪日者的屍塊餵食這隻野獸的建議。這隻生物偏好鯊魚肉，所以我要你飛去停在北方海峽的銀刃號。從船上拿一籃新鮮的肉餌，然後撒在水中來吸引鯊魚過來。', '銀白聯賽場地的莎薇娜‧識歌要你帶3片北海鯊魚肉給她。', '', '去找寒冰皇冠的莎薇娜‧識歌。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14119 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14119, 'zhTW', '祖達薩之眼', '', '', '', '去寒冰皇冠找鐵牆大壩的林奇·黑箭。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14136 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14136, 'zhTW', '海上救援', '科瓦迪爾在北方的小島，赫魯斯加臺地上設立了據點。我們派遣埃薩斯‧火鷹船長前往該區，但他們遇上了正朝聯賽場地而來的科瓦迪爾劫掠艦隊!火鷹號正遭受劫掠者的攻擊，且人數居於劣勢。盡速前往該地，讓那些科瓦迪爾人瞭解攻擊奪日者是件多麼愚蠢的計畫。$B$B火鷹號的位置介於聯賽場地與北邊的赫魯斯加臺地之間，海劫者航道的西側。', '銀白聯賽場地的『血漬』吉拉納要你殺掉登上火鷹號的8個科瓦迪爾狂戰士及3個科瓦迪爾魚叉手。', '', '去找寒冰皇冠的『血漬』吉拉納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14140 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14140, 'zhTW', '阻止侵略者', '科瓦迪爾，可怕的維酷劫掠者，攔截了我們的船隻並屠戮了北方一座島上的巨牙海民，把島更名為赫魯斯加臺地。如果他們在那邊打穩基礎，毫無疑問我們將會是他們下一個目標。$B$B十字軍的軍力全都用在對付天譴軍了，所以我們必須保護聯賽場地。從這裡向北飛抵島上並在科瓦迪爾毀滅任何東西之前處理掉他們。', '銀白聯賽場地的『血漬』吉拉納要你去殺掉10個科瓦迪爾人。', '', '去找寒冰皇冠的『血漬』吉拉納。', '卡瓦迪爾已擊殺', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14141 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14141, 'zhTW', '戈莫克要他的極地狗頭人', '我的兩名部下在試著囚禁猛瑪象人『穿刺者』戈莫克時被殺了，而那隻生物仍舊怒氣沖沖。牠因為最愛的極地狗頭人不在身邊而嚎叫了好幾個小時。$B$B如果銀白十字軍不希望在大競技場使用這隻怪物，我會親手殺掉牠。也許是該帶給這隻野獸一些玩具的時候了。帶著這個網子去風暴群山東南邊的迦姆之禍。就在K3的東北。捕捉一些極地狗頭人並向聖光祈禱你抓到正確的那隻。', '使用加重的網子捕捉8隻雪盲跟隨者，並帶給銀白聯賽場地的提洛斯‧曦奔。', '', '去找寒冰皇冠的提洛斯‧曦奔。', '', '已捕獲雪盲追隨者', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14142 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14142, 'zhTW', '庫爾，看看你這次幹得好事', '十字軍庫爾又讓自己陷入麻煩了，不過這次可不只他一個人。當他發現有些教徒在聯賽場地西邊的亡頌者之望紮營時，庫爾召集了一些志士發動一次突襲。$B$B在沒有增援的情況下，庫爾和他的跟隨者輕易地被俘虜了，庫爾如今被囚禁在營地內平台上的牢籠裏。除非我們進行救援，不然神教一定會將囚犯當作祭品。任何一個教徒都有可能帶著黑色牢籠的鑰匙。找到鑰匙並釋放庫爾及被俘虜的志士們。', '從亡頌者之望救出『魯莽』庫爾和4位被俘虜的志士，然後回去找銀白聯賽場地的『血漬』吉拉納。', '', '去找寒冰皇冠的『血漬』吉拉納。', '已救出魯莽者庫爾', '已救出被俘的候選者', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14143 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14143, 'zhTW', '被劫的腿肉補給', '銀白十字軍派遣了一艘載著陸行鳥肉及其他補給品的快艇來給聯賽場地的我們，但它一直沒有抵達。斥候回報說看見快艇被科瓦迪爾人所攻擊，那是一群可怕的海上維酷劫掠者。$B$B他們屠殺了船員並把貨物帶去一座叫做赫魯斯加臺地的島上。如果你往北方看去，可以看見它籠罩在迷霧之中。你能幫我們取回那些被偷的貨物嗎？沒有那些陸行鳥腿，我們很快就會斷糧。', '取回10份被偷的陸行鳥腿給銀白聯賽場地的『血漬』吉拉納。', '', '去找寒冰皇冠的『血漬』吉拉納。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14144 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14144, 'zhTW', '聖光的憐憫', '我聽從告解者帕爾璀絲的教誨，我必須告訴你，她說的話讓我省思許多。與十字軍並肩作戰是不夠的;我們必須接手他們的任務。$B$B北海岸外就是赫魯斯加臺地，來自海上的科瓦迪爾侵襲了這個古老的巨牙海民聚落，並屠殺了村民。拿著這本書並在村民屍體旁為死者頌禱儀式。這可以讓他們的靈魂脫離迷霧的束縛並獲得安息。', '使用告解者的祈禱書對8個被殺的托利克村民執行最後的儀式，然後回去找銀白聯賽場地的『血漬』吉拉納。', '', '去找寒冰皇冠的『血漬』吉拉納。', '已進行臨終祈禱', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14145 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14145, 'zhTW', '雪人到底該吃什麼？', '十字軍抓住了一隻叫作冰嚎的雪人。他將會成為大競技場對戰的成員之一，而我們被要求幫忙訓練及看護他。$B$B十字軍應該不會喜歡我們拿白銀誓盟的成員來餵食這隻野獸的建議。這隻生物偏好鯊魚肉，所以我要你飛去停在北方海峽的赤曦號。從船上拿一籃新鮮的肉餌，然後撒在水中來吸引鯊魚過來。', '銀白聯賽場地的提洛斯‧曦奔要你帶3片北海鯊魚肉給他。', '', '去找寒冰皇冠的提洛斯‧曦奔。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14147 AND `locale` = 'zhTW';
