INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14151, 'zhTW', '緋色紅寶石', '緋色紅寶石是北裂境最好的寶石。它在陽光下如水晶玫瑰般閃耀。$B$B在我教你這個轉化技術之前，我要求你進行五次史詩級寶石轉化來做事前準備。你可以轉化你喜歡的寶石，或者重複轉化相同的寶石也行。$B$B當你真的準備好後回來找我。', '達拉然的琳西‧黑栓要你用鍊金術成功的轉化5顆史詩級寶石。你可以轉化紫黃晶、祖爾之眼、懼石、王者琥珀和威嚴鋯石。', '', '去找寒冰皇冠的琳西·黑栓。', '史詩寶石嬗變', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14152 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14152, 'zhTW', '海上救援', '勇士、浪峰船長和她的船被派往北方襲擊赫魯斯加臺地的科瓦迪爾人，卻被朝聯賽場地而來的科瓦迪爾劫掠艦隊給攔截了。不幸的，科瓦迪爾的船員有著數量上的優勢，並逐漸佔領船隻。$B$B我們需要你往北方到海劫者航道上的浪峰號，就在聯賽場地和赫魯斯加臺地之間，幫助船員擊退來襲的敵人。你可以在航道的東邊看見這艘船。', '前往北海殺掉正在攻擊浪峰號的8個科瓦迪爾狂戰士及3個科瓦迪爾魚叉手。', '', '去找寒冰皇冠的娜拉希‧雪曦。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14160 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14160, 'zhTW', '功績令狀', '用優質的羊皮紙列著許多由$n所達成的成就是珠寶設計界的慣例。$B$B將這份文件繳回給達拉然的提摩西‧瓊斯來換取適當的獎賞。', '把功績令狀送給達拉然的提摩西‧瓊斯。', '', '去找達拉然的提摩西·瓊斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14163 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14163, 'zhTW', '戰鬥的召喚：征服之島', '當我們在寒冰皇冠距離勝利越來越近的時候，部落的軍隊卻給我們製造了越來越多的麻煩，讓我們的戰士在同巫妖王作戰的同時不得不抽出力量來對付他們。$B$B現在，部落派遣了他們的精英衛士柯爾克隆來阻擋我們對征服之島的進軍。那座島是一個非常重要的戰略要地。$N，你的任務就是為聯盟在那裡取下勝利的果實！', '在征服之島戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟准將覆命。', '征服之島的勝利', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14164 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14164, 'zhTW', '戰鬥的召喚：征服之島', '我們很快就會在北裂境取得勝利……但我們必須在寒冰皇冠取得一個立足點，用來為我們的部隊提供後勤補給。$B$B征服之島恰好是一個理想的地點。這裡很容易進行防禦，而且資源豐富。聯盟也看中了這個地方，並派遣第七軍團和我們爭奪對這座島嶼的控制權。$B$B$N，趕快到那裡去，不惜一切代價為部落奪取那個戰略要地！', '在征服之島戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。', '征服之島的勝利', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14166 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14166, 'zhTW', '感激的亡者', '能再次看看朋友和家人的感覺真好，雖然我或許有點太超過了...我已經把他們今天給我準備的東西全吃光了!$B$B我能麻煩你幫我找些美味的亡者麵包嗎?我會非常感激...$B$B我想，那邊的小販有在賣食譜。', '拿一些亡者麵包給達拉然墓地中興奮的達拉然靈魂。使用橘色金盞花可以看見這些隱形的靈魂。', '', '去找水晶歌森林的興奮的達拉然靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14167, 'zhTW', '死者的感激', '真高興能再次見到朋友和親人，不過也許我做得有些太誇張了……我已經吃光了他們為我準備的一切！$B$B能不能幫我一個忙，再給我拿來一些那種美味的悼念糕餅？我會非常感激你的……$B$B我想，那邊的查普曼正在出售食譜。', '弄到悼念糕餅，並把它交給鐵爐堡墓地的歡快的矮人靈魂。$B$B你必須使用一朵橙菊，才能看到那個隱形的靈魂。', '', '到丹莫洛鐵爐堡大門找附近的歡快的矮人靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14168 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14168, 'zhTW', '感激的亡者', '能再次看看朋友和家人的感覺真好，雖然我或許有點太超過了...我已經把他們今天給我準備的東西全吃光了!$B$B我能麻煩你幫我找些美味的亡者麵包嗎?我會非常感激...$B$B我想，那邊的小販有在賣食譜。', '拿一些亡者麵包給鐵爐堡墓地中興奮的地精靈魂。$B$B使用橘色金盞花可以看見這些隱形的靈魂。', '', '去找丹莫洛鐵爐堡大門附近的地精靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14169 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14169, 'zhTW', '死者的感激', '真高興能再次見到朋友和親人，不過也許我做得有些太誇張了……我已經吃光了他們為我準備的一切！$B$B能不能幫我一個忙，再給我拿來一些那種美味的悼念糕餅？我會非常感激你的……$B$B我想，那邊的查普曼正在出售食譜。', '弄到悼念糕餅，並把它交給艾克索達墓地的歡快的德萊尼靈魂。$B$B你必須使用一朵橙菊，才能看到那個隱形的靈魂。', '', '到藍謎島找歡快的德萊尼靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14170 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14170, 'zhTW', '感激的亡者', '能再次看看朋友和家人的感覺真好，雖然我或許有點太超過了...我已經把他們今天給我準備的東西全吃光了!$B$B我能麻煩你幫我找些美味的亡者麵包嗎?我會非常感激...$B$B我想，那邊的小販有在賣食譜。', '拿一些亡者麵包給達納蘇斯墓地中興奮的夜精靈靈魂。$B$B使用橘色金盞花可以看見這些隱形的靈魂。', '', '去泰達希爾找多蘭納爾的歡快的暗夜嚮導靈魂。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14171 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14171, 'zhTW', '感激的亡者', '能再次看看朋友和家人的感覺真好，雖然我或許有點太超過了...我已經把他們今天給我準備的東西全吃光了!$B$B我能麻煩你幫我找些美味的亡者麵包嗎?我會非常感激...$B$B我想，那邊的小販有在賣食譜。', '拿一些亡者麵包給銀月城墓地中興奮的血精靈靈魂。使用橘色金盞花可以看見這些隱形的靈魂。', '', '去找永歌森林的興奮的血精靈靈魂。', '', '', '', '', 0);
