INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14174, 'zhTW', '感激的亡者', '能再次看看朋友和家人的感覺真好，雖然我或許有點太超過了...我已經把他們今天給我準備的東西全吃光了!$B$B我能麻煩你幫我找些美味的亡者麵包嗎?我會非常感激...$B$B我想，那邊的小販有在賣食譜。', '拿一些亡者麵包給幽暗城墓地中興奮的被遺忘者靈魂。使用橘色金盞花可以看見這些隱形的靈魂。', '', '去找提裏斯法林地的興奮的被遺忘者靈魂。', '', '', '', '', 0);
