INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14199, 'zhTW', '死亡證明:黑騎士', '我的夥伴大法師泰彌亞要我警告你，危急的情況即將發生。不久之後，你將會挑戰位於寒冰皇冠，銀白大競技場的勇士試煉。你必須小心那位人們僅知其名的黑騎士，他將會試圖阻礙賽事的發展。$B$B將他靈魂的碎片交給我，如此祈倫托就知道他已經被解決了。他還告訴我，如果你失敗的話，恐怕你的小命就難保了。', '達拉然的大法師朗達拉克要你帶給他一片黑騎士的靈魂碎片。$B$B這個任務只能在英雄難度下完成。', '', '去找水晶歌森林的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14200 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14200, 'zhTW', '巫妖王之怒 任務', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14203 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14203, 'zhTW', '浸水的配方', '看起來這似乎是張調配烈酒的破舊配方。也許達拉然的「勸君更進一杯酒」的老闆對它會有興趣...', '將浸水的配方交給達拉然城的克利斯蒂‧斯托克頓。', '', '去達拉然找再來一杯的克莉絲蒂·斯多克頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14353 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14353, 'zhTW', '邪惡的盟友', '看樣子，瑪克林就在剃刀高地外面。我們必須將他消滅。$B$B我在奧格瑪的線人告訴我，他們的偵察兵在那裡發現了一些奇怪的跡象。那裡的野豬人身上發生了一些怪異的現象，他們的力量比以前強大了許多。不管天譴軍團在那裡做了什麼，我們必須立刻阻止他們。$B$B找到那個瑪克林，消滅他。然後回來向我報告。', '將瑪克林大師的信物交給幽暗城的布拉貢·血拳。', '', '回幽暗城的皇家區找貝拉戈·血拳。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14355 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14355, 'zhTW', '進入血色修道院', '我駐紮在這的任務之一便是幫助被遺忘者守好邊境，而這，$c，也正是你要為我做的事情。$B$B我本可以繼續在這過活，但血色十字軍會馬不停蹄的襲擊我的人，把他們的頭一個個砍下來。他們在這是個麻煩，大麻煩，而你要對此做點什麼。$B$B到修道院去，殺死大檢察官懷特邁恩和她的軍官們。', '消滅大檢察官懷特邁恩、血色十字軍指揮官莫格萊尼、血色十字軍勇士赫洛德和馴犬者洛克希，然後向幽暗城的布拉貢·血拳。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14356 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14356, 'zhTW', '毀滅之力…', '聽好，$c。$B$B你可能還不知道奧格瑪出事情了。怒焰裂谷深處有一幫自稱灼刃氏族的暗影議會成員在進行邪惡的儀式。因為我對全是由獸人組成的蠻兵幫我帶來的重要訊息不是很放心，所以我希望你去那裡看看。$B$B他們手上應該有兩本書籍。我不要讓灼刃氏族跟被遺忘者持有那些書。拿到書以後直接帶來給我。', '將《暗影法術研究》和《扭曲虛空的魔法》這兩本書交給幽暗城的貝拉戈·血拳。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14409 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14409, 'zhTW', '謹慎的回訪', '佔用你一點時間，$c。$B$B世事無常。我們又一次被迫離開了埃雷薩拉斯廢墟，走入外面的世界。我是來研究這座城市的，我不想走遠，但是也許你會對這個差事感興趣。$B$B我的同事準備前往達納蘇斯去找那裡的高階祭司談談，希望能借此與他們達成共識。帶上這本日記去找神殿中的莫丹特·永影。這東西也許會對他的外交任務有幫助。', '將達羅斯的日記帶給身處達納蘇斯的莫丹特·永影。', '', '去達納蘇斯找神殿花園的大法師摩丹特·平影。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14436 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14436, 'zhTW', '矮人挖掘', '有些矮人正準備在西北邊建立一個挖掘點。他們認為地底下埋藏著某些秘密，事實也的確如此，但挖空和破壞土地是不可能理解大地的教誨。$B$B收集矮人的挖掘工具，毀掉那些東西，然後把矮人損壞的工具帶來給我。$B$B你可以在熔爐邊破壞那些工具。你可以在雷霆崖找到熔爐，但任何一個熔爐 -- 甚至是矮人營地的熔爐 -- 都可以用來破壞工具。', '收集5個勘察員的十字鎬。在熔爐砸爛這些勘察員的十字鎬以製造損壞的工具。將5個損壞的工具交給血蹄村的奧莫‧雷角。', '', '去莫高雷找血蹄村的奧莫‧雷角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14438 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14438, 'zhTW', '土地之爭', '這片土地上有很多紛爭，$n。我希望你不會像我們的長老一樣經歷那麼多的戰爭，不過我還是希望你去做一件事，讓你可以瞭解到，一個看似不值一提的小小威脅如果不加制止的話，會對我們的領土帶來多大的危害。$B$B白鬃豺狼人已經在西邊的一個洞穴中和血蹄村的南邊紮了營。我們曾試圖和他們交流，卻被他們無禮地拒絕了，而且他們還大肆屠殺莫高雷的野生動物。$B$B現在語言已經不能解決問題了，我們必須有所行動。', '殺死13個白鬃豺狼人，然後回到血蹄村找奧莫‧雷角。', '', '去莫高雷找血蹄村的奧莫‧雷角。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14441 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14441, 'zhTW', '加爾魯什的親筆簽名', '他們說加爾魯什·地獄咆哮是部落最偉大的英雄之一！等我長大了，我也要成為部落的一名英雄！$B$B你認識加爾魯什嗎，$N？你能幫我個忙嗎？能不能幫我要到一份他的親筆簽名？我不知道該如何開口問他，他那樣偉大的人可能不會理我這樣的人……但你可以！你是一名冒險者，就像他一樣！我敢說他一定會毫不猶豫地給你簽名的！$B$B求求你了？', '轉至奧格瑪，為你所監護的兒童取得加爾魯什·地獄咆哮的親筆簽名。', '', '去找獸人孤兒。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14443 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14443, 'zhTW', '破損的劍柄', '這把老舊破碎的劍柄已經失去了往日的光輝。這劍柄在斷掉以前一定是某個工匠的精心傑作。$B$B如此優雅的徽記與劍柄上奇特的珠寶裝飾，在在顯示出這把劍的主人肯定不同凡響。白銀誓盟的人一定有興趣了解如何修復這把藝術品。到銀白聯賽場地南邊的奎爾德拉之眠去找他們的代理人。', '到銀白聯賽場地南邊的奎爾德拉之眠，把破損的劍柄帶給卡拉迪斯‧亮矛。', '', '去找卡拉迪斯‧亮矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14444 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14444, 'zhTW', '龍族的知識', '不會錯的-這劍柄是屬於一把強大且古老的武器，但會是哪一把呢？我不認為我曾見過或者聽過這把劍上的徽記，但這並不表示我們毫無頭緒。$B$B考雷斯塔茲，也就是為人所知的卡薩斯，是奎爾多雷和祈倫托的老朋友。以他豐富的知識與資源，想必能理出些頭緒。到龍眠神殿的最上層找他商議，然後回達拉然找白銀領區的秘法師泰巴林報告結果。', '與龍眠神殿最上層的卡薩斯談話。', '', '去找達拉然的秘法師泰巴林。', '已詢問克拉蘇劍柄的來歷', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14457 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14457, 'zhTW', '奪日者計畫', '我在城底區的線民說：奪日者密探在跟黑市商人買材料。奪日者通常不會對下水道的事情感興趣，顯然另有所圖。$B$B去城底區找出密探，把他解決了，然後檢查一下密探身上有沒有任何資訊可以幫我們找出龍眠之書的下落。絕對不能讓他們搶先一步把書帶回寒冰皇冠。', '取得奪日者的命令。', '', '去找達拉然的秘法師泰巴林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14483 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14483, 'zhTW', '微妙的氣氛(肯定不是愛)', '卡片的內容實在太瘋狂了，裡面詳細記載著感染整個艾澤拉斯的計畫。你應該把這個立刻拿去給其中一個熱砂企業的調查員看!', '把褪色的可愛邀請卡拿給奧格瑪的警探史內卜‧凸栓。', '', '去找影牙城堡的警探史內卜‧凸栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14488 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14488, 'zhTW', '服務到家', '你到了，嗯?很好。我一直在等待幫手。此時不做更待何時，對吧? $B$B帶著這個工具組，深入那個人渣化學製藥公司，把這張傳票交給他們的領導人胡默爾。傳票就在裡面。這可以保護你不被他們施展的化學伎倆給傷害。當時機來臨時，就使用其中一個中和劑，好嗎?', '把法院傳票交給影牙城堡的藥劑師胡默爾。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 20438 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (20438, 'zhTW', '適當的偽裝', '幫助你潛入奪日者聖堂可不是件簡單的差事。只有身著奪日者外袍的人才能獲准進入聖堂。假如我們可以拿到一件，再加上簡單的附魔，就可以完成後續的工作。$B$B你可以在命運織坊上方的露臺找到桑迪‧光爍 。我以前幫過他幾次，所以他欠我一個人情。他在城裡面幫各式各樣的人處理送洗的衣物。或許他有辦法把外袍『借』你一陣子。', '從桑迪‧光爍那裡取得一件借來的外袍。', '', '去找達拉然的秘法師泰巴林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 20439 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (20439, 'zhTW', '與博學者會面', '我已經在外袍上施加了魔法，這應該可讓你暫時避開奪日者聖堂的耳目。你應該有足夠的時間潛入『下流畜生酒店』，並與奪日者的聯繫人，博學者哈索瑞爾會面。$B$B在喬裝的掩護之下，設法取得他們向龍眠者借來的《上古龍鑄劍刃》，並且把書交給我。', '從博學者哈索瑞爾那裡取回上古龍鑄劍刃之書。', '', '去找達拉然的秘法師泰巴林。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24216 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24216, 'zhTW', '戰鬥的召喚：戰歌峽谷', '聯盟真是個陰險的敵人，$N。他們張口閉口說在保護梣谷的森林，以此證明他們對我們貧瘠之地領土的進攻行動是正當的。$B$B今天，我們有機會把敵人徹底趕出部落的領土。去戰歌峽谷，奪回一切本屬於我們的東西！', '在戰歌峽谷戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。', '在戰歌峽谷獲勝', '去找部落戰爭使者。', '', '', '', '', 0);
