INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24220, 'zhTW', '戰鬥的召喚：阿拉希盆地', '事實上，我們在多線作戰，$g小子:小姑娘;，而且我們不能把軍隊部署得太過分佈，否則我們可能會全盤皆輸！$B$B我們需要以天為單位來部署最關鍵的部隊，今天，阿拉希盆地的戰鬥最需要勇敢的士兵！$B$B帶著勝利的訊息回來吧，$n。我們不允許部落狗來威脅屬於我們的資源！', '在阿拉希盆地戰場中獲得一場勝利，然後向任意聯盟主城、冬握湖、達拉然或撒塔斯城中的聯盟准將覆命。', '在阿拉希盆地獲勝', '去找聯盟准將。', '', '', '', '', 0);
