INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24222, 'zhTW', '戰鬥的召喚：風暴之眼DEPRECATED', '無論在哪裡，只要找到敵人，我們就要和他們戰鬥到底，並消滅他們。艾澤拉斯或者外域，這兩者沒有任何區別。$B$B我們不能讓聯盟在風暴之眼取得優勢，今天就去跟他們戰鬥吧……明天也許就太晚了！', '在風暴之眼戰場中獲得一場勝利，然後向任意部落主城、冬握湖、達拉然或撒塔斯城中的部落戰爭使者覆命。', '在風暴之眼獲勝', '去找部落戰爭使者。', '', '', '', '', 0);
