INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24426, 'zhTW', '戰鬥的召喚：奧特蘭克山谷', '我們就快要把雷矛入侵者從奧特蘭克山谷趕走了，因此我們必須調動一切可能的增援力量來幫助霜狼氏族。$B$B一場決定性的勝利可以讓我們騰出足夠的資源在其它戰場上消滅聯盟的那些混蛋。$B$B出發吧，$N。聽從霜狼氏族的號令，去贏得無上的榮耀吧！', '在奧特蘭克山谷戰場中獲得一場勝利，然後向任意部落主城、達拉然、冬握湖或撒塔斯城中的部落戰爭使者覆命。', '在奧特蘭克山谷獲勝', '去找部落戰爭使者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24427 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24427, 'zhTW', '戰鬥的召喚：奧特蘭克山谷', '事實上，我們在多線作戰，$g小子:小姑娘;，而且我們不能把軍隊部署得太過分佈，否則我們可能會全盤皆輸！$B$B我們需要以天為單位來部署最關鍵的部隊，今天，奧特蘭克山谷的戰鬥最需要勇敢的士兵們！$B$B現在就出發吧，$N，去幫助雷矛遠征軍。我們不能就這麼看著霜狼氏族逃脫他們應受的懲罰。', '在奧特蘭克山谷戰場中獲得一場勝利，然後向任意聯盟主城、達拉然、冬握湖或撒塔斯城中的聯盟准將覆命。', '在奧特蘭克山谷獲勝', '去找聯盟准將。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24428 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24428, 'zhTW', '難以置信的挑戰', '你完成了一項不可能的任務。黑龍公主橫屍在你的面前。取下她的頭顱，把它交給『黑爪』加爾德斯。', '將奧妮克希亞的頭顱交給已宰的羔羊地下室裡的『黑爪』加爾德斯。', '', '去找暴風城的黑爪加爾德斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24429 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24429, 'zhTW', '難以置信的挑戰', '你完成了一項不可能的任務。黑龍公主橫屍在你的面前。取下她的頭顱，把它交給阿納克‧火刃。', '將奧妮克希亞的頭顱交給暗影裂口的阿納克‧火刃。', '', '去找奧格瑪的尼爾魯·火刃。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24431 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24431, 'zhTW', '浸水的配方', '看起來這似乎是張調配烈酒的破舊配方。也許達拉然的「勸君更進一杯酒」的老闆對它會有興趣...', '將浸水的配方交給達拉然城的克利斯蒂‧斯托克頓。', '', '去找達拉然的克利斯蒂·斯托克頓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24442 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24442, 'zhTW', '科瓦迪爾的作戰計畫', '看著手中的攻擊計劃，你發現了一張東部王國和卡林多的地圖，且各個重大的據點都被劃上了標記。當你閱讀其中記載的細節，你發現科瓦迪爾的船長們正策劃著一連串的毀滅性攻擊。$B$B根據記載，這些攻擊即將在喚霧者伊格瓦「祈求迷霧之心」後展開。如果你可以取得位於赫魯斯加臺地西邊，喚霧者的洞穴之中所顯現的預兆，並通知審判者瑪瑞爾·真心，那或許你就可以延緩他們的攻擊。', '取得迷霧之心，並將其與科瓦迪爾攻擊計畫一同交給銀白聯賽場地的審判者瑪瑞爾·真心。', '', '去找寒冰皇冠的審判者瑪瑞爾‧真心。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24451 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24451, 'zhTW', '謁見秘法師', '我已經在外袍上施加了魔法，這應該可讓你暫時避開白銀誓盟的耳目。你應該有足夠的時間進入白銀領區的頂樓，並與白銀誓盟的聯繫人秘法師泰巴林會面。$B$B在喬裝的掩護之下，設法取得他們向龍眠者借來的《上古龍鑄劍刃》，並且把書交給我。', '從秘法師泰巴林那裡取回上古龍鑄劍刃之書。', '', '去找達拉然的博學者哈索瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24454 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24454, 'zhTW', '回報卡拉迪斯‧亮矛', '我們必須盡快把書交給卡拉迪斯‧亮矛。你可以帶給他嗎？我不放心讓其他人運送這本書，而你證明了你擁有牽制奪日者的資質。$B$B帶著它前往奎爾德拉之眠，地點在寒冰皇冠的銀白聯賽場地之南。卡拉迪斯將帶著劍等你。一旦鑑定出這把劍的來歷，我們就能將其納入我們的名下。', '將上古龍鑄劍刃交給奎爾德拉之眠的卡拉迪斯‧亮矛。', '', '去找卡拉迪斯‧亮矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24461, 'zhTW', '重鑄劍刃', '我們不能坐視奎爾德拉如今殘破且淪喪的模樣。帶著殘缺的劍身以及破損的劍柄，前往冰冠城塞的薩倫之淵。$B$B巫妖王在那裡使喚奴隸採集、加工以及轉換薩鋼礦。這些灌能的薩鋼錠就是我們重鑄奎爾德拉所需的材料。$B$B你必須收集灌能的薩鋼錠並且奪取鍛造大師之錘，然後將這些東西帶到鍛造大師的鐵砧去重鑄劍刃。', '取得5個灌能薩鋼錠與鍛造大師之錘，並且利用它們製作出重鑄的奎爾德拉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24476 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24476, 'zhTW', '淬鍊劍刃', '奎爾德拉的碎塊終於接合好了，整把劍現在已回歸完整的面貌，但在淬鍊之前仍無法用於戰鬥之中。這把磨損的薩鋼劍刃相當脆弱，只要擊中任何東西就會立刻粉碎。$B$B在冰冠城塞深處的眾魂熔爐是一個可以安心淬鍊劍刃的地方。帶著奎爾德拉到靈魂吞噬者的住所尋找爐缸。把劍刃放進爐缸中淬鍊，然後把它帶來冰封大廳給我。', '去眾魂爐缸淬鍊重鑄的奎爾德拉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24480 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24480, 'zhTW', '倒影大廳', '你已經重鑄和淬鍊完劍刃了，但它依然紋風不動的插在劍鞘之中，完全未展示出它應有的力量。你說這把劍在引導著你，似乎它擁有自我的意志？$B$B你敢把它帶去它所欲之處嗎？這把劍不該如此沉寂與執著，但我擔心若你不將它帶往所欲之處，我們永遠無法查出原因。帶著它前往冰冠城塞裡的倒影大廳，但是請保持警覺！我會在冰封大廳等著你。', '把淬鍛的奎爾德拉帶去倒影大廳裡的劍息之地。', '', '', '將奎爾德拉帶往沉思之殿', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24498 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24498, 'zhTW', '入城之徑', '他們強迫被俘虜的我方士兵在礦區工作！$B$B英雄…請殺掉俘虜他們的人，釋放那些士兵…當我們挑戰天譴領主提朗紐斯的時候，我們會需要他們的援助。', '解放15名聯盟奴隸並擊殺鍛造大師加弗羅斯。', '', '', '聯盟奴隸已解放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24499 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24499, 'zhTW', '受苦靈魂的回聲', '在我方人手嚴重不足的情況下，冒險進入城塞簡直跟送命沒什麼兩樣，但絕對不能錯過如此罕見的機會。$B$B往遠方的那頭清出一條路，鞏固薩倫之淵的入口。我們必須佔領該處，才能讓我方的人員攻入城內。', '殺掉布朗吉姆以及靈魂吞噬者以控制薩倫之淵的入口。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24500, 'zhTW', '巫妖王之怒', '真是令人難以置信，在阿薩斯的王座上，我們或許有可能擊敗他。如果巫妖王真的被擊敗了，那麼誰又該成為下一個巫妖王呢?$B$B雖然局勢仍未明朗，不過你必須找到珍娜，即時逃離巫妖王的魔爪。', '找出珍娜‧普勞德摩爾女士並且逃離倒影大廳。', '', '', '尋找珍娜·普勞德摩爾', '逃離巫妖王', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24507 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24507, 'zhTW', '入城之徑', '他們強迫被俘虜的我方士兵在礦區工作。$B$B殺掉俘虜他們的人，釋放那些士兵，$c...當我們挑戰天譴領主提朗紐斯的時候，我們會需要他們的援助。', '解放15名部落奴隸並擊殺鍛造大師加弗羅斯。', '', '', '部落奴隸已解放', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24508 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24508, 'zhTW', '臨時任務記錄', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24509 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24509, 'zhTW', '臨時任務記錄', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24511 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24511, 'zhTW', '受苦靈魂的回聲', '用這麼少的人手潛入城中相當冒險，但是如此罕見的機會絕對不能錯過。$B$B往遠方的那頭清出一條路，鞏固好薩倫之淵的入口。我們必須佔領那個地方，才能讓我們的人員進入城內。', '殺掉布朗吉姆以及靈魂吞噬者以控制薩倫之淵的入口。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24522 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24522, 'zhTW', '太陽之井之旅', '儘快將奎爾德拉帶到太陽之井，$N。要相信烏瑟爾的話，他說過，當這把劍受到巫妖王邪惡力量的影響時，你不能徹底控制它。你必須轉至奎爾丹納斯島，在那裡，設法進入太陽之井，只有在那你才能淨化這把劍。$B$B太陽之井的守衛不會輕易放行的，所以你必須找到哈杜倫·明翼，他會在那裡巡視那些守衛。', '在奎爾丹納斯島，太陽之井高地入口處同哈杜倫·明翼交談。', '', '去奎爾丹納斯島找晨星村的哈杜倫·明翼', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24535 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24535, 'zhTW', '薩洛瑞安·尋晨者', '$N，如果你真的擁有奎爾德拉，我也許可以讓你進入太陽之井。也許你知道這把劍的歷史，知道薩洛瑞安·尋晨者曾經揮舞它對抗天譴軍團，守衛太陽之井。他犧牲的地方就是今天的死亡之痕。正是因為他捨身血戰，才為他的族人贏得了進行戰爭準備的時間。你可以在這座島的死亡之痕南端找到他的遺蹟。去那裡看看，如果他的靈魂賜予你祝福，我就會讓你進入太陽之井。', '訪問薩洛瑞安·尋晨者的遺體，獲得他的祝福，以使用奎爾德拉。', '', '去奎爾丹納斯島找晨星村的哈杜倫·明翼', '獲得薩洛瑞安的祝福', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24536 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24536, 'zhTW', '事有蹊蹺', '你也注意到那些傢伙了吧，對嗎?多年來，各大節慶的商業活動一向都由熱砂企業一手包辦，突然之間，這群傢伙就這麼湧入了市場。他們可不屬於熱砂企業;公司僱用我來查明事情的真相。這件事看來並不單純，不單是香水而已。 帶著我拿來的儀器，然後去分析一下守衛身上散發的香水氣息。我想知道他們在香水裡頭添加了什麼東西。事情看來不太對勁。', '使用『凸栓的空氣分析器』來測試6名香味濃郁的守衛四周的氣味，然後回奧格瑪找警探史內卜‧凸栓。', '', '去找奧格瑪的警探史內卜‧凸栓。', '已分析噴香守衛', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24541 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24541, 'zhTW', '竊取香水', '我就知道他們圖謀不軌!這東西含有某種思想控制的化學成分，但光憑這種小樣本，我仍無法掌握他們的把柄。我需要的是成品。', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24545 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24545, 'zhTW', '聖潔與墮落', '賦予你此次使命與我的想法背道而馳，$r，感覺此事會因你喪命而劃下句點。$B$B不過別在意我的看法，來進行這件重要的事情吧，我會提供你所需的知識以及資源來助你一臂之力。$B$B你必須回到霜之哀傷洞窟找出『聖光報復』，那把被阿薩斯所遺棄的錘子。用薩鋼來重鑄它，再用巫妖王旗下的憎惡體身上的酸性血液刻蝕其表面，就能為我們的行動奠定基礎。', '在冰冠城塞中，把『聖光報復』、25個原始薩鋼、『腐臉的酸性血液』以及『膿腸的酸性血液』放置在大領主莫格萊尼的符文熔爐。『腐臉的酸性血液』與『膿腸的酸性血液』只能在25人模式的冰冠城塞中取得。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24547 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24547, 'zhTW', '眾魂宴', '暗影之鋒是每個$c最渴望獲得的終極神兵。$B$B你對力量的渴望是否得到滿足了，$r?$B$B<你感受到莫格萊尼銳利的目光。>$B$B我覺得沒有。所以我要給你最後的警告...$B$B你正在進行一個非常險惡的任務。把持你內心的渴望，如果你心存惡念，你的性命，你靈魂的全部，將會被剝奪殆盡。$B$B你手上的武器仍只是一個空殼，尚未發揮出它應有的全部力量。', '大領主達瑞安‧莫格萊尼要你進入冰冠城塞，使用暗影之鋒殺死1000名巫妖王的爪牙。你只能在10人或25人模式副本中吸取靈魂。', '', '', '已將靈魂餵食給暗影之刃', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24548 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24548, 'zhTW', '破碎的王座', '巫妖王的王座曾經是囚禁他的牢獄。那是基爾加丹親自用扭曲虛空中找來的冰晶所製成的。其唯一的目的就是要禁錮急欲報復的耐祖奧之靈魂。$B$B當阿薩斯用霜之哀傷敲開了冰晶之牢，他釋放出耐祖奧的靈魂，然後讓他的靈魂與自己的靈魂合而為一。從那次撞擊中產生的裂片，如今散落在整個城塞。$B$B我需要巫妖王最強大的部下身上持有的碎片，來把力量封印在你的鋒刃之中。', '大領主莫格萊尼要你去收集50個暗影冰晶裂片。暗影冰晶裂片只能在25人困難模式中取得。', '', '去找大領主達瑞安‧莫格萊尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24549 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24549, 'zhTW', '影之哀傷...', '大領主達瑞安‧莫格萊尼要你把暗影之鋒帶給他。', '大領主莫格萊尼要你把暗影之鋒交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24553 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24553, 'zhTW', '淨化奎爾德拉', '我承認，我曾經懷疑你是否真的重鑄了奎爾德拉，而且我也沒想到薩洛瑞安的亡魂會在出現在你面前。你無法了解修復奎爾德拉對我以及我的族人代表著什麼意義。$B$B如同當初的承諾，我會讓你進入太陽之井，而你也會在裡面見到銀月城的領袖。把劍帶去太陽之井的房間，然後把它浸泡在井水中。劍刃就會與你產生連結。當連結產生以後，就帶著它回到奎爾德拉之眠找卡拉迪斯‧亮矛。', '把淬鍛的奎爾德拉浸泡在太陽之井中。當你準備好進入太陽之井高地的時候，請找一名太陽之井守望者談話。', '', '去找寒冰皇冠的卡拉迪斯‧亮矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24554 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24554, 'zhTW', '破損的劍柄', '這把老舊破碎的劍柄已經失去了往日的光輝。這劍柄在斷掉以前一定是某個工匠的精心傑作。$B$B如此優雅的徽記與劍柄上奇特的珠寶裝飾，在在顯示出這把劍的主人肯定不同凡響。奪日者的人一定有興趣了解如何修復這把藝術品。到銀白聯賽場地南邊的奎爾德拉之眠去找他們的代理人。', '到銀白聯賽場地南邊的奎爾德拉之眠，把破損的劍柄帶給米拉連恩‧日炎。', '', '去找米拉連恩‧日炎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24555 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24555, 'zhTW', '龍族的知識', '不會錯的 - 這劍柄是屬於一把強大且古老的武器，但會是哪一把呢？我無法辨識上頭的獨特徽記，不過事情還有解決的辦法。$B$B考雷斯塔茲，也就是為人所知的卡薩斯，是奎爾多雷和祈倫托的老朋友。以他豐富的知識與資源，想必能理出些頭緒。到龍眠神殿的最上層找他商議，然後回達拉然找奪日者聖堂的博學者哈索瑞爾報告結果。', '與龍眠神殿最上層的卡薩斯談話。', '', '去找達拉然的博學者哈索瑞爾。', '已詢問克拉蘇劍柄的來歷', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24556 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24556, 'zhTW', '適當的偽裝', '幫助你潛入白銀領區可不是件簡單的差事。只有身著白銀誓盟外袍的人才能獲准進入聖堂。假如我們可以拿到一件，再加上簡單的附魔，就可以完成後續的工作。$B$B你可以在命運織坊上方的露臺找到桑迪‧光爍。我以前幫過他幾次，所以他欠我一個人情。他在城裡面幫各式各樣的人處理送洗的衣物。或許他有辦法把外袍『借』你一陣子。', '從桑迪‧光爍那裡取得一件借來的外袍。', '', '去找達拉然的博學者哈索瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24557 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24557, 'zhTW', '白銀誓盟計畫', '我在城底區的線民發現有白銀誓盟的密探在咒語與烏鴉酒店蒐集情報。白銀誓盟的人通常不會在下水道出沒，所以他們一定在密謀些什麼。$B$B前去城底區找出這個密探，並解決他。檢查一下他身上有沒有任何資訊可以幫我們找出龍眠之書的下落。我們不能讓那些白銀誓盟的傻瓜搶先一步把書帶回寒冰皇冠。', '取得白銀誓盟命令。', '', '去找達拉然的博學者哈索瑞爾。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24558 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24558, 'zhTW', '回報米拉連恩‧日炎', '我們必須盡快把書交給米拉連恩‧日炎。你可以帶給他嗎？我不放心讓其他人運送這本書，而你證明了你擁有牽制白銀誓盟的資質。$B$B帶著它前往奎爾德拉之眠，地點在寒冰皇冠的銀白聯賽場地之南。米拉連恩將等待著你。如果他能鑑定出這把劍的來歷，我們就能將其納入埃薩‧奪日者的名下，並且讓達拉然以及聯盟們看到，我們將一馬當先對抗巫妖王。', '將上古龍鑄劍刃交給奎爾德拉之眠的米拉連恩‧日炎。', '', '去找米拉連恩‧日炎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24559 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24559, 'zhTW', '重鑄劍刃', '我們不能坐視奎爾德拉如今殘破且淪喪的模樣。帶著殘缺的劍身以及破損的劍柄，前往冰冠城塞的薩倫之淵。$B$B巫妖王在那裡使喚奴隸採集、加工以及轉換薩鋼礦。這些灌能的薩鋼錠就是我們重鑄奎爾德拉所需的材料。$B$B你必須收集灌能的薩鋼錠並且奪取鍛造大師之錘，然後將這些東西帶到鍛造大師的鐵砧去重鑄劍刃。', '取得5個灌能薩鋼錠與鍛造大師之錘，把它們跟奎爾德拉的殘塊組合起來，並且製作出重鑄的奎爾德拉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24560 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24560, 'zhTW', '淬鍊劍刃', '奎爾德拉的碎塊終於接合好了，整把劍現在已回歸完整的面貌，但在淬鍊之前仍無法用於戰鬥之中。這把磨損的薩鋼劍刃相當脆弱，只要擊中任何東西就會立刻粉碎。$B$B在冰冠城塞深處的眾魂熔爐是一個可以安心淬鍊劍刃的地方。帶著奎爾德拉到靈魂吞噬者的住所尋找爐缸。把劍刃放進爐缸中淬鍊，我會在冰封大廳等著你。', '去眾魂爐缸淬鍊重鑄的奎爾德拉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24561 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24561, 'zhTW', '倒影大廳', '你已經重鑄和淬鍊完劍刃了，但它依然紋風不動的插在劍鞘之中，跟一般的劍沒什麼兩樣。你說這把劍在引導著你，似乎它擁有自我的意志？$B$B你敢把它帶去它所欲之處嗎？這把劍不該如此沉寂與執著，但我擔心若你不將它帶往所欲之處，我們永遠無法查出原因。帶著它前往冰冠城塞裡的倒影大廳，但是請保持警覺。我會在冰封大廳等著你。', '把奎爾德拉帶去倒影大廳裡的劍息之地。', '', '', '將奎爾德拉帶往沉思之殿', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24562 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24562, 'zhTW', '前往太陽之井', '帶著奎爾德拉盡快前往太陽之井，$n。相信烏瑟的話吧，他說只要這把劍仍受巫妖王的邪惡所影響，你遲早會喪失操控它的權力。你必須前往奎爾達納斯之島，尋找太陽之井的入口，你可以在那裡淨化這把劍。$B$B守衛不會讓你進入太陽之井高地，但是你可以去認識一下赫杜倫‧亮翼，在那裡視察守衛的人。', '在奎爾達納斯之島的太陽之井高地入口處與赫杜倫‧亮翼談話。', '', '去找奎爾丹納斯島的赫杜倫·亮翼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24563 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24563, 'zhTW', '薩洛瑞安‧曦尋者', '你就是跟米拉連恩‧日炎合作的人嗎？我知道一個方法，可以讓我們測試劍刃。$B$B如果你清楚這把劍的來歷，你就會回想起，它曾經是薩洛瑞安‧曦尋者在抵抗天譴軍團入侵太陽之井時的佩劍。他拼死奮戰為同袍爭取準備的時間，而他倒下的地方如今稱作死亡之痕。你可以在這座小島上的死亡之痕最南邊找到他的遺骸。去那個地方看看，如果他的亡魂給你祝福的話，我就會允許你進入太陽之井。', '尋找薩洛瑞安‧曦尋者的遺骸，並取得他的祝福以使用奎爾德拉。', '', '去找奎爾丹納斯島的赫杜倫·亮翼。', '已取得薩羅林的祝福', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24564 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24564, 'zhTW', '淨化奎爾德拉', '太陽之井和奎爾德拉流浪的終點正等待著你，$n。$B$B你會發現奎爾薩拉斯的攝政王洛索瑪‧塞隆和大博學者洛摩斯站在一起。請提防他們，別讓他們的政治陰謀陷害了你。$B$B反言之，把焦點一直放在你的任務上。當你準備好進入太陽之井高地的時候，請找一名太陽之井守望者談話。然後將奎爾德拉浸泡在太陽之井中來完成復原劍刃的工作。然後回到奎爾德拉之眠，把劍刃拿給米拉連恩‧日炎看。', '把淬鍛的奎爾德拉浸泡在太陽之井中。當你準備好進入太陽之井高地的時候，請找一名太陽之井守望者談話。', '', '去找寒冰皇冠的米拉連恩‧日炎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24576 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24576, 'zhTW', '善意的溝通...', '<蘿卡聽你述說追捕史尼佛的原因，臉上浮現著厭惡的表情。>$B$B你的意思是說，這陣子我是被鍊金師下了咒?我真不敢相信我愛上那種大騙子!如果再讓我見到那個偷雞摸狗的小哥布林，我絕對會把他撕成碎片! $B$B達成任務之後，他就會前往奧格瑪城門外的東部飛艇塔!$n，無論如何，你都不能讓他就這樣搭上飛艇逃跑!$B$B趕快前往飛艇塔，不然你會錯失逮到他的機會!', '到奧格瑪中央斷崖上的飛艇塔，向史尼佛‧鏽彈質詢有關供給品的事。並且帶回你從他那裡找出來的證據。', '', '去找奧格瑪的警探史內卜‧凸栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24579 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24579, 'zhTW', '撒爾薩里安必須死!', '『黑曜守護者』撒爾薩里安，守護著暮光飛龍的龍蛋。他居住在黑曜聖所的守護巨龍之間，其位於龍眠神殿下方。$B$B六法議會已經頒布法令，要取撒爾薩里安的命!', '殺死撒爾薩里安。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24580 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24580, 'zhTW', '阿努比瑞克漢必須死!', '阿努比瑞克漢，曾經是奈幽蟲族王國中至高無上的蜘蛛領主，它已經被巫妖王所降服，並且腐化成不死之身。$B$B如今他成為地穴領主，在他的起居室中鎮守著納克薩瑪斯的蜘蛛區，並且幫助科爾蘇加德擬定策略。$B$B六法議會已經下令，要取阿努比瑞克漢的命!', '殺死阿努比瑞克漢。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24581 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24581, 'zhTW', '『瘟疫使者』諾斯必須死!', '『瘟疫使者』諾斯，一個叛徒跟懦夫!對那些受到天譴蹂躪的眾多冤魂而言，他的罪行僅次於巫妖王本人!$B$B趕快前去納克薩瑪斯。他就躲在納克薩瑪斯的瘟疫區中的那些不死爪牙身後。$B$B消滅他!六法議會已經下令，要取諾斯的命!', '殺死『瘟疫使者』諾斯。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24582 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24582, 'zhTW', '講師拉祖維斯必須死!', '講師拉祖維斯志得意滿地巡視著納克薩瑪斯的軍事區。傳聞中，只有經由他鍛鍊出來的死亡騎士才能禁得起他超凡的一擊。$B$B你跟你的團隊要去證明大家都錯了。$B$B六法議會已經下令，要取拉祖維斯的命!', '殺死講師拉祖維斯。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24583 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24583, 'zhTW', '縫補者必須死!', '俗稱『戰神化身』的縫補者是一個終極的憎惡體。它在龍骨荒野中對我們的部隊造成了極大的傷亡。$B$B我要你去召集同伴並且進入納克薩瑪斯的傀儡區，並且拆除掉那些傀儡。$B$B六法議會已經下令，要取縫補者的命!', '殺死縫補者。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24584 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24584, 'zhTW', '瑪里苟斯必須死!', '我們的資源遭到濫用了。號稱織法者的瑪里苟斯正在吸取這世上所有的魔法，並且把魔法凝聚在永恆之眼。少了魔法的力量，我們就完蛋了。$B$B$c，該把奧核之戰畫下句點了。六法議會已經下令，要取瑪里苟斯的命!', '殺死瑪里苟斯。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24585 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24585, 'zhTW', '烈焰戰輪必須死!', '在構築之地坐落著奧杜亞的第一道防線:烈焰戰輪。$B$B祈倫托得到了一個消息，指出這個由守護者製造的機器即將被運送到一個不明的地點，然後放出來毀滅艾澤拉斯上的凡人們。$B$B這種事情不能發生。六法議會已經下令，要取烈焰戰輪的命!', '殺死烈焰戰輪。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24586 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24586, 'zhTW', '銳鱗必須死!', '銳鱗通常蟠踞在奧杜亞的巨熔爐附近。然而，最近她一直對著泰坦建築群外頭的地面上噴火。$B$B雖然育母的故事是場悲劇，但是她對北裂境眾生造成的威脅迫在眉睫。六法議會已經下令，要取銳鱗的命!', '殺死銳鱗。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24587 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24587, 'zhTW', '『火爐之主』伊格尼司必須死!', '偉大的火巨人，『火爐之主』伊格尼司在奧杜亞巨熔爐內辛勤的工作著。在洛肯的命令下，伊格尼司製造的武器有著恐怖的威力。$B$B六法議會已經下令，要取伊格尼司的命!', '殺死『火爐之主』伊格尼司。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24588 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24588, 'zhTW', 'XT-002拆解者必須死!', '身為彌米倫的另一個奇作，XT-002拆解者竟然認為它就是守護者之子。別被它天真無邪的偽裝給騙了。它是一台殺人機器!$B$B你可以在奧杜亞的廢料場找到拆解者。六法議會已經下令，要取XT-002拆解者的命!', '殺死XT-002拆解者。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24589 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24589, 'zhTW', '賈拉克瑟斯領主必須死!', '大法師泰彌亞預見了一個駭人的事件即將發生。在十字軍試煉中，有一個愚蠢的地精將意外地召喚出燃燒軍團的埃雷達爾領主。$B$B當事情發生的時候你必須在場，$c。如果賈拉克瑟斯領主逃走了，他將會打開傳送門，並且把燃燒軍團再次送進我們的世界。$B$B六法議會已經下令，要取賈拉克瑟斯領主的命!', '殺死賈拉克瑟斯領主。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24590 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24590, 'zhTW', '瑪洛嘉領主必須死!', '瑪洛嘉領主是位居尖塔之間的冰封王座守護者。巫妖王用上千名受害冒險者的骨頭把它拼湊出來，同時瑪洛嘉也持有冰封王座的力量。$B$B如果不把這骸骨怨靈消滅掉的話，進佔冰冠城塞就毫無希望。$B$B六法議會已經頒布法令，要取瑪洛嘉領主的命!', '殺死瑪洛嘉領主。此任務可於任何難度或任何規模的團隊中完成。', '', '去找達拉然的大法師朗達拉克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24594 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24594, 'zhTW', '淨化奎爾德拉', '太陽之井和奎爾德拉流浪的終點正等待著你，$n。$B$B你會發現奎爾薩拉斯的攝政王洛索瑪‧塞隆和大博學者洛摩斯站在一起。請提防他們，別讓他們的政治陰謀陷害了你。$B$B反言之，把焦點一直放在你的任務上。當你準備好進入太陽之井高地的時候，請找一名太陽之井守望者談話。然後將奎爾德拉浸泡在太陽之井中來完成復原劍刃的工作。然後回到奎爾德拉之眠，把劍刃拿給米拉連恩‧日炎看。', '把受污染的奎爾德拉浸泡在太陽之井中。當你準備好進入太陽之井高地的時候，請找一名太陽之井守望者談話。', '', '去找寒冰皇冠的米拉連恩‧日炎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24595 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24595, 'zhTW', '淨化奎爾德拉', '我承認，我曾經懷疑你是否真的重鑄了奎爾德拉，而且我也沒想到薩洛瑞安的亡魂會在出現在你面前。你無法了解修復奎爾德拉對我以及我的族人代表著什麼意義。$B$B如同當初的承諾，我會讓你進入太陽之井，而你也會在裡面見到銀月城的領袖。把劍帶去太陽之井的房間，然後把它浸泡在井水中。一但劍刃復原了，就帶著它回到奎爾德拉之眠找卡拉迪斯‧亮矛。', '把受污染的奎爾德拉浸泡在太陽之井中。當你準備好進入太陽之井高地的時候，請找一名太陽之井守望者談話。', '', '去找寒冰皇冠的卡拉迪斯‧亮矛。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24596 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24596, 'zhTW', '淨化奎爾德拉', '太陽之井和奎爾德拉流浪的終點正等待著你，$n。$B$B你會發現奎爾薩拉斯的攝政王洛索瑪‧塞隆和大博學者洛摩斯站在一起。請提防他們，別讓他們的政治陰謀陷害了你。$B$B反言之，把焦點一直放在你的任務上。將奎爾德拉浸泡在太陽之井中來完成復原劍刃的工作，然後回到奎爾德拉之眠找米拉連恩‧日炎談話。當你準備好進入太陽之井高地的時候，請找一名太陽之井守望者談話。', '把受污染的奎爾德拉浸泡在太陽之井中。當你準備好進入太陽之井高地的時候，請找一名太陽之井守望者談話。', '', '去找寒冰皇冠的米拉連恩‧日炎。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24597 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24597, 'zhTW', '給暴風城特使的禮物', '你想為暴風城的特使製作可愛符咒手鐲嗎？我相信他一定會很開心。$B$B你已經有可愛符咒收集工具組了嗎？', '將可愛符咒手鐲獻給暴風城的特使歐德溫‧艾爾斯頓。', '', '去找瓦里安·烏瑞恩國王。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24598 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24598, 'zhTW', '淨化奎爾德拉', '太陽之井和奎爾德拉流浪的終點正等待著你，$n。$B$B你會發現奎爾薩拉斯的攝政王洛索瑪‧塞隆和大博學者洛摩斯站在一起。請提防他們，別讓他們的政治陰謀陷害了你。$B$B反言之，把焦點一直放在你的任務上。將奎爾德拉浸泡在太陽之井中來完成復原劍刃的工作，然後回到奎爾德拉之眠，把劍刃拿給米拉連恩‧日炎看。當你準備好進入太陽之井高地的時候，請找一名太陽之井守望者談話。', '把淬鍛的奎爾德拉浸泡在太陽之井中。當你準備好進入太陽之井高地的時候，請找一名太陽之井守望者談話。', '', '去找寒冰皇冠的米拉連恩‧日炎。', '', '', '', '', 0);
