INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24609, 'zhTW', '給鐵爐堡國王的禮物', '你想做一個可愛符咒手鐲送給穆拉丁‧銅鬚嗎？我相信他會大吃一驚的。$B$B你已經有可愛符咒收集工具組了嗎？', '將可愛符咒手鐲獻給鐵爐堡的穆拉丁‧銅鬚。', '', '去找丹莫羅的國王麥格尼·銅鬚。', '', '', '', '', 0);
