INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24610, 'zhTW', '給伊露恩的高階女祭司的禮物', '你想做一個可愛符咒手鐲送給伊露恩的高階女祭司嗎？我相信他會大吃一驚的。$B$B你已經有可愛符咒收集工具組了嗎？', '將可愛符咒手鐲獻給達納蘇斯的泰蘭妲‧語風。', '', '去達納蘇斯找神殿花園的泰蘭妲·語風。', '', '', '', '', 0);
