INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24611, 'zhTW', '給預言者的禮物', '你想做一個可愛符咒手鐲送給艾克索達的預言者嗎？我相信他會大吃一驚的。$B$B你已經有可愛符咒收集工具組了嗎？', '將可愛符咒手鐲獻給艾克索達的預言者費倫。', '', '去找預言者費倫。', '', '', '', '', 0);
