INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24613, 'zhTW', '給女妖之王的禮物', '你想做一個可愛符咒手鐲送給女妖之王嗎？我相信他會大吃一驚的。$B$B你已經有可愛符咒收集工具組了嗎？', '將可愛符咒手鐲獻給幽暗城的希瓦娜斯‧風行者女士。', '', '去找希瓦娜斯·風行者女士。', '', '', '', '', 0);
