INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24614, 'zhTW', '給牛頭大酋長的禮物', '你想做一個可愛符咒手鐲送給牛頭人酋長嗎？我相信他會大吃一驚的。$B$B你已經有可愛符咒收集工具組了嗎？', '將可愛符咒手鐲獻給雷霆崖的貝恩‧血蹄。', '', '去莫高雷找雷霆崖的凱恩·血蹄。', '', '', '', '', 0);
