INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24615, 'zhTW', '給奎爾薩拉斯攝政王的禮物', '你想做一個可愛符咒手鐲送給奎爾薩拉斯攝政王嗎？我相信他會大吃一驚的。$B$B你已經有可愛符咒收集工具組了嗎？', '將可愛符咒手鐲獻給銀月城的洛索瑪‧塞隆。', '', '去找銀月城的洛索瑪·塞隆。', '', '', '', '', 0);
