INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24629, 'zhTW', '完美香氛', '你看起來就是一個真正的行動家，$c。想不想一起搞個雙贏的生意？$B$B王冠公司要把節日主題商品的試用品，儘可能地提供給所有的潛在客戶。只要幫我們分享這份愛心，在購買一些優質的王冠公司商品時，就可以享有折扣！$B$B朋友，你出時間，我們賺錢。意下如何？', '對著10個人使用王冠香水罐。', '', '', '已提供樣本', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24635 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24635, 'zhTW', '典雅古龍', '你看起來就是個行動派，$c。要不要來打個交道？$B$B王冠公司要把節日主題商品的試用品儘可能地提供給所有的潛在客戶。只要幫我們分享這份愛心，你就可以獲得王冠公司的夢幻商品！$B$B朋友，你出時間，我們賺錢。你覺得呢？', '對著10個人使用王冠古龍水罐。', '', '', '已提供樣本', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24636 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24636, 'zhTW', '甜食總動員', '我知道你在尋找機會，$n。要不要一起賺些小錢呢?$B$B王冠公司要把節日主題商品的試吃品發送給城內所有的潛在客戶。幫我們分享這份愛心的話，我們就會把這些令人驚奇的王冠公司商品分享給你!$B$B朋友，你出時間，我們賺錢。一言為定囉?', '從王冠巧克力取樣器裡分送試吃品給10個人。', '', '', '已提供樣本', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24638 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24638, 'zhTW', '粉碎皇冠藥劑公司', '這賬本上提到了多處地點，我需要你前去調查並採取相應的行動，夥計。不能再拖下去了。$B$B這是我要你調查的一處地點：就在奧格瑪大門外，西面！他們肯定不會幹什麼好事。到那兒去解決掉他們。$B$B噢，對了，如果你發現了某些危險的大玩意兒需要當場銷燬的話，就朝它丟這個炸彈。', '消滅5個皇冠僕從，並使用滑栓的氪金炸彈摧毀在杜洛塔的奧格瑪大門西方的一臺藥劑車。然後返回奧格瑪，去見偵探斯奈普·滑栓。', '', '轉至奧格瑪，去找力量谷的偵探斯奈普·滑栓。', '摧毀藥劑車', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24645 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24645, 'zhTW', '摧毀化學製藥公司', '朋友，這帳本上記載著許多地點，我要你去一一調查，並且採取開行動。這事情已經拖夠久了。$B$B我要你去調查這個項目:它就在銀松森林裡的安伯米爾外頭。這絕不是什麼好事情。去那裡痛扁他們一頓吧。$B$B噢，如果你發現任何嚴重的問題，其危險的程度是必須要消滅掉的，就用這個炸彈炸掉它。', '到銀松森林裡的安伯米爾外頭，殺掉5名王冠公司暴徒，並且使用凸栓的克銀炸彈來摧毀一台化學貨車，然後回奧格瑪找警探史內卜‧凸栓。', '', '去找奧格瑪的力量谷的警探史內卜‧凸栓。', '化學馬車已摧毀', '', '', '', 0);
