INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24655, 'zhTW', '事有蹊蹺', '你也注意到那些傢伙了吧，對嗎?多年來，各大節慶的商業活動一向都由熱砂企業一手包辦，突然之間，這群傢伙就這麼湧入了市場。他們可不屬於熱砂企業;公司僱用我來查明事情的真相。這件事看來並不單純，不單是香水而已。 帶著我拿來的儀器，然後去分析一下守衛身上散發的香水氣息。我想知道他們在香水裡頭添加了什麼東西。事情看來不太對勁。', '使用『凸栓的空氣分析器』來測試6名香味濃郁的守衛四周的氣味，然後回暴風城找巡官史尼卜‧凸栓。', '', '去找暴風城的巡官史尼卜‧凸栓。', '已分析噴香守衛', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24656 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24656, 'zhTW', '竊取香水', '我就知道他們圖謀不軌！這東西含有某種思想控制的化學成分，但光憑這種小樣本，我仍無法掌握他們的把柄。我需要的是成品。', '', '', '', '', '', '', '', 0);
