INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24657, 'zhTW', '善意的溝通...', '<當瑪莉恩聽到你追捕史尼佛的原因，她的臉上浮現驚慌的神情。>$B$B你的意思是說，他可能對我下了藥?噢!我真不敢相信我愛上那種大騙子! $B$B一但他達成任務之後，就會前往碼頭搭上開往南海的船! $n，無論如何，你都不能讓他把這一切拋諸腦後! $B$B趕快前去暴風港，不然你會錯失逮到他的機會!', '到暴風港向史尼佛‧鏽彈質詢有關供給品的事。並且帶回你從他那裡找出來的證據。', '', '去找暴風城的巡官史尼卜‧凸栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24658 AND `locale` = 'zhTW';
