INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24661, 'zhTW', '再次使用', '朋友，這本帳簿上記錄了許多地點，我需要你對這些地點進行調查和採取行動。這可是一件相當繁重的工作。$B$B我現在就需要你去檢視一個地方：它就在奧格瑪大門外，朝西的方向！這可不太好。趕快到那裡去進行偵查。$B$B如果你看到一個非常巨大和危險，需要摧毀的東西，就把這顆炸彈向那裡扔過去。', '消滅5個皇冠僕從，並使用斯奈普·道爾的氪金炸彈摧毀杜洛塔，奧格瑪大門西方的一臺藥劑車。然後返回奧格瑪，去見名偵探斯奈普·道爾。', '', '去找名偵探斯奈普·道爾。', '摧毀藥劑車', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24662 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24662, 'zhTW', '摧毀化學製藥公司', '朋友，這帳本上記載著許多地點，我要你去一一調查，並且採取行動。這事情已經拖夠久了。$B$B我要你去調查這個項目:它就在塵泥沼澤裡塞拉摩外頭的警戒崗哨。別這樣看著我，好嗎?這對我們而言同樣是個問題。去那裡痛扁他們一頓吧。$B$B噢，如果你發現任何嚴重的問題，其危險的程度是必須要消滅掉的，就用這個炸彈炸掉它。', '到塵泥沼澤的塞拉摩外頭，殺掉5名王冠公司流氓，並且使用凸栓的克銀炸彈來摧毀一台化學貨車，然後回暴風城找巡官史尼卜‧凸栓。', '', '去找暴風城的貿易區的巡官史尼卜‧凸栓。', '化學馬車已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24663 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24663, 'zhTW', '粉碎皇冠藥劑公司', '這賬本上提到了多處地點，我需要你前去調查並採取相應的行動，夥計。不能再拖下去了。$B$B這是我要你調查的一處地點：就在辛特蘭的鷹巢山的東面。別那樣看著我，好嗎？這我們大家都是個問題。他們肯定不會幹什麼好事。到那兒去解決掉他們。$B$B噢，對了，如果你發現了某些危險的大玩意兒需要當場銷燬的話，就朝它丟這個炸彈。', '消滅5個皇冠密探，並使用滑栓的氪金炸彈摧毀在辛特蘭鷹巢山東面的一臺藥劑車。然後返回暴風城，去見探員斯尼普·滑栓。', '', '轉至暴風城，去找貿易區的探員斯尼普·滑栓。', '摧毀藥劑車', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24664 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24664, 'zhTW', '摧毀化學製藥公司', '朋友，這帳本上記載著許多地點，我要你去一一調查，並且採取行動。這事情已經拖夠久了。$B$B我要你去調查這個項目:它就在冬泉谷，永望鎮的東邊。喔，這純屬私事。去那裡痛扁他們一頓吧。$B$B噢，如果你發現任何嚴重的問題，其危險的程度是必須要消滅掉的，就用這個炸彈炸掉它。', '到冬泉谷的永望鎮東邊，殺掉5名王冠公司灑水員，並且使用凸栓的克銀炸彈來摧毀一台化學貨車，然後回暴風城找巡官史尼卜‧凸栓。', '', '去找暴風城的貿易區的巡官史尼卜‧凸栓。', '化學馬車已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24665 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24665, 'zhTW', '摧毀化學製藥公司', '朋友，這帳本上記載著許多地點，我要你去一一調查，並且採取行動。這事情已經拖夠久了。$B$B我要你去調查這個項目:這看起來是在泰洛卡森林，撒塔斯城的東邊。去那裡痛扁他們一頓吧。$B$B噢，如果你發現任何嚴重的問題，其危險的程度是必須要消滅掉的，就用這個炸彈炸掉它。', '到泰洛卡森林的撒塔斯城東邊，殺掉5名王冠公司部屬，並且使用凸栓的克銀炸彈來摧毀一台化學貨車，然後回暴風城找巡官史尼卜‧凸栓。', '', '去找暴風城的貿易區的巡官史尼卜‧凸栓。', '化學馬車已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24666 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24666, 'zhTW', '摧毀化學製藥公司', '朋友，這帳本上記載著許多地點，我要你去一一調查，並且採取行動。這事情已經拖夠久了。$B$B我要你去調查這個項目:這看起來是在水晶之歌森林裡的凋落樹林，曦光之鏡的西北邊。去那裡痛扁他們一頓吧。$B$B噢，如果你發現任何嚴重的問題，其危險的程度是必須要消滅掉的，就用這個炸彈炸掉它。', '到水晶之歌森林的凋落樹林，殺掉5名王冠公司噴灑者，並且使用凸栓的克銀炸彈來摧毀一台化學貨車，然後回暴風城找巡官史尼卜‧凸栓。', '', '去找暴風城的貿易區的巡官史尼卜‧凸栓。', '化學馬車已摧毀', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24710 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24710, 'zhTW', '逃離深淵', '我們必須經由主要的道路穿過洞窟，前往提朗紐斯所在的高地。$B$B他要是想阻止我們進入城塞本體，就不得不在那裡與我們一戰。$B$B出發吧，$c。當你迎戰提朗紐斯的時候，我與我的同伴會與你們並肩作戰。', '殺掉天譴領主提朗紐斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24712 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24712, 'zhTW', '逃離深淵', '我們必須經由主要的道路穿過洞窟，前往提朗紐斯所在的高地。$B$B在那裡，他不得不與我們決一死戰，好阻止我們進入城塞本體。$B$B出發吧，$c。當你迎戰提朗紐斯的時候，我與我的同伴將會與你們並肩作戰。', '殺掉天譴領主提朗紐斯。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24743 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24743, 'zhTW', '暗影之鋒', '', '聽好了，$c。接受這把武器，你的命運就此註定。$B$B戰勝它，或被它吞噬。$B$B是我讓你踏上這條路的，因此你是我個人的責任。如果你動搖了，我有責任終結你的性命，讓你解脫。$B$B記住我的話，$r，不要失敗。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24745 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24745, 'zhTW', '微妙的氣氛(肯定不是愛)', '卡片的內容實在太瘋狂了，裡面詳細記載著感染整個艾澤拉斯的計畫。你應該馬上把這個拿去給其中一個熱砂企業的調查員看!', '把褪色的可愛邀請卡拿給暴風城的巡官史尼卜‧凸栓。', '', '去找影牙城堡的巡官史尼卜‧凸栓。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24746 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24746, 'zhTW', '重複利用', '', '', '', '返回。', '被分析的灑上香水的鎮民', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24748 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24748, 'zhTW', '巫妖王的末日', '影之哀傷;一把嶄新的武器已經邁入這世界歷史的長河之中，並且在無與倫比的宿命之中重生。$B$B佩帶這把武器讓你肩負了重大的責任，而且進攻的號角即將響起。$B$B帶著這把傳說神兵向敵人邁進吧。為那些在殘酷戰役中喪命的無數英雄報仇雪恨。讓他們受難的靈魂安息。$B$B把自己武裝起來，$c，讓影之哀傷完成它被創造出來的使命吧。', '大領主莫格萊尼要你去冰冠城塞殺掉巫妖王。', '', '去找大領主達瑞安‧莫格萊尼。', '已擊敗巫妖王', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24749 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24749, 'zhTW', '穢邪之能', '在你的武器發揮它所有潛能之前，必須賦予它象徵性的力量。首先就是穢邪之力。$B$B你得找出一個名為普崔希德教授的人，並且殺掉他，但是這不是你主要的目標。你必須使用他的資源來對付他。$B$B想辦法吸收他的突變泥漿。利用這些穢物來為你的武器灌輸穢邪之力。事成之後，我才會交代你下一個任務。', '大領主莫格萊尼要你為暗影之鋒注入穢邪威能，並且殺掉普崔希德教授。此任務只能夠在25人模式的冰冠城塞中完成。', '為暗影之刃注入邪穢之力後擊殺普崔希德', '去找大領主達瑞安‧莫格萊尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24756 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24756, 'zhTW', '血魄之能', '你的武器已經準備好要接受血魄的力量了。$B$B你必須迎戰菈娜薩爾女王，並且用肉身承受住她血魄之鏡的攻擊。這種力量會促使暗影之鋒開始啜飲最靠近它的生物之血。這個生物可能會是你，$r。$B$B一但鋒刃甦醒之後，就讓女王的狂亂嗜血佔據你的身體，並餵食它三次以順從其渴求，隨後就用極盡羞辱的方式殺掉女王$B$B當巫妖王等待他的宿命降臨時，希望她的尖叫聲會刺痛他的雙耳。', '大領主莫格萊尼要你為暗影之鋒注入血魄的力量，並且擊敗菈娜薩爾女王。此任務只能夠在25人模式的冰冠城塞中完成。', '為暗影之刃注入鮮血之力後擊敗拉娜什', '去找大領主達瑞安‧莫格萊尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24757 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24757, 'zhTW', '冰霜之能', '暗影之鋒已經準備好要接受最後一次灌能了。$B$B敵人的坐騎，辛德拉苟莎必須倒下。但是在她倒下之前，你必須承受住4次冰霜吐息攻擊，而且不能倒下。$B$B一但失去那條龍，就沒有東西能夠插手你跟巫妖王之間的對決了。', '大領主莫格萊尼命令你去殺掉辛德拉苟莎，並且在佩帶暗影之鋒的期間，承受4次冰霜吐息攻擊。此任務只能夠在25人模式的冰冠城塞中完成。', '為暗影之刃注入寒冰之力後擊殺辛達苟薩', '去找大領主達瑞安‧莫格萊尼。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24788 AND `locale` = 'zhTW';
