INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24795, 'zhTW', '白銀誓盟的勝利', '儘管菈娜索爾女王對你冷嘲熱諷，你還是復原了奎爾德拉，$n。長久以來，取回奎爾德拉一直是我們的夢想。$B$B白銀誓盟與所有辛多雷欠你一份感恩之情。$B$B因為你是一個$c，劍刃似乎認為你缺乏劍術訓練，所以並沒有跟你產生連結。既然這樣，它的下一個主人會在哪裡呢？也許銀白十字軍可以找到合適的人。到北邊的銀白聯賽場地，以白銀誓盟的名義把劍交給審判者瑪瑞爾‧真心。', '到銀白聯賽場地，把復原的奎爾德拉交給審判者瑪瑞爾‧真心。', '', '去找銀色比武場中銀色大帳的裁決者瑪蕾爾·圖哈特。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24796 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24796, 'zhTW', '白銀誓盟的勝利', '儘管菈娜薩爾女王對你冷嘲熱諷，你還是復原了奎爾德拉，$n。長久以來，取回奎爾德拉一直是我們的夢想。$B$B白銀誓盟與所有辛多雷欠你一份感恩之情。$B$B等你從太陽之井歸還之後，白銀誓盟的領袖凡蕾莎‧風行者邀請你見她一面。帶著奎爾德拉前往達拉然，她會在紫羅蘭城塞等候著你，$n。', '到達拉然的紫羅蘭城塞，把復原的奎爾德拉交給凡蕾莎‧風行者。', '', '去找達拉然的凡蕾莎·風行者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24797 AND `locale` = 'zhTW';
