INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24798, 'zhTW', '奪日者的勝利', '為了奪日者與辛多雷的榮耀，奎爾德拉終於復原了! $B$B銀月城的所有人都將慶祝你成為了英雄，$n。$B$B因為你是一個$c，劍刃似乎認為你缺乏劍術訓練，所以並沒有跟你產生連結。既然這樣，它的下一個主人會在哪裡呢? 由於還沒有傑出的辛多雷自告奮勇。那我們就尋求一下銀白十字軍的建議吧。到北邊的銀白聯賽場地，以奪日者的名義把劍交給審判者瑪瑞爾‧真心。', '到銀白聯賽場地，把復原的奎爾德拉交給審判者瑪瑞爾‧真心。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24799 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24799, 'zhTW', '奪日者的勝利', '為了奪日者的榮耀，奎爾德拉終於復原了！ $B$B部落的所有人都將慶祝你成為了英雄，$n。$B$B因為你是一個$c，劍刃似乎認為你缺乏劍術訓練，所以並沒有跟你產生連結。既然這樣，它的下一個主人會在哪裡呢？ 這使我難掩失望之情，因為我希望他會是個傑出的辛多雷。讓我們尋求一下銀白十字軍的建議吧。到北邊的銀白聯賽場地，以白銀誓盟的名義把劍交給審判者瑪瑞爾‧真心。', '到銀白聯賽場地，把復原的奎爾德拉交給審判者瑪瑞爾‧真心。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24800 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24800, 'zhTW', '奪日者的勝利', '為了奪日者與辛多雷的榮耀，奎爾德拉終於復原了! $B$B銀月城的所有人都稱頌你成為了英雄，部落的所有人也這麼認為。$B$B等你從太陽之井歸來之後，奪日者的領袖大法師埃薩‧奪日者想邀請你見他一面。帶著奎爾德拉儘快前往達拉然的紫羅蘭城塞，$n。大法師希望能夠親自恭賀你!', '到達拉然紫羅蘭城塞，把復原的奎爾德拉交給大法師埃薩‧奪日者。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24801 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24801, 'zhTW', '奪日者的勝利', '為了奪日者與部落的榮耀，奎爾德拉終於復原了!這對我們對抗巫妖王所付出的努力而言是一大賜福。$B$B等你從太陽之井歸還之後，奪日者的領袖大法師埃薩‧奪日者邀請你見他一面。帶著奎爾德拉儘快前往達拉然的紫羅蘭城塞，$n。大法師希望能夠親自恭賀你!', '到達拉然紫羅蘭城塞，把復原的奎爾德拉交給大法師埃薩‧奪日者。', '', '去達拉然的紫羅蘭城堡找大法師艾薩斯·奪日者。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24802 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24802, 'zhTW', '巫妖王之怒', '真是令人難以置信，在阿薩斯的王座上，我們或許有可能擊敗他。如果巫妖王真的被擊敗了，那麼誰又該成為下一個巫妖王呢?$B$B雖然局勢仍未明朗，不過你必須找到希瓦娜斯，即時逃離巫妖王的魔爪。', '找到希瓦娜斯‧風行者女士，逃離倒影大廳。', '', '', '尋找希爾瓦娜斯·風行者', '逃離巫妖王', '', '', 0);
