INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24815, 'zhTW', '擇你所向', '', '我曾經是巫妖王旗下忠貞不二的死亡騎士，為了洗刷罪孽，我決定奉獻自己的心力，為正在努力奮鬥的兄弟姐妹們，製作強而有力的戒指供他們使用。在對抗天譴軍團的戰鬥之中，你已經證明自己是價值非凡的盟友，$n。只要你持續貢獻心力，我就會改善戒指原本的能力。慎選你的道路。改變心意會讓你付出代價。', '', '', '', '', '', '', 0);
