INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24849, 'zhTW', '重要線索', '這故事最好從頭講起。$n，我對他一見鍾情。從我見到那位哥布林的那一刻開始就愛上他了。$B$B在一起度過甜蜜的一週之後，史尼佛說他收到了一大筆錢，並且要帶我去南海度個長假!你相信嗎? $B$B總而言之，他說他去銀行、拍賣場以及美髮沙龍辦事情的時候，要我先整理行李，但是他就再也沒回來過了!我開始覺得他只是一個大騙子!', '到暴風城的會計室、拍賣場以及美容沙龍，尋找史尼佛‧鏽彈的身影。', '', '去找暴風城的瑪莉恩‧蘇頓。', '已搜查暴風城稅務局', '已搜查暴風城拍賣行', '已搜查暴風城理髮店', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24851 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24851, 'zhTW', '重要線索', '這故事最好從頭講起。$n，我對他一見鍾情。從我見到那位哥布林的那一刻開始就愛上他了。$B$B在一起度過甜蜜的一週之後，史尼佛說他收到了一大筆錢，並且要帶我去南海度個長假！你相信嗎？ $B$B總而言之，他說他去銀行、拍賣場以及美髮沙龍辦事情的時候，要我先整理行李，但是他就再也沒回來過了！我開始覺得他只是一個大騙子！', '到奧格瑪力量谷的銀行、拍賣場以及美容沙龍，尋找史尼佛‧鏽彈的身影。', '', '去找奧格瑪的蘿卡。', '已搜查奧格瑪銀行', '已搜查奧格瑪拍賣行', '已搜查奧格瑪理髮店', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24869 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24869, 'zhTW', '改邪歸正', '我們為了窺探巫妖王的陰謀詭計，本來安置了一名內應在詛咒神教裡面，沒想到我們低估了阿薩斯以及他的暗黑大臣亡語女士的媚誘之力。$B$B我們的夥伴，達納凡，如今成了他們的一份子。$B$B如果你們打算往祈願室的方向進攻的話，請睜大眼睛找找達納凡。假使你能夠把他活著救回來，我們就能夠破除神教的洗腦控制。', '在確保達納凡存活的情況之下擊敗亡語女士。', '', '去找滲透者敏加。', '營救達拿凡', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24872 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24872, 'zhTW', '受苦靈魂的安息', '你跟你的同伴都帶著這個生命水晶。它內含了來自龍骨荒野的翠綠龍殿中強大的能量，而這也是我能夠長久抵抗此地黑暗魔法的獨家秘方。$B$B當你迎戰辛德拉苟莎的時候，一但她開始呈現虛弱的狀態，就讓你的夥伴們使用這些水晶來誘導出她體內的精華。如果你隨後擊敗了她就會獲得精華，接著就把它帶回到龍骨荒野的龍眠神殿交還。', '使用生命水晶來保存辛德拉苟莎的精華。', '', '將辛達苟薩的靈魂交給龍骨荒野中龍眠神殿的卡雷苟斯。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 24880 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24880, 'zhTW', '受苦靈魂的安息', '你跟你的同伴都帶著這個生命水晶。它內含了來自龍骨荒野的翠綠龍殿中強大的能量，而這也是我能夠長久抵抗此地黑暗魔法的獨家秘方。$B$B當你迎戰辛德拉苟莎的時候，一但她開始呈現虛弱的狀態，就讓你的夥伴們使用這些水晶來誘導出她體內的精華。如果你隨後擊敗了她就會獲得精華，接著就把它帶回到龍骨荒野的龍眠神殿交還。', '使用生命水晶來保存辛德拉苟莎的精華。', '', '將辛達苟薩的靈魂交給龍骨荒野中龍眠神殿的卡雷苟斯。', '', '', '', '', 0);
