INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (24914, 'zhTW', '私人財產', '你在這個盒子上找不到機關或縫隙。如果不是裡面有東西在晃動，很容易就把它錯認為一整塊固體金屬。$B$B如果說有人知道開啟它的方法的話，那非大領主莫格萊尼莫屬了。', '把密封的箱子帶給在冰冠城塞的大領主達瑞安‧莫格萊尼。', '', '', '', '', '', '', 0);
