INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25055, 'zhTW', '制伏元素', '$c，元素的動盪永不會止歇。正在危害這片土地，甚至可能摧毀鐵爐堡的地震並不尋常。大地之環相信，我們必須在元素徹底撕裂艾澤拉斯之前讓它們恢復平靜。我們需要你的幫助，$n。$B$B我會給你一口袋大地之環的補給品。你能在其中找到兩件物品——元素靈契和淨化圖騰。你可以用靈契看到元素世界。然後你就要使用淨化圖騰制服躁動的大地之魂。', '加文·灰羽要你使用大地之環補給品中的元素靈契和淨化圖騰，制服20個激動的大地之魂。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25092 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25092, 'zhTW', '制伏元素', '$c，元素的动荡永不会止歇。正在危害这片土地的地震和随时可能烧毁奥格瑞玛的大火并不寻常。大地之环相信，我们必须在元素彻底撕裂艾泽拉斯之前让它们恢复平静。我们需要你的帮助，$n。$B$B我会给你一口袋大地之环的补给品。你能在其中找到两件物品——元素灵契和净化图腾。你可以用灵契看到元素世界。然后你就要使用净化图腾制服躁动的火焰之魂。', '先知巴胡拉要你使用大地之环补给品中的元素灵契和净化图腾，制服20个激动的火焰之魂。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25180 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25180, 'zhTW', '大地石板', '不久前，布萊恩從奧杜亞給麥格尼國王發了一則緊急訊息。他說他發現了一個古老的泰坦寶箱，裡頭裝著神秘難解的重要聖物。烏瑞恩王派出他手下最快的船前往北裂境將信差送來。我本該在這裡和他碰面並檢驗那些碑文的，但不管在哪都看不見信差的身影。$B$B麥格尼國王還蠻擔心的，$n。信差到現在都還沒有消息。你願不願意去暴風港看看他到底來了沒？', '將大地石板交給鐵爐堡的顧問貝爾格拉姆。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25181 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25181, 'zhTW', '火焰石板', '我正在等候一位從北裂境過來的信差，他身上帶著古老的泰坦寶藏，這些寶藏能撥開烏雲、為我看見的那擾人光景射入陽光。這名薩滿應該要跟最近的飛艇航班一起抵達的，這讓我開始擔心是不是出了什麼問題。$B$B他應該要在奧格瑪大門西南方的飛艇塔和我碰面，不過我不想錯過和大酋長間的會晤機會。你願不願意幫我去看看，那名信差到底是被什麼給耽擱了？', '將火焰石板交給奧格瑪的大地治癒者諾爾莎拉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25212 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25212, 'zhTW', '通風地平線', '我們原本以為可以慢慢等諾姆瑞根周圍的輻射散去，不過情況看起來越來越糟。$B$B想要奪回我們的城市，先得確定我們的部隊能安全地走進去。$B$B帶著這些輻射測量器，跳上這邊這台『閃雷』號，然後把測量器丟進諾姆瑞根外部的通風孔裡頭。測量器會直接將輻射等級資料回傳到我這來。', '搭乘駕駛員摩卓普拉克的飛行器，將輻射測量器丟進諾姆瑞根周圍的通風口中。', '', '去找駕駛員摩卓普拉克談話。', '輻射測量器', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25228 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25228, 'zhTW', '災難預言', '奧格瑪的街道上出現了一幫傢伙，他們滿嘴都是災難即將降臨的蠢話。這在奧格瑪本不算什麼新鮮事。但這幫傢伙卻讓我相當擔憂。他們的行動很有組織性。暗巷區的許多人都受到了他們的影響。他們的勢力在那裡發展得相當迅速。$B$B我考慮過將他們剿除，或者制止他們的活動。但貿然行動只會讓他們轉入地下。我們需要對他們有更多瞭解。你能不能到暗巷區去，聽聽那些末日預言者都在傳播些什麼？你最好能找到一些與他們的理念相關的文字情報。', '在暗巷區聽取一名末日預言者的演講，並取得名為《靈魂之元素火焰》、《萬物的終結對我有何意義？》和《在毀滅的世界中尋找安全與舒適》的小冊子。', '', '回到奧格瑪的力量谷向血衛士托雷克回報。', '聽聽末日預言者的演說', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25229 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25229, 'zhTW', '好地精寥寥', '我們的工程師正在為進攻諾姆瑞根而日夜不停地裝配我們的戰爭機械，但我們現在極端缺乏駕駛員！$B$B我們的工程師開發出一種名叫激勵儀的裝置。它能夠吸引地精們的注意力，並讓他們有勇氣響應我們的徵兵號令。$B$B用它鼓舞起幾名地精平民的勇氣，然後帶領他們去見鐵爐堡南邊，鋼架補給站的崔德·火鑽隊長。$B$B一定要小心。這個裝置還有些不太成熟。', '使用激勵儀，在地精區徵募地精，並率領他們返回鋼架補給站，去見崔德·火鑽隊長。', '', '跟鋼架補給站的特瑞德‧炫鼻上尉談談。', '應徵的地精', '帶著受激勵的地精交給斯巴克諾茲船長', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25238 AND `locale` = 'zhTW';
