INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25253, 'zhTW', '末日預言', '末日先驅走在暴風城的街道上，這已經不是什麼稀奇的事情了，不過最近出現的這群人讓我蠻擔心的。這些傢伙是有組織性的，在舊城區吸引了大批群眾目光，那邊似乎也是他們的集會場所。$B$B我想做點什麼，像是一口氣把他們包圍起來，或是打斷他們的活動之類的，不過這只會驅使他們躲在暗處偷偷活動。我們得找出更多的同黨。你願不願意去趟舊城區?去聽聽看末日預言者們到底在散佈些怎樣的訊息，盡量多收集一些關於他們理念的文宣品帶回來給我。', '到舊城區聽聽末日預言者的演說，並且取得《靈魂所需的那把元素之火》、《「世界末日」對我來說代表什麼?》、《在註定毀滅的世界中找尋安全與寬慰》這幾份文宣。', '', '返回暴風城的貿易區，去找安頓上尉。', '聽聽末日預言者的演說', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25254 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25254, 'zhTW', '及時的標記', '我們要採取行動，讓公眾對那個預言毀滅的教派失去興趣。但在我瞭解這個組織的幕後操控者之前，我很難決定該如何對這個組織下手。$B$B我已經讓我的部下在奧格瑪行人最密集的地方做好了標記。帶上這些佈告，把它們張貼在有這種標記的地方。它們對於那些下定決心的追隨者們不會有多大作用。但它畢竟是揭露這個教派邪惡面的第一步。部落的敵人已經很多了。所以我們現在更不能任由這些傢伙四處散佈謊言。', '在力量穀、暗巷區或者榮譽穀各處張貼5張報警佈告。', '', '返回奧格瑪的力量穀，去找血衛士托雷克。', '告示設置完畢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25282 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25282, 'zhTW', '及時的標記', '我們要採取行動，讓公眾對那個預言毀滅的教派失去興趣。但在我瞭解這個組織的幕後操控者之前，我很難決定該如何對這個組織下手。$B$B我已經讓我的部下在暴風城行人最密集的地方做好了標記。帶上這些佈告，把它們張貼在有這種標記的地方。它們對於那些下定決心的追隨者們不會有多大作用。但它畢竟是揭露這個教派邪惡面的第一步。國王已經有夠多敵人了，不需要連自己的子民都背叛他。', '在暴風城的貿易區、法師區或座堂區張貼5張報警佈告。', '', '去找暴風城的貿易區的安東上尉。', '已張貼海報', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25283 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25283, 'zhTW', '研擬講稿', '高等技工梅卡托克要我寫篇講稿，他要在開戰前發表一場演說，不過我分辨不出哪篇是好哪篇是壞。$B$B你想，你能不能幫我試一下，看看本地地精居民的反應？這裝置會投射出國王梅卡托克的影像，然後從每篇中挑幾句念出來。$B$B讓我知道哪篇比較好，沒問題吧？', '對卡拉諾斯西邊的奧齊‧電環、鋼架補給站的米利‧羽哨、以及卡拉諾斯旅店外面的托格‧鏽鏈使用地精播放裝置。試過所有講稿之後，回去向托比‧柴吉爾回報。', '', '返回鋼架補給站，去見託比·速輪。', '對奧齊·電環發表演說', '對米利·羽哨發表演說', '對托格·銹鏈發表演說', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25285 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25285, 'zhTW', '進進出出', '新的機械坦克已經整備完畢，隨時可以發動攻擊。你準備好要來看看這些狠角色的能耐嗎?!喔你當然準備好了!$B$B首先呢我們要確定的是，你進去之後有辦法出來。在戰鬥中，如果你覺得坦克快要爆炸了，先逃出來再說!我看過許多地精留在裡面的下場...坦克爆炸開來，那些地精也跟著爆開來。$B$B來吧，我已經幫這台坦克添加了彈射座椅的升級。幫我測試一下，好嗎?', '測試彈射用機械坦克上的彈射系統。', '', '讓崔德·火鑽隊長知道你順利地使用了彈射系統。', '彈射系統測試完畢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25286, 'zhTW', '演說稿', '來吧，演說稿在這，$n!$B$B以一場戰爭的開場白來說，這篇演說稿該有的都有了:以動人的語言直接向地精們演說，這能大大地激勵人心。從來從沒有人寫出如此完美的演說稿!$B$B回到特瑞德‧炫鼻上尉那，將這篇稿子送去給高等技工梅卡托克!', '將演說稿交給鋼架補給站的特瑞德‧炫鼻上尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25287 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25287, 'zhTW', '演說稿', '好了士兵，現在是證明你自身價值的時刻了!$B$B帶著演說稿、搭上我身旁這台飛行器『閃雷』。要去見高等技工梅卡托克，這艘是最快速的飛船了，他現在在等的就是這篇演說稿。$B$B快出發!現在出發!', '在鋼架補給站搭乘飛行器『閃雷』去見高等技工梅卡托克，然後把托比的演說稿交給他。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25288 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25288, 'zhTW', '滲透行動', '關於那個奇怪教派的傳聞正在奧格瑪的街巷間四處流傳。但對於它的來源和所作所為，卻沒有人清楚。$N，現在只有一個辦法能夠查清楚這群傢伙的底細。你要去加入他們。$B$B在暗巷區找到一個末日預言者，告訴他你想要入夥。如果你的運氣好，他們會把你引薦給他們的一個領導人，然後你就能知道他們的藏身之地了。你要穿上末日預言者給你的衣服，這樣你才能進入他們的秘密據點。', '同奧格瑪暗巷區的一名末日預言者交談，加入他們的教派，然後穿上信徒長袍。', '', '到奧格瑪外面的野豬農場找監督者金塔克。', '加入末日教派', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25290 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25290, 'zhTW', '滲透行動', '現在已經很難讓這個奇怪教派遠離公眾視野了。關於他們的謠言已經傳遍了全城。我想讓你加入那個教派，儘量從他們中間獲取情報。$B$B在舊城區找到一個末日預言者，告訴他，你想要加入他們。那個末日預言者很可能會給你一件他們的制服，並讓你去他們的秘密據點，結識其它教徒。$N，按照他的指示去做。這是取得他們信任的唯一方法。', '與暴風城舊城區中的一名末日預言者交談並加入末日教，然後穿上他給你的末日教派新兵長袍。', '', '轉至明鏡湖果園，向先知席蘭德拉報到。', '加入末日教派', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25293 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25293, 'zhTW', '失蹤人口', '除了那個神秘教派在城市中散佈的混亂和猜疑之外，我們還收到了無數關於失蹤人口的報告。人們的母親、父親、兄弟姐妹都在無緣無故地消失。我有一種感覺，這些失蹤的人可能都在那個教派位於城外的某個基地中。如果我給你一些失蹤者的名字，你是否能在那個教派的一座營地中找到他們？那座營地就在奧格瑪南邊的野豬農場。如果你要進入那座營地，首先要從暗巷區的末日預言者手中得到一件信徒長袍。', '穿上教派偽裝，同杜洛塔野豬農場中的教徒卡加恩、教徒艾格塔、教徒托卡和教徒洛卡迦交談。', '', '到奧格瑪找血衛士托雷克。', '和教徒卡嘎恩交談。', '和教徒阿格塔交談。', '和教徒托卡交談。', '和教徒羅卡嘎交談。', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25295 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25295, 'zhTW', '開火', '安全系統已連線!發動機功能運作正常!現在我們需要的只剩確認槍械是否可以正常射擊。$B$B我想這應該不會太難，$n。背後那座山丘上有台機械坦克，上頭的子彈沒有殺傷力。只要朝附近的靶子射個幾發，然後向我回報就可以了。', '利用附近的標的物來測試射擊用機械坦克的武器系統。', '', '向崔德·火鑽隊長報告你的結果。', '武器系統測試完畢', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25306, 'zhTW', '你現在入伍啦!', '', '[ph] Log Description。', '', '', '彈射系統已測試', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25343 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25343, 'zhTW', '主謀的計畫', '你在這裡適應得很好，$N，但是我們不只是每天做雜務和散布訊息而已。我相信你剛加入我們的時候就已經聽說過一些了。$B$B你知道的，這個世界即將終結，而沒有準備的人將會痛苦地死去。$B$B我們被賜予了一份禮物，一個成為更偉大、更強大的存在的機會。監督者戈爾巴茲即將在農場東側的祭壇前準備一場儀式。在那裡等他，好好認識你的新兄弟姐妹們。', '在野豬農場東側的祭壇瞭解教派更多的計畫。', '', '去找監督者金塔克。', '丘加利的啟示', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25347 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25347, 'zhTW', '末日計畫', '第一批元素裝置已經準備就緒。你的任務是把它們藏進奧格瑪城裡。這些裝置會在適當的時機釋放出火元素。別擔心，$N，在那之前你早就已經安全撤離了。$B$B千萬別做出任何會引起注意的事。$B$B<監督者交給你一個裝有數個元素裝置的包裹。這正是血衛士托雷克希望你找到的證據。你應該把這些裝置帶去給他。>', '把元素裝置帶去給奧格瑪力量谷的血衛士托雷克。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25348 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25348, 'zhTW', '挫敗暮光之錘', '被派進奧格瑪安置那些裝有火元素的裝置的人，不會只有你一個。我們必須在他們放出被囚禁的火元素、燒毀整座城市之前，找到並且拆除其餘的裝置。$B$B你對這些裝置夠瞭解，能把它們摧毀嗎？你得趕在裡面的火元素恢復全部力量之前就打開它們。如果你及早打開裝置，牠們應該不難對付。教徒們很可能已經把裝置藏遍了整座城市。', '打破元素裝置以釋放其中的元素。你必須擊敗5個狂怒的火元素。', '', '去找奧格瑪的力量谷的血衛士托雷克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25351 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25351, 'zhTW', '警告大酋長', '你已經成功保衛了奧格瑪，抵禦了暮光之錘教派帶來的威脅，$N，而且沒有讓我們自己人流血。我們的敵人不會休息太久。我無法想像丘加利會輕易接受這次的失敗。$B$B你必須把消息告訴索爾。前往智慧谷，在格羅瑪什要塞裡與他談話。告訴大酋長，我們的敵人已經現身，我們必須為他們的再次來襲做好準備。', '在奧格瑪智慧谷的格羅瑪什要塞與索爾談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25380 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25380, 'zhTW', '廣為傳播', '歡迎來到農場，$N。這裡的每個人都得自食其力。對某些人來說，這代表著要照顧動物。其他人則負責我們的建設工程。還有些人負責向人們傳播我們的訊息，我想這是最適合你開始的地方。$B$B拿著這塊木牌。上面簡短地寫著我們的信仰。戴著這塊木牌，前往奧格瑪大門外的東方飛艇塔和西方飛艇塔，以及南邊的剃刀嶺城鎮廣場。', '戴著你的末日訊息木牌，前往東方飛艇塔、西方飛艇塔，以及剃刀嶺的城鎮廣場。', '', '去找監督者金塔克。', '在東方飛艇塔散布訊息', '在西方飛艇塔散布訊息', '在剃刀嶺散布訊息', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25414 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25414, 'zhTW', '失蹤人口', '這個教派已經不只是散播恐懼和偏執了。現在，我開始收到人口失蹤的報告。母親、父親、兄弟姐妹們似乎都憑空消失了，但我有種預感，他們可能被關在城外某個教派的營地裡。如果我把幾位失蹤者的名字給你，你願不願意到明鏡湖果園的教徒營地裡找找看？那裡就在城門的西南方。要融入他們，你需要加入教派，並向舊城區的某位末日預言者要一件長袍。', '穿著你的末日教派新兵長袍，同艾爾文森林明鏡湖果園的異教徒萊瑟琳、異教徒凱瑪、異教徒懷曼和異教徒歐倫恩交談。', '', '', '與異教徒萊瑟琳交談', '與異教徒凱瑪交談', '與異教徒懷曼交談', '與異教徒歐倫恩交談', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25415 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25415, 'zhTW', '廣為傳播', '$N，歡迎來到我們的果園。這裡的每個人都在勤奮工作。其中一些人的工作是照料果樹，另一些則致力於實現我們的目標，還有一些人的任務是在人群中傳播我們的資訊。我相信，這將是適合於你的工作。$B$B帶上這塊板子。它上面用簡潔的語言寫明瞭我們的信仰。你要帶著它轉至西南方的西泉要塞；東邊的閃金鎮和暴風城的英雄谷。', '帶著末日資訊轉至西泉要塞、暴風城的英雄谷和閃金鎮的城鎮廣場。', '', '轉至明鏡湖果園，去找先知席蘭德拉。', '在西泉要塞傳播資訊', '在英雄谷傳播資訊', '在閃金鎮傳播資訊', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25416 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25416, 'zhTW', '主謀的計畫', '你在這裡適應得很好，$N，但是我們不只是每天做雜務和散布訊息而已。我相信你剛加入我們的時候就已經聽說過一些了。$B$B你知道的，這個世界即將終結，而沒有準備的人將會痛苦地死去。$B$B我們被賜予了一份禮物，一個成為更偉大、更強大的存在的機會。監督者塔拉索爾正在果園北側的祭壇準備一場儀式。在那裡等他，好好認識你的新兄弟姐妹們。', '在明鏡湖果園北側的祭壇瞭解教派更多的計畫。', '', '去找監督者賽倫德拉。', '丘加利的啟示', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25417 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25417, 'zhTW', '末日計畫', '第一批元素裝置已經準備就緒。你的任務是把它們藏進暴風城人口密集的區域。這些裝置會在適當的時機釋放出元素。別擔心，$N，在那之前你早就已經安全撤離了。$B$B千萬別做出任何會引起注意的事。$B$B<監督者交給你一個裝有數個元素裝置的包裹。這正是安東上尉希望你找到的證據。你應該把這些裝置帶去給他。>', '把元素裝置帶去給暴風城貿易區的安東上尉。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25418 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25418, 'zhTW', '挫敗暮光之錘', '被派進暴風城安置那些裝有風元素的裝置的人，不會只有你一個。我們必須在他們放出被囚禁的元素、在城裡掀起風暴之前，找到並且拆除其餘的裝置。$B$B你對這些裝置夠瞭解，能把它們摧毀嗎？我們最好的機會就是趕在裡面的元素恢復全部力量之前打開裝置。到貿易區、座堂廣場和法師區去找找看那些裝置。快點！', '摧毀元素裝置以釋放其中被囚禁的元素。擊敗5個狂怒的風元素。', '', '去找暴風城的貿易區的安東上尉。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25425 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25425, 'zhTW', '警告瓦里安國王', '你已經成功保衛了暴風城，抵禦了暮光之錘教派帶來的威脅，$N，而且沒有傷害到我們自己的市民。我們的敵人不會休息太久。事實上，丘加利肯定已經在忙著策劃他的下一步行動了。$B$B你必須把消息告訴瓦里安·烏瑞恩國王。直接前往暴風城堡的王座廳找他。告訴國王，我們的敵人已經現身，我們必須為他們的再次來襲做好準備。', '在暴風城堡與瓦里安·烏瑞恩國王談話。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25444 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25444, 'zhTW', '完美間諜', '一無所知地走進去實在是很蠢很蠢，所以我要製造一些小小間諜，送進去幫沃金收集情報，他想知道島上發生的事情。$B$B如果你願意的話，來幫我個忙。我跟你說要怎麼做。你先到森金村附近的樹蔭下抓幾隻青蛙。$B$B抓到之後，帶到我的崗哨圖騰那邊，讓我的視覺和青蛙進行視覺同調。', '捕捉5隻森金蛙，在凡妮拉的崗哨圖騰讓凡妮拉和捕捉到的青蛙進行視覺同調。', '', '去找凡妮拉。', '', '森金青蛙已調校', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25446 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25446, 'zhTW', '起飛！放蛙！', '青蛙準備好了，接下來我需要你幫我把青蛙送到島上去。$B$B去森金村的東面找蝙蝠管理員馬恩雷克，他幫沃金管理著手下斥候要用的蝙蝠，他可以借你一隻蝙蝠，讓你飛去島上。$B$B帶著這袋青蛙。我已經請求聖靈給予指引。聖靈會用煙指引你，最需要在哪些地方放置耳目。在蝙蝠上的時候，從袋子中把青蛙丟到白色煙幕的位置。', '在騎乘蝙蝠的狀態下，使用青蛙袋在回音群島的標記地點上面放置12隻同調蛙。', '', '去找森金村的凡妮拉。', '青蛙袋', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25461 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25461, 'zhTW', '搜尋志願者', '沃金把他的戰鼓交給了我，讓我在這負責訓練新人。唯一的問題是，沒什麼新人可以讓我訓練。$B$B我在想，我可以把他的鼓借給你用一用，你去剃刀嶺以沃金之名敲擊戰鼓，可以吧？就算只有幾名食人妖受到感召願意加入這次行動，也會使狀況不一樣的。你說服新人加入之後，把他們帶回來接受訓練。去南邊和蝙蝠管理員馬恩雷克交談，他會借你一隻蝙蝠，讓你飛去剃刀嶺。', '在剃刀嶺使用沃金的戰鼓召集5名食人妖居民。和蝙蝠管理員馬恩雷克交談，要求他派蝙蝠送你去剃刀嶺。', '', '去找森金村的勇士烏魯辛。', '沃金的戰鼓', '巨魔志願者已交給勇士烏爾金', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25482 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25482, 'zhTW', '地下城世界事件 - 無頭騎士', '', '', '', '', '', '', '', '', 0);
