DELETE FROM `quest_template_locale` WHERE `ID` = 25485 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25485, 'zhTW', '地下城世界事件 - 漢摩爾', '', '', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25495 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25495, 'zhTW', '開戰準備', '沃金正在整裝，讓戰士們做好準備。他要我叫你去東邊的島上與他和凡妮拉碰面。$B$B他和他的戰士們會從那裡對札拉贊恩發動攻擊。$n，願先祖與你同在。如果不是因為你，這場戰役只會沉睡在陰影之中。和蝙蝠管理員馬恩雷克談談，他就在南邊，他會派隻蝙蝠載你去集結區域。', '和蝙蝠管理員馬恩雷克交談以前往集結區域。在戰爭營地東邊的島上和沃金碰面。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 25500 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (25500, 'zhTW', '遞送演講稿', '好哇，$N，演講稿完成了！它能夠為所有偉大的戰爭作序言……它鼓舞人心，雄辯無礙，能夠為地精們清晰地指明方向。再也沒有比這個更優秀的演講稿了！$B$B把這份演講稿交給崔德·火鑽隊長，看看他還需要你做些什麼。', '將演講稿交給鋼架補給站的崔德·火鑽隊長。', '', '將演講稿交給高等技工梅卡托克。', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 26012 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (26012, 'zhTW', '龍眠神殿的麻煩', '我的老朋友卡薩斯傳來了消息，龍骨荒野的龍眠神殿發生了可怕的事情。他的信息十分簡短，但是看起來神殿下方的晶紅聖所受到了某種攻擊。$B$B在達拉然的要事使我無法親自前往那裡，但是我聽說你在巫妖王的城塞中表現出色，所以你無疑是能解決事情的人選 -- 也許你可以替我幫助卡薩斯?', '到龍骨荒野的龍眠神殿找卡薩斯談談。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 26013 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (26013, 'zhTW', '對聖所的攻擊', '$r，神殿下方的晶紅聖所發生了可怕的事情。$B$B聖所的大門已成廢墟，而它的守護者被殘忍地殺死了。我們派出了斥候進行調查，但是他們都沒有回來。我無法不去想像最糟的情況。$B$B進入晶紅聖所，找出我的家園到底發生了什麼事情。有了進一步的資訊，我們才能夠藉此計畫我們的下一步。', '調查龍眠神殿下的晶紅神殿。', '', '', '', '', '', '', 0);
DELETE FROM `quest_template_locale` WHERE `ID` = 26034 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (26034, 'zhTW', '暮光毀滅者', '這次進攻並非有勇無謀的行動，而是一次針對紅龍軍團經過精心策劃、直搗黃龍的謹慎行動。$B$B扎里斯利安，在那個崖地上監督著這次的進攻，但是這個軍團的真正領袖是一頭既兇猛又強大的暮光龍，名叫海萊恩。除了達貢納克斯，賽絲特拉的那些扭曲實驗品還沒有誰能完全成長到這種程度。$B$B殺死牠，$n，等到這次的入侵被完全擊退後，向卡薩斯回報你在這裡見到的所有一切。', '擊敗海萊恩並擊退對晶紅聖所的入侵。', '', '', '', '', '', '', 0);
